INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'En la komenco Dio kreis la ĉielon kaj la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Kaj la tero estis senforma kaj dezerta, kaj mallumo estis super la abismo; kaj la spirito de Dio ŝvebis super la akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Kaj Dio diris: Estu lumo; kaj fariĝis lumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Kaj Dio vidis la lumon, ke ĝi estas bona; kaj Dio apartigis la lumon de la mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Kaj Dio nomis la lumon Tago, kaj la mallumon Li nomis Nokto. Kaj estis vespero, kaj estis mateno, unu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Kaj Dio diris: Estu firmaĵo inter la akvo, kaj ĝi apartigu akvon de akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Kaj Dio kreis la firmaĵon, kaj apartigis la akvon, kiu estas sub la firmaĵo, de la akvo, kiu estas super la firmaĵo; kaj fariĝis tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Kaj Dio nomis la firmaĵon Ĉielo. Kaj estis vespero, kaj estis mateno, la dua tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Kaj Dio diris: Kolektiĝu la akvo de sub la ĉielo en unu lokon, kaj aperu la sekaĵo; kaj fariĝis tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Kaj Dio nomis la sekaĵon Tero, kaj la kolektiĝojn de la akvo Li nomis Maroj. Kaj Dio vidis, ke ĝi estas bona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Kaj Dio diris: Kreskigu la tero verdaĵon, herbon, kiu naskas semon, fruktarbon, kiu donas laŭ sia speco frukton, kies semo estas en ĝi mem, sur la tero; kaj fariĝis tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Kaj la tero elkreskigis verdaĵon, herbon, kiu naskas semon laŭ sia speco, kaj arbon, kiu donas frukton, kies semo estas en ĝi mem laŭ sia speco. Kaj Dio vidis, ke ĝi estas bona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Kaj estis vespero, kaj estis mateno, la tria tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Kaj Dio diris: Estu lumaĵoj en la ĉiela firmaĵo, por apartigi la tagon de la nokto, kaj ili prezentu signojn, tempojn, tagojn, kaj jarojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'kaj ili estu lumaĵoj en la ĉiela firmaĵo, por lumi super la tero; kaj fariĝis tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Kaj Dio faris la du grandajn lumaĵojn: la pli grandan lumaĵon, por regi la tagon, kaj la malpli grandan lumaĵon, por regi la nokton, kaj la stelojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Kaj Dio starigis ilin sur la ĉiela firmaĵo, por ke ili lumu sur la teron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'kaj por ke ili regu la tagon kaj la nokton kaj faru diferencon inter la lumo kaj la mallumo. Kaj Dio vidis, ke ĝi estas bona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Kaj estis vespero, kaj estis mateno, la kvara tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Kaj Dio diris: La akvo aperigu moviĝantaĵojn, vivajn estaĵojn, kaj birdoj ekflugu super la tero, sub la ĉiela firmaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Kaj Dio kreis la grandajn balenojn, kaj ĉiujn vivajn estaĵojn moviĝantajn, kiujn aperigis la akvo, laŭ ilia speco, kaj ĉiujn flugilhavajn birdojn laŭ ilia speco. Kaj Dio vidis, ke ĝi estas bona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Kaj Dio ilin benis, dirante: Fruktu kaj multiĝu, kaj plenigu la akvon en la maroj, kaj la birdoj multiĝu sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Kaj estis vespero, kaj estis mateno, la kvina tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Kaj Dio diris: La tero aperigu vivajn estaĵojn, laŭ ilia speco, brutojn kaj rampaĵojn kaj surterajn bestojn, laŭ ilia speco; kaj fariĝis tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Kaj Dio kreis la bestojn de la tero, laŭ ilia speco, kaj la brutojn, laŭ ilia speco, kaj ĉiujn rampaĵojn de la tero, laŭ ilia speco. Kaj Dio vidis, ke ĝi estas bona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Kaj Dio diris: Ni kreu homon laŭ Nia bildo, similan al Ni; kaj ili regu super la fiŝoj de la maro kaj super la birdoj de la ĉielo kaj super la brutoj, kaj super ĉiuj rampaĵoj, kiuj rampas sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Kaj Dio kreis la homon laŭ Sia bildo, laŭ la bildo de Dio Li kreis lin; en formo de viro kaj virino Li kreis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Kaj Dio benis ilin, kaj Dio diris al ili: Fruktu kaj multiĝu, kaj plenigu la teron kaj submetu ĝin al vi, kaj regu super la fiŝoj de la maro kaj super la birdoj de la ĉielo, kaj super ĉiuj bestoj, kiuj moviĝas sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Kaj Dio diris: Jen Mi donis al vi ĉiujn herbojn, kiuj semas semon, kiuj troviĝas sur la tuta tero, kaj ĉiujn arbojn, kiuj havas en si arban frukton, kiu semas semon; tio estu por vi manĝaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Kaj al ĉiuj bestoj de la tero kaj al ĉiuj birdoj de la ĉielo kaj al ĉiuj rampaĵoj sur la tero, kiuj havas en si vivan animon, la tutan verdan herbaĵon kiel manĝaĵon. Kaj fariĝis tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Kaj Dio rigardis ĉion, kion Li kreis, kaj vidis, ke ĝi estas tre bona. Kaj estis vespero, kaj estis mateno, la sesa tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Kaj estis finitaj la ĉielo kaj la tero kaj ĉiuj iliaj apartenaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Kaj Dio finis en la sepa tago Sian laboron, kiun Li faris, kaj Li ripozis en la sepa tago de la tuta laboro, kiun Li faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Kaj Dio benis la sepan tagon kaj sanktigis ĝin, ĉar en ĝi Li ripozis de Sia tuta laboro, kiun Li faris kreante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Tia estas la naskiĝo de la ĉielo kaj la tero, kiam ili estis kreitaj, kiam Dio la Eternulo faris la teron kaj la ĉielon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'Kaj nenia kampa arbetaĵo ankoraŭ estis sur la tero, kaj nenia kampa herbo ankoraŭ kreskis, ĉar Dio la Eternulo ne pluvigis sur la teron, kaj ne ekzistis homo, por prilabori la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Sed nebulo leviĝadis de la tero kaj donadis malsekecon al la tuta supraĵo de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Kaj Dio la Eternulo kreis la homon el polvo de la tero, kaj Li enblovis en lian nazon spiron de vivo, kaj la homo fariĝis viva animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Kaj Dio la Eternulo plantis ĝardenon en Eden en la Oriento, kaj Li metis tien la homon, kiun Li kreis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Kaj Dio la Eternulo elkreskigis el la tero ĉiun arbon ĉarman por la vido kaj bonan por la manĝo, kaj la arbon de vivo en la mezo de la ĝardeno, kaj la arbon de sciado pri bono kaj malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Kaj rivero eliras el Eden, por akvoprovizi la ĝardenon, kaj de tie ĝi dividiĝas kaj fariĝas kvar ĉefpartoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'La nomo de unu estas Piŝon; ĝi estas tiu, kiu ĉirkaŭas la tutan landon Ĥavila, kie estas la oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Kaj la oro de tiu lando estas bona; tie troviĝas bedelio kaj la ŝtono onikso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Kaj la nomo de la dua rivero estas Giĥon; ĝi estas tiu, kiu ĉirkaŭas la tutan landon Etiopujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Kaj la nomo de la tria rivero estas Ĥidekel; ĝi estas tiu, kiu fluas antaŭ Asirio. Kaj la kvara rivero estas Eŭfrato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Kaj Dio la Eternulo prenis la homon kaj enloĝigis lin en la ĝardeno Edena, por ke li prilaboradu ĝin kaj gardu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Kaj Dio la Eternulo ordonis al la homo, dirante: De ĉiu arbo de la ĝardeno vi manĝu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'sed de la arbo de sciado pri bono kaj malbono vi ne manĝu, ĉar en la tago, en kiu vi manĝos de ĝi, vi mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Kaj Dio la Eternulo diris: Ne estas bone, ke la homo estu sola; Mi kreos al li helpanton similan al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Kaj Dio la Eternulo kreis el la tero ĉiujn bestojn de la kampo kaj ĉiujn birdojn de la ĉielo, kaj venigis ilin al la homo, por vidi, kiel li nomos ilin; kaj kiel la homo nomis ĉiun vivan estaĵon, tiel restis ĝia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Kaj la homo donis nomojn al ĉiuj brutoj kaj al la birdoj de la ĉielo kaj al ĉiuj bestoj de la kampo; sed por la homo ne troviĝis helpanto simila al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Kaj Dio la Eternulo faligis profundan dormon sur la homon, kaj ĉi tiu endormiĝis; kaj Li prenis unu el liaj ripoj kaj fermis la lokon per karno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Kaj Dio la Eternulo konstruis el la ripo, kiun Li prenis de la homo, virinon, kaj Li venigis ŝin al la homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Kaj la homo diris: Jen nun ŝi estas osto el miaj ostoj kaj karno el mia karno; ŝi estu nomata Virino, ĉar el Viro ŝi estas prenita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Tial viro forlasos sian patron kaj sian patrinon, kaj aliĝos al sia edzino, kaj ili estos unu karno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Kaj ili ambaŭ estis nudaj, la homo kaj lia edzino, kaj ili ne hontis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Kaj la serpento estis pli ruza, ol ĉiuj kampaj bestoj, kiujn kreis Dio la Eternulo. Kaj ĝi diris al la virino: Ĉu Dio diris, ke vi ne manĝu de ĉiuj arboj de la ĝardeno?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Kaj la virino diris al la serpento: La fruktojn de la arboj de la ĝardeno ni povas manĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'sed pri la fruktoj de la arbo, kiu estas en la mezo de la ĝardeno, Dio diris: Ne manĝu ion de ili kaj ne tuŝu ilin, por ke vi ne mortu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Kaj la serpento diris al la virino: Ne, vi ne mortos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'sed Dio scias, ke en la tago, en kiu vi manĝos ion de ili, malfermiĝos viaj okuloj kaj vi estos kiel Dio, vi scios bonon kaj malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Kaj la virino vidis, ke la arbo estas bona por manĝi kaj ĝi estas ĉarma por la okuloj, kaj la arbo estas dezirinda por saĝiĝi; kaj ŝi prenis de ĝiaj fruktoj, kaj ŝi manĝis, kaj ŝi donis kune ankaŭ al sia edzo, kaj li manĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Kaj malfermiĝis la okuloj de ili ambaŭ, kaj ili sciiĝis, ke ili estas nudaj; kaj ili kunkudris foliojn de figarbo kaj faris al si zonaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Kaj ili aŭdis la voĉon de Dio la Eternulo, kiu marŝis en la ĝardeno dum la malvarmeto de la tago; kaj Adam kaj lia edzino kaŝiĝis de Dio la Eternulo inter la arboj de la ĝardeno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Kaj Dio la Eternulo vokis Adamon, kaj diris al li: Kie vi estas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Kaj tiu diris: Vian voĉon mi aŭdis en la ĝardeno, kaj mi ektimis, ĉar mi estas nuda; kaj mi kaŝis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Kaj Dio diris: Kiu diris al vi, ke vi estas nuda? ĉu vi ne manĝis de la arbo, pri kiu Mi ordonis al vi, ke vi ne manĝu de ĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Kaj Adam diris: La edzino, kiun Vi donis al mi kiel kunulinon, ŝi donis al mi de la arbo, kaj mi manĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Kaj Dio la Eternulo diris al la virino: Kial vi tion faris? Kaj la virino diris: La serpento tromplogis min, kaj mi manĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Kaj Dio la Eternulo diris al la serpento: Ĉar vi tion faris, tial estu malbenita inter ĉiuj brutoj kaj inter ĉiuj bestoj de la kampo; sur via ventro vi irados kaj teron vi manĝados dum via tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Kaj Mi metos malamikecon inter vi kaj la virino kaj inter via idaro kaj ŝia idaro; ĝi frapados vian kapon, kaj vi pikados ĝian kalkanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Al la virino Li diris: Mi multigos viajn suferojn dum via gravedeco; en doloro vi naskados infanojn; kaj al via viro vi vin tiros, kaj li regos super vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Kaj al Adam Li diris: Ĉar vi obeis la voĉon de via edzino, kaj vi manĝis de la arbo, pri kiu Mi ordonis al vi, dirante, ke vi ne manĝu de ĝi, tial malbenita estu la tero pro vi; kun suferoj vi manĝados de ĝi dum via tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Kaj dornojn kaj pikaĵojn ĝi kreskigos por vi, kaj vi manĝados herbojn de la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'En la ŝvito de via vizaĝo vi manĝados panon, ĝis vi revenos en la teron, el kiu vi estas prenita; ĉar vi estas polvo kaj refariĝos polvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Kaj Adam donis al sia edzino la nomon Eva, ĉar ŝi estis patrino de ĉiuj vivantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Kaj Dio la Eternulo faris por Adam kaj por lia edzino vestojn el felo, kaj Li vestis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Kaj Dio la Eternulo diris: Jen Adam fariĝis kiel unu el Ni, sciante bonon kaj malbonon; nun eble li etendos sian manon kaj prenos ankaŭ de la arbo de vivo kaj manĝos kaj vivos eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Kaj Dio la Eternulo eligis lin el la Edena ĝardeno, por ke li prilaboradu la teron, el kiu li estis prenita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Kaj Li elpelis Adamon, kaj lokis antaŭ la Edena ĝardeno la kerubon kaj la turniĝantan flaman glavon, por gardi la vojon al la arbo de vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Kaj Adam ekkonis Evan, sian edzinon, kaj ŝi gravediĝis, kaj ŝi naskis Kainon; kaj ŝi diris: Mi akiris homon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Kaj plue ŝi naskis lian fraton Habel. Kaj Habel fariĝis ŝafpaŝtisto, kaj Kain fariĝis terlaboristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Kaj post ia tempo fariĝis, ke Kain alportis el la fruktoj de la tero donacoferon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Kaj Habel ankaŭ alportis el la unuenaskitoj de siaj ŝafoj kaj el ilia graso. Kaj la Eternulo atentis Habelon kaj lian donacoferon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'sed Kainon kaj lian donacoferon Li ne atentis. Kaj Kain tre ekkoleris, kaj lia vizaĝo kliniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Kaj la Eternulo diris al Kain: Kial vi koleras? kaj kial kliniĝis via vizaĝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Ja se vi agos bone, vi estos forta; sed se vi agos malbone, la peko kuŝos ĉe la pordo, kaj vin ĝi aspiros, sed vi regu super ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Kaj Kain parolis kun sia frato Habel; kaj kiam ili estis sur la kampo, Kain leviĝis kontraŭ sian fraton Habel kaj mortigis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Kaj la Eternulo diris al Kain: Kie estas via frato Habel? Kaj tiu diris: Mi ne scias; ĉu mi estas gardisto de mia frato?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Kaj Li diris: Kion vi faris? la voĉo de la sango de via frato krias al Mi de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Kaj nun estu malbenita de sur la tero, kiu malfermis sian buŝon, por preni la sangon de via frato el via mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Kiam vi prilaboros la teron, ĝi ne plu donos al vi sian forton; vaganto kaj forkuranto vi estos sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Kaj Kain diris al la Eternulo: Pli granda estas mia puno, ol kiom mi povos elporti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Jen Vi forpelas min hodiaŭ de sur la tero, kaj mi devas min kaŝi de antaŭ Via vizaĝo, kaj mi estos vaganto kaj forkuranto sur la tero, kaj iu ajn, kiu min renkontos, mortigos min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Kaj la Eternulo diris al li: Sciu, ke al iu, kiu mortigos Kainon, estos venĝite sepoble. Kaj la Eternulo faris sur Kain signon, ke ne mortigu lin iu, kiu lin renkontos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Kaj Kain foriris de antaŭ la Eternulo, kaj loĝiĝis en la lando Nod, oriente de Eden.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Kaj Kain ekkonis sian edzinon, kaj ŝi gravediĝis, kaj ŝi naskis Ĥanoĥon. Kaj li konstruis urbon, kaj li donis al la urbo nomon laŭ la nomo de sia filo: Ĥanoĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Kaj al Ĥanoĥ naskiĝis Irad, kaj al Irad naskiĝis Meĥujael, kaj al Meĥujael naskiĝis Metuŝael, kaj al Metuŝael naskiĝis Lemeĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Kaj Lemeĥ prenis al si du edzinojn: unu havis la nomon Ada, kaj la dua havis la nomon Cila.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Kaj Ada naskis Jabalon; li estis la patro de tiuj, kiuj loĝas en tendoj kaj paŝtas brutojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Kaj la nomo de lia frato estis Jubal; li estis la patro de ĉiuj, kiuj ludas harpon kaj fluton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Cila ankaŭ naskis Tubal-Kainon, forĝanton de diversaj majstraĵoj el kupro kaj fero. Kaj la fratino de Tubal-Kain estis Naama.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Kaj Lemeĥ diris al siaj edzinoj Ada kaj Cila:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Aŭskultu mian voĉon, edzinoj de Lemeĥ, Atentu mian parolon! Ĉar viron mi mortigis por vundo al mi Kaj junulon por tubero al mi; Se sepoble estos venĝite por Kain, Por Lemeĥ estos sepdek-sepoble.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Kaj denove Adam ekkonis sian edzinon, kaj ŝi naskis filon, kaj donis al li la nomon Set: Ĉar Dio metis al mi alian semon anstataŭ Habel, kiun mortigis Kain.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Kaj al Set ankaŭ naskiĝis filo, kaj li donis al li la nomon Enoŝ. Tiam oni komencis alvokadi la nomon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Jen estas la libro de naskoj de Adam. Kiam Dio kreis la homon, Li faris lin laŭ la bildo de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'kiel viron kaj virinon Li kreis ilin, kaj Li benis ilin kaj donis al ili la nomon Homo en la tago de ilia naskiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Kaj Adam vivis cent tridek jarojn, kaj al li naskiĝis filo laŭ lia bildo kaj simileco, kaj li donis al li la nomon Set.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Kaj Adam vivis, post kiam naskiĝis al li Set, okcent jarojn, kaj naskiĝis al li filoj kaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Kaj la tuta vivo, kiun travivis Adam, estis naŭcent tridek jaroj, kaj li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Kaj Set vivis cent kvin jarojn, kaj naskiĝis al li Enoŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Kaj Set vivis, post kiam naskiĝis al li Enoŝ, okcent sep jarojn, kaj naskiĝis al li filoj kaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Kaj la tuta vivo de Set estis naŭcent dek du jaroj, kaj li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Kaj Enoŝ vivis naŭdek jarojn, kaj naskiĝis al li Kenan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Kaj Enoŝ vivis, post kiam naskiĝis al li Kenan, okcent dek kvin jarojn, kaj naskiĝis al li filoj kaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Kaj la tuta vivo de Enoŝ estis naŭcent kvin jaroj, kaj li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Kaj Kenan vivis sepdek jarojn, kaj naskiĝis al li Mahalalel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Kaj Kenan vivis, post kiam naskiĝis al li Mahalalel, okcent kvardek jarojn, kaj naskiĝis al li filoj kaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Kaj la tuta vivo de Kenan estis naŭcent dek jaroj, kaj li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Kaj Mahalalel vivis sesdek kvin jarojn, kaj naskiĝis al li Jared.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Kaj Mahalalel vivis, post kiam naskiĝis al li Jared, okcent tridek jarojn, kaj naskiĝis al li filoj kaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Kaj la tuta vivo de Mahalalel estis okcent naŭdek kvin jaroj, kaj li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Kaj Jared vivis cent sesdek du jarojn, kaj naskiĝis al li Ĥanoĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Kaj Jared vivis, post kiam naskiĝis al li Ĥanoĥ, okcent jarojn, kaj naskiĝis al li filoj kaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Kaj la tuta vivo de Jared estis naŭcent sesdek du jaroj, kaj li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Kaj Ĥanoĥ vivis sesdek kvin jarojn, kaj naskiĝis al li Metuŝelaĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Kaj Ĥanoĥ iradis kun Dio, post kiam naskiĝis al li Metuŝelaĥ, tricent jarojn, kaj naskiĝis al li filoj kaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Kaj la tuta vivo de Ĥanoĥ estis tricent sesdek kvin jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Kaj Ĥanoĥ iradis kun Dio; kaj li malaperis, ĉar Dio lin prenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Kaj Metuŝelaĥ vivis cent okdek sep jarojn, kaj naskiĝis al li Lemeĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Kaj Metuŝelaĥ vivis, post kiam naskiĝis al li Lemeĥ, sepcent okdek du jarojn, kaj naskiĝis al li filoj kaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Kaj la tuta vivo de Metuŝelaĥ estis naŭcent sesdek naŭ jaroj, kaj li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Kaj Lemeĥ vivis cent okdek du jarojn, kaj naskiĝis al li filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Kaj li donis al li la nomon Noa, dirante: Ĉi tiu konsolos nin en niaj faroj kaj en la laboroj de niaj manoj sur la tero, kiun la Eternulo malbenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Kaj Lemeĥ vivis, post kiam naskiĝis al li Noa, kvincent naŭdek kvin jarojn, kaj naskiĝis al li filoj kaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Kaj la tuta vivo de Lemeĥ estis sepcent sepdek sep jaroj, kaj li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Kaj Noa havis la aĝon de kvincent jaroj, kaj al Noa naskiĝis Ŝem, Ĥam, kaj Jafet.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Kaj kiam la homoj komencis multiĝi sur la tero kaj al ili naskiĝis filinoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'tiam la filoj de Dio vidis la filinojn de la homoj, ke ili estas belaj; kaj ili prenis al si edzinojn el ĉiuj, kiujn ili elektis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Kaj la Eternulo diris: Ne regos Mia spirito inter la homoj eterne, pro iliaj pekoj, ĉar ili estas karno; ilia vivo estu cent dudek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Gigantoj estis sur la tero en tiu tempo, eĉ post kiam la filoj de Dio venis al la filinoj de la homoj kaj ĉi tiuj naskis al ili. Tio estis la fortuloj, tre famaj de plej antikva tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Kaj la Eternulo vidis, ke granda estas la malboneco de la homoj sur la tero kaj ke ĉiuj pensoj kaj intencoj de iliaj koroj estas nur malbono en ĉiu tempo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'tiam la Eternulo pentis, ke Li kreis la homon sur la tero, kaj Li afliktiĝis en Sia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Kaj la Eternulo diris: Mi ekstermos de sur la tero la homon, kiun Mi kreis, de la homo ĝis la brutoj, ĝis la rampaĵoj, kaj ĝis la birdoj de la ĉielo; ĉar Mi pentas, ke Mi ilin kreis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Sed Noa akiris plaĉon en la okuloj de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Jen estas la historio de Noa: Noa estis homo virta kaj senmakula en sia generacio; kun Dio Noa iradis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Kaj naskiĝis al Noa tri filoj: Ŝem, Ĥam, kaj Jafet.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Kaj la tero malvirtiĝis antaŭ Dio, kaj la tero pleniĝis de maljustaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Kaj Dio vidis la teron, ke ĝi malvirtiĝis, ĉar ĉiu karno malvirtigis sian vojon sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Kaj Dio diris al Noa: La fino de ĉiu karno venis antaŭ Min, ĉar la tero pleniĝis de maljustaĵoj per ili, kaj jen Mi pereigos ilin kun la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Faru al vi arkeon el ligno gofera; apartaĵojn faru en la arkeo, kaj ŝmiru ĝin per peĉo interne kaj ekstere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Kaj faru ĝin tiamaniere: tricent ulnoj estu la longo de la arkeo, kvindek ulnoj ĝia larĝo, kaj tridek ulnoj ĝia alto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Fenestron faru en la arkeo, supre, kun la alto de unu ulno, kaj la pordon de la arkeo vi faros en la flanko; malsupran spacon, duan spacon, kaj trian spacon faru en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Kaj jen Mi venigos akvan diluvon sur la teron, por ekstermi ĉiun karnon, kiu havas en si spiriton de vivo sub la ĉielo; ĉio, kio estas sur la tero, pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Kaj Mi starigos Mian interligon kun vi; kaj vi eniros en la arkeon, vi kaj viaj filoj kaj via edzino kaj la edzinoj de viaj filoj kune kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Kaj el ĉiuj vivaĵoj, el ĉiu karno, enkonduku po unu paro el ĉiuj en la arkeon, ke ili restu vivaj kun vi; virbesto kaj virinbesto ili estu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'El la birdoj laŭ iliaj specoj, kaj el la brutoj laŭ iliaj specoj, el ĉiuj rampaĵoj de la tero laŭ iliaj specoj, po paro el ĉiuj eniru kun vi, por resti vivaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Kaj vi prenu al vi el ĉiuj manĝaĵoj, kiuj estas manĝataj, kaj kolektu al vi; kaj ĝi estu por vi kaj por ili por manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Kaj Noa tion faris; ĉion, kiel Dio al li ordonis, tiel li faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Kaj la Eternulo diris al Noa: Eniru vi kaj via tuta familio en la arkeon, ĉar vin Mi vidis, ke vi estas virtulo antaŭ Mi en ĉi tiu generacio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'El ĉiuj brutoj puraj prenu al vi po sep paroj, virbestojn kaj iliajn inojn; kaj el la brutoj, kiuj ne estas puraj, po du, virbeston kaj ĝian inon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Ankaŭ el la birdoj de la ĉielo po sep paroj, virbestojn kaj virinbestojn, por ke semo restu sur la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Ĉar post sep tagoj Mi pluvigos sur la teron dum kvardek tagoj kaj kvardek noktoj, kaj Mi ekstermos de sur la tero ĉiujn ekzistaĵojn, kiujn Mi kreis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Kaj Noa faris ĉion, kion la Eternulo al li ordonis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Kaj Noa havis la aĝon de sescent jaroj, kiam la akva diluvo venis sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Kaj eniris Noa kaj liaj filoj kaj lia edzino kaj la edzinoj de liaj filoj kune kun li en la arkeon, pro la akvo de la diluvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'El la brutoj puraj, kaj el la brutoj, kiuj ne estas puraj, kaj el la birdoj, kaj el ĉiuj rampaĵoj sur la tero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'po unu paro venis al Noa en la arkeon, virbesto kaj ino, kiel Dio ordonis al Noa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Kaj kiam pasis la sep tagoj, la diluva akvo venis sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'En la sescenta jaro de la vivo de Noa, en la dua monato, en la dek-sepa tago de la monato, en tiu tago disfendiĝis ĉiuj fontoj de la granda abismo kaj la aperturoj de la ĉielo malfermiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'Kaj estis pluvo sur la tero dum kvardek tagoj kaj kvardek noktoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Ĝuste en tiu tago eniris en la arkeon Noa, kaj Ŝem kaj Ĥam kaj Jafet, la filoj de Noa, kaj la edzino de Noa, kaj la tri edzinoj de liaj filoj kune kun ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'ili, kaj ĉiuj bestoj laŭ siaj specoj, kaj ĉiuj brutoj laŭ siaj specoj, kaj ĉiuj rampaĵoj, kiuj rampas sur la tero, laŭ siaj specoj, kaj ĉiuj flugaĵoj laŭ siaj specoj, ĉiuj birdoj, ĉiuj flugilhavantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Kaj eniris al Noa en la arkeon po du el ĉiu karno, kiu havas en si spiriton de vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Kaj la venintoj, virbesto kaj ino el ĉiu karno, eniris, kiel ordonis al ili Dio; kaj la Eternulo fermis post ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Kaj estis diluvo dum kvardek tagoj sur la tero; kaj multiĝis la akvo kaj levis la arkeon, kaj ĝi estis alte super la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Kaj la akvo fortiĝis sur la tero, kaj la arkeo naĝis sur la supraĵo de la akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Kaj la akvo treege fortiĝis kaj tre multiĝis sur la tero; kaj kovriĝis ĉiuj altaj montoj, kiuj estas sub la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Dek kvin ulnojn pli alte leviĝis la akvo kaj kovris la montojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Kaj pereis ĉiu karno, kiu moviĝas sur la tero, la birdoj kaj la brutoj kaj la bestoj, kaj ĉiuj rampaĵoj, kiuj rampas sur la tero, kaj ĉiuj homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Ĉio, kio havis en si spiriton de vivo, el ĉio, kio estis sur la seka tero, mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Kaj ekstermiĝis ĉiuj ekzistaĵoj, kiuj estis sur la tero, de homo ĝis brutoj kaj rampaĵoj kaj birdoj de la ĉielo; ili ekstermiĝis de sur la tero; kaj restis nur Noa kaj kio estis kun li en la arkeo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Kaj la akvo okupis la teron dum cent kvindek tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Kaj Dio rememoris Noan, kaj ĉiujn bestojn kaj ĉiujn brutojn, kiuj estis kun li en la arkeo; kaj Dio venigis venton sur la teron, kaj la akvo kvietiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Kaj fermiĝis la fontoj de la abismo kaj la aperturoj de la ĉielo, kaj ĉesiĝis la pluvo el la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Kaj iom post iom reforiĝis la akvo de sur la tero, kaj la akvo komencis malmultiĝi post la paso de cent kvindek tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Kaj la arkeo haltis en la sepa monato, en la dek-sepa tago de la monato, sur la montoj Ararat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Kaj la akvo konstante malpliiĝadis ĝis la deka monato; en la unua tago de la deka monato montriĝis la suproj de la montoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Kaj post kvardek tagoj Noa malfermis la fenestron de la arkeo, kiun li faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'Kaj li ellasis korvon, kaj ĝi elflugis, forflugadis kaj revenadis, ĝis forsekiĝis la akvo sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Kaj li ellasis de si kolombon, por vidi, ĉu jam malfortiĝis la akvo sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Sed la kolombo ne trovis ripozejon por siaj piedoj, kaj ĝi revenis al li en la arkeon, ĉar akvo estis sur la supraĵo de la tuta tero. Kaj li etendis sian manon kaj prenis la kolombon kaj envenigis ĝin al si en la arkeon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Kaj li atendis ankoraŭ aliajn sep tagojn, kaj li denove ellasis la kolombon el la arkeo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Kaj revenis al li la kolombo en tempo vespera, kaj jen ĝi havis en sia buŝo deŝiritan folion de olivarbo; kaj Noa konvinkiĝis, ke la akvo malfortiĝis sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Kaj li atendis ankoraŭ aliajn sep tagojn, kaj li ellasis la kolombon, kaj ĉi tiu jam ne plu revenis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Kaj en la sescent-unua jaro, en la unua tago de la unua monato, forsekiĝis la akvo sur la tero; kaj Noa malfermis la tegmenton de la arkeo, kaj li vidis, ke sekiĝis la supraĵo de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Kaj en la dua monato, en la dudek-sepa tago de la monato, la tero elsekiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Kaj Dio diris al Noa jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Eliru el la arkeo, vi kaj via edzino kaj viaj filoj kaj la edzinoj de viaj filoj kune kun vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'ĉiujn bestojn, kiuj estas kun vi, el ĉiu karno, el la birdoj kaj brutoj, kaj el ĉiuj rampaĵoj, kiuj rampas sur la tero, elirigu kune kun vi; kaj ili moviĝu sur la tero kaj fruktu kaj multiĝu sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Kaj eliris Noa kaj liaj filoj kaj lia edzino kaj la edzinoj de liaj filoj kune kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Ĉiuj bestoj, ĉiuj rampaĵoj, kaj ĉiuj birdoj, ĉio, kio moviĝas sur la tero, laŭ siaj familioj, eliris el la arkeo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Kaj Noa konstruis altaron al la Eternulo, kaj li prenis el ĉiuj puraj brutoj kaj el ĉiuj puraj birdoj kaj oferis bruloferojn sur la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Kaj la Eternulo flaris la agrablan odoron, kaj la Eternulo diris en Sia koro: Mi ne plu malbenos la teron pro la homo, ĉar la penso de la homa koro estas malbona jam de lia juneco; kaj Mi ne batos plu ĉion vivantan, kiel Mi faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'De nun tiel longe, kiel la tero ekzistos, semado kaj rikoltado, malvarmo kaj varmo, somero kaj vintro, tago kaj nokto ne ĉesiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Kaj Dio benis Noan kaj liajn filojn, kaj diris al ili: Fruktu kaj multiĝu, kaj plenigu la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Kaj ili timu vin kaj tremu antaŭ vi, ĉiuj bestoj de la tero kaj ĉiuj birdoj de la ĉielo, ĉio, kio moviĝas sur la tero, kaj ĉiuj fiŝoj de la maro; en viajn manojn ili estas transdonitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Ĉio, kio moviĝas kaj vivas, servu al vi kiel manĝaĵo; kiel verdan herbon, Mi donis al vi ĉion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Nur karnon kune kun ĝia animo, la sango, ne manĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Ankaŭ vian sangon kaj animon Mi repostulos, el la manoj de ĉiuj bestoj Mi ĝin repostulos, kaj el la manoj de homo, el la manoj de ĉiu homo pro lia frato Mi repostulos la animon de homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Se iu verŝos sangon de homo, lia sango ankaŭ estos verŝita de homo; ĉar laŭ la bildo de Dio estas farita la homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Kaj vi fruktu kaj multiĝu, moviĝadu sur la tero kaj multiĝu sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Kaj Dio diris al Noa kaj al liaj filoj kune kun li jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Jen Mi starigas Mian interligon kun vi kaj kun via idaro post vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'kaj kun ĉiu viva ekzistaĵo, kiu estas kun vi, el birdoj, el brutoj, kaj el ĉiuj bestoj de la tero kun vi, el ĉiuj, kiuj eliris el la arkeo, kun ĉiuj bestoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Kaj Mi starigas Mian interligon kun vi, ke ne ekstermiĝos plu ĉiu karno per akvo de diluvo, kaj ne estos plu diluvo, por pereigi la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Kaj Dio diris: Ĉi tio estas la signo de la interligo, kiun Mi metas inter Mi kaj inter vi kaj inter ĉiu viva ekzistaĵo, kiu estas kun vi, por eternaj generacioj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Mian arkon Mi metas en la nubon, kaj ĝi estu signo de la interligo inter Mi kaj la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Kaj kiam Mi venigos nubon super la teron, montriĝos la arko en la nubo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'kaj Mi rememoros Mian interligon, kiu ekzistas inter Mi kaj vi kaj ĉiu viva ekzistaĵo el ĉiu karno, kaj la akvo ne fariĝos plu diluvo, por pereigi ĉiun karnon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Kaj la arko estos en la nubo; kaj Mi ĝin vidos, por memori pri la eterna interligo inter Dio kaj ĉiu viva ekzistaĵo el ĉiu karno, kiu estas sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Kaj Dio diris al Noa: Ĉi tio estas la signo de la interligo, kiun Mi starigis inter Mi kaj ĉiu karno, kiu estas sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Kaj la filoj de Noa, kiuj eliris el la arkeo, estis: Ŝem, Ĥam, kaj Jafet; kaj Ĥam estis la patro de Kanaan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Tio estis la tri filoj de Noa; kaj de ili diskreskis la tuta loĝantaro de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Kaj Noa komencis terkultivan laboron kaj plantis vinberĝardenon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Kaj li trinkis el la vino kaj ebriiĝis, kaj nudiĝis en sia tendo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Kaj Ĥam, la patro de Kanaan, vidis la nudecon de sia patro, kaj li diris tion al siaj du fratoj ekstere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Kaj Ŝem kaj Jafet prenis la veston kaj metis ĝin sur siajn ŝultrojn, kaj iris dorsdirekte kaj kovris la nudecon de sia patro; kaj iliaj vizaĝoj estis turnitaj malantaŭen, kaj la nudecon de sia patro ili ne vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Kaj Noa vekiĝis de sia ebrieco, kaj li sciiĝis, kiel agis kun li lia pli juna filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'Kaj li diris: Malbenita estu Kanaan; Sklavo de sklavoj li estu ĉe siaj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Kaj li diris: Glorata estu la Eternulo, la Dio de Ŝem; Kaj Kanaan estu sklavo al ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Dio disvastigu Jafeton, Kaj li loĝu en la tendoj de Ŝem, Kaj Kanaan estu sklavo al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Kaj Noa vivis post la diluvo tricent kvindek jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Kaj la tuta vivo de Noa estis naŭcent kvindek jaroj, kaj li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Jen estas la generaciaro de la filoj de Noa: Ŝem, Ĥam, kaj Jafet. Kaj naskiĝis al ili filoj post la diluvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'La filoj de Jafet: Gomer kaj Magog kaj Madaj kaj Javan kaj Tubal kaj Meŝeĥ kaj Tiras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Kaj la filoj de Gomer: Aŝkenaz kaj Rifat kaj Togarma.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Kaj la filoj de Javan: Eliŝa kaj Tarŝiŝ, Kitim kaj Dodanim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'De ĉi tiuj dissemiĝis la insuloj da popoloj en siaj landoj, ĉiu laŭ sia lingvo, laŭ siaj gentoj kaj nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Kaj la filoj de Ĥam: Kuŝ kaj Micraim kaj Put kaj Kanaan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Kaj la filoj de Kuŝ: Seba kaj Ĥavila kaj Sabta kaj Raama kaj Sabteĥa; kaj la filoj de Raama; Ŝeba kaj Dedan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Kaj Kuŝ naskigis Nimrodon, kiu komencis esti potenca sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Li estis potenca ĉasisto antaŭ la Eternulo; tial oni diras: Kiel Nimrod, potenca ĉasisto antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Kaj la komenco de lia regno estis Babel kaj Ereĥ kaj Akad kaj Kalne en la lando Ŝinar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'El ĉi tiu lando li eliris en Asirion kaj konstruis la urbojn Nineve kaj Reĥobot kaj Kalaĥ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'kaj Resen inter Nineve kaj Kalaĥ (ĝi estis la granda urbo).');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Kaj Micraim naskigis la Ludidojn kaj la Anamidojn kaj la Lehabidojn kaj la Naftuĥidojn');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'kaj la Patrusidojn kaj la Kasluĥidojn (de kiuj devenis la Filiŝtoj) kaj la Kaftoridojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Kaj de Kanaan naskiĝis Cidon, lia unuenaskito, kaj Ĥet,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'kaj la Jebusidoj kaj la Amoridoj kaj la Girgaŝidoj');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'kaj la Ĥividoj kaj la Arkidoj kaj la Sinidoj');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'kaj la Arvadidoj kaj la Cemaridoj kaj la Ĥamatidoj; kaj poste la gentoj Kanaanaj disiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Kaj la limoj de la Kanaanidoj estis de Cidon ĝis Gerar kaj Gaza, ĝis Sodom kaj Gomora, Adma kaj Ceboim ĝis Laŝa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Tio estas la filoj de Ĥam laŭ siaj gentoj kaj lingvoj, en siaj landoj kaj nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Naskiĝis infanoj ankaŭ al Ŝem, la patro de ĉiuj Eberidoj, pli maljuna frato de Jafet.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'La filoj de Ŝem: Elam kaj Aŝur kaj Arpaĥŝad kaj Lud kaj Aram.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Kaj la filoj de Aram: Uc kaj Ĥul kaj Geter kaj Maŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Kaj al Arpaĥŝad naskiĝis Ŝelaĥ, kaj al Ŝelaĥ naskiĝis Eber.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Kaj al Eber naskiĝis du filoj: la nomo de unu estis Peleg, ĉar dum lia vivo dividiĝis la tero; kaj la nomo de lia frato estis Joktan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Kaj al Joktan naskiĝis Almodad kaj Ŝelef kaj Ĥacarmavet kaj Jeraĥ');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'kaj Hadoram kaj Uzal kaj Dikla');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'kaj Obal kaj Abimael kaj Ŝeba');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'kaj Ofir kaj Ĥavila kaj Jobab. Ĉiuj ĉi tiuj estis filoj de Joktan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Kaj ilia loĝloko estis de Meŝa ĝis Sefar, la orienta monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Tio estas la filoj de Ŝem laŭ siaj gentoj kaj lingvoj, en siaj landoj, laŭ siaj nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Tio estas la gentoj de la filoj de Noa, laŭ siaj generacioj, en siaj nacioj; kaj de ili disiĝis la popoloj sur la tero post la diluvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Sur la tuta tero estis unu lingvo kaj unu parolmaniero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Kaj kiam ili ekiris de la oriento, ili trovis valon en la lando Ŝinar kaj tie ekloĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Kaj ili diris unu al alia: Venu, ni faru brikojn kaj ni brulpretigu ilin per fajro. Kaj la brikoj fariĝis por ili ŝtonoj, kaj la bitumo fariĝis por ili kalko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Kaj ili diris: Venu, ni konstruu al ni urbon, kaj turon, kies supro atingos la ĉielon, kaj ni akiru al ni gloron, antaŭ ol ni disiĝos sur la supraĵo de la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Kaj la Eternulo malleviĝis, por vidi la urbon kaj la turon, kiujn konstruis la homidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Kaj la Eternulo diris: Jen estas unu popolo, kaj unu lingvon ili ĉiuj havas; kaj jen, kion ili komencis fari, kaj ili ne estos malhelpataj en ĉio, kion ili decidis fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Ni malleviĝu do, kaj Ni konfuzu tie ilian lingvon, por ke unu ne komprenu la parolon de alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Kaj la Eternulo disigis ilin de tie sur la supraĵon de la tuta tero, kaj ili ĉesis konstrui la urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Tial oni donis al ĝi la nomon Babel, ĉar tie la Eternulo konfuzis la lingvon de la tuta tero kaj de tie la Eternulo disigis ilin sur la supraĵon de la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Jen estas la generaciaro de Ŝem: Ŝem havis la aĝon de cent jaroj, kaj naskiĝis al li Arpaĥŝad, du jarojn post la diluvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Kaj Ŝem vivis post la naskiĝo de Arpaĥŝad kvincent jarojn, kaj naskiĝis al li filoj kaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Kaj Arpaĥŝad vivis tridek kvin jarojn, kaj naskiĝis al li Ŝelaĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Kaj Arpaĥŝad vivis post la naskiĝo de Ŝelaĥ kvarcent tri jarojn, kaj naskiĝis al li filoj kaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Kaj Ŝelaĥ vivis tridek jarojn, kaj naskiĝis al li Eber.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Kaj Ŝelaĥ vivis post la naskiĝo de Eber kvarcent tri jarojn, kaj naskiĝis al li filoj kaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Kaj Eber vivis tridek kvar jarojn, kaj naskiĝis al li Peleg.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Kaj Eber vivis post la naskiĝo de Peleg kvarcent tridek jarojn, kaj naskiĝis al li filoj kaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Kaj Peleg vivis tridek jarojn, kaj naskiĝis al li Reu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Kaj Peleg vivis post la naskiĝo de Reu ducent naŭ jarojn, kaj naskiĝis al li filoj kaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Kaj Reu vivis tridek du jarojn, kaj naskiĝis al li Serug.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Kaj Reu vivis post la naskiĝo de Serug ducent sep jarojn, kaj naskiĝis al li filoj kaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Kaj Serug vivis tridek jarojn, kaj naskiĝis al li Naĥor.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Kaj Serug vivis post la naskiĝo de Naĥor ducent jarojn, kaj naskiĝis al li filoj kaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Kaj Naĥor vivis dudek naŭ jarojn, kaj naskiĝis al li Teraĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Kaj Naĥor vivis post la naskiĝo de Teraĥ cent dek naŭ jarojn, kaj naskiĝis al li filoj kaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Kaj Teraĥ vivis sepdek jarojn, kaj naskiĝis al li Abram, Naĥor, kaj Haran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Kaj jen estas la generaciaro de Teraĥ: al Teraĥ naskiĝis Abram, Naĥor, kaj Haran; kaj al Haran naskiĝis Lot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Kaj Haran mortis antaŭ sia patro Teraĥ en sia lando de naskiĝo, en Ur la Ĥaldea.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Kaj Abram kaj Naĥor prenis al si edzinojn; la nomo de la edzino de Abram estis Saraj, kaj la nomo de la edzino de Naĥor estis Milka, filino de Haran, kiu estis la patro de Milka kaj la patro de Jiska.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Kaj Saraj estis senfrukta kaj ne havis infanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Kaj Teraĥ prenis sian filon Abram kaj sian nepon Lot, filo de Haran, kaj sian bofilinon Saraj, edzino de lia filo Abram; kaj ili eliris kune el Ur la Ĥaldea, por iri en la landon Kanaanan; kaj ili venis ĝis Ĥaran kaj enloĝiĝis tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Kaj Teraĥ atingis la aĝon de ducent kvin jaroj, kaj Teraĥ mortis en Ĥaran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Kaj la Eternulo diris al Abram: Iru el via lando, el inter via parencaro, kaj el la domo de via patro, al la lando, kiun Mi montros al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Kaj Mi faros vin granda popolo, kaj Mi benos vin kaj grandigos vian nomon, kaj vi estos beno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Kaj Mi benos viajn benantojn, kaj viajn malbenantojn Mi malbenos, kaj beniĝos per vi ĉiuj gentoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Kaj Abram iris, kiel la Eternulo diris al li, kaj kun li iris Lot. Kaj Abram havis la aĝon de sepdek kvin jaroj, kiam li eliris el Ĥaran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Kaj Abram prenis sian edzinon Saraj kaj sian nevon Lot, kaj ilian tutan havon, kiun ili akiris, kaj la homojn, kiujn ili akiris en Ĥaran; kaj ili eliris, por iri al la lando Kanaana; kaj ili venis en la landon Kanaanan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Kaj Abram trapasis la landon ĝis la loko Ŝeĥem, ĝis la kverko More; kaj la Kanaanidoj tiam loĝis en la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Kaj la Eternulo aperis al Abram, kaj diris: Al via idaro Mi donos ĉi tiun teron. Kaj li konstruis tie altaron al la Eternulo, kiu aperis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Kaj de tie li transloĝiĝis al la monto, kiu estas oriente de Bet-El, kaj aranĝis sian tendon tiamaniere, ke Bet-El estis okcidente kaj Aj oriente; kaj li konstruis tie altaron al la Eternulo kaj preĝadis al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Kaj Abram iris pluen, ĉiam pluen al sudo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Kaj estis malsato en la lando. Kaj Abram malsupreniris Egiptujon, por tie loĝi kelktempe, ĉar malfacila estis la malsato en la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Kaj kiam li estis jam proksime de Egiptujo, li diris al sia edzino Saraj: Mi scias ja, ke vi estas virino belaspekta;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'kaj kiam la Egiptoj vin vidos, ili diros: Tio estas lia edzino; kaj ili mortigos min, kaj vin ili lasos viva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Diru do, ke vi estas mia fratino, por ke al mi estu bone pro vi kaj por ke mia animo restu viva pro vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Kaj kiam Abram venis Egiptujon, la Egiptoj vidis, ke la virino estas tre bela;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'kaj vidis ŝin la eminentuloj de Faraono, kaj ili laŭdis ŝin al Faraono; kaj oni prenis la virinon en la domon de Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Kaj al Abram estis bone pro ŝi, kaj li havis ŝafojn kaj bovojn kaj azenojn kaj sklavojn kaj sklavinojn kaj azeninojn kaj kamelojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Kaj la Eternulo punis per grandaj suferoj Faraonon kaj lian domon pro Saraj, la edzino de Abram.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Kaj Faraono alvokis Abramon, kaj diris: Kion vi faris al mi? kial vi ne diris al mi, ke ŝi estas via edzino?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'kial vi diris: Ŝi estas mia fratino? Kaj mi prenis ŝin al mi kiel edzinon. Kaj nun jen estas via edzino; prenu kaj foriru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Kaj Faraono ordonis pri li al homoj, kaj ili forkondukis lin kaj lian edzinon kaj lian tutan havon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Kaj Abram supreniris el Egiptujo, li kaj lia edzino, kaj ĉio, kio estis kun li, kaj kun li ankaŭ Lot, direktante sin al sudo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Kaj Abram estis tre riĉa je brutoj, arĝento, kaj oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Kaj li daŭrigis sian migradon de sudo ĝis Bet-El, ĝis la loko, kie antaŭe estis lia tendo inter Bet-El kaj Aj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'al la loko de la altaro, kiun li tie faris antaŭe; kaj Abram tie preĝis al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Kaj ankaŭ Lot, kiu iris kun Abram, havis ŝafojn kaj bovojn kaj tendojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Kaj ne sufiĉis por ili la tero, ke ili loĝu kune, ĉar ilia havo estis granda kaj ili ne povis loĝi kune.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Kaj estis malpaco inter la paŝtistoj de la brutaro de Abram kaj la paŝtistoj de la brutaro de Lot; kaj la Kanaanidoj kaj Perizidoj tiam loĝis en la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Kaj Abram diris al Lot: Ne estu malpaco inter mi kaj vi kaj inter miaj paŝtistoj kaj viaj paŝtistoj, ĉar ni estas fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'La tuta tero estas ja antaŭ vi; apartiĝu do de mi: se vi iros maldekstren, mi iros dekstren; se vi iros dekstren, mi iros maldekstren.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Kaj Lot levis siajn okulojn kaj vidis, ke la tuta ĉirkaŭaĵo de Jordan, antaŭ ol la Eternulo pereigis Sodomon kaj Gomoran, tuta estas akvumata kiel ĝardeno de la Eternulo, kiel la lando Egipta, ĝis Coar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Kaj Lot elektis al si la tutan ĉirkaŭaĵon de Jordan; kaj Lot ekiris orienten; kaj ili apartiĝis unu de la alia:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram enloĝiĝis en la lando Kanaana, kaj Lot enloĝiĝis en la urboj de la ĉirkaŭaĵo kaj starigis siajn tendojn ĝis Sodom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Kaj la loĝantoj de Sodom estis malbonaj kaj tre pekaj kontraŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Kaj la Eternulo diris al Abram, post kiam Lot apartiĝis de li: Levu viajn okulojn, kaj rigardu de la loko, sur kiu vi nun estas, norden kaj suden kaj orienten kaj okcidenten;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'ĉar la tutan teron, kiun vi vidas, Mi donos al vi kaj al via idaro por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Kaj Mi faros vian idaron kiel polvo de la tero; se iu povos kalkuli la polvon de la tero, li kalkulos ankaŭ vian idaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Leviĝu, trairu la landon laŭlonge kaj laŭlarĝe, ĉar al vi Mi ĝin donos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Kaj Abram forprenis sian tendon, kaj iris kaj ekloĝis en la arbareto Mamre, kiu estas en Ĥebron; kaj li konstruis tie altaron al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Kaj estis en la tempo de Amrafel, reĝo de Ŝinar, Arjoĥ, reĝo de Elasar, Kedorlaomer, reĝo de Elam, kaj Tidal, reĝo de Gojim;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'ili faris militon kontraŭ Bera, reĝo de Sodom, kaj Birŝa, reĝo de Gomora, Ŝinab, reĝo de Adma, kaj Ŝemeber, reĝo de Ceboim, kaj la reĝo de Bela, kiu estas Coar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Ĉiuj ĉi tiuj kunvenis en la valo Sidim, kiu nun estas la Sala Maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Dek du jarojn ili servis al Kedorlaomer, kaj en la dek-tria ili ribeliĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Kaj en la dek-kvara jaro venis Kedorlaomer, kaj la reĝoj, kiuj estis kun li, kaj ili venkobatis la Rafaidojn en Aŝterot-Karnaim, kaj la Zuzidojn en Ham, kaj la Emidojn en Ŝave-Kirjataim,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'kaj la Ĥoridojn sur ilia monto Seir ĝis El-Paran, kiu estas ĉe la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Kaj ili reiris kaj venis al En-Miŝpat, kiu estas Kadeŝ, kaj venkobatis la tutan kampon de la Amalekidoj, kaj ankaŭ la Amoridojn, kiuj loĝis en Ĥacacon-Tamar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Kaj eliris la reĝo de Sodom kaj la reĝo de Gomora kaj la reĝo de Adma kaj la reĝo de Ceboim, kaj la reĝo de Bela, kiu estas Coar, kaj komencis batalon kontraŭ ili en la valo Sidim,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'kontraŭ Kedorlaomer, reĝo de Elam, kaj Tidal, reĝo de Gojim, kaj Amrafel, reĝo de Ŝinar, kaj Arjoĥ, reĝo de Elasar; kvar reĝoj kontraŭ kvin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Kaj en la valo Sidim estis multe da bitumaj kavoj; kaj la reĝoj de Sodom kaj Gomora forkuris kaj falis tien, kaj la restintoj kuris sur la monton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Kaj ili prenis la tutan havon de Sodom kaj Gomora kaj ilian tutan manĝeblaĵon, kaj foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Ili prenis Loton, la nevon de Abram, kaj lian havon, ĉar li loĝis en Sodom, kaj ili foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Kaj venis forsaviĝinto kaj diris al Abram la Hebreo, kiu loĝis en la arbareto de Mamre la Amorido, frato de Eŝkol kaj frato de Aner, kiuj estis en interligo kun Abram.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Kaj Abram aŭdis, ke lia frato estas kaptita, kaj li elkondukis siajn ekzercitojn, naskitajn en lia domo, tricent dek ok, kaj persekutis ĝis Dan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Kaj li dividis sin kontraŭ ili en la nokto, li kaj liaj domanoj, kaj venkobatis ilin, kaj persekutis ilin ĝis Ĥoba, kiu estas maldekstre de Damasko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Kaj li revenigis la tutan havon, kaj ankaŭ sian fraton Lot kaj lian havon li revenigis, kaj ankaŭ la virinojn kaj la popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Kaj la reĝo de Sodom eliris al li renkonte, kiam li revenis, venkinte Kedorlaomeron kaj la reĝojn, kiuj estis kun li, en la valon Ŝave, kiu estas Valo de la Reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Kaj Melkicedek, reĝo de Salem, elportis panon kaj vinon. Li estis pastro de Dio Plejsupra.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Kaj li benis lin kaj diris: Benata estu Abram de Dio Plejsupra, la Kreinto de la ĉielo kaj la tero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'kaj benata estu Dio Plejsupra, kiu transdonis viajn malamikojn en viajn manojn. Kaj Abram donis al li dekonaĵon el ĉio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Kaj la reĝo de Sodom diris al Abram: Donu al mi la homojn, kaj la havon prenu al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Kaj Abram diris al la reĝo de Sodom: Mi levas mian manon al la Eternulo, Dio Plejsupra, la Kreinto de la ĉielo kaj la tero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'ke eĉ fadenon aŭ rimenon de ŝuo mi ne prenos el ĉio, kio apartenas al vi, por ke vi ne diru: Mi riĉigis Abramon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'escepto estos nur tio, kion manĝis la junuloj, kaj la parto de la homoj, kiuj iris kun mi: Aner, Eŝkol, kaj Mamre; ili prenu sian parton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Post tiuj fariĝoj la Eternulo diris al Abram en vizio jene: Ne timu, Abram, Mi estas via ŝildo; via rekompenco estas tre granda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Kaj Abram diris: Ho Eternulo, mia Sinjoro, kion Vi donos al mi? mi vagas ja seninfane, kaj la administranto de mia domo estas Eliezer el Damasko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Kaj Abram diris: Al mi Vi ne donis ja idaron, kaj jen mia domano estos mia heredanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Kaj tiam la Eternulo diris al li jene: Ĉi tiu ne estos via heredanto; nur tiu, kiu eliros el via internaĵo, estos via heredanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Kaj Li elirigis lin eksteren, kaj diris: Rigardu al la ĉielo kaj kalkulu la stelojn, se vi povas ilin kalkuli. Kaj Li diris al li: Tiel estos via idaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Kaj li kredis al la Eternulo; kaj tio estis kalkulita al li kiel virto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Kaj Li diris al li: Mi estas la Eternulo, kiu elirigis vin el Ur la Ĥaldea, por doni al vi ĉi tiun landon kiel posedaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Kaj li diris: Ho Eternulo, mia Sinjoro, per kio mi povas scii, ke mi ĝin posedos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Kaj Li diris al li: Prenu por Mi bovinon trijaran kaj kaprinon trijaran kaj ŝafon trijaran kaj turton kaj junan kolombon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Kaj li alportis al Li ĉion ĉi tion, kaj Li distranĉis ilin laŭ la mezo kaj metis ĉiujn partojn unu kontraŭ la alia, sed la birdojn Li ne distranĉis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Kaj la rabobirdoj malleviĝis sur la kadavrojn, sed Abram ilin forpelis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Ĉe la subiro de la suno profunda dormo falis sur Abramon; kaj jen timego pro la granda mallumo atakis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Kaj Li diris al Abram: Sciu, ke via idaro estos fremduloj en lando, kiu ne apartenos al ili; kaj oni sklavigos kaj turmentos ilin dum kvarcent jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Tamen la popolon, ĉe kiu ili estos sklavoj, Mi juĝos; kaj poste ili eliros kun granda havo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Kaj vi foriros al viaj prapatroj en paco; vi estos entombigita en bona maljuneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Kaj en la kvara generacio ili revenos ĉi tien; ĉar la krimoj de la Amoridoj ankoraŭ ne atingis plenecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Kiam la suno subiris kaj fariĝis mallumo, subite forna fumo kaj fajra flamo trakuris inter tiuj distranĉitaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'En tiu tago la Eternulo faris interligon kun Abram, dirante: Al via idaro Mi donos ĉi tiun landon, de la rivero de Egiptujo ĝis la granda rivero, la rivero Eŭfrato:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'la Kenidojn kaj la Kenizidojn kaj la Kadmonidojn');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'kaj la Ĥetidojn kaj la Perizidojn kaj la Rafaidojn');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'kaj la Amoridojn kaj la Kanaanidojn kaj la Girgaŝidojn kaj la Jebusidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Kaj Saraj, la edzino de Abram, ne naskis al li; sed ŝi havis sklavinon, Egiptinon, kies nomo estis Hagar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Kaj Saraj diris al Abram: Jen la Eternulo ŝlosis min, ke mi ne nasku; eniru do al mia sklavino, eble mi havos infanojn per ŝi. Kaj Abram obeis la voĉon de Saraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Kaj Saraj, la edzino de Abram, prenis Hagaron la Egiptinon, sian sklavinon, kiam pasis dek jaroj de la tempo, kiam Abram ekloĝis en la lando Kanaana, kaj ŝi donis ŝin al sia edzo Abram kiel edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Kaj li venis al Hagar, kaj ŝi gravediĝis. Kaj ŝi vidis, ke ŝi gravediĝis, kaj tiam ŝia sinjorino senvaloriĝis en ŝiaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Kaj Saraj diris al Abram: Vi estas maljusta kontraŭ mi; mi donis mian sklavinon en viajn brakojn, sed kiam ŝi vidis, ke ŝi gravediĝis, mi senvaloriĝis en ŝiaj okuloj; la Eternulo juĝu inter mi kaj vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Kaj Abram diris al Saraj: Jen via sklavino estas en viaj manoj, faru kun ŝi ĉion, kio plaĉas al vi. Kaj Saraj komencis premi ŝin, kaj ŝi forkuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Kaj trovis ŝin anĝelo de la Eternulo ĉe akva fonto en la dezerto, ĉe la fonto sur la vojo al Ŝur.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Kaj li diris: Hagar, sklavino de Saraj, de kie vi venas kaj kien vi iras? Kaj ŝi diris: De Saraj, mia sinjorino, mi forkuras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Kaj la anĝelo de la Eternulo diris al ŝi: Reiru al via sinjorino, kaj humiliĝu sub ŝiaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Kaj la anĝelo de la Eternulo diris al ŝi: Mi multigos vian idaron tiel, ke pro multeco oni ne povos ĝin kalkuli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Kaj la anĝelo de la Eternulo diris al ŝi: Jen vi estas graveda, kaj vi naskos filon; kaj vi donos al li la nomon Iŝmael, ĉar la Eternulo aŭdis vian suferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Kaj li estos homo sovaĝa; lia mano estos kontraŭ ĉiuj, kaj la manoj de ĉiuj kontraŭ li, kaj li loĝos antaŭ ĉiuj siaj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Kaj la Eternulon, kiu parolis al ŝi, ŝi nomis: Dio-kiu-min-vidis; ĉar ŝi diris: Ĉi tie mi vidis Tiun, kiu min vidas; kaj ĉu mi poste vivas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Tial oni nomis tiun puton puto de la Vivanto-Vidanto; ĝi estas inter Kadeŝ kaj Bered.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Kaj Hagar naskis al Abram filon; kaj Abram donis al sia filo, kiun naskis Hagar, la nomon Iŝmael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Kaj Abram havis la aĝon de okdek ses jaroj, kiam Hagar naskis Iŝmaelon al Abram.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Kiam Abram havis la aĝon de naŭdek naŭ jaroj, aperis la Eternulo al Abram, kaj diris al li: Mi estas Dio la Plejpotenca; iradu antaŭ Mi kaj estu senpeka.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Kaj Mi faros Mian interligon inter Mi kaj vi, kaj Mi multigos vin tre forte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Kaj Abram ĵetis sin vizaĝaltere, kaj Dio parolis al li, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Jen estas Mia interligo kun vi: vi estos patro de multe da popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Kaj via nomo ne estos plu Abram, sed via nomo estos Abraham, ĉar Mi faris vin patro de multe da popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Kaj Mi fruktigos vin tre multe, kaj Mi devenigos de vi popolojn, kaj reĝoj devenos de vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Kaj Mi starigos Mian interligon inter Mi kaj vi kaj via idaro post vi en iliaj generacioj, eternan interligon, ke Mi estos Dio por vi kaj por via idaro post vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Kaj Mi donos al vi kaj al via idaro post vi la landon, en kiu vi loĝas kiel fremdulo, la tutan landon Kanaanan, por eterna posedaĵo, kaj Mi estos Dio por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Kaj Dio diris al Abraham: Kaj vi gardu Mian interligon, vi kaj via idaro post vi en iliaj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Jen estas Mia interligo, kiun vi devas gardi inter Mi kaj vi kaj via idaro post vi: ĉiu virseksulo ĉe vi estu cirkumcidata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Kaj cirkumcidu la karnon de via prepucio, kaj tio estu signo de interligo inter Mi kaj vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Kaj en la aĝo de ok tagoj estu cirkumcidata ĉe vi en viaj generacioj ĉiu virseksulo naskita en la domo aŭ aĉetita per mono ĉe iu aligentulo, kiu ne estas el via idaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Cirkumcidata estu ĉiu naskita en via domo aŭ aĉetita per via mono, kaj Mia interligo estu sur via karno kiel interligo eterna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Kaj se estos prepucihava virseksulo, kiu ne cirkumcidos la karnon de sia prepucio, tiu animo ekstermiĝos el sia popolo: Mian interligon ĝi rompis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Kaj Dio diris al Abraham: Vian edzinon Saraj ne nomu Saraj, sed ŝia nomo estu Sara.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Kaj Mi benos ŝin, kaj Mi donos de ŝi al vi filon; kaj Mi benos ŝin, kaj de ŝi devenos popoloj, reĝoj de popoloj devenos de ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Kaj Abraham ĵetis sin vizaĝaltere, kaj ekridis, kaj diris en sia koro: Ĉu de homo centjara fariĝos nasko, kaj ĉu Sara la naŭdekjara naskos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Kaj Abraham diris al Dio: Ho, ke Iŝmael vivu antaŭ Vi!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Kaj Dio diris: Efektive Sara, via edzino, naskos al vi filon, kaj vi donos al li la nomon Isaak; kaj Mi starigos Mian interligon kun li kiel interligon eternan por lia idaro post li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Ankaŭ pri Iŝmael Mi aŭdis vin: jen Mi benis lin, kaj Mi fruktigos lin kaj Mi multigos lin tre forte; dek du princoj naskiĝos de li, kaj Mi devenigos de li grandan popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Sed Mian interligon Mi starigos kun Isaak, kiun naskos al vi Sara en ĉi tiu tempo en la venonta jaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Kaj Li ĉesis paroli kun li, kaj Dio leviĝis for de Abraham.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Kaj Abraham prenis sian filon Iŝmael kaj ĉiujn naskitajn en lia domo kaj ĉiujn aĉetitajn per lia mono, ĉiun virseksulon el la homoj de la domo de Abraham, kaj li cirkumcidis la karnon de ilia prepucio en tiu sama tago, kiel diris al li Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Kaj Abraham havis la aĝon de naŭdek naŭ jaroj, kiam li cirkumcidis la karnon de sia prepucio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Kaj lia filo Iŝmael havis la aĝon de dek tri jaroj, kiam la karno de lia prepucio estis cirkumcidita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'En tiu sama tago estis cirkumciditaj Abraham kaj lia filo Iŝmael;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'kaj ĉiuj liaj domanoj, kiuj naskiĝis en la domo aŭ estis aĉetitaj per mono ĉe aligentulo, estis cirkumciditaj kune kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Kaj aperis al li la Eternulo en la arbareto Mamre, kiam li sidis ĉe la pordo de la tendo dum la varmego de la tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Kiam li levis siajn okulojn, li vidis, ke jen tri viroj staras antaŭ li. Ekvidinte, li kuris al ili renkonte de la pordo de la tendo kaj kliniĝis antaŭ ili ĝis la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'Kaj li diris: Mia sinjoro! se mi trovis plaĉon en viaj okuloj, ne pasu preter vian sklavon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Oni alportos iom da akvo, kaj vi lavu viajn piedojn kaj ripozu sub la arbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Kaj mi alportos pecon da pano, por ke vi fortigu viajn korojn; poste vi foriros; ĉar por tio vi pasis preter via sklavo. Kaj ili diris: Faru tiel, kiel vi diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Kaj Abraham rapidis en la tendon al Sara, kaj diris: Rapide prenu tri mezurojn da plej bona faruno, knedu, kaj faru kukojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Kaj ankaŭ al la bovoj Abraham kuris, kaj li prenis bovidon delikatan kaj bonan kaj donis al la junulo, kaj tiu rapide pretigis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Kaj li prenis buteron kaj lakton kaj la pretigitan bovidon kaj metis antaŭ ilin, kaj li staris apud ili sub la arbo, kaj ili manĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Kaj ili diris al li: Kie estas Sara, via edzino? Kaj li respondis: Jen ŝi estas en la tendo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Kaj Li diris: Mi revenos al vi en la sama jartempo, kaj tiam estos filo ĉe Sara, via edzino. Kaj Sara aŭskultis ĉe la pordo de la tendo, kiu estis malantaŭ Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Kaj Abraham kaj Sara estis maljunuloj de profunda aĝo; ĉe Sara ĉesiĝis la virinaj ordinaraĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Kaj Sara ekridis interne, dirante: Ĉu kiam mi kadukiĝis, mi havus ankoraŭ volupton? kaj mia sinjoro estas ja maljuna!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Kaj la Eternulo diris al Abraham: Kial do Sara ridas, dirante: Ĉu efektive mi naskos, kiam mi maljuniĝis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Ĉu por la Eternulo io estas malfacila? en la difinita tempo Mi revenos al vi en la venonta jaro, kaj Sara havos filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Sed Sara malkonfesis, dirante: Mi ne ridis; ĉar ŝi timis. Sed Li diris: Ne, vi ridis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Kaj leviĝis de tie la viroj kaj direktiĝis al Sodom: kaj Abraham iris kun ili, por akompani ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Kaj la Eternulo diris: Ĉu mi kaŝos antaŭ Abraham, kion Mi faras?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Abraham fariĝos ja popolo granda kaj potenca, kaj per li beniĝos ĉiuj popoloj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Ĉar Mi lin elektis, por ke li ordonu al siaj filoj kaj al sia domo post si, ke ili observu la vojon de la Eternulo, agante virte kaj juste; por ke la Eternulo plenumu pri Abraham, kion Li diris pri li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Kaj la Eternulo diris: Ĉar la kriado de Sodom kaj Gomora estas granda kaj ilia pekado estas tre peza,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'tial Mi malsupreniros, kaj rigardos, ĉu ili plene agas tiel, kiel estas la kriado, kiu venis al Mi, aŭ ne; Mi sciiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Kaj la viroj turniĝis de tie kaj iris al Sodom; kaj Abraham staris ankoraŭ antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Kaj Abraham alproksimiĝis, kaj diris: Ĉu Vi ankaŭ pereigos virtulon kune kun malvirtulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Eble ekzistas kvindek virtuloj en la urbo: ĉu Vi tiam pereigos kaj ne indulgos la lokon pro la kvindek virtuloj, kiuj estas en ĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Ne decas por Vi agi tiamaniere, ke Vi mortigu virtulon kune kun malvirtulo, ke virtulo estu kiel malvirtulo; ne decas por Vi, ke la Juĝanto de la tuta tero agu maljuste.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Kaj la Eternulo diris: Se Mi trovos en Sodom kvindek virtulojn en la urbo, Mi indulgos la tutan lokon pro ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Kaj Abraham respondis, dirante: Jen mi ekkuraĝis paroli al mia Sinjoro, kvankam mi estas polvo kaj cindro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'eble al la kvindeko da virtuloj mankos kvin: ĉu Vi pereigos pro la kvin la tutan urbon? Kaj Li diris: Mi ne pereigos, se Mi trovos tie kvardek kvin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Kaj li plue parolis al Li kaj diris: Eble troviĝos tie kvardek? Kaj Li diris: Mi ne faros tion pro la kvardek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Kaj li diris: Ne koleru, mia Sinjoro, ke mi parolos plue: eble troviĝos tie tridek? Kaj Li diris: Mi ne faros, se Mi trovos tie tridek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Kaj li diris: Jen mi ekkuraĝis paroli al mia Sinjoro: eble troviĝos dudek? Kaj Li diris: Mi ne pereigos pro la dudek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Kaj li diris: Ne koleru, mia Sinjoro, ke mi parolos ankoraŭ nur unu fojon: eble troviĝos tie dek? Kaj Li diris: Mi ne pereigos pro la dek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Kaj la Eternulo foriris, kiam Li ĉesis paroli kun Abraham; kaj Abraham reiris al sia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Kaj la du anĝeloj venis Sodomon vespere, kaj Lot tiam sidis ĉe la pordego de Sodom. Kiam Lot ilin ekvidis, li leviĝis renkonte al ili kaj kliniĝis vizaĝaltere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'Kaj li diris: Mi petas vin, sinjoroj, envenu en la domon de via sklavo kaj pasigu la nokton kaj lavu viajn piedojn, kaj vi leviĝos matene kaj iros vian vojon. Kaj ili diris: Ne, ni pasigos la nokton sur la strato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Kaj li tre petegis ilin, kaj ili direktis sin al li kaj envenis en lian domon; kaj li faris al ili festenon, kaj li bakis macojn, kaj ili manĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Antaŭ ol ili kuŝiĝis, la homoj de la urbo, la homoj de Sodom, ĉirkaŭis la domon, de la junuloj ĝis la maljunuloj, la tuta popolo, de ĉiuj finoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Kaj ili vokis Loton, kaj diris al li: Kie estas la viroj, kiuj venis al vi dum la nokto? elirigu ilin al ni, por ke ni ilin ekkonu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Kaj Lot eliris al ili antaŭ la sojlon, kaj la pordon li ŝlosis post si.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'Kaj li diris: Ho, miaj fratoj, ne agu malbone!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Jen mi havas du filinojn, kiuj ankoraŭ ne ekkonis viron; mi elirigos ilin al vi, kaj faru kun ili, kion vi deziras; nur al tiuj viroj nenion faru, ĉar por tio ili venis sub la ombron de mia tegmento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Sed ili diris: Iru for! Kaj ili diris plue: Vi venis ĉi tien kiel fremdulo, kaj vi volas juĝi! nun ni pli malbone agos kun vi, ol kun ili. Kaj ili tre insiste postulis de la viro, de Lot, kaj ili aliris, por elrompi la pordon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Tiam tiuj viroj etendis siajn manojn kaj envenigis Loton al si en la domon, kaj la pordon ili ŝlosis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'kaj la homojn, kiuj estis antaŭ la sojlo de la domo, ili frapis per blindeco, de la malgrandaj ĝis la grandaj, tiel ke tiuj laciĝis, serĉante la pordon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Kaj la viroj diris al Lot: Kiun vi havas ĉi tie? bofilon, aŭ viajn filojn aŭ viajn filinojn, aŭ ĉiun ajn, kiun vi havas en la urbo, elirigu ilin el ĉi tiu loko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'ĉar ni ekstermos ĉi tiun lokon, ĉar granda fariĝis ilia kriado antaŭ la Eternulo, kaj la Eternulo sendis nin, por ĝin pereigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Kaj Lot eliris, kaj parolis kun siaj bofiloj, prenontaj liajn filinojn, kaj diris: Leviĝu, eliru el ĉi tiu loko, ĉar la Eternulo pereigos la urbon. Sed liaj bofiloj rigardis lin kiel ŝercanton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Kiam leviĝis la matenruĝo, la anĝeloj rapidigis Loton, dirante: Leviĝu, prenu vian edzinon kaj ambaŭ viajn filinojn, kiuj ĉi tie troviĝas, por ke vi ne pereu pro la krimeco de la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Sed ĉar li malrapidis, tial la viroj kaptis lian manon kaj la manon de lia edzino kaj la manojn de liaj du filinoj, pro kompato de la Eternulo al li, kaj ili elirigis lin kaj metis lin ekster la urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Kaj kiam ili elkondukis lin eksteren, ili diris al li: Savu vin pro via animo; ne rigardu malantaŭen kaj haltu nenie en la tuta ĉirkaŭaĵo; sur la monton savu vin, por ke vi ne pereu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Kaj Lot diris al ili: Ho, ne, mia Sinjoro!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Jen Via sklavo plaĉis al Vi, kaj granda estas la favorkoreco, kiun Vi montris al mi, konservante la vivon al mia animo; sed mi ne povas savi min sur la monton, ĉar povus trafi min malfeliĉo kaj mi mortus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Jen ĉi tiu urbo estas sufiĉe proksima, por kuri tien, kaj ĝi estas malgranda; mi savos min tien; ĝi estas ja malgranda; kaj mia animo restos viva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Kaj Li diris al li: Jen Mi komplezos al vi ankaŭ en ĉi tiu afero, kaj Mi ne renversos la urbon, pri kiu vi parolis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Rapide savu vin tien, ĉar Mi nenion povas fari, ĝis vi venos tien. Tial tiu urbo ricevis la nomon Coar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'La suno leviĝis super la teron, kiam Lot venis Coaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Kaj la Eternulo pluvigis sur Sodomon kaj Gomoran sulfuron kaj fajron de la Eternulo el la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'Kaj Li ruinigis tiujn urbojn kaj la tutan ĉirkaŭaĵon kaj ĉiujn loĝantojn de la urboj kaj la kreskaĵojn de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Kaj lia edzino ekrigardis malantaŭen, kaj ŝi fariĝis kolono el salo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Kaj matene Abraham leviĝis kaj iris al la loko, kie li estis starinta antaŭ la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'kaj li ekrigardis en la direkto al Sodom kaj Gomora kaj al la tuta lando de la ĉirkaŭaĵo, kaj li vidis, ke jen fumo leviĝas de la tero kiel fumo el forno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Kaj kiam Dio estis pereiganta la urbojn de la ĉirkaŭaĵo, Li rememoris pri Abraham, kaj Li elirigis Loton el la mezo de la ruinigado, kiam Li estis ruiniganta la urbojn, en kiuj loĝis Lot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Kaj Lot eliris el Coar kaj ekloĝis sur la monto, kaj liaj du filinoj kun li; ĉar li timis loĝi en Coar. Kaj li loĝis en kaverno, li kaj liaj du filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Kaj la pli maljuna diris al la pli juna: Nia patro estas maljuna, kaj en la lando ne ekzistas viro, kiu envenus al ni laŭ la moro de la tuta tero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'tial ni ebriigu nian patron per vino, kaj ni kuŝu kun li, por ke ni aperigu de nia patro idaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Kaj ili ebriigis sian patron per vino en tiu nokto; kaj venis la pli maljuna kaj kuŝis kun sia patro; kaj li ne sciis, kiam ŝi kuŝiĝis kaj kiam ŝi leviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'La morgaŭan tagon la pli maljuna diris al la pli juna: Jen mi kuŝis hieraŭ kun mia patro; ni ebriigu lin per vino ankaŭ en ĉi tiu nokto, kaj vi venu, kuŝu kun li, por ke ni aperigu de nia patro idaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Kaj ili ankaŭ en ĉi tiu nokto ebriigis sian patron per vino; kaj la pli juna iris kaj kuŝis kun li; kaj li ne sciis, kiam ŝi kuŝiĝis kaj kiam ŝi leviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Kaj ambaŭ filinoj de Lot gravediĝis de sia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Kaj la pli maljuna naskis filon, kaj ŝi donis al li la nomon Moab; li estas la prapatro de la Moabidoj ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Kaj la pli juna ankaŭ naskis filon, kaj ŝi donis al li la nomon Ben- Ami; li estas la prapatro de la Amonidoj ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Kaj Abraham ekmigris de tie al la lando suda, kaj li ekloĝis inter Kadeŝ kaj Ŝur; kaj li loĝis kiel fremdulo en Gerar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Kaj Abraham diris pri sia edzino Sara: Ŝi estas mia fratino. Kaj Abimeleĥ, reĝo de Gerar, sendis kaj prenis Saran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Kaj Dio venis al Abimeleĥ nokte en la sonĝo, kaj diris al li: Vi mortos pro la virino, kiun vi prenis, ĉar ŝi estas edzino de edzo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Sed Abimeleĥ ne alproksimiĝis al ŝi, kaj li diris: Mia Sinjoro! ĉu vi mortigos ankaŭ senkulpan popolon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Li diris ja al mi: Ŝi estas mia fratino; kaj ŝi ankaŭ diris al mi: Li estas mia frato. En senkulpeco de mia koro kaj en pureco de miaj manoj mi faris tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Kaj Dio diris al li en la sonĝo: Mi ankaŭ scias, ke en senkulpeco de via koro vi tion faris, kaj tial Mi detenis vin, ke vi ne peku kontraŭ Mi, tial Mi ne lasis, ke vi kuntuŝiĝu kun ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Kaj nun redonu la edzinon al la edzo, ĉar li estas profeto, kaj li preĝos pri vi, kaj vi restos viva; sed se vi ne redonos, tiam sciu, ke vi mortos, vi kaj ĉiuj viaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Kaj Abimeleĥ leviĝis frue matene, kaj li vokis ĉiujn siajn sklavojn kaj rakontis ĉion ĉi tion al iliaj oreloj; kaj la homoj tre ektimis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Kaj Abimeleĥ vokis Abrahamon, kaj diris al li: Kion vi faris al ni? kaj per kio mi pekis antaŭ vi, ke vi venigis sur min kaj sur mian regnon grandan pekon? aferojn, kiuj ne estas farataj, vi faris kontraŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Kaj Abimeleĥ diris al Abraham: Kion vi vidis, kiam vi faris tiun aferon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Kaj Abraham diris: Mi pensis, ke ne ekzistas timo antaŭ Dio en ĉi tiu loko, kaj ke oni mortigos min pro mia edzino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Kaj efektive ŝi estas mia fratino, filino de mia patro, nur ne filino de mia patrino; kaj ŝi fariĝis mia edzino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Kaj kiam Dio elmigrigis min el la domo de mia patro, mi diris al ŝi: Faru al mi ĉi tiun komplezon, en kian ajn lokon ni venos, diru pri mi: Li estas mia frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Kaj Abimeleĥ prenis ŝafojn kaj bovojn kaj sklavojn kaj sklavinojn kaj donis al Abraham, kaj li redonis al li lian edzinon Sara.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Kaj Abimeleĥ diris: Jen mia lando estas antaŭ vi; kie plaĉas al vi, tie loĝiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Kaj al Sara li diris: Jen mi donis mil arĝentajn monerojn al via frato; tio estu al vi kovro por la okuloj antaŭ ĉiuj, kiuj estas kun vi, kaj antaŭ ĉiuj vi estas pravigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Kaj Abraham ekpreĝis al Dio; kaj Dio sanigis Abimeleĥon kaj lian edzinon kaj liajn sklavinojn, kaj ili komencis naski.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Ĉar la Eternulo estis ŝlosinta ĉiujn uterojn en la domo de Abimeleĥ pro Sara, la edzino de Abraham.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Kaj la Eternulo rememoris Saran, kiel Li diris, kaj la Eternulo faris al Sara, kiel Li parolis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Kaj Sara gravediĝis kaj naskis al Abraham filon en lia maljuneco, en la difinita tempo, pri kiu Dio al li diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Kaj Abraham donis al sia filo, kiu naskiĝis al li, kiun naskis al li Sara, la nomon Isaak.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Kaj Abraham cirkumcidis sian filon Isaak, kiam tiu havis la aĝon de ok tagoj, kiel ordonis al li Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Kaj Abraham havis la aĝon de cent jaroj, kiam naskiĝis al li lia filo Isaak.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Kaj Sara diris: Ridindaĵon faris al mi Dio; ĉiu, kiu aŭdos, ridos pri mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Kaj ŝi diris: Kiu dirus al Abraham, ke Sara mamnutros infanojn? ĉar mi naskis filon en lia maljuneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Kaj la infano kreskis, kaj ĝi estis demamigita, kaj Abraham faris grandan festenon en la tago, en kiu Isaak estis demamigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Kaj Sara vidis, ke la filo de Hagar la Egiptino, kiun ĉi tiu naskis al Abraham, mokas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Kaj ŝi diris al Abraham: Forpelu ĉi tiun sklavinon kaj ŝian filon; ĉar la filo de ĉi tiu sklavino ne heredos kun mia filo, kun Isaak.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Kaj la afero forte malplaĉis al Abraham pro lia filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Kaj Dio diris al Abraham: Ĝi ne malplaĉu al vi pro la knabo kaj pro via sklavino; pri ĉio, kion diros al vi Sara, obeu ŝian voĉon; ĉar per Isaak oni nomos vian idaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Sed ankaŭ el la filo de la sklavino Mi kreskigos popolon, ĉar li estas via semo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Kaj Abraham leviĝis frue matene, kaj prenis panon kaj felsakon kun akvo kaj donis al Hagar, metante ĝin sur ŝian ŝultron, ankaŭ la infanon, kaj foririgis ŝin; kaj ŝi iris, kaj ŝi erarvagis en la dezerto Beer-Ŝeba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Kaj konsumiĝis la akvo de la felsako, kaj ŝi ĵetis la infanon sub unu el la arbetaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'Kaj ŝi iris kaj sidiĝis kontraŭe, en la malproksimeco de pafo el pafarko; ĉar ŝi diris: Mi ne povas rigardi la morton de la infano. Kaj ŝi sidiĝis kontraŭe, kaj ŝi komencis laŭte plori.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Kaj Dio aŭdis la voĉon de la knabo; kaj anĝelo de Dio vokis Hagaron el la ĉielo, kaj diris al ŝi: Kio estas al vi, Hagar? ne timu, ĉar Dio aŭdis la voĉon de la knabo el la loko, kie li estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Leviĝu, prenu la knabon kaj tenu lin per via mano, ĉar grandan popolon Mi faros el li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Kaj Dio malfermis ŝiajn okulojn, kaj ŝi ekvidis puton kun akvo, kaj ŝi iris kaj plenigis la felsakon per akvo kaj trinkigis la knabon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Kaj Dio estis kun la knabo, kaj li grandiĝis kaj loĝis en la dezerto kaj fariĝis arkpafisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Kaj li loĝis en la dezerto Paran; kaj lia patrino prenis al li edzinon el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Kaj en tiu tempo Abimeleĥ kaj lia militestro Piĥol diris al Abraham jene: Dio estas kun vi en ĉio, kion vi faras;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'nun ĵuru do al mi per Dio, ke vi ne agos malfidele kun mi, nek kun mia filo, nek kun mia nepo; ke tiel same favorkore, kiel mi agis kun vi, vi agos kun mi, kaj kun la lando, en kiu vi loĝas kiel fremdulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Kaj Abraham diris: Mi ĵuras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Kaj Abraham riproĉis Abimeleĥon pro la akva puto, kiun perforte forprenis la sklavoj de Abimeleĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Kaj Abimeleĥ diris: Mi ne scias, kiu faris tion, kaj ankaŭ vi ne diris al mi; mi eĉ ne aŭdis pri tio ĝis hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Kaj Abraham prenis ŝafojn kaj bovojn kaj donis al Abimeleĥ, kaj ili ambaŭ starigis inter si interligon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Kaj Abraham starigis sep ŝafidojn aparte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Kaj Abimeleĥ diris al Abraham: Por kio estas tiuj sep ŝafidoj, kiujn vi starigis aparte?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Kaj tiu diris: Sep ŝafidojn prenu el mia mano, por ke ili estu por mi atesto, ke mi elfosis tiun puton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Tial tiu loko havas la nomon Beer-Ŝeba, ĉar tie ili ambaŭ ĵuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Kaj ili starigis interligon en Beer-Ŝeba. Kaj Abimeleĥ kaj lia militestro Piĥol leviĝis kaj reiris en la landon de la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Kaj Abraham plantis tamariskon en Beer-Ŝeba, kaj preĝis tie al la Eternulo, la Dio eterna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Kaj Abraham loĝis en la lando de la Filiŝtoj longan tempon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Post tiuj okazintaĵoj Dio provis Abrahamon, kaj diris al li: Abraham! Kaj tiu respondis: Jen mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Kaj Li diris: Prenu vian filon, vian solan, kiun vi amas, Isaakon, kaj iru en la landon Morija, kaj oferu lin tie kiel bruloferon sur unu el la montoj, kiun Mi montros al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Kaj Abraham leviĝis frue matene kaj selis sian azenon kaj prenis siajn du junulojn kun si kaj sian filon Isaak; kaj li fendis lignon por brulofero, kaj leviĝis kaj iris al tiu loko, pri kiu diris al li Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'En la tria tago Abraham levis siajn okulojn kaj ekvidis la lokon de malproksime.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Kaj Abraham diris al siaj junuloj: Restu ĉi tie kun la azeno, kaj mi kun la knabo iros tien, kaj ni adorkliniĝos kaj revenos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Kaj Abraham prenis la lignon por la brulofero kaj metis ĝin sur sian filon Isaak, kaj li prenis en sian manon la fajron kaj la tranĉilon; kaj ili iris ambaŭ kune.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Kaj Isaak diris al sia patro Abraham: Mia patro! Kaj tiu respondis: Jen mi estas, mia filo. Kaj li diris: Jen estas la fajro kaj la ligno, sed kie estas la ŝafo por la brulofero?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Kaj Abraham diris: Dio antaŭvidos al Si la ŝafon por la brulofero, mia filo. Kaj ili iris ambaŭ kune.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Kaj ili venis al la loko, pri kiu diris al li Dio; kaj Abraham konstruis tie la altaron kaj surmetis la lignon, kaj ligis sian filon Isaak kaj metis lin sur la altaron super la ligno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Kaj Abraham etendis sian manon kaj prenis la tranĉilon, por buĉi sian filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Kaj ekvokis al li anĝelo de la Eternulo el la ĉielo, kaj diris: Abraham, Abraham! Kaj li respondis: Jen mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Kaj Tiu diris: Ne etendu vian manon sur la knabon, kaj faru al li nenion; ĉar nun Mi scias, ke vi timas Dion kaj vi ne indulgis pro Mi vian filon, la solan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Kaj Abraham levis siajn okulojn, kaj vidis, ke jen virŝafo malantaŭe implikiĝis per la kornoj en la arbetaĵoj. Kaj Abraham iris kaj prenis la virŝafon, kaj oferis ĝin kiel bruloferon anstataŭ sia filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Kaj Abraham donis al tiu loko la nomon: La Eternulo Vidas; tial oni ankoraŭ nun diras: Sur la monto, kie la Eternulo aperas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Kaj denove anĝelo de la Eternulo vokis al Abraham el la ĉielo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'kaj diris: Mi ĵuras per Mi, diras la Eternulo, ke ĉar vi faris tiun aferon kaj ne indulgis vian filon, la solan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'tial Mi benos vin kaj Mi multigos vian idaron simile al la steloj de la ĉielo kaj al la sablo sur la bordo de la maro; kaj via idaro posedos la pordegojn de siaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Kaj beniĝos per via idaro ĉiuj popoloj de la tero, pro tio, ke vi obeis Mian voĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Kaj Abraham revenis al siaj junuloj, kaj ili leviĝis kaj iris kune al Beer-Ŝeba; kaj Abraham loĝis en Beer-Ŝeba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Post tiuj okazintaĵoj oni sciigis al Abraham, dirante: Jen ankaŭ Milka naskis infanojn al via frato Naĥor:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'la unuenaskiton Uc, kaj lian fraton Buz, kaj Kemuelon, la patron de Aram;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'kaj Kesedon kaj Ĥazon kaj Pildaŝon kaj Jidlafon kaj Betuelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Kaj de Betuel naskiĝis Rebeka. Ĉi tiujn ok naskis Milka al Naĥor, la frato de Abraham.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Kaj lia kromvirino, nome Reuma, ankaŭ naskis: Tebaĥon kaj Gaĥamon kaj Taĥaŝon kaj Maaĥan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Kaj la vivo de Sara estis cent dudek sep jaroj; tiom estis la jaroj de la vivo de Sara.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Kaj Sara mortis en Kirjat-Arba, kiu estas Ĥebron, en la lando Kanaana. Kaj Abraham venis, por funebri pri Sara kaj plori pri ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Kaj Abraham leviĝis for de sia mortintino, kaj diris al la filoj de Ĥet jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Fremdulo kaj pasloĝanto mi estas ĉe vi; donu al mi posedotan lokon por tombo inter vi, por ke mi enterigu mian mortintinon, kiu estas antaŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Kaj la filoj de Ĥet respondis al Abraham, dirante al li:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Aŭskultu nin, nia sinjoro! vi estas princo de Dio inter ni; en la plej elektitaj niaj tomboj enterigu vian mortintinon; neniu el ni rifuzos al vi sian tomblokon, por enterigi vian mortintinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Kaj Abraham leviĝis, kaj profunde kliniĝis antaŭ la popolo de la lando, antaŭ la filoj de Ĥet.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'Kaj li diris al ili jene: Se plaĉas al vi, ke mi enterigu mian mortintinon, kiu estas antaŭ mi, tiam aŭskultu min kaj petu por mi Efronon, la filon de Coĥar,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'ke li donu al mi la duoblan kavernon, kiun li havas en la fino de sia kampo; por plena sumo da mono li donu ĝin al mi inter vi por tomba posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Kaj Efron sidis inter la filoj de Ĥet, kaj respondis Efron la Ĥetido al Abraham aŭdeble por la filoj de Ĥet, antaŭ ĉiuj, kiuj venis en la pordegon de lia urbo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Ne, mia sinjoro, aŭskultu min! la kampon mi donas al vi, kaj la kavernon, kiu estas sur ĝi, al vi mi donas, antaŭ la okuloj de la filoj de mia popolo mi donas ĝin al vi; enterigu vian mortintinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Kaj Abraham profunde kliniĝis antaŭ la popolo de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'Kaj li diris al Efron aŭdeble por la popolo de la lando jene: Mi petas, aŭskultu min: mi donas monon por la kampo; prenu de mi, kaj mi enterigos tie mian mortintinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Kaj Efron respondis al Abraham, dirante al li:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Mia sinjoro, aŭskultu min: la tero valoras kvarcent siklojn; sed kio ĝi estas inter mi kaj vi? enterigu vian mortintinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Kaj Abraham aŭskultis Efronon, kaj Abraham pesis al Efron la monon, pri kiu li parolis aŭdeble por la filoj de Ĥet, kvarcent siklojn da arĝento, uzata en la komerco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Kaj la kampo de Efron kun la duobla kaverno, kiu estis antaŭ Mamre, la kampo kaj la kaverno sur ĝi kaj ĉiuj arboj sur la kampo, inter ĉiuj ĝiaj limoj ĉirkaŭe, fariĝis');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'posedaĵo de Abraham antaŭ la okuloj de la filoj de Ĥet, de ĉiuj, kiuj venis en la pordegon de lia urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Kaj post tio Abraham enterigis sian edzinon Sara en la duobla kaverno de la kampo, antaŭ Mamre, kiu estas Ĥebron, en la lando Kanaana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Kaj la kampo kaj la kaverno sur ĝi fariĝis tomba posedaĵo de Abraham, kiun li akiris de la filoj de Ĥet.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Kaj Abraham estis maljuna kaj en profunda aĝo. Kaj la Eternulo benis Abrahamon en ĉio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Kaj Abraham diris al sia sklavo, la administranto de lia domo, kiu regis ĉion, kio apartenis al li: Metu vian manon sub mian femuron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'kaj mi ĵurigas vin per la Eternulo, la Dio de la ĉielo kaj la Dio de la tero, ke vi ne prenos edzinon por mia filo el la filinoj de la Kanaanidoj, inter kiuj mi loĝas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'sed en mian landon kaj en mian patrujon vi iros kaj vi prenos edzinon por mia filo Isaak.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Kaj la sklavo diris al li: Eble la virino ne volos iri kun mi en ĉi tiun landon; ĉu mi tiam devas revenigi vian filon en la landon, el kiu vi eliris?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Kaj Abraham diris al li: Gardu vin, ne revenigu mian filon tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'La Eternulo, la Dio de la ĉielo, kiu prenis min el la domo de mia patro kaj el mia patrujo, kaj diris al mi kaj ĵuris al mi, dirante: Al via idaro Mi donos ĉi tiun landon-Li sendos Sian anĝelon antaŭ vi, kaj vi prenos edzinon por mia filo el tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Kaj se la virino ne volos iri kun vi, tiam vi fariĝos libera de ĉi tiu mia ĵuro; nur mian filon ne revenigu tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Kaj la sklavo metis sian manon sub la femuron de sia sinjoro Abraham kaj ĵuris al li pri tiu afero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Kaj la sklavo prenis dek kamelojn el la kameloj de sia sinjoro, kaj li iris; kaj ĉiaj bonaĵoj de lia sinjoro estis en liaj manoj. Kaj li leviĝis kaj iris Mezopotamion, al la urbo Naĥor.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Kaj li genuigis la kamelojn ekstere de la urbo, ĉe puto kun akvo, en vespera tempo, en la tempo, kiam eliras la virinoj, por ĉerpi akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Kaj li diris: Ho Eternulo, Dio de mia sinjoro Abraham, sukcesigu min hodiaŭ kaj faru favorkoraĵon al mia sinjoro Abraham.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Jen mi staras apud la fonto da akvo, kaj la filinoj de la urbanoj eliras, por ĉerpi akvon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'kaj la junulinon, al kiu mi diros: Volu klini vian kruĉon, ke mi trinku, kaj ŝi diros: Trinku, kaj mi trinkigos ankaŭ viajn kamelojn-ŝin Vi destinis por Via sklavo Isaak; kaj per tio mi sciiĝos, ke Vi faris favorkoraĵon al mia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Kaj antaŭ ol li finis paroli, jen eliras Rebeka, kiu estis naskita al Betuel, la filo de Milka, edzino de Naĥor, frato de Abraham; kaj ŝia kruĉo estis sur ŝia ŝultro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Kaj la junulino estis tre belaspekta, virgulino, kiun ankoraŭ ne ekkonis viro. Kaj ŝi malsupreniris al la fonto kaj plenigis sian kruĉon kaj iris supren.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Kaj la sklavo kuris al ŝi renkonte, kaj diris: Volu lasi min trinki iom da akvo el via kruĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Kaj ŝi diris: Trinku, mia sinjoro; kaj ŝi rapide mallevis la kruĉon sur sian manon, kaj ŝi donis al li trinki.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Kaj kiam ŝi sufiĉe lin trinkigis, ŝi diris: Ankaŭ por viaj kameloj mi ĉerpos, ĝis ili finos trinki.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Kaj rapide ŝi elverŝis el sia kruĉo en la trinkujon, kaj kuris denove al la puto, por ĉerpi por ĉiuj liaj kameloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Kaj la viro admiris ŝin silente, por konvinkiĝi, ĉu la Eternulo prosperigis lian vojon aŭ ne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Kaj kiam la kameloj ĉesis trinki, tiam la viro prenis oran ringon, havantan la pezon de duono de siklo, kaj du braceletojn por ŝiaj manoj, havantajn la pezon de dek sikloj da oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Kaj li diris: Kies filino vi estas? volu diri al mi; ĉu en la domo de via patro estas loko por ni, por tradormi la nokton?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Kaj ŝi diris al li: Mi estas filino de Betuel, filo de Milka, kiun ŝi naskis al Naĥor.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Kaj ŝi diris al li: Ankaŭ da pajlo kaj da furaĝo ni havas multe, kaj ankaŭ lokon, por ke vi tradormu la nokton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Kaj la viro kliniĝis kaj faris adoron al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'Kaj li diris: Glorata estu la Eternulo, la Dio de mia sinjoro Abraham, kiu ne lasis sen Sia favorkoreco kaj vereco mian sinjoron. Per la vojo, kiun mi iris, la Eternulo alkondukis min al la domo de la frato de mia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Kaj la junulino kuris, kaj rakontis tiujn aferojn en la domo de sia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Kaj Rebeka havis fraton, kiu estis nomata Laban. Kaj Laban kuris al la viro eksteren, al la fonto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Kaj kiam li vidis la ringon kaj la braceletojn sur la manoj de sia fratino, kaj kiam li aŭdis la vortojn de sia fratino Rebeka, kiu diris: Tiel parolis kun mi tiu viro-tiam li iris al la viro, kaj jen tiu staras ĉe la kameloj apud la fonto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Kaj li diris: Venu, benita de la Eternulo; kial vi staras ekstere? mi pretigis la domon kaj ankaŭ lokon por la kameloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Kaj li venigis la viron en la domon, kaj malligis la kamelojn, kaj donis pajlon kaj furaĝon al la kameloj, kaj akvon por lavi liajn piedojn, kaj la piedojn de la homoj, kiuj estis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Kaj estis metita antaŭ li manĝo; sed li diris: Mi ne manĝos, antaŭ ol mi diros mian aferon. Kaj tiu diris: Parolu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Kaj li diris: Sklavo de Abraham mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Kaj la Eternulo forte benis mian sinjoron, kaj li fariĝis granda; kaj Li donis al li ŝafojn kaj bovojn kaj arĝenton kaj oron kaj sklavojn kaj sklavinojn kaj kamelojn kaj azenojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Kaj Sara, la edzino de mia sinjoro, naskis filon al mia sinjoro, kiam ŝi maljuniĝis; kaj li donis al li ĉion, kion li havis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Kaj mia sinjoro ĵurigis min, dirante: Ne prenu edzinon por mia filo el la filinoj de la Kanaanidoj, en kies lando mi loĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Nur al la domo de mia patro iru kaj al mia familio, kaj prenu edzinon por mia filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Kaj mi diris al mia sinjoro: Eble la virino ne volos iri kun mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Kaj li diris al mi: La Eternulo, antaŭ kiu mi iradis, sendos Sian anĝelon kun vi kaj sukcesigos vian vojon; kaj vi prenos edzinon por mia filo el mia familio kaj el la domo de mia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Tiam vi estos libera de mia ĵuro, kiam vi venos al mia familio; kaj se ili ne donos al vi, vi estos libera de mia ĵuro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Kaj mi venis hodiaŭ al la fonto, kaj mi diris: Eternulo, Dio de mia sinjoro Abraham! ho, se Vi volus sukcesigi mian vojon, kiun mi nun iras!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Jen mi staras apud la fonto da akvo; la virgulino, kiu eliros, por ĉerpi, kaj al kiu mi diros: Lasu min trinki iom da akvo el via kruĉo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'kaj kiu diros al mi: Trinku vi, kaj ankaŭ por viaj kameloj mi ĉerpos -tio estas la virino, kiun la Eternulo destinis por la filo de mia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Antaŭ ol mi finis paroli en mia koro, jen Rebeka eliras, kaj ŝia kruĉo estas sur ŝia ŝultro; kaj ŝi malsupreniris al la fonto kaj ĉerpis. Kaj mi diris al ŝi: Volu trinkigi min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Kaj rapide ŝi deprenis sian kruĉon de la ŝultro, kaj diris: Trinku, kaj ankaŭ viajn kamelojn mi trinkigos. Kaj mi trinkis, kaj ankaŭ la kamelojn ŝi trinkigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Kaj mi demandis ŝin, kaj mi diris: Kies filino vi estas? Kaj ŝi diris: Filino de Betuel, filo de Naĥor, kiun naskis al li Milka. Kaj mi metis la ringon sur ŝian nazon kaj la braceletojn sur ŝiajn manojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Kaj mi kliniĝis kaj faris adoron al la Eternulo, kaj mi gloris la Eternulon, la Dion de mia sinjoro Abraham, kiu kondukis min per ĝusta vojo, por ke mi prenu la filinon de la frato de mia sinjoro por lia filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Kaj nun se vi volas fari favorkoraĵon kaj ĝustaĵon al mia sinjoro, diru al mi; kaj se ne, vi ankaŭ diru al mi, kaj mi turnos min dekstren aŭ maldekstren.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Tiam respondis Laban kaj Betuel, kaj diris: De la Eternulo venis ĉi tiu afero; ni ne povas diri al vi ion malbonan aŭ bonan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Jen Rebeka estas antaŭ vi; prenu ŝin kaj iru, kaj ŝi estu edzino al la filo de via sinjoro, kiel diris la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Kaj kiam la sklavo de Abraham aŭdis iliajn vortojn, li kliniĝis ĝis la tero al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Kaj la sklavo elprenis arĝentaĵojn kaj oraĵojn kaj vestojn kaj donis al Rebeka; kaj donacojn li donis al ŝia frato kaj al ŝia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Kaj manĝis kaj trinkis li kaj la homoj, kiuj estis kun li, kaj ili tradormis tie la nokton. Kaj kiam ili leviĝis matene, li diris: Lasu min for al mia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Tiam ŝia frato kaj ŝia patrino diris: La junulino restu kun ni almenaŭ dek tagojn, poste vi iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Kaj li diris al ili: Ne retenu min, ĉar la Eternulo sukcesigis mian vojon. Lasu min for, kaj mi iros al mia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Kaj ili diris: Ni vokos la junulinon, kaj ni demandos, kion ŝi diros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Kaj ili alvokis Rebekan, kaj diris al ŝi: Ĉu vi iros kun ĉi tiu viro? Kaj ŝi diris: Mi iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Kaj ili forsendis sian fratinon Rebeka kaj ŝian nutrintinon kaj la sklavon de Abraham kaj liajn homojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Kaj ili benis Rebekan, kaj diris al ŝi: Nia fratino! miloj da miloj elkresku el vi, kaj via idaro posedu la pordegojn de siaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Kaj leviĝis Rebeka kaj ŝiaj servistinoj kaj sidiĝis sur la kameloj, kaj ili iris post tiu viro; kaj la sklavo prenis Rebekan kaj foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Kaj Isaak venis de la vojo, kiu kondukas al la puto de la Vivanto- Vidanto; li loĝis en la suda lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Kaj Isaak eliris, por mediti sur la kampo, kiam komenciĝis vespero; kaj li levis siajn okulojn kaj vidis, ke jen venas kameloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Kaj Rebeka levis siajn okulojn, kaj ŝi ekvidis Isaakon kaj desaltis de la kamelo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Kaj ŝi diris al la sklavo: Kiu estas tiu viro, kiu iras sur la kampo renkonte al ni? Kaj la sklavo diris: Tio estas mia sinjoro. Kaj ŝi prenis la kovrotukon kaj kovris sin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Kaj la sklavo rakontis al Isaak ĉion, kion li faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Kaj Isaak enkondukis ŝin en la tendon de sia patrino Sara; kaj li prenis Rebekan, kaj ŝi fariĝis lia edzino, kaj li ekamis ŝin. Kaj Isaak konsoliĝis pri sia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Kaj Abraham prenis alian edzinon, kiu estis nomata Ketura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Kaj ŝi naskis al li Zimranon kaj Jokŝanon kaj Medanon kaj Midjanon kaj Jiŝbakon kaj Ŝuaĥon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Kaj de Jokŝan naskiĝis Ŝeba kaj Dedan. Kaj la filoj de Dedan estis la Aŝuridoj, Letuŝidoj, kaj Leumidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Kaj la filoj de Midjan estis Efa kaj Efer kaj Ĥanoĥ kaj Abida kaj Eldaa. Ĉiuj ĉi tiuj estis la filoj de Ketura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Kaj Abraham fordonis ĉion, kion li havis, al Isaak.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Kaj al la filoj de siaj kromvirinoj Abraham donis donacojn, kaj foririgis ilin de sia filo Isaak, ankoraŭ dum sia vivo, orienten, en landon orientan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Kaj la nombro de la jaroj de vivo de Abraham, kiujn li travivis, estis cent sepdek kvin jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Kaj Abraham konsumiĝis kaj mortis en bona maljuneco, profundaĝa kaj sata de vivo, kaj li alkolektiĝis al sia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Kaj enterigis lin liaj filoj Isaak kaj Iŝmael en la duobla kaverno, kiu troviĝas antaŭ Mamre, sur la kampo de Efron, filo de Coĥar, la Ĥetido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'Sur la kampo, kiun aĉetis Abraham de la filoj de Ĥet, tie estas enterigitaj Abraham kaj lia edzino Sara.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Kaj post la morto de Abraham Dio benis lian filon Isaak. Kaj Isaak loĝis ĉe la puto de la Vivanto-Vidanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Kaj jen estas la generaciaro de Iŝmael, filo de Abraham, kiun Hagar, la Egiptino, sklavino de Sara, naskis al Abraham;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'kaj jen estas la nomoj de la filoj de Iŝmael, laŭ iliaj nomoj kaj generacioj: Nebajot, la unuenaskita de Iŝmael, kaj Kedar kaj Adbeel kaj Mibsam');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'kaj Miŝma kaj Duma kaj Masa,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Ĥadad kaj Tema, Jetur, Nafiŝ, kaj Kedma.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Tio estas la filoj de Iŝmael, kaj tio estas iliaj nomoj en iliaj vilaĝoj kaj tendaroj, dek du princoj super siaj gentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Kaj la daŭro de la vivo de Iŝmael estis cent tridek sep jaroj; kaj li konsumiĝis kaj mortis kaj alkolektiĝis al sia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Kaj ili loĝis de Ĥavila ĝis Ŝur, kiu estas antaŭ Egiptujo, sur la vojo al Asirio. Antaŭ ĉiuj siaj fratoj li loĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Kaj jen estas la generaciaro de Isaak, filo de Abraham: de Abraham naskiĝis Isaak.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Kaj Isaak havis la aĝon de kvardek jaroj, kiam li prenis kiel edzinon Rebekan, filinon de Betuel la Siriano, el Mezopotamio, fratinon de Laban la Siriano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Kaj Isaak preĝis al la Eternulo pri sia edzino, ĉar ŝi estis senfrukta; kaj la Eternulo cedis al lia preĝo, kaj lia edzino Rebeka gravediĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Kaj la infanoj interpuŝiĝis en ŝia interno, kaj ŝi diris: Se estas tiel, por kio do mi gravediĝis? Kaj ŝi iris, por demandi la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Kaj la Eternulo diris al ŝi: Du popoloj estas en via ventro, Kaj du gentoj disapartiĝos el via interno; Kaj unu popolo estos pli forta ol la dua, Kaj la pli granda servos la malpli grandan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Kaj kiam venis la tempo, ke ŝi nasku, tiam montriĝis, ke ĝemeloj estas en ŝia ventro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Kaj la unua eliris ruĝa, li estis tuta kiel harkovrita felo; kaj oni donis al li la nomon Esav.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Kaj poste eliris lia frato, tenante per la mano la kalkanon de Esav; kaj oni donis al li la nomon Jakob. Kaj Isaak havis la aĝon de sesdek jaroj, kiam ili naskiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Kaj la knaboj grandiĝis; kaj Esav fariĝis lerta ĉasisto, kampisto, kaj Jakob fariĝis homo kvieta, sidanta en la tendo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Kaj Isaak amis Esavon, ĉar li manĝadis lian ĉasaĵon; sed Rebeka amis Jakobon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Kaj Jakob kuiris kuiraĵon; kaj Esav venis de la kampo kaj estis laca.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Kaj Esav diris al Jakob: Donu al mi manĝi de ĉi tiu ruĝa kuiraĵo, ĉar mi estas laca. Tial oni donis al li la nomon Edom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Kaj Jakob diris: Vendu al mi hodiaŭ vian unuenaskitecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Kaj Esav diris: Jen mi tuj mortos; por kio do mi bezonas la unuenaskitecon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Kaj Jakob diris: Ĵuru al mi hodiaŭ; kaj tiu ĵuris al li kaj vendis sian unuenaskitecon al Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Kaj Jakob donis al Esav panon kaj kuiraĵon el lentoj, kaj li manĝis kaj trinkis, kaj leviĝis kaj foriris. Kaj Esav malŝatis la unuenaskitecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Estis malsato en la lando, krom la antaŭa malsato, kiu estis en la tempo de Abraham. Kaj Isaak iris al Abimeleĥ, la reĝo de la Filiŝtoj, en Gerar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Kaj la Eternulo aperis al li, kaj diris: Ne iru Egiptujon, loĝu en la lando, pri kiu Mi diros al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Vivu kiel fremdulo en ĉi tiu lando, kaj Mi estos kun vi, kaj Mi benos vin; ĉar al vi kaj al via idaro Mi donos ĉiujn ĉi tiujn landojn, kaj Mi plenumos la ĵuron, kiun Mi ĵuris al via patro Abraham.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Kaj Mi multigos vian idaron simile al la steloj de la ĉielo, kaj Mi donos al via idaro ĉiujn ĉi tiujn landojn, kaj beniĝos per via idaro ĉiuj popoloj de la tero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'pro tio, ke Abraham obeis Mian voĉon, kaj plenumadis Miajn aranĝojn, Miajn leĝojn, kaj Miajn instruojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Kaj Isaak ekloĝis en Gerar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Kaj kiam la homoj de tiu loko demandis pri lia edzino, li diris: Ŝi estas mia fratino; ĉar li timis diri: Mia edzino; por ke la homoj de la loko ne mortigu lin pro Rebeka, ĉar ŝi estis belaspekta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Unu fojon, kiam li estis tie jam de longa tempo, Abimeleĥ, la reĝo de la Filiŝtoj, rigardis tra la fenestro, kaj vidis, ke Isaak amuziĝas kun sia edzino Rebeka.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Tiam Abimeleĥ vokis Isaakon, kaj diris: Jen, ŝi estas ja via edzino; kial do vi diris: Ŝi estas mia fratino? Kaj Isaak diris al li: Ĉar mi pensis, ke eble mi mortos pro ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Kaj Abimeleĥ diris: Kion do vi faris al ni! preskaŭ jam kuŝiĝis unu el la popolo kun via edzino, kaj vi venigus sur nin krimon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Kaj Abimeleĥ faris ordonon al la tuta popolo jene: Kiu tuŝos ĉi tiun viron aŭ lian edzinon, tiu mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Kaj Isaak semis en tiu lando, kaj havis en tiu jaro centoble-mezuran rikolton; kaj la Eternulo lin benis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Kaj tiu homo grandiĝis kaj ĉiam pli kaj pli grandiĝadis, ĝis li fariĝis tre granda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Kaj li havis tre multe da brutoj malgrandaj kaj brutoj grandaj kaj grandan servistaron; kaj la Filiŝtoj enviis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Kaj ĉiujn putojn, kiujn elfosis la sklavoj de lia patro en la tempo de lia patro Abraham, la Filiŝtoj ŝtopis kaj plenigis ilin per tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Tiam Abimeleĥ diris al Isaak: Foriru de ni, ĉar vi fariĝis multe pli forta ol ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Kaj Isaak foriris de tie kaj aranĝis siajn tendojn en la valo de Gerar, kaj tie li ekloĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Kaj Isaak denove elfosis la akvoputojn, kiujn oni elfosis en la tempo de lia patro Abraham kaj la Filiŝtoj ŝtopis post la morto de Abraham; kaj li donis al ili tiujn samajn nomojn, kiujn donis al ili lia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Kaj la sklavoj de Isaak fosis en la valo kaj trovis tie puton kun freŝa akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Kaj disputis la paŝtistoj de Gerar kun la paŝtistoj de Isaak, dirante: Al ni apartenas la akvo. Kaj oni donis al la puto la nomon Esek, ĉar oni disputis pri ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Kaj ili elfosis alian puton, kaj ankaŭ pri ĝi ili disputis; kaj oni donis al ĝi la nomon Sitna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Kaj ili foriĝis de tie kaj elfosis alian puton, kaj pri ĝi oni ne disputis. Kaj li donis al ĝi la nomon Reĥobot, dirante: Nun la Eternulo donis al ni vastan lokon, kaj ni multiĝos sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Kaj de tie li formigris al Beer-Ŝeba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Kaj aperis al li la Eternulo en tiu nokto, kaj diris: Mi estas la Dio de via patro Abraham; ne timu, ĉar Mi estas kun vi, kaj Mi benos vin kaj Mi multigos vian idaron pro Abraham, Mia servanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Kaj li konstruis tie altaron kaj preĝis al la Eternulo. Kaj li aranĝis tie sian tendon, kaj la sklavoj de Isaak elfosis tie puton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Kaj Abimeleĥ iris al li el Gerar, kaj ankaŭ lia amiko Aĥuzat kaj lia militestro Piĥol.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Kaj Isaak diris al ili: Por kio vi venis al mi? vi min ja malamas kaj forpelis min de vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Kaj ili diris: Ni vidis, ke la Eternulo estas kun vi; tial ni diris: Estu ĵuro inter ni, inter ni kaj vi, kaj ni faru interligon kun vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'ke vi ne faru al ni malbonon, kiel ni vin ne tuŝis kaj kiel ni faris al vi nur bonon kaj lasis vin foriri en paco; vi estas nun benito de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Kaj li faris por ili festenon, kaj ili manĝis kaj trinkis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Kaj ili leviĝis frue matene kaj ĵuris al si reciproke. Kaj Isaak lasis ilin foriri, kaj ili foriris de li en paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Kaj en tiu tago venis la sklavoj de Isaak, kaj raportis al li pri la puto, kiun ili elfosis, kaj diris al li: Ni trovis akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Kaj li donis al ĝi la nomon Ŝiba; pro tio la nomo de la urbo estas Beer-Ŝeba ĝis hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Kiam Esav havis la aĝon de kvardek jaroj, li prenis kiel edzinojn Jehuditon, filinon de Beeri la Ĥetido, kaj Basmaton, filinon de Elon la Ĥetido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Kaj ili multe ĉagrenis Isaakon kaj Rebekan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Kiam Isaak maljuniĝis kaj la vidado de liaj okuloj malakriĝis, li vokis Esavon, sian pli maljunan filon, kaj diris al li: Mia filo! Kaj tiu diris al li: Jen mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Kaj li diris: Jen mi maljuniĝis; mi ne scias, kiam mi mortos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'prenu do nun viajn armilojn, vian sagujon kaj vian pafarkon, kaj iru sur la kampon kaj ĉasu por mi ĉasaĵon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'kaj faru por mi bongustan manĝaĵon, kian mi amas, kaj alportu al mi, kaj mi ĝin manĝos, por ke mia animo vin benu, antaŭ ol mi mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Sed Rebeka aŭdis, kiam Isaak parolis al sia filo Esav. Kaj Esav iris sur la kampon, por ĉasi ĉasaĵon kaj alporti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Kaj Rebeka diris al sia filo Jakob jene: Mi aŭdis, ke via patro diris al via frato Esav jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Alportu al mi ĉasaĵon kaj faru por mi bongustan manĝaĵon, kaj mi manĝos, kaj mi benos vin antaŭ la Eternulo antaŭ mia morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Kaj nun, mia filo, aŭskultu mian voĉon, kion mi ordonas al vi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'iru al la brutaro kaj alportu al mi de tie du bonajn kapridojn, kaj mi faros el ili bongustan manĝaĵon por via patro, kian li amas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'kaj vi alportos al via patro, kaj li manĝos, por ke li benu vin antaŭ sia morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Kaj Jakob diris al sia patrino Rebeka: Mia frato Esav estas ja homo harkovrita, kaj mi estas homo glata;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'eble mia patro min palpos, tiam mi estos en liaj okuloj kiel trompanto, kaj mi venigos sur min malbenon, sed ne benon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Kaj lia patrino diris al li: Sur mi estu tiu malbeno, mia filo; nur aŭskultu mian voĉon kaj iru, alportu al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Kaj li iris kaj prenis kaj alportis al sia patrino, kaj lia patrino faris bongustan manĝaĵon, kian amis lia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Kaj Rebeka prenis la luksajn vestojn de sia pli maljuna filo Esav, kiujn ŝi havis ĉe si en la domo, kaj ŝi vestis sian pli junan filon Jakob;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'kaj per la feloj de la kapridoj ŝi vestis liajn manojn kaj la glataĵon de lia kolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Kaj ŝi donis la bongustan manĝaĵon kaj la panon, kiujn ŝi pretigis, en la manon de sia filo Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Kaj li venis al sia patro, kaj diris: Mia patro! Kaj tiu diris: Jen mi estas; kiu vi estas, mia filo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Kaj Jakob diris al sia patro: Mi estas Esav, via unuenaskito; mi faris, kiel vi diris al mi; volu leviĝi, sidiĝu, kaj manĝu mian ĉasaĵon, por ke via animo min benu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Kaj Isaak diris al sia filo: Kiamaniere vi tiel rapide trovis, mia filo? Kaj tiu diris: Ĉar la Eternulo, via Dio, sendis al mi renkonte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Kaj Isaak diris al Jakob: Alproksimiĝu, kaj mi vin palpos, mia filo, ĉu tio estas vi, mia filo Esav, aŭ ne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Kaj Jakob alproksimiĝis al sia patro Isaak, kaj tiu lin palpis, kaj diris: La voĉo estas voĉo de Jakob, sed la manoj estas manoj de Esav.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Kaj li ne rekonis lin, ĉar liaj manoj estis kiel la manoj de lia frato Esav, harkovritaj; kaj li benis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Kaj li diris: Ĉu tio estas vi, mia filo Esav? Kaj tiu diris: Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Kaj li diris: Alŝovu al mi, kaj mi manĝos la ĉasaĵon de mia filo, por ke mia animo vin benu. Kaj li alŝovis al li, kaj tiu manĝis; kaj li alportis al li vinon, kaj tiu trinkis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Kaj lia patro Isaak diris al li: Alproksimiĝu kaj kisu min, mia filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Kaj li alproksimiĝis kaj kisis lin, kaj tiu flaris la odoron de liaj vestoj, kaj li benis lin, kaj diris: Vidu, la odoro de mia filo Estas kiel la odoro de kampo, kiun la Eternulo benis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Dio donu al vi roson ĉielan Kaj grason de la tero Kaj multe da greno kaj mosto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Popoloj vin servu, Kaj gentoj kliniĝu antaŭ vi; Estu sinjoro super viaj fratoj, Kaj kliniĝu antaŭ vi la filoj de via patrino; Viaj malbenantoj estu malbenataj, Kaj viaj benantoj estu benataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Kaj kiam Isaak finis beni Jakobon kaj apenaŭ Jakob eliris de antaŭ sia patro Isaak, lia frato Esav venis de sia ĉasado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Kaj ankaŭ li faris bongustan manĝaĵon kaj alportis al sia patro, kaj diris al sia patro: Leviĝu, mia patro, kaj manĝu la ĉasaĵon de via filo, por ke via animo min benu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Kaj lia patro Isaak diris al li: Kiu vi estas? Kaj li diris: Mi estas via unuenaskita filo Esav.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Tiam Isaak ektremis per tre granda tremo, kaj diris: Kiu do estas tiu, kiu ĉasis ĉasaĵon kaj alportis al mi, kaj mi manĝis de ĉio, antaŭ ol vi venis, kaj mi benis lin? kaj li restos ja benita!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Kiam Esav aŭdis la vortojn de sia patro, li ekkriis per tre granda kaj maldolĉa krio, kaj diris al sia patro: Benu ankaŭ min, ho mia patro!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Kaj tiu diris: Via frato venis kun ruzo kaj prenis vian benon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Kaj li diris: Ĝuste do lia nomo estas Jakob, ĉar li submetis al mi la piedon jam du fojojn; mian unuenaskitecon li prenis, kaj jen li nun prenis mian benon! Kaj li diris: Ĉu vi ne rezervis por mi benon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Kaj Isaak respondis kaj diris al Esav: Jen mi faris lin sinjoro super vi, kaj ĉiujn liajn fratojn mi donis al li kiel servantojn, kaj grenon kaj moston mi havigis al li; kion do mi faros por vi, mia filo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Kaj Esav diris al sia patro: Ĉu ĝi estas la sola beno, kiun vi havas? benu ankaŭ min, ho mia patro! Kaj Esav ekploris per laŭta voĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Kaj lia patro Isaak respondis kaj diris al li: Jen la graso de la tero estu en via loko de loĝado Kaj la ĉiela roso de supre;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Kaj per via glavo vi vivos, kaj vian fraton vi servos; Sed kiam vi kontraŭbatalos, Vi deĵetos lian jugon de via kolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Kaj Esav ekmalamis Jakobon pro la beno, per kiu benis lin lia patro; kaj Esav diris en sia koro: Baldaŭ venos la tagoj de funebro pro mia patro, tiam mi mortigos mian fraton Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Kaj oni raportis al Rebeka la vortojn de ŝia pli maljuna filo Esav; tiam ŝi sendis kaj vokis sian pli junan filon Jakob, kaj diris al li: Jen via frato Esav minacas mortigi vin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'tial nun, mia filo, aŭskultu mian voĉon; kaj leviĝu, forkuru al mia frato Laban en Ĥaran;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'kaj loĝu ĉe li kelkan tempon, ĝis kvietiĝos la furiozo de via frato;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'ĝis la kolero de via frato deturniĝos de vi, kaj li forgesos, kion vi faris al li. Tiam mi sendos kaj prenos vin de tie. Kial mi perdu vin ambaŭ en unu tago?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Kaj Rebeka diris al Isaak: Tedis al mi la vivo pro la Ĥetidinoj; se Jakob prenos edzinon el ĉi tiuj Ĥetidinoj, el la filinoj de la lando, tiam por kio mi vivu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Tiam Isaak alvokis Jakobon kaj benis lin, kaj ordonis al li, dirante: Ne prenu edzinon el la filinoj Kanaanaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Leviĝu, iru Mezopotamion, al la domo de Betuel, la patro de via patrino, kaj prenu al vi el tie edzinon el la filinoj de Laban, la frato de via patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Kaj Dio la Plejpotenca benu vin kaj fruktigu vin kaj multigu vin, kaj kreskigu el vi amason da popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Kaj Li donu al vi la benon de Abraham, al vi kaj al via idaro kune kun vi, por ke vi heredu la landon de via fremdeloĝado, kiun Dio donis al Abraham.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Kaj Isaak forsendis Jakobon, kaj tiu iris Mezopotamion, al Laban, la filo de Betuel la Siriano, frato de Rebeka, patrino de Jakob kaj Esav.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Kiam Esav vidis, ke Isaak benis Jakobon kaj sendis lin en Mezopotamion, por ke li prenu al si el tie edzinon, kaj ke, benante lin, li ordonis al li, dirante: Ne prenu edzinon el la filinoj Kanaanaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'kaj ke Jakob obeis sian patron kaj sian patrinon kaj iris Mezopotamion:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'tiam Esav vidis, ke ne plaĉas la filinoj Kanaanaj al lia patro Isaak.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Kaj Esav iris al Iŝmael kaj prenis al si Maĥalaton, filinon de Iŝmael, filo de Abraham, fratinon de Nebajot, kiel edzinon krom siaj aliaj edzinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Kaj Jakob eliris el Beer-Ŝeba kaj iris en la direkto al Ĥaran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Li venis al iu loko kaj restis tie, por pasigi la nokton, ĉar la suno subiris. Kaj li prenis unu el la ŝtonoj de tiu loko kaj metis ĝin sub sian kapon kaj kuŝiĝis en tiu loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Kaj li sonĝis: jen ŝtuparo staras sur la tero, kaj ĝia supro atingas la ĉielon, kaj jen anĝeloj de Dio iras sur ĝi supren kaj malsupren.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Kaj jen la Eternulo staras sur ĝi, kaj diras: Mi estas la Eternulo, la Dio de via patro Abraham kaj la Dio de Isaak; la teron, sur kiu vi kuŝas, Mi donos al vi kaj al via idaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Kaj via idaro estos kiel la polvo de la tero, kaj vi disvastiĝos okcidenten kaj orienten kaj norden kaj suden, kaj beniĝos per vi kaj per via idaro ĉiuj gentoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Kaj Mi estas kun vi, kaj Mi gardos vin ĉie, kien vi iros, kaj Mi revenigos vin sur ĉi tiun teron; ĉar Mi ne forlasos vin, ĝis Mi estos farinta tion, kion Mi diris al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Kaj Jakob vekiĝis el sia dormo, kaj li diris: Vere, la Eternulo estas en ĉi tiu loko, kaj mi ne sciis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Kaj li ektimis, kaj diris: Kiel timinda estas ĉi tiu loko! ĝi estas nenio alia ol domo de Dio, kaj ĉi tie estas la pordego de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Kaj Jakob leviĝis frue matene, kaj prenis la ŝtonon, kiun li estis metinta sub sian kapon, kaj starigis ĝin kiel monumenton, kaj verŝis oleon sur ĝian supron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Kaj li donis al tiu loko la nomon Bet-El; sed antaŭe la nomo de la urbo estis Luz.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Kaj Jakob faris sanktan promeson, dirante: Se Dio estos kun mi, kaj gardos min sur ĉi tiu vojo, kiun mi iras, kaj donos al mi panon por manĝi kaj veston por porti sur mi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'kaj mi revenos en paco al la domo de mia patro, kaj la Eternulo estos por mi Dio:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'tiam ĉi tiu ŝtono, kiun mi starigis kiel monumenton, estos domo de Dio, kaj de ĉio, kion Vi donos al mi, mi oferos al Vi dekonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Kaj Jakob levis siajn piedojn kaj iris al la lando de la orientanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Kaj li vidis: jen estas puto sur la kampo, kaj tri gregoj da ŝafoj kuŝas apud ĝi; ĉar el tiu puto oni trinkigadis la gregojn; kaj granda ŝtono estis sur la aperturo de la puto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Kaj kiam tie kunvenis ĉiuj gregoj, tiam oni deruladis la ŝtonon de sur la aperturo kaj trinkigadis la ŝafojn kaj denove remetadis la ŝtonon sur ĝian lokon, sur la aperturon de la puto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Kaj Jakob diris al ili: Fratoj miaj, ke kie vi estas? Kaj ili diris: Ni estas el Ĥaran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Kaj li diris al ili: Ĉu vi konas Labanon, filon de Naĥor? Kaj ili diris: Ni konas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Kaj li diris al ili: Ĉu li bone fartas? Kaj ili diris: Li fartas bone, kaj jen lia filino Raĥel venas kun la ŝafoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Kaj li diris: De la tago restas ja ankoraŭ multe, ankoraŭ ne estas la tempo, por kolekti la gregojn; trinkigu la ŝafojn kaj iru, paŝtu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Kaj ili diris: Ni ne povas, ĝis kolektiĝos ĉiuj gregoj kaj oni derulos la ŝtonon de sur la aperturo de la puto kaj ni trinkigos la ŝafojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Dum li ankoraŭ parolis kun ili, venis Raĥel kun la ŝafoj de sia patro, ĉar ŝi paŝtis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Kaj kiam Jakob ekvidis Raĥelon, la filinon de Laban, frato de lia patrino, kaj la ŝafojn de Laban, frato de lia patrino, tiam Jakob alproksimiĝis, derulis la ŝtonon de sur la aperturo de la puto, kaj trinkigis la ŝafojn de Laban, la frato de lia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Kaj Jakob kisis Raĥelon kaj laŭte ekploris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Kaj Jakob diris al Raĥel, ke li estas parenco de ŝia patro kaj filo de Rebeka. Kaj ŝi kuris kaj diris al sia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Kaj kiam Laban aŭdis la sciigon pri Jakob, filo de lia fratino, li kuris al li renkonte kaj ĉirkaŭprenis lin kaj kisis lin kaj venigis lin en sian domon. Kaj tiu rakontis al Laban ĉion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Kaj Laban diris al li: Vi estas ja mia osto kaj mia karno! Kaj li loĝis ĉe li tutan monaton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Kaj Laban diris al Jakob: Ĉu pro tio, ke vi estas mia parenco, vi devas servi min senpage? diru al mi, kion mi devas pagi al vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Sed Laban havis du filinojn; la nomo de la pli maljuna estis Lea, kaj la nomo de la pli juna estis Raĥel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'La okuloj de Lea estis malsanaj, sed Raĥel estis belforma kaj belvizaĝa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Kaj Jakob ekamis Raĥelon, kaj diris: Mi servos vin sep jarojn pro Raĥel, via pli juna filino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Tiam Laban diris: Pli bone estas, ke mi donu ŝin al vi, ol ke mi donu ŝin al alia viro; loĝu ĉe mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Kaj Jakob servis pro Raĥel sep jarojn, kaj ili estis en liaj okuloj kiel kelke da tagoj, ĉar li amis ŝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Kaj Jakob diris al Laban: Donu mian edzinon, ĉar finiĝis mia tempo, kaj mi envenos al ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Kaj Laban kunvenigis ĉiujn homojn de tiu loko kaj faris festenon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Sed vespere li prenis sian filinon Lea kaj enirigis ŝin al li; kaj tiu envenis al ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Kaj Laban donis sian sklavinon Zilpa al Lea kiel sklavinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Sed matene montriĝis, ke tio estas Lea. Tiam li diris al Laban: Kion do vi faris al mi! ĉu ne pro Raĥel mi servis vin? kial do vi min trompis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Tiam Laban diris: En nia loko ne estas moro, ke oni donu la pli junan antaŭ ol la pli maljunan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Pasigu semajnon kun ĉi tiu, tiam mi donos al vi ankaŭ tiun, pro servo, kiun vi servos ĉe mi ankoraŭ aliajn sep jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Kaj Jakob faris tiel kaj pasigis semajnon kun ĉi tiu. Kaj Laban donis al li sian filinon Raĥel kiel edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Kaj Laban donis al sia filino Raĥel sian sklavinon Bilha kiel sklavinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Kaj Jakob envenis ankaŭ al Raĥel, kaj li amis Raĥelon pli ol Lean, kaj li servis ĉe li ankoraŭ aliajn sep jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Kiam la Eternulo vidis, ke Lea estas malamata, Li malŝlosis ŝian uteron; sed Raĥel estis senfrukta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Kaj Lea gravediĝis kaj naskis filon, kaj ŝi donis al li la nomon Ruben, ĉar ŝi diris: La Eternulo vidis mian mizeron, kaj nun mia edzo min amos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Kaj ŝi denove gravediĝis kaj naskis filon. Kaj ŝi diris: La Eternulo aŭdis, ke mi estas malamata, tial Li donis al mi ankaŭ ĉi tiun; kaj ŝi donis al li la nomon Simeon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Kaj ŝi denove gravediĝis kaj naskis filon. Kaj ŝi diris: La nunan fojon mia edzo aliĝos al mi, ĉar mi naskis al li tri filojn; tial al li estis donita la nomo Levi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Kaj ŝi denove gravediĝis kaj naskis filon. Kaj ŝi diris: Nun mi dankos la Eternulon; tial ŝi donis al li la nomon Jehuda. Kaj ŝi ĉesis naski.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Kiam Raĥel vidis, ke ŝi ne naskas al Jakob, ŝi enviis sian fratinon, kaj ŝi diris al Jakob: Donu al mi infanojn, ĉar alie mi mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Kaj Jakob forte ekkoleris Raĥelon, kaj li diris: Ĉu mi anstataŭas Dion, kiu rifuzis al vi frukton de ventro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Kaj ŝi diris: Jen estas mia sklavino Bilha; envenu al ŝi, ke ŝi nasku sur miaj genuoj kaj ke mi ankaŭ ricevu filojn per ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Kaj ŝi donis al li sian sklavinon Bilha kiel edzinon, kaj Jakob envenis al ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Kaj Bilha gravediĝis kaj naskis al Jakob filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Kaj Raĥel diris: Dio min juĝis kaj aŭdis mian voĉon kaj donis al mi filon; tial ŝi donis al li la nomon Dan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Kaj Bilha, la sklavino de Raĥel, denove gravediĝis kaj naskis duan filon al Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Tiam Raĥel diris: Per Dia lukto mi luktis kun mia fratino, kaj mi venkis; kaj ŝi donis al li la nomon Naftali.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Kiam Lea vidis, ke ŝi ĉesis naski, ŝi prenis sian sklavinon Zilpa kaj donis ŝin al Jakob kiel edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Kaj Zilpa, la sklavino de Lea, naskis al Jakob filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Kaj Lea diris: Venis feliĉo! kaj ŝi donis al li la nomon Gad.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Kaj Zilpa, la sklavino de Lea, naskis duan filon al Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Kaj Lea diris: Por mia bono; ĉar la virinoj diros, ke estas al mi bone. Kaj ŝi donis al li la nomon Aŝer.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Ruben iris en la tempo de rikoltado de tritiko kaj trovis mandragorojn sur la kampo, kaj li alportis ilin al sia patrino Lea. Kaj Raĥel diris al Lea: Donu al mi el la mandragoroj de via filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Sed tiu diris al ŝi: Ĉu ne sufiĉas al vi, ke vi prenis mian edzon, kaj vi volas preni ankaŭ la mandragorojn de mia filo? Tiam Raĥel diris: Nu, li kuŝu kun vi ĉi tiun nokton por la mandragoroj de via filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Kiam Jakob venis de la kampo vespere, Lea eliris al li renkonte, kaj diris: Al mi venu, ĉar mi aĉetis vin per la mandragoroj de mia filo. Kaj li kuŝis kun ŝi en tiu nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Kaj Dio aŭdis Lean, kaj ŝi gravediĝis kaj naskis al Jakob kvinan filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Kaj Lea diris: Dio donis al mi rekompencon por tio, ke mi donis mian sklavinon al mia edzo; kaj ŝi donis al li la nomon Isaĥar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Kaj Lea denove gravediĝis kaj naskis sesan filon al Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Kaj Lea diris: Havigis al mi Dio bonan havon; nun mia edzo loĝos ĉe mi, ĉar mi naskis al li ses filojn. Kaj ŝi donis al li la nomon Zebulun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Kaj poste ŝi naskis filinon, kaj ŝi donis al ŝi la nomon Dina.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Kaj Dio rememoris Raĥelon, kaj Dio elaŭdis ŝin kaj malŝlosis ŝian uteron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Kaj ŝi gravediĝis kaj naskis filon. Kaj ŝi diris: Dio forprenis mian malhonoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Kaj ŝi donis al li la nomon Jozef, dirante: La Eternulo aldonos al mi alian filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Kiam Raĥel naskis Jozefon, Jakob diris al Laban: Forliberigu min, kaj mi iros al mia loko kaj al mia lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Donu miajn edzinojn kaj miajn infanojn, pro kiuj mi servis vin, kaj mi iros; ĉar vi konas la servon, per kiu mi vin servis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Kaj Laban diris al li: Ho, se mi povus akiri vian favoron! mi spertis, ke la Eternulo benis min pro vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Kaj li diris: Difinu, kian rekompencon mi ŝuldas al vi, kaj mi donos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Kaj tiu diris al li: Vi scias, kiel mi servis vin kaj kia fariĝis via brutaro ĉe mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'ĉar malmulte vi havis antaŭ mi, sed nun ĝi multe vastiĝis; kaj la Eternulo benis vin post mia veno; kaj nun kiam mi laboros ankaŭ por mia domo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Kaj Laban diris: Kion mi donu al vi? Kaj Jakob diris: Donu al mi nenion; sed se vi faros al mi jenon, tiam mi denove paŝtos kaj gardos viajn ŝafojn:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'mi pasos hodiaŭ tra via tuta ŝafaro; apartigu el ĝi ĉiun ŝafon mikskoloran kaj makulitan kaj ĉiun bruton nigran inter la ŝafoj, kaj makulitan kaj mikskoloran inter la kaproj; kaj ili estu mia rekompenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Kaj respondos por mi mia justeco en la morgaŭa tago, kiam vi venos vidi mian rekompencon; ĉiu el la kaproj, kiu ne estos mikskolora aŭ makulita, kaj ĉiu el la ŝafoj, kiu ne estos nigra, estu rigardata kiel ŝtelita de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Kaj Laban diris: Ĝi estu, kiel vi diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Kaj li apartigis en tiu tago la virkaprojn striitajn kaj makulitajn kaj ĉiujn kaprinojn mikskolorajn kaj makulitajn, ĉiujn, kiuj havis sur si iom da blankaĵo, kaj ĉiujn nigrajn ŝafojn; kaj li transdonis ilin en la manojn de siaj filoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Kaj li faris interspacon de tritaga irado inter si kaj Jakob. Kaj Jakob paŝtis la restintajn ŝafojn de Laban.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Kaj Jakob prenis al si bastonojn el verdaj poploj, migdalarboj, kaj platanarboj, kaj senŝeligis sur ili blankajn striojn tiamaniere, ke la blankaĵo sur la bastonoj elmontriĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Kaj li metis la skrapitajn bastonojn antaŭ la ŝafoj en la akvotrinkigajn kanalojn, al kiuj la ŝafoj venadis por trinki, kaj ili gravediĝadis, kiam ili venadis trinki.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Kaj la ŝafoj gravediĝis super la bastonoj, kaj ili naskis ŝafidojn striitajn, mikskolorajn, kaj makulitajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Kaj la ŝafidojn Jakob apartigis, kaj li turnis la vizaĝojn de la brutoj kontraŭ la striitajn kaj kontraŭ la nigrajn brutojn de Laban; sed siajn brutarojn li apartigis kaj ne almiksis ilin al la brutoj de Laban.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Ĉiufoje, kiam pasiiĝis brutoj fortaj, Jakob metis la bastonojn en la kanalojn antaŭ la okuloj de la brutoj, por ke ili pasiiĝu antaŭ la bastonoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'sed kiam la brutoj estis malfortaj, li ne metis. Tiamaniere la malfortaj fariĝis apartenaĵo de Laban, kaj la fortaj fariĝis apartenaĵo de Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Kaj tiu homo fariĝis eksterordinare riĉa, kaj li havis multe da brutoj kaj sklavinojn kaj sklavojn kaj kamelojn kaj azenojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Li aŭdis, ke la filoj de Laban parolis jene: Jakob forprenis la tutan havon de nia patro, kaj el la havo de nia patro li akiris la tutan riĉecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Kaj Jakob vidis laŭ la vizaĝo de Laban, ke li ne estas rilate al li tia, kia li estis hieraŭ kaj antaŭhieraŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Kaj la Eternulo diris al Jakob: Reiru en la landon de viaj patroj kaj en vian naskiĝlandon, kaj Mi estos kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Tiam Jakob sendis kaj vokis Raĥelon kaj Lean sur la kampon al sia brutaro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'kaj li diris al ili: Mi vidas laŭ la vizaĝo de via patro, ke li ne estas rilate al mi tia, kia li estis hieraŭ kaj antaŭhieraŭ; sed la Dio de mia patro estis kun mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Vi scias, ke per ĉiuj miaj fortoj mi servis vian patron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Sed via patro trompis min kaj dekfoje ŝanĝis mian laborpagon; tamen Dio ne lasis lin fari al mi malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Kiam li diris: Mikskoloraj estu via rekompenco-ĉiuj brutoj naskis idojn mikskolorajn; kaj kiam li diris: Striitaj estu via rekompenco-ĉiuj brutoj naskis striitajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Tiamaniere Dio forprenis la brutojn de via patro kaj donis al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'En la tempo, kiam la brutoj pasiiĝis, mi levis miajn okulojn kaj vidis en sonĝo, ke la virbestoj, kiuj leviĝis sur la brutojn, estas striitaj, mikskoloraj, kaj makulitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Kaj anĝelo de Dio diris al mi en la sonĝo: Jakob! kaj mi diris: Jen mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Kaj li diris: Levu viajn okulojn kaj vidu: ĉiuj virbestoj, kiuj leviĝis sur la brutojn, estas striitaj, mikskoloraj, kaj makulitaj, ĉar Mi vidis ĉion, kion Laban faras al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Mi estas la Dio el Bet-El, kie vi verŝis oleon sur la monumenton kaj kie vi faris sanktan promeson al Mi. Nun leviĝu, eliru el ĉi tiu lando kaj reiru en la landon de via naskiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Kaj Raĥel kaj Lea respondis kaj diris al li: Ĉu ni havas ankoraŭ parton kaj heredon en la domo de nia patro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Li rigardas ja nin kiel fremdulinojn; ĉar li vendis nin kaj eĉ formanĝis nian monon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Ĉar la tuta riĉo, kiun Dio forprenis de nia patro, apartenas al ni kaj al niaj infanoj. Kaj nun ĉion, kion Dio al vi diris, faru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Jakob leviĝis, kaj metis siajn infanojn kaj siajn edzinojn sur la kamelojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'Kaj li forkondukis sian tutan brutaron kaj sian tutan havon, kiun li akiris, sian propraĵon, kiun li akiris en Mezopotamio, por iri al sia patro Isaak en la landon Kanaanan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Laban estis foririnta, por tondi siajn ŝafojn; tiam Raĥel ŝtelis la domajn diojn de sia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Jakob trompis la atenton de Laban la Siriano, ne dirante al li, ke li forkuras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Kaj li rapide foriris kune kun ĉio, kion li havis. Kaj li transpasis la Riveron kaj direktiĝis al la monto Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Oni diris al Laban en la tria tago, ke Jakob forkuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Tiam li prenis kun si siajn fratojn, kaj kuris post li distancon de sep tagoj kaj kuratingis lin sur la monto Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Tiam Dio aperis al Laban la Siriano nokte en la sonĝo, kaj diris al li: Gardu vin, ke vi ne parolu kun Jakob bone nek malbone.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Laban kuratingis Jakobon. Jakob starigis sian tendon sur la monto, kaj Laban aranĝis siajn fratojn ankaŭ sur la monto Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Kaj Laban diris al Jakob: Kion vi faris? vi trompis min kaj forkondukis miajn filinojn kvazaŭ militkaptitojn!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Kial vi forkuris sekrete kaj kaŝe de mi, kaj ne diris al mi? Mi foririgus vin en gajeco kaj kun kantoj, kun tamburino kaj harpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Vi eĉ ne lasis min kisi miajn infanojn kaj filinojn! malsaĝe vi agis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Mi havas forton en mia mano, por fari al vi malbonon; sed la Dio de via patro hieraŭ diris al mi jene: Gardu vin, ke vi ne parolu kun Jakob bone aŭ malbone.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Kaj se vi nun foriris, ĉar vi forte deziris esti en la domo de via patro, kial do vi ŝtelis miajn diojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Tiam Jakob respondis kaj diris al Laban: Mi timis; mi pensis, ke eble vi forrabos de mi viajn filinojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Sed tiu, ĉe kiu vi trovos viajn diojn, mortu. En la ĉeesto de niaj parencoj serĉu ĉe mi tion, kio estas via, kaj prenu al vi. Jakob ne sciis, ke Raĥel ilin ŝtelis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Tiam Laban eniris en la tendon de Jakob kaj en la tendon de Lea kaj en la tendon de la du sklavinoj, kaj li ne trovis. Kaj li eliris el la tendo de Lea kaj eniris en la tendon de Raĥel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Sed Raĥel prenis la domajn diojn kaj metis ilin sub la selon de la kamelo kaj sidiĝis sur ili. Kaj Laban palpe esploris la tutan tendon kaj ne trovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Kaj ŝi diris al sia patro: Mia sinjoro ne koleru, ke mi ne povas stariĝi antaŭ vi, ĉar mi havas la virinan ordinaraĵon. Kaj li serĉis kaj ne trovis la domajn diojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Kaj Jakob ekkoleris kaj disputis kun Laban. Kaj Jakob diris al Laban: Kia estas mia kulpo, kia estas mia peko, ke vi persekutas min?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Vi trapalpis ĉiujn miajn apartenaĵojn; kion vi trovis el la apartenaĵoj de via domo? elmetu ĉi tie antaŭ miaj parencoj kaj viaj, kaj ili juĝu inter ni ambaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Jam dudek jarojn mi estas ĉe vi; viaj ŝafoj kaj kaproj ne estis seninfanaj; la virŝafojn el via brutaro mi ne manĝis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'kion sovaĝaj bestoj disŝiris, tion mi ne alportis al vi: ĝi estis mia malprofito; de mi vi postulis ĉion, kio estis ŝtelita en tago aŭ ŝtelita en nokto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'dum la tago min konsumis la varmego, kaj dum la nokto la malvarmo; kaj dormo kuris for de miaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Tiaj estis la dudek jaroj, dum kiuj mi servis vin en via domo, dek kvar jarojn pro viaj du filinoj kaj ses jarojn pro viaj brutoj; kaj vi ŝanĝis mian laborpagon dekfoje.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Se ne estus kun mi la Dio de mia patro, la Dio de Abraham kaj Timo de Isaak, vi nun foririgus min kun nenio. Mian mizeron kaj la laboron de miaj manoj vidis Dio kaj ĝustigis vin hieraŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Tiam Laban respondis kaj diris al Jakob: La filinoj estas miaj filinoj, kaj la infanoj estas miaj infanoj, kaj la brutoj estas miaj brutoj, kaj ĉio, kion vi vidas, estas mia; sed kion mi povas fari hodiaŭ al miaj filinoj, kaj al iliaj infanoj, kiujn ili naskis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Nun ni faru interligon, mi kaj vi, kaj ĝi estu atesto inter mi kaj vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Tiam Jakob prenis ŝtonon kaj starigis ĝin kiel memorsignon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Kaj Jakob diris al siaj parencoj: Kolektu ŝtonojn. Kaj ili prenis ŝtonojn kaj faris monteton; kaj ili manĝis tie sur la monteto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Kaj Laban donis al ĝi la nomon Jegar-Sahaduta, sed Jakob donis al ĝi la nomon Galeed.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Laban diris: Ĉi tiu monteto estu nun atesto inter mi kaj vi; tial ĝi ricevis la nomon Galeed;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'ankaŭ la nomon Micpa; ĉar li diris: Dio observu inter mi kaj vi, kiam ni malaperos unu de la alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Se vi agos malbone kontraŭ miaj filinoj kaj se vi prenos aliajn edzinojn krom miaj filinoj, tiam, se neniu estos ĉe ni, vidu, ke Dio estas atestanto inter mi kaj vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Kaj Laban diris al Jakob: Jen estas ĉi tiu monteto, kaj jen estas la memorsigno, kiun mi starigis inter mi kaj vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'atesto estu ĉi tiu monteto, kaj atesto estu la memorsigno, ke mi ne transiros al vi trans ĉi tiun monteton kaj vi ne transiros al mi trans ĉi tiun monteton kaj trans la memorsignon por malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'La Dio de Abraham kaj la Dio de Naĥor juĝu inter ni, la Dio de ilia patro. Kaj Jakob ĵuris al li per la Timo de sia patro Isaak.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Kaj Jakob oferbuĉis oferon sur la monto, kaj li invitis siajn parencojn manĝi panon; kaj ili manĝis panon kaj tradormis la nokton sur la monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Laban leviĝis frue matene kaj kisis siajn infanojn kaj siajn filinojn kaj benis ilin, kaj foriris; kaj Laban reiris al sia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Kaj Jakob iris sian vojon. Kaj renkontiĝis kun li anĝeloj de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Kaj Jakob diris, kiam li ilin vidis: Tio estas militistaro de Dio; kaj li donis al tiu loko la nomon Maĥanaim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Jakob sendis antaŭ si senditojn al sia frato Esav, en la landon Seir, en la regionon de Edom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Kaj li ordonis al ili jene: Tiele diru al mia sinjoro Esav: Jen kion diris via sklavo Jakob: Mi loĝis ĉe Laban kaj restis tie ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Mi havas bovojn kaj azenojn, ŝafojn kaj sklavojn kaj sklavinojn; kaj mi sendas, por sciigi mian sinjoron, por ke mi akiru vian favoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Kaj la senditoj revenis al Jakob, kaj diris: Ni venis al via frato Esav; li iras renkonte al vi, kaj kvarcent homoj iras kune kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Tiam Jakob tre ektimis kaj afliktiĝis. Kaj li dividis la homojn, kiuj estis kun li, kaj la ŝafojn kaj la bovojn kaj la kamelojn, en du taĉmentojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'kaj li diris: Se Esav venos al unu taĉmento kaj venkobatos ĝin, tiam la restinta taĉmento sin savos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Kaj Jakob diris: Dio de mia patro Abraham kaj Dio de mia patro Isaak, Eternulo, kiu diris al mi: Reiru en vian landon kaj en vian naskiĝlokon, kaj Mi faros al vi bonon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'mi estas tro malgranda por ĉiuj favorkoraĵoj kaj por la tuta bonaĵo, kiun Vi faris al Via sklavo; ĉar kun mia bastono mi transiris ĉi tiun Jordanon, kaj nun mi havas du taĉmentojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Savu min de la mano de mia frato, de la mano de Esav; ĉar mi timas lin, ke li eble venos kaj mortigos ĉe mi patrinon kun la infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Vi diris ja: Mi faros al vi bonon, kaj Mi faros vian idaron tia, kia estas la apudmara sablo, kiun oni ne povas kalkuli pro multegeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Kaj li pasigis tie la nokton. Kaj li prenis el tio, kion li havis sub la mano, donacon por sia frato Esav:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'ducent kaprinojn kaj dudek virkaprojn, ducent ŝafinojn kaj dudek virŝafojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'tridek mamnutrantajn kamelojn kun iliaj idoj, kvardek bovinojn kaj dek virbovojn, dudek azeninojn kaj dek azenidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Kaj li transdonis en la manojn de siaj sklavoj ĉiun gregon aparte, kaj li diris al siaj sklavoj: Iru antaŭ mi kaj lasu liberan interspacon inter unu grego kaj alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Kaj al la unua li ordonis jene: Se vin renkontos mia frato Esav, kaj demandos vin: Kies vi estas? kaj kien vi iras? kaj al kiu apartenas tio, kio estas antaŭ vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'tiam diru: Al via sklavo Jakob; ĝi estas donaco, sendata al mia sinjoro Esav, kaj jen li ankaŭ mem estas post ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Kaj li ordonis ankaŭ al la dua, ankaŭ al la tria, ankaŭ al ĉiuj, kiuj iris post la gregoj, dirante: Tiamaniere parolu al Esav, kiam vi lin renkontos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Kaj diru: Jen ankaŭ via sklavo Jakob iras post ni. Ĉar li pensis: Mi pardonemigos lin per la donaco, kiu iras antaŭ mi, kaj poste mi vidos lian vizaĝon; eble li akceptos min favore.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Kaj la donaco pasis antaŭ li; sed li pasigis tiun nokton en la tendaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Kaj li leviĝis en tiu nokto, kaj prenis siajn du edzinojn kaj siajn du sklavinojn kaj siajn dek unu infanojn, kaj transpasis la vadejon de Jabok.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Kaj li prenis ilin kaj transirigis ilin trans la riveron, kaj transigis tion, kion li havis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Kaj Jakob restis sola. Kaj iu luktis kun li ĝis la apero de la matenruĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Vidinte, ke li ne povas lin venki, tiu tuŝis la artikon de lia femuro; kaj la femuro de Jakob elartikiĝis, dum li luktis kun tiu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Kaj tiu diris: Forliberigu min, ĉar leviĝis la matenruĝo. Sed li diris: Mi ne forliberigos vin, antaŭ ol vi min benos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Kaj tiu diris al li: Kia estas via nomo? Kaj li respondis: Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Tiam tiu diris: Ne Jakob estu de nun via nomo, sed Izrael; ĉar vi luktis kun Dio kaj kun homoj, kaj vi venkis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Kaj Jakob demandis, dirante: Diru vian nomon. Sed tiu diris: Por kio vi demandas mian nomon? Kaj li benis lin tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Kaj Jakob donis al tiu loko la nomon Penuel, dirante: Ĉar mi vidis Dion vizaĝon kontraŭ vizaĝo, kaj mia animo saviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'La suno leviĝis antaŭ li, kiam li trapasis Penuelon; kaj li lamis per sia femuro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Tial la Izraelidoj ne manĝas ĝis la nuna tempo la tendenon, kiu estas sur la artiko de la femuro, ĉar tiu tuŝis la femuran artikon de Jakob ĉe la tendeno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Jakob levis siajn okulojn, kaj vidis, ke jen venas Esav kaj kun li kvarcent homoj. Tiam li dividis la infanojn de Lea kaj de Raĥel kaj de la du sklavinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Kaj li starigis la sklavinojn kaj iliajn infanojn antaŭe, Lean kun ŝiaj infanoj poste, kaj Raĥelon kun Jozef en la fino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Kaj li mem pasis preter ilin, kaj kliniĝis ĝis la tero sep fojojn, antaŭ ol li atingis sian fraton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Sed Esav kuris al li renkonte kaj ĉirkaŭprenis lin, kaj ĵetis sin sur lian kolon kaj kisis lin; kaj ili ploris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Esav levis siajn okulojn kaj ekvidis la virinojn kaj la infanojn, kaj diris: Kiuj estas ĉe vi ĉi tiuj? Jakob respondis: La infanoj, kiujn Dio favore donis al via sklavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Tiam alproksimiĝis la sklavinoj, ili kaj iliaj infanoj, kaj profunde kliniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Poste alproksimiĝis ankaŭ Lea kaj ŝiaj infanoj kaj kliniĝis; fine alproksimiĝis Jozef kaj Raĥel kaj kliniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Tiam Esav diris: Kio estas tiu tuta taĉmento, kiun mi renkontis? Kaj Jakob respondis: Por akiri la favoron de mia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Sed Esav diris: Mi havas multe, mia frato; kio apartenas al vi, tio restu ĉe vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Kaj Jakob diris: Ho ne! se mi akiris vian favoron, prenu mian donacon el mia mano; ĉar mi vidis vian vizaĝon, kvazaŭ mi vidus la vizaĝon de Dio, kaj vi montriĝis favora al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Prenu mian benon, kiu estas alportita al vi; ĉar Dio favore donis al mi kaj mi havas ĉion. Kaj li insistis, kaj tiu prenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Kaj Esav diris: Ni leviĝu kaj iru, kaj mi iros apud vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Sed Jakob diris al li: Mia sinjoro scias, ke la infanoj estas malfortaj, kaj la ŝafoj kaj bovoj ĉe mi estas tro junaj; se oni pelos ilin dum unu tago, la brutaro mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Mia sinjoro iru antaŭ sia sklavo, kaj mi kondukos malrapide, kiel iros la brutoj, kiuj estas antaŭ mi, kaj kiel iros la infanoj, ĝis mi venos al mia sinjoro en Seir.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Tiam Esav diris: Mi restigos ĉe vi iujn el la homoj, kiuj estas kun mi. Sed Jakob diris: Por kio? lasu min nur posedi la favoron de mia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Kaj en tiu tago Esav returne foriris sian vojon al Seir.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Kaj Jakob ekiris al Sukot kaj konstruis al si domon, kaj por siaj brutoj li faris kabanojn; tial la loko ricevis la nomon Sukot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Veninte el Mezopotamio, Jakob alvenis bonstate en la urbo de Ŝeĥem, kiu estas en la lando Kanaana; kaj li starigis sian tendaron antaŭ la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Kaj la kampoparton, sur kiu li starigis sian tendon, li aĉetis el la manoj de la filoj de Ĥamor, la patro de Ŝeĥem, por cent kesitoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Kaj li starigis tie altaron, kaj li nomis ĝin El, la Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Dina, la filino de Lea, kiun ŝi naskis al Jakob, eliris, por vidi la filinojn de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Kaj vidis ŝin Ŝeĥem, filo de Ĥamor la Ĥivido, princo de la lando, kaj li prenis ŝin kaj kuŝis kun ŝi kaj faris al ŝi perfortaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Kaj algluiĝis lia animo al Dina, la filino de Jakob, kaj li ekamis la junulinon kaj parolis al la koro de la junulino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Kaj Ŝeĥem diris al sia patro Ĥamor jene: Prenu por mi ĉi tiun knabinon kiel edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Jakob aŭdis, ke li senhonorigis lian filinon Dina; sed liaj filoj estis kun liaj brutoj sur la kampo, tial Jakob silentis ĝis ilia veno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Kaj Ĥamor, la patro de Ŝeĥem, eliris al Jakob, por paroli kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Sed la filoj de Jakob venis de la kampo. Kiam ili aŭdis, la viroj ĉagreniĝis kaj forte koleriĝis, ke li faris malnoblaĵon en Izrael, kuŝinte kun la filino de Jakob, kio ne devis esti farata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Ĥamor ekparolis al ili, dirante: Ŝeĥem, mia filo, deziregas per sia animo vian filinon; donu ŝin al li kiel edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Kaj boparenciĝu kun ni: viajn filinojn donu al ni, kaj niajn filinojn prenu al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Kaj loĝu kun ni, kaj la lando estos antaŭ vi; loĝu kaj faru negocojn kaj akiru posedaĵojn en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Kaj Ŝeĥem diris al ŝia patro kaj al ŝiaj fratoj: Estu favoraj al mi; kaj kion vi diros al mi, mi donos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Postulu de mi tre grandan doton kaj donacojn, kaj mi donos, kion vi diros al mi; nur donu al mi la junulinon kiel edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Kaj la filoj de Jakob respondis al Ŝeĥem kaj al lia patro Ĥamor ruze, kaj parolis tiel pro tio, ke li senhonorigis ilian fratinon Dina;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'kaj ili diris al ili: Ni ne povas fari tion kaj doni nian fratinon al viro, kiu ne estas cirkumcidita; ĉar tio estus por ni hontindaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Nur tiam ni donos al vi nian konsenton, se vi estos kiel ni kaj cirkumcidos ĉe vi ĉiun virseksulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Tiam ni donos niajn filinojn al vi kaj viajn filinojn ni prenos al ni, kaj ni loĝos kun vi, kaj ni estos unu popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Sed se vi ne konsentos lasi cirkumcidi vin, tiam ni prenos nian filinon kaj foriros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Ilia parolo plaĉis al Ĥamor, kaj al Ŝeĥem, la filo de Ĥamor.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Kaj la junulo ne prokrastis fari la aferon, ĉar li deziris la filinon de Jakob; kaj li estis la plej honorata inter ĉiuj domanoj de sia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Kaj Ĥamor kaj lia filo Ŝeĥem venis al la pordego de sia urbo, kaj ekparolis al la loĝantoj de sia urbo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Tiuj homoj estas pacaj kun ni; tial ili loĝu en la lando kaj faru en ĝi negocojn; la lando estas ja grandspaca por ili. Iliajn filinojn ni prenu al ni kiel edzinojn, kaj niajn filinojn ni donu al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Sed nur en tia okazo tiuj homoj konsentas loĝi kun ni kaj esti unu popolo, se ni cirkumcidos ĉe ni ĉiun virseksulon, kiel ili estas cirkumciditaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Ilia akiritaĵo kaj havaĵo kaj ĉiuj iliaj brutoj fariĝos ja niaj, se ni nur donos al ili nian konsenton kaj ili loĝos kun ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Kaj obeis al Ĥamor kaj al lia filo Ŝeĥem ĉiuj elirantaj el la pordego de lia urbo; kaj cirkumcidiĝis ĉiuj virseksuloj, ĉiuj elirantaj el la pordego de lia urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'En la tria tago, kiam ili estis malsanaj, du filoj de Jakob, Simeon kaj Levi, fratoj de Dina, prenis ĉiu sian glavon kaj venis sentime en la urbon kaj mortigis ĉiujn virseksulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Kaj Ĥamoron kaj lian filon Ŝeĥem ili mortigis per glavo, kaj prenis Dinan el la domo de Ŝeĥem kaj eliris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'La filoj de Jakob venis al la mortigitoj, kaj prirabis la urbon pro tio, ke ili senhonorigis ilian fratinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Iliajn ŝafojn kaj iliajn bovojn kaj iliajn azenojn, kaj ĉion, kio estis en la urbo, kaj tion, kio estis sur la kampo, ili prenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'Kaj ilian tutan riĉon kaj ĉiujn iliajn infanojn kaj iliajn edzinojn ili malliberigis, kaj rabis ĉion, kio estis en la domoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Tiam Jakob diris al Simeon kaj al Levi: Vi afliktis min kaj faris min malaminda por la loĝantoj de la lando, por la Kanaanidoj kaj Perizidoj. Mi havas ja malmulte da homoj; kiam ili kolektiĝos kontraŭ mi kaj venkobatos min, tiam estos ekstermita mi kaj mia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Sed ili diris: Ĉu estas permesite agi kun nia fratino kiel kun publikulino?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Kaj Dio diris al Jakob: Leviĝu, iru al Bet-El kaj loĝu tie; kaj faru tie altaron al Dio, kiu aperis al vi, kiam vi kuris de via frato Esav.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Tiam Jakob diris al sia domanaro, kaj al ĉiuj, kiuj estis kun li: Forigu la fremdajn diojn, kiuj estas inter vi, kaj puriĝu kaj ŝanĝu viajn vestojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Kaj ni leviĝu, kaj ni iru al Bet-El; kaj mi faros tie altaron al Dio, kiu atentis min en la tago de mia mizero, kaj estis kun mi sur la vojo, kiun mi iris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Kaj ili donis al Jakob ĉiujn fremdajn diojn, kiuj estis en iliaj manoj, kaj la ringojn, kiuj estis en iliaj oreloj; kaj Jakob enfosis ilin sub la kverko, kiu estis apud Ŝeĥem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Kaj ili ekiris. Kaj timo de Dio venis sur la urbojn, kiuj estis ĉirkaŭ ili, kaj ili ne persekutis la filojn de Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Jakob venis al la urbo Luz, kiu estas en la lando Kanaana kaj havas ankaŭ la nomon Bet-El, li kaj ĉiuj homoj, kiuj estis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Kaj li konstruis tie altaron, kaj donis al la loko la nomon El-Bet-El; ĉar tie aperis al li Dio, kiam li kuris de sia frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Tiam mortis Debora, la mamnutrintino de Rebeka, kaj oni ŝin enterigis apud Bet-El, sub la kverko. Kaj tiu loko ricevis la nomon Alon-Baĥut.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Kaj denove Dio aperis al Jakob, kiam li revenis el Mezopotamio, kaj benis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Kaj Dio diris al li: Via nomo estas Jakob; tamen ne plue estu nomata Jakob, sed Izrael estu via nomo. Kaj Li donis al li la nomon Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Kaj Dio diris al li: Mi estas Dio la Plejpotenca; fruktu kaj multiĝu; popolo kaj popolaro fariĝos el vi, kaj reĝoj eliros el via lumbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Kaj la landon, kiun Mi donis al Abraham kaj al Isaak, Mi donos al vi, kaj al via idaro post vi Mi donos la landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Kaj Dio forleviĝis de li sur la loko, kie Li parolis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Jakob starigis monumenton sur la loko, kie Li parolis kun li, monumenton ŝtonan; kaj li verŝis sur ĝin verŝoferon kaj verŝis sur ĝin oleon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Kaj al la loko, kie Dio parolis kun li, Jakob donis la nomon Bet-El.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Kaj ili forlasis Bet-Elon. Kiam restis ankoraŭ negranda interspaco, por veni al Efrata, Raĥel naskis, kaj ŝia akuŝiĝo estis malfacila.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Dum ŝia akuŝiĝa suferado la akuŝistino diris al ŝi: Ne timu, ĉar ankaŭ ĉi tiu ĉe vi estas filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Dum la elirado de ŝia animo, ĉar ŝi estis mortanta, ŝi donis al li la nomon Ben-Oni; sed lia patro donis al li la nomon Benjamen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Kaj Raĥel mortis, kaj oni enterigis ŝin sur la vojo al Efrata, kiu estas Bet-Leĥem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Kaj Jakob starigis monumenton super ŝia tombo. Tio estas la tomba monumento de Raĥel ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Kaj Izrael formigris, kaj starigis sian tendon transe de la turo Eder.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'En la tempo, kiam Izrael loĝis en tiu lando, Ruben iris kaj kuŝis kun Bilha, la kromvirino de lia patro. Kaj pri tio aŭdis Izrael. La filoj de Jakob estis dek du:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'la filoj de Lea: Ruben, la unuenaskito de Jakob, kaj Simeon kaj Levi kaj Jehuda kaj Isaĥar kaj Zebulun;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'la filoj de Raĥel: Jozef kaj Benjamen;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'kaj la filoj de Bilha, sklavino de Raĥel: Dan kaj Naftali;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'kaj la filoj de Zilpa, sklavino de Lea: Gad kaj Aŝer. Tio estas la filoj de Jakob, kiuj naskiĝis al li en Mezopotamio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Kaj Jakob venis al sia patro Isaak en Mamre, al Kirjat-Arba (tio estas Ĥebron), kie vivis fremdule Abraham kaj Isaak.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Isaak havis la aĝon de cent okdek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Kaj Isaak konsumiĝis kaj mortis kaj alkolektiĝis al sia popolo, estante maljuna kaj sata de vivo. Kaj lin enterigis liaj filoj Esav kaj Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Jen estas la generaciaro de Esav, kiu ankaŭ estas Edom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esav prenis siajn edzinojn el la Kanaanidinoj: Adan, filinon de Elon la Ĥetido, kaj Oholibaman, filinon de Ana, filino de Cibeon la Ĥivido,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'kaj Basmaton, filinon de Iŝmael, fratinon de Nebajot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Kaj Ada naskis al Esav Elifazon, kaj Basmat naskis Reuelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Kaj Oholibama naskis Jeuŝon kaj Jalamon kaj Koraĥon. Tio estas la filoj de Esav, kiuj naskiĝis al li en la lando Kanaana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Kaj Esav prenis siajn edzinojn kaj siajn filojn kaj siajn filinojn kaj ĉiujn siajn domanojn kaj sian havon kaj ĉiujn siajn brutojn kaj sian tutan akiritaĵon, kiun li akiris en la lando Kanaana; kaj foriris en alian landon, for de sia frato Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Ĉar ilia havo estis tiel granda, ke ili ne povis loĝi kune; kaj la lando, en kiu ili vivis fremdule, ne povis teni ilin pro la grandeco de iliaj brutaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Kaj Esav ekloĝis sur la monto Seir; Esav estas ankaŭ Edom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Kaj jen estas la generaciaro de Esav, la patro de la Edomidoj, sur la monto Seir:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'jen estas la nomoj de la filoj de Esav: Elifaz, filo de Ada, edzino de Esav; Reuel, filo de Basmat, edzino de Esav.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Kaj la filoj de Elifaz estis: Teman, Omar, Cefo kaj Gatam kaj Kenaz.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Kaj Timna estis kromvirino de Elifaz, filo de Esav, kaj ŝi naskis al Elifaz Amalekon. Tio estas la filoj de Ada, edzino de Esav.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Kaj jen estas la filoj de Reuel: Naĥat kaj Zeraĥ, Ŝama kaj Miza. Tio estas la filoj de Basmat, edzino de Esav.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Kaj jen estas la filoj de Oholibama, filino de Ana, filino de Cibeon, edzino de Esav: ŝi naskis al Esav Jeuŝon kaj Jalamon kaj Koraĥon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Jen estas la ĉefoj de la filoj de Esav: la filoj de Elifaz, unuenaskito de Esav: ĉefo Teman, ĉefo Omar, ĉefo Cefo, ĉefo Kenaz,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'ĉefo Koraĥ, ĉefo Gatam, ĉefo Amalek. Tio estas la ĉefoj de Elifaz en la lando de Edom. Tio estas la filoj de Ada.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Kaj jen estas la filoj de Reuel, filo de Esav: ĉefo Naĥat, ĉefo Zeraĥ, ĉefo Ŝama, ĉefo Miza. Tio estas la ĉefoj de Reuel en la lando de Edom. Tio estas la filoj de Basmat, edzino de Esav.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Kaj jen estas la filoj de Oholibama, edzino de Esav: ĉefo Jeuŝ, ĉefo Jalam, ĉefo Koraĥ. Tio estas la ĉefoj de Oholibama, filino de Ana, edzino de Esav.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Tio estas la filoj de Esav, kaj tio estas iliaj ĉefoj. Tio estas Edom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Jen estas la filoj de Seir la Ĥorido, kiuj loĝis en la lando: Lotan kaj Ŝobal kaj Cibeon kaj Ana');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'kaj Diŝon kaj Ecer kaj Diŝan. Tio estas la ĉefoj de la Ĥoridoj, filoj de Seir, en la lando de Edom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'La filoj de Lotan estis: Ĥori kaj Hemam; kaj la fratino de Lotan estis Timna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Kaj jen estas la filoj de Ŝobal: Alvan kaj Manaĥat kaj Ebal, Ŝefo kaj Onam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Kaj jen estas la infanoj de Cibeon: Aja kaj Ana. Tio estas tiu Ana, kiu trovis la varmajn akvojn en la dezerto, kiam li paŝtis la azenojn de sia patro Cibeon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Kaj jen estas la infanoj de Ana: Diŝon, kaj Oholibama, filino de Ana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Kaj jen estas la filoj de Diŝon: Ĥemdan kaj Eŝban kaj Jitran kaj Keran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Jen estas la filoj de Ecer: Bilhan kaj Zaavan kaj Akan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Jen estas la filoj de Diŝan: Uc kaj Aran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Jen estas la ĉefoj de la Ĥoridoj: ĉefo Lotan, ĉefo Ŝobal, ĉefo Cibeon, ĉefo Ana,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'ĉefo Diŝon, ĉefo Ecer, ĉefo Diŝan. Tio estas la ĉefoj de la Ĥoridoj, laŭ la ordo de ilia ĉefeco en la lando Seir.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Kaj jen estas la reĝoj, kiuj reĝis en la lando de Edom, antaŭ ol aperis reĝoj ĉe la Izraelidoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'En Edom reĝis Bela, filo de Beor, kaj la nomo de lia urbo estis Dinhaba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Kiam Bela mortis, ekreĝis anstataŭ li Jobab, filo de Zeraĥ el Bocra.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Kiam mortis Jobab, ekreĝis anstataŭ li Ĥuŝam el la lando de la Temananoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Kiam mortis Ĥuŝam, ekreĝis anstataŭ li Hadad, filo de Bedad, kiu venkobatis la Midjanidojn sur la kampo de Moab; kaj la nomo de lia urbo estis Avit.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Kiam mortis Hadad, ekreĝis anstataŭ li Samla el Masreka.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Kiam mortis Samla, ekreĝis anstataŭ li Ŝaul el Reĥobot ĉe la Rivero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Kiam mortis Ŝaul, ekreĝis anstataŭ li Baal-Ĥanan, filo de Aĥbor.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Kiam mortis Baal-Ĥanan, filo de Aĥbor, ekreĝis anstataŭ li Hadar; la nomo de lia urbo estis Pau, kaj la nomo de lia edzino estis Mehetabel, filino de Matred, filino de Me-Zahab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Kaj jen estas la nomoj de la ĉefoj de Esav, laŭ iliaj gentoj, lokoj, kaj nomoj: ĉefo Timna, ĉefo Alva, ĉefo Jetet,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'ĉefo Oholibama, ĉefo Ela, ĉefo Pinon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'ĉefo Kenaz, ĉefo Teman, ĉefo Mibcar,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'ĉefo Magdiel, ĉefo Iram. Tio estas la ĉefoj de Edom, kiel ili loĝis en la lando, posedata de ili. Esav estis la patro de la Edomidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Jakob loĝis en la lando, en kiu lia patro loĝis fremdule, en la lando Kanaana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Jen estas la generaciaro de Jakob. Jozef, havante la aĝon de dek sep jaroj, paŝtis kune kun siaj fratoj la brutaron; li estis knabo kune kun la filoj de Bilha kaj la filoj de Zilpa, la edzinoj de lia patro; kaj malbonajn famojn pri ili Jozef raportadis al ilia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Kaj Izrael amis Jozefon pli ol ĉiujn siajn filojn, ĉar li estis por li filo naskita en maljuneco; kaj li faris al li mikskoloran veston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Ĉar la fratoj vidis, ke lin ilia patro amas pli ol ĉiujn liajn fratojn, tial ili malamis lin kaj ne povis paroli kun li pace.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Jozef havis sonĝon, kaj li rakontis ĝin al siaj fratoj; tiam ili ekmalamis lin ankoraŭ pli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Li diris al ili: Aŭskultu la sonĝon, kiun mi sonĝis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'ni ligis garbojn meze de la kampo; kaj jen mia garbo stariĝis kaj restis starante, kaj viaj garboj ĝin ĉirkaŭis kaj profunde kliniĝis antaŭ mia garbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Tiam liaj fratoj diris al li: Ĉu vi estos reĝo super ni? aŭ ĉu vi regos super ni? Kaj ili ankoraŭ pli ekmalamis lin pro liaj sonĝoj kaj pro liaj vortoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Kaj li sonĝis ankoraŭ alian sonĝon kaj rakontis ĝin al siaj fratoj, kaj diris: Mi sonĝis ankoraŭ unu sonĝon: jen la suno kaj la luno kaj dek unu steloj kliniĝas antaŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Kaj li rakontis al sia patro kaj al siaj fratoj; kaj lia patro faris al li riproĉon, kaj diris al li: Kion vi volas kun tiu sonĝo, kiun vi sonĝis? ĉu mi kaj via patrino kaj viaj fratoj venos, por kliniĝi antaŭ vi ĝis la tero?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Kaj liaj fratoj lin enviis, sed lia patro konservis en la memoro la aferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Liaj fratoj iris paŝti la ŝafojn de sia patro en Ŝeĥem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Kaj Izrael diris al Jozef: Viaj fratoj paŝtas ja en Ŝeĥem; venu do, mi sendos vin al ili. Kaj tiu respondis al li: Jen mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Kaj Izrael diris al li: Iru, rigardu, kiel fartas viaj fratoj kaj kiel fartas la ŝafoj, kaj alportu al mi respondon. Kaj li forsendis lin el la valo de Ĥebron, kaj tiu venis Ŝeĥemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Kaj iu viro trovis lin, kaj vidis, ke li erarvagas sur la kampo; kaj la viro demandis lin: Kion vi serĉas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Kaj li diris: Miajn fratojn mi serĉas; diru al mi, kie ili paŝtas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Kaj la viro diris: Ili foriris de ĉi tie; ĉar mi aŭdis, ke ili diris: Ni iru al Dotan. Kaj Jozef iris serĉi siajn fratojn, kaj trovis ilin en Dotan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Kaj ili ekvidis lin de malproksime; kaj antaŭ ol li alproksimiĝis al ili, naskiĝis en ili la malbona intenco mortigi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Kaj ili diris unu al alia: Jen tiu sonĝisto venas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'nun ni iru kaj mortigu lin, kaj ni ĵetu lin en unu el la putoj, kaj ni diru, ke sovaĝa besto lin formanĝis; kaj ni vidos, kio fariĝos el liaj sonĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Sed tion aŭdis Ruben kaj savis lin el iliaj manoj, kaj diris: Ni ne mortigu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Kaj Ruben diris al ili: Ne verŝu sangon; ĵetu lin en ĉi tiun puton, kiu estas en la dezerto, sed manon ne metu sur lin. Ĉar li intencis savi lin el iliaj manoj kaj revenigi lin al sia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Kaj kiam Jozef venis al siaj fratoj, ili deprenis de li lian veston, la mikskoloran veston, kiu estis sur li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'kaj ili prenis lin kaj ĵetis lin en la puton; sed la puto estis malplena, akvo ne estis en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Kiam ili sidiĝis, por manĝi panon, ili levis siajn okulojn, kaj ekvidis, ke jen karavano da Iŝmaelidoj venas el Gilead, kaj iliaj kameloj portas aromaĵojn kaj balzamon kaj mirhon; ili iras, direktante sin al Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Kaj Jehuda diris al siaj fratoj: Kian profiton ni havos, se ni mortigos nian fraton kaj kaŝos lian sangon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Venu, ni vendos lin al la Iŝmaelidoj, por ke nia mano ne metiĝu sur lin; ĉar li estas nia frato, nia karno. Kaj liaj fratoj akceptis lian proponon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Kaj kiam la Midjanidoj, la komercistoj, preteriris, ili eltiris kaj levis Jozefon el la puto kaj vendis Jozefon al la Iŝmaelidoj por dudek arĝentaj moneroj; kaj tiuj forkondukis Jozefon al Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Kiam Ruben revenis al la puto, li vidis, ke Jozef ne estas en la puto. Kaj li disŝiris siajn vestojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'Kaj li reiris al siaj fratoj, kaj diris: La knabo forestas, kaj kien mi nun iros?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Kaj ili prenis la veston de Jozef kaj buĉis kapron kaj trempis la veston en la sango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Kaj ili sendis la mikskoloran veston kaj venigis ĝin al sia patro, kaj dirigis: Ĉi tion ni trovis; rigardu, ĉu ĝi estas la vesto de via filo aŭ ne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Kaj li rekonis ĝin, kaj diris: Ĝi estas la vesto de mia filo! sovaĝa besto lin formanĝis! disŝirita estas Jozef!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Kaj Jakob disŝiris siajn vestojn kaj metis sakaĵon ĉirkaŭ sian lumbon kaj funebris pri sia filo multe da tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Kaj ĉiuj liaj filoj kaj filinoj penis konsoli lin, sed li ne volis konsoliĝi, kaj diris: En funebro mi iros en Ŝeolon al mia filo. Tiel ploris pri li lia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Sed la Midjanidoj vendis lin en Egiptujo al Potifar, kortegano de Faraono, estro de la korpogardistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'En tiu tempo Jehuda apartiĝis for de siaj fratoj, kaj ekloĝis apud iu Adulamano, kiu estis nomata Ĥira.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Kaj Jehuda vidis tie filinon de iu Kanaanido, nomata Ŝua, kaj li prenis ŝin kaj envenis al ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Kaj ŝi gravediĝis kaj naskis filon; kaj li donis al li la nomon Er.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Kaj ŝi denove gravediĝis kaj naskis filon, kaj ŝi donis al li la nomon Onan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Kaj ankoraŭ plue ŝi naskis filon, kaj donis al li la nomon Ŝela. Sed Jehuda estis en Kezib, kiam ŝi naskis tiun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Kaj Jehuda prenis edzinon por sia unuenaskito Er, kaj ŝia nomo estis Tamar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Sed Er, la unuenaskito de Jehuda, estis malbona antaŭ la okuloj de la Eternulo, kaj la Eternulo lin mortigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Tiam Jehuda diris al Onan: Envenu al la edzino de via frato, kaj boedziĝu kun ŝi kaj naskigu idaron al via frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Sed Onan sciis, ke ne por li estos la idaro; tial, envenante al la edzino de sia frato, li elverŝadis la semon sur la teron, por ne doni idaron al sia frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Kaj malplaĉis al la Eternulo tio, kion li faris, kaj Li mortigis ankaŭ lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Tiam Jehuda diris al sia bofilino Tamar: Restu kiel vidvino en la domo de via patro, ĝis grandiĝos mia filo Ŝela. Ĉar li timis, ke eble li ankaŭ mortos, kiel liaj fratoj. Kaj Tamar iris kaj ekloĝis en la domo de sia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Pasis multe da tempo, kaj mortis la filino de Ŝua, la edzino de Jehuda. Kiam Jehuda konsoliĝis, li iris Timnan, al la tondantoj de liaj ŝafoj, li kaj lia amiko, Ĥira la Adulamano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Kaj oni sciigis al Tamar, dirante: Jen via bopatro iras Timnan, por tondi siajn ŝafojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Tiam ŝi demetis de si siajn vestojn de vidvineco kaj kovris sin per kovrotuko kaj vualis sin, kaj sidiĝis apud la pordo de Enaim, kiu troviĝas sur la vojo al Timna. Ĉar ŝi vidis, ke Ŝela grandiĝis kaj ŝi ne estas donita al li kiel edzino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Kaj Jehuda ŝin vidis, kaj li pensis, ke ŝi estas publikulino, ĉar ŝi kovris sian vizaĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Kaj li turnis sin al ŝi ĉe la vojo, kaj diris: Lasu min enveni al vi. Ĉar li ne sciis, ke tio estas lia bofilino. Kaj ŝi diris: Kion vi donos al mi, se vi envenos al mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Kaj li diris: Mi sendos al vi kapron el la brutaro. Sed ŝi diris: Donu al mi garantiaĵon, ĝis vi sendos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Kaj li diris: Kian garantiaĵon mi donu al vi? Ŝi diris: Vian sigelilon kaj vian ŝnureton, kaj vian bastonon, kiu estas en via mano. Kaj li donis al ŝi kaj envenis al ŝi, kaj ŝi gravediĝis de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Kaj ŝi leviĝis kaj iris, kaj formetis de si sian kovrotukon kaj surmetis sur sin siajn vestojn de vidvineco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Kaj Jehuda sendis la kapron per sia amiko la Adulamano, por preni la garantiaĵon el la manoj de la virino; sed li ŝin ne trovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Kaj li demandis la homojn de ŝia loko, dirante: Kie estas la publikulino, kiu sidis en Enaim ĉe la vojo? Kaj ili diris: Ĉi tie ne estis publikulino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Kaj li revenis al Jehuda, kaj diris: Mi ŝin ne trovis, kaj ankaŭ la homoj de la loko diris, ke tie ne estis publikulino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Tiam Jehuda diris: Ŝi prenu ĝin al si, por ke ni ne estu mokataj; mi sendis ja ĉi tiun kapron, sed vi ŝin ne trovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Post la paso de tri monatoj oni sciigis al Jehuda, dirante: Tamar, via bofilino, malĉastiĝis, kaj ŝi eĉ gravediĝis de malĉasteco. Tiam Jehuda diris: Elkonduku ŝin, kaj oni ŝin brulmortigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Kiam oni ŝin kondukis, ŝi sendis, ke oni diru al ŝia bopatro: Mi gravediĝis de la viro, al kiu apartenas ĉi tio. Kaj ŝi diris: Rekonu, al kiu apartenas la sigelilo kaj la ŝnuretoj kaj ĉi tiu bastono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Kaj Jehuda rekonis, kaj li diris: Ŝi estas pli prava ol mi, ĉar mi ne donis ŝin al mia filo Ŝela. Kaj li ŝin ne plue konis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Kiam ŝi devis naski, montriĝis, ke ĝemeloj estas en ŝia ventro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Kaj kiam ŝi estis naskanta, elŝoviĝis la mano de unu infano; kaj la akuŝistino prenis kaj alligis al la mano ruĝan fadenon, dirante: Ĉi tiu eliris la unua.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Sed kiam li retiris sian manon, eliris lia frato. Kaj ŝi diris: Kial vi faris por vi traŝiron? Kaj oni donis al li la nomon Perec.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Poste eliris lia frato, kiu havis sur sia mano la ruĝan fadenon. Kaj oni donis al li la nomon Zeraĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Jozef estis forkondukita en Egiptujon, kaj lin aĉetis Potifar, kortegano de Faraono, estro de la korpogardistoj, Egipto, el la manoj de la Iŝmaelidoj, kiuj venigis lin tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Kaj la Eternulo estis kun Jozef, kaj li estis sukcesulo; kaj li estis en la domo de sia sinjoro, la Egipto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Kaj lia sinjoro vidis, ke la Eternulo estas kun li, kaj ke ĉion, kion li faras, la Eternulo sukcesigas en lia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Kaj Jozef akiris lian favoron kaj servis lin; kaj li estrigis lin super sia domo, kaj transdonis en liajn manojn ĉion, kion li havis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Kaj de tiu tempo, kiam li estrigis lin super sia domo, kaj super ĉio, kion li havis, la Eternulo benis la domon de la Egipto pro Jozef, kaj la beno de la Eternulo estis super ĉio, kion li havis, en la domo kaj sur la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Kaj li lasis ĉion, kion li havis, en la manoj de Jozef, kaj li sciis pri nenio, krom nur pri la pano, kiun li manĝis. Kaj Jozef estis gracia kaj bela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Post kelka tempo la edzino de lia sinjoro ĵetis siajn rigardojn sur Jozefon, kaj diris: Kuŝiĝu kun mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Sed li rifuzis, kaj li diris al la edzino de sia sinjoro: Jen, mia sinjoro kontrolas ĉe mi nenion en la domo, kaj ĉion, kion li havas, li transdonis en miajn manojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'neniu en ĉi tiu domo estas pli granda ol mi, kaj li retenis de mi nenion, krom vi, ĉar vi estas lia edzino. Kiel do mi faros ĉi tiun grandan malbonagon kaj pekos antaŭ Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Dum ŝi paroladis al Jozef ĉiutage kaj li ne volis obei ŝin kaj kuŝiĝi kun ŝi kaj esti kun ŝi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'okazis unu tagon, ke li venis en la domon, por fari sian laboron, kaj neniu el la domanoj estis en la domo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'tiam ŝi kaptis lin je lia vesto, dirante: Kuŝiĝu kun mi. Sed li lasis sian veston en ŝiaj manoj kaj forkuris for el la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Kaj kiam ŝi vidis, ke li lasis sian veston en ŝia mano kaj forkuris el la domo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'ŝi vokis siajn domanojn, kaj diris al ili: Rigardu, li venigis al ni Hebreon, por moki nin; ĉi tiu venis al mi, por kuŝiĝi kun mi; sed mi ekkriis per laŭta voĉo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'kaj kiam li aŭdis, ke mi ekkriis per laŭta voĉo, li lasis sian veston ĉe mi kaj forkuris for el la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Kaj ŝi kuŝigis lian veston apud si, ĝis lia sinjoro venis en sian domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Kaj ŝi rakontis al li tion saman, dirante: La sklavo, la Hebreo, kiun vi venigis al ni, venis al mi, por petoli kun mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'sed kiam mi laŭte ekkriis, li lasis sian veston ĉe mi kaj elkuris el la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Kiam lia sinjoro aŭdis la vortojn de sia edzino, kiujn ŝi diris al li, parolante: Tiel agis kun mi via sklavo-tiam li forte ekkoleris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Kaj la sinjoro de Jozef prenis lin kaj fordonis lin en malliberejon, en la lokon, kie la malliberuloj de la reĝo estis tenataj; kaj li estis tie en la malliberejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Kaj la Eternulo estis kun Jozef kaj estis favorkora al li kaj havigis al li la favoron de la estro de la malliberejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Kaj la estro de la malliberejo transdonis en la manojn de Jozef ĉiujn malliberulojn, kiuj estis en la malliberejo; kaj ĉio, kion ili tie faris, estis farata sub lia kontrolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'La estro de la malliberejo rigardis nenion, kio estis sub lia disponado, ĉar la Eternulo estis kun li; kaj ĉion, kion li faris, la Eternulo sukcesigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Post tiuj okazintaĵoj la vinisto de la reĝo de Egiptujo kaj la bakisto kulpiĝis antaŭ sia sinjoro, la reĝo de Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Kaj Faraono koleriĝis kontraŭ siaj du korteganoj, kontraŭ la vinistestro kaj kontraŭ la bakistestro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'Kaj li metis ilin sub gardon en la domon de la estro de la korpogardistoj, en la malliberejon, en la lokon, kie Jozef estis malliberigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Kaj la estro de la korpogardistoj destinis por ili Jozefon, kaj li servis ilin. Kaj ili restis kelkan tempon en la malliberejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Kaj ambaŭ sonĝis sonĝon, ĉiu sian apartan sonĝon en la sama nokto, ĉiu kun aparta signifo de la sonĝo, la vinisto kaj la bakisto de la reĝo de Egiptujo, kiuj estis tenataj en la malliberejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Kiam Jozef venis al ili matene, li vidis, ke ili estas ĉagrenitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Kaj li demandis la korteganojn de Faraono, kiuj estis kun li en malliberejo en la domo de lia sinjoro, dirante: Kial viaj vizaĝoj estas ĉagrenitaj hodiaŭ?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Kaj ili diris al li: Ni sonĝis sonĝon, sed estas ĉi tie neniu, kiu ĝin signifoklarigus. Kaj Jozef diris al ili: La signifoklarigoj apartenas ja al Dio; tamen rakontu al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Tiam la vinistestro rakontis sian sonĝon al Jozef, kaj diris al li: En mia sonĝo mi vidis antaŭ mi vinbertrunkon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'la trunko havis tri branĉojn; apenaŭ ĝi ekfloris, tuj aperis sur ĝi beraroj kun maturaj beroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'kaj la pokalo de Faraono estis en mia mano; kaj mi prenis la berojn, kaj mi elpremis ilin en la pokalon de Faraono, kaj mi donis la pokalon en la manon de Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Kaj Jozef diris al li: Jen estas ĝia signifoklarigo: la tri branĉoj estas tri tagoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'post tri tagoj Faraono levos vian kapon kaj redonos al vi vian oficon, kaj vi donos la pokalon de Faraono en lian manon laŭ la maniero de antaŭe, kiam vi estis lia vinisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Sed memoru min, kiam estos bone al vi, kaj faru al mi favorkoraĵon kaj memorigu pri mi Faraonon kaj elirigu min el ĉi tiu domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Ĉar oni ŝtelis min el la lando de la Hebreoj, kaj ankaŭ ĉi tie mi faris nenion, pro kio oni metis min en la malliberejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Kiam la bakistestro vidis, ke la signifoklarigo estas bona, li diris al Jozef: Mi ankaŭ havis sonĝon; jen tri blankaj korboj estis sur mia kapo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'kaj en la supra korbo estis ĉiaspecaj manĝaĵoj de Faraono, bakitaĵoj, kaj la birdoj manĝis ilin el la korbo sur mia kapo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Kaj Jozef respondis, dirante: Jen estas ĝia signifoklarigo: la tri korboj estas tri tagoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'post tri tagoj Faraono deprenos de vi vian kapon kaj pendigos vin sur arbo, kaj la birdoj formanĝos de vi vian karnon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'En la tria tago, tago de naskiĝo de Faraono, li faris festenon por ĉiuj siaj servantoj; kaj li venigis la vinistestron kaj la bakistestron en la mezon de siaj servantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Kaj li redonis al la vinistestro lian oficon, kaj tiu donis la pokalon en la manon de Faraono;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'sed la bakistestron li pendigis, kiel sonĝoklarigis al ili Jozef.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Kaj la vinistestro ne rememoris Jozefon, sed forgesis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Post du jaroj Faraono havis sonĝon, ke jen li staras apud la Rivero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Kaj jen el la Rivero eliras sep bovinoj belaspektaj kaj grasaj, kaj ili paŝtiĝas en la kanejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Kaj jen sep aliaj bovinoj eliras post ili el la Rivero, malbelaspektaj kaj malgrasaj, kaj ili stariĝas apud tiuj bovinoj sur la bordo de la Rivero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Kaj la bovinoj malbelaspektaj kaj malgrasaj formanĝis la sep bovinojn belaspektajn kaj grasajn. Kaj Faraono vekiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Kaj li endormiĝis kaj denove havis sonĝon: jen sep spikoj leviĝas sur unu spiktrunko, dikaj kaj bonaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Sed jen sep spikoj, maldikaj kaj bruligitaj de la orienta vento, elkreskas post ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Kaj la maldikaj spikoj englutis la sep spikojn dikajn kaj plenajn. Kaj Faraono vekiĝis, kaj vidis, ke tio estis sonĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'En la mateno lia spirito afliktiĝis; kaj li sendis kaj vokigis ĉiujn sorĉistojn de Egiptujo kaj ĉiujn ĝiajn saĝulojn, kaj Faraono rakontis al ili sian sonĝon; sed neniu povis signifoklarigi ĝin al Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Tiam la vinistestro ekparolis al Faraono, dirante: Miajn pekojn mi rememoras hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Faraono koleris siajn sklavojn, kaj metis min en malliberejon en la domon de la estro de la korpogardistoj, min kaj la bakistestron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Kaj ni sonĝis sonĝon en unu nokto, mi kaj li; ĉiu havis sonĝon kun aparta signifo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Kaj tie estis kun ni Hebrea junulo, sklavo de la estro de la korpogardistoj; kaj ni rakontis al li, kaj li signifoklarigis al ni niajn sonĝojn, al ĉiu li klarigis laŭ lia sonĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Kaj kiel li klarigis al ni, tiel fariĝis: min oni revenigis al mia ofico, kaj lin oni pendigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Tiam Faraono sendis alvoki Jozefon; kaj oni rapide eligis lin el la malliberejo, kaj li sin razis kaj ŝanĝis siajn vestojn kaj venis al Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Kaj Faraono diris al Jozef: Mi sonĝis sonĝon, kaj neniu povas ĝin klarigi; sed pri vi mi aŭdis, ke kiam vi aŭdas sonĝon, vi tuj ĝin klarigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Kaj Jozef respondis al Faraono, dirante: Ĝi ne dependas de mi; Dio respondos bonon al Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Kaj Faraono diris al Jozef: Mi sonĝis, ke jen mi staras sur la bordo de la Rivero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'kaj jen el la Rivero eliris sep bovinoj grasaj kaj belaspektaj kaj paŝtiĝis en la kanejo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'sed jen sep aliaj bovinoj eliris post ili, maldikaj, tre malbonaspektaj kaj malgrasaj; tiajn malbelajn, kiel ili, mi ne vidis en la tuta Egipta lando;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'kaj la malgrasaj kaj malbelaj bovinoj formanĝis la sep antaŭajn grasajn bovinojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'kaj tiuj eniĝis en ilian internon, sed oni ne povis rimarki, ke ili eniĝis en ilian internon, kaj ilia aspekto estis tiel maldika, kiel antaŭe. Kaj mi vekiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Kaj mi vidis en sonĝo: jen sep spikoj elkreskis sur unu spiktrunko, plenaj kaj bonaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'sed jen sep spikoj, maldikaj, malgrasaj, kaj bruligitaj de la orienta vento, elkreskis post ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'kaj la malgrasaj spikoj englutis la sep bonajn spikojn. Kaj mi rakontis al la sorĉistoj, sed neniu klarigis al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Tiam Jozef diris al Faraono: La sonĝo de Faraono estas unu; kion Dio estas faronta, Li diris al Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'La sep bonaj bovinoj estas sep jaroj, kaj la sep bonaj spikoj estas sep jaroj; ĝi estas unu sonĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Kaj la sep bovinoj malgrasaj kaj malbelaj, kiuj eliris post ili, estas sep jaroj; kaj la sep spikoj, malplenaj kaj bruligitaj de la orienta vento, estos sep jaroj de malsato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Tio estas, pri kio mi diris al Faraono, ke kion Dio estas faronta, Li montris al Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Jen venos sep jaroj de granda abundeco en la tuta Egipta lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Sed venos sep jaroj de malsato post ili; kaj forgesiĝos la tuta abundeco en la Egipta lando, kaj la malsato konsumos la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Kaj ne restos postesigno de la abundeco en la lando, pro tiu malsato, kiu venos poste, ĉar ĝi estos tre malfacila.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Kaj se la sonĝo dufoje ripetiĝis al Faraono, tio montras, ke la afero estas firme decidita de Dio, kaj Dio rapidos plenumi tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Kaj nun Faraono elserĉu homon kompetentan kaj saĝan kaj estrigu lin super la Egipta lando;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Faraono ordonu, ke li starigu observistojn en la lando kaj prenadu kvinonon de ĉiuj produktoj de la Egipta tero dum la sep jaroj de abundeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Kaj oni kolektu la tutan manĝaĵon de tiuj venontaj bonaj jaroj, kaj oni amasigu manĝeblan grenon en la urboj sub la disponon de Faraono, kaj oni ĝin konservu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Kaj tiu manĝaĵo estos provizo por la lando por la sep jaroj de malsato, kiuj estos en la Egipta lando, por ke la lando ne pereu de malsato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Kaj tio plaĉis al Faraono kaj al ĉiuj liaj servantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Kaj Faraono diris al siaj servantoj: Ĉu ni povus trovi tian homon, kiel li, en kiu estas la spirito de Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Kaj Faraono diris al Jozef: Ĉar Dio sciigis al vi ĉion ĉi tion, ne ekzistas kompetentulo kaj saĝulo tia, kiel vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Vi estos super mia domo, kaj viajn vortojn obeos mia tuta popolo; nur per la trono mi estos pli alta ol vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Kaj Faraono diris al Jozef: Vidu, mi estrigis vin super la tuta Egipta lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Kaj Faraono deprenis sian ringon de sia mano kaj metis ĝin sur la manon de Jozef; kaj li vestis lin per bisinaj vestoj kaj metis oran ĉenon sur lian kolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Kaj li veturigis lin sur sia dua ĉaro; kaj oni kriis antaŭ li: Genuiĝu! Kaj li estrigis lin super la tuta Egipta lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Kaj Faraono diris al Jozef: Mi estas Faraono; sed sen via ordono neniu levos sian manon aŭ sian piedon en la tuta Egipta lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Kaj Faraono donis al Jozef la nomon Cafnat-Paneaĥ, kaj li donis al li kiel edzinon Asnaton, filinon de Poti-Fera, pastro el On. Kaj Jozef komencis veturadon tra la Egipta lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Jozef havis la aĝon de tridek jaroj, kiam li stariĝis antaŭ Faraono, la reĝo de Egiptujo. Kaj Jozef foriris de Faraono kaj trapasis la tutan Egiptan landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Kaj la tero alportis en la sep jaroj de abundeco grandegajn amasojn da greno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Kaj li kolektis la tutan grenon de la sep jaroj, kiuj estis en la Egipta lando, kaj li metis la grenon en la urbojn; la grenon de ĉiuj kampoj, kiuj estis ĉirkaŭ iu urbo, li metis en ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Kaj Jozef kolektis tre multe da greno, kiel la marborda sablo, ĝis li ĉesis kalkuli, ĉar oni ne plu povis kalkuli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Antaŭ ol venis la jaroj de malsato, al Jozef naskiĝis du filoj, kiujn naskis al li Asnat, filino de Poti-Fera, pastro el On.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Kaj al la unuenaskito Jozef donis la nomon Manase, ĉar, li diris, Dio forgesigis al mi ĉiujn miajn suferojn kaj la tutan domon de mia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Kaj al la dua li donis la nomon Efraim, ĉar, li diris, Dio faris min fruktoporta en la lando de mia suferado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Kaj finiĝis la sep jaroj de abundeco, kiuj estis en la Egipta lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'Kaj komenciĝis la sep jaroj de malsato, kiel diris Jozef; kaj estis malsato en ĉiuj landoj, sed en la tuta lando Egipta estis pano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Kiam la tuta Egipta lando eksuferis malsaton, la popolo kriis al Faraono pri pano; tiam Faraono diris al ĉiuj Egiptoj: Iru al Jozef, kaj kion li diros al vi, tion faru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'La malsato estis en la tuta lando. Jozef malfermis ĉiujn grenejojn, kaj vendadis al la Egiptoj. Kaj la malsato estis tre granda en la Egipta lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Kaj el ĉiuj landoj oni venadis Egiptujon, por aĉeti de Jozef, ĉar la malsato estis tre granda en ĉiuj landoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Kiam Jakob sciiĝis, ke oni vendas grenon en Egiptujo, li diris al siaj filoj: Kion vi rigardas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Kaj li diris: Mi aŭdis, ke oni vendas grenon en Egiptujo; veturu do tien kaj aĉetu por ni tie grenon, por ke ni vivu kaj ne mortu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Kaj forveturis dek fratoj de Jozef, por aĉeti grenon en Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Sed Benjamenon, la fraton de Jozef, Jakob ne sendis kun liaj fratoj; ĉar li timis, ke eble lin trafos malfeliĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Kaj la filoj de Izrael venis, por aĉeti grenon, kune kun aliaj venintoj; ĉar estis malsato en la lando Kanaana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Kaj Jozef estis la estro super la lando, kaj li estis la vendanto de la greno por la tuta popolo de la lando. Kaj la fratoj de Jozef venis kaj kliniĝis al li vizaĝaltere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Kiam Jozef ekvidis siajn fratojn, li rekonis ilin; sed li ŝajnigis sin fremda al ili kaj parolis kun ili malafable, kaj diris al ili: El kie vi venis? Kaj ili diris: El la lando Kanaana, por aĉeti manĝaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Jozef rekonis siajn fratojn, sed ili lin ne rekonis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Kaj Jozef rememoris la sonĝojn, kiujn li sonĝis pri ili. Kaj li diris al ili: Vi estas spionoj: vi venis, por vidi la malfortajn lokojn de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Kaj ili diris al li: Ne, mia sinjoro! viaj sklavoj venis, por aĉeti manĝaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Ni ĉiuj estas filoj de unu homo; ni estas honestaj; viaj sklavoj neniam estis spionoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Sed li diris al ili: Ne, vi venis, por vidi la malfortajn lokojn de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Ili diris: Ni, viaj sklavoj, estas dek du fratoj, filoj de unu homo en la lando Kanaana; la plej juna estas nun kun nia patro, kaj unu malaperis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Kaj Jozef diris al ili: Estas tio, kion mi diris al vi, vi estas spionoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Per tio mi vin elprovos: mi ĵuras per la vivo de Faraono, ke vi foriros el ĉi tie nur tiam, kiam venos ĉi tien via plej juna frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Sendu unu el vi, ke li alkonduku vian fraton; sed vi estos malliberigitaj, kaj oni esploros viajn vortojn, ĉu vi diris la veron; se ne, tiam mi ĵuras per la vivo de Faraono, ke vi estas spionoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Kaj li metis ilin sub gardon por la daŭro de tri tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Kaj Jozef diris al ili en la tria tago: Tion faru, kaj vi restos vivaj, ĉar mi havas timon antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Se vi estas homoj honestaj, tiam unu el viaj fratoj restu malliberigita en la domo, en kiu oni vin gardas, kaj vi iru kaj forportu hejmen la grenon, kiun vi aĉetis kontraŭ la malsato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Sed vian plej junan fraton venigu al mi, por ke pruviĝu la vereco de viaj vortoj kaj por ke vi ne mortu. Kaj ili faris tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Kaj ili diris unu al alia: Vere ni estas kulpaj pro nia frato; ĉar ni vidis la suferadon de lia animo, kiam li petegis nin, sed ni ne aŭskultis; por tio venis sur nin ĉi tiu sufero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Kaj Ruben respondis al ili, dirante: Mi diris ja al vi: Ne peku rilate la infanon; sed vi ne obeis; nun lia sango estas repostulata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Kaj ili ne sciis, ke Jozef komprenas; ĉar inter ili estis tradukanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Kaj li deturnis sin de ili kaj ekploris; poste li denove returnis sin al ili kaj parolis kun ili, kaj li prenis el inter ili Simeonon kaj ligis lin antaŭ iliaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Kaj Jozef ordonis plenigi iliajn sakojn per greno kaj redoni ilian monon al ĉiu en lian sakon kaj doni al ili manĝaĵon por la vojo. Tiel oni faris al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Kaj ili metis sian grenon sur siajn azenojn kaj foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Kaj unu el ili malfermis sian sakon, por doni furaĝon al sia azeno dum la nokta halto, kaj li ekvidis sian monon, kiu estis en la aperturo de lia sako.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Kaj li diris al siaj fratoj: Mia mono estas redonita; jen ĝi estas en mia sako. Tiam konsterniĝis iliaj koroj, kaj kun tremo ili diris unuj al la aliaj: Kial Dio faris tion al ni?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Kiam ili venis al sia patro Jakob en la landon Kanaanan, ili rakontis al li ĉion, kio okazis al ili, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'La homo, kiu estas sinjoro super tiu lando, parolis kun ni malafable, kaj diris, ke ni estas spionoj en la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Kaj ni diris al li: Ni estas homoj honestaj, ni neniam estis spionoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'ni estas dek du fratoj, filoj de nia patro; unu malaperis, kaj la plej juna estas nun kun nia patro en la lando Kanaana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Tiam diris al ni la homo, kiu estas sinjoro super la lando: Per tio mi konvinkiĝos, ke vi estas homoj honestaj: unu el viaj fratoj lasu ĉe mi, kaj la necesan grenon por via hejmo prenu kaj iru;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'kaj venigu al mi vian plej junan fraton; tiam mi scios, ke vi ne estas spionoj, ke vi estas honestaj homoj; vian fraton mi redonos al vi, kaj vi povos negoci en la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Kiam ili malplenigis siajn sakojn, montriĝis, ke ĉiu el ili havas sian ligaĵon da mono en sia sako. Kaj ili vidis siajn ligaĵojn da mono, ili kaj ilia patro, kaj ili timiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Kaj ilia patro Jakob diris al ili: Vi min seninfanigis; Jozef forestas, kaj Simeon forestas, kaj Benjamenon vi volas forpreni! sur min ĉio falis!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Tiam Ruben diris al sia patro jene: Miajn du filojn mortigu, se mi ne revenigos lin al vi; donu lin en mian manon, kaj mi revenigos lin al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Sed li diris: Mia filo ne iros kun vi; ĉar lia frato mortis, kaj li sola restis. Se lin trafos malfeliĉo sur la vojo, kiun vi iros, tiam vi enirigos miajn grizajn harojn kun malĝojo en Ŝeolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'La malsato estis tre premanta en la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Kiam ili formanĝis la grenon, kiun ili venigis el Egiptujo, ilia patro diris al ili: Iru denove kaj aĉetu por ni iom da pano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Tiam Jehuda diris al li jene: Tiu homo tre severe diris al ni: Ne aperu antaŭ mi, se via frato ne estos kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Se vi sendos nian fraton kun ni, tiam ni iros kaj aĉetos por vi panon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'sed se vi ne sendos, tiam ni ne iros; ĉar tiu homo diris al ni: Ne aperu antaŭ mi, se via frato ne estos kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Kaj Izrael diris: Kial vi faris al mi tian malbonon, kaj diris al la homo, ke vi havas ankoraŭ fraton?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Kaj ili diris: La homo severe demandis pri ni kaj pri nia familio, dirante: Ĉu via patro ankoraŭ vivas? ĉu vi havas fraton? Kaj ni respondis al li tiujn demandojn. Ĉu ni povis scii, ke li diros: Venigu vian fraton?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Kaj Jehuda diris al sia patro Izrael: Sendu la knabon kun mi, tiam ni leviĝos kaj iros, por ke ni vivu kaj ne mortu, ni kaj vi kaj niaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Mi garantios por li, el miaj manoj vi lin postulos. Se mi ne revenigos lin al vi kaj ne starigos antaŭ via vizaĝo, tiam mi estos kulpa antaŭ vi dum la tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Se ni ne prokrastus, ni jam du fojojn estus revenintaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Tiam diris al ili ilia patro Izrael: Se estas tiel, tiam faru jene: prenu el la plej bonaj fruktoj de la lando en viajn vazojn, kaj alportu al la homo donacon: iom da balzamo kaj iom da mielo, aromaĵon kaj mirhon, pistakojn kaj migdalojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Kaj da mono prenu duoblan sumon en viajn manojn, kaj la monon, kiu estis metita returne en la aperturojn de viaj sakoj, redonu per viaj manoj: eble okazis eraro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Kaj vian fraton prenu, kaj leviĝu kaj iru returne al tiu homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Kaj Dio la Plejpotenca akirigu al vi kompaton de tiu homo, ke li resendu kun vi vian alian fraton kaj Benjamenon; sed mi, se mi seninfaniĝis, mi restu seninfana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Kaj la homoj prenis tiujn donacojn, kaj da mono ili prenis duoblan sumon en siajn manojn, kaj ankaŭ Benjamenon; kaj ili leviĝis kaj iris Egiptujon kaj stariĝis antaŭ Jozef.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Kiam Jozef vidis kun ili Benjamenon, li diris al la estro de sia domo: Enkonduku tiujn homojn en la domon, kaj buĉu bruton kaj pretigu; ĉar kun mi manĝos tiuj homoj hodiaŭ tagmeze.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Kaj la homo faris, kiel diris Jozef, kaj la homo enkondukis tiujn homojn en la domon de Jozef.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Kaj tiuj homoj ektimis, kiam oni enkondukis ilin en la domon de Jozef, kaj ili diris: Pro la mono, kiu antaŭe estis metita returne en niajn sakojn, oni enkondukis nin, por ĵeti sur nin kalumnion kaj ataki nin, kaj preni nin kiel sklavojn kune kun niaj azenoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Kaj ili aliris al la homo, kiu estis estro super la domo de Jozef, kaj ekparolis al li ĉe la pordo de la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'Kaj ili diris: Pardonu, nia sinjoro! ni estis venintaj, por aĉeti panon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'sed kiam ni venis al la noktohaltejo kaj ni malfermis niajn sakojn, ni ekvidis, ke la mono de ĉiu el ni estas en la aperturo de lia sako, nia mono laŭ ĝia plena pezo; tial ni ĝin realportis per niaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Kaj alian monon ni alportis per niaj manoj, por aĉeti panon. Ni ne scias, kiu metis nian monon en niajn sakojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Kaj li diris: Estu trankvilaj, ne timu. Via Dio kaj la Dio de via patro donis al vi trezoron en viajn sakojn; vian monon mi ricevis. Kaj li elkondukis al ili Simeonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Kaj tiu homo enkondukis ilin en la domon de Jozef kaj donis akvon, kaj ili lavis siajn piedojn; kaj li donis manĝon al iliaj azenoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Kaj ili pretigis la donacojn por la veno de Jozef tagmeze; ĉar ili aŭdis, ke tie ili manĝos panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Kaj Jozef venis hejmen; kaj ili alportis al li en la domon la donacojn, kiujn ili havis en la manoj, kaj kliniĝis al li ĝis la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Kaj li demandis ilin pri ilia farto, kaj diris: Ĉu bone fartas via maljuna patro, pri kiu vi diris al mi? ĉu li vivas ankoraŭ?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Kaj ili diris: Via sklavo nia patro fartas bone; li vivas ankoraŭ. Kaj ili kliniĝis kaj ĵetis sin antaŭ li sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Kaj li levis siajn okulojn, kaj ekvidis sian fraton Benjamen, la filon de lia patrino, kaj li diris: Ĉu tio estas via plej juna frato, pri kiu vi diris al mi? Kaj li diris: Dio vin favoru, mia filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Kaj Jozef forrapidis, ĉar ekflamis lia interno pro lia frato kaj li volis plori. Kaj li eniris en internan ĉambron kaj ploris tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Sed li lavis sian vizaĝon kaj eliris, kaj tenis sin forte, kaj diris: Surtabligu panon!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Kaj oni surtabligis por li aparte, kaj por ili aparte, kaj por la Egiptoj, kiuj manĝis kun li, aparte; ĉar la Egiptoj ne povas manĝi panon kun Hebreoj: tio estas abomenindaĵo por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Kaj ili sidiĝis antaŭ li, pli maljuna laŭ sia maljuneco kaj pli juna laŭ sia juneco; kaj la homoj miris unu antaŭ alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Kaj oni portis al ili manĝaĵon de lia tablo; sed la porcio de Benjamen estis kvinoble pli granda, ol la porcioj de ĉiuj. Kaj ili trinkis kaj ebriiĝis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Kaj Jozef ordonis al la estro de sia domo jene: Plenigu la sakojn de tiuj homoj per greno tiom, kiom ili nur povas porti, kaj metu la monon de ĉiu en la aperturon de lia sako;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'kaj mian pokalon, la arĝentan pokalon, metu en la aperturon de la sako de la plej juna, kune kun la mono por lia greno. Kaj tiu faris, kiel Jozef diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Kiam eklumis la mateno, oni forsendis la homojn, ilin kaj iliajn azenojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Kiam ili eliris el la urbo kaj ankoraŭ ne estis malproksime, Jozef diris al la estro de sia domo: Leviĝu, kuru post tiuj homoj, kaj kiam vi atingos ilin, diru al ili: Kial vi pagis malbonon por bono?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Ĝi estas ja tiu pokalo, el kiu trinkas mia sinjoro, kaj li ankaŭ aŭguras sur ĝi! vi agis malbone!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Kaj li kuratingis ilin kaj diris al ili tiujn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Kaj ili diris al li: Kial mia sinjoro parolas tiajn vortojn? Dio gardu viajn sklavojn de farado de tia afero!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Jen la monon, kiun ni trovis en la aperturoj de niaj sakoj, ni realportis al vi el la lando Kanaana; kiel do ni ŝtelus el la domo de via sinjoro arĝenton aŭ oron?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Tiu el viaj sklavoj, ĉe kiu oni ĝin trovos, mortu, kaj ankaŭ ni fariĝu sklavoj al mia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Kaj li diris: Ĝi estu laŭ viaj vortoj: tiu, ĉe kiu ĝi troviĝos, estu mia sklavo, sed vi estos senkulpaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Kaj rapide ĉiu el ili mallevis sian sakon sur la teron, kaj ĉiu malfermis sian sakon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Kaj li serĉis; de la plej maljuna li komencis, kaj per la plej juna li finis. Kaj la pokalo troviĝis en la sako de Benjamen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Tiam ili disŝiris siajn vestojn, kaj ĉiu metis la ŝarĝon sur sian azenon, kaj ili reiris en la urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Kaj Jehuda kaj liaj fratoj venis en la domon de Jozef, kiu estis ankoraŭ tie, kaj ili ĵetis sin antaŭ li sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Kaj Jozef diris al ili: Kian aferon vi faris! ĉu vi ne scias, ke tia homo, kiel mi, facile divenos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Tiam Jehuda diris: Kion ni diru al mia sinjoro? kion ni parolu kaj per kio ni nin pravigu? Dio trovis la pekon de viaj sklavoj! jen ni estas sklavoj al mia sinjoro, ni kaj ankaŭ tiu, en kies manoj troviĝis la pokalo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Sed li diris: Dio min gardu de tia faro! la homo, en kies mano troviĝis la pokalo, estos sklavo al mi, sed vi iru en paco al via patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Tiam Jehuda aliris al li, kaj diris: Permesu, mia sinjoro, ke via sklavo diru vorton en la orelojn de mia sinjoro, kaj ne koleriĝu kontraŭ via sklavo, ĉar vi estas kiel Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Mia sinjoro demandis siajn sklavojn, dirante: Ĉu vi havas patron aŭ fraton?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Kaj ni diris al mia sinjoro: Ni havas maljunan patron, kaj malgrandan knabon, naskitan en lia maljuneco; kaj lia frato mortis, kaj li restis sola de sia patrino, kaj lia patro lin amas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Tiam vi diris al viaj sklavoj: Venigu lin al mi, ke mi lin rigardu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Sed ni diris al mia sinjoro: La knabo ne povas forlasi sian patron; ĉar se li forlasos sian patron, tiu mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Tiam vi diris al viaj sklavoj: Se ne venos kun vi via plej juna frato, tiam ne aperu plu antaŭ mia vizaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Kaj kiam ni venis al via sklavo nia patro, ni diris al li la vortojn de mia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Nia patro diris: Reiru, aĉetu por ni iom da greno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Sed ni diris: Ni ne povas iri; se estos kun ni nia plej juna frato, tiam ni iros; ĉar ni ne povas aperi antaŭ la vizaĝo de tiu homo, se nia plej juna frato ne estos kun ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Tiam via sklavo nia patro diris al ni: Vi scias, ke mia edzino naskis al mi du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'sed unu foriris de mi, kaj mi diris: Li estas disŝirita; kaj mi ne vidis lin ĝis nun;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'se vi ankaŭ ĉi tiun prenos de mi kaj lin trafos malfeliĉo, tiam vi enirigos miajn grizajn harojn kun malĝojo en Ŝeolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Kaj nun se mi venos al via sklavo mia patro kaj ne estos kun ni la knabo, al kies animo estas alligita lia animo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'tiam, ekvidinte, ke la knabo forestas, li mortos; kaj viaj sklavoj enirigos la grizajn harojn de via sklavo nia patro kun malĝojo en Ŝeolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Ĉar mi, via sklavo, garantiis por la knabo antaŭ mia patro, dirante: Se mi ne revenigos lin al vi, mi estos kulpa antaŭ mia patro por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Tial mi, via sklavo, restu anstataŭ la knabo kiel sklavo ĉe mia sinjoro, sed la knabo iru kun siaj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Ĉar kiel mi iros al mia patro, se la knabo ne estos kun mi? mi tiam vidus la malfeliĉon, kiu trafos mian patron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Tiam Jozef ne povis plu sin deteni antaŭ ĉiuj, kiuj staris ĉirkaŭ li, kaj li ekkriis: Elirigu ĉiujn for de mi. Kaj neniu restis ĉe li, kiam Jozef rekonigis sin al siaj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Kaj li laŭte ekploris, kaj aŭdis la Egiptoj, kaj aŭdis la domo de Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Kaj Jozef diris al siaj fratoj: Mi estas Jozef; ĉu mia patro vivas ankoraŭ? Sed liaj fratoj ne povis respondi al li, ĉar ili konfuziĝis antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Kaj Jozef diris al siaj fratoj: Aliru do al mi. Kaj ili aliris. Kaj li diris: Mi estas Jozef, via frato, kiun vi vendis en Egiptujon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Sed nun ne afliktiĝu, kaj ne bedaŭru, ke vi vendis min ĉi tien; ĉar por la savo de via vivo Dio sendis min antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Ĉar nun jam du jarojn daŭras la malsato en la lando, sed ankoraŭ dum kvin jaroj ne estos plugado nek rikoltado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Kaj Dio sendis min antaŭ vi, por vin restigi sur la tero kaj por konservi vian vivon per granda savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Sciu do, ne vi sendis min ĉi tien, sed Dio; kaj Li faris min patro al Faraono, kaj sinjoro super lia tuta domo, kaj reganto super la tuta Egipta lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Iru rapide al mia patro, kaj diru al li: Tiele diris via filo Jozef: Dio faris min sinjoro super la tuta Egiptujo; venu al mi, ne prokrastu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Vi loĝos en la lando Goŝen, kaj vi estos proksime de mi, vi kaj viaj filoj kaj la filoj de viaj filoj, kaj viaj ŝafoj kaj viaj bovoj, kaj ĉio, kion vi havas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Kaj mi nutros vin tie, ĉar ankoraŭ kvin jarojn daŭros la malsato; por ke ne mizeriĝu vi kaj via domo, kaj ĉio, kion vi havas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Kaj jen viaj okuloj nun vidas, kaj ankaŭ la okuloj de mia frato Benjamen, ke mia buŝo parolas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Kaj rakontu al mia patro pri mia tuta gloro en Egiptujo, kaj ĉion, kion vi vidis; kaj rapide venigu mian patron ĉi tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Kaj li ĵetis sin sur la kolon de sia frato Benjamen kaj ploris, kaj Benjamen ploris sur lia kolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Kaj li kisis ĉiujn siajn fratojn kaj ploris super ili. Poste liaj fratoj ekparolis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Kaj la famo venis en la domon de Faraono, ke venis la fratoj de Jozef. Kaj tio plaĉis al Faraono kaj al liaj servantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Kaj Faraono diris al Jozef: Diru al viaj fratoj: Faru tion, ŝarĝu viajn brutojn kaj iru en la landon Kanaanan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'kaj prenu vian patron kaj viajn familiojn, kaj venu al mi; mi donos al vi ĉion bonan en la Egipta lando, kaj vi manĝos la grasaĵon de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Kaj ordonu al ili jene: Prenu al vi el la Egipta lando veturilojn por viaj infanoj kaj virinoj, kaj kunprenu vian patron kaj venu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Kaj ne tro zorgu pri viaj aĵoj; ĉar ĉio bona en la Egipta lando estas al via dispono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Kaj la filoj de Izrael faris tiel. Kaj Jozef donis al ili veturilojn laŭ la ordono de Faraono, kaj li donis al ili provizojn por la vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Al ĉiuj li donis novajn vestojn, sed al Benjamen li donis tricent arĝentajn monerojn kaj kvin novajn vestojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Kaj por sia patro li sendis dek azenojn, ŝarĝitajn per bonaĵo el Egiptujo, kaj dek azeninojn, ŝarĝitajn per greno, pano, kaj manĝaĵo por lia patro por la vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Kaj li forsendis siajn fratojn, kaj ili iris. Kaj li diris al ili: Ne malpacu dum la vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Kaj ili eliris el Egiptujo kaj venis en la landon Kanaanan al sia patro Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Kaj ili sciigis al li, dirante: Jozef vivas ankoraŭ, kaj li regas nun super la tuta Egipta lando. Kaj lia koro konfuziĝis, ĉar li ne kredis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Kaj ili rediris al li ĉiujn vortojn de Jozef, kiujn li diris al ili; kaj li vidis la veturilojn, kiujn Jozef sendis, por veturigi lin, kaj tiam la spirito de ilia patro Jakob reviviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Kaj Izrael diris: Sufiĉas, ke mia filo Jozef ankoraŭ vivas: mi iros kaj vidos lin, antaŭ ol mi mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Izrael ekiris kun ĉio, kion li havis, kaj li venis en Beer-Ŝeban, kaj li alportis oferojn al la Dio de sia patro Isaak.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Kaj Dio diris al Izrael en nokta vizio: Jakob! Jakob! Kaj tiu diris: Jen mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Kaj Li diris: Mi estas Dio, la Dio de via patro. Ne timu iri Egiptujon, ĉar Mi tie faros vin granda popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Mi iros kun vi Egiptujon, kaj Mi ankaŭ revenigos vin; kaj Jozef metos sian manon sur viajn okulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Kaj Jakob leviĝis el Beer-Ŝeba; kaj la filoj de Izrael ekveturigis sian patron Jakob kaj siajn infanojn kaj siajn edzinojn sur la veturiloj, kiujn sendis Faraono, por alveturigi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Kaj ili prenis siajn brutojn, kaj sian havon, kiun ili akiris en la lando Kanaana, kaj venis Egiptujon, Jakob kaj lia tuta idaro kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Siajn filojn kaj nepojn, siajn filinojn kaj nepinojn, kaj sian tutan idaron li venigis kun si en Egiptujon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Jen estas la nomoj de la filoj de Izrael, kiuj venis Egiptujon: Jakob kaj liaj filoj. La unuenaskito de Jabob, Ruben.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Kaj la filoj de Ruben: Ĥanoĥ kaj Palu kaj Ĥecron kaj Karmi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Kaj la filoj de Simeon: Jemuel kaj Jamin kaj Ohad kaj Jaĥin kaj Coĥar, kaj Ŝaul, filo de Kanaanidino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Kaj la filoj de Levi: Gerŝon, Kehat, kaj Merari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Kaj la filoj de Jehuda: Er kaj Onan kaj Ŝela kaj Perec kaj Zeraĥ; sed Er kaj Onan mortis en la lando Kanaana. Kaj la filoj de Perec estis: Ĥecron kaj Ĥamul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Kaj la filoj de Isaĥar: Tola kaj Puva kaj Job kaj Ŝimron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Kaj la filoj de Zebulun: Sered kaj Elon kaj Jaĥleel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Tio estas la filoj de Lea, kiujn ŝi naskis al Jakob en Mezopotamio, kaj lia filino Dina. La nombro de ĉiuj animoj de liaj filoj kaj filinoj estis tridek tri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Kaj la filoj de Gad: Cifjon kaj Ĥagi, Ŝuni kaj Ecbon, Eri kaj Arod kaj Areli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Kaj la filoj de Aŝer: Jimna kaj Jiŝva kaj Jiŝvi kaj Beria, kaj Seraĥ, ilia fratino; kaj la filoj de Beria: Ĥeber kaj Malkiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Tio estas la filoj de Zilpa, kiun Laban donis al sia filino Lea; kaj ŝi naskis ilin al Jakob, dek ses animojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'La filoj de Raĥel, edzino de Jakob: Jozef kaj Benjamen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Kaj al Jozef en la lando Egipta naskiĝis Manase kaj Efraim, kiujn naskis al li Asnat, filino de Poti-Fera, pastro el On.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Kaj la filoj de Benjamen: Bela kaj Beĥer kaj Aŝbel, Gera kaj Naaman, Eĥi kaj Roŝ, Mupim kaj Ĥupim kaj Ard.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Tio estas la filoj de Raĥel, kiuj naskiĝis al Jakob, kune dek kvar animoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Kaj la filoj de Dan: Ĥuŝim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Kaj la filoj de Naftali: Jaĥceel kaj Guni kaj Jecer kaj Ŝilem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Tio estas la filoj de Bilha, kiun donis Laban al sia filino Raĥel; ŝi naskis ilin al Jakob, kune sep animojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'La nombro de ĉiuj animoj, kiuj venis kun Jakob en Egiptujon, kiuj eliris el lia lumbo, krom la edzinoj de la filoj de Jakob, estis sesdek ses.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Kaj la filoj de Jozef, kiuj naskiĝis al li en Egiptujo, estis du animoj. La nombro de ĉiuj animoj de la domo de Jakob, kiuj venis Egiptujon, estis sepdek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Jehudan li sendis antaŭ si al Jozef, por ke li informu lin antaŭe pri Goŝen. Kaj ili venis en la landon Goŝen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Kaj Jozef jungis sian ĉaron kaj veturis renkonte al sia patro Izrael en la landon Goŝen. Kaj kiam li ekvidis lin, li ĵetis sin sur lian kolon kaj longe ploris sur lia kolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Kaj Izrael diris al Jozef: Nun mi volonte mortos, vidinte vian vizaĝon, ĉar vi vivas ankoraŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Kaj Jozef diris al siaj fratoj kaj al la domo de sia patro: Mi iros kaj rakontos al Faraono, kaj diros al li: Miaj fratoj kaj la domo de mia patro, kiuj estis en la lando Kanaana, venis al mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'kaj tiuj homoj estas paŝtistoj, ĉar ili estas brutedukistoj; kaj siajn malgrandajn kaj grandajn brutojn, kaj ĉion, kion ili havas, ili kunportis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Kaj se Faraono vin alvokos, kaj diros: Kio estas via okupo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'tiam diru: Viaj sklavoj estis brutedukistoj de nia juneco ĝis nun, kiel ni, tiel ankaŭ niaj patroj; por ke vi enloĝiĝu en la lando Goŝen; ĉar ĉiu paŝtisto estas abomenindaĵo por la Egiptoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Jozef venis kaj sciigis al Faraono, kaj diris: Mia patro kaj miaj fratoj kaj iliaj malgrandaj kaj grandaj brutoj, kaj ĉio, kio apartenas al ili, venis el la lando Kanaana, kaj nun ili estas en la lando Goŝen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Kaj el inter siaj fratoj li prenis kvin homojn kaj starigis ilin antaŭ Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Kaj Faraono diris al liaj fratoj: Kio estas via okupo? Kaj ili diris al Faraono: Viaj sklavoj estas brutedukistoj, kiel ni, tiel ankaŭ niaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Kaj ili diris al Faraono: Ni venis, por loĝi en la lando; ĉar ne ekzistas paŝtaĵo por la brutoj de viaj sklavoj, ĉar forta estas la malsato en la lando Kanaana; permesu do, ke viaj sklavoj loĝu en la lando Goŝen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Tiam Faraono diris al Jozef jene: Via patro kaj viaj fratoj venis al vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'la lando Egipta estas antaŭ vi; en la plej bona loko de la lando loĝigu vian patron kaj viajn fratojn; ili loĝu en la lando Goŝen; kaj se vi scias, ke estas inter ili kapablaj homoj, faru ilin administrantoj de miaj brutoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Kaj Jozef enkondukis sian patron Jakob kaj starigis lin antaŭ Faraono; kaj Jakob benis Faraonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Faraono diris al Jakob: Kian aĝon vi havas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Kaj Jakob diris al Faraono: La nombro de la jaroj de mia migrado estas cent tridek jaroj; malmultaj kaj malbonaj estis la jaroj de mia vivo, kaj ili ne atingis la nombron de la jaroj de la vivo de miaj patroj dum ilia migrado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Kaj Jakob benis Faraonon kaj foriris de Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Kaj Jozef enloĝigis sian patron kaj siajn fratojn, kaj donis al ili posedaĵon en la Egipta lando, en la lando Rameses, kiel Faraono ordonis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Kaj Jozef havigis panon al sia patro kaj al siaj fratoj kaj al la tuta domo de sia patro, laŭ la nombro de la infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Ne estis pano sur la tuta tero, ĉar la malsato estis tre forta; kaj senfortiĝis de la malsato la lando Egipta kaj la lando Kanaana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Kaj Jozef kolektis la tutan monon, kiu troviĝis en la lando Egipta kaj en la lando Kanaana, pro la greno, kiun oni aĉetadis; kaj Jozef enportis la tutan monon en la domon de Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Kiam ne estis plu mono en la lando Egipta kaj en la lando Kanaana, ĉiuj Egiptoj venis al Jozef, kaj diris: Donu al ni panon; kial ni mortu antaŭ vi pro tio, ke ni jam ne havas monon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Tiam Jozef diris: Donu viajn brutojn; kaj mi donos al vi panon pro viaj brutoj, se vi jam ne havas monon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Kaj ili alkondukis siajn brutojn al Jozef; kaj Jozef donis al ili panon pro ĉevaloj, ŝafoj, bovoj, kaj azenoj, kaj li provizadis al ili panon pro ĉiuj iliaj brutoj en tiu jaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Kiam finiĝis tiu jaro, ili venis al li en la dua jaro, kaj diris al li: Ni ne kaŝos antaŭ nia sinjoro, ke monon ni jam ne havas, kaj la brutoj estas ĉe nia sinjoro; nenio restis antaŭ nia sinjoro krom niaj korpoj kaj nia tero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'kial ni pereu antaŭ viaj okuloj, ni kaj nia tero? aĉetu nin kaj nian teron pro la pano, kaj ni kaj nia tero estu sklavoj al Faraono; kaj donu semon, por ke ni vivu kaj ne mortu kaj la tero ne dezertiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Kaj Jozef aĉetis la tutan Egiptan teron por Faraono; ĉar la Egiptoj vendis ĉiu sian kampon, ĉar forte premis ilin la malsato. Kaj la tero fariĝis propraĵo de Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Kaj la popolon li transirigis en la urbojn, de unu fino de Egiptujo ĝis la alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Nur la teron de la pastroj li ne aĉetis; ĉar la pastroj havis parton, difinitan de Faraono, kaj ili manĝadis sian parton, kiun donis al ili Faraono, tial ili ne vendis sian teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Kaj Jozef diris al la popolo: Jen mi aĉetis vin hodiaŭ kaj vian teron por Faraono; jen mi donas al vi semon, kaj prisemu la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Kaj kiam vi havos rikolton, vi donos kvinonon al Faraono, kaj kvar partoj apartenos al vi, por prisemi la kampon kaj por manĝi, por vi, por ĉio, kio estas en viaj domoj, kaj por viaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Kaj ili diris: Vi konservis nian vivon; ni akiru favoron de nia sinjoro, kaj ni estu sklavoj al Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Kaj Jozef faris ĝin leĝo ĝis la hodiaŭa tago: de la tero Egipta kvinono de la produktoj apartenas al Faraono. Nur la tero de la pastroj ne fariĝis propraĵo de Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Kaj Izrael ekloĝis en la lando Egipta, en la lando Goŝen; kaj ili posedis ĝin kaj fruktis kaj multiĝis forte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Kaj Jakob vivis en la lando Egipta dek sep jarojn. Kaj la daŭro de la vivo de Jakob estis cent kvardek sep jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Kiam alproksimiĝis la tempo, kiam Izrael devis morti, li alvokis sian filon Jozef, kaj diris al li: Se mi akiris vian favoron, metu vian manon sub mian femuron kaj faru al mi favorkoraĵon kaj fidelaĵon, ne enterigu min en Egiptujo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'sed mi kuŝu kun miaj patroj; elportu min el Egiptujo kaj entombigu min en ilia tombujo. Kaj tiu diris: Mi faros, kiel vi diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Kaj li diris: Ĵuru al mi. Kaj tiu ĵuris. Kaj Izrael adorkliniĝis sur la kapa parto de la lito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Post tiuj okazintaĵoj oni sciigis al Jozef: Jen, via patro estas malsana. Kaj li prenis kun si siajn du filojn, Manase kaj Efraim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Kaj oni sciigis al Jakob, dirante: Jen via filo Jozef venas al vi. Tiam Izrael streĉis siajn fortojn kaj sidiĝis sur la lito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Kaj Jakob diris al Jozef: Dio la Plejpotenca aperis al mi en Luz, en la lando Kanaana, kaj benis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'Kaj Li diris al mi: Mi fruktigos vin kaj multigos vin kaj faros vin amaso da popoloj, kaj Mi donos ĉi tiun landon al via idaro post vi kiel eternan posedaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Kaj nun viaj du filoj, kiuj naskiĝis al vi en la lando Egipta antaŭ mia alveno al vi en Egiptujon, estas miaj; Efraim kaj Manase estu al mi, kiel Ruben kaj Simeon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Sed viaj infanoj, kiuj naskiĝos al vi post ili, estu viaj; per la nomo de siaj fratoj ili estos nomataj en sia hereda parto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Kiam mi venis el Mezopotamio, mortis ĉe mi Raĥel en la lando Kanaana, dum la vojo, kiam restis ankoraŭ iom da tero ĝis Efrata; kaj mi enterigis ŝin tie sur la vojo al Efrata, kiu estas nomata ankaŭ Bet-Leĥem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Kaj Izrael ekvidis la filojn de Jozef, kaj diris: Kiuj estas ĉi tiuj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Kaj Jozef diris al sia patro: Ili estas miaj filoj, kiujn donis al mi Dio ĉi tie. Kaj tiu diris: Alkonduku ilin al mi, kaj mi benos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'La okuloj de Izrael malfortiĝis de maljuneco, li ne povis bone vidi. Jozef alkondukis ilin al li, kaj li kisis ilin kaj ĉirkaŭprenis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Kaj Izrael diris al Jozef: Vidi vian vizaĝon mi ne esperis, kaj jen Dio vidigis al mi eĉ vian idaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Kaj Jozef forigis ilin de liaj genuoj, kaj kliniĝis antaŭ li vizaĝaltere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Kaj Jozef prenis ambaŭ, Efraimon per sia dekstra mano, kontraŭ la maldekstra de Izrael, kaj Manasen per sia maldekstra mano, kontraŭ la dekstra de Izrael, kaj alkondukis ilin al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Sed Izrael etendis sian dekstran manon kaj metis ĝin sur la kapon de Efraim, kvankam li estis la pli juna, kaj sian maldekstran sur la kapon de Manase; li intence tiel faris per siaj manoj, ĉar Manase estis la unuenaskito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Kaj li benis Jozefon, kaj diris: Dio, antaŭ kiu iradis miaj patroj Abraham kaj Isaak, Dio, kiu paŝtis min de mia naskiĝo ĝis la nuna tago,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'la anĝelo, kiu savis min de ĉia malbono-Li benu la knabojn; oni nomu ilin per mia nomo kaj per la nomo de miaj patroj Abraham kaj Isaak, kaj ili kresku kaj multiĝu sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Jozef vidis, ke lia patro metis sian dekstran manon sur la kapon de Efraim, kaj tio ne plaĉis al li; kaj li prenis la manon de sia patro, por deturni ĝin de la kapo de Efraim sur la kapon de Manase.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Kaj Jozef diris al sia patro: Ne tiel, mia patro, ĉar ĉi tiu estas la unuenaskito; metu vian dekstran manon sur lian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Sed lia patro rifuzis, kaj diris: Mi scias, mia filo, mi scias; li ankaŭ fariĝos popolo kaj li ankaŭ fariĝos granda, sed lia pli juna frato estos pli granda ol li, kaj lia idaro estos multenombra inter la popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Kaj li benis ilin en tiu tago, dirante: Per vi benados Izrael, dirante: Dio vin faru kiel Efraim kaj Manase. Kaj li metis Efraimon antaŭ Manase.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Kaj Izrael diris al Jozef: Jen mi mortas; kaj Dio estos kun vi kaj revenigos vin en la landon de viaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Kaj mi donas al vi unu pecon da lando preferece antaŭ viaj fratoj, kiun mi prenis el la manoj de la Amoridoj per mia glavo kaj pafarko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Kaj Jakob alvokis siajn filojn, kaj diris: Kolektiĝu, kaj mi sciigos al vi, kio fariĝos al vi en la tempo venonta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Kunvenu kaj aŭskultu, filoj de Jakob, Kaj aŭskultu Izraelon, vian patron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben, vi estas mia unuenaskito, Mia forto kaj komenco de mia vireco, Supro de digno kaj supro de potenco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Rapidema kiel akvo, vi ne staros plej alte, Ĉar vi supreniris sur la liton de via patro; Tiam vi malhonoris mian liton per la supreniro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeon kaj Levi, fratoj; Iloj kruelaj estas viaj glavoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'En ilian konsilon mia animo ne iru, Al ilia kunveno ne aliĝu mia honoro; Ĉar en sia kolero ili mortigis viron Kaj pro sia kaprico ili kripligis bovon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Malbenita estu ilia kolero, ĉar ĝi estas forta, Kaj ilia furiozo, ĉar ĝi estas kruela. Mi dividos ilin en Jakob, Kaj mi disĵetos ilin en Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Jehuda, vin laŭdos viaj fratoj; Via mano estas sur la nuko de viaj malamikoj; Kliniĝos antaŭ vi la filoj de via patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Juna leono estas Jehuda; De ĉasakiro, mia filo, vi leviĝis. Li genuiĝis, kuŝiĝis kiel leono kaj kiel leonino; Kiu lin levos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Ne forpreniĝos sceptro de Jehuda, Nek regbastono de inter liaj piedoj, Ĝis venos paco Kaj al li humiliĝos la popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Li alligas al la vinbertrunko sian azenidon Kaj al la delikata vinberbranĉo la filon de sia azenino; Li lavas en vino sian veston Kaj en sango de vinberoj sian mantelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Liaj okuloj estas ruĝaj de vino Kaj la dentoj blankaj de lakto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zebulun loĝos ĉe la bordo de maro, Ĉe albordiĝejo de ŝipoj, Kaj lia limo atingos Cidonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Isaĥar estas fortosta azeno; Li kuŝos inter la baraĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Kaj li vidis, ke ripozo estas bona Kaj la tero estas agrabla; Kaj li klinis sian ŝultron por portado Kaj fariĝis laboristo por tributo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan juĝos sian popolon, Kiel unu el la triboj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan estos serpento ĉe la vojo, Cerasto ĉe la irejo, Mordanto de kalkano de ĉevalo, Ke ĝia rajdanto falas malantaŭen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Vian helpon mi esperas, ho Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gadon premos amaso, Sed li repremos ĝin je la kalkano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Ĉe Aŝer estas grasa lia pano, Kaj li liverados frandaĵojn al reĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Naftali estas belkura cervo; Li donas belajn parolojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Fruktoporta arbo estas Jozef, Fruktoporta arbo super fonto; La branĉoj etendiĝis super la muron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Ĉagrenis lin pafistoj Kaj pafis kaj malamikis kontraŭ li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Sed forta restis lia pafarko Kaj elastaj estas liaj brakoj, Per la manoj de la Potenculo de Jakob, Per la Paŝtisto, la Roko de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'La Dio de via patro donos al vi helpon, La Plejpotenculo benos vin Per benoj de la ĉielo supre, Per benoj de la abismo, kiu kuŝas malsupre, Per benoj de la mamoj kaj de la utero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'La benoj de via patro estas pli fortaj, Ol la benoj de miaj gepatroj, Ĝis la limo de la eternaj altaĵoj. Ili estu sur la kapo de Jozef Kaj sur la verto de la elektito inter liaj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamen estas lupo karnoŝira; Matene li manĝos ĉasakiron, Kaj vespere li dividos rabaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Tio estas ĉiuj dek du triboj de Izrael; kaj tio estas, kion diris al ili ilia patro; kaj li benis ilin, ĉiun per aparta beno li benis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Kaj li ordonis al ili, kaj diris al ili: Mi alkolektiĝas al mia popolo; enterigu min apud miaj patroj en la kaverno, kiu troviĝas sur la kampo de Efron la Ĥetido,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'en la duobla kampa kaverno, kiu troviĝas antaŭ Mamre en la lando Kanaana kaj kiun Abraham aĉetis kune kun la kampo de Efron la Ĥetido kiel tomban posedaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Tie oni enterigis Abrahamon kaj lian edzinon Sara, tie oni enterigis Isaakon kaj lian edzinon Rebeka, kaj tie mi enterigis Lean,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'sur la kampo kaj en la kaverno sur ĝi, kiuj estas aĉetitaj de el la filoj de Ĥet.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Kaj Jakob finis la ordonadon al siaj filoj, kaj li kunigis siajn piedojn sur la lito, kaj mortis kaj alkolektiĝis al sia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Tiam Jozef ĵetis sin sur la vizaĝon de sia patro, kaj ploris super li kaj kisis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Kaj Jozef ordonis al siaj servantoj kuracistoj, balzami lian patron; kaj la kuracistoj balzamis Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Kaj pasis super li kvardek tagoj; ĉar tiel longe daŭras la tagoj de balzamado. Kaj la Egiptoj ploris pri li sepdek tagojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Kiam pasis la tagoj de lia priplorado, Jozef ekparolis al la domanoj de Faraono, dirante: Se mi akiris vian favoron, diru al Faraono jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Mia patro ĵurigis min, dirante: Jen mi mortas; en mia tombo, kiun mi elfosis al mi en la lando Kanaana, tie vi min enterigu. Nun mi volus iri, enterigi mian patron, kaj reveni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Kaj Faraono diris: Iru kaj enterigu vian patron, kiel li ĵurigis vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Kaj Jozef iris, por enterigi sian patron; kaj kun li iris ĉiuj servantoj de Faraono, la ĉefoj de lia domo kaj ĉiuj ĉefoj de la lando Egipta,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'kaj la tuta domo de Jozef, kaj liaj fratoj kaj la domo de lia patro; nur siajn infanojn kaj siajn malgrandajn kaj grandajn brutojn ili restigis en la lando Goŝen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Kun ili iris ankaŭ ĉaroj kaj rajdantoj; kaj la anaro estis tre granda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Ili venis al la placo Atad, kiu estas transe de Jordan, kaj ili faris tie grandan kaj fortan priploradon; kaj li funebris pri sia patro dum sep tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Kiam la loĝantoj de la lando Kanaana vidis la funebron sur la placo Atad, ili diris: Ĝi estas granda funebro ĉe la Egiptoj; tial la loko ricevis la nomon Abel-Micraim. Ĝi estas transe de Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Kaj liaj infanoj faris kun li, kiel li ordonis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Kaj liaj filoj forportis lin en la landon Kanaanan, kaj enterigis lin en la kampa duobla kaverno, kiun Abraham aĉetis kune kun la kampo kiel tomban posedaĵon de el Efron la Ĥetido, antaŭ Mamre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Kaj Jozef revenis Egiptujon, li kaj liaj fratoj, kaj ĉiuj, kiuj iris kun li, por enterigi lian patron, post kiam ili enterigis lian patron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Kiam la fratoj de Jozef vidis, ke ilia patro mortis, ili diris: Eble Jozef ekmalamos nin, kaj repagos al ni pro la tuta malbono, kiun ni faris al li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Tial ili sendis al Jozef, por diri al li: Via patro ordonis antaŭ sia morto jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Tiel diru al Jozef: Mi petas vin, pardonu la kulpon de viaj fratoj kaj ilian pekon, ĉar ili faris al vi malbonon. Nun pardonu do la kulpon de la sklavoj de la Dio de via patro. Kaj Jozef ploris, kiam ili parolis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Kaj iris liaj fratoj mem kaj ĵetis sin teren antaŭ li, kaj diris: Jen ni estas sklavoj al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Sed Jozef diris al ili: Ne timu; ĉar ĉu mi estas anstataŭ Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Vi intencis fari al mi malbonon; sed Dio aranĝis de tio bonon, por fari tiel, kiel nun estas, por konservi la vivon de multe da homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Kaj nun ne timu; mi nutros vin kaj viajn infanojn. Kaj li konsolis ilin kaj parolis al ili kore.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Kaj Jozef loĝis en Egiptujo, li kaj la domo de lia patro; kaj Jozef vivis cent dek jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Kaj Jozef vidis ĉe Efraim infanojn ĝis la tria generacio; ankaŭ la infanoj de Maĥir, filo de Manase, naskiĝis sur la genuoj de Jozef.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Kaj Jozef diris al siaj fratoj: Mi mortas, sed Dio rememoros vin, kaj elkondukos vin el ĉi tiu lando en la landon, pri kiu Li ĵuris al Abraham, Isaak, kaj Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Kaj Jozef ĵurigis la filojn de Izrael, dirante: Kiam Dio rememoros vin, tiam elportu miajn ostojn el ĉi tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Kaj Jozef mortis en la aĝo de cent dek jaroj; kaj oni balzamis lin kaj metis lin en ĉerkon en Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Jen estas la nomoj de la filoj de Izrael, kiuj venis Egiptujon kun Jakob; ĉiu venis kun siaj domanoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Simeon, Levi, kaj Jehuda;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Isaĥar, Zebulun, kaj Benjamen;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan kaj Naftali, Gad kaj Aŝer.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Kaj la nombro de ĉiuj animoj, kiuj eliris el la lumbo de Jakob, estis sepdek; kaj Jozef estis jam en Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Kaj mortis Jozef kaj ĉiuj liaj fratoj kaj tiu tuta generacio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Kaj la Izraelidoj fruktis kaj diskreskis kaj multiĝis kaj treege fortiĝis, kaj la lando pleniĝis de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Aperis en Egiptujo nova reĝo, kiu ne konis Jozefon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Kaj li diris al sia popolo: Jen la popolo de la Izraelidoj estas pli multenombra kaj pli forta ol ni;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'ni uzu do ruzon kontraŭ ĝi, por ke ĝi ne multiĝu, ĉar se okazos milito, tiam ankaŭ tiu popolo aliĝos al niaj malamikoj kaj militos kontraŭ ni kaj foriros el la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Kaj oni metis super ilin laborestrojn, por premi ilin per malfacilaj laboroj. Kaj ili konstruis por Faraono provizejajn urbojn Pitom kaj Rameses.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Sed ju pli oni premis ilin, des pli ili multiĝis kaj kreskis; kaj la Izraelidoj fariĝis teruraĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Kaj la Egiptoj laborigis la Izraelidojn kruele.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'Kaj ili maldolĉigis al ili la vivon per malfacila laboro super argilo kaj brikoj, kaj per ĉia laboro sur la kampo, per ĉiaj laboroj, kiujn ili kruele metis sur ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Kaj la reĝo de Egiptujo parolis al la Hebreaj akuŝistinoj, el kiuj unu estis nomata Ŝifra kaj la dua estis nomata Pua.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'Li diris: Kiam vi akuŝigos la Hebreinojn, rigardu la kuŝejon; se estas filo, mortigu lin, kaj se estas filino, lasu ŝin vivi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Sed la akuŝistinoj timis Dion, kaj ili ne faris, kiel diris al ili la reĝo de Egiptujo; kaj ili lasis la vivon al la virseksaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Kaj la reĝo de Egiptujo alvokis la akuŝistinojn, kaj diris al ili: Kial vi tion faras kaj lasas la vivon al la virseksaj infanoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Tiam la akuŝistinoj diris al Faraono: Ne kiel la Egiptaj virinoj estas la Hebreinoj; ili estas viglaj: antaŭ ol venas al ili la akuŝistino, ili jam estas naskintaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Kaj Dio faris bonon al la akuŝistinoj, kaj la popolo multiĝis kaj tre fortiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Kaj ĉar la akuŝistinoj timis Dion, Li konstruis al ili domojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Kaj Faraono ordonis al sia tuta popolo, dirante: Ĉiun filon, kiu naskiĝis, ĵetu en la Riveron, kaj ĉiun filinon lasu viva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Kaj iris unu homo el la domo de Levi kaj prenis edzinon Leviidinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Kaj la virino gravediĝis, kaj naskis filon; kaj ŝi vidis, ke li estas bela, kaj ŝi kaŝis lin dum tri monatoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Sed ŝi ne povis plu kaŝi lin, tial ŝi prenis por li keston el kanoj kaj ĉirkaŭŝmiris ĝin per asfalto kaj peĉo, kaj metis tien la infanon kaj metis ĝin inter la kanojn sur la bordo de la Rivero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Kaj lia fratino stariĝis malproksime, por sciiĝi, kio fariĝos kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Kaj la filino de Faraono malsupreniris, por lavi sin en la Rivero, kaj ŝiaj servantinoj iradis sur la bordo de la Rivero. Ŝi ekvidis la keston meze de la kanoj, kaj ŝi sendis sian sklavinon, ke ŝi ĝin prenu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Ŝi malfermis, kaj ekvidis la infanon; ĝi estis knabeto, kiu ploris. Kaj ŝi kompatis lin, kaj diris: Ĝi estas el la Hebreaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Tiam lia fratino diris al la filino de Faraono: Ĉu mi iru kaj voku al vi virinon nutrantinon el la Hebreinoj, ke ŝi nutru por vi la infanon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Kaj la filino de Faraono diris al ŝi: Iru. Kaj la knabino iris kaj vokis la patrinon de la infano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Kaj la filino de Faraono diris al ŝi: Prenu ĉi tiun infanon kaj nutru ĝin por mi, kaj mi pagos al vi. Kaj la virino prenis la infanon kaj nutris ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Kiam la infano grandiĝis, ŝi alportis lin al la filino de Faraono, kaj li fariĝis filo por ŝi, kaj ŝi donis al li la nomon Moseo, dirante: El la akvo mi lin eltiris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'En la tempo, kiam Moseo estis jam granda, li eliris al siaj fratoj kaj vidis iliajn malfacilajn laborojn; kaj li vidis, ke Egipto batas iun Hebreon el liaj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Tiam li turnis sin unuflanken kaj aliflanken, kaj vidinte, ke estas neniu, mortigis la Egipton kaj kaŝis lin en la sablo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Kaj li eliris en la sekvanta tago, kaj vidis, ke du Hebreoj malpacas. Kaj li diris al la ofendanto: Kial vi batas vian proksimulon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Kaj tiu diris: Kiu faris vin estro kaj juĝanto super ni? ĉu vi intencas mortigi min, kiel vi mortigis la Egipton? Tiam Moseo ektimis, kaj diris: Videble la afero fariĝis sciata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Kaj Faraono aŭdis pri tiu afero kaj deziris mortigi Moseon. Sed Moseo forkuris de Faraono kaj ekloĝis en la lando Midjana, kaj li loĝis apud puto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'La pastro Midjana havis sep filinojn. Kaj ili venis kaj ĉerpis akvon kaj plenigis la trogojn, por trinkigi la ŝafojn de sia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Sed venis la paŝtistoj kaj forpelis ilin. Tiam Moseo leviĝis kaj helpis ilin kaj trinkigis iliajn ŝafojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Kiam ili venis al sia patro Reuel, li diris: Kial vi tiel baldaŭ venis hodiaŭ?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Kaj ili diris: Iu Egipto savis nin el la manoj de la paŝtistoj, kaj li eĉ ĉerpis por ni kaj trinkigis la ŝafojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Tiam li diris al siaj filinoj: Kie do li estas? kial vi forlasis tiun homon? voku lin, ke li manĝu panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Kaj Moseo konsentis loĝi ĉe tiu homo; kaj tiu donis sian filinon Cipora al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Kaj ŝi naskis filon, kaj li donis al li la nomon Gerŝom, ĉar li diris: Fremdulo mi estis en lando fremda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Post longa tempo mortis la reĝo de Egiptujo. Kaj la Izraelidoj ĝemis pro la laboroj kaj kriis, kaj ilia kriado pro la laboroj venis supren al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Kaj Dio aŭdis ilian ĝemadon, kaj Dio rememoris Sian interligon kun Abraham, Isaak, kaj Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Kaj Dio rigardis la Izraelidojn, kaj Dio rememoris ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Moseo paŝtis la ŝafojn de Jitro, sia bopatro, pastro Midjana. Kaj li forkondukis la ŝafojn en malproksiman parton de la dezerto kaj venis al la Dia monto Ĥoreb.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Kaj aperis al li anĝelo de la Eternulo en flama fajro el la mezo de arbetaĵo. Kaj li vidis, ke jen la arbetaĵo brulas en la fajro, kaj tamen la arbetaĵo ne forbrulas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Kaj Moseo diris: Mi iros kaj rigardos tiun grandan fenomenon, kial la arbetaĵo ne forbrulas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'La Eternulo vidis, ke li iras, por rigardi, kaj Dio vokis al li el la mezo de la arbetaĵo, kaj diris: Moseo, Moseo! Kaj tiu diris: Jen mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Kaj Li diris: Ne alproksimiĝu ĉi tien; deprenu viajn ŝuojn de viaj piedoj, ĉar la loko, sur kiu vi staras, estas tero sankta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Ankoraŭ Li diris: Mi estas la Dio de via patro, la Dio de Abraham, la Dio de Isaak, kaj la Dio de Jakob. Kaj Moseo kovris sian vizaĝon, ĉar li timis rigardi Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Kaj la Eternulo diris: Mi vidis la mizeron de Mia popolo, kiu estas en Egiptujo, kaj Mi aŭdis ĝian kriadon kaŭze de ĝiaj premantoj; Mi scias ĝiajn suferojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Kaj Mi malsupreniris, por savi ĝin el la manoj de la Egiptoj kaj elirigi ĝin el tiu lando en landon bonan kaj vastan, en landon, en kiu fluas lakto kaj mielo, sur la lokon de la Kanaanidoj kaj la Ĥetidoj kaj la Amoridoj kaj la Perizidoj kaj la Ĥividoj kaj la Jebusidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Nun la krioj de la Izraelidoj venis al Mi; kaj Mi vidis la turmentojn, per kiuj la Egiptoj turmentas ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Iru do, Mi sendos vin al Faraono, kaj elkonduku Mian popolon la Izraelidojn el Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Kaj Moseo diris al Dio: Kiu mi estas, ke mi iru al Faraono kaj mi elkonduku la Izraelidojn el Egiptujo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Kaj Li diris: Mi estos kun vi; kaj tio estu por vi signo, ke Mi vin sendis: kiam vi estos elkondukinta Mian popolon el Egiptujo, vi faros servon al Dio sur ĉi tiu monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Kaj Moseo diris al Dio: Jen mi venos al la Izraelidoj, kaj diros al ili: La Dio de viaj patroj sendis min al vi; tiam ili diros al mi: Kia estas Lia nomo? Kion mi diru al ili?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Kaj Dio diris al Moseo: MI ESTAS, KIU ESTAS. Kaj Li diris: Tiel diru al la Izraelidoj: La Estanto sendis min al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Kaj plue Dio diris al Moseo: Tiel diru al la Izraelidoj: La Eternulo, la Dio de viaj patroj, la Dio de Abraham, la Dio de Isaak, kaj la Dio de Jakob, sendis min al vi. Tia estas Mia nomo por eterne, kaj tia estas memoraĵo pri Mi por ĉiuj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Iru, kaj kunvenigu la ĉefojn de Izrael, kaj diru al ili: La Eternulo, la Dio de viaj patroj, aperis al mi, la Dio de Abraham, Isaak, kaj Jakob, kaj Li diris: Mi atentis vin, kaj tion, kio estas farita al vi en Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Kaj Mi diris: Mi elirigos vin el la mizero de Egiptujo en la landon de la Kanaanidoj kaj la Ĥetidoj kaj la Amoridoj kaj la Perizidoj kaj la Ĥividoj kaj la Jebusidoj, en landon, en kiu fluas lakto kaj mielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Kaj ili aŭskultos vian voĉon, kaj vi venos, vi kaj la ĉefoj de Izrael, al la reĝo de Egiptujo, kaj vi diros al li: La Eternulo, la Dio de la Hebreoj, vokis nin; lasu do nin iri vojon de tri tagoj en la dezerton, por ke ni faru oferon al la Eternulo, nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Sed Mi scias, ke la reĝo de Egiptujo ne permesos al vi iri, se ne devigos lin forta mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Kaj Mi etendos Mian manon, kaj Mi batos Egiptujon per ĉiuj Miaj mirakloj, kiujn Mi faros meze de ĝi; kaj poste li lasos vin iri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Kaj Mi donos al tiu popolo favoron de la Egiptoj; kaj kiam vi iros, vi ne iros kun malplenaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Ĉiu virino petos de sia najbarino kaj de sia samdomanino vazojn arĝentajn kaj vazojn orajn kaj vestojn; kaj vi metos tion sur viajn filojn kaj sur viajn filinojn, kaj vi senhavigos la Egiptojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Moseo respondis kaj diris: Sed se ili ne kredos al mi kaj ne aŭskultos mian voĉon, kaj se ili diros: Ne aperis al vi la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Kaj la Eternulo diris al li: Kion vi tie havas en via mano? Kaj li diris: Bastonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Kaj Li diris: Ĵetu ĝin sur la teron. Kaj li ĵetis ĝin sur la teron, kaj ĝi fariĝis serpento; kaj Moseo forkuris de ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Sed la Eternulo diris al Moseo: Etendu vian manon, kaj kaptu ĝin je ĝia vosto (kaj li etendis sian manon kaj kaptis ĝin, kaj ĝi fariĝis bastono en lia mano),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'por ke ili kredu, ke aperis al vi la Eternulo, la Dio de iliaj patroj, la Dio de Abraham, la Dio de Isaak, kaj la Dio de Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Kaj la Eternulo diris al li plue: Metu vian manon en vian sinon. Kaj li metis sian manon en sian sinon; kaj kiam li elprenis ĝin, jen lia mano estis leprokovrita kvazaŭ neĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Kaj Li diris: Remetu vian manon en vian sinon (kaj li remetis sian manon en sian sinon; kaj kiam li elprenis ĝin el sia sino, jen ĝi denove fariĝis kiel lia karno);');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'kaj se ili ne kredos al vi kaj ne aŭskultos la voĉon de la unua signo, ili kredos al la voĉo de la alia signo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Kaj se ili ne kredos eĉ al ambaŭ tiuj signoj kaj ne aŭskultos vian voĉon, tiam prenu akvon el la Rivero kaj verŝu ĝin sur la sekan teron; kaj tiam la akvo, kiun vi prenis el la Rivero, fariĝos sango sur la seka tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Kaj Moseo diris al la Eternulo: Ho, mia Sinjoro, mi ne estas elokventa, nek de hieraŭ, nek de antaŭhieraŭ, nek de tiu tempo, kiam Vi komencis paroli al Via sklavo; ĉar mi havas nelertan buŝon kaj nelertan langon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Kaj la Eternulo diris al li: Kiu faris buŝon al la homo? aŭ kiu faras muta aŭ surda aŭ vidanta aŭ blinda? ĉu ne Mi, la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Kaj nun iru, kaj Mi estos kun via buŝo, kaj Mi instruos vin, kion vi devas paroli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Kaj li diris: Ho, mia Sinjoro, sendu iun alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Tiam ekflamis la kolero de la Eternulo kontraŭ Moseo, kaj Li diris: Mi scias ja, ke via frato Aaron, la Levido, estas elokventa; kaj jen li eĉ iras al vi renkonte, kaj kiam li vidos vin, li ekĝojos en sia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Kaj vi parolos al li kaj metos la vortojn en lian buŝon; kaj Mi estos kun via buŝo kaj kun lia buŝo, kaj Mi instruos vin, kion vi devas fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Kaj li parolos por vi al la popolo; kaj li estos via buŝo, kaj vi estos por li anstataŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Kaj ĉi tiun bastonon prenu en vian manon; per ĝi vi faros la signojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Moseo iris kaj revenis al sia bopatro Jitro, kaj diris al li: Mi volas iri kaj reveni al miaj fratoj, kiuj estas en Egiptujo, kaj vidi, ĉu ili vivas ankoraŭ. Kaj Jitro diris al Moseo: Iru en paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Kaj la Eternulo diris al Moseo en Midjanujo: Iru, revenu Egiptujon; ĉar mortis ĉiuj homoj, kiuj volis vin mortigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Tiam Moseo prenis sian edzinon kaj siajn filojn kaj sidigis ilin sur azeno, kaj ekiris al la lando Egipta. Kaj Moseo prenis la bastonon de Dio en sian manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Kaj la Eternulo diris al Moseo: Kiam vi revenos Egiptujon, tiam rigardu, ĉiujn miraklojn, kiujn Mi donis en vian manon, faru antaŭ Faraono. Sed Mi malmoligos lian koron, kaj li ne permesos al la popolo foriri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Kaj vi diru al Faraono: Tiel diris la Eternulo: Mia filo unuenaskita estas Izrael;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'kaj Mi diras al vi: Permesu, ke Mia filo iru kaj faru al Mi servon; se vi ne permesos al li iri, tiam Mi mortigos vian unuenaskitan filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Sur la vojo, en la noktohaltejo, renkontis lin la Eternulo kaj volis mortigi lin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'sed Cipora prenis akran ŝtonon, kaj detranĉis la prepucion de sia filo kaj ektuŝis liajn piedojn, kaj diris: Sanga fianĉo vi estas por mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Tiam Li forlasis lin. Kaj ŝi diris: Sanga fianĉo per la cirkumcido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Kaj la Eternulo diris al Aaron: Iru renkonte al Moseo en la dezerton. Kaj li iris kaj renkontis lin ĉe la monto de Dio, kaj kisis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Kaj Moseo diris al Aaron ĉiujn vortojn de la Eternulo, kiu sendis lin, kaj ĉiujn signojn, pri kiuj Li ordonis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Kaj iris Moseo kaj Aaron kaj kunvenigis ĉiujn ĉefojn de la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Kaj Aaron diris ĉiujn vortojn, kiujn la Eternulo diris al Moseo, kaj li faris la signojn antaŭ la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Kaj la popolo kredis. Kaj ili aŭdis, ke la Eternulo rememoris la Izraelidojn kaj vidis ilian mizeron, kaj ili kliniĝis kaj faris adoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Poste venis Moseo kaj Aaron, kaj diris al Faraono: Tiel diris la Eternulo, la Dio de Izrael: Permesu, ke Mia popolo iru kaj faru al Mi feston en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Sed Faraono diris: Kiu estas la Eternulo, kies voĉon mi devas obei kaj lasi Izraelon iri? mi ne konas la Eternulon, kaj al Izrael mi ne permesos iri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Kaj ili diris: La Dio de la Hebreoj vokis nin; permesu, ke ni iru vojon de tri tagoj en la dezerton kaj ni alportu oferon al la Eternulo, nia Dio, por ke Li ne frapu nin per pesto aŭ glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Sed la reĝo de Egiptujo diris al ili: Kial vi, Moseo kaj Aaron, fortiras la popolon de ĝiaj laboroj? iru al viaj laboroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Kaj Faraono diris: Jen multenombra estas nun la popolo de la lando, kaj vi volas liberigi ilin de iliaj laboroj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Kaj Faraono ordonis en tiu tago al la voktoj de la popolo kaj al ĝiaj kontrolistoj, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Ne donu plu pajlon al la popolo por la farado de la brikoj, kiel ĝis nun; ili mem iru kaj kolektu al si pajlon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Sed la nombron de la brikoj, kiun ili pretigas ĝis nun, postulu de ili, ne malgrandigu ĝin; ĉar ili vagas senlabore, tial ili krias: Ni iru kaj alportu oferon al nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Oni devas premi tiujn homojn per la laboro, por ke ili estu okupitaj de ĝi kaj ne atentu mensogajn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Tiam eliris la voktoj de la popolo kaj ĝiaj kontrolistoj, kaj diris al la popolo: Tiel diras Faraono: Mi ne donos al vi pajlon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'iru mem, prenu al vi pajlon, kie vi trovos; sed el via laboro nenio estos deprenata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Tiam la popolo disiĝis en la tuta lando Egipta, por kolekti pecojn da pajlo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Kaj la voktoj insistadis, dirante: Pretigu vian ĉiutagan laboron, kiel tiam, kiam vi havis pajlon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Kaj la kontrolistojn Izraelidojn, starigitajn super ili de la voktoj de Faraono, oni batadis, dirante: Kial vi ne pretigis vian ordonitan nombron da brikoj hieraŭ kaj hodiaŭ, kiel ĝis nun?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'La kontrolistoj Izraelidoj venis kaj kriis al Faraono, dirante: Kial vi agas tiel kun viaj sklavoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Pajlo ne estas donata al viaj sklavoj, kaj brikojn oni ordonas al ni fari; kaj nun viaj sklavoj estas batataj, kaj via popolo pekas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Sed li diris: Mallaboruloj vi estas, mallaboruloj, tial vi diras: Ni iru, ni alportu oferon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Kaj nun iru, laboru, kaj pajlon oni ne donos al vi, kaj la difinitan nombron da brikoj liveru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Kaj la kontrolistoj Izraelidoj vidis, ke estas al ili malbone, ĉar estas dirite: Ne malgrandigu la ĉiutagan nombron de viaj brikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Ili renkontis Moseon kaj Aaronon, kiuj staris antaŭ ili, kiam ili eliris de Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Kaj ili diris al tiuj: La Eternulo rigardu vin, kaj juĝu vin por tio, ke vi malbonodorigis nian odoron antaŭ Faraono kaj antaŭ liaj servantoj, kaj donis glavon en iliajn manojn, por mortigi nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Tiam Moseo turnis sin al la Eternulo, kaj diris: Mia Sinjoro! kial Vi faris malbonon al tiu popolo? kial Vi sendis min?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'De tiu tempo, kiam mi venis al Faraono, por paroli en Via nomo, li fariĝis pli malbona kontraŭ tiu popolo, kaj Vi ne savis Vian popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Sed la Eternulo diris al Moseo: Nun vi vidos, kion Mi faros al Faraono; ĉar pro mano forta li foririgos ilin kaj pro mano forta li elpelos ilin el sia lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Kaj Dio ekparolis al Moseo kaj diris al li: Mi estas la ETERNULO.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Mi aperis al Abraham, al Isaak, kaj al Jakob kiel Dio la Plejpotenca, sed Mian nomon ETERNULO Mi ne sciigis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Mi starigis Mian interligon kun ili, ke Mi donos al ili la landon Kanaanan, la landon de ilia migrado, en kiu ili loĝis kiel fremduloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Kaj Mi aŭdis la ĝemadon de la Izraelidoj, kiujn la Egiptoj premas per laboroj, kaj Mi rememoris Mian interligon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Tial diru al la Izraelidoj: Mi estas la Eternulo, kaj Mi elirigos vin el sub la jugo de Egiptujo, kaj Mi liberigos vin el ilia sklaveco, kaj Mi savos vin per etendita brako kaj grandaj juĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Kaj Mi prenos vin kiel Mian popolon, kaj Mi estos via Dio; kaj vi scios, ke Mi estas la Eternulo, via Dio, kiu elirigas vin el sub la jugo de Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Kaj Mi venigos vin en la landon, pri kiu Mi, levinte Mian manon, promesis, ke Mi donos ĝin al Abraham, al Isaak, kaj al Jakob, kaj Mi donos ĝin al vi kiel posedaĵon, Mi, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Moseo parolis tiel al la Izraelidoj; sed ili ne aŭskultis Moseon pro malforteco de spirito kaj pro la malfacilaj laboroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Eniru, diru al Faraono, la reĝo de Egiptujo, ke li ellasu la Izraelidojn el sia lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Moseo ekparolis antaŭ la Eternulo, dirante: Jen la Izraelidoj ne aŭskultas min, kiel do min aŭskultos Faraono? kaj mi havas nelertajn lipojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Sed la Eternulo ekparolis al Moseo kaj al Aaron, kaj donis al ili ordonojn por la Izraelidoj, kaj por Faraono, reĝo de Egiptujo, por elirigi la Izraelidojn el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Jen estas la ĉefoj de iliaj familioj: la filoj de Ruben, unuenaskito de Izrael: Ĥanoĥ kaj Palu, Ĥecron kaj Karmi. Tio estas la familioj de Ruben.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Kaj la filoj de Simeon: Jemuel kaj Jamin kaj Ohad kaj Jaĥin kaj Coĥar, kaj Ŝaul, filo de Kanaanidino. Tio estas la familioj de Simeon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Kaj jen estas la nomoj de la filoj de Levi laŭ ilia naskiĝo: Gerŝon kaj Kehat kaj Merari. La daŭro de la vivo de Levi estis cent tridek sep jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'La filoj de Gerŝon: Libni kaj Ŝimei, kun iliaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Kaj la filoj de Kehat: Amram kaj Jichar kaj Ĥebron kaj Uziel. La daŭro de la vivo de Kehat estis cent tridek tri jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Kaj la filoj de Merari: Maĥli kaj Muŝi. Tio estas la familioj de Levi laŭ ilia naskiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Amram prenis al si sian onklinon Joĥebed kiel edzinon, kaj ŝi naskis al li Aaronon kaj Moseon. La daŭro de la vivo de Amram estis cent tridek sep jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Kaj la filoj de Jichar: Koraĥ kaj Nefeg kaj Ziĥri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Kaj la filoj de Uziel: Miŝael kaj Elcafan kaj Sitri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Aaron prenis al si Eliŝeban, filinon de Aminadab kaj fratinon de Naĥŝon, kiel edzinon, kaj ŝi naskis al li Nadabon kaj Abihun, Eleazaron kaj Itamaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Kaj la filoj de Koraĥ: Asir kaj Elkana kaj Abiasaf. Tio estas la familioj de la Koraĥidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Eleazar, la filo de Aaron, prenis al si edzinon el la filinoj de Putiel, kaj ŝi naskis al li Pineĥason. Tio estas la ĉefoj de la Leviidoj laŭ iliaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Tio estas tiuj Aaron kaj Moseo, al kiuj la Eternulo diris: Elirigu la Izraelidojn el la lando Egipta laŭ iliaj taĉmentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Tio estas ili, kiuj parolis al Faraono, reĝo de Egiptujo, por elirigi la Izraelidojn el Egiptujo; tio estas Moseo kaj Aaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'En tiu tago, kiam la Eternulo parolis al Moseo en la lando Egipta,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'la Eternulo diris al Moseo jene: Mi estas la Eternulo. Diru al Faraono, reĝo de Egiptujo, ĉion, kion Mi diras al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Kaj Moseo diris antaŭ la Eternulo: Jen mi havas nelertajn lipojn; kiel do Faraono min aŭskultos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Sed la Eternulo diris al Moseo: Vidu, mi faris vin dio por Faraono; kaj via frato Aaron estos via profeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Vi parolos ĉion, kion Mi ordonos al vi; kaj via frato Aaron parolos al Faraono, ke li ellasu la Izraelidojn el sia lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Sed Mi malmoligos la koron de Faraono, kaj Mi multigos Miajn signojn kaj Miajn miraklojn en la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Kaj Faraono vin ne aŭskultos, kaj Mi metos Mian manon sur Egiptujon, kaj Mi elirigos Mian militistaron, Mian popolon, la Izraelidojn, el la lando Egipta per grandaj juĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Kaj la Egiptoj sciiĝos, ke Mi estas la Eternulo, kiam Mi etendos Mian manon super la Egiptojn kaj elirigos la Izraelidojn el inter ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Kaj Moseo kaj Aaron faris, kiel ordonis al ili la Eternulo; tiel ili faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Moseo havis la aĝon de okdek jaroj, kaj Aaron havis la aĝon de okdek tri jaroj, kiam ili parolis al Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Kaj la Eternulo ekparolis al Moseo kaj al Aaron, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Se Faraono diros al vi, ke vi faru miraklon, tiam diru al Aaron: Prenu vian bastonon kaj ĵetu ĝin antaŭ Faraonon; ĝi fariĝos serpento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Moseo kaj Aaron venis al Faraono, kaj faris tiel, kiel ordonis la Eternulo. Aaron ĵetis sian bastonon antaŭ Faraonon kaj antaŭ liajn servantojn, kaj ĝi fariĝis serpento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Tiam ankaŭ Faraono alvokis la saĝulojn kaj sorĉistojn; kaj ankaŭ ili, la Egiptaj sorĉistoj, per siaj sorĉoj faris tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Ĉiu el ili ĵetis sian bastonon, kaj ili fariĝis serpentoj; sed la bastono de Aaron englutis iliajn bastonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Kaj malmoliĝis la koro de Faraono, kaj li ne aŭskultis ilin, kiel diris la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Tiam la Eternulo diris al Moseo: Obstina estas la koro de Faraono, li ne volas forliberigi la popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Iru al Faraono matene; li eliros al la akvo; stariĝu renkonte al li sur la bordo de la rivero, kaj la bastonon, kiu transformiĝis en serpenton, prenu en vian manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Kaj diru al li: La Eternulo, Dio de la Hebreoj, sendis min al vi, por diri: Permesu al Mia popolo iri kaj fari al Mi servon en la dezerto; sed jen vi ĝis nun ne obeis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Tiel diris la Eternulo: Per tio vi sciiĝos, ke Mi estas la Eternulo: jen per la bastono, kiu estas en mia mano, mi frapos la akvon, kiu estas en la rivero, kaj ĝi transformiĝos en sangon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Kaj la fiŝoj, kiuj estas en la rivero, mortos, kaj la rivero malbonodoros, kaj la Egiptoj abomenos trinki akvon el la rivero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Kaj la Eternulo diris al Moseo: Diru al Aaron: Prenu vian bastonon, kaj etendu vian manon super la akvojn de la Egiptoj, super iliajn riverojn, super iliajn torentojn kaj super iliajn lagojn kaj super ĉian kolektiĝon de iliaj akvoj, kaj ili fariĝu sango; kaj estu sango en la tuta lando Egipta, en la vazoj lignaj kaj en la vazoj ŝtonaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Kaj Moseo kaj Aaron faris tiel, kiel ordonis la Eternulo. Kaj li levis la bastonon, kaj frapis la akvon, kiu estis en la rivero, antaŭ la okuloj de Faraono kaj antaŭ la okuloj de liaj servantoj; kaj la tuta akvo, kiu estis en la rivero, transformiĝis en sangon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Kaj la fiŝoj, kiuj estis en la rivero, mortis, kaj la rivero fariĝis malbonodora, kaj la Egiptoj ne povis trinki akvon el la rivero; kaj estis sango en la tuta lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Sed tiel same faris la sorĉistoj de Egiptujo per siaj sorĉoj. Kaj malmoliĝis la koro de Faraono, kaj li ne aŭskultis ilin, kiel diris la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Kaj Faraono turniĝis kaj eniris en sian domon, kaj lia koro ne atentis eĉ tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Kaj ĉiuj Egiptoj ekfosis ĉirkaŭ la rivero pro akvo por trinki, ĉar ili ne povis trinki la akvon el la rivero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Pasis sep tagoj, post kiam la Eternulo frapis la riveron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Kaj la Eternulo diris al Moseo: Iru al Faraono, kaj diru al li: Tiel diris la Eternulo: Permesu al Mia popolo iri, por ke ĝi faru servon al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Kaj se vi ne volos permesi tion, jen Mi frapos vian tutan regionon per ranoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'kaj eksvarmos la rivero per ranoj, kaj ili elrampos kaj venos en vian domon kaj en vian dormoĉambron kaj sur vian liton kaj en la domojn de viaj servantoj kaj de via popolo kaj en viajn fornojn kaj en viajn pastujojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'kaj sur vin kaj sur vian popolon kaj sur ĉiujn viajn servantojn rampos la ranoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Kaj la Eternulo diris al Moseo: Diru al Aaron: Etendu vian manon kun via bastono super la riverojn, super la torentojn, kaj super la lagojn, kaj elirigu la ranojn sur la landon Egiptan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Kaj Aaron etendis sian manon super la akvojn de Egiptujo, kaj la ranoj eliris kaj kovris la landon Egiptan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Tion saman faris la sorĉistoj per siaj sorĉoj, kaj ili elirigis la ranojn sur la landon Egiptan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Tiam Faraono alvokis Moseon kaj Aaronon, kaj diris: Preĝu al la Eternulo, ke Li forigu la ranojn for de mi kaj de mia popolo; tiam mi forliberigos la popolon, ke ĝi alportu oferon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Kaj Moseo diris al Faraono: Ordonu al mi, por kiu tempo mi devas preĝi pro vi kaj pro viaj servantoj kaj pro via popolo, ke malaperu la ranoj for de vi kaj el viaj domoj kaj nur en la rivero ili restu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Tiu diris: Por morgaŭ. Kaj li diris: Ĝi estu, kiel vi diris, por ke vi sciu, ke ekzistas neniu tia, kiel la Eternulo, nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Kaj foriĝos la ranoj for de vi kaj de viaj domoj kaj de viaj servantoj kaj de via popolo; nur en la rivero ili restos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Moseo kaj Aaron eliris for de Faraono, kaj Moseo ekvokis al la Eternulo pri la ranoj, kiujn li venigis sur Faraonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Kaj la Eternulo faris laŭ la vortoj de Moseo; kaj mortis la ranoj en la domoj, en la kortoj, kaj sur la kampoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Kaj oni kunŝovelis ilin en multajn amasojn, kaj la lando malbonodoriĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Sed kiam Faraono vidis, ke fariĝis faciliĝo, li malmoligis sian koron kaj ne aŭskultis ilin, kiel diris la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Tiam la Eternulo diris al Moseo: Diru al Aaron: Etendu vian bastonon, kaj frapu la polvon de la tero, kaj el ĝi fariĝos pikmuŝoj en la tuta lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Ili faris tiel: Aaron etendis sian manon kun sia bastono kaj frapis la polvon de la tero, kaj aperis pikmuŝoj sur la homoj kaj la brutoj. La tuta polvo de la tero fariĝis pikmuŝoj en la tuta lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Tiel faris la sorĉistoj per siaj sorĉoj, por elirigi pikmuŝojn, sed ili ne povis. Kaj la pikmuŝoj estis sur la homoj kaj sur la brutoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Tiam la sorĉistoj diris al Faraono: Ĝi estas fingro de Dio. Sed la koro de Faraono restis obstina, kaj li ne aŭskultis ilin, kiel diris la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Kaj la Eternulo diris al Moseo: Leviĝu frue matene, kaj stariĝu antaŭ Faraono, kiam li iros al la akvo, kaj diru al li: Tiel diris la Eternulo: Forliberigu Mian popolon, ke ĝi faru servon al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Ĉar se vi ne forliberigos Mian popolon, jen Mi venigos sur vin kaj sur viajn servantojn kaj sur vian popolon kaj en viajn domojn fiinsektojn; kaj pleniĝos de la fiinsektoj la domoj de la Egiptoj, kaj ankaŭ la tero, sur kiu ili estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Kaj Mi distingos en tiu tago la teron de Goŝen, sur kiu troviĝas Mia popolo, ke tie ne estu fiinsektoj; por ke vi sciiĝu, ke Mi estas la Eternulo meze de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Kaj Mi faros apartigon inter Mia popolo kaj via popolo; morgaŭ okazos tiu signo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Kaj la Eternulo faris tiel, kaj aperis multego da fiinsektoj en la domo de Faraono kaj en la domoj de liaj servantoj kaj en la tuta lando Egipta; difektiĝis la tero kaŭze de la fiinsektoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Tiam Faraono alvokis Moseon kaj Aaronon, kaj diris: Iru, alportu oferon al via Dio en la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Sed Moseo diris: Ne estas oportune fari tiel; ĉar abomenindaĵo por la Egiptoj estus nia oferado al la Eternulo, nia Dio; se oferadon abomenindan por la Egiptoj ni faros antaŭ iliaj okuloj, ĉu ili tiam nin ne ŝtonmortigos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Vojon de tri tagoj ni iros en la dezerton, kaj ni faros oferon al la Eternulo, nia Dio, kiel Li diros al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Tiam Faraono diris: Mi forliberigos vin, kaj vi faros oferon al la Eternulo, via Dio, en la dezerto; nur ne foriru malproksime; preĝu pro mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Kaj Moseo diris: Jen mi foriras de vi, kaj mi preĝos al la Eternulo, ke foriĝu la fiinsektoj for de Faraono, de liaj servantoj, kaj de lia popolo morgaŭ; sed Faraono ne plu trompu, ne forliberigante la popolon, por fari oferon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Moseo eliris for de Faraono kaj preĝis al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Kaj la Eternulo faris, kiel diris Moseo, kaj forigis la fiinsektojn for de Faraono, de liaj servantoj, kaj de lia popolo; ne restis eĉ unu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Sed Faraono obstinigis sian koron ankaŭ ĉi tiun fojon, kaj ne forliberigis la popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Kaj la Eternulo diris al Moseo: Iru al Faraono, kaj diru al li: Tiel diris la Eternulo, Dio de la Hebreoj: Forliberigu Mian popolon, ke ĝi faru al Mi servon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Ĉar se vi ne volos forliberigi kaj vi plue ilin retenos,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'jen la mano de la Eternulo estos sur viaj brutoj, kiuj estas sur la kampo, sur la ĉevaloj, sur la azenoj, sur la kameloj, sur la bovoj, kaj sur la ŝafoj; estos sur ili tre forta pesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Kaj la Eternulo faros apartigon inter la brutoj de la Izraelidoj kaj la brutoj de la Egiptoj; kaj el ĉio, kio apartenas al la Izraelidoj, mortos nenio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Kaj la Eternulo difinis tempon, dirante: Morgaŭ la Eternulo faros tiun aferon en la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Kaj la Eternulo faris tion en la sekvanta tago, kaj mortis ĉiuj brutoj de la Egiptoj, sed el la brutoj de la Izraelidoj ne mortis eĉ unu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Faraono sendis, kaj oni vidis, ke el la brutoj de la Izraelidoj ne mortis eĉ unu. Sed la koro de Faraono estis obstina, kaj li ne forliberigis la popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Tiam la Eternulo diris al Moseo kaj al Aaron: Prenu al vi plenmanojn da cindro el la forno, kaj Moseo ĵetu ĝin al la ĉielo antaŭ la okuloj de Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Kaj ĝi fariĝos polvo super la tuta lando Egipta, kaj sur la homoj kaj sur la bestoj fariĝos el ĝi brulumaj abscesoj en la tuta lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Kaj ili prenis cindron el la forno kaj stariĝis antaŭ Faraono, kaj Moseo ĵetis ĝin al la ĉielo, kaj aperis brulumaj abscesoj sur la homoj kaj sur la bestoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Kaj la sorĉistoj ne povis teni sin antaŭ Moseo pro la abscesoj, ĉar la abscesoj estis sur la sorĉistoj kaj sur ĉiuj Egiptoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Sed la Eternulo obstinigis la koron de Faraono, kaj li ne aŭskultis ilin, kiel diris la Eternulo al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Tiam la Eternulo diris al Moseo: Leviĝu frue matene kaj stariĝu antaŭ Faraono, kaj diru al li: Tiel diris la Eternulo, Dio de la Hebreoj: Forliberigu Mian popolon, ke ĝi faru al Mi servon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Ĉar ĉi tiun fojon Mi sendos ĉiujn Miajn frapojn en vian koron kaj sur viajn servantojn kaj sur vian popolon, por ke vi sciu, ke ne ekzistas simila al Mi sur la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Ĉar nun Mi etendus Mian manon kaj batus vin kaj vian popolon per pesto, kaj vi malaperus de la tero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'sed nur por tio Mi vin konservis, ke Mi montru sur vi Mian forton, kaj por ke oni rakontu pri Mia nomo sur la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Ankoraŭ vi retenas Mian popolon, kaj ne forliberigas ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Jen morgaŭ en ĉi tiu tempo Mi pluvigos tre grandan hajlon, tian, ke simila al ĝi ne estis en Egiptujo de post la tago de ĝia fondiĝo ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Kaj nun sendu, kolektu viajn brutojn, kaj ĉion, kion vi havas sur la kampo; sur ĉiun homon kaj bruton, kiuj troviĝos sur la kampo kaj ne kolektiĝos en la domon, falos la hajlo, kaj ili mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Kiu el la servantoj de Faraono timis la vorton de la Eternulo, tiu rapide envenigis siajn sklavojn kaj brutojn en la domojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'sed kiu ne atentis la vorton de la Eternulo, tiu lasis siajn sklavojn kaj siajn brutojn sur la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Kaj la Eternulo diris al Moseo: Etendu vian manon al la ĉielo, kaj venos hajlo en la tuta lando Egipta, sur la homojn kaj sur la brutojn kaj sur ĉiujn herbojn de la kampo en la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Kaj Moseo etendis sian bastonon al la ĉielo; kaj la Eternulo aperigis tondrojn kaj hajlon, kaj fajro iris sur la teron, kaj la Eternulo pluvigis hajlon sur la landon Egiptan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Kaj estis hajlo, kaj fajro ekflamadis meze de la hajlo, en tiel forta grado, ke io simila neniam estis en la tuta lando Egipta de post la tempo, kiam en ĝi aperis popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Kaj la hajlo batdifektis en la tuta lando Egipta ĉion, kio estis sur la kampo; homojn kaj brutojn kaj ĉiun herbon de la kampo batdifektis la hajlo, kaj ĉiujn arbojn de la kampo ĝi rompis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Nur en la lando Goŝen, kie estis la Izraelidoj, ne estis hajlo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Tiam Faraono sendis, kaj alvokis Moseon kaj Aaronon, kaj diris al ili: Mi pekis la nunan fojon; la Eternulo estas la pravulo, mi kaj mia popolo estas la malpravuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Preĝu al la Eternulo, ke ĉesiĝu la tondroj de Dio kaj la hajlo; tiam mi forliberigos vin, kaj vi ne plu restos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Kaj Moseo diris al li: Kiam mi eliros el la urbo, mi etendos miajn manojn al la Eternulo; la tondroj ĉesiĝos kaj la hajlo ne plu estos, por ke vi sciiĝu, ke al la Eternulo apartenas la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Sed mi scias, ke vi kaj viaj servantoj ankoraŭ ne timas Dion, la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'La lino kaj la hordeo estis batdifektitaj, ĉar la hordeo havis spikojn kaj la lino havis burĝonojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'sed la tritiko kaj la spelto ne estis batdifektitaj, ĉar ili estis malfrusezonaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Moseo eliris de Faraono el la urbo kaj etendis siajn manojn al la Eternulo; tiam ĉesiĝis la tondroj kaj la hajlo, kaj pluvo ne plu verŝiĝis sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Kiam Faraono vidis, ke ĉesiĝis la pluvo kaj la hajlo kaj la tondroj, tiam li plue pekis kaj obstinigis sian koron, li kaj liaj servantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'La koro de Faraono restis obstina, kaj li ne forliberigis la Izraelidojn, kiel diris la Eternulo per Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Kaj la Eternulo diris al Moseo: Iru al Faraono, ĉar Mi obstinigis lian koron kaj la korojn de liaj servantoj, por ke Mi faru ĉi tiujn Miajn signojn inter ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'kaj por ke vi rakontu al via filo kaj al via nepo, kion Mi plenumis sur la Egiptoj, kaj pri Miaj signoj, kiujn Mi faris inter ili; kaj por ke vi sciu, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Moseo kaj Aaron venis al Faraono, kaj diris al li: Tiel diris la Eternulo, Dio de la Hebreoj: Ĝis kiam vi rifuzos humiliĝi antaŭ Mi? forliberigu Mian popolon, ke ĝi faru al Mi servon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Ĉar se vi rifuzos forliberigi Mian popolon, jen Mi venigos morgaŭ akridojn en vian regionon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'kaj ili kovros la supraĵon de la tero tiel, ke oni ne povos vidi la teron; kaj ili formanĝos ĉion, kio restis ĉe vi savita kontraŭ la hajlo, kaj ili ĉirkaŭmanĝos ĉiujn arbojn, kiuj kreskas ĉe vi sur la kampo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'kaj ili plenigos viajn domojn kaj la domojn de ĉiuj viaj servantoj kaj la domojn de ĉiuj Egiptoj tiel, kiel ne vidis viaj patroj kaj viaj prapatroj de post la tago, kiam ili aperis sur la tero ĝis la nuna tago. Kaj li turniĝis kaj eliris for de Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Tiam la servantoj de Faraono diris al li: Ĝis kiam tiu homo estos por ni suferilo? forliberigu tiujn homojn, por ke ili faru servon al la Eternulo, ilia Dio; ĉu vi ankoraŭ ne vidas, ke Egiptujo pereas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Kaj oni revenigis denove Moseon kaj Aaronon al Faraono, kaj ĉi tiu diris al ili: Iru, faru servon al la Eternulo, via Dio; sed kiuj estas la irontoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Tiam Moseo diris: Kun niaj junuloj kaj maljunuloj ni iros, kun niaj filoj kaj niaj filinoj, kun niaj ŝafoj kaj niaj bovoj ni iros, ĉar ni havas feston de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Kaj li diris al ili: Tiel la Eternulo estu kun vi, se mi forliberigos vin kaj viajn infanojn! ĉu vi ne havas ian malbonan intencon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Ne; iru nur la viroj kaj faru servon al la Eternulo, ĉar tion vi petas. Kaj oni elpelis ilin for de Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Tiam la Eternulo diris al Moseo: Etendu vian manon super la landon Egiptan pro la akridoj, ke ili venu sur la landon Egiptan, kaj formanĝu ĉiujn herbojn de la tero, ĉion, kion restigis la hajlo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Kaj Moseo etendis sian bastonon super la landon Egiptan, kaj la Eternulo direktis orientan venton sur la landon dum tiu tuta tago kaj dum la tuta nokto. Kiam fariĝis mateno, la orienta vento alportis la akridojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Kaj la akridoj venis sur la tutan landon Egiptan kaj sidiĝis en la tuta Egipta regiono en tre granda amaso; antaŭ ili neniam estis akridaro simila al ili, kaj poste neniam estos tia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Kaj ili kovris la tutan supraĵon de la tero, kaj la tero fariĝis malluma; kaj ili formanĝis la tutan herbon de la kampo, kaj ĉiujn arbajn fruktojn, kiujn restigis la hajlo; kaj restis nenia verdaĵo sur la arboj aŭ inter la herboj de la kampo en la tuta lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Tiam Faraono rapide alvokis Moseon kaj Aaronon, kaj diris: Mi pekis antaŭ la Eternulo, via Dio, kaj antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Sed nun pardonu mian pekon nur ĉi tiun fojon, kaj preĝu al la Eternulo, via Dio, ke Li forigu de mi nur ĉi tiun morton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Kaj li eliris for de Faraono kaj preĝis al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Kaj la Eternulo venigis de la kontraŭa flanko venton okcidentan tre fortan, kaj ĝi levis la akridojn kaj ĵetis ilin en la Ruĝan Maron; ne restis eĉ unu akrido en la tuta Egipta regiono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Sed la Eternulo obstinigis la koron de Faraono, kaj li ne forliberigis la Izraelidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Tiam la Eternulo diris al Moseo: Etendu vian manon al la ĉielo, kaj fariĝos mallumo en la lando Egipta, palpebla mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Kaj Moseo etendis sian manon al la ĉielo, kaj fariĝis densa mallumo en la tuta lando Egipta dum tri tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Oni ne vidis unu alian, kaj neniu leviĝis de sia loko dum tri tagoj; sed ĉiuj Izraelidoj havis lumon en siaj loĝejoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Tiam Faraono alvokis Moseon, kaj diris: Iru, faru servon al la Eternulo; nur viaj ŝafoj kaj viaj bovoj restu; ankaŭ viaj infanoj iru kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Sed Moseo diris: Vi devas ankaŭ doni en niajn manojn oferojn kaj bruloferojn, kiujn ni alportos al la Eternulo, nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Ankaŭ niaj brutoj iros kun ni, ne restos eĉ unu hufo; ĉar el ili ni prenos, por fari servon al la Eternulo, nia Dio; kaj ni ne scias, per kio ni devas servi al la Eternulo, ĝis ni venos tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Kaj la Eternulo obstinigis la koron de Faraono, kaj li ne volis forliberigi ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Kaj Faraono diris al li: Iru for de mi! gardu vin, ke vi ne venu plu antaŭ mian vizaĝon; ĉar en la tago, en kiu vi venos antaŭ mian vizaĝon, vi mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Tiam Moseo diris: Tiel vi diris; mi ne venos do plu antaŭ vian vizaĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Kaj la Eternulo diris al Moseo: Ankoraŭ unu punon Mi venigos sur Faraonon kaj sur Egiptujon; post tio li forliberigos vin el ĉi tie; kaj forliberigante, li tute elpelos vin el ĉi tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Diru nun al la popolo, ke ili petu ĉiu viro de sia proksimulo kaj ĉiu virino de sia proksimulino vazojn arĝentajn kaj vazojn orajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Kaj la Eternulo donis al la popolo favoron ĉe la Egiptoj; kaj ankaŭ Moseo estis tre granda homo en la lando Egipta, en la okuloj de la servantoj de Faraono kaj en la okuloj de la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Kaj Moseo diris: Tiel diris la Eternulo: En la mezo de la nokto Mi iros internen de Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'Kaj mortos ĉiu unuenaskito en la lando Egipta, de la unuenaskito de Faraono, kiu sidas sur sia trono, ĝis la unuenaskito de la sklavino, kiu sidas malantaŭ la muelejo; kaj ĉiu unuenaskito el la brutoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Kaj estos granda kriado en la tuta lando Egipta, tia, ke simila al ĝi neniam estis kaj neniam plu estos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Sed ĉe ĉiuj Izraelidoj ne movos hundo sian langon, nek kontraŭ homon, nek kontraŭ bruton; por ke vi sciu, kiel la Eternulo faras apartigon inter la Egiptoj kaj la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Kaj venos ĉiuj viaj sklavoj al mi kaj terĵetiĝos antaŭ mi, dirante: Eliru vi kaj la tuta popolo, kiu vin sekvas. Post tio mi eliros. Kaj li eliris for de Faraono kun granda kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Kaj la Eternulo diris al Moseo: Faraono vin ne aŭskultos; por ke multiĝu Miaj mirakloj en la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Kaj Moseo kaj Aaron faris ĉiujn tiujn miraklojn antaŭ Faraono; sed la Eternulo obstinigis la koron de Faraono, kaj li ne forliberigis la Izraelidojn el sia lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Kaj la Eternulo ekparolis al Moseo kaj al Aaron en la lando Egipta, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Ĉi tiu monato estu por vi komenco de la monatoj; la unua ĝi estu por vi inter la monatoj de la jaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Diru al la tuta komunumo de Izrael: En la deka tago de ĉi tiu monato prenu al si ŝafidon ĉiu patro de familio, po unu ŝafido por domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Kaj se en la domo estas tro malmulte da personoj por tuta ŝafido, tiam li prenu kune kun sia najbaro plej proksima al lia domo; laŭ la nombro de la animoj, laŭ la kvanto de manĝado de ĉiu, ili kalkulu sin por la ŝafido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'La ŝafido estu sendifekta, virseksa, havanta la aĝon de unu jaro; el la ŝafoj aŭ el la kaproj vi povas preni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Konservu ĝin ĝis la dek-kvara tago de ĉi tiu monato; kaj la tuta komunumo de Izrael buĉu ĝin en la komenco de vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Kaj ili prenu iom el la sango, kaj ŝmiru sur ambaŭ fostoj kaj sur la supra sojlo de la domoj, en kiuj ili ĝin manĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Kaj ili manĝu la viandon en tiu nokto, rostitan sur fajro; kaj macojn kun maldolĉaj herboj ili manĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Ne manĝu ĝin duonkrudan, nek kuiritan en akvo, sed nur rostitan sur fajro kun ĝiaj kapo, kruroj, kaj internaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Ne restigu iom el ĝi ĝis la mateno; kio restos el ĝi ĝis la mateno, tion bruligu per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Kaj tiele manĝu ĝin; via lumbo estu zonita, viaj ŝuoj sur viaj piedoj, kaj via bastono en via mano; kaj manĝu ĝin rapidante; ĝi estas Pasko de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Kaj Mi trairos la landon Egiptan en tiu nokto, kaj Mi batos ĉiun unuenaskiton en la lando Egipta, de la homoj ĝis la brutoj; kaj super ĉiuj dioj de Egiptujo Mi faros juĝon, Mi, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Kaj la sango ĉe vi estos signo sur la domoj, en kiuj vi troviĝas; kiam Mi vidos la sangon, Mi pasos preter vi, kaj ne estos inter vi la eksterma puno, kiam Mi batos la landon Egiptan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Kaj tiu tago estu por vi memoraĵo; kaj festu ĝin kiel feston de la Eternulo en viaj generacioj, kiel leĝon por eterne festu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Dum sep tagoj manĝu macojn; en la unua tago forigu la fermentaĵon el viaj domoj; ĉiu kiu manĝos fermentaĵon de la unua tago ĝis la sepa tago, ties animo estos ekstermita el Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Kaj en la unua tago faru al vi sanktan kunvenon, kaj en la sepa tago faru al vi sanktan kunvenon; nenia laboro estu farata en tiuj tagoj; nur kio estas necesa por manĝi por ĉiu, nur tio sola povas esti farata de vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Kaj observu la ordonon pri la macoj, ĉar ĝuste en tiu tago Mi elkondukis viajn taĉmentojn el la lando Egipta; kaj observu tiun tagon en viaj generacioj kiel leĝon eternan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'De post la vespero de la dek-kvara tago de la unua monato manĝu macojn ĝis la vespero de la dudek-unua tago de la monato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Dum sep tagoj fermentaĵo ne troviĝu en viaj domoj; ĉar kiu manĝos fermentaĵon, ties animo ekstermiĝos el la komunumo de Izrael, ĉu li estas fremdulo, aŭ ĉu li estas indiĝeno de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Nenion fermentintan manĝu; en ĉiuj viaj loĝlokoj manĝu macojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Moseo alvokis ĉiujn ĉefojn de Izrael, kaj diris al ili: Elektu kaj prenu al vi ŝafidojn laŭ viaj familioj, kaj buĉu la Paskon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Kaj prenu faskon da hisopo, kaj trempu ĝin en la sango, kiu estos en la pelvo, kaj tuŝu la supran sojlon kaj ambaŭ fostojn per la sango, kiu estos en la pelvo; kaj neniu el vi eliru el la pordo de sia domo ĝis la mateno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Kaj la Eternulo trairos, por puni la Egiptojn; kiam Li vidos la sangon sur la supra sojlo kaj ambaŭ fostoj, tiam la Eternulo preterpasos la pordon kaj ne permesos al la ekstermanto veni en viajn domojn por puni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Kaj observu ĉi tion kiel leĝon por vi kaj por viaj filoj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Kaj kiam vi venos en la landon, kiun la Eternulo donos al vi, kiel Li diris, observu ĉi tiun servon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Kaj kiam diros al vi viaj filoj: Kion signifas ĉi tiu via servo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'tiam diru: Ĝi estas ofero de Pasko al la Eternulo, kiu preterpasis la domojn de la Izraelidoj en Egiptujo, kiam Li punis la Egiptojn, sed niajn domojn savis. Kaj la popolo kliniĝis kaj faris adoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Kaj la Izraelidoj iris, kaj faris, kiel ordonis la Eternulo al Moseo kaj Aaron; tiel ili faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Kiam venis la noktomezo, la Eternulo batis ĉiujn unuenaskitojn en la lando Egipta, de la unuenaskito de Faraono, sidanta sur sia trono, ĝis la unuenaskito de malliberulo, sidanta en malliberejo; kaj ĉiujn unuenaskitojn el la brutoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Tiam Faraono leviĝis en la nokto, li kaj ĉiuj liaj servantoj kaj ĉiuj Egiptoj; kaj fariĝis granda kriado en Egiptujo; ĉar ne estis domo, en kiu ne estis mortinto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Kaj li alvokis Moseon kaj Aaronon en la nokto, kaj diris: Leviĝu, foriru el inter mia popolo, vi kaj la Izraelidoj; kaj iru, faru servon al la Eternulo, kiel vi diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Ankaŭ viajn ŝafojn kaj viajn bovojn prenu, kiel vi diris, kaj iru; kaj benu ankaŭ min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Kaj la Egiptoj urĝis sur la popolon, por pli rapide elirigi ilin el la lando; ĉar ili diris: Ni ĉiuj mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Kaj la popolo forportis sian paston, antaŭ ol ĝi fermentis; iliaj pastujoj, ligitaj en iliaj vestoj, estis sur iliaj ŝultroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Kaj la Izraelidoj faris, kiel diris Moseo; kaj ili petis de la Egiptoj vazojn arĝentajn kaj vazojn orajn kaj vestojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Kaj la Eternulo favorigis al la popolo la Egiptojn, kaj ĉi tiuj pruntedonis al ili; kaj ili multe prenis de la Egiptoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Kaj la Izraelidoj ekiris el Rameses al Sukot, en la nombro de ĉirkaŭ sescent mil piedirantaj viroj, krom la infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Kaj ankaŭ granda amaso da diversgentaj homoj eliris kun ili, kaj da ŝafoj kaj bovoj tre granda brutaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Kaj el la pasto, kiun ili elportis el Egiptujo, ili bakis macajn platpanojn, ĉar ĝi ankoraŭ ne fermentis; ĉar ili estis elpelitaj el Egiptujo kaj ne povis prokrasti, kaj ili eĉ ne pretigis al si manĝaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'La daŭro de la tempo, kiun la Izraelidoj loĝis en Egiptujo, estis kvarcent tridek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Kiam finiĝis kvarcent tridek jaroj, ĝuste en la sama tago, ĉiuj taĉmentoj de la Eternulo eliris el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Ĝi estas nokto dediĉata al la Eternulo, ĉar Li elkondukis ilin el la lando Egipta; ĝi estas tiu nokto, kiu estas dediĉata al la Eternulo de ĉiuj Izraelidoj en iliaj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Kaj la Eternulo diris al Moseo kaj Aaron: Ĉi tio estas la leĝo pri la Pasko: neniu fremdulo manĝu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Sed ĉiu sklavo, kiun iu aĉetis per mono, se vi cirkumcidis lin, tiam li povas manĝi ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Pasloĝanto kaj dungito ne manĝu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'En unu domo ĝi estu manĝata; ne elportu el la domo iom el la viando eksteren, kaj oston en ĝi ne rompu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'La tuta komunumo de Izrael faru ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Kaj se enloĝiĝos ĉe vi aligentulo kaj li volos fari Paskon al la Eternulo, tiam cirkumcidu ĉe li ĉiujn virseksulojn, kaj tiam li povas prepari sin, por fari ĝin, kaj li estos kiel indiĝeno de la lando; sed neniu ne cirkumcidita manĝu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'La sama leĝo estu por la indiĝeno, kaj por la aligentulo, kiu enloĝiĝis inter vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Kaj ĉiuj Izraelidoj faris, kiel ordonis la Eternulo al Moseo kaj al Aaron; tiel ili faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'En tiu sama tago la Eternulo elkondukis la Izraelidojn el la lando Egipta laŭ iliaj taĉmentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Dediĉu al Mi ĉiun unuenaskiton, kiu malfermas ĉiun uteron inter la Izraelidoj, el la homo kaj el la brutoj: al Mi li apartenas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Kaj Moseo diris al la popolo: Memoru ĉi tiun tagon, en kiu vi eliris el Egiptujo, el la domo de sklaveco; ĉar per forta mano la Eternulo elkondukis vin el tie; kaj ne manĝu fermentaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Hodiaŭ vi eliras, en la monato Abib.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Kaj kiam la Eternulo venigos vin en la landon de la Kanaanidoj kaj la Ĥetidoj kaj la Amoridoj kaj la Ĥividoj kaj la Jebusidoj, pri kiu Li ĵuris al viaj patroj, ke Li donos al vi, en la landon, en kiu fluas lakto kaj mielo, tiam servu ĉi tiun servon en ĉi tiu monato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Dum sep tagoj manĝu macojn, kaj en la sepa tago estu festo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Macoj estu manĝataj dum la sep tagoj, kaj ne vidiĝu ĉe vi fermentaĵo kaj ne vidiĝu ĉe vi fermentinta pasto, en la tuta regiono, kiu apartenas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Kaj sciigu al via filo en tiu tago, dirante: Ĝi estas pro tio, kion la Eternulo faris al mi ĉe mia elirado el Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Kaj tio estu ĉe vi kiel signo sur via mano kaj kiel memorigaĵo inter viaj okuloj, por ke la instruo de la Eternulo estu en via buŝo; ĉar per forta mano la Eternulo elkondukis vin el Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Plenumu ĉi tiun leĝon en ĝia tempo en ĉiu jaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Kaj kiam la Eternulo venigos vin en la landon de la Kanaanidoj, kiel Li ĵuris al vi kaj al viaj patroj, kaj donos ĝin al vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'tiam transdonadu ĉiun utermalferminton al la Eternulo, kaj ĉiun unuenaskiton el la brutoj, virseksulon, al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Kaj ĉiun unuenaskiton el la azenoj elaĉetu per ŝafido; kaj se vi ne elaĉetos, tiam rompu al ĝi la kolon; kaj ĉiun homan unuenaskiton inter viaj filoj elaĉetu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Kaj kiam via filo morgaŭ vin demandos, dirante: Kio tio estas? tiam diru al li: Per forta mano la Eternulo elkondukis nin el Egiptujo, el la domo de sklaveco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'kaj kiam Faraono obstine rifuzis forliberigi nin, tiam la Eternulo mortigis ĉiun unuenaskiton en la lando Egipta, de la unuenaskito de homo ĝis la unuenaskito de bruto; tial mi oferas al la Eternulo ĉiun utermalfermintan virseksulon, kaj ĉiun unuenaskiton el miaj filoj mi elaĉetas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Kaj tio estu kiel signo sur via mano kaj kiel memorigaĵo inter viaj okuloj; ĉar per forta mano la Eternulo elkondukis nin el Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Kiam Faraono forliberigis la popolon, Dio ne irigis ilin per la vojo de la lando Filiŝta, kiu estis proksima; ĉar Dio diris: Eble la popolo pentos, kiam ĝi ekvidos militon, kaj ĝi reiros Egiptujon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Kaj Dio kondukis la popolon ĉirkaŭire, per la vojo tra la dezerto, al la Ruĝa Maro. Kaj armitaj la Izraelidoj eliris el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Kaj Moseo prenis kun si la ostojn de Jozef, ĉar tiu ĵurigis la Izraelidojn, dirante: Kiam Dio rememoros vin, tiam elportu miajn ostojn el ĉi tie kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Kaj ili elmoviĝis el Sukot, kaj starigis sian tendaron en Etam, en la fino de la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Kaj la Eternulo iradis antaŭ ili dum la tago en nuba kolono, por konduki ilin laŭ la ĝusta vojo, kaj dum la nokto en kolono fajra, por lumi al ili, ke ili povu iri tage kaj nokte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Ne foriĝadis de antaŭ la popolo la nuba kolono dum la tago nek la fajra kolono dum la nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Diru al la Izraelidoj, ke ili iru returne, kaj starigu sian tendaron antaŭ Pi-Haĥirot, inter Migdol kaj la maro, apud Baal-Cefon; tie ili stariĝu tendare super la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Faraono diros pri la Izraelidoj: Ili perdis la vojon en la lando, la dezerto ilin ŝlosis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Kaj Mi obstinigos la koron de Faraono, kaj li kuros post ili; kaj Mi gloriĝos per Faraono kaj per lia tuta militistaro, kaj la Egiptoj sciiĝos, ke Mi estas la Eternulo. Kaj ili faris tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Kiam oni diris al la reĝo de Egiptujo, ke la popolo forkuris, tiam la koro de Faraono kaj de liaj servantoj turniĝis kontraŭ la popolon, kaj ili diris: Kion ni faris, forliberiginte la Izraelidojn de servado al ni?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Kaj li jungis sian ĉaron kaj prenis kun si sian popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Kaj li prenis sescent plej bonajn ĉarojn kaj ĉiujn ĉarojn de Egiptujo kaj la ĉefojn de la tuta militistaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Kaj la Eternulo obstinigis la koron de Faraono, la reĝo de Egiptujo, kaj li postkuris la Izraelidojn; sed la Izraelidojn elirigis mano alta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'La Egiptoj postkuris ilin, kaj ĉiuj ĉevaloj kaj ĉaroj de Faraono kaj liaj rajdantoj kaj lia militistaro atingis ilin, kiam ili staris tendare super la maro, apud Pi-Haĥirot antaŭ Baal-Cefon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Kiam Faraono alproksimiĝis, tiam la Izraelidoj levis siajn okulojn, kaj ekvidis, ke jen la Egiptoj iras post ili; kaj ili tre ektimis, kaj la Izraelidoj ekkriis al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Kaj ili diris al Moseo: Ĉu ne ekzistis tomboj en Egiptujo, ke vi prenis nin, por morti en la dezerto? kion vi faris al ni, elkondukinte nin el Egiptujo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Tion ni diris ja al vi en Egiptujo: Lasu nin, kaj ni servu la Egiptojn; ĉar pli bone estus por ni servi la Egiptojn, ol morti en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Tiam Moseo diris al la popolo: Ne timu; staru, kaj vidu la savon de la Eternulo, kiun Li faros al vi hodiaŭ; ĉar la Egiptojn, kiujn vi vidas hodiaŭ, vi eterne neniam plu vidos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'La Eternulo militos por vi, kaj vi silentu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Kaj la Eternulo diris al Moseo: Kion vi krias al Mi? diru al la Izraelidoj, ke ili ekiru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Kaj vi levu vian bastonon kaj etendu vian manon super la maron kaj disfendu ĝin, por ke la Izraelidoj iru tra la mezo de la maro sur seka tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Kaj jen, Mi obstinigos la korojn de la Egiptoj, kaj ili iros post vi; kaj Mi gloriĝos per Faraono kaj per lia tuta militistaro, per liaj ĉaroj kaj liaj rajdantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Kaj la Egiptoj sciiĝos, ke Mi estas la Eternulo, kiam Mi gloriĝos per Faraono, per liaj ĉaroj kaj liaj rajdantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Kaj la Dia anĝelo, kiu iradis antaŭ la tendaro de la Izraelidoj, formoviĝis kaj ekiris post ili; kaj la nuba kolono formoviĝis de antaŭ ili kaj stariĝis post ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'kaj ĝi aperis inter la tendaro de la Egiptoj kaj la tendaro de la Izraelidoj, kaj ĝi estis nubo malluma, kaj lumis dum la nokto tiamaniere, ke unuj al la aliaj ne povis alproksimiĝi dum la tuta nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Kaj Moseo etendis sian manon super la maron; kaj la Eternulo pelis la maron per forta orienta vento dum la tuta nokto kaj faris la maron seka tero; kaj la akvo disfendiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Kaj la Izraelidoj ekiris tra la mezo de la maro sur seka tero, kaj la akvo estis por ili muro dekstre kaj maldekstre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Kaj la Egiptoj postkuris kaj venis post ili, ĉiuj ĉevaloj de Faraono, liaj ĉaroj kaj liaj rajdantoj, en la mezon de la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Kiam venis la matena gardotempo, la Eternulo ekrigardis la tendaron de la Egiptoj el la fajra kaj nuba kolono, kaj Li tumultigis la tendaron de la Egiptoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Kaj Li depuŝis la radojn de iliaj ĉaroj kaj malrapidigis ilian iradon. Tiam la Egiptoj diris: Ni forkuru for de la Izraelidoj, ĉar la Eternulo militas por ili kontraŭ la Egiptoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Kaj la Eternulo diris al Moseo: Etendu vian manon super la maron, por ke la akvo revenu sur la Egiptojn, sur iliajn ĉarojn kaj iliajn rajdantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Kaj Moseo etendis sian manon super la maron, kaj la maro revenis en la komenco de la mateno, sur sian lokon, kaj la Egiptoj kuris renkonte al ĝi. Kaj la Eternulo ĵetis la Egiptojn en la mezon de la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Kaj la akvo revenis, kaj kovris la ĉarojn kaj la rajdantojn de la tuta militistaro de Faraono, kiu venis post ili en la maron; ne restis el ili eĉ unu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Sed la Izraelidoj iris sur seka tero tra la mezo de la maro, kaj la akvo estis por ili muro dekstre kaj maldekstre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Kaj la Eternulo savis en tiu tago la Izraelidojn el la mano de la Egiptoj; kaj la Izraelidoj vidis la Egiptojn mortintaj sur la bordo de la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Kaj la Izraelidoj vidis la grandan manon, kiun la Eternulo aperigis sur la Egiptoj, kaj la popolo ektimis la Eternulon kaj ekkredis al la Eternulo kaj al Lia sklavo Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Tiam Moseo kaj la Izraelidoj kantis ĉi tiun kanton al la Eternulo, kaj parolis jene: Mi kantos al la Eternulo, ĉar Li alte leviĝis; Ĉevalon kaj ĝian rajdanton Li ĵetis en la maron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Mia forto kaj glorkanto estas la Eternulo, Kaj Li estis por mi savo. Li estas mia Dio, kaj mi Lin gloros, La Dio de mia patro, kaj mi Lin altigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'La Eternulo estas viro de milito, Eternulo estas Lia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'La ĉarojn de Faraono kaj lian militistaron Li ĵetis en la maron; Kaj liaj elektitaj militestroj dronis en la Ruĝa Maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Abismoj ilin kovris; Ili falis en la profundojn kiel ŝtono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Via dekstra mano, ho Eternulo, estas glora per forto, Via dekstra mano, ho Eternulo, disbatas malamikon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Per Via granda majesto Vi frakasas Viajn kontraŭulojn; Vi sendas Vian koleron, kaj ĝi forbruligas ilin kiel pajlon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'De Via kolera blovo montiĝis akvo, Amasigite stariĝis fluaĵo, Densiĝis abismoj en la mezo de la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'La malamiko diris: Mi persekutos, Mi atingos, mi dividos militakiron; Satiĝos de ili mia animo; Mi eltiros mian glavon, ekstermos ilin mia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Vi blovis per Via spirito, kaj ilin kovris la maro; Kiel plumbo ili iris al fundo en la akvo potenca.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Kiu estas kiel Vi inter la dioj, ho Eternulo? Kiu estas kiel Vi, majesta en sankteco, Timinda kaj laŭdinda, faranta miraklojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Vi etendis Vian dekstran manon, Kaj ilin englutis la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Vi kondukis kun Via favorkoreco tiun popolon, kiun Vi liberigis; Vi kondukis ĝin per Via forto al Via sankta loĝejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Aŭdis popoloj kaj ektremis; Teruro atakis la loĝantojn de Filiŝtujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Tiam ektimis la ĉefoj de Edom; La potenculojn de Moab atakis tremo; Perdis la kuraĝon ĉiuj loĝantoj de Kanaan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Falas sur ilin timo kaj teruro pro la grandeco de Via brako; Ili mutiĝas kiel ŝtono, ĝis pasas Via popolo, ho Eternulo, Ĝis pasas la popolo, kiun Vi akiris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Vi venigos ilin, kaj plantos ilin Sur la monto de Via heredo, Sur la loko, ho Eternulo, kiun Vi faris Via sidejo, En la sanktejo, ho Sinjoro, kiun pretigis Viaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'La Eternulo reĝos ĉiam kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Ĉar la ĉevaloj de Faraono kun liaj ĉaroj kaj rajdantoj eniĝis en la maron, kaj la Eternulo turnis sur ilin la akvon de la maro; sed la Izraelidoj iris sur seka tero tra la mezo de la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Mirjam, la profetino, fratino de Aaron, prenis tamburinon en sian manon, kaj ĉiuj virinoj eliris post ŝi kun tamburinoj kaj dancante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Kaj Mirjam antaŭkantis al ili: Kantu al la Eternulo, ĉar Li alte leviĝis; Ĉevalon kaj ĝian rajdanton Li ĵetis en la maron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Moseo ekkondukis la Izraelidojn for de la Ruĝa Maro, kaj ili eliris al la dezerto Ŝur; ili iris dum tri tagoj tra la dezerto kaj ne trovis akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Ili venis al Mara, sed ili ne povis trinki la akvon en Mara, ĉar ĝi estis maldolĉa; tial oni donis al la loko la nomon Mara.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Kaj la popolo ekmurmuris kontraŭ Moseo, dirante: Kiam ni trinkos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Tiam li kriis al la Eternulo, kaj la Eternulo montris al li arbon, kaj li ĵetis ĝin en la akvon, kaj la akvo fariĝis dolĉa. Tie Li donis al ili leĝon kaj juĝon, kaj tie Li ilin elprovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Kaj Li diris: Se vi aŭskultados la voĉon de la Eternulo, via Dio, kaj farados tion, kio plaĉas al Li, kaj vi atentados Liajn ordonojn kaj observados ĉiujn Liajn leĝojn, tiam Mi venigos sur vin neniun el tiuj malsanoj, kiujn Mi venigis sur la Egiptojn; ĉar Mi estas la Eternulo, via saniganto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Kaj ili venis al Elim; tie estis dek du fontoj de akvo, kaj sepdek daktilpalmoj. Kaj ili starigis tie sian tendaron ĉe la akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Ili elmoviĝis el Elim, kaj la tuta komunumo de la Izraelidoj venis en la dezerton Sin, kiu troviĝas inter Elim kaj Sinaj, en la dek-kvina tago de la dua monato, post sia eliro el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Kaj la tuta komunumo de la Izraelidoj ekmurmuris kontraŭ Moseo kaj Aaron en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Kaj la Izraelidoj diris al ili: Ho, ni dezirus morti per la mano de la Eternulo en la lando Egipta, sidante super la potoj kun viando, manĝante panon ĝissate! vi elkondukis nin en ĉi tiun dezerton, por mortigi ĉi tiun tutan komunumon per malsato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Tiam la Eternulo diris al Moseo: Jen Mi pluvigos por vi panon el la ĉielo; kaj la popolo eliru kaj kolektu ĉiutage tiom, kiom ĝi bezonas por la tago, por ke Mi esploru ĝin, ĉu ĝi sekvos Mian leĝon aŭ ne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Sed en la sesa tago ili preparu tion, kion ili devas enporti, kaj tiam estos duobla porcio kompare kun tio, kion ili kolektas ĉiutage.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Kaj Moseo kaj Aaron diris al ĉiuj Izraelidoj: Vespere vi sciiĝos, ke la Eternulo elkondukis vin el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'Kaj matene vi vidos la gloron de la Eternulo; ĉar Li aŭdis vian murmuradon kontraŭ la Eternulo. Sed kio estas ni, ke vi murmuras kontraŭ ni?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Kaj Moseo diris: La Eternulo donos al vi vespere viandon por manĝi kaj matene panon por satiĝi; ĉar la Eternulo aŭdis vian murmuradon, kiun vi murmuris kontraŭ Li. Sed ni, kio ni estas? ne kontraŭ ni estas via murmurado, sed kontraŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Kaj Moseo diris al Aaron: Diru al la tuta komunumo de la Izraelidoj: Alproksimiĝu antaŭ la Eternulon, ĉar Li aŭdis vian murmuradon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Kaj dum Aaron estis parolanta al la tuta komunumo de la Izraelidoj, ili turniĝis al la dezerto, kaj jen la gloro de la Eternulo aperis en nubo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Kaj la Eternulo parolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Mi aŭdis la murmuradon de la Izraelidoj; diru al ili jenon: En la komenco de la vespero vi manĝos viandon, kaj matene vi satiĝos per pano, kaj vi sciiĝos, ke Mi estas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Kiam venis la vespero, alflugis koturnoj kaj kovris la tendaron, kaj matene estis tavolo da roso ĉirkaŭ la tendaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Kiam la tavolo da roso forleviĝis, tiam montriĝis, ke sur la supraĵo de la dezerto kuŝas io delikata, senŝela, delikata kiel prujno sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Kiam la Izraelidoj ekvidis, ili diris unuj al la aliaj: Kio ĝi estas? ĉar ili ne sciis, kio ĝi estas. Kaj Moseo diris al ili: Ĝi estas la pano, kiun la Eternulo donis al vi por manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Jen estas tio, kion ordonis la Eternulo: Kolektu ĝin ĉiu en tia kvanto, kiom li bezonas por manĝi; prenu po unu omero por ĉiu kapo, laŭ la nombro de viaj animoj, kiujn ĉiu havas en sia tendo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Kaj tiel faris la Izraelidoj, kaj ili kolektis, unu pli, alia malpli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Kaj oni mezuris per omero; kaj kiu kolektis pli, ne havis superflue, kaj kiu kolektis malpli, ne havis mankon; ĉiu kolektis tiom, kiom li povis manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Kaj Moseo diris al ili: Neniu restigu iom el ĝi ĝis la mateno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Sed ili ne obeis Moseon, kaj kelkaj restigis iom el ĝi ĝis la mateno; kaj aperis en ĝi vermoj, kaj ĝi malbonodoriĝis; kaj Moseo ekkoleris ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Ili kolektadis ĝin ĉiumatene, ĉiu tiom, kiom li bezonis por manĝi; kaj kiam la suno fariĝis pli varma, tio fandiĝadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Kiam venis la sesa tago, ili kolektis duoble da pano, po du omeroj por ĉiu; kaj ĉiuj ĉefoj de la komunumo venis kaj diris tion al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Kaj li diris al ili: Jen estas, kion diris la Eternulo: ripozo de sankta sabato de la Eternulo estas morgaŭ; kion vi estas bakontaj, baku, kaj kion vi estas kuirontaj, kuiru; sed ĉion superfluan formetu, por ke ĝi estu konservata ĝis la mateno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Kaj ili formetis ĝin ĝis la mateno, kiel ordonis Moseo, kaj ĝi ne malbonodoriĝis, kaj vermoj ne aperis en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Kaj Moseo diris: Manĝu ĝin hodiaŭ, ĉar hodiaŭ estas sabato de la Eternulo; hodiaŭ vi ne trovos ĝin sur la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Dum ses tagoj kolektu ĝin, sed la sepa tago estas sabato, en tiu tago ĝi ne troviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'En la sepa tago eliris kelkaj el la popolo, por kolekti, sed ili ne trovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Kaj la Eternulo diris al Moseo: Ĝis kiam vi rifuzos observi Miajn ordonojn kaj Mian instruon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Rigardu, la Eternulo donis al vi la sabaton, tial Li donas al vi en la sesa tago panon por du tagoj; restu ĉiu hejme, neniu eliru for de sia loko en la sepa tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Kaj la popolo ripozis en la sepa tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Kaj la domo de Izrael donis al ĝi la nomon manao; ĝi estis kiel la semo de koriandro, blanka, kaj ĝia gusto estis kiel blankpaneto kun mielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Kaj Moseo diris: Jen estas tio, kion ordonis la Eternulo: Plenigu per ĝi omeron, ke ĝi estu konservata en viaj generacioj, por ke oni vidu la panon, kiun Mi manĝigis al vi en la dezerto, kiam Mi elkondukis vin el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Kaj Moseo diris al Aaron: Prenu unu vazon kaj enmetu tien plenan omeron da manao kaj starigu ĝin antaŭ la Eternulo, por ke ĝi estu konservata en viaj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Kiel la Eternulo ordonis al Moseo, Aaron starigis ĝin antaŭ la Atesto, por konserviĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Kaj la Izraelidoj manĝis la manaon dum kvardek jaroj, ĝis ili venis en landon loĝeblan; la manaon ili manĝis, ĝis ili venis al la limo de la lando Kanaana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Kaj omero estas dekono de efo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'La tuta komunumo de la Izraelidoj elmoviĝis el la dezerto Sin laŭ siaj tagvojoj, kiel ordonis la Eternulo; kaj ili starigis sian tendaron en Refidim, kaj la popolo ne havis akvon por trinki.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Kaj la popolo malpacis kontraŭ Moseo, kaj ili diris: Donu al ni akvon por trinki. Kaj Moseo diris al ili: Kial vi malpacas kontraŭ mi? kial vi provas la Eternulon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Sed la popolo tie suferis pro manko de akvo, kaj la popolo murmuris kontraŭ Moseo, kaj diris: Kial vi elkondukis nin el Egiptujo, por mortigi nin kaj niajn infanojn kaj niajn brutojn per soifo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Tiam Moseo kriis al la Eternulo, dirante: Kion mi faros kun ĉi tiu popolo? baldaŭ povas okazi, ke ili min ŝtonmortigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Kaj la Eternulo diris al Moseo: Preteriru antaŭ la popolo, kaj prenu kun vi kelkajn el la ĉefoj de Izrael, kaj vian bastonon, per kiu vi frapis la riveron, prenu en vian manon, kaj iru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Jen Mi staros antaŭ vi tie super roko sur Ĥoreb; kaj vi frapos la rokon, kaj eliros el ĝi akvo, kaj la popolo trinkos. Kaj Moseo faris tiel antaŭ la okuloj de la ĉefoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Kaj li donis al tiu loko la nomon Masa kaj Meriba, pro la malpaco de la Izraelidoj, kaj pro tio, ke ili provis la Eternulon, dirante: Ĉu la Eternulo estas inter ni, aŭ ne?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Venis la Amalekidoj, kaj ekmilitis kontraŭ la Izraelidoj en Refidim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Tiam Moseo diris al Josuo: Elektu al ni virojn, kaj eliru, batalu kontraŭ la Amalekidoj. Morgaŭ mi staros sur supro de monteto, kaj la Dian bastonon mi havos en mia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Kaj Josuo faris, kiel diris al li Moseo, kaj batalis kontraŭ la Amalekidoj; kaj Moseo, Aaron, kaj Ĥur supreniris sur la supron de la monteto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Kaj ĉiufoje, kiam Moseo levis sian manon, venkis Izrael; kaj kiam li mallevis sian manon, venkis Amalek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Sed la manoj de Moseo estis pezaj; tial ili prenis ŝtonon kaj metis ĝin sub lin, kaj li sidiĝis sur ĝi; kaj Aaron kaj Ĥur subtenis liajn manojn, unu de unu flanko, la dua de la dua flanko; kaj liaj manoj estis en ĝusta teniĝo ĝis la subiro de la suno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Kaj Josuo senfortigis Amalekon kaj lian popolon per la glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Kaj la Eternulo diris al Moseo: Skribu ĉi tion por memoro en libron kaj enmetu ĉi tion en la orelojn de Josuo, ke Mi ekstermos la memoron pri Amalek sub la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Moseo konstruis altaron, kaj donis al ĝi la nomon: La Eternulo mia Standardo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Ĉar li diris: Estas promesite per la altaro de la Eternulo, ke la Eternulo militos kontraŭ Amalek de generacio al generacio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Jitro, la Midjana pastro, la bopatro de Moseo, aŭdis ĉion, kion la Eternulo faris al Moseo kaj al Sia popolo Izrael, ke la Eternulo elkondukis Izraelon el Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Kaj Jitro, la bopatro de Moseo, prenis Ciporan, la edzinon de Moseo, kiun tiu forlasis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'kaj ŝiajn du filojn, el kiuj unu havis la nomon Gerŝom; ĉar la patro diris: Mi estis fremdulo en fremda lando;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'kaj la dua havis la nomon Eliezer, ĉar tiu diris: La Dio de mia patro helpis min, kaj savis min kontraŭ la glavo de Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Kaj Jitro, la bopatro de Moseo, kun liaj filoj kaj lia edzino venis al Moseo en la dezerton, kie li staris tendare ĉe la monto de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Kaj li dirigis al Moseo: Mi, via bopatro Jitro, venas al vi, kaj ankaŭ via edzino kaj ŝiaj du filoj kun ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Tiam Moseo eliris renkonte al sia bopatro kaj profunde salutis lin kaj kisis lin, kaj ili demandis sin reciproke pri la farto kaj eniris en la tendon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Kaj Moseo rakontis al sia bopatro ĉion, kion la Eternulo faris al Faraono kaj al la Egiptoj pro Izrael, kaj ĉiujn malfacilaĵojn, kiuj trafis ilin dum la vojo kaj el kiuj la Eternulo ilin savis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Jitro ĝojis je la tuta bono, kiun la Eternulo faris al Izrael, savinte lin el la mano de la Egiptoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Kaj Jitro diris: Benata estu la Eternulo, kiu savis vin el la manoj de la Egiptoj kaj el la mano de Faraono, kaj kiu savis la popolon el sub la mano de la Egiptoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Nun mi scias, ke la Eternulo estas pli granda ol ĉiuj dioj; ĝi estas pro tio, ke tiuj malbonintencis kontraŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Kaj Jitro, la bopatro de Moseo, alportis al Dio bruloferon kaj buĉoferojn; kaj Aaron kaj ĉiuj ĉefoj de Izrael venis, por manĝi panon kun la bopatro de Moseo antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'La sekvantan tagon Moseo sidiĝis, por juĝi la popolon; kaj la popolo staris antaŭ Moseo de la mateno ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Kaj la bopatro de Moseo vidis ĉion, kion li faras por la popolo, kaj diris: Kio estas tio, kion vi faras al la popolo? kial vi sola sidas kaj la tuta popolo staras antaŭ vi de mateno ĝis vespero?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Tiam Moseo diris al sia bopatro: La popolo venas al mi, por demandi Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Kiam fariĝas inter ili ia afero, ili venas al mi; kaj mi juĝas inter unu kaj alia, kaj mi sciigas la leĝojn de Dio kaj Liajn instruojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Sed la bopatro de Moseo diris al li: Ne bona estas la afero, kiun vi faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Senfortiĝos vi kaj ĉi tiu popolo, kiu estas kun vi; ĉar la afero estas tro malfacila por vi; vi ne povas plenumi ĝin sola.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Aŭskultu mian voĉon, mi donos al vi konsilon, kaj Dio estos kun vi. Vi estu por la popolo perulo antaŭ Dio, kaj prezentu la aferojn al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Instruu al ili la leĝojn kaj instruojn, kaj montru al ili la vojon, kiun ili devas iri, kaj la farojn, kiujn ili devas fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Kaj vi elserĉu inter la tuta popolo homojn bravajn, timantajn Dion, homojn veramajn, neprofitamajn; kaj starigu ilin super la popolo kiel milestrojn, centestrojn, kvindekestrojn, kaj dekestrojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Kaj ili juĝadu la popolon en ĉiu tempo; ĉiun grandan aferon ili venigu al vi, sed ĉiun malgrandan aferon juĝu ili; tiel fariĝos pli facile al vi, kaj ili portos kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Se vi tion faros kaj Dio al vi ordonos, tiam vi povos resti forta, kaj ankaŭ ĉi tiu tuta popolo venos al sia loko en paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Moseo obeis la voĉon de sia bopatro, kaj faris ĉion, kion tiu diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Kaj Moseo elektis bravajn homojn inter la tuta Izrael, kaj faris ilin estroj super la popolo, milestroj, centestroj, kvindekestroj, kaj dekestroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Kaj ili juĝadis la popolon en ĉiu tempo; malfacilan aferon ili venigadis al Moseo, kaj ĉiun aferon malgrandan juĝadis ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Kaj Moseo lasis sian bopatron foriri, kaj tiu iris en sian landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'En la tria monato post la eliro de la Izraelidoj el la lando Egipta, en tiu tago ili venis en la dezerton Sinaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Ili eliris el Refidim, kaj venis en la dezerton Sinaj kaj starigis sian tendaron en la dezerto; kaj Izrael stariĝis tie tendare antaŭ la monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Kaj Moseo supreniris al Dio; kaj la Eternulo vokis al li de la monto, dirante: Tiel diru al la domo de Jakob kaj sciigu al la filoj de Izrael:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Vi vidis, kion Mi faris al la Egiptoj kaj kiel Mi portis vin sur aglaj flugiloj kaj venigis vin al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Kaj nun se vi obeos Mian voĉon kaj observos Mian interligon, vi estos Mia amata propraĵo inter ĉiuj popoloj, ĉar al Mi apartenas la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Kaj vi estos por Mi regno de pastroj kaj popolo sankta. Tio estas la vortoj, kiujn vi diru al la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Moseo venis, kaj alvokis la ĉefojn de la popolo, kaj prezentis al ili ĉiujn tiujn vortojn, pri kiuj la Eternulo ordonis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Kaj la tuta popolo respondis kune kaj diris: Ĉion, kion la Eternulo diris, ni faros. Kaj Moseo raportis la vortojn de la popolo al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Kaj la Eternulo diris al Moseo: Jen Mi venos al vi en densa nubo, por ke la popolo aŭdu, kiam Mi parolos kun vi, kaj por ke ili kredu al vi eterne. Kaj Moseo sciigis la vortojn de la popolo al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Kaj la Eternulo diris al Moseo: Iru al la popolo kaj sanktigu ĝin hodiaŭ kaj morgaŭ, kaj ili lavu siajn vestojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Kaj ili estu pretaj por la tria tago, ĉar en la tria tago la Eternulo malsupreniros antaŭ la okuloj de la tuta popolo sur la monton Sinaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Kaj difinu limon por la popolo ĉirkaŭe, dirante: Gardu vin, ke vi ne supreniru sur la monton nek tuŝu ĝian bazon; ĉiu, kiu tuŝos la monton, estu mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Mano lin ne tuŝu, sed per ŝtonoj li estu mortigita, aŭ li estu pafmortigita; ĉu tio estos bruto, ĉu tio estos homo, li ne vivu. Kiam eksonos longa trumpetado, tiam ili povas supreniri sur la monton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Kaj Moseo malsupreniris de la monto al la popolo kaj sanktigis la popolon, kaj ili lavis siajn vestojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Kaj li diris al la popolo: Estu pretaj por la tria tago; ne alproksimiĝu al virino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'En la tria tago, tuj matene, komenciĝis tondroj kaj fulmoj, kaj densa nubo estis super la monto, kaj aŭdiĝis tre forta sonado de korno; kaj ektremis la tuta popolo, kiu estis en la tendaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Kaj Moseo elirigis la popolon el la tendaro renkonte al Dio, kaj ili stariĝis antaŭ la bazo de la monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Kaj la monto Sinaj tuta fumiĝis kaŭze de tio, ke la Eternulo malsupreniris sur ĝin en fajro; kaj ĝia fumo leviĝadis kiel fumo el forno, kaj la tuta monto forte tremis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Kaj la sonado de la korno fariĝadis ĉiam pli kaj pli forta; Moseo paroladis, kaj Dio respondadis al li per voĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Kaj la Eternulo malsupreniris sur la monton Sinaj, sur la supron de la monto; kaj la Eternulo vokis Moseon sur la supron de la monto, kaj Moseo supreniris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Kaj la Eternulo diris al Moseo: Iru malsupren, avertu la popolon, ke ili ne translimiĝu perforte al la Eternulo, por vidi, ĉar tiam multaj el ili falus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Eĉ la pastroj, kiuj alproksimiĝos al la Eternulo, sanktigu sin, por ke la Eternulo ne frakasu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Kaj Moseo diris al la Eternulo: La popolo ne povas supreniri sur la monton Sinaj, ĉar Vi avertis nin, dirante: Faru limon ĉirkaŭ la monto, kaj sanktigu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Sed la Eternulo diris al li: Iru malsupren, poste supreniru vi kaj Aaron kun vi; sed la pastroj kaj la popolo ne penu perforte supreniri al la Eternulo, por ke Li ne frakasu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Kaj Moseo malsupreniris al la popolo kaj diris tion al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Kaj Dio diris ĉiujn sekvantajn vortojn:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Mi estas la Eternulo, via Dio, kiu elkondukis vin el la lando Egipta, el la domo de sklaveco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Ne ekzistu ĉe vi aliaj dioj antaŭ Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Ne faru al vi idolon, nek bildon de io, kio estas en la ĉielo supre aŭ sur la tero malsupre aŭ en la akvo sub la tero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'ne kliniĝu antaŭ ili kaj ne servu ilin; ĉar Mi, la Eternulo, via Dio, estas Dio severa, kiu la malbonagon de la patroj punas sur la idoj en la tria kaj kvara generacioj ĉe Miaj malamantoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'kaj kiu faras favorkoraĵon por miloj al Miaj amantoj kaj al la plenumantoj de Miaj ordonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Ne malbonuzu la nomon de la Eternulo, via Dio; ĉar la Eternulo ne lasos senpuna tiun, kiu malbonuzas Lian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Memoru pri la tago sabata, ke vi tenu ĝin sankta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Dum ses tagoj laboru kaj faru ĉiujn viajn aferojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'sed la sepa tago estas sabato de la Eternulo, via Dio; faru nenian laboron, nek vi, nek via filo, nek via filino, nek via sklavo, nek via sklavino, nek via bruto, nek via fremdulo, kiu estas inter viaj pordegoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'ĉar dum ses tagoj la Eternulo kreis la ĉielon kaj la teron, la maron, kaj ĉion, kio estas en ili, sed en la sepa tago Li ripozis. Tial la Eternulo benis la tagon sabatan kaj sanktigis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Respektu vian patron kaj vian patrinon, por ke longe daŭru via vivo sur la tero, kiun la Eternulo, via Dio, donas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Ne mortigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Ne adultu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Ne ŝtelu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Ne parolu kontraŭ via proksimulo malveran ateston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Ne deziru la domon de via proksimulo; ne deziru la edzinon de via proksimulo, nek lian sklavon, nek lian sklavinon, nek lian bovon, nek lian azenon, nek ion, kio apartenas al via proksimulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Kaj la tuta popolo vidis la tondrojn kaj la fulmojn kaj la sonadon de la korno kaj la fumiĝadon de la monto; kaj la popolo vidis, kaj retiriĝis kun teruro kaj stariĝis malproksime.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Kaj ili diris al Moseo: Parolu vi kun ni, kaj ni aŭskultos, sed Dio ne parolu kun ni, por ke ni ne mortu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Kaj Moseo diris al la popolo: Ne timu; ĉar por vin elprovi venis Dio, kaj por ke la timo antaŭ Li estu antaŭ via vizaĝo, por ke vi ne peku.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Kaj la popolo staris malproksime; sed Moseo alproksimiĝis al la mallumo, kie estis Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Kaj la Eternulo diris al Moseo: Tiel diru al la Izraelidoj: Vi vidis, kiel Mi parolis kun vi el la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Ne faru antaŭ Mi diojn arĝentajn, kaj diojn orajn ne faru al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Altaron el tero faru al Mi, kaj oferu sur ĝi viajn bruloferojn kaj pacoferojn, viajn ŝafojn kaj viajn bovojn; sur ĉiu loko, kie Mi memorigos Mian nomon, Mi venos al vi kaj benos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Kaj se vi faros al Mi altaron el ŝtonoj, ne konstruu ĝin el ŝtonoj hakitaj; ĉar se vi levos sur ĝin vian hakilon, vi ĝin malsanktigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Kaj ne supreniru per ŝtupoj al Mia altaro, por ke ne malkovriĝu via nudeco antaŭ ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Kaj jen estas la juĝoj, kiujn vi proponos al ili:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Se vi aĉetos sklavon Hebreon, li servu dum ses jaroj; sed en la sepa li eliru libera senpage.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Se li venis sola, li eliru sola; se li estas edzigita, tiam lia edzino eliru kune kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Se lia sinjoro donis al li edzinon kaj ŝi naskis al li filojn aŭ filinojn, tiam la edzino kaj ŝiaj infanoj restu ĉe sia sinjoro, kaj li eliru sola.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Sed se la sklavo diros: Mi amas mian sinjoron, mian edzinon, kaj miajn infanojn, mi ne volas liberiĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'tiam lia sinjoro alkonduku lin antaŭ la potenculojn kaj starigu lin apud la pordo aŭ apud la fosto, kaj lia sinjoro trapiku lian orelon per aleno, kaj li estu lia sklavo por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Kaj se iu vendos sian filinon kiel sklavinon, ŝi ne eliru kiel eliras la sklavoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Se ŝi ne plaĉas al sia sinjoro, al kiu ŝi estis fordonita, tiam li donu al ŝi la eblon elaĉetiĝi; al fremda popolo ŝin vendi li ne havas la rajton, ĉar li kondutis ne honeste kontraŭ ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Se iu transdonos ŝin al sia filo, li agu kun ŝi laŭ la rajto de filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Se li prenos por li alian edzinon, tiam nutraĵo, vestoj, kaj edzina vivo ne devas esti rifuzataj al ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Kaj se tiujn tri aferojn li ne faros por ŝi, tiam ŝi eliru senpage, sen elaĉeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Se iu batos homon kaj tiu mortos, li estu mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Sed se li ne agis malbonintence, nur Dio puŝis tiun sub lian manon, Mi difinas al vi lokon, kien li povas forkuri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Sed se iu intence mortigis sian proksimulon per ruzo, tiam eĉ de Mia altaro forprenu lin, ke li mortu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Kiu batas sian patron aŭ sian patrinon, tiu devas esti mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Kaj se iu ŝtelas homon por vendi lin, aŭ oni trovas tiun en lia mano, li devas esti mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Kiu malbenas sian patron aŭ sian patrinon, tiu devas esti mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Se homoj kverelos, kaj unu batos la alian per ŝtono aŭ per pugno kaj tiu ne mortos, sed devos kuŝi en lito:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'se li leviĝos kaj irados ekstere per apogilo, tiam la batinto estu senkulpa; li nur kompensu al li lian malliberigitecon kaj zorgu pri lia kuracado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Se iu batos sian sklavon aŭ sian sklavinon per bastono, kaj tiu mortos sub lia mano, tiam oni devas lin puni;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'sed se tiu restos viva dum unu aŭ du tagoj, tiam oni ne devas lin puni; ĉar tio estas lia mono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Se viroj kverelos kaj frapos gravedan virinon, kaj ŝi abortos, sed ne fariĝos malfeliĉo, tiam oni punu lin per monpuno, kian metos sur lin la edzo de la virino, kaj li pagu ĝin laŭ decido de juĝantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Sed se fariĝos malfeliĉo, tiam donu animon pro animo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'okulon pro okulo, denton pro dento, manon pro mano, piedon pro piedo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'bruldifekton pro bruldifekto, vundon pro vundo, kontuzon pro kontuzo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Kaj se iu batos okulon de sia sklavo aŭ de sia sklavino kaj difektos ĝin, tiam li forliberigu tiun kompense pro la okulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Kaj se li elbatos denton de sia sklavo aŭ denton de sia sklavino, li forliberigu tiun kompense pro la dento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Se bovo kornobatos viron aŭ virinon kaj tiu mortos, tiam oni ŝtonmortigu la bovon kaj ĝia viando ne estu manĝata, sed la mastro de la bovo restu senkulpa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Sed se la bovo estis kornobatema antaŭe kaj oni tion sciigis al ĝia mastro kaj li ĝin ne gardis kaj ĝi mortigis viron aŭ virinon, tiam la bovon oni ŝtonmortigu kaj ĝian mastron oni mortigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Se oni metos sur lin elaĉeton, tiam li donu pro sia animo tian elaĉetan sumon, kia estos metita sur lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Se filo aŭ filino estos kornobatita, oni agu kun li en la sama maniero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Se iun sklavon aŭ sklavinon kornobatos la bovo, tiam tridek sikloj da mono devas esti pagitaj al ties mastro kaj la bovo devas esti ŝtonmortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Se iu malfermos kavon, aŭ elfosos kavon, kaj ne kovros ĝin, kaj falos tien bovo aŭ azeno,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'tiam la mastro de la kavo devas kompensi per mono al ĝia mastro, kaj la kadavro apartenu al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Se la bovo de iu homo kornobatos bovon de lia proksimulo tiel, ke ĝi mortos, tiam ili vendu la vivan bovon kaj dividu inter si egalparte la monon pro ĝi, kaj ankaŭ la kadavron ili dividu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Sed se oni sciis, ke la bovo estis kornobatema antaŭe, kaj ĝia mastro ĝin ne gardis, tiam ili pagu bovon pro la bovo, kaj la kadavro apartenu al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Se iu ŝtelos bovon aŭ ŝafon kaj buĉos ĝin aŭ vendos ĝin, tiam li pagu kvin bovojn pro la bovo kaj kvar ŝafojn pro la ŝafo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Se iu trovos ŝtelanton ĉe subfosado kaj batos lin kaj tiu mortos, tiam oni ne juĝu lin pro la sango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Sed se lumis super li la suno, tiam oni juĝu lin pro la sango. La ŝtelinto pagu kompenson; se li ne havas, tiam oni lin vendu pro lia ŝtelo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Se la ŝtelitaĵo, ĉu ĝi estas bovo, ĉu azeno, ĉu ŝafo, estos trovita en liaj manoj viva, tiam li kompensu duoble.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Se iu difektos kampon aŭ vinberejon, lasante sian bruton, ke ĝi difektu kampon de aliulo, tiam li devas pagi per plejbonaĵo el sia kampo kaj per plejbonaĵo el sia vinberejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Se eliros fajro kaj trafos dornojn kaj ekstermos garbojn aŭ starantan grenon aŭ kampon, tiam tiu kompensu, kiu kaŭzis la brulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Se iu donos al sia proksimulo monon aŭ uzataĵojn, por konservi, kaj ili estos ŝtelitaj el la domo de tiu homo, tiam, se la ŝtelinto estos trovita, li kompensu duoble.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Se la ŝtelinto ne estos trovita, tiam la mastro de la domo venu al la potenculoj, kaj ĵuru, ke li ne etendis sian manon sur la apartenaĵon de sia proksimulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Pri ĉiu maljustaĵo, ĉu ĝi estos pri bovo, ĉu pri azeno, ĉu pri ŝafo, ĉu pri vesto, pri ĉiu perditaĵo, pri kiu iu diros, ke ĝi estas lia, la afero de ambaŭ devas esti prezentita al la potenculoj; kiun la potenculoj trovos kulpa, tiu kompensu duoble al sia proksimulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Se iu donos al sia proksimulo azenon aŭ bovon aŭ ŝafon aŭ alian bruton, por konservi, kaj ĝi mortos aŭ estos difektita aŭ forkaptita, kaj neniu tion vidos,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'tiam ĵuro antaŭ la Eternulo estu inter ili, ke li ne etendis sian manon sur la apartenaĵon de sia proksimulo, kaj ĝia mastro ĝin prenos kaj li ne kompensos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Sed se oni ĝin ŝtelos de li, tiam li devas kompensi al ĝia mastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Se ĝi estos disŝirita, li prezentu ateston, kaj la disŝiritaĵon li ne kompensos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Se iu ĝin prenos prunte de sia proksimulo, kaj ĝi estos difektita aŭ mortos dum foresto de sia mastro, tiam li devas kompensi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Se ĝia mastro estis apud ĝi, tiam li ne devas kompensi. Se ĝi estis dungita, li perdis sian dungomonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Se iu forlogos virgulinon, kiu ne estas fianĉinigita, kaj kuŝos kun ŝi, tiam li donu al ŝi doton kaj prenu ŝin al si kiel edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Se ŝia patro ne volos doni ŝin al li, tiam li pagu tiom da mono, kiom virgulinoj ordinare ricevas dote.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Sorĉistinon ne lasu vivi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Ĉiu, kiu kuŝis kun bruto, estu mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Kiu alportas oferojn al dioj, krom al la Eternulo sole, tiu estu ekstermita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Fremdulon ne ofendu, nek premu lin; ĉar fremduloj vi estis en la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Vidvinon kaj orfon ne premu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Se vi ilin premos kaj ili krios al Mi, tiam Mi aŭdos ilian krion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'kaj ekflamos Mia kolero, kaj Mi mortigos vin per glavo, kaj viaj edzinoj estos vidvinoj kaj viaj infanoj estos orfoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Se vi pruntedonos monon al iu el Mia popolo, al iu malriĉulo apud vi, ne estu por li premanto, ne metu sur lin procentojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Se vi prenos de via proksimulo veston kiel garantiaĵon, tiam antaŭ la subiro de la suno redonu ĝin al li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'ĉar ĝi estas lia sola kovro, ĝi estas la vesto por lia korpo; en kio li dormos? kaj kiam li krios al Mi, Mi aŭdos, ĉar Mi estas favorkora.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Potenculojn ne malbenu, kaj estron de via popolo ne insultu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Vian abundon kaj sukon ne retenu; la unuenaskiton el viaj filoj vi devas doni al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Tiel same agu kun via bovo kaj via ŝafo; sep tagojn ĝi restu kun sia patrino, en la oka tago donu ĝin al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Estu por Mi sanktaj homoj; kaj viandon, disŝiritan sur la kampo, ne manĝu; al hundo ĵetu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Ne disvastigu malveran famon; ne kunigu vian manon kun malvirtulo, por esti atestanto de malbonago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Ne sekvu la amason por malbonaĵoj; kaj en juĝo ne kliniĝu al la opinio de la plimulto, por dekliniĝi de la vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Ankaŭ malriĉulon ne favoru en lia juĝa afero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Se vi renkontos bovon de via malamiko aŭ lian azenon erarvagantan, rekonduku ĝin al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Se vi vidos, ke azeno de via malamiko falis sub sia ŝarĝo, ne forlasu ĝin, sed alportu helpon kune kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Ne forklinu la rajton de via malriĉulo en lia juĝa afero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'De mensogaĵo malproksimiĝu, kaj senkulpulon kaj virtulon ne mortigu; ĉar Mi ne pravigos maljustulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Donacojn ne akceptu; ĉar donacoj blindigas vidantojn kaj malĝustigas la aferojn de virtuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Fremdulon ne premu; vi konas ja la animon de fremdulo, ĉar fremduloj vi estis en la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Dum ses jaroj prisemu vian teron kaj rikoltu ĝiajn produktaĵojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'sed en la sepa jaro ripozigu ĝin kaj ne tuŝu ĝin, por ke manĝu la malriĉuloj el via popolo, kaj la restaĵon manĝu la bestoj de la kampo. Tiel same agu kun via vinberejo kaj kun via olivarbejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Dum ses tagoj faru viajn laborojn, kaj en la sepa tago festu, por ke ripozu via bovo kaj via azeno kaj por ke refreŝiĝu la filo de via sklavino kaj la fremdulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Kaj ĉion, kion Mi diris al vi, observu; kaj la nomon de aliaj dioj ne citu, ĝi ne estu aŭdata el via buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Tri fojojn festu al Mi dum la jaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'La feston de la macoj observu; dum sep tagoj manĝu macojn, kiel Mi ordonis al vi, en la difinita tempo en la monato Abib (ĉar en tiu tempo vi eliris el Egiptujo); kaj oni ne aperu antaŭ Mi kun malplenaj manoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'ankaŭ la feston de la rikolto de la unuaj fruktoj de via laboro, de tio, kion vi semos sur la kampo; kaj la feston de kolekto en la fino de la jaro, kiam vi kolektos viajn laborfruktojn el la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Tri fojojn ĉiujare aperu ĉiuj viaj virseksuloj antaŭ la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Ne verŝu sur fermentaĵon la sangon de Mia ofero; kaj la graso de Mia festofero ne restu ĝis mateno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'La komencaĵon de la unuaj fruktoj de via tero alportu en la domon de la Eternulo, via Dio. Ne kuiru kapridon en la lakto de ĝia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Jen Mi sendas anĝelon antaŭ vi, por gardi vin sur la vojo, kaj por venigi vin al la loko, kiun Mi pretigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Gardu vin antaŭ lia vizaĝo kaj aŭskultu lian voĉon; ne incitu lin, ĉar li ne pardonos vian pekon; ĉar Mia nomo estas en li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Sed se vi aŭskultos lian voĉon, kaj faros ĉion, kion Mi diros, tiam Mi malamikos kontraŭ viaj malamikoj kaj premos viajn premantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Kiam Mia anĝelo iros antaŭ vi, kaj Mi venigos vin al la Amoridoj, la Ĥetidoj, la Perizidoj, la Kanaanidoj, la Ĥividoj, kaj la Jebusidoj, kaj Mi ilin ekstermos:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'ne adoru iliajn diojn kaj ne servu ilin, kaj ne agu kiel ili agas, sed frakasu ilin kaj detruu iliajn statuojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Kaj servu la Eternulon, vian Dion, kaj Li benos vian panon kaj vian akvon; kaj Mi forigos malsanon el via mezo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Ne estos seninfana nek sennaska en via lando; la nombron de viaj tagoj Mi faros plena.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Mian teruron Mi sendos antaŭ vi, kaj Mi konfuzos ĉiun popolon, al kiu vi venos, kaj ĉiujn viajn malamikojn Mi turnos al vi dorse.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Kaj Mi sendos krabrojn antaŭ vi, kaj ili forpelos la Ĥividojn kaj la Kanaanidojn kaj la Ĥetidojn de antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Mi ne forpelos ilin de antaŭ vi en unu jaro, por ke la tero ne fariĝu senhoma kaj por ke ne multiĝu kontraŭ vi la bestoj de la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Iom post iom Mi forpelos ilin de antaŭ vi, ĝis vi multiĝos kaj posedos la landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Kaj Mi faros viajn limojn de la Ruĝa Maro ĝis la Maro Filiŝta, kaj de la dezerto ĝis la Rivero; ĉar Mi transdonos en viajn manojn la loĝantojn de la lando, kaj vi forpelos ilin de antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Ne faru interligon kun ili nek kun iliaj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Ili ne loĝu en via lando, por ke ili ne pekigu vin kontraŭ Mi; se vi servos iliajn diojn, tio fariĝos kaptilo por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Kaj al Moseo Li diris: Supreniru al la Eternulo, vi kaj Aaron, Nadab kaj Abihu, kaj sepdek el la ĉefoj de Izrael, kaj faru adoron de malproksime.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Kaj Moseo sola alproksimiĝu al la Eternulo; sed ili ne alproksimiĝu, kaj la popolo ne supreniru kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Kaj Moseo venis kaj rakontis al la popolo ĉiujn vortojn de la Eternulo kaj ĉiujn leĝojn. Kaj la tuta popolo respondis per unu voĉo, kaj ili diris: Ĉion, kion diris la Eternulo, ni faros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Kaj Moseo skribis ĉiujn vortojn de la Eternulo, kaj li leviĝis frue matene kaj konstruis altaron sub la monto kaj dek du kolonojn laŭ la dek du triboj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Kaj li sendis junulojn el la Izraelidoj, kaj ili alportis bruloferojn kaj buĉis pacoferojn al la Eternulo, bovidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Moseo prenis duonon de la sango kaj enverŝis en pelvojn, kaj duonon de la sango li ŝprucigis sur la altaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Kaj li prenis la libron de la interligo kaj laŭtlegis ĝin al la popolo, kaj ili diris: Ĉion, kion diris la Eternulo, ni faros kaj obeos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Kaj Moseo prenis la sangon kaj ŝprucigis sur la popolon, kaj diris: Jen estas sango de la interligo, kiun la Eternulo faris kun vi pri ĉiuj tiuj vortoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Kaj supreniris Moseo kaj Aaron, Nadab kaj Abihu, kaj sepdek el la ĉefoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'Kaj ili vidis la Dion de Izrael; kaj sub Liaj piedoj estis io, kiel faritaĵo el brilanta safiro, kaj kiel la ĉielo mem, kiam ĝi estas klara.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Li ne etendis Sian manon kontraŭ la ĉefojn de Izrael; kaj ili vidis Dion, kaj manĝis kaj trinkis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Kaj la Eternulo diris al Moseo: Supreniru al Mi sur la monton kaj estu tie; kaj Mi donos al vi ŝtonajn tabelojn, kaj la instruon kaj ordonojn, kiujn Mi skribis, por instrui ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Kaj leviĝis Moseo kaj lia servanto Josuo, kaj Moseo supreniris sur la monton de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Kaj al la ĉefoj li diris: Restu ĉi tie, ĝis ni revenos al vi; kaj jen Aaron kaj Ĥur estas kun vi; kiu havas ian aferon, tiu venu al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Kaj Moseo supreniris sur la monton, kaj nubo kovris la monton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Kaj la majesto de la Eternulo loĝis sur la monto Sinaj, kaj la nubo ĝin kovris dum ses tagoj; kaj Li vokis Moseon en la sepa tago el interne de la nubo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Kaj la aspekto de la majesto de la Eternulo estis kiel fajro flamanta sur la supro de la monto antaŭ la okuloj de la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Kaj Moseo eniris en la mezon de la nubo, kaj supreniris sur la monton; kaj Moseo estis sur la monto dum kvardek tagoj kaj kvardek noktoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Diru al la Izraelidoj, ke ili alportu por Mi oferdonon; de ĉiu homo, kies koro deziros doni, prenu la oferdonon por Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Kaj jen estas la oferdono, kiun vi prenos de ili: oro kaj arĝento kaj kupro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'kaj blua teksaĵo kaj purpura kaj ruĝa, kaj bisino kaj kapra lano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'kaj virŝafaj feloj ruĝe kolorigitaj kaj antilopaj feloj, kaj akacia ligno,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'oleo por lumigado, aromaĵoj por la sankta oleo kaj por la bonodoraj incensoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'ŝtonoj oniksaj kaj ŝtonoj enkadrigeblaj por la efodo kaj por la surbrustaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Kaj ili faru por Mi sanktejon, por ke Mi loĝu inter ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Laŭ ĉio, kiel Mi montros al vi la bildon de la Loĝejo kaj la bildon de ĉiuj ĝiaj objektoj, tiel faru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Kaj ili faru keston el akacia ligno; du ulnoj kaj duono estu ĝia longo, kaj unu ulno kaj duono ĝia larĝo, kaj unu ulno kaj duono ĝia alto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Kaj tegu ĝin per pura oro, interne kaj ekstere tegu ĝin, kaj faru sur ĝi oran kronon ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Kaj fandu por ĝi kvar orajn ringojn, kaj alfortikigu ilin sur ĝiaj kvar anguloj: du ringojn sur unu ĝia flanko kaj du ringojn sur ĝia alia flanko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Kaj faru stangojn el akacia ligno kaj tegu ilin per oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Kaj metu la stangojn en la ringojn sur la flankoj de la kesto, por porti la keston per ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'En la ringoj de la kesto devas esti la stangoj; ili ne estu prenataj for de ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Kaj en la keston enmetu la Ateston, kiun Mi donos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Kaj faru fermoplaton el pura oro; du ulnoj kaj duono estu ĝia longo, kaj unu ulno kaj duono ĝia larĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Kaj faru du kerubojn el oro; per forĝa laboro faru ilin ĉe la du randoj de la fermoplato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Faru unu kerubon ĉe unu flanko kaj unu kerubon ĉe la alia flanko; elstarantaj el la fermoplato faru la kerubojn, sur ĝiaj du flankoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Kaj la keruboj estu etendantaj siajn flugilojn supren, kovrante per siaj flugiloj la fermoplaton, kaj iliaj vizaĝoj estu unu kontraŭ la alia; al la fermoplato estu turnitaj la vizaĝoj de la keruboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Kaj metu la fermoplaton sur la keston supre, kaj en la keston metu la ateston, kiun Mi donos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Kaj Mi aperados al vi tie, kaj Mi parolados kun vi super la fermoplato, el inter la du keruboj, kiuj estos super la kesto de atesto, pri ĉio, kion Mi ordonos al vi por la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Kaj faru tablon el akacia ligno; du ulnoj estu ĝia longo, kaj unu ulno ĝia larĝo, kaj unu ulno kaj duono ĝia alto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Kaj tegu ĝin per pura oro, kaj faru al ĝi oran kronon ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Kaj faru ĉirkaŭ ĝi manlarĝan listelon, kaj faru oran kronon ĉirkaŭ la listelo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Kaj faru por ĝi kvar orajn ringojn, kaj alfortikigu la ringojn en la kvar anguloj, ĉe ĝiaj kvar piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Apud la listelo estu la ringoj, kiel ingoj por stangoj, por porti la tablon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Kaj faru la stangojn el akacia ligno, kaj tegu ilin per oro, ke per ili oni portu la tablon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Kaj faru ĝiajn pladojn kaj ĝiajn kulerojn, kaj ĝiajn kalikojn kaj ĝiajn kruĉojn, per kiuj oni verŝos; el pura oro faru ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Kaj metu sur la tablon panon de propono antaŭ Mi ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Kaj faru kandelabron el pura oro, per forĝa laboro estu farita la kandelabro; ĝia trunko kaj ĝiaj branĉoj, ĝiaj kalikoj, ĝiaj kapetoj, kaj ĝiaj floroj elstaru el ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Kaj ses branĉoj devas elstari el ĝiaj flankoj: tri branĉoj de la kandelabro el unu flanko, kaj tri branĉoj de la kandelabro el la alia flanko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'tri migdalformaj kalikoj, kapeto, kaj floro, sur unu branĉo, kaj tri migdalformaj kalikoj, kapeto, kaj floro, sur la alia branĉo; tiel sur la ses branĉoj, kiuj elstaras el la kandelabro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Kaj sur la kandelabro estu kvar migdalformaj kalikoj kun kapetoj kaj floroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Kaj kapeto sub unu paro da branĉoj, kapeto sub la dua paro da branĉoj, kaj kapeto sub la tria paro da branĉoj; tiel por la ses branĉoj, kiuj elstaras el la kandelabro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'La kapetoj kaj branĉoj devas elstari el ĝi; ĉio devas esti unu forĝita tutaĵo el pura oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Kaj faru por ĝi sep lucernojn; kaj starigu sur ĝi ĝiajn lucernojn, ke ili lumu sur ĝian antaŭan flankon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Kaj ĝiaj preniloj kaj cindrujoj estu el pura oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'El kikaro da pura oro oni faru ĝin kaj ĉiujn tiujn apartenaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Kaj rigardu kaj faru laŭ ilia modelo, kiu estis montrita al vi sur la monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'La tabernaklon faru el dek tapiŝoj el tordita bisino, kaj el blua, purpura, kaj ruĝa teksaĵo; kerubojn artiste laboritajn faru sur ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'La longo de ĉiu tapiŝo estu dudek ok ulnoj, kaj la larĝo de ĉiu tapiŝo estu kvar ulnoj; unu mezuro estu por ĉiuj tapiŝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Kvin tapiŝoj estu kunigitaj unu kun la alia, kaj la kvin ceteraj tapiŝoj estu ankaŭ kunigitaj unu kun la alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Kaj faru maŝojn el blua teksaĵo sur la rando de unu tapiŝo, sur la rando de la kuniĝo, kaj tiel same faru sur la rando de la ekstrema tapiŝo, sur la dua rando de kuniĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Kvindek maŝojn faru sur unu tapiŝo, kaj kvindek maŝojn faru sur la rando de tiu tapiŝo, sur kiu estas la dua flanko de la kuniĝo; la maŝoj devas esti reciproke aranĝitaj unu kontraŭ alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Kaj faru kvindek orajn hoketojn, kaj kunigu la tapiŝojn unu kun la alia per la hoketoj, por ke la tabernaklo fariĝu unu tutaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Kaj faru tapiŝojn el kapra lano kiel kovron super la tabernaklo; dek unu tiajn tapiŝojn faru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'La longo de ĉiu tapiŝo estu tridek ulnoj, kaj la larĝo de ĉiu tapiŝo estu kvar ulnoj; unu mezuro estu por la dek unu tapiŝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Kaj kunigu kvin tapiŝojn aparte kaj ses tapiŝojn aparte, kaj la sesan tapiŝon faldu duige antaŭ la tabernaklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Kaj faru kvindek maŝojn sur la rando de la ekstrema tapiŝo, sur la rando de la kuniĝo, kaj kvindek maŝojn sur la rando de la dua kuniĝa tapiŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Kaj faru kvindek kuprajn hoketojn, kaj metu la hoketojn en la maŝojn, por ke vi kunigu la tendon kaj ĝi estu unu tutaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Kaj el la superflua pendanta parto de la tapiŝoj de la kovro, duono de la superflua tapiŝa parto superpendu super la malantaŭa flanko de la tabernaklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Kaj po unu ulno ĉiuflanke el la superflua longo de la tapiŝoj superpendu super ambaŭ flankoj de la tabernaklo, por kovri ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Kaj faru kovron por la tendo el ruĝaj virŝafaj feloj kaj ankoraŭ kovron el antilopaj feloj supre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Kaj faru starantajn tabulojn por la tabernaklo el akacia ligno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Dek ulnoj estu la longo de ĉiu tabulo, kaj unu ulno kaj duono la larĝo de ĉiu tabulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Du pivotoj estu ĉe ĉiu tabulo, alĝustigitaj unu al la alia; tiel faru ĉe ĉiuj tabuloj de la tabernaklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Kaj faru la tabulojn por la tabernaklo: dudek tabuloj staru sur la flanko suda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Kaj kvardek arĝentajn bazojn faru sub la dudek tabuloj: du bazojn sub ĉiu tabulo, por ĝiaj du pivotoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Kaj sur la dua flanko de la tabernaklo, sur la flanko norda, estu dudek tabuloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'kaj kvardek arĝentaj bazoj por ili, po du bazoj sub ĉiu tabulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Kaj sur la malantaŭa flanko de la tabernaklo, okcidente, faru ses tabulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Kaj du tabulojn faru en la anguloj de la tabernaklo sur la malantaŭa flanko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Ili estu kunigitaj malsupre kaj kunigitaj supre per unu ringo; tiel ĝi estu kun ili ambaŭ; por ambaŭ anguloj ili estu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Tiel estu ok tabuloj, kaj ĉe ili dek ses arĝentaj bazoj, po du bazoj sub ĉiu tabulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Kaj faru riglilojn el akacia ligno, kvin por la tabuloj de unu flanko de la tabernaklo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'kaj kvin riglilojn por la tabuloj de la dua flanko de la tabernaklo, kaj kvin riglilojn por la tabuloj de la malantaŭa flanko de la tabernaklo, okcidente.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Kaj la meza riglilo meze de la tabuloj ŝoviĝu de unu fino ĝis la alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Kaj la tabulojn tegu per oro, kaj iliajn ringojn, ingojn por la rigliloj, faru el oro, kaj la riglilojn tegu per oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Starigu la tabernaklon laŭ ĝia modelo, kiu estis montrita al vi sur la monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Kaj faru kurtenon el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino; artiste laboritaj keruboj estu faritaj sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Kaj pendigu ĝin sur kvar akaciaj kolonoj, tegitaj per oro kaj havantaj orajn hokojn kaj arĝentajn bazojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Kaj pendigu la kurtenon sub la hokoj, kaj enportu tien internen de la kurteno la keston de atesto; kaj la kurteno faru por vi apartigon inter la sanktejo kaj la plejsanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Kaj metu la fermoplaton sur la keston de atesto en la plejsanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Kaj starigu la tablon ekster la kurteno, kaj la kandelabron kontraŭ la tablo, en la suda parto de la tabernaklo; la tablon starigu en la norda parto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Kaj faru kovrotukon por la pordo de la tabernaklo, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino, kun brodaĵoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'kaj faru por la kovrotuko kvin kolonojn el akacia ligno, kaj tegu ilin per oro, kaj iliaj hoketoj estu el oro; kaj fandu por ili kvin kuprajn bazojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Kaj faru la altaron el akacia ligno, havantan la longon de kvin ulnoj kaj la larĝon de kvin ulnoj; kvarangula estu la altaro; kaj ĝia alto estu tri ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Kaj faru ĝiajn kornojn sur ĝiaj kvar anguloj; el ĝi elstaru ĝiaj kornoj; kaj tegu ĝin per kupro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Kaj faru por ĝi potojn por ĝia cindro kaj ŝovelilojn kaj kalikojn kaj forkojn kaj karbujojn; ĉiujn ĝiajn vazojn faru el kupro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Kaj faru por ĝi kradon en formo de kupra reto, kaj faru sur la reto kvar kuprajn ringojn sur ĝiaj kvar anguloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Kaj metu ĝin sub la kornicon de la altaro, malsupren, tiel, ke la reto atingu ĝis la mezo de la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Kaj faru stangojn por la altaro, stangojn el akacia ligno, kaj tegu ilin per kupro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Kaj metu ĝiajn stangojn en ringojn, tiel, ke la stangoj estu ĉe ambaŭ flankoj de la altaro, kiam oni ĝin portos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Interne malplena faru ĝin el tabuloj; kiel estis montrite al vi sur la monto, tiel oni faru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Kaj faru korton por la tabernaklo; sur la flanko suda estu kurtenoj por la korto, el tordita bisino; unu flanko havu la longon de cent ulnoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'kaj ĝiaj dudek kolonoj kaj iliaj dudek bazoj estu el kupro; la hokoj de la kolonoj kaj iliaj ligiloj estu el arĝento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Tiel same ankaŭ sur la norda flanko laŭlonge estu kurtenoj, havantaj la longon de cent ulnoj; kaj dudek kolonoj, kaj por ili dudek bazoj el kupro; la hokoj de la kolonoj kaj iliaj ligiloj estu el arĝento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Sed laŭlarĝe de la korto, sur la flanko okcidenta, estu kurtenoj, havantaj la longon de kvindek ulnoj; dek kolonoj, kaj por ili dek bazoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Kaj laŭlarĝe de la korto, sur la flanko orienta, estu kurtenoj, havantaj la longon de kvindek ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Kaj kurtenoj, havantaj la longon de dek kvin ulnoj, estu por unu latero; ankaŭ tri kolonoj, kaj por ili tri bazoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'Kaj por la dua latero estu kurtenoj, havantaj la longon de dek kvin ulnoj; ankaŭ tri kolonoj, kaj por ili tri bazoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Kaj por la pordego de la korto estu kovrotuko, havanta la longon de dudek ulnoj, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino, kun brodaĵoj; kvar kolonoj, kaj por ili kvar bazoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Ĉiuj kolonoj ĉirkaŭ la korto havu ligilojn el arĝento, hokojn el arĝento, kaj bazojn el kupro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'La longo de la korto estu cent ulnoj, la larĝo ĉie kvindek, kaj la alto kvin ulnoj; ĉio estu farita el tordita bisino, kaj la bazoj estu el kupro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Ĉiuj vazoj de la tabernaklo, por ĉiuj servoj, kaj ĉiuj ĝiaj najloj kaj ĉiuj najloj de la korto, estu el kupro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Kaj vi ordonu al la Izraelidoj, ke ili alportu al vi oleon olivan, puran, pistitan, por lumigado, por ke lucerno brulu ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'En la tabernaklo de kunveno, ekstere de la kurteno, kiu pendas antaŭ la atesto, aranĝadu ĝin Aaron kaj liaj filoj de vespero ĝis mateno antaŭ la Eternulo. Tio estu eterna leĝo en la generacioj de la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Kaj vi alproksimigu al vi vian fraton Aaron kaj liajn filojn kun li el inter la Izraelidoj, por ke li estu Mia pastro: Aaron, kaj Nadab, Abihu, Eleazar, kaj Itamar, la filoj de Aaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Kaj faru sanktajn vestojn por via frato Aaron, por honoro kaj ornamo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Kaj diru al ĉiuj, kiuj havas saĝan koron kaj kiujn Mi plenigis per spirito de saĝo, ke ili faru por Aaron vestojn, por sanktigi lin, ke li estu Mia pastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Kaj jen estas la vestoj, kiujn ili devas fari: surbrustaĵo, efodo, tuniko, ĥitono teksita, cidaro, kaj zono. Kaj ili faru sanktajn vestojn por via frato Aaron kaj por liaj filoj, ke li estu Mia pastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Kaj ili prenu oron, kaj bluan, purpuran, kaj ruĝan teksaĵon, kaj bisinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Kaj ili faru la efodon el oro, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino, en artista maniero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Du surŝultraĵojn kunigantajn ĝi havu sur siaj du finoj, por ke ĝi estu ligita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Kaj la ĉirkaŭliganta zono sur ĝi estu la sama laboraĵo, kiel ĝia kontinuaĵo, el oro, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Kaj prenu du oniksajn ŝtonojn, kaj gravuru sur ili la nomojn de la filoj de Izrael:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'ses el iliaj nomoj sur unu ŝtono kaj la ses ceterajn nomojn sur la dua ŝtono, laŭ la ordo de ilia naskiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Per laboro de gravuristoj, kiel sigelila gravurado, gravurigu sur la du ŝtonoj la nomojn de la filoj de Izrael; faru ilin ĉirkaŭataj per kadretoj el oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Kaj metu la du ŝtonojn sur la surŝultraĵojn de la efodo, kiel ŝtonojn de memoro pri la filoj de Izrael; kaj Aaron portu iliajn nomojn antaŭ la Eternulo sur siaj du surŝultraĵoj por memoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Kaj faru kadretojn el oro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'kaj du ĉenetojn el pura oro; faru ilin kuniĝantaj per siaj finoj, plektitaj; kaj alfortikigu la plektitajn ĉenetojn al la kadretoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Kaj faru juĝan surbrustaĵon per artista laboro; simile al la laboro de la efodo faru ĝin; el oro, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino faru ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Kvarangula ĝi estu kaj duobla; manstreĉo estu ĝia longo, kaj manstreĉo ĝia larĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Kaj enmetu en ĝin enmetaĵon el ŝtonoj en kvar vicoj. La ŝtonoj de vico: rubeno, topazo, kaj smeraldo estu la unua vico;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'kaj la dua vico: hiacinto, safiro, kaj jaspiso;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'kaj la tria vico: ligurio, agato, kaj ametisto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'kaj la kvara vico: krizolito, kaj onikso, kaj berilo. En oraj kadretoj ili estu laŭ siaj vicoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Kaj la ŝtonoj estu laŭ la nomoj de la filoj de Izrael; dek du, laŭ iliaj nomoj, gravuritaj sigelile, ĉiu kun sia nomo, por la dek du triboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Kaj faru al la surbrustaĵo plektitajn ĉenetojn, kuniĝantajn per siaj finoj, el pura oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Kaj faru por la surbrustaĵo du orajn ringojn, kaj alfortikigu la du ringojn al la du finoj de la surbrustaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Kaj metu la du orajn plektitajn ĉenetojn en la du ringojn ĉe la finoj de la surbrustaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Kaj la du finojn de la du plektitaj ĉenetoj enfortikigu en la du kadretojn, kaj alfortikigu ilin al la surŝultraĵoj de la efodo sur la antaŭa flanko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Kaj faru du orajn ringojn, kaj alfortikigu ilin al la du aliaj finoj de la surbrustaĵo, sur interna ĝia rando, direktita al la efodo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Kaj faru du orajn ringojn, kaj alfortikigu ilin al la du surŝultraĵoj de la efodo malsupre, sur la antaŭa flanko, ĉe ĝia kuniĝo, super la zono de la efodo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Kaj oni alligu la surbrustaĵon per ĝiaj ringoj al la ringoj de la efodo per laĉo el blua ŝtofo, por ke ĝi estu super la zono de la efodo kaj por ke la surbrustaĵo ne forŝoviĝu de sur la efodo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Kaj Aaron portu la nomojn de la filoj de Izrael sur la juĝa surbrustaĵo sur sia koro, kiam li eniros en la sanktejon, por ĉiama memoro antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Kaj metu sur la juĝan surbrustaĵon la signojn de lumo kaj la signojn de justo, por ke ili estu sur la koro de Aaron, kiam li eniros antaŭ la Eternulon; kaj Aaron ĉiam portu la juĝon de la filoj de Izrael sur sia koro antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Kaj faru la tunikon de la efodo tutan el blua teksaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'La aperturo por la kapo estu en ĝia mezo; ĉirkaŭ la aperturo estu teksita bordero, kiel ĉe aperturo de ŝildo, por ke ĝi ne disŝiriĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Sur ĝia malsupra rando faru granatojn el blua, purpura, kaj ruĝa teksaĵo, ĉirkaŭe sur ĝia malsupra rando, kaj inter ili ĉirkaŭe orajn tintilojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Ora tintilo kaj granato, ora tintilo kaj granato estu ĉirkaŭe sur la malsupra rando de la tuniko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Ĝi estu sur Aaron dum lia servado; por ke oni aŭdu sonon de li, kiam li eniros en la sanktejon antaŭ la Eternulon kaj kiam li eliros, kaj por ke li ne mortu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Kaj faru tabuleton el pura oro, kaj gravuru sur ĝi en sigelila maniero: SANKTA AL LA ETERNULO.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Kaj alfortikigu ĝin per laĉo el blua ŝtofo, ke ĝi estu sur la cidaro; sur la antaŭa flanko de la cidaro ĝi devas esti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Ĝi estu sur la frunto de Aaron; kaj Aaron portados la pekon kontraŭ la sanktaĵoj, kiujn sanktigos la Izraelidoj en ĉiuj siaj sanktaj donoj; kaj ĝi estos sur lia frunto ĉiam, por ke la Eternulo ilin favoru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Kaj teksu la ĥitonon el bisino, kaj faru la cidaron el bisino, kaj faru broditan zonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Kaj por la filoj de Aaron faru ĥitonojn, kaj faru por ili zonojn, kaj mitrojn faru por ili, por honoro kaj ornamo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Kaj vestu per ili vian fraton Aaron kaj liajn filojn kune kun li; kaj sanktoleu ilin kaj konsekru ilin kaj sanktigu ilin, por ke ili estu pastroj al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Kaj faru por ili linajn pantalonojn, por kovri la nudecon de ilia karno; de la lumbo ĝis la femuroj ili estu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Kaj ili estu sur Aaron kaj sur liaj filoj, kiam ili eniros en la tabernaklon de kunveno, aŭ kiam ili alproksimiĝos al la altaro, por servi en la sanktejo; por ke ili ne faru pekon kaj ne mortu. Eterna leĝo ĝi estu por li kaj por lia idaro post li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Kaj jen estas tio, kion vi devas fari al ili, por sanktigi ilin, ke ili estu pastroj al Mi: prenu unu virbovidon kaj du virŝafojn sendifektajn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'kaj macan panon, kaj macajn kukojn, miksitajn kun oleo, kaj macajn flanojn, ŝmiritajn per oleo; el delikata tritika faruno faru ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Kaj metu ilin en unu korbon, kaj venigu ilin en la korbo, kaj ankaŭ la bovidon kaj la du virŝafojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Kaj Aaronon kaj liajn filojn alvenigu al la pordo de la tabernaklo de kunveno, kaj lavu ilin per akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Kaj prenu la vestojn, kaj metu sur Aaronon la ĥitonon kaj la tunikon de la efodo kaj la efodon kaj la surbrustaĵon, kaj zonu lin per la zono de la efodo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Kaj metu la cidaron sur lian kapon, kaj metu la sanktan kronon sur la cidaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Kaj prenu la oleon de sanktoleado, kaj verŝu sur lian kapon kaj sanktoleu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Kaj liajn filojn alvenigu, kaj vestu ilin per la ĥitonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Kaj zonu ilin per zono, Aaronon kaj liajn filojn, kaj alligu sur ili mitrojn, por ke al ili apartenu la pastreco laŭ eterna leĝo; kaj konsekru Aaronon kaj liajn filojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Kaj alvenigu la bovidon antaŭ la tabernaklon de kunveno, kaj Aaron kaj liaj filoj metu siajn manojn sur la kapon de la bovido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Kaj buĉu la bovidon antaŭ la Eternulo, ĉe la pordo de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Kaj prenu iom el la sango de la bovido kaj metu per viaj fingroj sur la kornojn de la altaro, kaj la tutan ceteran sangon elverŝu ĉe la bazo de la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Kaj prenu la tutan sebon, kiu kovras la internaĵon, kaj la reton de la hepato, kaj la du renojn, kaj la sebon, kiu estas sur ili, kaj incense bruligu ilin sur la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Kaj la karnon de la bovido kaj ĝian felon kaj ĝian malpuraĵon forbruligu per fajro ekster la tendaro; ĝi estas pekofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Kaj unu virŝafon prenu, kaj Aaron kaj liaj filoj metu siajn manojn sur la kapon de la virŝafo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Kaj buĉu la virŝafon, kaj prenu ĝian sangon kaj aspergu la altaron ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Kaj la virŝafon dishaku en partojn, kaj lavu ĝian internaĵon kaj ĝiajn krurojn, kaj metu ilin sur ĝiajn partojn kaj sur ĝian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Kaj forbruligu la tutan virŝafon sur la altaro; ĝi estas brulofero por la Eternulo; agrabla odoraĵo, fajrofero por la Eternulo ĝi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Kaj prenu la duan virŝafon, kaj Aaron kaj liaj filoj metu siajn manojn sur la kapon de la virŝafo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Kaj buĉu la virŝafon, kaj prenu iom el ĝia sango kaj metu sur la malsupran randon de la dekstra orelo de Aaron kaj sur la malsupran randon de la dekstra orelo de liaj filoj kaj sur la dikan fingron de ilia dekstra mano kaj sur la dikan fingron de ilia dekstra piedo; kaj aspergu per la sango la altaron ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Kaj prenu el la sango, kiu estos sur la altaro, kaj sanktan oleon, kaj aspergu Aaronon kaj liajn vestojn kaj liajn filojn kaj la vestojn de liaj filoj kune kun li; kaj sanktiĝos li kaj liaj vestoj kaj liaj filoj kaj la vestoj de liaj filoj kune kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Kaj prenu de la virŝafo la sebon kaj la voston, kaj la sebon, kiu kovras la internaĵon, kaj la reton de la hepato, kaj la du renojn, kaj la sebon, kiu estas sur ili, kaj la dekstran femuron, ĉar tio estas virŝafo de konsekrado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'kaj unu bulon da pano kaj unu kukon kun oleo kaj unu flanon, el la korbo kun macoj, kiu staras antaŭ la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'kaj metu ĉion sur la manojn de Aaron kaj sur la manojn de liaj filoj, kaj skuu tion kiel skuoferon antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Kaj prenu tion el iliaj manoj, kaj forbruligu ĝin sur la altaro kune kun la brulofero, kiel agrablan odoraĵon antaŭ la Eternulo; ĝi estas fajrofero por la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Kaj prenu la brustaĵon de la virŝafo de konsekrado de Aaron, kaj skuu ĝin kiel skuoferon antaŭ la Eternulo; kaj tio estos via parto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Kaj sanktigu la brustaĵon de skuado kaj la femuron de levado, kiuj estis skuitaj kaj levitaj el la virŝafo de konsekrado de Aaron kaj de liaj filoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'kaj tio estu por Aaron kaj por liaj filoj porĉiama destinitaĵo de la Izraelidoj; ĉar ĝi estas levofero, kaj levofero ĝi estu de la Izraelidoj, el iliaj pacoferoj ilia levofero al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Kaj la sanktaj vestoj de Aaron estu por liaj filoj post li, por ke ili estu sanktoleataj en ili kaj por ke ili estu konsekrataj en ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Dum sep tagoj portu ilin sur si tiu el liaj filoj, kiu estos pastro anstataŭ li, kaj kiu venos en la tabernaklon de kunveno, por servi en la sanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Kaj la virŝafon de konsekrado prenu, kaj kuiru ĝian viandon sur sankta loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Kaj Aaron kaj liaj filoj manĝu la viandon de la virŝafo, kaj la panon, kiu estas en la korbo, ĉe la pordo de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Kaj ili tion manĝu, ĉar per tio ili puriĝis, por ke ili estu konsekritaj kaj por ke ili estu sanktigitaj. Laiko tion ne manĝu, ĉar tio estas sankta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Se el la viando de konsekrado kaj el la pano restos iom ĝis la mateno, tiam forbruligu la restaĵon per fajro; ĝi ne estu manĝata, ĉar ĝi estas sankta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Kaj agu kun Aaron kaj kun liaj filoj tiel, kiel Mi ĉion ordonis al vi; dum sep tagoj konsekru ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Kaj propekan bovidon oferu ĉiutage por senpekiĝo; kaj senpekigu la altaron, oferante sur ĝi, kaj oleu ĝin, por ĝin sanktigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Dum sep tagoj senpekigu la altaron kaj sanktigu ĝin; kaj la altaro fariĝu plejsanktaĵo; ĉio, kio ektuŝos la altaron, fariĝos sankta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Jen tio, kion vi metos sur la altaron: du jaraĝajn ŝafidojn ĉiutage, ĉiam;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'unu ŝafidon oferu matene, kaj la duan ŝafidon oferu ĉirkaŭ la vespero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'kaj por unu ŝafido dekonon de efo da delikata faruno, miksita kun kvarono de hino da elpistita oleo, kaj kvaronon de hino da vino por verŝoferi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'La duan ŝafidon oferu ĉirkaŭ la vespero; faru kun ĝi kiel kun la matena donofero kaj verŝofero, ke ĝi estu agrabla odoraĵo, fajrofero por la Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'ĉiama brulofero en viaj generacioj ĉe la pordo de la tabernaklo de kunveno antaŭ la Eternulo, kie Mi aperados antaŭ vi, por paroli tie kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Kaj Mi aperados tie antaŭ la Izraelidoj, kaj la loko sanktiĝos per Mia gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Kaj Mi sanktigos la tabernaklon de kunveno kaj la altaron; kaj Aaronon kaj liajn filojn Mi sanktigos, por ke ili estu Miaj pastroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Kaj Mi loĝos inter la Izraelidoj, kaj Mi estos por ili Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Kaj ili sciu, ke Mi estas la Eternulo, ilia Dio, kiu elirigis ilin el la lando Egipta, por ke Mi loĝu inter ili, Mi, la Eternulo, ilia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Kaj faru altaron, por fumigi incenson; el akacia ligno faru ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Unu ulno estu ĝia longo, kaj unu ulno ĝia larĝo; ĝi estu kvarangula; kaj du ulnoj estu ĝia alto; kornoj elstaru el ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Kaj tegu ĝin per pura oro, ĝian supran platon kaj ĝiajn flankojn ĉirkaŭe kaj ĝiajn kornojn; kaj faru al ĝi oran kronon ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Kaj du orajn ringojn faru al ĝi sub ĝia krono, sur ĝiaj du lateroj; sur du flankoj faru ilin; kaj ili estu ingoj por stangoj, per kiuj oni portu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Kaj faru la stangojn el akacia ligno, kaj tegu ilin per oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Kaj starigu ĝin antaŭ la kurteno, kiu estas antaŭ la kesto de atesto, kontraŭ la fermoplato de la kesto de atesto, kie Mi aperados al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Kaj Aaron incensadu sur ĝi aroman incenson; ĉiumatene, kiam li ordigos la lucernojn, li incensu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Kaj kiam Aaron ekbruligos la lucernojn ĉirkaŭ vespero, li incensu; ĝi estu ĉiama incensado antaŭ la Eternulo en viaj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Ne alportu sur ĝi incenson alian, nek bruloferon nek donoferon, kaj verŝoferon ne verŝu sur ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Kaj ĉiopardonan oferon Aaron alportos sur ĝiaj kornoj unu fojon en la jaro; el la sango de la ĉiopardona pekofero unu fojon en jaro li alportu sur ĝi ĉiopardonan oferon en viaj generacioj; tio estos plej granda sanktaĵo antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Kiam vi kalkulos la kapojn de la Izraelidoj, tiam ĉiu donu liberigan pagon por sia animo al la Eternulo, kiam ili estos kalkulataj; kaj tiam ne estos inter ili epidemio dum la kalkulado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Jen kion devas doni ĉiu, kiu pasas la kalkulon: duonon de siklo laŭ la grandeco de la sankta siklo (siklo enhavas dudek gerojn); duono de siklo estu oferdono por la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Ĉiu, kiu pasas la kalkulon, de la aĝo de dudek jaroj kaj pli, devas doni la oferdonon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'La riĉulo ne donu pli kaj la malriĉulo ne donu malpli ol duonon de siklo, donante la oferdonon por la Eternulo, por liberigi viajn animojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Kaj prenu la monon de la liberigo de la Izraelidoj kaj uzu ĝin por la servado en la tabernaklo de kunveno, kaj tio estos por la Izraelidoj kiel memorigaĵo antaŭ la Eternulo, por liberigi viajn animojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Faru kupran lavujon kun kupra piedestalo, por lavado; kaj starigu ĝin inter la tabernaklo de kunveno kaj la altaro, kaj enverŝu tien akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Kaj Aaron kaj liaj filoj lavu per ĝi siajn manojn kaj piedojn:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'kiam ili iros en la tabernaklon de kunveno, ili lavu sin per akvo, por ke ili ne mortu; aŭ kiam ili alproksimiĝos al la altaro, por servi, por incensi fajroferon al la Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'ili lavu siajn manojn kaj piedojn, por ke ili ne mortu; kaj tio estu por ili leĝo eterna, por li kaj por lia idaro en iliaj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Plue la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Prenu al vi plej bonajn aromaĵojn: da bonodora mirho kvincent siklojn, kaj da aroma cinamo duonon de tio, ducent kvindek, kaj da aroma kano ducent kvindek,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'kaj da kasio kvincent siklojn laŭ la mezuro de la sankta siklo, kaj da olivoleo unu hinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Kaj faru el tio oleon por sanktoleado, kunmetitan ŝmiraĵon laŭ la arto de la ŝmiraĵisto; ĝi estu oleo por sanktoleado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Kaj sanktoleu per ĝi la tabernaklon de kunveno kaj la keston de atesto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'kaj la tablon kaj ĉiujn ĝiajn apartenaĵojn, kaj la kandelabron kaj ĝiajn apartenaĵojn, kaj la altaron de incensado,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'kaj la altaron de bruloferoj kaj ĉiujn ĝiajn apartenaĵojn, kaj la lavujon kaj ĝian piedestalon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Kaj sanktigu ilin, ke ili fariĝu plejsanktaĵo; ĉiu, kiu ektuŝos ilin, sanktiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Kaj Aaronon kaj liajn filojn sanktoleu, kaj sanktigu ilin, ke ili estu Miaj pastroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Kaj al la Izraelidoj diru jene: Tio estu por Mi oleo de sanktoleado en viaj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Sur homan karnon ĝi ne estu verŝata, kaj laŭ ĝia konsisto ne faru ion similan; ĝi estas sankta, ĝi estu sankta por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Se iu konsistigos ion similan kaj ŝmiros per ĝi laikon, li ekstermiĝu el sia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Kaj la Eternulo diris al Moseo: Prenu al vi aromaĵon: balzamon kaj stakton kaj galbanon bonodoran kaj puran olibanon, po egalaj partoj el ĉio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'kaj faru el tio incensaĵon kunmetitan laŭ la arto de la ŝmiraĵisto, bone frotmiksitan, puran, sanktan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Kaj pistu el tio subtilan pulvoron, kaj metu iom el ĝi antaŭ la keston de atesto en la tabernaklo de kunveno, kie Mi aperados al vi; plejsanktaĵo ĝi estu por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Kaj laŭ la incensaĵo, kiun vi faros, ne faru al vi alian similan; sankta ĝi estu al vi por la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Se iu faros ion similan, por odorigi per ĝi, li ekstermiĝos el sia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Jen, Mi vokis per la nomo Becalelon, filon de Uri, filo de Ĥur, el la tribo de Jehuda;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'kaj Mi plenigis lin per Dia spirito, per saĝo kaj prudento kaj scio kaj ĉia arto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'por pripensi ideojn, por labori el oro kaj el arĝento kaj el kupro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'kaj por ĉizi ŝtonojn por enkadrigo, kaj por ĉizi lignon, por fari ĉian laboron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Kaj jen Mi donis al li kiel helpanton Oholiabon, filon de Aĥisamaĥ, el la tribo de Dan; kaj en la koron de ĉiu kompetentulo Mi enmetis saĝon, por ke ili faru ĉion, kion Mi ordonis al vi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'la tabernaklon de kunveno kaj la keston de atesto kaj la fermoplaton sur ĝi kaj ĉiujn apartenaĵojn de la tabernaklo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'kaj la tablon kaj ĝiajn apartenaĵojn kaj la puran kandelabron kaj ĉiujn ĝiajn apartenaĵojn kaj la altaron de incensado,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'kaj la altaron de bruloferoj kaj ĉiujn ĝiajn apartenaĵojn kaj la lavujon kaj ĝian piedestalon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'kaj la oficajn vestojn kaj la sanktajn vestojn por la pastro Aaron kaj la pastrajn vestojn de liaj filoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'kaj la sanktan oleon kaj la aroman incensaĵon por la sanktejo; ĉion konforme al tio, kiel Mi ordonis al vi, ili faros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Diru al la Izraelidoj jene: Nepre observu Miajn sabatojn; ĉar tio estas signo inter Mi kaj vi en viaj generacioj, por ke vi sciu, ke Mi estas la Eternulo, kiu vin sanktigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Kaj observu la sabaton, ĉar ĝi estas sankta por vi; kiu ĝin malsanktigos, tiu mortu; ĉar se iu faros en ĝi laboron, tiu animo ekstermiĝu el la mezo de sia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Dum ses tagoj oni faru laboron, sed la sepan tagon estas sabato de ripozo, sankta por la Eternulo; ĉiu, kiu faros laboron en la tago sabata, estu mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Kaj la Izraelidoj observu la sabaton, por fari la sabaton en siaj generacioj eterna interligo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Inter Mi kaj la Izraelidoj ĝi estu signo por ĉiam; ĉar dum ses tagoj la Eternulo faris la ĉielon kaj la teron, sed en la sepa tago Li ĉesis kaj ripozis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Kaj, fininte paroli al li sur la monto Sinaj, la Eternulo donis al Moseo du tabelojn de atesto, tabelojn ŝtonajn, skribitajn per la fingro de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Kiam la popolo vidis, ke Moseo longe ne malsuprenvenas de la monto, la popolo kolektiĝis antaŭ Aaron, kaj diris al li: Leviĝu, faru al ni diojn, kiuj irus antaŭ ni; ĉar pri tiu Moseo, la viro, kiu elkondukis nin el la lando Egipta, ni ne scias, kio fariĝis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Tiam diris al ili Aaron: Elprenu la orajn orelringojn, kiuj estas en la oreloj de viaj edzinoj, de viaj filoj, kaj de viaj filinoj, kaj alportu al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Kaj la tuta popolo elprenis la orajn orelringojn, kiuj estis en iliaj oreloj, kaj alportis al Aaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Kaj li prenis tion el iliaj manoj kaj formis ĝin per ĉizilo kaj faris el ĝi fanditan bovidon. Kaj ili diris: Jen estas viaj dioj, ho Izrael, kiuj elirigis vin el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Kiam Aaron tion vidis, li konstruis altaron antaŭ ĝi; kaj Aaron proklamis kaj diris: Morgaŭ estos festo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Kaj ili leviĝis frue la sekvantan tagon kaj oferis bruloferojn kaj alportis pacoferojn; kaj la popolo sidiĝis, por manĝi kaj trinki, kaj ili leviĝis, por ludi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Tiam la Eternulo diris al Moseo: Iru, iru malsupren; ĉar malvirtiĝis via popolo, kiun vi elkondukis el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Rapide ili forflankiĝis de la vojo, kiun Mi ordonis al ili; ili faris al si fanditan bovidon kaj adorkliniĝis al ĝi kaj alportis al ĝi oferojn, kaj diris: Jen estas viaj dioj, ho Izrael, kiuj elirigis vin el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Kaj la Eternulo diris al Moseo: Mi vidas ĉi tiun popolon, ĝi estas popolo malmolnuka.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Lasu do Min, kaj ekflamos Mia kolero kontraŭ ilin, kaj Mi ilin ekstermos, kaj Mi faros vin granda popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Sed Moseo ekpetegis la Eternulon, sian Dion, kaj diris: Por kio, ho Eternulo, Via kolero estas ekflamonta kontraŭ Vian popolon, kiun Vi elirigis el la lando Egipta per granda forto kaj per potenca mano?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Por kio la Egiptoj diru: Por malbono Li elirigis ilin, por mortigi ilin en la montoj kaj por ekstermi ilin de sur la tero? Forlasu Vian flaman koleron kaj fordecidu la malbonon kontraŭ Via popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Rememoru Abrahamon, Isaakon, kaj Izraelon, Viajn sklavojn, al kiuj Vi ĵuris per Vi, kaj al kiuj Vi diris: Mi multigos vian semon kiel la steloj de la ĉielo, kaj la tutan tiun landon, pri kiu Mi parolis, Mi donos al viaj idoj, kaj ili posedos ĝin eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Kaj la Eternulo fordecidis la malbonon, pri kiu Li diris, ke Li faros ĝin al Sia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Moseo sin returnis kaj malsupreniris de la monto, kaj la du tabeloj de atesto estis en liaj manoj, tabeloj, sur kiuj estis skribite ambaŭflanke; sur unu flanko kaj sur la alia estis skribite sur ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Kaj la tabeloj estis faritaĵo de Dio, kaj la skribo estis skribo de Dio, gravurita sur la tabeloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Kaj Josuo aŭdis la bruon de la popolo ĝojkrianta, kaj li diris al Moseo: Bruo de batalo estas en la tendaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Sed tiu diris: Tio ne estas kriado de venko, nek kriado de malvenko, sed bruon de kantantoj mi aŭdas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Kiam li alproksimiĝis al la tendaro kaj ekvidis la bovidon kaj la dancadon, tiam ekflamis la kolero de Moseo, kaj li forĵetis el siaj manoj la tabelojn kaj disrompis ilin sub la monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Kaj li prenis la bovidon, kiun ili faris, kaj disbruligis ĝin per fajro kaj disfrakasis ĝis pulvoreco kaj disŝutis sur akvo kaj trinkigis ĝin al la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Kaj Moseo diris al Aaron: Kion faris al vi ĉi tiu poplo, ke vi venigis sur ĝin grandan pekon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Kaj Aaron diris: Ne ekflamu la kolero de mia sinjoro; vi scias, ke la popolo havas inklinon al malbono;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'ili diris al mi: Faru al ni diojn, kiuj irus antaŭ ni; ĉar pri tiu Moseo, la viro, kiu elkondukis nin el la lando Egipta, ni ne scias, kio fariĝis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Kaj mi diris al ili: Kiu havas oron, tiu deprenu ĝin; kaj ili donis al mi, kaj mi ĵetis ĝin en fajron, kaj eliris ĉi tiu bovido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Ĉar Moseo vidis, ke la popolo estas sendisciplina, ĉar Aaron sendisciplinigis ĝin ĝis honto antaŭ la malamikoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'tial Moseo stariĝis ĉe la pordego de la tendaro, kaj diris: Kiu estas partiano de la Eternulo, tiu venu al mi. Kaj kolektiĝis al li ĉiuj idoj de Levi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Kaj li diris al ili: Tiel diris la Eternulo, la Dio de Izrael: Metu ĉiu sian glavon sur sian femuron, trairu tien kaj reen de pordego ĝis pordego tra la tendaro, kaj ĉiu mortigu sian fraton, sian amikon, sian proksimulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Kaj la idoj de Levi faris, kiel diris Moseo; kaj estis mortigitaj el la popolo en tiu tago ĉirkaŭ tri mil homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Kaj Moseo diris: Konsekru vin hodiaŭ al la Eternulo, ĉiu sur sia filo kaj sur sia frato, por ke estu donata al vi hodiaŭ beno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'La sekvantan tagon Moseo diris al la popolo: Vi pekis per granda peko; nun mi supreniros al la Eternulo, eble mi akiros pardonon por via peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Kaj Moseo revenis al la Eternulo, kaj diris: Ho ve! tiu popolo pekis per granda peko kaj faris al si orajn diojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'nun volu pardoni ilian pekon; kaj se ne, tiam volu elstreki min el Via libro, kiun Vi skribis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Sed la Eternulo diris al Moseo; Kiu ajn pekis antaŭ Mi, tiun Mi elstrekos el Mia libro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Kaj nun iru, konduku la popolon tien, kien Mi diris al vi. Jen Mia anĝelo iros antaŭ vi; kaj en la tago de Mia rememorigado Mi rememorigos sur ili ilian pekon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Kaj la Eternulo frapis la popolon pro tio, ke ili faris la bovidon, kiun faris Aaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Kaj la Eternulo diris al Moseo: Iru, eliru el ĉi tie, vi kaj la popolo, kiun vi elkondukis el la lando Egipta, al la lando, pri kiu Mi ĵuris al Abraham, al Isaak, kaj al Jakob, dirante: Al via idaro Mi ĝin donos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Kaj Mi sendos antaŭ vi anĝelon, kaj Mi forpelos la Kanaanidojn, la Amoridojn kaj la Ĥetidojn kaj la Perizidojn, la Ĥividojn kaj la Jebusidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'Iru al lando, en kiu fluas lakto kaj mielo. Mi ne iros meze de vi; ĉar vi estas popolo malmolnuka, kaj Mi eble ekstermus vin dum la vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Kaj la popolo aŭdis tiun malbonan sciigon, kaj ili ekfunebris, kaj neniu metis sur sin siajn ornamaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Kaj la Eternulo diris al Moseo: Diru al la Izraelidoj: Vi estas popolo malmolnuka; se Mi nur unu momenton irus meze de vi, Mi vin ekstermus; nun demetu de vi viajn ornamaĵojn, kaj Mi rigardos, kion Mi faru kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Kaj la Izraelidoj demetis de si siajn ornamaĵojn antaŭ la monto Ĥoreb.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Moseo prenis la tabernaklon, kaj starigis ĝin ekster la tendaro, malproksime de la tendaro, kaj nomis ĝin Tabernaklo de Kunveno; kaj ĉiu, kiu volis peti la Eternulon, devis eliri al la tabernaklo de kunveno, kiu estis ekstere de la tendaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Kaj kiam Moseo eliradis al la tabernaklo, la tuta popolo leviĝadis, kaj ĉiu stariĝadis ĉe la pordo de sia tendo kaj rigardadis post Moseo, ĝis li eniris en la tabernaklon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Kaj kiam Moseo eniradis en la tabernaklon, malleviĝadis nuba kolono kaj stariĝadis ĉe la pordo de la tabernaklo kaj paroladis kun Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Kaj la tuta popolo vidadis la nuban kolonon, kiu staris ĉe la pordo de la tabernaklo; kaj la tuta popolo leviĝadis kaj adorkliniĝadis ĉiu ĉe la pordo de sia tendo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Kaj la Eternulo paroladis kun Moseo vizaĝon kontraŭ vizaĝo, kiel parolas homo kun sia amiko. Kaj kiam li reiradis en la tendaron, tiam lia servanto Josuo, filo de Nun, junulo, ne foriĝadis el la tabernaklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Kaj Moseo diris al la Eternulo: Vidu, Vi diras al mi: Konduku ĉi tiun popolon; kaj Vi ne sciigis al mi, kiun Vi sendos kun mi, kvankam Vi diris: Mi konas vin laŭ via nomo, kaj vi akiris Mian favoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Nun, se mi akiris Vian favoron, volu sciigi al mi Vian vojon, por ke mi konu Vin, por akiri Vian favoron; kaj vidu, ke ĉi tiu popolo estas Via popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Tiam Li diris: Mia vizaĝo iros antaŭe, kaj Mi donos al vi ripozon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Kaj li diris al Li: Se Via vizaĝo ne iros, tiam ne forkonduku nin de ĉi tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Per kio do montriĝos, ke mi kaj Via popolo akiris Vian favoron? ĉu ne per tio, ke Vi irados kun ni? tiam mi kaj Via popolo distingiĝos de ĉiu popolo, kiu estas sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Kaj la Eternulo diris al Moseo: Ankaŭ tion, kion vi diris, Mi faros; ĉar vi akiris Mian favoron kaj Mi konas vin laŭ via nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Kaj li diris: Volu montri al mi Vian gloron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Kaj Li diris: Mi preterpasigos antaŭ vi Mian tutan bonecon, kaj Mi alvokos la nomon de la Eternulo antaŭ vi; kaj Mi favorkoros tiun, kiun Mi favorkoros, kaj Mi kompatos tiun, kiun Mi kompatos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Kaj Li diris: Vi ne povas vidi Mian vizaĝon, ĉar ne povas homo vidi Min kaj resti viva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Kaj la Eternulo diris: Jen estas loko ĉe Mi; stariĝu sur la roko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Kaj kiam preteriros Mia gloro, Mi metos vin en fendon de la roko, kaj Mi ŝirmos vin per Mia mano, ĝis Mi pasos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Kaj kiam Mi formetos Mian manon, vi vidos Mian malantaŭan flankon, sed Mia vizaĝo ne estos videbla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Kaj la Eternulo diris al Moseo: Skulptu al vi du ŝtonajn tabelojn kiel la unuaj; kaj Mi skribos sur la tabeloj la vortojn, kiuj estis sur la unuaj tabeloj, kiujn vi rompis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Kaj estu preta por la mateno, kaj supreniru matene sur la monton Sinaj kaj stariĝu antaŭ Mi tie sur la pinto de la monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Kaj neniu supreniru kun vi, kaj ankaŭ neniu montriĝu sur la tuta monto; eĉ ŝafo aŭ bovo ne paŝtiĝu antaŭ tiu monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Kaj li skulptis du ŝtonajn tabelojn kiel la unuaj; kaj Moseo leviĝis frue matene kaj supreniris sur la monton Sinaj, kiel ordonis al li la Eternulo, kaj li prenis en siajn manojn la du ŝtonajn tabelojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Kaj la Eternulo malleviĝis en nubo, kaj Moseo stariĝis apud Li tie kaj alvokis la nomon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Kaj la Eternulo preteriris antaŭ li, kaj li ekkriis: Eternulo, Eternulo, Dio indulgema kaj kompatema, multepacienca, favorkora, kaj verema;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'kiu konservas favorkorecon por miloj, pardonas kulpon kaj krimon kaj pekon, sed antaŭ kiu neniu estas senkulpa; kiu punas la kulpon de patroj sur filoj kaj nepoj, en la tria kaj kvara generacioj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Kaj rapide Moseo kliniĝis ĝis la tero kaj faris adoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'Kaj li diris: Ho, se mi akiris Vian favoron, mia Sinjoro, tiam mia Sinjoro volu iri en nia mezo, ĉar tio estas popolo malmolnuka; kaj pardonu niajn kulpojn kaj niajn pekojn kaj faru nin Via posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Kaj Li diris: Jen Mi faros interligon; antaŭ via tuta popolo Mi faros miraklojn, kiuj neniam ekzistis sur la tuta tero nek ĉe iuj gentoj; kaj la tuta popolo, en kies mezo vi estas, vidos la faron de la Eternulo; ĉar terura estos tio, kion Mi faros por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Observu tion, kion Mi ordonas al vi hodiaŭ. Jen Mi forpelas antaŭ vi la Amoridojn kaj la Kanaanidojn kaj la Ĥetidojn kaj la Perizidojn kaj la Ĥividojn kaj la Jebusidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Gardu vin, ke vi ne faru interligon kun la loĝantoj de la lando, en kiun vi venos, por ke tio ne fariĝu falilo inter vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'sed iliajn altarojn detruu kaj iliajn statuojn rompu kaj iliajn sanktajn stangojn dishaku.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Ĉar vi ne devas adori alian dion; ĉar la Eternulo, koleremulo estas Lia nomo, estas Dio kolerema.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Ne faru interligon kun la loĝantoj de la lando; ĉar, malĉastante kun siaj dioj kaj alportante oferojn al siaj dioj, ili eble vokos vin kaj vi manĝos de iliaj oferoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'kaj vi prenos iliajn filinojn por viaj filoj, kaj iliaj filinoj malĉastos por siaj dioj kaj malĉastigos viajn filojn por siaj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Diojn fanditajn ne faru al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'La feston de macoj observu; dum sep tagoj manĝu macojn, kiel Mi ordonis al vi, en la difinita tempo de la monato Abib, ĉar en la monato Abib vi eliris el Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Ĉio, kio malfermas unue la uteron, apartenas al mi; ĉiu virseksulo el viaj brutoj, kiu malfermas unue la uteron, bovo aŭ ŝafo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Utermalferminton el azenoj elaĉetu per ŝafido: kaj se vi ne elaĉetos, tiam rompu al ĝi la kolon. La unuenaskiton el viaj filoj elaĉetu. Kaj oni ne montriĝu antaŭ Mi kun malplenaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Dum ses tagoj laboru, kaj en la sepa tago ripozu; en la tempo de la plugado kaj de la rikoltado ripozu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Kaj feston de semajnoj faru al vi en la komenco de la rikoltado de tritiko, kaj feston de kolektado de fruktoj en la fino de la jaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Tri fojojn en la jaro ĉiuj viaj virseksuloj aperu antaŭ la Sinjoro, la Eternulo, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Ĉar Mi forpelos gentojn antaŭ vi kaj vastigos viajn limojn, kaj neniu deziros havi vian landon, kiam vi iros, por montriĝi antaŭ la Eternulo, via Dio, tri fojojn en la jaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Ne buĉverŝu sur fermentintaĵon la sangon de Mia ofero, kaj ne devas resti ĝis mateno la ofero de la festo de Pasko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'La komencaĵon de la unuaj produktoj de via tero alportu en la domon de la Eternulo, via Dio. Ne kuiru kapridon en la lakto de ĝia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Kaj la Eternulo diris al Moseo: Skribu al vi ĉi tiujn vortojn, ĉar laŭ ĉi tiuj vortoj Mi faris interligon kun vi kaj kun Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Kaj li estis tie kun la Eternulo kvardek tagojn kaj kvardek noktojn; panon li ne manĝis kaj akvon li ne trinkis; kaj li skribis sur la tabeloj la vortojn de la interligo, la dek ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Kiam Moseo estis malsupreniranta de la monto Sinaj kaj la du tabeloj de atesto estis en la manoj de Moseo dum lia malsuprenirado de la monto, Moseo ne sciis, ke la haŭto de lia vizaĝo lumradiis pro tio, ke li parolis kun Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Kaj Aaron kaj ĉiuj Izraelidoj ekvidis Moseon, kaj jen la haŭto de lia vizaĝo lumradias; kaj ili timis alproksimiĝi al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Sed Moseo vokis ilin, kaj returniĝis al li Aaron kaj ĉiuj ĉefoj de la komunumo, kaj Moseo ekparolis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Poste alproksimiĝis ĉiuj Izraelidoj; kaj li ordonis al ili ĉion, kion diris al li la Eternulo sur la monto Sinaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Kiam Moseo ĉesis paroli al ili, li metis sur sian vizaĝon kovrotukon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Kiam Moseo venadis antaŭ la Eternulon, por paroli kun Li, li formetadis la kovrotukon ĝis sia eliro; kaj elirinte, li diradis al la Izraelidoj tion, kio estis ordonita al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Kaj la Izraelidoj vidis, ke la haŭto de la vizaĝo de Moseo lumradias; kaj tiam Moseo denove metis la kovrotukon sur sian vizaĝon, ĝis li eniris, por paroli kun Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Kaj Moseo kunvenigis la tutan komunumon de la Izraelidoj, kaj diris al ili: Jen kion la Eternulo ordonis al vi fari:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Dum ses tagoj faru laboron, sed la sepa tago estu por vi sankta, sabato de ripozo al la Eternulo; ĉiu, kiu faros en ĝi laboron, estu mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Ne bruligu fajron en ĉiuj viaj loĝejoj en la tago sabata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Kaj Moseo ekparolis al la tuta komunumo de la Izraelidoj, dirante: Jen kion ordonis la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Prenu inter vi oferdonon por la Eternulo: ĉiu memvole alportu la oferdonon por la Eternulo: oron kaj arĝenton kaj kupron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'kaj bluan teksaĵon kaj purpuran kaj ruĝan, kaj bisinon kaj kapran lanon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'kaj virŝafajn felojn ruĝe kolorigitajn, kaj antilopajn felojn, kaj akacian lignon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'kaj oleon por lumigado, kaj aromaĵojn por la sankta oleo kaj por la bonodoraj incensoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'kaj ŝtonojn oniksajn kaj ŝtonojn enkadrigeblajn por la efodo kaj por la surbrustaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Kaj ĉiu el vi, kiu estas kompetentulo, venu kaj faru ĉion, kion ordonis la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'la tabernaklon kaj ĝian tendon kaj ĝian kovron, ĝiajn hoketojn kaj ĝiajn tabulojn, ĝiajn riglilojn, ĝiajn kolonojn kaj ĝiajn bazojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'la keston kaj ĝiajn stangojn, la fermoplaton kaj la kurtenon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'la tablon kaj ĝiajn stangojn kaj ĉiujn ĝiajn apartenaĵojn kaj la panojn de propono;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'kaj la kandelabron por lumigi kaj ĝiajn apartenaĵojn kaj ĝiajn lucernojn kaj la oleon por lumigi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'kaj la altaron de incensado kaj ĝiajn stangojn kaj la sanktan oleon kaj la bonodoran incenson kaj la pordan kovrotukon antaŭ la pordo de la tabernaklo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'la altaron de bruloferoj kaj ĝian kupran kradon, ĝiajn stangojn kaj ĉiujn ĝiajn apartenaĵojn, la lavujon kaj ĝian piedestalon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'la kurtenojn de la korto, ĝiajn kolonojn kaj bazojn kaj la kovrotukon de la pordego de la korto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'la najlojn de la tabernaklo kaj la najlojn de la korto kaj iliajn ŝnurojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'la oficajn vestojn por servado en la sanktejo, la sanktajn vestojn por la pastro Aaron kaj la pastrajn vestojn de liaj filoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Kaj la tuta komunumo de la Izraelidoj eliris de antaŭ Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Kaj venis ĉiuj homoj, kiujn tiris la koro; kaj ĉiu, kiun inklinigis lia spirito, alportis la oferdonon por la Eternulo, por la aranĝo de la tabernaklo de kunveno kaj por ĝia tuta servado kaj por la sanktaj vestoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Kaj venis la viroj kaj la virinoj; ĉiuj, kiujn inklinigis la koro, alportis bukojn kaj orelringojn kaj ringojn kaj kolringojn, diversajn orajn objektojn; kaj ĉiu alportis oran oferdonon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Kaj ĉiu, ĉe kiu troviĝis blua teksaĵo, aŭ purpura, aŭ ruĝa, aŭ bisino, aŭ kapra lano, aŭ ŝafaj feloj ruĝaj, aŭ antilopaj feloj, alportis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Ĉiu, kiu oferis arĝenton aŭ kupron, alportis la oferdonon por la Eternulo; kaj ĉiu, ĉe kiu troviĝis akacia ligno por ĉia bezono de la servado, alportis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Kaj ĉiu virino, kiu havis ian kompetentecon, ŝpinis kaj alportis ŝpinitan lanon bluan kaj purpuran kaj ruĝan kaj bisinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Kaj ĉiuj virinoj, kiuj havis deziron kaj kompetentecon, ŝpinis kapran lanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Kaj la princoj alportis ŝtonojn oniksajn kaj ŝtonojn enkadrigeblajn por la efodo kaj por la surbrustaĵo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'kaj la aromaĵon kaj la oleon por lumigi kaj por la sankta oleo kaj por la bonodoraj incensoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Ĉiu viro kaj virino el la Izraelidoj, kiujn inklinigis ilia koro alporti por ĉia laboro, kiun la Eternulo per Moseo ordonis fari, alportis oferon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Kaj Moseo diris al la Izraelidoj: Jen, la Eternulo vokis per la nomo Becalelon, filon de Uri, filo de Ĥur, el la tribo de Jehuda;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'kaj Li plenigis lin per Dia spirito, per saĝo kaj prudento, kaj scio kaj per ĉia arto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'por pripensi ideojn, por labori el oro kaj el arĝento kaj el kupro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'kaj por ĉizi ŝtonojn por enkadrigo, kaj por ĉizi lignon, por fari ĉian artistan laboron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Kaj Li donis al li la kapablon instrui, al li kaj al Oholiab, filo de Aĥisamaĥ, el la tribo de Dan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Li plenigis ilin per kompetenteco por farado de ĉia majstra laboro, por ĉia talenta brodado sur teksaĵo blua kaj purpura kaj ruĝa kaj sur bisino, por teksado de ĉia laboraĵo kaj pripensado de ideoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Kaj laboros Becalel kaj Oholiab kaj ĉiuj kompetentuloj, en kiujn la Eternulo enmetis saĝon kaj prudenton, por ke ili sciu fari ĉiun laboron por la servado en la sanktejo, laŭ ĉio, kion ordonis la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Kaj Moseo alvokis Becalelon kaj Oholiabon, kaj ĉiun kompetentulon, al kiu la Eternulo enmetis saĝon en la koron, ĉiun, kiun tiris lia koro entrepreni la laboron kaj fari ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Kaj ili prenis de Moseo ĉiujn oferdonojn, kiujn alportis la Izraelidoj por la bezonoj de la servado en la sanktejo, por ellabori ilin. Kaj tiuj alportadis al li ankoraŭ plue oferdonojn ĉiumatene.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Kaj venis ĉiuj saĝuloj, kiuj estis farantaj la tutan laboron por la sanktejo, ĉiu venis de sia laboro, kiun li faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'Kaj ili diris al Moseo jene: La popolo alportas pli multe, ol bezonas la laboroj, kiujn la Eternulo ordonis fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Tiam Moseo ordonis, kaj oni elkriis en la tendaro jene: Neniu viro kaj neniu virino faru plue laboraĵon, por oferdoni al la sanktejo. Kaj la popolo ĉesis alporti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Kaj la alportitaĵo estis sufiĉa por la tuta farota laboro, kaj eĉ superflua.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Kaj ĉiuj kompetentuloj inter tiuj, kiuj estis farantaj la laboron por la tabernaklo, faris dek tapiŝojn el tordita bisino kaj el blua, purpura, kaj ruĝa teksaĵo; kerubojn artiste laboritajn ili faris sur ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'La longo de ĉiu tapiŝo estis dudek ok ulnoj, kaj la larĝo de ĉiu tapiŝo estis kvar ulnoj; unu mezuro estis por ĉiuj tapiŝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Kaj li kunigis kvin tapiŝojn unu kun la alia, kaj la kvin ceterajn ankaŭ unu kun la alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Kaj li faris maŝojn el blua teksaĵo sur la rando de unu tapiŝo, sur la rando de la kuniĝo; tiel same li faris sur la rando de la ekstrema tapiŝo, sur la dua rando de kuniĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Kvindek maŝojn li faris sur unu tapiŝo, kaj kvindek maŝojn li faris sur la rando de tiu tapiŝo, sur kiu estis la dua flanko de la kuniĝo; la maŝoj estis reciproke aranĝitaj unu kontraŭ alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Kaj li faris kvindek orajn hoketojn, kaj li kunigis la tapiŝojn unu kun la alia per la hoketoj; kaj la tabernaklo fariĝis unu tutaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Kaj li faris tapiŝojn el kapra lano kiel kovron super la tabernaklo; dek unu tiajn tapiŝojn li faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'La longo de ĉiu tapiŝo estis tridek ulnoj, kaj kvar ulnoj estis la larĝo de ĉiu tapiŝo; unu mezuro estis por la dek unu tapiŝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Kaj li kunigis kvin tapiŝojn aparte kaj la ceterajn ses tapiŝojn aparte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Kaj li faris kvindek maŝojn sur la rando de la ekstrema tapiŝo, sur la rando de la kuniĝo, kaj kvindek maŝojn li faris sur la rando de la dua kuniĝa tapiŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Kaj li faris kvindek kuprajn hoketojn, por kunigi la tendon, por ke ĝi estu unu tutaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Kaj li faris kovron por la tendo el ruĝaj virŝafaj feloj kaj ankoraŭ kovron el antilopaj feloj supre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Kaj li faris la tabulojn por la tabernaklo, starantajn, el akacia ligno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Dek ulnoj estis la longo de ĉiu tabulo, kaj unu ulno kaj duono la larĝo de ĉiu tabulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Ĉiu tabulo havis du pivotojn, alĝustigitajn unu al la alia; tiel li faris ĉe ĉiuj tabuloj de la tabernaklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Kaj li faris la tabulojn por la tabernaklo; dudek tabulojn sur la flanko suda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'Kaj kvardek arĝentajn bazojn li faris sub la dudek tabuloj, du bazojn sub ĉiu tabulo, por ĝiaj du pivotoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Kaj sur la dua flanko de la tabernaklo, sur la flanko norda, li faris dudek tabulojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'kaj kvardek arĝentajn bazojn por ili, du bazojn sub ĉiu tabulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Kaj sur la malantaŭa flanko de la tabernaklo, okcidente, li faris ses tabulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Kaj du tabulojn li faris en la anguloj de la tabernaklo sur la malantaŭa flanko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Kaj ili estis kunigitaj malsupre kaj kunigitaj supre per unu ringo; tiel li faris kun ambaŭ en la du anguloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Kaj estis ok tabuloj, kaj ĉe ili dek ses arĝentaj bazoj, po du bazoj sub ĉiu tabulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Kaj li faris riglilojn el akacia ligno: kvin por la tabuloj de unu flanko de la tabernaklo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'kaj kvin riglilojn por la tabuloj de la dua flanko de la tabernaklo, kaj kvin riglilojn por la tabuloj de la malantaŭa flanko de la tabernaklo, okcidente.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Kaj li faris mezan riglilon, kiu ŝoviĝis meze de la tabuloj de unu fino ĝis la alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Kaj la tabulojn li tegis per oro, kaj iliajn ringojn, ingojn por la rigliloj, li faris el oro, kaj la riglilojn li tegis per oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Kaj li faris la kurtenon el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino; per artista laboro li faris sur ĝi kerubojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Kaj li faris por ĝi kvar kolonojn el akacia ligno, kaj li tegis ilin per oro, kaj iliaj hoketoj estis el oro; kaj li fandis por ili kvar arĝentajn bazojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Kaj li faris kovrotukon por la pordo de la tabernaklo, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino, kun brodaĵoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'kaj kvin kolonojn por ĝi kun iliaj hoketoj; kaj li tegis iliajn kapojn kaj ligaĵojn per oro; kaj por ili kvin kuprajn bazojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Kaj Becalel faris la keston el akacia ligno; du ulnoj kaj duono estis ĝia longo, kaj unu ulno kaj duono ĝia larĝo, kaj unu ulno kaj duono ĝia alto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Kaj li tegis ĝin per pura oro interne kaj ekstere, kaj li faris al ĝi oran kronon ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Kaj li fandis por ĝi kvar orajn ringojn sur ĝiaj kvar anguloj: du ringojn sur unu ĝia flanko kaj du ringojn sur ĝia alia flanko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Kaj li faris stangojn el akacia ligno kaj tegis ilin per oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'Kaj li metis la stangojn en la ringojn sur la flankoj de la kesto, por porti la keston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Kaj li faris fermoplaton el pura oro; du ulnoj kaj duono estis ĝia longo, kaj unu ulno kaj duono ĝia larĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Kaj li faris du kerubojn el oro; per forĝa laboro li faris ilin, sur la du randoj de la fermoplato:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'unu kerubon ĉe unu flanko kaj la duan kerubon ĉe la dua flanko; elstarantaj el la fermoplato li faris la kerubojn, sur ĝiaj du flankoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Kaj la keruboj estis etendantaj siajn flugilojn supren, kovrante per siaj flugiloj la fermoplaton, kaj iliaj vizaĝoj estis unu kontraŭ la alia; al la fermoplato estis turnitaj la vizaĝoj de la keruboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Kaj li faris la tablon el akacia ligno; du ulnoj estis ĝia longo, kaj unu ulno ĝia larĝo, kaj unu ulno kaj duono ĝia alto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Kaj li tegis ĝin per pura oro, kaj li faris al ĝi oran kronon ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Kaj li faris ĉirkaŭ ĝi manlarĝan listelon, kaj li faris oran kronon ĉirkaŭ la listelo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Kaj li fandis por ĝi kvar orajn ringojn, kaj li alfortikigis la ringojn sur la kvar anguloj, ĉe ĝiaj kvar piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Apud la listelo estis la ringoj, kiel ingoj por la stangoj, por porti la tablon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Kaj li faris la stangojn el akacia ligno, kaj li tegis ilin per oro, por porti la tablon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Kaj ankaŭ la vazojn por la tablo, ĝiajn pladojn kaj ĝiajn kulerojn, kaj ĝiajn kruĉojn kaj la kalikojn, per kiuj oni verŝas, li faris el pura oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Kaj li faris la kandelabron el pura oro, per forĝa laboro li faris la kandelabron; ĝia trunko kaj ĝiaj branĉoj, ĝiaj kalikoj, ĝiaj kapetoj, kaj ĝiaj floroj elstaris el ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Kaj ses branĉoj elstaris el ĝiaj flankoj: tri branĉoj de la kandelabro el unu flanko, kaj tri branĉoj de la kandelabro el la dua flanko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'tri migdalformaj kalikoj, kapeto, kaj floro estis sur unu branĉo, kaj tri migdalformaj kalikoj, kapeto, kaj floro sur la dua branĉo; tiel estis sur la ses branĉoj, kiuj elstaris el la kandelabro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Kaj sur la kandelabro estis kvar migdalformaj kalikoj kun siaj kapetoj kaj floroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'Kaj kapeto estis sub unu paro da branĉoj, kaj kapeto sub la dua paro da branĉoj, kaj kapeto sub la tria paro da branĉoj; tiel estis ĉe la ses branĉoj, kiuj elstaris el ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'La kapetoj kaj branĉoj elstaris el ĝi; ĉio estis unu forĝita tutaĵo el pura oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Kaj li faris ĝiajn sep lucernojn kaj ĝiajn prenilojn kaj cindrujojn el pura oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'El kikaro da pura oro li faris ĝin kaj ĉiujn ĝiajn apartenaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Kaj li faris la altaron por la incensado el akacia ligno; unu ulno estis ĝia longo, kaj unu ulno ĝia larĝo; kvarangula ĝi estis; du ulnoj estis ĝia alto; el ĝi elstaris ĝiaj kornoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Kaj li tegis ĝin per pura oro, ĝian supran platon kaj ĝiajn muretojn ĉirkaŭe kaj ĝiajn kornojn; kaj li faris al ĝi oran kronon ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Kaj du orajn ringojn li faris al ĝi sub ĝia krono, sur ĝiaj du flankoj, kiel ingojn por stangoj, per kiuj oni portu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Kaj li faris la stangojn el akacia ligno kaj tegis ilin per oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Kaj li faris la oleon por la sanktoleado kaj la puran bonodoran incenson laŭ la arto de ŝmiraĵisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Kaj li faris la altaron por la bruloferoj el akacia ligno; kvin ulnoj estis ĝia longo, kaj kvin ulnoj ĝia larĝo; kvarangula ĝi estis; kaj tri ulnoj estis ĝia alto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Kaj li faris ĝiajn kornojn sur ĝiaj kvar anguloj; el ĝi elstaris ĝiaj kornoj; kaj li tegis ĝin per kupro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Kaj li faris ĉiujn vazojn de la altaro; la potojn, la ŝovelilojn, la kalikojn, la forkojn, la karbujojn; ĉiujn ĝiajn vazojn li faris el kupro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Kaj li faris por la altaro kradon en formo de kupra reto, sub ĝia kornico, malsupre, ĝis la mezo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Kaj li fandis kvar ringojn en la kvar anguloj de la kupra krado, ke ili estu ingoj por la stangoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Kaj li faris la stangojn el akacia ligno kaj tegis ilin per kupro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Kaj li metis la stangojn en la ringojn sur la flankoj de la altaro, por ke oni povu porti ĝin per ili; li faris ĝin interne malplena, el tabuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Kaj li faris la lavujon el kupro kaj ĝian piedestalon el kupro, el la speguloj de la virinoj, kiuj kolektiĝis amase antaŭ la pordo de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Kaj li faris la korton: sur la flanko suda estis la kurtenoj de la korto el tordita bisino, cent ulnoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'kaj al ili dudek kolonoj kun dudek kupraj bazoj; la hokoj de la kolonoj kaj iliaj ligaĵoj estis el arĝento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Kaj sur la norda flanko ankaŭ cent ulnoj, kaj al ili dudek kolonoj kaj dudek kupraj bazoj; la hokoj de la kolonoj kaj iliaj ligaĵoj estis el arĝento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Kaj sur la okcidenta flanko estis kurtenoj de kvindek ulnoj, kaj al ili dek kolonoj kun dek bazoj; la hokoj de la kolonoj kaj iliaj ligaĵoj estis el arĝento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Kaj sur la orienta flanko kvindek ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Kurtenoj de dek kvin ulnoj sur unu latero, kaj al tio tri kolonoj kun tri bazoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'Kaj sur la dua latero, sur ambaŭ flankoj de la pordego de la korto estis kurtenoj po dek kvin ulnoj, kaj al ili po tri kolonoj kun tri bazoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Ĉiuj kurtenoj de la korto ĉirkaŭe estis el tordita bisino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Kaj la bazoj de la kolonoj estis el kupro, la hokoj de la kolonoj kaj iliaj ligaĵoj el arĝento, kaj iliaj kapoj estis tegitaj per arĝento, kaj ĉiuj kolonoj de la korto estis kunigitaj per arĝentaj ligaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Kaj la kovrotuko de la pordego de la korto estis brodita laboraĵo el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino; kaj dudek ulnoj estis ĝia longo, kaj kvin ulnoj ĝia larĝo, laŭ la mezuro de la kurtenoj de la korto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Kaj al ĝi apartenis kvar kolonoj kun kvar kupraj bazoj; iliaj hokoj estis el arĝento, iliaj kapoj estis tegitaj per arĝento, kaj iliaj ligaĵoj estis el arĝento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Kaj ĉiuj najloj en la tabernaklo kaj en la korto ĉirkaŭe estis el kupro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Jen estas la kalkulo pri la tabernaklo, la tabernaklo de atesto, kiu estis kalkulita laŭ la ordono de Moseo, por la servo de la Levidoj, sub la kontrolo de Itamar, filo de la pastro Aaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Kaj Becalel, filo de Uri, filo de Ĥur, el la tribo de Jehuda, faris ĉion, kion ordonis la Eternulo al Moseo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'kaj kun li Oholiab, filo de Aĥisamaĥ, el la tribo de Dan, artista skulptisto, teksisto, kaj brodisto sur blua, purpura, kaj ruĝa teksaĵo, kaj sur bisino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'La tuta oro, kiu estis uzita por ĉiuj laboroj de la sanktejo, la oro, kiu estis alportita kiel oferdonoj, prezentis la kvanton de dudek naŭ kikaroj kaj sepcent tridek sikloj laŭ la mezuro de la sankta siklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Kaj la arĝento, akirita per la kalkulado de la komunumo, prezentis la kvanton de cent kikaroj kaj mil sepcent sepdek kvin sikloj laŭ la sankta siklo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'po unu bek�o, tio estas po duono de siklo laŭ la sankta siklo, por ĉiu kapo, de ĉiuj, kiuj trapasis la kalkulon, kiuj havis la aĝon de dudek jaroj kaj pli, de sescent tri mil kvincent kvindek homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Cent kikaroj da arĝento estis uzitaj por elfandi la bazojn de la sanktejo kaj la bazojn de la kurteno; cent bazoj el cent kikaroj, po unu kikaro por bazo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Kaj el mil sepcent sepdek kvin sikloj estis faritaj hokoj por la kolonoj kaj estis tegitaj iliaj kapoj kaj estis faritaj ligaĵoj inter ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Kaj da oferdonita kupro estis sepdek kikaroj kaj du mil kvarcent sikloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Kaj li faris el ĝi la bazojn por la pordo de la tabernaklo de kunveno kaj la kupran altaron kaj la kupran kradon por ĝi kaj ĉiujn apartenaĵojn de la altaro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'kaj la bazojn de la korto ĉirkaŭe kaj la bazojn de la pordego de la korto kaj ĉiujn najlojn de la tabernaklo kaj ĉiujn najlojn de la korto ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Kaj el la blua, purpura, kaj ruĝa teksaĵo ili faris la oficajn vestojn por la servado en la sanktejo; kaj ili faris la sanktajn vestojn por Aaron, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Kaj ili faris la efodon el oro, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Kaj ili batetendis foliojn da oro kaj tranĉis ilin en formo de fadenoj, por enteksi internen de la blua, purpura, kaj ruĝa teksaĵo kaj de la bisino per artista laboro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Surŝultraĵojn kunigantajn ili faris al ĝi; sur siaj du finoj ĝi estis ligita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Kaj la ĉirkaŭliganta zono sur ĝi estis kontinuaĵo de ĝi, la sama laboraĵo, el oro, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino; kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Kaj ili faris la oniksajn ŝtonojn, ĉirkaŭe enkadrigitajn per oro, gravuritajn per sigelila gravurado laŭ la nomoj de la filoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Kaj li metis ilin sur la surŝultraĵojn de la efodo, kiel ŝtonojn de memoro pri la filoj de Izrael; kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Kaj ili faris la surbrustaĵon per artista laboro, simile al la laboro de la efodo, el oro, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Ĝi estis kvarangula; ili faris la surbrustaĵon duobla; manstreĉo estis ĝia longo, kaj manstreĉo ĝia larĝo; ĝi estis duobla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Kaj ili enmetis en ĝin kvar vicojn da ŝtonoj. La unua vico estis: rubeno, topazo, kaj smeraldo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'kaj la dua vico: hiacinto, safiro, kaj jaspiso;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'kaj la tria vico: ligurio, agato, kaj ametisto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'kaj la kvara vico: krizolito, onikso, kaj berilo. Ĉiuj vicoj estis en oraj kadretoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Kaj la ŝtonoj estis laŭ la nomoj de la filoj de Izrael; dek du, laŭ iliaj nomoj, gravuritaj sigelile, ĉiu kun sia nomo, por la dek du triboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Kaj ili faris al la surbrustaĵo plektitajn ĉenetojn, kuniĝantajn per siaj finoj, el pura oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Kaj ili faris du orajn kadretojn kaj du orajn ringojn, kaj alfortikigis la du ringojn al la du finoj de la surbrustaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Kaj ili metis la du orajn plektitajn ĉenetojn en la du ringojn ĉe la finoj de la surbrustaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Kaj la du finojn de la du plektitaj ĉenetoj ili alfortikigis al la du kadretoj, kaj alfortikigis ilin al la surŝultraĵoj de la efodo sur la antaŭa flanko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Kaj ili faris du orajn ringojn, kaj alfortikigis ilin al la du aliaj finoj de la surbrustaĵo, sur ĝia rando interna, direktita al la efodo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Kaj ili faris du orajn ringojn, kaj alfortikigis ilin al la du surŝultraĵoj de la efodo malsupre, sur la antaŭa flanko, ĉe ĝia kuniĝo, super la zono de la efodo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Kaj ili alligis la surbrustaĵon per ĝiaj ringoj al la ringoj de la efodo per laĉo el blua ŝtofo, por ke ĝi estu super la zono de la efodo kaj por ke la surbrustaĵo ne forŝoviĝu de sur la efodo; kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Kaj li faris la tunikon por la efodo, teksitan, tutan el blua teksaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Kaj la aperturo de la tuniko estis en la mezo, kiel aperturo de ŝildo; borderon havis la aperturo ĉirkaŭe, por ke ĝi ne disŝiriĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Kaj ili faris sur la malsupra rando de la tuniko granatojn el blua, purpura, kaj ruĝa ŝtofo, tordita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Kaj ili faris tintilojn el pura oro, kaj metis la tintilojn mezen de la granatoj sur la malsupra rando de la tuniko, ĉirkaŭe inter la granatoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'tintilon kaj granaton, tintilon kaj granaton sur la malsupra rando de la tuniko, ĉirkaŭe, por la servado; kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Kaj ili faris la ĥitonon el bisino, teksitan, por Aaron kaj liaj filoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'kaj la cidaron el bisino, kaj la ornamajn mitrojn el bisino, kaj la linajn pantalonojn el tordita bisino,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'kaj la zonon el tordita bisino kaj el blua, purpura, kaj ruĝa teksaĵo, broditan; kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Kaj ili faris la tabuleton, la sanktan kronon, el pura oro, kaj ili skribis sur ĝi skribon gravuritan: SANKTA AL LA ETERNULO.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Kaj ili alfortikigis al ĝi laĉon el blua ŝtofo, por alfortikigi al la cidaro supre; kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Tiel finiĝis la tuta laboro por la konstruaĵo de la tabernaklo de kunveno. Kaj la Izraelidoj faris konforme al ĉio, kion la Eternulo ordonis al Moseo; tiel ili faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Kaj ili alportis la konstruaĵon al Moseo, la tabernaklon kaj ĉiujn ĝiajn apartenaĵojn: hokojn, tabulojn, riglilojn, kolonojn, kaj bazojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'kaj la kovron el ruĝaj virŝafaj feloj kaj la kovron el antilopaj feloj kaj la kurtenon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'la keston de atesto kaj ĝiajn stangojn kaj la fermoplaton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'la tablon, ĉiujn ĝiajn apartenaĵojn, kaj la panon de propono;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'la puran kandelabron, ĝiajn lucernojn, la lucernojn vice starantajn, ĉiujn ĝiajn apartenaĵojn, kaj la oleon por lumigado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'kaj la oran altaron kaj la sanktan oleon kaj la bonodoran incenson kaj la kovrotukon por la pordo de la tabernaklo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'la kupran altaron kaj la kupran kradon por ĝi, ĝiajn stangojn kaj ĉiujn ĝiajn apartenaĵojn, la lavujon kaj ĝian piedestalon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'la kurtenojn de la korto, ĝiajn kolonojn kaj bazojn, la kovrotukon por la pordego de la korto, ĝiajn ŝnurojn kaj najlojn, kaj ĉion, kio apartenas al la servado en la konstruaĵo de la tabernaklo de kunveno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'la oficajn vestojn por la servado en la sanktejo, la sanktajn vestojn por la pastro Aaron kaj la pastrajn vestojn por liaj filoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Konforme al ĉio, kion la Eternulo ordonis al Moseo, tiel la Izraelidoj faris la tutan laboron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Kaj Moseo vidis la tutan laboron, li vidis, ke ili faris ĝin tute tiel, kiel la Eternulo ordonis; kaj Moseo benis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'En la unua monato, en la unua tago de la monato starigu la konstruaĵon de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Kaj metu tien la keston de atesto kaj ŝirmu la keston per la kurteno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Kaj enportu la tablon kaj aranĝu sur ĝi ĝian aranĝotaĵon, kaj enportu la kandelabron kaj ekbruligu ĝiajn lucernojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Kaj starigu la oran altaron por la incensado antaŭ la kesto de atesto, kaj pendigu la kovrotukon ĉe la eniro de la tabernaklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Kaj starigu la altaron de bruloferoj antaŭ la eniro en la konstruaĵon de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Kaj starigu la lavujon inter la tabernaklo de kunveno kaj la altaro kaj enverŝu en ĝin akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Kaj aranĝu la korton ĉirkaŭe, kaj pendigu la kovrotukon ĉe la pordego de la korto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Kaj prenu la sanktan oleon, kaj sanktoleu la loĝejon, kaj ĉion, kio estas en ĝi, kaj sanktigu ĝin kun ĉiuj ĝiaj apartenaĵoj, por ke ĝi estu sankta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Kaj sanktoleu la altaron de bruloferoj kun ĉiuj ĝiaj apartenaĵoj, kaj sanktigu la altaron, ke la altaro estu tre sankta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Kaj sanktoleu la lavujon kaj ĝian piedestalon, kaj sanktigu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Kaj alkonduku Aaronon kaj liajn filojn al la eniro de la tabernaklo de kunveno, kaj lavu ilin per akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Kaj vestu Aaronon per la sanktaj vestoj kaj sanktoleu lin kaj sanktigu lin, ke li estu Mia pastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Kaj liajn filojn alkonduku, kaj vestu ilin per ĥitonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Kaj sanktoleu ilin, kiel vi sanktoleis ilian patron, ke ili estu Miaj pastroj; kaj ilia sanktoleiteco estu por ili por eterna pastreco en iliaj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Kaj Moseo faris konforme al ĉio, kion la Eternulo al li ordonis; tiel li faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'En la unua monato de la dua jaro, en la unua tago de la monato estis starigita la tabernaklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Kaj Moseo starigis la tabernaklon kaj metis ĝiajn bazojn kaj starigis ĝiajn tabulojn kaj aranĝis ĝiajn riglilojn kaj starigis ĝiajn kolonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Kaj li etendis tendon super la tabernaklo kaj metis la kovron de la tendo sur ĝin supre, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Kaj li prenis kaj metis la ateston en la keston, kaj almetis la stangojn al la kesto kaj surmetis la fermoplaton sur la keston supre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Kaj li envenigis la keston en la tabernaklon, kaj pendigis la kurtenon kaj ŝirmis la keston de atesto, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Kaj li starigis la tablon en la tabernaklo de kunveno, en la norda parto de la tabernaklo, ekster la kurteno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'Kaj li aranĝis sur ĝi vicon da panoj antaŭ la Eternulo, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Kaj li starigis la kandelabron en la tabernaklo de kunveno kontraŭ la tablo, en la suda parto de la tabernaklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'Kaj li ekbruligis la lucernojn antaŭ la Eternulo, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Kaj li starigis la oran altaron en la tabernaklo de kunveno antaŭ la kurteno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'Kaj li bruligis sur ĝi bonodoran incenson, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Kaj li pendigis la kovrotukon ĉe la pordo de la tabernaklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Kaj la altaron de bruloferoj li starigis ĉe la eniro de la tabernaklo de kunveno, kaj li alportis sur ĝi la bruloferon kaj la farunoferon, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Kaj li starigis la lavujon inter la tabernaklo de kunveno kaj la altaro, kaj enverŝis tien akvon por sin lavi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Kaj lavis per ĝi Moseo kaj Aaron kaj liaj filoj siajn manojn kaj siajn piedojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'kiam ili eniradis en la tabernaklon de kunveno kaj aliradis al la altaro, ili lavadis sin; kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Kaj li aranĝis la korton ĉirkaŭe de la tabernaklo kaj de la altaro, kaj li pendigis la kovrotukon ĉe la pordego de la korto. Tiamaniere Moseo finis la laboron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Kaj nubo kovris la tabernaklon de kunveno, kaj la majesto de la Eternulo plenigis la tabernaklon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Kaj Moseo ne povis eniri en la tabernaklon de kunveno, ĉar kuŝis sur ĝi la nubo kaj la majesto de la Eternulo plenigis la tabernaklon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Kaj kiam la nubo leviĝadis de sur la tabernaklo, la Izraelidoj ekmarŝadis, por fari ĉiujn siajn marŝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Sed se la nubo ne leviĝis, ili ne ekmarŝis ĝis la tago de ĝia leviĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Ĉar nubo de la Eternulo estis super la tabernaklo dum la tago, kaj fajro estis dum la nokto super ĝi, antaŭ la okuloj de ĉiuj Izraelidoj en ĉiuj iliaj marŝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'La Eternulo vokis Moseon, kaj ekparolis al li el la tabernaklo de kunveno, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Parolu al la Izraelidoj, kaj diru al ili: Se iu el vi volas alporti oferon al la Eternulo, el la brutoj, el la bovoj, kaj el la ŝafoj alportu vian oferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Se lia ofero estas brulofero el bovoj, li oferu virseksulon sendifektan; al la pordo de la tabernaklo de kunveno li alkonduku ĝin, por favorigi al si la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Kaj li metu sian manon sur la kapon de la brulofero, kaj li akiros favoron kaj pekpardonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Kaj li buĉu la bovidon antaŭ la Eternulo; kaj la filoj de Aaron, la pastroj, alportu la sangon kaj aspergu per la sango ĉirkaŭe la altaron, kiu estas ĉe la pordo de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Kaj oni senfeligu la bruloferon kaj dishaku ĝin en pecojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Kaj la filoj de la pastro Aaron metu fajron sur la altaron kaj metu lignon sur la fajron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Kaj la filoj de Aaron, la pastroj, metu la pecojn, la kapon, kaj la grason, sur la lignon, kiu estas sur la fajro sur la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Kaj la internaĵon kaj la krurojn oni lavu per akvo; kaj la pastro forbruligu ĉion sur la altaro kiel bruloferon; ĝi estas fajrofero, agrabla odoraĵo al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Kaj se lia ofero estas el la malgrandaj brutoj, el la ŝafoj aŭ el la kaproj, brulofero, li alportu ĝin virseksan, sendifektan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Kaj li buĉu ĝin sur la norda flanko de la altaro antaŭ la Eternulo; kaj la filoj de Aaron, la pastroj, aspergu per ĝia sango la altaron ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Kaj oni dishaku ĝin en pecojn, apartiginte la kapon kaj la grason, kaj la pastro metu ilin sur la lignon, kiu estas sur la fajro sur la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Kaj la internaĵon kaj la krurojn oni lavu per akvo; kaj la pastro ĉion alportu kaj forbruligu sur la altaro kiel bruloferon; ĝi estas fajrofero, agrabla odoraĵo al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Kaj se el la birdoj estas lia brulofero al la Eternulo, li alportu sian oferon el turtoj aŭ el kolombidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Kaj la pastro alportu ĝin al la altaro kaj fortordu ĝian kapon kaj forbruligu ĝin sur la altaro kaj elfluigu ĝian sangon super la muro de la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Kaj ĝian kropon kun ĝiaj plumoj li forigu kaj ĵetu ĝin apud la altaron sur la orientan flankon en la cindrejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Kaj li disfendu ĝiajn flugilojn, sed ne derompu; kaj la pastro forbruligu ĝin sur la altaro, sur la ligno, kiu estas sur la fajro; ĝi estas brulofero, fajrofero, agrabla odoraĵo al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Se iu alportos farunoferon al la Eternulo, lia ofero estu el delikata faruno, kaj li verŝu sur ĝin oleon kaj metu sur ĝin olibanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Kaj li alportu ĝin al la filoj de Aaron, la pastroj; kaj la pastro prenu el ĝi plenmanon el la faruno kun la oleo kaj kun la olibano, kaj li ekbruligu tiun parton promemoran sur la altaro; ĝi estas fajrofero, agrabla odoraĵo al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Kaj la restaĵo el la farunofero estu por Aaron kaj por liaj filoj; plejsanktaĵo ĝi estas el la fajroferoj de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Se vi alportos farunoferon el io, kio estas bakita en forno, ĝi estu macokukoj el plej bona faruno, miksitaj kun oleo, kaj macoflanoj, ŝmiritaj per oleo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Kaj se via ofero estos farunofero farita sur pato, ĝi estu el delikata faruno, miksita kun oleo, ne fermentinta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Dispecigu ĝin kaj verŝu sur ĝin oleon; ĝi estas farunofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Kaj se via ofero estos farunofero el kaserolo, ĝi estu farita el delikata faruno kun oleo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Kaj alportu la farunoferon, kiu estas farita el ĝi, al la Eternulo, kaj prezentu ĝin al la pastro, kaj li alportu ĝin al la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Kaj la pastro prenos el la farunofero la parton promemoran kaj bruligos ĝin sur la altaro; ĝi estas fajrofero, agrabla odoraĵo al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Kaj la restaĵo el la farunofero estu por Aaron kaj por liaj filoj; ĝi estas plejsanktaĵo el la fajroferoj de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Nenia farunofero, kiun vi alportos al la Eternulo, estu farita el fermentintaĵo; ĉar nenion fermentintan kaj nenian mielon vi devas bruligi kiel fajroferon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Kiel oferon de unuaaĵoj vi povas alporti tion al la Eternulo, sed sur la altaron ili ne venu kiel agrabla odoraĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Kaj ĉiun vian farunoferon salu per salo, kaj ne estigu vian farunoferon sen salo de interligo de via Dio; kun ĉiu via ofero alportu salon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Se vi alportos al la Eternulo farunoferon el la unuaj terproduktaĵoj, tiam spikojn, rostitajn sur fajro, grajnaĵon el freŝaj grajnoj alportu kiel farunoferon el viaj unuaj terproduktaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Kaj verŝu sur ĝin oleon kaj metu sur ĝin olibanon; ĝi estas farunofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Kaj la pastro bruligos la promemoran parton el ĝia grajnaĵo kaj el ĝia oleo kun ĝia tuta olibano, kiel fajroferon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Se lia ofero estas pacofero, se li alportas el la grandaj brutoj, ĉu ĝi estas virseksa, ĉu virinseksa, sendifektan li alportu ĝin antaŭ la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Kaj li metu sian manon sur la kapon de sia ofero kaj buĉu ĝin ĉe la pordo de la tabernaklo de kunveno; kaj la filoj de Aaron, la pastroj, aspergu per la sango la altaron ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Kaj li alportu el la pacofero kiel fajroferon al la Eternulo la sebon, kiu kovras la internaĵojn, kaj la tutan sebon, kiu estas sur la internaĵoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'kaj ambaŭ renojn, kaj la sebon, kiu estas sur ili, kiu estas ĉe la lumbo, kaj la reton sur la hepato, kune kun la renoj li ĝin apartigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Kaj la filoj de Aaron forbruligu tion sur la altaro, kune kun la brulofero, kiu estas sur la ligno, sur la fajro; ĝi estas fajrofero, agrabla odoraĵo al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Kaj se el la malgrandaj brutoj estas lia ofero, kiel pacofero al la Eternulo, ĉu ĝi estas virseksa, ĉu virinseksa, sendifektan li ĝin alportu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Se ŝafidon li alportas kiel sian oferon, li alportu ĝin antaŭ la Eternulon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'kaj li metu sian manon sur la kapon de sia ofero, kaj li buĉu ĝin antaŭ la tabernaklo de kunveno; kaj la filoj de Aaron aspergu per ĝia sango la altaron ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Kaj li alportu el la pacofero kiel fajroferon al la Eternulo ĝian sebon, la tutan voston, detranĉitan ĉe la sakro, kaj la sebon, kiu kovras la internaĵojn, kaj la tutan sebon, kiu estas sur la internaĵoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'kaj ambaŭ renojn, kaj la sebon, kiu estas sur ili, kiu estas ĉe la lumbo, kaj la reton sur la hepato, kune kun la renoj li ĝin apartigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Kaj la pastro bruligu tion sur la altaro; ĝi estas manĝaĵo, fajrofero al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Kaj se lia ofero estas kapro, li alportu ĝin antaŭ la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'Kaj li metu sian manon sur ĝian kapon, kaj li buĉu ĝin antaŭ la tabernaklo de kunveno; kaj la filoj de Aaron aspergu per ĝia sango la altaron ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Kaj li alportu el ĝi ofere, kiel fajroferon al la Eternulo, la sebon, kiu kovras la internaĵojn, kaj la tutan sebon, kiu estas sur la internaĵoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'kaj ambaŭ renojn, kaj la sebon, kiu estas sur ili, kiu estas ĉe la lumbo, kaj la reton sur la hepato, kune kun la renoj li ĝin apartigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Kaj la pastro bruligu tion sur la altaro; ĝi estas manĝaĵo, fajrofero, agrabla odoraĵo; la tuta sebo estu por la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Ĝi estu eterna leĝo por viaj generacioj en ĉiuj viaj loĝlokoj; sebon kaj sangon neniam manĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Diru al la Izraelidoj jene: Se iu pekos per eraro kontraŭ la ordonoj de la Eternulo, malpermesantaj fari diversajn aferojn, kaj li faros iun el ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'se pastro sanktoleita pekos, ĵetante kulpon sur la popolon, tiam li alportu pro sia peko, kiun li pekis, bovidon sendifektan al la Eternulo, kiel oferon propekan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Li venigu la bovidon al la pordo de la tabernaklo de kunveno antaŭ la Eternulon, kaj li metu sian manon sur la kapon de la bovido, kaj li buĉu la bovidon antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Kaj la sanktoleita pastro prenu iom el la sango de la bovido kaj enportu ĝin en la tabernaklon de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Kaj la pastro trempu sian fingron en la sango, kaj aspergu per la sango sepfoje antaŭ la Eternulo, antaŭ la kurteno de la sanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Kaj la pastro metu iom el la sango sur la kornojn de la altaro de bonodora incenso antaŭ la Eternulo en la tabernaklo de kunveno, kaj la tutan ceteran sangon de la bovido li elverŝu ĉe la bazo de la altaro de bruloferoj, kiu estas ĉe la pordo de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Kaj la tutan sebon de la propeka bovido li forlevu el ĝi, la sebon, kiu kovras la internaĵojn, kaj la tutan sebon, kiu estas sur la internaĵoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'kaj ambaŭ renojn, kaj la sebon, kiu estas sur ili, kiu estas ĉe la lumbo, kaj la reton sur la hepato, kune kun la renoj li ĝin apartigu,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'tiel same, kiel estas forlevata pacofero el bovo; kaj la pastro bruligu tion sur la altaro de bruloferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Kaj la felon de la bovido kaj ĝian tutan viandon kun ĝia kapo kaj kruroj kaj ĝiajn internaĵojn kaj malpuraĵon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'la tutan bovidon li elportu ekster la tendaron sur puran lokon, kien oni ŝutas la cindron, kaj li forbruligu tion sur ligno per fajro; sur la cindrejo tio estu forbruligata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Kaj se la tuta komunumo de la Izraelidoj pekos per eraro kaj la afero estos kaŝita antaŭ la okuloj de la anaro, kaj ili faros iun el la agoj, kiujn la Eternulo malpermesis, kaj ili fariĝos kulpaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'kaj ili sciiĝos pri la peko, kiun ili pekis: tiam la anaro alportu bovidon kiel propekan oferon kaj venigu ĝin antaŭ la tabernaklon de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Kaj la plejaĝuloj de la komunumo metu siajn manojn sur la kapon de la bovido antaŭ la Eternulo, kaj oni buĉu la bovidon antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Kaj la sanktoleita pastro enportu iom el la sango de la bovido en la tabernaklon de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'Kaj la pastro trempu sian fingron en la sango, kaj aspergu sep fojojn antaŭ la Eternulo, antaŭ la kurteno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Kaj iom el la sango li metu sur la kornojn de la altaro, kiu estas antaŭ la Eternulo en la tabernaklo de kunveno, kaj la tutan ceteran sangon li elverŝu ĉe la bazo de la altaro de bruloferoj, kiu estas ĉe la pordo de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Kaj ĝian tutan sebon li forlevu el ĝi kaj bruligu sur la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Kaj li faru kun la bovido; kiel li faris kun la propeka bovido, tiel li faru kun ĝi; kaj pekliberigos ilin la pastro, kaj estos pardonite al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Kaj li elportu la bovidon ekster la tendaron, kaj forbruligu ĝin, kiel li forbruligis la unuan bovidon; ĝi estas propeka ofero de la komunumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Se princo pekos, kaj per eraro faros iun el la agoj, kiujn la Eternulo, lia Dio, malpermesis fari, kaj li fariĝos kulpa;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'kaj li sciiĝos pri sia peko, kiun li pekis: tiam li alportu kiel sian oferon virkapron sendifektan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Kaj li metu sian manon sur la kapon de la kapro, kaj buĉu ĝin sur la loko, sur kiu estas buĉataj bruloferoj antaŭ la Eternulo; ĝi estas propeka ofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Kaj la pastro prenos iom el la sango de la propeka ofero per sia fingro, kaj li metos ĝin sur la kornojn de la altaro de bruloferoj, kaj la ceteran sangon li elverŝos ĉe la bazo de la altaro de bruloferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Kaj ĝian tutan sebon li bruligos sur la altaro, kiel la sebon de pacofero; kaj la pastro liberigos lin de lia peko, kaj estos pardonite al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Se iu el la popolo per eraro pekos, farante iun el la agoj, kiujn la Eternulo malpermesis, kaj li fariĝos kulpa;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'kaj li sciiĝos pri sia peko, kiun li pekis: tiam li alportu kiel sian oferon kaprinon sendifektan pro sia peko, kiun li pekis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Kaj li metu sian manon sur la kapon de la propeka ofero, kaj li buĉu la propekan oferon sur la loko de la bruloferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Kaj la pastro prenos iom el ĝia sango per sia fingro kaj metos sur la kornojn de la altaro de bruloferoj, kaj la tutan ceteran sangon li elverŝos ĉe la bazo de la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Kaj ĝian tutan sebon li apartigos, kiel estas apartigata la sebo de la pacoferoj, kaj la pastro bruligos ĝin sur la altaro, kiel agrablan odoraĵon al la Eternulo; kaj la pastro pekliberigos lin, kaj estos pardonite al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Se ŝafon li alportos kiel sian propekan oferon, li alportu virinseksan, sendifektan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Kaj li metu sian manon sur la kapon de la propeka ofero, kaj buĉu ĝin kiel propekan oferon sur la loko, kie oni buĉas bruloferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Kaj la pastro prenos per sia fingro iom el la sango de la propeka ofero kaj metos ĝin sur la kornojn de la altaro de bruloferoj, kaj ĝian tutan ceteran sangon li elverŝos ĉe la bazo de la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Kaj ĝian tutan sebon li apartigos, kiel estas apartigata la sebo de la ŝafo el la pacoferoj, kaj la pastro bruligos ĝin sur la altaro kun la fajroferoj al la Eternulo; kaj la pastro liberigos lin de la peko, kiun li pekis, kaj estos pardonite al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Se iu pekos per tio, ke li aŭdos ĵuron kaj estos atestanto, aŭ ke li vidos aŭ scios, sed ne sciigos kaj portos sur si la pekon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'aŭ se iu ektuŝos ion malpuran, aŭ kadavraĵon de malpura besto, aŭ kadavraĵon de malpura bruto, aŭ kadavraĵon de malpura rampaĵo, kaj li tion ne scios, kaj li malpuriĝos kaj kulpiĝos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'aŭ se iu ektuŝos malpuraĵon de homo, kia ajn estus tiu malpuraĵo, per kiu oni malpuriĝas, kaj li tion ne scios, kaj poste li sciiĝos, kaj li estos kulpa;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'aŭ se iu per nesingarda buŝo ĵuros fari ion malbonan aŭ bonan, kion ajn homo elesprimas per ĵuro, kaj li tion ne rimarkos, kaj poste li sciiĝos, kaj li estos kulpa pri io el tiuj aferoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'se iu estos kulpa pri io el tiuj aferoj, li faru konfeson pri tio, kion li pekis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'kaj pro sia peko, kiun li pekis, li alportu al la Eternulo kiel propekan oferon inon el la malgrandaj brutoj, ŝafinon aŭ kaprinon; kaj la pastro liberigos lin de lia peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Kaj se li ne estos sufiĉe bonstata, por alporti ŝafinon, li alportu pro sia peko, kiun li pekis, du turtojn aŭ du kolombidojn al la Eternulo, unu kiel propekan oferon, la duan kiel bruloferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Li alportu ilin al la pastro, kaj ĉi tiu prezentos antaŭe tiun, kiu estos propeka ofero, kaj li tordorompos ĝian kapon ĉe la nuko, sed ne apartigos ĝin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'kaj li aspergos per la sango de la propeka ofero la muron de la altaro, kaj la restintan sangon li elpremos ĉe la bazo de la altaro; tio estas propeka ofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Kaj el la dua li faros bruloferon laŭ la reguloj; kaj la pastro liberigos lin de la peko, kiun li pekis, kaj estos pardonite al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Se li ne estos sufiĉe bonstata, por alporti du turtojn aŭ du kolombidojn, tiam li alportu kiel oferon pro sia peko dekonon de efo da delikata faruno, kiel propekan oferon; li ne verŝu sur ĝin oleon kaj ne metu sur ĝin olibanon, ĉar ĝi estas propeka ofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Kaj li alportu ĝin al la pastro, kaj la pastro prenos el ĝi plenmanon kiel memorparton kaj bruligos sur la altaro kun la fajroferoj al la Eternulo; ĝi estas propeka ofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Kaj la pastro liberigos lin de lia peko, kiun li pekis koncerne iun el tiuj aferoj, kaj estos pardonite al li; la restaĵo estu por la pastro, kiel farunofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Se iu kulpiĝos, pekante per eraro kontraŭ la sanktaĵoj de la Eternulo, tiam li alportu kiel prokulpan oferon al la Eternulo virŝafon sendifektan el la malgrandaj brutoj, havantan laŭ via taksado la valoron de du sikloj, laŭ la sankta siklo; ĝi estu prokulpa ofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Kaj pro la sanktaĵo, kontraŭ kiu li pekis, li pagu, kaj li aldonu kvinonon de ĝia valoro kaj donu tion al la pastro; kaj la pastro pekliberigos lin per la prokulpa virŝafo, kaj estos pardonite al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Kaj se iu pekos, farante iun el tiuj aferoj, kiujn la Eternulo malpermesis, sed li ne sciis kaj fariĝis kulpa, kaj li portos sur si sian pekon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'tiam li alportu virŝafon sendifektan el la malgrandaj brutoj, laŭ via taksado, kiel kulpoferon al la pastro; kaj la pastro pekliberigos lin koncerne lian eraron, kiun li faris ne sciante, kaj estos pardonite al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Ĝi estas prokulpa ofero; li kulpiĝis antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Se iu pekos kaj krimos antaŭ la Eternulo, neante al sia proksimulo koncerne konfiditaĵon aŭ deponitaĵon aŭ rabitaĵon, aŭ se li trompe forprenos ion de sia proksimulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'aŭ se li trovos perditaĵon kaj neos tion, aŭ se li ĵuros mensoge pri io, kion homo faras, kaj per tio pekas:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'tiam, se li pekis kaj kulpiĝis, li redonu la rabitaĵon, kiun li rabis, aŭ tion, kion li trompe forprenis, aŭ la deponitaĵon, kiu estis deponita ĉe li, aŭ la perditaĵon, kiun li trovis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'aŭ ĉion, pri kio li mensoge ĵuris, li repagu per ĝia plena valoro kaj aldonu plie kvinonon de ĝi; al tiu, kies tio estas, li donu ĝin en la tago, kiam li alportas sian kulpoferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Kaj kiel sian kulpoferon li alportu al la Eternulo sendifektan virŝafon el la malgrandaj brutoj, laŭ via taksado, kiel kulpoferon, por la pastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Kaj la pastro pekliberigos lin antaŭ la Eternulo, kaj estos pardonite al li pri ĉio, kion li faris kaj per kio li kulpiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Ordonu al Aaron kaj al liaj filoj, dirante: Jen estas la leĝo pri la brulofero: la brulofero restu sur la fajrujo sur la altaro dum tuta nokto, ĝis la mateno, kaj la fajro de la altaro restu brulanta sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Kaj la pastro metu sur sin sian linan veston, kaj siajn linajn pantalonojn li surmetu sur sian korpon, kaj li deprenu la cindron, kiun la fajro elbruligis el la brulofero sur la altaro, kaj li metu ĝin apud la altaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Kaj li demetu siajn vestojn kaj metu sur sin aliajn vestojn kaj elportu la cindron ekster la tendaron sur puran lokon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Kaj la fajro sur la altaro restu brulanta sur ĝi kaj ne estingiĝu; kaj la pastro bruligu sur ĝi lignon ĉiumatene, kaj aranĝu sur ĝi la bruloferon kaj bruligu sur ĝi la sebon de la pacoferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Eterna fajro brulu sur la altaro, ne estingiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Kaj jen estas la leĝo pri la farunofero: la filoj de Aaron alportu ĝin antaŭ la Eternulon sur la antaŭan parton de la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Kaj la pastro prenu el ĝi plenmanon el la delikata faruno de la farunofero kaj el ĝia oleo, kaj la tutan olibanon, kiu estas sur la farunofero, kaj li bruligu sur la altaro kiel agrablan odoraĵon, memoraĵon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Kaj la restaĵon el ĝi manĝu Aaron kaj liaj filoj; senfermente ili ĝin manĝu sur sankta loko, sur la korto de la tabernaklo de kunveno ili ĝin manĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Ĝi ne estu bakata fermentinte; kiel ilian parton Mi donis ĝin el Miaj fajroferoj; ĝi estas plejsanktaĵo, simile al pekofero kaj kulpofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Ĉiu virseksulo el la Aaronidoj povas ĝin manĝi kiel eternan destinitaĵon en viaj generacioj el la fajroferoj de la Eternulo; ĉiu, kiu ektuŝos ilin, devos esti sankta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Jen estas la ofero de Aaron kaj liaj filoj, kiun ili alportos al la Eternulo en la tago de sia sanktoleateco: dekono de efo da delikata faruno kiel konstanta farunofero, unu duono matene kaj la dua duono vespere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Sur pato kun oleo ĝi devas esti preparita; bone bakitan alportu ĝin; en formo de dispecigita farunofero alportu ĝin kiel agrablan odoraĵon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Kaj la pastro, kiu el liaj filoj estos sanktoleita anstataŭ li, plenumos tion; ĝi estu eterna leĝo antaŭ la Eternulo; ĝi tuta devas esti forbruligata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Kaj ĉiu farunofero de pastro estu forbruligata tuta; ĝi ne estu manĝata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Diru al Aaron kaj al liaj filoj jene: Jen estas la leĝo pri la pekofero: sur tiu loko, sur kiu estas buĉata la brulofero, oni buĉu la pekoferon antaŭ la Eternulo; plejsanktaĵo ĝi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'La pastro, kiu plenumas la pekoferon, manĝu ĝin; sur sankta loko ĝi estu manĝata, sur la korto de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Ĉiu, kiu ektuŝos ĝian viandon, devas esti sankta; kaj se iu aspergos per ĝia sango la veston, li lavu la aspergitan pecon sur sankta loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Kaj la argilan vazon, en kiu ĝi estis kuirita, oni disrompu; kaj se ĝi estis kuirita en kupra vazo, oni purigu ĉi tiun kaj lavu ĝin per akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Ĉiu virseksulo el la pastroj povas ĝin manĝi; ĝi estas plejsanktaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Sed ĉiu pekofero, el kies sango oni enportos en la tabernaklon de kunveno por pekliberigo en la sanktejo, ne estu manĝata: per fajro oni ĝin forbruligu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Kaj jen estas la leĝo pri la kulpofero: plejsanktaĵo ĝi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Sur la loko, sur kiu estas buĉata la brulofero, oni buĉu la kulpoferon, kaj per ĝia sango oni aspergu la altaron ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Kaj ĝian tutan sebon oni alportu el ĝi ofere, la voston, kaj la sebon, kiu kovras la internaĵojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'kaj ambaŭ renojn, kaj la sebon, kiu estas sur ili, kiu estas ĉe la lumbo, kaj la reton sur la hepato, kune kun la renoj oni ĝin apartigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Kaj la pastro bruligu ilin sur la altaro kiel fajroferon al la Eternulo; ĝi estas kulpofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Ĉiu virseksulo el la pastroj povas ĝin manĝi; sur sankta loko ĝi estu manĝata; ĝi estas plejsanktaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Kiel por la pekofero, tiel ankaŭ por la kulpofero estu la sama leĝo; al la pastro, kiu pekliberigas per ĝi, al li ĝi apartenu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Al la pastro, kiu plenumas ies bruloferon, al tiu pastro apartenu la felo de la brulofero, kiun li plenumis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Kaj ĉiu farunofero, kiu estas bakita en forno aŭ pretigita en kaserolo aŭ sur pato, apartenu al la pastro, kiu prezentis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Kaj ĉiu farunofero, miksita kun oleo aŭ seka, apartenu al ĉiuj Aaronidoj, al ĉiuj egale.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Kaj jen estas la leĝo pri la pacofero, kiu estas alportata al la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'se iu ĝin alportas kiel dankon, li alportu kun la danka ofero nefermentintajn kukojn, miksitajn kun oleo, kaj nefermentintajn flanojn, ŝmiritajn per oleo, kaj el delikata faruno kukojn frititajn, miksitajn kun oleo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Kune kun kukoj el pano fermentinta li alportu sian oferon, ĉe sia danka pacofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Kaj li alportu unu el ili, el ĉiu ofero, kiel oferdonon al la Eternulo; al la pastro, kiu aspergas la sangon de la pacofero, ĝi apartenu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Kaj la viando de la danka pacofero estu manĝata en la tago de la oferado; oni ne devas restigi iom el ĝi ĝis la mateno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Sed se lia ofero estas sankta promeso aŭ memvola ofero, ĝi estu manĝata en la tago de la alportado de la ofero; kaj ankaŭ en la sekvanta tago oni povas manĝi tion, kio restis el ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Kaj kio restis el la viando de la ofero ĝis la tria tago, tio estu forbruligata per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Se iu manĝos el la viando de sia pacofero en la tria tago, ĝi ne akiros plaĉon; kiu alportos ĝin, al tiu ĝi ne estos kalkulata; ĝi estos abomenindaĵo, kaj kiu ĝin manĝos, tiu havos pekon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'La viando, kiu ektuŝis ion malpuran, ne estu manĝata, oni ĝin forbruligu per fajro. La ceteran viandon povas manĝi ĉiu purulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Se iu, havante sur si malpuraĵon, manĝos viandon el la pacofero, kiu estis destinita por la Eternulo, ties animo ekstermiĝos el sia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Se iu ektuŝos ion malpuran, ĉu malpuraĵon de homo, ĉu malpuran beston, ĉu ian malpuran abomenindaĵon, kaj manĝos el la viando de pacofero, kiu estis destinita por la Eternulo, ties animo ekstermiĝos el sia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Diru al la Izraelidoj jene: Sebon de bovo kaj de ŝafo kaj de kapro neniam manĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'La sebon de kadavraĵo kaj la sebon de besto disŝirita oni povas uzi por ĉia laboro, sed manĝi ĝin vi ne devas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Ĉar ĉiu, kiu manĝos sebon de brutoj, el kiuj oni alportas fajroferon al la Eternulo, la manĝinto ekstermiĝos el sia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Kaj nenian sangon manĝu en ĉiuj viaj loĝejoj, nek el birdoj, nek el brutoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Ĉiu, kiu manĝos ian sangon, ekstermiĝos el sia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Diru al la Izraelidoj jene: Kiu alportas sian pacoferon al la Eternulo, tiu alportu mem al la Eternulo tion, kio apartenas el liaj pacoferoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'propramane li alportu la fajroferon al la Eternulo; la sebon kune kun la brustaĵo li alportu; la brustaĵon, por skui ĝin kiel skuoferon antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Kaj la pastro bruligos la sebon sur la altaro, kaj la brustaĵo estos por Aaron kaj por liaj filoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Kaj la dekstran femuron el viaj pacoferoj donu kiel levoferon al la pastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Kiu el la Aaronidoj alportas la sangon de la pacoferoj kaj la sebon, al tiu apartenu la dekstra femuro kiel lia parto:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'ĉar la brustaĵon-skuoferon kaj la femuron-levoferon Mi prenis de la Izraelidoj el iliaj pacoferoj, kaj Mi donis ilin al la pastro Aaron kaj al liaj filoj kiel eternan destinitaĵon de la flanko de la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Tio estas la sankta parto de Aaron kaj la sankta parto de liaj filoj el la fajroferoj de la Eternulo de post la tago, en kiu ili estis aligitaj, por esti pastroj al la Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'parto, kiun la Eternulo ordonis doni al ili de la Izraelidoj en la tago, en kiu Li sanktoleis ilin. Tio estas eterna leĝo en iliaj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Tio estas la leĝo pri la brulofero, pri la farunofero, pri la pekofero, pri la kulpofero, pri la ofero de konsekro, kaj pri la pacofero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'kiun la Eternulo donis al Moseo sur la monto Sinaj, kiam Li ordonis al la Izraelidoj en la dezerto Sinaja, ke ili alportadu siajn oferojn al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Prenu Aaronon kaj liajn filojn kune kun li kaj la vestojn kaj la sanktan oleon kaj bovidon por pekofero kaj du virŝafojn kaj korbon da macoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'Kaj la tutan komunumon kunvenigu ĉe la eniro de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Kaj Moseo faris, kiel la Eternulo al li ordonis; kaj la komunumo kolektiĝis ĉe la eniro de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Kaj Moseo diris al la komunumo: Jen estas tio, kion la Eternulo ordonis fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Kaj Moseo alvenigis Aaronon kaj liajn filojn, kaj li lavis ilin per akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Kaj li metis sur lin la ĥitonon kaj zonis lin per zono kaj vestis lin per la tuniko kaj metis sur lin la efodon kaj zonis lin per la zono de la efodo kaj alfortikigis per ĝi la efodon sur li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Kaj li metis sur lin la surbrustaĵon, kaj sur la surbrustaĵon la signojn de lumo kaj de justo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Kaj li metis la cidaron sur lian kapon, kaj sur la cidaron sur la antaŭa flanko li metis la oran tabuleton, la sanktan kronon, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Kaj Moseo prenis la sanktan oleon, kaj sanktoleis la tabernaklon, kaj ĉion, kio estis en ĝi, kaj li sanktigis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Kaj li aspergis per tio la altaron sep fojojn, kaj li sankteŝmiris la altaron kaj ĉiujn ĝiajn apartenaĵojn, kaj la lavujon kaj ĝian piedestalon, por sanktigi ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Kaj li verŝis iom el la sankta oleo sur la kapon de Aaron, kaj li ŝmiris lin, por sanktigi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Kaj Moseo alvenigis la filojn de Aaron kaj vestis ilin per ĥitonoj kaj zonis ilin per zonoj kaj alligis sur ili mitrojn, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Kaj li alkondukis la propekan bovidon, kaj Aaron kaj liaj filoj metis siajn manojn sur la kapon de la propeka bovido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Kaj Moseo ĝin buĉis, kaj li prenis iom el la sango kaj metis per sia fingro sur la kornojn de la altaro ĉirkaŭe kaj pekliberigis la altaron; kaj la ceteran sangon li elverŝis ĉe la bazo de la altaro, kaj sanktigis ĉi tiun, por pekliberigi ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Kaj li prenis la tutan sebon, kiu estis sur la internaĵoj, kaj la reton de la hepato, kaj ambaŭ renojn kaj ilian sebon, kaj Moseo bruligis tion sur la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Kaj la bovidon kaj ĝian felon kaj ĝian karnon kaj ĝian malpuraĵon li forbruligis per fajro ekster la tendaro, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Kaj li alkondukis la virŝafon de brulofero; kaj Aaron kaj liaj filoj metis siajn manojn sur la kapon de la virŝafo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Kaj Moseo ĝin buĉis, kaj aspergis per la sango la altaron ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Kaj la virŝafon li dishakis en partojn, kaj Moseo ekbruligis la kapon kaj la partojn kaj la grason.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'La internaĵojn kaj la krurojn li lavis per akvo; kaj Moseo forbruligis la tutan ŝafon sur la altaro; ĝi estis brulofero por agrabla odoraĵo, fajrofero al la Eternulo, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Kaj li alkondukis la duan virŝafon, la virŝafon de konsekrado; kaj Aaron kaj liaj filoj metis siajn manojn sur la kapon de la virŝafo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Kaj li ĝin buĉis, kaj Moseo prenis iom el ĝia sango kaj metis sur la malsupran randon de la dekstra orelo de Aaron kaj sur la dikan fingron de lia dekstra mano kaj sur la dikan fingron de lia dekstra piedo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Kaj li alkondukis la filojn de Aaron, kaj Moseo metis iom el la sango sur la malsupran randon de ilia dekstra orelo kaj sur la dikan fingron de ilia dekstra mano kaj sur la dikan fingron de ilia dekstra piedo; kaj Moseo aspergis per la sango la altaron ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Kaj li prenis la sebon kaj la voston, kaj la tutan sebon, kiu estis sur la internaĵoj, kaj la reton de la hepato, kaj ambaŭ renojn kaj ilian sebon, kaj la dekstran femuron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Kaj el la korbo da macoj, kiu estis antaŭ la Eternulo, li prenis unu macan kukon kaj unu kukon kun oleo kaj unu flanon, kaj metis ilin sur la sebojn kaj sur la dekstran femuron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Kaj li metis ĉion ĉi tion sur la manojn de Aaron kaj sur la manojn de liaj filoj, kaj li skuis tion kiel skuoferon antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Kaj Moseo prenis tion for de iliaj manoj kaj ekbruligis sur la altaro kune kun la brulofero: tio estis ofero de konsekrado, por agrabla odoraĵo; ĝi estis fajrofero al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Kaj Moseo prenis la brustaĵon kaj skuis ĝin kiel skuoferon antaŭ la Eternulo: de la ŝafo de konsekrado ĝi estis la destinita parto por Moseo, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Kaj Moseo prenis iom el la sankta oleo, kaj el la sango, kiu estis sur la altaro, kaj aspergis Aaronon, liajn vestojn, liajn filojn, kaj la vestojn de liaj filoj kune kun li; kaj li sanktigis Aaronon, liajn vestojn, liajn filojn, kaj la vestojn de liaj filoj kune kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Kaj Moseo diris al Aaron kaj al liaj filoj: Kuiru la viandon ĉe la pordo de la tabernaklo de kunveno; kaj tie manĝu ĝin, kaj ankaŭ la panon, kiu estas en la korbo de konsekrado, kiel mi ordonis, dirante: Aaron kaj liaj filoj ĝin manĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Kaj la restaĵon el la viando kaj el la pano forbruligu per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Kaj for de la pordo de la tabernaklo de kunveno ne foriru dum sep tagoj, ĝis la tago, en kiu finiĝos la tempo de via konsekrado; ĉar sep tagojn daŭros via konsekrado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Kiel estis farite hodiaŭ, tiel la Eternulo ordonis fari, por pekliberigi vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Kaj ĉe la pordo de la tabernaklo de kunveno restu tage kaj nokte dum sep tagoj, kaj vi observos la servadon al la Eternulo, por ke vi ne mortu; ĉar tiel estas ordonite al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Kaj Aaron kaj liaj filoj faris ĉion, kion la Eternulo ordonis per Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'En la oka tago Moseo vokis Aaronon kaj liajn filojn kaj la plejaĝulojn de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'Kaj li diris al Aaron: Prenu al vi junan bovidon por pekofero kaj virŝafon por brulofero, sendifektajn, kaj alkonduku ilin antaŭ la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Kaj al la Izraelidoj diru jene: Prenu virkapron por propeka ofero, kaj bovidon kaj ŝafidon jaraĝajn, sendifektajn, por brulofero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'kaj virbovon kaj virŝafon por pacofero, por fari oferon antaŭ la Eternulo, kaj farunoferon, miksitan kun oleo; ĉar hodiaŭ la Eternulo aperos antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Kaj ili alportis tion, kion ordonis Moseo, antaŭ la pordon de la tabernaklo de kunveno; kaj la tuta komunumo alproksimiĝis kaj stariĝis antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Kaj Moseo diris: Jen estas tio, kion la Eternulo ordonis; faru, kaj tiam aperos antaŭ vi la majesto de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Kaj Moseo diris al Aaron: Aliru al la altaro, kaj faru vian pekoferon kaj vian bruloferon kaj pekliberigu vin kaj la popolon, kaj faru la oferon de la popolo kaj pekliberigu ilin, kiel ordonis la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Kaj Aaron aliris al la altaro, kaj buĉis la bovidon, kiu estis lia propeka ofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Kaj la filoj de Aaron alportis al li la sangon, kaj li trempis sian fingron en la sango kaj ŝmiris la kornojn de la altaro, kaj la ceteran sangon li elverŝis ĉe la bazo de la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Sed la sebon kaj la renojn kaj la reton de la hepato de la pekofero li bruligis sur la altaro, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Kaj la karnon kaj la felon li forbruligis per fajro ekster la tendaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Kaj li buĉis la bruloferon, kaj la filoj de Aaron alportis al li la sangon, kaj li aspergis per ĝi la altaron ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Kaj la bruloferon ili alportis al li dispecigitan kaj la kapon, kaj li bruligis tion sur la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Kaj li lavis la internaĵojn kaj la krurojn kaj bruligis tion kun la brulofero sur la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Kaj li alportis la oferon de la popolo, kaj li prenis la propekan kapron de la popolo, kaj buĉis ĝin kaj faris el ĝi pekoferon kiel el la antaŭa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Kaj li alportis la bruloferon kaj agis kun ĝi laŭ la reguloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Kaj li alportis la farunoferon kaj prenis el ĝi plenmanon kaj bruligis tion sur la altaro krom la matena brulofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Kaj li buĉis la bovon kaj la ŝafon kiel pacoferon de la popolo, kaj la filoj de Aaron alportis al li la sangon, kaj li aspergis per ĝi la altaron ĉirkaŭe;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'kaj la sebojn de la bovo, kaj el la ŝafo la voston kaj la kovrantan sebon kaj la renojn kaj la reton de la hepato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'Kaj ili metis la sebojn sur la brustaĵojn, kaj li ekbruligis la sebojn sur la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Kaj la brustaĵojn kaj la dekstran femuron Aaron skuis kiel skuoferon antaŭ la Eternulo, kiel Moseo ordonis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Kaj Aaron levis siajn manojn al la popolo kaj benis ĝin; kaj li malsupreniris, plenuminte la pekoferon kaj la bruloferon kaj la pacoferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Kaj Moseo kaj Aaron eniris en la tabernaklon de kunveno kaj eliris kaj benis la popolon. Kaj montriĝis la majesto de la Eternulo al la tuta popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Kaj eliris fajro el antaŭ la Eternulo kaj konsumis sur la altaro la bruloferon kaj la sebon; kaj la tuta popolo vidis, kaj ili ĝoje ekkriis kaj falis vizaĝaltere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Kaj Nadab kaj Abihu, la filoj de Aaron, prenis ĉiu sian incensujon kaj metis en ĝin fajron kaj metis sur ĝin incenson kaj alportis antaŭ la Eternulon fajron fremdan, pri kiu Li ne ordonis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Tiam eliris fajro el antaŭ la Eternulo kaj forbruligis ilin, kaj ili mortis antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Kaj Moseo diris al Aaron: Jen pri ĉi tio parolis la Eternulo, kiam Li diris: Per Miaj proksimuloj Mi sanktiĝos kaj antaŭ la tuta popolo Mi majestiĝos. Kaj Aaron silentis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Kaj Moseo alvokis Miŝaelon kaj Elcafanon, filojn de Uziel, onklo de Aaron, kaj li diris al ili: Aliru, elportu viajn fratojn el la sanktejo ekster la tendaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Kaj ili aliris kaj elportis ilin en iliaj ĥitonoj ekster la tendaron, kiel diris Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Kaj Moseo diris al Aaron kaj al liaj filoj Eleazar kaj Itamar: Viajn kapojn ne nudigu kaj viajn vestojn ne disŝiru, por ke vi ne mortu kaj por ke Li ne koleru la tutan komunumon; sed viaj fratoj, la tuta domo de Izrael, priploru la brulon, kiun la Eternulo ekbruligis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Kaj el la pordo de la tabernaklo de kunveno ne eliru, por ke vi ne mortu; ĉar la sankta oleo de la Eternulo estas sur vi. Kaj ili agis laŭ la vortoj de Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Kaj la Eternulo ekparolis al Aaron, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Vinon kaj ebriigaĵon ne trinku, nek vi, nek viaj filoj kun vi, kiam vi iras en la tabernaklon de kunveno, por ke vi ne mortu. Tio estu eterna leĝo en viaj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'Por ke vi diferencigu inter sanktaĵo kaj ordinaraĵo kaj inter malpuraĵo kaj puraĵo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'kaj por ke vi instruu al la Izraelidoj ĉiujn leĝojn, kiujn eldiris al ili la Eternulo per Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Kaj Moseo diris al Aaron, kaj al Eleazar kaj al Itamar, liaj restintaj filoj: Prenu la farunoferon, kiu restis el la fajroferoj de la Eternulo, kaj manĝu ĝin senfermente apud la altaro; ĉar ĝi estas plejsanktaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Kaj manĝu ĝin sur sankta loko; ĉar ĝi estas via destinitaĵo kaj la destinitaĵo de viaj filoj el la fajroferoj de la Eternulo; ĉar tiel estas ordonite al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Kaj la brustaĵon de skuado kaj la femuron de levado manĝu sur loko pura, vi kaj viaj filoj kaj viaj filinoj kune kun vi; ĉar ili estas donitaj kiel via destinitaĵo kaj destinitaĵo de viaj filoj el la pacoferoj de la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'La femuron de levado kaj la brustaĵon de skuado ili alportu kun la fajroferoj el la sebo, por skui tion kiel skuoferon antaŭ la Eternulo; kaj tio estu por vi kaj por viaj filoj eterna destinitaĵo, kiel ordonis la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Kaj la kapron propekan Moseo serĉis, sed montriĝis, ke ĝi estas forbruligita. Tiam li ekkoleris kontraŭ Eleazar kaj kontraŭ Itamar, la restintaj filoj de Aaron, kaj li diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Kial vi ne manĝis la pekoferon sur loko sankta? ĝi estas ja plejsanktaĵo, kaj ĝi estas donita al vi, por forporti la pekon de la komunumo, por pekliberigi ilin antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Jen ĝia sango ne estas enportita en la internon de la sanktejo; vi devis manĝi ĝin en la sanktejo, kiel estas ordonite al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Kaj Aaron diris al Moseo: Jen hodiaŭ ili alportis sian pekoferon kaj sian bruloferon antaŭ la Eternulon, kaj okazis al mi tia afero; se mi manĝus hodiaŭ pekoferon, ĉu tio plaĉus al la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Kaj Moseo tion aŭdis, kaj tio plaĉis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Kaj la Eternulo ekparolis al Moseo kaj al Aaron, dirante al ili:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Diru al la Izraelidoj jene: Tio estas la bestoj, kiujn vi povas manĝi el ĉiuj brutoj, kiuj estas sur la tero:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'ĉiun bruton, kiu havas disfenditajn hufojn kaj distranĉan sulkon sur la hufoj kaj kiu remaĉas maĉitaĵon, vi povas manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Nur ĉi tiujn ne manĝu el la remaĉantaj maĉitaĵon kaj el la havantaj disfenditajn hufojn: la kamelon, ĉar ĝi remaĉas maĉitaĵon, sed disfenditajn hufojn ĝi ne havas, malpura ĝi estas por vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'kaj la hirakon, ĉar ĝi remaĉas maĉitaĵon, sed disfenditajn hufojn ĝi ne havas, malpura ĝi estas por vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'kaj la leporon, ĉar ĝi remaĉas maĉitaĵon, sed disfenditajn hufojn ĝi ne havas, malpura ĝi estas por vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'kaj la porkon, ĉar ĝi havas disfenditajn hufojn kaj distranĉan sulkon sur la hufoj, sed ĝi ne remaĉas maĉitaĵon, malpura ĝi estas por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Ilian viandon ne manĝu kaj iliajn kadavrojn ne tuŝu, malpuraj ili estas por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Jenajn vi povas manĝi el ĉiuj bestoj, kiuj estas en la akvo: ĉiujn, kiuj havas naĝilojn kaj skvamojn en la akvo, en la maroj, kaj en la riveroj, ilin vi povas manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Sed ĉiuj, kiuj ne havas naĝilojn kaj skvamojn, en la maroj kaj en la riveroj, el ĉio, kio moviĝas en la akvo, kaj el ĉiuj estaĵoj, kiuj vivas en la akvo, ili estas abomenindaĵo por vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'kaj ili estu abomenindaĵo por vi, ilian viandon ne manĝu kaj iliajn kadavrojn abomenu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Ĉio en la akvo, kio ne havas naĝilojn kaj skvamojn, estas abomenindaĵo por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Kaj ĉi tiujn abomenu inter la birdoj, ili ne estu manĝataj, ili estas abomenindaĵoj: la aglon kaj la gipaeton kaj la pandionon');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'kaj la milvon kaj la falkon kun ĝia speco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'ĉiun korvon kun ĝia speco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'kaj la struton kaj la strigon kaj la mevon kaj la akcipitron kun ĝia speco');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'kaj la noktuon kaj la mergulon kaj la ibison');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'kaj la cignon kaj la pelikanon kaj la perknopteron');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'kaj la cikonion kaj la ardeon kun ĝia speco kaj la upupon kaj la vesperton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Ĉio moviĝanta, kio havas flugilojn kaj iras kvarpiede, estas abomenindaĵo por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Nur tiujn vi povas manĝi el ĉiuj moviĝantoj, kiuj havas flugilojn kaj iras kvarpiede: tiujn, kiuj havas genuojn super la kruroj, por salti per ili sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'La jenajn el ili vi povas manĝi: la akridon kun ĝia speco kaj la cikadon kun ĝia speco kaj la grilon kun ĝia speco kaj la lokuston kun ĝia speco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Sed ĉiu alia moviĝanto, kiu havas flugilojn kaj kvar piedojn, estas abomenindaĵo por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Kaj per la jenaj vi fariĝos malpuraj; ĉiu, kiu ektuŝos ilian kadavron, estos malpura ĝis la vespero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'kaj ĉiu, kiu portos kadavraĵon de ili, lavu siajn vestojn, kaj li estos malpura ĝis la vespero:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'ĉiu bruto, kiu havas disfenditajn hufojn, sed ne havas distranĉan sulkon kaj ne remaĉas maĉitaĵon, estas malpura por vi; ĉiu, kiu ektuŝos ilin, estos malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Kaj el ĉiuj bestoj kvarpiedaj ĉiuj, kiuj iras sur siaj plandoj, estas malpuraj por vi; ĉiu, kiu ektuŝos ilian kadavron, estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Kaj kiu portos kadavraĵon de ili, lavu siajn vestojn, kaj li estos malpura ĝis la vespero: malpuraj ili estas por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Kaj jen, kio estas malpura por vi inter la rampaĵoj, kiuj rampas sur la tero: la talpo kaj la muso kaj la lacerto kun ĝia speco');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'kaj la geko kaj la monitoro kaj la uromastiko kaj la skinko kaj la ĥameleono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Tiuj estas la malpuraj por vi inter ĉiuj rampaĵoj; ĉiu, kiu ektuŝos ilin post ilia morto, estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Kaj ĉio, sur kion falos io el ili malviva, estos malpura; ĉu ĝi estos ia ligna vazo, ĉu vesto, ĉu felo, ĉu sako, ĉu ia ilo, per kiu oni faras laboron-oni metu ĝin en akvon, kaj ĝi estos malpura ĝis la vespero, kaj tiam ĝi fariĝos pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Kaj se en ian argilan vazon io el ili falos internen, tiam ĉio, kio estas interne, fariĝos malpura; kaj la vazon rompu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Ĉiu manĝaĵo, kiun oni manĝas, se ŝprucos sur ĝin tia akvo, fariĝos malpura; kaj ĉiu trinkaĵo, kiun oni trinkas, en tia vazo fariĝos malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Kaj ĉio, sur kion falos io el ilia kadavraĵo, fariĝos malpura; se ĝi estos forno aŭ kaldrono, oni ĝin disrompu; malpuraj ili estas kaj malpuraj ili estu por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Nur fonto kaj puto kaj akvejoj restos puraj. Kiu ektuŝos ilian kadavraĵon, fariĝos malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Kaj se io el ilia kadavraĵo falos sur ian semeblan semon, kiu estas semota, ĝi restos pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Sed se estos verŝita akvo sur la semon kaj io el ilia kadavraĵo falos sur ĝin, tiam ĝi estos malpura por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Kaj se mortos ia bruto el tiuj, kiujn vi uzas por manĝi, tiam tiu, kiu ektuŝos ĝian kadavron, estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Kaj tiu, kiu manĝos ion el ĝia kadavraĵo, lavu siajn vestojn, kaj li estos malpura ĝis la vespero; kaj tiu, kiu portos ĝian kadavron, lavu siajn vestojn, kaj li estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Ĉia rampaĵo, kiu rampas sur la tero, estas abomenindaĵo, ĝi ne estu manĝata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Ĉio, kio rampas sur la ventro, kaj ĉio, kio iras sur kvar piedoj aŭ sur pli da piedoj, sed estas rampaĵo, kiu rampas sur la tero-ilin ne manĝu, ĉar ili estas abomenindaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Ne abomenindigu viajn animojn per iaj bestoj rampantaj, kaj ne malpuriĝu per ili, farante vin mem malpuraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Ĉar Mi, la Eternulo, estas via Dio; tial sanktigu vin kaj estu sanktaj, ĉar Mi estas sankta; kaj ne malpurigu viajn animojn per ia rampaĵo, kiu rampas sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Ĉar Mi estas la Eternulo, kiu elkondukis vin el la lando Egipta, por esti Dio por vi; estu do sanktaj, ĉar Mi estas sankta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Tio estas la leĝo pri la brutoj kaj pri la birdoj, kaj pri ĉiuj bestoj, moviĝantaj en la akvo, kaj pri ĉiuj bestoj, kiuj rampas sur la tero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'por fari diferencon inter la malpuraĵo kaj puraĵo, kaj inter la bestoj, kiujn oni povas manĝi, kaj la bestoj, kiujn oni devas ne manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Diru al la Izraelidoj jene: Se virino fruktigos semon kaj naskos knabeton, tiam ŝi estos malpura dum sep tagoj; kiel en la tagoj de sia monataĵa suferado ŝi estos malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Kaj en la oka tago oni cirkumcidu la karnon de lia prepucio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Tridek tri tagojn ŝi restu en la sango de sia puriĝo; nenion sanktan ŝi tuŝu kaj en la sanktejon ŝi ne venu, ĝis finiĝos la tagoj de ŝia puriĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Se ŝi naskos knabineton, tiam ŝi estu malpura dum du semajnoj kiel ĉe sia monataĵo, kaj sesdek ses tagojn ŝi restu en la sango de sia puriĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Kaj kiam finiĝos la tagoj de ŝia puriĝo post filo aŭ filino, ŝi alportu jaraĝan ŝafidon kiel bruloferon, kaj kolombidon aŭ turton kiel pekoferon, al la pordo de la tabernaklo de kunveno, al la pastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Kaj li tion alportos antaŭ la Eternulon kaj pekliberigos ŝin, kaj ŝi puriĝos de sia sangofluado. Tio estas la leĝo pri naskintino, ĉu de knabo, ĉu de knabino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Kaj se ŝi ne estas sufiĉe bonstata, por alporti ŝafidon, tiam ŝi prenu du turtojn aŭ du kolombidojn, unu kiel bruloferon kaj la duan kiel pekoferon; kaj la pastro pekliberigos ŝin, kaj ŝi puriĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Kaj la Eternulo ekparolis al Moseo kaj al Aaron, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Se ĉe iu homo sur la haŭto de lia korpo aperos ŝvelaĵo aŭ pustulo aŭ makulo tiamaniere, ke sur la haŭto de lia korpo fariĝos kvazaŭ infektaĵo de lepro, tiam oni alkonduku lin al la pastro Aaron aŭ al unu el liaj filoj, la pastroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Kaj la pastro rigardos la infektaĵon sur la haŭto de la korpo, kaj se li vidos, ke la haroj sur la infektaĵo fariĝis blankaj kaj la infektaĵo aspektas pli profunda ol la haŭto de lia korpo, tiam ĝi estas infektaĵo de lepro; kaj la pastro ĝin pririgardos, kaj deklaros, ke ĝi estas malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Kaj se ĝi estos blanka makulo sur la haŭto de lia korpo, sed ĝi ne aspektos pli profunda ol la haŭto, kaj la haroj sur ĝi ne fariĝis blankaj, tiam la pastro enŝlosu la infektiton por sep tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Kaj la pastro rigardos lin en la sepa tago, kaj se li vidos, ke la infektaĵo restis en la antaŭa stato, kaj ke la infektaĵo ne disvastiĝis sur la haŭto, tiam la pastro enŝlosu lin por pluaj sep tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Kaj la pastro rigardos lin en la plua sepa tago, kaj se li vidos, ke la infektaĵo fariĝis malpli rimarkebla kaj ĝi ne disvastiĝis sur la haŭto, tiam la pastro deklaru lin pura: ĝi estas likeno: li lavu siajn vestojn, kaj li estos pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Sed se la likeno tre disvastiĝis sur la haŭto, post kiam li montris sin al la pastro, ke tiu deklaru lin pura, tiam li duan fojon devas sin montri al la pastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Kaj se la pastro vidos, ke la likeno disvastiĝis sur la haŭto, tiam la pastro deklaros lin malpura: ĝi estas lepro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Se sur iu homo estos infektaĵo de lepro, oni alkonduku lin al la pastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Kaj se la pastro vidos, ke estas blanka ŝvelaĵo sur la haŭto kaj ke de ĝi la haroj fariĝis blankaj kaj sur la ŝvelaĵo estas kruda karno,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'tiam tio estas malnova lepro sur la haŭto de lia korpo; kaj la pastro deklaros lin malpura, ne enŝlosos lin; ĉar li estas malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Se la lepro disfloros sur la haŭto kaj la lepro kovros la tutan haŭton de la infektito, de lia kapo ĝis la piedoj, ĉion, kion povas vidi la okuloj de la pastro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'kaj la pastro vidos, ke la lepro kovris lian tutan korpon, tiam li deklaros la infektaĵon pura: ĉio fariĝis blanka, tial ĝi estas pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Sed en la tago, en kiu montriĝos sur li kruda karno, li estos malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Kiam la pastro vidos la krudan karnon, li deklaros lin malpura; la kruda karno estas malpura: ĝi estas lepro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Tamen se la kruda karno ŝanĝiĝos kaj fariĝos blanka, tiam li venu al la pastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Kaj kiam la pastro lin rigardos, kaj vidos, ke la infektaĵo aliformiĝis en blankaĵon, tiam la pastro deklaros la infektaĵon pura; li estos pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Kaj se sur ies korpo estos absceso kaj resaniĝos,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'kaj sur la loko de la absceso estos blanka ŝvelaĵo aŭ ruĝete-blanka makulo, tiam li devas sin montri al la pastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Kaj la pastro rigardos, kaj se li vidos, ke ĝi aspektas pli profunda ol la haŭto kaj ĝiaj haroj fariĝis blankaj, tiam la pastro deklaros lin malpura: ĝi estas infektaĵo de lepro, ĝi ekfloris en la absceso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Kaj se la pastro vidos, ke ne estas sur ĝi blankaj haroj kaj ĝi ne estas pli profunda ol la haŭto kaj ĝi estas ne tre rimarkebla, tiam la pastro enŝlosos lin por sep tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Sed se ĝi disvastiĝos sur la haŭto, tiam la pastro deklaros lin malpura: tio estas infektaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Se la makulo restos sur sia loko kaj ne disvastiĝos, ĝi estas brulumo de absceso; kaj la pastro deklaros ĝin pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Aŭ se sur la haŭto de lia korpo estos brulvundo kaj sur la karno de la brulvundo aperos makulo ruĝete-blanka aŭ blanka,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'kaj la pastro ĝin rigardos, kaj vidos, ke la haroj sur la makulo fariĝis blankaj kaj ĝi aspektas pli profunda ol la haŭto, tiam ĝi estas lepro, kiu ekfloris sur la brulvundo; kaj la pastro deklaros ĝin malpura: ĝi estas infektaĵo de lepro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Se la pastro vidos, ke sur la makulo ne estas blankaj haroj kaj ĝi ne estas pli profunda ol la haŭto kaj ĝi estas malmulte rimarkebla, tiam la pastro enŝlosos lin por sep tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Kaj la pastro lin rigardos en la sepa tago; se ĝi disvastiĝis sur la haŭto, tiam la pastro deklaros lin malpura: ĝi estas infektaĵo de lepro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Sed se la makulo restis sur sia loko kaj ne disvastiĝis sur la haŭto kaj estas malmulte rimarkebla, tiam ĝi estas ŝvelaĵo de la brulvundo; kaj la pastro deklaros lin pura, ĉar ĝi estas brulumo de la brulvundo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Se ĉe viro aŭ ĉe virino estos infektaĵo sur la kapo aŭ sur la barbo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'kaj la pastro rigardos la infektaĵon, kaj vidos, ke ĝi aspektas pli profunda ol la haŭto kaj sur ĝi estas haroj flavetaj kaj maldikaj, tiam la pastro deklaros lin malpura: tio estas favo, tio estas lepro de la kapo aŭ de la barbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Sed se la pastro rigardos la infektaĵon de la favo, kaj vidos, ke ĝi ne aspektas pli profunda ol la haŭto kaj ne estas sur ĝi nigraj haroj, tiam la pastro enŝlosos la favo-infektiton por sep tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Kaj la pastro rigardos la infektiton en la sepa tago, kaj se li vidos, ke la favo ne disvastiĝis kaj ne estas sur ĝi flavetaj haroj kaj la favaĵo ne aspektas pli profunda ol la haŭto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'tiam oni lin razu, sed la favaĵon oni ne razu; kaj la pastro enŝlosos la favulon denove por sep tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Kaj la pastro rigardos la favulon en la sepa tago, kaj se li vidos, ke la favo ne disvastiĝis sur la haŭto kaj ĝi ne aspektas pli profunda ol la haŭto, tiam la pastro deklaros lin pura; kaj li lavu siajn vestojn, kaj li estos pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Sed se la favo disvastiĝos sur la haŭto, post kiam li estis deklarita pura,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'kaj la pastro vidos, ke la favo disvastiĝis sur la haŭto, tiam la pastro ne serĉu flavetajn harojn: li estas malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Sed se la favo haltis en sia stato kaj nigraj haroj elkreskis sur ĝi, tiam la favo saniĝis; li estas pura, kaj la pastro deklaros lin pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Se sur la haŭto de la korpo de iu viro aŭ virino aperos makuloj, makuloj blankaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'kaj la pastro rigardos, kaj vidos, ke sur la haŭto de ilia korpo la makuloj estas pale-blankaj, tiam ĝi estas likeno, kiu ekfloris sur la haŭto; li estas pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Se ĉe iu elfalis la haroj sur la kapo, li estas senharulo; li estas pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Se lia kapo senhariĝas sur la antaŭa parto, li estas kalvulo; li estas pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Sed se sur la senharaĵo aŭ sur la kalvaĵo estos infektaĵo blanke- ruĝeta, tiam ĝi estas lepro, kiu ekfloris sur lia senharaĵo aŭ sur lia kalvaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Kaj la pastro lin rigardos, kaj se li vidos, ke la ŝvelaĵo de la infektaĵo estas blanke-ruĝeta sur lia senharaĵo aŭ sur lia kalvaĵo, kiel aspektas lepro sur la haŭto de la korpo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'tiam tio estas leprulo, li estas malpura; la pastro deklaru lin malpura: sur lia kapo estas lia infektaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Kaj la vestojn de la leprulo, sur kiu estos tiu infektaĵo, oni devas disŝiri, kaj lia kapo devas esti nekovrita, kaj ĝis la lipoj li devas esti ĉirkaŭkovrita, kaj li devas kriadi: Malpura, malpura!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'La tutan tempon, dum la infektaĵo estos sur li, li estu rigardata kiel malpura; malpura li estas; li estu izolita, ekster la tendaro estu lia loĝejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Kaj se estos infektaĵo de lepro sur vesto lana aŭ sur vesto lina,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'ĉu sur la fundamentaĵo, ĉu sur la enteksitaĵo, el lino aŭ el lano, ĉu sur felo, ĉu sur ia felaĵo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'kaj la infektaĵo estos verdeta aŭ ruĝeta sur la vesto aŭ sur la felo, sur la fundamentaĵo aŭ sur la enteksitaĵo aŭ sur la felaĵo, tiam ĝi estas infektaĵo de lepro, kaj oni devas montri ĝin al la pastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Kaj la pastro pririgardos la infektitaĵon kaj enŝlosos la infektitaĵon por sep tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Kaj li rigardos la infektitaĵon en la sepa tago; se li vidos, ke la infektaĵo disvastiĝis sur la vesto, aŭ sur la fundamentaĵo, aŭ sur la enteksitaĵo, aŭ sur ia felaĵo, tiam la infektaĵo estas lepro pereiga; ĝi estas malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Kaj oni forbruligu la veston aŭ la fundamentaĵon aŭ la enteksitaĵon el lano aŭ el lino aŭ ĉian felaĵon, sur kiu estos la infektaĵo; ĉar ĝi estas lepro pereiga, per fajro oni devas ĝin forbruligi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Sed se la pastro vidos, ke la infektaĵo ne disvastiĝis sur la vesto aŭ sur la fundamentaĵo aŭ sur la enteksitaĵo aŭ sur ia felaĵo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'tiam la pastro ordonos, ke oni lavu tion, sur kio estas la infektaĵo, kaj li enŝlosos ĝin denove por sep tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Kaj la pastro rigardos la infektaĵon post la lavo, kaj se li vidos, ke la infektaĵo ne ŝanĝis sian aspekton kaj la infektaĵo ne disvastiĝis, tiam ĝi estas malpura, per fajro oni ĝin forbruligu; ĝi estas penetriĝintaĵo sur la antaŭa aŭ malantaŭa flanko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Sed se la pastro vidos, ke la infektaĵo fariĝis malpli rimarkebla post la lavo, tiam li deŝiru ĝin de la vesto aŭ de la felo aŭ de la fundamentaĵo aŭ de la enteksitaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Se ĝi denove aperos sur la vesto aŭ sur la fundamentaĵo aŭ sur la enteksitaĵo aŭ sur ia felaĵo, tiam ĝi estas florantaĵo; per fajro oni forbruligu tion, sur kio estas la infektaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Sed la veston aŭ la fundamentaĵon aŭ la enteksitaĵon aŭ ĉian felaĵon, de kiuj post la lavo foriĝos la infektaĵo, oni lavu duan fojon, kaj ĝi estos pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Tio estas la leĝo pri la infektaĵo de lepro sur vesto lana aŭ lina, ĉu sur fundamentaĵo, ĉu sur enteksitaĵo, aŭ sur ia felaĵo, por deklari ĝin pura aŭ malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Jen estas la leĝo pri la leprulo, en la tago, kiam oni devos purigi lin: oni venigu lin al la pastro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'kaj la pastro eliros ekster la tendaron, kaj la pastro rigardos, kaj se li vidos, ke la infektaĵo de la lepro saniĝis ĉe la leprulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'tiam la pastro ordonos preni por la purigoto du birdojn vivajn, purajn, kaj cedran lignon kaj ruĝan ŝnureton kaj hisopon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Kaj la pastro ordonos buĉi unu birdon super argila vazo, super fluakvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Kaj la vivan birdon li prenos kaj ankaŭ la cedran lignon kaj la ruĝan ŝnureton kaj la hisopon, kaj li trempos ilin kune kun la viva birdo en la sango de la birdo buĉita super la fluakvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'Kaj li aspergos la purigaton je la lepro sep fojojn, kaj li deklaros lin pura, kaj li lasos la vivan birdon forflugi sur la kampon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Kaj la purigato lavos siajn vestojn kaj forrazos ĉiujn siajn harojn kaj banos sin en akvo, kaj li estos pura; kaj poste li iros en la tendaron kaj restos ekster sia tendo dum sep tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'En la sepa tago li forrazos ĉiujn siajn harojn, sian kapon kaj sian barbon kaj la brovojn de siaj okuloj, ĉiujn siajn harojn li forrazos, kaj li lavos siajn vestojn kaj banos sian korpon en akvo, kaj li fariĝos pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Kaj en la oka tago li prenos du ŝafidojn sendifektajn kaj unu ŝafidinon sendifektan, jaraĝan, kaj tri dekonojn de efo da delikata faruno, miksita kun oleo, kiel farunoferon, kaj unu log�on da oleo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Kaj la pastro puriganta starigos la homon purigatan kaj ilin antaŭ la Eternulo, ĉe la pordo de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Kaj la pastro prenos unu el la ŝafidoj kaj alportos ĝin kiel kulpoferon kune kun la log�o da oleo, kaj skuos tion kiel skuoferon antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Kaj li buĉos la ŝafidon sur la loko, sur kiu oni buĉas pekoferon kaj bruloferon, sur la sankta loko; ĉar, kiel la pekofero, la kulpofero apartenas al la pastro; ĝi estas plejsanktaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Kaj la pastro prenos iom el la sango de la kulpofero, kaj la pastro metos tion sur la malsupran randon de la dekstra orelo de la purigato kaj sur la dikan fingron de lia dekstra mano kaj sur la dikan fingron de lia dekstra piedo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Kaj la pastro prenos iom el la log�o da oleo kaj verŝos sur sian maldekstran manplaton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'Kaj la pastro trempos sian dekstran fingron en la oleo, kiu estos sur lia maldekstra manplato, kaj li aspergos per la oleo de sia fingro sep fojojn antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Kaj el la restaĵo de la oleo, kiu estos sur lia manplato, la pastro metos iom sur la malsupran randon de la dekstra orelo de la purigato kaj sur la dikan fingron de lia dekstra mano kaj sur la dikan fingron de lia dekstra piedo, sur la sangon de la kulpofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Kaj la restaĵon de la oleo, kiu estos sur la manplato de la pastro, ĉi tiu metos sur la kapon de la purigato; kaj la pastro pekliberigos lin antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Kaj la pastro plenumos la pekoferon, kaj li pekliberigos la purigaton koncerne lian malpurecon, kaj poste li buĉos la bruloferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Kaj la pastro metos la bruloferon kaj la farunoferon sur la altaron; kaj la pastro pekliberigos lin, kaj li estos pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Se li estas malriĉa kaj ne havas sufiĉe da bonstato, tiam li prenu unu ŝafidon, kiel pekoferon-skuataĵon, por pekliberiĝi, kaj unu dekonon de efo da delikata faruno, miksita kun oleo, kiel farunoferon, kaj log�on da oleo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'kaj du turtojn aŭ du kolombidojn, kiel lia stato permesos, kaj unu el ili estos pekofero kaj la dua estos brulofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Kaj li alportos ilin en la oka tago de sia purigado al la pastro, al la pordo de la tabernaklo de kunveno, antaŭ la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Kaj la pastro prenos la ŝafidon de la kulpofero kaj la log�on da oleo, kaj la pastro skuos ilin kiel skuoferon antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Kaj li buĉos la ŝafidon de la kulpofero, kaj la pastro prenos iom el la sango de la kulpofero kaj metos ĝin sur la malsupran randon de la dekstra orelo de la purigato kaj sur la dikan fingron de lia dekstra mano kaj sur la dikan fingron de lia dekstra piedo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Kaj el la oleo la pastro verŝos sur sian maldekstran manplaton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'Kaj la pastro aspergos per sia dekstra fingro, per la oleo, kiu estos sur lia maldekstra manplato, sep fojojn antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Kaj la pastro metos iom el la oleo, kiu estos sur lia manplato, sur la malsupran randon de la dekstra orelo de la purigato kaj sur la dikan fingron de lia dekstra mano kaj sur la dikan fingron de lia dekstra piedo, sur la lokon de la sango de la kulpofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Kaj la restaĵon de la oleo, kiu estos sur la manplato de la pastro, li metos sur la kapon de la purigato, por pekliberigi lin antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Kaj li faros el unu el la turtoj aŭ el la kolombidoj, laŭ la grado de lia bonstato,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'kiom permesos lia bonstato-el unu li faros pekoferon kaj el la dua li faros bruloferon kune kun la farunofero; kaj la pastro pekliberigos la purigaton antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Tio estas la leĝo pri persono, kiu havas infektaĵon de lepro kaj kiu ne estas sufiĉe bonstata dum sia puriĝado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Kaj la Eternulo ekparolis al Moseo kaj al Aaron, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Kiam vi venos en la landon Kanaanan, kiun Mi donas al vi kiel posedaĵon, kaj Mi ĵetus infektaĵon de lepro sur iun domon en la lando, kiun vi posedos,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'tiam tiu, al kiu apartenas la domo, devas veni, kaj diri al la pastro jene: Sur mia domo aperis io simila al infektaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Tiam la pastro ordonos, ke oni malplenigu la domon, antaŭ ol venos la pastro, por rigardi la infektaĵon, por ke ne malpuriĝu ĉio, kio estas en la domo; kaj post tio eniros la pastro, por ĉirkaŭrigardi la domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Kaj li rigardos la infektaĵon, kaj se li vidos, ke estas infektaĵo sur la muroj de la domo, kavetoj verdetaj aŭ ruĝetaj, kaj ili aspektas pli profundaj ol la supraĵo de la muro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'tiam la pastro eliros el la domo antaŭ la pordon de la domo, kaj li ŝlosos la domon por sep tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Kaj revenos la pastro en la sepa tago kaj rigardos; kaj se li vidos, ke la infektaĵo disvastiĝis sur la muroj de la domo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'tiam la pastro ordonos, ke oni elrompu la ŝtonojn, sur kiuj estas la infektaĵo, kaj oni ĵetu ilin ekster la urbon, sur lokon malpuran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Kaj la domon oni priskrapu interne ĉirkaŭe, kaj la kalkaĵon, kiun oni deskrapis, oni ĵetu ekster la urbon, sur lokon malpuran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Kaj oni prenu aliajn ŝtonojn kaj enmetu ilin sur la lokon de tiuj ŝtonoj, kaj oni prenu alian kalkaĵon kaj kalku la domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Se la infektaĵo reaperos kaj floros sur la domo, post kiam oni elrompis la ŝtonojn kaj ĉirkaŭskrapis la domon kaj kalkis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'kaj la pastro venos, kaj vidos, ke la infektaĵo disvastiĝis sur la domo, tiam tio estas pereiga lepro sur la domo; ĝi estas malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Kaj oni detruu la domon, ĝiajn ŝtonojn kaj lignon kaj la tutan kalkaĵon de la domo, kaj oni elportu tion ekster la urbon, sur lokon malpuran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Kaj kiu eniros en la domon, dum la tuta tempo, en kiu ĝi estos ŝlosita, tiu estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Kaj kiu dormis en tiu domo, tiu lavu siajn vestojn; kaj kiu manĝis en tiu domo, tiu lavu siajn vestojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Sed se la pastro venos, kaj vidos, ke la infektaĵo ne disvastiĝis sur la domo, post kiam oni kalkis la domon, tiam la pastro deklaros la domon pura, ĉar la infektaĵo saniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Tiam, por senpekigi la domon, li prenu du birdojn kaj cedran lignon kaj ruĝan ŝnureton kaj hisopon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'kaj li buĉu unu el la birdoj super argila vazo, super fluakvo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'kaj li prenu la cedran lignon kaj la hisopon kaj la ruĝan ŝnureton kaj la vivan birdon, kaj li trempu ilin en la sango de la birdo buĉita kaj en la fluakvo kaj aspergu la domon sep fojojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Kaj li senpekigos la domon per la sango de la birdo kaj per la fluakvo kaj per la viva birdo kaj per la cedra ligno kaj per la hisopo kaj per la ruĝa ŝnureto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Kaj li lasos la vivan birdon forflugi ekster la urbon, sur la kampon; kaj li pekliberigos la domon, kaj ĝi estos pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Tio estas la leĝo pri ĉiu infektaĵo de lepro kaj pri favo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'kaj pri lepro sur vesto kaj sur domo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'kaj pri ŝvelaĵo kaj pri likeno kaj pri makulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'por instrui, kiam oni devas deklari malpura kaj kiam oni devas deklari pura. Tio estas la leĝo pri la lepro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Kaj la Eternulo ekparolis al Moseo kaj al Aaron, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Parolu al la Izraelidoj, kaj diru al ili: Ĉiu, kiu havos elfluon el sia korpo, estos malpura pro sia elfluo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Kaj tia estos lia malpureco pro lia elfluo: kiam fluas el lia korpo lia elfluo aŭ kiam ŝtopiĝis lia korpo per lia elfluo, ĝi estas lia malpureco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Ĉiu lito, sur kiu kuŝos tiu, kiu havas elfluon, estos malpura; kaj ĉiu objekto, sur kiu li sidos, estos malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Kaj se iu ektuŝos lian liton, li lavu siajn vestojn kaj banu sin en akvo, kaj li estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Kaj se iu sidiĝos sur ia objekto, sur kiu sidis la elfluulo, li lavu siajn vestojn kaj banu sin en akvo, kaj li estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Kaj kiu ektuŝos la korpon de la elfluulo, tiu lavu siajn vestojn kaj banu sin en akvo, kaj li estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Se la elfluulo kraĉos sur purulon, tiam ĉi tiu lavu siajn vestojn kaj banu sin en akvo, kaj li estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Kaj ĉiu veturilo, sur kiu veturis la elfluulo, estos malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Kaj ĉiu, kiu ektuŝos ion, kio estis sub tiu, estos malpura ĝis la vespero; kaj kiu portos tion, tiu lavu siajn vestojn kaj banu sin en akvo, kaj li estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Kaj ĉiu, kiun ektuŝos la elfluulo, ne lavinte siajn manojn per akvo, lavu siajn vestojn kaj banu sin en akvo, kaj li estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Kaj argilan vazon, kiun ektuŝos la elfluulo, oni rompu; kaj ĉiun lignan vazon oni lavu per akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Kaj kiam la elfluulo puriĝos de sia elfluo, tiam li kalkulu al si sep tagojn de post la tago de sia puriĝo, kaj li lavu siajn vestojn kaj banu sian korpon en fluakvo, kaj li estos pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Kaj en la oka tago li prenu al si du turtojn aŭ du kolombidojn, kaj li venu antaŭ la Eternulon al la pordo de la tabernaklo de kunveno kaj donu ilin al la pastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Kaj la pastro oferfaros ilin, unu kiel pekoferon kaj la duan kiel bruloferon; kaj la pastro pekliberigos lin antaŭ la Eternulo koncerne lian elfluon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Se ĉe iu okazos elfluo de la semo, tiam li banu en akvo sian tutan korpon, kaj li estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Kaj ĉiun veston kaj ĉiun felon, sur kiun elverŝiĝis semo, oni lavu per akvo, kaj ĝi estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Kaj kiam kun virino kuŝis viro kun elverŝo de semo, tiam ili banu sin en akvo, kaj ili estos malpuraj ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Kaj kiam virino havos elfluon, sango fluos el ŝia korpo, tiam ŝi dum sep tagoj restu en sia malpureco; kaj ĉiu, kiu ŝin ektuŝos, estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Kaj ĉio, sur kio ŝi kuŝos dum sia malpureco, estos malpura; kaj ĉio, sur kio ŝi sidos, estos malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Kaj ĉiu, kiu ektuŝos ŝian liton, lavu siajn vestojn kaj banu sin en akvo, kaj li estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Kaj ĉiu, kiu ektuŝos ian objekton, sur kiu ŝi sidis, lavu siajn vestojn kaj banu sin en akvo, kaj li estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Kaj se io estos sur la lito, aŭ sur objekto, sur kiu ŝi sidis, kaj iu tion ektuŝos, tiam li estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Kaj se viro kuŝos kun ŝi kaj ŝia malpureco estos sur li, tiam li estos malpura dum sep tagoj; kaj ĉiu kuŝejo, sur kiu li kuŝos, estos malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Se ĉe virino fluos ŝia sango dum multaj tagoj ne en la tempo de ŝia monataĵo, aŭ se ŝi havos elfluon krom sia monataĵo, tiam dum la tuta tempo de elfluado de ŝia malpuraĵo, simile kiel dum la tempo de ŝia monataĵo, ŝi estos malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Ĉiu kuŝejo, sur kiu ŝi kuŝos dum la tuta tempo de sia elfluado, estos kiel la kuŝejo dum ŝia monataĵo; kaj ĉiu objekto, sur kiu ŝi sidos, estos malpura, simile al la malpureco dum ŝia monataĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Kaj ĉiu, kiu ektuŝos ilin, estos malpura; li lavu siajn vestojn kaj banu sin en akvo, kaj li estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Kaj kiam ŝi puriĝos de sia elfluo, tiam ŝi kalkulu al si sep tagojn, kaj poste ŝi estos pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Kaj en la oka tago ŝi prenu al si du turtojn aŭ du kolombidojn, kaj ŝi alportu ilin al la pastro, al la pordo de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Kaj la pastro oferfaros unu kiel pekoferon kaj la duan kiel bruloferon; kaj la pastro pekliberigos ŝin antaŭ la Eternulo koncerne la elfluon de ŝia malpureco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Tiel antaŭgardu la Izraelidojn kontraŭ ilia malpureco, por ke ili ne mortu en sia malpureco, malpurigante Mian loĝejon, kiu estas inter ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Tio estas la leĝo pri la havanto de elfluo, kaj pri tiu, kiu havas elverŝiĝon de semo, per kio li fariĝas malpura;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'kaj pri malsanulino pro sia monataĵo; kaj pri havanto de elfluo, ĉu tio estas viro, ĉu virino; kaj pri viro, kiu kuŝos kun malpurulino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Kaj la Eternulo ekparolis al Moseo post la morto de la du filoj de Aaron, kiam ili venis antaŭ la Eternulon kaj mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'Kaj la Eternulo diris al Moseo: Diru al via frato Aaron, ke li ne en ĉiu tempo eniru en la sanktejon malantaŭ la kurtenon, antaŭ la fermoplaton, kiu estas sur la kesto, por ke li ne mortu; ĉar en nubo Mi aperados super la fermoplato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Kun jeno Aaron venadu en la sanktejon: kun bovido por pekofero kaj kun virŝafo por brulofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Sanktan linan ĥitonon li surmetu sur sin, kaj linaj pantalonoj estu sur lia korpo, kaj per lina zono li zonu sin, kaj linan cidaron li havu sur la kapo: tio estas sanktaj vestoj. Kaj li banu en akvo sian korpon kaj surmetu ilin sur sin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Kaj de la komunumo de la Izraelidoj li prenu du kaprojn por pekofero kaj unu virŝafon por brulofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Kaj Aaron alportos sian bovidon de pekofero, kaj pekliberigos sin kaj sian domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Kaj li prenos la du kaprojn, kaj starigos ilin antaŭ la Eternulo, ĉe la pordo de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Kaj Aaron faros lotojn pri la du kaproj: unu loton por la Eternulo kaj la duan loton por Azazel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Kaj Aaron alportos la kapron, sur kiun falis la loto por la Eternulo, kaj li oferfaros ĝin kiel pekoferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Kaj la kapron, sur kiun falis la loto por Azazel, li starigu vivan antaŭ la Eternulo, por fari super ĝi pekliberigon kaj forsendi ĝin al Azazel en la dezerton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Kaj Aaron alportos sian bovidon de pekofero, kaj pekliberigos sin kaj sian domon, kaj buĉos sian bovidon de pekofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Kaj li prenos plenan incensujon da ardantaj karboj de la altaro, kiu staras antaŭ la Eternulo, kaj plenajn plenmanojn da bonodora pistita incenso, kaj li enportos tion malantaŭ la kurtenon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Kaj li metos la incenson sur la fajron antaŭ la Eternulon, kaj nubo de la incenso kovros la fermoplaton, kiu estas sur la kesto de atesto, por ke li ne mortu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Kaj li prenos iom el la sango de la bovido kaj aspergos per sia fingro la antaŭan parton de la fermoplato, kaj antaŭ la fermoplato li aspergos sep fojojn per la sango, kiu estos sur lia fingro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Kaj li buĉos la pekoferan kapron de la popolo, kaj li enportos ĝian sangon malantaŭ la kurtenon, kaj agos kun ĝia sango tiel same, kiel li agis kun la sango de la bovido, kaj li aspergos per ĝi sur la fermoplaton kaj antaŭ la fermoplato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Kaj li pekliberigos la sanktejon koncerne la malpuraĵojn de la Izraelidoj kaj iliajn krimojn, en ĉiuj iliaj pekoj; kaj tiel li agos kun la tabernaklo de kunveno, kiu estas inter ili, meze de iliaj malpuraĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Neniu homo estu en la tabernaklo de kunveno, kiam li eniros, por pekliberigi la sanktejon, ĝis li eliros. Kaj li pekliberigos sin kaj sian domon kaj la tutan komunumon de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Kaj li eliros al la altaro, kiu estas antaŭ la Eternulo, kaj pekliberigos ĝin; kaj li prenos iom el la sango de la bovido kaj el la sango de la kapro, kaj metos ĝin sur la kornojn de la altaro ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Kaj li aspergos ĝin sep fojojn per la sango, kiu estas sur lia fingro, kaj li purigos ĝin kaj sanktigos ĝin de la malpuraĵoj de la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Kiam li finos la pekliberigadon de la sanktejo kaj de la tabernaklo de kunveno kaj de la altaro, li alkondukos la vivan kapron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'kaj Aaron metos siajn ambaŭ manojn sur la kapon de la viva kapro kaj konfesos super ĝi ĉiujn malbonagojn de la Izraelidoj kaj ĉiujn iliajn krimojn kaj ĉiujn iliajn pekojn, kaj li metos ilin sur la kapon de la kapro kaj forsendos ĝin per speciala homo en la dezerton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Kaj la kapro forportos sur si ĉiujn iliajn malbonagojn en landon senkomunikiĝan; kaj li foririgos la kapron en la dezerton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Kaj Aaron eniros en la tabernaklon de kunveno, kaj demetos de si la linajn vestojn, kiujn li surmetis, enirante en la sanktejon, kaj li restigos ilin tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Kaj li banos sian korpon en akvo sur sankta loko, kaj li surmetos sur sin siajn vestojn, kaj eliros kaj oferfaros sian bruloferon kaj la bruloferon de la popolo, kaj li pekliberigos sin kaj la popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Kaj la sebon de la pekofero li fumbruligu sur la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Kaj tiu, kiu forkondukis la kapron por Azazel, lavu siajn vestojn kaj banu sian korpon en akvo, kaj poste li povas eniri en la tendaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Kaj la propekan bovidon kaj la propekan kapron, kies sango estis enportita, por pekliberigi la sanktejon, oni elportu ekster la tendaron, kaj oni forbruligu per fajro ilian felon kaj ilian karnon kaj ilian malpuraĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Kaj tiu, kiu forbruligis ilin, lavu siajn vestojn kaj banu sian korpon en akvo, kaj poste li povas eniri en la tendaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Kaj tio estu por vi eterna leĝo: en la sepa monato, en la deka tago de la monato, premu viajn animojn, kaj faru nenian laboron, nek la indiĝeno, nek la fremdulo, kiu loĝas inter vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Ĉar en tiu tago oni vin pekliberigos, por purigi vin; de ĉiuj viaj pekoj antaŭ la Eternulo vi fariĝos puraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Sabato de plena ripozo ĝi estu por vi; kaj premu viajn animojn; ĝi estu leĝo por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Pekliberigos la pastro, kiu estas sanktoleita, kaj kiu estas konsekrita, por pastri anstataŭ sia patro; kaj li surmetos sur sin la linajn vestojn, la sanktajn vestojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'Kaj li pekliberigos la plej sanktan sanktejon kaj la tabernaklon de kunveno, kaj la altaron li pekliberigos; kaj la pastrojn kaj la tutan popolon de la komunumo li pekliberigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Kaj tio estu por vi leĝo eterna: pekliberigi la Izraelidojn koncerne iliajn pekojn unu fojon en jaro. Kaj li faris, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Parolu al Aaron kaj al liaj filoj kaj al ĉiuj Izraelidoj, kaj diru al ili: Jen estas tio, kion la Eternulo ordonis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Se iu el la domo de Izrael buĉos bovon aŭ ŝafon aŭ kapron en la tendaro, aŭ se li buĉos ĝin ekster la tendaro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'kaj ne alkondukos ĝin al la pordo de la tabernaklo de kunveno, por prezenti ĝin kiel oferon al la Eternulo, antaŭ la loĝejo de la Eternulo, tiam tiu homo estos kulpa pri sango: li verŝis sangon, kaj tiu homo ekstermiĝos el inter sia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Por ke la Izraelidoj alkondukadu siajn buĉotojn, kiujn ili volas buĉi sur la kampo, kaj ili alkonduku ilin antaŭ la Eternulon, al la pordo de la tabernaklo de kunveno, al la pastro, kaj ili buĉu ilin kiel pacoferojn al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Kaj la pastro aspergos per la sango la altaron de la Eternulo ĉe la pordo de la tabernaklo de kunveno, kaj li fumbruligos la sebon kiel agrablan odoraĵon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Ili ne buĉu plu siajn oferbrutojn al la demonoj, kiujn ili malĉaste adoras. Leĝo eterna tio estu por ili en iliaj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Kaj diru al ili: Se iu el la domo de Izrael, aŭ el la fremduloj, kiuj loĝas inter ili, alportos bruloferon aŭ simplan oferon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'kaj ne alkondukos ĝin al la pordo de la tabernaklo de kunveno, por oferfari ĝin al la Eternulo, tiam tiu homo ekstermiĝos el sia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Se iu el la domo de Izrael, aŭ el la fremduloj, kiuj loĝas inter ili, manĝos ian sangon, tiam Mi turnos Mian vizaĝon kontraŭ tiun, kiu manĝis la sangon, kaj Mi ekstermos lin el inter lia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Ĉar la animo de korpo estas en la sango; kaj Mi destinis al vi ĉi tion por la altaro, por pekliberigi viajn animojn, ĉar la sango pekliberigas per la animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Tial Mi diris al la Izraelidoj: Neniu el vi manĝu sangon, kaj ankaŭ la fremdulo, kiu loĝas inter vi, ne manĝu sangon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Se iu el la Izraelidoj, aŭ el la fremduloj, kiuj loĝas inter ili, ĉaskaptos beston aŭ birdon, kiun oni povas manĝi, tiam li elfluigu ĝian sangon kaj kovru ĝin per polvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Ĉar la animo de ĉiu korpo estas ĝia sango, en ĝia animo ĝi estas. Tial Mi diris al la Izraelidoj: La sangon de ia korpo ne manĝu, ĉar la animo de ĉiu korpo estas ĝia sango; ĉiu, kiu ĝin manĝos, ekstermiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Kaj ĉiu, kiu manĝos mortintaĵon aŭ disŝiritaĵon, ĉu li estas indiĝeno, ĉu fremdulo, lavu siajn vestojn kaj banu sin en akvo, kaj li estos malpura ĝis la vespero, kaj poste li estos pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Sed se li ne lavos kaj sian korpon ne banos, li portos sur si sian malbonagon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Parolu al la Izraelidoj, kaj diru al ili: Mi estas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Laŭ la agoj de la lando Egipta, en kiu vi loĝis, ne agu; kaj laŭ la agoj de la lando Kanaana, en kiun Mi venigas vin, ne agu; laŭ iliaj leĝoj ne kondutu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Miajn decidojn plenumu kaj Miajn leĝojn observu, por konduti laŭ ili: Mi estas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Kaj observu Miajn leĝojn kaj Miajn decidojn, kiujn plenumante, la homo vivas per ili: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Neniu alproksimiĝu al iu sia korpoparencino, por malkovri nudecon: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'La nudecon de via patro kaj la nudecon de via patrino ne malkovru: ŝi estas via patrino, ne malkovru ŝian nudecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'La nudecon de via patredzino ne malkovru: ĝi estas la nudeco de via patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'La nudecon de via fratino, filino de via patro aŭ filino de via patrino, ĉu ŝi naskiĝis en la domo, ĉu ŝi naskiĝis ekstere, ne malkovru ilian nudecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'La nudecon de filino de via filo aŭ de filino de via filino, ne malkovru ilian nudecon; ĉar tio estas via nudeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'La nudecon de filino de via patredzino, kiu naskiĝis de via patro, ŝi estas via fratino, ne malkovru ŝian nudecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'La nudecon de fratino de via patro ne malkovru: ŝi estas korpoparencino de via patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'La nudecon de fratino de via patrino ne malkovru; ĉar ŝi estas korpoparencino de via patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'La nudecon de frato de via patro ne malkovru, al lia edzino ne alproksimiĝu: ŝi estas via onklino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'La nudecon de via bofilino ne malkovru: ŝi estas edzino de via filo, ne malkovru ŝian nudecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'La nudecon de edzino de via frato ne malkovru: ĝi estas nudeco de via frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'La nudecon de virino kaj de ŝia filino ne malkovru: filinon de ŝia filo kaj filinon de ŝia filino ne prenu, por malkovri ilian nudecon: ili estas korpoparencinoj; tio estas malĉasteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Kaj virinon kune kun ŝia fratino ne prenu kiel konkurantinon, por malkovri ŝian nudecon apud ŝi, dum ŝia vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Kaj al virino dum ŝia monata malpureco ne alproksimiĝu, por malkovri ŝian nudecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Kaj kun la edzino de via proksimulo ne kuŝu pro semo, malpuriĝante kun ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Kaj el via idaro ne fordonu oferon al Moleĥ, kaj ne malhonoru la nomon de via Dio: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Kaj kun virseksulo ne kuŝu, kiel oni kuŝas kun virino: tio estas abomenaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Kaj kun nenia bruto kuŝu, malpuriĝante per ĝi; kaj virino ne stariĝu antaŭ bruto, por kuniĝi: tio estas fiaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Ne malpuriĝu per ĉio ĉi tio; ĉar per ĉio ĉi tio malpuriĝis la popoloj, kiujn Mi forpelas de antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Kaj malpuriĝis la tero, kaj Mi postulas respondon pri ĝia malbonagado, kaj la tero elĵetas siajn loĝantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Sed vi observu Miajn leĝojn kaj Miajn decidojn, kaj ne faru iujn el tiuj abomenaĵoj, nek la indiĝeno, nek la fremdulo, kiu loĝas inter vi');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, '(ĉar ĉiujn tiujn abomenaĵojn faris la homoj de tiu tero, kiuj loĝis antaŭ vi, kaj la tero malpuriĝis);');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'por ke la tero ne elĵetu ankaŭ vin, kiam vi malpurigos ĝin, kiel ĝi elĵetis la popolon, kiu estis antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Ĉar se iu faros ion el ĉiuj tiuj abomenaĵoj, la farantoj ekstermiĝos el sia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Observu do Miajn ordonojn, por ke vi ne agu laŭ la abomenindaj leĝoj, laŭ kiuj oni agis antaŭ vi, kaj por ke vi ne malpuriĝu per ili: Mi estas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Parolu al la tuta komunumo de la Izraelidoj, kaj diru al ili: Sanktaj estu, ĉar sankta estas Mi, la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Ĉiu el vi timu sian patrinon kaj sian patron, kaj Miajn sabatojn observu: Mi estas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Ne turnu vin al idoloj, kaj diojn fanditajn ne faru al vi: Mi estas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Kaj kiam vi buĉos pacoferon al la Eternulo, buĉu ĝin, por akiri plaĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'En la tago de la oferado ĝi estu manĝata kaj en la morgaŭa tago; sed tion, kio restis ĝis la tria tago, oni forbruligu per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Sed se oni ĝin manĝos en la tria tago, ĝi estos abomenaĵo, ĝi ne plaĉos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Kaj ĝia manĝinto portos sur si sian malbonagon, ĉar li malhonoris la sanktaĵon de la Eternulo; kaj tiu animo ekstermiĝos el sia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Kaj kiam vi rikoltos rikoltaĵon de via tero, ne rikoltu ĉion ĝis la rando de via kampo, kaj la restaĵon de via rikoltaĵo ne forkolektu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Kaj vian vinberejon ne tute senberigu, kaj la falintajn berojn en via vinberejo ne forkolektu; por la malriĉulo kaj por la fremdulo restigu ilin: Mi estas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Ne ŝtelu, kaj ne mensogu, kaj ne trompu unu alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Kaj ne ĵuru per Mia nomo mensoge, malhonorante la nomon de via Dio: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Ne premu vian proksimulon kaj ne rabu; la pago por dungito ne noktorestu ĉe vi ĝis mateno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Ne malbenu surdulon, kaj antaŭ blindulo ne kuŝigu falilon; timu vian Dion: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Ne faru maljustaĵon en la juĝado, ne estu partia por malriĉulo kaj ne estimu potenculon; juste juĝu vian proksimulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Ne disportu kalumniojn inter via popolo, ne staru kontraŭ la sango de via proksimulo: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Ne malamu vian fraton en via koro; admonu vian proksimulon, por ke vi ne portu sur vi pekon pro li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Ne faru venĝon kaj ne portu koleron kontraŭ la filoj de via popolo; amu vian proksimulon kiel vin mem: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Miajn leĝojn observu. Vian bruton ne parigu miksospece, vian kampon ne prisemu miksospece, kaj veston miksospecan el lano kaj lino ne surmetu sur vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Se viro kuŝas kun virino pro semo, kaj ŝi estas sklavino, ordonita al viro, sed ankoraŭ ne elaĉetita aŭ ne ricevinta liberecon, tiam devas esti enketo, sed ili ne mortu, ĉar ŝi ne estis libera.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Li alportu pro sia kulpo al la Eternulo antaŭ la pordon de la tabernaklo de kunveno virŝafon kiel pekoferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Kaj la pastro pekliberigos lin per la virŝafo de pekofero antaŭ la Eternulo koncerne la pekon, kiun li pekis, kaj pardonita estos al li la peko, kiun li pekis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Kaj kiam vi venos en la landon kaj plantos ian arbon manĝodonan, tiam rigardu ĝiajn fruktojn kvazaŭ konsekritaj; dum tri jaroj ili estu por vi kvazaŭ konsekritaj, ili ne estu manĝataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'En la kvara jaro ĉiuj ĝiaj fruktoj estu sanktaj, dankoferoj al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Sed en la kvina jaro vi povas manĝi ĝiajn fruktojn, kolektante por vi ĝiajn produktaĵojn: Mi estas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Ne manĝu kun sango; ne aŭguru kaj ne antaŭdiru sorĉe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Ne ĉirkaŭtondu la flankojn de via kapo kaj ne fordifektu la flankojn de via barbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Entranĉojn pro mortinto ne faru sur via korpo kaj skribon enpikitan ne faru sur vi: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Ne senhonorigu vian filinon, prostituante ŝin; por ke la lando ne fariĝu prostituista kaj por ke la lando ne pleniĝu de malĉasteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Miajn sabatojn gardu kaj Mian sanktejon respektu: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Ne turnu vin al magiistoj nek al sorĉistoj, ne provu malpuriĝi per ili: Mi estas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Antaŭ grizulo stariĝu, kaj respektu la vizaĝon de maljunulo, kaj timu vian Dion: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Kaj se ekloĝos ĉe vi fremdulo en via lando, ne premu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Kiel indiĝeno el inter vi estu por vi la fremdulo, kiu ekloĝis ĉe vi, kaj amu lin kiel vin mem, ĉar fremduloj vi estis en la lando Egipta: Mi estas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Ne faru maljustaĵon en la juĝo, en la mezuro, en la peso, en la amplekso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Pesilo ĝusta, peziloj ĝustaj, efo ĝusta, kaj hino ĝusta estu ĉe vi: Mi estas la Eternulo, via Dio, kiu elkondukis vin el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Kaj observu ĉiujn Miajn leĝojn kaj ĉiujn Miajn decidojn kaj plenumu ilin: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Al la Izraelidoj diru: Ĉiu el la Izraelidoj, kaj el la fremduloj, kiuj loĝas inter la Izraelidoj, kiu donos iun el siaj idoj al Moleĥ, mortu; la popolo de la lando mortigu lin per ŝtonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Mi turnos Mian vizaĝon kontraŭ tiun homon, kaj Mi ekstermos lin el inter lia popolo pro tio, ke el siaj idoj li donis al Moleĥ, por malpurigi Mian sanktejon kaj malhonori Mian sanktan nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Kaj se la popolo de la lando kovros siajn okulojn for de tiu homo, kiam li donos iun el siaj idoj al Moleĥ, kaj ne mortigos lin:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'tiam Mi turnos Mian vizaĝon kontraŭ tiun homon kaj kontraŭ lian familion, kaj Mi ekstermos lin, kaj ĉiujn, kiuj malĉastos, imitante lin en la malĉastado por Moleĥ, el inter ilia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Kaj se iu animo sin turnos al magiistoj kaj sorĉistoj, por malĉasti sub ilia gvido, tiam Mi turnos Mian vizaĝon kontraŭ tiun animon kaj ekstermos ĝin el inter ĝia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Sanktigu vin kaj estu sanktaj, ĉar Mi estas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Kaj observu Miajn leĝojn kaj plenumu ilin: Mi estas la Eternulo, kiu sanktigas vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Ĉiu, kiu malbenas sian patron aŭ sian patrinon, estu mortigita: sian patron kaj sian patrinon li malbenis, lia sango estu sur li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Kaj se iu adultis kun edzinigita virino, se iu adultis kun la edzino de sia proksimulo, estu mortigitaj la adultinto kaj la adultintino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Kaj se iu kuŝis kun la edzino de sia patro, li malkovris la nudecon de sia patro; ambaŭ ili estu mortigitaj, ilia sango estu sur ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Kaj se iu kuŝis kun sia bofilino, ili ambaŭ estu mortigitaj: abomenaĵon ili faris, ilia sango estu sur ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Kaj se iu kuŝis kun viro kiel kun virino, abomenaĵon ili ambaŭ faris: ili estu mortigitaj, ilia sango estu sur ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Kaj se iu prenis virinon kaj ŝian patrinon, tio estas malĉastegeco: per fajro oni forbruligu lin kaj ilin, por ke ne estu malĉasteco inter vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Kaj se iu kuŝis kun bruto, li estu mortigita, kaj ankaŭ la bruton mortigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Kaj se virino alproksimiĝis al ia bruto, por sekskuniĝi kun ĝi, tiam mortigu la virinon kaj la bruton: ili estu mortigitaj, ilia sango estu sur ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Kaj se iu prenis sian fratinon, filinon de sia patro aŭ filinon de sia patrino, kaj li vidis ŝian nudecon kaj ŝi vidis lian nudecon, tio estas maldecaĵo; kaj ili devas esti ekstermitaj antaŭ la okuloj de sia popolo: la nudecon de sia fratino li malkovris, li portu sian pekon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Kaj se iu kuŝis kun virino dum ŝia malsano kaj malkovris ŝian nudecon, li vidatigis ŝian elfluejon kaj ŝi malkovris la elfluejon de sia sango: ili ambaŭ estu ekstermitaj el inter sia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Kaj la nudecon de la fratino de via patrino kaj de la fratino de via patro ne malkovru; ĉar li nudigis sian korpoparencinon, ili portu sian pekon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Kaj se iu kuŝis kun sia onklino, li malkovris la nudecon de sia onklo: ili portu sian pekon, ili mortos seninfanaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Kaj se iu prenis la edzinon de sia frato, tio estas malpuraĵo: la nudecon de sia frato li malkovris, seninfanaj ili estos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Kaj observu ĉiujn Miajn leĝojn kaj ĉiujn Miajn decidojn kaj plenumu ilin, por ke ne elĵetu vin la lando, en kiun Mi kondukas vin, por tie loĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Kaj ne agu laŭ la leĝoj de la popolo, kiun Mi forpelas de antaŭ vi, ĉar ĉion ĉi tion ili faris kaj Mi ekabomenis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Kaj Mi diris al vi: Vi heredos ilian landon, kaj Mi ĝin donos al vi, por ke vi posedu ĝin, la landon, en kiu fluas lakto kaj mielo. Mi estas la Eternulo, via Dio, kiu distingis vin el inter la popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Kaj faru diferencon inter bruto pura kaj malpura kaj inter birdo malpura kaj pura; kaj ne malpurigu viajn animojn per bruto kaj per birdo, kaj per ĉio, kio moviĝas sur la tero, kion Mi apartigis por vi, ke vi rigardu ilin kiel malpurajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Kaj estu antaŭ Mi sanktaj, ĉar sankta estas Mi, la Eternulo, kaj Mi apartigis vin el inter la popoloj, por ke vi estu Miaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Kaj viro aŭ virino, se ili estos magiistoj aŭ sorĉistoj, estu mortigitaj; per ŝtonoj oni ilin mortigu, ilia sango estu sur ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Kaj la Eternulo diris al Moseo: Parolu al la pastroj, la Aaronidoj, kaj diru al ili: Neniu el ili malpurigu sin per mortinto en sia popolo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'krom nur per sia proksima parenco, per sia patrino, per sia patro, per sia filo, per sia filino, kaj per sia frato;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'kaj per sia fratino-virgulino, proksima al li, kiu ne estis edzinigita, per ŝi li povas sin malpurigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Li ne malpurigu sin, kiel estro en sia popolo, malsanktigante sin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Ili ne faru al si senharaĵon sur sia kapo, kaj la flankojn de sia barbo ili ne razu, kaj sur sia korpo ili ne faru entranĉojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Sanktaj ili estu antaŭ sia Dio, kaj ili ne malsanktigu la nomon de sia Dio; ĉar la fajroferojn al la Eternulo, la panon al sia Dio ili alportas; tial ili estu sanktaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Virinon malĉastan aŭ senhonorigitan ili ne prenu, kaj virinon, forpuŝitan de sia edzo, ili ne prenu; ĉar pastro estas sankta al sia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Tial tenu lin sankte, ĉar la panon de via Dio li alportas; sankta li estu por vi, ĉar sankta estas Mi, la Eternulo, kiu sanktigas vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Se filino de pastro senhonoriĝis per malĉastado, ŝi senhonorigas sian patron: oni forbruligu ŝin per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'La granda pastro inter siaj fratoj, tiu, sur kies kapon estas verŝita la sankta oleo, kaj kiu estas konsekrita, por porti la vestojn, ne devas nudigi sian kapon nek disŝiri siajn vestojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Kaj al neniu mortinto li venu; eĉ per sia patro aŭ sia patrino li sin ne malpurigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Kaj el la sanktejo li ne eliru, kaj li ne malhonoru la sanktejon de sia Dio; ĉar sanktigo per la sankta oleo de lia Dio estas sur li: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Edzinon li prenu al si virgulinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Vidvinon, forpuŝitinon, senhonorigitinon, aŭ malĉastulinon li ne prenu, sed nur virgulinon el sia popolo li prenu kiel edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'Kaj li ne senhonorigu sian semon en sia popolo, ĉar Mi estas la Eternulo, kiu lin sanktigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Diru al Aaron jene: Se iu el via idaro en iliaj generacioj havos ian kriplaĵon, li ne alproksimiĝu, por alporti la panon de sia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Ĉar neniu, kiu havas ian kriplaĵon, alproksimiĝu: nek blindulo, nek lamulo, nek platnazulo, nek monstrulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'nek homo, kiu havas rompitan kruron aŭ rompitan brakon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'nek ĝibulo, nek ftizulo, nek makulokululo, nek aknulo, nek favulo, nek herniulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Neniu, kiu havas kriplaĵon el la idaro de Aaron la patro, alproksimiĝu, por alporti la fajroferojn de la Eternulo: li havas kriplaĵon, tial li ne alproksimiĝu, por alporti la panon de sia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'La panon de sia Dio el la plejsanktaĵoj kaj el la sanktaĵoj li povas manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Sed al la kurteno li ne aliru kaj al la altaro li ne alproksimiĝu, ĉar li havas kriplaĵon; por ke li ne malhonoru Miajn sanktejojn, ĉar Mi, la Eternulo, ilin sanktigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Kaj Moseo tion diris al Aaron kaj al liaj filoj kaj al ĉiuj Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Diru al Aaron kaj al liaj filoj, ke ili agu singarde koncerne la sanktaĵojn de la Izraelidoj, kaj ili ne malhonoru Mian sanktan nomon en tio, kion ili konsekras al Mi: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Diru al ili: Se iu en viaj generacioj el via tuta idaro aliros al la sanktaĵoj, kiujn la Izraelidoj konsekras al la Eternulo, kaj li havos sur si malpuraĵon, tiam tiu animo ekstermiĝos de antaŭ Mi: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Se iu el la idaro de Aaron havos lepron aŭ elfluon, tiu ne manĝu la sanktaĵojn, ĝis li puriĝos. Kiu ektuŝis iun, kiu malpuriĝis per mortinto, aŭ kiu havas elfluon de semo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'aŭ kiu ektuŝis ian rampaĵon, per kiu li malpuriĝis, aŭ iun homon, de kiu li malpuriĝis per ia lia malpuraĵo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'tiu, ektuŝinte tion, estos malpura ĝis la vespero, kaj li ne manĝu la sanktaĵojn, antaŭ ol li estos lavinta sian korpon per akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Post la subiro de la suno li fariĝos pura, kaj tiam li povas manĝi la sanktaĵojn, ĉar tio estas lia manĝaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Kadavraĵon kaj ion, kion disŝiris bestoj, li ne manĝu, por ke li ne malpuriĝu per tio: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Kaj ili observu Miajn ordonojn, por ke ili ne portu sur si pekon kaj ne mortu en ĝi, se ili tion malhonoros: Mi estas la Eternulo, kiu ilin sanktigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Kaj neniu laiko manĝu sanktaĵon; loĝanto ĉe pastro kaj ankaŭ dungito ne manĝu sanktaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Se pastro aĉetis homon per sia mono, tiu povas manĝi tion; kaj tiuj, kiuj naskiĝis en lia domo, povas manĝi lian panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Se filino de pastro edziniĝis kun viro laika, ŝi ne manĝu el la levataj sanktaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Sed se filino de pastro fariĝis vidvino aŭ eksedzino kaj ŝi ne havas infanojn, kaj ŝi revenis en la domon de sia patro, kiel ŝi estis en sia juneco, tiam ŝi povas manĝi la panon de sia patro; sed neniu laiko devas ĝin manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Se iu manĝis sanktaĵon per eraro, li aldonu al ĝi kvinonon de la valoro kaj redonu al la pastro la sanktaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Ili ne malhonoru la sanktaĵojn de la Izraelidoj, kiujn ili oferlevas al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'Kaj ili ne ŝarĝu sur sin la kulpon de la krimo, manĝante siajn sanktaĵojn; ĉar Mi estas la Eternulo, kiu ilin sanktigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Parolu al Aaron kaj al liaj filoj kaj al ĉiuj Izraelidoj, kaj diru al ili: Se iu el la domo de Izrael aŭ el la fremduloj inter Izrael alportas sian oferon, ĉu ĝi estas promesitaĵo aŭ ĉu ĝi estas ofero memvola, kiun ili alportas al la Eternulo kiel bruloferon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'tiam, por ke vi akiru plaĉon, ĝi devas esti sendifekta, virseksa, el grandaj brutoj, el ŝafoj, aŭ el kaproj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Neniun beston, kiu havas difektaĵon, alportu, ĉar ĝi ne akirigos al vi plaĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Kaj se iu alportas pacoferon al la Eternulo, por plenumi promeson aŭ memvole, el grandaj aŭ malgrandaj brutoj, ĝi estu sendifekta, por ke ĝi plaĉu; nenia difekto estu sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Beston blindan aŭ difektitan aŭ kriplan aŭ absceshavan aŭ aknohavan aŭ favan ne alportu al la Eternulo; kaj ne donu ilin kiel fajroferon sur la altaron de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Bovon aŭ ŝafon, kiu havas tro longajn aŭ tro mallongajn membrojn, vi povas alporti kiel oferon memvolan, sed kiel promesita ofero ĝi ne akiros plaĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Beston, kiu havas testikon kunpremitan, disbatitan, deŝiritan, aŭ fortranĉitan, ne alportu al la Eternulo, kaj en via lando ne faru tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Kaj el la manoj de alilandulo ne alportu tiajn kiel panon de via Dio; ĉar kriplaĵo estas sur ili, difektaĵo estas sur ili: ili ne akiros al vi plaĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Kiam naskiĝos bovido aŭ ŝafido aŭ kaprido, tiam ĝi restu dum sep tagoj sub sia patrino, kaj de post la oka tago kaj plue ĝi povas akiri plaĉon kiel fajrofero al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Sed nek bovon, nek ŝafon buĉu kun ĝia ido en unu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Se vi alportas dankoferon al la Eternulo, oferu ĝin tiel, ke ĝi akiru por vi plaĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'En la sama tago oni devas ĝin manĝi; ne lasu iom el ĝi ĝis la mateno: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Kaj observu Miajn ordonojn kaj plenumu ilin: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Kaj ne malhonoru Mian sanktan nomon, kaj Mi estu sankta inter la Izraelidoj: Mi estas la Eternulo, kiu sanktigas vin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'kiu elkondukis vin el la lando Egipta, por esti por vi Dio. Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Parolu al la Izraelidoj, kaj diru al ili: La festoj de la Eternulo, kiujn vi nomos sanktaj kunvenoj, jen ili estas, Miaj festoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Dum ses tagoj faru laboron; sed la sepan tagon estas sabato de ripozo, sankta kunveno, nenian laboron faru; ĝi estu sabato al la Eternulo en ĉiuj viaj loĝejoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Jen estas la festoj de la Eternulo, sanktaj kunvenoj, kiujn vi kunvokados en ilia tempo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'en la unua monato, en la dek-kvara tago de la monato, ĉirkaŭ la vespero, estas Pasko al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Kaj en la dek-kvina tago de tiu monato estas la festo de macoj al la Eternulo; dum sep tagoj manĝu macojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'En la unua tago estu ĉe vi sankta kunveno, faru nenian laboron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Kaj alportadu fajroferojn al la Eternulo dum sep tagoj; en la sepa tago estu sankta kunveno, faru nenian laboron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Parolu al la Izraelidoj, kaj diru al ili: Kiam vi venos en la landon, kiun Mi donas al vi, kaj vi rikoltos ĝian rikolton, tiam alportu al la pastro la unuan garbon el via rikolto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Kaj li skuos la garbon antaŭ la Eternulo, por ke vi akiru plaĉon; en la morgaŭa tago post la festo la pastro ĝin skuos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Kaj vi pretigu en la tago, kiam estos skuata via garbo, sendifektan ŝafidon jaraĝan kiel bruloferon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Kaj kun ĝi, kiel farunoferon, du dekonojn de efo da delikata faruno, miksita kun oleo, kiel fajroferon al la Eternulo, kiel agrablan odoraĵon, kaj kun ĝi, kiel verŝoferon, kvaronon de hino da vino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Kaj panon kaj rostitajn grajnojn kaj freŝajn grajnojn ne manĝu ĝis tiu tago mem, en kiu vi alportos la oferon al via Dio; ĝi estu eterna leĝo por viaj generacioj en ĉiuj viaj loĝejoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Kaj kalkulu al vi de post la morgaŭa tago post la festo, de post la tago, en kiu vi alportis la garbon por skuado, sep plenajn semajnojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Ĝis la morgaŭa tago post la sepa semajno kalkulu kvindek tagojn, kaj tiam vi alportos novan farunoferon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'El viaj loĝejoj alportu du panojn de skuofero; el du dekonoj de efo da delikata faruno ili estu; fermente ili estu bakitaj; tio estos unuaj produktoj por la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Kaj alportu kune kun la panoj sep ŝafidojn sendifektajn jaraĝajn kaj unu bovidon kaj du virŝafojn; ili estu brulofero al la Eternulo; kaj kune kun ili farunoferon kaj verŝoferon, fajroferon, agrablan odoraĵon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Pretigu ankaŭ unu kapron kiel pekoferon, kaj du jaraĝajn ŝafidojn kiel pacoferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Kaj la pastro skuu ilin kune kun la unuaproduktaj panoj kiel skuoferon antaŭ la Eternulo, kun la du ŝafidoj; ĝi estu sanktaĵo al la Eternulo por la pastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Kaj proklamu en tiu tago: sankta kunveno estu ĉe vi, faru nenian laboron; tio estu eterna leĝo en ĉiuj viaj loĝejoj en viaj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Kaj kiam vi rikoltos la rikolton en via lando, ne rikoltu ĉion ĝis la rando de via kampo dum via rikoltado, kaj la postrestaĵon de via rikolto ne kolektu; por la malriĉulo kaj por la fremdulo lasu tion: Mi estas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Diru al la Izraelidoj jene: En la sepa monato, en la unua tago de la monato, estu ĉe vi festo, memorigado per trumpetado, sankta kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Faru nenian laboron; kaj alportu fajroferon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Sed en la deka tago de tiu sepa monato estu tago de pekliberigo, sankta kunveno estu ĉe vi; kaj humiligu vian animon kaj alportu fajroferon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Kaj faru nenian laboron en tiu tago, ĉar ĝi estas tago de pekliberigo, por pekliberigi vin antaŭ la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Ĉiu animo, kiu ne humiligos sin en tiu tago, ekstermiĝos el inter sia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Se iu animo faros ian laboron en tiu tago, Mi ekstermos tiun animon el inter ĝia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Faru nenian laboron; ĝi estu eterna leĝo en viaj generacioj en ĉiuj viaj loĝejoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Granda sabato ĝi estu por vi; kaj humiligu viajn animojn; vespere en la naŭa tago de la monato, de vespero ĝis vespero festu vian sabaton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Diru al la Izraelidoj jene: Komencante de la dek-kvina tago de tiu sepa monato estu festo de laŭboj dum sep tagoj al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'En la unua tago estu sankta kunveno, faru nenian laboron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Dum sep tagoj alportadu fajroferojn al la Eternulo; en la oka tago estu ĉe vi sankta kunveno, kaj alportu fajroferon al la Eternulo; ferma festo ĝi estas, faru nenian laboron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Tio estas la festoj de la Eternulo, kiujn vi nomos sanktaj kunvenoj, por alporti fajroferon al la Eternulo, bruloferon kaj farunoferon, buĉoferon kaj verŝoferojn, ĉiun en ĝia tago;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'krom la sabatoj de la Eternulo kaj krom viaj donoj kaj krom ĉiuj viaj promesoj, kaj krom ĉiuj viaj memvolaj oferoj, kiujn vi donos al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Kaj en la dek-kvina tago de la sepa monato, kiam vi kolektos la produktaĵon de la tero, festu la feston de la Eternulo dum sep tagoj; en la unua tago estu festo kaj en la oka tago estu festo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Kaj prenu al vi en la unua tago fruktojn de belaj arboj, branĉojn de palmoj kaj branĉojn de densaj arboj kaj de apudriveraj salikoj; kaj gajigu vin antaŭ la Eternulo, via Dio, dum sep tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Kaj festu tiun feston de la Eternulo dum sep tagoj en la jaro; eterna leĝo tio estu en viaj generacioj; en la sepa monato festu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'En laŭboj loĝu dum sep tagoj, ĉiu indiĝeno en Izrael loĝu en laŭboj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'por ke sciu viaj generacioj, ke en laŭboj Mi loĝigis la Izraelidojn, kiam Mi elkondukis ilin el la lando Egipta: Mi estas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Kaj Moseo diris pri la festoj de la Eternulo al la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Ordonu al la Izraelidoj, ke ili alportadu al vi oleon olivan, puran, pistitan, por lumigado, por ke lucerno brulu ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Ekster la kurteno de la atesto en la tabernaklo de kunveno Aaron ĝin ĉiam aranĝadu de vespero ĝis mateno antaŭ la Eternulo; tio estu eterna leĝo en viaj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Sur la pure ora kandelabro li aranĝadu la lumojn antaŭ la Eternulo ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Kaj prenu delikatan farunon kaj baku el ĝi dek du panojn; el du dekonoj de efo estu ĉiu pano;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'kaj aranĝu ilin en du vicoj, po ses en vico, sur la pure ora tablo antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Kaj metu sur ĉiun vicon puran olibanon, kaj tio estos ĉe la pano memorofero, fajrofero al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'En ĉiu tago sabata oni ĉiam aranĝu tion antaŭ la Eternulo; de la Izraelidoj ĝi estu eterna interligo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Kaj ĝi estu por Aaron kaj por liaj filoj, kaj ili manĝu ĝin sur sankta loko, ĉar tio estas plejsanktaĵo por li el la fajroferoj de la Eternulo; tio estu eterna leĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Kaj eliris iu filo de virino Izraelida kaj de viro Egipta inter la Izraelidojn, kaj en la tendaro la filo de la Izraelidino ekkverelis kun Izraelido;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'kaj la filo de la Izraelidino insultis la nomon de Dio kaj blasfemis; kaj oni venigis lin al Moseo. La nomo de lia patrino estis Ŝelomit, filino de Dibri el la tribo de Dan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Kaj oni metis lin en malliberejon, ĝis oni ricevos precizan decidon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Elirigu la blasfeminton ekster la tendaron; kaj ĉiuj, kiuj aŭdis, metu siajn manojn sur lian kapon, kaj la tuta komunumo mortigu lin per ŝtonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Kaj al la Izraelidoj diru jene: Ĉiu, kiu blasfemos sian Dion, portos sian pekon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Kiu insultas la nomon de la Eternulo, tiu estu mortigita; per ŝtonoj mortigu lin la tuta komunumo. Ĉu fremdulo, ĉu indiĝeno, se li blasfemos la nomon de la Eternulo, estu mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Se iu mortigos iun homon, oni lin mortigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Kiu mortigos bruton, tiu pagu pro ĝi: beston pro besto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Se iu faris difekton al sia proksimulo, oni faru al li tiel, kiel li faris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'rompon pro rompo, okulon pro okulo, denton pro dento; kian difekton li faris al homo, tian oni faru al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Kaj kiu mortigis bruton, pagu pro ĝi; sed kiu mortigis homon, estu mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'La sama juĝo estu ĉe vi ĉu por fremdulo, ĉu por indiĝeno; ĉar Mi estas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Kaj Moseo diris al la Izraelidoj, kaj oni elirigis la blasfeminton ekster la tendaron kaj mortigis lin per ŝtonoj; kaj la Izraelidoj faris, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Kaj la Eternulo ekparolis al Moseo sur la monto Sinaj, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Parolu al la Izraelidoj, kaj diru al ili: Kiam vi venos en la landon, kiun Mi donas al vi, tiam la tero ripozu sabaton al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Dum ses jaroj prisemu vian kampon kaj dum ses jaroj pritranĉu vian vinberĝardenon kaj kolektu iliajn produktaĵojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'sed en la sepa jaro estu sabato de ripozo por la tero, sabato al la Eternulo: vian kampon ne prisemu kaj vian vinberĝardenon ne pritranĉu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Kio mem elkreskos post via rikolto, tion ne rikoltu, kaj la vinberojn de viaj nepritranĉitaj branĉoj ne deprenu: tio estu jaro de ripozo por la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Kaj la produktaĵoj de la sabata tero estu manĝaĵo por vi ĉiuj: por vi, por via sklavo, por via sklavino, kaj por via dungito kaj por via kunloĝanto, kiuj loĝas ĉe vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'Kaj por via bruto kaj por la bestoj, kiuj estas sur via tero, ĉiuj ĝiaj produktaĵoj estu kiel manĝaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Kaj kalkulu al vi sep sabatajn jarojn, sep fojojn po sep jaroj, ke vi havu en la sep sabataj jaroj kvardek naŭ jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Kaj proklamu per trumpetado en la sepa monato, en la deka tago de la monato; en la tago de pekliberigo trumpetu en via tuta lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Kaj sanktigu la kvindekan jaron, kaj proklamu liberecon en la lando por ĉiuj ĝiaj loĝantoj: jubileo ĝi estu por vi; kaj revenu ĉiu al sia posedaĵo, kaj ĉiu revenu al sia familio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Jubileo ĝi estu por vi, la kvindeka jaro; ne semu, kaj ne rikoltu tion, kio mem elkreskis, kaj ne deprenu la berojn de la nepritranĉitaj vinberbranĉoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Ĉar jubileo ĝi estas, sankta ĝi estu por vi; de la kampo manĝu ĝiajn produktaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'En tiu jubilea jaro ĉiu revenu al sia posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Kaj se vi ion vendos al via proksimulo, aŭ se vi aĉetos el la manoj de via proksimulo, unu ne malprofitigu la alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Laŭ la kalkulo de la jaroj post la jubileo aĉetu de via proksimulo; laŭ la kalkulo de la jaroj de produktado li vendu al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Laŭ la multeco de la jaroj pligrandigu la prezon, kaj ju pli malmultaj estas la jaroj, des pli malgrandigu la prezon; ĉar la nombron de la rikoltoj li vendas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Kaj ne malprofitigu unu la alian, kaj timu vian Dion; ĉar Mi estas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Kaj plenumu Miajn leĝojn, kaj Miajn decidojn observu kaj plenumu ilin, kaj tiam vi loĝos en la lando sendanĝere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Kaj la tero donados siajn fruktojn, kaj vi manĝados ĝissate, kaj vi loĝos sur ĝi sendanĝere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Kaj se vi diros: Kion ni manĝos en la sepa jaro, kiam ni ne semos kaj ne enkolektos niajn produktaĵojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Mi sendos al vi Mian benon en la sesa jaro, kaj ĝi alportos produktaĵojn por tri jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Kaj vi semos en la oka jaro, sed vi manĝos la produktaĵojn malnovajn ĝis la naŭa jaro; ĝis venos la rikolto de ĝiaj produktaĵoj, vi manĝos malnovajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Kaj la tero ne estu vendata por ĉiam; ĉar al Mi apartenas la tero, ĉar vi estas fremduloj kaj pasloĝantoj ĉe Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Kaj sur la tuta tero de via posedado permesu liberigon de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Se via frato malriĉiĝos kaj vendos ion de sia posedaĵo, sed venos reaĉetanto, lia proksima parenco, tiam li povu reaĉeti la venditaĵon de sia frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Kaj se iu ne trovos por si reaĉetanton, sed li mem fariĝos sufiĉe bonstata, kaj havos tiom, ke li povos reaĉeti,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'tiam li kalkulu la jarojn de la venditeco, kaj la restaĵojn li redonu al tiu, al kiu li vendis; kaj li revenu al sia posedado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Sed se li ne havos sufiĉe, por redoni al li, tiam lia venditaĵo restu en la manoj de la aĉetinto ĝis la jubilea jaro; sed en la jubilea jaro ĝi foriru, kaj li revenu al sia posedado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Kaj se iu vendos loĝeblan domon en urbo, kiun ĉirkaŭas muro, tiam ĝi estas reaĉetebla ĝis la fino de jaro post ĝia vendo; en la daŭro de jaro ĝi estas reaĉetebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Sed se ĝi ne estos reaĉetita antaŭ la fino de tuta jaro, tiam la domo, kiu estas en urbo ĉirkaŭita de muro, restas por ĉiam ĉe ĝia aĉetinto en liaj generacioj; ĝi ne foriras en jaro jubilea.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'La domoj en la vilaĝoj ne ĉirkaŭitaj de muro estu kalkulataj kiel kampo da tero; oni povas ilin reaĉeti, kaj en jubilea jaro ili foriras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Koncerne la urbojn de la Levidoj, la domojn en la urboj de ilia posedado, la Levidoj ĉiam havas la rajton de reaĉeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Se iu elaĉetos ion de la Levidoj, tiam la vendita domo aŭ la urba posedaĵo foriras en la jubilea jaro; ĉar la domoj en la urboj de la Levidoj estas ilia posedaĵo inter la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Kaj la kampoj ĉirkaŭ iliaj urboj ne estu vendataj, ĉar tio estas ilia porĉiama posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Se via frato malriĉiĝos kaj lia brako malfortiĝos apud vi, tiam subtenu lin; ĉu li estas fremdulo, ĉu pasloĝanto, li vivu kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Ne prenu de li procentojn nek alkreskon, kaj timu vian Dion, ke via frato vivu kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Donante al li monon, ne postulu de li procentojn, kaj donante al li manĝaĵon, ne postulu ĝian pligrandigon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Mi estas la Eternulo, via Dio, kiu elkondukis vin el la lando Egipta, por doni al vi la landon Kanaanan, por esti via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Kiam malriĉiĝos apud vi via frato kaj li estos vendita al vi, tiam ne ŝarĝu lin per laborado sklava;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'kiel dungito, kiel pasloĝanto li estu ĉe vi; ĝis la jubilea jaro li servu ĉe vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'kaj tiam li foriru de vi, li mem kaj ankaŭ liaj filoj kun li, kaj li revenu al sia familio kaj al la posedaĵo de siaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Ĉar ili estas Miaj sklavoj, kiujn Mi elkondukis el la lando Egipta; ili ne estu vendataj, kiel oni vendas sklavojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Ne regu ilin kun krueleco, kaj timu vian Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Via sklavo kaj via sklavino, kiujn vi povas havi, devas esti el la popoloj, kiuj estas ĉirkaŭ vi; el ili aĉetu sklavon kaj sklavinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Ankaŭ el la idoj de la pasloĝantoj, kiuj fremdule loĝas ĉe vi, el ili vi povas aĉeti, kaj el iliaj familioj, kiuj estas ĉe vi kaj kiuj naskiĝis en via lando; ili povas esti via posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Kaj vi povas transdoni ilin herede al viaj filoj post vi kiel porĉiaman posedaĵon; ilin vi povas uzi kiel sklavojn, sed super viaj fratoj, super Izraelidoj, ne regu unuj super aliaj kun krueleco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Kaj se fremdulo aŭ pasloĝanto ĉe vi estos bonstata, kaj via frato malriĉiĝos antaŭ li kaj vendos sin al la fremdulo aŭ pasloĝanto ĉe vi aŭ al ido de familio de fremdulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'post la vendo restas al li rajto de elaĉeto; iu el liaj fratoj elaĉetu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Aŭ lia onklo, aŭ filo de lia onklo elaĉetu lin, aŭ iu el lia parencaro, el lia familio elaĉetu lin; aŭ se lia stato sufiĉos, li mem sin elaĉetos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Kaj li faru prikalkulon kun sia aĉetinto, de la jaro, en kiu li sin vendis, ĝis la jaro jubilea; kaj la mono, pro kiu li vendis sin, devas esti redonita laŭ la nombro de la jaroj; kiel dungito li estu ĉe li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Se restas ankoraŭ multe da jaroj, tiam proporcie al ili li redonu elaĉeton pro si el la mono, pro kiu li estis aĉetita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Se restas malmulte da jaroj ĝis la jubilea jaro, tiam li kalkulu tion al li kaj proporcie al la jaroj li redonu pro si elaĉeton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Kiel laŭjara dungito li estu ĉe li, kaj ĉi tiu ne regu lin kruele antaŭ viaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Kaj se li ne elaĉetiĝos tiamaniere, tiam li foriru en la jubilea jaro, li kune kun siaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Ĉar Miaj sklavoj estas la Izraelidoj; ili estas Miaj sklavoj, kiujn Mi elkondukis el la lando Egipta: Mi estas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Ne faru al vi idolojn, kaj figurojn kaj statuojn ne starigu ĉe vi, kaj ŝtonojn kun bildoj ne kuŝigu en via lando, por adorkliniĝi super ili: ĉar Mi estas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Miajn sabatojn observu, kaj Mian sanktejon respektegu: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Se vi agos laŭ Miaj leĝoj kaj observos Miajn ordonojn kaj plenumos ilin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'tiam Mi donos al vi pluvojn iliatempe, kaj la tero donos siajn produktaĵojn, kaj la kampa arbo donos siajn fruktojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Kaj la tempo de draŝado daŭros ĉe vi ĝis la enkolektado de la vinberoj, kaj la enkolektado de vinberoj daŭros ĝis la semado, kaj vi manĝos vian panon sate kaj vi loĝos sendanĝere en via lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Kaj Mi donos pacon al via lando, kaj kiam vi kuŝos, neniu vin timigos; kaj Mi forigos la malbonajn bestojn el la lando, kaj glavo ne trapasos vian landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Kaj vi pelos viajn malamikojn, kaj ili falos antaŭ vi de glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Kaj kvin al vi pelos centon, kaj cent el vi pelos dekmilon; kaj viaj malamikoj falos antaŭ vi de glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Kaj Mi turnos Min al vi kaj kreskigos vin kaj multigos vin, kaj Mi fortikigos Mian interligon kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Kaj vi manĝos grenon malnovan pasintjaran, kaj vi elportos la malnovan pro la nova.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Kaj Mi starigos Mian loĝejon inter vi, kaj Mia animo vin ne abomenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Kaj Mi iros inter vi, kaj Mi estos via Dio, kaj vi estos Mia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Mi estas la Eternulo, via Dio, kiu elkondukis vin el la lando Egipta, por ke vi ne estu iliaj sklavoj; kaj Mi rompis la bastonojn de via jugo kaj ekirigis vin kun levita kapo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Sed se vi ne obeos Min kaj ne faros ĉiujn ĉi tiujn ordonojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'kaj se vi malestimos Miajn leĝojn kaj se via animo abomenos Miajn decidojn, kaj vi ne plenumos ĉiujn Miajn ordonojn, rompante Mian interligon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'tiam ankaŭ Mi faros al vi tion: Mi sendos sur vin teruron, maldikiĝon, kaj febron, kiuj konsumas la okulojn kaj senfortigas la animon; kaj vi semos viajn semojn vane, ilin manĝos viaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Kaj Mi turnos Mian vizaĝon kontraŭ vin, kaj vi falos antaŭ viaj malamikoj, kaj regos vin viaj malamantoj, kaj vi kuros, kiam neniu pelos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Kaj se vi malgraŭ ĉi tio ne obeos Min, tiam Mi sepoble pligrandigos la punon pro viaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Kaj Mi rompos vian fieran obstinecon, kaj Mi faros vian ĉielon kiel fero kaj vian teron kiel kupro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Kaj vane konsumiĝos via forto; via tero ne donos siajn produktaĵojn, kaj la arboj de la tero ne donos siajn fruktojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Kaj se vi malgraŭ tio spitos Min kaj ne volos obei Min, tiam Mi aldonos sepoble da frapoj laŭ viaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Kaj Mi venigos sur vin la sovaĝajn bestojn, kaj ili formanĝos viajn infanojn kaj ekstermos viajn brutojn kaj malmultigos vin tiel, ke viaj vojoj dezertiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Se ankaŭ per tio vi ne humiliĝos, sed plue agos kontraŭ Mi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'tiam ankaŭ Mi agos kontraŭ vi, kaj Mi ankaŭ frapos vin sepoble pro viaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Kaj Mi venigos sur vin venĝan glavon, kiu venĝos pro la interligo; kaj vi kolektiĝos en viaj urboj, kaj Mi sendos peston en vian mezon, kaj vi estos fordonitaj en la manojn de la malamiko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Kiam Mi rompos al vi la apogon de la pano, tiam dek virinoj bakos vian panon en unu forno kaj redonos vian panon pesante, kaj vi manĝos kaj ne satiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Kaj se vi malgraŭ tio ne obeos Min, kaj spitos Min:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'tiam Mi iros kontraŭ vin kolere, kaj Mi punos vin sepoble pro viaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Kaj vi manĝos la karnon de viaj filoj, kaj la karnon de viaj filinoj vi manĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Kaj Mi detruos viajn altaĵojn kaj ruinigos viajn kolonojn de la suno, kaj Mi ĵetos viajn kadavrojn sur la rompitaĵojn de viaj idoloj, kaj Mia animo abomenos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Kaj Mi faros el viaj urboj dezerton, kaj Mi ruinigos viajn sanktejojn, kaj Mi ne flaros viajn agrablajn odoraĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Kaj Mi dezertigos la teron, ke miregos pri ĝi viaj malamikoj, kiuj ekloĝos sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Kaj vin Mi disĵetos inter la popolojn, kaj Mi nudigos post vi glavon; kaj via tero estos dezerta kaj viaj urboj estos ruinigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Tiam la tero ricevos kontentigon pri siaj sabatoj dum la tuta tempo de sia dezerteco, kiam vi estos en la lando de viaj malamikoj; tiam ripozos la tero kaj kontentigos sin pri siaj sabatoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Dum la tuta tempo de dezerteco ĝi ripozos, kiom ĝi ne ripozis en viaj sabatoj, kiam vi loĝis sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Kaj al la restintoj el vi Mi sendos timon en ilian koron en la lando de iliaj malamikoj; kaj pelos ilin brueto de falanta folio, kaj ili kuros, kiel oni kuras de glavo, kaj ili falos, kiam neniu ilin persekutos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Kaj ili falos unu sur alian, kiel de glavo, dum neniu ilin pelos; kaj vi ne havos forton por stari antaŭ viaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Kaj vi pereos inter la popoloj, kaj formanĝos vin la lando de viaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Kaj la restintoj el vi senfortiĝos pro siaj pekoj en la landoj de viaj malamikoj, kaj ankaŭ pro la pekoj de siaj patroj ili senfortiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Tiam ili konfesos sian kulpon kaj la kulpon de siaj patroj en la malbonagoj, kiujn ili faris kontraŭ Mi kaj pri kio ili spitis Min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'Ankaŭ Mi iris kontraŭ ilin kaj envenigis ilin en la landon de iliaj malamikoj; kaj se tiam humiliĝos ilia koro ne cirkumcidita kaj se ili donos kontentigon pri siaj pekoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'tiam Mi rememoros Mian interligon kun Jakob, kaj Mian interligon kun Isaak kaj Mian interligon kun Abraham Mi rememoros, kaj la landon Mi rememoros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'La lando estos forlasita de ili kaj ricevos kontentigon pri siaj sabatoj, kiam ĝi dezertiĝos post ili; kaj ili donos kontentigon pri siaj kulpoj, ĉar ili malrespektis Miajn decidojn kaj Miajn leĝojn ilia animo abomenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Kaj tamen, kiam ili estos en la lando de siaj malamikoj, Mi ne malestimos ilin, kaj ne abomenos ilin tiom, por ekstermi ilin, por neniigi Mian interligon kun ili; ĉar Mi estas la Eternulo, ilia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Kaj Mi rememoros por ili la interligon kun la antaŭuloj, kiujn Mi elkondukis el la lando Egipta antaŭ la okuloj de la popoloj, por esti ilia Dio: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Tio estas la leĝoj kaj decidoj kaj instruoj, kiujn starigis la Eternulo inter Si kaj la Izraelidoj sur la monto Sinaj per Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Parolu al la Izraelidoj, kaj diru al ili: Se iu faros sanktan promeson dediĉi animon laŭ via taksado al la Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'tiam via taksado devas esti: pro virseksulo en la aĝo de dudek jaroj ĝis sesdek jaroj via taksado estu kvindek sikloj da arĝento laŭ la sankta siklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Kaj se tio estos virino, tiam via taksado estu tridek sikloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Kaj se tio estos aĝulo de kvin jaroj ĝis dudek jaroj, via taksado estu pro viro dudek sikloj kaj pro virino dek sikloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Se tio estos aĝulo de unu monato ĝis kvin jaroj, tiam via taksado estu pro viro kvin sikloj da arĝento kaj pro virino via taksado estu tri sikloj da arĝento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Kaj se en la aĝo de sesdek jaroj kaj pli, tiam, se tio estos viro, via taksado estu dek kvin sikloj kaj pro virino dek sikloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Kaj se li estas tro malriĉa por tia taksado, tiam oni starigu lin antaŭ la pastro kaj la pastro taksu lin: konforme al la bonhaveco de la promesinto la pastro lin taksu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Se tio estas bruto el tiaj, kiajn oni ofere alportas al la Eternulo, tiam ĉio, kio estas donita al la Eternulo, estu sankta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Oni ne devas ĝin ŝanĝi nek anstataŭigi ĝin, bonan per malbona aŭ malbonan per bona; se tamen iu anstataŭigos bruton per bruto, tiam ĝi kaj ankaŭ ĝia anstataŭigito fariĝu konsekrita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Se tio estas ia bruto malpura, el tiaj, kiajn oni ne alportas ofere al la Eternulo, tiam oni starigu la bruton antaŭ la pastro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'kaj la pastro taksos ĝin, ĉu ĝi estas bona, ĉu malbona; kiel taksos la pastro, tiel ĝi estu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Se la promesinto volos ĝin elaĉeti, li aldonu kvinonon al via takso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Se iu dediĉos sian domon kiel sanktaĵon al la Eternulo, tiam la pastro ĝin taksu, ĉu ĝi estas bona, ĉu malbona; kiel la pastro ĝin taksos, tiel ĝi restu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Sed se la dediĉinto volos elaĉeti sian domon, tiam li aldonu kvinonon de la mono de via takso, kaj ĝi restos lia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Se el sia posedata kampo iu dediĉos ion al la Eternulo, tiam via taksado devas esti proporcia al ĝia semitaĵo: pro semitaĵo en la kvanto de ĥomero da hordeo estu la takso kvindek sikloj da arĝento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Se de jubilea jaro li dediĉas sian kampon, tiam la afero restu laŭ via taksado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Sed se post la jubilea jaro li dediĉos sian kampon, tiam la pastro kalkulu al li la monon laŭ la jaroj, kiuj restas ĝis la jubilea jaro, kaj tion oni deprenu de via takso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Se la dediĉinto volos elaĉeti la kampon, tiam li aldonu kvinonon de la mono laŭ via taksado, kaj ĝi restos lia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Sed se li ne elaĉetos la kampon kaj la kampo estos vendita al alia homo, tiam ĝi ne estos plu elaĉetebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Kaj tiu kampo, kiam ĝi foriros en la jubilea jaro, estos konsekrita al la Eternulo, kiel kampo priĵurita: ĝi fariĝos posedaĵo de la pastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Kaj se iu dediĉos al la Eternulo kampon, kiun li aĉetis kaj kiu ne estas el la kampoj de lia hereda posedaĵo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'tiam la pastro kalkulu al li la takson ĝis la jubilea jaro, kaj li donu la takson en tiu tago, kiel konsekritaĵon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'En la jubilea jaro la kampo revenos al tiu, de kiu oni ĝin aĉetis, al kiu apartenas hereda posedado de tiu tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Ĉiu via taksado estu laŭ la sankta siklo: el dudek geroj konsistu la siklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Nur unuenaskiton, kiu el la brutoj apartenas al la Eternulo pro sia unuenaskiteco, neniu dediĉu: ĉu ĝi estas bovo, ĉu ĝi estas ŝafo, ĝi apartenas al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Se ĝi estas bruto malpura, tiam oni devas elaĉeti ĝin laŭ via taksado kaj aldoni al la valoro kvinonon; se ĝi ne estos elaĉetita, oni vendu ĝin laŭ via taksado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Nur ĉio konsekrita, kion iu konsekris al la Eternulo, el ĉio, kio apartenas al li, ĉu ĝi estas homo, ĉu bruto, ĉu posedata kampo, ne estu vendata nek elaĉetata. Ĉio konsekrita estas plejsanktaĵo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Ĉiu konsekrita, kiu estos konsekrita el la homoj, ne estu elaĉetita; li devas morti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Ĉiu dekonaĵo el la tero, el la semitaĵo de la tero, el la fruktoj de la arboj apartenas al la Eternulo; ĝi estas sanktaĵo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Se iu volos elaĉeti ion el sia dekonaĵo, li aldonu al la valoro kvinonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Kaj ĉiu dekono el la bovoj kaj ŝafoj, el ĉio, kio pasas sub la bastono de paŝtanto, la deka estu konsekrita al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Oni ne devas esplori, ĉu ĝi estas bona aŭ malbona, kaj oni ĝin devas ne anstataŭigi; se iu ĝin anstataŭigos, tiam ĝi kaj ĝia anstataŭaĵo estu sanktaĵoj kaj ne estu elaĉetataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Tio estas la ordonoj, kiujn la Eternulo ordonis al Moseo por la Izraelidoj sur la monto Sinaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Kaj la Eternulo ekparolis al Moseo en la dezerto Sinaj en la tabernaklo de kunveno en la unua tago de la dua monato de la dua jaro post ilia eliro el la lando Egipta, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Prikalkulu la tutan komunumon de la Izraelidoj laŭ iliaj familioj, laŭ iliaj patrodomoj, laŭ la nombro de la nomoj de ĉiuj virseksuloj laŭkape.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'De la aĝuloj de dudek jaroj kaj pli, ĉiujn, kiuj taŭgas por milito en Izrael, prikalkulu ilin laŭ iliaj taĉmentoj, vi kaj Aaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Kaj kun vi estu po unu homo el ĉiu tribo, homo, kiu estas ĉefo en sia patrodomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Kaj jen estas la nomoj de la viroj, kiuj staros kun vi: de Ruben staru Elicur, filo de Ŝedeur;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'de Simeon, Ŝelumiel, filo de Curiŝadaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'de Jehuda, Naĥŝon, filo de Aminadab;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'de Isaĥar, Netanel, filo de Cuar;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'de Zebulun, Eliab, filo de Ĥelon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'de la filoj de Jozef: de Efraim, Eliŝama, filo de Amihud; de Manase, Gamliel, filo de Pedacur;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'de Benjamen, Abidan, filo de Gideoni;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'de Dan, Aĥiezer, filo de Amiŝadaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'de Aŝer, Pagiel, filo de Oĥran;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'de Gad, Eljasaf, filo de Deuel;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'de Naftali, Aĥira, filo de Enan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Tio estas la distingitoj el la komunumo, la estroj de la triboj de siaj patroj, la ĉefoj de la miloj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Kaj Moseo kaj Aaron prenis tiujn virojn, cititajn laŭ iliaj nomoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'Kaj la tutan komunumon ili kunvenigis en la unua tago de la dua monato; kaj la kunvenintoj legitimis sin laŭ siaj familioj, laŭ siaj patrodomoj, laŭ la nombroj de la nomoj, de la aĝuloj de dudek jaroj kaj pli, laŭkape,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'kiel la Eternulo ordonis al Moseo. Kaj li prikalkulis ilin en la dezerto Sinaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Kaj montriĝis, ke la filoj de Ruben, la unuenaskito de Izrael, laŭ sia deveno, laŭ siaj familioj, laŭ siaj patrodomoj, laŭ la nombro da nomoj laŭkape, ĉiuj virseksuloj en la aĝo de dudek jaroj kaj pli, ĉiuj militkapablaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'prezentis en la tribo de Ruben la nombron de kvardek ses mil kvincent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'La filoj de Simeon laŭ sia deveno, laŭ siaj familioj, laŭ siaj patrodomoj, kalkulitaj laŭ la nombro da nomoj laŭkape, ĉiuj virseksuloj en la aĝo de dudek jaroj kaj pli, ĉiuj militkapablaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'prezentis en la tribo de Simeon la nombron de kvindek naŭ mil tricent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'La filoj de Gad laŭ sia deveno, laŭ siaj familioj, laŭ siaj patrodomoj, laŭ la nombro da nomoj, en la aĝo de dudek jaroj kaj pli, ĉiuj militkapablaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'prezentis en la tribo de Gad la nombron de kvardek kvin mil sescent kvindek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'La filoj de Jehuda laŭ sia deveno, laŭ siaj familioj, laŭ siaj patrodomoj, laŭ la nombro da nomoj, en la aĝo de dudek jaroj kaj pli, ĉiuj militkapablaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'prezentis en la tribo de Jehuda la nombron de sepdek kvar mil sescent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'La filoj de Isaĥar laŭ sia deveno, laŭ siaj familioj, laŭ siaj patrodomoj, laŭ la nombro da nomoj, en la aĝo de dudek jaroj kaj pli, ĉiuj militkapablaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'prezentis en la tribo de Isaĥar la nombron de kvindek kvar mil kvarcent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'La filoj de Zebulun laŭ sia deveno, laŭ siaj familioj, laŭ siaj patrodomoj, laŭ la nombro da nomoj, en la aĝo de dudek jaroj kaj pli, ĉiuj militkapablaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'prezentis en la tribo de Zebulun la nombron de kvindek sep mil kvarcent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'La filoj de Jozef, la filoj de Efraim laŭ sia deveno, laŭ siaj familioj, laŭ siaj patrodomoj, laŭ la nombro da nomoj, en la aĝo de dudek jaroj kaj pli, ĉiuj militkapablaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'prezentis en la tribo de Efraim la nombron de kvardek mil kvincent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'La filoj de Manase laŭ sia deveno, laŭ siaj familioj, laŭ siaj patrodomoj, laŭ la nombro da nomoj, en la aĝo de dudek jaroj kaj pli, ĉiuj militkapablaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'prezentis en la tribo de Manase la nombron de tridek du mil ducent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'La filoj de Benjamen laŭ sia deveno, laŭ siaj familioj, laŭ siaj patrodomoj, laŭ la nombro da nomoj, en la aĝo de dudek jaroj kaj pli, ĉiuj militkapablaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'prezentis en la tribo de Benjamen la nombron de tridek kvin mil kvarcent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'La filoj de Dan laŭ sia deveno, laŭ siaj familioj, laŭ siaj patrodomoj, laŭ la nombro da nomoj, en la aĝo de dudek jaroj kaj pli, ĉiuj militkapablaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'prezentis en la tribo de Dan la nombron de sesdek du mil sepcent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'La filoj de Aŝer laŭ sia deveno, laŭ siaj familioj, laŭ siaj patrodomoj, laŭ la nombro da nomoj, en la aĝo de dudek jaroj kaj pli, ĉiuj militkapablaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'prezentis en la tribo de Aŝer la nombron de kvardek unu mil kvincent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'La filoj de Naftali laŭ sia deveno, laŭ siaj familioj, laŭ siaj patrodomoj, laŭ la nombro da nomoj, en la aĝo de dudek jaroj kaj pli, ĉiuj militkapablaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'prezentis en la tribo de Naftali la nombron de kvindek tri mil kvarcent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Tio estas la kalkulitoj, kiujn kalkulis Moseo kaj Aaron kaj la princoj de Izrael, dek du homoj, po unu el ĉiu patrodomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Kaj la nombro de ĉiuj kalkulitoj el la Izraelidoj laŭ iliaj patrodomoj, en la aĝo de dudek jaroj kaj pli, ĉiuj militkapablaj en Izrael,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'la nombro de ĉiuj kalkulitoj estis sescent tri mil kvincent kvindek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Sed la Levidoj laŭ sia patrodomo ne estis kalkulitaj inter ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Ĉar la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Nur la tribon de Levi ne prikalkulu, kaj ne metu ilian nombron mezen de la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Sed vi komisiu al la Levidoj la tabernaklon de atesto kaj ĉiujn ĝiajn objektojn, kaj ĉion, kio apartenas al ĝi; ili portadu la tabernaklon kaj ĉiujn ĝiajn objektojn, kaj ili priservu ĝin, kaj ĉirkaŭ la tabernaklo ili starigu siajn tendojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Kaj kiam la tabernaklo devos forlasi sian lokon, tiam la Levidoj ĝin levu; kaj kiam la tabernaklo devos resti sur loko, tiam la Levidoj ĝin starigu; sed se laiko alproksimiĝos, li estu mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Kaj la Izraelidoj aranĝos sin ĉiu en sia tendaro kaj ĉiu apud sia standardo, laŭ siaj taĉmentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Sed la Levidoj starigu siajn tendojn ĉirkaŭ la tabernaklo de atesto, por ke ne trafu kolero la komunumon de la Izraelidoj; kaj la Levidoj plenumos la gardadon de la tabernaklo de atesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Kaj tiel faris la Izraelidoj; konforme al ĉio, kion la Eternulo ordonis al Moseo, tiel ili faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Kaj la Eternulo ekparolis al Moseo kaj al Aaron, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'La Izraelidoj starigu siajn tendojn ĉiu apud sia standardo, apud la signoj de sia patrodomo; iom malproksime ĉirkaŭ la tabernaklo de kunveno ili starigu siajn tendojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'En la antaŭa parto, oriente, staros tendare la standardo de la tendaro de Jehuda, laŭ iliaj taĉmentoj; kaj la princo de la Jehudaidoj estas Naĥŝon, filo de Aminadab;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'kaj lia taĉmento kaj ĝiaj kalkulitoj estas sepdek kvar mil sescent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Apude staru la tribo de Isaĥar; kaj la princo de la Isaĥaridoj estas Netanel, filo de Cuar;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'kaj lia taĉmento kaj ĝiaj kalkulitoj estas kvindek kvar mil kvarcent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Poste la tribo de Zebulun; kaj la princo de la Zebulunidoj estas Eliab, filo de Ĥelon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'kaj lia taĉmento kaj ĝiaj kalkulitoj estas kvindek sep mil kvarcent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Ĉiuj kalkulitoj de la tendaro de Jehuda estas cent okdek ses mil kvarcent laŭ iliaj taĉmentoj; ili elmoviĝu la unuaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'La standardo de la tendaro de Ruben estu sude, laŭ iliaj taĉmentoj; kaj la princo de la Rubenidoj estas Elicur, filo de Ŝedeur;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'kaj lia taĉmento kaj ĝiaj kalkulitoj estas kvardek ses mil kvincent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Apude staru la tribo de Simeon; kaj la princo de la Simeonidoj estas Ŝelumiel, filo de Curiŝadaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'kaj lia taĉmento kaj ĝiaj kalkulitoj estas kvindek naŭ mil tricent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Poste la tribo de Gad; kaj la princo de la Gadidoj estas Eljasaf, filo de Deuel;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'kaj lia taĉmento kaj ĝiaj kalkulitoj estas kvardek kvin mil sescent kvindek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Ĉiuj kalkulitoj de la tendaro de Ruben estas cent kvindek unu mil kvarcent kvindek laŭ iliaj taĉmentoj; ili elmoviĝu la duaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Poste elmoviĝu kun la tabernaklo de kunveno la tendaro de la Levidoj inter la tendaroj; kiel ili staros tendare, tiel ili elmoviĝu, ĉiu laŭ sia loko kun siaj standardoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'La standardo de la tendaro de Efraim, laŭ iliaj taĉmentoj, estu okcidente; kaj la princo de la Efraimidoj estas Eliŝama, filo de Amihud;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'kaj lia taĉmento kaj ĝiaj kalkulitoj estas kvardek mil kvincent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Apude estu la tribo de Manase; kaj la princo de la Manaseidoj estas Gamliel, filo de Pedacur;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'kaj lia taĉmento kaj ĝiaj kalkulitoj estas tridek du mil ducent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Poste la tribo de Benjamen; kaj la princo de la Benjamenidoj estas Abidan, filo de Gideoni;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'kaj lia taĉmento kaj ĝiaj kalkulitoj estas tridek kvin mil kvarcent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Ĉiuj kalkulitoj de la tendaro de Efraim estas cent ok mil cent laŭ iliaj taĉmentoj; ili elmoviĝu la triaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'La standardo de la tendaro de Dan estu norde, laŭ iliaj taĉmentoj; kaj la princo de la Danidoj estas Aĥiezer, filo de Amiŝadaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'kaj lia taĉmento kaj ĝiaj kalkulitoj estas sesdek du mil sepcent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Apude staru tendare la tribo de Aŝer; kaj la princo de la Aŝeridoj estas Pagiel, filo de Oĥran;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'kaj lia taĉmento kaj ĝiaj kalkulitoj estas kvardek unu mil kvincent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Poste la tribo de Naftali; kaj la princo de la Naftaliidoj estas Aĥira, filo de Enan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'kaj lia taĉmento kaj ĝiaj kalkulitoj estas kvindek tri mil kvarcent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Ĉiuj kalkulitoj de la tendaro de Dan estas cent kvindek sep mil sescent; ili elmoviĝu la lastaj kun siaj standardoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Tio estas la kalkulitoj de la Izraelidoj laŭ iliaj patrodomoj. Ĉiuj kalkulitoj de la tendaroj, laŭ iliaj taĉmentoj, estis sescent tri mil kvincent kvindek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Sed la Levidoj ne estis kalkulitaj inter la Izraelidoj; kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Kaj la Izraelidoj faris konforme al ĉio, kion la Eternulo ordonis al Moseo: tiel ili stariĝis tendare kun siaj standardoj, kaj tiel ili elmoviĝadis, ĉiu laŭ sia familio, laŭ sia patrodomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Kaj jen estas la genealogio de Aaron kaj Moseo en tiu tempo, kiam la Eternulo parolis al Moseo sur la monto Sinaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Jen estas la nomoj de la filoj de Aaron: la unuenaskito Nadab, kaj Abihu, Eleazar, kaj Itamar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Tio estas la nomoj de la filoj de Aaron, la pastroj sanktoleitaj, kiujn li konsekris por pastri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Sed Nadab kaj Abihu mortis antaŭ la Eternulo, kiam ili oferalportis fremdan fajron antaŭ la Eternulon en la dezerto Sinaj; kaj filojn ili ne havis. Kaj pastris Eleazar kaj Itamar apud Aaron ilia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Alvenigu la tribon de Levi, kaj starigu ĝin antaŭ la pastro Aaron, ke ili servu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Kaj ili plenumu gardon koncerne lin kaj koncerne la tutan komunumon antaŭ la tabernaklo de kunveno, por servi la servojn de la tabernaklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Kaj ili gardu ĉiujn objektojn de la tabernaklo de kunveno kaj la gardotaĵon de la Izraelidoj, por servi la servojn de la tabernaklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Kaj donu la Levidojn al Aaron kaj al liaj filoj; ili estu fordonitaj al li el la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Kaj Aaronon kaj liajn filojn oficialigu, ke ili plenumadu sian pastradon; se laiko en tion enmiksiĝos, li estu mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Jen Mi prenis la Levidojn el inter la Izraelidoj anstataŭ ĉiuj unuenaskitoj utermalfermintoj el la Izraelidoj; la Levidoj estu do Miaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'ĉar al Mi apartenas ĉiuj unuenaskitoj; en la tago, en kiu Mi batis ĉiujn unuenaskitojn en la lando Egipta, Mi dediĉis al Mi ĉiujn unuenaskitojn en Izrael, de homo ĝis bruto; Miaj ili estu: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Kaj la Eternulo ekparolis al Moseo en la dezerto Sinaj, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Prikalkulu la Levidojn laŭ iliaj patrodomoj, laŭ iliaj familioj; ĉiun virseksulon en la aĝo de unu monato kaj pli prikalkulu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Kaj Moseo prikalkulis ilin laŭ la diro de la Eternulo, kiel estis ordonite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Kaj jenaj estis la filoj de Levi laŭ iliaj nomoj: Gerŝon kaj Kehat kaj Merari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Kaj jen estas la nomoj de la filoj de Gerŝon laŭ iliaj familioj: Libni kaj Ŝimei.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Kaj la filoj de Kehat laŭ iliaj familioj: Amram kaj Jichar, Ĥebron kaj Uziel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Kaj la filoj de Merari laŭ iliaj familioj: Maĥli kaj Muŝi. Tio estas la familioj de Levi laŭ iliaj patrodomoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'De Gerŝon la familio de la Libniidoj kaj la familio de la Ŝimeiidoj; tio estas la familioj de la Gerŝonidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Iliaj kalkulitoj laŭ la nombro de ĉiuj virseksuloj en la aĝo de unu monato kaj pli prezentas la nombron de sep mil kvincent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'La familioj de la Gerŝonidoj devas havi siajn tendojn malantaŭ la tabernaklo, okcidente.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Kaj la estro de la patrodomo de la Gerŝonidoj estas Eljasaf, filo de Lael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Kaj sub la gardado de la Gerŝonidoj en la tabernaklo de kunveno estas la tabernaklo, kaj la tendo, ĝiaj kovriloj, kaj la kovrotuko de la pordo de la tabernaklo de kunveno,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'kaj la kurtenoj de la korto, kaj la kovrotuko de la pordo de la korto, kiu estas ĉirkaŭ la tabernaklo kaj ĉirkaŭ la altaro, kaj la ŝnuroj kun ĉiuj aranĝaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Kaj de Kehat estas la familio de la Amramidoj kaj la familio de la Jicharidoj kaj la familio de la Ĥebronidoj kaj la familio de la Uzielidoj; tio estas la familioj de la Kehatidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Laŭ la nombro de ĉiuj virseksuloj en la aĝo de unu monato kaj pli ili estas ok mil sescent, plenumantaj gardadon de la sanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'La familioj de la Kehatidoj devas havi siajn tendojn flanke de la tabernaklo, sude.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Kaj la estro de la patrodomo de la familioj de la Kehatidoj estas Elcafan, filo de Uziel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Kaj sub ilia gardado estu la kesto kaj la tablo kaj la kandelabro kaj la altaroj, kaj la sanktaj vazoj, per kiuj oni faras la servadon, kaj la kurteno kaj ĉiuj ĝiaj apartenaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Kaj la estro de la estroj de la Levidoj estas Eleazar, filo de la pastro Aaron; li kontrolas la plenumantojn de la gardado de la sanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'De Merari estas la familio de la Maĥliidoj kaj la familio de la Muŝiidoj; tio estas la familioj de Merari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Kaj iliaj kalkulitoj laŭ la nombro de ĉiuj virseksuloj en la aĝo de unu monato kaj pli estas ses mil ducent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Kaj la estro de la patrodomo de la familioj de Merari estas Curiel, filo de Abiĥail; ili devas havi siajn tendojn flanke de la tabernaklo, norde.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Kaj sub la kontrolo kaj gardado de la filoj de Merari estas la tabuloj de la tabernaklo kaj ĝiaj stangoj kaj ĝiaj kolonoj kaj ĝiaj bazoj kaj ĉiuj ĝiaj vazoj kaj ĝia tuta aranĝaĵo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'kaj la kolonoj de la korto ĉirkaŭe kaj iliaj bazoj kaj iliaj najloj kaj iliaj ŝnuroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Kaj antaŭ la tabernaklo, en la antaŭa parto de la tabernaklo de kunveno, oriente, havos siajn tendojn Moseo kaj Aaron kaj liaj filoj, plenumante la gardadon de la sanktejo, por gardi la Izraelidojn; sed se laiko alproksimiĝos, li estu mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Ĉiuj kalkulitaj Levidoj, kiujn prikalkulis Moseo kaj Aaron laŭ la ordono de la Eternulo, laŭ iliaj familioj, ĉiuj virseksuloj en la aĝo de unu monato kaj pli, estis dudek du mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Kaj la Eternulo diris al Moseo: Prikalkulu ĉiujn unuenaskitajn virseksulojn inter la Izraelidoj en la aĝo de unu monato kaj pli, kaj faru registron de iliaj nomoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Kaj prenu la Levidojn por Mi, kiu estas la Eternulo, anstataŭ ĉiuj unuenaskitoj el la Izraelidoj, kaj la brutojn de la Levidoj anstataŭ ĉiuj unuenaskitoj el la brutoj de la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Kaj Moseo prikalkulis, kiel ordonis al li la Eternulo, ĉiujn unuenaskitojn el la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Kaj estis ĉiuj unuenaskitaj virseksuloj laŭ la nombro de la nomoj en la aĝo de unu monato kaj pli laŭ la kalkulo dudek du mil ducent sepdek tri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Prenu la Levidojn anstataŭ ĉiuj unuenaskitoj el la Izraelidoj, kaj la brutojn de la Levidoj anstataŭ iliaj brutoj, kaj la Levidoj apartenu al Mi: Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Kaj elaĉete pro la ducent sepdek tri, kiuj estas superfluaj kompare kun la nombro de la Levidoj el la unuenaskitoj el la Izraelidoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'prenu po kvin sikloj pro ĉiu kapo, laŭ la sankta siklo prenu, po dudek geroj en siklo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'kaj donu la monon al Aaron kaj al liaj filoj, elaĉete pro la superfluaj inter ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Kaj Moseo prenis la monon de la elaĉeto de la superfluaj kompare kun tiuj, kiuj estis elaĉetitaj per la Levidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'De la unuenaskitoj de la Izraelidoj li prenis la monon, mil tricent sesdek kvin siklojn laŭ la sankta siklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Kaj Moseo donis la monon de la elaĉetitoj al Aaron kaj al liaj filoj, laŭ la diro de la Eternulo, kiel ordonis la Eternulo al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Kaj la Eternulo ekparolis al Moseo kaj al Aaron, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Prikalkulu la filojn de Kehat el inter la Levidoj laŭ iliaj familioj, laŭ iliaj patrodomoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'en la aĝo de tridek jaroj kaj pli, ĝis la aĝo de kvindek jaroj, ĉiujn kapablajn por servi, por fari laboron en la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Tio estas la servado de la Kehatidoj en la tabernaklo de kunveno, en la plejsanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Aaron kaj liaj filoj eniru, kiam la tendaro devos elmoviĝi, kaj ili deprenu la kovrantan kurtenon kaj kovru per ĝi la keston de atesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Kaj ili metu sur ĝin tegon el antilopaj feloj, kaj ili sternu supre bluan tukon, kaj ili enmetu ĝiajn stangojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Kaj sur la tablo de la panoj de propono ili sternu bluan tukon, kaj ili metu sur ĝin la pladojn kaj la kulerojn kaj la tasojn kaj la pokalojn de la verŝoferoj; kaj ĝia konstanta pano estu sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Kaj ili sternu sur tio ruĝan tukon kaj kovru ĝin per tego el antilopaj feloj, kaj ili enmetu ĝiajn stangojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Kaj ili prenu bluan tukon kaj kovru la kandelabron de lumigado kaj ĝiajn lucernojn kaj ĝiajn prenilojn kaj ĝiajn cindrujojn, kaj ĉiujn ĝiajn oleujojn, kiuj estas uzataj ĉe ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Kaj ili metu ĝin kaj ĉiujn ĝiajn apartenaĵojn en tegon el antilopaj feloj, kaj ili metu tion sur portilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Kaj sur la ora altaro ili sternu bluan tukon kaj tegu ĝin per tego el antilopaj feloj, kaj ili enmetu ĝiajn stangojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Kaj ili prenu ĉiujn objektojn de servado, per kiuj oni servas en la sanktejo, kaj ili metu tion en bluan tukon kaj tegu tion per tego el antilopaj feloj kaj metu sur portilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Kaj ili purigu la altaron de la cindro kaj sternu sur ĝi purpuran tukon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'Kaj ili metu sur ĝin ĉiujn ĝiajn objektojn, per kiuj oni servas sur ĝi, la karbujojn, la forkojn kaj la ŝovelilojn kaj la kalikojn, ĉiujn objektojn de la altaro, kaj ili sternu sur ĝi tegon el antilopaj feloj, kaj ili enmetu ĝiajn stangojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Kiam Aaron kaj liaj filoj finos la kovradon de la sanktejo kaj de ĉiuj objektoj de la sanktejo ĉe la elmoviĝo de la tendaro, tiam venos la filoj de Kehat, por porti; sed ili ne ektuŝu la sanktaĵon, por ke ili ne mortu. Tio estas la portaĵo de la filoj de Kehat ĉe la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Sub la gardado de Eleazar, filo de la pastro Aaron, estas la oleo por la lumigado kaj la bonodoraj incensoj kaj la konstanta farunofero kaj la oleo de sanktigado, la gardado de la tuta tabernaklo, kaj de ĉio, kio estas en ĝi, de la sanktejo kaj de ĝiaj objektoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Kaj la Eternulo ekparolis al Moseo kaj al Aaron, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Ne pereigu la tribon de la familioj Kehatidaj inter la Levidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'sed tion faru al ili, por ke ili vivu kaj ne mortu, kiam ili alproksimiĝos al la plejsanktejo: Aaron kaj liaj filoj eniru kaj starigu ilin ĉiun ĉe lia servo kaj ĉe lia portotaĵo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'sed ili ne aliru, por rigardi, kiel oni dismetas la sanktaĵojn, por ke ili ne mortu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Prikalkulu ankaŭ la filojn de Gerŝon laŭ iliaj patrodomoj, laŭ iliaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'De la havantaj la aĝon de tridek jaroj kaj pli ĝis la havantaj la aĝon de kvindek jaroj kalkulu ilin, ĉiujn, kiuj estas kapablaj por la servado, por plenumi laboron en la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Tio estas la laboro de la familioj Gerŝonidaj, por servi kaj por porti:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'ili portu la tapiŝojn de la tabernaklo, kaj la tabernaklon de kunveno, ĝian kovrilon, kaj la tegon el la antilopaj feloj, kiu estas super ĝi supre, kaj la kovrotukon de la pordo de la tabernaklo de kunveno,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'kaj la kurtenojn de la korto, kaj la kovrotukon de la pordego de la korto, kiu estas ĉirkaŭ la tabernaklo kaj ĉirkaŭ la altaro, kaj iliajn ŝnurojn kaj ĉiujn iliajn servajn objektojn; kaj ĉion, kion oni devas fari ĉe ili, ili faru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Laŭ la ordono de Aaron kaj de liaj filoj estu la tuta laborado de la Gerŝonidoj, koncerne ĉian ilian portadon kaj ĉian ilian laboradon; kaj metu sub ilian gardadon ĉion, kion ili portas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Tio estas la laboro de la familioj de la Gerŝonidoj en la tabernaklo de kunveno; kaj la kontrolon super ili havas Itamar, filo de la pastro Aaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'La filojn de Merari prikalkulu laŭ iliaj familioj, laŭ ilia patrodomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'De la havantaj la aĝon de tridek jaroj kaj pli ĝis la havantaj la aĝon de kvindek jaroj prikalkulu ilin, ĉiujn servokapablajn, por plenumi la laborojn de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Kaj jen estas la ofico de ilia portado ĉe ilia tuta laborado en la tabernaklo de kunveno: ili portu la tabulojn de la tabernaklo kaj ĝiajn riglilojn kaj ĝiajn kolonojn kaj ĝiajn bazojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'kaj la kolonojn de la korto ĉirkaŭe kaj iliajn bazojn kaj la najlojn kaj la ŝnurojn kun ĉiuj iliaj apartenaĵoj kaj kun ĉiuj iliaj servobjektoj; kaj laŭnome prikalkulu ĉiujn objektojn, kiujn ili ofice devas porti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Tio estas la laboro de la familioj de la Merariidoj ĉe ilia tuta laborado en la tabernaklo de kunveno, sub la kontrolo de Itamar, filo de la pastro Aaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Kaj Moseo kaj Aaron kaj la estroj de la komunumo prikalkulis la Kehatidojn laŭ iliaj familioj kaj laŭ ilia patrodomo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'de la havantaj la aĝon de tridek jaroj kaj pli ĝis la havantaj la aĝon de kvindek jaroj, ĉiujn servokapablajn por la laborado en la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Kaj ilia kalkulita nombro laŭ iliaj familioj estis du mil sepcent kvindek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Tio estas la kalkulitoj de la familioj Kehatidaj, de ĉiuj laborantoj en la tabernaklo de kunveno, kiujn prikalkulis Moseo kaj Aaron laŭ la diro de la Eternulo per Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Kaj la kalkulitoj de la filoj de Gerŝon laŭ iliaj familioj kaj laŭ ilia patrodomo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'de la havantaj la aĝon de tridek jaroj kaj pli ĝis la havantaj la aĝon de kvindek jaroj, ĉiuj servokapablaj por la laborado en la tabernaklo de kunveno,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'ilia nombro laŭ iliaj familioj, laŭ ilia patrodomo, estis du mil sescent tridek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Tio estas la kalkulitoj de la familioj de la filoj de Gerŝon, de ĉiuj laborantoj en la tabernaklo de kunveno, kiujn prikalkulis Moseo kaj Aaron laŭ la ordono de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Kaj la kalkulitoj de la familioj de la filoj de Merari laŭ iliaj familioj, laŭ ilia patrodomo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'de la havantaj la aĝon de tridek jaroj kaj pli ĝis la havantaj la aĝon de kvindek jaroj, ĉiuj servokapablaj por la laborado en la tabernaklo de kunveno,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'ilia nombro laŭ iliaj familioj estis tri mil ducent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Tio estas la kalkulitoj de la familioj de la filoj de Merari, kiujn prikalkulis Moseo kaj Aaron laŭ la diro de la Eternulo per Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Ĉiuj kalkulitoj, kiujn prikalkulis Moseo kaj Aaron kaj la estroj de Izrael, la Levidoj laŭ iliaj familioj kaj laŭ ilia patrodomo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'de la havantaj la aĝon de tridek jaroj kaj pli ĝis la havantaj la aĝon de kvindek jaroj, ĉiuj servokapablaj por plenumi laboron kaj plenumi porton en la tabernaklo de kunveno,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'ilia nombro estis ok mil kvincent okdek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Laŭ la diro de la Eternulo per Moseo ili estis kalkulitaj, ĉiu laŭ sia laboro kaj portado, kalkulitaj, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Ordonu al la Izraelidoj, ke ili elsendu el la tendaro ĉiujn leprulojn, kaj ĉiujn, kiuj havas elfluon, kaj ĉiujn, kiuj malpuriĝis de mortinto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Kiel virojn, tiel ankaŭ virinojn elsendu, ekster la tendaron elsendu ilin, por ke ili ne malpurigu siajn tendarojn, inter kiuj Mi loĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Kaj la Izraelidoj faris tiel, kaj ili elsendis ilin ekster la tendaron; kiel diris la Eternulo al Moseo, tiel faris la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Diru al la Izraelidoj: Se viro aŭ virino faros ian pekon kontraŭ homo, farante per tio krimon kontraŭ la Eternulo, kaj tiu animo kulpiĝos,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'tiam ili konfesu sian pekon, kiun ili faris, kaj ili kompensu sian kulpon plene kaj aldonu ĝian kvinonon, kaj donu al tiu, kontraŭ kiu ili kulpiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Sed se tiu homo ne havas parencon, al kiu oni povus kompensi la kulpon, tiam la kompenso de la kulpo apartenas al la Eternulo, por la pastro, krom la virŝafo de pekliberigo, per kiu li estos pekliberigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Kaj ĉiu oferdono el ĉiuj sanktaĵoj de la Izraelidoj, kiujn ili alportas al la pastro, apartenas al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Kaj ĉies sanktigitaĵo al li apartenas. Se iu ion donas al la pastro, ĝi apartenu al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Parolu al la Izraelidoj, kaj diru al ili: Se ies edzino forflankiĝos kaj pekos kontraŭ li,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'kaj iu viro kuŝos kun ŝi sekskuniĝe, kaj tio estos kaŝita antaŭ ŝia edzo, ĉar ŝi malpuriĝis kaŝe, kaj ne estos atestanto pri ŝi kaj ŝi ne estos kaptita;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'sed atakos lin spirito de ĵaluzo kaj li ĵaluzos sian edzinon, kiam ŝi estos malpuriĝinta, aŭ atakos lin spirito de ĵaluzo kaj li ĵaluzos sian edzinon, kiam ŝi ne estos malpuriĝinta:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'tiam la edzo alkonduku sian edzinon al la pastro, kaj alportu pro ŝi kiel oferon dekonon de efo da hordea faruno; li ne verŝu sur ĝin oleon kaj ne metu sur ĝin olibanon, ĉar tio estas farunofero de ĵaluzo, farunofero de memorigo, memorigante pri malbonago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Kaj la pastro alproksimigos ŝin kaj starigos ŝin antaŭ la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'kaj la pastro prenos sanktan akvon en argila vazo, kaj iom da tero, kiu estos sur la planko de la tabernaklo, la pastro prenos kaj ĵetos en la akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Kaj la pastro starigos la virinon antaŭ la Eternulo kaj disliberigos la harojn sur la kapo de la virino kaj donos en ŝiajn manojn la farunoferon de la memorigo, tiun farunoferon de ĵaluzo, kaj en la mano de la pastro estos akvo maldolĉa, malbeniga.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Kaj la pastro ŝin ĵurligos, kaj diros al la virino: Se neniu viro kuŝis kun vi kaj se vi ne forflankiĝis per malpuriĝo kun alia viro anstataŭ via edzo, tiam restu sendifekta de ĉi tiu maldolĉa malbeniga akvo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'sed se vi forflankiĝis kun alia viro anstataŭ via edzo kaj se vi malpuriĝis kaj iu viro kuŝis kun vi krom via edzo-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'la pastro ĵurligos la virinon per ĵuro de malbeno, kaj la pastro diros al la virino: Tiam la Eternulo fordonu vin al malbeno kaj al ĵuro inter via popolo, farante vian femuron maldikiĝinta kaj vian ventron ŝvelinta;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'kaj ĉi tiu malbeniga akvo eniru en viajn internaĵojn, por ke ŝvelu via ventro kaj maldikiĝu via femuro. Kaj la virino diros: Amen, amen!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Kaj la pastro enskribos tiun ĵurligon en libro kaj lavos ĝin per la maldolĉa akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Kaj li trinkigos al la virino la maldolĉan malbenigan akvon, kaj eniros en ŝin la malbeniga akvo por maldolĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Kaj la pastro prenos el la mano de la virino la farunoferon de ĵaluzo, kaj li skuos la farunoferon antaŭ la Eternulo kaj portos ĝin al la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Kaj la pastro prenos plenmanon el la farunofero, ĝian parton de memorigo, kaj bruligos sur la altaro, kaj poste li trinkigos al la virino la akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Kaj kiam li estos trinkiginta al ŝi la akvon, tiam, se ŝi malpuriĝis kaj pekis kontraŭ sia edzo, eniros en ŝin la malbeniga akvo por maldolĉo, kaj ŝvelos ŝia ventro kaj maldikiĝos ŝia femuro; kaj la virino fariĝos malbeno inter sia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Sed se la virino ne malpuriĝis kaj ŝi estas pura, tiam ŝi restos sendifekta kaj povos naski infanojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Tio estas la leĝo pri la ĵaluzo, kiam virino forflankiĝos kun alia viro anstataŭ sia edzo kaj malpuriĝos,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'aŭ kiam viron atakos spirito de ĵaluzo kaj li ĵaluzos sian edzinon; tiam li starigu la edzinon antaŭ la Eternulo, kaj la pastro agu kun ŝi laŭ la tuta tiu leĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Kaj la edzo estos pura de kulpo, kaj la edzino portos sian pekon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Parolu al la Izraelidoj, kaj diru al ili: Se viro aŭ virino decidos fari sanktan promeson de konsekriĝo, por konsekri sin al la Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'tiam li devas deteni sin de vino kaj de ebriigaĵo, vinagron vinan kaj vinagron de ebriigaĵoj li ne devas trinki, kaj nenian trinkaĵon el vinberoj li devas trinki, kaj vinberojn freŝajn aŭ sekigitajn li ne devas manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Dum la tuta tempo de sia konsekriteco li devas manĝi nenion, kio estas farita el vinberoj, de la kernoj ĝis la ŝelo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Dum la tuta tempo de la promesita konsekriteco razilo ne devas ektuŝi lian kapon; ĝis la finiĝo de la tempo, por kiu li konsekris sin al la Eternulo, li estas sankta; li lasu libere kreski la harojn de sia kapo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Dum la tuta tempo, por kiu li konsekris sin al la Eternulo, li ne aliru al mortinta korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Ne ĉe sia patro, nek ĉe sia patrino, nek ĉe sia frato, nek ĉe sia fratino li malpuriĝu, se ili mortis; ĉar konsekro al lia Dio estas sur lia kapo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Dum la tuta tempo de sia konsekriteco li estas sankta al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Kaj se iu mortos apud li subite, neatendite, kaj li malpurigos sian konsekritan kapon, li pritondu sian kapon en la tago de sia puriĝo, en la sepa tago li ĝin pritondu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'kaj en la oka tago li alportu du turtojn aŭ du kolombidojn al la pastro, al la pordo de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Kaj la pastro faros el unu pekoferon kaj el la dua bruloferon, kaj li pekliberigos lin de tio, kion li pekis per la mortinta korpo, kaj li sanktigos lian kapon en tiu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Kaj li konsekros sin al la Eternulo por la tempo de sia konsekriteco, kaj li alportos jaraĝan ŝafidon kiel kulpoferon; kaj la tempo antaŭa perdos sian valoron, ĉar lia konsekriteco malpuriĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Kaj jen estas la leĝo pri la konsekrito: kiam finiĝos la tempo de lia konsekriteco, oni venigu lin al la pordo de la tabernaklo de kunveno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'kaj li alportu kiel oferon al la Eternulo unu jaraĝan ŝafidon sendifektan kiel bruloferon, kaj unu jaraĝan ŝafidinon sendifektan kiel pekoferon, kaj unu virŝafon sendifektan kiel pacoferon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'kaj korbon da macoj el delikata faruno, kukojn miksitajn kun oleo, kaj flanojn nefermentintajn, ŝmiritajn per oleo, kaj ilian farunoferon kaj verŝoferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Kaj la pastro prezentos tion antaŭ la Eternulon kaj faros lian pekoferon kaj lian bruloferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Kaj el la virŝafo li faros pacoferon al la Eternulo kune kun la korbo da macoj, kaj la pastro faros lian farunoferon kaj lian verŝoferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Kaj la konsekrito pritondos ĉe la pordo de la tabernaklo de kunveno sian konsekritan kapon, kaj li prenos la harojn de sia konsekrita kapo, kaj metos sur la fajron, kiu estas sub la pacofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Kaj la pastro prenos la kuiritan ŝultron de la virŝafo kaj unu nefermentintan kukon el la korbo kaj unu nefermentintan flanon, kaj li metos tion sur la manon de la konsekrito, kiam tiu estos pritondinta sian konsekritan kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Kaj la pastro skuos tion kiel skuoferon antaŭ la Eternulo; sanktigita ĝi estu por la pastro, krom la brustaĵo de skuado kaj la femuro de levado. Poste la konsekrito povas trinki vinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Tio estas la leĝo pri konsekrito, kiu donis sanktan promeson; lia ofero apartenas al la Eternulo pro lia konsekriteco, krom tio, kion permesos al li lia bonhavo; konforme al sia promeso, kiun li promesis, li faru, laŭ la leĝo pri lia konsekriteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Diru al Aaron kaj al liaj filoj jene: Tiamaniere benu la Izraelidojn; diru al ili:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'La Eternulo vin benu kaj vin gardu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'La Eternulo lumu al vi per Sia vizaĝo kaj favorkoru vin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'La Eternulo turnu Sian vizaĝon al vi kaj donu al vi pacon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Tiel ili metu Mian nomon sur la Izraelidojn, kaj Mi ilin benos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'En la tago, kiam Moseo finis la starigadon de la tabernaklo, kiam li sanktoleis ĝin kaj sanktigis ĝin kaj ĉiujn ĝiajn apartenaĵojn kaj la altaron kaj ĉiujn ĝiajn apartenaĵojn kaj sanktoleis ilin kaj sanktigis ilin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'tiam alportis la estroj de Izrael, la ĉefoj de siaj patrodomoj, tiuj estroj de la triboj, tiuj, kiuj administris la kalkuladon-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'ili alportis siajn oferojn antaŭ la Eternulon, ses kovritajn veturilojn kaj dek du bovojn, po unu veturilo de du estroj kaj po unu bovo de ĉiu, kaj ili venigis tion antaŭ la tabernaklon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Prenu de ili, kaj tio estu por la plenumado de la laboroj ĉe la tabernaklo de kunveno; kaj donu tion al la Levidoj, al ĉiu laŭ la speco de lia laborado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Kaj Moseo prenis la veturilojn kaj la bovojn kaj donis ilin al la Levidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Du veturilojn kaj kvar bovojn li donis al la filoj de Gerŝon laŭ la speco de ilia laborado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'kaj kvar veturilojn kaj ok bovojn li donis al la filoj de Merari laŭ la speco de ilia laborado, sub la kontrolo de Itamar, filo de la pastro Aaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Sed al la filoj de Kehat li ne donis, ĉar ili havis laboradon sanktan; sur la ŝultroj ili devis porti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Kaj la estroj alportis oferojn por inaŭgura dono de la altaro, en la tago, en kiu ĝi estis sanktoleita; kaj la estroj alportis sian oferon antaŭ la altaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Kaj la Eternulo diris al Moseo: Po unu estro en tago ili alportu sian oferon por la inaŭguro de la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'En la unua tago la alportanto de sia ofero estis Naĥŝon, filo de Aminadab, de la tribo de Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Kaj lia ofero estis: unu arĝenta plado, havanta la pezon de cent tridek sikloj, unu arĝenta kaliko de sepdek sikloj, laŭ la sankta siklo, ambaŭ plenaj de delikata faruno, miksita kun oleo, por farunofero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'unu ora kulero deksikla, plena de incenso;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'unu bovido, unu virŝafo, unu jaraĝa ŝafido por brulofero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'unu kapro por pekofero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'kaj por pacofero du bovoj, kvin virŝafoj, kvin virkaproj, kvin jaraĝaj ŝafidoj. Tio estis la ofero de Naĥŝon, filo de Aminadab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'En la dua tago alportis Natanel, filo de Cuar, estro de Isaĥar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Li alportis sian oferon, kiu estis: unu arĝenta plado, havanta la pezon de cent tridek sikloj, unu arĝenta kaliko de sepdek sikloj, laŭ la sankta siklo, ambaŭ plenaj de delikata faruno, miksita kun oleo, por farunofero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'unu ora kulero deksikla, plena de incenso;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'unu bovido, unu virŝafo, unu jaraĝa ŝafido por brulofero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'unu kapro por pekofero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'kaj por pacofero du bovoj, kvin virŝafoj, kvin virkaproj, kvin jaraĝaj ŝafidoj. Tio estis la ofero de Netanel, filo de Cuar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'En la tria tago-la estro de la Zebulunidoj, Eliab, filo de Ĥelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Lia ofero: unu arĝenta plado, havanta la pezon de cent tridek sikloj, unu arĝenta kaliko de sepdek sikloj, laŭ la sankta siklo, ambaŭ plenaj de delikata faruno, miksita kun oleo, por farunofero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'unu ora kulero deksikla, plena de incenso;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'unu bovido, unu virŝafo, unu jaraĝa ŝafido por brulofero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'unu kapro por pekofero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'kaj por pacofero du bovoj, kvin virŝafoj, kvin virkaproj, kvin jaraĝaj ŝafidoj. Tio estis la ofero de Eliab, filo de Ĥelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'En la kvara tago-la estro de la Rubenidoj, Elicur, filo de Ŝedeur.');
