INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Lia ofero: unu arĝenta plado, havanta la pezon de cent tridek sikloj, unu arĝenta kaliko de sepdek sikloj, laŭ la sankta siklo, ambaŭ plenaj de delikata faruno, miksita kun oleo, por farunofero;');
