INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'En la dek-dua tago-la estro de la Naftaliidoj, Aĥira, filo de Enan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Lia ofero: unu arĝenta plado, havanta la pezon de cent tridek sikloj, unu arĝenta kaliko de sepdek sikloj, laŭ la sankta siklo, ambaŭ plenaj de delikata faruno, miksita kun oleo, por farunofero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'unu ora kulero deksikla, plena de incenso;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'unu bovido, unu virŝafo, unu jaraĝa ŝafido por brulofero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'unu kapro por pekofero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'kaj por pacofero du bovoj, kvin virŝafoj, kvin virkaproj, kvin jaraĝaj ŝafidoj. Tio estis la ofero de Aĥira, filo de Enan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Tia estis la inaŭgura dono de la altaro, en la tago, en kiu ĝi estis sanktoleita, de la estroj de Izrael: dek du arĝentaj pladoj, dek du arĝentaj kalikoj, dek du oraj kuleroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'po cent tridek sikloj da arĝento havis ĉiu plado, kaj po sepdek ĉiu kaliko; la tuta arĝento de tiuj vazoj estis du mil kvarcent sikloj laŭ la sankta siklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Da oraj kuleroj plenaj de incenso estis dek du; po dek sikloj havis ĉiu kulero, laŭ la sankta siklo; la tuta oro de la kuleroj estis cent dudek sikloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Ĉiuj brutoj por brulofero estis: dek du bovidoj, dek du virŝafoj, dek du jaraĝaj ŝafidoj, kaj al ili farunoferoj; kaj dek du kaproj por pekofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Kaj ĉiuj brutoj por pacofero estis: dudek kvar bovoj, sesdek virŝafoj, sesdek virkaproj, sesdek jaraĝaj ŝafidoj. Tio estis la inaŭgura dono de la altaro, post kiam ĝi estis sanktoleita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Kaj kiam Moseo eniris en la tabernaklon de kunveno, por paroli kun Li, li aŭdis la Voĉon, parolantan al li de super la fermoplato, kiu estas sur la kesto de atesto, inter la du keruboj; kaj estis parolate al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Parolu al Aaron, kaj diru al li: Kiam vi ekbruligos la lucernojn, tiam sur la antaŭan flankon de la kandelabro lumu la sep lucernoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Kaj Aaron tiel faris; sur la antaŭan flankon de la kandelabro li lumigis la lucernojn, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Kaj jen estas la aranĝo de la kandelabro: forĝita el oro, de ĝia trunko ĝis ĝiaj floroj, forĝita ĝi estis; laŭ la modelo, kiun montris la Eternulo al Moseo, tiel li faris la kandelabron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Prenu la Levidojn el inter la Izraelidoj kaj purigu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Kaj tiel agu kun ili, por purigi ilin: aspergu ilin per akvo propeka, kaj ili prirazu sian tutan korpon kaj lavu siajn vestojn kaj purigu sin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Kaj ili prenu bovidon kaj al ĝi farunoferon, delikatan farunon, miksitan kun oleo, kaj duan bovidon prenu por pekofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Kaj venigu la Levidojn antaŭ la tabernaklon de kunveno, kaj kunvenigu la tutan komunumon de la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Kaj alvenigu la Levidojn antaŭ la Eternulon, kaj la Izraelidoj metu siajn manojn sur la Levidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Kaj Aaron faru super la Levidoj skuon antaŭ la Eternulo en la nomo de la Izraelidoj, por ke ili komencu fari la servon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Kaj la Levidoj metu siajn manojn sur la kapojn de la bovidoj, kaj faru el unu pekoferon kaj el la dua bruloferon al la Eternulo, por pekliberigi la Levidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Kaj starigu la Levidojn antaŭ Aaron kaj antaŭ liaj filoj, kaj faru super ili skuon antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Kaj tiel apartigu la Levidojn el inter la Izraelidoj, kaj la Levidoj apartenu al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Kaj post tio la Levidoj eniros, por servi en la tabernaklo de kunveno, kiam vi estos puriginta ilin kaj plenuminta super ili la skuon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Ĉar ili estas fordonitaj al Mi el inter la Izraelidoj; anstataŭ ĉiuj utermalfermintoj unuenaskitoj el ĉiuj Izraelidoj Mi prenis ilin por Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Ĉar al Mi apartenas ĉiuj unuenaskitoj de la Izraelidoj, el la homoj kaj el la brutoj; en la tago, en kiu Mi batis ĉiujn unuenaskitojn en la lando Egipta, Mi sanktigis ilin por Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Kaj Mi prenis la Levidojn anstataŭ ĉiuj unuenaskitoj inter la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'Kaj Mi fordonis la Levidojn al Aaron kaj al liaj filoj el inter la Izraelidoj, por ke ili faru servon pro la Izraelidoj en la tabernaklo de kunveno kaj por pekliberigi la Izraelidojn; por ke ne trafu la Izraelidojn frapo, se la Izraelidoj alproksimiĝus al la sanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Kaj Moseo kaj Aaron kaj la tuta komunumo de la Izraelidoj agis kun la Levidoj konforme al ĉio, kion la Eternulo ordonis al Moseo pri la Levidoj; tiel agis kun ili la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Kaj la Levidoj sin purigis kaj lavis siajn vestojn, kaj Aaron faris super ili skuon antaŭ la Eternulo, kaj Aaron pekliberigis ilin, por purigi ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Kaj post tio la Levidoj eniris, por plenumi sian servon en la tabernaklo de kunveno antaŭ Aaron kaj antaŭ liaj filoj; kiel la Eternulo ordonis al Moseo pri la Levidoj, tiel oni agis kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'Jen estas, kio koncernas la Levidojn: de la aĝo de dudek kvin jaroj kaj pli ili devas eniri en sian oficon pri la servado en la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'Kaj de la aĝo de kvindek jaroj ili retiriĝos el la ofico de la servado kaj ne servos plu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Tiam ili servos siajn fratojn en la tabernaklo de kunveno, plenumante gardadon, sed ne farante servadon. Tiel agu kun la Levidoj koncerne ilian oficon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Kaj la Eternulo ekparolis al Moseo en la dezerto Sinaj en la dua jaro post ilia eliro el la lando Egipta, en la unua monato, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'La Izraelidoj faru la Paskon en la difinita tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'En la dek-kvara tago de ĉi tiu monato, ĉirkaŭ la vespero, faru ĝin en ĝia tempo; laŭ ĉiuj ĝiaj leĝoj kaj laŭ ĉiuj ĝiaj instrukcioj faru ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Kaj Moseo diris al la Izraelidoj, ke ili faru la Paskon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'Kaj ili faris la Paskon en la unua monato, en la dek-kvara tago de la monato, ĉirkaŭ la vespero, en la dezerto Sinaj; konforme al ĉio, kion la Eternulo ordonis al Moseo, tiel faris la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Sed estis homoj, kiuj estis malpuraj pro ektuŝo de mortinta homo kaj ne povis fari la Paskon en tiu tago; ili venis antaŭ Moseon kaj Aaronon en tiu tago;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'kaj tiuj homoj diris al li: Ni estas malpuraj pro ektuŝo de mortinta homo; kial ni estu esceptataj, ke ni ne alportu la oferon al la Eternulo en ĝia tempo inter la Izraelidoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Kaj Moseo diris al ili: Staru; mi aŭskultos, kion la Eternulo ordonos koncerne vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Parolu al la Izraelidoj, dirante: Se iu el vi aŭ el viaj estontaj generacioj estos malpura pro ektuŝo de mortinta homo, aŭ se iu estos en malproksima vojiro, tamen li faru Paskon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'En la dua monato, en la dek-kvara tago, ĉirkaŭ la vespero ili faru ĝin; kun macoj kaj maldolĉaj herboj ili ĝin manĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Ili ne lasu iom el ĝi ĝis la mateno, kaj oston ili ne rompu en ĝi; laŭ ĉiuj ritoj de la Pasko ili faru ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Sed se iu estas pura kaj ne troviĝas en vojiro kaj tamen ne faras la Paskon, ties animo ekstermiĝos el inter sia popolo, ĉar oferon al la Eternulo li ne alportis en ĝia tempo; sian pekon portos tiu homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Kaj se loĝos ĉe vi fremdulo, li ankaŭ faru Paskon al la Eternulo; laŭ la rito de la Pasko kaj laŭ ĝia regularo li faru: sama regularo estu por vi, kiel por la fremdulo, tiel por la indiĝeno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'En la tago, en kiu estis starigita la tabernaklo, nubo kovris la tabernaklon super la tendo de atesto, kaj vespere estis super la tabernaklo kvazaŭ aspekto de fajro ĝis la mateno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Tiel estis ĉiam: nubo ĝin kovris, kaj fajra aspekto en la nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Kaj kiam leviĝadis la nubo de super la tabernaklo, tuj poste elmoviĝadis la Izraelidoj; kaj sur la loko, kie haltadis la nubo, tie starigadis sian tendaron la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Laŭ la ordono de la Eternulo la Izraelidoj elmoviĝadis, kaj laŭ la ordono de la Eternulo ili starigadis sian tendaron; dum la tuta tempo, kiam la nubo restis super la tabernaklo, ili staradis tendare.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Kaj se la nubo restadis super la tabernaklo longan tempon, la Izraelidoj plenumadis la instrukcion de la Eternulo kaj ne elmoviĝadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Iufoje la nubo restadis kelke da tagoj super la tabernaklo, sed ili laŭ la ordono de la Eternulo restadis tendare kaj laŭ la ordono de la Eternulo elmoviĝadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Iufoje la nubo restadis de vespero ĝis mateno; tiam, kiam la nubo leviĝis matene, ili elmoviĝadis; iufoje tagon kaj nokton-kiam la nubo leviĝis, ili elmoviĝadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Iufoje du tagojn aŭ monaton aŭ pli longan tempon-kiel longe la nubo super la tabernaklo restis super ĝi, la Izraelidoj restadis tendare kaj ne elmoviĝadis; sed kiam ĝi leviĝis, ili elmoviĝadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Laŭ la ordono de la Eternulo ili restadis tendare, kaj laŭ la ordono de la Eternulo ili elmoviĝadis; ili plenumadis la instrukcion de la Eternulo, konforme al tio, kiel la Eternulo ordonis per Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Faru al vi du arĝentajn trumpetojn, forĝitaj faru ilin; kaj ili servu al vi por kunvokado de la komunumo kaj por elmoviĝado de la tendaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Kiam oni simple trumpetos per ili, tiam kolektiĝu al vi la tuta komunumo antaŭ la pordo de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Kaj se oni trumpetos per unu el ili, tiam kolektiĝu al vi la princoj, la milestroj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Kaj kiam vi trumpetos tambursone, tiam elmoviĝu la tendaroj, kiuj staras oriente.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Kaj kiam vi trumpetos tambursone duan fojon, tiam elmoviĝu la tendaroj, kiuj staras sude; oni trumpetu tambursone, kiam ili devos elmoviĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Sed kiam oni devas kunvenigi la komunumon, tiam trumpetu simple, sed ne tambursone.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Kaj la filoj de Aaron, la pastroj, trumpetu per la trumpetoj; tio estu por vi leĝo eterna en viaj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Kaj kiam vi komencos militon en via lando kontraŭ malamiko, kiu premas vin, tiam trumpetu tambursone per trumpetoj; kaj tiam vi estos rememoritaj antaŭ la Eternulo, via Dio, kaj vi estos helpitaj kontraŭ viaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Kaj en la tago de via ĝojo kaj en viaj festoj kaj en viaj novmonataj tagoj trumpetu per trumpetoj ĉe viaj bruloferoj kaj ĉe viaj pacoferoj; kaj tio estos memorigo pri vi antaŭ via Dio: Mi estas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'En la dua jaro, en la dua monato, en la dudeka tago de la monato, leviĝis la nubo de super la tabernaklo de atesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Kaj elmoviĝis la Izraelidoj en sian vojiron el la dezerto Sinaj, kaj la nubo haltis en la dezerto Paran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Kaj ili elmoviĝis la unuan fojon konforme al la ordono de la Eternulo per Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Kaj unue elmoviĝis la standardo de la tendaro de la Jehudaidoj laŭ iliaj taĉmentoj, kaj super ĝia taĉmento estis Naĥŝon, filo de Aminadab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'Kaj super la taĉmento de la tribo de la Isaĥaridoj estis Netanel, filo de Cuar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'Kaj super la taĉmento de la tribo de la Zebulunidoj estis Eliab, filo de Ĥelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Kaj oni dismetis la tabernaklon, kaj elmoviĝis la filoj de Gerŝon kaj la filoj de Merari, portantaj la tabernaklon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Kaj elmoviĝis la standardo de la tendaro de Ruben laŭ iliaj taĉmentoj, kaj super ĝia taĉmento estis Elicur, filo de Ŝedeur.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'Kaj super la taĉmento de la tribo de la Simeonidoj estis Ŝelumiel, filo de Curiŝadaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'Kaj super la taĉmento de la tribo de la Gadidoj estis Eljasaf, filo de Deuel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Kaj elmoviĝis la Kehatidoj, portantaj la sanktaĵojn; sed oni starigis la tabernaklon antaŭ ilia alveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Kaj elmoviĝis la standardo de la tendaro de la Efraimidoj laŭ iliaj taĉmentoj, kaj super ĝia taĉmento estis Eliŝama, filo de Amihud.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'Kaj super la taĉmento de la tribo de la Manaseidoj estis Gamliel, filo de Pedacur.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'Kaj super la taĉmento de la tribo de la Benjamenidoj estis Abidan, filo de Gideoni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Kaj elmoviĝis la standardo de la tendaro de la Danidoj, la finulo de ĉiuj tendaroj, laŭ iliaj taĉmentoj, kaj super ĝia taĉmento estis Aĥiezer, filo de Amiŝadaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'Kaj super la taĉmento de la tribo de la Aŝeridoj estis Pagiel, filo de Oĥran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'Kaj super la taĉmento de la tribo de la Naftaliidoj estis Aĥira, filo de Enan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Tiaj estis la marŝoj de la Izraelidoj laŭ iliaj taĉmentoj. Kaj ili elmoviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Kaj Moseo diris al Ĥobab, filo de Reuel la Midjanido, la bopatro de Moseo: Ni vojiras al tiu loko, pri kiu la Eternulo diris: Ĝin Mi donos al vi; iru kun ni, kaj ni faros al vi bonon, ĉar la Eternulo promesis bonon al Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Sed tiu diris al li: Mi ne iros, sed al mia lando kaj al mia parencaro mi iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Kaj li diris: Ho, ne forlasu nin; ĉar vi scias, kie ni povas starigi tendaron en la dezerto, kaj vi estos por ni kiel okuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'se vi iros kun ni, tiam la bonon, kiun la Eternulo faros al ni, ni faros al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Kaj ili ekvojiris for de la monto de la Eternulo vojon de tri tagoj; kaj la kesto de la interligo de la Eternulo iris antaŭ ili la tritagan vojon, por esplori por ili lokon de ripozo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Kaj la nubo de la Eternulo estis super ili dum la tago, kiam ili iris el la tendaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Kaj ĉiufoje, kiam la kesto elmoviĝis, Moseo diradis: Leviĝu, ho Eternulo, kaj disĵetiĝu Viaj malamikoj, kaj forkuru Viaj malamantoj for de Via vizaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Kaj kiam ĝi haltis, li diradis: Revenu, ho Eternulo, al la multegaj miloj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'Kaj la popolo komencis murmuri pri sia malfeliĉo al la oreloj de la Eternulo; kaj kiam la Eternulo tion aŭdis, Lia kolero ekflamis; kaj ekbrulis inter ili fajro de la Eternulo, kaj ĝi komencis ekstermadon en la rando de la tendaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Tiam la popolo ekkriis al Moseo, kaj Moseo preĝis al la Eternulo, kaj la fajro estingiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Kaj li donis al tiu loko la nomon Tabera, ĉar brulis inter ili la fajro de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Kaj la aliĝinta popolamaso inter ili komencis aperigi kapricojn; kaj ankaŭ la Izraelidoj ekploris, kaj diris: Kiu manĝigos al ni viandon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Ni memoras la fiŝojn, kiujn ni manĝis en Egiptujo senpage, la kukumojn kaj la melonojn kaj la poreojn kaj la bulbojn kaj la ajlojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'Kaj nun nia animo velkas; estas nenio krom ĉi tiu manao antaŭ niaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Kaj la manao estis kiel semo de koriandro, kaj ĝia aspekto estis kiel la aspekto de bedelio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'La popolo disiradis kaj kolektadis kaj mueladis per muelŝtonoj aŭ pistadis en pistujo, kaj kuiradis en kaldrono kaj faradis el ĝi kukojn; kaj ĝia gusto estis kiel la gusto de oleaj kukoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Kaj kiam la roso faladis sur la tendaron en la nokto, tiam faladis sur ĝin ankaŭ la manao.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Moseo aŭdis, ke la popolo ploras en siaj familioj, ĉiu ĉe la pordo de sia tendo; kaj forte ekflamis la kolero de la Eternulo, kaj Moseon tio afliktis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'Kaj Moseo diris al la Eternulo: Kial Vi faris malbonon al Via sklavo? kaj kial mi ne plaĉis al Vi, ke Vi metis la ŝarĝon de tiu tuta popolo sur min?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Ĉu mi embriigis tiun tutan popolon? aŭ ĉu mi ĝin naskis, ke Vi diris al mi: Portu ĝin sur via brusto, kiel portas nutristino suĉinfanon, en la landon, pri kiu Vi ĵuris al ĝiaj patroj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Kie mi prenos viandon, por doni al tiu tuta popolo? ĉar ili ploras antaŭ mi, dirante: Donu al ni viandon por manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Ne povas mi sola porti tiun tutan popolon, ĉar ĝi estas tro peza por mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Kaj se Vi tiel agas kun mi, tiam mortigu min, se mi plaĉas al Vi, por ke mi ne vidu mian malfeliĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Tiam la Eternulo diris al Moseo: Kolektu al Mi sepdek virojn el la plejaĝuloj de Izrael, pri kiuj vi scias, ke ili estas la plejaĝuloj de la popolo kaj ĝiaj gvidantoj, kaj prenu ilin al la tabernaklo de kunveno, ke ili stariĝu tie kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Kaj Mi malleviĝos kaj parolos tie kun vi, kaj Mi deprenos iom de la spirito, kiu estas sur vi, kaj Mi metos sur ilin, por ke ili portu kun vi la ŝarĝon de la popolo kaj por ke vi ne portu sola.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Kaj al la popolo diru: Prepariĝu por morgaŭ, kaj vi manĝos viandon; ĉar vi ploris al la oreloj de la Eternulo, dirante: Kiu manĝigos al ni viandon? bone estis al ni en Egiptujo-tial la Eternulo donos al vi viandon, kaj vi manĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Ne dum unu tago vi manĝos, kaj ne dum du tagoj kaj ne dum kvin tagoj kaj ne dum dek tagoj kaj ne dum dudek tagoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'sed dum tuta monato, ĝis ĝi eliros tra viaj nazotruoj kaj fariĝos al vi abomenaĵo, pro tio, ke vi malŝatis la Eternulon, kiu estas inter vi, kaj vi ploris antaŭ Li, dirante: Por kio ni eliris el Egiptujo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Kaj Moseo diris: El sescent mil piedirantoj konsistas la popolo, en kies mezo mi estas; kaj Vi diras: Mi donos al ili viandon, ke ili manĝos dum tuta monato!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Ĉu oni buĉu por ili ŝafojn kaj bovojn, por ke sufiĉu por ili? aŭ ĉu ĉiujn fiŝojn de la maro oni kolektu por ili, por ke sufiĉu por ili?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Tiam la Eternulo diris al Moseo: Ĉu la brako de la Eternulo estas tro mallonga? nun vi vidos, ĉu plenumiĝos al vi Mia vorto, aŭ ne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Kaj Moseo eliris, kaj transdiris al la popolo la vortojn de la Eternulo; kaj li kolektis sepdek virojn el la plejaĝuloj de la popolo, kaj li starigis ilin ĉirkaŭ la tabernaklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Kaj la Eternulo malleviĝis en nubo kaj parolis kun li, kaj Li deprenis iom de la spirito, kiu estis sur li, kaj metis sur la sepdek virojn plejaĝulojn. Kaj kiam haltis sur ili la spirito, ili ekprofetis kaj ne ĉesis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Sed restis du viroj en la tendaro; la nomo de unu estis Eldad, kaj la nomo de la dua estis Medad; kaj suriris sur ilin la spirito-ĉar ili estis inter la enskribitaj, sed ne eliris al la tabernaklo-kaj ili ekprofetis en la tendaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Tiam kuris junulo kaj raportis al Moseo, kaj diris: Eldad kaj Medad profetas en la tendaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Kaj respondis Josuo, filo de Nun, kaj servanto de Moseo detempe de lia juneco, kaj diris: Mia sinjoro Moseo, malpermesu al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Sed Moseo diris al li: Ĉu vi ĵaluzas pri mi? estus dezirinde, ke la tuta popolo de la Eternulo fariĝu profetoj, se la Eternulo metus Sian spiriton sur ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Kaj revenis Moseo en la tendaron, li kaj la plejaĝuloj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Kaj vento elmoviĝis de la Eternulo, kaj alportis de la maro koturnojn kaj ĵetis ilin sur la tendaron, sur la spaco de unutaga irado sur unu flanko kaj sur la spaco de unutaga irado sur la dua flanko, ĉirkaŭ la tendaro kaj en denseco de du ulnoj super la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Kaj la popolo staris tiun tutan tagon kaj la tutan nokton kaj la tutan morgaŭan tagon kaj kolektis la koturnojn; kiu kolektis plej malmulte, kolektis dek ĥomerojn; kaj ili diskuŝigis ilin al si ĉirkaŭ la tendaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Kiam la viando estis ankoraŭ inter iliaj dentoj kaj ankoraŭ ne estis konsumita, ekflamis kontraŭ la popolo la kolero de la Eternulo, kaj la Eternulo frapis la popolon per tre granda frapo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Kaj oni donis al tiu loko la nomon Kibrot-Hataava, ĉar tie oni enterigis la homojn, kiuj kapricis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'De Kibrot-Hataava la popolo ekvojiris al Ĥacerot kaj restis en Ĥacerot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Kaj ekparolis Mirjam kaj Aaron kontraŭ Moseo pro la edzino Etiopino, kiun li prenis; ĉar li prenis al si edzinon Etiopinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'Kaj ili diris: Ĉu nur kun Moseo parolis la Eternulo? Li parolis ja ankaŭ kun ni. Kaj la Eternulo tion aŭdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Sed Moseo estis homo tre modesta, pli ol ĉiuj homoj sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Kaj subite diris la Eternulo al Moseo kaj al Aaron kaj al Mirjam: Eliru vi tri al la tabernaklo de kunveno. Kaj ili eliris ĉiuj tri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Kaj la Eternulo malleviĝis en nuba kolono kaj stariĝis ĉe la pordo de la tabernaklo, kaj Li vokis Aaronon kaj Mirjamon, kaj ili ambaŭ eliris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Kaj Li diris: Aŭskultu Miajn vortojn: se iu el vi estas profeto de la Eternulo, Mi aperas al li en vizio, Mi parolas kun li en sonĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'sed ne tiel estas kun Mia sklavo Moseo: en Mia tuta domo li estas konfidato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Buŝon kontraŭ buŝo Mi parolas kun li, kaj malkaŝe, ne per enigmoj; kaj la bildon de la Eternulo li vidas. Kial vi ne timis paroli kontraŭ Mia sklavo Moseo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Kaj ekflamis la kolero de la Eternulo kontraŭ ili, kaj Li foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Kaj la nubo forturniĝis de super la tabernaklo, kaj jen Mirjam kovriĝis per lepro, kiel per neĝo. Kaj Aaron turniĝis al Mirjam, kaj li ekvidis, ke ŝi estas lepra.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Kaj Aaron diris al Moseo: Mi petas, mia sinjoro, ne kalkulu al ni kiel pekon, ke ni agis malsaĝe kaj ke ni pekis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'ho, ŝi ne estu kiel malvivulo, ĉe kiu tuj post la eliro el la ventro de sia patrino forkonsumiĝis jam duono de la korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Kaj Moseo ekkriis al la Eternulo, dirante: Mi petas Vin, ho Dio, sanigu ŝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Kaj la Eternulo diris al Moseo: Se ŝia patro estus kraĉinta sur ŝian vizaĝon, ĉu ŝi tiam ne hontus sep tagojn? ŝi estu do enŝlosita dum sep tagoj ekster la tendaro, kaj poste ŝi revenu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Kaj Mirjam estis enŝlosita ekster la tendaro dum sep tagoj; kaj la popolo ne elmoviĝis, ĝis Mirjam revenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'Poste la popolo ekvojiris de Ĥacerot kaj haltis tendare en la dezerto Paran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'Sendu virojn, ke ili esplorrigardu la landon Kanaanan, kiun Mi donas al la Izraelidoj; po unu viro el ĉiu tribo de iliaj patroj sendu, ĉiu estu eminentulo inter ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Kaj Moseo sendis ilin el la dezerto Paran laŭ la ordono de la Eternulo; ĉiuj ili estis eminentuloj inter la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Kaj jen estas iliaj nomoj: el la tribo de Ruben, Ŝamua, filo de Zakur;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'el la tribo de Simeon, Ŝafat, filo de Ĥori;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'el la tribo de Jehuda, Kaleb, filo de Jefune;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'el la tribo de Isaĥar, Jigal, filo de Jozef;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'el la tribo de Efraim, Hoŝea, filo de Nun;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'el la tribo de Benjamen, Palti, filo de Rafu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'el la tribo de Zebulun, Gadiel, filo de Sodi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'el la tribo de Jozef, el la tribo de Manase, Gadi, filo de Susi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'el la tribo de Dan, Amiel, filo de Gemali;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'el la tribo de Aŝer, Setur, filo de Miĥael;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'el la tribo de Naftali, Naĥbi, filo de Vofsi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'el la tribo de Gad, Geuel, filo de Maĥi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Tio estas la nomoj de la viroj, kiujn Moseo sendis, por esplorrigardi la landon. Kaj Moseo donis al Hoŝea, filo de Nun, la nomon Josuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Kaj Moseo sendis ilin, por esplorrigardi la landon Kanaanan, kaj diris al ili: Iru tien tra la Sudo kaj suriru sur la monton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'kaj rigardu la landon, kia ĝi estas; kaj la popolon, kiu loĝas en ĝi, ĉu ĝi estas forta aŭ malforta, ĉu ĝi estas malgrandnombra aŭ grandnombra;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'kaj kia estas la tero, sur kiu ĝi sidas, ĉu ĝi estas bona aŭ malbona; kaj kiaj estas la urboj, en kiuj ĝi loĝas, ĉu en tendaroj aŭ en fortikaĵoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'kaj kia estas la tero, ĉu ĝi estas grasa aŭ malgrasa, ĉu estas sur ĝi arboj aŭ ne estas; kaj estu kuraĝaj, kaj prenu iom el la fruktoj de la lando. Kaj tiam estis la tempo de maturiĝado de vinberoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Kaj ili iris kaj esplorrigardis la landon de la dezerto Cin ĝis Reĥob antaŭ Ĥamat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Kaj ili iris tra la Sudo, kaj venis ĝis Ĥebron, kie loĝis Aĥiman, Ŝeŝaj, kaj Talmaj, idoj de Anak. (Ĥebron estis konstruita sep jarojn antaŭ ol Coan de Egiptujo.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Kaj ili venis ĝis la valo Eŝkol, kaj ili detranĉis tie branĉon kun unu peniko da vinberoj, kaj ili ekportis ĝin sur stango duope; ankaŭ iom da granatoj kaj da figoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Al tiu loko oni donis la nomon Eŝkol, pro la peniko da vinberoj, kiun detranĉis tie la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Kaj ili revenis post la esplorrigardo de la lando post kvardek tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Kaj ili iris kaj venis al Moseo kaj al Aaron kaj al la tuta komunumo de la Izraelidoj en la dezerton Paran, en la lokon Kadeŝ, kaj donis al ili raporton kaj al la tuta komunumo kaj montris al ili la fruktojn de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'Kaj ili rakontis al li, kaj diris: Ni venis en la landon, en kiun vi sendis nin, kaj efektive en ĝi fluas lakto kaj mielo, kaj jen estas ĝiaj fruktoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'sed forta estas la popolo, kiu loĝas en la lando, kaj la urboj estas fortikigitaj, tre grandaj; kaj ankaŭ la idojn de Anak ni vidis tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Amalek loĝas en la suda parto de la lando, kaj la Ĥetidoj kaj Jebusidoj kaj Amoridoj loĝas sur la monto, kaj la Kanaanidoj loĝas apud la maro kaj sur la bordo de Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Kaj Kaleb trankviligis la popolon antaŭ Moseo, kaj diris: Ni iros, kaj ni ekposedos ĝin, ĉar ni povas ĝin venki.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Sed la viroj, kiuj iris kun li, diris: Ni ne povas iri al tiu popolo, ĉar ĝi estas pli forta ol ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Kaj pri la lando, kiun ili esplorrigardis, ili disvastigis inter la Izraelidoj malbonan famon, dirante: La lando, kiun ni trapasis por esplorrigardi ĝin, estas lando, kiu formanĝas siajn loĝantojn, kaj la tuta popolo, kiun ni vidis en ĝi, estas homoj grandkreskaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'kaj tie ni vidis la gigantojn, la idojn de Anak el la gigantoj, kaj ni estis en niaj okuloj kiel lokustoj, kaj tiaj ni estis ankaŭ en iliaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Tiam tumultiĝis la tuta komunumo kaj ekkriis, kaj la popolo ploris en tiu nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Kaj ekmurmuris kontraŭ Moseo kaj kontraŭ Aaron ĉiuj Izraelidoj, kaj la tuta komunumo diris al ili: Ho, se ni estus mortintaj en la lando Egipta, aŭ se ni mortus en ĉi tiu dezerto!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Kaj por kio la Eternulo irigas nin en tiun landon, por ke ni falu de glavo? niaj edzinoj kaj infanoj fariĝos militakiro. Ĉu ne estas pli bone, ke ni revenu Egiptujon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Kaj ili diris unu al alia: Ni starigu al ni estron, kaj ni reiru Egiptujon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Tiam Moseo kaj Aaron ĵetiĝis vizaĝaltere antaŭ la tuta anaro de la komunumo de la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Kaj Josuo, filo de Nun, kaj Kaleb, filo de Jefune, el tiuj, kiuj esplorrigardis la landon, disŝiris siajn vestojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'kaj ili diris al la tuta komunumo de la Izraelidoj jene: La lando, kiun ni trapasis, por esplorrigardi ĝin, tiu lando estas tre, tre bona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Se la Eternulo estos favorkora al ni, Li venigos nin en tiun landon kaj donos ĝin al ni, tiun landon, en kiu fluas lakto kaj mielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Nur ne ribelu kontraŭ la Eternulo, kaj ne timu la popolon de la lando, ĉar nia manĝotaĵo ili estas; ilia ŝirmo foriĝis de ili, kaj la Eternulo estas kun ni; ne timu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Kaj la tuta komunumo diris, ke oni mortigu ilin per ŝtonoj. Sed la majesto de la Eternulo aperis en la tabernaklo de kunveno antaŭ ĉiuj Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Kaj la Eternulo diris al Moseo: Ĝis kiam incitados Min ĉi tiu popolo? kaj ĝis kiam ĝi ne kredos al Mi, malgraŭ ĉiuj pruvosignoj, kiujn Mi faris meze de ĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Mi frapos ĝin per pesto kaj ekstermos ĝin, kaj Mi faros el vi popolon pli grandan kaj pli fortan ol ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Sed Moseo diris al la Eternulo: Aŭdos la Egiptoj, el inter kiuj Vi elkondukis ĉi tiun popolon per Via forto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'kaj ili diros al la loĝantoj de tiu lando, kiuj aŭdis, ke Vi, la Eternulo, estas meze de ĉi tiu popolo, kaj ke Vi, la Eternulo, montris Vin al ili okulon kontraŭ okulo, kaj ke Via nubo staras super ili, kaj ke Vi iras antaŭ ili dum la tago en nuba kolono kaj dum la nokto en kolono fajra;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'se Vi ekstermos ĉi tiun popolon kiel unu homon, tiam la popoloj, kiuj aŭdis la famon pri Vi, dirus:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'Ĉar la Eternulo ne povis venigi ĉi tiun popolon en la landon, pri kiu Li ĵuris al ili, tial Li buĉis ilin en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Nun montriĝu do granda la forto de mia Sinjoro, laŭ la parolo, kiun Vi diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'La Eternulo estas longepacienca kaj multe favorkora; Li pardonas kulpon kaj krimon, sed antaŭ Li neniu estas senkulpa; Li punas la kulpon de patroj sur filoj kaj nepoj, en la tria kaj kvara generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Ho, pardonu la kulpon de ĉi tiu popolo laŭ Via granda favorkoreco kaj kiel Vi pardonadis al ĉi tiu popolo de Egiptujo ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Kaj la Eternulo diris: Mi pardonis konforme al via diro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'sed kiel Mi vivas kaj kiel de la gloro de la Eternulo estas plena la tuta tero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'ĉiuj homoj, kiuj vidis Mian gloron kaj Miajn pruvosignojn, kiujn Mi faris en Egiptujo kaj en la dezerto, kaj provis Min jam dek fojojn kaj ne aŭskultis Mian voĉon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'ne vidos la landon, pri kiu Mi ĵuris al iliaj patroj, kaj ĉiuj, kiuj incitis Min, ne vidos ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Sed Mian sklavon Kaleb, ĉar estis en li spirito alia kaj li estis obeema al Mi, lin Mi venigos en la landon, en kiun li iris, kaj lia idaro heredos ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Sed la Amalekidoj kaj Kanaanidoj loĝas en la valo; morgaŭ turnu vin kaj ekiru en la dezerton sur la vojo al la Ruĝa Maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Kaj la Eternulo ekparolis al Moseo kaj al Aaron, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Ĝis kiam ĉi tiu malbona komunumo murmuros kontraŭ Mi? la murmuradon de la Izraelidoj, kiun ili murmuras kontraŭ Mi, Mi aŭdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Diru al ili: Kiel Mi vivas, diras la Eternulo, kiel vi parolis al Miaj oreloj, tiel Mi faros al vi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'en ĉi tiu dezerto falos viaj kadavroj, kaj el ĉiuj viaj kalkulitoj, laŭ via tuta kalkulo, en la aĝo de dudek jaroj kaj pli, kiuj murmuris kontraŭ Mi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'neniu venos en la landon, pri kiu Mi levis Mian manon, ke Mi loĝigos vin en ĝi, neniu krom Kaleb, filo de Jefune, kaj Josuo, filo de Nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Viajn infanojn, pri kiuj vi diris, ke ili fariĝos militakiro, Mi venigos tien, kaj ili ekkonos la landon, kiun vi malŝatis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Sed vi-viaj kadavroj falos en ĉi tiu dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'Kaj viaj filoj estos paŝtistoj en la dezerto dum kvardek jaroj, kaj portos vian malĉastecon, ĝis kiam viaj kadavroj konsumiĝos en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Laŭ la nombro de la tagoj, dum kiuj vi esplorrigardis la landon, kvardek tagoj, po jaro pro ĉiu tago, vi portos la punon pro via malbonago dum kvardek jaroj, por ke vi ekkonu Mian malfavoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Mi, la Eternulo, tion diris: tion Mi faros al tiu tuta malbona komunumo, kiu ribelis kontraŭ Mi; en ĉi tiu dezerto ili pereos kaj ĉi tie ili mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Kaj la viroj, kiujn Moseo sendis, por esplorrigardi la landon, kaj kiuj revenis kaj murmurigis kontraŭ li la tutan komunumon, disvastigante malbonan famon pri la lando-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'tiuj viroj, kiuj disvastigis malbonan famon pri la lando, mortis de pesto antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Sed Josuo, filo de Nun, kaj Kaleb, filo de Jefune, restis vivaj el tiuj viroj, kiuj iris, por esplorrigardi la landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Kaj Moseo diris tiujn vortojn al ĉiuj Izraelidoj, kaj la popolo tre malĝojis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Kaj ili leviĝis frumatene, kaj iris sur la supron de la monto, dirante: Jen ni estas, kaj ni iru sur la lokon, pri kiu parolis la Eternulo; ĉar ni pekis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Sed Moseo diris: Por kio vi kontraŭagas al la vortoj de la Eternulo? tio ja ne sukcesos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Ne iru, ĉar la Eternulo ne estas inter vi; kaj ne estu frapataj antaŭ viaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Ĉar la Amalekidoj kaj la Kanaanidoj estas tie antaŭ vi, kaj vi falos de glavo; ĉar pro tio, ke vi deturniĝis de la Eternulo, la Eternulo ne estos kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Sed ili obstinis, kaj iris sur la supron de la monto; tamen la kesto de la interligo de la Eternulo kaj Moseo ne eliris el la tendaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Kaj malsupreniris la Amalekidoj kaj la Kanaanidoj, kiuj loĝis sur la monto, kaj batis ilin kaj persekutis ilin ĝis Ĥorma.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Parolu al la Izraelidoj, kaj diru al ili: Kiam vi venos en la landon de via loĝado, kiun Mi donas al vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'kaj vi faros fajroferon al la Eternulo, bruloferon aŭ buĉoferon, plenumante sanktan promeson aŭ farante memvolan oferon, aŭ en viaj festoj, por fari agrablan odoraĵon al la Eternulo el grandaj brutoj aŭ el malgrandaj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'tiam la oferdonanto devas alporti al la Eternulo farunoferon el dekono de efo da delikata faruno, miksita kun kvarono de hino da oleo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'kaj da vino por verŝofero kvaronon de hino aldonu al la brulofero aŭ al la buĉofero al ĉiu ŝafido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Kaj ĉe ŝafo alportu farunoferon el du dekonoj de efo da delikata faruno, miksita kun triono de hino da oleo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'Kaj da vino por verŝofero trionon de hino; alportu tion kiel agrablan odoraĵon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Kaj se bovidon vi alportos kiel bruloferon aŭ buĉoferon, por plenumi sanktan promeson, aŭ kiel pacoferon al la Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'tiam kun la bovido oni devas alporti farunoferon el tri dekonoj de efo da delikata faruno, miksita kun duono de hino da oleo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'kaj da vino por verŝofero alportu duonon de hino kiel fajroferon, agrablan odoraĵon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Tiel oni devas fari ĉe ĉiu bovo aŭ ĉe ĉiu ŝafo aŭ ĉe brutido el ŝafoj aŭ kaproj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Laŭ la nombro de la oferoj, kiujn vi faros, agu tiel ĉe ĉiu, laŭ ilia nombro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Ĉiu indiĝeno faru tion tiamaniere, alportante fajroferon, agrablan odoraĵon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Kaj se loĝas inter vi fremdulo aŭ kiu ajn estas inter vi en viaj generacioj, kaj li alportos fajroferon, agrablan odoraĵon al la Eternulo, tiam li faru tiel, kiel vi faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Por la tuta komunumo devas esti unu leĝo, por vi kaj por la fremdulo inter vi; leĝo eterna en viaj generacioj, kiel por vi, tiel ankaŭ por la fremdulo, estu antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Unu leĝo kaj unu rajto estu por vi, kaj por la fremdulo, kiu loĝas kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Parolu al la Izraelidoj, kaj diru al ili: Kiam vi venos en la landon, en kiun Mi vin kondukas,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'kaj vi manĝos la panon de tiu lando, tiam donu oferdonon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Kiel unuaaĵon el via pasto alportu oferdone kukon; kiel oferdonon el la grenejo, tiel oferdonu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'El la unuaaĵoj de via pasto donu al la Eternulo oferdonon en viaj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Kaj se vi eraros, kaj ne plenumos ĉiujn tiujn ordonojn, kiujn la Eternulo diris al Moseo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'ĉion, kion la Eternulo ordonis al vi per Moseo, de la tago, en kiu la Eternulo ordonis, kaj plue, en viaj generacioj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'tiam se pro neatento de la komunumo estis farita la eraro, la tuta komunumo alportu unu bovidon kiel bruloferon, kiel agrablan odoraĵon al la Eternulo, kun ĝia farunofero kaj ĝia verŝofero laŭ la regularo, kaj unu kapron kiel pekoferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Kaj la pastro pekliberigos la tutan komunumon de la Izraelidoj, kaj estos pardonite al ili; ĉar tio estis eraro, kaj ili alportis sian oferon, fajroferon al la Eternulo, kaj sian pekoferon antaŭ la Eternulo pro sia peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'Kaj estos pardonite al la tuta komunumo de la Izraelidoj, kaj al la fremdulo, kiu loĝas inter ili; ĉar la tuta popolo eraris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Kaj se unu homo pekos per eraro, tiam li alportu kaprinon jaraĝan kiel pekoferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Kaj la pastro pekliberigos la homon, kiu eraris, pekante per eraro antaŭ la Eternulo; li pekliberigos lin, kaj estos pardonite al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Kiel por la indiĝeno el la Izraelidoj, tiel ankaŭ por la fremdulo, kiu loĝas inter ili, unu leĝo estu por vi por tiu, kiu eraris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Sed se iu faris ion per mano malhumila, ĉu li estas indiĝeno, ĉu fremdulo, li blasfemis kontraŭ la Eternulo; kaj ekstermiĝos tiu homo el inter sia popolo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'ĉar la vorton de la Eternulo li malestimis kaj Lian ordonon li malobeis; ekstermiĝu tiu homo, lia peko estas sur li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Kiam la Izraelidoj estis en la dezerto, ili trovis homon, kiu kolektis lignon en tago sabata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Kaj tiuj, kiuj trovis lin, kiam li kolektis lignon, alkondukis lin al Moseo kaj al Aaron kaj al la tuta komunumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Kaj oni metis lin en gardejon, ĉar ne estis ankoraŭ klarigite, kion oni devas fari al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Kaj la Eternulo diris al Moseo: Tiu homo mortu; per ŝtonoj mortigu lin la tuta komunumo ekster la tendaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Kaj la tuta komunumo elkondukis lin ekster la tendaron kaj mortigis lin per ŝtonoj, kaj li mortis; kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Kaj la Eternulo diris al Moseo jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Parolu al la Izraelidoj, kaj diru al ili, ke ili faru al si kvastojn sur la randoj de siaj vestoj en siaj generacioj, kaj ili enmetu en la kvaston de la rando fadenon bluan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Kaj ĝi estu por vi kvasto, kiun rigardante, vi rememoros ĉiujn ordonojn de la Eternulo kaj plenumos ilin kaj ne iros laŭ viaj koroj kaj viaj okuloj, kiujn vi malĉaste sekvadas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'por ke vi memoru kaj plenumu ĉiujn Miajn ordonojn kaj estu sanktaj antaŭ via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Mi estas la Eternulo, via Dio, kiu elkondukis vin el la lando Egipta, por ke Mi estu via Dio. Mi estas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Kaj entreprenis Koraĥ, filo de Jichar, filo de Kehat, ido de Levi, kaj Datan kaj Abiram, filoj de Eliab, kaj On, filo de Pelet, idoj de Ruben,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'kaj stariĝis antaŭ Moseo, kaj kun ili el la Izraelidoj ducent kvindek viroj, estroj de la komunumo, vokataj al la kunvenoj; homoj eminentaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'kaj ili kolektiĝis kontraŭ Moseo kaj kontraŭ Aaron, kaj diris al ili: Sufiĉe por vi! la tuta komunumo, ĉiuj estas ja sanktaj, kaj inter ili estas la Eternulo; kial do vi estrigas vin super la komunumo de la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Kaj Moseo tion aŭdis, kaj ĵetis sin vizaĝaltere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'Kaj li ekparolis al Koraĥ kaj al lia tuta anaro, dirante: Morgaŭ la Eternulo montros, kiu estas Lia kaj kiu estas sankta, por ke Li alproksimigu lin al Si; kaj kiun Li elektos, tiun Li alproksimigos al Si.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Faru jenon: prenu al vi incensujojn, Koraĥ kaj lia tuta anaro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'kaj metu sur ilin fajron kaj metu sur ilin incenson antaŭ la Eternulo morgaŭ; kaj kiun la Eternulo elektos, tiu estos la sanktulo. Estas troe, ho Levidoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Kaj Moseo diris al Koraĥ: Aŭskultu do, idoj de Levi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'ĉu ne sufiĉas al vi, ke la Dio de la Izraelidoj distingis vin inter la komunumo de Izrael, por alproksimigi vin al Si, por ke vi plenumu la servojn en la tabernaklo de la Eternulo kaj por ke vi staru antaŭ la komunumo, por servi al ĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'Kaj Li alproksimigos vin kaj ĉiujn viajn fratojn, la idojn de Levi, kun vi; kaj nun vi postulas eĉ pastrecon!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Tiamaniere vi kaj via tuta anaro ekribelis kontraŭ la Eternulo; sed kio estas Aaron, ke vi murmuras kontraŭ li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Kaj Moseo sendis voki Datanon kaj Abiramon, filojn de Eliab; sed ili diris: Ni ne iros!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Ĉu ne sufiĉas, ke el lando, en kiu fluas lakto kaj mielo, vi elirigis nin, por pereigi nin en la dezerto? kaj vi volas ankoraŭ regi super ni?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Ja ne en landon, en kiu fluas lakto kaj mielo, vi venigis nin, kaj vi ne donis al ni posedaĵon el kampoj kaj vinberĝardenoj! ĉu vi volas blindigi la okulojn de ĉi tiuj homoj? ni ne iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Kaj tio tre kolerigis Moseon, kaj li diris al la Eternulo: Ne turnu Vin al ilia ofero; eĉ unu azenon mi ne prenis de ili, kaj al neniu el ili mi faris ian malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Kaj Moseo diris al Koraĥ: Vi kaj via tuta anaro estu antaŭ la Eternulo morgaŭ, vi kaj ili kaj Aaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Kaj prenu ĉiu sian incensujon kaj metu sur ĝin incenson, kaj alportu antaŭ la Eternulon ĉiu sian incensujon, ducent kvindek incensujojn; ankaŭ vi kaj Aaron, ĉiu sian incensujon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Kaj ili prenis ĉiu sian incensujon kaj metis sur ĝin fajron kaj ŝutis sur ĝin incenson, kaj ili stariĝis ĉe la pordo de la tabernaklo de kunveno, ankaŭ Moseo kaj Aaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Kaj kunvenigis kontraŭ ili Koraĥ la tutan anaron ĉe la pordo de la tabernaklo de kunveno; kaj montriĝis la majesto de la Eternulo al la tuta komunumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Kaj la Eternulo ekparolis al Moseo kaj al Aaron, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Apartiĝu de ĉi tiu anaro, kaj Mi ekstermos ilin en momento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Kaj ili ĵetis sin vizaĝaltere, kaj diris: Ho Dio, Dio de la spiritoj de ĉia karno! unu pekis, kaj Vi volas koleri la tutan komunumon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Diru al la komunumo jene: Foriru de ĉirkaŭ la loĝejo de Koraĥ, Datan, kaj Abiram.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Kaj Moseo leviĝis kaj iris al Datan kaj Abiram, kaj post li iris la plejaĝuloj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Kaj li diris al la komunumo: Foriru do de la tendoj de tiuj malbonaj homoj, kaj tuŝu nenion, kio apartenas al ili, por ke vi ne pereu pro ĉiuj iliaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Kaj ili foriris de ĉirkaŭ la loĝejo de Koraĥ, Datan, kaj Abiram; sed Datan kaj Abiram eliris, kaj staris ĉe la pordo de siaj tendoj kune kun siaj edzinoj, filoj, kaj malgrandaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Kaj Moseo diris: Per tio vi ekscios, ke la Eternulo sendis min, por fari ĉiujn tiujn aferojn, kaj ke mi ne faris laŭ mia koro:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'se per la ordinara morto de ĉiuj homoj mortos ĉi tiuj, aŭ ilin trafos la sorto, kiu povas trafi ĉiun homon, tiam ne la Eternulo sendis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Sed se novan aperon kreos la Eternulo, kaj la tero malfermos sian buŝon, kaj englutos ilin, kaj ĉion, kio apartenas al ili, kaj ili vivaj malsupreniros en Ŝeolon, tiam sciu, ke ĉi tiuj homoj blasfemis kontraŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Apenaŭ li finis paroli ĉion tion, disfendiĝis la tero, kiu estis sub ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'kaj la tero malfermis sian buŝon kaj englutis ilin kaj iliajn domojn kaj ĉiujn homojn de Koraĥ kaj la tutan havon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'Kaj ili, kaj ĉio, kio apartenis al ili, malsupreniris vivaj en Ŝeolon, kaj fermiĝis super ili la tero, kaj ili forpereis el inter la komunumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Kaj ĉiuj Izraelidoj, kiuj estis ĉirkaŭ ili, forkuris ĉe ilia krio; ĉar ili diris: Ke nin ankaŭ la tero ne englutu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Kaj fajro eliris de la Eternulo, kaj ĝi forbruligis tiujn ducent kvindek homojn, kiuj alportis la incenson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, 'Diru al Eleazar, filo de la pastro Aaron, ke li levu la incensujojn el la brulintaĵo, sed la fajron disĵetu malproksimen; ĉar sanktiĝis');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'la incensujoj de tiuj, kiuj per sia vivo pagis pro la peko; kaj oni faru el ili tavoletojn, por tegi la altaron; ĉar oni alportis ilin antaŭ la Eternulon, kaj ili sanktiĝis; kaj ili estu memoriga signo por la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'Kaj Eleazar, la pastro, prenis la kuprajn incensujojn, kiujn alportis la bruligitaj, kaj tavoligis ilin, por tegi la altaron');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'memorige por la Izraelidoj, ke laiko, kiu ne estas el la idoj de Aaron, ne alproksimiĝu, por incensi antaŭ la Eternulo, por ke li ne fariĝu kiel Koraĥ kaj lia anaro, kiel diris la Eternulo al li per Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'Kaj en la sekvanta tago la tuta komunumo de la Izraelidoj ekmurmuris kontraŭ Moseo kaj kontraŭ Aaron, dirante: Vi mortigis la popolon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'Kaj kiam kolektiĝis la komunumo kontraŭ Moseo kaj kontraŭ Aaron, ili turniĝis al la tabernaklo de kunveno; kaj jen kovris ĝin la nubo kaj aperis la majesto de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'Kaj eniris Moseo kaj Aaron en la antaŭan parton de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, 'Foriĝu el inter ĉi tiu komunumo, kaj Mi pereigos ilin en momento. Sed ili ĵetiĝis vizaĝaltere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'Kaj Moseo diris al Aaron: Prenu vian incensujon kaj metu sur ĝin fajron de la altaro kaj ŝutu sur ĝin incenson kaj iru rapide al la komunumo kaj pekliberigu ĝin; ĉar eliris kolero de antaŭ la Eternulo, komenciĝis la frapado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'Tiam Aaron prenis, kiel diris Moseo, kaj kuris en la mezon de la komunumo; kaj jen komenciĝis jam la frapado en la popolo. Kaj li metis la incenson kaj pekliberigis la popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'Li stariĝis inter la mortintoj kaj la vivantoj, kaj la frapado ĉesiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'Kaj la nombro de la mortintoj de la frapado estis dek kvar mil sepcent, krom tiuj, kiuj mortis pro Koraĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'Kaj Aaron revenis al Moseo al la pordo de la tabernaklo de kunveno; kaj la frapado ĉesiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Parolu al la Izraelidoj, kaj prenu de ili po unu bastono de ĉiu tribo, de ĉiuj iliaj triboj dek du bastonojn, kaj ĉies nomon skribu sur lia bastono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Sed la nomon de Aaron skribu sur la bastono de Levi; ĉar unu bastono devas esti de la estro de ilia tribo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'Kaj kuŝigu ilin en la tabernaklo de kunveno antaŭ la kesto de atesto, kie Mi aperas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'Kaj kiun viron Mi elektos, ties bastono ekfloros; kaj tiel Mi silentigos antaŭ Mi la murmuradon de la Izraelidoj, kiun ili murmuras kontraŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Kaj Moseo parolis al la Izraelidoj, kaj ĉiuj iliaj estroj donis al li po unu bastono de ĉiu tribo, laŭ iliaj triboj dek du bastonojn; kaj la bastono de Aaron estis inter iliaj bastonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Kaj Moseo kuŝigis la bastonojn antaŭ la Eternulo en la tabernaklo de atesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Kaj en la sekvanta tago Moseo venis en la tabernaklon de atesto; kaj jen ekfloris la bastono de Aaron de la domo de Levi, kaj ĝi elirigis burĝonojn kaj donis florojn kaj maturigis migdalojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Kaj Moseo elportis ĉiujn bastonojn de antaŭ la Eternulo al ĉiuj Izraelidoj; kaj ili vidis, kaj ĉiu prenis sian bastonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Kaj la Eternulo diris al Moseo: Remetu la bastonon de Aaron antaŭ la keston de atesto, por ke ĝi estu gardata kiel memorsigno por la ribelemuloj, por ke ĉesiĝu ilia murmurado kontraŭ Mi, kaj por ke ili ne mortu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Kaj Moseo faris tion; kiel la Eternulo ordonis al li, tiel li faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Kaj la Izraelidoj diris al Moseo: Jen ni mortas, ni pereas, ni ĉiuj pereas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'ĉiu, kiu alproksimiĝas al la tabernaklo de la Eternulo, mortas; ĉu ni ĉiuj mortos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Kaj la Eternulo diris al Aaron: Vi kaj viaj filoj kaj la domo de via patro kune kun vi portos sur vi la kulpon pri la tabernaklo, kaj vi kaj viaj filoj kune kun vi portos la kulpon pri via pastrado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Ankaŭ viajn fratojn, la tribon de Levi, la genton de via patro, alproksimigu al vi; ili aliĝu al vi kaj servu vin; kaj vi kune kun viaj filoj estos ĉe la tabernaklo de atesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Kaj ili prizorgu la gardadon de vi kaj la gardadon de la tuta tabernaklo; nur al la objektoj de la sanktejo kaj al la altaro ili ne alproksimiĝu, por ke ili ne mortu, kiel ili, tiel ankaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Ili aliĝu al vi kaj plenumu la zorgadon pri la tabernaklo de kunveno, koncerne ĉiujn servojn en la tabernaklo; sed laiko ne alproksimiĝu al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Kaj plenumu la zorgadon pri la sanktejo kaj la zorgadon pri la altaro, por ke ne estu plu kolero kontraŭ la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Kaj Mi prenis viajn fratojn, la Levidojn, el inter la Izraelidoj; donace al vi ili estas donitaj por la Eternulo, por plenumi la servojn en la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Kaj vi kune kun viaj filoj plenumu vian pastradon en ĉio, kio koncernas la altaron, kaj tion, kio estas malantaŭ la kurteno, kaj servu; kiel donacon Mi donas al vi la servadon de via pastrado; sed laiko, kiu alproksimiĝos, estu mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Kaj la Eternulo diris al Aaron: Mi donis al vi la zorgadon pri Miaj oferdonoj: ĉion, kion konsekras la Izraelidoj, Mi donis al vi kaj al viaj filoj, kiel sanktan apartenaĵon per leĝo eterna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Jen kio apartenas al vi el la plejsanktaĵoj, el la bruligataĵo: ĉiu ilia ofero, kiel ĉiu ilia farunofero, tiel ankaŭ ĉiu ilia pekofero kaj ĉiu ilia kulpofero, kiun ili donos al Mi, estas plejsanktaĵo por vi kaj por viaj filoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'Sur la plej sankta loko manĝu tion; ĉiu virseksulo povas tion manĝi. Sankta ĝi estu por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Kaj jen kio apartenas al vi: iliaj donacataj oferdonoj el ĉiuj skuoferoj de la Izraelidoj; al vi Mi donis ilin kaj al viaj filoj kaj al viaj filinoj kune kun vi, per leĝo eterna; ĉiu pura en via domo povas tion manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Ĉion plej bonan el oleo kaj ĉion plej bonan el mosto kaj el greno, iliajn unuaaĵojn, kiujn ili donas al la Eternulo, Mi fordonis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'La unuaj produktoj de ĉio, kio estas sur ilia tero, kiujn ili alportos al la Eternulo, apartenas al vi; ĉiu pura en via domo povas tion manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Ĉio, kio estas konsekrita en Izrael, apartenas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Ĉiu utermalferminto el ĉiuj vivaj estaĵoj, kiun ili alportas al la Eternulo, kiel el homoj, tiel ankaŭ el brutoj, apartenas al vi; tamen prenu elaĉeton pro unuenaskito el homoj, kaj ankaŭ pro unuenaskito el malpuraj brutoj prenu elaĉeton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Ilia elaĉeto estas: post la aĝo de unu monato prenu elaĉeton laŭ via takso, kvin siklojn da arĝento laŭ la sankta siklo, kiu konsistas el dudek geroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Nur pro unuenaskito el bovoj aŭ pro unuenaskito el ŝafoj aŭ pro unuenaskito el kaproj ne prenu elaĉeton: ili estas sanktaĵo; per ilia sango aspergu la altaron, kaj ilian sebon bruligu kiel fajroferon, agrablan odoraĵon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Sed ilia viando apartenas al vi; kiel la brustaĵo de skuofero kaj la dekstra femuro, ĝi apartenas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Ĉiujn sanktajn oferdonojn, kiujn alportas la Izraelidoj al la Eternulo, Mi donis al vi kaj al viaj filoj kaj al viaj filinoj kune kun vi, per leĝo eterna. Tio estas interligo de salo por eterne antaŭ la Eternulo por vi kaj por via idaro kune kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Kaj la Eternulo diris al Aaron: En ilia tero vi ne havos heredaĵon, kaj parton vi ne havos inter ili; Mi estas via parto kaj via heredaĵo meze de la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Kaj al la filoj de Levi Mi donis kiel heredaĵon dekonaĵon de ĉio en Izrael, rekompence pro ilia servado, kiun ili faras, la servado en la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'Kaj la Izraelidoj ne alproksimiĝu plu al la tabernaklo de kunveno, por ke ili ne portu pekon kaj ne mortu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Nur la Levidoj mem plenumu la servadon en la tabernaklo de kunveno kaj portu sur si ilian pekon; leĝo eterna tio estu en viaj generacioj; kaj inter la Izraelidoj ili ne havos posedaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Ĉar la dekonaĵon de la Izraelidoj, kiun ili alportos al la Eternulo oferdone, Mi donis al la Levidoj kiel posedaĵon; tial Mi diris al ili, ke inter la Izraelidoj ili ne havu posedaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Al la Levidoj parolu, kaj diru al ili: Kiam vi prenos de la Izraelidoj la dekonaĵon, kiun Mi donas al vi de ili kiel posedaĵon, tiam levu el ĝi oferdonon por la Eternulo, dekonaĵon el la dekonaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'Kaj estos kalkulata al vi via oferdono, kiel greno el la garbejo kaj kiel abundaĵo el la vinpremejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Tiamaniere vi ankaŭ alportos oferdonon al la Eternulo el ĉiuj viaj dekonaĵoj, kiujn vi prenos de la Izraelidoj; kaj vi donos el ili la oferdonon, destinitan por la Eternulo, al la pastro Aaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'El ĉiuj ricevataj donacoj alportu oferdonon al la Eternulo, el ĉio plej bona en ĝi ĝian parton konsekritan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Kaj diru al ili: Kiam vi alportos el tio la plej bonan parton, tiam ĝi estos kalkulata al la Levidoj kiel enspezo el la garbejo kaj kiel enspezo el la vinpremejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Kaj vi povas tion manĝi sur ĉiu loko, vi kaj via domo; ĉar tio estas pago al vi pro via servado en la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Kaj vi ne portos pri tio pekon, kiam vi alportos la plej bonan parton el tio; kaj vi ne malsanktigos la konsekritaĵon de la Izraelidoj, kaj vi ne mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Kaj la Eternulo ekparolis al Moseo kaj al Aaron, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'Jen estas la instrukcio de la leĝo, kiun la Eternulo starigis, dirante: Diru al la Izraelidoj, ke ili venigu al vi bovinon ruĝan, sanan, kiu ne havas difekton kaj sur kiun ne estis metita jugo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Kaj donu ĝin al Eleazar, la pastro, kaj li elkonduku ĝin ekster la tendaron, kaj oni buĉu ĝin antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Kaj Eleazar, la pastro, prenu iom el ĝia sango per sia fingro kaj aspergu sep fojojn per ĝia sango en la direkto al la antaŭa parto de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Kaj oni forbruligu la bovinon antaŭ liaj okuloj: ĝian felon kaj ĝian karnon kaj ĝian sangon kune kun ĝia sterko oni forbruligu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Kaj la pastro prenu cedran lignon kaj hisopon kaj ruĝan lanon kaj ĵetu en la brulaĵon de la bovino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Kaj la pastro lavu siajn vestojn kaj banu sian korpon en akvo, kaj poste li venu en la tendaron, kaj la pastro restos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Kaj tiu, kiu ĝin forbruligis, lavu siajn vestojn per akvo kaj banu sian korpon en akvo, kaj li restos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Kaj viro pura kolektu la cindron de la bovino kaj metu ĝin ekster la tendaro sur puran lokon, kaj ĝi estos konservata por la komunumo de la Izraelidoj por la akvo puriga: tio estas ofero propeka.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Kaj la kolektinto de la cindro de la bovino lavu siajn vestojn, kaj li restos malpura ĝis la vespero. Tio estos leĝo eterna por la Izraelidoj, kaj por la fremduloj, kiuj loĝas inter ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Kiu ektuŝis la kadavron de ia homo, tiu restos malpura dum sep tagoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'li senpekigos sin per ĝi en la tria tago kaj en la sepa tago, kaj li fariĝos pura; kaj se li ne senpekigos sin en la tria tago kaj en la sepa tago, li ne fariĝos pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Ĉiu, kiu ektuŝis la kadavron de homo, kiu mortis, kaj ne senpekigos sin, tiu malpurigas la loĝejon de la Eternulo; kaj tiu homo ekstermiĝos el inter Izrael; ĉar li ne estas aspergita per puriga akvo, li estas malpura, lia malpureco estas ankoraŭ sur li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Jen estas la leĝo: se homo mortis en tendo, tiam ĉiu, kiu venas en la tendon, kaj ĉio, kio troviĝas en la tendo, estos malpura dum sep tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Kaj ĉiu nefermita vazo, sur kiu ne estas kovrilo kun ŝnureto, estas malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Kaj ĉiu, kiu ektuŝis sur kampo glavmortigiton aŭ mortinton aŭ oston de homo aŭ tombon, estos malpura dum sep tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Oni prenu por la malpurulo iom el la cindro de la bruligita pekofero kaj verŝu sur ĝin akvon vivan en vazon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'kaj viro pura prenu hisopon kaj trempu ĝin en akvo, kaj aspergu la tendon kaj ĉiujn vazojn, kaj la homojn, kiuj tie estis, kaj la tuŝinton de la osto aŭ de la mortigito aŭ de la mortinto aŭ de la tombo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Kaj la purulo aspergu la malpurulon en la tria tago kaj en la sepa tago kaj senpekigu lin en la sepa tago; kaj li lavu siajn vestojn kaj banu sin en akvo, kaj vespere li estos pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Kaj se iu estos malpura kaj ne senpekigos sin, tiu ekstermiĝos el inter la komunumo, ĉar li malpurigis la sanktejon de la Eternulo: li ne estas aspergita per puriga akvo, li estas malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Kaj tio estu por vi leĝo eterna. Kaj tiu, kiu aspergis per la puriga akvo, lavu siajn vestojn; kaj la ektuŝinto de la puriga akvo estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Kaj ĉio, kion ektuŝos la malpurulo, estos malpura; kaj la homo, kiu ektuŝis, estos malpura ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Kaj venis la Izraelidoj, la tuta komunumo, en la dezerton Cin en la unua monato; kaj la popolo ekloĝis en Kadeŝ, kaj tie mortis Mirjam kaj estis tie enterigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Kaj ne estis akvo por la komunumo, kaj ili kolektiĝis kontraŭ Moseo kaj Aaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'Kaj la popolo malpacis kontraŭ Moseo, kaj ili diris jene: Ho, kial ni ne mortis tiam, kiam mortis niaj fratoj antaŭ la Eternulo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Kaj kial vi venigis la komunumon de la Eternulo en ĉi tiun dezerton, por ke ni mortu ĉi tie kune kun niaj brutoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Kaj por kio vi elirigis nin el Egiptujo, por venigi nin al ĉi tiu malbona loko, kie oni ne povas semi, kie ne ekzistas figarboj nek vinberoj nek granatoj, kaj kie ne ekzistas akvo por trinki?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Tiam Moseo kaj Aaron iris de antaŭ la komunumo al la pordo de la tabernaklo de kunveno kaj ĵetiĝis vizaĝaltere, kaj la majesto de la Eternulo aperis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Prenu la bastonon kaj kunvenigu la komunumon, vi kaj via frato Aaron, kaj parolu antaŭ iliaj okuloj al la roko, kaj ĝi donos sian akvon; kaj vi elirigos por ili akvon el la roko, kaj vi trinkigos la komunumon kaj ĝiajn brutojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Kaj Moseo prenis la bastonon de antaŭ la Eternulo, kiel Li ordonis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Kaj Moseo kaj Aaron kunvenigis la komunumon antaŭ la rokon, kaj li diris al ili: Aŭskultu, ho ribeluloj, ĉu el ĉi tiu roko ni elirigu por vi akvon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Kaj Moseo levis sian manon kaj frapis la rokon per sia bastono du fojojn; kaj ekfluis multe da akvo, kaj trinkis la komunumo kaj ĝiaj brutoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Tiam la Eternulo diris al Moseo kaj al Aaron: Pro tio, ke vi ne kredis je Mi, por montri Min sankta en la okuloj de la Izraelidoj, tial vi ne venigos ĉi tiun komunumon en la landon, kiun Mi donas al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Tio estas la Akvo de Malpaco, ĉe kiu la Izraelidoj malpacis kontraŭ la Eternulo kaj per kiu Li montris Sin sankta al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Kaj Moseo sendis senditojn el Kadeŝ al la reĝo de Edom, por diri: Tiel diras via frato Izrael: Vi scias ĉiujn malfacilaĵojn, kiuj trafis nin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'niaj patroj foriris en Egiptujon, kaj ni loĝis en Egiptujo longan tempon, kaj la Egiptoj agis malbone kontraŭ ni kaj kontraŭ niaj patroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'kaj ni ekkriis al la Eternulo, kaj Li aŭdis nian voĉon, kaj Li sendis anĝelon kaj elkondukis nin el Egiptujo; kaj jen ni estas en Kadeŝ, urbo ĉe la fino de viaj limoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'permesu do al ni trairi vian landon; ni ne iros tra kampo nek tra vinberĝardeno, kaj ni ne trinkos akvon el la putoj; laŭ la ĉefa publika vojo ni iros, ni ne flankiĝos dekstren nek maldekstren, ĝis ni trapasos viajn limojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Sed Edom diris al li: Vi ne trapasos min, alie mi eliros kun glavo renkonte al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Kaj la Izraelidoj diris al li: Laŭ la granda vojo ni iros; kaj se ni trinkos vian akvon, mi kaj miaj brutoj, mi pagos pro ĝi; nenio pli, sole per miaj piedoj mi trairos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Sed li diris: Ne trairu. Kaj Edom elpaŝis kontraŭ lin kun popolo multenombra kaj kun mano forta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Kaj Edom ne volis permesi al Izrael trapasi liajn limojn; kaj Izrael iris flanke de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Kaj ili elmoviĝis el Kadeŝ; kaj la Izraelidoj, la tuta komunumo, venis al la monto Hor.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Kaj la Eternulo ekparolis al Moseo kaj al Aaron sur la monto Hor, ĉe la limo de la lando Edoma, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Aaron alkolektiĝu al sia popolo; ĉar pro tio, ke vi malobeis Mian ordonon ĉe la Akvo de Malpaco, li ne venos en la landon, kiun Mi donas al la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Prenu Aaronon, kaj Eleazaron, lian filon, kaj suririgu ilin sur la monton Hor;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'kaj deprenu de Aaron liajn vestojn, kaj surmetu ilin sur Eleazaron, lian filon; kaj Aaron alkolektiĝu al sia popolo kaj mortu tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Kaj Moseo faris, kiel ordonis la Eternulo; kaj ili suriris sur la monton Hor antaŭ la okuloj de la tuta komunumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Kaj Moseo deprenis de Aaron liajn vestojn, kaj surmetis ilin sur Eleazaron, lian filon. Kaj Aaron mortis tie sur la supro de la monto. Kaj Moseo kaj Eleazar malsupreniris de la monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Kaj la tuta komunumo vidis, ke Aaron mortis, kaj la tuta domo de Izrael priploris Aaronon dum tridek tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Kaj la Kanaanido, la reĝo de Arad, kiu loĝis en la Sudo, aŭdis, ke Izrael venas per la vojo de Atarim; kaj li ekbatalis kontraŭ Izrael kaj kaptis kelkajn kiel militkaptitojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Tiam Izrael faris sanktan promeson al la Eternulo, kaj diris: Se Vi donos ĉi tiun popolon en mian manon, tiam mi detruos iliajn urbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Kaj la Eternulo elaŭskultis la voĉon de Izrael kaj fordonis la Kanaanidojn; kaj oni pereigis ilin kaj iliajn urbojn kaj donis al la loko la nomon Ĥorma.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Kaj ili elmoviĝis de la monto Hor laŭ la vojo al la Ruĝa Maro, por ĉirkaŭiri la landon de Edom. Kaj senkuraĝiĝis la animo de la popolo sur la vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'Kaj la popolo ekparolis kontraŭ Dio kaj kontraŭ Moseo: Kial vi elkondukis nin el Egiptujo, por ke ni mortu en la dezerto? ĉar ekzistas nek pano nek akvo, kaj al nia animo naŭzas la mizera nutraĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Tiam la Eternulo sendis sur la popolon venenajn serpentojn, kaj ili mordis la popolon, kaj mortis multe da homoj el Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Kaj la popolo venis al Moseo, kaj diris: Ni pekis, parolante kontraŭ la Eternulo kaj kontraŭ vi; preĝu al la Eternulo, ke Li forigu de ni la serpentojn. Kaj Moseo preĝis pri la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Kaj la Eternulo diris al Moseo: Faru al vi serpenton kupran kaj metu ĝin sur stangon; kaj ĉiu mordita, kiu ekrigardos ĝin, restos viva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Kaj Moseo faris kupran serpenton kaj metis ĝin sur stangon; kaj se serpento mordis iun kaj ĉi tiu ekrigardis la kupran serpenton, li restis viva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Kaj la Izraelidoj elmoviĝis, kaj starigis sian tendaron en Obot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Kaj ili elmoviĝis el Obot, kaj starigis sian tendaron en Ije-Abarim en la dezerto, kiu estas kontraŭ Moab, en la oriento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'De tie ili elmoviĝis, kaj starigis sian tendaron en la valo de Zared.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'De tie ili elmoviĝis, kaj starigis sian tendaron apud tiu parto de Arnon en la dezerto, kiu estas ekster la limoj de la Amoridoj; ĉar Arnon estas la limo de Moab, inter Moab kaj la Amoridoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Tial estas dirite en la Libro de la Militoj de la Eternulo: Vaheb en Sufa, Kaj la valoj de Arnon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'Kaj la deklivo de la valoj, Kiu turniĝas al la kolonio Ar Kaj apogiĝas al la limo de Moab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Kaj de tie al Beer; tio estas tiu puto, pri kiu la Eternulo diris al Moseo: Kunvenigu la popolon, kaj Mi donos al ili akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Tiam kantis Izrael ĉi tiun kanton: Leviĝu, puto, ni kantu pri ĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Puto, kiun fosis princoj, Boris eminentuloj de la popolo, Per la sceptro, per siaj bastonoj. Kaj el tiu dezerto al Matana,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'kaj el Matana al Naĥaliel, kaj el Naĥaliel al Bamot,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'kaj el Bamot al la valo, kiu estas sur la kampo de Moab, ĉe la supro de Pisga, kiu estas turnita al la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Kaj Izrael sendis senditojn al Siĥon, reĝo de la Amoridoj, por diri:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Mi dezirus trairi vian landon; ni ne devojiĝos sur kampon aŭ en vinberĝardenon, ni ne trinkos akvon el puto; laŭ la ĉefa publika vojo ni iros, ĝis ni trapasos viajn limojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Sed Siĥon ne permesis al Izrael trapasi liajn limojn; kaj Siĥon kolektis sian tutan popolon kaj eliris kontraŭ Izraelon en la dezerton kaj venis ĝis Jahac kaj ekbatalis kontraŭ Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Kaj Izrael frapis lin per la glavo, kaj ekposedis lian landon de Arnon ĝis Jabok, ĝis la Amonidoj; ĉar forta estis la limo de la Amonidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Kaj Izrael prenis ĉiujn tiujn urbojn; kaj Izrael ekloĝis en ĉiuj urboj de la Amoridoj, en Ĥeŝbon kaj en ĉiuj ĝiaj dependantaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Ĉar Ĥeŝbon estis la urbo de Siĥon, la reĝo de la Amoridoj, kaj li militis kontraŭ la antaŭa reĝo de Moab kaj prenis el lia mano lian tutan landon ĝis Arnon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Tial diras alegoriistoj: Iru Ĥeŝbonon; Konstruiĝu kaj fortikiĝu la urbo de Siĥon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Ĉar fajro eliris el Ĥeŝbon, Flamo el la urbo de Siĥon; Ĝi formanĝis Ar-Moabon, La mastrojn de la altaĵoj de Arnon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Ve al vi, Moab! Vi pereis, ho popolo de Kemoŝ! Li faris el siaj filoj forkurintojn Kaj el siaj filinoj kaptitinojn De la reĝo de la Amoridoj Siĥon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Ni faligis ilin; pereis Ĥeŝbon ĝis Dibon; Kaj ni ruinigis ilin ĝis Nofaĥ, Kiu estas apud Medba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Kaj Izrael loĝis en la lando de la Amoridoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Kaj Moseo sendis, por esplorrigardi Jazeron, kaj ili militakiris ĝiajn vilaĝojn, kaj forpelis la Amoridojn, kiuj tie estis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Kaj ili forturniĝis kaj ekiris laŭ la vojo al Baŝan. Tiam eliris al ili renkonte Og, la reĝo de Baŝan, li kaj lia tuta popolo, por batali ĉe Edrei.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Kaj la Eternulo diris al Moseo: Ne timu lin, ĉar en vian manon Mi fordonos lin kaj lian tutan popolon kaj lian landon, kaj vi agos kun li, kiel vi agis kun Siĥon, la reĝo de la Amoridoj, kiu loĝis en Ĥeŝbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Kaj ili venkobatis lin kaj liajn filojn kaj lian tutan popolon, ĝis neniu restis; kaj ili ekposedis lian landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Kaj la Izraelidoj elmoviĝis, kaj haltis tendare en la stepoj de Moab, transe de Jordan, kontraŭ Jeriĥo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Balak, filo de Cipor, vidis ĉion, kion Izrael faris al la Amoridoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Kaj Moab tre timis tiun popolon, ĉar ĝi estis multenombra; kaj Moab ektremis antaŭ la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Kaj Moab diris al la ĉefoj de Midjan: Nun tiu popolo formanĝos nian tutan ĉirkaŭaĵon, kiel bovo formanĝas la herbon de la kampo. Kaj Balak, filo de Cipor, estis reĝo de Moab en tiu tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Kaj li sendis senditojn al Bileam, filo de Beor, en Petoron, kiu estis ĉe la Rivero, en la landon de sia popolo, por voki lin, kaj diri: Jen popolo eliris el Egiptujo, jen ĝi kovris la vizaĝon de la tero, kaj ĝi loĝas kontraŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Nun venu do, malbenu al mi tiun popolon, ĉar ĝi estas pli forta ol mi; eble tiam mi povos venkobati ĝin kaj elpeli ĝin el la lando; ĉar mi scias, ke kiun vi benas, tiu estas benita, kaj kiun vi malbenas, tiu estas malbenita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Kaj iris la plejaĝuloj de Moab kaj la plejaĝuloj de Midjan, havante en siaj manoj la donacojn pro la sorĉado, kaj ili venis al Bileam kaj diris al li la vortojn de Balak.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'Kaj li diris al ili: Tradormu ĉi tie la nokton, kaj mi donos al vi respondon, konforme al tio, kion diros al mi la Eternulo. Kaj la ĉefoj de Moab restis ĉe Bileam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Kaj Dio venis al Bileam, kaj diris: Kiuj estas tiuj viroj ĉe vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Kaj Bileam diris al Dio: Balak, filo de Cipor, reĝo de Moab, sendis al mi, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Jen estas la popolo, kiu eliris el Egiptujo, kaj ĝi kovris la vizaĝon de la tero; venu do, malbenu ĝin al mi, eble tiam mi povos batali kontraŭ ĝi kaj forpeli ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Tiam Dio diris al Bileam: Ne iru kun ili; ne malbenu la popolon, ĉar ĝi estas benita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Kaj Bileam leviĝis matene, kaj diris al la ĉefoj de Balak: Iru en vian landon, ĉar la Eternulo ne volas permesi al mi iri kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Kaj leviĝis la ĉefoj de Moab kaj venis al Balak, kaj diris: Bileam ne volas iri kun ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Balak sendis plue ĉefojn, pli grandajn kaj pli eminentajn ol tiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Kaj ili venis al Bileam, kaj diris al li: Tiel diris Balak, filo de Cipor: Ne rifuzu do iri al mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'ĉar mi tre honoros vin, kaj ĉion, kion vi diros al mi, mi faros; venu do, malbenu al mi tiun popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Sed Bileam respondis kaj diris al la servantoj de Balak: Eĉ se Balak donos al mi sian plenan domon da arĝento kaj oro, mi ne povas malobei la ordonon de la Eternulo, mia Dio, farante ion malgrandan aŭ grandan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Tamen restu ĉi tie ankaŭ vi dum la nokto, kaj mi sciiĝos, kion plue diros al mi la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Kaj Dio venis al Bileam en la nokto, kaj diris al li: Se tiuj viroj venis, por voki vin, leviĝu, iru kun ili, sed faru nur tion, kion Mi diros al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Kaj Bileam leviĝis matene kaj selis sian azeninon kaj iris kun la ĉefoj de Moab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Kaj ekflamis la kolero de Dio pro tio, ke li iris; kaj anĝelo de la Eternulo stariĝis sur la vojo, por malhelpi lin. Li rajdis sur sia azenino, kaj du liaj junuloj estis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Kaj la azenino ekvidis la anĝelon de la Eternulo, starantan sur la vojo kun elingigita glavo en la mano, kaj la azenino forturniĝis de la vojo kaj iris sur la kampon; kaj Bileam ekbatis la azeninon, por returni ĝin sur la vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Tiam la anĝelo de la Eternulo stariĝis sur la vojeto inter vinberĝardenoj, kie estis barilo sur unu flanko kaj barilo sur la dua flanko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Kaj la azenino ekvidis la anĝelon de la Eternulo, kaj alpremis sin al la muro kaj alpremis la piedon de Bileam al la muro; kaj li denove ĝin batis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Kaj la anĝelo de la Eternulo denove forlasis sian lokon, kaj stariĝis sur malvasta loko, kie oni ne povas flankeniri dekstren, nek maldekstren.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Kiam la azenino ekvidis la anĝelon de la Eternulo, ĝi kuŝiĝis sub Bileam. Kaj ekflamis la kolero de Bileam, kaj li batis la azeninon per la bastono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Tiam la Eternulo malŝlosis la buŝon de la azenino, kaj ĝi diris al Bileam: Kion mi faris al vi, ke vi batis min jam tri fojojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Kaj Bileam diris al la azenino: Ĉar vi mokis min; se mi havus glavon en mia mano, mi nun mortigus vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Kaj la azenino diris al Bileam: Ĉu mi ne estas via azenino, sur kiu vi rajdadis de longatempe ĝis la nuna tago? ĉu mi kutimis tiel fari al vi? Kaj li diris: Ne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Tiam la Eternulo malkovris la okulojn de Bileam, kaj li ekvidis la anĝelon de la Eternulo, starantan sur la vojo kun elingigita glavo en sia mano; kaj li kliniĝis, kaj ĵetiĝis vizaĝaltere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Kaj la anĝelo de la Eternulo diris al li: Kial vi batis vian azeninon jam tri fojojn? jen Mi eliris, por malhelpi, ĉar malbona estas via vojo antaŭ Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'La azenino ekvidis Min, kaj forturniĝis antaŭ Mi jam tri fojojn; se ĝi ne forturniĝus de Mi, tiam Mi vin mortigus kaj ĝin Mi lasus vivi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Tiam Bileam diris al la anĝelo de la Eternulo: Mi pekis, ĉar mi ne sciis, ke Vi staras kontraŭ mi sur la vojo; nun, se tio ne plaĉas al Vi, mi iros returne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Sed la anĝelo de la Eternulo diris al Bileam: Iru kun la viroj; sed nur tion, kion Mi diros al vi, vi diru. Kaj Bileam iris kun la ĉefoj de Balak.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Kiam Balak aŭdis, ke Bileam venis, li eliris renkonte al li ĝis tiu Moaba urbo, kiu troviĝas ĉe la limo apud Arnon, kiu estas ĉe la fino de la limo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Kaj Balak diris al Bileam: Mi sendis ja al vi, por voki vin; kial do vi ne iris al mi? ĉu efektive mi ne povas honori vin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Sed Bileam diris al Balak: Jen mi venis al vi; tamen ĉu mi povas ion diri al vi? kion Dio enmetos en mian buŝon, tion mi diros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Kaj Bileam iris kun Balak, kaj ili venis al Kirjat-Ĥucot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Kaj Balak buĉis bovojn kaj ŝafojn, kaj sendis al Bileam, kaj al la ĉefoj, kiuj estis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'En la sekvanta mateno Balak prenis Bileamon kaj surkondukis lin sur la altaĵojn de Baal, kaj li ekvidis de tie la finan parton de la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Kaj Bileam diris al Balak: Konstruu al mi ĉi tie sep altarojn, kaj pretigu al mi ĉi tie sep bovidojn kaj sep virŝafojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Kaj Balak faris, kiel diris Bileam; kaj Balak kaj Bileam oferis po unu bovido kaj po unu virŝafo sur ĉiu altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Kaj Bileam diris al Balak: Staru ĉe via brulofero, kaj mi iros; eble la Eternulo venos al mi renkonte, kaj kion Li montros al mi, tion mi diros al vi. Kaj li iris sur la altaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Kaj Dio renkontiĝis al Bileam, kaj ĉi tiu diris al Li: La sep altarojn mi pretigis, kaj mi oferis po unu bovido kaj po unu virŝafo sur ĉiu altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Kaj la Eternulo enmetis vorton en la buŝon de Bileam, kaj diris: Reiru al Balak kaj parolu tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Kaj li revenis al tiu, kaj jen tiu staras ĉe sia brulofero, li kaj ĉiuj ĉefoj de Moab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Kaj li komencis sian inspiritaĵon, kaj diris: El Aram venigis min Balak, Reĝo de Moab, el la montoj orientaj: Venu, malbenu al mi Jakobon, Kaj venu, malbondiru kontraŭ Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Kiel mi tiun malbenos, kiun ne malbenas Dio? Kiel mi tiun malbondiros, kiun ne malbondiras la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'De la supro de rokoj mi vidas lin, Kaj de altaĵoj mi rigardas lin; Jen la popolo loĝas aparte Kaj ne estas kalkulata inter la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Kiu kalkulis la polvon de Jakob Kaj la nombron de kvarono de Izrael? Mortu mia animo per la morto de justuloj, Kaj mia fino estu simila al ilia!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Tiam Balak diris al Bileam: Kion vi faris al mi? por malbeni miajn malamikojn mi prenis vin, kaj jen vi ilin benas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Kaj li respondis kaj diris: Ĉu ne tion, kion la Eternulo metas en mian buŝon, mi devas precize diri?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Kaj Balak diris al li: Venu do kun mi al alia loko, de kiu vi ilin vidos; nur ilian parton vi vidos, la tutan vi ilin ne vidos; kaj malbenu ilin al mi de tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Kaj li prenis lin sur la kampon de ĉirkaŭrigardantoj, sur la supron de Pisga, kaj li konstruis sep altarojn kaj oferis po unu bovido kaj unu virŝafo sur ĉiu altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Kaj li diris al Balak: Staru ĉi tie ĉe via brulofero, kaj mi iros renkonte tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Kaj la Eternulo renkontiĝis al Bileam kaj metis vorton en lian buŝon, kaj diris: Reiru al Balak kaj parolu tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Kaj li venis al li, kaj jen li staras ĉe sia brulofero, kaj kun li la ĉefoj de Moab. Kaj Balak diris al li: Kion parolis la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Kaj li komencis sian inspiritaĵon, kaj diris: Leviĝu, Balak, kaj aŭskultu; Atentu min, filo de Cipor.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Dio ne estas homo, ke Li mensogus, Kaj ne homido, ke Li pentus. Ĉu Li dirus kaj ne farus, Parolus kaj ne plenumus?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Jen beno estas komisiita al mi; Li benas, kaj mi ne povas tion ŝanĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Li ne vidis pekon ĉe Jakob, Kaj Li ne rimarkis malpiecon ĉe Izrael; La Eternulo, lia Dio, estas kun li, Kaj reĝa aklamado estas ĉe li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Dio, kiu elkondukis ilin el Egiptujo, Estas por ili kiel la forto de bubalo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Ĉar ne ekzistas sorĉado en Jakob, Nek aŭgurado en Izrael; Siatempe estas dirate al Jakob kaj al Izrael, kion faras Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Jen la popolo stariĝas kiel leonino Kaj leviĝas kiel leono; Ĝi ne kuŝiĝos, antaŭ ol ĝi manĝos rabakiron Kaj antaŭ ol ĝi trinkos sangon de mortigitoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Kaj Balak diris al Bileam: Nek per malbeno malbenu ilin, nek per beno benu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Sed Bileam respondis kaj diris al Balak: Ĉu mi ne diris al vi, ke ĉion, kion diros la Eternulo, tion mi faros?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Kaj Balak diris al Bileam: Venu, mi prenos vin sur alian lokon; eble plaĉos al Dio, kaj vi malbenos ilin al mi de tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Kaj Balak prenis Bileamon sur la supron de Peor, kiu estas turnita al la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Kaj Bileam diris al Balak: Konstruu al mi ĉi tie sep altarojn, kaj pretigu al mi ĉi tie sep bovidojn kaj sep virŝafojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Kaj Balak faris, kiel diris Bileam, kaj oferis po unu bovido kaj po unu virŝafo sur ĉiu altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Ĉar Bileam vidis, ke al la Eternulo plaĉas beni Izraelon, li ne iris, kiel antaŭe, por aŭguri, sed li turnis sian vizaĝon al la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Kaj Bileam levis siajn okulojn, kaj ekvidis Izraelon, starantan laŭ siaj triboj; kaj la spirito de Dio venis sur lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'Kaj li ekparolis sian inspiritaĵon, kaj diris: Parolas Bileam, filo de Beor, Kaj parolas viro kun malfermita okulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'Parolas tiu, kiu aŭdas la vortojn de Dio, Kaj kiu vidas la vizion de la Plejpotenculo; Li falas, sed malfermitaj estas liaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Kiel belaj estas viaj tendoj, ho Jakob, Viaj loĝejoj, ho Izrael!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Kiel valoj ili etendiĝas, Kiel ĝardenoj apud rivero, Kiel arboj aloaj, plantitaj de la Eternulo, Kiel cedroj apud akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Fluos akvo el liaj siteloj, Kaj lia semo estos ĉe multaj akvoj; Superos Agagon lia reĝo, Kaj altiĝos lia regno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Dio, kiu elkondukis lin el Egiptujo, Estas por li kiel la forto de bubalo; Li formanĝas la popolojn, kiuj estas malamikaj al li, Kaj iliajn ostojn li frakasas Kaj per siaj sagoj disbatas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Li genuiĝis, li kuŝiĝis, Kiel leono kaj kiel leonino; Kiu lin levos? Viaj benantoj estas benataj, Kaj viaj malbenantoj estas malbenataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Tiam ekflamis la kolero de Balak kontraŭ Bileam, kaj li kunefrapis siajn manojn; kaj Balak diris al Bileam: Por malbeni miajn malamikojn mi vokis vin, kaj vi nun benis ilin jam tri fojojn!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Kaj nun foriĝu sur vian lokon; mi intencis honori vin, sed jen la Eternulo senigis vin je la honoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Kaj Bileam diris al Balak: Ĉu eĉ al viaj senditoj, kiujn vi sendis al mi, mi ne parolis jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Se Balak eĉ donus al mi sian plenan domon da arĝento kaj oro, mi ne povus malobei la ordonon de la Eternulo, farante bonon aŭ malbonon laŭ mia deziro? kion diros la Eternulo, tion mi diros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Kaj nun mi iras al mia popolo; venu, mi sciigos al vi, kion faros tiu popolo al via popolo en la malproksima venonta tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Kaj li ekparolis sian inspiritaĵon, kaj diris: Parolas Bileam, filo de Beor, Kaj parolas viro kun malfermita okulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'Parolas tiu, kiu aŭdas la vortojn de Dio Kaj scias la penson de la Plejaltulo, Kaj kiu vidas la vizion de la Plejpotenculo; Li falas, sed malfermitaj estas liaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Mi vidas lin, sed ne nun; Mi rigardas lin, sed ne proksime. Eliros stelo el Jakob, Kaj leviĝos sceptro el Izrael, Detruos la randojn de Moab Kaj frakasos ĉiujn filojn de malordo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Kaj Edom estos submetito, Kaj Seir estos submetito de siaj malamikoj; Sed Izrael havos venkon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Kaj la reganto eliros el Jakob, Kaj li pereigos la restintojn el la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Kaj li ekvidis Amalekon, kaj li ekparolis sian inspiritaĵon, kaj diris: La unua el la popoloj estis Amalek, Sed lia fino estos pereo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Kaj li ekvidis la Kenidojn, kaj li ekparolis sian inspiritaĵon, kaj diris: Fortika estas via loĝejo, Kaj aranĝita sur roko estas via nesto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Sed ruinigita estos Kain, Baldaŭ Aŝur vin kaptos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Kaj li ekparolis sian inspiritaĵon, kaj diris: Ve! kiu vivos, kiam Dio tion faros?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Kaj venos ŝipoj de la lando de la Kitidoj, Kaj ili humiligos Aŝuron kaj humiligos Eberon; Sed ankaŭ ili pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Kaj Bileam leviĝis, kaj foriris kaj revenis al sia loko; kaj ankaŭ Balak iris sian vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Kaj Izrael loĝis en Ŝitim, kaj la popolo komencis malĉastadi kun la filinoj de Moab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'Kaj ili invitadis la popolon al la oferoj de siaj dioj, kaj la popolo manĝadis kaj kliniĝadis antaŭ iliaj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Kaj Izrael aliĝis al Baal-Peor; kaj ekflamis la kolero de la Eternulo kontraŭ Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Kaj la Eternulo diris al Moseo: Prenu ĉiujn estrojn de la popolo kaj pendigu ilin al la Eternulo kontraŭ la suno, kaj deturniĝos de Izrael la furiozo de la kolero de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Kaj Moseo diris al la juĝistoj de Izrael: Mortigu ĉiu siajn homojn, kiuj aliĝis al Baal-Peor.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Kaj jen iu el la Izraelidoj venis kaj alkondukis al siaj fratoj Midjanidinon antaŭ la okuloj de Moseo kaj antaŭ la okuloj de la tuta komunumo de Izrael, dum ili ploris ĉe la pordo de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Kiam tion vidis Pineĥas, filo de Eleazar, la filo de la pastro Aaron, li leviĝis el inter la komunumo kaj prenis ponardegon en sian manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'Kaj li iris post la Izraelido en la dormejon, kaj trapikis ilin ambaŭ, la Izraelidon kaj la virinon tra ŝia ventro; kaj tiam ĉesiĝis la punfrapado de la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Kaj la nombro de la mortintoj per la punfrapado estis dudek kvar mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Pineĥas, filo de Eleazar, la filo de la pastro Aaron, deturnis Mian koleregon de la Izraelidoj, ĉar li fervoris pri Mi inter ili, kaj Mi ne ekstermis la Izraelidojn en Mia severeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Tial diru: Jen Mi donas al li Mian interligon pri paco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'kaj ĝi estu por li kaj por lia idaro post li interligo de eterna pastreco, pro tio, ke li fervoris pri sia Dio kaj pekliberigis la Izraelidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'La nomo de la mortigita Izraelido, kiu estis mortigita kune kun la Midjanidino, estis Zimri, filo de Salu, ĉefo de patrodomo el la Simeonidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'kaj la nomo de la mortigita Midjanidino estis Kozbi, filino de Cur, estro de la anoj de patrodomo en Midjan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Estu malamikoj al la Midjanidoj kaj batu ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'ĉar ili estas malamikoj al vi per sia insido, kiun ili faris al vi per Peor, kaj per Kozbi, la filino de la Midjana estro, ilia fratino mortigita en la tago de la punfrapado pro Peor.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Kaj post la punfrapado la Eternulo ekparolis al Moseo, kaj al Eleazar, filo de la pastro Aaron, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Kalkulu la tutan komunumon de la Izraelidoj en la aĝo de dudek jaroj kaj pli, laŭ iliaj patrodomoj, ĉiujn militkapablajn en Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Kaj ekparolis al ili Moseo kaj la pastro Eleazar sur la stepoj de Moab apud la Jeriĥa Jordan, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'Kalkulu la popolon en la aĝo de dudek jaroj kaj pli, kiel la Eternulo ordonis al Moseo kaj al la Izraelidoj, kiuj eliris el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruben, la unuenaskito de Izrael. La filoj de Ruben: de Ĥanoĥ, la familio de la Ĥanoĥidoj; de Palu, la familio de la Paluidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'de Ĥecron, la familio de la Ĥecronidoj; de Karmi, la familio de la Karmiidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Tio estas la familioj de la Rubenidoj; kaj ilia nombro estas kvardek tri mil sepcent tridek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Kaj la filoj de Palu: Eliab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Kaj la filoj de Eliab: Nemuel kaj Datan kaj Abiram; tio estas tiuj Datan kaj Abiram, eminentuloj de la komunumo, kiuj ribelis kontraŭ Moseo kaj Aaron en la anaro de Koraĥ, kiam ili ribelis kontraŭ la Eternulo');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'kaj la tero malfermis sian buŝon kaj englutis ilin kaj Koraĥon ĉe la morto de la anaro, kiam la fajro ekstermis la ducent kvindek homojn, kaj ili fariĝis averto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Sed la filoj de Koraĥ ne mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'La filoj de Simeon laŭ iliaj familioj: de Nemuel, la familio de la Nemuelidoj; de Jamin, la familio de la Jaminidoj; de Jaĥin, la familio de la Jaĥinidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'de Zeraĥ, la familio de la Zeraĥidoj; de Ŝaul, la familio de la Ŝaulidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Tio estas la familioj de la Simeonidoj, dudek du mil ducent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'La filoj de Gad laŭ iliaj familioj: de Cefon, la familio de la Cefonidoj; de Ĥagi, la familio de la Ĥagiidoj; de Ŝuni, la familio de la Ŝuniidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'de Ozni, la familio de la Ozniidoj; de Eri, la familio de la Eriidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'de Arod, la familio de la Arodidoj; de Areli, la familio de la Areliidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Tio estas la familioj de la Gadidoj, laŭ ilia nombro kvardek mil kvincent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'La filoj de Jehuda: Er kaj Onan; sed Er kaj Onan mortis en la lando Kanaana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Kaj la filoj de Jehuda laŭ iliaj familioj estis: de Ŝela, la familio de la Ŝelaidoj; de Perec, la familio de la Perecidoj; de Zeraĥ, la familio de la Zeraĥidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Kaj la filoj de Perec estis: de Ĥecron, la familio de la Ĥecronidoj; de Ĥamul, la familio de la Ĥamulidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Tio estas la familioj de Jehuda, laŭ ilia nombro sepdek ses mil kvincent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'La filoj de Isaĥar laŭ iliaj familioj: de Tola, la familio de la Tolaidoj; de Puva, la familio de la Puvaidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'de Jaŝub, la familio de la Jaŝubidoj; de Ŝimron, la familio de la Ŝimronidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Tio estas la familioj de Isaĥar, laŭ ilia nombro sesdek kvar mil tricent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'La filoj de Zebulun laŭ iliaj familioj: de Sered, la familio de la Seredidoj; de Elon, la familio de la Elonidoj; de Jaĥleel, la familio de la Jaĥleelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Tio estas la familioj de la Zebulunidoj, laŭ ilia nombro sesdek mil kvincent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'La filoj de Jozef laŭ iliaj familioj: Manase kaj Efraim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'La filoj de Manase: de Maĥir, la familio de la Maĥiridoj; kaj de Maĥir naskiĝis Gilead; de Gilead, la familio de la Gileadidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Jen estas la filoj de Gilead: de Iezer, la familio de la Iezeridoj; de Ĥelek, la familio de la Ĥelekidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'kaj de Asriel, la familio de la Asrielidoj; kaj de Ŝeĥem, la familio de la Ŝeĥemidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'kaj de Ŝemida, la familio de la Ŝemidaidoj; kaj de Ĥefer, la familio de la Ĥeferidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Kaj Celofĥad, filo de Ĥefer, ne havis filojn, sed nur filinojn; kaj la nomoj de la filinoj de Celofĥad estis: Maĥla kaj Noa kaj Ĥogla kaj Milka kaj Tirca.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Tio estas la familioj de Manase, laŭ ilia nombro kvindek du mil sepcent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Jen estas la filoj de Efraim laŭ iliaj familioj: de Ŝutelaĥ, la familio de la Ŝutelaĥidoj; de Beĥer, la familio de la Beĥeridoj; de Taĥan, la familio de la Taĥanidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Kaj jen estas la filoj de Ŝutelaĥ: de Eran, la familio de la Eranidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Tio estas la familioj de la filoj de Efraim, laŭ ilia nombro tridek du mil kvincent. Tio estas la filoj de Jozef laŭ iliaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'La filoj de Benjamen laŭ iliaj familioj: de Bela, la familio de la Belaidoj; de Aŝbel, la familio de la Aŝbelidoj; de Aĥiram, la familio de la Aĥiramidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'de Ŝefufam, la familio de la Ŝefufamidoj; de Ĥufam la familio de la Ĥufamidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Kaj la filoj de Bela estis: Ard kaj Naaman; de Ard, la familio de la Ardidoj; de Naaman, la familio de la Naamanidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Tio estas la filoj de Benjamen laŭ iliaj familioj, kaj ilia nombro estis kvardek kvin mil sescent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Jen estas la filoj de Dan laŭ iliaj familioj: de Ŝuĥam, la familio de la Ŝuĥamidoj. Tio estas la familioj de Dan laŭ iliaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Ĉiuj familioj de la Ŝuĥamidoj prezentis la nombron de sesdek kvar mil kvarcent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'La filoj de Aŝer laŭ iliaj familioj: de Jimna, la familio de la Jimnaidoj; de Jiŝvi, la familio de la Jiŝviidoj; de Beria, la familio de la Beriaidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'De la filoj de Beria: de Ĥeber, la familio de la Ĥeberidoj; de Malkiel, la familio de la Malkielidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Kaj la nomo de la filino de Aŝer estis Seraĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Tio estas la familioj de la filoj de Aŝer, laŭ ilia nombro kvindek tri mil kvarcent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'La filoj de Naftali laŭ iliaj familioj: de Jaĥceel, la familio de la Jaĥceelidoj; de Guni, la familio de la Guniidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'de Jecer, la familio de la Jeceridoj; de Ŝilem la familio de la Ŝilemidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Tio estas la familioj de Naftali laŭ iliaj familioj, kaj ilia nombro estis kvardek kvin mil kvarcent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Tia estis la kalkulita nombro de la Izraelidoj: sescent unu mil sepcent tridek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'Al tiuj estu dividita la tero kiel posedaĵo laŭ la nombro de la nomoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Al la plinombra donu pli grandan posedaĵon, kaj al la malplinombra donu malpli grandan posedaĵon; al ĉiu laŭ lia nombro estu donita lia posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Sed per loto oni dividu la teron; laŭ la nomo de siaj patraj triboj ili ricevu posedaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Per la loto oni dividu al ĉiu lian posedaĵon, kiel al la plinombraj, tiel al la malplinombraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Kaj jen estas la kalkulitoj de Levi laŭ iliaj familioj: de Gerŝon, la familio de la Gerŝonidoj; de Kehat, la familio de la Kehatidoj; de Merari, la familio de la Merariidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Jen estas la familioj de Levi: la familio de la Libniidoj, la familio de la Ĥebronidoj, la familio de la Maĥliidoj, la familio de la Muŝiidoj, la familio de la Koraĥidoj. Kaj de Kehat naskiĝis Amram.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Kaj la nomo de la edzino de Amram estis Joĥebed, filino de Levi, kiu estis naskita al Levi en Egiptujo; kaj ŝi naskis al Amram Aaronon kaj Moseon kaj ilian fratinon Mirjam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Kaj al Aaron naskiĝis Nadab kaj Abihu kaj Eleazar kaj Itamar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Sed Nadab kaj Abihu mortis, kiam ili alportis fremdan fajron antaŭ la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Kaj la nombro de iliaj kalkulitoj estis dudek tri mil, ĉiuj virseksuloj en la aĝo de pli ol unu monato; ĉar ili ne estis kalkulitaj kune kun la Izraelidoj, ĉar al ili ne estis donita posedaĵo inter la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Tio estas la nombro, kiun kalkulis Moseo kaj la pastro Eleazar, kiuj kalkulis la Izraelidojn sur la stepoj de Moab ĉe la Jeriĥa Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Kaj inter ili estis neniu el tiuj, kiujn kalkulis Moseo kaj la pastro Aaron, kiam ili kalkulis la Izraelidojn en la dezerto Sinaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Ĉar la Eternulo diris pri ili: Ili mortos en la dezerto. Kaj restis el ili neniu, krom Kaleb, filo de Jefune, kaj Josuo, filo de Nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Kaj aliris la filinoj de Celofĥad, filo de Ĥefer, filo de Gilead, filo de Maĥir, filo de Manase, el la familioj de Manase, filo de Jozef; kaj jen estas la nomoj de liaj filinoj: Maĥla kaj Noa kaj Ĥogla kaj Milka kaj Tirca;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'kaj ili stariĝis antaŭ Moseo kaj antaŭ la pastro Eleazar kaj antaŭ la estroj kaj la tuta komunumo ĉe la pordo de la tabernaklo de kunveno, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Nia patro mortis en la dezerto, kaj li ne estis inter la anaro, kiu ribelis kontraŭ la Eternulo en la anaro de Koraĥ; sed pro sia peko li mortis, kaj filojn li ne havis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Kial malaperu la nomo de nia patro el inter lia familio, ĉar li ne havis filon? Donu al ni posedaĵon inter la fratoj de nia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Kaj Moseo prezentis ilian aferon antaŭ la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Kaj la Eternulo diris al Moseo jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Prave parolas la filinoj de Celofĥad; efektive donu al ili heredan posedaĵon inter la fratoj de ilia patro, kaj transirigu la posedaĵon de ilia patro al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Kaj al la Izraelidoj diru jene: Se iu mortos, ne havante filon, tiam transirigu lian posedaĵon al lia filino;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'kaj se li ne havas filinon, tiam donu lian posedaĵon al liaj fratoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'kaj se li ne havas fratojn, donu lian posedaĵon al la fratoj de lia patro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'kaj se lia patro ne havas fratojn, donu lian posedaĵon al lia proksima parenco el lia familio, ke li heredu ĝin. Kaj tio estu por la Izraelidoj leĝa juro, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Kaj la Eternulo diris al Moseo: Supreniru sur ĉi tiun monton Abarim, kaj rigardu la landon, kiun Mi donis al la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Kaj kiam vi estos vidinta ĝin, vi alkolektiĝos al via popolo, vi ankaŭ, kiel alkolektiĝis via frato Aaron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'ĉar vi malobeis Mian ordonon en la dezerto Cin, dum la malpaco de la komunumo, ke vi montru ĉe la akvo Mian sanktecon antaŭ iliaj okuloj-tiu Akvo de Malpaco ĉe Kadeŝ en la dezerto Cin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Kaj Moseo ekparolis al la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'La Eternulo, Dio de la spiritoj de ĉiu karno, starigu super la komunumo viron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'kiu eliradus antaŭ ili kaj kiu eniradus antaŭ ili kaj kiu elkondukadus ilin kaj kiu enkondukadus ilin, por ke ne estu la komunumo de la Eternulo kiel ŝafoj, kiuj ne havas paŝtiston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Kaj la Eternulo diris al Moseo: Prenu al vi Josuon, filon de Nun, viron, kiu havas en si spiriton, kaj metu vian manon sur lin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'kaj starigu lin antaŭ Eleazar, la pastro, kaj antaŭ la tuta komunumo, kaj donu al li instrukciojn antaŭ iliaj okuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'kaj metu sur lin parton de via majesto, por ke aŭskultu lin la tuta komunumo de la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Kaj li staru antaŭ la pastro Eleazar kaj demandu lin pri decido per la signoj de lumo antaŭ la Eternulo; laŭ lia vorto devas eliri kaj laŭ lia vorto devas eniri li kaj ĉiuj Izraelidoj kun li kaj la tuta komunumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Kaj Moseo faris, kiel ordonis al li la Eternulo; kaj li prenis Josuon kaj starigis lin antaŭ la pastro Eleazar kaj antaŭ la tuta komunumo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'kaj li metis sur lin siajn manojn kaj donis al li instrukciojn, kiel la Eternulo parolis per Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Ordonu al la Izraelidoj kaj diru al ili: Mian oferon, Mian panon, Miajn fajroferojn, Mian agrablan odoraĵon observu, por alportadi al Mi en ilia tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Kaj diru al ili: Jen estas la fajrofero, kiun vi devas alportadi al la Eternulo: ŝafidojn jaraĝajn sendifektajn po du en ĉiu tago, kiel konstantan bruloferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Unu ŝafidon oferu matene, kaj la duan ŝafidon oferu ĉirkaŭ la vespero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'kaj dekonon de efo da delikata faruno kiel farunoferon, miksitan kun kvarono de hino da elpistita oleo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'Tio estas la brulofero konstanta, kia estis farata ĉe la monto Sinaj, kiel agrabla odoraĵo, fajrofero al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'Kaj ĝia verŝofero estu po kvarono de hino ĉe unu ŝafido; en la sanktejo vi devas verŝi la vinon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Kaj la duan ŝafidon oferu ĉirkaŭ la vespero; kun tia farunofero, kiel matene, kaj kun tia verŝofero faru fajroferon, agrablan odoraĵon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Sed en la tago sabata du ŝafidojn jaraĝajn sendifektajn kaj du dekonojn de efo da delikata faruno kiel farunoferon, miksitan kun oleo, kaj ĝian verŝoferon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'tio estas la brulofero de ĉiu sabato, krom la konstanta brulofero kaj ĝia verŝofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'Kaj en viaj monatkomencoj alportu bruloferon al la Eternulo: du bovidojn kaj unu virŝafon, sep jaraĝajn sendifektajn ŝafidojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'kaj tri dekonojn de efo da delikata faruno kiel farunoferon, miksitan kun oleo, por ĉiu bovido, kaj du dekonojn da delikata faruno kiel farunoferon, miksitan kun oleo, por la unu virŝafo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'kaj po unu dekono da delikata faruno kiel farunoferon, miksitan kun oleo, por ĉiu ŝafido; tio estas brulofero, agrabla odoraĵo, fajrofero al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Kaj iliaj verŝoferoj estu: duono de hino da vino por bovido, kaj triono de hino por virŝafo, kaj kvarono de hino por ŝafido. Tio estas ĉiumonata brulofero por ĉiuj monatoj de la jaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Kaj unu virkapro, kiel pekofero al la Eternulo, krom la konstanta brulofero, estu oferata kune kun sia verŝofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Kaj en la unua monato, en la dek-kvara tago de la monato, estas Pasko al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'Kaj en la dek-kvina tago de tiu monato estas festo; dum sep tagoj oni manĝu macojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'En la unua tago estas sankta kunveno; faru nenian servan laboron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'kaj alportu fajroferon, bruloferon al la Eternulo: du bovidojn kaj unu virŝafon kaj sep jaraĝajn ŝafidojn; sendifektaj ili estu ĉe vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'kaj kiel ilian farunoferon alportu delikatan farunon, miksitan kun oleo, tri dekonojn por bovido kaj du dekonojn por la virŝafo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'po unu dekono alportu por ĉiu el la sep ŝafidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'kaj unu virkapron, por pekliberigi vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Krom la matena brulofero, kiu estas konstanta brulofero, alportu tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Tiel faru en ĉiu el la sep tagoj; tio estas manĝaĵo, fajrofero, agrabla odoraĵo al la Eternulo; krom la konstanta brulofero oni tion alportu kune kun ĝia verŝofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Kaj en la sepa tago estu ĉe vi sankta kunveno; faru nenian servan laboron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Kaj en la tago de la unuaj fruktoj, kiam vi alportos novan farunoferon al la Eternulo en via festo de semajnoj, estu ĉe vi sankta kunveno; faru nenian servan laboron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'kaj alportu bruloferon, kiel agrablan odoraĵon al la Eternulo: du bovidojn, unu virŝafon, sep jaraĝajn ŝafidojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'kaj kiel ilian farunoferon delikatan farunon, miksitan kun oleo, tri dekonojn por ĉiu bovido, du dekonojn por la unu virŝafo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'po unu dekono por ĉiu el la sep ŝafidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'unu virkapron, por pekliberigi vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Krom la konstanta brulofero kaj ĝia verŝofero alportu tion; sendifektaj ili estu ĉe vi kaj kun siaj verŝoferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'Kaj en la sepa monato, en la unua tago de la monato, estu ĉe vi sankta kunveno; faru nenian servan laboron; tago de trumpetado ĝi estu por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Kaj alportu bruloferon, kiel agrablan odoraĵon al la Eternulo: unu bovidon, unu virŝafon, sep jaraĝajn ŝafidojn sendifektajn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'kaj ilian farunoferon: delikatan farunon, miksitan kun oleo, tri dekonojn por la bovido, du dekonojn por la virŝafo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'kaj po unu dekono por ĉiu el la sep ŝafidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'kaj unu virkapron, kiel pekoferon, por pekliberigi vin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'krom la monata brulofero kaj ĝia farunofero kaj la konstanta brulofero kaj ĝia farunofero; kaj iliajn verŝoferojn laŭ ilia regularo; kiel agrablan odoraĵon, fajroferon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Kaj en la deka tago de tiu sepa monato estu ĉe vi sankta kunveno; kaj premu viajn animojn; faru nenian laboron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'kaj alportu bruloferon al la Eternulo, agrablan odoraĵon: unu bovidon, unu virŝafon, sep jaraĝajn ŝafidojn; sendifektaj ili estu ĉe vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'kaj ilian farunoferon: delikatan farunon, miksitan kun oleo, tri dekonojn por la bovido, du dekonojn por la unu virŝafo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'po unu dekono por ĉiu el la sep ŝafidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'unu virkapron, kiel pekoferon, krom la pekofero de pekliberigo kaj la konstanta brulofero kaj ĝia farunofero kaj iliaj verŝoferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Kaj en la dek-kvina tago de la sepa monato estu ĉe vi sankta kunveno; faru nenian servan laboron, kaj festu feston al la Eternulo dum sep tagoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'kaj alportu bruloferon, fajroferon, agrablan odoraĵon al la Eternulo: dek tri bovidojn, du virŝafojn, dek kvar jaraĝajn ŝafidojn, sendifektaj ili estu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'kaj ilian farunoferon: delikatan farunon, miksitan kun oleo, po tri dekonoj por ĉiu el la dek tri bovidoj, po du dekonoj por ĉiu el la du virŝafoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'kaj po unu dekono por ĉiu el la dek kvar ŝafidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'kaj unu virkapron, kiel pekoferon, krom la konstanta brulofero, ĝia farunofero, kaj ĝia verŝofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Kaj en la dua tago: dek du bovidojn, du virŝafojn, dek kvar jaraĝajn ŝafidojn sendifektajn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'kaj ilian farunoferon kaj iliajn verŝoferojn por la bovidoj, por la virŝafoj, kaj por la ŝafidoj, laŭ ilia nombro, laŭ la regularo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'kaj unu virkapron, kiel pekoferon, krom la konstanta brulofero kaj ĝia farunofero kaj iliaj verŝoferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Kaj en la tria tago: dek unu bovidojn, du virŝafojn, dek kvar jaraĝajn ŝafidojn sendifektajn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'kaj ilian farunoferon kaj iliajn verŝoferojn por la bovidoj, por la virŝafoj, kaj por la ŝafidoj, laŭ ilia nombro, laŭ la regularo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'kaj unu virkapron pekoferan, krom la konstanta brulofero kaj ĝia farunofero kaj ĝia verŝofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Kaj en la kvara tago: dek bovidojn, du virŝafojn, dek kvar jaraĝajn ŝafidojn sendifektajn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'ilian farunoferon kaj iliajn verŝoferojn por la bovidoj, por la virŝafoj, kaj por la ŝafidoj, laŭ ilia nombro, laŭ la regularo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'kaj unu virkapron pekoferan, krom la konstanta brulofero, ĝia farunofero, kaj ĝia verŝofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Kaj en la kvina tago: naŭ bovidojn, du virŝafojn, dek kvar jaraĝajn ŝafidojn sendifektajn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'kaj ilian farunoferon kaj iliajn verŝoferojn por la bovidoj, por la virŝafoj, kaj por la ŝafidoj, laŭ ilia nombro, laŭ la regularo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'kaj unu virkapron pekoferan, krom la konstanta brulofero kaj ĝia farunofero kaj ĝia verŝofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'Kaj en la sesa tago: ok bovidojn, du virŝafojn, dek kvar jaraĝajn ŝafidojn sendifektajn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'kaj ilian farunoferon kaj iliajn verŝoferojn por la bovidoj, por la virŝafoj, kaj por la ŝafidoj, laŭ ilia nombro, laŭ la regularo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'kaj unu virkapron pekoferan, krom la konstanta brulofero, ĝia farunofero, kaj ĝia verŝofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Kaj en la sepa tago: sep bovidojn, du virŝafojn, dek kvar jaraĝajn ŝafidojn sendifektajn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'kaj ilian farunoferon kaj iliajn verŝoferojn por la bovidoj, por la virŝafoj, kaj por la ŝafidoj, laŭ ilia nombro, laŭ la regularo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'kaj unu virkapron pekoferan, krom la konstanta brulofero, ĝia farunofero, kaj ĝia verŝofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'En la oka tago estu ĉe vi sankta kunveno; faru nenian servan laboron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'kaj alportu bruloferon, fajroferon, agrablan odoraĵon al la Eternulo; unu bovidon, unu virŝafon, sep jaraĝajn ŝafidojn sendifektajn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'ilian farunoferon kaj iliajn verŝoferojn por la bovido, por la virŝafo, kaj por la ŝafidoj, laŭ ilia nombro, laŭ la regularo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'kaj unu virkapron pekoferan, krom la konstanta brulofero kaj ĝia farunofero kaj ĝia verŝofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Tion faru al la Eternulo en viaj festoj, krom viaj sanktaj promesitaĵoj kaj viaj propravolaj donacoj, viaj bruloferoj kaj viaj farunoferoj kaj viaj verŝoferoj kaj viaj pacoferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, 'Kaj Moseo raportis al la Izraelidoj konforme al ĉio, kion la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Kaj Moseo ekparolis al la tribestroj de la Izraelidoj, dirante: Jen kion ordonis la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Se iu faros sanktan promeson al la Eternulo aŭ ĵuros ĵuron, ligante sian animon, li ne rompu sian vorton, sed konforme al ĉio, kio eliris el lia buŝo, li faru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Kaj se virino faros sanktan promeson al la Eternulo aŭ ligos sin en la domo de sia patro, en sia juneco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'kaj ŝia patro aŭdos ŝian promeson, kaj la ligon, kiun ŝi metas sur sian animon, kaj ŝia patro silentos pri tio; tiam valoras ĉiuj ŝiaj promesoj, kaj ĉiu ligo, kiun ŝi metis sur sian animon, valoras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'Sed se ŝia patro malpermesos al ŝi en la tago, kiam li aŭdis, tiam ĉiuj ŝiaj promesoj kaj ĉiuj ŝiaj ligoj, per kiuj ŝi ligis sian animon, ne valoras; kaj la Eternulo pardonos al ŝi, ĉar ŝia patro malpermesis al ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Se ŝi fariĝos edzino, kaj sur ŝi estos ŝiaj promesoj, aŭ vorto, kiu elglitis el ŝia buŝo kaj ligis ŝian animon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'kaj ŝia edzo aŭdos, kaj li silentos en la tago, kiam li aŭdis; tiam valoras ŝiaj promesoj, kaj ŝiaj ligoj, per kiuj ŝi ligis sian animon, valoras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'Sed se en la tago, kiam ŝia edzo aŭdis, li malpermesas al ŝi, tiam li neniigas ŝian promeson, kiu estas sur ŝi, kaj tion, kio elglitis el ŝia buŝo kaj per kio ŝi ligis sian animon; kaj la Eternulo pardonos al ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'La promeso de vidvino kaj de eksedzino, ĉio, per kio ŝi ligis sian animon, valoras sur ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Se virino en la domo de sia edzo faris sanktan promeson aŭ per ĵuro metis ligon sur sian animon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'kaj ŝia edzo aŭdis kaj silentis, ne malpermesis al ŝi; tiam valoras ĉiuj ŝiaj promesoj, kaj ĉiu ligo, kiun ŝi metis sur sian animon, valoras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'Sed se ŝia edzo neniigis ilin en la tago, kiam li aŭdis; tiam ĉio, kio eliris el ŝia buŝo, ŝiaj promesoj kaj la ligoj de ŝia animo, ne valoras: ŝia edzo ilin neniigis; kaj la Eternulo pardonos al ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Ĉiun promeson kaj ĉiun ligiĝon per ĵuro fari premon al sia animo ŝia edzo povas valorigi aŭ ŝia edzo povas neniigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Se ŝia edzo silentis tagon por tago, tiam li valorigas ĉiujn ŝiajn promesojn, aŭ ĉiujn ligiĝojn, kiuj estas sur ŝi, li valorigas; ĉar li silentis en la tago, kiam li aŭdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Kaj se li neniigis ilin, post kiam li aŭdis, tiam li prenis sur sin ŝian kulpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Tio estas la leĝoj, kiujn la Eternulo donis al Moseo pri la rilatoj inter edzo kaj lia edzino, inter patro kaj lia filino en ŝia juneco en la domo de ŝia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Faru venĝon pro la Izraelidoj sur la Midjanidoj; kaj poste alkolektiĝu al via popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Kaj Moseo ekparolis al la popolo, dirante: Armu inter vi virojn por milito, ke ili iru kontraŭ Midjan, por fari venĝon de la Eternulo sur Midjan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Po mil el tribo, el ĉiuj triboj de Izrael, sendu en militon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Kaj oni eligis el la miloj de la Izraelidoj, po mil el ĉiu tribo, dek du mil armitojn por milito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Kaj Moseo sendis ilin, po mil el tribo, en militon, ilin kaj Pineĥason, filon de la pastro Eleazar, en militon, kaj la sanktaj vazoj kaj alarmaj trumpetoj estis en lia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Kaj ili militis kontraŭ Midjan, kiel la Eternulo ordonis al Moseo, kaj ili mortigis ĉiujn virseksulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Kaj la reĝojn de Midjan ili mortigis inter la aliaj mortigitoj: Evin, Rekemon, Curon, Ĥuron, kaj Reban, la kvin reĝojn de Midjan, kaj Bileamon, filon de Beor, ili mortigis per glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Kaj la Izraelidoj prenis en malliberecon la virinojn Midjanajn kaj iliajn infanojn; kaj ĉiujn iliajn brutojn kaj ilian tutan posedaĵon kaj havon ili rabis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'Kaj ĉiujn iliajn urbojn en iliaj lokoj de loĝado kaj ĉiujn iliajn kastelojn ili forbruligis per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'Kaj ili prenis la tutan kaptitaĵon kaj rabitaĵon, kiel la homojn, tiel ankaŭ la brutojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'Kaj ili venigis al Moseo kaj al la pastro Eleazar kaj al la komunumo de la Izraelidoj la kaptitojn kaj la prenitaĵon kaj la rabitaĵon en la tendaron sur la stepoj de Moab apud la Jeriĥa Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Kaj eliris Moseo kaj la pastro Eleazar kaj ĉiuj estroj de la komunumo renkonte al ili ekster la tendaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Kaj Moseo ekkoleris kontraŭ la militestroj, la milestroj kaj centestroj, kiuj venis el la milito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'Kaj Moseo diris al ili: Vi lasis vivi ĉiujn virinojn!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Jen ili estis ja por la Izraelidoj, laŭ la vortoj de Bileam, instigo por deturniĝi de la Eternulo al Peor; kaj pro tio estis ja la punfrapado en la komunumo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Kaj nun mortigu ĉiun virseksan infanon; kaj ĉiun virinon, kiu ekkonis viron sur kuŝejo de viro, mortigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'Sed ĉiun infanon virinseksan, kiu ne ekkonis kuŝejon de viro, lasu viva por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Kaj vi restu ekster la tendaro dum sep tagoj; ĉiu el vi kaj viaj kaptitoj, kiu mortigis homon, kaj ĉiu, kiu ektuŝis mortigiton, pekpurigu sin en la tria tago kaj en la sepa tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Kaj ĉiun veston kaj ĉiun objekton el felo kaj ĉion faritan el kapra lano kaj ĉiun lignan vazon pekpurigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Kaj la pastro Eleazar diris al la militistoj, kiuj iris en la militon: Tio estas la leĝa instrukcio, kiun la Eternulo ordonis al Moseo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Nur oron, arĝenton, kupron, feron, stanon, kaj plumbon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'ĉion, kio povas iri en fajron, trairigu tra fajro, kaj ĝi estos pura, tamen per puriga akvo oni ĝin pekpurigu; ĉion, kio ne povas iri en fajron, trairigu tra akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Kaj lavu viajn vestojn en la sepa tago kaj fariĝu puraj, kaj poste vi povas veni en la tendaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Kalkulu la kvanton de la prenita kaptitaĵo, kiel de la homoj, tiel ankaŭ de la brutoj, vi kaj la pastro Eleazar kaj la estroj de la familioj de la komunumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'Kaj dividu la prenitaĵon po duono inter tiuj, kiuj partoprenis en la milito kaj iris batali, kaj inter la tuta komunumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Kaj prenu imposton por la Eternulo de la militistoj, kiuj iris batali, po unu animo el kvincent, kiel el la homoj, tiel el la bovoj kaj el la azenoj kaj el la ŝafoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'Prenu tion el ilia duono, kaj donu al la pastro Eleazar, kiel oferdonon por la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Kaj el la duono, apartenanta al la Izraelidoj, prenu po unu kaptito el kvindek, kiel el la homoj, tiel ankaŭ el la bovoj, el la azenoj, kaj el la ŝafoj, el ĉiuj brutoj, kaj donu ilin al la Levidoj, kiuj plenumas la oficojn en la tabernaklo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Kaj faris Moseo kaj la pastro Eleazar, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Kaj la kvanto de la kaptitaĵo, krom la rabitaĵo, kiun rabis la militistoj, estis: da ŝafoj sescent sepdek kvin mil;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'kaj da bovoj sepdek du mil;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'kaj da azenoj sesdek unu mil;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'kaj da homoj, el virinoj, kiuj ne ekkonis kuŝejon de viro, la nombro de ĉiuj estis tridek du mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'La duono, la parto de tiuj, kiuj iris en la militon, estis: da ŝafoj tricent tridek sep mil kvincent;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'kaj la tributo por la Eternulo estis el la ŝafoj sescent sepdek kvin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'kaj da bovoj estis tridek ses mil, kaj el ili la tributo al la Eternulo sepdek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'kaj da azenoj estis tridek mil kvincent, kaj el ili la tributo al la Eternulo sesdek unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'kaj da homoj estis dek ses mil, kaj el ili la tributo por la Eternulo tridek du animoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Kaj Moseo donis la tributon, la oferdonon por la Eternulo, al la pastro Eleazar, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Kaj el la duono, apartenanta al la Izraelidoj, kiun apartigis Moseo de la viroj, kiuj militis');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, '(kaj la duono, apartenanta al la komunumo, estis: da ŝafoj tricent tridek sep mil kvincent,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'kaj da bovoj tridek ses mil,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'kaj da azenoj tridek mil kvincent,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'kaj da homoj dek ses mil) -');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'Kaj Moseo prenis el la duono, apartenanta al la Izraelidoj, unu prenitaĵon el kvindek, kiel el la homoj, tiel ankaŭ el la brutoj, kaj li donis ilin al la Levidoj, kiuj plenumas oficojn en la tabernaklo de la Eternulo, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Kaj aliris al Moseo la estroj de la miloj da militistoj, la milestroj kaj la centestroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'kaj ili diris al Moseo: Viaj servantoj kalkulis la militistojn, kiuj estis komisiitaj al ni, kaj mankas el ili neniu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'tial ni alportas oferon al la Eternulo, kion ĉiu el ni trovis, orajn vazojn, ĉenetojn, braceletojn, ringojn, orelornamojn, kaj kolringojn, por pekliberigi niajn animojn antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Kaj Moseo kaj la pastro Eleazar prenis de ili la oron en la formo de diversaj objektoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Kaj la kvanto de la tuta oro oferdona, kiun ili oferdonis al la Eternulo, estis dek ses mil sepcent kvindek sikloj de la milestroj kaj de la centestroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, '(Ĉar la militistoj rabis ĉiu por si.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Kaj Moseo kaj la pastro Eleazar prenis la oron de la milestroj kaj centestroj, kaj alportis ĝin en la tabernaklon de kunveno, kiel memorigaĵon de la Izraelidoj antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'La filoj de Ruben kaj la filoj de Gad havis tre multe da brutaroj; kaj ili vidis, ke la lando Jazer kaj la lando Gilead estas lokoj bonaj por brutaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Kaj venis la filoj de Gad kaj la filoj de Ruben, kaj diris al Moseo kaj al la pastro Eleazar kaj al la estroj de la komunumo jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Atarot kaj Dibon kaj Jazer kaj Nimra kaj Ĥeŝbon kaj Eleale kaj Sibma kaj Nebo kaj Beon-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'tiu lando, kiun la Eternulo venkobatis antaŭ la komunumo de Izrael- estas lando bona por brutaroj, kaj viaj servantoj havas brutarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Kaj ili diris: Se vi estas favoraj al ni, tiam tiu lando estu donata al viaj servantoj kiel posedaĵo; ne irigu nin trans Jordanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Kaj Moseo diris al la filoj de Gad kaj al la filoj de Ruben: Ĉu viaj fratoj iru en la militon kaj vi sidos ĉi tie?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Kaj kial vi deklinas la koron de la Izraelidoj de la transiro en la landon, kiun donas al ili la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Tiel agis viaj patroj, kiam mi sendis ilin el Kadeŝ-Barnea, por rigardi la landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Ili iris ĝis la valo Eŝkol kaj vidis la landon, kaj deklinis la koron de la Izraelidoj, ke ili ne iru en la landon, kiun donas al ili la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Kaj ekflamis en tiu tago la kolero de la Eternulo, kaj Li ĵuris, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Tiuj homoj, kiuj eliris el Egiptujo, en la aĝo de dudek jaroj kaj pli, ne vidos la landon, pri kiu Mi ĵuris al Abraham, al Isaak, kaj al Jakob; ĉar ili ne sekvis Min;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'krom Kaleb, filo de Jefune, la Kenizido, kaj Josuo, filo de Nun, ĉar ili sekvis Min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Kaj ekflamis la kolero de la Eternulo kontraŭ Izrael, kaj Li igis ilin vagadi en la dezerto dum kvardek jaroj, ĝis mortis la tuta generacio, kiu faris malbonon en la okuloj de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'Kaj jen vi leviĝis anstataŭ viaj patroj, nova generacio da pekuloj, por ankoraŭ plifortigi la flaman koleron de la Eternulo kontraŭ Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Se vi deturniĝos de Li, tiam Li denove restigos ilin en la dezerto; kaj vi pereigos tiun tutan popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Kaj ili aliris al li, kaj diris: Baraĵojn por ŝafoj ni konstruos ĉi tie por niaj brutaroj kaj urbojn por niaj infanoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'sed ni mem rapidos armitaj antaŭ la Izraelidoj, ĝis ni alkondukos ilin al iliaj lokoj; kaj niaj infanoj loĝos en la fortikigitaj urboj pro la loĝantoj de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Ni ne revenos al niaj domoj, ĝis la Izraelidoj ekposedos ĉiu sian posedaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Ni ne prenos kun ili posedaĵon transe de Jordan kaj plue; ĉar ni ricevos nian posedaĵon sur ĉi tiu orienta flanko de Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Kaj Moseo diris al ili: Se vi tion faros, se vi iros armitaj antaŭ la Eternulo en la militon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'kaj ĉiu el vi armita transiros Jordanon antaŭ la Eternulo, ĝis Li forpelos Siajn malamikojn antaŭ Si,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'kaj la lando estos militakirita antaŭ la Eternulo, tiam vi poste revenos, kaj vi estos senkulpaj antaŭ la Eternulo kaj antaŭ Izrael, kaj ĉi tiu lando estos via posedaĵo antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Sed se vi ne agos tiel, tiam vi pekos antaŭ la Eternulo, kaj vi suferos vian punon, kiu trafos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Konstruu al vi urbojn por viaj infanoj kaj baraĵojn por viaj ŝafoj; kaj faru tion, kio eliris el via buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Kaj la filoj de Gad kaj la filoj de Ruben diris al Moseo jene: Viaj servantoj faros, kiel nia sinjoro ordonas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Niaj infanoj, niaj edzinoj, niaj brutaroj, kaj ĉiuj niaj brutoj estos ĉi tie, en la urboj de Gilead;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'sed viaj servantoj, ĉiuj armitaj militiste, iros antaŭ la Eternulo en la militon, kiel nia sinjoro diras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Kaj Moseo ordonis pri ili al la pastro Eleazar, kaj al Josuo, filo de Nun, kaj al la estroj de la triboj de la Izraelidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'kaj Moseo diris al ili: Se la filoj de Gad kaj la filoj de Ruben transiros kun vi Jordanon, ĉiuj armitaj por la milito antaŭ la Eternulo, kaj la lando estos militakirita antaŭ vi, tiam donu al ili la landon Gilead kiel posedaĵon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'sed se ili ne transiros kun vi armitaj, tiam ili ricevos posedaĵon inter vi en la lando Kanaana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Kaj la filoj de Gad kaj la filoj de Ruben respondis, dirante: Kion la Eternulo diris al viaj servantoj, tion ni faros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Ni transiros armitaj antaŭ la Eternulo en la landon Kanaanan, kaj nia hereda posedaĵo estos sur ĉi tiu flanko de Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Kaj Moseo donis al ili, al la filoj de Gad kaj al la filoj de Ruben, kaj al duono de la tribo de Manase, filo de Jozef, la regnon de Siĥon, reĝo de la Amoridoj, kaj la regnon de Og, reĝo de Baŝan, la landon kun ĝiaj urboj laŭ la limoj de la urboj de la lando ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Kaj la filoj de Gad rekonstruis Dibonon kaj Ataroton kaj Aroeron');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'kaj Atrot-Ŝofanon kaj Jazeron kaj Jogbehan');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'kaj Bet-Nimran kaj Bet-Haranon, fortikigitajn urbojn, kaj baraĵojn por ŝafoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Kaj la filoj de Ruben rekonstruis Ĥeŝbonon kaj Elealen kaj Kirjataimon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'kaj Nebon kaj Baal-Meonon, kies nomojn oni ŝanĝis, kaj Sibman; kaj ili donis nomojn al la urboj, kiujn ili konstruis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Kaj la filoj de Maĥir, filo de Manase, iris Gileadon kaj militakiris ĝin, kaj forpelis la Amoridojn, kiuj estis tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Kaj Moseo donis Gileadon al Maĥir, filo de Manase, kaj tiu ekloĝis tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Kaj Jair, filo de Manase, iris kaj militakiris iliajn vilaĝojn, kaj li donis al ili la nomon Vilaĝoj de Jair.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Kaj Nobaĥ iris kaj militakiris Kenaton kaj ĝiajn vilaĝojn, kaj donis al ĝi la nomon Nobaĥ, laŭ sia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Jen estas la iroj de la Izraelidoj, per kiuj ili eliris el la lando Egipta, laŭ siaj taĉmentoj, sub la kondukado de Moseo kaj Aaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Kaj Moseo priskribis iliajn lokojn de eliro, laŭ ilia irado, konforme al la ordono de la Eternulo; kaj jen estas ilia irado laŭ iliaj lokoj de eliro:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'el Rameses ili eliris en la unua monato, en la dek-kvina tago de la unua monato; en la dua tago de Pasko la Izraelidoj eliris kun forta mano antaŭ la okuloj de la tuta Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'Dume la Egiptoj estis enterigantaj ĉiujn unuenaskitojn, kiujn la Eternulo mortigis inter ili; kaj super iliaj dioj la Eternulo faris juĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Kaj la Izraelidoj eliris el Rameses kaj haltis tendare en Sukot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Kaj ili eliris el Sukot, kaj haltis tendare en Etam, kiu estas ĉe la rando de la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Kaj ili eliris el Etam, kaj turnis sin al Pi-Haĥirot, kiu estas kontraŭ Baal-Cefon, kaj ili haltis tendare antaŭ Migdol.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Kaj ili eliris el Pi-Haĥirot kaj transiris meze de la maro en la dezerton, kaj ili iris tritagan vojon tra la dezerto Etam kaj haltis tendare en Mara.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Kaj ili eliris el Mara kaj venis Elimon; en Elim estis dek du fontoj de akvo kaj sepdek daktilaj palmoj, kaj ili haltis tie tendare.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Kaj ili eliris el Elim kaj haltis tendare ĉe la Ruĝa Maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Kaj ili foriris de la Ruĝa Maro kaj haltis tendare en la dezerto Sin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Kaj ili foriris el la dezerto Sin kaj haltis tendare en Dofka.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Kaj ili eliris el Dofka kaj haltis tendare en Aluŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Kaj ili eliris el Aluŝ kaj haltis tendare en Refidim, kaj tie ne estis akvo por la popolo por trinki.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Kaj ili eliris el Refidim kaj haltis en la dezerto Sinaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Kaj ili eliris el la dezerto Sinaj kaj haltis tendare en Kibrot- Hataava.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Kaj ili eliris el Kibrot-Hataava kaj haltis tendare en Ĥacerot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Kaj ili eliris el Ĥacerot kaj haltis tendare en Ritma.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Kaj ili eliris el Ritma kaj haltis tendare en Rimon-Perec.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Kaj ili eliris el Rimon-Perec kaj haltis tendare en Libna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Kaj ili eliris el Libna kaj haltis tendare en Risa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Kaj ili eliris el Risa kaj haltis tendare en Kehelata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Kaj ili eliris el Kehelata kaj haltis tendare ĉe la monto Ŝefer.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Kaj ili foriris de la monto Ŝefer kaj haltis tendare en Ĥarada.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Kaj ili eliris el Ĥarada kaj haltis tendare en Makhelot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Kaj ili eliris el Makhelot kaj haltis tendare en Taĥat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Kaj ili eliris el Taĥat kaj haltis tendare en Teraĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Kaj ili eliris el Teraĥ kaj haltis tendare en Mitka.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'Kaj ili eliris el Mitka kaj haltis tendare en Ĥaŝmona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Kaj ili eliris el Ĥaŝmona kaj haltis tendare en Moserot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Kaj ili eliris el Moserot kaj haltis tendare en Bene-Jaakan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Kaj ili eliris el Bene-Jaakan kaj haltis tendare en Ĥor-Hagidgad.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Kaj ili eliris el Ĥor-Hagidgad kaj haltis tendare en Jotbata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Kaj ili eliris el Jotbata kaj haltis tendare en Abrona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Kaj ili eliris el Abrona kaj haltis tendare en Ecjon-Geber.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Kaj ili eliris el Ecjon-Geber kaj haltis tendare en la dezerto Cin (tio estas Kadeŝ).');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Kaj ili eliris el Kadeŝ, kaj haltis tendare ĉe la monto Hor, ĉe la rando de la lando de Edom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Kaj la pastro Aaron supreniris sur la monton Hor laŭ la ordono de la Eternulo, kaj mortis tie en la jaro kvardeka post la eliro de la Izraelidoj el la lando Egipta, en la kvina monato, en la unua tago de la monato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Kaj Aaron havis la aĝon de cent dudek tri jaroj, kiam li mortis sur la monto Hor.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Kaj la Kanaanido, la reĝo de Arad, kiu loĝis en la sudo de la lando Kanaana, aŭdis, ke venas la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Kaj ili foriris de la monto Hor kaj haltis tendare en Calmona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Kaj ili eliris el Calmona kaj haltis tendare en Punon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Kaj ili eliris el Punon kaj haltis tendare en Obot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Kaj ili eliris el Obot, kaj haltis tendare en Ije-Abarim, ĉe la limo de Moab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Kaj ili eliris el Ije-Abarim kaj haltis tendare en Dibon-Gad.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Kaj ili eliris el Dibon-Gad kaj haltis tendare en Almon-Diblataim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Kaj ili eliris el Almon-Diblataim, kaj haltis tendare ĉe la montoj Abarim, antaŭ Nebo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Kaj ili foriris de la montoj Abarim, kaj haltis tendare en la stepoj de Moab, ĉe la Jeriĥa Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'Kaj ili aranĝis sian tendaron ĉe Jordan, de Bet-Jeŝimot ĝis Abel- Ŝitim, en la stepoj de Moab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Kaj la Eternulo ekparolis al Moseo en la stepoj de Moab ĉe la Jeriĥa Jordan, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Parolu al la Izraelidoj, kaj diru al ili: Kiam vi transiros Jordanon en la landon Kanaanan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'tiam forpelu de antaŭ vi ĉiujn loĝantojn de la lando, kaj detruu ĉiujn iliajn figurojn, kaj ĉiujn iliajn fanditajn bildojn detruu, kaj ĉiujn iliajn altaĵojn ekstermu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'kaj ekposedu la landon kaj ekloĝu en ĝi, ĉar al vi Mi donas la landon, ke vi posedu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Kaj dispartigu al vi la landon per loto konforme al viaj familioj; al la plinombra donu pli grandan posedaĵon, kaj al la malplinombra donu malpli grandan posedaĵon; kie al iu trafos la loto, tie estu lia posedaĵo; laŭ la triboj de viaj patroj prenu al vi posedaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Sed se vi ne forpelos de antaŭ vi la loĝantojn de la lando, tiam tiuj, kiujn vi restigos el ili, estos dornoj por viaj okuloj kaj pikiloj por viaj flankoj, kaj ili premos vin en la lando, en kiu vi loĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Kaj tiam tion, kion Mi intencis fari al ili, Mi faros al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Ordonu al la Izraelidoj, kaj diru al ili: Kiam vi venos en la landon Kanaanan, tiu lando fariĝu via posedaĵo, la lando Kanaana laŭ siaj limoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'La rando suda estu por vi de la dezerto Cin, apud Edom, kaj la suda limo estu por vi de la fino de la Sala Maro oriente;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'kaj la suda limo turniĝos ĉe vi al la altaĵo Akrabim kaj iros tra Cin, kaj ĝiaj elstaraĵoj iros suden ĝis Kadeŝ-Barnea kaj atingos ĝis Ĥacar-Adar kaj pasos tra Acmon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'kaj de Acmon la limo turniĝos al la Egipta torento, kaj ĝiaj elstaraĵoj estos ĝis la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Kaj por okcidenta limo estu por vi la Granda Maro kiel limo; tio estos por vi la limo okcidenta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'Kaj tia estu por vi la limo norda: de la Granda Maro vi tiros ĝin al vi ĝis la monto Hor;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'de la monto Hor tiru ĝin ĝis Ĥamat, kaj la elstaraĵoj de la limo iros al Cedad;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'kaj la limo iros ĝis Zifron, kaj ĝiaj elstaraĵoj iros ĝis Ĥacar- Enan; tio estu por vi la limo norda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Kaj la limon orientan vi tiros al vi de Ĥacar-Enan ĝis Ŝefam;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'de Ŝefam la limo iros ĝis Ribla, orienten de Ain; poste la limo iros malsupren kaj tuŝos la bordon de la maro Kineret oriente;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'kaj pluen la limo iros ĝis Jordan, kaj ĝiaj elstaraĵoj estos ĝis la Sala Maro. Tia estos via lando laŭ ĝiaj limoj ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Kaj Moseo ordonis al la Izraelidoj, dirante: Tio estas la lando, kiun vi dividos inter vi per loto kaj kiun la Eternulo ordonis doni al naŭ triboj kaj al duontribo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'ĉar la tribo de la Rubenidoj laŭ iliaj patrodomoj, kaj la tribo de la Gadidoj laŭ iliaj patrodomoj, kaj duono de la tribo de la Manaseidoj prenis sian parton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'la du triboj kaj la duontribo prenis sian parton transe de la Jeriĥa Jordan, oriente, sur la flanko de sunleviĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Jen estas la nomoj de la viroj, kiuj disdividos inter vi la landon: Eleazar, la pastro, kaj Josuo, filo de Nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'Kaj po unu estro el ĉiu tribo prenu por la dividado de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Kaj jen estas la nomoj de la viroj: por la tribo de Jehuda, Kaleb, file de Jefune;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'kaj por la tribo de la Simeonidoj, Ŝemuel, filo de Amihud;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'por la tribo de Benjamen, Elidad, filo de Kislon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'kaj por la tribo de la Danidoj, la estro Buki, filo de Jogli;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'por la filoj de Jozef: por la tribo de la Manaseidoj, la estro Ĥaniel, filo de Efod,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'kaj por la tribo de la Efraimidoj, la estro Kemuel, filo de Ŝiftan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'kaj por la tribo de la Zebulunidoj, la estro Elicafan, filo de Parnaĥ;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'kaj por la tribo de la Isaĥaridoj, la estro Paltiel, filo de Azan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'kaj por la tribo de la Aŝeridoj, la estro Aĥihud, filo de Ŝelomi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'kaj por la tribo de la Naftaliidoj, la estro Pedahel, filo de Amihud.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Tio estas tiuj, al kiuj la Eternulo ordonis, ke ili disdonu la posedaĵojn al la Izraelidoj en la lando Kanaana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Kaj la Eternulo ekparolis al Moseo en la stepoj de Moab ĉe la Jeriĥa Jordan, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Ordonu al la Izraelidoj, ke ili donu al la Levidoj el siaj posedaĵoj urbojn por loĝi; ankaŭ la kampojn ĉirkaŭ tiuj urboj donu al la Levidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Kaj la urboj estos por ili por loĝi, kaj la kampoj estos por iliaj brutoj kaj por ilia havo kaj por ĉiuj iliaj bezonoj de la vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Kaj la kampoj de tiuj urboj, kiujn vi donos al la Levidoj, devas etendiĝi mil ulnojn ekster la muroj de la urboj ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Kaj mezuru ekster la urbo sur la orienta flanko du mil ulnojn kaj sur la suda flanko du mil ulnojn kaj sur la okcidenta flanko du mil ulnojn kaj sur la norda flanko du mil ulnojn, kaj la urbo estos en la mezo; tiaj estu por ili la kampoj de la urboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Kaj el la urboj, kiujn vi donos al la Levidoj, estos ses urboj de rifuĝo, en kiujn vi al mortiginto permesos forkuri; kaj krom tiuj donu kvardek du urbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'La nombro de ĉiuj urboj, kiujn vi devas doni al la Levidoj, estas kvardek ok urboj kune kun iliaj kampoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'La urbojn, kiujn vi donos el la posedaĵoj de la Izraelidoj, de la plimultaj prenu pli multe kaj de la malplimultaj prenu malpli multe; ĉiu konforme al sia posedaĵo, kiun li ricevos, devas doni el siaj urboj al la Levidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Kaj la Eternulo ekparolis al Moseo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Parolu al la Izraelidoj, kaj diru al ili: Kiam vi transiros Jordanon en la landon Kanaanan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'tiam elektu al vi urbojn, kiuj estu ĉe vi urboj de rifuĝo, kien povas forkuri mortiginto, kiu mortigis homon senintence.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Kaj tiuj urboj estos ĉe vi rifuĝejo kontraŭ venĝanto, por ke ne mortu la mortiginto, antaŭ ol li staros antaŭ la komunumo por juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Kaj el la urboj, kiujn vi donos, ses urboj de rifuĝo estu ĉe vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Tri urbojn donu transe de Jordan kaj tri urbojn donu en la lando Kanaana; urboj de rifuĝo ili estu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Por la Izraelidoj kaj por la fremdulo kaj por la pasloĝanto inter ili estu tiuj ses urboj por rifuĝo, por ke forkuru tien ĉiu, kiu mortigis homon senintence.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Sed se per fera objekto li batis lin kaj ĉi tiu mortis, tiam li estas mortiginto; la mortiginton oni devas mortigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Kaj se li batis lin per mana ŝtono, de kiu oni povas morti, kaj ĉi tiu mortis, tiam li estas mortiginto; la mortiginton oni devas mortigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Aŭ se li batis lin per mana objekto ligna, de kiu oni povas morti, kaj ĉi tiu mortis, tiam li estas mortiginto; la mortiginton oni devas mortigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'La venĝanto de la sango mem povas mortigi la mortiginton; kiam li renkontos lin, li povas mortigi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Se iu puŝis iun pro malamo aŭ sin kaŝinte ĵetis ion sur lin kaj ĉi tiu mortis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'aŭ se li malamike per sia mano batis lin kaj ĉi tiu mortis, tiam oni devas mortigi la batinton: li estas mortiginto; la venĝanto de la sango povas mortigi la mortiginton, kiam li renkontos lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Sed se per hazardo kaj ne pro malamikeco li puŝis lin, aŭ se li ĵetis sur lin ian objekton sen malbonintenco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'aŭ se ŝtonon, de kiu oni povas morti, li ĵetis sur lin ne vidante, kaj ĉi tiu mortis, sed li ne estis lia malamiko kaj ne deziris al li malbonon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'tiam la komunumo devas juĝi inter la batinto kaj la venĝanto de la sango laŭ ĉi tiuj leĝoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'kaj la komunumo devas savi la mortiginton el la mano de la venĝanto de la sango, kaj la komunumo revenigos lin en lian urbon de rifuĝo, kien li forkuris; kaj li devas loĝi tie ĝis la morto de la granda pastro, kiu estas oleita per sankta oleo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Sed se la mortiginto eliris el la limoj de sia urbo de rifuĝo, kien li forkuris,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'kaj la venĝanto de la sango trovis lin ekster la limoj de lia urbo de rifuĝo kaj la venĝanto de la sango mortigis la mortiginton, tiam li ne estas kulpa pri la sango;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'ĉar en sia urbo de rifuĝo li devas resti ĝis la morto de la granda pastro, kaj post la morto de la granda pastro la mortiginto povas reveni sur la teron de sia posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Kaj tio estu por vi leĝa regulo en viaj generacioj, en ĉiuj viaj lokoj de loĝado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Ĉiun, kiu mortigis homon, tiun mortiginton oni devas mortigi, se raportis pri li atestantoj; sed unu atestanto ne sufiĉas, por kondamni homon al morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Ne prenu elaĉeton pro animo de mortiginto, kiu estas malbonagulo mortiginda; oni devas lin mortigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Kaj ne prenu elaĉeton pro homo, kiu forkuris en urbon de rifuĝo, ke li povu reveni kaj loĝi sur sia tero antaŭ la morto de la pastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Kaj ne malhonoru la teron, sur kiu vi estos, ĉar sango malhonoras la teron, kaj nur per la sango de tiu, kiu verŝis sangon, la tero povas puriĝi de la sango, kiu estas verŝita sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Kaj ne malpurigu la landon, en kiu vi loĝas kaj en kies mezo Mi restas; ĉar Mi, la Eternulo, restas inter la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Kaj aliris la familiestroj de la familio de Gilead, filo de Maĥir, filo de Manase, el la familioj de la Jozefidoj, kaj ekparolis antaŭ Moseo kaj antaŭ la eminentuloj, la familiestroj de la Izraelidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'kaj ili diris: Al nia sinjoro la Eternulo ordonis disdoni la teron kiel posedaĵon per loto al la Izraelidoj, kaj al nia sinjoro la Eternulo ordonis doni la parton de nia frato Celofĥad al liaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Sed se ili fariĝos edzinoj de iu el la filoj de alia tribo de la Izraelidoj, tiam ilia posedaĵo estos forprenita el la posedaĵo de niaj patroj, kaj aliĝos al la posedaĵo de tiu tribo, al kiu ili ekapartenos, kaj el nia lote ricevita posedaĵo ĝi estos forprenita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'Kaj kiam eĉ estos jubilea jaro ĉe la Izraelidoj, ilia posedaĵo restos aligita al la posedaĵo de tiu tribo, al kiu ili apartenos; kaj el la posedaĵo de la tribo de niaj patroj ilia posedaĵo restos forprenita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Tiam Moseo donis ordonon al la Izraelidoj laŭ la instrukcio de la Eternulo, dirante: Prave parolas la tribo de la Jozefidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Jen kion ordonis la Eternulo koncerne la filinojn de Celofĥad: Ili povas fariĝi edzinoj de tiuj, kiuj plaĉos al ili, sed nur en familio el la tribo de siaj patroj ili edziniĝu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'por ke ne transiru hereda posedaĵo de la Izraelidoj el unu tribo en alian tribon, ĉar ĉiu el la Izraelidoj devas resti fortike ĉe la posedaĵo de la tribo de liaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Kaj ĉiu filino, kiu heredas posedaĵon en la triboj de la Izraelidoj, devas edziniĝi kun iu el la familioj de la tribo de ŝia patro, por ke la Izraelidoj heredu ĉiu la posedaĵon de siaj patroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'kaj por ke posedaĵo ne transiru el unu tribo en alian tribon, sed ĉiu tribo de la Izraelidoj restu fortike ĉe sia posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Kiel la Eternulo ordonis al Moseo, tiel faris la filinoj de Celofĥad;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'kaj Maĥla, Tirca kaj Ĥogla kaj Milka kaj Noa, la filinoj de Celofĥad, edziniĝis kun filoj de siaj onkloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'En la familioj de la filoj de Manase, filo de Jozef, ili edziniĝis, kaj ilia posedaĵo restis en la tribo de la familio de ilia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Tio estas la ordonoj kaj la leĝoj, kiujn la Eternulo donis per Moseo al la Izraelidoj en la stepoj de Moab, ĉe la Jeriĥa Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Jen estas la vortoj, kiujn diris Moseo al la tuta Izrael transe de Jordan, en la dezerto, en la stepo antaŭ Suf, inter Paran kaj Tofel kaj Laban kaj Ĥacerot kaj Di-Zahab,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'dek unu tagojn malproksime de Ĥoreb, sur la vojo de la monto Seir al Kadeŝ-Barnea.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Tio estis en la kvardeka jaro, en la dek-unua monato, en la unua tago de la monato, Moseo parolis al la Izraelidoj konforme al ĉio, kion la Eternulo ordonis al li por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'Post kiam li venkobatis Siĥonon, la reĝon de la Amoridoj, kiu loĝis en Ĥeŝbon, kaj Ogon, la reĝon de Baŝan, kiu loĝis en Aŝtarot kaj en Edrei;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'transe de Jordan, en la lando de Moab, Moseo komencis klarigi ĉi tiun instruon, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'La Eternulo, nia Dio, diris al ni sur Ĥoreb jene: Sufiĉe vi loĝis sur ĉi tiu monto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'turniĝu kaj elmoviĝu, kaj iru sur la monton de la Amoridoj kaj al ĉiuj iliaj najbaroj en la stepo, sur la monto kaj en la valo kaj en la sudo kaj sur la bordo de la maro, en la landon de la Kanaanidoj kaj sur Lebanonon, ĝis la granda rivero, la rivero Eŭfrato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Vidu, Mi donas al vi la landon; iru kaj ekposedu la landon, pri kiu la Eternulo ĵuris al viaj patroj, al Abraham, al Isaak, kaj al Jakob, ke Li donos ĝin al ili kaj al ilia idaro post ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'Kaj mi diris al vi en tiu tempo jene: Mi ne povas sola porti vin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'la Eternulo, via Dio, multigis vin, kaj jen vi estas nun multego, kiel la steloj de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'La Eternulo, la Dio de viaj patroj, multigu vin miloble kontraŭ via nuna nombro, kaj Li benu vin, kiel Li diris al vi!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Kiel mi povus sola porti la penadon por vi kaj vian ŝarĝon kaj viajn disputojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Elektu al vi el viaj triboj virojn saĝajn kaj kompetentajn kaj konatajn, kaj mi starigos ilin, kiel viajn estrojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Kaj vi respondis al mi kaj diris: Bona estas la afero, kiun vi proponis fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Tiam mi prenis la ĉefojn de viaj triboj, virojn saĝajn kaj konatajn, kaj mi faris ilin estroj super vi, milestroj kaj centestroj kaj kvindekestroj kaj dekestroj kaj kontrolistoj en viaj triboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'Kaj mi ordonis al viaj juĝistoj en tiu tempo, dirante: Aŭskultu viajn fratojn kaj juĝu juste inter homo kaj lia frato kaj fremdulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Ne distingu vizaĝojn ĉe la juĝo; malgrandan kaj grandan egale aŭskultu; timu neniun, ĉar la juĝo estas afero de Dio; kaj aferon, kiu estos malfacila por vi, venigu al mi, kaj mi ĝin aŭskultos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Kaj mi donis al vi ordonon en tiu tempo pri ĉio, kion vi devas fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Kaj ni foriris de Ĥoreb, kaj trairis tiun tutan grandan kaj teruran dezerton, kiun vi vidis, sur la vojo al la monto de la Amoridoj, kiel ordonis al ni la Eternulo, nia Dio; kaj ni venis al Kadeŝ-Barnea.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Kaj mi diris al vi: Vi venis al la monto de la Amoridoj, kiun la Eternulo, nia Dio, donas al ni;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'vidu, la Eternulo, via Dio, donas al vi la landon; iru, ekposedu ĝin, kiel diris al vi la Eternulo, la Dio de viaj patroj; ne timu kaj ne tremu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Sed vi ĉiuj aliris al mi, kaj diris: Ni sendu antaŭ ni virojn, ke ili esploru por ni la landon, kaj alportu al ni sciigon pri la vojo, per kiu ni devas iri, kaj pri la urboj, al kiuj ni devas veni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Kaj tio plaĉis al mi, kaj mi prenis el vi dek du virojn, po unu viro el tribo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'kaj ili iris kaj supreniris sur la monton, kaj venis al la valo Eŝkol kaj esplorrigardis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'Kaj ili prenis en siajn manojn iom el la fruktoj de la lando kaj liveris al ni, kaj alportis al ni sciigon, kaj diris: Bona estas la lando, kiun la Eternulo, nia Dio, donas al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Sed vi ne volis iri, kaj vi malobeis la vortojn de la Eternulo, via Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'kaj vi murmuris en viaj tendoj, kaj diris: Pro la malamo de la Eternulo kontraŭ ni, Li elkondukis nin el la lando Egipta, por transdoni nin en la manon de la Amoridoj, por ke ili ekstermu nin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'kien ni iru? Niaj fratoj ektimigis nian koron, dirante: La popolo estas pli granda kaj pli altkreska ol ni, la urboj estas grandaj kaj fortikigitaj ĝis la ĉielo, kaj ankaŭ Anakidojn ni tie vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Kaj mi diris al vi: Ne tremu kaj ne timu ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'la Eternulo via Dio, kiu iras antaŭ vi, Li batalos por vi, simile al ĉio, kion Li faris por vi en Egiptujo antaŭ viaj okuloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'kaj en la dezerto, kie, kiel vi vidis, la Eternulo, via Dio, portis vin, kiel homo portas sian filon, sur la tuta vojo, kiun vi iris, ĝis vi venis al ĉi tiu loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Sed eĉ ĉe tio vi ne fidas la Eternulon, vian Dion,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'kiu iras antaŭ vi sur la vojo, por serĉi por vi lokon, kie vi povus halti tendare, nokte en fajro, por montri al vi la vojon, kiun vi devas iri, kaj tage en nubo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Kaj la Eternulo aŭdis viajn vortojn, kaj Li ekkoleris kaj ĵuris, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Neniu el ĉi tiuj homoj, el ĉi tiu malbona generacio, vidos la bonan landon, kiun Mi ĵuris doni al viaj patroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'nur Kaleb, filo de Jefune, vidos ĝin; kaj pro tio, ke li sekvis la Eternulon, Mi donos al li kaj al liaj filoj la landon, kiun li trairis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Ankaŭ kontraŭ mi la Eternulo ekkoleris pro vi, dirante: Vi ankaŭ ne venos tien;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Josuo, filo de Nun, kiu staras antaŭ vi, li venos tien; lin fortigu, ĉar li donos ĝin al Izrael kiel posedaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Kaj viaj infanoj, pri kiuj vi diris, ke ili fariĝos militakiraĵo, kaj viaj filoj, kiuj nun ankoraŭ ne scias bonon nek malbonon, ili venos tien, kaj al ili Mi donos ĝin, kaj ili ekposedos ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Sed vi turniĝu, kaj iru en la dezerton en la direkto al la Ruĝa Maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Kaj vi respondis kaj diris al mi: Ni pekis antaŭ la Eternulo; ni iros kaj batalos, konforme al ĉio, kion ordonis al ni la Eternulo, nia Dio; kaj ĉiu el vi zonis sin per siaj bataliloj, kaj vi pretigis vin, por iri sur la monton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Sed la Eternulo diris al mi: Diru al ili: Ne iru kaj ne batalu, ĉar Mi ne estas inter vi; por ke vi ne estu frapitaj de viaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Kaj mi diris al vi, sed vi ne aŭskultis; kaj vi malobeis la vortojn de la Eternulo, kaj vi estis malhumilaj kaj iris sur la monton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Tiam eliris kontraŭ vin la Amoridoj, kiuj loĝis sur tiu monto, kaj ili pelis vin tiel, kiel faras la abeloj, kaj batis vin sur Seir ĝis Ĥorma.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Kaj vi revenis kaj ploris antaŭ la Eternulo; sed la Eternulo ne aŭskultis vian voĉon kaj ne atentis vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Kaj vi loĝis en Kadeŝ longan tempon, la tempon, dum kiu vi loĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Kaj ni turnis nin kaj elmoviĝis en la dezerton en la direkto al la Ruĝa Maro, kiel la Eternulo diris al mi; kaj ni ĉirkaŭiris la monton Seir dum longa tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Kaj la Eternulo diris al mi jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'Sufiĉe vi ĉirkaŭiris ĉi tiun monton; turnu vin norden;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'kaj al la popolo donu tian ordonon: Vi preteriros la limon de viaj fratoj la Esavidoj, kiuj loĝas sur Seir, kaj ili timos vin; sed gardu vin forte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'Ne komencu batalon kontraŭ ili, ĉar Mi ne donos al vi el ilia lando eĉ larĝecon de plando; ĉar al Esav Mi donis, kiel heredaĵon, la monton Seir.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Manĝaĵon aĉetu de ili pro mono kaj manĝu; kaj eĉ akvon aĉetu de ili pro mono kaj trinku;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'ĉar la Eternulo, via Dio, benis vin en ĉiu faro de viaj manoj; Li gvidis vian iradon tra ĉi tiu granda dezerto; jen jam kvardek jarojn la Eternulo estas kun vi, kaj nenio mankis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Kaj ni preteriris flanke de niaj fratoj la Esavidoj, kiuj loĝas sur Seir, flanke de la vojo stepa, de Elat kaj de Ecjon-Geber. Kaj ni turnis nin kaj iris laŭ la vojo al la dezerto de Moab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Kaj la Eternulo diris al mi: Ne faru malamikaĵon al Moab kaj ne komencu militon kontraŭ ili, ĉar Mi ne donos al vi heredaĵon el ilia lando; ĉar al la filoj de Lot Mi donis Aron kiel heredan posedaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, '(La Emidoj antaŭe loĝis tie, popolo granda kaj grandnombra, kaj altkreska kiel la Anakidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Ankaŭ ilin oni kalkulis inter la Rafaidoj, kiel la Anakidojn; kaj la Moabidoj nomas ilin Emidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Kaj sur Seir loĝis antaŭe la Ĥoridoj; sed la Esavidoj forpelis ilin kaj ekstermis ilin de antaŭ si kaj ekloĝis sur ilia loko, kiel agis Izrael kun la lando de sia posedaĵo, kiun la Eternulo donis al ili.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'Nun leviĝu kaj transiru la valon Zared. Kaj ni transiris la valon Zared.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Kaj la tempo, dum kiu ni iris de Kadeŝ-Barnea, ĝis ni transiris la valon Zared, estis tridek ok jaroj, ĝis formortis el la tendaro la tuta generacio de militistoj, kiel ĵuris al ili la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Kaj ankaŭ la mano de la Eternulo estis sur ili, por ekstermi ilin el inter la tendaro, ĝis ili ĉiuj formortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Kaj kiam formortis ĉiuj militistoj el inter la popolo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'tiam la Eternulo ekparolis al mi, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'Vi iras nun preter la limo de Moab, preter Ar,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'kaj vi alproksimiĝas al la Amonidoj; ne faru al ili malamikaĵon kaj ne batalu kontraŭ ili, ĉar Mi ne donos al vi heredaĵon el la lando de la Amonidoj; ĉar al la filoj de Lot Mi donis ĝin kiel heredan posedaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, '(Kiel landon de Rafaidoj oni rigardas ankaŭ ĝin; Rafaidoj loĝis en ĝi antaŭe; kaj la Amonidoj nomas ilin Zamzumoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'tio estis popolo granda kaj grandnombra, kaj altkreska kiel la Anakidoj; sed la Eternulo ekstermis ilin antaŭ ili, kaj ili forpelis ilin kaj ekloĝis sur ilia loko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'kiel Li faris por la Esavidoj, kiuj loĝas sur Seir, antaŭ kiuj Li ekstermis la Ĥoridojn, kaj ili forpelis ilin kaj loĝis sur ilia loko ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Kaj la Avidojn, kiuj loĝis en vilaĝoj ĝis Gaza, ekstermis la Kaftoridoj, kiuj eliris el Kaftor, kaj ili ekloĝis sur ilia loko.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Leviĝu, elmoviĝu kaj transiru la torenton Arnon; rigardu, Mi transdonas en vian manon Siĥonon, la reĝon de Ĥeŝbon, la Amoridon, kaj lian landon; komencu ekposedi kaj militu kontraŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'De la nuna tago Mi komencos ĵetadi teruron kaj timon antaŭ vi sur la popolojn sub la tuta ĉielo; tiuj, kiuj aŭdos la famon pri vi, ektremos kaj ektimos antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Kaj mi sendis senditojn el la dezerto Kedemot al Siĥon, la reĝo de Ĥeŝbon, kun vortoj de paco, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Mi dezirus iri tra via lando; mi iros nur laŭ la vojo, mi ne forflankiĝos dekstren nek maldekstren;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'manĝaĵon vendu al mi pro mono, kaj mi manĝos, kaj akvon donu al mi pro mono, kaj mi trinkos: nur per miaj piedoj mi trairos-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'kiel faris al mi la Esavidoj, kiuj loĝas sur Seir, kaj la Moabidoj, kiuj loĝas en Ar-ĝis mi transiros Jordanon en la landon, kiun la Eternulo, nia Dio, donas al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Sed ne volis Siĥon, la reĝo de Ĥeŝbon, tralasi nin, ĉar la Eternulo, via Dio, obstinigis lian spiriton kaj malcedemigis lian koron, por transdoni lin en vian manon, kiel nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Kaj la Eternulo diris al mi: Rigardu, Mi komencas transdoni al vi Siĥonon kaj lian landon; komencu posedpreni lian landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Kaj Siĥon eliris kontraŭ nin, li kaj lia tuta popolo, por batalo apud Jahac.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Kaj transdonis lin la Eternulo, nia Dio, al ni, kaj ni venkobatis lin kaj liajn filojn kaj lian tutan popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Kaj ni militakiris en tiu tempo ĉiujn liajn urbojn, kaj ni ekstermis en ĉiu urbo la virojn kaj la virinojn kaj la infanojn, ni restigis neniun;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'nur la brutojn ni prenis al ni, kiel militakiraĵon, kaj la rabaĵon el la urboj, kiujn ni militakiris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'De Aroer, kiu estas sur la bordo de la torento Arnon, kaj la urbo, kiu estas en la valo, ĝis Gilead ne estis urbo, kiu povus kontraŭstari al ni: ĉion transdonis al ni la Eternulo, nia Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'nur al la lando de la Amonidoj vi ne alproksimiĝis, al la tuta bordo de la torento Jabok, kaj al la urboj de la monto, kaj al ĉio, pri kio malpermesis la Eternulo, nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Kaj ni turnis nin kaj ekiris laŭ la vojo al Baŝan. Kaj eliris kontraŭ nin Og, la reĝo de Baŝan, li kaj lia tuta popolo, por batalo apud Edrei.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Kaj la Eternulo diris al mi: Ne timu lin; ĉar en vian manon Mi transdonis lin kaj lian tutan popolon kaj lian landon, kaj vi faros al li, kiel vi faris al Siĥon, la reĝo de la Amoridoj, kiu loĝis en Ĥeŝbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Kaj la Eternulo, nia Dio, transdonis en nian manon ankaŭ Ogon, la reĝon de Baŝan, kaj lian tutan popolon; kaj ni batis lin tiel, ke neniu restis ĉe li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Kaj ni militakiris tiam ĉiujn liajn urbojn; ne estis urbo, kiun ni ne prenis de ili: sesdek urbojn, la tutan distrikton de Argob, la regnon de Og la Baŝana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Ĉiuj tiuj urboj estis fortikigitaj per alta muro, per pordegoj kaj rigliloj, krom la tre multaj urboj ne fortikigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Kaj ni ekstermis ilin, kiel ni faris al Siĥon, la reĝo de Ĥeŝbon, ni ekstermis en ĉiu urbo la virojn, la virinojn, kaj la infanojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'sed ĉiujn brutojn kaj la rabaĵon el la urboj ni prenis al ni, kiel militakiraĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Kaj ni prenis tiam el la manoj de la du reĝoj de la Amoridoj la landon, kiu estas transe de Jordan, de la torento Arnon ĝis la monto Ĥermon');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '(la Cidonanoj nomas Ĥermonon Sirjon, kaj la Amoridoj nomas ĝin Senir),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'ĉiujn urbojn sur la ebenaĵo, kaj la tutan Gileadon kaj la tutan Baŝanon ĝis Salĥa kaj Edrei, urboj de la regno de Og la Baŝana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, '(Ĉar nur Og, la reĝo de Baŝan, estis restinta el la resto de la Rafaidoj. Jen estas lia lito, fera lito, jen ĝi estas en Raba de la Amonidoj: naŭ ulnoj estas ĝia longeco kaj kvar ulnoj estas ĝia larĝeco, laŭ la ulnoj de viro.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Kaj tiun landon ni ekposedis en tiu tempo: de Aroer, kiu estas apud la torento Arnon, kaj duonon de la monto Gilead kun ĝiaj urboj mi donis al la Rubenidoj kaj al la Gadidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'kaj la ceteran parton de Gilead kaj la tutan Baŝanon, la regnon de Og, mi donis al duono de la tribo de Manase, la tutan distrikton de Argob. (La tutan tiun Baŝanon oni nomas lando de Rafaidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jair, filo de Manase, prenis la tutan distrikton de Argob ĝis la limo de la Geŝuridoj kaj Maaĥatidoj, kaj li donis al Baŝan laŭ sia nomo la nomon Vilaĝoj de Jair, tiel estas ĝis nun.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Kaj al Maĥir mi donis Gileadon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'Kaj al la Rubenidoj kaj al la Gadidoj mi donis de Gilead ĝis la torento Arnon, kun la mezo de la valo por limo; ankaŭ ĝis la torento Jabok, limo de la Amonidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'kaj la stepon, kun Jordan por limo, de Kineret ĝis la maro de la ebenaĵo, la Sala Maro, ĉe la bazo de Pisga en la oriento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'Kaj mi faris al vi ordonon en tiu tempo, dirante: La Eternulo, via Dio, donis al vi ĉi tiun landon, por ke vi posedu ĝin; armitaj iru antaŭ viaj fratoj la Izraelidoj, ĉiuj militkapablaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Nur viaj edzinoj kaj viaj infanoj kaj viaj brutaroj-mi scias, ke vi havas grandnombrajn brutarojn-restu en viaj urboj, kiujn mi donis al vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'ĝis la Eternulo donos ripozon al viaj fratoj, kiel al vi, kaj ili ankaŭ ekposedos la landon, kiun la Eternulo, via Dio, donas al ili transe de Jordan; tiam vi reiros ĉiu al sia posedaĵo, kiun mi donis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Kaj al Josuo mi ordonis en tiu tempo, dirante: Viaj okuloj vidis ĉion, kion la Eternulo, via Dio, faris al tiuj du reĝoj; tiel la Eternulo faros al ĉiuj regnoj, kiujn vi trairos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Ne timu ilin; ĉar la Eternulo, via Dio, batalas por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Kaj mi preĝis al la Eternulo en tiu tempo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Mia Sinjoro, ho Eternulo! Vi komencis montradi al Via servanto Vian grandecon kaj Vian fortan manon; ĉar kie estas dio en la ĉielo aŭ sur la tero, kiu povus fari simile al Viaj faroj kaj al Via potenco?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Mi dezirus transiri kaj vidi tiun bonan landon, kiu estas transe de Jordan, tiun belan monton kaj Lebanonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Sed la Eternulo ekkoleris kontraŭ mi pro vi kaj ne aŭskultis min; kaj la Eternulo diris al mi: Sufiĉe, ne parolu al Mi plu pri tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Supreniru sur la supron de Pisga, kaj direktu viajn okulojn al okcidento kaj al nordo kaj al sudo kaj al oriento kaj rigardu per viaj okuloj; ĉar vi ne transiros ĉi tiun Jordanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Kaj donu instrukciojn al Josuo kaj fortigu kaj kuraĝigu lin, ĉar li transiros antaŭ ĉi tiu popolo, kaj li posedigos al ili la landon, kiun vi vidos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Kaj ni restis en la valo, kontraŭ Bet-Peor.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Kaj nun, ho Izrael, aŭskultu la leĝojn kaj la regulojn, kiujn mi instruas al vi, ke vi ilin plenumu, por ke vi vivu kaj venu kaj heredu la landon, kiun la Eternulo, la Dio de viaj patroj, donas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Ne aldonu al tio, kion mi ordonas al vi, kaj ne deprenu de ĝi; sed observu la ordonojn de la Eternulo, via Dio, kiujn mi ordonas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Viaj okuloj vidis, kion la Eternulo faris pro Baal-Peor; ĉar ĉiun homon, kiu sekvis Baal-Peoron, la Eternulo, via Dio, ekstermis el inter vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'sed vi, kiuj restis aliĝintaj al la Eternulo, via Dio, vi ĉiuj vivas hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Rigardu, mi instruis al vi leĝojn kaj regulojn, kiel ordonis al mi la Eternulo, mia Dio, ke vi agu tiel en la lando, en kiun vi venas, por ekposedi ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Kaj observu kaj plenumu ilin; ĉar tio estas via saĝo kaj via prudento en la okuloj de la popoloj, kiuj aŭdos pri ĉiuj ĉi tiuj leĝoj, kaj diros: Efektive, popolo saĝa kaj prudenta estas tiu granda popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Ĉar kie estas granda popolo, al kiu dioj estas tiel proksimaj, kiel la Eternulo, nia Dio, ĉiufoje, kiam ni vokas al Li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Kaj kie estas granda popolo, kiu havas leĝojn kaj regulojn justajn, kiel la tuta ĉi tiu instruo, kiun mi donas al vi hodiaŭ?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Nur gardu vin kaj forte gardu vian animon, ke vi ne forgesu la aferojn, kiujn vidis viaj okuloj, kaj ke ili ne eliru el via koro dum via tuta vivo; kaj rakontu al viaj filoj kaj al la filoj de viaj filoj');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'pri la tago, en kiu vi staris antaŭ la Eternulo, via Dio, ĉe Ĥoreb, kiam la Eternulo diris al mi: Kunvenigu al Mi la popolon, kaj Mi aŭdigos al ili Miajn vortojn, per kiuj ili lernos timi Min dum la tuta tempo, kiun ili vivas sur la tero, kaj ili lernigos siajn filojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Tiam vi alproksimiĝis kaj stariĝis ĉe la bazo de la monto, kaj la monto brulis per fajro ĝis la mezo de la ĉielo, en mallumo, nubo, kaj nebulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Kaj la Eternulo parolis al vi el meze de la fajro; la voĉon de la vortoj vi aŭdis, sed figuron vi ne vidis, nur la voĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Kaj Li sciigis al vi Sian interligon, kiun Li ordonis al vi plenumi, la dek ordonojn; kaj Li skribis ilin sur du ŝtonaj tabeloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Kaj al mi la Eternulo en tiu tempo ordonis instrui al vi la leĝojn kaj regulojn, por ke vi plenumadu ilin en la lando, en kiun vi iras, por ekposedi ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Gardu do bone viajn animojn: ĉar vi vidis nenian figuron en tiu tago, kiam la Eternulo parolis al vi sur Ĥoreb el meze de la fajro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'vi do ne malĉastiĝu, kaj ne faru al vi ian skulptaĵon, bildon de ia idolo, figuron de viro aŭ virino,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'figuron de ia bruto, kiu estas sur la tero, figuron de ia flugilhava birdo, kiu flugas sub la ĉielo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'figuron de io, kio rampas sur la tero, figuron de ia fiŝo, kiu estas en akvo, malsupre de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'Kaj, levinte viajn okulojn al la ĉielo kaj vidinte la sunon kaj la lunon kaj la stelojn kaj la tutan armeon de la ĉielo, ne forlogiĝu, kaj ne adorkliniĝu antaŭ ili kaj ne servu ilin, kiujn la Eternulo, via Dio, destinis por ĉiuj popoloj sub la tuta ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Kaj vin la Eternulo prenis, kaj elkondukis vin el la fera forno, el Egiptujo, por ke vi estu al Li popolo herede apartenanta, kiel nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Kaj la Eternulo ekkoleris min pro vi, kaj ĵuris, ke mi ne transiros Jordanon, kaj mi ne venos en la bonan landon, kiun la Eternulo, via Dio, donas al vi kiel posedaĵon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'ĉar mi mortos en ĉi tiu lando, mi ne transiros Jordanon, sed vi transiros kaj ekposedos tiun bonan landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Gardu vin, ke vi ne forgesu la interligon de la Eternulo, via Dio, kiun Li faris kun vi, kaj ke vi ne faru al vi ian skulptaĵon, figuron de io, kiel ordonis al vi la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Ĉar la Eternulo, via Dio, estas fajro konsumanta, Dio severa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Se vi naskos filojn kaj filojn de filoj, kaj, longe vivinte sur la tero, vi malĉastiĝos kaj faros skulptitan figuron de io kaj faros malbonon antaŭ la okuloj de la Eternulo, via Dio, kolerigante Lin:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'mi atestigas al vi hodiaŭ la ĉielon kaj la teron, ke vi rapide pereos de sur la tero, por kies ekposedo vi transiras Jordanon; ne longe vi loĝos sur ĝi, sed vi estos ekstermitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Kaj la Eternulo dissemos vin inter la popoloj, kaj vi restos en malgranda nombro inter la popoloj, al kiuj la Eternulo vin foririgos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Kaj vi servos tie al dioj, kiuj estas faritaĵo de homaj manoj, ligno kaj ŝtono, kiuj ne vidas kaj ne aŭdas kaj ne manĝas kaj ne flaras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Kaj vi serĉos el tie la Eternulon, vian Dion; kaj vi trovos, se vi serĉos Lin per via tuta koro kaj per via tuta animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Kiam vi estos en mizero kaj kiam vin trafos ĉio ĉi tio en la malproksima venonta tempo, tiam vi revenos al la Eternulo, via Dio, kaj vi aŭskultos Lian voĉon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'ĉar la Eternulo, via Dio, estas Dio kompatema; Li ne forlasos vin nek pereigos vin, kaj ne forgesos la interligon kun viaj patroj, pri kiu Li ĵuris al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Ĉar demandu la tempojn antaŭajn, kiuj estis antaŭ vi de post tiu tago, en kiu la Eternulo kreis homon sur la tero, kaj de unu rando de la ĉielo ĝis la alia rando: Ĉu estis io, kiel ĉi tiu granda afero, aŭ ĉu oni aŭdis pri io simila?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Ĉu aŭdis la popolo la voĉon de Dio, parolantan el meze de fajro, kiel vi aŭdis, kaj restis vivanta?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Aŭ ĉu provis ia dio iri kaj preni al si unu popolon el inter alia popolo per provoj, per signoj, kaj per mirakloj, kaj per milito kaj per forta mano kaj per etendita brako kaj per grandaj teruraĵoj, simile al ĉio, kion faris al vi la Eternulo, via Dio, en Egiptujo, antaŭ viaj okuloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Al vi tio estis montrita, por ke vi sciu, ke la Eternulo estas Dio, ke ne ekzistas alia krom Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'El la ĉielo Li aŭdigis al vi Sian voĉon, por instrui vin, kaj sur la tero Li montris al vi Sian grandan fajron, kaj Liajn vortojn vi aŭdis el meze de la fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Kaj ĉar Li amis viajn patrojn, tial Li elektis ilian idaron post ili, kaj elkondukis vin per Sia vizaĝo, per Sia granda forto el Egiptujo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'por forpeli de antaŭ vi popolojn, kiuj estas pli grandaj kaj pli fortaj ol vi, por envenigi vin kaj doni al vi ilian landon kiel posedaĵon, kiel nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Sciu do nun kaj enmetu en vian koron, ke la Eternulo estas Dio en la ĉielo supre kaj sur la tero malsupre; ne ekzistas alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Kaj observu Liajn leĝojn kaj Liajn ordonojn, kiujn mi ordonas al vi hodiaŭ, por ke estu bone al vi kaj al viaj filoj post vi, kaj por ke vi longe vivu sur la tero, kiun la Eternulo, via Dio, donas al vi por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Tiam Moseo apartigis tri urbojn transe de Jordan, sur la flanko de sunleviĝo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'por ke tien forkuru mortiginto, kiu mortigis sian proksimulon senintence, ne estinte malamika al li de antaŭe, kaj forkurinte al unu el tiuj urboj, li restu viva:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Becer en la dezerto, sur la ebenaĵo, por la Rubenidoj, kaj Ramot en Gilead por la Gadidoj, kaj Golan en Baŝan por la Manaseidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Kaj jen estas la instruo, kiun Moseo proponis al la Izraelidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'jen estas la atestoj kaj la leĝoj kaj la reguloj, kiujn Moseo eldiris al la Izraelidoj post ilia eliro el Egiptujo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'transe de Jordan, en la valo kontraŭ Bet-Peor, en la lando de Siĥon, reĝo de la Amoridoj, kiu loĝis en Ĥeŝbon kaj kiun venkobatis Moseo kaj la Izraelidoj post sia eliro el Egiptujo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'kaj ili ekposedis lian landon, kaj la landon de Og, reĝo de Baŝan, la du reĝoj de la Amoridoj, kiuj estis transe de Jordan, sur la flanko de sunleviĝo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'de Aroer, kiu estas sur la bordo de la torento Arnon, ĝis la monto Sion (kiu ankaŭ nomiĝas Ĥermon);');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'kaj la tutan stepon transe de Jordan oriente kaj ĝis la maro de la stepo ĉe la bazo de Pisga.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Kaj Moseo kunvokis ĉiujn Izraelidojn, kaj diris al ili: Aŭskultu, ho Izrael, la leĝojn kaj la regulojn, kiujn mi diras en viajn orelojn hodiaŭ, kaj lernu ilin kaj observu plenumi ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'La Eternulo, nia Dio, faris kun ni interligon sur Ĥoreb.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Ne kun niaj patroj la Eternulo faris tiun interligon, sed kun ni, kun ni, kiuj nun ĉi tie ĉiuj vivas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Vizaĝon kontraŭ vizaĝo la Eternulo parolis kun vi sur la monto el meze de la fajro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'mi tiam staris inter la Eternulo kaj vi, por transdiri al vi la vorton de la Eternulo, ĉar vi timis la fajron kaj ne supreniris sur la monton. Kaj Li diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Mi estas la Eternulo, via Dio, kiu elkondukis vin el la lando Egipta, el la domo de sklaveco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Ne ekzistu ĉe vi aliaj dioj antaŭ Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Ne faru al vi idolon, nek bildon de io, kio estas en la ĉielo supre aŭ sur la tero malsupre aŭ en la akvo sub la tero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'ne kliniĝu antaŭ ili kaj ne servu ilin; ĉar Mi, la Eternulo, via Dio, estas Dio severa, kiu la malbonagon de la patroj punas sur la idoj en la tria kaj kvara generacioj ĉe Miaj malamantoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'kaj kiu faras favorkoraĵon por miloj al Miaj amantoj kaj al la plenumantoj de Miaj ordonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Ne malbonuzu la nomon de la Eternulo, via Dio; ĉar la Eternulo ne lasos senpuna tiun, kiu malbonuzas Lian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Observu la tagon sabatan, ke vi tenu ĝin sankta, kiel ordonis al vi la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Dum ses tagoj laboru kaj faru ĉiujn viajn aferojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'sed la sepa tago estas sabato de la Eternulo, via Dio; faru nenian laboron, nek vi, nek via filo, nek via filino, nek via sklavo, nek via sklavino, nek via bovo, nek via azeno, nek ia via bruto, nek via fremdulo, kiu estas inter viaj pordegoj; por ke ripozu via sklavo kaj via sklavino, kiel vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Kaj memoru, ke vi estis sklavo en la lando Egipta, kaj la Eternulo, via Dio, elkondukis vin el tie per mano forta kaj per brako etendita; pro tio ordonis al vi la Eternulo, via Dio, observi la tagon sabatan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Respektu vian patron kaj vian patrinon, kiel ordonis al vi la Eternulo, via Dio; por ke longe daŭru via vivo, kaj por ke estu al vi bone sur la tero, kiun la Eternulo, via Dio, donas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Ne mortigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Kaj ne adultu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Kaj ne ŝtelu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Kaj ne parolu kontraŭ via proksimulo malveran ateston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Kaj ne deziru la edzinon de via proksimulo; kaj ne deziru la domon de via proksimulo, nek lian kampon, nek lian sklavon, nek lian sklavinon, nek lian bovon, nek lian azenon, nek ion, kio apartenas al via proksimulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Tiujn vortojn diris la Eternulo al via tuta anaro sur la monto, el meze de la fajro, nubo, kaj nebulo, per voĉo laŭta; kaj Li nenion plu aldonis. Kaj Li skribis ilin sur du ŝtonaj tabeloj kaj donis ilin al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Kaj kiam vi aŭdis la voĉon el la mallumo, dum la monto brulis per fajro, tiam vi aliris al mi, ĉiuj viaj tribestroj kaj plejaĝuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'kaj vi diris: Jen la Eternulo, nia Dio, montris al ni Sian majeston kaj Sian grandecon, kaj Lian voĉon ni aŭdis el meze de la fajro; en tiu tago ni vidis, ke parolas Dio al homo, kaj ĉi tiu restas vivanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Sed nun por kio ni mortu? nin ja formanĝos ĉi tiu granda fajro; se ni plue aŭskultos la voĉon de la Eternulo, nia Dio, ni mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Ĉar kie ekzistas ia karno, kiu aŭdis la voĉon de la vivanta Dio, parolantan el meze de fajro, kiel ni, kaj restis vivanta?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Alproksimiĝu vi, kaj aŭskultu ĉion, kion diros la Eternulo, nia Dio; kaj vi transdiros al ni ĉion, kion diros la Eternulo, nia Dio, kaj ni aŭskultos kaj ni plenumos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Kaj la Eternulo aŭdis la voĉon de viaj vortoj, kiam vi parolis al mi; kaj la Eternulo diris al mi: Mi aŭdis la voĉon de la vortoj de ĉi tiu popolo, kiujn ili diris al vi; bona estas ĉio, kion ili diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Ho, se ilia koro restus ĉe ili tia, ke ili timu Min kaj observu ĉiujn Miajn ordonojn ĉiutempe, por ke estu bone al ili kaj al iliaj filoj eterne!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Iru, diru al ili: Reiru en viajn tendojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Kaj vi ĉi tie restu kun Mi, kaj Mi eldiros al vi ĉiujn ordonojn kaj leĝojn kaj regulojn, kiujn vi instruos al ili, por ke ili plenumadu ilin en la lando, kiun Mi donas al ili kiel posedaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Kaj observu, ke vi faru, kiel ordonis al vi la Eternulo, via Dio; ne forflankiĝu dekstren, nek maldekstren.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'Laŭ tiu tuta vojo, kiun ordonis al vi la Eternulo, via Dio, iradu, por ke vi vivu kaj por ke estu bone al vi, kaj por ke longe daŭru via restado en la lando, kiun vi ekposedos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Kaj jen estas la ordonoj, la leĝoj, kaj la reguloj, kiujn la Eternulo, via Dio, ordonis instrui al vi, por ke vi plenumadu ilin en la lando, en kiun vi transiras, por ekposedi ĝin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'por ke vi timu la Eternulon, vian Dion, observante ĉiujn Liajn leĝojn kaj Liajn ordonojn, kiujn mi ordonas al vi, vi kaj via filo kaj la filo de via filo, dum via tuta vivo, por ke vi longe vivu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Aŭskultu do, Izrael, kaj observu, ke vi plenumu, por ke estu al vi bone, kaj por ke vi tre multiĝu, kiel diris al vi la Eternulo, la Dio de viaj patroj, en la lando, en kiu fluas lakto kaj mielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Aŭskultu, ho Izrael! la Eternulo, nia Dio, la Eternulo estas unu sola.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Kaj amu la Eternulon, vian Dion, per via tuta koro kaj per via tuta animo kaj per via tuta forto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'Kaj ĉi tiuj vortoj, kiujn mi ordonas al vi hodiaŭ, estu en via koro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'kaj ripetadu ilin al viaj infanoj, kaj parolu pri ili, kiam vi sidas en via domo kaj kiam vi iras sur vojo kaj kiam vi kuŝiĝas kaj kiam vi leviĝas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'kaj alligu ilin kiel signon al via mano, kaj ili estu kiel memorigaĵo inter viaj okuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'kaj skribu ilin sur la fostoj de via domo kaj sur viaj pordegoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'Kaj kiam la Eternulo, via Dio, venigos vin en la landon, pri kiu Li ĵuris al viaj patroj, al Abraham, al Isaak, kaj al Jakob, ke Li donos al vi grandajn kaj bonajn urbojn, kiujn vi ne konstruis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'kaj domojn plenajn de ĉia bonaĵo, kiujn vi ne plenigis, kaj putojn, elhakitajn en ŝtono, kiujn vi ne elhakis, vinberejojn kaj olivarbojn, kiujn vi ne plantis; kaj vi manĝos kaj estos sata:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'tiam gardu vin, ke vi ne forgesu la Eternulon, kiu elkondukis vin el la lando Egipta, el la domo de sklaveco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'La Eternulon, vian Dion, timu, kaj al Li servu, kaj per Lia nomo ĵuru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Ne sekvu aliajn diojn el la dioj de la popoloj, kiuj estas ĉirkaŭ vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'ĉar la Eternulo, via Dio inter vi, estas Dio severa; povas ekflami la kolero de la Eternulo, via Dio, kontraŭ vin, kaj Li ekstermos vin de sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Ne provu la Eternulon, vian Dion, kiel vi provis Lin en Masa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Precize observu la ordonojn de la Eternulo, via Dio, kaj Liajn atestojn kaj Liajn leĝojn, kiujn Li ordonis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'Kaj faru juston kaj bonon antaŭ la okuloj de la Eternulo, por ke estu bone al vi, kaj por ke vi venu kaj ekposedu la bonan landon, pri kiu la Eternulo ĵuris al viaj patroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'por ke Li forpelu ĉiujn viajn malamikojn antaŭ vi, kiel la Eternulo diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Se via filo vin demandos morgaŭ: Kion signifas la atestoj kaj leĝoj kaj reguloj, kiujn la Eternulo, nia Dio, ordonis al vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'tiam diru al via filo: Ni estis sklavoj al Faraono en Egiptujo, sed la Eternulo elkondukis nin el Egiptujo per forta mano;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'kaj la Eternulo aperigis signojn kaj miraklojn grandajn kaj suferigajn en Egiptujo, sur Faraono kaj sur lia tuta domo, antaŭ niaj okuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'kaj nin Li elkondukis el tie, por venigi nin kaj doni al ni la landon, pri kiu Li ĵuris al niaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Kaj la Eternulo ordonis al ni plenumi ĉiujn ĉi tiujn leĝojn, timi la Eternulon, nian Dion, por ke estu al ni bone ĉiam, por konservi al ni la vivon, kiel en la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'Kaj tio estos nia justeco, se ni observos plenumi ĉi tiun tutan ordonon antaŭ la Eternulo, nia Dio, kiel Li ordonis al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Kiam la Eternulo venigos vin en la landon, al kiu vi iras, por ekposedi ĝin, kaj Li forpelos antaŭ vi grandnombrajn popolojn, la Ĥetidojn kaj la Girgaŝidojn kaj la Amoridojn kaj la Kanaanidojn kaj la Perizidojn kaj la Ĥividojn kaj la Jebusidojn, sep popolojn pli grandnombrajn kaj pli fortajn ol vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'kaj kiam la Eternulo, via Dio, transdonos ilin al vi, kaj vi venkobatos ilin; tiam anatemu ilin, ne faru kun ili interligon kaj ne indulgu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Kaj ne boparenciĝu kun ili: vian filinon ne donu al ilia filo, kaj ilian filinon ne prenu por via filo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'ĉar ili forturnos viajn filojn de Mi, ke ili servu al aliaj dioj, kaj ekflamos kontraŭ vi la kolero de la Eternulo, kaj Li ekstermos vin rapide.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Sed tiele agu kun ili: iliajn altarojn detruu kaj iliajn statuojn rompu kaj iliajn sanktajn stangojn dishaku kaj iliajn idolojn forbruligu per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Ĉar popolo sankta vi estas al la Eternulo, via Dio; vin elektis la Eternulo, via Dio, ke vi estu Lia popolo propra el ĉiuj popoloj, kiuj estas sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Ne pro tio, ke vi estas la plej grandnombra el ĉiuj popoloj, la Eternulo ekdeziris vin kaj elektis vin, ĉar vi estas ja malpli grandnombra ol ĉiuj popoloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'sed pro la amo de la Eternulo al vi, kaj por ke Li plenumu la ĵuron, kiun Li ĵuris al viaj patroj, la Eternulo elkondukis vin per forta mano kaj liberigis vin el la domo de sklaveco, el la mano de Faraono, reĝo de Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Sciu do, ke la Eternulo, via Dio, nur Li estas Dio, Dio fidinda, kiu konservas la interligon kaj favorkorecon rilate al Liaj amantoj kaj al la plenumantoj de Liaj ordonoj dum mil generacioj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'kaj kiu repagas al Siaj malamantoj persone, pereigante ilin, ne prokrastas al Sia malamanto, al li persone Li repagas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Observu do la ordonojn kaj la leĝojn kaj la regulojn, kiujn mi ordonas al vi hodiaŭ, por plenumi ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Kaj pro tio, ke vi aŭskultos tiujn regulojn kaj observos ilin kaj plenumos ilin, la Eternulo, via Dio, konservos al vi la interligon kaj la favorkorecon, pri kiuj Li ĵuris al viaj patroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'kaj Li amos vin kaj benos vin kaj multigos vin, kaj benos la frukton de via ventro kaj la frukton de via tero, vian grenon kaj vian moston kaj vian oleon, la frukton de viaj bovinoj kaj la frukton de viaj ŝafinoj, sur la tero, pri kiu Li ĵuris al viaj patroj, ke Li donos ĝin al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Vi estos benita pli ol ĉiuj popoloj; ne estos inter vi senfruktulo aŭ senfruktulino, ankaŭ inter viaj brutoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Kaj la Eternulo forturnos de vi ĉian malsanon, kaj ĉiun malbonan epidemiaĵon de Egiptujo, kiun vi konas; Li ne metos ilin sur vin, sed Li metos ilin sur ĉiujn viajn malamantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Kaj vi konsumos ĉiujn popolojn, kiujn la Eternulo, via Dio, transdonas al vi; ne indulgu ilin via okulo, kaj vi ne servu al iliaj dioj, ĉar tio estus falilo por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Eble vi diros en via koro: Tiuj popoloj estas pli grandnombraj ol mi, kiel mi povos forpeli ilin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'Ne timu ilin: memoru, kion faris la Eternulo, via Dio, al Faraono kaj al la tuta Egiptujo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'la grandajn provojn, kiujn vidis viaj okuloj, kaj la signojn kaj la miraklojn kaj la fortan manon kaj la etenditan brakon, per kiuj elkondukis vin la Eternulo, via Dio; tiel la Eternulo, via Dio, faros al ĉiuj popoloj, kiujn vi timas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Kaj ankaŭ krabrojn sendos la Eternulo, via Dio, sur ilin, ĝis pereos la restintoj, kaj tiuj, kiuj kaŝiĝis antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Ne sentu teruron antaŭ ili, ĉar la Eternulo, via Dio, estas inter vi, la Dio granda kaj timinda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Kaj la Eternulo, via Dio, forpelos tiujn popolojn de antaŭ vi iom post iom; vi ne povas ekstermi ilin rapide, por ke ne multiĝu kontraŭ vi la sovaĝaj bestoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Kaj la Eternulo, via Dio, transdonos ilin al vi, kaj Li tumultigos ilin antaŭ vi per granda tumulto, ĝis ili estos ekstermitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Kaj Li transdonos iliajn reĝojn en viajn manojn, kaj vi ekstermos ilian nomon el sub la ĉielo; neniu restos stare antaŭ vi, ĝis vi ekstermos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'La figurojn de iliaj dioj forbruligu per fajro; ne deziru preni al vi la arĝenton aŭ oron, kiu estas sur ili, por ke vi ne kaptiĝu per tio; ĉar tio estas abomenaĵo por la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Kaj ne enportu abomenaĵon en vian domon, por ke vi ne anatemiĝu kiel ĝi; malestimu kaj abomenu ĝin, ĉar ĝi estas anatemaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Ĉiujn ordonojn, kiujn mi ordonas al vi hodiaŭ, observu, por plenumi ilin, por ke vi vivu kaj multiĝu, kaj venu kaj ekposedu la landon, pri kiu la Eternulo ĵuris al viaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Kaj memoru la tutan vojon, laŭ kiu kondukis vin la Eternulo, via Dio, dum kvardek jaroj tra la dezerto, por humiligi vin, por elprovi vin, por sciiĝi, kio estas en via koro, ĉu vi obeos Liajn ordonojn aŭ ne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Kaj Li humiligis vin kaj malsatigis vin, kaj nutris vin per manao, kiun vi ne konis kaj kiun ne konis viaj patroj, por montri al vi, ke ne per la pano sole vivas homo, sed per ĉio, kio eliras el la buŝo de la Eternulo, homo povas vivi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Via vesto ne sentaŭgiĝis sur vi kaj via piedo ne ŝvelis dum ĉiuj kvardek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Kaj sciu en via koro, ke kiel homo instruas sian filon, tiel la Eternulo, via Dio, instruas vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'Observu do la ordonojn de la Eternulo, via Dio, irante laŭ Liaj vojoj kaj timante Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Ĉar la Eternulo, via Dio, kondukas vin en landon bonan, en landon, en kiu torentoj da akvo, fontoj, kaj lagoj eliras el la valoj kaj el la montoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'en landon de tritiko kaj hordeo kaj vinberoj kaj figarboj kaj granatarboj, en landon de olivarboj kaj mielo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'en landon, en kiu vi manĝos panon sen neceso de ŝparado kaj en kiu nenio al vi mankos, en landon, kies ŝtonoj estas fero kaj en kies montoj vi elhakados kupron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Kaj vi manĝos kaj satiĝos, kaj vi benos la Eternulon, vian Dion, pro la bona tero, kiun Li donis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Gardu vin, ke vi ne forgesu la Eternulon, vian Dion, ne observante Liajn ordonojn kaj instrukciojn kaj leĝojn, kiujn mi ordonas al vi hodiaŭ;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'kiam vi manĝos kaj satiĝos kaj konstruos bonajn domojn kaj enloĝiĝos,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'kaj kiam viaj grandaj kaj malgrandaj brutoj multiĝos kaj vi havos multe da arĝento kaj oro kaj via tuta havo grandiĝos,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'tiam ne altiĝu via koro, kaj ne forgesu la Eternulon, vian Dion, kiu elkondukis vin el la lando Egipta, el la domo de sklaveco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'kaj kiu trakondukis vin tra la granda kaj terura dezerto, kie estis serpentoj, aspidoj kaj skorpioj kaj sekaj lokoj senakvaj; kaj kiu eligis por vi akvon el granita roko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'kaj kiu nutris vin en la dezerto per manao, kiun ne konis viaj patroj, por humiligi vin kaj por elprovi vin, por fari al vi bonon en la tempo estonta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Ne diru en via koro: Mia forto kaj la potenco de mia mano akiris al mi ĉi tiun grandan havon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'sed memoru la Eternulon, vian Dion, ĉar Li estas Tiu, kiu donas al vi forton, por akiri grandan havon, por plenumi Sian interligon, pri kiu Li ĵuris al viaj patroj, kiel vi vidas nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Kaj mi avertas vin hodiaŭ, ke, se vi forgesos la Eternulon, vian Dion, kaj sekvos aliajn diojn kaj servos al ili kaj kliniĝos antaŭ ili, tiam vi pereos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'simile al la popoloj, kiujn la Eternulo pereigas antaŭ vi, tiel vi pereos; pro tio, ke vi ne obeos la voĉon de la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Aŭskultu, ho Izrael! vi transiras nun Jordanon, por iri kaj ekposedi popolojn, kiuj estas pli grandaj kaj pli fortaj ol vi, urbojn grandajn kaj fortikigitajn ĝis la ĉielo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'popolon grandan kaj altkreskan, la Anakidojn, kiujn vi konas, kaj pri kiuj vi aŭdis: Kiu povas kontraŭstari al la filoj de Anak?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Sciu do nun, ke la Eternulo, via Dio, mem iras antaŭ vi, kiel fajro konsumanta; Li ekstermos ilin kaj Li submetos ilin antaŭ vi, kaj vi forpelos ilin kaj pereigos ilin rapide, kiel la Eternulo diris al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Ne diru en via koro, kiam la Eternulo, via Dio, forpelos ilin de antaŭ vi: Pro mia virteco la Eternulo venigis min por ekposedi ĉi tiun landon; pro la malvirteco de ĉi tiuj popoloj la Eternulo forpelas ilin de antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Ne pro via virteco kaj pro la honesteco de via koro vi venas por ekposedi ilian landon; sed pro la malvirteco de ĉi tiuj popoloj la Eternulo, via Dio, forpelas ilin de antaŭ vi, kaj por plenumi tion, kion la Eternulo ĵuris al viaj patroj, al Abraham, al Isaak, kaj al Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Sciu do, ke ne pro via virteco la Eternulo, via Dio, donas al vi tiun bonan landon por ekposedi ĝin; ĉar vi estas popolo malmolnuka.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Memoru, ne forgesu, kiel vi kolerigis la Eternulon, vian Dion, en la dezerto; de post la tago, en kiu vi eliris el la lando Egipta, ĝis via veno al ĉi tiu loko, vi estis malobeemaj kontraŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Kaj ĉe Ĥoreb vi incitis la Eternulon, kaj la Eternulo ekkoleris kontraŭ vi tiel, ke Li volis ekstermi vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Kiam mi supreniris sur la monton, por preni la ŝtonajn tabelojn, la tabelojn de la interligo, kiun la Eternulo faris kun vi, kaj mi restis sur la monto kvardek tagojn kaj kvardek noktojn, panon mi ne manĝis kaj akvon mi ne trinkis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'tiam la Eternulo donis al mi la du ŝtonajn tabelojn skribitajn per la fingro de Dio, kaj sur ili estis ĉiuj vortoj, kiujn diris al vi la Eternulo sur la monto el meze de fajro en la tago de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Kaj tio estis post la paso de kvardek tagoj kaj kvardek noktoj, ke la Eternulo donis al mi la du ŝtonajn tabelojn, la tabelojn de la interligo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'Kaj la Eternulo diris al mi: Leviĝu, rapide iru malsupren de ĉi tie, ĉar malmoraliĝis via popolo, kiun vi elkondukis el Egiptujo; rapide ili forflankiĝis de la vojo, kiun Mi ordonis al ili: ili faris al si fanditan idolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Kaj la Eternulo diris al mi jene: Mi vidas ĉi tiun popolon, Mi vidas, ke ĝi estas popolo malmolnuka;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'lasu Min, Mi ekstermos ilin, kaj Mi forviŝos ilian nomon el sub la ĉielo, kaj Mi faros el vi popolon pli fortan kaj pli grandnombran ol ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Kaj mi turnis min kaj malsupreniris de la monto, kaj la monto brulis per fajro; kaj la du tabeloj de la interligo estis en miaj du manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Kaj mi vidis, ke vi pekis kontraŭ la Eternulo, via Dio, vi faris al vi fanditan bovidon, vi rapide forflankiĝis de la vojo, kiun la Eternulo ordonis al vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'kaj mi prenis la du tabelojn kaj forĵetis ilin el miaj ambaŭ manoj kaj disrompis ilin antaŭ viaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Kaj mi ĵetis min antaŭ la Eternulo, kiel antaŭe, dum kvardek tagoj kaj kvardek noktoj mi panon ne manĝis kaj akvon ne trinkis, pro ĉiuj viaj pekoj, kiujn vi pekis, farante malbonon antaŭ la okuloj de la Eternulo, kolerigante Lin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'ĉar mi timis la koleron kaj furiozon, per kiuj la Eternulo ekkoleris kontraŭ vi, dezirante ekstermi vin. Kaj la Eternulo aŭskultis min ankaŭ ĉi tiun fojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Ankaŭ kontraŭ Aaron la Eternulo tre ekkoleris kaj volis ekstermi lin; sed mi preĝis ankaŭ por Aaron en tiu tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Kaj vian pekon, kiun vi faris, la bovidon, mi prenis kaj forbruligis ĝin per fajro kaj disbatis ĝin, disfrakasante tiel, ke ĝi fariĝis malgrandpeca kiel polvo, kaj mi ĵetis ĝian polvon en la torenton, kiu defluas de la monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Ankaŭ en Tabera kaj en Masa kaj en Kibrot-Hataava vi kolerigis la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'Kaj kiam la Eternulo sendis vin el Kadeŝ-Barnea, dirante: Iru kaj ekposedu la landon, kiun Mi donas al vi; tiam vi malobeis la vortojn de la Eternulo, via Dio, kaj vi ne kredis al Li kaj ne aŭskultis Lian voĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Malobeemaj vi estis kontraŭ la Eternulo de la tago, kiam mi ekkonis vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Mi do kuŝis antaŭ la Eternulo dum la kvardek tagoj kaj kvardek noktoj, kiujn mi kuŝis; ĉar la Eternulo intencis ekstermi vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'Kaj mi preĝis al la Eternulo, kaj diris: Mia Sinjoro, ho Eternulo, ne pereigu Vian popolon kaj Vian posedaĵon, kiun Vi liberigis per Via grandeco kaj kiun Vi elkondukis el Egiptujo per forta mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Rememoru Viajn servantojn Abraham, Isaak, kaj Jakob; ne atentu la obstinecon de ĉi tiu popolo nek ĝian malvirtecon nek ĝiajn pekojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'por ke ne diru la loĝantoj de tiu lando, el kiu Vi elkondukis nin: Pro tio, ke la Eternulo ne povis venigi ilin en la landon, pri kiu Li parolis al ili, kaj pro malamo al ili Li elkondukis ilin, por mortigi ilin en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Kaj ili estas ja Via popolo kaj Via posedaĵo, kiun Vi elkondukis per Via granda forto kaj per Via etendita brako.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'En tiu tempo la Eternulo diris al mi: Skulptu al vi du ŝtonajn tabelojn kiel la antaŭaj, kaj supreniru al Mi sur la monton, kaj faru al vi lignan keston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'Kaj Mi skribos sur la tabeloj la vortojn, kiuj estis sur la antaŭaj tabeloj, kiujn vi disrompis, kaj vi metos ilin en la keston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Tiam mi faris keston el akacia ligno, kaj mi skulptis du ŝtonajn tabelojn kiel la antaŭaj, kaj mi iris sur la monton, kaj la du tabeloj estis en miaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'Kaj Li skribis sur la tabeloj, kiel estis skribite antaŭe, la dek ordonojn, kiujn la Eternulo diris al vi sur la monto el meze de la fajro en la tago de kunveno, kaj la Eternulo donis ilin al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Kaj mi turnis min kaj malsupreniris de la monto, kaj metis la tabelojn en la keston, kiun mi faris, kaj ili restis tie, kiel la Eternulo ordonis al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, '(Kaj la Izraelidoj ekvojiris de Beerot-Bene-Jaakan al Mosera; tie mortis Aaron, kaj tie li estis enterigita; kaj lia filo Eleazar fariĝis pastro anstataŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'De tie ili ekvojiris al Gudgod, kaj el Gudgod al Jotbata, en la landon, en kiu troviĝas torentoj da akvoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'En tiu tempo la Eternulo apartigis la tribon de Levi, por porti la keston de la interligo de la Eternulo, por stari antaŭ la Eternulo, servi al Li, kaj beni en Lia nomo, ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Tial Levi ne ricevis parton kaj heredan posedaĵon kun siaj fratoj: la Eternulo estas lia heredaĵo, kiel la Eternulo, via Dio, diris al li.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Kaj mi staris sur la monto, kiel en la antaŭa tempo, dum kvardek tagoj kaj kvardek noktoj; kaj la Eternulo aŭskultis min ankaŭ tiun fojon: la Eternulo ne volis pereigi vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Kaj la Eternulo diris al mi: Leviĝu, ekvojiru antaŭ la popolo, por ke ili venu kaj ekposedu la landon, pri kiu Mi ĵuris al iliaj patroj, ke Mi donos ĝin al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Kaj nun, Izrael, kion la Eternulo, via Dio, postulas de vi? nur ke vi timu la Eternulon, vian Dion, ke vi iru laŭ ĉiuj Liaj vojoj, ke vi amu Lin, kaj ke vi servu al la Eternulo, via Dio, per via tuta koro kaj per via tuta animo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'ke vi observu la ordonojn de la Eternulo kaj Liajn leĝojn, kiujn mi transdonas al vi hodiaŭ, por ke estu bone al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Jen al la Eternulo, via Dio, apartenas la ĉielo kaj la ĉielo de la ĉieloj, la tero, kaj ĉio, kio estas sur ĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'tamen nur pri viaj patroj plaĉis al la Eternulo ekami ilin, kaj Li elektis vin, ilian idaron post ili, el ĉiuj popoloj, kiel vi vidas nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Cirkumcidu do la prepucion de via koro, kaj ne estu plu malmolnukaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Ĉar la Eternulo, via Dio, estas Dio de dioj kaj Sinjoro de sinjoroj, la Dio granda, potenca, kaj timinda, kiu ne atentas personojn kaj ne prenas subaĉeton,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'kaj kiu zorgas pri justeco por orfo kaj vidvino, kaj amas fremdulon, donante al li panon kaj veston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Amu do la fremdulon; ĉar fremduloj vi estis en la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'La Eternulon, vian Dion, timu; al Li servu kaj al Li algluiĝu kaj per Lia nomo ĵuru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Li estas via gloro, kaj Li estas via Dio, kiu faris por vi tiujn grandajn kaj timindajn aferojn, kiujn vidis viaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'En la nombro de sepdek animoj viaj patroj foriris en Egiptujon, kaj nun la Eternulo, via Dio, faris vin grandnombraj kiel la steloj de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Amu do la Eternulon, vian Dion, kaj observu Liajn aranĝojn kaj leĝojn kaj instrukciojn kaj ordonojn en ĉiu tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Kaj sciu hodiaŭ, ĉar mi parolas ne al viaj filoj, kiuj ne scias kaj ne vidis la punon de la Eternulo, via Dio, Lian grandecon, Lian fortan manon, kaj Lian etenditan brakon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'kaj Liajn signojn kaj Liajn farojn, kiujn Li faris interne de Egiptujo al Faraono, reĝo de Egiptujo, kaj al lia tuta lando;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'kaj kion Li faris al la militistaro de Egiptujo, al ĝiaj ĉevaloj kaj ĉaroj, kiujn Li superverŝis per la akvo de la Ruĝa Maro, kiam ili postkuris vin; kaj la Eternulo pereigis ilin ĝis la nuna tago;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'kaj kion Li faris al vi en la dezerto, ĝis vi venis al ĉi tiu loko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'kaj kion Li faris al Datan kaj Abiram, filoj de Eliab, filo de Ruben, kiam la tero malfermis sian buŝon kaj englutis ilin kaj iliajn familiojn kaj iliajn tendojn, kaj ĉion, kio ekzistis ĉe ili, meze de la tuta Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Viaj okuloj vidis ja ĉiujn grandajn farojn de la Eternulo, kiujn Li faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Observu do ĉiujn ordonojn, kiujn mi ordonas al vi hodiaŭ, por ke vi fortiĝu, kaj por ke vi venu kaj ekposedu la landon, en kiun vi transiras, por ekposedi ĝin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'kaj por ke vi longe vivu sur la tero, pri kiu la Eternulo ĵuris al viaj patroj, ke Li donos ĝin al ili kaj al ilia idaro, landon, en kiu fluas lakto kaj mielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Ĉar la lando, en kiun vi iras, por ekposedi ĝin, ne estas kiel la lando Egipta, el kiu vi eliris, kie, seminte vian semon, vi devis akvumi ĝin per viaj piedoj, kiel legoman ĝardenon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'La lando, en kiun vi transiras, por ekposedi ĝin, estas lando kun montoj kaj valoj; de la pluvo ĉiela ĝi trinkas akvon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'lando, pri kiu zorgas la Eternulo, via Dio; ĉiam la okuloj de la Eternulo, via Dio, estas sur ĝi, de la komenco de la jaro ĝis la fino de la jaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Kaj se vi obeos Miajn ordonojn, kiujn Mi ordonas al vi hodiaŭ, amante la Eternulon, vian Dion, kaj servante al Li per via tuta koro kaj per via tuta animo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'tiam Mi donos al via lando pluvon ĝiatempe, fruan kaj malfruan; kaj vi kolektos vian grenon kaj vian moston kaj vian oleon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'Kaj Mi donos herbon sur via kampo por via bruto; kaj vi manĝos kaj estos sata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Gardu vin, ke ne forlogiĝu via koro, kaj ke vi ne forflankiĝu, kaj ke vi ne servu al aliaj dioj kaj ne kliniĝu antaŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'Alie ekflamos kontraŭ vi la kolero de la Eternulo, kaj Li ŝlosos la ĉielon, kaj ne estos pluvo, kaj la tero ne donos siajn produktaĵojn, kaj vi rapide forpereos el la bona lando, kiun la Eternulo donas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Metu do ĉi tiujn miajn vortojn en vian koron kaj en vian animon, kaj alligu ilin kiel signon al via mano, kaj ili estu kiel memorigaĵo inter viaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'Kaj instruu ilin al viaj filoj, parolante pri ili, kiam vi sidos en via domo kaj kiam vi iros sur la vojo kaj kiam vi kuŝiĝos kaj kiam vi leviĝos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'kaj skribu ilin sur la fostoj de via domo kaj sur viaj pordegoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'por ke longiĝu via vivo kaj la vivo de viaj infanoj sur la tero, pri kiu la Eternulo ĵuris al viaj patroj, ke Li donos ĝin al ili, kiel longe estas la ĉielo super la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Se vi observos ĉiujn ĉi tiujn ordonojn, kiujn mi ordonas al vi plenumi, amante la Eternulon, vian Dion, irante laŭ ĉiuj Liaj vojoj, kaj algluiĝante al Li:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'tiam la Eternulo forpelos de antaŭ vi ĉiujn tiujn popolojn, kaj vi ekposedos popolojn pli grandajn kaj pli fortajn ol vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Ĉiu loko, sur kiu ekpaŝos via piedo, fariĝos via; de la dezerto kaj Lebanon, de la rivero, la rivero Eŭfrato, ĝis la ekstrema maro estos viaj limoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Neniu povos kontraŭstari al vi: timon kaj teruron antaŭ vi la Eternulo venigos sur ĉiun teron, sur kiu vi ekpaŝos, kiel Li diris al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Rigardu, mi proponas al vi hodiaŭ benon kaj malbenon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'benon, se vi aŭskultos la ordonojn de la Eternulo, via Dio, kiujn mi ordonas al vi hodiaŭ;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'kaj malbenon, se vi ne aŭskultos la ordonojn de la Eternulo, via Dio, sed forflankiĝos de la vojo, kiun mi ordonas al vi hodiaŭ, kaj sekvos diojn aliajn, kiujn vi ne konas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'Kiam la Eternulo, via Dio, venigos vin en la landon, en kiun vi iras, por ekposedi ĝin, tiam vi esprimos la benon sur la monto Gerizim kaj la malbenon sur la monto Ebal;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'ili estas transe de Jordan, malantaŭ la vojo al la okcidento, en la lando de la Kanaanidoj, kiuj loĝas en la stepo, kontraŭ Gilgal, apud la kverko More.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Ĉar vi transiras Jordanon, por veni ekposedi la landon, kiun la Eternulo, via Dio, donas al vi, kaj vi ekposedos ĝin kaj ekloĝos en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'Observu do, ke vi plenumu ĉiujn leĝojn kaj instrukciojn, kiujn mi donas al vi hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Jen estas la leĝoj kaj reguloj, kiujn vi devas observi por plenumi en la lando, kiun la Eternulo, la Dio de viaj patroj, donas al vi kiel posedaĵon, dum la tuta tempo, kiun vi vivos sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Ekstermu ĉiujn lokojn, kie la popoloj, kiujn vi ekposedos, servis al siaj dioj sur la altaj montoj kaj sur la montetoj kaj sub ĉiu verda arbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Kaj detruu iliajn altarojn, kaj rompu iliajn monumentojn, kaj iliajn sanktajn stangojn forbruligu per fajro, kaj la figurojn de iliaj dioj disbatu, kaj ekstermu ilian nomon de tiu loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Ne faru tiele al la Eternulo, via Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'sed al la loko, kiun elektos la Eternulo, via Dio, inter ĉiuj viaj triboj, por meti tien Sian nomon, al Lia loĝejo direktu vin kaj venu tien,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'kaj tien alportu viajn bruloferojn kaj viajn buĉoferojn kaj viajn dekonaĵojn kaj la oferdonojn de viaj manoj kaj viajn promesitaĵojn kaj viajn memvolajn oferojn kaj la unuenaskitojn el viaj grandaj kaj malgrandaj brutoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'Kaj manĝu tie antaŭ la Eternulo, via Dio, kaj estu gajaj, vi kaj viaj familioj, en ĉiu entrepreno de viaj manoj, per kiu benis vin la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Ne faru simile al ĉio, kion ni faras ĉi tie hodiaŭ, ĉiu tion, kio plaĉas al li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'ĉar vi nun ankoraŭ ne venis al la ripozo kaj al la posedaĵo, kiun la Eternulo, via Dio, donas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Sed kiam vi transiros Jordanon kaj ekloĝos en la lando, kiun la Eternulo, via Dio, posedigas al vi, kaj Li ripozigos vin de ĉiuj viaj malamikoj ĉirkaŭe kaj vi loĝos sendanĝere:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'tiam sur la lokon, kiun elektos la Eternulo, via Dio, por loĝigi tie Sian nomon, tien alportu ĉion, kion mi ordonas al vi: viajn bruloferojn kaj viajn buĉoferojn, viajn dekonaĵojn kaj la oferdonojn de viaj manoj, kaj ĉion elektitan laŭ viaj promesoj, kiujn vi promesis al la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'kaj estu gajaj antaŭ la Eternulo, via Dio, vi kaj viaj filoj kaj viaj filinoj kaj viaj servantoj kaj viaj servantinoj, kaj la Levido, kiu estas inter viaj pordegoj, ĉar li ne havas parton kaj posedaĵon kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Gardu vin, ke vi ne alportu viajn bruloferojn sur ĉiu loko, kiun vi vidos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'nur sur tiu loko, kiun elektos la Eternulo, inter unu el viaj triboj, tie alportu viajn bruloferojn, kaj tie faru ĉion, kion mi ordonas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Tamen, kiom deziros via animo, vi povas buĉi kaj manĝi viandon laŭ la beno de la Eternulo, via Dio, kiun Li donos al vi en ĉiuj viaj urboj; purulo kaj malpurulo povas manĝi ĝin, kiel gazelon aŭ cervon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Nur la sangon ne manĝu; sur la teron elverŝu ĝin, kiel akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Vi ne devas manĝi en viaj urboj la dekonaĵon el via greno kaj el via mosto kaj el via oleo, kaj la unuenaskitojn el viaj grandaj kaj malgrandaj brutoj, kaj ĉiujn viajn promesitaĵojn, kiujn vi promesos, kaj viajn memvolajn oferojn kaj la oferdonojn de viaj manoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'sed nur antaŭ la Eternulo, via Dio, manĝu tion sur la loko, kiun elektos la Eternulo, via Dio, vi kaj via filo kaj via filino kaj via servanto kaj via servantino, kaj la Levido, kiu estas inter viaj pordegoj; kaj estu gajaj antaŭ la Eternulo, via Dio, en ĉiu entrepreno de viaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Gardu vin, ke vi ne forlasu la Levidon dum via tuta vivo sur via tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Kiam la Eternulo, via Dio, vastigos viajn limojn, kiel Li diris al vi, kaj vi diros: Mi manĝos viandon-ĉar via animo ekdeziros manĝi viandon: tiam laŭ la tuta deziro de via animo manĝu viandon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Se estos malproksima de vi tiu loko, kiun elektos la Eternulo, via Dio, por meti tien Sian nomon, tiam buĉu el viaj grandaj kaj malgrandaj brutoj, kiujn la Eternulo donis al vi, kiel mi ordonis al vi, kaj manĝu en viaj urboj laŭ la tuta deziro de via animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Sed manĝu tion tiel, kiel oni manĝas gazelon kaj cervon; malpurulo kaj purulo egale povas tion manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Nur detenu vin, ke vi ne manĝu la sangon; ĉar la sango estas la animo, kaj vi ne devas manĝi la animon kun la viando;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'ne manĝu ĝin, sur la teron elverŝu ĝin, kiel akvon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'ne manĝu ĝin, por ke estu bone al vi kaj al viaj idoj post vi, se vi faros plaĉantaĵon antaŭ la okuloj de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Sed viajn sanktaĵojn, kiujn vi havos, kaj viajn promesitaĵojn portu, kaj venu sur la lokon, kiun elektos la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'Kaj oferfaru viajn bruloferojn, la viandon kaj la sangon, sur la altaro de la Eternulo, via Dio; sed la sango de viaj buĉoferoj estu elverŝata sur la altaron de la Eternulo, via Dio, kaj la viandon vi povas manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Observu kaj obeu ĉiujn ĉi tiujn vortojn, kiujn mi ordonas al vi, por ke estu bone al vi kaj al viaj idoj post vi eterne, se vi faros tion, kio estas bona kaj plaĉa antaŭ la okuloj de la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Kiam la Eternulo, via Dio, ekstermos de antaŭ vi la popolojn, al kiuj vi iras, por forpeli ilin, kaj vi forpelos ilin kaj ekloĝos en ilia lando:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'tiam gardu vin, ke vi ne enretiĝu per ili, post kiam ili estos ekstermitaj de antaŭ vi, kaj ke vi ne serĉu iliajn diojn, dirante: Kiel ĉi tiuj popoloj servis al siaj dioj, tiel mi ankaŭ faros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Ne agu tiel koncerne la Eternulon, vian Dion; ĉar ĉion, kion abomenas la Eternulo, kion Li malamas, ili faras por siaj dioj, kaj eĉ siajn filojn kaj filinojn ili forbruligas per fajro al siaj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Ĉion, kion mi ordonas al vi, tion observu, ke vi ĝin plenumu; ne aldonu al tio, kaj ne deprenu de tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Se aperos inter vi profeto aŭ sonĝisto kaj prezentos al vi signon aŭ miraklon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'kaj plenumiĝos la signo aŭ miraklo, pri kiu li parolis al vi, kaj li diros: Ni sekvu aliajn diojn, kiujn vi ne konas, kaj ni servu al ili:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'tiam ne aŭskultu la vortojn de tiu profeto aŭ de tiu sonĝisto, ĉar tiam elprovas vin la Eternulo, via Dio, por sciiĝi, ĉu vi amas la Eternulon, vian Dion, per via tuta koro kaj per via tuta animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'La Eternulon, vian Dion, sekvu, kaj Lin timu, kaj Liajn ordonojn observu, kaj Lian voĉon aŭskultu, kaj al Li servu, kaj al Li alteniĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Kaj tiun profeton aŭ tiun sonĝiston oni devas mortigi; ĉar li predikis defalon de la Eternulo, via Dio, kiu elkondukis vin el la lando Egipta kaj liberigis vin el la domo de sklaveco-por delogi vin de la vojo, laŭ kiu la Eternulo, via Dio, ordonis al vi iri; kaj ekstermu la malbonon el inter vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Se logos vin sekrete via frato, filo de via patrino, aŭ via filo, aŭ via filino, aŭ la edzino en viaj brakoj, aŭ via amiko plej intima, dirante: Ni iru kaj servu al aliaj dioj, kiujn ne konis vi nek viaj patroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'el la dioj de la popoloj, kiuj estas ĉirkaŭ vi, la proksimaj de vi aŭ la malproksimaj de vi, de unu fino de la lando ĝis la alia:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'tiam ne konsentu kun li kaj ne aŭskultu lin; ne indulgu lin via okulo, ne kompatu kaj ne kaŝu lin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'sed mortigu lin; via mano devas esti sur li la unua, por mortigi lin, kaj la manoj de la tuta popolo poste.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'Kaj ĵetu sur lin ŝtonojn, ke li mortu; ĉar li volis forlogi vin de la Eternulo, via Dio, kiu elkondukis vin el la lando Egipta, el la domo de sklaveco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'Kaj la tuta Izrael tion aŭdos kaj ektimos, kaj oni ne plu faros tian malbonan agon inter vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Se vi aŭdos pri iu el viaj urboj, kiujn la Eternulo, via Dio, donas al vi por loĝado, ke oni diras:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Eliris el inter vi homoj sentaŭgaj kaj forlogis la loĝantojn de sia urbo, dirante: Ni iru kaj servu al aliaj dioj, kiujn vi ne konis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'kaj vi serĉos kaj esploros kaj bone pridemandos; kaj montriĝos, ke tio estas preciza vero, ke la abomenaĵo estas farita inter vi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'tiam mortigu la loĝantojn de tiu urbo per glavo, detruu ĝin, kaj ĉion, kio estas en ĝi, kaj ankaŭ ĝiajn brutojn mortigu per glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'Kaj ĝian tutan havon kolektu sur la mezon de placo, kaj forbruligu per fajro la urbon kaj ĝian tutan havon, absolute ĉion, al la Eternulo, via Dio; kaj ĝi estu eterna ruino, oni neniam ĝin rekonstruu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Kaj nenio el la anatemaĵo algluiĝu al via mano, por ke la Eternulo forlasu Sian flaman koleron kaj donu al vi favorkorecon kaj indulgu vin kaj multigu vin, kiel Li ĵuris al viaj patroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'se vi aŭskultos la voĉon de la Eternulo, via Dio, observante ĉiujn Liajn ordonojn, kiujn mi ordonas al vi hodiaŭ, farante plaĉantaĵon antaŭ la okuloj de la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Vi estas filoj de la Eternulo, via Dio: ne faru sur vi entranĉojn kaj ne faru senharaĵon super viaj okuloj pro mortinto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'ĉar vi estas popolo sankta al la Eternulo, via Dio, kaj vin la Eternulo elektis, ke vi estu Lia popolo propra, el ĉiuj popoloj, kiuj estas sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Nenian abomenaĵon manĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Jen estas la brutoj, kiujn vi povas manĝi: bovo, ŝafo, kaj kapro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'cervo kaj gazelo kaj kapreolo kaj ibekso kaj antilopo kaj uro kaj tragelafo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'Ĉian bruton, kiu havas disfenditajn hufojn kaj distranĉan sulkon inter la du duonhufoj kaj kiu remaĉas maĉitaĵon, tian el la brutoj vi povas manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Nur ĉi tiujn ne manĝu el la remaĉantaj maĉitaĵon kaj el la havantaj disfenditajn hufojn kun distranĉa sulko: la kamelon kaj la leporon kaj la hirakon; ĉar ili remaĉas maĉitaĵon, sed iliaj hufoj ne estas disfenditaj, malpuraj ili estas por vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'kaj la porkon, ĉar ĝiaj hufoj estas disfenditaj, sed ĝi ne remaĉas maĉitaĵon, malpura ĝi estas por vi; ilian viandon ne manĝu, kaj ilian kadavron ne ektuŝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Ĉi tiujn vi povas manĝi el ĉiuj bestoj, kiuj estas en la akvo: ĉiujn, kiuj havas naĝilojn kaj skvamojn, vi povas manĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'sed ĉiujn, kiuj ne havas naĝilojn kaj skvamojn, ne manĝu: malpura tio estas por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Ĉian birdon puran vi povas manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Sed ĉi tiujn el ili ne manĝu: la aglon kaj la gipaeton kaj la pandionon');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'kaj la vulturon kaj la falkon kaj la milvon kun ĝia speco');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'kaj ĉian korvon kun ĝia speco');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'kaj la struton kaj la strigon kaj la mevon kaj la akcipitron kun ĝia speco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'la noktuon kaj la ibison kaj la cignon');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'kaj la pelikanon kaj la perknopteron kaj la mergulon');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'kaj la cikonion kaj la ardeon kun ĝia speco kaj la upupon kaj la vesperton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Kaj ĉia rampaĵo flugilhava estas por vi malpura; oni ne devas ilin manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Ĉian puran birdon vi povas manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Manĝu nenian kadavraĵon; al la fremdulo, kiu estas en via urbo, vi povas ĝin doni, ke li ĝin manĝu; aŭ vi povas vendi al alilandulo; ĉar vi estas popolo sankta al la Eternulo, via Dio. Ne kuiru kapridon en la lakto de ĝia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Apartigu dekonaĵon el ĉiuj produktaĵoj de via semado, kiuj venas de la kampo ĉiujare.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'Kaj manĝu antaŭ la Eternulo, via Dio, sur la loko, kiun Li elektos, por loĝigi tie Sian nomon, dekonaĵon el via greno, el via mosto, kaj el via oleo, kaj la unuenaskitojn el viaj grandaj kaj malgrandaj brutoj; por ke vi lernu timi ĉiam la Eternulon, vian Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Kaj se tro longa estos por vi la vojo kaj vi ne povos porti, ĉar tro malproksima estos de vi la loko, kiun elektos la Eternulo, via Dio, por meti tien Sian nomon, kaj la Eternulo, via Dio, vin benis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'tiam vi povas tion monigi, kaj vi prenos la monon en vian manon, kaj iros al la loko, kiun la Eternulo, via Dio, elektos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'kaj vi aĉetos pro tiu mono ĉion, kion ekdeziros via animo, el grandaj aŭ malgrandaj brutoj, el vino aŭ el drinkaĵo, aŭ el ĉio, kion postulos via animo; kaj vi manĝos tie antaŭ la Eternulo, via Dio, kaj vi estos gajaj, vi kaj via familio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Kaj la Levidon, kiu estas en via urbo, ne forlasu; ĉar li ne havas parton kaj heredaĵon ĉe vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Post paso de tri jaroj apartigu la tutan dekonaĵon de viaj produktaĵoj de tiu jaro kaj metu tion ĉe viaj pordegoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'kaj venos la Levido-ĉar li ne havas parton kaj heredaĵon ĉe vi- kaj la fremdulo kaj la orfo kaj la vidvino, kiuj estas en via urbo, kaj ili manĝos kaj satiĝos; por ke benu vin la Eternulo, via Dio, en ĉiu faro de viaj manoj, kiun vi faros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Post paso de sep jaroj faru forlason.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Jen estas la esenco de la forlaso: ĉiu kreditoro, kiu pruntedonis ion al sia proksimulo, forlasu tion, li ne postulu tion de sia proksimulo aŭ de sia frato; ĉar estas proklamita forlaso pro la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'De alilandulo vi povas postuli; sed kion vi havos ĉe via frato, tion via mano forlasu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Cetere ne estos ĉe vi malriĉulo (ĉar la Eternulo benos vin en la lando, kiun la Eternulo, via Dio, donas al vi kiel heredan posedaĵon),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'se vi nur obeos la voĉon de la Eternulo, via Dio, por observi kaj plenumi ĉiujn ĉi tiujn ordonojn, kiujn mi ordonas al vi hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Ĉar la Eternulo, via Dio, benos vin, kiel Li diris al vi; kaj vi pruntedonos al multaj popoloj, sed vi ne prunteprenos; kaj vi regos super multaj popoloj, sed super vi ili ne regos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Se estos inter vi malriĉulo iu el viaj fratoj en iu el viaj urboj en via lando, kiun la Eternulo, via Dio, donas al vi, tiam ne malmoligu vian koron kaj ne fermu vian manon antaŭ via frato, la malriĉulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'sed malfermu al li vian manon, kaj pruntedonu al li laŭmezure de lia manko, kio mankos al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Gardu vin, ke ne aperu en via koro malpia penso: Alproksimiĝas la sepa jaro, la jaro de forlaso; kaj via okulo fariĝos malfavora kontraŭ via malriĉa frato kaj vi ne donos al li, kaj li plendos pri vi al la Eternulo, kaj peko estos sur vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Donu al li, kaj ne ĉagrenu vin via koro, kiam vi donos al li; ĉar pro tio benos vin la Eternulo, via Dio, en ĉiuj viaj faroj kaj en ĉiu entrepreno de via mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Ĉar ne mankos malriĉuloj en la lando, tial mi ordonas al vi jene: malfermu vian manon al via frato, al via senhavulo, kaj al via malriĉulo en via lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Se vendos sin al vi via frato, Hebreo aŭ Hebreino, li servu vin dum ses jaroj, sed en la sepa jaro forsendu lin de vi en libereco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'Kaj kiam vi forsendos lin de vi en libereco, ne forsendu lin kun malplenaj manoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'sed havigu al li iom el viaj brutoj kaj el via garbejo kaj el via vinpremejo; per kio benis vin la Eternulo, via Dio, tion donu al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Memoru, ke vi estis sklavo en la lando Egipta, kaj la Eternulo, via Dio, liberigis vin; tial mi ordonas al vi tion hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Kaj se li diros al vi: Mi ne foriros de vi, ĉar mi amas vin kaj vian domon-ĉar estas al li bone ĉe vi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'tiam prenu alenon kaj enpiku en lian orelon kaj en la pordon, kaj li estos sklavo al vi por ĉiam. Ankaŭ kun via sklavino agu tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Tio ne ŝajnu al vi malfacila, kiam vi forsendos lin de vi en libereco; ĉar duoblan pagon de dungito li perlaboris ĉe vi dum ses jaroj; kaj la Eternulo, via Dio, benos vin en ĉio, kion vi faros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Ĉiun virseksan unuenaskiton, kiu naskiĝos al viaj grandaj kaj malgrandaj brutoj, dediĉu al la Eternulo, via Dio; ne laboru per la unuenaskito de via bovo, kaj ne tondu la unuenaskiton de via ŝafo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Antaŭ la Eternulo, via Dio, manĝu ĝin ĉiujare, sur la loko, kiun elektos la Eternulo, vi kaj via familio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'sed se ĝi havos ian difekton, se ĝi estos lama aŭ blinda, aŭ se ĝi havos kian ajn malbonan difekton, tiam ne buĉu ĝin ofere al la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'Sed inter viaj pordegoj vi povas ĝin manĝi, malpurulo kaj purulo egale, kiel gazelon kaj cervon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Nur ĝian sangon ne manĝu; sur la teron elverŝu ĝin, kiel akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Observu la monaton Abib, kaj faru Paskon al la Eternulo, via Dio; ĉar en la monato Abib elkondukis vin la Eternulo, via Dio, el Egiptujo en la nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Kaj buĉu Paskon al la Eternulo, via Dio, el grandaj kaj malgrandaj brutoj, sur la loko, kiun la Eternulo elektos, por loĝigi tie Sian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Ne manĝu kun tio fermentintaĵon; dum sep tagoj manĝu kun tio macojn, panon de mizero-ĉar rapidece vi eliris el la lando Egipta-por ke vi memoru dum la tuta tempo de via vivo la tagon de via eliro el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Oni ne vidu ĉe vi fermentintaĵon en via tuta limitaĵo dum sep tagoj; kaj el la viando, kiun vi oferbuĉos vespere en la unua tago, neniom restu ĝis la mateno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Vi ne povas buĉi la Paskon en iu el la urboj, kiujn la Eternulo, via Dio, donos al vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'nur sur la loko, kiun elektos la Eternulo, via Dio, por loĝigi tie Sian nomon, buĉu la Paskon vespere, ĉe la subiro de la suno-tempo de via eliro el Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Kaj kuiru kaj manĝu sur tiu loko, kiun elektos la Eternulo, via Dio; kaj en la sekvanta tago vi povas vin turni kaj iri al viaj tendoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Dum ses tagoj manĝu macojn, kaj en la sepa tago estu sankta kunveno antaŭ la Eternulo, via Dio; ne faru laboron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Sep semajnojn kalkulu al vi; de post la apero de la rikoltilo en la spikoj komencu kalkuli la sep semajnojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Kaj faru feston de semajnoj al la Eternulo, via Dio, kun libervola dono el via mano, kiun vi donos konforme al tio, kiom benis vin la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'Kaj estu gajaj antaŭ la Eternulo, via Dio, vi kaj via filo kaj via filino kaj via servanto kaj via servantino, kaj la Levido, kiu estas en viaj pordegoj, kaj la fremdulo kaj la orfo kaj la vidvino, kiuj estas inter vi, sur la loko, kiun elektos la Eternulo, via Dio, por loĝigi tie Sian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Kaj memoru, ke vi estis sklavo en Egiptujo; kaj observu kaj plenumu ĉi tiujn leĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Feston de laŭboj faru al vi dum sep tagoj, kiam vi kolektos el via draŝejo kaj el via vinpremejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'Kaj estu gajaj en via festo, vi kaj via filo kaj via filino kaj via servanto kaj via servantino, kaj la Levido kaj la fremdulo kaj la orfo kaj la vidvino, kiuj estas inter viaj pordegoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Dum sep tagoj festu al la Eternulo, via Dio, sur la loko, kiun elektos la Eternulo; ĉar benos vin la Eternulo, via Dio, en ĉiuj viaj produktaĵoj kaj en ĉiuj faroj de viaj manoj, kaj vi estos tute gaja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Tri fojojn en la jaro ĉiu via virseksulo devas aperi antaŭ la Eternulo, via Dio, sur la loko, kiun Li elektos: en la festo de macoj kaj en la festo de semajnoj kaj en la festo de laŭboj; kaj li ne aperu antaŭ la Eternulo kun malplenaj manoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'ĉiu kun donaco en sia mano, konforme al la beno de la Eternulo, via Dio, kiun Li donis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Juĝistojn kaj kontrolistojn starigu al vi en ĉiuj viaj urboj, kiujn la Eternulo, via Dio, donos al vi laŭ viaj triboj; kaj ili juĝu la popolon per juĝo justa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Ne klinu la leĝon, ne atentu personojn; kaj ne prenu subaĉeton, ĉar subaĉeto blindigas la okulojn de saĝuloj kaj konfuzas la aferojn de justuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Justecon, justecon sekvu, por ke vi vivu kaj posedu la landon, kiun la Eternulo, via Dio, donas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Ne plantu al vi sanktan stangon el ia arbo apud la altaro de la Eternulo, via Dio, kiun vi faros al vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'kaj ne starigu al vi statuon, kion malamas la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Ne oferbuĉu al la Eternulo, via Dio, bovon aŭ ŝafon, kiu havas sur si difekton, kian ajn malbonaĵon; ĉar tio estas abomenaĵo por la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Se troviĝos inter vi en iu el viaj urboj, kiujn la Eternulo, via Dio, donas al vi, viro aŭ virino, kiu faras malbonon antaŭ la Eternulo, via Dio, malobeante Lian interligon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'kaj li iros kaj servos al aliaj dioj, kaj adorkliniĝos antaŭ ili aŭ antaŭ la suno aŭ antaŭ la luno aŭ antaŭ la tuta armeo de la ĉielo, kion mi ne ordonis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'kaj estos dirite al vi, kaj vi aŭdos kaj bone esploros, kaj montriĝos, ke la afero estas preciza vero, ke tiu abomenaĵo estas farita en Izrael:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'tiam elkonduku tiun viron aŭ tiun virinon, kiuj faris tiun malbonan aferon, al via pordego, la viron aŭ la virinon, kaj ĵetu sur ilin ŝtonojn, ke ili mortu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Laŭ la akuzo de du atestantoj aŭ tri atestantoj la mortigoto estu ekzekutita; li ne estu mortigita laŭ la akuzo de unu atestanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'La mano de la atestantoj estu sur li plej antaŭe, por mortigi lin, kaj la mano de la tuta popolo poste; tiel ekstermu la malbonon el inter vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Se estos por vi tro malfacila ia juĝa afero inter sango kaj sango, inter proceso kaj proceso, inter frapo kaj frapo, en disputaj aferoj en via urbo: tiam leviĝu, kaj iru al la loko, kiun elektos la Eternulo, via Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'kaj venu al la pastroj Levidoj, kaj al la juĝisto, kiu estos en tiu tempo, kaj demandu, kaj ili diros al vi la juĝan decidon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Kaj agu laŭ la vorto, kiun ili diros al vi de tiu loko, kiun la Eternulo elektos; kaj observu, ke vi faru ĉion, kion ili instruos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Laŭ la instruo, kiun ili donos al vi, kaj laŭ la decido, kiun ili diros al vi, agu; de tio, kion ili diros al vi, ne dekliniĝu dekstren nek maldekstren.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Kiu agos arogante, kaj ne obeos la pastron, kiu staras tie, por servi al la Eternulo, via Dio, aŭ la juĝiston, tiu homo devas morti; kaj vi ekstermos la malbonon el Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'Kaj la tuta popolo aŭdos kaj ektimos, kaj ili ne plu agos arogante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Kiam vi venos en la landon, kiun la Eternulo, via Dio, donas al vi, kaj vi ekposedos ĝin kaj ekloĝos en ĝi, kaj diros: Mi starigos super mi reĝon, kiel ĉiuj popoloj ĉirkaŭ mi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'tiam starigu super vi reĝon, kiun elektos la Eternulo, via Dio; el inter viaj fratoj starigu super vi reĝon; vi ne povas starigi super vi homon aligentan, kiu ne estas via frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Sed li ne multigu al si ĉevalojn, kaj li ne revenigu la popolon en Egiptujon, por multigi ĉevalojn; la Eternulo diris al vi: Ne iru plu returne laŭ tiu vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Kaj li ne multigu al si edzinojn, por ke ne dekliniĝu lia koro; kaj arĝenton kaj oron li ne tro multigu al si.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Sed kiam li sidiĝos sur la trono de sia regno, li transskribu al si kopion de ĉi tiu instruo en libron laŭ tio, kio troviĝas ĉe la pastroj Levidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'kaj ĝi estu ĉe li, kaj li legadu en ĝi dum sia tuta vivo, por ke li lernu timi la Eternulon, sian Dion, observante ĉiujn vortojn de ĉi tiu instruo kaj ĉi tiujn leĝojn, por plenumi ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'por ke ne altiĝu lia koro super liaj fratoj kaj por ke li ne dekliniĝu de la ordono dekstren nek maldekstren, por ke li restu longe en sia reĝeco, li kaj liaj filoj, inter Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Ne havos la pastroj Levidoj, la tuta tribo de Levi, parton kaj heredaĵon kun Izrael: la fajroferojn de la Eternulo kaj Lian apartenaĵon ili manĝados.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Heredaĵon ili ne havos inter siaj fratoj: la Eternulo estas ilia heredaĵo, kiel Li diris al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Jen estas tio, kion devas doni al la pastroj la popolo, la oferbuĉantoj de bovo aŭ ŝafo: oni donu al la pastro la ŝultron kaj la makzelojn kaj la stomakon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'la unuaaĵon de via greno, de via mosto, kaj de via oleo, kaj la unuaaĵon de la tonditaĵo de viaj ŝafoj donu al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Ĉar lin elektis la Eternulo, via Dio, el ĉiuj viaj triboj, ke li staru kaj servu en la nomo de la Eternulo, li kaj liaj filoj en ĉiu tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Kaj se venos Levido el iu el viaj urboj, el la tuta Izrael, kie li loĝas, kaj li venos pro la tuta deziro de sia animo al la loko, kiun elektos la Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'kaj li servos en la nomo de la Eternulo, lia Dio, kiel ĉiuj liaj fratoj, la Levidoj, kiuj staras tie antaŭ la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'tiam ili manĝu egalajn partojn, krom tio, kion donas al li la vendo de la patra havo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Kiam vi venos en la landon, kiun la Eternulo, via Dio, donas al vi, tiam ne lernu fari ion similan al la abomenaĵoj de tiuj popoloj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'ne devas troviĝi inter vi iu, kiu trairigas sian filon aŭ filinon tra fajro, aŭguristo, antaŭdiristo, magiisto, sorĉisto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'nek subĵurigisto, nek elvokisto de spiritoj, nek signoklarigisto, nek esploristo de mortintoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'ĉar abomenaĵo por la Eternulo estas ĉiu, kiu faras tion, kaj pro tiuj abomenaĵoj la Eternulo, via Dio, forpelas ilin de antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Senmakula estu antaŭ la Eternulo, via Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'ĉar tiuj popoloj, kiujn vi forpelas, aŭskultas antaŭdiristojn kaj aŭguristojn; sed al vi ne tion donis la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Profeton al via mezo, el viaj fratoj, similan al mi, starigos por vi la Eternulo, via Dio; lin aŭskultu,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'konforme al tio, kion vi petis de la Eternulo, via Dio, ĉe Ĥoreb en la tago de la kunveno, dirante: Mi ne aŭdu plu la voĉon de la Eternulo, mia Dio, kaj ĉi tiun grandan fajron mi ne vidu plu, por ke mi ne mortu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Kaj la Eternulo diris al mi: Bona estas tio, kion ili diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Profeton Mi starigos por ili el la mezo de iliaj fratoj, similan al vi; kaj Mi metos Miajn vortojn en lian buŝon, kaj li parolos al ili ĉion, kion Mi ordonos al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Kaj se iu homo ne aŭskultos Miajn vortojn, kiujn li parolos en Mia nomo, tiun Mi punos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Sed profeton, kiu arogos diri en Mia nomo ion, kion Mi ne ordonis al li diri, aŭ kiu parolos en la nomo de aliaj dioj, tiun profeton oni mortigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Kaj se vi diros en via koro: Kiel ni ekkonos la vorton, kiun ne diris la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'Kion la profeto diros en la nomo de la Eternulo kaj la afero ne fariĝos kaj ne plenumiĝos-tio estas la vortoj, kiujn la Eternulo ne diris; pro aroganteco diris tion la profeto; ne timu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Kiam la Eternulo, via Dio, ekstermos la popolojn, kies landon la Eternulo, via Dio, donas al vi, kaj vi forpelos ilin kaj ekloĝos en iliaj urboj kaj en iliaj domoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'tiam apartigu el vi tri urbojn en via lando, kiun la Eternulo, via Dio, donas al vi kiel posedaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Aranĝu al vi la vojon, kaj dividu en tri partojn la spacon de via lando, kiun havigos al vi la Eternulo, via Dio; kaj ili estos por tio, ke tien forkuru ĉiu mortiginto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Kaj jen estas la afero pri mortiginto, kiu povas forkuri tien kaj resti vivanta: se iu mortigos sian proksimulon senintence, ne estinte lia malamiko antaŭe;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'aŭ se iu iros kun sia proksimulo en arbaron, por haki lignon, kaj eksvingiĝos lia mano kun la hakilo, por haki la arbon, kaj la fero desaltos de la tenilo kaj trafos la proksimulon kaj tiu mortos-li forkuru al unu el tiuj urboj, por resti vivanta;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'por ke ne postkuru la sangovenĝanto la mortiginton, kiam ekflamos lia koro, kaj ne kuratingu lin, se la vojo estos longa, kaj ne mortigu lin; ĉar li ne meritas morton, ĉar li ne estis lia malamiko antaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Tial mi ordonas al vi, dirante: Tri urbojn apartigu al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Kaj kiam la Eternulo, via Dio, plilarĝigos viajn limojn, kiel Li ĵuris al viaj patroj, kaj donos al vi la tutan landon, kiun Li promesis doni al viaj patroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'se ĉiujn ĉi tiujn ordonojn, kiujn mi donas al vi hodiaŭ, vi observos kaj plenumos, amante la Eternulon, vian Dion, kaj irante laŭ Liaj vojoj en ĉiu tempo: tiam aldonu al vi ankoraŭ tri urbojn krom tiuj tri;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'por ke ne estu verŝata senkulpa sango meze de via lando, kiun la Eternulo, via Dio, donas al vi kiel posedaĵon, kaj por ke vi ne estu kulpa pri sango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Sed se iu estos malamiko al sia proksimulo kaj insidos lin kaj leviĝos kontraŭ lin kaj mortigos lin kaj forkuros al unu el tiuj urboj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'tiam la plejaĝuloj en lia urbo sendu kaj prenigu lin el tie kaj transdonu lin en la manon de la sangovenĝanto, por ke li mortu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Via okulo ne indulgu lin; forviŝu la sangon de senkulpulo el Izrael, kaj estos al vi bone.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Ne forŝovu la limon de via proksimulo, kiun difinis la antaŭuloj en via posedaĵo, kiun vi ricevos en la lando, kiun la Eternulo, via Dio, donas al vi kiel posedaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Ne valoras unu atestanto kontraŭ homo en ĉia kulpo, en ĉia krimo, kaj en ĉia peko, kiun li pekos: laŭ la diro de du atestantoj aŭ laŭ la diro de tri atestantoj oni povas fari proceson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Se kontraŭ iu stariĝos atestanto maljusta, akuzante lin pri krimo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'tiam la du homoj, kiuj havas inter si juĝan disputon, stariĝu antaŭ la Eternulo, antaŭ la pastroj kaj la juĝistoj, kiuj estos en tiu tempo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'kaj la juĝistoj bone esploru; kaj se montriĝos, ke la atestanto estas atestanto malvera, ke li akuzis malvere sian fraton:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'tiam agu kun li tiel, kiel li intencis agi kun sia frato; kaj tiel ekstermu la malbonon el inter vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Kaj la aliaj aŭdos kaj ektimos, kaj ili ne faros plu tian malbonon inter vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Kaj via okulo ne indulgu: animon pro animo, okulon pro okulo, denton pro dento, manon pro mano, piedon pro piedo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Kiam vi iros milite kontraŭ vian malamikon kaj vi vidos ĉevalojn kaj ĉarojn kaj pli multe da homoj ol ĉe vi, ne timu ilin; ĉar kun vi estas la Eternulo, via Dio, kiu elkondukis vin el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'Kaj kiam vi alproksimiĝos al la batalo, tiam elpaŝu la pastro kaj parolu al la popolo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'kaj li diru al ili: Aŭdu, ho Izrael! vi iras nun en batalon kontraŭ viajn malamikojn; ne malfortiĝu via koro, ne timu, ne konfuziĝu, kaj ne tremu antaŭ ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'ĉar la Eternulo, via Dio, iras kun vi, por batali pro vi kontraŭ viaj malamikoj kaj por helpi vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Kaj la kontrolistoj parolu al la popolo, dirante: Kiu konstruis novan domon kaj ne inaŭguris ĝin, tiu iru kaj revenu al sia domo, ĉar eble li mortos en la batalo kaj alia homo ĝin inaŭguros;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'kaj kiu plantis vinberĝardenon kaj ne ĝuis ĝiajn fruktojn, tiu iru kaj revenu al sia domo, ĉar eble li mortos en la batalo kaj alia homo ĝuos ĝiajn fruktojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'kaj kiu fianĉiĝis kun virino kaj ne prenis ŝin, tiu iru kaj revenu al sia domo, ĉar eble li mortos en la batalo kaj alia viro ŝin prenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Kaj plue la kontrolistoj parolu al la popolo, kaj diru: Kiu estas timema kaj senkuraĝa, tiu iru kaj revenu al sia domo, por ke li ne senkuraĝigu la koron de siaj fratoj, kiel lia koro estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Kaj kiam la kontrolistoj finos paroli al la popolo, tiam oni starigu militestrojn super la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Kiam vi aliros al urbo, por batali kontraŭ ĝi, tiam proponu al ĝi pacon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Kaj se ĝi respondos al vi per paco kaj malfermos sin antaŭ vi, tiam la tuta popolo, kiu troviĝos en ĝi, pagu al vi tributon kaj servu vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Sed se ĝi ne faros pacon kun vi, sed militos kontraŭ vi, tiam sieĝu ĝin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'kaj kiam la Eternulo, via Dio, transdonos ĝin en vian manon, tiam mortigu ĉiujn ĝiajn virseksulojn per glavo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'nur la virinojn kaj la infanojn kaj la brutojn, kaj ĉion, kio estos en la urbo, la tutan militakiraĵon prenu al vi, kaj konsumu la militakiraĵon de viaj malamikoj, kiujn la Eternulo, via Dio, transdonis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Tiel agu kun ĉiuj urboj, kiuj estas tre malproksime de vi kaj kiuj ne apartenas al la urboj de tiuj popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Sed al tiuj urboj de tiuj popoloj, kiujn la Eternulo, via Dio, donas al vi kiel posedaĵon, lasu la vivon al neniu animo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'sed ekstermu ilin: la Ĥetidojn kaj la Amoridojn, la Kanaanidojn kaj la Perizidojn, la Ĥividojn kaj la Jebusidojn, kiel ordonis al vi la Eternulo, via Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'por ke ili ne instruu al vi fari simile al ĉiuj iliaj abomenaĵoj, kiujn ili faris por siaj dioj, kaj por ke vi ne peku antaŭ la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Se vi dum longa tempo sieĝos urbon, por militakiri ĝin kaj preni ĝin, ne ruinigu ĝiajn arbojn, levante kontraŭ ilin hakilon; ĉar vi povas manĝi fruktojn de ili, tial ne forhaku ilin; ĉar ĉu arbo de kampo estas homo, ke ĝi povus foriri de vi en la fortikaĵon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Nur tian arbon, pri kiu vi scios, ke ĝi ne estas arbo fruktodona, vi povas ruinigi kaj forhaki, por konstrui bastionojn kontraŭ la urbo, kiu militas kontraŭ vi, ĝis vi ĝin venkos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Se estos trovita mortigito sur la tero, kiun la Eternulo, via Dio, donas al vi kiel posedaĵon, kuŝanta sur la kampo, kaj oni ne scios, kiu lin mortigis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'tiam eliru viaj plejaĝuloj kaj viaj juĝistoj, kaj ili mezuru ĝis la urboj, kiuj troviĝas ĉirkaŭe de la mortigito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Kaj kiu urbo estos plej proksime de la mortigito, ties plejaĝuloj prenu bovidinon, per kiu oni ne laboris kaj kiu ne portis jugon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'kaj la plejaĝuloj de tiu urbo forkonduku la bovidinon al valo kun fluanta akvo, valo, kiu ne estas plugita nek prisemita, kaj ili rompu tie la kolon de la bovidino en la valo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'kaj aliru la pastroj, idoj de Levi (ĉar ilin elektis la Eternulo, via Dio, por servi al Li kaj por beni en la nomo de la Eternulo, kaj laŭ ilia diro devas esti decidata ĉiu disputo kaj ĉiu difekto);');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'kaj ĉiuj plejaĝuloj de tiu urbo, kiuj estos la plej proksimaj de la mortigito, lavu siajn manojn super la bovidino, al kiu oni rompis la kolon en la valo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'kaj ili sciigu kaj diru: Niaj manoj ne verŝis ĉi tiun sangon, kaj niaj okuloj ne vidis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'pekliberigu Vian popolon Izrael, kiun Vi liberigis, ho Eternulo, kaj ne kalkulu sangon senkulpan inter Via popolo Izrael. Kaj estos pardonita al ili la sango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Kaj vi elviŝu el inter vi la sangon de senkulpulo, por ke vi faru plaĉantaĵon antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Kiam vi eliros en militon kontraŭ viajn malamikojn, kaj la Eternulo, via Dio, transdonos ilin en viajn manojn, kaj vi prenos de ili kaptitojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'kaj vi vidos inter la kaptitoj virinon belaspektan kaj ekamos ŝin kaj prenos ŝin al vi kiel edzinon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'tiam venigu ŝin internen de via domo, kaj ŝi pritondu sian kapon kaj pritranĉu siajn ungojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'kaj ŝi deprenu de si siajn vestojn de kaptiteco, kaj ŝi loĝu en via domo, kaj ŝi priploru sian patron kaj sian patrinon en la daŭro de unu monato; kaj post tio vi povas eniri al ŝi kaj fariĝi ŝia edzo, kaj ŝi estos por vi edzino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Kaj se ŝi ne plaĉos al vi, tiam forliberigu ŝin, kien ŝi volas; sed ne vendu ŝin pro mono, ne premu ŝin per via forto, pro tio, ke vi humiligis ŝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Se viro havos du edzinojn, unu amatan kaj duan ne amatan, kaj ili naskos al li filojn, la amata kaj la ne amata, kaj la filo unuenaskita estos de la ne amata:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'tiam ĉe la disdono de sia havo al la filoj li ne povas doni unuaecon al la filo de la amata antaŭ la filo de la ne amata, la unuenaskito;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'sed la unuenaskiton, la filon de la ne amata, li devas estkonfesi, por doni al li duoblan parton el ĉio, kio troviĝas ĉe li; ĉar li estas la unua frukto de lia forto, li havas la rajton de unuenaskiteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Se iu havos filon obstinan kaj malobean, kiu ne aŭskultas la voĉon de sia patro nek la voĉon de sia patrino, kaj ili punadis lin, sed li ne aŭskultas ilin:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'tiam lia patro kaj lia patrino prenu lin kaj alkonduku lin al la plejaĝuloj de lia urbo kaj al la pordego de lia loĝoloko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'kaj ili diru al la plejaĝuloj de lia urbo: Ĉi tiu nia filo estas obstina kaj malobea, li ne aŭskultas nian voĉon, li estas manĝegemulo kaj drinkemulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Tiam ĉiuj homoj de lia urbo priĵetu lin per ŝtonoj, ke li mortu; tiel ekstermu la malbonon el inter vi, kaj ĉiuj Izraelidoj aŭdos kaj ektimos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Se iu fariĝos kulpa pri peko, kiu meritas morton, kaj li estos mortigita kaj vi pendigos lin sur arbo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'tiam lia kadavro ne devas resti dum la nokto sur la arbo, sed vi devas lin enterigi en la sama tago; ĉar pendigito estas malbenita antaŭ Dio; kaj ne makulu vian teron, kiun la Eternulo, via Dio, donas al vi kiel posedaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Kiam vi vidos, ke bovo de via frato aŭ lia ŝafo erarvagas, ne forturnu vin de ili, sed rekonduku ilin al via frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Se via frato ne estas proksime de vi aŭ se vi lin ne konas, tiam enpelu ilin en vian domon, kaj ili estu ĉe vi, ĝis via frato ilin serĉos, kaj tiam redonu ilin al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Tiel same agu kun lia azeno, tiel same agu kun lia vesto, kaj tiel same agu kun ĉia perditaĵo de via frato, kun ĉio, kio estos perdita de li kaj kion vi trovos: vi ne devas forturni vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Kiam vi vidos, ke azeno de via frato aŭ lia bovo falis sur la vojo, ne forturnu vin de ili; levu ilin kune kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Ne devas esti apartenaĵo de viro sur virino, kaj viro ne surmetu sur sin veston de virino; ĉar abomenaĵo por la Eternulo, via Dio, estas ĉiu, kiu faras tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Se vi trovos neston de birdo antaŭ vi sur la vojo, sur iu arbo aŭ sur la tero, kun birdidoj aŭ kun ovoj, kaj la patrino sidas sur la birdidoj aŭ sur la ovoj, ne prenu la patrinon kune kun la idoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'la patrinon forliberigu, kaj la idojn vi povas preni al vi; por ke estu al vi bone kaj por ke vi longe vivu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Kiam vi konstruos novan domon, faru balustradon ĉirkaŭ via tegmento, por ke vi ne venigu sangon sur vian domon, se iu defalos de ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Ne prisemu vian vinberĝardenon per miksospecaj semoj, por ke ne malbeniĝu la tuta rikolto, la semo, kiun vi semis, kaj la fruktoj de la vinberĝardeno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Ne plugu per bovo kaj azeno kune.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Ne surmetu sur vin miksospecan veston el lano kaj lino kune.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Kvastojn faru al vi sur la kvar anguloj de via kovrilo, per kiu vi vin kovras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Se iu prenos edzinon kaj envenos al ŝi kaj ekmalamos ŝin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'kaj li akuzos ŝin kalumnie kaj kurigos pri ŝi malbonon famon, kaj diros: Ĉi tiun virinon mi prenis, kaj mi alproksimiĝis al ŝi kaj ne trovis ĉe ŝi virgecon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'tiam la patro de la junulino kaj ŝia patrino prenu kaj elportu la signojn de virgeco de la junulino al la plejaĝuloj de la urbo al la pordego;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'kaj la patro de la junulino diru al la plejaĝuloj: Mian filinon mi donis al ĉi tiu viro kiel edzinon, kaj li ekmalamis ŝin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'kaj jen li akuzis ŝin kalumnie, dirante: Mi ne trovis ĉe via filino virgecon; sed jen estas la signoj de virgeco de mia filino. Kaj ili etendos la veston antaŭ la plejaĝuloj de la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Tiam la plejaĝuloj de tiu urbo prenu la edzon kaj punu lin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'kaj ili kondamnu lin al punpago de cent arĝentaj moneroj, kaj ili donu tion al la patro de la junulino pro tio, ke tiu kurigis malbonan famon pri junulino Izraelida; kaj ŝi restu lia edzino, li ne povas forigi ŝin de si dum sia tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Sed se tiu afero estos vera kaj ne troviĝos signoj de virgeco ĉe la junulino:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'tiam oni alkonduku la junulinon al la pordo de ŝia patro, kaj la loĝantoj de ŝia urbo priĵetu ŝin per ŝtonoj, ke ŝi mortu; ĉar ŝi faris malhonoraĵon en Izrael, malĉastante en la domo de sia patro. Tiel ekstermu la malbonon el inter vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Se estos trovita viro, kuŝanta kun virino edzinigita, tiam oni mortigu ambaŭ, la viron, kiu kuŝis kun la virino, kaj la virinon. Tiel ekstermu la malbonon el Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Se juna virgulino estos fianĉigita kun viro, kaj iu renkontos ŝin en la urbo kaj kuŝos kun ŝi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'tiam konduku ilin ambaŭ al la pordego de tiu urbo, kaj priĵetu ilin per ŝtonoj, ke ili mortu; la junulinon pro tio, ke ŝi ne kriis en la urbo, kaj la viron pro tio, ke li senhonorigis la edzinon de sia proksimulo. Tiel ekstermu la malbonon el inter vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Sed se sur kampo renkontos la viro la fianĉigitan junulinon, kaj la viro ŝin kaptos kaj kuŝos kun ŝi: tiam oni mortigu sole la viron, kiu kuŝis kun ŝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'sed al la junulino faru nenion; la junulino ne havas mortomeritan pekon, ĉar tiu afero estas tia, kiel se iu leviĝas kontraŭ sian proksimulon kaj mortigas lin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'li renkontis ja ŝin sur kampo, la fianĉigita junulino eble kriis, sed neniu ŝin savis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Se iu renkontos junulinon virgulinon ne fianĉigitan kaj kaptos ŝin kaj kuŝos kun ŝi, kaj oni ilin trovos:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'tiam la viro, kiu kuŝis kun ŝi, donu al la patro de la junulino kvindek arĝentajn monerojn, kaj ŝi fariĝu lia edzino, pro tio, ke li senhonorigis ŝin; li ne povas forigi ŝin de si dum sia tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Neniu prenu la edzinon de sia patro, nek malkovru la baskon de sia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Kiu havas dispremitajn testikojn aŭ detranĉitan seksan membron, tiu ne povas eniri en la komunumon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Peknaskito ne povas eniri en la komunumon de la Eternulo; eĉ lia deka generacio ne povas eniri en la komunumon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Amonido kaj Moabido ne povas eniri en la komunumon de la Eternulo; eĉ ilia deka generacio ne povas eniri en la komunumon de la Eternulo eterne;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'pro tio, ke ili ne renkontis vin kun pano kaj akvo sur la vojo, kiam vi iris el Egiptujo, kaj ke ili dungis kontraŭ vi Bileamon, filon de Beor, el Petor en Mezopotamio, por malbeni vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'Sed la Eternulo, via Dio, ne volis aŭskulti Bileamon; kaj la Eternulo, via Dio, turnis por vi la malbenon en benon, ĉar la Eternulo, via Dio, amas vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Ne faru al ili pacon nek bonon dum via tuta ekzistado eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Ne abomenu Edomidon, ĉar li estas via frato; ne abomenu Egipton, ĉar vi estis fremdulo en lia lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'La infanoj, kiuj naskiĝos de ili, en la tria generacio povas eniri en la komunumon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Kiam vi eliros tendare kontraŭ viajn malamikojn, tiam gardu vin kontraŭ ĉio malbona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Se estos inter vi iu, kiu ne estos pura pro okazintaĵo nokta, li eliru ekster la tendaron, li ne venu internen de la tendaro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'kiam fariĝos vespero, li lavu sin per akvo, kaj post la subiro de la suno li povas veni en la tendaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Lokon vi devas havi ekster la tendaro, kien vi elirados por necesaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Fosileton vi devas havi ĉe vi sur rimeno; kaj kiam vi sidos ekstere, fosu per ĝi kaj reen kovru vian elirintaĵon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'ĉar la Eternulo, via Dio, iras meze de via tendaro, por savi vin kaj por transdoni al vi viajn malamikojn; tial via tendaro devas esti sankta, por ke Li ne vidu inter vi ion hontindan kaj ne deturniĝu de vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Ne transdonu sklavon al lia sinjoro, se li serĉos rifuĝon ĉe vi kontraŭ sia sinjoro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'kun vi li loĝu, inter vi, sur la loko, kiun li elektos en unu el viaj urboj, kie plaĉos al li; ne premu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Ne devas esti malĉastistino inter la filinoj de Izrael, kaj ne devas esti malĉastisto inter la filoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Ne enportu pagon de malĉastistino nek de malĉastisto en la domon de la Eternulo, via Dio, pro ia promeso; ĉar ambaŭ estas abomenaĵo antaŭ la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Ne donu kreskige al via frato monon, nek manĝaĵon, nek ion alian, kion oni povas doni kreskige.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Al alilandulo vi povas doni kreskige, sed al via frato ne donu kreskige; por ke la Eternulo, via Dio, benu vin en ĉiu entrepreno de viaj manoj sur la tero, sur kiun vi venas, por ekposedi ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Se vi faros promeson al la Eternulo, via Dio, ne prokrastu plenumi ĝin; ĉar la Eternulo, via Dio, postulos ĝin de vi, kaj estos sur vi peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Sed se vi ne faros promeson, ne estos sur vi peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Kio eliris el via buŝo, tion observu kaj plenumu, kiel vi promesis al la Eternulo, via Dio, propravole, kion vi diris per via buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Kiam vi eniros en vinberĝardenon de via proksimulo, vi povas manĝi vinberojn kiom vi volos, ĝissate; sed en vian vazon ne metu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Kiam vi venos sur la grenkampon de via proksimulo, vi povas deŝiri spikojn per viaj manoj; sed rikoltilon ne levu kontraŭ la grenkampon de via proksimulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Se iu prenos virinon kaj fariĝos ŝia edzo, kaj okazos, ke ŝi ne plaĉas al li, ĉar li trovis ĉe ŝi ion hontindan: tiam li skribu al ŝi eksedzigan leteron kaj donu ĝin en ŝian manon kaj forsendu ŝin el sia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'Kaj se ŝi eliros el lia domo kaj iros kaj edziniĝos kun alia viro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'kaj tiu lasta edzo ŝin ekmalamos kaj skribos al ŝi eksedzigan leteron kaj donos en ŝian manon kaj forsendos ŝin el sia domo; aŭ mortos tiu lasta viro, kiu prenis ŝin kiel edzinon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'tiam ŝia unua edzo, kiu forsendis ŝin, ne povas preni ŝin denove kiel edzinon, post kiam ŝi estas malpurigita; ĉar tio estas abomenaĵo antaŭ la Eternulo; kaj vi ne pekmakulu la teron, kiun la Eternulo, via Dio, donas al vi kiel heredaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Se iu antaŭ nelonge edziĝis, li ne iru en militon, kaj oni nenion metu sur lin; li restu libera en sia domo dum unu jaro, kaj li gajigu sian edzinon, kiun li prenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Neniu prenu kiel garantiaĵon muelilon aŭ supran muelŝtonon, ĉar tiam li prenus garantiaĵe animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Se oni trovos iun, kiu ŝtelis iun el siaj fratoj, el la Izraelidoj, kaj sklavigis lin kaj vendis lin, tiu ŝtelinto devas morti; kaj tiel ekstermu la malbonon el inter vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Atentu pri la infekto de lepro, ke vi observu precize kaj plenumu ĉion, kion instruos al vi la pastroj Levidoj; kiel mi ordonis al ili, tiel penu agi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Memoru, kion la Eternulo, via Dio, faris al Mirjam sur la vojo, kiam vi iris el Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Se vi ion pruntedonos al via proksimulo, ne iru en lian domon, por preni de li garantiaĵon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'staru sur la strato; kaj la homo, al kiu vi pruntedonis, elportos al vi la garantiaĵon eksteren.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Kaj se li estas malriĉulo, tiam ne dormu kun lia garantiaĵo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'redonu al li la garantiaĵon ĉe la subiro de la suno, por ke li kuŝu en sia vesto kaj benu vin; kaj vi havos meriton antaŭ la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Ne faru maljustaĵon al dungito, al malriĉulo kaj senhavulo el viaj fratoj aŭ el viaj fremduloj, kiuj loĝas en via lando, en viaj urboj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'en la sama tago donu al li lian pagon, ke la suno ne subiru super ĝi, ĉar li estas malriĉa kaj per tio li subtenas sian vivon; ke li ne plendu kontraŭ vi al la Eternulo kaj vi ne havu sur vi pekon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Patrojn oni ne mortigu pro la gefiloj, kaj gefilojn oni ne mortigu pro la patroj: ĉiu devas ricevi morton pro sia krimo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Ne juĝu malĝuste fremdulon, orfon, kaj ne prenu garantiaĵe veston de vidvino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Kaj memoru, ke vi estis sklavo en Egiptujo, kaj la Eternulo, via Dio, liberigis vin el tie; tial mi ordonas al vi, ke vi agu tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Kiam vi rikoltos vian rikolton sur via kampo kaj vi forgesos garbon sur la kampo, ne iru returne por preni ĝin: ĝi restu por la fremdulo, por la orfo, kaj por la vidvino; por ke la Eternulo, via Dio, benu vin en ĉiuj faroj de viaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Kiam vi debatos la fruktojn de via olivarbo, ne debatu ĝis fino: io restu por la fremdulo, por la orfo, kaj por la vidvino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Kiam vi rikoltos en via vinberejo, ne forkolektu la restaĵon post vi: io restu por la fremdulo, por la orfo, kaj por la vidvino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Kaj memoru, ke vi estis sklavo en la lando Egipta; pro tio mi ordonas al vi agi tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Se estos disputo inter homoj, ili venu al la juĝo, kaj oni juĝu ilin, kaj oni deklaru prava la pravulon, kaj la malpravulon oni kondamnu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Kaj se la kulpulo meritas batojn, tiam la juĝisto ordonu kuŝigi lin kaj bati lin antaŭ li laŭ la grado de lia kulpeco, laŭ kalkulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Kvardek batojn oni povas doni al li, sed ne pli; oni ne batu lin tro multe, por ke via frato ne estu humiligita antaŭ viaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Ne fermu la buŝon al bovo draŝanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Se fratoj loĝas kune, kaj unu el ili mortas, ne havante filon, tiam la edzino de la mortinto ne devas edziniĝi ekstere kun viro fremda; sed ŝia bofrato venu al ŝi kaj prenu ŝin al si kiel edzinon kaj vivu kun ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'Kaj la unuenaskito, kiun ŝi naskos, ricevos la nomon de lia mortinta frato, por ke ne malaperu lia nomo en Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Sed se tiu viro ne deziros preni sian bofratinon, tiam lia bofratino devas iri al la pordego, al la plejaĝuloj, kaj diri: Mia bofrato rifuzas restarigi al sia frato nomon en Izrael, li ne volas edziĝi kun mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Tiam la plejaĝuloj de lia urbo devas voki lin kaj admoni lin. Kaj se li stariĝos, kaj diros: Mi ne volas preni ŝin:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'tiam lia bofratino devas aliri al li antaŭ la okuloj de la plejaĝuloj, kaj depreni lian ŝuon de lia piedo kaj kraĉi sur lian vizaĝon, kaj respondi kaj diri: Tiel oni agas kun homo, kiu ne konstruas domon al sia frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Kaj oni donu al li nomon en Izrael: Domo de senŝuigito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Se du viroj kverelas inter si, kaj aliros la edzino de unu, por savi sian edzon el la mano de lia batanto, kaj ŝi etendos sian manon kaj kaptos lian hontan parton:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'tiam dehaku ŝian manon, via okulo ne indulgu ŝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Ne havu en via sako duspecajn pezilojn, grandajn kaj malgrandajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Ne havu en via domo duspecajn efojn, grandan kaj malgrandan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Pezilon plenan kaj ĝustan vi devas havi, efon plenan kaj ĝustan vi devas havi; por ke vi longe vivu sur la tero, kiun la Eternulo, via Dio, donas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Ĉar abomenaĵo por la Eternulo, via Dio, estas ĉiu, kiu faras tion, ĉiu, kiu faras maljustaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Memoru, kion faris al vi Amalek sur la vojo, kiam vi iris el Egiptujo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'kiel li renkontis vin sur la vojo, kaj mortigis ĉe vi ĉiujn, kiuj, malfortiĝinte, restis malantaŭe, kiam vi estis laca kaj multelaborinta; kaj li ne timis Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Tial, kiam la Eternulo, via Dio, ripozigos vin de ĉiuj viaj malamikoj ĉirkaŭe en la lando, kiun la Eternulo, via Dio, donas al vi kiel heredan posedaĵon, elviŝu la memoron pri Amalek el sub la ĉielo; ne forgesu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Kaj kiam vi venos en la landon, kiun la Eternulo, via Dio, donas al vi kiel posedaĵon, kaj vi ekposedos ĝin kaj enloĝiĝos en ĝi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'tiam prenu el la unuaj el ĉiuj fruktoj de la tero, kiujn vi ricevos de via tero, kiun la Eternulo, via Dio, donas al vi, kaj metu en korbon, kaj iru al la loko, kiun la Eternulo, via Dio, elektos, por loĝigi tie Sian nomon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'kaj venu al la pastro, kiu estos en tiu tempo, kaj diru al li: Mi sciigas hodiaŭ antaŭ la Eternulo, via Dio, ke mi eniris en la landon, pri kiu la Eternulo ĵuris al niaj patroj, ke Li donos ĝin al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Kaj la pastro prenos la korbon el via mano, kaj metos ĝin antaŭ la altaron de la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Kaj vi ekparolos, kaj diros antaŭ la Eternulo, via Dio: Vaganta Siriano estis mia patro, kaj li foriris en Egiptujon kaj enloĝiĝis tie fremdule kun malmulte da homoj, kaj fariĝis tie popolo granda, forta, kaj multenombra;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'kaj la Egiptoj agis malbone kontraŭ ni kaj premis nin kaj metis sur nin malfacilan laboron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'kaj ni ekkriis al la Eternulo, la Dio de niaj patroj, kaj la Eternulo aŭskultis nian voĉon kaj vidis nian mizeron kaj nian laboradon kaj nian prematecon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'kaj la Eternulo elkondukis nin el Egiptujo per mano forta kaj per brako etendita kaj per granda teruro kaj per signoj kaj mirakloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'kaj Li venigis nin al ĉi tiu loko kaj donis al ni ĉi tiun landon, landon, en kiu fluas lakto kaj mielo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'kaj nun jen mi alportis la unuajn fruktojn de la tero, kiun Vi donis al mi, ho Eternulo. Kaj vi metos tion antaŭ la Eternulon, vian Dion, kaj vi adorkliniĝos antaŭ la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'Kaj vi estos gaja pro la tuta bono, kiun donis la Eternulo, via Dio, al vi kaj al via domo, vi, kaj la Levido, kaj la fremdulo, kiu loĝas inter vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Kiam vi finos la apartigadon de ĉiuj dekonaĵoj el viaj produktaĵoj en la tria jaro, la jaro de la dekonaĵoj, kaj vi fordonos al la Levido kaj al la fremdulo, al la orfo kaj al la vidvino, por ke ili manĝu inter viaj pordegoj kaj satiĝu:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'tiam diru antaŭ la Eternulo, via Dio: Mi forigis la sanktigitaĵon el la domo, kaj mi donis ĝin al la Levido kaj al la fremdulo, al la orfo kaj al la vidvino, tute laŭ Via ordono, kiun Vi faris al mi; mi ne transpaŝis Viajn ordonojn kaj mi ne forgesis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'mi ne manĝis el ĝi en la tagoj de mia malĝojo, kaj mi ne apartigis el ĝi en stato de malpureco, kaj mi ne donis el ĝi por mortinto; mi aŭskultis la voĉon de la Eternulo, mia Dio; mi faris konforme al ĉio, kion Vi ordonis al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Ekrigardu el Via sankta loĝejo, el la ĉielo, kaj benu Vian popolon Izrael, kaj la teron, kiun Vi donis al ni, kiel Vi ĵuris al niaj patroj, la landon, en kiu fluas lakto kaj mielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'En la hodiaŭa tago la Eternulo, via Dio, ordonas al vi plenumi ĉi tiujn leĝojn kaj regulojn; kaj observu kaj plenumu ilin per via tuta koro kaj per via tuta animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Al la Eternulo vi promesis hodiaŭ, ke Li estos via Dio, kaj ke vi iros laŭ Liaj vojoj kaj observos Liajn leĝojn kaj Liajn ordonojn kaj Liajn decidojn kaj aŭskultos Lian voĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Kaj la Eternulo promesis al vi hodiaŭ, ke vi estos al Li popolo propra, kiel Li diris al vi, se vi observos ĉiujn Liajn ordonojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'kaj ke Li starigos vin pli alte ol ĉiuj popoloj, kiujn Li kreis, en honoro, gloro, kaj majesto, kaj ke vi estos popolo sankta al la Eternulo, via Dio, kiel Li diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Kaj Moseo kaj la plejaĝuloj de Izrael ordonis al la popolo, dirante: Observu ĉiujn ordonojn, kiujn mi ordonas al vi hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'Kaj kiam vi transiros trans Jordanon en la landon, kiun la Eternulo, via Dio, donas al vi, tiam starigu al vi grandajn ŝtonojn kaj ĉirkaŭŝmiru ilin per kalko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'kaj skribu sur ili ĉiujn vortojn de ĉi tiu instruo, kiam vi transiros, por ke vi venu en la landon, kiun la Eternulo, via Dio, donis al vi, la landon, en kiu fluas lakto kaj mielo, kiel parolis al vi la Eternulo, la Dio de viaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Kaj kiam vi transiros Jordanon, tiam starigu ĉi tiujn ŝtonojn, pri kiuj mi ordonas al vi hodiaŭ, sur la monto Ebal, kaj ĉirkaŭŝmiru ilin per kalko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Kaj konstruu tie altaron al la Eternulo, via Dio, altaron el ŝtonoj; ne levu sur ilin feron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'El ŝtonoj tutaj konstruu la altaron de la Eternulo, via Dio, kaj alportu sur ĝi bruloferojn al la Eternulo, via Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'kaj buĉu pacoferojn, kaj manĝu tie, kaj estu gaja antaŭ la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Kaj skribu tre klare sur la ŝtonoj ĉiujn vortojn de ĉi tiu instruo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Kaj Moseo kaj la pastroj Levidoj ekparolis al la tuta Izrael, dirante: Silentu kaj aŭskultu, ho Izrael; en la hodiaŭa tago vi fariĝis popolo al la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Aŭskultu do la voĉon de la Eternulo, via Dio, kaj plenumu Liajn ordonojn kaj Liajn leĝojn, kiujn mi donas al vi hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Kaj Moseo ordonis al la popolo en tiu tago, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Ĉi tiuj stariĝu, por beni la popolon, sur la monto Gerizim, kiam vi transiros Jordanon: Simeon kaj Levi kaj Jehuda kaj Isaĥar kaj Jozef kaj Benjamen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Kaj ĉi tiuj stariĝu por malbenado sur la monto Ebal: Ruben, Gad kaj Aŝer kaj Zebulun, Dan kaj Naftali.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Kaj la Levidoj ekparolos, kaj diros al ĉiuj Izraelidoj per laŭta voĉo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Malbenita estu la homo, kiu faros idolon skulptitan aŭ fanditan, abomenaĵon antaŭ la Eternulo, manfaritaĵon de artisto, kaj starigos ĝin sekrete. Kaj la tuta popolo respondos kaj diros: Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Malbenita estu, kiu ne respektas sian patron kaj sian patrinon. Kaj la tuta popolo diros: Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Malbenita estu, kiu forŝovas la limon de sia proksimulo. Kaj la tuta popolo diros: Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Malbenita estu, kiu erarigas blindulon pri la vojo. Kaj la tuta popolo diros: Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Malbenita estu, kiu forklinas la rajton de fremdulo, orfo, kaj vidvino. Kaj la tuta popolo diros: Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Malbenita estu, kiu kuŝas kun la edzino de sia patro; ĉar li malkovris la baskon de sia patro. Kaj la tuta popolo diros: Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Malbenita estu, kiu kuŝas kun ia bruto. Kaj la tuta popolo diros: Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Malbenita estu, kiu kuŝas kun sia fratino, filino de sia patro aŭ filino de sia patrino. Kaj la tuta popolo diros: Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Malbenita estu, kiu kuŝas kun sia bopatrino. Kaj la tuta popolo diros: Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Malbenita estu, kiu kaŝe mortigas sian proksimulon. Kaj la tuta popolo diros: Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Malbenita estu, kiu prenas subaĉeton, por mortigi animon, sangon senkulpan. Kaj la tuta popolo diros: Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Malbenita estu, kiu ne persistos en la vortoj de ĉi tiu instruo, por plenumi ilin. Kaj la tuta popolo diros: Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Se vi aŭskultos la voĉon de la Eternulo, via Dio, penante plenumi ĉiujn Liajn ordonojn, kiujn mi transdonas al vi hodiaŭ, tiam la Eternulo, via Dio, faros vin pli alta, ol ĉiuj popoloj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'Kaj venos sur vin ĉiuj ĉi tiuj benoj kaj atingos vin, se vi aŭskultos la voĉon de la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Benita vi estos en la urbo, kaj benita vi estos sur la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Benita estos la frukto de via ventro kaj la frukto de via tero kaj la frukto de via bruto, la naskitaĵo de viaj grandaj brutoj kaj la idaro de viaj malgrandaj brutoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Benita estos via korbo kaj via pastujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Benita vi estos ĉe via venado, kaj benita vi estos ĉe via elirado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'La Eternulo, via Dio, faros, ke viaj malamikoj, kiuj leviĝos kontraŭ vin, estos frapitaj antaŭ vi; per unu vojo ili eliros kontraŭ vin, kaj per sep vojoj ili forkuros de antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'La Eternulo sendos al vi la benon por viaj grenejoj kaj por ĉiu entrepreno de viaj manoj, kaj Li benos vin sur la tero, kiun la Eternulo, via Dio, donas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'La Eternulo starigos vin al Si kiel popolon sanktan, kiel Li ĵuris al vi, se vi observos la ordonojn de la Eternulo, via Dio, kaj iros laŭ Liaj vojoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'Kaj vidos ĉiuj popoloj de la tero, ke la nomo de la Eternulo estas sur vi, kaj ili timos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Kaj la Eternulo donos al vi abundon da bono en la frukto de via ventro kaj en la frukto de via bruto kaj en la frukto de via tero, sur la tero, pri kiu la Eternulo ĵuris al viaj patroj, ke Li donos ĝin al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'La Eternulo malfermos al vi Sian bonan trezorejon, la ĉielon, por doni al via tero la pluvon en la ĝusta tempo kaj por beni ĉiujn farojn de viaj manoj; kaj vi pruntedonos al multaj popoloj, sed vi ne prunteprenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Kaj la Eternulo faros vin kapo, ne vosto, kaj vi estos nur supre, kaj vi ne estos malsupre; se vi obeos la ordonojn de la Eternulo, via Dio, kiujn mi transdonas al vi hodiaŭ, por observi kaj plenumi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'kaj se vi ne dekliniĝos de ĉiuj vortoj, kiujn mi ordonas al vi hodiaŭ, dekstren nek maldekstren, por sekvi aliajn diojn, servante al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Sed se vi ne aŭskultos la voĉon de la Eternulo, via Dio, penante plenumi ĉiujn Liajn ordonojn kaj leĝojn, kiujn mi transdonas al vi hodiaŭ, tiam venos sur vin ĉiuj ĉi tiuj malbenoj kaj atingos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Malbenita vi estos en la urbo, kaj malbenita vi estos sur la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Malbenita estos via korbo kaj via pastujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Malbenita estos la frukto de via ventro kaj la frukto de via tero, la naskitaĵo de viaj grandaj brutoj kaj la idaro de viaj malgrandaj brutoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Malbenita vi estos ĉe via venado, kaj malbenita vi estos ĉe via elirado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'La Eternulo sendos sur vin malbenon, konfuzon, kaj malsukceson en ĉiuj entreprenoj de via mano, kion ajn vi faros, ĝis vi estos ekstermita kaj ĝis vi baldaŭ pereos, pro viaj malbonaj agoj, pro tio, ke vi Min forlasis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'La Eternulo alkroĉos al vi la peston, ĝis Li ekstermos vin de sur la tero, al kiu vi iras, por ekposedi ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'La Eternulo frapos vin per ftizo kaj per febro kaj per malsaneca varmego kaj per brulumo kaj per sekeco kaj per bruliga aero kaj per flaviĝo de la kreskaĵoj; kaj ili persekutos vin, ĝis vi pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Kaj via ĉielo, kiu estas super via kapo, fariĝos kupro; kaj la tero, kiu estas sub vi, fariĝos fero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Anstataŭ pluvo la Eternulo donos al via tero polvon kaj cindron; el la ĉielo ĝi falados sur vin, ĝis vi ekstermiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Frapos vin la Eternulo antaŭ viaj malamikoj; per unu vojo vi eliros al ili, kaj per sep vojoj vi forkuros de antaŭ ili; kaj vi estos terurilo por ĉiuj regnoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'Kaj via kadavro estos manĝaĵo por ĉiuj birdoj de la ĉielo kaj por la bestoj de la tero, kaj neniu ilin forpelos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'La Eternulo frapos vin per abscesoj de Egiptujo kaj per sangaj ulceroj kaj per favo kaj per skabio, de kiuj vi ne povos resaniĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'La Eternulo frapos vin per frenezeco kaj per blindeco kaj per senkapableco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'Kaj vi palpados en tagmezo, kiel palpas blindulo en mallumo, kaj vi ne sukcesos sur viaj vojoj; kaj vi estos premata kaj prirabata ĉiutage, kaj neniu vin helpos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Kun virino vi fianĉiĝos, sed alia viro kuŝos kun ŝi; domon vi konstruos, sed vi ne loĝos en ĝi; vinberĝardenon vi plantos, sed vi ne ĝuos ĝiajn fruktojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Via bovo estos buĉita antaŭ viaj okuloj, sed vi ne manĝos de ĝi; via azeno estos rabita for de vi kaj ne revenos al vi; viaj ŝafoj estos fordonitaj al viaj malamikoj, kaj neniu vin helpos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Viaj filoj kaj viaj filinoj estos fordonitaj al alia popolo, kaj viaj okuloj rigardos kaj sopiros pri ili la tutan tagon; sed ne estos forto en viaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'La fruktojn de via tero kaj vian tutan laboron manĝos popolo, kiun vi ne konis; kaj vi estos nur premata kaj turmentata en ĉiu tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'Kaj vi freneziĝos de la vidaĵo antaŭ viaj okuloj, kiun vi vidos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'La Eternulo frapos vin per malbonaj ulceroj sur la genuoj kaj sur la tibikarnoj, ulceroj, de kiuj vi ne povos resaniĝi, de la plando de via piedo ĝis via verto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'La Eternulo foririgos vin, kaj la reĝon, kiun vi starigos super vi, al popolo, kiun ne konis vi nek viaj patroj; kaj vi servos tie al fremdaj dioj el ligno kaj el ŝtono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'Kaj vi estos terurilo, instrua ekzemplo, kaj mokataĵo ĉe ĉiuj popoloj, al kiuj la Eternulo vin foririgos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Multe da semoj vi elportos sur la kampon, sed malmulte vi enkolektos; ĉar formanĝos tion la akridoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Vinberĝardenojn vi plantos kaj prilaboros, sed vinon vi ne trinkos, nek enkolektos berojn; ĉar formanĝos ilin la vermoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Olivarbojn vi havos en ĉiuj viaj limoj, sed per oleo vi vin ne ŝmiros; ĉar senfruktiĝos viaj olivarboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Filojn kaj filinojn vi naskigos, sed ili ne estos ĉe vi; ĉar ili iros en malliberecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Ĉiujn viajn arbojn kaj la fruktojn de via tero ekposedos la insektoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'La fremdulo, kiu estos inter vi, leviĝos super vi ĉiam pli kaj pli alte, kaj vi malleviĝos ĉiam pli kaj pli malalte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Li pruntedonos al vi, sed vi ne pruntedonos al li; li estos kapo, kaj vi estos vosto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Kaj venos sur vin ĉiuj ĉi tiuj malbenoj kaj persekutos vin kaj atingos vin, ĝis vi estos ekstermita; ĉar vi ne aŭskultis la voĉon de la Eternulo, via Dio, por observi Liajn ordonojn kaj Liajn leĝojn, kiujn Li donis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'Kaj ili estos kiel signoj kaj avertoj sur vi kaj sur via idaro eterne;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'pro tio, ke vi ne servis al la Eternulo, via Dio, en gajeco kaj kun ĝoja koro, kiam vi ĉion havis abunde.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'Kaj vian malamikon, kiun la Eternulo sendos sur vin, vi servos en malsato kaj soifo kaj nudeco kaj manko de ĉio; kaj li metos feran jugon sur vian kolon, ĝis li ekstermos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'La Eternulo venigos sur vin popolon de malproksime, de la fino de la tero; ĝi venos, kiel flugas aglo; tio estos popolo, kies lingvon vi ne komprenos,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'popolo aroganta, kiu ne respektos maljunulon kaj ne kompatos junulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'Kaj ĝi manĝos la fruktojn de viaj brutoj kaj la fruktojn de via tero, ĝis ĝi ruinigos vin tiel, ke ĝi ne lasos al vi grenon, nek moston, nek oleon, nek naskitaĵojn de viaj grandaj brutoj, nek idaron de viaj malgrandaj brutoj, ĝis ĝi pereigos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'Kaj ĝi premos vin en ĉiuj viaj pordegoj, ĝis falos viaj altaj kaj fortikaj muroj, kiujn vi fidis, en via tuta lando; kaj ĝi premos vin en ĉiuj viaj pordegoj, en via tuta lando, kiun la Eternulo, via Dio, donis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Kaj vi manĝos la frukton de via ventro, la karnon de viaj filoj kaj viaj filinoj, kiujn donis al vi la Eternulo, via Dio, en la sieĝado kaj premado, per kiu premos vin via malamiko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Viro delikata inter vi kaj tre alkutimiĝinta al lukso, malamike rigardos sian fraton, sian amatan edzinon, siajn restintajn infanojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'donante al neniu el ili iom de la karno de siaj infanoj, kiun li manĝos; ĉar restis al li nenio en la sieĝado kaj premado, per kiu premos vin via malamiko en ĉiuj viaj pordegoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Virino delikata inter vi kaj dorlotita, kiu neniam starigis sian piedon sur la tero pro dorlotiteco kaj delikateco, malamike rigardos sian amatan edzon kaj sian filon kaj sian filinon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'ne donante al ili la placenton, kiu eliras el inter ŝiaj piedoj, nek la infanojn, kiujn ŝi naskas; ĉar, pro manko de ĉio, ŝi manĝos ilin sekrete, en la sieĝado kaj premado, per kiu premos vin via malamiko en viaj pordegoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Se vi ne penos plenumi ĉiujn vortojn de ĉi tiu instruo, skribitajn en ĉi tiu libro, timante ĉi tiun gloran kaj timindan nomon: LA ETERNULON, VIAN DION:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'tiam la Eternulo distingos viajn plagojn kaj la plagojn de via idaro, kiel plagojn grandajn kaj longedaŭrajn kaj malsanojn malbonajn kaj longedaŭrajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'Kaj Li turnos sur vin ĉiujn malsanojn de Egiptujo, kiujn vi timis, kaj ili alkroĉiĝos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Ankaŭ ĉian malsanon kaj ĉian plagon, kiuj ne estas skribitaj en ĉi tiu libro de instruo, la Eternulo venigos sur vin, ĝis vi estos ekstermita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'Kaj restos de vi malgranda amaseto, anstataŭ tio, ke vi estis multaj, kiel la steloj de la ĉielo; pro tio, ke vi ne aŭskultis la voĉon de la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Kaj kiel ĝojis la Eternulo, farante al vi bonon kaj multigante vin, tiel ĝojos la Eternulo, pereigante vin kaj ekstermante vin; kaj vi estos elŝirita el la lando, en kiun vi iras, por ekposedi ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Kaj la Eternulo disĵetos vin inter ĉiujn popolojn, de unu fino de la tero ĝis la alia fino de la tero; kaj vi servos tie al fremdaj dioj el ligno kaj el ŝtono, dioj, kiujn ne konis vi nek viaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Sed ankaŭ inter tiuj popoloj vi ne trankviliĝos, kaj ne estos ripozo por via piedo; kaj la Eternulo donos al vi tie koron tremantan kaj senfortiĝon de la okuloj kaj suferadon de la animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'Kaj via vivo estos pendanta antaŭ vi; kaj vi timos tage kaj nokte, kaj vi ne estos certa pri via vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Matene vi diros: Ho, venu la vespero! kaj vespere vi diros: Ho, venu la mateno! pro la kortremo, kiu atakos vin, kaj pro la vidaĵo antaŭ viaj okuloj, kiun vi vidos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Kaj la Eternulo revenigos vin en Egiptujon per ŝipoj, per la vojo, pri kiu mi diris al vi, ke vi ne plu vidos ĝin; kaj vi vende proponos vin tie al viaj malamikoj kiel sklavojn kaj sklavinojn, sed neniu aĉetos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Tio estas la vortoj de la interligo, kiun la Eternulo ordonis al Moseo fari kun la Izraelidoj en la lando de Moab, krom la interligo, kiun Li faris kun ili sur Ĥoreb.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'Kaj Moseo vokis al ĉiuj Izraelidoj, kaj diris al ili: Vi vidis ĉion, kion faris la Eternulo antaŭ viaj okuloj en la lando Egipta al Faraono kaj al ĉiuj liaj servantoj kaj al lia tuta lando,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'tiujn grandajn provojn, kiujn vidis viaj okuloj, tiujn grandajn signojn kaj miraklojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Sed la Eternulo ne donis al vi koron, por kompreni, nek okulojn, por vidi, nek orelojn, por aŭdi, ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Kaj mi kondukis vin dum kvardek jaroj en la dezerto; ne sentaŭgiĝis viaj vestoj sur vi, kaj viaj ŝuoj ne sentaŭgiĝis sur via piedo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Panon vi ne manĝis, kaj vinon kaj ebriigaĵojn vi ne trinkis; por ke vi sciu, ke Mi, la Eternulo, estas via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'Kaj vi venis al ĉi tiu loko; kaj eliris Siĥon, reĝo de Ĥeŝbon, kaj Og, reĝo de Baŝan, kontraŭ nin milite, kaj ni venkobatis ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'kaj ni prenis ilian landon, kaj ni donis ĝin kiel posedaĵon al la Rubenidoj kaj al la Gadidoj kaj al duono de la tribo de Manase.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Observu do la vortojn de ĉi tiu interligo kaj plenumu ilin, por ke vi sukcesu en ĉio, kion vi faros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Vi ĉiuj staras hodiaŭ antaŭ la Eternulo, via Dio; viaj estroj, viaj triboj, viaj plejaĝuloj, kaj viaj oficistoj, ĉiuj Izraelidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'viaj infanoj, viaj edzinoj, kaj via fremdulo, kiu estas en via tendaro, de la hakanto de via ligno ĝis la ĉerpanto de via akvo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'por ke vi transiru en la interligon de la Eternulo, via Dio, kaj en Lian ĵuran interkonsenton, kiun la Eternulo, via Dio, faras kun vi hodiaŭ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'por ke Li starigu vin hodiaŭ kiel Sian popolon, kaj Li estu al vi Dio, kiel Li diris al vi, kaj kiel Li ĵuris al viaj patroj, al Abraham, al Isaak, kaj al Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'Kaj ne kun vi solaj mi faras ĉi tiun interligon kaj ĉi tiun ĵuran interkonsenton,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'sed kun tiuj, kiuj staras hodiaŭ ĉi tie antaŭ la Eternulo, nia Dio, kaj kun tiuj, kiuj ne estas hodiaŭ ĉi tie kun ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Ĉar vi scias, kiel ni loĝis en la lando Egipta, kaj kiel ni trairis meze de la popoloj, tra kiuj vi trairis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'kaj vi vidis iliajn abomenaĵojn, kaj iliajn idolojn el ligno kaj el ŝtono, el arĝento kaj el oro, kiujn ili havas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Eble troviĝas inter vi viro aŭ virino aŭ familio aŭ tribo, kies koro deturniĝas hodiaŭ de la Eternulo, nia Dio, por iri servi al la dioj de tiuj popoloj; eble troviĝas inter vi radiko, kiu kreskigas maldolĉaĵon kaj absinton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'kaj kiam li aŭdos la vortojn de ĉi tiu malbeno, li benos sin en sia koro, dirante: Paco estos al mi, malgraŭ tio, ke mi iros laŭ la deziroj de mia koro; kaj pereos la trinkintoj kune kun la soifantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'La Eternulo ne volos pardoni lin, sed tiam ekflamos la kolero de la Eternulo kaj Lia severo kontraŭ tiu homo, kaj falos sur lin la tuta malbeno, kiu estas skribita en ĉi tiu libro, kaj la Eternulo ekstermos lian nomon el sub la ĉielo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'kaj la Eternulo apartigos lin por pereo el ĉiuj triboj de Izrael, konforme al ĉiuj malbenoj de la interligo, kiu estas skribita en ĉi tiu libro de instruo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'Kaj diros la venonta generacio, viaj infanoj, kiuj aperos post vi, kaj la alilandulo, kiu venos el malproksima lando kaj vidos la plagojn de ĉi tiu lando kaj ĝiajn malsanojn, per kiuj la Eternulo ĝin frapos-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'sulfuro kaj salo, bruligitaĵo estas la tuta lando; ĝi ne estas prisemata kaj ne naskas, kaj nenia herbo tie elkreskas, simile al la ruinoj de Sodom kaj Gomora, Adma kaj Ceboim, kiujn la Eternulo ruinigis en Sia kolero kaj en Sia furiozo-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'ĉiuj popoloj diros: Pro kio la Eternulo tiel agis kun ĉi tiu lando? pro kio estis tiu granda flamo de kolero?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'Kaj oni respondos: Pro tio, ke ili forlasis la interligon de la Eternulo, la Dio de iliaj patroj, kiun Li faris kun ili, kiam Li elkondukis ilin el la lando Egipta,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'kaj ili iris kaj servis al aliaj dioj kaj adorkliniĝis al ili, al dioj, kiujn ili ne konis kaj kiujn Li ne destinis por ili:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'pro tio ekflamis la kolero de la Eternulo kontraŭ tiu lando, kaj Li venigis sur ĝin ĉiujn malbenojn, kiuj estas skribitaj en ĉi tiu libro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'kaj la Eternulo elĵetis ilin el ilia lando en kolero kaj en furiozo kaj en granda indigno, kaj Li ĵetis ilin en landon alian, kiel ni vidas nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'La kaŝitaĵo apartenas al la Eternulo, nia Dio; kaj la nekaŝitaĵo al ni kaj al niaj gefiloj eterne, por ke ni plenumu ĉiujn vortojn de ĉi tiu instruo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'Kaj kiam venos sur vin ĉiuj ĉi tiuj aferoj, la beno kaj la malbeno, kiujn mi prezentis al vi, kaj vi pentos per via koro inter ĉiuj popoloj, inter kiujn ĵetis vin la Eternulo, via Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'kaj kiam vi revenos al la Eternulo, via Dio, kaj aŭskultos Lian voĉon konforme al ĉio, kion mi ordonas al vi hodiaŭ, vi kaj viaj gefiloj, per via tuta koro kaj per via tuta animo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'tiam la Eternulo, via Dio, revenigos viajn kaptitojn, kaj Li kompatos vin, kaj rekolektos vin el inter ĉiuj popoloj, inter kiujn disĵetis vin la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Eĉ se vi estus forĵetita ĝis la rando de la ĉielo, eĉ el tie rekolektos vin la Eternulo, via Dio, kaj el tio Li vin prenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'Kaj la Eternulo, via Dio, venigos vin en la landon, kiun posedis viaj patroj, kaj vi ĝin ekposedos; kaj Li faros al vi bonon kaj multigos vin pli ol viajn patrojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Kaj la Eternulo, via Dio, cirkumcidos vian koron kaj la koron de via idaro, por ke vi amu la Eternulon, vian Dion, per via tuta koro kaj per via tuta animo, por ke vi vivu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Kaj la Eternulo, via Dio, venigos ĉiujn ĉi tiujn malbenojn sur viajn malamikojn kaj sur viajn malamantojn, kiuj persekutis vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Kaj vi konvertiĝos kaj aŭskultos la voĉon de la Eternulo, kaj plenumos ĉiujn Liajn ordonojn, kiujn mi transdonas al vi hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Kaj la Eternulo, via Dio, donos al vi abundon en ĉiu faro de viaj manoj, en la frukto de via ventro kaj en la frukto de via bruto kaj en la frukto de via tero, al via bono; ĉar denove la Eternulo ĝojos pri vi, farante al vi bonon, kiel Li ĝojis pri viaj patroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'se vi aŭskultos la voĉon de la Eternulo, via Dio, observante Liajn ordonojn kaj Liajn leĝojn, kiuj estas skribitaj en ĉi tiu libro de instruo, se vi revenos al la Eternulo, via Dio, per via tuta koro kaj per via tuta animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Ĉar ĉi tiu ordono, kiun mi donas al vi hodiaŭ, ne estas neatingebla por vi, kaj ĝi ne estas malproksima.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Ne en la ĉielo ĝi estas, por ke oni povu diri: Kiu suprenirus por ni en la ĉielon kaj prenus ĝin por ni kaj aŭdigus ĝin al ni, por ke ni ĝin plenumu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Kaj ne trans la maro ĝi estas, por ke oni povu diri: Kiu irus por ni trans la maron kaj prenus ĝin por ni kaj aŭdigus ĝin al ni, por ke ni ĝin plenumu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Sed tre proksime de vi estas la afero: en via buŝo kaj en via koro, por plenumi ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Rigardu, mi proponis al vi hodiaŭ la vivon kaj bonon, kaj la morton kaj malbonon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'ordonante al vi ami la Eternulon, vian Dion, iri laŭ Liaj vojoj, kaj observi Liajn ordonojn kaj Liajn leĝojn kaj Liajn decidojn, por ke vi vivu kaj multiĝu, kaj por ke vin benu la Eternulo, via Dio, en la lando, en kiun vi venas, por ekposedi ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Sed se dekliniĝos via koro kaj vi ne aŭskultos kaj vi lasos forlogi vin kaj vi adorkliniĝos al aliaj dioj kaj servos al ili:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'en tia okazo mi sciigas al vi hodiaŭ, ke vi pereos, ke vi ne longe vivos sur la tero, sur kiun vi transiras trans Jordanon, por veni tien kaj ekposedi ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Mi atestigas pri vi hodiaŭ la ĉielon kaj la teron: la vivon kaj la morton mi proponis al vi, la benon kaj la malbenon; elektu la vivon, por ke vi vivu, vi kaj via idaro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'amante la Eternulon, vian Dion, aŭskultante Lian voĉon kaj alkroĉante vin al Li; ĉar Li estas via vivo kaj via longatempeco de loĝado sur la tero, pri kiu la Eternulo ĵuris al viaj patroj, al Abraham, al Isaak, kaj al Jakob, ke Li donos al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Kaj Moseo iris kaj parolis ĉi tiujn vortojn al la tuta Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'Kaj li diris al ili: Mi havas hodiaŭ la aĝon de cent dudek jaroj, mi ne povas plu eliri nek eniri; kaj la Eternulo diris al mi: Vi ne transiros ĉi tiun Jordanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'La Eternulo, via Dio, mem iros antaŭ vi; Li ekstermos tiujn popolojn antaŭ vi, kaj vi heredos ilin; Josuo iros antaŭ vi, kiel la Eternulo diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Kaj la Eternulo faros al ili, kiel Li faris al Siĥon kaj al Og, reĝoj de la Amoridoj, kaj al ilia lando, kiujn Li ekstermis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Kaj la Eternulo transdonos ilin al vi, kaj vi agos kun ili laŭ ĉiuj ordonoj, kiujn mi donis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Estu fortaj kaj kuraĝaj, ne timu kaj ne tremu antaŭ ili; ĉar la Eternulo, via Dio, mem iros kun vi; Li ne foriros de vi kaj ne forlasos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Kaj Moseo alvokis Josuon, kaj diris al li antaŭ la okuloj de ĉiuj Izraelidoj: Estu forta kaj kuraĝa; ĉar vi venigos ĉi tiun popolon en la landon, pri kiu la Eternulo ĵuris al iliaj patroj, ke Li donos ĝin al ili, kaj vi ekposedigos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Kaj la Eternulo, kiu mem iros antaŭ vi, Li estos kun vi, Li ne foriros de vi kaj ne forlasos vin; ne timu, kaj ne perdu la kuraĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Kaj Moseo skribis ĉi tiun instruon, kaj donis ĝin al la pastroj, idoj de Levi, kiuj portis la keston de la interligo de la Eternulo, kaj al ĉiuj plejaĝuloj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Kaj Moseo ordonis al ili, dirante: Post paso de sep jaroj, en la tempo de la jaro de forlaso, en la festo de laŭboj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'kiam la tuta Izrael venos, por aperi antaŭ la Eternulo, via Dio, sur la loko, kiun Li elektos, tiam antaŭlegu ĉi tiun instruon antaŭ la tuta Izrael, antaŭ iliaj oreloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Kunvenigu la popolon, la virojn kaj la virinojn kaj la infanojn, kaj viajn fremdulojn, kiuj estos en viaj urboj, por ke ili aŭdu kaj lernu, kaj timu la Eternulon, vian Dion, kaj penu plenumi ĉiujn vortojn de ĉi tiu instruo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Kaj iliaj filoj, kiuj ankoraŭ ne sciis, aŭdos, kaj lernos timi la Eternulon, vian Dion, dum la tuta tempo, en kiu vi vivos sur la tero, al kiu vi iras trans Jordanon, por ekposedi ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Kaj la Eternulo diris al Moseo: Jen alproksimiĝis viaj tagoj, por morti; alvoku Josuon, kaj stariĝu en la tabernaklo de kunveno, kaj Mi donos al li instrukciojn. Kaj Moseo kaj Josuo iris kaj stariĝis en la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Kaj la Eternulo aperis en la tabernaklo en nuba kolono, kaj la nuba kolono stariĝis ĉe la pordo de la tabernaklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Kaj la Eternulo diris al Moseo: Jen vi iras dormi kun viaj patroj; kaj ĉi tiu popolo komencos malĉasti post fremdaj dioj de tiu lando, en kiun ĝi venas, kaj ĝi forlasos Min kaj rompos Mian interligon, kiun Mi faris kun ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'Kaj ekflamos Mia kolero kontraŭ ĝi en tiu tago, kaj Mi forlasos ilin kaj kaŝos Mian vizaĝon for de ili, kaj ili estos konsumitaj, kaj trafos ilin multaj malfeliĉoj kaj mizeroj; kaj ili diros en tiu tago: Ĉu ne pro tio, ke nia Dio ne estas inter ni, trafis nin ĉi tiuj malfeliĉoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Sed Mi kaŝos Mian vizaĝon en tiu tago pro ĉiuj malbonagoj, kiujn ili faris, turninte sin al aliaj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Kaj nun skribu al vi ĉi tiun kanton, kaj instruu ĝin al la Izraelidoj; metu ĝin en ilian buŝon, por ke ĉi tiu kanto estu por Mi atesto inter la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Kiam Mi venigos ilin en la landon, pri kiu Mi ĵuris al iliaj patroj kaj en kiu fluas lakto kaj mielo, kaj ili manĝos kaj satiĝos kaj grasiĝos: tiam ili sin turnos al aliaj dioj kaj servos al ili, kaj Min ili malestimos kaj rompos Mian interligon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Sed kiam trafos ilin multaj malfeliĉoj kaj mizeroj, tiam ĉi tiu kanto sonos antaŭ ili kiel atesto, ĉar ĝi ne estos forgesita el la buŝo de ilia idaro. Ĉar Mi konas iliajn pensojn, kiujn ili havas hodiaŭ, antaŭ ol Mi venigis ilin en la landon, pri kiu Mi ĵuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Kaj Moseo skribis ĉi tiun kanton en tiu tago kaj lernigis ĝin al la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Kaj Li ordonis al Josuo, filo de Nun, kaj diris: Estu forta kaj kuraĝa, ĉar vi venigos la Izraelidojn en la landon, pri kiu Mi ĵuris al ili; kaj Mi estos kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Kaj kiam Moseo tute finis la skribadon de la vortoj de ĉi tiu instruo en libron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'tiam Moseo ordonis al la Levidoj, kiuj portis la keston de interligo de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Prenu ĉi tiun libron de la instruo, kaj kuŝigu ĝin flanke de la kesto de interligo de la Eternulo, via Dio, por ke ĝi estu tie atesto kontraŭ vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'ĉar mi konas vian malobeemecon kaj vian malmolan nukon; ja eĉ nun, kiam mi estas ankoraŭ vivanta inter vi, vi estis malobeemaj kontraŭ la Eternulo: kio do estos post mia morto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Kunvenigu al mi ĉiujn plejaĝulojn de viaj triboj kaj viajn oficistojn, kaj mi parolos antaŭ iliaj oreloj tiujn vortojn, kaj mi atestigos kontraŭ ili la ĉielon kaj la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Ĉar mi scias, ke post mia morto vi malboniĝos kaj dekliniĝos de la vojo, pri kiu mi ordonis al vi; kaj trafos vin mizero en la estonta tempo pro tio, ke vi faros malbonon antaŭ la okuloj de la Eternulo, kolerigante Lin per la faroj de viaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Kaj Moseo eldiris antaŭ la oreloj de la tuta komunumo de Izrael la vortojn de ĉi tiu kanto ĝis la fino:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Atentu, ĉielo, kaj mi parolos; Kaj aŭdu la tero la vortojn de mia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Verŝiĝos kiel pluvo mia instruo, Fluos kiel roso mia parolo, Kiel pluvego sur verdaĵon Kaj kiel grandaj gutoj sur herbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Ĉar la nomon de la Eternulo mi vokas; Donu honoron al nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Li estas la Roko; perfektaj estas Liaj faroj; Ĉar ĉiuj Liaj vojoj estas justaj. Li estas Dio fidela kaj sen malbonago; Justa kaj verama Li estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Ili malboniĝis antaŭ Li, Ili ne estas Liaj infanoj, pro sia malvirteco; Generacio malhumila kaj malhonesta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Ĉu al la Eternulo vi tiel repagas, Popolo malnobla kaj malprudenta? Ĉu ne Li estas via patro, kiu vin kreis? Ĉu ne Li vin estigis kaj aranĝis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Rememoru la tempon antikvan, Pripensu la jarojn de la antaŭaj generacioj; Demandu vian patron, kaj li sciigos al vi; Viajn maljunulojn, kaj ili diros al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Kiam la Plejaltulo donis landojn al la popoloj, Kiam Li disloĝigis la homidojn, Li starigis la limojn de la popoloj Laŭ la nombro de la idoj de Izrael;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Ĉar parto de la Eternulo estas Lia popolo; Jakob estas Lia hereda mezuritaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Li trovis lin en dezerto, En stepo, kie regas bruo senviva; Li ĉirkaŭis lin, zorgis pri li, Gardis lin kiel pupilon de Sia okulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Kiel aglo vekas sian neston, Flugpendas super siaj idoj, Tiel Li etendis Siajn flugilojn, Prenis lin, portis lin sur Siaj flugiloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'La Eternulo sola kondukis lin, Kaj neniu fremda dio estis kun Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Li portis lin sur altaĵon de la tero, Manĝigis al li produktojn de kampoj, Nutris lin per mielo el ŝtono Kaj per oleo el granita roko,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Per butero de bovinoj kaj per lakto de ŝafinoj Kun sebo de ŝafidoj Kaj per ŝafoj de Baŝan kaj per kaproj Kaj per la graso de la kernoj de tritiko; Kaj vi trinkis la ŝaŭmantan sangon de vinberoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Kaj Jeŝurun grasiĝis kaj malhumiliĝis; Vi grasiĝis, dikiĝis, kaj sebopleniĝis; Kaj li forlasis la Dion, kiu lin kreis, Kaj li malrespektis la Rokon de sia savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Ili incitis Lin per fremdaj dioj, Per abomenaĵoj ili kolerigis Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Ili alportis oferojn al diabloj, ne al Dio, Al dioj, kiujn ili ne konis, Al novaj, antaŭ nelonge venintaj, Pri kiuj ne pensis viaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'La Defendanton, kiu vin naskis, vi perdis el la memoro, Kaj vi forgesis la Dion, kiu vin estigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Kaj la Eternulo vidis, Kaj ekabomenis kolere Siajn filojn kaj Siajn filinojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'Kaj Li diris: Mi kaŝos Mian vizaĝon for de ili, Mi vidos, kia estos ilia fino; Ĉar ili estas generacio perfida, Infanoj, kiuj ne havas en si fidelecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Ili incitis Min per ne-dio, Kolerigis Min per siaj vantaĵoj: Tial Mi incitos ilin per ne-popolo, Per popolo malnobla Mi ilin kolerigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Ĉar fajro ekflamis en Mia kolero, Kaj ĝi brulas ĝis la profundoj de Ŝeol, Kaj ĝi ruinigas la teron kaj ĝiajn produktojn, Kaj ĝi bruligas la bazojn de la montoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Mi amasigos super ili malfeliĉojn; Miajn sagojn Mi ĉiujn eluzos kontraŭ ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Ili konsumiĝos de malsato Kaj senfortiĝos de febro kaj de turmenta epidemio; Kaj la dentojn de bestoj Mi venigos sur ilin Kun la veneno de rampantoj sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Ekstere ekstermos glavo, Kaj en la domoj teruro, Junulon kaj junulinon, Suĉinfanon kun grizharulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Mi dirus: Mi disblovos ilin, Mi neniigos la memoron pri ili inter la homoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Se Mi ne timus, ke ĉagrenus Min la malamikoj, Ke eble fieriĝus iliaj premantoj, Kaj dirus: Nia mano estas potenca, Kaj ne la Eternulo faris ĉion ĉi tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Ĉar ili estas popolo, kiu perdis la prudenton, Kaj komprenadon ili ne havas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Se ili estus prudentaj, ili tion komprenus; Ili pripensus, kia estos ilia fino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Kiel povus unu persekuti milon Kaj du forkurigi dek milojn, Se ilia Defendanto ilin ne vendus Kaj la Eternulo ilin ne transdonus?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Ilia defendanto ne estas ja kiel nia Defendanto, Niaj malamikoj mem tion povas juĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Ĉar el la vinberbranĉoj de Sodom estas iliaj vinberbranĉoj Kaj el la kampoj de Gomora; Iliaj beroj estas beroj venenaj, Vinberojn maldolĉajn ili havas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Galo de drakoj estas ilia vino, Kaj pereiga veneno de aspidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Ĉu tio ne estas kaŝita ĉe Mi, Sigelita en Mia trezorejo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Ĉe Mi estas venĝo kaj repago, Ĝis la tago, kiam ekŝanceliĝos ilia piedo; Ĉar proksima estas la tago de ilia malfeliĉo, Kaj rapide venos tio, kio estas destinita por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Ĉar la Eternulo juĝos Sian popolon, Kaj Li kompatos Siajn sklavojn, Kiam Li vidos, ke malaperis ilia forto, Ke jam ne ekzistas malliberulo nek liberulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Kaj Li diros: Kie estas iliaj dioj, La fortikaĵo, kiun ili fidis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'Kiuj manĝis la sebon de iliaj buĉoferoj, Trinkis la vinon de iliaj verŝoferoj? Ili leviĝu kaj helpu vin, Ili estu ŝirmo por vi!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Vidu nun, ke estas Mi, Mi sola, Kaj ne ekzistas dio krom Mi; Mi mortigas kaj vivigas; Mi frapas kaj resanigas; Kaj neniu povas savi el Mia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Mi levos al la ĉielo Mian manon, Kaj Mi diros: Mi vivas eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'Kiam Mi akrigos Mian brilantan glavon Kaj Mia mano komencos la juĝadon, Tiam Mi revenĝos al Miaj malamikoj, Kaj al Miaj malamantoj Mi repagos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Mi ebriigos Miajn sagojn per sango, Kaj Mia glavo manĝos karnon, El la sango de mortigitoj kaj kaptitoj, El la kapoj de la estroj de la malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Gloru, ho gentoj, Lian popolon; Ĉar Li venĝos pro la sango de Siaj sklavoj, Kaj Li redonos venĝon al Siaj malamikoj Kaj pekliberigos Sian teron kaj Sian popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Kaj Moseo venis kaj eldiris ĉiujn vortojn de ĉi tiu kanto antaŭ la oreloj de la popolo, li kaj Josuo, filo de Nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Kaj kiam Moseo finis la paroladon de ĉiuj ĉi tiuj vortoj antaŭ la tuta Izrael,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'tiam li diris al ili: Enmetu en vian koron ĉiujn vortojn, per kiuj mi avertas vin hodiaŭ, kaj transdonu ilin al viaj gefiloj, por ke ili penu plenumi ĉiujn vortojn de ĉi tiu instruo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Ĉar ne malgrava afero ĝi estas por vi; sed ĝi estas via vivo, kaj per ĉi tiu afero vi longe vivos sur la tero, al kiu vi iras trans Jordanon, por ekposedi ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Kaj la Eternulo ekparolis al Moseo en la sama tago, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Supreniru sur ĉi tiun monton Abarim, sur la monton Nebo, kiu estas en la lando Moaba, kontraŭ Jeriĥo; kaj rigardu la landon Kanaanan, kiun Mi donas al la Izraelidoj kiel posedaĵon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'kaj mortu sur la monto, sur kiun vi supreniras, kaj alkolektiĝu al via popolo, kiel mortis Aaron, via frato, sur la monto Hor, kaj alkolektiĝis al sia popolo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'pro tio, ke vi pekis kontraŭ Mi inter la Izraelidoj ĉe la Akvo de Malpaco en Kadeŝ, en la dezerto Cin; pro tio, ke vi ne aperigis Mian sanktecon inter la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Ĉar de malproksime vi vidos la landon, sed vi ne eniros tien, en la landon, kiun mi donas al la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Kaj jen estas la beno, per kiu benis Moseo, la Dia homo, la Izraelidojn antaŭ sia morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Li diris: La Eternulo venis de Sinaj Kaj eklumis al ili de Seir; Li ekbrilis de la monto Paran Kaj venis el milmiloj da sanktuloj; Ĉe Lia dekstra flanko estas fajro de leĝo por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Vere Li amas la popolojn; Ĉiuj Liaj sanktuloj estas en Via mano; Kaj ili falis antaŭ Viaj piedoj, Por aŭskulti Viajn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Instruon transdonis al ni Moseo, Heredaĵon por la komunumo de Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'Kaj li fariĝis reĝo en Jeŝurun, Kiam kunvenis la ĉefoj de la popolo, Kune la triboj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Vivu Ruben, kaj li ne mortu; Kaj liaj viroj ne estu malmultaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Kaj ĉi tion pri Jehuda li diris: Aŭdu, ho Eternulo, la voĉon de Jehuda, Kaj alkonduku lin al lia popolo; Per siaj manoj li sin defendos, Kaj Vi estu helpanto kontraŭ liaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Kaj pri Levi li diris: Viaj signoj de lumo kaj de justo estu por Via sankta viro, Kiun Vi elprovis en Masa, Kun kiu Vi malpacis ĉe la Akvo de Malpaco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'Kiu diras pri sia patro kaj pri sia patrino: Mi ne vidis ilin; Kiu ne rekonis siajn fratojn Kaj ne konis siajn filojn: Ĉar ili observis Viajn dirojn Kaj gardis Vian interligon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Ili instruu Viajn leĝojn al Jakob Kaj Vian instruon al Izrael; Ili metu incenson antaŭ Vian vizaĝon, Kaj bruloferojn sur Vian altaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Benu, ho Eternulo, lian forton, Kaj favoru la faron de liaj manoj; Frapu la lumbon de tiuj, kiuj leviĝas kontraŭ lin, Kaj de liaj malamantoj, ke ili ne povu releviĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'Pri Benjamen li diris: La amato de la Eternulo loĝos sendanĝere ĉe Li; Li protektas lin ĉiutage, Kaj inter Liaj brakoj li ripozas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Kaj pri Jozef li diris: Benita de la Eternulo estas lia tero, Per donoj de la ĉielo, per roso, Kaj per la profundaĵo, kuŝanta malsupre,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'Kaj per donoj, produktataj de la suno, Kaj per donoj, kiujn eligas la lunoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'Kaj per la plejbonaĵoj de la antikvaj montoj, Kaj per la donoj de la eternaj montetoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'Kaj per la donoj de la tero kaj de ĝia abundeco. Kaj la favoro de Tiu, kiu aperis en la arbetaĵo, Venu sur la kapon de Jozef Kaj sur la verton de la elektito inter liaj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Lia unuenaskita bovido estas belega, Kaj liaj kornoj estas kiel kornoj de bubalo; Per ili li kornobatos ĉiujn popolojn kune ĝis la randoj de la tero. Tio estas la dekmiloj de Efraim, Tio estas la miloj de Manase.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Kaj pri Zebulun li diris: Ĝoju, Zebulun, ĉe via eliro; Kaj Isaĥar, en viaj tendoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'La popolojn ili vokas sur la monton; Tie ili oferbuĉas oferojn de justeco; Ĉar ili nutras sin per la riĉaĵo de la maro, Kaj per trezoroj, kaŝitaj en la sablo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Kaj pri Gad li diris: Benata estu la disvastiganto de Gad; Kiel leono li kuŝas, Kaj li disŝiras brakon kune kun la verto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Li elrigardis al si komencaĵon, Ĉar tie la leĝdonanto destinis por li parton; Kaj li venis kun la ĉefoj de la popolo, Plenumis la justecon de la Eternulo Kaj Liajn decidojn pri Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'Kaj pri Dan li diris: Dan estas juna leono, Kiu elsaltas el Baŝan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Kaj pri Naftali li diris: Naftali estas sata de favoro Kaj plena de beno de la Eternulo; Okcidenton kaj sudon li posedu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'Kaj pri Aŝer li diris: Benita inter la filoj estas Aŝer; Li estu amata de siaj fratoj, Kaj li trempu en oleo sian piedon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Fero kaj kupro estu viaj rigliloj; Kaj dum via tuta vivo daŭru via bonstato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Ne ekzistas simila al Dio, ho Jeŝurun, Kiu sidas en la ĉielo por via helpo, En Sia majesto en la nuboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'La Dio antikva estas loĝejo, Kaj malsupre estas brakoj eternaj. Kaj Li forpelis de antaŭ vi la malamikon, Kaj diris: Ekstermu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Kaj Izrael loĝas sendanĝere, sola; La fonto de Jakob estas sur tero de greno kaj mosto, Kaj lia ĉielo gutigas roson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Feliĉa vi estas, ho Izrael! Kiu estas simila al vi, popolo helpata de la Eternulo, La ŝildo de via helpo kaj la glavo de via gloro? Flatos vin viaj malamikoj, Kaj vi paŝados sur iliaj altaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Kaj Moseo supreniris de la stepo de Moab sur la monton Nebo, sur la supron de Pisga, kiu estas kontraŭ Jeriĥo. Kaj la Eternulo montris al li la tutan landon Gilead, ĝis Dan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'kaj la tutan teron de Naftali kaj la teron de Efraim kaj Manase kaj la tutan teron de Jehuda ĝis la ekstrema maro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'kaj la teron sudan kaj la distrikton de la valo de Jeriĥo, la urbo de Palmoj, ĝis Coar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Kaj la Eternulo diris al li: Jen estas la lando, pri kiu Mi ĵuris al Abraham, al Isaak, kaj al Jakob, dirante: Al via idaro Mi ĝin donos. Mi vidigis ĝin al vi per viaj okuloj, sed tien vi ne eniros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Kaj mortis tie Moseo, la servanto de la Eternulo, en la lando Moaba, laŭ la diro de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'Kaj li estas enterigita en la valo en la lando Moaba, kontraŭ Bet-Peor; kaj neniu scias lian tombon ĝis hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Kaj Moseo havis la aĝon de cent dudek jaroj, kiam li mortis; ne malakriĝis lia okulo, kaj ne malaperis lia freŝeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Kaj la Izraelidoj priploris Moseon sur la stepoj de Moab dum tridek tagoj. Kaj pasis la tagoj de plorado kaj funebrado pri Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Kaj Josuo, filo de Nun, estis plena de spirito de saĝeco, ĉar Moseo metis siajn manojn sur lin; kaj la Izraelidoj aŭskultis lin, kaj agis, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Ne aperis plu en Izrael profeto tia, kiel Moseo, kiun la Eternulo konis, vizaĝon kontraŭ vizaĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'koncerne ĉiujn signojn kaj miraklojn, kiujn la Eternulo sendis lin fari en la lando Egipta super Faraono kaj super ĉiuj liaj servantoj kaj super lia tuta lando,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'kaj koncerne la tutan potencon, kaj ĉiujn mirindajn kaj grandajn farojn, kiujn Moseo faris antaŭ la okuloj de la tuta Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Post la morto de Moseo, servanto de la Eternulo, la Eternulo diris al Josuo, filo de Nun, helpanto de Moseo, jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Mia servanto Moseo mortis; kaj nun leviĝu, transiru ĉi tiun Jordanon, vi kaj ĉi tiu tuta popolo, en la landon, kiun Mi donas al ili, al la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Ĉiun lokon, sur kiun paŝos la plando de via piedo, Mi donas al vi, kiel Mi diris al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'De la dezerto kaj de ĉi tiu Lebanon ĝis la granda rivero, la rivero Eŭfrato, la tuta lando de la Ĥetidoj, ĝis la Granda Maro okcidente, estu viaj limoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Neniu rezistos al vi dum via tuta vivo; kiel Mi estis kun Moseo, tiel Mi estos kun vi; Mi ne foriros de vi kaj Mi ne forlasos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Estu forta kaj kuraĝa; ĉar vi ekposedigos al ĉi tiu popolo la landon, pri kiu Mi ĵuris al iliaj patroj, ke Mi donos ĝin al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Nur estu forta kaj tre kuraĝa, penante agi laŭ la tuta instruo, kiun donis al vi Mia servanto Moseo; ne dekliniĝu de ĝi dekstren nek maldekstren, por ke vi sukcesu ĉie, kien vi iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Ĉi tiu libro de la instruo ne foriĝu de via buŝo, sed meditu pri ĝi tage kaj nokte, por ke vi zorge plenumu ĉion, kio estas skribita en ĝi; ĉar tiam vi havos feliĉon sur viaj vojoj, kaj tiam vi havos sukceson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Jen Mi ordonis al vi: estu forta kaj kuraĝa; ne havu teruron kaj ne timu; ĉar kun vi estas la Eternulo, via Dio, ĉie, kien vi iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Kaj Josuo ordonis al la oficistoj de la popolo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Iru tra la tendaro, kaj ordonu al la popolo, dirante: Pretigu por vi manĝaĵon, ĉar post tri tagoj vi transiros ĉi tiun Jordanon, por iri ekposedi la landon, kiun la Eternulo, via Dio, donas al vi kiel posedaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Kaj al la Rubenidoj kaj al la Gadidoj kaj al la duontribo de Manase, Josuo diris jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Memoru la aferon, kiun ordonis al vi Moseo, servanto de la Eternulo, dirante: La Eternulo, via Dio, ripozigis vin, kaj donis al vi ĉi tiun teron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'viaj edzinoj, viaj infanoj, kaj viaj brutoj restos sur la tero, kiun donis al vi Moseo transe de Jordan; kaj vi iru armitaj antaŭ viaj fratoj, ĉiuj, kiuj taŭgas por la milito, kaj helpu ilin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'ĝis la Eternulo ripozigos viajn fratojn, kiel vin, kaj ili ankaŭ ekposedos la teron, kiun la Eternulo, via Dio, donas al ili; tiam vi reiros sur la teron de via posedado, kaj vi posedos ĝin, kiun donis al vi Moseo, servanto de la Eternulo, transe de Jordan, sur la flanko de sunleviĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Kaj ili respondis al Josuo, dirante: Ĉion, kion vi ordonis, ni faros, kaj ĉien, kien vi sendos nin, ni iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Tute tiel, kiel ni obeis Moseon, ni obeos vin; nur la Eternulo, via Dio, estu kun vi, kiel Li estis kun Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Ĉiu, kiu malobeos vian diron kaj ne aŭskultos viajn vortojn en ĉio, kion vi ordonis al li, estos mortigita. Nur estu forta kaj kuraĝa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Kaj Josuo, filo de Nun, sendis el Ŝitim du esplorrigardantojn sekrete, dirinte: Iru, pririgardu la landon kaj Jeriĥon. Kaj ili iris, kaj venis en la domon de malĉastistino, kies nomo estis Raĥab, kaj ili dormis tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Kaj oni diris al la reĝo de Jeriĥo jene: Jen venis ĉi tien en la nokto viroj el la Izraelidoj, por esplorrigardi la landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Tiam la reĝo de Jeriĥo sendis al Raĥab, por diri: Elirigu la virojn, kiuj venis al vi, kiuj venis en vian domon; ĉar por esplorrigardi la tutan landon ili venis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Sed la virino prenis la du virojn kaj kaŝis ilin, kaj diris: Efektive venis al mi la viroj, sed mi ne scias, el kie ili estas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'kaj kiam en la mallumo oni estis fermontaj la pordegon, la viroj eliris; mi ne scias, kien la viroj iris; postkuru ilin rapide, ĉar vi kuratingos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Sed ŝi suprenirigis ilin sur la tegmenton, kaj kaŝis ilin en la trunkoj de lino, kiuj kuŝis ĉe ŝi sur la tegmento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'La viroj postkuris ilin en la direkto al Jordan ĝis la transirejo; kaj la pordegon oni fermis, post kiam eliris la postkurantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Kaj antaŭ ol la kaŝitoj kuŝiĝis, ŝi supreniris al ili sur la tegmenton,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'kaj ŝi diris al la viroj: Mi scias, ke la Eternulo transdonis al vi la landon kaj ke teruro pri vi falis sur nin kaj ke timuliĝis antaŭ vi ĉiuj loĝantoj de la lando;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'ĉar ni aŭdis, ke la Eternulo sekigis antaŭ vi la akvon de la Ruĝa Maro, kiam vi eliris el Egiptujo, kaj kiel vi agis kun la du reĝoj de la Amoridoj, kiuj estis transe de Jordan, kun Siĥon kaj kun Og, kiujn vi ekstermis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Ni aŭdis, kaj ektimis nia koro, kaj en neniu restis kuraĝo antaŭ vi; ĉar la Eternulo, via Dio, estas Dio en la ĉielo supre kaj sur la tero malsupre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Kaj nun ĵuru al mi per la Eternulo, ke ĉar mi faris favorkoraĵon al vi, tial ankaŭ vi faros favorkoraĵon al la domo de mia patro; kaj donu al mi signon de vereco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'ke vi konservos la vivon al mia patro kaj al mia patrino kaj al miaj fratoj kaj al miaj fratinoj, kaj al ĉiu, kiun ili havas, kaj vi savos niajn animojn kontraŭ morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Kaj la viroj diris al ŝi: Nia animo mortu anstataŭ via, se vi ne rakontos pri ĉi tiu nia afero; kaj kiam la Eternulo donos al ni la landon, tiam ni faros al vi favorkoraĵon kaj fidelaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Kaj ŝi malsuprenigis ilin per ŝnuro tra la fenestro; ĉar ŝia domo estis en la muro de la urbo, kaj ŝi loĝis en la muro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Kaj ŝi diris al ili: Iru sur la monton, por ke ne renkontu vin la postkurantoj, kaj kaŝu vin tie dum tri tagoj, ĝis la postkurantoj revenos; kaj poste vi iros vian vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Kaj la viroj diris al ŝi: Jen kiamaniere ni estos liberaj de via ĵuro, per kiu vi ĵurigis nin:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'jen ni venos en la landon, kaj vi alligu al la fenestro la ruĝan ŝnuron, per kiu vi nin malsuprenigis; kaj vian patron kaj vian patrinon kaj viajn fratojn kaj la tutan familion de via patro kolektu al vi en la domon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'kaj se iu eliros el la pordo de via domo eksteren, lia sango estos sur lia kapo, kaj ni estos senkulpaj; kaj pri ĉiu, kiu estos kun vi en la domo, lia sango estos sur nia kapo, se ies mano lin tuŝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Sed se vi rakontos ĉi tiun nian aferon, tiam ni estos liberaj de via ĵuro, per kiu vi ĵurigis nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Kaj ŝi diris: Ĝi estu, kiel vi diris. Kaj ŝi foririgis ilin, kaj ili iris; kaj ŝi alligis la ruĝan ŝnuron al la fenestro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Kaj ili iris, kaj venis sur la monton, kaj restis tie dum tri tagoj, ĝis revenis la postkurantoj. Kaj la postkurantoj serĉis sur la tuta vojo, kaj ne trovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Tiam la du viroj iris returne, kaj malsupreniris de la monto, kaj transiĝis, kaj venis al Josuo, filo de Nun, kaj rakontis al li ĉion, kio okazis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'Kaj ili diris al Josuo: La Eternulo transdonis en nian manon la tutan landon, kaj ĉiuj loĝantoj de la lando havas timon antaŭ ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Kaj Josuo leviĝis frue matene, kaj ili elmoviĝis de Ŝitim kaj alvenis al Jordan, li kaj ĉiuj Izraelidoj, kaj ili tradormis tie la nokton, antaŭ ol transiri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Kaj post paso de tri tagoj la oficistoj iris tra la tendaro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'kaj ordonis al la popolo, dirante: Kiam vi ekvidos la keston de interligo de la Eternulo, via Dio, kaj la pastrojn Levidojn, kiuj portas ĝin, tiam ekmoviĝu de viaj lokoj kaj iru post ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Sed inter vi kaj ĝi devas esti interspaco de ĉirkaŭ du mil ulnoj da mezuro; ne alproksimiĝu al ĝi, por ke vi sciu la vojon, laŭ kiu vi devas iri; ĉar vi ne iris laŭ tiu vojo antaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Kaj Josuo diris al la popolo: Sanktigu vin, ĉar morgaŭ la Eternulo faros inter vi miraklojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Kaj Josuo diris al la pastroj jene: Prenu la keston de interligo, kaj preteriru antaŭ la popolo. Kaj ili prenis la keston de interligo, kaj preteriris antaŭ la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Kaj la Eternulo diris al Josuo: En ĉi tiu tago Mi komencos altigi vin antaŭ la okuloj de la tuta Izrael, por ke ili sciu, ke kiel Mi estis kun Moseo, tiel Mi estos kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Kaj vi ordonu al la pastroj, kiuj portas la keston de interligo, dirante: Kiam vi venos al la rando de la akvo de Jordan, tiam stariĝu en Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Kaj Josuo diris al la Izraelidoj: Aliru ĉi tien, kaj aŭskultu la vortojn de la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Kaj Josuo diris: Per tio vi ekscios, ke la vivanta Dio estas inter vi, kaj ke Li forpelos de antaŭ vi la Kanaanidojn kaj la Ĥetidojn kaj la Ĥividojn kaj la Perizidojn kaj la Girgaŝidojn kaj la Amoridojn kaj la Jebusidojn:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'jen la kesto de interligo de la Sinjoro de la tuta tero transiros antaŭ vi Jordanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Kaj nun prenu al vi dek du virojn el la triboj de Izrael, po unu viro el ĉiu tribo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Kaj kiam la plandoj de la piedoj de la pastroj, kiuj portas la keston de la Eternulo, la Sinjoro de la tuta tero, haltos en la akvo de Jordan, la akvo de Jordan detiriĝos, la akvo, kiu fluas de supre; kaj ĝi stariĝos, kiel unu muro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Kaj kiam la popolo elmoviĝis el siaj tendoj, por transiri Jordanon, kaj la pastroj, kiuj portis la keston de interligo, estis antaŭ la popolo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'kaj kiam la portantoj de la kesto venis al Jordan, kaj la piedoj de la pastroj, kiuj portis la keston, trempiĝis en la rando de la akvo (kaj Jordan estis plena ĉe ĉiuj siaj bordoj dum la tuta tempo de rikoltado),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'tiam la akvo, kiu fluis de supre, haltis, stariĝis kiel unu muro, tre malproksime, ĉe la urbo Adam, kiu estas apud Cartan; kaj la akvo, kiu fluis al la maro de la stepo, al la Sala Maro, tute foriris. Kaj la popolo transiris kontraŭ Jeriĥo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Kaj la pastroj, kiuj portis la keston de interligo de la Eternulo, staris forte sur seka tero meze de Jordan, kaj la tuta Izrael iris trans seka tero, ĝis la tuta popolo transiris Jordanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Kaj kiam la tuta popolo transiris Jordanon, la Eternulo diris al Josuo jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Prenu al vi el la popolo dek du virojn, po unu viro el ĉiu tribo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'kaj ordonu al ili, dirante: Prenu al vi de ĉi tie, el la mezo de Jordan, kie firme staris la piedoj de la pastroj, dek du ŝtonojn, kaj transportu ilin kun vi, kaj metu ilin sur la nokthaltejo, kie vi pasigos ĉi tiun nokton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Kaj Josuo alvokis la dek du virojn, kiujn li destinis el la Izraelidoj, po unu viro el ĉiu tribo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'kaj Josuo diris al ili: Iru antaŭ la kesto de la Eternulo, via Dio, en la mezo de Jordan, kaj levu al vi sur vian ŝultron ĉiu po unu ŝtono, laŭ la nombro de la triboj de la Izraelidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'por ke ĉi tio estu signo inter vi. Se viaj infanoj morgaŭ demandos vin, dirante: Pro kio estas ĉe vi ĉi tiuj ŝtonoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'tiam vi diros al ili: Pro tio, ke disflankiĝis la akvo de Jordan antaŭ la kesto de interligo de la Eternulo; kiam ĝi iris trans Jordanon, disflankiĝis la akvo de Jordan. Kaj ĉi tiuj ŝtonoj estos memorigaĵo por la Izraelidoj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Kaj la Izraelidoj faris tiel, kiel ordonis Josuo; kaj ili prenis dek du ŝtonojn el meze de Jordan, kiel la Eternulo diris al Josuo, laŭ la nombro de la triboj de la Izraelidoj; kaj ili transportis ilin kun si al la nokthaltejo, kaj kuŝigis ilin tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Kaj dek du ŝtonojn Josuo starigis meze de Jordan, sur la loko, sur kiu staris la piedoj de la pastroj, kiuj portis la keston de interligo; kaj ili restis tie ĝis hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Kaj la pastroj, kiuj portis la keston, staris meze de Jordan, ĝis finiĝis ĉio, kion la Eternulo ordonis al Josuo diri al la popolo, konforme al ĉio, kion Moseo ordonis al Josuo. Kaj la popolo rapide transiris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Kaj kiam la tuta popolo transiris, tiam transiris la kesto de la Eternulo kaj la pastroj antaŭ la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Kaj la Rubenidoj kaj la Gadidoj kaj la duontribo de Manase transiris armitaj antaŭ la Izraelidoj, kiel diris al ili Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Ĉirkaŭ kvardek mil armitaj militistoj transiris antaŭ la Eternulo por la milito, sur la stepon de Jeriĥo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'En tiu tago la Eternulo altigis Josuon antaŭ la okuloj de la tuta Izrael; kaj ili komencis timi lin, kiel ili timis Moseon dum lia tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Kaj la Eternulo diris al Josuo jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Ordonu al la pastroj, kiuj portas la keston de atesto, ke ili supreniru el Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Kaj Josuo ordonis al la pastroj, dirante: Supreniru el Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Kaj kiam la pastroj, kiuj portis la keston de interligo de la Eternulo, supreniris el Jordan, kaj kiam la plandoj de la pastroj leviĝis sur la sekan teron, la akvo de Jordan reiris al sia loko kaj ekfluis kiel antaŭe laŭ ĉiuj siaj bordoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Kaj la popolo eliris el Jordan en la deka tago de la unua monato, kaj ili starigis sian tendaron en Gilgal, oriente de Jeriĥo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Kaj la dek du ŝtonojn, kiujn ili prenis el Jordan, Josuo starigis en Gilgal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'Kaj li diris al la Izraelidoj jene: Se en la venonta tempo viaj filoj demandos siajn patrojn, dirante: Kion signifas ĉi tiuj ŝtonoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'tiam diru al viaj filoj jene: Sur seka tero Izrael transiris ĉi tiun Jordanon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'ĉar la Eternulo, via Dio, elsekigis la akvon de Jordan antaŭ vi, ĝis vi transiris, kiel la Eternulo, via Dio, faris kun la Ruĝa Maro, kiun Li elsekigis antaŭ ni, ĝis ni transiris;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'por ke ĉiuj popoloj de la tero sciu, ke la mano de la Eternulo estas forta, kaj por ke ili timu la Eternulon, vian Dion, en ĉiu tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Kaj kiam ĉiuj reĝoj de la Amoridoj, kiuj loĝis transe de Jordan okcidente, kaj ĉiuj reĝoj de la Kanaanidoj, kiuj loĝis apud la maro, aŭdis, ke la Eternulo elsekigis la akvon de Jordan antaŭ la Izraelidoj, ĝis ili transiris, tiam ektimis ilia koro, kaj ili ne havis plu kuraĝon antaŭ la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'En tiu tempo la Eternulo diris al Josuo: Faru al vi ŝtonajn tranĉilojn, kaj cirkumcidu la Izraelidojn denove, duan fojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Kaj Josuo faris al si ŝtonajn tranĉilojn, kaj cirkumcidis la Izraelidojn sur la monteto Aralot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Kaj jen estas la kaŭzo, pro kiu Josuo cirkumcidis: la tuta popolo, kiu eliris el Egiptujo, la virseksuloj, ĉiuj militkapablaj, mortis en la dezerto, sur la vojo, kiam ili iris el Egiptujo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'ĉar cirkumcidita estis la tuta popolo, kiu eliris; sed ĉiuj, kiuj naskiĝis en la dezerto, sur la vojo, kiam ili iris el Egiptujo, ne estis cirkumciditaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Ĉar dum kvardek jaroj la Izraelidoj iris en la dezerto, ĝis la tuta popolo militkapabla, kiu eliris el Egiptujo, elmortis, pro tio, ke ili ne obeis la voĉon de la Eternulo; al ili la Eternulo ĵuris, ke Li ne montros al ili la landon, pri kiu la Eternulo ĵuris al iliaj patroj, ke Li donos al ni landon, en kiu fluas lakto kaj mielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Iliajn filojn Li starigis anstataŭ ili. Tiujn Josuo cirkumcidis; ĉar ili estis necirkumciditaj, ĉar oni ne cirkumcidis ilin dum la vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Kaj kiam estis finita la cirkumcidado de la tuta popolo, ili restis sur sia loko en la tendaro, ĝis ili resaniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Kaj la Eternulo diris al Josuo: Hodiaŭ Mi derulis de vi la hontindaĵon de Egiptujo. Kaj tiu loko ricevis la nomon Gilgal ĝis hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Kaj la Izraelidoj staris tendare en Gilgal, kaj faris la Paskon en la dek-kvara tago de la monato vespere sur la stepo de Jeriĥo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'Kaj ili manĝis el la produktoj de la tero en la sekvanta tago post la Pasko, macojn kaj rostitajn grajnojn en la sama tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Kaj la manao ĉesis fali en la sekvanta tago, post kiam ili manĝis el la produktoj de la tero; kaj la Izraelidoj ne plu havis manaon, sed ili manĝis la produktojn de la lando Kanaana en tiu jaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Kaj okazis, ke kiam Josuo estis apud Jeriĥo, li levis siajn okulojn, kaj ekvidis, ke jen viro staras antaŭ li kaj en sia mano li tenas nudigitan glavon. Kaj Josuo aliris al li, kaj diris al li: Ĉu vi estas nia, aŭ ĉu el niaj malamikoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Kaj tiu diris: Ne, mi estas militestro de la Eternulo, mi nun venis. Tiam Josuo ĵetis sin vizaĝaltere kaj faris adoron, kaj diris al li: Kion mia sinjoro diros al sia sklavo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Kaj la militestro de la Eternulo diris al Josuo: Demetu viajn ŝuojn de viaj piedoj; ĉar la loko, sur kiu vi staras, estas sankta. Kaj Josuo faris tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, '(Kaj Jeriĥo estis fermita kaj ŝlosita kontraŭ la Izraelidoj; neniu eliris, kaj neniu eniris.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Kaj la Eternulo diris al Josuo: Vidu, Mi transdonis en vian manon Jeriĥon kaj ĝian reĝon kaj ĝiajn fortajn militistojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Ĉirkaŭiru la urbon ĉiuj militistoj, ĉirkaŭiru la urbon unu fojon; tiel faru dum ses tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'Kaj sep pastroj portu sep trumpetojn jubileajn antaŭ la kesto; kaj en la sepa tago ĉirkaŭiru la urbon sep fojojn, kaj la pastroj sonigu per la trumpetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Kaj kiam oni ektrumpetos per la jubilea korno kaj vi ekaŭdos la sonadon de la trumpeto, tiam la tuta popolo ekkriu per laŭta voĉo; kaj la muro de la urbo falos malsupren, kaj la popolo eniru, ĉiu rekte antaŭen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Kaj Josuo, filo de Nun, alvokis la pastrojn, kaj diris al ili: Portu la keston de interligo, kaj sep pastroj portu sep jubileajn trumpetojn antaŭ la kesto de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Kaj li diris al la popolo: Iru, kaj ĉirkaŭiru la urbon, kaj la armitoj preteriru antaŭ la kesto de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Kaj post kiam Josuo tion diris al la popolo, sep pastroj, portantaj sep jubileajn trumpetojn antaŭ la Eternulo, ekiris kaj ektrumpetis per la trumpetoj; kaj la kesto de interligo de la Eternulo iris post ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Kaj la armitoj iris antaŭ la pastroj, kiuj trumpetis per la trumpetoj, kaj la resto de la popolo iris post la kesto; oni iris kaj trumpetis per trumpetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Kaj al la popolo Josuo ordonis, dirante: Ne kriu, kaj ne aŭdigu vian voĉon, kaj neniu vorto eliru el via buŝo, ĝis la tago, kiam mi diros al vi, ke vi kriu; tiam vi krios.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Kaj la kesto de la Eternulo ekiris ĉirkaŭ la urbo, ĉirkaŭiris ĝin unu fojon; kaj ili venis en la tendaron kaj tranoktis en la tendaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Kaj Josuo leviĝis frue matene, kaj la pastroj ekportis la keston de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'Kaj la sep pastroj, kiuj portis sep jubileajn trumpetojn antaŭ la kesto de la Eternulo, iris kaj senĉese trumpetis per la trumpetoj; kaj la armitoj iris antaŭ ili, kaj la resto de la popolo iris post la kesto de la Eternulo, kaj oni senĉese trumpetis per trumpetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Kaj ili ĉirkaŭiris la urbon en la dua tago unu fojon, kaj revenis en la tendaron. Tiel oni faris dum ses tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'En la sepa tago ili leviĝis frue, kiam montriĝis la matena ĉielruĝo, kaj ili ĉirkaŭiris la urbon en la sama maniero sep fojojn; en tiu sola tago ili ĉirkaŭiris la urbon sep fojojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Kaj ĉe la sepa fojo, kiam la pastroj trumpetis per la trumpetoj, Josuo diris al la popolo: Ekkriu, ĉar la Eternulo transdonis al vi la urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Kaj la urbo estu sub anatemo de la Eternulo, ĝi kaj ĉio, kio estas en ĝi; nur la malĉastistino Raĥab restu viva, ŝi kaj ĉiu, kiu estas kun ŝi en la domo; ĉar ŝi kaŝis la senditojn, kiujn ni sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Sed vi gardu vin kontraŭ la anatemitaĵo, por ke vi ne anatemiĝu, se vi prenos ion el la anatemitaĵo, kaj por ke vi ne faligu anatemon sur la tendaron de Izrael kaj ne malfeliĉigu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Kaj la tuta arĝento kaj oro, kaj ĉiuj vazoj kupraj kaj feraj, estu sanktigitaj al la Eternulo; en la trezorejon de la Eternulo ili venos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Kaj la popolo ekkriis, kaj oni ektrumpetis per trumpetoj. Kaj kiam la popolo ekaŭdis la sonadon de la trumpeto, la popolo ekkriis per laŭta voĉo; kaj la muro falis malsupren, kaj la popolo eniris en la urbon, ĉiu rekte antaŭen, kaj ili prenis la urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'Kaj ili ekstermis per glavo ĉion, kio estis en la urbo, la virojn kaj virinojn, junulojn kaj maljunulojn, bovojn kaj ŝafojn kaj azenojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Kaj al la du viroj, kiuj esplorrigardis la landon, Josuo diris: Iru en la domon de la malĉastistino, kaj elkonduku el tie la virinon, kaj ĉiujn, kiuj estas ĉe ŝi, kiel vi ĵuris al ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Kaj la junuloj esplorrigardintoj iris, kaj elkondukis Raĥabon kaj ŝian patron kaj ŝian patrinon kaj ŝiajn fratojn, kaj ĉiujn, kiuj estis ĉe ŝi, kaj ŝian tutan familion ili elkondukis, kaj starigis ilin ekster la tendaron de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Kaj la urbon oni forbruligis per fajro, kaj ĉion, kio estis en ĝi; nur la arĝenton kaj oron kaj la kuprajn kaj ferajn vazojn oni donis en la trezorejon de la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Kaj la malĉastistinon Raĥab, kaj la domon de ŝia patro, kaj ĉiujn, kiuj estis kun ŝi, Josuo lasis vivaj, kaj ŝi restis inter Izrael ĝis nun; ĉar ŝi kaŝis la senditojn, kiujn Josuo sendis por esplorrigardi Jeriĥon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Kaj en tiu tempo Josuo faris ĵuron, dirante: Malbenita antaŭ la Eternulo estu tiu viro, kiu restarigos kaj konstruos ĉi tiun urbon Jeriĥo. Sur sia unuenaskito li ĝin fondos, kaj sur sia plej juna filo li starigos ĝiajn pordegojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Kaj la Eternulo estis kun Josuo, kaj li estis fama sur la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Sed la Izraelidoj pekis kontraŭ la anatemo: Aĥan, filo de Karmi, filo de Zabdi, filo de Zeraĥ, el la tribo de Jehuda, prenis el la anatemitaĵo, kaj la kolero de la Eternulo ekflamis kontraŭ la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Kaj Josuo sendis virojn el Jeriĥo al Aj, kiu estis apud Bet-Aven, oriente de Bet-El, kaj li diris al ili jene: Iru kaj esplorrigardu la landon. Kaj la viroj iris kaj esplorrigardis Ajon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Kaj ili revenis al Josuo, kaj diris al li: Ne iru la tuta popolo, nur du mil aŭ tri mil viroj iru kaj venkobatu Ajon; ne lacigu tien la tutan popolon, ĉar ili estas malgrandnombraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Kaj iris tien el la popolo ĉirkaŭ tri mil viroj; sed ili forkuris de antaŭ la loĝantoj de Aj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'Kaj la loĝantoj de Aj mortigis el ili tridek ses homojn, kaj persekutis ilin de la pordego ĝis Ŝebarim, kaj venkobatis ilin sur la deklivo de la monto; kaj malkuraĝiĝis la koro de la popolo kaj fariĝis kiel akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Tiam Josuo disŝiris siajn vestojn, kaj ĵetis sin vizaĝaltere antaŭ la keston de la Eternulo, restante tiel ĝis la vespero, li kaj la plejaĝuloj de Izrael; kaj ili ŝutis polvon sur siajn kapojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Kaj Josuo diris: Ho, mia Sinjoro, Eternulo, kial Vi transirigis ĉi tiun popolon trans Jordanon, por transdoni nin en la manon de la Amoridoj, por pereigi nin? ho, kial ni ne restis sur tiu flanko de Jordan?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Ho, mia Sinjoro! kion mi povas diri, post kiam Izrael turnis sian dorson al siaj malamikoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Kiam aŭdos la Kanaanidoj kaj ĉiuj loĝantoj de la lando, ili ĉirkaŭos nin kaj ekstermos nian nomon de sur la tero; kaj kion Vi faros por Via granda nomo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Tiam la Eternulo diris al Josuo: Leviĝu! por kio vi ĵetis vin vizaĝaltere?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Izrael pekis, kaj ili agis kontraŭ Mia interligo, kiun Mi donis al ili, kaj ili prenis el la anatemitaĵo, kaj ŝtelis, kaj mensoge neis, kaj metis inter siajn vazojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Tial la Izraelidoj ne povos rezisti antaŭ siaj malamikoj, sian dorson ili turnos al siaj malamikoj, ĉar ili falis sub anatemon; Mi ne estos plu kun vi, se vi ne malaperigos la anatemitaĵon el inter vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Leviĝu, sanktigu la popolon, kaj diru: Sanktigu vin por morgaŭ; ĉar tiel diris la Eternulo, Dio de Izrael: Anatemitaĵo estas inter vi, Izrael; vi ne povos rezisti antaŭ viaj malamikoj, ĝis vi forigos la anatemitaĵon el inter vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Kaj vi aliros matene laŭ viaj triboj; kaj la tribo, kiun montros la Eternulo, aliros laŭ la familioj; kaj la familio, kiun montros la Eternulo, aliros laŭ la domoj; kaj la domo, kiun montros la Eternulo, aliros laŭ apartaj homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Kaj tiun, ĉe kiu montriĝos la anatemitaĵo, oni forbruligu per fajro, lin kaj ĉion, kio apartenas al li; ĉar li agis kontraŭ la interligo de la Eternulo, kaj ĉar li faris malnoblaĵon en Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Kaj Josuo leviĝis frue matene, kaj alirigis Izraelon laŭ liaj triboj; kaj la montro falis sur la tribon de Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Kaj li alirigis la tribon de Jehuda, kaj la montro falis sur la familion de la Zeraĥidoj; kaj li alirigis la familion de la Zeraĥidoj laŭ apartaj homoj, kaj la montro falis sur Zabdin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'Kaj li alirigis lian domon laŭ apartaj homoj, kaj la montro falis sur Aĥanon, filon de Karmi, filo de Zabdi, filo de Zeraĥ, el la tribo de Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Tiam Josuo diris al Aĥan: Mia filo! donu gloron al la Eternulo, Dio de Izrael, kaj faru al Li konfeson, kaj diru al mi, kion vi faris; ne kaŝu antaŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Kaj Aĥan respondis al Josuo, kaj diris: Efektive, mi pekis antaŭ la Eternulo, Dio de Izrael, kaj tiel kaj tiel mi faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'Mi vidis inter la militakiraĵo belan Ŝinaran mantelon, kaj ducent siklojn da arĝento, kaj unu stangeton da oro, havantan la pezon de kvindek sikloj, kaj mi ekdeziris ilin kaj prenis ilin; kaj nun ili estas kaŝitaj en la tero meze de mia tendo, kaj la arĝento estas sub tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Kaj Josuo sendis senditojn, kaj ili kuris en la tendon; kaj montriĝis, ke tio estas kaŝita en lia tendo kaj la arĝento estas sub tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Kaj ili prenis tion el meze de la tendo, kaj alportis al Josuo kaj al ĉiuj Izraelidoj, kaj elmetis tion antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Kaj Josuo kune kun la tuta Izrael prenis Aĥanon, filon de Zeraĥ, kaj la arĝenton kaj la mantelon kaj la stangeton da oro, kaj liajn filojn kaj liajn filinojn, kaj liajn bovojn kaj liajn azenojn kaj liajn ŝafojn, kaj lian tendon, kaj ĉion, kio apartenis al li, kaj elkondukis ilin en la valon Aĥor.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Kaj Josuo diris: Pro tio, ke vi malĝojigis nin, la Eternulo malĝojigos vin en ĉi tiu tago. Kaj la tuta Izrael mortigis lin per ŝtonoj; kaj oni forbruligis ilin per fajro, kaj ĵetis sur ilin ŝtonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Kaj oni amasigis super li grandan amason da ŝtonoj, kiu restis ĝis hodiaŭ. Kaj malaperis la flama kolero de la Eternulo. Pro tio tiu loko havas la nomon valo Aĥor ĝis hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Kaj la Eternulo diris al Josuo: Ne timu, kaj ne estu malkuraĝa; prenu kun vi ĉiujn militistojn, kaj leviĝu kaj iru al Aj; vidu, Mi transdonis en vian manon la reĝon de Aj kaj lian popolon kaj lian urbon kaj lian landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Kaj agu kun Aj kaj kun ĝia reĝo, kiel vi agis kun Jeriĥo kaj kun ĝia reĝo; nur ilian militakiraĵon kaj iliajn brutojn vi povas rabi por vi. Faru insidon malantaŭ la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Kaj leviĝis Josuo kaj ĉiuj militistoj, por iri al Aj; kaj Josuo elektis tridek mil homojn, bonajn militistojn, kaj sendis ilin nokte,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'kaj ordonis al ili, dirante: Vidu, vi faros insidon ĉe la urbo, malantaŭ la urbo; ne tro malproksimiĝu de la urbo, kaj estu ĉiuj pretaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Kaj mi, kaj la tuta popolo, kiu estas kun mi, alproksimiĝos al la urbo. Kaj kiam ili eliros kontraŭ nin, kiel antaŭe, ni forkuros de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Kaj ili eliros post ni, ĝis ni ellogos ilin el la urbo; ĉar ili diros: Ili forkuras de ni, kiel antaŭe. Kaj ni kuros de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Tiam vi leviĝu el la insido kaj ekposedu la urbon; kaj la Eternulo, via Dio, transdonos ĝin en vian manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'Kaj kiam vi okupos la urbon, ekbruligu la urbon per fajro; faru laŭ la diro de la Eternulo. Vidu, mi tion ordonas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Kaj Josuo sendis ilin, kaj ili iris en insidejon, kaj ili eksidis inter Bet-El kaj Aj, okcidente de Aj. Kaj Josuo pasigis tiun nokton meze de la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Kaj Josuo leviĝis frue matene, kaj ordigis la popolon, kaj ekiris li kaj la plejaĝuloj de Izrael antaŭ la popolo al Aj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Kaj ĉiuj militistoj, kiuj estis kun li, iris, kaj alproksimiĝis, kaj venis antaŭ la urbon, kaj starigis sian tendaron norde de Aj; kaj inter ili kaj Aj estis valo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Kaj li prenis ĉirkaŭ kvin mil homojn, kaj aranĝis ilin inside inter Bet-El kaj Aj, okcidente de Aj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Kaj la popolo starigis la tutan tendaron, kiu estis norde de la urbo, tiel, ke ĝia fina parto estis okcidente de la urbo. Kaj Josuo iris en tiu nokto en la mezon de la valo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Kiam la reĝo de Aj tion ekvidis, tiam la loĝantoj de la urbo rapide leviĝis kaj eliris kontraŭ Izraelon milite, li kaj lia tuta popolo, sur difinitan lokon antaŭ la valo. Kaj li ne sciis, ke estas kontraŭ li insido malantaŭ la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Kaj Josuo kaj la tuta Izrael ŝajnigis sin venkobatitaj de ili, kaj ekkuris en la direkto al la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Kaj ili per krio vokis la tutan popolon, kiu estis en la urbo, por persekuti ilin; kaj ili postkuris Josuon, kaj malproksimiĝis de la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'Kaj en Aj kaj en Bet-El restis neniu homo, kiu ne kuris post Izrael. Kaj ili lasis la urbon malfermita, kaj postkuris Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Kaj la Eternulo diris al Josuo: Etendu la lancon, kiu estas en via mano, kontraŭ Ajon; ĉar en vian manon Mi ĝin transdonos. Kaj Josuo etendis la lancon, kiu estis en lia mano, kontraŭ la urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Kaj la insidanoj rapide leviĝis de sia loko, kaj ekkuris, kiam li etendis sian manon, kaj ili venis en la urbon kaj okupis ĝin, kaj rapide ekbruligis la urbon per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Kaj la loĝantoj de Aj ekrigardis malantaŭen, kaj vidis, ke fumo de la urbo iras al la ĉielo. Kaj ili ne havis lokon, kien forkuri-nek tien nek ĉi tien; kaj la popolo, kiu estis kurinta al la dezerto, turniĝis kontraŭ la persekutantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Kaj kiam Josuo kaj la tuta Izrael ekvidis, ke la insidanoj okupis la urbon kaj ke leviĝas fumo de la urbo, ili turniĝis kaj ekbatis la loĝantojn de Aj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Kaj tiuj el la urbo eliris renkonte al ili, kaj ili troviĝis en la mezo inter la Izraelidoj, el kiuj unuj estis sur unu flanko kaj aliaj sur la dua flanko, kaj ili batis ilin tiel, ke neniu el ili restis kaj neniu povis forkuri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Kaj la reĝon de Aj oni kaptis vivan, kaj alkondukis lin al Josuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Kaj kiam Izrael mortigis ĉiujn loĝantojn de Aj sur la kampo, en la dezerto, kien tiuj ilin postkuris, kaj ĉiuj falis de glavo ĝis plena ekstermiĝo, tiam ĉiuj Izraelidoj reiris en la urbon Aj kaj mortigis tie ĉiujn per glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Kaj la nombro de ĉiuj falintoj en tiu tago, viroj kaj virinoj, estis dek du mil, ĉiuj loĝantoj de Aj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Kaj Josuo ne retiris sian manon, kiun li etendis kun la lanco, ĝis estis ekstermitaj ĉiuj loĝantoj de Aj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Nur la brutojn kaj la militakiraĵon de tiu urbo la Izraelidoj rabis al si, laŭ la diro de la Eternulo, kiun Li ordonis al Josuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Kaj Josuo forbruligis la urbon Aj, kaj faris ĝin eterna ruino, dezertaĵo ĝis hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Kaj la reĝon de Aj li pendigis sur arbo, kie li restis ĝis la vespero; kaj kiam la suno subiris, Josuo ordonis, kaj oni deprenis lian kadavron de la arbo, kaj ĵetis ĝin antaŭ la pordegon de la urbo, kaj amasigis super ĝi grandan amason da ŝtonoj, kiu restis ĝis hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Tiam Josuo konstruis sur la monto Ebal altaron al la Eternulo, Dio de Izrael,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'kiel ordonis Moseo, servanto de la Eternulo, al la Izraelidoj, kiel estas skribite en la libro de instruo de Moseo, altaron el ŝtonoj nehakitaj, sur kiujn oni ne levis feron. Kaj oni alportis sur ĝi bruloferojn al la Eternulo, kaj oni buĉis pacoferojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Kaj li skribis tie sur la ŝtonoj kopion de la instruo de Moseo, kiun li skribis antaŭ la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Kaj la tuta Izrael kaj liaj plejaĝuloj kaj oficistoj kaj liaj juĝistoj staris ĉe ambaŭ flankoj de la kesto, kontraŭ la pastroj Levidoj, kiuj portis la keston de interligo de la Eternulo, kiel la fremduloj, tiel ankaŭ la indiĝenoj; duono staris kontraŭ la monto Gerizim, kaj la dua duono kontraŭ la monto Ebal, kiel ordonis antaŭe Moseo, servanto de la Eternulo, por beni la popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Kaj poste li laŭte legis ĉiujn vortojn de la instruo, la benon kaj la malbenon, konforme al ĉio, kio estas skribita en la libro de la instruo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'El ĉio, kion ordonis Moseo, ne estis eĉ unu vorto, kiun ne antaŭlegis Josuo antaŭ la tuta komunumo de Izrael, kaj antaŭ la virinoj, infanoj, kaj fremduloj, kiuj estis inter ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Kaj kiam aŭdis ĉiuj reĝoj, kiuj loĝis trans Jordan, sur la monto kaj en la valo, kaj sur la tuta bordo de la Granda Maro kontraŭ Lebanon, la Ĥetidoj, kaj la Amoridoj, la Kanaanidoj, la Perizidoj, la Ĥividoj, kaj la Jebusidoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'ili kolektiĝis kune, por militi unuanime kontraŭ Josuo kaj kontraŭ Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Kaj la loĝantoj de Gibeon aŭdis, kion faris Josuo al Jeriĥo kaj al Aj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'kaj ili ankaŭ faris ruzaĵon: ili iris kaj provizis sin per manĝaĵoj, kaj metis malnovajn sakojn sur siajn azenojn kaj malnovajn disŝiritajn kaj flikitajn vinsakojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'kaj ŝuoj malnovaj kaj flikitaj estis sur iliaj piedoj, kaj vestoj malnovaj estis sur ili, kaj ilia tuta pano estis malfreŝa kaj ŝimiĝinta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Kaj ili iris al Josuo en la tendaron ĉe Gilgal, kaj diris al li kaj al la tuta Izrael: El lando malproksima ni venis; faru do kun ni interligon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Kaj la Izraelidoj diris al la Ĥividoj: Eble vi loĝas apude de ni; kiel do ni povas fari kun vi interligon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'Kaj ili diris al Josuo: Ni estas viaj sklavoj. Kaj Josuo diris al ili: Kiuj vi estas? kaj el kie vi venas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'Kaj ili diris al li: El lando tre malproksima venis viaj sklavoj pro la nomo de la Eternulo, via Dio; ĉar ni aŭdis Lian gloron, kaj ĉion, kion Li faris en Egiptujo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'kaj ĉion, kion Li faris al la du reĝoj de la Amoridoj transe de Jordan, al Siĥon, reĝo de Ĥeŝbon, kaj al Og, reĝo de Baŝan, kiu loĝis en Aŝtarot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Kaj diris al ni niaj plejaĝuloj kaj ĉiuj loĝantoj de nia lando jene: Prenu en viajn manojn manĝaĵon por la vojo, kaj iru renkonte al ili, kaj diru al ili: Ni estas viaj sklavoj; faru do kun ni interligon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Ĉi tiu nia pano estis varma, kiam ni prenis ĝin provize el niaj domoj en la tago, en kiu ni eliris, por iri al vi; kaj nun jen ĝi malfreŝiĝis kaj ŝimiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Kaj ĉi tiuj niaj felsakoj kun vino, kiujn ni plenigis novajn, jen ili disfendiĝis; kaj ĉi tiuj niaj vestoj kaj ŝuoj malnoviĝis pro la tre longa vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Tiam la homoj prenis iom el ilia pano, kaj la Eternulon ili ne demandis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Kaj Josuo faris pacon kun ili, kaj starigis interligon kun ili, por lasi ilin vivaj; kaj la ĉefoj de la komunumo ĵuris al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Sed post paso de tri tagoj, post kiam ili faris kun ili interligon, ili ekaŭdis, ke ili estas iliaj najbaroj kaj loĝas apude de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Kaj la Izraelidoj elmoviĝis, kaj venis al iliaj urboj en la tria tago; iliaj urboj estis Gibeon kaj Kefira kaj Beerot kaj Kirjat-Jearim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Kaj la Izraelidoj ne batis ilin, ĉar la estroj de la komunumo ĵuris al ili per la Eternulo, Dio de Izrael. Kaj la tuta komunumo ekmurmuris kontraŭ la estroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Kaj ĉiuj estroj diris al la tuta komunumo: Ni ĵuris al ili per la Eternulo, Dio de Izrael, kaj nun ni ne povas tuŝi ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'tion ni faros al ili: ni lasu ilin vivaj, por ke ne trafu nin kolero pro la ĵuro, kiun ni ĵuris al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Kaj la estroj diris al ili: Ili vivu. Kaj ili fariĝis lignohakistoj kaj akvoportistoj por la tuta komunumo, kiel diris al ili la estroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Kaj Josuo alvokis ilin, kaj diris al ili jene: Kial vi nin trompis, dirante, ke vi estas tre malproksimaj de ni, dum vi loĝas apude de ni?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'estu do nun malbenitaj: ne ĉesiĝu inter vi sklavoj kaj lignohakistoj kaj akvoportistoj por la domo de mia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Kaj ili respondis al Josuo kaj diris: Estis dirite al viaj sklavoj, ke la Eternulo, via Dio, promesis al Sia servanto Moseo, ke Li donos al vi la tutan landon kaj ekstermos antaŭ vi ĉiujn loĝantojn de la lando; tial ni tre ektimis antaŭ vi pri nia vivo, kaj ni faris tiun aferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Kaj nun jen ni estas en via mano: kiel vi trovas bona kaj justa agi kun ni, tiel agu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'Kaj li agis kun ili tiel: li savis ilin kontraŭ la manoj de la Izraelidoj, kaj ĉi tiuj ne mortigis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'Sed Josuo destinis al ili en tiu tago, ke ili estu lignohakistoj kaj akvoportistoj por la komunumo kaj por la altaro de la Eternulo, ĝis la nuna tago, sur la loko, kiun Li elektos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Kiam Adoni-Cedek, reĝo de Jerusalem, aŭdis, ke Josuo prenis Ajon kaj ekstermis ĝin; ke kiel li agis kun Jeriĥo kaj kun ĝia reĝo, tiel li agis kun Aj kaj kun ĝia reĝo; kaj ke la loĝantoj de Gibeon faris pacon kun Izrael kaj restis inter ili:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'tiam ili tre ektimis; ĉar Gibeon estis urbo granda, kiel unu el la reĝaj urboj, kaj ĝi estis pli granda ol Aj, kaj ĉiuj ĝiaj loĝantoj estis homoj fortaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Kaj Adoni-Cedek, reĝo de Jerusalem, sendis al Hoham, reĝo de Ĥebron, kaj al Piram, reĝo de Jarmut, kaj al Jafia, rego de Laĥiŝ, kaj al Debir, reĝo de Eglon, por diri:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Venu al mi kaj helpu min, ke ni venkobatu Gibeonon pro tio, ke ĝi faris pacon kun Josuo kaj kun la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Kaj kuniĝis kaj iris la kvin reĝoj de la Amoridoj, la reĝo de Jerusalem, la reĝo de Ĥebron, la reĝo de Jarmut, la reĝo de Laĥiŝ, la reĝo de Eglon, ili kaj ilia tuta militistaro; kaj ili starigis tendarojn ĉirkaŭ Gibeon kaj ekmilitis kontraŭ ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Tiam la loĝantoj de Gibeon sendis al Josuo en la tendaron ĉe Gilgal, por diri: Ne forprenu viajn manojn de viaj sklavoj; venu al ni rapide kaj savu nin kaj helpu nin, ĉar kolektiĝis kontraŭ ni ĉiuj reĝoj de la Amoridoj, kiuj loĝas sur la monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Kaj Josuo eliris el Gilgal, li kaj la tuta militistaro kun li, kaj ĉiuj militotaŭguloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Kaj la Eternulo diris al Josuo: Ne timu ilin; ĉar en vian manon Mi transdonis ilin; neniu el ili povos rezisti antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Kaj Josuo venis al ili neatendite; la tutan nokton li iris el Gilgal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'Kaj la Eternulo konfuzegis ilin antaŭ Izrael, kaj ĉi tiu batis ilin per granda venkobato en Gibeon, kaj persekutis ilin laŭ la vojo, kiu suprenkondukas al Bet-Ĥoron, kaj batis ilin ĝis Azeka kaj ĝis Makeda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Kaj kiam ili, forkurante de la Izraelidoj, estis sur la deklivo de Bet- Ĥoron, la Eternulo ĵetadis sur ilin grandajn ŝtonojn el la ĉielo, ĝis Azeka, kaj ili mortis; pli granda estis la nombro de tiuj, kiuj mortis de la ŝtonoj de hajlo, ol la nombro de tiuj, kiujn la Izraelidoj mortigis per la glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Tiam Josuo parolis al la Eternulo en la tago, en kiu la Eternulo transdonis la Amoridojn al la Izraelidoj; kaj li diris antaŭ la ĉeestanta Izrael: Suno, haltu super Gibeon, Kaj luno super la valo de Ajalon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Kaj la suno haltis, kaj la luno staris tiel longe, Kiel la popolo faris venĝon al siaj malamikoj. Tio estas ja skribita en la libro de la Justulo. Kaj la suno staris meze de la ĉielo, kaj ne rapidis subiri preskaŭ dum tuta tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Kaj nek antaŭe nek poste estis tago simila al tiu, en kiu la Eternulo obeis la voĉon de homo; ĉar la Eternulo batalis por Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Kaj Josuo kune kun la tuta Izrael revenis en la tendaron ĉe Gilgal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Kaj forkuris tiuj kvin reĝoj kaj kaŝis sin en kaverno en Makeda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Kaj oni sciigis al Josuo, dirante: Estas trovitaj la kvin reĝoj, kaŝitaj en kaverno en Makeda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Tiam Josuo diris: Alrulu grandajn ŝtonojn al la aperturo de la kaverno, kaj starigu ĉe ĝi homojn, por gardi ĝin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'sed vi ne haltu, persekutu viajn malamikojn kaj ekstermu iliajn malantaŭajn taĉmentojn; ne permesu al ili veni en iliajn urbojn; ĉar la Eternulo, via Dio, transdonis ilin en viajn manojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Kaj kiam Josuo kaj la Izraelidoj finis bati ilin per tre granda venkobato ĝis preskaŭ plena ekstermo, kaj la restintoj el ili forkuris en la fortikigitajn urbojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'kaj la tuta popolo revenis al Josuo en la tendaron en Makedan sendifekta, kaj neniu movis sian langon kontraŭ la Izraelidojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'tiam Josuo diris: Malfermu la aperturon de la kaverno, kaj elkonduku al mi tiujn kvin reĝojn el la kaverno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'Kaj oni faris tiel, kaj oni elkondukis al li tiujn kvin reĝojn el la kaverno: la reĝon de Jerusalem, la reĝon de Ĥebron, la reĝon de Jarmut, la reĝon de Laĥiŝ, la reĝon de Eglon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Kaj kiam oni elkondukis tiujn reĝojn al Josuo, tiam Josuo alvokis ĉiujn Izraelidojn, kaj diris al la estroj de la militistoj, kiuj iris kun li: Alproksimiĝu, metu viajn piedojn sur la kolojn de ĉi tiuj reĝoj; kaj ili aliris, kaj metis siajn piedojn sur iliajn kolojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Kaj Josuo diris al ili: Ne timu kaj ne tremu, estu fortaj kaj kuraĝaj; ĉar tiel la Eternulo faros al ĉiuj viaj malamikoj, kontraŭ kiuj vi militas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Kaj poste Josuo frapis ilin, kaj mortigis ilin, kaj pendigis ilin sur kvin arboj; kaj ili pendis sur la arboj ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Kaj post la subiro de la suno Josuo ordonis, kaj oni deprenis ilin de la arboj, kaj ĵetis ilin en la kavernon, en kiu ili estis kaŝintaj sin; kaj oni almetis al la aperturo de la kaverno grandajn ŝtonojn, kiuj restis ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Kaj Makedan Josuo prenis en tiu sama tago, kaj batis ĝin per glavo, ankaŭ ĝian reĝon; kaj li ekstermis ilin kaj ĉion vivantan, kio estis en ĝi; li lasis neniun restanton. Kaj li agis kun la reĝo de Makeda, kiel li agis kun la reĝo de Jeriĥo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Kaj Josuo kune kun la tuta Izrael transiris el Makeda al Libna, kaj militis kontraŭ Libna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'Kaj la Eternulo transdonis ankaŭ ĝin kaj ĝian reĝon en la manon de Izrael; kaj li per glavo batis ĝin kaj ĉion vivantan, kio estis en ĝi; li lasis en ĝi neniun restanton. Kaj li agis kun ĝia reĝo, kiel li agis kun la reĝo de Jeriĥo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Kaj Josuo kune kun la tuta Izrael transiris el Libna al Laĥiŝ, kaj starigis tendaron ĉirkaŭ ĝi, kaj militis kontraŭ ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Kaj la Eternulo transdonis Laĥiŝon en la manon de Izrael, kaj li prenis ĝin en la dua tago, kaj per glavo ekstermis ĝin kaj ĉion vivantan en ĝi, simile al ĉio, kion li faris al Libna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Tiam venis Horam, reĝo de Gezer, por alporti helpon al Laĥiŝ; sed Josuo venkobatis lin kaj lian popolon tiel, ke li lasis al li neniun restanton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Kaj Josuo kune kun la tuta Izrael transiris el Laĥiŝ al Eglon, kaj starigis tendaron ĉirkaŭ ĝi, kaj militis kontraŭ ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'Kaj ili prenis ĝin en tiu tago, kaj ekstermis ĝin per glavo, kaj ĉion vivantan en ĝi li ekstermis en tiu tago, simile al ĉio, kion li faris al Laĥiŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Kaj Josuo kune kun la tuta Izrael iris el Eglon al Ĥebron, kaj militis kontraŭ ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'Kaj ili prenis ĝin, kaj per glavo ekstermis ĝin kaj ĝian reĝon kaj ĉiujn ĝiajn urbojn kaj ĉion vivantan, kio estis en ĝi; li lasis neniun restanton, simile al ĉio, kion li faris al Eglon; kaj li ekstermis ĝin, kaj ĉion, kio vivis en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Kaj Josuo kune kun la tuta Izrael iris returne al Debir, kaj militis kontraŭ ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'Kaj li prenis ĝin kaj ĝian reĝon kaj ĉiujn ĝiajn urbojn, kaj batis ilin per glavo, kaj ekstermis ĉion vivantan, kio estis en ĝi; li lasis neniun restanton; kiel li faris al Ĥebron, tiel li faris al Debir kaj al ĝia reĝo, kaj kiel li faris al Libna kaj al ĝia reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Kaj Josuo venkobatis la tutan landon sur la monto, kaj la sudan kaj la malaltan kaj la deklivan, kaj ĉiujn iliajn reĝojn; li lasis neniun restanton, kaj li ekstermis ĉion vivantan, kiel ordonis la Eternulo, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Kaj Josuo batis ilin de Kadeŝ-Barnea ĝis Gaza, kaj la tutan landon Goŝen, ĝis Gibeon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Kaj ĉiujn tiujn reĝojn kaj iliajn landojn Josuo prenis per unu fojo; ĉar la Eternulo, Dio de Izrael, batalis por Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Kaj Josuo kune kun la tuta Izrael revenis en la tendaron, en Gilgalon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Kiam tion aŭdis Jabin, reĝo de Ĥacor, li sendis al Jobab, reĝo de Madon, kaj al la reĝo de Ŝimron kaj al la reĝo de Aĥŝaf,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'kaj al la reĝoj, kiuj loĝis norde sur la monto, kaj sur la stepo sude de Kinerot, kaj sur la malaltaĵo, kaj en Nafot-Dor apud la maro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'al la Kanaanidoj oriente kaj okcidente, kaj al la Amoridoj kaj Ĥetidoj kaj Perizidoj, kaj Jebusidoj sur la monto, kaj al la Ĥividoj sub Ĥermon en la lando Micpa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Kaj eliris ili kaj ilia tuta militistaro kun ili, granda nombro da homoj, kiel la sablo sur la bordo de la maro, kaj tre multe da ĉevaloj kaj ĉaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Kaj kuniĝis ĉiuj tiuj reĝoj, kaj venis kaj starigis siajn tendarojn kune apud la akvo Merom, por batali kontraŭ Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Kaj la Eternulo diris al Josuo: Ne timu ilin, ĉar morgaŭ en ĉi tiu tempo Mi transdonos ilin ĉiujn mortigotajn al Izrael; iliajn ĉevalojn vi lamigos, kaj iliajn ĉarojn vi forbruligos per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Kaj eliris kontraŭ ilin Josuo kune kun ĉiuj militistoj subite al la akvo Merom, kaj ĵetis sin sur ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'Kaj la Eternulo transdonis ilin en la manojn de la Izraelidoj, kaj ĉi tiuj batis ilin, kaj persekutis ilin ĝis Granda Cidon kaj ĝis Misrefot- Maim, kaj ĝis la valo de Micpe oriente, kaj batis ilin tiel, ke ili lasis al ili neniun restanton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Kaj Josuo agis kun ili tiel, kiel diris al li la Eternulo: iliajn ĉevalojn li lamigis, kaj iliajn ĉarojn li forbruligis per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Kaj en tiu tempo Josuo iris returne, kaj prenis Ĥacoron, kaj ĝian reĝon li mortigis per glavo; ĉar Ĥacor antaŭe estis la ĉefa el ĉiuj tiuj regnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Kaj ili mortigis per glavo ĉion vivantan, kio estis en ĝi; ili ekstermis tiel, ke restis neniu animo; kaj Ĥacoron li forbruligis per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Kaj ĉiujn urbojn de tiuj reĝoj kaj ĉiujn iliajn reĝojn Josuo prenis, kaj mortigis ilin per glavo, ekstermis ilin, kiel ordonis Moseo, servanto de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Sed ĉiujn urbojn, kiuj staris sur montetoj, la Izraelidoj ne forbruligis; nur Ĥacoron solan Josuo forbruligis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Kaj la tutan akireblaĵon el tiuj urboj kaj la brutojn la Izraelidoj rabis al si; nur ĉiujn homojn ili mortigis per glavo, ĝis ili ekstermis ilin, restigante neniun animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Kiel la Eternulo ordonis al Sia servanto Moseo, tiel Moseo ordonis al Josuo, kaj tiel faris Josuo; li mankigis nenion el ĉio, kion la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Tiamaniere Josuo prenis tiun tutan landon, la monton kaj la tutan sudan parton kaj la tutan landon Goŝen kaj la malaltaĵon kaj la stepon kaj la monton de Izrael kun ĝia bazo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'de la monto Ĥalak, kiu leviĝas en la direkto al Seir, ĝis Baal-Gad en la valo de Lebanon, sub la monto Ĥermon; kaj ĉiujn iliajn reĝojn li prenis, kaj batis ilin kaj mortigis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Dum longa tempo Josuo militis kontraŭ ĉiuj tiuj reĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Ne ekzistis urbo, kiu faris pacon kun la Izraelidoj, krom la Ĥividoj, loĝantoj en Gibeon; ĉiujn ili prenis per milito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Ĉar de la Eternulo venis la obstiniĝo de ilia koro al milito kontraŭ Izrael, por ekstermi ilin, por ke ne estu indulgo por ili, sed por ekstermi ilin plene, kiel la Eternulo ordonis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'Kaj en tiu tempo venis Josuo, kaj ekstermis la Anakidojn sur la monto, en Ĥebron, en Debir, en Anab, kaj sur la tuta monto de Jehuda kaj sur la monto de Izrael; kun iliaj urboj Josuo ekstermis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Ne restis Anakidoj en la lando de la Izraelidoj; nur en Gaza, en Gat, kaj en Aŝdod ili restis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Tiamaniere Josuo prenis la tutan landon, konforme al ĉio, kion la Eternulo diris al Moseo; kaj Josuo donis ĝin kiel heredan posedaĵon al Izrael, laŭ iliaj partoj, laŭ iliaj triboj. Kaj la lando trankviliĝis de milito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Kaj jen estas la reĝoj de la lando, kiujn venkobatis la Izraelidoj, kaj kies landon ili ekposedis transe de Jordan oriente, de la torento Arnon ĝis la monto Ĥermon, kaj la tutan stepon en la oriento:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Siĥon, reĝo de la Amoridoj, kiu loĝis en Ĥeŝbon, kaj regis de Aroer, kiu troviĝas sur la bordo de la torento Arnon, la mezon de la valo, kaj duonon de Gilead, ĝis la torento Jabok, limo de la Amonidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'kaj la stepon ĝis la maro Kinerot, oriente, kaj ĝis la maro de la stepo, la Sala Maro, oriente en la direkto al Bet-Jeŝimot, kaj sude la bazon de la deklivo de Pisga;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'kaj la regiono de Og, reĝo de Baŝan, restinto el la Rafaidoj, kiu loĝis en Aŝtarot kaj Edrei,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'kaj regis la monton Ĥermon kaj Salĥan kaj la tutan Baŝanon ĝis la limo de la Geŝuridoj kaj Maaĥatidoj, kaj duonon de Gilead ĝis la limo de Siĥon, reĝo de Ĥeŝbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Moseo, servanto de la Eternulo, kaj la Izraelidoj venkobatis ilin; kaj Moseo, servanto de la Eternulo, donis la landon kiel posedaĵon al la Rubenidoj kaj al la Gadidoj kaj al la duontribo de Manase.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Kaj jen estas la reĝoj de la lando, kiujn venkobatis Josuo kaj la Izraelidoj transe de Jordan, okcidente, de Baal-Gad en la valo de Lebanon, ĝis la monto Ĥalak, kiu leviĝas en la direkto al Seir; kaj Josuo donis ĝin al la triboj de Izrael kiel posedaĵon laŭ iliaj partoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'sur la monto kaj sur la malaltaĵo kaj en la stepo kaj sur la deklivoj kaj en la dezerto kaj sude, la Ĥetidoj, la Amoridoj, kaj la Kanaanidoj, la Perizidoj, la Ĥividoj, kaj la Jebusidoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'la reĝo de Jeriĥo, unu; la reĝo de Aj, kiu estas flanke de Bet-El, unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'la reĝo de Jerusalem, unu; la reĝo de Ĥebron, unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'la reĝo de Jarmut, unu; la reĝo de Laĥiŝ, unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'la reĝo de Eglon, unu; la reĝo de Gezer, unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'la reĝo de Debir, unu; la reĝo de Geder, unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'la reĝo de Ĥorma, unu; la reĝo de Arad, unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'la reĝo de Libna, unu; la reĝo de Adulam, unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'la reĝo de Makeda, unu; la reĝo de Bet-El, unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'la reĝo de Tapuaĥ, unu; la reĝo de Ĥefer, unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'la reĝo de Afek, unu; la reĝo de Laŝaron, unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'la reĝo de Madon, unu; la reĝo de Ĥacor, unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'la reĝo de Ŝimron-Meron, unu; la reĝo de Aĥŝaf, unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'la reĝo de Taanaĥ, unu; la reĝo de Megido, unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'la reĝo de Kedeŝ, unu; la reĝo de Jokneam ĉe Karmel, unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'la reĝo de Dor en Nafot-Dor, unu; la reĝo de la popoloj en Gilgal, unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'la reĝo de Tirca, unu. La nombro de ĉiuj reĝoj estis tridek unu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Josuo maljuniĝis, atingis profundan aĝon, kaj la Eternulo diris al li: Vi maljuniĝis, atingis profundan aĝon, kaj da tero restas ankoraŭ tre multe por ekposedi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Jen estas la tero, kiu restas: ĉiuj regionoj de la Filiŝtoj, kaj la tuta lando de la Geŝuridoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'komencante de Ŝiĥor, kiu estas antaŭ Egiptujo, ĝis la limoj de Ekron norde, kiu estas alkalkulata al la lando de la Kanaanidoj; kvin regantoj Filiŝtaj: de Gaza, kaj de Aŝdod, de Aŝkelon, de Gat, kaj de Ekron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'kaj la Avidoj sude; la tuta lando de la Kanaanidoj, kaj Meara de la Cidonanoj, ĝis Afek, ĝis la limoj de la Amoridoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'kaj la lando de la Gebalanoj, kaj la tuta Lebanon oriente de Baal-Gad, sub la monto Ĥermon, ĝis Ĥamat;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'ĉiuj loĝantoj de la montoj, de Lebanon ĝis Misrefot-Maim, ĉiuj Cidonanoj. Mi forpelos ilin de antaŭ la Izraelidoj; dividu ĉion kiel partojn heredajn por Izrael, kiel Mi ordonis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Kaj nun dividu ĉi tiun landon en heredajn partojn por la naŭ triboj kaj por la duontribo de Manase.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Kun ĉi tiu tribo la Rubenidoj kaj la Gadidoj prenis sian heredan parton, kiun donis al ili Moseo transe de Jordan oriente, kiel donis al ili Moseo, servanto de la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'de Aroer, kiu estas sur la bordo de la torento Arnon, kaj la urbon, kiu estas meze de la valo, kaj la tutan ebenaĵon Medba ĝis Dibon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'kaj ĉiujn urbojn de Siĥon, reĝo de la Amoridoj, kiu regis en Ĥeŝbon, ĝis la limo de la Amonidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'kaj Gileadon, kaj la regionon de la Geŝuridoj kaj Maaĥatidoj, kaj la tutan monton Ĥermon, kaj la tutan Baŝanon ĝis Salĥa;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'la tutan regnon de Og en Baŝan, kiu regis en Aŝtarot kaj Edrei. Li restis el la Rafaidoj. Kaj Moseo venkobatis ilin, kaj forpelis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Sed la Izraelidoj ne forpelis la Geŝuridojn kaj la Maaĥatidojn; kaj la Geŝuridoj kaj Maahatidoj restis inter la Izraelidoj ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Nur al la tribo de Levi li ne donis heredan parton; la fajroferoj de la Eternulo, Dio de Izrael, estas ilia hereda parto, kiel Li diris al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Kaj Moseo donis al la tribo de la Rubenidoj laŭ iliaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'Kaj ilia regiono estis de Aroer, kiu estas sur la bordo de la torento Arnon, kaj la urbo, kiu estas meze de la valo, kaj la tuta ebenaĵo ĝis Medba,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Ĥeŝbon, kaj ĉiuj ĝiaj urboj, kiuj estas sur la ebenaĵo, Dibon kaj Bamot-Baal kaj Bet-Baal-Meon');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'kaj Jahac kaj Kedemot kaj Mefaat');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'kaj Kirjataim kaj Sibma kaj Ceret-Ŝaĥar sur la monto Emek');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'kaj Bet-Peor kaj la deklivoj de Pisga kaj Bet-Jeŝimot,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'kaj ĉiuj urboj de la ebenaĵo, kaj la tuta regno de Siĥon, reĝo de la Amoridoj, kiu regis en Ĥeŝbon, kaj kiun mortigis Moseo, kiel ankaŭ la Midjanajn princojn Evi kaj Rekem kaj Cur kaj Ĥur kaj Reba, princojn de Siĥon, kiuj loĝis en la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Kaj Bileamon, filon de Beor, la sorĉiston, mortigis la Izraelidoj per glavo kune kun la aliaj mortigitoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Kaj limo de la Rubenidoj estis Jordan kaj ĝia regiono. Tio estas la posedaĵo de la Rubenidoj laŭ iliaj familioj, la urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Kaj Moseo donis al la tribo de Gad, al la Gadidoj, laŭ iliaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'Kaj ilia regiono estis Jazer, kaj ĉiuj urboj de Gilead, kaj duono de la lando de la Amonidoj, ĝis Aroer, kiu estas antaŭ Raba;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'kaj de Ĥeŝbon ĝis Ramat-Micpe, kaj Betonim; kaj de Maĥanaim ĝis la limo de Debir;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'kaj en la valo, Bet-Haram kaj Bet-Nimra kaj Sukot kaj Cafon, la restaĵo de la regno de Siĥon, reĝo de Ĥeŝbon; limo estis Jordan ĝis la fino de la maro Kineret, transe de Jordan, oriente.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Tio estas la posedaĵo de la Gadidoj laŭ iliaj familioj, la urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Kaj Moseo donis al la duontribo de Manase; kaj tio estis por la duontribo de Manase laŭ iliaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'Kaj ilia regiono estis: de Maĥanaim la tuta Baŝan, la tuta regno de Og, reĝo de Baŝan, kaj ĉiuj Vilaĝoj de Jair, kiuj estas en Baŝan, sesdek urboj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'kaj duono de Gilead, kaj Aŝtarot kaj Edrei, urboj de la regno de Og en Baŝan, estis donitaj al la idoj de Maĥir, filo de Manase, al duono de la idoj de Maĥir laŭ iliaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Tio estas, kion Moseo disdividis sur la stepoj de Moab, transe de Jordan, antaŭ Jeriĥo, oriente.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Sed al la tribo de Levi Moseo ne donis posedaĵon: la Eternulo, Dio de Izrael, estas ilia hereda parto, kiel Li diris al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Kaj jen estas, kion la Izraelidoj ekposedis en la lando Kanaana, kaj kion posedigis al ili la pastro Eleazar, kaj Josuo, filo de Nun, kaj la familiestroj de la triboj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'Laŭ loto ili donis posedaĵon, kiel ordonis la Eternulo per Moseo, al la naŭ triboj kaj duono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Ĉar Moseo donis al du triboj kaj duono posedaĵon transe de Jordan; kaj al la Levidoj li ne donis posedaĵon inter ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'ĉar la idoj de Jozef estis du triboj, Manase kaj Efraim; kaj al la Levidoj oni ne donis parton en la lando, sed nur urbojn por loĝado, kune kun iliaj antaŭurboj por iliaj brutoj kaj por ilia havo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Kiel la Eternulo ordonis al Moseo, tiel faris la Izraelidoj kaj dividis la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Kaj aliris la idoj de Jehuda al Josuo en Gilgal, kaj diris al li Kaleb, filo de Jefune, Kenizido: Vi scias tion, kion la Eternulo diris al Moseo, la homo de Dio, pri mi kaj pri vi en Kadeŝ-Barnea.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Mi havis la aĝon de kvardek jaroj, kiam Moseo, servanto de la Eternulo, sendis min el Kadeŝ-Barnea, por esplorrigardi la landon; kaj mi alportis al li raporton laŭ mia konscienco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Kaj miaj fratoj, kiuj iris kun mi, malkuraĝigis la koron de la popolo; sed mi obeis la Eternulon, mian Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Kaj Moseo ĵuris en tiu tago, dirante: La tero, sur kiu paŝis via piedo, estos posedaĵo por vi kaj por viaj filoj eterne, ĉar vi obeis la Eternulon, mian Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Kaj nun jen la Eternulo konservis min viva, kiel Li diris. Nun pasis kvardek kvin jaroj de tiu tempo, kiam la Eternulo diris tion al Moseo, dum Izrael iradis en la dezerto; kaj nun jen mi havas la aĝon de okdek kvin jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'Ankoraŭ hodiaŭ mi estas tiel forta, kiel en la tago, kiam Moseo min sendis; kiom da forto mi tiam havis, tiom mi nun havas por la milito, por eliri kaj eniri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Donu do al mi nun ĉi tiun monton, pri kiu la Eternulo parolis en tiu tago; ĉar vi aŭdis en tiu tago, ke tie estas Anakidoj kaj grandaj kaj fortikigitaj urboj; eble la Eternulo estos kun mi kaj mi forpelos ilin, kiel diris la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Tiam Josuo benis lin, kaj donis Ĥebronon al Kaleb, filo de Jefune, kiel posedaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Tial Ĥebron fariĝis posedaĵo de Kaleb, filo de Jefune, la Kenizido, ĝis la nuna tago; pro tio, ke li obeis la Eternulon, Dion de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Kaj la nomo de Ĥebron antaŭe estis urbo de Arba, granda homo inter la Anakidoj. Kaj la tero trankviliĝis de milito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'La lotaĵo de la tribo de la Jehudaidoj laŭ iliaj familioj estis: ĉe la limo de Edom la dezerto Cin, sude, en la suda fino de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Ilia suda limo estis de la fino de la Sala Maro, de la golfo, kiu direktiĝas suden.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'Kaj ĝi iras de sude al la altaĵo Akrabim kaj pasas tra Cin kaj leviĝas de sude ĝis Kadeŝ-Barnea kaj pasas tra Ĥecron kaj leviĝas ĝis Adar kaj turniĝas al Karka');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'kaj pasas tra Acmon kaj iras al la torento Egipta; kaj la fino de la limo estas la maro. Tio estu por vi la limo suda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Kaj la limo oriente estas la Sala Maro ĝis la fino de Jordan; kaj la limo de la flanko norda estas de la golfo de la maro ĉe la fino de Jordan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'kaj la limo leviĝas al Bet-Ĥogla kaj pasas norde al Bet-Araba, kaj la limo leviĝas al la ŝtono de Bohan, filo de Ruben.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'Kaj la limo leviĝas al Debir de la valo Aĥor, kaj norde ĝi turniĝas al Gilgal, kiu estas kontraŭ la altaĵo Adumim, kiu estas sude de la torento; kaj la limo pasas al la akvo En-Ŝemeŝ kaj finiĝas ĉe En-Rogel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Kaj la limo leviĝas al la valo de la filo de Hinom, ĉe la suda flanko de la Jebusidoj, kio estas Jerusalem, kaj la limo leviĝas al la supro de la monto, kiu estas okcidente kontraŭ la valo de Hinom, kiu estas ĉe la fino de la valo Refaim norde.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'Kaj de la supro de la monto la limo turniĝas al la fonto de la akvo Neftoaĥ kaj iras al la urboj de la monto Efron; kaj la limo turniĝas al Baala, kiu estas Kirjat-Jearim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Kaj la limo turniĝas de Baala okcidenten al la monto Ŝeir, kaj iras preter la norda flanko de la monto Jearim, kiu estas Kesalon, kaj malleviĝas al Bet-Ŝemeŝ kaj iras al Timna;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'kaj la limo iras preter la norda flanko de Ekron; kaj la limo turniĝas al Ŝikron kaj pasas tra la monto Baala kaj iras al Jabneel; kaj la fino de la limo estas ĉe la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'La okcidenta limo estas la Granda Maro. Ĉi tiu limo estas la limo de la Jehudaidoj ĉirkaŭe, laŭ iliaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Kaj al Kaleb, filo de Jefune, estis donita parto meze de la Jehudaidoj, laŭ la diro de la Eternulo al Josuo, la urbo de Arba, patro de Anak (tio estas Ĥebron).');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Kaj Kaleb elpelis el tie la tri filojn de Anak: Ŝeŝaj kaj Aĥiman kaj Talmaj, la naskitojn de Anak.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'Kaj de tie li iris al la loĝantoj de Debir; la nomo de Debir antaŭe estis Kirjat-Sefer.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Kaj Kaleb diris: Kiu venkobatos Kirjat-Seferon kaj prenos ĝin, al tiu mi donos mian filinon Aĥsa kiel edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Kaj prenis ĝin Otniel, filo de Kenaz, frato de Kaleb; kaj li donis al li sian filinon Aĥsa kiel edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Kaj kiam ŝi venis, ŝi instigis lin peti de ŝia patro kampon. Kaj ŝi malsupreniĝis de la azeno, kaj Kaleb diris al ŝi: Kio estas al vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Kaj ŝi diris: Donu al mi benon; ĉar vi donis al mi teron sudflankan, tial donu al mi ankaŭ akvofontojn. Kaj li donis al ŝi fontojn suprajn kaj fontojn malsuprajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Jen estas la posedaĵo de la tribo de la Jehudaidoj laŭ iliaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Kaj la urboj ĉe la rando de la tribo de la Jehudaidoj, apud la limo de Edom sude, estis: Kabceel kaj Eder kaj Jagur');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'kaj Kina kaj Dimona kaj Adada');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'kaj Kedeŝ kaj Ĥacor kaj Jitnan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Zif kaj Telem kaj Bealot');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'kaj Ĥacor-Ĥadata kaj Keriot-Ĥecron (tio estas Ĥacor),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam kaj Ŝema kaj Molada');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'kaj Ĥacar-Gada kaj Ĥeŝmon kaj Bet-Pelet');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'kaj Ĥacar-Ŝual kaj Beer-Ŝeba kaj Bizjotja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baala kaj Ijim kaj Ecem');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'kaj Eltolad kaj Kesil kaj Ĥorma');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'kaj Ciklag kaj Madmana kaj Sansana');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'kaj Lebaot kaj Ŝilĥim kaj Ain kaj Rimon. La nombro de ĉiuj urboj estis dudek naŭ kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'Sur la malaltaĵo: Eŝtaol kaj Corea kaj Aŝna');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'kaj Zanoaĥ kaj En-Ganim, Tapuaĥ kaj Enam,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmut kaj Adulam, Soĥo kaj Azeka');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'kaj Ŝaaraim kaj Aditaim kaj Gedera kaj Gederotaim: dek kvar urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Cenan kaj Ĥadaŝa kaj Migdal-Gad');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'kaj Dilan kaj Micpe kaj Jokteel,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Laĥiŝ kaj Bockat kaj Eglon');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'kaj Kabon kaj Laĥmas kaj Kitliŝ');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'kaj Gederot, Bet-Dagon kaj Naama kaj Makeda: dek ses urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna kaj Eter kaj Aŝan');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'kaj Jiftaĥ kaj Aŝna kaj Necib');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'kaj Keila kaj Aĥzib kaj Mareŝa: naŭ urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ekron kaj ĝiaj urbetoj kaj ĝiaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'De Ekron ĝis la maro ĉio, kio estas ĉirkaŭ Aŝdod kaj ĝiaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Aŝdod, ĝiaj urbetoj kaj ĝiaj vilaĝoj; Gaza, ĝiaj urbetoj kaj ĝiaj vilaĝoj, ĝis la torento Egipta; kaj la Granda Maro estas la limo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'Kaj sur la monto: Ŝamir kaj Jatir kaj Soĥo');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'kaj Dana kaj Kirjat-Sana (tio estas Debir)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'kaj Anab kaj Eŝtemo kaj Anim');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'kaj Goŝen kaj Ĥolon kaj Gilo: dek unu urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab kaj Duma kaj Eŝan');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'kaj Janum kaj Bet-Tapuaĥ kaj Afeka');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'kaj Ĥumta kaj Kirjat-Arba (tio estas Ĥebron) kaj Cior; naŭ urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maon, Karmel kaj Zif kaj Juta');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'kaj Jizreel kaj Jokdeam kaj Zanoaĥ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kain, Gibea kaj Timna: dek urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Ĥalĥul, Bet-Cur kaj Gedor');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'kaj Maarat kaj Bet-Anot kaj Eltekon: ses urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kirjat-Baal (tio estas Kirjat-Jearim) kaj Raba: du urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'En la dezerto: Bet-Araba kaj Midin kaj Seĥaĥa');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'kaj Nibŝan kaj la Urbo de Salo kaj En-Gedi: ses urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Sed la Jebusidojn, loĝantojn de Jerusalem, la Jehudaidoj ne povis forpeli; kaj la Jebusidoj restis kun la Jehudaidoj en Jerusalem ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Kaj la loto por la Jozefidoj donis: de Jordan kontraŭ Jeriĥo, ĉe la akvo de Jeriĥo, orienten, la dezerton, kiu etendiĝas de Jeriĥo ĝis la monto Bet-El.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'Kaj la limo iras de Bet-El ĝis Luz, kaj transiras ĝis la limo de la Arkanoj al Atarot;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'kaj ĝi malleviĝas okcidenten al la limo de la Jafletidoj, ĝis la limo de la malsupra Bet-Ĥoron kaj ĝis Gezer; kaj ĝi finiĝas ĉe la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Tion ricevis kiel posedaĵon Manase kaj Efraim, filoj de Jozef.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Kaj la regiono de la Efraimidoj estis laŭ iliaj familioj: la limo de ilia posedaĵo oriente estis de Atrot-Adar ĝis la supra Bet-Ĥoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'Kaj la limo iras al la maro ĉe Miĥmetat norde; kaj la limo turniĝas orienten ĉe Taanat-Ŝilo, kaj trapasas ĝin orienten al Janoaĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'Kaj ĝi malleviĝas de Janoaĥ al Atarot kaj Naara, kaj tuŝas Jeriĥon, kaj finiĝas ĉe Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'De Tapuaĥ la limo iras okcidenten al la torento Kana, kaj finiĝas ĉe la maro. Tio estas la posedaĵo de la tribo de la Efraimidoj laŭ iliaj familioj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'kaj la urboj, kiuj estas apartigitaj por la Efraimidoj meze de la posedaĵo de la Manaseidoj, ĉiuj urboj kun iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Kaj ili ne forpelis la Kanaanidojn, kiuj loĝis en Gezer; kaj la Kanaanidoj restis meze de la Efraimidoj ĝis la nuna tago, servante kiel tributuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Kaj la loto donis al la tribo de Manase, ĉar li estas la unuenaskito de Jozef; al Maĥir, unuenaskito de Manase kaj patro de Gilead, ĉar li estis homo militema, estis donitaj Gilead kaj Baŝan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Estis donite ankaŭ al la ceteraj filoj de Manase laŭ iliaj familioj: al la filoj de Abiezer kaj al la filoj de Ĥelek kaj al la filoj de Asriel kaj al la filoj de Ŝeĥem kaj al la filoj de Ĥefer kaj al la filoj de Ŝemida. Tio estas la naskitoj de Manase, filo de Jozef, la virseksuloj, laŭ iliaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Sed Celofĥad, filo de Ĥefer, filo de Gilead, filo de Maĥir, filo de Manase, ne havis filojn, sed nur filinojn; jen estas la nomoj de liaj filinoj: Maĥla, kaj Noa, Ĥogla, Milka, kaj Tirca.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Kaj ili aliris al la pastro Eleazar, kaj al Josuo, filo de Nun, kaj al la estroj, dirante: La Eternulo ordonis al Moseo doni al ni posedaĵon meze de niaj fratoj. Kaj li donis al ili, konforme al la diro de la Eternulo, posedaĵon inter la fratoj de ilia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Kaj Manase ricevis dek parcelojn, krom la lando Gileada kaj Baŝana, kiu estas transe de Jordan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'ĉar la filinoj de Manase ricevis posedaĵon inter liaj filoj, kaj la lando Gileada estis por la ceteraj filoj de Manase.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Kaj la limo de Manase estis de Aŝer ĝis Miĥmetat, kiu estas kontraŭ Ŝeĥem; kaj la limo iras dekstren, al la loĝantoj de En-Tapuaĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Manase ricevis la landon Tapuaĥ; sed la urbon Tapuaĥ ĉe la limo de Manase ricevis la Efraimidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Kaj la limo malsupreniras al la torento Kana, sude de la torento. Tiuj urboj apartenas al Efraim meze de la urboj de Manase. Kaj la limo de Manase estas norde de la torento, kaj finiĝas ĉe la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'La suda parto apartenis al Efraim, kaj la norda parto apartenis al Manase, kaj la maro estis lia limo. Kaj kun Aŝer ili kuntuŝiĝis norde, kaj kun Isaĥar oriente.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Ĉe Isaĥar kaj Aŝer apartenis al Manase Bet-Ŝean kaj ĝiaj urbetoj, kaj Jibleam kaj ĝiaj urbetoj, kaj la loĝantoj de Dor kaj de ĝiaj urbetoj, kaj la loĝantoj de En-Dor kaj de ĝiaj urbetoj, kaj la loĝantoj de Taanaĥ kaj de ĝiaj urbetoj, kaj la loĝantoj de Megido kaj de ĝiaj urbetoj, kaj la triobla altaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'La filoj de Manase ne povis preni tiujn urbojn; kaj la Kanaanidoj plue restis en tiu lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Sed kiam la Izraelidoj plifortiĝis, ili faris la Kanaanidojn tributuloj, sed ne forpelis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Kaj la filoj de Jozef ekparolis al Josuo, dirante: Kial vi donis al mi kiel posedaĵon nur unu lotaĵon kaj unu parcelon, dum mi estas ja multnombra, ĉar la Eternulo min benis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Kaj Josuo diris al ili: Se vi estas multnombra, iru supren en la arbaron, kaj elhaku al vi tie lokon en la lando de la Perizidoj kaj de la Rafaidoj; ĉar la monto de Efraim estas malvasta por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Kaj la filoj de Jozef diris: Ne sufiĉos por ni la monto; kaj ferajn ĉarojn havas ĉiuj Kanaanidoj, kiuj loĝas en la valo, tiuj, kiuj loĝas en Bet-Ŝean kaj en ĝiaj urbetoj, kaj ankaŭ tiuj, kiuj loĝas en la valo Jizreel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Kaj Josuo diris al la domo de Jozef, al Efraim kaj Manase, jene: Vi estas multnombra kaj havas grandan forton, tial vi ne havos unu lotaĵon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'sed vi havos monton, sur kiu estas arbaro; elhaku ĝin, kaj ĝi estos via ĝis sia fino; ĉar vi forpelos la Kanaanidojn, malgraŭ ke ili havas ferajn ĉarojn, kaj malgraŭ ke ili estas fortaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Kaj la tuta komunumo de la Izraelidoj kolektiĝis en Ŝilo, kaj ili starigis tie la tabernaklon de kunveno; kaj la lando estis jam submetita al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Kaj restis inter la Izraelidoj ankoraŭ sep triboj, al kiuj ankoraŭ ne estis disdividita ilia hereda posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Kaj Josuo diris al la Izraelidoj: Ĝis kiam vi prokrastos iri kaj ekposedi la landon, kiun donis al vi la Eternulo, Dio de viaj patroj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Elektu al vi po tri homoj el ĉiu tribo, kaj mi sendos ilin, ke ili leviĝu kaj trairu la landon kaj priskribu ĝin laŭ ĝiaj heredaj partoj kaj venu al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'Kaj dividu ĝin en sep partojn. Jehuda restu en siaj limoj sude, kaj la domo de Jozef restu en siaj limoj norde.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Kaj vi disskribu la landon en sep partojn, kaj alportu al mi ĉi tien; kaj mi faros lotadon ĉi tie antaŭ la Eternulo, nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'La Levidoj ne havos parton inter vi, ĉar la pastrado antaŭ la Eternulo estas ilia hereda parto; kaj Gad kaj Ruben kaj la duontribo de Manase prenis sian parton transe de Jordan, oriente, kion donis al ili Moseo, servanto de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Kaj la viroj leviĝis kaj iris. Kaj Josuo ordonis al tiuj, kiuj iris priskribi la landon, dirante: Iru kaj trairu la landon kaj priskribu ĝin kaj revenu al mi, kaj ĉi tie mi faros al vi lotadon antaŭ la Eternulo en Ŝilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Kaj la viroj foriris kaj trairis la landon kaj disskribis ĝin laŭ la urboj en sep partojn en libro, kaj revenis al Josuo en la tendaron, al Ŝilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Kaj Josuo faris al ili lotadon en Ŝilo antaŭ la Eternulo, kaj Josuo dividis tie la landon por la Izraelidoj laŭ iliaj partoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Kaj eliris la loto de la tribo de la Benjamenidoj, laŭ iliaj familioj; kaj la limoj de ilia lotita parto estis inter la Jehudaidoj kaj la Jozefidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Kaj ilia limo norde estas de Jordan, kaj la limo leviĝas al la norda flanko de Jeriĥo, kaj leviĝas sur la monton okcidente, kaj finiĝas en la dezerto Bet-Aven.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'Kaj de tie la limo iras al Luz, al la suda flanko de Luz (tio estas Bet-El); kaj la limo plue iras al Atrot-Adar, sur la monton, kiu estas sude de la malsupra Bet-Ĥoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Kaj la limo turniĝas kaj dekliniĝas okcidenten, suden de la monto, kiu estas sude de Bet-Ĥoron; kaj ĝi finiĝas ĉe Kirjat-Baal (tio estas Kirjat-Jearim), urbo de la Jehudaidoj. Tio estas la flanko okcidenta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Kaj la suda flanko komenciĝas de la fino de Kirjat-Jearim; kaj la limo iras okcidenten, kaj finiĝas ĉe la fonto de la akvo Neftoaĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'Kaj la limo malleviĝas al la fino de la monto, kiu estas antaŭ la valo de la filo de Hinom, kiu troviĝas en la valo Refaim norde; kaj ĝi iras tra la valo de Hinom al la sude flanko de la Jebusidoj, kaj malleviĝas al En-Rogel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'Kaj ĝi turniĝas de norde, kaj eliras al En-Ŝemeŝ, kaj iras al Gelilot, kiu estas kontraŭ la altaĵo Adumim; kaj ĝi malleviĝas al la ŝtono de Bohan, filo de Ruben.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'Kaj ĝi iras preter la stepo norden, kaj malleviĝas sur la stepon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Kaj la limo iras preter Bet-Ĥogla norden; kaj la limo finiĝas ĉe la golfo de la Sala Maro norde, ĉe la suda fino de Jordan. Tio estas la limo suda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Kaj Jordan limas sur la flanko orienta. Tio estas la posedaĵo de la Benjamenidoj laŭ ĝiaj limoj ĉirkaŭe, laŭ iliaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Kaj la urboj de la tribo de la Benjamenidoj laŭ iliaj familioj estis: Jeriĥo kaj Bet-Ĥogla kaj Emek-Kecic');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'kaj Bet-Araba kaj Cemaraim kaj Bet-El');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'kaj Avim kaj Para kaj Ofra');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'kaj Kefer-Amona kaj Ofni kaj Geba: dek du urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeon kaj Rama kaj Beerot');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'kaj Micpe kaj Kefira kaj Moca');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'kaj Rekem kaj Jirpeel kaj Tarala');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'kaj Cela, Elef, kaj la Jebusidoj (tio estas Jerusalem), Gibeat, Kirjat: dek kvar urboj kaj iliaj vilaĝoj. Tio estas la posedaĵo de la Benjamenidoj, laŭ iliaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Kaj la dua loto eliris por Simeon, por la tribo de la Simeonidoj, laŭ iliaj familioj. Kaj ilia posedaĵo estis meze de la posedaĵo de la Jehudaidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'Apartenis al ili en ilia posedaĵo: Beer-Ŝeba (kun Ŝeba) kaj Molada');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'kaj Ĥacar-Ŝual kaj Bala kaj Ecem');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'kaj Eltolad kaj Betul kaj Ĥorma');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'kaj Ciklag kaj Bet-Markabot kaj Ĥacar-Susa');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'kaj Bet-Lebaot kaj Ŝaruĥen: dek tri urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ain, Rimon kaj Eter kaj Aŝan: kvar urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'Kaj ĉiuj vilaĝoj, kiuj estas ĉirkaŭ tiuj urboj, ĝis Baalat-Beer, Ramat sude. Tio estas la posedaĵo de la tribo de la Simeonidoj, laŭ iliaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'El la landpeco de la Jehudaidoj estis la posedaĵo de la Simeonidoj; ĉar la parto de la Jehudaidoj estis tro granda por ili, tial la Simeonidoj ricevis posedaĵon meze de ilia posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Kaj la tria loto eliris por la Zebulunidoj, laŭ iliaj familioj; kaj la limo de ilia posedaĵo estis ĝis Sarid.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'Kaj ilia limo iras ĝis la maro kaj Marala, kaj kuntuŝiĝas kun Dabeŝet, kaj kuntuŝiĝas kun la torento, kiu estas antaŭ Jokneam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'Kaj ĝi iras returne de Sarid orienten, al la flanko de sunleviĝo, ĝis la limo de Kislot-Tabor; kaj ĝi iras al Dabrat, kaj leviĝas al Jafia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Kaj de tie ĝi iras orienten, al la flanko de sunleviĝo, tra Gat- Ĥefer kaj Et-Kacin, kaj eliras al Rimon-Metoar kaj Nea.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Kaj la limo turniĝas de nordo al Ĥanaton, kaj finiĝas en la valo Jiftaĥ-El.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'Kaj Katat, kaj Nahalal kaj Ŝimron kaj Jidala kaj Bet-Leĥem: dek du urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Tio estas la posedaĵo de la Zebulunidoj, laŭ iliaj familioj, tiuj urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Por Isaĥar eliris la kvara loto, por la Isaĥaridoj, laŭ iliaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'Kaj ilia limo estis: Jizreel kaj Kesulot kaj Ŝunem');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'kaj Ĥafaraim kaj Ŝion kaj Anaĥarat');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'kaj Rabit kaj Kiŝjon kaj Abec');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'kaj Remet kaj En-Ganim kaj En-Ĥada kaj Bet-Pacec.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'Kaj la limo kuntuŝiĝas al Tabor kaj Ŝaĥacima kaj Bet-Ŝemeŝ; kaj ilia limo finiĝas ĉe Jordan: dek ses urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Tio estas la posedaĵo de la tribo de la Isaĥaridoj, laŭ iliaj familioj, la urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Kaj la kvina loto eliris por la tribo de la Aŝeridoj, laŭ iliaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'Kaj ilia limo estis: Ĥelkat kaj Ĥali kaj Beten kaj Aĥŝaf');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'kaj Alameleĥ kaj Amad kaj Miŝal. Kaj ĝi kuntuŝiĝas al Karmel okcidente, kaj al Ŝiĥor-Libnat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'Kaj ĝi returniĝas oriente al Bet-Dagon, kaj kuntuŝiĝas al Zebulun kaj al la valo Jiftaĥ-El norde, al Bet-Emek kaj Neiel, kaj eliras al Kabul maldekstre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'Kaj Ebron kaj Reĥob kaj Ĥamon kaj Kana ĝis Granda Cidon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'Kaj la limo returniĝas al Rama kaj al la fortikigita urbo Tiro; kaj la limo returniĝas al Ĥosa, kaj finiĝas ĉe la maro, de Ĥebel ĝis Aĥzib;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'kaj Uma kaj Afek kaj Reĥob: dudek du urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Tio estas la posedaĵo de la tribo de la Aŝeridoj, laŭ iliaj familioj, tiuj urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Por la Naftaliidoj eliris la sesa loto, por la Naftaliidoj, laŭ iliaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Kaj ilia limo estis de Ĥelef, de la kverkaro ĉe Caananim, Adami- Nekeb, kaj Jabneel, ĝis Lakum; kaj ĝi finiĝas ĉe Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Kaj la limo turniĝas okcidenten al Aznot-Tabor, kaj eliras de tie al Ĥukok, kaj kuntuŝiĝas al Zebulun sude, kaj al Aŝer ĝi kuntuŝiĝas okcidente, kaj al Jehuda ĉe Jordan oriente.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Kaj fortikigitaj urboj: Cidim, Cer kaj Ĥamat, Rakat kaj Kineret');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'kaj Adama kaj Rama kaj Ĥacor');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'kaj Kedeŝ kaj Edrei kaj En-Ĥacor');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'kaj Jiron kaj Migdal-El, Ĥorem kaj Bet-Anat kaj Bet-Ŝemeŝ: dek naŭ urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Tio estas la posedaĵo de la tribo de la Naftaliidoj, laŭ iliaj familioj, la urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Por la tribo de la Danidoj, laŭ iliaj familioj, eliris la sepa loto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'Kaj la limo de ilia posedaĵo estis: Corea kaj Eŝtaol kaj Ir-Ŝemeŝ');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'kaj Ŝaalabin kaj Ajalon kaj Jitla');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'kaj Elon kaj Timna kaj Ekron');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'kaj Elteke kaj Gibeton kaj Baalat');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'kaj Jehud kaj Bene-Berak kaj Gat-Rimon');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'kaj Me-Jarkon kaj Rakon, kun la limo apud Jafo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Kaj tie finiĝas la limo de la Danidoj. Kaj la Danidoj iris kaj militis kontraŭ Leŝem, kaj prenis ĝin kaj batis ĝin per glavo, kaj ekposedis ĝin kaj enloĝiĝis en ĝi, kaj donis al Leŝem la nomon Dan, laŭ la nomo de Dan, ilia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Tio estas la posedaĵo de la tribo de la Danidoj, laŭ iliaj familioj, tiuj urboj kaj iliaj vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Kaj ili finis la dividadon de la lando laŭ ĝiaj limoj; kaj la Izraelidoj donis al Josuo, filo de Nun, heredan posedaĵon inter si.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Laŭ la ordono de la Eternulo ili donis al li la urbon, kiun li petis, Timnat-Seraĥ sur la monto de Efraim; kaj li konstruis la urbon kaj loĝis en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Tio estas la posedaĵoj, kiujn la pastro Eleazar, kaj Josuo, filo de Nun, kaj la familiestroj disdividis al la triboj de la Izraelidoj laŭ loto, en Ŝilo, antaŭ la Eternulo, antaŭ la pordo de la tabernaklo de kunveno. Kaj ili finis la dividadon de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Kaj la Eternulo ekparolis al Josuo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Diru al la Izraelidoj jene: Aranĝu al vi la urbojn de rifuĝo, pri kiuj Mi parolis al vi per Moseo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'por ke tien povu forkuri mortiginto, kiu mortigis homon per eraro kaj ne sciante; kaj ili estu ĉe vi rifuĝejo kontraŭ venĝanto pro sango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Kaj li forkuros al unu el tiuj urboj, kaj stariĝos antaŭ la pordego de la urbo, kaj rakontos al la plejaĝuloj de tiu urbo sian aferon; kaj ili enprenos lin en la urbon al si, kaj donos al li lokon, por ke li loĝu ĉe ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Kaj kiam la sangovenĝanto postkuros lin, ili ne transdonu la mortiginton en liajn manojn; ĉar senintence li mortigis sian proksimulon, kaj ne estis malamiko de li de antaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Kaj li loĝos en tiu urbo, ĝis li stariĝos antaŭ la komunumo por juĝo, ĝis la morto de la granda pastro, kiu estos en tiu tempo. Tiam la mortiginto reiru, kaj venu en sian urbon kaj al sia domo, en la urbon, el kiu li forkuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Kaj ili konsekris la urbon Kedeŝ en Galileo, sur la monto de Naftali, kaj Ŝeĥem, sur la monto de Efraim, kaj Kirjat-Arba (tio estas Ĥebron), sur la monto de Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Kaj transe de Jordan, oriente de Jeriĥo, ili donis: Becer, en la dezerto, sur la ebenaĵo, de la tribo de Ruben, kaj Ramot en Gilead, de la tribo de Gad, kaj Golan en Baŝan, de la tribo de Manase.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Tiuj urboj estis destinitaj por ĉiuj Izraelidoj, kaj por la fremduloj, kiuj loĝas inter ili, por ke tien povu forkuri ĉiu, kiu mortigis homon per eraro, kaj por ke li ne mortu de la mano de sangovenĝanto, ĝis li stariĝos antaŭ la komunumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Kaj la familiestroj de la Levidoj aliris al la pastro Eleazar, kaj al Josuo, filo de Nun, kaj al la familiestroj de la triboj de la Izraelidoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'kaj ekparolis al ili en Ŝilo, en la lando Kanaana, dirante: La Eternulo ordonis per Moseo doni al ni urbojn por loĝi, kaj iliajn ĉirkaŭaĵojn por niaj brutoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Tiam la Izraelidoj donis al la Levidoj el siaj posedaĵoj, konforme al la ordono de la Eternulo, tiujn urbojn kaj iliajn ĉirkaŭaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Kaj eliris la loto por la familio de la Kehatidoj; kaj al la filoj de la pastro Aaron, el la Levidoj, estis donitaj de la tribo de Jehuda kaj de la tribo de la Simeonidoj kaj de la tribo de Benjamen, per loto, dek tri urboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'Kaj al la ceteraj filoj de Kehat estis donitaj de la familioj de la tribo de Efraim kaj de la tribo de Dan kaj de la duontribo de Manase, per loto, dek urboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Kaj al la filoj de Gerŝon estis donitaj de la familioj de la tribo de Isaĥar kaj de la tribo de Aŝer kaj de la tribo de Naftali kaj de la duontribo de Manase en Baŝan, per loto, dek tri urboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Al la filoj de Merari, laŭ iliaj familioj, estis donitaj de la tribo de Ruben kaj de la tribo de Gad kaj de la tribo de Zebulun dek du urboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Kaj la Izraelidoj donis al la Levidoj per loto tiujn urbojn kaj iliajn ĉirkaŭaĵojn, kiel ordonis la Eternulo per Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Kaj ili donis de la tribo de la Jehudaidoj kaj de la tribo de la Simeonidoj tiujn urbojn, kies nomojn ili difinis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'Al la filoj de Aaron el la familioj de la Kehatidoj, el la Levidoj- ĉar ilia estis la loto unua-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'al ili oni donis la urbon de Arba, patro de Anak (tio estas, la urbon Ĥebron), sur la monto de Jehuda, kaj ĝiajn suburbaĵojn ĉirkaŭ ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Kaj la kampon de la urbo kaj ĝiajn vilaĝojn oni donis al Kaleb, filo de Jefune, kiel propraĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Kaj al la filoj de la pastro Aaron oni donis la urbon de rifuĝo por mortiginto Ĥebron kaj ĝiajn ĉirkaŭaĵojn, kaj Libna kaj ĝiajn ĉirkaŭaĵojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'kaj Jatir kaj ĝiajn ĉirkaŭaĵojn, kaj Eŝtemoa kaj ĝiajn ĉirkaŭaĵojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'kaj Ĥolon kaj ĝiajn ĉirkaŭaĵojn, kaj Debir kaj ĝiajn ĉirkaŭaĵojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'kaj Ain kaj ĝiajn ĉirkaŭaĵojn, kaj Juta kaj ĝiajn ĉirkaŭaĵojn, Bet-Ŝemeŝ kaj ĝiajn ĉirkaŭaĵojn: naŭ urbojn de tiuj du triboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'Kaj de la tribo de Benjamen: Gibeon kaj ĝiajn ĉirkaŭaĵojn, Geba kaj ĝiajn ĉirkaŭaĵojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anatot kaj ĝiajn ĉirkaŭaĵojn, kaj Almon kaj ĝiajn ĉirkaŭaĵojn: kvar urbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'La nombro de ĉiuj urboj de la Aaronidoj, la pastroj, estis dek tri urboj kaj iliaj ĉirkaŭaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Kaj por la familioj de la Kehatidoj, la Levidoj, la restintaj el la Kehatidoj, la urboj de ilia loto estis de la tribo de Efraim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'Kaj oni donis al ili la rifuĝurbon por mortiginto Ŝeĥem kaj ĝiajn ĉirkaŭaĵojn, sur la monto de Efraim, kaj Gezer kaj ĝiajn ĉirkaŭaĵojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'kaj Kibcaim kaj ĝiajn ĉirkaŭaĵojn, kaj Bet-Ĥoron kaj ĝiajn ĉirkaŭaĵojn: kvar urbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'Kaj de la tribo de Dan: Elteke kaj ĝiajn ĉirkaŭaĵojn, Gibeton kaj ĝiajn ĉirkaŭaĵojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ajalon kaj ĝiajn ĉirkaŭaĵojn, Gat-Rimon kaj ĝiajn ĉirkaŭaĵojn: kvar urbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'Kaj de la duontribo de Manase: Taanaĥ kaj ĝiajn ĉirkaŭaĵojn, kaj Gat-Rimon kaj ĝiajn ĉirkaŭaĵojn: du urbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'La nombro de ĉiuj urboj kun iliaj ĉirkaŭaĵoj por la familioj de la restintaj Kehatidoj estis dek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Kaj al la Gerŝonidoj, el la familioj de la Levidoj, oni donis de la duontribo de Manase la rifuĝurbon por mortiginto Golan en Baŝan kaj ĝiajn ĉirkaŭaĵojn, kaj Beeŝtera kaj ĝiajn ĉirkaŭaĵojn: du urbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Kaj de la tribo de Isaĥar: Kiŝjon kaj ĝiajn ĉirkaŭaĵojn, Dabrat kaj ĝiajn ĉirkaŭaĵojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmut kaj ĝiajn ĉirkaŭaĵojn, En-Ganim kaj ĝiajn ĉirkaŭaĵojn: kvar urbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'Kaj de la tribo de Aŝer: Miŝal kaj ĝiajn ĉirkaŭaĵojn, Abdon kaj ĝiajn ĉirkaŭaĵojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Ĥelkat kaj ĝiajn ĉirkaŭaĵojn, kaj Reĥob kaj ĝiajn ĉirkaŭaĵojn: kvar urbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'Kaj de la tribo de Naftali: la rifuĝurbon por mortiginto Kedeŝ en Galileo kaj ĝiajn ĉirkaŭaĵojn, kaj Ĥamot-Dor kaj ĝiajn ĉirkaŭaĵojn, kaj Kartan kaj ĝiajn ĉirkaŭaĵojn: tri urbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'La nombro de ĉiuj urboj de la Gerŝonidoj, laŭ iliaj familioj, estis dek tri urboj kaj iliaj ĉirkaŭaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Kaj al la familioj de la Merariidoj, la ceteraj Levidoj, oni donis de la tribo de Zebulun: Jokneam kaj ĝiajn ĉirkaŭaĵojn, Karta kaj ĝiajn ĉirkaŭaĵojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimna kaj ĝiajn ĉirkaŭaĵojn, Nahalal kaj ĝiajn ĉirkaŭaĵojn: kvar urbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'Kaj de la tribo de Ruben: Becer kaj ĝiajn ĉirkaŭaĵojn, kaj Jahac kaj ĝiajn ĉirkaŭaĵojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedemot kaj ĝiajn ĉirkaŭaĵojn, kaj Mefaat kaj ĝiajn ĉirkaŭaĵojn: kvar urbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'Kaj de la tribo de Gad: la rifuĝurbon por mortiginto Ramot en Gilead kaj ĝiajn ĉirkaŭaĵojn, kaj Maĥanaim kaj ĝiajn ĉirkaŭaĵojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Ĥeŝbon kaj ĝiajn ĉirkaŭaĵojn, Jazer kaj ĝiajn ĉirkaŭaĵojn: kune kvar urbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'La nombro de ĉiuj urboj, kiujn lote ricevis la Merariidoj, laŭ iliaj familioj, la restintaj el la familioj de la Levidoj, estis dek du.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'La nombro de ĉiuj urboj de la Levidoj meze de la posedaĵoj de la Izraelidoj estis kvardek ok urboj kaj iliaj ĉirkaŭaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Tiuj urboj estis ĉiu urbo kun ĝiaj ĉirkaŭaĵoj; tiel estis kun ĉiuj tiuj urboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Kaj la Eternulo donis al la Izraelidoj la tutan landon, kiun doni Li ĵuris al iliaj patroj; kaj ili ekposedis ĝin kaj enloĝiĝis en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Kaj la Eternulo donis al ili trankvilecon ĉirkaŭe, konforme al ĉio, kion Li ĵuris al iliaj patroj; kaj neniu homo el ĉiuj iliaj malamikoj rezistis antaŭ ili; ĉiujn iliajn malamikojn la Eternulo transdonis en iliajn manojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Ne mankis eĉ unu vorto el ĉiuj bonaj vortoj, kiujn la Eternulo diris al la domo de Izrael; ĉio plenumiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Tiam Josuo alvokis la Rubenidojn kaj la Gadidojn kaj la duontribon de Manase;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'kaj li diris al ili: Vi plenumis ĉion, kion ordonis al vi Moseo, servanto de la Eternulo, kaj vi obeis mian voĉon en ĉio, kion mi ordonis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Vi ne forlasis viajn fratojn dum longa tempo ĝis nun, kaj vi plenumis la deciditaĵon laŭ la ordono de la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Nun la Eternulo, via Dio, donis ripozon al viaj fratoj, kiel Li diris al ili; turnu do vin nun, kaj iru al viaj tendoj sur la teron de via posedaĵo, kiun donis al vi Moseo, servanto de la Eternulo, transe de Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Sed forte penu plenumi la ordonojn kaj la instruon, kiujn donis al vi Moseo, servanto de la Eternulo, por ami la Eternulon, vian Dion, kaj iri laŭ ĉiuj Liaj vojoj kaj observi Liajn ordonojn kaj alfortikiĝi al Li kaj servi al Li per via tuta koro kaj per via tuta animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Kaj Josuo benis ilin kaj forliberigis ilin; kaj ili iris al siaj tendoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Kaj al unu duono de la tribo de Manase Moseo donis posedaĵon en Baŝan, kaj al la dua duono Josuo donis posedaĵon kun iliaj fratoj transe de Jordan, okcidente. Kaj kiam Josuo forliberigis ilin al iliaj tendoj, li benis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'Kaj li diris al ili jene: Kun granda riĉaĵo vi reiras nun al viaj tendoj, kaj kun tre granda brutaro, kun arĝento kaj kun oro kaj kun kupro kaj kun fero, kaj kun tre multe da vestoj; dividu la militakiron, kiun vi ricevis de viaj malamikoj, kun viaj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Kaj turniĝis la Rubenidoj kaj la Gadidoj kaj la duontribo de Manase, kaj foriris de la Izraelidoj el Ŝilo, kiu estas en la lando Kanaana, por iri en la landon Gilead, en la landon de ilia posedaĵo, kiun ili ekposedis laŭ la ordono de la Eternulo per Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Kaj ili venis en la distriktojn ĉe Jordan, kiuj estas en la lando Kanaana; kaj la Rubenidoj kaj la Gadidoj kaj la duontribo de Manase konstruis tie altaron ĉe Jordan, altaron grandan kaj bonaspektan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Kaj aŭdis la Izraelidoj: Jen la Rubenidoj kaj la Gadidoj kaj la duontribo de Manase konstruis altaron apud la lando Kanaana, en la distriktoj de Jordan, sur la flanko de la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Kaj kiam la Izraelidoj tion aŭdis, tiam la tuta komunumo de la Izraelidoj kolektiĝis en Ŝilo, por iri kontraŭ ilin milite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Kaj la Izraelidoj sendis al la Rubenidoj kaj la Gadidoj kaj la duontribo de Manase en la landon Gilead Pineĥason, filon de la pastro Eleazar,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'kaj kun li dek ĉefojn, po unu ĉefo el tribo, el ĉiuj triboj de Izrael; kaj ĉiu el ili estis estro de patrodomo inter la miloj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Kaj ili venis al la Rubenidoj kaj la Gadidoj kaj la duontribo de Manase en la landon Gilead, kaj ekparolis al ili, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'Tiel diras la tuta komunumo de la Eternulo: Kio estas ĉi tiu krimo, kiun vi faris kontraŭ la Dio de Izrael, forturniĝinte hodiaŭ de la Eternulo, konstruinte al vi altaron kaj ribelante hodiaŭ kontraŭ la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Ĉu ne sufiĉas al ni la krimo pri Peor, de kiu ni ne puriĝis ĝis la nuna tago kaj pro kiu trafis frapo la komunumon de Izrael?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Kaj vi forturniĝas nun de la Eternulo! estos tiel: hodiaŭ vi ribelas kontraŭ la Eternulo, kaj morgaŭ Li koleros kontraŭ la tuta komunumo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Se la lando de via posedaĵo ŝajnas al vi malpura, tiam transiru en la landon de la posedaĵo de la Eternulo, en kiu staras la loĝejo de la Eternulo, kaj prenu posedaĵon inter ni; sed kontraŭ la Eternulo ne ribelu, kaj kontraŭ ni ne ribelu, konstruante al vi altaron krom la altaro de la Eternulo, nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Jen, Aĥan, filo de Zeraĥ, faris krimon koncerne la anatemitaĵon, kaj la kolero estis kontraŭ la tuta komunumo de Izrael, kaj ne li sola mortis pro sia krimo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Kaj respondis la Rubenidoj kaj la Gadidoj kaj la duontribo de Manase, kaj diris al la milestroj de Izrael:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Dio de la dioj, la Eternulo, Dio de la dioj, la Eternulo, Li scias, kaj Izrael sciu; se ni agis pro ribelo aŭ por defali de la Eternulo, tiam Li ne helpu nin hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'Se ni konstruis al ni la altaron por tio, ke ni defalu de la Eternulo, aŭ ke ni alportu sur ĝi bruloferon kaj farunoferon, aŭ ke ni faru sur ĝi pacoferojn, tiam la Eternulo nin punu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Ni faris tion pro zorgo pri tio, ke morgaŭ ne diru viaj filoj al niaj filoj: Kion komunan vi havas kun la Eternulo, Dio de Izrael?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'kiel limon inter ni kaj vi, Rubenidoj kaj Gadidoj, la Eternulo metis Jordanon; vi ne havas parton en la Eternulo. Kaj tiamaniere viaj filoj malhelpus niajn filojn respekti la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Tial ni diris: Ni konstruu al ni altaron, ne por brulofero nek por aliaj oferoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'sed nur por ke ĝi estu atesto inter ni kaj vi kaj inter niaj estontaj generacioj, ke ni havas la rajton fari servon al la Eternulo antaŭ Li per niaj bruloferoj kaj per niaj buĉoferoj kaj per niaj pacoferoj, kaj por ke ne diru viaj filoj morgaŭ al niaj filoj: Vi ne havas parton en la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Kaj ni pensis: Se ili diros tion al ni kaj al niaj estontaj generacioj, tiam ni diros: Vidu la similaĵon de la altaro de la Eternulo, kiun faris niaj patroj, ne por brulofero nek por buĉofero, sed nur kiel ateston inter ni kaj vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Malproksima de ni estas la deziro ribeli kontraŭ la Eternulo kaj defali hodiaŭ de la Eternulo, konstrui altaron por brulofero, por farunofero kaj por buĉofero, krom la altaro de la Eternulo, nia Dio, kiu estas antaŭ Lia tabernaklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Kaj la pastro Pineĥas, kaj la ĉefoj de la komunumo, kaj la milestroj de Izrael, kiuj estis kun li, aŭdis la vortojn, kiujn diris la Rubenidoj kaj la Gadidoj kaj la Manaseidoj, kaj tio plaĉis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Kaj la pastro Pineĥas, filo de Eleazar, diris al la Rubenidoj kaj la Gadidoj kaj la Manaseidoj: Nun ni scias, ke la Eternulo estas inter ni, ĉar vi ne faris kontraŭ la Eternulo tiun krimon; vi savis la Izraelidojn kontraŭ la mano de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Kaj la pastro Pineĥas, filo de Eleazar, kaj la ĉefoj reiris de la Rubenidoj kaj la Gadidoj el la lando Gilead en la landon Kanaanan, al la Izraelidoj, kaj alportis al ili respondon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Kaj tio plaĉis al la Izraelidoj; kaj la Izraelidoj benis Dion, kaj ne havis plu la intencon iri kontraŭ ilin milite, por ruinigi la landon, en kiu loĝis la Rubenidoj kaj la Gadidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Kaj la Rubenidoj kaj la Gadidoj donis nomon al la altaro: ke ĝi estu atesto inter ni, ke la Eternulo estas la Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Longan tempon post kiam la Eternulo donis al Izrael ripozon kontraŭ ĉiuj iliaj malamikoj ĉirkaŭe, Josuo maljuniĝis, atingis profundan aĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'Tiam Josuo alvokis la tutan Izrael, iliajn plejaĝulojn kaj ĉefojn kaj juĝistojn kaj observistojn, kaj diris al ili: Mi maljuniĝis, mi atingis profundan aĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'Kaj vi vidis ĉion, kion faris la Eternulo, via Dio, al ĉiuj tiuj popoloj antaŭ vi; ĉar la Eternulo, via Dio, mem batalis por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Vidu, mi dividis por vi lote tiujn restintajn popolojn, kiel posedaĵon por viaj triboj, komencante de Jordan, kaj ĉiujn popolojn, kiujn mi ekstermis, ĝis la Granda Maro, kie subiras la suno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Kaj la Eternulo, via Dio, forpuŝos ilin de antaŭ vi kaj forpelos ilin de antaŭ vi; kaj vi ekposedos ilian landon, kiel diris al vi la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Penu do bone, ke vi observu kaj plenumu ĉion, skribitan en la libro de instruo de Moseo, ne forkliniĝante de ĝi dekstren nek maldekstren,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'ne komunikiĝante kun tiuj popoloj, kiuj restis kun vi; kaj la nomon de iliaj dioj ne citu, kaj ne ĵuru per ili, kaj ne servu al ili, kaj ne adoru ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'nur al la Eternulo, via Dio, alfortikiĝu, kiel vi faris ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Kaj la Eternulo forpelis de antaŭ vi popolojn grandajn kaj fortajn; kaj neniu rezistis antaŭ vi ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Unu el vi forpelas milon; ĉar la Eternulo, via Dio, mem batalas por vi, kiel Li diris al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Gardu do bone viajn animojn, por ami la Eternulon, vian Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Ĉar se vi forkliniĝos, kaj aliĝos al tiuj restintaj popoloj, kiuj restis kun vi, kaj vi boparenciĝos kun ili, kaj vi iros al ili kaj ili al vi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'tiam sciu, ke la Eternulo, via Dio, ne plu forpelos tiujn popolojn de antaŭ vi; kaj ili fariĝos por vi kaptilo kaj reto, kaj vipo por viaj flankoj, kaj pikilo por viaj okuloj, ĝis vi forpereos de sur tiu bona tero, kiun donis al vi la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Nun mi ekiras hodiaŭ la vojon de la tuta mondo; kaj vi sciu per via tuta koro kaj per via tuta animo, ke ne restis neplenumita eĉ unu vorto el ĉiuj bonaj vortoj, kiujn la Eternulo, via Dio, diris pri vi; ĉio plenumiĝis por vi, ne mankis el ĝi eĉ unu vorto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Sed kiel plenumiĝis por vi ĉiuj bonaj vortoj, kiujn la Eternulo, via Dio, diris al vi, tiel la Eternulo venigos sur vin ĉion malbonan, ĝis Li ekstermos vin de sur tiu bona tero, kiun donis al vi la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Se vi malobeos la interligon de la Eternulo, via Dio, kiun Li starigis kun vi, kaj vi iros kaj servos al aliaj dioj kaj adoros ilin: tiam ekflamos kontraŭ vin la kolero de la Eternulo, kaj vi forpereos rapide de sur la bona tero, kiun Li donis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Kaj Josuo kunvenigis ĉiujn tribojn de Izrael en Ŝeĥemon, kaj alvokis la plejaĝulojn de Izrael kaj iliajn ĉefojn kaj juĝistojn kaj observistojn; kaj ili stariĝis antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'Kaj Josuo diris al la tuta popolo: Tiel diris la Eternulo, Dio de Izrael: Transe de la Rivero loĝis viaj patroj en la tempo antikva, Teraĥ, patro de Abraham kaj patro de Naĥor; kaj ili servis al aliaj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Sed Mi prenis vian patron Abraham de trans la Rivero kaj kondukis lin tra la tuta lando Kanaana, kaj Mi multigis lian idaron, kaj Mi donis al li Isaakon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Kaj Mi donis al Isaak Jakobon kaj Esavon; kaj Mi donis al Esav la monton Seir, ke li posedu ĝin; sed Jakob kaj liaj filoj foriris en Egiptujon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Kaj Mi sendis Moseon kaj Aaronon, kaj frapis Egiptujon, kiel Mi faris inter ili; kaj poste Mi elkondukis vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Kaj Mi elkondukis viajn patrojn el Egiptujo; kaj vi venis al la maro. Kaj la Egiptoj postkuris viajn patrojn per ĉaroj kaj rajdantoj ĝis la Ruĝa Maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Kaj ili ekkriis al la Eternulo, kaj Li aperigis mallumon inter vi kaj la Egiptoj, kaj venigis sur ilin la maron kaj kovris ilin. Kaj viaj okuloj vidis, kion Mi faris en Egiptujo; kaj vi loĝis en la dezerto dum longa tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Kaj Mi venigis vin al la lando de la Amoridoj, kiuj loĝas transe de Jordan, kaj ili militis kontraŭ vi; kaj Mi transdonis ilin en viajn manojn, kaj vi ekposedis ilian landon, kaj Mi ekstermis ilin antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Kaj leviĝis Balak, filo de Cipor, reĝo de Moab, kaj militis kontraŭ Izrael, kaj sendis kaj alvokis Bileamon, filon de Beor, por malbeni vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Sed Mi ne volis aŭskulti Bileamon; kaj li benis vin, kaj Mi savis vin el liaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Kaj vi transiris Jordanon kaj venis al Jeriĥo; kaj militis kontraŭ vi la loĝantoj de Jeriĥo, la Amoridoj kaj la Perizidoj kaj la Kanaanidoj kaj la Ĥetidoj kaj la Girgaŝidoj, la Ĥividoj kaj la Jebusidoj; sed Mi transdonis ilin en viajn manojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Kaj Mi sendis antaŭ vi krabrojn, kaj ili forpelis de vi la du reĝojn de la Amoridoj; ne per via glavo, kaj ne per via pafarko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Kaj Mi donis al vi landon, pri kiu vi ne laboris, kaj urbojn, kiujn vi ne konstruis, kaj vi loĝas en ili; de vinberĝardenoj kaj olivarboj, kiujn vi ne plantis, vi manĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Timu do la Eternulon, kaj servu al Li fidele kaj vere; kaj forpuŝu la diojn, al kiuj servis viaj patroj transe de la Rivero kaj en Egiptujo, kaj servu al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Sed se ne plaĉas al vi servi al la Eternulo, tiam elektu al vi hodiaŭ, al kiu vi volas servi: ĉu al la dioj, al kiuj servis viaj patroj, kiuj loĝis transe de la Rivero, ĉu al la dioj de la Amoridoj, en kies lando vi loĝas; sed mi kaj mia domo servos al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Tiam la popolo respondis kaj diris: Malproksima de ni estas la deziro forlasi la Eternulon kaj servi al aliaj dioj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'ĉar la Eternulo estas nia Dio, Li, kiu elkondukis nin kaj niajn patrojn el Egiptujo, el la domo de sklaveco, kaj kiu faris antaŭ niaj okuloj tiujn grandajn signojn, kaj gardis nin dum la tuta vojo, kiun ni iris, kaj inter ĉiuj popoloj, tra kies mezo ni trairis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Kaj la Eternulo forpelis antaŭ ni ĉiujn popolojn, kaj la Amoridojn, kiuj loĝis en la lando. Ni do ankaŭ servos al la Eternulo; ĉar Li estas nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Kaj Josuo diris al la popolo: Vi ne povas servi al la Eternulo; ĉar Li estas Dio sankta, Dio severa; Li ne estos indulga kontraŭ viaj malbonagoj kaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Se vi forlasos la Eternulon kaj servos al fremdaj dioj, tiam Li Sin turnos kaj faros al vi malbonon kaj ekstermos vin, post kiam Li faris al vi bonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Kaj la popolo diris al Josuo: Ne, nur al la Eternulo ni servos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Kaj Josuo diris al la popolo: Vi estas atestantoj pri vi, ke vi elektis al vi la Eternulon, por servi al Li. Kaj ili respondis: Ni estas atestantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'Nun forpuŝu do la fremdajn diojn, kiuj estas inter vi, kaj turnu vian koron al la Eternulo, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Kaj la popolo diris al Josuo: Al la Eternulo, nia Dio, ni servos, kaj Lian voĉon ni obeos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Kaj Josuo faris interligon kun la popolo en tiu tago, kaj donis al ĝi leĝojn kaj regulojn en Ŝeĥem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Kaj Josuo skribis tiujn vortojn en la libron de instruo de Dio, kaj li prenis grandan ŝtonon, kaj starigis ĝin tie sub la kverko, kiu estis apud la sanktejo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Kaj Josuo diris al la tuta popolo: Jen ĉi tiu ŝtono estos por ni atestanto; ĉar ĝi aŭdis ĉiujn vortojn de la Eternulo, kiujn Li diris al ni; kaj ĝi estu atestanto pri vi, por ke vi ne forneu vian Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Kaj Josuo forliberigis la popolon, ĉiun al lia posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Post tiu okazintaĵo mortis Josuo, filo de Nun, servanto de la Eternulo, havante la aĝon de cent dek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'Kaj oni enterigis lin inter la limoj de lia posedaĵo en Timnat-Seraĥ, kiu estas sur la monto de Efraim, norde de la monto Gaaŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Kaj Izrael servis al la Eternulo dum la tuta vivo de Josuo, kaj dum la tuta vivo de la plejaĝuloj, kiuj vivis longe post Josuo, kaj kiuj sciis ĉiujn farojn de la Eternulo, kiujn Li faris al Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Kaj la ostojn de Jozef, kiujn la Izraelidoj kunportis el Egiptujo, oni enterigis en Ŝeĥem, sur la kampoparto, kiun Jakob aĉetis de la filoj de Ĥamor, patro de Ŝeĥem, pro cent kesitoj, kaj kiu fariĝis posedaĵo de la filoj de Jozef.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Kaj Eleazar, filo de Aaron, mortis; kaj oni enterigis lin sur la monteto de Pineĥas, lia filo, la monteto, kiu estis donita al li sur la monto de Efraim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Post la morto de Josuo la Izraelidoj demandis la Eternulon, dirante: Kiu el ni plej antaŭe devas iri kontraŭ la Kanaanidojn, por militi kontraŭ ili?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'Kaj la Eternulo diris: Jehuda iros; jen Mi transdonas la landon en liajn manojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Tiam Jehuda diris al sia frato Simeon: Iru kun mi en mian sorton, kaj ni militos kontraŭ la Kanaanidoj; kaj mi ankaŭ iros kun vi en vian sorton. Kaj Simeon iris kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Kaj Jehuda iris, kaj la Eternulo transdonis en liajn manojn la Kanaanidojn kaj la Perizidojn; kaj ili batis el ili en Bezek dek mil homojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'Kaj ili renkontis Adoni-Bezekon en Bezek kaj batalis kontraŭ li kaj venkobatis la Kanaanidojn kaj la Perizidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Kaj Adoni-Bezek forkuris; sed ili postkuris lin kaj kaptis lin kaj dehakis la dikfingrojn de liaj manoj kaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Kaj Adoni-Bezek diris: Sepdek reĝoj kun dehakitaj dikfingroj de la manoj kaj piedoj kolektadis panrestaĵojn sub mia tablo; kiel mi agis, tiel Dio repagis al mi. Kaj oni venigis lin en Jerusalemon, kaj li mortis tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Kaj la Jehudaidoj militis kontraŭ Jerusalem kaj prenis ĝin kaj venkobatis ĝin per glavo, kaj la urbon ili forbruligis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Poste la Jehudaidoj iris, por militi kontraŭ la Kanaanidoj, kiuj loĝis sur la monto kaj en la suda regiono kaj sur la malaltaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Kaj Jehuda iris al la Kanaanidoj, kiuj loĝis en Ĥebron (la nomo de Ĥebron antaŭe estis Kirjat-Arba), kaj venkobatis Ŝeŝajon kaj Aĥimanon kaj Talmajon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Kaj de tie li iris al la loĝantoj de Debir (la nomo de Debir antaŭe estis Kirjat-Sefer).');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Kaj Kaleb diris: Kiu venkobatos Kirjat-Seferon kaj prenos ĝin, al tiu mi donos mian filinon Aĥsa kiel edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Kaj prenis ĝin Otniel, filo de Kenaz, la pli juna frato de Kaleb; kaj li donis al li sian filinon Aĥsa kiel edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Kaj kiam ŝi venis, ŝi instigis lin peti de ŝia patro kampon. Kaj ŝi malsupreniĝis de la azeno; kaj Kaleb diris al ŝi: Kio estas al vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Kaj ŝi diris al li: Donu al mi benon; ĉar vi donis al mi teron sudflankan, tial donu al mi ankaŭ akvofontojn. Kaj Kaleb donis al ŝi fontojn suprajn kaj fontojn malsuprajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Kaj la idoj de la Kenido, bofrato de Moseo, iris el la urbo de Palmoj kun la idoj de Jehuda en la dezerton de Jehuda, kiu estas sude de Arad; kaj ili venis kaj ekloĝis kune kun la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Kaj Jehuda iris kun sia frato Simeon, kaj ili venkobatis la Kanaanidojn, kiuj loĝis en Cefat, kaj detruis ĝin, kaj donis al la urbo la nomon Ĥorma.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Kaj Jehuda prenis la urbojn Gaza kun ĝiaj limoj kaj Aŝkelon kun ĝiaj limoj kaj Ekron kun ĝiaj limoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Kaj la Eternulo estis kun Jehuda, kaj li ekposedis la monton. Sed li ne povis forpeli la loĝantojn de la valo, ĉar ili havis ferajn ĉarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Kaj oni donis al Kaleb Ĥebronon, kiel diris Moseo; kaj li elpelis el tie la tri filojn de Anak.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Sed la Jebusidojn, kiuj loĝis en Jerusalem, la Benjamenidoj ne elpelis; kaj la Jebusidoj loĝis kun la Benjamenidoj en Jerusalem ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Kaj iris ankaŭ la Jozefidoj al Bet-El; kaj la Eternulo estis kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Kaj la Jozefidoj esplorrigardis Bet-Elon (la nomo de la urbo antaŭe estis Luz).');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'Kaj la esplorrigardantoj vidis viron, irantan el la urbo, kaj ili diris al li: Montru al ni la eniron en la urbon, kaj ni faros al vi favoraĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Kaj li montris al ili la eniron en la urbon, kaj ili venkobatis la urbon per glavo; sed tiun viron kaj lian tutan familion ili forliberigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Kaj la viro iris en la landon de la Ĥetidoj, kaj konstruis urbon, kaj donis al ĝi la nomon Luz; tia estas ĝia nomo ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Kaj Manase ne ekposedis la urbojn Bet-Ŝean kun ĝiaj urbetoj kaj Taanaĥ kun ĝiaj urbetoj, kaj la loĝantojn de Dor kaj de ĝiaj urbetoj kaj la loĝantojn de Jibleam kaj de ĝiaj urbetoj kaj la loĝantojn de Megido kaj de ĝiaj urbetoj; kaj la Kanaanidoj plue loĝis en tiu lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Kiam Izrael fortiĝis, li faris la Kanaanidojn tributuloj, sed ne elpelis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Kaj Efraim ne elpelis la Kanaanidojn, kiuj loĝis en Gezer; kaj la Kanaanidoj loĝis inter li en Gezer.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Zebulun ne forpelis la loĝantojn de Kitron, nek la loĝantojn de Nahalol; kaj la Kanaanidoj loĝis inter li, kaj fariĝis tributuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Aŝer ne forpelis la loĝantojn de Ako, nek la loĝantojn de Cidon, nek de Aĥlab, nek de Aĥzib, nek de Ĥelba, nek de Afek, nek de Reĥob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'Kaj la Aŝeridoj loĝis meze de la Kanaanidoj, loĝantoj de la lando; ĉar ili ne forpelis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Naftali ne forpelis la loĝantojn de Bet-Ŝemeŝ, nek la loĝantojn de Bet-Anat; kaj li loĝis meze de la Kanaanidoj, loĝantoj de la lando; kaj la loĝantoj de Bet-Ŝemeŝ kaj de Bet-Anat fariĝis liaj tributuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Kaj la Amoridoj premis la Danidojn sur la monton, ne permesante al ili malsupreniri en la valon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Kaj la Amoridoj plue loĝis sur la monto Ĥeres, en Ajalon kaj en Ŝaalbim; sed la mano de la Jozefidoj pezis sur ili, kaj ili fariĝis tributuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Kaj la limo de la Amoridoj estis de la loko, kie leviĝas Akrabim, de Sela pli alten.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Kaj venis anĝelo de la Eternulo el Gilgal al Boĥim, kaj diris: Mi elkondukis vin el Egiptujo, kaj venigis vin en la landon, pri kiu Mi ĵuris al viaj patroj, kaj Mi diris: Mi neniam rompos Mian interligon kun vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'sed vi ne faru interligon kun la loĝantoj de ĉi tiu lando, iliajn altarojn detruu. Sed vi ne obeis Mian voĉon; kial vi tion faris?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Tial Mi diras: Mi ne forpelos ilin de vi, kaj ili estos por vi kaptilo, kaj iliaj dioj estos por vi falilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Kaj kiam la anĝelo de la Eternulo parolis tiujn vortojn al ĉiuj Izraelidoj, la popolo levis sian voĉon kaj ploris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'Kaj ili donis al tiu loko la nomon Boĥim. Kaj ili tie buĉis oferojn al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Kaj Josuo forliberigis la popolon, kaj la Izraelidoj iris ĉiu al sia hereda parto, por ekposedi la landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'Kaj la popolo servis al la Eternulo dum la tuta vivo de Josuo, kaj dum la tuta vivo de la plejaĝuloj, kiuj vivis longe post Josuo, kaj kiuj vidis ĉiujn grandajn farojn de la Eternulo, kiujn Li faris al Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Kaj mortis Josuo, filo de Nun, servanto de la Eternulo, en la aĝo de cent dek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'Kaj oni enterigis lin inter la limoj de lia posedaĵo en Timnat-Ĥeres, sur la monto de Efraim, norde de la monto Gaaŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Kaj ankaŭ tiu tuta generacio alkolektiĝis al siaj patroj; kaj aperis post ili generacio alia, kiu ne konis la Eternulon, nek la farojn, kiujn Li faris al Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Kaj la Izraelidoj faris malbonon antaŭ la okuloj de la Eternulo, kaj servis al Baaloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'Kaj ili forlasis la Eternulon, Dion de iliaj patroj, kiu elkondukis ilin el la lando Egipta, kaj ili sekvis aliajn diojn, el la dioj de la popoloj, kiuj estis ĉirkaŭ ili, kaj ili adoris ilin, kaj kolerigis la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Kaj ili forlasis la Eternulon, kaj servis al Baal kaj al Aŝtar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Kaj ekflamis la kolero de la Eternulo kontraŭ Izrael, kaj Li transdonis ilin en la manojn de rabistoj, kiuj prirabis ilin, kaj Li vendis ilin en la manojn de iliaj malamikoj ĉirkaŭe; kaj ili ne povis plu sin teni antaŭ siaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Kien ajn ili iris, la mano de la Eternulo estis kontraŭ ili por malbono, kiel la Eternulo diris kaj kiel la Eternulo ĵuris al ili; kaj ili estis tre premataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Kaj la Eternulo starigis juĝistojn, kiuj savis ilin el la manoj de iliaj rabintoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'tamen ankaŭ la juĝistojn ili ne obeis, sed ili malĉastis kun aliaj dioj kaj adoris ilin, rapide dekliniĝis de la vojo, kiun iris iliaj patroj, obeante la ordonojn de la Eternulo; ili tiel ne agis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Kaj kiam la Eternulo starigis por ili juĝistojn, kaj la Eternulo estis kun la juĝisto, kaj savadis ilin el la manoj de iliaj malamikoj dum la tuta vivo de la juĝisto, ĉar la Eternulo kompatis ilin, kiam ili ĝemis pro siaj turmentantoj kaj premantoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'tiam, apenaŭ la juĝisto mortis, ili denove fariĝis pli malbonaj ol iliaj patroj, sekvante aliajn diojn, servante al ili, kaj adorante ilin. Ili ne dekliniĝis de siaj faroj kaj de sia malbona vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Kaj ekflamis la kolero de la Eternulo kontraŭ Izrael, kaj Li diris: Ĉar ĉi tiu popolo malobeis Mian interligon, kiun Mi donis al iliaj patroj, kaj ne aŭskultis Mian voĉon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'tial Mi ankaŭ forpelos de ili neniun el la popoloj, kiujn restigis Josuo, kiam li mortis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'por elprovi per ili Izraelon, ĉu ili observos la vojon de la Eternulo kaj iros ĝin, kiel observis iliaj patroj, aŭ ne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Kaj la Eternulo restigis tiujn popolojn, kaj ne rapidis elpeli ilin, kaj ne transdonis ilin en la manojn de Josuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Kaj jen estas la popoloj, kiujn la Eternulo restigis, por elprovi per ili Izraelon, ĉiujn, kiuj ne sciis pri ĉiuj militoj kontraŭ Kanaan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'por ke eksciu la generacioj de la Izraelidoj, por lernigi militon al tiuj, kiuj antaŭe ne konis ĝin:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'kvin princoj de Filiŝtoj, kaj ĉiuj Kanaanidoj, kaj Cidonanoj, kaj Ĥividoj, kiuj loĝis sur la monto Lebanon, de la monto Baal-Ĥermon ĝis la eniro de Ĥamat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Ili restis, por elprovi per ili la Izraelidojn, por sciiĝi, ĉu ili obeos la ordonojn de la Eternulo, kiujn Li donis al iliaj patroj per Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Kaj la Izraelidoj loĝis meze de la Kanaanidoj, Ĥetidoj kaj Amoridoj kaj Perizidoj kaj Ĥividoj kaj Jebusidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'Kaj ili prenis al si iliajn filinojn kiel edzinojn, kaj siajn filinojn ili donis al iliaj filoj, kaj ili servis al iliaj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Kaj la Izraelidoj faris malbonon antaŭ la okuloj de la Eternulo, kaj forgesis la Eternulon, sian Dion, kaj servis al Baaloj kaj al sanktaj stangoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Kaj ekflamis la kolero de la Eternulo kontraŭ Izrael, kaj Li transdonis ilin en la manojn de Kuŝan-Riŝataim, reĝo de Mezopotamio; kaj la Izraelidoj servis al Kuŝan-Riŝataim dum ok jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Kaj la Izraelidoj ekkriis al la Eternulo, kaj la Eternulo aperigis savanton por la Izraelidoj, kiu savis ilin: Otnielon, filon de Kenaz, pli juna frato de Kaleb.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Kaj estis sur li la spirito de la Eternulo, kaj li estis juĝisto de Izrael. Kaj li eliris milite, kaj la Eternulo transdonis en lian manon Kuŝan-Riŝataimon, reĝon de Mezopotamio, kaj lia mano fariĝis forta super Kuŝan-Riŝataim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'Kaj la lando ripozis dum kvardek jaroj; kaj mortis Otniel, filo de Kenaz.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Kaj denove la Izraelidoj faris malbonon antaŭ la okuloj de la Eternulo; kaj la Eternulo fortigis Eglonon, reĝon de Moab, kontraŭ Izrael, pro tio, ke ili faris malbonon antaŭ la okuloj de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Kaj li aligis al si la Amonidojn kaj Amalekidojn, kaj iris kaj venkobatis Izraelon, kaj ili ekposedis la urbon de Palmoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Kaj la Izraelidoj servis al Eglon, reĝo de Moab, dum dek ok jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Kaj la Izraelidoj ekkriis al la Eternulo, kaj la Eternulo aperigis por ili savanton, Ehudon, filon de Gera, Benjamenidon, maldekstramanulon. Kaj la Izraelidoj sendis per li donacojn al Eglon, reĝo de Moab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Kaj Ehud faris al si glavon dutranĉan, havantan la longon de unu ulno, kaj zonis ĝin sub sia vesto al sia dekstra femuro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'Kaj li prezentis la donacojn al Eglon, reĝo de Moab; Eglon estis homo tre grasdika.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Kaj kiam li finis la prezentadon de la donacoj, li foririgis la homojn, kiuj alportis la donacojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Sed li mem revenis de la idoloj en Gilgal, kaj diris: Mi devas diri al vi ion sekretan, ho reĝo. Kaj tiu diris: Silentu! Kaj eliris de apud li ĉiuj, kiuj staris apud li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Kaj Ehud eniris al li, kiam li sidis en malvarmeta ĉambreto, kiu estis por li sola; kaj Ehud diris: Mi havas por vi vorton de Dio; kaj li leviĝis de la seĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Tiam Ehud etendis sian maldekstran manon, kaj prenis la glavon de sia dekstra femuro, kaj enpuŝis ĝin en lian ventron tiel,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'ke eĉ la tenilo eniris post la tranĉfero, kaj la graso kovris la tranĉferon; ĉar li ne eltiris la glavon el lia ventro, kaj ĝi trapenetris la postan parton de la korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Kaj Ehud eliris en la vestiblon, kaj fermis post si la pordon de la ĉambreto, kaj ŝlosis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Kiam li eliris, la servantoj de la reĝo venis, kaj vidis, ke la pordo de la ĉambreto estas ŝlosita, kaj ili diris: Certe pro natura bezono li estas en la malvarmeta ĉambreto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'Kaj ili atendis longe, sed neniu malfermis la pordon de la ĉambreto; tiam ili prenis la ŝlosilon kaj malŝlosis, kaj ili vidis, ke ilia sinjoro kuŝas malviva sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Kaj dum ili staris konsternitaj, Ehud forkuris, kaj li preterpasis la idolojn kaj forkuris al Seira.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Kaj kiam li alvenis, li ektrumpetis per korno sur la monto de Efraim, kaj la Izraelidoj malsupreniris kun li de la monto, kaj li estis antaŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Kaj li diris al ili: Kuru post mi; ĉar la Eternulo transdonis viajn malamikojn, la Moabidojn, en viajn manojn. Kaj ili iris post li, kaj okupis la transirejon de Jordan, kondukantan al Moab, kaj permesis al neniu transiri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'Kaj ili mortigis en tiu tempo ĉirkaŭ dek mil virojn el la Moabidoj, homojn sanajn kaj fortajn; kaj neniu saviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Kaj en tiu tago Moab humiliĝis sub la manojn de la Izraelidoj; kaj la lando ripozis dum okdek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Post li estis Ŝamgar, filo de Anat; li mortigis sescent virojn el la Filiŝtoj per bova bastono; kaj li ankaŭ savis Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Kaj la Izraelidoj denove faris malbonon antaŭ la okuloj de la Eternulo, kiam Ehud mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'Kaj la Eternulo transdonis ilin en la manojn de Jabin, Kanaana reĝo, kiu reĝis en Ĥacor; lia militistestro estis Sisera, kiu loĝis en Ĥaroŝet- Goim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Kaj la Izraelidoj ekkriis al la Eternulo; ĉar tiu havis naŭcent ferajn ĉarojn, kaj li forte premis la Izraelidojn dum dudek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'Debora, profetino, edzino de Lapidot, estis en tiu tempo juĝistino de la Izraelidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'ŝi sidadis sub la palmo de Debora, inter Rama kaj Bet-El, sur la monto de Efraim; kaj la Izraelidoj venadis al ŝi por juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Kaj ŝi sendis kaj alvokigis Barakon, filon de Abinoam, el Kedeŝ- Naftali, kaj diris al li: La Eternulo, Dio de Izrael, ordonis: Iru, konduku la militistaron sur la monton Tabor, kaj prenu kun vi dek mil virojn el la Naftaliidoj kaj el la Zebulunidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'kaj al la torento Kiŝon Mi alkondukos al vi Siseran, la militistestron de Jabin, kaj liajn ĉarojn kaj lian amasegon; kaj Mi transdonos lin en viajn manojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Tiam diris al ŝi Barak: Se vi iros kun mi, mi iros; sed se vi ne iros kun mi, mi ne iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Kaj ŝi respondis: Bone, mi iros kun vi; sed vi ne havos gloron sur la vojo, kiun vi iros; ĉar en la manojn de virino la Eternulo transdonos Siseran. Kaj Debora leviĝis, kaj iris kun Barak al Kedeŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Kaj Barak vokis la Zebulunidojn kaj la Naftaliidojn al Kedeŝ; kaj lin sekvis dek mil viroj, kaj Debora iris kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Ĥeber, la Kenido, apartiĝis de la Kenidoj, de la idoj de Ĥobab, bofrato de Moseo, kaj li starigis sian tendon apud la kverkaro en Caananim, apud Kedeŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Kaj oni sciigis Siseran, ke Barak, filo de Abinoam, supreniris sur la monton Tabor.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Kaj Sisera kunvokis ĉiujn siajn ĉarojn, naŭcent ferajn ĉarojn, kaj la tutan popolon, kiu estis kun li, el Ĥaroŝet-Goim al la torento Kiŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Tiam Debora diris al Barak: Leviĝu, ĉar nun estas la tago, en kiu la Eternulo transdonos Siseran en viajn manojn; jen la Eternulo eliris antaŭ vi. Kaj Barak malsupreniris de la monto Tabor, kaj post li dek mil viroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Kaj la Eternulo ĵetis konfuzon sur Siseran kaj sur ĉiujn ĉarojn kaj sur la tutan militistaron, antaŭ la glavo de Barak; kaj Sisera deiris de la ĉaro kaj forkuris piede.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Kaj Barak persekutis la ĉarojn kaj la militistaron ĝis Ĥaroŝet-Goim; kaj la tuta militistaro de Sisera falis de glavo; restis neniu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Sed Sisera forkuris piede al la tendo de Jael, edzino de la Kenido Ĥeber; ĉar estis paco inter Jabin, reĝo de Ĥacor, kaj la domo de la Kenido Ĥeber.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Kaj Jael eliris renkonte al Sisera, kaj diris al li: Eniru, mia sinjoro, eniru al mi; ne timu. Kaj li eniris al ŝi en la tendon, kaj ŝi kovris lin per litkovrilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Kaj li diris al ŝi: Donu al mi por trinki iom da akvo, ĉar mi soifas. Kaj ŝi malfermis felsakon kun lakto kaj donis al li por trinki, kaj kovris lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Kaj li diris al ŝi: Staru ĉe la pordo de la tendo, kaj se iu venos kaj demandos vin, kaj diros: Ĉu iu estas ĉi tie? tiam diru, ke neniu estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Kaj Jael, edzino de Ĥeber, prenis najlon de la tendo kaj metis martelon en sian manon kaj aliris al li mallaŭte, kaj enbatis la najlon en lian tempion tiel, ke ĝi enpenetris en la teron. Li dormis, lacigita; kaj li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'Kaj Barak postkuris Siseran. Kaj Jael eliris al li renkonte, kaj diris al li: Venu, mi montros al vi la viron, kiun vi serĉas. Kaj li venis al ŝi, kaj li vidis, ke Sisera kuŝas malviva kaj najlo estas en lia tempio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Tiel Dio humiligis en tiu tago Jabinon, reĝon de Kanaan, antaŭ la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'Kaj la mano de la Izraelidoj ĉiam pli fortiĝis super Jabin, reĝo de Kanaan, ĝis ili ekstermis Jabinon, reĝon de Kanaan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Kaj ekkantis Debora, kaj Barak, filo de Abinoam, en tiu tago, jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Ĉar la ĉefoj gvidis en Izrael Kaj la popolo montris sin fervora, Benu la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Aŭskultu, ho reĝoj; atentu, ho princoj: Mi al la Eternulo, mi kantas; Mi ludas al la Eternulo, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Ho Eternulo! kiam Vi eliris de Seir, Kiam Vi iris de la kampo de Edom, Tremis la tero, kaj la ĉielo fluigis gutojn, Kaj la nuboj gutigis akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'La montoj fluis antaŭ la Eternulo, Tiu Sinaj antaŭ la Eternulo, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'En la tempo de Ŝamgar, filo de Anat, En la tempo de Jael, forlasitaj estis la vojoj, Kaj tiuj, kiuj devis iri sur la vojoj, iris laŭ flankaj vojetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Forestis juĝistoj en Izrael, forestis, Ĝis stariĝis mi, Debora, Ĝis stariĝis mi, patrino en Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Oni elektis novajn diojn; Kaj tiam milito aperis antaŭ la pordego. Ĉu iu vidis ŝildon aŭ lancon Ĉe la kvardek miloj de Izrael?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Mia koro estas kun la estroj de Izrael, Kun la fervoruloj en la popolo; Benu la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Vi, kiuj rajdas sur blankaj azeninoj, Vi, kiuj sidas sur tapiŝoj, Kaj vi, kiuj iras sur la vojo, kantu!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Inter la kantoj de la pafarkistoj ĉe la akvoĉerpejoj, Tie oni prikantos la justecon de la Eternulo, La justecon de Lia estrado en Izrael. Tiam eliris al la pordego la popolo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Vekiĝu, vekiĝu, Debora, Vekiĝu, vekiĝu, kantu kanton; Leviĝu, Barak, kaj konduku viajn kaptitojn, filo de Abinoam!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Tiam eliris la restintoj el la fortuloj de la popolo; La Eternulo eliris kun mi inter la herooj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'De Efraim venis tiuj, kiuj havas siajn radikojn en Amalek; Post vi venis Benjamen en via popolo; De Maĥir venis estroj, Kaj de Zebulun kondukantoj per princa bastono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Kaj princoj el Isaĥar estis kun Debora, Kaj Isaĥar, kiel Barak, kuris en la valon. Ĉe la torentoj de Ruben estas grandaj konsiliĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Kial vi sidas inter la baraĵoj, Aŭskultante la fajfadon ĉe la brutaroj? Ĉe la torentoj de Ruben estas grandaj konsiliĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gilead restis transe de Jordan; Kaj kial Dan sidas sur la ŝipoj? Aŝer sidas sur la bordo de la maro, Kaj loĝas ĉe siaj golfoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Zebulun estas popolo, kiu riskis sian animon por la morto, Kaj Naftali sur la altaĵoj de la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Venis reĝoj, ili batalis; Tiam batalis reĝoj de Kanaan En Taanaĥ, ĉe la akvo de Megido; Sed ili ricevis neniom da mono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'El la ĉielo oni batalis; La steloj de siaj vojoj batalis kontraŭ Sisera.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'La torento Kiŝon forportis ilin, La torento antikva, la torento Kiŝon. Piedpremu, mia animo, la fortulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Tiam frapis la hufoj de ĉevaloj Pro la rapidega forkurado de fortuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Malbenu la urbon Meroz, diris anĝelo de la Eternulo, Malbenu, malbenu ĝiajn loĝantojn; Ĉar ili ne venis kun helpo al la Eternulo, Kun helpo al la Eternulo inter la herooj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Benita estu inter la virinoj Jael, La edzino de la Kenido Ĥeber, Inter la virinoj en la tendo ŝi estu benita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Akvon li petis, lakton ŝi donis; En belega kaliko ŝi alportis buteron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Ŝi etendis sian manon al najlo Kaj sian dekstran manon al martelo de laboristoj; Kaj ŝi ekbatis Siseran, ekfrapis lian kapon, Kaj frakasis kaj traboris lian tempion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Al ŝiaj piedoj li kliniĝis kaj falis kaj ekkuŝis; Al ŝiaj piedoj li kliniĝis kaj falis; Kie li kliniĝis, tie li falis pereinta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Tra la fenestro rigardas, kaj plorkrias tra la krado, la patrino de Sisera: Kial longe ne venas lia ĉaro? Kial malfruiĝas la radoj de liaj kaleŝoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'La saĝaj el ŝiaj sinjorinoj respondas al ŝi, Kaj ŝi mem al si respondas:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, 'Ili ja trovis kaj dividas militakiron; Po unu aŭ po du knabinoj por ĉiu viro, Diverskolorajn vestojn por Sisera, Diverskolorajn vestojn broditajn, Ambaŭflanke broditajn por la kolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Tiel pereu ĉiuj Viaj malamikoj, ho Eternulo! Sed Liaj amantoj estu kiel la leviĝanta suno en sia potenco. Kaj la lando ripozis dum kvardek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Kaj la Izraelidoj faris malbonon antaŭ la okuloj de la Eternulo; kaj la Eternulo transdonis ilin en la manojn de Midjan por la daŭro de sep jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'Kaj la mano de Midjan forte premis Izraelon. Kontraŭ la Midjanidoj la Izraelidoj faris al si la fendegojn en la montoj kaj la kavernojn kaj la fortikaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Kaj kiam la Izraelidoj semis, tiam venadis la Midjanidoj kaj la Amalekidoj kaj la orientanoj, kaj atakadis ilin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'kaj stariĝadis tendare kontraŭ ili, kaj ekstermadis la produktojn de la tero sur la tuta spaco ĝis Gaza, kaj ne restigadis porvivaĵon ĉe la Izraelidoj, nek ŝafon, nek bovon, nek azenon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Ĉar ili venadis kun siaj brutoj kaj tendoj en multego, simile al akridoj; kaj ili kaj iliaj kameloj estis sennombraj, kaj ili venadis en la landon, por dezertigi ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Kaj Izrael tre mizeriĝis de Midjan; kaj la Izraelidoj ekkriis al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Kaj kiam la Izraelidoj ekkriis al la Eternulo pro Midjan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'tiam la Eternulo sendis profeton al la Izraelidoj, kaj ĉi tiu diris al ili: Tiel diras la Eternulo, la Dio de Izrael: Mi venigis vin el Egiptujo, kaj Mi elkondukis vin el la domo de sklaveco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'kaj Mi savis vin el la manoj de la Egiptoj kaj el la manoj de ĉiuj viaj premantoj, kaj Mi forpelis ilin de vi, kaj Mi donis al vi ilian landon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'kaj Mi diris al vi: Mi estas la Eternulo, via Dio; ne timu la diojn de la Amoridoj, en kies lando vi loĝas; sed vi ne obeis Mian voĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Kaj venis anĝelo de la Eternulo, kaj sidiĝis sub kverko, kiu estis en Ofra kaj apartenis al Joaŝ la Abiezrido; lia filo Gideon estis draŝanta tritikon en vinpremejo, por kaŝi antaŭ la Midjanidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Kaj aperis al li la anĝelo de la Eternulo, kaj diris al li: La Eternulo estas kun vi, brava heroo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Kaj Gideon diris al li: Mia sinjoro! se la Eternulo estas kun ni, tiam kial trafis nin ĉio ĉi tio? kaj kie estas ĉiuj Liaj mirakloj, pri kiuj rakontis al ni niaj patroj, dirante: La Eternulo elkondukis ja nin el Egiptujo? Kaj nun la Eternulo forlasis nin, kaj transdonis nin en la manojn de Midjan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Kaj la Eternulo Sin turnis al li, kaj diris: Iru kun ĉi tiu via forto, kaj savu Izraelon el la manoj de Midjan; jen Mi sendas vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Kaj tiu diris al Li: Mia Sinjoro! per kio mi savos Izraelon? mia familio estas ja la plej mizera en Manase, kaj mi estas la plej juna en la domo de mia patro!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Kaj la Eternulo diris al li: Sed Mi estos kun vi, kaj vi venkobatos la Midjanidojn kiel unu homon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Kaj li diris al Li: Se mi akiris Vian favoron, donu al mi pruvosignon, ke tio estas Vi, kiu parolas kun mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'ne foriru de ĉi tie, ĝis mi venos al Vi kaj alportos mian oferaĵon kaj metos antaŭ Vin. Kaj Li diris: Mi restos, ĝis vi revenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Kaj Gideon venis, kaj pretigis kapridon kaj macojn el efo da faruno; la viandon li metis en korbon kaj la brogaĵon li enverŝis en poton, kaj alportis al Li sub la kverkon kaj proponis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Kaj la anĝelo de Dio diris al li: Prenu la viandon kaj la macojn kaj metu sur ĉi tiun rokon, kaj la brogaĵon elverŝu. Kaj li faris tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Kaj la anĝelo de la Eternulo etendis la finon de la bastono, kiu estis en lia mano, kaj ektuŝis la viandon kaj la macojn; kaj tiam eliris fajro el la roko kaj konsumis la viandon kaj la macojn; kaj la anĝelo de la Eternulo foriris de antaŭ liaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Tiam Gideon vidis, ke tio estis anĝelo de la Eternulo; kaj Gideon diris: Ho ve, mia Sinjoro, ho Eternulo! ĉar mi vidis anĝelon de la Eternulo, vizaĝon kontraŭ vizaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Sed la Eternulo diris al li: Paco al vi; ne timu; vi ne mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Kaj Gideon konstruis tie altaron al la Eternulo, kaj donis al ĝi la nomon: La Eternulo estas Paco. Ĝis la nuna tago ĝi estas ankoraŭ en Ofra de la Abiezridoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Kaj en tiu nokto diris al li la Eternulo: Prenu junan bovon de via patro, kaj alian bovon sepjaran, kaj detruu la altaron de Baal, kiu estas ĉe via patro, kaj la sanktan stangon, kiu estas apud ĝi, dehaku;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'kaj konstruu altaron al la Eternulo, via Dio, sur la supro de ĉi tiu roko, laŭ la reguloj, kaj prenu la duan bovon, kaj alportu bruloferon sur la ligno de la sankta stango, kiun vi dehakos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Kaj Gideon prenis dek homojn el siaj servantoj, kaj faris, kiel diris al li la Eternulo; sed ĉar li timis la domanojn de sia patro kaj la urbanojn, por fari tion en la tago, tial li faris en la nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Kiam frue matene la urbanoj leviĝis, ili ekvidis, ke la altaro de Baal estas detruita, kaj la sankta stango, kiu estas apud ĝi, estas dehakita, kaj la dua bovo estas alportita kiel brulofero sur la konstruita altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Kaj ili diris unu al alia: Kiu tion faris? Kaj ili serĉis kaj demandis, kaj oni diris: Gideon, filo de Joaŝ, faris tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Tiam la urbanoj diris al Joaŝ: Elirigu vian filon; li devas morti, ĉar li detruis la altaron de Baal, kaj ĉar li dehakis la sanktan stangon, kiu estis apud ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Sed Joaŝ diris al ĉiuj, kiuj staris antaŭ li: Ĉu vi bezonas batali por Baal? ĉu vi bezonas helpi lin? kiu batalos por li, tiu mortos ĉi tiun matenon. Se li estas dio, li mem batalu por si pro tio, ke oni detruis lian altaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Kaj de tiu tago oni nomis lin Jerubaal, dirante: Baal batalu kontraŭ li, ĉar li detruis lian altaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Kaj ĉiuj Midjanidoj kaj Amalekidoj kaj orientanoj kolektiĝis kune, kaj transiris kaj stariĝis tendare en la valo Jizreel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Kaj la spirito de la Eternulo venis sur Gideonon, kaj li ekblovis per trumpeto; kaj la familio de la Abiezridoj kolektiĝis, por sekvi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Kaj li sendis senditojn al la tuta Manase, kaj ankaŭ ili sekvis lin; kaj li sendis senditojn al Aŝer kaj al Zebulun kaj al Naftali, kaj ili eliris renkonte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Kaj Gideon diris al Dio: Se Vi intencas helpi per mia mano Izraelon, kiel Vi diris,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'en tia okazo jen mi metas sur la draŝejon tonditan lanon: se estos roso nur sur la lano, kaj sur la tuta tero estos seke, tiam mi scios, ke Vi helpos per mia mano Izraelon, kiel Vi diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'Kaj tiel fariĝis: kiam la morgaŭan tagon li matene leviĝis, li elpremis la lanon, kaj elpremis el la lano roson, plenan kalikon da akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Kaj Gideon diris al Dio: Ne koleru min, se mi ankoraŭ unu fojon ekparolos, kaj ankoraŭ nur unu fojon faros provon kun la lano: estu sekeco nur sur la lano, kaj sur la tuta tero estu roso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Kaj Dio faris tiel en tiu nokto: estis sekeco nur sur la lano, kaj sur la tuta tero estis roso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Kaj frue matene leviĝis Jerubaal, tio estas Gideon, kaj la tuta popolo, kiu estis kun li, kaj ili starigis sian tendaron ĉe la fonto Ĥarod; kaj la tendaro de Midjan estis rilate al li sur la norda flanko de la monteto More en la valo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Kaj la Eternulo diris al Gideon: La popolo, kiu estas kun vi, estas tro grandnombra, por ke Mi transdonu la Midjanidojn en iliajn manojn; eble fieriĝos kontraŭ Mi Izrael, dirante: Mia mano helpis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Tial nun proklamu al la oreloj de la popolo jene: Kiu estas timema kaj tremema, tiu iru returne kaj foriru de la monto Gilead. Kaj iris returne el la popolo dudek du mil, kaj dek mil restis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Kaj la Eternulo diris al Gideon: Ankoraŭ estas tro multe da popolo; konduku ilin malsupren al la akvo, kaj tie Mi ilin elektos por vi. Pri kiu Mi diros al vi: Ĉi tiu iru kun vi-tiu devas iri kun vi; kaj ĉiu, pri kiu Mi diros al vi: Ĉi tiu ne iru kun vi-tiu ne devas iri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Kaj li alvenigis la popolon al la akvo. Kaj la Eternulo diris al Gideon: Ĉiun, kiu lektrinkos akvon per sia lango, kiel lektrinkas hundo, tiun starigu aparte; ankaŭ ĉiun, kiu kliniĝos sur siaj genuoj, por trinki.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Kaj la nombro de tiuj, kiuj lektrinkis el la mano al la buŝo, estis tricent homoj; la tuta cetera popolo kliniĝis sur siaj genuoj, por trinki la akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Kaj la Eternulo diris al Gideon: Per la tricent homoj, kiuj lektrinkis, Mi helpos vin, kaj Mi transdonos la Midjanidojn en viajn manojn; kaj la tuta popolo foriru ĉiu al sia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Kaj ili prenis al si la manĝotaĵon de la popolo, kaj iliajn trumpetojn; kaj ĉiujn Izraelidojn li forsendis ĉiun al lia tendo, kaj la tricent homojn li retenis. La tendaro de Midjan estis malsupre de li en la valo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'En tiu nokto la Eternulo diris al li: Leviĝu, iru malsupren en la tendaron; ĉar Mi transdonas ĝin en viajn manojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Sed se vi timas malsupreniri, tiam iru vi kun via junulo Pura al la tendaro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'kaj aŭskultu, kion oni parolas; tiam fortiĝos viaj manoj, kaj vi iros malsupren en la tendaron. Kaj li iris kun sia junulo Pura al la unua armita taĉmenteto de la tendaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'La Midjanidoj kaj la Amalekidoj kaj ĉiuj orientanoj kuŝis en la valo en tia multego, kiel akridoj; kaj iliaj kameloj estis sennombraj, en tia multego, kiel la sablo sur la bordo de la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Gideon venis, kaj jen unu rakontas al sia kamarado sonĝon, kaj diras: Mi vidis en sonĝo, ke jen elbakita hordea pano ruliĝis tra la tendaro de Midjan, kaj venis al tendo, kaj ekfrapis ĝin tiel, ke ĝi falis, kaj renversis ĝin, kaj la tendo tute kuŝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Tiam lia kamarado respondis, dirante: Tio estas nenio alia, nur la glavo de Gideon, filo de Joaŝ, Izraelido; Dio transdonis en lian manon la Midjanidojn kaj la tutan tendaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Kaj kiam Gideon aŭdis la rakonton pri la sonĝo kaj la klarigon de ĝia signifo, li adorkliniĝis, kaj revenis en la tendaron de la Izraelidoj, kaj diris: Leviĝu, ĉar la Eternulo transdonis en viajn manojn la tendaron de Midjan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Kaj li dividis la tricent homojn en tri taĉmentojn, kaj donis al ĉiuj en la manojn trumpetojn kaj malplenajn kruĉojn, kun torĉoj interne de la kruĉoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'Kaj li diris al ili: Rigardu min, kaj faru tion saman, kion mi faros; jen mi iras al la rando de la tendaro, kaj kion mi faros, tion faru ankaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Kiam mi kaj tiuj, kiuj estas kun mi, ekblovos per trumpeto, tiam ankaŭ vi blovu per la trumpetoj ĉirkaŭ la tuta tendaro, kaj kriu: Pro la Eternulo kaj pro Gideon!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Kaj venis Gideon, kaj la cent homoj, kiuj estis kun li, al la rando de la tendaro en la komenco de la meza noktogardo, kiam ĵus stariĝis la gardistoj; kaj ili ekblovis per la trumpetoj, kaj rompis la kruĉojn, kiujn ili havis en la manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'Tiam ekblovis la tri taĉmentoj per la trumpetoj kaj rompis la kruĉojn, kaj ili tenis en la maldekstra mano la torĉojn, kaj en la dekstra la trumpetojn por blovi, kaj ili kriis: Glavo pro la Eternulo kaj pro Gideon!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'Kaj ili staris ĉiu sur sia loko ĉirkaŭ la tendaro; kaj la tuta tendaranaro ekkuris; kaj ĉiuj ekkriis kaj forkuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Kaj oni blovis per la tricent trumpetoj, kaj la Eternulo turnis en la tuta tendaro la glavon de unu kontraŭ alian; kaj la tendaranoj kuris ĝis Bet-Ŝita, al Cerera, ĝis la limo de Abel-Meĥola apud Tabat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Kaj oni kunvokis la Izraelidojn el Naftali kaj el Aŝer kaj el la tuta Manase, kaj ili postkuris la Midjanidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Kaj Gideon sendis senditojn sur la tutan monton de Efraim, por diri: Kuru renkonte al la Midjanidoj kaj baru al ili la akvon ĝis Bet-Bara kaj ĝis Jordan. Kaj kolektiĝis ĉiuj Efraimidoj kaj baris la vojon ĝis Bet-Bara kaj ĝis Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Kaj ili kaptis Orebon kaj Zeebon, du princojn de Midjan, kaj mortigis Orebon ĉe la roko de Oreb, kaj Zeebon ili mortigis ĉe la vinpremejo de Zeeb, kaj persekutis la Midjanidojn; kaj la kapojn de Oreb kaj Zeeb ili alportis al Gideon trans Jordanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Kaj la Efraimidoj diris al li: Kial vi tion faris al ni, ke vi ne vokis nin, kiam vi iris batali kontraŭ Midjan? Kaj ili forte kverelis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Sed li diris al ili: Kion mi faris nun similan al via faro? ĉu la postkolekto de Efraim ne estas pli bona ol la tuta vinberkolekto de Abiezer?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'En viajn manojn Dio transdonis Orebon kaj Zeebon, la princojn de Midjan; kaj kiel mi povis fari en komparo kun tio, kion vi faris? Tiam kvietiĝis ilia kolero kontraŭ li, kiam li diris tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Kaj Gideon venis al Jordan kaj transiris, li kaj la tricent homoj, kiuj estis kun li, lacaj kaj persekutantaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Kaj li diris al la loĝantoj de Sukot: Donu, mi petas, panojn al la homoj, kiuj sekvas min; ĉar ili estas lacaj, kaj mi postkuras Zebaĥon kaj Calmunan, reĝojn de Midjan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Sed la estroj de Sukot diris: Ĉu la manoj de Zebaĥ kaj Calmuna estas jam en viaj manoj, ke ni donu al via militistaro panon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Tiam Gideon diris: Pro tio, kiam la Eternulo transdonos Zebaĥon kaj Calmunan en miajn manojn, mi draŝos viajn korpojn per dornoj de dezerto kaj per kardoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Kaj li iris de tie al Penuel, kaj diris al ĝiaj loĝantoj tion saman; kaj la loĝantoj de Penuel respondis al li tiel, kiel respondis la loĝantoj de Sukot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Kaj li diris ankaŭ al la loĝantoj de Penuel jene: Kiam mi revenos feliĉe, mi detruos ĉi tiun turon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Kaj Zebaĥ kaj Calmuna estis en Karkor, kaj kun ili estis ilia militistaro, ĉirkaŭ dek kvin mil, ĉiuj, kiuj restis el la tuta militistaro de la orientanoj; la nombro de la falintoj estis cent dudek mil homoj, kiuj povis eltiri glavon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Kaj Gideon iris laŭ la vojo de la tendoloĝantoj orienten de Nobaĥ kaj Jogbeha, kaj venkobatis la tendaron, kiam la tendaro opiniis sin tute eksterdanĝera.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Kaj Zebaĥ kaj Calmuna forkuris; sed li postkuris ilin, kaj kaptis Zebaĥon kaj Calmunan, la du reĝojn de Midjan, kaj la tutan militistaron li ektremigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Kaj revenis Gideon, filo de Joaŝ, de la milito, de la deklivo de Ĥeres.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'Kaj li kaptis junulon el la loĝantoj de Sukot, kaj demandis lin; kaj tiu skribis al li la estrojn de Sukot kaj ĝiajn plejaĝulojn, sepdek sep homojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Kaj li venis al la loĝantoj de Sukot, kaj diris: Jen estas Zebaĥ kaj Calmuna, pri kiuj vi mokis min, dirante: Ĉu la manoj de Zebaĥ kaj Calmuna estas jam en viaj manoj, ke ni donu al viaj lacaj homoj panon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Kaj li prenis la plejaĝulojn de la urbo, kaj la dornojn de dezerto kaj la kardojn, kaj punis per ili la loĝantojn de Sukot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Kaj la turon de Penuel li detruis, kaj mortigis la loĝantojn de la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Kaj li diris al Zebaĥ kaj Calmuna: Kiaj estis la homoj, kiujn vi mortigis ĉe Tabor? Kaj ili diris: Ili estis tiaj, kiel vi, ĉiuj aspektis kiel reĝidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'Tiam li diris: Tio estis miaj fratoj, filoj de mia patrino. Per la vivo de la Eternulo, se vi restigus ilin vivaj, mi ne mortigus vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Kaj li diris al sia unuenaskito Jeter: Leviĝu, mortigu ilin. Sed la junulo ne eltiris sian glavon; ĉar li timis, ĉar li estis ankoraŭ juna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Kaj Zebaĥ kaj Calmuna diris: Leviĝu mem kaj frapu nin, ĉar kia estas la viro, tia estas lia forto. Tiam Gideon leviĝis kaj mortigis Zebaĥon kaj Calmunan, kaj li prenis la ornamaĵojn, kiuj estis sur la koloj de iliaj kameloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Kaj la Izraelidoj diris al Gideon: Regu nin, vi kaj via filo kaj la filo de via filo; ĉar vi savis nin el la manoj de Midjan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Sed Gideon diris al ili: Mi ne regos vin, kaj ankaŭ mia filo ne regos vin: la Eternulo regu vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Kaj Gideon diris al ili: Mi petas de vi peton, ĉiu el vi donu al mi la orelringon el sia militakiro. Ili havis orajn orelringojn, ĉar estis afero kun Iŝmaelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'Kaj ili diris: Ni donos. Kaj ili sternis veston, kaj ĉiu ĵetis tien orelringon el sia militakiro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Kaj la pezo de la oraj orelringoj, kiujn li elpetis, estis mil sepcent sikloj da oro, krom la ornamaĵoj kaj la ringoj kaj la purpuraj vestoj, kiuj estis sur la reĝoj de Midjan, kaj krom la kolornamaĵoj, kiuj estis sur la koloj de iliaj kameloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Kaj Gideon faris el tio efodon, kaj lokmetis ĝin en sia urbo, en Ofra; kaj ĉiuj Izraelidoj malĉastiĝis per ĝi tie; kaj tio fariĝis falilo por Gideon kaj por lia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Kaj humiliĝis la Midjanidoj antaŭ la Izraelidoj kaj ne levis plu sian kapon. Kaj la lando ripozis dum kvardek jaroj en la tempo de Gideon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Kaj Jerubaal, filo de Joaŝ, iris kaj ekloĝis en sia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Kaj Gideon havis sepdek filojn, kiuj eliris el liaj lumboj, ĉar li havis multe da edzinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Kaj lia kromvirino, kiu estis en Ŝeĥem, ankaŭ naskis al li filon, kaj li donis al li la nomon Abimeleĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Kaj Gideon, filo de Joaŝ, mortis en tre maljuna ago; kaj oni enterigis lin en la tombo de Joaŝ, lia patro, en Ofra de la Abiezridoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Kiam Gideon mortis, la Izraelidoj denove malĉaste sekvis la Baalojn kaj elektis al si Baal-Beriton kiel sian dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Kaj la Izraelidoj ne memoris la Eternulon, sian Dion, kiu savadis ilin el la manoj de ĉiuj iliaj malamikoj ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'Kaj ili ne estis favorkoraj al la domo de Jerubaal-Gideon rekompence al la tuta bono, kiun li faris al Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Abimeleĥ, filo de Jerubaal, iris en Ŝeĥemon, al la fratoj de sia patrino, kaj ekparolis al ili kaj al la tuta familio de la domo de sia patrinpatro jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Diru al la oreloj de ĉiuj loĝantoj de Ŝeĥem: Kio estas pli bona al vi, ĉu ke regu vin sepdek homoj, ĉiuj filoj de Jerubaal, aŭ ke regu vin unu homo? memoru ankaŭ, ke mi estas via osto kaj via karno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Kaj la fratoj de lia patrino diris pri li al la oreloj de ĉiuj loĝantoj de Ŝeĥem ĉiujn tiujn vortojn, kaj ilia koro inkliniĝis al Abimeleĥ; ĉar ili diris: Li estas nia frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'Kaj ili donis al li sepdek arĝentajn monerojn el la domo de Baal-Berit, kaj Abimeleĥ dungis per ili homojn mallaboremajn kaj facilanimajn, kaj ili sekvis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Kaj li venis en la domon de sia patro en Ofra, kaj mortigis siajn fratojn, la filojn de Jerubaal, sepdek homojn, sur unu ŝtono; restis Jotam, la plej juna filo de Jerubaal, ĉar li kaŝiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Kaj kolektiĝis ĉiuj loĝantoj de Ŝeĥem kaj la tuta domo de Milo, kaj ili iris kaj faris Abimeleĥon reĝo, ĉe la kverko, kiu staras en Ŝeĥem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Kaj oni diris pri tio al Jotam, kaj li iris kaj stariĝis sur la supro de la monto Gerizim, kaj laŭte ekkriis, kaj diris al ili: Aŭskultu min, loĝantoj de Ŝeĥem, kaj aŭskultos vin Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Iris la arboj, por sanktolei reĝon super si; kaj ili diris al la olivarbo: Reĝu super ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Sed la olivarbo diris al ili: Ĉu mi perdis mian grason, per kiu estas honorataj Dio kaj homoj, ke mi iru vagi super la arboj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Kaj la arboj diris al la figarbo: Iru vi, reĝu super ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Sed la figarbo diris al ili: Ĉu mi perdis mian dolĉecon kaj miajn bonajn fruktojn, ke mi iru vagi super la arboj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Kaj la arboj diris al la vinberujo: Iru vi, reĝu super ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Sed la vinberujo diris al ili: Ĉu mi perdis mian moston, kiu gajigas Dion kaj homojn, ke mi iru vagi super la arboj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Tiam ĉiuj arboj diris al la dornarbusto: Iru vi, reĝu super ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Kaj la dornarbusto diris al la arboj: Se vere vi sanktoleas min kiel reĝon super vi, tiam venu, ŝirmu vin sub mia ombro; se ne, tiam eliros fajro el la dornarbusto kaj forbruligos la cedrojn de Lebanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Nun ĉu vi agis ĝuste kaj juste, reĝigante Abimeleĥon? kaj ĉu vi agis bone rilate Jerubaalon kaj lian domon, kaj ĉu vi agis kun li konforme al lia merito?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'Mia patro batalis pro vi kaj ne ŝatis sian vivon kaj savis vin el la manoj de Midjan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'kaj vi leviĝis nun kontraŭ la domon de mia patro, kaj mortigis liajn filojn, sepdek homojn, sur unu ŝtono, kaj Abimeleĥon, filon de lia sklavino, vi reĝigis super la loĝantoj de Ŝeĥem, pro tio, ke li estas via frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'Se ĝuste kaj juste vi agis nun rilate Jerubaalon kaj lian domon, tiam ĝoju pri Abimeleĥ, kaj li ankaŭ ĝoju pri vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Sed se ne, tiam eliru fajro el Abimeleĥ kaj forbruligu la loĝantojn de Ŝeĥem kaj la domon de Milo; kaj fajro eliru el la loĝantoj de Ŝeĥem kaj el la domo de Milo kaj forbruligu Abimeleĥon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Kaj Jotam forkuris kaj forsavis sin kaj iris en Beeron kaj ekloĝis tie pro timo antaŭ sia frato Abimeleĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Kaj Abimeleĥ regis super Izrael tri jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Kaj Dio venigis malbonan spiriton inter Abimeleĥ kaj la loĝantoj de Ŝeĥem; kaj la loĝantoj de Ŝeĥem perfidis Abimeleĥon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'por ke la krimo pri la sepdek filoj de Jerubaal kaj ilia sango venu sur Abimeleĥon, ilian fraton, kiu mortigis ilin, kaj sur la loĝantojn de Ŝeĥem, kiuj subtenis liajn manojn, por ke li mortigu siajn fratojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Kaj la loĝantoj de Ŝeĥem starigis kontraŭ li insidantojn sur la suproj de la montoj, kaj ili prirabadis ĉiun, kiu pasis preter ili sur la vojo. Kaj oni diris tion al Abimeleĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Kaj venis Gaal, filo de Ebed, kun siaj fratoj, kaj ili iris tra Ŝeĥem; kaj fidis lin la loĝantoj de Ŝeĥem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Kaj ili eliris sur la kampon kaj ŝirkolektis siajn vinberojn kaj elpremis ilin kaj faris feston kaj iris en la domon de sia dio kaj manĝis kaj drinkis kaj malbenis Abimeleĥon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Kaj Gaal, filo de Ebed, diris: Kiu estas Abimeleĥ, kaj kio estas Ŝeĥem, ke ni servu al li? li estas ja filo de Jerubaal, kaj Zebul estas lia oficisto. Servu al la homoj de Ĥamor, patro de Ŝeĥem, sed al tiu kial ni servu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Se iu donus ĉi tiun popolon en miajn manojn, mi forpelus Abimeleĥon. Kaj oni diris al Abimeleĥ: Plimultigu vian militistaron, kaj eliru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Kiam Zebul, la estro de la urbo, aŭdis la vortojn de Gaal, filo de Ebed, lia kolero ekflamis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'Kaj li sendis ruze senditojn al Abimeleĥ, por diri: Jen Gaal, filo de Ebed, kun siaj fratoj venis en Ŝeĥemon kaj ribeligas la urbon kontraŭ vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'tial leviĝu en la nokto, vi kaj la popolo, kiu estas kun vi, kaj faru embuskon sur la kampo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'kaj matene, kiam leviĝos la suno, leviĝu frue, kaj ataku la urbon; kaj kiam li kaj la popolo, kiu estas kun li, eliros al vi, tiam faru al li, kion via mano povos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Kaj Abimeleĥ, kaj la tuta popolo, kiu estis kun li, leviĝis en la nokto, kaj faris apud Ŝeĥem embuskon el kvar taĉmentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Kaj Gaal, filo de Ebed, eliris kaj stariĝis ĉe la pordego de la urbo; kaj Abimeleĥ, kaj la popolo, kiu estis kun li, leviĝis el la embusko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Kiam Gaal ekvidis la popolon, li diris al Zebul: Jen popolo malsupreniras de la suproj de la montoj. Sed Zebul diris al li: La ombro de la montoj ŝajnas al vi homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Kaj Gaal parolis plue, kaj diris: Jen popolo malsupreniras de la altaĵo, kaj unu taĉmento venas laŭ la vojo de la kverko de sorĉistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Tiam Zebul diris al li: Kie nun estas via buŝo, kiu diris: Kiu estas Abimeleĥ, ke ni servu al li? Tio estas ja tiu popolo, kiun vi malŝatis; nun eliru, kaj batalu kontraŭ ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Kaj Gaal eliris, havante post si la loĝantojn de Ŝeĥem, kaj ekbatalis kontraŭ Abimeleĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Kaj Abimeleĥ ekpelis lin, kaj li forkuris, kaj falis multe da mortigitoj ĝis la pordego mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Kaj Abimeleĥ restis en Aruma; kaj Zebul elpelis Gaalon kaj liajn fratojn, ke ili ne loĝu en Ŝeĥem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'En la sekvanta tago la popolo eliris sur la kampon. Kaj oni diris tion al Abimeleĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Kaj li prenis sian militistaron kaj dividis ĝin en tri taĉmentojn kaj faris embuskon sur la kampo. Kiam li vidis, ke la popolo eliras el la urbo, li leviĝis kontraŭ ili kaj batis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Kaj Abimeleĥ, kaj la taĉmentoj, kiuj estis kun li, atakis kaj stariĝis antaŭ la pordego de la urbo; kaj du taĉmentoj atakis ĉiujn, kiuj estis sur la kampo, kaj mortigis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Kaj Abimeleĥ batalis kontraŭ la urbo la tutan tiun tagon; kaj li prenis la urbon, kaj mortigis la popolon, kiu estis en ĝi; kaj li detruis la urbon kaj semis sur ĝia loko salon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Kiam tion aŭdis ĉiuj loĝantoj de la turo de Ŝeĥem, ili foriris en la fortikaĵon de la dio Berit.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Kaj oni diris al Abimeleĥ, ke kolektiĝis ĉiuj loĝantoj de la turo de Ŝeĥem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Tiam Abimeleĥ iris sur la monton Calmon, li kaj la tuta popolo, kiu estis kun li, kaj Abimeleĥ prenis hakilon en sian manon kaj dehakis branĉon de arbo kaj prenis ĝin kaj metis ĝin sur sian ŝultron, kaj diris al la homoj, kiuj estis kun li: Kion vi vidis, ke mi faris, tion rapide faru kiel mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Kaj ankaŭ ĉiuj el la tuta popolo dehakis branĉojn kaj iris post Abimeleĥ kaj almetis al la fortikaĵo kaj ekbruligis per ili la fortikaĵon per fajro; kaj mortis ankaŭ ĉiuj homoj de la turo de Ŝeĥem, ĉirkaŭ mil viroj kaj virinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Kaj Abimeleĥ iris al Tebec kaj sieĝis Tebecon kaj prenis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Fortika turo estis meze de la urbo, kaj tien forkuris ĉiuj viroj kaj virinoj kaj ĉiuj loĝantoj de la urbo, kaj enŝlosis sin tie kaj supreniris sur la tegmenton de la turo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Kaj Abimeleĥ venis al la turo kaj sieĝis ĝin, kaj aliris al la pordo de la turo, por forbruligi ĝin per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Tiam iu virino ĵetis muelŝtonon sur la kapon de Abimeleĥ kaj rompis al li la kranion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Tiam li rapide alvokis la junulon, kiu portis liajn batalilojn, kaj diris al li: Eltiru vian glavon kaj mortigu min, por ke oni ne diru pri mi: Virino lin mortigis. Kaj lia junulo lin trapikis, kaj li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Kaj la Izraelidoj vidis, ke Abimeleĥ mortis, kaj ili iris ĉiu al sia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Tiel Dio repagis la malbonagon de Abimeleĥ, kiun ĉi tiu faris rilate sian patron, mortigante siajn sepdek fratojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'Kaj la tutan malbonagon de la loĝantoj de Ŝeĥem Dio revenigis sur ilian kapon; kaj venis sur ilin la malbeno de Jotam, filo de Jerubaal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Post Abimeleĥ leviĝis, por helpadi al Izrael, Tola, filo de Pua, filo de Dodo, Isaĥarido. Li loĝis en Ŝamir, sur la monto de Efraim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Kaj li estis juĝisto de Izrael dum dudek tri jaroj, kaj li mortis, kaj oni enterigis lin en Ŝamir.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Post li leviĝis Jair, Gileadano, kaj li estis juĝisto de Izrael dum dudek du jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Li havis tridek filojn, kiuj rajdadis sur tridek junaj azenoj, kaj ili havis tridek urbojn; ĝis nun oni ilin nomas Vilaĝoj de Jair, kiuj estas en la lando Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Kaj Jair mortis, kaj oni enterigis lin en Kamon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Kaj la Izraelidoj plue faradis malbonon antaŭ la okuloj de la Eternulo, kaj servadis al la Baaloj kaj al la Aŝtaroj kaj al la dioj de Sirio kaj al la dioj de Cidon kaj al la dioj de Moab kaj al la dioj de la Amonidoj kaj al la dioj de la Filiŝtoj; kaj ili forlasis la Eternulon, kaj ne servadis al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Tiam ekflamis la kolero de la Eternulo kontraŭ Izrael, kaj Li transdonis ilin en la manojn de la Filiŝtoj kaj en la manojn de la Amonidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Kaj ili premadis kaj turmentadis la Izraelidojn de tiu jaro dum dek ok jaroj, ĉiujn Izraelidojn, kiuj estis transe de Jordan en la lando de la Amoridoj, kiu estas en Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Kaj la Amonidoj transiris Jordanon, por militi ankaŭ kontraŭ Jehuda kaj Benjamen kaj la domo de Efraim; kaj Izrael estis tre premata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Tiam ekkriis la Izraelidoj al la Eternulo, dirante: Ni pekis antaŭ Vi, ĉar ni forlasis nian Dion kaj servis al la Baaloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Kaj la Eternulo diris al la Izraelidoj: Mi savis ja vin de la Egiptoj kaj de la Amoridoj kaj de la Amonidoj kaj de la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'Kaj la Cidonanoj kaj Amalekidoj kaj Maonidoj premis vin, kaj vi kriis al Mi, kaj Mi savis vin el iliaj manoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'kaj tamen vi forlasis Min kaj servis al aliaj dioj; tial Mi ne plu helpos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Iru kaj kriu al la dioj, kiujn vi elektis; ili helpu vin en la tempo de via mizero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Kaj la Izraelidoj diris al la Eternulo: Ni pekis; faru al ni ĉion, kio plaĉas al Vi; nur savu nin hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Kaj ili forigis el inter si la fremdajn diojn, kaj ekservis al la Eternulo; kaj Li eksentis kompaton pro la suferado de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Kaj kolektiĝis la Amonidoj kaj stariĝis tendare en Gilead; kolektiĝis ankaŭ la Izraelidoj kaj stariĝis tendare en Micpa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Kaj la estroj de Gilead diris unuj al la aliaj: Kiu komencos batalon kontraŭ la Amonidoj, tiu estos estro de ĉiuj loĝantoj de Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Jiftaĥ, la Gileadano, estis heroa militisto, sed li estis filo de malĉastulino. De Gilead naskiĝis Jiftaĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Kaj la edzino de Gilead naskis al li filojn. Kiam la filoj de la edzino grandiĝis, ili forpelis Jiftaĥon, kaj diris al li: Vi ne heredos en la domo de nia patro; ĉar vi estas filo de alia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Tiam Jiftaĥ forkuris de siaj fratoj kaj ekloĝis en la lando Tob. Kaj kolektiĝis al Jiftaĥ sentaŭgaj homoj kaj eliradis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Post kelka tempo ekmilitis la Amonidoj kontraŭ Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Kaj kiam la Amonidoj militis kontraŭ Izrael, la plejaĝuloj de Gilead iris, por preni Jiftaĥon el la lando Tob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'Kaj ili diris al Jiftaĥ: Iru kaj estu nia kondukanto, kaj ni batalos kontraŭ la Amonidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Kaj Jiftaĥ diris al la plejaĝuloj de Gilead: Vi malamas ja min, kaj vi forpelis min el la domo de mia patro; kial do vi nun venis al mi, kiam vi estas en mizero?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Kaj la plejaĝuloj de Gilead diris al Jiftaĥ: Pro tio ni nun revenas al vi, ke vi iru kun ni, kaj ni batalos kontraŭ la Amonidoj, kaj vi estos ĉe ni estro de ĉiuj loĝantoj de Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Kaj Jiftaĥ diris al la plejaĝuloj de Gilead: Se vi revenigas min, por batali kontraŭ la Amonidoj, kaj la Eternulo transdonos ilin al mi, ĉu tiam mi estos via estro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Kaj la plejaĝuloj de Gilead diris al Jiftaĥ: La Eternulo estu aŭskultanto inter ni, ke ni faros konforme al viaj vortoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Tiam Jiftaĥ iris kun la plejaĝuloj de Gilead, kaj la popolo faris lin super si estro kaj kondukanto, kaj Jiftaĥ eldiris ĉiujn siajn vortojn antaŭ la Eternulo en Micpa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Jiftaĥ sendis senditojn al la reĝo de la Amonidoj, por diri: Kio estas inter mi kaj vi, ke vi venis al mi, por militi kontraŭ mia lando?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Kaj la reĝo de la Amonidoj diris al la senditoj de Jiftaĥ: Pro tio, ke Izrael prenis mian landon, kiam li iris el Egiptujo, de Arnon ĝis Jabok kaj ĝis Jordan; nun redonu ĝin al mi en paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Tiam Jiftaĥ duan fojon sendis senditojn al la reĝo de la Amonidoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'kaj dirigis al li: Tiel diris Jiftaĥ: Izrael ne prenis landon de Moab, nek landon de la Amonidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'ĉar irante el Egiptujo, Izrael iris tra la dezerto ĝis la Ruĝa Maro kaj venis al Kadeŝ;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'kaj tiam Izrael sendis senditojn al la reĝo de Edom, por diri: Permesu al mi trairi vian landon; sed la reĝo de Edom ne konsentis; ankaŭ al la reĝo de Moab estis sendite, sed li ne konsentis; tial Izrael restis en Kadeŝ;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'kaj li iris tra la dezerto kaj ĉirkaŭis la landon de Edom kaj la landon de Moab kaj venis de oriento al la lando de Moab kaj stariĝis tendare transe de Arnon, sed ne eniris en la limojn de Moab, ĉar Arnon estas la limo de Moab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Kaj Izrael sendis senditojn al Siĥon, reĝo de la Amoridoj, reĝo de Ĥeŝbon, kaj Izrael diris al li: Permesu al ni trairi vian landon ĝis mia loko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'sed Siĥon ne volis, ke Izrael trairu liajn limojn; kaj Siĥon kolektis sian tutan popolon, kaj ili stariĝis tendare en Jahac kaj batalis kontraŭ Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Kaj la Eternulo, Dio de Izrael, transdonis Siĥonon kaj lian tutan popolon en la manojn de Izrael, kiu venkobatis ilin; kaj Izrael ekposedis la tutan landon de la Amoridoj, kiuj loĝis en tiu lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'Kaj ili ekposedis la tutan regionon de la Amoridoj, de Arnon ĝis Jabok kaj de la dezerto ĝis Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Tiamaniere la Eternulo, Dio de Izrael, forpelis la Amoridojn de antaŭ Lia popolo Izrael; kaj vi volas preni ĝian posedaĵon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Tion, kion posedigas al vi Kemoŝ, via dio, tion posedu; sed ĉiun, kiun la Eternulo, nia Dio, forpelis de antaŭ ni, tiun ni heredos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Ĉu vi estas pli bona ol Balak, filo de Cipor kaj reĝo de Moab? ĉu tiu malpacis kun Izrael aŭ militis kontraŭ li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'De la tempo, kiam Izrael ekloĝis en Ĥeŝbon kaj en ĝiaj dependaĵoj kaj en Aroer kaj en ĝiaj dependaĵoj, kaj en ĉiuj urboj, kiuj estas apud Arnon, pasis jam tricent jaroj; kial vi ne forprenis ilin en tiu tempo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Mi ne pekis kontraŭ vi, kaj vi faras al mi malbonon, militante kontraŭ mi. La Eternulo, la Juĝanto, juĝu nun inter la Izraelidoj kaj la Amonidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Sed la reĝo de Amon ne atentis la vortojn de Jiftaĥ, kiujn ĉi tiu sendis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Kaj venis sur Jiftaĥon la spirito de la Eternulo, kaj li trapasis Gileadon kaj la regionon de Manase, kaj li trairis Micpan Gileadan, kaj de Micpa Gileada li iris al la Amonidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Kaj Jiftaĥ faris sanktan promeson al la Eternulo, kaj diris: Se Vi transdonos la Amonidojn en miajn manojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'tiam tiu, kiu eliros el la pordo de mia domo renkonte al mi, kiam mi feliĉe revenos de la Amonidoj-tiu apartenu al la Eternulo, kaj mi oferos lin kiel bruloferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Kaj Jiftaĥ venis al la Amonidoj, por batali kontraŭ ili; kaj la Eternulo transdonis ilin en liajn manojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'Kaj li venkobatis ilin de Aroer ĝis Minit, dudek urbojn, kaj ĝis Abel-Keramim-tio estis tre granda venkobato; kaj la Amonidoj humiliĝis antaŭ la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Kaj Jiftaĥ venis al Micpa, al sia domo, kaj jen lia filino eliras renkonte al li kun tamburinoj kaj danco; kaj ŝi estis lia sola infano; krom ŝi li havis neniun filon nek filinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Kiam li ekvidis ŝin, li disŝiris siajn vestojn, kaj diris: Ho ve, mia filino! kiel forte vi min klinis, vi min malĝojigis! mi malfermis mian buŝon antaŭ la Eternulo, kaj mi ne povas repreni la faron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Kaj ŝi diris al li: Mia patro! vi malfermis vian buŝon antaŭ la Eternulo; agu do kun mi tiel, kiel diris via buŝo, post kiam la Eternulo faris al vi venĝon kontraŭ viaj malamikoj, kontraŭ la Amonidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Kaj ŝi diris al sia patro: Faru por mi jenon: lasu min for por du monatoj, kaj mi iros, mi iros sur la montojn kaj priploros mian virgecon, mi kune kun miaj amikinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Kaj li diris: Iru; kaj li forsendis ŝin por du monatoj. Kaj ŝi iris kune kun siaj amikinoj kaj priploris sian virgecon sur la montoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Kaj kiam pasis la du monatoj, ŝi revenis al sia patro, kaj li plenumis sur ŝi sian sanktan promeson, kiun li faris; kaj ŝi ne ekkonis viron. Kaj fariĝis moro en Izrael,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'ke ĉiujare la filinoj de Izrael iras priplori la filinon de Jiftaĥ, la Gileadano, dum kvar tagoj en jaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Kaj kolektiĝis la Efraimidoj kaj iris norden, kaj diris al Jiftaĥ: Kial vi iris militi kontraŭ la Amonidoj, kaj nin ne vokis, ke ni iru kun vi? vian domon kune kun vi ni forbruligos per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Kaj Jiftaĥ diris al ili: Mi kaj mia popolo havis grandan disputon kun la Amonidoj; mi kriis al vi, sed vi ne savis min el ilia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Kiam mi vidis, ke vi ne savas, mi elmetis al risko mian animon kaj iris kontraŭ la Amonidojn, kaj la Eternulo transdonis ilin en miajn manojn. Kial do vi venis hodiaŭ al mi, por malpaci kontraŭ mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Kaj Jiftaĥ kolektis ĉiujn loĝantojn de Gilead kaj batalis kontraŭ la Efraimidoj. Kaj la loĝantoj de Gilead venkobatis la Efraimidojn; ĉar ĉi tiuj diris: Vi estas forkurintoj el Efraim, Gilead estas ja meze de Efraim kaj meze de Manase.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Kaj la Gileadanoj baris al la Efraimidoj la transirejojn de Jordan. Kaj kiam iu el la forkurantaj Efraimidoj diris: Mi volas transiri, tiam la Gileadanoj diris al li: Ĉu vi estas Efraimido? Se li diris: Ne,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'tiam ili diris al li: Diru: Ŝibolet; li diris: Sibolet, ĉar li ne povis elparoli ĝuste; tiam ili kaptis lin kaj buĉis lin ĉe la transirejo de Jordan. Kaj en tiu tempo falis el la Efraimidoj kvardek du mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Kaj Jiftaĥ estis juĝisto de Izrael dum ses jaroj. Kaj mortis Jiftaĥ, la Gileadano, kaj oni enterigis lin en la urboj de Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Kaj post li estis juĝisto de Izrael Ibcan el Bet-Leĥem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Li havis tridek filojn, kaj tridek filinojn li edzinigis eksteren, kaj tridek filinojn li prenis el ekstere por siaj filoj. Kaj li estis juĝisto de Izrael dum sep jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'Kaj Ibcan mortis, kaj oni enterigis lin en Bet-Leĥem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Kaj post li estis juĝisto de Izrael Elon, Zebulunido, kaj li estis juĝisto de Izrael dum dek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Kaj mortis Elon, la Zebulunido, kaj oni enterigis lin en Ajalon, en la lando de Zebulun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Kaj post li estis juĝisto de Izrael Abdon, filo de Hilel, Piratonano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Li havis kvardek filojn kaj tridek nepojn, kiuj rajdadis sur sepdek junaj azenoj. Kaj li estis juĝisto de Izrael dum ok jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Kaj mortis Abdon, filo de Hilel, la Piratonano, kaj oni enterigis lin en Piraton, en la lando de Efraim, sur la monto de la Amalekidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Kaj la Izraelidoj denove faris malbonon antaŭ la okuloj de la Eternulo; kaj la Eternulo transdonis ilin en la manojn de la Filiŝtoj por kvardek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Kaj estis iu homo el Corea, el la tribo de Dan, kies nomo estis Manoaĥ; lia edzino estis senfrukta kaj ne naskis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Kaj aperis anĝelo de la Eternulo al la virino, kaj diris al ŝi: Jen vi estas senfrukta kaj ne naskas; tamen vi gravediĝos kaj naskos filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Sed nun gardu vin, kaj ne trinku vinon nek ebriigaĵon, kaj manĝu nenion malpuran;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'ĉar jen vi gravediĝos kaj naskos filon; kaj razilo ne devas tuŝi lian kapon, ĉar konsekrita al Dio estos la knabo de el la ventro; kaj li komencos savadi Izraelon el la manoj de la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Kaj la virino iris, kaj diris al sia edzo jene: Dia homo venis al mi, kaj lia aspekto estis kiel la aspekto de anĝelo de Dio, tre respektinda; kaj mi ne demandis lin, de kie li estas, kaj sian nomon li ne diris al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Kaj li diris al mi: Jen vi gravediĝos kaj naskos filon; kaj nun ne trinku vinon nek ebriigaĵon, kaj manĝu nenion malpuran; ĉar konsekrita al Dio estos la knabo de el la ventro ĝis la tago de lia morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Tiam Manoaĥ ekpreĝis al la Eternulo, kaj diris: Mi petas Vin, ho mia Sinjoro: la Dia homo, kiun Vi sendis, venu denove al ni, kaj li instruu nin, kiel ni devas agi kun la naskota knabo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Kaj Dio aŭskultis la voĉon de Manoaĥ; kaj la anĝelo de Dio venis denove al la virino, kiam ŝi estis sur la kampo; kaj Manoaĥ, ŝia edzo, ne estis kun ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'La virino rapide kuris kaj sciigis sian edzon, kaj diris al li: Jen aperis al mi la homo, kiu venis al mi en tiu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Kaj Manoaĥ leviĝis kaj iris post sia edzino kaj venis al la homo, kaj diris al li: Ĉu vi estas tiu homo, kiu parolis al la virino? Kaj tiu diris: Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Kaj Manoaĥ diris: Se viaj vortoj plenumiĝos, tiam kiaj devas esti la reguloj pri la knabo kaj liaj agoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Kaj la anĝelo de la Eternulo diris al Manoaĥ: Kontraŭ ĉio, pri kio mi parolis al la virino, ŝi sin gardu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'nenion el tio, kio devenas el vinberbranĉo, ŝi manĝu, vinon aŭ ebriigaĵon ŝi ne trinku, kaj nenion malpuran ŝi manĝu; ĉion, kion mi ordonis al ŝi, ŝi plenumu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Kaj Manoaĥ diris al la anĝelo de la Eternulo: Permesu, ke ni retenu vin, kaj ni pretigos por vi kapridon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Sed la anĝelo de la Eternulo diris al Manoaĥ: Kvankam vi retenos min, mi tamen ne manĝos vian panon; sed se vi volas fari bruloferon, faru ĝin al la Eternulo. Ĉar Manoaĥ ne sciis, ke tio estas anĝelo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Kaj Manoaĥ diris al la anĝelo de la Eternulo: Kia estas via nomo? ke ni povu honori vin, kiam plenumiĝos via vorto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Sed la anĝelo de la Eternulo diris al li: Por kio vi demandas pri mia nomo? ĝi estas neordinara.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Kaj Manoaĥ prenis kapridon kaj farunoferon kaj oferlevis tion sur roko al la Eternulo. Kaj Li faris miraklon, kaj Manoaĥ kaj lia edzino tion vidis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'kiam la flamo leviĝis de la altaro al la ĉielo, tiam la anĝelo de la Eternulo leviĝis en la flamo de la altaro. Kaj Manoaĥ kaj lia edzino tion vidis, kaj ili ĵetis sin vizaĝaltere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'Kaj la anĝelo de la Eternulo ne montris sin plu al Manoaĥ kaj al lia edzino. Tiam Manoaĥ konvinkiĝis, ke tio estis anĝelo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'Kaj Manoaĥ diris al sia edzino: Ni certe mortos, ĉar ni vidis Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Sed lia edzino diris al li: Se la Eternulo dezirus mortigi nin, Li ne akceptus el niaj manoj bruloferon kaj farunoferon, kaj ne montrus al ni ĉion tion, kaj nun Li ne aŭdigus al ni tion, kion Li aŭdigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Kaj la virino naskis filon kaj donis al li la nomon Ŝimŝon. Kaj la knabo kreskis, kaj la Eternulo lin benis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'Kaj la spirito de la Eternulo komencis ekscitadi lin en la Tendaro de Dan, inter Corea kaj Eŝtaol.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Ŝimŝon iris en Timnan, kaj ekvidis en Timna virinon el la filinoj de la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Kaj li iris kaj sciigis tion al sia patro kaj al sia patrino, kaj diris: Mi vidis en Timna virinon el la filinoj de la Filiŝtoj; nun prenu ŝin al mi kiel edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Kaj lia patro kaj lia patrino diris al li: Ĉu ne troviĝas virino inter la filinoj de viaj fratoj kaj en nia tuta popolo, ke vi iras preni edzinon el la necirkumciditaj Filiŝtoj? Sed Ŝimŝon diris al sia patro: Ŝin prenu por mi, ĉar ŝi plaĉas al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Kaj lia patro kaj lia patrino ne sciis, ke tio estas de la Eternulo, ĉar Li serĉis pretekston kontraŭ la Filiŝtoj; en tiu tempo la Filiŝtoj regis super Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Kaj Ŝimŝon kun sia patro kaj kun sia patrino iris en Timnan; kiam ili venis al la vinberĝardenoj de Timna, juna leono blekegante venis renkonte al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Kaj venis sur lin la spirito de la Eternulo, kaj li disŝiris lin, kiel oni disŝiras kapridon, kvankam li nenion havis en sia mano. Kaj li ne diris al siaj gepatroj, kion li faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Kaj li venis kaj parolis kun la virino, kaj ŝi plaĉis al Ŝimŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Post kelka tempo li iris denove, por preni ŝin, kaj li devojiĝis, por vidi la kadavron de la leono; kaj jen svarmamaso da abeloj estas en la kadavro de la leono, kaj ankaŭ mielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Kaj li prenis ĝin en siajn manojn kaj iris, manĝante dum la irado; kaj li iris al siaj gepatroj, kaj donis al ili, kaj ili manĝis; sed li ne diris al ili, ke el la kadavro de la leono li prenis la mielon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Kaj lia patro venis al la virino, kaj Ŝimŝon faris tie festenon, kiel ordinare faras la junuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Kiam ili ekvidis lin, ili donis al li tridek kompanianojn, ke ili estu kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Kaj Ŝimŝon diris al ili: Mi proponos al vi enigmon; se vi divenos ĝin al mi dum la sep tagoj de la festeno kaj trafos, tiam mi donos al vi tridek ĉemizojn kaj tridek kompletojn da vestoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'sed se vi ne povas diveni al mi, tiam vi donos al mi tridek ĉemizojn kaj tridek kompletojn da vestoj. Kaj ili diris al li: Proponu vian enigmon, kaj ni aŭskultos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Kaj li diris al ili: El manĝantaĵo devenis manĝataĵo, Kaj el fortaĵo devenis dolĉaĵo. Kaj ili ne povis solvi la enigmon dum tri tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'En la sepa tago ili diris al la edzino de Ŝimŝon: Admonu vian edzon, ke li solvu al ni la enigmon; alie ni forbruligos per fajro vin kaj la domon de via patro. Ĉu por senhavigi nin vi invitis nin ĉi tien?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Tiam la edzino de Ŝimŝon ekploris antaŭ li, kaj diris: Vi nur malamas min, sed ne amas; vi proponis enigmon al la filoj de mia popolo, kaj al mi vi ne diris ĝian solvon. Kaj li diris al ŝi: Jen al miaj gepatroj mi ne diris la solvon, kaj ĉu al vi mi ĝin diru?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Kaj ŝi ploris antaŭ li dum la sep tagoj, kiujn daŭris ĉe ili la festeno; en la sepa tago li diris al ŝi la solvon, ĉar ŝi tre insistis. Kaj ŝi diris la solvon de la enigmo al la filoj de ŝia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Kaj la urbanoj diris al li en la sepa tago, antaŭ la subiro de la suno: Kio estas pli dolĉa ol mielo? kaj kio estas pli forta ol leono? Kaj li diris al ili: Se vi ne plugus per mia bovidino, Vi ne trovus la solvon de mia enigmo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Kaj venis sur lin la spirito de la Eternulo, kaj li iris en Aŝkelonon kaj mortigis tie tridek homojn kaj prenis iliajn vestojn kaj donis la kompletojn de iliaj vestoj al la solvintoj de la enigmo. Sed ekflamis lia kolero, kaj li foriris en la domon de sia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Kaj la edzino de Ŝimŝon fariĝis edzino de lia festena kompaniulo, kiu kompaniis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Post kelka tempo, en la tempo de rikoltado de tritiko, Ŝimŝon vizitis sian edzinon, alportante kapridon, kaj diris: Mi envenos al mia edzino en la internan ĉambron. Sed ŝia patro ne permesis al li eniri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'Kaj ŝia patro diris: Mi pensis, ke vi ekmalamis ŝin, kaj mi donis ŝin al via amiko. Jen ŝia pli juna fratino estas ja pli bela ol ŝi; ŝi fariĝu via, anstataŭ tiu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Sed Ŝimŝon diris al ili: Ĉi tiun fojon mi estos senkulpa antaŭ la Filiŝtoj, se mi faros al ili malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Kaj Ŝimŝon iris, kaj kaptis tricent vulpojn kaj prenis torĉojn, kaj turnis voston al vosto kaj alligis po unu torĉo meze inter ĉiuj du vostoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Kaj li ekbruligis per fajro la torĉojn kaj pelis ilin sur la grenkampojn de la Filiŝtoj kaj forbruligis la garbojn kaj la ankoraŭ ne rikoltitan grenon kaj la vinberĝardenojn kaj la olivarbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Kaj la Filiŝtoj diris: Kiu tion faris? Kaj oni respondis: Ŝimŝon, bofilo de la Timnaano; ĉar ĉi tiu prenis lian edzinon kaj fordonis ŝin al lia amiko. Kaj la Filiŝtoj iris kaj forbruligis per fajro ŝin kaj ŝian patron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Tiam Ŝimŝon diris al ili: Se vi agas tiel, tiam mi ne ĉesos, antaŭ ol mi faros venĝon kontraŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'Kaj li forte batis al ili la krurojn kaj la lumbojn; poste li iris kaj ekloĝis en la fendego de la roko Etam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Tiam la Filiŝtoj iris kaj stariĝis tendare en la regiono de Jehuda kaj etendiĝis ĝis Leĥi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Kaj la Jehudaidoj diris: Pro kio vi eliris kontraŭ nin? Kaj ili respondis: Ni venis, por ligi Ŝimŝonon, por agi kun li, kiel li agis kun ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Tiam iris tri mil homoj el Jehuda al la fendego de la roko Etam, kaj diris al Ŝimŝon: Ĉu vi ne scias, ke la Filiŝtoj regas super ni? kion do vi faris al ni? Kaj li diris al ili: Kiel ili agis kun mi, tiel mi agis kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Kaj ili diris al li: Ni venis, por ligi vin, por doni vin en la manojn de la Filiŝtoj. Tiam Ŝimŝon diris al ili: Ĵuru al mi, ke vi ne mortigos min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Kaj ili diris al li jene: Ne; ni nur ligos vin kaj transdonos vin en iliajn manojn, sed certe ni ne mortigos vin. Kaj ili ligis lin per du novaj ŝnuroj kaj elkondukis lin el la roko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Kiam li venis al Leĥi, la Filiŝtoj ĝojkriante iris renkonte al li. Sed venis sur lin la spirito de la Eternulo, kaj la ŝnuroj, kiuj estis sur liaj brakoj, fariĝis kiel lino, bruligita de fajro, kaj liaj katenoj disfalis de liaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Kaj li trovis freŝan makzelon de azeno, kaj li etendis sian manon kaj prenis ĝin kaj mortigis per ĝi mil homojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Kaj Ŝimŝon diris: Per makzelo de azeno grandegan amason, Per makzelo de azeno mi mortigis mil homojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Kiam li finis paroli, li forĵetis el sia mano la makzelon; kaj li donis al tiu loko la nomon Ramat-Leĥi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Kaj li eksentis grandan soifon, kaj li ekvokis al la Eternulo, kaj diris: Vi faris per la mano de Via sklavo tiun grandan savon; kaj nun mi devas morti de soifo kaj fali en la manojn de la necirkumciditoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Tiam Dio fendis kavon, kiu estis en Leĥi, kaj eliris el ĝi akvo; kaj li trinkis, kaj lia spirito revenis, kaj li reviviĝis. Tial ĝi ricevis la nomon ĝis la nuna tago: Fonto de la Vokanto en Leĥi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Kaj li estis juĝisto de Izrael en la tempo de la Filiŝtoj dum dudek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Ŝimŝon iris en Gazan kaj vidis tie malĉastulinon kaj eniris al ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'Al la Gazaanoj oni diris: Ŝimŝon venis ĉi tien; kaj ili ĉirkaŭis lin kaj spione atendis lin dum la tuta nokto ĉe la pordego de la urbo, kaj staris senbrue dum la tuta nokto, dirante: Antaŭ la mateniĝo ni lin mortigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Ŝimŝon kuŝis ĝis noktomezo; je noktomezo li leviĝis kaj kaptis la pordojn de la urba pordego kune kun ambaŭ fostoj kaj levis ilin kune kun la riglilo kaj metis sur siajn ŝultrojn, kaj forportis ilin sur la supron de la monto, kiu estas antaŭ Ĥebron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Post tio li ekamis virinon en la valo Sorek; ŝia nomo estis Delila.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Kaj venis al ŝi la estroj de la Filiŝtoj, kaj diris al ŝi: Allogu lin, kaj vidu, en kio konsistas lia granda forto, kaj per kio ni povus fortosuperi lin, ke ni ligu lin kaj humiligu lin; tiam ni donos al vi ĉiu po mil kaj cent arĝentaj moneroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Kaj Delila diris al Ŝimŝon: Diru al mi, mi petas, en kio konsistas via granda forto, kaj per kio oni povas ligi vin, por humiligi vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Kaj Ŝimŝon diris al ŝi: Se oni ligos min per sep freŝaj ne sekiĝintaj ŝnuroj, tiam mi senfortiĝos kaj fariĝos kiel la aliaj homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Tiam la estroj de la Filiŝtoj alportis al ŝi sep freŝajn ne sekiĝintajn ŝnurojn, kaj ŝi ligis lin per ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'Kaj dum la embuskuloj sidis ĉe ŝi en alia ĉambro, ŝi diris al li: Filiŝtoj iras al vi, Ŝimŝon! Tiam li disŝiris la ŝnurojn, kiel oni disŝiras fadenon el stupo, kiam fajro ĝin bruldifektis. Kaj oni ne sciiĝis pri lia forto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Kaj Delila diris al Ŝimŝon: Jen vi trompis min kaj diris al mi mensogon; nun diru al mi, per kio oni povas vin ligi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Kaj li diris al ŝi: Se oni min ligos per novaj ŝnuroj, kiuj ne estis uzitaj por laboro, tiam mi senfortiĝos kaj fariĝos kiel la aliaj homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Tiam Delila prenis novajn ŝnurojn kaj ligis lin per ili, kaj diris al li: Filiŝtoj iras al vi, Ŝimŝon! Dume la embuskuloj sidis en alia ĉambro. Kaj li deŝiris ilin de siaj brakoj kiel fadenon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Kaj Delila diris al Ŝimŝon: Ĝis nun vi trompas min kaj diras al mi mensogojn; diru al mi, per kio oni povas vin ligi. Kaj li diris al ŝi: Se vi interteksos la sep buklojn de mia kapo kun ŝpinaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Kaj ŝi alfortikigis ilin per najlo, kaj diris al li: Filiŝtoj iras al vi, Ŝimŝon! Kaj li vekiĝis el sia dormo kaj eltiris la interteksan najlon kune kun la ŝpinaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Tiam ŝi diris al li: Kial vi diras, ke vi amas min, dum tamen via koro ne estas kun mi? jam tri fojojn vi trompis min, kaj ne diris al mi, en kio konsistas via granda forto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Kaj ĉar ŝi tedadis lin per siaj vortoj ĉiutage kaj turmentadis lin, lia animo morte laciĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'Kaj li malkaŝis al ŝi sian tutan koron, kaj diris al ŝi: Tondilo ne tuŝis mian kapon, ĉar mi estas konsekrita al Dio de el la ventro de mia patrino. Se oni tondos miajn harojn, tiam forlasos min mia forto, mi senfortiĝos kaj fariĝos kiel la aliaj homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Kiam Delila vidis, ke li malkaŝis al ŝi sian tutan koron, ŝi sendis kaj vokigis la estrojn de la Filiŝtoj, dirante: Venu ĉi tiun fojon, ĉar li malkaŝis al mi sian tutan koron. Kaj venis al ŝi la estroj de la Filiŝtoj kaj alportis la arĝenton en siaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Kaj ŝi endormigis lin sur siaj genuoj, kaj alvokis homon, kaj detondigis la sep buklojn de lia kapo. Kaj ŝi komencis humiligadi lin, kaj lia forto lin forlasis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Kaj ŝi diris: Filiŝtoj iras al vi, Ŝimŝon! Li vekiĝis de sia dormo, kaj diris: Mi eliros, kiel ĉiufoje, kaj mi vigliĝos; sed li ne sciis, ke la Eternulo forlasis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Kaj la Filiŝtoj kaptis lin kaj elpikis liajn okulojn, kaj venigis lin en Gazan kaj ligis lin per kupraj ĉenoj; kaj li devis mueli en la malliberejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Dume la haroj de lia kapo komencis rekreski post la fortondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'La estroj de la Filiŝtoj kunvenis, por alporti grandan oferon al sia dio Dagon kaj por festeni, kaj ili diris: Nia dio transdonis en niajn manojn nian malamikon Ŝimŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Kaj la popolo vidis lin, kaj gloris sian dion, dirante: Nia dio transdonis en niajn manojn nian malamikon kaj la ruiniganton de nia lando kaj la mortiginton de multaj el ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Kiam ilia koro gajiĝis, ili diris: Voku Ŝimŝonon, ke li amuzu nin. Kaj oni vokis Ŝimŝonon el la malliberejo, kaj li faris amuzon al ili, kaj oni starigis lin inter la kolonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Kaj Ŝimŝon diris al la junulo, kiu kondukis lin je la mano: Lasu min, ke mi palpu la kolonojn, sur kiuj la domo staras, kaj mi apogos min al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Kaj la domo estis plena de viroj kaj virinoj, kaj tie estis ĉiuj estroj de la Filiŝtoj; kaj sur la tegmento estis ĉirkaŭ tri mil viroj kaj virinoj, kiuj rigardis la amuzadon de Ŝimŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Kaj Ŝimŝon vokis al la Eternulo, kaj diris: Mia Sinjoro, ho Eternulo, mi petas, rememoru min kaj fortigu min nur ĉi tiun fojon, ho Dio, por ke mi faru al la Filiŝtoj venĝon per unu fojo pro miaj du okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Kaj Ŝimŝon kaptis la du mezajn kolonojn, sur kiuj staris la domo, kaj apogis sin al ili, al unu per sia dekstra mano kaj al la dua per sia maldekstra mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Kaj Ŝimŝon diris: Mortu mia animo kune kun la Filiŝtoj! Kaj li ekpremis forte; kaj falis la domo sur la estrojn, kaj sur la tutan popolon, kiu estis en ĝi. Kaj la nombro de la mortintoj, kiujn li mortigis ĉe sia morto, estis pli granda, ol la nombro de tiuj, kiujn li mortigis dum sia vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Kaj venis liaj fratoj kaj la tuta domo de lia patro kaj prenis lin, kaj iris kaj enterigis lin inter Corea kaj Eŝtaol, en la tombo de lia patro Manoaĥ. Li estis juĝisto de Izrael dum dudek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Estis homo sur la monto de Efraim; lia nomo estis Miĥa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Li diris al sia patrino: La mil kaj cent arĝentaj moneroj, kiujn oni prenis de vi kaj pro kiuj vi malbenis antaŭ miaj oreloj, jen la arĝento estas ĉe mi; mi prenis ĝin. Kaj lia patrino diris: Mia filo estu benata de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Kaj li redonis la mil kaj cent arĝentajn monerojn al sia patrino. Kaj lia patrino diris: Mi dediĉis la arĝenton al la Eternulo el mia mano por mia filo, por fari figuron kaj idolon; nun mi redonas ĝin al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Sed li redonis la arĝenton al sia patrino. Lia patrino prenis ducent arĝentajn monerojn kaj donis ilin al orfandisto, kaj li faris el tio figuron kaj idolon, kiu restis en la domo de Miĥa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Tiu homo Miĥa havis domon de dio; kaj li faris efodon kaj domajn diojn, kaj konsekris unu el siaj filoj, ke li estu por li pastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'En tiu tempo ne ekzistis reĝo ĉe Izrael; ĉiu faradis tion, kio plaĉis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Estis junulo el Bet-Leĥem de Jehuda, el familio de Jehudaidoj, li estis Levido kaj loĝis tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Tiu homo iris el la urbo, el Bet-Leĥem de Jehuda, por ekloĝi tie, kie li trovos oportune. Kaj li venis dum sia vojirado sur la monton de Efraim al la domo de Miĥa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Kaj Miĥa diris al li: De kie vi venas? Kaj tiu diris al li: Mi estas Levido el Bet-Leĥem de Jehuda, kaj mi iras, por ekloĝi tie, kie mi trovos oportune.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Tiam Miĥa diris al li: Restu ĉe mi kaj estu por mi patro kaj pastro, kaj mi donados al vi po dek arĝentaj moneroj ĉiujare kaj necesajn vestojn kaj manĝaĵon. Kaj la Levido iris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Kaj la Levido konsentis resti ĉe tiu homo, kaj la junulo estis por li kiel unu el liaj filoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Kaj Miĥa konsekris la Levidon, kaj la junulo fariĝis por li pastro kaj loĝis en la domo de Miĥa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Kaj Miĥa diris: Nun mi scias, ke la Eternulo bonfaros al mi, ĉar Levido fariĝis por mi pastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'En tiu tempo ne ekzistis reĝo ĉe Izrael; kaj en tiu tempo la tribo de Dan serĉis por si posedaĵon, por ekloĝi, ĉar ĝis tiu tempo ili ne ricevis posedaĵon inter la triboj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Kaj la Danidoj sendis kvin homojn el sia tribo, el siaj reprezentantoj, virojn batalkapablajn el Corea kaj Eŝtaol, por rigardi la landon kaj esplori ĝin, kaj diris al ili: Iru, esploru la landon. Kaj ili venis sur la monton de Efraim al la domo de Miĥa kaj tranoktis tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Kiam ili estis kun la domanoj de Miĥa, ili rekonis la voĉon de la juna Levido, kaj eniris tien, kaj diris al li: Kiu venigis vin ĉi tien? kaj kion vi faras ĉi tie? kaj kion vi bezonas ĉi tie?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Kaj li diris al ili: Tiel kaj tiel agis kun mi Miĥa, kaj li dungis min, kaj mi fariĝis pastro por li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'Kaj ili diris al li: Demandu, ni petas, Dion, por ke ni eksciu, ĉu estos sukcesa nia vojo, kiun ni iras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Kaj la pastro diris al ili: Iru en paco; laŭ la Eternulo estas via vojo, kiun vi iras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Kaj tiuj kvin viroj ekiris kaj venis en Laiŝon, kaj vidis la popolon, ke ĝi tie loĝas senzorge, laŭ la maniero de la Cidonanoj, trankvile kaj fide, kaj neniu per io ofendas ilin en la lando aŭ regas super ili, kaj de la Cidonanoj ili estas malproksime kaj kun neniu ili havas ian aferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Kaj ili venis al siaj fratoj en Corean kaj Eŝtaolon; kaj iliaj fratoj diris al ili: Kion vi raportos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'Kaj ili diris: Leviĝu, kaj ni iru kontraŭ ilin; ĉar ni vidis, ke la lando estas tre bona; estu trankvilaj, ne prokrastu iri kaj veni kaj ekposedi la landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Kiam vi venos, vi venos al popolo, kiu ne pensas pri danĝero, kaj la lando estas vasta; Dio transdonas ĝin en viajn manojn; tio estas loko, kie mankas nenio, kio estas sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Kaj elmoviĝis el tie el la tribo de la Danidoj, el Corea kaj Eŝtaol, sescent viroj, zonitaj per bataliloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Kaj ili iris, kaj stariĝis tendare en Kirjat-Jearim, en la regiono de Jehuda. Tial oni ĝis nun nomas tiun lokon Tendaro de Dan; ĝi estas post Kirjat-Jearim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Kaj ili iris de tie sur la monton de Efraim kaj venis al la domo de Miĥa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Kaj la kvin viroj, kiuj iris, por esplorrigardi la landon Laiŝ, diris al siaj fratoj: Ĉu vi scias, ke en ĉi tiuj domoj troviĝas efodo kaj domaj dioj kaj figuro kaj idolo? pripensu do, kion vi devas fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'Kaj ili turniĝis tien kaj eniris en la domon de la juna Levido, en la domon de Miĥa, kaj salutis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'La sescent viroj el la Danidoj, zonitaj per siaj bataliloj, staris antaŭ la pordego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'Kaj la kvin viroj, kiuj iris, por esplorrigardi la landon, eniris tien kaj prenis la figuron kaj la efodon kaj la domajn diojn kaj la idolon. Dume la pastro staris antaŭ la pordego, kun la sescent viroj, zonitaj per bataliloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Kiam tiuj eniris en la domon de Miĥa, kaj prenis la figuron, la efodon, la domajn diojn, kaj la idolon, la pastro diris al ili: Kion vi faras?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'Sed ili diris al li: Silentu, metu vian manon sur vian buŝon; kaj iru kun ni kaj estu por ni patro kaj pastro; ĉu pli bone estas por vi esti pastro por la domo de unu homo, ol esti pastro por tribo kaj gento en Izrael?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Kaj tio bone plaĉis al la pastro, kaj li prenis la efodon kaj la domajn diojn kaj la figuron kaj iris inter la popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Kaj ili turniĝis kaj iris, kaj sendis la infanojn kaj la brutojn kaj la pakaĵojn antaŭ sin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Kiam ili malproksimiĝis de la domo de Miĥa, la homoj, kiuj estis en la domoj najbaraj de Miĥa, kun krio kolektiĝis kaj kuris post la Danidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Kaj ili kriis al la Danidoj; kaj ĉi tiuj turnis siajn vizaĝojn, kaj diris al Miĥa: Kio estas al vi, ke vi faras krion?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Kaj li diris: Miajn diojn, kiujn mi faris, vi forprenis, kaj ankaŭ la pastron, kaj vi foriris; kaj kio ankoraŭ estas al mi? kial do vi demandas, kio estas al mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Kaj la Danidoj diris al li: Ne aŭdigu vian voĉon antaŭ ni, ĉar alie atakos vin koleraj homoj kaj vi pereigos vian animon kaj la animon de via domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Kaj la Danidoj foriris sian vojon. Kaj Miĥa vidis, ke ili estas pli fortaj ol li; kaj li returniĝis kaj revenis en sian domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Sed tiuj prenis tion, kion faris Miĥa, kaj la pastron, kiu estis ĉe li; kaj ili venis en Laiŝon, kontraŭ la popolon trankvilan kaj senzorgan, kaj venkobatis ĝin per la glavo; kaj la urbon ili forbruligis per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'Kaj estis neniu savanto, ĉar ĝi estis malproksime de Cidon kaj ili havis neniajn aferojn kun iu, kaj ĝi estis en la valo, kiu troviĝas apud Bet-Reĥob. Ili konstruis la urbon kaj ekloĝis en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'Ili donis al la urbo la nomon Dan, laŭ la nomo de sia patro, kiu naskiĝis de Izrael; antaŭe la nomo de la urbo estis Laiŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Kaj la Danidoj starigis al si la figuron; kaj Jehonatan, filo de Gerŝom, filo de Manase, li kaj liaj filoj estis pastroj por la tribo de la Danidoj, ĝis la tago, kiam ili estis forkaptitaj el la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Kaj dum la tuta tempo, kiam la domo de Dio estis en Ŝilo, ili havis ĉe si la idolon de Miĥa, kiun li faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'En tiu tempo, kiam ne ekzistis reĝo ĉe Izrael, loĝis iu Levido sur la deklivo de la monto de Efraim. Li prenis al si kromedzinon el Bet-Leĥem de Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Kaj lia kromedzino perfidis lin kaj foriris de li en la domon de sia patro en Bet-Leĥem de Jehuda, kaj ŝi restis tie kvar monatojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Kaj leviĝis ŝia edzo kaj iris al ŝi, por paroli al ŝia koro, por revenigi ŝin; kun li estis lia junulo kaj paro da azenoj. Kaj ŝi enirigis lin en la domon de sia patro; kaj la patro de la juna virino lin ekvidis kaj akceptis lin kun ĝojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Kaj retenis lin lia bopatro, la patro de la juna virino, kaj li restis ĉe li dum tri tagoj; kaj ili manĝis kaj trinkis kaj tranoktis tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'En la kvara tago ili leviĝis frue matene, kaj li intencis foriri; sed la patro de la juna virino diris al sia bofilo: Fortigu vian koron per peco da pano; kaj poste vi iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Kaj ili restis, kaj ambaŭ kune manĝis kaj trinkis. Kaj la patro de la juna virino diris al la viro: Mi petas vin, tranoktu kaj ĝojigu vian koron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'La viro leviĝis, por foriri; sed lia bopatro insiste petis lin, kaj li restis kaj tranoktis tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'En la kvina tago li leviĝis frue matene, por iri; sed la patro de la juna virino diris: Fortigu, mi petas, vian koron, kaj ne rapidu, ĝis finiĝos la tago. Kaj ili ambaŭ manĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Kaj la viro leviĝis, por iri, li kaj lia kromedzino kaj lia junulo. Sed lia bopatro, la patro de la juna virino, diris al li: Jen finiĝis la tago kaj fariĝas vespero, tranoktu do, mi petas; jen la tago finiĝis, tranoktu ĉi tie, ke via koro faru al si ĝojon; morgaŭ frue vi leviĝos, por iri vian vojon, kaj vi iros al via tendo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Sed la viro ne volis tranokti; li leviĝis kaj iris. Kaj li venis al la ĉirkaŭaĵo de Jebus (tio estas Jerusalem); kun li estis paro da ŝarĝitaj azenoj, kaj ankaŭ lia kromedzino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Kiam ili estis antaŭ Jebus, la tago jam forte kliniĝis. Kaj la junulo diris al sia sinjoro: Venu, ni eniru en ĉi tiun urbon de la Jebusidoj, kaj ni tranoktu en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Sed lia sinjoro diris al li: Ni ne eniros en urbon de aligentuloj, kiuj ne estas el la Izraelidoj; ni iros pluen, ĝis Gibea.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Kaj li diris al sia junulo: Iru, ke ni alproksimiĝu al unu el la lokoj, kaj ni tranoktu en Gibea aŭ en Rama.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Kaj ili iris pluen kaj iris; kaj la suno subiris antaŭ ili apud Gibea, kiu apartenis al la Benjamenidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'Kaj ili turniĝis tien, por eniri kaj tranokti en Gibea. Kaj li eniris kaj sidiĝis sur la strato; sed neniu invitis ilin en la domon, por tranokti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Sed jen iu maljunulo venis vespere de sia laboro de la kampo; li estis de la monto de Efraim kaj loĝis tiutempe en Gibea; kaj la loĝantoj de tiu loko estis Benjamenidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Li levis siajn okulojn kaj ekvidis la fremdan homon sur la strato de la urbo. Kaj la maljunulo diris: Kien vi iras? kaj de kie vi venas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Kaj tiu diris al li: Ni iras el Bet-Leĥem de Jehuda al la deklivo de la monto de Efraim, de kie mi estas. Mi iris al Bet-Leĥem de Jehuda, kaj nun mi iras al la domo de la Eternulo; kaj neniu invitas min en la domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Ni havas pajlon kaj manĝaĵon por niaj azenoj, ankaŭ panon kaj vinon mi havas por mi kaj por via sklavino, kaj por la junulo, kiu estas kun viaj sklavoj; nenio mankas al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Kaj la maljunulo diris: Paco estu al vi; ĉion, kio mankus al vi, mi prenas sur min; nur ne tranoktu sur la strato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Kaj li envenigis lin en sian domon, kaj li donis manĝaĵon al la azenoj; kaj ili lavis siajn piedojn kaj manĝis kaj trinkis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Dum ili ĝojigadis sian koron, jen la loĝantoj de la urbo, homoj malmoralaj, ĉirkaŭis la domon, frapis je la pordo, kaj diris al la maljuna domomastro jene: Elirigu la homon, kiu venis en vian domon, ke ni lin ekkonu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Tiam eliris al ili la domomastro, kaj diris al ili: Ne, miaj fratoj, ne faru malbonon; ĉar tiu homo venis en mian domon, ne faru tian malnoblaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Jen mi havas filinon virgulinon, kaj li havas kromedzinon; mi elirigos ilin, kaj vi malhonoru ilin, kaj faru al ili tion, kio plaĉas al vi; sed kun ĉi tiu viro ne faru tian abomenindaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Sed la homoj ne volis aŭskulti lin. Tiam la viro prenis sian kromedzinon kaj elirigis al ili sur la straton. Kaj ili ekkonis ŝin, kaj faris al si amuzon kun ŝi dum la tuta nokto, ĝis la mateno; kaj ili forliberigis ŝin, kiam leviĝis la matenruĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Kaj la virino venis antaŭ la mateniĝo, kaj falis antaŭ la pordo de la domo de tiu homo, kie estis ŝia sinjoro; kaj ŝi kuŝis, ĝis fariĝis lume.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Matene leviĝis ŝia sinjoro kaj malfermis la pordon de la domo, kaj eliris, por iri sian vojon; kaj jen li vidas, ke la virino, lia kromedzino, kuŝas antaŭ la pordo de la domo, kaj ŝiaj manoj estas sur la sojlo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Kaj li diris al ŝi: Leviĝu, kaj ni iros. Sed estis nenia respondo. Tiam li prenis ŝin sur la azenon, leviĝis, kaj iris al sia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Kiam li venis en sian domon, li prenis tranĉilon, prenis sian kromedzinon kaj distranĉis ŝin kun ŝiaj ostoj en dek du partojn kaj dissendis tion en ĉiujn regionojn de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Kaj ĉiu, kiu tion vidis, diris: Ne estis kaj ne vidiĝis io simila de post la tago, kiam la Izraelidoj eliris el la lando Egipta, ĝis nun; atentu tion, konsiliĝu, kaj decidu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Kaj eliris ĉiuj Izraelidoj, kaj kolektiĝis la tuta komunumo kiel unu homo, de Dan ĝis Beer-Ŝeba, kaj la lando Gilead, antaŭ la Eternulo en Micpa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Kaj kunvenis la estroj de la tuta popolo, ĉiuj triboj de Izrael, en la kunvenejon de la popolo de Dio, kvarcent mil piedirantoj kapablaj eltiri glavon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'La Benjamenidoj aŭdis, ke la Izraelidoj venis en Micpan. Kaj la Izraelidoj diris: Diru, kiamaniere okazis tiu malbonaĵo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Tiam respondis la Levido, la edzo de la mortigita virino, kaj diris: Mi venis en Gibean de la Benjamenidoj, mi kun mia kromedzino, por tranokti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Kaj leviĝis kontraŭ min la loĝantoj de Gibea, kaj ĉirkaŭis pro mi la domon nokte. Min ili intencis mortigi, kaj mian kromedzinon ili turmentis tiel, ke ŝi mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Tiam mi prenis mian kromedzinon, distranĉis ŝin kaj dissendis en ĉiujn regionojn de Izrael; ĉar ili faris malĉastaĵon kaj malnoblaĵon en Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Jen vi ĉiuj estas Izraelidoj; faru konsiliĝon kaj decidon ĉi tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Kaj leviĝis la tuta popolo kiel unu homo, kaj diris: Neniu el ni iros al sia tendo, kaj neniu el ni revenos al sia domo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'sed jen estas, kion ni faros al Gibea: ni lotos pri ĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'kaj ni prenos po dek homoj el ĉiu cento, el ĉiuj triboj, po cent el mil kaj po mil el dek mil, ke ili alportu manĝaĵon por la popolo, por ke ĉi tiu iru en Gibean de la Benjamenidoj, kaj agu kontraŭ ĝi konforme al la malnoblaĵo, kiun ĝi faris en Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Kaj kolektiĝis kontraŭ la urbo ĉiuj Izraelidoj unuanime, kiel unu homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Kaj la triboj de Izrael sendis homojn al ĉiuj familioj de Benjamen, por diri: Kio estas la malbonaĵo, kiu estas farita ĉe vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Eligu do nun la kanajlajn homojn, kiuj estas en Gibea, kaj ni mortigos ilin kaj ekstermos la malbonon el Izrael. Sed la Benjamenidoj ne volis obei la voĉon de siaj fratoj, la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Kaj la Benjamenidoj kolektiĝis el la urboj en Gibea, por eliri milite kontraŭ la Izraelidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Kaj la nombro de la Benjamenidoj el la urboj en tiu tago estis dudek ses mil homoj pretaj eltiri glavon; krom tio el la loĝantoj de Gibea estis la nombro de sepcent homoj plej taŭgaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'El tiu tuta popolo estis sepcent homoj plej taŭgaj, maldekstruloj; ĉiu el ili povis ĵeti ŝtonon kontraŭ haron, kaj ne maltrafi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Kaj la nombro de la Izraelidoj, krom la Benjamenidoj, estis kvarcent mil homoj pretaj eltiri glavon; ĉiuj ili estis batalkapablaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Kaj ili leviĝis kaj iris en Bet-Elon kaj demandis Dion, kaj la Izraelidoj diris: Kiu el ni devas iri antaŭe milite kontraŭ la Benjamenidojn? Kaj la Eternulo diris: Jehuda antaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Kaj la Izraelidoj leviĝis matene kaj eksieĝis Gibean.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Kaj la Izraelidoj eliris milite kontraŭ la Benjamenidojn, kaj la Izraelidoj komencis batalon kontraŭ ili antaŭ Gibea.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Kaj eliris la Benjamenidoj el Gibea kaj batis en tiu tago el la Izraelidoj dudek du mil homojn sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Sed la popolo de la Izraelidoj ekscitis sian kuraĝon, kaj denove komencis batalon sur la loko, kie ili batalis en la unua tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Kaj la Izraelidoj iris kaj ploris antaŭ la Eternulo ĝis la vespero, kaj demandis la Eternulon, dirante: Ĉu ni devas plue alproksimiĝi milite al la Benjamenidoj, niaj fratoj? Kaj la Eternulo diris: Iru kontraŭ ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Kaj la Izraelidoj alpaŝis al la Benjamenidoj en la dua tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'Kaj la Benjamenidoj eliris al ili renkonte el Gibea en la dua tago kaj batis el la Izraelidoj ankoraŭ dek ok mil homojn sur la teron; ĉiuj ili estis eltirantoj de glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Tiam ĉiuj Izraelidoj kaj la tuta popolo iris kaj venis en Bet-Elon kaj ploris kaj restis tie antaŭ la Eternulo kaj fastis en tiu tago ĝis la vespero kaj alportis bruloferojn kaj pacoferojn antaŭ la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'Kaj la Izraelidoj demandis la Eternulon (tie estis en tiu tempo la kesto de interligo de Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'kaj Pineĥas, filo de Eleazar, filo de Aaron, staris antaŭ ĝi en tiu tempo); kaj ili diris: Ĉu ni devas plue elpaŝi batale kontraŭ niajn fratojn la Benjamenidojn, aŭ ĉu ni devas ĉesi? Kaj la Eternulo diris: Iru, ĉar morgaŭ Mi transdonos ilin en viajn manojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Kaj la Izraelidoj aranĝis embuskojn ĉirkaŭe de Gibea.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Kaj la Izraelidoj eliris kontraŭ la Benjamenidojn en la tria tago kaj stariĝis kontraŭ Gibea kiel antaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Kaj la Benjamenidoj eliris kontraŭ la popolon, malproksimiĝis de la urbo, kaj komencis batadi la popolon kiel en la antaŭaj fojoj, sur la vojoj, el kiuj unu iras al Bet-El kaj la dua al Gibea, kaj mortigis pli-malpli tridek homojn el la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Kaj la Benjamenidoj diris al si: Ili falas antaŭ ni kiel antaŭe. Kaj la Izraelidoj diris: Ni kuru, por ke ni ellogu ilin el la urbo sur la vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Kaj ĉiuj Izraelidoj leviĝis de sia loko kaj stariĝis en Baal-Tamar. Kaj la embuskuloj de la Izraelidoj ĵetis sin el sia loko, el la kaverno Geba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Kaj venis antaŭ Gibean dek mil elektitaj viroj el la tuta Izrael, kaj estis kruela batalo; kaj ili ne sciis, ke trafos ilin malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'Kaj la Eternulo frapis la Benjamenidojn antaŭ la Izraelidoj; kaj la Izraelidoj ekstermis en tiu tago el la Benjamenidoj dudek kvin mil kaj cent homojn; ĉiuj ili estis eltirantoj de glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'La Benjamenidoj vidis, ke tiuj estis frapitaj kaj la Izraelidoj cedis la lokon al la Benjamenidoj; ĉar ili fidis la embuskon, kiun ili aranĝis ĉe Gibea.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Kaj la embuskuloj rapidis kaj ĵetis sin kontraŭ Gibean, kaj la embuskuloj eniris kaj batis la tutan urbon per glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Estis interkonsentite inter la Izraelidoj kaj la embuskuloj, ke ĉi tiuj suprenigos grandan kolonon da fumo el la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Kiam la Izraelidoj retiriĝis dum la batalo, kaj la Benjamenidoj komencis mortigi Izraelidojn kaj mortigis pli-malpli tridek homojn, kaj diris: Ili falas antaŭ ni kiel en la unua batalo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'tiam komencis leviĝadi el la urbo kolono da fumo. La Benjamenidoj ekrigardis returne, kaj ili ekvidis, ke el la tuta urbo leviĝas flamoj al la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Kaj la Izraelidoj returniĝis, kaj la Benjamenidoj terure konsterniĝis; ĉar ili vidis, ke malfeliĉo ilin trafis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'Kaj ili turniĝis antaŭ la Izraelidoj, al la vojo, kiu kondukas al la dezerto; sed la batalo postkuris ilin, kaj la elirintoj el la urboj ekstermis ilin dumvoje,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'ĉirkaŭis la Benjamenidojn, persekutis ilin ĝis Menuĥa, kaj piedpremis ilin ĝis la orienta flanko de Gibea.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Kaj falis el la Benjamenidoj dek ok mil homoj; ĉiuj ili estis fortaj militistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Kaj ili sin turnis kaj ekkuris al la dezerto, al la roko Rimon; kaj oni batis el ili sur la vojo kvin mil homojn, kaj oni postkuris ilin ĝis Gidom kaj batis el ili ankoraŭ du mil homojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'La nombro de ĉiuj falintoj el la Benjamenidoj en tiu tago estis dudek kvin mil homoj eltirantoj de glavo; ĉiuj ili estis fortaj militistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Kaj ili sin turnis kaj forkuris en la dezerton, al la roko Rimon, sescent homoj; kaj ili restis ĉe la roko Rimon kvar monatojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Sed la Izraelidoj reiris al la Benjamenidoj, kaj mortigis per glavo la urbanojn, la brutojn, kaj ĉion, kion ili trovis; kaj ĉiujn urbojn, kiujn ili renkontis, ili forbruligis per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Kaj la Izraelidoj ĵuris en Micpa, dirante: Neniu el ni donos sian filinon edzinige al Benjamenido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Kaj la popolo venis en Bet-Elon, kaj restis tie ĝis la vespero antaŭ Dio, kaj levis sian voĉon kaj forte ploris,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'kaj diris: Kial, ho Eternulo, Dio de Izrael, fariĝis tio en Izrael, ke malaperis nun el Izrael unu tribo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'La morgaŭan tagon la popolo leviĝis frue kaj konstruis tie altaron kaj oferis bruloferojn kaj pacoferojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Kaj la Izraelidoj diris: Kiu homo el ĉiuj triboj de Izrael ne venis kun la komunumo al la Eternulo? Ĉar estis farita granda ĵuro pri tiuj, kiuj ne venis al la Eternulo en Micpan, ke ili estos mortigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Kaj la Izraelidoj ekpentis pri siaj fratoj la Benjamenidoj, kaj diris: Forhakita estas hodiaŭ unu tribo el Izrael!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'kion ni faros al ili, al la restintoj, koncerne edzinojn? ni ĵuris ja per la Eternulo, ke ni ne donos al ili edzinojn el niaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Kaj ili diris: Kiu homo el la triboj de Izrael ne venis al la Eternulo en Micpan? Kaj tiam montriĝis, ke en la tendaron al la komunumo venis neniu el Jabeŝ en Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Kaj oni reviziis la popolon, kaj montriĝis, ke tie estas neniu el la loĝantoj de Jabeŝ en Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Tiam la komunumo sendis tien dek du mil homojn el la viroj batalkapablaj, kaj ordonis al ili jene: Iru kaj mortigu per glavo la loĝantojn de Jabeŝ en Gilead, ankaŭ la virinojn kaj infanojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Kaj tiel agu: ĉiun virseksulon, kaj ĉiun virinon, kiu ekkonis kuŝejon de viro, ekstermu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Kaj ili trovis inter la loĝantoj de Jabeŝ en Gilead kvarcent junajn virgulinojn, kiuj ne ekkonis kuŝejon de viro; kaj ili venigis ilin en la tendaron en Ŝilon, kiu estas en la lando Kanaana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Kaj la tuta komunumo sendis, por paroli kun la Benjamenidoj, kiuj estis ĉe la roko Rimon, kaj anonci al ili pacon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Tiam la Benjamenidoj revenis, kaj oni donis al ili la virinojn, kiuj restis vivaj el la virinoj de Jabeŝ en Gilead; sed ne estis sufiĉe por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Kaj la popolo bedaŭris pri Benjamen, ĉar la Eternulo faris fendon en la triboj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Kaj la plejaĝuloj de la komunumo diris: Kion ni faru al la restintoj koncerne edzinojn? ekstermitaj estas ja la virinoj de Benjamen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Kaj ili diris: La restintoj el la Benjamenidoj bezonas ja heredontojn, por ke ne malaperu tribo el Izrael;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'kaj ni ne povas doni al ili edzinojn el niaj filinoj, ĉar la Izraelidoj ĵuris, dirante: Malbenita estu tiu, kiu donos edzinon al Benjamenido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Sed ili diris: Jen ĉiujare estas festo de la Eternulo en Ŝilo, kiu estas norde de Bet-El, oriente de la vojo, kiu kondukas de Bet-El al Ŝeĥem, kaj sude de Lebona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Kaj ili ordonis al la Benjamenidoj jene: Iru kaj faru insidon en la vinberĝardenoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'kaj kiam vi vidos, ke la knabinoj de Ŝilo eliras, por danci en rondoj, tiam eliru el la vinberĝardenoj kaj kaptu al vi ĉiu edzinon el la knabinoj de Ŝilo kaj iru en la landon de la Benjamenidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Kaj se venos iliaj patroj aŭ fratoj kun plendo al ni, ni diros al ili: Pardonu nin pro ili; ĉar ni ne prenis por ĉiu edzinon en la milito, kaj vi ne donis al ili; tial vi estas nun senkulpaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Kaj tiel agis la Benjamenidoj, kaj prenis edzinojn laŭ sia nombro el la dancrondoj, rabinte ilin; kaj ili iris kaj revenis al sia posedaĵo kaj konstruis urbojn kaj ekloĝis en ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Kaj en la sama tempo disiris de tie la Izraelidoj, ĉiu al sia tribo kaj al sia familio, kaj ĉiu foriris de tie al sia posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'En tiu tempo ne ekzistis reĝo ĉe Izrael; ĉiu faradis tion, kio plaĉis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'En la tempo, kiam regis la juĝistoj, iam malsato okazis en la lando; kaj foriris viro el Bet-Leĥem en Judujo, por pasloĝi en la lando de Moab; li kaj lia edzino kaj liaj du filoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'La nomo de la viro estis Elimeleĥ, kaj la nomo de lia edzino estis Naomi, kaj la nomoj de liaj du filoj estis Maĥlon kaj Kiljon, Efratanoj el Bet-Leĥem en Judujo. Kaj ili venis sur la kampojn de Moab kaj restis tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Elimeleĥ, la edzo de Naomi, mortis; kaj restis ŝi kun siaj du filoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Ambaŭ edziĝis kun Moabidinoj; la nomo de unu estis Orpa, kaj la nomo de la dua estis Rut; kaj ili loĝis tie ĉirkaŭ dek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Sed mortis ankaŭ ambaŭ, Maĥlon kaj Kiljon; kaj restis nur la virino sola, senigita je sia edzo kaj siaj du filoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Ŝi leviĝis kun siaj bofilinoj, por iri returne el la lando de Moab; ĉar ŝi aŭdis en la lando de Moab, ke la Eternulo rememoris Sian popolon, donante al ĝi panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Ŝi eliris el la loko, kie ŝi loĝis, kun siaj du bofilinoj; kaj ili iris sur la vojo, por ke ili revenu al la lando de Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'Naomi diris al siaj du bofilinoj: Iru, kaj revenu ĉiu el vi al la domo de sia patrino; la Eternulo favoru vin tiel same, kiel vi estis favorkoraj al la mortintoj kaj al mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'la Eternulo favoru vin, ke vi trovu ripozon, ĉiu el vi en domo de sia edzo. Ŝi kisis ilin, kaj ili levis sian voĉon kaj ploris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'Kaj ili diris al ŝi: Ni volas iri kun vi al via popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Naomi respondis: Iru returne, miaj filinoj; kial do vi irus kun mi? Ĉu ankoraŭ ekzistas filoj en mia utero, ke vi edziniĝu kun ili?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Revenu, miaj filinoj, foriru; ĉar mi jam estas tro maljuna por edziniĝi kun viro. Eĉ se mi dirus, ke mi havas ankoraŭ esperon, eĉ se mi jam havus edzon hodiaŭ nokte, kaj eĉ se mi naskus filojn:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'ĉu pri ili vi esperu, ĝis ili plenaĝiĝos? ĉu por ili vi atendu, ne edziniĝante kun viro? Ne, miaj filinoj; estas tre maldolĉe al mi pro vi, ĉar la mano de la Eternulo afliktis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Sed ili levis sian voĉon kaj ploris plue. Kaj Orpa kisis sian bopatrinon, sed Rut aliĝis al ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Kaj ĉi tiu diris: Jen via bofratino reiris al sia gento kaj al siaj dioj; iru vi ankaŭ returne post via bofratino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Sed Rut diris: Ne petegu min, ke mi vin forlasu, aŭ ke mi returnu min kaj ĉesu sekvi vin; ĉar kien vi iros, mi ankaŭ iros, kaj kie vi noktos, mi ankaŭ noktos; via popolo ankaŭ estos mia popolo, kaj via Dio estos mia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Sur la loko, kie vi mortos, mi ankaŭ mortos, kaj tie oni min enterigos. La Eternulo faru al mi tion kaj pli, se io krom la morto disigos min de vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Kiam Naomi vidis, ke ŝi firme decidis iri kun ŝi, tiam ŝi ĉesis disputi kun ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'Kaj ili ambaŭ iradis, ĝis ili alvenis en Bet-Leĥemon. Kaj kiam ili eniris en Bet-Leĥemon, la tuta loĝantaro de la urbo ekbruis pri ili, dirante: Ĉu tio estas Naomi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Kaj ŝi respondis al ili: Ne nomu min Naomi, nomu min Mara; ĉar la Plejpotenculo faris al mi maldolĉegon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'kun pleneco mi foriris, sed la Eternulo revenigis min malplena; kial do vi nomus min Naomi, konsiderante, ke la Eternulo atestis kontraŭ mi kaj la Plejpotenculo afliktis min?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Tiel Naomi revenis, kaj kun ŝi ankaŭ Rut, la Moabidino, ŝia bofilino, kiu revenis el la lando de Moab; kaj ili venis en Bet-Leĥemon je la komenco de la rikolto de hordeo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Naomi havis parencon de ŝia edzo, viron eminentan, el la familio de Elimeleĥ; lia nomo estis Boaz.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Kaj la Moabidino Rut diris al Naomi: Mi iros sur la kampon, kaj mi kolektos spikojn post tiu, ĉe kiu mi trovos favoron. Kaj ŝi respondis: Iru, mia filino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Kaj ŝi foriris, kaj venis kaj kolektis post la rikoltistoj. Kaj okazis, ke la parcelo de la kampo apartenis al Boaz, kiu estis el la familio de Elimeleĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Kaj jen Boaz venis el Bet-Leĥem, kaj li salutis la rikoltistojn: La Eternulo estu kun vi! Kaj ili respondis al li: La Eternulo vin benu!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Kaj Boaz demandis sian serviston, la estron de la rikoltistoj: Kiu estas ĉi tiu knabino?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Kaj la servisto, la estro de la rikoltistoj, respondis kaj diris: Ŝi estas Moaba knabino, kiu revenis kun Naomi el la lando de Moab;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'ŝi diris: Permesu al mi, ke mi sekvu kaj kolektu apud la garboj, post la rikoltistoj; kaj ŝi restis ĉi tie de la mateno ĝis nun; ŝi ĵus sidiĝis en la dometo por iomete da tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Kaj Boaz diris al Rut: Ĉu vi aŭdas, mia filino? ne iru kolekti sur la kampo de iu fremdulo, kaj ankaŭ ne foriru de ĉi tie, sed restu ĉi tie kun miaj junulinoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'rimarku la kampon, kie ili rikoltas, kaj sekvu ilin; mi jam ordonis al la servistoj, ke ili ne malhelpu vin; kaj kiam vi soifos, iru al la vazaro, kaj trinku el tio, el kio la servistaro ĉerpas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Ŝi ĵetis sin vizaĝaltere, kaj diris al li: Kial do mi trovis favoron en viaj okuloj, ke vi atentas min, kvankam mi estas fremdulino?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Kaj Boaz respondis kaj diris al ŝi: Jam estas rakontita al mi ĉio, kion vi faris al via bopatrino post la morto de via edzo: ke vi forlasis viajn gepatrojn kaj vian naskiĝlandon, kaj iris al popolo, kiun vi ne konis hieraŭ nek antaŭhieraŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'La Eternulo rekompencu vin pro ĉi tiu faro, kaj via rekompenco estu plena de la Eternulo, Dio de Izrael, sub kies flugiloj vi serĉis protekton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Kaj ŝi diris: Estus sufiĉe, ke mi trovu favoron en viaj okuloj, mia sinjoro, ĉar vi konsolis min kaj parolis amike al via sklavino, kvankam mi ne valoras esti egala al iu el viaj sklavinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Kaj en la horo de la manĝado Boaz diris al ŝi: Alproksimiĝu kaj manĝu kune, vi ankaŭ povas trempi vian panon en la vinagro. Kaj ŝi sidiĝis ĉe la flanko de la rikoltistoj; kaj ili metis antaŭ ŝin rostitajn grajnojn, kaj ŝi manĝis kaj satiĝis, kaj ankaŭ havis restaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Kiam ŝi leviĝis, por kolekti, Boaz ordonis al siaj servistoj, dirante: Eĉ inter la garboj lasu ŝin kolekti, kaj ne hontigu ŝin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'kaj vi ankaŭ ŝajnigu al ŝi, ke vi postlasis la malgrandajn garbetojn, kaj vi permesu al ŝi, ke ŝi kolektu ilin, kaj ne riproĉu ŝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Kaj ŝi kolektadis sur la kampo ĝis la vespero, kaj ŝi draŝis tion, kion ŝi kolektis, kaj tio estis ĉirkaŭ efo da hordeo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Kaj ŝi levis tion, kaj iris en la urbon; kaj ŝia bopatrino vidis tion, kion ŝi kolektis; ŝi ankaŭ elprenis, kaj donis al ŝi la restaĵon, kiun ŝi posedis de post sia satiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Ŝia bopatrino diris al ŝi: Kie vi kolektis hodiaŭ? kaj kie vi amasigis? estu benata tiu, kiu vin tiel favore akceptis! Ŝi rakontis al sia bopatrino, kie ŝi laboris, kaj ŝi diris: La nomo de la viro, ĉe kiu mi laboris hodiaŭ, estas Boaz.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Tiam Naomi diris al sia bofilino: Li estu benata de la Eternulo, kiu ne fortiris Sian favoron for de la vivantoj kaj de la mortintoj. Kaj Naomi plue diris al ŝi: La viro estas nia parenco, unu el niaj savantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Kaj Rut, la Moabidino, diris: Li ankaŭ diris al mi: Restu kune kun miaj servistoj, ĝis ili finos la tutan rikolton, kiu apartenas al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Naomi respondis al sia bofilino Rut: Estos bone por vi, mia filino, ke vi ĉiam iru kun liaj junulinoj, ĉar eble oni hontigus vin, se vi irus aliloken.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Kaj ŝi kuniĝis kun la junulinoj de Boaz, por kolekti, ĝis la fino de la rikolto de hordeo kaj de la rikolto de tritiko; kaj poste ŝi loĝis kune kun sia bopatrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Naomi, ŝia bopatrino, diris al ŝi: Mia bofilino, mia celo estas, ke mi trovu por vi ripozejon, kie pliboniĝos via stato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Vidu nun, nia parenco Boaz, kun kies junulinoj vi kuniĝis, ventumas hordeon dum ĉi tiu nokto en la draŝejo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'lavu do vin kaj oleu vin kaj vestu vin per viaj plej bonaj vestoj, kaj iru en la draŝejon; ne vidigu vin al la viro, antaŭ ol li finos manĝi kaj trinki;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'kaj kiam li kuŝiĝos, rimarku la lokon, kie li kuŝas, iru tien, malkovru la piedparton de la kuŝejo, kaj kuŝiĝu; kaj li diros al vi, kion vi devos fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Rut respondis al ŝi: Kion vi diras al mi, tion mi faros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Kaj ŝi iris en la draŝejon, kaj faris tion, kion ŝia bopatrino ordonis al ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Kiam Boaz estis manĝinta kaj trinkinta kaj gajiĝis, li iris por kuŝiĝi malantaŭ grenamaso; kaj ŝi venis kviete, kaj malkovris la piedparton de la kuŝejo, kaj kuŝiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'En la noktomezo la viro ektimiĝis; li turnis sin, kaj li ekvidis, ke virino kuŝas ĉe liaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'Li demandis: Kiu vi estas? Kaj ŝi respondis: Mi estas Rut, via servistino; etendu vian mantelon sur vian servistinon, ĉar vi estas savanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'Kaj li diris: Estu benata de la Eternulo, mia filino; via lasta piaĵo estas pli granda, ol la unua, ĉar vi ne volas iri kun la junuloj, ĉu ili estas malriĉaj, ĉu riĉaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Kaj nun, mia filino, ne timu; mi faros al vi ĉion, kion vi petos de mi; ĉar estas sciate en la tuta urbo de mia popolo, ke vi estas bravulino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Kaj nun, kvankam vere mi estas parenco, tamen ekzistas parenco pli proksima ol mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Restu ĉi tie la nokton; kaj kiam venos la mateno, se la alia parenco perfekte elaĉetos vin, lasu elaĉeti vin; sed se li ne volos vin elaĉeti, tiam mi vin elaĉetos, kiel la Eternulo vivas. Kuŝu ĝis la tagiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'Kaj ŝi kuŝis ĉe liaj piedoj ĝis la tagiĝo; sed ŝi leviĝis, antaŭ ol oni povis rekoni unu la alian. Kaj li diris: Mi ne volas, ke iu sciiĝu, ke ĉi tiu virino estis en mia draŝejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Kaj li diris: Alportu la ŝalon, kiun vi havas sur vi, kaj tenu ĝin. Ŝi ĝin tenis, kaj li enmezuris en ĝin ses mezurilojn da hordeo kaj metis ĝin sur ŝin, kaj ŝi iris en la urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Kiam ŝi alvenis al sia bopatrino, ĉi tiu demandis: Kiel la afero iras ĉe vi, mia filino? Kaj ŝi rakontis al ŝi ĉion, kion la viro faris al ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'Kaj ŝi diris plue: La ses mezurilojn da hordeo li ankaŭ donis al mi; ĉar li diris al mi: Ne revenu malplena al via bopatrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Kaj ĉi tiu diris: Restu, mia filino, ĝis vi sciiĝos, kiel la afero finiĝis; ĉar tiu homo ne ripozos, ĝis la afero estos finita hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Boaz iris al la pordego de la urbo kaj sidiĝis tie. Kaj jen preterpasas la parenco, pri kiu Boaz parolis. Kaj li diris: Alproksimiĝu kaj sidiĝu ĉi tie, vi, tia-tia. Tiu alproksimiĝis kaj sidiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Kaj Boaz prenis dek virojn el la plejaĝuloj de la urbo, kaj diris: Sidiĝu ĉi tie. Kaj ili sidiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Kaj li diris al la parenco: Tiun parcelon de la kampo, kiu apartenis al nia frato Elimeleĥ, vendas Naomi, kiu revenis el la lando de Moab;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'kaj mi decidis sciigi vin, dirante: Aĉetu en la ĉeesto de la loĝantoj kaj en la ĉeesto de la plejaĝuloj de mia popolo. Se vi volas elaĉeti, aĉetu nun; sed se vi ne volas elaĉeti, diru al mi, por ke mi sciu; ĉar ne ekzistas iu alia por aĉeti, krom vi, kaj mi estas via postproksimulo. Tiu diris: Mi volas elaĉeti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Tiam Boaz diris: Samtempe, kiam vi aĉetos la kampon el la mano de Naomi kaj de Rut, la Moabidino, edzino de la mortinto, vi ankaŭ prenos sur vin la devon restarigi la nomon de la mortinto al lia heredaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Kaj la parenco diris: Mi ne povas elaĉeti al mi, por ke mi ne pereigu mian propran heredaĵon; elaĉetu al vi mian aĉetotaĵon, ĉar vere mi ne povas elaĉeti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Sed de la antikva tempo ekzistis kutimo en Izrael, pri elaĉetado kaj ŝanĝado, por firmigi ĉion: oni detiras sian ŝuon kaj donas ĝin al sia proksimulo; kaj tio estas la atesto en Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'La parenco diris al Boaz: Elaĉetu al vi; kaj li detiris sian ŝuon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Kaj Boaz diris al la plejaĝuloj kaj al la popolamaso: Hodiaŭ vi estas atestantoj, ke mi aĉetis el la mano de Naomi ĉion, kio apartenis al Elimeleĥ kaj al Kiljon kaj Maĥlon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'kaj ankaŭ Ruton, la Moabidinon, la edzinon de Maĥlon, mi akiris al mi kiel edzinon, por restarigi la nomon de la mortinto al lia heredaĵo, por ke la nomo de la mortinto ne estingiĝu inter liaj fratoj kaj ĉe la pordego de lia loko; vi estas atestantoj hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Kaj la tuta ĉeestantaro, kiu troviĝis ĉe la pordego, kiel ankaŭ la plejaĝuloj, respondis: Ni estas atestantoj; la Eternulo faru, ke la virino, kiu envenas en vian domon, estu simila al Raĥel kaj Lea, kiuj ambaŭ starigis la domon de Izrael, kaj vi estu sukcesplena en Efrata kaj akiru bonan nomon en Bet-Leĥem;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'kaj via domo estu sukcesplena, simile al la domo de Perec, kiun naskis Tamar al Jehuda, el la idaro, kiun la Eternulo donos al vi de tiu junulino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Kaj Boaz prenis Ruton, kaj ŝi fariĝis lia edzino; kaj li envenis al ŝi, kaj la Eternulo donis al ŝi gravedecon, kaj ŝi naskis filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Kaj la virinoj diris al Naomi: Benata estu la Eternulo, kiu ne lasis vin sen parenco hodiaŭ, kaj li estu fama en Izrael;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'kaj li estu al vi ĝojiganto, kaj prizorganto de via maljuneco; ĉar via bofilino, kiu amas vin kaj kiu estas al vi pli bona ol sep filoj, naskis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Kaj Naomi prenis la infanon kaj metis ĝin sur sian bruston kaj fariĝis ĝia vartistino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Kaj la najbarinoj donis al li nomon, dirante: Filo naskiĝis al Naomi; kaj ili nomis lin Obed. Li estas la patro de Jiŝaj, patro de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Kaj jen estas la generacioj de Perec: al Perec naskiĝis Ĥecron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'al Ĥecron naskiĝis Ram, al Ram naskiĝis Aminadab,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'al Aminadab naskiĝis Naĥŝon, al Naĥŝon naskiĝis Salma,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'al Salma naskiĝis Boaz, al Boaz naskiĝis Obed,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'al Obed naskiĝis Jiŝaj, kaj al Jiŝaj naskiĝis David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Estis unu viro el Ramataim-Cofim, de la monto de Efraim; lia nomo estis Elkana, filo de Jeroĥam, filo de Elihu, filo de Toĥu, filo de Cuf, Efratano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Li havis du edzinojn; la nomo de unu estis Ĥana, kaj la nomo de la dua estis Penina. Penina havis infanojn, sed Ĥana ne havis infanojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Tiu viro ĉiujare iradis el sia urbo, por adorkliniĝi kaj fari oferon al la Eternulo Cebaot en Ŝilo; kaj tie Ĥofni kaj Pineĥas, du filoj de Eli, estis pastroj de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Unu tagon Elkana faris oferon, kaj li donis al sia edzino Penina kaj al ĉiuj ŝiaj filoj kaj filinoj partojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'kaj al Ĥana li kun malĝojo donis unu parton, ĉar Ĥanan li amis, sed la Eternulo ŝlosis ŝian uteron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Kaj ŝia konkurantino afliktis ŝin kaj tre incitis ŝin kaŭze de tio, ke la Eternulo ŝlosis ŝian uteron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'Tiel estis farate ĉiujare; kiam ŝi iradis al la domo de la Eternulo, la konkurantino tiel incitadis ŝin, ke ŝi ploris kaj ne manĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Kaj ŝia edzo Elkana diris al ŝi: Ĥana, kial vi ploras? kaj kial vi ne manĝas? kaj kial tiel afliktiĝas via koro? ĉu mi ne estas por vi pli bona ol dek filoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Kaj Ĥana leviĝis, manĝinte en Ŝilo kaj trinkinte. Kaj la pastro Eli sidis sur seĝo ĉe la fosto de la templo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'Kaj ŝi estis tre malĝoja, kaj preĝis al la Eternulo, kaj forte ploris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'Kaj ŝi faris sanktan promeson, kaj diris: Ho Eternulo Cebaot! se Vi rigardos la suferon de Via sklavino kaj rememoros min kaj ne forgesos Vian sklavinon kaj donos al Via sklavino idon virseksan, tiam mi fordonos lin al la Eternulo por la tuta tempo de lia vivo, kaj tondilo ne tuŝos lian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Dum ŝi longe preĝis antaŭ la Eternulo, Eli atente rigardis ŝian buŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Ĥana parolis en sia koro; nur ŝiaj lipoj moviĝadis, sed ŝian voĉon oni ne aŭdis; tial Eli pensis, ke ŝi estas ebria.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Kaj Eli diris al ŝi: Kiel longe vi restos ebria? forigu vian vinon el vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Sed Ĥana respondis kaj diris: Ne, mia sinjoro, mi estas virino kun malĝoja koro; vinon aŭ ebriigaĵon mi ne trinkis, mi nur elverŝas mian animon antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Ne opiniu pri via sklavino, ke ŝi estas virino malmorala; pro mia granda malĝojo kaj sufero mi parolis ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Tiam Eli respondis kaj diris: Iru en paco, kaj la Dio de Izrael plenumos vian peton, kiun vi petis de Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Kaj ŝi diris: Via sklavino akiru vian favoron. Kaj la virino iris sian vojon, kaj ŝi manĝis, kaj ŝia vizaĝo ne estis plu malgaja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Kaj ili leviĝis frue matene kaj adorkliniĝis antaŭ la Eternulo, kaj reiris kaj venis al sia domo en Rama. Kaj Elkana ekkonis sian edzinon Ĥana, kaj la Eternulo rememoris ŝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Post kelka tempo Ĥana gravediĝis kaj naskis filon, kaj ŝi donis al li la nomon Samuel, ĉar: De la Eternulo mi lin elpetis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'La viro Elkana kun sia tuta domanaro iris, por oferi al la Eternulo la ĉiujaran oferon kaj sian promesitaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Sed Ĥana ne iris, sed ŝi diris al sia edzo: Kiam la knabo estos demamigita, tiam mi venigos lin, ke li aperu antaŭ la Eternulo kaj restu tie por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Kaj ŝia edzo Elkana diris al ŝi: Faru tion, kio plaĉas al vi; restu, ĝis vi demamigos lin; nur la Eternulo plenumu Sian promeson. Kaj la virino restis, kaj suĉigis sian infanon, ĝis ŝi demamigis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Kaj post kiam ŝi demamigis lin, ŝi venigis lin kun si kune kun tri bovoj kaj unu efo da faruno kaj felsako da vino, kaj ŝi venigis lin en la domon de la Eternulo en Ŝilo; kaj la knabo estis ankoraŭ juna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Kaj oni buĉis bovon kaj venigis la knabon al Eli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Kaj ŝi diris: Ho mia sinjoro! tiel certe, kiel vivas via animo, mia sinjoro, mi estas tiu virino, kiu staris ĉi tie apud vi kaj preĝis al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Pri ĉi tiu knabo mi preĝis, kaj la Eternulo plenumis al mi mian peton, pri kiu mi petis Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Tial mi fordonas lin al la Eternulo; por la tuta tempo de sia vivo li estu fordonita al la Eternulo. Kaj ili tie adorkliniĝis antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Kaj Ĥana preĝis kaj diris: Ĝojas mia koro pri la Eternulo, Mia korno altiĝis pro la Eternulo; Larĝe malfermiĝis mia buŝo kontraŭ miaj malamikoj, Ĉar mi ĝojas pro Via helpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Neniu estas tiel sankta, kiel la Eternulo; Ĉar ekzistas neniu krom Vi, Kaj nenia defendanto simila al nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Ne parolu plu fieraĵon; Malhumilaĵo ne eliru plu el via buŝo; Ĉar la Eternulo estas Dio ĉioscianta, Kaj Li starigis la aferojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'La pafarko de la fortuloj estas senvalorigata, Kaj la malfortuloj zoniĝas per forto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Satuloj sin dungigas pro pano, Kaj malsatuloj jam ne malsatas; Senfruktulino naskis sep, Kaj multinfanulino senfortiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'La Eternulo mortigas kaj vivigas, Malsuprigas en Ŝeolon kaj suprigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'La Eternulo malriĉigas kaj riĉigas, Malaltigas kaj altigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Li levas malriĉulon el polvo, El koto Li altigas senhavulon, Por sidigi lin kun altranguloj, Kaj tronon de gloro Li heredigas al li; Ĉar al la Eternulo apartenas la fundamentoj de la tero, Kaj sur ili Li starigis la mondon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'La piedojn de Siaj piuloj Li gardas, Kaj la malvirtuloj pereas en mallumo; Ĉar ne per sia forto potenciĝas la homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'La Eternulo pereigas tiujn, kiuj ribelas kontraŭ Li; El la ĉielo Li tondras kontraŭ ili. La Eternulo juĝos la finojn de la tero, Kaj donos forton al Sia reĝo, Kaj altigos la kornon de Sia sanktoleito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Kaj Elkana iris en Raman, al sia domo; kaj la knabo fariĝis servisto de la Eternulo apud la pastro Eli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'La filoj de Eli estis malmoralaj; ili ne konis la Eternulon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'nek la devojn de pastroj koncerne la popolon. Se iu buĉis oferon, tiam venadis knabo de la pastro dum la kuirado de la viando, havante en sia mano tridentan forkon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'kaj li enpuŝadis ĝin en la lavujon aŭ en la kaldronon aŭ en la poton aŭ en la kaserolon, kaj ĉion, kion trafis la forko, prenadis la pastro. Tiel ili agadis kun ĉiuj Izraelidoj, kiuj venadis tien en Ŝilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Eĉ antaŭ la oferbruligo de la sebo venadis knabo de la pastro, kaj diradis al la alportanto de la ofero: Donu viandon, por rosti por la pastro; li ne prenos de vi viandon kuiritan, sed nur krudan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Se la homo diris al li: Antaŭe oni oferbruligu la sebon, kaj poste prenu al vi, kion via animo deziras; tiam li diradis: Donu tuj, alie mi prenos per forto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'La peko de la knaboj estis tre granda antaŭ la Eternulo, ĉar la homoj malestimis la oferdonon, faratan al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Samuel estis servisto antaŭ la Eternulo; la knabo estis zonita per lina efodo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Kaj malgrandan tunikon faradis al li lia patrino, kaj alportadis al li ĉiujare, kiam ŝi venadis kun sia edzo, por alporti la ĉiujaran oferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Kaj Eli benadis Elkanan kaj lian edzinon, kaj diradis: La Eternulo donu al vi idojn de ĉi tiu virino rekompence pro la konsekrito, kiun vi konsekris al la Eternulo. Kaj ili iradis al sia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'La Eternulo atentis Ĥanan, kaj ŝi gravediĝis kaj naskis tri filojn kaj du filinojn; kaj la knabo Samuel kreskis antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Eli estis tre maljuna; li aŭdis ĉion, kiel agas liaj filoj kun ĉiuj Izraelidoj, kaj ke ili kuŝas kun la virinoj, kiuj kolektiĝas antaŭ la pordo de la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'Kaj li diris al ili: Kial vi faras tiajn agojn? ĉar mi aŭdas pri viaj malbonaj agoj de ĉi tiu tuta popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Ne, miaj infanoj, ne bona estas la famo, kiun mi aŭdas; vi devojigas la popolon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Se pekas homo kontraŭ homo, povas defendi lin Dio; sed se homo pekas kontraŭ la Eternulo, tiam kiu defendos lin? Sed ili ne aŭskultis la voĉon de sia patro, ĉar la Eternulo decidis mortigi ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Dume la knabo Samuel ĉiam pli kreskis, kaj li plaĉis kiel al la Eternulo, tiel ankaŭ al la homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Kaj venis homo de Dio al Eli, kaj diris al li: Tiel diras la Eternulo: Mi montris Min ja al la domo de via patro, kiam ili estis en Egiptujo, en la domo de Faraono;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'kaj Mi elektis lin el ĉiuj triboj de Izrael kiel pastron por Mi, ke li oferu sur Mia altaro, ke li fumigu incenson, ke li portu efodon antaŭ Mi; kaj Mi donis al la domo de via patro ĉiujn fajroferojn de la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Kial do vi piedpremas Mian buĉoferon kaj farunoferon, kiujn Mi starigis por la loĝejo? vi honoras viajn filojn pli ol Min, por grasigi vin per la unuaj partoj de ĉiuj oferdonoj de Mia popolo Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Tial la Eternulo, Dio de Izrael, diras: Mi diris, ke via domo kaj la domo de via patro irados antaŭ Mi eterne; sed nun, diras la Eternulo, Mi tion ne permesos; ĉar Miajn honorantojn Mi honoros, kaj Miaj malestimantoj estos malaltigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Jen venos baldaŭ la tempo, kiam Mi rompos vian brakon kaj la brakon de via patrodomo, ke ne estos maljunulo en via domo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'kaj vi vidos konkuranton en la loĝejo, dum ĉiuj bonoj, kiuj estos farataj al Izrael; kaj neniam estos maljunulo en via domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Sed Mi neniun ekstermos ĉe vi de antaŭ Mia altaro, por ke viaj okuloj konsumiĝu kaj via animo turmentiĝu; ĉiu, kiu naskiĝas en via domo, mortos en la vira aĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'Kaj jen estas por vi la pruvosigno, kiu plenumiĝos sur viaj du filoj, sur Ĥofni kaj Pineĥas: en unu tago ili ambaŭ mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Kaj Mi starigos por Mi pastron fidelan, kiu agados laŭ Mia koro kaj laŭ Mia animo; kaj Mi konstruos al li domon fidindan, kaj li irados ĉiam antaŭ Mia sanktoleito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'Kaj ĉiu, kiu restos el via domo, venos kaj kliniĝos antaŭ li ĝis la tero pro malgranda monero kaj pro bulo da pano, kaj diros: Mi petas, lasu min aliĝi al ia el la pastraĵoj, por ke mi povu manĝi pecon da pano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'La knabo Samuel servadis al la Eternulo antaŭ Eli; kaj la vorto de la Eternulo estis grandpreza en tiu tempo; ne aperadis ofte profetaj vizioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'En tiu tempo unu fojon Eli kuŝis sur sia loko (lia vidado komencis malakriĝi, ke li ne povis vidi);');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'kaj la lucerno de Dio ankoraŭ ne estingiĝis, kaj Samuel kuŝis en la templo de la Eternulo, kie estis la kesto de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'tiam la Eternulo vokis Samuelon, kaj ĉi tiu diris: Jen mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'Kaj li kuris al Eli, kaj diris: Jen mi estas, kiel vi vokis min. Sed tiu diris: Mi ne vokis; iru returne kaj kuŝiĝu. Kaj li iris kaj kuŝiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Kaj la Eternulo denove vokis Samuelon, kaj Samuel leviĝis kaj iris al Eli, kaj diris: Jen mi estas, kiel vi vokis min. Sed tiu diris: Mi ne vokis, mia filo; iru returne kaj kuŝiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Samuel ankoraŭ ne konis la Eternulon, kaj ankoraŭ ne estis revelaciita al li la vorto de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Kaj la Eternulo denove vokis Samuelon la trian fojon; kaj li leviĝis kaj iris al Eli, kaj diris: Jen mi estas, kiel vi vokis min. Tiam Eli komprenis, ke la Eternulo vokas la knabon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'Kaj Eli diris al Samuel: Iru, kuŝiĝu; kaj se vi estos vokata, tiam diru: Parolu, ho Eternulo, ĉar Via sklavo aŭskultas. Kaj Samuel iris kaj kuŝiĝis sur sia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Kaj venis la Eternulo kaj stariĝis, kaj vokis kiel la antaŭajn fojojn: Samuel, Samuel! Kaj Samuel diris: Parolu, ĉar Via sklavo aŭskultas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Tiam la Eternulo diris al Samuel: Jen Mi faros en Izrael tian faron, ke al ĉiu, kiu tion aŭdos, eksonoros ambaŭ liaj oreloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'En tiu tago Mi plenumos super Eli ĉion, kion Mi diris pri lia domo; Mi komencos kaj finos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Mi sciigis al li, ke Mi juĝos lian domon por ĉiam pro la krimo, ke li sciis, ke liaj filoj venigas malbenon sur sin, kaj li ne detenis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Kaj tial Mi ĵuris al la domo de Eli, ke neniam pekliberiĝos la krimo de la domo de Eli per buĉofero nek per farunofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Kaj Samuel kuŝis ĝis la mateno; poste li malfermis la pordojn de la domo de la Eternulo. Sed Samuel timis raporti pri la vizio al Eli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Kaj Eli vokis Samuelon, kaj diris: Samuel, mia filo! Kaj ĉi tiu diris: Jen mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Kaj tiu diris: Kia estas la afero, pri kiu Li parolis al vi? mi petas, ne kaŝu antaŭ mi; tion kaj ankoraŭ pli faru al vi Dio, se vi kaŝos antaŭ mi ion el ĉio, kion Li diris al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Kaj Samuel rakontis al li ĉion, kaj nenion kaŝis antaŭ li. Kaj li diris: Li estas la Eternulo; Li faru tion, kio plaĉas al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Kaj Samuel kreskis, kaj la Eternulo estis kun li; kaj neniun el Liaj vortoj li faligis sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Kaj eksciis la tuta Izrael, de Dan ĝis Beer-Ŝeba, ke Samuel fariĝis fidinda profeto de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Kaj la Eternulo plue aperadis en Ŝilo, post kiam la Eternulo revelaciis Sin al Samuel en Ŝilo per la parolo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'Kaj Samuel parolis al la tuta Izrael. Kaj Izrael eliris milite kontraŭ la Filiŝtojn, kaj stariĝis tendare apud Eben-Ezer, kaj la Filiŝtoj stariĝis tendare apud Afek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Kaj la Filiŝtoj starigis siajn vicojn kontraŭ Izrael, kaj la batalo vastiĝis, kaj Izrael estis venkobatita de la Filiŝtoj, kaj ili mortigis sur la kampo de la batalo pli-malpli kvar mil homojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Kaj la popolo venis en la tendaron, kaj la plejaĝuloj de Izrael diris: Pro kio la Eternulo frapis nin hodiaŭ antaŭ la Filiŝtoj? ni prenu al ni el Ŝilo la keston de interligo de la Eternulo, por ke ĝi venu inter nin kaj savu nin kontraŭ la manoj de niaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Kaj la popolo sendis en Ŝilon, kaj oni alportis de tie la keston de interligo de la Eternulo Cebaot, sidanta sur la keruboj; tie estis kun la kesto de interligo de Dio la du filoj de Eli, Ĥofni kaj Pineĥas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Kaj kiam la kesto de interligo de la Eternulo venis en la tendaron, tiam la tuta Izrael faris tian grandan kriadon, ke la tero ekbruis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Kiam la Filiŝtoj aŭdis la laŭtan kriadon, ili diris: Kion signifas ĉi tiu granda kaj forta kriado en la tendaro de la Hebreoj? Kaj ili eksciis, ke la kesto de la Eternulo venis en la tendaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Kaj la Filiŝtoj ektimis, ĉar ili diris: Venis Dio en la tendaron. Kaj ili diris: Ve al ni! ĉar ne estis tiel antaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Ve al ni! kiu savos nin kontraŭ la manoj de tiuj fortaj dioj? tio estas tiuj dioj, kiuj frapis la Egiptojn per ĉiaj frapoj en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Estu kuraĝaj kaj viraj, ho Filiŝtoj, por ke vi ne fariĝu sklavoj al la Hebreoj, kiel ili estis sklavoj al vi; estu viroj kaj batalu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Kaj la Filiŝtoj batalis, kaj la Izraelidoj estis venkobatitaj, kaj ili forkuris ĉiu al sia tendo; kaj la venkobato estis tre granda, kaj falis el la Izraelidoj tridek mil piedirantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Kaj la kesto de Dio estis prenita, kaj la du filoj de Eli, Ĥofni kaj Pineĥas, mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Unu Benjamenido kuris el la militistaro kaj venis en Ŝilon en la sama tago, kaj liaj vestoj estis disŝiritaj, kaj tero estis sur lia kapo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Kiam li venis, Eli sidis sur seĝo, rigardante sur la vojon, ĉar lia koro tremis pri la kesto de Dio. Kaj tiu homo venis, por sciigi en la urbo, kaj ekkriis la tuta urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Kiam Eli aŭdis la kriadon, li diris: Kion signifas ĉi tiu tumulta kriado? Kaj la viro rapide venis kaj sciigis al Eli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Eli tiam havis la aĝon de naŭdek ok jaroj, kaj liaj okuloj malakriĝis, kaj li ne povis vidi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Kaj tiu viro diris al Eli: Mi venis el la militistaro, mi alkuris hodiaŭ el la militistaro. Kaj Eli diris: Kia estis la afero, mia filo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Kaj la sciiganto respondis kaj diris: Izrael forkuris antaŭ la Filiŝtoj, kaj granda frapo trafis la popolon, kaj ankaŭ viaj du filoj, Ĥofni kaj Pineĥas, mortis, kaj la kesto de Dio estas forprenita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Apenaŭ li menciis la keston de Dio, Eli falis de la seĝo malantaŭen ĉe la pordego, rompis al si la kolon, kaj mortis; ĉar li estis maljuna kaj peza. Li estis juĝisto de Izrael dum kvardek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Lia bofilino, la edzino de Pineĥas, estis graveda, baldaŭ naskonta. Kiam ŝi aŭdis la sciigon pri la forpreno de la kesto de Dio kaj pri la morto de sia bopatro kaj de sia edzo, ŝi kliniĝis kaj naskis, ĉar subite atakis ŝin la naskaj doloroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Kaj dum ŝi estis mortanta, la virinoj, kiuj ŝin ĉirkaŭis, diris: Ne timu, ĉar vi naskis filon; sed ŝi ne respondis, kaj ne prenis tion al sia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'Kaj ŝi donis al la knabo la nomon Ikabod, dirante: For estas la gloro de Izrael; ĉar forprenita estis la kesto de Dio kaj pereis ŝia bopatro kaj ŝia edzo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Kaj ŝi diris: For estas la gloro de Izrael, ĉar forprenita estas la kesto de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'La Filiŝtoj prenis la keston de Dio kaj portis ĝin el Eben-Ezer en Aŝdodon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Kaj la Filiŝtoj prenis la keston de Dio kaj enportis ĝin en la templon de Dagon kaj starigis ĝin apude de Dagon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Sed kiam la Aŝdodanoj en la morgaŭa tago leviĝis, ili vidis, ke jen Dagon kuŝas vizaĝaltere antaŭ la kesto de la Eternulo. Kaj ili prenis Dagonon kaj restarigis lin sur lia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Kiam ili en la morgaŭa tago matene leviĝis, ili vidis, ke jen Dagon kuŝas vizaĝaltere antaŭ la kesto de la Eternulo; la kapo de Dagon kaj liaj ambaŭ manoj dehakitaj kuŝas sur la sojlo, nur la torso restis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Pro tio la pastroj de Dagon, kaj ĉiuj, kiuj eniras en la templon de Dagon en Aŝdod, ne paŝas sur la sojlon de Dagon ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Kaj la mano de la Eternulo peze falis sur la Aŝdodanojn, kaj Li komencis ekstermi ilin kaj frapis ilin per tuberoj, en Aŝdod kaj en ĝiaj ĉirkaŭaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Kiam la Aŝdodanoj vidis, ke estas tiel, tiam ili diris: Ne restu ĉe ni la kesto de la Dio de Izrael, ĉar peza estas Lia mano sur ni kaj sur nia dio Dagon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Ili sendis kaj kunvenigis al si ĉiujn estrojn de la Filiŝtoj, kaj diris: Kion ni faru kun la kesto de la Dio de Izrael? Kaj tiuj diris: Oni transportu la keston de la Dio de Izrael en Gaton. Kaj oni transportis la keston de la Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Sed kiam oni transportis ĝin, la mano de la Eternulo faris en la urbo tre grandan tumulton, kaj Li frapis la loĝantojn de la urbo, kiel la malgrandajn, tiel ankaŭ la grandajn, kaj aperis sur ili tuberoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Tiam ili forsendis la keston de Dio en Ekronon. Sed kiam la kesto de Dio venis en Ekronon, la Ekronanoj ekkriis, dirante: Oni alportis al ni la keston de la Dio de Izrael, por mortigi nin kaj nian popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Ili sendis kaj kunvenigis ĉiujn estrojn de la Filiŝtoj, kaj diris: Forsendu la keston de la Dio de Izrael, ke ĝi revenu sur sian lokon kaj ne mortigu nin kaj nian popolon; ĉar en la tuta urbo estis morta teruro, tiel forte pezis la mano de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Kaj la homoj, kiuj ne mortis, estis frapitaj per tuberoj, kaj la kriado de la urbo leviĝis ĝis la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'La kesto de la Eternulo estis en la lando de la Filiŝtoj dum sep monatoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Kaj la Filiŝtoj vokis la pastrojn kaj la aŭguristojn, kaj diris: Kion ni faru kun la kesto de la Eternulo? sciigu al ni, kiamaniere ni resendu ĝin sur ĝian lokon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Kaj tiuj diris: Se vi volas resendi la keston de la Dio de Izrael, ne resendu ĝin sen donacoj, sed repagu al Li prokulpan oferon; tiam vi resaniĝos, kaj ekscios, kial ne foriĝas de vi Lia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Kaj ili diris: Kian prokulpan oferon ni repagu al Li? Kaj tiuj diris: Laŭ la nombro de la estroj de la Filiŝtoj kvin orajn tuberojn kaj kvin orajn musojn; ĉar la sama frapo trafis vin ĉiujn kaj viajn estrojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Faru bildojn de viaj tuberoj kaj bildojn de viaj musoj, kiuj ruinigis la landon, kaj faru honoron al la Dio de Izrael; tiam Li eble malplipezigos Sian manon sur vi kaj sur viaj dioj kaj sur via lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Kial vi obstinigus vian koron, kiel obstinigis sian koron Faraono kaj la Egiptoj? kiam Li montris sur ili Sian forton, ili ja forliberigis ilin, ke ili iru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Nun faru novan ĉaron, kaj prenu du suĉigantajn bovinojn, kiuj ankoraŭ ne havis sur si jugon, kaj jungu la bovinojn al la ĉaro, kaj iliajn idojn forkonduku de ili hejmen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Kaj prenu la keston de la Eternulo, kaj metu ĝin sur la ĉaron; kaj la orajn objektojn, kiujn vi donos al Li kiel prokulpan oferon, metu en kesteton apud ĝin, kaj forsendu ĝin, ke ĝi iru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'Kaj rigardu: se ĝi iros laŭ la vojo al sia regiono, al Bet-Ŝemeŝ, tiam Li faris al ni tiun grandan malbonon; se ne, tiam ni scios, ke ne Lia mano frapis nin, sed ke tio trafis nin blindokaze.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Kaj la homoj faris tiel, kaj ili prenis du suĉigantajn bovinojn kaj aljungis ilin al ĉaro, kaj iliajn idojn ili enŝlosis hejme;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'kaj ili metis la keston de la Eternulo sur la ĉaron, kaj ankaŭ la kesteton kun la oraj musoj kaj kun la bildoj de siaj tuberoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Kaj la bovinoj direktis sian iradon al la vojo, kiu kondukas al Bet- Ŝemeŝ; ili iris nur sur unu vojeto, iris kaj blekis, sed ne forflankiĝis dekstren nek maldekstren; kaj la estroj de la Filiŝtoj iris post ili ĝis la limo de Bet-Ŝemeŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Kaj la loĝantoj de Bet-Ŝemeŝ estis rikoltantaj tritikon en la valo; kiam ili levis la okulojn kaj ekvidis la keston, ili ekĝojis pro tio, kion ili vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'La ĉaro venis sur la kampon de Josuo, Bet-Ŝemeŝano, kaj haltis tie; tie estis granda ŝtono. Kaj oni dishakis la lignon de la ĉaro, kaj la bovinojn oni oferis brulofere al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'La Levidoj malsuprenprenis la keston de la Eternulo, kaj la kesteton, kiu estis apud ĝi kaj enhavis la orajn objektojn, kaj ili metis tion sur la grandan ŝtonon; kaj la loĝantoj de Bet-Ŝemeŝ faris bruloferojn kaj buĉis buĉoferojn al la Eternulo en tiu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Kaj la kvin estroj de la Filiŝtoj vidis, kaj reiris en Ekronon en la sama tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Kaj jen estas la oraj tuberoj, kiujn la Filiŝtoj donis kiel prokulpan oferon al la Eternulo: unu pro Aŝdod, unu pro Gaza, unu pro Aŝkelon, unu pro Gat, unu pro Ekron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'La oraj musoj, laŭ la nombro de ĉiuj urboj Filiŝtaj en la kvin provincoj, kiel de la urboj fortikigitaj, tiel ankaŭ de la neŝirmitaj vilaĝoj, kaj ankaŭ la granda ŝtono, sur kiun oni metis la keston de la Eternulo, estas kaŝitaj ĝis nun sur la kampo de Josuo, la Bet-Ŝemeŝano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Kaj Li frapis la loĝantojn de Bet-Ŝemeŝ pro tio, ke ili enrigardis en la keston de la Eternulo; Li mortigis el la popolo kvindek mil sepdek homojn; kaj ekfunebris la popolo pro tio, ke la Eternulo frapis la popolon per granda frapo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Kaj la loĝantoj de Bet-Ŝemeŝ diris: Kiu povas stari antaŭ la Eternulo, tiu sankta Dio? kaj al kiu Li iros de ni?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Kaj ili sendis senditojn al la loĝantoj de Kirjat-Jearim, por diri: La Filiŝtoj redonis la keston de la Eternulo; venu, prenu ĝin al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Kaj venis la loĝantoj de Kirjat-Jearim, kaj prenis la keston de la Eternulo kaj alportis ĝin en la domon de Abinadab sur la monteton, kaj lian filon Eleazar ili konsekris, por gardi la keston de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'De la tago, de kiam la kesto restis en Kirjat-Jearim, pasis multe da tempo, pasis dudek jaroj. Kaj la tuta domo de Izrael sopiris pri la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Kaj Samuel diris al la tuta domo de Izrael jene: Se per via tuta koro vi konvertiĝis al la Eternulo, tiam forigu el inter vi la fremdajn diojn kaj la Aŝtarojn, kaj turnu vian koron al la Eternulo kaj servu al Li sola, kaj Li savos vin el la manoj de la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Kaj la Izraelidoj forigis la Baalojn kaj la Aŝtarojn, kaj komencis servadi al la Eternulo sola.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Kaj Samuel diris: Kunvenigu la tutan Izraelon en Micpan, kaj mi preĝos por vi al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Kaj ili kunvenis en Micpan, kaj ĉerpis akvon kaj verŝis antaŭ la Eternulo, kaj fastis en tiu tago, kaj diris tie: Ni pekis antaŭ la Eternulo. Kaj Samuel juĝis la Izraelidojn en Micpa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Kiam la Filiŝtoj aŭdis, ke la Izraelidoj kolektiĝis en Micpa, la estroj de la Filiŝtoj elmoviĝis kontraŭ Izraelon. Aŭdinte tion, la Izraelidoj ektimis antaŭ la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'Kaj la Izraelidoj diris al Samuel: Ne ĉesu krii por ni al la Eternulo, nia Dio, ke Li savu nin kontraŭ la manoj de la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Tiam Samuel prenis unu suĉantan ŝafidon kaj oferis ĝin tutan brulofere al la Eternulo, kaj Samuel vokis al la Eternulo por Izrael, kaj la Eternulo aŭskultis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Kaj dum Samuel estis oferanta la bruloferon, la Filiŝtoj venis, por batali kontraŭ la Izraelidoj. Sed la Eternulo ektondris en tiu tago per granda tondro super la Filiŝtoj kaj teruris ilin, kaj ili estis frapitaj antaŭ Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Kaj la viroj de Izrael eliris el Micpa kaj persekutis la Filiŝtojn, kaj batis ilin ĝis sub Bet-Kar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Kaj Samuel prenis unu ŝtonon, kaj metis ĝin inter Micpa kaj Ŝen, kaj donis al ĝi la nomon Eben-Ezer, dirante: Ĝis ĉi tiu loko helpis nin la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Tiamaniere la Filiŝtoj estis kvietigitaj, kaj ne venadis plu en la regionon de Izrael. Kaj la mano de la Eternulo estis super la Filiŝtoj dum la tuta vivo de Samuel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Kaj estis redonitaj al Izrael la urboj, kiujn la Filiŝtoj prenis de Izrael, de Ekron ĝis Gat, kaj iliajn regionojn Izrael savis el la manoj de la Filiŝtoj. Kaj estis paco inter Izrael kaj la Amoridoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Kaj Samuel estis juĝisto de Izrael dum sia tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Kaj li iradis ĉiujare ĉirkaŭe en Bet-Elon, Gilgalon, kaj Micpan, kaj juĝadis Izraelon en ĉiuj tiuj lokoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Kaj li revenadis en Raman, ĉar tie estis lia domo; kaj tie ankaŭ li juĝadis Izraelon, kaj li konstruis tie altaron al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Kiam Samuel maljuniĝis, li faris siajn filojn juĝistoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'La nomo de lia unuenaskita filo estis Joel, kaj la nomo de lia dua filo estis Abija; ili juĝadis en Beer-Ŝeba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Sed liaj filoj ne iris laŭ lia vojo; ili serĉis profiton, ili prenadis subaĉeton kaj juĝadis maljuste.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Kaj kolektiĝis ĉiuj plejaĝuloj de Izrael kaj venis al Samuel en Raman,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'kaj diris al li: Jen vi maljuniĝis, kaj viaj filoj ne iras laŭ via vojo; starigu do al ni reĝon, por ke li juĝadu nin, kiel ĉe ĉiuj popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Ne plaĉis la afero al Samuel, kiam ili diris: Starigu al ni reĝon, por ke li juĝadu nin. Kaj Samuel ekpreĝis al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Kaj la Eternulo diris al Samuel: Obeu la voĉon de la popolo en ĉio, kion ili diros al vi; ĉar ne vin ili forpuŝis, sed Min ili forpuŝis de regado super ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Simile al ĉiuj agoj, kiujn ili faris de la tempo, kiam Mi elkondukis ilin el Egiptujo, ĝis nun, kaj kiel ili forlasis Min kaj servis al aliaj dioj, tiel ili agas ankaŭ kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Nun obeu ilian voĉon, tamen klarigu al ili kaj sciigu al ili la rajtojn de la reĝo, kiu reĝos super ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Kaj Samuel raportis ĉiujn vortojn de la Eternulo al la popolo, kiu petis de li reĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Kaj li diris: Tiaj estos la rajtoj de la reĝo, kiu reĝos super vi: viajn filojn li prenos por siaj ĉaroj kaj por siaj ĉevaloj, kaj ili kurados antaŭ lia ĉaro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'kaj li faros ilin milestroj kaj kvindekestroj, kaj devigos ilin plugi lian kampon kaj rikolti lian rikolton kaj fari liajn batalilojn kaj la apartenaĵojn de lia ĉaro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'kaj viajn filinojn li prenos kiel ŝmiraĵistinojn, kuiristinojn, kaj bakistinojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Kaj viajn plej bonajn kampojn kaj vinberĝardenojn kaj olivĝardenojn li prenos, kaj donos al siaj servantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Kaj el viaj semitaĵoj kaj vinberĝardenoj li prenos dekonaĵon, kaj donos al siaj korteganoj kaj al siaj servantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Kaj viajn servantojn kaj servantinojn kaj viajn plej bonajn junulojn kaj viajn azenojn li prenos, kaj uzos por siaj laboroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'El viaj ŝafoj li prenos dekonon, kaj vi fariĝos por li sklavoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'Tiam vi ekkrios pro via reĝo, kiun vi elektis al vi, sed la Eternulo tiam ne aŭskultos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Sed la popolo ne volis obei la voĉon de Samuel kaj diris: Ne, reĝo estu super ni;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'kaj ni ankaŭ estu kiel ĉiuj popoloj, kaj nia reĝo juĝadu nin kaj iradu antaŭ ni kaj kondukadu niajn militojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Kaj Samuel aŭskultis ĉiujn vortojn de la popolo, kaj raportis ilin al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Kaj la Eternulo diris al Samuel: Obeu ilian voĉon, kaj starigu super ili reĝon. Kaj Samuel diris al la viroj de Izrael: Iru ĉiu en sian urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Estis viro el la Benjamenidoj, kiu havis la nomon Kiŝ, filo de Abiel, filo de Ceror, filo de Beĥorat, filo de Afiaĥ, Benjamenido, viro forta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Li havis filon, kies nomo estis Saul; ĉi tiu estis juna kaj bela, kaj neniu el la Izraelidoj estis pli bela ol li; de siaj ŝultroj supren li estis pli alta ol la tuta popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Perdiĝis azeninoj de Kiŝ, patro de Saul; kaj Kiŝ diris al sia filo Saul: Prenu kun vi unu el la junuloj, kaj leviĝu, kaj iru serĉi la azeninojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Kaj li iris sur la monton de Efraim kaj trairis la landon Ŝaliŝa, sed ili ne trovis; kaj ili trairis la landon Ŝaalim, sed tie ne troviĝis; kaj li trairis la landon de Benjamen, sed ili ne trovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Kiam li venis en la landon Cuf, Saul diris al la junulo, kiu estis kun li: Venu, ni reiru hejmen, ĉar alie mia patro eble ĉesos pensi pri la azeninoj kaj estos maltrankvila pri ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Kaj tiu diris al li: Jen en ĉi tiu urbo estas Dia homo, homo respektata; ĉio, kion li diras, nepre plenumiĝas; ni iru do tien, eble li montros al ni la vojon, kiun ni devas iri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Kaj Saul diris al sia junulo: Bone, ni iros, sed kion ni alportos al la homo? ĉar la pano elĉerpiĝis en nia sako, kaj ni havas nenian donacon, por alporti al la Dia homo; kion ni havas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'La junulo plue respondis al Saul kaj diris: Jen en mia mano troviĝas kvarono de arĝenta siklo; mi donos ĝin al la Dia homo, kaj li montros al ni la vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, '(En la antaŭa tempo ĉe Izrael oni tiel diradis, kiam oni iris demandi Dion: Ni iru al la antaŭvidisto; ĉar kion oni nun nomas profeto, tion oni antaŭe nomis antaŭvidisto.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Kaj Saul diris al sia junulo: Bone vi diris; ni iru. Kaj ili iris en la urbon, en kiu loĝis la Dia homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'Irante supren en la urbon, ili renkontis knabinojn, kiuj eliris, por ĉerpi akvon; kaj ili diris al tiuj: Ĉu la antaŭvidisto estas ĉi tie?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'Kaj tiuj respondis al ili kaj diris: Ĉi tie; jen li estas antaŭ vi; nun rapidu, ĉar hodiaŭ li venis en la urbon, ĉar hodiaŭ la popolo alportas buĉoferon sur la altaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Kiam vi eniros en la urbon, vi tuj trovos lin, antaŭ ol li iros sur la altaĵon, por manĝi; ĉar la popolo ne manĝas antaŭ lia veno, ĉar li benas la buĉoferon, kaj nur poste manĝas la invititoj. Iru do, ĉar nun vi lin trovos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Kaj ili iris supren en la urbon. Apenaŭ ili venis en la mezon de la urbo, jen Samuel eliras renkonte al ili, por iri sur la altaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Dume la Eternulo revelaciis al la oreloj de Samuel, unu tagon antaŭ la veno de Saul, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, 'Morgaŭ en ĉi tiu tempo Mi sendos al vi homon el la lando de Benjamen, kaj vi sanktoleos lin kiel ĉefon super Mia popolo Izrael, kaj li savos Mian popolon el la manoj de la Filiŝtoj; ĉar Mi vidis Mian popolon, kaj ĝiaj krioj atingis Min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Kiam Samuel ekvidis Saulon, la Eternulo diris al li: Jen estas la homo, pri kiu Mi diris al vi, ke li regos super Mia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Saul alproksimiĝis al Samuel en la pordego, kaj diris: Diru al mi, mi petas, kie estas ĉi tie la domo de la antaŭvidisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Kaj Samuel respondis al Saul kaj diris: Mi estas la antaŭvidisto; iru antaŭ mi sur la altaĵon; vi manĝos kun mi hodiaŭ, kaj morgaŭ mi lasos vin for, kaj mi diros al vi ĉion, kio estas en via koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'Kaj pri la azeninoj, kiuj perdiĝis ĉe vi antaŭ tri tagoj, ne zorgu, ĉar ili estas trovitaj. Kaj al kiu apartenos ĉio plej bona en Izrael? ĉu ne al vi kaj al la tuta domo de via patro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Saul respondis kaj diris: Mi estas ja Benjamenido, el la plej malgrandaj triboj de Izrael, kaj mia familio estas la plej malgranda el ĉiuj familioj de la tribo de Benjamen; kial do vi diris al mi tiajn vortojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Tiam Samuel prenis Saulon kaj lian junulon, kaj enkondukis ilin en la manĝoĉambron, kaj donis al ili lokon supraloke de la invititoj, kiuj estis en la nombro de ĉirkaŭ tridek homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Kaj Samuel diris al la kuiristo: Donu tiun porcion, kiun mi donis al vi kaj pri kiu mi diris al vi, ke vi retenu ĝin ĉe vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Kaj la kuiristo prezentis femuron, kaj tion, kio estas kun ĝi, kaj metis tion antaŭ Saulon, kaj Samuel diris: Jen estas, kio restis; metu ĝin antaŭ vin kaj manĝu, ĉar ĝi estas rezervita por vi por la tempo, por kiu mi invitis la popolon. Kaj Saul manĝis kun Samuel en tiu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Kaj ili malsupreniris de la altaĵo en la urbon, kaj Samuel parolis kun Saul sur la tegmento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Kaj ili leviĝis frue; kaj kiam la matenruĝo leviĝis, Samuel vokis Saulon sur la tegmenton, kaj diris: Leviĝu, mi lasos vin for. Kaj Saul leviĝis, kaj ili eliris ambaŭ, li kaj Samuel, eksteren.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Kiam ili atingis la finon de la urbo, Samuel diris al Saul: Diru al la junulo, ke li iru antaŭen (kaj tiu iris antaŭen); kaj vi haltu nun, kaj mi anoncos al vi la diron de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Tiam Samuel prenis kruĉeton kun oleo kaj verŝis sur lian kapon, kaj kisis lin, kaj diris: Vidu, la Eternulo sanktoleis vin kiel ĉefon super Sia heredaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Kiam vi hodiaŭ foriros de mi, vi trovos ĉe la tombo de Raĥel, en la regiono de Benjamen, en Celcaĥ, du homojn, kiuj diros al vi: Estas trovitaj la azeninoj, kiujn vi iris serĉi, kaj jen via patro ĉesis pensi pri la azeninoj, kaj estas maltrankvila pri vi, dirante: Kion mi faru koncerne mian filon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Kaj kiam vi foriros de tie pluen kaj venos al la kverko de Tabor, renkontos vin tie tri homoj, irantaj al Dio en Bet-Elon; unu portas tri kapridojn, la dua portas tri bulojn da pano, kaj la tria portas felsakon da vino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Kaj ili salutos vin, kaj donos al vi du panojn; kaj vi prenu el iliaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Poste vi venos al la monteto de Dio, kie estas garnizono de la Filiŝtoj; kaj kiam vi tie eniros en la urbon, vi renkontos grupon da profetoj, irantaj malsupren de la altaĵo, kaj antaŭ ili psalteron, tamburinon, fluton, kaj harpon, kaj ili profetas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Kaj penetros vin la spirito de la Eternulo, kaj vi ekprofetos kune kun ili, kaj vi fariĝos alia homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'Kiam plenumiĝos super vi ĉi tiuj antaŭsignoj, tiam faru, kion bontrovos via mano, ĉar Dio estas kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Kaj vi iros antaŭ mi en Gilgalon; poste mi venos al vi, por fari bruloferojn, por buĉi pacoferojn. Sep tagojn atendu, ĝis mi venos al vi, kaj sciigos al vi, kion vi devas fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Kaj kiam li turnis siajn ŝultrojn, por foriri de Samuel, Dio donis al li alian koron, kaj ĉiuj tiuj antaŭsignoj plenumiĝis en tiu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Kiam ili venis tien al la monteto, jen grupo da profetoj iras al li renkonte; kaj penetris lin la spirito de la Eternulo, kaj li ekprofetis meze de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Kaj kiam ĉiuj, kiuj konis lin de antaŭe, vidis, ke li profetas kun profetoj, tiam la homoj diris unu al alia: Kio fariĝis kun la filo de Kiŝ? ĉu ankaŭ Saul estas inter la profetoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Kaj unu el tie respondis kaj diris: Kiu estas ilia patro? De tio devenis la proverbo: Ĉu ankaŭ Saul estas inter la profetoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Kaj ĉesinte profeti, li venis sur la altaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Kaj la onklo de Saul diris al li kaj al lia junulo: Kien vi iris? Kaj li respondis: Por serĉi la azeninojn; sed kiam ni vidis, ke ili ne troviĝas, ni iris al Samuel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Tiam diris la onklo de Saul: Diru al mi, mi petas, kion diris al vi Samuel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Kaj Saul diris al sia onklo: Li diris al ni, ke la azeninoj estas trovitaj. Sed tion, kion Samuel diris pri la reĝado, li ne diris al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Dume Samuel kunvenigis la popolon al la Eternulo en Micpan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'Kaj li diris al la Izraelidoj: Tiel diris la Eternulo, Dio de Izrael: Mi elkondukis Izraelon el Egiptujo, kaj savis vin el la manoj de la Egiptoj, kaj el la manoj de ĉiuj regnoj, kiuj premis vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Sed vi nun forrifuzis vian Dion, kiu savas vin el ĉiuj viaj mizeroj kaj suferoj, kaj vi diris al Li: Reĝon starigu super ni. Stariĝu do nun antaŭ la Eternulo laŭ viaj triboj kaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Kaj Samuel alvenigis ĉiujn tribojn de Izrael; kaj la loto trafis la tribon de Benjamen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Kaj li alvenigis la tribon de Benjamen laŭ ĝiaj familioj, kaj la loto trafis la familion de Matri; kaj la loto trafis Saulon, filon de Kiŝ. Oni serĉis lin, sed oni lin ne trovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Tiam oni demandis ankoraŭ la Eternulon: Ĉu la viro ankoraŭ venos ĉi tien? Kaj la Eternulo diris: Jen li kaŝis sin inter la vazaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Kaj oni kuris, kaj prenis lin de tie; kaj li stariĝis meze de la popolo, kaj de la ŝultroj supren li estis pli alta ol la tuta popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Kaj Samuel diris al la tuta popolo: Ĉu vi vidas, kiun la Eternulo elektis? ĉar ne ekzistas simila al li en la tuta popolo. Kaj la tuta popolo ekkriis, kaj diris: Vivu la reĝo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Kaj Samuel klarigis al la popolo la rajtojn de la reĝado, kaj skribis tion en libron kaj metis antaŭ la Eternulon. Kaj Samuel foririgis la tutan popolon ĉiun al lia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Kaj Saul ankaŭ iris al sia domo en Gibean; kaj iris kun li la militistoj, kies koron Dio ektuŝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Sed la sentaŭguloj diris: Kiamaniere helpos nin ĉi tiu? Kaj ili malestimis lin, kaj ne alportis al li donacojn; sed li ŝajnigis, ke li ne aŭdas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Venis Naĥaŝ la Amonido, kaj stariĝis tendare antaŭ Jabeŝ en Gilead. Kaj ĉiuj loĝantoj de Jabeŝ diris al Naĥaŝ: Faru kun ni interligon, kaj ni servos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Sed Naĥaŝ la Amonido diris al ili: Mi faros kun la kondiĉo, ke al ĉiuj el vi mi elpikos la dekstran okulon kaj per tio metos malhonoron sur la tutan Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Tiam diris al li la plejaĝuloj de Jabeŝ: Donu al ni tempon de sep tagoj, por ke ni sendu senditojn en ĉiujn regionojn de Izrael; kaj se neniu nin helpos, tiam ni eliros al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Kaj venis la senditoj en Gibean de Saul kaj diris tiujn vortojn al la oreloj de la popolo, kaj la tuta popolo laŭte ekploris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Sed jen Saul venas de la kampo malantaŭ la bovoj. Kaj Saul diris: Kio estas al la popolo, ke ili ploras? Kaj oni transdiris al li la vortojn de la loĝantoj de Jabeŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Kaj la spirito de Dio penetris Saulon, kiam li aŭdis tiujn vortojn, kaj forte ekflamis lia kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Kaj li prenis paron da bovoj kaj dishakis ilin, kaj dissendis la partojn per la senditoj en ĉiujn regionojn de Izrael, dirante: Se iu ne eliros post Saul kaj post Samuel, tiam tiel estos farite kun liaj bovoj. Kaj timo antaŭ la Eternulo falis sur la popolon, kaj ili eliris kiel unu homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Li kalkulis ilin en Bezek, kaj la nombro de la Izraelidoj estis tricent mil, kaj la nombro de la Jehudaidoj estis tridek mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Kaj ili diris al la venintaj senditoj: Tiel diru al la loĝantoj de Jabeŝ en Gilead: Morgaŭ venos al vi helpo, kiam la suno brilos varmege. Kaj la senditoj venis kaj raportis al la loĝantoj de Jabeŝ, kaj tiuj ĝojis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Kaj la loĝantoj de Jabeŝ diris: Morgaŭ ni eliros al vi, por ke vi agu kun ni, kiel plaĉos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'En la sekvanta tago Saul dividis la popolon en tri taĉmentojn, kaj ili eniris en la tendaron dum la matena gardotempo, kaj venkobatis la Amonidojn, antaŭ ol la tago fariĝis varma; la restintoj diskuris tiel, ke ne restis eĉ du kune.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Kaj la popolo diris al Samuel: Kiuj estas tiuj, kiuj diris: Ĉu Saul reĝos super ni? Donu tiujn homojn, ke ni ilin mortigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Sed Saul diris: Neniun oni devas mortigi en ĉi tiu tago, ĉar hodiaŭ la Eternulo faris savon al Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Kaj Samuel diris al la popolo: Venu, ni iru en Gilgalon, kaj ni novofestos tie la reĝecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Kaj la tuta popolo iris en Gilgalon, kaj ili reĝigis tie Saulon antaŭ la Eternulo en Gilgal, kaj buĉis tie pacoferojn antaŭ la Eternulo, kaj forte gajis tie Saul kaj ĉiuj Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Tiam Samuel diris al ĉiuj Izraelidoj: Jen mi obeis vian voĉon pri ĉio, kion vi diris al mi, kaj mi starigis por vi reĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'Kaj nun jen la reĝo iras antaŭ vi, kaj mi maljuniĝis kaj griziĝis, kaj miaj filoj estas ĉi tie inter vi; mi iradis antaŭ vi de mia juneco ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Jen mi estas; parolu pri mi antaŭ la Eternulo kaj antaŭ Lia sanktoleito: kies bovon mi prenis? kaj kies azenon mi prenis? kaj kontraŭ kiu mi agis maljuste? kaj kiun mi premis? kaj el kies mano mi prenis subaĉeton, por ke mi kovru miajn okulojn koncerne lin? kaj mi repagos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'Sed ili diris: Vi faris al ni nenian perfortaĵon nek maljustaĵon, kaj vi nenion prenis el ies mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Kaj li diris al ili: La Eternulo estas atestanto antaŭ vi, kaj Lia sanktoleito estas atestanto hodiaŭ, ke vi nenion trovis en mia mano. Kaj ili diris: Atestanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Tiam Samuel diris al la popolo: La Eternulo, kiu starigis Moseon kaj Aaronon, kaj kiu elkondukis viajn patrojn el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Nun stariĝu, kaj mi faru juĝan analizon koncerne vin antaŭ la Eternulo pri ĉiuj bonfaroj de la Eternulo, kiujn Li faris al vi kaj al viaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Kiam Jakob venis en Egiptujon kaj viaj patroj ekkriis al la Eternulo, tiam la Eternulo sendis Moseon kaj Aaronon, kaj ili elkondukis viajn patrojn el Egiptujo kaj ekloĝigis ilin sur ĉi tiu loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Sed ili forgesis la Eternulon, sian Dion, kaj Li transdonis ilin en la manojn de Sisera, militestro de Ĥacor, kaj en la manojn de la Filiŝtoj kaj en la manojn de la reĝo de Moab, kiuj militis kontraŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Tiam ili ekkriis al la Eternulo, kaj diris: Ni pekis, ĉar ni forlasis la Eternulon kaj servis al la Baaloj kaj al la Aŝtaroj; nun savu nin el la manoj de niaj malamikoj, kaj ni servos al Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Tiam la Eternulo sendis Jerubaalon kaj Bedanon kaj Jiftaĥon kaj Samuelon, kaj Li savis vin el la manoj de viaj malamikoj ĉirkaŭe, kaj vi restis eksterdanĝeraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Sed kiam vi vidis, ke Naĥaŝ, reĝo de la Amonidoj, venis kontraŭ vin, vi diris al mi: Ne, reĝo regu super ni; kaj la Eternulo, via Dio, estas ja via reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Nun jen estas la reĝo, kiun vi elektis, pri kiu vi petis; jen la Eternulo starigis reĝon super vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Se vi timos la Eternulon kaj servos al Li kaj obeos Lian voĉon kaj ne ribelos kontraŭ la diro de la Eternulo, tiam vi kaj ankaŭ la reĝo, kiu ekregis super vi, estos sub la defendo de la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Sed se vi ne obeos la voĉon de la Eternulo kaj vi ribelos kontraŭ la diro de la Eternulo, tiam la mano de la Eternulo estos kontraŭ vi, kiel kontraŭ viaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Eĉ nun stariĝu, kaj vidu tiun grandan faron, kiun la Eternulo faros antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Ĉu ne estas nun rikolto de tritiko? sed mi ekvokos al la Eternulo, kaj Li donos tondrojn kaj pluvon, por ke vi sciu kaj vidu, kiel granda estas via malbono, kiun vi faris antaŭ la Eternulo, petante por vi reĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Kaj Samuel ekvokis al la Eternulo, kaj la Eternulo donis tondrojn kaj pluvon en tiu tago; kaj forte ektimis la tuta popolo la Eternulon kaj Samuelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Kaj la tuta popolo diris al Samuel: Preĝu por viaj sklavoj al la Eternulo, via Dio, por ke ni ne mortu; ĉar al ĉiuj niaj pekoj ni aldonis ankoraŭ malbonagon per tio, ke ni petis por ni reĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Sed Samuel diris al la popolo: Ne timu; vi faris ja tiun tutan malbonon; nur ne forturniĝu de la Eternulo, kaj servu al la Eternulo per via tuta koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Kaj ne forkliniĝu al la vantaĵoj, kiuj ne helpas nek savas, ĉar ili estas vantaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'La Eternulo ne forlasos Sian popolon, pro Sia granda nomo; ĉar la Eternulo bonvolis fari vin Lia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Mi ankaŭ ne permesos al mi peki antaŭ la Eternulo, ĉesante preĝi por vi, kaj mi gvidados vin laŭ la vojo bona kaj ĝusta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Nur timu la Eternulon kaj servu al Li fidele per via tuta koro, ĉar vi vidas, kion grandan Li faris al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Sed se vi agos malbone, tiam ambaŭ, kiel vi, tiel ankaŭ via reĝo, pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Unu jaro pasis post la reĝiĝo de Saul, kaj jam du jarojn li reĝis super Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Kaj Saul elektis al si tri mil virojn el Izrael; du mil estis kun Saul en Miĥmaŝ kaj sur la monto Bet-El, kaj mil estis kun Jonatan en Gibea de Benjamen; la ceterajn el la popolo li foririgis ĉiun al lia tendo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Kaj Jonatan venkobatis la garnizonon de la Filiŝtoj, kiu estis en Geba. Kaj tion aŭdis la Filiŝtoj; kaj Saul disblovigis per trumpeto tra la tuta lando, dirante: Aŭdu tion la Hebreoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'Kaj la tuta Izrael aŭdis jenon: Saul venkobatis la garnizonon de la Filiŝtoj, kaj Izrael fariĝis malamata por la Filiŝtoj. Kaj oni kunvokis la popolon al Saul en Gilgalon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Kaj la Filiŝtoj kolektiĝis, por militi kontraŭ Izrael, tridek mil ĉaroj kaj ses mil rajdantoj, kaj tiom da popolo, kiom da sablo sur la bordo de la maro. Kaj ili eliris kaj stariĝis tendare en Miĥmaŝ, oriente de Bet- Aven.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'La Izraelidoj vidis, ke ili estas en mizero, ĉar la popolo perdis la kuraĝon, kaj la homoj kaŝis sin en kavernoj, en arbustoj, en rokoj, en kavoj, kaj en putoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Hebreoj transiris ankaŭ trans Jordanon en la landon de Gad kaj en Gileadon. Sed Saul estis ankoraŭ en Gilgal, kaj la tuta popolo tremis ĉe li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Kaj li atendis sep tagojn ĝis la templimo, kiun difinis Samuel, sed Samuel ne venis en Gilgalon; kaj la popolo komencis disiĝi de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Tiam Saul diris: Alportu al mi la bruloferon kaj la pacoferojn. Kaj li oferis la bruloferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Apenaŭ li finis la oferadon de la brulofero, venis Samuel. Kaj Saul eliris renkonte al li, por saluti lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Sed Samuel diris: Kion vi faris? Saul respondis: Mi vidis, ke la popolo diskuras de mi, kaj vi ne venis al la difinita tempo, kaj la Filiŝtoj kolektiĝis en Miĥmaŝ;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'kaj mi diris: Nun la Filiŝtoj atakos min ĉi tie en Gilgal, kaj mi ankoraŭ ne preĝis antaŭ la Eternulo; mi detenis min, sed fine mi oferis la bruloferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Tiam Samuel diris al Saul: Vi agis malprudente, ne plenumante la ordonon de la Eternulo, via Dio, kiun Li ordonis al vi; ĉar nun la Eternulo fortikigus vian reĝadon super Izrael por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Sed nun via reĝado ne longe daŭros: la Eternulo elserĉis al Si viron laŭ Sia koro, kaj la Eternulo ordonis al li esti estro super Lia popolo, ĉar vi ne plenumis tion, kion la Eternulo ordonis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Kaj Samuel leviĝis kaj iris de Gilgal al Gibea de Benjamen. Kaj Saul kalkulis la popolon, kiu troviĝis ĉe li, ĉirkaŭ sescent homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Saul kaj lia filo Jonatan, kaj la popolo, kiu estis kun ili, restis en Gibea de Benjamen, kaj la Filiŝtoj staris tendare en Miĥmaŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Kaj eliris el la tendaro de la Filiŝtoj tri taĉmentoj da ekstermantoj: unu taĉmento direktis sin laŭ la vojo al Ofra, al la lando Ŝual;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'la dua taĉmento direktis sin laŭ la vojo al Bet-Ĥoron; kaj la tria taĉmento direktis sin laŭ la lima vojo, kiu kondukas al la valo Ceboim, al la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Sed en la tuta lando de Izrael oni ne povis trovi forĝiston, ĉar la Filiŝtoj zorgis pri tio, ke la Hebreoj ne faru glavon aŭ ponardegon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Kaj ĉiuj Izraelidoj devis iri al la Filiŝtoj, se iu bezonis akrigi sian plugilon aŭ sian fosilon aŭ sian hakilon aŭ sian rikoltilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'Kaj la tranĉrandoj de la plugilferoj kaj de la fosiloj kaj de la tridentoj kaj de la hakiloj kaj de la pikstangoj malakriĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Tial en la tago de la batalo ne troviĝis glavo nek ponardego en la manoj de la tuta popolo, kiu estis kun Saul kaj kun Jonatan, sed troviĝis nur ĉe Saul kaj ĉe lia filo Jonatan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'Dume gardistaro el la Filiŝtoj eliris al la trapasejo de Miĥmaŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Unu tagon Jonatan, filo de Saul, diris al sia junulo armilportisto: Venu, ni transiru al la garnizono de la Filiŝtoj, kiu estas tie transe; sed al sia patro li tion ne diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Kaj Saul estis en la randa parto de Gibea, sub granatarbo, kiu estis en Migron; kaj da popolo estis kun li ĉirkaŭ sescent homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'Kaj Aĥija, filo de Aĥitub, frato de Ikabod, filo de Pinaĥas, filo de Eli, la pastro de la Eternulo en Ŝilo, estis portanto de la efodo; kaj la popolo ne sciis, ke Jonatan foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Inter la pasejoj, tra kiuj Jonatan volis transiri al la garnizono de la Filiŝtoj, estis pinta roko sur unu flanko kaj pinta roko sur la dua flanko; la nomo de unu estis Bocec, kaj la nomo de la dua estis Sene.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Unu roko elstaris norde kontraŭ Miĥmaŝ, kaj la dua sude kontraŭ Geba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Kaj Jonatan diris al sia junulo armilportisto: Venu, ni transiru al la garnizono de tiuj necirkumciditoj; eble la Eternulo ion faros por ni; ĉar por la Eternulo ne estas malfacile helpi per multo aŭ per malmulto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Kaj lia armilportisto diris al li: Faru ĉion, kion diras al vi via koro; iru antaŭen, mi iros kun vi, kien vi volas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Tiam Jonatan diris: Jen ni transiros al tiuj homoj, kaj montros nin al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Se ili diros al ni tiel: Restu, ĝis ni atingos vin-tiam ni haltos sur nia loko kaj ne supreniros al ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'sed se ili diros tiel: Venu al ni supren-tiam ni supreniros; ĉar la Eternulo transdonis ilin en niajn manojn, kaj tio estos por ni pruvosigno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Kaj ili ambaŭ aperis antaŭ la garnizono de la Filiŝtoj, kaj la Filiŝtoj diris: Jen Hebreoj eliras el la truoj, en kiuj ili sin kaŝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Kaj la homoj el la garnizono ekparolis al Jonatan kaj al lia armilportisto, kaj diris: Venu al ni supren, kaj ni klarigos al vi aferon. Tiam Jonatan diris al sia armilportisto: Sekvu min, ĉar la Eternulo transdonis ilin en la manojn de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Kaj Jonatan ekgrimpis per siaj manoj kaj piedoj, kaj lia armilportisto post li. Tiam ili ekfalis antaŭ Jonatan, kaj lia armilportisto mortigis ilin post li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'La unua mortigo, kiun faris Jonatan kaj lia armilportisto, estis ĉirkaŭ dudek homoj, sur la spaco de ĉirkaŭ duontaga plugado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Tiam fariĝis teruro en la tendaro, sur la kampo, kaj inter la tuta popolo; la garnizonanoj kaj la vagatakistoj ankaŭ ektimis, kaj la tero ektremis, kaj ekregis tumulto, farita de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'La gardostarantoj de Saul en Gibea de Benjamen ekvidis, ke la amaso disŝutiĝis kaj kuras en diversajn flankojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Tiam Saul diris al la homoj, kiuj estis ĉe li: Esploru kaj rigardu, kiu foriris de ni. Kaj oni esploris, kaj montriĝis, ke forestas Jonatan kaj lia armilportisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Kaj Saul diris al Aĥija: Venigu la keston de Dio; ĉar la kesto de Dio estis en tiu tago kun la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Kaj dum Saul parolis ankoraŭ kun la pastro, la tumulto en la tendaro de la Filiŝtoj fariĝis ankoraŭ pli granda. Kaj Saul diris al la pastro: Retiru vian manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Kaj kolektiĝis Saul kaj la tuta popolo, kiu estis kun li, kaj ili venis al la batalejo, kaj jen ili ekvidis, ke la glavo de ĉiu frapas lian proksimulon kaj la konfuzo estas tre granda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Kaj la Hebreoj, kiuj estis kun la Filiŝtoj antaŭe kaj venis kune kun ili en tendaro ĉirkaŭen, ili ankaŭ aliĝis al la Izraelidoj, kiuj estis kun Saul kaj Jonatan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Kaj ĉiuj Izraelidoj, kiuj sin kaŝis sur la monto de Efraim, aŭdis, ke la Filiŝtoj forkuras, kaj ili ankaŭ aliĝis kontraŭ ili batale.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'Kaj la Eternulo helpis en tiu tago Izraelon; la batalo daŭris ĝis Bet-Aven.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'La Izraelidoj estis lacaj en tiu tago; sed Saul ĵurligis la popolon, dirante: Malbenita estu tiu, kiu manĝos panon antaŭ la vespero, antaŭ ol mi venĝos al miaj malamikoj. Kaj la tuta popolo ne gustumis panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Kaj ĉiuj venis en arbaron; kaj tie estis mielo sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Kiam la popolo venis en la arbaron, ili vidis, ke jen fluas la mielo; sed neniu levis sian manon al la buŝo, ĉar la popolo timis la ĵuron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Sed Jonatan ne aŭdis, kiam lia patro ĵurligis la popolon; kaj li etendis la pinton de la bastono, kiu estis en lia mano, kaj trempis ĝin en la mielĉelaro, kaj almetis sian manon al la buŝo, kaj liaj okuloj revigliĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Tiam unu el la popolo ekparolis, kaj diris: Via patro ĵurligis la popolon, dirante: Malbenita estu tiu, kiu ion manĝos hodiaŭ; kaj la popolo laciĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Tiam Jonatan diris: Mia patro malgajigis la landon; rigardu, kiel revigliĝis miaj okuloj, kiam mi gustumis iom el ĉi tiu mielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Se la popolo manĝus hodiaŭ el la militakiraĵo, kion ĝi prenis de siaj malamikoj kaj kion ĝi trovis, ĉu nun ne pligrandiĝus la venkobato kontraŭ la Filiŝtoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'Kaj ili venkobatis en tiu tago la Filiŝtojn de Miĥmaŝ ĝis Ajalon; kaj la popolo forte laciĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Kaj la popolo ĵetis sin sur la militakiraĵon; kaj ili prenis ŝafojn kaj bovojn kaj bovidojn kaj buĉis ilin sur la tero, kaj la popolo manĝis kune kun la sango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Oni raportis al Saul, dirante: Jen la popolo pekas antaŭ la Eternulo, manĝante kun la sango. Kaj li diris: Vi faris kontraŭleĝaĵon; rulu nun al mi grandan ŝtonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Kaj Saul diris: Disiru en la popolon, kaj diru al ĝi: Ĉiu alkonduku al mi sian bovon kaj sian ŝafon, kaj buĉu ĝin ĉi tie kaj manĝu, kaj ne peku antaŭ la Eternulo, manĝante kun la sango. Kaj ĉiu el la popolo propramane alkondukis en tiu nokto sian bovon kaj buĉis tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Kaj Saul konstruis altaron al la Eternulo; tio estis la unua altaro, kiun li konstruis al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Kaj Saul diris: Ni postkuru la Filiŝtojn en la nokto kaj ni prirabu ilin, ĝis eklumos la mateno, kaj ni neniun restigu el ili. Kaj ili diris: Faru ĉion, kio plaĉas al vi. Kaj la pastro diris: Ni turnu nin ĉi tie al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Kaj Saul demandis Dion: Ĉu mi iru post la Filiŝtoj? ĉu Vi transdonos ilin en la manojn de la Izraelidoj? Sed Li ne respondis al li en tiu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Tiam Saul diris: Venu ĉi tien ĉiuj estroj de la popolo; eksciu kaj vidu, en kio konsistis la peko hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Ĉar kiel vivas la Eternulo, la helpanto de Izrael: se la kulpo estas en Jonatan, mia filo, li estos mortigita. Sed neniu el la tuta popolo respondis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Tiam li diris al ĉiuj Izraelidoj: Vi estos sur unu flanko, kaj mi kun mia filo Jonatan estos sur la dua flanko. Kaj la popolo respondis al Saul: Faru tion, kio plaĉas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Kaj Saul diris al la Eternulo, Dio de Izrael: Montru, kiu estas prava. Tiam estis trafitaj Jonatan kaj Saul, sed la popolo eliris senkulpa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Tiam Saul diris: Lotu inter mi kaj mia filo Jonatan. Kaj trafita estis Jonatan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Tiam Saul diris al Jonatan: Raportu al mi, kion vi faris. Kaj Jonatan raportis al li kaj diris: Mi gustumis per la pinto de la bastono, kiu estas en mia mano, iom da mielo: nun mi mortu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Kaj Saul diris: Dio faru tiel kaj pli; Jonatan devas morti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Sed la popolo diris al Saul: Ĉu devas morti Jonatan, kiu faris tiun grandan helpon al Izrael? ho, neniel! kiel vivas la Eternulo, eĉ unu haro de lia kapo ne falu sur la teron, ĉar kun Dio li agis hodiaŭ. Kaj la popolo liberigis Jonatanon, kaj li ne mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Kaj Saul foriris de la Filiŝtoj, kaj la Filiŝtoj iris sur sian lokon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Kaj Saul prenis en siajn manojn la regadon super Izrael, kaj li militis ĉirkaŭe kontraŭ ĉiuj siaj malamikoj, kontraŭ Moab kaj kontraŭ la Amonidoj kaj kontraŭ Edom kaj kontraŭ la reĝoj de Coba kaj kontraŭ la Filiŝtoj; kaj kien ajn li sin direktis, li venkobatis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Li aranĝis militistaron kaj venkobatis Amalekon kaj liberigis Izraelon el la manoj de liaj rabantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'La filoj de Saul estis: Jonatan kaj Jiŝvi kaj Malki-Ŝua; kaj la nomoj de liaj du filinoj estis: la nomo de la unuenaskita estis Merab, kaj la nomo de la pli juna estis Miĥal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Kaj la nomo de la edzino de Saul estis Aĥinoam, filino de Aĥimaac; kaj la nomo de lia militestro estis Abner, filo de Ner kaj onklo de Saul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Kiŝ estis la patro de Saul; kaj Ner, patro de Abner, estis filo de Abiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Forta estis la milito kontraŭ la Filiŝtoj dum la tuta vivo de Saul. Kaj ĉiufoje, kiam Saul vidis ian viron fortan kaj bravan, li prenis lin al si.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Kaj Samuel diris al Saul: Min sendis la Eternulo, por sanktolei vin kiel reĝon super Lia popolo, super Izrael; aŭskultu do la voĉon de la vortoj de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Tiel diris la Eternulo Cebaot: Mi rememoris, kion faris Amalek al Izrael, kiel li baris la vojon al li, kiam ĉi tiu iris el Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Nun iru kaj frapu Amalekon, kaj ekstermu ĉion, kion li havas; ne indulgu lin, sed mortigu la virojn kaj virinojn, infanojn kaj suĉinfanojn, bovojn kaj ŝafojn, kamelojn kaj azenojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Tiam Saul faris alvokon al la popolo, kaj li kalkulis ilin en Telaim, tie estis ducent mil piedirantoj kaj dek mil viroj el Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Kaj Saul venis al la urbo de Amalek kaj faris batalon ĉe la torento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'Kaj Saul diris al la Kenidoj: Iru, deturnu vin kaj foriĝu el inter la Amalekidoj, por ke mi ne ekstermu vin kune kun ili; vi faris ja favorkoraĵon al ĉiuj Izraelidoj, kiam ili iris el Egiptujo. Kaj la Kenidoj foriris el inter la Amalekidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Kaj Saul venkobatis Amalekon de Ĥavila ĝis Ŝur, kiu estas antaŭ Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Kaj li kaptis Agagon, reĝon de Amalek, vivantan, sed la tutan popolon li ekstermis per glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Kaj Saul kaj la popolo indulgis Agagon kaj la plej bonajn ŝafojn kaj bovojn kaj bovidojn kaj ŝafidojn, kaj ĉion, kio estis bona, kaj ili ne volis ekstermi ilin, sed ĉion senvaloran kaj neakceptindan ili ekstermis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Tiam la Eternulo ekparolis al Samuel, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, 'Mi bedaŭras, ke Mi faris Saulon reĝo; ĉar li deturnis sin de Mi, kaj Miajn vortojn li ne plenumis. Tio malĝojigis Samuelon, kaj li vokis al la Eternulo dum la tuta nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Kaj Samuel leviĝis frue matene, por iri renkonte al Saul. Oni raportis al Samuel, ke Saul venis al Karmel, ke li tie starigis al si monumenton kaj poste turnis sin kaj foriris kaj venis en Gilgalon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Kiam Samuel venis al Saul, Saul diris al li: Estu benita de la Eternulo; mi plenumis la diron de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Sed Samuel diris: Kion do signifas tiu voĉo de ŝafoj en miaj oreloj, kaj la voĉo de bovoj, kiun mi aŭdas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Kaj Saul respondis: De la Amalekidoj oni venigis ilin, ĉar la popolo indulgis la plej bonajn ŝafojn kaj bovojn, por buĉoferi ilin al la Eternulo, via Dio; la ceterajn ni ekstermis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Sed Samuel diris al Saul: Permesu, mi diros al vi, kion parolis al mi la Eternulo en ĉi tiu nokto. Kaj tiu respondis al li: Diru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Kaj Samuel diris: Ĉu vi ne estis malgranda en viaj okuloj, kaj tamen vi fariĝis estro de la triboj de Izrael, kaj la Eternulo sanktoleis vin reĝo super Izrael?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Kaj la Eternulo vojirigis vin, kaj diris: Iru kaj ekstermu la pekulojn la Amalekidojn, kaj militu kontraŭ ili, ĝis vi tute ekstermos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Kial do vi ne obeis la voĉon de la Eternulo, sed direktiĝis al militakiraĵo kaj faris la malbonon antaŭ la okuloj de la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Kaj Saul diris al Samuel: Mi obeis la voĉon de la Eternulo, kaj mi iris la vojon, sur kiun sendis min la Eternulo, kaj mi venigis Agagon, reĝon de Amalek, kaj la Amalekidojn mi ekstermis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Kaj la popolo prenis el la militakiraĵo ŝafojn kaj bovojn, la plej bonan el la kondamnitaĵo, por buĉoferi al la Eternulo, via Dio, en Gilgal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Sed Samuel diris: Ĉu bruloferoj kaj buĉoferoj estas tiel agrablaj al la Eternulo, kiel la obeado al la voĉo de la Eternulo? vidu, obeado estas pli bona ol buĉofero, atentado estas pli bona ol la sebo de ŝafoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Ĉar malobeo estas kiel peko de sorĉado, kaj neplenumo estas kiel peko de idolservado. Pro tio, ke vi malŝatis la diron de la Eternulo, Li malŝatis vin, ke vi ne estu plu reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Tiam Saul diris al Samuel: Mi pekis, ĉar mi malobeis la diron de la Eternulo kaj viajn vortojn; mi timis la popolon, kaj mi obeis ĝian voĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Kaj nun pardonu, mi petas, mian pekon, kaj iru kun mi returne, por ke mi adorkliniĝu antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Sed Samuel diris al Saul: Mi ne iros kun vi returne; ĉar vi malŝatis la diron de la Eternulo, tial la Eternulo malŝatis vin, ke vi ne estu plu reĝo super Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Kaj kiam Samuel deturnis sin por iri, li kaptis lin je la rando de lia vesto, kaj ĝi disŝiriĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Tiam Samuel diris al li: La Eternulo forŝiris de vi hodiaŭ la regnon de Izrael, kaj transdonis ĝin al via proksimulo, kiu estas pli bona ol vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Kaj la Potenculo de Izrael ne ŝanĝos Sian decidon kaj ne pentos; ĉar Li ne estas homo, ke Li pentu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Kaj tiu diris: Mi pekis; sed nun, mi vin petas, faru al mi honoron antaŭ la plejaĝuloj de mia popolo kaj antaŭ Izrael, reiru kun mi, por ke mi adorkliniĝu antaŭ la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Tiam Samuel reiris post Saul, kaj Saul adorkliniĝis antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Kaj Samuel diris: Alkonduku al mi Agagon, reĝon de Amalek; kaj venis al li Agag en katenoj, kaj Agag diris: Ho, alproksimiĝas la maldolĉeco de la morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Kaj Samuel diris: Kiel via glavo seninfanigis virinojn, via patrino fariĝos seninfana inter la virinoj. Kaj Samuel dishakis Agagon antaŭ la Eternulo en Gilgal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Kaj Samuel foriris en la direkto al Rama, kaj Saul iris al sia domo en Gibea de Saul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Kaj Samuel ne plu vidis Saulon ĝis la tago de sia morto; tamen Samuel funebris pri Saul; kaj la Eternulo bedaŭris, ke Li faris Saulon reĝo super Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Kaj la Eternulo diris al Samuel: Kiel longe vi funebros pri Saul, kiun Mi trovis nedigna reĝi super Izrael? plenigu vian kornon per oleo, kaj iru; Mi sendos vin al Jiŝaj la Bet-Leĥemano, ĉar inter liaj filoj Mi elvidis al Mi reĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Kaj Samuel diris: Kiel mi iros? Saul aŭdos, kaj mortigos min. Sed la Eternulo diris: Prenu kun vi bovidinon, kaj diru: Mi venis, por fari buĉoferon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'Kaj invitu Jiŝajon al la ofero; kaj Mi sciigos al vi, kion vi devas fari, kaj vi sanktoleos al Mi tiun, kiun Mi montros al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Kaj Samuel faris tion, kion diris la Eternulo, kaj li venis Bet- Leĥemon. Kun timo iris al li renkonte la plejaĝuloj de la urbo, kaj diris: Ĉu en paco vi venas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Kaj li respondis: En paco; mi venis, por buĉoferi al la Eternulo; sanktigu vin, kaj venu kun mi por la buĉofero. Kaj li sanktigis Jiŝajon kaj liajn filojn, kaj invitis ilin al la ofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Kiam ili venis, li ekvidis Eliabon, kaj diris: Jen antaŭ la Eternulo estas Lia sanktoleito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Sed la Eternulo diris al Samuel: Ne rigardu lian aspekton kaj lian altan kreskon, ĉar Mi malŝatas lin; ne estas tiel, kiel vidas homo: ĉar homo vidas tion, kio estas antaŭ la okuloj, sed la Eternulo rigardas en la koron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Tiam Jiŝaj vokis Abinadabon, kaj pasigis lin antaŭ Samuel; sed ĉi tiu diris: Ankaŭ ĉi tiun la Eternulo ne elektis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Kaj Jiŝaj pasigis Ŝaman; sed Samuel diris: Ankaŭ ĉi tiun la Eternulo ne elektis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Tiel Jiŝaj pasigis siajn sep filojn antaŭ Samuel; sed Samuel diris al Jiŝaj: La Eternulo ne elektis ĉi tiujn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Kaj Samuel diris al Jiŝaj: Ĉu tio estas jam ĉiuj knaboj? Kaj ĉi tiu diris: Restas ankoraŭ la plej juna, li paŝtas nun la ŝafojn. Kaj Samuel diris al Jiŝaj: Sendu, kaj venigu lin, ĉar ni ne sidiĝos al la tablo, antaŭ ol li venos ĉi tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Kaj li sendis, kaj venigis lin. Kaj li estis ruĝa, kun belaj okuloj kaj bonaspekta. Tiam la Eternulo diris: Leviĝu, sanktoleu lin, ĉar tio estas li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Kaj Samuel prenis la kornon kun la oleo, kaj sanktoleis lin inter liaj fratoj. Kaj la spirito de la Eternulo ekfavoris Davidon de post tiu tago kaj pluen. Kaj Samuel leviĝis kaj iris en Raman.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Kaj la spirito de la Eternulo foriĝis de Saul, kaj ekturmentis lin spirito malbona, sendita de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Kaj la servantoj de Saul diris al li: Jen malbona spirito, sendita de Dio, turmentas vin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'tial nia sinjoro diru al siaj servantoj, ke ili elserĉu homon, kiu povoscias ludi harpon: kaj kiam atakos vin la malbona spirito, sendita de Dio, li ekludos per sia mano, kaj tiam fariĝos al vi bone.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Kaj Saul diris al siaj servantoj: Elserĉu al mi homon, kiu bone ludas, kaj venigu lin al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Tiam unu el la junuloj respondis kaj diris: Ĉe Jiŝaj la Bet-Leĥemano mi vidis filon, kiu povoscias ludi, kaj li estas fortulo kaj militkapablulo kaj prudenta en siaj paroloj kaj belaspekta, kaj la Eternulo estas kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Kaj Saul sendis senditojn al Jiŝaj, kaj dirigis: Sendu al mi vian filon David, kiu estas ĉe la ŝafoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Tiam Jiŝaj prenis azenon, ŝarĝitan per pano, kaj felsakon kun vino, kaj unu kapridon, kaj li sendis tion per sia filo David al Saul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'Kaj David venis al Saul, kaj ekservis antaŭ li; kaj ĉi tiu tre ekamis lin, kaj li fariĝis lia armilportisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Kaj Saul sendis al Jiŝaj, por diri: Mi petas, David restu ĉe mi, ĉar li plaĉas al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'Kaj ĉiufoje, kiam la spirito, sendita de Dio, atakis Saulon, David prenadis la harpon kaj ludadis per sia mano; tiam al Saul fariĝadis pli facile kaj bone, kaj la malbona spirito foriĝadis de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'La Filiŝtoj kolektis siajn militistarojn por milito, kaj kuniĝis apud Soĥo de Jehuda, kaj stariĝis tendare inter Soĥo kaj Azeka, en Efes-Damim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Kaj Saul kaj la viroj de Izrael kolektiĝis, kaj stariĝis tendare en la valo de Ela, kaj pretigis sin por batalo kontraŭ la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'La Filiŝtoj staris sur la monto unuflanke, kaj la Izraelidoj staris sur la monto duaflanke, kaj la valo estis inter ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Kaj eliris grandegulo el la tendaroj de la Filiŝtoj; lia nomo estis Goljat, el Gat; lia alteco estis ses ulnoj kaj unu manlarĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Kaj kupra kasko estis sur lia kapo, kaj per skvamita kiraso li estis vestita, kaj la pezo de la kiraso estis kvin mil sikloj da kupro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Kaj kupraj armaĵetoj estis sur liaj piedoj, kaj kupra ŝildo sur liaj ŝultroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'La tenilo de lia lanco estis kiel rultrabo de teksisto, kaj la fero de lia lanco havis la pezon de sescent sikloj da fero; kaj antaŭ li iris ŝildoportisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Kaj li stariĝis, kaj ekkriis al la taĉmentoj de Izrael, kaj diris al ili: Por kio vi eliris batale? ĉu mi ne estas Filiŝto, kaj vi sklavoj de Saul? elektu inter vi viron, kaj li malsupreniru al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Se li povos batali kun mi kaj venkos min, tiam ni estos viaj sklavoj; sed se mi lin venkos kaj batos, tiam vi estos niaj sklavoj kaj vi servos al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Kaj la Filiŝto diris: Mi hontigos hodiaŭ la taĉmentojn de Izrael; donu al mi viron, ke ni ambaŭ interbatalu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Kiam Saul kaj ĉiuj Izraelidoj aŭdis la vortojn de tiu Filiŝto, ili eksentis teruron kaj tre ektimis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'Estis David, filo de tiu Efratano el Bet-Leĥem de Jehuda, kies nomo estis Jiŝaj kaj kiu havis ok filojn; kaj tiu viro en la tempo de Saul estis jam maljuna, profundaĝa inter la viroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'La tri plej maljunaj filoj de Jiŝaj iris, sekvante Saulon, en la militon; la nomoj de liaj tri filoj, kiuj iris en la militon, estis: Eliab, la unuenaskito, kaj la dua post li Abinadab, kaj la tria Ŝama.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'David estis la plej juna; kaj la tri plej maljunaj iris post Saul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'Sed David venadis al Saul kaj reiradis de li, por paŝti la ŝafojn de sia patro en Bet-Leĥem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'La Filiŝto eliradis matene kaj vespere, kaj stariĝadis dum kvardek tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Kaj Jiŝaj diris al sia filo David: Prenu por viaj fratoj ĉi tiun efon da rostitaj grajnoj kaj ĉi tiujn dek panojn, kaj kuru en la tendaron al viaj fratoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'kaj ĉi tiujn dek fromaĝojn alportu al la milestro, kaj rigardu, kiel fartas viaj fratoj, kaj prenu ilian komision.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Kaj Saul kaj ili kaj ĉiuj viroj de Izrael estis en la valo de Ela, militante kontraŭ la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Kaj David leviĝis frue matene, lasis la ŝafojn al la gardisto, prenis la portotaĵon kaj iris, kiel ordonis al li Jiŝaj, kaj venis al la tendaro, kiam la militistaro eliris por sin aranĝi kaj oni trumpetis por batalo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Kaj aranĝis sin la Izraelidoj kaj la Filiŝtoj, fronton kontraŭ fronto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'David lasis la vazojn, kiujn li portis, ĉe la gardisto de ilaroj, kuris al la fronto, kaj demandis pri la farto de siaj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Dum li parolis kun ili, jen la grandegulo, Goljat la Filiŝto estis lia nomo, el Gat, eliris el la vicoj de la Filiŝtoj kaj komencis paroli kiel antaŭe; kaj David tion aŭdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Kaj ĉiuj Izraelidoj, ekvidinte tiun viron, forkuris de li kaj tre timis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Kaj la Izraelidoj diris: Ĉu vi vidis tiun viron, kiu tiel sin levas? por moki Izraelon li sin levas; kiu lin venkobatos, tiun la reĝo riĉigos per granda riĉeco, kaj sian filinon li donos al li, kaj la domon de lia patro li faros libera en Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Tiam David diris al la homoj, kiuj staris apud li: Kio estos farita al la homo, kiu venkobatos tiun Filiŝton kaj deprenos de Izrael la malhonoron? ĉar kiu estas tiu necirkumcidita Filiŝto, ke li mokas la militistaron de la vivanta Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Kaj la popolo diris al li kiel antaŭe: Tio estos farita al la homo, kiu venkobatos lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Kiam lia plej maljuna frato Eliab aŭdis, kiel li parolas kun la homoj, ekflamis la kolero de Eliab kontraŭ David, kaj li diris: Por kio vi venis? kaj sub kies zorgado vi lasis tiun malgrandan ŝafaron en la dezerto? mi konas vian arogantecon kaj vian malbonan koron; vi venis nur por vidi la batalon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'Tiam David diris: Kion do mi nun faris? ĉu mi venis sen bezono?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Kaj li deturnis sin de li al alia flanko, kaj ekparolis kiel antaŭe; kaj la homoj respondis al li kiel la unuan fojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'Kiam oni aŭdis la vortojn, kiujn diris David, oni raportis al Saul, kaj ĉi tiu venigis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'Kaj David diris al Saul: Neniu perdu la kuraĝon pro li: via sklavo iros kaj batalos kontraŭ tiu Filiŝto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Sed Saul diris al David: Vi ne povas iri kontraŭ tiun Filiŝton, por batali kontraŭ li; ĉar vi estas knabo, kaj li estas batalisto detempe de siaj plej junaj jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'Tiam David diris al Saul: Via sklavo estis ĉe sia patro paŝtanto de ŝafoj; kaj venadis leono aŭ urso kaj forportadis ŝafon el la ŝafaro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'tiam mi kuradis post tiu, batadis ĝin, kaj savadis el ĝia buŝo; se ĝi stariĝis kontraŭ mi, mi kaptis ĝin je la makzelo, batis kaj mortigis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Kiel la leonon, tiel ankaŭ la urson via sklavo venkobatis; ankaŭ kun ĉi tiu necirkumcidita Filiŝto estos la sama afero, kiel kun ĉiu el tiuj, ĉar li malhonoras la militistaron de la vivanta Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Kaj David diris: La Eternulo, kiu savis min kontraŭ leono kaj kontraŭ urso, savos min kontraŭ ĉi tiu Filiŝto. Tiam Saul diris al David: Iru, kaj la Eternulo estu kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Kaj Saul vestis Davidon per siaj vestoj, kaj metis kupran kaskon sur lian kapon, kaj vestis lin per kiraso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Kaj David zonis lian glavon supre de siaj vestoj, kaj provis iri, ĉar li ne kutimis; sed David diris al Saul: Mi ne povas iri en ĉi tio, ĉar mi ne kutimis. Kaj David demetis tion de si.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'Kaj li prenis sian bastonon en sian manon, kaj elektis al si kvin glatajn ŝtonojn el la torento, kaj metis ilin en la paŝtistan vazon, kiun li havis, kaj en la saketon, kaj kun la ĵetilo en la mano li iris al la Filiŝto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Kaj la Filiŝto eliris kaj komencis alproksimiĝi al David, kaj lia ŝildoportisto iris antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Kiam la Filiŝto ekrigardis kaj vidis Davidon, li malŝatis lin, ĉar li estis knabo, ruĝvanga kaj belaspekta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Kaj la Filiŝto diris al David: Ĉu mi estas hundo, ke vi iras al mi kun bastono? Kaj la Filiŝto malbenis Davidon per siaj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Kaj la Filiŝto diris al David: Venu al mi, por ke mi donu vian karnon al la birdoj de la ĉielo kaj al la bestoj de la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'Sed David diris al la Filiŝto: Vi iras kontraŭ min kun glavo, lanco, kaj ŝildo; kaj mi iras kontraŭ vin en la nomo de la Eternulo Cebaot, la Dio de la militistaro de Izrael, kiun vi malhonoris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Hodiaŭ la Eternulo transdonos vin en mian manon, ke mi venkobatu vin kaj deprenu de vi vian kapon, kaj por ke mi donu hodiaŭ la kadavrojn de la Filiŝtaj taĉmentoj al la birdoj de la ĉielo kaj al la bestoj de la tero, por ke eksciu la tuta tero, ke Izrael havas Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'Kaj ekscios ĉi tiu tuta komunumo, ke ne per glavo kaj lanco savas la Eternulo, ĉar de la Eternulo dependas la milito, kaj Li transdonos vin en niajn manojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Kaj kiam la Filiŝto leviĝis kaj ekiris, por alproksimiĝi al David, tiam David rapide ekkuris al la fronto kontraŭ la Filiŝton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'Kaj David etendis sian manon al la vazo, kaj prenis el tie ŝtonon, ĵetis per la ĵetilo kaj trafis la Filiŝton en lian frunton, kaj la ŝtono penetris en lian frunton, kaj li falis kun la vizaĝo sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Tiamaniere David venkis la Filiŝton per la ĵetilo kaj per la ŝtono, kaj batis la Filiŝton kaj mortigis lin, kvankam glavo ne estis en la mano de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'David alkuris, stariĝis super la Filiŝto, prenis lian glavon, elprenis ĝin el la ingo, kaj mortigis lin, kaj dehakis per ĝi lian kapon. Kiam la Filiŝtoj vidis, ke ilia fortegulo mortis, ili forkuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Tiam leviĝis la viroj de Izrael kaj Jehuda, kaj ekkriis, kaj postkuris la Filiŝtojn ĝis la eniro en la valon kaj ĝis la pordego de Ekron. Kaj falis la mortigitoj el la Filiŝtoj sur la vojo al Ŝaaraim, ĝis Gat kaj ĝis Ekron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Kaj la Izraelidoj revenis de la kurado post la Filiŝtoj kaj disrabis ilian tendaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'Kaj David prenis la kapon de la Filiŝto, kaj alportis ĝin en Jerusalemon, kaj liajn armilojn li metis en sian tendon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Kiam Saul vidis Davidon, elirantan kontraŭ la Filiŝton, li diris al Abner, la militestro: Kies filo estas ĉi tiu junulo, Abner? Kaj Abner respondis: Mi ĵuras per via animo, ho reĝo, ke mi ne scias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Kaj la reĝo diris: Demandu, kies filo estas ĉi tiu junulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Kiam David revenis post la mortigo de la Filiŝto, Abner prenis lin kaj venigis lin antaŭ Saulon, kaj la kapo de la Filiŝto estis en lia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Kaj Saul diris al li: Kies filo vi estas, junulo? Kaj David respondis: Filo de via sklavo Jiŝaj, la Bet-Leĥemano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Kiam li finis la paroladon kun Saul, la animo de Jonatan alligiĝis al la animo de David, kaj Jonatan ekamis lin kiel sian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Kaj Saul prenis lin en tiu tago, kaj ne lasis lin reiri al la domo de sia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Kaj Jonatan faris kun David interligon, ĉar li ekamis lin kiel sian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Kaj Jonatan deprenis la tunikon, kiu estis sur li, kaj donis ĝin al David, ankaŭ siajn militajn vestojn, inkluzive sian glavon, sian pafarkon, kaj sian zonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'Kaj David iradis ĉien, kien sendis lin Saul, kaj agadis prudente; kaj Saul faris lin estro de la militistoj, kaj tio plaĉis al la tuta popolo kaj ankaŭ al la servantoj de Saul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Okazis, ke dum ilia revenado, kiam David revenis post la mortigo de la Filiŝto, eliris la virinoj el ĉiuj urboj de Izrael, kantante kaj dancante, renkonte al la reĝo Saul, kun tamburinoj, ĝojkrioj, kaj cimbaloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'Kaj la ludantaj virinoj kantis unuj al la aliaj, kaj diris: Saul frapis milojn, Kaj David dekmilojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Kaj tio tre kolerigis Saulon kaj ne plaĉis al li, kaj li diris: Ili donis al David dekmilojn, kaj al mi ili donis milojn; nun mankas al li ankoraŭ nur la reĝeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'De tiu tago kaj plue Saul malamike rigardadis Davidon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'En la morgaŭa tago okazis, ke la malbona spirito, sendita de Dio, atakis Saulon, kaj li furiozis en sia domo, kaj David ludis per sia mano, kiel ĉiutage, kaj en la mano de Saul estis lanco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'Kaj Saul ĵetis la lancon, kaj pensis: Mi alpikos Davidon al la muro. Sed David forturnis sin de li du fojojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Tiam Saul ektimis Davidon, ĉar la Eternulo estis kun li, kaj de Saul Li Sin forturnis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Kaj Saul forigis lin de si kaj faris lin milestro, kaj li iradis kaj venadis antaŭ la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'Kaj David estis prudenta en ĉiuj siaj agoj, kaj la Eternulo estis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Kaj Saul vidis, ke li agas tre prudente, kaj li timis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Sed la tuta Izrael kaj Jehuda amis Davidon pro tio, kiamaniere li iradis kaj venadis antaŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Kaj Saul diris al David: Jen estas mia pliaĝa filino Merab, mi donos ŝin al vi kiel edzinon; nur estu al mi kuraĝa kaj konduku la militojn de la Eternulo. Ĉar Saul pensis: Mia mano lin ne tuŝu, sed li pereu de la manoj de la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'Sed David diris al Saul: Kiu mi estas, kaj kia estas la vivo de la familio de mia patro en Izrael, ke mi fariĝu bofilo de la reĝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Tamen, kiam venis la tempo, ke Merab, la filino de Saul, estu donata al David, ŝi estis fordonita kiel edzino al Adriel, la Meĥolatano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Dume Miĥal, filino de Saul, ekamis Davidon, kaj oni diris tion al Saul, kaj la afero plaĉis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'Kaj Saul pensis: Mi donos ŝin al li, por ke ŝi fariĝu por li falilo, kaj por ke trafu lin la manoj de la Filiŝtoj. Kaj Saul diris al David: Per la dua filino fariĝu nun mia bofilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Kaj Saul ordonis al siaj servantoj: Parolu al David sekrete, kaj diru: Jen la reĝo vin favoras, kaj ĉiuj liaj servantoj vin amas; boparenciĝu do nun kun la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Kaj la servantoj de Saul diris tiujn vortojn al David; sed David diris: Ĉu vi opinias, ke estas afero facila boparenciĝi kun la reĝo? mi estas ja homo malriĉa kaj ne eminenta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Kaj la servantoj de Saul raportis al li, dirante: Tiajn vortojn diris David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Tiam Saul diris: Tiamaniere diru al David: La reĝo ne deziras alian edziĝan donacon krom cent prepucioj de Filiŝtoj, por venĝi al la malamikoj de la reĝo. Kaj Saul esperis faligi Davidon per la manoj de la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Kaj liaj servantoj diris al David tiujn vortojn, kaj al David plaĉis la afero, ke li boparenciĝos kun la reĝo. Kaj antaŭ ol venis la destinita tempo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'David leviĝis kaj iris kun siaj viroj kaj mortigis el la Filiŝtoj ducent virojn, kaj David alportis iliajn prepuciojn en plena nombro al la reĝo, por boparenciĝi kun la reĝo. Kaj Saul donis al li sian filinon Miĥal kiel edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Kaj Saul vidis kaj komprenis, ke la Eternulo estas kun David, kaj ke Miĥal, la filino de Saul, lin amas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Tiam Saul ankoraŭ pli ektimis Davidon, kaj Saul fariĝis malamiko de David por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'La estroj de la Filiŝtoj eliradis, kaj ĉiufoje, kiam ili eliris, David agis pli prudente ol ĉiuj servantoj de Saul, kaj lia nomo fariĝis tre glora.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Saul diris al sia filo Jonatan kaj al ĉiuj siaj servantoj, ke ili mortigu Davidon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'Sed Jonatan, filo de Saul, tre amis Davidon. Kaj Jonatan sciigis al David, dirante: Mia patro Saul intencas mortigi vin; tial gardu vin, mi petas, morgaŭ matene: iru en sekretan lokon kaj kaŝu vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Kaj mi eliros kaj stariĝos apud mia patro sur tiu kampo, kie vi estos, kaj mi parolos pri vi al mia patro; kaj kiam mi vidos, kiel la afero staras, mi diros al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Kaj Jonatan parolis pri David bonon al sia patro Saul, kaj diris al li: La reĝo ne peku kontraŭ sia sklavo David, ĉar li ne pekis kontraŭ vi kaj ĉar liaj agoj estas tre bonaj por vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'li riskis sian vivon kaj mortigis la Filiŝton, kaj la Eternulo faris grandan savon al la tuta Izrael; vi tion vidis, kaj vi ĝojis; kial do vi volas peki kontraŭ senkulpa sango kaj mortigi Davidon senkaŭze?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Kaj Saul aŭskultis la voĉon de Jonatan, kaj Saul ĵuris: Mi ĵuras per la Eternulo, li ne mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Tiam Jonatan alvokis Davidon, kaj Jonatan rakontis al li ĉion ĉi tion; kaj Jonatan alkondukis Davidon al Saul, ke li estu antaŭ ĉi tiu kiel antaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Komenciĝis denove milito; kaj David eliris kaj batalis kontraŭ la Filiŝtoj, kaj frapis ilin per granda frapo, kaj ili forkuris de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Sed la malbona spirito, sendita de la Eternulo, denove venis sur Saulon, kiam li sidis en sia domo kaj lia lanco estis en lia mano kaj David ludis per la mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Kaj Saul intencis alpiki per la lanco Davidon al la muro; sed David forsaltis de Saul, kaj la lanco enpikiĝis en la muron, kaj David forkuris kaj saviĝis en tiu nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Tiam Saul sendis senditojn al la domo de David, por fari gardon kontraŭ li kaj mortigi lin matene. Sed al David diris lia edzino Miĥal jene: Se vi ne savos vian animon en ĉi tiu nokto, vi morgaŭ estos mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Kaj Miĥal malsuprenigis Davidon per la fenestro, kaj li foriris, forkuris, kaj saviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Poste Miĥal prenis doman dion, metis ĝin sur la liton, ĉirkaŭ ĝian kapon ŝi metis tapiŝon el kapra felo, kaj kovris ĝin per vesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Kiam Saul sendis senditojn, por preni Davidon, ŝi diris: Li estas malsana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Saul sendis la senditojn, ke ili rigardu Davidon, kaj li diris al ili: Alportu lin al mi kun la lito, por ke oni mortigu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'La senditoj venis, kaj vidis, ke sur la lito estas doma dio kaj ĉirkaŭ ĝia kapo estas tapiŝo el kapra felo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Kaj Saul diris al Miĥal: Kial vi tiel trompis min kaj foririgis mian malamikon, ke li saviĝu? Kaj Miĥal diris al Saul: Li diris al mi: Foririgu min, ĉar alie mi vin mortigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'Dume David forkuris kaj saviĝis, kaj venis al Samuel en Raman, kaj rakontis al li ĉion, kion faris al li Saul. Kaj li kaj Samuel iris kaj restis en Najot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Kaj oni raportis al Saul, dirante: Jen David estas nun en Najot, en la regiono de Rama.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Tiam Saul sendis senditojn, por preni Davidon. Sed ili ekvidis aron da profetoj, kiuj estis profetantaj, kaj Samuelon, kiu staris super ili; kaj venis sur la senditojn de Saul la spirito de Dio, kaj ili ankaŭ ekprofetis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Kiam oni tion raportis al Saul, li sendis aliajn senditojn; sed ankaŭ ili ekprofetis. Kaj Saul plue sendis triajn senditojn, sed ankaŭ ili ekprofetis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Tiam li mem iris en Raman, kaj venis al la granda puto, kiu estas en Seĥu, kaj demandis: Kie estas Samuel kaj David? Kaj oni respondis: En Najot, en la regiono de Rama.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'Kaj li iris tien, en Najoton en la Rama regiono; sed tiam ankaŭ sur lin venis la spirito de Dio, kaj li iris ĉiam profetante, ĝis li venis en Najoton en la Rama regiono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Kaj li ankaŭ demetis siajn vestojn, kaj li ankaŭ profetis antaŭ Samuel, kaj li kuŝis senveste dum tiu tuta tago kaj dum la tuta nokto. Tial oni diras: Ĉu ankaŭ Saul estas inter la profetoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'Sed David forkuris el Najot en la Rama regiono, kaj venis, kaj diris al Jonatan: Kion mi faris? kio estas mia krimo? kaj kio estas mia peko antaŭ via patro, ke li volas forpreni mian animon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Sed tiu diris al li: Tio certe ne fariĝos, vi ne mortos; mia patro faras nenian aferon grandan aŭ malgrandan, ne sciigante tion al mi; kial do mia patro kaŝus antaŭ mi ĉi tiun aferon? tio ne fariĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Tiam David plue ĵuris kaj diris: Via patro scias bone, ke vi favoras min, tial li diris al si: Jonatan ne devas scii ĉi tion, por ke li ne afliktiĝu; vere, kiel vivas la Eternulo kaj kiel vivas via animo, inter mi kaj la morto estas nur unu paŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Kaj Jonatan diris al David: Kion ajn via animo diros, tion mi faros por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'Tiam David diris al Jonatan: Jen morgaŭ estos monatkomenco, kaj mi devas sidi kun la reĝo ĉe la tagmanĝo; permesu, ke mi foriru kaj kaŝu min sur la kampo ĝis vespero de la tria tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Se via patro demandos pri mi, tiam diru: David forte petis min, ke li kuru al sia urbo Bet-Leĥem, ĉar tie estas ĉiujara oferado de la tuta familio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Se li diros: Bone, tiam estos paco al via sklavo; sed se li ekkoleros, tiam sciu, ke malbono jam estas decidita de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Faru do favorkoraĵon al via sklavo, ĉar vi akceptis vian sklavon kun vi en interligon antaŭ la Eternulo; kaj se mi havas sur mi ian kulpon, tiam mortigu min vi; sed por kio vi venigus min al via patro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Sed Jonatan diris: Neniam tio fariĝu al vi, ke mi scius, ke mia patro decidis malbonon kontraŭ vi, kaj mi ne sciigus tion al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'Kaj David diris al Jonatan: Kiu diros al mi, se via patro donos al vi respondon kruelan?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Jonatan diris al David: Venu, ni eliros sur la kampon. Kaj ambaŭ eliris sur la kampon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Tiam Jonatan diris al David: La Eternulo, Dio de Izrael, se mi esploros mian patron ĝis postmorgaŭ, kaj konvinkiĝos, ke li estas favora al David, kaj se mi tiam ne sendos al vi kaj ne malkaŝos al viaj oreloj-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'tiam la Eternulo punu kaj repunu Jonatanon. Sed se al mia patro plaĉos io malbona kontraŭ vi, tion mi ankaŭ malkaŝos al viaj oreloj, kaj mi forliberigos vin, ke vi iru en paco; kaj la Eternulo estu kun vi, kiel Li estis kun mia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Kaj se mi ankoraŭ vivos, ĉu vi ne agos kun mi favorkore, ke mi ne mortu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'Kaj vian favorkorecon ne fortiru de mia domo eterne, eĉ ne tiam, kiam la Eternulo ekstermos ĉiujn malamikojn de David de sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Tiamaniere faris Jonatan interligon kun la domo de David, se la Eternulo punos la malamikojn de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Kaj Jonatan plue ĵuris al David pri sia amo al li, ĉar li amis lin kiel sian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Kaj Jonatan diris al li: Morgaŭ estos komenco de monato, kaj oni demandos pri vi, ĉar oni rimarkos vian sidlokon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'En la tria tago rapidu kaj venu al la loko, kie vi kaŝis vin dum la labora tago, kaj vi sidos apud la ŝtono Ezel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Kaj mi pafos preter ĝin tri sagojn, kvazaŭ pafante al celo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'Kaj poste mi sendos junulon, dirante: Iru, trovu la sagojn. Se mi diros al la junulo: Jen la sagoj estas antaŭ vi, prenu ilin kaj venu-tiam estas paco al vi kaj nenio minacas, kiel vivas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Sed se mi tiel diros al la junulo: Jen la sagoj estas post vi malproksime-tiam foriru, ĉar la Eternulo vin forsendas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Kaj koncerne tion, kion parolis inter ni mi kaj vi, la Eternulo estu inter mi kaj vi por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'Tiam David kaŝis sin sur la kampo. Kaj kiam estis la monatkomenco, la reĝo sidiĝis al tagmanĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'kaj kiam la reĝo sidiĝis sur sia loko, kiel ĉiufoje, sur la sidloko apud la muro, Jonatan leviĝis, kaj Abner sidiĝis apud Saul, kaj la loko de David restis neokupita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Sed Saul diris nenion en tiu tago, ĉar li pensis: Io okazis al li, verŝajne li estas malpura, li ne puriĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Estis la dua tago de la monatkomenco, kaj la loko de David restis neokupita. Tiam Saul diris al sia filo Jonatan: Kial la filo de Jiŝaj ne venis hieraŭ nek hodiaŭ al la tagmanĝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Kaj Jonatan respondis al Saul: David forte petis min, ke li iru Bet- Leĥemon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'kaj li diris: Forliberigu min, ĉar ni havas en la urbo familian oferadon, kaj mia frato ordonis al mi esti tie; tial nun, se vi estas favora al mi, permesu, ke mi rapidu tien kaj ke mi vidu miajn fratojn. Tial li ne venis al la tablo de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Tiam ekflamis la kolero de Saul kontraŭ Jonatan, kaj li diris al li: Ho, filo de obstina virino! ĉu mi ne scias, ke vi elektis al vi la filon de Jiŝaj, por via malhonoro kaj por la malhonoro de via patrino?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Ĉar tiel longe, kiel la filo de Jiŝaj vivos sur la tero, ne fortikiĝos vi nek via regno. Nun sendu, kaj venigu lin al mi, ĉar li meritas la morton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Sed Jonatan respondis al sia patro Saul kaj diris al li: Pro kio oni mortigu lin? kion li faris?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Tiam Saul ĵetis sur lin la lancon, por frapi lin. Tiam Jonatan komprenis, ke ĉe lia patro ĝi estas afero decidita, mortigi Davidon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Kaj Jonatan en forta kolero levis sin de ĉe la tablo; kaj li nenion manĝis en tiu dua tago de la monatkomenco; ĉar li malĝojis pro David, ke lia patro tiel insultis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'En la sekvanta mateno Jonatan eliris sur la kampon en la tempo interkonsentita kun David, kaj malgranda knabo estis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Kaj li diris al sia knabo: Kuru, trovu la sagojn, kiujn mi pafas. La knabo kuris, kaj li pafĵetis la sagon malproksime trans lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Kiam la knabo venis al la loko, kien Jonatan pafĵetis la sagon, Jonatan ekkriis al la junulo, dirante: La sago kuŝas ja post vi malproksime.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Kaj Jonatan kriis al la knabo: Tuj, rapidu, ne staru. Kaj la knabo de Jonatan kolektis la sagojn kaj venis al sia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Kaj la knabo nenion sciis; nur Jonatan kaj David sciis la aferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Jonatan fordonis siajn armilojn al la knabo, kiu estis ĉe li, kaj diris al li: Iru, portu en la urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Kiam la knabo foriris, David leviĝis de la suda flanko, ĵetis sin vizaĝaltere, kaj salutis tri fojojn; kaj ili kisis sin reciproke, kaj ploris ambaŭ kune, sed David pli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Kaj Jonatan diris al David: Iru en paco, kiel ni ĵuris ambaŭ per la nomo de la Eternulo, dirante: La Eternulo estu inter mi kaj vi, inter mia idaro kaj via idaro eterne. Kaj li leviĝis kaj foriris, kaj Jonatan venis en la urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Kaj David venis en Nobon al la pastro Aĥimeleĥ, kaj Aĥimeleĥ time eliris renkonte al David, kaj diris al li: Kial vi estas sola kaj neniu estas kun vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'Kaj David respondis al la pastro Aĥimeleĥ: La reĝo ion komisiis al mi, kaj diris al mi: Neniu ion sciu pri la afero, por kiu mi sendas vin kaj kiun mi komisiis al vi; tial por miaj junuloj mi destinis lokon tian kaj tian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Nun kion vi havas sub la mano? donu en mian manon kvin panojn, aŭ tion, kio troviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Kaj la pastro respondis al David kaj diris: Simplan panon mi ne havas sub mia mano, estas nur pano sankta, se la junuloj nur detenis sin de virinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'Tiam David respondis al la pastro kaj diris al li: Virinoj estas for de ni de hieraŭ kaj antaŭhieraŭ, de la momento, kiam mi eliris, kaj la apartenaĵoj de la junuloj estas sanktaj; se la vojo estas malsankta, ĝi ankoraŭ hodiaŭ sanktiĝos per la apartenaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Tiam la pastro donis al li la sanktaĵon, ĉar ne estis tie pano krom la panoj de propono, kiuj estis forprenitaj de antaŭ la Eternulo, por meti varman panon post la formeto de tiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Tie unu el la servantoj de Saul estis enŝlosita en tiu tago antaŭ la Eternulo; lia nomo estis Doeg la Edomido, la ĉefa el la paŝtistoj de Saul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'Kaj David diris al Aĥimeleĥ: Ĉu vi ne havas sub via mano lancon aŭ glavon? ĉar nek mian glavon, nek miajn aliajn batalilojn mi prenis kun mi, ĉar la afero de la reĝo estis urĝa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Tiam la pastro diris: La glavo de Goljat, la Filiŝto, kiun vi mortigis en la valo de Ela, jen ĝi estas, envolvita en vesto, malantaŭ la efodo. Se vi volas preni ĝin al vi, prenu, ĉar ne haviĝas alia krom ĉi tiu. Kaj David diris: Ne ekzistas simila al ĝi, donu ĝin al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Kaj David leviĝis kaj forkuris en tiu tago de Saul, kaj venis al Aĥiŝ, reĝo de Gat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Kaj la servantoj de Aĥiŝ diris al li: Tio estas ja David, reĝo de la lando! pri li oni ja kantis, dancante, kaj dirante: Saul frapis milojn, Kaj David dekmilojn!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'David metis tiujn vortojn en sian koron, kaj tre ektimis Aĥiŝon, la reĝon de Gat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Tial li ŝanĝis sian aspekton antaŭ iliaj okuloj, furiozis inter iliaj manoj, desegnis sur la pordoj de la pordego, kaj fluigis salivon sur sian barbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Tiam Aĥiŝ diris al siaj servantoj: Vi vidas ja, ke ĉi tiu homo estas freneza; kial do vi venigis lin al mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Ĉu mankas al mi frenezuloj, ke vi alkondukis ĉi tiun, ke li faru frenezaĵojn antaŭ mi? ĉu tia povas eniri en mian domon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'Kaj David foriris de tie, kaj saviĝis en la kaverno Adulam. Kiam tion aŭdis liaj fratoj kaj la tuta domo de lia patro, ili venis al li tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Kaj kolektiĝis al li ĉiuj viroj premataj, ŝulduloj, afliktitoj, kaj li fariĝis ilia estro; ili estis kun li ĉirkaŭ kvarcent viroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Kaj de tie David iris en Micpen de Moab, kaj li diris al la reĝo de Moab: Permesu al mia patro kaj al mia patrino resti ĉe vi, ĝis mi ekscios, kion faros al mi Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Kaj li alkondukis ilin al la reĝo de Moab, kaj ili restis ĉe li la tutan tempon, kiun David estis en la fortikaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Sed la profeto Gad diris al David: Ne restu en la fortikaĵo; iru kaj venu en la landon de Jehuda. Kaj David iris kaj venis en la arbaron Ĥeret.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Saul aŭdis, ke aperis David kaj la viroj, kiuj estis kun li. Saul tiam sidis en Gibea sub la tamarisko sur la altaĵo, kaj lia lanco estis en lia mano, kaj ĉiuj liaj servantoj staris apud li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'Kaj Saul diris al siaj servantoj, kiuj staris apud li: Aŭskultu, idoj de Benjamen: ĉu al ĉiuj el vi la filo de Jiŝaj donos kampojn kaj vinberĝardenojn? ĉu vin ĉiujn li faros milestroj kaj centestroj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'ĉar vi ĉiuj faris konspiron kontraŭ mi, kaj neniu sciigis al miaj oreloj, ke mia filo faris interligon kun la filo de Jiŝaj, kaj neniu el vi kompatas min kaj sciigis al miaj oreloj, ke mia filo instigis mian sklavon kontraŭ mi, por fari insidon, kiel nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Tiam respondis Doeg la Edomido, kiu staris kun la servantoj de Saul, kaj li diris: Mi vidis, ke la filo de Jiŝaj venis en Nobon al Aĥimeleĥ, filo de Aĥitub.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Kaj ĉi tiu demandis pri li la Eternulon, kaj donis al li manĝaĵon, kaj ankaŭ la glavon de la Filiŝto Goljat li donis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Tiam la reĝo sendis voki la pastron Aĥimeleĥ, filo de Aĥitub, kaj la tutan domon de lia patro, la pastrojn, kiuj estis en Nob, kaj ili ĉiuj venis al la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Kaj Saul diris: Aŭskultu, filo de Aĥitub! Kaj ĉi tiu respondis: Jen mi estas, mia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Kaj Saul diris al li: Kial vi faris konspiron kontraŭ mi, vi kaj la filo de Jiŝaj, kiam vi donis al li panon kaj glavon, kaj demandis pri li Dion, por ke li leviĝu kontraŭ mi inside, kiel nun?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Kaj Aĥimeleĥ respondis al la reĝo kaj diris: Kiu do el ĉiuj viaj servantoj estas tiel fidela, kiel David, kiu estas bofilo de la reĝo kaj fervore vin obeas kaj estas estimata en via domo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'ĉu hodiaŭ mi komencis demandi pri li Dion? neniel mi tion farus! la reĝo ne kulpigu pri tio sian sklavon, nek la tutan domon de mia patro; ĉar via sklavo sciis pri ĉio ĉi tio nenion malgrandan nek grandan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Sed la reĝo diris: Vi devas morti, Aĥimeleĥ, vi kaj la tuta domo de via patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Kaj la reĝo diris al la kuristoj, kiuj staris apud li: Turnu vin kaj mortigu la pastrojn de la Eternulo, ĉar ili estas en interkonsento kun David; ili sciis, ke li estas forkurinto, kaj tamen ili ne raportis al mi. Sed la servantoj de la reĝo ne volis levi siajn manojn, por frapi la pastrojn de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Tiam la reĝo diris al Doeg: Turnu vin vi kaj frapu la pastrojn. Kaj Doeg la Edomido sin turnis kaj frapis la pastrojn, kaj mortigis en tiu tago okdek kvin virojn, kiuj portis linajn efodojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Kaj Nobon, la urbon de la pastroj, li frapis per la akraĵo de la glavo, la virojn kaj virinojn, infanojn kaj suĉinfanojn, bovojn kaj azenojn kaj ŝafojn, ĉion per la akraĵo de la glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Sed forsaviĝis unu filo de Aĥimeleĥ, filo de Aĥitub; lia nomo estis Ebjatar; li forkuris al David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Kaj Ebjatar rakontis al David, ke Saul mortigis la pastrojn de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'Tiam David diris al Ebjatar: Mi sciis en tiu tago, kiam tie estis Doeg la Edomido, ke li certe raportos al Saul; mi estas kulpa pri ĉiuj animoj de via patrodomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Restu ĉe mi, ne timu; ĉar kiu serĉos mian animon, tiu serĉos ankaŭ vian animon; sed vi estos gardata ĉe mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Oni raportis al David la sciigon: Jen la Filiŝtoj militas kontraŭ Keila kaj prirabas la draŝejojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Tiam David demandis la Eternulon, dirante: Ĉu mi iru kaj frapu tiujn Filiŝtojn? Kaj la Eternulo diris al David: Iru kaj frapu la Filiŝtojn, kaj savu Keilan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Sed la viroj de David diris al li: Jen ĉi tie en Judujo ni timas; kiel do estos, kiam ni iros al Keila, al la taĉmentoj de la Filiŝtoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Tiam David denove demandis la Eternulon, kaj la Eternulo respondis al li, dirante: Leviĝu, iru al Keila, ĉar Mi transdonos la Filiŝtojn en viajn manojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Kaj David kun siaj viroj iris al Keila kaj batalis kontraŭ la Filiŝtoj kaj forpelis iliajn brutojn kaj frapis ilin per granda frapo; tiamaniere David savis la loĝantojn de Keila.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Kiam Ebjatar, filo de Aĥimeleĥ, forkuris al David en Keilan, li kunportis kun si efodon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Oni raportis al Saul, ke David venis en Keilan. Tiam Saul diris: Dio transdonis lin en mian manon, ĉar li estas enŝlosita, enirinte en urbon, kiu havas pordojn kaj riglilojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Kaj Saul kunvokigis la tutan popolon por milito, por iri al Keila, por sieĝi Davidon kaj liajn virojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Kiam David eksciis, ke Saul intencas malbonon kontraŭ li, li diris al la pastro Ebjatar: Donu la efodon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Kaj David diris: Ho Eternulo, Dio de Izrael, Via sklavo aŭdis, ke Saul intencas veni al Keila, por pereigi la urbon pro mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Ĉu transdonos min la loĝantoj de Keila en lian manon? ĉu venos ĉi tien Saul, kiel aŭdis Via sklavo? Ho Eternulo, Dio de Izrael, diru tion al Via sklavo! Kaj la Eternulo diris: Li venos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Kaj David diris: Ĉu la loĝantoj de Keila transdonos min kaj miajn homojn en la manon de Saul? Kaj la Eternulo diris: Ili transdonos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Tiam leviĝis David kun siaj viroj, ĉirkaŭ sescent homoj, kaj eliris el Keila, kaj iris, kien ili povis iri. Kaj al Saul oni raportis, ke David foriĝis el Keila, kaj tial li decidis ne eliri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'Sed David restis en la dezerto en nealirebla loko, kaj li restis sur la monto en la dezerto Zif. Saul ĉiam serĉis lin, sed Dio ne transdonis lin en lian manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'David vidis, ke Saul eliris, por serĉi lian animon; kaj David estis en la dezerto Zif, inter arbetaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Kaj leviĝis Jonatan, filo de Saul, kaj iris al David en la arbetaĵojn, kaj kuraĝigis lin per la nomo de Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'kaj diris al li: Ne timu, ĉar ne atingos vin la mano de mia patro Saul; kaj vi reĝos super Izrael, kaj mi estos la dua post vi, kaj eĉ mia patro Saul tion bone scias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'Kaj ili ambaŭ faris interligon antaŭ la Eternulo; kaj David restis en la arbetaĵaro, kaj Jonatan iris al sia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Dume Zifanoj venis al Saul en Gibean, kaj diris: David sin kaŝas ĉe ni en nealirebla loko, inter arbetaĵoj, sur la monteto Ĥaĥila, kiu estas sude de la dezerto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'kaj nun laŭ la tuta deziro de via koro, ho reĝo, iru tien, kaj ni transdonos lin en la manon de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Kaj Saul diris: La Eternulo benu vin pro tio, ke vi kompatis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Iru, mi petas, informiĝu ankoraŭ, kaj ekkonu kaj rigardu lian lokon, kie paŝas lia piedo, kaj kiu lin tie vidis; ĉar oni diris al mi, ke li estas tre ruza.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Kaj rigardu kaj eksciu ĉiujn kaŝejojn, kie li sin kaŝas, kaj revenu al mi kun certeco, kaj tiam mi iros kun vi. Se li troviĝas en la lando, mi serĉos lin en ĉiuj milejoj de Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Ili leviĝis kaj iris en Zifon antaŭ Saul. Sed David kaj liaj homoj estis en la dezerto Maon, sur la ebenaĵo sude de la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Kiam Saul kun siaj homoj iris, por serĉi, oni sciigis Davidon, kaj li malsupreniris al la roko kaj restis en la dezerto Maon. Kaj kiam Saul aŭdis tion, li postkuris Davidon en la dezerto Maon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Saul iris sur unu flanko de la monto, kaj David kun siaj homoj sur la dua flanko. David rapidis foriri de Saul, kaj Saul kun siaj homoj penis ĉirkaŭi Davidon kaj liajn homojn, por kapti ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'Sed venis sendito al Saul, kaj diris: Rapide iru, ĉar la Filiŝtoj atakis la landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Tiam Saul ĉesis postkuri Davidon, kaj iris kontraŭ la Filiŝtojn; tial oni donis al tiu loko la nomon Roko de Disiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, 'Kaj David leviĝis de tie, kaj ekloĝis sur nealirebla loko de En-Gedi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'Kiam Saul revenis de sia iro kontraŭ la Filiŝtoj, oni raportis al li, dirante: Jen David estas en la dezerto En-Gedi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Tiam Saul prenis tri mil virojn, elektitajn el la tuta Izrael, kaj iris serĉi Davidon kaj liajn homojn sur la rokoj de la ibeksoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Kaj li venis al la baraĵoj de la ŝafoj ĉe la vojo; tie estis kaverno; kaj Saul eniris tien por natura bezono. Kaj David kun siaj homoj estis en la profundo de la kaverno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Tiam la homoj de David diris al li: Jen estas la tago, pri kiu la Eternulo diris al vi: Jen Mi transdonos vian malamikon en viajn manojn, por ke vi faru al li tion, kio plaĉos al vi. Sed David leviĝis, kaj nerimarkite detranĉis anguleton de la vesto de Saul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Tamen post tio la koro de David ekbatis en li pro tio, ke li detranĉis la vestanguleton de Saul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Kaj li diris al siaj homoj: La Eternulo gardu min, ke mi ne faru tian faron al mia sinjoro, al la sanktoleito de la Eternulo, etendante mian manon kontraŭ lin; li estas ja sanktoleito de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'Kaj David repuŝis siajn homojn per la vortoj, kaj ne permesis al ili leviĝi kontraŭ Saulon. Kaj Saul leviĝis el la kaverno kaj iris sur la vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Post tio leviĝis David kaj eliris el la kaverno, kaj kriis post Saul jene: Mia sinjoro, ho reĝo! Saul ekrigardis malantaŭen, kaj tiam David klinis sian vizaĝon al la tero kaj adorkliniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'Kaj David diris al Saul: Kial vi aŭskultas la vortojn de homoj, kiuj diras: Jen David serĉas malbonon kontraŭ vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'Jen hodiaŭ viaj okuloj vidis, ke la Eternulo transdonis vin hodiaŭ en mian manon en la kaverno, kaj oni diris, ke mi mortigu vin; sed mi indulgis vin, kaj mi diris: Mi ne etendos mian manon kontraŭ mian sinjoron, ĉar li estas sanktoleito de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Mia patro, rigardu kaj vidu la anguleton de via vesto en mia mano; el tio, ke mi detranĉis la anguleton de via vesto, sed ne mortigis vin, sciu kaj vidu, ke mi ne havas malbonon nek krimon en mia mano kaj mi ne pekis kontraŭ vi; sed vi postkuras mian animon, por preni ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'La Eternulo juĝu inter mi kaj vi, kaj la Eternulo venĝu al vi pro mi; sed mia mano ne estos sur vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Kiel diras antikva proverbo: De malpiuloj eliras malpiaĵo; sed mia mano ne estos sur vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Post kiu eliris la reĝo de Izrael? kiun vi postkuras? malvivan hundon, unu pulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'La Eternulo estu juĝanto kaj juĝu inter mi kaj vi, kaj Li rigardu kaj prizorgu mian proceson kaj defendu min kontraŭ via mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'Kaj kiam David finis la paroladon de tiuj vortoj al Saul, Saul diris: Ĉu tio estas via voĉo, mia filo David? Kaj Saul levis sian voĉon kaj ekploris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'Kaj li diris al David: Vi estas pli justa ol mi; ĉar vi repagis al mi per bono, dum mi repagis al vi per malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'Kaj hodiaŭ vi montris al mi, kiel vi agis bone kun mi; ĉar la Eternulo transdonis min en vian manon, kaj vi ne mortigis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Kiam homo trovas sian malamikon, ĉu li forliberigas lin en bona maniero? La Eternulo repagu al vi per bono pro tio, kion vi hodiaŭ faris al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Kaj jen nun mi eksciis, ke vi fariĝos reĝo, kaj fortikiĝos en via mano la regno de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Ĵuru do al mi per la Eternulo, ke vi ne ekstermos mian idaron post mi kaj vi ne malaperigos mian nomon el la domo de mia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'Kaj David ĵuris al Saul. Tiam Saul foriris al sia domo, kaj David kun siaj homoj iris en la rifuĝejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Samuel mortis; kaj kolektiĝis ĉiuj Izraelidoj, kaj priploris lin kaj enterigis lin en lia domo en Rama. Kaj David leviĝis, kaj foriris en la dezerton Paran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'Estis viro en Maon, kiu havis siajn aferojn en Karmel; tiu homo estis tre potenca, li havis tri mil ŝafojn kaj mil kaprojn. Tiam oni estis tondanta liajn ŝafojn en Karmel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'La nomo de tiu viro estis Nabal, kaj la nomo de lia edzino estis Abigail. La virino estis prudenta kaj belaspekta; sed la viro estis malmola kaj malbona en siaj agoj, kaj li estis Kalebido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'Kiam David aŭdis en la dezerto, ke Nabal tondas siajn ŝafojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'tiam David sendis dek junulojn, kaj David diris al la junuloj: Iru Karmelon, kaj venu al Nabal kaj salutu lin en mia nomo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'kaj diru: Feliĉon al vi! paco estu al vi, paco al via domo, kaj paco al ĉio, kio apartenas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Mi aŭdis, ke oni tondas al vi la ŝafojn. Nu, viaj paŝtistoj estis kun ni, kaj ni ne ofendis ilin, kaj nenio perdiĝis ĉe ili dum la tuta tempo, kiun ili estis en Karmel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Demandu viajn junulojn, kaj ili diros al vi; tial miaj junuloj akiru vian favoron, tiom pli, ke ni venis al festa tago; donu afable, kion trovos via mano, al viaj sklavoj kaj al via filo David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Kaj la servantoj de David iris, kaj diris al Nabal ĉiujn tiujn vortojn en la nomo de David, kaj haltis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Sed Nabal respondis al la servantoj de David, dirante: Kiu estas David? kaj kiu estas la filo de Jiŝaj? nun estas multe da tiaj servantoj, kiuj foriĝis de siaj sinjoroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Ĉu mi prenu mian panon kaj mian akvon, kaj mian viandon, kiun mi buĉigis por miaj tondantoj, kaj mi donu tion al homoj, pri kiuj mi ne scias, de kie ili estas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Kaj la servantoj de David ekiris returne sian vojon, kaj revenis kaj raportis al li ĉiujn tiujn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Tiam David diris al siaj homoj: Zonu ĉiu sian glavon! Kaj ili zonis ĉiu sian glavon, kaj ankaŭ David zonis sian glavon; kaj iris kun David ĉirkaŭ kvarcent viroj, kaj ducent restis ĉe la armilaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Sed al Abigail, edzino de Nabal, unu el la servantoj raportis, dirante: Jen David sendis senditojn el la dezerto, por deziri feliĉon al nia sinjoro, sed li forofendis ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'kaj tiuj homoj estis tre bonaj por ni, kaj ili ne ofendis nin, kaj nenio perdiĝis ĉe ni dum la tuta tempo, kiun ni iradis kun ili, estante sur la kampo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'muro ili estis por ni kiel en la nokto, tiel en la tago, la tutan tempon, kiun ni estis kun ili, paŝtante la ŝafojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'tial nun pripensu kaj rigardu, kion vi devas fari, ĉar decidita estas malbono kontraŭ nia sinjoro kaj kontraŭ lia tuta domo; kaj li estas ja malhumila homo, oni ne povas paroli kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Tiam Abigail rapide prenis ducent panojn kaj du felsakojn da vino kaj kvin pretigitajn ŝafojn kaj kvin mezurojn da rostitaj grajnoj kaj cent kukojn sekvinberajn kaj ducent kukojn figajn, kaj metis ĉion sur azenojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'Kaj ŝi diris al siaj servantoj: Iru antaŭ mi, jen mi venas post vi. Sed al sia edzo Nabal ŝi nenion diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'Dum ŝi estis rajdanta sur la azeno kaj malleviĝanta al la bazo de la monto, jen David kun siaj homoj malleviĝas renkonte al ŝi, kaj ŝi renkontiĝis kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'Dume David estis dirinta: Nur vane mi gardis la apartenaĵon de tiu homo en la dezerto, ke nenio perdiĝis el lia havo; li repagis al mi malbonon pro bono;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'tiel Dio faru al la malamikoj de David kaj pli: el ĉio, kio apartenas al li, mi restigos ĝis la morgaŭa mateniĝo neniun virseksulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Kiam Abigail ekvidis Davidon, ŝi rapide deiris de la azeno, kaj ĵetis sin antaŭ David vizaĝaltere kaj adorkliniĝis ĝis la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'Kaj ŝi ĵetis sin antaŭ liajn piedojn, kaj diris: Sur mi, mia sinjoro, estas la krimo; permesu, ke via sklavino parolu al viaj oreloj, kaj aŭskultu la vortojn de via sklavino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Mia sinjoro ne atentu tiun malvirtan viron Nabal, ĉar kia estas lia nomo, tia li mem estas: Nabal estas lia nomo, kaj malsaĝecon li havas en si; kaj mi, via sklavino, ne vidis la servantojn de mia sinjoro, kiujn vi sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Kaj nun, mia sinjoro, kiel vivas la Eternulo kaj kiel vivas via animo, la Eternulo retenas vin, ke vi ne falu en sangon kaj ke vi ne helpu vin per via propra mano; nun estu kiel Nabal viaj malamikoj, kaj tiuj, kiuj deziras malbonon al mia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Kaj jen ĉi tiu benaĵo, kiun via sklavino alportis al mia sinjoro; ĝi estu donita al la servantoj, kiuj sekvas mian sinjoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Pardonu, mi petas, la krimon de via sklavino, ĉar la Eternulo aranĝos al mia sinjoro domon fidindan, pro tio, ke mia sinjoro militas la militojn de la Eternulo; kaj malbono neniam estu trovata ĉe vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Se leviĝis homo, por vin persekuti kaj serĉi vian animon, la animo de mia sinjoro tamen estas ĉirkaŭbarita per ĉirkaŭbaro de vivo ĉe la Eternulo, via Dio; sed la animo de viaj malamikoj estos forĵetita kvazaŭ per ĵetilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'Kiam la Eternulo faros al mia sinjoro ĉion bonan, kiun Li promesis, kaj faros vin estro super Izrael,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'tiam ĉi tio ne estu por vi puŝiĝilo nek korfalilo por mia sinjoro, se vi verŝos sangon senkaŭze kaj se mia sinjoro helpos sin mem. Tiam la Eternulo faros bonon al mia sinjoro, kaj vi rememoros vian sklavinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Tiam David diris al Abigail: Benata estu la Eternulo, Dio de Izrael, kiu sendis vin hodiaŭ al mi renkonte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Kaj benata estu via elokventeco, kaj benata estu vi, kiu malhelpis min hodiaŭ de enfalo en sangon kaj de helpado al mi per mia propra mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Sed kiel vivas la Eternulo, Dio de Izrael, kiu malhelpis min fari al vi malbonon: se vi ne rapidus kaj ne venus al mi renkonte, ĝis la mateniĝo restus ĉe Nabal neniu virseksulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'Kaj David prenis el ŝia mano tion, kion ŝi alportis al li, kaj li diris al ŝi: Iru pace al via domo; vidu, mi aŭskultis vian voĉon kaj honoris vian vizaĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Kiam Abigail venis al Nabal, jen li havis festenon en sia domo, kiel festeno de reĝo, kaj la koro de Nabal estis gaja en li, kaj li estis tre ebria; sed ŝi diris al li nenion malgrandan nek grandan ĝis la mateniĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Matene, kiam la vino eliris el Nabal, lia edzino rakontis al li tion, kio okazis; tiam rigidiĝis en li lia koro, kaj li fariĝis kiel ŝtono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'Post dek tagoj la Eternulo frapis Nabalon, kaj li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Kiam David aŭdis, ke Nabal mortis, li diris: Benata estu la Eternulo, kiu juĝe punis pro la malhonoro, kiun mi havis de Nabal, kaj Sian sklavon Li detenis de malbono, kaj la malbonecon de Nabal la Eternulo returnis sur lian kapon. Kaj David sendis kaj paroligis al Abigail, ke li volas preni ŝin al si kiel edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Kaj venis la servantoj de David al Abigail en Karmelon, kaj diris al ŝi jene: David sendis nin al vi, por preni vin al li kiel edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Tiam ŝi leviĝis, kaj kliniĝis kun la vizaĝo ĝis la tero, kaj diris: Jen via sklavino estas servantino, por lavi la piedojn de la servantoj de mia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Kaj Abigail rapide leviĝis kaj ekrajdis sur azeno, kaj ŝiaj kvin servantinoj ekiris post ŝi, kaj ŝi sekvis la senditojn de David kaj fariĝis lia edzino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'Ankaŭ Aĥinoamon el Jizreel David prenis, kaj ili ambaŭ fariĝis liaj edzinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Sed Saul fordonis sian filinon Miĥal, edzinon de David, al Palti, filo de Laiŝ, el Galim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Venis la Zifanoj al Saul en Gibean, kaj diris: David ja kaŝas sin sur la monteto Ĥaĥila, kiu estas antaŭ la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Tiam Saul leviĝis kaj ekiris al la dezerto Zif, kaj kun li estis tri mil viroj elektitaj el Izrael, por serĉi Davidon en la dezerto Zif.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'Kaj Saul starigis sian tendaron sur la monteto Ĥaĥila, kiu estas antaŭ la dezerto, apud la vojo. Kaj David estis en la dezerto, kaj vidis, ke Saul venis en la dezerton, por lin serĉi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'Kaj David sendis esplorrigardantojn, kaj konvinkiĝis, ke Saul efektive venis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Tiam David leviĝis, kaj venis al la loko, kie staris tendare Saul, kaj David rigardis la lokon, kie kuŝis Saul, kaj Abner, filo de Ner, lia militestro. Saul kuŝis en la centro de la tendaro, kaj la tuta popolo ĉirkaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'Kaj David ekparolis kaj diris al Aĥimeleĥ la Ĥetido, kaj al Abiŝaj, filo de Ceruja, frato de Joab, jene: Kiu iros kun mi al Saul en la tendaron? Kaj Abiŝaj diris: Mi iros kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'Kaj David kaj Abiŝaj venis al la popolo nokte; kaj jen Saul kuŝas kaj dormas en la centro de la tendaro, kaj lia lanco estas enfiksita en la tero apud lia kaploko, kaj Abner kaj la popolo kuŝas ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Tiam Abiŝaj diris al David: Dio transdonis hodiaŭ vian malamikon en viajn manojn; nun permesu, ke mi trapiku lin per la lanco al la tero unu fojon; duan fojon mi tion ne faros al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Sed David diris al Abiŝaj: Ne pereigu lin; ĉar kiu povas senpune etendi sian manon kontraŭ la sanktoleiton de la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Kaj David diris: Mi ĵuras per la Eternulo, ke nur la Eternulo lin frapos; aŭ venos lia tago kaj li mortos, aŭ li iros en militon kaj pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'La Eternulo gardu min, ke mi ne etendu mian manon kontraŭ sanktoleiton de la Eternulo! nun prenu la lancon, kiu estas apud lia kaploko, kaj la vazon kun la akvo, kaj ni foriru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Kaj David prenis la lancon kaj la vazon kun la akvo de la kaploko de Saul, kaj ili foriris; kaj neniu vidis, neniu rimarkis, kaj neniu vekiĝis, sed ĉiuj dormis; ĉar dormego venanta de la Eternulo falis sur ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Kaj David transiris sur la alian flankon, kaj stariĝis sur la supro de la monto, malproksime, tiel ke granda interspaco estis inter ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'Kaj David ekkriis al la popolo, kaj al Abner, filo de Ner, jene: Ĉu vi ne respondos, Abner? Kaj Abner respondis kaj diris: Kiu vi estas, kiu krias kontraŭ la reĝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'Tiam David diris al Abner: Ĉu vi ne estas viro? kaj kiu estas egala al vi en Izrael? kial do vi ne gardis vian sinjoron, la reĝon? ĉar venis unu el la popolo, por pereigi la reĝon, vian sinjoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Ne bona estas tio, kion vi faris. Kiel vivas la Eternulo, vi meritas la morton pro tio, ke vi ne gardis vian sinjoron, la sanktoleiton de la Eternulo. Nun rigardu, kie estas la lanco de la reĝo, kaj la vazo kun la akvo, kiu estis apud lia kaploko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Tiam Saul rekonis la voĉon de David, kaj diris: Ĉu tio estas via voĉo, mia filo David? Kaj David diris: Ĝi estas mia voĉo, mia sinjoro, ho reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Kaj li diris plue: Kial mia sinjoro persekutas sian sklavon? kion mi faris? kaj kia malbono estas en mia mano?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Nun mia sinjoro la reĝo volu aŭskulti la vortojn de sia sklavo: se la Eternulo incitas vin kontraŭ mi, ekodoru farunofero; sed se homoj, tiam ili estu malbenitaj antaŭ la Eternulo; ĉar ili elpelis min nun, ke mi ne partoprenu en la heredaĵo de la Eternulo, kaj ili diras: Iru, servu al aliaj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Nun mia sango ne falu sur la teron malproksime de la vizaĝo de la Eternulo; la reĝo de Izrael eliris ja, por serĉi iun pulon, kiel oni postkuras perdrikon en la montoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Tiam Saul diris: Mi pekis; revenu, mia filo David, ĉar mi ne plu faros al vi malbonon, pro tio, ke mia animo estis kara antaŭ viaj okuloj hodiaŭ. Jen mi agis malsaĝe kaj tre multe eraris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'Kaj David respondis kaj diris: Jen estas la lanco de la reĝo; unu el la servantoj venu kaj prenu ĝin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'kaj la Eternulo repagu al ĉiu laŭ lia justeco kaj fideleco. La Eternulo transdonis vin hodiaŭ en miajn manojn, sed mi ne volis etendi mian manon kontraŭ sanktoleiton de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'Jen, kiel via animo havis hodiaŭ grandan valoron en miaj okuloj, tiel mia animo havu grandan valoron en la okuloj de la Eternulo, kaj Li savu min de ĉia mizero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Kaj Saul diris al David: Benata vi estu, mia filo David; vi faros vian faron, kaj vi venkos. Kaj David iris sian vojon, kaj Saul reiris al sia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'Tamen David diris al si mem: Mi povas enfali iun tagon en la manon de Saul; estas por mi nenio pli bona, ol ke mi forkuru en la landon de la Filiŝtoj, por ke Saul ĉesu serĉi min plu en la regionoj de Izrael, kaj por ke mi saviĝu kontraŭ lia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Kaj David leviĝis kaj transiris, li kaj la sescent viroj, kiuj estis kun li, al Aĥiŝ, filo de Maoĥ, reĝo de Gat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'Kaj David ekloĝis ĉe Aĥiŝ en Gat, li kaj liaj viroj, ĉiu kun sia domo, David kun siaj du edzinoj, Aĥinoam, la Jizreelanino, kaj Abigail, edzino de Nabal, la Karmelanino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Kiam oni raportis al Saul, ke David forkuris en Gaton, li ne plu serĉis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'Kaj David diris al Aĥiŝ: Se mi akiris vian favoron, oni donu al mi, mi petas, lokon en unu el la urboj de la kamparo, por ke mi ekloĝu tie; por kio via sklavo loĝu en via reĝa urbo kune kun vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Kaj Aĥiŝ donis al li en tiu tago Ciklagon; pro tio Ciklag fariĝis apartenaĵo de la reĝoj de Judujo ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'La nombro de la tagoj, kiujn David traloĝis en la regiono de la Filiŝtoj, estis unu jaro kaj kvar monatoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'Kaj David kun siaj viroj iris kaj atakis la Geŝuridojn kaj Gezeridojn kaj Amalekidojn, ĉar ili loĝis en tiu lando de antikva tempo ĝis Ŝur kaj ĝis la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'Kiam David venkobatis la landon, li lasis la vivon nek al viroj nek al virinoj, sed prenis ŝafojn kaj bovojn kaj azenojn kaj kamelojn kaj vestojn, kaj reiris kaj venis al Aĥiŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Kiam Aĥiŝ demandis: Ĉu vi ne faris hodiaŭ atakon? David respondis: Sur la sudan regionon de Jehuda, sur la sudan regionon de la Jeraĥmeelidoj, kaj sur la sudan regionon de la Kenidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Nek viron nek virinon David lasis veni viva en Gaton, dirante: Ili ne parolu kontraŭ ni, dirante, ke tiel agis David. Kaj tia estis lia maniero de agado dum la tuta tempo, kiun li loĝis en la regiono de la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Kaj Aĥiŝ fidis Davidon, dirante: Li faris sin abomeninda antaŭ sia popolo Izrael, kaj tial li estos mia sklavo por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'Okazis en tiu tempo, ke la Filiŝtoj kolektis sian militistaron, por militi kontraŭ Izrael. Kaj Aĥiŝ diris al David: Sciu, ke vi iros kun mi en la militon, vi kaj viaj viroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'Kaj David diris al Aĥiŝ: Tial vi ekscios, kion faros via sklavo. Kaj Aĥiŝ diris al David: Mi faros vin por ĉiam mia kapogardisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Dume Samuel mortis, kaj ĉiuj Izraelidoj lin priploris, kaj enterigis lin en Rama, en lia urbo. Kaj Saul estis eksterminta el la lando ĉiujn sorĉistojn kaj aŭguristojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Kiam la Filiŝtoj kolektiĝis, kaj venis kaj stariĝis tendare en Ŝunem, tiam Saul kolektis ĉiujn Izraelidojn, kaj ili stariĝis tendare en Gilboa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Kiam Saul ekvidis la tendaron de la Filiŝtoj, li ektimis, kaj lia koro forte ektremis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Kaj Saul petis konsilon ĉe la Eternulo, sed la Eternulo ne respondis al li per sonĝoj, nek per la signoj de lumo, nek per profetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Tiam Saul diris al siaj servantoj: Elserĉu al mi virinon, kiu povoscias aŭguri, por ke mi iru al ŝi kaj ricevu de ŝi informojn. Kaj liaj servantoj diris: Jen ekzistas en En-Dor virino, kiu povoscias aŭguri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Tiam Saul ŝanĝis siajn vestojn, metis sur sin aliajn vestojn, kaj iris kune kun du viroj, kaj ili venis al la virino nokte. Kaj li diris: Aŭguru al mi, mi petas, per via aŭgura povoscio, kaj elvoku al mi tiun, pri kiu mi diros al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Sed la virino diris al li: Vi scias ja, kion faris Saul, kiu ekstermis la sorĉistojn kaj la aŭguristojn el la lando; kial do vi volas retkapti mian animon, por pereigi min?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Tiam Saul ĵuris al ŝi per la Eternulo, dirante: Kiel vivas la Eternulo, ne trafos vin puno pro ĉi tiu afero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Kaj la virino diris: Kiun mi elvoku al vi? Kaj li diris: Samuelon elvoku al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Kiam la virino ekvidis Samuelon, ŝi ekkriis per laŭta voĉo; kaj la virino diris al Saul: Kial vi min trompis? vi estas ja Saul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Sed la reĝo diris al ŝi: Ne timu; kion vi vidis? Kaj la virino diris al Saul: Iun dian mi vidis leviĝantan el la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Kaj li diris al ŝi: Kia estas lia aspekto? Kaj ŝi diris: Leviĝas viro maljuna, kaj li estas vestita per pastra tuniko. Tiam Saul komprenis, ke tio estas Samuel; kaj li klinis sin kun la vizaĝo ĝis la tero, kaj faris adorsaluton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Tiam Samuel diris al Saul: Kial vi maltrankviligis min, elvokante min supren? Kaj Saul respondis: Mi estas en tre premita stato; la Filiŝtoj militas kontraŭ mi, kaj Dio forturnis Sin de mi kaj jam ne respondas al mi per profetoj nek per sonĝoj; tial mi vokis vin, por ke vi sciigu al mi, kion mi devas fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Sed Samuel diris: Kial do vi demandas min, se la Eternulo forturnis Sin de vi kaj transiris al via konkuranto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Kaj la Eternulo faros al li, kion Li diris per mi; kaj la Eternulo elŝiros la regnon el viaj manoj kaj donos ĝin al via proksimulo David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Ĉar vi ne aŭskultis la voĉon de la Eternulo kaj ne plenumis Lian flaman koleron kontraŭ Amalek, tial ĉi tion faris hodiaŭ la Eternulo al vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'kaj la Eternulo transdonos kune kun vi ankaŭ Izraelon en la manojn de la Filiŝtoj; kaj morgaŭ vi kaj viaj filoj estos kun mi; ankaŭ la tendaron de Izrael la Eternulo transdonos en la manojn de la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Tiam Saul tuj falis laŭ sia tuta longeco sur la teron, ĉar li tre ektimis pro la vortoj de Samuel; ankaŭ forton li ne havis en si, ĉar li nenion manĝis la tutan tagon kaj la tutan nokton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Kiam la virino aliris al Saul, kaj vidis, ke li estas tre konsternita, ŝi diris al li: Jen via sklavino obeis vian voĉon, kaj mi metis en danĝeron mian animon, kaj obeis la vortojn, kiujn vi diris al mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'nun mi petas, aŭskultu ankaŭ vi la voĉon de via sklavino, kaj mi metos antaŭ vin pecon da pano, kaj vi manĝu, por ke vi havu forton, kiam vi iros la vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Sed li rifuzis, kaj diris: Mi ne manĝos. Sed kiam insistis super li liaj servantoj kaj ankaŭ la virino, li obeis ilian voĉon, leviĝis de la tero, kaj sidiĝis sur lito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'La virino havis en la domo grasigitan bovidon; ŝi rapide ĝin buĉis, kaj ŝi prenis farunon, knedis ĝin, kaj bakis el ĝi macojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Kaj ŝi alportis tion antaŭ Saulon kaj antaŭ liajn servantojn, kaj ili manĝis; kaj en la sama nokto ili leviĝis kaj foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Dume la Filiŝtoj kolektis sian tutan militistaron en Afek; kaj la Izraelidoj staris tendare apud la fonto, kiu estas en Jizreel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'La estroj de la Filiŝtoj preterpasis kun siaj centoj kaj miloj, kaj David kun siaj viroj preterpasis en la fina parto kun Aĥiŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Kaj la estroj de la Filiŝtoj diris: Por kio estas ĉi tiuj Hebreoj? Sed Aĥiŝ respondis al la estroj de la Filiŝtoj: Tio estas ja David, servanto de Saul, reĝo de Izrael; li estis kun mi kelkan tempon aŭ eĉ jarojn, kaj mi trovis en li nenion de post la tago de la defalo ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Sed ekkoleris kontraŭ li la estroj de la Filiŝtoj, kaj la estroj de la Filiŝtoj diris al li: Reirigu tiun viron, kaj li revenu sur sian lokon, kiun vi destinis por li, sed li ne iru kun ni en la batalon kaj ne fariĝu nia kontraŭulo dum la batalo; ĉar per kio ĉi tiu povus favorigi al si sian sinjoron, se ne per la kapoj de niaj viroj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Ĉu tio ne estas ja tiu David, pri kiu oni kantis en la dancrondoj jene: Saul frapis milojn, Kaj David dekmilojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Tiam Aĥiŝ alvokis Davidon, kaj diris al li: Kiel vivas la Eternulo, vi estas honesta, kaj plaĉas al mi via agado kun mi en la tendaro; mi ne trovis en vi malbonon de post la tago de via veno al mi ĝis hodiaŭ; sed al la estroj vi ne plaĉas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Reiru do nun kaj iru en paco, por ke vi ne faru ion ne plaĉan al la estroj de la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'Sed David diris al Aĥiŝ: Kion mi faris, kaj kion vi trovis en via sklavo de post la tago, kiam mi stariĝis antaŭ vi, ĝis nun, ke mi ne iru kaj ne batalu kontraŭ la malamikoj de mia sinjoro la reĝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Kaj Aĥiŝ respondis kaj diris al David: Mi scias, ke vi estas bona antaŭ miaj okuloj, kiel anĝelo de Dio; sed la estroj de la Filiŝtoj diras: Li ne iru kun ni en la batalon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Leviĝu do frue matene kun la servantoj de via sinjoro, kiuj venis kun vi; leviĝu frue matene kaj, kiam vi havos lumon, foriru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Kaj David, li mem kaj liaj viroj, leviĝis frue, por iri matene, por reveni en la landon de la Filiŝtoj; kaj la Filiŝtoj direktis sin al Jizreel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Kiam David kaj liaj viroj venis en Ciklagon en la tria tago, la Amalekidoj estis atakintaj la sudan regionon kaj Ciklagon, venkobatintaj Ciklagon kaj forbruligintaj ĝin per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'Ili prenis en malliberecon la virinojn, kiuj estis tie, de la malgrandaj ĝis la grandaj; ili neniun mortigis, sed forkondukis, kaj iris sian vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Kiam David kun siaj viroj venis al la urbo, ili ekvidis, ke ĝi estas forbruligita per fajro, kaj iliaj edzinoj kaj filoj kaj filinoj estas prenitaj en malliberecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Tiam David, kaj la homoj, kiuj estis kun li, levis sian voĉon kaj ekploris, ĝis ili jam ne havis forton por plori.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'La du edzinoj de David ankaŭ estis prenitaj en malliberecon, Aĥinoam, la Jizreelanino, kaj Abigail, edzino de Nabal, la Karmelanino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'Kaj al David estis tre malfacile, ĉar la popolo intencis ŝtonmortigi lin, ĉar tre koleris la tuta popolo, ĉiu pro siaj filoj kaj siaj filinoj. Sed David havis fortan fidon al la Eternulo, sia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'Kaj David diris al Ebjatar, la pastro, filo de Aĥimeleĥ: Volu alporti al mi la efodon; kaj Ebjatar alportis la efodon al David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'Tiam David faris demandon al la Eternulo, dirante: Ĉu mi postkuru tiun amason, kaj ĉu mi ĝin kaptos? Kaj Li diris al li: Postkuru, ĉar vi kaptos kaj vi savos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Kaj David iris, li kaj la sescent viroj, kiuj estis kun li, kaj ili venis al la torento Besor, kaj la postrestintoj haltis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'Kaj postkuris David kun kvarcent viroj; haltis ducent viroj, kiuj estis tro lacaj, por transiri la torenton Besor.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'Kaj ili trovis iun Egipton sur la kampo, kaj ili alkondukis lin al David; oni donis al li panon, kaj li manĝis, kaj oni trinkigis al li akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'Kaj oni donis al li pecon da figa kuko kaj du kuketojn sekvinberajn, kaj li manĝis, kaj revenis al li lia spirito, ĉar antaŭ tio li dum tri tagoj kaj tri noktoj ne manĝis panon kaj ne trinkis akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'Kaj David diris al li: Kies vi estas? kaj de kie vi estas? Kaj li respondis: Mi estas Egipta junulo, mi estas sklavo de unu Amalekido; sed mia sinjoro forlasis min, ĉar mi malsaniĝis antaŭ tri tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Ni atakis la sudan regionon de la Keretidoj kaj la regionon de Jehuda kaj la sudan regionon de Kaleb, kaj Ciklagon ni forbruligis per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'Tiam David diris al li: Ĉu vi kondukos min al tiu amaso? Kaj li respondis: Ĵuru al mi per Dio, ke vi ne mortigos min kaj ne transdonos min en la manon de mia sinjoro; tiam mi kondukos vin al tiu amaso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Kaj li alkondukis lin; kaj jen ili, disĵetitaj sur la tuta landpeco, manĝas kaj trinkas kaj festenas pro la tuta granda militakiro, kiun ili prenis el la lando Filiŝta kaj el la lando Juda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'Kaj David batis ilin de la mateno ĝis la morgaŭa vespero; kaj neniu el ili sin savis, krom kvarcent junaj viroj, kiuj ekrajdis sur la kameloj kaj forkuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'Kaj David savis ĉion, kion prenis la Amalekidoj, kaj siajn du edzinojn David savis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Kaj mankis al ili nenio malgranda nek granda, nek el la filoj nek el la filinoj, nek el la militakiro, nek el ĉio, kion ili prenis al si: ĉion David reprenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'Kaj David prenis ĉiujn ŝafojn kaj bovojn kaj pelis la brutojn antaŭ si, kaj oni diris: Tio estas la militakiro de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Kaj David venis al la ducent viroj, kiuj pro laceco ne povis sekvi Davidon kaj estis restigitaj ĉe la torento Besor. Kaj ili eliris renkonte al David, kaj al la popolo, kiu estis kun li. Kaj David aliris al tiuj homoj kaj afable salutis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Tiam kelkaj malbonaj kaj sentaŭgaj el la viroj, kiuj iris kun David, ekparolis kaj diris: Pro tio, ke ili ne iris kun ni, ni ne donu al ili ion el la militakiro, kiun ni reprenis; nur al ĉiu lian edzinon kaj liajn gefilojn; ili prenu kaj iru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Sed David diris: Ne agu tiel, miaj fratoj, kun tio, kion donis al ni la Eternulo, kiu konservis nin, kaj transdonis en niajn manojn la amason, kiu atakis nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Kaj kiu aŭskultos vin en tiu afero? ĉar la parto de tiu, kiu iris en la batalon, devas esti tia sama, kiel de tiu, kiu restis ĉe la ĉararo; egale devas esti dividite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'Tiel estis de post tiu tago; kaj li starigis tion kiel leĝon kaj moron en Izrael ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'Kiam David venis en Ciklagon, li sendis iom el la militakiro al la Judaj plejaĝuloj, al siaj amikoj, dirante: Jen akceptu donacon el la militakiro de la malamikoj de la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'al tiuj, kiuj estis en Bet-El, kaj al tiuj, kiuj estis en la suda Ramot, kaj al tiuj, kiuj estis en Jatir,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'kaj al tiuj, kiuj estis en Aroer, kaj al tiuj, kiuj estis en Sifmot, kaj al tiuj, kiuj estis en Eŝtemoa,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'kaj al tiuj, kiuj estis en Raĥal, kaj al tiuj, kiuj estis en la urboj de la Jeraĥmeelidoj, kaj al tiuj, kiuj estis en la urboj de la Kenidoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'kaj al tiuj, kiuj estis en Ĥorma, kaj al tiuj, kiuj estis en Kor- Aŝan, kaj al tiuj, kiuj estis en Ataĥ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'kaj al tiuj, kiuj estis en Ĥebron, kaj en ĉiuj lokoj, en kiuj estis vaginta David kun siaj viroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Dume la Filiŝtoj batalis kontraŭ Izrael; kaj la Izraelidoj forkuris de la Filiŝtoj kaj falis mortigitaj sur la monto Gilboa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Kaj la Filiŝtoj kuratingis Saulon kaj liajn filojn, kaj la Filiŝtoj mortigis Jonatanon kaj Abinadabon kaj Malki-Ŝuan, filojn de Saul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'La batalo fortiĝis kontraŭ Saul; kaj la arkpafistoj trovis lin, kaj li estis forte vundita de la arkpafistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Tiam Saul diris al sia armilportisto: Eltiru vian glavon kaj trapiku min per ĝi, por ke ne venu tiuj necirkumciditoj, por trapiki min kaj mokmalhonori min. Sed lia armilportisto ne volis, ĉar li forte timis. Tiam Saul prenis sian glavon kaj faligis sin sur ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Kiam lia armilportisto vidis, ke Saul mortis, li ankaŭ faligis sin sur sian glavon kaj mortis kune kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Tiamaniere mortis Saul kaj liaj tri filoj kaj lia armilportisto kaj ĉiuj liaj viroj en tiu tago kune kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Kiam la Izraelidoj, kiuj estis transe de la valo kaj transe de Jordan, vidis, ke la Izraelidoj forkuras kaj ke Saul kaj liaj filoj mortis, ili forlasis la urbojn kaj forkuris; kaj venis la Filiŝtoj kaj ekloĝis en ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'En la sekvanta tago venis la Filiŝtoj, por senvestigi la mortigitojn; kaj ili trovis Saulon kaj liajn tri filojn falintajn sur la monto Gilboa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Tiam ili dehakis lian kapon kaj deprenis liajn armilojn kaj sendis en la landon de la Filiŝtoj ĉirkaŭen, por anonci en la domo de iliaj idoloj kaj al la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Kaj ili metis liajn armilojn en la templon de Aŝtar, kaj lian korpon ili pendigis sur la muro de Bet-Ŝan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Kiam la loĝantoj de Jabeŝ en Gilead aŭdis pri tio, kion faris la Filiŝtoj al Saul,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'tiam ĉiuj kuraĝuloj leviĝis kaj iris tutan nokton kaj prenis la korpon de Saul kaj la korpojn de liaj filoj de la muro de Bet-Ŝan, kaj venis en Jabeŝon kaj forbruligis ilin tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Kaj ili prenis iliajn ostojn kaj enterigis sub la tamarisko en Jabeŝ, kaj ili fastis dum sep tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Post la morto de Saul, kiam David revenis de la venkobato de Amalek, kaj David estis en Ciklag de du tagoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'okazis, ke en la tria tago iu viro venis el la tendaro, de Saul, kaj liaj vestoj estis disŝiritaj kaj terpolvo estis sur lia kapo; kaj kiam li alvenis al David, li ĵetis sin sur la teron kaj adorkliniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'Kaj David diris al li: De kie vi venas? Kaj tiu diris al li: El la tendaro de la Izraelidoj mi forsavis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'Kaj David diris al li: Kiel estis la afero? diru al mi, mi petas. Kaj tiu diris, ke la popolo forkuris el la batalo, ke multaj falis el la popolo kaj mortis, kaj ke ankaŭ Saul kaj lia filo Jonatan mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'Kaj David diris al la junulo, kiu raportis al li: Kiamaniere vi eksciis, ke mortis Saul kaj lia filo Jonatan?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Kaj la junulo raportanta al li diris: Okaze mi venis sur la monton Gilboa, kaj jen mi vidis, ke Saul apogas sin sur sia glavo kaj la ĉaroj kaj rajdantoj atingas lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Kaj li ekrigardis malantaŭen, kaj ekvidis min kaj vokis min; kaj mi diris: Jen mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Kaj li diris al mi: Kiu vi estas? Kaj mi diris al li: Mi estas Amalekido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Kaj li diris al mi: Stariĝu, mi petas, super mi, kaj mortigu min, ĉar kaptis min agonio; ĉar mia animo ĝis nun ankoraŭ estas en mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Tiam mi stariĝis super li kaj mortigis lin, ĉar mi sciis, ke li ne vivos post sia falo; kaj mi prenis la kronon, kiu estis sur lia kapo, kaj la brakornamon, kiu estis sur lia brako, kaj mi alportis ilin al mia sinjoro ĉi tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Tiam David kaptis siajn vestojn kaj disŝiris ilin, ankaŭ ĉiuj homoj, kiuj estis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'Kaj ili funebris kaj ploris kaj fastis ĝis la vespero, pro Saul, kaj pro Jonatan, lia filo, kaj pro la popolo de la Eternulo, kaj pro la domo de Izrael, ke ili falis de glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Kaj David diris al la junulo, kiu raportis al li: De kie vi estas? Kaj tiu respondis: Mi estas filo de fremdulo Amalekido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Tiam David diris al li: Kiel vi ne timis etendi vian manon, por pereigi la sanktoleiton de la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Kaj David alvokis unu el la servantoj, kaj diris: Alproksimiĝu, kaj frapu lin. Kaj tiu frapis lin, kaj li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'Kaj David diris al li: Via sango estu sur via kapo; ĉar via buŝo atestas kontraŭ vi per tio, ke vi diris: Mi mortigis la sanktoleiton de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Kaj David eldiris la sekvantan funebran parolon pri Saul kaj pri lia filo Jonatan');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, '(kaj li ordonis instrui al la Judoj la uzadon de pafarko, kiel estas skribite en la libro de la Justulo):');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'La beleco de Izrael estas mortigita sur viaj altaĵoj! Kiel falis la herooj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Ne sciigu en Gat, Ne anoncu sur la stratoj de Aŝkelon; Por ke ne ĝoju la filinoj de la Filiŝtoj, Por ke ne ĝojkriu la filinoj de la necirkumciditoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Montoj en Gilboa, Nek roso nek pluvo estu sur vi, nek kampoj fruktodonaj; Ĉar tie estas malhonorita la ŝildo de herooj, La ŝildo de Saul, kvazaŭ li ne estus oleita per sankta oleo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Sen sango de mortigitoj, sen sebo de fortuloj, La pafarko de Jonatan neniam venis returne, Kaj la glavo de Saul ne revenis vane.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saul kaj Jonatan, amindaj kaj ĉarmaj ĉe sia vivo, Eĉ ĉe sia morto ne disiĝis; Pli rapidaj ili estis ol agloj, Pli fortaj ol leonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Filinoj de Izrael, ploru pri Saul, Kiu vestis vin per purpuro kun ornamaĵoj, Kiu metis orajn ornamojn sur viajn vestojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Kiel falis herooj meze de la batalo! Mortigita estas Jonatan sur viaj altaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Mi malĝojas pro vi, mia frato Jonatan; Vi estis al mi tre kara; Via amo estis al mi pli kara, Ol la amo de virinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Kiel falis herooj, Kaj pereis batalaj armiloj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Post tio David demandis la Eternulon, dirante: Ĉu mi eniru en unu el la urboj de Jehuda? Kaj la Eternulo diris al li: Eniru. Kaj David diris: Kien mi eniru? Kaj Li respondis: En Ĥebronon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'Kaj David tien eniris, kune kun siaj edzinoj, Aĥinoam, la Jizreelanino, kaj Abigail, edzino de Nabal, la Karmelanino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Ankaŭ siajn virojn, kiuj estis kun li, David alkondukis, ĉiun kun lia domo; kaj ili ekloĝis en la urboj de Ĥebron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Tiam venis la viroj de Jehuda kaj sanktoleis tie Davidon kiel reĝon super la domo de Jehuda. Kiam oni sciigis al David, ke la loĝantoj de Jabeŝ en Gilead enterigis Saulon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'David sendis senditojn al la loĝantoj de Jabeŝ en Gilead, kaj dirigis al ili: Estu benataj de la Eternulo pro tio, ke vi faris tiun favorkoraĵon al via sinjoro, al Saul, kaj enterigis lin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'nun la Eternulo faru al vi favorkoraĵon kaj justaĵon; kaj mi ankaŭ repagos al vi tiun bonaĵon, kiun vi faris;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'nun fortiĝu viaj manoj, kaj estu kuraĝaj; ĉar mortis via sinjoro Saul, sed jam min sanktoleis la Judoj kiel reĝon super ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Dume Abner, filo de Ner, militestro de Saul, prenis Iŝ-Boŝeton, filon de Saul, kaj transkondukis lin en Maĥanaimon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'kaj starigis lin kiel reĝon super Gilead kaj super la Aŝuridoj kaj super Jizreel kaj super Efraim kaj super Benjamen kaj super la tuta Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Iŝ-Boŝet, filo de Saul, havis la aĝon de kvardek jaroj, kiam li fariĝis reĝo de Izrael, kaj du jarojn li reĝis. Nur la domo de Jehuda sekvis Davidon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'La daŭro de la tempo, dum kiu David estis reĝo en Ĥebron super la domo de Jehuda, estis sep jaroj kaj ses monatoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Kaj Abner, filo de Ner, kun la servantoj de Iŝ-Boŝet, filo de Saul, eliris el Maĥanaim en Gibeonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Kaj Joab, filo de Ceruja, kun la servantoj de David, eliris kaj renkontiĝis kun ili ĉe la akvejo de Gibeon; kaj sidiĝis unuj ĉe unu flanko de la akvejo, kaj la aliaj ĉe la dua flanko de la akvejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Kaj Abner diris al Joab: La junuloj leviĝu, kaj amuziĝu antaŭ ni. Kaj Joab diris: Ili leviĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Kaj leviĝis kaj eliris dek du de la flanko de Benjamen kaj de Iŝ- Boŝet, filo de Saul, kaj dek du el la servantoj de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Kaj ili kaptis ĉiu la kapon de sia kontraŭulo kaj enpikis sian glavon en la flankon de sia kontraŭulo, kaj ili falis kune. Tial oni donis al tiu loko la nomon Kampo de la Fortuloj en Gibeon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'Kaj fariĝis tre kruela batalo en tiu tago; kaj frapitaj estis Abner kaj la Izraelidoj antaŭ la servantoj de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Kaj tie estis tri filoj de Ceruja: Joab kaj Abiŝaj kaj Asahel; Asahel estis rapidpieda kiel gazelo sur la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'Kaj Asahel postkuris Abneron, kaj, ne flankiĝante dekstren nek maldekstren, sekvis Abneron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Abner turniĝis malantaŭen, kaj diris: Ĉu vi estas Asahel? Kaj tiu respondis: Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Tiam Abner diris al li: Flankeniĝu dekstren aŭ maldekstren, kaj kaptu al vi unu el la junuloj, kaj prenu al vi liajn armilojn. Sed Asahel ne volis cedi de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Abner denove diris al Asahel: Forcedu de mi; por kio mi batu vin sur la teron? kaj kiel mi poste montros mian vizaĝon al via frato Joab?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Sed tiu ne volis foriĝi. Tiam Abner ekbatis lin per la malantaŭa fino de la lanco en la ventron tiel, ke la lanco eliris tra lia malantaŭa parto; kaj li tie falis, kaj mortis sur la sama loko. Kaj ĉiu, kiu venis al la loko, kie Asahel falis kaj mortis, haltis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Kaj Joab kaj Abiŝaj postkuris Abneron. Kiam la suno malleviĝis, ili venis al la monteto Ama, kiu estas kontraŭ Giaĥ sur la vojo al la dezerto Gibeona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Kaj la Benjamenidoj kolektiĝis ĉirkaŭ Abner kaj formis unu taĉmenton kaj stariĝis sur la supro de unu monteto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Tiam Abner ekkriis al Joab, kaj diris: Ĉu eterne manĝados la glavo? ĉu vi ne scias, kiel maldolĉaj estos la sekvoj? kiel longe vi ne ordonos al la popolo ĉesigi la atakadon de siaj fratoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Kaj Joab respondis: Kiel vivas la Eternulo, se vi ne estus elvokinta, tiam ankoraŭ matene la popolo ĉesus atakadi ĉiu sian fraton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Kaj Joab ekblovis per trumpeto, kaj la tuta popolo haltis kaj ne persekutis plu la Izraelidojn kaj ne plu batalis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Abner kaj liaj viroj marŝis sur la ebenaĵo tiun tutan nokton kaj transiris Jordanon kaj trairis la tutan Bitronon kaj venis en Maĥanaimon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Kaj Joab revenis de la persekutado de Abner kaj kolektis la tutan popolon; kaj mankis el la servantoj de David dek naŭ viroj kaj Asahel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Sed la servantoj de David frapis el la Benjamenidoj kaj el la viroj de Abner tricent sesdek virojn, kiuj mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Kaj ili levis Asahelon, kaj enterigis lin en la tombo de lia patro, kiu estas en Bet-Leĥem. Kaj Joab kaj liaj viroj iris dum la tuta nokto, kaj la mateno trafis ilin en Ĥebron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Kaj la milito estis longedaŭra inter la domo de Saul kaj la domo de David. Sed David fariĝadis ĉiam pli forta, kaj la domo de Saul fariĝadis ĉiam pli malforta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Al David naskiĝis filoj en Ĥebron. Lia unuenaskito estis Amnon, de Aĥinoam, la Jizreelanino;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'lia dua filo estis Kilab, de Abigail, edzino de Nabal, la Karmelanino; la tria, Abŝalom, de Maaĥa, filino de Talmaj, reĝo de Geŝur;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'la kvara, Adonija, filo de Ĥagit; la kvina, Ŝefatja, filo de Abital;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'la sesa, Jitream, de Egla, edzino de David. Ĉi tiuj naskiĝis al David en Ĥebron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Dum la tempo, kiam estis milito inter la domo de Saul kaj la domo de David, Abner subtenadis la domon de Saul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Saul havis kromvirinon, kies nomo estis Ricpa, filino de Aja. Kaj Iŝ- Boŝet diris al Abner: Kial vi envenis al la kromvirino de mia patro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Tiam Abner forte ekkoleris pro la vortoj de Iŝ-Boŝet, kaj li diris: Ĉu mi estas kapo de hundo, mi, kiu kontraŭ Jehuda faras favorkoraĵon al la domo de via patro Saul, al liaj fratoj kaj al liaj amikoj, kaj ne transdonis vin en la manon de David? kaj vi riproĉas al mi hodiaŭ krimon pro la virino!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Tiel kaj pli Dio punu Abneron, se mi ne agos konforme al tio, kiel la Eternulo ĵuris al David;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'por forpreni la regnon de la domo de Saul, kaj starigi la tronon de David super Izrael kaj Jehuda, de Dan ĝis Beer-Ŝeba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Kaj li ne povis plu respondi al Abner eĉ unu vorton, ĉar li timis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Tiam Abner sendis senditojn al David anstataŭ si, por diri: Al kiu apartenas la lando? faru vian interligon kun mi, kaj tiam mia mano estos kun vi, por turni al vi la tutan Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Kaj tiu diris: Bone, mi faros kun vi interligon; nur unu aferon mi petos de vi, nome: vi ne vidos mian vizaĝon, se vi antaŭe ne alkondukos al mi Miĥalon, filinon de Saul, kiam vi venos, por vidi mian vizaĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'Kaj David sendis senditojn al Iŝ-Boŝet, filo de Saul, por diri: Donu mian edzinon Miĥal, kiun mi edzinigis al mi per cent prepucioj de Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Tiam Iŝ-Boŝet sendis, kaj prenis ŝin de la edzo, de Paltiel, filo de Laiŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Kaj ŝia edzo iris kun ŝi, ne ĉesante plori pro ŝi ĝis Baĥurim; sed Abner diris al li: Iru returne; kaj li iris returne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Kaj Abner ekparolis kun la plejaĝuloj de Izrael, dirante: Jam de longe vi volas havi Davidon kiel reĝon super vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'nun faru do tion; ĉar la Eternulo diris pri David jene: Per la mano de Mia servanto David Mi savos Mian popolon Izrael el la manoj de la Filiŝtoj kaj el la manoj de ĉiuj iliaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Ankaŭ al la oreloj de la Benjamenidoj Abner parolis. Kaj Abner ankaŭ iris, por diri al la oreloj de David en Ĥebron ĉion, kio plaĉas al la Izraelidoj kaj al la tuta domo de Benjamen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Kiam Abner venis al David en Ĥebronon kaj kun li dudek viroj, David faris por Abner kaj por liaj viroj festenon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Kaj Abner diris al David: Mi leviĝos, kaj iros kaj kunvenigos al mia sinjoro la reĝo la tutan Izraelon, por ke ili faru kun vi interligon, kaj por ke vi reĝu super ĉio, kiel deziros via animo. Kaj David forliberigis Abneron, kaj li iris en paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'Sed jen la servantoj de David kaj Joab venis el batalo, kaj alportis kun si multe da militakiro; Abner tiam jam ne estis kun David en Ĥebron, ĉar ĉi tiu forliberigis lin kaj li foriris en paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Kiam venis Joab kun la tuta militistaro, kiu estis kun li, oni sciigis al Joab, dirante: Abner, filo de Ner, venis al la reĝo; kaj ĉi tiu forliberigis lin kaj li iris en paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Tiam Joab venis al la reĝo, kaj diris: Kion vi faris? jen Abner venis al vi; kial do vi forliberigis lin, ke li foriris?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Vi konas ja Abneron, filon de Ner; nur por tromplogi vin li venis, kaj por ekkoni ĉiujn viajn elirojn kaj enirojn, kaj por ekscii ĉion, kion vi faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Kaj Joab eliris de David kaj sendis senditojn post Abner, kaj ili revenigis lin de la puto Sira; kaj David ne sciis pri tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Kiam Abner revenis Ĥebronon, Joab kondukis lin en la mezon de la pordego, por paroli kun li sekrete, kaj frapis lin tie en la ventron; kaj li mortis, pro la sango de lia frato Asahel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Kiam David poste aŭdis pri tio, li diris: Senkulpa estas mi kaj mia regno antaŭ la Eternulo por eterne pri la sango de Abner, filo de Ner.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Ĝi falu sur la kapon de Joab kaj de lia tuta patrodomo; ne manku en la domo de Joab pusulo, nek leprulo, nek apoganta sin sur bastono, nek falanta de glavo, nek havanta mankon de pano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Tiel Joab kaj lia frato Abiŝaj mortigis Abneron pro tio, ke li mortigis Asahelon, ilian fraton, en Gibeon dum la batalo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Kaj David diris al Joab, kaj al la tuta popolo, kiu estis kun li: Disŝiru viajn vestojn kaj zonu vin per sakoj, kaj funebru pro Abner. Kaj la reĝo David sekvis la mortintportilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'Kaj oni enterigis Abneron en Ĥebron; kaj la reĝo levis sian voĉon kaj ploris super la tombo de Abner, kaj ploris la tuta popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Kaj la reĝo eldiris funebran parolon pri Abner, kaj diris: Ĉu Abner devis morti tiel, kiel mortas malnoblulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Viaj manoj ne estis ligitaj, kaj viaj piedoj ne estis en katenoj; Vi falis, kiel oni falas de krimuloj. Kaj ankoraŭ pli ploris pro li la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Poste venis la tuta popolo, por igi Davidon manĝi, dum estis ankoraŭ tago; sed David ĵuris, dirante: Tiel kaj pli punu min Dio, se mi antaŭ la sunsubiro gustumos panon aŭ ion ajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Kaj la tuta popolo tion komprenis; kaj tio plaĉis al ĝi, tiel same, kiel ĉio, kion faris la reĝo, plaĉis al la tuta popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Kaj eksciis en tiu tago la tuta popolo kaj la tuta Izrael, ke ne de la reĝo tio venis, ke oni mortigis Abneron, filon de Ner.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Kaj la reĝo diris al siaj servantoj: Ĉu vi ne scias, ke princo kaj grandulo falis hodiaŭ en Izrael?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Sed mi hodiaŭ estas ankoraŭ malforta kaj apenaŭ sanktoleita kiel reĝo, kaj tiuj homoj, la filoj de Ceruja, estas pli fortaj ol mi; la Eternulo repagu al la malbonaganto konforme al lia malbonago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Kiam la filo de Saul aŭdis, ke mortis Abner en Ĥebron, tiam liaj manoj malleviĝis kaj la tuta Izrael konsterniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Du viroj taĉmentestroj estis ĉe la filo de Saul; la nomo de unu estis Baana, kaj la nomo de la dua Reĥab, filoj de Rimon, Beerotano, el la Benjamenidoj; ĉar Beerot ankaŭ estis kalkulata kiel apartenaĵo de la Benjamenidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'Sed la Beerotanoj forkuris en Gitaimon kaj loĝis tie kiel fremduloj ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'De Jonatan, filo de Saul, restis filo, kiu havis malsanajn piedojn. Li havis la aĝon de kvin jaroj, kiam venis la sciigo pri Saul kaj Jonatan el Jizreel; kiam lia vartistino prenis lin kaj ekkuris, kaj ŝi rapidis forkuri, li falis kaj fariĝis lama. Lia nomo estis Mefiboŝet.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Reĥab kaj Baana, filoj de Rimon, la Beerotano, iris kaj venis en la varmego de la tago en la domon de Iŝ-Boŝet, kiam li kuŝis sian tagmezan kuŝadon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Kaj jen ili eniris en la mezon de la domo, kvazaŭ por preni tritikon, kaj frapis lin en la ventron; poste Reĥab kaj lia frato Baana forkuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Kiam ili eniris en la domon, li kuŝis sur sia lito en sia dormoĉambro; tial ili frapis lin kaj mortigis lin, kaj dehakis lian kapon, kaj prenis lian kapon, kaj iris laŭ la vojo al la ebenaĵo dum la tuta nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'Kaj ili alportis la kapon de Iŝ-Boŝet al David en Ĥebronon, kaj diris al la reĝo: Jen estas la kapo de Iŝ-Boŝet, filo de Saul, via malamiko, kiu serĉis vian animon; la Eternulo donis al nia sinjoro, la reĝo, venĝon hodiaŭ pro Saul kaj pro lia idaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Sed David respondis al Reĥab kaj al lia frato Baana, filoj de Rimon, la Beerotano, kaj diris al ili: Kiel vivas la Eternulo, kiu savis mian animon el ĉiuj malfeliĉoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'se tiun, kiu sciigis al mi, ke Saul mortis, kaj kiu pensis, ke li estas agrabla sciiganto, mi kaptis kaj mortigis en Ciklag, por rekompenci lin pro la sciigo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'kiel do oni devas agi kun malpiaj homoj, kiuj mortigis homon senkulpan en lia domo, sur lia lito? ĉu mi ne devas repostuli lian sangon el viaj manoj, kaj ekstermi vin de sur la tero?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'Kaj David ordonis al la servantoj; kaj ĉi tiuj ilin mortigis, kaj dehakis iliajn manojn kaj piedojn, kaj pendigis ilin super la lageto en Ĥebron; kaj la kapon de Iŝ-Boŝet oni prenis kaj enterigis en la tombo de Abner en Ĥebron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Kaj venis ĉiuj triboj de Izrael al David en Ĥebronon, kaj diris jene: Jen ni estas via osto kaj via karno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'jam antaŭe, kiam Saul estis reĝo super ni, vi estis la elkondukanto kaj enkondukanto de Izrael; kaj la Eternulo diris al vi: Vi paŝtos Mian popolon Izrael, kaj vi estos la estro super Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Kaj venis ĉiuj plejaĝuloj de Izrael al la reĝo en Ĥebronon, kaj la reĝo David faris kun ili interligon en Ĥebron antaŭ la Eternulo; kaj ili sanktoleis Davidon reĝo super Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'La aĝon de tridek jaroj havis David, kiam li fariĝis reĝo; kvardek jarojn li reĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'En Ĥebron li reĝis super Jehuda sep jarojn kaj ses monatojn, kaj en Jerusalem li reĝis tridek tri jarojn super la tuta Izrael kaj Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Kaj la reĝo kun siaj viroj iris al Jerusalem, kontraŭ la Jebusidojn, la loĝantojn de tiu lando. Sed ili diris al David: Vi ne eniros ĉi tien, ĉar blinduloj kaj lamuloj vin rebatos; tio signifis: David ne venos ĉi tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Sed David venkoprenis la fortikaĵon Cion, tio estas, la urbon de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Kaj David diris en tiu tago: Ĉiu, kiu frapas la Jebusidojn, ekstermu la akvotubojn, kaj la blindulojn kaj la lamulojn, kiujn malamas la animo de David. Tial oni diras: Blindulo kaj lamulo ne venos en la domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'Kaj David ekloĝis en la fortikaĵo, kaj donis al ĝi la nomon: Urbo de David. Kaj David konstruis ĉirkaŭe, komencante de Milo kaj internen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'Kaj David fariĝadis ĉiam pli kaj pli granda; kaj la Eternulo, Dio Cebaot, estis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Kaj Ĥiram, reĝo de Tiro, sendis senditojn al David, kaj cedrajn arbojn, kaj ĉarpentistojn kaj masonistojn; kaj ili konstruis domon al David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'Kaj David konsciis, ke la Eternulo fortikigis lin kiel reĝon super Izrael, kaj ke Li altigis lian regnon pro Sia popolo Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Kaj David prenis ankoraŭ kromvirinojn kaj edzinojn el Jerusalem post sia veno el Ĥebron. Kaj naskiĝis al David ankoraŭ filoj kaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Jen estas la nomoj de tiuj, kiuj naskiĝis al li en Jerusalem: Ŝamua kaj Ŝobab kaj Natan kaj Salomono');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'kaj Jibĥar kaj Eliŝua kaj Nefeg kaj Jafia');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'kaj Eliŝama kaj Eljada kaj Elifelet.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Kiam la Filiŝtoj aŭdis, ke oni sanktoleis Davidon reĝo super Izrael, ĉiuj Filiŝtoj iris, por serĉi Davidon. David aŭdis pri tio, kaj eniris en la fortikaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Kaj la Filiŝtoj venis kaj okupis lokon en la valo Refaim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Kaj David demandis la Eternulon, dirante: Ĉu mi iru kontraŭ la Filiŝtojn? ĉu Vi transdonos ilin en mian manon? Kaj la Eternulo diris al David: Iru, ĉar Mi certe transdonos la Filiŝtojn en vian manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Tiam David venis al la loko Baal-Peracim, kaj David tie venkobatis ilin; kaj li diris: La Eternulo disbatis miajn malamikojn antaŭ mi, kiel oni disbatas akvon. Tial oni donis al tiu loko la nomon Baal-Peracim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'Kaj ili lasis tie siajn diojn, kaj forportis ilin David kaj liaj viroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Kaj denove venis la Filiŝtoj kaj okupis lokon en la valo Refaim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Kaj kiam David demandis la Eternulon, Li diris: Ne iru; turnu vin post ilin, kaj venu al ili de la flanko de la morusarboj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'kaj kiam vi ekaŭdos la sonon de paŝoj sur la supro de la morusarboj, tiam ataku; ĉar tiam la Eternulo eliris antaŭ vi, por frapi la tendaron de la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'Kaj David faris tiel, kiel ordonis al li la Eternulo; kaj li venkobatis la Filiŝtojn de Geba ĝis Gezer.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'Kaj denove David kolektis ĉiujn elektitojn en Izrael, tridek mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Kaj David, kaj la tuta popolo, kiu estis kun li, leviĝis kaj iris el Baale-Jehuda, por venigi de tie la keston de Dio, kiu estas nomata per la nomo de la Eternulo Cebaot, kiu sidas sur la keruboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Kaj oni veturigis la keston de Dio sur nova veturilo, kaj prenis ĝin el la domo de Abinadab, kiu estis en Gibea. Kaj Uza kaj Aĥjo, filoj de Abinadab, kondukis la novan veturilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'Kaj oni prenis ĝin el la domo de Abinadab en Gibea kun la kesto de Dio, kaj Aĥjo iris antaŭ la kesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'Kaj David kaj la tuta domo de Izrael ludis antaŭ la Eternulo per ĉiaj instrumentoj el cipreso, per harpoj, psalteroj, tamburinoj, sistroj, kaj cimbaloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Kiam ili venis al la draŝejo de Naĥon, Uza etendis sian manon al la kesto de Dio kaj ekkaptis ĝin, ĉar la bovoj klinpuŝis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Tiam ekflamis la kolero de la Eternulo kontraŭ Uza, kaj Dio mortigis lin tie pro la peko, kaj li mortis tie apud la kesto de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'Kaj afliktiĝis David pro tio, ke la Eternulo frapis Uzan, kaj li donis al tiu loko la nomon Perec-Uza, ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Kaj ektimis David la Eternulon en tiu tago, kaj diris: Kiamaniere venos al mi la kesto de la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Kaj David ne volis transportigi al si la keston de la Eternulo en la urbon de David, kaj David direktis ĝin en la domon de Obed-Edom, la Gatano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'Kaj la kesto de la Eternulo restis en la domo de Obed-Edom, la Gatano, dum tri monatoj; kaj la Eternulo benis Obed-Edomon kaj lian tutan domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Kaj oni sciigis al la reĝo David, dirante: La Eternulo benis la domon de Obed-Edom, kaj ĉion, kio apartenas al li, pro la kesto de Dio. Tiam David iris, kaj transportis la keston de Dio el la domo de Obed-Edom en la urbon de David kun ĝojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'Kaj ĉiufoje, kiam la portantoj de la kesto de la Eternulo trapaŝis ses paŝojn, li oferbuĉis bovon kaj grasan ŝafon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'Kaj David dancis per ĉiuj fortoj antaŭ la Eternulo, kaj David estis zonita per lina efodo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Kaj David kaj la tuta domo de Izrael kondukis la keston de la Eternulo kun ĝojkriado kaj trumpetado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Kiam la kesto de la Eternulo venis en la urbon de David, Miĥal, la filino de Saul, rigardis tra la fenestro; kaj kiam ŝi vidis, ke la reĝo David saltas kaj dancas antaŭ la Eternulo, ŝi ekmalestimis lin en sia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Kaj oni alportis la keston de la Eternulo, kaj metis ĝin sur ĝian lokon meze de la tendo, kiun David starigis por ĝi; kaj David alportis antaŭ la Eternulo bruloferojn kaj pacoferojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Kiam David finis la oferadon de la bruloferoj kaj de la pacoferoj, li benis la popolon en la nomo de la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Kaj li disdonis al la tuta popolo, al la tuta amaso de la Izraelidoj, kiel al la viroj, tiel ankaŭ al la virinoj, al ĉiu po unu bulo da pano, po unu porcio da viando, kaj po unu peniko da sekvinberoj. Kaj la tuta popolo iris ĉiu al sia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Kiam David revenis, por beni sian domon, Miĥal, filino de Saul, eliris renkonte al David, kaj diris: Kiel majesta estis hodiaŭ la reĝo de Izrael, kiu elmontris sin hodiaŭ antaŭ la okuloj de la sklavinoj de siaj servantoj, kiel sin elmontras iu el la publikaj dancistoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Sed David diris al Miĥal: Antaŭ la Eternulo, kiu preferis min antaŭ via patro kaj antaŭ lia tuta domo, ordonante al mi esti estro super la popolo de la Eternulo, super Izrael, antaŭ la Eternulo mi ludis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'Kaj mi senvalorigos min ankoraŭ pli ol tio, kaj mi humiligos min antaŭ miaj okuloj; kaj tamen inter la sklavinoj, pri kiuj vi parolis, mi estos honorata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Kaj Miĥal, la filino de Saul, ne havis infanojn ĝis la tago de ŝia morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Kiam la reĝo loĝis en sia domo, kaj la Eternulo donis al li ripozon rilate ĉiujn liajn malamikojn ĉirkaŭe,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'la reĝo diris al la profeto Natan: Vidu, mi loĝas en domo cedroligna, kaj la kesto de Dio restas inter tapiŝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Kaj Natan diris al la reĝo: Ĉion, kio estas en via koro, iru kaj faru, ĉar la Eternulo estas kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Sed en tiu sama nokto aperis vorto de la Eternulo al Natan, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Iru, kaj diru al Mia servanto David: Tiele diris la Eternulo: Ĉu vi konstruos al Mi domon por Mia loĝado?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Ĉar Mi ne loĝis en domo de post tiu tago, kiam Mi elkondukis la Izraelidojn el Egiptujo, ĝis la nuna tempo; sed Mi migradis en tendo kaj en tabernaklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Kien ajn Mi iris kun ĉiuj Izraelidoj, ĉu Mi diris eĉ unu vorton al iu el la triboj de Izrael, al kiu Mi ordonis paŝti Mian popolon Izrael, dirante: Kial vi ne konstruis por Mi cedrolignan domon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Kaj nun diru jenon al Mia servanto David: Tiele diras la Eternulo Cebaot: Mi prenis vin el ŝafejo, de ŝafoj, por ke vi estu estro super Mia popolo Izrael;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'kaj Mi estis kun vi ĉie, kien vi iris; kaj Mi ekstermis ĉiujn viajn malamikojn antaŭ vi, kaj Mi faris al vi grandan nomon, egalan al la nomoj de la potenculoj sur la tero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'kaj Mi aranĝis lokon por Mia popolo Izrael; kaj Mi plantis ĝin, ke ĝi loĝu trankvile sur sia loko kaj ne tremu plu; kaj malbonuloj ne plu premos ĝin, kiel antaŭe;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'kaj de post tiu tempo, kiam Mi starigis juĝistojn super Mia popolo Izrael kaj donis al vi trankvilecon rilate ĉiujn viajn malamikojn, la Eternulo sciigis al vi, ke domon konstruos al vi la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Kiam finiĝos viaj tagoj kaj vi kuŝiĝos kun viaj patroj, Mi starigos post vi vian idon, kiu eliros el via ventro; kaj Mi fortikigos lian regnon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Li konstruos domon al Mia nomo; kaj Mi fortikigos la tronon de lia regno por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Mi estos al li patro, kaj li estos al Mi filo; se li faros malbonagon, Mi punos lin per vergo de homoj kaj per batoj de homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'Kaj Mia favorkoreco ne deturniĝos de li, kiel Mi deturnis ĝin de Saul, kiun Mi forigis antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Kaj fidinda estos via domo kaj via regno eterne antaŭ vi; via trono estos fortikigita por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Konforme al ĉiuj ĉi tiuj vortoj kaj konforme al ĉi tiu tuta vizio Natan parolis al David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Kaj venis la reĝo David kaj sidiĝis antaŭ la Eternulo, kaj diris: Kiu estas mi, mia Sinjoro, ho Eternulo, kaj kio estas mia domo, ke Vi venigis min ĝis ĉi tie?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Sed eĉ tio estis nesufiĉa antaŭ Vi, mia Sinjoro, ho Eternulo, kaj Vi parolis pri la domo de Via sklavo eĉ por la malproksima estonteco, laŭ la maniero de homo, mia Sinjoro, ho Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Kion pli David povas diri al Vi? Vi konas ja Vian sklavon, mia Sinjoro, ho Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Pro Via vorto kaj laŭ Via koro Vi faris tiun tutan grandaĵon, por montri al Via sklavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Pro tio Vi estas granda, ho Dio Eternulo; ĉar ne ekzistas simila al Vi, kaj ne ekzistas Dio krom Vi, laŭ ĉio, kion ni aŭdis per niaj oreloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Kaj kiu estas simila al Via popolo Izrael, la sola popolo sur la tero, koncerne kiun Dio iris, por elaĉeti ĝin al Si kiel popolon, kaj fari al Si nomon, kaj fari grandaĵojn por Vi kaj timindaĵojn por Via tero, antaŭ Via popolo, kiun Vi liberigis al Vi el Egiptujo, de ĝiaj popoloj kaj ĝiaj dioj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Kaj Vi starigis al Vi Vian popolon Izrael, por ke ĝi estu por Vi popolo por eterne; kaj Vi, ho Eternulo, faris Vin Dio por ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Kaj nun, ho Dio Eternulo, la vorton, kiun Vi diris pri Via sklavo kaj pri lia domo, fortikigu por eterne, kaj Vi agu tiel, kiel Vi diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Kaj granda estu Via nomo por eterne, por ke oni diru: La Eternulo Cebaot estas Dio super Izrael. Kaj la domo de Via sklavo David estu fortikigita antaŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Ĉar Vi, ho Eternulo Cebaot, Dio de Izrael, sciigis al la orelo de Via sklavo, dirante: Domon mi konstruos al vi; tial Via sklavo trovis kuraĝon en sia koro preĝi al Vi ĉi tiun preĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Kaj nun, mia Sinjoro, ho Eternulo, Vi estas Dio, kaj Viaj vortoj estas veraj; kaj Vi diris pri Via sklavo ĉi tiun bonaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Nun komencu beni la domon de Via sklavo, ke ĝi restu eterne antaŭ Vi; ĉar Vi, mia Sinjoro, ho Eternulo, parolis; kaj per Via beno estos benita la domo de Via sklavo eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Post tio okazis, ke David venkobatis la Filiŝtojn kaj humiligis ilin, kaj David prenis la ĉefurbon el la manoj de la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Li ankaŭ venkobatis la Moabidojn, kaj, kuŝiginte ilin sur la tero, li mezuris ilin per ŝnuro; du partojn li mezuris por mortigi, kaj unu plenan mezuron por restigi vivaj. Kaj la Moabidoj submetiĝis al David kaj alportis tributojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'Kaj David venkobatis Hadadezeron, filon de Reĥob, reĝon de Coba, kiam tiu iris, por restarigi sian regadon super la rivero Eŭfrato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'Kaj David venkoprenis de li mil sepcent rajdantojn kaj dudek mil piedirantojn; kaj David lamigis ĉiujn ĉarĉevalojn, sed restigis el ili por cent ĉaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'La Sirianoj Damaskaj venis, por helpi al Hadadezer, reĝo de Coba; sed David venkobatis el la Sirianoj dudek du mil homojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Kaj David restigis garnizonojn en la Damaska Sirio, kaj la Sirianoj submetiĝis al David kaj alportis tributojn. Kaj la Eternulo helpis al David ĉie, kien li iris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'Kaj David prenis la orajn ŝildojn, kiujn havis sur si la servantoj de Hadadezer, kaj alportis ilin en Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Kaj el Betaĥ kaj el Berotaj, urboj de Hadadezer, la reĝo David prenis tre multe da kupro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Kiam Toi, reĝo de Ĥamat, aŭdis, ke David venkobatis la tutan militistaron de Hadadezer,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'tiam Toi sendis sian filon Joram al la reĝo David, por saluti lin, kaj gratuli lin pro tio, ke li militis kontraŭ Hadadezer kaj venkobatis lin (ĉar Toi estis en milito kontraŭ Hadadezer); kaj li havis en siaj manoj vazojn arĝentajn kaj vazojn orajn kaj vazojn kuprajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Ilin ankaŭ la reĝo David dediĉis al la Eternulo, kune kun la arĝento kaj oro, kiun li dediĉis el tio, kion li akiris de ĉiuj nacioj, kiujn li venkis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'de la Sirianoj, de Moab, de la Amonidoj, de la Filiŝtoj, kaj de Amalek, kaj el la militakiro, kiun li ricevis de Hadadezer, filo de Reĥob kaj reĝo de Coba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'Kaj David faris al si nomon, kiam li revenis post la venkobato de la Sirianoj en la Valo de Salo, en la nombro de dek ok mil homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Kaj li starigis en Edomujo garnizonojn, en la tuta Edomujo li starigis garnizonojn; kaj ĉiuj Edomidoj submetiĝis al David. Kaj la Eternulo helpis al David ĉie, kien li iris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'Kaj David reĝis super la tuta Izrael, kaj David faradis juĝon kaj justecon al sia tuta popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Joab, filo de Ceruja, estis estro de la militistaro; Jehoŝafat, filo de Aĥilud, estis kronikisto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Cadok, filo de Aĥitub, kaj Aĥimeleĥ, filo de Ebjatar, estis pastroj; kaj Seraja estis skribisto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Benaja, filo de Jehojada, estis super la Keretidoj kaj la Peletidoj; kaj la filoj de David estis pastroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Kaj David diris: Ĉu ekzistas ankoraŭ iu, kiu restis el la domo de Saul, ke mi povu fari al li favorkoraĵon pro Jonatan?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'El la domo de Saul estis servanto, kies nomo estis Ciba; kaj oni vokis lin al David, kaj la reĝo diris al li: Ĉu vi estas Ciba? Kaj tiu respondis: Mi, via sklavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Tiam la reĝo diris: Ĉu ekzistas ankoraŭ iu el la domo de Saul, ke mi povu fari al li favorkoraĵon en la nomo de Dio? Kaj Ciba diris al la reĝo: Ekzistas ankoraŭ filo de Jonatan, lamulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Kaj la reĝo diris al li: Kie li estas? Kaj Ciba diris al la reĝo: Jen li estas en la domo de Maĥir, filo de Amiel, en Lo-Debar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Tiam la reĝo David sendis, kaj venigis lin el la domo de Maĥir, filo de Amiel, el Lo-Debar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Kaj venis Mefiboŝet, filo de Jonatan, filo de Saul, al David, kaj ĵetis sin vizaĝaltere kaj adorkliniĝis. Kaj David diris: Mefiboŝet! Kaj tiu diris: Jen mi estas, via sklavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'Kaj David diris al li: Ne timu, ĉar mi estos por vi favorkora pro via patro Jonatan, kaj mi redonos al vi ĉiujn kampojn de via patro Saul, kaj vi manĝados ĉiam ĉe mia tablo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Kaj tiu adorkliniĝis, kaj diris: Kio estas via sklavo, ke vi vin turnas al senviva hundo, kiel mi estas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Kaj la reĝo alvokis Ciban, la servanton de Saul, kaj diris al li: Ĉion, kio apartenis al Saul kaj al lia tuta domo, mi donas al la filo de via sinjoro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'prilaboradu do por li la teron, vi kaj viaj filoj kaj viaj servantoj, kaj rikoltadu, por ke la filo de via sinjoro havu panon por manĝado; sed Mefiboŝet, filo de via sinjoro, manĝados ĉiam ĉe mia tablo. Kaj Ciba havis dek kvin filojn kaj dudek servantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Kaj Ciba diris al la reĝo: Ĉion, kion mia sinjoro la reĝo ordonas al sia sklavo, via sklavo faros. Kaj Mefiboŝet manĝados ĉe mia tablo egale al la filoj de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Mefiboŝet havis malgrandan filon, kies nomo estis Miĥa. Kaj ĉiuj, kiuj loĝis en la domo de Ciba, estis servantoj al Mefiboŝet.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Kaj Mefiboŝet loĝis en Jerusalem, ĉar li ĉiam manĝadis ĉe la tablo de la reĝo. Kaj li estis lama je siaj ambaŭ piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Okazis poste, ke mortis la reĝo de la Amonidoj, kaj lia filo Ĥanun fariĝis reĝos anstataŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Tiam David diris: Mi estos favorkora al Ĥanun, filo de Naĥaŝ, konforme al tio, kiel lia patro agis favorkore koncerne min. Kaj David sendis, por konsoli lin per siaj servantoj pri lia patro. Kaj la servantoj de David venis en la landon de la Amonidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'Sed la eminentuloj de la Amonidoj diris al sia sinjoro Ĥanun: Ĉu efektive David deziras honori vian patron antaŭ vi, ke li sendis al vi konsolantojn? ĉu ne por pristudi la urbon, esplorrigardi kaj ruinigi ĝin, David sendis al vi siajn servantojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Tiam Ĥanun prenis la servantojn de David, kaj forrazis al ili duonon de la barbo, kaj detranĉis iliajn vestojn ĝis duono, ĝis la lumboj, kaj foririgis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Kiam oni tion raportis al David, li sendis al ili renkonte, ĉar tiuj homoj tre hontis. Kaj la reĝo diris: Restu en Jeriĥo, ĝis rekreskos viaj barboj, kaj tiam revenu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Kiam la Amonidoj vidis, ke ili indignigis Davidon, tiam la Amonidoj sendis kaj dungis Sirianojn el Bet-Reĥob kaj Sirianojn el Coba, dudek mil piedirantojn, kaj de la reĝo de Maaĥa mil homojn kaj de Tob dek du mil homojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Kiam David aŭdis pri tio, li sendis Joabon kaj la tutan armeon da kuraĝuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Kaj eliris la Amonidoj kaj batalaranĝiĝis ĉe la enirejo de la pordego; kaj la Sirianoj el Coba kaj el Reĥob kaj la viroj de Tob kaj de Maaĥa estis aparte, sur la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Kiam Joab vidis, ke li havos kontraŭ si batalon antaŭe kaj malantaŭe, li faris elekton el ĉiuj plejbravuloj en Izrael kaj batalaranĝis ilin kontraŭ la Sirianoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'kaj la ceteran parton de la popolo li komisiis al sia frato Abiŝaj, kaj batalaranĝis ilin kontraŭ la Amonidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'Kaj li diris: Se la Sirianoj superfortos min, tiam vi donos al mi helpon; sed se la Amonidoj superfortos vin, tiam mi iros, por helpi vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Estu kuraĝa, kaj ni tenu nin forte por nia popolo kaj por la urboj de nia Dio; kaj la Eternulo faru tion, kio plaĉos al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Kaj Joab, kun la popolo, kiu estis kun li, komencis la batalon kontraŭ la Sirianoj; kaj ĉi tiuj forkuris antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Kiam la Amonidoj vidis, ke la Sirianoj forkuris, ili ankaŭ forkuris antaŭ Abiŝaj, kaj foriris en la urbon. Tiam Joab returnis sin de la Amonidoj, kaj venis Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Kiam la Sirianoj vidis, ke ili estas venkobatitaj de la Izraelidoj, ili kolektiĝis en unu loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'Kaj Hadadezer sendis, kaj elirigis la Sirianojn transriverajn; kaj ili venis en Ĥelamon; kaj Ŝobaĥ, militestro de Hadadezer, ilin kondukis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Kiam tio estis raportita al David, li kolektis ĉiujn Izraelidojn, kaj transiris Jordanon kaj venis en Ĥelamon. Kaj la Sirianoj aranĝis sin kontraŭ David kaj ekbatalis kontraŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Kaj la Sirianoj forkuris antaŭ Izrael, kaj David mortigis el la Sirianoj sepcent ĉaristojn kaj kvardek mil rajdantojn; ankaŭ Ŝobaĥon, la militestron, li frapis, kaj tiu mortis tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Kiam ĉiuj reĝoj, kiuj servis Hadadezeron, vidis, ke ili estas venkobatitaj de la Izraelidoj, ili faris pacon kun la Izraelidoj kaj submetiĝis al ili. Kaj la Sirianoj timis helpi plu al la Amonidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Post unu jaro, en la tempo, kiam la reĝoj eliras milite, David sendis Joabon kune kun siaj servantoj kaj kun ĉiuj Izraelidoj; kaj ili faris ruinigadon inter la Amonidoj, kaj sieĝis Raban. Sed David restis en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Okazis, ke vespere David leviĝis de sia kuŝejo kaj ekpromenis sur la tegmento de la reĝa domo; kaj li ekvidis de la tegmento virinon, kiu sin lavis; kaj la virino estis tre belaspekta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'Kaj David sendis, por demandi pri la virino; kaj oni diris al li, ke ŝi estas Bat-Ŝeba, filino de Eliam, kaj edzino de Urija, la Ĥetido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Tiam David sendis senditojn, por preni ŝin; kaj ŝi venis al li, kaj li kuŝis kun ŝi; kiam ŝi repuriĝis de sia malpureco, ŝi revenis en sian domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'Kaj la virino gravediĝis, kaj ŝi sendis, por sciigi Davidon, dirante: Mi gravediĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Tiam David sendis al Joab, por diri: Sendu al mi Urijan, la Ĥetidon. Kaj Joab sendis Urijan al David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Kiam Urija venis al li, David demandis pri la farto de Joab kaj pri la farto de la popolo kaj pri la sukceso de la milito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Kaj David diris al Urija: Iru en vian domon, kaj lavu viajn piedojn. Kaj Urija eliris el la domo de la reĝo, kaj lin sekvis donacoj de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Sed Urija dormis ĉe la enirejo de la domo de la reĝo, kune kun ĉiuj servantoj de lia sinjoro, kaj li ne iris en sian domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Kaj oni raportis al David, dirante: Urija ne iris en sian domon. Tiam David diris al Urija: Vi venis ja de la vojo; kial do vi ne iris en vian domon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Kaj Urija respondis al David: La kesto kaj Izrael kaj Jehuda troviĝas en tendoj, kaj mia sinjoro Joab kaj la servantoj de mia sinjoro bivakas sur la kampo; kaj ĉu mi irus en mian domon, por manĝi kaj trinki, kaj kuŝi kun mia edzino? mi ĵuras per via vivo kaj per la vivo de via animo, ke mi ne faros tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Tiam David diris al Urija: Restu ĉi tie ankoraŭ hodiaŭ, kaj morgaŭ mi forliberigos vin. Kaj Urija restis en Jerusalem tiun tagon kaj la sekvantan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Kaj David invitis lin, ke li manĝu kaj trinku ĉe li, kaj ebriigis lin. Vespere li eliris, por dormi sur sia kuŝejo kun la servantoj de sia sinjoro, sed en sian domon li ne iris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Matene David skribis leteron al Joab, kaj sendis ĝin per Urija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'Kaj en la letero li skribis jenon: Metu Urijan en la fronton de la plej forta batalo, kaj deturniĝu de li, ke li estu frapita kaj mortu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Tial, kiam Joab sieĝis la urbon, li metis Urijan sur la lokon, pri kiu li sciis, ke tie estas la plej fortaj viroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Kiam la loĝantoj de la urbo eliris kaj ekbatalis kontraŭ Joab, falis kelka nombro el la servantoj de David; kaj mortis ankaŭ Urija, la Ĥetido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Joab sendis kaj raportigis al David ĉiujn cirkonstancojn de la batalo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'Kaj al la sendito li donis jenan ordonon: Kiam vi finos raporti al la reĝo ĉiujn cirkonstancojn de la batalo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'kaj la reĝo ekkoleros, kaj diros: Kial vi alproksimiĝis al la urbo, por batali? ĉu vi ne sciis, ke oni pafos de la muro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'kiu mortigis Abimeleĥon, filon de Jerubeŝet? ĉu ne virino ĵetis sur lin de la muro muelŝtonon, ke li mortis en Tebec? kial vi alproksimiĝis al la muro? tiam diru: Ankaŭ via servanto Urija, la Ĥetido, mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'La sendito iris, kaj venis kaj raportis al David ĉion, por kio sendis lin Joab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Kaj la sendito diris al David: Kiam tiuj homoj montriĝis pli fortaj ol ni kaj eliris kontraŭ nin sur la kampon, ni komencis premi ilin al la enirejo en la pordegon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'tiam la pafistoj pafis sur viajn servantojn de sur la muro, kaj pereis kelkaj el la servantoj de la reĝo, kaj ankaŭ via servanto Urija, la Ĥetido, mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Tiam David diris al la sendito: Tiel diru al Joab: Ne afliktiĝu pro tio, ke la glavo formanĝas jen tiun, jen alian; plifortigu vian militon kontraŭ la urbo kaj detruu ĝin, kaj estu kuraĝa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Kiam la edzino de Urija aŭdis, ke mortis ŝia edzo Urija, ŝi funebris pro sia edzo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Kiam pasis la funebro, David sendis, kaj prenis ŝin en sian domon; kaj ŝi fariĝis lia edzino, kaj ŝi naskis al li filon. Sed la faro, kiun faris David, malplaĉis al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Kaj la Eternulo sendis al David Natanon, kaj ĉi tiu venis al li, kaj diris al li: En unu urbo estis du viroj, unu riĉulo kaj la dua malriĉulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'la riĉulo havis tre multe da ŝafoj kaj da bovoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'kaj la malriĉulo havis nenion, krom unu malgranda ŝafeto, kiun li aĉetis kaj nutris, kaj ĝi elkreskis ĉe li kaj ĉe liaj infanoj kune kun ili; el lia peco ĝi manĝadis, el lia kaliko ĝi trinkadis, kaj sur lia sino ĝi dormadis, kaj ĝi estis por li kiel filino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Sed venis gasto al la riĉa homo, kaj ĉi tiu domaĝis preni el siaj ŝafoj aŭ el siaj bovoj, por prepari ion por la gasto, kiu venis al li, kaj li prenis la ŝafeton de la viro malriĉa, kaj preparis ĝin por la homo, kiu venis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Tiam forte ekflamis la kolero de David kontraŭ tiu homo, kaj li diris al Natan: Mi ĵuras per la Eternulo, ke morti devas la homo, kiu tion faris;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'kaj pro la ŝafeto li repagu kvaroble, pro tio, ke li faris tion kaj ke li agis senkompate.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Tiam Natan diris al David: Vi estas tiu homo. Tiele diris la Eternulo, Dio de Izrael: Mi sanktoleis vin reĝo super Izrael, kaj Mi savis vin el la mano de Saul,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'kaj Mi donis al vi la domon de via sinjoro kaj la edzinojn de via sinjoro sur vian sinon, kaj Mi donis al vi la domon de Izrael kaj Jehuda; kaj se tio ne sufiĉus, Mi aldonus ankoraŭ tion kaj alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Kial do vi malŝatis la vorton de la Eternulo, farante malbonon antaŭ Liaj okuloj? Urijan, la Ĥetidon, vi mortigis per glavo, kaj lian edzinon vi prenis al vi kiel edzinon, post kiam vi lin mortigis per glavo de la Amonidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Nun ne malaperos el via domo la glavo eterne, pro tio, ke vi malŝatis Min, kaj prenis la edzinon de Urija, la Ĥetido, ke ŝi estu via edzino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Tiele diris la Eternulo: Jen Mi venigos sur vin malbonon el via domo; kaj Mi prenos viajn edzinojn antaŭ viaj okuloj, kaj fordonos al via konkuranto, kaj li kuŝos kun viaj edzinoj antaŭ ĉi tiu suno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Ĉar vi agis sekrete; sed Mi faros tiun aferon antaŭ la tuta Izrael kaj antaŭ la suno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Tiam David diris al Natan: Mi pekis antaŭ la Eternulo. Kaj Natan diris al David: La Eternulo forigis vian pekon, vi ne mortos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'sed ĉar vi per tiu faro incitis la malamikojn de la Eternulo, tial la filo, kiu naskiĝis al vi, mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Kaj Natan iris en sian domon. Kaj la Eternulo frapis la infanon, kiun la edzino de Urija naskis al David, kaj ĝi danĝere malsaniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'Kaj David ekpreĝis al la Eternulo pri la infano; kaj David fastis, kaj li eniris, kaj pasigis la nokton sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Kaj ekinsistis super li la plejaĝuloj de lia domo, por igi lin leviĝi de la tero; sed li ne volis, kaj li ne manĝis kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'En la sepa tago la infano mortis. Kaj la servantoj de David timis sciigi al li, ke la infano mortis; ĉar ili pensis: Jen dum la infano ankoraŭ vivis, ni parolis al li, kaj li ne aŭskultis nian voĉon; kiel do ni diros al li, ke la infano mortis? li faros ian malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Sed kiam David vidis, ke liaj servantoj murmuretas inter si, li komprenis, ke la infano mortis; kaj David diris al siaj servantoj: Ĉu la infano mortis? Kaj ili respondis: Ĝi mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Tiam David leviĝis de la tero, lavis sin kaj oleis sin kaj ŝanĝis siajn vestojn, kaj iris en la domon de la Eternulo, kaj adorkliniĝis. Poste li venis en sian domon; li petis, ke oni donu al li panon, kaj li manĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Tiam diris al li liaj servantoj: Kion signifas tio, kion vi faris? dum la infano estis ankoraŭ vivanta, vi fastis kaj ploris; kaj kiam la infano mortis, vi leviĝis kaj manĝis!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Kaj li respondis: Dum la infano ankoraŭ vivis, mi fastis kaj ploris; ĉar mi pensis: Kiu scias? eble la Eternulo indulgos min kaj la infano vivos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Sed nun ĝi mortis; por kio do mi fastos? ĉu mi povas ankoraŭ revenigi ĝin? mi iros al ĝi, sed ĝi ne revenos al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Kaj David konsolis sian edzinon Bat-Ŝeba, kaj envenis al ŝi kaj kuŝis kun ŝi; kaj ŝi naskis filon, kaj li donis al li la nomon Salomono; kaj la Eternulo lin amis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'Kaj li transdonis lin en la manojn de la profeto Natan; ĉi tiu donis al li la nomon Jedidja, pro la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Joab ekmilitis kontraŭ Raba de la Amonidoj, kaj venkoprenis la reĝan urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Kaj Joab sendis senditojn al David, kaj dirigis: Mi militis kontraŭ Raba, kaj mi venkoprenis la urbon de akvoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'nun kolektu la reston de la popolo, kaj sieĝu la urbon kaj prenu ĝin; ĉar alie, se mi prenus la urbon, oni nomus ĝin per mia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'Tiam David kolektis la tutan popolon, kaj iris al Raba, kaj militis kontraŭ ĝi kaj prenis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Kaj li prenis la kronon de Malkam de lia kapo; ĝi havis la pezon de kikaro da oro; en ĝi estis multekosta ŝtono, kiu transiris sur la kapon de David. Kaj da militakiraĵo li elportis el la urbo tre multe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Kaj la popolon, kiu tie estis, li elirigis, kaj metis ĝin al segiloj kaj al feraj draŝiloj kaj al feraj hakiloj kaj forkondukis al brikfarejoj. Tiele li agis kun ĉiuj urboj de la Amonidoj. Kaj David kaj la tuta popolo revenis Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Poste okazis jeno: Abŝalom, filo de David, havis belan fratinon, kies nomo estis Tamar; ŝin ekamis Amnon, filo de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Kaj Amnon suferis multe kaj preskaŭ malsaniĝis pro sia fratino Tamar; ĉar ŝi estis virgulino, kaj al Amnon ŝajnis malfacile fari ion al ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Sed Amnon havis amikon, kies nomo estis Jonadab, filo de Ŝimea, frato de David; kaj Jonadab estis homo tre saĝa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Kaj li diris al li: Kial vi tiel malgrasiĝas, ho reĝido, kun ĉiu tago? ĉu vi ne diros al mi? Kaj Amnon diris al li: Tamaron, fratinon de mia frato Abŝalom, mi amas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Tiam Jonadab diris al li: Kuŝiĝu en vian liton, kaj ŝajnigu vin malsana; kaj kiam venos via patro, por vidi vin, diru al li: Mi petas, ke mia fratino Tamar venu, kaj ŝi donu al mi manĝi kaj ŝi pretigu antaŭ mi la manĝaĵon, por ke mi vidu kaj mi manĝu el ŝiaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Amnon kuŝiĝis, kaj ŝajnigis sin malsana; kaj venis la reĝo, por vidi lin, kaj Amnon diris al la reĝo: Mi petas, ke venu mia fratino Tamar, kaj ke ŝi pretigu antaŭ miaj okuloj du kuketojn, por ke mi manĝu el ŝiaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Tiam David sendis al Tamar en la domon, por diri: Iru, mi petas, en la domon de via frato Amnon, kaj pretigu al li manĝaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Kaj Tamar iris en la domon de sia frato Amnon; li kuŝis. Kaj ŝi prenis paston, knedis ĝin, preparis antaŭ liaj okuloj, kaj bakis la kuketojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Kaj ŝi prenis la paton, kaj elskuis antaŭ li; sed li ne volis manĝi. Kaj Amnon diris: Forigu de mi ĉiujn. Kaj ĉiuj eliris de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Tiam Amnon diris al Tamar: Alportu la manĝaĵon en la internan ĉambron, por ke mi manĝu el viaj manoj. Tamar prenis la kuketojn, kiujn ŝi faris, kaj alportis ilin al sia frato Amnon en la internan ĉambron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Sed, kiam ŝi ilin alportis al li por manĝi, li kaptis ŝin, kaj diris al ŝi: Venu, kuŝiĝu kun mi, mia fratino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Tiam ŝi diris al li: Ne, mia frato, ne perfortu min; ĉar tiel ne estas farate en Izrael; ne faru tian malnoblaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Kien mi irus kun mia malhonoro? kaj vi fariĝus kiel iu el la malnobluloj en Izrael. Parolu kun la reĝo, mi petas; kaj li ne rifuzos min al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Sed li ne volis obei ŝiajn vortojn, kaj kaptis ŝin kaj perfortis ŝin kaj kuŝis kun ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Post tio Amnon ekmalamis ŝin per tre granda malamo; pli granda estis la malamo, kiun li eksentis al ŝi, ol la amo, kiun li antaŭe havis por ŝi. Kaj Amnon diris al ŝi: Leviĝu, foriru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Kaj ŝi diris al li: Se vi forpelas min, tiam ĉi tiu granda malbono estas pli granda, ol la alia, kiun vi faris al mi. Sed li ne volis aŭskulti ŝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Kaj li alvokis sian junulon-servanton, kaj diris: Forpelu de mi ĉi tiun for, kaj ŝlosu la pordon post ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Ŝi havis sur si diverskoloran veston, ĉar per tiaj tunikoj vestadis sin la filinoj de la reĝo. Kaj lia servanto elkondukis ŝin eksteren kaj ŝlosis la pordon post ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Tiam Tamar prenis cindron sur sian kapon, kaj la diverskoloran veston, kiu estis sur ŝi, ŝi disŝiris; kaj ŝi metis sian manon sur sian kapon, kaj iris kaj kriis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Kaj diris al ŝi ŝia frato Abŝalom: Ĉu via frato Amnon estis kun vi? nun, mia fratino, silentu; li estas via frato; ne tro afliktiĝu pro tiu afero. Kaj Tamar restis malĝoja en la domo de sia frato Abŝalom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Kiam la reĝo David aŭdis ĉion ĉi tion, li tre koleris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Abŝalom parolis kun Amnon nek malbonon nek bonon; ĉar Abŝalom malamis Amnonon pro tio, ke li perfortis lian fratinon Tamar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Okazis post du jaroj, ke oni tondis la ŝafojn ĉe Abŝalom en Baal- Ĥacor, kiu estas apud Efraim; kaj Abŝalom invitis ĉiujn filojn de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Kaj Abŝalom venis al la reĝo, kaj diris: Jen oni tondas ĉe via sklavo; mi petas, ke la reĝo kun siaj servantoj venu al via sklavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Sed la reĝo diris al Abŝalom: Ne, mia filo, ni ne iros ĉiuj, por ke ni ne estu ŝarĝo por vi. Tiu insiste lin petis; sed li ne volis iri, li nur benis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Tiam Abŝalom diris: Se ne, tiam almenaŭ mia frato Amnon iru kun ni. Kaj la reĝo diris al li: Por kio li iru kun vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Sed Abŝalom insiste lin petis; tial li lasis iri kun li Amnonon kaj ĉiujn filojn de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Kaj Abŝalom ordonis al siaj servantoj jene: Rigardu, mi petas, kiam la koro de Amnon gajiĝos de vino, kaj mi diros al vi, ke vi frapu Amnonon, tiam mortigu lin, ne timu; ĉar ja mi ordonis al vi; estu senhezitaj kaj kuraĝaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Kaj la servantoj de Abŝalom faris al Amnon, kiel ordonis Abŝalom. Tiam leviĝis ĉiuj filoj de la reĝo, kaj sidiĝis ĉiu sur sia mulo kaj forkuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Kiam ili estis ankoraŭ sur la vojo, al David venis la famo, ke Abŝalom mortigis ĉiujn filojn de la reĝo kaj neniu el ili restis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'La reĝo leviĝis, kaj disŝiris siajn vestojn, kaj kuŝiĝis sur la tero; kaj ĉiuj liaj servantoj staris kun disŝiritaj vestoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Tiam ekparolis Jonadab, filo de Ŝimea, frato de David, kaj diris: Mia sinjoro ne diru, ke ĉiuj junuloj filoj de la reĝo estas mortigitaj; ĉar nur Amnon sola mortis; ĉar ĉe Abŝalom tio estis decidita de post la tago, kiam tiu perfortis lian fratinon Tamar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Kaj nun mia sinjoro la reĝo ne atentu la famon, kiu diras, ke ĉiuj filoj de la reĝo mortis; nur Amnon sola mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Dume Abŝalom forkuris. La gardostaranta servanto levis siajn okulojn, kaj ekvidis, ke multe da homoj iras de la vojo malantaŭa laŭ la deklivo de la monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Kaj Jonadab diris al la reĝo: Jen la filoj de la reĝo venas; kiel via sklavo diris, tiel fariĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Kiam li finis paroli, venis la filoj de la reĝo, kaj ili levis sian voĉon kaj ploris; kaj ankaŭ la reĝo kaj ĉiuj liaj servantoj ploris per tre granda ploro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Sed Abŝalom forkuris, kaj venis al Talmaj, filo de Amihud, reĝo de Geŝur. Kaj David funebris pro sia filo dum la tuta tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Abŝalom forkuris, kaj iris Geŝuron, kaj restis tie dum tri jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Kaj la reĝo David forte sopiris al Abŝalom; ĉar li konsoliĝis pri la morto de Amnon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Joab, filo de Ceruja, rimarkis, ke la koro de la reĝo plifavoriĝis por Abŝalom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Kaj Joab sendis en Tekoan kaj venigis de tie saĝan virinon, kaj diris al ŝi: Ŝajnigu vin funebranta kaj metu sur vin funebrajn vestojn, kaj ne ŝmiru vin per oleo, kaj estu kiel virino, kiu jam de longe funebras pro mortinto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'kaj venu al la reĝo, kaj diru al li jenon; kaj Joab inspiris al ŝi, kion ŝi devas diri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Kaj la virino el Tekoa ekparolis al la reĝo, kaj ĵetis sin vizaĝaltere kaj adorkliniĝis, kaj diris: Helpu min, ho reĝo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'Kaj la reĝo diris al ŝi: Kio estas al vi? Kaj ŝi respondis: Ho ve, mi estas vidvino, mia edzo mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Sed via sklavino havis du filojn; ili ambaŭ ekkverelis sur la kampo, kaj ĉar estis inter ili neniu savanto, unu frapis la alian kaj mortigis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'Kaj jen leviĝis kontraŭ vian sklavinon la tuta familio, dirante: Eldonu la fratmortiginton, por ke ni mortigu lin pro la animo de lia frato, kiun li mortigis, kaj ni ekstermu ankaŭ la heredanton. Tiel ili volas estingi mian karbon, kiu ankoraŭ restis, por ne restigi al mia edzo nomon nek ian restaĵon sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Tiam la reĝo diris al la virino: Iru hejmen, kaj mi donos ordonon pri vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Sed la virino el Tekoa diris al la reĝo: Sur mi, mia sinjoro, ho reĝo, estu la krimo, kaj sur la domo de mia patro; sed la reĝo kaj lia trono estas senkulpaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Kaj la reĝo diris: Alkonduku al mi tiun, kiu parolas kontraŭ vi, kaj li ne plu tuŝos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Kaj ŝi diris: La reĝo volu memori pri la Eternulo, lia Dio, por ke la sangovenĝantoj ne faru pli da pereo kaj ne ekstermu mian filon. Li diris: Mi ĵuras per la Eternulo, ke ne falos eĉ haro de via filo sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Kaj la virino diris: Permesu, ke via sklavino diru vorton al mia sinjoro la reĝo. Li diris: Parolu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Kaj la virino diris: Kial do vi tiel pensas pri la popolo de Dio? eldirante tian vorton, la reĝo fariĝas kvazaŭ kulpulo, ke li ne revenigas sian elpeliton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Ĉar ni devas morti, kaj ni similas al akvo, kiu estas verŝata sur la teron kaj kiun oni ne povas enkolekti; sed Dio ne volas pereigi animon; Li pripensas, ke forpuŝito ne estu forpuŝata ankaŭ de Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Nur nun mi venis, por diri tion al la reĝo, mia sinjoro, ĉar la popolo min timigis; sed via sklavino diris al si: Mi provos paroli al la reĝo; eble la reĝo plenumos la vorton de sia sklavino;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'eble la reĝo aŭskultos, por savi sian sklavinon el la mano de tiu homo, kiu volas ekstermi min kaj mian filon kune el la heredaĵo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Kaj via sklavino diris al si: La vorto de mia sinjoro la reĝo donos trankvilecon; ĉar kiel anĝelo de Dio, tiel estas mia sinjoro la reĝo, por distingi la bonon kaj malbonon; kaj la Eternulo, via Dio, estos kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Tiam ekparolis la reĝo, kaj diris al la virino: Mi petas, kaŝu antaŭ mi nenion, pri kio mi demandos vin. Kaj la virino diris: Mia sinjoro la reĝo volu paroli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Kaj la reĝo diris: Ĉu ne la mano de Joab estas kun vi en ĉio ĉi tio? Kaj la virino respondis kaj diris: Vere, kiel vivas via animo, mia sinjoro, ho reĝo, ne estas eble dekliniĝi dekstren nek maldekstren de ĉio, kion diris mia sinjoro la reĝo; ĉar via sklavo Joab tion ordonis al mi, kaj li inspiris al via sklavino ĉiujn ĉi tiujn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'Por aliformigi la aspekton de la afero, via sklavo Joab tion faris; sed mia sinjoro estas saĝa per saĝeco de anĝelo de Dio, kaj scias ĉion, kio estas sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Tiam la reĝo diris al Joab: Jen mi tion faris; iru do kaj revenigu la junulon Abŝalom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Joab ĵetis sin vizaĝaltere kaj adorkliniĝis, kaj dankis la reĝon. Kaj Joab diris: Hodiaŭ via sklavo scias, ke mi akiris vian favoron, mia sinjoro, ho reĝo, ĉar la reĝo plenumis la vorton de sia sklavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Kaj Joab leviĝis, kaj iris en Geŝuron, kaj venigis Abŝalomon en Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Sed la reĝo diris: Li reiru en sian domon, sed mian vizaĝon li ne vidu. Kaj Abŝalom revenis en sian domon, sed la vizaĝon de la reĝo li ne vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'En la tuta Izrael estis neniu homo tiel famege bela, kiel Abŝalom: de la plando de lia piedo ĝis lia verto estis en li nenia mallaŭdindaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'Kaj kiam li tondis sian kapon (li tondadis ĉiujare, ĉar la haroj fariĝadis por li tro pezaj, kaj estis necese tondi), la haroj de lia kapo pezis ducent siklojn laŭ la reĝa pesilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Al Abŝalom naskiĝis tri filoj, kaj unu filino, kies nomo estis Tamar; ŝi estis virino belaspekta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Abŝalom restis en Jerusalem du jarojn, kaj la vizaĝon de la reĝo li ne vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Kaj Abŝalom sendis al Joab, por sendi lin al la reĝo; sed tiu ne volis veni al li. Li sendis ankoraŭ duan fojon, sed tiu ne volis veni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Tiam li diris al siaj servantoj: Rigardu la kampoparton de Joab apud mia; li havas tie hordeon; iru, kaj forbruligu ĝin per fajro. Kaj la servantoj de Abŝalom forbruligis la kampoparton per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Tiam Joab leviĝis, kaj venis al Abŝalom en la domon, kaj diris al li: Kial viaj servantoj forbruligis per fajro mian kampoparton?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Abŝalom respondis al Joab: Jen mi sendis al vi, por diri al vi: Venu ĉi tien, por ke mi sendu vin al la reĝo, por demandi, kial mi venis el Geŝur; pli bone estus por mi resti tie. Nun mi volas vidi la vizaĝon de la reĝo; kaj se mi havas en mi krimon, li mortigu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Kaj Joab iris al la reĝo, kaj diris al li tion; kaj ĉi tiu alvokis Abŝalomon, kiu venis al la reĝo, kaj adorkliniĝis vizaĝaltere antaŭ la reĝo; kaj la reĝo kisis Abŝalomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Post tio Abŝalom havigis al si ĉaron kaj ĉevalojn kaj kvindek virojn, kiuj kuradis antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Kaj Abŝalom leviĝadis frue, kaj stariĝadis ĉe la vojo al la pordego; kaj ĉiun homon, kiu havis plendon kaj iris al la reĝo por juĝo, Abŝalom vokis al si, kaj diris al li: El kiu urbo vi estas? Kaj kiam tiu respondis: Via sklavo estas el tiu aŭ tiu tribo de Izrael,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Abŝalom diris al li: Via afero estas bona kaj justa, sed ne ekzistas por vi aŭskultanto ĉe la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Kaj plue Abŝalom parolis: Ho, kiu farus min juĝisto en la lando, por ke al mi venu ĉiu homo, kiu havas plendon aŭ juĝan aferon, kaj por ke mi faru al li juston!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Kaj kiam iu alproksimiĝis, por adorkliniĝi antaŭ li, li etendis sian manon, kaptis lin, kaj kisis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Tiel Abŝalom agis kun ĉiuj Izraelidoj, kiuj iris por juĝo al la reĝo; kaj Abŝalom ŝtele allogis al si la korojn de la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Atinginte la aĝon de kvardek jaroj, Abŝalom diris al la reĝo: Permesu al mi iri kaj plenumi en Ĥebron mian sanktan promeson, kiun mi faris al la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'ĉar sanktan promeson faris via sklavo, kiam mi estis en Geŝur en Sirio, nome: Se la Eternulo revenigos min en Jerusalemon, mi faros oferon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Kaj la reĝo diris al li: Iru en paco. Kaj li leviĝis, kaj iris Ĥebronon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Kaj Abŝalom sendis esplorrigardantojn al ĉiuj triboj de Izrael kun la sekvanta instrukcio: Kiam vi aŭdos la sonon de trumpeto, tiam diru: Abŝalom fariĝis reĝo en Ĥebron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Kune kun Abŝalom iris ducent viroj el Jerusalem; ili estis invititaj, kaj iris sen ia kulpa intenco, nenion sciante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Kaj Abŝalom sendis inviti ankaŭ Aĥitofelon, la Giloanon, la konsiliston de David, el lia urbo Gilo, kiam li estis faranta la buĉoferojn. Tiam la konspiro plifortiĝis, kaj la popolo ĉiam pli kaj pli amase iris al Abŝalom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Dume venis raportanto al David, kaj diris: La koroj de la Izraelidoj turniĝis al Abŝalom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Tiam David diris al ĉiuj siaj servantoj, kiuj estis kun li en Jerusalem: Leviĝu, kaj ni forkuru, ĉar alie ni ne povos saviĝi kontraŭ Abŝalom; rapidu foriri, por ke li, rapidinte, ne atingu nin, ne venigu sur nin malfeliĉon, kaj ne pereigu la urbon per glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Kaj la servantoj de la reĝo diris al la reĝo: Kion ajn elektos nia sinjoro la reĝo, ni estas viaj sklavoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'Tiam la reĝo kaj lia tuta domo eliris piede, kaj la reĝo restigis la dek kromvirinojn, por gardi la domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Kaj la reĝo, kun la tuta popolo, kiu sekvis lin, eliris; kaj ili haltis ĉe malproksima domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'Kaj ĉiuj liaj servantoj preteriris preter li, kaj ĉiuj Keretidoj kaj Peletidoj, kaj ĉiuj Gatanoj, sescent viroj, kiuj sekvis lin el Gat, preteriris antaŭ la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Kaj la reĝo diris al Itaj, la Gatano: Kial vi ankaŭ iras kun ni? iru returne kaj restu kun la reĝo, ĉar vi estas fremdulo kaj vi estas elŝirita el via loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Hieraŭ vi venis; kaj ĉu mi povas hodiaŭ altrudi al vi la iradon kun ni? mi iras, kien mi povas iri. Iru returne, kaj rekonduku viajn fratojn kun vi; favorkoreco kaj justeco estu al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Sed Itaj respondis al la reĝo kaj diris: Mi ĵuras per la Eternulo kaj per mia sinjoro la reĝo: nur en tiu loko, en kiu estos mia sinjoro la reĝo, ĉu por vivo, ĉu por morto, nur tie estos via sklavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'Tiam David diris al Itaj: Venu, kaj preteriru. Kaj preteriris Itaj, la Gatano, kaj ĉiuj liaj viroj, kune kun ĉiuj infanoj, kiuj estis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Kaj ĉiuj ploris per laŭta voĉo, kaj la tuta popolo preteriris. Kaj la reĝo transiris la torenton Kidron, kaj la tuta popolo iris antaŭen laŭ la vojo al la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'Aperis ankaŭ Cadok, kune kun ĉiuj Levidoj, kiuj portis la keston de interligo de Dio; kaj ili starigis la keston de Dio; kaj Ebjatar staris pli alte, ĝis preteriris la tuta popolo el la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Kaj la reĝo diris al Cadok: Revenigu la keston de Dio en la urbon. Se mi akiros favoron de la Eternulo, tiam Li revenigos min kaj vidigos al mi ĝin kaj Sian loĝejon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'sed se Li diros: Vi ne plaĉas al Mi, tiam mi estas preta; Li faru kun mi, kiel plaĉas al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Kaj la reĝo diris al la pastro Cadok: Vi estas antaŭvidema; reiru en paco en la urbon, kaj via filo Aĥimaac, kaj Jonatan, filo de Ebjatar, ambaŭ viaj filoj, iru kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Vidu, mi restos sur la ebenaĵoj de la dezerto, ĝis venos io de vi, por sciigi al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Tiam Cadok kaj Ebjatar reportis la keston de Dio en Jerusalemon, kaj ili tie restis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'Kaj David supreniris sur la monton de olivoj, irante kaj plorante; lia kapo estis kovrita, kaj li iris nudpieda; kaj la tuta popolo, kiu estis kun li, kovris ĉiu sian kapon kaj iris supren, senĉese plorante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Kiam oni diris al David, ke Aĥitofel estas inter la konspirantoj kun Abŝalom, David diris: Mi petas Vin, ho Eternulo, malsaĝigu la konsilon de Aĥitofel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'David venis sur la supron, kie oni adorkliniĝas al Dio; kaj jen renkonte al li iras Ĥuŝaj, la Arkano; lia vesto estas disŝirita, kaj tero estas sur lia kapo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'Kaj David diris al li: Se vi iros kun mi, vi estos por mi ŝarĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'sed se vi reiros en la urbon, kaj diros al Abŝalom: Mi estos via sklavo, ho reĝo; kiel mi estis la sklavo de via patro delonge, tiel mi de nun estos via sklavo-tiam vi detruos por mi la konsilon de Aĥitofel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Tie estos kun vi la pastroj Cadok kaj Ebjatar; kaj ĉion, kion vi aŭdos en la domo de la reĝo, diru al la pastroj Cadok kaj Ebjatar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Jen tie estas kun ili iliaj du filoj, Aĥimaac ĉe Cadok, kaj Jonatan ĉe Ebjatar; per ili vi transsendos al mi ĉion, kion vi aŭdos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Kaj Ĥuŝaj, amiko de David, venis en la urbon. Ankaŭ Abŝalom venis Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'Kiam David iom malsupreniris de la supro, jen venis al li renkonte Ciba, la servanto de Mefiboŝet, kun paro da selitaj azenoj, sur kiuj estis ducent panoj kaj cent sekvinberaj kukoj kaj cent sekigitaj fruktoj kaj felsako kun vino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Kaj la reĝo diris al Ciba: Por kio tio estas kun vi? Kaj Ciba respondis: La azenoj estas por la domo de la reĝo, por rajdi sur ili, kaj la pano kaj la fruktoj por la servantoj por manĝi, kaj la vino por trinki por la laciĝintoj en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Kaj la reĝo diris: Kie estas la filo de via sinjoro? Ciba respondis al la reĝo: Li sidas en Jerusalem, ĉar li diras: Nun la domo de Izrael redonos al mi la regnon de mia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Tiam la reĝo diris al Ciba: Nun al vi apartenu ĉio, kion havas Mefiboŝet. Kaj Ciba diris: Mi adorkliniĝas; mi akiru vian favoron, mia sinjoro, ho reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Kiam la reĝo David venis ĝis Baĥurim, jen el tie eliras viro el la familio de la domo de Saul; lia nomo estis Ŝimei, filo de Gera; elirante, li senĉese insultadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'Li ĵetis ŝtonojn sur Davidon kaj sur ĉiujn servantojn de la reĝo David; la tuta popolo kaj ĉiuj fortuloj estis dekstre kaj maldekstre de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'Kaj tiel parolis Ŝimei, insultante: For, for, sangavidulo, malbonagulo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'la Eternulo revenigis sur vin la tutan sangon de la domo de Saul, sur kies loko vi fariĝis reĝo, kaj la Eternulo transdonis la regnon en la manon de via filo Abŝalom; tion vi havas pro via malboneco, ĉar vi estas sangavidulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Tiam Abiŝaj, filo de Ceruja, diris al la reĝo: Kial insultu tiu senviva hundo mian sinjoron, la reĝon? permesu al mi iri kaj dehaki lian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Sed la reĝo diris: Kiel tio koncernas min kaj vin, filoj de Ceruja? li insultu; ĉar la Eternulo diris al li: Insultu Davidon. Kiu povas diri: Kial vi tion faras?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Kaj David diris al Abiŝaj kaj al ĉiuj siaj servantoj: Jen mia filo, kiu eliris el mia interno, atencas mian animon; tiom pli tion povas fari nun la Benjamenido; lasu lin, kaj li insultu, ĉar la Eternulo tion ordonis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Eble la Eternulo vidos mian mizeron, kaj la Eternulo repagos al mi bonon anstataŭ lia hodiaŭa insultado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'Kaj David kun siaj homoj daŭrigis sian vojon. Kaj Ŝimei iris laŭ la deklivo de la monto, kontraŭ li, iris kaj insultis, ĵetadis ŝtonojn sur lin, kaj ŝutadis sur lin teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'La reĝo kaj la tuta popolo, kiu estis kun li, venis lacaj kaj ripozis tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Dume Abŝalom kaj ĉiuj Izraelidoj venis en Jerusalemon, kaj Aĥitofel kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Kiam Ĥuŝaj, la Arkano, amiko de David, venis al Abŝalom, li diris al Abŝalom: Vivu la reĝo! vivu la reĝo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Kaj Abŝalom diris al Ĥuŝaj: Tia estas via amo al via amiko! kial vi ne iris kun via amiko?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Sed Ĥuŝaj respondis al Abŝalom: Ne, sed kiun elektis la Eternulo kaj ĉi tiu popolo kaj ĉiuj Izraelidoj, al tiu mi apartenos, kaj kun li mi restos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Due, kiun mi servos? ĉu ne lian filon? kiel mi servis vian patron, tiel mi estos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Tiam Abŝalom diris al Aĥitofel: Konsiliĝu inter vi, kion ni devas fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Kaj Aĥitofel diris al Abŝalom: Eniru al la kromvirinoj de via patro, kiujn li restigis, por gardi la domon. Kiam ĉiuj Izraelidoj aŭdos, ke vi abomenigis al vi vian patron, tiam fortiĝos la manoj de ĉiuj, kiuj estas kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Tiam oni starigis por Abŝalom tendon sur la tegmento, kaj Abŝalom eniris al la kromvirinoj de sia patro antaŭ la okuloj de ĉiuj Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'La konsiloj de Aĥitofel, kiujn li donadis en tiu tempo, havis tian valoron, kiel se oni demandus la decidon de Dio; tiaj estis ĉiuj konsiloj de Aĥitofel, kiel por David, tiel ankaŭ por Abŝalom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Kaj Aĥitofel diris al Abŝalom: Permesu al mi elekti dek du mil virojn, kaj mi leviĝos kaj postkuros Davidon en la nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'Mi atakos lin, kiam li estos laca kaj liaj manoj estos malfortaj; mi teruros lin tiel, ke forkuros la tuta popolo, kiu estas kun li; tiam mi mortigos la reĝon solan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'Kaj mi revenigos la tutan popolon al vi; kiam revenos ĉiuj, krom tiu, kiun vi serĉas, tiam al la tuta popolo fariĝos paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Kaj la afero plaĉis al Abŝalom kaj al ĉiuj plejaĝuloj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Tamen Abŝalom diris: Alvoku ankoraŭ Ĥuŝajon, la Arkanon, por ke ni aŭdu ankaŭ tion, kion li diros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Kiam Ĥuŝaj venis al Abŝalom, Abŝalom diris al li: Jen kion diris Aĥitofel; ĉu ni faru tion, kion li diris? se ne, tiam diru vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Tiam Ĥuŝaj diris al Abŝalom: Ne bona estas la konsilo, kiun donis Aĥitofel ĉi tiun fojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Kaj Ĥuŝaj diris plue: Vi konas vian patron kaj liajn virojn, ke ili estas fortuloj; krom tio ili estas koleraj, kiel urso, de kiu oni forrabis la infanojn sur la kampo; kaj via patro estas sperta militisto, kaj li ne dormos nokte kun la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Jen nun li kaŝiĝas en ia kaverno aŭ en ia alia loko. Se en la komenco iu el la niaj falos, kaj disvastiĝos la famo, ke havis malvenkon la popolo, kiu sekvas Abŝalomon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'tiam eĉ la plej kuraĝa, kiu havas koron, similan al la koro de leono, senkuraĝiĝos; ĉar la tuta Izrael scias, kiel fortaj estas via patro, kaj la militistoj, kiuj estas kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Tial mi konsilas: kolektu al vi la tutan Izraelon, de Dan ĝis Beer- Ŝeba, tian multegon, kiel la sablo apud la maro, kaj vi persone iru meze de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Kaj ni atakos lin, en kiu ajn loko li troviĝos, kaj ni surfalos sur lin, kiel falas la roso sur la teron; kaj el li, kun ĉiuj viroj, kiuj estas kun li, ne restos eĉ unu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Kaj se li enfermiĝos en urbo, tiam la tuta Izrael ĉirkaŭigos tiun urbon per ŝnuroj, kaj trenos ĝin en la riveron, ĝis ne restos tie eĉ ŝtoneto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Tiam diris Abŝalom kaj ĉiuj Izraelidoj: La konsilo de Ĥuŝaj, la Arkano, estas pli bona, ol la konsilo de Aĥitofel. Sed la Eternulo decidis detrui la bonan konsilon de Aĥitofel, por ke la Eternulo venigu malfeliĉon sur Abŝalomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Kaj Ĥuŝaj diris al la pastroj Cadok kaj Ebjatar: Tiel kaj tiel konsilis Aĥitofel al Abŝalom kaj al la plejaĝuloj de Izrael, kaj tiel kaj tiel konsilis mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'nun sendu rapide, kaj dirigu al David jenon: Ne pasigu ĉi tiun nokton sur la ebenaĵo de la dezerto, sed transiru, por ke ne pereu la reĝo, kaj la tuta popolo, kiu estas kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Jonatan kaj Aĥimaac staris apud En-Rogel; servantino iris kaj sciigis al ili, por ke ili iru kaj sciigu al la reĝo David, ĉar ili ne devis sin montri kaj veni en la urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Sed ilin ekvidis iu junulo, kaj raportis al Abŝalom; dume ili ambaŭ rapide iris, kaj venis en Baĥurimon en la domon de unu homo, sur kies korto troviĝis puto, kaj ili malsupreniris tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'Kaj lia edzino prenis kaj sternis kovrotukon super la aperturo de la puto kaj ŝutis sur ĝin grion, por ke oni nenion rimarku.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Kiam la servantoj de Abŝalom venis al la virino en la domon, kaj demandis, kie estas Aĥimaac kaj Jonatan, la virino respondis al ili: Ili iris trans la akvujon. Kaj ili serĉis kaj ne trovis, kaj ili revenis Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Kiam ili foriris, tiuj eliris el la puto, kaj iris kaj raportis al la reĝo David, kaj diris al David: Leviĝu, kaj transiru rapide la akvon, ĉar tiel kaj tiel konsilis kontraŭ vi Aĥitofel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Tiam leviĝis David, kaj la tuta popolo, kiu estis kun li, kaj ili transiris Jordanon antaŭ la mateniĝo; kaj restis neniu, kiu ne estus transirinta Jordanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Kiam Aĥitofel vidis, ke oni ne plenumis lian konsilon, li selis azenon, leviĝis kaj iris al sia domo, en sian urbon, faris ordonojn pri sia domo, kaj sufokis sin kaj mortis; kaj oni enterigis lin en la tombo de lia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'Dume David venis en Maĥanaimon, kaj Abŝalom transiris Jordanon, li kaj ĉiuj viroj de Izrael kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Kaj Amasan Abŝalom starigis super la militistaro anstataŭ Joab; Amasa estis filo de viro, kies nomo estis Jitra, el Jizreel, kaj kiu envenis al Abigail, filino de Naĥaŝ, fratino de Ceruja, patrino de Joab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Kaj Izrael kaj Abŝalom stariĝis tendare en la lando Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Kiam David venis en Maĥanaimon, tiam Ŝobi, filo de Naĥaŝ, el Raba de la Amonidoj, kaj Maĥir, filo de Amiel, el Lo-Debar, kaj Barzilaj, la Gileadano, el Roglim,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'alportis litojn kaj tapiŝojn kaj argilajn vazojn, kaj tritikon kaj hordeon kaj farunon kaj rostitajn grajnojn, kaj fabojn kaj lentojn, ankaŭ rostitajn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'kaj mielon kaj buteron kaj ŝafojn kaj fromaĝojn; ili alportis al David, kaj al la popolo, kiu estis kun li, por manĝi; ĉar ili diris: La popolo estas malsata kaj laca kaj soifa en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'David prikalkulis la popolon, kiu estis kun li, kaj starigis super ĝi milestrojn kaj centestrojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'Kaj David metis trionon de la popolo sub la disponon de Joab, kaj trionon sub la disponon de Abiŝaj, filo de Ceruja kaj frato de Joab, kaj trionon sub la disponon de Itaj, la Gatano. Kaj la reĝo diris al la popolo: Mi ankaŭ iros kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Sed la popolo diris: Ne iru; ĉar se ni eĉ forkuros, ili ne tre atentos nin; eĉ se duono de ni mortos, ili ne tre atentos nin; sed vi estas kiel dek mil el ni; tial estas pli bone, ke vi helpu nin el la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Tiam la reĝo diris al ili: Kion vi deziras, tion mi faros. Kaj la reĝo stariĝis apud la pordego, kaj la tuta popolo eliris laŭ centoj kaj miloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Kaj la reĝo ordonis al Joab kaj al Abiŝaj kaj al Itaj: Estu singardaj kun la junulo Abŝalom. Kaj la tuta popolo aŭdis, kiel la reĝo ordonis al ĉiuj estroj koncerne Abŝalomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Kaj la popolo eliris sur la kampon kontraŭ Izraelon, kaj fariĝis batalo en la arbaro de Efraim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Kaj la popolo Izraela estis tie venkobatita de la servantoj de David, kaj tie estis granda venkobato en tiu tago: falis dudek mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'La batalo disvastiĝis tie sur la tutan regionon; kaj la arbaro pereigis pli da homoj, ol ekstermis la glavo en tiu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Kaj Abŝalom renkontiĝis kun la servantoj de David; Abŝalom rajdis sur mulo. Kaj la mulo trafis sub interplektitajn branĉojn de granda kverko, kaj lia kapo alkroĉiĝis al la kverko, kaj li ekpendis inter la ĉielo kaj la tero; kaj la mulo, kiu estis sub li, forkuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Tion ekvidis unu homo, kaj sciigis al Joab, kaj diris: Jen mi vidis Abŝalomon, kiu pendas de kverko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Kaj Joab diris al la homo, kiu raportis al li: Se vi vidis, kial do vi ne batis lin tie sur la teron? mi donus al vi dek arĝentajn monerojn kaj unu zonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Sed la homo diris al Joab: Se vi donus en miajn manojn eĉ mil arĝentajn monerojn, mi ne etendus mian manon kontraŭ la filo de la reĝo; ĉar antaŭ niaj oreloj la reĝo ordonis al vi kaj al Abiŝaj kaj al Itaj, dirante: Gardu al mi la junulon Abŝalom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Kaj se mi farus falsaĵon kontraŭ mia animo, nenio kaŝiĝus antaŭ la reĝo, kaj vi starus flanke.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Joab diris: Mi ne perdos tempon kun vi. Kaj li prenis en sian manon tri lancojn, kaj enpikis ilin en la koron de Abŝalom, kiam ĉi tiu ankoraŭ estis vivanta inter la branĉoj de la kverko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Poste dek junuloj armilportistoj de Joab ĉirkaŭis Abŝalomon, batis, kaj mortigis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Tiam Joab ekblovis per trumpeto, kaj la popolo ĉesis postkuri la Izraelidojn; ĉar Joab haltigis la popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Kaj oni prenis Abŝalomon kaj ĵetis lin en la arbaro en grandan kavon, kaj oni metis super li tre grandan amason da ŝtonoj; kaj ĉiuj Izraelidoj forkuris ĉiu al sia tendo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Sed Abŝalom ankoraŭ dum sia vivo starigis al si monumenton, kiu troviĝas en la Valo de la Reĝo; ĉar li diris: Mi ne havas filon, kiu memorigus pri mia nomo; kaj li nomis la monumenton per sia nomo. Kaj oni nomas ĝin ĝis nun monumento de Abŝalom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Aĥimaac, filo de Cadok, diris: Mi kuros, kaj sciigos al la reĝo, ke la Eternulo faris al li juston kontraŭ liaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Sed Joab diris al li: Ne bona sciiganto vi estos hodiaŭ; vi sciigos en alia tago, kaj hodiaŭ ne sciigu, ĉar mortis la filo de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Kaj Joab diris al Etiopo: Iru, diru al la reĝo, kion vi vidis. La Etiopo adorkliniĝis antaŭ Joab kaj ekkuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Tamen Aĥimaac, filo de Cadok, parolis plue, kaj diris al Joab: Kio ajn estos, permesu ankaŭ al mi kuri post la Etiopo. Sed Joab diris: Por kio vi kuros, mia filo? venu, la sciigo ne estos agrabla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'Kaj li diris: Kio ajn estos, mi kuros. Kaj tiu diris al li: Kuru. Kaj Aĥimaac ekkuris laŭ la vojo de la ebenaĵo, kaj kurantaŭiĝis antaŭ la Etiopon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'David sidis inter la du pordegoj; kaj la gardostaranto iradis sur la tegmento de la pordego, super la muro, kaj, levinte siajn okulojn, li ekvidis, ke jen iu viro sola kuras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Kaj la gardostaranto ekkriis, kaj raportis al la reĝo. Kaj la reĝo diris: Se li estas sola, tiam bona sciigo estas en lia buŝo. Kaj dum tiu ĉiam pli alproksimiĝadis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'la gardostaranto ekvidis, ke ankoraŭ alia viro kuras; kaj la gardostaranto ekkriis al la pordegisto, kaj diris: Jen ankoraŭ iu viro sola kuras. Kaj la reĝo diris: Ankaŭ ĉi tiu havas bonan sciigon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'La gardostaranto diris: Mi vidas la kuradon de la unua, ĝi estas kiel la kurado de Aĥimaac, filo de Cadok. Kaj la reĝo diris: Li estas bona homo, kun bona sciigo li venas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Kaj Aĥimaac ekkriis, kaj diris: Paco al la reĝo! Kaj li adorkliniĝis antaŭ la reĝo vizaĝaltere, kaj diris: Benata estu la Eternulo, via Dio, kiu transdonis la homojn, kiuj levis sian manon kontraŭ mian sinjoron la reĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Kaj la reĝo diris: Ĉu bone fartas la junulo Abŝalom? Aĥimaac respondis: Mi vidis grandan tumulton, kiam Joab sendis la servanton de la reĝo kaj vian sklavon, kaj mi ne scias, kio estis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Tiam la reĝo diris: Deturniĝu, kaj stariĝu tie. Kaj li deturniĝis, kaj stariĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Kaj jen venis la Etiopo, kaj la Etiopo diris: Bonan sciigon mi alportas al mia sinjoro la reĝo; la Eternulo hodiaŭ faris al vi juston kontraŭ ĉiuj, kiuj leviĝis kontraŭ vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Kaj la reĝo diris al la Etiopo: Ĉu bone fartas la junulo Abŝalom? La Etiopo respondis: Kio fariĝis al la junulo, tio fariĝu al la malamikoj de mia sinjoro la reĝo, kaj al ĉiuj, kiuj malbonintence leviĝis kontraŭ vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'Tiam la reĝo malĝojiĝis, kaj li foriris en la superpordegan ĉambreton, kaj ekploris. Kaj, irante, li parolis: Mia filo Abŝalom, mia filo, mia filo Abŝalom! ho, se mi mortus anstataŭ vi, Abŝalom, mia filo, mia filo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Oni sciigis al Joab: Jen la reĝo ploras kaj malĝojas pri Abŝalom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Kaj la triumfo en tiu tago fariĝis funebro por la tuta popolo; ĉar la popolo aŭdis en tiu tago, ke la reĝo malĝojas pri sia filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Kaj la popolo kvazaŭ ŝtelmaniere iris en tiu tago en la urbon, kiel ŝtelmaniere iras homoj hontigitaj per tio, ke ili forkuris el batalo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Kaj la reĝo kovris sian vizaĝon, kaj la reĝo kriadis laŭte: Mia filo Abŝalom, Abŝalom, mia filo, mia filo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Tiam Joab venis al la reĝo en la domon, kaj diris: Vi malhonoris hodiaŭ la vizaĝon de ĉiuj viaj servantoj, kiuj savis hodiaŭ vian animon kaj la animon de viaj filoj kaj de viaj filinoj kaj la animon de viaj edzinoj kaj la animon de viaj kromvirinoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'ĉar vi amas viajn malamikojn, kaj malamas viajn amantojn; ĉar vi montris hodiaŭ, ke ne ekzistas por vi estroj nek sklavoj. Mi komprenas hodiaŭ, ke se Abŝalom vivus kaj ni ĉiuj hodiaŭ mortus, tio plaĉus al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Leviĝu do, eliru kaj parolu ion al la koro de viaj servantoj; ĉar mi ĵuras per la Eternulo, se vi ne eliros, en ĉi tiu nokto ne restos eĉ unu homo ĉe vi; kaj tio estos por vi pli malbona, ol ĉiuj malbonoj, kiuj trafis vin de via juneco ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Tiam la reĝo leviĝis, kaj sidiĝis ĉe la pordego. Kaj oni sciigis al la tuta popolo, dirante: Jen la reĝo sidas ĉe la pordego. Kaj la tuta popolo venis antaŭ la reĝon. Sed la Izraelidoj forkuris ĉiu en sian tendon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Kaj la tuta popolo disputadis inter si en ĉiuj triboj de Izrael, dirante: La reĝo savis nin el la manoj de niaj malamikoj, li savis nin el la manoj de la Filiŝtoj; kaj nun li forkuris el sia lando pro Abŝalom!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Kaj Abŝalom, kiun ni sanktoleis super ni, mortis en la batalo. Kial do vi nun hezitas revenigi la reĝon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Dume la reĝo David sendis al la pastroj Cadok kaj Ebjatar, por diri: Parolu kun la plejaĝuloj de Jehuda, kaj diru: Kial vi volas esti la lastaj koncerne la revenigon de la reĝo en lian domon, kiam la paroloj de la tuta Izrael jam venis al la reĝo en lian domon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Vi estas miaj fratoj, vi estas mia osto kaj mia karno; kial do vi devas esti la lastaj ĉe la revenigo de la reĝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Kaj al Amasa diru: Vi estas ja mia osto kaj mia karno; tiel kaj pli punu min Dio, se vi ne estos ĉe mi por ĉiam militestro anstataŭ Joab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Kaj li inklinigis la koron de ĉiuj viroj de Jehuda kiel unu viron; kaj ili sendis al la reĝo, kaj diris: Revenu vi kaj ĉiuj viaj servantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Kaj la reĝo revenis; li venis al Jordan; kaj la viroj de Jehuda venis en Gilgalon, por iri renkonte al la reĝo, por akompani la reĝon trans Jordanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Tiam Ŝimei, filo de Gera, la Benjamenido, el Baĥurim, rapide iris kun la viroj de Jehuda renkonte al la reĝo David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'Kun li estis mil viroj el Benjamen, ankaŭ Ciba, servanto de la domo de Saul, kaj liaj dek kvin filoj kaj liaj dudek servantoj kun li; kaj ili transiris Jordanon antaŭ la reĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'La pramo transiradis, por transveturigi la familion de la reĝo, kaj fari tion, kion li deziros; tiam Ŝimei, filo de Gera, falis antaŭ la reĝo, kiam ĉi tiu transiris Jordanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'Kaj li diris al la reĝo: Mia sinjoro ne kalkulu tion al mi kiel krimon, kaj ne rememoru tion, kion malbonagis via sklavo en tiu tago, kiam mia sinjoro la reĝo eliris el Jerusalem, kaj la reĝo ne metu tion en sian koron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Ĉar via sklavo konscias, ke mi pekis; kaj nun mi venis la unua el la tuta domo de Jozef, por iri renkonte al mia sinjoro la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Tiam ekparolis Abiŝaj, filo de Ceruja, kaj diris: Ĉu efektive Ŝimei ne estos mortigita pro tio, ke li insultis la sanktoleiton de la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Sed David diris: Kiel tio koncernas min kaj vin, filoj de Ceruja, ke vi hodiaŭ malhelpas min? ĉu hodiaŭ oni povas iun mortigi en Izrael? ĉu mi ne scias, ke mi nun estas reĝo super Izrael?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'Kaj la reĝo diris al Ŝimei: Vi ne mortos. Kaj la reĝo ĵuris al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Ankaŭ Mefiboŝet, ido de Saul, iris renkonte al la reĝo. Li ne ordigis siajn piedojn kaj ne ordigis sian barbon kaj ne lavis siajn vestojn, de post la tago, kiam la reĝo foriris, ĝis la tago, kiam li bonfarte revenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'Kiam li venis Jerusalemon renkonte al la reĝo, la reĝo diris al li: Kial vi ne iris kun mi, Mefiboŝet?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Ĉi tiu respondis: Mia sinjoro, ho reĝo! mia servanto min trompis; ĉar via sklavo diris: Selu al mi azenon, por ke mi rajdu sur ĝi kaj mi iru kun la reĝo; ĉar via sklavo estas lama.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'Sed li kalumniis kontraŭ via sklavo al mia sinjoro la reĝo; tamen vi, mia sinjoro, ho reĝo, estas kiel anĝelo de Dio; agu, kiel plaĉas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Ĉar la tuta domo de mia patro meritis morton antaŭ mia sinjoro la reĝo; vi tamen metis vian sklavon inter tiujn, kiuj manĝas ĉe via tablo. Kian justecon mi do ankoraŭ bezonas? kaj kion mi havas por plendi al la reĝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Kaj la reĝo diris al li: Kial vi parolas ankoraŭ pri viaj aferoj? mi jam diris, ke vi kaj Ciba dividu inter vi la kampojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'Sed Mefiboŝet diris al la reĝo: Li prenu eĉ ĉion, post kiam mia sinjoro la reĝo venis bonfarte en sian domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Ankaŭ Barzilaj, la Gileadano, venis el Roglim, kaj akompanis la reĝon trans Jordanon, por konduki lin transe de Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Barzilaj estis tre maljuna; li havis la aĝon de okdek jaroj. Li donadis manĝaĵon al la reĝo, kiam ĉi tiu estis en Maĥanaim, ĉar li estis homo tre bonstata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Kaj la reĝo diris al Barzilaj: Iru kun mi, kaj mi zorgados pri vi ĉe mi en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Sed Barzilaj diris al la reĝo: Kiel longe mi havas ankoraŭ por vivi, ke mi iru kun la reĝo Jerusalemon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Mi havas nun la aĝon de okdek jaroj; ĉu mi povas distingi inter bono kaj malbono? ĉu via sklavo sentos la guston de tio, kion mi manĝos aŭ kion mi trinkos? ĉu mi povas ankoraŭ kompreni la voĉon de kantistoj kaj kantistinoj? por kio via sklavo estu ŝarĝo por mia sinjoro la reĝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Iomete iros via sklavo kun la reĝo trans Jordanon; por kio la reĝo volas rekompenci min per tia rekompenco?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Permesu al via sklavo, ke mi reiru, kaj ke mi mortu en mia urbo, ĉe la tombo de mia patro kaj mia patrino. Sed jen via sklavo Kimham iru kun mia sinjoro la reĝo; kaj faru por li tion, kio plaĉos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Kaj la reĝo diris: Kimham iru kun mi, kaj mi faros por li tion, kio estos agrabla al vi; kaj ĉion, kion vi deziros de mi, mi faros por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'La tuta popolo transiris Jordanon, kaj ankaŭ la reĝo transiris. Kaj la reĝo kisis Barzilajon kaj benis lin, kaj ĉi tiu reiris al sia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'La reĝo transiris en Gilgalon, kaj Kimham iris kun li; kaj la tuta popolo Juda akompanis la reĝon, kaj ankaŭ duono de la popolo Izraela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Sed jen ĉiuj Izraelidoj venis al la reĝo, kaj diris al la reĝo: Kial ŝtelis vin niaj fratoj la Judoj, kaj transkondukis trans Jordanon la reĝon kaj lian familion kaj ĉiujn liajn virojn kun li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Tiam ĉiuj Judoj respondis al la Izraelidoj: Ĉar la reĝo estas nia parenco; kaj kial tio ĉagrenas vin? ĉu ni ion manĝis de la reĝo, aŭ ĉu li donis al ni donacojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Kaj la Izraelidoj respondis al la Judoj kaj diris: Dek partojn ni havas en la reĝo; kaj eĉ en David ni havas pli grandan parton ol vi; kial do vi malŝatis nin? ĉu ne ni la unuaj ekparolis pri revenigo de nia reĝo? Sed la vortoj de la Judoj estis pli obstinaj, ol la vortoj de la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Troviĝis tie viro malbonaga, kies nomo estis Ŝeba, filo de Biĥri, Benjamenido; li ekblovis per trumpeto, kaj diris: Ni ne havas parton en David, ni ne havas heredaĵon en la filo de Jiŝaj: iru, Izraelidoj, ĉiu en sian tendon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Kaj ĉiuj Izraelidoj foriris de David, kaj sekvis Ŝeban, filon de Biĥri; sed la Judoj restis fidelaj al sia reĝo, de Jordan ĝis Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'Kiam David venis en sian domon en Jerusalem, la reĝo prenis la dek kromvirinojn, kiujn li restigis, por gardi la domon, kaj metis ilin en gardejon; li donadis al ili vivrimedojn, sed li ne envenadis al ili. Kaj ili restis ŝlositaj ĝis la tago de sia morto, vivante kiel vidvinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Kaj la reĝo diris al Amasa: Kunvoku al mi la Judojn por la tria tago, kaj vi ankaŭ venu ĉi tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Amasa iris, por kunvoki la Judojn; sed li malfruis la templimon, kiu estis destinita al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Tiam David diris al Abiŝaj: Nun Ŝeba, filo de Biĥri, faros al ni pli da malbono, ol Abŝalom; prenu do vi la servantojn de via sinjoro, kaj postkuru lin, por ke li ne trovu fortikigitajn urbojn kaj ne ŝirmu sin kontraŭ niaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Kaj eliris post li la viroj de Joab kaj la Keretidoj kaj la Peletidoj kaj ĉiuj fortuloj; kaj ili eliris el Jerusalem, por postkuri Ŝeban, filon de Biĥri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Kiam ili estis ĉe la granda ŝtono, kiu troviĝas en Gibeon, Amasa venis antaŭ ilin. Joab havis sur si striktan veston, kaj sur ĝi estis zonita glavo, kiu pendis en la glavingo ĉe lia lumbo kaj facile povis eliri kaj eniri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Kaj Joab diris al Amasa: Kiel vi fartas, mia frato? Kaj per la dekstra mano Joab prenis la barbon de Amasa, por kisi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Amasa ne atentis la glavon, kiu estis en la mano de Joab; kaj ĉi tiu frapis lin per ĝi en la ventron tiel, ke liaj internaĵoj elŝutiĝis sur la teron, kaj sen ripetita frapo li mortis. Poste Joab kaj lia frato Abiŝaj postkuris Ŝeban, filon de Biĥri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Ĉe la mortigito staris viro el la servantoj de Joab, kaj diris: Kiu amas Joabon kaj kiu estas por David, tiu sekvu Joabon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Amasa kuŝis rulita en sango meze de la vojo. Kiam tiu viro vidis, ke ĉiuj haltadis, li fortrenis Amasan de la vojo sur la kampon kaj ĵetis sur lin veston, ĉar li vidis, ke ĉiu, kiu venis al li, haltis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Kiam li estis forigita for de la vojo, ĉiuj iris post Joab, por postkuri Ŝeban, filon de Biĥri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Ĉi tiu trairis ĉiujn tribojn de Izrael, ĝis Abel kaj Bet-Maaĥa, kaj ĉiuj Beriidoj; kaj oni kolektiĝis, kaj sekvis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'Kaj ili venis, kaj eksieĝis lin en Abel-Bet-Maaĥa, kaj ŝutis ĉirkaŭ la urbo remparon, kiu atingis la muron; kaj la tuta popolo, kiu estis kun Joab, komencis detrui, por faligi la muron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Tiam ekkriis unu saĝa virino el la urbo: Aŭskultu, aŭskultu; diru, mi petas, al Joab, ke li alproksimiĝu ĉi tien, por ke mi parolu kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Kiam li alproksimiĝis al ŝi, la virino diris: Ĉu vi estas Joab? Li respondis: Mi. Kaj ŝi diris al li: Aŭskultu la vortojn de via sklavino. Li respondis: Mi aŭskultas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Tiam ŝi diris: En antaŭaj tempoj oni diradis: Demandu la Abelanojn, kaj konforme al tio decidu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Mi estas unu el la pacemaj kaj fidelaj urboj de Izrael; vi volas ruinigi urbon kaj patrinon en Izrael; por kio vi volas ekstermi posedaĵon de la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Tiam Joab respondis kaj diris: Mi tute, tute ne intencas ekstermi kaj ruinigi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'ne tia estas la afero; sed unu viro de la monto de Efraim-Ŝeba, filo de Biĥri, estas lia nomo-levis sian manon kontraŭ la reĝon David; donu lin solan, kaj mi foriros de la urbo. Kaj la virino diris al Joab: Jen lia kapo estos ĵetita al vi trans la muron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Kaj la virino venis al la tuta popolo kun sia saĝa parolo; kaj ili dehakis la kapon de Ŝeba, filo de Biĥri, kaj ĵetis al Joab. Tiam li ekblovis per trumpeto, kaj oni foriris de la urbo ĉiu al sia tendo; kaj Joab revenis Jerusalemon al la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Joab estis super la tuta militistaro de Izrael; kaj Benaja, filo de Jehojada, super la Keretidoj kaj la Peletidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'kaj Adoram super la impostoj; kaj Jehoŝafat, filo de Aĥilud, estis kronikisto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'kaj Ŝeva estis skribisto; kaj Cadok kaj Ebjatar estis pastroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'ankaŭ Ira, la Jairano, estis pastro ĉe David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'Estis malsato en la tempo de David dum tri jaroj, jaron post jaro. Kaj David faris demandon ĉe la Eternulo; kaj la Eternulo respondis: Tio estas pro Saul kaj pro la sangavida domo, pro tio, ke li mortigis la Gibeonanojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Tiam la reĝo alvokis la Gibeonanojn, kaj parolis kun ili. (Kaj la Gibeonanoj estis ne el la Izraelidoj, sed el la restaĵoj de la Amoridoj; kaj la Izraelidoj ĵuris al ili, sed Saul penis ekstermi ilin pro sia fervoro por la Izraelidoj kaj Judoj.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'Kaj David diris al la Gibeonanoj: Kion mi faru por vi, kaj per kio mi pekliberiĝu, por ke vi benu la heredaĵon de la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'La Gibeonanoj diris al li: Ni ne postulas arĝenton aŭ oron de Saul kaj de lia domo; kaj ni ne volas, ke oni iun mortigu en Izrael. Kaj la reĝo diris: Kion vi diros, tion mi faros por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Tiam ili diris al la reĝo: Pro tiu homo, kiu nin pereigis, kaj kiu atencis kontraŭ ni, por nin ekstermi, por ke nenio restu el ni en ĉiuj limoj de Izrael,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'oni donu al ni sep virojn el liaj filoj, kaj ni pendigu ilin antaŭ la Eternulo en Gibea de Saul, la elektito de la Eternulo. Kaj la reĝo diris: Mi donos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Sed la reĝo indulgis Mefiboŝeton, filon de Jonatan, filo de Saul, pro la ĵuro antaŭ la Eternulo, kiu ekzistis inter ili, inter David kaj Jonatan, filo de Saul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Kaj la reĝo prenis Armonin kaj Mefiboŝeton, la du filojn de Ricpa, filino de Aja, kiujn ŝi naskis al Saul, kaj la kvin filojn de Miĥal, filino de Saul, kiujn ŝi naskis al Adriel, filo de Barzilaj, la Meĥolatano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'Kaj li transdonis ilin en la manojn de la Gibeonanoj, kaj ĉi tiuj pendigis ilin sur la monto antaŭ la Eternulo. Tiel ili falis sepope kune; ili estis mortigitaj en la unuaj tagoj de la rikolto, en la komenco de la rikolto de hordeo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Tiam Ricpa, filino de Aja, prenis sakon, kaj etendis ĝin super si ĉe la roko, de la komenco de la rikolto ĝis ekpluvis sur ilin el la ĉielo; kaj ŝi ne permesis, ke la birdoj de la ĉielo ripozu sur ili tage, nek la kampaj bestoj nokte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Oni raportis al David, kion faris Ricpa, filino de Aja kaj kromvirino de Saul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Tiam David iris, kaj prenis la ostojn de Saul kaj la ostojn de lia filo Jonatan de la loĝantoj de Jabeŝ en Gilead, kiuj forŝtelis ilin el la strato de Bet-Ŝan, kie pendigis ilin la Filiŝtoj en la tago, kiam la Filiŝtoj venkobatis Saulon sur Gilboa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Kaj li forportis de tie la ostojn de Saul kaj la ostojn de lia filo Jonatan; kaj oni kunigis ilin kun la ostoj de la pendigitoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'Kaj oni enterigis la ostojn de Saul kaj de lia filo Jonatan en la tero de Benjamen, en Cela, en la tombo de lia patro Kiŝ; kaj oni faris ĉion, kion ordonis la reĝo. Post tio Dio repaciĝis kun la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Estis denove milito inter la Filiŝtoj kaj la Izraelidoj. Kaj iris David kune kun siaj servantoj, kaj batalis kontraŭ la Filiŝtoj. Kaj David laciĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Jiŝbi-benob, el la infanoj de giganto, li, kies lanco havis la pezon de tricent sikloj da kupro, kaj kiu estis zonita per nova glavo, intencis mortigi Davidon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Sed venis kun helpo Abiŝaj, filo de Ceruja, kaj li frapis la Filiŝton kaj mortigis lin. Tiam la viroj de David ĵuris al li, dirante: Vi devas ne plu iri kun ni en militon, por ke ne estingiĝu la lucerno de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Post tio estis denove milito kontraŭ la Filiŝtoj en Gob; tiam Sibĥaj, la Ĥuŝaido, mortigis Safon, kiu estis el la infanoj de la giganto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Kaj denove estis milito kontraŭ la Filiŝtoj en Gob; kaj Elĥanan, filo de Jaare-Orgim, Bet-Leĥemano, mortigis Goljaton, la Gatanon, ĉe kiu la tenilo de lia lanco estis kiel rultrabo de teksisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Kaj denove estis milito en Gat; tie estis viro tre altkreska, kiu havis sur la manoj kaj sur la piedoj po ses fingroj, sume dudek kvar; li ankaŭ naskiĝis al la giganto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Kiam li insultis Izraelon, lin mortigis Jonatan, filo de Ŝimea, frato de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Tiuj kvar naskiĝis al la giganto en Gat, kaj ili falis de la mano de David kaj de la mano de liaj servantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'Kaj David eldiris antaŭ la Eternulo la vortojn de la sekvanta kanto, kiam la Eternulo lin savis el la manoj de ĉiuj liaj malamikoj kaj el la mano de Saul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'Li diris: La Eternulo estas mia Roko, kaj mia fortikaĵo, kaj mia Savanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Dion, mian Rokon, mi fidas; Mia ŝildo, kaj la korno de mia savo, mia fortigo, kaj mia rifuĝejo; Mia Savanto, kiu helpas min kontraŭ maljusteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Mi vokas al la Eternulo, la glorinda; Kaj mi saviĝas de miaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Ĉar ĉirkaŭis min la ondoj de la morto, Torentoj pereigaj min teruris;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'La ŝnuroj de Ŝeol min ĉirkaŭis; La retoj de la morto min atingis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'En mia premiteco mi vokis la Eternulon, Kaj al mia Dio mi vokis; Kaj el Sia templo Li aŭdis mian voĉon, Kaj mia krio atingis Liajn orelojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Ektremis kaj ekskuiĝis la tero, La fundamentoj de la ĉielo ekmoviĝis Kaj ekŝanceliĝis, ĉar Li koleris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Leviĝis fumo el Lia nazo, Kaj ekstermanta fajro el Lia buŝo; Karboj ekflamis de ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Li klinis la ĉielon kaj iris malsupren, Kaj densa mallumo estis sub Liaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Kaj Li ekrajdis sur kerubo kaj ekflugis, Kaj Li portiĝis sur la flugiloj de la vento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Li ĉirkaŭigis Sin per mallumo kiel per tendo, Per densaj nuboj, plenaj de akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'De la brilo antaŭ Li Ekbrulis karboj per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'El la ĉielo ektondris la Eternulo, Kaj la Plejaltulo aŭdigis Sian voĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Li ĵetis sagojn, kaj dispelis ilin; fulmon, kaj konfuzis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Kaj malkovriĝis la kuŝujoj de la maro, Nudiĝis la fundamentoj de la universo, De la minaca voĉo de la Eternulo, De la kolera spirado de Lia nazo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Li etendas el supre la brakon, kaj prenas min; Li eltiras min el grandaj akvoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Li savas min de mia potenca malamiko, De miaj malamantoj, ĉar ili estas pli fortaj ol mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Ili atingis min en la tago de mia malfeliĉo; Sed la Eternulo fariĝis mia subteno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Kaj Li elkondukis min en vastan lokon; Li liberigis min, ĉar Li estas favora al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'La Eternulo rekompencas min laŭ mia justeco; Laŭ la pureco de miaj manoj Li repagas al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Ĉar mi min tenis je la vojoj de la Eternulo, Kaj mi ne faris malbonon antaŭ mia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Ĉar ĉiuj Liaj leĝoj estis antaŭ mi, Kaj Liajn ordonojn mi ne forigis de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'Mi estis senkulpa antaŭ Li, Kaj mi gardis min, ke mi ne peku.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Kaj la Eternulo rekompencis min laŭ mia justeco, Laŭ mia pureco antaŭ Liaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Kun favorkorulo Vi estas favorkora, Kun piulo Vi estas pia;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'Kun purulo Vi agas laŭ lia pureco, Kaj kun maliculo laŭ lia maliceco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Popolon humilan Vi helpas; Kaj per Viaj okuloj Vi malaltigas la fierulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Ĉar Vi estas mia lumilo, ho Eternulo; La Eternulo lumigas mian mallumon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Ĉar kun Vi mi forkurigas militistaron; Kun mia Dio mi transsaltas muron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'La vojo de Dio estas perfekta; La parolo de la Eternulo estas tute pura; Li estas ŝildo por ĉiuj, kiuj Lin fidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Ĉar kiu estas Dio, krom la Eternulo? Kaj kiu estas Roko, krom nia Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Dio fortikigas min per forto; Kaj Li perfektigas mian vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Li similigas miajn piedojn al cervaj, Kaj starigas min sur miaj altaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'Li instruas mian manon militi, Kaj miajn brakojn streĉi kupran pafarkon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Vi donis al mi la ŝildon de Via savo; Kaj Via favoro min grandigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Vi larĝigas mian paŝon sub mi, Por ke ne ŝanceliĝu miaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Mi persekutas miajn malamikojn, kaj ekstermas ilin; Kaj mi ne revenas, ĝis mi ilin pereigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Mi pereigas kaj frakasas ilin, ke ili ne povas plu leviĝi; Ili falas sub miajn piedojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Vi ĉirkaŭzonas min per forto por la milito; Miajn atakintojn Vi ĵetas sub min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Vi forkurigas de mi miajn malamikojn, Kaj miajn malamantojn mi ekstermas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Ili rigardas ĉirkaŭen, sed ne venas helpanto; Al la Eternulo, sed Li ne respondas al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Mi disfrotas ilin simile al polvo de la tero; Kiel stratan koton mi ilin disbatas kaj dispremas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Vi savas min de la ribeloj de mia popolo; Vi gardas min, ke mi estu ĉefo super la nacioj; Popolo, kiun mi ne konas, servas min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Aligentuloj respektegas min; Ili obeas min per atentaj oreloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Aligentuloj senfortiĝas, Kaj kuras terurite el siaj fortikaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Vivas la Eternulo; kaj benata estu mia Roko; Alte glorata estu mia Dio, la Roko de mia savo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Tiu Dio, kiu donas al mi venĝon Kaj submetas al mi popolojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'Kiu forkondukas min de miaj malamikoj, Altigas min super miaj atakintoj, Kaj savas min de perfortulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Tial mi gloras Vin, ho Eternulo, inter la popoloj, Kaj pri Via nomo mi kantas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'Li donas grandan helpon al Sia reĝo, Kaj faras favoraĵon al Sia sanktoleito, Al David kaj al lia idaro, por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Jen estas la lastaj vortoj de David: Parolas David, filo de Jiŝaj, Kaj parolas la viro, kiu estas alte levita, La sanktoleito de la Dio de Jakob, Kantverkisto en Izrael:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'La spirito de la Eternulo parolas per mi, Kaj Lia vorto estas sur mia lango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'La Dio de Izrael parolis, Al mi diris la Roko de Izrael: Justulo regas super homoj, Li regas en timo antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'Kaj li estas kiel la lumo de mateno, Kiam leviĝas la suno, De mateno sennuba, Kiam post la pluvo Elkreskas la verdaĵo el la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Ĉu ne tiel estas mia domo ĉe la Eternulo? Ĉar Li faris kun mi eternan interligon, Kiu estas bone aranĝita en ĉio, kaj observata; Ĉar mia tuta savo, kaj ĉio, kion mi deziras, bone prosperas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'La malbonaguloj ĉiuj estas kiel dornoj forĵetitaj, Kiujn oni ne povas preni per la mano;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Sed se iu volas ektuŝi ilin, Tiu devas armi sin per fero aŭ per stango de lanco; Kaj per fajro ili estos forbruligitaj sur sia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Jen estas la nomoj de la herooj, kiuj estis ĉe David: sidanta en la konsilantaro de la saĝuloj, estro de trio, estis Adino, la Ecnido, kiu mortigis okcent malamikojn per unu fojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Post li estis Eleazar, filo de Dodo, filo de Aĥoĥido, en la nombro de la tri herooj ĉe David. Kiam ili mokis la Filiŝtojn kaj kolektiĝis tie por batalo kaj la Izraelidoj eliris,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'tiam li leviĝis kaj frapis la Filiŝtojn, ĝis lia mano laciĝis kaj alrigidiĝis al la glavo; kaj la Eternulo donis grandan helpon en tiu tago, kaj la popolo returniĝis post li nur por rabakiri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Post li estis Ŝama, filo de Age, la Hararano. Kiam la Filiŝtoj kolektiĝis amase en loko, kie estis kampoparto plena de lentoj, kaj la popolo forkuris de la Filiŝtoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'tiam li stariĝis en la mezo de la kampoparto, kaj savis ĝin kaj venkobatis la Filiŝtojn; kaj la Eternulo donis grandan helpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Kaj iris tri el la tridek ĉefoj, kaj venis dum la rikoltado al David en la kavernon Adulam; kaj la amaso de la Filiŝtoj staris tendare en la valo Refaim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'David tiam estis en fortikaĵo, kaj la garnizono de la Filiŝtoj estis tiam en Bet-Leĥem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Kaj David esprimis deziron kaj diris: Kiu trinkigus al mi akvon el la puto Bet-Leĥema, kiu estas apud la pordego?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Tiam tiuj tri herooj trarompe penetris en la tendaron de la Filiŝtoj, ĉerpis akvon el la puto Bet-Leĥema, kiu estis apud la pordego, prenis kaj alportis al David. Sed li ne volis trinki ĝin; li elverŝis ĝin al la Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'kaj diris: Gardu min, ho Eternulo, ke mi ne faru tion; ĉu mi trinku la sangon de la viroj, kiuj riskis sian vivon? Kaj li ne volis trinki ĝin. Tion faris la tri herooj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Abiŝaj, frato de Joab, filo de Ceruja, estis estro de tiuj tri; li mortigis per sia lanco tricent homojn, kaj li havis gloran nomon inter la tri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'De la tri li estis honorata kaj estis ilia estro; sed en la trion li ne eniris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Benaja, filo de Jehojada, filo de militisto multe aginta, el Kabceel: li mortigis la du fortulojn de Moab; li ankaŭ malsupreniris, kaj mortigis leonon en kavo en neĝa tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Li ankaŭ mortigis Egipton, viron dignaspektan; en la mano de la Egipto estis lanco; sed li aliris al li kun bastono, elŝiris la lancon el la mano de la Egipto, kaj mortigis lin per lia propra lanco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Tion faris Benaja, filo de Jehojada. Kaj li havis gloran nomon inter la tri herooj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Inter la tridek li estis plej honorata, sed en la trion li ne eniris. Kaj David faris lin lia korpogardistestro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Asahel, frato de Joab, estis inter la tridek; Elĥanan, filo de Dodo, el Bet-Leĥem,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Ŝama el Ĥarod, Elika el Ĥarod,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Ĥelec, la Paltido, Ira, filo de Ikeŝ, la Tekoaano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abiezer la Anatotano, Mebunaj, la Ĥuŝaido,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Calmon, la Aĥoĥido, Maharaj, la Netofaano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Ĥeleb, filo de Baana, la Netofaano, Itaj, filo de Ribaj, el Gibea de la Benjamenidoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Benaja, la Piratonano, Hidaj el Naĥale-Gaaŝ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Abi-Albon, la Arbatano, Azmavet, la Baĥurimano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Eljaĥba, la Ŝaalbonano, Jonatan el la filoj de Jaŝen,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Ŝama, la Hararano, Aĥiam, filo de Ŝarar, la Hararano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Elifelet, filo de Aĥasbaj, la Maaĥatano, Eliam, filo de Aĥitofel, la Giloano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Ĥecraj, la Karmelano, Paaraj, la Arbano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Jigal, filo de Natan, el Coba, Bani, la Gadido,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Celek, la Amonido, Naĥaraj, la Beerotano, armilportisto de Joab, filo de Ceruja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Ira, la Jetrido, Gareb, la Jetrido,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Urija, la Ĥetido. La nombro de ĉiuj estas tridek sep.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'La kolero de la Eternulo denove ekflamis kontraŭ la Izraelidoj, kaj Li incitis Davidon kontraŭ ili, dirante: Iru, kalkulu Izraelon kaj Jehudan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Kaj la reĝo diris al Joab, la militestro, kiu estis ĉe li: Iru, mi petas, tra ĉiuj triboj de Izrael, de Dan ĝis Beer-Ŝeba, kaj kalkulu la popolon, por ke mi sciu la nombron de la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Tiam Joab diris al la reĝo: La Eternulo, via Dio, plimultigu la popolon centoble kompare kun tio, kio estas nun, kaj la okuloj de mia sinjoro tion vidu; sed por kio mia sinjoro la reĝo deziras tiun aferon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Sed la vorto de la reĝo superfortis Joabon kaj la militestrojn; tial Joab kaj la militestroj foriris de la reĝo, por kalkuli la popolon Izraelan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Ili transiris Jordanon, kaj starigis siajn tendojn en Aroer, dekstre de la urbo, kiu estas meze de la valo Gad, antaŭ Jazer;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'kaj ili venis en Gileadon kaj en la landon Taĥtim-Ĥodŝi; poste ili venis en Dan-Jaanon kaj en la ĉirkaŭaĵon de Cidon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Ili venis al la fortikaĵo de Tiro, kaj en ĉiujn urbojn de la Ĥividoj kaj Kanaanidoj, kaj eliris en la sudon de Judujo al Beer-Ŝeba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'Ili trapasis la tutan landon, kaj venis Jerusalemon post naŭ monatoj kaj dudek tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Kaj Joab transdonis al la reĝo la rezulton de la kalkulado de la popolo; kaj montriĝis, ke da Izraelidoj estas okcent mil viroj militkapablaj, povantaj eltiri glavon, kaj da Jehudaidoj kvincent mil viroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Kaj ekbatis la koro de David, post kiam li kalkuligis la popolon. Kaj David diris al la Eternulo: Mi forte pekis per tio, kion mi faris; kaj nun, ho Eternulo, pardonu do la malbonagon de Via sklavo; ĉar mi agis tre malsaĝe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'David leviĝis matene, kaj la Eternulo parolis al la profeto Gad, la viziisto de David, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Iru kaj diru al David: Tiele diris la Eternulo: Tri punojn Mi proponas al vi; elektu al vi unu el ili, ke Mi ĝin faru al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Kaj Gad venis al David kaj sciigis al li, kaj diris al li: Ĉu venu al vi sepjara malsato en via lando? aŭ dum tri monatoj vi forkuradu de viaj malamikoj kaj ili persekutu vin? aŭ estu tritaga pesto en via lando? pripensu do kaj decidu, kion mi respondu al mia Sendinto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'Tiam David diris al Gad: Estas al mi tre malfacile; sed ni falu en la manon de la Eternulo, ĉar granda estas Lia kompatemeco; nur mi ne falu en manon homan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'Kaj la Eternulo venigis peston sur Izraelon, de tiu mateno ĝis la difinita tempo; kaj mortis el la popolo de Dan ĝis Beer-Ŝeba sepdek mil homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Kaj la anĝelo etendis sian manon kontraŭ Jerusalemon, por pereigi ĝin; sed la Eternulo bedaŭris la malbonon, kaj diris al la anĝelo, kiu ekstermis la popolon: Sufiĉe! nun haltigu vian manon! La anĝelo de la Eternulo estis tiam ĉe la draŝejo de Aravna, la Jebusido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'Kaj, ekvidinte la anĝelon, kiu frapis la popolon, David ekparolis al la Eternulo, dirante: Jen mi pekis, kaj mi malbonagis; sed kion faris ĉi tiuj ŝafoj? Via mano estu sur mi kaj sur la domo de mia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'En tiu tago venis Gad al David, kaj diris al li: Iru, starigu altaron al la Eternulo en la draŝejo de Aravna, la Jebusido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'Kaj David iris konforme al la vortoj de Gad, kiel ordonis la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Aravna ekrigardis, kaj ekvidis la reĝon kaj liajn servantojn, kiuj iris al li; kaj Aravna eliris, kaj adorkliniĝis al la reĝo vizaĝaltere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Kaj Aravna diris: Por kio mia sinjoro la reĝo venis al sia sklavo? David respondis: Por aĉeti de vi la draŝejon, kaj konstrui altaron al la Eternulo, por ke ĉesiĝu la pesto inter la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Sed Aravna diris al David: Mia sinjoro la reĝo prenu kaj alportu oferojn, kiel plaĉas al li; jen estas bovoj por brulofero, kaj la draŝiloj kaj la jungilaro de la bovoj servos kiel ligno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Ĉion tion donis Aravna al la reĝo. Kaj Aravna diris al la reĝo: La Eternulo, via Dio, favoru vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Tamen la reĝo diris al Aravna: Ne; mi volas aĉeti de vi pro difinita prezo; mi ne alportos al la Eternulo, mia Dio, bruloferojn senpagajn. Kaj David aĉetis la draŝejon kaj la bovojn pro kvindek sikloj da arĝento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'Kaj David konstruis tie altaron al la Eternulo, kaj alportis bruloferojn kaj pacoferojn. Kaj la Eternulo repaciĝis kun la lando; kaj ĉesiĝis la pesto inter la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'La reĝo David maljuniĝis kaj atingis profundan aĝon; kaj oni kovris lin bone per vestoj, sed li ne povis varmiĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Tiam diris al li liaj servantoj: Oni elserĉu por nia sinjoro la reĝo junulinon virgulinon, kaj ŝi staru antaŭ la reĝo kaj flegu lin kaj dormu ĉe lia brusto, kaj tiam al nia sinjoro la reĝo fariĝos varme.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Kaj oni serĉis belan junulinon en la tuta regiono de Izrael, kaj oni trovis la Ŝunemaninon Abiŝag kaj venigis ŝin al la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'La junulino estis tre bela; kaj ŝi fariĝis flegantino de la reĝo kaj servis al li; sed la reĝo ne ekkonis ŝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Dume Adonija, filo de Ĥagit, fieriĝis, kaj diris: Mi fariĝos reĝo. Kaj li havigis al si ĉarojn kaj rajdistojn kaj kvindek homojn por kuradi antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Kaj lia patro neniam afliktis lin per demando: Kial vi tion faras? Krom tio li estis tre belaspekta, kaj li estis naskita post Abŝalom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Kaj li interkonsentis kun Joab, filo de Ceruja, kaj kun la pastro Ebjatar, kaj ili helpadis Adonijan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Sed la pastro Cadok, kaj Benaja, filo de Jehojada, kaj la profeto Natan kaj Ŝimei kaj Rei kaj la fortuloj de David ne estis kun Adonija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Adonija buĉis ŝafojn kaj bovojn kaj grasigitajn brutojn ĉe la ŝtono Zoĥelet, kiu kuŝas apud En-Rogel; kaj li invitis ĉiujn siajn fratojn, la filojn de la reĝo, kaj ĉiujn Jehudaanojn, kiuj servis al la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Sed la profeton Natan kaj Benajan kaj la fortulojn kaj sian fraton Salomono li ne invitis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Kaj Natan diris al Bat-Ŝeba, patrino de Salomono, jene: Ĉu vi ne aŭdis, ke Adonija, filo de Ĥagit, fariĝis reĝo, kaj nia sinjoro David tion ne scias?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Venu do, mi donos al vi konsilon, por ke vi savu vian animon kaj la animon de via filo Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Iru kaj venu al la reĝo David, kaj diru al li: Mia sinjoro, ho reĝo, vi ĵuris ja al via servantino, dirante: Via filo Salomono reĝos post mi, kaj li sidos sur mia trono; kial do Adonija fariĝis reĝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Dum vi ankoraŭ estos parolanta tie kun la reĝo, mi venos post vi kaj kompletigos viajn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Kaj Bat-Ŝeba venis al la reĝo en la ĉambron; la reĝo estis tre maljuna, kaj la Ŝunemanino Abiŝag servis al la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Bat-Ŝeba salutis kaj adorkliniĝis antaŭ la reĝo; kaj la reĝo diris: Kio estas al vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Kaj ŝi diris al li: Mia sinjoro, vi ĵuris al via servantino per la Eternulo, via Dio: Via filo Salomono reĝos post mi, kaj li sidos sur mia trono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'Sed nun jen Adonija fariĝis reĝo; kaj vi, mia sinjoro, ho reĝo, tion ne scias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Li buĉis multe da bovoj kaj grasigitaj brutoj kaj ŝafoj, kaj invitis ĉiujn filojn de la reĝo kaj la pastron Ebjatar kaj la militestron Joab, sed vian servanton Salomono li ne invitis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Sed vi, mia sinjoro, ho reĝo-la okuloj de ĉiuj Izraelidoj estas turnitaj al vi, por ke vi diru al ili, kiu sidos sur la trono de mia sinjoro la reĝo post li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Kiam mia sinjoro la reĝo kuŝiĝos kun siaj patroj, tiam mi kaj mia filo Salomono estos proklamitaj kulpuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Dum ŝi ankoraŭ estis parolanta kun la reĝo, venis la profeto Natan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Kaj oni raportis al la reĝo: Jen estas la profeto Natan; kaj ĉi tiu venis antaŭ la reĝon kaj adorkliniĝis antaŭ la reĝo vizaĝaltere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Kaj Natan diris: Mia sinjoro, ho reĝo! ĉu vi diris: Adonija fariĝos reĝo post mi, kaj li sidos sur mia trono?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Ĉar li iris hodiaŭ kaj buĉis multe da bovoj kaj grasigitaj brutoj kaj ŝafoj, kaj invitis ĉiujn filojn de la reĝo kaj la militestron kaj la pastron Ebjatar; kaj jen ili manĝas kaj trinkas antaŭ li, kaj proklamas: Vivu la reĝo Adonija!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Sed min, vian servanton, kaj la pastron Cadok, kaj Benajan, filon de Jehojada, kaj vian servanton Salomono li ne invitis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Ĉu laŭ ordono de mia sinjoro la reĝo tio fariĝis, kaj vi ne sciigis al via servanto, kiu sidos sur la trono de mia sinjoro la reĝo post li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Tiam la reĝo David respondis kaj diris: Voku al mi Bat-Ŝeban. Kaj ŝi venis antaŭ la reĝon kaj stariĝis antaŭ la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'Kaj la reĝo ĵuris kaj diris: Kiel vivas la Eternulo, kiu liberigis mian animon el ĉiuj malfeliĉoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'kiel mi ĵuris al vi per la Eternulo, Dio de Izrael, dirante: Via filo Salomono reĝos post mi kaj li sidos sur mia trono anstataŭ mi-tiel mi faros hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Tiam Bat-Ŝeba salutis vizaĝaltere kaj adorkliniĝis antaŭ la reĝo, kaj diris: Vivu mia sinjoro la reĝo David eterne!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Kaj la reĝo David diris: Voku al mi la pastron Cadok kaj la profeton Natan, kaj Benajan, filon de Jehojada. Kaj ili venis antaŭ la reĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'Kaj la reĝo diris al ili: Prenu kun vi la servantojn de via sinjoro, kaj rajdigu mian filon Salomono sur mia mulo kaj venigu lin en Giĥonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Kaj tie la pastro Cadok kaj la profeto Natan lin sanktoleu reĝo super Izrael; kaj blovu per trumpeto, kaj proklamu: Vivu la reĝo Salomono!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Poste revenu, sekvante lin, kaj li venu kaj sidiĝu sur mia trono; kaj li reĝos anstataŭ mi, al li mi ordonas esti estro de Izrael kaj Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Tiam respondis Benaja, filo de Jehojada, al la reĝo, kaj diris: Amen! tiel diru la Eternulo, Dio de mia sinjoro la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Kiel la Eternulo estis kun mia sinjoro la reĝo, tiel Li estu kun Salomono, kaj Li faru lian tronon pli granda, ol la trono de mia sinjoro, la reĝo David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Kaj iris la pastro Cadok kaj la profeto Natan, kaj Benaja, filo de Jehojada, kaj la Keretidoj kaj la Peletidoj, kaj ili rajdigis Salomonon sur la mulo de la reĝo David kaj kondukis lin en Giĥonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Kaj la pastro Cadok prenis la kornon kun oleo el la tabernaklo kaj sanktoleis Salomonon; kaj oni ekblovis per trumpeto, kaj la tuta popolo diris: Vivu la reĝo Salomono!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Kaj la tuta popolo ekiris post li, kaj la popolo muzikis per flutoj kaj estis tre gaja, tiel ke la tero resonis de iliaj krioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Tion aŭdis Adonija, kaj ĉiuj invititoj, kiuj estis kun li; ili jam finis la manĝadon; kaj aŭdis Joab la sonadon de la trumpeto, kaj li diris: Kion signifas la tumulta bruo de la urbo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Kiam li estis ankoraŭ parolanta, jen venis Jonatan, filo de la pastro Ebjatar. Kaj Adonija diris: Eniru, ĉar vi estas brava homo kaj vi sciigos bonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Kaj Jonatan respondis kaj diris al Adonija: Jes, nia sinjoro la reĝo David faris Salomonon reĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'kaj la reĝo sendis kun li la pastron Cadok kaj la profeton Natan, kaj Benajan, filon de Jehojada, kaj la Keretidojn kaj la Peletidojn, kaj ili rajdigis lin sur la mulo de la reĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'kaj la pastro Cadok kaj la profeto Natan sanktoleis lin reĝo en Giĥon, kaj ili revenis de tie gajaj, kaj la urbo tumultiĝis; tio estas la bruo, kiun vi aŭdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Kaj Salomono jam sidiĝis sur la reĝa trono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'Kaj jam venis la servantoj de la reĝo, por gratuli nian sinjoron, la reĝon David, dirante: Via Dio faru la nomon de Salomono pli fama, ol via nomo, kaj Li faru lian tronon pri granda, ol via trono; kaj la reĝo adorkliniĝis sur la kuŝejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'Kaj ankaŭ tiele diris la reĝo: Benata estu la Eternulo, Dio de Izrael, kiu donis hodiaŭ sidanton sur mia trono, kaj miaj okuloj vidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Kaj ektimis kaj leviĝis ĉiuj invititoj de Adonija, kaj foriris ĉiu sian vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Sed Adonija timis Salomonon, kaj li leviĝis kaj iris kaj ekkaptis la kornojn de la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Kaj oni raportis al Salomono jene: Jen Adonija timas la reĝon Salomono, kaj li tenas la kornojn de la altaro, dirante: La reĝo Salomono ĵuru al mi hodiaŭ, ke li ne mortigos sian servanton per glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Kaj Salomono diris: Se li estos homo brava, tiam eĉ unu el liaj haroj ne falos teren; sed se en li troviĝos malbono, tiam li mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Kaj la reĝo Salomono sendis forprenigi lin de la altaro, kaj li venis kaj adorkliniĝis antaŭ la reĝo Salomono; kaj Salomono diris al li: Iru en vian domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Kiam por David alproksimiĝis la tempo por morti, li testamentis al sia filo Salomono jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Mi foriras la vojon de la tuta mondo; sed vi tenu vin forte kaj estu viro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Kaj observu la ordonojn de la Eternulo, via Dio, irante laŭ Liaj vojoj, plenumante Liajn leĝojn, ordonojn, decidojn, kaj regulojn, kiel estas skribite en la instruo de Moseo, por ke vi estu saĝa en ĉio, kion vi faros, kaj kien ajn vi vin turnos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'por ke la Eternulo plenumu Sian vorton, kiun Li diris pri mi, parolante: Se viaj filoj observos siajn vojojn, irante antaŭ Mi en vero per sia tuta koro kaj per sia tuta animo, tiam ne mankos ĉe vi viro sur la trono de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Ankaŭ vi scias, kion faris al mi Joab, filo de Ceruja, kion li faris al la du militestroj de Izrael, al Abner, filo de Ner, kaj al Amasa, filo de Jeter, ke li mortigis ilin kaj verŝis militan sangon en tempo de paco kaj makulis per milita sango sian zonon sur siaj lumboj kaj siajn ŝuojn sur siaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Agu laŭ via saĝo, ke vi ne lasu al liaj grizaj haroj iri en paco en Ŝeolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Sed al la filoj de Barzilaj, la Gileadano, faru favoron, kaj ili estu inter la manĝantoj ĉe via tablo; ĉar ili tiel alproksimiĝis al mi, kiam mi forkuris de via frato Abŝalom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Kaj jen ĉe vi estas Ŝimei, filo de Gera, Benjamenido el Baĥurim; li malbenis min per kruela malbeno, kiam mi iris al Maĥanaim; sed li venis al mi renkonte ĉe Jordan, kaj mi ĵuris al li per la Eternulo, dirante: Mi ne mortigos vin per glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Sed nun ne lasu lin senpuna, ĉar vi estas homo saĝa, kaj vi scias, kion vi devas fari al li, por malsuprenigi liajn grizajn harojn en sango en Ŝeolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Kaj David ekdormis kun siaj patroj, kaj oni lin enterigis en la urbo de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'La tempo, kiun David reĝis super Izrael, estis kvardek jaroj: en Ĥebron li reĝis sep jarojn, kaj en Jerusalem li reĝis tridek tri jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Kaj Salomono sidis sur la trono de sia patro David, kaj lia reĝado tre fortikiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Adonija, filo de Ĥagit, venis al Bat-Ŝeba, patrino de Salomono. Ŝi diris: Ĉu kun paco vi venas? Kaj li respondis: Kun paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Kaj li diris: Mi havas aferon al vi. Ŝi respondis: Parolu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Kaj li diris: Vi scias, ke la regno apartenis al mi, kaj al mi ĉiuj Izraelidoj turnis sian vizaĝon, ke mi reĝu; sed la reĝado deturniĝis kaj transiris al mia frato, ĉar de la Eternulo ĝi estis destinita al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Nun unu peton mi petas de vi, ne rifuzu al mi. Kaj ŝi diris al li: Parolu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Kaj li diris: Diru, mi petas, al la reĝo Salomono (ĉar li ne rifuzos al vi), ke li donu al mi la Ŝunemaninon Abiŝag kiel edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'Kaj Bat-Ŝeba diris: Bone, mi parolos pri vi kun la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Kaj Bat-Ŝeba venis al la reĝo Salomono, por paroli al li pri Adonija. La reĝo leviĝis renkonte al ŝi kaj adorkliniĝis antaŭ ŝi kaj sidiĝis sur sia trono. Kaj oni starigis tronon por la patrino de la reĝo, kaj ŝi sidiĝis dekstre de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Kaj ŝi diris: Unu malgrandan peton mi petos de vi, ne rifuzu al mi. Kaj la reĝo diris al ŝi: Petu, mia patrino, ĉar mi ne rifuzos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Kaj ŝi diris: La Ŝunemanino Abiŝag estu donata kiel edzino al via frato Adonija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Tiam respondis la reĝo Salomono kaj diris al sia patrino: Kial vi petas la Ŝunemaninon Abiŝag por Adonija? petu por li ankaŭ la reĝecon, ĉar li estas mia pli aĝa frato-por li, kaj por la pastro Ebjatar, kaj por Joab, filo de Ceruja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Kaj la reĝo Salomono ĵuris per la Eternulo, dirante: Tion kaj pli faru al mi la Eternulo; kontraŭ sia vivo Adonija diris tiujn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Nun, kiel vivas la Eternulo, kiu min konfirmis kaj min sidigis sur la trono de mia patro David kaj kiu aranĝis al mi domon laŭ Sia promeso, hodiaŭ Adonija estos mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Kaj la reĝo Salomono sendis Benajan, filon de Jehojada, kaj ĉi tiu frapis lin, kaj li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Kaj al la pastro Ebjatar la reĝo diris: Iru en Anatoton, sur vian kampon; vi meritas la morton, sed mi nun ne mortigos vin, ĉar vi portis la keston de la Sinjoro, la Eternulo, antaŭ mia patro David, kaj ĉar vi suferis ĉion, kion suferis mia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'Kaj Salomono forigis Ebjataron, ke li ne estu plu pastro al la Eternulo; por ke plenumiĝu la vorto de la Eternulo, kiun Li diris pri la domo de Eli en Ŝilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'La famo pri tio atingis Joabon (ĉar Joab aliĝis al Adonija, kvankam al Abŝalom li ne aliĝis); kaj Joab forkuris en la tabernaklon de la Eternulo kaj ekkaptis la kornojn de la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Oni raportis al la reĝo Salomono, ke Joab forkuris en la tabernaklon de la Eternulo kaj estas nun ĉe la altaro. Tiam Salomono sendis Benajan, filon de Jehojada, dirante al li: Iru, mortigu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Benaja venis en la tabernaklon de la Eternulo, kaj diris al li: Tiele diras la reĝo: Eliru! Sed tiu respondis: Ne, ĉi tie mi mortu. Kaj Benaja raportis tion al la reĝo, dirante: Tiele diris Joab, kaj tiele li respondis al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Tiam la reĝo diris al li: Faru, kiel li diris, mortigu lin kaj enterigu lin; por ke vi forigu de mi kaj de la domo de mia patro la senkulpan sangon, kiun Joab verŝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'La Eternulo refaligu lian sangon sur lian kapon, pro tio, ke li mortigis du virojn, kiuj estis pli virtaj kaj pli bonaj ol li, kaj li mortigis ilin per glavo, dum mia patro David tion ne sciis: Abneron, filon de Ner, militestron de Izrael, kaj Amasan, filon de Jeter, militestron de Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Ilia sango falu sur la kapon de Joab kaj sur la kapon de lia idaro por eterne; sed al David kaj al lia idaro kaj al lia domo kaj al lia trono estu paco por eterne de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Tiam Benaja, filo de Jehojada, iris kaj frapis lin kaj mortigis lin, kaj oni enterigis lin en lia domo en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Kaj la reĝo starigis Benajan, filon de Jehojada, anstataŭ li kiel militestron, kaj la pastron Cadok la reĝo starigis anstataŭ Ebjatar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Kaj la reĝo sendis por voki Ŝimein, kaj li diris al li: Konstruu al vi domon en Jerusalem, kaj loĝu tie kaj nenien eliru el tie;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'se iun tagon vi eliros kaj transiros la torenton Kidron, tiam sciu, ke vi nepre mortos; via sango estos sur via kapo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Kaj Ŝimei diris al la reĝo: Bone; kiel diris mia sinjoro la reĝo, tiel via servanto faros. Kaj Ŝimei loĝis en Jerusalem multe da tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Sed post paso de tri jaroj forkuris du sklavoj de Ŝimei al Aĥiŝ, filo de Maaĥa, reĝo de Gat. Kaj oni sciigis al Ŝimei, dirante: Jen viaj sklavoj estas en Gat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Tiam Ŝimei leviĝis, kaj selis sian azenon kaj iris en Gaton al Aĥiŝ, por serĉi siajn sklavojn. Kaj Ŝimei iris, kaj revenigis siajn sklavojn el Gat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Kaj oni raportis al Salomono, ke Ŝimei foriris el Jerusalem en Gaton kaj revenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Tiam la reĝo sendis, kaj vokigis Ŝimein, kaj diris al li: Mi ĵurligis ja vin per la Eternulo kaj avertis vin, dirante, ke se iun tagon vi ien ajn foriros, tiam sciu, ke vi nepre mortos; kaj vi diris al mi: Bona estas tio, kion mi aŭdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Kial do vi ne observis la ĵuron per la Eternulo, kaj la ordonon, kiun mi faris al vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Kaj la reĝo diris al Ŝimei: Vi scias la tutan malbonon, kiun via koro scias kaj kiun vi faris al mia patro David; la Eternulo repagu vian malbonon sur via kapo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Sed la reĝo Salomono estu benata, kaj la trono de David staru forte antaŭ la Eternulo eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Kaj la reĝo ordonis al Benaja, filo de Jehojada, kaj ĉi tiu iris kaj frapis tiun, kaj tiu mortis. Kaj la regno fortikiĝis en la manoj de Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Kaj Salomono boparenciĝis kun Faraono, reĝo de Egiptujo, kaj prenis filinon de Faraono kaj venigis ŝin en la urbon de David, ĝis li finis la konstruadon de sia domo kaj de la domo de la Eternulo kaj de la muregoj de Jerusalem ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Tamen la popolo alportadis ankoraŭ oferojn sur altaĵoj, ĉar ĝis tiu tempo ankoraŭ ne estis konstruita domo al la nomo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Kaj Salomono amis la Eternulon, irante laŭ la instrukcioj de sia patro David; tamen li oferadis kaj incensadis sur altaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Kaj la reĝo iris en Gibeonon, por alporti tie oferojn, ĉar tie estis la ĉefa altaĵo. Mil bruloferojn Salomono alportis sur tiu altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'En Gibeon la Eternulo aperis al Salomono nokte en sonĝo, kaj Dio diris: Petu, kion Mi donu al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Kaj Salomono diris: Vi faris al Via servanto, mia patro David, multe da favoro, ĉar li iradis antaŭ Vi en vero kaj en justeco kaj en pureco de la koro koncerne Vin; kaj Vi konservis por li tiun grandan favorecon, kaj Vi donis al li filon, kiu sidas nun sur lia trono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Kaj nun, ho Eternulo, mia Dio, Vi reĝigis Vian servanton anstataŭ mia patro David; sed mi estas malgranda junulo; mi ne scias, kiel eliri kaj eniri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'Kaj Via servanto estas meze de Via popolo, kiun Vi elektis, popolo granda, kiu ne povas esti nombrata nek kalkulata pro sia multeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Donu do al Via servanto koron, kiu povoscius regi Vian popolon, distingi inter bono kaj malbono; ĉar kiu povas regi tiun Vian potencan popolon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Kaj tio plaĉis al la Sinjoro, ke Salomono petis tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Kaj Dio diris al li: Ĉar vi petis ĉi tion, sed ne petis por vi longan vivon kaj ne petis por vi riĉecon kaj ne petis la animon de viaj malamikoj, sed vi petis saĝon, por povoscii regi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'tial jen Mi faras konforme al via parolo: jen Mi donas al vi koron saĝan kaj kompreneman, tiel ke simila al vi ekzistis neniu antaŭ vi, kaj post vi ne aperos tia, kiel vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Sed ankaŭ tion, pri kio vi ne petis, Mi donos al vi, riĉecon kaj gloron, tiamaniere, ke ne ekzistos simila al vi inter la reĝoj dum via tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Kaj se vi irados laŭ Miaj vojoj, observante Miajn leĝojn kaj ordonojn, kiel iradis via patro David, Mi longigos vian vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Kaj Salomono vekiĝis, kaj vidis, ke tio estis sonĝo. Kaj li venis en Jerusalemon kaj stariĝis antaŭ la kesto de interligo de la Eternulo kaj alportis bruloferojn kaj faris pacoferojn, kaj li faris festenon por ĉiuj siaj servantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Tiam venis du virinoj malĉastistinoj al la reĝo kaj stariĝis antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'Kaj unu el la virinoj diris: Ho mia sinjoro! mi kaj ĉi tiu virino loĝas en unu domo; kaj mi naskis, loĝante kun ŝi en la sama domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'En la tria tago post mia nasko naskis ankaŭ ĉi tiu virino; kaj ni estis kune, estis neniu fremdulo kun ni en la domo, nur ni ambaŭ estis en la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Kaj la filo de ĉi tiu virino mortis en la nokto, ĉar ŝi dormis sur li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Kaj ŝi leviĝis meze de la nokto kaj prenis mian filon de ĉe mi, kiam via servantino dormis, kaj kuŝigis lin ĉe sia brusto, kaj sian mortintan filon ŝi almetis al mia brusto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Kiam mi leviĝis matene, por suĉigi mian filon, jen li estas senviva; sed kiam mi matene bone lin rigardis, mi vidis, ke tio ne estas mia filo, kiun mi naskis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Sed la dua virino diris: Ne, mia filo estas la vivanta, kaj via estas la mortinta. Kaj la unua diris: Ne, via filo estas la mortinta, kaj mia estas la vivanta. Kaj tiel ili parolis antaŭ la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Tiam la reĝo diris: Unu diras: Mia estas la vivanta filo, kaj via estas la mortinta; kaj la dua diras: Ne, via filo estas la mortinta, kaj mia filo estas la vivanta;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'kaj la reĝo diris: Alportu al mi glavon. Kaj oni alportis la glavon al la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Kaj la reĝo diris: Dishaku la vivantan infanon en du partojn, kaj donu duonon al unu kaj duonon al la alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Tiam la virino, kies filo estis la vivanta, ekparolis al la reĝo, ĉar ekscitiĝis ŝia kompato al ŝia filo, kaj ŝi diris: Ho mia sinjoro, donu al ŝi la infanon vivantan, sed ne mortigu ĝin. Sed la dua diris: Nek mi havu, nek vi; dishaku.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Tiam la reĝo respondis kaj diris: Donu al ŝi la vivantan infanon, sed ne mortigu ĝin; ŝi estas ĝia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Kaj ĉiuj Izraelidoj aŭdis pri la juĝo, kiun juĝis la reĝo; kaj ili ektimis la reĝon, ĉar ili vidis, ke en li estas saĝo de Dio, por fari juĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Kaj la reĝo Salomono estis reĝo super la tuta Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'Kaj jen estas la estroj, kiuj estis ĉe li: Azarja, filo de Cadok, pastro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Eliĥoref kaj Aĥija, filoj de Ŝiŝa, skribistoj; Jehoŝafat, filo de Aĥilud, kronikisto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'kaj Benaja, filo de Jehojada, super la militistaro; kaj Cadok kaj Ebjatar, pastroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'kaj Azarja, filo de Natan, super la administrantoj; kaj Zabud, filo de Natan, pastro, amiko de la reĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'kaj Aĥiŝar super la palaco; kaj Adoniram, filo de Abda, super la impostoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Kaj Salomono havis dek du administrantojn super la tuta Izrael, kaj ili liveradis provizaĵojn al la reĝo kaj al lia domo; unu monaton en jaro ĉiu el ili devis liveri provizaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Kaj jen estas iliaj nomoj: Ben-Ĥur, sur la monto de Efraim;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Ben-Deker, en Makac kaj Ŝaalbim kaj Bet-Ŝemeŝ kaj Elon-Bet-Ĥanan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Ben-Ĥesed, en Arubot; al li apartenis Soĥo kaj la tuta regiono Ĥefer;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Ben-Abinadab, super la tuta regiono Dor; Tafat, filino de Salomono, estis lia edzino;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baana, filo de Aĥilud, en Taanaĥ kaj Megido kaj super la tuta Bet- Ŝean, kiu estas apud Cartan, malsupre de Jizreel, de Bet-Ŝean ĝis Abel- Meĥola, ĝis trans Jokmeam;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Ben-Geber, en Ramot en Gilead; al li apartenis la Vilaĝoj de Jair, filo de Manase, kiuj estis en Gilead; al li apartenis la distrikto Argob, kiu estis en Baŝan, sesdek grandaj urboj kun muregoj kaj kupraj rigliloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Aĥinadab, filo de Ido, en Maĥanaim;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Aĥimaac, en la regiono de Naftali; ankaŭ li prenis Basmaton, filinon de Salomono, kiel edzinon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baana, filo de Ĥuŝaj, en la regiono de Aŝer kaj en Alot;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Jehoŝafat, filo de Paruaĥ, en la regiono de Isaĥar;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Ŝimei, filo de Ela, en la regiono de Benjamen;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Geber, filo de Uri, en la regiono Gilead, en la lando de Siĥon, reĝo de la Amoridoj, kaj de Og, reĝo de Baŝan. Unu administranto estis en tiu tuta lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Jehuda kaj Izrael estis grandnombraj kiel la sablo ĉe la maro; ili manĝis kaj trinkis kaj estis gajaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'Salomono regis super ĉiuj regnoj, de la Rivero ĝis la lando Filiŝta kaj ĝis la limo de Egiptujo; ili alportadis donacojn kaj servadis al Salomono dum lia tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'La manĝprovizoj de Salomono por ĉiu tago estis: tridek kor�oj da delikata faruno kaj sesdek kor�oj da simpla faruno,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'dek grasigitaj bovoj kaj dudek bovoj de paŝtejo kaj cent ŝafoj, krom cervoj kaj gazeloj kaj kapreoloj kaj grasigitaj birdoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'Ĉar li regis super la tuta transo de la Rivero, de Tifsaĥ ĝis Gaza, super ĉiuj reĝoj de trans la Rivero; kaj li havis pacon kun ĉiuj ĉirkaŭaj landoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'Kaj Jehuda kaj Izrael sidis en sendanĝereco, ĉiu sub siaj vinberbranĉoj kaj sub sia figarbo, de Dan ĝis Beer-Ŝeba, dum la tuta vivo de Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'Kaj Salomono havis kvardek mil stalojn por ĉarĉevaloj kaj dek du mil rajdistojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'Kaj tiuj administrantoj liveradis manĝprovizojn por la reĝo Salomono, kaj por ĉiuj, kiuj venadis al la tablo de la reĝo Salomono, ĉiu en sia monato, nenion mankigante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'Kaj la hordeon kaj pajlon por la ĉevaloj kaj la kurĉevaloj ili liveradis al la loko, kie li estis, ĉiu laŭ sia instrukcio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'Kaj Dio donis al Salomono saĝon kaj tre multe da prudento kaj tre multe da spirito, kiel la sablo ĉe la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'Kaj la saĝeco de Salomono estis pli granda, ol la saĝeco de ĉiuj orientanoj kaj ol la tuta saĝeco de Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'Kaj li estis pli saĝa, ol ĉiuj homoj, pli ol Etan la Ezraĥido, kaj Heman kaj Kalkol kaj Darda, filoj de Maĥol; kaj li estis fama inter ĉiuj popoloj ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'Kaj li eldiris tri mil sentencojn; kaj la nombro de liaj kantoj estis mil kaj kvin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'Kaj li parolis pri la arboj, de la cedro, kiu estas sur Lebanon, ĝis la hisopo, kiu elkreskas el la muro; kaj li parolis pri la brutoj kaj la birdoj kaj la rampaĵoj kaj la fiŝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'Kaj oni venadis el ĉiuj popoloj, por aŭskulti la saĝecon de Salomono, de ĉiuj reĝoj de la tero, kiuj aŭdis pri lia saĝeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Ĥiram, reĝo de Tiro, sendis siajn servantojn al Salomono, kiam li aŭdis, ke oni lin sanktoleis reĝo anstataŭ lia patro; ĉar Ĥiram estis amiko de David en la tuta tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Kaj Salomono sendis al Ĥiram, por diri:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'Vi scias pri mia patro David, ke li ne povis konstrui domon al la nomo de la Eternulo, lia Dio, pro la militantoj, kiuj lin ĉirkaŭis, ĝis la Eternulo metis ilin sub la plandojn de liaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Sed nun la Eternulo, mia Dio, donis al mi ripozon ĉirkaŭe; ne ekzistas kontraŭulo nek ia malbona malhelpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Tial jen mi intencas konstrui domon al la nomo de la Eternulo, mia Dio, kiel la Eternulo parolis al mia patro David, dirante: Via filo, kiun Mi sidigos anstataŭ vi sur via trono, konstruos la domon al Mia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Ordonu do nun, ke oni haku por mi cedrojn de Lebanon; kaj miaj servantoj estos kun viaj servantoj, kaj pagon por viaj servantoj mi donos al vi tian, kian vi diros; ĉar vi scias, ke ekzistas inter ni neniu, kiu povus haki arbojn kiel la Cidonanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Kiam Ĥiram aŭdis la vortojn de Salomono, li tre ekĝojis, kaj diris: Benata estu hodiaŭ la Eternulo, kiu donis al David filon saĝan super tiu grandnombra popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Kaj Ĥiram sendis al Salomono, por diri: Mi aŭskultis tion, kion vi sendis diri al mi; mi plenumos vian tutan deziron pri la arboj cedraj kaj arboj cipresaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Miaj servantoj malsuprenigos ilin de Lebanon al la maro, kaj mi flosos ilin sur la maro ĝis la loko, pri kiu vi sciigos al mi, kaj tie mi ilin disigos, kaj vi prenigos. Kaj vi plenumu mian deziron, kaj donu manĝaĵon por mia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Kaj Ĥiram donis al Salomono lignon cedran kaj lignon cipresan, kiom li nur volis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Kaj Salomono donis al Ĥiram dudek mil kor�ojn da tritiko kiel manĝaĵon por lia domo kaj dudek kor�ojn da plej pura oleo. Tiom Salomono donadis al Ĥiram ĉiujare.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Kaj la Eternulo donis saĝon al Salomono, kiel Li promesis al li. Kaj estis paco inter Ĥiram kaj Salomono, kaj ili ambaŭ faris inter si interligon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'La reĝo Salomono prenis imposton de la tuta Izrael; la imposto estis tridek mil viroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Kaj li sendis ilin sur Lebanonon, po dek mil ĉiumonate, alterne; unu monaton ili estis sur Lebanon kaj du monatojn en sia domo. Adoniram administris tiun imposton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Kaj Salomono havis sepdek mil ŝarĝoportistojn kaj okdek mil montajn ŝtonhakistojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'krom la tri mil tricent oficistoj, kiujn Salomono starigis super la laboroj kaj kiuj regis super la popolo okupita per la laboroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'Kaj la reĝo ordonis, ke oni elhaku grandajn ŝtonojn, multekostajn ŝtonojn, por aranĝi por la domo fundamenton el ŝtonoj ĉirkaŭhakitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Kaj hakis la konstruistoj de Salomono kaj la konstruistoj de Ĥiram kaj la Gebalanoj, kaj pretigis lignon kaj ŝtonojn, por konstrui la domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'En la jaro kvarcent-okdeka post la eliro de la Izraelidoj el la lando Egipta, en la kvara jaro de la reĝado de Salomono, en la monato Ziv, tio estas la dua monato, oni komencis konstrui la domon por la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Kaj la domo, kiun la reĝo Salomono konstruis por la Eternulo, havis la longon de sesdek ulnoj, la larĝon de dudek, kaj la alton de tridek ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Kaj la portiko antaŭ la templo de la domo havis la longon de dudek ulnoj, konforme al la larĝo de la domo; dek ulnoj estis ĝia larĝo antaŭ la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Kaj li faris en la domo fenestrojn fermeblajn kaj kovreblajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Kaj li aranĝis ĉe la muro de la domo galeriojn ĉirkaŭ la muroj de la domo, ĉirkaŭ la templo kaj la plejsanktejo, kaj li faris flankajn ĉambrojn ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'La malsupra galerio havis la larĝon de kvin ulnoj, la meza havis la larĝon de ses ulnoj, kaj la tria havis la larĝon de sep ulnoj; ĉar ĉirkaŭ la domo ekstere li faris ŝtupaĵojn, por ne enfortikigi en la muroj de la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Kiam la domo estis konstruata, ĝi estis konstruata el ŝtonoj prete ĉirkaŭhakitaj; martelo aŭ hakilo aŭ ia alia fera instrumento ne estis aŭdata en la domo dum ĝia konstruado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'La pordo de la meza galerio estis ĉe la dekstra flanko de la domo; kaj per ŝtuparo oni povis supreniri en la mezan galerion kaj el la meza en la trian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Kaj li konstruis la domon kaj finis ĝin, kaj li kovris la domon per traboj kaj tabuloj el cedroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Kaj li konstruis la galeriojn ĉirkaŭ la tuta domo, havantajn la alton de kvin ulnoj; kaj li kovris la domon per cedra ligno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Kaj la Eternulo ekparolis al Salomono, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'Koncerne la domon, kiun vi konstruas: se vi irados laŭ Miaj leĝoj kaj plenumados Miajn instrukciojn kaj observados ĉiujn Miajn ordonojn, por agadi laŭ ili, tiam Mi plenumos Mian promeson pri vi, kiun Mi eldiris al via patro David,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'kaj Mi loĝos inter la Izraelidoj kaj ne forlasos Mian popolon Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Kaj Salomono konstruis la domon kaj finis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'Kaj li konstruis la murojn de la domo interne el cedraj tabuloj; de la planko de la domo ĝis la plafono li kovris interne per ligno, kaj li kovris la plankon de la domo per cipresaj tabuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Kaj li konstruis en la distanco de dudek ulnoj de la rando de la domo cedrotabulan muron de la planko ĝis la plafono, kaj li konstruis tion interne por interna sanktejo, la plejsanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Kvardek ulnojn da longo havis la domo, tio estas la antaŭa parto de la templo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Sur la cedroj interne de la domo estis skulptitaj tuberoj kaj floroj; ĉio estis cedra, oni vidis nenian ŝtonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'La plejsanktejon li aranĝis en la domo por tio, ke oni starigu tie la keston de interligo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'La internon de la plejsanktejo, kiu havis la longon de dudek ulnoj, la larĝon de dudek ulnoj, kaj la alton de dudek ulnoj, li tegis per pura oro, kaj ankaŭ la cedran altaron li tegis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Kaj Salomono tegis la domon interne per pura oro, kaj li tiris orajn ĉenojn antaŭ la plejsanktejo kaj tegis ĝin per oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Kaj la tutan domon li tegis per oro, absolute la tutan domon, kaj la tutan altaron antaŭ la plejsanktejo li tegis per oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Kaj li faris en la plejsanktejo du kerubojn el oleastra ligno, havantajn la alton de dek ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'Kvin ulnojn havis unu flugilo de kerubo, kaj kvin ulnojn la dua flugilo de kerubo; dek ulnoj estis de unu fino de ĝiaj flugiloj ĝis la dua fino de ĝiaj flugiloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Kaj dek ulnojn havis ankaŭ la dua kerubo; la saman mezuron kaj la saman formon havis ambaŭ keruboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'La alto de unu kerubo estis dek ulnoj, kaj tiel same ankaŭ de la dua kerubo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Kaj li starigis la kerubojn meze de la interna parto de la domo; kaj la flugiloj de la keruboj estis etenditaj, kaj la flugilo de unu kerubo estis altuŝanta la muron, kaj la flugilo de la dua kerubo estis altuŝanta la duan muron; sed la flugiloj, kiuj estis direktitaj en la mezon de la domo, estis altuŝantaj unu la alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Kaj li tegis la kerubojn per oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Kaj sur ĉiuj muroj de la domo ĉirkaŭe li faris skulptitajn figurojn de keruboj, palmoj, kaj floroj, interne kaj ekstere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Ankaŭ la plankon de la domo li kovris per oro interne kaj ekstere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Ĉe la enirejo en la plejsanktejon li faris pordojn el oleastra ligno kun kvinangulaj fostoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Sur du pordoj el oleastra ligno li faris skulptitajn kerubojn kaj palmojn kaj florojn kaj tegis per oro; li tegis per oro la kerubojn kaj la palmojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Ankaŭ ĉe la enirejo en la templon li faris kvarangulajn fostojn el oleastra ligno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'kaj du pordojn el cipresa ligno; ambaŭ duonoj de unu pordo estis kunmeteblaj, kaj ambaŭ duonoj de la dua pordo estis kunmeteblaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Kaj li faris sur ili kerubojn kaj palmojn kaj florojn kaj tegis per oro ĝuste laŭ la skulptaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Kaj li konstruis la internan korton el tri vicoj da ĉirkaŭhakitaj ŝtonoj kaj el vico da cedraj traboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'En la kvara jaro, en la monato Ziv, estis fondita la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'Kaj en la dek-unua jaro, en la monato Bul, tio estas en la oka monato, la domo estis finita en ĉiuj siaj detaloj kaj laŭ sia tuta plano; li konstruis ĝin dum sep jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Kaj sian domon Salomono konstruis dum dek tri jaroj, kaj li finis sian tutan domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Kaj li konstruis la domon de la arbaro Lebanona; ĝi havis la longon de cent ulnoj, la larĝon de kvindek ulnoj, kaj la alton de tridek ulnoj; sur kvar vicoj da cedraj kolonoj, kaj cedraj traboj estis sur la kolonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'Kaj li kovris per cedro la supron de la galerioj, kiuj estis sur kvardek kvin kolonoj, po dek kvin en unu vico.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Kaj da fenestraj kadroj estis tri vicoj, kaj fenestroj kontraŭ fenestroj trifoje.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Kaj ĉiuj pordoj kaj la fostoj estis kvarangulaj, kaj la fenestroj estis kontraŭ fenestroj trifoje.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Kaj ĉambregon el kolonoj li faris, havantan la longon de kvindek ulnoj kaj la larĝon de tridek ulnoj; kaj ankoraŭ ĉambron antaŭ ili kaj kolonojn kaj sojlon antaŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Kaj tronan salonon, por tie juĝi, juĝan salonon li faris, kaj ĉiujn plankojn li kovris per cedro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Lia domo, en kiu li loĝis, en la malantaŭa korto post la salono, estis aranĝita tiel same. Kaj li faris ankaŭ domon, similan al tiu salono, por la filino de Faraono, kiun Salomono prenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Ĉio ĉi tio estis farita el multekostaj ŝtonoj, ĉirkaŭhakitaj laŭmezure, segitaj per segilo, interne kaj ekstere, de la fundamento ĝis la tegmento, kaj ekstere ĝis la granda korto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'En la fundamento estis ŝtonoj multekostaj, ŝtonoj grandaj, ŝtonoj de dek ulnoj kaj ŝtonoj de ok ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'Kaj supre estis multekostaj ŝtonoj, ĉirkaŭhakitaj laŭmezure, kaj cedro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Kaj la granda ĉirkaŭa korto havis tri vicojn da ĉirkaŭhakitaj ŝtonoj kaj unu vicon da cedraj traboj; tiel same ankaŭ la interna korto de la domo de la Eternulo kaj la salono ĉe la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'La reĝo Salomono sendis, kaj venigis el Tiro Ĥuramon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Li estis filo de unu vidvino, el la tribo de Naftali; lia patro estis Tirano, kupristo. Li estis plena de saĝeco, kompetenteco, kaj sciado, por fari ĉian laboron el kupro. Kaj li venis al la reĝo Salomono kaj plenumis ĉiujn liajn laborojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Li faris du kuprajn kolonojn, el kiuj unu kolono havis la alton de dek ok ulnoj, kaj fadeno de dek du ulnoj prezentis la amplekson de la dua kolono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Kaj du kapitelojn, fanditajn el kupro, li faris, por meti sur la suprojn de la kolonoj; kvin ulnoj estis la alto de unu kapitelo, kaj kvin ulnoj la alto de la dua kapitelo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Retoj plektitaj kaj ŝnuretoj ĉenoformaj estis ĉe la kapiteloj, kiuj estis supre de la kolonoj; sep ĉe unu kapitelo kaj sep ĉe la dua.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Kaj li faris la kolonojn tiel, ke du vicoj da granatoj estis ĉirkaŭ unu reto, por kovri la kapitelon; tiel same li faris ankaŭ por la dua kapitelo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'La kapiteloj sur la kolonoj estis faritaj kiel la lilioj en la salono, kaj havis kvar ulnojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Kaj la kapiteloj sur la du kolonoj super la konveksaĵo, kiu estis apud la reto; kaj sur la dua kapitelo ĉirkaŭe en vicoj ducent granatoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Kaj li starigis la kolonojn antaŭ la salono de la templo; kaj li starigis la dekstran kolonon kaj donis al ĝi la nomon Jaĥin; kaj li starigis la maldekstran kolonon kaj donis al ĝi la nomon Boaz.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Sur la suproj de la kolonoj estis skulptaĵo en formo de lilio. Tiel estis finita la laboro de la kolonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Kaj li faris maron fanditan, havantan dek ulnojn de rando ĝis rando, tute rondan, havantan la alton de kvin ulnoj; kaj ŝnuro de tridek ulnoj prezentis ĝian mezuron ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Kaj tuberoj sub ĝia rando troviĝis ĉirkaŭe de ĝi; sur la spaco de dek ulnoj ili ĉirkaŭis la maron en du vicoj; la tuberoj estis fanditaj kune kun ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Ĝi staris sur dek du bovoj; tri kun la vizaĝo norden, tri kun la vizaĝo okcidenten, tri kun la vizaĝo suden, kaj tri kun la vizaĝo orienten; kaj la maro estis sur ili supre, kaj ĉiuj iliaj malantaŭaj partoj estis turnitaj internen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Ĝi havis la dikon de manlarĝo; kaj ĝia rando, farita laŭ la maniero de rando de kaliko, estis simila al disvolviĝinta lilio. Ĝi ampleksis du mil bat�ojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Kaj li faris dek kuprajn bazaĵojn; ĉiu bazaĵo havis la longon de kvar ulnoj, la larĝon de kvar ulnoj, kaj la alton de tri ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Kaj jen estas la aranĝo de la bazaĵoj: ili havis muretojn, muretojn inter la listeloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'Kaj sur la muretoj, kiuj estis inter la listeloj, estis leonoj, bovoj, kaj keruboj; kaj sur la listeloj estis tiel supre, kaj sube de la leonoj kaj bovoj estis malsuprenpendantaj festonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Kaj ĉiu bazaĵo havis kvar kuprajn radojn kun kupraj aksoj, kaj ĝiaj kvar anguloj havis ŝultretojn, fanditajn ŝultretojn sub la kaldrono, kaj sur ĉiu flanko estis festonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Ĝia aperturo de la interna kapitelo ĝis la supro havis unu ulnon; ĝia aperturo estis ronda, en formo de bazeto, havanta unu ulnon kaj duonon, kaj ĉe la aperturo estis skulptaĵoj; sed ĝiaj muretoj estis kvarangulaj, ne rondaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Kaj la kvar radoj estis sub la muretoj, kaj la aksoj de la radoj estis en la bazaĵo; la alto de ĉiu rado estis unu ulno kaj duono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'La aranĝo de la radoj estis kiel la aranĝo de radoj de veturilo; iliaj aksoj kaj aksingoj kaj radradioj kaj radrondoj, ĉio estis fandita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Kaj la kvar ŝultretoj ĉe la kvar anguloj de ĉiu bazaĵo elstaris el la bazaĵo mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Supre de la bazaĵo estis rondaĵo, havanta la alton de duono de ulno; kaj supre de la bazaĵo ĝiaj teniloj kaj muretoj elstaris el ĝi mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Kaj sur la tabuletoj de ĝiaj teniloj kaj sur ĝiaj muretoj li skulptis kerubojn, leonojn, kaj palmojn, sur ĉiu libera loko, kaj festonojn ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Tiel li faris la dek bazaĵojn; ĉiuj havis egalan fandon, egalan mezuron, egalan formon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Kaj li faris dek kuprajn lavujojn; ĉiu lavujo havis la amplekson de kvardek bat�oj; kvar ulnojn havis ĉiu lavujo; ĉiu lavujo staris sur unu bazaĵo el la dek bazaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Kaj li starigis la bazaĵojn, kvin ĉe la dekstra flanko de la domo, kaj kvin ĉe la maldekstra flanko; kaj la maron li starigis ĉe la dekstra flanko de la domo, sudoriente.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Kaj Ĥuram faris la lavujojn kaj la ŝovelilojn kaj la aspergajn kalikojn. Kaj Ĥuram finis la tutan laboron, kiun li faris por la reĝo Salomono en la domo de la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'la du kolonojn kaj la du globaĵojn de la kapiteloj sur la supro de la kolonoj, kaj la du retojn por kovri la du globaĵojn de la kapiteloj, kiuj estis sur la supro de la kolonoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'kaj la kvarcent granatojn ĉe la du retoj, po du vicoj da granatoj por ĉiu reto, por kovri la du globaĵojn de la kapiteloj, kiuj estis sur la kolonoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'kaj la dek bazaĵojn kaj la dek lavujojn sur la bazaĵoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'kaj la unu maron kaj la dek du bovojn sub la maro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'kaj la kaldronojn kaj la ŝovelilojn kaj la aspergajn kalikojn. Kaj ĉiuj vazoj de la templo, kiujn Ĥuram faris al la reĝo Salomono por la domo de la Eternulo, estis el polurita kupro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'En la ĉirkaŭaĵo de Jordan la reĝo fandigis ilin en argila tero, inter Sukot kaj Cartan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Kaj Salomono metis ĉiujn vazojn sur ilian lokon. Pro la tre granda multo la pezo de la kupro ne estis kalkulita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Kaj Salomono faris ĉiujn vazojn, kiuj estas en la domo de la Eternulo: la oran altaron, kaj la oran tablon, sur kiu estas la pano de propono;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'kaj la kandelabrojn, kvin dekstre kaj kvin maldekstre antaŭ la plejsanktejo, el pura oro; kaj la florojn kaj lucernojn kaj prenilojn, el oro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'kaj la tasojn, tranĉilojn, aspergajn kalikojn, kulerojn, kaj karbujojn, el pura oro; kaj la maŝojn ĉe la pordo de la interna domo, de la plejsanktejo, ĉe la pordo de la templa domo, el oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Tiamaniere estis finita la tuta laboro, kiun la reĝo Salomono faris por la domo de la Eternulo. Kaj Salomono enportis la konsekritaĵojn de sia patro David; la arĝenton kaj la oron kaj la vazojn li metis en la trezorejojn de la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Tiam Salomono kunvenigis la plejaĝulojn de Izrael kaj ĉiujn ĉefojn de la triboj, la estrojn de la patrodomoj de la Izraelidoj, al la reĝo Salomono en Jerusalemon, por transporti la keston de interligo de la Eternulo el la urbo de David, tio estas el Cion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Kaj kolektiĝis al la reĝo Salomono ĉiuj Izraelidoj al la festo, en la monato Etanim, tio estas la sepa monato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Kaj venis ĉiuj plejaĝuloj de Izrael; kaj la pastroj ekportis la keston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'Kaj oni enportis la keston de la Eternulo kaj la tabernaklon de kunveno, kaj ĉiujn sanktajn vazojn, kiuj estis en la tabernaklo; ilin portis la pastroj kaj la Levidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Kaj la reĝo Salomono, kaj la tuta komunumo de Izrael, kiu kolektiĝis al li, estis kun li antaŭ la kesto, oferbuĉante ŝafojn kaj bovojn, kiujn oni ne povis nombri nek kalkuli pro ilia granda multeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Kaj la pastroj venigis la keston de interligo de la Eternulo sur ĝian lokon, en la profundon de la domo, en la plejsanktejon, sub la flugilojn de la keruboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Ĉar la keruboj havis siajn flugilojn etenditaj super la loko de la kesto, kaj la keruboj estis kovrantaj la keston kaj ĝiajn stangojn de supre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Kaj la stangoj estis tiel longaj, ke la kapetoj de la stangoj estis videblaj el la sankta loko en la antaŭa parto de la plejsanktejo, sed ekstere ili ne estis videblaj; kaj ili restis tie ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'En la kesto estis nenio krom la du ŝtonaj tabeloj, kiujn metis tien Moseo sur Ĥoreb, kiam la Eternulo faris interligon kun la Izraelidoj post ilia eliro el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Kiam la pastroj eliris el la sanktejo, nubo plenigis la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'Kaj la pastroj ne povis stari kaj servi, pro la nubo; ĉar la majesto de la Eternulo plenigis la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Tiam Salomono ekparolis: La Eternulo diris, ke Li deziras loĝi en mallumo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'tial mi konstruis domon por Via loĝado, lokon por Via restado eterna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Kaj la reĝo turnis sian vizaĝon kaj benis la tutan komunumon de Izrael; kaj la tuta komunumo de Izrael staris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Kaj li diris: Benata estu la Eternulo, Dio de Izrael, kiu parolis per Sia buŝo al mia patro David, kaj nun plenumis per Sia mano, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'De post la tago, kiam Mi elkondukis Mian popolon Izrael el Egiptujo, Mi elektis neniun urbon inter ĉiuj triboj de Izrael, por konstrui domon, en kiu estus Mia nomo; sed Mi elektis Davidon, ke li estu super Mia popolo Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Mia patro David havis la intencon konstrui domon al la nomo de la Eternulo, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Sed la Eternulo diris al mia patro David: Intencante konstrui domon al Mia nomo, vi agis bone, havante tian intencon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'tamen la domon konstruos ne vi, sed nur via filo, kiu eliris el viaj lumboj, konstruos la domon al Mia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Kaj la Eternulo plenumis Sian vorton, kiun Li diris: mi leviĝis anstataŭ mia patro David kaj sidiĝis sur la trono de Izrael, kiel diris la Eternulo, kaj mi konstruis la domon al la nomo de la Eternulo, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'Kaj mi aranĝis tie lokon por la kesto, en kiu troviĝas la interligo de la Eternulo, kiun Li faris kun niaj patroj, kiam Li elkondukis ilin el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Kaj Salomono stariĝis antaŭ la altaro de la Eternulo kontraŭ la tuta komunumo de Izrael, kaj li etendis siajn manojn al la ĉielo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'kaj li parolis: Ho Eternulo, Dio de Izrael! ne ekzistas dio simila al Vi en la ĉielo supre nek sur la tero malsupre; Vi konservas la interligon kaj la favorkorecon al Viaj servantoj, kiuj iradas antaŭ Vi per sia tuta koro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'Vi plenumis al Via servanto David, mia patro, kion Vi promesis al li; Vi parolis per Via buŝo, kaj Vi plenumis per Via mano, kiel ni nun vidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Nun, ho Eternulo, Dio de Izrael, plenumu al Via servanto David, mia patro, kion Vi promesis al li, dirante: Ne mankos ĉe vi antaŭ Mi viro, sidanta sur la trono de Izrael, se viaj filoj nur observados sian vojon, por iradi antaŭ Mi, kiel vi iradis antaŭ Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Nun, ho Dio de Izrael, veriĝu Via vorto, kiun Vi diris al Via servanto David, mia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Ĉu efektive Dio loĝus sur la tero? ja la ĉielo kaj la ĉielo de ĉieloj ne povas Vin ampleksi; des pli tion ne povas ĉi tiu domo, kiun mi konstruis!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Sed turnu Vin al la preĝo de Via servanto kaj al lia petego, ho Eternulo, mia Dio, por aŭskulti la vokadon kaj la preĝon, per kiu Via servanto preĝas antaŭ Vi hodiaŭ;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'por ke Viaj okuloj estu nefermitaj super ĉi tiu domo nokte kaj tage, super la loko, pri kiu Vi diris: Mia nomo tie estos; por aŭskulti la preĝon, kiun Via servanto faros sur ĉi tiu loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Kaj aŭskultu la petegon de Via servanto kaj de Via popolo Izrael, kiun ili preĝos sur ĉi tiu loko; aŭskultu sur la loko de Via loĝado en la ĉielo; kaj kiam Vi aŭskultos, Vi pardonu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Kiam iu pekos kontraŭ sia proksimulo, kaj oni postulos de li ĵuron, ke li ĵuru, kaj la ĵuro estos farata antaŭ Via altaro en ĉi tiu domo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'tiam aŭskultu en la ĉielo, kaj faru juĝon pri Viaj servantoj, kondamnante la manbonagulon, metante lian konduton sur lian kapon, kaj montrante la pravecon de la virtulo, rekompencante lin laŭ lia virteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Se Via popolo Izrael estos frapita de malamiko pro tio, ke ĝi pekis antaŭ Vi, sed ili sin returnos al Vi kaj gloros Vian nomon kaj preĝos kaj petegos al Vi en ĉi tiu domo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'tiam aŭskultu en la ĉielo, kaj pardonu la pekon de Via popolo Izrael, kaj revenigu ilin sur la teron, kiun Vi donis al iliaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Se la ĉielo ŝlosiĝos tiel, ke ne estos pluvo pro tio, ke ili pekis antaŭ Vi, sed ili ekpreĝos sur ĉi tiu loko kaj gloros Vian nomon kaj returnos sin de sia peko, por ke Vi aŭskultu ilin:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'tiam aŭskultu en la ĉielo, kaj pardonu la pekon de Viaj servantoj kaj de Via popolo Izrael, montrante al ili la bonan vojon, kiun ili devas iri, kaj donu pluvon sur Vian landon, kiun Vi donis al Via popolo kiel heredaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Se estos malsato en la lando, aŭ se estos pesto, brulsekeco, velkado, akridoj, aŭ vermoj, aŭ se premos ilin malamiko en la lando de ilia loĝado, aŭ se estos ia plago aŭ malsano;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'ĉe ĉiu preĝo, ĉe ĉiu petego, kiu venos de iu homo aŭ de Via tuta popolo Izrael, kiam ĉiu el ili sentos malfeliĉon en sia koro kaj etendos siajn manojn al ĉi tiu domo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'Vi aŭskultu en la ĉielo, en la loko de Via loĝado, kaj pardonu, kaj faru kaj redonu al ĉiu konforme al lia tuta konduto, kiel Vi konas lian koron (ĉar Vi sola konas la koron de ĉiuj homidoj);');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'por ke ili Vin timu dum la tuta tempo, kiun ili vivas sur la tero, kiun Vi donis al niaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Ankaŭ koncerne aligentulon, kiu ne estas el Via popolo Izrael, sed venos el malproksima lando pro Via nomo');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '(ĉar ili aŭdos pri Via granda nomo kaj pri Via forta mano kaj pri Via etendita brako), kaj li venos kaj preĝos en ĉi tiu domo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'Vi aŭskultu en la ĉielo, en la loko de Via loĝado, kaj faru ĉion, pri kio vokos al Vi la aligentulo; por ke ĉiuj popoloj de la tero konu Vian nomon, por ke ili timu Vin, kiel Via popolo Izrael, kaj por ke ili sciu, ke per Via nomo estas nomata ĉi tiu domo, kiun mi konstruis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Kiam Via popolo eliros milite kontraŭ sian malamikon laŭ la vojo, laŭ kiu Vi ilin sendos, kaj ili preĝos al la Eternulo, turninte sin al la urbo, kiun Vi elektis, kaj al la domo, kiun mi konstruis al Via nomo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'tiam aŭskultu en la ĉielo ilian preĝon kaj ilian petegon, kaj defendu ilian aferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Se ili pekos antaŭ Vi (ĉar ne ekzistas homo, kiu ne pekas), kaj Vi ekkoleros kontraŭ ili kaj transdonos ilin al malamiko, kaj iliaj kaptintoj forkondukos ilin en landon malamikan, malproksiman aŭ proksiman;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'sed ili rekonsciiĝos en la lando, en kiu ili estos kaptitaj, konvertiĝos, kaj petegos Vin en la lando de siaj kaptintoj, dirante: Ni pekis, ni malbonagis, ni krimis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'kaj ili returnos sin al Vi per sia tuta koro kaj per sia tuta animo en la lando de siaj malamikoj, kiuj ilin kaptis, kaj ili preĝos al Vi, turninte sin al sia lando, kiun Vi donis al iliaj patroj, al la urbo, kiun Vi elektis, kaj al la domo, kiun mi konstruis al Via nomo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'tiam aŭskultu en la ĉielo, en la loko de Via loĝado, ilian preĝon kaj ilian petegon, kaj defendu ilian aferon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'kaj pardonu al Via popolo tion, per kio ili pekis antaŭ Vi, kaj ĉiujn iliajn krimojn, kiujn ili faris kontraŭ Vi, kaj veku por ili kompaton en iliaj kaptintoj, por ke ĉi tiuj estu favorkoraj al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Ĉar ili estas Via popolo kaj Via heredaĵo, kiun Vi elkondukis el Egiptujo, el la fera forno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Viaj okuloj estu malfermitaj al la petego de Via servanto kaj al la petego de Via popolo Izrael, por ke Vi aŭdu ilin pri ĉio, pri kio ili vokas al Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Ĉar Vi distingis ilin kiel Vian heredaĵon el ĉiuj popoloj de la tero, kiel Vi diris per Via servanto Moseo, kiam Vi elkondukis niajn patrojn el Egiptujo, ho Sinjoro, Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Kiam Salomono finis preĝi antaŭ la Eternulo tiun tutan preĝon kaj petegon, li leviĝis de sia genuado antaŭ la altaro de la Eternulo, kaj liaj manoj estis etenditaj al la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'Kaj li stariĝis, kaj benis la tutan komunumon de Izrael per laŭta voĉo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Benata estu la Eternulo, kiu donis ripozon al Sia popolo Izrael konforme al ĉio, kion Li diris: ne forfalis eĉ unu vorto el ĉiuj Liaj bonaj vortoj, kiujn Li diris per Sia servanto Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'La Eternulo, nia Dio, estu kun ni, kiel Li estis kun niaj patroj, Li ne forlasu nin kaj ne forĵetu nin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'Li klinu nian koron al Si, por ke ni iru laŭ ĉiuj Liaj vojoj, kaj por ke ni observu Liajn ordonojn kaj Liajn leĝojn kaj Liajn regulojn, kiujn Li donis al niaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Kaj ĉi tiuj miaj vortoj, kiujn mi preĝis antaŭ la Eternulo, estu proksimaj al la Eternulo, nia Dio, tage kaj nokte, por ke Li faru justaĵon al Sia servanto kaj justaĵon al Sia popolo Izrael en ĉiuj tagoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'por ke ĉiuj popoloj de la tero sciu, ke la Eternulo estas Dio kaj ke ne ekzistas alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Via koro estu tute sindona al la Eternulo, nia Dio, por iri laŭ Liaj leĝoj kaj por observi Liajn ordonojn, kiel hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Kaj la reĝo kaj kun li ĉiuj Izraelidoj buĉis oferojn antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Kaj Salomono oferis la pacoferon, kiun li alportis al la Eternulo, dudek du mil bovojn kaj cent dudek mil ŝafojn. Tiamaniere la reĝo kaj ĉiuj Izraelidoj inaŭguris la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'En tiu tago la reĝo sanktigis la mezon de la korto, kiu estis antaŭ la domo de la Eternulo; ĉar li faris tie la bruloferon kaj la farunoferon kaj alportis ofere la sebon de la pacoferoj; ĉar la kupra altaro, kiu estis antaŭ la Eternulo, estis tro malgranda, por doni lokon al la brulofero kaj la farunofero kaj la sebo de la pacoferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Kaj Salomono faris tiam feston, kaj kun li la tuta Izrael, tre granda anaro, kiu kunvenis de Ĥamat ĝis la torento de Egiptujo, antaŭ la Eternulo, nia Dio, dum sep tagoj kaj ankoraŭ sep tagoj, kune dek kvar tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'En la oka tago li forsendis la popolon; kaj ili benis la reĝon, kaj iris al siaj tendoj, gajaj kaj ĝojantaj pro la tuta bono, kiun la Eternulo faris al Sia servanto David kaj al Sia popolo Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Kiam Salomono finis la konstruadon de la domo de la Eternulo kaj de la reĝa domo, kaj de ĉio dezirita de Salomono, kion li deziris fari,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'la Eternulo aperis al Salomono duan fojon, kiel Li aperis al li en Gibeon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'Kaj la Eternulo diris al li: Mi aŭdis vian preĝon kaj vian petegon, kiun vi faris antaŭ Mi; Mi sanktigis ĉi tiun domon, kiun vi konstruis, por ke Mi metu tien Mian nomon por eterne; kaj Miaj okuloj kaj Mia koro estos tie ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Kaj pri vi, se vi irados antaŭ Mi tiel, kiel iradis via patro David, kun pura koro kaj ĝusteco, farante ĉion, kion Mi ordonis al vi, kaj observante Miajn leĝojn kaj regulojn:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'tiam Mi fortikigos la tronon de via reĝado super Izrael por eterne, kiel Mi promesis al via patro David, dirante: Ne mankos ĉe vi viro sur la trono de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Sed se vi kaj viaj filoj deturnos vin de Mi, kaj ne observos Miajn ordonojn kaj Miajn leĝojn, kiujn Mi donis al vi, kaj vi iros kaj servos al aliaj dioj kaj adorkliniĝos al ili:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'tiam Mi ekstermos Izraelon de la lando, kiun Mi donis al li; kaj ĉi tiun domon, kiun Mi sanktigis por Mia nomo, Mi forpuŝos de antaŭ Mia vizaĝo; kaj Izrael fariĝos proverbo kaj moko inter ĉiuj popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Kaj pri ĉi tiu domo, kiu estas tre alta, ĉiu preteriranto miregos kaj fajfos; kaj oni diros: Pro kio la Eternulo agis tiele kun ĉi tiu lando kaj kun ĉi tiu domo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'Kaj oni respondos: Pro tio, ke ili forlasis la Eternulon, ilian Dion, kiu elkondukis iliajn patrojn el la lando Egipta, kaj ili aliĝis al aliaj dioj kaj adorkliniĝis al ili kaj servis al ili-pro tio la Eternulo venigis sur ilin ĉi tiun tutan malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Post paso de la dudek jaroj, dum kiuj Salomono konstruis la du domojn, la domon de la Eternulo kaj la reĝan domon');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, '(por kiuj Ĥiram, la reĝo de Tiro, liveris al Salomono cedrajn arbojn kaj cipresajn arbojn kaj oron laŭ lia tuta deziro), la reĝo Salomono tiam donis al Ĥiram dudek urbojn en la lando Galilea.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Kaj Ĥiram eliris el Tiro, por rigardi la urbojn, kiujn donis al li Salomono; kaj ili ne plaĉis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Kaj li diris: Kio estas tiuj urboj, kiujn vi donis al mi, mia frato? Kaj li donis al ili la nomon lando Kabul ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Kaj Ĥiram sendis al la reĝo cent dudek kikarojn da oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Jen estas la aranĝo pri la impostoj, kiujn starigis la reĝo Salomono, por konstrui la domon de la Eternulo kaj sian domon kaj Milon kaj la muregon de Jerusalem kaj Ĥacoron kaj Megidon kaj Gezeron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, '(Faraono, reĝo de Egiptujo, venis kaj venkoprenis Gezeron kaj forbruligis ĝin per fajro, kaj mortigis la Kanaanidojn, kiuj loĝis en la urbo, kaj li donis ĝin kiel donacon al sia filino, edzino de Salomono.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Kaj Salomono konstruis Gezeron, kaj la malsupran Bet-Ĥoronon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'kaj Baalaton, kaj Tadmoron en la dezerto, en la lando,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'kaj ĉiujn urbojn de provizoj, kiujn Salomono havis, kaj la urbojn por la ĉaroj kaj la urbojn por la rajdistoj, kaj ĉion, kion Salomono deziris konstrui en Jerusalem kaj sur Lebanon kaj en la tuta lando de sia regado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Koncerne la tutan popolon, kiu restis el la Amoridoj, Ĥetidoj, Perizidoj, Ĥividoj, kaj Jebusidoj, kiuj ne estis el la idoj de Izrael:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'iliajn infanojn, kiuj restis post ili en la lando kaj kiujn la Izraelidoj ne povis ekstermi, Salomono faris tributuloj-laboristoj ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Sed el la Izraelidoj Salomono ne faris laboristojn; ili estis militistoj, liaj servantoj, liaj eminentuloj, liaj militestroj, liaj ĉarestroj, kaj liaj rajdistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'La nombro de la ĉefaj oficistoj super la laboroj de Salomono estis kvincent kvindek; ili regis la popolon, kiu faris la laborojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'La filino de Faraono transiris el la urbo de David en sian domon, kiun li konstruis por ŝi; tiam li konstruis Milon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Kaj Salomono alportadis tri fojojn en jaro bruloferojn kaj pacoferojn sur la altaron, kiun li konstruis al la Eternulo, kaj incensadis ĉe ĝi antaŭ la Eternulo. Kaj li finkonstruis la domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Kaj ŝiparon faris la reĝo Salomono en Ecjon-Geber, kiu troviĝas apud Elat, sur la bordo de la Ruĝa Maro, en la lando de Edom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Kaj Ĥiram sendis en la ŝiparo siajn servantojn ŝipistojn, spertajn maristojn, kun la servantoj de Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Kaj ili venis Ofiron, kaj prenis de tie kvarcent dudek kikarojn da oro kaj venigis al la reĝo Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Kiam la reĝino de Ŝeba aŭdis la famon pri Salomono kaj pri la domo de la Eternulo, ŝi venis, por elprovi lin per enigmoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Kaj ŝi venis Jerusalemon kun tre granda akompanantaro, kun kameloj, portantaj aromaĵojn, tre multe da oro, kaj multekostajn ŝtonojn. Kaj ŝi venis al Salomono, kaj parolis kun li pri ĉio, kion ŝi havis en sia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Kaj Salomono solvis al ŝi ĉiujn ŝiajn demandojn; kaj estis nenio, kion la reĝo ne scius kaj kion li ne solvus al ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Kaj la reĝino de Ŝeba vidis la tutan saĝecon de Salomono, kaj la domon, kiun li konstruis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'kaj la manĝaĵon ĉe lia tablo kaj la loĝejon de liaj sklavoj kaj la oficojn de liaj servantoj kaj iliajn vestojn kaj liajn vinverŝistojn, kaj liajn bruloferojn, kiujn li oferadis en la domo de la Eternulo; kaj ŝi estis tute ravita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Kaj ŝi diris al la reĝo: Vera estas tio, kion mi aŭdis en mia lando pri viaj aferoj kaj pri via saĝeco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'mi ne kredis al la diroj, ĝis mi venis kaj ĝis miaj okuloj ekvidis; sed nun mi vidas, ke oni ne rakontis al mi eĉ duonon; vi havas pli da saĝo kaj bono, ol diras la famo, kiun mi aŭdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Feliĉaj estas viaj homoj, feliĉaj estas viaj servantoj, kiuj ĉiam staras antaŭ vi kaj aŭdas vian saĝecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Benata estu la Eternulo, via Dio, kiu favoras vin kaj sidigis vin sur la tronon de Izrael. Pro Sia eterna amo al Izrael Li faris vin reĝo, por ke vi zorgu pri juĝo kaj justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Kaj ŝi donacis al la reĝo cent dudek kikarojn da oro kaj tre multe da aromaĵoj kaj multekostajn ŝtonojn; neniam plu venis tiom multe da aromaĵoj, kiom la reĝino de Ŝeba donacis al la reĝo Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Kaj la ŝiparo de Ĥiram, kiu venigis oron el Ofir, alvenigis el Ofir tre multe da santala ligno kaj multekostajn ŝtonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Kaj el la santala ligno la reĝo faris pilastrojn por la domo de la Eternulo kaj por la reĝa domo, ankaŭ harpojn kaj psalterojn por la kantistoj; neniam venis tiom da santala ligno, nek estis vidata, ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Kaj la reĝo Salomono donis al la reĝino de Ŝeba ĉion, kion ŝi deziris kaj kion ŝi petis, krom tio, kion li donis al ŝi el la mano de la reĝo Salomono mem. Kaj ŝi foriris returne en sian landon, ŝi kaj ŝiaj servantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'La pezo de la oro, kiu estis alportita al Salomono dum unu jaro, estis sescent sesdek ses kikaroj da oro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'krom tio, kio venis de la butikistoj kaj de la komerco de negocistoj kaj de ĉiuj reĝoj de Arabujo kaj de la regionestroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Kaj la reĝo Salomono faris ducent grandajn ŝildojn el forĝita oro (sescent sikloj da oro estis uzitaj por ĉiu ŝildo)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'kaj tricent malgrandajn ŝildojn el forĝita oro (tri min�oj da oro estis uzitaj por ĉiu el tiuj ŝildoj); kaj la reĝo metis ilin en la arbardomon de Lebanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Kaj la reĝo faris grandan tronon el eburo kaj tegis ĝin per pura oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Ses ŝtupojn havis la trono, rondan supron havis la trono malantaŭe, kaj brakapogojn ambaŭflanke de la sidloko, kaj du leonojn, starantajn apud la brakapogoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'Kaj ankoraŭ dek du leonoj tie staris sur la ses ŝtupoj ambaŭflanke; ne ekzistis io simila en iu ajn regno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Kaj ĉiuj trinkvazoj de la reĝo Salomono estis el oro, kaj ĉiuj vazoj de la Lebanona arbardomo estis el pura oro; nenio estis el arĝento; en la tempo de Salomono ĝi estis rigardata kiel senvalora.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Ĉar Tarŝiŝan ŝiparon la reĝo havis sur la maro kun la ŝiparo de Ĥiram; unu fojon en tri jaroj venadis la Tarŝiŝa ŝiparo, alportante oron, arĝenton, eburon, simiojn, kaj pavojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Tiel la reĝo Salomono superis ĉiujn reĝojn de la tero per riĉeco kaj per saĝeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Kaj ĉiuj sur la tero penis vidi Salomonon, por aŭdi lian saĝon, kiun Dio enmetis en lian koron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Kaj ili alportadis ĉiu sian donacon: vazojn arĝentajn, vazojn orajn, vestojn, batalilojn, aromaĵojn, ĉevalojn, kaj mulojn, ĉiujare.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Kaj Salomono kolektis al si ĉarojn kaj rajdistojn; kaj li havis mil kvarcent ĉarojn kaj dek du mil rajdistojn; kaj li lokis ilin en la urboj de ĉaroj kaj ĉe la reĝo en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Kaj la reĝo atingis tion, ke la arĝento estis en Jerusalem kiel ŝtonoj, kaj la cedroj estis en tiel granda kvanto, kiel sikomoroj sur malaltaj lokoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'La ĉevalojn al Salomono oni venigadis el Egiptujo; kaj societo de komercistoj de la reĝo aĉetadis ilin amase laŭ difinita prezo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'Ĉiu ĉaro estis liverata el Egiptujo pro sescent sikloj da arĝento, kaj ĉiu ĉevalo pro cent kvindek; tiel same ili estis liverataj per iliaj manoj al ĉiuj reĝoj de la Ĥetidoj kaj al la reĝoj de Sirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'La reĝo Salomono amis multajn aligentajn virinojn, la filinon de Faraono, Moabidinojn, Amonidinojn, Edomidinojn, Cidonaninojn, Ĥetidinojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'el tiuj popoloj, pri kiuj la Eternulo diris al la Izraelidoj: Ne iru al ili, kaj ili ne iru al vi, ĉar ili turnos vian koron al siaj dioj; al ili Salomono aliĝis per amo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Kaj li havis da ĉefaj edzinoj sepcent kaj da kromvirinoj tricent; kaj liaj edzinoj forklinis lian koron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'En la tempo de maljuneco de Salomono liaj edzinoj turnis lian koron al aliaj dioj, kaj lia koro ne estis tiel plene fordonita al la Eternulo, lia Dio, kiel la koro de lia patro David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Kaj Salomono sekvis Aŝtaron, diaĵon de la Cidonanoj, kaj Milkomon, abomenindaĵon de la Amonidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Kaj Salomono faris malbonon antaŭ la okuloj de la Eternulo, kaj ne sekvis plene la Eternulon, kiel lia patro David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Tiam Salomono konstruis altaĵon al Kemoŝ, abomenindaĵo de la Moabidoj, sur la monto, kiu estas antaŭ Jerusalem, kaj al Moleĥ, abomenindaĵo de la Amonidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Kaj tiel li faris por ĉiuj siaj aligentaj edzinoj, kiuj incensadis kaj alportadis oferojn al siaj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Kaj la Eternulo ekkoleris Salomonon pro tio, ke li forklinis sian koron de la Eternulo, Dio de Izrael, kiu aperis al li du fojojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'kaj kiu ordonis al li pri tiu afero, ke li ne sekvu aliajn diojn; sed li ne observis tion, kion la Eternulo ordonis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Kaj la Eternulo diris al Salomono: Pro tio, ke ĉi tio fariĝis ĉe vi, kaj ke vi ne observis Mian interligon kaj Miajn leĝojn, kiujn Mi donis al vi, Mi forŝiros de vi la regnon kaj donos ĝin al via servanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Tamen dum via vivo Mi tion ne faros, pro via patro David; el la manoj de via filo Mi ĝin forŝiros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Sed ne la tutan regnon Mi forŝiros; unu tribon Mi donos al via filo, pro Mia servanto David, kaj pro Jerusalem, kiun Mi elektis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Kaj la Eternulo aperigis kontraŭulon kontraŭ Salomono, Hadadon, la Edomidon, el la reĝa semo de Edom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Kiam David estis en Edomujo, kaj la militestro Joab venis, por enterigi la mortigitojn, li mortigis ĉiujn virseksulojn en Edomujo');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, '(ĉar ses monatojn tie restis Joab kaj ĉiuj Izraelidoj, ĝis ili ekstermis ĉiujn virseksulojn en Edomujo);');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'tiam forkuris Hadad kune kun viroj Edomidoj el la servantoj de lia patro, por iri Egiptujon; Hadad estis tiam malgranda knabo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Ili elmoviĝis el Midjan kaj venis Paranon kaj prenis kun si homojn el Paran, kaj venis Egiptujon al Faraono, reĝo de Egiptujo, kaj ĉi tiu donis al li domon kaj nutraĵon, kaj ankaŭ landon li donis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Hadad tre ekplaĉis al Faraono, kaj ĉi tiu donis al li kiel edzinon fratinon de sia edzino, fratinon de la reĝino Taĥpenes.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Kaj la fratino de Taĥpenes naskis al li lian filon Genubat. Kaj Taĥpenes edukis lin en la domo de Faraono, kaj Genubat loĝis en la domo de Faraono inter la filoj de Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Kiam Hadad aŭdis en Egiptujo, ke David ekdormis kun siaj patroj kaj ke la militestro Joab mortis, Hadad diris al Faraono: Forliberigu min, ke mi iru en mian landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Faraono diris al li: Ĉu io mankas al vi ĉe mi, ke vi deziras iri en vian landon? Kaj li respondis: Ne, tamen forliberigu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Dio starigis kontraŭ li ankoraŭ kontraŭulon, Rezonon, filon de Eljada, kiu forkuris de sia sinjoro Hadadezer, reĝo de Coba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'Kaj li kolektis kontraŭ li virojn kaj fariĝis estro de bando, kiam David ilin mortigis; kaj ili iris Damaskon kaj ekloĝis tie kaj ekregis en Damasko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'Kaj li estis kontraŭulo de la Izraelidoj dum la tuta vivo de Salomono, krom la malbono, kiu venadis de Hadad. Kaj li havis malamon kontraŭ la Izraelidoj, kaj li fariĝis reĝo de Sirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Kaj Jerobeam, filo de Nebat, Efratano el Cereda, kies patrino havis la nomon Cerua kaj estis vidvino, servanto de Salomono, levis la manon kontraŭ la reĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Kaj jen estas la kaŭzo, pro kiu li levis la manon kontraŭ la reĝon: Salomono konstruis Milon; li riparis la breĉojn de la urbo de sia patro David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Jerobeam estis viro forta kaj kuraĝa. Kiam Salomono vidis, ke la junulo estas laborkapabla, li starigis lin administranto de la tributlaboroj de la domo de Jozef.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'En tiu tempo okazis, ke Jerobeam eliris el Jerusalem; kaj renkontis lin sur la vojo la profeto Aĥija, la Ŝiloano; li portis sur si novan veston; ili ambaŭ estis solaj sur la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Kaj Aĥija prenis la novan veston, kiu estis sur li, kaj disŝiris ĝin en dek du pecojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'Kaj li diris al Jerobeam: Prenu al vi dek pecojn; ĉar tiele diras la Eternulo, Dio de Izrael: Jen Mi forŝiras la regnon el la manoj de Salomono kaj donas al vi dek tribojn');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, '(sed unu tribo restos ĉe li, pro Mia servanto David, kaj pro la urbo Jerusalem, kiun Mi elektis el ĉiuj triboj de Izrael);');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'pro tio, ke ili forlasis Min, kaj adorkliniĝis al Aŝtar, diaĵo de la Cidonanoj, al Kemoŝ, dio de Moab, kaj al Milkom, dio de la Amonidoj, kaj ne iris laŭ Miaj vojoj, por plenumi tion, kio plaĉas al Mi, kaj Miajn leĝojn kaj Miajn regulojn, kiel lia patro David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Mi ne prenos la tutan regnon el liaj manoj, sed Mi faros, ke li restos reganto dum sia tuta vivo, pro Mia servanto David, kiun Mi elektis kaj kiu observis Miajn ordonojn kaj Miajn leĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Sed Mi prenos la regnon el la manoj de lia filo, kaj Mi donos el ĝi al vi dek tribojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'kaj al lia filo Mi donos unu tribon, por ke restu lumilo por ĉiam al Mia servanto David antaŭ Mi en Jerusalem, en la urbo, kiun Mi elektis al Mi, por meti tien Mian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Vin Mi prenos, kaj vi regos super ĉio, kion via animo deziros, kaj vi estos reĝo super Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Kaj se vi obeos ĉion, kion Mi ordonos al vi, kaj iros laŭ Miaj vojoj, kaj faros tion, kio plaĉas al Mi, observante Miajn leĝojn kaj Miajn ordonojn, kiel faris Mia servanto David, tiam Mi estos kun vi, kaj konstruos al vi domon fidindan, kiel Mi konstruis al David, kaj Mi donos al vi Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'Kaj per tio Mi humiligos la semon de David, tamen ne por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Salomono intencis mortigi Jerobeamon; sed Jerobeam leviĝis kaj forkuris en Egiptujon, al Ŝiŝak, reĝo de Egiptujo, kaj li restis en Egiptujo ĝis la morto de Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'La tuta cetera historio de Salomono, kaj ĉio, kion li faris, kaj lia saĝeco estas priskribitaj en la libro de kroniko de Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'La tempo, dum kiu Salomono reĝis en Jerusalem super la tuta Izrael, estis kvardek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Kaj Salomono ekdormis kun siaj patroj kaj estis enterigita en la urbo de sia patro David. Kaj anstataŭ li ekreĝis Reĥabeam, lia filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Reĥabeam iris en Ŝeĥemon, ĉar en Ŝeĥemon venis ĉiuj Izraelidoj, por fari lin reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Kiam tion aŭdis Jerobeam, filo de Nebat (ĉar li estis ankoraŭ en Egiptujo, kien li forkuris de la reĝo Salomono, kaj Jerobeam loĝis en Egiptujo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'sed oni sendis kaj vokis lin), tiam Jerobeam kaj la tuta komunumo de Izrael venis, kaj ekparolis al Reĥabeam, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'Via patro tro pezigis nian jugon; nun deprenu iom de la malfacilaj laboroj de via patro, kaj de lia peza jugo, kiun li metis sur nin, kaj tiam ni servados al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Kaj li diris al ili: Iru, kaj post tri tagoj revenu al mi. Kaj la popolo disiris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Kaj la reĝo Reĥabeam konsiliĝis kun la maljunuloj, kiuj staradis antaŭ lia patro Salomono dum lia vivo, kaj li diris: Kiel vi konsilas respondi al ĉi tiu popolo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'Kaj ili diris al li jene: Se hodiaŭ vi estos servanto al ĉi tiu popolo kaj komplezos al ili kaj kontentigos ilin kaj parolos al ili bonajn vortojn, ili estos al vi servantoj por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Sed li ne atentis la konsilon de la maljunuloj, kiun ili donis al li, kaj li konsiliĝis kun la junuloj, kiuj elkreskis kune kun li kaj staris antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'Kaj li diris al ili: Kion vi konsilas, ke ni respondu al ĉi tiu popolo, kiu diris al mi jene: Faru malpli peza la jugon, kiun via patro metis sur nin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Kaj la junuloj, kiuj elkreskis kune kun li, parolis al li, dirante: Tiele diru al ĉi tiu popolo, kiu diris al vi: Via patro faris nian jugon tro peza, kaj vi faru ĝin malpli peza-tiele diru al ili: Mia malgranda fingro estas pli dika, ol la lumboj de mia patro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'tial se mia patro ŝarĝis vin per peza jugo, mi ankoraŭ plipezigos vian jugon; mia patro vin punadis per vipoj, sed mi vin punados per skorpioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Kaj Jerobeam kaj la tuta popolo venis al Reĥabeam en la tria tago, kiel la reĝo ordonis, dirante: Revenu al mi en la tria tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'Kaj la reĝo respondis al la popolo malafable, kaj ne atentis la konsilon de la maljunuloj, kiun ili donis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'kaj li parolis al ili laŭ la konsilo de la junuloj, dirante: Mia patro pezigis vian jugon, sed mi ankoraŭ pli pezigos vian jugon; mia patro vin punadis per vipoj, sed mi vin punados per skorpioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Kaj la reĝo ne aŭskultis la popolon; ĉar estis destinite de la Eternulo, por ke plenumiĝu Lia vorto, kiun la Eternulo diris per Aĥija, la Ŝiloano, al Jerobeam, filo de Nebat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Kiam ĉiuj Izraelidoj vidis, ke la reĝo ilin ne obeas, tiam la popolo respondis al la reĝo, dirante: Kian parton ni havas en David? ni ne havas heredaĵon en la filo de Jiŝaj. Al viaj tendoj, ho Izrael! nun zorgu mem pri via domo, ho David! Kaj la Izraelidoj disiris al siaj tendoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Sed super la Izraelidoj, kiuj loĝis en la urboj de Judujo, reĝis Reĥabeam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Kaj la reĝo Reĥabeam sendis Adoramon, la estron super la impostoj; sed ĉiuj Izraelidoj ĵetis sur lin ŝtonojn, kaj li mortis. Kaj la reĝo Reĥabeam rapide sidiĝis en ĉaro, por forkuri en Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'Tiamaniere Izrael defalis de la domo de David ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Kiam ĉiuj Izraelidoj aŭdis, ke Jerobeam revenis, ili sendis kaj vokis lin al la kunveno kaj faris lin reĝo super ĉiuj Izraelidoj. La domon de David sekvis sole nur la tribo de Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Kaj kiam Reĥabeam venis en Jerusalemon, li kolektis el la tuta domo de Jehuda kaj el la tribo de Benjamen cent okdek mil elektitajn militistojn, por militi kontraŭ la domo de Izrael, por revenigi la regnon al Reĥabeam, filo de Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Sed aperis vorto de Dio al Ŝemaja, homo de Dio, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Diru al Reĥabeam, filo de Salomono, reĝo de Judujo, kaj al la tuta domo de Jehuda kaj de Benjamen kaj al la cetera popolo jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Tiele diras la Eternulo: Ne iru kaj ne militu kontraŭ viaj fratoj, la Izraelidoj; reiru ĉiu al sia domo, ĉar de Mi estas farita ĉi tiu afero. Kaj ili obeis la vorton de la Eternulo, kaj retenis sin de irado, konforme al la vorto de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Kaj Jerobeam prikonstruis Ŝeĥemon sur la monto de Efraim kaj ekloĝis en ĝi; kaj li eliris el tie kaj konstruis Penuelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Kaj Jerobeam diris en sia koro: Nun la regno povas reveni al la domo de David;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'se ĉi tiu popolo irados, por fari oferojn en la domo de la Eternulo en Jerusalem, tiam la koro de ĉi tiu popolo returniĝos al ilia sinjoro, al Reĥabeam, reĝo de Judujo; kaj ili mortigos min kaj revenos al Reĥabeam, reĝo de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Kaj la reĝo aranĝis konsiliĝon, kaj li faris du orajn bovidojn, kaj diris al la popolo: Ne iradu plu en Jerusalemon; jen estas viaj dioj, ho Izrael, kiuj elkondukis vin el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Kaj li starigis unu en Bet-El, kaj la duan li instalis en Dan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Kaj ĉi tiu afero fariĝis kaŭzo de pekado: la popolo komencis iradi al unu el ili ĝis Dan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Kaj li konstruis domojn de altaĵoj, kaj li starigis pastrojn el la popolo, kiuj ne estis el la idoj de Levi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Kaj Jerobeam starigis feston en la oka monato, en la dek-kvina tago de la monato, simile al la festo en Judujo, kaj li suriris sur la altaron; tiel li faris en Bet-El, alportante oferojn al la bovidoj, kiujn li faris; kaj li loĝigis en Bet-El la pastrojn de la altaĵoj, kiujn li aranĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Kaj li suriris sur la altaron, kiun li faris en Bet-El, en la dek-kvina tago de la oka monato, kiun li mem elpensis; kaj li faris feston por la Izraelidoj, kaj suriris sur la altaron, por incensi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Kaj jen homo de Dio venis el Judujo laŭ ordono de la Eternulo en Bet- Elon, kiam Jerobeam staris sur la altaro, por incensi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Kaj li vokis al la altaro laŭ ordono de la Eternulo kaj diris: Ho altaro, altaro! tiele diras la Eternulo: Jen en la domo de David naskiĝos filo, kies nomo estos Joŝija, kaj li buĉos sur vi la pastrojn de la altaĵoj, incensantajn sur vi, kaj homaj ostoj estos bruligitaj sur vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'Kaj li donis en tiu tago signon, dirante: Ĉi tio estas la signo, ke tion parolis la Eternulo: jen la altaro disfendiĝos, kaj la cindro, kiu estas sur ĝi, disŝutiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Kiam la reĝo aŭdis la vortojn de la homo de Dio, kiujn li vokis al la altaro en Bet-El, Jerobeam etendis sian manon de sur la altaro, kaj diris: Kaptu lin! Sed rigidiĝis lia mano, kiun li etendis kontraŭ lin, kaj li ne povis retiri ĝin al si.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Kaj la altaro disfendiĝis, kaj la cindro de la altaro disŝutiĝis, konforme al la signo, kiun donis la homo de Dio laŭ la ordono de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Kaj la reĝo ekparolis kaj diris al la homo de Dio: Faru peton antaŭ la Eternulo, via Dio, kaj preĝu por mi, por ke mia mano revenu al mi. Kaj la homo de Dio faris peton antaŭ la Eternulo, kaj la mano de la reĝo revenis al li kaj fariĝis kiel antaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Tiam la reĝo diris al la homo de Dio: Iru kun mi en la domon kaj fortigu vin per manĝo, kaj mi donos al vi donacon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Sed la homo de Dio diris al la reĝo: Eĉ se vi donos al mi duonon de via domo, mi ne iros kun vi, kaj mi ne manĝos panon nek trinkos akvon en ĉi tiu loko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'ĉar tiele estas ordonite al mi per la vorto de la Eternulo: Ne manĝu panon nek trinku akvon, kaj ne reiru laŭ la vojo, laŭ kiu vi venis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Kaj li iris laŭ alia vojo, kaj ne reiris laŭ la vojo, laŭ kiu li venis en Bet-Elon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Unu profeto maljunulo loĝis en Bet-El. Kaj venis liaj filoj, kaj rakontis al li la tutan aferon, kiun faris la homo de Dio hodiaŭ en Bet-El; la vortojn, kiujn li diris al la reĝo, ili rakontis al sia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'Kaj ilia patro diris al ili: Laŭ kiu vojo li iris? Kaj liaj filoj montris la vojon, laŭ kiu iris la homo de Dio, kiu venis el Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Tiam li diris al siaj filoj: Selu al mi la azenon. Kaj ili selis al li la azenon, kaj li ekrajdis sur ĝi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'kaj sekvis la homon de Dio kaj trovis lin sidanta sub kverko, kaj diris al li: Ĉu vi estas la homo de Dio, kiu venis el Judujo? Kaj tiu diris: Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Kaj li diris al li: Venu kun mi en la domon kaj manĝu panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Sed tiu diris: Mi ne povas reiri kun vi kaj veni al vi, kaj mi ne manĝos panon nek trinkos ĉe vi akvon en ĉi tiu loko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'ĉar estas dirite al mi per la vorto de la Eternulo: Ne manĝu panon nek trinku tie akvon, ne reiru laŭ la vojo, laŭ kiu vi venis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Kaj li diris al li: Mi ankaŭ estas profeto, kiel vi, kaj anĝelo diris al mi laŭ ordono de la Eternulo jene: Revenigu lin kun vi en vian domon, por ke li manĝu panon kaj trinku akvon. Li mensogis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Kaj li reiris kun li kaj manĝis panon en lia domo kaj trinkis akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Dum ili sidis ankoraŭ ĉe la tablo, venis la vorto de la Eternulo al la profeto, kiu lin revenigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'Kaj li vokis al la homo de Dio, kiu venis el Judujo, dirante: Tiele diras la Eternulo: Pro tio, ke vi malobeis la buŝon de la Eternulo, kaj ne plenumis la ordonon, kiun faris al vi la Eternulo, via Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'sed vi reiris kaj manĝis panon kaj trinkis akvon en la loko, pri kiu Li diris al vi, ke vi ne manĝu panon kaj ne trinku akvon, via kadavro ne venos en la tombon de viaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Post kiam li manĝis panon kaj trinkis, oni selis por li la azenon, por la profeto, kiun li revenigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'Kaj li iris, kaj sur la vojo renkontis lin leono kaj mortigis lin. Kaj lia kadavro kuŝis ĵetita sur la vojo, kaj la azeno staris apude, kaj la leono staris apud la kadavro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Kaj jen pasis homoj, kaj vidis la kadavron kuŝantan sur la vojo, kaj la leonon starantan apud la kadavro, kaj ili iris kaj rakontis en la urbo, en kiu loĝis la maljuna profeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Kiam tion aŭdis la profeto, kiu revenigis lin de la vojo, li diris: Tio estas la homo de Dio, kiu malobeis la buŝon de la Eternulo; la Eternulo transdonis lin al leono, kiu disŝiris kaj mortigis lin konforme al la vorto de la Eternulo, kiun Li diris al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Kaj li diris al siaj filoj jene: Selu al mi la azenon. Kaj ili selis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'Kaj li iris kaj trovis lian kadavron kuŝantan sur la vojo, kaj la azenon kaj la leonon starantajn apud la kadavro; la leono ne manĝis la kadavron kaj ne disŝiris la azenon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Kaj la profeto levis la kadavron de la homo de Dio kaj metis ĝin sur la azenon kaj veturigis ĝin returne. Kaj la maljuna profeto venis en la urbon, por priplori kaj enterigi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Kaj li metis lian kadavron en sian tombon; kaj ili priploris lin: Ho ve, mia frato!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Post kiam oni enterigis lin, li diris al siaj filoj jene: Kiam mi mortos, entombigu min en la tombo, en kiu estas entombigita la homo de Dio; apud liajn ostojn metu miajn ostojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Ĉar plenumiĝos la vorto, kiun li eldiris laŭ ordono de la Eternulo pri la altaro, kiu estas en Bet-El, kaj pri ĉiuj domoj de altaĵoj, kiuj troviĝas en la urboj de Samario.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Post tiu okazintaĵo Jerobeam ne retiris sin de sia malbona vojo, sed li denove starigis el la popolo pastrojn por la altaĵoj; kiun li volis, tiun li konsekris, ke li fariĝu pastro de altaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Kaj ĉi tio fariĝis peko por la domo de Jerobeam, por pereo kaj ekstermiĝo de sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'En tiu tempo malsaniĝis Abija, filo de Jerobeam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Kaj Jerobeam diris al sia edzino: Leviĝu kaj aliaspektiĝu, por ke oni ne sciu, ke vi estas edzino de Jerobeam, kaj iru en Ŝilon; tie troviĝas la profeto Aĥija, kiu antaŭdiris al mi, ke mi estos reĝo super ĉi tiu popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Kaj prenu en vian manon dek panojn kaj biskvitojn kaj kruĉon da mielo, kaj iru al li; li diros al vi, kio estos al la knabo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'Kaj la edzino de Jerobeam tiel faris; ŝi leviĝis kaj iris en Ŝilon kaj venis en la domon de Aĥija. Aĥija ne povis vidi, ĉar liaj okuloj ĉesis funkcii pro maljuneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Sed la Eternulo diris al Aĥija: Jen la edzino de Jerobeam iras, por demandi vin pri sia filo, ĉar li estas malsana; tiel kaj tiel diru al ŝi; kiam ŝi venos, ŝi prezentos sin kiel alian personon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'Kaj kiam Aĥija ekaŭdis la sonadon de ŝiaj piedoj, kiam ŝi eniris en la pordon, li diris: Eniru, edzino de Jerobeam; por kio vi prezentas vin kiel alian personon? mi estas sendita al vi kun sciigo premanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Iru, diru al Jerobeam: Tiele diras la Eternulo, Dio de Izrael: Ĉar Mi altigis vin el inter la popolo kaj faris vin princo super Mia popolo Izrael,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'kaj Mi forŝiris la regnon de la domo de David kaj donis ĝin al vi; sed vi ne estis kiel Mia servanto David, kiu observis Miajn ordonojn kaj sekvis Min per sia tuta koro, farante nur tion, kio plaĉas al Mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'kaj vi agis pli malbone, ol ĉiuj, kiuj estis antaŭ vi, kaj vi iris kaj faris al vi aliajn diojn kaj idolojn, por kolerigi Min, kaj Min vi ĵetis malantaŭ vian dorson:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'tial Mi venigos malbonon sur la domon de Jerobeam, kaj Mi ekstermos ĉe Jerobeam ĉiun virseksulon, malliberulon kaj liberulon en Izrael, kaj Mi elbalaos la domon de Jerobeam, kiel on elbalaas malpuraĵon, ĉion ĝis la fino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Kiu mortos ĉe Jerobeam en la urbo, tiun formanĝos la hundoj, kaj kiu mortos sur la kampo, tiun formanĝos la birdoj de la ĉielo; ĉar la Eternulo tion diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Kaj vi leviĝu, iru al via domo; kiam via piedo eniros en la urbon, la infano mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Kaj priploros lin ĉiuj Izraelidoj kaj enterigos lin; ĉar li sola ĉe Jerobeam iros en tombon, ĉar en li el la tuta domo de Jerobeam troviĝis io bona koncerne la Eternulon, Dion de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Kaj la Eternulo starigos al Si super Izrael reĝon, kiu ekstermos la domon de Jerobeam en tiu tago kaj baldaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Kaj la Eternulo frapos Izraelon, similigante lin al kano, kiu ŝanceliĝas en la akvo, kaj Li elŝiros la Izraelidojn el tiu bona tero, kiun Li donis al iliaj patroj, kaj Li disblovos ilin trans la Riveron pro tio, ke ili faris siajn sanktajn stangojn, kolerigante la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Kaj Li transdonos Izraelon pro la pekoj de Jerobeam, per kiuj li pekis kaj per kiuj li pekigis Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Kaj leviĝis la edzino de Jerobeam kaj foriris kaj venis en Tircan. Apenaŭ ŝi paŝis sur la sojlon de la domo, la knabo mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'Kaj oni enterigis lin, kaj ĉiuj Izraelidoj priploris lin, konforme al la vorto de la Eternulo, kiun Li diris per Sia servanto, la profeto Aĥija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'La cetera historio de Jerobeam, kiel li militis kaj kiel li reĝis, estas priskribita en la libro de kroniko de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'La tempo, dum kiu reĝis Jerobeam, estis dudek du jaroj. Kaj li ekdormis kun siaj patroj. Kaj anstataŭ li ekreĝis lia filo Nadab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Reĥabeam, filo de Salomono, reĝis en Judujo. La aĝon de kvardek unu jaroj havis Reĥabeam, kiam li fariĝis reĝo; kaj dek sep jarojn li reĝis en Jerusalem, la urbo, kiun la Eternulo elektis inter ĉiuj triboj de Izrael, por estigi tie Sian nomon. La nomo de lia patrino estis Naama, la Amonidino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Kaj la Judoj faris malbonon antaŭ la okuloj de la Eternulo, kaj incitis Lin pli ol ĉio, kion faris iliaj patroj per siaj pekoj, kiujn ili pekis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Kaj ankaŭ ili konstruis al si altaĵojn, statuojn, kaj sanktajn stangojn sur ĉiu alta monteto kaj sub ĉiu branĉoriĉa arbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Ankaŭ malĉastistoj estis en la lando; ili faris ĉiujn abomenindaĵojn de la popoloj, kiujn la Eternulo forpelis antaŭ la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'En la kvina jaro de la reĝo Reĥabeam iris Ŝiŝak, reĝo de Egiptujo, kontraŭ Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'Kaj li forprenis la trezorojn de la domo de la Eternulo kaj la trezorojn de la reĝa domo, ĉion li prenis; li prenis ankaŭ ĉiujn orajn ŝildojn, kiujn faris Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'Kaj la reĝo Reĥabeam faris anstataŭ ili ŝildojn kuprajn, kaj transdonis ilin en la manojn de la estroj de korpogardistoj, kiuj gardadis la enirejon de la reĝa domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'Kaj ĉiufoje, kiam la reĝo iris en la domon de la Eternulo, la korpogardistoj ilin portis, kaj poste returne portis ilin en la ĉambron de la korpogardistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'La cetera historio de Reĥabeam, kaj ĉio, kion li faris, estas priskribitaj en la libro de kroniko de la reĝoj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Kaj inter Reĥabeam kaj Jerobeam estis milito dum ilia tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Kaj Reĥabeam ekdormis kun siaj patroj, kaj oni enterigis lin kun liaj patroj en la urbo de David. La nomo de lia patrino estis Naama, Amonidino. Kaj anstataŭ li ekreĝis lia filo Abijam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'En la dek-oka jaro de la reĝo Jerobeam, filo de Nebat, ekreĝis Abijam super Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Tri jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Maaĥa, filino de Abiŝalom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Li iradis en ĉiuj pekoj de sia patro, kiujn ĉi tiu faris antaŭ li; kaj lia koro ne estis plene fordonita al la Eternulo, lia Dio, kiel la koro de lia patro David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Sed pro David la Eternulo, lia Dio, donis al li lumilon en Jerusalem, starigante lian filon post li kaj subtenante Jerusalemon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'pro tio, ke David faradis tion, kio plaĉas al la Eternulo, kaj dum sia tuta vivo ne forkliniĝis de ĉio, kion Li ordonis al li, krom la afero kun Urija, la Ĥetido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Kaj milito estis inter Reĥabeam kaj Jerobeam dum lia tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'La cetera historio de Abijam, kaj ĉio, kion li faris, estas priskribitaj en la libro de kroniko de la reĝoj de Judujo. Kaj milito estis inter Abijam kaj Jerobeam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Kaj Abijam ekdormis kun siaj patroj, kaj oni enterigis lin en la urbo de David. Kaj anstataŭ li ekreĝis lia filo Asa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'En la dudeka jaro de la reĝado de Jerobeam super Izrael ekreĝis Asa super Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Kaj kvardek unu jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Maaĥa, filino de Abiŝalom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Kaj Asa agadis, kiel plaĉas al la Eternulo, kiel lia patro David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Kaj li elpelis la malĉastistojn el la lando, kaj forigis ĉiujn idolojn, kiujn faris liaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Kaj eĉ sian patrinon Maaĥa li senigis je ŝia titolo de reĝino, pro tio, ke ŝi faris idolon por Aŝtar. Kaj Asa dishakis ŝian idolon kaj forbruligis ĉe la torento Kidron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Tamen la altaĵoj ne estis forigitaj; sed la koro de Asa estis perfekta ĉe la Eternulo dum lia tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Li enportis en la domon de la Eternulo la konsekritaĵojn de sia patro kaj siajn proprajn konsekritaĵojn, arĝenton kaj oron kaj vazojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Kaj milito estis inter Asa kaj Baaŝa, reĝo de Izrael, dum ilia tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Kaj Baaŝa, reĝo de Izrael, iris kontraŭ Judujon, kaj li konstruis Raman, por bari la eliradon kaj eniradon al Asa, reĝo de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Tiam Asa prenis la tutan arĝenton kaj oron, kiu restis en la trezorejo de la domo de la Eternulo kaj en la trezorejo de la reĝa domo, kaj donis tion en la manojn de siaj servantoj; kaj la reĝo Asa sendis ilin al Ben- Hadad, filo de Tabrimon, filo de Ĥezjon, reĝo de Sirio, kiu loĝis en Damasko, kaj dirigis al li:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Estas interligo inter mi kaj vi, inter mia patro kaj via patro; jen mi sendas al vi donacon, arĝenton kaj oron; neniigu vian interligon kun Baaŝa, reĝo de Izrael, por ke li foriru de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Kaj Ben-Hadad obeis la reĝon Asa, kaj sendis siajn militestrojn kontraŭ la urbojn de Izrael kaj venkobatis Ijonon kaj Danon kaj Abel-Bet- Maaĥan kaj la tutan Kineroton, la tutan landon de Naftali.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Kiam Baaŝa tion aŭdis, li ĉesis konstrui Raman kaj restis en Tirca.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Tiam la reĝo Asa kunvokis ĉiujn Judojn, sen escepto; kaj ili forportis la ŝtonojn de Rama kaj ĝian lignon, el kiuj Baaŝa faris la konstruadon; kaj la reĝo Asa konstruis el tio Geban de Benjamen kaj Micpan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'La cetera historio de Asa, kaj lia heroeco, kaj ĉio, kion li faris, kaj la urboj, kiujn li konstruis, estas priskribitaj en la libro de kroniko de la reĝoj de Judujo. Nur en sia maljuneco li malsaniĝis je siaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Kaj Asa ekdormis kun siaj patroj, kaj oni enterigis lin kun liaj patroj en la urbo de lia patro David. Kaj anstataŭ li ekreĝis lia filo Jehoŝafat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Nadab, filo de Jerobeam, fariĝis reĝo super Izrael en la dua jaro de Asa, reĝo de Judujo; kaj li reĝis super Izrael du jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Kaj li faris malbonon antaŭ la okuloj de la Eternulo, kaj iris laŭ la vojo de sia patro kaj en liaj pekoj, per kiuj li pekigis Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Kaj faris konspiron kontraŭ li Baaŝa, filo de Aĥija, el la domo de Isaĥar, kaj Baaŝa mortigis lin ĉe Gibeton de la Filiŝtoj, kiam Nadab kaj ĉiuj Izraelidoj sieĝis Gibetonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Kaj Baaŝa mortigis lin en la tria jaro de Asa, reĝo de Judujo, kaj ekreĝis anstataŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Kaj kiam li fariĝis reĝo, li mortigis la tutan domon de Jerobeam; li ne restigis ĉe Jerobeam eĉ unu animon, ĝis li tute lin ekstermis, konforme al la vorto de la Eternulo, kiun Li diris per Sia servanto Aĥija, la Ŝiloano;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'pro la pekoj de Jerobeam, per kiuj li pekis kaj per kiuj li pekigis Izraelon, pro la incito, per kiu li kolerigis la Eternulon, Dion de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'La cetera historio de Nadab, kaj ĉio, kion li faris, estas priskribitaj en la libro de kroniko de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Milito estis inter Asa kaj Baaŝa, reĝo de Izrael, dum ilia tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'En la tria jaro de Asa, reĝo de Judujo, ekreĝis Baaŝa, filo de Aĥija, super la tuta Izrael en Tirca por la daŭro de dudek kvar jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Kaj li faris malbonon antaŭ la okuloj de la Eternulo, kaj iris laŭ la vojo de Jerobeam kaj en liaj pekoj, per kiuj li pekigis Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Kaj aperis la vorto de la Eternulo al Jehu, filo de Ĥanani, pri Baaŝa, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'Ĉar mi levis vin el la polvo kaj faris vin reganto super Mia popolo Izrael kaj vi iras laŭ la vojo de Jerobeam kaj pekigas Mian popolon Izrael, incitante Min per iliaj pekoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'tial Mi elbalaos Baaŝan kaj lian domon, kaj Mi faros kun via domo kiel kun la domo de Jerobeam, filo de Nebat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Kiu mortos ĉe Baaŝa en la urbo, tiun formanĝos la hundoj, kaj kiu mortos ĉe li sur la kampo, tiun formanĝos la birdoj de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'La cetera historio de Baaŝa, kaj tio, kion li faris, kaj lia potenco estas priskribitaj en la libro de kroniko de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Kaj Baaŝa ekdormis kun siaj patroj, kaj oni enterigis lin en Tirca. Kaj anstataŭ li ekreĝis lia filo Ela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Per la profeto Jehu, filo de Ĥanani, aperis la vorto de la Eternulo pri Baaŝa kaj pri lia domo pro la tuta malbono, kiun li faris antaŭ la okuloj de la Eternulo, incitante Lin per la faroj de siaj manoj, estante kiel la domo de Jerobeam, kaj pro tio, ke li mortigis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'En la jaro dudek-sesa de Asa, reĝo de Judujo, ekreĝis Ela, filo de Baaŝa, super Izrael en Tirca por la daŭro de du jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Kaj faris konspiron kontraŭ li lia servanto Zimri, estro de duono de la ĉaroj. Kiam li en Tirca drinkis ĝis ebrieco en la domo de Arca, palacestro de Tirca,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'tiam venis Zimri kaj frapis lin kaj mortigis lin, en la jaro dudek-sepa de Asa, reĝo de Judujo, kaj faris sin reĝo anstataŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Kiam li fariĝis reĝo, kiam li eksidis sur lia trono, li mortigis la tutan domon de Baaŝa, restigante ĉe li neniun virseksulon, kaj ankaŭ liajn parencojn kaj amikojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Kaj Zimri ekstermis la tutan domon de Baaŝa, konforme al la vorto de la Eternulo, kiun Li diris pri Baaŝa per la profeto Jehu,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'pro ĉiuj pekoj de Baaŝa kaj la pekoj de lia filo Ela, per kiuj ili pekis kaj per kiuj ili pekigis Izraelon, incitante la Eternulon, Dion de Izrael, per siaj idolaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'La cetera historio de Ela, kaj ĉio, kion li faris, estas priskribitaj en la libro de kroniko de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'En la dudek-sepa jaro de Asa, reĝo de Judujo, ekreĝis Zimri por la daŭro de sep tagoj en Tirca, kiam la popolo sieĝis Gibetonon de la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Kiam la sieĝanta popolo aŭdis, ke Zimri faris konspiron kaj mortigis la reĝon, tiam la tuta popolo en la sama tago elektis kiel reĝon Omrin, la militestron de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Kaj Omri kune kun la tuta Izrael foriris de Gibeton kaj eksieĝis Tircan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Kiam Zimri vidis, ke la urbo estas prenita, li iris en la palacon de la reĝa domo kaj ekbruligis ĉirkaŭ si per fajro la reĝan domon, kaj mortis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'pro siaj pekoj, per kiuj li pekis, farante malbonon antaŭ la okuloj de la Eternulo, irante laŭ la vojo de Jerobeam kaj en lia peko, kiun li faris, pekigante Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'La cetera historio de Zimri, kaj lia konspiro, kiun li faris, estas priskribitaj en la libro de kroniko de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Tiam la popolo Izraela dividiĝis en du partojn: duono de la popolo aliĝis al Tibni, filo de Ginat, por reĝigi lin, kaj la dua duono aliĝis al Omri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Kaj la popolo, kiu aliĝis al Omri, venkis tiun popolon, kiu aliĝis al Tibni, filo de Ginat; kaj Tibni mortis, kaj ekreĝis Omri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'En la tridek-unua jaro de Asa, reĝo de Judujo, Omri ekreĝis super Izrael por la daŭro de dek du jaroj. En Tirca li reĝis dum ses jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Kaj li aĉetis la monton Samario de Ŝemer pro du kikaroj da arĝento, kaj li prikonstruis tiun monton, kaj al la urbo, kiun li konstruis, li donis la nomon Samario, laŭ la nomo de Ŝemer, la mastro de la monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Kaj Omri faris malbonon antaŭ la okuloj de la Eternulo, kaj li agis pli malbone, ol ĉiuj, kiuj estis antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Kaj li iris laŭ la tuta vojo de Jerobeam, filo de Nebat, kaj en liaj pekoj, per kiuj li pekigis Izraelon, incitante la Eternulon, Dion de Izrael, per iliaj idolaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'La cetera historio de Omri, tio, kion li faris, kaj liaj heroaĵoj, kiujn li faris, estas priskribitaj en la libro de kroniko de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Kaj Omri ekdormis kun siaj patroj, kaj oni enterigis lin en Samario. Kaj anstataŭ li ekreĝis lia filo Aĥab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Aĥab, filo de Omri, ekreĝis super Izrael en la tridek-oka jaro de Asa, reĝo de Judujo. Kaj Aĥab, filo de Omri, reĝis super Izrael en Samario dudek du jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Kaj Aĥab, filo de Omri, faris malbonon antaŭ la okuloj de la Eternulo, pli ol ĉiuj, kiuj estis antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Ne sufiĉis al li, ke li iris en la pekoj de Jerobeam, filo de Nebat: li prenis al si kiel edzinon Izebelon, filinon de Etbaal, reĝo de la Cidonanoj, kaj li iris kaj servis al Baal kaj adorkliniĝis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Kaj li starigis altaron al Baal en la domo de Baal, kiun li konstruis en Samario.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Kaj Aĥab faris sanktajn stangojn, kaj Aĥab faris pli da incitado kontraŭ la Eternulo, Dio de Izrael, ol ĉiuj reĝoj de Izrael, kiuj estis antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'En lia tempo Ĥiel, Bet-Elano, konstruis Jeriĥon. Kun perdo de sia unuenaskito Abiram li fondis ĝin, kaj kun perdo de sia plej juna filo Segub li starigis ĝiajn pordegojn, konforme al la vorto de la Eternulo, kiun Li diris per Josuo, filo de Nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Kaj Elija, la Teŝebano, el la loĝantoj de Gilead, diris al Aĥab: Kiel vivas la Eternulo, Dio de Izrael, antaŭ kiu mi staras, ne estos en ĉi tiuj jaroj roso nek pluvo, krom en la okazo, se mi tion diros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Kaj aperis la vorto de la Eternulo al li, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Foriru de ĉi tie, kaj direktu vin orienten, kaj kaŝu vin ĉe la torento Kerit, kiu estas oriente de Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'El tiu torento vi trinkados, kaj al la korvoj Mi ordonis, ke ili tie vin nutru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Kaj li iris kaj faris, kiel ordonis la Eternulo; li iris kaj restis ĉe la torento Kerit, kiu estas oriente de Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Kaj la korvoj alportadis al li panon kaj viandon matene kaj panon kaj viandon vespere; kaj el la torento li trinkadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Post kelka tempo la torento elsekiĝis, ĉar ne estis pluvo en la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Tiam aperis al li la vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Leviĝu, iru Carfaton, kiu apartenas al Cidon, kaj restu tie; Mi ordonis tie al virino vidvino, ke ŝi liveradu al vi manĝaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Kaj li leviĝis, kaj iris Carfaton. Kiam li venis al la pordego de la urbo, li ekvidis virinon vidvinon, kiu kolektis lignon. Kaj li vokis al ŝi, kaj diris: Alportu al mi iom da akvo en vazo, por ke mi trinku.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Kaj ŝi ekiris, por preni; tiam li vokis al ŝi, kaj diris: Alportu al mi pecon da pano en viaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Sed ŝi respondis: Kiel vivas la Eternulo, via Dio, mi ne havas bakitaĵon, sed nur plenmanon da faruno en la vazo kaj iom da oleo en la kruĉo; jen mi kolektis du pecojn da ligno, kaj mi iros kaj pretigos tion por mi kaj por mia filo, kaj ni tion manĝos kaj mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Kaj Elija diris al ŝi: Ne timu, iru kaj faru, kiel vi diris; tamen antaŭe faru al mi el tio malgrandan bakitaĵon kaj alportu al mi; kaj por vi kaj por via filo vi faros poste.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Ĉar tiele diras la Eternulo, Dio de Izrael: La faruno en la vazo ne konsumiĝos, kaj la oleo en la kruĉo ne mankos, ĝis la tago, kiam la Eternulo donos pluvon sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Kaj ŝi iris kaj faris, kiel ordonis Elija; kaj manĝis ŝi kaj li kaj ŝia domo dum kelka tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'La faruno en la vazo ne konsumiĝis, kaj la oleo en la kruĉo ne mankis, konforme al la vorto de la Eternulo, kiun Li diris per Elija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Post tiu okazintaĵo malsaniĝis la filo de la virino, la dommastrino; kaj lia malsano estis tre forta, tiel, ke li tute ĉesis spiri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Tiam ŝi diris al Elija: Kio estas inter mi kaj vi, homo de Dio? Vi venis al mi, por rememorigi pri miaj pekoj kaj mortigi mian filon!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Kaj li diris al ŝi: Donu al mi vian filon. Kaj li prenis lin el ŝiaj brakoj, kaj portis lin en la subtegmenton, en kiu li loĝis, kaj metis lin sur sian liton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Kaj li vokis al la Eternulo, kaj diris: Ho Eternulo, mia Dio! ĉu eĉ al la vidvino, ĉe kiu mi loĝas, Vi faros malbonon, mortigante ŝian filon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Kaj li etendis sin super la infano tri fojojn, kaj vokis al la Eternulo, kaj diris: Ho Eternulo, mia Dio, revenigu la animon de ĉi tiu infano en lian internon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Kaj la Eternulo aŭskultis la voĉon de Elija, kaj la animo de la infano revenis en lian internon, kaj li reviviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Kaj Elija prenis la infanon kaj portis lin malsupren el la subtegmento en la domon kaj redonis lin al lia patrino; kaj Elija diris: Rigardu, via filo vivas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Tiam la virino diris al Elija: Nun mi eksciis, ke vi estas homo de Dio kaj ke la vorto de la Eternulo en via buŝo estas vera.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Post multe da tempo aperis la vorto de la Eternulo al Elija en la tria jaro, dirante: Iru, montru vin al Aĥab, kaj Mi donos pluvon sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Kaj Elija iris, por montri sin al Aĥab. La malsato estis forta en Samario.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Aĥab vokis Obadjan, kiu estis lia palacestro. (Obadja estis tre diotima;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'kiam Izebel ekstermis la profetojn de la Eternulo, Obadja prenis cent profetojn kaj kaŝis ilin en kavernoj po kvindek homoj kaj nutradis ilin per pano kaj akvo.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'Kaj Aĥab diris al Obadja: Iru tra la lando al ĉiuj akvaj fontoj kaj al ĉiuj torentoj; eble ni trovos herbon, por ke ni povu konservi la vivon al la ĉevaloj kaj muloj kaj ne ekstermiĝu al ni ĉiuj brutoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Kaj ili dividis inter si la landon, por trairi ĝin: Aĥab iris aparte laŭ unu direkto, kaj Obadja iris aparte laŭ alia direkto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Kiam Obadja estis sur la vojo, subite venis al li renkonte Elija. Tiu rekonis lin kaj ĵetis sin vizaĝaltere, kaj diris: Ĉu tio estas vi, mia sinjoro Elija?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Kaj ĉi tiu respondis al li: Mi; iru, diru al via sinjoro, ke Elija estas ĉi tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Kaj li diris: Per kio mi pekis, ke vi transdonas vian servanton en la manon de Aĥab, por ke li mortigu min?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Kiel vivas la Eternulo, via Dio, ne ekzistas popolo aŭ regno, kien mia sinjoro ne estus sendinta min, por serĉi vin; kaj kiam ili diris, ke vi tie ne estas, li ĵurigis tiun regnon kaj popolon, ke oni ne trovis vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'Kaj nun vi diras: Iru, diru al via sinjoro, ke Elija estas ĉi tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Kaj okazos, ke kiam mi foriros de vi, la spirito de la Eternulo forportos vin, mi ne scias kien; mi venos, por diri al Aĥab, kaj li ne trovos vin, kaj tiam li mortigos min; kaj via servanto estas diotima de sia juneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Ĉu oni ne rakontis al mia sinjoro, kion mi faris, kiam Izebel mortigis la profetojn de la Eternulo, ke mi kaŝis cent homojn el la profetoj de la Eternulo en kavernoj po kvindek homoj kaj nutradis ilin per pano kaj akvo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'Kaj nun vi diras: Iru, diru al via sinjoro, ke Elija estas ĉi tie! li ja mortigos min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Tiam Elija diris: Kiel vivas la Eternulo Cebaot, antaŭ kiu mi staras, hodiaŭ mi montros min al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Kaj Obadja iris renkonte al Aĥab kaj diris al li. Tiam Aĥab iris renkonte al Elija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Kaj kiam Aĥab ekvidis Elijan, Aĥab diris al li: Ĉu tio estas vi, kiu senordigas Izraelon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Sed li respondis: Izraelon senordigis ne mi, sed vi kaj la domo de via patro, per tio, ke vi forlasis la ordonojn de la Eternulo kaj sekvis la Baalojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Kaj nun sendu, kunvenigu al mi la tutan Izraelon sur la monton Karmel, ankaŭ la kvarcent kvindek profetojn de Baal kaj la kvarcent profetojn de Aŝtar, kiuj estas nutrataj ĉe la tablo de Izebel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Kaj Aĥab sendis al ĉiuj Izraelidoj, kaj li kunvenigis la profetojn sur la monton Karmel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Tiam Elija aliris al la tuta popolo, kaj diris: Kiel longe ankoraŭ vi lamos sur du flankoj? se la Eternulo estas Dio, sekvu Lin; kaj se Baal, tiam sekvu lin. Kaj la popolo nenion respondis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Kaj Elija diris al la popolo: Mi restis la sola profeto de la Eternulo, kaj da profetoj de Baal estas kvarcent kvindek homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Oni donu do al ni du bovojn; kaj ili elektu al si unu el la bovoj kaj dishaku ĝin kaj metu sur la lignon, sed fajron ili ne submetu; kaj mi pretigos la duan bovon kaj metos sur la lignon, kaj fajron mi ne submetos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Kaj voku al la nomo de via dio, kaj mi vokos al la nomo de la Eternulo; kaj tiu Dio, kiu respondos per fajro, estu konfesata kiel Dio. Kaj la tuta popolo respondis kaj diris: Bone.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Kaj Elija diris al la profetoj de Baal: Elektu al vi unu el la bovoj kaj pretigu antaŭe, ĉar vi estas multaj; kaj voku al la nomo de via dio, sed fajron ne submetu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Kaj ili prenis la bovon, kiun li donis al ili, kaj pretigis, kaj vokadis al la nomo de Baal de la mateno ĝis la tagmezo, dirante: Ho Baal, aŭskultu nin! Sed aperis nenia voĉo nek respondo. Kaj ili saltadis ĉirkaŭ la altaro, kiun ili faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Kiam fariĝis tagmezo, Elija mokis ilin, kaj diris: Kriu per laŭta voĉo, ĉar li estas dio; eble li havas interparoladon, aŭ eble li foriris, aŭ eble li vojaĝas; eble li dormas, li do vekiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Kaj ili kriis per laŭta voĉo, kaj pikis sin laŭ sia kutimo per glavoj kaj lancoj, ĝis sango verŝiĝis sur ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Kiam pasis la tagmezo, ili ĉiam ankoraŭ faradis la ceremoniojn, ĝis venis la tempo, kiam oni faras la farunoferojn; sed estis nenia voĉo, nenia respondo, nenia atento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Tiam Elija diris al la tuta popolo: Aliru al mi. Kaj la tuta popolo aliris al li. Kaj li rekonstruis la detruitan altaron de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Kaj Elija prenis dek du ŝtonojn, laŭ la nombro de la triboj de la filoj de Jakob, al kiu aperis la vorto de la Eternulo, dirante: Via nomo estu Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'Kaj li konstruis el la ŝtonoj altaron en la nomo de la Eternulo, kaj li faris ĉirkaŭ la altaro foson, havantan la amplekson de du grenmezuroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Kaj li aranĝis la lignon, kaj dishakis la bovon kaj metis ĝin sur la lignon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Kaj li diris: Plenigu kvar sitelojn per akvo, kaj oni verŝu tion sur la bruloferon kaj sur la lignon. Poste li diris: Ripetu. Kaj oni ripetis. Kaj li diris: Faru same la trian fojon. Kaj oni faris same la trian fojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Kaj la akvo verŝiĝis ĉirkaŭen de la altaro, kaj ankaŭ la tuta foso pleniĝis de akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Kaj kiam venis la tempo, kiam oni faras farunoferon, la profeto Elija aliris, kaj diris: Ho Eternulo, Dio de Abraham, Isaak, kaj Izrael! hodiaŭ oni eksciu, ke Vi estas Dio ĉe Izrael kaj mi estas Via servanto, kaj ke laŭ Via vorto mi faris ĉion ĉi tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Aŭskultu min, ho Eternulo, aŭskultu min, por ke ĉi tiu popolo eksciu, ke Vi, Eternulo, estas Dio, kaj por ke Vi konvertu ilian koron returne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Tiam falis fajro de la Eternulo kaj konsumis la bruloferon kaj la lignon kaj la ŝtonojn kaj la polvon; kaj la akvon, kiu estis en la foso, ĝi forlekis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Kiam la tuta popolo tion vidis, ili ĵetis sin vizaĝaltere, kaj diris: La Eternulo estas Dio, la Eternulo estas Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Tiam Elija diris al ili: Kaptu la profetojn de Baal, ke neniu el ili saviĝu. Kaj oni kaptis ilin; kaj Elija forkondukis ilin al la torento Kiŝon kaj buĉis ilin tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Kaj Elija diris al Aĥab: Iru, manĝu kaj trinku, ĉar aŭdiĝas bruo de pluvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Kaj Aĥab iris, por manĝi kaj trinki; sed Elija suriris sur la supron de Karmel kaj kliniĝis al la tero kaj metis sian vizaĝon inter siajn genuojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Kaj li diris al sia junulo: Iru kaj rigardu en la direkto al la maro. Tiu iris kaj rigardis, kaj diris: Estas nenio. Kaj li diris: Iru denove, sep fojojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'En la sepa fojo tiu diris: Jen malgranda nubo, kiel manplato de homo, leviĝas de la maro. Tiam li diris: Iru, diru al Aĥab: Jungu kaj forveturu, por ke vin ne retenu la pluvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Dume de momento al momento la ĉielo mallumiĝis de nuboj kaj vento, kaj fariĝis granda pluvo. Kaj Aĥab ekveturis kaj direktis sin al Jizreel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Kaj la mano de la Eternulo estis super Elija. Li zonis siajn lumbojn kaj kuris antaŭ Aĥab ĝis Jizreel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Aĥab rakontis al Izebel ĉion, kion faris Elija, kaj tion, ke li mortigis ĉiujn profetojn per glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Tiam Izebel sendis senditon al Elija, por diri: La dioj faru al mi tion kaj pli, se mi morgaŭ en ĉi tiu tempo ne faros kun via animo, kiel estas farite kun la animo de ĉiu el ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Li ektimis, kaj leviĝis kaj foriris, por savi sian vivon; kaj li venis en Beer-Ŝeban, kiu troviĝas en Judujo, kaj restigis tie sian junulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Sed li mem iris en la dezerton vojiron de unu tago, kaj venis kaj sidiĝis sub unu genisto kaj petis morton por sia animo, kaj diris: Sufiĉas nun, ho Eternulo! prenu mian animon, ĉar mi ne estas pli bona ol miaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Kaj li kuŝiĝis kaj endormiĝis sub la genisto; kaj jen anĝelo ektuŝis lin, kaj diris al li: Leviĝu, manĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Li ekrigardis, kaj jen ĉe sia kaploko li ekvidis bakitan paneton kaj kruĉon kun akvo. Kaj li manĝis kaj trinkis, kaj denove kuŝiĝis, por dormi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Kaj la anĝelo de la Eternulo revenis duan fojon kaj ektuŝis lin, kaj diris: Leviĝu, manĝu, ĉar vin atendas granda vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Kaj li leviĝis kaj manĝis kaj trinkis; kaj per la forto, kiun li ricevis de tiu manĝado, li iris kvardek tagojn kaj kvardek noktojn ĝis Ĥoreb, la monto de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Kaj tie li eniris en kavernon kaj tradormis tie. Kaj jen aperis al li vorto de la Eternulo, kaj diris al li: Kion vi faras ĉi tie, Elija?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Kaj li respondis: Mi fervoris pro la Eternulo, Dio Cebaot, ĉar la Izraelidoj forlasis Vian interligon, detruis Viajn altarojn, kaj mortigis Viajn profetojn per glavo; mi sola restis, sed oni serĉas mian animon, por forpreni ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Kaj Li diris: Eliru kaj stariĝu sur la monto antaŭ la Eternulo. Kaj jen la Eternulo preteriras, kaj granda kaj forta vento disŝiras montojn kaj disrompas rokojn antaŭ la Eternulo; sed ne en la vento estis la Eternulo. Post la vento estis tertremo, sed ne en la tertremo estis la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Post la tertremo estis fajro, sed ne en la fajro estis la Eternulo. Post la fajro aŭdiĝis blovado de delikata venteto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Kiam Elija tion ekaŭdis, li kovris sian vizaĝon per sia mantelo, kaj eliris kaj stariĝis ĉe la enirejo de la kaverno. Kaj jen aperis al li voĉo, kaj diris: Kion vi faras ĉi tie, Elija?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Kaj li respondis: Mi fervoris pro la Eternulo, Dio Cebaot, ĉar la Izraelidoj forlasis Vian interligon, detruis Viajn altarojn, kaj mortigis Viajn profetojn per glavo; mi sola restis, sed oni serĉas mian animon, por forpreni ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Kaj la Eternulo diris al li: Iru returne vian vojon tra la dezerto al Damasko; kiam vi venos, sanktoleu Ĥazaelon kiel reĝon super Sirio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'kaj Jehun, filon de Nimŝi, sanktoleu kiel reĝon super Izrael; kaj Eliŝan, filon de Ŝafat, el Abel-Meĥola, sanktoleu kiel profeton anstataŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Kaj estos, ke kiu saviĝos de la glavo de Ĥazael, tiun mortigos Jehu; kaj kiu saviĝos de la glavo de Jehu, tiun mortigos Eliŝa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Mi restigos el Izrael sep mil, ĉiujn, kies genuoj ne fleksiĝis antaŭ Baal kaj kies buŝo ne kisis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Kaj li foriris de tie, kaj trovis Eliŝan, filon de Ŝafat, kiu estis pluganta; dek du bovoparoj estis antaŭ li, kaj li mem estis ĉe la dek-dua. Kaj Elija aliris al li kaj ĵetis al li sian mantelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Kaj tiu forlasis la brutojn kaj ekkuris al Elija, kaj diris: Permesu al mi nur kisi mian patron kaj mian patrinon, kaj mi sekvos vin. Kaj li diris al li: Iru kaj revenu, ĉar kion mi faris al vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Kaj tiu foriris de li, kaj prenis paron da bovoj kaj buĉis ilin, kaj sur la jungaĵo de la bovoj li kuiris la viandon kaj donis al la homoj, kaj ili manĝis. Kaj li leviĝis kaj eksekvis Elijan kaj ekservis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Ben-Hadad, reĝo de Sirio, kolektis sian tutan militistaron; kun li estis tridek du reĝoj, kaj ĉevalojn kaj ĉarojn; kaj li iris kaj eksieĝis Samarion kaj militis kontraŭ ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Kaj li sendis senditojn al Aĥab, reĝo de Izrael, en la urbon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'kaj dirigis al li: Tiele diras Ben-Hadad: Via arĝento kaj via oro devas esti miaj, kaj viaj edzinoj kaj viaj plej bonaj filoj devas esti miaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Kaj la reĝo de Izrael respondis kaj diris: Konforme al via diro, mia sinjoro, ho reĝo, al vi apartenas mi, kaj ĉio, kion mi havas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'La senditoj venis denove, kaj diris: Tiele diras Ben-Hadad: Ĉar mi sendis al vi, por diri, ke vian arĝenton kaj vian oron kaj viajn edzinojn kaj viajn filojn vi donu al mi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'tial morgaŭ en ĉi tiu tempo mi sendos miajn servantojn al vi, por ke ili traserĉu vian domon kaj la domojn de viaj servantoj, kaj por ke ĉion, kio estas kara al vi, ili prenu en siajn manojn kaj forportu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Tiam la reĝo de Izrael kunvokis ĉiujn plejaĝulojn de la lando, kaj diris: Sciu kaj rigardu, kian malbonon li intencas; ĉar li sendis al mi, por postuli miajn edzinojn kaj miajn filojn kaj mian arĝenton kaj mian oron, kaj mi ne rifuzis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Kaj ĉiuj plejaĝuloj kaj la tuta popolo diris al li: Ne obeu, kaj ne konsentu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Tiam li diris al la senditoj de Ben-Hadad: Diru al mia sinjoro la reĝo: Ĉion, pri kio vi sendis al via servanto la unuan fojon, mi plenumos; sed ĉi tion mi ne povas fari. Kaj la senditoj iris kaj transdonis la vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Tiam Ben-Hadad sendis al li, kaj dirigis: La dioj faru al mi tion kaj pli, se la polvo de Samario sufiĉos, ke ĉiuj homoj, kiuj min sekvas, povu preni manplenon da ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Sed la reĝo de Izrael respondis kaj diris: Diru: Kiu surmetas la zonon, ne fanfaronu kiel tiu, kiu ĝin demetas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Kiam Ben-Hadad aŭdis tiujn vortojn, dum li kaj la reĝoj estis drinkantaj en la tendoj, li diris al siaj servantoj: Aranĝu vin. Kaj ili aranĝis sin kontraŭ la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Kaj jen unu profeto aliris al Aĥab, reĝo de Izrael, kaj diris: Tiele diras la Eternulo: Ĉu vi vidas tiun tutan grandan amason? jen Mi hodiaŭ transdonos ĝin al vi, por ke vi sciu, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Kaj Aĥab diris: Per kiu? Kaj tiu respondis: Tiele diras la Eternulo: Per la junuloj de la regionestroj. Kaj li diris: Kiu komencos la batalon? Kaj tiu respondis: Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Tiam li kalkulis la junulojn de la regionestroj, kaj montriĝis, ke ilia nombro estas ducent tridek du; post ili li kalkulis la tutan popolon, ĉiujn Izraelidojn, sep mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Ili eliris en tagmezo, kiam Ben-Hadad drinkis ebria en la tendoj, li kaj la reĝoj, la tridek du reĝoj, kiuj helpis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Antaŭe eliris la junuloj de la regionestroj. Ben-Hadad sendis, kaj oni raportis al li, dirante: Viroj eliris el Samario.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Tiam li diris: Se por paco ili eliris, kaptu ilin vivajn; kaj se ili eliris por milito, ankaŭ kaptu ilin vivajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Tiuj eliris el la urbo, la junuloj de la regionestroj, kaj la militistaro post ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'Kaj ili batis ĉiu sian renkontiton; kaj la Sirianoj forkuris, kaj la Izraelidoj ilin postkuris. Kaj Ben-Hadad, reĝo de Sirio, savis sin sur ĉevalo kun la rajdistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Tiam eliris la reĝo de Izrael kaj venkobatis la ĉevalojn kaj la ĉarojn, kaj li faris inter la Sirianoj grandan buĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Kaj aliris la profeto al la reĝo de Izrael, kaj diris al li: Iru, fortigu vin, atendu kaj rigardu, kion vi devas fari; ĉar post paso de unu jaro la reĝo de Sirio iros kontraŭ vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Kaj la servantoj de la reĝo de Sirio diris al li: Ilia Dio estas Dio de montoj, tial ili venkis nin; sed se ni batalos kontraŭ ili sur ebenaĵo, ni certe venkos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Faru jenon: forigu la reĝojn ĉiun de lia loko, kaj starigu anstataŭ ili regionestrojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'kaj kolektu al vi militistaron egalan al tiu, kiu falis ĉe vi, kaj ĉevalojn nombregale al tiuj ĉevaloj kaj ĉarojn nombregale al tiuj ĉaroj; kaj ni batalos kontraŭ ili sur ebenaĵo, kaj tiam ni certe ilin venkos. Kaj li obeis ilian voĉon kaj faris tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Post paso de la jaro Ben-Hadad revuis la Sirianojn, kaj iris en Afekon, por militi kontraŭ la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Kaj la Izraelidoj ankaŭ pretigis sin kaj provizis sin per nutraĵoj kaj iris renkonte al ili. Kaj la Izraelidoj stariĝis tendare kontraŭ ili, kiel du malgrandaj kapraroj; sed la Sirianoj plenigis la tutan landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Tiam aliris homo de Dio, kaj diris al la reĝo de Izrael: Tiele diras la Eternulo: Pro tio, ke la Sirianoj diris, ke la Eternulo estas Dio de montoj kaj Li ne estas Dio de valoj, Mi transdonos tiun tutan grandan amason en vian manon, por ke vi sciu, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'Kaj staris tendare unuj kontraŭ la aliaj dum sep tagoj. En la sepa tago komenciĝis la batalo; kaj la Izraelidoj mortigis el la Sirianoj cent mil piedirantojn en unu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'La ceteraj forkuris en la urbon Afek. Kaj la murego falis sur la restintajn dudek sep mil. Kaj Ben-Hadad kuris kaj venis en la urbon, en plej internan ĉambron de unu domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Kaj liaj servantoj diris al li: Ni aŭdis, ke la reĝoj de la domo de Izrael estas reĝoj kompatemaj; ni metu do sakaĵon sur niajn lumbojn kaj ŝnurojn sur niajn kapojn, kaj ni eliru al la reĝo de Izrael; eble li lasos la vivon al via animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Kaj ili zonis per sakaĵo siajn lumbojn kaj metis ŝnurojn sur siajn kapojn, kaj venis al la reĝo de Izrael, kaj diris: Via servanto Ben-Hadad diras: Mi petas lasi la vivon al mia animo. Kaj tiu diris: Ĉu li vivas ankoraŭ? li estas mia frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'La homoj prenis tion kiel bonan signon, kaj rapidis certiĝi, ĉu tio estas pri li, kaj ili diris: Via frato Ben-Hadad. Kaj li diris: Iru, venigu lin. Tiam eliris al li Ben-Hadad, kaj li sidigis lin sur la ĉaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Kaj tiu diris al li: La urbojn, kiujn mia patro prenis de via patro, mi redonos; kaj vi povas aranĝi al vi stratojn en Damasko, kiel mia patro aranĝis en Samario. (Kaj Aĥab diris:) Kaj mi forliberigos vin kun jena interligo. Kaj li faris kun li interligon kaj forliberigis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Tiam unu viro el la profetidoj diris al sia kamarado laŭ la vorto de la Eternulo: Batu min. Sed tiu homo ne volis lin bati.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Tiam li diris al tiu: Pro tio, ke vi ne obeis la voĉon de la Eternulo, mortigos vin leono, kiam vi foriros de mi. Tiu foriris de li, kaj lin renkontis leono kaj mortigis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Li trovis alian homon, kaj diris: Batu min. Kaj la homo lin batis tiel, ke li vundis lin per la batado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Tiam la profeto iris kaj stariĝis antaŭ la reĝo sur la vojo kaj kovris per kovrotuko siajn okulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Kiam la reĝo iris pretere, li ekkriis al la reĝo, kaj diris: Via servanto eliris en batalon, kaj jen unu homo sin deturnis kaj alkondukis al mi alian homon, kaj diris: Gardu ĉi tiun homon; se li malaperos, tiam via animo anstataŭos lian animon, aŭ vi devos pese pagi kikaron da arĝento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Dum via servanto estis faranta tion kaj alion, tiu malaperis. Kaj la reĝo de Izrael diris al li: Tio estas via verdikto, vi mem decidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Tiam li rapide forprenis la kovrotukon de siaj okuloj, kaj la reĝo rekonis lin, ke li estas el la profetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'Kaj li diris al li: Tiele diras la Eternulo: Pro tio, ke vi forlasis el la mano la homon, kiun Mi kondamnis, via animo anstataŭos lian animon kaj via popolo lian popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Kaj la reĝo de Izrael iris hejmen malĝoja kaj afliktita, kaj venis Samarion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Post tiu historio okazis jeno: Nabot, Jizreelano, havis vinberĝardenon en Jizreel, apud la palaco de Aĥab, reĝo de Samario.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Kaj Aĥab ekparolis al Nabot, dirante: Donu al mi vian vinberĝardenon, por ke ĝi fariĝu por mi legomĝardeno, ĉar ĝi estas proksime de mia domo; kaj mi donos al vi anstataŭ ĝi vinberĝardenon pli bonan ol ĝi; se vi volas, mi donos al vi per arĝento ĝian prezon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Sed Nabot diris al Aĥab: La Eternulo gardu min, ke mi ne fordonu al vi la heredaĵon de miaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Tiam Aĥab revenis hejmen malĝoja kaj afliktita pro la vortoj, kiujn diris al li Nabot, la Jizreelano, dirante: Mi ne donos al vi la heredaĵon de miaj patroj. Kaj li kuŝiĝis sur sia lito kaj forturnis sian vizaĝon kaj ne manĝis panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Kaj venis al li lia edzino Izebel, kaj diris al li: Kial via spirito estas tiel malĝoja, ke vi ne manĝas panon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Li respondis al ŝi: Kiam mi parolis al Nabot, la Jizreelano, kaj diris al li: Donu al mi vian vinberĝardenon pro mono, aŭ, se vi volas, mi donos al vi alian vinberĝardenon anstataŭ ĝi, li diris: Mi ne donos al vi mian vinberĝardenon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Tiam diris al li lia edzino Izebel: Nun vi montru vian reĝecon super Izrael; leviĝu, manĝu panon, kaj estu bonhumora: mi donos al vi la vinberĝardenon de Nabot, la Jizreelano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Kaj ŝi skribis leterojn en la nomo de Aĥab kaj sigelis per lia sigelilo, kaj ŝi sendis la leterojn al la plejaĝuloj kaj al la eminentuloj, kiuj loĝis kun Nabot en lia urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'Kaj ŝi skribis en la leteroj jenon: Proklamu faston kaj sidigu Naboton sur la ĉefa loko inter la popolo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'kaj sidigu apud li du homojn malvirtajn, kaj ili atestu kontraŭ li kaj diru: Vi blasfemis kontraŭ Dio kaj la reĝo; kaj oni elkonduku lin, kaj priĵetu lin per ŝtonoj, ke li mortu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Kaj la viroj de lia urbo, la plejaĝuloj kaj la eminentuloj, kiuj loĝis en lia urbo, faris kiel ordonis al ili Izebel, kiel estis skribite en la leteroj, kiujn ŝi sendis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Ili proklamis faston kaj sidigis Naboton sur la ĉefa loko inter la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Kaj venis du homoj malvirtaj kaj sidiĝis apud li, kaj la malvirtaj homoj atestis kontraŭ Nabot antaŭ la popolo, dirante: Nabot blasfemis kontraŭ Dio kaj la reĝo. Kaj oni elkondukis lin ekster la urbon kaj priĵetis lin per ŝtonoj, kaj li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Kaj oni sendis al Izebel, por diri: Nabot estas priĵetita per ŝtonoj kaj mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Kiam Izebel aŭdis, ke Nabot estas priĵetita per ŝtonoj kaj mortis, Izebel diris al Aĥab: Leviĝu, ekposedu la vinberĝardenon de Nabot, la Jizreelano, kiun li ne volis doni al vi pro mono; ĉar Nabot jam ne vivas; li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Kiam Aĥab aŭdis, ke Nabot mortis, Aĥab leviĝis, por iri en la vinberĝardenon de Nabot, la Jizreelano, por ekposedi ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Tiam aperis la vorto de la Eternulo al Elija, la Teŝebano, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Leviĝu, iru renkonte al Aĥab, reĝo de Izrael, kiu estas en Samario; jen li nun estas en la vinberĝardeno de Nabot, kien li iris, por ekposedi ĝin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'kaj diru al li jene: Tiele diras la Eternulo: Vi mortigis, kaj vi ankoraŭ prenas en posedon! Kaj diru al li: Tiele diras la Eternulo: Sur la loko, kie la hundoj lekis la sangon de Nabot, la hundoj lekos ankaŭ vian sangon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Kaj Aĥab diris al Elija: Vi trovis min, ho mia malamiko! Kaj tiu diris: Mi trovis, ĉar vi vin vendis, por fari malbonon antaŭ la okuloj de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Jen Mi venigos sur vin malbonon, kaj forbalaos la postesignojn post vi, kaj Mi ekstermos ĉe Aĥab ĉiun virseksulon, malliberulon kaj liberulon en Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'Kaj Mi agos kun via domo, kiel kun la domo de Jerobeam, filo de Nebat, kaj kiel kun la domo de Baaŝa, filo de Aĥija, pro la incito, per kiu vi Min incitis kaj pekigis Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Kaj ankaŭ pri Izebel parolis la Eternulo, dirante: La hundoj formanĝos Izebelon apud la murego de Jizreel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Kiu mortos ĉe Aĥab en la urbo, tiun manĝos la hundoj; kaj kiu mortos sur la kampo, tiun manĝos la birdoj de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, '(Estis neniu tia, kiel Aĥab, kiu fordonis sin al farado de malbono antaŭ la okuloj de la Eternulo, al kio instigadis lin lia edzino Izebel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Li fariĝis tre abomeninda, sekvante la idolojn, konforme al ĉio, kion faradis la Amoridoj, kiujn la Eternulo forpelis de antaŭ la Izraelidoj.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Kiam Aĥab aŭdis tiujn vortojn, li disŝiris siajn vestojn kaj metis sakaĵon sur sian korpon kaj fastis kaj dormis en la sakaĵo kaj iradis malĝoje.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Tiam aperis vorto de la Eternulo al Elija, la Teŝebano, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'Ĉu vi vidas, kiel Aĥab humiliĝis antaŭ Mi? Pro tio, ke li humiliĝis antaŭ Mi, Mi ne venigos la malbonon dum lia vivo; dum la vivo de lia filo Mi venigos la malbonon sur lian domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Pasis tri jaroj, kaj estis nenia milito inter Sirio kaj Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'En la tria jaro Jehoŝafat, reĝo de Judujo, venis al la reĝo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'La reĝo de Izrael diris al siaj servantoj: Ĉu vi scias, ke Ramot en Gilead apartenas al ni? kaj ni ne zorgas preni ĝin el la manoj de la reĝo de Sirio!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Kaj li diris al Jehoŝafat: Ĉu vi iros kun mi milite kontraŭ Ramoton en Gilead? Kaj Jehoŝafat diris al la reĝo de Izrael: Mi estas kiel vi, mia popolo kiel via popolo, miaj ĉevaloj kiel viaj ĉevaloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Kaj Jehoŝafat diris al la reĝo de Izrael: Demandu hodiaŭ la vorton de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Tiam la reĝo de Izrael kunvenigis la profetojn, ĉirkaŭe kvarcent homojn, kaj diris al ili: Ĉu mi iru milite kontraŭ Ramoton en Gilead, aŭ mi tion ne faru? Kaj ili respondis: Iru, la Sinjoro ĝin transdonos en la manon de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Sed Jehoŝafat diris: Ĉu ne troviĝas ĉi tie ankoraŭ iu profeto de la Eternulo, kiun ni povus demandi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Kaj la reĝo de Izrael diris al Jehoŝafat: Ekzistas ankoraŭ unu homo, per kiu ni povas demandi la Eternulon, sed mi lin malamas, ĉar li profetas pri mi ne bonon, sed nur malbonon; tio estas Miĥaja, filo de Jimla. Sed Jehoŝafat diris: La reĝo ne parolu tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Tiam la reĝo de Izrael alvokis unu korteganon, kaj diris: Venigu rapide Miĥajan, filon de Jimla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'La reĝo de Izrael, kaj Jehoŝafat, reĝo de Judujo, sidis ĉiu sur sia seĝo, vestitaj per siaj vestoj, sur placo antaŭ la pordego de Samario, kaj ĉiuj profetoj profetadis antaŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Kaj Cidkija, filo de Kenaana, faris al si ferajn kornojn, kaj diris: Tiele diras la Eternulo: Per ĉi tio vi kornobatos la Sirianojn, ĝis vi ilin tute ekstermos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Kaj ĉiuj profetoj profetis tiel same, dirante: Iru kontraŭ Ramoton en Gilead kaj sukcesu, kaj la Eternulo ĝin transdonos en la manon de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'La sendito, kiu iris por voki Miĥajan, diris al li: Jen la vortoj de la profetoj unuanime antaŭdiras bonon al la reĝo; estu do via vorto simila al la vorto de ĉiu el ili, kaj antaŭdiru bonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Sed Miĥaja diris: Kiel vivas la Eternulo: kion diros la Eternulo al mi, tion mi diros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Kaj kiam li venis al la reĝo, la reĝo diris al li: Miĥaja! ĉu ni iru milite kontraŭ Ramoton en Gilead, aŭ ni tion ne faru? Kaj tiu respondis al li: Iru kaj sukcesu, kaj la Eternulo ĝin transdonos en la manon de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Kaj la reĝo diris al li: Multfoje mi vin ĵurligas, ke vi parolu al mi nur la veron en la nomo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Kaj tiu diris: Mi vidis ĉiujn Izraelidojn disĵetitaj sur la montoj, kiel ŝafoj, kiuj ne havas paŝtanton; kaj la Eternulo diris: Ili ne havas estrojn, ili reiru pace ĉiu al sia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Kaj la reĝo de Izrael diris al Jehoŝafat: Ĉu mi ne diris al vi, ke li profetos pri mi ne bonon, sed nur malbonon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Sed Miĥaja diris: Tial aŭskultu la vorton de la Eternulo: mi vidis la Eternulon, sidantan sur Sia trono, kaj la tuta armeo de la ĉielo staris antaŭ Li dekstre kaj maldekstre de Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'Kaj la Eternulo diris: Kiu allogos Aĥabon, ke li iru kaj falu en Ramot en Gilead? Kaj unu parolis tiel, alia parolis alie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Tiam eliris spirito kaj stariĝis antaŭ la Eternulo, kaj diris: Mi lin allogos. Kaj la Eternulo diris al li: Per kio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Kaj tiu diris: Mi eliros kaj faros min spirito mensoga en la buŝo de ĉiuj liaj profetoj. Tiam Li diris: Vi allogos kaj havos sukceson; eliru kaj agu tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Kaj nun jen la Eternulo metis mensogan spiriton en la buŝon de ĉiuj tiuj viaj profetoj, kaj la Eternulo decidis por vi malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Tiam aliris Cidkija, filo de Kenaana, kaj frapis Miĥajan sur la vango, kaj diris: Per kiu vojo la spirito de la Eternulo transiris de mi, por paroli per vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Kaj Miĥaja respondis: Jen vi tion vidos en tiu tago, kiam vi eniros en internan ĉambron, por vin kaŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Tiam la reĝo de Izrael diris: Prenu Miĥajan, kaj konduku lin al la urbestro Amon kaj al la reĝido Joaŝ;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'kaj diru: Tiele diras la reĝo: Metu ĉi tiun en malliberejon, kaj nutru lin per mizera pano kaj mizera akvo, ĝis mi revenos en paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Kaj Miĥaja diris: Se vi revenos en paco, en tiu okazo ne parolis per mi la Eternulo. Kaj li diris: Aŭskultu, ĉiuj popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Kaj la reĝo de Izrael, kaj Jehoŝafat, reĝo de Judujo, iris al Ramot en Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Kaj la reĝo de Izrael diris al Jehoŝafat: Mi alivestos min kaj iros en la batalon; sed vi surmetu viajn vestojn. Kaj la reĝo de Izrael alivestis sin kaj iris en la batalon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'La reĝo de Sirio ordonis al la tridek du ĉarestroj, kiuj estis ĉe li, dirante: Batalu ne kontraŭ iu malgranda aŭ granda, sed sole nur kontraŭ la reĝo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Kiam la ĉarestroj ekvidis Jehoŝafaton, ili pensis, ke tio certe estas la reĝo de Izrael, kaj ili turnis sin kontraŭ lin, por batali; kaj Jehoŝafat ekkriis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Kiam la ĉarestroj vidis, ke tio ne estas la reĝo de Izrael, ili forturnis sin de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Kaj unu viro sen ia celo streĉis la pafarkon, kaj pafe trafis la reĝon de Izrael inter la artikoj de la kiraso. Tiam ĉi tiu diris al sia veturiganto: Turnu vian manon, kaj elveturigu min el la militistaro, ĉar mi estas vundita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Sed la batalo plifortiĝis en tiu tago, kaj la reĝo staris sur la ĉaro kontraŭ la Sirianoj, kaj li mortis vespere. Kaj la sango el la vundo fluis en la mezon de la ĉaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Post la subiro de la suno tra la militistaro ekkuris voko: Ĉiu en sian urbon, ĉiu en sian landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'La reĝo mortis, kaj oni venigis lin en Samarion, kaj oni enterigis la reĝon en Samario.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'Kaj oni lavis la ĉaron ĉe la lageto de Samario, kaj la hundoj lekis lian sangon kaj malĉastistinoj lavis, konforme al la vorto de la Eternulo, kiun Li diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'La cetera historio de Aĥab, kaj ĉio, kion li faris, kaj la ebura domo, kiun li konstruis, kaj ĉiuj urboj, kiujn li konstruis, estas priskribitaj en la libro de kroniko de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Kiam Aĥab ekdormis kun siaj patroj, anstataŭ li ekreĝis lia filo Aĥazja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Jehoŝafat, filo de Asa, ekreĝis super Judujo en la kvara jaro de Aĥab, reĝo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Jehoŝafat havis la aĝon de tridek kvin jaroj, kiam li fariĝis reĝo, kaj dudek kvin jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Azuba, filino de Ŝilĥi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Li iradis tute laŭ la vojo de sia patro Asa; li ne deturniĝis de ĝi, agante tiel, kiel plaĉas al la Eternulo. Nur la altaĵoj ne estis forigitaj; la popolo ankoraŭ oferportadis kaj incensadis sur la altaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Kaj Jehoŝafat havis pacon kun la reĝo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'La cetera historio de Jehoŝafat, kaj liaj heroaĵoj, kiujn li faris, kaj kiel li militis, estas priskribitaj en la libro de kroniko de la reĝoj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'La lastan kvanton da malĉastistoj, kiuj restis ankoraŭ dum la vivo de lia patro Asa, li ekstermis el la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Tiam ne estis reĝo en Edomujo; estis anstataŭanto de reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Jehoŝafat faris Tarŝiŝajn ŝipojn, kiuj devis iri Ofiron, por preni oron; sed ili ne iris, ĉar la ŝipoj rompiĝis en Ecjon-Geber.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Tiam Aĥazja, filo de Aĥab, diris al Jehoŝafat: Permesu, ke miaj servantoj iru kun viaj servantoj sur la ŝipoj; sed Jehoŝafat ne konsentis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Jehoŝafat ekdormis kun siaj patroj, kaj oni enterigis lin kun liaj patroj en la urbo de lia patro David. Kaj anstataŭ li ekreĝis lia filo Jehoram.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Aĥazja, filo de Aĥab, fariĝis reĝo super Izrael en Samario en la dek-sepa jaro de Jehoŝafat, reĝo de Judujo, kaj li reĝis super Izrael du jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Li faradis malbonon antaŭ la okuloj de la Eternulo, kaj iradis laŭ la vojo de sia patro kaj de sia patrino, kaj laŭ la vojo de Jerobeam, filo de Nebat, kiu pekigis Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Kaj li servadis al Baal kaj adorkliniĝadis al li, kaj incitadis la Eternulon, Dion de Izrael, tute tiel, kiel faradis lia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Moab defalis de Izrael post la morto de Aĥab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Kaj Aĥazja elfalis tra la krado de sia supra ĉambro en Samario, kaj malsaniĝis. Kaj li sendis senditojn, kaj diris al ili: Iru, demandu Baal- Zebubon, la dion de Ekron, ĉu mi resaniĝos de ĉi tiu malsano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Sed anĝelo de la Eternulo diris al Elija, la Teŝebano: Leviĝu, iru renkonte al la senditoj de la reĝo de Samario, kaj diru al ili: Ĉu ne ekzistas Dio en Izrael, ke vi iras demandi Baal-Zebubon, la dion de Ekron?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Pro tio tiele diras la Eternulo: De la lito, sur kiu vi kuŝiĝis, vi ne deiros, sed vi mortos. Kaj Elija foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Kiam la senditoj revenis al li, li diris al ili: Kial vi revenis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Kaj ili respondis al li: Viro venis renkonte al ni, kaj diris al ni: Iru, revenu al la reĝo, kiu sendis vin, kaj diru al li: Tiele diras la Eternulo: Ĉu ne ekzistas Dio en Izrael, ke vi sendas demandi Baal-Zebubon, la dion de Ekron? pro tio, de la lito, sur kiu vi kuŝiĝis, vi ne deiros, sed vi mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Kaj li diris al ili: Kia estas la aspekto de la viro, kiu venis renkonte al vi kaj diris al vi tiujn vortojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'Ili respondis al li: Li estas homo kovrita de haroj, kaj ledan zonon li havas ĉirkaŭ siaj lumboj. Tiam li diris: Tio estas Elija, la Teŝebano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Kaj li sendis al li kvindekestron kun lia kvindeko. Kaj tiu iris al li kaj trovis lin sidanta sur la supro de monto, kaj diris al li: Ho homo de Dio! la reĝo diris, ke vi malsupreniru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Kaj Elija respondis kaj diris al la kvindekestro: Se mi estas homo de Dio, tiam venu fajro el la ĉielo kaj ekstermu vin kaj vian kvindekon. Kaj venis fajro el la ĉielo kaj ekstermis lin kaj lian kvindekon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Kaj li denove sendis al li alian kvindekestron kun lia kvindeko. Kaj tiu ekparolis kaj diris al li: Ho homo de Dio! tiele diras la reĝo: Malsupreniru rapide.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Kaj Elija respondis kaj diris al ili: Se mi estas homo de Dio, tiam venu fajro el la ĉielo kaj ekstermu vin kaj vian kvindekon. Kaj venis fajro de Dio el la ĉielo kaj ekstermis lin kaj lian kvindekon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Kaj li denove sendis triafoje kvindekestron kun lia kvindeko. Kaj la tria kvindekestro iris, kaj venis kaj fleksis siajn genuojn antaŭ Elija, kaj ekpetegis lin kaj diris al li: Ho homo de Dio! mia animo kaj la animo de ĉi tiuj kvindek viaj servantoj havu do ian valoron antaŭ viaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Jen venis fajro el la ĉielo kaj ekstermis la du antaŭajn kvindekestrojn kaj iliajn kvindekojn; nun mia animo havu ian valoron antaŭ viaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Tiam anĝelo de la Eternulo diris al Elija: Iru kun li, ne timu lin. Kaj li leviĝis, kaj iris kun li al la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Kaj li ekparolis al li: Tiele diras la Eternulo: Pro tio, ke vi sendis senditojn, por demandi Baal-Zebubon, la dion de Ekron, kvazaŭ ne ekzistus Dio en Izrael, por demandi Lian vorton, tial de la lito, sur kiu vi kuŝiĝis, vi ne deiros, sed vi mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Kaj li mortis, konforme al la vorto de la Eternulo, kiun eldiris Elija. Kaj anstataŭ li ekreĝis Jehoram, en la dua jaro de Jehoram, filo de Jehoŝafat, reĝo de Judujo; ĉar li ne havis filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'La cetera historio de Aĥazja, kion li faris, estas priskribita en la libro de kroniko de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Kiam la Eternulo volis levi Elijan en ventego en la ĉielon, Elija estis iranta kun Eliŝa el Gilgal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Kaj Elija diris al Eliŝa: Restu do ĉi tie, ĉar la Eternulo sendas min al Bet-El. Sed Eliŝa diris: Mi ĵuras per la Eternulo kaj per via animo, ke mi vin ne forlasos. Kaj ili ekiris al Bet-El.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Kaj eliris la profetidoj, kiuj estis en Bet-El, al Eliŝa, kaj diris al li: Ĉu vi scias, ke hodiaŭ la Eternulo forprenos vian sinjoron de super via kapo? Li diris: Mi ankaŭ scias, silentu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Kaj Elija diris al li: Eliŝa, restu do ĉi tie, ĉar la Eternulo sendas min al Jeriĥo. Sed li diris: Mi ĵuras per la Eternulo kaj per via animo, ke mi ne forlasos vin. Kaj ili venis en Jeriĥon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Kaj la profetidoj, kiuj estis en Jeriĥo, aliris al Eliŝa, kaj diris al li: Ĉu vi scias, ke hodiaŭ la Eternulo forprenos vian sinjoron de super via kapo? Li diris: Mi ankaŭ scias, silentu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Kaj Elija diris al li: Restu do ĉi tie, ĉar la Eternulo sendas min al Jordan. Sed li diris: Mi ĵuras per la Eternulo kaj per via animo, ke mi vin ne forlasos. Kaj ili ambaŭ iris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Kaj kvindek homoj el la profetidoj iris kaj stariĝis malproksime kontraŭ ili; sed ili ambaŭ staris ĉe Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Tiam Elija prenis sian mantelon kaj kunvolvis ĝin, kaj frapis la akvon, kaj ĝi dividiĝis duflanken, kaj ili ambaŭ trapasis sur sekaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Kiam ili trapasis, Elija diris al Eliŝa: Petu, kion mi faru al vi, antaŭ ol mi estos prenita for de vi. Kaj Eliŝa diris: Duobla parto de via spirito estu do sur mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Kaj tiu diris: Vi petas ion malfacilan; se vi vidos min, kiam mi estos prenata for de vi, estos al vi tiel; kaj se ne, tiam ne estos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Dum ili estis irantaj kaj parolantaj, subite aperis fajra ĉaro kaj fajraj ĉevaloj kaj disigis ilin; kaj Elija en ventego suprenflugis en la ĉielon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Eliŝa vidis, kaj ekkriis: Mia patro, mia patro, ĉaro de Izrael kaj liaj rajdistoj! Kaj li ne plu lin vidis. Kaj li kaptis siajn vestojn kaj disŝiris ilin en du pecojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Kaj li levis la mantelon de Elija, kiu defalis de li, kaj reiris kaj stariĝis sur la bordo de Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Kaj li prenis la mantelon de Elija, kiu defalis de li, kaj frapis la akvon, kaj diris: Kie estas la Eternulo, Dio de Elija? Kaj li frapis la akvon, kaj ĝi dividiĝis duflanken, kaj Eliŝa trapasis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Kiam la profetidoj, kiuj estis kontraŭe en Jeriĥo, lin ekvidis, ili diris: La spirito de Elija transiris sur Eliŝan. Kaj ili iris al li renkonte kaj adorkliniĝis antaŭ li ĝis la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'Kaj ili diris al li: Jen kun viaj servantoj troviĝas kvindek homoj, viroj fortaj; ili iru kaj serĉu vian sinjoron; eble la spirito de la Eternulo forportis lin kaj ĵetis lin sur unu el la montoj aŭ en unu el la valoj. Sed li diris: Ne sendu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Tamen ili insistis tiel longe, ĝis li hontis, kaj li diris: Sendu. Kaj ili sendis kvindek homojn kaj serĉis dum tri tagoj, sed ne trovis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Kaj ili revenis al li, dum li estis en Jeriĥo. Kaj li diris al ili: Mi diris ja al vi, ke vi ne iru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Kaj la loĝantoj de tiu urbo diris al Eliŝa: Jen do la loĝado en ĉi tiu urbo estas bona, kiel nia sinjoro vidas; sed la akvo estas malbona, kaj la tero estas senfrukta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Tiam li diris: Alportu al mi novan pladon, kaj metu tien salon. Kaj oni alportis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Kaj li eliris al la fonto de la akvo kaj ĵetis tien salon, kaj diris: Tiele diras la Eternulo: Mi resanigas ĉi tiun akvon, ĝi ne kaŭzos plu morton nek senfruktecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Kaj la akvo fariĝis sana ĝis la nuna tempo, konforme al la vorto de Eliŝa, kiun li diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Kaj li foriris de tie en Bet-Elon. Dum li estis iranta sur la vojo, malgrandaj knaboj eliris el la urbo kaj mokis lin, kaj parolis al li: Iru, kalvulo, iru, kalvulo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Li returnis sin kaj ekvidis ilin, kaj malbenis ilin en la nomo de la Eternulo. Kaj eliris du ursinoj el la arbaro kaj disŝiris el ili kvardek du infanojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Kaj li iris de tie al la monto Karmel, kaj de tie li revenis en Samarion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Jehoram, filo de Aĥab, fariĝis reĝo super Izrael en Samario en la dek- oka jaro de Jehoŝafat, reĝo de Judujo, kaj li reĝis dek du jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Li faradis malbonon antaŭ la okuloj de la Eternulo, tamen ne tiel, kiel lia patro kaj lia patrino; li forigis la statuon de Baal, kiun faris lia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Tamen li restis aliĝinta al la pekoj de Jerobeam, filo de Nebat, per kiuj li pekigis Izraelon; li ne forlasis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Meŝa, reĝo de Moab, estis paŝtisto, kaj li sendadis al la reĝo de Izrael po cent mil ŝafidoj kaj cent mil virŝafoj kun ilia lano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Sed kiam Aĥab mortis, la reĝo de Moab defalis de la reĝo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Tiam la reĝo Jehoram eliris el Samario kaj revuis la tutan Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Kaj li iris kaj sendis al Jehoŝafat, reĝo de Judujo, por diri: La reĝo de Moab defalis de mi; ĉu vi iros kun mi milite kontraŭ Moabon? Tiu diris: Mi iros; mi estas kiel vi, mia popolo kiel via popolo, miaj ĉevaloj kiel viaj ĉevaloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Kaj li diris: Kiun vojon ni iros? Kaj la alia diris: La vojon de la Edoma dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Tiam ekiris la reĝo de Izrael kaj la reĝo de Judujo kaj la reĝo de Edom; sed kiam ili trairis vojon de sep tagoj, ne estis akvo por la militistaro, nek por la brutoj, kiuj sekvis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Kaj la reĝo de Izrael diris: Ho ve! la Eternulo vokis ĉi tiujn tri reĝojn, por transdoni ilin en la manojn de Moab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Sed Jehoŝafat diris: Ĉu ne troviĝas ĉi tie profeto de la Eternulo, por ke ni demandu per li la Eternulon? Tiam respondis unu el la servantoj de la reĝo de Izrael, kaj diris: Estas ĉi tie Eliŝa, filo de Ŝafat, kiu verŝadis akvon sur la manojn de Elija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Kaj Jehoŝafat diris: Li posedas la vorton de la Eternulo. Kaj iris al li la reĝo de Izrael kaj Jehoŝafat kaj la reĝo de Edom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Kaj Eliŝa diris al la reĝo de Izrael: Kio komuna estas inter mi kaj vi? iru al la profetoj de via patro kaj al la profetoj de via patrino. Sed la reĝo de Izrael diris al li: Ne, ĉar la Eternulo vokis ĉi tiujn tri reĝojn, por transdoni ilin en la manojn de Moab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Tiam Eliŝa diris: Mi ĵuras per la Eternulo Cebaot, antaŭ kiu mi staras, ke se mi ne estimus Jehoŝafaton, reĝon de Judujo, mi ne ekrigardus vin kaj ne vidus vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Nun alkonduku al mi muzikiston. Kaj kiam la muzikisto ludis, estis sur li la mano de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'Kaj li diris: Tiele diras la Eternulo: Faru en ĉi tiu valo multajn fosojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Ĉar tiele diras la Eternulo: Vi ne vidos venton kaj vi ne vidos pluvon, kaj tamen ĉi tiu valo pleniĝos de akvo, kaj vi trinkos, kaj ankaŭ viaj apartenantoj kaj viaj brutoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Sed ĉi tio ne sufiĉos al la Eternulo; Li transdonos ankaŭ Moabon en viajn manojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'Kaj vi venkobatos ĉiujn urbojn fortikigitajn kaj ĉiujn urbojn distingindajn, kaj ĉiujn bonajn arbojn vi faligos, kaj ĉiujn fontojn de akvo vi ŝtopos, kaj ĉiujn bonajn kampojn vi malbonigos per ŝtonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Kaj jen matene, kiam oni alportas farunoferojn, subite venis akvo per la vojo de Edom, kaj la tero pleniĝis de akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Ĉiuj Moabidoj aŭdis, ke la reĝoj venis, por militi kontraŭ ili, kaj ili kunvokis ĉiujn, kiuj povis komenci porti zonon, kaj pli aĝajn, kaj stariĝis ĉe la limo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Kiam ili leviĝis frue matene kaj la suno ekbrilis super la akvo, al la Moabidoj de malproksime ŝajnis, ke la akvo estas ruĝa kiel sango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'Kaj ili diris: Tio estas sango! la reĝoj batalis inter si kaj ekstermis unu alian; nun, Moab, iru preni rabakiron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Ili venis al la tendaro de Izrael. Tiam la Izraelidoj leviĝis kaj frapis la Moabidojn, kaj ĉi tiuj forkuris de ili. Sed ili venis kaj batis la Moabidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Kaj la urbojn ili ruinigis, kaj sur ĉiun bonan kampon ĉiu ĵetis ŝtonon tiel, ke ili plenigis ilin, kaj ĉiujn fontojn de akvo ili ŝtopis, kaj ĉiun bonan arbon ili faligis, ĝis restis nur ŝtonoj en Kir-Ĥareset. Kaj ĉirkaŭis ĝin la ŝtonĵetistoj kaj ĝisfine frapis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Kiam la reĝo de Moab vidis, ke la batalo lin venkas, li prenis kun si sepcent virojn kun eltiritaj glavoj, por trabati sin al la reĝo de Edom; sed ili ne povis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Tiam li prenis sian filon unuenaskitan, kiu estis reĝonta anstataŭ li, kaj oferportis lin kiel bruloferon sur la murego. Tiam la Izraelidoj forte indignis, kaj ili foriris de li kaj reiris en sian landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Unu virino el la edzinoj de la profetidoj plendis al Eliŝa, dirante: Via servanto, mia edzo, mortis; kaj vi scias, ke via servanto estis timanta la Eternulon; nun la pruntedoninto venis, por preni miajn du infanojn kiel sklavojn por si.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Kaj Eliŝa diris al ŝi: Kion mi povas fari por vi? diru al mi, kion vi havas en la domo? Ŝi respondis: Via servantino havas en la domo nenion, krom kruĉeto kun oleo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Tiam li diris: Iru, petu al vi vazojn ekstere, de ĉiuj viaj najbaroj, vazojn malplenajn, kolektu ne malmulte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Kaj venu kaj ŝlosu la pordon post vi kaj post viaj filoj, kaj enverŝu en ĉiujn tiujn vazojn, kaj, pleniginte, forstarigu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Kaj ŝi iris de li kaj ŝlosis la pordon post si kaj post siaj filoj. Ili alportadis al ŝi, kaj ŝi verŝadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Kiam la vazoj estis plenaj, ŝi diris al sia filo: Alportu al mi ankoraŭ vazon. Sed li diris al ŝi: Ne estas plu vazo. Tiam la oleo haltis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Kaj ŝi venis kaj rakontis al la homo de Dio. Kaj li diris al ŝi: Iru, vendu la oleon kaj pagu vian ŝuldon, kaj vi kun viaj filoj vivos per la restaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Unu tagon Eliŝa venis Ŝunemon; tie estis unu riĉa virino, kiu retenis lin, ke li manĝu ĉe ŝi. Kaj ĉiufoje, kiam li venis, li iradis tien, por manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Kaj ŝi diris al sia edzo: Jen mi scias, ke li estas sankta homo de Dio, li, kiu ĉiam preteriras antaŭ ni;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'ni faru malgrandan supran ĉambreton, kaj ni metu tien por li liton kaj tablon kaj seĝon kaj lumingon, kaj ĉiufoje, kiam li venos al ni, li tien iru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Unu tagon li venis tien, kaj li iris en la supran ĉambreton kaj kuŝiĝis tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Kaj li diris al sia junulo Geĥazi: Alvoku tiun Ŝunemaninon. Kaj tiu vokis ŝin, kaj ŝi aperis antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Kaj li diris al li: Diru al ŝi: Jen vi prizorgis por ni ĉion ĉi tion; kion mi povas fari por vi? ĉu vi bezonas ion diri al la reĝo aŭ al la militestro? Sed ŝi respondis: Mi loĝas ja meze de mia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Kaj li diris: Kion do ni povas fari por ŝi? Tiam Geĥazi diris: Ho, ŝi ne havas filon, kaj ŝia edzo estas maljuna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Kaj li diris: Alvoku ŝin. Kaj li vokis ŝin, kaj ŝi stariĝis ĉe la pordo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'Kaj li diris: Post unu jaro en ĉi tiu tempo vi enbrakigos filon. Kaj ŝi diris: Ne, mia sinjoro, homo de Dio, ne mensogu al via servantino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Sed la virino gravediĝis, kaj naskis filon en la sekvanta jaro en la sama tempo, kiel diris al ŝi Eliŝa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'La infano fariĝis granda. Unu tagon li iris al sia patro, al la rikoltantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Kaj li diris al sia patro: Mia kapo, mia kapo! Kaj tiu diris al sia junulo: Portu lin al lia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Kaj li prenis lin kaj alportis lin al lia patrino; li sidis sur ŝiaj genuoj ĝis tagmezo, kaj mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Tiam ŝi iris kaj metis lin sur la liton de la homo de Dio kaj ŝlosis post li kaj eliris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Kaj ŝi vokis sian edzon, kaj diris: Sendu al mi unu el la junuloj kaj unu el la azeninoj, mi kuros al la homo de Dio kaj revenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Li diris: Por kio vi iras al li? hodiaŭ estas nek monatkomenco, nek sabato. Sed ŝi diris: Estu trankvila.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Kaj ŝi selis la azeninon, kaj diris al sia junulo: Konduku kaj iru, ne retenu min en la rajdado, ĝis mi diros al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Kaj ŝi iris kaj venis al la homo de Dio, sur la monton Karmel. Kiam la homo de Dio ŝin ekvidis de malproksime, li diris al sia junulo Geĥazi: Jen estas tiu Ŝunemanino;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'kuru do al ŝi renkonte, kaj diru al ŝi: Kiel vi fartas? kiel fartas via edzo? kiel fartas la infano? Ŝi diris: Ni fartas bone.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Kaj ŝi aliris al la homo de Dio sur la monton kaj ekkaptis liajn piedojn. Geĥazi aliris, por forpuŝi ŝin; sed la homo de Dio diris: Lasu ŝin, ĉar ŝia animo estas afliktita; kaj la Eternulo kaŝis antaŭ mi kaj ne sciigis al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Kaj ŝi diris: Ĉu mi petis filon de mia sinjoro? ĉu mi ne diris: Ne trompu min?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Kaj li diris al Geĥazi: Zonu viajn lumbojn, kaj prenu en vian manon mian bastonon kaj iru. Se vi renkontos iun, ne salutu lin; kaj se iu vin salutos, ne respondu al li. Kaj metu mian bastonon sur la vizaĝon de la knabo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Sed la patrino de la knabo diris: Mi ĵuras per la Eternulo kaj per via animo, ke mi vin ne forlasos. Kaj li leviĝis, kaj iris post ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Geĥazi iris antaŭ ili, kaj li metis la bastonon sur la vizaĝon de la knabo; sed ne aperis voĉo nek sento. Kaj li revenis renkonte al li, kaj sciigis al li, dirante: La knabo ne vekiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Tiam Eliŝa eniris en la domon, kaj vidis, ke la mortinta infano estas kuŝigita sur lia lito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Kaj li eniris kaj ŝlosis la pordon post ili ambaŭ, kaj ekpreĝis al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Kaj li iris kaj kuŝiĝis sur la infano, kaj almetis sian buŝon al lia buŝo kaj siajn okulojn al liaj okuloj kaj siajn manojn al liaj manoj, kaj etendis sin sur li. Kaj la korpo de la infano varmiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Kaj li releviĝis kaj iris en la domo tien kaj reen, kaj venis kaj etendis sin sur la infano. Kaj la knabo ternis sep fojojn, kaj la knabo malfermis siajn okulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Tiam li vokis Geĥazin, kaj diris: Alvoku tiun Ŝunemaninon. Kaj li vokis ŝin, kaj ŝi venis al li, kaj li diris: Prenu vian filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Kaj ŝi venis kaj ĵetis sin al liaj piedoj kaj adorkliniĝis ĝis la tero; kaj ŝi prenis sian filon kaj eliris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Eliŝa reiris Gilgalon. Estis malsato en la lando; kaj la profetidoj sidis antaŭ li. Kaj li diris al sia junulo: Starigu la grandan kaldronon kaj kuiru supon por la profetidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Sed unu el ili eliris sur la kampon, por kolekti verdaĵon; kaj li trovis sovaĝan volvokreskaĵon kaj kolektis de ĝi kolocintojn, plenan sian veston. Kaj li venis kaj tranĉis ilin en la kaldronon kun la supo, ĉar ili ne sciis, kio tio estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Kaj ili elverŝis al la homoj, por manĝi. Sed kiam tiuj ekmanĝis el la supo, ili ekkriis kaj diris: Morto estas en la kaldrono, ho homo de Dio! Kaj ili ne povis manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Tiam li diris: Alportu farunon. Kaj li enŝutis en la kaldronon, kaj diris: Verŝu al la homoj, ke ili manĝu. Kaj jam estis nenio malbona en la kaldrono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Venis homo el Baal-Ŝaliŝa, kaj alportis al la homo de Dio unuaaĵon de pano: dudek hordeajn panojn kaj freŝajn grajnojn en sia saketo. Kaj ĉi tiu diris: Donu al la homoj, ke ili manĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Lia servanto diris: Kiel mi povas tion doni al cent homoj? Sed li diris: Donu al la homoj, ke ili manĝu; ĉar tiele diras la Eternulo: Oni manĝos, kaj ankoraŭ iom restos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Kaj li donis al ili, kaj ili manĝis, kaj iom ankoraŭ restis, konforme al la vorto de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Naaman, la militestro de la reĝo de Sirio, estis granda homo antaŭ sia sinjoro kaj tre estimata, ĉar per li la Eternulo donis venkon al Sirio. Tiu homo estis forta militisto, sed leprulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'La Sirianoj unu fojon eliris taĉmente kaj kaptis el la Izraela lando malgrandan knabinon, kaj ŝi fariĝis servantino de la edzino de Naaman.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Kaj ŝi diris al sia sinjorino: Ho, se mia sinjoro estus ĉe la profeto, kiu loĝas en Samario! tiu forigus de li la lepron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Kaj iu iris kaj rakontis al sia sinjoro, dirante: Tiel kaj tiel diris la knabino, kiu estas el la lando Izraela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Kaj la reĝo de Sirio diris: Iru, kaj mi sendos leteron al la reĝo de Izrael. Kaj li iris, kaj li prenis kun si dek kikarojn da arĝento kaj ses mil siklojn da oro kaj dek kompletojn da vestoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Kaj li alportis al la reĝo de Izrael la leteron, en kiu estis skribite: Kune kun ĉi tiu letero mi sendas al vi mian servanton Naaman, por ke vi liberigu lin de lia lepro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Kiam la reĝo de Izrael tralegis la leteron, li disŝiris siajn vestojn, kaj diris: Ĉu mi estas Dio, por mortigi kaj vivigi, ke tiu sendas al mi, por ke mi liberigu homon de lia lepro? nun sciu kaj vidu, ke li serĉas pretekston kontraŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Kiam Eliŝa, la homo de Dio, aŭdis, ke la reĝo de Izrael disŝiris siajn vestojn, li sendis al la reĝo, por diri: Kial vi disŝiris viajn vestojn? li venu al mi, kaj li ekscios, ke ekzistas profeto en Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Kaj venis Naaman kun siaj ĉevaloj kaj ĉaroj, kaj haltis ĉe la pordo de la domo de Eliŝa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Kaj Eliŝa sendis al li senditon, por diri: Iru kaj lavu vin sep fojojn en Jordan, kaj renoviĝos via korpo kaj vi fariĝos pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Tiam Naaman ekkoleris kaj foriris, kaj diris: Jen mi pensis, ke li eliros kaj stariĝos, kaj alvokos la nomon de la Eternulo, sia Dio, kaj metos sian manon sur la lokon kaj forigos la lepron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Ĉu Amana kaj Parpar, la riveroj de Damasko, ne estas pli bonaj, ol ĉiuj akvoj de Izrael? ĉu mi ne povas lavi min en ili kaj fariĝi pura? Kaj li forturnis sin kaj foriris kun kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Sed liaj servantoj aliris, kaj ekparolis al li, kaj diris: Nia patro! se ion grandan la profeto ordonus al vi, ĉu vi tion ne farus? des pli, se li diris al vi: Lavu vin, kaj vi estos pura!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Kaj li iris kaj enakvigis sin en Jordan sep fojojn, konforme al la vorto de la homo de Dio; kaj lia korpo renoviĝis kiel la korpo de malgranda infano, kaj li fariĝis pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Kaj li revenis al la homo de Dio, li kaj lia tuta akompanantaro, kaj li venis kaj stariĝis antaŭ li, kaj diris: Nun mi eksciis, ke sur la tuta tero ne ekzistas Dio krom ĉe Izrael; prenu do nun donacon de via servanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Sed tiu diris: Kiel vivas la Eternulo, antaŭ kiu mi staras, mi ne prenos. Li insistis ĉe li, ke li prenu, sed tiu ne volis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Tiam Naaman diris: Se ne, tiam mi petas, oni donu al via servanto tiom da tero, kiom povas porti paro da muloj; ĉar via servanto ne alportados plu bruloferojn nek buĉoferojn al aliaj dioj krom la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Nur en jena afero la Eternulo pardonu vian servanton: kiam mia sinjoro iros en la templon de Rimon, por tie adorkliniĝi, kaj li apogos sin sur mia brako kaj mi adorkliniĝos en la templo de Rimon, tiam la Eternulo pardonu vian servanton pri tiu afero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Tiu diris al li: Iru en paco. Kaj kiam li foriris de li certan spacon da tero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Geĥazi, la junulo de Eliŝa, de la homo de Dio, diris al si: Jen mia sinjoro domaĝis la Sirianon Naaman, kaj ne prenis el lia mano tion, kion tiu alportis; kiel vivas la Eternulo, mi kuros post li kaj prenos ion de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Kaj Geĥazi postkuris Naamanon. Kiam Naaman vidis, ke li kuras post li, li desaltis de la ĉaro renkonte al li, kaj diris: Ĉu la farto estas bona?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Tiu respondis: Bona; mia sinjoro sendis min, por diri: Jen nun venis al mi de la monto de Efraim du junuloj el la profetidoj; donu por ili, mi petas, kikaron da arĝento kaj du kompletojn da vestoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Kaj Naaman diris: Pli bone prenu du kikarojn. Kaj li insistis ĉe li, kaj ligis du kikarojn da arĝento en du paketoj kaj du kompletojn da vestoj kaj donis al siaj du junuloj, kaj ili portis antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Kiam li venis al la monteto, li prenis el iliaj manoj kaj kaŝis en la domo. Kaj li forliberigis la homojn, kaj ili foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Kiam li venis kaj aperis antaŭ sia sinjoro, Eliŝa diris al li: De kie vi venas, Geĥazi? Ĉi tiu respondis: Via servanto nenien iris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Sed tiu diris al li: Mia koro ne forestis, kiam la homo returnis sin de sia ĉaro renkonte al vi. Ĉu nun estas la tempo, por preni arĝenton aŭ preni vestojn aŭ olivarbojn, vinberĝardenojn, ŝafojn, bovojn, sklavojn, aŭ sklavinojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'La lepro de Naaman aliĝu do al vi kaj al via idaro por eterne. Kaj tiu foriris de li, leprokovrita kiel neĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'La profetidoj diris al Eliŝa: Jen la loko, kie ni loĝas ĉe vi, estas tro malvasta por ni;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'ni iru do al Jordan, kaj ni prenu de tie ĉiu po unu trabo, kaj ni aranĝu al ni tie lokon, por tie loĝi. Li diris: Iru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Kaj unu el ili diris: Volu vi ankaŭ iri kun viaj servantoj. Kaj li diris: Mi iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Kaj li iris kun ili. Kaj ili venis al Jordan kaj hakis arbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Kiam unu el ili faligis arbon, la hakilo falis en la akvon. Kaj li ekkriis kaj diris: Ho ve, mia sinjoro! ĝi estas ja prunteprenita!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Kaj la homo de Dio diris: Kien ĝi falis? Tiu montris al li la lokon. Kaj li dehakis lignon kaj ĵetis tien, kaj la hakilo suprennaĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'Kaj li diris: Levu ĝin. Tiu etendis sian manon kaj prenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'La reĝo de Sirio komencis militon kontraŭ Izrael, kaj konsiliĝis kun siaj servantoj, dirante: Tie kaj tie mi stariĝos tendare.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Tiam la homo de Dio sendis al la reĝo de Izrael, por diri: Gardu vin, ke vi ne trapasu tiun lokon, ĉar tie staras la Sirianoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Kaj la reĝo de Izrael sendis al la loko, pri kiu diris al li la homo de Dio kaj avertis lin, kaj li tie antaŭgardis sin ne unu kaj ne du fojojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Maltrankviliĝis la koro de la reĝo de Sirio pro tiu afero; kaj li alvokis siajn servantojn, kaj diris al ili: Ĉu vi ne diros al mi, kiu el ni estas en rilatoj kun la reĝo de Izrael?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Tiam diris unu el liaj servantoj: Ne, mia sinjoro, ho reĝo! sed la profeto Eliŝa, kiu estas en Izrael, raportas al la reĝo de Izrael eĉ tiujn vortojn, kiujn vi parolas en via dormoĉambro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Kaj li diris: Iru kaj rigardu, kie li estas, tiam mi sendos kaj prenos lin. Kaj oni sciigis al li, dirante: Jen li estas en Dotan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Tiam li sendis tien ĉevalojn kaj ĉarojn kaj grandan militistaron. Ili venis en nokto kaj ĉirkaŭis la urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Kiam la servanto de la homo de Dio frue matene leviĝis kaj eliris, jen militistaro ĉirkaŭas la urbon kun ĉevaloj kaj ĉaroj. Kaj lia servanto diris al li: Ho ve, mia sinjoro! kion ni faros?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Sed li diris: Ne timu; ĉar pli multaj estas tiuj, kiuj estas kun ni, ol tiuj, kiuj estas kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Kaj Eliŝa ekpreĝis kaj diris: Ho Eternulo, malfermu liajn okulojn, por ke li vidu. Kaj la Eternulo malfermis la okulojn de la junulo, kaj li ekvidis, ke la tuta monto estas plena de fajraj ĉevaloj kaj ĉaroj ĉirkaŭ Eliŝa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'La Sirianoj venis al li. Tiam Eliŝa ekpreĝis al la Eternulo kaj diris: Frapu ĉi tiun popolon per blindeco. Kaj Li frapis ilin per blindeco, konforme al la vorto de Eliŝa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Kaj Eliŝa diris al ili: Ĝi estas ne tiu vojo kaj ne tiu urbo; sekvu min, kaj mi kondukos vin al tiu viro, kiun vi serĉas. Kaj li kondukis ilin en Samarion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Kiam ili venis en Samarion, Eliŝa diris: Ho Eternulo, malfermu iliajn okulojn, por ke ili vidu. Kaj la Eternulo malfermis iliajn okulojn, kaj ili ekvidis, ke ili estas meze de Samario.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Kaj la reĝo de Izrael diris al Eliŝa, kiam li ekvidis ilin: Ĉu mi ne mortigu ilin? ĉu mi ne mortigu ilin, mia patro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Sed li diris: Ne mortigu; ĉu vi mortigas tiujn, kiujn vi kaptis per via glavo kaj per via pafarko? metu antaŭ ilin panon kaj akvon; ili manĝu kaj trinku, kaj ili iru al sia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Kaj li faris por ili grandan tagmanĝon, kaj ili manĝis kaj trinkis, kaj poste li ilin forliberigis, kaj ili iris al sia sinjoro. Ne venis plu taĉmentoj de Sirianoj en la landon de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Post tio Ben-Hadad, reĝo de Sirio, kolektis sian tutan militistaron, kaj iris kaj eksieĝis Samarion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Estis granda malsato en Samario. Kaj ili sieĝis ĝin tiel longe, ĝis kapo de azeno ricevis la prezon de okdek sikloj, kaj kvarono de kab�o da sterko de kolomboj la prezon de kvin sikloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Unu fojon la reĝo de Izrael iris sur la murego, kaj iu virino ekkriis al li, dirante: Helpu, mia sinjoro, ho reĝo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Li respondis: Se la Eternulo vin ne helpas, el kio do mi vin helpos? ĉu el la draŝejo aŭ ĉu el la vinpremejo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Kaj la reĝo diris al ŝi: Kio estas al vi? Ŝi respondis: Ĉi tiu virino diris al mi: Donu vian filon, por ke ni manĝu lin hodiaŭ, kaj mian filon ni manĝos morgaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Kaj ni kuiris mian filon kaj formanĝis lin; sed kiam mi diris al ŝi la sekvantan tagon: Donu vian filon, por ke ni lin manĝu, ŝi kaŝis sian filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Kiam la reĝo aŭdis la vortojn de la virino, li disŝiris siajn vestojn, irante sur la muro; kaj la popolo vidis, ke subveste sur lia korpo estas sakaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Kaj li diris: Tion kaj pli faru al mi la Eternulo, se la kapo de Eliŝa, filo de Ŝafat, restos sur li hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Dume Eliŝa sidis en sia domo, kaj la plejaĝuloj estis ĉe li. La reĝo sendis de si homon. Antaŭ ol la sendito venis al li, li diris al la plejaĝuloj: Ĉu vi vidas, ke tiu filo de mortigisto sendis, por depreni mian kapon? rigardu, kiam venos la sendito, fermu la pordon kaj forpuŝu lin per la pordo; la sono de la piedoj de lia sinjoro aŭdiĝas post li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Dum li estis ankoraŭ parolanta kun ili, jen la sendito venis al li; kaj li diris: Jen tia malbono venas de la Eternulo! kion mi ankoraŭ povas atendi de la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Tiam diris Eliŝa: Aŭskultu la vorton de la Eternulo: tiele diras la Eternulo: Morgaŭ en ĉi tiu tempo mezuro da delikata faruno havos la prezon de unu siklo, kaj du mezuroj da hordeo la prezon de unu siklo, ĉe la pordego de Samario.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Kaj respondis la altrangulo, sur kies brako la reĝo sin apogadis, al la homo de Dio, kaj diris: Eĉ se la Eternulo faros fenestrojn en la ĉielo, ĉu tio povas fariĝi? Kaj tiu diris: Vi vidos tion per viaj okuloj, sed vi ne manĝos de tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Kvar homoj lepruloj estis ĉe la enirejo de la pordego. Kaj ili diris unu al la alia: Kial ni sidas ĉi tie, ĝis ni mortos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Se ni decidos eniri en la urbon, en la urbo estas ja malsato, kaj ni tie mortos; se ni sidos ĉi tie, ni ankaŭ mortos; ni iru do kaj ĵetu nin en la tendaron de la Sirianoj. Se ili lasos nin vivantaj, ni vivos; kaj se ili mortigos nin, ni mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Kaj ili leviĝis en krepusko, por iri en la tendaron de la Sirianoj. Ili venis al la rando de la tendaro de la Sirianoj, kaj jen neniu tie estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'La Sinjoro aŭdigis al la tendaro de la Sirianoj la sonon de ĉaroj kaj la sonon de ĉevaloj, la sonon de granda militistaro. Kaj ili diris unu al la alia: Certe la reĝo de Izrael dungis kontraŭ ni la reĝojn de la Ĥetidoj kaj la reĝojn de la Egiptoj, ke ili iru kontraŭ nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Kaj ili leviĝis kaj forkuris en la krepusko, kaj restigis siajn tendojn kaj siajn ĉevalojn kaj siajn azenojn, la tutan tendaron, kia ĝi estis, kaj ili forkuris, por savi sian vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Kaj tiuj lepruloj venis al la rando de la tendaro, kaj ili eniris en unu tendon kaj manĝis kaj trinkis, kaj prenis de tie arĝenton kaj oron kaj vestojn, kaj iris kaj kaŝis; kaj ili venis denove, kaj eniris en alian tendon kaj prenis de tie, kaj iris kaj kaŝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Kaj ili diris unu al la alia: Ne ĝuste ni agas; la hodiaŭa tago estas tago de bona sciigo; se ni silentos kaj atendos ĝis la lumo de la mateno, ni montriĝos kulpaj. Ni iru do, por ke ni venu kaj sciigu al la domo de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Kaj ili venis, kaj vokis al la pordegistoj de la urbo, kaj raportis al ili, dirante: Ni venis en la tendaron de la Sirianoj, kaj ni konvinkiĝis, ke tie estas neniu homo nek voĉo de homo, sed nur ĉevaloj alligitaj kaj azenoj alligitaj kaj tendoj en sia ordinara stato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Kaj la pordegistoj vokis kaj raportis internen, en la domon de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Tiam la reĝo leviĝis en la nokto, kaj diris al siaj servantoj: Mi diros al vi, kion faris al ni la Sirianoj. Ili scias, ke ni suferas malsaton, kaj ili eliris el la tendaro, por kaŝi sin sur la kampo, pensante: Kiam ili eliros el la urbo, ni kaptos ilin vivantajn, kaj ni eniros en la urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Sed unu el liaj servantoj respondis kaj diris: Oni prenu do kvin el la restintaj ĉevaloj, kiuj restis en la urbo (estos al ili kiel al la tuta multo da Izraelidoj, kiuj restis en la urbo, aŭ kiel al la tuta multo da Izraelidoj, kiuj pereis); kaj ni sendu kaj vidu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Kaj oni prenis du ĉarojn kun ĉevaloj; kaj la reĝo sendis post la militistaro de la Sirianoj, dirante: Iru kaj rigardu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Kaj ili iris post ili ĝis Jordan, kaj vidis, ke la tuta vojo estas plena de vestoj kaj uzataĵoj, kiujn la Sirianoj ĵetis ĉe sia rapidado. Kaj la senditoj revenis kaj raportis al la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Tiam la popolo eliris, kaj disrabis la tendaron de la Sirianoj. Kaj la prezo de mezuro da delikata faruno fariĝis unu siklo, kaj de du mezuroj da hordeo unu siklo, konforme al la vorto de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'La reĝo donis al la altrangulo, sur kies brako li sin apogadis, postenon ĉe la pordego; kaj la popolo dispremis lin per la piedoj ĉe la pordego, kaj li mortis, kiel diris la homo de Dio, kion li parolis, kiam la reĝo venis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Kiam la homo de Dio parolis al la reĝo, dirante: Du mezuroj da hordeo havos la prezon de unu siklo, kaj unu mezuro da delikata faruno la prezon de unu siklo, morgaŭ en ĉi tiu tempo ĉe la pordego de Samario:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'tiam la altrangulo respondis al la homo de Dio kaj diris: Eĉ se la Eternulo faros fenestrojn en la ĉielo, ĉu tio povas fariĝi? Kaj li diris: Vi vidos per viaj okuloj, sed vi ne manĝos de tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'Kaj tiel fariĝis al li; la popolo dispremis lin per la piedoj ĉe la pordego, kaj li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Eliŝa diris al la virino, kies filon li revivigis, jene: Leviĝu kaj iru, vi kaj via domo, kaj loĝu kelkan tempon tie, kie vi povos loĝi; ĉar la Eternulo alvokos malsaton, kaj ĝi venos en la landon por sep jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Kaj la virino leviĝis kaj faris laŭ la vorto de la homo de Dio, kaj ŝi iris, ŝi kaj ŝia domo, kaj loĝis en la lando de la Filiŝtoj sep jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Post la paso de la sep jaroj la virino revenis el la lando de la Filiŝtoj, kaj ŝi iris, por klopodi ĉe la reĝo pri sia domo kaj pri sia kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'La reĝo tiam parolis kun Geĥazi, la junulo de la homo de Dio, dirante: Rakontu al mi ĉiujn grandajn farojn, kiujn faris Eliŝa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Dum li estis rakontanta al la reĝo, ke tiu revivigis mortinton, jen la virino, kies filon li revivigis, ekpetis la reĝon pri sia domo kaj pri sia kampo. Kaj Geĥazi diris: Mia sinjoro, ho reĝo, jen estas tiu virino, kaj jen estas ŝia filo, kiun Eliŝa revivigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Kaj la reĝo demandis la virinon, kaj ŝi rakontis al li. Kaj la reĝo donis al ŝi unu korteganon, dirante: Redonu al ŝi ĉion, kio apartenas al ŝi, kaj ĉiujn enspezojn de la kampo de post la tago, kiam ŝi forlasis la landon, ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Eliŝa venis en Damaskon. Ben-Hadad, reĝo de Sirio, tiam estis malsana. Kaj oni raportis al li, dirante: La homo de Dio venis ĉi tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'Tiam la reĝo diris al Ĥazael: Prenu en vian manon donacon, kaj iru renkonte al la homo de Dio, kaj demandu per li la Eternulon, ĉu mi resaniĝos de ĉi tiu malsano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Kaj Ĥazael iris renkonte al li, kaj prenis donacon en sian manon kaj da ĉio plej bona en Damasko tiom, kiom povas porti kvardek kameloj, kaj li venis kaj stariĝis antaŭ li, kaj diris: Via filo Ben-Hadad, reĝo de Sirio, sendis min al vi, por demandi: Ĉu mi resaniĝos de ĉi tiu malsano?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Kaj Eliŝa diris al li: Iru, diru al li: Vi resaniĝos. Sed la Eternulo montris al mi, ke li mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Kaj li fikse rigardis lin, ĝis li hontiĝis, kaj la homo de Dio ploris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Ĥazael diris: Kial mia sinjoro ploras? Tiu respondis: Ĉar mi scias, kian malbonon vi faros al la Izraelidoj: iliajn fortikaĵojn vi forbruligos, iliajn junulojn vi mortigos per glavo, iliajn suĉinfanojn vi frakasos, kaj iliajn gravedulinojn vi disfendos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Ĥazael diris: Kio estas via servanto, la hundo, ke li faru tiun grandan faron? Kaj Eliŝa diris: La Eternulo montris al mi, ke vi estos reĝo de Sirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Li foriris de Eliŝa kaj venis al sia sinjoro. Ĉi tiu diris al li: Kion diris al vi Eliŝa? Kaj li respondis: Li diris al mi, ke vi resaniĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Sed la sekvantan tagon li prenis la litkovrilon, kaj trempis ĝin en akvo kaj etendis ĝin sur lia vizaĝo, kaj li mortis. Kaj anstataŭ li ekreĝis Ĥazael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'En la kvina jaro de Joram, filo de Aĥab, reĝo de Izrael, post Jehoŝafat, reĝo de Judujo, ekreĝis Jehoram, filo de Jehoŝafat, reĝo de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Li havis la aĝon de tridek du jaroj, kiam li fariĝis reĝo, kaj ok jarojn li reĝis en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Li iradis laŭ la vojo de la reĝoj de Izrael, kiel faris la domo de Aĥab, ĉar filino de Aĥab estis lia edzino, kaj li faradis malbonon antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Tamen la Eternulo ne volis pereigi Judujon, pro Sia servanto David, ĉar Li promesis al li doni lumilon al li kaj al liaj filoj por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'En lia tempo la Edomidoj defalis de Judujo kaj starigis super si reĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Joram iris Cairon kune kun ĉiuj siaj ĉaroj; kaj li leviĝis nokte, kaj venkobatis la Edomidojn, kiuj estis ĉirkaŭ li, kaj la ĉarestrojn; kaj la popolo forkuris al siaj tendoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Tamen la Edomidoj restis defalintaj de Judujo ĝis la nuna tago. Tiam defalis ankaŭ Libna en la sama tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'La cetera historio de Joram, kaj ĉio, kion li faris, estas priskribitaj en la libro de kroniko de la reĝoj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Kaj Joram ekdormis kun siaj patroj, kaj oni enterigis lin kun liaj patroj en la urbo de David. Kaj anstataŭ li ekreĝis lia filo Aĥazja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'En la dek-dua jaro de Joram, filo de Aĥab, reĝo de Izrael, ekreĝis Aĥazja, filo de Jehoram, reĝo de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'La aĝon de dudek du jaroj havis Aĥazja, kiam li fariĝis reĝo, kaj unu jaron li reĝis en Jerusalem. La nomo de lia patrino estis Atalja, filino de Omri, reĝo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Kaj li iradis laŭ la vojo de la domo de Aĥab, kaj faradis malbonon antaŭ la Eternulo, kiel la domo de Aĥab, ĉar li estis boparenco de la domo de Aĥab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Li iris kun Joram, filo de Aĥab, milite kontraŭ Ĥazaelon, reĝon de Sirio, al Ramot en Gilead; kaj la Sirianoj vundis Joramon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Kaj la reĝo Joram revenis, por kuraci sin en Jizreel de la vundoj, kiujn faris al li la Sirianoj en Ramot, kiam li batalis kontraŭ Ĥazael, reĝo de Sirio. Kaj Aĥazja, filo de Jehoram, reĝo de Judujo, iris, por viziti Joramon, filon de Aĥab, en Jizreel, ĉar ĉi tiu estis malsana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'La profeto Eliŝa alvokis unu el la profetidoj, kaj diris al li: Zonu viajn lumbojn, kaj prenu en vian manon ĉi tiun vazon kun oleo, kaj iru en Ramoton en Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Kiam vi venos tien, elserĉu tie Jehun, filon de Jehoŝafat, filo de Nimŝi, kaj aliru kaj starigu lin el meze de liaj fratoj kaj enkonduku lin en la plej internan ĉambron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Kaj prenu la vazon kun la oleo kaj verŝu sur lian kapon, kaj diru: Tiele diras la Eternulo: Mi sanktoleis vin reĝo super Izrael. Poste malfermu la pordon kaj forkuru, ne prokrastu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Kaj iris la junulo, la junulo la profeto, al Ramot en Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Kiam li venis, li vidis, ke sidas la militestroj. Kaj li diris: Mi havas ion por diri al vi, ho estro. Kaj Jehu diris: Al kiu el ni ĉiuj? Li respondis: Al vi, ho estro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Tiu leviĝis kaj iris en la domon. Li verŝis la oleon sur lian kapon, kaj diris: Tiele diras la Eternulo, Dio de Izrael: Mi sanktoleis vin reĝo super la popolo de la Eternulo, super Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Kaj vi ekstermos la domon de via sinjoro Aĥab, por ke Mi venĝu la sangon de Miaj servantoj, la profetoj, kaj la sangon de ĉiuj servantoj de la Eternulo, verŝitajn de la mano de Izebel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'Kaj pereos la tuta domo de Aĥab; kaj Mi ekstermos ĉe Aĥab ĉiun virseksulon, malliberulon kaj liberulon en Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Kaj mi faros al la domo de Aĥab kiel al la domo de Jerobeam, filo de Nebat, kaj kiel al la domo de Baaŝa, filo de Aĥija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Kaj Izebelon manĝos la hundoj sur la kampo de Jizreel, kaj neniu enterigos ŝin. Kaj li malfermis la pordon kaj forkuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Kiam Jehu eliris al la servantoj de sia sinjoro, ili diris al li: Ĉu ĉio estas en ordo? por kio venis al vi tiu frenezulo? Li respondis al ili: Vi konas ja tiun homon kaj lian parolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Ili diris: Ne vero, tamen diru al ni. Kaj li diris: Tiel kaj tiel li parolis al mi, dirante: Tiele diras la Eternulo: Mi sanktoleis vin reĝo super Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Kaj rapide ili prenis ĉiu sian veston kaj sternis sub li sur la altaj ŝtupoj, kaj ekblovis per trumpeto, kaj diris: Jehu fariĝis reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Tiam Jehu, filo de Jehoŝafat, filo de Nimŝi, faris konspiron kontraŭ Joram. (Dume Joram staris garde en Ramot en Gilead, li kaj la tuta Izrael, kontraŭ Ĥazael, reĝo de Sirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Kaj la reĝo Joram* revenis, por kuraci sin en Jizreel de la vundoj, kiujn faris al li la Sirianoj, kiam li batalis kontraŭ Ĥazael, reĝo de Sirio.) Tiam Jehu diris: Se vi konsentas, neniu eliĝu el la urbo, por iri kaj sciigi en Jizreel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Kaj Jehu ekrajdis kaj direktis sin al Jizreel; ĉar tie kuŝis Joram, kaj Aĥazja, reĝo de Judujo, venis, por viziti Joramon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'La gardostaranto staris sur la turo en Jizreel, kaj li ekvidis la alproksimiĝantan amason de Jehu, kaj diris: Mi vidas amason. Tiam Joram diris: Prenu rajdanton kaj sendu kontraŭ ili, por ke li demandu, ĉu ĉio estas en ordo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Kaj la rajdanto sur ĉevalo direktis sin renkonte al li, kaj diris: Tiele diras la reĝo: Ĉu ĉio estas en ordo? Sed Jehu respondis: La ordo ne estas via afero, turnu vin kaj sekvu min. Kaj la gardostaranto raportis, dirante: La sendito venis al ili, sed ne revenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Tiam li sendis duan rajdanton, kaj ĉi tiu venis al ili, kaj diris: Tiele diras la reĝo: Ĉu ĉio estas en ordo? Jehu respondis: La ordo ne estas via afero, turnu vin kaj sekvu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'La gardostaranto raportis, dirante: Li venis al ili, sed ne revenis; la kondukado estas kiel kondukado de Jehu, filo de Nimŝi, ĉar li kondukas rapidege.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Tiam Joram diris: Oni jungu! Kaj oni jungis lian ĉaron. Kaj eliris Joram, reĝo de Izrael, kaj Aĥazja, reĝo de Judujo, ĉiu sur sia ĉaro, kaj ili direktis sin renkonte al Jehu, kaj ili renkontis lin sur la kampo de Nabot, la Jizreelano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Kiam Joram ekvidis Jehun, li diris: Ĉu ĉio estas en ordo, Jehu? Sed tiu respondis: Kia ordo povas esti ĉe la malĉastado de via patrino Izebel kaj ĉe ŝiaj multaj sorĉaĵoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Tiam Joram turnis sian manon kaj forkuris, kaj diris al Aĥazja: Perfido, ho Aĥazja!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Sed Jehu streĉis per sia mano la pafarkon kaj pafe frapis Joramon inter liaj brakoj, kaj la sago iris tra lian koron, kaj li falis genue sur sia ĉaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Kaj Jehu diris al sia altrangulo Bidkar: Prenu kaj ĵetu lin sur la kampon de Nabot, la Jizreelano; ĉar rememoru, kiel mi kaj vi sur ĉaro veturis post lia patro Aĥab kaj la Eternulo eldiris pri li jenan profetaĵon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Vere, diris la Eternulo, la sangon de Nabot kaj la sangon de liaj filoj Mi vidis hieraŭ, kaj Mi venĝos al vi sur ĉi tiu kampo, diris la Eternulo. Prenu do nun kaj ĵetu lin sur la kampon, konforme al la vorto de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Kiam Aĥazja, reĝo de Judujo, tion vidis, li forkuris en la direkto al la ĝardena domo. Sed Jehu postkuris lin, kaj diris: Lin ankaŭ batu sur la ĉaro. Kaj oni frapis lin sur la altaĵo Gur, kiu estas apud Jibleam. Kaj li forkuris en Megidon kaj mortis tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Kaj liaj servantoj forveturigis lin en Jerusalemon kaj enterigis lin en lia tombo kun liaj patroj en la urbo de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'En la jaro dek-unua de Joram, filo de Aĥab, Aĥazja ekreĝis super Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Jehu venis al Jizreel. Kiam Izebel tion aŭdis, ŝi kolorigis siajn okulojn kaj beligis sian kapon kaj ekrigardis tra la fenestro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Kiam Jehu eniris en la pordegon, ŝi diris: Ĉu nun estos paco, ho Zimri, mortiginto de sia sinjoro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Tiam li levis sian vizaĝon al la fenestro, kaj diris: Kiu estas kun mi? kiu? Kaj ekrigardis al li du aŭ tri korteganoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Kaj li diris: Elĵetu ŝin! Kaj ili ŝin elĵetis. Kaj ŝia sango ŝprucis sur la muron kaj sur la ĉevalojn, kaj oni dispremis ŝin per la piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Li eniris kaj manĝis kaj trinkis, kaj diris: Rigardu, kie estas tiu malbenitino, kaj enterigu ŝin, ĉar ŝi estas reĝidino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Kaj oni iris, por enterigi ŝin, sed oni trovis nenion de ŝi krom la kranio, la piedoj, kaj la manplatoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Oni revenis kaj raportis al li. Tiam li diris: Tio estas la vorto de la Eternulo, kiun Li diris per Sia servanto Elija, la Teŝebano, nome: Sur la kampo de Jizreel la hundoj formanĝos la karnon de Izebel;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'kaj la kadavro de Izebel estos kiel sterko sur la tero sur la kampo de Jizreel, tiel, ke neniu povos diri: Tio estas Izebel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Aĥab havis sepdek filojn en Samario. Kaj Jehu skribis leterojn kaj sendis en Samarion al la estroj de Jizreel, la plejaĝuloj, kaj la filedukistoj de Aĥab, kun la sekvanta enhavo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'Kiam ĉi tiu letero venos al vi, ĉe kiuj troviĝas la filoj de via sinjoro kaj sub kies administrado troviĝas la ĉaroj kaj la ĉevaloj kaj la fortikigita urbo kaj la bataliloj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'tiam rigardu, kiu estas la plej bona kaj plej digna el la filoj de via sinjoro, kaj sidigu lin sur la trono de lia patro kaj batalu pro la domo de via sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Sed ili tre forte ektimis, kaj diris: Jen la du reĝoj ne povis kontraŭstari al li, kiel do ni kontraŭstaros?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Kaj la palacestro kaj la urbestro kaj la plejaĝuloj kaj la filedukistoj sendis al Jehu, por diri: Ni estas viaj servantoj, kaj ĉion, kion vi ordonos al ni, ni faros; ni neniun faros reĝo; kio plaĉas al vi, tion faru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Tiam li skribis al ili duan leteron kun jena enhavo: Se vi estas sur mia flanko kaj obeas mian voĉon, tiam prenu la kapojn de la filoj de via sinjoro kaj venu al mi morgaŭ en ĉi tiu tempo en Jizreelon. Kaj da reĝidoj estis sepdek homoj ĉe la eminentuloj de la urbo, kiuj edukis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Kiam la letero venis al ili, ili prenis la filojn de la reĝo kaj buĉis ilin, sepdek homojn, kaj metis iliajn kapojn en korbojn kaj sendis al li en Jizreelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Kaj venis la sendito, kaj diris al li jene: Oni alportis la kapojn de la reĝidoj. Kaj li diris: Kuŝigu ilin en du amasoj antaŭ la enirejo de la pordego ĝis mateno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Matene li eliris kaj stariĝis, kaj diris al la tuta popolo: Vi estas senkulpaj; estas mi, kiu faris konspiron kontraŭ mia sinjoro kaj mortigis lin; sed kiu mortigis ĉiujn ĉi tiujn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Sciu do nun, ke el la vortoj de la Eternulo nenio falis teren, el tio, kion la Eternulo diris pri la domo de Aĥab; la Eternulo faris tion, kion Li diris per Sia servanto Elija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Kaj Jehu mortigis ĉiujn restintojn el la domo de Aĥab en Jizreel kaj ĉiujn liajn altrangulojn kaj liajn konatojn kaj liajn pastrojn, ĝis restis neniu saviĝinto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Kaj li leviĝis, kaj iris kaj direktis sin al Samario. Kiam li estis survoje ĉe la domo de la paŝtistoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'Jehu renkontis la fratojn de Aĥazja, reĝo de Judujo, kaj li diris: Kiuj vi estas? Ili respondis: Ni estas fratoj de Aĥazja, kaj ni iras, por demandi pri la farto de la filoj de la reĝo kaj de la filoj de la reĝino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Tiam li diris: Prenu ilin vivantajn. Kaj oni prenis ilin vivantajn kaj buĉis ilin super la puto ĉe la domo de paŝtistoj, kvardek du homojn, kaj neniu el ili restis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'De tie li foriris, kaj li renkontis Jehonadabon, filon de Reĥab, irantan renkonte al li. Li salutis lin, kaj diris al li: Ĉu via koro estas favora, kiel mia koro estas favora al via koro? Jehonadab respondis: Jes. Se jes, tiam donu al mi vian manon. Kaj li donis al li sian manon kaj prenis lin al si sur la ĉaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'Kaj li diris: Iru kun mi kaj rigardu mian fervoron pri la Eternulo. Kaj oni veturigis lin kun li sur lia ĉaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Kiam li venis Samarion, li mortigis ĉiujn, kiuj restis de Aĥab en Samario, ĝis li tute ekstermis lin, konforme al la vorto de la Eternulo, kiun Li diris al Elija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Kaj Jehu kunvenigis la tutan popolon, kaj diris al ili: Aĥab servis al Baal malmulte, Jehu servos al li multe;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'kunvoku do al mi ĉiujn profetojn de Baal, ĉiujn liajn servantojn, kaj ĉiujn liajn pastrojn, ke neniu forestu; ĉar mi volas fari grandan oferadon al Baal; ĉiu, kiu forestos, perdos sian vivon. Jehu faris tion kun ruza intenco, por pereigi la servantojn de Baal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Kaj Jehu diris: Aranĝu sanktan kunvenon por Baal. Kaj oni tion proklamis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Kaj Jehu sendis al la tuta Izrael; kaj venis ĉiuj servantoj de Baal; restis neniu, kiu ne venus. Ili eniris en la domon de Baal, kaj la domo de Baal pleniĝis de rando ĝis rando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Kaj li diris al la estro de la vestejo: Elportu vestojn por ĉiuj servantoj de Baal. Kaj li elportis vestojn por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Kaj Jehu kun Jehonadab, filo de Reĥab, eniris en la domon de Baal, kaj li diris al la servantoj de Baal: Esploru kaj rigardu, ĉu ne estas ĉi tie kun vi iu el la servantoj de la Eternulo, ĉar ĉi tie devas esti sole nur servantoj de Baal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'Ili eniris, por fari buĉoferojn kaj bruloferojn. Dume Jehu starigis ekstere okdek virojn, kaj diris: Se ĉe iu el vi saviĝos iu el la homoj, kiujn mi transdonas en viajn manojn, tiam lia animo anstataŭos la animon de tiu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Kiam la bruloferoj estis finitaj, Jehu diris al la korpogardistoj kaj al la estroj: Iru, batu ilin, ke neniu eliru. Kaj oni mortigis ilin per glavo, kaj la korpogardistoj kaj la estroj forĵetis ilin kaj iris en la urbon de la domo de Baal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'Kaj oni elportis la statuojn el la domo de Baal kaj forbruligis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'Kaj oni disrompis la statuon de Baal, kaj oni detruis la domon de Baal, kaj oni faris el ĝi ekskrementejon ĝis la nuna tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Kaj Jehu ekstermis Baalon el Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Tamen de la pekoj de Jerobeam, filo de Nebat, per kiuj li pekigis Izraelon, Jehu ne deturnis sin, de la oraj bovidoj, kiuj estis en Bet-El kaj en Dan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Kaj la Eternulo diris al Jehu: Pro tio, ke vi bone faris tion, kio plaĉis al Mi, kaj vi faris al la domo de Aĥab konforme al tio, kio estis en Mia koro, viaj filoj ĝis la kvara generacio sidos sur la trono de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Sed Jehu ne zorgis pri tio, ke li iradu laŭ la instruo de la Eternulo, Dio de Izrael, per sia tuta koro. Li ne deturnis sin de la pekoj de Jerobeam, per kiuj li pekigis Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'En tiu tempo la Eternulo komencis faradi dehakojn en Izrael, kaj Ĥazael venkobatis ilin ĉe ĉiuj limoj de Izrael:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'oriente de Jordan la tutan landon de Gilead, de la Gadidoj, Rubenidoj, kaj Manaseidoj, komencante de Aroer, kiu estas ĉe la torento Arnon, Gileadon kaj Baŝanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'La cetera historio de Jehu, kaj ĉio, kion li faris, kaj lia tuta potenco estas priskribitaj en la libro de kroniko de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Kaj Jehu ekdormis kun siaj patroj, kaj oni enterigis lin en Samario. Kaj anstataŭ li ekreĝis lia filo Jehoaĥaz.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'La tempo de reĝado de Jehu super Izrael en Samario estis dudek ok jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Kiam Atalja, la patrino de Aĥazja, vidis, ke ŝia filo mortis, ŝi leviĝis kaj ekstermis la tutan reĝan idaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Sed Jehoŝeba, filino de la reĝo Joram kaj fratino de Aĥazja, prenis Joaŝon, filon de Aĥazja, kaj ŝtele forkondukis lin el inter la mortigataj filoj de la reĝo, lin kaj lian nutristinon, kaj lokis ilin en la ĉambro de litoj; kaj oni kaŝis lin for de Atalja, kaj li ne estis mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Kaj li restis kaŝita kun ŝi en la domo de la Eternulo dum ses jaroj; kaj Atalja reĝis super la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Sed en la sepa jaro sendis Jehojada kaj prenis la centestrojn el la korpogardistoj kaj la kuristoj kaj venigis ilin al si en la domon de la Eternulo; kaj li faris kun ili interligon kaj ĵurigis ilin en la domo de la Eternulo kaj montris al ili la filon de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'Kaj li ordonis al ili, dirante: Jenon vi devas fari: tiu triono de vi, kiu venas en sabato, plenumu gardadon en la domo de la reĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'triono estu ĉe la Pordego Sur; kaj triono ĉe la pordego malantaŭ la korpogardistoj. Kaj plenumu la gardadon de la domo alterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Du partoj el vi ĉiuj, kiuj foriras en sabato, plenumu gardadon ĉe la reĝo en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Kaj ĉirkaŭu la reĝon ĉiuflanke, ĉiu kun sia batalilo en la mano; kaj se iu eniros en la vicojn, oni lin mortigu. Kaj estu apud la reĝo, kiam li eliros aŭ eniros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Kaj la centestroj faris ĉion, kion ordonis la pastro Jehojada; kaj ĉiu prenis siajn homojn, la sabate venantajn kaj la sabate forirantajn, kaj venis al la pastro Jehojada.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'La pastro disdonis al la centestroj la lancojn kaj ŝildojn, kiuj apartenis al la reĝo David kaj kiuj estis en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Kaj la korpogardistoj stariĝis, ĉiu kun siaj bataliloj en la mano, de la dekstra flanko de la domo ĝis la maldekstra flanko de la domo, ĉe la altaro kaj ĉe la domo, ĉirkaŭe de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Kaj li elkondukis la reĝidon kaj metis sur lin la kronon kaj la ateston; kaj oni proklamis lin reĝo kaj sanktoleis lin, kaj oni aplaŭdis kaj kriis: Vivu la reĝo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Kiam Atalja aŭdis la bruon de la kuranta popolo, ŝi iris al la popolo en la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Kaj ŝi ekvidis, ke jen la reĝo staras ĉe la kolono, laŭ la moro, kaj la eminentuloj kaj la trumpetistoj apud la reĝo, kaj la tuta popolo de la lando ĝojas, kaj oni trumpetas. Tiam Atalja disŝiris siajn vestojn, kaj ekkriis: Konspiro, konspiro!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Kaj la pastro Jehojada ordonis al la centestroj, la estroj de la militistaro, kaj diris al ili: Elkonduku ŝin ekster la vicojn, kaj ĉiun, kiu ŝin sekvos, mortigu per glavo; ĉar la pastro diris: Oni ne mortigu ŝin en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Kaj oni liberigis por ŝi lokon, kaj ŝi iris laŭ la vojo de la ĉevaloj al la reĝa domo, kaj tie oni ŝin mortigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Kaj Jehojada faris interligon inter la Eternulo kaj la reĝo kaj la popolo, ke ĝi estu popolo de la Eternulo; kaj inter la reĝo kaj la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Kaj la tuta popolo de la lando iris en la domon de Baal kaj ĝin detruis; kaj liajn altarojn kaj liajn bildojn ili tute disrompis; kaj Matanon, la pastron de Baal, ili mortigis antaŭ la altaroj. Kaj la pastro starigis oficistaron en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Kaj li prenis la centestrojn kaj la korpogardistojn kaj la kuristojn kaj la tutan popolon de la lando, kaj ili kondukis la reĝon el la domo de la Eternulo, kaj ili venis per la pordego de la kuristoj en la reĝan domon; kaj li sidiĝis sur la trono de la reĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Kaj la tuta popolo de la lando ĝojis, kaj la urbo estis trankvila. Sed Ataljan oni mortigis per glavo en la reĝa domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'La aĝon de sep jaroj havis Jehoaŝ, kiam li fariĝis reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'En la sepa jaro de Jehu Jehoaŝ fariĝis reĝo, kaj kvardek jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Cibja, el Beer-Ŝeba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Jehoaŝ agadis tiel, kiel plaĉas al la Eternulo, dum la tempo, en kiu gvidadis lin la pastro Jehojada.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Nur la altaĵojn oni ne senfunkciigis; la popolo ĉiam ankoraŭ oferadis kaj incensadis sur la altaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Kaj Jehoaŝ diris al la pastroj: La tutan sanktigatan monon, kiun oni alportas en la domon de la Eternulo, la monon de pasantoj, la monon, kiun oni donas laŭtakse por sia animo, la tutan monon, kiun iu donas propradezire, por enporti en la domon de la Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'la pastroj prenu al si, ĉiu de sia konato, kaj ili rebonigu la difektojn en la domo, ĉie, kie troviĝos ia difekto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'Sed ĉar ĝis la dudek-tria jaro de la reĝo Jehoaŝ la pastroj ne rebonigis la difektojn en la domo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'la reĝo Jehoaŝ alvokis la pastron Jehojada kaj la aliajn pastrojn, kaj diris al ili: Kial vi ne rebonigas la difektojn de la domo? ne prenu do de nun monon de viaj konatoj, sed donu ĝin por rebonigo de la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Kaj la pastroj konsentis ne preni plu monon de la popolo kaj ne rebonigi la difektojn en la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'La pastro Jehojada prenis keston kaj traboris truon supre, kaj starigis ĝin apud la altaro, dekstre de la enirantoj en la domon de la Eternulo. Kaj la pastroj, kiuj gardostaris ĉe la sojlo, metadis tien la tutan monon, kiu estis alportata en la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'Ĉiufoje, kiam ili vidis, ke en la kesto estas multe da mono, venadis skribisto de la reĝo kaj la ĉefpastro, kaj ili kunligadis kaj kalkuladis la monon, trovitan en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Kaj ili donadis la kalkulitan monon en la manojn de la oficistoj laborgvidantoj en la domo de la Eternulo; kaj ĉi tiuj elspezadis ĝin por la ĉarpentistoj kaj konstruistoj, kiuj laboris en la domo de la Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'kaj por la masonistoj kaj la ŝtonhakistoj, kaj por aĉeti lignon kaj hakitajn ŝtonojn, por rebonigi la difektojn en la domo de la Eternulo, kaj por ĉio, kio devis esti elspezata por la rebonigo de la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'Tamen oni ne faris por la domo de la Eternulo arĝentajn tasojn, tranĉilojn, aspergajn kalikojn, trumpetojn, ĉiajn orajn vazojn kaj arĝentajn vazojn el la mono, kiu estis alportata en la domon de la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'sed oni donadis ĝin al la oficistoj laborgvidantoj, por ke ili rebonigu per tio la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'Oni ne postulis kalkulan raporton de tiuj homoj, en kies manojn oni donis la monon, por transdoni al la farantoj de la laboroj, sed ili laboris konfidate.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'La monon de kulpofero kaj la monon de pekofero oni ne enportadis en la domon de la Eternulo: ĝi estis por la pastroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'En tiu tempo ekiris Ĥazael, reĝo de Sirio, kaj ekmilitis kontraŭ Gat kaj venkoprenis ĝin; kaj Ĥazael intencis iri kontraŭ Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Tiam Jehoaŝ, reĝo de Judujo, prenis la tutan sanktigitaĵon, kiun sanktigis Jehoŝafat kaj Jehoram kaj Aĥazja, liaj patroj, reĝoj de Judujo, kaj tion, kion li mem sanktigis, kaj la tutan oron, kiu troviĝis en la trezorejoj de la domo de la Eternulo kaj de la reĝa domo, kaj li sendis tion al Ĥazael, reĝo de Sirio, kaj ĉi tiu foriris de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'La cetera historio de Joaŝ, kaj ĉio, kion li faris, estas priskribitaj en la libro de kroniko de la reĝoj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Liaj servantoj leviĝis kaj faris konspiron, kaj mortigis Joaŝon en la domo Milo, sur la vojo al Sila.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Jozaĥar, filo de Ŝimeat, kaj Jehozabad, filo de Ŝomer, liaj servantoj, frapis lin, kaj li mortis. Kaj oni enterigis lin kun liaj patroj en la urbo de David. Kaj anstataŭ li ekreĝis lia filo Amacja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'En la dudek-tria jaro de Joaŝ, filo de Aĥazja, reĝo de Judujo, Jehoaĥaz, filo de Jehu, fariĝis reĝo super Izrael en Samario por la daŭro de dek sep jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Li agadis malbone antaŭ la Eternulo, kaj sekvadis la pekojn de Jerobeam, filo de Nebat, per kiuj li pekigis Izraelon; li ne deturnis sin de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Kaj ekflamis la kolero de la Eternulo kontraŭ la Izraelidoj, kaj Li transdonis ilin en la manon de Ĥazael, reĝo de Sirio, kaj en la manon de Ben-Hadad, filo de Ĥazael, por la tuta tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Sed Jehoaĥaz ekpreĝis al la Eternulo, kaj la Eternulo aŭskultis lin, ĉar Li vidis la suferadon de Izrael, kiel premis ilin la reĝo de Sirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, '(Kaj la Eternulo donis al la Izraelidoj savanton, kaj ili eliris el sub la mano de la Sirianoj, kaj la Izraelidoj loĝis en siaj tendoj kiel antaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Tamen ili ne deturnis sin de la pekoj de la domo de Jerobeam, kiu pekigis Izraelon, sed ili sekvis ilin; ankaŭ la sankta stango restis en Samario.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Al Jehoaĥaz ne restis pli ol kvindek rajdistoj kaj dek ĉaroj kaj dek mil piedirantoj; ĉar la reĝo de Sirio pereigis ilin kaj faris ilin kiel polvo piedpremata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'La cetera historio de Jehoaĥaz, kaj ĉio, kion li faris, kaj lia forto estas priskribitaj en la libro de kroniko de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Kaj Jehoaĥaz ekdormis kun siaj patroj, kaj oni enterigis lin en Samario. Kaj anstataŭ li ekreĝis lia filo Joaŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'En la tridek-sepa jaro de Joaŝ, reĝo de Judujo, Jehoaŝ, filo de Jehoaĥaz, fariĝis reĝo super Izrael en Samario, por la daŭro de dek ses jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Li agadis malbone antaŭ la Eternulo; li ne deturnis sin de ĉiuj pekoj de Jerobeam, filo de Nebat, per kiuj li pekigis Izraelon; ilin li sekvis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'La cetera historio de Joaŝ, kaj ĉio, kion li faris, kaj lia forto, kaj kiel li militis kontraŭ Amacja, reĝo de Judujo, estas priskribitaj en la libro de kroniko de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Kaj Joaŝ ekdormis kun siaj patroj, kaj Jerobeam eksidis sur lia trono. Kaj oni enterigis Joaŝon en Samario kun la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Eliŝa malsaniĝis per sia malsano, de kiu li estis mortonta. Venis al li Joaŝ, reĝo de Izrael, kaj ploris super li, kaj diris: Mia patro, mia patro, ĉaro de Izrael kaj liaj rajdistoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Kaj Eliŝa diris al li: Prenu pafarkon kaj sagojn. Kaj li prenis al si pafarkon kaj sagojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Kaj li diris al la reĝo de Izrael: Metu vian manon sur la pafarkon. Kaj li metis sian manon. Kaj Eliŝa metis siajn manojn sur la manojn de la reĝo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'kaj diris: Malfermu la fenestron orienten. Li malfermis. Kaj Eliŝa diris: Pafu. Li pafis. Kaj li diris: Sago de savo de la Eternulo kaj sago de savo kontraŭ Sirio, kaj vi venkobatos la Sirianojn en Afek, ĝis vi ilin tute pereigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Kaj li diris: Prenu la sagojn. Li prenis. Kaj li diris al la reĝo de Izrael: Frapu sur la teron. Li frapis tri fojojn kaj haltis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Tiam ekkoleris kontraŭ li la homo de Dio, kaj diris: Vi devis frapi kvin aŭ ses fojojn, tiam vi venkobatus la Sirianojn ĝis plena pereo; sed nun vi nur tri fojojn batos la Sirianojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Eliŝa mortis, kaj oni enterigis lin. Kaj militistaroj de Moab venis en la landon en la komenco de la jaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Okazis, ke, enterigante iun homon, oni ekvidis la militistaron, kaj oni ĵetis la homon en la tombon de Eliŝa. Kiam tiu homo tien falis kaj kuntuŝiĝis kun la ostoj de Eliŝa, li reviviĝis kaj stariĝis sur siaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Ĥazael, reĝo de Sirio, premis la Izraelidojn dum la tuta vivo de Jehoaĥaz.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Sed la Eternulo favorkoris ilin kaj kompatis ilin kaj turnis Sin al ili pro Sia interligo kun Abraham, Isaak, kaj Jakob, kaj Li ne volis ekstermi ilin kaj ankoraŭ ne forĵetis ilin de antaŭ Sia vizaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Ĥazael, reĝo de Sirio, mortis, kaj anstataŭ li ekreĝis lia filo Ben-Hadad.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Kaj Jehoaŝ, filo de Jehoaĥaz, prenis returne el la mano de Ben-Hadad, filo de Ĥazael, la urbojn, kiujn li milite prenis el la mano de lia patro Jehoaĥaz. Tri fojojn Joaŝ venkobatis lin kaj reprenis la urbojn de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'En la dua jaro de Joaŝ, filo de Joaĥaz, reĝo de Izrael, Amacja, filo de Joaŝ, reĝo de Judujo, fariĝis reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Li havis la aĝon de dudek kvin jaroj, kiam li fariĝis reĝo, kaj dudek naŭ jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Jehoadan, el Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Li agadis bone antaŭ la Eternulo, tamen ne kiel lia patro David. Li agadis tiel, kiel agadis lia patro Joaŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'La altaĵoj ne estis senfunkciigitaj; la popolo ĉiam ankoraŭ oferadis kaj incensadis sur la altaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Kiam la reĝeco fortiĝis en lia mano, li mortigis siajn servantojn, kiuj mortigis la reĝon, lian patron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Sed la infanojn de la mortigintoj li ne mortigis, kiel estas skribite en la libro de instruo de Moseo, kion ordonis la Eternulo, nome: Oni ne mortigu patrojn pro la infanoj, kaj oni ne mortigu infanojn pro la patroj, sed ĉiu povas esti mortigata nur pro sia peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Li venkobatis la Edomidojn en la Valo de Salo, dek milojn, kaj prenis per milito Selan kaj donis al ĝi la nomon Jokteel ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'En tiu tempo Amacja sendis senditojn al Jehoaŝ, filo de Jehoaĥaz, filo de Jehu, reĝo de Izrael, por diri: Venu, ni komparu niajn fortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Tiam Jehoaŝ, reĝo de Izrael, sendis al Amacja, reĝo de Judujo, por diri: La prunelo sur Lebanon sendis al la cedro sur Lebanon, por diri: Donu vian filinon al mia filo kiel edzinon. Sed preteriris sovaĝa besto de Lebanon kaj dispremis per la piedoj la prunelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Vi venkobatis la Edomidojn, kaj via koro fieriĝis. Tenu vian gloron kaj sidu hejme. Kial vi volas entrepreni aferon malfeliĉan, ke vi falu kaj kun vi ankaŭ Judujo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Sed Amacja ne obeis. Kaj eliris Jehoaŝ, reĝo de Izrael, kaj ili komparis siajn fortojn, li kaj Amacja, reĝo de Judujo, en Bet-Ŝemeŝ, kiu estas en Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Kaj la Judoj estis venkobatitaj de la Izraelidoj, kaj ili diskuris ĉiu al sia tendo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Kaj Amacjan, reĝon de Judujo, filon de Jehoaŝ, filo de Aĥazja, kaptis Jehoaŝ, reĝo de Izrael, en Bet-Ŝemeŝ; kaj li venis Jerusalemon, kaj detruis la muregon de Jerusalem, de la Pordego de Efraim ĝis la Pordego Angula, sur la spaco de kvarcent ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'Kaj li prenis la tutan oron kaj arĝenton, kaj ĉiujn vazojn, kiuj troviĝis en la domo de la Eternulo kaj en la trezorejoj de la reĝa domo, kaj ankaŭ garantiulojn, kaj li reiris en Samarion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'La cetera historio de Jehoaŝ, kion li faris, kaj lia forto, kaj kiel li militis kontraŭ Amacja, reĝo de Judujo, ĉio estas priskribita en la libro de kroniko de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Kaj Jehoaŝ ekdormis kun siaj patroj, kaj oni enterigis lin en Samario kun la reĝoj de Izrael. Kaj anstataŭ li ekreĝis lia filo Jerobeam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Kaj Amacja, filo de Joaŝ, reĝo de Judujo, vivis post la morto de Jehoaŝ, filo de Jehoaĥaz, reĝo de Izrael, ankoraŭ dek kvin jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'La cetera historio de Amacja estas priskribita en la libro de kroniko de la reĝoj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Oni faris kontraŭ li konspiron en Jerusalem, kaj li forkuris en Laĥiŝon. Sed oni sendis post li en Laĥiŝon, kaj tie oni lin mortigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Kaj oni venigis lin sur ĉevaloj, kaj oni enterigis lin kun liaj patroj en la urbo de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Kaj la tuta Juda popolo prenis Azarjan, kiu havis la aĝon de dek ses jaroj, kaj faris lin reĝo anstataŭ lia patro Amacja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Li prikonstruis Elaton kaj revenigis ĝin al Judujo, post kiam la reĝo ekdormis kun siaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'En la dek-kvina jaro de Amacja, filo de Joaŝ, reĝo de Judujo, ekreĝis Jerobeam, filo de Joaŝ, reĝo de Izrael, en Samario, kaj li reĝis kvardek unu jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Li faradis malbonon antaŭ la okuloj de la Eternulo, ne deturnis sin de ĉiuj pekoj de Jerobeam, filo de Nebat, per kiuj li pekigis Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Li restarigis la limojn de Izrael de Ĥamat ĝis la maro de la dezerto, konforme al la vorto de la Eternulo, Dio de Izrael, kiun Li diris per Sia servanto Jona, filo de Amitaj, la profeto el Gat-Ĥefer.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Ĉar la Eternulo vidis, ke la suferado de Izrael estas tre mizera; restis nek sklavo nek liberulo, kaj estis neniu helpanto por Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'La Eternulo ne decidis ekstermi la nomon de Izrael el sub la ĉielo, kaj Li savis ilin per Jerobeam, filo de Joaŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'La cetera historio de Jerobeam, kaj ĉio, kion li faris, kaj lia forto, kaj kiel li militis, kaj kiel li revenigis al Izrael Damaskon kaj Ĥamaton de Judujo, ĉio estas priskribita en la libro de kroniko de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Kaj Jerobeam ekdormis kun siaj patroj, kun la reĝoj de Izrael. Kaj anstataŭ li ekreĝis lia filo Zeĥarja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'En la dudek-sepa jaro de Jerobeam, reĝo de Izrael, ekreĝis Azarja, filo de Amacja, reĝo de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Li havis la aĝon de dek ses jaroj, kiam li fariĝis reĝo, kaj kvindek du jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Jeĥolja, el Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Li agadis bone antaŭ la Eternulo, tiel same, kiel agadis lia patro Amacja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Nur la altaĵoj ne estis senfunkciigitaj; la popolo ĉiam ankoraŭ oferadis kaj incensadis sur la altaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'La Eternulo frapis la reĝon, kaj li fariĝis lepra ĝis la tago de sia morto, kaj li loĝis en izolita domo. Kaj Jotam, filo de la reĝo, estis ĉefo de la domo kaj regis la popolon de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'La cetera historio de Azarja, kaj ĉio, kion li faris, estas priskribitaj en la libro de kroniko de la reĝoj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Kaj Azarja ekdormis kun siaj patroj, kaj oni enterigis lin kun liaj patroj en la urbo de David. Kaj anstataŭ li ekreĝis lia filo Jotam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'En la tridek-oka jaro de Azarja, reĝo de Judujo, Zeĥarja, filo de Jerobeam, fariĝis reĝo super Izrael en Samario, kaj li reĝis ses monatojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Li faradis malbonon antaŭ la okuloj de la Eternulo, kiel faradis liaj patroj; li ne deturnis sin de la pekoj de Jerobeam, filo de Nebat, per kiuj li pekigis Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Kontraŭ li faris konspiron Ŝalum, filo de Jabeŝ, kaj frapis lin antaŭ la popolo kaj mortigis lin kaj ekreĝis anstataŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'La cetera historio de Zeĥarja estas priskribita en la libro de kroniko de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Tio estas la vorto de la Eternulo, kiun Li diris al Jehu, nome: Viaj filoj sidos sur la trono de Izrael ĝis la kvara generacio. Tiel fariĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Ŝalum, filo de Jabeŝ, fariĝis reĝo en la tridek-naŭa jaro de Uzija, reĝo de Judujo. Kaj li reĝis unu monaton en Samario.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Kaj iris Menaĥem, filo de Gadi, el Tirca, kaj venis en Samarion kaj frapis Ŝalumon, filon de Jabeŝ, en Samario, kaj mortigis lin kaj ekreĝis anstataŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'La cetera historio de Ŝalum, kaj lia konspiro, kiun li faris, estas priskribitaj en la libro de kroniko de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Tiam Menaĥem frapis Tifsaĥon, kaj ĉion, kio estis en ĝi, kaj ĝian regionon, komencante de Tirca, pro tio, ke ĝi ne malfermis al li la pordegon. Kaj li mortigis ĉiujn ĝiajn gravedulinojn, disfendinte ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'En la tridek-naŭa jaro de Azarja, reĝo de Judujo, Menaĥem, filo de Gadi, fariĝis reĝo super Izrael, kaj li reĝis dek jarojn en Samario.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Li faradis malbonon antaŭ la okuloj de la Eternulo; dum sia tuta vivo li ne deturnis sin de ĉiuj pekoj de Jerobeam, filo de Nebat, per kiuj li pekigis Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Pul, reĝo de Asirio, venis en la landon. Kaj Menaĥem donis al Pul mil kikarojn da arĝento, por ke li helpu lin, por fortikigi la reĝecon en lia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Kaj Menaĥem impostigis la arĝenton sur Izrael, sur ĉiuj riĉuloj, sur ĉiu po kvindek sikloj da arĝento, por doni al la reĝo de Asirio. Kaj la reĝo de Asirio iris returne kaj ne restis tie en la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'La cetera historio de Menaĥem, kaj ĉio, kion li faris, estas priskribitaj en la libro de kroniko de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Menaĥem ekdormis kun siaj patroj; kaj anstataŭ li ekreĝis lia filo Pekaĥja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'En la kvindeka jaro de Azarja, reĝo de Judujo, Pekaĥja, filo de Menaĥem, fariĝis reĝo super Izrael en Samario, kaj li reĝis du jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Li faradis malbonon antaŭ la okuloj de la Eternulo; li ne deturnis sin de la pekoj de Jerobeam, filo de Nebat, per kiuj li pekigis Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Kaj faris kontraŭ li konspiron Pekaĥ, filo de Remalja, lia altrangulo, kaj frapis lin en Samario, en la salono de la reĝa domo, kune kun Argob kaj Arje, kaj kun li estis kvindek viroj el la Gileadanoj. Kaj li mortigis lin kaj ekreĝis anstataŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'La cetera historio de Pekaĥja, kaj ĉio, kion li faris, estas priskribitaj en la libro de kroniko de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'En la kvindek-dua jaro de Azarja, reĝo de Judujo, Pekaĥ, filo de Remalja, fariĝis reĝo super Izrael en Samario, kaj li reĝis dudek jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Li faradis malbonon antaŭ la okuloj de la Eternulo; li ne deturnis sin de la pekoj de Jerobeam, filo de Nebat, per kiuj li pekigis Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'En la tempo de Pekaĥ, reĝo de Izrael, venis Tiglat-Pileser, reĝo de Asirio, kaj prenis Ijonon, Abel-Bet-Maaĥan, Janoaĥon, Kedeŝon, Ĥacoron, Gileadon, Galileon, la tutan landon de Naftali; kaj forkondukis ilin en Asirion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Hoŝea, filo de Ela, faris konspiron kontraŭ Pekaĥ, filo de Remalja, kaj frapis lin kaj mortigis lin, kaj ekreĝis anstataŭ li en la dudeka jaro de Jotam, filo de Uzija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'La cetera historio de Pekaĥ, kaj ĉio, kion li faris, estas priskribitaj en la libro de kroniko de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'En la dua jaro de Pekaĥ, filo de Remalja, reĝo de Izrael, ekreĝis Jotam, filo de Uzija, reĝo de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Li havis la aĝon de dudek kvin jaroj, kiam li fariĝis reĝo, kaj dek ses jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Jeruŝa, filino de Cadok.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Li agadis bone antaŭ la Eternulo; li agadis tiel same, kiel agadis lia patro Uzija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Sed la altaĵoj ne estis senfunkciigitaj; la popolo ĉiam ankoraŭ oferadis kaj incensadis sur la altaĵoj. Li konstruis la supran pordegon ĉe la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'La cetera historio de Jotam, kaj ĉio, kion li faris, estas priskribitaj en la libro de kroniko de la reĝoj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'En tiu tempo la Eternulo komencis sendadi sur Judujon Recinon, reĝon de Sirio, kaj Pekaĥon, filon de Remalja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Kaj Jotam ekdormis kun siaj patroj, kaj oni enterigis lin kun liaj patroj en la urbo de lia patro David. Kaj anstataŭ li ekreĝis lia filo Aĥaz.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'En la dek-sepa jaro de Pekaĥ, filo de Remalja, ekreĝis Aĥaz, filo de Jotam, reĝo de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'La aĝon de dudek jaroj havis Aĥaz, kiam li fariĝis reĝo, kaj dek ses jarojn li reĝis en Jerusalem; kaj li ne agadis bone antaŭ la Eternulo, lia Dio, kiel lia patro David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Li iradis laŭ la vojo de la reĝoj de Izrael, kaj eĉ sian filon li trairigis tra fajro, simile al la abomenindaĵoj de la nacioj, kiujn la Eternulo forpelis de antaŭ la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Li oferadis kaj incensadis sur la altaĵoj kaj sur la montetoj kaj sub ĉiu verda arbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Tiam Recin, reĝo de Sirio, kaj Pekaĥ, filo de Remalja, reĝo de Izrael, iris milite kontraŭ Jerusalemon; ili sieĝis Aĥazon, sed ne povis venkopreni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'En tiu tempo Recin, reĝo de Sirio, revenigis Elaton al Sirio kaj elpelis la Judojn el Elat; la Sirianoj eniris Elaton kaj ekloĝis tie ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Aĥaz sendis senditojn al Tiglat-Pileser, reĝo de Asirio, por diri: Mi estas via servanto kaj via filo; venu, kaj savu min kontraŭ la mano de la reĝo de Sirio kaj kontraŭ la mano de la reĝo de Izrael, kiuj leviĝis kontraŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Kaj Aĥaz prenis la arĝenton kaj oron, kiuj troviĝis en la domo de la Eternulo kaj en la trezorejoj de la reĝa domo, kaj sendis tion donace al la reĝo de Asirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Kaj la reĝo de Asirio obeis lin, kaj la reĝo de Asirio iris kontraŭ Damaskon kaj prenis ĝin kaj transkondukis ĝiajn loĝantojn en Kiron, kaj Recinon li mortigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'La reĝo Aĥaz iris Damaskon renkonte al Tiglat-Pileser, reĝo de Asirio, kaj li vidis la altaron, kiu estis en Damasko; kaj la reĝo Aĥaz sendis al la pastro Urija la bildon de la altaro kaj la desegnon de ĝia tuta konstruo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Kaj la pastro Urija konstruis altaron. Konforme al ĉio, kion la reĝo Aĥaz sendis el Damasko, la pastro Urija aranĝis, antaŭ ol la reĝo Aĥaz venis el Damasko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Kiam la reĝo venis el Damasko, la reĝo ekvidis la altaron, kaj la reĝo aliris al la altaro kaj faris sur ĝi oferon');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'kaj bruligis sian bruloferon kaj sian farunoferon kaj verŝis sian verŝoferon kaj aspergis la altaron per la sango de sia pacofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Kaj la kupran altaron, kiu staris antaŭ la Eternulo, li forŝovis de la antaŭa flanko de la domo, de la loko inter la altaro kaj la domo de la Eternulo, kaj starigis ĝin flanke de la altaro norde.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Kaj la reĝo Aĥaz ordonis al la pastro Urija, dirante: Sur la granda altaro bruligu la matenan bruloferon, la vesperan farunoferon, la bruloferon de la reĝo kaj lian farunoferon, la bruloferon de la tuta popolo, ilian farunoferon kaj ilian verŝoferon, kaj per la tuta sango de brulofero kaj per la tuta sango de buĉofero aspergu ĝin; sed la kupra altaro restu, ĝis mi pripensos pri ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Kaj la pastro Urija faris ĉion konforme al tio, kiel ordonis la reĝo Aĥaz.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'La reĝo Aĥaz derompis la muretojn de la bazaĵoj kaj deprenis de ili la lavujon, kaj la maron li deprenis de la kupraj bovoj, kiuj estis sub ĝi, kaj metis ĝin sur ŝtonan plankon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Kaj la kovritan sabatan halon, kiun oni konstruis ĉe la domo, kaj la eksteran enirejon de la reĝo li turnis al la domo de la Eternulo, pro la reĝo de Asirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'La cetera historio de Aĥaz, kion li faris, estas priskribita en la libro de kroniko de la reĝoj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Kaj Aĥaz ekdormis kun siaj patroj, kaj oni enterigis lin kun liaj patroj en la urbo de David. Kaj anstataŭ li ekreĝis lia filo Ĥizkija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'En la dek-dua jaro de Aĥaz, reĝo de Judujo, Hoŝea, filo de Ela, fariĝis reĝo en Samario super Izrael, kaj li reĝis naŭ jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Li faradis malbonon antaŭ la Eternulo, sed ne tiel, kiel la reĝoj de Izrael, kiuj estis antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Kontraŭ lin iris Ŝalmaneser, reĝo de Asirio, kaj Hoŝea fariĝis lia servanto kaj donadis al li tributon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Kiam la reĝo de Asirio rimarkis ĉe Hoŝea perfidon, ĉar li sendis senditojn al So, reĝo de Egiptujo, kaj ne liveris tributon al la reĝo de Asirio, kiel ĉiujare, tiam la reĝo de Asirio kaptis lin kaj metis lin en malliberejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Kaj la reĝo de Asirio iris kontraŭ la tutan landon, venis al Samario, kaj sieĝis ĝin dum tri jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'En la naŭa jaro de Hoŝea la reĝo de Asirio venkoprenis Samarion, kaj transkondukis la Izraelidojn en Asirion, kaj loĝigis ilin en Ĥalaĥ, kaj en Ĥabor, ĉe la rivero Gozan, kaj en la urboj de la Medoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Ĉar la Izraelidoj pekis kontraŭ la Eternulo, ilia Dio, kiu elkondukis ilin el la lando Egipta, el sub la mano de Faraono, reĝo de Egiptujo, kaj ili adoradis aliajn diojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'kaj agadis laŭ la leĝoj de la nacioj, kiujn la Eternulo forpelis antaŭ la Izraelidoj, kaj laŭ tio, kiel agadis la reĝoj de Izrael;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'kaj la Izraelidoj blasfemadis per malkonvenaj vortoj kontraŭ la Eternulo, ilia Dio, kaj aranĝis al si altaĵojn en ĉiuj siaj urboj, komencante de la gardostara turo ĝis la fortikigita urbo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'kaj ili starigis al si statuojn kaj sanktajn stangojn sur ĉiu alta monteto kaj sub ĉiu verda arbo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'kaj ili incensadis tie sur ĉiuj altaĵoj, kiel la nacioj, kiujn la Eternulo forpelis antaŭ ili, kaj faradis malbonaĵojn, por inciti la Eternulon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'kaj ili servadis al la idoloj, pri kiuj la Eternulo diris al ili: Ne faru tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Kaj la Eternulo avertis la Izraelidojn kaj la Judojn per ĉiuj Siaj profetoj kaj viziistoj, dirante: Returnu vin de viaj malbonaj vojoj, kaj plenumu Miajn ordonojn kaj leĝojn, laŭ la tuta instruo, kiun Mi donis al viaj patroj kaj kiun Mi sendis al vi per Miaj servantoj, la profetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Sed ili ne aŭskultis, kaj ili malmoligis sian nukon simile al la nuko de iliaj patroj, kiuj ne fidis la Eternulon, sian Dion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'kaj ili malestimis Liajn leĝojn, kaj Lian interligon, kiun Li faris kun iliaj patroj, kaj Liajn avertojn, per kiuj Li avertis ilin, kaj ili sekvis vantaĵon kaj vantiĝis, kaj sekvis la naciojn, kiuj estis ĉirkaŭ ili kaj pri kiuj la Eternulo ordonis al ili, ke ili ne imitu ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'kaj ili forlasis ĉiujn ordonojn de la Eternulo, ilia Dio, kaj faris al si fandaĵon de du bovidoj kaj faris sanktan stangon kaj adorkliniĝis antaŭ la tuta armeo de la ĉielo kaj servis al Baal;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'kaj ili trairigadis siajn filojn kaj siajn filinojn tra fajro kaj sorĉadis kaj aŭguradis kaj fordonis sin al farado de malbono antaŭ la okuloj de la Eternulo, por inciti Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Tial la Eternulo forte ekkoleris kontraŭ la Izraelidoj, kaj forpuŝis ilin de antaŭ Sia vizaĝo. Restis nur sole la tribo de Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Sed ankaŭ la Judoj ne obeis la ordonojn de la Eternulo, sia Dio, kaj ili sekvis la morojn de la Izraelidoj, kiujn tiuj starigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Kaj abomenis la Eternulo la tutan idaron de Izrael kaj humiligis ilin kaj transdonis ilin en la manon de rabantoj, ĝis Li tute forĵetis ilin de antaŭ Si.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Ĉar la Izraelidoj defalis de la domo de David, kaj prenis al si kiel reĝon Jerobeamon, filon de Nebat; kaj Jerobeam deturnis Izraelon de la Eternulo kaj entiris ilin en grandan pekon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'Kaj la Izraelidoj iradis en ĉiuj pekoj de Jerobeam, kiujn li faris, ne deturnante sin de ili,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'ĝis la Eternulo forpuŝis Izraelon de antaŭ Sia vizaĝo, kiel Li diris per ĉiuj Siaj servantoj, la profetoj; kaj Izrael estas elpelita el sia lando en Asirion ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Kaj la reĝo de Asirio transkondukis homojn el Babel, Kut, Ava, Ĥamat, kaj Sefarvaim, kaj ekloĝigis ilin en la urboj de Samario anstataŭ la Izraelidoj. Kaj ili ekposedis Samarion kaj ekloĝis en ĝiaj urboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'Sed ĉar en la komenco de sia loĝado tie ili ne timis la Eternulon, la Eternulo sendis kontraŭ ilin leonojn, kiuj faris inter ili mortigadon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Oni raportis al la reĝo de Asirio, dirante: La popoloj, kiujn vi transkondukis kaj loĝigis en la urboj de Samario, ne konas la leĝojn de la Dio de la lando, kaj tial Li sendis kontraŭ ilin leonojn, kiuj nun mortigas ilin, ĉar ili ne konas la leĝojn de la Dio de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Tiam la reĝo de Asirio ordonis, dirante: Venigu tien unu el la pastroj, kiujn vi elkondukis el tie; oni iru kaj loĝu tie, kaj li instruu al ili la leĝojn de la Dio de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Kaj venis unu el la pastroj, kiuj estis forkondukitaj el Samario, kaj li ekloĝis en Bet-El, kaj instruis ilin, kiel ili devas timi la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Tamen ĉiu popolo faris ankaŭ siajn diojn, kaj starigis ilin en la domoj de la altaĵoj, kiujn konstruis la Samarianoj, ĉiu popolo en siaj urboj, en kiuj ili loĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'La Babelanoj faris Sukot-Benoton, la Kutanoj faris Nergalon, la Ĥamatanoj faris Aŝiman;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'la Avaanoj faris Nibĥazon kaj Tartakon; kaj la Sefarvaimanoj bruligadis siajn infanojn per fajro al Adrameleĥ kaj Anameleĥ, la dioj de Sefarvaim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Ili timis ankaŭ la Eternulon, kaj starigis al si el sia mezo pastrojn por la altaĵoj, kaj tiuj servadis por ili en la domoj de la altaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'La Eternulon ili timis, kaj al siaj dioj ili servis, laŭ la moro de tiuj popoloj, el kiuj oni transkondukis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Ĝis la nuna tempo ili agas laŭ la moroj antikvaj: ili ne timas la Eternulon, kaj ne agas laŭ siaj leĝoj kaj siaj moroj, nek laŭ la instruo kaj ordono, kiujn la Eternulo donis al la filoj de Jakob, al kiu Li donis la nomon Izrael,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'kun kiuj la Eternulo faris interligon kaj ordonis al ili, dirante: Ne timu aliajn diojn, ne adorkliniĝu antaŭ ili, ne servu al ili, kaj ne faru al ili oferojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'sed nur la Eternulon, kiu elkondukis vin el la lando Egipta per granda forto kaj etendita brako, Lin timu, antaŭ Li adorkliniĝu, kaj al Li faru oferojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'kaj la leĝojn kaj la decidojn kaj la instruon kaj la ordonojn, kiujn Li skribis por vi, observu, ke vi plenumu ilin ĉiam, kaj ne timu aliajn diojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'kaj la interligon, kiun Mi faris kun vi, ne forgesu, kaj ne timu aliajn diojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'sed nur la Eternulon, vian Dion, timu, kaj Li savos vin el la mano de ĉiuj viaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Tamen ili ne obeis, sed agis laŭ siaj moroj antaŭaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Tiuj popoloj timis la Eternulon, sed ankaŭ al siaj idoloj ili servis, ankaŭ iliaj infanoj kaj la infanoj de iliaj infanoj; kiel agis iliaj patroj, tiel ili agas ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'En la tria jaro de Hoŝea, filo de Ela, reĝo de Izrael, ekreĝis Ĥizkija, filo de Aĥaz, reĝo de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Li havis la aĝon de dudek kvin jaroj, kiam li fariĝis reĝo, kaj dudek naŭ jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Abi, filino de Zeĥarja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Li agadis bone antaŭ la Eternulo, tiel same, kiel agadis lia patro David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Li forigis la altaĵojn, rompis la statuojn, dehakis la sanktajn stangojn, kaj disbatis la kupran serpenton, kiun faris Moseo; ĉar ĝis tiu tempo la Izraelidoj incensadis al ĝi, kaj oni nomis ĝin Neĥuŝtan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'La Eternulon, Dion de Izrael, li fidis; kaj simila al li ne ekzistis inter ĉiuj reĝoj de Judujo post li, nek inter tiuj, kiuj estis antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Li forte tenis sin al la Eternulo, ne deturnis sin de Li, kaj li observadis Liajn ordonojn, kiujn la Eternulo donis al Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Kaj la Eternulo estis kun li; ĉie, kien li iris, li agis prudente. Li defalis de la reĝo de Asirio kaj ĉesis servi al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Li venkobatis la Filiŝtojn ĝis Gaza kaj ĝia regiono, de la gardostara turo ĝis la fortikigita urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'En la kvara jaro de la reĝo Ĥizkija, tio estas en la sepa jaro de Hoŝea, filo de Ela, reĝo de Izrael, iris Ŝalmaneser, reĝo de Asirio, kontraŭ Samarion kaj eksieĝis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'Kaj li venkoprenis ĝin post tri jaroj; en la sesa jaro de Ĥizkija, tio estas en la naŭa jaro de Hoŝea, reĝo de Izrael, Samario estis prenita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Kaj la reĝo de Asirio transkondukis la Izraelidojn en Asirion, kaj loĝigis ilin en Ĥalaĥ, kaj en Ĥabor, ĉe la rivero Gozan, kaj en la urboj de la Medoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'pro tio, ke ili ne obeis la voĉon de la Eternulo, sia Dio, kaj malobeis Lian interligon, ĉion, kion ordonis Moseo, servanto de la Eternulo, ili ne obeis kaj ne plenumis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'En la dek-kvara jaro de la reĝo Ĥizkija eliris Sanĥerib, reĝo de Asirio, kontraŭ ĉiujn fortikigitajn urbojn de Judujo, kaj venkoprenis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Tiam Ĥizkija, reĝo de Judujo, sendis al la reĝo de Asirio en Laĥiŝon, por diri: Mi pekis; returnu vin de mi; kion vi metos sur min, tion mi plenumos. Kaj la reĝo de Asirio metis sur Ĥizkijan, reĝon de Judujo, tributon de tricent kikaroj da arĝento kaj tridek kikaroj da oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Kaj Ĥizkija fordonis la tutan arĝenton, kiu troviĝis en la domo de la Eternulo kaj en la trezorejoj de la reĝa domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'En tiu tempo Ĥizkija dehakis la pordojn de la templo de la Eternulo, kaj la kolonojn, kiujn Ĥizkija, reĝo de Judujo, estis teginta, kaj donis ilin al la reĝo de Asirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'La reĝo de Asirio sendis Tartanon kaj Rab-Sarison kaj Rabŝaken el Laĥiŝ al la reĝo Ĥizkija kun granda militistaro al Jerusalem. Ili iris kaj venis en Jerusalemon. Kiam ili venis, ili stariĝis ĉe la akvotubo de la supra lageto, kiu estas ĉe la vojo de la kampo de fulistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Ili vokis la reĝon. Kaj eliris al ili Eljakim, filo de Ĥilkija, la palacestro, kaj Ŝebna, la skribisto, kaj Joaĥ, filo de Asaf, la kronikisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Kaj Rabŝake diris al ili: Diru al Ĥizkija: Tiele diras la granda reĝo, la reĝo de Asirio: Kio estas la fido, kiun vi fidas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Vi diris nur buŝan babiladon; por milito oni bezonas konsilon kaj forton. Nun kiun vi fidas, ke vi ribelis kontraŭ mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Jen vi fidas la apogon de Egiptujo, tiu kano rompita, kiu, se iu sin apogas sur ĝi, eniras en lian manon kaj trapikas ĝin. Tia estas Faraono, reĝo de Egiptujo, por ĉiuj, kiuj fidas lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Eble vi diros al mi: La Eternulon, nian Dion, ni fidas? sed Li estas ja Tiu, kies altaĵojn kaj altarojn Ĥizkija forigis, dirante al Judujo kaj Jerusalem: Antaŭ ĉi tiu altaro adorkliniĝu en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Nun provu konkuri kun mia sinjoro, la reĝo de Asirio; mi donos al vi du mil ĉevalojn-ĉu vi povas trovi rajdantojn por ili?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Kiel vi povas forigi estron, unu el la plej malgrandaj servantoj de mia sinjoro, kaj fidi Egiptujon pro la ĉaroj kaj rajdistoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Cetere, ĉu sen la volo de la Eternulo mi iris kontraŭ ĉi tiun lokon, por ruinigi ĝin? La Eternulo diris al mi: Iru kontraŭ ĉi tiun landon kaj ruinigu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Tiam Eljakim, filo de Ĥilkija, kaj Ŝebna kaj Joaĥ diris al Rabŝake: Volu paroli al viaj sklavoj en la lingvo Siria, ĉar ni komprenas; sed ne parolu kun ni Jude antaŭ la oreloj de la popolo, kiu estas sur la murego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Sed Rabŝake diris al ili: Ĉu al via sinjoro kaj al vi sendis min mia sinjoro, por diri tiujn vortojn? ĉu ne al la homoj, kiuj sidas sur la murego, por manĝi sian ekskrementon kaj trinki sian urinon kune kun vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Kaj Rabŝake stariĝis, kaj ekkriis per laŭta voĉo Jude, kaj li ekparolis, dirante: Aŭskultu la vortojn de la granda reĝo, la reĝo de Asirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Tiele diras la reĝo: Ĥizkija ne forlogu vin, ĉar li ne povos savi vin el lia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Kaj Ĥizkija ne fidigu vin per la Eternulo, dirante: La Eternulo certe nin savos, kaj ĉi tiu urbo ne estos transdonita en la manojn de la reĝo de Asirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Ne aŭskultu Ĥizkijan; ĉar tiele diras la reĝo de Asirio: Faru kun mi pacon kaj eliru al mi, kaj manĝu ĉiu el sia vinberĝardeno kaj ĉiu de sia figarbo kaj trinku ĉiu la akvon el sia puto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'ĝis mi venos kaj prenos vin en landon similan al via lando, en landon de greno kaj mosto, en landon de pano kaj vinberĝardenoj, en landon de olivoj kaj de mielo, kaj vi vivos kaj ne mortos. Kaj ne aŭskultu Ĥizkijan, kiam li forlogas vin per la vortoj: La Eternulo nin savos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Ĉu la dioj de la nacioj savis ĉiu sian landon el la manoj de la reĝo de Asirio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Kie estas la dioj de Ĥamat kaj de Arpad? kie estas la dioj de Sefarvaim, de Hena kaj Iva? ĉu ili savis Samarion el miaj manoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Kiu el ĉiuj dioj de tiuj landoj savis sian landon el miaj manoj, ke la Eternulo savu Jerusalemon el miaj manoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Kaj la popolo silentis kaj nenion respondis al li; ĉar estis ordono de la reĝo: Ne respondu al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Kaj Eljakim, filo de Ĥilkija, la palacestro, kaj Ŝebna, la skribisto, kaj Joaĥ, filo de Asaf, la kronikisto, venis al Ĥizkija en disŝiritaj vestoj, kaj raportis al li la vortojn de Rabŝake.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Kiam la reĝo Ĥizkija tion aŭdis, li disŝiris siajn vestojn kaj ĉirkaŭkovris sin per sako, kaj iris en la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Kaj li sendis Eljakimon, la palacestron, kaj Ŝebnan, la skribiston, kaj la plejaĝulojn el la pastroj, ĉirkaŭkovritajn per sakoj, al la profeto Jesaja, filo de Amoc.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Kaj ili diris al li: Tiele diras Ĥizkija: Ĉi tiu tago estas tago de malfeliĉo, de puno, kaj de malhonoro; ĉar infanoj atingis la aperturon de la utero, sed forestas forto por naski.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Eble aŭdos la Eternulo, via Dio, ĉiujn vortojn de Rabŝake, kiun sendis la reĝo de Asirio, lia sinjoro, por blasfemi la vivantan Dion, kaj punos pro la vortoj, kiujn aŭdis la Eternulo, via Dio. Levu do preĝon por la restintoj, kiuj ankoraŭ ekzistas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Kaj la servantoj de la reĝo Ĥizkija venis al Jesaja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'Kaj Jesaja diris al ili: Tiele parolu al via sinjoro: Tiele diras la Eternulo: Ne timu la vortojn, kiujn vi aŭdis kaj per kiuj blasfemis Min la servantoj de la reĝo de Asirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Jen Mi metos en lin spiriton, ke, aŭdinte sciigon, li reiros en sian landon, kaj Mi faligos lin per glavo en lia lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Kaj Rabŝake revenis, kaj trovis la reĝon de Asirio militanta kontraŭ Libna; ĉar li aŭdis, ke li foriris de Laĥiŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Kaj venis sciigo pri Tirhaka, reĝo de Etiopujo, nome: Li eliris, por militi kontraŭ vi. Tiam li denove sendis senditojn al Ĥizkija kun la sekvanta komisio:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'Tiele diru al Ĥizkija, reĝo de Judujo: Ne forlogu vin via Dio, kiun vi fidas, dirante: Jerusalem ne estos transdonita en la manojn de la reĝo de Asirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Vi aŭdis ja, kion faris la reĝoj de Asirio al ĉiuj landoj, ruinigante ilin; ĉu vi do saviĝos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Ĉu ilin savis la dioj de la nacioj, kiujn ekstermis miaj patroj, la naciojn de Gozan kaj Ĥaran kaj Recef kaj la filojn de Eden en Telasar?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Kie estas la reĝo de Ĥamat kaj la reĝo de Arpad kaj la reĝo de la urbo Sefarvaim, de Hena kaj Iva?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Ĥizkija prenis la leteron el la manoj de la senditoj kaj legis ĝin, kaj li iris en la domon de la Eternulo, kaj Ĥizkija disvolvis ĝin antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Kaj Ĥizkija ekpreĝis al la Eternulo, kaj diris: Ho Eternulo, Dio de Izrael, sidanta sur la keruboj! Vi estas la sola Dio super ĉiuj regnoj de la tero, Vi kreis la ĉielon kaj la teron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'klinu, ho Eternulo, Vian orelon, kaj aŭskultu; malfermu, ho Eternulo, Viajn okulojn, kaj rigardu; kaj aŭdu la vortojn de Sanĥerib, kiujn li sendis, por insulti la Dion vivantan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Estas vero, ho Eternulo, la reĝoj de Asirio ruinigis la popolojn kaj ilian teron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'kaj ĵetis iliajn diojn en fajron; ĉar tio estis ne dioj, sed faritaĵoj de homaj manoj, ligno kaj ŝtono; ili ekstermis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Sed nun, ho Eternulo, nia Dio, savu nin do kontraŭ liaj manoj, por ke ĉiuj regnoj de la tero eksciu, ke Vi, ho Eternulo, estas sola.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Kaj Jesaja, filo de Amoc, sendis al Ĥizkija, por diri: Tiele diras la Eternulo, Dio de Izrael: Tion, kion vi preĝis al Mi pri Sanĥerib, reĝo de Asirio, Mi aŭdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Jen estas tio, kion diris pri li la Eternulo: Malestimas vin, mokas vin la virga filino de Cion, balancas post vi la kapon la filino de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Kiun vi blasfemis kaj insultis? kaj kontraŭ kiun vi laŭtigis voĉon kaj alte levis viajn okulojn? Kontraŭ la Sanktulon de Izrael!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Per viaj servantoj vi blasfemis la Sinjoron, kaj vi diris: Kun mia multo da ĉaroj mi supreniris sur la supron de montoj, sur la randon de Lebanon, kaj mi dehakis ĝiajn altajn cedrojn, ĝiajn plej bonajn cipresojn, kaj mi atingis ĝian plej altan pinton, ĝian ĝardensimilan arbaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Mi fosis kaj trinkis fremdan akvon, kaj mi sekigos per la plandoj de miaj piedoj ĉiujn riverojn de Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Ĉu vi ne aŭdis, ke Mi jam delonge tion decidis, de tempo antikva tion destinis? nun Mi tion plenumis, ke la fortikigitaj urboj fariĝis amaso da ruinŝtonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Kaj iliaj loĝantoj senfortigitaj ektremis kaj kovriĝis per honto; ili fariĝis kiel herbo de kampo, kiel malgrava verdaĵo, kiel musko sur tegmentoj, kaj kiel sunbruligita greno antaŭ la spikiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Sed vian sidon kaj vian eliron kaj vian venon Mi scias, ankaŭ vian koleron kontraŭ Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Pro tio, ke vi koleris kontraŭ Mi kaj via aroganteco venis al Miaj oreloj, Mi metos Mian ringon en viajn nazotruojn kaj Mian buŝbridaĵon en vian buŝon, kaj Mi reirigos vin per la sama vojo, per kiu vi venis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Kaj jen estas por vi la pruvosigno: vi manĝos en ĉi tiu jaro grenon memsemiĝintan, en la dua jaro grenon sovaĝan, sed en la tria jaro vi semos kaj rikoltos kaj plantos vinberĝardenojn kaj manĝos iliajn fruktojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Kaj la restaĵo de la domo de Jehuda denove enradikiĝos malsupre kaj donos fruktojn supre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Ĉar el Jerusalem devenos restaĵo, kaj savitaĵo de la monto Cion; la fervoro de la Eternulo Cebaot tion faros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Tial tiele diras la Eternulo pri la reĝo de Asirio: Li ne eniros en ĉi tiun urbon kaj ne ĵetos tien sagon kaj ne aliros al ĝi kun ŝildo kaj ne ŝutos kontraŭ ĝi remparon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Per la sama vojo, per kiu li venis, li reiros, kaj en ĉi tiun urbon li ne eniros, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Mi defendos ĉi tiun urbon, por savi ĝin pro Mi kaj pro Mia servanto David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'En tiu nokto eliris anĝelo de la Eternulo kaj frapis en la tendaro de la Asirianoj cent okdek kvin mil. Kiam oni leviĝis matene, oni ekvidis, ke ili ĉiuj estas kadavroj senvivaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Kaj Sanĥerib, la reĝo de Asirio, elmoviĝis kaj iris kaj rehejmiĝis kaj restis en Nineve.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Kaj kiam li adorkliniĝis en la domo de sia dio Nisroĥ, liaj filoj Adrameleĥ kaj Ŝarecer mortigis lin per glavo, kaj mem ili forkuris en la landon Araratan. Kaj ekreĝis anstataŭ li lia filo Esar-Ĥadon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'En tiu tempo Ĥizkija morte malsaniĝis; kaj venis al li la profeto Jesaja, filo de Amoc, kaj diris al li: Tiele diras la Eternulo: Faru testamenton pri via domo, ĉar vi mortos kaj ne vivos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Tiam Ĥizkija turnis sian vizaĝon al la muro, kaj ekpreĝis al la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Mi petas, ho Eternulo, rememoru, ke mi iradis antaŭ Vi kun vero kaj koro fidela, kaj mi faradis tion, kio plaĉas al Vi. Kaj Ĥizkija laŭte ekploris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Kiam Jesaja ankoraŭ ne eliris el la interna korto, aperis al li la vorto de la Eternulo jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Reiru, kaj diru al Ĥizkija, la estro de Mia popolo: Tiele diras la Eternulo, Dio de via patro David: Mi aŭdis vian preĝon, Mi vidis viajn larmojn; jen Mi resanigos vin; en la tria tago vi iros en la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Kaj Mi aldonos al via vivo dek kvin jarojn; kaj kontraŭ la mano de la reĝo de Asirio Mi savos vin kaj ĉi tiun urbon, kaj Mi defendos ĉi tiun urbon pro Mi kaj pro Mia servanto David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Kaj Jesaja diris: Oni alportu dispremitan figon. Kaj oni alportis kaj metis sur la ŝvelaĵon, kaj li resaniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Kaj Ĥizkija diris al Jesaja: Kia estas la signo, ke la Eternulo min resanigos kaj mi iros en la tria tago en la domon de la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Jesaja respondis: Tio estos por vi la pruvosigno de la Eternulo, ke la Eternulo plenumos tion, kion Li diris: ĉu la hormontra ombro iru antaŭen je dek gradoj, aŭ ĉu ĝi iru returne je dek gradoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Kaj Ĥizkija diris: Facile estas por la ombro iri antaŭen je dek gradoj; ne, la ombro iru returne je dek gradoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Tiam la profeto Jesaja vokis al la Eternulo, kaj Li retiris la hormontran ombron malantaŭen je dek gradoj sur la hormontrilo de Aĥaz, sur kiu ĝi malsupriĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'En tiu tempo Berodaĥ-Baladan, filo de Baladan, reĝo de Babel, sendis leterojn kaj donacojn al Ĥizkija; ĉar li aŭdis, ke Ĥizkija estis malsana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Kaj Ĥizkija elaŭdis ilin, kaj montris al ili sian tutan trezorejon, la arĝenton kaj la oron kaj la aromaĵojn kaj la karan oleon kaj sian armilejon, kaj ĉion, kio troviĝis en liaj trezorejoj; estis nenio, kion Ĥizkija ne montrus al ili en sia domo kaj en sia tuta posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Kaj venis la profeto Jesaja al la reĝo Ĥizkija, kaj diris al li: Kion parolis tiuj homoj? kaj de kie ili venis al vi? Kaj Ĥizkija diris: El lando malproksima ili venis, el Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Kaj li diris: Kion ili vidis en via domo? Kaj Ĥizkija respondis: Ĉion, kio estas en mia domo, ili vidis; estis nenio, kion mi ne montrus al ili en miaj trezorejoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Tiam Jesaja diris al Ĥizkija: Aŭskultu la diron de la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Jen venos tagoj, kaj ĉio, kio estas en via domo kaj kion kolektis viaj patroj ĝis la nuna tago, estos forportata en Babelon; nenio restos, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'Kaj el viaj filoj, kiuj devenos de vi, kiujn vi naskigos, oni prenos; kaj ili estos korteganoj en la palaco de la reĝo de Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Kaj Ĥizkija diris al Jesaja: Bona estas la vorto de la Eternulo, kiun vi diris. Kaj li diris plue: Estu nur paco kaj vero en mia tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'La cetera historio de Ĥizkija, kaj lia tuta forto, kaj kiel li faris la lageton kaj la akvotubon kaj enkondukis la akvon en la urbon, ĉio estas priskribita en la libro de kroniko de la reĝoj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Kaj Ĥizkija ekdormis kun siaj patroj, kaj anstataŭ li ekreĝis lia filo Manase.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'La aĝon de dek du jaroj havis Manase, kiam li fariĝis reĝo, kaj kvindek kvin jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Ĥefci-Ba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Li agadis malbone antaŭ la Eternulo, simile al la abomenindaĵoj de la nacioj, kiujn la Eternulo forpelis de antaŭ la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Li konstruis denove la altaĵojn, kiujn forigis lia patro Ĥizkija; kaj li starigis altarojn al Baal kaj faris sanktan stangon, kiel faris Aĥab, reĝo de Izrael, kaj adorkliniĝis antaŭ la tuta armeo de la ĉielo kaj servis al ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Li konstruis ankaŭ altarojn en la domo de la Eternulo, pri kiu la Eternulo diris: En Jerusalem Mi estigos Mian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Kaj li konstruis altarojn al la tuta armeo de la ĉielo, sur la du kortoj de la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Kaj li trairigis sian filon tra fajro, kaj li aŭguradis kaj sorĉadis, kaj starigis antaŭdiristojn kaj magiistojn; li multe agadis malbone antaŭ la Eternulo, kolerigante Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Ankaŭ la idolon por Aŝtar, kiun li faris, li starigis en la domo, pri kiu la Eternulo diris al David kaj al lia filo Salomono: En ĉi tiu domo kaj en Jerusalem, kiun Mi elektis inter ĉiuj triboj de Izrael, Mi estigos Mian nomon por eterne,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'kaj Mi ne plu elvagigos la piedon de Izrael el la tero, kiun Mi donis al iliaj patroj, se ili nur observos, por agadi konforme al ĉio, kion Mi ordonis al ili, kaj al la tuta instruo, kiun donis al ili Mia servanto Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Sed ili ne obeis; kaj Manase forlogis ilin tiel, ke ili agis pli malbone, ol la nacioj, kiujn la Eternulo ekstermis antaŭ la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Kaj la Eternulo ekparolis per Siaj servantoj, la profetoj, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'Pro tio, ke Manase, reĝo de Judujo, faris tiujn abomenindaĵojn, kiuj estas pli malbonaj, ol ĉio, kion faris la Amoridoj, kiuj estis antaŭ li, kaj li pekigis ankaŭ la Judojn per siaj idoloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'tiele diras la Eternulo, Dio de Izrael: Jen Mi venigos sur Jerusalemon kaj Judujon tian malbonon, ke ĉe ĉiu, kiu tion aŭdos, ektintos en ambaŭ liaj oreloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Mi etendos super Jerusalem la mezurŝnuron de Samario kaj la vertikalon de la domo de Aĥab, kaj Mi elviŝos Jerusalemon tiel, kiel oni elviŝas pladon, elviŝos kaj renversos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Kaj Mi forpuŝos la restaĵon de Mia heredaĵo, kaj Mi transdonos ilin en la manojn de iliaj malamikoj, kaj ili fariĝos kaptaĵo kaj rabaĵo por ĉiuj siaj malamikoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'pro tio, ke ili faradis malbonon antaŭ Miaj okuloj kaj incitadis Min, de post la tago, kiam iliaj patroj eliris el Egiptujo, ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Ankaŭ da senkulpa sango Manase elverŝis tre multe, ĝis li plenigis Jerusalemon de unu rando ĝis la alia, krom sia peko, per kiu li pekigis Judujon, por fari malbonon antaŭ la okuloj de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'La cetera historio de Manase, kaj ĉio, kion li faris, kaj la pekoj, kiujn li faris, estas priskribitaj en la libro de kroniko de la reĝoj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Kaj Manase ekdormis kun siaj patroj, kaj oni enterigis lin en la ĝardeno ĉe lia domo, en la ĝardeno de Uza. Kaj anstataŭ li ekreĝis lia filo Amon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'La aĝon de dudek du jaroj havis Amon, kiam li fariĝis reĝo, kaj du jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Meŝulemet, filino de Ĥaruc, el Jotba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Li agadis malbone antaŭ la Eternulo, kiel agadis lia patro Manase.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'Li iradis laŭ tute la sama vojo, laŭ kiu iradis lia patro, kaj li servadis al la idoloj, al kiuj servadis lia patro, kaj adorkliniĝadis antaŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'Li forlasis la Eternulon, Dion de liaj patroj, kaj ne iradis laŭ la vojo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Kaj la servantoj de Amon konspiris kontraŭ li, kaj mortigis la reĝon en lia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Sed la popolo de la lando mortigis ĉiujn, kiuj faris konspiron kontraŭ la reĝo Amon; kaj la popolo de la lando faris reĝo anstataŭ li lian filon Joŝija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'La cetera historio de Amon, kion li faris, estas priskribita en la libro de kroniko de la reĝoj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Kaj oni enterigis lin en lia tombo, en la ĝardeno de Uza. Kaj anstataŭ li ekreĝis lia filo Joŝija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'La aĝon de ok jaroj havis Joŝija, kiam li fariĝis reĝo, kaj tridek unu jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Jedida, filino de Adaja, el Bockat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Li agadis bone antaŭ la Eternulo, kaj iradis tute laŭ la vojo de sia patro David, kaj ne deflankiĝis dekstren, nek maldekstren.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'En la dek-oka jaro de la reĝo Joŝija la reĝo sendis la skribiston Ŝafan, filo de Acalja, filo de Meŝulam, en la domon de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Iru al la ĉefpastro Ĥilkija, ke li elprenu la tutan monon, kiu estis alportita en la domon de la Eternulo kaj kiun kolektis de la popolo la pordogardistoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'kaj oni transdonu ĝin en la manojn de la laborplenumantoj, kiuj havis komision en la domo de la Eternulo, por ke ĉi tiuj donu ĝin al la laborantoj en la domo de la Eternulo, por rebonigi la difektojn en la domo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'al la ĉarpentistoj kaj konstruistoj kaj masonistoj, kaj por aĉeti lignon kaj ĉirkaŭhakitajn ŝtonojn por la rebonigo de la domo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'sed oni ne postulu de ili kalkulan raporton pri la mono, transdonita en iliajn manojn, ĉar ili devas labori konfidate.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Kaj la ĉefpastro Ĥilkija diris al la skribisto Ŝafan: Libron de la instruo mi trovis en la domo de la Eternulo. Kaj Ĥilkija donis la libron al Ŝafan, kaj li ĝin legis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Kaj la skribisto Ŝafan venis al la reĝo kaj alportis al la reĝo respondon, kaj diris: Viaj servantoj elŝutis la monon, kiu troviĝis en la domo, kaj donis ĝin en la manojn de la laborplenumantoj en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Kaj la skribisto Ŝafan raportis al la reĝo, dirante: Libron donis al mi la pastro Ĥilkija. Kaj Ŝafan legis ĝin antaŭ la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Kiam la reĝo aŭdis la vortojn de la libro de la instruo, li disŝiris siajn vestojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Kaj la reĝo ordonis al la pastro Ĥilkija, kaj al Aĥikam, filo de Ŝafan, kaj al Aĥbor, filo de Miĥaja, kaj al la skribisto Ŝafan, kaj al Asaja, servanto de la reĝo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Iru, demandu la Eternulon por mi kaj por la popolo kaj por la tuta Judujo koncerne la vortojn de tiu trovita libro; ĉar granda estas la kolero de la Eternulo, ekflaminta kontraŭ ni pro tio, ke niaj patroj ne obeis la vortojn de tiu libro, por plenumi ĉion, kio estas skribita por ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Kaj iris la pastro Ĥilkija kaj Aĥikam kaj Aĥbor kaj Ŝafan kaj Asaja al la profetino Ĥulda, edzino de Ŝalum, filo de Tikva, filo de Ĥarĥas, la vestogardisto (ŝi loĝis en Jerusalem, en la dua parto); kaj ili parolis kun ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Kaj ŝi diris al ili: Tiele diras la Eternulo, Dio de Izrael: Diru al la homo, kiu sendis vin al mi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Tiele diras la Eternulo: Jen Mi venigos malfeliĉon sur ĉi tiun lokon kaj sur ĝiajn loĝantojn, ĉiujn vortojn de la libro, kiun legis la reĝo de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Pro tio, ke ili Min forlasis kaj incensis al aliaj dioj, kolerigante Min per ĉiuj faroj de siaj manoj, ekflamis Mia kolero kontraŭ ĉi tiu loko kaj ne estingiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Sed koncerne la reĝon de Judujo, kiu sendis vin, por demandi la Eternulon, diru al li jene: Tiele diras la Eternulo, Dio de Izrael, pri la vortoj, kiujn vi aŭdis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Ĉar via koro moliĝis kaj vi humiliĝis antaŭ la Eternulo, kiam vi aŭdis, kion Mi diris pri ĉi tiu loko kaj pri ĝiaj loĝantoj, ke ili fariĝos ruinaĵo kaj malbenaĵo, kaj vi disŝiris viajn vestojn kaj ploris antaŭ Mi, tial Mi ankaŭ aŭskultis vin, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Pro tio jen Mi alkolektos vin al viaj patroj, kaj vi iros en vian tombon en paco, kaj viaj okuloj ne vidos la tutan malfeliĉon, kiun Mi venigos sur ĉi tiun lokon. Kaj ili alportis la respondon al la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'La reĝo sendis, kaj oni kunvenigis al li ĉiujn plejaĝulojn de Judujo kaj Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Kaj la reĝo iris en la domon de la Eternulo, kaj kune kun li ĉiuj Judoj kaj ĉiuj loĝantoj de Jerusalem, kaj la pastroj kaj la profetoj kaj la tuta popolo, de la malgrandaj ĝis la grandaj; kaj oni voĉlegis antaŭ ili ĉiujn vortojn de la libro de interligo, kiu estis trovita en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Kaj la reĝo stariĝis ĉe la kolono, kaj faris interligon antaŭ la Eternulo, por sekvi la Eternulon kaj observi Liajn ordonojn kaj Liajn atestojn kaj Liajn leĝojn, per la tuta koro kaj per la tuta animo, por restarigi la vortojn de tiu interligo, skribitajn en tiu libro. Kaj la tuta popolo aliĝis al la interligo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Kaj la reĝo ordonis al la ĉefpastro Ĥilkija kaj al la duagradaj pastroj kaj al la pordogardistoj, ke oni elportu el la templo de la Eternulo ĉiujn objektojn, faritajn por Baal kaj por Aŝtar kaj por la tuta armeo de la ĉielo; kaj oni forbruligis ilin ekster Jerusalem sur la kampo Kidron, kaj oni forportis ilian cindron en Bet-Elon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Kaj li forigis la idolpastrojn, kiujn starigis la reĝoj de Judujo, por incensi sur la altaĵoj en la urboj de Judujo kaj en la ĉirkaŭaĵo de Jerusalem, kaj tiujn, kiuj incensadis al Baal, al la suno, al la luno, al la stelaroj, kaj al la tuta armeo de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Kaj li elportigis la sanktan stangon el la domo de la Eternulo ekster Jerusalemon al la torento Kidron; kaj oni forbruligis ĝin ĉe la torento Kidron kaj disfrotis ĝin ĝis cindreco, kaj oni ĵetis la cindron sur la tombejon de la simpla popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Kaj li detruis la domojn de malĉastistoj, kiuj estis ĉe la domo de la Eternulo kaj en kiuj la virinoj teksadis tendojn por Aŝtar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Kaj li venigis ĉiujn pastrojn el la urboj de Judujo, kaj malpurigis la altaĵojn, sur kiuj la pastroj incensadis, de Geba ĝis Beer-Ŝeba; kaj li detruis la altaĵojn ĉe la pordegoj; tiun, kiu estis antaŭ la pordego de la urbestro Josuo, kaj tiun, kiu estis maldekstre ĉe la enirado en la urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Tamen la pastroj de la altaĵoj ne oferadis sur la altaro de la Eternulo en Jerusalem, sed ili manĝadis macojn kune kun siaj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Kaj li malpurigis ankaŭ Tofeton, kiu estis en la valo de la filoj de Hinom, por ke neniu trairigu sian filon aŭ sian filinon tra fajro al Moleĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Kaj li forigis la ĉevalojn, kiujn la reĝoj de Judujo starigis al la suno ĉe la enirejo de la domo de la Eternulo, apud la ĉambro de la eŭnuko Netan-Meleĥ en Parvarim, kaj la ĉarojn de la suno li forbruligis per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Kaj la altarojn, kiuj estis sur la tegmento de la supra ĉambro de Aĥaz, kiujn faris la reĝoj de Judujo, kaj la altarojn, kiujn faris Manase en la du kortoj de la domo de la Eternulo, la reĝo detruis, kaj li kuris de tie kaj ĵetis ilian cindron en la torenton Kidron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Ankaŭ la altaĵojn, kiuj estis antaŭ Jerusalem, dekstre de la monto de pereo, kaj kiujn aranĝis Salomono, reĝo de Izrael, por Aŝtar, abomenindaĵo de la Cidonanoj, kaj por Kemoŝ, abomenindaĵo de la Moabidoj, kaj por Milkom, abomenindaĵo de la Amonidoj, la reĝo malpurigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'Kaj li disrompis la statuojn kaj dehakis la sanktajn stangojn, kaj plenigis ilian lokon per ostoj de homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Ankaŭ la altaron, kiu estis en Bet-El, kaj la altaĵon, kiun aranĝis Jerobeam, filo de Nebat, kiu pekigis Izraelon, ankaŭ tiun altaron kaj la altaĵon li detruis, kaj li forbruligis la altaĵon kaj faris el ĝi polvon kaj forbruligis la sanktan stangon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Joŝija sin turnis, kaj ekvidis la tombojn, kiuj estis tie sur la monto, kaj li sendis, kaj prenigis la ostojn el la tomboj kaj forbruligis ilin sur la altaro kaj malpurigis ĝin, konforme al la vorto de la Eternulo, kiun proklamis tiu homo de Dio, kiu antaŭdiris tiun fariĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Kaj li diris: Kio estas tiu monumento, kiun mi vidas? Kaj la loĝantoj de la urbo diris al li: Tio estas la tombo de la homo de Dio, kiu venis el Judujo, kaj antaŭdiris tiujn farojn, kiujn vi faris koncerne la altaron de Bet-El.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Kaj li diris: Lasu lin kuŝi, neniu tuŝu liajn ostojn. Tiamaniere liaj ostoj estis savitaj kun la ostoj de la profeto, kiu venis el Samario.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Ankaŭ ĉiujn domojn de la altaĵoj, kiuj estis en la urboj de Samario kaj kiujn konstruis la reĝoj de Izrael, por inciti la Eternulon, Joŝija detruis, kaj agis kun ili simile al tio, kion li faris en Bet-El.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Kaj li buĉis ĉiujn pastrojn de la altaĵoj, kiuj tie estis, sur la altaroj, kaj bruligis sur ili homajn ostojn; kaj li revenis en Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Kaj la reĝo ordonis al la tuta popolo, dirante: Faru Paskon al la Eternulo, via Dio, kiel estas skribite en tiu libro de la interligo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Ĉar simila Pasko ne estis farita de post la tempo de la juĝistoj, kiuj juĝadis Izraelon, kaj en la tuta tempo de la reĝoj de Izrael kaj de la reĝoj de Judujo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'nur en la dek-oka jaro de la reĝo Joŝija estis farita tiu Pasko al la Eternulo en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Kaj la aŭguristojn kaj la sorĉistojn kaj la domajn diojn kaj la idolojn kaj ĉiujn abomenindaĵojn, kiuj montriĝis en la Juda lando kaj en Jerusalem, Joŝija ekstermis, por plenumi la vortojn de la instruo, skribitajn en la libro, kiun la pastro Ĥilkija trovis en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Ne estis antaŭ li reĝo simila al li, kiu turnis sin al la Eternulo per sia tuta koro kaj per sia tuta animo kaj per sia tuta forto, konforme al la tuta instruo de Moseo; kaj post li ne aperis simila al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Tamen la Eternulo ne deturnis Sin de la granda furiozo de Sia kolero, per kiu Lia kolero ekflamis kontraŭ Judujo pro ĉiuj incitoj, per kiuj incitis Lin Manase.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Kaj la Eternulo diris: Ankaŭ Judujon Mi forigos de antaŭ Mia vizaĝo, kiel Mi forigis Izraelon, kaj Mi forpuŝos ĉi tiun urbon, kiun Mi elektis, Jerusalemon, kaj la domon, pri kiu Mi diris, ke Mia nomo tie estos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'La cetera historio de Joŝija, kaj ĉio, kion li faris, estas priskribitaj en la libro de kroniko de la reĝoj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'En lia tempo Faraono Neĥo, reĝo de Egiptujo, iris kontraŭ la reĝon de Asirio al la rivero Eŭfrato. La reĝo Joŝija iris renkonte al li, kaj ĉi tiu mortigis lin en Megido, kiam li ekvidis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Kaj liaj servantoj forveturigis lin mortintan el Megido kaj venigis lin en Jerusalemon kaj enterigis lin en lia tombo. Kaj la popolo de la lando prenis Jehoaĥazon, filon de Joŝija, kaj sanktoleis lin kaj faris lin reĝo anstataŭ lia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'La aĝon de dudek tri jaroj havis Jehoaĥaz, kiam li fariĝis reĝo, kaj tri monatojn li reĝis en Jerusalem. La nomo de lia patrino estis Ĥamutal, filino de Jeremia, el Libna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Li agadis malbone antaŭ la Eternulo, tiel same kiel agadis liaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Kaj Faraono Neĥo malliberigis lin en Ribla en la lando Ĥamat, por ke li ne reĝu en Jerusalem, kaj li metis sur la landon monpunon de cent kikaroj da arĝento kaj unu kikaro da oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Kaj Faraono Neĥo ekreĝigis Eljakimon, filon de Joŝija, anstataŭ lia patro Joŝija, kaj ŝanĝis lian nomon je Jehojakim; sed Jehoaĥazon li prenis kaj venigis en Egiptujon, kaj tie li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'La arĝenton kaj oron Jehojakim donis al Faraono; sed li metis tion sur la landon, ke oni donu la arĝenton laŭ la ordono de Faraono: de ĉiu laŭ taksado li prenis la arĝenton kaj la oron de la popolo de la lando, por doni al Faraono Neĥo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'La aĝon de dudek kvin jaroj havis Jehojakim, kiam li fariĝis reĝo, kaj dek unu jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Zebuda, filino de Pedaja, el Ruma.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Li agadis malbone antaŭ la Eternulo, tiel same, kiel agadis liaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'En lia tempo venis Nebukadnecar, reĝo de Babel; kaj Jehojakim estis lia subulo dum tri jaroj, sed poste li defalis de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'La Eternulo sendis sur lin hordojn da Ĥaldeoj, hordojn da Sirianoj, hordojn da Moabidoj, kaj hordojn da Amonidoj, sendis ilin sur Judujon, por pereigi ĝin, konforme al la vorto de la Eternulo, kiun Li diris per Siaj servantoj, la profetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Sed laŭ la ordono de la Eternulo tio fariĝis al Judujo, por forpuŝi ĝin de antaŭ Lia vizaĝo pro la pekoj de Manase, pro ĉio, kion li faris;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'ankaŭ pro la senkulpa sango, kiun li verŝis, plenigante Jerusalemon per senkulpa sango, la Eternulo ne volis pardoni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'La cetera historio de Jehojakim, kaj ĉio, kion li faris, estas priskribitaj en la libro de kroniko de la reĝoj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Kaj Jehojakim ekdormis kun siaj patroj, kaj anstataŭ li ekreĝis lia filo Jehojaĥin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'La reĝo de Egiptujo ne eliris plu el sia lando, ĉar la reĝo de Babel forprenis ĉion, kio apartenis al la reĝo de Egiptujo, de la torento de Egiptujo ĝis la rivero Eŭfrato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'La aĝon de dek ok jaroj havis Jehojaĥin, kiam li fariĝis reĝo, kaj tri monatojn li reĝis en Jerusalem. La nomo de lia patrino estis Neĥuŝta, filino de Elnatan, el Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Li agadis malbone antaŭ la Eternulo, tiel same, kiel agadis lia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'En tiu tempo la servantoj de Nebukadnecar, reĝo de Babel, iris kontraŭ Jerusalemon, kaj oni komencis sieĝi la urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Kaj Nebukadnecar, reĝo de Babel, venis al la urbo, kiam liaj servantoj ĝin sieĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Kaj Jehojaĥin, reĝo de Judujo, eliris al la reĝo de Babel, li kaj lia patrino kaj liaj servantoj kaj liaj altranguloj kaj liaj korteganoj; kaj la reĝo de Babel prenis lin en la oka jaro de sia reĝado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Kaj li elprenis el tie ĉiujn trezorojn de la domo de la Eternulo kaj la trezorojn de la reĝa domo, kaj li disrompis ĉiujn orajn vazojn, kiujn Salomono, reĝo de Izrael, faris en la templo de la Eternulo, kiel diris la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Kaj li forkondukis ĉiujn Jerusalemanojn, ĉiujn eminentulojn, ĉiujn fortajn militistojn-dek mil estis forkondukitaj-kaj ĉiujn artistojn kaj ĉiujn forĝistojn; restis neniu krom la malriĉa popolo de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Kaj li forkondukis Jehojaĥinon en Babelon; kaj la patrinon de la reĝo kaj la edzinojn de la reĝo kaj liajn korteganojn kaj la potenculojn de la lando li forkondukis en kaptitecon el Jerusalem en Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'Kaj ĉiujn fortulojn, sep mil, kaj la artistojn kaj la forĝistojn, mil, ĉiujn bravajn militistojn, la reĝo de Babel forkondukis en kaptitecon en Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Kaj la reĝo de Babel faris reĝo anstataŭ li lian onklon Matanja, kaj ŝanĝis lian nomon je Cidkija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'La aĝon de dudek unu jaroj havis Cidkija, kiam li fariĝis reĝo, kaj dek unu jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Ĥamutal, filino de Jeremia, el Libna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Li agadis malbone antaŭ la Eternulo, tiel same, kiel agadis Jehojakim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Ĉar la kolero de la Eternulo estis kontraŭ Jerusalem kaj kontraŭ Judujo, ĝis Li forĵetis ilin de antaŭ Sia vizaĝo. Kaj Cidkija defalis de la reĝo de Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'En la naŭa jaro de lia reĝado, en la deka monato, en la deka tago de la monato, venis Nebukadnecar, reĝo de Babel, li kaj lia tuta militistaro, kontraŭ Jerusalemon, kaj eksieĝis ĝin, kaj oni konstruis ĉirkaŭ ĝi bastionojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'Kaj la urbo restis sieĝata ĝis la dek-unua jaro de la reĝo Cidkija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'En la naŭa tago de la kvara monato, kiam la malsato tiel fortiĝis en la urbo, ke la popolo de la lando ne havis panon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'tiam oni faris enrompon en la urbon; kaj ĉiuj militistoj forkuris en la nokto laŭ la vojo de la pordego inter la du muregoj apud la ĝardeno de la reĝo, kaj foriris laŭ la vojo al la stepo. Kaj la Ĥaldeoj staris ĉirkaŭ la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Kaj la militistaro de la Ĥaldeoj postkuris la reĝon kaj kuratingis lin sur la stepo de Jeriĥo, kaj lia tuta militistaro diskuris for de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Kaj ili kaptis la reĝon kaj forkondukis lin al la reĝo de Babel en Riblan, kaj oni faris pri li juĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'La filojn de Cidkija oni buĉis antaŭ liaj okuloj, kaj al Cidkija oni blindigis liajn okulojn, kaj oni ligis lin per kupraj katenoj kaj forkondukis lin en Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'En la kvina monato, en la sepa tago de la monato, tio estas en la dek- naŭa jaro de la reĝo Nebukadnecar, reĝo de Babel, venis Nebuzaradan, estro de la korpogardistoj, servanto de la reĝo de Babel, en Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'Kaj li forbruligis la domon de la Eternulo kaj la domon de la reĝo kaj ĉiujn domojn de Jerusalem; ĉiujn grandajn domojn li forbruligis per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Kaj la muregojn de Jerusalem ĉirkaŭe detruis la tuta militistaro de la Ĥaldeoj, kiu estis kun la estro de la korpogardistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'La ceteran popolon, kiu restis en la urbo, kaj la transkurintojn, kiuj transkuris al la reĝo de Babel, kaj la ceteran popolamason forkondukis Nebuzaradan, la estro de la korpogardistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Sed iom el la malriĉuloj de la lando la estro de la korpogardistoj restigis, ke ili estu vinberistoj kaj terkultivistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'La kuprajn kolonojn, kiuj estis en la domo de la Eternulo, kaj la bazaĵojn kaj la kupran maron, kiuj estis en la domo de la Eternulo, la Ĥaldeoj disrompis kaj forportis ilian kupron en Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Kaj la potojn kaj la ŝovelilojn kaj la tranĉilojn kaj la kulerojn kaj ĉiujn kuprajn vazojn, kiuj estis uzataj ĉe la servado, ili forprenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Kaj la karbujojn kaj la aspergajn kalikojn, kiuj estis aŭ el oro aŭ el arĝento, prenis la estro de la korpogardistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Koncerne la du kolonojn, la unu maron, kaj la bazaĵojn, kiujn faris Salomono por la domo de la Eternulo: la kvanto de la kupro en ĉiuj tiuj iloj estis nemezurebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'La alton de dek ok ulnoj havis unu kolono; la kapitelo sur ĝi estis kupra, kaj la alto de la kapitelo estis tri ulnoj, kaj ĉirkaŭ la kapitelo estis kradaĵo kaj granatoj, ĉio el kupro; tiel same estis ĉe la dua kolono, ankaŭ kun kradaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Kaj la estro de la korpogardistoj prenis la ĉefpastron Seraja kaj la duan pastron Cefanja kaj la tri pordogardistojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'Kaj el la urbo li prenis unu korteganon, kiu estis super la militistoj, kaj kvin virojn el la adjutantoj de la reĝo, kiuj troviĝis en la urbo, kaj la skribiston de la militestro, kiu enregistradis la militistojn el la popolo de la lando, kaj sesdek homojn el la popolo de la lando, kiuj troviĝis en la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Ilin prenis Nebuzaradan, la estro de la korpogardistoj, kaj forkondukis al la reĝo de Babel en Riblan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'Kaj la reĝo de Babel frapis ilin kaj mortigis ilin en Ribla, en la lando Ĥamat. Tiamaniere Jehuda estis elhejmigita el sia lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Super la popolo, kiu restis en la Juda lando kaj kiun restigis Nebukadnecar, reĝo de Babel, li estrigis super ili Gedaljan, filon de Aĥikam, filo de Ŝafan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Kiam ĉiuj militestroj, ili kaj iliaj homoj, aŭdis, ke la reĝo de Babel estrigis Gedaljan, ili venis al Gedalja en Micpan, nome: Iŝmael, filo de Netanja, kaj Joĥanan, filo de Kareaĥ, kaj Seraja, filo de Tanĥumet, Netofaano, kaj Jaazanja, filo de Maaĥatano, ili kaj iliaj homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Kaj Gedalja ĵuris al ili kaj al iliaj homoj, kaj diris al ili: Ne timu esti subuloj de la Ĥaldeoj; loĝu en la lando kaj servu al la reĝo de Babel, kaj estos al vi bone.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Sed en la sepa monato venis Iŝmael, filo de Netanja, filo de Eliŝama, el la reĝa idaro, kune kun dek viroj, kaj ili frapis Gedaljan, kaj li mortis, ankaŭ la Judojn kaj la Ĥaldeojn, kiuj estis kun li en Micpa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Tiam leviĝis la tuta popolo, de la malgrandaj ĝis la grandaj, kaj ankaŭ la militestroj, kaj ili foriris en Egiptujon, ĉar ili timis la Ĥaldeojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'En la tridek-sepa jaro post la elpatrujigo de Jehojaĥin, reĝo de Judujo, en la dek-dua monato, en la dudek-sepa tago de la monato, Evil- Merodaĥ, reĝo de Babel, en la jaro de sia reĝiĝo levis la kapon de Jehojaĥin, reĝo de Judujo, el la malliberejo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'kaj li parolis kun li afable, kaj starigis lian tronon pli alte ol la tronoj de la aliaj reĝoj, kiuj estis ĉe li en Babel;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'kaj li ŝanĝis liajn vestojn de malliberejo; kaj li manĝadis ĉiam ĉe li dum sia tuta vivo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'kaj liaj vivrimedoj, vivrimedoj konstantaj, estis donataj al li de la reĝo ĉiutage dum lia tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Set, Enoŝ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kenan, Mahalalel, Jared,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Ĥanoĥ, Metuŝelaĥ, Lemeĥ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noa, Ŝem, Ĥam, kaj Jafet.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'La filoj de Jafet: Gomer, Magog, Madaj, Javan, Tubal, Meŝeĥ, kaj Tiras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'La filoj de Gomer: Aŝkenaz, Rifat, kaj Togarma.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'La filoj de Javan: Eliŝa, Tarŝiŝ, Kitim, kaj Dodanim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'La filoj de Ĥam: Kuŝ, Micraim, Put, kaj Kanaan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'La filoj de Kuŝ: Seba, Ĥavila, Sabta, Raama, kaj Sabteĥa. La filoj de Raama: Ŝeba kaj Dedan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Kuŝ naskigis ankaŭ Nimrodon; ĉi tiu komencis esti potenculo sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Micraim naskigis la Ludidojn, la Anamidojn, la Lehabidojn, la Naftuĥidojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'la Patrusidojn, la Kasluĥidojn (de kiuj devenis la Filiŝtoj), kaj la Kaftoridojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'De Kanaan naskiĝis Cidon, lia unuenaskito, kaj Ĥet,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'la Jebusidoj, la Amoridoj, la Girgaŝidoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'la Ĥividoj, la Arkidoj, la Sinidoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'la Arvadidoj, la Cemaridoj, la Ĥamatidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'La filoj de Ŝem: Elam, Aŝur, Arpaĥŝad, Lud, Aram, Uc, Ĥul, Geter, kaj Meŝeĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'De Arpaĥŝad naskiĝis Ŝelaĥ, de Ŝelaĥ naskiĝis Eber.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Al Eber naskiĝis du filoj: la nomo de unu estis Peleg, ĉar en lia tempo estis dividita la tero; la nomo de lia frato estis Joktan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'De Joktan naskiĝis Almodad, Ŝelef, Ĥacarmavet, Jeraĥ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Hadoram, Uzal, Dikla,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Ebal, Abimael, Ŝeba,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Ofir, Ĥavila, kaj Jobab. Ĉiuj ĉi tiuj estis la filoj de Joktan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Ŝem, Arpaĥŝad, Ŝelaĥ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Eber, Peleg, Reu,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serug, Naĥor, Teraĥ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram (tio estas Abraham).');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'La filoj de Abraham: Isaak kaj Iŝmael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Jen estas ilia genealogio: de Iŝmael, la unuenaskito Nebajot, poste Kedar, Adbeel, Mibsam,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Miŝma, Duma, Masa, Ĥadad, Tema,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetur, Nafiŝ, kaj Kedma. Tio estas la filoj de Iŝmael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'La filoj de Ketura, kromvirino de Abraham, kiujn ŝi naskis: Zimran, Jokŝan, Medan, Midjan, Jiŝbak, kaj Ŝuaĥ. Kaj la filoj de Jokŝan estis Ŝeba kaj Dedan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'La filoj de Midjan: Efa, Efer, Ĥanoĥ, Abida, kaj Eldaa. Ĉiuj ĉi tiuj estis la filoj de Ketura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Abraham naskigis Isaakon. La filoj de Isaak: Esav kaj Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'La filoj de Esav: Elifaz, Reuel, Jeuŝ, Jalam, kaj Koraĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'La filoj de Elifaz: Teman, Omar, Cefi, Gatam, Kenaz, Timna, kaj Amalek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'La filoj de Reuel: Naĥat, Zeraĥ, Ŝama, kaj Miza.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'La filoj de Seir: Lotan, Ŝobal, Cibeon, Ana, Diŝon, Ecer, kaj Diŝan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'La filoj de Lotan: Ĥori kaj Homam; la fratino de Lotan estis Timna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'La filoj de Ŝobal: Aljan, Manaĥat, Ebal, Ŝefi, kaj Onam. La filoj de Cibeon: Aja kaj Ana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'La filoj de Ana: Diŝon. La filoj de Diŝon: Ĥamran, Eŝban, Jitran, kaj Keran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'La filoj de Ecer: Bilhan, Zaavan, kaj Jaakan. La filoj de Diŝan: Uc kaj Aran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Jen estas la reĝoj, kiuj reĝis en la lando de Edom, antaŭ ol aperis reĝo ĉe la Izraelidoj: Bela, filo de Beor; la nomo de lia urbo estis Dinhaba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Kaj Bela mortis, kaj anstataŭ li ekreĝis Jobab, filo de Zeraĥ, el Bocra.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Kaj Joab mortis, kaj anstataŭ li ekreĝis Ĥuŝam, el la lando de la Temanidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Kaj Ĥuŝam mortis, kaj anstataŭ li ekreĝis Hadad, filo de Bedad, kiu venkobatis la Midjanidojn sur la kampo de Moab; la nomo de lia urbo estis Avit.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Kaj Hadad mortis, kaj anstataŭ li ekreĝis Samla el Masreka.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Kaj Samla mortis, kaj anstataŭ li ekreĝis Ŝaul el Reĥobot ĉe la Rivero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Kaj Ŝaul mortis, kaj anstataŭ li ekreĝis Baal-Ĥanan, filo de Aĥbor.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Kaj Baal-Ĥanan mortis, kaj anstataŭ li ekreĝis Hadad; la nomo de lia urbo estis Pai; la nomo de lia edzino estis Mehetabel, filino de Matred, filino de Me-Zahab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Kaj Hadad mortis. Tiam la ĉefoj de Edom estis: ĉefo Timna, ĉefo Alva, ĉefo Jetet,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'ĉefo Oholibama, ĉefo Ela, ĉefo Pinon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'ĉefo Kenaz, ĉefo Teman, ĉefo Mibcar,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'ĉefo Magdiel, ĉefo Iram. Tio estas la ĉefoj de Edom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Jen estas la filoj de Izrael: Ruben, Simeon, Levi, Jehuda, Isaĥar, Zebulun,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Jozef, Benjamen, Naftali, Gad, kaj Aŝer.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'La filoj de Jehuda: Er, Onan, kaj Ŝela, tri naskiĝis al li de Bat-Ŝua, la Kanaanidino. Er, la unuenaskito de Jehuda, estis malbona antaŭ la Eternulo, kaj Li mortigis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Kaj lia bofilino Tamar naskis al li Perecon kaj Zeraĥon. La nombro de ĉiuj filoj de Jehuda estis kvin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'La filoj de Perec: Ĥecron kaj Ĥamul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'La filoj de Zeraĥ: Zimri, Etan, Heman, Kalkol, kaj Dara; da ili ĉiuj estis kvin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'La filoj de Karmi: Aĥan, kiu malĝojigis Izraelon, pekinte kontraŭ anatemaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'La filoj de Etan: Azarja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'La filoj de Ĥecron, kiuj naskiĝis al li: Jeraĥmeel, Ram, kaj Kelubaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Ram naskigis Aminadabon; Aminadab naskigis Naĥŝonon, princon de la idoj de Jehuda;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Naĥŝon naskigis Salman; Salma naskigis Boazon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'Boaz naskigis Obedon; Obed naskigis Jiŝajon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Jiŝaj naskigis sian unuenaskiton Eliab, la dua estis Abinadab, la tria estis Ŝimea,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'la kvara estis Netanel, la kvina estis Radaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'la sesa estis Ocem, la sepa estis David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'Iliaj fratinoj estis: Ceruja kaj Abigail. La filoj de Ceruja estis: Abiŝaj, Joab, kaj Asahel-tri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Abigail naskis Amasan; la patro de Amasa estis Jeter, Iŝmaelido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Kaleb, filo de Ĥecron, naskigis de sia edzino Azuba kaj de Jeriot; jen estas ŝiaj filoj: Jeŝer, Ŝobab, kaj Ardon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Kiam mortis Azuba, Kaleb prenis al si Efratan, kaj ŝi naskis al li Ĥuron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Ĥur naskigis Urin; kaj Uri naskigis Becalelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Poste Ĥecron envenis al la filino de Maĥir, patro de Gilead; li prenis ŝin, kiam li havis la aĝon de sesdek jaroj, kaj ŝi naskis al li Segubon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Segub naskigis Jairon, kaj li havis dudek tri urbojn en la lando Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Sed la Geŝuranoj kaj Sirianoj forprenis de ili la Vilaĝojn de Jair, Kenaton kaj ĝiajn dependaĵojn, sesdek urbetojn. Ĉiuj ĉi tiuj estis la filoj de Maĥir, patro de Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Post la morto de Ĥecron en Kaleb-Efrata la edzino de Ĥecron, Abija, naskis al li Aŝĥuron, la fondinton de Tekoa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'La filoj de Jeraĥmeel, unuenaskito de Ĥecron, estis: la unuenaskito Ram, poste Buna, Oren, Ocem, kaj Aĥija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Jeraĥmeel havis ankaŭ alian edzinon, ŝia nomo estis Atara; ŝi estis la patrino de Onam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'La filoj de Ram, la unuenaskito de Jeraĥmeel, estis: Maac, Jamin, kaj Eker.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'La filoj de Onam estis: Ŝamaj kaj Jada. La filoj de Ŝamaj estis: Nadab kaj Abiŝur.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'La nomo de la edzino de Abiŝur estis Abiĥail; ŝi naskis al li Aĥbanon kaj Molidon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'La filoj de Nadab estis: Seled kaj Apaim. Seled mortis sen infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'La filo de Apaim estis Jiŝei. La filo de Jiŝei estis Ŝeŝan. La filo de Ŝeŝan estis Aĥlaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'La filoj de Jada, frato de Ŝamaj, estis: Jeter kaj Jonatan. Jeter mortis sen infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'La filoj de Jonatan estis: Pelet kaj Zaza. Tio estis la idoj de Jeraĥmeel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Ŝeŝan ne havis filojn, sed nur filinojn. Ŝeŝan havis sklavon Egipton, kies nomo estis Jarĥa;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'kaj Ŝeŝan donis sian filinon kiel edzinon al sia sklavo Jarĥa, kaj ŝi naskis al li Atajon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Ataj naskigis Natanon; kaj Natan naskigis Zabadon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Zabad naskigis Eflalon; kaj Eflal naskigis Obedon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Obed naskigis Jehun, kaj Jehu naskigis Azarjan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Azarja naskigis Ĥelecon; kaj Ĥelec naskigis Eleasan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Eleasa naskigis Sismajon; kaj Sismaj naskigis Ŝalumon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Ŝalum naskigis Jekamjan; kaj Jekamja naskigis Eliŝaman.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'La filoj de Kaleb, frato de Jeraĥmeel: lia unuenaskito Meŝa, kiu estis la fondinto de Zif; kaj la filoj de Mareŝa, fondinto de Ĥebron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'La filoj de Ĥebron: Koraĥ, Tapuaĥ, Rekem, kaj Ŝema.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Ŝema naskigis Raĥamon, fondinton de Jorkeam; kaj Rekem naskigis Ŝamajon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'La filo de Ŝamaj estis Maon; kaj Maon estis la fondinto de Bet-Cur.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Kaj Efa, kromvirino de Kaleb, naskis Ĥaranon, Mocan, kaj Gazezon; kaj Ĥaran naskigis Gazezon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'La filoj de Jedaj estis: Regem, Jotam, Geŝan, Pelet, Efa, kaj Ŝaaf.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Maaĥa, kromvirino de Kaleb, naskis Ŝeberon kaj Tirĥanan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Ŝi naskis ankaŭ Ŝaafon, la fondinton de Madmana, Ŝevan, la fondinton de Maĥbena kaj la fondinton de Gibea. La filino de Kaleb estis Aĥsa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Tio estis la idoj de Kaleb: la filo de Ĥur, unuenaskito de Efrata: Ŝobal, fondinto de Kirjat-Jearim,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma, fondinto de Bet-Leĥem, Ĥaref, fondinto de Bet-Gader.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Ŝobal, fondinto de Kirjat-Jearim, havis la filojn: Haroe, duono de la Menuĥot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'La familioj de Kirjat-Jearim estis: la Jetridoj, la Putidoj, la Ŝumatidoj, la Miŝraidoj. De ĉi tiuj devenis la Coreaidoj kaj la Eŝtaolidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'La idoj de Salma: la Bet-Leĥemanoj, la Netofaanoj, la Atrotanoj de la domo de Joab, la duono de la Manaĥatanoj, la Coreanoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'kaj la familioj de la skribistoj, kiuj loĝis en Jabec, la Tiratidoj, Ŝimeatidoj, kaj Suĥatidoj; tio estis la Kenidoj, kiuj devenis de Ĥamat, la fondinto de Bet-Reĥab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Jen estas la filoj de David, kiuj naskiĝis al li en Ĥebron: la unuenaskito Amnon, de la Jizreelanino Aĥinoam; la dua estis Daniel, de la Karmelanino Abigail;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'la tria estis Abŝalom, filo de Maaĥa, filino de Talmaj, reĝo de Geŝur; la kvara estis Adonija, filo de Ĥagit;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'la kvina estis Ŝefatja, de Abital; la sesa estis Jitream, de lia edzino Egla;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'ses naskiĝis al li en Ĥebron. Li reĝis tie sep jarojn kaj ses monatojn; kaj tridek tri jarojn li reĝis en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Kaj jen estas tiuj, kiuj naskiĝis al li en Jerusalem: Ŝimea, Ŝobab, Natan, Salomono-ĉi tiuj kvar de Bat-Ŝua, filino de Amiel;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'Jibĥar, Eliŝama, Elifelet,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Noga, Nefeg, Jafia,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Eliŝama, Eljada, kaj Elifelet-naŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Tio estas ĉiuj filoj de David, krom la filoj de kromvirinoj; kaj ilia fratino estis Tamar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'La filo de Salomono estis Reĥabeam; la filo de ĉi tiu estis Abija; la filo de ĉi tiu: Asa; la filo de ĉi tiu: Jehoŝafat;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'la filo de ĉi tiu: Joram; la filo de ĉi tiu: Aĥazja; la filo de ĉi tiu: Joaŝ;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'la filo de ĉi tiu: Amacja; la filo de ĉi tiu: Azarja; la filo de ĉi tiu: Jotam;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'la filo de ĉi tiu: Aĥaz; la filo de ĉi tiu: Ĥizkija; la filo de ĉi tiu: Manase;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'la filo de ĉi tiu: Amon; la filo de ĉi tiu: Joŝija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'La filoj de Joŝija estis: la unuenaskito Joĥanan, la dua Jehojakim, la tria Cidkija, la kvara Ŝalum.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'La filoj de Jehojakim: lia filo Jeĥonja, lia filo Cidkija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'La filoj de Jeĥonja: Asir, lia filo Ŝealtiel,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Malkiram, Pedaja, Ŝenacar, Jekamja, Ĥoŝama, kaj Nedabja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'La filoj de Pedaja: Zerubabel kaj Ŝimei. La filoj de Zerubabel: Meŝulam, Ĥananja; ilia fratino estis Ŝelomit;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'ankaŭ ĉi tiuj kvin: Ĥaŝuba, Ohel, Bereĥja, Ĥasadja, kaj Juŝab- Ĥesed.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'La idoj de Ĥananja: Pelatja kaj Jeŝaja; la filoj de Refaja, la filoj de Arnan, la filoj de Obadja, la filoj de Ŝeĥanja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'La filo de Ŝeĥanja estis Ŝemaja; la filoj de Ŝemaja: Ĥatuŝ, Jigal, Bariaĥ, Nearja, kaj Ŝafat-ses.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'La filoj de Nearja: Eljoenaj, Ĥizkija, kaj Azrikam-tri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'La filoj de Eljoenaj: Hodavja, Eljaŝib, Pelaja, Akub, Joĥanan, Delaja, kaj Anani-sep.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'La filoj de Jehuda estis: Perec, Ĥecron, Karmi, Ĥur, kaj Ŝobal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Reaja, filo de Ŝobal, naskigis Jaĥaton; Jaĥat naskigis Aĥumajon kaj Lahadon; tio estas la familioj de la Coreaidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Kaj jen estas la domanaro de Etam: Jizreel, Jiŝma, Jidbaŝ; la nomo de ilia fratino estis Haclelponi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'kaj Penuel, la fondinto de Gedor, kaj Ezer, la fondinto de Ĥuŝa. Tio estas la idoj de Ĥur, unuenaskito de Efrata, posedanto de Bet-Leĥem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Aŝĥur, fondinto de Tekoa, havis du edzinojn: Ĥela kaj Naara.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Naara naskis al li Aĥuzamon, Ĥeferon, Temnin, kaj Aĥaŝtarin; tio estas la filoj de Naara;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'la filoj de Ĥela estis: Ceret, Coĥar, kaj Etnan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Koc naskigis Anubon, Cobeban, kaj la familiojn de Aĥarĥel, filo de Harum.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Jabec estis la plej estimata inter siaj fratoj. Lia patrino donis al li la nomon Jabec, ĉar ŝi diris: En malĝojo mi naskis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Kaj Jabec vokis al Dio de Izrael, dirante: Ho, se Vi min benus kaj vastigus miajn limojn, kaj Via mano estus kun mi kaj forigus la malbonon, por ke mi ne havu aflikton! Kaj Dio plenumis tion, pri kio li petis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Kelub, frato de Ŝuĥa, naskigis Meĥiron; ĉi tiu estis la patro de Eŝton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Eŝton naskigis Bet-Rafan, Paseaĥon, kaj Teĥinan, fondinton de la urbo Naĥaŝ; tio estas la loĝantoj de Reĥa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'La filoj de Kenaz estis: Otniel kaj Seraja; la filo de Otniel estis Ĥatat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Meonotaj naskigis Ofran, kaj Seraja naskigis Joabon, fondinton de la Valo de Ĉarpentistoj; ĉar ili estis ĉarpentistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'La filoj de Kaleb, filo de Jefune: Iru, Ela, kaj Naam; la filo de Ela estis Kenaz.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'La filoj de Jehalelel: Zif, Zifa, Tirja, kaj Asarel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'La filoj de Ezra: Jeter, Mered, Efer, kaj Jalon. Ŝi naskis Mirjamon, Ŝamajon, kaj Jiŝbaĥon, la patron de Eŝtemoa;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'dum lia edzino la Judino naskis Jeredon, fondinton de Gedor, Ĥeberon, fondinton de Soĥo, kaj Jekutielon, fondinton de Zanoaĥ. Tiuj estis la filoj de Bitja, filino de Faraono, kiun prenis Mered.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'La filoj de la edzino de Hodija, fratino de Naĥam: la patro de Keila, la Garmano, kaj Eŝtemoa, la Maaĥatano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'La filoj de Ŝimon: Amnon, Rina, Ben-Ĥanan, kaj Tilon; la filoj de Jiŝei: Zoĥet kaj Ben-Zoĥet.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'La filoj de Ŝela, filo de Jehuda: Er, patro de Leĥa, kaj Lada, patro de Mareŝa, kaj la familioj de la tolfaristoj el la domo de Aŝbea;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'kaj Jokim, kaj la loĝantoj de Kozeba, kaj Joaŝ, kaj Saraf, kiuj estis sinjoroj en Moab kaj poste revenis en Bet-Leĥemon, laŭ antikvaj rakontoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'Ili estis potistoj, kaj loĝis inter ĝardenoj kaj brutejoj; ĉe la reĝo ili tie loĝis por liaj laboroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'La filoj de Simeon: Nemuel, Jamin, Jarib, Zeraĥ, kaj Ŝaul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'La filo de ĉi tiu estis Ŝalum; la filo de ĉi tiu estis Mibsam; la filo de ĉi tiu estis Miŝma.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'La filoj de Miŝma: lia filo Ĥamuel, lia filo Zakur, lia filo Ŝimei.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Ŝimei havis dek ses filojn kaj ses filinojn; sed liaj fratoj ne havis multe da filoj, kaj ilia tuta parencaro ne tiel multiĝis, kiel la idaro de Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Ili loĝis en Beer-Ŝeba, Molada, kaj Ĥacar-Ŝual,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'en Bilha, Ecem, kaj Tolad,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'en Betuel, Ĥorma, kaj Ciklag,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'en Bet-Markabot, Ĥacar-Susim, Bet-Biri, kaj Ŝaaraim. Tio estis iliaj urboj ĝis la reĝado de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Iliaj vilaĝoj estis: Etam, Ain, Rimon, Toĥen, kaj Aŝan, kvin urboj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'kaj ĉiuj iliaj vilaĝoj, kiuj estis ĉirkaŭ tiuj urboj, ĝis Baal. Tie estis ilia loĝloko, kaj ili havis apartan genealogian registron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Kaj Meŝobab, Jamleĥ, Joŝa, filo de Amacja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'Joel, Jehu, filo de Joŝibja, filo de Seraja, filo de Asiel,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'Eljoenaj, Jaakoba, Jeŝoĥaja, Asaja, Adiel, Jesimiel, Benaja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'Ziza, filo de Ŝifi, filo de Alon, filo de Jedaja, filo de Ŝimri, filo de Ŝemaja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Ĉi tiuj, cititaj laŭ iliaj nomoj, estis princoj en siaj familioj, kaj iliaj patrodomoj forte vastiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Ili iris ĝis Gedor, ĝis la orienta flanko de la valo, por serĉi paŝtejon por siaj ŝafoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'kaj ili trovis paŝtejon grasan kaj bonan, kaj teron vastan, trankvilan, kaj kvietan, ĉar el la Ĥamidoj estis tiuj, kiuj tie loĝis antaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Kaj venis tiuj, kiuj ĵus estas cititaj, en la tempo de Ĥizkija, reĝo de Judujo, kaj disbatis iliajn tendojn, kaj ankaŭ la Meunojn, kiuj tie troviĝis, kaj ekstermis ilin por ĉiam kaj ekloĝis sur ilia loko, ĉar tie estis paŝtejo por iliaj ŝafoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Kaj el ili, el la idoj de Simeon, kvincent homoj iris al la monto Seir; iliaj estroj estis Pelatja, Nearja, Refaja, kaj Uziel, filoj de Jiŝei.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'Kaj ili venkobatis la restintajn saviĝintojn de Amalek kaj ekloĝis tie por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'La filoj de Ruben, unuenaskito de Izrael. (Li estis la unuenaskito; sed kiam li malhonoris la liton de sia patro, lia unuenaskiteco estis fordonita al la filoj de Jozef, filo de Izrael, kaj li ne estis enskribita en la genealogian liston kiel unuenaskito;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Jehuda estis la plej potenca inter siaj fratoj, kaj la reganto devenis de li; sed la unuenaskiteco estis donita al Jozef.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'La filoj de Ruben, unuenaskito de Izrael: Ĥanoĥ, Palu, Ĥecron, kaj Karmi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'La idoj de Joel: lia filo estis Ŝemaja, lia filo estis Gog, lia filo estis Ŝimei,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'lia filo estis Miĥa, lia filo estis Reaja, lia filo estis Baal,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'lia filo estis Beera, kiun forkondukis en kaptitecon Tiglat-Pileser, reĝo de Asirio. Li estis princo de la Rubenidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Kaj liaj fratoj, laŭ iliaj familioj, laŭ ilia genealogia listo, estis: Jeiel, la ĉefo, Zeĥarja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'kaj Bela, filo de Azaz, filo de Ŝema, filo de Joel. Li loĝis en Aroer, ĝis Nebo kaj Baal-Meon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'Oriente li loĝis ĝis la komenco de la dezerto ĉe la rivero Eŭfrato; ĉar ili havis multe da brutoj en la lando Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'En la tempo de Saul ili militis kontraŭ la Hagaridoj, kaj ĉi tiuj enfalis en iliajn manojn; kaj ili ekloĝis en la tendoj de tiuj en la tuta orienta parto de Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'La idoj de Gad loĝis apude de ili, en la lando Baŝan, ĝis Salĥa;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'la ĉefo estis Joel, la dua estis Ŝafam, poste Janaj kaj Ŝafat en Baŝan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Iliaj fratoj, laŭ iliaj patrodomoj: Miĥael, Meŝulam, Ŝeba, Joraj, Jakan, Zia, kaj Eber-sep.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Jen estas la filoj de Abiĥail, filo de Ĥuri, filo de Jaroaĥ, filo de Gilead, filo de Miĥael, filo de Jeŝiŝaj, filo de Jaĥdo, filo de Buz;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Aĥi, filo de Abdiel, filo de Guni, estis ĉefo de ilia patrodomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Kaj ili loĝis en Gilead en Baŝan kaj ĝiaj filinurboj, kaj sur ĉiuj kampoj de Ŝaron, ĝis iliaj finoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Ĉiuj ili estis genealogie enskribitaj en la tempo de Jotam, reĝo de Judujo, kaj en la tempo de Jerobeam, reĝo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'La idoj de Ruben kaj la Gadidoj kaj la duontribo de Manase havis da batalkapablaj viroj, portantaj ŝildon kaj glavon, streĉantaj pafarkon, kaj instruitaj por milito, kvardek kvar mil sepcent sesdek, elirantojn en militistaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Ili militis kontraŭ la Hagaridoj, kontraŭ Jetur, Nafiŝ, kaj Nodab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'Kaj ili ricevis helpon kontraŭ ĉi tiuj; kaj la Hagaridoj, kun ĉio, kion ili havis, estis transdonitaj en iliajn manojn. Ĉar dum la milito ili vokis al Dio, kaj Li aŭskultis ilian preĝon pro tio, ke ili fidis Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Kaj ili forkaptis la brutojn de tiuj, kvindek mil kamelojn, ducent kvindek mil ŝafojn, du mil azenojn, kaj cent mil homojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Multe da mortigitoj falis, ĉar de Dio estis la milito. Kaj ili loĝis sur ilia loko ĝis la elpatrujigo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'La idoj de la duontribo de Manase loĝis en la lando de Baŝan ĝis Baal-Ĥermon, Senir, kaj la monto Ĥermon. Ili estis en granda nombro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Kaj jen estas la ĉefoj de iliaj patrodomoj: Efer, Jiŝei, Eliel, Azriel, Jeremia, Hodavja, kaj Jaĥdiel, viroj potencaj, viroj famaj, ĉefoj de siaj patrodomoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Sed ili defalis de Dio de iliaj patroj, kaj malĉaste sekvis la diojn de la enlandaj popoloj, kiujn Dio ekstermis antaŭ ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'tial Dio de Izrael ekscitis kontraŭ ili la spiriton de Pul, reĝo de Asirio, kaj la spiriton de Tiglat-Pileser, reĝo de Asirio, kaj li elpatrujigis la Rubenidojn, la Gadidojn, kaj la duontribon de la Manaseidoj, kaj forkondukis ilin en Ĥalaĥon, Ĥaboron, Haran, kaj al la rivero Gozan ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'La filoj de Levi: Gerŝon, Kehat, kaj Merari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'La filoj de Kehat: Amram, Jichar, Ĥebron, kaj Uziel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'La infanoj de Amram: Aaron, Moseo, kaj Mirjam; kaj la filoj de Aaron: Nadab, Abihu, Eleazar, kaj Itamar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Eleazar naskigis Pineĥason, Pineĥas naskigis Abiŝuan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Abiŝua naskigis Bukin, Buki naskigis Uzin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'Uzi naskigis Zeraĥjan, Zeraĥja naskigis Merajoton,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Merajot naskigis Amarjan, Amarja naskigis Aĥitubon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'Aĥitub naskigis Cadokon, Cadok naskigis Aĥimaacon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'Aĥimaac naskigis Azarjan, Azarja naskigis Joĥananon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Joĥanan naskigis Azarjan (li estis tiu, kiu estis pastro en la domo, kiun Salomono konstruis en Jerusalem),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Azarja naskigis Amarjan, Amarja naskigis Aĥitubon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'Aĥitub naskigis Cadokon, Cadok naskigis Ŝalumon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Ŝalum naskigis Ĥilkijan, Ĥilkija naskigis Azarjan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Azarja naskigis Serajan, Seraja naskigis Jehocadakon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'Jehocadak iris en kaptitecon, kiam la Eternulo elpatrujigis la Judojn kaj la Jerusalemanojn per Nebukadnecar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'La filoj de Levi: Gerŝon, Kehat, kaj Merari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'Jen estas la nomoj de la filoj de Gerŝon: Libni kaj Ŝimei.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'La filoj de Kehat: Amram, Jichar, Ĥebron, kaj Uziel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'La filoj de Merari: Maĥli kaj Muŝi. Kaj jen estas la familioj de Levi laŭ iliaj patrodomoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'la idoj de Gerŝon: Libni; lia filo: Jaĥat; lia filo: Zima;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'lia filo: Joaĥ; lia filo: Ido; lia filo: Zeraĥ; lia filo: Jeatraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'La idoj de Kehat: lia filo: Aminadab; lia filo: Koraĥ; lia filo: Asir;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'lia filo: Elkana; lia filo: Ebjasaf; lia filo: Asir;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'lia filo: Taĥat; lia filo: Uriel; lia filo: Uzija; lia filo: Ŝaul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'La filoj de Elkana: Amasaj kaj Aĥimot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'Elkana: la idoj de Elkana: lia filo: Cofaj; lia filo: Naĥat;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'lia filo: Eliab; lia filo: Jeroĥam; lia filo: Elkana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'La filoj de Samuel: la unuenaskito Vaŝni, kaj Abija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'La idoj de Merari: Maĥli; lia filo: Libni; lia filo: Ŝimei; lia filo: Uza;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'lia filo: Ŝimea; lia filo: Ĥagija; lia filo: Asaja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'Jen estas tiuj, kiujn David starigis por kantado en la domo de la Eternulo de post la tempo, kiam la sankta kesto trovis tie ripozejon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'ili servadis antaŭ la tabernaklo de kunveno per kantado, ĝis Salomono konstruis la domon de la Eternulo en Jerusalem; kaj ili stariĝadis al sia servado laŭ sia regularo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'jen estas tiuj, kiuj stariĝadis, kaj iliaj filoj: el la Kehatidoj estis la kantisto Heman, filo de Joel, filo de Samuel,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'filo de Elkana, filo de Jeroĥam, filo de Eliel, filo de Toaĥ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'filo de Cuf, filo de Elkana, filo de Maĥat, filo de Amasaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'filo de Elkana, filo de Joel, filo de Azarja, filo de Cefanja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'filo de Taĥat, filo de Asir, filo de Ebjasaf, filo de Koraĥ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'filo de Jichar, filo de Kehat, filo de Levi, filo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Kaj lia frato Asaf, kiu staradis dekstre de li, Asaf, filo de Bereĥja, filo de Ŝimea,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'filo de Miĥael, filo de Baaseja, filo de Malkija,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'filo de Etni, filo de Zeraĥ, filo de Adaja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'filo de Etan, filo de Zima, filo de Ŝimei,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'filo de Jaĥat, filo de Gerŝon, filo de Levi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'La idoj de Merari, iliaj fratoj, staradis maldekstre: Etan, filo de Kiŝi, filo de Abdi, filo de Maluĥ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'filo de Ĥaŝabja, filo de Amacja, filo de Ĥilkija,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'filo de Amci, filo de Bani, filo de Ŝemer,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'filo de Maĥli, filo de Muŝi, filo de Merari, filo de Levi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Kaj iliaj fratoj, la Levidoj, estis destinitaj por ĉiuj servoj en la tabernaklo de la domo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Aaron kaj liaj filoj incensadis sur la altaro de bruloferoj kaj sur la altaro de incensado; ili estis destinitaj por ĉiuj servoj en la plejsanktejo, kaj por pekliberigi Izraelon, konforme al ĉio, kion ordonis Moseo, servanto de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Kaj jen estas la idoj de Aaron: lia filo: Eleazar; lia filo: Pineĥas; lia filo: Abiŝua;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'lia filo: Buki; lia filo: Uzi; lia filo: Zeraĥja;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'lia filo: Merajot; lia filo: Amarja; lia filo: Aĥitub;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'lia filo: Cadok; lia filo: Aĥimaac.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Kaj jen estas iliaj loĝlokoj, laŭ iliaj vilaĝoj en iliaj limoj: al la idoj de Aaron, al la familioj de la Kehatidoj, ĉar al ili destinis la loto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'oni donis Ĥebronon, en la lando de Jehuda, kaj ĝiajn antaŭurbojn ĉirkaŭ ĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'sed la kampon de tiu urbo kaj ĝiajn vilaĝojn oni donis al Kaleb, filo de Jefune.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Al la idoj de Aaron oni donis la urbojn de rifuĝo: Ĥebronon, Libnan kaj ĝiajn antaŭurbojn, Jatiron, Eŝtemoan kaj ĝiajn antaŭurbojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'Ĥilenon kaj ĝiajn antaŭurbojn, Debiron kaj ĝiajn antaŭurbojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'Aŝanon kaj ĝiajn antaŭurbojn, Bet-Ŝemeŝon kaj ĝiajn antaŭurbojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'kaj de la tribo de Benjamen: Geban kaj ĝiajn antaŭurbojn, Alemeton kaj ĝiajn antaŭurbojn, kaj Anatoton kaj ĝiajn antaŭurbojn. La nombro de ĉiuj iliaj urboj en iliaj familioj estis dek tri urboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'Al la idoj de Kehat, kiuj restis el la familio de la tribo, oni donis de la duontribo de Manase laŭlote dek urbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Al la idoj de Gerŝon laŭ iliaj familioj oni donis de la tribo Isaĥar, de la tribo Aŝer, de la tribo Naftali, kaj de la tribo Manase en Baŝan dek tri urbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Al la idoj de Merari laŭ iliaj familioj oni donis de la tribo Ruben, de la tribo Gad, kaj de la tribo Zebulun laŭlote dek du urbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Kaj la Izraelidoj donis al la Levidoj la urbojn kaj iliajn antaŭurbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'Ili donis laŭlote de la tribo de la Jehudaidoj, de la tribo de la Simeonidoj, kaj de la tribo de la Benjamenidoj tiujn urbojn, kiujn ili nomis laŭ la nomoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'Al kelkaj familioj el la idoj de Kehat oni donis urbojn, apartenontajn al ili, de la tribo Efraim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'Kaj oni donis al ili la urbojn de rifuĝo: Ŝeĥemon kaj ĝiajn antaŭurbojn, sur la monto de Efraim, Gezeron kaj ĝiajn antaŭurbojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'Jokmeamon kaj ĝiajn antaŭurbojn, Bet-Ĥoronon kaj ĝiajn antaŭurbojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'Ajalonon kaj ĝiajn antaŭurbojn, Gat-Rimonon kaj ĝiajn antaŭurbojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'kaj de la duontribo de Manase: Aneron kaj ĝiajn antaŭurbojn, Bileamon kaj ĝiajn antaŭurbojn. Tio estis por la restintaj familioj de la Kehatidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'Al la idoj de Gerŝon oni donis de la familioj de la duontribo de Manase: Golanon en Baŝan kaj ĝiajn antaŭurbojn, kaj Aŝtaroton kaj ĝiajn antaŭurbojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'de la tribo Isaĥar: Kedeŝon kaj ĝiajn antaŭurbojn, Dabraton kaj ĝiajn antaŭurbojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'Ramoton kaj ĝiajn antaŭurbojn, kaj Anemon kaj ĝiajn antaŭurbojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'de la tribo Aŝer: Maŝalon kaj ĝiajn antaŭurbojn, Abdonon kaj ĝiajn antaŭurbojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'Ĥukokon kaj ĝiajn antaŭurbojn, kaj Reĥobon kaj ĝiajn antaŭurbojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'de la tribo Naftali: Kedeŝon en Galileo kaj ĝiajn antaŭurbojn, Ĥamonon kaj ĝiajn antaŭurbojn, kaj Kirjataimon kaj ĝiajn antaŭurbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'Al la ceteraj idoj de Merari oni donis de la tribo Zebulun: Rimonon kaj ĝiajn antaŭurbojn, kaj Taboron kaj ĝiajn antaŭurbojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'kaj transe de Jordan, kontraŭ Jeriĥo, oriente de Jordan, oni donis de la tribo Ruben: Beceron en la dezerto kaj ĝiajn antaŭurbojn, Jahacon kaj ĝiajn antaŭurbojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'Kedemoton kaj ĝiajn antaŭurbojn, kaj Mefaaton kaj ĝiajn antaŭurbojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'kaj de la tribo Gad: Ramoton en Gilead kaj ĝiajn antaŭurbojn, Maĥanaimon kaj ĝiajn antaŭurbojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'Ĥeŝbonon kaj ĝiajn antaŭurbojn, kaj Jazeron kaj ĝiajn antaŭurbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'La filoj de Isaĥar estis: Tola, Pua, Jaŝub, kaj Ŝimron-kvar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'La idoj de Tola: Uzi, Refaja, Jeriel, Jaĥmaj, Jibsam, kaj Ŝemuel, ĉefoj de patrodomoj de Tola, kuraĝaj militistoj en siaj generacioj; ilia nombro en la tempo de David estis dudek du mil sescent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'La idoj de Uzi: Jizraĥja; la idoj de Jizraĥja: Miĥael, Obadja, Joel, kaj Jiŝija-kune kvin patrodomoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Kun ili, laŭ iliaj generacioj, laŭ iliaj patrodomoj, estis da militistoj armitaj por milito tridek ses mil; ĉar ili havis multe da edzinoj kaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Da iliaj fratoj, en ĉiuj familioj de Isaĥar, estis okdek sep mil batalkapabluloj, ĉiuj enskribitaj en la genealogiajn listojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Ĉe Benjamen: Bela, Beĥer, kaj Jediael-tri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'La idoj de Bela: Ecbon, Uzi, Uziel, Jerimot, kaj Iri-kvin patrodomoj, militkapablaj. En la genealogiaj listoj ili prezentis la nombron de dudek du mil tridek kvar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'La idoj de Beĥer: Zemira, Joaŝ, Eliezer, Eljoenaj, Omri, Jeremot, Abija, Anatot, kaj Alemet; ĉiuj ili estis la filoj de Beĥer.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'En la listoj, laŭ ilia genealogio, laŭ iliaj patrodomoj, estis dudek mil ducent batalkapabluloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'La idoj de Jediael: Bilhan; la idoj de Bilhan: Jeuŝ, Benjamen, Ehud, Kenaana, Zetan, Tarŝiŝ, kaj Aĥiŝaĥar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Ĉiuj ili estis la idoj de Jediael, laŭ patrodomoj, batalkapabluloj, dek sep mil ducent armitaj por milito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Ŝupim kaj Ĥupim, idoj de Ir; Ĥuŝim, idoj de Aĥer.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'La filoj de Naftali: Jaĥciel, Guni, Jecer, kaj Ŝalum, filoj de Bilha.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'La filoj de Manase: Asriel, kiun naskis lia kromvirino, Sirianino; ŝi naskis ankaŭ Maĥiron, la patron de Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Maĥir prenis edzinon el la domanaro de Ĥupim kaj Ŝupim; la nomo de lia fratino estis Maaĥa. La nomo de la dua estis Celofĥad. Celofĥad havis nur filinojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Kaj Maaĥa, la edzino de Maĥir, naskis filon kaj donis al li la nomon Pereŝ; la nomo de lia frato estis Ŝereŝ; liaj filoj estis Ulam kaj Rekem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'La filo de Ulam estis Bedan. Tio estas la filoj de Gilead, filo de Maĥir, filo de Manase.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Lia fratino Moleĥet naskis Iŝ-Hodon, Abiezeron, kaj Maĥlan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'La filoj de Ŝemida estis: Aĥjan, Ŝeĥem, Likĥi, kaj Aniam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'La idoj de Efraim: Ŝutelaĥ, kaj lia filo Bered, kaj lia filo Taĥat, kaj lia filo Eleada, kaj lia filo Taĥat,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'kaj lia filo Zabad, kaj lia filo Ŝutelaĥ, kaj Ezer, kaj Elead. Kaj mortigis ilin la loĝantoj de Gat, la indiĝenoj de la lando, kiam ili iris, por forpreni iliajn brutojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Kaj ilia patro Efraim funebris longan tempon, kaj liaj fratoj venis, por konsoli lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Kaj li envenis al sia edzino, kaj ŝi gravediĝis kaj naskis filon, kaj donis al li la nomon Beria, ĉar malfeliĉo okazis en lia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Lia filino estis Ŝeera. Ŝi konstruis Bet-Ĥoronon, la malsupran kaj la supran, kaj Uzen-Ŝeeran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Kaj lia filo estis Refaĥ, lia filo estis Reŝef, lia filo estis Telaĥ, lia filo estis Taĥan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'lia filo estis Ladan, lia filo estis Amihud, lia filo estis Eliŝama,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'lia filo estis Nun, lia filo estis Josuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Ilia posedaĵo kaj loĝloko estis Bet-El kaj ĝiaj filinurboj, oriente Naaran, okcidente Gezer kun ĝiaj filinurboj, kaj Ŝeĥem kun ĝiaj filinurboj, ĝis Aza kun ĝiaj filinurboj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'ĉe la flanko de la Manaseidoj: Bet-Ŝean kun ĝiaj filinurboj, Taanaĥ kun ĝiaj filinurboj, Megido kun ĝiaj filinurboj, Dor kun ĝiaj filinurboj. En tiuj lokoj loĝis la idoj de Jozef, filo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'La filoj de Aŝer: Jimna, Jiŝva, Jiŝvi, Beria; ilia fratino estis Seraĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'La filoj de Beria: Ĥeber, kaj Malkiel, kiu estis la patro de Birzait.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Ĥeber naskigis Jafleton, Ŝomeron, Ĥotamon, kaj Ŝuan, ilian fratinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'La filoj de Jaflet: Pasaĥ, Bimhal, kaj Aŝvat. Tio estas la filoj de Jaflet.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'La filoj de Ŝemer: Aĥi, Rohaga, Jeĥuba, kaj Aram.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'La filoj de lia frato Helem: Cofaĥ, Jimna, Ŝeleŝ, kaj Amal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'La filoj de Cofaĥ: Suaĥ, Ĥarnefer, Ŝual, Beri, Jimra,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Becer, Hod, Ŝama, Ŝilŝa, Jitran, kaj Beera.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'La filoj de Jeter: Jefune, Pispa, kaj Ara.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'La filoj de Ula: Araĥ, Ĥaniel, kaj Ricja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Ĉiuj ĉi tiuj estis idoj de Aŝer, ĉefoj de patrodomoj, elektitaj, kuraĝaj militistoj, ĉefaj estroj. Ili estis enskribitaj en la genealogia listo, en la militistaro, por milito; ilia nombro estis dudek ses mil viroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'De Benjamen naskiĝis: Bela, lia unuenaskito, Aŝbel, la dua, Aĥraĥ, la tria;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Noĥa estis la kvara, kaj Rafa estis la kvina.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'La filoj de Bela estis: Adar, Gera, Abihud,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abiŝua, Naaman, Aĥoaĥ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Gera, Ŝefufan, kaj Ĥuram.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Jen estas la filoj de Ehud, kiuj estis ĉefoj de patrodomoj, kiuj loĝis en Geba kaj elmigris en Manaĥaton:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'Naaman, Aĥija, Gera; ĉi tiu elmigrigis ilin, kaj li naskigis Uzan kaj Aĥiĥudon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Ŝaĥaraim naskigis sur la kampoj de Moab, post kiam li forigis de si siajn edzinojn Ĥuŝim kaj Baara.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Li naskigis de sia edzino Ĥodeŝ: Jobabon, Cibjan, Meŝan, Malkamon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jeucon, Ŝoĥjan, kaj Mirman. Tio estis liaj filoj, ĉefoj de patrodomoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'De Ĥuŝim li naskigis Abitubon kaj Elpaalon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'La filoj de Elpaal: Eber, Miŝeam, kaj Ŝemer; ĉi tiu konstruis Onon kaj Lodon kaj ĝiajn filinurbojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'kaj Beria, kaj Ŝema. Ili estis la ĉefoj de patrodomoj de la loĝantoj de Ajalon; ili elpelis la loĝantojn de Gat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'Aĥjo, Ŝaŝak, Jeremot,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Zebadja, Arad, Eder,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Miĥael, Jiŝpa, kaj Joĥa estis la filoj de Beria.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Zebadja, Meŝulam, Ĥizki, Ĥeber,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Jiŝmeraj, Jizlia, kaj Jobab estis la filoj de Elpaal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Jakim, Ziĥri, Zabdi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elienaj, Ciltaj, Eliel,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adaja, Beraja, kaj Ŝimrat estis la filoj de Ŝimei.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Jiŝpan, Eber, Eliel,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdon, Ziĥri, Ĥanan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Ĥananja, Elam, Antotija,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Jifdeja, kaj Penuel estis la filoj de Ŝaŝak.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Ŝamŝeraj, Ŝeĥarja, Atalja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jaareŝja, Elija, kaj Ziĥri estis la filoj de Jeroĥam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Tio estis la ĉefoj de patrodomoj, ĉefoj laŭ siaj generacioj; ili loĝis en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'En Gibeon loĝis: la fondinto de Gibeon-la nomo de lia edzino estis Maaĥa-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'kaj lia unuenaskita filo Abdon, Cur, Kiŝ, Baal, Nadab,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedor, Aĥjo, kaj Zeĥer.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'Miklot naskigis Ŝiman. Ankaŭ ili apud siaj fratoj enloĝiĝis en Jerusalem kun siaj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Ner naskigis Kiŝon, Kiŝ naskigis Saulon, Saul naskigis Jonatanon, Malki-Ŝuan, Abinadabon, kaj Eŝbaalon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'La filo de Jonatan estis Merib-Baal, kaj Merib-Baal naskigis Miĥan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'La filoj de Miĥa estis Piton, Meleĥ, Taarea, kaj Aĥaz.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Aĥaz naskigis Jehoadan; Jehoada naskigis Alemeton, Azmaveton, kaj Zimrin; Zimri naskigis Mocan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Moca naskigis Binean; lia filo estis Rafa, lia filo estis Eleasa, lia filo estis Acel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Acel havis ses filojn; jen estas iliaj nomoj: Azrikam, Boĥru, Iŝmael, Ŝearja, Obadja, kaj Ĥanan. Ĉiuj ĉi tiuj estis la filoj de Acel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'La filoj de lia frato Eŝek: lia unuenaskito estis Ulam, la dua estis Jeuŝ, kaj la tria estis Elifelet.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'La filoj de Ulam estis kuraĝaj militistoj, pafarkistoj, kaj ili havis multe da filoj kaj nepoj: cent kvindek. Ĉiuj ĉi tiuj estis el la Benjamenidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Ĉiuj Izraelidoj estis kalkulitaj, kaj ili estis enskribitaj en la libro de la reĝoj de Izrael. La Judojn oni forkondukis en Babelon pro iliaj malbonagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'La unuaj loĝantoj, kiuj loĝis en siaj posedaĵoj, en siaj urboj, estis Izraelidoj, pastroj, Levidoj, kaj Netinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'En Jerusalem loĝis parto de la idoj de Jehuda, de la idoj de Benjamen, kaj de la idoj de Efraim kaj de Manase:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Utaj, filo de Amihud, filo de Omri, filo de Imri, filo de Bani, el la idoj de Perec, filo de Jehuda;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'kaj el la Ŝiloanoj: Asaja, la unuenaskito, kaj liaj filoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'el la idoj de Zeraĥ: Jeuel, kaj iliaj fratoj, sescent naŭdek;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'el la Benjamenidoj: Salu, filo de Meŝulam, filo de Hodavja, filo de Hasenua,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'kaj Jibneja, filo de Jeroĥam, Ela, filo de Uzi, filo de Miĥri, kaj Meŝulam, filo de Ŝefatja, filo de Reuel, filo de Jibnija;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'kaj iliaj fratoj laŭ sia deveno, naŭcent kvindek ses. Ĉiuj ĉi tiuj estis ĉefoj de patrodomoj en siaj patrodomoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Kaj el la pastroj: Jedaja, Jehojarib, Jaĥin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'Azarja, filo de Ĥilkija, filo de Meŝulam, filo de Cadok, filo de Merajot, filo de Aĥitub, estro en la domo de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'kaj Adaja, filo de Jeroĥam, filo de Paŝĥur, filo de Malkija, kaj Maasaj, filo de Adiel, filo de Jaĥzera, filo de Meŝulam, filo de Meŝilemit, filo de Imer;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'kaj iliaj fratoj, ĉefoj de siaj patrodomoj, mil sepcent sesdek, tre lertaj en la laboro de la servado en la domo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'El la Levidoj: Ŝemaja, filo de Ĥaŝub, filo de Azrikam, filo de Ĥaŝabja, el la idoj de Merari;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'kaj Bakbakar, Ĥereŝ, Galal, Matanja, filo de Miĥa, filo de Ziĥri, filo de Asaf,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'Obadja, filo de Ŝemaja, filo de Galal, filo de Jedutun, Bereĥja, filo de Asa, filo de Elkana, kiu loĝis en la vilaĝoj de la Netofaanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Kaj la pordegistoj: Ŝalum, Akub, Talmon, Aĥiman, kaj iliaj fratoj; Ŝalum estis la ĉefo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'Kaj ĝis nun ĉe la reĝa pordego, oriente, ili estas pordegistoj el la anaro de la Levidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Ŝalum, filo de Kore, filo de Ebjasaf, filo de Koraĥ, kaj liaj fratoj el lia patrodomo, la Koraĥidoj, laŭ sia ofico estis gardistoj de la sojloj de la tabernaklo, kiel iliaj patroj ĉe la restejo de la Eternulo estis gardistoj de la eniro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Pineĥas, filo de Eleazar, en la antaŭa tempo estis ilia estro, kaj la Eternulo estis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Zeĥarja, filo de Meŝelemja, estis pordisto ĉe la tabernaklo de kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'La tuta nombro de tiuj, kiuj estis elektitaj kiel pordegistoj ĉe la sojloj, estis ducent dek du. Ili estis enregistritaj laŭ siaj vilaĝoj. Ilin starigis David, kaj Samuel, la antaŭvidisto, pro ilia fideleco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Ili kaj iliaj filoj estis gardistoj de la pordegoj en la domo de la Eternulo, la domo de la tabernaklo, laŭ deĵoroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Ĉe la kvar flankoj estis la pordegistoj: oriente, okcidente, norde, kaj sude.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Iliaj fratoj estis en siaj vilaĝoj, kaj ili devis nur de tempo al tempo, unu fojon en sep tagoj, veni al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'Ĉar konstante estis kvar estroj de pordegistoj, ili estis Levidoj; ili estis super la ĉambroj kaj super la trezoroj en la domo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'Ili noktadis ĉirkaŭ la domo de Dio, ĉar ili havis la devon gardi, kaj ili devis malfermi ĉiumatene.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Parto el ili estis super ĉiuj vazoj de la servado, laŭkalkule ili enportadis kaj laŭkalkule elportadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Parto el ili estis komisiita pri la ceteraj vazoj kaj pri ĉiuj sanktaj objektoj, pri la faruno, la vino, la oleo, la olibano, kaj la aromaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'El la pastridoj kelkaj pretigadis la ŝmiraĵojn el aromaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Al Matitja el la Levidoj, kiu estis unuenaskito de Ŝalum, Koraĥido, estis komisiitaj la aferoj de la patoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Al parto de la Kehatidoj, iliaj fratoj, estis komisiitaj la panoj de propono, kiujn ili devis pretigi por ĉiu sabato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'La kantistoj, ĉefoj de patrodomoj inter la Levidoj, estis liberaj de servado en la ĉambroj, ĉar tage kaj nokte ili devis sin okupadi per sia arto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Tio estas la ĉefoj de patrodomoj de la Levidoj en siaj generacioj. Ili loĝis en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'En Gibeon loĝis: Jeiel, la fondinto de Gibeon-la nomo de lia edzino estis Maaĥa-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'kaj lia unuenaskita filo Abdon, kaj Cur, Kiŝ, Baal, Ner, Nadab,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedor, Aĥjo, Zeĥarja, kaj Miklot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Miklot naskigis Ŝimamon. Ili ankaŭ apud siaj fratoj enloĝiĝis en Jerusalem kun siaj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Ner naskigis Kiŝon, Kiŝ naskigis Saulon, Saul naskigis Jonatanon, Malki-Ŝuan, Abinadabon, kaj Eŝbaalon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'La filo de Jonatan estis Merib-Baal, kaj Merib-Baal naskigis Miĥan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'La filoj de Miĥa estis: Piton, Meleĥ, kaj Taĥrea,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'kaj Aĥaz-li naskigis Jaaran, Jaara naskigis Alemeton, Azmaveton, kaj Zimrin; Zimri naskigis Mocan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'Moca naskigis Binean; lia filo estis Refaja, lia filo estis Eleasa, lia filo estis Acel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Acel havis ses filojn; jen estas iliaj nomoj: Azrikam, Boĥru, Iŝmael, Ŝearja, Obadja, kaj Ĥanan. Tio estis la filoj de Acel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Dume la Filiŝtoj batalis kontraŭ Izrael; kaj la Izraelidoj forkuris de la Filiŝtoj, kaj falis mortigitaj sur la monto Gilboa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Kaj la Filiŝtoj kuratingis Saulon kaj liajn filojn; kaj la Filiŝtoj mortigis Jonatanon kaj Abinadabon kaj Malki-Ŝuan, filojn de Saul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'La batalo fortiĝis kontraŭ Saul; kaj la arkpafistoj trovis lin, kaj li estis vundita de la arkpafistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Tiam Saul diris al sia armilportisto: Eltiru vian glavon, kaj trapiku min per ĝi, por ke ne venu tiuj necirkumciditoj kaj ne mokmalhonoru min. Sed lia armilportisto ne volis, ĉar li forte timis. Tiam Saul prenis sian glavon kaj faligis sin sur ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Kiam lia armilportisto vidis, ke Saul mortis, li ankaŭ faligis sin sur la glavon kaj mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Tiamaniere mortis Saul kaj liaj tri filoj, kaj lia tuta domo kune mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Kiam ĉiuj Izraelidoj, kiuj estis en la valo, vidis, ke oni forkuras kaj ke Saul kaj liaj filoj mortis, tiam ili forlasis siajn urbojn kaj forkuris; kaj venis la Filiŝtoj kaj enloĝiĝis en ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'En la sekvanta tago venis la Filiŝtoj, por senvestigi la mortigitojn, kaj ili trovis Saulon kaj liajn filojn falintajn sur la monto Gilboa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Kaj ili senvestigis lin kaj prenis lian kapon kaj liajn armilojn kaj sendis en la landon de la Filiŝtoj ĉirkaŭen, por anonci al iliaj idoloj kaj al la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Kaj ili metis liajn armilojn en la domon de siaj dioj, kaj lian kranion ili alfiksis en la domo de Dagon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Kiam la tuta Jabeŝ en Gilead aŭdis pri ĉio, kion faris la Filiŝtoj al Saul,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'tiam leviĝis ĉiuj kuraĝuloj, kaj prenis la korpon de Saul kaj la korpojn de liaj filoj kaj alportis lin en Jabeŝon, kaj enterigis iliajn ostojn sub la kverko en Jabeŝ, kaj fastis dum sep tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Tiamaniere mortis Saul pro siaj malbonagoj, kiujn li faris antaŭ la Eternulo, ne plenumante la vorton de la Eternulo; ankaŭ pro tio, ke li turnis sin al antaŭdiristino, por demandi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'sed ne demandis la Eternulon. Pro tio Li mortigis lin, kaj transdonis la reĝadon al David, filo de Jiŝaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Kaj kunvenis ĉiuj Izraelidoj al David en Ĥebronon, kaj diris: Jen ni estas via osto kaj via karno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Ankaŭ hieraŭ kaj antaŭhieraŭ, kiam Saul estis ankoraŭ reĝo, vi elkondukadis kaj enkondukadis Izraelon; kaj la Eternulo, via Dio, diris al vi: Vi paŝtos Mian popolon Izrael, kaj vi estos estro de Mia popolo Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Kaj ĉiuj plejaĝuloj de Izrael venis al la reĝo en Ĥebronon, kaj David faris kun ili interligon en Ĥebron antaŭ la Eternulo; kaj ili sanktoleis Davidon reĝo super Izrael, konforme al la vorto de la Eternulo per Samuel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Kaj David kaj ĉiuj Izraelidoj iris en Jerusalemon (tio estas, en Jebuson). Tie la Jebusidoj estis la loĝantoj de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Kaj la loĝantoj de Jebus diris al David: Vi ne eniros ĉi tien. Sed David venkoprenis la fortikaĵon Cion, tio estas, la urbon de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Kaj David diris: Kiu la unua venkobatos la Jebusidojn, tiu estos ĉefo kaj estro. Kaj la unua supreniris Joab, filo de Ceruja, kaj li fariĝis ĉefo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Kaj David ekloĝis en tiu fortikaĵo; pro tio oni donis al ĝi la nomon: Urbo de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Kaj li ĉirkaŭkonstruis la urbon ĉiuflanke, de Milo en la tuta ĉirkaŭo; kaj Joab restarigis la ceterajn partojn de la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'Kaj David fariĝadis ĉiam pli kaj pli granda, kaj la Eternulo Cebaot estis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Jen estas la ĉefaj herooj, kiuj estis ĉe David, kaj kiuj tenis sin forte kun li dum lia reĝado, kune kun la tuta Izrael, por reĝigi lin super Izrael konforme al la vorto de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Jen estas la nombro de la herooj, kiuj estis ĉe David: Jaŝobeam, filo de Ĥaĥmoni, estro de la tridek; li levis sian lancon kontraŭ tricent kaj mortigis ilin per unu fojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Post li estis Eleazar, filo de Dodo, la Aĥoĥido; li estis el la tri herooj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Li estis kun David en Pas-Damim, kie la Filiŝtoj kolektiĝis por batalo; tie estis kampoparto plena de hordeo; kaj la popolo forkuris antaŭ la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'Sed tiuj stariĝis meze de la kampoparto, kaj savis ĝin kaj venkobatis la Filiŝtojn; kaj la Eternulo helpis per granda helpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Kaj tri el la tridek ĉefoj iris sur la rokon al David, en la kavernon Adulam, dum la tendaro de la Filiŝtoj staris en la valo Refaim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'David tiam estis en la fortikaĵo, kaj la garnizono de la Filiŝtoj estis tiam en Bet-Leĥem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Kaj David esprimis deziron kaj diris: Kiu trinkigus al mi akvon el la puto Bet-Leĥema, kiu estas apud la pordego?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Tiam tiuj tri trarompe penetris en la tendaron de la Filiŝtoj, ĉerpis akvon el la puto Bet-Leĥema, kiu estis apud la pordego, prenis kaj alportis al David. Sed David ne volis trinki ĝin; li elverŝis ĝin al la Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'kaj diris: Gardu min mia Dio, ke mi ne faru tion: ĉu mi trinku la sangon de tiuj viroj, kiuj riskis sian vivon? ĉar kun risko por sia vivo ili alportis ĝin. Kaj li ne volis trinki ĝin. Tion faris la tri herooj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Abiŝaj, frato de Joab, estis estro de tiuj tri; li mortigis per sia lanco tricent homojn, kaj li havis gloran nomon inter la tri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'El la tri li estis honorata de du kaj estis ilia estro, sed en la trion li ne eniris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Benaja, filo de Jehojada, filo de homo kuraĝa, granda pro siaj faroj, el Kabceel: li mortigis la du fortulojn de Moab; li ankaŭ malsupreniris, kaj mortigis leonon en kavo en neĝa tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Li ankaŭ mortigis Egipton, viron, kiu havis la alton de kvin ulnoj; en la mano de la Egipto estis lanco kiel rultrabo de teksisto; li aliris al li kun bastono, elŝiris la lancon el la mano de la Egipto, kaj mortigis lin per lia propra lanco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Tion faris Benaja, filo de Jehojada. Kaj li havis gloran nomon inter la tri herooj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Inter la tridek li estis plej honorata, sed en la trion li ne eniris. Kaj David faris lin lia korpogardistestro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'La ĉefaj militistoj estis: Asahel, frato de Joab, Elĥanan, filo de Dodo, el Bet-Leĥem,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Ŝamot, la Harorano, Ĥelec, la Pelonano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Ira, filo de Ikeŝ, la Tekoaano, Abiezer, la Anatotano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Sibĥaj, la Ĥuŝaido, Ilaj, la Aĥoĥido,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maharaj, la Netofaano, Ĥeled, filo de Baana, la Netofaano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Itaj, filo de Ribaj, el Gibea de la Benjamenidoj, Benaja, la Piratonano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Ĥuraj, el Naĥale-Gaaŝ, Abiel, la Arbatano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Azmavet, la Baĥurimano, Eljaĥba, la Ŝaalbonano;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'el la filoj de Haŝem, la Gizonano: Jonatan, filo de Ŝage, la Hararano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Aĥiam, filo de Saĥar, la Hararano, Elifal, filo de Ur,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Ĥefer, la Meĥeratano, Aĥija, la Pelonano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Ĥecro, la Karmelano, Naaraj, filo de Ezbaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joel, frato de Natan, Mibĥar, filo de Hagri,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Celek, la Amonido, Naĥaraj, la Beerotano, armilportisto de Joab, filo de Ceruja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Ira, la Jetrido, Gareb, la Jetrido,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Urija, la Ĥetido, Zabad, filo de Aĥlaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adina, filo de Ŝiza, la Rubenido, ĉefo de Rubenidoj, kaj kun li estis tridek,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Ĥanan, filo de Maaĥa, Joŝafat, la Mitnido,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Uzija, la Aŝterotano, Ŝama kaj Jeiel, filoj de Ĥotam, la Aroerano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediael, filo de Ŝimri, kaj lia frato Joĥa, la Ticano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliel, la Maĥavido, Jeribaj kaj Joŝavja, filoj de Elnaam, Jitma, la Moabido,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel, Obed, kaj Jaasiel el Mecobaja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Jen estas tiuj, kiuj venis al David en Ciklagon, kiam li estis ankoraŭ kaŝita antaŭ Saul, filo de Kiŝ; ili ankaŭ estis inter la herooj, helpantoj en la milito;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'armitaj per pafarko, povosciantaj ĵeti ŝtonojn kaj pafarkajn sagojn per la dekstra mano kaj per la maldekstra, el la fratoj de Saul, Benjamenidoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'la ĉefo Aĥiezer, kaj Joaŝ, filoj de Ŝemaa, la Gibeaano, Jeziel kaj Pelet, filoj de Azmavet, Beraĥa, kaj Jehu, la Anatotano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'Jiŝmaja, la Gibeonano, heroo el tridek kaj super tridek, Jeremia, Jaĥaziel, Joĥanan, kaj Jozabad, la Gederaano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Eluzaj, Jerimot, Bealja, Ŝemarja, kaj Ŝefatja, la Ĥarufano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elkana, Jiŝija, Azarel, Joezer, kaj Jaŝobeam, la Koraĥidoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Joela kaj Zebadja, filoj de Jeroĥam, el Gedor.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'El la Gadidoj apartiĝis al David en la fortikigitan lokon en la dezerto kuraĝaj militistoj, kapablaj batalistoj, armitaj per ŝildo kaj lanco; iliaj vizaĝoj estis kiel vizaĝo de leono, kaj rapidkuraj ili estis, kiel gazeloj sur la montoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Ezer estis la ĉefo, Obadja la dua, Eliab la tria,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Miŝmana la kvara, Jeremia la kvina,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Ataj la sesa, Eliel la sepa,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Joĥanan la oka, Elzabad la naŭa,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Jeremia la deka, Maĥbanaj la dek-unua.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Ĉi tiuj el la Gadidoj estis ĉefoj en la militistaro: la plej malgranda estis super cent, kaj la plej granda super mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Ili estis tiuj, kiuj transiris Jordanon en la unua monato, kiam ĝi inundis siajn ambaŭ bordojn, kaj ili dispelis ĉiujn loĝantojn de la valoj orienten kaj okcidenten.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Ankaŭ el la idoj de Benjamen kaj de Jehuda oni venis en la fortikigitan lokon al David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Kaj David eliris renkonte al ili, kaj ekparolis kaj diris al ili: Se vi venis al mi kun paco, por helpi al mi, mia koro estos kun vi; sed se por ruze transdoni min al miaj malamikoj, kvankam miaj manoj estas senkulpaj, tiam vidu tion Dio de niaj patroj, kaj Li juĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Kaj spirito venis sur Amasajon, la estron de la herooj, kaj li diris: Al vi, ho David, kaj kun vi, ho filo de Jiŝaj, estu paco; paco al vi, kaj paco al viaj helpantoj, ĉar al vi helpas via Dio. Kaj David ilin akceptis kaj faris ilin ĉefoj de la militistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Ankaŭ el la Manaseidoj oni aliĝis al David, kiam li iris kun la Filiŝtoj milite kontraŭ Saulon, sed ne helpis al ili; ĉar post konsiliĝo la estroj de la Filiŝtoj forsendis lin, dirante: Kun niaj kapoj li aliĝos al sia sinjoro Saul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Kiam li venis en Ciklagon, aliĝis al li el la Manaseidoj: Adnaĥ, Jozabad, Jediael, Miĥael, Jozabad, Elihu, kaj Ciltaj, milestroj de la Manaseidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Kaj ili helpis al David kontraŭ la militistoj, ĉar ili ĉiuj estis herooj, kaj ili estis estroj en militistaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Ĉiutage oni venis pli al David, por helpi al li, ĝis kolektiĝis granda armeo, kiel armeo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Jen estas la nombro de la ĉefaj armitaj militistoj, kiuj venis al David en Ĥebronon, por transdoni al li la regnon de Saul, konforme al la vorto de la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'da Jehudaidoj, portantaj ŝildon kaj lancon, estis ses mil okcent armitaj por la militistaro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'el la Simeonidoj, batalkapablaj por la militistaro, estis sep mil cent;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'el la Levidoj estis kvar mil sescent;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'kaj Jehojada, estro de Aaronidoj, kaj kun li tri mil sepcent;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'kaj Cadok, kuraĝa junulo, kaj lia patrodomo, dudek du estroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'el la Benjamenidoj, samtribanoj de Saul, tri mil; ĝis tiam la plimulto el ili fidele servis al la domo de Saul;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'el la Efraimidoj dudek mil okcent kuraĝaj militistoj, viroj famaj en siaj patrodomoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'el la duontribo de Manase dek ok mil, kiuj estis vokitaj laŭnome, por iri reĝigi Davidon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'el la Isaĥaridoj, kiuj komprenis la cirkonstancojn, kaj sciis, kion Izrael devas fari, estis ducent ĉefoj, kaj ĉiuj iliaj fratoj agis laŭ iliaj vortoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'el la Zebulunidoj, militkapablaj, kaj irantaj en militon kun ĉiaj bataliloj, estis kvindek mil, por enviciĝi en konkordo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'el la Naftaliidoj estis mil estroj, kaj kun ili tridek sep mil kun ŝildoj kaj lancoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'el la Danidoj, armitaj por milito, estis dudek ok mil sescent;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'el la Aŝeridoj, militkapablaj kaj pretaj por milito, kvardek mil;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'de trans Jordan, el la Rubenidoj, la Gadidoj, kaj la duontribo de Manase, kun ĉiaj militaj bataliloj, cent dudek mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Ĉiuj tiuj militistoj, prezentantaj aranĝitajn vicojn, venis plenkore en Ĥebronon, por fari Davidon reĝo super la tuta Izrael; ankaŭ ĉiuj ceteraj Izraelidoj estis unuanimaj, por reĝigi Davidon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Kaj ili restis tie kun David dum tri tagoj, manĝis kaj trinkis; ĉar iliaj fratoj pretigis por ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'ankaŭ tiuj, kiuj estis proksime de ili, ĝis Isaĥar, Zebulun, kaj Naftali, alportadis al ili sur azenoj, kameloj, muloj, kaj bovoj manĝaĵon el faruno, premitajn figojn, sekvinberojn, vinon, oleon, bovojn, kaj ŝafojn en granda kvanto; ĉar estis ĝojo en Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'David konsiliĝis kun la milestroj, centestroj, kaj ĉiuj ĉefoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'kaj David diris al la tuta komunumo de Izrael: Se plaĉas al vi, kaj se tio estas de la Eternulo, nia Dio, ni dissendu ĉiuflanken al ĉiuj ceteraj niaj fratoj en ĉiujn regionojn de Izrael, kaj samtempe al la pastroj kaj Levidoj en la urbojn de ilia loĝado, ke ili kolektiĝu al ni;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'kaj ni transportu al ni la keston de nia Dio, ĉar ni ne turnis nin al Li en la tempo de Saul.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Kaj la tuta komunumo diris, ke oni tiel agu; ĉar la afero plaĉis al la tuta popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Tiam David kolektis la tutan Izraelon, de Ŝiĥor la Egipta ĝis Ĥamat, por ke oni venigu la keston de Dio el Kirjat-Jearim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Kaj David kun la tuta Izrael iris en Baalan, en Kirjat-Jearimon, kiu troviĝas en Judujo, por venigi de tie la keston de Dio, de la Eternulo, kiu sidas sur la keruboj, kie estas vokata Lia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'Kaj oni veturigis la keston de Dio sur nova veturilo el la domo de Abinadab, kaj Uza kaj Aĥjo kondukis la veturilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Kaj David kaj ĉiuj Izraelidoj ludis antaŭ Dio per la tuta forto, kun kantoj, harpoj, psalteroj, tamburinoj, cimbaloj, kaj trumpetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Kiam ili alvenis al la draŝejo de Kidon, Uza etendis sian manon, por subteni la keston, ĉar la bovoj klinpuŝis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Tiam ekflamis la kolero de la Eternulo kontraŭ Uza, kaj Li mortigis lin pro tio, ke li etendis sian manon al la kesto; kaj li mortis tie antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Kaj afliktiĝis David pro tio, ke la Eternulo frapis Uzan, kaj li donis al tiu loko la nomon Perec-Uza, ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'Kaj David ektimis Dion en tiu tago, kaj diris: Kiamaniere mi enportos al mi la keston de Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Kaj David ne transportigis la keston al si, en la urbon de David, sed li direktis ĝin en la domon de Obed-Edom, la Gatano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'Kaj la kesto de Dio restis kun la familio de Obed-Edom en lia domo dum tri monatoj; kaj la Eternulo benis la domon de Obed-Edom, kaj ĉion, kio apartenis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Ĥiram, reĝo de Tiro, sendis al David senditojn, kaj cedran lignon, kaj masonistojn kaj ĉarpentistojn, por ke ili konstruu por li domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'Kaj David konsciis, ke la Eternulo fortikigis lin kiel reĝon super Izrael, ke lia regno leviĝis alte pro Lia popolo Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Kaj David prenis ankoraŭ edzinojn en Jerusalem, kaj David naskigis ankoraŭ filojn kaj filinojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Kaj jen estas la nomoj de tiuj, kiuj naskiĝis al li en Jerusalem: Ŝamua kaj Ŝobab, Natan kaj Salomono');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'kaj Jibĥar kaj Eliŝua kaj Elpelet');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'kaj Noga kaj Nefeg kaj Jafia');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'kaj Eliŝama kaj Beeljada kaj Elifelet.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Kiam la Filiŝtoj aŭdis, ke David estas oleita kiel reĝo super la tuta Izrael, tiam ĉiuj Filiŝtoj iris, por serĉi Davidon. David aŭdis pri tio, kaj li eliris kontraŭ ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Kaj la Filiŝtoj venis kaj okupis la valon Refaim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Kaj David demandis Dion, dirante: Ĉu mi iru kontraŭ la Filiŝtojn? kaj ĉu Vi transdonos ilin en mian manon? Kaj la Eternulo diris al li: Iru, ĉar Mi transdonos ilin en vian manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Kaj ili iris al Baal-Peracim, kaj David venkobatis ilin tie. Kaj David diris: Dio disbatis miajn malamikojn per mia mano, kiel oni disbatas akvon. Tial oni donis al tiu loko la nomon Baal-Peracim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Kaj ili lasis tie siajn diojn; kaj David ordonis, ke oni forbruligu ilin per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Kaj denove venis la Filiŝtoj kaj okupis la valon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Tiam David denove demandis Dion, kaj Dio diris al li: Ne iru post ili, deturnu vin de ili, kaj venu al ili de la flanko de la morusarboj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'kaj kiam vi ekaŭdos la sonon de paŝoj sur la supro de la morusarboj, tiam komencu la batalon; ĉar Dio eliris antaŭ vi, por frapi la tendaron de la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'Kaj David faris, kiel ordonis al li Dio; kaj ili venkobatis la tendaron de la Filiŝtoj de Gibeon ĝis Gezer.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Kaj la nomo de David fariĝis fama en ĉiuj landoj; kaj la Eternulo faris lin timata de ĉiuj nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Li konstruis al si domojn en la urbo de David, kaj pretigis lokon por la kesto de Dio, kaj etendis tendon super ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Tiam David diris: Neniu portu la keston de Dio krom la Levidoj; ĉar ilin la Eternulo elektis, por ke ili portu la keston de Dio kaj servu al Li eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Kaj David kunvenigis ĉiujn Izraelidojn en Jerusalemon, por porti la keston de la Eternulo sur ĝian lokon, kiun li pretigis por ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Kaj David kunvenigis la idojn de Aaron kaj la Levidojn:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'el la idoj de Kehat estis: la estro Uriel kaj liaj fratoj, cent dudek;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'el la idoj de Merari: la estro Asaja kaj liaj fratoj, ducent dudek;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'el la idoj de Gerŝon: la estro Joel kaj liaj fratoj, cent tridek;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'el la idoj de Elicafan: la estro Ŝemaja kaj liaj fratoj, ducent;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'el la idoj de Ĥebron: la estro Eliel kaj liaj fratoj, okdek;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'el la idoj de Uziel: la estro Aminadab kaj liaj fratoj, cent dek du.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Kaj David alvokis la pastrojn Cadok kaj Ebjatar, kaj la Levidojn Uriel, Asaja, Joel, Ŝemaja, Eliel, kaj Aminadab;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'kaj li diris al ili: Vi, ĉefoj de patrodomoj de la Levidoj, sanktigu vin kaj viajn fratojn, kaj alportu la keston de la Eternulo, Dio de Izrael, sur la lokon, kiun mi pretigis por ĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'ĉar antaŭe, kiam ne vi tion faris, la Eternulo, nia Dio, frapis nin pro tio, ke ni serĉis Lin ne tiel, kiel oni devas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Kaj sanktigis sin la pastroj kaj la Levidoj, por porti la keston de la Eternulo, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Kaj la idoj de Levi ekportis la keston de Dio, kiel ordonis Moseo laŭ la vorto de la Eternulo, sur siaj ŝultroj, per stangoj sur ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Kaj David diris al la estroj de la Levidoj, ke ili starigu siajn fratojn la kantistojn kun muzikaj instrumentoj, psalteroj, harpoj, kaj laŭtaj cimbaloj, por ke alte aŭdiĝu la sonoj de ĝojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Kaj la Levidoj starigis Hemanon, filon de Joel, kaj el liaj fratoj Asafon, filon de Bereĥja, kaj el la idoj de Merari, siaj fratoj, Etanon, filon de Kuŝaja;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'kaj kun ili iliajn duagradajn fratojn: Zeĥarja, Ben, Jaaziel, Ŝemiramot, Jeĥiel, Uni, Eliab, Benaja, Maaseja, Matitja, Eliflehu, Mikneja, Obed-Edom, kaj Jeiel, kiel pordegistojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'La kantistoj Heman, Asaf, kaj Etan estis por ludado sur kupraj cimbaloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Zeĥarja, Aziel, Ŝemiramot, Jeĥiel, Uni, Eliab, Maaseja, kaj Benaja- sur psalteroj, por sopranuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'Matitja, Eliflehu, Mikneja, Obed-Edom, Jeiel, kaj Azazja-sur harpoj, por basuloj, por antaŭkanti;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Kenanja, la estro de la Levidoj-por aranĝado; li aranĝadis la muzikon, ĉar li estis kompetentulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Bereĥja kaj Elkana estis pordogardistoj ĉe la kesto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Ŝebanja, Joŝafat, Netanel, Amasaj, Zeĥarja, Benaja, kaj Eliezer, la pastroj, trumpetadis per trumpetoj antaŭ la kesto de Dio; Obed-Edom kaj Jeĥija estis pordogardistoj ĉe la kesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'Tiamaniere iris David kaj la plejaĝuloj de Izrael kaj la milestroj, por transporti kun ĝojo la keston de interligo de la Eternulo el la domo de Obed-Edom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Kaj kiam Dio helpis al la Levidoj, kiuj portis la keston de interligo de la Eternulo, oni oferbuĉis sep bovojn kaj sep ŝafojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'David estis vestita per tuniko el delikata tolo, ankaŭ ĉiuj Levidoj, kiuj portis la keston, la kantistoj, kaj Kenanja, la estro de aranĝado de la ĥoroj; David ankaŭ havis sur si linan efodon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Kaj ĉiuj Izraelidoj akompanis la keston de interligo de la Eternulo, kun ĝojkrioj, kun sonado de korno, kun trumpetoj, laŭtaj cimbaloj, psalteroj, kaj harpoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Kiam la kesto de interligo de la Eternulo venis al la urbo de David, Miĥal, filino de Saul, rigardis tra la fenestro; kaj kiam ŝi vidis, ke la reĝo David saltas kaj ludas, ŝi ekmalestimis lin en sia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Kaj oni alportis la keston de Dio, kaj metis ĝin interne de la tendo, kiun David starigis por ĝi; kaj oni alportis bruloferojn kaj pacoferojn antaŭ Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Kiam David finis la oferadon de la bruloferoj kaj de la pacoferoj, li benis la popolon en la nomo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Kaj li disdonis al ĉiuj Izraelidoj, kiel al la viroj, tiel ankaŭ al la virinoj, al ĉiu po unu bulo da pano, po unu porcio da viando, kaj po unu peniko da sekvinberoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Kaj li starigis antaŭ la kesto de la Eternulo el la Levidoj servantojn, por kantadi gloron, dankon, kaj laŭdon al la Eternulo, Dio de Izrael:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'la ĉefo estis Asaf, la dua estis Zeĥarja, poste Jeiel, Ŝemiramot, Jeĥiel, Matitja, Eliab, Benaja, Obed-Edom, kaj Jeiel, kun psalteroj kaj harpoj, kaj Asaf sonigadis per cimbaloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'Benaja kaj Jaĥaziel, la pastroj, estis kun trumpetoj ĉiam antaŭ la kesto de interligo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Tiam, en tiu tago, David la unuan fojon aranĝis dankokanton al la Eternulo per Asaf kaj liaj fratoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Gloru la Eternulon, voku Lian nomon; Sciigu inter la popoloj Liajn farojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Kantu al Li, muziku al Li; Parolu pri ĉiuj Liaj mirakloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Laŭdu Lian sanktan nomon; Ĝoju la koro de tiuj, kiuj serĉas la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Turnu vin al la Eternulo kaj al Lia potenco; Serĉu ĉiam Lian vizaĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Memoru Liajn miraklojn, kiujn Li faris; Liajn signomiraklojn kaj la juĝojn de Lia buŝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'Vi, semo de Izrael, Lia sklavo, Filoj de Jakob, Liaj elektitoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Li estas la Eternulo, nia Dio; Sur la tuta tero estas Liaj juĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Memoru eterne Lian interligon, La vorton, kiun Li testamentis por mil generacioj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'Kiun Li interkonsentis kun Abraham Kaj ĵuris al Isaak.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'Li metis ĝin por Jakob kiel leĝon, Por Izrael kiel eternan interligon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Dirante: Al vi Mi donos la landon Kanaanan Kiel vian parton heredan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Kiam vi estis malgrandnombraj, Malmultaj, kaj fremduloj en ĝi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Kaj ili iradis de popolo al popolo, El unu regno al alia gento,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Tiam Li al neniu permesis premi ilin, Kaj Li punis pro ili reĝojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'Dirante: Ne tuŝu Miajn sanktoleitojn, Kaj al Miaj profetoj ne faru malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Kantu al la Eternulo la tuta tero; Proklamu de tago al tago Lian savon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Rakontu inter la popoloj Lian gloron, Inter ĉiuj gentoj Liajn miraklojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Ĉar la Eternulo estas granda kaj tre glorinda; Li estas timinda super ĉiuj dioj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Ĉar ĉiuj dioj de la popoloj estas idoloj; Sed la Eternulo kreis la ĉielon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Gloro kaj majesto estas antaŭ Li; Forto kaj beleco estas sur Lia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Tributu al la Eternulo, familioj de la popoloj; Tributu al la Eternulo gloron kaj potencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Tributu al la Eternulo honoron de Lia nomo; Alportu donacon, kaj venu antaŭ Lin; Adorkliniĝu antaŭ la Eternulo en sankta ornamo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Tremu antaŭ Li la tuta tero; Li aranĝis ja la mondon, ke ĝi ne ŝanceliĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Ĝoju la ĉielo, kaj estu gaja la tero; Kaj oni diru inter la nacioj: La Eternulo reĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Bruu la maro, kaj ĉio, kio ĝin plenigas; Ĝoju la kampo, kaj ĉio, kio estas sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Tiam kantu ĉiuj arboj de la arbaro antaŭ la Eternulo, Ĉar Li venas, por juĝi la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Laŭdu la Eternulon, ĉar Li estas bona; Ĉar eterna estas Lia favorkoreco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Kaj diru: Savu nin, ho Dio de nia savo, Kolektu nin kaj liberigu nin el inter la nacioj, Por ke ni danku Vian sanktan nomon, Por ke ni gloru nin per Via majesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Benata estu la Eternulo, Dio de Izrael, De eterne ĝis eterne. Kaj la tuta popolo diris: Amen! kaj gloro al la Eternulo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Kaj li restigis tie antaŭ la kesto de interligo de la Eternulo Asafon kaj liajn fratojn, por servadi antaŭ la kesto konstante, laŭ la ordo de ĉiu tago;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'kaj Obed-Edomon kaj liajn fratojn, sesdek ok; Obed-Edom, filo de Jedutun, kaj Ĥosa, restis kiel pordegistoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'kaj la pastron Cadok kaj liajn fratojn, la pastrojn, antaŭ la loĝejo de la Eternulo sur la altaĵo en Gibeon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'por ke ili alportadu bruloferojn al la Eternulo sur la altaro de bruloferoj konstante, matene kaj vespere, kaj por ĉio, kio estas skribita en la instruo de la Eternulo, kiun Li donis al Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'Kaj kun ili estis Heman kaj Jedutun, kaj la aliaj elektitoj, difinitaj laŭnome, por kantadi laŭdon al la Eternulo, ĉar eterna estas Lia favorkoreco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'kun ili estis Heman kaj Jedutun, kun trumpetoj kaj cimbaloj kaj aliaj instrumentoj por kantado antaŭ Dio; kaj la filoj de Jedutun estis ĉe la pordego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Kaj la tuta popolo disiris ĉiu en sian domon; kaj David iris returne, por beni sian domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Kiam David loĝis en sia domo, li diris unu fojon al la profeto Natan: Jen mi loĝas en domo cedroligna, kaj la kesto de interligo de la Eternulo restas sub tapiŝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Kaj Natan diris al David: Ĉion, kio estas sur via koro, faru, ĉar Dio estas kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Sed en tiu sama nokto aperis vorto de Dio al Natan, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Iru, kaj diru al Mia servanto David: Tiele diras la Eternulo: Ne vi konstruos por Mi la domon por loĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'ĉar Mi ne loĝis en domo de post tiu tago, kiam Mi elkondukis Izraelon, ĝis la nuna tempo; sed Mi estis nur en tabernaklo kaj en tendo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Kien ajn Mi iris kun la tuta Izrael, ĉu Mi diris eĉ unu vorton al iu el la juĝistoj de Izrael, al kiuj Mi ordonis paŝti Mian popolon, dirante: Kial vi ne konstruis por Mi cedrolignan domon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Kaj nun diru jenon al Mia servanto David: Tiele diras la Eternulo Cebaot: Mi prenis vin de ŝafejo, de ŝafoj, por ke vi estu estro super Mia popolo Izrael;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'kaj Mi estis kun vi ĉie, kien vi iris; kaj Mi ekstermis ĉiujn viajn malamikojn antaŭ vi, kaj Mi faris al vi nomon, egalan al la nomoj de la potenculoj sur la tero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'kaj Mi aranĝis lokon por Mia popolo Izrael, kaj Mi plantis ĝin tiel, ke ĝi loĝu trankvile sur sia loko kaj ne plu tremu; kaj malbonuloj ne plu senfortigos ĝin, kiel antaŭe;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'kaj de post tiu tempo, kiam Mi starigis juĝistojn super Mia popolo Izrael, Mi humiligis ĉiujn viajn malamikojn; kaj Mi diras al vi, ke domon konstruos al vi la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Kiam finiĝos viaj tagoj kaj vi iros al viaj patroj, Mi starigos post vi vian idon, kiu estos el viaj filoj; kaj Mi fortikigos lian regnon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Li konstruos por Mi domon; kaj Mi fortikigos lian tronon por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Mi estos al li patro, kaj li estos al Mi filo; kaj Mian favorkorecon Mi ne deturnos de li tiel, kiel Mi deturnis de tiu, kiu estis antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Kaj Mi starigos lin en Mia domo kaj en Mia regno por ĉiam; kaj lia trono estos fortikigita por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Konforme al ĉiuj ĉi tiuj vortoj kaj al ĉi tiu tuta vizio, Natan parolis al David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Kaj venis la reĝo David kaj sidiĝis antaŭ la Eternulo, kaj diris: Kiu estas mi, ho Dio Eternulo, kaj kio estas mia domo, ke Vi venigis min ĝis ĉi tie?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Sed eĉ tio estis nesufiĉa antaŭ Vi, ho Dio, kaj Vi parolis pri la domo de Via servanto eĉ por la malproksima estonteco, kaj Vi rigardis min kiel homon alte starantan, ho Dio Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Kion pli David povas diri al Vi, por honori Vian servanton? Vi konas ja Vian servanton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Ho Eternulo, por Via servanto kaj laŭ Via koro Vi faris tiun tutan grandaĵon, por montri ĉian grandecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Ho Eternulo, ne ekzistas simila al Vi, kaj ne ekzistas Dio krom Vi, laŭ ĉio, kion ni aŭdis per niaj oreloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Kaj kiu estas simila al Via popolo Izrael, la sola popolo sur la tero, koncerne kiun Dio iris, por elaĉeti ĝin al Si kiel popolon, por fari al Si nomon per grandaĵoj kaj timindaĵoj, forpelante naciojn antaŭ Via popolo, kiun Vi liberigis el Egiptujo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Vi faris Vian popolon Izrael Via popolo por eterne; kaj Vi, ho Eternulo, faris Vin Dio por ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Kaj nun, ho Eternulo, la vorto, kiun Vi diris pri Via servanto kaj pri lia domo, veriĝu por eterne, kaj Vi agu tiel, kiel Vi diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Kaj Via nomo estu vera kaj granda por eterne, por ke oni diru: La Eternulo Cebaot, Dio de Izrael, estas Dio al Izrael; kaj la domo de Via servanto David estu fortika antaŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Ĉar Vi, ho mia Dio, sciigis al la orelo de Via servanto, ke Vi konstruos al li domon; tial Via servanto trovis kuraĝon preĝi antaŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Kaj nun, ho Eternulo, Vi estas Dio, kaj Vi diris pri Via servanto ĉi tiun bonaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Nun komencu beni la domon de Via servanto, ke ĝi restu eterne antaŭ Vi; ĉar kion Vi, ho Eternulo, benas, tio restas benita por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Post tio okazis, ke David venkobatis la Filiŝtojn kaj humiligis ilin, kaj li prenis Gaton kaj ĝiajn filinurbojn el la manoj de la Filiŝtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Li ankaŭ venkobatis la Moabidojn, kaj la Moabidoj submetiĝis al David kaj alportis tributojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Kaj David venkobatis Hadarezeron, reĝon de Coba, en Ĥamat, kiam tiu iris, por fortikigi sian regadon super la rivero Eŭfrato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Kaj David venkoprenis de li mil ĉarojn kaj sep mil rajdantojn kaj dudek mil piedirantojn; kaj David lamigis ĉiujn ĉarĉevalojn, sed restigis el ili por cent ĉaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'La Sirianoj Damaskaj venis, por helpi al Hadarezer, reĝo de Coba; sed David venkobatis el la Sirianoj dudek du mil homojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Kaj David restigis garnizonojn en la Damaska Sirio, kaj la Sirianoj submetiĝis al David kaj alportis tributojn. Kaj la Eternulo helpis al David ĉie, kien li iris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Kaj David prenis la orajn ŝildojn, kiujn havis sur si la servantoj de Hadarezer, kaj alportis ilin en Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Kaj el Tibĥat kaj el Kun, urboj de Hadarezer, David prenis tre multe da kupro, el kiu poste Salomono faris la kupran maron, la kolonojn, kaj la kuprajn vazojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Kiam Tou, reĝo de Ĥamat, aŭdis, ke David venkobatis la tutan militistaron de Hadarezer, reĝo de Coba,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'tiam li sendis sian filon Hadoram al la reĝo David, por saluti lin, kaj gratuli lin pri tio, ke li militis kontraŭ Hadarezer kaj venkobatis lin (ĉar Tou estis en milito kontraŭ Hadarezer); kaj li havis kun si ĉiaspecajn vazojn el oro, arĝento, kaj kupro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Ankaŭ ĉi tiujn David dediĉis al la Eternulo, kune kun la arĝento kaj oro, kiun li prenis de ĉiuj nacioj: de Edom, de Moab, de la Amonidoj, de la Filiŝtoj, kaj de Amalek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Plue Abiŝaj, filo de Ceruja, venkobatis Edomon en la Valo de Salo, dek ok mil homojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'kaj li restigis en Edomujo garnizonojn, kaj ĉiuj Edomidoj submetiĝis al David. Kaj la Eternulo helpis al David ĉie, kien li iris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Kaj David reĝis super la tuta Izrael, kaj li faradis juĝon kaj justecon al sia tuta popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Joab, filo de Ceruja, estis estro de la militistaro; Jehoŝafat, filo de Aĥilud, estis kronikisto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Cadok, filo de Aĥitub, kaj Abimeleĥ, filo de Ebjatar, estis pastroj; kaj Ŝavŝa estis skribisto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Benaja, filo de Jehojada, estis super la Keretidoj kaj la Peletidoj; kaj la filoj de David estis la unuaj apud la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Okazis poste, ke mortis Naĥaŝ, reĝo de la Amonidoj, kaj lia filo fariĝis reĝo anstataŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Tiam David diris: Mi estos favorkora al Ĥanun, filo de Naĥaŝ, ĉar lia patro agis favorkore koncerne min. Kaj David sendis senditojn, por konsoli lin pri lia patro. Kaj la servantoj de David venis en la landon de la Amonidoj, al Ĥanun, por lin konsoli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'Sed la eminentuloj de la Amonidoj diris al Ĥanun: Ĉu efektive David deziras honori vian patron antaŭ vi, ke li sendis al vi konsolantojn? ĉu ne venis al vi liaj servantoj nur por esplori, por ruinigi, kaj por esplorrigardi la landon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Tiam Ĥanun prenis la servantojn de David, razigis ilin, detranĉis iliajn vestojn ĝis duono, ĝis la lumboj, kaj foririgis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Kaj ili iris. Kaj oni raportis al David pri tiuj viroj, kaj li sendis renkonte al ili, ĉar la viroj tre hontis. Kaj la reĝo diris: Restu en Jeriĥo, ĝis rekreskos viaj barboj, kaj tiam revenu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Kiam la Amonidoj vidis, ke ili indignigis kontraŭ si Davidon, tiam Ĥanun kaj la Amonidoj sendis mil kikarojn da arĝento, por dungi al si el Mezopotamio, el Sirio de Maaĥa, kaj el Coba ĉarojn kaj rajdistojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Kaj ili dungis al si tridek du mil ĉarojn kaj la reĝon de Maaĥa kun lia popolo. Kaj ili venis kaj stariĝis tendare antaŭ Medba. Kaj la Amonidoj kolektiĝis el siaj urboj kaj venis al la milito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Kiam David aŭdis pri tio, li sendis Joabon kaj la tutan armeon da kuraĝuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Kaj la Amonidoj eliris, kaj batalaranĝiĝis antaŭ la enirejo de la urbo; kaj la reĝoj venintaj aranĝiĝis aparte, sur la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Kiam Joab vidis, ke li havos kontraŭ si batalon antaŭe kaj malantaŭe, li faris elekton el ĉiuj plejbravuloj en Izrael kaj batalaranĝis ilin kontraŭ la Sirianoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'la ceteran parton de la popolo li komisiis al sia frato Abiŝaj, kaj ili batalaranĝis sin kontraŭ la Amonidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Kaj li diris: Se la Sirianoj superfortos min, tiam vi donos al mi helpon; sed se la Amonidoj superfortos vin, tiam mi donos al vi helpon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'estu kuraĝa, kaj ni tenu nin forte pro nia popolo kaj pro la urboj de nia Dio; kaj la Eternulo faru tion, kio plaĉos al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Kaj Joab, kun la popolo, kiu estis kun li, komencis la batalon kontraŭ la Sirianoj, kaj ĉi tiuj forkuris antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Kiam la Amonidoj vidis, ke la Sirianoj forkuris, ili ankaŭ forkuris antaŭ lia frato Abiŝaj, kaj foriris en la urbon. Kaj Joab venis Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Vidante, ke ili estas venkobatitaj de la Izraelidoj, la Sirianoj sendis senditojn kaj elirigis la Sirianojn transriverajn; kaj Ŝofaĥ, la militestro de Hadarezer, ilin kondukis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Kiam tio estis raportita al David, li kolektis ĉiujn Izraelidojn, transiris Jordanon, venis al ili, kaj batalaranĝiĝis kontraŭ ili; David aranĝis batalon kontraŭ la Sirianoj, kaj ili interbatalis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Kaj la Sirianoj forkuris antaŭ Izrael, kaj David mortigis el la Sirianoj sep mil ĉaristojn kaj kvardek mil piedirantojn; ankaŭ Ŝofaĥon, la militestron, li mortigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Kiam la servantoj de Hadarezer vidis, ke ili estas venkobatitaj de la Izraelidoj, ili faris pacon kun David kaj submetiĝis al li. Kaj la Sirianoj ne volis plu helpi al la Amonidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Post paso de unu jaro, en la tempo, kiam la reĝoj eliras milite, Joab kondukis la militistaron kaj komencis ruinigi la landon de la Amonidoj, kaj li venis kaj eksieĝis Raban. Sed David restis en Jerusalem. Kaj Joab venkobatis Raban kaj detruis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Kaj David prenis la kronon de Malkam de lia kapo; li trovis, ke ĝi enhavas laŭpeze kikaron da oro, kaj estis en ĝi multekosta ŝtono, kiu transiris sur la kapon de David. Kaj da militakiraĵo li elportis el la urbo tre multe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Kaj la popolon, kiu estis tie, li elirigis, kaj mortigis per segiloj, feraj draŝiloj, kaj hakiloj. Tiele David agis kun ĉiuj urboj de la Amonidoj. Kaj David kun la tuta popolo revenis Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Post tio komenciĝis milito en Gezer, kontraŭ la Filiŝtoj; tiam Sibĥaj, la Ĥuŝaido, mortigis Sipajon, unu el la infanoj de la giganto. Kaj ili humiliĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Kaj denove estis milito kun la Filiŝtoj; kaj Elĥanan, filo de Jair, mortigis Laĥmin, fraton de Goljat, la Gatano, ĉe kiu la tenilo de lia lanco estis kiel rultrabo de teksisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Kaj denove estis milito en Gat; tie estis viro tre altkreska, kiu havis po ses fingroj, sume dudek kvar; li ankaŭ naskiĝis al la giganto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Kiam li insultis Izraelon, lin mortigis Jonatan, filo de Ŝimea, frato de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Tiuj naskiĝis al la giganto en Gat, kaj ili falis de la mano de David kaj de la manoj de liaj servantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Satano leviĝis kontraŭ Izraelon kaj instigis Davidon kalkuli Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Kaj David diris al Joab kaj al la estroj de la popolo: Iru, kalkulu la Izraelidojn, de Beer-Ŝeba ĝis Dan, kaj raportu al mi, por ke mi sciu ilian nombron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Joab diris: La Eternulo multigu Sian popolon centoble; ili ĉiuj, ho reĝo, mia sinjoro, estas ja servantoj por mia sinjoro; por kio do mia sinjoro tion postulas? por kio tio fariĝu kulpo sur Izrael?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Sed la vorto de la reĝo superfortis Joabon; tial Joab iris, trairis la tutan Izraelidaron, kaj venis Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Kaj Joab transdonis al David la rezulton de la kalkulado de la popolo; kaj montriĝis, ke da Izraelidoj estas miliono kaj cent mil viroj povantaj eltiri glavon, kaj da Jehudaidoj kvarcent sepdek mil povantaj eltiri glavon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'La Levidojn kaj la Benjamenidojn li ne kalkulis inter ili, ĉar antipatia estis al Joab la vorto de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Kaj tiu afero malplaĉis al Dio, kaj Li frapis Izraelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Tiam David diris al Dio: Mi forte pekis, farante tiun aferon. Sed nun, pardonu do la malbonagon de Via servanto; ĉar mi agis tre malsaĝe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Kaj la Eternulo parolis al Gad, la viziisto de David, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Iru kaj diru al David: Tiele diras la Eternulo: Tri punojn Mi proponas al vi; elektu al vi unu el ili, ke Mi ĝin faru al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Kaj Gad venis al David, kaj diris al li: Tiele diras la Eternulo: Akceptu por vi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'aŭ dum tri jaroj estos malsato en la lando; aŭ dum tri monatoj vi estos premata de viaj kontraŭuloj kaj vin atingos la glavo de viaj malamikoj; aŭ dum tri tagoj regos en la lando la glavo de la Eternulo kaj pesto, kaj anĝelo de la Eternulo ekstermados en ĉiuj regionoj de Izrael. Pripensu do nun, kion mi respondu al mia Sendinto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'Tiam David diris al Gad: Estas al mi tre malfacile; sed mi falu en la manon de la Eternulo, ĉar tre granda estas Lia kompatemeco; nur mi ne falu en manon homan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Kaj la Eternulo venigis peston sur Izraelon, kaj falis el la Izraelidoj sepdek mil homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Kaj Dio sendis anĝelon al Jerusalem, por fari en ĝi ekstermon. Sed kiam li komencis la ekstermadon, la Eternulo rigardis, kaj bedaŭris la malbonon, kaj diris al la anĝelo-ekstermanto: Sufiĉe! nun haltigu vian manon! La anĝelo de la Eternulo staris tiam apud la draŝejo de Ornan, la Jebusido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'David levis siajn okulojn, kaj ekvidis la anĝelon de la Eternulo, starantan inter la tero kaj la ĉielo, kaj tenantan en sia mano eltiritan glavon, etenditan super Jerusalem. Tiam David kaj la plejaĝuloj, kovritaj per sakaĵoj, ĵetis sin vizaĝaltere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'Kaj David diris al Dio: Mi estas ja tiu, kiu ordonis kalkuli la popolon; mi estas tiu, kiu pekis kaj faris la malbonaĵon; sed kion faris ĉi tiuj ŝafoj? Ho Eternulo, mia Dio, Via mano estu sur mi kaj sur la domo de mia patro; sed Vian popolon ne plagu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'La anĝelo de la Eternulo diris al Gad, ke li diru al David, ke David iru kaj starigu altaron al la Eternulo sur la draŝejo de Ornan, la Jebusido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Tiam David iris, konforme al la vorto de Gad, kiun li eldiris en la nomo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Kiam Ornan sin returnis kaj ekvidis la anĝelon, li kaj liaj kvar filoj kun li sin kaŝis. Ornan tiam estis draŝanta tritikon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Kaj David venis al Ornan. Ornan ekrigardis kaj ekvidis Davidon, kaj li eliris el la draŝejo kaj adorkliniĝis antaŭ David vizaĝaltere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'David diris al Ornan: Donu al mi la lokon de la draŝejo, por ke mi konstruu sur ĝi altaron al la Eternulo; pro ĝia plena prezo donu ĝin al mi, por ke ĉesiĝu la pesto inter la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Kaj Ornan diris al David: Prenu al vi; mia sinjoro la reĝo faru tion, kio plaĉas al li; vidu, mi fordonas la bovojn por bruloferoj, la draŝilojn por ligno, kaj la tritikon por farunofero; ĉion mi fordonas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Sed la reĝo David diris al Ornan: Ne; mi volas aĉeti pro plena prezo; ĉar mi ne oferportos vian propraĵon al la Eternulo, kaj mi ne alportos bruloferon senpagan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'Kaj David donis al Ornan pro la loko sescent siklojn da oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Kaj David konstruis tie altaron al la Eternulo, kaj alportis bruloferojn kaj pacoferojn, kaj ekvokis al la Eternulo; kaj Li respondis al li per fajro el la ĉielo sur la altaron de la brulofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Kaj la Eternulo ordonis al la anĝelo, ke li remetu sian glavon en ĝian ingon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'En tiu tempo, vidante, ke la Eternulo respondis al li sur la draŝejo de Ornan, la Jebusido, David alportis tie oferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'La tabernaklo de la Eternulo, kiun faris Moseo en la dezerto, kaj la altaro de bruloferoj, estis en tiu tempo sur altaĵo en Gibeon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Sed David ne povis iri antaŭ ĝin por demandi Dion; ĉar lin timigis la glavo de la anĝelo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Kaj David diris: Ĉi tie estas la domo de Dio, la Eternulo, kaj ĉi tio estas altaro por bruloferoj por Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Kaj David ordonis kunvenigi la fremdulojn, kiuj estis en la lando de Izrael, kaj li starigis ŝtonhakistojn, por ĉirkaŭhaki ŝtonojn por la konstruado de la domo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Kaj multe da fero por najloj al la pordoj de la pordegoj kaj por la krampoj pretigis David, ankaŭ multe da kupro, en nemezurita kvanto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'kaj sennombran kvanton da cedra ligno, ĉar la Cidonanoj kaj Tiranoj alveturigis al David multe da cedra ligno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Kaj David diris: Mia filo Salomono estas juna kaj neforta, kaj la domo, kiun oni devas konstrui por la Eternulo, devas esti granda, por ke Lia nomo kaj gloro estu konata en ĉiuj landoj. Tial mi preparados por li. Kaj David multe preparis antaŭ sia morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Kaj li alvokis sian filon Salomono, kaj testamentis al li, ke li konstruu domon por la Eternulo, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'Kaj David diris al Salomono: Mia filo, mi havis la intencon konstrui domon al la nomo de la Eternulo, mia Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'sed aperis pri mi vorto de la Eternulo, dirante: Multe da sango vi verŝis, kaj grandajn militojn vi faris, tial vi ne devas konstrui domon al Mia nomo; ĉar multe da sango vi verŝis antaŭ Mi sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Jen filo naskiĝos al vi; li estos homo de paco, kaj Mi donos al li pacon en rilato al ĉiuj liaj malamikoj ĉirkaŭe; Salomono estos lia nomo, kaj pacon kaj trankvilecon Mi donos al Izrael en lia tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Li konstruos domon al Mia nomo; li estos al Mi filo, kaj Mi estos al li patro; kaj Mi fortikigos la tronon de lia reĝado super Izrael por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Nun, ho mia filo, la Eternulo estu kun vi, por ke vi sukcesu kaj konstruu la domon de la Eternulo, via Dio, kiel Li diris pri vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'La Eternulo donu al vi saĝon kaj kompetentecon, kaj Li faru vin ordonanto super Izrael, por ke vi plenumadu la instruon de la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Tiam vi havos sukceson, se vi observos kaj plenumos la leĝojn kaj preskribojn, kiujn la Eternulo donis per Moseo al Izrael. Estu forta kaj kuraĝa; ne timu, kaj ne tremu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Jen mi en mia malriĉeco pretigis por la domo de la Eternulo cent mil kikarojn da oro, kaj milionon da kikaroj da arĝento, kaj kupron kaj feron en nekalkulebla kvanto, ĉar estas multe da ĝi; ankaŭ lignon kaj ŝtonojn mi pretigis; kaj vi povas aldoni al tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Vi havas multe da farontoj de la laboroj, masonistojn kaj ĉarpentistojn kaj kompetentulojn pri ĉiaj aferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'La oro, arĝento, kupro, kaj fero estas en nekalkulebla kvanto; leviĝu kaj faru, kaj la Eternulo estu kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Kaj David ordonis al ĉiuj estroj de Izrael, ke ili helpu lian filon Salomono:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'La Eternulo, via Dio, estas ja kun vi, kaj Li donis al vi trankvilecon ĉiuflanke ĉirkaŭe; ĉar Li transdonis en miajn manojn la loĝantojn de la lando, kaj la lando humiliĝis antaŭ la Eternulo kaj antaŭ Lia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Direktu do nun vian koron kaj vian animon, por turni vin al la Eternulo, via Dio. Leviĝu, kaj konstruu la sanktejon de la Eternulo Dio, por transporti la keston de interligo de la Eternulo kaj la sanktajn vazojn de Dio en la domon, kiu estos konstruita al la nomo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'David maljuniĝis kaj atingis sufiĉan aĝon; kaj li faris Salomonon, sian filon, reĝo super Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Kaj li kunvenigis ĉiujn estrojn de Izrael kaj la pastrojn kaj la Levidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Kaj estis kalkulitaj la Levidoj de la aĝo de tridek jaroj kaj pli; kaj montriĝis, ke ilia nombro, kalkulante ĉiujn kapojn de viroj, estis tridek ok mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'El ili por administri la servadon de la domo de la Eternulo estis dudek kvar mil; da oficistoj kaj juĝistoj estis ses mil;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'kvar mil pordegistoj, kaj kvar mil glorantoj de la Eternulo per instrumentoj, kiujn mi faris por glorado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'Kaj David dividis ilin en klasojn laŭ la filoj de Levi: Gerŝon, Kehat, kaj Merari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'La Gerŝonidoj: Ladan kaj Ŝimei.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'La filoj de Ladan: la ĉefo Jeĥiel, Zetam, kaj Joel-tri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'La filoj de Ŝimei: Ŝelomit, Ĥaziel, kaj Haran-tri. Tio estas la ĉefoj de patrodomoj de Ladan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Kaj la filoj de Ŝimei: Jaĥat, Zina, Jeuŝ, kaj Beria. Tio estas la filoj de Ŝimei-kvar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Jaĥat estis la ĉefo, Zina estis la dua; Jeuŝ kaj Beria havis nemulte da infanoj, tial ili ĉe la kalkulado prezentis unu patrodomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'La filoj de Kehat: Amram, Jichar, Ĥebron, kaj Uziel-kvar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'La filoj de Amram: Aaron kaj Moseo. Aaron estis apartigita kaj sanktigita por la plejsanktejo, li kaj liaj idoj por ĉiam, por incensadi antaŭ la Eternulo, por servadi al Li kaj por benadi en Lia nomo eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Moseo estis homo de Dio, kaj liaj idoj estis alkalkulitaj al la tribo de Levi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'La filoj de Moseo: Gerŝom kaj Eliezer.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'La filoj de Gerŝom: Ŝebuel estis la ĉefo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'La filoj de Eliezer estis: Reĥabja, la unua; aliajn filojn Eliezer ne havis; sed Reĥabja havis tre multe da filoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'La filoj de Jichar: Ŝelomit, la unua.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'La filoj de Ĥebron: la unua estis Jerija, la dua estis Amarja, la tria estis Jaĥaziel, la kvara estis Jekameam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'La filoj de Uziel: Miĥa, la unua, kaj Jiŝija, la dua.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'La filoj de Merari: Maĥli kaj Muŝi. La filoj de Maĥli: Eleazar kaj Kiŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Eleazar mortis, kaj li ne havis filojn, sed nur filinojn; kaj ilin prenis al si la filoj de Kiŝ, iliaj kuzoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'La filoj de Muŝi: Maĥli, Eder, kaj Jeremot-tri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Tio estas la idoj de Levi laŭ iliaj patrodomoj, la ĉefoj de patrodomoj laŭ ilia kalkulo, laŭ ilia laŭnoma kaj laŭkapa nombro, kiuj faradis la laboron de servado en la domo de la Eternulo, komencante de la aĝo de dudek jaroj kaj plue.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Ĉar David diris: La Eternulo, Dio de Izrael, donis ripozon al Sia popolo; kaj Li enloĝiĝis en Jerusalem por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'Kaj la Levidoj ne bezonis portadi la tabernaklon kaj ĉiujn ĝiajn vazojn por la servado en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Laŭ la lastaj ordonoj de David estis kalkulitaj la Levidoj, havantaj la aĝon de dudek jaroj kaj pli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Ilia ofico estis helpi al la Aaronidoj ĉe la servado en la domo de la Eternulo, zorgi pri la kortoj, pri la ĉambroj, pri la pureco de ĉio sankta, kaj plenumi la laboron en la domo de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'zorgi pri la pano de propono, pri la faruno por farunoferoj, pri la macoj, pri la patoj, pri la rostado, kaj pri ĉia mezurado kaj pesado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'stari ĉiumatene, por kanti laŭdon kaj gloron al la Eternulo, tiel same ankaŭ vespere;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'fari ĉiujn bruloferojn al la Eternulo en la sabatoj, monatkomencoj, kaj festoj, laŭ ilia nombro, laŭ la preskribo pri ili, ĉiam antaŭ la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'servi por deĵorado ĉe la tabernaklo de kunveno, ĉe la sanktaĵoj, kaj apud siaj fratoj la Aaronidoj ĉe la servado en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'La ordo de la Aaronidoj: la filoj de Aaron: Nadab, Abihu, Eleazar, kaj Itamar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Nadab kaj Abihu mortis pli frue ol ilia patro, kaj filojn ili ne havis; kaj Eleazar kaj Itamar fariĝis pastroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'La ordon aranĝis David, kaj Cadok el la idoj de Eleazar, kaj Aĥimeleĥ el la idoj de Itamar, laŭ iliaj oficoj ĉe ilia servado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Montriĝis, ke inter la idoj de Eleazar estis pli granda nombro da viroj, ol inter la idoj de Itamar. Oni dividis ilin: por la idoj de Eleazar estis dek ses ĉefoj de patrodomoj, kaj por la idoj de Itamar ok patrodomoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Oni dividis ilin per lotado, ambaŭ partojn paralele, ĉar la estroj de la sanktejo kaj la estroj en la aferoj de Dio estis el la idoj de Eleazar kaj el la idoj de Itamar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Kaj enskribis ilin Ŝemaja, filo de Netanel, skribisto el la Levidoj, antaŭ la reĝo kaj la estroj, antaŭ la pastro Cadok, antaŭ Aĥimeleĥ, filo de Ebjatar, kaj antaŭ la ĉefoj de patrodomoj de la pastroj kaj de la Levidoj; unu loto estis por patrodomo de Eleazaridoj, kaj unu loto estis por patrodomo de Itamaridoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'La unua loto eliris por Jehojarib, la dua por Jedaja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'la tria por Ĥarim, la kvara por Seorim,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'la kvina por Malkija, la sesa por Mijamin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'la sepa por Hakoc, la oka por Abija,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'la naŭa por Jeŝua, la deka por Ŝeĥanja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'la dek-unua por Eljaŝib, la dek-dua por Jakim,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'la dek-tria por Ĥupa, la dek-kvara por Jeŝebab,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'la dek-kvina por Bilga, la dek-sesa por Imer,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'la dek-sepa por Ĥezir, la dek-oka por Hapicec,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'la dek-naŭa por Petaĥja, la dudeka por Jeĥezkel,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'la dudek-unua por Jaĥin, la dudek-dua por Gamul,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'la dudek-tria por Delaja, la dudek-kvara por Maazja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Tio estis ilia ordo ĉe ilia servado, por iri en la domon de la Eternulo laŭ la preskribo donita per ilia patro Aaron, kiel ordonis al li la Eternulo, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'La ordo por la ceteraj idoj de Levi: el la idoj de Amram: Ŝubael; el la idoj de Ŝubael: Jeĥdeja;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'ĉe Reĥabja: el la idoj de Reĥabja la unua estis Jiŝija;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'ĉe la Jicharidoj: Ŝelomot; el la filoj de Ŝelomot: Jaĥat;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'la filoj de Ĥebron: Jerija, Amarja estis la dua, Jaĥaziel la tria, Jekameam la kvara;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'el la filoj de Uziel: Miĥa; el la filoj de Miĥa: Ŝamir;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'la frato de Miĥa estis Jiŝija; el la filoj de Jiŝija: Zeĥarja;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'el la filoj de Merari: Maĥli kaj Muŝi; el la filoj de Jaazija: Beno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'el la idoj de Merari: ĉe Jaazija: Beno, Ŝoham, Zakur, kaj Ibri;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'ĉe Maĥli: Eleazar; li ne havis filojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'ĉe Kiŝ: el la filoj de Kiŝ: Jeraĥmeel;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'la filoj de Muŝi: Maĥli, Eder, kaj Jerimot. Tio estas la Levidoj laŭ iliaj patrodomoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Ili ankaŭ lotis samtempe kun siaj fratoj la Aaronidoj, antaŭ la reĝo David, Cadok, Aĥimeleĥ, kaj la ĉefoj de patrodomoj de la pastroj kaj de la Levidoj: ĉefo de patrodomo egale kun sia pli malgranda frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'David kaj la militestroj apartigis por la servado filojn de Asaf, de Heman, kaj de Jedutun, kiuj estis inspiritaj por harpoj, psalteroj, kaj cimbaloj. Ili estis kalkulitaj por sia servado:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'el la filoj de Asaf: Zakur, Jozef, Netanja, kaj Aŝarela, filoj de Asaf, sub gvidado de Asaf, kiu kantis ĉe la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'De Jedutun, la filoj de Jedutun: Gedalja, Ceri, Jeŝaja, Ĥaŝabja, kaj Matitja, ses, sub gvidado de sia patro Jedutun, kiu ludis inspirite sur harpo, por laŭdi kaj glori la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'De Heman, la filoj de Heman: Bukija, Matanja, Uziel, Ŝebuel, Jerimot, Ĥananja, Ĥanani, Eliata, Gidalti, Romamti-Ezer, Joŝbekaŝa, Maloti, Hotir, kaj Maĥaziot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Ĉiuj ili estis filoj de Heman, viziisto de la reĝo koncerne la vortojn de Dio, por levi la kornon. Dio donis al Heman dek kvar filojn kaj tri filinojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Ĉiuj ĉi tiuj estis sub la gvidado de siaj patroj ĉe la kantado en la domo de la Eternulo, kun cimbaloj, psalteroj, kaj harpoj, ĉe la servado en la domo de Dio, sub la gvidado de la reĝo, Asaf, Jedutun, kaj Heman.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Ilia nombro, kune kun iliaj fratoj, instruitaj por kanti antaŭ la Eternulo, ĉiuj kompetentuloj, estis ducent okdek ok.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Ili lotis pri la vico de sia deĵorado, la malgrandaj egale kiel la grandaj, kompetentulo egale kiel lernanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'La unua loto eliris ĉe Asaf por Jozef; la dua por Gedalja; li kun siaj fratoj kaj siaj filoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'la tria por Zakur; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'la kvara por Jicri; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'la kvina por Netanja; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'la sesa por Bukija; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'la sepa por Jeŝarela; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'la oka por Jeŝaja; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'la naŭa por Matanja; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'la deka por Ŝimei; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'la dek-unua por Azarel; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'la dek-dua por Ĥaŝabja; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'la dek-tria por Ŝubael; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'la dek-kvara por Matitja; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'la dek-kvina por Jeremot; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'la dek-sesa por Ĥananja; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'la dek-sepa por Joŝbekaŝa; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'la dek-oka por Ĥanani; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'la dek-naŭa por Maloti; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'la dudeka por Eliata; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'la dudek-unua por Hotir; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'la dudek-dua por Gidalti; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'la dudek-tria por Maĥaziot; liaj filoj kaj fratoj estis dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'la dudek-kvara por Romamti-Ezer; liaj filoj kaj fratoj estis dek du.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'La klasoj de la pordegistoj: el la Koraĥidoj: Meŝelemja, filo de Kore, el la filoj de Asaf.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Meŝelemja havis filojn: la unuenaskito estis Zeĥarja, la dua estis Jediael, la tria estis Zebadja, la kvara estis Jatniel;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'la kvina estis Elam, la sesa estis Jehoĥanan, la sepa estis Eljehoenaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Obed-Edom havis filojn: Ŝemaja estis la unuenaskito, Jehozabad la dua, Joaĥ la tria, Saĥar la kvara, Netanel la kvina,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Amiel la sesa, Isaĥar la sepa, Peultaj la oka; ĉar benis lin Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Al lia filo Ŝemaja naskiĝis filoj, kiuj regis en siaj patrodomoj, ĉar ili estis bravaj homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'La filoj de Ŝemaja: Otni, Refael, Obed, Elzabad, liaj fratoj, bravaj homoj, Elihu kaj Semaĥja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Ĉiuj ili estis el la idoj de Obed-Edom; ili kaj iliaj filoj kaj iliaj fratoj estis bravaj homoj, taŭgaj por servado: sesdek du ili estis ĉe Obed- Edom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Meŝelemja havis filojn kaj fratojn, bravajn homojn dek ok.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Ĥosa el la Merariidoj havis filojn: Ŝimri estis la ĉefo (kvankam li ne estis unuenaskito, tamen lia patro faris lin ĉefo),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Ĥilkija estis la dua, Tebalja la tria, Zeĥarja la kvara; ĉiuj filoj kaj fratoj de Ĥosa estis dek tri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Al tiuj grupoj da pordegistoj, al la ĉefoj de viroj, estis komisiita la servado en la domo de la Eternulo kune kun iliaj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Kaj ili lotis, kiel la malgrandaj, tiel ankaŭ la grandaj, laŭ siaj patrodomoj, por ĉiu pordego aparte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Kaj la loto pri la oriento falis por Ŝelemja; kaj pri lia filo Zeĥarja, la saĝa konsilanto, oni lotis, kaj lia loto eliris por la nordo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'pri Obed-Edom por la sudo, kaj pri liaj filoj por la provizejo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'pri Ŝupim kaj Ĥosa por la okcidento, por la Pordego Ŝaleĥet, kie la vojo leviĝas, kie gardo staras apud gardo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Oriente estis ses Levidoj, norde kvar ĉiutage, sude kvar ĉiutage, kaj ĉe la provizejoj po du.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'Ĉe la alirejo okcidente estis: kvar ĉe la vojo, kaj du ĉe la alirejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Tio estis la grupoj da pordegistoj el la Koraĥidoj kaj el la Merariidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'El la Levidoj, Aĥija estis super la trezoroj de la domo de Dio kaj super la trezoroj de la sanktaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'El la idoj de Ladan, idoj de la Gerŝonido Ladan, ĉefoj de patrodomoj de la Gerŝonido Ladan estis la Jeĥielidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'La Jeĥielidoj: Zetam, kaj Joel, lia frato, estis super la trezoroj de la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'El la Amramidoj, Jicharidoj, Ĥebronidoj, kaj Uzielidoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Ŝebuel, ido de Gerŝom, filo de Moseo, estis estro super la trezoroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Lia frato Eliezer havis filon Reĥabja; lia filo estis Jeŝaja, lia filo estis Joram, lia filo estis Ziĥri, kaj lia filo estis Ŝelomit.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Ĉi tiu Ŝelomit kaj liaj fratoj estis super ĉiuj trezoroj de la sanktaĵoj, kiujn sanktigis la reĝo David, la ĉefoj de patrodomoj, la milestroj, kaj la centestroj, kaj la militestroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'El la militoj kaj el la militakiraĵoj ili konsekris partojn, por subteni la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'Ankaŭ ĉio, kion sanktigis la antaŭvidisto Samuel, kaj Saul, filo de Kiŝ, kaj Abner, filo de Ner, kaj Joab, filo de Ceruja, ĉio sanktigita estis sub la gardado de Ŝelomit kaj liaj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'El la Jicharidoj, Kenanja kaj liaj filoj estis por la aferoj eksteraj de Izrael, kiel inspektistoj kaj juĝistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'El la Ĥebronidoj, Ĥaŝabja kaj liaj fratoj, bravaj homoj, mil sepcent, havis oficojn en Izrael transe de Jordan, okcidente, por ĉiuj aferoj koncernantaj la Eternulon kaj por la aferoj de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'El la Ĥebronidoj, Jerija estis ĉefo de la Ĥebronidoj en iliaj generacioj kaj patrodomoj. En la kvardeka jaro de la reĝado de David ili estis esploritaj, kaj oni trovis ĉe ili bravajn homojn en Jazer en Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'Kaj liaj fratoj, bravaj homoj, du mil sepcent, ĉefoj de patrodomoj; al ili la reĝo David donis oficojn ĉe la Rubenidoj, la Gadidoj, kaj la duontribo de Manase, por ĉiuj aferoj de Dio kaj aferoj de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'La Izraelidoj havis laŭ sia nombro ĉefojn de patrodomoj, milestrojn, centestrojn, kaj siajn inspektistojn, kiuj servis al la reĝo pri ĉiuj aferoj de la apartaĵoj, interŝanĝante sin ĉiumonate, en ĉiuj monatoj de la jaro. Ĉiu apartaĵo konsistis el dudek kvar mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Super la unua apartaĵo en la unua monato estis Jaŝobeam, filo de Zabdiel; en lia apartaĵo estis dudek kvar mil;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'li estis el la idoj de Perec, la ĉefo de ĉiuj militestroj por la unua monato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Super la apartaĵo de la dua monato estis Dodaj, la Aĥoĥido; en lia apartaĵo estis ankaŭ la princo Miklot; en lia apartaĵo estis dudek kvar mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'La tria militestro, por la tria monato, estis Benaja, filo de la pastro Jehojada; en lia apartaĵo estis dudek kvar mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Ĉi tiu Benaja estis el la tridek herooj, kaj estro super ili; en lia apartaĵo estis lia filo Amizabad.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'La kvara, por la kvara monato, estis Asahel, frato de Joab, kaj post li lia filo Zebadja; en lia apartaĵo estis dudek kvar mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'La kvina, por la kvina monato, estis la estro Ŝamhut, la Jizraĥido; en lia apartaĵo estis dudek kvar mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'La sesa, por la sesa monato, estis Ira, filo de Ikeŝ, la Tekoaano; en lia apartaĵo estis dudek kvar mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'La sepa, por la sepa monato, estis Ĥelec, la Pelonano, el la Efraimidoj; en lia apartaĵo estis dudek kvar mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'La oka, por la oka monato, estis Sibĥaj, la Ĥuŝaido, el la Zeraĥidoj; en lia apartaĵo estis dudek kvar mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'La naŭa, por la naŭa monato, estis Abiezer, la Anatotano, el la Benjamenidoj; en lia apartaĵo estis dudek kvar mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'La deka, por la deka monato, estis Maharaj, la Netofaano, el la Zeraĥidoj; en lia apartaĵo estis dudek kvar mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'La dek-unua, por la dek-unua monato, estis Benaja, la Piratonano, el la Efraimidoj; en lia apartaĵo estis dudek kvar mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'La dek-dua, por la dek-dua monato, estis Ĥeldaj, la Netofaano, el la Otnielidoj; en lia apartaĵo estis dudek kvar mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Kaj super la triboj de Izrael: la estro de la Rubenidoj estis Eliezer, filo de Ziĥri; de la Simeonidoj: Ŝefatja, filo de Maaĥa;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'de la Levidoj: Ĥaŝabja, filo de Kemuel; de la Aaronidoj: Cadok;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'de la Jehudaidoj: Elihu, el la fratoj de David; de la Isaĥaridoj: Omri, filo de Miĥael;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'de la Zebulunidoj: Jiŝmaja, filo de Obadja; de la Naftaliidoj: Jerimot, filo de Azriel;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'de la Efraimidoj: Hoŝea, filo de Azazja; de la duontribo de Manase: Joel, filo de Pedaja;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'de la duontribo de Manase en Gilead: Jido, filo de Zeĥarja; de la Benjamenidoj: Jaasiel, filo de Abner;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'de la Danidoj: Azarel, filo de Jeroĥam. Tio estis la estroj de la triboj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Sed David ne faris kalkulon de tiuj, kiuj havis la aĝon de malpli ol dudek jaroj; ĉar la Eternulo promesis multigi Izraelon simile al la steloj de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Joab, filo de Ceruja, komencis la kalkuladon, sed ne finis. Kaj pro tio estis kolero kontraŭ Izrael; kaj tiu kalkulado ne estas enportita en la kronikon pri la reĝo David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Super la trezoroj de la reĝo estis Azmavet, filo de Adiel; super la trezoroj sur la kampo, en la urboj, en la vilaĝoj, kaj en la turoj estis Jonatan, filo de Uzija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Super la plenumantoj de la laboroj sur la kampo, super la terkultivo, estis Ezri, filo de Kelub.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'Super la vinberĝardenoj estis Ŝimei, la Ramaano; super la provizoj de vino en la vinberĝardenoj estis Zabdi, la Ŝefamano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Super la olivarboj kaj super la sikomoroj, kiuj estis en la valo, estis Baal-Ĥanan, la Gederano; super la provizoj de oleo estis Joaŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Super la bovoj, kiuj paŝtiĝis en Ŝaron, estis Ŝitraj, la Ŝaronano; super la bovoj en la valoj estis Ŝafat, filo de Adlaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'Super la kameloj estis Obil, la Iŝmaelido; super la azeninoj estis Jeĥdeja, la Meronotano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'Super la ŝafoj estis Jaziz, la Hagarido. Ĉiuj ĉi tiuj estis estroj super la havaĵoj, kiujn posedis la reĝo David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Jonatan, onklo de David, estis konsilisto; li estis homo kompetenta kaj klera; Jeĥiel, filo de Ĥaĥmoni, estis ĉe la filoj de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Aĥitofel estis konsilisto de la reĝo; Ĥuŝaj, la Arkano, estis amiko de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Post Aĥitofel estis Jehojada, filo de Benaja, kaj Ebjatar; la militestro de la reĝo estis Joab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'David kunvenigis en Jerusalemon ĉiujn estrojn de Izrael, la estrojn de la triboj, la estrojn de la apartaĵoj, kiuj servis al la reĝo, la milestrojn kaj centestrojn, la estrojn super ĉiuj havaĵoj kaj super la brutoj de la reĝo kaj de liaj filoj, ankaŭ la korteganojn, heroojn, kaj ĉiujn distingitojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Kaj la reĝo David stariĝis sur siaj piedoj, kaj diris: Aŭskultu min, ho miaj fratoj kaj mia popolo! Mi intencis konstrui domon de ripozo por la kesto de interligo de la Eternulo kaj por piedbenketo por nia Dio, kaj mi preparis min, por konstrui.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Sed Dio diris al mi: Ne konstruu domon al Mia nomo, ĉar vi estas homo de milito kaj vi verŝadis sangon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Tamen la Eternulo, Dio de Izrael, elektis min el la tuta domo de mia patro, por ke mi estu reĝo super Izrael por ĉiam; ĉar Jehudan Li elektis kiel reganton, kaj en la domo de Jehuda la domon de mia patro, kaj inter la filoj de mia patro Li favoris min, farante min reĝo super la tuta Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Kaj el ĉiuj miaj filoj-ĉar multe da filoj donis al mi la Eternulo- Li elektis mian filon Salomono, ke li sidu sur la trono de la reĝado de la Eternulo super Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Kaj Li diris al mi: Via filo Salomono, li konstruos Mian domon kaj Miajn kortojn; ĉar Mi elektis lin al Mi kiel filon, kaj Mi estos al li patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Kaj Mi fortikigos lian regnon por ĉiam, se li persistos en la plenumado de Miaj ordonoj kaj preskriboj kiel ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Kaj nun antaŭ la okuloj de la tuta Izrael, la komunumo de la Eternulo, kaj antaŭ la oreloj de nia Dio: observu kaj atentu ĉiujn ordonojn de la Eternulo, via Dio, por ke vi posedu ĉi tiun bonan landon kaj heredigu ĝin al viaj infanoj post vi eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Kaj vi, mia filo Salomono, konu la Dion de via patro, kaj servu al Li el plena koro kaj kun animo sincera; ĉar ĉiujn korojn la Eternulo esploras, kaj ĉiujn pensojn kaj intencojn Li komprenas. Se vi serĉos Lin, vi Lin trovos; kaj se vi forlasos Lin, Li forpuŝos vin por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Vidu nun, kiam la Eternulo elektis vin, por konstrui domon por la sanktejo; estu forta, kaj agu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Kaj David donis al sia filo Salomono la desegnon de la portiko, de la domoj, provizejoj, supraj ĉambroj, internaj ĉambroj, kaj de la loko por la sankta kesto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'kaj la desegnon de ĉio, kion li havis en sia animo koncerne la kortojn de la domo de la Eternulo kaj koncerne ĉiujn ĉambrojn ĉirkaŭe, koncerne la trezorojn de la domo de Dio kaj la trezorojn de la sanktaĵoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'koncerne la ordojn de la pastroj kaj de la Levidoj, koncerne la tutan servadon en la domo de la Eternulo, kaj koncerne ĉiujn objektojn de servado en la domo de la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'ankaŭ la oron, laŭ la pezo de la oro por ĉiuj objektoj de servado, kaj la pezon de ĉiuj arĝentaj objektoj de servado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'ankaŭ la pezon de la oraj kandelabroj kaj de iliaj oraj lucernoj, montrante aparte la pezon de ĉiu kandelabro kaj de ĝiaj lucernoj, kaj la pezon de la arĝentaj kandelabroj, de ĉiu kandelabro kaj de ĝiaj lucernoj, laŭ la destino de ĉiu kandelabro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'Li donis ankaŭ la pezon de la oro por la tabloj de propono, por ĉiu tablo aparte, kaj de la arĝento por la tabloj arĝentaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'ankaŭ por la forkoj, aspergaj kalikoj, tasoj el pura oro, oraj pelvoj, montrante la pezon por ĉiu pelvo aparte, kaj por la arĝentaj pelvoj, montrante la pezon de ĉiu pelvo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'ankaŭ la pezon de la incensaltaro el refandita oro. Li donis ankaŭ desegnon de la ĉaro kun la oraj keruboj, kiuj etendas la flugilojn kaj ŝirmas la keston de interligo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'Ĉio ĉi tio, li diris, estas skribita al mi de la mano de la Eternulo; Li klarigis al mi ĉiujn detalojn de la desegno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Kaj David diris al sia filo Salomono: Estu forta kaj kuraĝa, kaj agu; ne timu, kaj ne tremu; ĉar Dio la Eternulo, mia Dio, estas kun vi; Li ne deturnos Sin de vi kaj ne forlasos vin, ĝis vi finos la tutan aferon por la servado en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Kaj jen estas la ordoj de la pastroj kaj de la Levidoj por ĉia servado en la domo de Dio; ili estos kun vi por ĉiu faro, kun fervoro kaj lerteco en ĉiu laboro; kaj la estroj kaj la tuta popolo plenumos ĉiujn viajn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Kaj la reĝo David diris al la tuta komunumo: Mia filo Salomono, la sola, kiun elektis la Eternulo, estas juna kaj neforta, kaj la laboro estas granda; ĉar ne por homo estas la loĝejo, sed por Dio la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Mi preparis per mia tuta forto por la domo de mia Dio oron por la oraj objektoj, arĝenton por la arĝentaj, kupron por la kupraj, feron por la feraj, lignon por la lignaj, ŝtonojn oniksajn kaj ŝtonojn enkadrigitajn, ŝtonojn belajn kaj diverskolorajn, kaj ĉiaspecajn ŝtonojn multekostajn, kaj multe da ŝtonoj marmoraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Krom tio, pro mia amo al la domo de mia Dio, mian propran trezoron de oro kaj arĝento, kiun mi havas, mi fordonas por la domo de mia Dio, krom tio, kion mi pretigis por la sankta domo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'tri mil kikarojn da oro, el la oro de Ofir, kaj sep mil kikarojn da arĝento refandita, por tegi la murojn de la domoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'oron por la oraj objektoj, arĝenton por la arĝentaj, kaj por ĉiuj laborotaĵoj de la majstroj. Tamen kiu ankoraŭ deziras oferi hodiaŭ por la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Kaj oferis la ĉefoj de patrodomoj, la estroj de la triboj de Izrael, la milestroj kaj centestroj, kaj la estroj super la aferoj de la reĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'kaj ili donis por la bezonoj de la domo de Dio kvin mil kikarojn da oro kaj dek mil darkemonojn, kaj dek mil kikarojn da arĝento, kaj dek ok mil kikarojn da kupro, kaj cent mil kikarojn da fero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Kaj tiuj, ĉe kiuj troviĝis multekostaj ŝtonoj, donis ilin por la trezorejo de la domo de la Eternulo, en la manojn de Jeĥiel, la Gerŝonido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Kaj la popolo ĝojis pro tiu oferado, ĉar el plena koro ili oferis al la Eternulo; ankaŭ la reĝo David ĝojis tre forte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Kaj David benis la Eternulon antaŭ la okuloj de la tuta komunumo, kaj David diris: Estu benata, ho Eternulo, Dio de nia patro Izrael, eterne kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Al Vi, ho Eternulo, apartenas grandeco, potenco, majesto, venko, kaj gloro, ĉar ĉio en la ĉielo kaj sur la tero estas Via; al Vi, ho Eternulo, apartenas la reĝado, kaj Vi estas alte super ĉiuj estroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'Riĉeco kaj honoro venas de Vi; Vi regas super ĉio; en Via mano estas forto kaj potenco; Via mano povas ĉion grandigi kaj fortikigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Kaj nun, ho nia Dio, ni dankas Vin, kaj ni gloras Vian majestan nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Ĉar kiu estas mi, kaj kio estas mia popolo, ke mi havis la forton, por oferi tiom? de Vi estas ĉio, kaj el Via mano ni donis al Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Pasloĝantoj kaj enmigrintoj ni estas apud Vi, kiel ĉiuj niaj patroj; kiel ombro estas niaj tagoj sur la tero, nenio fortika.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Ho Eternulo, nia Dio! ĉi tiu tuta abundaĵo, kiun ni preparis, por konstrui al Vi domon, al Via sankta nomo, estas el Via mano, al Vi ĉio apartenas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Mi scias, ho mia Dio, ke Vi esploras la koron kaj ke sincereco plaĉas al Vi; el sincera koro mi oferis ĉion ĉi tion; kaj nun mi vidas kun ĝojo Vian popolon, kiu troviĝas ĉi tie, ke ĝi oferas al Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Ho Eternulo, Dio de niaj patroj Abraham, Isaak, kaj Izrael! konservu ĝin por ĉiam, ĉi tiun pensmanieron de la koro de Via popolo, kaj turnu ilian koron al Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Kaj al mia filo Salomono donu koron perfektan, ke li observu Viajn ordonojn, Viajn preskribojn, kaj Viajn leĝojn, ke li ĉion plenumu, kaj ke li konstruu la konstruaĵon, por kiu mi faris la preparojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Kaj David diris al la tuta komunumo: Benu la Eternulon, vian Dion. Kaj la tuta komunumo benis la Eternulon, Dion de iliaj patroj; kaj ili kliniĝis kun adoro antaŭ la Eternulo kaj antaŭ la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Kaj ili faris buĉoferojn al la Eternulo. Kaj en la sekvanta tago ili alportis bruloferojn al la Eternulo: mil bovojn, mil virŝafojn, mil ŝafidojn, kune kun iliaj verŝoferoj, kaj multe da oferoj por la tuta Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Kaj ili manĝis kaj trinkis antaŭ la Eternulo en tiu tago kun granda ĝojo. Kaj duafoje ili faris reĝo Salomonon, filon de David, kaj sanktoleis lin kiel reganton, kaj Cadokon kiel pastron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Kaj Salomono suriris sur la tronon de la Eternulo kiel reĝo anstataŭ sia patro David; kaj li havis sukceson, kaj la tuta Izrael obeadis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Kaj ĉiuj estroj kaj eminentuloj, kaj ankaŭ ĉiuj filoj de la reĝo David, submetis sin al la reĝo Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Kaj la Eternulo forte altigis Salomonon antaŭ la okuloj de la tuta Izrael, kaj metis sur lin reĝan majeston, kiu antaŭe estis sur neniu el la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'David, filo de Jiŝaj, estis reĝo super la tuta Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'La tempo, dum kiu li reĝis super Izrael, estis kvardek jaroj: en Ĥebron li reĝis sep jarojn, kaj en Jerusalem li reĝis tridek tri jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Kaj li mortis en bona maljuneco, sata de aĝo, riĉeco, kaj gloro; kaj anstataŭ li ekreĝis lia filo Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'La historio de la reĝo David, la antaŭa kaj la posta, estas priskribita en la kroniko de la antaŭvidisto Samuel, en la kroniko de la profeto Natan, kaj en la kroniko de la viziisto Gad;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'lia tuta reĝado, lia potenco, kaj la tempo, kiun travivis li kaj Izrael kaj ĉiuj regnoj de la landoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Salomono, filo de David, fortikiĝis en sia regno; kaj la Eternulo, lia Dio, estis kun li kaj levis lin alte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Kaj Salomono kunvokis la tutan Izraelon, la milestrojn kaj centestrojn, la juĝistojn, kaj ĉiujn estrojn en la tuta Izrael, la ĉefojn de la patrodomoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'Kaj Salomono kune kun la tuta komunumo iris al la altaĵo en Gibeon, ĉar tie estis la tabernaklo de kunveno de Dio, tiu, kiun faris Moseo, servanto de la Eternulo, en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Sed la keston de Dio David estis transportinta el Kirjat-Jearim sur tiun lokon, kiun David pretigis por ĝi; ĉar li aranĝis por ĝi tendon en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'La kupra altaro, kiun faris Becalel, filo de Uri, filo de Ĥur, estis tie, antaŭ la tabernaklo de la Eternulo; kaj Salomono kaj la komunumo ĝin serĉis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Kaj Salomono supreniris tie antaŭ la Eternulo sur la kupran altaron, kiu estis antaŭ la tabernaklo de kunveno, kaj alportis sur ĝi mil bruloferojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'En tiu nokto Dio aperis al Salomono, kaj diris al li: Petu, kion Mi donu al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Kaj Salomono diris al Dio: Vi estis tre favorkora al mia patro David, kaj Vi faris min reĝo anstataŭ li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'nun, ho Dio Eternulo, plenumiĝu do Via vorto al mia patro David. Ĉar Vi faris min reĝo super popolo grandnombra kiel la polvo de la tero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'tial donu al mi nun saĝecon kaj sciadon, por ke mi povosciu eliradi kaj eniradi antaŭ tiu popolo; ĉar kiu povas regi tiun Vian grandan popolon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Tiam Dio diris al Salomono: Pro tio, ke ĉi tio estis en via koro, kaj vi ne petis riĉecon, nek havaĵojn, nek gloron, nek la animon de viaj malamikoj, kaj eĉ longan vivon vi ne petis, sed vi petis por vi saĝecon kaj sciadon, por regi Mian popolon, super kiu Mi faris vin reĝo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'pro tio saĝeco kaj sciado estas donataj al vi; sed ankaŭ riĉecon, havaĵojn, kaj gloron Mi donos al vi en tia grado, kiun ne havis la reĝoj antaŭ vi, kaj ankaŭ post vi oni tion ne havos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Kaj Salomono revenis de la altaĵo en Gibeon, de la tabernaklo de kunveno, en Jerusalemon. Kaj li reĝis super Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Kaj Salomono kolektis al si ĉarojn kaj rajdistojn. Li havis mil kvarcent ĉarojn kaj dek du mil rajdistojn; kaj li lokis ilin en la urboj de ĉaroj kaj ĉe la reĝo en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Kaj la reĝo atingis tion, ke la arĝento kaj oro estis en Jerusalem kiel ŝtonoj, kaj la cedroj estis en tiel granda kvanto, kiel la sikomoroj sur la malaltaj lokoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'La ĉevalojn al Salomono oni venigadis el Egiptujo; kaj societo de komercistoj de la reĝo aĉetadis ilin amase laŭ difinita prezo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'Ili liveradis el Egiptujo ĉiun ĉaron pro sescent sikloj da arĝento, kaj ĉiun ĉevalon pro cent kvindek; tiel same ili estis liverataj per iliaj manoj al ĉiuj reĝoj de la Ĥetidoj kaj al la reĝoj de Sirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Kaj Salomono ordonis, ke oni konstruu domon al la nomo de la Eternulo kaj reĝan domon por li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Salomono starigis sepdek mil portistojn, okdek mil montajn ŝtonhakistojn, kaj tri mil sescent kontrolistojn super ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Kaj Salomono sendis al Ĥiram, reĝo de Tiro, por diri: Vi scias, kiel vi agis kun mia patro David, kaj sendis al li cedran lignon, por ke li konstruu al si domon, por loĝi en ĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'nun jen mi konstruas domon al la nomo de la Eternulo, mia Dio, por ke ĝi estu konsekrita al Li, por incensadi antaŭ Li bonodorajn incensojn, prezenti tie konstante panojn de propono, bruloferojn matene kaj vespere, en sabatoj, monatkomencoj, kaj festoj de la Eternulo, nia Dio, kio estas eterna leĝo por Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'La domo, kiun mi konstruas, estos granda; ĉar pli granda estas nia Dio, ol ĉiuj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Kiu havus sufiĉe da fortoj, por konstrui al Li domon? la ĉielo kaj la ĉielo de ĉieloj ne povas ja Lin ampleksi. Kaj kiu mi estas, ke mi konstruu al Li domon, kiu servus por io alia, ol por nura incensado antaŭ Li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Sendu do nun al mi homon, kiu estas majstro en farado de objektoj el oro, arĝento, kupro, fero, el ŝtofo purpura, ruĝa, kaj blua, kaj kiu povoscias gravuri gravuraĵojn, kune kun la artistoj, kiuj estas ĉe mi en Judujo kaj en Jerusalem kaj kiujn mia patro David preparis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Kaj sendu al mi lignon cedran, cipresan, kaj santalan de Lebanon; ĉar mi scias, ke viaj servantoj povoscias haki arbojn Lebanonajn. Kaj jen miaj servantoj estos kun viaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'por pretigi por mi multe da ligno; ĉar la domo, kiun mi konstruas, devas esti granda kaj mirinda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Jen por la ĉarpentistoj, por la lignohakistoj, viaj servantoj, mi destinis dudek mil kor�ojn da draŝita tritiko, dudek mil kor�ojn da hordeo, dudek mil bat�ojn da vino, kaj dudek mil bat�ojn da oleo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Ĥiram, reĝo de Tiro, respondis per letero, kiun li sendis al Salomono: Pro amo de la Eternulo al Sia popolo Li faris vin reĝo super ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Kaj Ĥiram diris plue: Benata estu la Eternulo, Dio de Izrael, kiu kreis la ĉielon kaj la teron, kaj kiu donis al la reĝo David filon saĝan, kleran, kaj ĉiokomprenan, kiu konstruos domon por la Eternulo kaj reĝan domon por si.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Nun mi sendis homon saĝan kaj kompetentan, mian majstron Ĥuram;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'li estas filo de virino el la idinoj de Dan, kaj lia patro estis Tirano; li povoscias fari objektojn el oro, arĝento, kupro, fero, ŝtono, kaj ligno, el ŝtofo purpura, blua, bisina, kaj ruĝa, fari ĉiajn gravuraĵojn, kaj trovi bonajn ideojn pri ĉio, kio estos komisiita al li, kune kun viaj artistoj kaj kun la artistoj de mia sinjoro David, via patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Nun la tritikon, hordeon, oleon, kaj vinon, pri kiuj mia sinjoro parolis, li sendu al siaj servantoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'kaj ni hakos lignon de Lebanon, kiom vi bezonas, kaj ni sendos ĝin al vi per flosoj sur la maro ĝis Jafo; kaj vi venigos tion en Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Kaj Salomono kalkulis ĉiujn fremdulojn, kiuj estis en la lando de Izrael post la kalkulo, kiun aranĝis lia patro David; kaj troviĝis da ili cent kvindek tri mil sescent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'Kaj li faris el ili sepdek mil portistojn, okdek mil montajn ŝtonhakistojn, kaj tri mil sescent kontrolistojn, por devigadi la popolon labori.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Kaj Salomono komencis konstrui la domon de la Eternulo en Jerusalem, sur la monto Morija, kiu estis montrita al lia patro David, sur la loko, kiun David pretigis, sur la loko de la draŝejo de Ornan, la Jebusido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Li komencis konstrui en la dua tago de la dua monato, en la kvara jaro de sia reĝado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Kaj jene Salomono faris la fundamenton, por konstrui la domon de Dio: la longo estis laŭ la antaŭa ulnomezuro sesdek ulnoj, kaj la larĝo dudek ulnoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'la portiko laŭlonge de la domo havis simile al la larĝo de la domo dudek ulnojn; la alto estis cent dudek. Kaj li tegis ĝin interne per pura oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'La grandan domon li tabulkovris per ligno cipresa kaj tegis ĝin per pura oro kaj faris sur ĝi palmornamojn kaj ĉenornamojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Kaj li garnis la domon per multekostaj ŝtonoj por beleco; la oro estis oro Parvaima.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Kaj li kovris la domon, la trabojn, la sojlojn, ĝiajn murojn, kaj ĝiajn pordojn per oro, kaj li skulptigis kerubojn sur la muroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Kaj li faris la plejsanktejon; ĝia longo, konforme al la larĝo de la domo, estis dudek ulnoj, kaj ĝia larĝo estis dudek ulnoj; kaj li tegis ĝin per bona oro en la kvanto de sescent kikaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Por la najloj li donis kvindek siklojn da oro; kaj la suprajn ĉambrojn li tegis per oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Kaj en la plejsanktejo li faris du kerubojn artiste faritajn kaj tegis ilin per oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'La flugiloj de la keruboj havis la longon de dudek ulnoj; unu flugilo, havanta kvin ulnojn, tuŝiĝis kun la muro de la domo, kaj la dua flugilo, havanta kvin ulnojn, tuŝiĝis kun la flugilo de la dua kerubo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Ankaŭ ĉe la dua kerubo unu flugilo, havanta kvin ulnojn, tuŝiĝis kun la muro de la domo, kaj la dua flugilo, havanta kvin ulnojn, tuŝiĝis kun la flugilo de la alia kerubo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'La flugiloj de tiuj keruboj estis etenditaj sur la spaco de dudek ulnoj; ili staris sur siaj piedoj, kaj iliaj vizaĝoj estis turnitaj al la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Kaj li faris la kurtenon el ŝtofo blua, purpura, kaj ruĝa, kaj el bisino; kaj li faris sur ĝi kerubojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Kaj li faris antaŭ la domo du kolonojn, havantajn la longon de tridek kvin ulnoj, kaj la kapitelo supre havis kvin ulnojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Kaj li faris ĉenojn en la plejsanktejo kaj metis ilin sur la supron de la kolonoj; kaj li faris cent granatojn kaj metis ilin sur la ĉenojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Kaj li starigis la kolonojn antaŭ la templo, unu dekstre kaj unu maldekstre; al la dekstra li donis la nomon Jaĥin, kaj al la maldekstra la nomon Boaz.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Kaj li faris kupran altaron, havantan la longon de dudek ulnoj, la larĝon de dudek ulnoj, kaj la alton de dek ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Kaj li faris maron fanditan, havantan dek ulnojn de rando ĝis rando, tute rondan, havantan la alton de kvin ulnoj; kaj ŝnuro de tridek ulnoj prezentis ĝian mezuron ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Figuroj de bovoj estis sub ĝi ĉirkaŭe, ĉiuflanke ĝin ĉirkaŭis; sur la spaco de dek ulnoj ili ĉirkaŭis la maron, du vicoj da bovoj, fanditaj samfande kun ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Ĝi staris sur dek du bovoj: tri kun la vizaĝo norden, tri kun la vizaĝo okcidenten, tri kun la vizaĝo suden, kaj tri kun la vizaĝo orienten; kaj la maro estis sur ili supre; kaj ĉiuj iliaj malantaŭaj partoj estis turnitaj internen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Ĝi havis la dikon de manlarĝo; kaj ĝia rando, farita laŭ la maniero de rando de kaliko, estis simila al disvolviĝinta lilio. Ĝi ampleksis tri mil bat�ojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Li faris dek lavujojn kaj starigis kvin dekstre kaj kvin maldekstre, por lavi en ili tion, kio estis preparata por brulofero, por skulavi tion en ili; kaj la maro estis, por ke la pastroj lavu sin en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Kaj li faris dek orajn kandelabrojn laŭ la preskribo koncerne ilin, kaj starigis en la templo, kvin dekstre kaj kvin maldekstre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Li faris dek tablojn, kaj starigis en la templo, kvin dekstre kaj kvin maldekstre. Li faris ankaŭ cent orajn aspergajn kalikojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Li aranĝis la korton de la pastroj kaj la grandan antaŭkorton kaj pordojn por la antaŭkorto; kaj la pordojn li tegis per kupro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Kaj la maron li starigis sur la dekstra flanko, oriente, en la suda parto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Kaj Ĥuram faris la kaldronojn kaj la ŝovelilojn kaj la aspergajn kalikojn. Kaj Ĥuram finis la laboron, kiun li faris por la reĝo Salomono en la domo de Dio:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'du kolonojn, du globaĵojn kaj kapitelojn sur la supro de la kolonoj, du retojn por kovri la du globaĵojn de la kapiteloj, kiuj estis sur la supro de la kolonoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'kaj kvarcent granatojn sur la du retoj, po du vicoj da granatoj por ĉiu reto, por kovri la du globaĵojn de la kapiteloj, kiuj estis sur la kolonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Kaj li faris la bazaĵojn, kaj la lavujojn li faris sur la bazaĵoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'la unu maron, kaj la dek du bovojn sub ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'Kaj la kaldronojn, la ŝovelilojn, kaj la forkojn, kaj ĉiujn iliajn vazojn faris al Salomono lia majstro Ĥuram por la domo de la Eternulo, el polurita kupro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'En la ĉirkaŭaĵo de Jordan la reĝo fandigis ilin en argila tero, inter Sukot kaj Cereda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Kaj Salomono faris ĉiujn tiujn vazojn en tre granda nombro, ĉar la pezo de la kupro ne estis kalkulita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Kaj Salomono faris ĉiujn vazojn, kiuj estas en la domo de Dio: la oran altaron, la tablojn, sur kiuj estas la panoj de propono;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'la kandelabrojn kaj iliajn lucernojn, por bruligi ilin laŭ la preskribo antaŭ la plejsanktejo-el pura oro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'kaj la florojn kaj la lucernojn kaj la prenilojn, el oro, tute el oro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'kaj la tranĉilojn kaj la aspergajn kalikojn kaj la kulerojn kaj la karbujojn, el pura oro; kaj la enirejo de la domo, ĝiaj internaj pordoj al la plejsanktejo, kaj la pordoj de la domo al la templo, estis oraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Tiamaniere estis finita la tuta laboro, kiun Salomono faris por la domo de la Eternulo. Kaj Salomono enportis la konsekritaĵojn de sia patro David; la arĝenton kaj la oron kaj ĉiujn vazojn li metis en la trezorejojn de la domo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Tiam Salomono kunvenigis la plejaĝulojn de Izrael kaj ĉiujn ĉefojn de la triboj, la estrojn de la patrodomoj de la Izraelidoj, en Jerusalemon, por transporti la keston de interligo de la Eternulo el la urbo de David, tio estas el Cion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Kaj kolektiĝis al la reĝo ĉiuj Izraelidoj al la festo, tio estas en la sepa monato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Kaj venis ĉiuj plejaĝuloj de Izrael; kaj la Levidoj ekportis la keston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'Kaj oni enportis la keston kaj la tabernaklon de kunveno, kaj ĉiujn sanktajn vazojn, kiuj estis en la tabernaklo; ilin portis la pastroj Levidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Kaj la reĝo Salomono, kaj la tuta komunumo de Izrael, kiu kolektiĝis al li, estis antaŭ la kesto, oferbuĉante ŝafojn kaj bovojn, kiujn oni ne povis nombri nek kalkuli pro ilia granda multeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Kaj la pastroj venigis la keston de interligo de la Eternulo sur ĝian lokon, en la profundon de la domo, en la plejsanktejon, sub la flugilojn de la keruboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Ĉar la keruboj havis siajn flugilojn etenditaj super la loko de la kesto, kaj la keruboj estis kovrantaj la keston kaj ĝiajn stangojn de supre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Kaj la stangoj estis tiel longaj, ke la kapetoj de la stangoj estis videblaj el la kesto en la antaŭa parto de la plejsanktejo, sed ekstere ili ne estis videblaj; kaj ili restis tie ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'En la kesto estis nenio krom la du tabeloj, kiujn metis tien Moseo sur Ĥoreb, kiam la Eternulo faris interligon kun la Izraelidoj post ilia eliro el Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Kiam la pastroj eliris el la sanktejo (ĉar ĉiuj pastroj, kiuj tie troviĝis, sanktiĝis, sen diferenco de la ordoj),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'kaj la Levidoj-kantistoj-ili ĉiuj, Asaf, Heman, Jedutun, iliaj filoj kaj fratoj-en bisinaj vestoj, kun cimbaloj, psalteroj, kaj harpoj, staris oriente de la altaro, kaj kun ili cent dudek pastroj, trumpetantaj per trumpetoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'kaj ili estis kvazaŭ unu, la trumpetantoj kaj la kantantoj; kaj oni aŭdis kvazaŭ unu voĉon, laŭdantan kaj dankantan antaŭ la Eternulo; kaj kiam ektondris la voĉo de la trumpetoj kaj cimbaloj kaj aliaj muzikaj instrumentoj, kaj de la glorkantado al la Eternulo, ke Li estas bona kaj ke Lia favorkoreco estas eterna: tiam la domo pleniĝis de nubo, la domo de la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'kaj la pastroj ne povis stari kaj servi pro la nubo, ĉar la majesto de la Eternulo plenigis la domon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Tiam Salomono ekparolis: La Eternulo diris, ke Li deziras loĝi en mallumo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'tial mi konstruis domon por Via loĝado, kaj lokon por Via restado eterna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Kaj la reĝo turnis sian vizaĝon kaj benis la tutan komunumon de Izrael; kaj la tuta komunumo de Izrael staris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Kaj li diris: Benata estu la Eternulo, Dio de Izrael, kiu parolis per Sia buŝo al mia patro David, kaj nun plenumis per Sia mano, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'De post la tago, kiam Mi elkondukis Mian popolon el la lando Egipta, Mi elektis neniun urbon inter ĉiuj triboj de Izrael, por konstrui domon, en kiu estus Mia nomo; kaj Mi ne elektis homon, ke li estu reganto super Mia popolo Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Sed Mi elektis Jerusalemon, ke Mia nomo tie estu; kaj Mi elektis Davidon, ke li estu super Mia popolo Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Mia patro David havis la intencon konstrui domon al la nomo de la Eternulo, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Sed la Eternulo diris al mia patro David: Intencante konstrui domon al Mia nomo, vi agis bone, havante tian intencon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'tamen la domon konstruos ne vi, sed nur via filo, kiu eliris el viaj lumboj, li konstruos la domon al Mia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Kaj la Eternulo plenumis Sian vorton, kiun Li diris: mi leviĝis anstataŭ mia patro David kaj sidiĝis sur la trono de Izrael, kiel diris la Eternulo, kaj mi konstruis la domon al la nomo de la Eternulo, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'Kaj mi metis tien la keston, en kiu troviĝas la interligo de la Eternulo, kiun Li faris kun la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Kaj li stariĝis antaŭ la altaro de la Eternulo kontraŭ la tuta komunumo de Izrael, kaj li etendis siajn manojn');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, '(ĉar Salomono estis farinta kupran ambonon, havantan la longon de kvin ulnoj, la larĝon de kvin ulnoj, kaj la alton de tri ulnoj, kaj li estis lokinta ĝin meze de la antaŭkorto: li nun stariĝis sur ĝi, ekgenuis antaŭ la tuta komunumo de Izrael, etendis siajn manojn al la ĉielo),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'kaj li parolis: Ho Eternulo, Dio de Izrael! ne ekzistas dio simila al Vi en la ĉielo nek sur la tero; Vi konservas la interligon kaj la favorkorecon al Viaj servantoj, kiuj iradas antaŭ Vi per sia tuta koro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Vi plenumis al Via servanto David, mia patro, kion Vi promesis al li; Vi parolis per Via buŝo, kaj Vi plenumis per Via mano, kiel ni nun vidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Nun, ho Eternulo, Dio de Izrael, plenumu plue al Via servanto David, mia patro, kion Vi promesis al li, dirante: Ne mankos ĉe vi antaŭ Mi viro, sidanta sur la trono de Izrael, se viaj filoj nur observados sian vojon, por iri laŭ Mia instruo, kiel vi iradis antaŭ Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Nun, ho Eternulo, Dio de Izrael, veriĝu Via vorto, kiun Vi diris al Via servanto David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Ĉu efektive Dio loĝus kun homoj sur la tero? ja la ĉielo kaj la ĉielo de ĉieloj ne povas Vin ampleksi; des pli tion ne povas ĉi tiu domo, kiun mi konstruis!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Sed turnu Vin al la preĝo de Via servanto kaj al lia petego, ho Eternulo, mia Dio, por aŭskulti la vokadon kaj la preĝon, per kiu Via servanto preĝas antaŭ Vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'por ke Viaj okuloj estu nefermitaj super ĉi tiu domo tage kaj nokte, super la loko, pri kiu Vi promesis, ke Vi estigos tie Vian nomon; por aŭskulti la preĝon, kiun Via servanto faros sur ĉi tiu loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Kaj aŭskultu la petegojn de Via servanto kaj de Via popolo Izrael, per kiuj ili preĝos sur ĉi tiu loko; aŭskultu el la loko de Via loĝado, el la ĉielo; kaj kiam Vi aŭskultos, Vi pardonu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Se iu pekos kontraŭ sia proksimulo, kaj oni postulos de li ĵuron, ke li ĵuru, kaj la ĵuro estos farata antaŭ Via altaro en ĉi tiu domo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'tiam aŭskultu el la ĉielo, kaj faru juĝon pri Viaj servantoj, repagante al la malbonagulo, metante lian konduton sur lian kapon, kaj elmontrante la pravecon de virtulo, rekompencante lin laŭ lia virteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Se Via popolo Izrael estos frapita de malamiko, pekinte antaŭ Vi, sed ili returnos sin kaj gloros Vian nomon kaj preĝos kaj petegos antaŭ Vi en ĉi tiu domo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'tiam aŭskultu el la ĉielo, kaj pardonu la pekon de Via popolo Izrael, kaj revenigu ilin sur la teron, kiun Vi donis al ili kaj al iliaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Se la ĉielo ŝlosiĝos tiel, ke ne estos pluvo pro tio, ke ili pekis antaŭ Vi, sed ili ekpreĝos sur ĉi tiu loko kaj gloros Vian nomon kaj returnos sin de sia peko, por ke Vi aŭskultu ilin:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'tiam aŭskultu el la ĉielo, kaj pardonu la pekon de Viaj servantoj kaj de Via popolo Izrael, montrante al ili la bonan vojon, kiun ili devas iri; kaj donu pluvon sur Vian landon, kiun Vi donis al Via popolo kiel heredaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Se estos malsato en la lando, aŭ se estos pesto, brulsekeco, velkado, akridoj, aŭ vermoj, aŭ se premos ilin malamiko en la lando de ilia loĝado, aŭ se estos ia plago aŭ malsano;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'ĉe ĉiu preĝo, ĉe ĉiu petego, kiun faros iu homo aŭ Via tuta popolo Izrael, kiam ĉiu el ili sentos sian malfeliĉon kaj sian doloron kaj etendos siajn manojn al ĉi tiu domo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'aŭskultu el la ĉielo, el la loko de Via loĝado, kaj pardonu, kaj redonu al ĉiu konforme al lia tuta konduto, kiel Vi konas lian koron (ĉar Vi sola konas la koron de la homidoj);');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'por ke ili Vin timu, kaj por ke ili iradu laŭ Viaj vojoj dum la tuta tempo, kiun ili vivas sur la tero, kiun Vi donis al niaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Ankaŭ koncerne aligentulon, kiu ne estas el Via popolo Izrael, sed venos el malproksima lando pro Via granda nomo, pro Via forta mano, kaj pro Via etendita brako, kaj li venos kaj preĝos en ĉi tiu domo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'Vi aŭskultu el la ĉielo, el la loko de Via loĝado, kaj faru ĉion, pri kio vokos al Vi la aligentulo; por ke ĉiuj popoloj de la tero konu Vian nomon, kaj timu Vin tiel, kiel Via popolo Izrael, kaj por ke ili sciu, ke per Via nomo estas nomata ĉi tiu domo, kiun mi konstruis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Kiam Via popolo eliros milite kontraŭ siajn malamikojn laŭ la vojo, laŭ kiu Vi ilin sendos, kaj ili preĝos al Vi, turninte sin al ĉi tiu urbo, kiun Vi elektis, kaj al la domo, kiun mi konstruis al Via nomo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'tiam aŭskultu el la ĉielo ilian preĝon kaj ilian petegon, kaj defendu ilian aferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Se ili pekos antaŭ Vi (ĉar ne ekzistas homo, kiu ne pekus), kaj Vi ekkoleros kontraŭ ili kaj transdonos ilin al malamiko, kaj iliaj kaptintoj forkondukos ilin en landon malproksiman aŭ proksiman;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'sed ili rekonsciiĝos en la lando, en kiu ili estos kaptitaj, konvertiĝos, kaj petegos Vin en la lando de sia kaptiteco, dirante: Ni pekis, ni malbonagis, ni krimis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'kaj ili returnos sin al Vi per sia tuta koro kaj per sia tuta animo en la lando de sia kaptiteco, kien oni forkondukis ilin, kaj ili preĝos, turninte sin al sia lando, kiun Vi donis al iliaj patroj, kaj al la urbo, kiun Vi elektis, kaj al la domo, kiun mi konstruis al Via nomo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'tiam aŭskultu el la ĉielo, el la loko de Via loĝado, ilian preĝon kaj ilian petegon, defendu ilian aferon, kaj pardonu al Via popolo tion, per kio ili pekis antaŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Nun, ho mia Dio, Viaj okuloj estu nefermitaj kaj Viaj oreloj estu atentaj al la preĝo sur ĉi tiu loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Kaj nun leviĝu, ho Dio Eternulo, en Vian ripozejon, Vi kaj la arkeo de Via potenco. Viaj pastroj, ho Dio Eternulo, vestiĝu per savo, kaj Viaj fideluloj ĝuu bonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Ho Dio Eternulo, ne forturnu la vizaĝon de Via sanktoleito; memoru la favorkorecon koncerne Davidon, Vian servanton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Kiam Salomono finis la preĝadon, malleviĝis fajro el la ĉielo kaj forbruligis la bruloferon kaj la aliajn oferojn; kaj la majesto de la Eternulo plenigis la domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Kaj la pastroj ne povis eniri en la domon de la Eternulo, ĉar la majesto de la Eternulo plenigis la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Kaj ĉiuj Izraelidoj vidis, kiel la fajro kaj la majesto de la Eternulo malleviĝis sur la domon, kaj ili ekgenuis vizaĝaltere sur la pavimo, adorkliniĝis, kaj dankis la Eternulon, ke Li estas bona, ke eterna estas Lia favorkoreco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Kaj la reĝo kaj la tuta popolo faris oferojn antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'La reĝo Salomono oferis dudek du mil bovojn kaj cent dudek mil ŝafojn. Tiamaniere la reĝo kaj la tuta popolo inaŭguris la domon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'La pastroj staris sur siaj postenoj, kaj la Levidoj kun la muzikaj instrumentoj por la Eternulo, kiujn faris la reĝo David, por kanti dankon al la Eternulo, ke eterna estas Lia favorkoreco, per la laŭdkantoj de David; kaj la pastroj trumpetis apud ili, kaj ĉiuj Izraelidoj staris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Kaj Salomono sanktigis la mezon de la korto, kiu estis antaŭ la domo de la Eternulo; ĉar li faris tie la bruloferojn kaj alportis ofere la sebon de la pacoferoj; ĉar la kupra altaro, kiun Salomono faris, ne povis plene loki sur si la bruloferon, la farunoferon, kaj la sebon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'Kaj Salomono faris tiam feston dum sep tagoj, kaj kun li la tuta Izrael, tre granda anaro, kiu kunvenis de Ĥamat ĝis la torento de Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Kaj en la oka tago ili faris festofermon, ĉar la inaŭguron de la altaro ili faris dum sep tagoj kaj la feston dum sep tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'En la dudek-tria tago de la sepa monato li forsendis la popolon al ĝiaj tendoj, gajan kaj ĝojantan pro la bono, kiun la Eternulo faris al David, al Salomono, kaj al Sia popolo Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Tiamaniere Salomono sukcese finis la domon de la Eternulo kaj la reĝan domon, kaj ĉion, kion Salomono en sia koro faris en la domo de la Eternulo kaj en sia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Kaj la Eternulo aperis al Salomono en la nokto, kaj diris al li: Mi aŭdis vian preĝon, kaj Mi elektis al Mi ĉi tiun lokon kiel domon de oferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Se Mi ŝlosos la ĉielon tiel, ke ne estos pluvo, aŭ se Mi ordonos al la lokustoj primanĝi la teron, aŭ se Mi sendos peston sur Mian popolon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'sed Mia popolo, kiu portas Mian nomon, humiliĝos kaj preĝos kaj serĉos Mian vizaĝon kaj returnos sin de siaj malbonaj vojoj: tiam Mi aŭskultos el la ĉielo, kaj pardonos ilian pekon kaj resanigos ilian landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Nun Miaj okuloj estos nefermitaj kaj Miaj oreloj estos atentaj al preĝo sur ĉi tiu loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Nun Mi elektis kaj sanktigis ĉi tiun domon, por ke Mia nomo estu tie eterne; kaj Miaj okuloj kaj Mia koro estos tie ĉiutempe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Kaj se vi irados antaŭ Mi tiel, kiel iradis via patro David, kaj vi agados konforme al ĉio, kion Mi ordonis al vi, kaj vi observados Miajn leĝojn kaj preskribojn:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'tiam Mi fortikigos la tronon de via regno, kiel Mi promesis al via patro David, dirante: Ne mankos ĉe vi viro, reganta super Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Sed se vi deturnos vin, kaj forlasos Miajn leĝojn kaj Miajn ordonojn, kiujn Mi donis al vi, kaj vi iros kaj servos al aliaj dioj kaj adorkliniĝos antaŭ ili:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'tiam Mi elŝiros ilin el Mia lando, kiun Mi donis al ili; kaj ĉi tiun domon, kiun Mi sanktigis por Mia nomo, Mi forpuŝos de antaŭ Mia vizaĝo, kaj Mi faros ĝin proverbo kaj mokataĵo inter ĉiuj popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Kaj pri ĉi tiu domo, kiu estas tre alta, ĉiu preteriranto miregos, kaj diros: Pro kio la Eternulo agis tiele kun ĉi tiu lando kaj kun ĉi tiu domo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'Kaj oni respondos: Pro tio, ke ili forlasis la Eternulon, Dion de siaj patroj, kiu elkondukis ilin el la lando Egipta, kaj ili aliĝis al aliaj dioj kaj adorkliniĝis antaŭ ili kaj servis al ili-pro tio Li venigis sur ilin ĉi tiun tutan malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Post paso de la dudek jaroj, dum kiuj Salomono konstruis la domon de la Eternulo kaj sian domon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'kaj post kiam Salomono konstruis ankaŭ la urbojn, kiujn Ĥiram donis al Salomono, kaj li enloĝigis tie la Izraelidojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Salomono iris kontraŭ Ĥamat-Coban kaj venkoprenis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Kaj li konstruis Tadmoron en la dezerto, kaj ĉiujn urbojn de provizoj, kiujn li konstruis en Ĥamat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Li ankaŭ konstruis Bet-Ĥoronon la supran kaj Bet-Ĥoronon la malsupran, urbojn fortikigitajn kun muregoj, pordoj, kaj rigliloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'kaj Baalaton, kaj ĉiujn urbojn de provizoj, kiujn Salomono havis, kaj ĉiujn urbojn por la ĉaroj kaj la urbojn por la rajdistoj, kaj ĉion, kion Salomono deziris konstrui en Jerusalem kaj sur Lebanon kaj en la tuta lando de sia regado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Koncerne la tutan popolon, kiu restis el la Ĥetidoj, Amoridoj, Perizidoj, Ĥividoj, kaj Jebusidoj, kiuj ne estis el la Izraelidoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'el iliaj infanoj, kiuj restis post ili en la lando kaj kiujn la Izraelidoj ne ekstermis, Salomono faris tributulojn ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Sed el la Izraelidoj Salomono ne faris servantojn por liaj laboroj, ĉar ili estis militistoj, estroj de liaj korpogardistoj, estroj super liaj ĉaroj kaj super liaj rajdistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'La nombro de la ĉefaj oficistoj, kiujn havis la reĝo Salomono, estis ducent kvindek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'La filinon de Faraono elkondukis Salomono el la urbo de David en la domon, kiun li konstruis por ŝi; ĉar li diris: Virino ne devas loĝi ĉe mi en la domo de David, reĝo de Izrael, ĉar ĝi estas sankta pro tio, ke en ĝin eniris la kesto de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Tiam Salomono komencis alportadi bruloferojn al la Eternulo sur tiun altaron de la Eternulo, kiun li konstruis antaŭ la portiko,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'por oferadi laŭ la ordo de ĉiu tago, konforme al la ordono de Moseo pri la sabatoj, la monatkomencoj, kaj la festoj, kiuj estis tri fojojn en jaro, Pasko, Pentekosto, kaj festo de laŭboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Kaj li starigis, konforme al la preskribo de sia patro David, la partiojn de la pastroj por ilia servado, kaj la Levidojn por iliaj postenoj, por ke ili glorkantu kaj servu apud la pastroj laŭ la ordo de ĉiu tago, ankaŭ la pordegistojn laŭ iliaj grupoj por ĉiu pordego; ĉar tia estis la ordono de David, la homo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Kaj oni en nenio dekliniĝis de la ordono de la reĝo pri la pastroj kaj Levidoj kaj pri la trezoroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Tiele estis aranĝita la tuta laboro de Salomono de post la tago, kiam estis fondita la domo de la Eternulo, ĝis la domo de la Eternulo estis tuta preta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Tiam Salomono iris en Ecjon-Geberon kaj en Elaton, sur la bordo de la maro, en la lando de Edom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Kaj Ĥiram sendis al li per siaj servantoj ŝipojn, kaj servistojn, kiuj konis la maron; kaj ili veturis kun la servantoj de Salomono en Ofiron, kaj prenis de tie kvarcent kvindek kikarojn da oro kaj venigis al la reĝo Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Kiam la reĝino de Ŝeba aŭdis la famon pri Salomono, ŝi venis, por elprovi Salomonon per enigmoj, en Jerusalemon, kun tre granda akompanantaro, kun kameloj, portantaj aromaĵojn, multe da oro, kaj multekostajn ŝtonojn. Kaj ŝi venis al Salomono, kaj parolis kun li pri ĉio, kion ŝi havis sur sia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Kaj Salomono solvis al ŝi ĉiujn ŝiajn demandojn; kaj estis nenio, kion Salomono ne scius kaj kion li ne solvus al ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Kaj la reĝino de Ŝeba vidis la saĝecon de Salomono, kaj la domon, kiun li konstruis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'kaj la manĝaĵon de lia tablo kaj la loĝejon de liaj sklavoj kaj la oficojn de liaj servantoj kaj iliajn vestojn, liajn vinverŝistojn kaj iliajn vestojn, kaj lian iradon, kiam li iris en la domon de la Eternulo; kaj ŝi estis tute ravita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'Kaj ŝi diris al la reĝo: Vera estas tio, kion mi aŭdis en mia lando pri viaj aferoj kaj pri via saĝeco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'mi ne kredis iliajn vortojn, ĝis mi venis kaj ĝis miaj okuloj ekvidis; sed nun mi vidas, ke oni ne rakontis al mi eĉ duonon de via granda saĝeco: vi superas la famon, kiun mi aŭdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Feliĉaj estas viaj homoj, kaj feliĉaj estas viaj servantoj, kiuj ĉiam staras antaŭ vi kaj aŭdas vian saĝecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Benata estu la Eternulo, via Dio, kiu favoras vin kaj sidigis vin sur via trono kiel reĝon antaŭ la Eternulo, via Dio. Pro amo de via Dio al la Izraelidoj, por fortikigi ilin por ĉiam, Li faris vin reĝo super ili, por ke vi zorgu pri juĝo kaj justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Kaj ŝi donacis al la reĝo cent dudek kikarojn da oro kaj tre multe da aromaĵoj kaj multekostajn ŝtonojn; neniam estis aromaĵoj similaj al tiuj, kiujn la reĝino de Ŝeba donacis al la reĝo Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Kaj la servantoj de Ĥiram kaj la servantoj de Salomono, kiuj venigis oron el Ofir, venigis ankaŭ santalan lignon kaj multekostajn ŝtonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Kaj el la santala ligno la reĝo faris ŝtuparojn por la domo de la Eternulo kaj por la reĝa domo, ankaŭ harpojn kaj psalterojn por la kantistoj; neniam antaŭe oni vidis ion similan en la Juda lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Kaj la reĝo Salomono donis al la reĝino de Ŝeba ĉion, kion ŝi deziris kaj kion ŝi petis, krom tio, kion ŝi alportis al la reĝo. Kaj ŝi foriris returne en sian landon, ŝi kaj ŝiaj servantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'La pezo de la oro, kiu estis alportita al Salomono dum unu jaro, estis sescent sesdek ses kikaroj da oro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'krom tio la disportistoj kaj komercistoj alportadis, kaj ankaŭ ĉiuj reĝoj de Arabujo kaj la regionestroj alportadis al Salomono oron kaj arĝenton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Kaj la reĝo Salomono faris ducent grandajn ŝildojn el forĝita oro (sescent sikloj da forĝita oro estis uzitaj por ĉiu ŝildo),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'kaj tricent malgrandajn ŝildojn el forĝita oro (tricent sikloj da oro estis uzitaj por ĉiu el tiuj ŝildoj), kaj la reĝo metis ilin en la arbardomon de Lebanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Kaj la reĝo faris grandan tronon el eburo kaj tegis ĝin per pura oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Kaj ses ŝtupojn havis la trono, kaj oran piedbenketon, alfortikigitajn al la trono, kaj brakapogojn ambaŭflanke de la sidloko, kaj du leonojn, starantajn apud la brakapogoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Kaj ankoraŭ dek du leonoj tie staris sur la ses ŝtupoj ambaŭflanke; io simila ne ekzistis en iu regno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Kaj ĉiuj trinkvazoj de la reĝo Salomono estis el oro, kaj ĉiuj vazoj de la Lebanona arbardomo estis el pura oro; arĝento en la tempo de Salomono estis rigardata kiel senvalora.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Ĉar la reĝo havis ŝipojn, kiuj iradis en Tarŝiŝon kun la servantoj de Ĥiram; unu fojon en tri jaroj venadis la ŝipoj el Tarŝiŝ, alportante oron, arĝenton, eburon, simiojn, kaj pavojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Tiel la reĝo Salomono superis ĉiujn reĝojn de la tero per riĉeco kaj saĝeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Kaj ĉiuj reĝoj de la tero penis vidi Salomonon, por aŭdi lian saĝecon, kiun Dio enmetis en lian koron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Kaj ili alportadis ĉiu sian donacon: vazojn arĝentajn, vazojn orajn, vestojn, batalilojn, aromaĵojn, ĉevalojn, kaj mulojn, ĉiujare.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Kaj Salomono havis kvar mil ĉevalstalojn, ĉarojn, kaj dek du mil rajdistojn; kaj li lokis ilin en la urboj de ĉaroj kaj ĉe la reĝo en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Li regis super ĉiuj reĝoj, de la Rivero ĝis la lando Filiŝta kaj ĝis la limo de Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Kaj la reĝo atingis tion, ke la arĝento en Jerusalem estis kiel ŝtonoj, kaj la cedroj estis en tiel granda kvanto, kiel sikomoroj sur malaltaj lokoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Ĉevalojn oni venigadis al Salomono el Egiptujo kaj el ĉiuj landoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'La tuta cetera historio de Salomono, la unua kaj la lasta, estas priskribita en la kroniko de la profeto Natan, en la profetaĵoj de Aĥija, la Ŝiloano, kaj en la vizioj de Jedo, la viziisto, pri Jerobeam, filo de Nebat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Kaj Salomono reĝis en Jerusalem super la tuta Izrael kvardek jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Kaj Salomono ekdormis kun siaj patroj, kaj oni enterigis lin en la urbo de lia patro David. Kaj anstataŭ li ekreĝis Reĥabeam, lia filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Reĥabeam iris en Ŝeĥemon, ĉar en Ŝeĥemon venis ĉiuj Izraelidoj, por fari lin reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Kiam tion aŭdis Jerobeam, filo de Nebat (ĉar li estis en Egiptujo, kien li forkuris de la reĝo Salomono), Jerobeam revenis el Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Kaj oni sendis, kaj vokis lin. Tiam venis Jerobeam kaj la tuta Izrael, kaj ili ekparolis al Reĥabeam, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Via patro tro pezigis nian jugon; nun deprenu iom de la malfacilaj laboroj de via patro, kaj de lia peza jugo, kiun li metis sur nin, kaj tiam ni servados al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Kaj li diris al ili: Post tri tagoj revenu al mi. Kaj la popolo disiris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Kaj la reĝo Reĥabeam konsiliĝis kun la maljunuloj, kiuj staradis antaŭ lia patro Salomono dum lia vivo, kaj li diris: Kiel vi konsilas respondi al ĉi tiu popolo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'Kaj ili diris al li jene: Se vi estos bona al ĉi tiu popolo kaj montros al ili favoron kaj parolos al ili bonajn vortojn, ili estos al vi servantoj por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Sed li ne atentis la konsilon de la maljunuloj, kiun ili donis al li; kaj li konsiliĝis kun la junuloj, kiuj elkreskis kune kun li kaj staris antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Kaj li diris al ili: Kion vi konsilas, ke ni respondu al ĉi tiu popolo, kiu diris al mi jene: Faru malpli peza la jugon, kiun via patro metis sur nin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Kaj la junuloj, kiuj elkreskis kune kun li, parolis al li, dirante: Tiele diru al la popolo, kiu diris al vi: Via patro faris nian jugon tro peza, kaj vi faru ĝin malpli peza-tiele diru al ili: Mia malgranda fingro estas pli dika, ol la lumboj de mia patro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'tial se mia patro ŝarĝis vin per peza jugo, mi ankoraŭ pli pezigos vian jugon; mia patro vin punadis per vipoj, sed mi vin punados per skorpioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Kaj Jerobeam kaj la tuta popolo venis al Reĥabeam en la tria tago, kiel la reĝo ordonis, dirante: Revenu al mi en la tria tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'Kaj la reĝo respondis al ili malafable; kaj la reĝo Reĥabeam ne atentis la konsilon de la maljunuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'kaj li parolis al ili laŭ la konsilo de la junuloj, dirante: Mia patro pezigis vian jugon, sed mi ĝin ankoraŭ pli pezigos; mia patro vin punadis per vipoj, sed mi vin punados per skorpioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Kaj la reĝo ne aŭskultis la popolon; ĉar estis tiel destinite de Dio, por ke la Eternulo plenumu Sian vorton, kiun Li diris per Aĥija, la Ŝiloano, al Jerobeam, filo de Nebat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Kiam ĉiuj Izraelidoj vidis, ke la reĝo ilin ne obeas, tiam la popolo respondis al la reĝo, dirante: Kian parton ni havas en David? ni ne havas heredaĵon en la filo de Jiŝaj; iru, ho Izraelidoj, ĉiu al sia tendo! nun zorgu mem pri via domo, ho David! Kaj ĉiuj Izraelidoj disiris al siaj tendoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Sed super la Izraelidoj, kiuj loĝis en la urboj de Judujo, regis Reĥabeam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Kaj la reĝo Reĥabeam sendis Hadoramon, la estron super la impostoj; sed la Izraelidoj ĵetis sur lin ŝtonojn, kaj li mortis. Kaj la reĝo Reĥabeam rapide sidiĝis en ĉaro, por forkuri en Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Tiamaniere Izrael defalis de la domo de David ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Kiam Reĥabeam venis en Jerusalemon, li kolektis el la domo de Jehuda kaj de Benjamen cent okdek mil elektitajn militistojn, por militi kontraŭ Izrael, por revenigi la regnon al Reĥabeam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Sed aperis vorto de la Eternulo al Ŝemaja, homo de Dio, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Diru al Reĥabeam, filo de Salomono, reĝo de Judujo, kaj al ĉiuj Izraelidoj en la lando de Jehuda kaj de Benjamen jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Tiele diras la Eternulo: Ne iru kaj ne militu kontraŭ viaj fratoj; reiru ĉiu al sia domo, ĉar de Mi estas farita ĉi tiu afero. Kaj ili obeis la vortojn de la Eternulo, kaj rifuzis iri kontraŭ Jerobeamon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Reĥabeam loĝis en Jerusalem, kaj li konstruis fortikaĵojn en la urboj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Li prikonstruis Bet-Leĥemon, Etamon, Tekoan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Bet-Curon, Soĥon, Adulamon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Gaton, Mareŝan, Zifon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adoraimon, Laĥiŝon, Azekan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Corean, Ajalonon, kaj Ĥebronon, kiuj estis urboj fortikigitaj en la lando de Jehuda kaj de Benjamen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Li fortigis tiujn fortikaĵojn kaj starigis tie estrojn, aranĝis provizejojn de manĝaĵoj, oleo, kaj vino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'Kaj en ĉiu urbo li kolektis ŝildojn kaj lancojn, kaj tre fortigis ilin. Kaj Jehuda kaj Benjamen restis liaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'La pastroj kaj Levidoj, kiuj estis en la tuta lando de Izrael, kolektiĝis al li el ĉiuj siaj regionoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'la Levidoj forlasis siajn antaŭurbojn kaj sian posedaĵon kaj iris en Judujon kaj Jerusalemon, ĉar Jerobeam kaj liaj filoj forpuŝis ilin de la pastrado al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'Li starigis ĉe si pastrojn por la altaĵoj, por la kaproj kaj bovidoj, kiujn li faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Post ili el ĉiuj triboj de Izrael tiuj homoj, kiuj havis la inklinon turnadi sin al la Eternulo, Dio de Izrael, venadis en Jerusalemon, por fari oferojn al la Eternulo, Dio de iliaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Kaj ili fortigadis la regnon de Judujo, kaj subtenadis Reĥabeamon, filon de Salomono, dum tri jaroj; ĉar ili iradis laŭ la vojo de David kaj Salomono dum tri jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Reĥabeam prenis al si kiel edzinon Maĥalaton, filinon de Jerimot, filo de David, kaj de Abiĥail, filino de Eliab, filo de Jiŝaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Ŝi naskis al li filojn: Jeuŝ, Ŝemarja, kaj Zaham.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Post ŝi li prenis Maaĥan, filinon de Abŝalom; kaj ŝi naskis al li Abijan, Atajon, Zizan, kaj Ŝelomiton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Reĥabeam amis Maaĥan, filinon de Abŝalom, pli ol ĉiujn siajn edzinojn kaj kromvirinojn; ĉar li havis dek ok edzinojn kaj sesdek kromvirinojn, kaj li naskigis dudek ok filojn kaj sesdek filinojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Reĥabeam starigis Abijan, filon de Maaĥa, kiel ĉefon, kiel princon inter liaj fratoj, intencante fari lin reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'Li agadis prudente; li dissendis ĉiujn siajn filojn en ĉiujn regionojn de Jehuda kaj de Benjamen, en ĉiujn fortikigitajn urbojn; li donis al ili grandajn vivrimedojn kaj prenis por ili multe da edzinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Kiam fortikiĝis la regno de Reĥabeam kaj li fariĝis forta, li forlasis la instruon de la Eternulo, kaj kun li la tuta Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'En la kvina jaro de la reĝo Reĥabeam iris Ŝiŝak, reĝo de Egiptujo, kontraŭ Jerusalemon (ĉar ili pekis kontraŭ la Eternulo)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'kun mil ducent ĉaroj kaj sesdek mil rajdistoj; sennombra estis la popolo, kiu venis kun li el Egiptujo: la Luboj, Sukioj, kaj Etiopoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Kaj li venkoprenis la fortikigitajn urbojn de Judujo kaj aliris ĝis Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Tiam la profeto Ŝemaja venis al Reĥabeam, kaj al la estroj de Judujo, kiuj kolektiĝis en Jerusalem pro Ŝiŝak, kaj li diris al ili: Tiele diras la Eternulo: Vi forlasis Min, tial ankaŭ Mi forlasas vin en la manojn de Ŝiŝak.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Tiam humiliĝis la estroj de Izrael kaj la reĝo, kaj diris: Justa estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Kiam la Eternulo vidis, ke ili humiliĝis, tiam aperis vorto de la Eternulo al Ŝemaja, dirante: Ili humiliĝis, tial Mi ne ekstermos ilin; Mi donos al ili iom da savo, kaj Mia kolero ne elverŝiĝos sur Jerusalemon per Ŝiŝak;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'tamen ili estos liaj subuloj, por ke ili eksciu, kio estas servado al Mi kaj servado al teraj regnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Kaj Ŝiŝak, reĝo de Egiptujo, iris kontraŭ Jerusalemon, kaj li forprenis la trezorojn de la domo de la Eternulo kaj la trezorojn de la reĝa domo, ĉion li prenis; li prenis ankaŭ la orajn ŝildojn, kiujn faris Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'Kaj la reĝo Reĥabeam faris anstataŭ ili ŝildojn kuprajn, kaj transdonis ilin en la manojn de la estroj de korpogardistoj, kiuj gardadis la enirejon de la reĝa domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Kaj ĉiufoje, kiam la reĝo iris en la domon de la Eternulo, venis la korpogardistoj, portis ilin, kaj poste returne portis ilin en la ĉambron de la korpogardistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Kiam li humiliĝis, tiam deturniĝis de li la kolero de la Eternulo, kaj ne ĉio pereis; ĉar en Judujo estis ankoraŭ io bona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'La reĝo Reĥabeam fortikiĝis en Jerusalem, kaj li reĝis. La aĝon de kvardek unu jaroj havis Reĥabeam, kiam li fariĝis reĝo; kaj dek sep jarojn li reĝis en Jerusalem, la urbo, kiun elektis la Eternulo inter ĉiuj triboj de Izrael, por estigi tie Sian nomon. La nomo de lia patrino estis Naama, la Amonidino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Li agis malbone, ĉar li ne alkutimigis sian koron al serĉado de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'La historio de Reĥabeam, la unua kaj la lasta, estas priskribita en la kronikoj de la profeto Ŝemaja kaj de la viziisto Ido, ĉe la genealogio. Kaj inter Reĥabeam kaj Jerobeam estis militoj dum ilia tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Kaj Reĥabeam ekdormis kun siaj patroj, kaj oni enterigis lin en la urbo de David. Kaj anstataŭ li ekreĝis lia filo Abija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'En la dek-oka jaro de la reĝo Jerobeam ekreĝis Abija super Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Tri jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Miĥaja, filino de Uriel, el Gibea. Milito estis inter Abija kaj Jerobeam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Abija eliris en la militon kun anaro da bonaj militistoj, konsistanta el kvarcent mil viroj elektitaj; Jerobeam eliris en la militon kontraŭ li kun okcent mil viroj elektitaj, bonaj militistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Abija stariĝis supre sur la monto Cemaraim, kiu estas en la montaro de Efraim, kaj diris: Aŭskultu min, ho Jerobeam kaj la tuta Izrael!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Vi devas ja scii, ke la Eternulo, Dio de Izrael, donis la reĝadon super Izrael por ĉiam al David, al li kaj al liaj filoj, per interligo de salo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Sed leviĝis Jerobeam, filo de Nebat, servanto de Salomono, filo de David, kaj ribelis kontraŭ sia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'Kaj kolektiĝis ĉirkaŭ li homoj vantaj, homoj malvirtaj, kaj superfortis Reĥabeamon, filon de Salomono; Reĥabeam estis juna kaj molkora kaj ne povis rezisti al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Kaj nun vi pensas, ke vi havos forton kontraŭ la regno de la Eternulo en la mano de la filoj de David, ĉar vi prezentas grandan amason, kaj vi havas orajn bovidojn, kiujn Jerobeam faris dioj por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Vi elpuŝis ja la pastrojn de la Eternulo, la Aaronidojn kaj Levidojn, kaj vi faris al vi pastrojn kiel la popoloj de la aliaj landoj; ĉiu, kiu venas por sia konsekrado kun bovo kaj kun sep ŝafoj, fariĝas pastro por la nedioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Sed kun ni estas la Eternulo, nia Dio; ni ne forlasis Lin; kaj al la Eternulo servas pastroj Aaronidoj kaj Levidoj laŭ ilia ofico,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'kaj ili bruligas al la Eternulo bruloferojn ĉiumatene kaj ĉiuvespere, kaj incensan aromaĵon, kaj ili aranĝas panon sur pura tablo, kaj la oran kandelabron kun ĝiaj lucernoj, ke ili brulu ĉiuvespere; ĉar ni plenumas la preskribon de la Eternulo, nia Dio, kaj vi forlasis Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Vidu, kun ni, kiel nia ĉefo, estas Dio, kaj ankaŭ Liaj pastroj kaj laŭtesonaj trumpetoj, por trumpetegi kontraŭ vi. Ho Izraelidoj, ne militu kontraŭ la Eternulo, Dio de viaj patroj, ĉar vi ne havos sukceson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Dume Jerobeam ĉirkaŭirigis embuskon, kiu aperis malantaŭ ili; tiamaniere estis militistoj antaŭ la Judoj kaj embusko malantaŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'La Judoj sin returnis, kaj ekvidis, ke ili havas batalon antaŭe kaj malantaŭe. Tiam ili ekkriis al la Eternulo, kaj la pastroj ektrumpetis per la trumpetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Kaj la Judoj laŭte ekbruis; kaj kiam la Judoj ekbruis, Dio frapis Jerobeamon kaj ĉiujn Izraelidojn antaŭ Abija kaj la Judoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Kaj la Izraelidoj ekkuris antaŭ la Judoj, kaj Dio transdonis ilin en la manojn de ĉi tiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Kaj Abija kaj lia popolo faris inter ili grandan baton; kaj falis mortigitoj el Izrael kvincent mil viroj elektitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Tiam humiliĝis la Izraelidoj, kaj fortiĝis la Judoj, ĉar ili apogis sin sur la Eternulo, Dio de iliaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Kaj Abija persekutis Jerobeamon, kaj prenis de li urbojn: Bet-Elon kun ĝiaj filinurboj, Jeŝanan kun ĝiaj filinurboj, kaj Efrainon kun ĝiaj filinurboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Kaj Jerobeam ne plu refortiĝis en la tempo de Abija. Kaj la Eternulo frapis lin, kaj li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Sed Abija fortiĝis. Kaj li prenis al si dek kvar edzinojn, kaj li naskigis dudek du filojn kaj dek ses filinojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'La cetera historio de Abija, liaj agoj, kaj liaj vortoj estas priskribitaj en la komentario de la profeto Ido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Kaj Abija ekdormis kun siaj patroj, kaj oni enterigis lin en la urbo de David. Kaj anstataŭ li ekreĝis lia filo Asa. En lia tempo la lando estis trankvila dum dek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Asa agadis bone kaj juste antaŭ la Eternulo, sia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Li forigis la altarojn de fremdaj dioj kaj la altaĵojn, li disbatis la statuojn, kaj dehakis la sanktajn stangojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'Kaj li ordonis al la Judoj turni sin al la Eternulo, Dio de iliaj patroj, por plenumi la instruon kaj la ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Li forigis el ĉiuj urboj de Judujo la altaĵojn kaj la kolonojn de la suno. Kaj la regno estis trankvila sub li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Li konstruis urbojn fortikigitajn en Judujo; la lando estis trankvila, kaj li ne havis militon en tiuj jaroj, ĉar la Eternulo donis al li ripozon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Kaj li diris al la Judoj: Ni prikonstruu ĉi tiujn urbojn, ni ĉirkaŭigu ilin per muregoj kaj turoj, pordoj, kaj rigliloj. La lando estas ankoraŭ nia, ĉar ni turnis nin al la Eternulo, nia Dio; ni turnis nin, kaj Li donis al ni trankvilecon ĉirkaŭe. Kaj ili konstruis, kaj la afero iris sukcese.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Kaj Asa havis militistaron: da viroj armitaj per ŝildo kaj lanco el la Jehudaidoj tricent mil, kaj el la Benjamenidoj da viroj portantaj manŝildon kaj pafantaj per pafarko estis ducent okdek mil; ĉiuj ili estis bravaj militistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Eliris kontraŭ ilin Zeraĥ, la Etiopo, kun militistaro de unu miliono kaj kun tricent ĉaroj, kaj li venis ĝis Mareŝa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Kaj eliris Asa renkonte al li, kaj ili aranĝiĝis al batalo en la valo Cefata, apud Mareŝa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Kaj Asa ekvokis al la Eternulo, sia Dio, kaj diris: Ho Eternulo, por Vi ne estas diferenco helpi al grandnombrulo aŭ al senfortulo; helpu do al ni, ho Eternulo, nia Dio, ĉar sur Vi ni nin apogas kaj en Via nomo ni venis kontraŭ ĉi tiun grandan anaron. Ho Eternulo, Vi estas nia Dio; kontraŭ Vi neniu homo montriĝu forta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Kaj la Eternulo frapis la Etiopojn antaŭ Asa kaj antaŭ la Judoj, kaj la Etiopoj forkuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Kaj Asa, kaj la popolo, kiu estis kun li, persekutis ilin ĝis Gerar; kaj la Etiopoj falis tiel, ke neniu el ili restis vivanta; ĉar ili estis frakasitaj antaŭ la Eternulo kaj antaŭ Lia militistaro. Kaj ili forportis tre multe da militakiraĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Kaj ili venkobatis ĉiujn urbojn ĉirkaŭe de Gerar, ĉar sur ilin falis teruro de la Eternulo; kaj ili prirabis ĉiujn urbojn, ĉar en ili troviĝis multe da rabeblaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'Ankaŭ ili disbatis la tendojn de la brutoj, kaptis multe da ŝafoj kaj da kameloj, kaj revenis en Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Sur Azarjan, filon de Oded, venis la spirito de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Kaj li eliris antaŭ Asan, kaj diris al li: Aŭskultu min, ho Asa kaj ĉiuj Jehudaidoj kaj Benjamenidoj: la Eternulo estas kun vi, kiam vi estas kun Li; kaj se vi Lin serĉos, vi Lin trovos, sed se vi Lin forlasos, Li forlasos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Dum longa tempo Izrael estos sen la vera Dio, sen instruanta pastro, kaj sen instruo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'sed en sia mizero ili returnos sin al la Eternulo, Dio de Izrael; kaj ili serĉos Lin, kaj Li trovigos Sin al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'En tiu tempo ne havos pacon la eliranto nek la eniranto, ĉar grandaj tumultoj estos ĉe ĉiuj loĝantoj de la landoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Nacio disbatos nacion kaj urbo urbon, ĉar Dio konfuzos ilin per diversaj malfeliĉoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Sed vi estu kuraĝaj, kaj ne faligu viajn manojn; ĉar ekzistas rekompenco pro viaj faroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Kiam Asa aŭdis tiujn vortojn kaj la profetaĵon de la profeto Oded, li kuraĝiĝis, kaj elĵetis la abomenindaĵojn el la tuta lando de Jehuda kaj de Benjamen, kaj el la urboj, kiujn li venkoprenis sur la monto de Efraim; kaj li renovigis la altaron de la Eternulo, starantan antaŭ la portiko de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Kaj li kunvenigis ĉiujn Jehudaidojn kaj Benjamenidojn, kaj la kun ili loĝantajn enmigrintojn el la tribo de Efraim, de Manase, kaj de Simeon; ĉar ili en granda nombro transiris al li de Izrael, kiam ili vidis, ke la Eternulo, lia Dio, estas kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Kaj ili kunvenis en Jerusalemon en la tria monato de la dek-kvina jaro de la reĝado de Asa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'Kaj ili alportis en tiu tago oferojn al la Eternulo el la militakiraĵo, kiun ili venigis: sepcent bovojn kaj sep mil ŝafojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Kaj ili faris interligon, ke ili strebados al la Eternulo, Dio de iliaj patroj, per sia tuta koro kaj per sia tuta animo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'kaj ke ĉiu, kiu ne turnos sin al la Eternulo, Dio de Izrael, devas morti, ĉu tio estas malgranda, ĉu granda, ĉu viro, ĉu virino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'Kaj ili ĵuris al la Eternulo per laŭta voĉo, per ĝojkriado, per trumpetoj kaj kornoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Kaj ĉiuj Judoj ĝojis pri la ĵuro, ĉar ili ĵuris el sia tuta koro, ili serĉis Lin kun plena fervoro, kaj Li trovigis Sin al ili. Kaj la Eternulo donis al ili trankvilecon ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Kaj eĉ Maaĥan, la patrinon, la reĝo Asa senigis je ŝia titolo de reĝino, pro tio, ke ŝi faris idolon por Aŝtar. Kaj Asa dishakis ŝian idolon, dispecigis ĝin kaj forbruligis ĉe la torento Kidron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Tamen la altaĵoj ne estis forigitaj ĉe Izrael; sed la koro de Asa estis perfekta dum lia tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Li enportis en la domon de Dio la konsekritaĵojn de sia patro, kaj siajn proprajn konsekritaĵojn, arĝenton kaj oron kaj vazojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Kaj ne estis milito ĝis la tridek-kvina jaro de la reĝado de Asa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'En la tridek-sesa jaro de la reĝado de Asa iris Baaŝa, reĝo de Izrael, kontraŭ Judujon, kaj li konstruis Raman, por bari la eliradon kaj eniradon al Asa, reĝo de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Tiam Asa elprenis arĝenton kaj oron el la trezorejoj de la domo de la Eternulo kaj de la reĝa domo, kaj sendis al Ben-Hadad, reĝo de Sirio, kiu loĝis en Damasko, kaj dirigis al li:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Estas interligo inter mi kaj vi, kiel inter mia patro kaj via patro; jen mi sendas al vi arĝenton kaj oron: neniigu vian interligon kun Baaŝa, reĝo de Izrael, por ke li foriru de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Kaj Ben-Hadad obeis la reĝon Asa, kaj sendis siajn militestrojn kontraŭ la urbojn de Izrael, kaj ili venkobatis Ijonon kaj Danon kaj Abel- Maimon, kaj ĉiujn provizejojn en la urboj de Naftali.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Kiam Baaŝa tion aŭdis, li ĉesis konstrui Raman kaj haltigis sian laboradon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Tiam la reĝo Asa prenis ĉiujn Judojn; kaj ili forportis la ŝtonojn de Rama kaj ĝian lignon, el kiuj Baaŝa faris la konstruadon; kaj li konstruis el tio Geban kaj Micpan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'En tiu tempo venis la antaŭvidisto Ĥanani al Asa, reĝo de Judujo, kaj diris al li: Ĉar vi apogis vin sur la reĝo de Sirio, kaj ne apogis vin sur la Eternulo, via Dio, tial saviĝis el via mano la militistaro de la reĝo de Sirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Ĉu la Etiopoj kaj Luboj ne estis kun granda forto, kun ĉaroj kaj rajdistoj en tre granda nombro? tamen, ĉar vi apogis vin sur la Eternulo, Li transdonis ilin en vian manon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'ĉar la okuloj de la Eternulo ĉirkaŭrigardas la tutan teron, por subteni tiujn, kies koro estas plene aldonita al Li. Malsaĝe vi agis per ĉi tio; pro tio de nun vi havos militojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Asa ekkoleris kontraŭ la antaŭvidisto kaj metis lin en malliberejon, ĉar li indignis kontraŭ li pro tio; ankaŭ kelkajn el la popolo Asa premis en tiu tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'La historio de Asa, la unua kaj la lasta, estas priskribita en la libro de la reĝoj de Judujo kaj Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'En la tridek-naŭa jaro de sia reĝado Asa malsaniĝis je siaj piedoj; tre forta fariĝis lia malsano; sed eĉ en sia malsano li turnis sin ne al la Eternulo, sed al kuracistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Kaj Asa ekdormis kun siaj patroj, kaj mortis en la kvardek-unua jaro de sia reĝado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Kaj oni enterigis lin en lia tombo, kiun li pretigis al si en la urbo de David; kaj oni kuŝigis lin sur lito plenigita de aromaĵoj kaj diversaj lerte preparitaj ŝmiraĵoj, kaj oni faris por li tre grandan brulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Anstataŭ li ekreĝis lia filo Jehoŝafat. Kaj li fariĝis potenca kontraŭ Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'Li starigis militistaron en ĉiuj fortikigitaj urboj de Judujo, kaj starigis garnizonojn en la lando de Jehuda, kaj en la urboj de Efraim, kiujn venkoprenis lia patro Asa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Kaj la Eternulo estis kun Jehoŝafat, ĉar li iradis laŭ la antaŭaj vojoj de sia patro David kaj ne turnis sin al la Baaloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'sed nur la Dion de sia patro li serĉis kaj Liajn ordonojn li sekvis, ne simile al la agado de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Kaj la Eternulo fortikigis la regnon en lia mano, kaj ĉiuj Judoj donacis donacojn al Jehoŝafat, kaj li havis multe da riĉeco kaj da honoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Lia koro altiĝis sur la vojoj de la Eternulo; li ankaŭ forigis la altaĵojn kaj la sanktajn stangojn el Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'En la tria jaro de lia reĝado li sendis siajn eminentulojn Ben-Ĥail, Obadja, Zeĥarja, Netanel, kaj Miĥaja, ke ili instruu en la urboj de Judujo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'kaj kun ili la Levidojn Ŝemaja, Netanja, Zebadja, Asahel, Ŝemiramot, Jehonatan, Adonija, Tobija, kaj Tob-Adonija, la Levidojn, kaj kun ili la pastrojn Eliŝama kaj Jehoram.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Kaj ili instruis en Judujo, havante kun si libron de instruo de la Eternulo; ili trairis ĉiujn urbojn de Judujo kaj instruis la popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Kaj timo antaŭ la Eternulo estis en ĉiuj regnoj de la landoj, kiuj estis ĉirkaŭ Judujo, kaj ili ne militis kontraŭ Jehoŝafat.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'De la Filiŝtoj oni alportadis al Jehoŝafat donacojn, kaj arĝenton kiel tributon; ankaŭ la Araboj venigadis al li malgrandajn brutojn: sep mil sepcent ŝafojn kaj sep mil sepcent kaprojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Jehoŝafat fariĝadis ĉiam pli granda kaj atingis grandan altecon. Kaj li konstruis en Judujo kastelojn kaj grenurbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'Kaj multe da laboroj li havis en la urboj de Judujo, kaj bravajn militistojn en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'Jen estas ilia ordo laŭ iliaj patrodomoj: ĉe la Jehudaidoj estis milestroj: la estro Adna, kaj kun li estis tricent mil bravaj militistoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'apud li estis la estro Jehoĥanan, kaj kun li ducent okdek mil;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'apud li estis Amasja, filo de Ziĥri, kiu konsekris sin al la Eternulo, kaj kun li estis ducent mil bravaj militistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Ĉe la Benjamenidoj estis: brava militisto Eljada, kaj kun li ducent mil viroj armitaj per pafarko kaj ŝildo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'apud li estis Jehozabad, kaj kun li cent okdek mil viroj armitaj por la militistaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Tiuj servis al la reĝo, krom tiuj, kiujn la reĝo starigis en la fortikigitaj urboj de la tuta Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Jehoŝafat havis multe da riĉeco kaj honoro; kaj li boparenciĝis kun Aĥab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Post kelke da jaroj li veturis al Aĥab en Samarion. Kaj Aĥab buĉis multe da ŝafoj kaj bovoj por li, kaj por la popolo, kiu estis kun li, kaj konvinkis lin iri kontraŭ Ramoton en Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Kaj Aĥab, reĝo de Izrael, diris al Jehoŝafat, reĝo de Judujo: Ĉu vi iros kun mi kontraŭ Ramoton en Gilead? Kaj ĉi tiu respondis al li: Mi estas kiel vi, kaj mia popolo estas kiel via popolo; ni iros kun vi en la militon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Kaj Jehoŝafat diris al la reĝo de Izrael: Demandu hodiaŭ la vorton de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Tiam la reĝo de Izrael kunvenigis la profetojn, kvarcent homojn, kaj diris al ili: Ĉu ni iru milite kontraŭ Ramoton en Gilead, aŭ mi tion ne faru? Kaj ili respondis: Iru, kaj Dio ĝin transdonos en la manon de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Sed Jehoŝafat diris: Ĉu ne troviĝas ĉi tie ankoraŭ iu profeto de la Eternulo, kiun ni povus demandi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Kaj la reĝo de Izrael diris al Jehoŝafat: Ekzistas ankoraŭ unu homo, per kiu ni povas demandi la Eternulon, sed mi lin malamas, ĉar neniam li profetas pri mi ion bonan, sed dum sia tuta vivo nur malbonon; tio estas Miĥaja, filo de Jimla. Sed Jehoŝafat diris: La reĝo ne parolu tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Tiam la reĝo de Izrael alvokis unu korteganon, kaj diris: Venigu rapide Miĥajan, filon de Jimla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'La reĝo de Izrael, kaj Jehoŝafat, reĝo de Judujo, sidis ĉiu sur sia seĝo, vestitaj per siaj vestoj; ili sidis sur placo antaŭ la pordego de Samario, kaj ĉiuj profetoj profetadis antaŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Kaj Cidkija, filo de Kenaana, faris al si ferajn kornojn, kaj diris: Tiele diras la Eternulo: Per ĉi tio vi kornobatos la Sirianojn, ĝis vi ilin tute ekstermos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Kaj ĉiuj profetoj profetis tiel same, dirante: Iru kontraŭ Ramoton en Gilead kaj sukcesu, ĉar la Eternulo ĝin transdonos en la manon de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'La sendito, kiu iris por voki Miĥajan, diris al li: Jen la vortoj de la profetoj unuanime antaŭdiras bonon al la reĝo; estu do via vorto simila al la vorto de ĉiu el ili, kaj antaŭdiru bonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Sed Miĥaja diris: Kiel vivas la Eternulo: kion mia Dio diros al mi, tion mi diros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Kaj kiam li venis al la reĝo, la reĝo diris al li: Miĥaja! ĉu ni iru milite kontraŭ Ramoton en Gilead, aŭ ni tion ne faru? Kaj tiu diris: Iru kaj sukcesu, kaj ili estos transdonitaj en vian manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Tiam la reĝo diris al li: Multfoje mi vin ĵurligas, ke vi parolu al mi nur la veron en la nomo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Kaj tiu diris: Mi vidis ĉiujn Izraelidojn disĵetitaj sur la montoj, kiel ŝafoj, kiuj ne havas paŝtanton; kaj la Eternulo diris: Ili ne havas estrojn, ili reiru pace ĉiu al sia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Kaj la reĝo de Izrael diris al Jehoŝafat: Ĉu mi ne diris al vi, ke li profetos pri mi ne bonon, sed nur malbonon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Sed Miĥaja diris: Tial aŭskultu la vorton de la Eternulo: mi vidis la Eternulon, sidantan sur Sia trono, kaj la tuta armeo de la ĉielo staris dekstre kaj maldekstre de Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Kaj la Eternulo diris: Kiu allogos Aĥabon, reĝon de Izrael, ke li iru kaj falu en Ramot en Gilead? Kaj unu parolis tiel, alia parolis alie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Tiam eliris spirito kaj stariĝis antaŭ la Eternulo, kaj diris: Mi lin allogos. Kaj la Eternulo diris al li: Per kio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Kaj tiu respondis: Mi eliros kaj faros min spirito mensoga en la buŝo de ĉiuj liaj profetoj. Kaj Li diris: Vi allogos kaj havos sukceson; eliru kaj agu tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Kaj nun jen la Eternulo metis mensogan spiriton en la buŝon de tiuj viaj profetoj, kaj la Eternulo decidis por vi malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Tiam aliris Cidkija, filo de Kenaana, kaj frapis Miĥajan sur la vango, kaj diris: Per kiu vojo la spirito de la Eternulo transiris de mi, por paroli per vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Miĥaja respondis: Jen vi tion vidos en tiu tago, kiam vi eniros en internan ĉambron, por vin kaŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Tiam la reĝo de Izrael diris: Prenu Miĥajan, kaj konduku lin al la urbestro Amon kaj al la reĝido Joaŝ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'kaj diru: Tiele diras la reĝo: Metu ĉi tiun en malliberejon, kaj nutru lin per mizera pano kaj mizera akvo, ĝis mi revenos en paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Sed Miĥaja diris: Se vi revenos en paco, en tiu okazo ne parolis per mi la Eternulo. Kaj li diris: Aŭskultu, ĉiuj popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Kaj la reĝo de Izrael, kaj Jehoŝafat, reĝo de Judujo, iris al Ramot en Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Kaj la reĝo de Izrael diris al Jehoŝafat: Mi alivestos min kaj iros en la batalon, sed vi surmetu viajn vestojn. Kaj la reĝo de Izrael alivestis sin, kaj ili iris en la batalon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Kaj la reĝo de Sirio ordonis al siaj ĉarestroj jene: Batalu ne kontraŭ iu malgranda aŭ granda, sed sole nur kontraŭ la reĝo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Kiam la ĉarestroj ekvidis Jehoŝafaton, ili pensis, ke tio estas la reĝo de Izrael, kaj ili ĉirkaŭis lin, por batali kontraŭ li; sed Jehoŝafat ekkriis, kaj la Eternulo helpis al li, kaj Dio forigis ilin de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Kiam la ĉarestroj vidis, ke tio ne estas la reĝo de Izrael, ili forturnis sin de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Kaj unu viro sen ia celo streĉis la pafarkon, kaj vundis la reĝon de Izrael inter la artikoj de la kiraso. Kaj ĉi tiu diris al sia veturiganto: Turnu vian manon kaj elveturigu min el la militistaro, ĉar mi estas vundita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Sed la batalo plifortiĝis en tiu tago; kaj la reĝo de Izrael staris sur la ĉaro kontraŭ la Sirianoj ĝis la vespero, kaj li mortis en la momento de la malleviĝo de la suno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Jehoŝafat, reĝo de Judujo, revenis bonstate en sian hejmon, en Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Kaj eliris renkonte al li Jehu, filo de Ĥanani, la viziisto, kaj diris al la reĝo Jehoŝafat: Ĉu oni devas helpi al malvirtulo? vi amas la malamikojn de la Eternulo, kaj pro tio estas sur vi la kolero de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Tamen bonaĵoj estas trovitaj en vi, ĉar vi ekstermis la sanktajn stangojn el la lando kaj direktis vian koron al la serĉado de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Kaj Jehoŝafat loĝis en Jerusalem. Kaj denove li iris al la popolo, de Beer-Ŝeba ĝis la monto de Efraim, kaj revenigis ilin al la Eternulo, Dio de iliaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Li starigis juĝistojn en la lando, en ĉiuj fortikigitaj urboj de Judujo, en ĉiu urbo aparte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'Kaj li diris al la juĝistoj: Rigardu, kion vi faras, ĉar ne por homo vi juĝas, sed por la Eternulo; Li estos kun vi en la aferoj de juĝado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Estu do en vi timo antaŭ la Eternulo, agadu singarde; ĉar ĉe la Eternulo, nia Dio, ne ekzistas maljusteco, nek personfavorado, nek akceptado de subaĉetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Ankaŭ en Jerusalem Jehoŝafat starigis virojn el la Levidoj, pastroj, kaj ĉefoj de patrodomoj de Izrael, por juĝado antaŭ la Eternulo kaj por juĝaj disputoj. Kaj ili revenis al Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Kaj li ordonis al ili jene: Tiele agu en timo antaŭ la Eternulo, en fideleco kaj kun pura koro:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'en ĉiu juĝa disputo, kiu venos antaŭ vin de viaj fratoj, kiuj loĝas en siaj urboj, ĉu pri afero de sango, ĉu pri religia preskribo, ordono, leĝoj, aŭ decidoj, klarigu al ili, por ke ili ne kulpiĝu antaŭ la Eternulo kaj por ke ne falu kolero sur vin kaj sur viajn fratojn; tiel agu, tiam vi ne fariĝos kulpaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Kaj jen la ĉefpastro Amarja estas super vi en ĉiu afero koncernanta la Eternulon, kaj Zebadja, filo de Iŝmael, la princo el la domo de Jehuda, en ĉiu afero koncernanta la reĝon, kaj la Levidojn vi havas antaŭ vi kiel oficistojn. Tenu vin forte kaj agadu, kaj la Eternulo estos kun la bonulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Post tio la Moabidoj kaj la Amonidoj, kaj kun ili ankaŭ najbaroj de la Amonidoj, iris milite kontraŭ Jehoŝafaton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Kaj oni venis kaj raportis al Jehoŝafat, dirante: Venis kontraŭ vin granda multo da homoj de trans la maro, el Sirio; kaj jen ili nun estas en Ĥacacon-Tamar, tio estas en En-Gedi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Jehoŝafat ektimis, kaj decidis turni sin al la Eternulo. Kaj li proklamis faston en la tuta Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Kaj kunvenis la Judoj, por peti la Eternulon; el ĉiuj urboj de Judujo ili venis, por peti la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Jehoŝafat stariĝis inter la komunumo de Judujo kaj Jerusalem en la domo de la Eternulo, antaŭ la nova korto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'Kaj li diris: Ho Eternulo, Dio de niaj patroj! Vi estas ja Dio en la ĉielo, kaj Vi regas super ĉiuj regnoj de la nacioj, en Via mano estas forto kaj potenco, kaj neniu povas kontraŭstari al Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Vi, nia Dio, forpelis ja la loĝantojn de ĉi tiu lando antaŭ Via popolo Izrael, kaj donis ĝin al la idaro de Abraham, Via amanto, por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'Kaj ili enloĝiĝis en ĝi, kaj konstruis por Vi en ĝi sanktejon al Via nomo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'Se venos sur nin malfeliĉo, glavo, puno, pesto, aŭ malsato, tiam ni stariĝos antaŭ ĉi tiu domo kaj antaŭ Vi, ĉar Via nomo estas en ĉi tiu domo, kaj ni vokos al Vi el nia mizero, kaj Vi aŭdos kaj helpos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Kaj nun jen la Amonidoj kaj la Moabidoj kaj la loĝantoj de la monto Seir, tra kies lando Vi ne permesis al la Izraelidoj iri, kiam ili iris el la lando Egipta, sed ili devis iri preter kaj ne ekstermi ilin-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'jen ili repagas al ni, venante, por elpeli nin el Via heredaĵo, kiun Vi donis al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Ho nia Dio, ĉu Vi ne juĝos ilin? ĉar ni ne havas forton kontraŭ ĉi tiu granda homamaso, kiu venis kontraŭ nin, kaj ni ne scias, kion ni devas fari, sed al Vi sin turnas niaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Kaj ĉiuj Judoj staris antaŭ la Eternulo, ankaŭ iliaj infanoj, edzinoj, kaj filoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Tiam sur Jaĥaziel, filo de Zeĥarja, filo de Benaja, filo de Jeiel, filo de Matanja, Levido el la idoj de Asaf, aperis la spirito de la Eternulo meze de la komunumo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'kaj li diris: Aŭskultu, ĉiuj Judoj kaj loĝantoj de Jerusalem kaj reĝo Jehoŝafat! Tiele diras al vi la Eternulo: Ne timu kaj ne sentu teruron antaŭ ĉi tiu granda homamaso, ĉar la milito estas ne kontraŭ vi, sed kontraŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Morgaŭ malsupreniru sur ilin: jen ili supreniras sur la altaĵon de Cic, kaj vi trovos ilin en la fino de la valo, antaŭ la dezerto Jeruel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Ne vi devas batali ĉi tiun fojon: stariĝu, staru, kaj rigardu la savon, kiun la Eternulo sendas al vi, ho Judujo kaj Jerusalem. Ne timu kaj ne sentu teruron: morgaŭ eliru kontraŭ ilin, kaj la Eternulo estos kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Tiam Jehoŝafat kliniĝis vizaĝaltere, kaj ĉiuj Judoj kaj loĝantoj de Jerusalem ĵetis sin antaŭ la Eternulo, por adorkliniĝi antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Kaj leviĝis la Levidoj el la Kehatidoj kaj el la Koraĥidoj, por ekkanti gloron al la Eternulo, Dio de Izrael, per laŭta voĉo alten.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Ili leviĝis frue matene kaj eliris al la dezerto de Tekoa; kaj kiam ili eliris, stariĝis Jehoŝafat, kaj diris: Aŭskultu min, ho Judoj kaj loĝantoj de Jerusalem! kredu je la Eternulo, via Dio, kaj havu fidon; kredu je Liaj profetoj, kaj vi havos sukceson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Kaj li konsiliĝis kun la popolo, kaj li starigis kantistojn al la Eternulo, ke ili glorkantu en sankta ornamo, irante antaŭ la armitoj, kaj parolu: Gloru la Eternulon, ĉar eterna estas Lia favorkoreco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Kaj en la tempo, kiam ili komencis ĝojkrii kaj glorkanti, la Eternulo starigis embuskon kontraŭ la Amonidoj, Moabidoj, kaj Seiranoj, kiuj venis kontraŭ Judujon, kaj ili estis batitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Kaj stariĝis la Amonidoj kaj Moabidoj kontraŭ la loĝantoj de la monto Seir, por pereigi kaj ekstermi; kaj kiam ili finis kun la loĝantoj de Seir, ili komencis ekstermi unu la alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Kiam la Judoj venis sur la observejon en la dezerto kaj turnis sin al la homamaso, ili ekvidis kadavrojn, kiuj falis sur la teron, kaj neniu saviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Kaj venis Jehoŝafat kaj lia popolo, por preni la militakiraĵon; kaj ili trovis ĉe ili multe da havaĵo, vestoj, kaj multekostaj objektoj, kaj prenis al si tiom, ke ili ne povis porti. Kaj dum tri tagoj ili forprenadis la militakiraĵon, ĉar estis tre multe da ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'En la kvara tago ili kolektiĝis en la Valo de Beno, ĉar tie ili benis la Eternulon; pro tio oni donis al tiu loko la nomon Valo de Beno ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Kaj ĉiuj Judoj kaj Jerusalemanoj, kun Jehoŝafat antaŭe, iris returne, por reiri kun ĝojo en Jerusalemon; ĉar la Eternulo donis al ili ĝojon pri iliaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'Kaj ili venis en Jerusalemon kun psalteroj, harpoj, kaj trumpetoj, al la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Kaj timo antaŭ Dio venis sur ĉiujn regnojn de la landoj, kiam ili aŭdis, ke la Eternulo militis kontraŭ la malamikoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Kaj trankviliĝis la regno de Jehoŝafat; kaj lia Dio donis al li trankvilecon ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Jehoŝafat reĝis super Judujo; la aĝon de tridek kvin jaroj li havis, kiam li fariĝis reĝo, kaj dudek kvin jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Azuba, filino de Ŝilĥi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Li iradis laŭ la vojo de sia patro Asa kaj ne deturniĝis de ĝi, agante tiel, kiel plaĉas al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Tamen la altaĵoj ne estis forigitaj, kaj la popolo ankoraŭ ne turnis forte sian koron al Dio de ĝiaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'La cetera historio de Jehoŝafat, la unua kaj la lasta, estas priskribita en la kroniko de Jehu, filo de Ĥanani, kiu estas enigita en la libron de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Poste Jehoŝafat, reĝo de Judujo, amikiĝis kun Aĥazja, reĝo de Izrael, kiu agadis malpie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Li kuniĝis kun li, por fari ŝipojn, irontajn en Tarŝiŝon. Kaj li konstruis ŝipojn en Ecjon-Geber.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Tiam Eliezer, filo de Dodava, el Mareŝa, eldiris profetaĵon pri Jehoŝafat jene: Pro tio, ke vi kuniĝis kun Aĥazja, la Eternulo disbatis viajn aferojn. Kaj la ŝipoj rompiĝis kaj ne povis iri en Tarŝiŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Jehoŝafat ekdormis kun siaj patroj, kaj oni enterigis lin kun liaj patroj en la urbo de David. Kaj anstataŭ li ekreĝis lia filo Jehoram.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Li havis fratojn, filojn de Jehoŝafat: Azarja, Jeĥiel, Zeĥarja, Azarjahu, Miĥael, kaj Ŝefatja. Ĉiuj ili estis filoj de Jehoŝafat, reĝo de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Ilia patro donis al ili multe da donacoj, arĝenton, oron, multekostaĵojn, kaj fortikigitajn urbojn en Judujo; sed la regnon li donis al Jehoram, ĉar li estis la unuenaskito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Kiam Jehoram estriĝis super la regno de sia patro kaj fortiĝis, li mortigis per glavo ĉiujn siajn fratojn kaj ankaŭ kelkajn el la eminentuloj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'La aĝon de tridek du jaroj havis Jehoram, kiam li fariĝis reĝo, kaj ok jarojn li reĝis en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Li iradis laŭ la vojo de la reĝoj de Izrael, kiel faris la domo de Aĥab, ĉar filino de Aĥab estis lia edzino, kaj li faradis malbonon antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Tamen la Eternulo ne volis pereigi la domon de David, pro la interligo, kiun Li faris kun David, kaj ĉar Li promesis doni lumilon al li kaj al liaj filoj por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'En lia tempo la Edomidoj defalis de Judujo kaj starigis super si reĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Tiam Jehoram kun siaj militestroj kaj kun ĉiuj siaj ĉaroj eliris; kaj li leviĝis nokte, kaj venkobatis la Edomidojn, kiuj estis ĉirkaŭ li, kaj la ĉarestrojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Tamen la Edomidoj restis defalintaj de Judujo ĝis la nuna tago. En la sama tempo ankaŭ Libna defalis de li, ĉar li forlasis la Eternulon, Dion de liaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Li ankaŭ aranĝis altaĵojn sur la montoj de Judujo, li malĉastigis la loĝantojn de Jerusalem kaj delogis Judujon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Kaj venis al li letero de la profeto Elija, en kiu estis skribite: Tiele diras la Eternulo, Dio de via patro David: Pro tio, ke vi ne iradis laŭ la vojoj de via patro Jehoŝafat, kaj laŭ la vojoj de Asa, reĝo de Judujo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'sed vi iradis laŭ la vojo de la reĝoj de Izrael, kaj malĉastigis Judujon kaj la loĝantojn de Jerusalem, kiel malĉastigis la domo de Aĥab, kaj eĉ viajn fratojn, la domon de via patro, kiuj estis pli bonaj ol vi, vi mortigis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'pro tio jen la Eternulo frapos per granda plago vian popolon, viajn filojn, viajn edzinojn, kaj vian tutan havaĵon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'kaj vi mem havos grandan malsanon, malsanon en viaj internaĵoj tian, ke pro la malsano elfalados viaj internaĵoj ĉiutage.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Kaj la Eternulo ekscitis kontraŭ Jehoram la spiriton de la Filiŝtoj, kaj de la Araboj, kiuj loĝis apude de la Etiopoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'kaj ili iris kontraŭ Judujon kaj penetris en ĝin, kaj forprenis la tutan havaĵon, kiu troviĝis en la reĝa domo, ankaŭ liajn filojn kaj liajn edzinojn; kaj restis ĉe li neniu filo, krom lia plej juna filo Jehoaĥaz.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Kaj post ĉio ĉi tio la Eternulo frapis liajn internaĵojn per nesanigebla malsano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Kaj tio daŭris de tago al tago; kaj kiam finiĝis du jaroj, liaj internaĵoj eliris de li kune kun lia malsano, kaj li mortis en grandaj doloroj; kaj lia popolo ne faris al li brulon, kiel la bruloj por liaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'La aĝon de tridek du jaroj li havis, kiam li fariĝis reĝo, kaj ok jarojn li reĝis en Jerusalem; li foriris ne estimata, kaj oni enterigis lin en la urbo de David, sed ne en la tomboj de la reĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'La loĝantoj de Jerusalem ekreĝigis lian plej junan filon Aĥazja anstataŭ li, ĉar ĉiujn pli aĝajn mortigis la taĉmento, kiu venis kun la Araboj en la tendaron. Kaj ekreĝis Aĥazja, filo de Jehoram, reĝo de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'La aĝon de kvardek du jaroj havis Aĥazja, kiam li fariĝis reĝo, kaj unu jaron li reĝis en Jerusalem. La nomo de lia patrino estis Atalja, filino de Omri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Li ankaŭ iradis laŭ la vojoj de la domo de Aĥab, ĉar lia patrino estis lia konsilantino por malbonagi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Li faradis malbonon antaŭ la Eternulo, kiel la domo de Aĥab, ĉar ili estis liaj konsilantoj post la morto de lia patro, por pereigi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Ankaŭ ilian konsilon li sekvis, kaj iris kun Jehoram, filo de Aĥab, milite kontraŭ Ĥazaelon, reĝon de Sirio, al Ramot en Gilead. Kaj la Sirianoj vundis Jehoramon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Kaj li revenis, por kuraci sin en Jizreel de la vundoj, kiujn oni faris al li en Ramot, kiam li batalis kontraŭ Ĥazael, reĝo de Sirio. Kaj Azarja, filo de Jehoram, reĝo de Judujo, iris por viziti Jehoramon, filon de Aĥab, en Jizreel, ĉar ĉi tiu estis malsana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Sed de Dio estis destinita pereo por Aĥazja per tio, ke li venis al Jehoram: post sia veno li eliris kun Jehoram kontraŭ Jehun, filon de Nimŝi, kiun la Eternulo sanktoleis, por ekstermi la domon de Aĥab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Kiam Jehu faris juĝon sur la domo de Aĥab, li trovis la eminentulojn de Judujo kaj la filojn de la fratoj de Aĥazja, kiuj servis al Aĥazja, kaj li mortigis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Kaj li serĉis Aĥazjan, kaj oni kaptis lin, kiam li estis kaŝita en Samario; kaj oni venigis lin al Jehu kaj mortigis lin kaj enterigis lin, ĉar oni diris: Li estas filo de Jehoŝafat, kiu strebis al la Eternulo per sia tuta koro. Kaj el la domo de Aĥazja restis neniu, kiu povus reĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Kiam Atalja, la patrino de Aĥazja, vidis, ke ŝia filo mortis, ŝi leviĝis kaj ekstermis la tutan reĝan idaron de la domo de Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Sed Jehoŝabeat, filino de la reĝo, prenis Joaŝon, filon de Aĥazja, kaj ŝtele elkondukis lin el inter la mortigataj filoj de la reĝo kaj lokis lin kaj lian nutristinon en la ĉambro de litoj; kaj kaŝis lin Jehoŝabeat, filino de la reĝo Jehoram kaj edzino de la pastro Jehojada (ĉar ŝi estis fratino de Aĥazja), for de Atalja, kaj ĉi tiu lin ne mortigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Kaj li restis kaŝita ĉe ili en la domo de Dio dum ses jaroj; kaj Atalja reĝis en la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Sed en la sepa jaro kuraĝis Jehojada kaj prenis al si en interligon la centestrojn Azarja, filo de Jeroĥam, Iŝmael, filo de Jehoĥanan, Azarja, filo de Obed, Maaseja, filo de Adaja, kaj Eliŝafat, filo de Ziĥri;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'kaj ili rondiris en Judujo kaj kolektis la Levidojn el ĉiuj urboj de Judujo kaj la ĉefojn de patrodomoj en Izrael kaj venis en Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Kaj la tuta anaro faris en la domo de Dio interligon kun la reĝo. Kaj Jehojada diris al ili: Jen la filo de la reĝo devas reĝi, kiel diris la Eternulo pri la filoj de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Jenon vi devas fari: tiu triono de vi, kiu venas en sabato, el la pastroj kaj el la Levidoj, estu pordegistoj ĉe la sojloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'triono en la reĝa domo, kaj triono ĉe la Pordego de la Fundamento; la tuta popolo estu sur la kortoj de la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Neniu eniru en la domon de la Eternulo, krom la pastroj kaj la servantoj el la Levidoj; ĉi tiuj povas eniri, ĉar ili estas sanktigitaj; sed la tuta popolo faru gardon por la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Kaj la Levidoj ĉirkaŭu la reĝon ĉiuflanke, ĉiu kun sia batalilo en la mano; kaj ĉiun, kiu eniros en la domon, oni mortigu. Kaj estu apud la reĝo, kiam li eniros aŭ eliros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'La Levidoj kaj ĉiuj Judoj faris ĉion, kion ordonis la pastro Jehojada; kaj ĉiu prenis siajn homojn, la sabate venantajn kun la sabate forirantaj, ĉar la pastro Jehojada ne forliberigis la laŭvicajn grupojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Kaj la pastro Jehojada disdonis al la centestroj la lancojn, ŝildojn, kaj manŝildojn de la reĝo David, kiuj estis en la domo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Kaj li starigis la tutan popolon, ĉiun kun lia batalilo en la mano, de la dekstra flanko de la domo ĝis la maldekstra flanko de la domo, ĉe la altaro kaj ĉe la domo, ĉirkaŭe de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Kaj oni elkondukis la reĝidon, metis sur lin la kronon kaj la ateston, kaj proklamis lin reĝo; Jehojada kaj liaj filoj sanktoleis lin, kaj diris: Vivu la reĝo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Kiam Atalja aŭdis la bruon de la popolo, kuranta kaj gloranta la reĝon, ŝi iris al la popolo en la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Kaj ŝi ekvidis, ke jen la reĝo staras ĉe la kolono apud la enirejo, kaj la eminentuloj kaj la trumpetistoj apud la reĝo, kaj la tuta popolo de la lando ĝojas, kaj oni trumpetas per trumpetoj, kaj la kantistoj staras kun la muzikaj instrumentoj kaj glorkantas. Tiam Atalja disŝiris siajn vestojn, kaj ekkriis: Konspiro, konspiro!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Tiam la pastro Jehojada elirigis la centestrojn, la estrojn de la militistaro, kaj diris al ili: Elkonduku ŝin ekster la vicojn; kaj kiu ŝin sekvos, tiun oni mortigu per glavo; ĉar la pastro diris: Ne mortigu ŝin en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Kaj oni liberigis por ŝi lokon, kaj ŝi iris tra la enirejo de la Pordego de Ĉevaloj al la reĝa domo, kaj tie oni ŝin mortigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Kaj Jehojada faris interligon inter li, la tuta popolo, kaj la reĝo, ke ili estu popolo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Kaj la tuta popolo iris en la domon de Baal kaj ĝin detruis; kaj liajn altarojn kaj bildojn ili disrompis, kaj Matanon, la pastron de Baal, ili mortigis antaŭ la altaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Kaj Jehojada komisiis la oficojn en la domo de la Eternulo al la pastroj Levidoj, kiujn destinis David por la domo de la Eternulo, por faradi bruloferojn al la Eternulo, kiel estas skribite en la instruo de Moseo, kun ĝojo kaj kantoj, laŭ la preskribo de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Kaj li starigis la pordegistojn ĉe la pordegoj de la domo de la Eternulo, por ke neniu povu eniri, kiu pro io estas malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Kaj li prenis la centestrojn kaj la potenculojn kaj la regantojn de la popolo kaj la tutan popolon de la lando, kaj li kondukis la reĝon el la domo de la Eternulo; kaj ili trairis tra la supra pordego en la reĝan domon, kaj ili sidigis la reĝon sur la regna trono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Kaj la tuta popolo de la lando ĝojis, kaj la urbo estis trankvila. Sed Ataljan oni mortigis per glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'La aĝon de sep jaroj havis Joaŝ, kiam li fariĝis reĝo, kaj kvardek jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Cibja, el Beer- Ŝeba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Joaŝ agadis bone antaŭ la Eternulo dum la tuta vivo de la pastro Jehojada.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Kaj Jehojada prenis por li du edzinojn, kaj li naskigis filojn kaj filinojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Post tio Joaŝ ekintencis renovigi la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Kaj li kunvokis la pastrojn kaj la Levidojn, kaj diris al ili: Iru en la urbojn de Judujo kaj kolektu de ĉiuj Izraelidoj monon por riparadi la domon de via Dio ĉiujare; kaj rapidu kun tiu afero. Sed la Levidoj ne rapidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Tiam la reĝo alvokis Jehojadan, ilian ĉefon, kaj diris al li: Kial vi ne postulas de la Levidoj, ke ili alportadu el Judujo kaj Jerusalem la imposton, kiun Moseo, la servanto de la Eternulo, kaj la komunumo de Izrael starigis por la tabernaklo de la interligo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Ĉar la malpia Atalja kaj ŝiaj filoj ruinigis la domon de Dio; kaj ĉion, kio estis sanktigita por la domo de la Eternulo, ili uzis por la Baaloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Kaj la reĝo ordonis, kaj oni faris unu keston kaj starigis ĝin ĉe la pordego de la domo de la Eternulo, ekstere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Kaj oni proklamis en Judujo kaj en Jerusalem, ke oni alportadu al la Eternulo la imposton, kiun Moseo, servanto de Dio, starigis por la Izraelidoj en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Kaj ekĝojis ĉiuj estroj kaj la tuta popolo, kaj ili alportis kaj ĵetis en la keston, ĝis ĝi pleniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Kaj ĉiufoje, kiam oni alportis la keston per la Levidoj en la reĝan oficejon, kaj oni vidis, ke estas multe da mono, venis skribisto de la reĝo kaj komisiito de la ĉefpastro, kaj ili malplenigis la keston, kaj poste oni reportis ĝin kaj restarigis sur ĝia loko. Tiel oni faradis ĉiutage, kaj oni kolektis multe da mono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Kaj la reĝo kaj Jehojada donadis ĝin al la farantoj de la laboroj en la domo de la Eternulo, kaj oni dungis ŝtonhakistojn kaj ĉarpentistojn, por renovigi la domon de la Eternulo, ankaŭ feraĵistojn kaj kupraĵistojn, por ripari la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Kaj la laboristoj laboris, kaj la afero antaŭeniris per iliaj manoj; kaj oni metis la domon de Dio en bonan staton, kaj oni ĝin fortikigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Kiam ili finis, ili alportis la restintan monon al la reĝo kaj al Jehojada; el tio oni faris vazojn por la domo de la Eternulo, vazojn por la servado kaj por la bruloferoj, kalikojn kaj aliajn vazojn orajn kaj arĝentajn. Kaj oni alportadis bruloferojn en la domo de la Eternulo konstante, dum la tuta vivo de Jehojada.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Jehojada maljuniĝis kaj atingis sufiĉan aĝon, kaj li mortis; la aĝon de cent tridek jaroj li havis, kiam li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'Kaj oni enterigis lin en la urbo de David, kun la reĝoj; ĉar li faradis bonon en Izrael, por Dio kaj por Lia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Post la morto de Jehojada venis la estroj de Judujo kaj kliniĝis antaŭ la reĝo; kaj li komencis obeadi ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Kaj ili forlasis la domon de la Eternulo, Dio de iliaj patroj, kaj ili servadis al sanktaj stangoj kaj al idoloj; kaj ekscitiĝis Lia kolero kontraŭ Judujo kaj kontraŭ Jerusalem pro ĉi tiu ilia kulpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Li sendis al ili profetojn, por revenigi ilin al la Eternulo; kaj ili admonis ilin, sed ĉi tiuj ne atentis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'La spirito de Dio venis sur Zeĥarjan, filon de la pastro Jehojada, kaj li stariĝis antaŭ la popolo, kaj diris al ili: Tiele diras Dio: Kial vi malobeas la ordonojn de la Eternulo? Vi ne havos sukceson, ĉar vi forlasis la Eternulon, kaj tial Li vin forlasis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Ili faris konspiron kontraŭ li, kaj ŝtonmortigis lin laŭ ordono de la reĝo sur la korto de la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Kaj la reĝo Joaŝ ne memoris la favorkoraĵon, kiun lia patro Jehojada faris al li, kaj li mortigis lian filon. Ĉi tiu, mortante, diris: La Eternulo vidu, kaj punu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Post paso de unu jaro eliris kontraŭ lin la militistaro de Sirio; kaj ili eniris en Judujon kaj Jerusalemon kaj ekstermis el la popolo ĉiujn estrojn de la popolo; kaj la tutan militakiraĵon ili sendis al la reĝo de Damasko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Kun nemulte da homoj venis la militistaro de Sirio; tamen la Eternulo transdonis en ilian manon la militistaron multe pli grandan, pro tio, ke ĉi tiuj forlasis la Eternulon, Dion de iliaj patroj. Kaj sur Joaŝ ili faris juĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Kiam ili foriris de li, lasinte lin en grava malsano, liaj servantoj faris konspiron kontraŭ li pro la sango de la filoj de Jehojada, la pastro, kaj ili mortigis lin sur lia lito, kaj li mortis. Kaj oni enterigis lin en la urbo de David, sed oni ne enterigis lin en la reĝaj tomboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'La konspirintoj kontraŭ li estis: Zabad, filo de la Amonidino Ŝimeat, kaj Jehozabad, filo de la Moabidino Ŝimrit.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Pri liaj filoj, pri la multo da mono, kiu estis kolektita sub li, kaj pri la riparado de la domo de Dio, estas skribite en la komentario en la libro de la reĝoj. Kaj anstataŭ li ekreĝis lia filo Amacja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'La aĝon de dudek kvin jaroj havis Amacja, kiam li fariĝis reĝo, kaj dudek naŭ jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Jehoadan, el Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Li agadis bone antaŭ la Eternulo, tamen ne el plena koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Kiam lia reĝado fortikiĝis, li mortigis siajn servantojn, kiuj mortigis la reĝon, lian patron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Sed iliajn filojn li ne mortigis, ĉar tiel estas skribite en la instruo, en la libro de Moseo, kie la Eternulo ordonis, dirante: Ne devas morti patroj pro la infanoj, kaj infanoj ne devas morti pro la patroj, sed ĉiu devas morti pro sia peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Amacja kunvenigis la Judojn, kaj starigis ilin laŭ patrodomoj, laŭ milestroj kaj centestroj, ĉiujn Jehudaidojn kaj Benjamenidojn; kaj li kalkulis ilin, la havantajn la aĝon de dudek jaroj kaj pli, kaj li trovis, ke ili prezentas la nombron de tricent mil viroj elektitaj, povantaj iri en militon kaj teni lancon kaj ŝildon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Kaj li dungis de Izrael cent mil bravajn militistojn pro cent kikaroj da arĝento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Sed homo de Dio venis al li, kaj diris: Ho reĝo, ne iru kun vi la militistaro de Izrael, ĉar la Eternulo ne estas kun Izrael, kun ĉiuj idoj de Efraim;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'sed iru vi sola, agu kuraĝe en la milito; alie Dio faligos vin antaŭ la malamiko, ĉar Dio havas la forton, por helpi kaj por faligi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Kaj Amacja diris al la homo de Dio: Kion do oni faru kun la cent kikaroj, kiujn mi donis al la militistoj de Izrael? La homo de Dio respondis: La Eternulo povas doni al vi pli ol tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Tiam Amacja apartigis la militistojn, kiuj venis al li el la lando de Efraim, ke ili iru al sia loko. Kaj forte ekflamis ilia kolero kontraŭ Judujo, kaj ili reiris al sia loko kun kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Kaj Amacja havis la kuraĝon kaj kondukis sian popolon kaj iris en la Valon de Salo; kaj li mortigis el la Seiranoj dek mil;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'kaj dek mil vivantajn la Judoj prenis en kaptitecon kaj kondukis ilin sur la supron de roko, kaj ĵetis ilin malsupren de la supro de la roko tiel, ke ĉiuj dishakiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Sed la militistoj, kiujn Amacja sendis returne, por ke ili ne iru kun li en la militon, kuris en la urbojn de Judujo, de Samario ĝis Bet-Ĥoron, kaj mortigis tie tri mil homojn, kaj kaptis multe da rabakiraĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Kiam Amacja revenis post la venkobato de la Edomidoj, li alportis la diojn de la Seiranoj kaj starigis ilin al si kiel diojn, kaj antaŭ ili li adorkliniĝis kaj al ili li incensis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Tiam ekflamis la kolero de la Eternulo kontraŭ Amacja, kaj Li sendis al li profeton, kaj ĉi tiu diris al li: Kial vi turnas vin al la dioj de la popolo, kiuj ne savis sian popolon kontraŭ via mano?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Kaj dum li estis parolanta al li, la reĝo diris al li: Ĉu oni faris vin konsilisto de la reĝo? ĉesu, ĉar alie oni vin mortigos. Tiam la profeto ĉesis, kaj diris: Mi scias, ke Dio decidis pereigi vin; ĉar vi tion faris kaj vi ne aŭskultis mian konsilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Amacja, reĝo de Judujo, konsiliĝis, kaj sendis al Joaŝ, filo de Jehoaĥaz, filo de Jehu, reĝo de Izrael, por diri: Venu, ni komparu niajn fortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Tiam Joaŝ, reĝo de Izrael, sendis al Amacja, reĝo de Judujo, por diri: La prunelo sur Lebanon sendis al la cedro sur Lebanon, por diri: Donu vian filinon al mia filo kiel edzinon. Sed preteriris sovaĝa besto de Lebanon kaj dispremis per la piedoj la prunelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Vi diras al vi: Jen mi venkobatis la Edomidojn; kaj via koro fieriĝis kaj serĉas gloron. Sidu nun hejme; kial vi volas entrepreni aferon malfeliĉan, ke vi falu kaj kun vi ankaŭ Judujo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Sed Amacja ne obeis; ĉar tio estis de Dio, por transdoni ilin en manojn pro tio, ke ili turnis sin al la dioj de Edom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Kaj eliris Joaŝ, reĝo de Izrael, kaj ili komparis siajn fortojn, li kaj Amacja, reĝo de Judujo, en Bet-Ŝemeŝ, kiu estas en Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Kaj la Judoj estis venkobatitaj de la Izraelidoj, kaj ili diskuris ĉiu al sia tendo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Kaj Amacjan, reĝon de Judujo, filon de Joaŝ, filo de Jehoaĥaz, kaptis Joaŝ, reĝo de Izrael, en Bet-Ŝemeŝ, kaj venigis lin en Jerusalemon; kaj li detruis la muregon de Jerusalem, de la Pordego de Efraim ĝis la Pordego Angula, sur la spaco de kvarcent ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Kaj li prenis la tutan oron kaj arĝenton, kaj ĉiujn vazojn, kiuj troviĝis en la domo de Dio ĉe Obed-Edom, kaj la trezorojn de la reĝa domo, kaj ankaŭ garantiulojn, kaj li reiris en Samarion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Kaj Amacja, filo de Joaŝ, reĝo de Judujo, vivis post la morto de Joaŝ, filo de Jehoaĥaz, reĝo de Izrael, ankoraŭ dek kvin jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'La cetera historio de Amacja, la unua kaj la lasta, estas priskribita en la libro de la reĝoj de Judujo kaj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'De la tempo, kiam Amacja deturnis sin de la Eternulo, oni faris kontraŭ li konspiron en Jerusalem, kaj li forkuris en Laĥiŝon. Sed oni sendis post li en Laĥiŝon, kaj tie oni lin mortigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Kaj oni venigis lin sur ĉevaloj kaj enterigis lin kun liaj patroj en la urbo de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Kaj la tuta Juda popolo prenis Uzijan, kiu havis la aĝon de dek ses jaroj, kaj faris lin reĝo anstataŭ lia patro Amacja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Li prikonstruis Elaton kaj revenigis ĝin al Judujo, post kiam la reĝo ekdormis kun siaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'La aĝon de dek ses jaroj havis Uzija, kiam li fariĝis reĝo, kaj kvindek du jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Jeĥolja, el Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Li agadis bone antaŭ la Eternulo, tiel same, kiel agadis lia patro Amacja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Li turnadis sin al Dio en la tempo de Zeĥarja, la kompetentulo en Diaj vizioj; kaj en tiu tempo, kiam li turnadis sin al la Eternulo, Dio donadis al li sukceson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Li eliris kaj militis kontraŭ la Filiŝtoj; li detruis la muregon de Gat, la muregon de Jabne, kaj la muregon de Aŝdod; kaj li konstruis urbojn en la regiono de Aŝdod kaj en Filiŝtujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Kaj Dio helpis al li kontraŭ la Filiŝtoj, kaj kontraŭ la Araboj, kiuj loĝis en Gur-Baal, kaj kontraŭ la Meunoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Kaj la Amonidoj donis al Uzija donacojn, kaj lia nomo fariĝis fama ĝis la limo de Egiptujo, ĉar li estis tre forta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Uzija konstruis turojn en Jerusalem super la Pordego Angula, super la Pordego de la Valo, kaj super la angulo, kaj fortikigis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Li konstruis ankaŭ turojn en la dezerto kaj elhakis multe da putoj, ĉar li havis multe da brutoj sur la malaltaĵo kaj sur la ebenaĵo; li havis ankaŭ terkultivistojn kaj vinberistojn sur la montoj kaj kreskotaŭgaj lokoj, ĉar li estis amanto de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Uzija havis militistaron, kapablan por bataloj, elirantan en militon per taĉmentoj, laŭ la nombro, kalkulita de la skribisto Jeiel kaj de la inspektisto Maaseja, sub kontrolo de Ĥananja, el la altranguloj de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'La tuta nombro de la ĉefoj de patrodomoj, el la bravaj militistoj, estis du mil sescent;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'kaj sub ilia regado estis militistaro el tricent sep mil kvincent povantaj fari militon kun batalkapableco, por helpi al la reĝo kontraŭ la malamiko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Kaj Uzija pretigis por ili, por la tuta militistaro, ŝildojn, lancojn, kaskojn, kirasojn, pafarkojn, kaj ŝtonojn por ŝtonĵetiloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Kaj li faris en Jerusalem maŝinojn, elpensitajn de specialistoj, por ke ili troviĝu sur la turoj kaj sur la anguloj, por ĵetadi sagojn kaj grandajn ŝtonojn. Kaj lia nomo fariĝis fama malproksime, ĉar li mirinde aranĝis al si helpon, ĝis li fariĝis potenca.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Sed kiam li fariĝis potenca, lia koro fieriĝis tiel, ke li malboniĝis. Li krimis kontraŭ la Eternulo, lia Dio, kaj li eniris en la templon de la Eternulo, por incensi sur la altaro de incensado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Kaj eniris post li la pastro Azarja, kaj kun li okdek pastroj de la Eternulo, kuraĝuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'kaj ili stariĝis kontraŭ la reĝo Uzija, kaj diris al li: Ne vi, Uzija, devas incensi al la Eternulo, sed incensi devas la pastroj, idoj de Aaron, sanktigitaj; eliru el la sanktejo, ĉar vi faris krimon, kaj tio ne estos por vi honora antaŭ Dio, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Tiam Uzija ekkoleris, kaj en la mano li tenis incensilon, por incensi. Sed kiam li ekkoleris kontraŭ la pastroj, lepro aperis sur lia frunto, antaŭ la pastroj en la domo de la Eternulo, apud la altaro de incensado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Kiam sin turnis al li la ĉefpastro Azarja kaj ĉiuj pastroj, ili ekvidis, ke li havas lepron sur la frunto. Kaj ili rapide elkondukis lin de tie, kaj ankaŭ li mem rapidis eliri, ĉar la Eternulo lin frapis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Kaj la reĝo Uzija restis lepra ĝis la tago de sia morto, kaj li loĝis en izolita domo de leprulo; ĉar li estis forigita for de la domo de la Eternulo. Kaj lia filo Jotam estis ĉefo de la reĝa domo kaj regis la popolon de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'La ceteran historion de Uzija, la unuan kaj la lastan, priskribis la profeto Jesaja, filo de Amoc.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Kaj Uzija ekdormis kun siaj patroj, kaj oni enterigis lin kun liaj patroj sur la kampo de la tomboj de la reĝoj; ĉar oni diris: Li estas leprulo. Kaj anstataŭ li ekreĝis lia filo Jotam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'La aĝon de dudek kvin jaroj havis Jotam, kiam li fariĝis reĝo, kaj dek ses jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Jeruŝa, filino de Cadok.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Li agadis bone antaŭ la Eternulo, tiel same, kiel agadis lia patro Uzija; sed li ne eniris en la templon de la Eternulo; kaj la popolo ĉiam ankoraŭ pekadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Li konstruis la supran pordegon de la domo de la Eternulo, kaj ĉe la muro de Ofel li multe konstruis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Li konstruis ankaŭ urbojn sur la monto de Jehuda, kaj en la arbaroj li konstruis kastelojn kaj turojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Li militis kontraŭ la reĝo de la Amonidoj kaj venkis ilin; kaj la Amonidoj donis al li en tiu jaro cent kikarojn da arĝento, dek mil kor�ojn da tritiko, kaj dek mil da hordeo. Tion saman donis al li la Amonidoj ankaŭ en la dua jaro kaj en la tria.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Jotam fariĝis potenca, ĉar li bone aranĝis siajn vojojn antaŭ la Eternulo, sia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'La cetera historio de Jotam, ĉiuj liaj militoj kaj liaj vojoj, estas priskribitaj en la libro de la reĝoj de Izrael kaj Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'La aĝon de dudek kvin jaroj li havis, kiam li fariĝis reĝo, kaj dek ses jarojn li reĝis en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Kaj Jotam ekdormis kun siaj patroj, kaj oni enterigis lin en la urbo de David. Kaj anstataŭ li ekreĝis lia filo Aĥaz.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'La aĝon de dudek jaroj havis Aĥaz, kiam li fariĝis reĝo, kaj dek ses jarojn li reĝis en Jerusalem; kaj li ne agadis bone antaŭ la Eternulo, kiel lia patro David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'Li iradis laŭ la vojoj de la reĝoj de Izrael, kaj li eĉ faris fanditajn statuojn de Baaloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'li incensadis en la valo de la filo de Hinom, li bruligis siajn filojn per fajro, simile al la abomenindaĵoj de la nacioj, kiujn la Eternulo forpelis de antaŭ la Izraelidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'li oferadis kaj incensadis sur la altaĵoj kaj sur la montetoj kaj sub ĉiu verda arbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Kaj la Eternulo, lia Dio, transdonis lin en la manon de la reĝo de Sirio, kaj ili venkobatis lin, prenis de li multe da kaptitoj kaj forkondukis en Damaskon. Ankaŭ en la manon de la reĝo de Izrael li estis transdonita, kaj ĉi tiu faris al li grandan baton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Pekaĥ, filo de Remalja, mortigis el la Judoj cent dudek mil en unu tago, kiuj ĉiuj estis homoj bravaj-pro tio, ke ili forlasis la Eternulon, Dion de iliaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Kaj Ziĥri, fortulo el la Efraimidoj, mortigis Maasejan, filon de la reĝo, kaj Azrikamon, la palacestron, kaj Elkanan, la duan post la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Kaj la Izraelidoj forkaptis de siaj fratoj ducent mil virinojn, filojn, kaj filinojn, kaj ankaŭ multe da rabaĵo ili prenis de ili kaj venigis la rabaĵon en Samarion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Tie estis profeto de la Eternulo kun la nomo Oded. Li eliris antaŭ la militistaron, kiu venis al Samario, kaj diris al ili: Jen pro la kolero de la Eternulo, Dio de viaj patroj, kontraŭ la Judoj, Li transdonis ilin en viajn manojn, kaj vi mortigis ilin kun tia furiozo, ke tio atingis la ĉielon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'Nun la loĝantojn de Judujo kaj Jerusalem vi intencas subigi al vi kiel sklavojn kaj sklavinojn. Sed per tio vi fariĝos ja kulpaj antaŭ la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Aŭskultu do min, kaj redonu la kaptitojn, kiujn vi prenis el viaj fratoj, ĉar ekscitiĝis kontraŭ vi la flamo de kolero de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Tiam leviĝis kelkaj el la ĉefoj de la Efraimidoj, Azarja, filo de Jehoĥanan, Bereĥja, filo de Meŝilemot, Jeĥizkija, filo de Ŝalum, kaj Amasa, filo de Ĥadlaj, kontraŭ tiuj, kiuj venis el la militistaro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'kaj diris al ili: Ne konduku ĉi tien la kaptitojn, ĉar novan nian kulpon antaŭ la Eternulo vi intencas aldoni al niaj pekoj kaj kulpoj; granda estas nia kulpo kaj la flama kolero kontraŭ Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Tiam la armitoj forlasis la kaptitojn kaj la rabitaĵon antaŭ la estroj kaj la tuta komunumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Kaj leviĝis la viroj, menciitaj laŭ iliaj nomoj, prenis la kaptitojn, kaj ĉiujn el iliaj nuduloj ili vestis per parto de la rabitaĵo, vestis ilin, donis al ili ŝuojn, donis al ili manĝi kaj trinki, ŝmiris ilin per oleo, sidigis sur azenoj ĉiujn senfortulojn, forkondukis ilin en Jeriĥon, la urbon de Palmoj, al iliaj fratoj; kaj ili mem revenis en Samarion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'En tiu tempo la reĝo Aĥaz sendis al la reĝoj de Asirio, ke ili helpu al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Ankaŭ la Edomidoj venis, venkobatis la Judojn, kaj forkaptis kaptitojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Ankaŭ la Filiŝtoj invadis la urbojn de la malaltaĵo kaj de la sudo de Judujo, kaj venkoprenis la urbojn Bet-Ŝemeŝ, Ajalon, Gederot, Soĥo kun ĝiaj filinurboj, Timna kun ĝiaj filinurboj, kaj Gimzo kun ĝiaj filinurboj, kaj enloĝiĝis tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Ĉar la Eternulo humiligis Judujon pro Aĥaz, reĝo de Izrael, kiu malĉastigis Judujon kaj krimis antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Kaj venis kontraŭ lin Tiglat-Pileser, reĝo de Asirio, kaj premis lin, anstataŭ subteni lin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'ĉar Aĥaz prirabis la domon de la Eternulo kaj la reĝan domon kaj la eminentulojn, kaj donis al la reĝo de Asirio, tamen tio ne helpis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'En la tempo de sia mizero li plue krimis kontraŭ la Eternulo, li, la reĝo Aĥaz.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Kaj li alportadis oferojn al la dioj de la Damaskanoj, kiuj venkobatis lin, kaj li diris: La dioj de la reĝoj de Sirio helpas al ili; tial mi oferados al ili, kaj ili helpos al mi. Sed ili kaŭzis falon al li kaj al la tuta Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Kaj Aĥaz kolektis ĉiujn vazojn de la domo de Dio kaj disbatis la vazojn de la domo de Dio, kaj li ŝlosis la pordojn de la domo de la Eternulo, kaj faris al si altarojn en ĉiuj anguloj de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Kaj en ĉiuj urboj de Judujo li faris altaĵojn, por incensi al aliaj dioj, kaj li kolerigis la Eternulon, Dion de liaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Lia cetera historio kaj lia tuta konduto, la antaŭa kaj la lasta, estas priskribitaj en la libro de la reĝoj de Judujo kaj Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Kaj Aĥaz ekdormis kun sian patroj, kaj oni enterigis lin en la urbo, en Jerusalem; ĉar oni ne metis lin en la tombojn de la reĝoj de Izrael. Kaj anstataŭ li ekreĝis lia filoj Ĥizkija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Ĥizkija fariĝis reĝo, havante la aĝon de dudek kvin jaroj, kaj dudek naŭ jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Abija, filino de Zeĥarja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Li agadis bone antaŭ la Eternulo, tiel same, kiel agadis lia patro David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'En la unua jaro de sia reĝado, en la unua monato, li malŝlosis la pordojn de la domo de la Eternulo kaj riparis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Kaj li venigis la pastrojn kaj la Levidojn, kolektis ilin sur la placo orienta,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'kaj diris al ili: Aŭskultu min, ho Levidoj! nun vi sanktigu vin, kaj sanktigu la domon de la Eternulo, Dio de viaj patroj, kaj elĵetu la malpuraĵon el la sanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Ĉar niaj patroj krimis, agadis malbone antaŭ la Eternulo, nia Dio, forlasis Lin, forturnis sian vizaĝon de la loĝejo de la Eternulo, kaj turnis al ĝi sian dorson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Ili ankaŭ ŝlosis la pordojn de la portiko, estingis la lucernojn, incensojn ili ne incensis, kaj bruloferojn ili ne faris en la sanktejo al Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Kaj ekkoleris la Eternulo kontraŭ Judujo kaj Jerusalem; kaj Li elmetis ilin al teruro, ruinigo, kaj mokado, kiel vi vidas per viaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Kaj jen niaj patroj falis de glavo, kaj niaj filoj, filinoj, kaj edzinoj estas pro tio en kaptiteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Nun mi intencas fari interligon kun la Eternulo, Dio de Izrael, por ke Li forigu de ni la flamon de Sia kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Miaj infanoj, nun ne estu malzorgaj, ĉar vin elektis la Eternulo, ke vi staru antaŭ Li, ke vi servu al Li, kaj ke vi estu por Li servantoj kaj incensantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Tiam leviĝis la Levidoj: Maĥat, filo de Amasaj, Joel, filo de Azarja, el la Kehatidoj; kaj el la Merariidoj: Kiŝ, filo de Abdi, Azarja, filo de Jehalelel; kaj el la Gerŝonidoj: Joaĥ, filo de Zima, kaj Eden, filo de Joaĥ;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'kaj el la idoj de Elicafan: Ŝimri kaj Jeiel; kaj el la idoj de Asaf: Zeĥarja kaj Matanja;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'kaj el la idoj de Heman: Jeĥiel kaj Ŝimei; kaj el la idoj de Jedutun: Ŝemaja kaj Uziel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Kaj ili kolektis siajn fratojn kaj sanktigis sin; kaj ili eniris, laŭ la ordono de la reĝo, konforme al la vortoj de la Eternulo, por purigi la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Kaj la pastroj eniris en la internon de la domo de la Eternulo, por purigi; kaj ĉion malpuran, kion ili trovis en la templo de la Eternulo, ili elportis sur la korton de la domo de la Eternulo; kaj tion prenis la Levidoj, por elporti eksteren, al la torento Kidron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Ili komencis la sanktigadon en la unua tago de la unua monato, kaj en la oka tago de la monato ili eniris en la portikon de la Eternulo; ili sanktigis la domon de la Eternulo dum ok tagoj, kaj en la dek-sesa tago de la unua monato ili finis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Kaj ili eniris internen al la reĝo Ĥizkija, kaj diris: Ni purigis la tutan domon de la Eternulo, kaj la altaron de bruloferoj kaj ĉiujn ĝiajn vazojn, kaj la tablon de la panoj de propono kaj ĉiujn ĝiajn vazojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'kaj ĉiujn vazojn, kiujn la reĝo Aĥaz dum sia reĝado malpurigis per siaj krimoj, ni pretigis kaj sanktigis, kaj jen ili estas antaŭ la altaro de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'La reĝo Ĥizkija leviĝis frue matene, kunvenigis la estrojn de la urbo, kaj iris en la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Kaj ili alkondukis sep bovojn, sep virŝafojn, sep ŝafidojn, kaj sep kaprojn, kiel pekoferon pro la regno, pro la sanktejo, kaj pro Judujo; kaj li ordonis al la Aaronidoj, la pastroj, fari bruloferon sur la altaro de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Kaj oni buĉis la bovojn, kaj la pastroj prenis la sangon kaj aspergis la altaron; kaj oni buĉis la virŝafojn kaj aspergis per la sango la altaron; kaj oni buĉis la ŝafidojn kaj aspergis per la sango la altaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Kaj oni alkondukis la propekajn kaprojn antaŭ la reĝon kaj la komunumon, kaj ili metis siajn manojn sur ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'Kaj la pastroj ilin buĉis, kaj senpekigis per ilia sango la altaron, por pekliberigi la tutan Izraelon; ĉar pro la tuta Izrael, diris la reĝo, estas la brulofero kaj la pekofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Kaj li starigis la Levidojn en la domo de la Eternulo kun cimbaloj, psalteroj, kaj harpoj, laŭ la preskribo de David, de Gad, la viziisto de la reĝo, kaj de la profeto Natan; ĉar de la Eternulo estis tiu preskribo per Liaj profetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Kaj stariĝis la Levidoj kun la instrumentoj de David, kaj la pastroj kun la trumpetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Kaj Ĥizkija ordonis, ke oni faru la bruloferon sur la altaro. Kaj en la momento, kiam komenciĝis la brulofero, komenciĝis la kantado al la Eternulo, akompanata de trumpetoj kaj de instrumentoj de David, reĝo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Kaj la tuta popolo adorkliniĝis, kaj la kantado de la kantistoj kaj la trumpetado de la trumpetistoj daŭris ĝis la fino de la brulofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Kiam la brulofero estis finita, la reĝo, kaj ĉiuj, kiuj troviĝis kun li, ekgenuis kaj adorkliniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Kaj la reĝo Ĥizkija kaj la estroj diris al la Levidoj, ke ili gloru la Eternulon per la vortoj de David kaj de la viziisto Asaf; kaj ili glorkantis kun ĝojo, fleksis sin, kaj adorkliniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Kaj Ĥizkija diris plue: Nun vi konsekris vin al la Eternulo; aliru kaj konduku buĉoferojn kaj dankoferojn al la domo de la Eternulo. Kaj la komunumo alkondukis buĉoferojn kaj dankoferojn kaj memvolajn bruloferojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'La nombro de la bruloferoj, kiujn la komunumo alkondukis, estis: sepdek bovoj, cent virŝafoj, ducent ŝafidoj; ĉio ĉi tio estis bruloferoj al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Da konsekritaj estis: sescent bovoj kaj tri mil ŝafoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Sed la nombro de la pastroj estis tro malgranda, kaj ili ne povis senfeligi ĉiujn bruloferojn; tial helpis al ili iliaj fratoj, la Levidoj, ĝis la laboro estis finita kaj ĝis la pastroj sin sanktigis; ĉar la Levidoj estis pli fervoraj en la sinsanktigado, ol la pastroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Ankaŭ tre multe estis da bruloferoj, kun la sebo de pacoferoj kaj kun verŝoferoj por la bruloferoj. Tiamaniere estis preta la servado en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Kaj ĝojis Ĥizkija kaj la tuta popolo pri tio, kion Dio pretigis por la popolo; ĉar neatendita estis la afero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Ĥizkija sendis al la tuta Izrael kaj Jehuda, li skribis ankaŭ leterojn al Efraim kaj Manase, ke ili venu en la domon de la Eternulo, en Jerusalemon, por fari Paskon al la Eternulo, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Kaj la reĝo kaj liaj eminentuloj kaj la tuta komunumo en Jerusalem per konsiliĝo decidis fari la Paskon en la dua monato;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'ĉar ili ne povis fari ĝin en tiu tempo pro tio, ke la pastroj ne sanktigis sin en sufiĉa nombro kaj la popolo ne kolektiĝis en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'La afero plaĉis al la reĝo kaj al la tuta komunumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'Kaj ili decidis proklami en la tuta lando de Izrael, de Beer-Ŝeba ĝis Dan, ke oni venu fari Paskon al la Eternulo, Dio de Izrael, en Jerusalem; ĉar jam delonge oni ne faris ĝin, kiel estas skribite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Kaj ekiris kurieroj kun leteroj de la reĝo kaj de liaj eminentuloj en la tutan landon de Izrael kaj Jehuda, kun jena ordono de la reĝo: Ho idoj de Izrael, revenu al la Eternulo, Dio de Abraham, Isaak, kaj Izrael, kaj tiam Li revenos al la saviĝintoj, kiuj restis ĉe vi de la mano de la reĝoj de Asirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Kaj ne estu kiel viaj patroj kaj viaj fratoj, kiuj krimis kontraŭ la Eternulo, Dio de iliaj patroj, kaj kiujn Li tial elmetis al ruinigo, kiel vi vidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Nun ne estu malmolnukaj kiel viaj patroj: donu la manon al la Eternulo, kaj venu en Lian sanktejon, kiun Li sanktigis por ĉiam, kaj servu al la Eternulo, via Dio, kaj Li deturnos de vi la flamon de Sia kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Ĉar se vi revenos al la Eternulo, viaj fratoj kaj viaj filoj trovos favorkorecon ĉe tiuj, kiuj ilin forkaptis, kaj povos reveni en ĉi tiun landon; ĉar kompatema kaj favorkora estas la Eternulo, via Dio, kaj Li ne deturnos de vi Sian vizaĝon, se vi revenos al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'La kurieroj iris de urbo al urbo en la lando de Efraim kaj Manase kaj ĝis la lando de Zebulun; sed oni ridis pri ili kaj mokis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Nur kelkaj el la Aŝeridoj, Manaseidoj, kaj Zebulunidoj humiliĝis, kaj venis en Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Super Judujo estis la mano de Dio, por doni al ili unuanimecon, por plenumi la ordonon de la reĝo kaj de la eminentuloj konforme al la vorto de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Kaj kolektiĝis en Jerusalem multe da popolo, por fari la feston de macoj en la dua monato, tre granda homamaso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Kaj ili leviĝis, kaj forigis la altarojn, kiuj estis en Jerusalem; kaj ĉion, sur kio oni faradis incensadon, ili forigis kaj ĵetis en la torenton Kidron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Kaj ili buĉis la Paskon en la dek-kvara tago de la dua monato. La pastroj kaj la Levidoj hontis, kaj sanktigis sin kaj venigis la bruloferojn al la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'Kaj ili staris sur siaj postenoj laŭ la preskribo, konforme al la instruo de Moseo, la homo de Dio. La pastroj aspergis per la sango el la manoj de la Levidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Ĉar en la komunumo estis multaj, kiuj sin ne sanktigis, tial la Levidoj okupis sin per la buĉado de la Paskoj anstataŭ ĉiu, kiu ne estis pura, por esti sanktigata al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Multaj el la popolo, plejparte el Efraim, Manase, Isaĥar, kaj Zebulun, ne purigis sin; tamen ili manĝis la Paskon, ne konforme al la preskribo; sed Ĥizkija preĝis pri ili, dirante: La Eternulo, la bona, pardonu ĉiun,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'kiu pretigis sian koron, por turni sin al Dio, la Eternulo, Dio de liaj patroj, kvankam ne konforme al la sankta puriĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Kaj la Eternulo aŭskultis Ĥizkijan kaj pardonis la popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Kaj la Izraelidoj, kiuj troviĝis en Jerusalem, faris la feston de macoj dum sep tagoj en granda ĝojo; kaj ĉiutage la Levidoj kaj la pastroj glorkantis al la Eternulo per instrumentoj, difinitaj por glorado de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Kaj Ĥizkija parolis afable al ĉiuj Levidoj, kiuj distingiĝis en la servado al la Eternulo. Kaj oni manĝis la festan manĝaĵon dum sep tagoj, alportante pacoferojn, kaj dankante la Eternulon, Dion de iliaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Kaj la tuta komunumo interkonsiliĝe decidis festi aliajn sep tagojn, kaj ili pasigis la sep tagojn en gajeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Ĉar Ĥizkija, reĝo de Judujo, donis por la popolo mil bovojn kaj sep mil ŝafojn, kaj la eminentuloj donis al la popolo mil bovojn kaj dek mil ŝafojn; kaj jam tre multaj el la pastroj sin sanktigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Kaj ĝojis la tuta komunumo de la Judoj kaj la pastroj kaj la Levidoj, kaj la tuta popolamaso, kiu venis de Izrael, kaj la aligentuloj, kiuj venis el la lando de Izrael kaj kiuj loĝis en Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Kaj estis granda ĝojo en Jerusalem; ĉar de la tempo de Salomono, filo de David, reĝo de Izrael, ne estis io simila en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Kaj leviĝis la pastroj kaj la Levidoj kaj benis la popolon; kaj aŭskultita estis ilia voĉo, kaj venis ilia preĝo en Lian sanktan loĝejon, en la ĉielon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Kiam ĉio ĉi tio finiĝis, ĉiuj Izraelidoj, kiuj tie troviĝis, eliris en la urbojn de Judujo, kaj disrompis la statuojn, dishakis la sanktajn stangojn, kaj detruis la altaĵojn kaj la altarojn en la tuta Judujo kaj en la regionoj de Benjamen, de Efraim, kaj de Manase, ĝis plena ekstermo. Kaj reiris ĉiuj Izraelidoj ĉiu al sia posedaĵo, al siaj urboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Kaj Ĥizkija starigis la grupojn de la pastroj kaj de la Levidoj laŭ ilia ordo, ĉiun laŭ ĝia destino, la pastrojn kaj la Levidojn por la bruloferoj kaj por la pacoferoj, por servado, por laŭdkantado kaj glorkantado, ĉe la pordegoj de la tendaro de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Kaj la reĝo destinis parton el sia havaĵo por bruloferoj: por la bruloferoj matenaj kaj vesperaj, por la bruloferoj sabataj, monatkomencaj, kaj festaj, kiel estas skribite en la instruo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Kaj li ordonis al la popolo, kiu loĝis en Jerusalem, donadi vivrimedojn al la pastroj kaj al la Levidoj, por ke ili povu fordoni sin al la instruo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Kiam ĉi tiu ordono disvastiĝis, la Izraelidoj alportis multe da unuaaĵoj el greno, mosto, oleo, kaj mielo, kaj diversajn kampajn produktaĵojn, kaj ankaŭ dekonaĵojn el ĉio ili multe alportis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Kaj la Izraelidoj kaj la Judoj, kiuj loĝis en la urboj de Judujo, ankaŭ alportis dekonaĵon el bovoj kaj ŝafoj, kaj dekonaĵon sanktan, konsekritan al la Eternulo, ilia Dio; kaj ili amasigis grandajn amasojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'En la tria monato oni komencis la aranĝadon de la amasoj, kaj en la sepa monato oni finis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Kiam Ĥizkija kaj la estroj venis kaj ekvidis la amasojn, ili benis la Eternulon kaj Lian popolon Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Kaj Ĥizkija demandis la pastrojn kaj la Levidojn pri la amasoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Kaj respondis al li Azarja, la ĉefpastro, el la domo de Cadok, kaj diris: De la momento, kiam oni komencis portadi la donojn en la domon de la Eternulo, oni manĝis kaj satiĝis, kaj restis ankoraŭ multe; ĉar la Eternulo benis Sian popolon; el la restaĵo kolektiĝis ĉi tiu amasego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Kaj Ĥizkija ordonis pretigi ĉambrojn ĉe la domo de la Eternulo. Kaj oni pretigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'Kaj oni transportis tien la donojn, la dekonaĵojn, kaj la konsekritaĵojn kun fideleco. Estro super tio estis Konanja, la Levido, kaj lia frato Ŝimei estis la dua post li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Kaj Jeĥiel, Azazja, Naĥat, Asahel, Jerimot, Jozabad, Eliel, Jiŝmaĥja, Maĥat, kaj Benaja estis oficistoj apud Konanja kaj lia frato Ŝimei, laŭ ordono de la reĝo Ĥizkija, kaj de Azarja, estro en la domo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Kore, filo de Jimna, Levido pordegisto ĉe la flanko orienta, estis super la memvolaj donoj al Dio, super la oferdonoj, alportataj al la Eternulo, kaj super la plejsanktaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Liaj helpantoj estis Eden, Minjamin, Jeŝua, Ŝemaja, Amarja, kaj Ŝeĥanja, en la urboj de la pastroj, por fidele disdonadi al siaj fratoj laŭgrupe, al la grandaj kaj al la malgrandaj');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, '(krom la registritaj virseksuloj, havantaj la aĝon de tri jaroj kaj pli, de ĉiuj, kiuj iradis ĉiutage en la domon de la Eternulo laŭ siaj oficoj kaj grupoj),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'al la registritaj pastroj, laŭ iliaj patrodomoj, kaj al la Levidoj, havantaj la aĝon de dudek jaroj kaj pli, laŭ iliaj oficoj kaj grupoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'al la registritoj kun ĉiuj iliaj malgrandaj infanoj, edzinoj, filoj, kaj filinoj, al la tuta komunumo, por ke ili fidele dediĉu sin al la sanktaj aferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Kaj por la Aaronidoj, la pastroj, sur la antaŭurbaj kampoj de iliaj urboj, de ĉiu urbo, la nomitaj viroj estis destinitaj, por doni partojn al ĉiu virseksulo inter la pastroj kaj al ĉiu registrito inter la Levidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Tion faris Ĥizkija en la tuta Judujo, kaj li agadis bone, juste, kaj vere antaŭ la Eternulo, lia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'Kaj en ĉiuj faroj, kiujn li entreprenis koncerne la servadon en la domo de Dio, la instruon kaj la ordonon pri la sinturnado al sia Dio, li agadis el la tuta koro, kaj li havis sukceson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Post tiuj aferoj kaj veraĵoj venis Sanĥerib, reĝo de Asirio; li venis en Judujon, eksieĝis la fortikigitajn urbojn, kaj intencis forŝiri ilin al si.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Kiam Ĥizkija vidis, ke Sanĥerib venis kaj intencas militi kontraŭ Jerusalem,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'li konsiliĝis kun siaj eminentuloj kaj fortuloj, kaj decidis ŝutkovri la akvon de la fontoj, kiuj estis ekster la urbo; kaj ili helpis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Kaj kolektiĝis multe da popolo, kaj ili ŝutkovris ĉiujn fontojn, kaj la torenton, kiu fluas meze de la lando, ĉar ili diris: Por kio permesi, ke la reĝoj de Asirio, veninte, trovu multe da akvo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Kaj li estis kuraĝa, kaj li prikonstruis la tutan difektiĝintan muregon, li plialtigis la turojn, kaj konstruis ekstere ankoraŭ alian muregon, kaj li fortikigis Milon apud la urbo de David, kaj pretigis multe da bataliloj kaj da ŝildoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Kaj li starigis militestrojn super la popolo, kaj li kunvenigis ilin al si sur la placon antaŭ la pordego de la urbo, kaj vigligis ilian koron, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Estu kuraĝaj kaj fortaj, ne timu, kaj ne sentu teruron antaŭ la reĝo de Asirio kaj antaŭ la tuta homamaso, kiu estas kun li, ĉar kun ni estas pli, ol kun li:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'kun li estas brako karna, sed kun ni estas la Eternulo, nia Dio, por helpi al ni kaj por batali en niaj bataloj. Kaj la popolo vigliĝis de la vortoj de Ĥizkija, reĝo de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Post tio Sanĥerib, reĝo de Asirio, sendis siajn servantojn en Jerusalemon (li mem estis ĉe Laĥiŝ kune kun sia tuta militistaro) al Ĥizkija, reĝo de Judujo, kaj al ĉiuj Judoj en Jerusalem, por diri:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'Tiele diras Sanĥerib, reĝo de Asirio: Kion vi fidas, loĝante en la fortikaĵo de Jerusalem?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Ĥizkija trompis vin, por mortigi vin de malsato kaj soifo, se li diras al vi: La Eternulo, nia Dio, savos nin el la mano de la reĝo de Asirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Li mem, Ĥizkija, forigis ja Liajn altaĵojn kaj Liajn altarojn, kaj ordonis al Judujo kaj Jerusalem, dirante: Antaŭ unu sola altaro adorkliniĝu kaj sur ĝi incensu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Ĉu vi ne scias, kion mi kaj miaj patroj faris al ĉiuj popoloj de la landoj? Ĉu la dioj de la nacioj de la landoj povis savi ilian landon el mia mano?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Kiu el ĉiuj dioj de tiuj nacioj, kiujn miaj patroj ekstermis, povis savi sian popolon el mia mano, ke via Dio povus savi vin el mia mano?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Ĥizkija do ne trompu vin kaj ne logu vin tiamaniere, kaj vi ne kredu al li. Se neniu dio de iu ajn nacio kaj regno povis savi sian popolon el mia mano kaj el la mano de miaj patroj, ankaŭ viaj dioj ne savos vin el mia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Kaj ankoraŭ pli liaj servantoj parolis kontraŭ Dio, la Eternulo, kaj kontraŭ Lia servanto Ĥizkija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Kaj leterojn li skribis, por insulti la Eternulon, Dion de Izrael, kaj dirante pri Li tiele: Kiel la dioj de la nacioj de la landoj ne savis sian popolon el mia mano, tiel ankaŭ la Dio de Ĥizkija ne savos Sian popolon el mia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Kaj ili kriis per laŭta voĉo en la Juda lingvo al la popolo Jerusalema, kiu estis sur la murego, por timigi ĝin kaj senkuraĝigi ĝin, por ke ili povu venkopreni la urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'Kaj ili parolis pri Dio de Jerusalem tiel, kiel pri la dioj de la popoloj de la tero, faritaĵo de homaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Sed la reĝo Ĥizkija, kaj la profeto Jesaja, filo de Amoc, ekpreĝis pri tio kaj kriis al la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Kaj la Eternulo sendis anĝelon, kaj li ekstermis ĉiujn fortulojn kaj eminentulojn kaj estrojn en la tendaro de la reĝo de Asirio. Kaj ĉi tiu revenis kun honto en sian landon; kaj kiam li eniris en la domon de sia dio, homoj, kiuj elvenis el liaj propraj lumboj, faligis lin per glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Tiamaniere la Eternulo savis Ĥizkijan kaj la loĝantojn de Jerusalem el la mano de Sanĥerib, reĝo de Asirio, kaj el la manoj de ĉiuj; kaj Li gardis ilin ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Tiam multaj alportadis donacojn al la Eternulo en Jerusalemon, kaj multekostajn objektojn al Ĥizkija, reĝo de Judujo. Kaj post tio li altiĝis en la okuloj de ĉiuj nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'En tiu tempo Ĥizkija morte malsaniĝis. Kaj li preĝis al la Eternulo. Ĉi Tiu parolis al li kaj donis al li pruvosignon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Ĥizkija ne repagis konforme al tio, kio estis farita por li; lia koro fieriĝis. Kaj ekscitiĝis kolero kontraŭ li kaj kontraŭ Judujo kaj Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Sed Ĥizkija humiliĝis pri la fieriĝo de sia koro, li kaj la loĝantoj de Jerusalem; tial ne trafis lin la kolero de la Eternulo en la tempo de Ĥizkija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Ĥizkija havis tre multe da riĉeco kaj honoro; kaj li faris al si trezorejojn por arĝento kaj oro, por multekostaj ŝtonoj, aromaĵoj, ŝildoj, kaj ĉiaj valoraj objektoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'ankaŭ provizejojn por la produktaĵoj: greno, mosto, oleo, kaj stalojn por ĉiaspecaj brutoj, kaj ŝafejojn por la ŝafoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Kaj urbojn li konstruis al si. Kaj da ŝafoj kaj bovoj li havis multe, ĉar Dio donis al li tre grandan havaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Li, Ĥizkija, ŝtopkovris la supran fonton de Giĥon kaj direktis ĝin malsupren al la okcidenta flanko de la urbo de David. Kaj Ĥizkija havis sukceson en ĉiu sia faro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Nur kiam la senditoj de la princoj de Babel estis senditaj al li, por demandi lin pri la signomiraklo, kiu aperis en la lando, Dio lin forlasis, por elprovi lin, por scii ĉion, kion li havis en sia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'La cetera historio de Ĥizkija kaj liaj virtoj estas priskribitaj en la vizio de la profeto Jesaja, filo de Amoc, en la libro de la reĝoj de Judujo kaj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Kaj Ĥizkija ekdormis kun siaj patroj, kaj oni enterigis lin en la plej alta loko de la tomboj de la idoj de David; kaj honoron faris al li post lia morto ĉiuj Judoj kaj loĝantoj de Jerusalem. Kaj anstataŭ li ekreĝis lia filo Manase.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'La aĝon de dek du jaroj havis Manase, kiam li fariĝis reĝo, kaj kvindek kvin jarojn li reĝis en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Li agadis malbone antaŭ la Eternulo, simile al la abomenindaĵoj de la nacioj, kiujn la Eternulo forpelis de antaŭ la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Li konstruis denove la altaĵojn, kiujn detruis lia patro Ĥizkija; kaj li starigis altarojn al la Baaloj, faris sanktajn stangojn, kaj adorkliniĝis antaŭ la tuta armeo de la ĉielo kaj servis al ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Li konstruis ankaŭ altarojn en la domo de la Eternulo, pri kiu la Eternulo diris: En Jerusalem estos Mia nomo eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Li konstruis altarojn al la tuta armeo de la ĉielo, sur la du kortoj de la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Li ankaŭ trairigis siajn filojn tra fajro en la valo de la filo de Hinom, li esploradis la estontecon, aŭguradis, sorĉadis, starigis antaŭdiristojn kaj magiistojn; li multe agadis malbone antaŭ la Eternulo, kolerigante Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'La skulptaĵon de la idolo, kiun li faris, li starigis en la domo de Dio, pri kiu Dio diris al David kaj al lia filo Salomono: En ĉi tiu domo kaj en Jerusalem, kiun Mi elektis inter ĉiuj triboj de Izrael, Mi estigos Mian nomon por eterne;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'kaj Mi ne plu foririgos la piedon de Izrael de sur la tero, kiun Mi destinis por viaj patroj, se ili nur observos por plenumi ĉion, kion Mi ordonis al ili, la tutan instruon, leĝojn, kaj preskribojn, donitajn per Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Manase delogis la Judojn kaj la loĝantojn de Jerusalem en tia grado, ke ili agadis pli malbone, ol tiuj nacioj, kiujn la Eternulo ekstermis antaŭ la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'La Eternulo parolis al Manase kaj al lia popolo, sed ili ne aŭskultis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Kaj la Eternulo venigis sur ilin la militestrojn de la reĝo de Asirio; kaj ili malliberigis Manasen per katenoj, ligis lin per ĉenoj, kaj forkondukis lin en Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'En sia mizero li ekpetegis la Eternulon, sian Dion, kaj li tre humiliĝis antaŭ la Dio de siaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'Kiam li preĝis al Li kaj petegis Lin, Li aŭskultis lian peton kaj revenigis lin en Jerusalemon al lia regno. Kaj Manase eksciis, ke la Eternulo estas la vera Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Post tio li konstruis eksteran muregon por la urbo de David okcidente de Giĥon, en la valo, ĝia la enirejo de la Pordego de Fiŝoj, ĉirkaŭ Ofel, kaj li faris ĝin tre alta. Kaj li starigis militestrojn en ĉiuj fortikigitaj urboj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Li forigis la fremdajn diojn kaj la idolon el la domo de la Eternulo, ankaŭ ĉiujn altarojn, kiujn li konstruis sur la monto de la domo de la Eternulo kaj en Jerusalem; kaj li elĵetis tion eksteren de la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Kaj li rekonstruis la altaron de la Eternulo kaj faris sur ĝi pacoferojn kaj dankoferojn, kaj li ordonis al la Judoj, ke ili servadu al la Eternulo, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Tamen la popolo ĉiam ankoraŭ oferadis sur la altaĵoj, sed nur al la Eternulo, sia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'La cetera historio de Manase, lia preĝo al lia Dio, kaj la vortoj de la viziistoj, kiuj parolis al li en la nomo de la Eternulo, Dio de Izrael, troviĝas en la kroniko de la reĝoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Lia preĝo kaj aŭskultiteco, ĉiuj liaj pekoj kaj krimoj, kaj la lokoj, sur kiuj li konstruis altaĵojn kaj starigis sanktajn stangojn kaj idolojn antaŭ sia humiliĝo, estas priskribitaj en la kroniko de la viziistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Kaj Manase ekdormis kun siaj patroj, kaj oni enterigis lin en lia domo. Kaj anstataŭ li ekreĝis lia filo Amon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'La aĝon de dudek du jaroj havis Amon, kiam li fariĝis reĝo, kaj du jarojn li reĝis en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Li agadis malbone antaŭ la Eternulo, kiel agadis lia patro Manase; kaj al ĉiuj idoloj, kiujn faris lia patro Manase, Amon oferadis kaj servadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Li ne humiliĝis antaŭ la Eternulo, kiel humiliĝis lia patro Manase, sed li, Amon, multe kulpiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Kaj konspiris kontraŭ li liaj servantoj kaj mortigis lin en lia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Sed la popolo de la lando mortigis ĉiujn, kiuj faris konspiron kontraŭ la reĝo Amon; kaj la popolo de la lando faris reĝo anstataŭ li lian filon Joŝija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'La aĝon de ok jaroj havis Joŝija, kiam li fariĝis reĝo, kaj tridek unu jarojn li reĝis en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Li agadis bone antaŭ la Eternulo, kaj iradis laŭ la vojoj de sia patro David, kaj ne deflankiĝis dekstren nek maldekstren.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'En la oka jaro de sia reĝado, estante ankoraŭ knabo, li komencis turnadi sin al la Dio de sia patro David; kaj en la dek-dua jaro li komencis purigi Judujon kaj Jerusalemon de la altaĵoj, sanktaj stangoj, idoloj, kaj fanditaj statuoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Kaj oni detruis antaŭ li la altarojn de la Baaloj; la kolonojn de la suno, kiuj estis super ili, li dehakis; la sanktajn stangojn, idolojn, kaj statuojn li disbatis, dispecetigis, kaj disĵetis sur la tombojn de tiuj, kiuj alportadis al ili oferojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'La ostojn de la pastroj li forbruligis sur iliaj altaroj; kaj li purigis Judujon kaj Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Ankaŭ en la urboj de Manase, Efraim, Simeon, kaj ĝis Naftali, en iliaj ruinoj ĉirkaŭe,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'li detruis la altarojn kaj la sanktajn stangojn, kaj la idolojn li disbatis en pecetojn, kaj ĉiujn kolonojn de la suno li dehakis en la tuta lando de Izrael; kaj li revenis en Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'En la dek-oka jaro de sia reĝado, post la purigo de la lando kaj de la domo, li sendis Ŝafanon, filon de Acalja, la urbestron Maaseja, kaj la kronikiston Joaĥ, filo de Joaĥaz, por ripari la domon de la Eternulo, lia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Kaj ili venis al la ĉefpastro Ĥilkija, kaj transdonis la arĝenton, alportitan en la domon de Dio, kaj kolektitan de la Levidoj, la sojlogardistoj, el la manoj de Manase, Efraim, kaj ĉiuj restintaj Izraelidoj, ankaŭ de ĉiuj Jehudaidoj kaj Benjamenidoj; kaj ili revenis en Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'Kaj ili donis tion en la manojn de la laborplenumantoj, kiuj havis komision en la domo de la Eternulo; kaj ĉi tiuj donis al tiuj, kiuj laboris en la domo de la Eternulo, rebonigante kaj riparante la domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'Ili donis al la ĉarpentistoj kaj konstruistoj, por aĉeti ĉirkaŭhakitajn ŝtonojn kaj lignon por kunteniloj kaj traboj por la domoj, kiujn ruinigis la reĝoj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Tiuj homoj plenumadis la laboron honeste; oficon de observistoj super ili havis Jaĥat kaj Obadja, Levidoj el la Merariidoj, kaj Zeĥarja kaj Meŝulam el la Kehatidoj; la Levidoj ĉiuj estis kompetentaj muzikistoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'super la portistoj, kiel observistoj super ĉiuj laboristoj en ĉiuj laboroj, estis el la Levidoj la skribistoj, kontrolistoj, kaj pordegistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Kiam ili elprenis la arĝenton, kiu estis alportita en la domon de la Eternulo, la pastro Ĥilkija trovis la libron de instruo de la Eternulo, donitan per Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Kaj Ĥilkija ekparolis kaj diris al la skribisto Ŝafan: Libron de la instruo mi trovis en la domo de la Eternulo; kaj Ĥilkija donis la libron al Ŝafan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Kaj Ŝafan alportis la libron al la reĝo, kaj li ankaŭ raportis al la reĝo jene: Ĉion, kio estas komisiita al viaj servantoj, ili faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Oni elŝutis la arĝenton, trovitan en la domo de la Eternulo, kaj donis ĝin en la manojn de la oficistoj kaj de la laboristoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Kaj la skribisto Ŝafan raportis al la reĝo, dirante: Libron donis al mi la pastro Ĥilkija. Kaj Ŝafan legis el ĝi antaŭ la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Kiam la reĝo aŭdis la vortojn de la instruo, li disŝiris siajn vestojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'Kaj la reĝo ordonis al Ĥilkija, Aĥikam, filo de Ŝafan, Abdon, filo de Miĥa, la skribisto Ŝafan, kaj Asaja, servanto de la reĝo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Iru, demandu la Eternulon por mi kaj por la restintoj el Izrael kaj Jehuda, pri la vortoj de la trovita libro; ĉar granda estas la kolero de la Eternulo, elverŝiĝinta sur nin pro tio, ke niaj patroj ne observis la vorton de la Eternulo, por plenumi ĉion, kio estas skribita en ĉi tiu libro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Kaj iris Ĥilkija, kaj tiuj, kiuj estis ĉe la reĝo, al la profetino Ĥulda, edzino de Ŝalum, filo de Tokhat, filo de Ĥasra, la vestogardisto (ŝi loĝis en Jerusalem, en la dua parto); kaj ili parolis kun ŝi pri tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Kaj ŝi diris al ili: Tiele diras la Eternulo, Dio de Izrael: Diru al la homo, kiu sendis vin al mi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Tiele diras la Eternulo: Jen Mi venigos malfeliĉon sur ĉi tiun lokon kaj sur ĝiajn loĝantojn, ĉiujn malbenojn, skribitajn en la libro, kiun oni legis antaŭ la reĝo de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Pro tio, ke ili Min forlasis kaj incensis al aliaj dioj, kolerigante Min per ĉiuj faroj de siaj manoj, ekflamis Mia kolero kontraŭ ĉi tiu loko, kaj ĝi ne estingiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Kaj koncerne la reĝon de Judujo, kiu sendis vin, por demandi la Eternulon, diru al li jene: Tiele diras la Eternulo, Dio de Izrael, pri la vortoj, kiujn vi aŭdis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Ĉar via koro moliĝis kaj vi humiliĝis antaŭ Dio, kiam vi aŭdis Liajn vortojn pri ĉi tiu loko kaj pri ĝiaj loĝantoj, kaj vi humiliĝis antaŭ Mi, disŝiris viajn vestojn, kaj ploris antaŭ Mi: tial Mi ankaŭ aŭskultis vin, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Jen Mi alkolektos vin al viaj patroj, kaj vi iros en vian tombon en paco, kaj viaj okuloj ne vidos la tutan malfeliĉon, kiun Mi venigos sur ĉi tiun lokon kaj sur ĝiajn loĝantojn. Kaj ili alportis la respondon al la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'La reĝo sendis, kaj kunvenigis ĉiujn plejaĝulojn de Judujo kaj Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Kaj la reĝo iris en la domon de la Eternulo, kaj kune kun li ĉiuj Judoj kaj loĝantoj de Jerusalem, la pastroj kaj la Levidoj, kaj la tuta popolo, de la grandaj ĝis la malgrandaj; kaj oni voĉlegis antaŭ ili ĉiujn vortojn de la libro de interligo, kiu estis trovita en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Kaj la reĝo stariĝis sur sia loko, kaj faris interligon antaŭ la Eternulo, por sekvi la Eternulon, kaj observi Liajn ordonojn, decidojn, kaj leĝojn, per sia tuta koro kaj per sia tuta animo, por plenumi la vortojn de la interligo, skribitajn en tiu libro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Kaj li aligis al tio ĉiujn, kiuj troviĝis en Jerusalem kaj en la lando de Benjamen. Kaj la loĝantoj de Jerusalem agadis laŭ la interligo de Dio, Dio de iliaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Kaj Joŝija forigis ĉiujn abomenindaĵojn el ĉiuj regionoj, kiuj apartenis al la Izraelidoj; kaj ĉiujn, kiuj troviĝis en Izrael, li devigis servi al la Eternulo, ilia Dio. Dum lia tuta vivo ili ne defalis de la Eternulo, Dio de iliaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Joŝija faris en Jerusalem Paskon al la Eternulo, kaj oni buĉis la Paskon en la dek-kvara tago de la unua monato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Li starigis la pastrojn sur iliaj postenoj kaj vigligis ilin por la servado en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Kaj li diris al la Levidoj, la instruantoj de la tuta Izrael, konsekritaj al la Eternulo: Metu la sanktan keston en la domon, kiun konstruis Salomono, filo de David, reĝo de Izrael; vi ne bezonas porti ĝin sur la ŝultroj; servu nun al la Eternulo, via Dio, kaj al Lia popolo Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'Aranĝu vin laŭ viaj patrodomoj, laŭ viaj grupoj, laŭ la preskribo de David, reĝo de Izrael, kaj laŭ la preskribo de lia filo Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'Kaj staru en la sanktejo laŭ klasoj, laŭ la patrodomoj de viaj fratoj, filoj de la popolo, kaj laŭ la patrodomaj grupoj de la Levidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Kaj buĉu la Paskon, kaj sanktigu vin, kaj pretigu por viaj fratoj, agante laŭ la vorto de la Eternulo per Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Kaj Joŝija donis donace al la filoj de la popolo ŝafojn, ŝafidojn, kapridojn, ĉion por la Paskoj, por ĉiuj, kiuj tie troviĝis, en la nombro de tridek mil, kaj tri mil bovojn. Tio estis el la havaĵo de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Kaj liaj eminentuloj donis memvolan donacon al la popolo, al la pastroj, kaj al la Levidoj. Ĥilkija, Zeĥarja, kaj Jeĥiel, la estroj en la domo de Dio, donis al la pastroj por la Paskoj du mil sescent ŝafidojn kaj tricent bovojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Konanja, Ŝemaja, kaj Netanel, liaj fratoj, kaj Ĥaŝabja, Jeiel, kaj Jozabad, la estroj de la Levidoj, donacis al la Levidoj por la Paskoj kvin mil ŝafidojn kaj kvincent bovojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Tiamaniere la servado estis aranĝita. Kaj la pastroj stariĝis sur siaj postenoj kaj la Levidoj laŭ iliaj grupoj, laŭ la ordono de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Kaj ili buĉis la Paskon. Kaj la pastroj aspergis el siaj manoj, kaj la Levidoj senhaŭtigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Kaj ili apartigis la bruloferojn, por doni ilin laŭklase, laŭ la patrodomoj, al la filoj de la popolo, por alportado al la Eternulo, kiel estas skribite en la libro de Moseo. Tiel same ili agis kun la bovoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Kaj ili kuiris la Paskon sur fajro, laŭ la preskribo; kaj la sanktajn oferojn ili kuiris en kaldronoj, en potoj, kaj en kaseroloj, kaj faris tion rapide por la tuta popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Kaj poste ili pretigis por si kaj por la pastroj; ĉar la pastroj, la Aaronidoj, estis okupitaj je la alportado de la bruloferoj kaj seboj ĝis la nokto; tial la Levidoj pretigis por si kaj por la pastroj, la Aaronidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'La kantistoj, idoj de Asaf, estis sur siaj postenoj laŭ la preskribo de David, Asaf, Heman, kaj Jedutun, la viziisto de la reĝo, kaj la pordegistoj estis ĉe ĉiu pordego; ili ne bezonis forlasi sian servadon, ĉar iliaj fratoj, la Levidoj, preparis por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Tiamaniere estis aranĝita en tiu tago la servado al la Eternulo, por farado de la Pasko kaj alportado de bruloferoj sur la altaro de la Eternulo, laŭ la ordono de la reĝo Joŝija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Kaj la Izraelidoj, kiuj tie troviĝis, faris la Paskon en tiu tempo kaj la feston de macoj dum sep tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Tia Pasko ne estis farita en Izrael de post la tempo de la profeto Samuel; kaj el ĉiuj reĝoj de Izrael neniu faris tian Paskon, kian faris Joŝija, kaj la pastroj, kaj la Levidoj, kaj ĉiuj Judoj kaj Izraelidoj, kiuj tie troviĝis, kaj la loĝantoj de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'En la dek-oka jaro de la reĝado de Joŝija estis farita tiu Pasko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Post ĉio ĉi tio, kion Joŝija aranĝis en la domo, Neĥo, reĝo de Egiptujo, eliris milite kontraŭ Karkemiŝon ĉe Eŭfrato. Kaj eliris kontraŭ lin Joŝija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Kaj tiu sendis al li senditojn, por diri: Kio estas inter mi kaj vi, ho reĝo de Judujo? ne kontraŭ vin mi nun iras, sed tien, kie mi havas militon. Kaj Dio diris, ke mi rapidu; ne kontraŭstaru al Dio, kiu estas kun mi, por ke Li vin ne pereigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Sed Joŝija ne forturnis sin de li, sed alivestis sin por batali kontraŭ li; li ne obeis la vortojn de Neĥo el la buŝo de Dio, sed li iris en la valon Megido, por batali.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'La pafistoj pafis sur la reĝon Joŝija; kaj la reĝo diris al siaj servantoj: Forkonduku min, ĉar mi estas grave vundita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Liaj servantoj deprenis lin de la ĉaro, kaj sidigis lin sur alia veturilo, kiun li havis, kaj venigis lin en Jerusalemon. Kaj li mortis, kaj oni enterigis lin en la tomboj de liaj patroj. Kaj la tuta Judujo kaj Jerusalem funebris pri Joŝija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Ankaŭ Jeremia plorkantis pri Joŝija; kaj ĉiuj kantistoj kaj kantistinoj parolis en siaj plorkantoj pri Joŝija ĝis la nuna tago kaj faris ilin tradiciaj ĉe Izrael; ili estas enskribitaj en la libro de la plorkantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'La cetera historio de Joŝija kaj liaj virtoj, konformaj al la preskriboj de la instruo de la Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'kaj liaj agoj, la unuaj kaj la lastaj, estas priskribitaj en la libro de la reĝoj de Izrael kaj Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'La popolo de la lando prenis Jehoaĥazon, filon de Joŝija, kaj faris lin reĝo anstataŭ lia patro en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'La aĝon de dudek tri jaroj havis Jehoaĥaz, kiam li fariĝis reĝo, kaj tri monatojn li reĝis en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'La reĝo de Egiptujo detronigis lin en Jerusalem, kaj punis la landon per kontribucio de cent kikaroj da arĝento kaj unu kikaro da oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Kaj la reĝo de Egiptujo ekreĝigis super Judujo kaj Jerusalem lian fraton Eljakim, kaj ŝanĝis lian nomon je Jehojakim; kaj lian fraton Jehoaĥaz Neĥo prenis kaj forkondukis en Egiptujon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'La aĝon de dudek kvin jaroj havis Jehojakim, kiam li fariĝis reĝo, kaj dek unu jarojn li reĝis en Jerusalem. Kaj li agadis malbone antaŭ la Eternulo, lia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Kontraŭ lin iris Nebukadnecar, reĝo de Babel, kaj ligis lin per ĉenoj, por forkonduki lin en Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Kaj parton el la vazoj de la domo de la Eternulo Nebukadnecar transportis en Babelon kaj metis ilin en sian templon en Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'La cetera historio de Jehojakim, kaj liaj abomenindaĵoj, kiujn li faris kaj kiujn oni trovis pri li, estas priskribitaj en la libro de la reĝoj de Izrael kaj Judujo. Kaj anstataŭ li ekreĝis lia filo Jehojaĥin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'La aĝon de ok jaroj havis Jehojaĥin, kiam li fariĝis reĝo, kaj tri monatojn kaj dek tagojn li reĝis en Jerusalem. Kaj li agadis malbone antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Kiam la jaro finiĝis, la reĝo Nebukadnecar sendis, kaj venigis lin en Babelon, kune kun multekostaj vazoj el la domo de la Eternulo, kaj li faris lian fraton Cidkija reĝo super Judujo kaj Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'La aĝon de dudek unu jaroj havis Cidkija, kiam li fariĝis reĝo, kaj dek unu jarojn li reĝis en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Li agadis malbone antaŭ la Eternulo, lia Dio. Li ne humiliĝis antaŭ Jeremia, kiu profetis laŭ la vortoj de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Li defalis ankaŭ de la reĝo Nebukadnecar, kiu ĵurigis lin per Dio; li malmoligis sian nukon kaj obstinigis sian koron, ne konvertante sin al la Eternulo, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Ankaŭ ĉiuj estroj de la pastroj kaj de la popolo tre multe pekadis, simile al ĉiuj abomenindaĵoj de la nacioj, kaj ili malpurigis la domon de la Eternulo, kiun Li sanktigis en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'La Eternulo, Dio de iliaj patroj, avertadis ilin per Siaj senditoj, konstante avertadis, ĉar Li domaĝis Sian popolon kaj Sian loĝejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Sed ili mokis la senditojn de Dio, malŝatis Liajn vortojn, kaj ridis pri Liaj profetoj, ĝis la kolero de la Eternulo leviĝis kontraŭ Lian popolon tiel, ke saniĝo fariĝis ne ebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Kaj Li venigis sur ilin la reĝon de la Ĥaldeoj, kaj ĉi tiu mortigis iliajn junulojn per glavo en la domo de ilia sanktejo; li ne kompatis junulon nek junulinon, nek maljunulon nek grizulon: ĉio estis transdonita en lian manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Kaj ĉiujn objektojn el la domo de Dio, la grandajn kaj la malgrandajn, kaj la trezorojn de la domo de la Eternulo, kaj la trezorojn de la reĝo kaj de liaj altranguloj, ĉion li transportis en Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Kaj ili forbruligis la domon de Dio kaj detruis la muregojn de Jerusalem, kaj ĉiujn ĝiajn palacojn ili forbruligis per fajro, kaj ĉiujn ĝiajn plej karajn objektojn ili neniigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Kaj tiujn, kiuj restis de la glavo, li forkondukis en Babelon, kaj ili fariĝis sklavoj por li kaj por liaj filoj, ĝis venis la regado de la Persoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'por ke plenumiĝu la vorto de la Eternulo, dirita per Jeremia: Ĝis la lando estos elfestinta siajn sabatojn. Ĉar dum la tuta tempo de sia dezerteco ĝi havis sabaton, ĝis finiĝis sepdek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'En la unua jaro de Ciro, reĝo de Persujo, por ke plenumiĝu la vorto de la Eternulo, dirita per Jeremia, la Eternulo ekscitis la spiriton de Ciro, reĝo de Persujo, kaj ĉi tiu ordonis proklami en sia tuta regno voĉe kaj skribe jenon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'Tiele diras Ciro, reĝo de Persujo: Ĉiujn regnojn de la tero donis al mi la Eternulo, Dio de la ĉielo, kaj Li komisiis al mi konstrui al Li domon en Jerusalem, kiu estas en Judujo. Kiu inter vi estas el Lia tuta popolo, kun tiu estu la Eternulo, lia Dio, kaj li tien iru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'En la unua jaro de Ciro, reĝo de Persujo, por ke plenumiĝu la vorto de la Eternulo, dirita per Jeremia, la Eternulo ekscitis la spiriton de Ciro, reĝo de Persujo, kaj ĉi tiu ordonis proklami en sia tuta regno voĉe kaj skribe jenon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'Tiele diras Ciro, reĝo de Persujo: Ĉiujn regnojn de la tero donis al mi la Eternulo, Dio de la ĉielo, kaj Li komisiis al mi konstrui al Li domon en Jerusalem, kiu estas en Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Kiu inter vi estas el Lia tuta popolo, kun tiu estu lia Dio; kaj li iru en Jerusalemon, kiu estas en Judujo, kaj konstruu la domon de la Eternulo, Dio de Izrael, de tiu Dio, kiu estas en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Kaj al ĉiu, kiu restis, en kiu ajn loko li loĝas, la loĝantoj de lia loko helpu al li per arĝento, per oro, per alia havo, kaj per brutoj, kun memvola donaco por la domo de Dio, kiu estas en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Kaj leviĝis la ĉefoj de la patrodomoj de Jehuda kaj de Benjamen, kaj la pastroj kaj la Levidoj, ĉiu, en kiu Dio vekis lian spiriton, por iri konstrui la domon de la Eternulo en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Kaj ĉiuj iliaj ĉirkaŭantoj helpis al ili per arĝentaj objektoj, per oro, per alia havo, per brutoj, kaj per multekostaĵoj, krom ĉiuj memvolaj donacoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Kaj la reĝo Ciro elportigis la vazojn de la domo de la Eternulo, kiujn Nebukadnecar estis elportinta el Jerusalem kaj metinta en la domon de liaj dioj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Ciro, reĝo de Persujo, elportigis ilin per la trezoristo Mitredat, kiu laŭkalkule transdonis ilin al Ŝeŝbacar, princo de la Judoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Kaj jen estas ilia nombro: da oraj pelvoj tridek, da arĝentaj pelvoj mil, da tranĉiloj dudek naŭ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'da oraj kalikoj tridek, da arĝentaj duoblaj kalikoj kvarcent dek, da aliaj vazoj mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'La nombro de ĉiuj vazoj oraj kaj arĝentaj estis kvin mil kvarcent. Ĉion ĉi tion kunportis Ŝeŝbacar ĉe la foriro de la forkaptitoj el Babel en Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Jen estas la loĝantoj de la lando, kiuj iris el la forkaptitoj, kiujn forkondukis en Babelon Nebukadnecar, reĝo de Babel, kaj kiuj revenis en Jerusalemon kaj en Judujon, ĉiu en sian urbon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'kiuj venis kun Zerubabel, Jeŝua, Neĥemja, Seraja, Reelaja, Mordeĥaj, Bilŝan, Mispar, Bigvaj, Reĥum, Baana. La nombro de la viroj de la popolo Izraela estis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'de la idoj de Paroŝ, du mil cent sepdek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'de la idoj de Ŝefatja, tricent sepdek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'de la idoj de Araĥ, sepcent sepdek kvin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'de la idoj de Paĥat-Moab, el la idoj de Jeŝua kaj Joab, du mil okcent dek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'de la idoj de Elam, mil ducent kvindek kvar,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'de la idoj de Zatu, naŭcent kvardek kvin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'de la idoj de Zakaj, sepcent sesdek,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'de la idoj de Bani, sescent kvardek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'de la idoj de Bebaj, sescent dudek tri,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'de la idoj de Azgad, mil ducent dudek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'de la idoj de Adonikam, sescent sesdek ses,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'de la idoj de Bigvaj, du mil kvindek ses,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'de la idoj de Adin, kvarcent kvindek kvar,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'de la idoj de Ater, el la domo de Ĥizkija, naŭdek ok,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'de la idoj de Becaj, tricent dudek tri,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'de la idoj de Jora, cent dek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'de la idoj de Ĥaŝum, ducent dudek tri,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'de la idoj de Gibar, naŭdek kvin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'de la idoj de Bet-Leĥem, cent dudek tri,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'de la loĝantoj de Netofa, kvindek ses,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'de la loĝantoj de Anatot, cent dudek ok,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'de la idoj de Azmavet, kvardek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'de la idoj de Kirjat-Arim, Kefira, kaj Beerot, sepcent kvardek tri,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'de la idoj de Rama kaj Geba, sescent dudek unu,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'de la loĝantoj de Miĥmas, cent dudek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'de la loĝantoj de Bet-El kaj Aj, ducent dudek tri,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'de la idoj de Nebo, kvindek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'de la idoj de Magbiŝ, cent kvindek ses,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'de la idoj de la alia Elam, mil ducent kvindek kvar,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'de la idoj de Ĥarim, tricent dudek,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'de la idoj de Lod, Ĥadid, kaj Ono, sepcent dudek kvin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'de la idoj de Jeriĥo, tricent kvardek kvin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'de la idoj de Senaa, tri mil sescent tridek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'De la pastroj: de la idoj de Jedaja, el la domo de Jeŝua, naŭcent sepdek tri,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'de la idoj de Imer, mil kvindek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'de la idoj de Paŝĥur, mil ducent kvardek sep,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'de la idoj de Ĥarim, mil dek sep.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'De la Levidoj: de la idoj de Jeŝua kaj Kadmiel, el la filoj de Hodavja, sepdek kvar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'De la kantistoj: de la idoj de Asaf, cent dudek ok.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'De la idoj de la pordegistoj: la idoj de Ŝalum, la idoj de Ater, la idoj de Talmon, la idoj de Akub, la idoj de Ĥatita, la idoj de Ŝobaj, ĉiuj kune cent tridek naŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'De la Netinoj: la idoj de Ciĥa, la idoj de Ĥasufa, la idoj de Tabaot,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'la idoj de Keros, la idoj de Siaha, la idoj de Padon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'la idoj de Lebana, la idoj de Ĥagaba, la idoj de Akub,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'la idoj de Ĥagab, la idoj de Ŝalmaj, la idoj de Ĥanan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'la idoj de Gidel, la idoj de Gaĥar, la idoj de Reaja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'la idoj de Recin, la idoj de Nekoda, la idoj de Gazam,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'la idoj de Uza, la idoj de Paseaĥ, la idoj de Besaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'la idoj de Asna, la idoj de Meunim, la idoj de Nefusim,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'la idoj de Bakbuk, la idoj de Ĥakufa, la idoj de Ĥarĥur,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'la idoj de Baclut, la idoj de Meĥida, la idoj de Ĥarŝa,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'la idoj de Barkos, la idoj de Sisra, la idoj de Tamaĥ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'la idoj de Neciaĥ, la idoj de Ĥatifa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'La idoj de la servantoj de Salomono: la idoj de Sotaj, la idoj de Soferet, la idoj de Peruda,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'la idoj de Jaala, la idoj de Darkon, la idoj de Gidel,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'la idoj de Ŝefatja, la idoj de Ĥatil, la idoj de Poĥeret-Cebaim, la idoj de Ami.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'La nombro de ĉiuj Netinoj kaj de la idoj de la servantoj de Salomono estis tricent naŭdek du.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Kaj jen estas la elirintoj el Tel-Melaĥ, Tel-Ĥarŝa, Kerub, Adan, kaj Imer, kiuj ne povis montri sian patrodomon kaj devenon, ĉu ili devenas de Izrael:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'la idoj de Delaja, la idoj de Tobija, la idoj de Nekoda, sescent kvindek du.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'Kaj el la pastridoj: la idoj de Ĥabaja, la idoj de Hakoc, la idoj de Barzilaj, kiu prenis al si edzinon el la filinoj de Barzilaj, la Gileadano, kaj estis nomata per ilia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Ili serĉis siajn dokumentojn genealogiajn, sed ĉi tiuj ne troviĝis; tial ili estis eligitaj el la listo de la pastroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'Kaj la regionestro diris al ili, ke ili ne manĝu el la plejsanktaĵo, ĝis aperos pastro kun la signoj de lumo kaj de justo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'La tuta komunumo kune konsistis el kvardek du mil tricent sesdek homoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'krom iliaj sklavoj kaj sklavinoj, kies nombro estis sep mil tricent tridek sep, kaj al tio estis ducent kantistoj kaj kantistinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Da ĉevaloj ili havis sepcent tridek ses; da muloj ili havis ducent kvardek kvin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'da kameloj ili havis kvarcent tridek kvin; da azenoj ses mil sepcent dudek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Kelkaj el la ĉefoj de patrodomoj, veninte al la domo de la Eternulo en Jerusalem, faris memvolan oferon por la domo de Dio, por restarigi ĝin sur ĝia fundamento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Laŭ sia povo ili donis en la trezorejon de la laboroj: da oro sesdek unu mil darkemonojn, da arĝento kvin mil min�ojn, kaj da pastraj vestoj cent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'Kaj ekloĝis la pastroj kaj la Levidoj kaj la popolanoj kaj la kantistoj kaj la pordegistoj kaj la Netinoj en siaj urboj, kaj la tuta Izrael en siaj urboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Kiam venis la sepa monato kaj la Izraelidoj estis jam en la urboj, kolektiĝis la tuta popolo, kiel unu homo, en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Kaj leviĝis Jeŝua, filo de Jocadak, kaj liaj fratoj, la pastroj, kaj Zerubabel, filo de Ŝealtiel, kaj liaj fratoj, kaj ili konstruis la altaron de Dio de Izrael, por alportadi sur ĝi bruloferojn, kiel estas skribite en la instruo de Moseo, la homo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'Kaj ili aranĝis la altaron sur ĝia loko, ĉar ili timis la popolojn de la landoj; kaj ili komencis alportadi sur ĝi bruloferojn al la Eternulo, bruloferojn matenajn kaj vesperajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Kaj ili solenis la feston de laŭboj, kiel estas skribite, kaj faris la ĉiutagajn bruloferojn laŭ ilia nombro, konforme al tio, kio estas preskribita por ĉiu tago;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'kaj post tio la ĉiutagajn bruloferojn, kaj por la monatkomencoj kaj por ĉiuj sanktigitaj festoj de la Eternulo, kaj por ĉiu, kiu alportis memvolan oferon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'De la unua tago de la sepa monato ili komencis alportadi bruloferojn al la Eternulo. Sed la fundamento por la templo de la Eternulo ankoraŭ ne estis starigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Kaj ili donis monon al la ŝtonhakistoj kaj ĉarpentistoj, kaj manĝaĵon, trinkaĵon, kaj oleon al Cidonanoj kaj Tiranoj, por ke ili venigu cedrojn de Lebanon per la maro ĝis Jafo, konforme al la permeso, kiun donis al ili Ciro, reĝo de Persujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'En la dua jaro post ilia alveno al la domo de Dio en Jerusalem, en la dua monato, Zerubabel, filo de Ŝealtiel, kaj Jeŝua, filo de Jocadak, kaj iliaj ceteraj fratoj, la pastroj, kaj la Levidoj, kaj ĉiuj, kiuj venis el la kaptiteco en Jerusalemon, faris la komencon, kaj starigis la Levidojn, havantajn la aĝon de dudek jaroj kaj pli, por inspekti la laborojn en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Kaj Jeŝua kun siaj filoj kaj fratoj, kaj Kadmiel kun siaj filoj, la idoj de Jehuda, stariĝis kiel unu homo, por inspekti la faradon de la laboroj en la domo de Dio, ankaŭ la idoj de Ĥenadad kun siaj filoj kaj fratoj, la Levidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Kiam la konstruistoj starigis fundamenton por la templo de la Eternulo, tiam stariĝis la pastroj en siaj vestoj kun trumpetoj, kaj la Levidoj, idoj de Asaf, kun cimbaloj, por glori la Eternulon per la kantoj de David, reĝo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'Kaj ili ekkantis gloron kaj laŭdon al la Eternulo, ke Li estas bona, ke eterna estas Lia favorkoreco al Izrael; kaj la tuta popolo ĝojkriis laŭte, glorante la Eternulon pro la fondo de la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Kaj multaj el la pastroj kaj el la Levidoj kaj el la ĉefoj de patrodomoj, maljunuloj, kiuj vidis la unuan templon, nun, ĉe la fondado de ĉi tiu templo antaŭ iliaj okuloj, laŭte ploris; sed multaj laŭte ĝojkriis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Kaj la popolo ne povis distingi inter la sonoj de la ĝojkriado kaj la sonoj de la popola plorado; ĉar la popolo kriis tre laŭte, kaj tiu kriado estis aŭdata malproksime.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Kiam la malamikoj de Jehuda kaj Benjamen aŭdis, ke la revenintoj el la kaptiteco konstruas templon al la Eternulo, Dio de Izrael,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'tiam ili venis al Zerubabel kaj al la ĉefoj de la patrodomoj, kaj diris al ili: Ni ankaŭ deziras konstrui kun vi, ĉar simile al vi ni ankaŭ serĉas vian Dion, kaj al Li ni alportas oferojn de post la tempo de Esar-Ĥadon, reĝo de Asirio, kiu venigis nin ĉi tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Sed Zerubabel kaj Jeŝua kaj la aliaj ĉefoj de patrodomoj de Izrael diris al ili: Ne estas bone, ke vi kune kun ni konstruu domon por nia Dio; ni solaj konstruos por la Eternulo, Dio de Izrael, kiel ordonis al ni la reĝo Ciro, reĝo de Persujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Tiam la popolo de la lando komencis malfortigadi la manojn de la Juda popolo kaj malhelpadi al ĝi en la konstruado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Kaj ili dungadis kontraŭ ili konsilistojn, por detrui ilian entreprenon, dum la tuta tempo de Ciro, reĝo de Persujo, ĝis la reĝado de Dario, reĝo de Persujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Kaj en la tempo de la reĝado de Aĥaŝveroŝ, en la komenco de lia reĝado, ili skribis akuzon kontraŭ la loĝantoj de Judujo kaj de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'En la tempo de Artaĥŝaŝt skribis Biŝlam, Mitredat, Tabeel, kaj la aliaj iliaj kunuloj al Artaĥŝaŝt, reĝo de Persujo: la letero estis skribita Sirie kaj klarigita Sirie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Reĥum, konsilisto, kaj Ŝimŝaj, skribisto, skribis unu leteron kontraŭ Jerusalem al Artaĥŝaŝt, la reĝo, en la sekvanta maniero:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'Ni, Reĥum, konsilisto, kaj Ŝimŝaj, skribisto, kaj iliaj aliaj kunuloj, Dinaanoj, Afarsatĥanoj, Tarpelanoj, Afarsanoj, Arkevanoj, Babelanoj, Ŝuŝananoj, Dehaanoj, Elamanoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'kaj la aliaj popoloj, kiujn transloĝigis Asnapar, la granda kaj glora, kaj enloĝigis en Samario kaj en la aliaj urboj transriveraj, kaj tiel plu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'Jen estas la teksto de la letero, kiun ili sendis al li: Al la reĝo Artaĥŝaŝt viaj sklavoj, la transriveranoj, kaj tiel plu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Estu sciate al la reĝo, ke la Judoj, kiuj foriris de vi kaj venis al ni en Jerusalemon, rekonstruas nun tiun ribeleman kaj malbonan urbon kaj faras muregojn kaj starigas jam la fundamentojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Nun estu sciate al la reĝo, ke se tiu urbo estos konstruita kaj la muregoj estos finitaj, tiam ili ne donos tributon nek impostojn nek jarpagon, kaj la reĝa kaso havos malprofiton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Ĉar ni manĝas salon el la reĝa palaco, kaj ni ne volas vidi ion, kio malhonoras la reĝon, tial ni sendas kaj sciigas al la reĝo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'ke oni serĉu en la kronikoj de viaj patroj, kaj vi trovos en la kronikoj kaj konvinkiĝos, ke tiu urbo estas urbo ribelema kaj malutila por la reĝoj kaj landoj, kaj ke ribeloj estis farataj en ĝi de la plej malproksimaj tempoj, kio estas la kaŭzo, pro kiu tiu urbo estis detruita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Ni sciigas al la reĝo, ke se tiu urbo estos rekonstruita kaj ĝiaj muregoj estos finitaj, tiam vi poste havos nenian parton en la regiono transrivera.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'La reĝo sendis respondon: Al Reĥum, konsilisto, Ŝimŝaj, skribisto, kaj al la aliaj iliaj kunuloj, kiuj loĝas en Samario kaj en la aliaj transriveraj lokoj, pacon kaj saluton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'La letero, kiun vi sendis al ni, estas klare legita antaŭ mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'kaj mi donis ordonon, ke oni serĉu; kaj oni trovis, ke tiu urbo de malproksima tempo ribeladis kontraŭ la reĝoj, kaj tumultoj kaj defaloj estis farataj en ĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'ke potencaj reĝoj estis en Jerusalem kaj posedis la tutan transriveran regionon, kaj tributo, impostoj, kaj jarpagoj estis donataj al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Tial agu laŭ ĉi tiu ordono: malhelpu tiujn homojn en ilia laborado, ke la urbo ne estu rekonstruata, ĝis estos donita ordono de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Kaj estu singardaj, ke vi ne estu malatentaj en tio, por ke ne naskiĝu granda malprofito por la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Kiam ĉi tiu letero de la reĝo Artaĥŝaŝt estis tralegita antaŭ Reĥum, la skribisto Ŝimŝaj, kaj iliaj kunuloj, ili tuj iris en Jerusalemon al la Judoj kaj haltigis ilian laboradon per forta mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Tiam ĉesiĝis la laborado ĉe la domo de Dio en Jerusalem; kaj tiu stato daŭris ĝis la dua jaro de reĝado de Dario, reĝo de Persujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Kaj la profetoj, Ĥagaj, la profeto, kaj Zeĥarja, filo de Ido, profetis pri la Judoj, kiuj estis en Judujo kaj Jerusalem, en la nomo de Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Tiam leviĝis Zerubabel, filo de Ŝealtiel, kaj Jeŝua, filo de Jocadak, kaj komencis konstrui la domon de Dio en Jerusalem, kaj kun ili estis la profetoj de Dio, kiuj fortigadis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'En tiu tempo venis al ili Tatnaj, la estro de la transrivera regiono, kaj Ŝetar-Boznaj, kaj iliaj kunuloj, kaj tiele diris al ili: Kiu permesis al vi konstrui ĉi tiun domon kaj starigi ĉi tiujn murojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Tiam ni diris al ili, kiaj estis la nomoj de tiuj homoj, kiuj konstruis tiun konstruaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Sed la okulo de ilia Dio estis super la plejaĝuloj de la Judoj, kaj ili ne estis malhelpataj, ĝis la afero estis raportita al Dario kaj ĝis revenis decido pri tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Jen estas la enhavo de la letero, kiun sendis Tatnaj, la estro de la transrivera regiono, kaj Ŝetar-Boznaj, kun siaj kunuloj la Afarseĥanoj, kiuj estis en la transrivera regiono, al la reĝo Dario;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'la raporto, kiun ili sendis al li, havis la sekvantan tekston: Al la reĝo Dario plenan pacon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Estu sciate al la reĝo, ke ni iris en la Judan landon, al la domo de la granda Dio; ĝi estas konstruata el grandaj ŝtonoj, kaj trabojn oni enmetas en la murojn, kaj la laboro estas farata vigle kaj sukcesas en iliaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Tiam ni demandis tiujn plenaĝulojn, kaj diris al ili: Kiu donis al vi la permeson konstrui ĉi tiun domon kaj starigi ĉi tiujn murojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Kaj krom tio ni demandis pri iliaj nomoj, por raporti al vi, kaj skribi la nomojn de tiuj homoj, kiuj estas iliaj ĉefoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Per la sekvantaj vortoj ili respondis al ni kaj diris: Ni estas servantoj de Dio de la ĉielo kaj de la tero, kaj ni konstruas la domon, kiu estis konstruita antaŭ multe da jaroj, kaj granda reĝo de Izrael konstruis ĝin kaj finis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Sed kiam niaj patroj kolerigis Dion de la ĉielo, Li transdonis ilin en la manon de Nebukadnecar, reĝo de Babel, la Ĥaldeo; kaj tiun domon li detruis, kaj la popolon li transloĝigis en Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Sed en la unua jaro de Ciro, reĝo de Babel, la reĝo Ciro donis permeson rekonstrui ĉi tiun domon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Eĉ la vazojn de la domo de Dio, la orajn kaj arĝentajn, kiujn Nebukadnecar elportis el la templo de Jerusalem kaj forportis en la templon de Babel, ilin la reĝo Ciro elportis el la templo de Babel, kaj oni transdonis ilin al Ŝeŝbacar, kiun li starigis kiel regionestron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'kaj li diris al li: Prenu ĉi tiujn vazojn, iru, kaj forportu ilin en la templon de Jerusalem, kaj la domo de Dio estu konstruata sur sia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Tiam venis tiu Ŝeŝbacar kaj metis la fundamenton por la domo de Dio en Jerusalem; kaj de tiu tempo ĝis nun ĝi estas konstruata, kaj ĝi ankoraŭ ne estas finita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Tial, se plaĉas al la reĝo, oni serĉu en la domo de la reĝaj trezoroj tie en Babel, ĉu efektive la reĝo Ciro donis permeson konstrui ĉi tiun domon de Dio en Jerusalem; kaj la volon de la reĝo pri tio oni sendu al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Tiam la reĝo Dario ordonis, ke oni serĉu en la domo de dokumentoj, kie la trezoroj estis deponitaj, en Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'Kaj oni trovis en Aĥmeta, la reĝa kastelo en la Meda lando, unu skribrulaĵon, en kiu estis skribita la sekvanta pormemoraĵo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'En la unua jaro de la reĝo Ciro, la reĝo Ciro donis ordonon: Pri la domo de Dio en Jerusalem, estu konstruata domo, loko, kie oni alportas oferojn, kaj fortikaj fundamentoj por ĝi estu starigitaj; la alto de la domo estu sesdek ulnoj, ĝia larĝo estu sesdek ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'Da vicoj el grandaj ŝtonoj estu tri, kaj unu vico el ligno; la elspezoj estu donataj el la reĝa domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Ankaŭ la vazojn de la domo de Dio, orajn kaj arĝentajn, kiujn Nebukadnecar elportis el la templo de Jerusalem kaj forportis en Babelon, oni redonu, kaj ili iru en la templon de Jerusalem sur sian lokon kaj estu lokitaj en la domo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Tial Tatnaj, la estro de la transrivera regiono, Ŝetar-Boznaj, kaj iliaj kunuloj, la Afarseĥanoj, kiuj estas en la transrivera regiono, foriĝu de tie;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'permesu al ili labori ĉe la domo de Dio; la regionestro de Judujo kaj la plejaĝuloj de la Judoj konstruu tiun domon de Dio sur ĝia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Kaj de mi estas donata ordono pri tio, kio devas esti farata al la plejaĝuloj de la Judoj por la konstruado de tiu domo: el la apartenaĵo de la reĝo, el la transriveraj impostoj oni tuj donu la elspezojn al tiuj homoj, por ke la laborado ne haltu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'Kaj tiom estos necese da bovoj, ŝafoj, aŭ ŝafidoj por bruloferoj por Dio de la ĉielo, da tritiko, salo, vino, oleo, kiel diros la pastroj en Jerusalem, oni donadu al ili ĉiutage sen halto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'por ke ili alportadu agrablodoran oferon al la Dio de la ĉielo, kaj por ke ili preĝu pri la vivo de la reĝo kaj de liaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'De mi estas donata la ordono, ke se iu homo ŝanĝos ĉi tiun decidon, oni elprenu trabon el lia domo, kaj li estu levita kaj alnajlita al ĝi, kaj lia domo pro tio estu ruinigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Kaj Dio, kiu loĝigis tie Sian nomon, faligu ĉiun reĝon kaj popolon, kiu etendus sian manon, por ŝanĝi ĉi tion, por fari ion malutilan al tiu domo de Dio en Jerusalem. Mi, Dario, donis la ordonon; ĝi estu tuj plenumita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Tiam Tatnaj, la estro de la transrivera regiono, Ŝetar-Boznaj, kaj iliaj kunuloj komencis tuj agadi konforme al tio, kion ordonis la reĝo Dario.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'Kaj la plejaĝuloj de la Judoj konstruis kun sukceso, konforme al la profetado de Ĥagaj, la profeto, kaj de Zeĥarja, filo de Ido. Kaj ili konstruis kaj finis laŭ la volo de Dio de Izrael, kaj laŭ la volo de Ciro, de Dario, kaj de Artaĥŝaŝt, reĝoj de Persujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'Kaj oni finis la domon en la tria tago de la monato Adar, en la sesa jaro de reĝado de la reĝo Dario.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Kaj la Izraelidoj, la pastroj, la Levidoj, kaj la aliaj revenintoj el la kaptiteco faris kun ĝojo la sanktigon de tiu domo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'Kaj oni alportis ĉe la sanktigo de tiu domo de Dio: cent bovojn, ducent ŝafojn, kvarcent ŝafidojn, kaj dek du pekoferajn kaprojn pro la tuta Izrael, laŭ la nombro de la triboj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Kaj oni starigis la pastrojn laŭ iliaj ordoj, kaj la Levidojn laŭ iliaj vicoj, por la servado al Dio en Jerusalem, kiel estas preskribite en la libro de Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Kaj la revenintoj el la kaptiteco faris Paskon en la dek-kvara tago de la unua monato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Ĉar la pastroj kaj la Levidoj purigis sin ĉiuj kiel unu homo; kaj ili buĉis Paskajn ŝafidojn por ĉiuj revenintoj el la kaptiteco, por siaj fratoj, la pastroj, kaj por si.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Kaj manĝis la Izraelidoj, kiuj revenis el la kaptiteco, kaj ĉiuj, kiuj apartigis sin de la malpureco de la nacioj de la tero, por turni sin al la Eternulo, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'Kaj ili en ĝojo solenis la feston de macoj dum sep tagoj; ĉar la Eternulo ĝojigis ilin, kaj turnis al ili la koron de la reĝo de Asirio, por ke li fortigu iliajn manojn ĉe la laborado koncerne la domon de Dio, la Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Post tiuj okazintaĵoj, dum la reĝado de Artaĥŝast, reĝo de Persujo, el Babel iris Ezra, filo de Seraja, filo de Azarja, filo de Ĥilkija,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'filo de Ŝalum, filo de Cadok, filo de Aĥitub,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'filo de Amarja, filo de Azarja, filo de Merajot,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'filo de Zeraĥja, filo de Uzi, filo de Buki,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'filo de Abiŝua, filo de Pineĥas, filo de Eleazar, filo de Aaron, la ĉefpastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'Tiu Ezra iris el Babel. Li estis lerta scienculo koncerne la instruon de Moseo, kiun donis la Eternulo, Dio de Izrael. Kaj la reĝo donis al li ĉion laŭ lia deziro, ĉar la mano de la Eternulo, lia Dio, estis super li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Ankaŭ kelkaj el la Izraelidoj, el la pastroj, el la Levidoj, el la kantistoj, el la pordegistoj, kaj el la Netinoj iris en Jerusalemon en la sepa jaro de la reĝo Artaĥŝast.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'Kaj li venis en Jerusalemon en la kvina monato, en la sepa jaro de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Ĉar en la unua tago de la unua monato estis la komenco de la irado el Babel, kaj en la unua tago de la kvina monato li venis en Jerusalemon, ĉar la mano de lia Dio favore estis super li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Ĉar Ezra pretigis sian koron, por studi la instruon de la Eternulo kaj plenumi ĝin, kaj por instrui en Izrael leĝojn kaj ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Kaj jen estas la teksto de la letero, kiun la reĝo Artaĥŝast donis al Ezra, la pastro, la scienculo, kiu instruis la vortojn de la ordonoj de la Eternulo kaj Liajn leĝojn pri Izrael:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, 'Artaĥŝast, reĝo de la reĝoj, al Ezra, pastro, kaj scienculo pri la leĝoj de Dio de la ĉielo, pacon kaj saluton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'De mi estas ordonite, ke en mia regno ĉiu el la popolo de Izrael kaj el ĝiaj pastroj kaj Levidoj, kiu volas iri en Jerusalemon, iru kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Ĉar vi estas sendata de la reĝo kaj de liaj sep konsilistoj, por pririgardi Judujon kaj Jerusalemon laŭ la en via mano troviĝanta leĝo de via Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'kaj por tien forporti la arĝenton kaj oron, kiun la reĝo kaj liaj konsilistoj oferis al Dio de Izrael, kies loĝejo estas en Jerusalem,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'kaj la tutan arĝenton kaj oron, kiun vi akiros en la tuta provinco de Babel, kune kun la memvolaj donacoj de la popolo kaj de la pastroj, kiuj oferos por la domo de sia Dio, kiu estas en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'Aĉetu tuj pro tiu mono bovojn, ŝafojn, kaj ŝafidojn, kaj la al tio apartenantajn farunoferojn kaj verŝoferojn, kaj alportu ilin sur la altaron de la domo de via Dio en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Kaj kion vi kaj viaj fratoj trovos bona fari el la cetera arĝento kaj oro, tion laŭ la volo de via Dio faru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Kaj la vazojn, kiuj estas donitaj al vi por la servado en la domo de via Dio, prezentu antaŭ la Dio de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Kaj ĉion ceteran, kio estas necesa por la domo de via Dio, kion vi trovos bona doni, donu el la reĝa trezorejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'Kaj de mi, Artaĥŝast, la reĝo, estas farata ordono al ĉiuj trezorgardistoj trans la rivero, ke ĉio, kion postulos de vi Ezra, la pastro, instruisto de la leĝoj de Dio de la ĉielo, estu tuj plenumata,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'ĝis jena kvanto: arĝento ĝis cent kikaroj, tritiko ĝis cent kor�oj, vino ĝis cent bat�oj, ankaŭ oleo ĝis cent bat�oj, kaj salo en kvanto senlima.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Ĉio, kio estas ordonita de Dio de la ĉielo, devas esti farata tuj por la domo de Dio de la ĉielo, por ke Lia kolero ne trafu la regnon, la reĝon, aŭ liajn infanojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Kaj ni sciigas al vi, ke sur neniun el la pastroj, Levidoj, kantistoj, pordegistoj, Netinoj, aŭ servantoj ĉe tiu domo de Dio vi devas meti tributon, imposton, aŭ depagojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Kaj vi, Ezra, laŭ la saĝo, kiun via Dio donis al vi, starigu registojn kaj juĝistojn, kiuj juĝadus la tutan popolon, kiu estas trans la rivero, ĉiujn, kiuj scias la leĝojn de via Dio; kaj kiu ne scias, tiun instruu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Kaj ĉiu, kiu ne plenumos la leĝojn de via Dio aŭ la leĝojn de la reĝo, tuj estu juĝe kondamnata, ĉu al morto, ĉu al elpelo, ĉu al monpuno, ĉu al meto en malliberejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Benata estu la Eternulo, Dio de niaj patroj, kiu metis en la koron de la reĝo la ideon beligi la domon de la Eternulo en Jerusalem,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'kaj sur min turnis favoron de la reĝo kaj de liaj konsilistoj kaj de ĉiuj potencaj princoj de la reĝo. Kaj mi ricevis kuraĝon, ĉar la mano de la Eternulo, mia Dio, estis super mi; kaj mi kolektis en Izrael ĉefojn, por ke ili iru kun mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Jen estas la ĉefoj de patrodomoj kun ilia genealogio, kiuj iris kun mi el Babel en la tempo de reĝado de la reĝo Artaĥŝast:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'el la idoj de Pineĥas: Gerŝom; el la idoj de Itamar: Daniel; el la idoj de David: Ĥatuŝ;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'el la idoj de Ŝeĥanja: el la idoj de Paroŝ: Zeĥarja, kaj kun li la familianoj, viroj en la nombro de cent kvindek;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'el la idoj de Paĥat-Moab: Eljehoenaj, filo de Zeraĥja, kaj kun li ducent virseksuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'el la idoj de Ŝeĥanja: la filo de Jaĥaziel, kaj kun li tricent virseksuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'el la idoj de Adin: Ebed, filo de Jonatan, kaj kun li kvindek virseksuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'el la idoj de Elam: Jeŝaja, filo de Atalja, kaj kun li sepdek virseksuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'el la idoj de Ŝefatja: Zebadja, filo de Miĥael, kaj kun li okdek virseksuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'el la idoj de Joab: Obadja, filo de Jeĥiel, kaj kun li ducent dek ok virseksuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'el la idoj de Ŝelomit: la filo de Josifja, kaj kun li cent sesdek virseksuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'el la idoj de Bebaj: Zeĥarja, filo de Bebaj, kaj kun li dudek ok virseksuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'el la idoj de Azgad: Joĥanan, filo de Hakatan, kaj kun li cent dek virseksuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'el la idoj de Adonikam la lastaj, kaj jen estas iliaj nomoj: Elifelet, Jeiel, kaj Ŝemaja, kaj kun ili sesdek virseksuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'el la idoj de Bigvaj: Utaj kaj Zakur, kaj kun ili sepdek virseksuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Kaj mi kolektis ilin ĉe la rivero, kiu enfluas en Ahavan, kaj ni restis tie tri tagojn; kaj kiam mi pririgardis la popolon kaj la pastrojn, mi el la idoj de Levi trovis tie neniun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Tiam mi sendis Eliezeron, Arielon, Ŝemajan, Elnatanon, Jaribon, Elnatanon, Natanon, Zeĥarjan, kaj Meŝulamon, la ĉefojn, kaj Jojaribon kaj Elnatanon, la scienculojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'kaj mi donis al ili komision al Ido, la ĉefo en la loko Kasifja, kaj mi donis al ili instrukcion pri tio, kion ili devas diri al Ido, kaj al liaj fratoj, la Netinoj, en la loko Kasifja, por venigi al ni servistojn por la domo de nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Kaj ili venigis al ni, ĉar super ni estis la favora mano de nia Dio, homon saĝan el la idoj de Maĥli, filo de Levi, filo de Izrael, kaj Ŝerebjan kun liaj filoj kaj fratoj, dek ok homojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'kaj Ĥaŝabjan, kaj kun li Jeŝajan, el la idoj de Merari, kun liaj fratoj kaj iliaj filoj, dudek;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'kaj el la Netinoj, kiujn David kaj la princoj starigis por servi al la Levidoj, ducent dudek Netinojn; ĉiuj ili estis registritaj laŭ siaj nomoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Kaj mi proklamis tie faston ĉe la rivero Ahava, por ke ni humiligu nin antaŭ nia Dio, por peti de Li ĝustan vojon por ni, por niaj infanoj, kaj por nia tuta havo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Ĉar mi hontis peti de la reĝo militistojn kaj rajdistojn por defendi nin kontraŭ malamikoj sur la vojo; ĉar ni tiele diris al la reĝo: La mano de nia Dio estas bonfaranta por ĉiuj, kiuj sin turnas al Li, kaj Lia potenco kaj Lia kolero estas kontraŭ ĉiuj, kiuj Lin forlasas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Ni do fastis, kaj petis nian Dion pri tio; kaj Li aŭskultis nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Kaj mi apartigis el la ĉefaj pastroj dek du, kaj mi aligis al ili Ŝerebjan kaj Ĥaŝabjan kaj dek el iliaj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'Kaj mi pese transdonis al ili la arĝenton kaj la oron kaj la vazojn, kiuj estis donacitaj por la domo de nia Dio kaj kiujn donacis la reĝo kaj liaj konsilistoj kaj liaj princoj, kaj ĉiuj Izraelidoj, kiuj tie troviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Kaj mi pese transdonis al ili: da arĝento sescent kvindek kikarojn, da arĝentaj vazoj cent kikarojn, kaj da oro cent kikarojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'da oraj kalikoj dudek je la sumo de mil darkemonoj, kaj du vazojn el brilanta plej bona kupro, multekosta kiel oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Kaj mi diris al ili: Vi estas sanktaj al la Eternulo, kaj la vazoj estas sanktaj, ankaŭ la arĝento kaj la oro, memvole donacitaj al la Eternulo, Dio de viaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Maldormu, kaj gardu tion, ĝis vi transdonos pese al la ĉefaj pastroj, Levidoj, kaj ĉefoj de patrodomoj de Izrael en Jerusalem, en la ĉambroj de la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Kaj la pastroj kaj la Levidoj akceptis la pesitajn arĝenton, oron, kaj vazojn, por forporti en Jerusalemon en la domon de nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Kaj ni ekvojiris de la rivero Ahava en la dek-dua tago de la unua monato, por iri en Jerusalemon; kaj la mano de nia Dio estis super ni, kaj Li savis nin kontraŭ la manoj de malamikoj kaj kontraŭ insidantoj ĉe la vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'Kaj ni venis en Jerusalemon kaj restis tie dum tri tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'En la kvara tago la arĝento, oro, kaj vazoj estis transdonitaj pese en la domon de nia Dio, en la manojn de la pastro Meremot, filo de Urija, kune kun Eleazar, filo de Pineĥas, kune kun Jozabad, filo de Jeŝua, kaj Noadja, filo de Binuj, la Levidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'Ĉio estis farita laŭnombre kaj laŭpeze, kaj ĉio pesita estis tiutempe enskribita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'La forkaptitoj, kiuj revenis el la kaptiteco, alportis bruloferojn al Dio de Izrael: dek du bovojn, pro la tuta Izrael, naŭdek ses ŝafojn, sepdek sep ŝafidojn, dek du pekoferajn kaprojn, ĉion kiel bruloferon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'Kaj oni transdonis la ordonojn de la reĝo al la satrapoj de la reĝo kaj al la transriveraj regionestroj; kaj ĉi tiuj subtenis la popolon kaj la domon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Kiam ĉio tio estis finita, aliris al mi la estroj, kaj diris: La popolo Izraela kaj la pastroj kaj la Levidoj ne apartigis sin de la popoloj de la landoj koncerne iliajn abomenindaĵojn, de la Kanaanidoj, Ĥetidoj, Perizidoj, Jebusidoj, Amonidoj, Moabidoj, Egiptoj, kaj Amoridoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'ĉar ili prenis el iliaj filinoj edzinojn por si kaj por siaj filoj, kaj miksiĝis la sankta semo kun la popoloj de la landoj; kaj la mano de la eminentuloj kaj ĉefoj estis la unua en ĉi tiu malbonago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Kiam mi aŭdis tion, mi disŝiris miajn vestojn kaj mian tunikon, mi elŝiris harojn de mia kapo kaj el mia barbo, kaj mi sidis konsternite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Kaj kolektiĝis al mi ĉiuj, kiuj timis la vortojn de Dio de Izrael, pro la krimo de la forkaptitoj; kaj mi sidis konsternite ĝis la vesperofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Kaj ĉe la vesperofero mi leviĝis de mia aflikto, kaj kun disŝiritaj vestoj kaj tuniko mi stariĝis surgenue kaj etendis miajn manojn al la Eternulo, mia Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'kaj mi diris: Ho mia Dio, mi hontas, kaj ĝenas min levi mian vizaĝon al Vi, ho mia Dio; ĉar niaj malbonagoj kreskis pli alten ol nia kapo, kaj nia kulpo fariĝis granda ĝis la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'De post la tempo de niaj patroj ni estas en granda kulpo ĝis la nuna tago; pro niaj malbonagoj ni estis transdonitaj, ni kaj niaj reĝoj kaj niaj pastroj, en la manojn de la alilandaj reĝoj, sub glavon, en kaptitecon, al disrabo kaj malhonoro, kiel tio estas nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Kaj nun antaŭ momento venis pardono de la Eternulo, nia Dio, kaj Li restigis al ni saviĝintojn kaj permesis al ni alfortikiĝi sur Lia sankta loko; nia Dio donis lumon al niaj okuloj, kaj Li permesis al ni iom reviviĝi en nia sklaveco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Ni estas ja sklavoj; sed en nia sklaveco nia Dio nin ne forlasis. Kaj Li donis al ni favorkorecon de la reĝoj de Persujo, por permesi al ni reviviĝi, por konstrui la domon de nia Dio kaj restarigi ĝiajn ruinojn, kaj por doni al ni barilon en Judujo kaj Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Kaj nun kion ni diros, ho nia Dio, post tio? ĉar ni forlasis Viajn ordonojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'kiujn Vi ordonis per Viaj servantoj, la profetoj, dirante: La lando, en kiun vi venas por ekposedi ĝin, estas lando malpura pro la malpureco de la popoloj alilandaj, pro iliaj abomenindaĵoj, per kiuj ili plenigis ĝin de rando al rando en sia malpureco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'ne donu do viajn filinojn al iliaj filoj, kaj iliajn filinojn ne prenu por viaj filoj, neniam zorgu pri ilia paco kaj bonstato, por ke vi fortiĝu kaj por ke vi nutru vin per la bonaĵoj de la tero kaj por ke vi heredigu ĝin por eterne al viaj filoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Kaj post ĉio, kio trafis nin pro niaj malbonaj faroj kaj pro nia granda kulpo, kaj kiam nun Vi indulgis nin malgraŭ niaj malbonagoj kaj donis al ni tian saviĝon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'ĉu ni nun denove malobeu Viajn ordonojn, kaj boparenciĝu kun la popoloj de tiuj abomenindaĵoj? Ĉu Vi ne koleros kontraŭ ni ĝis plena ekstermo sen restigo de ia restaĵo kaj savitaĵo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Ho Eternulo, Dio de Izrael! Vi estas justa; ĉar ni restis saviĝintoj ĝis la nuna tago. Jen ni estas antaŭ Vi en nia kulpo; ni ne povas teni nin antaŭ Vi pro tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Kiam Ezra preĝis kaj faris konfeson, plorante kaj kuŝante antaŭ la domo de Dio, kolektiĝis al li el la Izraelidoj tre granda amaso, viroj, virinoj, kaj infanoj; ĉar ankaŭ la popolo tre multe ploris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Kaj ekparolis Ŝeĥanja, filo de Jeĥiel, el la idoj de Elam, kaj diris al Ezra: Ni faris krimon kontraŭ nia Dio, prenante edzinojn aligentajn el la popoloj de la lando. Tamen nun ekzistas espero por Izrael en ĉi tiu afero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Nun ni faru interligon kun nia Dio, ke laŭ la konsilo de mia sinjoro, kaj de tiuj, kiuj havas timon antaŭ la ordonoj de nia Dio, ni forigos ĉiujn virinojn kaj iliajn naskitojn, kaj estu farite konforme al la leĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Leviĝu, ĉar vi devas okupi vin pri tio, kaj ni estos kun vi; estu kuraĝa, kaj agu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Tiam Ezra leviĝis, kaj ĵurigis la ĉefajn pastrojn, la Levidojn, kaj la tutan Izraelon, ke ili agos tiel; kaj ili ĵuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Kaj Ezra leviĝis de antaŭ la domo de Dio, kaj iris al la ĉambro de Jehoĥanan, filo de Eljaŝib, kaj eniris tien. Panon li ne manĝis kaj akvon li ne trinkis, ĉar li funebris pri la krimo de la kaptitecanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Kaj oni proklamis en Judujo kaj Jerusalem al ĉiuj, kiuj venis el la kaptiteco, ke ili kolektiĝu en Jerusalem,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'kaj ke al ĉiu, kiu ne venos tien post paso de tri tagoj, laŭ decido de la estroj kaj plejaĝuloj estos anatemita lia tuta havo, kaj li estos ekskomunikita el la komunumo de la reenmigrintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Kaj kolektiĝis ĉiuj idoj de Jehuda kaj de Benjamen en Jerusalem post tri tagoj. Tio estis en la naŭa monato, en la dudeka tago de la monato. Kaj la tuta popolo sidis sur la placo antaŭ la domo de Dio, tremante pro ĉi tiu afero kaj pro pluvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Kaj leviĝis Ezra, la pastro, kaj diris al ili: Vi faris krimon, prenante aligentajn edzinojn kaj pligrandigante la kulpon de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Tial faru nun konfeson al la Eternulo, Dio de viaj patroj, kaj plenumu Lian volon: apartigu vin de la popoloj de la lando kaj de la aligentaj edzinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Kaj la tuta komunumo respondis kaj diris per laŭta voĉo: Jes, kiel vi diras, tiel estu farite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Tamen la popolo estas grandnombra, kaj la tempo nun estas pluva, kaj ni ne havas forton, por stari sur la strato; cetere tio ne estas afero de unu tago aŭ de du, ĉar ni multe pekis en tiu afero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Niaj estroj do stariĝu pro la tuta komunumo, kaj ĉiuj en niaj urboj, kiuj prenis aligentajn edzinojn, venu en difinita tempo, kaj kun ili la plejaĝuloj de ĉiu urbo kaj ĝiaj juĝistoj, ĝis oni forturnos de ni la flaman koleron de nia Dio pro tiu afero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Sed Jonatan, filo de Asahel, kaj Jaĥzeja, filo de Tikva, kontraŭstaris tion, kaj Meŝulam, kaj Ŝabtaj, la Levido, helpis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Kaj tiel faris la revenintoj el la kaptiteco. Kaj apartiĝis por tio la pastro Ezra kaj ĉefoj de patrodomoj laŭ iliaj patrodomoj, ĉiuj laŭnome; kaj ili sidiĝis en la unua tago de la deka monato, por esplori la aferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'Kaj ĝis la unua tago de la unua monato ili finis la aferon pri ĉiuj viroj, kiuj prenis aligentajn edzinojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Kaj troviĝis el la pastridoj, kiuj prenis aligentajn edzinojn, el la filoj de Jeŝua, filo de Jocadak, kaj el liaj fratoj: Maaseja, Eliezer, Jarib, kaj Gedalja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'Kaj ili donis sian manon, ke ili forigos siajn edzinojn, kaj ke ili alportos pro sia kulpo virŝafon kiel kulpoferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'Kaj el la filoj de Imer: Ĥanani kaj Zebadja;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'el la filoj de Ĥarim: Maaseja, Elija, Ŝemaja, Jeĥiel, kaj Uzija;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'el la filoj de Paŝĥur: Eljoenaj, Maaseja, Iŝmael, Netanel, Jozabad, kaj Eleasa;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'kaj el la Levidoj: Jozabad, Ŝimei, Kelaja (ankaŭ nomata Kelita), Petaĥja, Jehuda, kaj Eliezer;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'el la kantistoj: Eljaŝib; el la pordegistoj: Ŝalum, Telem, kaj Uri;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'el la Izraelidoj: el la filoj de Paroŝ: Ramja, Jizija, Malkija, Mijamin, Eleazar, Malkija, kaj Benaja;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'el la filoj de Elam: Matanja, Zeĥarja, Jeĥiel, Abdi, Jeremot, kaj Elija;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'el la filoj de Zatu: Eljoenaj, Eljaŝib, Matanja, Jeremot, Zabad, kaj Aziza;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'el la filoj de Bebaj: Jehoĥanan, Ĥananja, Zabaj, Atlaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'el la filoj de Bani: Meŝulam, Maluĥ, Adaja, Jaŝub, Ŝeal, kaj Ramot;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'el la filoj de Paĥat-Moab: Adna, Kelal, Benaja, Maaseja, Matanja, Becalel, Binuj, kaj Manase;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'el la filoj de Ĥarim: Eliezer, Jiŝija, Malkija, Ŝemaja, Ŝimeon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamen, Maluĥ, Ŝemarja;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'el la filoj de Ĥaŝum: Matnaj, Matata, Zabad, Elifelet, Jeremaj, Manase, Ŝimei;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'el la filoj de Bani: Maadaj, Amram, Uel,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benaja, Bedja, Keluhu,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Vanja, Meremot, Eljaŝib,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Matanja, Matnaj, Jaasaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'Bani, Binuj, Ŝimei,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'Ŝelemja, Natan, Adaja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Maĥnadbaj, Ŝaŝaj, Ŝaraj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Azarel, Ŝelemja, Ŝemarja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Ŝalum, Amarja, Jozef;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'el la filoj de Nebo: Jeiel, Matitja, Zabad, Zebina, Jadaj, Joel, Benaja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Ĉiuj tiuj prenis edzinojn aligentajn; kelkaj el tiuj edzinoj naskis infanojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Vortoj de Neĥemja, filo de Ĥaĥalja. En la monato Kislev, en la dudeka jaro, mi estis en la kastelurbo Ŝuŝan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'Kaj venis Ĥanani, unu el miaj fratoj, li kaj kelkaj viroj el Judujo. Kaj mi demandis lin pri la Judoj, kiuj saviĝis kaj restis el la forkaptitaro, kaj pri Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Kaj ili diris al mi: La restintoj, kiuj restis el la forkaptitaro, troviĝas tie en la lando en granda mizero kaj malhonoro; kaj la murego de Jerusalem estas detruita, kaj ĝiaj pordegoj estas forbruligitaj per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Kiam mi aŭdis tiujn vortojn, mi sidiĝis kaj ekploris, kaj funebris dum kelke da tagoj; kaj mi fastis kaj preĝis antaŭ Dio de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'Kaj mi diris: Mi petas Vin, ho Eternulo, Dio de la ĉielo, Dio granda kaj timinda, kiu konservas la interligon kaj favorkorecon al Liaj amantoj kaj al la plenumantoj de Liaj ordonoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Via orelo estu atenta, kaj Viaj okuloj estu malfermitaj, por aŭskulti la preĝon de Via servanto, per kiu mi preĝas antaŭ Vi nun tage kaj nokte pri la Izraelidoj, Viaj servantoj, dum mi faras konfeson pri la pekoj de la Izraelidoj, kiujn ni pekis antaŭ Vi; mi kaj la domo de mia patro, ni pekis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Ni forte pekis antaŭ Vi, kaj ni ne plenumis la ordonojn kaj la leĝojn kaj la decidojn, kiujn Vi ordonis al Moseo, Via servanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Sed volu rememori la vorton, kiun Vi eldiris al Via servanto Moseo, nome: Se vi pekos, Mi disĵetos vin inter la popolojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'sed se vi returnos vin al Mi kaj konservos Miajn ordonojn kaj plenumos ilin, tiam se viaj forpelitoj eĉ estus ĉe la rando de la ĉielo, Mi eĉ de tie kolektos ilin, kaj venigos ilin sur la lokon, kiun Mi elektis, por loĝigi tie Mian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Ili estas ja Viaj servantoj, kaj Via popolo, kiun Vi liberigis per Via granda forto kaj per Via potenca mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Mi petas, ho Sinjoro, Via orelo estu atenta al la preĝo de Via servanto, kaj al la preĝo de Viaj servantoj, kiuj deziras timi Vian nomon; kaj donu sukceson al Via servanto hodiaŭ, kaj akirigu al li favorkorecon antaŭ ĉi tiu homo. (Mi estis vinverŝisto ĉe la reĝo.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'En la monato Nisan, en la dudeka jaro de la reĝo Artaĥŝast, antaŭ li staris vino. Kaj mi prenis la vinon kaj donis al la reĝo; kaj ĝis tiam mi ne estis malgaja antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Kaj la reĝo diris al mi: Kial vi aspektas malbone, kvankam vi ne estas malsana? tio certe estas doloro de koro. Kaj mi forte ektimis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'kaj mi diris al la reĝo: La reĝo vivu eterne; kiel mi povas ne aspekti malbone, kiam la urbo, kiu estas la tomboloko de miaj patroj, estas dezertigita, kaj ĝiaj pordegoj estas forbruligitaj per fajro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Kaj la reĝo diris al mi: Kion do vi deziras? Tiam mi preĝis al Dio de la ĉielo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'kaj diris al la reĝo: Se al la reĝo plaĉas, kaj se via sklavo havas vian favoron, permesu al mi veturi en Judujon, en la urbon, kie troviĝas la tomboj de miaj patroj, kaj konstrui ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Kaj la reĝo diris al mi (la reĝino sidis apud li): Kiel longe daŭros via veturado? kaj kiam vi revenos? Kaj la reĝo bonvolis forliberigi min, kaj mi difinis al li templimon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Kaj mi diris al la reĝo: Se al la reĝo plaĉas, oni donu al mi leterojn al la transriveraj regionestroj, ke ili permesu al mi trairi, ĝis mi venos en Judujon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'kaj ankaŭ leteron al Asaf, la gardisto de la reĝa arbaro, ke li donu al mi arbojn por tegi la pordegojn de la kastelo ĉe la templo, kaj por la murego de la urbo, kaj por la domo, en kiu mi loĝos. Kaj la reĝo donis al mi, ĉar super mi estis la favora mano de mia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Kaj mi venis al la transriveraj regionestroj, kaj mi donis al ili la leterojn de la reĝo. Kaj la reĝo sendis kun mi oficirojn kaj rajdistojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Kiam tion aŭdis Sanbalat, la Ĥoronano, kaj Tobija, la sklavo Amonida, ili havis grandan ĉagrenon, ke venis homo, por zorgi pri la bono de la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Kaj mi venis en Jerusalemon. Kaj restinte tie dum tri tagoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'mi leviĝis nokte kune kun nemultaj homoj, kiuj estis kun mi; mi al neniu ion diris pri tio, kion mia Dio inspiris al mi fari por Jerusalem; neniu besto estis kun mi, krom tiu, sur kiu mi rajdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Kaj mi trarajdis nokte tra la Pordego de la Valo, al la Fonto de la Drako kaj al la Pordego de Sterko; mi rigardis la muregojn de Jerusalem, kiel detruitaj ili estas, kaj ĝiajn pordegojn, kiel ili estas forbruligitaj per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Kaj mi alrajdis al la Pordego de la Fonto kaj al la Reĝa Lageto; sed tie ne estis sufiĉe da spaco, ke povu trairi la besto, kiu estis sub mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Kaj mi leviĝis nokte laŭ la torento kaj pririgardis la muregon, kaj, trarajdinte denove tra la Pordego de la Valo, mi revenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Kaj la estroj ne sciis, kien mi iris kaj kion mi faras; nek al la Judoj, nek al la pastroj, nek al la eminentuloj, nek al la estroj, nek al la ceteraj plenumantoj de la laboroj mi ion diris ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Kaj mi diris al ili: Vi vidas la mizeron, en kiu ni troviĝas, kiel Jerusalem estas dezertigita kaj ĝiaj pordegoj estas forbruligitaj per fajro; ni iru kaj konstruu la muregon de Jerusalem, ke ni ne estu plu en malhonoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Kaj mi rakontis al ili pri la mano de mia Dio, kiu favore estis super mi, ankaŭ la vortojn de la reĝo, kiujn li diris al mi. Kaj ili diris: Ni leviĝu kaj konstruu; kaj iliaj manoj fortiĝis por la bono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Kiam tion aŭdis Sanbalat, la Ĥoronano, kaj Tobija, la sklavo Amonida, kaj Geŝem, la Arabo, ili ridis pri ni kaj rigardis nin malestime, kaj diris: Kio estas tiu afero, kiun vi faras? ĉu ne kontraŭ la reĝo vi ribelas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Kaj mi respondis al ili, kaj diris al ili: Dio de la ĉielo donos al ni sukceson, kaj ni, Liaj servantoj, leviĝos kaj konstruos; sed vi havas nenian parton nek rajton nek memoron en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Kaj leviĝis la ĉefpastro Eljaŝib, kaj liaj fratoj, la pastroj, kaj konstruis la Pordegon de Ŝafoj; ili sanktigis ĝin kaj starigis ĝiajn pordojn, ili sanktigis ĝis la turo Mea, ĝis la turo Ĥananel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Apud li konstruis la loĝantoj de Jeriĥo, apud ili konstruis Zakur, filo de Imri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'La Pordegon de Fiŝoj konstruis la loĝantoj de Senaa; ili tegis ĝin, kaj starigis ĝiajn pordojn, serurojn, kaj riglilojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Apud ili konstruis Meremot, filo de Urija, filo de Hakoc; apud ili konstruis Meŝulam, filo de Bereĥja, filo de Meŝezabel; apud ili konstruis Cadok, filo de Baana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Apud ili konstruis la Tekoaanoj; tamen iliaj eminentuloj ne metis sian kolon sub laboradon por sia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'La Malnovan Pordegon konstruis Jojada, filo de Paseaĥ, kaj Meŝulam, filo de Besodja; ili tegis ĝin, kaj starigis ĝiajn pordojn, ĝiajn serurojn, kaj ĝiajn riglilojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Apud ili konstruis Melatja, la Gibeonano, kaj Jadon, la Meronotano, la loĝantoj de Gibeon kaj de Micpa, ĝis la seĝo de la transrivera regionestro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Apud li konstruis Uziel, filo de Ĥarhaja, fandisto; apud li konstruis Ĥananja, filo de ŝmiraĵisto. Kaj ili restarigis Jerusalemon ĝis la Larĝa Murego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Apud ili konstruis Refaja, filo de Ĥur, estro de duondistrikto de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Apud ili kaj kontraŭ sia domo konstruis Jedaja, filo de Ĥarumaf; apud li konstruis Ĥatuŝ, filo de Ĥaŝabneja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Alian parton konstruis Malkija, filo de Ĥarim, kaj Ĥaŝub, filo de Paĥat-Moab; ankaŭ la Turon de la Fornoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Apude konstruis Ŝalum, filo de Haloĥeŝ, estro de duondistrikto de Jerusalem, li kaj liaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'La Pordegon de la Valo konstruis Ĥanun kaj la loĝantoj de Zanoaĥ; ili konstruis ĝin, kaj starigis ĝiajn pordojn, ĝiajn serurojn, kaj ĝiajn riglilojn, kaj mil ulnojn de la murego ĝis la Pordego de Sterko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'La Pordegon de Sterko konstruis Malkija, filo de Reĥab, estro de la distrikto de Bet-Kerem; li konstruis ĝin, kaj starigis ĝiajn pordojn, serurojn, kaj riglilojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'La Pordegon de la Fonto konstruis Ŝalun, filo de Kol-Ĥoze, estro de la distrikto de Micpa; li konstruis ĝin kaj tegis ĝin, kaj starigis ĝiajn pordojn, serurojn, kaj riglilojn; ankaŭ la muregon ĉe la lageto Ŝelaĥ de la reĝa ĝardeno kaj ĝis la ŝtupoj, kiuj iras malsupren de la urbo de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Post li konstruis Neĥemja, filo de Azbuk, estro de duondistrikto de Bet-Cur, ĝis la loko kontraŭ la tomboj de David kaj ĝis la farita lageto kaj ĝis la Domo de Herooj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Post li konstruis la Levidoj: Reĥum, filo de Bani; apude konstruis Ĥaŝabja, estro de duondistrikto de Keila, por sia distrikto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Post li konstruis iliaj fratoj, Bavaj, filo de Ĥenadad, estro de duondistrikto de Keila.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Apud li konstruis Ezer, filo de Jeŝua, estro de Micpa, duan parton, ĉe la angulo, kontraŭ la loko, kie oni supreniras al la armilejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Post li vigle konstruis Baruĥ, filo de Zakaj, alian parton, de la angulo ĝis la pordo de la domo de Eljaŝib, la ĉefpastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Post li konstruis Meremot, filo de Urija, filo de Hakoc, alian parton, de la pordo de la domo de Eljaŝib ĝis la fino de la domo de Eljaŝib.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Post li konstruis la pastroj, kiuj loĝis en la ĉirkaŭaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Post ili konstruis Benjamen kaj Ĥaŝub, kontraŭ sia domo; post ili konstruis Azarja, filo de Maaseja, filo de Ananja, apud sia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Post li konstruis Binuj, filo de Ĥenadad, alian parton, de la domo de Azarja ĝis la angulo kaj la rando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Palal, filo de Uzaj, de kontraŭ la angulo kaj la turo, kiu elstaras el la supra reĝa domo, apud la korto de malliberejo. Post li Pedaja, filo de Paroŝ');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, '(La Netinoj loĝis en Ofel.) ĝis kontraŭ la Pordego de la Akvo oriente, kaj ĝis la elstaranta turo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Poste konstruis la Tekoaanoj, alian parton, de kontraŭ la granda elstaranta turo ĝis la muro de Ofel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'De post la Pordego de la Ĉevaloj konstruis la pastroj, ĉiu kontraŭ sia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Poste konstruis Cadok, filo de Imer, kontraŭ sia domo; post li konstruis Ŝemaja, filo de Ŝeĥanja, gardisto de la Orienta Pordego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Post li konstruis Ĥananja, filo de Ŝelemja, kaj Ĥanun, sesa filo de Calaf, alian parton. Post li konstruis Meŝulam, filo de Bereĥja, kontraŭ sia ĉambro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Post li konstruis Malkija, filo de fandisto, ĝis la domo de la Netinoj kaj de la butikistoj, kontraŭ la Pordego de Depono kaj ĝis la tegmenta ĉambro de la angulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'Inter la tegmenta ĉambro de la angulo kaj la Pordego de Ŝafoj konstruis la fandistoj kaj la butikistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Kiam Sanbalat aŭdis, ke ni konstruas la muregon, li koleris kaj havis grandan ĉagrenon, kaj li mokis la Judojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'Kaj li parolis antaŭ siaj fratoj kaj antaŭ la militistoj de Samario, kaj diris: Kion faras tiuj senfortaj Judoj? ĉu oni tion permesos al ili? ĉu efektive ili alportados oferojn? ĉu ili iam finos? ĉu ili revivigos la ŝtonojn, kiuj fariĝis amaso da rubo kaj estas difektitaj de brulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Kaj Tobija, la Amonido, kiu estis apud li, diris: Eĉ tio, kion ili konstruas, estas tia, ke se venos vulpo, ĝi detruos ilian ŝtonan muregon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Aŭskultu, ho nia Dio, en kia malestimo ni troviĝas; reĵetu ilian mokadon sur ilian kapon, kaj elmetu ilin al prirabado en lando de kaptiteco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'ne kovru ilian malbonagon, kaj ilia peko ne elviŝiĝu antaŭ Vi; ĉar ili ĉagrenis la konstruantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Ni tamen konstruis la muregon, kaj la tuta murego estis jam kunmetita ĝis duono; kaj la popolo laboris kuraĝe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Kiam Sanbalat kaj Tobija kaj la Araboj kaj la Amonidoj kaj la Aŝdodanoj aŭdis, ke la muregoj de Jerusalem estas riparataj kaj ke la breĉoj komencis esti fermataj, ili tre ekkoleris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Kaj ili faris interkonsenton, ke ili ĉiuj kune iru milite kontraŭ Jerusalemon kaj faru al ĝi malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Sed ni preĝis al nia Dio, kaj ni starigis pro ili gardon tage kaj nokte kontraŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'La Judoj diris: Malgrandiĝis la forto de la portistoj, kaj da rubo estas multe; kaj ni ne povas konstrui la muregon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Kaj niaj malamikoj diris: Ili ne scios kaj ne vidos, ĝis ni venos en ilian mezon kaj mortigos ilin kaj ĉesigos la laboradon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Kiam la Judoj, kiuj loĝis apud ili, venadis, kaj diradis al ni, dekfoje, el ĉiuj lokoj: Revenu al ni,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'tiam mi starigis malsupre sur la lokoj malantaŭ la murego, sur la nekovritaj lokoj, mi starigis la popolon laŭfamilie, kun iliaj glavoj, lancoj, kaj pafarkoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Kaj mi pririgardis, kaj mi stariĝis, kaj diris al la eminentuloj kaj al la estroj kaj al la cetera popolo: Ne timu ilin; memoru pri la Sinjoro, la granda kaj timinda, kaj batalu por viaj fratoj, viaj filoj, viaj filinoj, viaj edzinoj, kaj viaj domoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'Kiam niaj malamikoj aŭdis, ke ni scias, tiam Dio detruis ilian intencon, kaj ni ĉiuj revenis al la murego, ĉiu al sia laboro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Kaj de post tiu tago duono de miaj junuloj faradis la laboron, kaj duono tenis lancojn, ŝildojn, pafarkojn, kaj kirasojn; kaj la estroj troviĝadis malantaŭ la tuta domo de Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Unuj konstruis la muregon, kaj aliaj portis la ŝarĝojn, kiujn ili metis sur sin; per unu mano ĉiu faris la laboron, kaj en la dua mano li tenis batalilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'La konstruantoj ĉiuj havis sian glavon alligitan al siaj lumboj, kaj tiamaniere ili konstruis; kaj la trumpetisto estis apud mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'Kaj mi diris al la eminentuloj kaj al la estroj kaj al la cetera popolo: La laboro estas granda kaj vasta, kaj ni estas disigitaj sur la murego, malproksime unu de la alia;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'tial se de iu loko vi aŭdos la sonon de trumpeto, tien kolektiĝu al ni; nia Dio batalos por ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'Tiamaniere ni faradis la laboron; kaj duono de ili tenis lancojn de la leviĝo de la ĉielruĝo ĝis la apero de la steloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'Kaj mi ankaŭ diris en tiu tempo al la popolo, ke ĉiu kun sia knabo noktu en Jerusalem, por ke ili estu por ni nokte kiel gardo, kaj tage ili laboru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'Kaj nek mi, nek miaj fratoj, nek miaj knaboj, nek la gardistoj, kiuj estis malantaŭ mi, neniu el ni deprenis de si siajn vestojn; nur ĉiu aparte estis sendata, por sin bani.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Kaj la popolo kaj iliaj edzinoj komencis forte krii kontraŭ siaj fratoj, la Judoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Estis tiaj, kiuj parolis: Estas multe da ni kaj da niaj filoj kaj filinoj; ni prenu al ni grenon kaj manĝu, por ke ni vivu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Aliaj parolis: Niajn kampojn, niajn vinberĝardenojn, kaj niajn domojn ni donas proprunte, por ke ni akiru grenon kontraŭ malsato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Aliaj parolis: Ni pruntas monon por impostoj por la reĝo, donante garantiaĵe niajn kampojn kaj vinberĝardenojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'sed kiel la korpo de niaj fratoj, tia estas nia korpo, kiel iliaj infanoj, tiaj estas niaj infanoj; tamen jen ni devas humile servigi niajn filojn kaj niajn filinojn, kaj el niaj filinoj kelkaj jam estas humiligitaj. Ni ne havas forton en niaj manoj, kaj niaj kampoj kaj vinberĝardenoj apartenas al aliaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Kaj tio forte min ĉagrenis, kiam mi aŭdis ilian kriadon kaj tiujn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Sed mia koro donis al mi konsilon, kaj mi faris severan riproĉon al la eminentuloj kaj al la estroj, kaj diris al ili: Vi prenas procentegon de viaj fratoj! Kaj mi kunvokis kontraŭ ili grandan kunvenon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'Kaj mi diris al ili: Ni elaĉetis niajn fratojn, la Judojn, kiuj estis venditaj al la nacioj, kiom ni povis; dume vi volas vendi viajn fratojn, kaj ili estas vendataj al ni! Ili silentis kaj trovis nenion por respondi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Kaj mi diris: Ne bona estas tio, kion vi faras. Ĉu vi ne devas konduti kun timo antaŭ nia Dio, por eviti malhonoron de la flanko de la nacioj, niaj malamikoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Ankaŭ mi kaj miaj fratoj kaj miaj junuloj donis al ili prunte monon kaj grenon; ni malŝuldigu al ili tiun ŝuldon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Redonu do al ili hodiaŭ iliajn kampojn, vinberĝardenojn, olivĝardenojn, kaj domojn, kaj la procenton pro la mono, la greno, la mosto, kaj la oleo, kiujn vi pruntis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Kaj ili diris: Ni redonos, kaj ni ne postulos de ili; ni agos tiel, kiel vi diras. Kaj mi alvokis la pastrojn, kaj mi prenis de ili ĵuron, ke ili tiel agos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Kaj mi elskuis mian baskon, kaj diris: Tiele Dio elskuu el lia domo kaj el lia akiritaĵo ĉiun homon, kiu ne plenumos tiun vorton; tiele li estu elskuita kaj senhava. Kaj la tuta komunumo diris: Amen; kaj oni gloris la Eternulon. Kaj la popolo agis tiele.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Krom tio, de post la tago, kiam al mi estis ordonite esti ilia regionestro en la Juda lando, de la dudeka jaro ĝis la tridek-dua jaro de la reĝo Artaĥŝast, en la daŭro de dek du jaroj, mi kun miaj fratoj ne manĝis la panon de regionestro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'La antaŭaj regionestroj, kiuj estis antaŭ mi, ŝarĝadis la popolon, kaj prenadis de ili panon kaj vinon, krom kvardek sikloj da arĝento; eĉ iliaj junuloj regis super la popolo. Sed mi ne agis tiel, pro timo antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Mi partoprenis ankaŭ en la laborado ĉe tiu murego; kaj kampon ni ne aĉetis; kaj ĉiuj miaj junuloj kolektiĝadis tie al la laboro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Ĉe mia tablo estadis po cent kvindek homoj da Judoj kaj estroj, kaj ankaŭ da tiuj, kiuj venis al ni el la nacioj, kiuj estas ĉirkaŭ ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Preparataj estis por unu tago: unu bovo, ses plej bonaj ŝafoj, kaj ankaŭ birdoj estis preparataj ĉe mi; kaj en la daŭro de dek tagoj estis uzata tre multe da vino. Malgraŭ tio mi ne postulis panon de regionestro, ĉar la popolo estis ŝarĝita de malfacila laboro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Rememoru pri mi al bono, ho mia Dio, ĉion, kion mi faris por ĉi tiu popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Kiam Sanbalat, Tobija, la Arabo Geŝem, kaj niaj ceteraj malamikoj aŭdis, ke mi rekonstruis la muregon kaj ke ne restis en ĝi difektoj (kvankam ĝis tiu tempo mi ankoraŭ ne starigis pordojn en la pordegoj),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'tiam Sanbalat kaj Geŝem sendis, por diri al mi: Venu, ni kune kunvenu en la vilaĝoj de la valo Ono. Ili intencis fari al mi malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Sed mi sendis al ili senditojn, por diri: Mi faras grandan laboron, kaj mi ne povas iri; kial ĉesiĝu la laborado, kiam mi ĝin forlasos kaj iros al vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Kaj ili sendis al mi la saman proponon kvar fojojn, kaj mi respondis tion saman.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Kaj Sanbalat sendis al mi kun la sama propono la kvinan fojon sian junulon, kiu havis en sia mano nefermitan leteron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'En ĝi estis skribite: Inter la nacioj iras la famo, kaj Geŝem diras, ke vi kaj la Judoj intencas defali; por tio vi konstruas la muregon; kaj laŭ tiu famo vi volas esti ilia reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Ankaŭ profetojn vi starigis, por ke ili prediku pri vi en Jerusalem, dirante: Estas reĝo en Judujo. Nun la famo pri tio venos al la reĝo; venu do, ke ni kune interkonsiliĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Sed mi sendis al li, por diri: Nenio fariĝis el tio, kion vi diras; vi mem tion elpensis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Ili ĉiuj ja timigis nin, pensante: Ili ellasos el siaj manoj la laboron, kaj ĝi ne estos farata. Sed nun fortiĝu miaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Kaj mi venis en la domon de Ŝemaja, filo de Delaja, filo de Mehetabel; li sin enŝlosis. Kaj li diris: Ni iru kune en la domon de Dio, en la mezon de la templo, kaj ni ŝlosu la pordojn de la templo; ĉar oni venos, por mortigi vin, en la nokto oni venos, por mortigi vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Sed mi diris: Ĉu tia homo, kiel mi, forkuru? ĉu tia, kiel mi, iru en la templon, por konservi la vivon? mi ne iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Mi komprenis, ke ne Dio lin sendis; ĉar la profetaĵon li eldiris pri mi pro tio, ke Tobija kaj Sanbalat lin subaĉetis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Li estis subaĉetita, por ke mi timu, por ke mi agu tiel kaj peku. Tio donus al ili pretekston por malbona famo, por ke ili min malhonoru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Rememoru, ho mia Dio, pri Tobija kaj Sanbalat tiujn iliajn farojn, ankaŭ pri la profetino Noadja, kaj la aliaj profetoj, kiuj timigis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'La murego estis finita en la dudek-kvina tago de la monato Elul, en la daŭro de kvindek du tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Kiam tion aŭdis ĉiuj niaj malamikoj, kaj vidis ĉiuj nacioj, kiuj estis ĉirkaŭ ni, ili multe perdis la kuraĝon; ĉar ili komprenis, ke tiu laboro estas farita de nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Krom tio, en tiuj tagoj la eminentuloj el la Judoj skribis multe da leteroj al Tobija, kaj leteroj de Tobija venis al ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'ĉar multaj el la Judoj estis en ĵura ligo kun li, ĉar li estis bofilo de Ŝeĥanja, filo de Araĥ, kaj lia filo Jehoĥanan prenis por edzino filinon de Meŝulam, filo de Bereĥja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Ili ankaŭ paroladis bone pri li antaŭ mi, kaj miajn vortojn ili transdonadis al li. Tobija sendis leterojn, por timigi min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Kiam la murego estis konstruita, mi starigis la pordojn; kaj ricevis siajn oficojn la pordegistoj, la kantistoj, kaj la Levidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Kaj mi donis ordonon al mia frato Ĥanani, kaj al Ĥananja, kastelestro de Jerusalem (ĉar li estis homo fidela, kaj diotima pli ol multaj aliaj),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'kaj mi diris al ili: Oni ne malfermu la pordegojn de Jerusalem, antaŭ ol la suno estos bone varmiga; kaj tiel longe, kiel ili staras, ili restigu la pordegojn fermitaj kaj ŝlositaj; kaj oni starigu gardon el la loĝantoj de Jerusalem, ĉiun sur lia gardoloko kaj ĉiun kontraŭ lia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Sed la urbo estis vasta kaj granda, kaj da loĝantoj estis en ĝi nemulte, kaj la domoj ne estis konstruitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Kaj mia Dio min inspiris, kaj mi kunvenigis la eminentulojn kaj la estrojn kaj la popolon, por ilin registri. Kaj mi trovis la genealogian registron de tiuj, kiuj venis antaŭe, kaj mi trovis, ke en ĝi estas skribite jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Jen estas la loĝantoj de la lando, kiuj iris el la forkaptitoj, kiujn forkondukis Nebukadnecar, reĝo de Babel, kaj kiuj revenis en Jerusalemon kaj en Judujon, ĉiu en sian urbon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'kiuj venis kun Zerubabel, Jeŝua, Neĥemja, Azarja, Raamja, Naĥamani, Mordeĥaj, Bilŝan, Misperet, Bigvaj, Neĥum, Baana. La nombro de la viroj de la popolo Izraela estis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'de la idoj de Paroŝ, du mil cent sepdek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'de la idoj de Ŝefatja, tricent sepdek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'de la idoj de Araĥ, sescent kvindek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'de la idoj de Paĥat-Moab, el la idoj de Jeŝua kaj Joab, du mil okcent dek ok,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'de la idoj de Elam, mil ducent kvindek kvar,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'de la idoj de Zatu, okcent kvardek kvin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'de la idoj de Zakaj, sepcent sesdek,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'de la idoj de Binuj, sescent kvardek ok,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'de la idoj de Bebaj, sescent dudek ok,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'de la idoj de Azgad, du mil tricent dudek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'de la idoj de Adonikam, sescent sesdek sep,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'de la idoj de Bigvaj, du mil sesdek sep,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'de la idoj de Adin, sescent kvindek kvin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'de la idoj de Ater, el la domo de Ĥizkija, naŭdek ok,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'de la idoj de Ĥaŝum, tricent dudek ok,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'de la idoj de Becaj, tricent dudek kvar,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'de la idoj de Ĥarif, cent dek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'de la idoj de Gibeon, naŭdek kvin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'de la loĝantoj de Bet-Leĥem kaj de Netofa, cent okdek ok,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'de la loĝantoj de Anatot, cent dudek ok,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'de la loĝantoj de Bet-Azmavet, kvardek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'de la loĝantoj de Kirjat-Jearim, Kefira, kaj Beerot, sepcent kvardek tri,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'de la loĝantoj de Rama kaj Geba, sescent dudek unu,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'de la loĝantoj de Miĥmas, cent dudek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'de la loĝantoj de Bet-El kaj Aj, cent dudek tri,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'de la loĝantoj de Nebo-Aĥer, kvindek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'de la idoj de la alia Elam, mil ducent kvindek kvar,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'de la idoj de Ĥarim, tricent dudek,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'de la idoj de Jeriĥo, tricent kvardek kvin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'de la idoj de Lod, Ĥadid, kaj Ono, sepcent dudek unu,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'de la idoj de Senaa, tri mil naŭcent tridek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'De la pastroj: de la idoj de Jedaja, el la domo de Jeŝua, naŭcent sepdek tri,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'de la idoj de Imer, mil kvindek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'de la idoj de Paŝĥur, mil ducent kvardek sep,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'de la idoj de Ĥarim, mil dek sep.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'De la Levidoj: de la idoj de Jeŝua, el la domo de Kadmiel, el la filoj de Hodja, sepdek kvar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'De la kantistoj: de la idoj de Asaf, cent kvardek ok.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'De la pordegistoj: la idoj de Ŝalum, la idoj de Ater, la idoj de Talmon, la idoj de Akub, la idoj de Ĥatita, la idoj de Ŝobaj, cent tridek ok.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'De la Netinoj: la idoj de Ciĥa, la idoj de Ĥasufa, la idoj de Tabaot,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'la idoj de Keros, la idoj de Sia, la idoj de Padon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'la idoj de Lebana, la idoj de Ĥagaba, la idoj de Ŝalmaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'la idoj de Ĥanan, la idoj de Gidel, la idoj de Gaĥar,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'la idoj de Reaja, la idoj de Recin, la idoj de Nekoda,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'la idoj de Gazam, la idoj de Uza, la idoj de Paseaĥ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'la idoj de Besaj, la idoj de Meunim, la idoj de Nefiŝesim,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'la idoj de Bakbuk, la idoj de Ĥakufa, la idoj de Ĥarĥur,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'la idoj de Baclit, la idoj de Meĥida, la idoj de Ĥarŝa,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'la idoj de Barkos, la idoj de Sisra, la idoj de Tamaĥ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'la idoj de Neciaĥ, la idoj de Ĥatifa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'La idoj de la servantoj de Salomono: la idoj de Sotaj, la idoj de Soferet, la idoj de Perida,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'la idoj de Jaala, la idoj de Darkon, la idoj de Gidel,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'la idoj de Ŝefatja, la idoj de Ĥatil, la idoj de Poĥeret-Cebaim, la idoj de Amon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'La nombro de ĉiuj Netinoj kaj de la idoj de la servantoj de Salomono estis tricent naŭdek du.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Kaj jen estas la elirintoj el Tel-Melaĥ, Tel-Ĥarŝa, Kerub, Adon, kaj Imer, kiuj ne povis montri sian patrodomon kaj devenon, ĉu ili devenas de Izrael:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'la idoj de Delaja, la idoj de Tobija, la idoj de Nekoda, sescent kvardek du.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'Kaj el la pastroj: la idoj de Ĥabaja, la idoj de Hakoc, la idoj de Barzilaj, kiu prenis al si edzinon el la filinoj de Barzilaj, la Gileadano, kaj estis nomata per ilia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Ili serĉis siajn dokumentojn genealogiajn, sed ĉi tiuj ne troviĝis; tial ili estis eligitaj el la listo de la pastroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'Kaj la regionestro diris al ili, ke ili ne manĝu el la plejsanktaĵo, ĝis aperos pastro kun la signoj de lumo kaj de justo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'La tuta komunumo kune konsistis el kvardek du mil tricent sesdek homoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'krom iliaj sklavoj kaj sklavinoj, kies nombro estis sep mil tricent tridek sep, kaj al tio estis ducent kvardek kvin kantistoj kaj kantistinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Da ĉevaloj ili havis sepcent tridek ses; da muloj ili havis ducent kvardek kvin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'da kameloj ili havis kvarcent tridek kvin; da azenoj ses mil sepcent dudek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Kelkaj el la ĉefoj de patrodomoj donis por la laboroj: la regionestro donis por la trezorejo: mil darkemonojn da oro, kvindek aspergajn kalikojn, kvincent tridek pastrajn vestojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'El la ĉefoj de patrodomoj, kelkaj donis en la trezorejon de la laboroj dudek mil darkemonojn da oro kaj du mil ducent min�ojn da arĝento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'Kaj kion donis la ceteraj el la popolo, tio estis: dudek mil darkemonoj da oro kaj du mil min�oj da arĝento kaj sesdek sep pastraj vestoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'Kaj ekloĝis la pastroj kaj la Levidoj kaj la pordegistoj kaj la kantistoj kaj la popolanoj kaj la Netinoj kaj la tuta Izrael en siaj urboj. Kiam venis la sepa monato, la Izraelidoj estis jam en siaj urboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Kaj la tuta popolo, kiel unu homo, kolektiĝis sur la placo, kiu estas antaŭ la Pordego de la Akvo, kaj ili diris al Ezra, la skribisto, ke li alportu la libron de instruo de Moseo, kiun la Eternulo ordonis al Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Kaj la pastro Ezra alportis la instruon antaŭ la komunumon, antaŭ la virojn kaj virinojn, antaŭ ĉiujn, kiuj povis kompreni, en la unua tago de la sepa monato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'Kaj li legis el ĝi sur la placo, kiu estas antaŭ la Pordego de la Akvo, de la tagiĝo ĝis la tagmezo, antaŭ la viroj kaj virinoj kaj komprenpovantoj; kaj la oreloj de la tuta popolo estis turnitaj al la libro de instruo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Kaj la skribisto Ezra staris sur ligna ambono, kiun oni faris por tio, kaj apud li staris Matitja, Ŝema, Anaja, Urija, Ĥilkija, kaj Maaseja, dekstre de li; kaj maldekstre de li: Pedaja, Miŝael, Malkija, Ĥaŝum, Ĥaŝbadana, Zeĥarja, kaj Meŝulam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Kaj Ezra malfermis la libron antaŭ la okuloj de la tuta popolo, ĉar li staris pli alte ol la tuta popolo; kaj kiam li ĝin malfermis, la tuta popolo stariĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Kaj Ezra benis la Eternulon, la grandan Dion; kaj la tuta popolo respondis: Amen, amen, levante supren siajn manojn; kaj ili kliniĝis kaj faris adoron antaŭ la Eternulo vizaĝaltere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Kaj Jeŝua, Bani, Ŝerebja, Jamin, Akub, Ŝabtaj, Ĥodija, Maaseja, Kelita, Azarja, Jozabad, Ĥanan, Pelaja, kaj la Levidoj klarigadis al la popolo la instruon; kaj la popolo staris sur sia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Kaj ili legis el la libro, el la instruo de Dio, klare, kun komentarioj, ke oni komprenu la legataĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Kaj Neĥemja, kiu estis la regionestro, kaj la pastro Ezra, la skribisto, kaj la Levidoj, kiuj donadis klarigojn al la popolo, diris al la tuta popolo: Ĉi tiu tago estas sankta al la Eternulo, via Dio; ne malĝoju kaj ne ploru. Ĉar la tuta popolo ploris, aŭskultante la vortojn de la instruo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Kaj li diris al ili: Iru, manĝu grasaĵon kaj trinku dolĉaĵon, kaj sendu porciojn al tiuj, kiuj nenion pretigis por si; ĉar ĉi tiu tago estas sankta al nia Sinjoro; kaj ne malĝoju, ĉar la ĝojo pri la Eternulo estas via forto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Kaj la Levidoj trankviligadis la tutan popolon, dirante: Ĉesu, ĉar ĉi tiu tago estas sankta; ne malĝoju.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Kaj la tuta popolo iris, por manĝi kaj trinki kaj sendi porciojn kaj fari grandan festenon; ĉar ili komprenis la vortojn, kiujn oni sciigis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'En la dua tago kunvenis la ĉefoj de patrodomoj de la tuta popolo, ankaŭ la pastroj kaj la Levidoj, al la skribisto Ezra, por ke li plue klarigu al ili la vortojn de la instruo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'Kaj ili trovis, ke en la instruo, kiun la Eternulo ordonis per Moseo, estas skribite, ke la Izraelidoj sidu en laŭboj en la festo de la sepa monato,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'kaj ke ili aŭdigu kaj proklamu en ĉiuj siaj urboj kaj en Jerusalem, dirante: Iru sur la monton, kaj prenu branĉojn de olivarbo, branĉojn de oleastraj arboj, branĉojn de mirto, branĉojn de palmoj, kaj branĉojn de densfoliaj arboj, por fari laŭbojn, kiel estas skribite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Kaj la popolo eliris kaj prenis, kaj faris al si laŭbojn, ĉiu sur sia tegmento, aŭ sur sia korto, aŭ sur la kortoj de la domo de Dio, aŭ sur la placo de la Pordego de la Akvo, aŭ sur la placo de la Pordego de Efraim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Kaj la tuta komunumo de tiuj, kiuj revenis el la kaptiteco, faris laŭbojn kaj loĝis en la laŭboj; ĉar de la tempo de Josuo, filo de Nun, ĝis tiu tago la Izraelidoj tion ne faris. Kaj estis tre granda ĝojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Kaj oni legis el la libro de instruo de Dio ĉiutage, de la unua tago ĝis la lasta tago. Kaj oni festis dum sep tagoj, kaj en la oka tago oni faris ferman feston, laŭ la preskribo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'En la dudek-kvara tago de tiu monato kunvenis la Izraelidoj, fastante, en sakaĵoj kaj kun tero sur la kapoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Kaj la idaro de Izrael apartigis sin de ĉiuj fremduloj, kaj stariĝis, kaj faris konfeson pri siaj pekoj kaj pri la pekoj de siaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Kaj ili leviĝis sur la loko, kie ili staris, kaj oni legis el la libro de instruo de la Eternulo, ilia Dio, dum kvarono de tago, kaj dum alia kvarono oni faris konfeson kaj adorkliniĝon antaŭ la Eternulo, ilia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Kaj sur la tribuno por la Levidoj stariĝis Jeŝua, Bani, Kadmiel, Ŝebanja, Buni, Ŝerebja, Bani, kaj Kenani, kaj ekvokis per laŭta voĉo al la Eternulo, ilia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Kaj diris la Levidoj Jeŝua, Kadmiel, Bani, Ĥaŝabneja, Ŝerebja, Hodija, Ŝebanja, kaj Petaĥja: Leviĝu, benu la Eternulon, vian Dion, de eterne ĝis eterne. Kaj oni benu Vian nomon, la majestan kaj plej altan super ĉia beno kaj laŭdo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Vi, ho Eternulo, estas sola; Vi faris la ĉielon, la ĉielon de ĉieloj, kaj ĝian tutan armeon, la teron, kaj ĉion, kio estas sur ĝi, la marojn, kaj ĉion, kio estas en ili; kaj Vi donas vivon al ĉio, kaj la armeo de la ĉielo adorkliniĝas antaŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Vi estas la Eternulo, la Dio, kiu elektis Abramon kaj elirigis lin el Ur la Ĥaldea kaj donis al li la nomon Abraham,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'kaj trovis lian koron fidela antaŭ Vi, kaj faris kun li interligon, por transdoni la landon de la Kanaanidoj, la Ĥetidoj, la Amoridoj, la Perizidoj, la Jebusidoj, kaj la Girgaŝidoj, transdoni ĝin al lia idaro; kaj Vi plenumis Viajn vortojn, ĉar Vi estas justa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Vi vidis la mizeron de niaj patroj en Egiptujo, kaj Vi aŭdis ilian kriadon ĉe la Ruĝa Maro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'kaj Vi faris signojn kaj miraklojn super Faraono, super ĉiuj liaj servantoj, kaj super la tuta popolo de lia lando, ĉar Vi sciis, ke ili agis fiere kontraŭ ili; kaj Vi faris al Vi nomon, kia ĝi estas ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Kaj Vi disfendis antaŭ ili la maron, kaj ili trairis meze de la maro sur seka tero; kaj iliajn persekutantojn Vi ĵetis en la profundon, kiel ŝtonon en potencan akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Per nuba kolono Vi kondukis ilin tage, kaj per fajra kolono nokte, por prilumi al ili la vojon, kiun ili devis iri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Kaj sur la monton Sinaj Vi malsupreniris, kaj Vi parolis al ili el la ĉielo, kaj donis al ili instrukciojn ĝustajn, instruojn verajn, leĝojn kaj ordonojn bonajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Kaj Vian sanktan sabaton Vi konigis al ili, kaj ordonojn, leĝojn, kaj instruon Vi ordonis al ili, per Via servanto Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Kaj panon en la ĉielo Vi donis al ili kontraŭ ilia malsato, kaj akvon el roko Vi elirigis por ili kontraŭ ilia soifo; kaj Vi diris al ili, ke ili iru ekposedi la landon, kiun per levo de la mano Vi promesis doni al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Sed ili kaj niaj patroj fariĝis fieraj kaj malmolnukaj kaj ne obeis Viajn ordonojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'ili ne volis obei, kaj ne memoris Viajn mirindaĵojn, kiujn Vi faris sur ili; ili malmoligis sian nukon kaj starigis al si estron, por reveni ribele al sia sklaveco. Sed Vi estas Dio pardonema, indulgema kaj kompatema, pacienca kaj favorkora, kaj Vi ne forlasis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Kvankam ili faris al si fanditan bovidon, kaj diris: Jen estas via dio, kiu elkondukis vin el Egiptujo, kaj kvankam ili faris grandajn blasfemojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'Vi tamen en Via granda favorkoreco ne forlasis ilin en la dezerto, la nuba kolono ne foriĝis de ili tage, por konduki ilin sur la vojo, kaj la fajra kolono nokte, por prilumi al ili la vojon, kiun ili devis iri;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'kaj Vian bonan spiriton Vi donis al ili, por instrui ilin, kaj Vian manaon Vi ne rifuzis al ilia buŝo, kaj akvon Vi donis al ili kontraŭ ilia soifo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Kaj dum kvardek jaroj Vi nutris ilin en la dezerto; nenio mankis al ili; iliaj vestoj ne sentaŭgiĝis, kaj iliaj piedoj ne ŝvelis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Kaj Vi donis al ili regnojn kaj popolojn, kaj dividis ilin laŭparte; kaj ili ekposedis la landon de Siĥon, la landon de la reĝo de Ĥeŝbon, kaj la landon de Og, reĝo de Baŝan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Kaj iliajn filojn Vi multigis kiel la steloj de la ĉielo, kaj Vi venigis ilin en la landon, pri kiu Vi diris al iliaj patroj, ke ili venos kaj ekposedos ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Kaj la filoj venis kaj ekposedis la landon; kaj Vi humiligis antaŭ ili la loĝantojn de la lando, la Kanaanidojn, kaj transdonis ilin en iliajn manojn, ankaŭ iliajn reĝojn kaj la popolojn de la lando, por ke ili agu kun ĉi tiuj laŭ sia bontrovo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'Kaj ili venkoprenis urbojn fortikigitajn kaj teron grasan, kaj ili ekposedis domojn plenajn de ĉio bona, putojn elhakitajn en ŝtonoj, vinberĝardenojn kaj olivĝardenojn, kaj multajn manĝaĵdonajn arbojn. Kaj ili manĝis, satiĝis, grasiĝis, kaj ĝuis, dank� al Via granda boneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Kaj ili fariĝis malobeemaj kaj defalis de Vi kaj ĵetis Vian instruon malantaŭ sian dorson; Viajn profetojn, kiuj admonis ilin returni sin al Vi, ili mortigis; kaj ili faris grandajn blasfemojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Tiam Vi transdonis ilin en la manojn de iliaj malamikoj, kaj ĉi tiuj premis ilin. Sed en la tempo de sia mizero ili vokis al Vi, kaj Vi el la ĉielo aŭdis, kaj pro Via granda favorkoreco Vi donis al ili savantojn, kiuj savis ilin el la manoj de iliaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Tamen, kiam ili ricevis trankvilecon, ili denove faradis malbonon antaŭ Vi. Kaj Vi forlasis ilin en la manoj de iliaj malamikoj, kiuj regis super ili. Sed, kiam ili returnis sin kaj vokis al Vi, Vi aŭdis el la ĉielo, kaj Vi savis ilin multfoje pro Via granda kompatemeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'Vi admonis ilin, ke ili returnu sin al Via instruo; sed ili estis malhumilaj kaj ne obeis Viajn ordonojn, ili pekis kontraŭ Viaj preskriboj, per kies plenumado la homo vivas, ili deturnis sian ŝultron, malmoligis sian nukon, kaj ne volis aŭskulti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Vi atendis por ili dum multe da jaroj, Vi admonadis ilin kun Via spirito per Viaj profetoj; sed ili ne atentis; tial Vi transdonis ilin en la manojn de la popoloj alilandaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Tamen pro Via granda kompatemeco Vi ne ekstermis ilin tute, kaj ne forlasis ilin, ĉar Vi estas Dio indulgema kaj kompatema.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Kaj nun, ho nia Dio, Dio granda, potenca, kaj timinda, kiu konservas la interligon kaj la favorkorecon, ne rigardu kiel tro malgrandan la tutan suferon, kiu trafis nin, niajn reĝojn, niajn princojn, niajn pastrojn, niajn profetojn, niajn patrojn, kaj Vian tutan popolon, de la tempo de la reĝoj de Asirio ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Vi estas justa en ĉio, kio trafis nin; ĉar Vi agis laŭ la vero, kaj ni agis malpie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Kaj niaj reĝoj, niaj princoj, niaj pastroj, kaj niaj patroj ne plenumis Vian instruon, kaj ne atentis Viajn ordonojn kaj admonojn, per kiuj Vi ilin admonis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'En la tempo de sia regno, kaj ĉe Via granda bono, kiun Vi donis al ili, sur la tero vasta kaj grasa, kiun Vi donis al ili, ili ne servis al Vi kaj ne deturnis sin de siaj malbonaj agoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Jen ni hodiaŭ estas sklavoj, kaj sur la tero, kiun Vi donis al niaj patroj, por ke ni manĝu ĝiajn fruktojn kaj ĝian bonaĵon, jen ni estas sklavoj sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Kaj ĝiaj produktaĵoj abunde iras al la reĝoj, kiujn Vi starigis super ni pro niaj pekoj; ili regas super niaj korpoj kaj super niaj brutoj laŭ sia plaĉo, kaj en granda mizero ni estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'En ĉio ĉi tio ni faras firman interligon, kaj ni skribas, kaj tion sigelas niaj eminentuloj, niaj Levidoj, niaj pastroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'La sigelintoj estas: Neĥemja, la regionestro, filo de Ĥaĥalja, kaj Cidkija,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Seraja, Azarja, Jeremia,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Paŝĥur, Amarja, Malkija,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Ĥatuŝ, Ŝebanja, Maluĥ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Ĥarim, Meremot, Obadja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Daniel, Ginton, Baruĥ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Meŝulam, Abija, Mijamin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Maazja, Bilgaj, Ŝemaja. Tio estas la pastroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'La Levidoj: Jeŝua, filo de Azanja, Binuj, el la filoj de Ĥenadad, Kadmiel;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'kaj iliaj fratoj: Ŝebanja, Hodija, Kelita, Pelaja, Ĥanan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Miĥa, Reĥob, Ĥaŝabja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Zakur, Ŝerebja, Ŝebanja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Hodija, Bani, Beninu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'La ĉefoj de la popolo: Paroŝ, Paĥat-Moab, Elam, Zatu, Bani,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Buni, Azgad, Bebaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Adonija, Bigvaj, Adin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Ater, Ĥizkija, Azur,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Hodija, Ĥaŝum, Becaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Ĥarif, Anatot, Nebaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Magpiaŝ, Meŝulam, Ĥezir,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Meŝezabel, Cadok, Jadua,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Pelatja, Ĥanan, Anaja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Hoŝea, Ĥananja, Ĥaŝub,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Haloĥeŝ, Pilĥa, Ŝobek,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Reĥum, Ĥaŝabna, Maaseja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Aĥija, Ĥanan, Anan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Maluĥ, Ĥarim, Baana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Kaj la cetera popolo, la pastroj, Levidoj, pordegistoj, kantistoj, Netinoj, kaj ĉiuj, kiuj apartiĝis de la aligentaj popoloj al la instruo de Dio, iliaj edzinoj, filoj, kaj filinoj, ĉiuj, kiuj povis kompreni,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'aliĝis al siaj fratoj, al la eminentuloj, kaj ligis sin per ĵura promeso, ke ili sekvos la instruon de Dio, donitan per Moseo, servanto de Dio, kaj ke ili konservos kaj plenumos ĉiujn ordonojn de la Eternulo, nia Sinjoro, Liajn preskribojn kaj leĝojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'ke ni ne donos niajn filinojn al la popoloj de la lando, kaj iliajn filinojn ni ne prenos por niaj filoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'ke kiam la popoloj de la lando venigos la komercaĵojn aŭ ĉiaspecan grenon en sabato, por vendi, ni ne prenos de ili en sabato aŭ en alia sankta tago; ke en ĉiu sepa jaro ni forigos ĉiujn ŝuldojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Kaj ni starigis al ni kiel leĝon, ke ni donados de ni po triono de siklo ĉiujare por la servado en la domo de nia Dio:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'por la panoj de propono, por la ĉiutaga farunofero, por la ĉiutaga brulofero, por la sabatoj, monatkomencoj, festoj, por la sanktaĵoj, por pekoferoj, por pekliberigi Izraelon, kaj por ĉiuj laboroj en la domo de nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Kaj ni lotis inter la pastroj, Levidoj, kaj popolo pri la ofera liverado de ligno en la domo de nia Dio, laŭ niaj patrodomoj, ĉiujare en difinitaj tempoj, por bruligi sur la altaro de la Eternulo, nia Dio, kiel estas skribite en la instruo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Kaj ni akceptis kiel devon, ke ni alportados la unuaaĵojn de nia tero kaj la unuaaĵojn de ĉiuj fruktoj de ĉiu arbo ĉiujare en la domon de la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'ankaŭ la unuenaskitojn el niaj filoj kaj el niaj brutoj, kiel estas skribite en la instruo, kaj la unuenaskitojn de niaj bovoj kaj de niaj ŝafoj ni alportados en la domon de nia Dio, al la pastroj, kiuj servas en la domo de nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'Kaj la unuaaĵon de nia pasto, niajn oferdonojn, la fruktojn de ĉiuj arboj, moston, kaj oleon ni alportados al la pastroj en la ĉambrojn de la domo de nia Dio; kaj la dekonaĵon de nia tero ni donos al la Levidoj, por ke ili, la Levidoj, havu dekonaĵon en ĉiuj urboj, kie ni prilaboras la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Kaj la pastro, la Aaronido, estos kun la Levidoj, kiam ili prenos la dekonaĵon; kaj la Levidoj venigos dekonaĵon el la dekonaĵo en la domon de nia Dio, en la ĉambrojn de la provizejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Ĉar en tiujn ĉambrojn la Izraelidoj kaj la Levidoj devas liveri la oferdonon el la greno, mosto, kaj oleo. Tie troviĝas la vazoj de la sanktejo, la servantaj pastroj, la pordegistoj, kaj la kantistoj. Kaj ni ne forlasos la domon de nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'La estroj de la popolo loĝis en Jerusalem. La cetera popolo faris lotadon, por ke unu parto el dek loĝu en Jerusalem, la sankta urbo, kaj la ceteraj naŭ partoj en la urboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'Kaj la popolo benis ĉiujn homojn, kiuj memvole konsentis loĝi en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Jen estas la ĉefoj de la provinco, kiuj loĝis en Jerusalem; en la urboj de Judujo loĝis ĉiu en sia posedaĵo, laŭ siaj urboj, la Izraelidoj, pastroj, Levidoj, Netinoj, kaj idoj de la servantoj de Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'En Jerusalem loĝis el la idoj de Jehuda kaj el la idoj de Benjamen: el la idoj de Jehuda: Ataja, filo de Uzija, filo de Zeĥarja, filo de Amarja, filo de Ŝefatja, filo de Mahalalel, el la filoj de Perec;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'kaj Maaseja, filo de Baruĥ, filo de Kol-Ĥoze, filo de Ĥazaja, filo de Adaja, filo de Jojarib, filo de Zeĥarja, filo de la Ŝiloano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'La nombro de ĉiuj idoj de Perec, kiuj loĝis en Jerusalem, estis kvarcent sesdek ok, homoj batalkapablaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Kaj jen estas la idoj de Benjamen: Salu, filo de Meŝulam, filo de Joed, filo de Pedaja, filo de Kolaja, filo de Maaseja, filo de Itiel, filo de Jeŝaja;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'post li Gabaj, Salaj, naŭcent dudek ok.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'Kaj Joel, filo de Ziĥri, estis ilia estro; kaj Jehuda, filo de Hasenua, estis dua urbestro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'El la pastroj: Jedaja, filo de Jojarib, Jaĥin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Seraja, filo de Ĥilkija, filo de Meŝulam, filo de Cadok, filo de Merajot, filo de Aĥitub, estro en la domo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'Kaj iliaj fratoj, kiuj plenumadis laboron en la domo, estis en la nombro de okcent dudek du; kaj Adaja, filo de Jeroĥam, filo de Pelalja, filo de Amci, filo de Zeĥarja, filo de Paŝĥur, filo de Malkija;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'kaj liaj fratoj, ĉefoj de patrodomoj, ducent kvardek du; kaj Amaŝsaj, filo de Azarel, filo de Aĥzaj, filo de Meŝilemot, filo de Imer;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'kaj iliaj fratoj, kuraĝaj viroj, cent dudek ok. Ilia estro estis Zabdiel, filo de Hagedolim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Kaj el la Levidoj: Ŝemaja, filo de Ĥaŝub, filo de Azrikam, filo de Ĥaŝabja, filo de Buni;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'kaj Ŝabtaj kaj Jozabad super la eksteraj aferoj de la domo de Dio, el la ĉefoj de la Levidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'kaj Matanja, filo de Miĥa, filo de Zabdi, filo de Asaf, ĉefa komencisto de laŭdkantado ĉe la preĝoj, kaj Bakbukja, la dua inter siaj fratoj, kaj Abda, filo de Ŝamua, filo de Galal, filo de Jedutun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'La nombro de ĉiuj Levidoj en la sankta urbo estis ducent okdek kvar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Kaj la pordegistoj: Akub, Talmon, kaj iliaj fratoj, gardistoj ĉe la pordegoj, cent sepdek du.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'La ceteraj Izraelidoj, pastroj, kaj Levidoj loĝis en ĉiuj urboj de Judujo, ĉiu en sia posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Kaj la Netinoj loĝis en Ofel; Ciĥa kaj Giŝpa estis super la Netinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Estro de la Levidoj en Jerusalem estis Uzi, filo de Bani, filo de Ĥaŝabja, filo de Matanja, filo de Miĥa, el la idoj de Asaf, kantistoj ĉe la servado en la domo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Ĉar pri ili estis ordono de la reĝo, kaj por la kantistoj estis difinita ĉiutaga salajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Kaj Petaĥja, filo de Meŝezabel, el la idoj de Zeraĥ, filo de Jehuda, estis komisiita de la reĝo por ĉiuj aferoj, koncernantaj la popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'Kaj en la vilaĝoj, sur siaj kampoj multaj el la idoj de Jehuda loĝis en Kirjat-Arba kaj ĝiaj ĉirkaŭaĵoj, en Dibon kaj ĝiaj ĉirkaŭaĵoj, en Kabceel kaj ĝiaj vilaĝoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'en Jeŝua, en Molada, en Bet-Pelet,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'en Ĥacar-Ŝual, en Beer-Ŝeba kaj ĝiaj ĉirkaŭaĵoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'en Ciklag, en Meĥona kaj ĝiaj ĉirkaŭaĵoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'en En-Rimon, en Corea, en Jarmut,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'en Zanoaĥ, en Adulam, kaj iliaj vilaĝoj, en Laĥiŝ kaj sur ĝiaj kampoj, en Azeka kaj ĝiaj ĉirkaŭaĵoj. Ili starigis siajn tendojn de Beer- Ŝeba ĝis la valo Hinom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Kaj la idoj de Benjamen loĝis komencante de Geba, en Miĥmaŝ, en Aja, en Bet-El kaj ĝiaj ĉirkaŭaĵoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'en Anatot, en Nob, en Ananja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'en Ĥacor, en Rama, en Gitaim,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'en Ĥadid, en Ceboim, en Nebalat,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'en Lod, en Ono, en la Valo de Ĉarpentistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Kaj el la Levidoj parto el Judujo loĝis en la regiono de Benjamen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Jen estas la pastroj kaj Levidoj, kiuj venis kun Zerubabel, filo de Ŝealtiel, kaj kun Jeŝua: Ŝeraja, Jeremia, Ezra,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amarja, Maluĥ, Ĥatuŝ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Ŝeĥanja, Reĥum, Meremot,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Ido, Ginton, Abija,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Mijamin, Maadja, Bilga,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Ŝemaja, Jojarib, Jedaja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Salu, Amok, Ĥilkija, Jedaja. Tio estas la ĉefoj de la pastroj kaj iliaj fratoj en la tempo de Jeŝua.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Kaj la Levidoj: Jeŝua, Binuj, Kadmiel, Ŝerebja, Jehuda, Matanja, super la laŭdkantoj, li kaj liaj fratoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'kaj Bakbukja kaj Uni, iliaj fratoj, deĵoris kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Jeŝua naskigis Jojakimon, Jojakim naskigis Eljaŝibon, Eljaŝib naskigis Jojadan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'Jojada naskigis Jonatanon, Jonatan naskigis Jaduan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'En la tempo de Jojakim estis pastroj ĉefoj de patrodomoj: de la domo de Seraja: Meraja; de la domo de Jeremia: Ĥananja;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'de la domo de Ezra: Meŝulam; de la domo de Amarja: Jehoĥanan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'de la domo de Meliĥu: Jonatan; de la domo de Ŝebanja: Jozef;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'de la domo de Ĥarim: Adna; de la domo de Merajot: Ĥelkaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'de la domo de Ido: Zeĥarja; de la domo de Ginton: Meŝulam;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'de la domo de Abija: Ziĥri; de la domo de Minjamin, de la domo de Moadja: Piltaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'de la domo de Bilga: Ŝamua; de la domo de Ŝemaja: Jehonatan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'de la domo de Jojarib: Matnaj; de la domo de Jedaja: Uzi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'de la domo de Salaj: Kalaj; de la domo de Amok: Eber;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'de la domo de Ĥilkija: Ĥaŝabja; de la domo de Jedaja: Netanel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'El la Levidoj estis enskribitaj la ĉefoj de patrodomoj en la tempo de Eljaŝib, Jojada, Joĥanan, kaj Jadua; la pastroj dum la reĝado de Dario la Persa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'La Levidoj, ĉefoj de patrodomoj, estis enskribitaj en la libron de kroniko ĝis la tempo de Joĥanan, filo de Eljaŝib.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'La ĉefoj de la Levidoj: Ĥaŝabja, Ŝerebja, Jeŝua, filo de Kadmiel, kaj iliaj fratoj apud ili estis destinitaj por la laŭdkantoj, laŭ la aranĝo de David, la homo de Dio, laŭ deĵorpartoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Matanja, Bakbukja, Obadja, Meŝulam, Talmon, kaj Akub estis pordegistoj, kaj deĵoris en la provizejoj ĉe la pordegoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Ili estis en la tempo de Jojakim, filo de Jeŝua, filo de Jocadak, kaj en la tempo de Neĥemja, la regionestro, kaj de Ezra, la pastro-skribisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Ĉe la inaŭguro de la murego de Jerusalem oni serĉis la Levidojn el ĉiuj iliaj lokoj, por venigi ilin en Jerusalemon, por fari inaŭguron kaj ĝojan feston, kun glorhimnoj kaj kantoj, kun cimbaloj, psalteroj, kaj harpoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Kaj kunvenis la idoj de kantistoj el la regiono ĉirkaŭ Jerusalem kaj el la vilaĝoj de la Netofaanoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'el Bet-Gilgal, de la kampoj de Geba kaj Azmavet; ĉar la kantistoj konstruis al si vilaĝojn en la ĉirkaŭaĵo de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Kaj purigis sin la pastroj kaj la Levidoj, kaj ili purigis la popolon, la pordegojn, kaj la muregon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Tiam mi suprenirigis la estrojn de Judujo sur la muregon, kaj mi starigis du grandajn ĥorojn kaj procesiojn. Unu sur la dekstra flanko de la murego, ĉe la Pordego de Sterko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'Kaj post ili iris Hoŝaja, kaj duono de la estroj de Judujo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'kaj Azarja, Ezra, Meŝulam,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Jehuda, Benjamen, Ŝemaja, kaj Jeremia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'El la pastridoj kun trumpetoj: Zeĥarja, filo de Jonatan, filo de Ŝemaja, filo de Matanja, filo de Miĥaja, filo de Zakur, filo de Asaf;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'kaj liaj fratoj: Ŝemaja, Azarel, Milalaj, Gilalaj, Maaj, Netanel, Jehuda, Ĥanani, kun muzikaj instrumentoj de David, la homo de Dio; kaj antaŭ ili estis Ezra, la skribisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Apud la Pordego de la Fonto, kontraŭ ĝi, ili iris sur la ŝtupoj de la urbo de David supren sur la muregon al la domo de David, kaj ĝis la Pordego de la Akvo oriente.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'La dua ĥoro iris kontraŭe de ili, kaj post ĝi iris mi kaj duono de la popolo, supre sur la murego, de la Turo de la Fornoj ĝis la Larĝa Murego,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'al la Pordego de Efraim, al la Malnova Pordego, al la Pordego de Fiŝoj, al la turo de Ĥananel, al la turo Mea, ĝis la Pordego de Ŝafoj; kaj ili haltis ĉe la Pordego de la Malliberejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Kaj ambaŭ ĥoroj haltis ĉe la domo de Dio, ankaŭ mi kaj duono de la estroj kun mi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'kaj la pastroj Eljakim, Maaseja, Minjamin, Miĥaja, Eljoenaj, Zeĥarja, Ĥananja, kun trumpetoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'kaj Maaseja, Ŝemaja, Eleazar, Uzi, Jehoĥanan, Malkija, Elam, kaj Ezer. Kaj laŭte kantis la kantistoj; ilia ĉefo estis Jizraĥja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'Kaj oni alportis en tiu tago grandajn oferojn, kaj oni estis gajaj; ĉar Dio ĝojigis ilin per granda ĝojo; eĉ la virinoj kaj la infanoj ĝojis, kaj la gajeco de Jerusalem estis aŭdata malproksime.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'Kaj en tiu tago estis starigitaj homoj por la ĉambroj de provizejo, por la oferdonoj, la unuaaĵoj, la dekonaĵoj, por kolekti en tiuj ĉambroj el la kampoj de la urboj la preskribitajn partojn por la pastroj kaj la Levidoj; ĉar la Judoj ĝojis pri la pastroj kaj Levidoj, kiuj staris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'Kaj ili observadis la preskribon de sia Dio kaj la preskribon pri la pureco. Kaj la kantistoj kaj pordegistoj staris konforme al la preskribo de David kaj de lia filo Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Ĉar ankaŭ antaŭe, en la tempo de David kaj Asaf, estis ĉefoj de kantistoj, kaj glorkantoj kaj dankokantoj al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Ĉiuj Izraelidoj en la tempo de Zerubabel kaj en la tempo de Neĥemja donadis partojn ĉiutagajn al la kantistoj kaj pordegistoj; kaj ili konsekradis partojn por la Levidoj, kaj la Levidoj konsekradis partojn por la idoj de Aaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'En tiu tago oni legis el la libro de Moseo antaŭ la oreloj de la popolo; kaj troviĝis, ke estas skribite en ĝi, ke Amonido kaj Moabido neniam devas eniri en la komunumon de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'ĉar ili ne venis renkonte al la Izraelidoj kun pano kaj akvo, kaj dungis kontraŭ ili Bileamon, por malbeni ilin; sed nia Dio ŝanĝis la malbenon en benon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Kiam ili aŭdis tiun leĝon, ili apartigis de Izrael ĉiun aligentulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Antaŭ ĉi tio la pastro Eljaŝib, administranto de la ĉambroj de la domo de nia Dio, parenco de Tobija,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'aranĝis por li grandan ĉambron, en kiu oni antaŭe deponadis la farunoferon, olibanon, vazojn, dekonaĵon el la greno, mosto, kaj oleo, kiuj estis destinitaj por la Levidoj, kantistoj, kaj pordegistoj, kaj la oferdonojn por la pastroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Dum ĉio ĉi tio mi ne estis en Jerusalem, ĉar en la tridek-dua jaro de Artaĥŝast, reĝo de Babel, mi iris al la reĝo, kaj nur post kelka tempo mi forpetis min de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'Kiam mi venis en Jerusalemon, mi eksciis pri la malbono, kiun Eljaŝib faris pro Tobija, aranĝante por li ĉambron en la kortoj de la domo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'Tio min forte ĉagrenis, kaj mi elĵetis ĉiujn domobjektojn de Tobija for el la ĉambro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'Kaj mi diris, ke oni purigu la ĉambrojn; kaj mi revenigis tien la vazojn de la domo de Dio, la farunoferon kaj la olibanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Mi ankaŭ eksciis, ke la partoj de la Levidoj ne estis donataj al ili, ke la Levidoj kaj kantistoj, kiuj devis fari la servadon, forkuris ĉiu al sia kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Tiam mi faris pro tio severan riproĉon al la estroj, kaj diris: Kial la domo de Dio estas forlasita? Kaj mi kunvenigis ilin kaj starigis ilin sur iliaj lokoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Kaj ĉiuj Judoj alportadis dekonaĵon el la greno, el la mosto, kaj el la oleo por la provizejoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'Kaj mi starigis super la provizejoj la pastron Ŝelemja, la skribiston Cadok, el la Levidoj Pedajan, kaj al ili Ĥananon, filon de Zakur, filo de Matanja; ĉar ili estis opiniataj fidindaj. Kaj ili havis la devon distribui la partojn al siaj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Memoru tion pri mi, ho mia Dio, kaj ne forviŝu miajn bonajn agojn, kiujn mi faris koncerne la domon de mia Dio kaj la servadon al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'En tiu tempo mi vidis en Judujo, ke oni tretas vinpremilojn en sabato kaj portas garbojn kaj ŝarĝas sur azenoj, ankaŭ vinon, vinberojn, figojn, kaj ĉiaspecan ŝarĝon, kaj veturigas tion en Jerusalemon en tago sabata. Kaj mi faris al ili riproĉon en la tago, kiam ili vendis manĝaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Ankaŭ Tiranoj loĝis tie, kaj ili alveturigadis fiŝojn kaj ĉiaspecajn komercaĵojn, kaj vendadis en sabato al la loĝantoj de Judujo kaj de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Kaj mi faris mallaŭdon al la eminentuloj de la Judoj, kaj diris al ili: Kial vi faras tian malbonon kaj malsanktigas la tagon sabatan?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Tiel agis ja viaj patroj, kaj pro tio nia Dio venigis sur nin kaj sur ĉi tiun urbon ĉi tiun tutan malfeliĉon! Kaj vi pligrandigas la koleron kontraŭ Izrael, malsanktigante la sabaton!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Kiam ĉe la pordegoj de Jerusalem fariĝis krepusko, antaŭ sabato, mi ordonis ŝlosi la pordojn kaj ne malfermi ilin ĝis post sabato. Kaj kelkajn el miaj servantoj mi starigis ĉe la pordegoj, por ke oni ne enportu ŝarĝon en la tago sabata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Kaj la komercistoj kaj vendistoj de ĉiaspeca vendeblaĵo noktis ekstere de Jerusalem unu fojon kaj duan fojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Kaj mi faris al ili riproĉon, kaj diris al ili: Kial vi noktas apud la murego? se vi faros tion duan fojon, mi metos la manon sur vin. De tiu tempo ili ne venadis en sabato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Kaj mi diris al la Levidoj, ke ili sin purigu, kaj venu stari garde ĉe la pordegoj, por ke oni tenu sankte la tagon sabatan. Ankaŭ ĉi tion memoru pri mi, ho mia Dio, kaj indulgu min laŭ Via granda favorkoreco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'Ankaŭ en tiu tempo mi vidis Judojn, kiuj prenis al si edzinojn Aŝdodaninojn, Amonidinojn, kaj Moabidinojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'kaj iliaj infanoj duone parolis Aŝdode, kaj ne povosciis paroli Jude, sed nur la lingvon de tiu aŭ alia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Mi faris al ili severan riproĉon kaj malbenis ilin, kaj batis kelkajn virojn el ili kaj ŝiris al ili la harojn, kaj devigis ilin ĵuri per Dio: Vi ne donos viajn filinojn al iliaj filoj kaj ne prenos iliajn filinojn por viaj filoj aŭ por vi mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Per tio pekis ja Salomono, reĝo de Izrael; inter la multaj nacioj ne estis reĝo simila al li, kaj li estis amata de sia Dio, kaj Dio faris lin reĝo super la tuta Izrael; tamen eĉ lin pekigis la aligentaj edzinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Kaj ĉu pri vi oni povas aŭdi, ke vi faras ĉi tiun tutan grandan malbonon, pekante kontraŭ nia Dio kaj prenante aligentajn edzinojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'El la filoj de Jojada, filo de la ĉefpastro Eljaŝib, unu estis bofilo de la Ĥoronano Sanbalat. Mi forpelis lin de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Memoru pri ili, ho mia Dio, ke ili makulis la pastrecon kaj la interligon pastran kaj Levidan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Tiamaniere mi purigis ilin de ĉio aligenta, kaj mi restarigis la servoregulojn de la pastroj kaj Levidoj, de ĉiu en lia ofico,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'kaj por la oferliverado de ligno en difinitaj tempoj, kaj por la unuaaĵoj. Memoru min, ho mia Dio, al bono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Tio estis en la tempo de Aĥaŝveroŝ, de tiu Aĥaŝveroŝ, kiu reĝis de Hindujo ĝis Etiopujo, super cent dudek sep landoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'En tiu tempo, kiam la reĝo Aĥaŝveroŝ sidis sur sia reĝa trono en la kastelurbo Ŝuŝan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'en la tria jaro de lia reĝado, li faris festenon por ĉiuj siaj princoj kaj siaj servantoj, por la potenculoj de Persujo kaj Medujo, por la landestroj kaj regionestroj, kiuj estis ĉe li,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'montrante la grandan riĉecon de sia regno kaj la majestan belecon de sia grandeco, dum multe da tagoj, dum cent okdek tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Kiam finiĝis tiuj tagoj, la reĝo faris por la tuta popolo, kiu troviĝis en la kastelurbo Ŝuŝan, de la grandaj ĝis la malgrandaj, festenon septagan sur la ĝardena korto de la reĝa palaco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Blankaj, ruĝaj, kaj bluaj ŝtofoj, fiksitaj per bisinaj kaj purpuraj ŝnuroj, pendis sur arĝentaj ringoj kaj marmoraj kolonoj. Oraj kaj arĝentaj benkoj staris sur podio el verda, blanka, flava, kaj nigra marmoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'La trinkaĵon oni donadis en oraj vazoj kaj en vazoj ne similaj unuj al la aliaj; kaj da reĝa vino estis multe, kiel decis al la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'La trinkado estis en ordo, neniu devigis; ĉar tiel la reĝo ordonis al ĉiuj administrantoj de sia domo, ke oni agu laŭ la volo de ĉiu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Ankaŭ la reĝino Vaŝti faris festenon por la virinoj de la reĝa domo de la reĝo Aĥaŝveroŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'En la sepa tago, kiam la koro de la reĝo gajiĝis de vino, li diris al Mehuman, Bizta, Ĥarbona, Bigta, Abagta, Zetar, kaj Karkas, la sep eŭnukoj, kiuj servadis antaŭ la reĝo Aĥaŝveroŝ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'ke ili alkonduku la reĝinon Vaŝti al la reĝo en la reĝina krono, por montri al la popoloj kaj al la princoj ŝian belecon; ĉar ŝi estis bela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Sed la reĝino Vaŝti ne volis veni laŭ la ordono, kiun la reĝo donis per la eŭnukoj. Tiam la reĝo forte ekkoleris, kaj lia furiozo brulis en li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Kaj la reĝo diris al la saĝuloj kompetentaj pri la cirkonstancoj (ĉar la aferoj de la reĝo estis ordinare farataj post konsiliĝo kun ĉiuj konantoj de leĝo kaj juro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'kaj la plej proksimaj al li estis: Karŝena, Ŝetar, Admata, Tarŝiŝ, Meres, Marsena, kaj Memuĥan, la sep princoj Persaj kaj Medaj, kiuj havis la rajton rigardi la vizaĝon de la reĝo kaj okupis la unuan lokon en la regno):');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'Kiel oni laŭ la leĝo devas agi kun la reĝino Vaŝti pro tio, ke ŝi ne plenumis la ordonon de la reĝo Aĥaŝveroŝ, donitan per la eŭnukoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Tiam diris Memuĥan antaŭ la reĝo kaj la princoj: La reĝino Vaŝti estas kulpa, ne sole kontraŭ la reĝo, sed kontraŭ ĉiuj princoj, kaj kontraŭ ĉiuj popoloj, kiuj troviĝas en ĉiuj landoj de la reĝo Aĥaŝveroŝ;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'ĉar la ago de la reĝino fariĝos konata al ĉiuj virinoj tiel, ke ili malrespektos siajn edzojn, dirante: La reĝo Aĥaŝveroŝ ordonis venigi al li la reĝinon Vaŝti, kaj ŝi ne iris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Nun la Persaj kaj Medaj princedzinoj, kiuj aŭdis pri la ago de la reĝino, parolos tiel same al ĉiuj princoj de la reĝo; kaj estos sufiĉe da malhonoro kaj da ĉagreno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Se al la reĝo plaĉas, oni elirigu ordonon de la reĝo, kaj oni enskribu ĝin kiel nemalobeeblan leĝon de Persujo kaj Medujo, ke la reĝino Vaŝti ne venu plu antaŭ la reĝon Aĥaŝveroŝ; kaj ŝian reĝinecon la reĝo transdonu al alia virino, kiu estas pli bona ol ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'Kiam la ordono, kiun la reĝo faris, estos aŭdita en lia tuta regno, kiel ajn granda ĝi estas, tiam ĉiuj virinoj respektos siajn edzojn, de la grandaj ĝis la malgrandaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'La parolo plaĉis al la reĝo kaj al la princoj, kaj la reĝo agis konforme al la parolo de Memuĥan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'Kaj li sendis leterojn en ĉiujn landojn de la reĝo, en ĉiun landon laŭ ĝia skribmaniero kaj al ĉiu popolo en ĝia lingvo, ke ĉiu viro estu ĉefo en sia domo kaj postulu paroladon en la lingvo de lia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Post tiu afero, kiam kvietiĝis la kolero de la reĝo Aĥaŝveroŝ, li rememoris pri Vaŝti, kaj pri tio, kion ŝi faris kaj kio estis dekretita pri ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Kaj diris la junuloj de la reĝo, kiuj servadis al li: Oni serĉu por la reĝo belajn junajn virgulinojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'kaj la reĝo starigu en ĉiuj landoj de sia regno oficistojn, kiuj kolektus ĉiujn belajn junajn virgulinojn en la kastelurbon Ŝuŝan, en la virinejon, sub la inspektadon de Hegaj, la reĝa eŭnuko, gardisto de la virinoj, kaj oni donu al ili iliajn beligaĵojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'kaj la junulino, kiu plaĉos al la okuloj de la reĝo, fariĝos reĝino anstataŭ Vaŝti. Kaj la afero plaĉis al la reĝo, kaj li tiel faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'En la kastelurbo Ŝuŝan estis Judo, kies nomo estis Mordeĥaj, filo de Jair, filo de Ŝimei, filo de Kiŝ, Benjamenido;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'kiu estis transloĝigita el Jerusalem kune kun la transloĝigitoj, kiuj estis forkondukitaj kun Jeĥonja, reĝo de Judujo, kaj kiujn transloĝigis Nebukadnecar, reĝo de Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Li estis prizorganto de Hadasa, kiu ankaŭ estis nomata Ester, filino de lia onklo, ĉar ŝi ne havis patron nek patrinon. La junulino estis belstatura kaj belvizaĝa. Kiam mortis ŝiaj gepatroj, Mordeĥaj prenis ŝin al si kiel filinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Kiam estis aŭdigita la ordono de la reĝo kaj lia leĝo, kaj kiam oni kolektis multe da knabinoj en la kastelurbon Ŝuŝan sub la inspekton de Hegaj, tiam ankaŭ Ester estis prenita en la reĝan domon sub la inspekton de Hegaj, la gardisto de la virinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'La knabino plaĉis al li kaj akiris lian favoron, kaj li rapide donis al ŝi ŝiajn beligaĵojn kaj ŝian destinitaĵon, kaj sep knabinojn elektitajn el la domo de la reĝo; kaj li transloĝigis ŝin kun ŝiaj knabinoj en la plej bonan parton de la virinejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Ester ne diris pri sia popolo nek pri sia patrujo, ĉar Mordeĥaj ordonis al ŝi, ke ŝi ne diru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Ĉiutage Mordeĥaj iradis antaŭ la korto de la virinejo, por sciiĝi pri la farto de Ester, kaj pri tio, kio okazas al ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Kiam por ĉiu knabino venis la vico iri al la reĝo Aĥaŝveroŝ, post kiam dum dek du monatoj estis farata al ŝi la beligado destinita por la virinoj (ĉar tiel longe daŭris la tempo de ilia beligado: ses monatoj per mirha oleo, kaj ses monatoj per aromaĵoj kaj per aliaj ŝmiraĵoj),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'tiam la knabino eniris al la reĝo. Ĉion, kion ŝi diris, oni donis al ŝi, por ke ŝi iru kun tio el la virinejo en la reĝan domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Vespere ŝi eniris, kaj matene ŝi revenis en la virinejon duan, sub la inspekton de Ŝaaŝgaz, reĝa eŭnuko, gardisto de la kromvirinoj; ŝi jam ne plu iris al la reĝo, krom en la okazo, se la reĝo ŝin deziris kaj se ŝi estis vokita laŭnome.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Kiam por Ester, filino de Abiĥail, onklo de Mordeĥaj, kiu prenis ŝin al si kiel filinon, venis la vico iri al la reĝo, ŝi nenion petis, krom nur tio, kion diris Hegaj, la reĝa eŭnuko, gardisto de la virinoj. Kaj Ester akiris la favoron de ĉiuj, kiuj ŝin vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Ester estis prenita al la reĝo Aĥaŝveroŝ en lian reĝan domon en la deka monato, tio estas en la monato Tebet, en la sepa jaro de lia reĝado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'Kaj la reĝo ekamis Esteron pli ol ĉiujn edzinojn, kaj ŝi akiris ĉe li simpation kaj favoron pli ol ĉiuj virgulinoj; kaj li metis reĝan kronon sur ŝian kapon kaj faris ŝin reĝino anstataŭ Vaŝti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Kaj la reĝo faris grandan festenon por ĉiuj siaj princoj kaj servantoj, festenon je la honoro de Ester; kaj li donis ripozon al la landoj kaj disdonis reĝajn donacojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Kaj kiam oni la duan fojon kolektis junulinojn, Mordeĥaj sidis ĉe la pordego de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Ester ankoraŭ ne diris pri sia patrujo kaj pri sia popolo, kiel ordonis al ŝi Mordeĥaj; kaj la dirojn de Mordeĥaj Ester plenumadis tiel same, kiel tiam, kiam ŝi estis sub lia prizorgado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'En tiu tempo, kiam Mordeĥaj sidadis ĉe la pordego de la reĝo, ekkoleris Bigtan kaj Tereŝ, du korteganoj de la reĝo el la sojlogardistoj, kaj ili intencis meti manon sur la reĝon Aĥaŝveroŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Pri tio eksciis Mordeĥaj, kaj li diris al la reĝino Ester, kaj Ester diris tion al la reĝo en la nomo de Mordeĥaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'La afero estis esplorita kaj trovita vera, kaj oni pendigis ambaŭ sur arbo. Kaj tio estis enskribita en la kronikon ĉe la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Post tiuj okazintaĵoj la reĝo Aĥaŝveroŝ eminentigis Hamanon, filon de Hamedata, la Agagidon, altigis lin kaj starigis lian seĝon super ĉiuj princoj, kiuj estis ĉe li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'Kaj ĉiuj servantoj de la reĝo, kiuj estis ĉe la pordego de la reĝo, klinadis sin kaj ĵetadis sin vizaĝaltere antaŭ Haman, ĉar tiel ordonis pri li la reĝo. Sed Mordeĥaj sin ne klinadis kaj ne ĵetadis sin vizaĝaltere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'La servantoj de la reĝo, kiuj estis ĉe la pordego de la reĝo, diris al Mordeĥaj: Kial vi malobeas la ordonon de la reĝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Ĉar ili diradis tion al li ĉiutage kaj li ne obeis ilin, tial ili raportis tion al Haman, por vidi, ĉu la vortoj de Mordeĥaj konservos sian forton; ĉar li diris al ili, ke li estas Judo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Kiam Haman vidis, ke Mordeĥaj ne klinas sin kaj ne ĵetas sin vizaĝaltere antaŭ li, tiam Haman pleniĝis de kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Sed li trovis nesufiĉa meti la manon sur Mordeĥajon; ĉar oni diris al li, el kiu popolo Mordeĥaj estas, tial Haman ekintencis ekstermi ĉiujn Judojn, kiuj estis en la tuta regno de Aĥaŝveroŝ, la popolon de Mordeĥaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'En la unua monato, tio estas en la monato Nisan, en la dek-dua jaro de la reĝado de Aĥaŝveroŝ, oni ĵetadis pur�on, tio estas loton, antaŭ Haman, de tago al tago kaj de monato al monato, ĝis la dek-dua, tio estas ĝis la monato Adar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Kaj Haman diris al la reĝo Aĥaŝveroŝ: Ekzistas unu popolo, disĵetita kaj dissemita inter la popoloj en ĉiuj landoj de via regno; iliaj leĝoj estas malsimilaj al la leĝoj de ĉiuj popoloj, kaj la leĝojn de la reĝo ili ne plenumas; ne decas al la reĝo tiel restigi ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Se al la reĝo plaĉas, oni preskribu ekstermi ilin; tiam dek mil kikarojn da arĝento mi pesos en la manojn de la oficistoj, por enporti en la kason de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Tiam la reĝo deprenis sian ringon de sia mano, kaj donis ĝin al Haman, filo de Hamedata, la Agagido, malamiko de la Judoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'Kaj la reĝo diris al Haman: La arĝento estas transdonata al vi, kaj ankaŭ la popolo, por fari al ĝi tion, kio plaĉas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Kaj oni vokis la skribistojn de la reĝo en la unua monato, en ĝia dek- tria tago, kaj oni skribis konforme al ĉiuj ordonoj de Haman al la satrapoj de la reĝo, kaj al la regionestroj, kiuj estis super ĉiu regiono, kaj al la princoj de ĉiu popolo, en ĉiun landon laŭ ĝia skribmaniero kaj al ĉiu popolo en ĝia lingvo; en la nomo de la reĝo Aĥaŝveroŝ tio estis skribita kaj sigelita per la ringo de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Kaj oni sendis per kurieroj leterojn en ĉiujn landojn de la reĝo, ke oni ekstermu, mortigu, kaj pereigu ĉiujn Judojn, de junulo ĝis maljunulo, la infanojn kaj la virinojn, en unu tago, en la dek-tria tago de la dek-dua monato, tio estas de la monato Adar, kaj ilian havaĵon oni disrabu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Kopio de la letero estis transdonota kiel leĝo en ĉiun landon kaj proklamota al ĉiuj popoloj, por ke ili estu pretaj al tiu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'La kurieroj eliris rapide kun la ordono de la reĝo. La leĝo estis donita en la kastelurbo Ŝuŝan. La reĝo kaj Haman sidiĝis, por drinki, sed la urbo Ŝuŝan estis konsternita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Kiam Mordeĥaj eksciis ĉion, kio fariĝis, tiam Mordeĥaj disŝiris siajn vestojn, metis sur sin sakaĵon kaj cindron, eliris en la mezon de la urbo, kaj kriis per laŭta kaj maldolĉa voĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'Kaj li venis ĝis antaŭ la pordego de la reĝo, ĉar estis malpermesite eniri en sakaĵo en la pordegon de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'Kaj en ĉiu lando, sur ĉiu loko, kien venis la ordono de la reĝo kaj lia dekreto, estis granda malĝojo ĉe la Judoj, fastado, plorado, kaj ĝemado; kaj multaj kuŝis en sakaĵo kaj cindro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Kaj venis la servistinoj de Ester kaj ŝiaj eŭnukoj, kaj rakontis al ŝi. Kaj la reĝino forte konsterniĝis. Kaj ŝi sendis vestojn, por vesti Mordeĥajon kaj depreni de li la sakaĵon; sed li ne akceptis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Kaj Ester alvokis Hataĥon, unu el la eŭnukoj de la reĝo, kiun ĉi tiu destinis por servado al ŝi, kaj ŝi sendis lin al Mordeĥaj, por ekscii, kio kaj pro kio tio estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Hataĥ eliris al Mordeĥaj sur la urban placon, kiu estis antaŭ la pordego de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'Kaj Mordeĥaj rakontis al li ĉion, kio okazis al li, kaj pri la difinita sumo da mono, kiun Haman promesis doni pese en la kason de la reĝo pro la Judoj, por ekstermi ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Kaj kopion de la letera ordono, kiu estis donita en Ŝuŝan, por ilin ekstermi, li donis al li, por montri al Ester kaj sciigi al ŝi, ordonante al ŝi iri al la reĝo, por petegi lin pri ŝia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Hataĥ venis kaj transdonis al Ester la vortojn de Mordeĥaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Kaj Ester diris al Hataĥ, ordonante, ke li diru al Mordeĥaj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Ĉiuj servantoj de la reĝo kaj la popolo en la landoj de la reĝo scias, ke por ĉiu viro aŭ virino, kiu eniris al la reĝo en la internan korton ne vokite, ekzistas nur unu leĝo, nome la morto, krom nur en la okazo, se la reĝo etendas al li sian oran sceptron-tiam li restas vivanta; kaj mi ne estas vokita iri al la reĝo jam de tridek tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Kiam oni raportis al Mordeĥaj la vortojn de Ester,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'tiam Mordeĥaj sendis respondon al Ester: Ne pensu en via animo, ke en la reĝa domo vi saviĝos sola el ĉiuj Judoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Se vi silentos en ĉi tiu tempo, tiam liberigo kaj savo venos al la Judoj de alia loko; sed vi kaj la domo de via patro pereos. Kaj kiu scias, ĉu ne por tia tempo vi atingis reĝinecon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Tiam Ester diris, ke oni respondu al Mordeĥaj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Iru, kunvenigu ĉiujn Judojn, kiuj troviĝas en Ŝuŝan, fastu por mi, ne manĝu kaj ne trinku dum tri tagoj, tage kaj nokte; ankaŭ mi kaj miaj servistinoj fastos tiel same; poste mi iros al la reĝo, kvankam tio estas kontraŭleĝa; kaj se mi pereos, mi pereu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Kaj Mordeĥaj iris, kaj faris ĉion, kion komisiis al li Ester.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'En la tria tago Ester vestis sin reĝe, kaj stariĝis sur la interna korto de la reĝa domo, kontraŭ la domo de la reĝo. La reĝo sidis sur sia reĝa trono en la reĝa domo, kontraŭ la enirejo de la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Kiam la reĝo ekvidis la reĝinon Ester, starantan sur la korto, ŝi trovis favoron en liaj okuloj, kaj la reĝo etendis al Ester la oran sceptron, kiu estis en lia mano; tiam Ester aliris, kaj ektuŝis la pinton de la sceptro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Kaj la reĝo diris al ŝi: Kio estas al vi, ho reĝino Ester, kaj kia estas via peto? se tio estas eĉ duono de la regno, ĝi estos donita al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Kaj Ester respondis: Se al la reĝo plaĉas, la reĝo kune kun Haman venu hodiaŭ al la festeno, kiun mi faris por li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Tiam la reĝo diris: Venigu plej rapide Hamanon, por plenumi tion, kion diris Ester. Kaj la reĝo kaj Haman venis al la festeno, kiun faris Ester.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Kaj la reĝo diris al Ester dum la trinkado de vino: Kion vi petas? tio estos donita al vi; kaj kia estas via deziro? ĝis duono de la regno ĝi estos plenumita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Ester respondis kaj diris: Jen estas mia peto kaj deziro:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'se mi akiris favoron en la okuloj de la reĝo, kaj se al la reĝo plaĉas plenumi mian peton kaj fari mian deziron, la reĝo kun Haman venu al la festeno, kiun mi faros por ili; kaj morgaŭ mi faros, kion la reĝo diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Haman eliris en tiu tago, gaja kaj bonhumora. Sed kiam Haman ekvidis Mordeĥajon ĉe la reĝa pordego, kaj tiu ne leviĝis kaj ne moviĝis antaŭ li, tiam Haman pleniĝis de kolero kontraŭ Mordeĥaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Tamen Haman detenis sin, kaj iris hejmen. Kaj li sendis, kaj venigis al si siajn amikojn kaj sian edzinon Zereŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Kaj Haman rakontis al ili pri sia granda riĉeco, pri la multo de siaj filoj, kaj pri ĉio, per kio la reĝo lin altigis kaj starigis lin super la princoj kaj servantoj de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Kaj Haman diris: Eĉ la reĝino Ester invitis kun la reĝo al la festeno, kiun ŝi faris, neniun krom mi; ankaŭ por morgaŭ mi estas invitita al ŝi kun la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Sed ĉio ĉi tio ne kontentigas min tiel longe, kiel mi vidas, ke la Judo Mordeĥaj sidas ĉe la pordego de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Tiam diris al li lia edzino Zereŝ kaj ĉiuj liaj amikoj: Oni pretigu arbon, havantan la alton de kvindek ulnoj, kaj matene diru al la reĝo, ke oni pendigu sur ĝi Mordeĥajon; kaj poste iru gaje kun la reĝo al la festeno. Tio plaĉis al Haman, kaj li pretigis la arbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'En tiu nokto la reĝo ne povis dormi; kaj li ordonis alporti la memoraĵan libron de la kronikoj, kaj oni legis ilin antaŭ la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'Kaj tie troviĝis skribite, kiel Mordeĥaj raportis pri Bigtan kaj Tereŝ, la du reĝaj korteganoj el la sojlogardistoj, kiuj intencis meti manon sur la reĝon Aĥaŝveroŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Tiam la reĝo diris: Kian honoron kaj distingon oni faris pro tio al Mordeĥaj? Kaj la junuloj servistoj de la reĝo respondis: Nenio estas farita al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'La reĝo diris: Kiu estas sur la korto? Dume Haman estis veninta sur la eksteran korton de la reĝa domo, por diri al la reĝo, ke oni pendigu Mordeĥajon sur la arbo, kiun li pretigis por li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'La junuloj de la reĝo diris al li: Jen Haman staras sur la korto. Kaj la reĝo diris: Li eniru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Haman eniris. Kaj la reĝo diris al li: Kion oni faru al tiu homo, kiun la reĝo deziras honori? Haman pensis en sia koro: Al kiu la reĝo povas deziri fari honoron krom mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Kaj Haman diris al la reĝo: Se al iu la reĝo volas fari honoron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'oni alportu reĝan veston, kiun portis sur si la reĝo, kaj ĉevalon, sur kiu rajdis la reĝo, kiam sur lian kapon estis metita la reĝa krono;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'oni donu la veston kaj la ĉevalon en la manon de unu el la plej eminentaj reĝaj princoj, ke oni vestu la homon, kiun la reĝo deziras honori, kaj rajdigu lin sur la ĉevalo sur la strato de la urbo, kaj oni proklamadu antaŭ li: Tiele estas farate al la homo, kiun la reĝo volas honori.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Tiam la reĝo diris al Haman: Rapide prenu la veston kaj la ĉevalon, kiel vi diris, kaj agu tiel kun la Judo Mordeĥaj, kiu sidas ĉe la pordego de la reĝo; mankigu nenion el ĉio, kion vi diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Haman prenis la veston kaj la ĉevalon, kaj vestis Mordeĥajon, kaj rajdigis lin tra la strato de la urbo, kaj proklamadis antaŭ li: Tiele estas farate al la homo, kiun la reĝo volas honori.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Poste Mordeĥaj revenis al la pordego de la reĝo; kaj Haman rapidis hejmen, malĝoja kaj kun kovrita kapo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Haman rakontis al sia edzino Zereŝ kaj al ĉiuj siaj amikoj ĉion, kio okazis al li. Kaj diris al li liaj saĝuloj kaj lia edzino Zereŝ: Se el la gento de la Judoj estas Mordeĥaj, antaŭ kiu vi komencis fali, vi nenion povas fari kontraŭ li, sed vi plue falos antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Dum ili ankoraŭ parolis kun li, venis la eŭnukoj de la reĝo kaj rapidigis Hamanon iri al la festeno, kiun pretigis Ester.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'La reĝo kaj Haman venis, por festeni ĉe la reĝino Ester.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'Kaj ankaŭ en la dua tago, dum la trinkado de vino, la reĝo diris al Ester: Kion vi petas, ho reĝino Ester? tio estos donita al vi; kaj kia estas via deziro? ĝis duono de la regno ĝi estos plenumita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Tiam la reĝino Ester respondis kaj diris: Se mi trovis favoron en viaj okuloj, ho reĝo, kaj se al la reĝo plaĉas, tiam mia vivo estu donacita al mi laŭ mia peto, kaj mia popolo laŭ mia deziro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'ĉar ni estas venditaj, mi kaj mia popolo, por ekstermo, mortigo, kaj pereigo. Se ni almenaŭ estus venditaj nur por esti sklavoj kaj sklavinoj, mi silentus, kvankam la malamiko ne kompensus la malprofiton de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Tiam la reĝo Aĥaŝveroŝ diris al la reĝino Ester: Kiu li estas kaj kie li estas, tiu, kiu prenis en sian koron la kuraĝon agi tiel?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Kaj Ester respondis: La malamanto kaj malamiko estas ĉi tiu malbona Haman. Kaj Haman ektremis antaŭ la reĝo kaj la reĝino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'La reĝo leviĝis kolere de la vintrinkado, kaj iris en la ĝardenon de la palaco; sed Haman restis, por peti pri sia vivo la reĝinon Ester, ĉar li vidis, ke la reĝo destinis por li malbonan sorton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Kiam la reĝo revenis el la palaca ĝardeno en la ĉambron de la festeno, Haman estis falinta sur la litbenkon, sur kiu sidis Ester. Tiam la reĝo diris: Eĉ perforti la reĝinon li volas ĉe mi en la domo! La vorto eliris el la buŝo de la reĝo, kaj oni kovris al Haman la vizaĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Ĥarbona, unu el la eŭnukoj antaŭ la reĝo, diris: Jen eĉ la arbo, kiun Haman pretigis por Mordeĥaj, kiu parolis bonon por la reĝo, staras en la domo de Haman; ĝi havas la alton de kvindek ulnoj. Tiam la reĝo diris: Pendigu lin sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Kaj oni pendigis Hamanon sur la arbo, kiun li pretigis por Mordeĥaj. Kaj la kolero de la reĝo kvietiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'En tiu tago la reĝo Aĥaŝveroŝ transdonis al la reĝino Ester la domon de Haman, la malamiko de la Judoj; kaj Mordeĥaj venis antaŭ la reĝon, ĉar Ester diris, kio li estas por ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Kaj la reĝo deprenis sian ringon, kiun li forprenis de Haman, kaj donis ĝin al Mordeĥaj; kaj Ester starigis Mordeĥajon super la domo de Haman.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Kaj Ester plue parolis antaŭ la reĝo, kaj ĵetis sin antaŭ liajn piedojn, kaj ploris kaj petegis lin, ke li neniigu la malbonaĵon de Haman, la Agagido, kaj lian planon, kiun li entreprenis kontraŭ la Judoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'La reĝo etendis al Ester sian oran sceptron, kaj Ester leviĝis kaj stariĝis antaŭ la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'Kaj ŝi diris: Se al la reĝo plaĉas, kaj se mi trovis favoron antaŭ li, se la afero ŝajnas al li ĝusta, kaj se li havas simpation por mi: tiam estu skribate, ke oni revoku la leterojn, kiujn elpensis Haman, filo de Hamedata, la Agagido, kaj kiujn li skribis, por ekstermi la Judojn, kiuj troviĝas en ĉiuj landoj de la reĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'ĉar kiel mi povus vidi la malfeliĉon, kiu trafas mian popolon? kaj kiel mi povus vidi la pereon de miaj samgentanoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Tiam la reĝo Aĥaŝveroŝ diris al la reĝino Ester kaj al la Judo Mordeĥaj: Jen la domon de Haman mi transdonis al Ester, kaj lin mem oni pendigis sur arbo, pro tio, ke li metis sian manon sur la Judojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'skribu do pri la Judoj en la nomo de la reĝo tion, kio plaĉas al vi, kaj sigelu per la reĝa ringo; ĉar leteron, skribitan en la nomo de la reĝo kaj sigelitan per la reĝa ringo, oni ne povas revoki.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Kaj oni vokis la skribistojn de la reĝo en tiu tempo, en la tria monato, tio estas en la monato Sivan, en ĝia dudek-tria tago; kaj oni skribis ĉion tiel, kiel ordonis Mordeĥaj, al la Judoj, al la satrapoj, al la regionestroj, kaj al la princoj de la landoj, kiuj estis de Hindujo ĝis Etiopujo, cent dudek sep landoj, al ĉiu lando laŭ ĝia skribmaniero kaj al ĉiu popolo en ĝia lingvo, ankaŭ al la Judoj laŭ ilia skribmaniero kaj en ilia lingvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'Li skribigis en la nomo de la reĝo Aĥaŝveroŝ, kaj sigelis per la reĝa ringo, kaj sendis per rajdantaj kurieroj sur bone kurantaj bonrasaj ĉevaloj leterojn pri tio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'ke la reĝo permesas al la Judoj en ĉiuj urboj kolektiĝi kaj stariĝi, por defendi sian vivon, ekstermi, mortigi, kaj pereigi ĉiujn fortulojn de la popolo kaj de la lando, kiuj atakos ilin, la infanojn, kaj la virinojn, kaj disrabi ilian havaĵon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'en la daŭro de unu tago en ĉiuj landoj de la reĝo Aĥaŝveroŝ, en la dek-tria tago de la dek-dua monato, tio estas de la monato Adar;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'ke oni donu kopion de ĉi tiu ordonletero kiel leĝon, proklamotan al ĉiuj popoloj, kaj ke la Judoj estu pretaj por tiu tago, por venĝi al siaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'La kurieroj, rajdantaj sur bonrasaj ĉevaloj, elrajdis tuj kaj rapide kun la ordono de la reĝo. La leĝo estis donita en la kastelurbo Ŝuŝan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Mordeĥaj eliris de la reĝo en reĝa vesto el blua kaj blanka ŝtofo, kun granda ora krono, kaj en mantelo bisina kaj purpura. Kaj la urbo Ŝuŝan ĝojkriis kaj estis gaja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Ĉe la Judoj estis lumo kaj ĝojo, gajeco kaj triumfo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Kaj en ĉiu lando kaj en ĉiu urbo, sur ĉiu loko, kien atingis la ordono kaj dekreto de la reĝo, estis ĉe la Judoj ĝojo kaj gajeco, festeno kaj festo. Kaj multaj homoj el la popoloj de la lando fariĝis Judoj, ĉar falis sur ilin timo antaŭ la Judoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'En la dek-dua monato, tio estas en la monato Adar, en ĝia dek-tria tago, kiam venis la tempo de plenumo de la reĝa ordono kaj dekreto-en la tago, kiam la malamikoj de la Judoj esperis superforti ilin-la afero turniĝis, kaj la Judoj superfortis siajn malamikojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'La Judoj kolektiĝis en siaj urboj en ĉiuj landoj de la reĝo Aĥaŝveroŝ, por etendi la manon kontraŭ siajn malbondezirantojn; kaj neniu povis kontraŭstari al ili, ĉar timo antaŭ ili falis sur ĉiujn popolojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'Kaj ĉiuj landestroj, satrapoj, regionestroj, kaj oficistoj de la reĝo favoris la Judojn, ĉar falis sur ilin timo antaŭ Mordeĥaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Ĉar Mordeĥaj estis granda en la domo de la reĝo, kaj la famo pri li iris tra ĉiuj landoj, ĉar la viro Mordeĥaj fariĝadis ĉiam pli kaj pli granda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Kaj la Judoj batis ĉiujn siajn malamikojn, frapante per glavo, mortigante kaj ekstermante, kaj ili faris al siaj malamikoj, kion ili volis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'En la kastelurbo Ŝuŝan la Judoj mortigis kaj pereigis kvincent homojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'ankaŭ Parŝandatan, Dalfonon, Aspatan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Poratan, Adaljan, Aridatan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'Parmaŝtan, Arisajon, Aridajon, kaj Vajzatan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'la dek filojn de Haman, filo de Hamedata kaj persekutanto de la Judoj, ili mortigis; sed sur la havaĵon ili ne metis sian manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'En la sama tago la nombro de la mortigitoj en la kastelurbo Ŝuŝan estis raportita al la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Kaj la reĝo diris al la reĝino Ester: En la kastelurbo Ŝuŝan la Judoj mortigis kaj pereigis kvincent homojn kaj ankaŭ la dek filojn de Haman; kion ili faris en la ceteraj regionoj de la reĝo? Kion vi petas? tio estos donita al vi; kion vi ankoraŭ deziras? tio estos plenumita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Ester respondis: Se al la reĝo plaĉas, estu permesite al la Judoj en Ŝuŝan ankaŭ morgaŭ fari tion saman, kion hodiaŭ, kaj la dek filojn de Haman oni pendigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Kaj la reĝo diris, ke oni faru tiel. Kaj estis donita dekreto pri tio en Ŝuŝan, kaj la dek filojn de Haman oni pendigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'La Judoj, kiuj estis en Ŝuŝan, kolektiĝis ankaŭ en la dek-kvara tago de la monato Adar, kaj mortigis en Ŝuŝan tricent homojn; sed sur la havaĵon ili ne metis sian manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Ankaŭ la ceteraj Judoj, kiuj estis en la landoj de la reĝo, kolektiĝis kaj stariĝis, por defendi sian vivon kaj por akiri trankvilecon antaŭ siaj malamikoj, kaj ili mortigis el siaj malamikoj sepdek kvin mil, sed sur la havaĵon ili ne metis sian manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'Tio estis en la dek-tria tago de la monato Adar. Kaj en ĝia dek-kvara tago estis ripozo, kaj oni faris ĝin tago de festeno kaj de gajeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Sed la Judoj, kiuj estis en Ŝuŝan, kolektiĝis en la dek-tria kaj en la dek-kvara tagoj; ripozo estis en la dek-kvina tago, kaj ili faris ĝin tago de festeno kaj de gajeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Tial la Judoj, kiuj loĝas en loĝlokoj kaj urboj ne fortikigitaj, faras la dek-kvaran tagon de la monato Adar tago de ĝojo kaj de festeno, festotago, kaj ili sendas donacojn unuj al aliaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Mordeĥaj priskribis ĉiujn tiujn okazintaĵojn, kaj sendis leterojn al ĉiuj Judoj, kiuj estis en ĉiuj landoj de la reĝo Aĥaŝveroŝ, la proksimaj kaj la malproksimaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'ke ili akceptu por si, ke ili festados ĉiujare la dek-kvaran tagon de la monato Adar kaj ĝian dek-kvinan tagon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'kiel tagojn, en kiuj la Judoj ricevis trankvilecon kontraŭ siaj malamikoj, kaj kiel monaton, kiu turnis por ili malĝojon en ĝojon, funebron en feston; ke ili faradu ilin tagoj de festeno kaj de gajeco, de sendado de donacoj unuj al aliaj kaj de donacado al malriĉuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'Kaj la Judoj akceptis tion, kion ili jam mem komencis fari kaj pri kio skribis al ili Mordeĥaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Ĉar Haman, filo de Hamedata, la Agagido, kaj malamiko de ĉiuj Judoj, intencis pereigi la Judojn kaj ĵetis pur�on, tio estas loton, por ekstermi kaj pereigi ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'sed kiam ŝi venis antaŭ la reĝon, ĉi tiu ordonis skribe, ke lia malbona entrepreno, kiun li preparis por la Judoj, turniĝu sur lian kapon; kaj ke oni pendigu lin kaj liajn filojn sur arbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Pro tio oni donis al tiuj tagoj la nomon Purim, laŭ la vorto pur. Tial, konforme al ĉiuj vortoj de tiu letero, kaj al tio, kion ili mem vidis koncerne tion kaj kio trafis ilin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'la Judoj decidis kaj akceptis por si, por sia idaro, kaj por ĉiuj, kiuj aliĝos al ili, ke ili nepre festados tiujn du tagojn laŭ la preskribo kaj en la difinita tempo ĉiujare.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'Tiuj tagoj devas esti memorataj kaj festataj en ĉiuj generacioj, en ĉiu familio, en ĉiu lando, kaj en ĉiu urbo; kaj tiuj tagoj de Purim ne devas esti forigitaj ĉe la Judoj, kaj la memoro pri ili ne devas malaperi inter ilia idaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Kaj la reĝino Ester, filino de Abiĥail, kaj la Judo Mordeĥaj skribis kun plena insisto, ke oni plenumu tiun duan leteron pri Purim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'Kaj ili sendis leterojn al ĉiuj Judoj en la cent dudek sep landojn de la regno de Aĥaŝveroŝ, kun vortoj de paco kaj de vero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'ke ili festadu tiujn tagojn de Purim en ilia tempo, kiel decidis pri ili la Judo Mordeĥaj kaj la reĝino Ester, kaj kiel ili mem akceptis por si kaj por sia idaro koncerne la fastadon kaj preĝadon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Kaj laŭ la ordono de Ester oni konfirmis tiun historion de Purim kaj enskribis en libron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'La reĝo Aĥaŝveroŝ metis sub tributon la teron kaj la insulojn de la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'La tuta historio pri lia forto kaj lia potenco, kaj la detaloj pri la grandeco de Mordeĥaj, kiun la reĝo grandigis, estas priskribitaj en la libro de kroniko de la reĝoj de Medujo kaj Persujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Ĉar la Judo Mordeĥaj estis la dua post la reĝo Aĥaŝveroŝ, granda inter la Judoj kaj amata inter la multo de siaj fratoj, zorganta pri la bono de sia popolo kaj donanta pacon al sia tuta idaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Estis iu homo en la lando Uc, lia nomo estis Ijob. Tiu homo estis honesta, justa, diotima, kaj li evitadis malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Al li naskiĝis sep filoj kaj tri filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'Lia brutaro konsistis el sep mil ŝafoj, tri mil kameloj, kvincent paroj da bovoj, kvincent azeninoj, kaj li havis tre multe da servistoj; kaj tiu homo estis pli eminenta, ol ĉiuj filoj de la oriento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Liaj filoj havis la kutimon faradi festenon en la domo de ĉiu el ili, ĉiu en sia tago; kaj ili invitadis siajn tri fratinojn, por manĝi kaj trinki kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Kaj ĉiufoje, kiam la rondo de la festenaj tagoj estis finita, Ijob sendis, por sanktigi ilin, kaj li leviĝis frue matene kaj alportis bruloferojn laŭ la nombro de ili ĉiuj; ĉar, diris Ijob: Eble miaj filoj pekis kaj blasfemis Dion en sia koro. Tiel agadis Ijob ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Unu tagon, kiam la filoj de Dio venis, por stariĝi antaŭ la Eternulo, venis inter ili ankaŭ Satano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Kaj la Eternulo diris al Satano: De kie vi venas? Kaj Satano respondis al la Eternulo, kaj diris: Mi vagadis sur la tero kaj rondiradis sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Kaj la Eternulo diris al Satano: Ĉu vi atentis Mian servanton Ijob? ne ekzistas ja sur la tero homo simila al li, tiel honesta, justa, diotima, kaj evitanta malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Kaj Satano respondis al la Eternulo, kaj diris: Ĉu vane Ijob timas Dion?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Vi ŝirmis ja ĉiuflanke lin kaj lian domon, kaj ĉion, kio apartenas al li; la farojn de liaj manoj Vi benis, kaj liaj brutaroj disvastiĝis sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Sed etendu nur Vian manon, kaj ektuŝu ĉion, kion li havas; Vi vidos, ĉu li ne blasfemos Vin antaŭ Via vizaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Tiam la Eternulo diris al Satano: Jen ĉio, kion li havas, estas transdonata en vian manon; nur sur lin mem ne etendu vian manon. Kaj Satano foriris de antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Unu tagon, kiam liaj filoj kaj liaj filinoj estis manĝantaj kaj trinkantaj vinon en la domo de ilia unuenaskita frato,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'venis sendito al Ijob, kaj diris: Dum la bovoj estis plugantaj kaj la azeninoj estis paŝtiĝantaj apud ili,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'superfalis ilin la Ŝebaanoj, kaj forprenis ilin; kaj la servistojn ili mortigis per glavo; saviĝis nur mi sola, por raporti al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Kiam ankoraŭ tiu parolis, venis alia, kaj diris: Fajro de Dio falis el la ĉielo, bruligis la ŝafojn kaj la servistojn, kaj ekstermis ilin; saviĝis nur mi sola, por raporti al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Kiam tiu ankoraŭ parolis, venis alia, kaj diris: La Ĥaldeoj aranĝis tri taĉmentojn, atakis la kamelojn kaj forprenis ilin, kaj la servistojn ili mortigis per glavo; saviĝis nur mi sola, por raporti al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Dum tiu ankoraŭ parolis, venis alia, kaj diris: Viaj filoj kaj viaj filinoj estis manĝantaj kaj trinkantaj vinon en la domo de ilia unuenaskita frato;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'kaj jen granda vento leviĝis de la flanko de la dezerto, puŝis la kvar angulojn de la domo, kaj ĉi tiu falis sur la junulojn, kaj ili mortis; saviĝis nur mi sola, por raporti al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Tiam Ijob leviĝis, disŝiris sian veston, pritondis sian kapon, ĵetis sin sur la teron, kaj adorkliniĝis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'kaj li diris: Nuda mi eliris el la ventro de mia patrino, kaj nuda mi revenos tien; la Eternulo donis, kaj la Eternulo prenis; la nomo de la Eternulo estu benata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'Malgraŭ ĉio ĉi tio Ijob ne pekis, kaj ne eldiris blasfemon kontraŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Unu tagon, kiam la filoj de Dio venis, por stariĝi antaŭ la Eternulo, venis ankaŭ Satano inter ili, por stariĝi antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Kaj la Eternulo diris al Satano: De kie vi venas? Kaj Satano respondis al la Eternulo, kaj diris: Mi vagadis sur la tero kaj rondiradis sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Kaj la Eternulo diris al Satano: Ĉu vi atentis Mian servanton Ijob? ne ekzistas sur la tero homo simila al li, tiel honesta, justa, diotima, kaj evitanta malbonon; kaj li ĝis nun ankoraŭ estas firma en sia virteco, kvankam vi ekscitis Min kontraŭ li, por pereigi lin senkulpe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Tiam Satano respondis al la Eternulo, kaj diris: Haŭto pro haŭto; kaj ĉion, kion homo posedas, li fordonus pro sia vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Sed etendu Vian manon, kaj tuŝu liajn ostojn kaj lian karnon; tiam Vi vidos, ke li blasfemos Vin antaŭ Via vizaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'La Eternulo diris al Satano: Jen li estas transdonata en vian manon; nur lian vivon konservu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Satano foriris de antaŭ la vizaĝo de la Eternulo, kaj frapis Ijobon per turmentaj abscesoj de la plando de lia piedo ĝis lia verto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Li prenis potpecon, por skrapadi sin per ĝi, sidante meze de cindro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Kaj lia edzino diris al li: Vi ĉiam ankoraŭ estas firma en via virteco! blasfemu Dion, kaj mortu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Sed li diris al ŝi: Vi parolas tiel, kiel parolas iu el la malsaĝulinoj; ĉu bonon ni akceptu de Dio, kaj malbonon ni ne akceptu? Malgraŭ ĉio ĉi tio Ijob ne pekis per siaj lipoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Kiam la tri amikoj de Ijob aŭdis pri tiu tuta malfeliĉo, kiu trafis lin, ili iris ĉiu de sia loko, Elifaz, la Temanano, Bildad, la Ŝuĥano, kaj Cofar, la Naamano, kaj kunvenis kune, por iri plori kun li kaj konsoli lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Kiam ili levis siajn okulojn de malproksime, ili ne rekonis lin; kaj ili levis sian voĉon kaj ekploris; kaj ĉiu el ili disŝiris sian veston, kaj ĵetis teron sur sian kapon, turnante sin al la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Kaj ili sidis kun li sur la tero dum sep tagoj kaj sep noktoj, kaj ne parolis al li eĉ unu vorton; ĉar ili vidis, ke la suferado estas tre granda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Poste Ijob malfermis sian buŝon, kaj malbenis sian tagon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Kaj Ijob ekparolis, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Pereu la tago, en kiu mi naskiĝis, Kaj la nokto, kiu diris: Embriiĝis homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Tiu tago estu malluma; Dio de supre ne rigardu ĝin, Neniu lumo ekbrilu super ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Mallumo kaj tomba ombro ekposedu ĝin; Nubo ĝin kovru; Eklipsoj de tago faru ĝin terura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Tiun nokton prenu mallumego; Ĝi ne alkalkuliĝu al la tagoj de la jaro, Ĝi ne eniru en la kalkulon de la monatoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Ho, tiu nokto estu soleca; Neniu ĝojkrio aŭdiĝu en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Malbenu ĝin la malbenantoj de la tago, Tiuj, kiuj estas pretaj eksciti levjatanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Mallumiĝu la steloj de ĝia krepusko; Ĝi atendu lumon, kaj ĉi tiu ne aperu; Kaj la palpebrojn de matenruĝo ĝi ne ekvidu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'Pro tio, ke ĝi ne fermis la pordon de la utero de mia patrino Kaj ne kaŝis per tio la malfeliĉon antaŭ miaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Kial mi ne mortis tuj el la utero, Ne senviviĝis post la eliro el la ventro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Kial akceptis min la genuoj? Por kio estis la mamoj, ke mi suĉu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Mi nun kuŝus kaj estus trankvila; Mi dormus kaj havus ripozon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'Kune kun la reĝoj kaj la konsilistoj sur la tero, Kiuj konstruas al si izolejojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'Aŭ kun la potenculoj, kiuj havas oron, Kiuj plenigas siajn domojn per arĝento;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'Aŭ kiel abortitaĵo kaŝita mi ne ekzistus, Simile al la infanoj, kiuj ne vidis lumon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Tie la malpiuloj ĉesas tumulti; Kaj tie ripozas tiuj, kies fortoj konsumiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'Tie la malliberuloj kune havas ripozon; Ili ne aŭdas la voĉon de premanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Malgranduloj kaj granduloj, tie ili estas; Kaj sklavo estas libera de sia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Por kio al suferanto estas donita la lumo, Kaj la vivo al tiuj, kiuj havas maldolĉan animon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'Kiuj atendas la morton, kaj ĝi ne aperas, Kiuj elfosus ĝin pli volonte ol trezorojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'Kiuj ekĝojus kaj estus ravitaj, Se ili trovus tombon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'Al la homo, kies vojo estas kaŝita, Kaj antaŭ kiu Dio starigis barilon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Antaŭ ol mi ekmanĝas panon, mi devas ĝemi, Kaj mia plorkriado verŝiĝas kiel akvo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Ĉar teruraĵo, kiun mi timis, trafis min, Kaj tio, pri kio mi estis maltrankvila, venis al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Mi ne havas trankvilon, mi ne havas kvieton, mi ne havas ripozon; Trafis min kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Kaj ekparolis Elifaz, la Temanano, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Se oni provos diri al vi vorton, tio eble estos por vi turmenta? Sed kiu povas deteni sin de parolado?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Jen vi multajn instruis, Kaj manojn senfortiĝintajn vi refortigis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Falantojn restarigis viaj vortoj, Kaj fleksiĝantajn genuojn vi fortigis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Kaj nun, kiam tio trafis vin, vi perdis la forton; Ĝi ektuŝis vin, kaj vi ektimis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Ĉu ne via timo antaŭ Dio estas via konsolo? Ĉu la virteco de viaj vojoj ne estas via espero?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Rememoru do, ĉu pereis iu senkulpa? Kaj kie virtuloj estis ekstermitaj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Kiel mi vidis, tiuj, kiuj plugis pekojn kaj semis malbonagojn, Tiuj ilin rikoltas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'De la ekblovo de Dio ili pereas, Kaj de la ekspiro de Lia kolero ili malaperas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'La kriado de leono kaj la voĉo de leopardo silentiĝis, Kaj la dentoj de junaj leonoj rompiĝis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Leono pereis pro manko de manĝaĵo, Kaj idoj de leonino diskuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Kaj al mi kaŝe alvenis vorto, Kaj mia orelo kaptis parteton de ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'Dum meditado pri la vizioj de la nokto, Kiam profunda dormo falas sur la homojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'Atakis min teruro kaj tremo, Kaj ĉiuj miaj ostoj eksentis timon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Kaj spirito traflugis antaŭ mi, Kaj la haroj sur mia korpo rigidiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Staris bildo antaŭ miaj okuloj, sed mi ne povis rekoni ĝian aspekton; Estis silento, kaj mi ekaŭdis voĉon, dirantan:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, 'Ĉu homo estas pli justa ol Dio? Ĉu viro estas pli pura ol lia Kreinto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Vidu, al Siaj servantoj Li ne konfidas, Kaj Siajn anĝelojn Li trovas mallaŭdindaj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'Des pli koncerne tiujn, Kiuj loĝas en argilaj dometoj, Fonditaj sur tero, Kaj kiujn formanĝas vermoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'De la mateno ĝis la vespero ili disfalas, Pereas por ĉiam, kaj neniu tion atentas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'La fadeno de ilia vivo estas distranĉita; Ili mortas, kaj ne en saĝeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Voku do! ĉu iu respondos al vi? Kaj al kiu el la sanktuloj vi vin turnos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Malsaĝulon mortigas la kolero, Kaj sensenculon pereigas la incitiĝemeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Mi vidis malsaĝulon, kiu enradikiĝis, Kaj mi malbenis subite lian loĝejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Malproksimaj de savo estos liaj filoj; Oni disbatos ilin ĉe la pordego, Kaj neniu ilin savos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Lian rikoltaĵon formanĝos malsatulo, El inter la dornoj li ĝin prenos, Kaj soifantoj englutos lian havaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Ne el la polvo eliras malpiaĵo, Kaj ne el la tero elkreskas malbonago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'Sed homo naskiĝas por suferoj, Kiel birdoj por flugado supren.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Sed mi min turnus al Dio, Kaj al Li mi transdonus mian aferon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'Al Tiu, kiu faras grandaĵojn, kiujn neniu povas esplori, Mirindaĵojn, kiujn neniu povas kalkuli;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'Kiu donas pluvon sur la teron Kaj sendas akvon sur la kampojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'Por starigi malaltulojn alte, Ke la afliktitoj leviĝu savite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Li detruas la intencojn de ruzuloj, Ke iliaj manoj ne plenumas sian entreprenon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'Li kaptas la saĝulojn per ilia ruzaĵo; Kaj la decido de maliculoj fariĝas senvalora.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'En la tago ili renkontas mallumon, Kaj en tagmezo ili palpas, kiel en nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Li savas kontraŭ glavo, Kontraŭ la buŝo kaj mano de potenculo Li savas malriĉulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'Al la senhavulo aperas espero, Kaj la malboneco fermas sian buŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Feliĉa estas la homo, kiun punas Dio; Kaj la moralinstruon de la Plejpotenculo ne malŝatu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Ĉar Li vundas, sed ankaŭ bandaĝas; Li batas, sed Liaj manoj ankaŭ resanigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'En ses malfeliĉoj Li vin savos; En la sepa ne tuŝos vin la malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'En tempo de malsato Li savos vin de la morto, Kaj en milito el la mano de glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Kontraŭ la vipo de lango vi estos kaŝita; Kaj vi ne timos ruinigon, kiam ĝi venos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Dum ruinigo kaj malsato vi ridos; Kaj la bestojn de la tero vi ne timos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'Ĉar kun la ŝtonoj de la kampo vi havos interligon, Kaj la bestoj de la kampo havos pacon kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'Kaj vi ekscios, ke paco estas en via tendo; Vi esploros vian loĝejon, kaj nenio mankos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Kaj vi ekscios, ke grandnombra estas via idaro Kaj via naskitaro estas kiel la herbo de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'En maljuneco vi iros en la tombon, Kiel envenas garbaro en sia tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Vidu, ni tion esploris, kaj tiel ĝi estas; Atentu tion, kaj sciu tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Ijob respondis kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'Se estus pesita mia ĉagreno, Kaj samtempe estus metita sur la pesilon mia suferado,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Ĝi estus nun pli peza, ol la sablo ĉe la maroj; Pro tio miaj vortoj estas plenaj de plendo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Ĉar la sagoj de la Plejpotenculo estas en mi, Ilian venenon trinkas mia spirito; La teruraĵoj de Dio direktiĝis sur min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Ĉu krias sovaĝa azeno sur herbo? Ĉu bovo blekas kolere ĉe sia manĝaĵo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Ĉu oni manĝas sengustaĵon sen salo? Ĉu havas guston la albumeno de ovo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Kion ne volis tuŝi mia animo, Tio nun estas abomeninde mia manĝaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'Ho, se mia peto plenumiĝus, Kaj se Dio donus al mi tion, kion mi esperas!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Ho, se Dio komencus kaj disbatus min, Donus liberecon al Sia mano kaj frakasus min!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Tio estus ankoraŭ konsolo por mi; Kaj mi ĝojus, se en la turmento Li ne kompatus, Ĉar mi ne forpuŝis ja la vortojn de la Sanktulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Kio estas mia forto, ke mi persistu? Kaj kia estas mia fino, ke mi havu paciencon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Ĉu mia forto estas forto de ŝtonoj? Ĉu mia karno estas kupro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Mi havas ja nenian helpon, Kaj savo estas forpuŝita for de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Al malfeliĉulo decas kompato de amiko, Eĉ se li forlasas la timon antaŭ la Plejpotenculo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Miaj fratoj trompas kiel torento, Kiel akvaj fluegoj, kiuj pasas,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'Kiuj estas malklaraj pro glacio, En kiuj kaŝas sin neĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'En la tempo de degelo ili malaperas, En la tempo de varmego ili forŝoviĝas de sia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Ili forklinas la direkton de sia vojo, Iras en la dezerton, kaj malaperas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Serĉas ilin per sia rigardo la vojoj de Tema, Esperas je ili la karavanoj el Ŝeba;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Sed ili hontas pro sia fido; Ili aliras, kaj ruĝiĝas de honto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Nun vi neniiĝis; Vi ekvidis teruraĵon, kaj ektimis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Ĉu mi diris: Donu al mi, El via havaĵo donacu pro mi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'Savu min el la mano de premanto, Aŭ liberigu min el la mano de turmentantoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Instruu min, kaj mi eksilentos; Komprenigu al mi, per kio mi pekis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Kial vi mallaŭdas pravajn vortojn? Kaj kion povas instrui la moralinstruanto el vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Ĉu vi intencas riproĉi pro vortoj? Sed paroloj de malesperanto iras al la vento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'Eĉ orfon vi atakus, Kaj sub via amiko vi fosus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Nun, ĉar vi komencis, rigardu min; Ĉu mi mensogos antaŭ via vizaĝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Rigardu denove, vi ne trovos malpiaĵon; Ripetu, vi trovos mian pravecon en la afero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Ĉu estas peko sur mia lango? Ĉu mia palato ne komprenas tion, kio estas malbona?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Difinita estas ja por la homo la limtempo sur la tero, Kaj liaj tagoj estas kiel la tagoj de dungito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Kiel sklavo, kiu sopiras al ombro, Kaj kiel dungito, kiu atendas sian pagon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'Tiel mi ricevis sorte monatojn vantajn, Kaj noktoj turmentaj estas nombritaj al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Kiam mi kuŝiĝas, mi diras: Kiam mi leviĝos? Sed la vespero fariĝas longa, kaj mi satiĝas de maltrankvileco ĝis la tagiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Mia korpo estas kovrita de vermoj kaj de pecoj da tero; Mia haŭto krevis kaj putras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Miaj tagoj forflugis pli facile, ol bobeno de teksisto, Kaj pasis, lasinte nenian esperon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Memoru, ke mia vivo estas bloveto, Ke miaj okuloj ne plu revidos bonon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Ne plu revidos min okulo de vidanto; Vi volos ekrigardi min, sed mi jam ne ekzistos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Nubo pasas kaj foriras; Tiel ne plu revenas tiu, kiu iris en Ŝeolon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Li ne plu revenas en sian domon; Lia loko ne plu rekonos lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Tial mi ne detenos mian buŝon; Mi parolos en la premiteco de mia spirito, Mi plendos en la maldolĉeco de mia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Ĉu mi estas maro aŭ mara monstro, Ke Vi starigis gardon por mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Kiam mi pensas, ke mia lito min konsolos, Ke mia kuŝejo plifaciligos mian suferadon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'Tiam Vi teruras min per sonĝoj, Timigas min per vizioj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'Kaj mia animo deziras sufokiĝon, Miaj ostoj la morton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Tedis al mi; ne eterne mi vivu; Forlasu min, ĉar miaj tagoj estas vantaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Kio estas homo, ke Vi faras lin granda, Ke Vi zorgas pri li,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'Ke Vi rememoras lin ĉiumatene, Elprovas lin ĉiumomente?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Kial Vi ne deturnas Vin de mi, Ne lasas min libera eĉ tiom, ke mi povu engluti mian salivon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Se mi pekis, kion mi per tio faris al Vi, ho gardanto de la homoj? Kial Vi faris min celo de Viaj atakoj, Ke mi fariĝis ŝarĝo por mi mem?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Kaj kial Vi ne deprenas mian pekon, ne pardonas mian malbonagon? Jen mi ja baldaŭ kuŝos en la tero; Kaj kiam Vi morgaŭ serĉos min, mi ne ekzistos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Kaj ekparolis Bildad, la Ŝuĥano, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Kiel longe vi tiel parolos, Kaj la vortoj de via buŝo estos kiel forta vento?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Ĉu Dio falsas la juĝon? Ĉu la Plejpotenculo falsas la justecon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Se viaj filoj pekis kontraŭ Li, Li forpuŝis ilin pro ilia malbonago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Se vi serĉas Dion Kaj petegas la Plejpotenculon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'Se vi estas pura kaj pia, Li maldormos super vi, Kaj restarigos la bonstaton en via virta loĝejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Kaj se via komenco estis malgranda, Via estonteco forte kreskos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Ĉar demandu la antaŭajn generaciojn, Kaj primeditu tion, kion esploris iliaj patroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Ĉar ni estas de hieraŭ, kaj ni nenion scias; Nia vivo sur la tero estas nur ombro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Ili instruos vin, diros al vi, Kaj el sia koro elirigos vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Ĉu povas kreski kano sen malsekeco? Ĉu kreskas junko sen akvo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'En tia okazo ĝi velksekiĝas pli frue ol ĉiu herbo, Kiam ĝi estas ankoraŭ en sia freŝeco, Kiam ĝi ankoraŭ ne estas detranĉita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Tiaj estas la vojoj de ĉiuj, kiuj forgesas Dion; Kaj pereas la espero de hipokritulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Kies fido dehakiĝas, Kaj kies espero estas araneaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Li apogas sin al sia domo, sed ne restos staranta; Li ekkaptos ĝin, sed ne povos sin teni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Li estis verda antaŭ la suno, Kaj super lia ĝardeno etendiĝas liaj branĉoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Amase plektiĝas liaj radikoj, Inter ŝtonoj ili tenas sin forte;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Sed kiam oni elŝiras lin el lia loko, Ĝi malkonfesas lin: Mi vin ne vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Tia estas la ĝojo de lia vivo; Kaj el la tero kreskas aliaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Vidu, Dio ne forpuŝas virtulon Kaj ne subtenas la manon de malpiuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Li plenigos ankoraŭ vian buŝon per rido Kaj viajn lipojn per ĝojkrioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Viaj malamantoj kovriĝos per honto; Sed la tendo de malpiuloj malaperos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Ijob respondis kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'Certe, mi scias, ke tiel estas; Kaj kiel povas homo esti prava koncerne Dion?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Se li volus havi kun Li juĝan disputon, Li ne povus respondi al Li eĉ unu kontraŭ mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Li estas saĝa per Sia koro kaj potenca per Sia forto; Kiu kuraĝus stari kontraŭ Li kaj restus sendifekta?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Li forŝovas montojn, kaj ili eĉ ne rimarkas, Ke Li renversis ilin en Sia kolero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'Li skuas la teron de ĝia loko, Ke ĝiaj kolonoj tremas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'Li diras al la suno, kaj ĝi ne leviĝas, Kaj la stelojn Li sigelfermas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'Li sola etendas la ĉielon, Kaj Li iras sur la altaĵoj de la maro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'Li kreis la Grandan Ursinon, Orionon, kaj Plejadojn, Kaj la stelojn de la sudo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'Li faras neesploreblajn grandaĵojn, Kaj nekalkuleblajn mirindaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Jen Li preteriros preter mi, kaj mi tion eĉ ne vidos; Li pasos, kaj mi eĉ ne rimarkos Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Kiam Li kaptas, kiu malpermesus al Li? Kiu dirus al Li: Kion Vi faras?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Li estas Dio, kaj Lian koleron oni ne povas haltigi; Sub Li fleksiĝas la helpantoj de Rahab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Des pli ĉu mi povus respondi al Li, Ĉu mi povus elekti vortojn kontraŭ Li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Eĉ se mi estus prava, mi ne respondus; Sed mi nur petegus mian juĝanton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Se mi vokus kaj Li respondus, Mi ne kredus, ke Li aŭdis mian voĉon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Li, kiu povas frakasi min per ventego Kaj fari al mi senkulpe multe da vundoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Li ne permesas al mi trankviligi mian spiriton, Sed Li satigas min per maldolĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Se oni volas forton, Li estas potenca; Se oni volas juĝon, kiu alvokos min?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Se mi montros mian pravecon, mia propra buŝo min kondamnos; Se mi montros min virtulo, Li montros min malbonagulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Mi estas senkulpa; mi ne zorgas pri mia animo, Mi abomenas mian vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Ĉio estas egala; tial mi diras: Senkulpulon kaj malpiulon Li ambaŭ pereigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Kiam vipo subite ekbatas, Li ridas ĉe la elprovado de senkulpuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'La tero estas transdonita en la manon de malpiulo; La vizaĝon de ĝiaj juĝistoj Li kovras. Se ne Li, tiam kiu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Miaj tagoj estis pli rapidpiedaj ol kuristo; Ili forkuris, ne vidis bonon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'Ili forkuris, kiel ŝipetoj el kano, Kiel aglo flugas al manĝotaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Se mi ekpensas: Mi forgesos mian plendon, Mi farlasos mian mienon, kaj mi min gajigos:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'Tiam mi ektremas pro ĉiuj miaj suferoj; Mi scias, ke Vi ne rigardos min kiel senkulpan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Mi restos ja malprava; Por kio do mi vane min turmentas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Se mi lavus min per neĝa akvo Kaj purigus miajn manojn per lesivo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'Eĉ tiam Vi trempus min en koto, Kaj miaj vestoj min abomenus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Ĉar Li ne estas homo simile al mi, Ke mi povu respondi al Li, Ke ni povu ambaŭ iri al juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Ne ekzistas inter ni arbitracianto, Kiu povus meti sian manon sur nin ambaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Li forigu de mi Sian vergon, Kaj Lia teruro ne timigu min;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'Tiam mi ekparolos, kaj ne timos Lin, Ĉar ne tia mi estas en mi mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Tedis al mia animo mia vivo; Mi fordonos min al mia plendado; Mi parolos en la malĝojeco de mia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Mi diros al Dio: Ne kondamnu min, Sciigu al mi, pro kio Vi malpacas kontraŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Ĉu Vi trovas tion bona, ke Vi turmentas, Ke Vi forpuŝas la laboritaĵon de Viaj manoj, Sendas brilon sur la entreprenon de malpiuloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Ĉu Vi havas okulojn karnajn, Kaj ĉu Vi rigardas, kiel homo rigardas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Ĉu Viaj tagoj estas kiel la tagoj de homo, Aŭ ĉu Viaj jaroj estas kiel la vivtempo de homo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'Ke Vi serĉas mian kulpon Kaj penas trovi mian pekon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'Kvankam Vi scias, ke mi ne estas malbonagulo, Sed el Via mano neniu povas savi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Viaj manoj min formis kaj faris min tutan ĉirkaŭe, Kaj tamen Vi min pereigas!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Rememoru, ke kiel argilon Vi min prilaboris; Kaj Vi returne faros min polvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Vi elverŝis ja min kiel lakton, Kaj kiel fromaĝon Vi min kundensigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Per haŭto kaj karno Vi min vestis, Per ostoj kaj tendenoj Vi min plektis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Vivon kaj bonon Vi donis al mi, Kaj Via prizorgado gardis mian spiriton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Sed ĉi tion Vi kaŝis en Via koro; Mi scias, ke Vi tion intencis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Se mi pekos, Vi tion rimarkos sur mi, Kaj mian pekon Vi ne lasos senpuna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Se mi agis malbone, ve al mi! Se mi estas prava, mi ne povas tamen levi mian kapon, Estante tute humiligita Kaj vidante mian mizeron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Se ĝi leviĝas, Vi ĉasas min kiel leono, Kaj denove montras sur mi Vian mirindan potencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Vi elmetas kontraŭ mi novajn atestojn, Plifortigas Vian koleron kontraŭ mi; Nova armeo min atakas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Por kio Vi elirigis min el la ventro? Ho, se mi estus pereinta, ke nenies okulo min vidu!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Tiam mi estus kiel ne estinta; El la ventro mi estus transportita en la tombon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Mia vivo estas ja mallonga; Ĉesu do, lasu min libera, por ke mi iom revigliĝu,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'Antaŭ ol mi foriros senrevene En la landon de mallumo kaj de morta ombro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'En la landon, kie la lumo estas kiel mallumo, Kie estas morta ombro kaj senordeco, Kie estas lume kiel en mallumego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Kaj ekparolis Cofar, la Naamano, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'Ĉu kontraŭ multe da vortoj oni ne povas doni respondon? Kaj ĉu tiu, kiu multe parolas, estas prava?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Ĉu via senenhava parolado devas silentigi la homojn, Por ke vi mokinsultu kaj neniu vin hontigu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Vi diras: Mia opinio estas ĝusta, Kaj mi estas pura antaŭ Viaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Sed ho, se Dio ekparolus, Kaj malfermus antaŭ vi Siajn lipojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'Kaj malkaŝus antaŭ vi la sekretojn de la saĝo, Kiu havas multoblan forton! Sciu, ke ne ĉiujn viajn pekojn Dio rememoras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Ĉu vi povas eltrovi la esencon de Dio? Ĉu vi povas plene kompreni la perfektecon de la Plejpotenculo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Tio estas pli alta ol la ĉielo; Kion vi povas fari? Tio estas pli profunda ol Ŝeol; Kion vi povas ekscii?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Pli longa ol la tero estas ĝia mezuro, Kaj pli larĝa ol la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Se Li preteriros, kaj fermos, kaj faros juĝon, Tiam kiu repuŝos Lin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Ĉar Li konas la homojn malvirtajn; Li vidas la malbonagojn, kiujn oni ne rimarkas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'Eĉ vanta homo devas kompreni, Eĉ homo, kiu naskiĝis sovaĝulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Se vi aranĝas vian koron Kaj etendas al Li viajn manojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'Se vi forigas la malvirton, kiu estas en via mano, Kaj vi ne permesos al malbonaĵoj resti en via tendo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'Tiam vi povos levi vian vizaĝon sen difekto; Vi estos firma kaj ne timos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Tiam vi forgesos mizeron; Vi rememoros ĝin kiel forfluintan akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'Kaj via vivo leviĝos pli hele ol la tagmezo, La mallumo fariĝos kiel mateno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Kaj vi estos trankvila, ĉar ekzistas espero; Vi rigardos ĉirkaŭen, kaj iros dormi en sendanĝereco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Vi kuŝos, kaj neniu vin timigos; Kaj multaj serĉos vian favoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Sed la okuloj de malpiuloj konsumiĝos, Pereos por ili la rifuĝo, Kaj ilia espero elspiros sian vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Kaj Ijob respondis kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'Certe, vi solaj estas homoj, Kaj kun vi mortos la saĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Mi ankaŭ havas koron, kiel vi; Mi ne estas malpli valora ol vi; Kiu ne povas paroli tiele?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Mi fariĝis mokataĵo por mia amiko, Mi, kiu vokadis al Dio kaj estis aŭskultata; Virtulo kaj senkulpulo fariĝis mokataĵo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Malestimata lucerneto li estas antaŭ la pensoj de feliĉuloj, Pretigita por migrantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Bonstataj estas la tendoj de rabistoj, Kaj sendanĝerecon havas la incitantoj de Dio, Tiuj, kiuj portas Dion en sia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Vere, demandu la brutojn, kaj ili instruos vin; La birdojn de la ĉielo, kaj ili diros al vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Aŭ parolu kun la tero, kaj ĝi klarigos al vi; Kaj rakontos al vi la fiŝoj de la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Kiu ne ekscius el ĉio ĉi tio, Ke la mano de la Eternulo tion faris,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'De Tiu, en kies mano estas la animo de ĉio vivanta Kaj la spirito de ĉiu homa karno?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'La orelo esploras ja la parolon, Kaj la palato gustumas al si la manĝaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'La maljunuloj posedas saĝon, Kaj la grandaĝuloj kompetentecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Ĉe Li estas la saĝo kaj la forto; Ĉe Li estas konsilo kaj kompetenteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Kion Li detruas, tio ne rekonstruiĝas; Kiun Li enŝlosos, tiu ne liberiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Kiam Li digas la akvon, ĝi elsekiĝas; Kiam Li fluigas ĝin, ĝi renversas la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Ĉe Li estas potenco kaj forto; Lia estas tiu, kiu eraras, kaj tiu, kiu erarigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Li irigas konsilistojn kiel erarvagantojn, Kaj la juĝistojn Li faras malsaĝaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'La ligilojn de reĝoj Li malligas, Kaj Li ligas per zono iliajn lumbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Li erarvagigas la pastrojn Kaj faligas la potenculojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Li mutigas la lipojn de fidinduloj Kaj forprenas de maljunuloj la prudenton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Li verŝas honton sur eminentulojn Kaj malfirmigas la zonon de potenculoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'Li malkovras profundaĵon el meze de mallumo, Kaj mortan ombron Li elirigas en la lumon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Li grandigas naciojn kaj pereigas ilin, Disvastigas naciojn kaj forpelas ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'Li senkuraĝigas la ĉefojn de la popolo de la lando Kaj erarvagigas ilin en dezerto senvoja;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'Ili palpas en mallumo, en senlumeco; Kaj Li ŝanceliĝigas ilin kiel ebriuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Ĉion ĉi tion mia okulo vidis, Mia orelo aŭdis kaj komprenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Kion vi scias, mi ankaŭ scias; Kaj mi ne estas malpli valora ol vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Sed mi volus paroli kun la Plejpotenculo, Mi dezirus disputi kun Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Tamen vi komentarias malvere, Vi ĉiuj estas senutilaj kuracistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Ho, se vi silentus, Tio estus saĝeco de via flanko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Aŭskultu do mian moralinstruon, Kaj atentu la defendan parolon de mia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Ĉu pro Dio vi volas paroli malveron, Kaj pro Li paroli falsaĵon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Ĉu vi volas esti personfavoraj al Li, Aŭ pro Dio vi volas disputi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Ĉu estos bone, kiam Li esploros vin? Ĉu vi volas trompi Lin, kiel oni trompas homon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Li certe vin punos, Se vi sekrete estos personfavoraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Ĉu Lia majesto ne konfuzas vin? Ĉu ne falas sur vin timo antaŭ Li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Viaj memorigoj estas sentencoj polvaj, Via bastionoj estas amasoj da argilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Silentu antaŭ mi, kaj parolos mi, Kio ajn trafos min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Por kio mi portu mian karnon en miaj dentoj Kaj metu mian animon en mian manon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Li ja mortigos min, kaj mi ne havas esperon; Sed pri mia konduto mi volas disputi antaŭ Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Tio jam estos savo por mi, Ĉar ne hipokritulo venos antaŭ Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Aŭskultu mian parolon Kaj mian klarigon antaŭ viaj oreloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Jen mi pretigis juĝan aferon; Mi scias, ke mi montriĝos prava.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Kiu povas procesi kontraŭ mi? Tiam mi eksilentus kaj mortus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Nur du aferojn ne faru al mi, Tiam mi ne kaŝos min antaŭ Via vizaĝo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Malproksimigu de mi Vian manon, Kaj Via teruro ne timigu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Tiam voku, kaj mi respondos; Aŭ mi parolos, kaj Vi respondu al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Kiom da malbonagoj kaj pekoj estas sur mi? Sciigu al mi miajn krimojn kaj pekojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Kial Vi kaŝas Vian vizaĝon Kaj rigardas min kiel Vian malamikon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Ĉu Vi volas montri Vian forton kontraŭ deŝirita folio? Kaj ĉu sekiĝintan pajleron Vi volas persekuti?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Ĉar Vi skribas kontraŭ mi maldolĉaĵon Kaj venigas sur min la pekojn de mia juneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'Vi metis miajn piedojn en ŝtipon, Vi observas ĉiujn miajn vojojn, Kaj Vi observas la plandojn de miaj piedoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'Dum mi ja disfalas kiel putraĵo, Kiel vesto dismanĝita de tineoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'Homo, naskita de virino, Havas mallongan vivon kaj abundon da afliktoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Kiel floro li elkreskas kaj velkas; Li forkuras kiel ombro kaj ne restas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Kaj kontraŭ tia Vi malfermas Viajn okulojn, Kaj min Vi vokas al juĝo kun Vi!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Ĉu povas purulo deveni de malpurulo? Neniu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Se liaj tagoj estas difinitaj, la nombro de liaj monatoj estas ĉe Vi; Vi difinis lian limon, kiun li ne transpasos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Deturnu do Vin de li, ke li estu trankvila, Ĝis venos lia tempo, kiun li sopiras kiel dungito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Arbo havas esperon, se ĝi estas dehakita, ke ĝi denove ŝanĝiĝos, Kaj ĝi ne ĉesos kreskigi branĉojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Se ĝia radiko maljuniĝis en la tero, Kaj ĝia trunko mortas en polvo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'Tamen, eksentinte la odoron de akvo, ĝi denove verdiĝas, Kaj kreskas plue, kvazaŭ ĵus plantita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Sed homo mortas kaj malaperas; Kiam la homo finiĝis, kie li estas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Forfluas la akvo el lago, Kaj rivero elĉerpiĝas kaj elsekiĝas:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'Tiel homo kuŝiĝas, kaj ne plu leviĝas; Tiel longe, kiel la ĉielo ekzistas, ili ne plu vekiĝos, Nek revigliĝos el sia dormado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Ho, se Vi kaŝus min en Ŝeol, Se Vi kaŝus min ĝis la momento, kiam pasos Via kolero, Se Vi difinus por mi templimon kaj poste rememorus min!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Kiam homo mortas, ĉu li poste povas reviviĝi? Dum la tuta tempo de mia batalado mi atendus, Ĝi venos mia forŝanĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Vi vokus, kaj mi respondus al Vi; Vi ekdezirus la faritaĵon de Viaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Nun Vi kalkulas miajn paŝojn; Ne konservu mian pekon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Sigelu en paketo miajn malbonagojn, Kaj kovru mian kulpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Sed monto, kiu falas, malaperas; Kaj roko forŝoviĝas de sia loko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'Ŝtonojn forlavas la akvo, Kaj ĝia disverŝiĝo fordronigas la polvon de la tero: Tiel Vi pereigas la esperon de homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Vi premas lin ĝis fino, kaj li foriras; Li ŝanĝas sian vizaĝon, kaj Vi forigas lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Se liaj infanoj estas honorataj, li tion ne scias; Se ili estas humiligataj, li tion ne rimarkas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Nur lia propra korpo lin doloras, Nur pri sia propra animo li suferas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Ekparolis Elifaz, la Temanano, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'Ĉu saĝulo povas respondi per ventaj opinioj, Kaj plenigi sian ventron per sensencaĵoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Vi disputas per vortoj senutilaj, Kaj per paroloj, kiuj nenion helpas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Vi forigas la timon, Kaj senvalorigas preĝon antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Ĉar via malbonago instigas vian buŝon, Kaj vi elektis stilon de maliculoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Vin kondamnas via buŝo, ne mi; Kaj viaj lipoj atestas kontraŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Ĉu vi naskiĝis la unua homo? Ĉu vi estas kreita pli frue ol la altaĵoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Ĉu vi aŭdis la sekretan decidon de Dio, Kaj alkaptis al vi la saĝon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Kion vi scias tian, kion ni ne scias? Kion vi komprenas tian, kio al ni mankas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Inter ni estas grizuloj kaj maljunuloj, Kiuj vivis pli longe ol via patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Ĉu tiel malmulte valoras por vi la konsoloj de Dio Kaj vorto kvieta?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Kial vin tiel levas via koro, Kaj kial tiel palpebrumas viaj okuloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'Ke vi direktas kontraŭ Dion vian koleron, Kaj elirigis el via buŝo tiajn vortojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Kio estas homo, ke li povus esti pura Kaj ke naskito de virino povus esti prava?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Vidu, inter Liaj sanktuloj ne ĉiuj estas fidindaj, Kaj la ĉielo ne estas pura en Liaj okuloj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'Des pli homo, abomeninda kaj malbona, Kiu trinkas malbonagojn kiel akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Mi montros al vi, aŭskultu min; Kaj kion mi vidis, tion mi rakontos,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'Kion saĝuloj diris kaj ne kaŝis antaŭ siaj patroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'Al kiuj, al ili solaj, estis donita la tero, Kaj fremdulo ne trairis meze de ili:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'Dum sia tuta vivo malpiulo estas maltrankvila, Kaj la nombro de la jaroj de tirano estas kaŝita antaŭ li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Teruroj sonas en liaj oreloj; Meze de paco venas sur lin rabisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Li ne esperas, ke li saviĝos el mallumo; Kaj li serĉas ĉirkaŭe glavon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Li vagadas, serĉante panon; Li scias, ke preta estas en lia mano la tago de mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Teruras lin mizero kaj premateco, Venkobatas lin kiel reĝo, pretiĝinta por batalo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Pro tio, ke li etendis sian manon kontraŭ Dion Kaj kontraŭstaris al la Plejpotenculo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'Kuris kontraŭ Lin kun fiera kolo, Kun dikaj dorsoj de siaj ŝildoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'Li kovris sian vizaĝon per graso Kaj metis sebon sur siajn lumbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'Li loĝas en urboj ruinigitaj, En domoj ne loĝataj, Destinitaj esti ŝtonamasoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'Li ne restos riĉa, lia bonstato ne teniĝos, Kaj lia havaĵo ne disvastiĝos sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Li ne forkliniĝos de mallumo; Flamo velksekigos liajn branĉojn, Kaj Li forigos lin per la blovo de Sia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'La erarinto ne fidu vantaĵon, Ĉar vanta estos lia rekompenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Antaŭtempe li finiĝos, Kaj lia branĉo ne estos verda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Lia nematura bero estos deŝirita, kiel ĉe vinbertrunko; Kaj lia floro defalos, kiel ĉe olivarbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Ĉar la anaro de la hipokrituloj senhomiĝos; Kaj fajro ekstermos la tendojn de tiuj, kiuj prenas subaĉeton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Ili gravediĝis per malpiaĵo kaj naskis pekon, Kaj ilia ventro pretigas malicaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Ijob respondis kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'Mi aŭdis multe da similaj aferoj; Tedaj konsolantoj vi ĉiuj estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Ĉu estos fino al la ventaj vortoj? Kaj kio vin incitis, ke vi tiel parolas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Mi ankaŭ povus paroli, kiel vi. Se vi estus sur mia loko, Mi konsolus vin per vortoj Kaj balancus pri vi mian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'Mi fortigus vin per mia buŝo Kaj konsolus vin per paroloj de miaj lipoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Se mi parolos, mia doloro ne kvietiĝos; Se mi ĉesos, kio foriros de mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Sed nun Li lacigis min, Li detruis mian tutan esencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Vi faris al mi sulkojn, tio fariĝis atesto; Mia senfortiĝo staras antaŭ mia vizaĝo, kaj parolas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Lia kolero disŝiras; Mia malamanto grincigas kontraŭ mi siajn dentojn; Mia premanto briligas kontraŭ mi siajn okulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Ili malfermegis kontraŭ mi sian buŝon, insulte batas min sur la vangojn; Ĉiuj kune kontentigis sur mi sian koleron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Dio transdonis min al maljustulo, Ĵetis min en la manojn de malbonuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Mi estis trankvila; sed Li frakasis min, Li kaptis min je la kolo, disbatis min, Kaj Li faris min por Si celo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Liaj pafistoj min ĉirkaŭis; Li dishakas miajn internaĵojn kaj ne kompatas, Li elverŝas sur la teron mian galon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Li faras en mi breĉon post breĉo, Li kuras kontraŭ min kiel batalisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Sakaĵon mi kudris sur mian korpon, Kaj en polvo mi kaŝis mian kornon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Mia vizaĝo ŝvelis de plorado, Kaj sur miaj palpebroj estas morta ombro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'Kvankam ne troviĝas perfortaĵo en miaj manoj, Kaj mia preĝo estas pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Ho tero, ne kovru mian sangon, Kaj mia kriado ne trovu haltejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Vidu, en la ĉielo estas mia atestanto, Kaj mia konanto estas en la altaj sferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Parolistoj estas por mi miaj amikoj; Sed mia okulo larmas al Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'Ke Li decidu inter homo kaj Dio, Inter homo kaj lia amiko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Ĉar la nombro de la jaroj pasos, Kaj mi iros sur vojon nereveneblan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Mia spirito senfortiĝis, miaj tagoj mallongiĝis, Tomboj estas antaŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Mokado min ĉirkaŭas; En aflikto pro tio restas mia okulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Estu Vi mem mia garantianto antaŭ Vi; Alie kiu donos la manon pro mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Ĉar ilian koron Vi kovris kontraŭ prudento; Tial Vi ne donos al ili triumfon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Se iu fanfaronas antaŭ siaj amikoj pri sia parto, La okuloj de liaj infanoj konsumiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Li faris min proverbo por la popoloj; Kaj mi fariĝis homo, al kiu oni kraĉas en la vizaĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Mia okulo mallumiĝis de ĉagreno, Kaj ĉiuj miaj membroj fariĝis kiel ombro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'La justuloj eksentos teruron pro tio, Kaj la senkulpulo ekscitiĝos kontraŭ la hipokritulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Tamen la virtulo forte konservos sian vojon, Kaj la purmanulo pli firmiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Kaj kiom ajn vi ĉiuj revenos, Mi ne trovos inter vi saĝulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Miaj tagoj forpasis, pereis miaj intencoj, Kiujn havis mia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'La nokton ili volas fari tago, La lumon alproksimigi al la mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Se mi atendas, tamen Ŝeol estas mia domo, En la mallumo estas pretigita mia lito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'Al la kavo mi diras: Vi estas mia patro; La vermojn mi nomas mia patrino kaj mia fratino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'Kion mi devas atendi? Kiu atentos mian esperon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'En la profundon de Ŝeol ĝi malsupreniros, Ni ambaŭ kune kuŝos en la polvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Ekparolis Bildad, la Ŝuĥano, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, 'Kiam vi ĉesos ĵetadi vortojn? Pripensu, kaj poste ni parolos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Kial ni estu rigardataj kiel brutoj, Kaj ni estu malpuruloj en viaj okuloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Ho vi, kiu disŝiras sian animon en sia kolero, Ĉu por vi estu forlasata la tero, Kaj roko forŝoviĝu de sia loko?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'La lumo de la malpiulo estingiĝos, Kaj ne brilos la flamo de lia fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'La lumo mallumiĝos en lia tendo, Kaj lia lucerno super li estingiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Mallongiĝos liaj fortaj paŝoj, Kaj lia propra intenco lin faligos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Ĉar li trafis per siaj piedoj en reton, Kaj li moviĝas en kaptilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'La maŝo enkroĉigos lian kalkanon, Kaj pereo lin atakos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Kaŝita en la tero estas lia falilo, Kaj kaptiloj kontraŭ li estas sur la vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'De ĉiuj flankoj timigos lin teruroj Kaj atakos liajn piedojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Malsato konsumos lian forton, Kaj pereo estas preparita por liaj flankoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Konsumiĝos la membroj de lia korpo, Liajn membrojn konsumos la unuenaskito de la morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Lia espero estos elŝirita el lia tendo, Kaj ĝi pelos lin al la reĝo de teruroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'Nenio restos en lia tendo; Sur lian loĝejon ŝutiĝos sulfuro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Malsupre sekiĝos liaj radikoj, Kaj supre detranĉiĝos liaj branĉoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'La memoro pri li malaperos de sur la tero, Kaj sur la stratoj li ne havos nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'Li estos elpelita el lumo en mallumon, Kaj el la mondo li estos elpuŝita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Nek filon nek nepon li havos en sia popolo, Kaj neniu restos ĉe li en lia loĝloko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'La posteuloj sentos teruron pri lia tago, Kaj la antaŭulojn kaptos timo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Tia estas la loĝejo de maljustulo, Kaj tia estas la loko de tiu, kiu ne konas Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Ijob respondis kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, 'Ĝis kiam vi afliktados mian animon Kaj turmentados min per paroloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Jen jam dek fojojn vi malhonoras min; Vi ne hontas premi min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Se mi efektive eraris, Mia eraro restos ĉe mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Se efektive vi volas montri vin pli grandaj ol mi, Kaj vi riproĉas al mi hontindaĵon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'Tiam sciu, ke Dio faris al mi maljustaĵon, Kaj ĉirkaŭis min per Sia reto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Jen mi krias pri maljusteco, sed mi ne ricevas respondon; Mi vokas, sed mi ne ricevas juĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Mian vojon Li baris, ke mi ne povas transiri, Kaj sur mian irejon Li metis mallumon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Mian honoron Li detiris de mi, Kaj deprenis la kronon de mia kapo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Li disbatis min ĉirkaŭe tiel, ke mi pereas; Mian esperon Li elŝiris kiel arbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Ekflamis kontraŭ mi Lia kolero, Kaj Li rigardas min kiel Lian malamikon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Kune venis Liaj taĉmentoj, kaj ebenigis kontraŭ mi sian vojon Kaj stariĝis sieĝe ĉirkaŭ mia tendo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Miajn fratojn Li malproksimigis de mi, Kaj miaj konatoj forfremdiĝis de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Miaj parencoj fortiriĝis, Kaj miaj konantoj forgesis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'La loĝantoj de mia domo kaj miaj servistinoj rigardas min kiel fremdulon; En iliaj okuloj mi fariĝis aligentulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Mian sklavon mi vokas, kaj li ne respondas; Per mia buŝo mi devas petegi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Mia spiro fariĝis abomenata por mia edzino, Kaj mia petado por la filoj de mia ventro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Eĉ la malgrandaj infanoj malestimas min; Kiam mi leviĝas, ili parolas kontraŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Abomenas min ĉiuj miaj intimuloj; Kaj tiuj, kiujn mi amis, turnis sin kontraŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Kun mia haŭto kaj kun mia karno kunkreskis miaj ostoj, Mi restis nur kun haŭto sur miaj dentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Kompatu min, kompatu min, miaj amikoj; Ĉar la mano de Dio frapis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Kial vi persekutas min, kiel Dio, Kaj ne povas satiĝi de mia karno?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Ho, se miaj vortoj estus enskribitaj, Ho, se ili estus gravuritaj en libro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'Per fera skribilo kun plumbo, Gravuritaj por eterne sur roko!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Sed mi scias, ke mia Liberigonto vivas, Kaj fine Li leviĝos super la polvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'Kaj post kiam mia haŭto estos tiel detruita Kaj mi estos senkorpa, mi vidos Dion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'Lin vidos mi, kaj miaj okuloj vidos, ne fremdaj; Pri tio sopiregas mia interno en mia brusto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Se vi diros: Kiel ni lin persekutu, Kaj ni trovu kontraŭ li la radikon de la afero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'Tiam timu glavon; Ĉar furioza estas la glavo kontraŭ malbonagoj, Por ke vi sciu, ke ekzistas juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Ekparolis Cofar, la Naamano, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, 'Pro tio miaj pensoj devigas min respondi, Pro tio, kion mi sentas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Hontindan riproĉon mi aŭdis, Kaj la spirito de mia prudento respondos por mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Ĉu vi scias, ke tiel estis de eterne, De post la apero de homo sur la tero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'Ke la triumfado de malvirtuloj estas mallongatempa, Kaj la ĝojo de hipokritulo estas nur momenta?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Se lia grandeco eĉ atingus ĝis la ĉielo, Kaj lia kapo tuŝus la nubon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'Li tamen pereos por ĉiam, kiel lia sterko; Tiuj, kiuj lin vidis, diros: Kie li estas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Kiel sonĝo li forflugos, kaj oni lin ne trovos; Li malaperos, kiel nokta vizio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'Okulo, kiu rigardis lin, ne plu vidos lin; Lia loko lin ne plu vidos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Liaj filoj kurados almozpetante, Kaj liaj manoj redonos lian havaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Liaj ostoj estos punitaj pro la pekoj de lia juneco, Kaj tio kuŝiĝos kune kun li en la polvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Se la malbono estas dolĉa en lia buŝo, Li kaŝas ĝin sub sia lango,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'Li flegas ĝin kaj ne forlasas ĝin, Kaj retenas ĝin sur sia palato:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'Tiam lia manĝaĵo renversiĝos en liaj internaĵoj, Fariĝos galo de aspidoj interne de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Li englutis havaĵon, sed li ĝin elvomos; El lia ventro Dio ĝin elpelos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Venenon de aspidoj li suĉos; Lango de vipuro lin mortigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Li ne vidos fluojn nek riverojn, Torentojn de mielo kaj de butero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Li redonos tion, kion li pene akiris, kaj li tion ne englutos; Kiel ajn granda estas lia havaĵo, li ĝin fordonos kaj ne ĝuos ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Ĉar li premis kaj forlasis la senhavulojn, Li rabis al si domon, kiun li ne konstruis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Ĉar lia interno ne estis trankvila, Tial li ne savos tion, kio estis por li kara.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Nenion restigis lia manĝemeco; Tial lia bonstato ne estos longedaŭra.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Malgraŭ lia abundeco, li estos premata; Ĉiaspecaj suferoj trafos lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Por plenigi lian ventron, Li sendos sur lin la flamon de Sia kolero, Kaj pluvigos sur lin Sian furiozon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Se li forkuros de batalilo fera, Trafos lin pafarko kupra.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Nudigita glavo trairos lian korpon, Kaj la fulmo de lia turmentilo venos sur lin kun teruro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Nenia mallumo povos kaŝi liajn trezorojn; Lin konsumos fajro ne disblovata; Malbone estos al tiu, kiu restos en lia tendo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'La ĉielo malkovros liajn malbonagojn, Kaj la tero leviĝos kontraŭ lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Malaperos la greno el lia domo, Disŝutita ĝi estos en la tago de Lia kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Tia estas de Dio la sorto de homo malpia, Kaj la heredaĵo destinita por li de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Ijob respondis kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, 'Aŭskultu mian parolon; Kaj ĝi estu anstataŭ viaj konsoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Toleru, ke mi parolu; Kaj kiam mi finos mian paroladon, tiam moku.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Ĉu kontraŭ homo mi disputas? Kaj kial mi ne estu malpacienca?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Turnu vin al mi, kaj vi eksentos teruron, Kaj vi metos la manon sur la buŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Kiam mi ekpensas pri tio, min atakas teruro, Kaj tremo kaptas mian korpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Kial malpiuloj vivas, Atingas maljunecon, akiras grandan havaĵon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Ilia idaro estas bone aranĝita antaŭ ili, kune kun ili, Kaj ilia devenantaro estas antaŭ iliaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Iliaj domoj estas en paco, sen timo; Kaj la vergo de Dio ne estas sur ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Ilia bovo naskigas kaj ne estas forpuŝata; Ilia bovino gravediĝas kaj ne abortas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Siajn malgrandajn infanojn ili elirigas kiel ŝafaron, Kaj iliaj knaboj saltas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'Ili ĝojkrias sub la sonoj de tamburino kaj harpo, Ili estas gajaj sub la sonoj de fluto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'Ili pasigas siajn tagojn en bonstato, Kaj iras en Ŝeolon momente.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'Kaj tamen ili diras al Dio: Foriru de ni, Ni ne deziras koni Viajn vojojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Kio estas la Plejpotenculo, ke ni servu al Li? Kaj kian utilon ni havos, se ni turnos nin al Li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Sed ne de ili dependas ilia bonstato; La pensmaniero de la malpiuloj estas malproksima de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Ĝis kiam? La lumilo de la malpiuloj estingiĝu, Kaj ilia pereo venu sur ilin; Suferojn Li partodonu al ili en Sia kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'Ili estu kiel pajlero antaŭ vento, Kaj kiel grenventumaĵo, kiun forportas ventego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Dio konservas lian malfeliĉon por liaj infanoj; Li repagu al li mem, ke li sciu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Liaj propraj okuloj vidu lian malfeliĉon, Kaj el la kolero de la Plejpotenculo li trinku.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Ĉar kiom interesas lin lia domo post li, Kiam la nombro de liaj monatoj finiĝis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Ĉu oni povas instrui scion al Dio, Kiu juĝas ja plej altajn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Unu mortas meze de sia abundeco, Tute trankvila kaj kontenta;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'Lia brusto estas plena de lakto, Kaj liaj ostoj estas saturitaj de medolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Alia mortas kun animo suferanta, Kaj li ne ĝuis bonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Sed ambaŭ kune ili kuŝas en la tero, Kaj vermoj ilin kovras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Vidu, mi scias viajn pensojn, Kaj la argumentojn, kiujn vi malice kolektas kontraŭ mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Vi diros: Kie estas la domo de la nobelo? Kaj kie estas la tendo, en kiu loĝis la malpiuloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'Sed demandu la vojaĝantojn, Kaj ne malatentu iliajn atestojn:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'En tago de malfeliĉo la malpiulo estas ŝirmata, En tago de kolero li estas metata flanken.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Kiu montros antaŭ lia vizaĝo lian konduton? Kiu repagos al li, se li ion faris?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Kaj li estas akompanata al la tomboj, Kaj sur la tomba altaĵeto estas starigataj gardistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Dolĉaj estas por li la terbuloj de la valo, Kaj post li treniĝas ĉiuj homoj, Kaj sennombraj estas tiuj, kiuj iris antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Kiel do vi volas konsoli min per vantaĵo, Kaj viaj respondoj enhavas nur malĝustaĵojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Ekparolis Elifaz, la Temanano, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, 'Ĉu Dion povas instrui homo? Ĉu povas Lin instrui eĉ saĝulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Ĉu por la Plejpotenculo tio estas utila, se vi estas virta? Kaj ĉu Li havas profiton de tio, se via konduto estas pia?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Ĉu pro timo antaŭ vi Li disputos kun vi, Iros kun vi al juĝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Via malvirteco estas ja granda, Kaj viaj malbonagoj ne havas finon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Vi prenis de viaj fratoj garantiaĵon vane, De preskaŭ-nuduloj vi deprenis la vestojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Al laculo vi ne donis akvon por trinki, Kaj al malsatulo vi rifuzis panon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'Per forta brako vi akiris teron, Kaj dank� al eminenteco vi loĝis sur ĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Vidvinojn vi foririgis kun nenio, Kaj la brakojn de orfoj vi frakasis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Pro tio ĉirkaŭe de vi estas kaptiloj, Kaj subita teruro vin timigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Aŭ pro mallumo vi nenion vidas, Kaj multego da akvo vin kovris?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Ĉu ne estas Dio tie alte en la ĉielo? Rigardu la stelojn, kiel alte ili estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Kaj vi diras: Kion scias Dio? Ĉu Li povas juĝi en mallumo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'La nuboj kovras Lin, kaj Li ne vidas; Kaj Li nur rondiras en la rondo de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Ĉu vi konservas la vojon antikvan, Kiun iradis homoj malpiaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'Kiuj estis kaptitaj antaŭtempe, Kaj kies grundo disverŝiĝis kiel rivero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'Kiuj parolis al Dio: Foriru de ni! Kion povas fari al ni la Plejpotenculo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Kvankam Li plenigis iliajn domojn per bonaĵo. Sed la pensmaniero de malvirtuloj estas malproksima de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'La virtuloj vidos kaj ĝojos; La senkulpulo mokos ilin:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, 'Certe malaperis nia kontraŭulo, Kaj kio restis, tion ekstermis fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Interkonsentu do kun Li, kaj vi havos pacon; Per tio venos al vi bono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Prenu el Lia buŝo instruon, Kaj metu Liajn vortojn en vian koron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Se vi revenos al la Plejpotenculo, vi estos konstruita; Forigu malpiaĵon el via tendo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'Ĵetu en la polvon la multekostan metalon, Kaj la Ofiran oron sur la ŝtonojn de la torentoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'Tiam la Plejpotenculo estos via oro kaj via brilanta arĝento;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Ĉar tiam vi havos vian plezuron en la Plejpotenculo, Kaj vi levos al Dio vian vizaĝon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Vi preĝos al Li, kaj Li vin aŭskultos; Kaj viajn sanktajn promesojn vi plenumos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Se vi ion decidos, ĝi plenumiĝos ĉe vi; Kaj super viaj vojoj brilos lumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Ĉar tiujn, kiuj humiliĝis, Li altigos; Kaj kiu mallevas la okulojn, tiu estos savita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Ankaŭ tiun, kiu ne estis senkulpa, Li savos; Tia estos savita pro la pureco de viaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Ijob respondis kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, 'Eĉ hodiaŭ mia parolado restas maldolĉa; Mia suferado estas pli peza, ol miaj ĝemoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Ho, se mi scius, kiamaniere mi povas Lin trovi, Veni al Lia trono!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Mi prezentus al Li juĝan aferon, Kaj mian buŝon mi plenigus per argumentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Mi ekscius la vortojn, kiujn Li respondus al mi; Mi komprenus, kion Li dirus al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Ĉu en la grandeco de Sia forto Li luktus kontraŭ mi? Ne, Li nur atentu min;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Tiam pravulo procesus kun Li, Kaj mi liberiĝus por ĉiam de mia Juĝanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Sed jen mi iras antaŭen, kaj Li tie ne estas; Mi iras malantaŭen, kaj mi Lin ne rimarkas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'Se Li faras ion maldekstre, mi Lin ne trovas; Se Li kaŝas Sin dekstre, mi Lin ne vidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Sed mian vojon Li konas; Se Li min elprovos, mi eliros kiel oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Sur Lia irejo forte teniĝas mia piedo; Lian vojon mi konservis, kaj ne forkliniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'Mi ne deturnas min de la ordonoj de Liaj lipoj; Pli ol mian propran leĝon mi konservis la dirojn de Lia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Sed Li estas sola: kiu kontraŭstaros al Li? Kion Lia animo deziras, tion Li faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Kio estas destinita por mi, tion Li plenumos; Kaj Li havas multe da similaj aferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Tial mi tremas antaŭ Lia vizaĝo, Mi primeditas, kaj mi timas Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Dio senkuraĝigis mian koron, Kaj la Plejpotenculo min konfuzis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Ĉar mi ne estas neniigita antaŭ la mallumo, Kaj antaŭ mia vizaĝo Li ne kovris la mallumon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Kial la Plejpotenculo ne destinis tempojn, Kaj Liaj konantoj ne vidas Liajn tagojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'Oni forŝovas la limojn; Oni rabas la ŝafaron kaj paŝtas ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'Oni forkondukas la azenon de orfoj, Oni prenas kiel garantiaĵon la bovon de vidvino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'Oni forpuŝas malriĉulojn de la vojo; La suferantoj sur la tero devas sin kaŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Jen kiel sovaĝaj azenoj ili eliras al sia laboro, por serĉi kaptaĵon; La stepo donas al ili panon por iliaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'Sur fremda kampo ili rikoltas, Kaj en vinberĝardeno de malpiulo ili kolektas berojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Nudaj ili tradormas la nokton, ĉar ili ne havas veston, Kaj dum la frosto ili havas nenion, por sin kovri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'De la pluvego de la montoj ili malsekiĝas, Kaj pro nehavado de rifuĝejo ili ĉirkaŭprenas rokon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'Oni forŝiras orfon de la mamoj, Kaj oni ruinigas malriĉulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Ili iras nudaj, sen vestoj, Kaj malsataj ili portas garbojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'Inter iliaj muroj oni pretigas oleon; Oni devigas ilin treti en vinpremejoj, dum ili mem estas soifantaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'El la urbo aŭdiĝas ĝemoj de homoj, Kaj la animoj de mortigatoj krias; Sed Dio ne atentas tiun blasfemadon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Tiuj homoj estas kontraŭuloj de la lumo; Ili ne konas Liajn vojojn, Ne revenas al Lia irejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Antaŭ tagiĝo leviĝas la mortigisto, Mortigas malriĉulon kaj senhavulon, Kaj en la nokto li estas kiel ŝtelisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'La okulo de adultulo atendas la krepuskon, Dirante: Neniu okulo min vidu; Kaj li kovras sian vizaĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'En mallumo oni faras subfoson sub domoj; Dum la tago oni kaŝas sin ĉe si, ne konante lumon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Ĉar la mallumo estas mateno por ili ĉiuj, Ĉar ili interkonatiĝis kun la teruroj de la mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Tia homo estas malpeza sur la supraĵo de akvo; Malgranda estas lia parto sur la tero; Li ne iras laŭ la vojo de vinberĝardenoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Kiel seka tero kaj varmego englutas neĝan akvon, Tiel Ŝeol englutas la pekulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'Forgesu lin la interno de lia patrino; La vermoj frandu lin; Oni lin ne plu rememoru; Li rompiĝu kiel malbona arbo-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'Li, kiu premas seninfanulinon, kiu ne naskis, Kaj kiu ne faras bonon al vidvino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Kiu eĉ potenculojn maltrankviligas per sia forto, Tiel ke oni ne estas certa pri sia vivo, kiam li leviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Dio donas al ili sendanĝerecon kaj apogon, Kaj Liaj okuloj estas super iliaj vojoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'Ili leviĝis alte; sed subite ili ne plu ekzistas; Ili falas kaj estas forkaptataj kiel ĉiuj, Kaj kiel la kapo de spiko ili dehakiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Ĉu ne estas tiel? Kiu pruvos, ke mi mensogas, kaj senvalorigos mian parolon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Ekparolis Bildad, la Ŝuĥano, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, 'Regado kaj timigo estas ĉe Li, Kiu faras pacon en Siaj altaj sferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Ĉu oni povas kalkuli Liajn taĉmentojn? Kaj super kiu ne leviĝas Lia lumo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Kiel povas homo esti prava antaŭ Dio? Kaj kiel naskito de virino povas esti pura?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Vidu, eĉ la luno ne estas hela Kaj la steloj ne estas puraj antaŭ Liaj okuloj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'Des pli homo, la vermo! Kaj homido, la tineo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Ijob respondis kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'Kiel vi helpas al tiu, kiu ne havas forton! Kiel vi subtenas tiun, kies brako estas senforta!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Kian konsilon vi donas al tiu, kiu ne havas saĝon, Kaj kiel grandan prudenton vi montras!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'Al kiu vi parolas vortojn? Kaj kies spirito eliras el vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'La mortintoj tremas sub la akvo, Kaj ankaŭ tiuj, kiuj vivas en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Ŝeol estas malkovrita antaŭ Li, Kaj la abismo ne havas kovron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Li etendis la nordon super la malpleno, Li pendigis la teron sur nenio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Li ligas la akvon en Siaj nuboj, Kaj nubo ne krevas sub tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Li kovras la tronon Kaj etendas ĉirkaŭ ĝi Sian nubon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Li faris limon sur la akvo, Ĝis la loko, kie finiĝas la lumo kaj la mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'La kolonoj de la ĉielo ŝanceliĝas Kaj tremas de Lia krio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Per Sia forto Li kvietigas la maron, Kaj per Sia saĝo Li frakasas Rahabon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Per Lia spirito belegiĝis la ĉielo; Lia mano trapikas la tordiĝantan serpenton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Jen tio estas parto de Liaj vojoj; Kaj nur iometon ni aŭdis pri Li. Kiu povas kompreni la tondron de Lia potenco?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Kaj Ijob daŭrigis siajn sentencojn, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, 'Kiel vivas Dio, kiu rifuzis al mi miajn rajtojn, Kaj la Plejpotenculo, kiu afliktas mian animon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'Tiel longe, kiel mia animo estas en mi Kaj la spiro de Dio en mia nazo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'Miaj lipoj ne eldiros malĝustaĵon, Kaj mia lango ne diros malveraĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Malproksime estas de mi, Rigardi vin kiel pravajn; Ĝis mia morto mi ne ĉesos rigardi min kiel senkulpan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Mian pravecon mi tenas forte, kaj mi ne ellasos ĝin; Dum mia tuta vivo mia koro ne faros al mi riproĉon pri tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Mia malamiko estu rigardata kiel malvirtulo, Kaj mia kontraŭulo kiel malpiulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Ĉar kio estas la espero de hipokritulo, Kiam Dio faras al li finon, elŝiras lian animon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Ĉu lian kriadon Dio aŭskultos, Kiam trafos lin malfeliĉo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Ĉu li povas havi ĝuon de la Plejpotenculo, Voki al Dio en ĉiu tempo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Mi instruos vin pri la mano de Dio; Mi ne kaŝos antaŭ vi tion, kio estas ĉe la Plejpotenculo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Jen vi ĉiuj mem vidis; Kial do vi parolas senenhavaĵon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Tia estas la sorto de malbona homo ĉe Dio, Kaj la parto, kiun tiranoj ricevas de la Plejpotenculo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Se li havos multe da filoj, ili iros sub la glavon; Kaj lia devenantaro ne havos sate panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Tiujn, kiuj restos ĉe li, enterigos la morto; Kaj liaj vidvinoj ne ploros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Se li kolektos arĝenton kiel polvon Kaj pretigos al si vestojn kiel argilon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'Tiam li pretigos, sed justulo metos sur sin la vestojn, Kaj senkulpulo dividos la arĝenton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Li konstruas sian domon kiel tineo, Kaj kiel gardisto, kiu faras al si laŭbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Li kuŝiĝas riĉa, kaj nenion kunportas; Li malfermas la okulojn, kaj jam nenio ekzistas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Teruro superfalos lin kiel akvo; En la nokto forportos lin ventego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Levos lin vento orienta, kaj foriros, Kaj forblovos lin de lia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'Li tion ĵetos sur lin senkompate; De Lia mano li kuros kaj kuros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Oni kunfrapos pri li la manojn, Kaj oni fajfos pri li sur lia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'La arĝento havas lokon, kie oni ĝin elakiras; Kaj la oro havas lokon, kie oni ĝin fandas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'La fero estas ricevata el polvo, Kaj el ŝtono oni fandas la kupron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'Oni faras finon al la mallumo, Kaj rezulte oni trovas la ŝtonojn el grandega mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Oni fosas kavon tie, kie oni loĝas; Kaj tie, kie paŝas neniu piedo, ili laboras pendante, forgesitaj de homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'La tero, el kiu devenas pano, Estas trafosata sube kvazaŭ per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'Ĝiaj ŝtonoj estas loko de safiroj, Kaj terbuloj enhavas oron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'La vojon ne konas rabobirdo, Kaj la okulo de falko ĝin ne vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'Ne paŝis sur ĝi sovaĝaj bestoj, Ne iris sur ĝi leono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'Sur rokon oni metas sian manon, Oni renversas montojn de ilia bazo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'En rokoj oni elhakas riverojn, Kaj ĉion grandvaloran vidis la okulo de homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Oni haltigas la fluon de riveroj, Kaj kaŝitaĵon oni eltiras al la lumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Sed kie oni trovas la saĝon? Kaj kie estas la loko de prudento?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'La homo ne scias ĝian prezon; Kaj ĝi ne estas trovata sur la tero de vivantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'La abismo diras: Ne en mi ĝi estas; La maro diras: Ĝi ne troviĝas ĉe mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Oni ne povas doni por ĝi plej bonan oron, Oni ne pesas arĝenton page por ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'Oni ne taksas ĝin per oro Ofira, Nek per multekosta onikso kaj safiro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Ne valoregalas al ĝi oro kaj vitro; Kaj oni ne povas ŝanĝi ĝin kontraŭ vazoj el pura oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Koraloj kaj kristalo ne estas atentataj; Kaj posedo de saĝo estas pli valora ol perloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Ne valoregalas al ĝi topazo el Etiopujo; Pura oro ne povas esti ĝia prezo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'De kie venas la saĝo? Kaj kie estas la loko de prudento?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Kaŝita ĝi estas antaŭ la okuloj de ĉio vivanta, Nevidebla por la birdoj de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'La abismo kaj la morto diras: Per niaj oreloj ni aŭdis nur famon pri ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Dio komprenas ĝian vojon, Kaj Li scias ĝian lokon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Ĉar Li rigardas ĝis la fino de la tero, Li vidas sub la tuta ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Kiam Li donis pezon al la vento Kaj aranĝis la akvon laŭmezure,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'Kiam Li starigis leĝon por la pluvo Kaj vojon por la fulmo kaj tondro:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'Tiam Li vidis ĝin kaj anoncis ĝin, Pretigis ĝin kaj esploris ĝin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'Kaj Li diris al la homoj: Vidu, timo antaŭ Dio estas saĝo, Kaj evitado de malbono estas prudento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Kaj plue Ijob parolis siajn sentencojn, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, 'Ho, se estus al mi tiel, kiel en la antaŭaj monatoj, Kiel en la tempo, kiam Dio min gardis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'Kiam Lia lumilo lumis super mia kapo; Kaj sub Lia lumo mi povis iri en mallumo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'Kiel estis al mi en la tagoj de mia juneco, Kiam la ŝirmado de Dio estis super mia tendo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'Kiam la Plejpotenculo estis ankoraŭ kun mi, Kaj ĉirkaŭ mi estis miaj infanoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'Kiam miaj paŝoj laviĝadis en butero, Kaj la roko verŝadis al mi fluojn da oleo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'Kiam mi eliris el la pordego al la urbo Kaj aranĝis al mi sidon sur la placo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'Vidis min junuloj kaj kaŝis sin, Kaj maljunuloj leviĝis kaj staris;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'Eminentuloj ĉesis paroli Kaj metis la manon sur sian buŝon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'La voĉo de altranguloj sin kaŝis, Kaj ilia lango algluiĝis al ilia palato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Kiam orelo aŭdis, ĝi nomis min feliĉa; Kiam okulo vidis, ĝi gloris min;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Ĉar mi savadis kriantan malriĉulon, Kaj orfon, kiu ne havis helpanton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'Beno de pereanto venadis sur min, Kaj la koro de vidvino estis ĝojigata de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Virteco estis mia vesto, Kaj mia justeco vestis min kiel mantelo kaj kapornamo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Mi estis okuloj por la blindulo, Kaj piedoj por la lamulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'Mi estis patro por la malriĉuloj, Kaj juĝan aferon de homoj nekonataj mi esploradis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'Mi rompadis la makzelojn al maljustulo, Kaj el liaj dentoj mi elŝiradis la kaptitaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Kaj mi pensis: En mia nesto mi mortos, Kaj grandnombraj kiel sablo estos miaj tagoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Mia radiko estas malkovrita por la akvo, Kaj roso noktas sur miaj branĉoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'Mia gloro estas ĉiam nova, Kaj mia pafarko ĉiam refortiĝas en mia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'Oni aŭskultadis min kaj atendadis, Kaj silentadis, kiam mi donadis konsilojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Post miaj vortoj oni ne plu parolis; Kaj miaj vortoj gutadis sur ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'Oni atendadis min kiel la pluvon, Kaj malfermadis sian buŝon, kiel por malfrua pluvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Se mi iam ridis al ili, ili ne kredis tion; Kaj la lumo de mia vizaĝo ne falis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Kiam mi iris al ili, mi sidis sur la ĉefa loko; Mi loĝis kiel reĝo inter taĉmentoj, Kiel konsolanto de funebruloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'Sed nun ridas pri mi homoj pli junaj ol mi, Kies patrojn mi ne volus starigi kun la hundoj de miaj ŝafaroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Kies forto de la manoj estis senbezona por mi, Kaj kiuj ne povis atingi maljunecon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'Kiuj pro malriĉeco kaj malsato solece kuris En la dezerton mizeran kaj senvivan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'Kiuj elŝiras atriplon apud la arbetaĵoj, Kaj kies pano estas la radiko de genisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'El meze de la homoj oni elpelas ilin; Oni krias sur ilin, kiel sur ŝteliston;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'En terfendoj ĉe la valoj ili loĝas, En truoj de la tero kaj de rokoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'Inter la arbetaĵoj ili krias, Sub la kardoj ili kolektiĝas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'Kiel infanoj de sentaŭguloj kaj sennomuloj, Ili estas elpelitaj el la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Kaj nun mi fariĝis objekto de ilia mokokanto, Mi fariĝis por ili objekto de babilado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'Ili abomenas min, malproksimiĝas de mi, Ne timas kraĉi sur mian vizaĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Li malligis mian ŝnuron kaj turmentas min, Kaj ili forĵetis antaŭ mi la bridon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'Dekstre buboj stariĝis, kaj puŝas miajn piedojn; Ili ebenigis kontraŭ mi siajn pereigajn vojojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'Ili disfosis mian vojon, facile pereigas min, Ne bezonante helpanton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'Ili venas kiel tra larĝa breĉo, Ĵetas sin tumulte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Teruroj turnis sin kontraŭ min, Forpelis mian majeston kiel vento; Kiel nubo foriris mia feliĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'Kaj nun elverŝiĝas mia animo; Kaptis min tagoj de mizero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'En la nokto miaj ostoj traboriĝas en mi, Kaj miaj mordetantoj ne dormas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Kun granda malfacileco demetiĝas mia vesto; Premas min la rando de mia ĉemizo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Oni komparas min kun koto; Mi similiĝis al polvo kaj cindro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Mi krias al Vi, sed Vi ne respondas al mi; Mi staras, ke Vi atentu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Vi fariĝis kruelulo por mi; Per la forto de Via mano Vi montras al mi Vian malamon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Vi levis min en la venton, Lasis min kaj neniigis min en la ventego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Mi scias, ke Vi transdonos min al la morto, En la kunvenejon de ĉio vivanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Sed ĉu oni povas ne deziri eltiri manon, Kaj krii en sia malfeliĉo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Ĉu mi ne ploris pri tiu, kiu havis malfeliĉan tempon? Ĉu mia animo ne afliktiĝis pri malriĉulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Mi atendis bonon, sed venis malbono; Mi esperis lumon, sed venis mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Miaj internaĵoj bolas kaj ne ĉesas; Atakis min tempo de mizero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Mi estas nigra, sed ne de la suno; Mi leviĝas en la komunumo kaj krias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Mi fariĝis frato al la ŝakaloj Kaj kamarado al la strutoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Mia haŭto nigriĝis sur mi, Kaj miaj ostoj sekiĝis de varmego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Mia harpo fariĝis plendilo, Kaj mia fluto fariĝis voĉo de plorantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'Mi faris interligon kun miaj okuloj, Ke mi ne atentu virgulinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Kia estas la parto, kiun donas Dio de supre? Kaj kion destinas la Plejpotenculo el la altaj sferoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Ĉu ne malfeliĉon al malpiulo, Kaj forpuŝon de malbonagantoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Ĉu Li ne vidas mian konduton, Ne kalkulas ĉiujn miajn paŝojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Ĉu mi iradis en malvero, Kaj miaj piedoj rapidis al trompo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'Li pesu min per justa pesilo, Kaj tiam Dio konvinkiĝos pri mia senkulpeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Se mia paŝo forkliniĝis de la vojo, Se mia koro sekvis miajn okulojn, Kaj se al mia mano algluiĝis makulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'Tiam mi semu kaj alia manĝu, Kaj mia idaro elradikiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Se mia koro forlogiĝis al virino, Kaj mi kaŝe atendis ĉe la pordo de mia amiko:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'Tiam mia edzino estu adultigata de aliulo, Kaj aliuloj kliniĝu super ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Ĉar tio estus malvirto, Tio estus krimo, kiun devas puni juĝistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'Tio estas fajro, kiu ekstermas ĝis la abismo, Kaj mian tutan akiritaĵon ĝi elradikigus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Ĉu mi malŝatis la rajton de mia servisto aŭ de mia servistino, Kiam ili havis juĝan aferon kun mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'Tiam kion mi farus, kiam Dio leviĝus? Kaj kion mi respondus al Li, kiam Li esplordemandus?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Lin kreis ja Tiu sama, kiu kreis min en la ventro, Kaj Tiu sama pretigis en la ventro ankaŭ lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Ĉu mi rifuzis la deziron de senhavuloj? Aŭ ĉu mi turmentis la okulojn de vidvino?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'Ĉu mian panpecon mi manĝis sola? Ĉu ne manĝis de ĝi ankaŭ orfo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, 'Ĉar detempe de mia juneco mi estis kiel patro, Kaj de post la eliro el la ventro de mia patrino mi estis gvidisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'Kiam mi vidis malfeliĉulon sen vesto Kaj malriĉulon sen kovro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'Ĉu tiam ne benis min liaj lumboj, Ĉu li ne estis varmigata per la lano de miaj ŝafoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'Se mi levis mian manon kontraŭ orfon, Ĉar mi vidis en la pordego helpon al mi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'En tia okazo mia ŝultro defalu de la dorso, Kaj mia brako rompiĝu de kano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Ĉar mi timas la punon de Dio, Kaj ĝian pezon mi ne povus elteni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Ĉu mi faris la oron mia espero, Kaj la orbulon mi nomis mia fido?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'Ĉu mi ĝojis, ke mia riĉeco estas granda Kaj ke mia mano multe akiris?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'Kiam mi vidis la lumon brilantan Kaj la lunon majeste irantan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'Ĉu tiam sekrete forlogiĝis mia koro Kaj mi sendis kisojn per mia mano?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'Ankaŭ tio estus krimo juĝinda, Ĉar mi forneus per tio Dion en la alto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Ĉu mi ĝojis pri malfeliĉo de mia malamiko? Aŭ ĉu mi estis ravita, se lin trafis malbono?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'Mi ne permesis al mia gorĝo peki Per eldiro de malbeno kontraŭ lia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Ĉu la homoj de mia tendo ne diris: Ho, se oni ne satiĝus de lia karno!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'Ne noktis fremdulo sur la strato; Miajn pordojn mi malfermadis al migrantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Ĉu mi hommaniere kovradis miajn kulpojn, Por kaŝi en mia brusto miajn pekojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'En tia okazo mi timus grandan homamason, Kaj malestimo de familioj min timigus; Mi silentus, kaj ne elirus ekster la pordon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Ho, se iu aŭskultus min! Jen estas mia signo; la Plejpotenculo respondu al mi. Se mia akuzanto skribus libron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Mi portus ĝin sur mia ŝultro, Mi metus ĝin sur min kiel kronon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Mi raportus al li pri la nombro de miaj paŝoj; Mi alproksimiĝus al li kiel al princo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Se mia lando kriis kontraŭ mi, Kaj ĝiaj sulkoj ploris,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'Se ĝiajn fruktojn mi manĝis senpage, Kaj mi afliktis la animon de ĝiaj mastroj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'Tiam anstataŭ tritiko kresku por mi kardo, Kaj anstataŭ hordeo dornoj. Finiĝis la paroloj de Ijob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Kaj tiuj tri viroj ĉesis respondi al Ijob, ĉar li opiniis sin prava.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Tiam ekflamis la kolero de Elihu, filo de Baraĥel, Buzano, el la familio de Ram. Kontraŭ Ijob ekflamis lia kolero pro tio, ke li opiniis sin pli prava ol Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'kaj kontraŭ liaj tri amikoj ekflamis lia kolero pro tio, ke ili ne trovis respondon kaj akuzis Ijobon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Elihu atendis, dum ili parolis kun Ijob, ĉar ili estis pli aĝaj ol li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Sed kiam Elihu vidis, ke ne troviĝas respondo en la buŝo de la tri viroj, ekflamis lia kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'Kaj ekparolis Elihu, filo de Baraĥel, la Buzano, kaj diris: Mi estas juna, kaj vi estas maljunuloj; Tial mi hezitis kaj timis eldiri al vi mian opinion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Mi pensis: La aĝo parolu, Kaj la jarmulto montru saĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Sed la spirito en la homoj kaj la spiro de la Plejpotenculo Donas al ili prudenton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Ne la grandaj estas la plej prudentaj, Kaj ne la maljunuloj sole scias juĝi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Tial mi diras: Aŭskultu min; Mi ankaŭ eldiros mian opinion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Jen mi atendis viajn vortojn, Mi atentis vian kompetentecon, Ĝis vi trovos la ĝustan parolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'Sed atentante vin, mi vidis, Ke neniu el vi donas al Ijob moralinstruon, Respondante al liaj paroloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Ne diru: Ni trovis la saĝon. Dio instruu lin, ne homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Li ne direktis al mi siajn vortojn, Kaj per viaj diroj mi ne respondos al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Ili perdis la kuraĝon, ili ne plu respondis; Mankas al ili vortoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Mi atendis, ĝis ili ĉesos paroli; Sed ĉar ili haltis kaj ne plu respondis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Tial ankaŭ mi de mia flanko respondos, Mi ankaŭ eldiros mian opinion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Ĉar mi estas plena de vortoj; La spirito de mia interno min premas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Mia interno estas kiel vino ŝtopfermita, Kiu krevigas novan felsakon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Mi ekparolos, kaj tiam fariĝos al mi pli facile; Mi malfermos mian buŝon, kaj mi respondos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Mi ne atentos la vizaĝon de persono, Kaj mi ne flatos al homo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Ĉar mi ne povoscias flati; Aliokaze pereigu min mia Kreinto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'Aŭskultu do, Ijob, miajn parolojn, Kaj atentu ĉiujn miajn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Jen mi malfermis mian buŝon, Parolas mia lango en mia gorĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Ĝuste el mia koro estas miaj paroloj, Kaj puran scion eldiros miaj lipoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'La spirito de Dio min kreis, Kaj la spiro de la Plejpotenculo min vivigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Se vi povas, respondu al mi; Armu vin kontraŭ mi, kaj stariĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Jen mi simile al vi estas de Dio; Mi ankaŭ estas farita el argilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Vidu, vi ne bezonas timi min, Kaj mia ŝarĝo ne pezos sur vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Vi parolis antaŭ miaj oreloj, Kaj mi aŭdis la sonon de tiaj vortoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, 'Mi estas pura, sen malbonagoj; Senkulpa, mi ne havas pekon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Jen Li trovis ion riproĉindan en mi, Li rigardas min kiel Lian malamikon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'Li metis miajn piedojn en ŝtipon; Li observas ĉiujn miajn vojojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Sed en tio vi ne estas prava, mi respondas al vi; Ĉar Dio estas pli granda ol homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Kial vi havas pretendon kontraŭ Li pro tio, Ke Li ne donas al vi kalkulraporton pri ĉiuj Siaj faroj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Cetere Dio parolas en unu maniero kaj en alia maniero, Sed oni tion ne rimarkas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'En sonĝo, en nokta vizio, Kiam sur la homojn falis dormo, Kiam ili dormas sur la lito,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'Tiam Li malfermas la orelon de la homoj, Kaj, doninte instruon, sigelas ĝin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'Por deturni homon de ia faro Kaj gardi viron kontraŭ fiereco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'Por ŝirmi lian animon kontraŭ pereo Kaj lian vivon kontraŭ falo sub glavon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Ankaŭ per malsano sur lia lito Li avertas lin, Kiam ĉiuj liaj ostoj estas ankoraŭ fortaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'Kaj abomenata fariĝas por li en lia vivo la manĝaĵo, Kaj por lia animo la frandaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Lia karno konsumiĝas tiel, ke oni ĝin jam ne vidas; Kaj elstaras liaj ostoj, kiuj antaŭe estis nevideblaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'Kaj lia animo alproksimiĝas al la pereo, Kaj lia vivo al la mortigo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'Sed se li havas por si anĝelon proparolanton, Kvankam unu el mil, Kiu elmontrus pri la homo lian pravecon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'Tiam Li indulgas lin, kaj diras: Liberigu lin, ke li ne malsupreniru en la tombon, Ĉar Mi trovis pardonigon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'Tiam lia korpo fariĝas denove freŝa, kiel en la juneco; Li revenas al la tagoj de sia knabeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Li preĝas al Dio, Kaj ĉi Tiu korfavoras lin, Kaj montras al li Sian vizaĝon kun ĝojo, Kaj rekompencas la homon laŭ lia virteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Li rigardas la homojn, kaj diras: Mi pekis, la veron mi kripligis, Kaj Li ne repagis al mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Li liberigis mian animon, ke ĝi ne iru en pereon, Kaj mia vivo vidas la lumon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Ĉion ĉi tion Dio faras Du aŭ tri fojojn kun homo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'Por deturni lian animon de pereo Kaj prilumi lin per la lumo de vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Atentu, Ijob, aŭskultu min; Silentu, kaj mi parolos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Se vi havas, kion diri, respondu al mi; Parolu, ĉar mi dezirus, ke vi montriĝu prava.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Se ne, tiam aŭskultu min; Silentu, kaj mi instruos al vi saĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Elihu parolis plue, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, 'Aŭskultu, saĝuloj, miajn vortojn; Kaj vi, kompetentuloj, atentu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Ĉar la orelo esploras la parolon, Kiel la palato gustumas la manĝaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Decidon ni elektu al ni; Ni esploru inter ni, kio estas bona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Ĉar Ijob diris: Mi estas prava, Sed Dio forigis mian rajton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'En mia juĝa afero mi estas refutata; Turmentas min mia sago, kvankam mi estas senkulpa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Kiu homo estas simila al Ijob, Kiu trinkas mokojn kiel akvon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'Kaj li estas preta aliĝi al malbonaguloj Kaj iri kun malpiuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Ĉar li diras: Homo ne havas utilon, Se li serĉas favoron de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Tial aŭskultu min, ho saĝaj homoj: Dio estas malproksima de malbonagoj, Kaj la Plejpotenculo estas malproksima de maljusteco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Sed Li repagas al homo laŭ liaj agoj, Kaj laŭ la vojo de ĉiu Li renkontas lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Vere, Dio ne malbonagas, Kaj la Plejpotenculo ne kurbigas la veron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Kiu komisiis al Li la teron? Kaj kiu starigis Lin super la tuta mondo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Se Li pensus nur pri Si, Se Li prenus al Si Sian spiriton kaj spiron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'Tiam pereus absolute ĉiu karno, Kaj homo refariĝus polvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Se vi havas prudenton, aŭskultu ĉi tion; Atentu la voĉon de miaj paroloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Ĉu povas regi malamanto de justeco? Ĉu vi povas akuzi la Plejjustulon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Ĉu oni povas diris al reĝo: Sentaŭgulo; Aŭ al altranguloj: Malpiulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'Sed Li ne atentas la vizaĝon de princoj, Kaj ne preferas riĉulon antaŭ malriĉulo; Ĉar ĉiuj estas faritaĵo de Liaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'Momente ili mortas, noktomeze ili tumultiĝas kaj malaperas; Ne de homa mano estas forigataj la potenculoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Ĉar Liaj okuloj estas super la vojoj de homo, Kaj ĉiujn liajn paŝojn Li vidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Ne ekzistas mallumo nek ombrego, Kie povus sin kaŝi malbonaguloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Li ne bezonas multe klopodi kun homo, Ke li iru al Dio por juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Li pereigas la fortulojn sennombre Kaj starigas sur ilia loko aliajn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Ĉar Li scias iliajn farojn; Li renversas ilin en la nokto, kaj ili frakasiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Kiel malpiulojn Li frapas ilin sur loko, kie ĉiuj vidas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'Pro tio, ke ili forturniĝis de Li Kaj ne penis kompreni ĉiujn Liajn vojojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'Sed venigis al Li la kriadon de malriĉulo, Kaj Li aŭdis la kriadon de mizeruloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Se Li kvietigas, tiam kiu povas ribeligi? Se Li kaŝas Sian vizaĝon, tiam kiu povas Lin vidi? Tiel estas egale kun nacio kaj kun aparta homo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'Por ke ne regu homo hipokrita, El la pekigantoj de popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Al Dio oni devas diri: Mi fieriĝis, mi ne plu faros malbonon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Kion mi ne vidas, pri tio instruu min; Se mi faris maljustaĵon, mi ne plu faros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Ĉu konforme al via opinio Li devas repagi? Al vi ja ne plaĉis. Vi elektu, ne mi; Kaj kion vi scias, tion diru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Saĝaj homoj diros al mi, Kaj prudenta homo, kiu min aŭskultas:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, 'Ijob parolas malsaĝe, Kaj liaj vortoj estas malprudentaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Ho, se Ijob estus elprovita ĝis la fino, Pro tio, ke li aliĝas al homoj pekaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Ĉar al sia peko li aldonas blasfemon; Inter ni li mokas, kaj multe parolas kontraŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Elihu parolis plue, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, 'Ĉu tion vi opinias justa, ke vi diras: Mi estas pli prava ol Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Ĉar vi diras: Kiom tio utilas al vi? Kian profiton mi havas kompare kun tiu okazo, se mi pekus?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Mi respondos al vi, Kaj kune ankaŭ al viaj amikoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Rigardu la ĉielon, kaj vidu; Rigardu la nubojn, kiel tro alte ili estas por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Se vi pekas, kiom vi malutilas al Li? Kaj se viaj malbonagoj estas multaj, kion vi faras al Li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Se vi estas virta, kion vi donas al Li? Aŭ kion Li prenas el via mano?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Al homo, simila al vi, povas ion fari via malbonago, Kaj via virteco havas signifon nur por homido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'Pro multe da premado oni krias; Oni ĝemas pro la brako de potenculoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'Sed oni ne diras: Kie estas Dio, kiu min kreis, Kiu donas kantojn en la nokto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'Kiu instruas nin pli ol la brutojn sur la tero, Prudentigas nin pli ol la birdojn de la ĉielo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Tie ili krias pri la fiereco de la malbonuloj, Sed Li ne respondas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Tamen malvere estas, ke Dio ne aŭdas Kaj ke la Plejpotenculo ne vidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Kvankam vi diras, ke vi Lin ne vidas, Ekzistas tamen juĝo ĉe Li; Kaj vi atendu Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Sed ĉar Li nun ne montras Sian koleron Kaj ne atentas la tro grandan malvirtecon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Tial Ijob vante malfermis sian buŝon Kaj tre multe parolas malprudente.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Kaj plue parolis Elihu, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, 'Atendu ankoraŭ iom; mi montros al vi, Ĉar mi havas ankoraŭ kion paroli pro Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Mi prenos mian scion de malproksime, Kaj mi montros, ke mia Kreinto estas prava.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Ĉar vere miaj vortoj ne estas mensogaj; Homo sincera estas antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Vidu, Dio estas potenca, kaj tamen Li neniun malŝatas; Li estas potenca per la forto de la koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Al malpiulo Li ne permesas vivi, Kaj al mizeruloj Li donas justecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Li ne forturnas de virtuloj Siajn okulojn, Sed kun reĝoj sur trono Li sidigas ilin por ĉiam, Por ke ili estu altaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'Kaj se ili estas ligitaj per ĉenoj, Malliberigitaj mizere per ŝnuroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'Tiam Li montras al ili iliajn farojn kaj kulpojn, Kiel grandaj ili estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'Li malfermas ilian orelon por la moralinstruo, Kaj diras, ke ili deturnu sin de malbonagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Se ili obeas kaj servas al Li, Tiam ili finas siajn tagojn en bono Kaj siajn jarojn en stato agrabla;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Sed se ili ne obeas, Tiam ili pereas per glavo Kaj mortas en malprudento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'La hipokrituloj portas en si koleron; Ili ne vokas, kiam Li ilin ligis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Ilia animo mortas en juneco, Kaj ilia vivo pereas inter la malĉastuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Li savas la suferanton en lia mizero, Kaj per la sufero Li malfermas ilian orelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Ankaŭ vin Li elkondukus el la suferoj En spacon vastan, kie ne ekzistas premateco; Kaj vi havus pacon ĉe via tablo, plena de grasaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Sed vi fariĝis plena de kulpoj de malvirtulo; Kulpo kaj juĝo tenas sin kune.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Via kolero ne forlogu vin al mokado, Kaj grandeco de elaĉeto ne deklinu vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Ĉu Li atentos vian riĉecon? Ne, nek oron, nek forton aŭ potencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Ne strebu al tiu nokto, Kiu forigas popolojn de ilia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Gardu vin, ne kliniĝu al malpieco; Ĉar tion vi komencis pro la mizero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Vidu, Dio estas alta en Sia forto. Kiu estas tia instruanto, kiel Li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Kiu povas preskribi al Li vojon? Kaj kiu povas diri: Vi agis maljuste?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Memoru, ke vi honoru Liajn farojn, Pri kiuj kantas la homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Ĉiuj homoj ilin vidas; Homo rigardas ilin de malproksime.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Vidu, Dio estas granda kaj nekonata; La nombro de Liaj jaroj estas neesplorebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Kiam Li malgrandigas la gutojn de akvo, Ili verŝiĝas pluve el la nebulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'Verŝiĝas la nuboj Kaj gutas sur multe da homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'Kaj kiam Li intencas etendi la nubojn Kiel tapiŝojn de Sia tendo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Tiam Li etendas sur ilin Sian lumon Kaj kovras la radikojn de la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Ĉar per ili Li juĝas la popolojn Kaj donas ankaŭ manĝaĵon abunde.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Per la manoj Li kovras la lumon Kaj ordonas al ĝi aperi denove.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Antaŭdiras pri ĝi ĝia bruo, Kaj eĉ la brutaroj, kiam ĝi alproksimiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'Pri tio tremas mia koro Kaj saltas de sia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Aŭskultu atente en la bruo Lian voĉon, Kaj la sonojn, kiuj eliras el Lia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Sub la tutan ĉielon Li kurigas tion, Kaj Sian lumon al la randoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Post ĝi ekbruas la tondro; Li tondras per Sia majesta voĉo, Kaj oni ne povas tion haltigi, kiam aŭdiĝas Lia voĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Mirinde tondras Dio per Sia voĉo; Li faras ion grandan, sed ne konatan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Al la neĝo Li diras: Falu sur la teron; Ankaŭ al la pluvego, al Siaj fortaj pluvegoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Sur la manon de ĉiu homo Li metas sigelon, Por ke ĉiuj homoj sciu Lian faron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'La sovaĝa besto iras en sian kavon Kaj restas en sia loĝejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'El la sudo venas ventego, Kaj de la nordo venas malvarmo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'De la spiro de Dio venas frosto, Kaj vasta akvo fariĝas kvazaŭ fandaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'La nubojn Li pezigas per akvo, Kaj nubo disŝutas Lian lumon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'Li direktas ilin ĉirkaŭen, kien Li volas, Por ke ili plenumu ĉion, kion Li ordonas al ili, sur la tero:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'Ĉu por puno de ia lando, Ĉu por favorkoraĵo Li ilin direktas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Atentu tion, Ijob; Staru, kaj konsideru la miraklojn de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Ĉu vi scias, kiamaniere Dio agigas ilin Kaj aperigas lumon el Sia nubo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Ĉu vi komprenas, ĉe la distiro de nubo, La miraklojn de Tiu, kiu estas la plej perfekta en la sciado?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Kiamaniere viaj vestoj varmiĝas, Kiam la tero kvietiĝas de sude?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'Ĉu vi povas etendi kun Li la ĉielon, Firman kiel fandita spegulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Sciigu al ni, kion ni devas diri al Li; Mi nenion povas elkonjekti pro mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Ĉu estos rakontita al Li tio, kion mi parolas? Se iu parolos, li pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Nun oni ne povas rigardi la lumon, kiu hele lumas en la ĉielo, Kiam la vento pasas kaj purigas ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'De norde venas oro; Ĉirkaŭ Dio estas terura brilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'La Plejpotenculon ni ne povas kompreni. Li estas granda en forto, justo, kaj vero; Li neniun premas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Tial respektegas Lin la homoj; Kaj Li atentas neniun el la saĝuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'La Eternulo el ventego ekparolis al Ijob, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, 'Kiu estas tiu, kiu mallumigas la plej altan decidon Per vortoj sensencaj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Zonu kiel viro viajn lumbojn; Mi vin demandos, kaj vi sciigu al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Kie vi estis, kiam Mi fondis la teron? Diru, se vi havas scion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Kiu starigis ĝiajn mezurojn, se vi tion scias? Aŭ kiu etendis super ĝi rektoŝnuron?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Sur kio estas enfortikigitaj ĝiaj bazoj, Aŭ kiu kuŝigis ĝian angulŝtonon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'Dum komuna glorkantado de la matenaj steloj Kaj ĝojkriado de ĉiuj filoj de Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Kiu fermis la maron per pordoj, Kiam ĝi elpuŝiĝis kvazaŭ el la ventro de patrino;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'Kiam Mi faris la nubon ĝia vesto Kaj mallumon ĝiaj vindaĵoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'Kaj starigis al ĝi limon Kaj faris riglilojn kaj pordojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'Kaj diris: Ĝis ĉi tie aliru, sed ne plu, Kaj ĉi tie rompiĝados viaj majestaj ondoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Ĉu vi en via vivo iam ordonis al la mateno, Montris al la matenruĝo ĝian lokon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'Ke ĝi kaptu la randojn de la tero, Kaj ke la malpiuloj deskuiĝu el ĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Ke ilia internaĵo renversiĝu kiel koto, Kaj ke ili tute konfuziĝu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'Ke de la malpiuloj forpreniĝu ilia lumo, Kaj ilia malhumila brako estu rompita?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Ĉu vi venis ĝis la fontoj de la maro? Kaj ĉu vi iradis sur la fundo de la abismo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Ĉu malfermiĝis antaŭ vi la pordego de la morto? Kaj ĉu vi vidis la pordegon de la mallumego?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Ĉu vi pririgardis la larĝon de la tero? Diru, ĉu vi scias ĉion ĉi tion?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Kie estas la vojo al la loĝejo de la lumo, Kaj kie estas la loko de la mallumo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'Ke vi konduku ĝin al ĝia limo, Kaj ke vi rimarku la vojetojn al ĝia domo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Ĉu vi sciis, kiam vi naskiĝos Kaj kiel granda estos la nombro de viaj tagoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Ĉu vi venis al la devenejo de la neĝo, Kaj ĉu vi vidis la devenejon de la hajlo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'Kiujn Mi konservas por la tempo de suferado, Por la tago de batalo kaj milito?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Kie estas la vojo, laŭ kiu dividiĝas la lumo, Diskuras la orienta vento super la teron?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Kiu destinis direkton por la fluo Kaj vojon por la tondra fulmo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'Por doni pluvon sur teron, kie neniu troviĝas, Sur dezerton senhoman,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'Por nutri dezerton kaj stepon Kaj kreskigi verdan herbon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Ĉu la pluvo havas patron? Aŭ kiu naskigis la gutojn de roso?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'El kies ventro eliris la glacio? Kaj kiu naskis la prujnon sub la ĉielo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Simile al ŝtono malmoliĝas la akvo, Kaj la supraĵo de la abismo kunfirmiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Ĉu vi povas ligi la ligilon de la Plejadoj? Aŭ ĉu vi povas malligi la ligon de Oriono?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Ĉu vi povas elirigi iliatempe la planedojn, Kaj konduki la Ursinon kun ĝiaj infanoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Ĉu vi konas la leĝojn de la ĉielo? Aŭ ĉu vi povas aranĝi ĝian regadon super la tero?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Ĉu vi povas levi al la nubo vian voĉon, Ke abundo da akvo vin kovru?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Ĉu vi povas sendi fulmojn, Ke ili iru kaj diru al vi: Jen ni estas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Kiu metis en la internon la saĝon? Kaj kiu donis al la koro la prudenton?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Kiu estas tiel saĝa, ke li povu kalkuli la nubojn? Kaj kiu elverŝas la felsakojn de la ĉielo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'Kiam la polvo kunfandiĝas Kaj la terbuloj kungluiĝas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, 'Ĉu vi ĉasas kaptaĵon por la leonino, Kaj satigas la leonidojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, 'Kiam ili kuŝas en la nestegoj, Sidas embuske en la laŭbo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, 'Kiu pretigas al la korvo ĝian manĝaĵon, Kiam ĝiaj idoj krias al Dio, Vagflugas, ne havante, kion manĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Ĉu vi scias la tempon, en kiu naskas la ibeksoj sur la rokoj? Ĉu vi observis la akuŝiĝon de la cervinoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Ĉu vi kalkulis la monatojn de ilia gravedeco? Aŭ ĉu vi scias la tempon, kiam ili devas naski?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Ili fleksiĝas, elĵetas siajn idojn, Liberiĝas de siaj doloroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Iliaj infanoj fortiĝas, kreskas en libereco, Foriras, ke ne revenas al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Kiu donis liberecon al la sovaĝa azeno? Kaj kiu malligis ĝiajn ligilojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'La dezerton Mi faris ĝia domo, Kaj stepon ĝia loĝejo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Ĝi ridas pri la bruo de la urbo, La kriojn de pelanto ĝi ne aŭdas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'La produktaĵoj de la montoj estas ĝia manĝaĵo, Kaj ĝi serĉas ĉian verdaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Ĉu bubalo volos servi al vi? Ĉu ĝi volos nokti ĉe via manĝujo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Ĉu vi povas alligi bubalon per ŝnuro al bedo? Ĉu ĝi erpos post vi valojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Ĉu vi fidos ĝin pro ĝia granda forto? Kaj ĉu vi komisios al ĝi vian laboron?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Ĉu vi havos konfidon al ĝi, ke ĝi reportos viajn semojn Kaj kolektos en vian grenejon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'La flugilo de struto leviĝas gaje, Simile al la flugilo de cikonio kaj de akcipitro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Ĉar ĝi lasas sur la tero siajn ovojn Kaj varmigas ilin en la sablo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'Ĝi forgesas, ke piedo povas ilin dispremi Kaj sovaĝa besto povas ilin disbati.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Ĝi estas kruela por siaj idoj, kvazaŭ ili ne estus ĝiaj; Ĝi ne zorgas pri tio, ke ĝia laboro estas vana;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'Ĉar Dio senigis ĝin je saĝo Kaj ne donis al ĝi prudenton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'Kiam ĝi leviĝas alten, Ĝi mokas ĉevalon kaj ĝian rajdanton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Ĉu vi donas forton al la ĉevalo? Ĉu vi vestas ĝian kolon per kolharoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Ĉu vi povas saltigi ĝin kiel akrido? Terura estas la beleco de ĝia ronkado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'Ĝi fosas en la valo kaj estas gaja pro forteco; Ĝi eliras kontraŭ armiton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Ĝi ridas pri timo kaj ne senkuraĝiĝas, Kaj ne retiras sin de glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Super ĝi sonoras la sagujo, Brilas lanco kaj ponardego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'Kun bruo kaj kolero ĝi glutas teron, Kaj ne povas stari trankvile ĉe sonado de trumpeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Kiam eksonas la trumpeto, ĝi ekkrias: Ho, ho! Kaj de malproksime ĝi flarsentas la batalon, Kriadon de la kondukantoj, kaj bruon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Ĉu pro via saĝo flugas la akcipitro Kaj etendas siajn flugilojn al sudo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Ĉu pro via ordono leviĝas la aglo Kaj faras alte sian neston?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'Sur roko ĝi loĝas, Noktas sur dento de roko kaj de monta pinto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'De tie ĝi elrigardas por si manĝaĵon; Malproksime vidas ĝiaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'Ĝiaj idoj trinkas sangon; Kaj kie estas mortigitoj, tie ĝi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'Kaj la Eternulo plue parolis al Ijob, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, 'Ĉu povas blasfemanto disputi kun la Plejpotenculo? La mallaŭdanto de Dio tion respondu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Kaj Ijob respondis al la Eternulo, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, 'Jen mi estis facilanima; kion mi povas respondi al Vi? Mi metas mian manon sur mian buŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Unu fojon mi parolis, kaj mi ne respondos; Tion mi ne faros duan fojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Kaj la Eternulo respondis al Ijob el la ventego, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, 'Zonu kiel viro viajn lumbojn; Mi vin demandos, kaj vi sciigu al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Ĉu vi volas senvalorigi Mian verdikton, Akuzi Min, por ke vi montriĝu prava?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'Se vi havas tian brakon, kiel Dio, Kaj se vi povas tondri per voĉo simile al Li,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Tiam ornamu vin per majesto, kaj altiĝu, Vestu vin per gloro kaj belegeco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Elverŝu la furiozon de via kolero; Ekrigardu ĉion fieran kaj humiligu ĝin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Ekrigardu ĉiun fierulon kaj konfuzu lin; Kaj frakasu la malpiulojn sur ilia loko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Kaŝu ilin ĉiujn en la tero; Ilian vizaĝon kovru per mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'Tiam Mi gloros vin, Se via dekstra mano vin helpos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Vidu la hipopotamon, kiun Mi kreis apud vi; Herbon ĝi manĝas, kiel bovo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Vidu, ĝia forto estas en ĝiaj lumboj, Kaj ĝia fortikeco estas en la muskoloj de ĝia ventro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Ĝi streĉas sian voston kiel cedron, La tendenoj de ĝiaj femuroj estas interplektitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Ĝiaj ostoj estas kiel kupraj tuboj, Ĝiaj ostoj estas kiel feraj stangoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'Ĝi estas la komenco de la vojoj de Dio; Ĝia Kreinto donis al ĝi ĝian glavon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'La montoj alportas al ĝi manĝaĵon, Kaj ĉiuj bestoj de la kampo tie ludas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Sub ombroriĉaj arboj ĝi kuŝas, Sub kovro de kanoj kaj en ŝlimo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'Ombroriĉaj arboj ŝirmas ĝin per sia ombro, Ĉirkaŭas ĝin salikoj apud torentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Se la rivero tumultas, ĝi ne konfuziĝas; Ĝi staras trankvile, se eĉ Jordan enverŝiĝus en ĝian buŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Ĉu iu povas preni ĝin antaŭ ĝiaj okuloj, Ĉu iu povas trabori per ŝnuroj ĝian nazon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Ĉu vi povas eltiri levjatanon per fiŝhoko, Aŭ ligi per ŝnuro ĝian langon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Ĉu vi povas trameti kanon tra ĝia nazo Kaj trapiki ĝian vangon per pikilo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Ĉu ĝi multe petegos vin, Aŭ parolos al vi flataĵojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Ĉu ĝi faros interligon kun vi? Ĉu vi povas preni ĝin kiel porĉiaman sklavon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Ĉu vi amuziĝos kun ĝi kiel kun birdo? Aŭ ĉu vi ligos ĝin por viaj knabinoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Ĉu kamaradoj ĝin dishakos, Kaj dividos inter komercistoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Ĉu vi povas plenigi per pikiloj ĝian haŭton Kaj per fiŝistaj hokoj ĝian kapon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Metu sur ĝin vian manon; Tiam vi bone memoros la batalon, kaj ĝin ne plu entreprenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Vidu, la espero ĉiun trompos; Jam ekvidinte ĝin, li falos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Neniu estas tiel kuraĝa, por inciti ĝin; Kiu do povas stari antaŭ Mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Kiu antaŭe ion donis al Mi, ke Mi redonu al li? Sub la tuta ĉielo ĉio estas Mia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Mi ne silentos pri ĝiaj membroj, Pri ĝia forto kaj bela staturo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'Kiu povas levi ĝian veston? Kiu aliros al ĝia paro da makzeloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'Kiu povas malfermi la pordon de ĝia vizaĝo? Teruro ĉirkaŭas ĝiajn dentojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Ĝiaj fieraj skvamoj estas kiel ŝildoj, Interligitaj per fortika sigelo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'Unu kuntuŝiĝas kun la alia tiel, Ke aero ne povas trairi tra ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Unu alfortikiĝis al la alia, Interkuniĝis kaj ne disiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Ĝia terno briligas lumon, Kaj ĝiaj okuloj estas kiel la palpebroj de la ĉielruĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'El ĝia buŝo eliras torĉoj, Elkuras flamaj fajreroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'El ĝiaj nazotruoj eliras fumo, Kiel el bolanta poto aŭ kaldrono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Ĝia spiro ekbruligas karbojn, Kaj flamo eliras el ĝia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'Sur ĝia kolo loĝas forto, Kaj antaŭ ĝi kuras teruro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'La partoj de ĝia karno estas firme kunligitaj inter si, Tenas sin fortike sur ĝi, kaj ne ŝanceliĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Ĝia koro estas malmola kiel ŝtono, Kaj fortika kiel suba muelŝtono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Kiam ĝi sin levas, ektremas fortuloj, Konsterniĝas de teruro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, 'Glavo, kiu alproksimiĝas al ĝi, ne povas sin teni, Nek lanco, sago, aŭ kiraso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, 'Feron ĝi rigardas kiel pajlon, Kupron kiel putran lignon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, 'Ne forpelos ĝin sago; Ŝtonoj el ŝtonĵetilo fariĝas pajleroj antaŭ ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, 'Bastonegon ĝi rigardas kiel pajlon, Kaj ĝi mokas la sonon de lanco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, 'Sube ĝi havas akrajn pecetojn; Kiel draŝrulo ĝi kuŝas sur la ŝlimo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, 'Kiel kaldronon ĝi ondigas la profundon; La maron ĝi kirlas kiel ŝmiraĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, 'La vojo post ĝi lumas; La abismo aperas kiel grizaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, 'Ne ekzistas sur la tero io simila al ĝi; Ĝi estas kreita sentima.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, 'Ĝi rigardas malestime ĉion altan; Ĝi estas reĝo super ĉiuj sovaĝaj bestoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Ijob respondis al la Eternulo, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, 'Mi scias, ke Vi ĉion povas fari, Kaj ke nenio, kion Vi entreprenas, estas malfacila por Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Kiu estas tiu, kiu kovras malkompetente la plej altan decidon? Jes, mi parolis sen komprenado pri aferoj, Kiuj estas tro misteraj por mi, kaj kiujn mi ne konas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Aŭskultu, kaj mi parolos; Mi demandos Vin, kaj Vi sciigu al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Nur per la oreloj mi aŭdis pri Vi; Sed nun mia okulo Vin vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Tial mi faras al mi riproĉon, Kaj mi pentas en polvo kaj cindro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'Post kiam la Eternulo parolis tiujn vortojn al Ijob, la Eternulo diris al Elifaz, la Temanano: Mia kolero ekflamis kontraŭ vi kaj kontraŭ viaj du amikoj, pro tio, ke vi ne parolis antaŭ Mi tiel ĝuste, kiel Mia servanto Ijob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Prenu do nun al vi sep bovojn kaj sep ŝafojn, kaj iru al Mia servanto Ijob, kaj alportu bruloferon pro vi; kaj Mia servanto Ijob preĝos por vi; ĉar nur lin Mi atentos, por ne fari al vi punon pro tio, ke vi ne parolis antaŭ Mi tiel ĝuste, kiel Mia servanto Ijob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Kaj iris Elifaz, la Temanano, kaj Bildad, la Ŝuĥano, kaj Cofar, la Naamano, kaj faris tion, kion diris al ili la Eternulo. Kaj la Eternulo atentis Ijobon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Kaj la Eternulo redonis la forprenitaĵon al Ijob, kiam li preĝis por siaj amikoj. Kaj la Eternulo donis al Ijob duoble pli ol ĉio, kion li havis antaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Kaj venis al li ĉiuj liaj fratoj kaj ĉiuj liaj fratinoj kaj ĉiuj liaj antaŭaj konatoj, kaj ili manĝis kun li en lia domo, kaj esprimis al li sian kunsenton, kaj konsolis lin pri la tuta malbono, kiun la Eternulo venigis sur lin; kaj ĉiu el ili donis al li po unu kesito, kaj ĉiu po unu ora ringo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'Kaj la Eternulo benis la lastajn jarojn de Ijob pli ol la komencajn; kaj li havis dek kvar mil ŝafojn kaj ses mil kamelojn kaj mil parojn da bovoj kaj mil azeninojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Kaj li havis sep filojn kaj tri filinojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'Al unu el ĉi tiuj li donis al nomon Jemima, al la dua la nomon Kecia, kaj al la tria la nomon Keren-Hapuĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'Kaj en la tuta lando ne troviĝis virinoj tiel belaj, kiel la filinoj de Ijob; kaj ilia patro donis al ili heredan posedaĵon inter iliaj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Kaj post tio Ijob vivis cent kvardek jarojn, kaj li vidis siajn filojn kaj nepojn ĝis la kvara generacio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'Kaj Ijob mortis, maljuna kaj satiĝinta de la vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Feliĉa estas la homo, kiu ne iras laŭ konsilo de malpiuloj, Nek staras sur vojo de pekuloj, Nek sidas en kunsido de blasfemantoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'Sed li nur havas deziron por la leĝo de la Eternulo, Kaj pri Lia leĝo li pensas tage kaj nokte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Kaj li estos kiel arbo, plantita apud akvaj torentoj, Donanta sian frukton en sia tempo, Kaj kies folio ne velkas; Kaj en ĉio, kion li faras, li sukcesos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Ne tiel estas la malpiuloj; Sed ili estas kiel grenventumaĵo, kiun disblovas la vento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Tial ne staros fortike la malpiuloj ĉe la juĝo, Nek la pekuloj en societo de piuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Ĉar la Eternulo konas la vojon de piuloj; Sed la vojo de malpiuloj pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Kial tumultas popoloj, Kaj gentoj pripensas vanaĵon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Leviĝas reĝoj de la tero, Kaj eminentuloj konsiliĝas kune, Kontraŭ la Eternulo kaj kontraŭ Lia sanktoleito, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'Ni disŝiru iliajn ligilojn, Kaj ni deĵetu de ni iliajn ŝnurojn!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'La loĝanta en la ĉielo ridas, La Sinjoro mokas ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Tiam Li parolos al ili en Sia kolero, Kaj per Sia furiozo Li ilin ektimigos, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'Mi starigis ja Mian reĝon Super Cion, Mia sankta monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Mi raportos pri la decido: La Eternulo diris al mi: Vi estas Mia filo, Hodiaŭ Mi vin naskis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Petu Min, kaj Mi donos al vi popolojn por heredo, Kaj por posedo limojn de tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Vi disbatos ilin per fera sceptro, Kiel potan vazon vi ilin dispecigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Kaj nun, ho reĝoj, prudentiĝu; Instruiĝu, juĝistoj de la tero!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Servu al la Eternulo kun timo, Kaj ĝoju kun tremo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Kisu la filon, ke Li ne koleru, kaj vi ne pereu sur la vojo, Ĉar baldaŭ ekbrulos Lia kolero. Feliĉaj estas ĉiuj, kiuj fidas Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Psalmo de David, kiam li forkuris de sia filo Abŝalom. Ho Eternulo, kiel multaj estas miaj premantoj, Multaj leviĝis kontraŭ mi!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Multaj diradas pri mia animo: Ne ekzistas por li savo de Dio. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Sed Vi, ho Eternulo, estas ŝildo por mi, Mia honoro kaj levanto de mia kapo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Per mia voĉo mi vokas al la Eternulo, Kaj Li respondas al mi de Sia sankta monto. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Mi kuŝiĝas kaj endormiĝas, Kaj mi vekiĝas, ĉar la Eternulo min subtenas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Mi ne timas miriadojn da kontraŭuloj, Kiuj estas ĉirkaŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Leviĝu, ho Eternulo, savu min, mia Dio; Ĉar Vi frapis al ĉiuj miaj malamikoj la vangojn, La dentojn de la malpiuloj Vi frakasis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Ĉe la Eternulo estas la savo; Super Via popolo estu Via beno. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Al la ĥorestro. Por kordaj instrumentoj. Psalmo de David. Kiam mi vokas, respondu al mi, justa mia Dio! En premo Vi liberigas min; Korfavoru min, kaj aŭskultu mian preĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Homidoj, ĝis kiam mia honoro estos malhonorata? Ĝis kiam vi amos vantaĵon kaj celos malveron? Sela. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Sciu do, ke la Eternulo apartigis la piulon por Si; La Eternulo aŭdas, kiam mi vokas al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Tremu, kaj ne peku; Meditu en viaj koroj, sur viaj kuŝejoj, kaj estu fortikanimaj. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Oferdonu oferojn piajn, Kaj fidu la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Multaj diradas: Kiu montros al ni bonon? Direktu sur nin la lumon de Via vizaĝo, ho Eternulo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Vi metis ĝojon en mian koron, pli ol dum ilia greno kaj ilia mosto plimultiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Pace mi kuŝiĝas kaj tuj endormiĝas; Ĉar Vi, ho Eternulo, loĝigas min sola en sendanĝereco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Al la ĥorestro. Por blovaj instrumentoj. Psalmo de David. Miajn vortojn aŭskultu, ho Eternulo. Trapenetru miajn pensojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Aŭdu la voĉon de mia krio, mia Reĝo kaj mia Dio; Ĉar al Vi mi preĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Ho Eternulo, matene Vi aŭdas mian voĉon; Matene mi eldiras mian preĝon al Vi, kaj mi atendas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Ĉar Vi ne estas tia Dio, kiu amas malpiaĵon; Malbonulo ne povas gasti ĉe Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Fanfaronuloj ne staros antaŭ Vi; Vi malamas ĉiujn, kiuj faras malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Vi pereigas tiujn, kiuj parolas malveron; Sangavidan kaj malican la Eternulo abomenas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Kaj mi, pro Via granda favoro, eniros en Vian domon; Mi kliniĝos en Via sankta templo kun respektego al Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Ho Eternulo, gvidu min laŭ Via justeco; Pro miaj insidantoj ebenigu antaŭ mi Vian vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Ĉar ne ekzistas vero en ilia buŝo; En ilia interno estas malvirteco; Malfermita tombo estas ilia gorĝo; Per sia lango ili hipokritas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Montru ilian kulpon, ho Dio, Ke ili falu per siaj intencoj; Pro iliaj multaj krimoj ĵetu ilin malsupren, Ĉar ili ribelis kontraŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Kaj ekĝojos ĉiuj, kiuj fidas Vin; Ili eterne estos gajaj, kaj Vi ilin favoros; Kaj triumfos pri Vi tiuj, kiuj amas Vian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Ĉar Vi, ho Eternulo, benas piulon; Kiel per ŝildo Vi ĉirkaŭdefendas lin per favoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Al la ĥorestro. Por kordaj instrumentoj, por basuloj. Psalmo de David. Ho Eternulo, ne en Via kolero min riproĉu, Kaj ne en Via furiozo min punu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Korfavoru min, ho Eternulo, ĉar mi senfortiĝis; Sanigu min, ho Eternulo, ĉar ektremis miaj ostoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Kaj mia animo forte ektremis; Kaj Vi, ho Eternulo, ĝis kiam?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Returnu Vin, ho Eternulo, savu mian animon; Helpu min pro Via favorkoreco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Ĉar en la morto ne ekzistas memoro pri Vi; En Ŝeol, kiu gloros Vin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Mi laciĝis de mia ĝemado; Ĉiun nokton mi priverŝas mian liton; Per miaj larmoj mi malsekigas mian kuŝejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Sekiĝis de malĝojo mia vizaĝo, Maljuniĝis de ĉiuj miaj premantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Foriĝu de mi, ĉiuj, kiuj faras malbonon; Ĉar aŭdis la Eternulo la voĉon de mia ploro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Aŭdis la Eternulo mian peton; La Eternulo akceptos mian preĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Hontigitaj kaj tre teruritaj estos ĉiuj miaj malamikoj; Ili forturniĝos kaj tuj estos hontigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Senkulpiĝo de David, kiun li kantis al la Eternulo pri Kuŝ, la Benjamenido. Ho Eternulo, mia Dio, ĉe Vi mi rifuĝas; helpu min kontraŭ ĉiuj miaj persekutantoj, kaj savu min,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'Por ke oni ne elŝiru, kiel leono, mian animon, Ĝin disŝirante, dum neniu savas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'Ho Eternulo, mia Dio! se mi faris ĉi tion, Se ekzistas maljusteco en miaj manoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Se al mia amiko mi pagis per malbono, Aŭ se mi difektis tiun, kiu premis min senkaŭze:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'Tiam malamiko persekutu mian animon, Li atingu kaj enpremu mian vivon en la teron, Kaj mian honoron li metu en la polvon. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Stariĝu, ho Eternulo, en Via kolero, Leviĝu super la furiozon de miaj premantoj; Kaj vekiĝu por mi, Vi, kiu ordonis fari juĝon. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Kaj amaso da popoloj Vin ĉirkaŭos; Kaj super ili reiru supren.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'La Eternulo juĝas popolojn. Juĝu min, ho Eternulo, laŭ mia justeco kaj laŭ mia pieco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Finiĝu la malboneco de malpiuloj, kaj Vi subtenu justulon, Vi, kiu esploras korojn kaj internaĵojn, justa Dio!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Mia ŝildo estas ĉe Dio, Kiu savas piajn korojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Dio estas juĝanto justa, Kaj Dio minacanta ĉiutage.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Se oni ne reĝustiĝas, Li akrigas Sian glavon, Streĉas Sian pafarkon kaj direktas ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'Kaj Li pretigas por ĝi mortigilojn, Siajn sagojn Li faras bruligaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Jen tiu gravediĝis per malbono, Portis en si malicon, kaj naskis mensogon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Li fosis kavon kaj profundigis ĝin, Kaj li falis en la kavon, kiun li pretigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Lia malico refalos sur lian kapon, Kaj sur lian verton falos lia krimo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Mi gloros la Eternulon pro Lia justeco, Kaj kantos la nomon de la Eternulo Plejalta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Al la ĥorestro. Por la gitito. Psalmo de David. Ho Eternulo, nia Sinjoro, Kiel majesta estas Via nomo sur la tuta tero! Vi levis Vian gloron super la ĉielon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Per la buŝo de junaj infanoj kaj suĉinfanoj Vi fondis al Vi potencon kontraŭ Viaj malamikoj, Por kvietigi la malamikon kaj la venĝemulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Kiam mi rigardas Vian ĉielon, la faron de Viaj fingroj, La lunon kaj la stelojn, kiujn Vi estigis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Kio estas homo, ke Vi lin memoras? Kio estas homido, ke Vi pensas pri li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Vi malaltigis lin malmulte antaŭ Dio; Per honoro kaj beleco Vi lin kronis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Vi faris lin reganto super la faritaĵoj de Viaj manoj; Ĉion Vi metis sub liajn piedojn:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Ŝafojn kaj bovojn ĉiujn Kaj ankaŭ la sovaĝajn bestojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'La birdojn de la ĉielo kaj la fiŝojn de la maro, Ĉion, kio iras la vojojn de la maroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Ho Eternulo, nia Sinjoro, Kiel majesta estas Via nomo sur la tuta tero!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Al la ĥorestro. Por mut-labeno. Psalmo de David. Mi gloros Vin, ho Eternulo, per mia tuta koro; Mi rakontos ĉiujn Viajn mirindaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Mi ĝojos kaj triumfos pro Vi; Mi kantos Vian nomon, ho Vi Plejalta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Ĉar miaj malamikoj turniĝas malantaŭen, Ili falas kaj pereas antaŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Ĉar Vi faris por mi juĝon kaj plenumon de leĝo; Vi sidiĝis sur la trono, Vi justa juĝanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Vi indignis kontraŭ la popoloj, Vi pereigis malpiulojn, Ilian nomon Vi ekstermis por ĉiam kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'La malamikoj malaperis, ruiniĝis por ĉiam; Iliajn urbojn Vi renversis, La memoro pri ili pereis kune kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Sed la Eternulo restas eterne, Li pretigis Sian tronon por juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Kaj Li juĝos la mondon kun justeco, Li plenumos leĝojn inter la popoloj kun senpartieco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'Kaj la Eternulo estos rifuĝo por la premato, Rifuĝo en la tempo de mizero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'Kaj esperos al Vi tiuj, kiuj konas Vian nomon, Ĉar Vi ne forlasas tiujn, kiuj serĉas Vin, ho Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Kantu al la Eternulo, kiu loĝas sur Cion, Rakontu inter la popoloj Liajn farojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Ĉar venĝante por la sango, Li memoras pri ili, Li ne forgesas la krion de malfeliĉuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Estu favora al mi, ho Eternulo; Vidu, kion mi suferas de miaj malamikoj, Vi, kiu suprenlevas min el la pordegoj de la morto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Por ke mi rakontu Vian tutan gloron En la pordegoj de la filino de Cion Kaj mi ĝoju pro Via savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'Eniĝis la popoloj en la kavon, kiun ili elfosis; En la reton, kiun ili metis, enkaptiĝis ilia piedo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Oni ekkonas la Eternulon laŭ la juĝo, kiun Li faris; Per la faroj de siaj manoj estas kaptita la malpiulo. Higajon. Sela..');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'La malbonuloj reiru en Ŝeolon, Ĉiuj popoloj, kiuj forgesas Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Ĉar ne por ĉiam malriĉulo estos forgesita, Kaj la espero de mizeruloj ne pereos por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Leviĝu, ho Eternulo, ke homoj ne tro fortiĝu; La popoloj estu juĝataj antaŭ Via vizaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Metu, ho Eternulo, timon sur ilin, La popoloj sciu, ke ili estas homoj. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Kial, ho Eternulo, Vi staras malproksime? Kial Vi kaŝas Vin en la tempo de la mizero?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Pro la malhumileco de malbonulo suferas malriĉulo; Ili kaptiĝu per la artifikoj, kiujn ili elpensis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Ĉar malbonulo fanfaronas pri la kapricoj de sia animo; Rabanto forlasas, malŝatas la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Malpiulo en sia malhumileco ne esploras; En ĉiuj liaj pensoj Dio ne ekzistas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Li ĉiam iras forte laŭ siaj vojoj; Viaj juĝoj estas tro alte super li; Ĉiujn siajn malamikojn li forspitas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Li diris en sia koro: Mi ne ŝanceliĝos, De generacio al generacio neniam estos al mi malbone.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Lia buŝo estas plena de malbenado, trompo, kaj malico; Sub lia lango estas suferigo kaj malvero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Inside li sidas en la vilaĝoj; Kaŝe li mortigas senkulpulon; Liaj okuloj spionas malriĉulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Li sidas inside en kaŝita loko, kiel leono en la kaverno; Li insidas, por kapti malriĉulon; Kaj li kaptas malriĉulon, tirante lin en sian reton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Li insidas, alpremiĝas, Kaj la malriĉulo falas en liajn fortajn ungegojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Li diras en sia koro: Dio forgesis, Li kovras Sian vizaĝon, Li neniam vidos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Leviĝu, ho Eternulo; ho Dio, levu Vian manon; Ne forgesu mizerulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Por kio malpiulo malŝatas Dion, Kaj diras en sia koro, ke Vi ne postulos respondon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Vi vidas ja, ĉar mizerojn kaj suferojn Vi rigardas, por redoni laŭ Via forto. Al Vi fordonas sin malriĉulo; Por orfo Vi estas helpanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Rompu la brakon de malpiulo kaj malbonulo, Por ke eĉ serĉante lian malbonon, oni ĝin ne trovu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'La Eternulo estas Reĝo por eterne kaj ĉiam, Pereis la idolistoj de Lia tero. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Deziron de humiluloj Vi aŭdas, ho Eternulo; Vi fortigas ilian koron, Vi atentigas Vian orelon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'Por doni juĝon al orfo kaj premato, Por ke oni ĉesu peli homon de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Al la ĥorestro. De David. Ĉe la Eternulo mi rifuĝas. Kial vi diras al mia animo: Flugu kiel birdo sur vian monton?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Ĉar jen la malbonuloj streĉis pafarkon, Almetis sagon sian al la tendeno, Por pafi kaŝe kontraŭ la honestajn korojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Kiam la fundamentoj estas detruitaj, Kion povas fari la justulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'La Eternulo estas en Sia sankta templo; La trono de la Eternulo estas en la ĉielo; Liaj okuloj vidas, Liaj palpebroj esploras la homidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'La Eternulo elprovas justulon; Sed malpiulon kaj perfortemulon Lia animo malamas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Sur la malpiulojn Li pluvigos brulantajn karbojn, fajron kaj sulfuron; Brula vento estos kaliko, destinita por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Ĉar la Eternulo estas justa, Li amas justecon; La piulo vidos Lian vizaĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Al la ĥorestro. Por basuloj. Psalmo de David. Helpu, ho Eternulo, ĉar malaperis piuloj Kaj maloftiĝis fideluloj inter la homidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Malveron ili parolas unuj al aliaj, Vortojn flatajn el koro hipokrita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'La Eternulo ekstermu ĉiun flatan buŝon Kaj langon fanfaronantan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Tiujn, kiuj diras: Per nia lango ni venkos, Nia buŝo estas kun ni; kiu estas sinjoro super ni?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'Ĉar prematoj estas ruinigataj kaj malfeliĉuloj ĝemas, Tial nun Mi Min levos, diras la Eternulo; Mi donos savon al tiuj, kiuj sopiras pri ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'La paroloj de la Eternulo estas paroloj puraj, Arĝento, purigita en tera fandujo kaj sepfoje refandita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Vi, ho Eternulo, konservos ilin, Vi gardos nin kontraŭ ĉi tiu generacio por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Ĉirkaŭe aperas multe da malpiuloj, Kiam malnobleco altiĝas inter la homidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Al la ĥorestro. Psalmo de David. Ĝis kiam, ho Eternulo, Vi tute forgesos pri mi? Ĝis kiam Vi kaŝos Vian vizaĝon antaŭ mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Ĝis kiam mi havos zorgojn en mia animo Kaj sopirojn en mia koro ĉiutage? Ĝis kiam mia malamiko estos supre super mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Rigardu kaj aŭdu min, ho Eternulo, mia Dio; Lumigu miajn okulojn, ke mi ne ekdormu per morto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Ke ne diru mia malamiko: Mi lin venkis; Ke ne ĝoju miaj premantoj, se mi falos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'Sed mi esperas al Via favorkoreco; Mia koro ĝojas pro Via savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Mi kantos al la Eternulo, Ĉar Li faris al mi bonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Al la ĥorestro. De David. La sensaĝulo diris en sia koro: Dio ne ekzistas. Ili sentaŭgiĝis, ili abomeniĝis pro siaj faroj; Ekzistas neniu, kiu faras bonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'La Eternulo el la ĉielo ekrigardis la homidojn, Por vidi, ĉu ekzistas prudentulo, kiu serĉas Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Ĉiuj devojiĝis, ĉiuj malvirtiĝis; Ekzistas neniu, faranta bonon, ne ekzistas eĉ unu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Ĉu ne prudentiĝos ĉiuj, kiuj faras malbonon, Kiuj manĝas mian popolon, kiel oni manĝas panon, Kaj kiuj ne vokas al la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Tie ili forte ektimis, Ĉar Dio estas en la generacio de la justuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Vi malhonoris la konsilon de malriĉulo, Sed la Eternulo estas lia rifuĝejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Ho, ke venu el Cion savo al Izrael! Kiam la Eternulo revenigos Sian forkaptitan popolon, Tiam triumfos Jakob kaj ĝojos Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Psalmo de David. Ho Eternulo, kiu povas gasti en Via tendo? Kiu povas loĝi sur Via sankta monto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Tiu, kiu vivas honeste, agas juste, Kaj parolas veron el sia koro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'Kiu ne kalumnias per sia lango, Ne faras malbonon al sia kunulo, Kaj ne ĵetas malhonoron sur sian proksimulon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'Kiu abomenas malnoblulon Kaj estimas la respektantojn de la Eternulo, Kiu faris ĵuron malprofite por si kaj ĝin ne rompas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Kiu sian monon ne donas procentege, Kaj subaĉetajn donacojn kontraŭ senkulpulo ne akceptas. Kiu tiel agas, tiu neniam falos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Verko de David. Gardu min, ho Dio, ĉar mi rifuĝas ĉe Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Mi diris al la Eternulo: Vi estas mia Sinjoro; Mi ne havas alian bonon krom Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'Al la sanktuloj, kiuj estas sur la tero, Kaj al la majestuloj iras mia tuta deziro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Multiĝos la malĝojoj de tiuj, kiuj sekvis alian; Mi ne verŝos iliajn sangajn verŝoferojn Kaj ne metos iliajn nomojn en mian buŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'La Eternulo estas mia sorta parto kaj kaliko; Vi subtenas mian sorton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Loto agrabla trafis min, Ĉarma estas mia heredo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Mi gloras la Eternulon, kiu konsilas min; Eĉ en la nokto instruas min mia internaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Ĉiam mi vidas la Eternulon antaŭ mi; Ĉar Li estas ĉe mia dekstra mano, mi ne falos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Tial ĝojas mia koro, raviĝas mia animo; Eĉ mia karno ripozas senzorge.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Ĉar Vi ne lasos mian animon al Ŝeol; Vi ne permesos, ke Via sanktulo forputru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Vi konigos al mi la vojon de la vivo; Multe da ĝojoj estas antaŭ Vi, Ĉarmoj estas en Via dekstra mano eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Preĝo de David. Aŭskultu, ho Eternulo, la justulon, atentu mian krion, Donu orelon al mia preĝo el ne malsincera buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'De Vi venos mia juĝo; Viaj okuloj rigardos la veremecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Vi esploras mian koron, ekzamenas ĝin en la nokto; Vi elprovas min, Kaj Vi trovas nenion, kion mi intencus, Sed kio ne volus eliri el mia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Pri homaj faroj, konforme al la vortoj el Via buŝo, Mi gardis min de vojoj kontraŭleĝaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Miaj paŝoj tuj sekvas en Viaj postesignoj, miaj piedoj ne ŝanceliĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Mi vokas al Vi, ĉar Vi respondos al mi, ho Dio; Klinu al mi Vian orelon kaj aŭdu mian parolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Montru Vian mirindan favorkorecon, Vi, kiu per Via dekstra mano helpas la fidantojn kontraŭ la atakantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Gardu min kiel la pupilon de la okulo, Per la ombro de Viaj flugiloj kaŝu min');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'De la malbonuloj, kiuj atakas min, De miaj malamikoj, kiuj ĉirkaŭe insidas kontraŭ mia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Sian koron ili fermis, Per sia buŝo ili parolas fiere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Kien ni iras, ili nin ĉirkaŭas; Siajn okulojn ili direktas, por ĵeti nin sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Li similas leonon, kiu avidas akiron, Kaj leonidon, kiu sidas en kaŝita loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Leviĝu, ho Eternulo, antaŭvenu kaj renversu lin; Savu mian animon kontraŭ la malbonulo per Via glavo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'Kontraŭ la homoj, ho Eternulo, per Via mano, Kontraŭ la homoj de ĉi tiu mondo, kiuj havas sian parton en la nuna vivo, Kaj kies ventron Vi plenigis per Viaj trezoroj, Ke iliaj filoj estos sataj kaj ili lasos restaĵon por siaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Kaj mi en pieco rigardos Vian vizaĝon; Vekiĝante, mi satiĝos per Via bildo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Al la ĥorestro. De la sklavo de la Eternulo, David, kiu eldiris al la Eternulo la vortojn de ĉi tiu kanto, kiam la Eternulo lin savis el la manoj de ĉiuj liaj malamikoj kaj el la mano de Saul. Kaj li diris: Mi varmege Vin amas, ho Eternulo, mia forteco!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'La Eternulo estas mia Roko, kaj mia fortikaĵo, kaj mia Savanto, Mia Dio, mia forta Roko, kiun mi fidas, Mia ŝildo kaj la korno de mia savo, mia rifuĝejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Mi vokas al la Eternulo, la glorinda; Kaj mi saviĝas de miaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Ĉirkaŭis min la ondoj de la morto, Kaj torentoj pereigaj min teruris;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'La ŝnuroj de Ŝeol min ĉirkaŭis, La retoj de la morto min atingis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'En mia premiteco mi vokis la Eternulon, Kaj al mia Dio mi kriis; El Sia templo Li aŭdis mian voĉon, Kaj mia krio al Li atingis Liajn orelojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'Ektremis kaj ekskuiĝis la tero, La fundamentoj de la montoj ekmoviĝis Kaj ekŝanceliĝis, ĉar Li koleris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Leviĝis fumo el Lia nazo, Kaj ekstermanta fajro el Lia buŝo; Karboj ekflamis de ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Li klinis la ĉielon kaj iris malsupren; Kaj densa mallumo estis sub Liaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Kaj Li ekrajdis sur kerubo kaj ekflugis, Kaj Li portiĝis sur la flugiloj de la vento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'El la mallumo Li faris al Si kovron, Tendon Li faris ĉirkaŭ Si el la mallumo de la akvo, densaj nuboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'De la brilo antaŭ Li, tra Liaj densaj nuboj, Flugis hajlo kaj brulantaj karboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'Kaj la Eternulo ektondris en la ĉielo, Kaj la Plejaltulo aŭdigis Sian voĉon; Hajlon kaj brulantajn karbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Li ĵetis Siajn sagojn, kaj dispelis ilin; Ĵetis multajn fulmojn, kaj konfuzis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'Kaj malkovriĝis la kuŝujoj de la akvoj, Kaj nudiĝis la fundamentoj de la universo, De Via minaca voĉo, ho Eternulo, De la kolera spirado de Via nazo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Li etendas el supre la brakon, kaj prenas min; Li eltiras min el grandaj akvoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Li savas min de mia potenca malamiko, Kaj de miaj malamantoj, ĉar ili estas pli fortaj ol mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Ili atingis min en la tago de mia malfeliĉo; Sed la Eternulo fariĝis mia subteno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Kaj Li elkondukis min en vastan lokon; Li liberigis min, ĉar Li estas favora al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'La Eternulo rekompencas min laŭ mia justeco; Laŭ la pureco de miaj manoj Li repagas al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Ĉar mi min tenis je la vojoj de la Eternulo, Kaj mi ne faris malbonon antaŭ mia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Ĉar ĉiuj Liaj leĝoj estis antaŭ mi, Kaj Liajn ordonojn mi ne forigis de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'Mi estis senkulpa antaŭ Li, Kaj mi gardis min, ke mi ne peku.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Kaj la Eternulo rekompencis min laŭ mia justeco, Laŭ la pureco de miaj manoj antaŭ Liaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Kun favorkorulo Vi estas favorkora, Kun piulo Vi estas pia,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'Kun purulo Vi agas laŭ lia pureco, Kaj kun maliculo laŭ lia maliceco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Ĉar humilan popolon Vi helpas, Sed altajn okulojn Vi malaltigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Ĉar Vi lumigas mian lumilon; La Eternulo, mia Dio, lumigas mian mallumon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Ĉar kun Vi mi forkurigas militistaron, Kaj kun mia Dio mi transsaltas muron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'La vojo de Dio estas perfekta; La parolo de la Eternulo estas tute pura; Li estas ŝildo por ĉiuj, kiuj Lin fidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Ĉar kiu estas Dio, krom la Eternulo? Kaj kiu estas Roko, krom nia Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Tiu Dio, kiu ĉirkaŭzonas min per forto Kaj perfektigas mian vojon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Kiu similigas miajn piedojn al cervaj, Kaj starigas min sur miaj altaĵoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'Kiu instruas mian manon militi, Kaj miajn brakojn streĉi kupran pafarkon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Vi donis al mi la ŝildon de Via savo; Kaj Via dekstra mano subtenas min, Kaj Via favoro min grandigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Vi larĝigas mian paŝon sub mi, Por ke ne ŝanceliĝu miaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Mi persekutas miajn malamikojn, kaj mi atingas ilin; Kaj mi ne revenas, ĝis mi ilin pereigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Mi ilin frakasas, ke ili ne povas plu leviĝi; Ili falas sub miajn piedojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Vi ĉirkaŭzonas min per forto por la milito; Miajn atakintojn Vi ĵetas sub min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Vi forkurigas de mi miajn malamikojn, Kaj miajn malamantojn mi ekstermas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Ili krias, sed ne venas helpanto; Al la Eternulo, sed Li ne respondas al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Mi disflugigas ilin, kiel polvon laŭ la vento; Kiel stratan koton mi ilin forĵetas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Vi savas min de popola tumulto; Vi faras min ĉefo de la nacioj; Popolo, kiun mi ne konas, servas min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Per atentaj oreloj ili obeas min; Aligentuloj respektegas min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Aligentuloj senfortiĝas, Kaj kuras terurite el siaj fortikaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Vivas la Eternulo; kaj benata estu mia Roko; Kaj alte glorata estu la Dio de mia savo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Tiu Dio, kiu donas al mi venĝon Kaj submetas al mi popolojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'Kiu savas min de miaj malamikoj, Altigas min super miaj atakintoj, Kaj savas min de perfortulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'Tial mi gloras Vin, ho Eternulo, inter la popoloj, Kaj pri Via nomo mi kantas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Li donas grandan helpon al Sia reĝo, Kaj faras favoraĵon al Sia sanktoleito, Al David kaj al lia idaro, por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Al la ĥorestro. Psalmo de David. La ĉieloj rakontas la gloron de Dio, Kaj la farojn de Liaj manoj raportas la ĉiela firmaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Tago al tago transdonas diron, Kaj nokto al nokto faras sciigon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Sen parolo kaj sen vortoj; Oni ne aŭdas ilian voĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Tra la tuta mondo iras ilia ordono, Kaj ĝis la fino de la universo iras iliaj vortoj; Por la suno Li aranĝis tendon inter ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'Kaj ĝi eliras kiel fianĉo el sia baldakeno, Ĝojas kiel heroo, trakuranta sian vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Sur unu rando de la ĉielo estas ĝia leviĝo, Kaj ĝia rondiro estas ĝis aliaj randoj; Kaj nenio kaŝiĝas antaŭ ĝia varmego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'La instruo de la Eternulo estas perfekta, ĝojigas la animon; La atesto de la Eternulo estas certa, ĝi saĝigas sensaĝulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'La ordonoj de la Eternulo estas justaj, ĝojigas la koron; La ordondiro de la Eternulo estas klara, faras lumon antaŭ la okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'La timo antaŭ la Eternulo estas pura, restas eterne; La juĝoj de la Eternulo estas veraj, kaj ĉiuj estas justaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'Ili estas pli dezirindaj, ol oro kaj ol multe da plej pura oro; Ili estas pli dolĉaj, ol mielo kaj ĉelaraj mielgutoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Ankaŭ Via sklavo instruiĝis per ili; Kiu ilin observas, tiu havas grandan rekompencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Kiu scias siajn erarojn? Purigu min de eraroj kaŝitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Ankaŭ de intencaj eraroj detenu Vian sklavon, Ke ili ne regu super mi. Tiam mi estos perfekta, kaj pura de granda peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Akceptu favore la vortojn el mia buŝo kaj la parolon de mia koro antaŭ Vi, Ho Eternulo, mia Roko kaj mia Liberiganto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Al la ĥorestro. Psalmo de David. La Eternulo aŭskultu vin en tago de mizero; Defendu vin la nomo de Dio de Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Li sendu al vi helpon el la sanktejo, Kaj el Cion Li vin fortigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Li rememoru ĉiujn viajn oferdonojn, Kaj via brulofero aperu grasa antaŭ Li. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Li donu al vi tion, kion deziras via koro; Kaj ĉiujn viajn intencojn Li plenumu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Ni estos gajaj pro Via venko, Kaj pro la nomo de nia Dio ni levos standardon. La Eternulo plenumu ĉiujn viajn petojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Nun mi ekscias, ke la Eternulo savas Sian sanktoleiton; Li aŭskultas lin el Sia sankta ĉielo, Forte savas lin per Sia dekstra mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Unuj fidas veturilojn, aliaj ĉevalojn; Sed ni alvokas la nomon de la Eternulo, nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Ili ŝanceliĝas kaj falas, Kaj ni staras kaj tenas nin forte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Ho Eternulo, savu; La Reĝo respondu al ni, kiam ni vokas al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Al la ĥorestro. Psalmo de David. Ho Eternulo, pro Via forto ĝojas la reĝo, Kaj pro Via helpo kiel forte li triumfas!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Kion lia koro deziris, tion Vi donis al li; Kaj la peton de lia buŝo Vi ne rifuzis. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Vi antaŭvenas al li kun beno de bono; Vi metis sur lian kapon kronon el pura oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Vivon li petis de Vi; Kaj Vi donis al li longan vivon por ĉiam kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Granda estas lia honoro pro Via helpo; Gloron kaj majeston Vi metis sur lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Vi donas al li eternajn benojn; Vi gajigas lin per ĝojo antaŭ Via vizaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Ĉar la reĝo fidas la Eternulon, Kaj pro favoro de la Plejaltulo li ne falos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Trovos Via mano ĉiujn Viajn malamikojn, Via dekstra trovos Viajn malamantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Vi similigos ilin al brulanta forno, kiam Vi koleros; La Eternulo englutos ilin per Sia kolero, Kaj fajro ilin formanĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Ilian naskitaron Vi ekstermos de sur la tero, Kaj ilian semon el inter la homidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Ĉar ili preparis malbonon por Vi, Pripensis atencon, sed ne povis ĝin plenumi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Vi devigos ilin turni al Vi la dorson, Viajn tendenojn Vi direktos kontraŭ iliajn vizaĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Leviĝu, ho Eternulo, en Via forto; Ni kantos kaj gloros Vian potencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Al la ĥorestro. Por ario: Matenkrepuska Cervino. Psalmo de David. Mia Dio, mia Dio, kial Vi forlasis min, Kaj estas malproksima de mia savo, de miaj plendaj paroloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Mia Dio, mi vokas en la tago, kaj Vi ne respondas; En la nokto, kaj mi ne trovas trankvilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Sed Vi estas sankta, Ho Vi, kiu loĝas inter la glorado de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Vin fidis niaj patroj; Ili fidis, kaj Vi ilin helpis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Al Vi ili kriadis kaj estis savataj; Vin ili fidis, kaj ili ne devis honti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Sed mi estas vermo kaj ne homo; Mokata de la homoj, malestimata de la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Ĉiuj, kiuj min vidas, insultas min, Malfermegas la buŝon, balancas la kapon, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'Li apogis sin al la Eternulo: Tiu helpu lin; Tiu savu lin, se Li amas lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Vi eltiris ja min el la ventro, Vi zorgis pri mi sur la brusto de mia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Al Vi mi estis ĵetita de post la momento de mia naskiĝo; De la ventro de mia patrino Vi estas mia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Ne malproksimiĝu de mi, Ĉar malfeliĉo estas proksima, kaj helpanton mi ne havas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Ĉirkaŭis min multaj bovoj, Fortaj bovoj Baŝanaj stariĝis ĉirkaŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Ili malfermegis kontraŭ mi siajn buŝojn, Kiel leono ŝiranta kaj krieganta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Kiel akvo mi disverŝiĝis, Kaj disiĝis ĉiuj miaj ostoj; Mia koro fariĝis kiel vakso, Fandiĝis en mia interno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Mia forto elsekiĝis kiel peco da poto; Mia lango algluiĝis al mia palato; Kaj Vi metas min en tomban polvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Ĉar ĉirkaŭis min hundoj; Amaso da malbonuloj staras ĉirkaŭ mi; Ili mordas miajn manojn kaj piedojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Mi povas kalkuli ĉiujn miajn ostojn; Ili rigardas kaj konstante rigardas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Ili dividas miajn vestojn inter si, Pri mia tuniko ili lotas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Sed Vi, ho Eternulo, ne malproksimiĝu; Mia forto, rapidu, por helpi min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Savu de la glavo mian animon, Mian solan savu de la hundo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Savu min de buŝo de leono, Kaj helpu min kontraŭ kornoj de bubaloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Mi predikos Vian nomon al miaj fratoj; En la mezo de popola kunveno mi Vin gloros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Respektantoj de la Eternulo, gloru Lin; Tuta semo de Jakob, honoru Lin; Tuta semo de Izrael, estimegu Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Ĉar Li ne malŝatis kaj ne malestimis la suferojn de premato, Kaj ne kaŝis antaŭ li Sian vizaĝon; Sed aŭskultis lin, kiam tiu kriis al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Vin mi gloros en granda komunumo; Mi plenumos miajn promesojn antaŭ Liaj respektantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'La humiluloj manĝu kaj satiĝu, Gloru la Eternulon Liaj serĉantoj; Via koro vivu eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Rememoros kaj revenos al la Eternulo ĉiuj finoj de la mondo; Kaj kliniĝos antaŭ Vi ĉiuj popolaj familioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Ĉar al la Eternulo apartenas la reĝado; Li reĝas super la popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Manĝos kaj kliniĝos ĉiuj grasuloj de la tero; Antaŭ Li genufleksos ĉiuj forirantaj al la tombo Kaj nepovantaj konservi sian animon viva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Naskotaro Lin servos; Oni predikos pri mia Sinjoro al la estonta generacio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Al naskota popolo oni venos kaj predikos Pri Lia justeco kaj pri Liaj faroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Psalmo de David. La Eternulo estas mia paŝtisto; mi mankon ne havos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Sur verdaj herbejoj Li ripozigas min, Apud trankvilaj akvoj Li kondukas min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Li kvietigas mian animon; Li kondukas min laŭ vojo de la vero, pro Sia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Eĉ kiam mi iros tra valo de densa mallumo, Mi ne timos malbonon, ĉar Vi estas kun mi; Via bastono kaj apogiĝilo trankviligos min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Vi kovras por mi tablon antaŭ miaj malamikoj; Vi ŝmiris per oleo mian kapon, mia pokalo estas plenigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Nur bono kaj favoro sekvos min en la daŭro de mia tuta vivo; Kaj mi restos en la domo de la Eternulo eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Psalmo de David. Al la Eternulo apartenas la tero, kaj ĉio, kio ĝin plenigas, La mondo kaj ĉiuj ĝiaj loĝantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Ĉar Li sur la maroj ĝin fondis Kaj sur la akvoj ĝin fortikigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Kiu supreniros sur la monton de la Eternulo? Kaj kiu staros ĉe Lia sankta loko?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Tiu, kiu havas purajn manojn kaj senmakulan koron, Kiu ne fordonis sian animon al malvero Kaj ne ĵuras trompe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Li ricevos benon de la Eternulo, Kaj bonfarojn de Dio, lia savanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Tio estas la gento de Liaj adorantoj, De la serĉantoj de Via vizaĝo, ho Dio de Jakob. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Levu, pordegoj, viajn kapojn; Kaj leviĝu, pordoj antikvaj, Por ke eniru la Reĝo de gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Kiu estas tiu Reĝo de gloro? La Eternulo forta kaj potenca, La Eternulo, la potenculo de milito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Levu, pordegoj, viajn kapojn; Kaj leviĝu, pordoj antikvaj, Por ke eniru la Reĝo de gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Kiu estas tiu Reĝo de gloro? La Eternulo Cebaot, Li estas la Reĝo de gloro. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'De David. Al Vi, ho Eternulo, mi levas mian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Ho mia Dio, Vin mi fidas; Ne lasu min hontiĝi; Ne lasu, ke miaj malamikoj moku pri mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Ĉar neniu el tiuj, kiuj esperas al Vi, hontiĝos; Nur tiuj hontiĝos, kiuj forlasas Vin senpripense.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Viajn vojojn, ho Eternulo, montru al mi; Instruu min sekvi Vian iradon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Gvidu min en Via vero kaj lernigu min, Ĉar Vi estas la Dio, kiu min helpas; Al Vi mi esperas ĉiun tagon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Rememoru, ho Eternulo, Vian kompatemecon kaj Vian favorkorecon, Ĉar ili estis de ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'La pekojn de mia juneco kaj miajn krimojn ne rememoru; Laŭ Via favorkoreco rememoru min, Pro Via boneco, ho Eternulo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Bona kaj justa estas la Eternulo, Tial Li montras al pekantoj la vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Li gvidas la humilulojn en justeco, Kaj instruas al la humiluloj Siajn vojojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Ĉiuj vojoj de la Eternulo estas favorkoreco kaj fideleco al tiuj, Kiuj observas Lian interligon kaj Liajn leĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Pro Via nomo, ho Eternulo, pardonu al mi mian pekon, Ĉar ĝi estas granda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Al ĉiu homo, kiu timas la Eternulon, Li montras la vojon, kiun tiu devas elekti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Lia animo ĝuos bonon, Kaj liaj idoj posedos la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Konfidon de la Eternulo havas Liaj timantoj; Kaj Sian aranĝon Li sciigas al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Miaj okuloj estas ĉiam direktitaj al la Eternulo, Ĉar Li eltiras el reto miajn piedojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Turnu Vin al mi kaj korfavoru min, Ĉar mi estas soleca kaj mizera.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'La suferoj de mia koro estas grandaj; El mia premateco elkonduku min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Rigardu mian suferon kaj mizeron, Kaj pardonu ĉiujn miajn pekojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Rigardu, kiel multaj estas miaj malamikoj Kaj per kia kruela malamo ili min malamas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Gardu mian animon kaj savu min; Ne lasu min hontiĝi, ĉar Vin mi fidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Senkulpeco kaj justeco defendu min, Ĉar al Vi mi esperas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Liberigu, ho Dio, Izraelon el ĉiuj liaj suferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'De David. Juĝu min, ho Eternulo, ĉar mi iris en sincereco kaj la Eternulon mi fidis; Mi ne ŝanceliĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Esploru min, ho Eternulo, kaj elprovu min; Refandu mian internaĵon kaj mian koron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Ĉar Via favorkoreco estas antaŭ miaj okuloj; Kaj mi marŝas en Via vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Mi ne sidas kun homoj malveremaj, Kaj kun falsemuloj mi ne iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Mi malamas societon de malbonfarantoj, Kaj kun malpiuloj mi ne sidos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Mi lavas miajn manojn per senkulpeco; Kaj mi moviĝas ĉirkaŭ Via altaro, ho Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'Por aŭdigi laŭte gloradon Kaj famigi ĉiujn Viajn miraklojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Ho Eternulo, mi amas la ejon de Via domo, Kaj la lokon, en kiu loĝas Via gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Ne pereigu mian animon kune kun la pekuloj, Nek mian vivon kun la sangaviduloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'En kies manoj estas krimo Kaj kies dekstra mano estas plena de subaĉetaj donacoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Kaj mi iras en senkulpeco; Liberigu min kaj korfavoru min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Mia piedo staras sur ebena loko; En kunvenoj mi benos la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'De David. La Eternulo estas mia lumo kaj mia savo; kiun mi devas timi? La Eternulo estas la forto de mia vivo; kiu povas min teruri?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Kiam alproksimiĝos al mi malbonfarantoj, por manĝi mian karnon, Miaj kontraŭuloj kaj malamikoj, ili surpuŝiĝos kaj falos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Se elpaŝos kontraŭ min armeo, Mia koro ne ektimos; Se leviĝos kontraŭ min milito, Ankaŭ tiam mi havos fidon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Nur unu aferon mi petas de la Eternulo, nur tion mi deziras: Ke mi restu en la domo de la Eternulo en la daŭro de mia tuta vivo, Por rigardi la ĉarmon de la Eternulo, admiri Lian templon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Ĉar Li kovros min en Sia kabano en la tago de malbono; Li kaŝos min en sekreta loko de Sia tendo; Sur rokon Li levos min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'Kaj nun leviĝos mia kapo super miajn malamikojn, kiuj min ĉirkaŭas; Kaj mi oferfaros en Lia tendo oferojn de danko; Mi kantos kaj gloros la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Aŭskultu, ho Eternulo, mian voĉon, kiam mi vokas; Korfavoru min, kaj respondu al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'De Vi diris al mi mia koro: Serĉu Mian vizaĝon. Vian vizaĝon, ho Eternulo, mi serĉas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Ne kaŝu antaŭ mi Vian vizaĝon, Ne forpuŝu en kolero Vian sklavon; Vi estis mia helpo, Ne forpuŝu kaj ne forlasu min, ho Dio de mia savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Ĉar mia patro kaj mia patrino min forlasis, Sed la Eternulo min akceptis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Instruu al mi, ho Eternulo, Vian vojon, Kaj konduku min sur ĝusta irejo, spite miajn insidantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Ne fordonu min al la volo de miaj premantoj; Ĉar stariĝis kontraŭ mi falsaj atestantoj, plenaj de rabemeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Se mi ne esperus vidi la bonecon de la Eternulo En la lando de vivantoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Esperu al la Eternulo; Tenu vin forte, forta estu via koro; Jes, esperu al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'De David. Al Vi, ho Eternulo, mi vokas; Mia Roko, ne silentu al mi; Se Vi silentos al mi, mi similiĝos al tiuj, Kiuj iras en la tombon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Aŭskultu la voĉon de mia petego, kiam mi krias al Vi, Kiam mi levas miajn manojn al Via plejsanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Ne kunpereigu min kune kun malpiuloj, kaj kun krimfarantoj, Kiuj parolas pace kun siaj proksimuloj, Dum malbono estas en ilia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Redonu al ili laŭ iliaj faroj kaj laŭ iliaj malbonaj agoj; Laŭ la faroj de iliaj manoj redonu al ili; Redonu al ili, kion ili meritas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Ĉar ili ne atentas la agojn de la Eternulo Kaj la farojn de Liaj manoj, Li disbatos ilin kaj ne rekonstruos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Glorata estu la Eternulo, Ĉar Li aŭskultis la voĉon de mia petego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'La Eternulo estas mia forto kaj mia ŝildo; Lin fidis mia koro, kaj Li helpis min; Tial ekĝojas mia koro, Kaj per mia kanto mi Lin gloros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'La Eternulo estas ilia forto, Li estas savanta forto por Sia sanktoleito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Helpu Vian popolon kaj benu Vian heredon, Kaj paŝtu kaj altigu ilin eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Psalmo de David. Tributu al la Eternulo, vi potenculoj, Tributu al la Eternulo honoron kaj forton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Tributu al la Eternulo la honoron de Lia nomo; Kliniĝu antaŭ la Eternulo en sankta ornamo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'La voĉo de la Eternulo iras super la akvoj; La Dio de gloro tondras, La Eternulo super grandaj akvoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'La voĉo de la Eternulo iras kun forto, La voĉo de la Eternulo iras kun majesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'La voĉo de la Eternulo rompas cedrojn, La Eternulo rompas la cedrojn de Lebanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'Li saltigas ilin kiel bovidon, Lebanonon kaj Sirjonon kiel bubalidon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'La voĉo de la Eternulo elhakas fajran flamon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'La voĉo de la Eternulo skuas dezerton, La Eternulo skuas la dezerton Kadeŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'La voĉo de la Eternulo igas cervinojn naski, kaj nudigas arbarojn; Kaj en Lia templo ĉio parolas pri Lia gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'La Eternulo regis en la tempo de la diluvo, La Eternulo restos Reĝo eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'La Eternulo donos forton al Sia popolo, La Eternulo benos Sian popolon per paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Psalmo-kanto ĉe inaŭguro de la Domo; de David. Mi gloros Vin alte, ho Eternulo, Ĉar Vi levis min kaj Vi ne lasis miajn malamikojn triumfi super mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Ho Eternulo, mia Dio, mi vokis al Vi, Kaj Vi min sanigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Ho Eternulo, Vi ellevis el Ŝeol mian animon; Vi vivigis min, ke mi ne iru en la tombon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Kantu al la Eternulo, ho Liaj piuloj, Kaj gloru Lian sanktan nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Ĉar nur momenton daŭras Lia kolero, Sed tutan vivon daŭras Lia favoro; Vespere povas esti ploro, Sed matene venos ĝojego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Kaj mi diris en la tempo de mia feliĉo: Mi neniam falos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Ho Eternulo, per Via favoro Vi starigis mian monton fortike; Sed kiam Vi kaŝis Vian vizaĝon, mi konfuziĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'Al Vi, ho Eternulo, mi vokis, Kaj al la Eternulo mi preĝis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'Kion utilos mia sango, se mi iros en la tombon? Ĉu gloros Vin polvo? ĉu ĝi aŭdigos Vian veron?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Aŭskultu, ho Eternulo, kaj korfavoru min; Ho Eternulo, estu helpanto al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Vi anstataŭigis al mi mian plendon per danco; Vi deprenis de mi mian sakaĵon kaj zonis min per ĝojo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Por ke mia animo kantu al Vi kaj ne silentiĝu. Ho Eternulo, mia Dio, eterne mi Vin gloros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Al la ĥorestro. Psalmo de David. Vin, ho Eternulo, mi fidas, ke mi neniam estu hontigita; Per Via justeco savu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Klinu al mi Vian orelon, rapide savu min! Estu por mi forta roko, fortika kastelo, por helpi min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Ĉar Vi estas mia roko kaj mia kastelo; Kaj pro Via nomo gvidu min kaj konduku min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Eligu min el la reto, kiun ili metis kontraŭ mi; Ĉar Vi estas mia fortikaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'En Vian manon mi transdonas mian spiriton; Vi savas min, ho Eternulo, Dio de la vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'Mi malamas la adorantojn de vantaj idoloj, Sed mi fidas la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Mi gajas kaj ĝojas pro Via favoro; Ĉar Vi vidis min mizeron, Vi eksciis la suferojn de mia animo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Kaj Vi ne transdonis min en la manon de malamiko, Vi starigis miajn piedojn sur vasta loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Korfavoru min, ho Eternulo, ĉar mi suferas; Malfortiĝis de malĝojo mia okulo, mia animo, kaj mia korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Ĉar mia vivo konsumiĝis de malĝojo kaj miaj jaroj de ĝemado; Mia forto malaperis per mia kulpo, kaj miaj ostoj malfortiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Per ĉiuj miaj malamikoj mi fariĝis granda hontindaĵo por miaj najbaroj Kaj teruraĵo por miaj konatoj; Kiuj vidas min sur la strato, tiuj forkuras de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Oni forgesis pri mi en la koro, kiel pri mortinto; Mi fariĝis kiel rompita vazo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Ĉar mi aŭdas la insultojn de multaj; Ĉirkaŭe estas minacoj; Ili kune konspiras kontraŭ mi, Ili intencas pereigi mian vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Sed mi-mi fidas Vin, ho Eternulo; Mi diras: Vi estas mia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'En Via mano estas mia sorto; Savu min de la mano de miaj malamikoj kaj persekutantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Lumu per Via vizaĝo al Via sklavo, Helpu min per Via boneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Ho Eternulo, ne hontigu min, ĉar mi vokis al Vi; Hontigitaj estu la malpiuloj, ili silentiĝu por Ŝeol.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Mutiĝu la mensogaj buŝoj, Kiuj parolas arogante kontraŭ piulo, Kun fiero kaj malestimo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Kiel granda estas Via boneco, kiun Vi konservis por tiuj, kiuj Vin timas, Kaj kiun Vi faris antaŭ la homoj por tiuj, kiuj Vin fidas!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Vi kovras ilin per la kovro de Via vizaĝo kontraŭ homaj atencoj, Vi kaŝas ilin en tendo kontraŭ malamikaj langoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Glorata estu la Eternulo, Kiu aperigis al mi mirindan favoron en fortikigita urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Kaj mi diris en mia konfuziĝo: Mi estas forpuŝita for de Viaj okuloj; Tamen Vi aŭskultis la voĉon de mia preĝo, kiam mi vokis al Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Amu la Eternulon, ĉiuj Liaj piuloj; La fidelulojn la Eternulo gardas, Kaj Li repagas sufiĉege al tiuj, kiuj agas malhumile.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Estu kuraĝaj, kaj forta estu via koro, Vi ĉiuj, kiuj esperas al la Eternulo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Instruo de David. Feliĉa estas tiu, kies krimo estas pardonita, kies peko estas kovrita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Feliĉa estas la homo, al kiu la Eternulo ne kalkulas lian kulpon Kaj en kies spirito estas nenia malvero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Kiam mi silentis, miaj ostoj senfortiĝis De mia ĉiutaga ploregado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Ĉar tage kaj nokte pezis sur mi Via mano; La freŝecon de mia sukoj anstataŭis sekeco de somero. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Mian pekon mi konfesis al Vi, kaj mian kulpon mi ne kaŝis; Mi diris: Mi konfesos miajn krimojn al la Eternulo; Kaj Vi deprenis la kulpon de mia peko. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Pro tio preĝu antaŭ Vi ĉiu piulo en favora tempo, Por ke ĉe la disverŝiĝo de grandaj akvoj ili lin ne atingu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Vi estas mia ŝirmo; Kontraŭ sufero Vi min gardos, Per kantoj de savo Vi min ĉirkaŭos. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Mi prudentigos vin, kaj montros al vi la vojon, kiun vi devas iri; Kun konsiloj Mi direktos sur vin Mian okulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Ne estu kiel ĉevalo, kiel senprudenta mulo, Al kiuj oni devas kateni la buŝon per brido kaj buŝpeco, Alie ili ne venos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Multajn frapojn havas la malpiulo; Sed kiu fidas la Eternulon, tiun ĉirkaŭas favoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Ĝoju pro la Eternulo, kaj gaju, ho justuloj; Kaj triumfu ĉiuj, kiuj havas pian koron!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Ĝoje kantu, ho piuloj, antaŭ la Eternulo; Al la justuloj konvenas glorado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Gloru la Eternulon per harpo, Per dekkorda psaltero ludu al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Kantu al Li novan kanton, Bone ludu al Li kun trumpetado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Ĉar ĝusta estas la vorto de la Eternulo, Kaj ĉiu Lia faro estas fidinda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Li amas justecon kaj juĝon; La tero estas plena de la boneco de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Per la vorto de la Eternulo estiĝis la ĉielo; Kaj per la spiro de Lia buŝo estiĝis ĝia tuta ekzistantaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Li kolektis kiel en tenujon la akvon de la maro, Li metis la abismojn en konservejojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Timu la Eternulon la tuta tero; Tremu antaŭ Li ĉiuj loĝantoj de la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Ĉar Li diris, kaj tio fariĝis; Li ordonis, kaj tio aperis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'La Eternulo neniigas la interkonsenton de la popoloj, Li detruas la intencojn de la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'La decido de la Eternulo restas eterne, La pensoj de Lia koro restas de generacio al generacio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Felica estas la popolo, kies Dio estas la Eternulo; La gento, kiun Li elektis al Si kiel heredon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'El la ĉielo la Eternulo rigardas, Li vidas ĉiujn homidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'De la trono, sur kiu Li sidas, Li rigardas ĉiujn, kiuj loĝas sur la tero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'Li, kiu kreis la korojn de ili ĉiuj, Kiu rimarkas ĉiujn iliajn farojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'La reĝon ne helpos granda armeo, Fortulon ne savos granda forto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Vana estas la ĉevalo por helpo, Kaj per sia granda forto ĝi ne savos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Jen la okulo de la Eternulo estas sur tiuj, kiuj Lin timas, Kiuj esperas Lian favoron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'Ke Li savu de morto ilian animon Kaj nutru ilin en tempo de malsato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Nia animo fidas la Eternulon; Li estas nia helpo kaj nia ŝildo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'Ĉar pro Li ĝojas nia koro, Ĉar ni fidas Lian sanktan nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Via favoro, ho Eternulo, estu super ni, Kiel ni esperas al Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'De David, kiam li ŝajnigis sin freneza antaŭ Abimeleĥ, kaj tiu lin forpelis kaj li foriris. Mi gloros la Eternulon en ĉiu tempo; Ĉiam laŭdo por Li estos en mia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Per la Eternulo gloriĝas mia animo; La humiluloj aŭdu kaj ĝoju.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Gloru la Eternulon kun mi, Kaj ni altigu kune Lian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Mi serĉis la Eternulon, kaj Li respondis al mi, Kaj de ĉiuj miaj danĝeroj Li savis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Kiuj rigardas al Li, ricevas lumon, Kaj ilia vizaĝo ne kovriĝos per honto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Jen ĉi tiu mizerulo vokis, kaj la Eternulo aŭdis, Kaj de ĉiuj liaj mizeroj Li savis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Anĝelo de la Eternulo postenas ĉirkaŭ tiuj, kiuj Lin timas, Kaj Li ilin savas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Provu kaj vidu, kiel bona estas la Eternulo; Feliĉa estas la homo, kiu Lin fidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Timu la Eternulon, Liaj sanktuloj; Ĉar nenio mankas al tiuj, kiuj Lin timas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Leonidoj estas senhavaj kaj malsataj; Sed kiuj serĉas la Eternulon, tiuj havas mankon en nenia bono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Venu, infanoj, aŭskultu min; Pri timo antaŭ la Eternulo mi vin instruos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Kiu ajn vi estas, homo, Kiu deziras vivon kaj amas multajn kaj bonajn tagojn:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Gardu vian langon kontraŭ malbono, Kaj vian buŝon kontraŭ mensoga parolo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Dekliniĝu de malbono kaj faru bonon, Serĉu pacon kaj ĉasu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'La okuloj de la Eternulo estas turnitaj al la piuloj, Kaj Liaj oreloj al iliaj krioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'La vizaĝo de la Eternulo estas kontraŭ tiuj, kiuj faras malbonon, Por ekstermi de la tero la memoron pri ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Oni krias, kaj la Eternulo aŭdas, Kaj de ĉiuj iliaj mizeroj Li ilin savas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Proksima estas la Eternulo al tiuj, kies koro estas rompita, Kaj la spirite suferantajn Li helpas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Multaj estas la suferoj de piulo; Sed de ĉiuj la Eternulo lin savas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Li gardas ĉiujn liajn ostojn; Eĉ unu el ili ne rompiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'La malbonulon mortigos la malbono; Kaj la malamantoj de piulo pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'La Eternulo liberigas la animon de Siaj sklavoj; Kaj ne pereos ĉiuj, kiuj Lin fidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'De David. Batalu, ho Eternulo, kontraŭ tiuj, kiuj batalas kontraŭ mi; Militu kontraŭ tiuj, kiuj militas kontraŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Prenu ŝildon kaj armilojn, Kaj stariĝu, por helpi min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Kaj nudigu ponardegon, kaj stariĝu kontraŭ miaj persekutantoj; Diru al mia animo: Via helpo Mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Hontigitaj kaj malhonoritaj estu tiuj, kiuj celas kontraŭ mia animo; Turniĝu reen kaj estu hontigitaj tiuj, kiuj intencas malbonon kontraŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Ili estu kiel grenventumaĵo antaŭ vento, Kaj anĝelo de la Eternulo ilin forpelu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Ilia vojo estu malluma kaj glitiga, Kaj anĝelo de la Eternulo ilin persekutu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Ĉar sen mia kulpo ili submetis por mi sian reton, Sen mia kulpo ili fosis sub mia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Venu sur lin pereo neatendite, Kaj lia reto, kiun li kaŝis, kaptu lin; Por pereo li falu en ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Kaj mia animo ĝojos pro la Eternulo, Triumfos pro Lia helpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Ĉiuj miaj ostoj diros: Ho Eternulo, kiu egalas Vin, Kiu liberigas mizerulon de lia perfortanto, Mizerulon kaj malriĉulon de lia rabanto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Stariĝas kontraŭ mi krimaj atestantoj; Kion mi ne scias, pri tio ili min demandas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Ili pagas al mi malbonon por bono, Atencon kontraŭ mia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Kaj mi dum ilia malsano metis sur min sakaĵon, Mi turmentis mian animon per fasto, Kaj mi preĝis sincere, kiel pri mi mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Mi kondutis, kvazaŭ ili estus miaj amikoj, miaj fratoj; Kiel homo, kiu funebras pri sia patrino, mi profunde malĝojis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Sed kiam mi difektiĝis, ili ĝojis, kaj ili kuniĝis; Kuniĝis kontraŭ mi la senkoruloj, kiam mi ne atendis: Ili ŝiris kaj ne ĉesis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'Laŭ la maniero de malpiaj parazitoj, Ili kunfrapis kontraŭ mi siajn dentojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Mia Sinjoro! kiel longe Vi tion rigardos? Deturnu mian animon de iliaj atakoj, Mian solan de la leonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Mi gloros Vin en granda kunveno, Meze de multe da popolo mi Vin laŭdos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Ne ĝoju pri mi miaj maljustaj malamikoj; Kaj tiuj, kiuj malamas min sen mia kulpo, ne moku per la okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Ĉar ne pri paco ili parolas, Kaj kontraŭ la kvietuloj sur la tero ili pripensas malicajn intencojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Ili larĝe malfermis kontraŭ mi sian buŝon, Kaj diris: Ha, ha! nia okulo vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Vi vidis, ho Eternulo; ne silentu! Mia Sinjoro, ne malproksimiĝu de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Vekiĝu kaj leviĝu, por fari al mi juĝon, Mia Dio kaj mia Sinjoro, pri mia disputo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Juĝu min laŭ Via justeco, ho Eternulo, mia Dio; Kaj ili ne ĝoju pri mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Ili ne diru en sia koro: Ha, ha! tio estas laŭ nia deziro; Ili ne diru: Ni lin englutis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Ili estu hontigitaj kaj malhonoritaj ĉiuj, kiuj ĝojas pro mia malfeliĉo; Vestiĝu per honto kaj malhonoro tiuj, kiuj fanfaronas kontraŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Triumfu kaj ĝoju tiuj, kiuj deziras justecon por mi; Kaj ili diru ĉiam: Granda estas la Eternulo, Kiu deziras bonstaton por Sia sklavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Kaj mia lango rakontados pri Via justeco Kaj ĉiutage pri Via gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Al la ĥorestro. De David, sklavo de la Eternulo. La pekado de malpiulo parolas al lia koro; Antaŭ liaj okuloj ne ekzistas timo antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Ĉar ĝi flatas al li en liaj okuloj, Ĝis lia pekado eltroviĝos kaj li malamiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'La paroloj de lia buŝo estas krimo kaj malvero; Li ne volas kompreni, por fari bonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Krimon li pripensas sur sia kuŝejo; Li staras sur vojo ne bona; Malbonon li ne abomenas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Ho Eternulo, ĝis la ĉielo atingas Via boneco, Via vereco ĝis la nuboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Via justeco estas kiel la montoj de Dio, Viaj juĝoj estas granda abismo; Homon kaj bruton Vi helpas, ho Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Kiel grandvalora estas Via favoro, ho Dio! Kaj la homidoj ricevas rifuĝon en la ombro de Viaj flugiloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Ili satiĝas per la riĉa havo de Via domo, Kaj el la rivero de Viaj bonaĵoj Vi ilin trinkigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Ĉar ĉe Vi estas la fonto de vivo, Kaj en Via lumo ni vidas lumon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Venigu Vian favoron sur tiujn, kiuj Vin konas, Kaj Vian bonecon sur la honestulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Ne paŝu sur min piedo de fiereco, Kaj mano de malpiuloj ne renversu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Tie falu la farantoj de malbono; Ili estu renversitaj kaj ne povu sin levi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'De David. Ne incitiĝu pro la malvirtuloj; Ne enviu tiujn, kiuj agas maljuste.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Ĉar simile al herbo ili rapide dehakiĝas, Kaj kiel verda vegetaĵo ili forvelkas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Fidu la Eternulon kaj faru bonon; Loĝu sur la tero kaj konservu honestecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'Serĉu plezuron ĉe la Eternulo, Kaj Li plenumos la dezirojn de via koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Transdonu al la Eternulo vian vojon kaj fidu Lin, Kaj Li faros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'Kaj Li aperigos vian pravecon kiel lumon, Kaj vian justecon kiel tagmezon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Silentu antaŭ la Eternulo kaj esperu al Li; Ne incitiĝu, kiam sukcesas homo, Kiu plenumas malbonajn intencojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Detenu vin de kolero kaj forlasu furiozon; Ne incitiĝu, ke vi ne faru malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Ĉar malbonfarantoj ekstermiĝos, Kaj la esperantaj al la Eternulo heredos la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Ankoraŭ malmulte da tempo pasos, kaj la malpiulo jam ne ekzistos; Vi rigardos lian lokon, kaj li ne estos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Kaj la humiluloj heredos la teron Kaj ĝuos grandan pacon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Malvirtulo malbonintencas kontraŭ virtulo Kaj frapas kontraŭ li per siaj dentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Sed mia Sinjoro ridas pri li; Ĉar Li vidas, ke venas lia tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Glavon nudigas la malvirtuloj kaj streĉas sian pafarkon, Por faligi mizerulon kaj malriĉulon kaj buĉi virtulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Ilia glavo trafos en ilian koron, Kaj iliaj pafarkoj rompiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Pli bona estas la malmulto, kiun havas virtulo, Ol la granda havo de multaj malpiuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Ĉar la brakoj de malpiuloj rompiĝas; Sed la virtulojn la Eternulo subtenas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'La Eternulo scias la tagojn de la virtuloj; Kaj ilia havo restos eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Ili ne estos hontigitaj en tempo malbona, Kaj en tagoj de malsato ili estos sataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Ĉar la malvirtuloj pereos, Kaj la malamikoj de la Eternulo malaperos kiel beleco de la herbejoj, Ili malaperos kiel fumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Malpiulo prunteprenas kaj ne pagas; Sed piulo korfavoras kaj donas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Ĉar Liaj benitoj heredos la teron, Kaj Liaj malbenitoj ekstermiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'De la Eternulo fortikiĝas la paŝoj de virta homo, Kaj lia vojo plaĉas al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Falante, li ne estos forĵetita; Ĉar la Eternulo subtenos lian manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Mi estis juna kaj mi maljuniĝis, Kaj mi ne vidis virtulon forlasita, Nek liajn infanojn petantaj panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Ĉiutage li korfavoras kaj pruntedonas, Kaj liaj infanoj estos benitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Forturniĝu de malbono kaj faru bonon, Kaj vi vivos eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Ĉar la Eternulo amas justecon, Kaj ne forlasas Siajn fidelulojn; Ĉiam ili estos gardataj; Sed la semo de la malpiuloj estos ekstermita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'La virtuloj heredos la teron Kaj loĝos sur ĝi eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'La buŝo de virtulo parolas saĝon, Kaj lia lango diras justecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'La ordonoj de lia Dio estas en lia koro; Liaj paŝoj ne ŝanceliĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Malvirtulo subrigardas virtulon Kaj celas mortigi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'Sed la Eternulo ne lasos lin en liaj manoj, Kaj ne kondamnos lin, kiam li estos juĝata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Esperu al la Eternulo kaj tenu vin je Lia vojo, Kaj Li altigos vin, ke vi heredu la teron; Vi vidos la ekstermon de la malvirtuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Mi vidis malpiulon, kiu estis spitema, Kaj tenis sin larĝe, kiel sukplena multebranĉa arbo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'Sed apenaŭ mi preterpasis, li jam ne ekzistis; Mi serĉis lin, kaj li jam ne estis trovebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Konservu senkulpecon kaj celu veron, Ĉar estontecon havas homo pacema;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'Sed la krimuloj ĉiuj estos ekstermitaj; La estonteco de la malpiuloj pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'La virtuloj havas helpon de la Eternulo; Li estas ilia forto en tempo de mizero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Kaj la Eternulo ilin helpos kaj savos; Li savos ilin de malbonuloj kaj helpos ilin, Ĉar ili fidas Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Psalmo de David. Pro memoro. Ho Eternulo, ne en Via kolero min riproĉu, Kaj ne en Via furiozo min punu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Ĉar Viaj sagoj penetris en min, Kaj pezas sur mi Via mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Ekzistas neniu sana loko en mia korpo pro Via kolero, Nenio sendifekta ekzistas en miaj ostoj pro mia peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Ĉar miaj krimoj superas mian kapon; Kiel peza ŝarĝo, ili estas tro pezaj por mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Malbonodoras kaj pusas miaj ulceroj Pro mia malsaĝeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Mi kurbiĝis kaj kliniĝis treege, La tutan tagon mi iras malgaja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Ĉar miaj internaĵoj estas plenaj de brulumo, Kaj ne ekzistas sana loko en mia korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Mi tute senfortiĝis kaj kadukiĝis, Mi kriegas pro malkvieteco de mia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Mia Sinjoro, antaŭ Vi estas ĉiuj miaj deziroj, Kaj mia ĝemo ne estas kaŝita antaŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Mia koro tremegas, forlasis min mia forto; Kaj eĉ la lumo de miaj okuloj ne estas ĉe mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Miaj amikoj kaj kamaradoj repaŝis pro mia pesto, Kaj miaj proksimuloj stariĝis malproksime.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Kaj insidis kontraŭ mi tiuj, kiuj celas mian vivon, Kaj miaj malbondezirantoj parolas pri mia pereo, Kaj malicojn ili pripensas ĉiutage.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Kaj mi estas kiel surdulo kaj ne aŭdas; Kiel mutulo, kiu ne malfermas sian buŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Mi estas kiel homo, kiu ne aŭdas Kaj kiu ne havas en sia buŝo reparolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Sed al Vi, ho Eternulo, mi esperas; Vi aŭskultos, mia Sinjoro, mia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Ĉar mi diris: Ili povus ĝoji pri mi; Ili fanfaronus pri mi, kiam mia piedo ekŝanceliĝus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Ĉar mi estas preta fali, Kaj mia sufero estas ĉiam antaŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Ĉar mi konfesas mian kulpon; Kaj min ĉagrenas mia peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Kaj la malamikoj de mia vivo estas fortaj, Kaj multaj estas miaj senkaŭzaj malamantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Kaj tiuj, kiuj pagas al mi malbonon por bono, Atakas min pro tio, ke mi celas bonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Ne forlasu min, ho Eternulo; Mia Dio, ne malproksimiĝu de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Rapidu, por helpi min, Mia Sinjoro, mia helpo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Al la ĥorestro Jedutun. Psalmo de David. Mi diris: Mi gardos min sur miaj vojoj, ke mi ne peku per mia lango; Mi bridos mian buŝon, kiam malpiulo staras kontraŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Mi estis muta kaj silenta, mi silentis eĉ pri bono; Kaj mia sufero estis mordanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Ekbrulis mia koro en mia interno, En miaj pensoj ekflamis fajro, Mi ekparolis per mia lango:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Sciigu al mi, ho Eternulo, mian finon, Kaj kia estos la daŭro de miaj tagoj, Por ke mi sciu, kiel neniiĝa mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Jen Vi donis al mi tagojn larĝajn kiel manplato, Kaj la daŭro de mia vivo estas antaŭ Vi kiel nenio; Absoluta vantaĵo estas ĉiu homo, kiel ajn forte li starus. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Nur kiel fantomo iras la homo, nur vante li klopodas; Li kolektas, kaj ne scias, kiu ĝin ricevos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Kaj nun kion mi devas esperi, mia Sinjoro? Mia espero estas al Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'De ĉiuj miaj pekoj liberigu min, Ne lasu min fariĝi mokindaĵo por sensaĝulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Mi mutiĝis, mi ne malfermos mian buŝon, Ĉar Vi tion faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Deturnu de mi Vian frapon; De Via batanta mano mi pereas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Se Vi punas homon pro lia krimo, Tiam lia beleco konsumiĝas kiel de tineoj. Nur vantaĵo estas ĉiu homo. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Aŭskultu mian preĝon, ho Eternulo, kaj atentu mian krion; Al miaj larmoj ne silentu; Ĉar migranto mi estas ĉe Vi, Enmigrinto, kiel ĉiuj miaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Lasu min, ke mi vigliĝu, Antaŭ ol mi foriros kaj ĉesos ekzisti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Al la ĥorestro. Psalmo de David. Mi atende esperis al la Eternulo, Kaj Li kliniĝis al mi kaj aŭskultis mian krion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Kaj Li eltiris min el la pereiga foso, el la ŝlima marĉo, Kaj Li starigis sur roko mian piedon kaj fortikigis miajn paŝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'Kaj Li metis en mian buŝon novan kanton, laŭdon al nia Dio. Multaj tion vidos kaj ektimos, Kaj ili esperos al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Feliĉa estas la homo, kiu metis sian esperon sur la Eternulon Kaj ne turnis sin al la fieruloj kaj al la mensogemuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Multon Vi faris, ho Eternulo, mia Dio! Viaj mirakloj kaj pensoj estas pri ni. Neniu egalas Vin. Mi rakontos kaj parolos, Sed ili estas super ĉiu kalkulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Oferojn kaj donacojn Vi ne deziras; La orelojn Vi malfermis al mi; Bruloferojn kaj pekoferojn Vi ne postulas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Tiam mi diris: Jen mi venas; En la skribrulaĵo estas skribite pri mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Plenumi Vian volon, mia Dio, mi deziras, Kaj Viaj ordonoj estas en mia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Mi predikas justecon en granda kunveno; Jen mi ne fermas mian buŝon, ho Eternulo, Vi tion scias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Vian justecon mi ne kaŝis en mia koro, Pri Via fideleco kaj Via helpo mi parolis; Mi ne kaŝis Vian favorkorecon kaj Vian verecon antaŭ la granda kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Vi, ho Eternulo, ne fermu Vian favorkorecon antaŭ mi, Via boneco kaj Via vereco ĉiam min gardu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Ĉar ĉirkaŭis min suferoj sennombraj, Atingis min miaj kulpoj, ke mi ne povas vidi; Ili estas pli multenombraj, ol la haroj sur mia kapo, kaj mia koro min forlasis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Volu, ho Eternulo, savi min; Ho Eternulo, rapidu helpi min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Hontiĝu kaj konfuziĝu tiuj, kiuj volas pereigi mian animon; Retiriĝu kaj estu mokataj tiuj, kiuj deziras al mi malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Teruritaj estu de sia honto tiuj, Kiuj diras al mi: Ha, ha!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Gaju kaj ĝoju pro Vi ĉiuj Viaj serĉantoj; La amantoj de Via helpo diru ĉiam: Granda estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Kaj mi estas mizera kaj malriĉa; Mia Sinjoro pensu pri mi. Vi estas mia helpo kaj mia savanto; Ho mia Dio, ne malrapidu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Al la ĥorestro. Psalmo de David. Feliĉa estas tiu, kiu atentas senhavulon: En tago de mizero savos lin la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'La Eternulo lin gardos kaj vivigos; Li estos feliĉa sur la tero, Kaj Vi ne transdonos lin al la volo de liaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'La Eternulo fortigos lin sur la lito de malsano; Lian tutan kuŝejon Vi aliigas en la tempo de lia malsano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Mi diris: Ho Eternulo, kompatu min; Sanigu mian animon, ĉar mi pekis antaŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Miaj malamikoj parolas malbonon pri mi, dirante: Kiam li mortos kaj lia nomo pereos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Kaj se iu venas, por vidi min, li parolas malsincere; Lia koro serĉas malbonon; Kaj, elirinte eksteren, li ĝin disparolas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Mallaŭte parolas inter si pri mi ĉiuj miaj malamikoj; Ili pensas malbonon pri mi, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Afero pereiga atakis lin; Kaj ĉar li kuŝiĝis, li jam ne plu leviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'Eĉ mia konfidato, kiun mi fidis, kiu manĝis mian panon, Levis kontraŭ min la piedon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Sed Vi, ho Eternulo, korfavoru min kaj restarigu min, Por ke mi povu repagi al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Per tio mi scios, ke Vi favoras min, Se mia malamiko ne triumfos super mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'Kaj min Vi subtenos pro mia senkulpeco, Kaj Vi starigos min antaŭ Via vizaĝo por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Glorata estu la Eternulo, Dio de Izrael, De eterne ĝis eterne. Amen, kaj amen!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Al la ĥorestro. Instruo de la Koraĥidoj. Kiel cervo sopiras al fluanta akvo, Tiel mia animo sopiras al Vi, ho Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Mia animo soifas Dion, la vivantan Dion; Kiam mi venos kaj aperos antaŭ la vizaĝo de Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Miaj larmoj fariĝis mia pano tage kaj nokte, Ĉar oni diras al mi ĉiutage: Kie estas via Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Elverŝiĝas mia animo, kiam mi rememoras, Kiel mi iradis kun la granda homamaso, kaj kondukis ĝin en la domon de Dio, Ĉe laŭta kantado kaj glorado de festanta amaso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Kial vi malĝojas, ho mia animo? Kaj kial vi konsterniĝas en mi? Esperu al Dio; Ĉar ankoraŭ mi dankos Lin, La savanton de mia vizaĝo kaj mian Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Malĝojas en mi mia animo; Tial mi rememoras pri Vi en la lando de Jordan kaj Ĥermon, Sur la monto Micar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Abismo resonas al abismo per la bruo de Viaj falakvoj; Ĉiuj Viaj akvoj kaj ondoj pasis super mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'En la tago la Eternulo aperigas al mi Sian bonecon, Kaj en la nokto mi havas kanton al Li, Preĝon al la Dio de mia vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Mi diras al Dio, mia Roko: Kial Vi min forgesis? Kial mi iradas malgaja pro la premado de la malamiko?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Kvazaŭ dispremante miajn ostojn, mokas min miaj malamikoj, Dirante al mi ĉiutage: Kie estas via Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Kial vi malĝojas, ho mia animo? Kaj kial vi konsterniĝas en mi? Esperu al Dio; Ĉar ankoraŭ mi dankos Lin, La savanton de mia vizaĝo kaj mian Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Juĝu min, ho Dio, kaj defendu mian aferon kontraŭ popolo nepia; De homo malverema kaj maljusta savu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Ĉar Vi estas la Dio de mia forto; kial Vi forpuŝis min? Kial mi iradas malĝoja pro la premado de la malamiko?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Sendu Vian lumon kaj Vian veron, ke ili min gvidu, Ke ili alvenigu min al Via sankta monto kaj al Via loĝejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'Kaj mi venos al la altaro de Dio, Al la Dio de mia ĝojo kaj ĝuo; Kaj mi gloros Vin per harpo, ho Dio, mia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Kial vi malĝojas, ho mia animo? Kaj kial vi konsterniĝas en mi? Esperu al Dio; Ĉar ankoraŭ mi dankos Lin, La savanton de mia vizaĝo kaj mian Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Al la ĥorestro. Instruo de la Koraĥidoj. Ho Dio, per niaj oreloj ni aŭdis, niaj patroj rakontis al ni, Kion Vi faris en iliaj tagoj, en tempo antikva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Vi per Via mano forpelis popolojn, kaj ilin Vi enloĝigis; Popolojn Vi pereigis, kaj ilin Vi vastigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Ĉar ne per sia glavo ili akiris la teron, Kaj ne ilia brako helpis ilin; Sed nur Via dekstra mano kaj Via brako kaj la lumo de Via vizaĝo, Ĉar Vi ilin favoris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Vi estas mia Reĝo, ho Dio; Disponu helpon al Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Per Vi ni disbatos niajn malamikojn; Per Via nomo ni piedpremos niajn kontraŭbatalantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Ĉar ne mian pafarkon mi fidas, Mia glavo min ne helpos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Sed Vi helpas nin kontraŭ niaj malamikoj, Kaj niajn malamantojn Vi kovras per honto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'Dion ni gloros ĉiutage, Kaj Vian nomon ni dankos eterne. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Tamen Vi nin forlasis kaj hontigis, Kaj Vi ne eliras kun nia militistaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Vi devigas nin forkuri de nia malamiko, Ke niaj malamantoj nin prirabu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Vi fordonas nin por formanĝo, kiel ŝafojn, Kaj inter la popolojn Vi disĵetis nin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Vi vendis Vian popolon por nenio, Kaj prenis por ili nenian prezon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Vi faris nin malestimataĵo por niaj najbaroj, Mokataĵo kaj insultataĵo por niaj ĉirkaŭantoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Vi faris nin instrua ekzemplo por la popoloj, Ke la nacioj balancas pri ni la kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Ĉiutage mia malhonoro estas antaŭ mi, Kaj honto kovras mian vizaĝon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'Pro la voĉo de mokanto kaj insultanto, Antaŭ la vizaĝo de malamiko kaj venĝanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'Ĉio tio trafis nin, sed ni Vin ne forgesis, Kaj ni ne perfidiĝis al Via interligo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Ne retiriĝis nia koro, Kaj niaj paŝoj ne deflankiĝis de Via vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Kiam Vi batis nin sur loko de ŝakaloj Kaj kovris nin per ombro de morto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Tiam se ni forgesus la nomon de nia Dio Kaj ni etendus niajn manojn al fremda dio:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'Ĉu Dio tion ne trovus? Li ja scias la sekretojn de la koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'Pro Vi ni ja estas mortigataj ĉiutage; Oni rigardas nin kiel ŝafojn por buĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Leviĝu, kial Vi dormas, mia Sinjoro? Vekiĝu, ne forpuŝu por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Kial Vi kaŝas Vian vizaĝon, Forgesas nian mizeron kaj nian suferon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Nia animo estas ja ĵetita en la polvon; Nia korpo kliniĝis al la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Leviĝu; helpu kaj savu nin pro Via boneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Al la ĥorestro. Por ŝoŝanoj. Instrua ama kanto de la Koraĥidoj. Mia koro pleniĝis per bona temo; Mi kantos pri reĝo; Mia lango estas kiel plumo de lerta skribisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Vi estas la plej bela el la homidoj; Ĉarmo estas sur viaj lipoj; Tial Dio benis vin por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Zonu vian lumbon per glavo, Vi, forta per via majesteco kaj beleco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'Kaj en via beleco prosperu, forrajdu por la vero, Por justeco al la humiluloj; Kaj via dekstra mano montros miraklojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Viaj sagoj estas akraj; Kaj, faligante antaŭ vi la popolojn, Ili penetros en la koron de la malamikoj de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Via trono estas Dia trono por ĉiam kaj eterne; La sceptro de via regno estas sceptro de justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Vi amas virton kaj malamas malvirton; Tial Dio, via Dio, oleis vin per oleo de ĝojo pli ol viajn kamaradojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'De mirho, aloo, kaj kasio odoras ĉiuj viaj vestoj; En palacoj eburaj ĝojigas vin muziko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Reĝidinoj estas inter viaj karulinoj; Ĉe via dekstra flanko staras edzino en Ofira oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Aŭdu, filino, rigardu, kaj klinu vian orelon, Kaj forgesu vian popolon kaj la domon de via patro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Kaj kiam la reĝo deziros vian belecon, Ĉar li estas via sinjoro, tiam vi kliniĝu antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'Kaj la filino de Tiro venos al vi kun donacoj; Petegos antaŭ vi la riĉuloj de la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'En sia plena ornamo estas interne la reĝidino; El ora teksaĵo estas ŝia vesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'En broditaj vestoj ŝi estas kondukata al la reĝo; Post ŝi estas kondukataj al vi knabinoj, ŝiaj koleginoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'Ili estas kondukataj kun ĝojo kaj kantoj; Ili eniras en la palacon de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Anstataŭ viaj patroj estos viaj filoj; Vi faros ilin princoj sur la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Mi memorigos vian nomon de generacio al generacio; Tial gloros vin popoloj ĉiam kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Al la ĥorestro. De la Koraĥidoj. Por sopranuloj. Kanto. Dio estas por ni rifuĝejo kaj forto, Helpo en mizeroj, rapide trovata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Tial ni ne timas, eĉ se pereus la tero Kaj la montoj falus en la internon de la maroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Bruu, bolu Liaj akvoj, Tremu la montoj de ilia fiera ondado. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Estas rivero, kies torentoj ĝojigas la urbon de Dio, La sanktan loĝejon de la Plejaltulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Dio estas en ĝia mezo, ĝi ne ŝanceliĝos; Dio ĝin helpas en frua mateno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Ekbruis popoloj, ekŝanceliĝis regnoj; Li sonigis Sian voĉon, kaj la tero fandiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'La Eternulo Cebaot estas kun ni; Nia defendo estas la Dio de Jakob. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Iru, rigardu la farojn de la Eternulo, Kiu faris detruojn sur la tero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Kiu ĉesigas militojn ĝis la fino de la tero, Rompas pafarkon, rompas ponardegon, Forbruligas veturilojn per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'Cedu, kaj sciu, ke Mi estas Dio; Mi estas glora inter la popoloj, Mi estas glora sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'La Eternulo Cebaot estas kun ni; Nia defendo estas la Dio de Jakob. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Al la ĥorestro. De la Koraĥidoj. Psalmo. Ĉiuj popoloj, plaŭdu per la manoj, Kriu al Dio per voĉo de kanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Ĉar la Eternulo Plejalta estas timinda; Li estas granda Reĝo super la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Li subigas al ni popolojn Kaj metas gentojn sub niajn piedojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Li elektas por ni nian heredon, La majeston de Jakob, kiun Li amas. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Dio supreniras ĉe sonoj de ĝojo, La Eternulo ĉe trumpetado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Kantu al Dio, kantu! Kantu al nia Reĝo, kantu!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Ĉar Dio estas la Reĝo de la tuta tero: Kantu edifan kanton!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Dio reĝas super la popoloj; Dio sidas sur Sia sankta trono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'La princoj de la popoloj kolektiĝis, La popolo de la Dio de Abraham; Ĉar al Dio apartenas la ŝildoj de la tero; Li estas tre alta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Kanto-psalmo de la Koraĥidoj. Granda estas la Eternulo, Kaj tre glora en la urbo de nia Dio, Sur Lia sankta monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Bela altaĵo, ĝojiga por la tuta tero Estas la monto Cion, en la norda regiono, La urbo de la granda Reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Dio estas konata en ĝiaj palacoj, kiel rifuĝejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Jen kolektiĝis la reĝoj, Sed ĉiuj kune foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Ili vidis kaj ekmiris, Konfuziĝis kaj forkuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'Teruro ilin atakis, Tremo, kiel ĉe akuŝantino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Per orienta vento Vi ruinigis la ŝipojn de Tarŝiŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Kion ni aŭdis, tion ni vidis En la urbo de la Eternulo Cebaot, en la urbo de nia Dio; Dio fortikigu ĝin por ĉiam! Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Ni meditis, ho Dio, pri Via boneco, Interne de Via templo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Kiel Via nomo, ho Dio, Tiel Via gloro estas en la finoj de la tero; Plena de justeco estas Via dekstra mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Ĝoju la monto Cion, Ĝoju la filinoj de Jehuda, Pro Via juĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Iru ĉirkaŭ Cion kaj ĉirkaŭrigardu ĝin, Kalkulu ĝiajn turojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Atentu ĝiajn fortikaĵojn, Vizitu ĝiajn palacojn, Por ke vi rakontu al estonta generacio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Ĉar jen estas Dio, nia Dio, por ĉiam kaj eterne; Li estos nia kondukanto ĝis la morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Al la ĥorestro. De la Koraĥidoj. Psalmo. Aŭskultu ĉi tion, ĉiuj popoloj; Atentu, ĉiuj loĝantoj de la mondo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'Kaj altrangulo kaj malaltrangulo, Riĉulo kaj malriĉulo kune.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Mia buŝo diros saĝaĵon, Kaj la penso de mia koro prudentaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Mi klinos mian orelon al sentenco; Sur harpo mi esprimos mian enigmon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Kial mi devus timi en tagoj de malbono, Kiam min ĉirkaŭas la malboneco de miaj persekutantoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Kiuj fidas sian potencon Kaj fanfaronas per sia granda riĉeco?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'Fraton tute ne liberigos homo, Nek donos al Dio elaĉeton por li');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, '(Multekosta estus la elaĉeto de ilia animo, Kaj neniam tio estos),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'Ke li restu viva eterne, Ke li ne vidu la tombon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'Oni ja vidas, ke saĝuloj mortas, Kaj ankaŭ malsaĝulo kaj sensciulo pereas Kaj lasas al aliaj sian havon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Ilia deziro estas, ke iliaj domoj ekzistu por ĉiam, Kaj iliaj loĝejoj de generacio al generacio; Ili nomas siajn bienojn laŭ siaj nomoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Sed homo ne restas longe en honoro; Li egaliĝas al bruto buĉota.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Tia estas ilia vojo, ilia espero, Kaj iliaj posteuloj aprobas ilian opinion. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Kiel ŝafoj ili estos metataj en Ŝeolon; La morto ilin paŝtos; Kaj matene virtuloj ilin ekposedos, Kaj ilia bildo pereos en Ŝeol, perdinte loĝejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Sed Dio liberigos mian animon el la mano de Ŝeol, Ĉar Li prenos min. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Ne timu, kiam homo riĉiĝas, Kiam grandiĝas la gloro de lia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Ĉar mortante li nenion prenos; Ne iros post li malsupren lia honoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Ĉar kvankam li ĝuigas sian animon dum sia vivado, Kaj oni vin laŭdas por tio, ke vi faras al vi bone,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'Tamen li iros al la generacio de siaj patroj, Kiuj neniam vidos lumon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'Homo, kiu estas en honoro, sed ne havas prudenton, Estas egala al bruto buĉota.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Psalmo de Asaf. Dio de la dioj, la Eternulo, ekparolis, Kaj vokis la teron de la sunleviĝo ĝis la sunsubiro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'El Cion, la perfektaĵo de beleco, Dio ekbrilis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Nia Dio venas kaj ne silentas; Fajro ekstermanta estas antaŭ Li, Ĉirkaŭ Li estas granda ventego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Li vokas la ĉielon supre kaj la teron, Por juĝi Sian popolon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, 'Kolektu al Mi Miajn fidelulojn, Kiuj faris kun Mi interligon ĉe oferdono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Kaj la ĉielo proklamis Lian justecon, Ĉar Dio estas tiu juĝanto. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, 'Aŭskultu, ho Mia popolo, kaj Mi parolos; Ho Izrael, Mi atestos pri vi; Mi estas Dio, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Ne pro viaj oferdonoj Mi vin riproĉos, Ĉar viaj bruloferoj estas ĉiam antaŭ Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Mi ne prenos el via domo bovidon, Nek el viaj kortoj kaprojn:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Ĉar al Mi apartenas ĉiuj bestoj en la arbaroj, Miloj da brutoj sur la montoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Mi konas ĉiujn birdojn sur la montoj, Kaj ĉiuj bestoj de la kampoj estas antaŭ Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Se Mi fariĝus malsata, Mi ne dirus al vi, Ĉar al Mi apartenas la mondo, kaj ĉio, kio ĝin plenigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Ĉu Mi manĝas viandon de bovoj, Kaj ĉu Mi trinkas sangon de kaproj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Oferdonu al Dio dankon, Kaj plenumu antaŭ la Plejaltulo viajn promesojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'Voku Min en la tago de mizero; Mi vin liberigos, kaj vi Min gloros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Sed al la malpiulo Dio diris: Por kio vi parolas pri Miaj leĝoj Kaj portas Mian interligon en via buŝo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'Dum vi malamas moralinstruon Kaj ĵetas Miajn vortojn malantaŭen de vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Kiam vi vidas ŝteliston, vi aliĝas al li, Kaj kun adultuloj vi estas partoprenanto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Vian buŝon vi uzas por malbono, Kaj via lango plektas falsaĵon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Vi sidas kaj parolas kontraŭ via frato, Pri la filo de via patrino vi kalumnias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Tion vi faris, kaj Mi silentis; Kaj vi pensis, ke Mi estas tia, kiel vi. Mi punos vin, kaj Mi metos ĉion antaŭ viajn okulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Komprenu ĉi tion, vi, kiuj forgesas Dion; Alie Mi disŝiros, kaj neniu savos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Kiu oferdonas dankon, tiu Min honoras; Kaj kiu estas singarda en la vojo, Al tiu Mi aperigos Dian helpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Al la ĥorestro. Psalmo de David, kiam venis al li la profeto Natan post lia aliĝo al Bat-Ŝeba. Korfavoru min, ho Dio, laŭ Via boneco; Laŭ Via granda kompatemeco elstreku miajn pekojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Lavu min tute pure de mia krimo, Kaj purigu min de mia peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Ĉar miajn kulpojn mi konsciadas; Kaj mia peko estas ĉiam antaŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Antaŭ Vi sola mi pekis, Kaj mi faris tion, kio estas malbona antaŭ Viaj okuloj; Tial Vi estas justa en Via vorto Kaj pura en Via juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Mi estas ja naskita en krimo; Kaj en peko gravediĝis per mi mia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Vi amas ja veron en la koro, Kaj en kaŝiteco Vi aperigas al mi saĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Senpekigu min per hisopo, kaj mi fariĝos pura; Lavu min, kaj mi estos pli blanka ol neĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Aŭdigu al mi ĝojon kaj gajecon, Kaj regajiĝos la ostoj, kiujn Vi batis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Kaŝu Vian vizaĝon de miaj pekoj, Kaj ĉiujn miajn krimojn elstreku.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Koron puran kreu al mi, ho Dio, Kaj spiriton fidelan novigu en mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Ne forpuŝu min de Via vizaĝo, Kaj Vian sanktan spiriton ne forprenu de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Redonu al mi la ĝojon de Via helpo; Kaj spirito bonfara fortikigu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Mi instruos al la krimuloj Vian vojon; Kaj pekuloj revenos al Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Liberigu min de sango, ho Dio, Dio de mia savo; Mia lango kantos Vian justecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Ho, mia Sinjoro, malfermu miajn lipojn; Kaj mia buŝo rakontos Vian gloron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Ĉar Vi ne deziras oferdonon, alie mi ĝin donus; Brulofero ne plaĉas al Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Oferdonoj al Dio estas spirito suferanta; Koron suferantan kaj humilan Vi, ho Dio, ne malŝatas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Bonfaru al Cion laŭ Via favoro, Konstruu la murojn de Jerusalem;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Tiam plaĉos al Vi oferdonoj de pieco, brulofero kaj plenofero; Tiam oni metos sur Vian altaron junajn bovojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Al la ĥorestro. Instruo de David, kiam venis Doeg, la Edomido, kaj raportis al Saul, kaj diris al li: David venis en la domon de Aĥimeleĥ. Kial vi fanfaronas pro malbono, ho tirano? La boneco de Dio estas ĉiama.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'Pereon intencas via lango, Kiel akrigita razilo ĝi tranĉas malicon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Vi pli amas malbonon, ol bonon; Pli mensogi, ol diri veron. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Vi amas ĉian parolon pereigan, Parolon malican.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Tial Dio pereigos vin por ĉiam, Elŝiros vin el via tendo, Kaj elĵetos vin el la lando de la vivantoj. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Kaj virtuloj vidos kaj ektimos, Kaj pri li ili ridos, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'Jen estas la viro, kiu ne en Dio vidis sian forton, Sed fidis sian grandan riĉecon, Sentis sin forta per sia malbonpovado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Kaj mi, kiel verda olivarbo en la domo de Dio, Fidas la bonecon de Dio ĉiam kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Mi dankos Vin eterne por tio, kion Vi faris, Kaj mi esperos al Via nomo, ĉar Vi estas bona por Viaj fideluloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Al la ĥorestro. Por maĥalato. Instruo de David. La sensaĝulo diris en sia koro: Dio ne ekzistas. Ili sentaŭgiĝis, kaj abomeniĝis en la malvirto; Ekzistas neniu, kiu faras bonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Dio el la ĉielo ekrigardis la homidojn, Por vidi, ĉu ekzistas prudentulo, kiu serĉas Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Ĉiu devojiĝis, ĉiuj malvirtiĝis; Ekzistas neniu, faranta bonon, ne ekzistas eĉ unu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Ĉu ne prudentiĝos tiuj, kiuj faras malbonon, Kiuj manĝas mian popolon, kiel oni manĝas panon, Kaj kiuj ne vokas al Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Tie ili forte ektimis, kie timindaĵo ne ekzistis; Ĉar Dio disĵetis la ostojn de tiuj, kiuj vin sieĝas; Vi hontigis ilin, ĉar Dio ilin forpuŝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Ho, ke venu el Cion savo al Izrael! Kiam Dio revenigos Sian forkaptitan popolon, Tiam triumfos Jakob kaj ĝojos Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Al la ĥorestro. Por kordaj instrumentoj. Instruo de David, kiam venis la Zifanoj, kaj diris al Saul: Jen David kaŝiĝas ĉe ni. Ho Dio, per Via nomo helpu min, Kaj per Via forto donu al mi justecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'Ho Dio, aŭskultu mian preĝon, Atentu la vortojn de mia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Ĉar fremduloj leviĝis kontraŭ mi, Kaj fortuloj serĉas mian animon; Ili ne havas Dion antaŭ si. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Jen Dio estas mia helpanto, Mia Sinjoro estas subtenanto de mia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Li returnos la malbonon al miaj malamikoj: Laŭ Via vereco ekstermu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Kun volonteco mi faros al Vi oferdonon, Mi gloros Vian nomon, ho Eternulo, ĉar ĝi estas bona;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Ĉar de ĉiuj suferoj Li savis min, Kaj venĝon sur miaj malamikoj vidas mia okulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Al la ĥorestro. Por kordaj instrumentoj. Instruo de David. Aŭskultu, ho Dio, mian preĝon, Kaj ne kaŝu Vin de mia petego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Atentu min, kaj respondu al mi; Mi ĝemas en mia malĝojo, kaj mi ploregas,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'Pro la kriado de la malamiko, Pro la premado de la malbonulo, Ĉar ili preparas kontraŭ mi malicon Kaj kolere min malamas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'Mia koro tremas en mi; Kaj teruroj de morto min atakis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Timo kaj tremo venis sur min, Kaj konsternego min kovris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'Kaj mi diris: Ho, se mi havus flugilojn kiel kolombo! Mi forflugus kaj mi ie ekloĝus;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Malproksimen mi foriĝus, Mi ekloĝus en dezerto. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Mi rapidus al rifuĝejo For de ventego kaj fulmotondro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Pereigu, ho mia Sinjoro, disigu ilian langon; Ĉar mi vidas rabadon kaj malpacon en la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Tage kaj nokte ili ĉirkaŭas ĝiajn murojn; Kaj malbonfaroj estas interne de ĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Pereigemo estas interne de ĝi, Kaj trompo kaj falso ne forlasas ĝian straton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Ne malamiko min ja insultas-mi tion tolerus; Ne mia malamanto tenas sin grande kontraŭ mi-mi kaŝus min de li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Sed vi, kiu estas tia sama homo, kiel mi, Mia amiko, mia kamarado,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'Vi, kun kiu ni kune intime paroladis, Iradis en la domon de Dio en la homamaso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'La morto ilin kaptu, Ili iru vivaj en Ŝeolon; Ĉar malbonagado estas en iliaj loĝejoj, en ilia mezo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Mi vokas al Dio, Kaj la Eternulo min savos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Vespere kaj matene kaj tagmeze mi plendas kaj ĝemas; Kaj Li aŭskultas mian voĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Li liberigis pace mian animon de atako kontraŭ mi, Kiam ili grandanombre estis kontraŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Dio aŭskultos, kaj Li humiligos ilin, La vivanto de eterne; Sela. Ĉar ili ne ŝanĝiĝas Kaj ili ne timas Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Li metis sian manon sur siajn amikojn, Li rompis sian interligon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Pli glata ol butero estas lia buŝo, Sed milito estas en lia koro; Liaj vortoj estas pli delikataj ol oleo, Sed ili estas nudigitaj glavoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Metu vian ŝarĝon sur la Eternulon, Kaj Li vin subtenos; Neniam Li lasos fali piulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Vi, ho Dio, malsuprenigos ilin en la foson de pereo; La homoj de sango kaj falso ne atingos la duonon de siaj tagoj; Sed mi fidas Vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Al la ĥorestro. Por Jonatelem-reĥokim. Verko de David, kiam kaptis lin la Filiŝtoj en Gat. Korfavoru min, ho Dio, ĉar homo volas min engluti, Dum la tuta tago malamiko min premas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Miaj malamikoj volas min engluti ĉiutage, Ĉar multaj militas kontraŭ mi fiere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'En la tago, kiam mi timas, Mi fidas Vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'Dion, kies vorton mi gloras, Tiun Dion mi fidas; mi ne timas: Kion karno faros al mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Dum la tuta tago ili atakas miajn vortojn; Ĉiuj iliaj pensoj pri mi estas por malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Ili kolektiĝas, embuskas, observas miajn paŝojn, Penante kapti mian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'Por ilia malbonago repagu al ili, En kolero faligu la popolojn, ho Dio!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Mian vagadon Vi kalkulis; Metu miajn larmojn en Vian felsakon, Ili estas ja en Via libro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Tiam miaj malamikoj returniĝos malantaŭen en la tago, kiam mi vokos; Tion mi scias, ke Dio estas kun mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Mi gloros vorton de Dio; Mi gloros vorton de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'Dion mi fidas, mi ne timas: Kion faros al mi homo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Mi faris al Vi, ho Dio, promesojn, Mi plenumos al Vi dankoferojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Ĉar Vi savis mian animon de la morto, Kaj miajn piedojn de falpuŝiĝo, Por ke mi iradu antaŭ Dio En la lumo de la vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Al la ĥorestro. Por Al-taŝĥet. Verko de David, kiam li forkuris de Saul en la kavernon. Korfavoru min, ho Dio, korfavoru min; Ĉar ĉe Vi rifuĝas mia animo, Kaj sub la ombro de Viaj flugiloj mi min kaŝas, Ĝis pasos la mizeroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Mi vokas al Dio Plejalta, Al Dio, kiu decidas pri mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Li sendu el la ĉielo kaj helpu min, Li, kiu hontigas miajn persekutanton; Sela. Dio sendu Sian favoron kaj Sian veron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Mia animo estas inter leonoj; Mi kuŝas inter homidoj avidaj, kies dentoj estas ponardegoj kaj sagoj, Kaj kies lango estas akra glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Altiĝu super la ĉielo, ho Dio; Via gloro estu super la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Reton ili metis antaŭ miaj piedoj; Ili premis mian animon; Ili fosis antaŭ mi foson, Sed ili mem falis en ĝin. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Fortika estas mia koro, ho Dio, fortika estas mia koro; Mi kantos kaj gloros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Vekiĝu, mia honoro, vekiĝu, psaltero kaj harpo; Mi vekos la matenan ĉielruĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Mi gloros Vin, ho mia Sinjoro, inter la popoloj; Mi prikantos Vin inter la gentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Ĉar granda ĝis la ĉielo estas Via boneco, Kaj ĝis la nuboj estas Via vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Altiĝu super la ĉielo, ho Dio; Via gloro estu super la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Al la ĥorestro. Por Al-taŝĥet. Verko de David. Ĉu efektive vi parolas veron, vi potenculoj? Ĉu vi juste juĝas, homidoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Kontraŭe, en la koro vi faras krimaĵojn, Sur la tero vi pesas per manoj rabemaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'De la momento de sia naskiĝo la malvirtuloj devojiĝis; De el la ventro de sia patrino la mensogantoj ekeraris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Ilia veneno estas simila al la veneno de serpento, De surda aspido, kiu ŝtopas sian orelon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'Kiu ne aŭskultas la vortojn de sorĉistoj, Kiel ajn lertaj en sia arto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'Ho Dio, frakasu iliajn dentojn en ilia buŝo; Frakasu la makzelojn de la junaj leonoj, ho Eternulo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Ili forverŝiĝu kiel akvo, kiu malaperas; Kiam Li ĵetos Siajn sagojn, ili estu kiel buĉitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Kiel limako konsumiĝanta ili malaperu, Kiel abortaĵo virina, kiu ne vidis la sunon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Antaŭ ol viaj kaldronoj eksentos la dornojn, Ilin vivajn kaj freŝajn pereigu la ventego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Ĝojos la virtulo, kiam li vidos venĝon; Li lavos siajn piedojn en la sango de la malvirtulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'Kaj la homoj diros: Ekzistas rekompenco por la virtulo, Ekzistas Dio, juĝanto sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Al la ĥorestro. Por Al-aŝĥet. Verko de David, kiam Saul sendis, ke oni gardu la domon, por lin mortigi. Savu min de miaj malamikoj, mia Dio; Defendu min kontraŭ tiuj, kiuj leviĝis kontraŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Savu min de la krimuloj, Kaj kontraŭ la sangaviduloj helpu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Ĉar jen ili embuskas kontraŭ mia animo, Fortuloj kolektiĝas kontraŭ mi, Ne por mia krimo kaj ne por mia peko, ho Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Sen kulpo de mia flanko ili kunkuras kaj armiĝas; Rapidu renkonte al mi, kaj rigardu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Vi, ho Eternulo, Dio Cebaot, Dio de Izrael, Vekiĝu, por punviziti ĉiujn popolojn; Ne indulgu ĉiujn krimajn malbonfarantojn. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Ili revenas vespere, bojas kiel hundoj, Kaj iras ĉirkaŭ la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Jen ili parolaĉas per siaj buŝoj; Glavoj estas sur iliaj lipoj; ĉar kiu, ili diras, aŭdas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Sed Vi, ho Eternulo, ridos pri ili; Vi mokos ĉiujn popolojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Ho mia forto, al Vi mi min turnas; Ĉar Dio estas mia rifuĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Mia bona Dio rapidos al mi; Dio vidigos al mi venĝon sur miaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Ne mortigu ilin, por ke ne forgesu mia popolo; Disbatu ilin per Via forto kaj faligu ilin, Ho Sinjoro, nia ŝildo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'La parolo de iliaj lipoj estas peko de iliaj buŝoj; Ili kaptiĝu per sia malhumileco, Ĉar ili parolas nur pri ĵurrompo kaj mensogo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Ekstermu ilin en kolerego, ekstermu, ke ili ne plu ekzistu; Kaj ili eksciu, ke Dio regas ĉe Jakob, Ĝis la limoj de la mondo. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Ili revenas vespere, bojas kiel hundoj, Kaj iras ĉirkaŭ la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Ili vagas pro manĝo, Kaj sen satiĝo pasigas la nokton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Sed mi kantos Vian forton, Kaj matene mi gloros Vian bonecon; Ĉar Vi estis por mi defendo kaj rifuĝo En la tago de mia malfeliĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'Ho mia forto, al Vi mi kantos; Ĉar Dio estas mia defendo, la Dio de mia favoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Al la ĥorestro. Por ŝuŝan-eduto. Instrua verko de David, kiam li militis kun Sirio Mezopotamia kaj kun Sirio Coba, kaj kiam Joab, revenante, batis dek du mil Edomidojn en la Valo de Salo. Ho Dio, Vi forlasis nin, Vi disbatis nin; Vi koleris; rekonsolu nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'Vi ekskuis la teron kaj fendis ĝin; Resanigu ĝiajn vundojn, ĉar ĝi ŝanceliĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Vi sentigis al Via popolo pezan sorton; Vi trinkigis al ni vinon senkonsciigan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Sed Vi donis standardon al tiuj, kiuj Vin timas, Por ke ili ĝin levu pro la vero. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Por ke liberiĝu Viaj amatoj, Helpu per Via dekstra mano, kaj aŭskultu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Dio diris en Sia sanktejo: Mi triumfos; Mi dividos Ŝeĥemon, kaj la valon Sukot Mi mezuros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Al Mi apartenas Gilead, al Mi apartenas Manase; Efraim estas la forto de Mia kapo, Jehuda estas Mia sceptro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Moab estas Mia lavopelvo; Sur Edomon Mi ĵetos Mian ŝuon; Super Filiŝtujo Mi triumfe krios.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Kiu enkondukos min en fortikigitan urbon? Kiu alkondukos min ĝis Edom?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Ĉu ne Vi, ho Dio, forlasis nin? Vi ne eliras, ho Dio, kun niaj militistaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Donu al ni helpon kontraŭ la malamiko; Vanta estas helpo de homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Kun Dio ni faros heroaĵojn; Kaj Li dispremos niajn malamikojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Al la ĥorestro. Por korda instrumento. De David. Aŭskultu, ho Dio, mian krion; Atentu mian preĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'De la fino de la tero mi vokas al Vi en la malĝojo de mia koro: Sur rokon tro altan por mi suprenkonduku min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Ĉar Vi estis mia rifuĝejo, Fortika turo kontraŭ malamiko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Lasu min loĝi eterne en Via tendo, Havi rifuĝon sub la kovro de Viaj flugiloj. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Ĉar Vi, ho Dio, aŭdis miajn promesojn; Vi donis al mi la heredon de tiuj, kiuj timas Vian nomon. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Aldonu tagojn al la tagoj de la reĝo, Ke liaj jaroj daŭru multajn generaciojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Li restu eterne antaŭ Dio; Boneco kaj vero laŭ Via volo lin gardu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Tiel mi prikantos Vian nomon eterne, Plenumante miajn promesojn ĉiutage.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Al la ĥorestro. Por Jedutun. Psalmo de David. Nur al Dio esperas mia animo; De Li venas mia savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Nur Li estas mia fortikaĵo kaj mia savo, mia rifuĝejo; Mi ne tute renversiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Ĝis kiam vi insidos kontraŭ viro kaj ĉiuj vi penos faligi lin, Kiel kliniĝintan muron, kiel barilon kadukan?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Ili meditas nur pri tio, ke ili deĵetu lin de lia altaĵo; Plaĉas al ili malvero; Per la buŝo ili benas, kaj interne ili malbenas. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Nur Dion fidu, mia animo; Ĉar Li estas mia espero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Nur Li estas mia fortikaĵo kaj mia savo, mia rifuĝejo; Mi ne renversiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'En Dio estas mia savo kaj mia honoro; Mia forta roko, mia ŝirmo estas en Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Fidu Lin en ĉiu tempo, ho popolo; Elverŝu antaŭ Li vian koron: Dio estas nia defendo. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Nur vantaĵo estas la malaltranguloj, malveraĵo estas la altranguloj; Metitaj sur pesilon, ili ĉiuj estas malpli ol vantaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Ne fidu perfortaĵon, kaj rabitaĵon ne fidu vane; Kiam kreskos riĉeco, ne atentu ĝin per via koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Unu vorton diris Dio, Dufoje mi ĝin aŭdis, Ke la forto estas ĉe Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Kaj Vi, ho mia Sinjoro, havas favorkorecon; Ĉar Vi redonas al homo laŭ liaj faroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Psalmo de David, kiam li estis en la dezerto de Judujo. Ho Dio, mia Dio, Vin mi fervore serĉas; Soifas pri Vi mia animo, sopiras pri Vi mia karno, En lando seka, sensuka, kaj senakva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Mi volus vidi Vin en Via sanktejo, Vidi Vian forton kaj gloron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Ĉar Via favoro estas pli bona ol vivo; Miaj lipoj Vin gloras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Tiel mi Vin gloradus en la daŭro de mia vivo, Levadus miajn manojn pro Via nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Kvazaŭ de graso kaj oleo satiĝus mia animo, Kaj per vortoj de kanto Vin gloradus mia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Kiam mi rememoras Vin sur mia lito, En ĉiuj partoj de la nokto mi meditas pri Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Ĉar Vi estis por mi helpo, Kaj en la ombro de Viaj flugiloj mi ĝojas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Mia animo algluiĝis al Vi; Min subtenas Via dekstra mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Kaj tiuj, kiuj penas pereigi mian animon, Iros en la profundon subteran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Ili estos mortigitaj per glavo, Fariĝos akiro de vulpoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Kaj la reĝo ĝojos per Dio; Triumfos ĉiu, kiu ĵuras al Li; Ĉar ŝtopiĝos la buŝo de tiuj, kiuj parolas malveron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Al la ĥorestro. Psalmo de David. Aŭdu, ho Dio, mian krion en mia malĝojo; De la teruro pri malamiko gardu mian vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Ŝirmu min kontraŭ la konspiro de maliculoj, Kontraŭ la amaso de krimuloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Kiuj akrigis sian langon kiel glavon, Direktis vortojn maldolĉajn, kvazaŭ siajn sagojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'Por pafi kaŝe kontraŭ senkulpulon; Subite ili pafas kontraŭ lin kaj ne timas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'Ili fortikigas sin en malbona intenco, Ili konsiliĝas, por meti sekrete retojn; Ili diras: Kiu ilin vidos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Ili elpensas krimojn, kaŝas ilin tre zorge interne en si, En la profundeco de la koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Sed Dio pafos kontraŭ ilin; Per sago subita ili estos frapitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Kaj ili falos per sia propra lango; Ĉiuj, kiuj ilin vidos, balancos la kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'Kaj ektimos ĉiuj homoj, Kaj ili rakontos la agon de Dio Kaj komprenos Liajn farojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'La virtulo ĝojos per la Eternulo, kaj fidos Lin; Kaj triumfos ĉiuj, kiuj havas pian koron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Al la ĥorestro. Psalmo de David. Kanto. Vin oni fidas kaj gloras, ho Dio, en Cion; Kaj al Vi oni plenumas promesojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Al Vi, kiu aŭskultas preĝon, Venas ĉiu karno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Krimaĵoj min premas; Niajn pekojn Vi pardonos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Feliĉa estas tiu, kiun Vi elektas kaj alproksimigas al Vi, Ke li loĝu en Viaj kortoj. Ni satiĝu per la bonaĵoj de Via domo, De Via sankta templo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Per timindaĵoj Vi respondas al ni en justeco, Ho Dio de nia savo, Espero de ĉiuj finoj de la tero kaj de malproksimaj maroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Vi, kiu fortigas montojn per Sia forto, Kiu estas zonita per potenco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'Kiu kvietigas la bruadon de maroj, la bruadon de iliaj ondoj, Kaj la tumulton de popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'Kaj ektimos pro Viaj mirakloj la loĝantoj de la limoj; La lokojn de la sunleviĝo kaj sunsubiro Vi ĝojigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Vi memoras pri la tero, Kaj Vi donas al ĝi akvon, kaj Vi forte ĝin riĉigas; La torento de Dio estas plena de akvo; Vi pretigas ĝian panon, ĉar tiel Vi ĝin aranĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Vi donas trinkon al ĝiaj sulkoj, Vi ebenigas ĝiajn bulojn; Per pluvego Vi ĝin moligas, Vi benas ĝiajn kreskaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Vi kronas la jaron per Via bono; Kaj la signoj de Viaj piedoj gutas per graso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'La stepoj de dezerto grasiĝas, Kaj la montetoj zoniĝas per ĝojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'La herbejoj kovriĝas per brutaroj, Kaj la kampoj vestiĝas per greno; Ili ĝojas kaj kantas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Al la ĥorestro. Kanto-psalmo. Ĝoje kriu al Dio tuta la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Muziku la gloron de Lia nomo, Faru honoron al Lia gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Diru al Dio: Kiel timindaj estas Viaj faroj! Pro Via granda forto kaŝiĝas antaŭ Vi Viaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'La tuta tero kliniĝas antaŭ Vi kaj kantas al Vi, Kantas Vian nomon. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Venu, kaj rigardu la farojn de Dio, Kiu estas timinda pro Siaj faroj inter la homidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Li faris el maro sekan teron; Riveron oni transpaŝis piede; Tie ni ĝojis pro Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Li regas per Sia potenco eterne; Liaj okuloj rigardas la popolojn; La ribelantoj ne leviĝu. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Laŭdu, ho popoloj, nian Dion, Kaj laŭte aŭdigu Lian gloron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'Li donis vivon al nia animo, Kaj ne lasis falŝanceliĝi nian piedon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Ĉar Vi esploris nin, ho Dio; Vi refandis nin, kiel oni refandas arĝenton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Vi enirigis nin en kaptilon, Vi metis ŝarĝon sur niajn lumbojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Vi rajdigis homojn sur niaj kapoj; Ni trapasis fajron kaj akvon, Sed Vi elirigis nin en bonstaton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Mi eniros en Vian domon kun bruloferoj; Mi plenumos al Vi miajn promesojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'Kiujn eligis miaj lipoj kaj elparolis mia buŝo, Kiam mi estis en premo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Grasajn bruloferojn mi alportos al Vi kun fumo de virŝafoj; Mi oferos bovidojn kaj kaprojn. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Venu, aŭskultu, ĉiuj, kiuj timas Dion; Kaj mi rakontos, kion Li faris por mia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Al Li mi vokis per mia buŝo, Kaj Lia glorado estis sub mia lango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Se mi vidus maljustaĵon en mia koro, Mia Sinjoro min ne aŭskultus;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Sed Dio aŭskultis, Li atentis la voĉon de mia preĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Glorata estu Dio, Kiu ne forpuŝis mian preĝon kaj ne rifuzis al mi Sian bonecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Al la ĥorestro. Por kordaj instrumentoj. Psalmo-kanto. Dio nin korfavoru kaj benu; Li aperigu al ni Sian luman vizaĝon. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Oni ekkonu sur la tero Vian vojon, En ĉiuj popoloj Vian savon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'Danku Vin popoloj, ho Dio, Danku Vin ĉiuj popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Ĝoju kaj kantu gentoj, Ĉar Vi juĝas popolojn juste, Kaj gentojn sur la tero Vi regas. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Danku Vin popoloj, ho Dio, Danku Vin ĉiuj popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'La tero donis sian frukton; Benos nin Dio, nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Benos nin Dio; Kaj respektu Lin ĉiuj limoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Al la ĥorestro. De David. Psalmo-kanto. Leviĝu Dio, disĵetiĝu Liaj malamikoj, Kaj forkuru Liaj malamantoj for de Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Kiel dispeliĝas fumo, tiel Vi ilin dispelu; Kiel vakso fandiĝas de fajro, tiel pereu la malvirtuloj antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Sed la virtuloj ĝojos, gajos antaŭ Dio, Kaj triumfos ĝojege.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Kantu al Dio, muziku al Lia nomo, Gloru la veturantan sur la nuboj; Lia nomo estas JAH; ĝoju antaŭ Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Patro de la orfoj kaj juĝanto de la vidvinoj Estas Dio en Sia sankta loĝejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Dio donas domon al soluloj, Elirigas malliberulojn en liberecon; Nur la ribeluloj restas en dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Ho Dio, kiam Vi iris antaŭ Via popolo, Kiam Vi paŝis en la dezerto, Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'La tero tremis kaj la ĉielo fandiĝis de la vizaĝo de Dio, Tiu Sinaj tremis de la vizaĝo de Dio, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'Bonfaran pluvon Vi verŝis, ho Dio, sur Vian heredon, Kaj kiam ĝi perdis la fortojn, Vi ĝin vigligis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Via gento ekloĝis tie; Vi pretigis per Via boneco ĉion por la malriĉulo, ho Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Mia Sinjoro elparolas vorton; Kaj grandega estas la nombro de la anoncantinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Reĝoj de armeoj forkuras, forkuras; Kaj la hejmesidantino dividas akiron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Kiam vi kuŝas inter brutejoj, La flugiloj de kolombo estas kovritaj de arĝento, Kaj ĝiaj plumoj de brilanta oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Kiam la Plejpotenculo dismetis reĝojn sur la tero, Ĝi brilis kiel neĝo sur Calmon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Monto de Dio estas la monto Baŝana, Monto multepinta estas la monto Baŝana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Kial vi, montoj multepintaj, envie rigardas la monton, Kiun Dio elektis, por sidi sur ĝi, Kaj sur kiu la Eternulo loĝos eterne?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Da veturiloj de Dio ekzistas multaj miloj da miloj; Inter ili estas mia Sinjoro sur la sankta Sinaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Vi supreniris alten, alkondukis kaptitojn, Prenis donacojn de homoj, Kaj eĉ ribeluloj povas loĝi ĉe la Eternulo, la Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Glorata estu mia Sinjoro, ĉiutage Li zorgas pri ni; Dio estas nia savo. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Dio estas por ni Dio de savo, Kaj la Eternulo, mia Sinjoro, savas de la morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Jes, Dio frakasas la kapon de Siaj malamikoj, La multeharan kranion de tiuj, kiuj obstinas en siaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Mia Sinjoro diris: El Baŝan Mi alkondukos, Mi alkondukos el la profundeco de la maro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'Por ke vi trempu vian piedon en sango, Kaj la lango de viaj hundoj ĝuu de viaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'Oni vidis Vian iron, ho Dio, La iron de mia Dio, mia Reĝo, en la sanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Antaŭe iris kantistoj, poste kordinstrumentistoj, En la mezo de knabinoj tamburinistinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'En la kunvenoj gloru Dion, mian Sinjoron, Vi, devenantoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Tie estas Benjamen, la plej juna, ilia reganto; La princoj de Jehuda kaj iliaj amasoj; La princoj de Zebulun kaj de Naftali.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Via Dio destinis vian forton. Fortikigu, ho Dio, tion, kion Vi faris por ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Pro Via templo en Jerusalem Sela. La reĝoj alportos al Vi donacojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'Kvietigu la beston en la kanoj, La aron da bovoj kun la bovidoj, Popoloj, kiuj humiliĝas pro pecoj da arĝento. Li dispelas la popolojn, kiuj deziras batalojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Venos eminentuloj el Egiptujo; Etiopujo rapidos, por etendi siajn manojn al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Regnoj de la tero, kantu al Dio, Muziku al mia Sinjoro, Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'Kiu regas en la ĉielo de la eternaj ĉieloj. Jen Li tondras per Sia voĉo, forta voĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'Gloru la forton de Dio! Super Izrael estas Lia majesto, Kaj Lia potenco estas en la nuboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Timinda Vi estas, ho Dio, en Via sanktejo. Li estas la Dio de Izrael, Li donas forton kaj potencon al la popolo. Glorata estu Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Al la ĥorestro. Por ŝoŝanoj. De David. Savu min, ho Dio; Ĉar la akvoj venis ĝis mia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Mi profundiĝis en profundan marĉon, kaj mi ne havas, sur kio stari; Mi enfalis en la profundon de la akvo, kaj la fluo min forportas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Mi senfortiĝis de mia kriado, sekiĝis mia gorĝo; Laciĝis miaj okuloj de la atendado de mia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Pli multaj ol la haroj de mia kapo estas miaj senkaŭzaj malamantoj; Fortiĝis miaj premantoj, miaj maljustaj malamikoj; Kion mi ne rabis, tion mi devas fordoni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Ho Dio, Vi scias mian malsaĝecon; Kaj miaj kulpoj ne estas kaŝitaj por Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Ne hontiĝu per mi tiuj, kiuj esperas al Vi, ho mia Sinjoro, Eternulo Cebaot! Ne hontiĝu per mi tiuj, kiuj Vin serĉas, ho Dio de Izrael!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Ĉar pro Vi mi portas malhonoron, Honto kovras mian vizaĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Mi fariĝis fremda por miaj fratoj, Nekonato por la filoj de mia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Ĉar fervoro pri Via domo min konsumis, Kaj la insultoj de Viaj insultantoj falis sur min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Kaj mi ploras, mia animo estas en fasto, Kaj pri tio oni min hontigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Kiel veston mi metis sur min sakon, Kaj mi fariĝis moka ekzemplo por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Parolas pri mi la sidantoj ĉe la pordego, Kaj la drinkantoj kantas pri mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Kaj mi preĝas al Vi, ho Eternulo, en favora tempo; Ho Dio, pro Via granda boneco respondu al mi per Via vera helpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Eligu min el la ŝlimo, ke mi ne dronu; Mi estu savita kontraŭ miaj malamantoj kaj el profunda akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Ne fortiru min fluo de la akvo, Ne englutu min profundo, Kaj abismo ne fermu super mi sian buŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Aŭskultu min, ho Eternulo, ĉar bona estas Via favorkoreco; Laŭ Via kompatemeco turnu Vin al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Kaj ne kaŝu antaŭ Via sklavo Vian vizaĝon, ĉar mi suferas; Rapidu, aŭskultu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Alproksimiĝu al mia animo, savu ĝin; Spite miajn malamikojn liberigu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Vi scias mian malhonoron kaj mian honton kaj mian mokatecon; Antaŭ Vi estas ĉiuj miaj premantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Honto rompis mian koron, kaj mi senfortiĝis; Mi atendis kompatantojn, sed ili forestis; Konsolantojn, sed mi ne trovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Kaj ili donis al mi por manĝo galon, Kaj en mia soifo ili trinkigis al mi vinagron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Ilia tablo antaŭ ili fariĝu reto, Kaj ilia prospero fariĝu kaptilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Mallumiĝu iliaj okuloj, ke ili ne vidu; Kaj iliajn lumbojn malfortigu por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Verŝu sur ilin Vian furiozon, Kaj la flamo de Via kolero ilin ataku.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Ilia loĝejo dezertiĝu, En iliaj tendoj ne ekzistu loĝanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Ĉar tiun, kiun Vi frapis, ili persekutas, Kaj la suferojn de Viaj batitoj ili rakontas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Aldonu kulpon al ilia kulpo, Ke ili ne atingu Vian bonecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Ili estu elstrekitaj el la libro de vivantoj, Kaj ili ne estu skribitaj kune kun virtuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Sed mi estas malriĉa kaj suferanta; Via helpo min defendu, ho Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Mi gloros la nomon de Dio per kanto, Kaj mi rakontos en danko Lian grandecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'Kaj ĝi estos pli agrabla al la Eternulo, Ol bovo aŭ bovido kun kornoj kaj fendohavaj hufoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'Vidos humiluloj kaj ĝojos! Ho serĉantoj de Dio, via koro reviviĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Ĉar la Eternulo aŭskultas humilulojn, Kaj Siajn malliberulojn Li ne malŝatas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Gloru Lin la ĉielo kaj la tero, La maroj, kaj ĉio, kio en ili moviĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Ĉar Dio helpos Cionon kaj konstruos la urbojn de Judujo, Ke oni tie loĝos kaj ilin heredos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'Kaj la idaro de Liaj sklavoj ĝin heredos, Kaj la amantoj de Lia nomo loĝos en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Al la ĥorestro. De David. Pro memoro. Volu, ho Dio, savi min; Ho Eternulo, rapidu helpi min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Hontiĝu kaj konfuziĝu tiuj, kiuj serĉas mian animon; Retiriĝu kaj estu mokataj tiuj, kiuj deziras al mi malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Kun honto iru returne tiuj, Kiuj diras al mi: Ha, ha!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Gaju kaj ĝoju pro Vi ĉiuj Viaj serĉantoj; Kaj la amantoj de Via savo diru ĉiam: Granda estas Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Kaj mi estas mizera kaj malriĉa; Ho Dio, rapidu al mi. Vi estas mia helpo kaj mia savanto; Ho Eternulo, ne malrapidu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'Vin, ho Eternulo, mi fidas: Mi neniam estu hontigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Per Via justeco savu min kaj liberigu min; Klinu al mi Vian orelon, kaj helpu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Estu por mi fortika roko, kien mi povus ĉiam veni, Kiun Vi destinis por mia savo; Ĉar Vi estas mia roko kaj mia fortikaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Ho mia Dio, liberigu min el la mano de malbonulo, El la mano de krimulo kaj premanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Ĉar Vi estas mia espero, ho mia Sinjoro; La Eternulo estas mia fido de post mia juneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Vin mi fidis de la embrieco, De la ventro de mia patrino Vi estas mia protektanto; Vin mi ĉiam gloros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Mirindaĵo mi estis por multaj; Kaj Vi estas mia forta rifuĝejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Mia buŝo estas plena de glorado por Vi, Ĉiutage de Via majesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Ne forpuŝu min en la tempo de maljuneco; Kiam konsumiĝos miaj fortoj, tiam ne forlasu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Ĉar miaj malamikoj parolas pri mi, Kaj tiuj, kiuj insidas kontraŭ mia animo, konsiliĝas inter si,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'Dirante: Dio lin forlasis; Persekutu kaj kaptu lin, ĉar neniu lin savos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Ho Dio, ne malproksimiĝu de mi; Ho mia Dio, rapidu, por helpi min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Estu hontigitaj kaj malaperu la persekutantoj de mia animo; De honto kaj malhonoro estu kovritaj tiuj, kiuj deziras al mi malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Kaj mi ĉiam fidos Kaj ĉiam pligrandigos Vian gloron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Mia buŝo rakontos Vian justecon, Ĉiutage Vian helpon, Ĉar mi ne povus ĉion elkalkuli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Mi gloros la fortojn de mia Sinjoro, la Eternulo; Mi rakontos nur Vian justecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Ho Dio, Vi instruis min detempe de mia juneco; Kaj ĝis nun mi predikas pri Viaj mirakloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Ankaŭ ĝis la maljuneco kaj grizeco ne forlasu min, ho Dio, Ĝis mi rakontos pri Via brako al la estonta generacio, Pri Via forto al ĉiuj venontoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Via justeco, ho Dio, estas tre alta; En la grandaj faroj, kiujn Vi plenumis, Ho Dio, kiu Vin egalas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Vi vidigis al mi grandajn kaj kruelajn suferojn, Sed Vi denove min vivigis, Kaj el la abismoj de la tero Vi denove min eligis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Vi pliigas mian grandecon Kaj denove min konsolas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'Kaj mi gloros Vin per psaltero por Via fideleco, ho mia Dio; Mi kantos al Vi per harpo, Ho Sanktulo de Izrael!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Ĝojas miaj lipoj, kiam mi kantas al Vi; Kaj mia animo, kiun Vi savis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Kaj mia lango ĉiutage rakontas Vian justecon; Ĉar hontigitaj kaj malhonoritaj estas tiuj, kiuj deziras al mi malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Pri Salomono. Ho Dio, Vian juĝon donu al la reĝo Kaj Vian justecon al la reĝido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Li juĝu Vian popolon kun vero Kaj Viajn prematojn kun justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'La montoj alportu al la popolo pacon, Ankaŭ la montetoj, per justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Li juĝu la prematojn en la popolo, Li savu la filojn de senhavulo, Kaj li dispremu la premanton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Oni timu Vin tiel longe, kiel ekzistos la suno kaj la luno, De generacioj al generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Li malleviĝu, kiel pluvo sur falĉitan herbejon; Kiel gutoj, kiuj malsekigas la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'En liaj tagoj floru virtulo kaj granda paco, Ĝis ne plu ekzistos la luno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Li regu de maro ĝis maro Kaj de la Rivero ĝis la finoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Kliniĝu antaŭ li la dezertanoj, Kaj liaj malamikoj leku polvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'La reĝoj de Tarŝiŝ kaj de la insuloj alportu donacojn; La reĝoj de Ŝeba kaj Seba venigu donojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Kliniĝu antaŭ li ĉiuj reĝoj; Ĉiuj popoloj lin servu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Ĉar li savos ploregantan malriĉulon Kaj senhelpan mizerulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Li estos favorkora por malriĉulo kaj senhavulo, Kaj li savos la animojn de mizeruloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'De malico kaj krimo li savos iliajn animojn; Kaj kara estos ilia sango en liaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Kaj li vivu, kaj oni donu al li el la oro de Ŝeba; Kaj oni ĉiam preĝu por li, kaj ĉiutage oni lin benu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Estu multe da greno en la lando; Sur la supro de la montoj ĝiaj spikoj ondiĝu kiel Lebanon; Kaj en la urboj ĉio floru, kiel herbo sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Lia nomo estu eterna; Tiel longe, kiel ekzistas la suno, kresku lia nomo; Ĉiuj popoloj sin benu per li kaj gloru lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Glorata estu Dio la Eternulo, Dio de Izrael, Kiu sola faras miraklojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'Kaj laŭdata estu Lia glora nomo eterne; Kaj Lia gloro plenigu la tutan teron. Amen, kaj amen!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Finiĝis la preĝoj de David, filo de Jiŝaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Psalmo de Asaf. Jes, bona estas Dio por Izrael, Por tiuj, kiuj havas puran koron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Sed mi-apenaŭ ne falŝanceliĝis miaj piedoj, Preskaŭ elglitis miaj paŝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Ĉar mi ĉagreniĝis pro la fanfaronuloj, Vidante la bonstaton de la malvirtuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Ĉar ili ne havas suferojn de morto, Kaj iliaj fortoj estas fortikaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'Ili ne partoprenas en la zorgoj de homoj, Kaj ili ne suferas kun aliaj homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Tial ilian kolon ĉirkaŭvolvis fiereco, Kaj perforteco ilin vestas kiel ornamo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Pro graso elmetiĝis iliaj okuloj, Superbordiĝis en ilia koro la intencoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Ili mokas, ili parolas malbonintence pri premado; Ili parolas de alte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Kontraŭ la ĉielon ili levas sian buŝon, Kaj ilia lango promenas sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Tial tien ankaŭ iras Lia popolo, Kaj ili akvon ĉerpas abunde.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Kaj ili diras: Kiel Dio scias? Kaj ĉu la Plejaltulo komprenas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Jen tiuj estas malvirtuloj, Kaj ili estas feliĉuloj de la mondo kaj atingis riĉecon!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Nur vane mi purigis mian koron Kaj lavis per senkulpeco miajn manojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'Kaj mi turmentiĝas ĉiutage Kaj mi suferas punon ĉiumatene!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Se mi intencus paroli kiel ili, Tiam mi fariĝus perfida al la generacio de Viaj filoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Mi meditis, por kompreni ĉi tion; Sed ĝi estis malfacila en miaj okuloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'Ĝis mi venis en la sanktejon de Dio Kaj ekkomprenis la finon de tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Vi starigas ilin sur glitiga loko; Kaj Vi ĵetas ilin en pereon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Kiel momente ili ruiniĝis! Pereis, malaperis de subita teruro!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Simile al sonĝo post la vekiĝo, Vi, ho mia Sinjoro, en kolero tute sensignifigas ilian bildon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Kiam bolis mia koro Kaj turmentiĝis mia internaĵo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'Tiam mi estis senklerulo kaj mi ne komprenis; Mi estis kiel bruto antaŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Sed mi ĉiam estas apud Vi; Vi tenas min je la dekstra mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Per Via konsilo Vi min kondukas, Kaj poste Vi akceptas min kun honoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Kiu estas por mi en la ĉielo? Kaj krom Vi mi nenion volas sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Konsumiĝas mia karno kaj mia koro; Sed la fortikaĵo de mia koro kaj mia parto estas Dio por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Jen tiuj, kiuj malproksimiĝas de Vi, pereas; Vi ekstermas ĉiun, kiu perfidiĝis al Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Sed al mi estas bone, ke mi estas proksima al Dio; Sur mian Sinjoron, sur la Eternulon, mi metis mian fidon, Por rakonti ĉiujn Viajn farojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Instruo de Asaf. Kial, ho Dio, Vi forpuŝis nin por ĉiam? Kial fumas Via kolero kontraŭ la ŝafoj de Via paŝtejo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Rememoru Vian komunumon, kiun Vi aĉetis en la tempo antikva, La genton de Via heredo, kiun Vi liberigis, Ĉi tiun monton Cion, sur kiu Vi loĝiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Direktu Viajn paŝojn al la eternaj ruinoj, Al ĉio, kion detruis malamiko en la sanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Krias Viaj malamikoj en Via domo, Metis tie siajn signojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Oni vidas, kiel ili levas la hakilojn Kontraŭ la lignajn plektaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'Kaj nun ĉiujn ĝiajn skulptaĵojn Ili dishakas per hakilo kaj marteloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Ili bruligis per fajro Vian sanktejon, Malhonore alterigis la loĝejon de Via nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'Ili diris en sia koro: Ni ruinigos ilin tute; Ili forbruligis ĉiujn domojn de Dio en la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Niajn signojn ni ne vidis; Jam ne ekzistas profeto, Kaj neniu ĉe ni scias, kiel longe tio daŭros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Kiel longe, ho Dio, mokos la premanto? Ĉu eterne la malamiko insultos Vian nomon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Kial Vi retenas Vian brakon kaj Vian dekstran manon? Ekstermu ilin el Via basko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Dio estas ja mia Reĝo de antikve, Li faras savon sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Vi disŝiris per Via forto la maron, Vi rompis la kapojn de balenoj en la akvo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Vi disbatis la kapojn de la levjatano, Vi donis ĝin por manĝo al la bestoj de la dezerto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Vi elfendis fonton kaj torenton, Vi elsekigis potencajn riverojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'Al Vi apartenas la tago, kaj al Vi apartenas la nokto; Vi aranĝis lumon kaj sunon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Vi difinis ĉiujn limojn de la tero; La someron kaj la vintron Vi aranĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Rememoru tion, ke malamiko insultas la Eternulon Kaj popolo malsaĝa malhonoras Vian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Ne fordonu al sovaĝa besto la animon de Via turto; La anaron de Viaj mizeruloj ne forgesu por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Rememoru la interligon, Ĉar ĉiuj mallumaj lokoj de la tero estas plenaj de rabejoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'La suferanto ne reiru hontigita; Malriĉulo kaj mizerulo gloru Vian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Leviĝu, ho Dio, defendu Vian aferon; Rememoru la malhonoron, kiun malsaĝulo faras al Vi ĉiutage.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Ne forgesu la krion de Viaj malamikoj; La bruo de tiuj, kiuj leviĝis kontraŭ Vi, konstante kreskas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Al la ĥorestro. Por Al-taŝĥet. Psalmo de Asaf. Kanto. Ni gloras Vin, ho Dio, ni gloras Vin; Proksima estas Via nomo; Oni rakontas Viajn miraklojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'Kiam Mi elektos tempon, Mi faros justan juĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'Tremas la tero kaj ĉiuj ĝiaj loĝantoj; Mi fortikigis ĝiajn kolonojn. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Mi diras al la fanfaronuloj: Ne fanfaronu; Kaj al la malvirtuloj: Ne levu kornon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Ne levu supren vian kornon, Ne parolu kun nefleksebla kolo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Ĉar ne de oriento kaj ne de okcidento Kaj ne de la dezerto venas alteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Nur Dio estas juĝanto; Unu homon Li malaltigas, kaj alian Li altigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'Ĉar la pokalo estas en la mano de la Eternulo, Kaj la vino ŝaŭmas, plena de aromaĵo, kaj Li verŝas el ĝi; Sed nur ĝian feĉon elsuĉos kaj trinkos ĉiuj malvirtuloj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Kaj mi eterne predikos, Mi kantos al la Dio de Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'Kaj ĉiujn kornojn de la malvirtuloj mi rompos; Altiĝos la kornoj de virtulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Al la ĥorestro. Por kordaj instrumentoj. Psalmo de Asaf. Kanto. Dio estas konata en Judujo; Granda estas Lia nomo en Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'En Salem estas Lia tendo, Kaj Lia loĝejo sur Cion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Tie Li rompis la sagojn de pafarko, Ŝildon, glavon, kaj militon. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Vi estas majesta kaj potenca sur la sovaĝbestaj montoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Senarmiĝis la fortkoruloj, endormiĝis; Kaj ĉiuj militistoj restis kvazaŭ sen manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'De Via minaco, ho Dio de Jakob, Paraliziĝis rajdisto kaj ĉevalo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Vi, Vi estas timinda; Kaj kiu restos staranta antaŭ Vi, kiam ekflamas Via kolero?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'El la ĉielo Vi aŭdigis juĝon; La tero ektimis kaj eksilentis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Kiam Dio leviĝis, por juĝi, Por savi ĉiujn humilulojn sur la tero. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'Ĉar la kolero de homo fariĝas Via gloro, Kiam Vi zonas Vin per la resto de Via kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Faru kaj plenumu promesojn al la Eternulo, via Dio; Vi ĉiuj, kiuj Lin ĉirkaŭas, alportu donacojn al la Timindulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Li humiligis la spiriton de potenculoj; Li estas timinda por la reĝoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Al la ĥorestro. Por Jedutun. Psalmo de Asaf. Mia voĉo iras al Dio, kaj mi krias; Mia voĉo iras al Dio, ke Li aŭskultu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'En la tago de mia suferado mi serĉas mian Sinjoron; En la nokto mia mano estas etendita kaj ne malleviĝas; Mia animo ne volas konsoliĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Mi rememoras Dion, kaj mi ĝemas; Mi meditas, kaj mia spirito malĝojas. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Vi retenas la palpebrojn de miaj okuloj; Mi estas frapita, mi ne povas paroli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Mi meditas pri la tagoj antikvaj, Pri la jaroj antaŭlonge pasintaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Mi rememoras en la nokto mian kanton; Mi parolas kun mia koro, Kaj mia spirito esploras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Ĉu por eterne mia Sinjoro forpuŝis? Kaj ĉu Li ne plu favoros?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Ĉu por eterne ĉesiĝis Lia boneco? Ĉu Lia promeso ne plenumiĝos por ĉiuj generacioj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Ĉu Dio forgesis indulgi? Ĉu Li fermis en kolero Sian favorkorecon? Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Kaj mi diris: Tio estas mia aflikto, Ke aliiĝis la dekstra mano de la Plejaltulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Mi rememoros la farojn de la Eternulo; Jes, mi rememoros Viajn antikvajn miraklojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Mi meditos pri ĉiuj Viaj faroj, Kaj pri Viaj agoj mi parolos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'Ho Dio, en sankteco estas Via vojo; Kiu estas tiel granda dio, kiel nia Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Vi estas tiu Dio, kiu faras miraklojn; Vi montris Vian forton inter la popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Vi liberigis per Via brako Vian popolon, La filojn de Jakob kaj Jozef. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Vidis Vin akvoj, ho Dio, Vidis Vin akvoj, kaj ili ektremis, Kaj abismoj skuiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Nubegoj verŝis akvon, La ĉielo eligis bruon, Kaj Viaj sagoj ekflugis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'La voĉo de Via tondro estis en la turnovento, Fulmoj lumigis la mondon; Tremis kaj ŝanceliĝis la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Sur la maro estis Via vojo, Kaj Via irejo sur grandaj akvoj, Sed Viaj paŝosignoj ne estis videblaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Vi kondukis Vian popolon kiel ŝafojn, Per la mano de Moseo kaj Aaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Instruo de Asaf. Atentu, ho mia popolo, mian instruon; Klinu vian orelon al la paroloj de mia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Mi malfermos per sentenco mian buŝon; Mi eldiros enigmojn el tempo antikva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Kion ni aŭdis kaj sciiĝis, Kion rakontis al ni niaj patroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'Tion ni ne kaŝos antaŭ iliaj infanoj, Rakontante al venonta generacio la gloron de la Eternulo, Kaj Lian potencon, kaj Liajn miraklojn, kiujn Li faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Li starigis ateston en Jakob, Kaj en Izrael Li fiksis leĝon, Pri kiu Li ordonis al niaj patroj, Ke ili sciigu ĝin al siaj infanoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'Por ke sciu estonta generacio, la infanoj, kiuj naskiĝos, Ili leviĝu kaj rakontu al siaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'Ili metu sian fidon sur Dion, Kaj ili ne forgesu la farojn de Dio, Kaj ili plenumu Liajn ordonojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'Kaj ili ne estu, kiel iliaj patroj, Generacio ribela kaj perfida, Generacio, kiu ne estis firma per sia koro, Nek fidela al Dio per sia spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'La filoj de Efraim, armitaj, portantaj pafarkon, Turniĝis malantaŭen en tago de batalo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Ili ne plenumis la interkonsenton de Dio, Kaj rifuzis sekvi Lian instruon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'Kaj ili forgesis Liajn farojn, Kaj Liajn miraklojn, kiujn Li aperigis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Antaŭ iliaj patroj Li faris miraklojn En la lando Egipta, sur la kampo Coan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Li fendis la maron kaj pasigis ilin, Kaj starigis la akvon kvazaŭ muron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Kaj Li kondukis ilin tage en nubo Kaj la tutan nokton en la lumo de fajro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Li fendis ŝtonojn en la dezerto, Kaj trinkigis ilin kvazaŭ el granda abismo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Li eligis riveretojn el roko, Kaj fluigis akvon kiel riverojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Sed ili plue pekis antaŭ Li, Ĉagrenis la Plejaltulon en la dezerto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'Kaj ili incitis Dion en sia koro, Petante manĝon pro sia kaprico;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'Kaj ili parolis kontraŭ Dio, Kaj diris: Ĉu Dio povas kovri tablon en la dezerto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Jen Li frapis rokon, Kaj verŝiĝis akvo kaj ekfluis riveroj: Ĉu Li povas ankaŭ panon doni? Ĉu Li pretigos ankaŭ viandon por Sia popolo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Tial la Eternulo, aŭdinte, flamiĝis; Kaj fajro ekbrulis kontraŭ Jakob, Kaj leviĝis kolero kontraŭ Izrael;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'Ĉar ili ne kredis je Dio Kaj ne fidis Lian savon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Kaj Li ordonis el supre al la nuboj, Kaj Li malfermis la pordojn de la ĉielo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'Kaj Li pluvigis al ili manaon, por manĝi, Kaj Li donis al ili ĉielan grenon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Panon de potenculoj ĉiu manĝis; Li sendis al ili manĝon satege.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Li kurigis tra la ĉielo venton orientan, Kaj per Sia forto Li aperigis venton sudan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'Kaj Li pluvigis sur ilin viandon kiel polvon, Kaj flugilajn birdojn kiel apudmaran sablon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'Kaj Li faligis ĉion mezen de ilia tendaro, Ĉirkaŭe de iliaj loĝejoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Kaj ili manĝis kaj tre satiĝis; Kaj Li venigis al ili tion, kion ili deziris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Sed kiam ili ankoraŭ ne forlasis sian deziron Kaj ilia manĝaĵo estis ankoraŭ en ilia buŝo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'La kolero de Dio venis sur ilin Kaj mortigis la plej eminentajn el ili, Kaj la junulojn de Izrael ĝi faligis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Malgraŭ ĉio ĉi tio ili plue ankoraŭ pekis Kaj ne kredis je Liaj mirakloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Kaj Li finigis iliajn tagojn en vanteco Kaj iliajn jarojn en teruro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Kiam Li estis mortiganta ilin, tiam ili Lin ekserĉis, Returniĝis kaj fervore vokis Dion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'Kaj ili rememoris, ke Dio estas ilia fortikaĵo Kaj Dio la Plejalta estas ilia Liberiganto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Sed ili flatis al Li per sia buŝo, Kaj per sia lango ili mensogis al Li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'Ĉar ilia koro ne estis firma al Li, Kaj ili ne estis fidelaj en Lia interligo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Tamen Li, favorkora, pardonas pekon, kaj Li ne pereigas, Kaj Li ofte forklinis Sian koleron, Kaj Li ne eligis Sian tutan furiozon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Kaj Li rememoris, ke ili estas karno, Vento, kiu iras kaj ne revenas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Kiom da fojoj ili ĉagrenis Lin en la dezerto Kaj indignigis Lin en la stepo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Ripete ili incitadis Dion Kaj provokis la Sanktulon de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Ili ne rememoris Lian manon, La tagon, en kiu Li liberigis ilin de premanto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'Kiam Li faris en Egiptujo Siajn signojn Kaj Siajn miraklojn sur la kampo Coan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'Kiam Li ŝanĝis en sangon iliajn riverojn kaj torentojn, Ke ili ne povis trinki.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Li sendis sur ilin insektojn, kiuj ilin manĝis, Kaj ranojn, kiuj ilin pereigis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'Iliajn produktojn de la tero Li fordonis al vermoj Kaj ilian laboron al akridoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Per hajlo Li batis iliajn vinberojn, Kaj iliajn sikomorojn per frosto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Li elmetis al hajlo iliajn brutojn, Kaj iliajn paŝtatarojn al fulmo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Li sendis sur ilin Sian flamantan koleron, Furiozon, malbenon, kaj mizeron, Taĉmenton da malbonaj anĝeloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Li donis liberan vojon al Sia kolero, Ne ŝirmis kontraŭ la morto ilian animon, Kaj ilian vivon Li transdonis al pesto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'Li mortigis ĉiun unuenaskiton en Egiptujo, La komencajn fortojn en la tendoj de Ĥam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Kaj Li kondukis kiel ŝafojn Sian popolon, Kaj Li kondukis ilin kiel paŝtataron tra la dezerto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Li kondukis ilin en sendanĝereco, kaj ili ne timis, Kaj iliajn malamikojn kovris la maro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Kaj Li venigis ilin al Sia sankta limo, Al tiu monto, kiun akiris Lia dekstra mano;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Li forpelis antaŭ ili popolojn, Lote disdonis ilian heredon, Kaj loĝigis en iliaj tendoj la tribojn de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Sed ili incitis kaj ĉagrenis Dion la Plejaltan, Kaj Liajn leĝojn ili ne observis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'Ili defalis kaj perfidiĝis, kiel iliaj patroj, Returniĝis, kiel malfidinda pafarko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Ili kolerigis Lin per siaj altaĵoj, Kaj per siaj idoloj ili Lin incitis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Dio aŭdis kaj flamiĝis, Kaj forte ekindignis kontraŭ Izrael;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'Li forlasis Sian loĝejon en Ŝilo, La tendon, en kiu Li loĝis inter la homoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'Kaj Li fordonis en malliberecon Sian forton, Kaj Sian majeston en la manon de malamiko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'Kaj Li elmetis al glavo Sian popolon, Kaj kontraŭ Sia heredo Li flamiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Ĝiajn junulojn formanĝis fajro, Kaj ĝiaj junulinoj ne estis prikantataj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Ĝiaj pastroj falis de glavo, Kaj ĝiaj vidvinoj ne ploris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Sed mia Sinjoro vekiĝis kiel dormanto, Kiel fortulo, vigligita de vino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'Kaj Li batis ĝiajn malamikojn malantaŭen: Eternan malhonoron Li donis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Kaj Li malŝatis la tendon de Jozef, Kaj la tribon de Efraim Li ne elektis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'Sed Li elektis la tribon de Jehuda, La monton Cion, kiun Li ekamis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'Kaj Li konstruis Sian sanktejon kiel monton, Kaj kiel la teron Li fortikigis ĝin por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'Kaj Li elektis Davidon, Sian sklavon, Kaj Li prenis lin el la staloj de ŝafoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'De apud la ŝafinoj Li venigis lin, Por paŝti Lian popolon Jakob kaj Lian heredon Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Kaj li paŝtis ilin laŭ la fideleco de sia koro, Kaj per lertaj manoj li ilin kondukis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Psalmo de Asaf. Ho Dio! venis idolanoj en Vian heredon, Malpurigis Vian sanktan templon, Faris el Jerusalem ruinojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'La kadavrojn de Viaj sklavoj ili donis kiel manĝon al la birdoj de la ĉielo, La karnon de Viaj fideluloj al la bestoj de la tero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Ili verŝis ilian sangon kiel akvon, ĉirkaŭ Jerusalem, Kaj estis neniu, kiu ilin enterigus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Ni fariĝis hontindaĵo por niaj najbaroj, Mokataĵo kaj insultataĵo por niaj ĉirkaŭantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Ĝis kiam, ho Eternulo, Vi koleros senĉese? Kaj Via indigno brulos, kiel fajro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Elverŝu Vian koleron sur tiujn naciojn, kiuj Vin ne konas, Kaj sur la regnojn, kiuj ne vokas Vian nomon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Ĉar ili formanĝis Jakobon Kaj dezertigis lian loĝejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Ne memoru niajn antaŭajn krimojn, Rapide atingu nin Via favorkoreco; Ĉar ni tre konsumiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Helpu nin, ho Dio de nia savo, pro la gloro de Via nomo; Kaj savu nin kaj pardonu al ni niajn pekojn pro Via nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Kial devas diri la popoloj: Kie estas ilia Dio? Fariĝu konata inter la popoloj antaŭ niaj okuloj La venĝo por la verŝita sango de Viaj sklavoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Venu al Vi la ĝemoj de la malliberuloj; Per la grandeco de Via brako liberigu tiujn, kiuj estas kondamnitaj al morto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'Kaj redonu al niaj najbaroj sepoble en ilian sinon la malhonoron, Per kiu ili malhonoris Vin, ho mia Sinjoro!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Kaj ni, Via popolo kaj la ŝafoj de Via paŝtataro, Eterne Vin dankos, De generacio al generacio ni rakontos Vian gloron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Al la ĥorestro. Por ŝoŝanoj. Atesto de Asaf. Psalmo. Ho Paŝtisto de Izrael, aŭskultu; Vi, kiu kondukas Jozefon, kiel ŝafojn, Vi, kiu sidas sur keruboj, aperu!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Antaŭ Efraim kaj Benjamen kaj Manase veku Vian forton, Kaj venu, por savi nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Ho Dio, revenigu nin kaj lumigu Vian vizaĝon, Por ke ni estu savitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Ho Eternulo, Dio Cebaot, Ĝis kiam Vi kolere repuŝos la preĝon de Via popolo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Vi manĝigis al ili panon larman, Kaj Vi trinkigis al ili larmojn per granda mezuro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Vi faris nin objekto de disputo por niaj najbaroj; Kaj niaj malamikoj nin mokas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Ho Dio Cebaot! revenigu nin kaj lumigu Vian vizaĝon, Por ke ni estu savitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Vinberbranĉon el Egiptujo Vi elportis, Vi forpelis popolojn kaj ĝin plantis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Vi purigis lokon por ĝi; Kaj ĝi profundigis siajn radikojn kaj plenigis la tutan landon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Montojn kovris ĝia ombro, Kaj ĝiaj branĉoj fariĝis kiel cedroj de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Ĝi etendis siajn branĉojn ĝis la maro Kaj siajn branĉetojn ĝis la Rivero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Kial Vi detruis ĝiajn barilojn, Ke ĉiuj pasantoj ĝin ŝiras?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Subfosas ĝin arbara apro, Kaj kampa besto ĝin mordas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Ho Dio Cebaot, returniĝu; Rigardu el la ĉielo kaj vidu, kaj rememoru tiun vinbertrunkon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'Kaj ŝirmu tion, kion plantis Via dekstra mano, Kaj la kreskaĵidon, kiun Vi fortikigis por Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'Ĝi estas bruligita de fajro, krevinta; De Via minaca vizaĝo ili pereis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Via brako estu super la viro de Via dekstra mano, Super la homido, kiun Vi fortikigis por Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Kaj ni ne foriros de Vi; Vivigu nin, kaj ni vokos Vian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'Ho Eternulo, Dio Cebaot! revenigu nin, lumigu Vian vizaĝon, Por ke ni estu savitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Al la ĥorestro. Por la gitito. De Asaf. Laŭte kantu al Dio, nia forto; Ĝoje kriu al la Dio de Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Sonigu kanton, donu tamburinon, Ĉarman harpon, kaj psalteron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Muziku per korno en novmonato, Je la plenluno, en la tago de nia festo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Ĉar ĝi estas leĝo por Izrael Kaj ordono de la Dio de Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'Li aranĝis ĝin kiel ateston por Jozef, Kiam Li eliris kontraŭ la landon Egiptan. Lingvon, kiun mi ne konas, mi aŭdis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'Mi liberigis lian dorson de ŝarĝo, Liaj manoj liberiĝis de korboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'En la mizero vi vokis, kaj Mi vin helpis; Mi respondis al vi en mistera loko de tondro; Mi esploris vin ĉe la akvo de Malpaco. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Aŭdu, ho Mia popolo, Mi atestos al vi; Ho Izrael, se vi Min aŭskultus!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Ne estu ĉe vi alia dio; Kaj ne adoru fremdan dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Mi estas la Eternulo, via Dio, Kiu elkondukis vin el la lando Egipta; Malfermu larĝe vian buŝon, kaj Mi ĝin plenigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Sed Mia popolo ne aŭskultis Mian voĉon, Izrael ne obeis Min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Kaj Mi lasis ilin al la kaprico de ilia koro, Ke ili iru laŭ siaj intencoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'Ho, se Mia popolo aŭskultus Min, Se Izrael irus per Miaj vojoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Rapide Mi faligus iliajn malamikojn, Kaj kontraŭ iliajn premantojn Mi direktus Mian manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'La malamantoj de la Eternulo humiliĝus antaŭ Li, Kaj ilia bonstato estus eterna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'Kaj Mi manĝigus al ili grason de tritiko, Kaj Mi satigus vin per mielo el roko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Psalmo de Asaf. Dio stariĝis en Dia anaro; Inter la dioj Li juĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, 'Ĝis kiam vi juĝos maljuste, Kaj privilegios la personojn de malvirtuloj? Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Estu justaj al malriĉulo kaj orfo; Rilate afliktiton kaj senhavulon estu virtaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Liberigu malriĉulon kaj mizerulon; El la mano de malvirtulo ilin savu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Ili ne scias kaj ne komprenas, En mallumo ili marŝas; Ekŝanceliĝis ĉiuj fundamentoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Mi diris: Vi estas dioj, Kaj ĉiuj vi estas filoj de la Plejaltulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Sed vi mortos, kiel homoj, Kaj vi falos, kiel ĉiu el la potenculoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Leviĝu, ho Dio, juĝu la teron; Ĉar Vi heredas ĉiujn popolojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Kanto-Psalmo de Asaf. Ho Dio, ne silentu; Ne estu senparola kaj ne restu trankvila, ho Dio!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Ĉar jen Viaj malamikoj ekbruis, Kaj Viaj malamantoj levis la kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Kontraŭ Via popolo ili sekrete konspiras, Kaj ili konsiliĝas kontraŭ Viaj gardatoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Ili diris: Ni iru, kaj ni ekstermu ilin el inter la popoloj, Ke oni ne plu rememoru la nomon de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Ĉar ili unuanime interkonsentis, Ili faris interligon kontraŭ Vi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'La tendoj de Edom kaj la Iŝmaelidoj, Moab kaj la Hagaridoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Gebal kaj Amon kaj Amalek, La Filiŝtoj kun la loĝantoj de Tiro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'Ankaŭ Asirio aliĝis al ili Kaj fariĝis helpo al la idoj de Lot. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Faru al ili, kiel al Midjan, Kiel al Sisera, kiel al Jabin ĉe la torento Kiŝon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Kiuj estis ekstermitaj en En-Dor Kaj fariĝis sterko por la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Agu kun iliaj princoj kiel kun Oreb kaj Zeeb, Kaj kun ĉiuj iliaj estroj kiel kun Zebaĥ kaj Calmuna,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Kiuj diris: Ni ekposedu la loĝejon de Dio!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'Ho mia Dio, similigu ilin al turniĝanta polvo, Al pajlrestaĵo antaŭ vento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Kiel fajro bruligas arbaron, Kaj kiel flamo bruldezertigas montojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Tiel pelu ilin per Via ventego, Kaj per Via fulmotondro ilin timigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'Plenigu ilian vizaĝon per malhonoro, Por ke ili turniĝu al Via nomo, ho Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Ili estu hontigitaj kaj timigitaj por ĉiam, Ili malhonoriĝu kaj pereu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'Kaj ili eksciu, ke Vi, kies nomo estas ETERNULO, Estas sola Plejaltulo super la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Al la ĥorestro. Por la gitito. Psalmo de la Koraĥidoj. Kiel ĉarmaj estas Viaj loĝejoj, ho Eternulo Cebaot!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Mia animo deziras kaj sopiras al la kortoj de la Eternulo; Mia koro kaj mia korpo sentas ravon pri la viva Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Eĉ birdo trovas domon kaj hirundo neston por si, En kiu ĝi tenas siajn idojn: Viajn altarojn, ho Eternulo Cebaot, mia Reĝo kaj mia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Feliĉaj estas tiuj, kiuj loĝas en Via domo: Ili laŭdas Vin konstante. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Feliĉaj estas la homoj, kies forto estas en Vi, Kaj en kies koro estas Viaj vojoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Kiuj pasas tra la Valo de Ploro kaj faras tie fontojn, Kaj la printempa pluvo ĝin kovras per benoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Ili iras de forto al forto, Aperas antaŭ Dio sur Cion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Ho Eternulo, Dio Cebaot, aŭdu mian preĝon; Aŭskultu, ho Dio de Jakob! Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Nia ŝildo, vidu, ho Dio, Kaj rigardu la vizaĝon de Via sanktoleito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Ĉar tago en Viaj kortoj estas pli bona, ol mil aliaj: Mi preferas stari sur la sojlo de la domo de mia Dio, Ol loĝi en tendoj de malvirto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Ĉar Dio, la Eternulo, estas suno kaj ŝildo; Favoron kaj honoron donas la Eternulo; Li ne domaĝas bonon al tiuj, kiuj iras en virto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Ho Eternulo Cebaot, bone estas al la homo, kiu Vin fidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Al la ĥorestro. Psalmo de la Koraĥidoj. Vi korfavoris, ho Eternulo, Vian landon, Vi revenigis la forkaptitojn de Jakob;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Vi pardonis la kulpon de Via popolo, Vi kovris ĉiujn ĝiajn pekojn. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Vi retenis Vian tutan koleron, Forlasis Vian furiozon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Turnu Vin al ni, ho Dio de nia savo, Kaj ĉesigu Vian koleron kontraŭ ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Ĉu eterne Vi nin koleros, Daŭrigos Vian koleron de generacio al generacio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Ĉu Vi ne revivigos nin denove, Ke Via popolo ĝoju per Vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Aperigu al ni, ho Eternulo, Vian favoron, Kaj Vian helpon donu al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Mi aŭdu, kion diras Dio, la Eternulo; Ĉar Li deklaros pacon al Sia popolo kaj al Siaj fideluloj, Ke ili ne reiru al malsaĝeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Jam proksima estas Lia helpo al tiuj, kiuj Lin timas, Por ke ekregu honoro en nia lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Bono kaj vero renkontiĝas, Justeco kaj paco sin kisas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'Vero elkreskas el la tero, Kaj justeco rigardas el la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'Kaj la Eternulo donos bonon, Kaj nia tero donos siajn produktojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'Justeco iros antaŭ Li Kaj faros vojon por Liaj paŝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Preĝo de David. Klinu, ho Eternulo, Vian orelon, aŭskultu min; Ĉar mi estas mizera kaj malriĉa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Konservu mian animon, ĉar mi estas fidela; Ho Vi, mia Dio, helpu Vian sklavon, kiu fidas Vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Korfavoru min, ho mia Sinjoro, Ĉar mi vokas al Vi la tutan tagon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Ĝojigu la animon de Via sklavo, Ĉar al Vi, ho mia Sinjoro, mi levas mian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Ĉar Vi, mia Sinjoro, estas bona kaj pardonema Kaj tre favora por ĉiuj, kiuj Vin vokas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Aŭskultu, ho Eternulo, mian preĝon, Kaj atentu la voĉon de mia petego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'En tago de mia sufero mi Vin vokas, Por ke Vi aŭskultu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Ne ekzistas simila al Vi inter la dioj, ho mia Sinjoro, Kaj ne ekzistas faroj kiel Viaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Ĉiuj popoloj, kiujn Vi kreis, venos kaj kliniĝos antaŭ Via vizaĝo, ho mia Sinjoro, Kaj honoros Vian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Ĉar Vi estas granda kaj Vi faras miraklojn; Vi sola estas Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Montru al mi, ho Eternulo, Vian vojon, por ke mi iru en Via vero; Dediĉu mian koron al la respektado de Via nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Mi dankos Vin, ho mia Sinjoro, mia Dio, per mia tuta koro, Kaj mi honoros Vian nomon eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'Ĉar granda estas Via boneco al mi; Kaj Vi savis mian animon el la profundo de Ŝeol.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'Ho Dio, fieruloj leviĝis kontraŭ mi, Kaj anaro da premantoj serĉas mian animon Kaj ne havas Vin antaŭ si.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Sed Vi, mia Sinjoro, estas Dio kompatema kaj favorkora, Longetolerema kaj tre bona kaj verama.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Turnu Vin al mi kaj korfavoru min, Donu Vian forton al Via sklavo, Kaj helpu la filon de Via sklavino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Faru super mi signon por bono, Por ke miaj malamantoj vidu kaj hontiĝu, Ĉar Vi, ho Eternulo, min helpos kaj konsolos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'De la Koraĥidoj. Psalmo-kanto. Lia fundamento estas sur la sanktaj montoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'La Eternulo amas la pordegojn de Cion Pli ol ĉiujn loĝejojn de Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Gloraĵojn Li rakontas pri vi, ho urbo de Dio. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'Mi parolas al miaj konatoj pri Egiptujo kaj Babel, Ankaŭ pri Filiŝtujo kaj Tiro kun Etiopujo: Jen tiu tie naskiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'Sed pri Cion oni diras: Tiu kaj tiu tie naskiĝis, Kaj Li, la Plejaltulo, ĝin fortikigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'La Eternulo notos, enskribante la popolojn: Ĉi tiu tie naskiĝis. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'Kaj la kantistoj kaj muzikistoj: Ĉiuj miaj fontoj estas en Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Kanto-psalmo de la oraĥidoj. Al la ĥorestro. Por maĥalat-leanoto. de Heman, la Ezraĥido. Ho Eternulo, Dio de mia savo! Tage kaj nokte mi krias antaŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Mia preĝo venu antaŭ Vian vizaĝon; Klinu Vian orelon al mia ploro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Ĉar mia animo trosatiĝis de malbonoj Kaj mia vivo atingis Ŝeolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Mi similiĝis al la forirantoj en la tombon; Mi fariĝis kiel viro sen fortoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Etendita inter mortintoj; Kiel mortigitoj, kuŝantaj en la tombo, Kiujn Vi jam ne rememoras Kaj kiuj estas forigitaj for de Via mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Vi metis min en la plej profundan foson, En mallumon, en abismon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Pezas sur mi Via furiozo, Kaj per ĉiuj Viaj ondoj Vi min premas. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Vi malproksimigis de mi miajn konatojn, Vi faris min abomenaĵo por ili; Mi estas enŝlosita, kaj mi ne povas eliri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Mia okulo mallumiĝis de malĝojo; Mi vokas Vin, ho Eternulo, ĉiutage, Mi etendas al Vi miajn manojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Ĉu por mortintoj Vi faros miraklojn? Ĉu malvivuloj leviĝos kaj gloros Vin? Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Ĉu en la tombo estos rakontata Via boneco, Kaj fidindeco en la abismo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Ĉu en la mallumo estos konataj Viaj mirakloj, Kaj Via justeco en la lando de forgeso?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Sed mi vokas al Vi, ho Eternulo, Kaj matene mia preĝo Vin renkontas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Kial, ho Eternulo, Vi forpuŝas mian animon? Kial Vi kaŝas Vian vizaĝon de mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Mi estas mizera kaj senforta detempe de la juneco; Mi portas Viajn terurojn, mi konsumiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Venis sur min Via furiozo, Viaj timigoj min dispremas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Ili ĉirkaŭas min, kiel akvo, ĉiutage; Ili tute min ĉirkaŭsieĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Vi malproksimigis de mi amanton kaj amikon; Miaj konatoj estas en mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Instruo de Etan, la Ezraĥido. La favorfarojn de la Eternulo mi kantos eterne; De generacio al generacio mi sciigos Vian fidelecon per mia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Ĉar mi diris: Por eterne estas fundamentita la boneco, En la ĉielo estas fortikigita Via fideleco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'Mi faris interligon kun Mia elektito. Mi ĵuris al David, Mia sklavo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'Por eterne Mi fortikigos vian semon, Kaj Mi konstruis vian tronon por ĉiuj generacioj. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'Kaj la ĉielo gloras Viajn miraklojn, ho Eternulo, Kaj Vian fidelecon en la anaro de la sanktuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Ĉar kiu en la ĉielo estas egala al la Eternulo? Kiu estas simila al la Eternulo inter la potenculoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Dio estas potenca en la anaro de la sanktuloj, Kaj timinda por ĉiuj, kiuj Lin ĉirkaŭas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Ho Eternulo, Dio Cebaot, Kiu estas potenca kiel Vi, ho Eternulo? Kaj Via fideleco estas en ĉio, kio Vin ĉirkaŭas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Vi regas la malkvietecon de la maro; Kiam leviĝas ĝiaj ondoj, Vi ilin kvietigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Vi faligis Rahabon, kiel mortigiton; Per Via forta brako Vi diskurigis Viajn malamikojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Al Vi apartenas la ĉielo, kaj ankaŭ al Vi apartenas la tero; La universon, kaj ĉion, kio ĝin plenigas, Vi fondis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'La nordon kaj la sudon Vi kreis; Tabor kaj Ĥermon prikantas Vian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Vi havas brakon kun forto; Sela. Potenca estas Via mano, alta estas Via dekstra.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Virto kaj justeco estas la fundamento de Via trono; Boneco kaj vero iras antaŭ Via vizaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Feliĉa estas la popolo, kiu konas trumpetadon; Ho Eternulo, en la lumo de Via vizaĝo ili marŝas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Pro Via nomo ili ĝojas la tutan tagon, Kaj ili fieras pro Via justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'Ĉar Vi estas la beleco de ilia forto; Kaj pro Via favoro altiĝas nia korno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Ĉar de la Eternulo estas nia ŝildo, Kaj de la Sanktulo de Izrael estas nia reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Tiam Vi parolis en vizio al Viaj fideluloj, Kaj Vi diris: Mi sendis helpon al heroo, Mi altigis elektiton el la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Mi trovis Davidon, Mian sklavon, Per Mia sankta oleo Mi lin ŝmiris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'Mia mano lin subtenos, Kaj Mia brako lin fortikigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'Ne venkos lin malamiko, Kaj malbonagulo lin ne premos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Kaj Mi disbatos antaŭ lia vizaĝo liajn malamikojn, Kaj liajn malamantojn Mi frapos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'Kaj Mia fideleco kaj Mia favoro estas kun li; Kaj per Mia nomo altiĝos lia korno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'Kaj Mi etendos super la maron lian brakon Kaj super la riverojn lian dekstran manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'Li vokos Min: Vi estas mia patro, Mia Dio, kaj la roko de mia savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Kaj Mi faros lin unuenaskito, Ĉefo super la reĝoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Por ĉiam Mi konservos al li Mian favoron; Kaj Mia interligo kun li estos fidela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Kaj lian semon Mi faros eterna, Kaj lian tronon longedaŭra kiel la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Se liaj filoj forlasos Mian instruon Kaj ne iros laŭ Miaj leĝoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'Se Miajn decidojn ili malplenumos Kaj Miajn ordonojn ili ne observos:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'Tiam Mi per bastono punos ilian pekon Kaj per batoj ilian krimon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'Sed Mian favoron Mi ne forprenos de li, Kaj Mian fidelecon Mi ne perfidos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Mi ne malplenumos Mian interligon, Kaj tion, kio eliris el Mia buŝo, Mi ne ŝanĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Unu aferon Mi ĵuris per Mia sankteco: Mi ne perfidos al David;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Lia semo estos eterna, Kaj lia trono estos kiel la suno antaŭ Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Kiel la luno, ĝi staros eterne, Kaj kiel la atestulo en la ĉielo ĝi estos fidinda. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Sed nun Vi forpuŝis kaj malestimis, Vi koleris Vian sanktoleiton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Vi disigis la interligon kun Via sklavo, Ĵetis sur la teron lian kronon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Vi detruis ĉiujn liajn barilojn, Ruinigis liajn fortikaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Prirabas lin ĉiuj pasantoj; Li fariĝis mokataĵo por siaj najbaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Vi altigis la dekstran manon de liaj malamikoj, Vi ĝojigis ĉiujn liajn kontraŭulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Vi returnis la tranĉon de lia glavo, Kaj ne subtenis lin en la milito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Vi forigis lian brilon, Kaj lian tronon Vi ĵetis sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Vi mallongigis la tagojn de lia juneco, Vi kovris lin per honto. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Ĝis kiam, ho Eternulo, Vi kaŝos Vin senĉese Kaj Via kolerego brulos kiel fajro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Ho, rememoru, kia estas la daŭro de mia vivo, Por kia vantaĵo Vi kreis ĉiujn homidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Kiu homo vivas kaj neniam vidos morton, Savos sian animon de la mano de Ŝeol? Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Kie estas Viaj antaŭaj favorfaroj, mia Sinjoro, Pri kiuj Vi ĵuris al David per Via fideleco?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Rememoru, mia Sinjoro, la malhonoron de Viaj sklavoj, Kiun mi portas en mia brusto de ĉiuj multaj popoloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Kaj per kiu malhonoras Viaj malamikoj, ho Eternulo, Per kiu ili malhonoras la paŝosignojn de Via sanktoleito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'Glorata estu la Eternulo eterne. Amen, kaj Amen!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Preĝo de Moseo, homo de Dio. Mia Sinjoro, Vi estis por ni loĝejo De generacio al generacio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Antaŭ ol la montoj naskiĝis Kaj Vi kreis la teron kaj la mondon, Kaj de eterne ĝis eterne, Vi estas Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Vi venigas homon al polvo; Kaj Vi diras: Revenu, homidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Ĉar mil jaroj estas en Viaj okuloj Kiel la hieraŭa tago, kiu pasis, Kaj kiel nokta gardoparto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Vi forfluigas ilin torente, ili estas kiel sonĝo; Matene ili renoviĝas kiel herbo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'Matene ĝi floras kaj ĝermas, Vespere ĝi dehakiĝas kaj sekiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Jes, ni pereas de Via kolero, Kaj de Via kolerego ni neniiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Vi metis niajn malbonagojn antaŭ Vin, Nian kaŝitaĵon antaŭ la lumon de Via vizaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Ĉar ĉiuj niaj tagoj pasis sub Via kolero, Malaperis niaj jaroj, kiel sono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'La daŭro de nia vivo estas sepdek jaroj, Kaj ĉe forteco okdek jaroj; Kaj ilia tuta majesto estas penado kaj suferado, Ĉar ĝi forkuras rapide kaj ni forflugas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Kiu scias la forton de Via kolero, Vian timindecon kaj Vian indignon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Instruu nin kalkuli niajn tagojn, Por ke ni akiru saĝan koron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Returnu Vin, ho Eternulo! Kiel longe? Kaj kompatu Viajn sklavojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Satigu nin matene per Via boneco; Kaj ni kantos kaj ĝojos en la daŭro de nia tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Ĝojigu nin tiel longe, kiel Vi nin premis, Tiom da jaroj, kiom ni vidis mizeron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Al Viaj sklavoj aperu Viaj faroj, Kaj Via beleco al iliaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Kaj la favoro de la Eternulo, nia Dio, estu super ni; Kaj la faron de niaj manoj fortikigu al ni, Kaj fortikigu la faron de niaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Kiu loĝas sub la ŝirmo de la Plejaltulo, Tiu ripozas en la ombro de la Plejpotenculo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'Mi diras al la Eternulo: Mia rifuĝejo kaj mia fortikaĵo Estas Dio, kiun mi fidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Ĉar Li savos vin de la reto de kaptisto, De la pereiga pesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Per Siaj plumoj Li ŝirmos vin, Kaj sub Liaj flugiloj vi rifuĝos; Lia fideleco estas ŝildo kaj kiraso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Ne timu la teruron de nokto, Nek sagon, kiu flugas tage,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'Nek peston, kiu iras en mallumo, Nek epidemion, kiu ekstermas tagmeze.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Ĉe via flanko falos milo, Kaj dek miloj ĉe via dekstra flanko; Sed vin ĝi ne tuŝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Vi nur rigardos per viaj okuloj, Kaj vi vidos la redonon al la malvirtuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Ĉar Vi, ho Eternulo, estas mia defendo! La Plejaltulon vi elektis kiel vian rifuĝejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Ne trafos vin malbono, Kaj frapo ne atingos vian tendon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Ĉar al Siaj anĝeloj Li ordonis pri vi, Ke ili vin gardu sur ĉiuj viaj vojoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Sur la manoj ili vin portos, Por ke vi ne falpuŝiĝu sur ŝtono per via piedo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Sur leonon kaj aspidon vi paŝos, Vi piedpremos leonidon kaj drakon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'Ĉar li ekamis Min, tial Mi lin savos; Mi defendos lin, ĉar li konas Mian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Li vokos Min, kaj Mi lin aŭskultos; Mi estos kun li en mizero; Mi lin liberigos kaj honoratigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Mi satigos lin per longa vivo, Kaj aperigos al li Mian helpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Psalmo-kanto por la tago sabata. Bone estas glori la Eternulon Kaj prikanti Vian nomon, ho Plejaltulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Rakonti matene pri Via boneco Kaj nokte pri Via fideleco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'Sur dekkorda instrumento kaj sur psaltero, Per solenaj sonoj de harpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'Ĉar Vi ĝojigis min, ho Eternulo, per Viaj agoj; La farojn de Viaj manoj mi prikantos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Kiel grandaj estas Viaj faroj, ho Eternulo! Tre profundaj estas Viaj pensoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Malklerulo ne scias, Kaj malsaĝulo tion ne komprenas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Kiam malvirtuloj verdestas kiel herbo Kaj ĉiuj malbonaguloj floras, Tio kondukas al ilia ekstermiĝo por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Kaj Vi estas alta eterne, ho Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Ĉar jen Viaj malamikoj, ho Eternulo, Jen Viaj malamikoj pereas, Diskuras ĉiuj malbonaguloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Sed mian kornon Vi altigas kiel la kornon de bubalo; Mi estas oleita per freŝa oleo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'Kaj mia okulo rigardas miajn malamikojn; Pri la malbonaguloj, miaj kontraŭuloj, aŭdas miaj oreloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Virtulo verdestas, kiel palmo, Staras alte, kiel cedro sur Lebanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Plantitaj en la domo de la Eternulo, Ili verdestas en la kortoj de nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Ili floras ankoraŭ en la maljuneco, Estas sukplenaj kaj freŝaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'Por sciigi, ke la Eternulo estas justa, Mia fortikaĵo, kaj ne ekzistas en Li maljusteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'La Eternulo reĝas; Li estas vestita de majesto; La Eternulo estas vestita kaj zonita de potenco; Kaj fortikigita estas la mondo, ke ĝi ne ŝanceliĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'De antikve estas fortika Via trono; Vi estas de eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Levas la riveroj, ho Eternulo, levas la riveroj sian voĉon, Levas la riveroj sian bruon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Pli ol la bruo de multego da akvo, Ol la potencaj ondoj de la maro, Potenca estas la Eternulo en la altaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Viaj leĝoj estas tre fidindaj; Via domo estas ornamita de sankteco, Ho Eternulo, por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Dio de venĝo, ho Eternulo, Dio de venĝo, aperu!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Leviĝu, Juĝanto de la tero; Redonu la meritaĵon al la fieruloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Kiel longe la malvirtuloj, ho Eternulo, Kiel longe la malvirtuloj triumfos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'Ili estas malhumilaj, parolas arogantaĵon; Fanfaronas ĉiuj malbonaguloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Vian popolon, ho Eternulo, ili premas, Kaj Vian heredon ili turmentas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Vidvinon kaj fremdulon ili mortigas, Kaj orfojn ili buĉas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'Kaj ili diras: La Eternulo ne vidas, Kaj la Dio de Jakob ne scias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Komprenu, senprudentuloj en la popolo; Kaj vi, malsaĝuloj, kiam vi saĝiĝos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Ĉu ne aŭdas Tiu, kiu aranĝis orelon? Ĉu ne vidas Tiu, kiu kreis okulon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Ĉu ne punas la ĝustiganto de la popoloj, Kiu instruas al homo scion?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'La Eternulo scias la pensojn de homo, Ke ili estas vantaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Bone estas al la homo, kiun Vi, ho Eternulo, ĝustigas, Kaj al kiu Vi instruas Vian leĝon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'Por trankviligi lin en la malbonaj tagoj, Ĝis estos pretigita la foso por la malvirtulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Ĉar la Eternulo ne forpuŝos Sian popolon, Kaj Sian heredon Li ne forlasos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'Ĉar juĝo revenos al vero, Kaj ĝin sekvos ĉiuj virtkoruloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Kiu helpas min kontraŭ malbonuloj? Kiu staras apud mi kontraŭ malbonaguloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Se la Eternulo ne estus mia helpanto, Mia animo preskaŭ kuŝus jam silenta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Kiam mi diris, ke mia piedo ŝanceliĝas, Via boneco, ho Eternulo, min subtenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Kiam mi havas interne multe da maltrankvilaj pensoj, Viaj konsoloj karesas mian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Ĉu aliĝos al Vi trono de maljusteco, Kiu aranĝas maljustaĵon en la nomo de la leĝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Ili sin armas kontraŭ la animo de virtulo, Kaj sangon senkulpan ili akuzas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Sed la Eternulo estos mia rifuĝejo; Kaj mia Dio estos la roko de mia ŝirmo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Kaj Li redonos al ili por iliaj malbonagoj, Kaj por ilia malboneco Li ilin ekstermos; Ilin ekstermos la Eternulo, nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Venu, ni kantu al la Eternulo; Ni ĝoje kriu al la rifuĝejo de nia helpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Ni venu antaŭ Lian vizaĝon kun glorado, Per psalmoj ni ĝoje kriu al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Ĉar granda Dio estas la Eternulo Kaj granda Reĝo super ĉiuj dioj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'Kiu havas en Sia mano la profundaĵojn de la tero, Kaj al kiu apartenas la altaĵoj de la montoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'Al kiu apartenas la maro, kaj Li ĝin faris, Kaj la sekteron Liaj manoj kreis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Venu, ni kliniĝu, ni ĵetu nin teren, Ni genuu antaŭ la Eternulo, nia Kreinto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Ĉar Li estas nia Dio, Kaj ni estas la popolo de Lia paŝtejo kaj la ŝafoj de Lia mano. Hodiaŭ, se vi aŭskultas Lian voĉon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'Ne obstinigu vian koron, kiel en Meriba, Kiel en la tago de Masa en la dezerto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'Kiam viaj patroj Min incitis, Esploris kaj vidis Mian faron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Kvardek jarojn Mi indignis kontraŭ tiu generacio, Kaj Mi diris: Ili estas popolo kun koro malĝusta, Kaj ili ne volas koni Miajn vojojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'Tial Mi ĵuris en Mia kolero, Ke ili ne venos en Mian ripozejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Kantu al la Eternulo novan kanton; Kantu al la Eternulo la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Kantu al la Eternulo, gloru Lian nomon, Proklamu de tago al tago Lian savon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Rakontu inter la popoloj Lian gloron, Inter ĉiuj gentoj Liajn miraklojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Ĉar la Eternulo estas granda kaj tre glorinda, Li estas timinda pli ol ĉiuj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Ĉar ĉiuj dioj de la popoloj estas nur idoloj; Sed la Eternulo kreis la ĉielon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Gloro kaj majesto estas antaŭ Li, Forto kaj beleco estas en Lia sanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Tributu al la Eternulo, familioj de la popoloj; Tributu al la Eternulo gloron kaj potencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Tributu al la Eternulo la honoron de Lia nomo; Alportu donacon kaj venu en Liajn kortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Kliniĝu al la Eternulo en sankta ornamo; Tremu antaŭ Li la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Diru inter la popoloj: La Eternulo reĝas, Kaj fortikigita estas la mondo, ke ĝi ne ŝanceliĝu; Li juĝas la popolojn en justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Ĝoju la ĉielo, kaj estu gaja la tero, Bruu la maro, kaj ĉio, kio ĝin plenigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Ĝoju la kampo, kaj ĉio, kio estas sur ĝi; Tiam kantu ĉiuj arboj de la arbaro');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'Antaŭ la Eternulo, ĉar Li venas, Ĉar Li venas, por juĝi la teron; Li juĝos la mondon kun justeco Kaj la popolojn kun Sia fideleco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'La Eternulo reĝas; ĝoju la tero; Estu gajaj la multaj insuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Nubo kaj mallumo estas ĉirkaŭ Li; Vero kaj justeco estas la fundamento de Lia trono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Fajro iras antaŭ Li, Kaj bruligas ĉirkaŭe Liajn malamikojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Liaj fulmoj lumigas la mondon; La tero vidas, kaj tremas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Montoj fandiĝas kiel vakso antaŭ la vizaĝo de la Eternulo, Antaŭ la vizaĝo de la Sinjoro de la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'La ĉielo rakontas Lian veron, Kaj ĉiuj popoloj vidas Lian gloron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Hontiĝu ĉiuj, kiuj servas al idoloj, Kiuj laŭdas sin pro diaĉoj. Kliniĝu antaŭ Li ĉiuj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Aŭdis kaj ekĝojis Cion, Kaj ektriumfis la filinoj de Jehuda Pro Viaj juĝoj, ho Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Ĉar Vi, ho Eternulo, estas Plejalta super la tuta tero, Vi tre alte leviĝis super ĉiuj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Amantoj de la Eternulo, malamu malbonon. Li gardas la animojn de Siaj fideluloj; Li savos ilin de la mano de malvirtuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Lumo verŝiĝas sur virtulon, Kaj ĝojo sur purkorulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Ĝoju, virtuloj, pro la Eternulo, Kaj gloru Lian sanktan nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Psalmo. Kantu al la Eternulo novan kanton, Ĉar miraklojn Li faris; Helpis Lin Lia dekstra mano kaj Lia sankta brako.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'La Eternulo aperigis Sian savon; Antaŭ la okuloj de la popoloj Li malkaŝis Sian justecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Li memoras Sian bonecon kaj Sian fidelecon al la domo de Izrael. Vidis ĉiuj finoj de la tero la helpon de nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Ĝoje kriu al la Eternulo la tuta tero; Kantu, gloru, kaj muziku.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Muziku al la Eternulo per harpo, Per harpo kaj per sonoj de psalmo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'Per trumpetoj kaj per sono de korno Ĝoje kriu antaŭ la Reĝo, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Bruu la maro, kaj ĉio, kio ĝin plenigas, La mondo kaj ĝiaj loĝantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'La riveroj plaŭdu per la manoj, La montoj kune kantu ĝoje,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'Antaŭ la Eternulo, ĉar Li venas, por juĝi la teron; Li juĝos la mondon kun justeco kaj la popolojn kun vereco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'La Eternulo reĝas, tremas la popoloj; Li sidas sur keruboj, ŝanceliĝas la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'La Eternulo estas granda en Cion, Kaj Li estas alte super ĉiuj popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Oni gloru Vian grandan kaj timindan nomon: Li estas sankta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Kaj la forton de la reĝo, kiu amas justecon, Vi fortikigis en praveco; Juĝon kaj justecon en Jakob Vi aranĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Altigu la Eternulon, nian Dion, Kaj kliniĝu antaŭ la benketo de Liaj piedoj: Li estas sankta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Moseo kaj Aaron estas inter Liaj pastroj, Kaj Samuel estas inter tiuj, kiuj vokas Lian nomon; Ili vokis al la Eternulo, kaj Li ilin aŭskultis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'El nuba kolono Li parolis al ili; Ili observis Liajn regulojn, kaj la leĝon, kiun Li donis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Ho Eternulo, nia Dio, Vi ilin aŭskultis; Vi estis por ili Dio pardonanta, kvankam venĝanto por iliaj faroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Altigu la Eternulon, nian Dion, Kaj kliniĝu antaŭ Lia sankta monto; Ĉar sankta estas la Eternulo, nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Psalmo de dankado. Ĝoje kriu al la Eternulo la tuta tero!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Servu al la Eternulo kun ĝojo, Venu antaŭ Lian vizaĝon kun kanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Sciu, ke la Eternulo estas Dio; Li nin kreis, kaj al Li ni apartenas, Lia popolo kaj ŝafoj de Lia paŝtejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Eniru en Liajn pordegojn kun dankado, En Liajn kortojn kun laŭdado. Gloru Lin, benu Lian nomon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Ĉar la Eternulo estas bona; Lia favorkoreco estas eterna, Kaj de generacio al generacio daŭras Lia fideleco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Psalmo de David. Bonecon kaj justecon mi prikantos; Al Vi, ho Eternulo, mi muzikos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Mi penas iri prudente la vojon de pieco; Kiam Vi venos al mi? Mi iras kun pura koro interne de mia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Mi ne metas antaŭ miajn okulojn malbonan aferon; Mi malamas farojn de malfideleco, Ili ne aliĝas al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Koro perversa foriĝu de mi; Malbonon mi ne volas koni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Kiu sekrete kalumnias sian proksimulon, tiun mi ekstermos; Kiu havas fieran okulon kaj malhumilan koron, tiun mi ne toleros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Miaj okuloj restas turnataj al la fideluloj de la tero, ke ili sidu kun mi; Kiu iras la vojon de pieco, tiu servu al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Ne loĝos interne de mia domo iu, kiu agas hipokrite; Kiu diras malveron, tiu ne staros antaŭ miaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Fervore mi ekstermos ĉiujn malvirtulojn de la lando, Por elradikigi el la urbo de la Eternulo ĉiujn krimulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Preĝo de mizerulo, kiam li perdas la fortojn kaj elverŝas antaŭ la Eternulo sian malĝojon. Ho Eternulo, aŭskultu mian preĝon; Kaj mia krio venu al Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Ne kaŝu antaŭ mi Vian vizaĝon en la tago de mia suferado; Klinu al mi Vian orelon; En la tago, kiam mi vokas, rapide aŭskultu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Ĉar pasis kiel fumo miaj tagoj, Kaj miaj ostoj ĉirkaŭbrulis kiel en forno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Falĉiĝis kiel herbo kaj sekiĝis mia koro, Ĉar mi forgesis manĝi mian panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'De la voĉo de mia plorado Algluiĝis miaj ostoj al mia karno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Mi similiĝis al pelikano en la dezerto, Mi fariĝis kiel noktuo en ruinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Mi ne dormas, Kaj mi estas kiel birdo solulo sur tegmento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Ĉiutage insultas min miaj malamikoj, Miaj mokantoj ĵuras per mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Ĉar cindron mi manĝis kiel panon, Kaj mian trinkaĵon mi miksis kun larmoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'Kaŭze de Via kolero kaj indigno; Ĉar Vi min levis kaj ĵetis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'Miaj tagoj malaperas kiel ombro, Kaj mi sekiĝas kiel herbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Sed Vi, ho Eternulo, restas eterne; Kaj la memoro pri Vi restas de generacio al generacio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Vi leviĝos, Vi korfavoros Cionon; Ĉar estas tempo por ĝin kompati, ĉar venis la tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Ĉar Viaj sklavoj ekamis ĝiajn ŝtonojn, Ĉarma estas por ili ĝia polvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'Kaj ektimos popoloj la nomon de la Eternulo, Kaj ĉiuj reĝoj de la tero Vian gloron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Ĉar la Eternulo rekonstruis Cionon, Kaj aperis en Sia gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'Li Sin turnis al la preĝo de la forlasitoj, Kaj ne forpuŝis ilian petegon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'Ĉi tio estos skribita por estontaj generacioj; Kaj rekreita popolo gloros la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Ĉar Li rigardis malsupren el Sia sankta altaĵo, El la ĉielo la Eternulo direktis rigardon al la tero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'Por aŭdi la ĝemon de malliberulo, Por liberigi la kondamnitajn al morto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'Por ke oni rakontu en Cion pri la nomo de la Eternulo Kaj en Jerusalem pri Lia gloro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'Kiam kolektiĝos kune la popoloj kaj regnoj, Por servi al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'Li lacigis en la vojo miajn fortojn, Li mallongigis miajn tagojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Mi diras: Ho mia Dio, ne forprenu min en la mezo de miaj tagoj, Vi, kies jaroj estas de generacio al generacio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'En antikveco Vi fondis la teron; Kaj la ĉielo estas la faro de Viaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Ili pereos, sed Vi restos; Kaj ĉiuj ili eluziĝos kiel vesto, Kiel veston Vi ilin ŝanĝos, kaj ili ŝanĝiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'Sed Vi restas la sama, Kaj Viaj jaroj ne finiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'La filoj de Viaj sklavoj restos, Kaj ilia semo fortikiĝos antaŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'De David. Benu, ho mia animo, la Eternulon, Kaj mia tuta internaĵo Lian sanktan nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Benu, ho mia animo, la Eternulon, Kaj ne forgesu ĉiujn Liajn bonfarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'Li pardonas ĉiujn viajn pekojn, Li sanigas ĉiujn viajn malsanojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'Li savas de la tombo vian vivon, Li kronas vin per boneco kaj favorkoreco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'Li satigas per bonaĵoj vian maljunan aĝon, Ke via juneco renoviĝas kiel ĉe aglo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'La Eternulo faras justecon kaj juĝon al ĉiuj prematoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Li sciigis Siajn vojojn al Moseo, Siajn farojn al la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Favorkora kaj kompatema estas la Eternulo, Longetolerema kaj tre bona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Ne eterne Li indignas, Kaj ne por ĉiam Li koleras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Ne laŭ niaj pekoj Li agis kun ni, Kaj ne laŭ niaj krimoj Li redonis al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Ĉar kiel alte estas la ĉielo super la tero, Tiel granda estas Lia boneco por tiuj, kiuj Lin timas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'Kiel malproksime estas la oriento de la okcidento, Tiel Li malproksimigis de ni niajn pekojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Kiel patro korfavoras filojn, Tiel la Eternulo korfavoras tiujn, kiuj Lin timas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Ĉar Li scias nian esencon; Li memoras, ke ni estas polvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'La tagoj de homo estas kiel herbo; Kiel floro de kampo, tiel li floras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Pasas super ĝi vento, kaj ĝi jam ne ekzistas; Kaj ĝia loko ĝin jam ne rekonas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Sed la boneco de la Eternulo daŭras eterne al tiuj, kiuj Lin timas, Kaj Lia bonfaremeco iras ĝis la pranepoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'Kiuj observas Lian interligon Kaj memoras Liajn ordonojn por ilin plenumi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'La Eternulo starigis en la ĉielo Sian tronon; Kaj Lia reĝeco regas ĉion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Benu la Eternulon Liaj anĝeloj, potencaj per sia forto, Kiuj plenumas Lian vorton, Por ke oni obeu la voĉon de Lia vorto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Benu la Eternulon ĉiuj Liaj ĉirkaŭantoj, Liaj servantoj, kiuj plenumas Lian volon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Benu la Eternulon ĉiuj Liaj kreitaĵoj, En ĉiuj lokoj de Lia regado. Benu, ho mia animo, la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Benu, ho mia animo, la Eternulon. Ho Eternulo, mia Dio, Vi estas tre granda, De majesto kaj beleco Vi estas vestita;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Vi, kiu estas ĉirkaŭkovrita de lumo kiel de vesto, Kiu sternas la ĉielon kiel tapiŝon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Kiu aranĝas sur la akvo Siajn ĉambrojn, Kiu faras la nubojn Lia veturilo; Kiu iras sur la flugiloj de la vento;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Kiu faras la ventojn Liaj senditoj, Flamantan fajron Liaj servantoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Kiu fondis la teron sur ĝiaj fundamentoj, Ke ĝi neniam ŝanceliĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'La abismon Vi kovris kiel per vesto, Sur la montoj staras akvo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'De Via minaco ĝi kuras, De la voĉo de Via tondro ĝi forrapidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'Ĝi leviĝas sur montojn, malleviĝas sur valojn, Al tiu loko, kiun Vi destinis por ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Vi faris limon, kiun ĝi ne superpaŝos, Por ke ĝi ne revenu por kovri la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Vi sendas fontojn al la riveroj, Kiuj iras inter montoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'Ili trinkigas ĉiujn kampajn bestojn; Sovaĝaj azenoj kvietigas sian soifon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Apud ili loĝas la birdoj ĉielaj, El inter la branĉoj ili sonigas sian voĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Vi trinkigas la montojn el Viaj ĉambroj; Per la produktoj de Viaj faroj satiĝas la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Vi kreskigas herbon por la bruto, Kaj verdaĵon, kiu servas al la homo, Por elirigi panon el la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'Kaj la vino gajigas la koron de la homo, La vizaĝo brilas de la oleo, Kaj la pano fortikigas la koron de la homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Satiĝas la arboj de la Eternulo, La cedroj de Lebanon, kiujn Li plantis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'Kaj tie nestas birdoj; Cikonio havas sian loĝejon sur abioj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'La altaj montoj estas por la ibeksoj, La rokoj estas rifuĝejo por la hirakoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Li aranĝis la lunon laŭ la partoj de tempo; La suno scias sian subiron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Vi sendas mallumon, kaj fariĝas nokto, Dum kiu vagas ĉiuj arbaraj bestoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'La leonidoj krias pri rabakiro, Por peti de Dio sian manĝaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Kiam leviĝas la suno, Ili sin kaŝas kaj kuŝiĝas en siaj loĝejoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Eliras homo por sia okupiĝo, Por sia laboro ĝis la vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Kiel multaj estas Viaj faroj, ho Eternulo! Ĉion Vi faris kun saĝo; La tero estas plena de Viaj faritaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Jen la maro, granda kaj vasta: Tie estas rampaĵoj sennombraj, Bestoj malgrandaj kaj grandaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Tie iras ŝipoj; Tie estas la levjatano, kiun Vi kreis, ke ĝi tie ludu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Ĉiuj ili atendas de Vi, Ke Vi donu al ili manĝon en ĝia tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Vi donas al ili, ili kolektas; Vi malfermas Vian manon, kaj ili satiĝas de bonaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Vi kaŝas Vian vizaĝon, tiam ili ektimas; Vi forprenas ilian spiriton, Tiam ili mortas kaj revenas al sia polvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Vi sendas Vian spiriton, tiam ili kreiĝas; Kaj Vi renovigas la vizaĝon de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Gloro al la Eternulo estu eterne; La Eternulo ĝoju pri Siaj faritaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Li ekrigardas la teron, kaj ĝi tremas; Li ektuŝas la montojn, kaj ili fumiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Mi kantados al la Eternulo, dum mi vivos; Mi muzikados al mia Dio, dum mi estos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Agrabla estu al Li mia meditado; Mi ĝojos pri la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Malaperu pekuloj de sur la tero, Kaj malvirtuloj ne plu ekzistu. Benu, ho mia animo, la Eternulon. Haleluja!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Gloru la Eternulon, voku Lian nomon; Sciigu inter la popoloj Liajn farojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Kantu al Li, muziku al Li; Parolu pri ĉiuj Liaj mirakloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Laŭdu Lian sanktan nomon; Ĝoju la koro de tiuj, kiuj serĉas la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Turnu vin al la Eternulo kaj al Lia potenco; Serĉu ĉiam Lian vizaĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Memoru Liajn miraklojn, kiujn Li faris, Liajn signomiraklojn kaj la juĝojn de Lia buŝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'Vi, semo de Abraham, Lia sklavo, Filoj de Jakob, Liaj elektitoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Li estas la Eternulo, nia Dio; Sur la tuta tero estas Liaj juĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Li memoras eterne Sian interligon, La vorton, kiun Li testamentis por mil generacioj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'Kiun Li interkonsentis kun Abraham Kaj ĵuris al Isaak.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'Li metis ĝin por Jakob kiel leĝon, Por Izrael kiel eternan interligon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'Dirante: Al vi Mi donos la landon Kanaanan Kiel vian parton heredan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Kiam ili estis malgrandnombraj, Malmultaj, kaj fremduloj en ĝi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'Kaj ili iradis de popolo al popolo, El unu regno al alia gento,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Tiam Li al neniu permesis premi ilin, Kaj Li punis pro ili reĝojn, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, 'Ne tuŝu Miajn sanktoleitojn, Kaj al Miaj profetoj ne faru malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Kaj Li sendis malsaton en la landon, Rompis ĉion, kio portis panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Li sendis antaŭ ili homon: Jozef estis vendita kiel sklavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'Oni enpremis liajn piedojn en katenojn, Fero ŝarĝis lian korpon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'Ĝis la tempo, kiam venis Lia vorto; La parolo de la Eternulo lin elprovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Reĝo sendis kaj malligis lin, Reganto super popoloj liberigis lin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Li faris lin sinjoro super lia domo Kaj reganto super lia tuta havo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'Ke li submetu al si liajn eminentulojn Kaj saĝigu liajn maljunulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Kaj Izrael venis en Egiptujon, Kaj Jakob enmigris en la landon de Ĥam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Kaj Li tre kreskigis Sian popolon, Kaj faris ĝin pli forta ol ĝiaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Li malĝustigis ilian koron, Ke ili ekmalamis Lian popolon, ekruzis kontraŭ Liaj sklavoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Li sendis Moseon, Sian sklavon, Kaj Aaronon, kiun Li elektis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Ili faris inter ili Liajn pruvosignojn Kaj miraklojn en la lando de Ĥam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Li sendis mallumon kaj mallumigis; Kaj ili ne atentis Liajn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Li ŝanĝis ilian akvon en sangon, Kaj senvivigis iliajn fiŝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Ilia tero eksvarmigis ranojn, En la ĉambroj de iliaj reĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Li diris, kaj venis fiinsektoj, Pedikoj en ĉiuj iliaj regionoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Antataŭ pluvo Li donis al ili hajlon, Flamantan fajron en ilia lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'Li batis iliajn vinbertrunkojn kaj iliajn figarbojn, Kaj rompis la arbojn en iliaj limoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Li diris, kaj venis akridoj kaj skaraboj sennombraj');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'Kaj formanĝis la tutan herbon en ilia lando Kaj formanĝis la produktojn de ilia tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Kaj Li mortigis ĉiujn unuenaskitojn en ilia lando, La komencaĵojn de ĉiuj iliaj fortoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Sed ilin Li elkondukis kun arĝento kaj oro, Kaj en iliaj triboj estis neniu kadukulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Ĝojis Egiptujo, kiam ili eliris, Ĉar atakis ĝin timo antaŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Li etendis nubon, kiel kovron; Kaj fajron, por ke ĝi lumu en la nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'Ili petis, kaj Li sendis koturnojn, Kaj per pano ĉiela Li ilin satigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Li malfermis rokon, Kaj ekfluis akvo kaj ekiris kiel rivero en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Ĉar Li memoris Sian sanktan vorton Al Abraham, Sia sklavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Kaj Li elkondukis Sian popolon en ĝojo, Siajn elektitojn kun kantado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'Kaj Li donis al ili la landojn de popoloj, Kaj la laboron de gentoj ili heredis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'Por ke ili plenumu Liajn leĝojn Kaj konservu Liajn instruojn. Haleluja!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Haleluja! Gloru la Eternulon, ĉar Li estas bona; Ĉar eterna estas Lia boneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Kiu eldiros la potencon de la Eternulo, Aŭdigos Lian tutan gloron?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Bone estas al tiuj, kiuj observas justecon, Kiuj agas bone en ĉiu tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Memoru min, ho Eternulo, pro favoro al Via popolo; Sendu al mi Vian savon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'Por ke mi vidu la bonstaton de Viaj elektitoj, Por ke mi ĝoju kun la ĝojo de Via popolo, Por ke mi triumfu kun Via heredo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Ni pekis kune kun niaj patroj, Ni malbonagis, ni malvirtis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Niaj patroj en Egiptujo ne komprenis Viajn miraklojn, Ne memoris Vian grandan bonecon; Kaj ili ribelis apud la maro, apud la Ruĝa Maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Sed Li savis ilin pro Sia nomo, Por montri Sian potencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Kaj Li ekkriis al la Ruĝa Maro, kaj ĝi elsekiĝis; Kaj Li kondukis ilin tra la abismoj, kiel tra la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'Kaj Li savis ilin el la mano de la malamanto, Kaj Li liberigis ilin en la mano de la malamiko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Kaj la akvo kovris iliajn kontraŭulojn; Eĉ unu el ili ne restis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Tiam ili ekkredis al Liaj vortoj, Ili ekkantis Lian gloron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Sed baldaŭ ili forgesis Liajn farojn, Ili ne fidis Lian konsilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'Ili fordonis sin al siaj kapricoj en la dezerto, Kaj ili incitis Dion en la stepo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'Kaj Li plenumis ilian deziron, Sed Li sendis pereon al iliaj animoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Ili enviis Moseon en la tendaro, Aaronon, sanktulon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'Malfermiĝis la tero kaj englutis Datanon, Kaj kovris la anaron de Abiram.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'Kaj ekbrulis fajro en ilia anaro, Flamo forbruligis la malvirtulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Ili faris bovidon ĉe Ĥoreb, Kaj adorkliniĝis antaŭ fandaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'Ili ŝanĝis sian honoron En bildon de bovo, kiu manĝas herbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Ili forgesis Dion, sian savanton, Kiu faris grandajn farojn en Egiptujo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'Miraklojn en la lando de Ĥam, Timindaĵojn apud la Ruĝa Maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Kaj Li decidis ekstermi ilin; Sed Moseo, Lia elektito, stariĝis antaŭ Li ĉe la fendo, Por forklini Lian koleregon, ke Li ilin ne ekstermu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Kaj ili malŝatis la dezirindan landon, Ili ne kredis al Lia vorto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'Ili murmuris en siaj tendoj, Kaj ne aŭskultis la voĉon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Tial Li ĵuris al ili per levo de Sia mano, Por faligi ilin en la dezerto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'Kaj por disfaligi ilian semon inter la popoloj, Kaj disĵeti ilin en la landojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Kaj ili aliĝis al Baal-Peor, Kaj manĝis oferricevojn de malvivuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'Kaj ili kolerigis Lin per siaj faroj; Kaj disvastiĝis inter ili epidemio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Kaj stariĝis Pineĥas kaj aranĝis juĝon; Kaj la epidemio haltis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'Kaj tio estas kalkulita al li kiel bonfaro, Por ĉiuj generacioj kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Kaj ili kolerigis Lin ĉe la akvo de Meriba, Kaj pro ili fariĝis malbono al Moseo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'Ĉar ili maldolĉigis lian spiriton, Kaj li eldiris ion nepripensitan per sia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Ili ne ekstermis la popolojn, Pri kiuj diris al ili la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'Sed ili miksiĝis kun la popoloj Kaj lernis iliajn farojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'Ili servis al iliaj idoloj, Kaj ĉi tiuj fariĝis reto por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Kaj ili oferdonis siajn filojn kaj filinojn al demonoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'Kaj ili verŝis senkulpan sangon, la sangon de siaj filoj kaj filinoj, Kiujn ili oferportis al la Kanaanaj idoloj; Kaj la tero malpuriĝis de sango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'Kaj ili malpuriĝis per siaj faroj, Kaj malĉastiĝis per siaj agoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Kaj ekflamis la kolero de la Eternulo kontraŭ Lia popolo, Kaj Li abomenis Sian heredon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'Kaj Li donis ilin en la manojn de idolanoj, Kaj iliaj malamantoj ekregis super ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'Kaj premis ilin iliaj malamikoj, Kaj sub la manoj de ĉi tiuj ili humiliĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Multajn fojojn Li ilin savis; Sed ili ribeladis per siaj entreprenoj, Kaj ili senfortiĝis pro sia krimeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Sed Li ekrigardis ilian suferon, Kiam Li aŭdis ilian kriadon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'Kaj Li rememoris Sian interligon kun ili, Kaj Li ekbedaŭris laŭ Sia granda favorkoreco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'Kaj Li aperigis kompaton por ili Ĉe ĉiuj iliaj malliberigintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Savu nin, ho Eternulo, nia Dio, Kaj kolektu nin el inter la popoloj, Por glori Vian sanktan nomon, Por triumfi pro Via gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Glorata estu la Eternulo, Dio de Izrael, de eterne ĝis eterne. Kaj la tuta popolo diru: Amen. Haleluja!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Gloru la Eternulon, ĉar Li estas bona; Ĉar eterna estas Lia boneco:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Diru la liberigitoj de la Eternulo, Kiujn Li liberigis el la mano de malamiko,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'Kiujn Li kolektis el la landoj, De oriento kaj okcidento, De nordo kaj de la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Ili vagis en la dezerto, laŭ vojo senviva, Urbon loĝatan ili ne trovis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Ili malsatis kaj soifis, Ilia animo en ili senfortiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Sed ili ekkriis al la Eternulo en sia sufero, Kaj Li liberigis ilin el ilia mizero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'Kaj Li kondukis ilin laŭ ĝusta vojo, Ke ili venu al urbo loĝata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Ili gloru la Eternulon por Lia boneco, Kaj por Liaj mirakloj antaŭ la homidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Ĉar Li satigis animon soifantan, Kaj animon malsatan Li plenigis per bonaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Ili sidis en mallumo kaj en ombro de morto, Katenitaj de mizero kaj fero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'Ĉar ili malobeis la vortojn de Dio Kaj malŝatis la decidon de la Plejaltulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Kaj Li frapis ilian koron per sufero; Ili falis, kaj neniu helpis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Sed ili ekkriis al la Eternulo en sia sufero, Kaj Li liberigis ilin el ilia mizero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Li eligis ilin el mallumo kaj ombro de morto, Kaj iliajn ligilojn Li disŝiris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Ili gloru la Eternulon por Lia boneco, Kaj por Liaj mirakloj antaŭ la homidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Ĉar Li rompis kuprajn pordojn, Kaj disbatis ferajn riglilojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'La malsaĝuloj suferis pro siaj pekaj vojoj Kaj pro siaj krimoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Ĉiujn manĝojn abomenis ilia animo, Kaj ili atingis la pordegon de la morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Sed ili ekkriis al la Eternulo en sia sufero, Kaj Li liberigis ilin el ilia mizero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Li sendis Sian vorton, Kaj Li sanigis ilin kaj savis ilin de la tombo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Ili gloru la Eternulon por Lia boneco, Kaj por Liaj mirakloj antaŭ la homidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'Kaj ili oferdonu dankajn oferojn, Kaj rakontu Liajn farojn kun kantado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Kiuj veturas per ŝipoj sur la maro, Kiuj komercas sur grandaj akvoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'Tiuj vidis la farojn de la Eternulo Kaj Liajn miraklojn en la profundo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Li diris, kaj aperis granda ventego Kaj alte levis ĝiajn ondojn:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Ili leviĝas ĝis la ĉielo, malleviĝas en la abismojn; Ilia animo konsumiĝas de sufero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Ili iras ĉirkaŭe kaj ŝanceliĝas kiel ebriulo, Kaj ilia tuta saĝeco malaperas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Sed ili ekkriis al la Eternulo en sia sufero, Kaj Li eligis ilin el ilia mizero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Li kvietigis la ventegon, Kaj ĝiaj ondoj silentiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'Kaj ili ekĝojis, kiam fariĝis silente; Kaj Li alkondukis ilin al la dezirata haveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Ili gloru la Eternulon por Lia boneco, Kaj por Liaj mirakloj antaŭ la homidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'Kaj ili altigu Lin en popola kunveno, Kaj en kunsido de plejaĝuloj ili Lin laŭdu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Li ŝanĝas riverojn en dezerton, Kaj fontojn de akvo en sekaĵon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'Fruktoportan teron en salan dezerton, Pro la malboneco de ĝiaj loĝantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Li ŝanĝas dezerton en lagon, Kaj sekan teron en fontojn de akvo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'Kaj Li loĝigas tie malsatulojn, Kaj ili konstruas urbon loĝatan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'Kaj ili prisemas kampojn, Plantas vinberujojn, kaj ricevas fruktojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Kaj Li ilin benas, kaj ili tre multiĝas, Kaj brutoj ne mankas al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Kaj kiam ili estas tre malmultaj kaj malfortaj Pro la premanta malbono kaj mizero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'Li verŝas honton sur eminentulojn, Kaj erarvagigas ilin en dezerto senvoja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'Malriĉulon Li altigas el mizero, Kaj kreas familiojn kiel ŝafojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'La virtuloj tion vidas, kaj ĝojas; Kaj ĉia malboneco fermas sian buŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Kiu estas saĝa, tiu tion observu, Kaj oni komprenu la favoraĵojn de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Kanto. Psalmo de David. Fortika estas mia koro, ho Dio; Mi kantos kaj gloros kun mia honoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Vekiĝu, psaltero kaj harpo; Mi vekos la matenan ĉielruĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Mi gloros Vin, ho Eternulo, inter la popoloj; Kaj mi prikantos Vin inter la gentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Ĉar granda ĝis super la ĉielo estas Via boneco, Kaj ĝis la nuboj estas Via vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Altiĝu super la ĉielo, ho Dio; Kaj Via gloro estu super la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Por ke liberiĝu viaj amatoj, Helpu per Via dekstra mano, kaj aŭskultu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Dio diris en Sia sanktejo: Mi triumfos; Mi dividos Ŝeĥemon, kaj la valon Sukot Mi mezuros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Al Mi apartenas Gilead, al Mi apartenas Manase; Efraim estas la forto de Mia kapo, Jehuda estas Mia sceptro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Moab estas Mia lavopelvo; Sur Edomon Mi ĵetos Mian ŝuon; Super Filiŝtujo Mi triumfe krios.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Kiu enkondukos min en fortikigitan urbon? Kiu alkondukos min ĝis Edom?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Ĉu ne Vi, ho Dio, forlasis nin? Vi ne eliras, ho Dio, kun niaj militistaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Donu al ni helpon kontraŭ la malamiko; Vanta estas helpo de homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Kun Dio ni faros heroaĵojn; Kaj Li dispremos niajn malamikojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Al la ĥorestro. Psalmo de David. Ho Dio, mia gloro, ne silentu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Ĉar buŝon malvirtan kaj buŝon malican ili malfermis kontraŭ mi, Ili parolas kun mi per mensogema lango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'Per vortoj de malamo ili min ĉirkaŭis, Kaj ili militas kontraŭ mi sen mia kulpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Por mia amo ili min malamas; Sed mi preĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'Ili pagas al mi malbonon por bono Kaj malamon por mia amo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Metu malvirtulon super lin; Kaj kontraŭulo stariĝu ĉe lia dekstra mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Kiam li estos juĝata, li eliru kulpa; Kaj lia preĝo estu peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Liaj tagoj estu malmultaj; Lian oficon ricevu alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Liaj infanoj estu orfoj, Kaj lia edzino estu vidvino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Liaj infanoj vagadu, Kaj ili petu kaj serĉu apud siaj ruinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Kreditoro forprenu ĉion, kion li havas; Kaj fremduloj disrabu lian laboron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Neniu faru al li ion bonan; Kaj ne troviĝu kompatanto por liaj orfoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Lia idaro estu kondamnita al ekstermo; En la dua generacio elviŝiĝu ilia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'La malbonago de liaj patroj rememoriĝu al la Eternulo, Kaj la peko de lia patrino ne elviŝiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Ili estu ĉiam antaŭ la Eternulo, Kaj Li ekstermu la memoron pri ili de sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Pro tio, ke li ne memoris fari bonfarojn, Kaj ke li persekutis mizerulon kaj malriĉulon kaj korsuferanton, Por lin mortigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Li amis malbenon, kaj ĝi venis sur lin; Li ne volis benon, kaj ĝi malproksimiĝis de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Li metis sur sin malbenon, kiel veston; Kaj ĝi penetris en lian internon, kiel akvo, Kaj en liajn ostojn, kiel oleo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Ĝi estu por li kiel vesto, per kiu li sin kovras, Kaj kiel zono, kiun li ĉiam portas ĉirkaŭ si.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Tia estas de la Eternulo la agado kontraŭ miaj kontraŭuloj, Kaj kontraŭ tiuj, kiuj parolas malbonon kontraŭ mia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Kaj Vi, ho Eternulo, mia Sinjoro, agu kun mi pro Via nomo; Ĉar bona estas Via favorkoreco, savu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Ĉar mi estas malriĉulo kaj mizerulo, Kaj mia koro estas rompita en mia interno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Kiel ombro longiĝanta mi malaperas; Oni forskuas min kiel akridon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Miaj genuoj senfortiĝis de fastado, Kaj mia karno perdis la grason.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Kaj mi fariĝis mokataĵo por ili; Kiam ili vidas min, ili balancas sian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Helpu min, ho Eternulo, mia Dio; Savu min laŭ Via boneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'Kaj oni sciu, ke tio estas Via mano; Ke Vi, ho Eternulo, tion faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Ili malbenas, sed Vi benu; Ili leviĝis, sed ili estos hontigitaj, kaj Via sklavo ĝojos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Miaj kontraŭuloj kovriĝu per malhonoro, Kaj ili envolviĝu en sian honton kiel en veston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Mi forte gloros la Eternulon per mia buŝo, Kaj meze de multaj homoj mi Lin laŭdos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'Ĉar Li staras ĉe la dekstra flanko de malriĉulo, Por savi lin de tiuj, kiuj juĝas lian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Psalmo de David. La Eternulo diris al mia sinjoro: Sidu dekstre de Mi, Ĝis Mi faros viajn malamikojn benketo por viaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'La sceptron de via potenco la Eternulo sendos el Cion: Regu inter viaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'En la tago de via potenco via popolo volonte sin donas al vi en sankta ornamo. De la komenco de matenruĝo aliĝas al vi la roso de via junularo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'La Eternulo ĵuris, kaj ne pentos; Vi estas pastro por ĉiam, Laŭ la maniero de Melkicedek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'La Sinjoro ĉe via dekstra flanko Frapas reĝojn en la tago de Sia kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Li juĝos inter la popoloj, inter plene da kadavroj; Li frakasos la ĉefon de granda lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Li trinkos el rivero sur la vojo; Tial li levos la kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Haleluja! Mi gloras la Eternulon per mia tuta koro, En rondo de piuloj kaj en kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Grandaj estas la faroj de la Eternulo, Serĉataj de ĉiuj, kiuj ilin amas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Bela kaj majesta estas Lia verko, Kaj Lia justeco restas eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Memorindaj Li faris Siajn miraklojn; Kompatema kaj favorkora estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Li donas manĝon al tiuj, kiuj Lin timas; Li memoras eterne Sian interligon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'La potencon de Siaj fortoj Li aperigis al Sia popolo, Doninte al ili la heredon de gentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'La faroj de Liaj manoj estas vero kaj justeco; Perfektaj estas ĉiuj Liaj ordonoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'Ili estas fortikaj por eterne, Faritaj per vero kaj honesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Liberigon Li sendis al Sia popolo; Li aranĝis por ĉiam Sian interligon. Sankta kaj respektinda estas Lia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Komenco de saĝeco estas timo antaŭ la Eternulo; Bonan prudenton havas ĉiuj plenumantoj. Lia gloro restas eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Haleluja! Bone estas al la homo, kiu timas la Eternulon Kaj tre amas Liajn ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Forta sur la tero estos lia semo; La gento de virtuloj estos benita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Bonstato kaj riĉeco estas en lia domo; Kaj lia justeco restas eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'En mallumo leviĝas lumo por la virtulo. Li estas kompatema, favorkora, kaj justa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Bone estas al la homo, kiu kompatas kaj pruntedonas, Kiu pesas siajn farojn per justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Ĉar neniam li falos; Virtulo estos memorata eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Malbonan famon li ne timos; Fortika estas lia koro, ĝi fidas la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Senŝanceliĝa estas lia koro; Li ne timas, ĝis li vidas la pereon de siaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Li ŝutas kaj donas al la malriĉuloj; Lia justeco restas eterne, Lia korno altiĝos en honoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'La malvirtulo vidas kaj ĉagreniĝas, Kunfrapas la dentojn kaj konsumiĝas. La deziro de malvirtuloj pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Haleluja! Gloru, sklavoj de la Eternulo, Gloru la nomon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'La nomo de la Eternulo estu benata De nun kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'De la leviĝejo de la suno ĝis ĝia malleviĝejo Estas glorata la nomo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Alte super ĉiuj popoloj estas la Eternulo; Super la ĉielo estas Lia gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Kiu estas kiel la Eternulo, nia Dio, Kiu sidas alte,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'Kiu kliniĝas por rigardi La ĉielon kaj la teron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Kiu el la polvo restarigas mizerulon, El la koto levas malriĉulon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'Por sidigi lin kun eminentuloj, Kun la eminentuloj de lia popolo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'Li donas familion al senfruktulino, Kaj faras ŝin ĝoja patrino de infanoj. Haleluja!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Kiam Izrael eliris el Egiptujo, La domo de Jakob el fremda popolo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'Tiam Jehuda fariĝis Lia sanktaĵo, Izrael Lia regno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'La maro vidis kaj forkuris, Jordan turniĝis malantaŭen;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'La montoj saltis kiel ŝafoj, La montetoj kiel ŝafidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Kio estas al vi, ho maro, ke vi forkuris? Jordan, kial vi turniĝis malantaŭen?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Montoj, kial vi saltas kiel ŝafoj, Montetoj, kiel ŝafidoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Antaŭ la Sinjoro tremu, ho tero, Antaŭ la Dio de Jakob,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'Kiu ŝanĝas rokon en lagon da akvo, Graniton en akvodonan fonton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Ne al ni, ho Eternulo, ne al ni, Sed al Via nomo donu honoron, Pro Via favorkoreco, pro Via vereco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Kial devas diri la popoloj: Kie do estas ilia Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Sed nia Dio estas en la ĉielo; Ĉion, kion Li deziras, Li faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Iliaj idoloj estas arĝento kaj oro, Faritaĵo de homaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Buŝon ili havas, sed ne parolas; Okulojn ili havas, sed ne vidas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'Orelojn ili havas, sed ne aŭdas; Nazon ili havas, sed ne flaras;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'Manojn ili havas, sed ne palpas; Piedojn ili havas, sed ne iras; Ili ne donas sonon per sia gorĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Kiel ili, tiel estos iliaj farantoj, Ĉiuj, kiuj ilin fidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Ho Izrael, fidu la Eternulon; Li estas ilia helpo kaj ŝildo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Ho domo de Aaron, fidu la Eternulon; Li estas ilia helpo kaj ŝildo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Ho timantoj de la Eternulo, fidu la Eternulon; Li estas ilia helpo kaj ŝildo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'La Eternulo nin memoras, Li benas, Li benas la domon de Izrael, Li benas la domon de Aaron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Li benas la timantojn de la Eternulo, La malgrandajn kaj la grandajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'La Eternulo vin multigu, Vin kaj viajn infanojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Vi estas benitaj de la Eternulo, Kiu faris la ĉielon kaj la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'La ĉielo estas ĉielo de la Eternulo, Sed la teron Li donis al la homidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Ne la mortintoj gloros la Eternulon, Kaj ne tiuj, kiuj foriris en la silentejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Sed ni benos la Eternulon De nun kaj eterne. Haleluja!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Mi amas, ke la Eternulo aŭdas mian voĉon Kaj mian petegon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'Ke Li klinis Sian orelon al mi; Kaj en miaj tagoj mi Lin vokos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Ĉirkaŭis min la ondoj de la morto, Kaj turmentoj de Ŝeol min trafis; Suferon kaj ĉagrenon mi trovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Sed la nomon de la Eternulo mi vokis: Ho Eternulo, savu mian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Favorkora estas la Eternulo kaj justa, Kaj nia Dio estas kompatema.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'La Eternulo gardas la simplanimulojn; Mi estis en mizero, kaj Li min savis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Revenu, ho mia animo, al via trankvileco, Ĉar la Eternulo faris al vi bonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Ĉar Vi savis mian animon de la morto, Miajn okulojn de larmoj, Miajn piedojn de falpuŝiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Mi irados antaŭ la Eternulo En la lando de la vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Kun kredo mi diris: Mi estas tre afliktita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Mi diris en mia konfuziĝo: Ĉu homo mensogas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Kion mi redonu al la Eternulo Por ĉiuj Liaj bonfaroj al mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Mi levos la pokalon de savo, Kaj mi vokos la nomon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Miajn promesojn al la Eternulo mi plenumos Antaŭ Lia tuta popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Grandvalora en la okuloj de la Eternulo Estas la morto de Liaj fideluloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'Ho Eternulo, mi ja estas Via sklavo, Mi estas Via sklavo, filo de Via sklavino; Vi disigis miajn ligilojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Al Vi mi oferdonos dankan oferon, Kaj la nomon de la Eternulo mi vokos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Miajn promesojn al la Eternulo mi plenumos Antaŭ Lia tuta popolo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'En la kortoj de la domo de la Eternulo, Interne de vi, ho Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Haleluja! Gloru la Eternulon ĉiuj popoloj, Laŭdu Lin ĉiuj gentoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Ĉar granda estas Lia boneco al ni, Kaj la vero de la Eternulo restas eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Haleluja! Gloru la Eternulon, ĉar Li estas bona; Ĉar eterna estas Lia boneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Izrael diru, Ke eterna estas Lia boneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'La domo de Aaron diru, Ke eterna estas Lia boneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'La timantoj de la Eternulo diru, Ke eterna estas Lia boneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'El premateco mi vokis al la Eternulo, Kaj per liberigo respondis al mi la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'La Eternulo estas kun mi, mi ne timas; Kion faros al mi homo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'La Eternulo estas kun mi, kiel mia helpanto; Kaj mi triumfos super miaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Pli bone estas fidi la Eternulon, Ol fidi homon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Pli bone estas fidi la Eternulon, Ol fidi eminentulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Ĉiuj popoloj min ĉirkaŭis, Sed per la nomo de la Eternulo mi ilin disbatos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Ili ĉirkaŭis min de ĉiuj flankoj, Sed per la nomo de la Eternulo mi ilin disbatos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Ili ĉirkaŭis min kiel abeloj, Sed ili estingiĝas, kiel fajro en dornoj; Per la nomo de la Eternulo mi ilin disbatos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Oni min puŝis, ke mi falu; Sed la Eternulo min helpis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'La Eternulo estas mia forto kaj mia kanto, Kaj Li fariĝis mia savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'La voĉo de triumfo kaj de saviĝo sonas en la tendoj de la virtuloj: La dekstra mano de la Eternulo faras heroaĵojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'La dekstra mano de la Eternulo estas alte, La dekstra mano de la Eternulo faras heroaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Mi ne mortos, sed mi vivos, Kaj mi rakontos la farojn de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Per forta puno punadis min la Eternulo, Sed al la morto Li min ne donis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Malfermu al mi la pordegojn de la vero; Mi iros tra ili, mi gloros la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Jen estas la pordego de la Eternulo; Virtuloj iras tra ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Mi dankas Vin, Ĉar Vi aŭskultis min kaj fariĝis mia savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Ŝtono, kiun malŝatis la konstruantoj, Fariĝis ŝtono bazangula.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'De la Eternulo ĉi tio fariĝis, Ĝi estas miraklo en niaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Ĉi tiun tagon faris la Eternulo; Ni ĝoju kaj gajiĝu en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Ho Eternulo, helpu! Ho Eternulo, sukcesigu!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Estu benata tiu, kiu venas en la nomo de la Eternulo! Ni benas vin el la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'La Eternulo estas Dio, kaj Li lumas al ni. Aranĝu la festan procesion kun branĉoj ĝis la kornoj de la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Vi estas mia Dio, kaj mi Vin gloras; Mia Dio, Vin mi altigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Gloru la Eternulon, ĉar Li estas bona; Ĉar eterna estas Lia boneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Bone estas al tiuj, kies vojo estas senmakula, Kiuj iras laŭ la leĝo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Bone estas al tiuj, kiuj plenumas Liajn decidojn, Kiuj serĉas Lin per la tuta koro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'Ili ne faras malbonagon, Ili iras laŭ Liaj vojoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Vi ordonis al ni, Forte observi Viajn leĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Ho, estu fortikaj miaj vojoj, Ke mi observu Viajn leĝojn!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Tiam mi ne bezonos honti, Kiam mi atentos ĉiujn Viajn ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Mi gloros Vin el pura koro, Lernante la juĝojn de Via justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Viajn leĝojn mi observos; Ne forlasu min tute.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Per kio junulo povas purigi sian vojon? Per plenumado laŭ Viaj vortoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Per mia tuta koro mi Vin serĉas; Ne lasu min deflankiĝi de Viaj ordonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'En mia koro mi konservas Vian diron, Por ke mi ne peku antaŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Benata Vi estas, ho Eternulo; Instruu al mi Viajn leĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Per miaj lipoj mi rakontas Ĉiujn decidojn de Via buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Pri la vojo de Viaj leĝoj mi ĝojas, Kiel pri granda riĉeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Pri Viaj ordonoj mi meditas, Kaj mi rigardas Viajn vojojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Mi havas plezuron de Viaj leĝoj, Mi ne forgesas Vian vorton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Bonfaru al Via sklavo, Ke mi vivu kaj plenumu Vian vorton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Malfermu miajn okulojn, Ke mi vidu miraklojn de Via instruo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Migranto mi estas sur la tero; Ne kaŝu antaŭ mi Viajn ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Elturmentiĝis mia animo De senĉesa sintirado al Viaj juĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Vi humiligas la malbenitajn fierulojn, Kiuj dekliniĝas de Viaj ordonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Forigu de mi honton kaj malhonoron, Ĉar mi observas Viajn decidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Eĉ kiam sidas eminentuloj kaj parolas kontraŭ mi, Via sklavo meditas pri Viaj leĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Viaj decidoj estas mia plezuro, Miaj konsilantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Mia animo algluiĝis al la polvo; Vivigu min laŭ Via vorto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Mi raportis pri miaj vojoj, kaj Vi aŭskultis min; Instruu al mi Viajn leĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Komprenigu al mi la vojon de Viaj ordonoj; Kaj mi meditos pri Viaj mirakloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Konsumiĝis mia animo pro malĝojo; Restarigu min laŭ Via vorto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'La vojon de malvero deturnu de mi, Kaj donacu al mi Vian instruon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'La vojon de la vero mi elektis, Mi sopiris al Viaj leĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Mi alkroĉiĝis al Viaj ordonoj; Ho Eternulo, ne hontigu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Mi kuras laŭ la vojo de Viaj leĝoj, Ĉar Vi larĝigas mian koron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Montru al mi, ho Eternulo, la vojon de Viaj leĝoj, Kaj mi ĝin sekvos ĝis la fino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Komprenigu al mi, kaj mi sekvos Vian instruon, Kaj mi konservos ĝin per la tuta koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Irigu min sur la vojeto de Viaj ordonoj, Ĉar en ĝi mi havas plezuron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Klinu mian koron al Viaj leĝoj, Sed ne al profito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Deturnu miajn okulojn, ke ili ne rigardu falsaĵon; Vivigu min per Viaj vojoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Plenumu al Via sklavo Vian diron, Kiu koncernas respekton por Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Forigu mian malhonoron, kiun mi timas; Ĉar Viaj juĝoj estas bonaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Jen mi deziregas Viajn ordonojn; Per Via justeco vivigu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Kaj venu al mi Viaj favoroj, ho Eternulo, Via helpo, konforme al Via vorto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'Ke mi povu doni respondon al mia insultanto; Ĉar mi fidas Vian vorton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'Ne forprenu tute de mia buŝo la vorton de vero, Ĉar mi esperas al Viaj juĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Kaj mi konservos Vian instruon Ĉiam kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'Kaj mi iros en libereco, Ĉar mi serĉas Viajn ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Kaj mi parolos pri Viaj leĝoj antaŭ reĝoj, Kaj mi ne hontos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Kaj mi havos plezuron de Viaj ordonoj, Kiujn mi amas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'Kaj mi etendos miajn manojn al Viaj ordonoj, kiujn mi amas, Kaj mi meditos pri Viaj leĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Rememoru la vorton al Via sklavo, Pri kio Vi min esperigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Ĉi tio estas mia konsolo en mia mizero, Ke Via vorto min revivigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Fieruloj tre forte min mokas, Sed de Via instruo mi ne dekliniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Mi rememoras Viajn juĝojn de tempoj tre antikvaj, ho Eternulo, Kaj mi konsoliĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Flama furiozo min kaptas pro la malvirtuloj, Kiuj forlasas Vian leĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Viaj leĝoj estas por mi kantoj En la domo de mia migrado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Mi rememoras en la nokto Vian nomon, ho Eternulo, Kaj mi plenumas Vian instruon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Tio fariĝis al mi, Ĉar mi observas Viajn ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Mi diris: Mia sortaĵo estas, ho Eternulo, Plenumi Viajn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Mi petegas antaŭ Vi per la tuta koro: Korfavoru min, konforme al Via vorto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Mi esploris miajn vojojn Kaj direktis miajn paŝojn al Viaj leĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Mi rapidas kaj ne prokrastas, Por plenumi Viajn ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Retoj de malvirtuloj min ĉirkaŭis; Sed Vian instruon mi ne forgesis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'En la mezo de la nokto mi leviĝas, Por glori Vin por Viaj justaj juĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Mi estas kamarado por ĉiuj, Kiuj Vin timas kaj kiuj observas Viajn ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'De Via boneco, ho Eternulo, la tero estas plena; Instruu al mi Viajn leĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Bonon Vi faris al Via sklavo, ho Eternulo, Konforme al Via vorto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Bonajn morojn kaj scion instruu al mi, Ĉar al Viaj ordonoj mi kredas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Antaŭ ol mi suferis, mi erarvagis, Sed nun mi observas Vian vorton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Vi estas bona kaj bonfara; Instruu al mi Viajn leĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Fieruloj plektis mensogon pri mi; Sed mi per la tuta koro konservas Viajn ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Grasiĝis kiel sebo ilia koro; Sed mi havas plezuron de Via instruo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Bone estas al mi, ke mi suferis, Por ke mi lernu Viajn leĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Pli bona estas por mi la instruo de Via buŝo, Ol miloj da oreroj kaj arĝenteroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Viaj manoj min kreis kaj fortikigis; Prudentigu min, kaj mi lernu Viajn ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Viaj timantoj min vidos kaj ĝojos, Ĉar mi fidis Vian vorton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Mi scias, ho Eternulo, ke Viaj juĝoj estas justaj, Kaj ke Vi juste min suferigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Via boneco estu do mia konsolo, Konforme al Via vorto al Via sklavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Venu sur min Via favorkoreco, ke mi vivu; Ĉar Via instruo estas mia plezuro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Hontiĝu la fieruloj, ĉar maljuste ili min premis; Mi meditos pri Viaj ordonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Turniĝu al mi Viaj timantoj Kaj la konantoj de Viaj leĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Mia koro estu ĝusta, laŭ Viaj leĝoj, Por ke mi ne hontiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Mia animo avidas Vian savon; Vian vorton mi fidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Miaj okuloj avidas Vian vorton, dirante: Kiam Vi min konsolos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Ĉar mi fariĝis kiel felsako en fumo; Sed Viajn leĝojn mi ne forgesas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Kiom estos la tagoj de Via sklavo? Kiam Vi faros juĝon super miaj persekutantoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Fosojn fosis al mi la fieruloj, Kontraŭe al Viaj leĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Ĉiuj Viaj ordonoj estas vero; Maljuste oni min persekutas; helpu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Oni preskaŭ pereigis min de sur la tero, Sed mi ne forlasis Viajn ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Laŭ Via boneco vivigu min, Kaj mi observos la ordonojn de Via buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Por eterne, ho Eternulo, Via vorto staras forte en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Por ĉiuj generacioj restas Via vero; Vi fortikigis la teron, kaj ĝi staras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Laŭ Viaj leĝoj ĉio nun staras, Ĉar ĉio estas Viaj sklavoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Se Via instruo ne estus mia konsolo, Mi pereus en mia mizero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Neniam mi forgesos Viajn ordonojn, Ĉar per ili Vi min vivigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Al Vi mi apartenas; Helpu min, ĉar mi serĉas Viajn ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Pri mi embuskis malvirtuloj, por min pereigi; Sed mi studas Viajn leĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Ĉe ĉiu afero mi vidis finon; Sed Via ordono estas tre vasta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Kiel mi amas Vian instruon! La tutan tagon mi meditas pri ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Via ordono faras min pli saĝa ol miaj malamikoj, Ĉar ĝi restas al mi por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Mi fariĝis pli saĝa, ol ĉiuj miaj instruantoj, Ĉar Viaj leĝoj estas mia tuta meditado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Mi estas pli scianta ol maljunuloj, Ĉar Viajn ordonojn mi konservas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'De ĉiu malbona vojo mi detenas mian piedon, Por plenumi Vian vorton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'De Viaj decidoj mi ne dekliniĝas, Ĉar Vi min gvidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Kiel dolĉa estas por mia palato Via vorto! Pli ol mielo por mia buŝo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'De Viaj ordonoj mi prudentiĝas; Tial mi malamas ĉiun vojon de malvero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Via vorto estas lumilo por miaj piedoj, Kaj lumo por mia vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Mi ĵuris, kaj mi plenumos: Observi Viajn justajn decidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Mi estas tre senfortigita, ho Eternulo; Vivigu min, konforme al Via vorto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'La oferdono de mia buŝo plaĉu al Vi, ho Eternulo, Kaj pri Viaj decidoj instruu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Mia animo estas ĉiam en mia mano, Sed Vian instruon mi ne forgesas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'La malvirtuloj metis reton por mi; Sed de Viaj ordonoj mi ne dekliniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Mi heredigis al mi Viajn ordonojn por ĉiam, Ĉar ili estas la ĝojo de mia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Mi klinis mian koron, Por plenumi Viajn leĝojn eterne ĝis la fino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Skeptikulojn mi malamas, Sed Vian instruon mi amas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Vi estas mia ŝirmo kaj ŝildo; Vian vorton mi fidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Foriĝu de mi, malbonagantoj; Mi observos la ordonojn de mia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Subtenu min laŭ Via diro, ke mi vivu; Kaj ne hontigu min pri mia espero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Fortikigu min, ke mi saviĝu, Kaj mi ĉiam havos plezuron de Viaj leĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Vi forpuŝas ĉiujn, kiuj dekliniĝas de Viaj leĝoj, Ĉar ilia falsaĵo estas mensoga.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Kiel skorion Vi forĵetas ĉiujn malvirtulojn sur la tero; Tial mi amas Viajn decidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'De Via teruro tremas mia karno, Kaj Viajn juĝojn mi timas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'AIN. Mi faris juĝon kaj justecon; Ne transdonu min al miaj premantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Garantie liberigu Vian sklavon por bono, Por ke fieruloj min ne premu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Miaj okuloj sopiras Vian helpon Kaj Vian justan vorton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Agu kun Via sklavo laŭ Via boneco, Kaj Viajn leĝojn instruu al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Mi estas Via sklavo; Klerigu min, ke mi sciu Viajn decidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Estas tempo, ke la Eternulo agu: Ili rompis Vian leĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Tial mi amas Viajn ordonojn Pli ol oron, eĉ ol puran oron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Tial mi estimas ĉiujn Viajn ordonojn, Ĉiun vojon de malvero mi malamas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Mirindaj estas Viaj decidoj; Tial mia animo ilin konservas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Malkaŝo de Via vorto klerigas, Ĝi prudentigas simplanimulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Mi malfermas mian buŝon kaj enspiras, Ĉar mi deziregas Viajn ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Turnu Vin al mi kaj korfavoru min, Kiel Vi agas kun la amantoj de Via nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Direktu miajn paŝojn laŭ Via promeso; Kaj nenia malhonesteco ekregu super mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Liberigu min de homa premado; Kaj mi observos Viajn ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Lumu per Via vizaĝo sur Vian sklavon, Kaj instruu al mi Viajn leĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Torentojn da akvo elverŝas miaj okuloj, Pro tio, ke oni ne plenumas Vian instruon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Justulo Vi estas, ho Eternulo, Kaj justaj estas Viaj juĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Vi aperigis Viajn decidojn Kun justeco kaj plena vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Elturmentis min mia fervoro, Ĉar miaj malamikoj forgesis Viajn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Tre pura estas Via vorto, Kaj Via sklavo ĝin amas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Mi estas malgranda kaj malestimata; Sed Viajn ordonojn mi ne forgesas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Via justeco estas justeco eterna, Kaj Via instruo estas vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Sufero kaj mizero min trafis; Sed Viaj ordonoj estas mia plezuro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'La justeco de Viaj decidoj estas eterna; Klerigu min, por ke mi vivu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Mi vokas el la tuta koro; aŭskultu min, ho Eternulo; Mi plenumos Viajn leĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Mi vokas al Vi; savu min, Kaj mi konservos Viajn decidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Antaŭ la matenruĝo mi vokas; Vian vorton mi fidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Antaŭ la noktaj gardopartoj miaj okuloj vekiĝas, Por ke mi meditu pri Via vorto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Mian voĉon aŭskultu, laŭ Via boneco, ho Eternulo; Laŭ Via justeco lasu min vivi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Alproksimiĝas malicaj persekutantoj; Malproksimaj ili estas de Via leĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Proksima Vi estas, ho Eternulo; Kaj ĉiuj Viaj ordonoj estas vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'De longe mi scias pri Viaj decidoj, Ke Vi fiksis ilin por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Rigardu mian mizeron, kaj liberigu min, Ĉar Vian instruon mi ne forgesis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Defendu mian aferon, kaj liberigu min; Laŭ Via vorto lasu min vivi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Malproksima de malvirtuloj estas savo, Ĉar ili ne ŝatas Viajn leĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Via favorkoreco estas granda, ho Eternulo; Laŭ Via justeco lasu min vivi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Multaj estas miaj persekutantoj kaj premantoj, Sed de Viaj decidoj mi ne dekliniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Mi vidis perfidulojn, kaj mi ilin abomenis, Ĉar Vian vorton ili ne observis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Rigardu, mi amas Viajn ordonojn; Ho Eternulo, laŭ Via boneco lasu min vivi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'La esenco de Via vorto estas vero, Kaj eterna estas ĉiu juĝo de Via justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Princoj persekutas min senkaŭze; Sed Vian vorton timas mia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Mi ĝojas pri Via vorto, Kiel ricevinto de granda akiro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Malveron mi malamas kaj abomenas; Vian instruon mi amas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Sepfoje ĉiutage mi Vin gloras Por Viaj justaj juĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Grandan pacon havas la amantoj de Via instruo; Kaj ili ne falpuŝiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Mi atendas Vian savon, ho Eternulo, Viajn ordonojn mi plenumas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Mia animo observas Viajn decidojn, Kaj mi ilin forte amas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Mi observas Viajn ordonojn kaj decidojn, Ĉar ĉiuj miaj vojoj estas antaŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Mia krio venu al Vi, ho Eternulo; Laŭ Via vorto klerigu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Mia petego venu al Vi; Laŭ Via diro savu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Miaj lipoj eldiru gloradon, Ĉar Vi instruas al mi Viajn leĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Mia lango predikos pri Via vorto, Ĉar ĉiuj Viaj ordonoj estas justaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Via mano estu al mi helpo, Ĉar Viajn ordonojn mi elektis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Mi deziregas Vian savon, ho Eternulo, Kaj Via instruo estas mia plezuro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Mia animo vivu kaj gloru Vin, Kaj Viaj juĝoj min helpu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Mi erarvagis kiel perdita ŝafo; Elserĉu Vian sklavon, ĉar Viajn ordonojn mi ne forgesis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Kanto de suprenirado. Al la Eternulo mi vokis en mia sufero, Kaj Li aŭskultis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Ho Eternulo, savu mian animon de mensoga parolo, De falsa lango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Kion Li donos al vi, Kaj kion Li alportos al vi, ho falsa lango?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Akrajn sagojn de fortulo Kun karboj genistaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Ve al mi, ke mi gastas en Meŝeĥ, Ke mi loĝas inter la tendoj de Kedar!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Tro longe loĝis mia animo Inter malamantoj de paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Mi estas pacema; Sed kiam mi ekparolas, ili komencas militon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Kanto de suprenirado. Mi levas miajn okulojn al la montoj: De kie venas al mi helpo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Mia helpo venas de la Eternulo, Kiu kreis la ĉielon kaj la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Li ne lasos vian piedon falpuŝiĝi; Via gardanto ne dormetas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Jen ne dormetas kaj ne dormas La gardanto de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'La Eternulo estas via gardanto; La Eternulo estas via ombro ĉe via dekstra mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'En la tago la suno vin ne frapos, Nek la luno en la nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'La Eternulo vin gardos de ĉia malbono, Li gardos vian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'La Eternulo gardos vian eliron kaj eniron, De nun kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Kanto de suprenirado. De David. Mi ekĝojis, kiam oni diris al mi: Ni iru en la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Niaj piedoj staris en viaj pordegoj, Ho Jerusalem,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Vi Jerusalem, konstruita kiel urbo, En kiu ĉio kuniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'Tien supreniris la triboj, la triboj de la Eternulo, Laŭ la moro de Izrael, Por glori la nomon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Ĉar tie staris tronoj de juĝo, Tronoj de la domo de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Deziru pacon al Jerusalem; Bonan staton havu viaj amantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Paco estu inter viaj muroj, Bonstato en viaj palacoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Pro miaj fratoj kaj amikoj mi do diru: Paco estu al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Pro la domo de la Eternulo, nia Dio, Mi deziras al vi bonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Kanto de suprenirado. Al Vi mi levas miajn okulojn, Ho Vi, kiu sidas en la ĉielo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Jen kiel la okuloj de sklavoj estas direktitaj al la mano de iliaj sinjoroj, Kiel la okuloj de sklavino al la mano de ŝia sinjorino, Tiel niaj okuloj estas direktitaj al la Eternulo, nia Dio, Ĝis Li korfavoros nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Korfavoru nin, ho Eternulo, korfavoru nin; Ĉar ni suferis sufiĉe da malestimo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Tute pleniĝis nia animo De la insultado de arogantuloj, De la malhonorado de fieruloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Kanto de suprenirado. De David. Se la Eternulo ne estus kun ni, Diru nun Izrael,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'Se la Eternulo ne estus kun ni, Kiam homoj leviĝis kontraŭ ni:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'Tiam ili englutus nin vivajn, Kiam ekflamis kontraŭ ni ilia kolero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'Tiam dronigus nin akvo, torento kovrus nian animon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'Tiam kovrus nian animon pereiga akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Benata estu la Eternulo, Kiu ne fordonis nin kiel rabakiron al iliaj dentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Nia animo liberiĝis, kiel birdo el la reto de kaptistoj; La reto disŝiriĝis, kaj ni liberiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Nia helpo estas en la nomo de la Eternulo, Kiu kreis la ĉielon kaj la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Kanto de suprenirado. Kiuj fidas la Eternulon, Tiuj estas kiel la monto Cion, Kiu ne ŝanceliĝas, sed restas eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Montoj estas ĉirkaŭ Jerusalem, Kaj la Eternulo ĉirkaŭas Sian popolon, De nun kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Ĉar ne kuŝos la sceptro de malvirteco sur la sorto de la virtuloj; Por ke la virtuloj ne etendu siajn manojn al maljustaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Bonfaru, ho Eternulo, al tiuj, Kiuj estas bonaj kaj piaj per sia koro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Sed tiujn, kiuj dekliniĝas al siaj malrektaj vojoj, La Eternulo pereigos kune kun la malbonaguloj. Paco al Izrael!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Kanto de suprenirado. Kiam la Eternulo revenigis la forkaptitojn al Cion, Tiam ni estis kiel sonĝantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Tiam nia buŝo estis plena de gajeco, Kaj nia lango plena de kantado; Tiam oni diris inter la popoloj: Ion grandan la Eternulo faris por ĉi tiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Ion grandan la Eternulo faris por ni: Ni ĝojas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Revenigu, ho Eternulo, niajn forkaptitojn, Kiel riveretojn en sudan landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Kiuj semas kun larmoj, Tiuj rikoltos kun kanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Iras kaj ploras la portanto de semotaĵo; Venos kun kanto la portanto de siaj garboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Kanto de suprenirado. De Salomono. Se la Eternulo ne konstruas la domon, Tiam vane laboras super ĝi ĝiaj konstruantoj; Se la Eternulo ne gardas urbon, Tiam vane maldormas la gardanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Vane vi frue leviĝas, malfrue sidas, Manĝas panon kun klopodoj: Al Sia amato Li donas en dormo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Jen, heredo de la Eternulo estas infanoj; Rekompenco estas la frukto de ventro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Kiel sagoj en la mano de fortulo, Tiel estas junaj filoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Bone estas al la homo, kiu plenigis per ili sian sagujon; Ili ne estos hontigitaj, Kiam ili parolos kun la malamikoj ĉe la pordego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Kanto de suprenirado. Feliĉa estas tiu, kiu timas la Eternulon Kaj iras laŭ Liaj vojoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Kiam vi manĝas la laborakiron de viaj manoj, Feliĉe kaj bone estas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Via edzino estas kiel fruktoporta vinberbranĉo interne en via domo; Viaj filoj estas kiel olivaj branĉoj ĉirkaŭ via tablo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Jen tiel estas benata tiu homo, Kiu timas la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'Benos vin la Eternulo el Cion, Kaj vi vidos la bonstaton de Jerusalem en la daŭro de via tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'Kaj vi vidos la infanojn de viaj infanoj. Paco al Izrael!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Kanto de suprenirado. Multe oni afliktis min de post mia juneco, Diras Izrael,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'Multe oni afliktis min de post mia juneco, Sed oni min ne pereigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Sur mia dorso plugis plugistoj, Faris siajn sulkojn longaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'La Eternulo estas justa; Li dishakis la ŝnurojn de la malvirtuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Hontiĝu kaj turniĝu malantaŭen Ĉiuj malamantoj de Cion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Ili estu kiel tegmenta herbo, Kiu forvelkas, antaŭ ol oni ĝin elŝiris;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'Per kiu ne plenigas rikoltanto sian manon Nek garbiganto sian baskon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'Kaj la preterirantoj ne diros: Beno de la Eternulo estu al vi, Ni benas vin per la nomo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Kanto de suprenirado. El profundo mi vokas Vin, ho Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Mia Sinjoro, aŭskultu mian voĉon; Viaj oreloj atentu la voĉon de mia petego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Se vi, ho Eternulo, kalkulus la pekojn, Kiu povus stari, ho mia Sinjoro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Sed Vi estas pardonema, Por ke Vi estu respektata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Mi esperis al la Eternulo, esperis mia animo, Kaj Lian vorton mi fidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Mia animo atendas mian Sinjoron pli, Ol la gardantoj atendas la matenon, La gardantoj la matenon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Izrael fidu la Eternulon; Ĉar ĉe la Eternulo estas favorkoreco Kaj ĉe Li estas granda liberigo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'Kaj Li liberigos Izraelon De ĉiuj liaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Kanto de suprenirado. De David. Ho Eternulo, ne tenas sin alte mia koro, kaj ne leviĝas alte miaj okuloj; Kaj mi ne okupas min per aferoj grandaj kaj neatingeblaj por mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Mi trankviligis kaj kvietigis mian animon; Kiel infano formetita for de la mamo de sia patrino, kiel infano demamigita, Tiel estas en mi mia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Ho Izrael, fidu la Eternulon, De nun kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Kanto de suprenirado. Rememoru, ho Eternulo, Davidon kaj ĉiujn liajn suferojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'Ke li ĵuris al la Eternulo, Kaj donis sanktan promeson al la Potenculo de Jakob:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, 'Mi ne eniros en la ŝirmejon de mia domo, Mi ne supreniros sur la liton, pretigitan por mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'Mi ne donos dormon al miaj okuloj, Nek dormeton al miaj palpebroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'Ĝis mi trovos lokon por la Eternulo, Loĝejon por la Potenculo de Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Jen ni aŭdis, ke ĝi estas en Efrata; Ni ĝin trovis sur arbara kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Ni iru en Lian loĝejon, Ni kliniĝu antaŭ la benketo de Liaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Leviĝu, ho Eternulo, en Vian ripozejon, Vi kaj la kesto de Via potenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Viaj pastroj vestiĝu per justeco, Kaj Viaj fideluloj triumfu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Pro David, Via sklavo, Ne forturnu la vizaĝon de Via sanktoleito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'La Eternulo ĵuris al David veron, kaj Li ne dekliniĝos de ĝi: Frukton de via ventro Mi sidigos sur via trono;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Se viaj filoj observos Mian interligon kaj Mian leĝon, kiun Mi instruos al ili, Tiam ankaŭ iliaj filoj eterne sidos sur via trono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Ĉar la Eternulo elektis Cionon, Kaj deziris, ke ĝi estu loĝejo por Li:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, 'Ĉi tio estas Mia ripozejo por eterne; Ĉi tie Mi loĝos, ĉar ĝin Mi ekdeziris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Ĝian nutraĵon Mi abunde benos, Ĝiajn malriĉulojn Mi satigos per pano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Kaj ĝiajn pastrojn Mi vestos per savo; Kaj ĝiaj fideluloj ĝojos kaj triumfos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Tie Mi elkreskigos kornon al David, Tie Mi aranĝos lumilon por Mia sanktoleito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Liajn malamikojn Mi kovros per honto; Sed sur li brilos lia krono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Kanto de suprenirado. De David. Jen, kiel bone kaj ĉarme estas, Se fratoj vivas kune!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Kiel la bona oleo, Kiu de la kapo defluas sur la barbon, la barbon de Aaron, Kaj defluas sur la randon de lia vesto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'Kiel la roso, Kiu de Ĥermon malleviĝas sur la montojn de Cion; Ĉar tie la Eternulo donas la benon, Vivon por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Kanto de suprenirado. Nun benu la Eternulon, ĉiuj sklavoj de la Eternulo, Kiuj en la noktoj staras en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Levu la manojn al la sanktejo, Kaj benu la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'El Cion benu vin la Eternulo, La Kreinto de la ĉielo kaj la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Haleluja! Gloru la nomon de la Eternulo, Gloru, sklavoj de la Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'Kiuj staras en la domo de la Eternulo, En la kortoj de la domo de nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Gloru la Eternulon, ĉar la Eternulo estas bona; Prikantu Lian nomon, ĉar ĝi estas ĉarma.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Ĉar Jakobon la Eternulo elektis al Si, Izraelon kiel Sian trezoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Ĉar mi scias, ke la Eternulo estas granda Kaj ke nia Sinjoro estas super ĉiuj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Ĉion, kion la Eternulo deziras, Li faras, En la ĉielo kaj sur la tero, sur la maroj kaj en ĉiuj abismoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'Li levas la nubojn de la randoj de la tero, Li aperigas fulmojn en la pluvo, Li elirigas la venton el Siaj provizejoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'Li batis la unuenaskitojn en Egiptujo, De homo ĝis bruto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'Li aperigis signojn kaj miraklojn interne de vi, ho Egiptujo, Super Faraono kaj ĉiuj liaj sklavoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'Li batis multajn popolojn, Kaj mortigis potencajn reĝojn:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Siĥonon, reĝon de la Amoridoj, Kaj Ogon, reĝon de Baŝan, Kaj ĉiujn regnojn Kanaanajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'Kaj Li donis ilian landon kiel heredon, Heredon al Lia popolo Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Ho Eternulo, Via nomo estas eterna; Ho Eternulo, la memoro pri Vi restas por ĉiuj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Ĉar la Eternulo juĝos Sian popolon, Kaj Li korfavoros Siajn sklavojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'La idoloj de la popoloj estas arĝento kaj oro, Faritaĵo de homaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Buŝon ili havas, sed ne parolas; Okulojn ili havas, sed ne vidas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'Orelojn ili havas, sed ne aŭdas; Kaj ne ekzistas spiro en ilia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Kiel ili, tiel estos iliaj farantoj, Ĉiuj, kiuj ilin fidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Ho domo de Izrael, benu la Eternulon; Ho domo de Aaron, benu la Eternulon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Ho domo de Levi, benu la Eternulon; Ho timantoj de la Eternulo, benu la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'El Cion estu benata la Eternulo, Kiu loĝas en Jerusalem. Haleluja!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Gloru la Eternulon, ĉar Li estas bona, Ĉar eterna estas Lia boneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Gloru la Dion de la dioj, Ĉar eterna estas Lia boneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Gloru la Sinjoron de la sinjoroj, Ĉar eterna estas Lia boneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'La sola faranto de grandaj mirakloj, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Kiu saĝege kreis la ĉielon, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Kiu etendis la teron super la akvo, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Kiu kreis grandajn lumojn, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'La sunon, por regi en la tago, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'La lunon kaj la stelojn, por regi en la nokto, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Kiu batis Egiptujon en ĝiaj unuenaskitoj, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'Kaj elkondukis el ĝia mezo Izraelon, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'Per forta mano kaj etendita brako, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Kiu fendis la Ruĝan Maron en du partojn, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'Kaj trairigis Izraelon tra ĝi, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'Kaj enĵetis Faraonon kaj lian militistaron en la Ruĝan Maron, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Kiu kondukis Sian popolon tra la dezerto, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'Kiu batis grandajn reĝojn, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'Kaj mortigis reĝojn potencajn, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Siĥonon, reĝon de la Amoridoj, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'Kaj Ogon, reĝon de Baŝan, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'Kaj donis ilian landon kiel heredon, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'Heredon al Lia sklavo Izrael, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'Kiu rememoris nin, kiam ni estis humiligitaj, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'Kaj liberigis nin de niaj premantoj, Ĉar eterna estas Lia boneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'Kiu donas panon al ĉiu karno, Ĉar eterna estas Lia boneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Gloru la Dion de la ĉielo, Ĉar eterna estas Lia boneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'Apud la riveroj de Babel Ni sidis kaj ploris, Rememorante Cionon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Sur la salikoj tie Ni pendigis niajn harpojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Ĉar tie niaj kaptintoj postulis de ni kantojn, Kaj niaj mokantoj ĝojon, dirante: Kantu al ni el la kantoj de Cion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Kiel ni kantos sur fremda tero La kanton de la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Se mi forgesos vin, ho Jerusalem, Tiam forgesiĝu mia dekstra mano;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Algluiĝu mia lango al mia palato, Se mi vin ne memoros, Se mi ne levos Jerusalemon en la supron de miaj ĝojoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Rememorigu, ho Eternulo, al la filoj de Edom La tagon de Jerusalem, kiam ili diris: Detruu, detruu ĝis ĝia fundamento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Ho ruinigema filino de Babel! Bone estos al tiu, Kiu repagos al vi por la faro, kiun vi faris al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Bone estos al tiu, Kiu prenos kaj frakasos viajn infanetojn sur ŝtono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'De David. Mi gloras Vin el mia tuta koro; Antaŭ la dioj mi Vin prikantas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Mi kliniĝas antaŭ Via sankta templo, Kaj mi gloras Vian nomon por Via boneco kaj vereco; Ĉar Vi grandigis pli ol ĉio Vian nomon per Via vorto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'En la tago, kiam mi vokis, Vi aŭskultis min, Vi donis forton al mia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Gloros Vin, ho Eternulo, ĉiuj reĝoj de la tero, Ĉar ili aŭdis la vortojn de Via buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'Kaj ili prikantos la vojojn de la Eternulo; Ĉar granda estas la gloro de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Ĉar kvankam la Eternulo estas alte, tamen Li rigardas humilulon, Kaj fierulon Li rimarkas de malproksime.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Kvankam mi iras meze de suferoj, tamen Vi konservas mian vivon; Kontraŭ la kolero de miaj malamikoj Vi etendas Vian brakon, Kaj Via dekstra mano min helpas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'La Eternulo plenumos por mi. Ho Eternulo, Via boneco estas eterna; La kreitaĵojn de Viaj manoj ne forlasu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Al la ĥorestro. Psalmo de David. Ho Eternulo, Vi min esploras kaj min konas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Vi scias, kiam mi sidas kaj kiam mi leviĝas; Vi komprenas mian penson de malproksime.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Kiam mi iras kaj kiam mi ripozas, Vi estas ĉirkaŭ mi, Kaj ĉiujn miajn vojojn Vi konas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Ĉar antaŭ ol troviĝas vorto sur mia lango, Jen, ho Eternulo, Vi ĉion jam scias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'De malantaŭe kaj de antaŭe Vi ĉirkaŭbaris min Kaj metis sur min Vian manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Mirinda estas por mi tia sciado, tro alta; Mi ĝin ne povas kompreni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Kien mi iros for de Via spirito? Kaj kien mi kuros for de Via vizaĝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Se mi leviĝos al la ĉielo, Vi estas tie; Se mi kuŝiĝos en Ŝeol, jen Vi tie estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Ĉu mi okupos la flugilojn de la matenruĝo, Ĉu mi loĝiĝos sur la rando de la maro:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'Ankaŭ tie Via mano min kondukos, Kaj Via dekstra mano min tenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Se mi diros: Mallumo min kovros, Kaj la lumo ĉirkaŭ mi fariĝos nokto:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'Eĉ mallumo ne mallumas antaŭ Vi, Kaj la nokto lumas kiel tago; Mallumo fariĝas kiel lumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Ĉar Vi kreis mian internaĵon, Formis min en la ventro de mia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Mi gloras Vin, ĉar mi estas mirinde kreita; Mirindaj estas Viaj kreitaĵoj, Kaj mia animo tion bone konscias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Ne estis kaŝitaj antaŭ Vi miaj ostoj, Kiam mi estis kreata en kaŝiteco, Kiam mi estis formata en la profundo de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Mian embrion vidis Viaj okuloj, Kaj en Via libro estis enskribitaj ĉiuj tagoj destinitaj, Kiam ankoraŭ eĉ unu ne ekzistis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Kiel grandvaloraj estas por mi Viaj pensoj, ho Dio! Kiel granda estas ilia nombro!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Se mi ilin kalkulus, ili estus pli multaj ol la sablo; Kiam mi vekiĝas, mi estas ankoraŭ kun Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Mortigu, ho Dio, la malvirtulojn, Kaj sangaviduloj foriĝu de mi!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Ili parolas pri Vi malice, Kaj Viaj malamikoj leviĝas por trompo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Viajn malamantojn, ho Eternulo, mi ja malamas, Kaj Viajn kontraŭulojn mi abomenas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Per ekstrema malamo mi ilin malamas; Ili fariĝis por mi malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Esploru min, ho Dio, kaj konu mian koron; Provu min kaj sciu miajn pensojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'Kaj rigardu, ĉu mi estas sur malbona vojo, Kaj gvidu min sur la vojo de eterneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Al la ĥorestro. Psalmo de David. Liberigu min, ho Eternulo, de malbona homo, Gardu min kontraŭ perfortulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Kontraŭ tiuj, kiuj elpensas malbonon en la koro, Ĉiutage kaŭzas militojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'Kiuj akrigas sian langon, kiel serpento; Veneno de vipuro estas sub iliaj lipoj. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Gardu min, ho Eternulo, kontraŭ la manoj de malvirtuloj, Gardu min kontraŭ perfortuloj, Kiuj intencas renversi miajn paŝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Fieruloj kaŝis kaptilon por mi kaj ŝnurojn, Ili etendis reton ĉe la vojo, implikilon ili metis por mi. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Mi diris al la Eternulo: Vi estas mia Dio; Atentu, ho Eternulo, la voĉon de mia petego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Ho Eternulo, mia Sinjoro, forto de mia savo, Vi ŝirmas mian kapon en la tago de batalo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Ne donu, ho Eternulo, al malvirtulo lian dezirataĵon, Lian intencon ne efektivigu, ke ili ne fieriĝu. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'La veneno de miaj ĉirkaŭantoj, La malicaĵo de iliaj lipoj kovru ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Falu sur ilin brulantaj karboj; Ili ĵetiĝu en fajron, En abismojn, ke ili ne leviĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Kalumnianto ne staros forte sur la tero; Perfortulon la malbono entiros en pereon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Mi scias, ke la Eternulo defendos la aferon de mizerulo, La rajton de malriĉuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Kaj virtuloj ja gloros Vian nomon; Piuloj restos antaŭ Via vizaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Psalmo de David. Ho Eternulo, mi vokas al Vi; rapidu al mi; Atentu mian voĉon, kiam mi vokas al Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Mia preĝo valoru antaŭ Vi kiel incenso, La levo de miaj manoj kiel vespera oferdono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Metu, ho Eternulo, gardon al mia buŝo, Gardu la pordon de miaj lipoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Ne klinu mian koron al io malbona, Al partoprenado en malbonagoj kun malbonaguloj; Mi ne manĝu iliajn bongustaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Virtuloj min frapu favorkore kaj punu min: Ĝi estos oleo por la kapo; Mia kapo ne rifuzos, se estos eĉ pli; Kaj mi preĝas ĉe iliaj malfeliĉoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Disiĝis sur roko iliaj juĝantoj, Kaj ili aŭdis miajn vortojn, kiel amikaj ili estis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Kiel iu plugas kaj dispecigas la teron, Tiel estas disĵetitaj iliaj ostoj ĝis la buŝo de Ŝeol.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Ĉar al Vi, ho Eternulo, mia Sinjoro, estas direktitaj miaj okuloj; Al Vi mi esperas: ne forpuŝu mian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Gardu min kontraŭ la reto, kiun oni metis al mi, Kontraŭ la implikilo de la malbonaguloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'La malvirtuloj falu en siajn retojn ĉiuj, Dum mi preteriros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Instruo de David, kiam li estis en la kaverno. Preĝo. Per mia voĉo mi krias al la Eternulo, Per mia voĉo mi preĝas al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Mi elverŝas antaŭ Li mian peton, Mian suferon mi al Li rakontas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Kiam senfortiĝis en mi mia spirito, tiam Vi sciis mian vojon: Sur la vojo, kiun mi iras, ili kaŝis reton por mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Rigardu dekstren kaj vidu: neniu volas min koni; Malaperis rifuĝejo por mi, neniu zorgas pri mia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Mi krias al Vi, ho Eternulo; Mi diras: Vi estas mia rifuĝejo, Mia parto en la lando de la vivantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Atentu mian ploron, ĉar mi tre senfortiĝis; Savu min de miaj persekutantoj, ĉar ili estas pli fortaj ol mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Eligu mian animon el malliberejo, por ke mi gloru Vian nomon. Min ĉirkaŭos la virtuloj, kiam Vi bonfaros al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Psalmo de David. Ho Eternulo, aŭskultu mian preĝon, Atentu mian petegon laŭ Via vereco, Respondu al mi laŭ Via justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'Kaj ne eniru en juĝon kun Via sklavo, Ĉar neniu vivanta povos praviĝi antaŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Ĉar malamiko persekutis mian animon, Premis al la tero mian vivon; Li metis min en mallumon, kiel delonge mortintojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Senfortiĝas en mi mia animo, Konsumiĝas en mi mia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Mi rememoras la tagojn antikvajn, Mi meditas pri ĉiuj Viaj faroj, Mi pensas pri la faritaĵoj de Viaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Mi etendas al Vi miajn manojn; Mia animo soifas Vin kiel seka tero. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Rapidu, aŭskultu min, ho Eternulo, mia spirito konsumiĝas; Ne kaŝu antaŭ mi Vian vizaĝon, Ĉar mi similiĝus al la forirantaj en la tombon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Aŭdigu al mi matene Vian bonecon, Ĉar Vin mi fidas; Montru al mi la vojon, kiun mi devas iri, Ĉar al Vi mi levas mian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Savu min de miaj malamikoj, ho Eternulo; Al Vi mi rifuĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Instruu al mi plenumi Vian volon, ĉar Vi estas mia Dio; Via bona spirito gvidu min sur ebena tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Pro Via nomo, ho Eternulo, lasu min vivi; Pro Via justeco eligu mian animon el mizero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'Kaj pro Via favorkoreco ekstermu miajn malamikojn Kaj pereigu ĉiujn premantojn de mia animo, Ĉar mi estas Via sklavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'De David. Benata estu la Eternulo, mia Roko, Kiu instruas miajn manojn batali, miajn fingrojn militi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'Mia bono kaj mia fortikaĵo, Mia rifuĝejo kaj mia savanto, Mia ŝildo, Li, kiun mi fidas, Kiu submetas al mi mian popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Ho Eternulo, kio estas homo, ke Vi lin konas, Kaj homido, ke Vi lin atentas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'Homo estas simila al spireto; Liaj tagoj estas kiel pasanta ombro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Ho Eternulo, klinu Vian ĉielon kaj iru malsupren; Tuŝu la montojn, kaj ili ekfumiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Ekbriligu fulmon, kaj dispelu ilin; Sendu Viajn sagojn, kaj konfuzu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Etendu Vian manon el supre; Liberigu min, kaj savu min el granda akvo, El la mano de fremduloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'Kies buŝo parolas malveraĵon Kaj kies dekstra mano estas mano de trompo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Ho Dio, novan kanton mi kantos al Vi, Sur dekkorda psaltero mi muzikos al Vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'Kiu donas helpon al la reĝoj, Kiu savas Sian sklavon David de danĝera glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Liberigu min, kaj savu min el la mano de fremduloj, Kies buŝo parolas malveraĵon Kaj kies dekstra mano estas mano de trompo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Niaj filoj kiel plantitaĵoj kreskas en sia juneco; Niaj filinoj estas kiel skulptitaj kolonoj, ornamoj de palaco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Niaj grenejoj estas plenaj, enhavas sufiĉe da greno de ĉiu speco; Niaj ŝafoj estas en la nombro de miloj kaj dekmiloj sur niaj paŝtejoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Niaj bovoj estas ŝarĝitaj; Ne ekzistas difekto, ne ekzistas perdo, ne ekzistas ploro sur niaj stratoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Feliĉa estas la popolo, kiu havas tian staton; Feliĉa estas la popolo, kies Dio estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Glorkanto de David. Mi altigos Vin, mia Dio, ho Reĝo, Kaj mi benos Vian nomon ĉiam kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Ĉiutage mi Vin benos, Kaj mi gloros Vian nomon ĉiam kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Granda estas la Eternulo kaj tre glorinda, Kaj Lia grandeco estas nemezurebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Generacio al generacio laŭdos Viajn farojn Kaj rakontos pri Via potenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Pri la majesto de Via granda gloro Kaj pri Viaj mirindaj faroj mi meditos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'La forton de Viaj timindaĵoj oni priparolos, Kaj Vian grandecon mi rakontos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Oni gloros la renomon de Via granda boneco, Kaj oni prikantos Vian justecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Kompatema kaj favorkora estas la Eternulo, Longetolera kaj kun granda boneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'La Eternulo estas bona por ĉiuj; Lia favorkoreco estas super ĉiuj Liaj kreitaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Gloros Vin, ho Eternulo, ĉiuj Viaj kreitaĵoj, Kaj Viaj fideluloj Vin benos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Ili raportos pri la gloro de Via regno Kaj parolos pri Via potenco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'Por sciigi al la homidoj Lian potencon Kaj la majestan gloron de Lia regno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Via reĝeco estas reĝeco eterna, Kaj Via regado estas por ĉiuj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'La Eternulo subtenas ĉiujn falantojn Kaj restarigas ĉiujn kurbigitojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Ĉies okuloj estas turnitaj al Vi, Kaj Vi donas al ili ilian manĝon en ĝia tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Vi malfermas Vian manon Kaj satigas favore ĉion vivantan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Justa estas la Eternulo en ĉiuj Siaj vojoj Kaj bona en ĉiuj Siaj faroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Proksima estas la Eternulo por ĉiuj, kiuj Lin vokas, Por ĉiuj, kiuj vokas Lin sincere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'La deziron de Siaj respektantoj Li plenumas, Kaj ilian krion Li aŭdas kaj helpas ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'La Eternulo gardas ĉiujn Sian amantojn, Kaj ĉiujn malvirtulojn Li ekstermas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'La gloron de la Eternulo eldiros mia buŝo, Kaj ĉiu karno benu Lian sanktan nomon ĉiam kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Haleluja! Gloru, ho mia animo, la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Mi gloros la Eternulon en la daŭro de mia tuta vivo, Mi kantos al mia Dio tiel longe, kiel mi estos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Ne fidu eminentulojn, Homidon, kiu ne povas helpi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Eliras lia spirito, li reiras en sian teron; Kaj en tiu tago neniiĝas ĉiuj liaj intencoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Bone estas al tiu, kies helpo estas la Dio de Jakob, Kiu esperas al la Eternulo, lia Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'Kiu kreis la ĉielon kaj la teron, La maron, kaj ĉion, kio estas en ili, Kiu gardas la veron eterne;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'Kiu faras justecon al la prematoj, Donas panon al la malsataj. La Eternulo liberigas la malliberulojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'La Eternulo malfermas la okulojn al la blinduloj; La Eternulo restarigas la kurbigitojn; La Eternulo amas la virtulojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'La Eternulo gardas la enmigrintojn, Subtenas orfon kaj vidvinon; Sed la vojon de malvirtuloj Li pereigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'La Eternulo reĝas eterne, Via Dio, ho Cion, por ĉiuj generacioj. Haleluja!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Haleluja! Ĉar estas bone kanti al nia Dio, Ĉar agrabla estas la glorkantado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'La Eternulo konstruas Jerusalemon, La elpelitojn de Izrael Li kolektas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Li sanigas la korprematojn Kaj bandaĝas iliajn vundojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Li kalkulas la stelojn, Kaj al ili ĉiuj Li donas nomojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Granda estas nia Sinjoro kaj tre forta; Lia saĝo estas nemezurebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'La Eternulo altigas la humilulojn; Sed la malvirtulojn Li malaltigas ĝis la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Kantu al la Eternulo gloradon, Muziku al nia Dio per harpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'Li kovras la ĉielon per nuboj, Pretigas por la tero pluvon, Kreskigas sur la montoj herbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'Li donas al la bruto ĝian nutraĵon, Kaj al la korvidoj, kiuj krias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Ne la forton de ĉevalo Li ŝatas; Ne la femuroj de homo al Li plaĉas:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Plaĉas al la Eternulo Liaj timantoj, Kiuj fidas Lian bonecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Laŭdu, ho Jerusalem, la Eternulon; Gloru vian Dion, ho Cion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Ĉar Li fortikigis la riglilojn en viaj pordegoj, Li benis viajn filojn interne de vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Li donas pacon al viaj limoj, Li satigas vin per la plej bona el la tritiko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Li sendas Sian ordonon al la tero; Tre rapide kuras Lia vorto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'Li donas neĝon kiel lanon, Li ŝutas prujnon kiel cindron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Li ĵetas Sian glacion kiel pecojn; Kiu kontraŭstaros al Lia frosto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Li sendas Sian vorton, kaj ĉio degelas; Li blovas per Sia vento, kaj ekfluas akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Li sciigas al Jakob Sian vorton, Siajn leĝojn kaj decidojn al Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Tiel Li ne faras al iu alia popolo; Kaj Liajn decidojn ili ne scias. Haleluja!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Haleluja! Gloru la Eternulon el la ĉielo, Gloru Lin en la alto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Gloru Lin, ĉiuj Liaj anĝeloj; Gloru Lin, ĉiuj Liaj militistaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Gloru Lin, suno kaj luno; Gloru Lin, ĉiuj lumaj steloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Gloru Lin, plej supraj ĉieloj, Kaj la akvo, kiu estas super la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Ili gloru la nomon de la Eternulo; Ĉar Li ordonis, kaj ili kreiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'Kaj Li starigis ilin por ĉiam, por eterne; Li donis leĝon, kiun ili ne malobeos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Gloru la Eternulon el la tero, Marmonstroj kaj ĉiuj abismoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'Fulmo kaj hajlo, neĝo kaj nebulo, Ventego, kiu plenumas Lian vorton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'Montoj kaj ĉiuj montetoj, Fruktoportaj arboj kaj ĉiuj cedroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'Bestoj kaj ĉiaj brutoj, Rampaĵoj kaj flugilaj birdoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'Reĝoj de la tero kaj ĉiuj popoloj, Princoj kaj ĉiuj juĝantoj sur la tero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'Junuloj kaj junulinoj, Maljunuloj kaj knaboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Ili gloru la nomon de la Eternulo, Ĉar sole Lia nomo estas alta, Lia majesto estas sur la tero kaj en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'Kaj Li altigis la kornon de Sia popolo, La gloron de ĉiuj Liaj fideluloj, De la filoj de Izrael, Lia plej proksima popolo. Haleluja!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Haleluja! Kantu al la Eternulo novan kanton, Lian gloron en la anaro de fideluloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Izrael ĝoju pri sia Kreinto, La filoj de Cion ĝoju pri sia Reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Ili gloru Lian nomon en danco, Per tamburino kaj harpo ili muziku al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Ĉar al la Eternulo plaĉas Lia popolo; Li ornamas humilulojn per savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'La fideluloj ĝoju en honoro, Kantu ĝoje sur siaj kuŝejoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Glorado al Dio estas en ilia buŝo, Kaj dutranĉa glavo en ilia mano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'Por fari venĝon super la popoloj, Punkorektadon super la gentoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'Por malliberigi iliajn reĝojn per ĉenoj Kaj iliajn eminentulojn per feraj katenoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'Por fari super ili antaŭdestinitan juĝon. Tio estas honoro por ĉiuj Liaj fideluloj. Haleluja!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Haleluja! Gloru Dion en Lia sanktejo, Gloru Lin en la firmaĵo de Lia forto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Gloru Lin por Liaj potencaj faroj, Gloru Lin laŭ Lia granda majesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Gloru Lin per sonado de trumpeto, Gloru Lin per psaltero kaj harpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Gloru Lin per tamburino kaj danco, Gloru Lin per kordinstrumentoj kaj fluto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Gloru Lin per laŭtaj cimbaloj, Gloru Lin per tintantaj cimbaloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Ĉio spiranta gloru la Eternulon. Haleluja!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Sentencoj de Salomono, filo de David, reĝo de Izrael:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'Por scii saĝon kaj moralinstruon; Por kompreni parolojn de prudento;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'Por ricevi instruon pri saĝo, Vero, justo, kaj honesto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'Por doni al la malkleruloj spriton, Al la junulo scion kaj singardemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Saĝulo aŭdu kaj plimultigu sian scion, Kaj prudentulo akiros gvidajn kapablojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'Por kompreni sentencon kaj retoraĵon, La vortojn de saĝuloj kaj iliajn enigmojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'La timo antaŭ la Eternulo estas la komenco de sciado. Saĝon kaj instruon malpiuloj malestimas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Aŭskultu, mia filo, la instruon de via patro, Kaj ne forĵetu la ordonon de via patrino;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Ĉar ili estas bela krono por via kapo, Kaj ornamo por via kolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Mia filo, se pekuloj vin logos, Ne sekvu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Se ili diros: Iru kun ni, Ni embuskos por mortigi, Ni senkaŭze insidos senkulpulojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'Kiel Ŝeol ni englutos ilin vivajn, Kaj la piulojn kiel irantajn en la tombon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Ni trovos diversajn grandvaloraĵojn, Ni plenigos niajn domojn per rabaĵo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'Vi lotos meze inter ni, Unu monujo estos por ni ĉiuj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Mia filo, ne iru la vojon kune kun ili; Gardu vian piedon de ilia vojstreko,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Ĉar iliaj piedoj kuras al malbono, Kaj rapidas, por verŝi sangon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Ĉar vane estas metata reto Antaŭ la okuloj de ĉiu birdo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'Kaj ili embuskas sian propran sangon, Ili insidas siajn proprajn animojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Tiaj estas la vojoj de ĉiu, kiu avidas rabakiron; Ĝi forprenas la vivon de sia posedanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'La saĝo krias sur la strato; Ĝi aŭdigas sian voĉon sur la placoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'Ĝi vokas en la ĉefaj kunvenejoj, ĉe la pordegaj enirejoj; En la urbo ĝi diras siajn parolojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'Ĝis kiam, ho malkleruloj, vi amos nescion? Kaj al blasfemantoj plaĉos blasfemado, Kaj senprudentuloj malamos scion?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Returnu vin al mia predikado; Jen mi eligos al vi mian spiriton, Mi sciigos al vi miajn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Ĉar mi vokis, kaj vi rifuzis; Mi etendis mian manon, kaj neniu atentis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'Kaj vi forĵetis ĉiujn miajn konsilojn, Kaj miajn predikojn vi ne deziris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'Tial ankaŭ mi ridos ĉe via malfeliĉo; Mi mokos, kiam timo vin atakos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'Kiam la timo atakos vin kiel uragano, Kaj via malfeliĉo venos kiel ventego, Kiam venos al vi mizero kaj sufero:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Tiam ili min vokos, sed mi ne respondos; Ili min serĉos, sed min ne trovos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Tial ke ili malamis scion, Kaj timon antaŭ la Eternulo ili ne deziris havi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'Ili ne deziris miajn konsilojn, Ili malestimis ĉiujn miajn predikojn:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'Ili manĝu la fruktojn de sia agado, Kaj ili satiĝu de siaj pripensoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Ĉar la kapricoj de la malsaĝuloj ilin mortigas, Kaj la senzorgeco de la senorduloj ilin pereigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Sed kiu min aŭskultas, tiu loĝos sendanĝere, Kaj estos trankvila, kaj ne timos malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Mia filo! se vi akceptos miajn parolojn Kaj konservos ĉe vi miajn ordonojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'Ke via orelo atente aŭskultos saĝon Kaj vian koron vi inklinigos al komprenado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'Se vi vokos la prudenton Kaj direktos vian voĉon al la saĝo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'Se vi serĉos ĝin kiel arĝenton, Serĉegos kiel trezoron:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'Tiam vi komprenos la timon antaŭ la Eternulo, Kaj vi akiros konadon pri Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Ĉar la Eternulo donas saĝon; El Lia buŝo venas scio kaj kompreno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'Li havas helpon por la virtuloj; Li estas ŝildo por tiuj, kiuj vivas pie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'Li gardas la iradon de la justo, Kaj zorgas pri la vojo de Siaj piuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Tiam vi komprenos veremon kaj juston Kaj pion kaj ĉiun bonan vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Ĉar saĝo venos en vian koron, Kaj scio estos agrabla por via animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'Bona konscio vin gvidos, Prudento vin gardos,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'Por savi vin de la vojo de malbono, De homo, parolanta kontraŭveraĵon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'De tiuj, kiuj forlasas la ĝustan vojon, Por iri la vojojn de mallumo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'Kiuj ĝojas, kiam ili faras malbonon, Trovas plezuron en la malordo de la malboneco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'Kies vojoj estas malrektaj Kaj kies irado deflankiĝis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'Por savi vin de fremda virino, De edzino ne via, kies paroloj estas glataj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'Kiu forlasas la amikon de sia juneco, Kaj forgesas la ligon de sia Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'Ĉar ŝia domo kondukas al morto, Kaj ŝiaj paŝoj al la inferuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'Ĉiuj, kiuj eniras al ŝi, ne revenas, Kaj ne reatingas la vojon de la vivo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Ke vi iru la vojon de bonuloj, Kaj sekvu la paŝosignojn de piuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Ĉar la piuloj loĝos sur la tero, Kaj la senpekuloj restos sur ĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'Sed la malpiuloj estos ekstermitaj de sur la tero, Kaj la maliculoj estos malaperigitaj de tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Mia filo! ne forgesu mian instruon, Kaj via koro konservu miajn ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'Ĉar ili akirigos al vi longan vivon, Jarojn de vivo kaj paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Favoro kaj vero vin ne forlasu; Alligu ilin al via kolo, Skribu ilin sur la tabeloj de via koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'Kaj vi trovos favoron kaj bonan opinion Ĉe Dio kaj homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Fidu la Eternulon per via tuta koro, Kaj ne fidu vian prudenton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Konsciu Lin en ĉiuj viaj vojoj, Kaj Li ĝustigos vian iradon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Ne opiniu vin saĝa; Timu la Eternulon, kaj deturnu vin de malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'Ĉi tio estos saniga por via korpo, Kaj bona nutro por viaj ostoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Faru honoron al la Eternulo el via havo Kaj el la unuavenaĵo de ĉiuj viaj rikoltoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'Tiam viaj grenejoj tute pleniĝos, Kaj viaj vinpremejoj superbordigos moston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'La instruon de la Eternulo, ho mia filo, ne malŝatu; Kaj ne deturnu vin, kiam Li faras al vi punon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Ĉar kiun la Eternulo amas, tiun Li punkorektas, Kiel patro la filon, en kiu li havas plezuron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Feliĉa estas la homo, kiu trovis saĝon, Kaj la homo, kiu akiris prudenton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Ĉar estas pli bone ĝin aĉeti, ol aĉeti arĝenton, Kaj ĝia rikoltaĵo estas pli bona, ol pura oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Ĝi estas pli kara, ol juveloj; Kaj nenio, kion vi povus deziri, povas esti komparata kun ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Longa vivo estas en ĝia dekstra mano; Riĉo kaj gloro estas en ĝia maldekstra mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Ĝiaj vojoj estas vojoj agrablaj, Kaj ĉiuj ĝiaj vojetoj estas paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Ĝi estas arbo de vivo por tiuj, kiuj ĝin ekkaptis; Kaj feliĉaj estas tiuj, kiuj ĝin posedas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'La Eternulo per saĝo fondis la teron; Per prudento Li aranĝis la ĉielon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Per Lia ĉionsciado disiĝis abismoj; Kaj la nuboj elverŝas roson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Mia filo! ili ne foriru de viaj okuloj; Konservu klarecon de la kapo kaj prudenton:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'Ili estos vivo por via animo, Kaj ornamo por via kolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Tiam vi iros sendanĝere vian vojon, Kaj via piedo ne falpuŝiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Kiam vi kuŝiĝos dormi, vi ne timos; Kaj kiam vi kuŝos, via dormo estos agrabla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Ne timu subitan teruron, Nek pereigon, kiu povus veni de malbonuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Ĉar la Eternulo estos via helpo, Kaj gardos vian piedon kontraŭ reto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Ne rifuzu bonon al la bezonantoj, Se via mano havas la forton por fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Kiam vi havas ĉe vi, ne diru al via proksimulo: Iru kaj revenu, kaj morgaŭ mi donos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Ne pripensu malbonon kontraŭ via proksimulo, Kiam li kun konfido loĝas ĉe vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Ne malpacu kun iu senkaŭze, Se li ne faris al vi malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Ne enviu rabemulon, Kaj elektu neniun el liaj vojoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Ĉar la perversulojn la Eternulo abomenas, Kaj Sian intencon Li malkaŝas al la piuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'Malbeno de la Eternulo estas en la domo de malbonulo, Kaj la loĝejon de piuloj Li benas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'La mokantojn Li mokas, Kaj al la humiluloj Li donas favoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Honoron heredas saĝuloj; Sed malsaĝuloj forportas honton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Aŭskultu, infanoj, la instruon de la patro, Kaj atentu, por lerni prudenton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Ĉar bonan instruon mi donis al vi; Mian leĝon ne forlasu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Ĉar mi estis filo de mia patro, Dorlotata kaj sola de mia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'Kaj li instruis min, kaj diris al mi: Via koro akceptu miajn vortojn; Observu miajn ordonojn, kaj vi vivos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Akiru saĝon, akiru prudenton; Ne forgesu, kaj ne deflankiĝu de la paroloj de mia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Ne forlasu ĝin, kaj ĝi vin gardos; Amu ĝin, kaj ĝi zorgos pri vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'La komenco de saĝo estas: akiru saĝon; Kaj por via tuta havo akiru prudenton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Ŝatu ĝin alte, kaj ĝi vin altigos; Kaj ĝi donos al vi honoron, se vi ĝin enbrakigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Ĝi donos ĉarman ornamon al via kapo; Belan kronon ĝi donacos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Aŭskultu, mia filo, kaj akceptu miajn vortojn; Kaj multiĝos la jaroj de via vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Mi kondukos vin laŭ la vojo de saĝo; Mi irigos vin sur rekta vojstreko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Kiam vi iros, via irado ne estos malfaciligata; Kaj kiam vi kuros, vi ne falpuŝiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Tenu forte la instruon, ne forlasu ĝin; Konservu ĝin, ĉar ĝi estas via vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'La vojstrekon de malpiuloj ne iru, Kaj ne ekpaŝu sur la vojo de malbonuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Evitu ĝin, ne trapasu ĝin; Flankiĝu de ĝi, kaj preterpasu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Ĉar ili ne ekdormas, se ili ne faris malbonon; Kaj ili perdas la dorman ripozon, se ili ne pekigis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Ĉar ili manĝas panon de malpio Kaj trinkas vinon de krimo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Kaj la vojo de piuloj estas kiel lumo leviĝanta, Kiu ĉiam pli lumas ĝis plena tagiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'La vojo de malpiuloj estas kiel mallumo; Ili ne scias, je kio ili falpuŝiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Mia filo, atentu miajn vortojn; Klinu vian orelon al miaj paroloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Ili ne foriĝu de viaj okuloj; Gardu ilin en via koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Ĉar ili estas vivo por tiuj, kiuj ilin trovis, Kaj sanigaj por ilia tuta korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Pli ol ĉion gardatan, gardu vian koron; Ĉar el ĝi eliras la vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Forigu de vi falsemon de la buŝo, Kaj malicon de la lipoj malproksimigu de vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Viaj okuloj rigardu rekte, Kaj viaj palpebroj direktiĝu rekte antaŭen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Fortikigu la direkton de viaj piedoj, Kaj ĉiuj viaj vojoj estu firmaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Ne ŝanceliĝu dekstren, nek maldekstren; Forigu de malbono vian piedon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Mia filo! atentu mian saĝon; Al mia prudento klinu vian orelon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'Por ke vi konservu prudenton Kaj via buŝo tenu scion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Ĉar la buŝo de malĉastulino elverŝas mielon, Kaj ŝia gorĝo estas pli glata ol oleo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'Sed ŝia sekvaĵo estas maldolĉa kiel absinto, Akra kiel ambaŭtranĉa glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Ŝiaj piedoj iras malsupren al la morto; Ŝiaj paŝoj atingas Ŝeolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Ŝi ne iras rekte laŭ la vojo de vivo; Ŝiaj paŝoj ŝanceliĝas, sed tion ŝi ne scias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Kaj nun, infanoj, aŭskultu min, Kaj ne forkliniĝu de la vortoj de mia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Malproksimigu de ŝi vian vojon, Kaj ne proksimiĝu al la pordo de ŝia domo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'Por ke vi ne fordonu al aliaj vian honoron Kaj viajn jarojn al la kruelulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'Por ke fremduloj ne satiĝu de via havo, Kaj viaj laboroj ne estu en fremda domo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'Ĝis vi ĝemos en la fino, Kiam konsumiĝos via karno kaj via korpo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'Kaj vi diros: Ho, kiel mi malamis instruon, Kaj mia koro malŝatis moraligon!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'Kaj mi ne aŭskultis la voĉon de miaj instruantoj, Kaj mi ne klinis mian orelon al miaj lernigantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Mi estis preskaŭ en ĉia malbono Meze de kunveno kaj societo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Trinku akvon el via cisterno, Kaj fluantan el via puto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Viaj fontoj disfluu eksteren, Akvaj torentoj en la stratojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Ili apartenu al vi sola, Sed ne al aliaj kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Via fonto estu benata; Kaj havu ĝojon de la edzino de via juneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'Ŝi estas ĉarma kiel cervino, Kaj aminda kiel ibeksino; Ŝiaj karesoj ĝuigu vin en ĉiu tempo, Ŝia amo ĉiam donu al vi plezuron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Kaj kial, mia filo, vi volas serĉi al vi plezuron ĉe fremda virino Kaj enbrakigi ne apartenantan al vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Ĉar antaŭ la okuloj de la Eternulo estas la vojoj de homo, Kaj ĉiujn liajn irojn Li pripensas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Liaj propraj malbonfaroj enkaptos la malpiulon, Kaj la ŝnuroj de lia peko lin tenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Li mortos pro manko de eduko; Kaj la multo de lia senprudenteco lin devojigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Mia filo! se vi garantiis por via proksimulo Kaj donis vian manon por aliulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'Tiam vi enretiĝis per la vortoj de via buŝo, Kaptiĝis per la vortoj de via buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'Tiam, mia filo, agu tiel kaj saviĝu, Ĉar vi falis en la mano de via proksimulo: Iru, vigliĝu, kaj petegu vian proksimulon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Ne lasu viajn okulojn dormi Kaj viajn palpebrojn dormeti;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Savu vin, kiel gazelo, el la mano, Kaj kiel birdo el la mano de la birdokaptisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Iru al la formiko, vi maldiligentulo; Rigardu ĝian agadon, kaj saĝiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Kvankam ĝi ne havas estron, Nek kontrolanton, nek reganton,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'Ĝi pretigas en la somero sian panon, Ĝi kolektas dum la rikolto sian manĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Ĝis kiam, maldiligentulo, vi kuŝos? Kiam vi leviĝos de via dormo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Iom da dormo, iom da dormeto, Iom da kunmeto de la manoj por kuŝado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'Kaj venos via malriĉeco kiel rabisto, Kaj via senhaveco kiel viro armita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Homo sentaŭga, homo malbonfarema, Iras kun buŝo malica,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'Donas signojn per la okuloj, aludas per siaj piedoj, Komprenigas per siaj fingroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'Perverseco estas en lia koro, li intencas malbonon; En ĉiu tempo li semas malpacon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Tial subite venos lia pereo; Li estos rompita subite, kaj neniu lin sanigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Jen estas ses aferoj, kiujn la Eternulo malamas, Kaj sep, kiujn Li abomenegas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'Arogantaj okuloj, mensogema lango, Kaj manoj, kiuj verŝas senkulpan sangon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'Koro, kiu preparas malbonfarajn intencojn, Piedoj, kiuj rapidas kuri al malbono,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'Falsa atestanto, kiu elspiras mensogojn; Kaj tiu, kiu semas malpacon inter fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Konservu, mia filo, la ordonon de via patro, Kaj ne forĵetu la instruon de via patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Ligu ilin por ĉiam al via koro, Volvu ilin sur vian kolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Kiam vi iros, ili gvidos vin; Kiam vi kuŝiĝos, ili vin gardos; Kaj kiam vi vekiĝos, ili parolos kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Ĉar moralordono estas lumingo, kaj instruo estas lumo, Kaj edifaj predikoj estas vojo de vivo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'Por gardi vin kontraŭ malbona virino, Kontraŭ glata lango de fremdulino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Ne deziregu en via koro ŝian belecon, Kaj ne kaptiĝu per ŝiaj palpebroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Ĉar la kosto de publikulino estas nur unu pano; Sed fremda edzino forkaptas la grandvaloran animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Ĉu iu povas teni fajron en sia sino tiel, Ke liaj vestoj ne brulu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Ĉu iu povas marŝi sur ardantaj karboj, Ne bruligante siajn piedojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Tiel ankaŭ estas kun tiu, kiu venas al la edzino de sia proksimulo; Neniu, kiu ŝin ektuŝas, restas sen puno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Oni ne faras grandan honton al ŝtelanto, Se li ŝtelas por sin satigi, kiam li malsatas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'Kaj kiam oni lin kaptas, li pagas sepoble; La tutan havon de sia domo li fordonas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Sed kiu adultas kun virino, tiu estas sensaĝa; Tiu, kiu faras tion, pereigas sian animon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Batojn kaj malhonoron li ricevas, Kaj lia honto ne elviŝiĝas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Ĉar furiozas la ĵaluzo de la edzo; Kaj li ne indulgas en la tempo de la venĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Li rigardas nenian kompenson, Kaj li ne akceptas, se vi volas eĉ multe donaci.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Mia filo! konservu miajn vortojn, Kaj gardu ĉe vi miajn moralordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Konservu miajn moralordonojn, kaj vivu; Kaj mian instruon, kiel la pupilon de viaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Ligu ilin al viaj fingroj; Skribu ilin sur la tabelo de via koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Diru al la saĝo: Vi estas mia fratino; Kaj la prudenton nomu mia parencino;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'Por ke vi estu gardata kontraŭ fremda edzino, Kontraŭ fremdulino, kies paroloj estas glataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Ĉar mi rigardis tra fenestro de mia domo, Tra mia krado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'Kaj mi vidis inter la naivuloj, Mi rimarkis inter la nematuruloj junulon senprudentan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'Kiu pasis sur la placo preter ŝia angulo, Kaj iris la vojon al ŝia domo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'En krepusko, en vespero de tago, Kiam fariĝis nokto kaj mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'Kaj jen renkonte al li iras virino En ornamo de publikulino, ruzema je la koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Bruema kaj vagema; Ŝiaj piedoj ne loĝas en ŝia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'Jen ŝi estas sur la strato, jen sur la placoj, Kaj apud ĉiu angulo ŝi embuskas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Kaj ŝi kaptis lin, kaj kisis lin Kun senhonta vizaĝo, kaj diris al li:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, 'Mi devis alporti dankan oferdonon; Hodiaŭ mi plenumis mian solenan promeson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Tial mi eliris al vi renkonte, Por serĉi vian vizaĝon, kaj mi vin trovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Mi bele kovris mian liton Per multkoloraj teksaĵoj el Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Mi parfumis mian kuŝejon Per mirho, aloo, kaj cinamo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Venu, ni ĝuu sufiĉe volupton ĝis la mateno, Ni plezuriĝu per la amo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Ĉar mia edzo ne estas hejme, Li iris en malproksiman vojon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'La sakon kun mono li prenis kun si; Li revenos hejmen je la plenluno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Ŝi forlogis lin per sia multeparolado, Per sia glata buŝo ŝi lin entiris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Li tuj iras post ŝi, Kiel bovo iras al la buĉo Kaj kiel katenita malsaĝulo al la puno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'Ĝis sago fendas al li la hepaton; Kiel birdo rapidas al la kaptilo, Kaj ne scias, ke ĝi pereigas sian vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Kaj nun, infanoj, aŭskultu min, Atentu la vortojn de mia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Via koro ne flankiĝu al ŝia vojo, Ne eraru sur ŝia irejo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Ĉar multajn ŝi vundis kaj faligis, Kaj multegaj estas ŝiaj mortigitoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Ŝia domo estas vojoj al Ŝeol, Kiuj kondukas malsupren al la ĉambroj de la morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Ĉu ne vokas la saĝo? Kaj ĉu la prudento ne aŭdigas sian voĉon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Ĝi staras sur la pinto de altaĵoj, Apud la vojo, ĉe la vojkruĉiĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'Apud la pordegoj, ĉe la eniro en la urbon, Ĉe la eniro tra la pordoj, ĝi kantas:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'Al vi, ho viroj, mi vokas; Kaj mia voĉo sin turnas al la homoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Komprenu, naivuloj, la prudenton, Kaj sensprituloj prenu en la koron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Aŭskultu, ĉar mi parolos gravaĵon, Kaj ĝustaĵo eliros el mia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Ĉar mia lango parolos veron, Kaj malpiaĵon abomenas miaj lipoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Justaj estas ĉiuj paroloj de mia buŝo; Ili ne enhavas falson kaj malicon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Ĉiuj ili estas ĝustaj por tiu, kiu ilin komprenas, Kaj justaj por tiuj, kiuj akiris scion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Prenu mian instruon, kaj ne arĝenton; Kaj la scion ŝatu pli, ol plej puran oron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Ĉar saĝo estas pli bona ol multekostaj ŝtonoj; Kaj nenio, kion oni povas deziri, povas esti egala al ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Mi, saĝo, loĝas kun la prudento, Kaj mi trovas prudentajn konsilojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Timo antaŭ la Eternulo malamas malbonon, Fieron, malhumilon, kaj malbonan vojon; Malsinceran buŝon mi malamas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'De mi venas konsilo kaj bonaranĝo; Mi estas prudento; al mi apartenas forto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Per mi reĝas la reĝoj, Kaj la estroj donas leĝojn de justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Per mi regas la princoj Kaj la potenculoj kaj ĉiuj juĝantoj sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Mi amas miajn amantojn; Kaj miaj serĉantoj min trovos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Riĉo kaj gloro estas ĉe mi, Daŭra havo kaj justo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Mia frukto estas pli bona ol oro kaj ol plej pura oro; Kaj la rikolto de mi estas pli bona ol elektita arĝento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Laŭ la vojo de vero mi iras, Laŭ la vojstreko de la justo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'Por heredigi al miaj amantoj esencan bonon, Kaj plenigi iliajn trezorejojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'La Eternulo min formis en la komenco de Sia vojo, Antaŭ Siaj kreitaĵoj, tre antikve.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Antaŭ eterno mi estis firme fondita, en la komenco, Antaŭ la kreo de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Kiam ankoraŭ ne ekzistis la abismoj, mi estis jam naskita, Kiam ankoraŭ ne ekzistis fontoj, ŝprucigantaj akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Antaŭ ol la montoj estis starigitaj, Antaŭ la altaĵoj mi estis kreita;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'Kiam la tero ankoraŭ ne estis farita, nek la kampoj, Nek la komencaj polveroj de la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Dum Li firmigis la ĉielojn, mi jam estis tie; Dum Li desegnis limojn sur la supraĵo de la abismo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'Dum Li fortikigis la nubojn supre, Dum Li firmigis la fontojn de la abismo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'Dum Li donis Sian leĝon al la maro, Por ke la akvoj ne transpaŝu siajn bordojn, Kaj dum Li difinis la fundamentojn de la tero:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'Tiam mi estis ĉe Li kiel konstruanto; Mi estis la ĝojo de ĉiuj tagoj, Ludante antaŭ Li ĉiutempe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'Mi ludas sur Lia mondo-tero; Kaj mia ĝojo estas inter la homidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Kaj nun, infanoj, aŭskultu min; Kaj feliĉaj estos tiuj, kiuj iras laŭ miaj vojoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Aŭskultu instruon kaj saĝiĝu, Kaj ne forĵetu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Feliĉa estas la homo, kiu min aŭskultas, Kiu maldormas ĉiutage ĉe miaj pordoj, Kiu staras garde ĉe la fostoj de miaj pordegoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Ĉar kiu min trovis, tiu trovis vivon, Kaj akiros favoron de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'Sed kiu maltrafas min, tiu difektas sian animon; Ĉiuj, kiuj min malamas, amas la morton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'La saĝo konstruis sian domon, Ĉarpentis ĝiajn sep kolonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Ĝi buĉis sian bruton, verŝis sian vinon, Kaj pretigis sian tablon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Ĝi sendis siajn servantinojn, Por anonci sur la pintoj de la altaĵoj de la urbo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, 'Kiu estas naiva, tiu sin turnu ĉi tien! Al la senspritulo ĝi diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, 'Venu, manĝu de mia pano, Kaj trinku el la vino, kiun mi enverŝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Forlasu la malsaĝaĵon, kaj vivu; Kaj iru laŭ la vojo de la prudento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Kiu instruas blasfemanton, tiu prenas sur sin malhonoron; Kaj kiu penas ĝustigi malpiulon, tiu estas mokata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Ne penu ĝustigi blasfemanton, ke li vin ne malamu: Penu ĝustigi saĝulon, kaj li vin amos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Donu al saĝulo, kaj li ankoraŭ pli saĝiĝos; Instruu justulon, kaj li lernos pli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'La komenco de la saĝo estas timo antaŭ la Eternulo; Kaj ekkono pri la Sanktulo estas prudento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Ĉar per mi plimultiĝos viaj tagoj, Kaj aldoniĝos al vi jaroj da vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Se vi saĝiĝis, vi saĝiĝis por vi; Kaj se vi blasfemas, vi sola suferos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Virino malsaĝa, bruema, Sensprita, kaj nenion scianta,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'Sidas ĉe la pordo de sia domo, Sur seĝo sur altaĵo de la urbo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'Por voki la pasantojn, Kiuj iras sian ĝustan vojon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, 'Kiu estas naiva, tiu sin turnu ĉi tien! Kaj al la senspritulo ŝi diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, 'Akvoj ŝtelitaj estas dolĉaj, Kaj pano kaŝita estas agrabla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Kaj li ne scias, ke tie estas mortintoj Kaj ke ŝiaj invititoj estas en la profundoj de Ŝeol.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Sentencoj de Salomono. Saĝa filo estas ĝojo por sia patro, Kaj filo malsaĝa estas malĝojo por sia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Maljustaj trezoroj ne donas utilon; Sed bonfaremo savas de morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'La Eternulo ne malsatigos animon de piulo; Sed la avidon de malpiulo Li forpuŝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Maldiligenta mano malriĉigas; Sed mano de diligentuloj riĉigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Kiu kolektas dum la somero, tiu estas filo saĝa; Sed kiu dormas en la tempo de rikolto, tiu estas filo hontinda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Beno estas sur la kapo de piulo; Sed la buŝo de malpiulo kaŝas krimon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'La memoro de piulo estas benata; Sed la nomo de malpiuloj forputros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Kiu havas saĝan koron, tiu akceptos moralordonojn; Sed kiu havas malsaĝan buŝon, tiu renversiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Kiu iras en senkulpeco, tiu iras sendanĝere; Sed kiu kurbigas siajn vojojn, tiu estos punita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Kiu grimacas per la okulo, tiu kaŭzas suferon; Kaj kiu havas malsaĝan buŝon, tiu renversiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'La buŝo de piulo estas fonto de vivo; Sed la buŝo de malpiulo kaŝas krimon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Malamo kaŭzas malpacon; Sed amo kovras ĉiujn pekojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Sur la lipoj de prudentulo troviĝas saĝo; Sed vergo apartenas al la dorso de sensaĝulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Saĝuloj konservas la scion; Sed la buŝo de malsaĝulo estas proksima al la pereo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'La havo de riĉulo estas lia fortika urbo; Sed pereo por la malriĉuloj estas ilia malriĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'La laborpago de piulo estas por la vivo; La enspezoj de malpiulo estas por peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Kiu konservas la instruon, tiu iras al vivo; Sed kiu forĵetas atentigon, tiu restas en eraro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Kiu kaŝas malamon, tiu havas falseman buŝon; Kaj kiu elirigas kalumnion, tiu estas malsaĝulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Ĉe multo da vortoj ne evitebla estas peko; Sed kiu retenas siajn lipojn, tiu estas saĝa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'La lango de piulo estas plej bonspeca arĝento; La koro de malpiuloj estas kiel nenio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'La lipoj de piulo gvidas multajn; Sed malsaĝuloj mortas pro manko de saĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'La beno de la Eternulo riĉigas, Kaj malĝojon Li ne aldonas al ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'Por malsaĝulo estas ĝojo fari malbonon; Kaj saĝo, por saĝulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Kio timigas malpiulon, tio trafos lin; Kaj kion deziras piuloj, tio estos donita al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Kiel pasanta ventego, tiel malpiulo rapide malaperas; Sed piulo havas eternan fundamenton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Kiel la vinagro por la dentoj kaj la fumo por la okuloj, Tiel la maldiligentulo estas por tiuj, kiuj lin sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'La timo antaŭ la Eternulo multigas la tagojn; Sed la jaroj de malpiuloj estos mallongigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'La atendo de piuloj fariĝos ĝojo; Sed la espero de malpiuloj pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'La vojo de la Eternulo estas defendo por la senpekulo, Sed pereo por la malbonfarantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Piulo neniam falpuŝiĝos; Sed la malpiuloj ne restos sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'La buŝo de piulo eligas saĝon; Sed lango falsema estos ekstermita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'La lipoj de piulo anoncas favoraĵon, Kaj la buŝo de malpiuloj malicaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Malvera pesilo estas abomenaĵo por la Eternulo; Sed plena pezo plaĉas al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Se venis malhumileco, venos ankaŭ honto; Sed ĉe la humiluloj estas saĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'La senkulpeco de la piuloj gvidos ilin; Sed la falsemo pereigos la maliculojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Ne helpos riĉo en la tago de kolero; Sed bonfaremo savas de morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'La justeco de piulo ebenigas lian vojon; Sed malpiulo falos per sia malpieco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'La justeco de piuloj savos ilin; Sed la pasio de maliculoj ilin kaptos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Kiam mortas homo pia, ne pereas lia espero; Sed la atendo de la pekuloj pereas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Piulo estas savata kontraŭ mizero, Kaj malpiulo venas sur lian lokon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Per la buŝo de hipokritulo difektiĝas lia proksimulo; Sed per kompreno piuloj saviĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Kiam al la piuloj estas bone, la urbo ĝojas; Kaj kiam pereas malpiuloj, ĝi estas gaja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Per la beno de piuloj urbo altiĝas; Kaj per la buŝo de malpiuloj ĝi ruiniĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Kiu mokas sian proksimulon, tiu estas malsaĝulo; Sed homo prudenta silentas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Kiu iras kun kalumnioj, tiu elperfidas sekreton; Sed kiu havas fidelan spiriton, tiu konservas aferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Ĉe manko de prikonsiliĝo popolo pereas; Sed ĉe multe da konsilantoj estas bonstato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Malbonon faras al si tiu, kiu garantias por fremdulo; Sed kiu malamas donadon de mano, tiu estas ekster danĝero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Aminda virino akiras honoron, Kaj potenculoj akiras riĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Bonkora homo donos bonon al sia animo, Kaj kruelulo detruas sian karnon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Malvirtulo akiras profiton malveran, Kaj la semanto de virto veran rekompencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Bonfarado kondukas al vivo; Kaj kiu celas malbonon, tiu iras al sia morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Abomenaĵo por la Eternulo estas la malickoruloj; Sed plaĉas al Li tiuj, kiuj iras vojon pian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Oni povas esti certa, ke malvirtulo ne restos senpuna; Sed la idaro de virtuloj estos savita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Kiel ora ringo sur la nazo de porko, Tiel estas virino bela, sed malbonkonduta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'La deziro de virtuloj estas nur bono; Sed malvirtuloj povas esperi nur koleron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Unu disdonas, kaj riĉiĝas ĉiam pli; Alia tro avaras, kaj tamen nur malriĉiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Animo benanta ĝuos bonstaton; Kaj kiu trinkigas, tiu mem havos sufiĉe por trinki.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Kiu retenas grenon, tiun malbenas la popolo; Sed beno venas sur la kapon de tiu, kiu disdonas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Kiu celas bonon, tiu atingos plaĉon; Sed kiu serĉas malbonon, tiun ĝi trafos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Kiu fidas sian riĉecon, tiu falos; Sed virtuloj floros kiel juna folio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Kiu detruas sian domon, tiu heredos venton; Kaj malsaĝulo estas sklavo de saĝulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'La frukto de virtulo estas arbo de vivo; Kaj akiranto de animoj estas saĝulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Se virtulo ricevas redonon sur la tero, Tiom pli malvirtulo kaj pekulo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Kiu amas instruon, tiu amas scion; Sed kiu malamas atentigon, tiu estas malsaĝulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Bonulo akiras favoron de la Eternulo; Sed homo malica estos kondamnita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Ne fortikiĝos homo per malvirto; Sed la radiko de virtuloj ne ŝanceliĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Brava virino estas krono por sia edzo; Sed senhonora estas kiel puso en liaj ostoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'La pensoj de virtuloj estas justeco; La meditado de malvirtuloj estas malico.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'La paroloj de malvirtuloj estas insido pri sango; Sed la buŝo de virtuloj ilin savas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'La malvirtuloj renversiĝos kaj malaperos; Sed la domo de virtuloj staros forte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Oni laŭdas homon laŭ lia saĝo; Sed perversulo estos hontigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Pli bona estas homo negrava, sed laboranta por si, Ol homo, kiu serĉas honoron, sed al kiu mankas pano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Virtulo kompatas la vivon de sia bruto; Sed la koro de malvirtuloj estas kruela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Kiu prilaboras sian teron, tiu havos sate da pano; Sed kiu serĉas vantaĵojn, tiu estas malsaĝulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Malvirtulo serĉas subtenon de malnobluloj; Sed la radiko de virtuloj donas forton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Per siaj pekaj vortoj kaptiĝas malbonulo; Sed virtulo eliras el mizero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Per la fruktoj de sia buŝo homo bone satiĝas; Kaj laŭ la merito de siaj manoj homo ricevas redonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'La vojo de malsaĝulo estas ĝusta en liaj okuloj; Sed saĝulo aŭskultas konsilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Malsaĝulo tuj montras sian koleron; Sed saĝulo ignoras ofendon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Kiu estas verama, tiu eldiras tion, kio estas ĝusta, Sed falsama atestulo trompon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Ofte nepripensita parolo vundas kiel glavo; Sed la lango de saĝuloj sanigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Parolo vera restas fortike por ĉiam; Sed parolo malvera nur por momento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Malico estas en la koro de malbonintenculoj; Sed ĉe la pacigantoj estas ĝojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Nenio malbona trafos virtulon; Sed la malvirtuloj havas plene da malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Abomenaĵo por la Eternulo estas buŝo mensogema; Sed kiuj agas laŭ vero, tiuj plaĉas al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'Saĝa homo kaŝas scion; Sed la koro de malsaĝuloj elkrias malsaĝecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'La mano de diligentuloj regos; Sed mano maldiligenta pagos tributon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Zorgo en la koro de homo ĝin premas; Sed amika vorto ĝin ĝojigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Al la virtulo estas pli bone, ol al lia proksimulo; Sed la vojo de malvirtuloj ilin erarigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Maldiligenteco ne pretigos al si manĝon; Sed homo diligenta havas riĉecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'Sur la vojo de virto estas vivo, Kaj ĝi estos ebenigita kontraŭ morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Saĝa filo lernas de la patro; Sed mokanto ne aŭskultas moralinstruon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'La frukto de la buŝo donas al homo bonan manĝon; Sed la deziro de krimuloj estas perforto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Kiu gardas sian buŝon, tiu gardas sian animon; Kiu tro malfermas sian buŝon, tiu pereas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'La animo de maldiligentulo deziras, kaj ne ricevas; Sed la animo de diligentuloj satiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Vorton malveran virtulo malamas; Sed malvirtulo agas abomene kaj venas al honto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'La virto gardas tiun, kiu iras ĝustan vojon; Sed la malvirto pereigas pekulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Unu ŝajnigas sin riĉa, havante nenion; Alia ŝajnigas sin malriĉa, havante grandan riĉecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Per sia riĉeco homo savas sian animon; Sed malriĉulo ne aŭskultas atentigon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'La lumo de virtuloj brilegas; Sed la lumilo de malvirtuloj estingiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Nur de malhumileco venas malpaco; Sed la akceptantaj konsilojn havas saĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Riĉeco rapide akirita malgrandiĝas; Sed kion oni kolektas per laboro, tio multiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Espero prokrastata dolorigas la koron; Sed plenumita deziro estas arbo de vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Kiu malŝatas diron, tiu malutilas al si mem; Sed respektanta ordonon estos rekompencita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Instruo de saĝulo estas fonto de vivo, Por evitigi la retojn de la morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Bona prudento plaĉigas; Sed la vojo de perfiduloj estas malglata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Ĉiu prudentulo agas konscie; Sed malsaĝulo elmontras malsaĝecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Malbona sendito falas en malfeliĉon; Sed sendito fidela sanigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Malriĉa kaj hontigata estos tiu, kiu forpuŝas instruon; Sed kiu observas instruon, tiu estos estimata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Deziro plenumita estas agrabla por la animo; Sed malagrable por la malsaĝuloj estas deturni sin de malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Kiu iras kun saĝuloj, tiu estos saĝa; Sed kamarado de malsaĝuloj suferos doloron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Pekulojn persekutas malbono; Sed virtulojn rekompencas bono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Bonulo heredigas la nepojn; Kaj por virtulo konserviĝas la havo de pekulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Multe da manĝaĵo estas sur la kampo de malriĉuloj; Sed multaj pereas pro manko de justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Kiu ŝparas sian vergon, tiu malamas sian filon; Sed kiu lin amas, tiu baldaŭ lin punas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Virtulo manĝas, por satigi sian animon; Sed la ventro de malvirtuloj havas mankon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Saĝa virino konstruas sian domon; Sed malsaĝa detruas ĝin per siaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Kiu iras la ĝustan vojon, tiu timas la Eternulon; Sed kiu iras vojon malĝustan, tiu Lin malestimas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'En la buŝo de malsaĝulo estas vergo por lia malhumileco; Sed la buŝo de saĝuloj ilin gardas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Se ne ekzistas bovoj, la grenejoj estas malplenaj; Sed multe da profito estas de la forto de bovoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Verama atestanto ne mensogas; Sed atestanto falsama elspiras mensogojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Mokanto serĉas saĝecon kaj ĝin ne trovas; Sed por saĝulo la sciado estas facila.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Foriru de homo malsaĝa; Ĉar vi ne aŭdos parolon de saĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'La saĝeco de saĝulo estas komprenado de sia vojo; Kaj la malsaĝeco de malsaĝuloj estas trompiĝado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Malsaĝuloj ŝercas pri siaj kulpoj; Sed inter virtuloj ekzistas reciproka favoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Koro scias sian propran malĝojon; Kaj en ĝia ĝojo ne partoprenas fremdulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Domo de malvirtuloj estos ekstermita; Sed dometo de virtuloj floros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Iufoje vojo ŝajnas ĝusta al homo, Kaj tamen ĝia fino kondukas al la morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Ankaŭ dum ridado povas dolori la koro; Kaj la fino de ĝojo estas malĝojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Laŭ siaj agoj manĝos homo malbonkora; Kaj homo bona satiĝos per siaj faroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Naivulo kredas ĉiun vorton; Sed saĝulo estas atenta pri sia vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Saĝulo timas, kaj forkliniĝas de malbono; Sed malsaĝulo estas incitiĝema kaj memfidema.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'Malpacienculo faras malsaĝaĵojn; Kaj malbonintenculo estas malamata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Naivuloj akiras malsaĝecon; Sed saĝuloj estas kronataj de klereco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Malbonuloj humiliĝos antaŭ bonuloj; Kaj malvirtuloj estos antaŭ la pordego de virtulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Malriĉulo estas malamata eĉ de sia proksimulo; Sed riĉulo havas multe da amikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Kiu malŝatas sian proksimulon, tiu estas pekulo; Sed kiu kompatas malriĉulojn, tiu estas feliĉa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Ĉu ne eraras malbonintenculoj? Sed favorkoreco kaj vero estas ĉe tiuj, kiuj havas bonajn intencojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'De ĉiu laboro estos profito; Sed de babilado venas nur senhaveco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Propra riĉeco estas krono por la saĝuloj; Sed la malsaĝeco de la malsaĝuloj restas malsaĝeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Verparola atestanto savas animojn; Sed malverparola elspiras trompon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'En la timo antaŭ la Eternulo estas forta fortikaĵo; Kaj Li estos rifuĝejo por Siaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'La timo antaŭ la Eternulo estas fonto de vivo, Por evitigi la retojn de la morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'Grandeco de popolo estas gloro por reĝo; Kaj manko de popolo pereigas la reganton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Pacienculo havas multe da saĝo; Sed malpacienculo elmontras malsaĝecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Trankvila koro estas vivo por la korpo; Sed envio estas puso por la ostoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Kiu premas malriĉulon, tiu ofendas lian Kreinton; Kaj kiu Lin honoras, tiu kompatas malriĉulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'Pro sia malboneco malvirtulo estos forpuŝita; Sed virtulo eĉ mortante havas esperon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'En la koro de saĝulo ripozas saĝo; Kaj kio estas en malsaĝuloj, tio elmontriĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Virto altigas popolon; Sed peko pereigas gentojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Favoron de la reĝo havas sklavo saĝa; Sed kontraŭ malbonkonduta li koleras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Milda respondo kvietigas koleron; Sed malmola vorto ekscitas koleron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'La lango de saĝuloj bonigas la instruon; Sed la buŝo de malsaĝuloj elparolas sensencaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Sur ĉiu loko estas la okuloj de la Eternulo; Ili vidas la malbonulojn kaj bonulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'Milda lango estas arbo de vivo; Sed malbonparola rompas la spiriton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Malsaĝulo malŝatas la instruon de sia patro; Sed kiu plenumas la admonon, tiu estas prudenta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'En la domo de virtulo estas multe da trezoroj; Sed en la profito de malvirtulo estas pereo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'La buŝo de saĝuloj semas instruon; Sed la koro de malsaĝuloj ne estas tia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Oferdono de malvirtuloj estas abomenaĵo por la Eternulo; Sed la preĝo de virtuloj al Li plaĉas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Abomenaĵo por la Eternulo estas la vojo de malvirtulo; Sed kiu celas virton, tiun Li amas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Malbona puno atendas tiun, kiu forlasas la vojon; Kaj la malamanto de admono mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Ŝeol kaj la abismo estas antaŭ la Eternulo: Tiom pli la koroj de la homidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Mokanto ne amas tiun, kiu lin admonas; Al saĝuloj li ne iras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Ĝoja koro faras la vizaĝon ĝoja; Sed ĉe ĉagreno de la koro la spirito estas malgaja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'La koro de saĝulo serĉas instruon; Sed la buŝo de malsaĝuloj nutras sin per malsaĝeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Ĉiuj tagoj de malfeliĉulo estas malbonaj; Sed kontenta koro estas festenado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Pli bona estas malmulto kun timo antaŭ la Eternulo, Ol granda trezoro kun maltrankvileco ĉe ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Pli bona estas manĝo el verdaĵo, sed kun amo, Ol grasa bovo, sed kun malamo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'Kolerema homo kaŭzas malpacon; Kaj pacienculo kvietigas disputon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'La vojo de maldiligentulo estas kiel dornarbeto; Sed la vojo de virtuloj estas ebenigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Saĝa filo ĝojigas la patron; Sed homo malsaĝa estas malhonoro por sia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Malsaĝeco estas ĝojo por malsaĝulo; Sed homo prudenta iras ĝustan vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Kie ne estas konsilo, tie la entreprenoj neniiĝas; Sed ĉe multe da konsilantoj ili restas fortikaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Plezuro por homo estas en la respondo de lia buŝo; Kaj kiel bona estas vorto en la ĝusta tempo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'La vojo de la vivo por saĝulo iras supren, Por ke li evitu Ŝeolon malsupre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'La domon de fieruloj la Eternulo ruinigas; Sed Li gardas la limojn de vidvino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Abomenaĵo por la Eternulo estas la intencoj de malnoblulo; Sed agrablaj estas la paroloj de puruloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Profitemulo malĝojigas sian domon; Sed kiu malamas donacojn, tiu vivos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'La koro de virtulo pripensas respondon; Sed la buŝo de malvirtuloj elfluigas malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'La Eternulo estas malproksima de la malvirtuloj; Sed la preĝon de la virtuloj Li aŭskultas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Luma okulo ĝojigas la koron; Bona sciigo fortikigas la ostojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Orelo, kiu aŭskultas la instruon de la vivo, Loĝos inter saĝuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Kiu forpuŝas admonon, tiu malestimas sian animon; Sed kiu aŭskultas instruon, tiu akiras saĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'La timo antaŭ la Eternulo instruas saĝon, Kaj humileco troviĝas antaŭ honoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Al la homo apartenas la projektoj de la koro; Sed de la Eternulo venas la vortoj de la lango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Ĉiuj vojoj de la homo estas puraj en liaj okuloj; Sed la Eternulo esploras la spiritojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Transdonu al la Eternulo viajn farojn; Tiam viaj entreprenoj staros forte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Ĉiu faro de la Eternulo havas sian celon; Eĉ malvirtulo estas farita por tago de malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Ĉiu malhumilulo estas abomenaĵo por la Eternulo; Kaj li certe ne restos ne punita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Per bono kaj vero pardoniĝas peko; Kaj per timo antaŭ la Eternulo oni evitas malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Kiam al la Eternulo plaĉas la vojoj de homo, Li eĉ liajn malamikojn pacigas kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Pli bona estas malmulto, sed kun justeco, Ol granda profito, sed maljusta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'La koro de homo pripensas sian vojon; Sed la Eternulo direktas lian iradon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Sorĉo estas sur la lipoj de reĝo; Lia buŝo ne peku ĉe la juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Ĝusta pesilo kaj ĝustaj pesiltasoj estas de la Eternulo; Ĉiuj pezilŝtonoj en la sako estas Lia faro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Abomenaĵo por reĝoj estas fari maljustaĵon; Ĉar per justeco staras fortike la trono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Al la reĝoj plaĉas lipoj veramaj; Kaj ili amas tiun, kiu parolas la veron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Kolero de reĝo estas kuriero de morto; Sed homo saĝa igas ĝin pardoni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'Luma vizaĝo de reĝo estas vivo; Kaj lia favoro estas kiel nubo kun printempa pluvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Akiro de saĝeco estas multe pli bona ol oro; Kaj akiro de prudento estas preferinda ol arĝento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'La vojo de virtuloj evitas malbonon; Kiu gardas sian vojon, tiu konservas sian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Antaŭ la pereo iras fiereco; Kaj antaŭ la falo iras malhumileco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Pli bone estas esti humila kun malriĉuloj, Ol dividi akiron kun fieruloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Kiu prudente kondukas aferon, tiu trovos bonon; Kaj kiu fidas la Eternulon, tiu estas feliĉa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Kiu havas prudentan koron, tiu estas nomata saĝulo; Kaj agrablaj paroloj plivalorigas la instruon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Saĝo estas fonto de vivo por sia posedanto; Sed la instruo de malsaĝuloj estas malsaĝeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'La koro de saĝulo prudentigas lian buŝon, Kaj en lia buŝo plivaloriĝas la instruo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Agrabla parolo estas freŝa mielo, Dolĉa por la animo kaj saniga por la ostoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Iufoje vojo ŝajnas ĝusta al homo, Kaj tamen ĝia fino kondukas al la morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'Kiu laboras, tiu laboras por si mem; Ĉar lin devigas lia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'Malbona homo kaŭzas malbonon; Kaj sur liaj lipoj estas kvazaŭ brulanta fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'Malica homo disvastigas malpacon; Kaj kalumnianto disigas amikojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'Rabemulo forlogas sian proksimulon Kaj kondukas lin sur vojo malbona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Kiu faras signojn per la okuloj, tiu intencas malicon; Kiu faras signojn per la lipoj, tiu plenumas malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Krono de gloro estas la grizeco; Sur la vojo de justeco ĝi estas trovata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Pacienculo estas pli bona ol fortulo; Kaj kiu regas sian spiriton, tiu estas pli bona ol militakiranto de urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'Sur la baskon oni ĵetas loton; Sed ĝia tuta decido estas de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Pli bona estas seka peco da pano, sed kun trankvileco, Ol domo plena de viando, kun malpaco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Saĝa sklavo regos super filo hontinda, Kaj dividos heredon kune kun fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Fandujo estas por arĝento, kaj forno por oro; Sed la korojn esploras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Malbonfaranto obeas malbonajn buŝojn; Malveremulo atentas malpian langon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Kiu mokas malriĉulon, tiu ofendas lian Kreinton; Kiu ĝojas pri ies malfeliĉo, tiu ne restos sen puno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Nepoj estas krono por maljunuloj; Kaj gloro por infanoj estas iliaj gepatroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Al malsaĝulo ne konvenas alta parolado, Kaj ankoraŭ malpli al nobelo mensogado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Donaco estas juvelo en la okuloj de sia mastro; Kien ajn li sin turnos, li sukcesos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Kiu kovras kulpon, tiu serĉas amikecon; Sed kiu reparolas pri la afero, tiu disigas amikojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Pli efikas riproĉo ĉe saĝulo, Ol cent batoj ĉe malsaĝulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Malbonulo serĉas nur ribelon; Sed terura sendato estos sendita kontraŭ lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Pli bone estas renkonti ursinon, al kiu estas rabitaj ĝiaj infanoj, Ol malsaĝulon kun lia malsaĝeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Kiu redonas malbonon por bono, El ties domo ne malaperos malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'La komenco de malpaco estas kiel liberigo de akvo; Antaŭ ol ĝi tro vastiĝis, forlasu la malpacon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Kiu pravigas malvirtulon, kaj kiu malpravigas virtulon, Ambaŭ estas abomenaĵo por la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Por kio servas mono en la mano de malsaĝulo? Ĉu por aĉeti saĝon, kiam li prudenton ne havas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'En ĉiu tempo amiko amas, Kaj li fariĝas frato en mizero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Homo malsaĝa donas manon en manon, Kaj garantias por sia proksimulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Kiu amas malpacon, tiu amas pekon; Kiu tro alte levas sian pordon, tiu serĉas pereon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Malica koro ne trovos bonon; Kaj kiu havas neĝustan langon, tiu enfalos en malfeliĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Kiu naskas malsaĝulon, tiu havas ĉagrenon; Kaj patro de malprudentulo ne havos ĝojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Ĝoja koro estas saniga; Kaj malĝoja spirito sekigas la ostojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Kaŝitajn donacojn akceptas malvirtulo, Por deklini la vojon de la justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'Antaŭ la vizaĝo de prudentulo estas saĝo; Sed la okuloj de malsaĝulo estas en la fino de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'Filo malsaĝa estas ĉagreno por sia patro, Kaj malĝojo por sia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Ne estas bone suferigi virtulon, Nek bati noblulon, kiu agas juste.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Kiu ŝparas siajn vortojn, tiu estas prudenta; Kaj trankvilanimulo estas homo saĝa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Eĉ malsaĝulo, se li silentas, estas rigardata kiel saĝulo; Kaj kiel prudentulo, se li tenas fermita sian buŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Kiu apartiĝas, tiu serĉas sian volupton Kaj iras kontraŭ ĉiu saĝa konsilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Malsaĝulo ne deziras prudenton, Sed nur malkovri sian koron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Kiam venas malvirtulo, Venas ankaŭ malestimo kun honto kaj moko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'La vortoj de homa buŝo estas profunda akvo; La fonto de saĝo estas fluanta rivero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Ne estas bone favori malvirtulon, Por faligi virtulon ĉe la juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'La lipoj de malsaĝulo kondukas al malpaco, Kaj lia buŝo venigas batojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'La buŝo de malsaĝulo estas pereo por li, Kaj liaj lipoj enretigas lian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'La vortoj de kalumnianto estas kiel frandaĵoj, Kaj ili penetras en la profundon de la ventro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Kiu estas senzorga en sia laborado, Tiu estas frato de pereiganto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'La nomo de la Eternulo estas fortika turo: Tien kuras virtulo, kaj estas ŝirmata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'La havo de riĉulo estas lia fortika urbo, Kaj kiel alta muro en lia imago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Antaŭ la pereo la koro de homo fieriĝas, Kaj antaŭ honoro estas humileco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Kiu respondas, antaŭ ol li aŭdis, Tiu havas malsaĝon kaj honton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'La spirito de homo nutras lin en lia malsano; Sed spiriton premitan kiu povas elporti?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'La koro de saĝulo akiras prudenton, Kaj la orelo de saĝuloj serĉas scion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Donaco de homo donas al li vastecon Kaj kondukas lin al la grandsinjoroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'La unua estas prava en sia proceso; Sed venas lia proksimulo kaj ĝin klarigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'La loto ĉesigas disputojn Kaj decidas inter potenculoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Malpaciĝinta frato estas pli obstina, ol fortikigita urbo; Kaj disputoj estas kiel rigliloj de turo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'De la fruktoj de la buŝo de homo satiĝas lia ventro; Li manĝas la produktojn de siaj lipoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'Morto kaj vivo dependas de la lango; Kaj kiu ĝin amas, tiu manĝos ĝiajn fruktojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Kiu trovis edzinon, tiu trovis bonon Kaj ricevis favoron de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Per petegado parolas malriĉulo; Kaj riĉulo respondas arogante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Havi multajn amikojn estas embarase; Sed ofte amiko estas pli sindona ol frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Pli bona estas malriĉulo, kiu iras en sia senkulpeco, Ol homo, kiu estas malicbuŝulo kaj malsaĝulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Vivo sen prudento ne estas bona; Kaj kiu tro rapidas, tiu maltrafas la vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'Malsaĝeco de homo erarigas lian vojon, Kaj lia koro koleras la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Riĉeco donas multon da amikoj; Sed malriĉulo estas forlasata de sia amiko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Falsa atestanto ne restos sen puno; Kaj kiu elspiras mensogojn, tiu ne saviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Multaj serĉas favoron de malavarulo; Kaj ĉiu estas amiko de homo, kiu donas donacojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Ĉiuj fratoj de malriĉulo lin malamas; Tiom pli malproksimiĝas de li liaj amikoj! Li havas esperon pri vortoj, kiuj ne estos plenumitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Kiu akiras prudenton, tiu amas sian animon; Kiu gardas saĝon, tiu trovas bonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Falsa atestanto ne restos sen puno; Kaj kiu elspiras mensogojn, tiu pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Al malsaĝulo ne konvenas agrablaĵo; Ankoraŭ malpli konvenas al sklavo regi super princoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Saĝo de homo faras lin pacienca; Kaj gloro por li estas pardoni pekon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Kiel kriego de leono estas la kolero de reĝo; Kaj lia favoro estas kiel roso sur herbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Pereo por sia patro estas malsaĝa filo; Kaj malpacema edzino estas kiel konstanta gutado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Domo kaj havo estas heredataj post gepatroj; Sed saĝa edzino estas de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'Mallaboremeco enigas en profundan dormon, Kaj animo maldiligenta suferos malsaton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Kiu konservas moralordonon, tiu konservas sian animon; Sed kiu ne atentas Lian vojon, tiu mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Kiu kompatas malriĉulon, tiu pruntedonas al la Eternulo, Kaj Tiu redonos al li por lia bonfaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Punu vian filon, dum ekzistas espero, Sed via koro ne deziru lian pereon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Koleranto devas esti punata; Ĉar se vi lin indulgos, li fariĝos ankoraŭ pli kolerema.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Aŭskultu konsilon kaj akceptu admonon, Por ke vi poste estu saĝa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Multaj estas la intencoj en la koro de homo, Sed la decido de la Eternulo restas fortike.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Ornamo estas por la homo lia bonfaro; Kaj pli bona estas malriĉulo, ol homo mensogema.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Timo antaŭ la Eternulo kondukas al vivo, Al sateco, kaj al evito de malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Mallaboremulo metas sian manon en la poton, Kaj eĉ al sia buŝo li ĝin ne relevas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Se vi batos blasfemanton, sensciulo fariĝos atenta; Se oni punas saĝulon, li komprenas la instruon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Kiu ruinigas patron kaj forpelas patrinon, Tiu estas filo hontinda kaj malbeninda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Ĉesu, mia filo, aŭskulti admonon Kaj tamen dekliniĝi de la vortoj de la instruo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Fripona atestanto mokas juĝon; Kaj la buŝo de malvirtuloj englutas maljustaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'La blasfemantojn atendas punoj, Kaj batoj la dorson de malsaĝuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'La vino estas blasfemanto, ebriiga trinkaĵo estas sovaĝa; Kaj kiu delogiĝas per ili, tiu ne estas prudenta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Minaco de reĝo estas kiel kriego de leono; Kiu lin kolerigas, tiu pekas kontraŭ sia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'Estas honoro por homo ĉesigi malpacon; Sed ĉiu malsaĝulo estas malpacema.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'En la malvarma tempo mallaborulo ne plugas; Li petos en aŭtuno, kaj li nenion ricevos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Intenco en la koro de homo estas profunda akvo; Sed homo saĝa ĝin elĉerpos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Multaj homoj proklamas pri sia boneco; Sed kiu trovos homon fidelan?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Virtulo iras en sia senpekeco; Feliĉaj estas liaj infanoj post li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Reĝo, kiu sidas sur trono de juĝo, Disventumas per siaj okuloj ĉion malbonan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Kiu povas diri: Mi purigis mian koron, Mi estas libera de mia peko?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Neegalaj peziloj, neegalaj mezuroj, Ambaŭ estas abomenaĵo por la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Eĉ knabon oni povas ekkoni laŭ liaj faroj, Ĉu estas pura kaj justa lia konduto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Orelon aŭdantan kaj okulon vidantan: Ilin ambaŭ kreis la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Ne amu dormon, por ke vi ne malriĉiĝu; Malfermu viajn okulojn, kaj vi satiĝos de pano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, 'Malbona, malbona, diras la aĉetanto; Sed kiam li foriris, tiam li fanfaronas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Oni povas havi oron kaj multe da perloj; Sed buŝo prudenta estas multevalora ilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Prenu la veston de tiu, kiu garantiis por aliulo; Kaj pro la fremduloj prenu de li garantiaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Malhonesta pano estas bongusta por homo; Sed lia buŝo poste estos plena de ŝtonetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Intencoj fortikiĝas per konsilo; Kaj militon oni faru prudente.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Kiu malkaŝas sekreton, tiu estas kiel kalumnianto; Ne komunikiĝu kun tiu, kiu havas larĝan buŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Kiu malbenas sian patron kaj sian patrinon, Ties lumilo estingiĝos meze de profunda mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Heredo, al kiu oni komence tro rapidas, Ne estas benata en sia fino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Ne diru: Mi repagos malbonon; Fidu la Eternulon, kaj Li vin helpos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Neegalaj peziloj estas abomenaĵo por la Eternulo, Kaj malvera pesilo estas ne bona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'La irado de homo dependas de la Eternulo; Kiel homo povus kompreni sian vojon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Ĝi estas reto por homo, se li rapidas nomi ion sankta Kaj esploras nur post faro de promeso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Saĝa reĝo dispelas malvirtulojn, Kaj venigas radon sur ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'La animo de homo estas lumilo de la Eternulo; Ĝi esploras ĉiujn internaĵojn de la korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'Favorkoreco kaj veremeco hardas reĝon; Kaj per favorkoreco li subtenas sian tronon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Gloro por junuloj estas ilia forto, Kaj ornamo por maljunuloj estas grizeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Vundoj de batoj devas penetri en malbonulon, Kaj frapoj devas iri profunde en lian korpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Kiel akvaj torentoj estas la koro de reĝo en la mano de la Eternulo: Kien Li volas, Li ĝin direktas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Ĉiuj vojoj de homo estas ĝustaj en liaj okuloj; Sed la Eternulo pesas la korojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Plenumado de vero kaj justeco Estas al la Eternulo pli agrabla ol oferado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Fieraj okuloj kaj aroganta koro, Kulturaĵo de malvirtuloj, estas peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'La entreprenoj de diligentulo donas nur profiton; Sed ĉiu trorapidado kondukas nur al manko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Akirado de trezoroj per lango mensogema Estas vanta bloveto, retoj de morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'La rabo de malvirtuloj atakos ilin mem; Ĉar ili ne volis fari justaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Malrekta estas la vojo de homo kulpa; Sed la agado de purulo estas ĝusta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Pli bone estas loĝi sur angulo de tegmento, Ol kun malpacema edzino en komuna domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'La animo de malvirtulo deziras malbonon; Lia proksimulo ne estas favorata de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Kiam blasfemanto estas punata, senspertulo fariĝas pli saĝa; Kaj kiam oni instruas saĝulon, li akiras prudenton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'La Justulo rigardas la domon de malvirtulo, Kaj Li faligas malvirtulojn en malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Se iu ŝtopas sian orelon kontraŭ kriado de malriĉulo, Li ankaŭ vokos kaj ne estos aŭskultata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Sekreta donaco kvietigas koleron, Kaj donaco en la sinon, fortan furiozon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Farado de justaĵo estas ĝojo por la virtulo Kaj teruro por la malbonaguloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Homo, kiu erarforiĝis de la vojo de prudento, Ekloĝos en komunumo de mortintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Kiu amas gajecon, tiu havos mankon; Kiu amas vinon kaj oleon, tiu ne estos riĉa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'La malvirtulo estos liberiga anstataŭo por la virtulo, Kaj malpiulo por piuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Pli bone estas loĝi en lando dezerta, Ol kun malpacema kaj kolerema edzino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Ĉarma trezoro kaj oleo estas en la domo de saĝulo; Sed homo malsaĝa ĉion englutas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Kiu celas justecon kaj bonecon, Tiu trovos vivon, justecon, kaj honoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'Kontraŭ urbon de fortuloj eliras saĝulo, Kaj li faligas ĝian fortan fortikaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Kiu gardas sian buŝon kaj sian langon, Tiu gardas sian animon kontraŭ malfeliĉoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Fiera malbonulo, kiun oni nomas blasfemulo, Agas kun kolero kaj malboneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'La deziro de mallaborulo lin mortigas, Ĉar liaj manoj ne volas labori.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Tuttage li forte deziras; Sed virtulo donas kaj ne rifuzas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Oferdono de malvirtuloj estas abomenaĵo; Kiom pli, kiam li ĝin alportas kiel pekoferon!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Mensoga atestanto pereos; Sed homo, kiu mem aŭdis, parolos por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Malvirtulo tenas sian vizaĝon arogante; Sed virtulo zorgas pri sia vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Ne ekzistas saĝo, ne ekzistas prudento, Ne ekzistas konsilo kontraŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Ĉevalo estas preparata por la tago de milito; Sed la helpo venas de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Nomo bona estas pli preferinda, ol granda riĉeco; Kaj bona estimo, ol arĝento kaj oro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Riĉulo kaj malriĉulo renkontiĝas: Ilin ambaŭ kreis la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Prudentulo antaŭvidas malbonon, kaj kaŝiĝas; Sed naivuloj antaŭenpaŝas, kaj difektiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Por humileco kaj timo antaŭ la Eternulo Oni ricevas riĉecon kaj honoron kaj vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Dornoj kaj retoj estas sur la vojo de malbonagulo; Kiu gardas sian animon, tiu malproksimiĝas de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Instruu knabon konforme al lia vojo, Kaj eĉ maljuniĝinte li ne dekliniĝos de ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Riĉulo regas super malriĉuloj, Kaj kiu prunteprenas, tiu estas sklavo de la pruntedoninto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Kiu semas maljustaĵon, tiu rikoltos suferon, Kaj la kano de lia krueleco rompiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Bonokululo estos benata; Ĉar li donas el sia pano al malriĉulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Forpelu blasfemulon, kaj foriros malpaco, Kaj ĉesiĝos malkonsento kaj ofendo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Kiu amas purecon de koro kaj agrable parolas, Al tiu la reĝo estas amiko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'La okuloj de la Eternulo gardas la prudenton; Sed la vortojn de maliculo Li renversas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Mallaborulo diras: Leono estas ekstere, Mi povus esti mortigita meze de la strato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'La buŝo de malĉastulino estas profunda foso; Kiun la Eternulo koleras, tiu tien enfalas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'Malsaĝeco forte sidas en la koro de knabo; Sed vergo punanta ĝin elpelas el ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Kiu premas malriĉulon, por pligrandigi sian riĉecon, Tiu donas al riĉulo, por ke li malriĉiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Klinu vian orelon kaj aŭskultu vortojn de saĝuloj, Kaj direktu vian koron al mia instruo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'Ĉar ili estos agrablaj, se vi gardos ilin en via interno; Ili estos ĉiuj pretaj sur viaj lipoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Ke al la Eternulo estu via fido, Tion mi instruis al vi hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Ĉu mi ne skribis al vi tion trifoje Kun konsiloj kaj scio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'Por sciigi al vi la ĝustecon de la paroloj de vero, Por ke vi transdonu la parolojn de vero al tiuj, kiuj vin sendis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Ne prirabu malriĉulon, pro tio, ke li estas malriĉa; Kaj ne premu senhavulon ĉe la pordego;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'Ĉar la Eternulo defendos ilian aferon Kaj dispremos iliajn premantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Ne amikiĝu kun homo kolerema, Kaj ne komunikiĝu kun homo flamiĝema;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'Ke vi ne lernu lian vojon Kaj ne ricevu reton por via animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Ne estu inter tiuj, kiuj firmigas per mano, Kiuj garantias por ŝuldoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Se vi ne havos per kio pagi, Oni ja prenos vian litaĵon de sub vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Ne forŝovu la antikvajn limojn, Kiujn faris viaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Se vi vidas homon lertan en sia profesio, li staros antaŭ reĝoj; Li ne staros antaŭ maleminentuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Kiam vi sidiĝos, por manĝi kun reganto, Rigardu bone, kio estas antaŭ vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'Kaj vi metu tranĉilon al via gorĝo, Se vi estas avidulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Ne deziru liajn bongustajn manĝojn; Ĉar ĝi estas trompa pano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Ne penu riĉiĝi; Forlasu vian pripensadon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Ĉu vi direktos viajn okulojn al ĝi? ĝi jam ne ekzistos; Ĉar riĉeco faras al si flugilojn kiel aglo, kaj forflugas al la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Ne manĝu panon de malbondeziranto, Kaj ne deziru liajn bongustajn manĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'Ĉar kiaj estas la pensoj en lia animo, tia li ankaŭ estas: Manĝu kaj trinku, li diros al vi, Sed lia koro ne estas kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'La pecon, kiun vi manĝis, vi elvomos; Kaj vane vi perdis viajn agrablajn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'En la orelojn de malsaĝulo ne parolu; Ĉar li malŝatos la saĝecon de viaj vortoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Ne forŝovu la antikvajn limojn, Kaj sur la kampon de orfoj ne iru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Ĉar ilia Liberiganto estas forta; Li defendos ilian aferon kontraŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Elmetu vian koron al instruo Kaj viajn orelojn al paroloj de prudento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Ne malvolu puni knabon: Se vi batos lin per kano, li ne mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Vi batos lin per kano, Kaj lian animon vi savos de Ŝeol.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Mia filo, se via koro estos saĝa, Tiam ĝojos ankaŭ mia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'Kaj mia internaĵo ĝojos, Kiam viaj lipoj parolos ĝustaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Via koro sin tiru ne al pekuloj, Sed al timo antaŭ la Eternulo ĉiutage.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'Ĉar ekzistas estonteco, Kaj via espero ne perdiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Aŭskultu vi, mia filo, kaj estu saĝa, Kaj direktu vian koron al la ĝusta vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Ne estu inter la drinkantoj de vino, Inter tiuj, kiuj manĝas tro da viando;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'Ĉar drinkemulo kaj manĝegemulo malriĉiĝos, Kaj dormemulo havos sur si ĉifonaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Aŭskultu vian patron, kiu vin naskigis, Kaj ne malŝatu vian patrinon, kiam ŝi maljuniĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Veron aĉetu, kaj ne vendu saĝon Kaj instruon kaj prudenton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Grandan ĝojon havas patro de virtulo, Kaj naskinto de saĝulo ĝojos pro li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Via patro kaj via patrino ĝojos, Kaj via naskintino triumfos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Donu, mia filo, vian koron al mi, Kaj al viaj okuloj plaĉu miaj vojoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Ĉar malĉastulino estas profunda foso, Kaj fremda edzino estas malvasta puto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'Ŝi embuskas kiel rabisto, Kaj kolektas ĉirkaŭ si perfidulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Ĉe kiu estas ploro? ĉe kiu estas ĝemoj? ĉe kiu estas malpaco? Ĉe kiu estas plendoj? ĉe kiu estas senkaŭzaj batoj? Ĉe kiu estas malklaraj okuloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Ĉe tiuj, kiuj sidas malfrue ĉe vino, Ĉe tiuj, kiuj venas, por gustumi aroman trinkaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Ne rigardu la vinon, kiel ruĝa ĝi estas, Kiel ĝi brilas en la pokalo, kiel glate ĝi eniras:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'En la fino ĝi mordas kiel serpento Kaj pikas kiel vipuro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Viaj okuloj vidos fremdaĵojn, Kaj via koro parolos malĝustaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'Kaj vi estos kiel dormanto meze de la maro, Kaj kiel dormanto sur la supro de masto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, 'Ili batis min, sed ĝi min ne doloris; Ili frapis min, sed mi ne sentis; Kiam mi vekiĝos, mi denove tion serĉos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Ne sekvu malbonajn homojn, Kaj ne deziru esti kun ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'Ĉar ilia koro pensas pri perfortaĵo, Kaj ilia buŝo parolas malbonaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Per saĝo konstruiĝas domo, Kaj per prudento ĝi fortikiĝas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'Kaj per sciado la ĉambroj pleniĝas Per ĉia havo grandvalora kaj agrabla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'Homo saĝa havas forton, Kaj homo prudenta estas potenca.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Kun pripenso faru militon; Kaj venko venas per multe da konsilantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Tro alta estas la saĝo por malsaĝulo; Ĉe la pordego li ne malfermos sian buŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Kiu intencas fari malbonon, Tiun oni nomas maliculo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Malico de malsaĝulo estas peko; Kaj blasfemanto estas abomenaĵo por homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Se vi montriĝis malforta en tago de mizero, Via forto estas ja malgranda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Savu tiujn, kiujn oni prenis por mortigi, Kaj ne fortiriĝu de tiuj, kiuj estas kondamnitaj al morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Se vi diras: Ni tion ne sciis, La esploranto de koroj ja komprenas, Kaj la gardanto de via animo ja scias, Kaj Li redonas al homo laŭ liaj faroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Manĝu, mia filo, mielon, ĉar ĝi estas bona; Kaj la mieltavolo estas dolĉa por via gorĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Tia estas por via animo la sciado de saĝo, se vi ĝin trovis, Kaj ekzistas estonteco, kaj via espero ne pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Ne insidu, ho malvirtulo, kontraŭ la domo de virtulo; Ne ataku lian ripozejon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Ĉar sep fojojn virtulo falos, kaj tamen leviĝos; Sed malvirtuloj implikiĝas en la malfeliĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Kiam falas via malamiko, ne ĝoju, Kaj ĉe lia malfeliĉo via koro ne plezuriĝu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'Ĉar eble la Eternulo vidos, kaj tio ne plaĉos al Li, Kaj Li returnos de li Sian koleron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Ne koleru kontraŭ malbonfarantoj, Kaj ne enviu la malvirtulojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'Ĉar la malbonulo ne havos estontecon; La lumilo de malvirtuloj estingiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Timu, mia filo, la Eternulon kaj la reĝon; Kun ribeluloj ne komunikiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'Ĉar subite venos ilia pereo; Kaj kiu scias, kiam venos la puno de ambaŭ?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Ankaŭ ĉi tio estas vortoj de saĝuloj: Konsideri personojn ĉe juĝado estas ne bone.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Kiu diras al malvirtulo: Vi estas virtulo, Tiun malbenos popoloj, tiun malamos gentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'Sed kiuj faras riproĉojn, tiuj plaĉas, Kaj sur ilin venos bona beno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Kiu respondas ĝustajn vortojn, Tiu kisas per la lipoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Plenumu vian laboron ekstere, Pretigu ĉion sur via kampo; Kaj poste aranĝu vian domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Ne atestu sen kaŭzo kontraŭ via proksimulo; Ĉu vi trompus per via buŝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Ne diru: Kiel li agis kontraŭ mi, tiel mi agos kontraŭ li; Mi redonos al la homo laŭ lia faro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Mi pasis tra kampo de homo maldiligenta Kaj tra vinberĝardeno de sensaĝulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'Kaj jen ĉie elkreskis urtiko, Ĉio estas kovrita de dornoj, Kaj la ŝtona muro estas detruita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Kaj kiam mi vidis, mi prenis ĝin en mian koron, Mi rigardis, kaj ricevis instruon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Iom da dormo, iom da dormeto, Iom da kunmeto de la manoj por kuŝado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'Kaj venos via malriĉeco kiel rabisto, Kaj via senhaveco kiel viro armita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Ankaŭ ĉi tio estas sentencoj de Salomono, kiujn kolektis la viroj de Ĥizkija, reĝo de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Honoro de Dio estas kaŝi aferon; Sed honoro de reĝoj estas esplori aferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'La ĉielo estas alta, la tero estas profunda, Kaj la koro de reĝoj estas neesplorebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Forigu de arĝento la almiksaĵon, Kaj la puriganto ricevos vazon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Forigu malvirtulon de la reĝo, Kaj lia trono fortikiĝos en justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Ne montru vin granda antaŭ la reĝo, Kaj sur la loko de eminentuloj ne stariĝu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'Ĉar pli bone estas, se oni diros al vi: Leviĝu ĉi tien, Ol se oni malaltigos vin antaŭ eminentulo, Kiun vidis viaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Ne komencu tuj disputi; Ĉar kion vi faros poste, kiam via proksimulo vin hontigos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Faru disputon kun via proksimulo mem, Sed sekreton de aliulo ne malkaŝu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'Ĉar alie aŭdanto vin riproĉos, Kaj vian babilon vi jam ne povos repreni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Vorto dirita en ĝusta tempo Estas kiel oraj pomoj sur retaĵo arĝenta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Kiel ora orelringo kaj multekosta kolringo, Tiel estas saĝa admonanto por aŭskultanta orelo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Kiel malvarmo de neĝo en la tempo de rikolto, Tiel estas fidela sendito por siaj sendintoj: Li revigligas la animon de sia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Kiel nuboj kaj vento sen pluvo, Tiel estas homo, kiu fanfaronas per dono, kiun li ne faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Per pacienco oni altiras al si potenculon, Kaj mola parolo rompas oston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Kiam vi trovis mielon, manĝu, kiom vi bezonas, Por ke vi ne fariĝu tro sata kaj ne elvomu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Detenu vian piedon de la domo de via proksimulo; Ĉar alie vi tedus lin kaj li vin malamus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Kiel martelo kaj glavo kaj akra sago Estas tiu homo, kiu parolas pri sia proksimulo malveran ateston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Kiel putra dento kaj malforta piedo Estas nefidinda espero en tago de mizero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Kiel demeto de vesto en tempo de malvarmo, kiel vinagro sur natro, Tiel estas kantado de kantoj al koro suferanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Se via malamanto estas malsata, manĝigu al li panon; Kaj se li estas soifa, trinkigu al li akvon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'Ĉar fajrajn karbojn vi kolektos sur lia kapo, Kaj la Eternulo vin rekompencos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Norda vento kaŭzas pluvon, Kaj ĉagrenita vizaĝo kaŝatan parolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Pli bone estas loĝi sur angulo de tegmento, Ol kun malpacema edzino en komuna domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Kiel malvarma akvo por suferanto de soifo, Tiel estas bona sciigo el lando malproksima.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Virtulo, kiu falas antaŭ malvirtulo, Estas malklara fonto kaj malbonigita puto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Ne bone estas manĝi tro multe da mielo; Kaj ne glore estas serĉi sian gloron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'Homo, kiu ne povas regi sian spiriton, Estas urbo detruita, kiu ne havas muron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Kiel neĝo en somero, kaj kiel pluvo en tempo de rikolto, Tiel ne konvenas honoro por malsaĝulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Kiel birdo forleviĝas, kiel hirundo forflugas, Tiel senkaŭza malbeno ne efektiviĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Vipo estas por ĉevalo, brido por azeno, Kaj bastono por la dorso de malsaĝuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Ne respondu al malsaĝulo laŭ lia malsaĝeco, Por ke vi mem ne fariĝu egala al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Respondu al malsaĝulo laŭ lia malsaĝeco, Por ke li ne estu saĝulo en siaj propraj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Kiu komisias aferon al malsaĝulo, Tiu tranĉas al si la piedojn kaj sin suferigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Kiel la kruroj de lamulo pendas peze, Tiel estas sentenco en la buŝo de malsaĝuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Kiel iu, kiu alligas ŝtonon al ĵetilo, Tiel estas tiu, kiu faras honoron al malsaĝulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Kiel dorna kano en la mano de ebriulo, Tiel estas sentenco en la buŝo de malsaĝuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Kompetentulo ĉion bone faras; Sed kiu dungas pasantojn, tiu dungas malsaĝulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Kiel hundo revenas al sia vomitaĵo, Tiel malsaĝulo ripetas sian malsaĝaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Ĉu vi vidas homon, kiu estas saĝa en siaj okuloj? Estas pli da espero por malsaĝulo ol por li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Maldiligentulo diras: Leono estas sur la vojo, Leono estas sur la stratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Pordo turniĝas sur sia hoko, Kaj maldiligentulo sur sia lito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Maldiligentulo ŝovas sian manon en la poton, Kaj ne volas venigi ĝin al sia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Maldiligentulo estas en siaj okuloj pli saĝa, Ol sep veraj saĝuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Pasanto, kiu sin miksas en malpropran disputon, Estas kiel iu, kiu kaptas hundon je la oreloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Kiel frenezulo, kiu ĵetas fajron, Sagojn, kaj morton,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'Tiel estas homo, kiu trompas sian proksimulon, Kaj diras: Mi ja ŝercas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Kie ne estas ligno, estingiĝas la fajro; Kaj se ne estas kalumnianto, ĉesiĝas malpaco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Karbo servas por ardaĵo, ligno por fajro, Kaj homo malpacema por provoki malpacon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'La vortoj de kalumnianto estas kiel frandaĵoj, Kaj ili penetras en la profundon de la ventro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Varmegaj lipoj kun malica koro Estas nepurigita arĝento, kiu kovras argilaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Malamanto havas maskitajn parolojn, Kaj en sia koro li preparas malicon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Kiam li ĉarmigas sian voĉon, ne kredu al li; Ĉar sep abomenaĵoj estas en lia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Kiu trompe kaŝas malamon, Tiu aperigos sian malbonecon en popola kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Kiu fosas foson, tiu falos en ĝin; Kaj kiu rulas ŝtonon, al tiu ĝi revenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'Mensogema lango malamas tiujn, kiujn ĝi dispremis; Kaj hipokrita buŝo kaŭzas pereon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Ne fanfaronu pri la morgaŭa tago; Ĉar vi ne scias, kion naskos la tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Alia vin laŭdu, sed ne via buŝo; Fremdulo, sed ne viaj lipoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Peza estas ŝtono, kaj sablo estas ŝarĝo; Sed kolero de malsaĝulo estas pli peza ol ambaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Kolero estas kruelaĵo, kaj furiozo estas superakvego; Sed kiu sin tenos kontraŭ envio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Pli bona estas riproĉo nekaŝita, Ol amo kaŝita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Fidelkoraj estas la batoj de amanto; Sed tro multaj estas la kisoj de malamanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'Sata animo malŝatas mieltavolon, Sed por malsata animo ĉio maldolĉa estas dolĉa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Kiel birdo, kiu forlasis sian neston, Tiel estas homo, kiu forlasis sian lokon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Oleo kaj odorfumaĵo ĝojigas la koron, Kaj la konsilo de amiko estas dolĉaĵo por la animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Ne forlasu vian amikon kaj la amikon de via patro, Kaj en la domon de via frato ne iru en la tago de via mizero; Pli bona estas najbaro proksima, ol frato malproksima.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Estu saĝa, mia filo, kaj ĝojigu mian koron; Kaj mi havos kion respondi al mia insultanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Prudentulo antaŭvidas malbonon, kaj kaŝiĝas; Sed naivuloj antaŭenpaŝas, kaj difektiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Prenu la veston de tiu, kiu garantiis por aliulo; Kaj pro la fremduloj prenu de li garantiaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Kiu frue matene benas sian proksimulon per laŭta voĉo, Tiu estos opiniata malbenanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Defluilo en pluva tago Kaj malpacema edzino estas egalaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Kiu ŝin retenas, tiu retenas venton Kaj volas kapti oleon per sia dekstra mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Fero akriĝas per fero, Kaj homon akrigas la rigardo de lia proksimulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Kiu gardas figarbon, tiu manĝos ĝiajn fruktojn; Kaj kiu gardas sian sinjoron, tiu estos honorata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Kiel en la akvo vizaĝo speguliĝas al vizaĝo, Tiel la koro de homo estas kontraŭ alia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Ŝeol kaj la abismo neniam satiĝas; Kaj ankaŭ la okuloj de homo neniam satiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Kiel fandujo por arĝento kaj forno por oro, Tiel estas por homo la buŝo de lia laŭdanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Se vi pistos malsaĝulon en pistujo inter griaĵo, Lia malsaĝeco de li ne apartiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Bone konu viajn ŝafojn, Atentu viajn brutarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'Ĉar riĉeco ne daŭras eterne, Kaj krono ne restas por ĉiuj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Aperas herbo, montriĝas verdaĵo, Kaj kolektiĝas kreskaĵoj de la montoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'Ŝafidoj estas, por vesti vin, Kaj kaproj, por doni al vi la eblon aĉeti kampon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'Estas sufiĉe da kaprina lakto, por nutri vin, por nutri vian domon, Kaj por subteni la vivon de viaj servantinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Malvirtulo kuras, kiam neniu persekutas; Sed virtuloj estas sentimaj kiel leono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Kiam lando pekas, ĝi havas multe da estroj; Sed se regas homo prudenta kaj kompetenta, li regas longe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'Homo malriĉa, kiu premas malriĉulojn, Estas kiel pluvo batanta, sed ne dononta panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Kiuj forlasis la leĝojn, tiuj laŭdas malvirtulon; Sed la observantoj de la leĝoj indignas kontraŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Malbonaj homoj ne komprenas justecon; Sed la serĉantoj de la Eternulo komprenas ĉion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Pli bona estas malriĉulo, kiu iras en sia senkulpeco, Ol homo, kiu iras malĝustan vojon, kvankam li estas riĉa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Kiu observas la leĝojn, tiu estas filo prudenta; Sed kunulo de malĉastuloj hontigas sian patron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Kiu pligrandigas sian havon per procentegoj kaj troprofito, Tiu kolektas ĝin por kompatanto de malriĉuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Kiu forklinas sian orelon de aŭdado de instruo, Ties eĉ preĝo estas abomenaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Kiu forlogas virtulojn al vojo malbona, Tiu mem falos en sian foson; Sed la senkulpuloj heredos bonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'Riĉulo estas saĝa en siaj okuloj; Sed saĝa malriĉulo lin tute travidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Kiam triumfas virtuloj, estas granda gloro; Sed kiam altiĝas malvirtuloj, tiam homoj sin kaŝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Kiu kaŝas siajn pekojn, tiu ne estos feliĉa; Sed kiu ilin konfesas kaj forlasas, tiu estos pardonita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Bone estas al homo, kiu ĉiam timas; Sed kiu havas malmolan koron, tiu falos en malfeliĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Leono krieganta kaj urso avida Estas malvirta reganto super malriĉa popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Se reganto estas neprudenta, tiam fariĝas multe da maljustaĵoj; Sed kiu malamas maljustan profiton, tiu longe vivos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Homo, kies konscienco estas ŝarĝita de mortigo, Kuros al foso; kaj oni lin ne haltigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Kiu iras en senpekeco, tiu estos savita; Sed kiu iras malĝustan vojon, tiu subite falos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Kiu prilaboras sian teron, tiu havos sate da pano; Sed kiu serĉas vantaĵojn, tiu havos plenan malriĉecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'Homon fidelan oni multe benas; Sed kiu rapidas riĉiĝi, tiu ne restos sen puno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Konsideri personojn ne estas bone; Pro peco da pano homo pekus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Homo enviema rapidas al riĉeco, Kaj li ne scias, ke malriĉeco lin atendas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Kiu faras riproĉojn al homo, tiu poste trovos pli da danko, Ol tiu, kiu flatas per la lango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Kiu rabas de sia patro kaj patrino, kaj diras: Ĝi ne estas peko, Tiu estas kamarado de mortigisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Fierulo kaŭzas malpacojn; Sed kiu fidas la Eternulon, tiu estos bonstata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Kiu fidas sin mem, tiu estas malsaĝa; Sed kiu tenas sin prudente, tiu estos savita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Kiu donas al malriĉulo, tiu ne havos mankon; Sed kiu kovras siajn okulojn, tiu estas multe malbenata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Kiam malvirtuloj altiĝas, homoj kaŝiĝas; Sed kiam ili pereas, tiam multiĝas virtuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'Se homo ofte admonita restos obstina, Li subite pereos sen ia helpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Kiam altiĝas virtuloj, la popolo ĝojas; Sed kiam regas malvirtulo, la popolo ĝemas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Homo, kiu amas saĝon, ĝojigas sian patron; Sed kiu komunikiĝas kun malĉastulinoj, tiu disperdas sian havon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Reĝo per justeco fortikigas la landon; Sed donacamanto ĝin ruinigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'Homo, kiu flatas al sia proksimulo, Metas reton antaŭ liaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'Per sia pekado malbona homo sin implikas; Sed virtulo triumfas kaj ĝojas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Virtulo penas ekkoni la aferon de malriĉuloj; Sed malvirtulo ne povas kompreni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Homoj blasfemantaj indignigas urbon; Sed saĝuloj kvietigas koleron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Se saĝa homo havas juĝan aferon kun homo malsaĝa, Tiam, ĉu li koleras, ĉu li ridas, li ne havas trankvilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Sangaviduloj malamas senkulpulon; Sed virtuloj zorgas pri lia vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Sian tutan koleron aperigas malsaĝulo; Sed saĝulo ĝin retenas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Se reganto atentas mensogon, Tiam ĉiuj liaj servantoj estas malvirtuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Malriĉulo kaj procentegisto renkontiĝas; La Eternulo donas lumon al la okuloj de ambaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Se reĝo juĝas juste malriĉulojn, Lia trono fortikiĝas por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'Kano kaj instruo donas saĝon; Sed knabo, lasita al si mem, hontigas sian patrinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Kiam altiĝas malvirtuloj, tiam multiĝas krimoj; Sed virtuloj vidos ilian falon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Punu vian filon, kaj li vin trankviligos, Kaj li donos ĝojon al via animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Se ne ekzistas profetaj predikoj, tiam popolo fariĝas sovaĝa; Sed bone estas al tiu, kiu observas la leĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Per vortoj sklavo ne instruiĝas; Ĉar li komprenas, sed ne obeas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Ĉu vi vidas homon, kiu tro rapidas kun siaj vortoj? Estas pli da espero por malsaĝulo ol por li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Se oni de infaneco kutimigas sklavon al dorlotiĝado, Li poste fariĝas neregebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'Kolerema homo kaŭzas malpacojn, Kaj flamiĝema kaŭzas multajn pekojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'La fiereco de homo lin malaltigos; Sed humilulo atingos honoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Kiu dividas kun ŝtelisto, tiu malamas sian animon; Li aŭdas la ĵuron kaj nenion diras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'Timo antaŭ homoj faligas en reton; Sed kiu fidas la Eternulon, tiu estas ŝirmita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Multaj serĉas favoron de reganto; Sed la sorto de homo dependas de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'Maljusta homo estas abomenaĵo por virtuloj; Kaj kiu iras la ĝustan vojon, tiu estas abomenaĵo por malvirtulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Vortoj de Agur, filo de Jake. Profeta parolo de tiu viro al Itiel, al Itiel kaj Ukal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Mi estas la plej malklera homo, Kaj homan prudenton mi ne posedas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'Kaj mi ne lernis saĝon, Kaj pri la Sanktulo mi ne havas ekkonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Kiu leviĝis en la ĉielon, kaj malleviĝis? Kiu kolektis la venton en siajn mankavojn? Kiu ligis la akvon en la veston? Kiu aranĝis ĉiujn limojn de la tero? Kia estas lia nomo? kaj kia estas la nomo de lia filo? Ĉu vi scias?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Ĉiu diro de Dio estas pura; Li estas ŝildo por tiuj, kiuj Lin fidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Ne aldonu al Liaj vortoj, Por ke Li ne punu vin, kaj por ke vi ne aperu mensoganto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Du aferojn mi petis de Vi; Ne rifuzu al mi, antaŭ ol mi mortos:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Falsaĵon kaj mensogaĵon forigu de mi; Malriĉecon kaj riĉecon ne donu al mi; Nutru min per tiom da pano, kiom mi bezonas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'Ĉar alie mi eble trosatiĝus kaj neus, kaj dirus: Kiu estas la Eternulo? Aŭ eble mi malriĉiĝus kaj ŝtelus, Kaj malbonuzus la nomon de mia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Ne kalumniu sklavon antaŭ lia sinjoro, Por ke li ne malbenu vin kaj vi ne fariĝu kulpulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Estas generacio, kiu malbenas sian patron Kaj ne benas sian patrinon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'Generacio, kiu estas pura en siaj okuloj Kaj tamen ne laviĝis de siaj malpuraĵoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'Generacio, kiu tiel alte tenas siajn okulojn Kaj tiel levas siajn palpebrojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'Generacio, kies dentoj estas glavoj kaj kies makzeloj estas tranĉiloj, Por formanĝi la malriĉulojn de la tero kaj la mizerulojn inter la homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'Hirudo havas du filinojn, kiuj krias: Donu, donu; Ili tri neniam satiĝas. Kvar objektoj ne diras: Sufiĉe:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'Ŝeol; senfrukta ventro; la tero ne satiĝas de akvo; kaj la fajro ne diras: Sufiĉe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Okulon, kiu mokas la patron Kaj malŝatas obeadon al la patrino, Elpikos korvoj ĉe la rivero kaj formanĝos aglidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Tri aferoj estas nekompreneblaj por mi, Kaj kvaran mi ne scias:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'La vojon de aglo en la aero; La vojon de serpento sur roko; La vojon de ŝipo meze de la maro; Kaj la vojon de viro ĉe virgulino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Tia estas la vojo de virino adultanta: Ŝi manĝas, viŝas la buŝon, Kaj diras: Mi faris nenian pekon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Sub tri objektoj tremas la tero, Kaj kvar ĝi ne povas porti:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'Sklavon, kiam li fariĝis reĝo; Malsaĝulon, kiam li tro satiĝis de pano;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'Malamatan virinon, kiam ŝi edziniĝis, Kaj sklavinon, kiam ŝi elpelis sian sinjorinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Kvar estas malgranduloj sur la tero, Kaj tamen ili estas tre saĝaj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'La formikoj, popolo ne forta, Tamen ili en somero pretigas al si manĝaĵon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'La hirakoj, popolo senforta, Tamen ili faras siajn domojn en la roko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'La akridoj ne havas reĝon, Kaj tamen ili ĉiuj eliras en vicoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'La lacerto kroĉiĝas per siaj manoj, Tamen ĝi estas en reĝaj palacoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Ekzistas tri, kiuj bone iras, Kaj kvar, kiuj marŝas bele:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'La leono, plej forta el la bestoj, Cedas al neniu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'Cervo kun bonaj lumboj; virkapro; Kaj reĝo, kiun neniu povas kontraŭstari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Se vi agis malsaĝe pro via fiereco, Kaj se vi intencis malbonon, Tiam metu la manon sur la buŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Ĉar batado de lakto produktas buteron, Ekbato de nazo aperigas sangon, Kaj incitado de kolero kaŭzas malpacon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Vortoj de la reĝo Lemuel, instruo, kiun donis al li lia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Ho mia filo, ho filo de mia ventro! Ho filo de miaj promesoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Ne donu al la virinoj vian forton, Nek viajn agojn al la pereigantoj de reĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Ne al la reĝoj, ho Lemuel, ne al la reĝoj konvenas trinki vinon, Nek al la princoj deziri ebriigaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'Ĉar drinkinte, ili povas forgesi la leĝojn, Kaj ili malĝustigos la juĝon de ĉiuj prematoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Donu ebriigaĵon al la pereanto, Kaj vinon al tiu, kiu havas suferantan animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'Li trinku, kaj forgesu sian malriĉecon, Kaj li ne plu rememoru sian malfeliĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Malfermu vian buŝon por senvoĉulo, Por la defendo de ĉiuj forlasitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Malfermu vian buŝon, por juĝi juste, Por defendi malriĉulon kaj senhavulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Se iu trovis kapablan edzinon, Ŝia valoro estas pli granda ol perloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Fidas ŝin la koro de ŝia edzo, Kaj havo ne mankos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Ŝi redonas al li bonon, sed ne malbonon, En la daŭro de ŝia tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Ŝi serĉas lanon kaj linon, Kaj volonte laboras per siaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Ŝi estas kiel ŝipo de komercisto; De malproksime ŝi alportas sian panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Ŝi leviĝas, kiam estas ankoraŭ nokto, Kaj ŝi disdonas manĝon al sia domanaro Kaj porciojn al siaj servantinoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Ŝi pensas pri kampo, kaj aĉetas ĝin; Per la enspezoj de sia mano ŝi plantas vinberĝardenon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Ŝi zonas siajn lumbojn per forto Kaj fortikigas siajn brakojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Ŝi komprenas, ke ŝia komercado estas bona; Ŝia lumilo ne estingiĝas en la nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Ŝi etendas sian manon al la ŝpinilo, Kaj ŝiaj fingroj tenas la ŝpinturnilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Ŝi malfermas sian manon al la malriĉulo Kaj etendas siajn manojn al la senhavulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Ŝi ne timas la neĝon por sia domo, Ĉar ŝia tuta domanaro estas vestita per ruĝa teksaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Ŝi faras al si kovrojn; Delikata tolo kaj purpuro estas ŝiaj vestoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Ŝia edzo estas konata ĉe la pordego, Kie li sidas kune kun la maljunuloj de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Ŝi faras teksaĵon kaj vendas, Kaj zonojn ŝi donas al la komercisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Fortika kaj bela estas ŝia vesto, Kaj ŝi ridas pri la venonta tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Sian buŝon ŝi malfermas kun saĝo; Bonkora instruo estas sur ŝia lango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Ŝi kontrolas la iradon de aferoj en sia domo, Kaj ŝi ne manĝas panon en senlaboreco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Leviĝas ŝiaj filoj kaj ŝin gratulas; Ŝia edzo ŝin laŭdegas, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, 'Multaj filinoj estas bravaj, Sed vi superas ĉiujn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Ĉarmeco estas trompa, kaj beleco estas vantaĵo; Virino, kiu timas la Eternulon, estos glorata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Donu al ŝi laŭ la fruktoj de ŝiaj manoj; Kaj ŝiaj faroj ŝin gloros ĉe la pordegoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Vortoj de la Predikanto, filo de David, reĝo en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Vantaĵo de vantaĵoj, diris la Predikanto; vantaĵo de vantaĵoj, ĉio estas vantaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Kian profiton havas la homo de ĉiuj siaj laboroj, kiujn li laboras sub la suno?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Generacio foriras kaj generacio venas, kaj la tero restas eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Leviĝas la suno kaj subiras la suno, kaj al sia loko ĝi rapidas, kaj tie ĝi leviĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Iras al sudo kaj reiras al nordo, turniĝas, turniĝas en sia irado la vento, kaj al siaj rondoj revenas la vento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Ĉiuj riveroj iras al la maro, sed la maro ne pleniĝas; al la loko, al kiu la riveroj alfluas, ili alfluas ĉiam denove.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Ĉiuj aferoj estas lacigaj, ne povas homo tion eldiri; ne satiĝas la okulo de vidado, kaj ne pleniĝas la orelo de aŭdado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Kio estis, tio estos; kaj kio estis farata, tio estos farata; kaj ekzistas nenio nova sub la suno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Ekzistas io, pri kio oni diras: Vidu, ĉi tio estas nova; sed ĝi estis jam en la eterna tempo, kiu estis antaŭ ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Ne restis memoro pri la antaŭuloj; kaj ankaŭ pri la posteuloj, kiuj estos, ne restos memoro ĉe tiuj, kiuj estos poste.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Mi, Predikanto, estis reĝo super Izrael en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'Kaj mi decidis en mia koro esplori kaj ekzameni per la saĝo ĉion, kio fariĝas sub la ĉielo: ĉi tiun malfacilan okupon Dio donis al la homidoj, por ke ili turmentiĝu per ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Mi vidis ĉiujn aferojn, kiuj fariĝas sub la suno; kaj jen, ĉio estas vantaĵo kaj entreprenoj ventaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Kurbigitan oni ne povas rerektigi, kaj mankantan oni ne povas kalkuli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Mi meditis kun mia koro tiele: Jen mi kreskigis kaj multigis en mi sciencon pli ol ĉiuj, kiuj estis antaŭ mi en Jerusalem; kaj mia koro penetris multon da saĝo kaj scio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'Sed kiam mi dediĉis mian koron, por ekkoni la saĝecon kaj ekkoni la malsaĝecon kaj sensencecon, mi eksciis, ke ankaŭ ĉi tio estas ventaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Ĉar ĉe multe da saĝeco estas multe da zorgemeco; kaj, kiu plimultigas siajn sciojn, tiu plimultigas siajn dolorojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Mi diris en mia koro: Lasu, mi elprovos vin per ĝojo, kaj vi ĝuu bonon; sed jen ankaŭ ĉi tio estas vantaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Pri la rido mi diris: Ĝi estas sensencaĵo! kaj pri la ĝojo: Kion ĝi havigas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Mi serĉis en mia koro, kiel plezurigi mian korpon per vino, kaj, dum mia koro min gvidas per saĝeco, sekvi ankaŭ malsaĝecon, ĝis mi ekvidos, kio estas bona por la homidoj, kion ili povus fari sub la ĉielo en la kalkulitaj tagoj de sia vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Mi entreprenis grandajn farojn: mi konstruis al mi domojn, mi plantis al mi vinberejojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'mi aranĝis al mi ĝardenojn kaj arbaretojn, kaj plantis en ili ĉiafruktajn arbojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'mi aranĝis al mi akvujojn, por akvumi el ili arbaretojn, kiuj kreskigas arbojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'mi akiris al mi sklavojn kaj sklavinojn, kaj domanojn mi havis; ankaŭ da bruto granda kaj malgranda mi havis pli multe, ol ĉiuj, kiuj estis antaŭ mi en Jerusalem;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'mi kolektis al mi ankaŭ arĝenton kaj oron, kaj juvelojn de reĝoj kaj landoj; mi havigis al mi kantistojn kaj kantistinojn, kaj plezurojn de homidoj, kaj multajn amantinojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'Kaj mi pligrandigis kaj plimultigis ĉion pli ol ĉiuj, kiuj estis antaŭ mi en Jerusalem, kaj mia saĝeco restis kun mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'Kaj ĉion, kion postulis miaj okuloj, mi ne rifuzis al ili; mi fortenis mian koron de nenia ĝojo, ĉar mia koro ĝojis pri ĉiuj miaj laboroj; kaj ĉi tio estis mia rekompenco por ĉiuj miaj laboroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Kaj mi ekrigardis ĉiujn farojn, kiujn faris miaj manoj, kaj ĉiujn laborojn, kiujn mi plenumis, por fari ilin: kaj jen, ĉio estas vantaĵo kaj ventaĵo, kaj nenia profito estas de ili sub la suno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Kaj mi turnis min, por rigardi saĝecon kaj malsaĝecon kaj sensencecon; ĉar kion povas fari homo, venonta post reĝo, en komparo kun tio, kion tiu jam antaŭ longe faris?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'Kaj mi vidis, ke havas superecon la saĝeco antaŭ la malsaĝeco, kiel havas superecon lumo antaŭ mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'La saĝulo havas siajn okulojn en la kapo, kaj la malsaĝulo iras en mallumo; sed mi ankaŭ eksciis, ke unu sorto atingas ilin ĉiujn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Kaj mi diris en mia koro: Ankaŭ min atingos tia sama sorto, kiel la malsaĝulon; por kio do mi estis pli saĝa? Kaj mi diris en mia koro, ke ankaŭ ĉi tio estas vantaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Ĉar pri la saĝulo ne restos memoro eterne tiel same, kiel pri la malsaĝulo; en la tempoj estontaj ĉio estos forgesita. Kaj ho ve, mortas saĝulo egale kiel malsaĝulo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Kaj mi ekmalamis la vivon; ĉar abomenindaj estas por mi la faroj, kiuj fariĝas sub la suno, ĉar ĉio estas vantaĵo kaj ventaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Kaj mi ekmalamis ĉiun laboron, kiun mi laboris sub la suno; ĉar mi devos lasi ĝin al homo, kiu estos post mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'Kaj kiu scias, ĉu estos saĝa aŭ malsaĝa tiu, kiu ekposedos mian tutan laboron, pri kiu mi penis kaj streĉis mian saĝon sub la suno? Ankaŭ ĉi tio estas vantaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'Kaj mi decidis, ke mia koro atendu nenion de la tuta laboro, kiun mi laboris sub la suno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Ĉar ofte oni vidas homon, kiu laboras en saĝo, scienco, kaj talento, kaj li devas fordoni sian akiron al homo, kiu ne laboris por ĝi; ĉi tio ankaŭ estas vantaĵo kaj granda malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Kaj kio restas al la homo de lia tuta laborado kaj de la zorgoj de lia koro, kion li laboras sub la suno?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Ĉar ĉiuj liaj tagoj estas suferoj, kaj liaj okupoj estas maltrankvileco; eĉ en la nokto ne trankviliĝas lia koro; ankaŭ ĉi tio estas vantaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Ne ekzistas alia bono por la homo, krom manĝi kaj trinki kaj igi sian animon ĝui plezuron de lia laborado; ankaŭ pri ĉi tio mi vidis, ke ĝi estas de la mano de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'Ĉar kiu povas manĝi, kaj kiu povas ĝui, sen Li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Ĉar al homo, kiu agas bone antaŭ Li, Li donas saĝon kaj scion kaj ĝojon, kaj al la pekulo Li donas la zorgemecon amasigi kaj kolekti, por poste transdoni al tiu, kiu agas bone antaŭ Dio; kaj ĉi tio estas vantaĵo kaj ventaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Por ĉio estas sezono, kaj tempo difinita estas por ĉiu afero sub la suno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'estas tempo por naskiĝi, kaj tempo por morti; estas tempo por planti, kaj tempo por elŝiri la plantitaĵon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'estas tempo por mortigi, kaj tempo por kuraci; estas tempo por detrui, kaj tempo por konstrui;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'estas tempo por plori, kaj tempo por ridi; estas tempo por ĝemi, kaj tempo por danci;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'estas tempo por disĵeti ŝtonojn, kaj tempo por kolekti ŝtonojn; estas tempo por ĉirkaŭbraki, kaj tempo por foriri de ĉirkaŭbrakado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'estas tempo por serĉi, kaj tempo por perdi; estas tempo por konservi, kaj tempo por forĵeti;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'estas tempo por disŝiri, kaj tempo por kunkudri; estas tempo por silenti, kaj tempo por paroli;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'estas tempo por ami, kaj tempo por malami; estas tempo por milito, kaj tempo por paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Kian profiton havas faranto de tio, kion li laboras?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Mi vidis la penemecon, kiun Dio donis al la homidoj, por ke ili turmentiĝu per ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Ĉion Li kreis bela ĝiatempe; kaj scion pri la mondo Li enmetis en ilian koron, sed tiel, ke homo ne povas kompreni la farojn, kiujn faris Dio de la komenco ĝis la fino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Mi scias, ke ekzistas nenia bono por ili, krom ĝoji kaj fari bonon en sia vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'Kaj se homo manĝas kaj trinkas kaj ĝuas bonon de sia tuta laborado, tio estas dono de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Mi scias, ke ĉio, kion faras Dio, restas eterne; al ĝi oni nenion povas aldoni, kaj de ĝi oni nenion povas depreni; kaj Dio tion faris, ke oni Lin timu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'Kio fariĝis, tio ekzistas de longe; kaj kio estas fariĝonta, tio antaŭ longe jam estis, kaj Dio revokas pasintaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Ankoraŭ mi vidis sub la suno: en la loko de juĝo, ke tie estas maljusteco; en la loko de vero, ke tie estas malico.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'Mi diris en mia koro: Piulon kaj malpiulon juĝos Dio; ĉar estas tempo por ĉiu afero, kaj por ĉio, kio fariĝas tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Mi diris en mia koro: Ĉi tio estas pri la homidoj, ke Dio ilin elprovu, kaj ke ili vidu, ke ili estas bruto per si mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Ĉar la sorto de homidoj kaj la sorto de bruto estas sorto egala: kiel ĉi tiuj mortas, tiel mortas ankaŭ tiuj, kaj sama spirito estas en ĉiuj; kaj supereco de homo kontraŭ bruto ne ekzistas, ĉar ĉio estas vantaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Ĉiuj iras al unu loko: ĉiuj fariĝis el polvo, kaj ĉiuj refariĝos polvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Kiu scias, ĉu la spirito de homidoj leviĝas supren, kaj ĉu la spirito de bruto malleviĝas malsupren en la teron?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Kaj mi ekvidis, ke ekzistas nenio pli bona, ol ke homo ĝuu plezuron de siaj faroj, ĉar tia estas lia sorto; ĉar kiu alkondukos lin, por vidi, kio estas post li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Kaj mi returniĝis, kaj mi vidis ĉiujn premojn, kiuj estas farataj sub la suno: kaj jen estas larmoj de prematoj, kaj ne ekzistas por ili konsolanto; kaj perforteco de la mano de iliaj premantoj, kaj ne ekzistas por ili konsolanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Kaj mi trovis, ke la mortintoj, kiuj jam antaŭ longe mortis, estas pli feliĉaj ol la vivantoj, kiuj vivas ĝis nun;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'kaj pli feliĉa ol ili ambaŭ estas tiu, kiu ĝis nun ne ekzistis, kiu ne vidis la malbonajn farojn, kiuj estas farataj sub la suno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Mi vidis ankaŭ, ke ĉia laboro kaj ĉia lerteco en la faroj estas nur konkurado de unu kontraŭ alia; kaj ankaŭ ĉi tio estas vantaĵo kaj ventaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Malsaĝulo kunmetas siajn manojn, kaj formanĝas sian korpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Pli bona estas plenmano da trankvilanimeco, ol ambaŭmano da penado kaj ventaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Kaj denove mi turniĝis, kaj vidis vantaĵon sub la suno:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'jen estas solulo, kaj neniun alian li havas; nek filon nek fraton li havas; kaj tamen ne havas finon lia laborado, kaj lia okulo ne povas satiĝi de riĉeco; por kiu do mi laboras kaj senigas mian animon de ĝuado? Ĉi tio ankaŭ estas vantaĵo kaj malbona afero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Pli bone estas al du ol al unu, ĉar ili havas bonan rekompencon por sia laborado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Ĉar se ili falos, unu levos la alian; sed ve al solulo, se li falos, kaj se ne estas alia, kiu lin levus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Ankaŭ se du kuŝiĝas, estas al ili varme; sed unu-kiel li varmiĝos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'Kaj se iu montros sin pli forta kontraŭ unu, tiam ambaŭ kontraŭstaros lin; eĉ fadeno triopigita ne baldaŭ disŝiriĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Pli bona estas knabo malriĉa sed saĝa, ol reĝo maljuna sed malsaĝa, kiu jam ne povas akiri scion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Iu el malliberejo eliris, kaj fariĝis reĝo; alia por reĝeco naskiĝis, kaj tamen estas malriĉa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Mi vidis, ke ĉiu vivanto iras sub la suno kun la junulo: ĝi estas la alia, kiu okupos lian lokon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Senfina estas la popolo, antaŭ kiu li estis, kaj tamen la posteuloj ne ĝojos pri li; ankaŭ ĉi tio estas vantaĵo kaj ventaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Gardu vian piedon, kiam vi iros en la domon de Dio, kaj estu preta pli por aŭskultado, ol por oferdonado de malsaĝuloj; ĉar ili ne scias, ke ili agas malbone.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Ne rapidu kun via buŝo, kaj via koro ne rapidu elparoli vorton antaŭ Dio, ĉar Dio estas en la ĉielo, kaj vi estas sur la tero; tial malmultaj estu viaj vortoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Ĉar sonĝo prezentiĝas per multe da agado, kaj parolo de malsaĝulo konsistas el multe da vortoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Kiam vi faros promeson al Dio, ne prokrastu ĝin plenumi; ĉar malagrablaj al Li estas malsaĝuloj: kion vi promesis, tion plenumu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Pli bone estas, ke vi ne faru promeson, ol fari promeson kaj ne plenumi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Ne permesu al via buŝo pekigi vian korpon, kaj ne diru al la sendito de Dio, ke ĝi estas eraro; kial fari, ke Dio koleru pro via parolo, kaj ke Li detruu la faron de viaj manoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Ĉe multo da sonĝoj kaj vantaĵoj estas ankaŭ multe da vortoj; sed vi timu Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Se premadon de malriĉulo kaj rompadon de justeco kaj honesteco vi vidas en lando, ne miru; ĉar pli alta kontrolas pli altan, kaj plej altaj ilin kontrolas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Kaj superecon en ĉio havas tiu lando, en kiu la reĝo servas al la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Kiu amas monon, tiu ne satiĝos per mono; kaj kiu amas riĉecon, al tiu ĝi ne donos utilon: ankaŭ ĉi tio estas vantaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Ju pli estas da havo, des pli multaj estas ĝiaj konsumantoj; kaj kian profiton havas ĝia mastro, krom vidi ĝin per siaj okuloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Dolĉa estas la dormo de laboranto, ĉu li manĝas malmulte aŭ multe; sed trosateco ne lasas la riĉulon dormi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Turmentan malbonon mi vidis sub la suno: riĉecon konservatan por la malutilo de ĝia propra mastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Kaj pereas ĉi tiu riĉeco en malfavoraj cirkonstancoj; naskiĝas filo, kaj li nenion havas en la mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Kiel li eliris el la ventro de sia patrino, tiel nuda li foriras, kiel li venis; kaj nenion li elportas el sia laboro, kion li povus porti en la mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Kaj ĉi tio estas turmenta doloro, ke kiel li venis, tiel li foriras; kian do profiton li havas de tio, ke li laboras por la vento?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'Kaj ĉiujn siajn tagojn li konsumis en mallumo, en multe da ekscitiĝo, en malsano kaj malagrablaĵoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Jen, kion mi vidis: ke estas bone kaj bele manĝi kaj trinki kaj ĝui plezurojn de ĉiuj siaj laboroj, kiujn homo laboras sub la suno dum la tagoj de sia vivo, kiujn donis al li Dio; ĉar tio estas lia apartenaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'Kaj se al iu homo Dio donis riĉecon kaj havon, kaj donis al li la povon konsumi ilin kaj preni sian parton kaj ĝui plezuron de siaj laboroj, ĉi tio estas dono de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, 'Ĉar ne longe li memoros la tagojn de sia vivo; Dio donas al li ĝojon de lia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Ekzistas malbono, kiun mi vidis sub la suno, kaj granda ĝi estas por la homo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'se al iu homo Dio donas riĉecon kaj havon kaj honoron, kaj al lia animo mankas nenio, kion ajn li dezirus, sed Dio ne donas al li la povon konsumi ĝin, nur fremda homo ĝin konsumas-ĉi tio estas vantaĵo kaj malfacila doloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Se iu homo naskigus cent infanojn kaj vivus multajn jarojn kaj atingus profundan aĝon, sed lia animo ne ĝuus sate la havon, kaj eĉ bonan enterigon li ne havus-tiam mi dirus: Pli feliĉa ol li estas abortito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Ĉar ĉi tiu vante venis kaj en mallumon foriris, kaj en mallumo kaŝiĝos lia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'Eĉ la sunon li ne vidis kaj ne konis-al li estas pli trankvile ol al tiu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Kaj se tiu homo vivus du mil jarojn kaj la bonon ne ĝuus, ĉu ne al unu loko ĉiuj iros?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Ĉiuj laboroj de homo estas por lia buŝo, kaj tamen lia animo ne estas satigebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Kaj kian superecon havas la saĝulo antaŭ malsaĝulo, la inteligenta malriĉulo antaŭ aliaj vivaj estaĵoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Pli bone estas vidi per la okuloj, ol imagi en la animo; ankaŭ ĉi tio estas vantaĵo kaj ventaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Kio ajn ekzistas, tio de longe havas nomon; kaj estas sciate, kia estas la homo, kaj ke li ne povas juĝe batali kun Tiu, kiu estas pli forta ol li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Ĉar ekzistas multe da aferoj, kiuj plimultigas la vantaĵon; kian do superecon havas la homo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Ĉar kiu scias, kio estas bona por la homo dum la tagoj de lia vanta vivo, kiun li pasigas kiel ombro? kaj kiu diros al la homo, kio estos post li sub la suno?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Pli bona estas bona nomo, ol bona oleo; kaj la tago de la morto estas pli bona, ol la tago de la naskiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Pli bone estas iri en domon de funebro, ol iri en domon de festenado; ĉar morto estas la fino de ĉiu homo, kaj la vivanto notos ĉi tion en sia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Pli bona estas plendo, ol rido; ĉar ĉe malĝojo de la vizaĝo pliboniĝas la koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'La koro de saĝuloj estas en domo de funebro, kaj la koro de malsaĝuloj en domo de ĝojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Pli bone estas aŭskulti riproĉon de saĝulo, ol aŭskulti kanton de malsaĝuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Ĉar simila al la kraketado de dornoj sub poto estas la ridado de la malsaĝuloj; kaj vantaĵo ĝi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Ĉar perforteco forprenas la saĝon de saĝulo, kaj la prudenton malbonigas donaco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'La fino de afero estas pli bona, ol ĝia komenco; pacienculo estas pli bona, ol malhumilulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Ne rapidu koleri en via spirito; ĉar koleremeco loĝas en la brusto de malsaĝuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Ne diru: Kial la antaŭaj tagoj estis pli bonaj, ol la nunaj? ĉar ne el saĝeco vi ĉi tion demandus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Bona estas saĝeco kune kun hereda havo, kaj ĝi estas profita al tiuj, kiuj vidas la sunon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Ĉar la saĝeco estas ŝirmo tiel same, kiel mono estas ŝirmo; sed la supereco de scienco konsistas en tio, ke la saĝeco donas vivon al sia posedanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Rigardu la faron de Dio; ĉar kiu povas tion rektigi, kion Li kurbigis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'En la tago de bonstato uzu la bonstaton, kaj en la tago de malfeliĉo atendu: ĉi tion kaj tion aranĝis Dio, por ke la homo nenion komprenu post Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Ĉion tion mi vidis en miaj vantaj tagoj: okazas, ke virtulo pereas ĉe sia virteco, kaj okazas, ke malvirtulo longe vivas ĉe sia malvirteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Ne estu tro virta, kaj ne rezonu tro multe: kial vi devas vin konfuzi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Ne malvirtu tro multe, kaj ne estu senprudenta: kial vi devas morti ne en via tempo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Bone estas, se vi tenos vin je unu afero kaj ankaŭ de alia afero vi ne forprenos vian manon; ĉar tiu, kiu timas Dion, penas plaĉi al ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'La saĝeco faras la saĝulon pli forta, ol dek potenculoj en la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Ĉar ne ekzistas sur la tero virtulo, kiu farus nur bonon kaj ne pekus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Ne ĉiujn vortojn, kiujn oni diras, atentu en via koro, por ke vi ne aŭdu vian sklavon malbenanta vin:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'ĉar multajn fojojn konsciis via koro, ke ankaŭ vi malbenis aliajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Ĉion ĉi tion mi provis per mia saĝo; mi diris al mi: Mi akiru saĝon; tamen ĝi estas malproksima de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Kio estas malproksima kaj tre profunda, kiu tion komprenos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Mi turnis min kun mia koro, por ekkoni, esplori, kaj traserĉi saĝecon kaj prudenton, kaj ekscii, ke la malvirteco estas malsaĝeco kaj ke la senscieco estas sensenca.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'Kaj mi trovas, ke pli malbona ol la morto estas la virino, kiu estas kaptilo, kaj kies koro estas reto, kaj kies manoj estas katenoj; tiu, kiu plaĉas al Dio, sin savos de ŝi, sed pekulo estos kaptita de ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Jen, kion mi trovis, diris la Predikanto: oni devas kunigi unu fakton kun alia, por veni al konkludo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'Jen, kion ankoraŭ serĉis mia animo kaj ne trovis: viron unu inter mil mi trovis, sed virinon inter ĉiuj mi tute ne trovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Nur ĉi tion mi trovis, ke Dio kreis la homon virtema; sed la homoj fordonis sin al multaj artifikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Kiu estas simila al saĝulo? kaj kiu komprenas la sencon de la aferoj? Saĝeco de homo lumigas lian vizaĝon, kaj la maldelikateco de lia vizaĝo ŝanĝiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Mi diras: La reĝan ordonon plenumu, pro la ĵuro farita antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Ne rapidu foriri de antaŭ li, kaj ne estu persistema en malbona afero; ĉar ĉion, kion li volos, li povos fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'Ĉar la vorto de reĝo estas potenca; kaj kiu povas diri al li: Kion vi faras?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Kiu plenumas la ordonon, tiu spertos nenion malbonan; tempon kaj manieron de agado scias la koro de saĝulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Ĉar por ĉiu afero estas ĝia tempo kaj ĝia maniero; kaj granda estas por la homo la malbono de tio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'ke li ne scias, kio estos; ĉar kiu diros al vi, kiel estos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Neniu homo povas regi la venton kaj reteni la venton, neniu povas regi la tagon de la morto; ne ekzistas forpermeso en tiu milito, kaj malvirteco ne savas sian faranton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Ĉion ĉi tion mi vidis, kaj mi atentis ĉiun aferon, kiu estas farata sub la suno, kaj tiun tempon, en kiu homo regas homon al lia malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Kaj ankaŭ mi vidis, ke oni enterigis malvirtulojn, kiuj venadis kaj eliradis el la sankta loko, kaj kiuj estis forgesitaj en la urbo, kie ili tiel agis; kaj ĉi tio ankaŭ estas vantaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Ĉar ne baldaŭ estas farata juĝo kontraŭ malbonaj faroj, tial plene kuraĝas la koro de homidoj fari malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'Kvankam pekulo faras malbonon cent fojojn, kaj Dio estas pacienca al li, tamen mi scias, ke estos bone al tiuj, kiuj timas Dion, kiuj respektas Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'Kaj ne estos bone al malvirtulo, kaj ne tenos sin longe, simile al ombro, tiu, kiu ne timas Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Ekzistas vantaĵo, kiu fariĝas sur la tero: ekzistas virtuloj, al kiuj fariĝas tio sama, kio fariĝas al malvirtuloj; kaj ekzistas malvirtuloj, al kiuj fariĝas tio sama, kio al la virtuloj; kaj mi diris al mi, ke ankaŭ ĉi tio estas vantaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Kaj mi eklaŭdis la gajecon, ĉar ne ekzistas io pli bona por homo sub la suno, ol manĝi, trinki, kaj gaji, kaj ke ĉi tio akompanu lin en liaj laboroj en la tagoj de lia vivo, kiujn donis al li Dio sub la suno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Kiam mi direktis mian koron, por ekkoni saĝecon, kaj por ĉirkaŭrigardi la aferojn, kiuj estas farataj sur la tero tiamaniere, ke nek tage nek nokte homo vidas dormon sur siaj okuloj; kaj kiam mi rigardis ĉiujn farojn de Dio:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'tiam mi trovis, ke homo ne povas kompreni la aferojn, kiuj fariĝas sub la suno; kiom ajn la homo penus esplori, li ne komprenos; kaj se eĉ saĝulo diras, ke li scias, li tamen ne povas kompreni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Al ĉio ĉi tio mi direktis mian koron, por esplori ĉion ĉi tion, ke la virtuloj kaj saĝuloj kaj iliaj faroj estas en la mano de Dio; kaj nek amon nek malamon scias la homo, kaj nenion, kio lin atendas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Al ĉiuj estas la sama sorto: al la virtulo kaj al la malvirtulo, al la bona kaj pura kaj al la malpura, al la oferfaranto kaj al tiu, kiu ne oferfaras, al la bonulo kaj al la pekulo, al la ĵuranto kaj al tiu, kiu timas ĵuron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'Ĉi tio estas malbona en ĉio, kio fariĝas sub la suno, ke la sama sorto ekzistas por ĉiuj, kaj la koro de la homidoj estas plena de malbono, kaj sensencaĵo estas en ilia koro dum ilia vivado, kaj poste ili transiras al la mortintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Ĉar kiu troviĝas inter la vivuloj, tiu havas ankoraŭ esperon; ĉar eĉ al hundo vivanta estas pli bone, ol al leono mortinta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Ĉar la vivantoj scias, ke ili mortos; kaj la mortintoj scias nenion, kaj por ili jam ne ekzistas rekompenco, ĉar la memoro pri ili estas forgesita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Kaj ilia amo, kaj ilia malamo, kaj ilia ĵaluzo jam de longe malaperis; kaj jam por neniam ili havas partoprenon en io, kio fariĝas sub la suno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Iru, manĝu ĝoje vian panon, kaj trinku kun gaja koro vian vinon, se Dio favoris viajn aferojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'En ĉiu tempo viaj vestoj estu blankaj, kaj oleo ne manku sur via kapo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Ĝuu la vivon kun la edzino, kiun vi amas en la tempo de via tuta vanta vivo, kaj kiun Dio donis al vi por ĉiuj viaj vantaj tagoj; ĉar ĉi tio estas via apartenaĵo en via vivo, kaj en viaj laboroj, kiujn vi laboris sub la suno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Kion ajn via mano povas fari laŭ via forto, tion faru; ĉar ekzistas nek faro, nek kalkulo, nek scio, nek saĝo, en Ŝeol, kien vi iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Aliflanke mi vidis sub la suno, ke ne de la rapiduloj dependas la kuro, ne de la fortuloj dependas la milito, kaj ne la saĝuloj havas panon, kaj ne la talentuloj havas riĉecon, kaj ne la kompetentuloj trovas aprobon; nur de la tempo kaj okazo ili ĉiuj dependas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Ĉar eĉ ne scias la homo sian sorton; kiel fiŝoj, kaptitaj en pereigan reton, kaj kiel birdoj, implikiĝintaj en kaptilon, tiel kaptiĝas la homoj en tempo malbona, kiam ĝi atakas ilin neatendite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Ankaŭ jenan saĝaĵon mi vidis sub la suno, kaj ĝi ŝajnis al mi granda:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'estis urbo malgranda, kaj malmulte da homoj ĝi havis; venis al ĝi granda reĝo, kaj sieĝis ĝin, kaj konstruis ĉirkaŭ ĝi grandajn sieĝajn fortikaĵojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'sed troviĝis en ĝi homo malriĉa sed saĝa, kaj li savis la urbon per sia saĝeco; tamen neniu rememoris tiun malriĉan homon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Kaj mi diris: Pli bona estas saĝo ol forto, tamen la saĝo de malriĉulo estas malrespektata, kaj liaj vortoj ne estas aŭdataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'La vortoj de saĝuloj, trankvile aŭskultitaj, estas pli bonaj ol la kriado de reganto inter malsaĝuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Pli bona estas saĝo, ol militaj instrumentoj; kaj unu pekulo pereigas multe da bono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Venenaj muŝoj putrigas kaj haladzigas la oleon de parfumisto; pli ŝatata ol saĝo kaj honoro ofte estas malgranda malsaĝaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'La koro de saĝulo estas ĉe lia dekstra flanko, kaj la koro de malsaĝulo ĉe lia maldekstra.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Kaj eĉ en la vojo, laŭ kiu iras malsaĝulo, mankas al li saĝo, kaj al ĉiu li diras, ke li estas malsaĝulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Se atakos vin kolero de reganto, ne forlasu vian lokon, ĉar mildeco pardonigas eĉ grandajn krimojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Ekzistas malbono, kiun mi vidis sub la suno; ĝi estas kvazaŭ eraro, venanta de la reganto:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'senscieco estas metata tre alte, kaj la riĉuloj sidas malalte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Mi vidis sklavojn sur ĉevaloj, kaj princojn, irantajn piede, kiel sklavoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Kiu fosas kavon, tiu falos en ĝin; kaj kiu detruas muron, tiun mordos serpento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Kiu transmovas ŝtonojn, tiu faras al si difekton per streĉo; kaj kiu hakas lignon, tiu sin vundas per ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Se malakriĝis la hakilo, kaj oni ne akrigas la tranĉan flankon, oni devas streĉi la fortojn; kaj la ĉefaĵo estas prepari ĉion saĝe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Se mordis la serpento sen kuracparolo, tiam jam ne utilas kuracparolanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Vortoj el buŝo de saĝulo estas agrablaj, sed la buŝo de malsaĝulo lin mem pereigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'La komenco de la parolo de lia buŝo estas malsaĝaĵo, kaj la fino de lia parolo estas abomeninda sensencaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Malsaĝulo multe parolas, kvankam homo ne scias, kio estos; kaj kio estos post li? kiu ĉi tion diros al li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Penado de malsaĝuloj lacigas ĉiun, kiu ne scias eĉ la vojon al la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Ve al vi, ho lando, se via reĝo estas infano kaj viaj princoj manĝas frue!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Feliĉa vi estas, ho lando, se via reĝo estas de nobla deveno kaj viaj princoj manĝas en ĝusta tempo, por fortiĝi, ne por festeni!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'De mallaboremeco falos la plafono; kaj, se oni mallevas la manojn, tramalsekiĝas la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Por plezuro oni aranĝas festenojn, kaj vino gajigas la vivon, kaj mono respondas por ĉio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Eĉ en viaj pensoj ne malbenu la reĝon, kaj en via dormoĉambro ne malbenu riĉulon; ĉar birdo ĉiela transportos vian voĉon, kaj flugila estaĵo eldiros vian parolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Elsendu vian panon sur la akvon; ĉar post longa tempo vi ĝin retrovos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Donu parton al sep, kaj eĉ al ok, ĉar vi ne scias, ĉu ne estos malfeliĉo sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Kiam la nuboj pleniĝos, ili verŝos pluvon sur la teron, kaj se falos arbo suden aŭ norden, ĝi tie restos, kien ĝi falis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Kiu observas la venton, tiu ne semos; kaj kiu rigardas la nubojn, tiu ne rikoltos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Kiel vi ne scias, kian vojon iros la vento, kaj kiel formiĝas la ostoj en la ventro de gravedulino, tiel vi ne povas scii la faron de Dio, kiu ĉion faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Matene semu vian semon, kaj vespere via mano ne ripozu; ĉar vi ne scias, ĉu tio aŭ alio estos pli ĝusta, aŭ ĉu ambaŭ egale estos bonaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Agrabla estas la lumo, kaj bone estas al la okuloj vidi la sunon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Ĉar se eĉ multajn jarojn homo vivus, li ĝoju en ili ĉiuj; kaj li memoru pri la tagoj mallumaj, ĉar estos multe da ili; ĉio, kio venos, estas vantaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Ĝoju, junulo, en via infaneco; kaj via koro ĝuu plezuron en la tagoj de via juneco, kaj iru, kien kondukas vin via koro kaj kien rigardas viaj okuloj; sed sciu, ke pri ĉio ĉi tio Dio venigos vin al juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Tial forpelu malĝojon de via koro, kaj forigu malagrablaĵon de via korpo; ĉar la infaneco kaj la juneco estas vantaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Kaj memoru vian Kreinton en la tagoj de via juneco, dum ankoraŭ ne venis la tagoj de malbono, kaj ne venis la jaroj, pri kiuj vi diros: Mi ne havas plezuron de ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'dum ne mallumiĝis la suno, la lumo, la luno, kaj la steloj, kaj ne revenis nuboj post la pluvo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'en la tago, kiam ektremos la gardantoj de la domo, kaj malfortiĝos la militantoj, kaj ĉesos mueli la muelantinoj, ĉar estos malmulte da ili, kaj senvidiĝos la rigardantinoj tra la fenestroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'kaj fermitaj estos la pordoj al la strato, kiam eksilentos la sonado de la muelŝtono; kaj homo leviĝados laŭ la krio de birdo, kaj mallaŭtiĝos la sonoj de kantoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'kaj altaĵojn ili ektimos, kaj sur la vojo aperos teruroj, kaj ekfloros la migdalarbo, kaj peziĝos la lokusto, kaj malaperos deziro: tiam homo foriros en sian eternan domon, kaj sur la strato marŝos plorantoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'ĝis disŝiriĝos la arĝenta ĉeneto, rompiĝos la ora lampeto, rompiĝos la kruĉo ĉe la fonto, kaj falos la rado en la puton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'kaj la polvo refariĝos tero, kiel ĝi estis, kaj la spirito reiros al Dio, kiu ĝin donis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Vantaĵo de vantaĵoj, diris la Predikanto; ĉio estas vantaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'Krom tio, ke la Predikanto estis saĝulo, li ankoraŭ instruis scion al la popolo; li ĉion pesis, esploris, kaj verkis multe da sentencoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Penis la Predikanto trovi agrablajn parolojn, kaj li skribis ĝuste vortojn de vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'La paroloj de saĝuloj estas kiel akraj pintoj, kaj kiel enbatitaj najloj estas la vortoj de publikaj parolistoj; ili estas donitaj de unu paŝtisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'Kaj krom tio, mia filo, akceptu mian instruon, ke se oni volus verki multajn librojn, ne estus fino, kaj multe legi lacigas la korpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Ni aŭskultu la finon de ĉio: timu Dion, kaj plenumu Liajn ordonojn, ĉar ĉi tio estas ĉio por la homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Ĉar ĉiun faron Dio venigos al juĝo, eĉ ĉion kaŝitan, ĉu ĝi estas bona aŭ malbona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Alta kanto de Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Ho, li kisu min per kisoj de sia buŝo! Ĉar via amo estas pli bona, ol vino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Ho, kiel bonodoras viaj aromaĵoj! Via nomo similas al elverŝita oleo; Tial la fraŭlinoj amas vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Altiru min; ni postkuros vin. La reĝo envenigu min en siajn ĉambrojn; Ho, ni ĝojos kaj gajiĝos kun vi; Ni memoros vian amon pli, ol vinon; Sincere oni amas vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Mi estas nigra, tamen beleta, Ho filinoj de Jerusalem, Kiel la tendoj de Kedar, Kiel la tapetoj de Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Ne rigardu min, ke mi estas nigreta: La suno min brulkolorigis. La filoj de mia patrino koleris kontraŭ mi; Ili faris min gardistino de la vinberĝardenoj; Mian propran vinberĝardenon mi ne gardis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Diru al mi, ho vi, kiun mia animo amas, Kie vi paŝtas, kie vi ripozigas vian brutaron tagmeze: Kial mi similu al vagistino Ĉe la brutaroj de viaj kamaradoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Se vi ne scias tion, ho belulino inter virinoj, Sekvu la paŝojn de la ŝafaro, Kaj paŝtu viajn kapridojn ĉe la tendoj de la paŝtistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Al la ĉevalino en la ĉaroj de Faraono Mi komparas vin, ho mia amatino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Belaj estas viaj vangoj sub la orelringoj, Via kolo sub la laĉoj de perloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Orajn orelringojn ni faros al vi, Kun arĝentaj enkrustaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Dum la reĝo sidas ĉe la festotablo, Mia nardo bonodoras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Kiel fasko de mirho, restanta inter miaj mamoj, Estas al mi mia amato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Kiel floraro de kofero estas por mi mia amato, En la vinberĝardenoj de En-Gedi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'Ho, vi estas bela, mia amatino; ho, vi estas ja bela; Viaj okuloj estas kiel ĉe kolomboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'Ho, vi estas bela, mia amato, kaj ĉarma; Nia lito estas kiel freŝaj herboj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'La traboj de nia domo estas cedraj, Niaj ĉevronoj estas abiaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Mi estas la lilio de Ŝaron, La rozo de la valoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Kiel rozo inter la dornoj, Tiel estas mia amatino inter la knabinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Kiel pomarbo inter arboj nefruktaj, Tiel estas mia amato inter la junuloj. Mi sopiris al lia ombro, jen mi sidiĝis; Kaj liaj fruktoj estas bongustaj al mia palato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Li enkonduku min en vindomon, Kaj lia standardo super mi estu la amo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Plifortigu min per vinberkuko, Refreŝigu min per pomsuko; Ĉar mi estas malsana de amo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Lia maldekstra mano estu sub mia kapo, Lia dekstra ĉirkaŭprenu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Mi ĵurligas vin, ho filinoj de Jerusalem, Je la gazeloj aŭ la cervoj de la kampo: Ne veku nek sendormigu la amatinon, Ĝis ŝi mem volos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Ho, jen estas la voĉo de mia amato! Ho, jen li venas, Rapidante sur la montoj, saltante sur la altaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Mia amato similas al gazelo aŭ al cervo. Ho, jen li staras post nia muro, Rigardante tra la fenestro, Sin montrante ĉe la krado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Mia amato vokas, li parolas al mi: Leviĝu, mia amatino, mia belulino, ho venu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Ĉar la vintro jam forpasis, La pluvo pasis kaj malaperis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'La floroj jam estas sur la tero; La kantosezono jam alvenis, Kaj la voĉo de la turto jam aŭdiĝas en nia lando;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'La figarbo jam maturigas siajn fruktetojn, La vinbertrunkoj siajn vinberetojn, Kiuj jam bonodoras. Leviĝu, mia amatino, mia belulino, kaj venu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Ho mia kolombino, en la krevaĵoj de la roko, en la kaŝejo de la rokkrutaĵo, Montru al mi vian aspekton, aŭdigu al mi vian voĉon; Ĉar via voĉo estas dolĉa, kaj via aspekto estas bela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Kaptu al ni la ŝakalojn, la malgrandajn ŝakalojn, La detruantojn de la vinberĝardenoj, Kiam niaj vinberĝardenoj burĝonas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Mia amato apartenas al mi, Kaj mi apartenas al li, Kiu paŝtas inter la rozoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Ĝis la tago malvarmetiĝos kaj la ombroj forkuros, Turnu vin, ho amato, similiĝu al gazelo aŭ al cervo Sur la montoj de aromaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Sur mia kuŝejo dum la nokto mi serĉis tiun, kiun mia animo amas; Mi serĉis lin, sed mi lin ne trovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Mi leviĝos, kaj irados tra la urbo; Sur la stratoj kaj placoj mi serĉos tiun, kiun mia animo amas; Mi serĉis lin, sed mi lin ne trovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'La gardistoj, kiuj iradas tra la urbo, renkontis min, Al ili mi demandis: Ĉu vi vidis tiun, kiun mia animo amas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'Kiam mi nur ekforiris de ili, Mi renkontis tiun, kiun mia animo amas; Mi tenis lin, kaj ne delasis lin, Ĝis mi enkondukis lin en la domon de mia patrino, Kaj en la ĉambron de ŝi, kiu naskis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Mi ĵurligas vin, ho filinoj de Jerusalem, Je la gazeloj aŭ cervoj de la kampo: Ne veku nek sendormigu la amatinon, Ĝis ŝi mem volos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Kiu estas ŝi, kiu venas el la dezerto, kiel kolono de fumo Parfumita per mirho kaj olibano, Per ĉiaj pudroj de la parfumisto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Jen estas la lito de Salomono! Sesdek fortuloj ĉirkaŭas ĝin El la fortuloj de Izrael,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Ĉiuj tenantaj glavojn, kompetentaj batalantoj; Ĉiu portas sian glavon ĉe sia femuro, Pro la teruro de la nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Edziĝan liton el la ligno de Lebanon Konstruis al si la reĝo Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Ĝiajn kolonojn li konstruis el arĝento, La ĉarpentaĵon el oro, la tegaĵon el purpuro; La interno estas pavimita per la amo de la filinoj de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Iru tien, ho filinoj de Cion, kaj vidu la reĝon Salomono, Vestitan per la krono, per kiu lia patrino kronis lin en la tago de lia edziĝofesto, En la tago de la ĝojo de lia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Vi estas bela, mia amatino, vi estas bela; Viaj okuloj estas kolombaj, malantaŭ via vualo. Viaj haroj estas kiel aro da kaprinoj, Deirantaj sur la deklivo de la monto Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Viaj dentoj estas kiel tondotaj ŝafinoj, Kiuj elvenas el la lavejo; Ĉiuj estas en paroj, Kaj ne mankas eĉ unu el ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Viaj lipoj estas kiel ruĝa fadeno, Kaj via elparolado estas bela; Kiel peco de granato, viaj vangoj aspektas Malantaŭ via vualo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Via kolo estas kiel la turo de David, kiu estas konstruita kiel armiltenejo; Mil ŝildoj pendas sur ĝi, Ĉiuj ŝildoj de la potenculoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Viaj du mamoj estas kiel du cervidoj, ĝemeloj de gazelino, Kiuj sin paŝtas inter la rozoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Ĝis la tago malvarmetiĝos kaj la ombroj forkuros, Mi foriros al la monto de mirho kaj al la altaĵo de olibano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Via tutaĵo estas bela, mia amatino; Vi ne havas difekton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Kun mi el Lebanon venu, ho mia fianĉino, Kun mi el Lebanon; Rigardu malsupren de la pinto de Amana, De la pinto de Senir kaj Ĥermon, El la kavernoj de la leonoj, De la montoj de la leopardoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Vi kortuŝis min, mia fratino, mia fianĉino; Vi kortuŝis min per unu ekrigardo de viaj okuloj, Per unu ĉeno de sur via kolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Kiel bela estas via amo, mia fratino, mia fianĉino! Ho, kiom pli bona estas via amo, ol vino! Kaj la bonodoro de viaj parfumaĵoj estas pli bona, ol ĉiaj aromaĵoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Mielo gutadas el viaj lipoj, ho mia fianĉino; Mielo kaj lakto kuŝas sub via lango; Kaj la bonodoro de viaj vestoj estas kiel la bonodoro de Lebanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Vi estas ĝardeno ŝlosita, ho mia fratino, mia fianĉino; Vi estas fonto ŝlosita, puto sigelita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Viaj kreskaĵoj estas paradizo de granatoj kun multevaloraj fruktoj, Plena de koferoj kaj nardoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'Nardo kaj safrano; Kano kaj cinamo, kun ĉiuspecaj olibanarboj; Mirho kaj aloo kaj la plej delikataj aromaĵoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Ĝardenfonto, puto de vivanta akvo, Kaj riveretoj elfluantaj el Lebanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Vekiĝu, ho norda vento, venu, ho suda vento; Trablovu mian ĝardenon, ke ĝiaj aromaĵoj elfluu. Venu mia amato en sian ĝardenon Kaj manĝu ĝiajn multevalorajn fruktojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Mi venis en mian ĝardenon, mia fratino, mia fianĉino; Mi deŝiris mian mirhon kaj miajn aromaĵojn; Mi manĝis mian mielĉelaron, kiel ankaŭ mian mielon; Mi trinkis mian vinon, kiel ankaŭ mian lakton. Manĝu, ho miaj kamaradoj; Drinku kaj ebriiĝu, ho miaj amikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Mi dormis, sed mia koro estis maldorma; Jen estas la voĉo de mia amato, jen li ekfrapas: Malfermu al mi, ho mia fratino, mia amatino, mia kolombino, mia virtulino; Ĉar mia kapo estas plena de roso, Miaj harbukloj de la gutoj de la nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'Mi jam demetis mian ĥitonon; kial mi ĝin denove surmetu? Mi jam lavis miajn piedojn; kial mi ilin malpurigu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Mia amato etendis sian manon tra la truo, Kaj mia interno kompatis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Mi leviĝis, por malfermi al mia amato; Kaj de miaj manoj gutis mirho, Kaj miaj fingroj estis malsekaj de mirha fluidaĵo, Sur la riglilo de la seruro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Mi malfermis al mia amato; Sed mia amato forturniĝis kaj malaperis. Mia animo tremis, dum li parolis; Mi lin serĉis, sed mi lin ne trovis; Mi vokis lin, sed li ne respondis al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'La gardistoj, kiuj ĉirkaŭas la urbon, renkontis min, Ili batis kaj vundis min; La gardistoj de la muroj deprenis de mi la kovrotukon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Mi ĵurligas vin, ho filinoj de Jerusalem, se vi renkontos mian amaton, Ho, kion vi diros al li? ke mi estas malsana de amo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Per kio diferencas via amato de aliaj amatoj, Ho belulino inter virinoj? Per kio diferencas via amato de aliaj amatoj, Ke vi tiele ĵurligas nin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Mia amato estas blanka kaj ruĝa, Distinginda inter dekmilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Lia kapo estas pura oro; Liaj haroj estas buklitaj, nigraj kiel korvo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Liaj okuloj estas kiel kolomboj ĉe la akvotorentoj; Lavitaj per lakto, orname enkadrigitaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Liaj vangoj estas kiel bedoj de aromaĵoj, kiel kesto de ŝmiraĵisto; Liaj lipoj estas kiel rozoj, ili gutadas fluidan mirhon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Liaj manoj estas kiel oraj ringoj, kadritaj per topazoj; Lia korpo estas ebura, enkrustita per safiroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Liaj kruroj estas kiel marmoraj kolonoj, enfiksitaj en bazoj el pura oro; Lia aspekto estas kiel Lebanon, majesta kiel cedroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Lia palato estas dolĉaĵoj; lia tutaĵo estas tre aminda. Tia estas mia amato, kaj tia estas mia kamarado, Ho filinoj de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Kien foriris via amato, Ho belulino inter virinoj? Kien forturniĝis via amato, Por ke ni lin serĉu kun vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Mia amato iris en sian ĝardenon, al la bedoj de aromaĵoj, Por paŝti en la ĝardenoj kaj kolekti rozojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Mi apartenas al mia amato, kaj mia amato apartenas al mi; Tiu, kiu paŝtas inter la rozoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Ho, mia amatino, vi estas bela kiel Tirca, Agrabla kiel Jerusalem, Terura kiel batalantaj taĉmentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Forturnu la okulojn for de mi, Ĉar ili venkas min. Viaj haroj estas kiel aro da kaprinoj, Deirantaj sur la deklivo de la monto Gilead.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Viaj dentoj estas kiel aro da ŝafinoj, Kiuj elvenas el la lavejo; Ĉiuj estas en paroj, Kaj ne mankas eĉ unu el ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Kiel peco de granato, viaj vangoj aspektas Malantaŭ via vualo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Da reĝinoj ekzistas sesdek, kaj okdeko da kromvirinoj, Kaj la junulinoj estas sennombraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Sed unu sola estas mia kolombino, mia virtulino; Ŝi estas la sola ĉe sia patrino, La elektita de sia naskintino; La filinoj vidis ŝin, kaj nomas ŝin feliĉulino; La reĝinoj kaj la kromvirinoj laŭdas ŝin, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Kiu estas ŝi, kiu aspektas kiel la matenruĝo, Bela kiel la luno, Hela kiel la suno, Terura kiel batalantaj taĉmentoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'Mi iris en la nuksarban ĝardenon, Por trarigardi la verdajn kreskaĵojn de la valo, Por vidi, ĉu la vinbertrunko burĝonas, ĉu la granatarboj floras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Tiam mi ankoraŭ ne sciis, Ke mia animo elektos min por la ĉaroj de la nobeloj de mia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, 'Turniĝu, turniĝu, ho Ŝulamit; Turniĝu, turniĝu, ke ni rigardu vin. Kial vi volas rigardi Ŝulamiton tiel, Kiel oni rigardas la dancadon de la taĉmentoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Kiel belaj estas viaj paŝoj en sandaloj, ho filino de princo! La svingado de viaj femuroj estas kiel ĉenringoj, Majstre ellaboritaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Via umbiliko estas kiel ronda pokalo, Al kiu trinkaĵo ne mankas; Via ventro estas kiel amaso da tritiko ĉirkaŭita de rozoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Viaj du mamoj estas kiel du cervidoj, Ĝemeloj de gazelino;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Via kolo estas kiel turo el eburo; Viaj okuloj kiel la lagetoj en Ĥeŝbon, ĉe la pordego de Bat-Rabim; Via nazo estas kiel la turo de Lebanon rigardanta Damaskon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Via kapo sur vi estas kiel Karmel, Kaj la harbukloj de via kapo kiel la purpura robo de la reĝo, falde kunligita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Kiel bela kaj kiel ĉarma estas mia amatino inter la plezuroj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Via staturo similas la palmotrunkon, Kaj viaj mamoj la vinberarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Mi diris: Mi suprengrimpos la palmotrunkon kaj teniĝos je ĝiaj branĉoj; Kaj viaj mamoj estu kiel la penikoj de la vinbertrunko, Kaj la bonodoro de via nazo kiel la bonodoro de citronoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'Kaj via palato kiel vino bongusta, Kiu englitiĝas ĉarmege kaj glate, Kiu paroligas la lipojn de la dormantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Mi apartenas al mia amato, Kaj li sin tiras al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Venu, mia amato, ni eliru sur la kamparon; Ni enloĝiĝu en la vilaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Frumatene ni iru al la vinberĝardenoj; Ni rigardu, ĉu la vinbertrunko jam burĝonis, Ĉu ĝiaj floroj jam malfermiĝis, Ĉu la granatarboj jam floras; Tie mi donos al vi mian amon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'La mandragoroj jam bonodoras, Kaj apud nia enirejo troviĝas delikataj fruktoj ĉiuspecaj, fruaj kaj malfruaj, Kiujn mi provizis por vi, ho mia amato!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'Ho, se vi estus al mi kiel frato, Kiu suĉis la mamojn de mia patrino! Se mi renkontus vin ekstere, mi kisus vin; Kaj tamen neniu malestimus min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Mi gvidus vin, mi enkondukus vin en la domon de mia patrino; Vi instruus min, Kaj mi trinkigus al vi la spicitan vinon kaj la granatsukon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Lia maldekstra mano estu sub mia kapo, Kaj lia dekstra ĉirkaŭprenu min!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Mi ĵurligas vin, ho filinoj de Jerusalem, Ne veku nek sendormigu la amatinon, Ĝis ŝi mem volos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Kiu estas ŝi, kiu venas el la dezerto, Sin apogante sur sia amato? Sub la pomarbo mi vekis vin; Tie, kie via patrino vin naskis, Kie vin naskis via naskintino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Konservu min kiel sigelon en via koro, kiel sigelon sur via brako; Ĉar la amo estas forta kiel la morto; La ĵaluzo estas nefleksebla kiel Ŝeol; Ĝiaj brulaĵoj estas brulaĵoj de fajro, La flamo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Granda akvo ne povas estingi la amon, Kaj riveroj ne povas superakvi ĝin; Se homo proponus doni la tutan havaĵon de sia domo por la amo, Oni malestime lin forpuŝus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Nia fratino ankoraŭ estas malgranda, Kaj mamojn ŝi ankoraŭ ne havas; Kion ni faros al nia fratino, Kiam oni svatos ŝin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Se ŝi estos muro, ni konstruos sur ŝi arĝentan palacon; Kaj se ŝi estos pordo, ni ĉirkaŭbaros ŝin per traboj el cedro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Mi estas muro, kaj miaj mamoj kiel turoj; Mi jam estis al li kiel iu, kiu trovis favoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Salomono posedis vinberĝardenon en Baal-Hamon; Li luigis la vinberĝardenon al gardistoj; Ĉiu devas alporti milon da arĝentaj moneroj pro ĝiaj fruktoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Mia propra vinberĝardeno estas antaŭ mi. La milon al vi, ho Salomono, Kaj ducent al la gardistoj de ĝiaj fruktoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Ho vi, loĝantino de la ĝardenoj, La kamaradoj volas aŭskulti vian voĉon; Al mi ĝin aŭdigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Forkuru, ho mia amato, Kaj similiĝu al gazelo aŭ al cervo Sur la montoj de aromaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Vizio de Jesaja, filo de Amoc, kiun li vidis pri Judujo kaj Jerusalem, en la tempo de Uzija, Jotam, Aĥaz, kaj Ĥizkija, reĝoj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Aŭskultu, ho ĉielo, kaj atentu, ho tero, ĉar parolas la Eternulo: Filojn Mi edukis kaj altigis, kaj ili perfidis Min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Bovo konas sian aĉetinton, kaj azeno la manĝujon de sia mastro; sed Izrael ne konas, Mia popolo ne komprenas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Ve al la popolo peka, al la gento ŝarĝita de malbonagoj, al la idaro krima, al la filoj pereuloj! ili forlasis la Eternulon, ili malŝatis la Sanktulon de Izrael, ili forturniĝis malantaŭen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Kion oni ankoraŭ batu en vi, kiuj daŭrigas sian defaladon? la tuta kapo estas malsana, kaj la tuta koro estas senforta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'De la plando de la piedo ĝis la kapo estas en ĝi nenio sendifekta, nur vundoj kaj tuberoj kaj ulceroj pusaj, kiuj ne estas purigitaj, nek ĉirkaŭligitaj, nek moligitaj per oleo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Via lando estas dezerta, viaj urboj estas forbruligitaj per fajro, vian kampon antaŭ vi formanĝas fremduloj, kaj dezerta ĝi estas, kiel ruinigita de fremduloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'Kaj restis la filino de Cion kiel tendo en vinberĝardeno, kiel budo sur kukumkampo, kiel urbo sieĝata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Se la Eternulo Cebaot ne lasus al ni restaĵon, ni fariĝus preskaŭ kiel Sodom, ni similiĝus al Gomora.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Aŭskultu la vortojn de la Eternulo, estroj de Sodom; atentu la instruon de nia Dio, popolo de Gomora!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Por kio Mi bezonas vian multegon da buĉoferoj? diras la Eternulo; Mi trosatiĝis de la bruloferoj de ŝafoj kaj de la sebo de grasigitaj brutoj, kaj la sangon de bovoj kaj ŝafidoj kaj kaproj Mi ne deziras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Kiam vi venas, por aperi antaŭ Mia vizaĝo, kiu postulas tion de viaj manoj, ke vi paŝu sur Mian korton?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Ne plu alportu hipokritajn donacojn; la incensado estas abomenindaĵo por Mi; monatkomencon, sabaton, kaj kunvokon de kunvenoj Mi ne toleras- krimo kaj sankta kunveno!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Viajn monatkomencojn kaj festojn Mia animo malamas; ili fariĝis por Mi ŝarĝo, tedis al Mi porti ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Kiam vi etendas viajn manojn, Mi kaŝas antaŭ vi Miajn okulojn; eĉ kiam vi multe preĝas, Mi ne aŭskultas; viaj manoj estas plenaj de sango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Lavu vin, purigu vin; forigu la malbonon de viaj faroj antaŭ Miaj okuloj, ĉesu malbonagi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Lernu agi bone, celu justecon, helpu prematon, havigu juston al orfo, defendu aferon de vidvino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Venu, kaj ni faru inter ni juĝan disputon, diras la Eternulo: se viaj pekoj estas sangoruĝaj, ili fariĝos blankaj kiel neĝo; kaj se ili estas kiel skarlato, ili fariĝos kiel lano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Se vi estos humilaj kaj obeemaj, vi manĝos la bonaĵon de la tero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'sed se vi rifuzos kaj ribelos, glavo vin ekstermos; ĉar tiel diris la buŝo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Kiamaniere la fidela urbo fariĝis malĉastulino! ĝi estis plena de justeco, virto en ĝi loĝis, sed nun mortigistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Via arĝento fariĝis skorio, via vino miksiĝis kun akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Viaj estroj estas perfiduloj, kaj kolegoj de ŝtelistoj; ili ĉiuj amas donacojn kaj ĉasas profiton; al orfo ili ne donas juston, kaj la juĝa plendo de vidvino ne atingas ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Pro tio diras la Sinjoro, la Eternulo Cebaot, la Potenculo de Izrael: Ho ve, Mi konsolos Min sur Miaj kontraŭuloj, kaj Mi venĝos al Miaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'Kaj Mi remetos Mian manon sur vin, kaj Mi forte purigos vian skorion, kaj Mi eligos vian tutan stanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'Kaj Mi restarigos viajn juĝistojn, kiel antaŭe, kaj viajn konsilistojn, kiel en la komenco; post tio oni nomos vin urbo de virto, civito fidela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Cion elaĉetiĝos per justeco, kaj ĝiaj revenintoj per virto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'La krimuloj kaj pekuloj pereos kune, kaj la forlasintoj de la Eternulo ekstermiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Ĉar ili estos malhonoritaj pro la terebintarboj, kiujn vi amis, kaj vi estos hontigitaj pro la ĝardenoj, kiujn vi elektis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'Ĉar vi estos kiel terebintarbo, kies folioj velkis, kaj kiel ĝardeno, kiu ne havas akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'Kaj la fortulo fariĝos kiel stupo, kaj lia laboro kiel fajrero; kaj ambaŭ brulos, kaj neniu estingos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Afero, kiun Jesaja, filo de Amoc, vidis vizie pri Judujo kaj Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Iam en la tempo estonta la monto de la domo de la Eternulo staros kiel ĉefo inter la montoj, kaj ĝi estos pli alta ol ĉiuj altaĵoj; kaj fluos al ĝi ĉiuj nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'Kaj iros multaj popoloj, kaj diros: Venu, ni iru supren sur la monton de la Eternulo, al la domo de la Dio de Jakob, por ke Li instruu nin pri Siaj vojoj, kaj ni iru laŭ Lia irejo; ĉar el Cion eliros la instruo, kaj la vorto de la Eternulo el Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Kaj Li juĝos inter la nacioj, kaj Li decidos pri multaj popoloj; kaj ili forĝos el siaj glavoj plugilojn kaj el siaj lancoj rikoltilojn; ne levos nacio glavon kontraŭ nacion, kaj oni ne plu lernos militon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Ho domo de Jakob, venu, kaj ni iru en la lumo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Sed Vi forlasis Vian popolon, la domon de Jakob, ĉar ili pli pleniĝis ol antaŭe kaj ili sorĉas kiel la Filiŝtoj kaj aliĝis al infanoj de aligentuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Kaj ilia lando pleniĝis de arĝento kaj oro, kaj senfinaj estas iliaj trezoroj; kaj ilia lando pleniĝis de ĉevaloj, kaj sennombraj estas iliaj ĉaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Kaj ilia lando pleniĝis de idoloj; ili adorkliniĝas al la faritaĵo de siaj manoj, al tio, kion faris iliaj fingroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Kaj kliniĝis la homo, kaj malaltiĝis la viro; kaj Vi ne pardonos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Eniru en rokon kaj kaŝu vin en la tero, pro timo antaŭ la Eternulo kaj antaŭ la majesto de Lia grandeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'La fieraj okuloj de homo malleviĝos, kaj la altaj homoj estos malaltigitaj; nur la Eternulo sola estos alta en tiu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Ĉar la tago de la Eternulo Cebaot estos super ĉio malhumila kaj alta kaj super ĉio aroganta, kiu estos malaltigita;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'kaj super ĉiuj cedroj de Lebanon, la altaj kaj malhumilaj, kaj super ĉiuj kverkoj de Baŝan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'kaj super ĉiuj altaj montoj, kaj super ĉiuj leviĝintaj montetoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'kaj super ĉiu alta turo, kaj super ĉiu fortikigita muro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'kaj super ĉiuj ŝipoj de Tarŝiŝ, kaj super ĉiuj belaspektaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'Kaj humiligita estos la fiereco de homo, kaj altaj homoj estos malaltigitaj; nur la Eternulo sola estos alta en tiu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'La idoloj estos tute neniigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'Kaj oni iros en la kavernojn de la rokoj kaj en la fendojn de la tero, pro timo antaŭ la Eternulo kaj antaŭ Lia majesta grandeco, kiam Li leviĝos, por ĵeti teruron sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'En tiu tago la homo ĵetos al la talpoj kaj vespertoj siajn arĝentajn kaj orajn idolojn, kiujn li faris al si por adorado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'por eniri en kavernojn de rokoj kaj en fendojn de ŝtonegoj, pro timo antaŭ la Eternulo kaj antaŭ Lia majesta grandeco, kiam Li leviĝos, por ĵeti teruron sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Ĉesu zorgi pri homo, kies animo estas en liaj nazotruoj; ĉar kion li valoras?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Ĉar jen la Sinjoro, la Eternulo Cebaot, forprenos de Jerusalem kaj de Judujo la apogon kaj forton, ĉian apogon de pano kaj ĉian apogon de akvo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'heroon kaj militiston, juĝiston kaj profeton, aŭguriston kaj plejaĝulon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'kvindekestron kaj eminentulon, konsiliston, majstron, kaj lertan sorĉiston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Kaj junulojn Mi faros iliaj estroj, kaj petoluloj regos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'Kaj premos la popolo ĉiu la alian kaj ĉiu sian proksimulon; junulo estos aroganta kontraŭ maljunulo, kaj senvalorulo antaŭ eminentulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Homo ekkaptos sian fraton en la domo de sia patro, dirante: Vi havas veston, estu do nia estro, kaj ĉi tiu ruino estu sub via mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'Sed ĉi tiu laŭte protestos, dirante: Mi ne volas esti kuracanto; nek panon nek veston mi havas en mia domo; ne faru min estro de la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Ĉar malfortiĝis Jerusalem, kaj Judujo falis; ĉar iliaj paroloj kaj iliaj faroj estas kontraŭ la Eternulo kaj ofendas la okulojn de Lia majesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'La signoj de iliaj vizaĝoj atestis kontraŭ ili, kaj sian pekon, simile al la Sodomanoj, ili proklamas, ne kaŝas. Ve al iliaj animoj! ĉar ili mem repagis al si malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Parolu pri la justulo, ke estas bone al li; ĉar ili manĝas la fruktojn de siaj faroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Ve al la malbona malvirtulo! ĉar la faroj de liaj manoj estos repagitaj al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Mian popolon premas infanoj, kaj virinoj regas ĝin. Mia popolo! viaj gvidantoj erarigas vin kaj ruinigas la vojon de via irado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'La Eternulo stariĝis, por juĝi; Li staras, por juĝi popolojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'La Eternulo faros juĝan proceson kontraŭ la plejaĝuloj de Lia popolo kaj kontraŭ ĝiaj estroj: Vi ruinigis la vinberĝardenon; havo, kiun vi rabis de malriĉuloj, estas en viaj domoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Kial vi premas Mian popolon kaj ofendas la malriĉulojn? diras la Sinjoro, la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Kaj la Eternulo diras: Pro tio, ke la filinoj de Cion fieriĝis, kaj iras kun etendita kolo kaj kun malmodesta rigardo, iras kaj koketas, kaj tintas per ĉenetoj sur la piedoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'la Sinjoro senharigos la verton de la filinoj de Cion, kaj la Eternulo nudigos ilian hontindaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'En tiu tago la Sinjoro forigos la ornamon de la ĉenetoj kaj la steletojn kaj la lunetojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'la orelringojn, la ĉenetojn kaj la ĉirkaŭligojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'la brilaĵetojn kaj la bukojn kaj la laĉojn kaj la parfumujojn kaj la talismanojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'la ringojn kaj la nazringojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'la multekostajn vestojn kaj la mantelojn kaj la vualojn kaj la saketojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'la spegulojn kaj la delikatajn ŝtofojn kaj la kapornamojn kaj la kaptukojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'Kaj anstataŭ bonodoro estos malbonodoro, kaj anstataŭ zono estos ŝnuro, kaj anstataŭ krispaj haroj estos kalvo, kaj anstataŭ eleganta mantelo estos sako, anstataŭ beleco estos brulmakuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Viaj viroj falos de glavo, kaj viaj fortuloj en la milito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'Kaj ĝiaj pordegoj ploros kaj funebros, kaj mizere ĝi sidos sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'En tiu tago ekkaptos sep virinoj unu viron, kaj diros: Ni manĝados nian panon, kaj ni portados niajn vestojn; nur permesu al ni porti vian nomon, forigu de ni nian malhonoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'En tiu tago la markoto de la Eternulo estos belo kaj honoro, kaj la frukto de la tero estos majesto kaj ornamo por la savitaĵo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Kaj la restintoj en Cion kaj la reteniĝintoj en Jerusalem estos nomataj sanktuloj, ĉiuj, al kiuj la sorto lasis vivon en Jerusalem,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'se la Sinjoro forlavos la malpuraĵon de la filinoj de Cion, kaj forigos el Jerusalem la sangon, kiu estas interne de ĝi, per la spirito de juĝo kaj per la spirito de fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'Kaj super ĉiu loko de la monto Cion kaj super ĉiuj ĝiaj kunvenejoj la Eternulo kreos nubon kaj fumon por la tago kaj flamon de brulanta fajro por la nokto; super ĉio honora estos ŝirmo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'Kaj estos tendo, por ombri kontraŭ la varmegeco de la tago, kaj por rifuĝigi kaj ŝirmi kontraŭ malbona vetero kaj pluvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Mi kantos al mia amato la kanton de mia amiko pri lia vinberĝardeno. Vinberĝardenon havis mia amiko sur grasa altaĵo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'kaj li ĉirkaŭfosis ĝin, senŝtonigis ĝin, kaj plantis en ĝi plej bonspecajn vinberbranĉojn; kaj li konstruis turon meze de ĝi, kaj ankaŭ vinpremejon li elhakis en ĝi; kaj li esperis, ke ĝi donos bonajn vinberojn, sed ĝi donis senvalorajn berojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Nun, ho loĝantoj de Jerusalem kaj Judujo, juĝu do inter mi kaj mia vinberĝardeno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Kion oni povas ankoraŭ fari al mia vinberĝardeno, kion mi ne faris por ĝi? kial mi esperis, ke ĝi donos bonajn vinberojn, kaj ĝi tamen donis berojn senvalorajn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Nun mi sciigos al vi, kion mi faros al mia vinberĝardeno: forigita estos ĝia barilo, kaj ĝi estos ruinigata, ĝiaj muroj estos disĵetitaj, kaj ĝi estos piedpremata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Mi lasos ĝin dezerta, ĝi ne estos pritranĉata nek prifosata, kaj elkreskos en ĝi dornoj kaj pikarbustoj; kaj al la nuboj mi ordonos, ke ili ne verŝu sur ĝin pluvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'La vinberĝardeno de la Eternulo Cebaot estas la domo de Izrael, kaj la viroj de Jehuda estas Lia plej amata plantaĵo; kaj Li esperis justecon, sed montriĝis malnoblaĵo-bonagojn, sed montriĝis kriindaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Ve al vi, kiuj aligas domon al domo, kampon al kampo, ĝis restas jam nenia loko, por ke vi solaj posedu la landon!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'En miaj oreloj estas la vortoj de la Eternulo Cebaot: Multaj domoj fariĝos dezertaj, grandaj kaj bonaj estos sen loĝantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Ĉar dek parceloj da vinberĝardeno donos nur unu bat�on, kaj ĥomero da semoj donos nur unu efon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Ve al tiuj, kiuj leviĝas frue matene, por fordoni sin al drinkado, sidas malfrue nokte, por varmegigi sin per vino!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Harpo, psaltero, tamburino, fluto, kaj vino estas en iliaj festenoj; sed la verkon de la Eternulo ili ne rigardas, kaj la faron de Liaj manoj ili ne vidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Tial mia popolo estas forkondukita en malliberecon pro nekomprenado, kaj ĝiaj eminentuloj konsumiĝis de malsato, kaj ĝia popolamaso senfortiĝis de soifo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Pro tio Ŝeol larĝigis sian internon kaj eksterordinare malfermis sian faŭkon; kaj malleviĝos tien ĝia gloro kaj ĝia amaso kaj ĝia bruantaro kaj ĝia gajularo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'Kliniĝos homo kaj malaltiĝos viro, kaj la okuloj de fieruloj humiliĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'Sed la Eternulo Cebaot altiĝos en la juĝo, kaj la sankta Dio estos sankta en la justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Tiam la ŝafidoj paŝtiĝos en bona ordo, kaj fremduloj manĝos tion, kio restos de la fortuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Ve al tiuj, kiuj altiras malbonagon per ŝnuroj de vanteco kaj pekon kvazaŭ per ĉenoj de ĉaroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'al tiuj, kiuj diras: Li rapidu, Li akcelu Sian faron, por ke ni vidu; la plano de la Sanktulo de Izrael alproksimiĝu kaj venu, por ke ni ĝin ekkonu!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Ve al tiuj, kiuj la malbonon nomas bono kaj la bonon malbono, kiuj mallumon faras lumo kaj la lumon mallumo, kiuj maldolĉon faras dolĉo kaj la dolĉon maldolĉo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Ve al tiuj, kiuj estas saĝuloj en siaj okuloj kaj antaŭ si mem estas kompetentuloj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Ve al tiuj, kiuj estas herooj, por trinki vinon, kaj bravuloj, por miksi ebriigaĵon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'kiuj pravigas malvirtulon pro subaĉeto, kaj de pravulo forprenas lian pravecon!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Pro tio, kiel la lango de fajro formanĝas pajlon kaj la flamo ekstermas fojnon, tiel ilia radiko fariĝos nutraĵo, kaj ilia floro suprenflugos kiel polvo; ĉar ili malŝatis la instruon de la Eternulo Cebaot, kaj la vortojn de la Sanktulo de Izrael ili malestimis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Pro tio ekflamis la kolero de la Eternulo kontraŭ Lia popolo, kaj Li etendis Sian manon kontraŭ ĝin kaj frapis ĝin; kaj ektremis la montoj, kaj la kadavroj de la popolo estas kiel koto sur la stratoj; kaj malgraŭ ĉio ĉi tio Lia kolero ne kvietiĝis, kaj Lia brako estas ankoraŭ etendita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Kaj Li levos signon por la popoloj malproksimaj, kaj alvokos tian popolon de la ekstremaĵo de la tero, kaj ĝi venos rapide kaj facile.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Ne estos en tiu popolo laculo nek senfortulo, ĝi ne dormos nek dormetos, ne deliberiĝos la zono de ĝia lumbo, kaj ne disŝiriĝos rimeno de ĝia ŝuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Ĝiaj sagoj estas akraj, kaj ĉiuj ĝiaj pafarkoj estas streĉitaj; la hufoj de ĝiaj ĉevaloj estas kiel granito, kaj la radoj de ĝiaj ĉaroj kiel ventego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Ĝia blekado estas simila al la leona; ĝi krias, kiel leonidoj; ĝi ekbruas, kaj ekkaptas la rabakiron kaj forportas, kaj neniu savas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'Kaj ĝi blekegos super li en tiu tago simile al la bruo de la maro; kiam oni rigardos la teron, tie estos mallumo kaj mizero, kaj la lumo malaperos el la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'En la jaro de la morto de la reĝo Uzija mi vidis la Sinjoron, sidantan sur alta kaj levita trono, kaj Liaj baskoj plenigis la templon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Serafoj staris supre de Li; ĉiu havis po ses flugiloj; per du li kovris sian vizaĝon, per du li kovris siajn piedojn, kaj per du li flugis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'Kaj unu vokadis al alia, kaj diris: Sankta, sankta, sankta estas la Eternulo Cebaot, la tuta tero estas plena de Lia gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'Ekŝanceliĝis de la vokanta voĉo la kolonoj de la pordo, kaj la domo pleniĝis de fumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Kaj mi diris: Ve al mi! ĉar mi pereis; ĉar mi estas homo kun malpura buŝo, kaj mi loĝas inter popolo malpurbuŝa, kaj la Reĝon, la Eternulon Cebaot, vidis miaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Tiam alflugis al mi unu el la serafoj, havante en la mano ardantan karbon, kiun li per prenilo prenis de la altaro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'kaj li ektuŝis mian buŝon, kaj diris: Jen ĉi tio ektuŝis vian buŝon, kaj foriĝis via malpieco, kaj via peko estas pardonita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Kaj mi ekaŭdis la voĉon de la Sinjoro, kiu diris: Kiun Mi sendos, kaj kiu iros por ni? Kaj mi diris: Jen mi estas, sendu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Tiam Li diris: Iru kaj diru al tiu popolo: Vi aŭdos, sed ne komprenos; vi vidos, sed ne rimarkos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Sensentigu la koron de tiu popolo, kaj ĝiajn orelojn surdigu, kaj ĝiajn okulojn blindigu, por ke ĝi ne vidu per siaj okuloj, kaj por ke ĝi ne aŭdu per siaj oreloj, por ke ĝi ne komprenu per sia koro, por ke ĝi ne konvertiĝu kaj ne saniĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Mi diris: Ĝis kiam, ho Sinjoro? Kaj Li respondis: Ĝis malpleniĝos la urboj pro nehavado de loĝantoj kaj la domoj pro nehavado de homoj, kaj ĝis la tero tute dezertiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'Kaj la Eternulo forigos la homojn, kaj granda estos la forlasiteco en la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Se restos en ĝi dekono, ĝi ankaŭ ekstermiĝos, sed kiel terebintarbo aŭ kverko, de kiuj post la dehako restas ankoraŭ radiko; sankta semo estos ĝia radiko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'En la tempo de Aĥaz, filo de Jotam, filo de Uzija, reĝo de Judujo, eliris Recin, reĝo de Sirio, kaj Pekaĥ, filo de Remalja, reĝo de Izrael, kontraŭ Jerusalemon, por militi kontraŭ ĝi; sed ili ne povis konkeri ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Oni raportis al la domo de David, dirante: La Sirianoj stariĝis tendare en la lando de Efraim. Tiam ektremis lia koro kaj la koro de lia popolo, kiel la arboj de arbaro tremas de vento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Sed la Eternulo diris al Jesaja: Iru renkonte al Aĥaz, vi kaj via filo Ŝear-Jaŝub, al la fino de la akvotubo de la supra lageto, ĉe la vojo al la kampo de fulistoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'kaj diru al li: Gardu vin, kaj estu trankvila; ne timu, kaj via koro ne senkuraĝiĝu pro la du fumantaj brulŝtipoj, pro la furiozo de Recin kun la Sirianoj kaj de la filo de Remalja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'La Sirianoj, kun Efraim kaj kun la filo de Remalja, havas malbonan intencon kontraŭ vi, kaj diras:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Ni iru kontraŭ Judujon, ni malgrandigu ĝin, malkovru ĝin por ni, kaj ni starigu kiel reĝon super ĝi la filon de Tabeel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'Tiele diris la Sinjoro, la Eternulo: Tio ne plenumiĝos, kaj tio ne estos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Ĉar la kapo de Sirio estas Damasko, kaj la kapo de Damasko estas Recin, kaj post sesdek kvin jaroj Efraim ĉesos esti popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'Kaj la kapo de Efraim estas Samario, kaj la kapo de Samario estas la filo de Remalja. Se vi ne kredas, vi ne estas fidelaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Kaj plue diris la Eternulo: Diru al Aĥaz jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Petu por vi signon de la Eternulo, via Dio, ĉu profunde malsupre, ĉu alte supre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Sed Aĥaz diris: Mi ne petos, kaj mi ne incitos la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Kaj li diris: Aŭskultu, domo de David: ĉu ne sufiĉas al vi ĉagreni homojn, ke vi ĉagrenas eĉ mian Dion?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Tial la Sinjoro mem donos al vi signon: jen virgulino gravediĝis, kaj ŝi naskos filon, kaj ŝi donos al li la nomon Emanuel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Buteron kaj mielon li manĝos, ĝis li povoscios forpuŝi malbonon kaj elekti bonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Sed antaŭ ol la knabo povoscios forpuŝi malbonon kaj elekti bonon, estos forlasita tiu lando, kiun vi timas pro ĝiaj du reĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'La Eternulo venigos sur vin kaj sur vian popolon kaj sur la domon de via patro tiajn tagojn, kiuj ne venis de post la tempo, kiam Efraim defalis de Jehuda; Li venigos la reĝon de Asirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'En tiu tago la Eternulo alvokos la muŝojn de la randoj de la lagoj de Egiptujo kaj la abelojn de la lando Asiria;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'kaj ili venos kaj sidiĝos ĉiuj en la dezertigitaj valoj kaj en la fendoj de la rokoj kaj sur ĉiuj arbustoj kaj sur ĉiuj pikarbetaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'En tiu tempo la Eternulo razos per dungita razilo, per la transriveranoj, per la reĝo de Asirio, la kapon kaj la harojn de la piedoj, kaj forigos eĉ la barbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'En tiu tempo homo nutros junan bovinon kaj du ŝafojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'kaj pro la abundo de lakto li manĝos buteron; ĉar buteron kaj lakton manĝos ĉiu, kiu restos en la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'En tiu tempo ĉiu loko, kie estis mil vinberbranĉoj, havantaj la prezon de mil arĝentaj moneroj, kovriĝos per dornoj kaj pikarbustoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'Kun sagoj kaj pafarkoj oni venos tien, ĉar la tuta lando kovriĝos per dornoj kaj pikarbustoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'Kaj sur ĉiujn montojn, kiujn oni prilaboradis per pioĉoj, oni ne povos supreniri pro timo antaŭ la dornoj kaj pikarbustoj; oni sendos tien bovojn, oni irigos tien ŝafojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Kaj la Eternulo diris al mi: Prenu al vi grandan skribtabulon, kaj skribu sur ĝi per homa skribilo: Rapidu akiri, baldaŭ rabado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'Kaj mi prenis al mi du fidindajn atestantojn: la pastron Urija, kaj Zeĥarjan, filon de Jebereĥja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Kaj mi iris al la profetino, kaj ŝi gravediĝis kaj naskis filon. Kaj la Eternulo diris al mi: Donu al li la nomon: Rapidu-Akiri-Baldaŭ-Rabado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Ĉar antaŭ ol la knabo povoscios voki: Mia patro, kaj Mia patrino, la riĉaĵon de Damasko kaj la rabakiron de Samario oni portos antaŭ la reĝo de Asirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Kaj plue la Eternulo parolis al mi, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Pro tio, ke ĉi tiu popolo malŝatis la akvon de Ŝiloaĥ, kiu fluas kviete, kaj ĝojas pro Recin kaj pro la filo de Remalja:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'pro tio la Sinjoro jen venigos sur ilin la akvon de la Rivero, la forta kaj granda, la reĝon de Asirio kaj lian tutan gloron; kaj ĝi leviĝos super ĉiujn siajn kuŝujojn kaj iros super ĉiujn siajn bordojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'Kaj ĝi enpenetros en Judujon, inundos, leviĝos, kaj atingos ĝis la kolo; kaj ĝi etendos siajn flugilojn kaj plenigos vian tutan landon, ho Emanuel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Koleru, ho popoloj, tamen vi ektimos; atentu, vi ĉiuj en la malproksimaj landoj; armu vin, sed vi ektimos; armu vin, sed vi ektimos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Pripensu entreprenon, sed ĝi neniiĝos; parolu vortojn, sed ili ne plenumiĝos, ĉar kun ni estas Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Ĉar tiel diris al mi la Eternulo, tenante la manon sur mi, kaj Li instruis al mi, ke mi ne iru la vojon de tiu popolo, kaj Li diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'Ne nomu konspiro ĉion tion, kion tiu popolo nomas konspiro; kaj tion, kion ĝi timas, ne timu, kaj tio vin ne teruru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'La Eternulo Cebaot estu por vi sankta; Lin vi timu, kaj Li estu por vi terura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'Li estos sanktaĵo kaj ŝtono de falpuŝiĝo kaj roko de alfrapiĝo por la du domoj de Izrael, kaptilo kaj falilo por la loĝantoj de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'Kaj multaj falpuŝiĝos, kaj falos kaj rompiĝos, kaj enretiĝos kaj kaptiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Ligu la ateston, sigelu la leĝon ĉe Miaj lernantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Kaj mi atendas la Eternulon, kiu kaŝis Sian vizaĝon antaŭ la domo de Jakob, kaj mi esperas al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Jen, mi kaj la infanoj, kiujn la Eternulo donis al mi, estas kiel signoj kaj atentigiloj en Izrael de la Eternulo Cebaot, kiu loĝas sur la monto Cion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'Kaj se oni diros al vi: Demandu la antaŭdiristojn kaj la sorĉistojn, la flustristojn kaj la murmuretistojn, ĉar popolo ja demandas sian Dion, per la mortintoj por la vivantoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'tiam al la instruo kaj al la atesto! se ili ne diros konforme al tio, ili ne havos matenan ĉielruĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'Ili irados sur ĝi premataj kaj malsataj; kaj kiam ili estos malsataj, ili koleros kaj insultos sian reĝon kaj sian Dion, kaj rigardos supren.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'Kaj la teron ili rigardos, kaj ili vidos mizeron kaj mallumon, premantan mallumon, kaj en la mallumon ili estos puŝataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Sed ne restos la mallumo super tiuj, kiuj estas premataj: kiel la antaŭa tempo humiligis la landon de Zebulun kaj la landon de Naftali, la sekvonta tempo glorigos la apudmaran vojon, la transan flankon de Jordan, la Galileon de la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Popolo, kiu iris en mallumo, ekvidis grandan lumon; super homoj, sidantaj en lando de morta ombro, ekbrilis lumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Vi multigis la popolon, Vi grandigis ĝian ĝojon; ili ĝojas antaŭ Vi, kiel oni ĝojas dum la rikolto, kiel oni ĝojas ĉe dividado de rabakiro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Ĉar la jugon de ilia ŝarĝo, la kanon de ilia ŝultro, kaj la bastonon de ilia premanto Vi rompis, kiel en la tempo de Midjan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Ĉar ĉiu armaĵo de tiuj, kiuj sin brue armis, kaj la vestoj, kiuj ruliĝis en sango, estos forbruligitaj, ekstermitaj per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Ĉar infano naskiĝis al ni, filo estas donita al ni, kaj la regado estos sur lia ŝultro, kaj lia nomo estos: Mirinda, Konsilisto, Potenculo, Patro de Eterneco, Princo de Paco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'por pligrandigi la regadon kaj por paco senfina sur la trono de David kaj en lia regno, por fortikigi ĝin kaj fortigi ĝin per justeco kaj vero de nun ĝis eterne. La fervoro de la Eternulo Cebaot tion faros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Vorton sendis la Sinjoro al Jakob, kaj ĝi falis en Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'Tion sciu la tuta popolo, Efraim kaj la loĝantoj de Samario, kiuj diras kun fiereco kaj kun malhumila koro:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Brikoj falis, sed el hakitaj ŝtonoj ni konstruos; sikomoroj estas dishakitaj, sed ni anstataŭigos ilin per cedroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'La Eternulo fortigos kontraŭ ili la malamikojn de Recin, kaj liajn kontraŭulojn Li ekscitos,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'la Sirianojn de antaŭe kaj la Filiŝtojn de malantaŭe; kaj ili formanĝos Izraelon per la tuta buŝo. Malgraŭ ĉio ĉi tio ne kvietiĝis Lia kolero, kaj Lia brako estas ankoraŭ etendita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Sed la popolo ne turnas sin al Tiu, kiu ĝin batas, kaj la Eternulon Cebaot ili ne serĉas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Tial la Eternulo dehakos ĉe Izrael la kapon kaj la voston, branĉon kaj kanon, en unu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'Maljunulo kaj eminentulo estas la kapo; kaj profeto, kiu instruas malveraĵon, estas la vosto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'La gvidantoj de tiu popolo erarigas, kaj la gvidatoj pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Tial la Sinjoro ne ĝojos pro iliaj junuloj, kaj iliajn orfojn kaj vidvinojn Li ne kompatos; ĉar ĉiuj estas hipokrituloj kaj malbonaguloj, kaj ĉiu buŝo parolas malnoblaĵon. Malgraŭ ĉio ĉi tio ne kvietiĝis Lia kolero, kaj Lia brako estas ankoraŭ etendita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Ĉar la malbonageco ekbrulis kiel fajro, dornojn kaj pikarbustojn ĝi formanĝas, ĝi brulas en densejo de arbaro, kaj leviĝas kolonoj da fumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'De la kolero de la Eternulo Cebaot ekbrulis la tero, kaj la popolo fariĝis manĝaĵo por la fajro; neniu kompatas sian fraton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Oni tranĉas dekstre kaj restas malsataj, oni manĝas maldekstre kaj ne satiĝas; ĉiu manĝas la karnon de sia brako.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, 'Manase estas kontraŭ Efraim, kaj Efraim kontraŭ Manase, ambaŭ kune kontraŭ Jehuda. Malgraŭ ĉio ĉi tio Lia kolero ne kvietiĝis, kaj Lia brako estas ankoraŭ etendita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Ve al la leĝdonantoj, kiuj starigas maljustajn leĝojn, kaj al tiuj, kiuj skribas maljustajn verdiktojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'por forpuŝi malriĉulojn de la leĝo kaj forrabi la justecon de senhavuloj de Mia popolo, por ke la vidvinoj fariĝu ilia rabakiro, kaj por prirabi la orfojn!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Sed kion vi faros en la tago de puno kaj de pereo, kiu venos de malproksime? al kiu vi kuros, por serĉi helpon? kaj kie vi lasos vian honoron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'por ne fleksiĝi inter la kaptitoj kaj ne fali inter la mortigitoj? Malgraŭ ĉio ĉi tio Lia kolero ne kvietiĝis, kaj Lia brako estas ankoraŭ etendita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Ve al la Asiriano, la vergo de Mia kolero! la bastono en iliaj manoj estas Mia indigno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Kontraŭ popolon hipokritan Mi lin sendos, kaj pri la popolo de Mia kolero Mi donos al li ordonon, ke li prenu militakiron, ke li rabu rabaĵon, kaj ke li piedpremu ĝin kiel koton sur la stratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Sed li ne tiel tion komprenas, kaj lia koro ne tiel intencas; li intencas ekstermi kaj dispremi ne malmulte da popoloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'ĉar li diras: Ĉu miaj princoj ĉiuj ne estas reĝoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Ĉu Kalno ne estas kiel Karkemiŝ? ĉu Ĥamat ne estas kiel Arpad? ĉu Samario ne estas kiel Damasko?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Ĉar mia mano trafis la regnojn idolistajn, kies idoloj estas pli multaj ol en Jerusalem kaj en Samario,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'tial, kiel mi agis kun Samario kaj ĝiaj idoloj, tiel mi agos kun Jerusalem kaj ĝiaj idoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Sed kiam la Sinjoro plenumos Sian tutan faron sur la monto Cion kaj en Jerusalem, Mi rememoros la frukton de la malhumila reĝo de Asirio kaj la majeston de liaj arogantaj okuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'ĉar li diris: Mi tion faris per la forto de mia mano kaj per mia saĝeco, ĉar mi estas saĝa; mi forigis la limojn de la popoloj, rabis iliajn provizojn, kaj mi deĵetis kiel potenculo la sidantojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'kaj mia mano trovis la riĉaĵon de la popoloj kiel neston; kaj kiel oni enkolektas forlasitajn ovojn, mi enkolektis la tutan teron; kaj neniu movis flugilon, malfermis la buŝon, nek krietis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Ĉu povas hakilo fanfaroni antaŭ tiu, kiu hakas per ĝi? ĉu povas segilo fieri antaŭ tiu, kiu ĝin tiras? kvazaŭ vergo svingus tiun, kiu ĝin levas! kvazaŭ bastono levus tiun, kiu ne estas el ligno!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Tial la Sinjoro, la Eternulo Cebaot, venigos malgrasecon sur liajn grasulojn, kaj sub lia gloro ekbrulos fajro, kiel flamo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'Kaj la lumo de Izrael fariĝos fajro, kaj lia Sanktulo fariĝos flamo; kaj ĝi forbruligos kaj ekstermos liajn pikarbustojn kaj dornojn en unu tago,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'kaj ekstermos la majeston de lia arbaro kaj de lia fruktoĝardeno, de la animo ĝis la karno; kaj li fariĝos kiel senfortigita kadukulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'La restaĵo de la arboj de lia arbaro estos malgrandnombra, kaj knabo povos ilin registri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'En tiu tago la restintoj de Izrael kaj la savitoj de la domo de Jakob ne plu fidos sian batanton, sed fidos fidele la Eternulon, la Sanktulon de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Konvertiĝos la restintoj, la restintoj de Jakob, al la Dio potenca.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Ĉar se via popolo, ho Izrael, eĉ estos kiel la apudmara sablo, nur la restintoj konvertiĝos; ĉar estas decidita ekstermo per inunda justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Ĉar deciditan ekstermon la Sinjoro, la Eternulo Cebaot, faros en la tuta lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Tial tiele diras la Sinjoro, la Eternulo Cebaot: Ne timu la Asirianon, ho Mia popolo, kiu loĝas en Cion; per vergo li vin frapos, kaj sian bastonon li levos kontraŭ vin, kiel la Egiptoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'ĉar ankoraŭ tre malmulte daŭros, kaj finiĝos la kolero kaj Mia furiozo pro iliaj malbonagoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'kaj la Eternulo Cebaot aperigos vipon super li, kiel Li frapis la Midjanidojn ĉe la roko Oreb kaj kiel Lia bastono estis super la maro, kaj Li levos ĝin, kiel kontraŭ la Egiptojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'Kaj en tiu tago lia ŝarĝo estos deprenita de sur viaj ŝultroj kaj lia jugo de sur via kolo, kaj la jugo krevos pro la graseco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Li venas Ajaton, trapasas Migronon, revizias siajn armilojn en Miĥmaŝ;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'ili trapasis la pasejon, tradormas la nokton en Geba; Rama tremas, Gibea de Saul forkuras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Kriu laŭte, filino de Galim! atentu, Laiŝ! ho malriĉa Anatot!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madmena cedas, la loĝantoj de Gebim forkuras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Jam hodiaŭ li restos en Nob; li etendas sian manon kontraŭ la monton de la filino de Cion, kontraŭ la monteton de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Jen la Sinjoro, la Eternulo Cebaot, kun forto dehakos branĉojn; la alte leviĝintaj estos dehakitaj, kaj la fieraj estos humiligitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Kaj Li pereigos la densajn partojn de la arbaro per fero, kaj Lebanon falos de la Potenculo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Eliros markoto el la trunko de Jiŝaj, kaj branĉo elkreskos el ĝiaj radikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'Kaj estos sur li la spirito de la Eternulo, spirito de saĝo kaj prudento, sprito de konsilo kaj forto, spirito de sciado kaj de timo antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'Kaj agrabla estos al li la timo antaŭ la Eternulo; kaj ne laŭ la rigardo de siaj okuloj li juĝados, ne laŭ la aŭdo de siaj oreloj li eldirados verdiktojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'sed li juĝados malriĉulojn laŭ vero, kaj laŭ justeco li eldirados verdiktojn por humiluloj de la lando; kaj li frapos la teron per la vergo de sia buŝo, kaj per la spiro de siaj lipoj li mortigos malpiulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Vero estos la zono de lia lumbo, kaj fideleco la zono de liaj koksoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Kaj loĝos lupo kun ŝafido, kaj leopardo kuŝos kun kaprido; kaj bovido kaj leonido kaj grasigita bruto estos kune, kaj malgranda knabo ilin kondukos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Kaj bovino paŝtiĝos kun urso, kaj iliaj idoj kuŝos kune; kaj leono simile al bovo manĝos pajlon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'Kaj suĉinfano ludos super la truo de aspido, kaj demamigita infano metos sian manon sur la neston de vipuro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Oni ne malbonagos kaj ne difektos sur Mia tuta sankta monto, ĉar la tero estos tiel plena de konado de la Eternulo, kiel la akvo plenigas la maron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'En tiu tempo al la radiko de Jiŝaj, kiu staros kiel standardo por la popoloj, celados la nacioj; kaj lia ripozejo estos honoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'En tiu tempo la Sinjoro denove etendos Sian manon, por akiri la restaĵon de Sia popolo, kiu restis de Asirio kaj de Egiptujo kaj de Patros kaj de Etiopujo kaj de Elam kaj de Ŝinar kaj de Ĥamat kaj de la insuloj de la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'Kaj Li levos standardon inter la nacioj kaj kolektos la dispelitojn de Izrael, kaj la disĵetitojn de Jehuda Li kolektos de la kvar finoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Kaj malaperos la envio kontraŭ Efraimon, kaj la premantoj de Jehuda ekstermiĝos; Efraim ne envios Jehudan, kaj Jehuda ne premos Efraimon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'Sed ili flugos kune al la Filiŝtoj okcidenten, prirabos la filojn de la oriento, sur Edomon kaj Moabon ili metos sian manon; kaj la Amonidoj ilin obeos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'Kaj la Eternulo sekigos la golfon de Egiptujo, kaj svingos Sian manon kun forta vento super la Rivero, kaj dividos ĝin en sep riveretojn, kiujn oni povos transiri en ŝuoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'Kaj estos vojo por la restaĵo de Lia popolo, kiu restos de Asirio, kiel estis al Izrael en la tempo, kiam li eliris el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'En tiu tago vi diros: Mi dankas Vin, ho Eternulo; ĉar kvankam Vi koleris min, Via kolero jam foriĝis, kaj Vi konsolas min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Jen Dio estas mia savo: mi fidas, kaj mi ne timas; ĉar Dio, la Eternulo, estas mia forto kaj mia kanto, kaj Li fariĝis mia savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'Kaj vi ĉerpos kun ĝojo akvon el la fontoj de la savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'Kaj vi diros en tiu tago: Danku la Eternulon, voku Lian nomon, sciigu Liajn farojn inter la popoloj, memorigu, ke Lia nomo estas alta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Kantu al la Eternulo, ĉar majestaĵon Li faris; tio estu sciata sur la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Ĝojkriu kaj kantu, loĝantino de Cion; ĉar granda estas inter vi la Sanktulo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Profetaĵo pri Babel, kiun viziis Jesaja, filo de Amoc.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Sur senarba monto levu standardon, laŭte voku al ili, faru signon per la mano, ke ili eniru en la pordegon de la eminentuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Mi ordonis al Miaj sanktigitoj, Mi kunvokis al Mia kolero Miajn fortulojn, kiuj ĝojas pro Mia majesteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Bruo de amaso estas sur la montoj, kvazaŭ de grandnombra popolo! bruo de la regnoj de nacioj kolektiĝintaj! la Eternulo Cebaot ĉirkaŭrigardas la batalontan militistaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Ili venis el lando malproksima, de la rando de la ĉielo, la Eternulo kaj la iloj de Lia kolero, por ruinigi la tutan landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Ĝemu, ĉar proksima estas la tago de la Eternulo; kiel katastrofo ĝi venos de la Plejpotenculo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Tial ĉiuj manoj senfortiĝas kaj ĉiu homa koro senkuraĝiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'Ili estas terurataj, spasmoj kaj doloroj ilin atakas, ili sin tordas, kiel naskantino; kun miro ili rigardas unu alian, iliaj vizaĝoj flamas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Jen venis la tago de la Eternulo, kruela kaj kolera kaj furioza, por fari la landon dezerto kaj ekstermi el ĝi ĝiajn pekulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'La steloj de la ĉielo kaj ĝiaj stelfiguroj ne donas sian lumon, la suno mallumiĝis leviĝante, kaj la luno ne briligos sian lumon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'Mi repagos al la mondo la malbonon kaj al la malpiuloj ilian kulpon; Mi ĉesigos la fierecon de la malhumiluloj, kaj la arogantecon de la potenculoj Mi malaltigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Mi faros, ke viro estos pli kara, ol oro, kaj homo estos pli kara, ol la ora metalo el Ofir.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Por tio Mi ektremigos la ĉielon, kaj la tero skuiĝos el sia loko, pro la kolero de la Eternulo Cebaot kaj en la tago de Lia flama kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'Ili estos kiel gazelo persekutata, kiel ŝafo forlasita; ĉiu sin turnos al sia popolo, kaj ĉiu kuros al sia lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Ĉiu renkontita estos trapikita, kaj ĉiu kaptita falos de glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Iliaj infanoj estos frakasitaj antaŭ iliaj okuloj; iliaj domoj estos prirabitaj, kaj iliaj edzinoj estos malhonoritaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Mi vekos kontraŭ ilin la Medojn, kiuj ne ŝatas arĝenton kaj oron ne avidas,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'sed per pafarkoj mortigas junulojn, frukton de ventro ne kompatas; infanojn ne indulgas ilia okulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'Kaj Babel, la plej bela el la regnoj, la majesta belaĵo de la Ĥaldeoj, estos kiel Sodom kaj Gomora, ruinigitaj de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'neniu iam tie sidos, kaj por eterne ĝi restos neloĝata; Arabo ne starigos tie sian tendon, kaj paŝtistoj tie ne ripozos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Ripozos tie sovaĝaj bestoj, kaj iliaj domoj estos plenaj de gufoj, kaj strutoj tie loĝos, kaj virkaproj tie saltados.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'Kaj ŝakaloj bruos en iliaj palacoj, kaj strigoj en la salonoj de amuzo. Kaj baldaŭ venos ĝia tempo, kaj ĝiaj tagoj ne daŭros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Ĉar la Eternulo ekkompatos Jakobon, kaj denove elektos Izraelon, kaj reloĝigos ilin en ilia lando. Kaj fremduloj kuniĝos kun ili, kaj aliĝos al la domo de Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Kaj popoloj prenos ilin kaj venigos ilin sur ilian lokon, kaj la domo de Izrael ekposedos ilin en la lando de la Eternulo kiel sklavojn kaj sklavinojn. Kaj ili malliberigos siajn malliberigintojn kaj regos siajn premintojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'Kaj en tiu tago, kiam la Eternulo ripozigos vin de via suferado kaj de via mizero, kaj de la malfacila laborado, per kiu oni laborigis vin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'vi eldiros ĉi tiun mokokanton pri la reĝo de Babel, kaj diros: Kiel kvietiĝis la premanto, ĉesiĝis la tributo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'La Eternulo rompis la bastonon de la maljustuloj, la vergon de la regantoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'kiu kolere batadis popolojn per batoj senĉesaj, kolere regadis popolojn, senĉese persekutante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Ekripozis, trankviliĝis la tuta tero, ĝojkrias, kantante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Eĉ la cipresoj ĝojas pri vi, la cedroj de Lebanon: De tiu tempo, kiam vi ekkuŝis, neniu hakanto venas al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Ŝeol sube ekskuiĝis pro vi, renkontante vin venantan; ĝi vekis por vi la mortintojn, ĉiujn potenculojn de la tero; ĝi levis por vi de iliaj tronoj ĉiujn reĝojn de la popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Ili ĉiuj ekparolos kaj diros al vi: Vi ankaŭ senfortiĝis, kiel ni, vi similiĝis al ni;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'en Ŝeolon estas ĵetita via majesto kaj la bruo de viaj psalteroj; sub vi sterniĝos vermoj, kaj vermoj estos via kovrilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Kial vi falis de la ĉielo, ho brilo, filo de la matenruĝo! hakita sur la teron vi estas, ho turmentinto de la popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Kaj vi diris en via koro: Mi supreniros en la ĉielon, pli alten ol la steloj de Dio mi levos mian tronon, kaj mi sidos sur la monto de kunveno, ĉe la rando de nordo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'mi supreniros sur la altaĵon de la nuboj, mi similiĝos al la Plejaltulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Sed en Ŝeolon vi estos mallevita, en la profundon de la tombo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Tiuj, kiuj vin vidos, rigardos vin atente, kaj miros: Ĉu ĉi tio estas la viro, kiu tremigis la teron, teruris regnojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'kiu faris la mondon dezerto kaj ruinigis ĝiajn urbojn, kiu siajn kaptitojn ne liberigis hejmen?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Ĉiuj reĝoj de popoloj kuŝas kun honoro, ĉiu en sia domo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'sed vi estas forĵetita el via tombo, kiel malŝatata branĉo, kovrita de mortigitoj, trapikitaj per glavo, ĵetitaj malsupren en kavon, kiel kadavro piedpremata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Vi ne estos kun ili en tombo, ĉar vian landon vi ruinigis, vian popolon vi mortigis; la semon de malbonaguloj oni neniam nomos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Preparu liajn filojn por buĉo pro la pekoj de iliaj patroj, por ke ili ne leviĝu kaj ne heredu la landon kaj ne plenigu la mondon per urboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Mi leviĝos kontraŭ ilin, diras la Eternulo Cebaot; kaj Mi ekstermos de Babel la nomon kaj restaĵon kaj filon kaj nepon, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'Kaj Mi faros ĝin heredaĵo de botaŭroj, kaj akvaj marĉoj, kaj Mi balaos ĝin per balailo de pereigo, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Ĵuris la Eternulo Cebaot, dirante: Kiel Mi intencis, tiel fariĝos; kaj kiel Mi decidis, tiel efektiviĝos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'frakasita estos la Asiriano en Mia lando, kaj sur Miaj montoj Mi lin dispremos, por ke foriĝu de ili lia jugo kaj lia ŝarĝo estu deprenita de sur iliaj ŝultroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'Tio estas la decido, farita pri la tuta tero; kaj tio estas la mano, etendita super ĉiujn popolojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Ĉar la Eternulo Cebaot decidis, kaj kiu malhelpos? kaj Lia mano estas etendita, kiu do ĝin returnos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'En la jaro de la morto de la reĝo Aĥaz estis farita la sekvanta profetaĵo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Ne ĝoju, tuta Filiŝtujo, ke rompita estas la vergo, kiu vin batadis; ĉar el la radiko de serpento eliros vipuro, kaj ĝia produkto estos fluganta serpento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'Kaj la unuenaskitoj de malriĉuloj paŝtiĝos, kaj senhavuloj ripozos sendanĝere; kaj Mi pereigos per malsato vian radikon, kaj via restaĵo estos mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Ĝemploru, ho pordego; kriu, ho urbo; perdis la kuraĝon la tuta Filiŝtujo; ĉar de nordo venas fumo, kaj neniu restas sola en iliaj taĉmentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Kaj kion oni respondos al la senditoj de la popolo? Ke la Eternulo fortikigis Cionon, kaj en ĝi trovos defendon la malriĉuloj de Lia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Profetaĵo pri Moab: En nokto ruiniga pereis Ar-Moab, en nokto ruiniga pereis Kir-Moab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Ili iris en la domon kaj sur la altaĵojn de Dibon, por plori; pri Nebo kaj Medba ĝemploras Moab; ĉiuj kapoj estas kalvaj, ĉiuj barboj estas razitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Sur siaj stratoj ili ĉirkaŭzonis sin per sakaĵoj; sur iliaj tegmentoj kaj placoj ĉiuj ĝemkrias, konsumiĝas per plorado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'Krias Ĥeŝbon kaj Eleale, ĝis Jahac oni aŭdas ilian voĉon; tial ĝemploras la armitoj de Moab, lia animo tremas en li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Mia koro krias pro Moab; liaj forkurintoj kuras ĝis Coar, ĝis la tria Eglat; ĉar laŭ la vojo supren al Luĥit ili iras plorante, ĉar sur la vojo al Ĥoronaim leviĝas kriado de malfeliĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Ĉar la akvo de Nimrim sekforiĝis, ĉar sekiĝis la herbo, malaperis kreskaĵoj, verdaĵo jam ne ekzistas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Tial la abundaĵon, kiun ili kolektis, kaj sian ŝparitaĵon ili transportas trans la riveron de la salikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Ĉar la kriado ĉirkaŭas la limojn de Moab, ĝis Eglaim atingas lia plorado, kaj ĝis Beer-Elim atingas lia plorado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Ĉar la akvo de Dimon estas plena de sango; ĉar Mi ankoraŭ pli multe venigos sur Dimonon, leonon sur la saviĝintojn de Moab kaj sur la restaĵon de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Sendu ŝafidon al la reganto de la tero el Sela en la dezerto sur la monton de la filino de Cion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Kiel vaganta birdo, elpelita el la nesto, tiel estos la filinoj de Moab ĉe la transirejoj de Arnon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Aranĝu konsilon, faru decidon; simile al nokto faru vian ombron meze de la tago; kaŝu la elpelitojn, ne malkaŝu la vaganton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Miaj elpelitaj Moabidoj loĝu ĉe vi; estu por ili ŝirmo kontraŭ la rabanto, ĝis ĉesiĝos la premado, finiĝos la rabado, malaperos la piedpremanto el la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'Kaj fortikiĝos trono per favorkoreco, kaj sur ĝi kun justeco en la tendo de David sidos juĝisto, celanta justecon, akcelanta la veron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Ni aŭdis pri la fiereco de Moab, ke ĝi estas tre granda; lia malhumileco kaj fiereco kaj furiozado estas pli granda, ol lia forto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Tial ĝemkrios Moab pri si mem, ĉiuj ĝemkrios; pri la fundamentoj de Kir-Ĥareset ili ploras, profunde frapitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Ĉar la kampoj de Ĥeŝbon dezertiĝis, ankaŭ la vinberĝardenoj de Sibma; la estroj de la popoloj dishakis la plej bonajn branĉojn, kiuj atingis ĝis Jazer, etendiĝis en la dezerton; ĝiaj markotoj disĵetiĝis, transiris la maron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Tial per la ploro de Jazer mi ploros pri la vinberĝardeno de Sibma; mi priverŝos vin per miaj larmoj, ho Ĥeŝbon kaj Eleale; ĉar krioj de triumfo falis sur viajn somerajn fruktojn kaj sur vian grenrikolton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'Foriĝis de la kampo ĝojo kaj gajeco, kaj en la vinberĝardenoj oni ne kantas nek ĝojkrias; vinon en la vinpremejoj oni ne premas; la ĝojkriojn Mi ĉesigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Tial mia interno sonas pri Moab kiel harpo, kaj mia koro pri Kir- Ĥeres.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'Kaj kiam montriĝos, ke Moab senfortiĝis sur la altaĵo, kaj eniros en sian templon, por preĝi, li nenion atingos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Tio estas la vorto, kiun la Eternulo diris pri Moab antaŭ longe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Sed nun la Eternulo diris jene: Post tri jaroj, kiel estas la jaroj de dungito, malaltiĝos la gloro de Moab kun la tuta grandnombreco, kaj restos tre malmulte, malgrandnombre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Profetaĵo pri Damasko: Jen Damasko ne plu estos urbo, sed ĝi estos amaso da ruinaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Forlasitaj estos la urboj de Aroer; brutaroj tie paŝtiĝos, kaj neniu ilin fortimigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Kaj detruita estos la fortikaĵo de Efraim, kaj la regno de Damasko kaj la restaĵo de Sirio estos kiel la gloro de la Izraelidoj, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'En tiu tempo maldikiĝos la gloro de Jakob, kaj lia grasa korpo malgrasiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Kaj estos tiel, kiel kiam rikoltanto enkolektis la grenon kaj lia mano rikoltis la spikojn, kaj estos kiel post la rikolto de spikoj en la valo Refaim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Kaj restos tie postrikoltaĵo, kiel ĉe la skuado de olivarbo: du, tri olivoj sur la supro de alta branĉo, kvar, kvin sur la branĉoj fruktoportaj, diras la Eternulo, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'En tiu tempo la homo sin turnos al sia Kreinto, kaj liaj okuloj ekrigardos al la Sanktulo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'Kaj li ne turnos sin al la altaroj, faritaj de liaj manoj, kaj ne rigardos al la faritaĵo de siaj fingroj, al la sanktaj stangoj kaj la idoloj de la suno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'En tiu tempo liaj urboj fortikigitaj estos kiel ruinoj en arbaro aŭ sur altaĵo, kiujn oni forlasis pro la Izraelidoj, kaj ili estos dezertaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Ĉar vi forgesis la Dion de via savo kaj ne memoris la Rokon de via forteco; tial vi plantis plantaĵojn plezurigajn kaj kreskigis fremdan vinberbranĉon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'en la tago, kiam vi plantis, vi zorgis pri la kreskado, kaj en la mateno, kiam vi semis, vi zorgis pri la floroj; sed en la tago de ricevado estas ne rikolto, sed doloro suferiga.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Ho ve! bruo de multe da popoloj; ili bruas simile al la bruo de maroj; kaj tumulto de gentoj, kiel tumulto de grandaj akvoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Gentoj bruas simile al la bruado de grandaj akvoj; sed Li minace ekkrios al ili, kaj ili forkuros malproksimen, kaj ili estos pelataj, kiel grenventumaĵo sur la montoj estas pelata de vento, kaj kiel polvo estas pelata de ventego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Dum la vespero jen estas teruro; sed antaŭ la mateno ili jam ne ekzistas. Tia estas la sorto de niaj premantoj kaj la loto de niaj rabantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Ve al la lando flanke ombrata, kiu troviĝas transe de la riveroj Etiopaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'kiu sendas senditojn per la maro kaj per kanaj ŝipoj sur la akvo! Iru, rapidaj senditoj, al la popolo grandkreska kaj glathaŭta, al la popolo, kiu estas pli terura, ol kia ajn alia, al la popolo laŭregulara kaj piedpremanta, kies landon tratranĉas riveroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Vi ĉiuj, kiuj troviĝas en la mondo kaj loĝas sur la tero! rigardu, kiam oni levos standardon; kaj aŭskultu, kiam oni ekblovos per trumpeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Ĉar tiel diris al mi la Eternulo: Mi restos trankvila kaj rigardos en Mia loĝejo, kiel serena varmego ĉe hela lumo, kiel rosa nubo ĉe varmego de rikolto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Ĉar antaŭ la rikolto, kiam la florado finiĝis kaj la floro fariĝis matura bero, Li detranĉos la branĉojn per tranĉiloj kaj deprenos la vinberbranĉojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Ĉio kune estos lasita por la rabobirdoj de la montoj kaj por la bestoj de la tero; kaj la rabobirdoj loĝos super ĝi en somero, kaj ĉiaj bestoj de la tero super ĝi vintros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'En tiu tempo sur la lokon de la nomo de la Eternulo Cebaot, sur la monton Cion, alportos donacojn al la Eternulo Cebaot la popolo grandkreska kaj glathaŭta, la popolo, kiu estas pli terura, ol kia ajn alia, la popolo laŭregulara kaj piedpremanta, kies landon tratranĉas riveroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Profetaĵo pri Egiptujo: Jen la Eternulo veturos sur malpeza nubo kaj venos Egiptujon. Kaj ektremos antaŭ Li la idoloj de Egiptujo, kaj la koro de la Egiptoj senkuraĝiĝos interne de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Kaj Mi tumultigos Egiptojn kontraŭ Egiptojn; kaj militos ĉiu kontraŭ sia frato kaj ĉiu kontraŭ sia amiko, urbo kontraŭ urbo, regno kontraŭ regno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'Kaj malaperos la kuraĝo de la Egiptoj interne de ili, kaj Mi detruos iliajn intencojn; kaj ili demandos la idolojn kaj la sorĉistojn kaj la aŭguristojn kaj la antaŭdiristojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Kaj Mi transdonos la Egiptojn en la manon de kruela sinjoro, kaj senkompata reĝo regos super ili, diras la Sinjoro, la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'Kaj sekforiĝos la akvo el la maro, kaj la rivero senakviĝos kaj sekiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'Kaj senhaviĝos la riveroj, elĉerpiĝos kaj sekiĝos la kanaloj de Egiptujo, kano kaj junko velkos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'La herbejoj apudakvaj, super la akvo mem, kaj ĉio semita apud la akvo velkos, sekiĝos, kaj malaperos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Kaj malĝojos la fiŝkaptistoj, kaj ploros ĉiuj, kiuj ĵetas fiŝhokojn en la akvon, kaj la etendantoj de retoj surakvaj estos malfeliĉaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Kaj hontos la prilaboristoj de lino kombita kaj la teksistoj de blanka tolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Kaj la pilastroj de la lando estos disbatitaj; ĉiuj dungatoj estos malgajaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Malsaĝaj estas la princoj de Coan; la saĝaj konsilistoj de Faraono fariĝis senkonsilaj. Kiel vi diros al Faraono: Mi estas filo de saĝuloj, ido de antikvaj reĝoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Kie do nun estas viaj saĝuloj? ili do diru al vi kaj sciigu, kion la Eternulo Cebaot decidis pri Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Malsaĝiĝis la princoj de Coan, trompiĝis la princoj de Nof, erarigis Egiptujon, la fundamenton de siaj gentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'La Eternulo verŝis en ilin spiriton de konfuzo; kaj ili erarigis Egiptujon en ĉiuj ĝiaj faroj, kiel ebriulo ŝanceliĝas vomante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'Kaj estos en Egiptujo nenia faro, kiun farus kapo aŭ vosto, branĉo aŭ kano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'En tiu tempo Egiptujo estos kiel virinoj; ĝi tremos kaj timos antaŭ la moviĝo de la mano de la Eternulo Cebaot, kiun Li svingos super ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'Kaj la lando de Jehuda fariĝos teruraĵo por la Egiptoj; ĉiu, kiu rememoros ĝin, ektimos, pro la decido de la Eternulo Cebaot, kiun Li decidis pri ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'En tiu tempo estos en la lando Egipta kvin urboj, parolantaj la lingvon Kanaanan kaj ĵurantaj per la Eternulo Cebaot; unu havos la nomon Urbo de Detruo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'En tiu tempo estos altaro por la Eternulo meze de la lando Egipta, kaj monumento por la Eternulo apud ĝia limo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'kaj ĝi estos signo kaj atesto pri la Eternulo Cebaot en la lando Egipta; ĉar ili krios al la Eternulo pro la premantoj, kaj Li sendos al ili savanton kaj potenculon, kiu savos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'Kaj la Eternulo fariĝos konata al la Egiptoj; kaj la Egiptoj tiam ekkonos la Eternulon, kaj alportos buĉoferojn kaj farunoferojn, kaj faros sanktajn promesojn al la Eternulo kaj plenumos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'La Eternulo frapos la Egiptojn, frapos kaj resanigos; kaj ili returnos sin al la Eternulo, kaj Li aŭskultos ilian peton kaj resanigos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'En tiu tempo estos vojo de Egiptujo al Asirio; kaj la Asirianoj venados en Egiptujon kaj la Egiptoj en Asirion, kaj la Egiptoj servados kune kun la Asirianoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'En tiu tempo Izrael estos triope kun Egiptujo kaj Asirio; estos beno sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'La Eternulo Cebaot benos ilin, dirante: Benataj estu Mia popolo la Egiptoj, kaj Asirio, verko de Miaj manoj, kaj Mia heredaĵo Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'En la jaro, kiam Tartan venis Aŝdodon, kien lin sendis Sargon, reĝo de Asirio, kaj li militis kontraŭ Aŝdod kaj prenis ĝin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'en tiu tempo la Eternulo parolis per Jesaja, filo de Amoc, dirante: Iru, kaj demetu la sakaĵon de via lumbo, kaj demetu la ŝuojn de viaj piedoj. Kaj li faris tiel; li iris nuda kaj nudpieda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Kaj la Eternulo diris: Kiel Mia servanto Jesaja iris nuda kaj nudpieda por trijara montrado kaj antaŭdirado pri Egiptujo kaj Etiopujo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'tiel la reĝo de Asirio kondukos la kaptitajn Egiptojn kaj la ekzilitajn Etiopojn, junulojn kaj maljunulojn, nudajn kaj nudpiedajn kaj kun nudaj hontaj partoj, malhonore por la Egiptoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'Kaj ili havos teruron kaj honton pro Etiopujo, kiun ili fidis, kaj pro Egiptujo, pri kiu ili fanfaronis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Kaj en tiu tempo diros la loĝantoj de tiu apudmara lando: Jen kia estas nia fidita lando, kien ni kuris, por serĉi helpon, por savi nin kontraŭ la reĝo de Asirio; kiamaniere ni nun savos nin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Profetaĵo pri la apudmara dezerto: Kiel renversanta de ventego de sudo, li venas el la dezerto, el lando terura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Kruela vizio estas montrita al mi: rabanto rabas, kaj ruiniganto ruinigas. Supreniru, ho Elam; sieĝu, ho Medujo; ĉiun ĝemadon mi ĉesigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Tial mia lumbo estas plena de doloro; turmentoj kaptis min, kiel turmentoj de naskantino; mi tordiĝis, kiam mi aŭdis; mi sentis teruron, kiam mi vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Konsterniĝas mia koro, teruro min frapis; la ĉarma nokto fariĝis por mi teruro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Preparu tablon, starigu gardostarantojn, manĝu, trinku. Leviĝu, princoj, ŝmiru la ŝildon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Ĉar tiele diris al mi mia Sinjoro: Iru, starigu observanton; kion li vidos, li diru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Kaj li vidis vicojn da ĉevaloj duope, vicojn da azenoj, vicojn da kameloj; kaj li aŭskultis atente, kun granda atento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'Kaj li ekkriis kiel leono: Mia sinjoro, mi staris konstante sur mia observejo dum la tago, kaj sur mia gardejo mi staris tutajn noktojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'kaj jen venis viro, veturanta sur duĉevala ĉaro, kaj li ekkrias kaj diras: Falis, falis Babel, kaj ĉiuj idoloj de ĝiaj dioj rompiĝis sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'Mia draŝaĵo, kaj filo de mia garbejo! kion mi aŭdis de la Eternulo Cebaot, Dio de Izrael, tion mi diris al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Profetaĵo pri Duma: Oni krias al mi el Seir: Gardisto, kiom da nokto restas? gardisto, kiom da nokto restas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'La gardisto diris: Venis la mateno, kaj tamen estas nokto; se vi volas demandi, demandu, revenu denove.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Profetaĵo pri Arabujo: En la arbaro Arabuja pasigu la nokton, karavanoj Dedanaj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Elportu akvon renkonte al la soifanto, vi, loĝantoj de la lando Tema, kun pano renkontu la forkurinton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'ĉar oni forkuras de glavo, de akrigita glavo, kaj de pafarko streĉita, kaj de kruela batalo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Ĉar tiele diris al mi la Sinjoro: Post unu jaro, kiel la jaro de dungito, malaperos la tuta gloro de Kedar;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'kaj la restaĵo de la heroaj arkpafistoj de Kedar estos malgranda; ĉar la Eternulo, Dio de Izrael, diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Profetaĵo pri la valo de vizio: Kio nun estas al vi, ke vi ĉiuj iris sur la tegmentojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'Vi, plena de bruo, urbo tumulta, urbo gaja, viaj mortigitoj ne estas mortigitaj per glavo kaj ne mortis en batalo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'ĉiuj viaj ĉefoj kune forkuris de pafarko; ĉiuj, kiujn oni trovis ĉe vi, estas ligitaj; ligitaj estas kune ĉiuj, kiuj forkuris malproksimen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Tial mi diris: Forturnu vin de mi, mi ploros maldolĉe; ne penu konsoli min pri la malfeliĉo de la filino de mia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Ĉar tio estas tago de konsterno kaj de piedpremado kaj de konfuzo antaŭ la Sinjoro, la Eternulo Cebaot, en la valo de vizio; detruado de muroj kaj vokado al la montoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Kaj Elam portis sagujon en vico da rajdantoj, kaj Kir briligis ŝildon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'Kaj viaj plej bonaj valoj pleniĝis de ĉaroj, kaj rajdantoj sin aranĝis antaŭ la pordego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Kaj oni formetis la kurtenon de Jehuda; kaj vi rigardis en tiu tago la armilojn de la arbara domo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'kaj vi vidis, ke estas multe da fendoj en la urbo de David; kaj vi kolektis la akvon de la malsupra lageto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'Kaj vi kalkulis la domojn de Jerusalem; kaj vi detruis la domojn, por fortikigi la muron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'Kaj inter la du muroj vi faris basenon por la akvo de la malnova lageto. Sed vi ne direktis vian rigardon al Tiu, kiu tion faris, kaj ĝian antikvan Kreinton vi ne rigardis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Kaj en tiu tago la Sinjoro, la Eternulo Cebaot, vokis, ke oni ploru kaj kriu, kaj detranĉu siajn harojn kaj surmetu sur sin sakaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'Jen estas ĝojo kaj gajeco: oni mortigas bovojn, buĉas ŝafojn; oni manĝas viandon kaj trinkas vinon, dirante: Ni manĝu kaj trinku, ĉar morgaŭ ni mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Sed al mia orelo malkaŝis la Eternulo Cebaot: Ĉi tiu malbonagado ne estos pardonita al vi, ĝis vi mortos, diris la Sinjoro, la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Tiele diris la Sinjoro, la Eternulo Cebaot: Iru, venu al tiu administranto, al Ŝebna, la palacestro, kaj diru:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'Kion vi havas ĉi tie? kaj kiun vi havas ĉi tie, ke vi elhakigis al vi ĉi tie tombon? Li elhakigas alte sian tombon, li elĉizigas en la roko loĝejon por si.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Jen la Eternulo forte vin ĵetos kaj forte vin kaptos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'Li volvos vin kaj rulos kiel globon en vastan landon; tie vi mortos, tie restos la ĉaroj de via gloro, vi, malhonoro de la domo de via sinjoro!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Kaj Mi depuŝos vin de via posteno, kaj el via ofico vi estos forigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'Kaj en tiu tago Mi alvokos Mian servanton Eljakim, filon de Ĥilkija,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'kaj Mi vestos lin per via ĥitono kaj zonos per via zono, kaj vian regadon Mi transdonos en lian manon; kaj li estos patro por la loĝantoj de Jerusalem kaj por la domo de Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Kaj Mi metos la ŝlosilon de la domo de David sur lian ŝultron; kaj li malfermos, kaj neniu fermos; kaj li fermos, kaj neniu malfermos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'Kaj Mi fortikigos lin kiel najlon sur loko fidinda, kaj li estos trono de honoro en la domo de sia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'Kaj pendos sur li la tuta gloro de la domo de lia patro, la infanoj kaj idoj, ĉiuj malgrandaj vazoj, de la vazoj por manĝado ĝis la vazoj por trinkado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'En tiu tago, diras la Eternulo Cebaot, estos forigita la najlo, fortikigita sur loko fidinda; ĝi estos rompita kaj falos, kaj pereos la ŝarĝo, kiu estis sur ĝi; ĉar la Eternulo diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Profetaĵo pri Tiro: Plorkriu, ho ŝipoj de Tarŝiŝ; ĉar ĝi estas detruita tiel, ke restis neniu domo, neniu pordo. El la lando de la Kitidoj tio estas sciigita al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Silentu, ho loĝantoj de la apudmara lando. Komercistoj de Cidon, transveturantaj la maron, vin plenigadis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'sur granda akvo oni venigadis al ĝi semojn de Ŝiĥor, rikoltaĵon de Nilo; kaj ĝi estis komercejo de la popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Hontu, Cidon; ĉar la maro, la mara fortikaĵo diris: Mi ne havis dolorojn, mi ne naskis, mi ne edukis knabojn, mi ne kreskigis knabinojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Kiam oni tion aŭdos en Egiptujo, oni ektremos ĉe la sciigo pri Tiro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Transiru al Tarŝiŝ, plorkriu, ho loĝantoj de la apudmara lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Ĉu tio estas via gaja urbo, la tre antikva? ĝiaj piedoj forportas ĝin, por loĝi malproksime.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Kiu decidis tion pri Tiro, la kronita, kies komercistoj estas princoj kaj kies negocistoj estas eminentuloj de la lando?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'La Eternulo Cebaot tion decidis, por malaperigi la majeston de ĉiu gloro, por humiligi ĉiujn eminentulojn de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Trapasu vian landon kiel rivero, ho filino de Tarŝiŝ; jam nenio vin zonas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Sian manon Li etendis super la maron, Li skuis regnojn; la Eternulo faris ordonon pri Kanaan, por ekstermi liajn fortikaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'Kaj Li diris: Vi en plu estos gaja, vi, senhonorigita virgulino, filino de Cidon! Leviĝu, transiru al la Kitidoj; sed ankaŭ tie vi ne havos trankvilecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Jen la lando de la Ĥaldeoj: ĉi tiu popolo ne ekzistis; la Asiriano ĝin fondis por la loĝantoj de la dezerto; ili starigis sieĝajn turojn, detruis ĝiajn palacojn, faris ĝin ruino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Plorkriu, ho ŝipoj de Tarŝiŝ; ĉar detruita estas via potenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'En tiu tempo Tiro estos forgesita dum sepdek jaroj, kiuj estas kiel la tempo de unu reĝo; post la fino de la sepdek jaroj estos kun Tiro tio, kion oni kantas pri malĉastistino:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, 'Prenu la harpon, ĉirkaŭiru la urbon, ho forgesita malĉastistino; ludu bone, kantu multe, por ke oni rememoru vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Kaj post la fino de la sepdek jaroj la Eternulo vizitos Tiron, kiu denove ricevados promalĉastajn donacojn kaj malĉastados kun ĉiuj regnoj de la mondo sur la supraĵo de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Kaj ĝia komercenspezo kaj ĝiaj promalĉastaj donacoj estos konsekritaj al la Eternulo; ili ne estos kolektataj en trezorejon nek konservataj; sed por tiuj, kiuj loĝas antaŭ la vizaĝo de la Eternulo, estos ĝia komercenspezo, por ke ili manĝu sate kaj havu belajn vestojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Jen la Eternulo dezertigas la landon kaj ruinigas ĝin kaj ŝanĝas ĝian aspekton kaj disĵetas ĝiajn loĝantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'Kaj estos al la popolo kiel al la pastro, al la servisto kiel al lia mastro, al la servistino kiel al ŝia mastrino, al la aĉetanto kiel al la vendanto, al la pruntedonanto kiel al la prunteprenanto, al la ŝuldanto kiel al la kreditoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Tute dezertigita estos la lando kaj tute prirabita; ĉar la Eternulo tion diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Funebras kaj velkas la lando, senfortiĝas kaj velkas la mondo, senfortiĝas la eminentuloj de la popolo de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Kaj la tero estas malpurigita de siaj loĝantoj; ĉar ili malobeis la instruon, ŝanĝis la leĝon, detruis la eternan interligon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Pro tio malbeno konsumis la teron, kaj kulpiĝis tiuj, kiuj loĝas sur ĝi; pro tio forbrulis la loĝantoj de la lando kaj restis malmulte da homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Malgaja estas la mosto, sensukiĝis la vinbero, ĝemas ĉiuj ĝojintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Ĉesiĝis la gajeco de tamburinoj, malaperis la bruo de gajuloj, ĉesiĝis la gajeco de harpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Oni ne trinkas vinon ĉe kantado; maldolĉa estas ebriigaĵo por siaj trinkantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'Ruinigita estas la dezerta urbo; ĉiuj domoj estas fermitaj tiel, ke oni ne povas eniri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Oni ploras sur la stratoj pri vino; mallumiĝis ĉia ĝojo, malaperis la gajeco de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'En la urbo restis dezerteco, kaj la pordegoj disbatitaj estas ruinigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Ĉar tiel estos meze de la lando, meze de la popoloj: kiel post fruktoskuo de olivarbo, kiel estas al la restintaj beroj post la fino de la vinberrikolto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Ili levos sian voĉon kaj ĝojkrios, pri la majesto de la Eternulo ili krios de la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'Tial en la regionoj orientaj gloru la Eternulon, sur la insuloj de la maro la nomon de la Eternulo, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'De la rando de la tero ni aŭdis kantadon: Gloro al la justulo; sed mi diras: Ho mi malfeliĉa, ho mi malfeliĉa, ve al mi! rabis rabistoj, kaj per granda rabado ili rabis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Teruro, kavo, kaj kaptilo trafos vin, ho loĝantoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'Kaj tiu, kiu forkuros de la voĉo de la teruro, falos en kavon; kaj kiu eliros el la kavo, trafos en la kaptilon; ĉar la aperturoj de alte malfermiĝis kaj la fundamento de la tero ekskuiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'Forte diskrevis la tero, forte dispeciĝis la tero, forte skuiĝis la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'Ŝanceliĝas la tero kiel ebriulo, kaj balanciĝas kiel hamako; kaj pezas sur ĝi ĝia krimeco; kaj ĝi falis, kaj ne plu leviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'Kaj en tiu tempo punos la Eternulo la taĉmentojn de la alto en la ĉielo kaj la reĝojn de la tero sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'Kaj ili estos kolektitaj kune, ligitaj en malliberejo, kaj ili estos enŝlositaj en ŝlositejo, kaj post longa tempo ili estos punitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'Kaj ruĝiĝos la luno, kaj hontos la suno, kiam la Eternulo Cebaot ekreĝos sur la monto Cion kaj en Jerusalem, kaj Lia gloro aperos antaŭ Liaj plejaĝuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Ho Eternulo, Vi estas mia Dio; mi gloros Vin, mi laŭdos Vian nomon; ĉar Vi faris miraklon; decidoj antikvaj fariĝis efektivaĵoj kaj veraĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Ĉar Vi faris el urbo amason da ŝtonoj; urbon fortikigitan Vi faris ruino; la kasteloj de la barbaroj ne plu prezentas urbon kaj neniam rekonstruiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Pro tio gloros Vin popolo potenca, urbo de fortaj gentoj Vin timos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Ĉar Vi fariĝis fortikaĵo por senhavulo, fortikaĵo por malriĉulo en lia mizero, rifuĝejo kontraŭ pluvego, ombro kontraŭ varmego; ĉar la spirito de potenculoj estas kiel pluvego kontraŭ muron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Kiel varmegon en dezerto Vi kvietigis la malhumilecon de la barbaroj; kiel varmego per ombro de nubo estas mallaŭtigita la kantado de la potenculoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Kaj la Eternulo Cebaot faros por ĉiuj popoloj sur tiu monto festenon el grasaĵoj, festenon el bona vino, el grasaĵoj sukoplenaj, el vinoj ne fermentintaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'Kaj Li forigos sur tiu monto la kovrilon, kiu kovras ĉiujn popolojn, kaj la kurtenon, kiu estas etendita super ĉiuj gentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Li neniigos la morton por ĉiam; kaj la Sinjoro, la Eternulo, forviŝos la larmojn de ĉiuj vizaĝoj, kaj la honton de Sia popolo Li forigos de la tuta tero; ĉar la Eternulo tion diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'Kaj oni diros en tiu tago: Jen estas nia Dio, al kiu ni esperis, kaj Li nin savis; jen estas la Eternulo, al kiu ni esperis, ni ĝoju kaj estu gajaj pro Lia savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Ĉar haltos la mano de la Eternulo sur tiu monto; tiam Moab estos dispremita sur sia loko, kiel pajlo estas dispremata en sterka koto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'Kaj se li etendos siajn manojn meze de ĝi, kiel naĝanto etendas, por naĝi, tiam humiliĝos lia fiereco kune kun la lerteco de liaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'Kaj viajn altajn fortikajn murojn Li renversos, malaltigos, ĵetos sur la teron al la polvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'En tiu tago la jena kanto estos kantata en la lando Juda: Ni havas urbon potencan; savon Li starigas kiel murojn kaj remparon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Malfermu la pordegojn, por ke eniru la popolo justa, konservanta la fidelecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Por la fidmensulo Vi konservos pacon absolutan; ĉar Vin li fidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Fidu la Eternulon por ĉiam; ĉar en Dio, la Eternulo, estas roko eterna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Ĉar Li ĵetis malsupren loĝantojn de la altaĵo, urbon alte leviĝintan; Li malaltigis ĝin, malaltigis ĝis la tero, ĵetis ĝin al la polvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Piedo ĝin premas, la piedoj de malriĉuloj, la plandoj de senhavuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'La vojo de justulo estas rekta; Vi, Pravulo, ebenigas la vojon de justulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Eĉ sur la vojo de Via juĝo, ho Eternulo, ni esperis al Vi; Vian nomon kaj la memoron pri Vi sopiris nia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Per mia animo mi sopiris Vin en la nokto, per mia spirito en mia interno mi serĉis Vin matene; ĉar dum Via juĝado sur la tero la loĝantoj de la mondo lernis justecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Se malvirtulo estas indulgata, li ne lernas justecon; en lando de justeco li agas maljuste kaj ne rigardas la majeston de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Ho Eternulo, levita estis Via mano, sed ili ne vidis tion; ili ekvidos kun honto Vian ĵaluzon pri la popolo; Via flama kolero kontraŭ Viaj malamikoj formanĝos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Ho Eternulo, Vi starigos por ni pacon; ĉar ankaŭ ĉiujn niajn aferojn Vi faris por ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Ho Eternulo, nia Dio! regis super ni sinjoroj krom Vi, sed nur per Vi ni gloras Vian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Ili mortis kaj ne reviviĝos, ili estas malvivuloj kaj ne releviĝos; ĉar Vi ilin punis kaj ekstermis, kaj Vi malaperigis ĉiun memoron pri ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Vi multigis la popolon, ho Eternulo, Vi multigis la popolon; Vi gloriĝis vaste sur ĉiuj finoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Ho Eternulo, en mizero ili rememoris Vin, ili preĝis mallaŭte, kiam Vi ilin punis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Kiel gravedulino ĉe la alproksimiĝo de la naskado turmentiĝas kaj krias en siaj doloroj, tiel ni estis antaŭ Vi, ho Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Ni estis gravedaj, ni turmentiĝis, ni naskis kvazaŭ venton; savon ni ne venigis al la tero, kaj ne falis la loĝantoj de la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Reviviĝos Viaj mortintoj, miaj kadavroj releviĝos. Vekiĝu kaj ĝoju vi, kuŝantaj en la tero; ĉar roso sur kreskaĵoj estas Via roso, kaj la tero elĵetos la mortintojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Iru, mia popolo, eniru en viajn ĉambrojn kaj ŝlosu viajn pordojn post vi; kaŝu vin por mallonga momento, ĝis pasos la kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Ĉar jen la Eternulo eliros el Sia loko, por puni la malbonagojn de la loĝantoj de la tero; kaj la tero malkaŝos sian sangon kaj ne plu kovros siajn mortigitojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'En tiu tago la Eternulo punos per Sia peza kaj granda kaj forta glavo la levjatanon, la serpenton eltordiĝeman, kaj la levjatanon, la serpenton kurbiĝantan; kaj Li mortigos la drakon, kiu estas en la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'En tiu tago kantu pri ĝi, pri la kara vinberĝardeno:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Mi, la Eternulo, estas ĝia gardanto; ĉiumomente Mi trinkigas ĝin; por ke neniu ĝin difektu, Mi gardas ĝin tage kaj nokte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Ĉu Mi ne havas koleron? ĉu iu elmetus batale kontraŭ Mi dornojn kaj pikarbustojn? Mi elpaŝus kontraŭ ilin, kaj ĉiujn kune forbruligus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Nur en la okazo, se oni serĉus Mian defendon, por fari pacon kun Mi, oni farus kun Mi pacon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'En la estonteco Jakob enradikiĝos; Izrael ekfloros kaj ellasos verdajn branĉojn; kaj ili plenigos la mondon per fruktoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Ĉu li estis frapata tiel, kiel estis frapataj liaj frapantoj? aŭ ĉu li estas mortigita tiel, kiel estas mortigitaj liaj mortigintoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Nur kiam la mezuro tro pleniĝis, Vi punis lin per ekzilo: Li elpelis lin per Sia potenca blovo en la tago de orienta vento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Tial tiamaniere estos forviŝita la malbonagado de Jakob; kaj la tuta frukto de la forigo de lia peko konsistos en tio, ke li faros ĉiujn ŝtonojn de la altaroj kiel dispeciĝintaj kalkŝtonoj, ke ne plu restu la sanktaj stangoj kaj la idoloj de la suno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Ĉar urbo fortikigita estos solecigita, loĝloko estos forlasita kaj forrestigita kiel dezerto; tie paŝtiĝos bovido, tie ĝi ripozos kaj formanĝos ĝiajn kreskaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Kiam sekiĝos ĝiaj branĉoj, oni ilin rompos; venos virinoj kaj forbruligos ilin. Ĉar tio ne estas popolo prudenta, tial ĝia Kreinto ne kompatos ĝin, kaj ĝia Farinto ĝin ne indulgos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'Kaj en tiu tago la Eternulo debatos la fruktojn, komencante de la fluo de la Rivero ĝis la torento de Egiptujo; kaj vi, ho Izraelidoj, estos kolektitaj unu post unu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Kaj en tiu tago oni ekblovos per granda trumpeto, kaj venos tiuj, kiuj perdiĝis en la lando Asiria kaj kiuj estis elpelitaj en la landon Egiptan, kaj ili adorkliniĝos antaŭ la Eternulo sur la sankta monto en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Ve al la fiera krono de la ebriuloj de Efraim! ilia bela majesto estas velkinta floro; sur la supro de grasa kampo ili estas senkonsciigitaj de vino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Jen la Sinjoro havas fortulon kaj potenculon; kiel hajla pluvego, kiel pereiga ventego, kiel inundo de forta disverŝiĝinta akvo, li potence ĵetos ilin sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Per piedoj estos premata la fiera krono de la ebriuloj de Efraim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'Kaj ilia bela majesto fariĝos velkinta floro sur la supro de grasa kampo, kiel figo antaŭ la somero; kiam la vidanto ĝin ekvidas, li, apenaŭ preninte ĝin en la manon, tuj ĝin englutas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'En tiu tago la Eternulo Cebaot estos majesta krono kaj bela diademo por la restaĵo de Sia popolo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'kaj spirito de justeco por la sidantoj en la juĝejo, kaj forto por tiuj, kiuj rebatas la batalon al la pordego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Sed ankaŭ ĉi tiuj ŝanceliĝas de vino kaj balanciĝas de drinkaĵo; pastro kaj profeto ŝanceliĝas de drinkaĵo, senkonsciiĝas de vino, vagas pro drinkaĵo, eraras en la vidado, falpuŝiĝas ĉe la juĝa verdikto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Ĉar ĉiuj tabloj estas plenaj de vomaĵo kaj malpuraĵo, mankas jam loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'Al kiu li instruas scion, kaj al kiu li aŭdigas predikon? ĉu al forprenitaj for de lakto, al demamigitoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Ĉar ordono post ordono, ordono post ordono; regulo post regulo, regulo post regulo; iom tie, iom ĉi tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'Per balbutantaj lipoj kaj per lingvo fremda Li parolos al ili,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'Tiu, kiu diris al ili: Jen estas ripozejo, lasu la laculon ripozi; kaj jen estas trankviligo; sed ili ne volis aŭskulti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'Kaj aperos al ili la vorto de la Eternulo, ordono post ordono, ordono post ordono, regulo post regulo, regulo post regulo, iom tie, iom ĉi tie; por ke ili iru kaj falu dorsen kaj rompiĝu kaj enretiĝu kaj kaptiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Tial aŭskultu la vorton de la Eternulo, vi, mokistoj, regantoj de tiu popolo, kiu estas en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Ĉar vi diras: Ni faris interligon kun la morto, kaj kun Ŝeol ni faris interkonsenton; kiam la frapanta vipo estos trapasanta, ĝi nin ne atingos, ĉar mensogon ni faris nia rifuĝejo kaj per malvero ni nin kovros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'Pro tio tiele diris la Sinjoro, la Eternulo: Jen Mi por fundamento kuŝigas ŝtonon en Cion, ŝtonon elprovitan, bazangulan, valoregan, fortikigitan fundamenton; la fidanto ne maltrankviliĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'Kaj Mi faros justecon la mezurŝnuro, kaj veron la vertikalo; kaj hajlo forbatos la rifuĝejon de mensogo, kaj la kaŝejon forportos akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'Kaj forigita estos via interligo kun la morto, kaj via interkonsento kun Ŝeol ne teniĝos; kiam la frapanta vipo estos trapasanta, vi estos frakasata de ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Ĉiufoje, kiam ĝi trairos, ĝi kaptos vin; ĉar ĉiutage ĝi trairos, tage kaj nokte, kaj terura estos la klarigo, kiun ĝi donos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Ĉar tro mallonga estos la lito, por sin etendi; kaj la litkovrilo estos tro mallarĝa, por sin enkovri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Ĉar la Eternulo leviĝos, kiel sur la monto Peracim, Li koleros, kiel en la valo Gibeona, por plenumi Sian faron, Sian eksterordinaran faron, kaj fari Sian laboron, Sian eksterordinaran laboron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Kaj nun ne moku, por ke viaj katenoj ne plifortiĝu; ĉar mi aŭdis, ke de la Sinjoro, la Eternulo Cebaot, tio estas neŝanĝeble decidita pri la tuta lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Atentu, kaj aŭskultu mian voĉon; konsideru, kaj aŭskultu mian parolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Ĉu ĉiutage la plugisto plugas por semado, sulkaranĝas kaj erpas sian kampon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Kiam li ebenigis ĝian supraĵon, li disŝutas ja nigelon kaj disĵetas kuminon kaj metas tritikon laŭ vicoj kaj hordeon en la difinitan lokon kaj spelton ĉe la limoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Tian ordon lernigis al li lia Dio, Li instruis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Ĉar ne per fera draŝilo oni draŝas nigelon, kaj oni ne rulas radon de ĉaro sur kumino; sed per bastono oni elbatas nigelon, kaj kuminon per vergo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Greno estas draŝata; sed ne eterne oni ĝin draŝas; oni frapas ĝin per la rado de sia ĉaro, sed per siaj ĉevaloj oni ĝin ne dispremas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Ankaŭ ĉi tio venas de la Eternulo Cebaot; mirinda estas Lia decido, granda estas Lia saĝeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Ve al Ariel, al Ariel, al la urbo, en kiu sidis David! aldonu jaron al jaro, la festoj faru sian ciklon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Mi premos Arielon, kaj estos ĝemado kaj malĝojo; kaj li estos al Mi vera Ariel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Kaj Mi sieĝos vin ĉirkaŭe, kaj Mi premos vin per remparo, kaj Mi starigos kontraŭ vi turojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Kaj vi parolos malalte el sub la tero, kaj el sub la polvo vi murmuros viajn vortojn; kaj via voĉo estos kiel voĉo de ventroparolisto el sub la tero, kaj el sub la polvo vi flustros viajn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Sed la multego de viaj malamikoj estos kiel subtila polvo, kaj la multo de la premantoj estos kiel disfluganta grenventumaĵo; kaj tio fariĝos subite, neatendite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'De la Eternulo Cebaot vi estos punata kun tondro kaj tertremo kaj granda bruo, kun ventego kaj turnovento kaj konsumeganta fajra flamo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Kaj kiel sonĝo, kiel nokta vizio estos la multo de la popoloj, kiuj batalos kontraŭ Ariel kaj kontraŭ ĉiuj liaj fortikaĵoj kaj kiuj premos lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Kiel malsatanto sonĝas, ke li manĝas, sed li vekiĝas, kaj lia interno estas malplena; kaj kiel soifanto sonĝas, ke li trinkas, sed li vekiĝas, kaj li estas senforta kaj lia animo forte soifas: tiel estos kun la multego de ĉiuj popoloj, kiuj batalos kontraŭ la monto Cion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Haltu kaj miru, ŝajnigu vin blindaj kaj blindiĝu. Ili ebriiĝis, sed ne de vino; ili ŝanceliĝas, sed ne de drinkaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Ĉar la Eternulo verŝis sur vin spiriton de profunda dormo kaj fermis viajn okulojn, vualis la profetojn kaj viajn estrojn, la viziistojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Kaj ĉia vizio estos por vi kiel la vortoj de libro sigelita, kiun oni donas al homo, kiu povoscias legi, dirante al li: Volu legi ĉi tion; sed li respondas: Mi ne povas, ĉar ĝi estas sigelita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'Sed kiam oni donas la libron al homo, kiu ne povoscias legi, dirante al li: Volu legi ĉi tion, li respondas: Mi ne povoscias legi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Kaj la Sinjoro diris: Ĉar ĉi tiu popolo alproksimiĝas per sia buŝo kaj honoras Min per siaj lipoj, sed ilia koro estas malproksime de Mi, kaj ilia timo antaŭ Mi estas nur lernita ordono de homoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'tial Mi plue agos mirinde kun ĉi tiu popolo, Mi agos tre mirinde; kaj pereos la saĝeco de ĝiaj saĝuloj, kaj la kompetenteco de ĝiaj kompetentuloj malaperos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Ve al tiuj, kiuj profunde kaŝas antaŭ la Eternulo la intencojn, kaj kies faroj estas en mallumo, kaj kiuj diras: Kiu nin vidas? kaj kiu scias pri ni?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Ho, via perverseco! Ĉu la potfaristo estas rigardata kiel egala al la argilo? ĉu faritaĵo diras pri sia farinto: Li min ne faris? kaj ĉu kreitaĵo diras pri sia kreinto: Li ne estas kompetenta?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Sed jen baldaŭ, post mallonga tempo, Lebanon aliformiĝos en fruktoportan kampon, kaj la fruktoporta kampo estos rigardata kiel arbaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'Kaj en tiu tago la surduloj aŭdos la vortojn de la libro, kaj la okuloj de la blinduloj ekvidos tra mallumo kaj nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'Kaj la mizeruloj havos grandan ĝojon en la Eternulo, kaj la homoj malriĉaj triumfos en la Sanktulo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Ĉar malaperos premanto, kaj ne plu ekzistos blasfemanto, kaj ekstermitaj estos ĉiuj zorgantoj pri malbonagoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'kiuj pekigas homojn per vorto kaj faras insidojn kontraŭ juĝopetanto ĉe la pordego kaj trompe forpuŝas justulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Pro tio tiele diris pri la domo de Jakob la Eternulo, kiu elaĉetis Abrahamon: Nun Jakob ne hontos, kaj nun lia vizaĝo ne paliĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Ĉar kiam li vidos meze de si siajn infanojn, la faron de Miaj manoj, ili honoros Mian nomon kaj honoros la Sanktulon de Jakob kaj respektos la Dion de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'Kaj la spirite-erarantoj ricevos prudenton, kaj la malpacemuloj akceptos instruon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Ve al la filoj malobeemaj, diras la Eternulo, kiuj faras interkonsilojn, sed sen Mi, kaj aranĝas interkonsentojn, sed sen Mia spirito, por aligi pekon al peko,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'kaj kiuj iras Egiptujon, ne demandinte Mian buŝon, por defendi sin per defendo de Faraono kaj kaŝi sin en la ombro de Egiptujo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Sed la defendo de Faraono estos por vi honto, kaj la kaŝiĝo en la ombro de Egiptujo-malhonoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Ĉar liaj princoj estis en Coan, kaj liaj senditoj venis en Ĥaneson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'Ĉiuj hontos pro la popolo, kiu ne servis al ili por helpo, nek por utilo, sed nur por honto kaj malhonoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Jen oni vidas ŝarĝojn sur bestoj en sudo, en lando de mizero kaj suferoj, kie estas leonino kaj leono, vipuro kaj fluganta serpento; ili forportas sur la dorso de junaj azenoj siajn riĉaĵojn kaj sur la ĝibo de kameloj siajn trezorojn al popolo, kiu ne povas utili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'La helpo de la Egiptoj estas vanta kaj vana; tial Mi diris pri tio: Ili fanfaronas, sidante hejme.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Nun iru, skribu tion al ili sur tabelo kaj desegnu tion en libro, por ke tio restu por la tempo estonta, por ĉiam, por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Ĉar tio estas popolo malobeema, filoj mensogaj, filoj, kiuj ne volas aŭskulti instruon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'Ili diras al la antaŭvidistoj: Ne antaŭvidu; kaj al la profetoj: Ne profetu al ni la veron, parolu al ni flataĵojn, profetu al ni gajaĵon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'flankiĝu for de la vojo, dekliniĝu de la irejo, forigu de antaŭ ni la Sanktulon de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Tial tiele diras la Sanktulo de Izrael: Ĉar vi malŝatas tiun vorton kaj fidas maljustaĵon kaj trompon kaj apogas vin sur ĉi tio:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'tial ĉi tiu kulpo estos por vi kiel fendo, minacanta disfalon kaj montranta sin sur alta muro, kies falo estos subita, neatendita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'Kaj Li frakasos ĝin, kiel oni frakasas argilan vazon, frakasos senindulge, tiel ke en ĝiaj rompopecoj ne troviĝos vazopeco, por preni fajron de la fajrujo aŭ ĉerpi akvon el akvujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Ĉar tiele diras la Sinjoro, la Eternulo, la Sanktulo de Izrael: Per pento kaj trankvileco vi saviĝus, en kvieteco kaj fido estus via forto; sed vi ne volis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'Vi diris: Ne, ni forkuros sur ĉevaloj; tial vi forkuros; kaj: Sur rapiduloj ni forrajdos; tial rapidaj estos viaj persekutantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'De la minaco de unu forkuros tuta milo, de la minaco de kvin vi ĉiuj forkuros, ĝis vi restos kiel signo sur la supro de monto kaj kiel flago sur monteto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Tial la Eternulo atendos, antaŭ ol Li vin korfavoros, kaj tial Li leviĝos, antaŭ ol Li vin kompatos; ĉar la Eternulo estas Dio de juĝo; feliĉaj estas ĉiuj, kiuj fidas Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Ĉar, ho popolo de Cion, loĝantoj de Jerusalem, vi ne plu ploros; Li korfavoros vin, kiam vi plorkrios; kiam Li aŭdos vin, Li respondos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Kaj la Sinjoro donos al vi panon en la mizero kaj akvon en la premado; kaj ne plu kaŝiĝos viaj instruantoj, kaj viaj okuloj vidos viajn instruantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'Kaj kiam vi dekliniĝos ĉu dekstren, ĉu maldekstren, viaj oreloj aŭdos vortojn diratajn malantaŭ vi: Jen estas la vojo, iru laŭ ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Kaj vi rigardos kiel malpuran la arĝentan tegon de viaj statuoj kaj la oran kovron de viaj idoloj; vi forĵetos ilin kiel malpuraĵon, vi diros al ili: For!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Kaj Li donos pluvon al via semo, kiun vi semos sur la kampo, kaj panon, produkton de la tero, kaj ĝi estos sukoplena kaj grasa; sur vasta paŝtejo paŝtiĝos tiam viaj brutoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'Kaj la bovoj kaj junaj azenoj, kiuj prilaboros la teron, manĝos miksitan nutraĵon, ŝutitan per kribrilo kaj ŝovelilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'Kaj sur ĉiu alta monto kaj sur ĉiu alta monteto estos riveroj, torentoj da akvo, en la tago de la granda mortigado, kiam falos la turoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'Kaj la lumo de la luno estos kiel la lumo de la suno, kaj la lumo de la suno estos sepoble pli granda, kiel la lumo de sep tagoj, en tiu tempo, kiam la Eternulo bandaĝos la difektojn de Sia popolo kaj resanigos ĝiajn vundojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Jen la nomo de la Eternulo venas de malproksime; Lia kolero flamas kaj estas pezega; Lia buŝo estas plena de indigno, kaj Lia lango estas kiel fajro ekstermanta;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'kaj Lia spiro estas kiel torento disverŝiĝinta, kiu atingas ĝis la kolo, por trakribri la popolojn per kribrilo de pereo; kaj erariga brido estos sur la makzeloj de la popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Kantado estos ĉe vi, kiel en la nokto de celebrado de festo; kaj kora ĝojo, kiel ĉe tiu, kiu iras kun fluto, por veni sur la monton de la Eternulo al la Roko de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Kaj la Eternulo aŭdigos Sian majestan voĉon, kaj la pezon de Sia brako Li vidigos en bolanta kolero kaj en flamo de ekstermanta fajro, en ventego kaj pluvego kaj ŝtona hajlo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Ĉar ektremos la Asiriano de la voĉo de la Eternulo, kiu frapos lin per la vergo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'Kaj penetranta estos ĉiu ekbato per la bastono, kiun la Eternulo faligos sur lin kun tamburinoj kaj harpoj; kaj per bataloj senhaltaj Li batalos kontraŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Ĉar delonge estas preparita la bruligejo; ĝi estas preta ankaŭ por la reĝo, profundigita, vastigita; ĝia lignaro enhavas multe da fajro kaj ligno; la blovo de la Eternulo ekbruligos ĝin kiel torenton da sulfuro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Ve al tiuj, kiuj iras Egiptujon, por serĉi helpon, kaj esperas je ĉevaloj, kaj fidas ĉarojn, ĉar estas multe da ili, kaj rajdantojn, ĉar ili estas fortaj; sed ili ne rigardas al la Sanktulo de Izrael kaj ne demandas la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Sed Li estas saĝa, kaj Li venigas malfeliĉon, kaj Siajn vortojn Li ne reprenas; kaj Li leviĝos kontraŭ la domo de la malpiuloj kaj kontraŭ la helpanto de malbonagantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'La Egiptoj estas ja homoj, ne Dio; kaj iliaj ĉevaloj estas karno, ne spirito. Kiam la Eternulo etendos Sian manon, tiam falpuŝiĝos la helpanto kaj falos la helpato, kaj ĉiuj kune pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Ĉar tiele diris al mi la Eternulo: Kiel leono aŭ leonido blekegas super sia rabaĵo, kaj, se eĉ oni kunevokus kontraŭ ĝin multon da paŝtistoj, ĝi ne timas ilian voĉon kaj ne humiliĝas antaŭ ilia bruado, tiel la Eternulo Cebaot malsupreniros, por batali pro la monto Cion kaj pro ĝia altaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Kiel birdoj per siaj flugiloj, tiel la Eternulo Cebaot defendos Jerusalemon, defendos kaj savos, indulgos kaj liberigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Revenu al Tiu, de kiu tiel profunde defalis la filoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Ĉar en tiu tago ĉiu forĵetos siajn idolojn arĝentajn kaj siajn idolojn orajn, kiujn viaj manoj faris al vi por peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'Kaj la Asiriano falos de glavo ne vira, kaj glavo ne homa lin ekstermos; kaj li forkuros de glavo, kaj liaj junuloj fariĝos tributo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'Kaj lia forto forkuros pro timo, kaj liaj princoj ektremos antaŭ standardo, diras la Eternulo, kies fajro estas sur Cion kaj kies fajrejo estas en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Jen kun justeco regos reĝo, kaj princoj administros laŭleĝe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'Kaj ĉiu estos kiel ŝirmilo kontraŭ vento, kiel rifuĝejo kontraŭ pluvego, kiel torentoj da akvo en la stepo, kiel ombro de peza roko en lando dezerta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'La okuloj de vidantoj ne estos fermitaj, kaj la oreloj de aŭdantoj atentos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'Kaj la koro de senprudentuloj lernos scion, kaj la lango de balbutantoj parolos rapide kaj klare.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Oni ne plu nomos malnoblulon noblulo, kaj pri avarulo oni ne plu diros, ke li estas bonfaranto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Ĉar malnoblulo parolas malnoblaĵon, kaj lia koro faras malbonagojn, agante hipokrite kaj parolante pri la Eternulo malveraĵon, senmanĝigante la animon de malsatanto kaj forprenante trinkaĵon de soifanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'La iloj de malpiulo estas malbonaj; li havas intencojn malvirtajn, por pereigi malriĉulojn per vortoj mensogaj, eĉ kiam la senhavulo diras pravaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Sed noblulo havas intencojn noblajn, kaj li restas en nobleco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Virinoj senzorgaj, leviĝu, aŭskultu mian voĉon; filinoj ne pensantaj pri danĝero, atentu miajn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Post tagoj kaj jaro vi ektremos, ho senzorgulinoj; ĉar finita estos la vinberrikolto, ne plu estos enkolektado de fruktoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Maltrankviliĝu, ho senzorgaj; ektremu, ne pensantaj pri danĝero; senvestigu kaj nudigu vin kaj zonu la lumbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'Oni ploros pri la abundo, pri la ĉarmaj kampoj, pri la fruktoriĉaj vinberĝardenoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'Sur la tero de mia popolo kreskos pikarbustoj kaj dornoj, ankaŭ sur ĉiuj domoj de gajeco de la brua urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Ĉar la palacoj estos forlasitaj, la bruo de la urbo malaperos, la fortikaĵoj kaj turoj fariĝos por ĉiam anstataŭaĵo de kavernoj, ĝojloko por sovaĝaj azenoj, paŝtiĝejo por brutaroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'ĝis verŝiĝos sur nin spirito de supre kaj la dezerto fariĝos fruktodona kampo kaj la fruktodona kampo estos rigardata kiel arbaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'Kaj justeco ekloĝos en la dezerto, kaj vero sidos sur la fruktodona kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'Kaj produkto de justeco estos paco, kaj akiro de justeco estos trankvileco kaj sendanĝereco por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'Kaj mia popolo loĝos en loĝejo paca kaj en sidejoj sendanĝeraj kaj en ripozejoj senzorgaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'kaj disŝutiĝos kiel hajlo sur la deklivoj de arbaro, kaj malsupre en la valo etendiĝos la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Feliĉaj estas vi, kiuj semas super ĉiu akvo, kiuj lasas en libereco la piedojn de la bovo kaj de la azeno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Ve al vi, kiu rabas kaj mem ne estas prirabita, kaj kiu perfidas kaj mem ne estas perfidita! Kiam vi finos la rabadon, vi mem estos prirabita; kiam vi ĉesos perfidi, vi mem estos perfidita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Ho Eternulo, korfavoru nin! je Vi ni esperas; estu ilia brako ĉiumatene kaj nia savo en la tempo de mizero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'De la sono de tondro forkuris popoloj, de Via majesto diskuris gentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Kaj kolektita estos via rabakiro, kiel kolektas vermoj; kaj oni kuros post ĝi, kiel kuras akridoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'La Eternulo altiĝis, ĉar Li loĝas alte; Li plenigas Cionon per justeco kaj vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Saĝo kaj scio, forto de via savo, estos la garantiaĵo de via estonteco; timo antaŭ la Eternulo estos lia trezoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Jen iliaj fortuloj plorkrias ekstere, la anoncantoj de paco ploras maldolĉe;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'la vojoj senhomiĝis, vojiranto jam ne pasas; li rompis la interligon, malestimis la urbojn, ne ŝatis la homojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Funebras, malĝojas la tero; hontigita estas Lebanon kaj velkas; Ŝaron fariĝis kiel dezerto; Baŝan kaj Karmel senfoliiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Nun Mi stariĝos, diras la Eternulo; nun Mi altiĝos, nun Mi leviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Vi, gravedaj per fojno, naskos pajlon; via spiro estos fajro, kiu vin ekstermos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'Kaj la popoloj estos kiel bruligita kalko, kiel dornoj dehakitaj ili forbrulos en fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Aŭskultu, malproksimuloj, kion Mi faris; kaj ekkonu, proksimuloj, Mian forton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Ektimos la pekuloj sur Cion, tremo kaptos la hipokritulojn: Kiu el ni eltenos ĉe la ekstermanta fajro? kiu el ni eltenos ĉe la eterna ardego?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Kiu agas juste kaj parolas veron, abomenas profiton rabitan, forskuas siajn manojn, por ne preni subaĉeton, ŝtopas siajn orelojn, por ne aŭskulti aferojn sangajn, kaj fermas siajn okulojn, por ne rigardi malbonon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'tiu loĝos sur la altaĵoj; fortikaĵoj el rokoj estos lia defendo; pano estos donita al li, akvon li havos konstante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Viaj okuloj vidos la reĝon en lia majesto, ili rigardos landon vastan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Via koro rememoros la teruraĵon: Kie estas la kalkulanto? kie estas la pesanto? kie estas la kontrolanto de la turoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'La popolon arogantan vi ne vidos, la popolon kun lingvo malklara kaj nedistingebla, kun lingvo balbuta kaj nekomprenebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Rigardu Cionon, la urbon de niaj kunvenoj; viaj okuloj vidos Jerusalemon, loĝlokon trankvilan, tendon ne forigotan; neniam estos eltirataj ĝiaj stangoj, kaj neniu el ĝiaj ŝnuroj disŝiriĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Ĉar tie la forto de la Eternulo estos por ni anstataŭ riveroj, larĝaj lagoj; ŝipo kun remiloj ne iros sur ili, kaj potenca ŝipo ilin ne trapasos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Ĉar la Eternulo estas nia juĝanto, la Eternulo estas nia leĝdonanto, la Eternulo estas nia reĝo; Li helpos nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Viaj ŝnuregoj malfortiĝis; ili jam ne alfortikigas la maston, ne streĉas la velon. Tiam estos dividata la granda rabakiro; eĉ lamuloj iros kapti rabaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'Kaj ne diros la loĝanto: Mi estas malsana; al la popolo, kiu tie loĝas, estas pardonita la kulpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Alproksimiĝu, popoloj, por aŭskulti; kaj atentu, ho gentoj; aŭskultu la tero, kaj ĉio, kio ĝin plenigas, la mondo kaj ĉiuj ĝiaj produktoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Ĉar indignas la Eternulo kontraŭ ĉiuj popoloj kaj flame koleras kontraŭ ilia tuta anaro; Li kondamnis ilin, eldonis ilin al buĉado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'Kaj iliaj mortigitoj estos disĵetitaj, kaj iliaj kadavroj eligos malbonodoron, kaj la montoj trapenetriĝos de ilia sango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Kaj velkos la tuta estaĵaro de la ĉielo, kaj la ĉielo kuneruliĝos kiel skribrulaĵo; kaj ĝia tuta estaĵaro defalos, kiel defalas folio de vinberbranĉo kaj velkintaĵo de figarbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Ĉar Mia glavo ebriiĝis en la ĉielo; jen ĝi malsupreniras sur Edomon kaj sur Mian kondamnitan popolon, por fari juĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'La glavo de la Eternulo estas plena de sango, grasiĝis de sebo, de sango de ŝafoj kaj kaproj, de sebo de ŝafaj renoj; ĉar buĉoferadon la Eternulo aranĝos en Bocra kaj grandan buĉadon en la lando de Edom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Kaj falos bubaloj kun ili, kaj bovoj junaj kun bovoj grasigitaj, kaj ilia tero estos saturita de sango, kaj ilia polvo estos grasigita de sebo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Ĉar tio estas tago de venĝo de la Eternulo, jaro de repago pro la juĝafero de Cion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Kaj liaj riveroj aliformiĝos en peĉon kaj lia polvo en sulfuron, kaj lia tero fariĝos brulanta peĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'Nek tage nek nokte ĝi estingiĝos, eterne leviĝados ĝia fumo; de generacio al generacio ĝi restos dezerta, en eterneco neniu iros sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Ekposedos ĝin pelikano kaj botaŭro, kaj gufo kaj korvo loĝos sur ĝi; kaj Li etendos super ĝi rektoŝnuron de ruinigo kaj vertikalon de detruo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Ĝi ne havos potenculojn, kiuj povus tie proklami regnon, kaj ĉiuj ĝiaj princoj malaperos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'Kaj en ĝiaj palacoj kreskos dornoj kaj urtikoj, kaj sur ĝiaj fortikaĵoj kreskos pikarbustoj; kaj ĝi estos loĝejo de ŝakaloj, spaco por strutoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Kaj renkontiĝos tie sovaĝaj katoj kun sovaĝaj hundoj, kaj virkaproj krios unu al alia; nur strigo tie nestos kaj trovos por si ripozejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Tie nestos saltanta serpento kaj metos ovojn kaj kovos kaj kolektos en sia ombro; tie milvoj kolektiĝos unu al alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Serĉu en la libro de la Eternulo, kaj legu: eĉ unu el ili ne mankos, unu ne sentos foreston de alia; ĉar Lia buŝo tion ordonis kaj Lia spirito tion kolektas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Kaj Li mem lotumis por ili, kaj Lia mano dividis por ili laŭ rektoŝnuro; ili heredos tion por ĉiam, de generacio al generacio ili loĝos tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Ekĝojos la dezerto kaj la senakvejo, triumfos la stepo kaj ekfloros kiel lilio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Ĝi forte ekfloros kaj triumfos, triumfos kaj kantos; la gloro de Lebanon estos donita al ĝi, la beleco de Karmel kaj Ŝaron; ili vidos la gloron de la Eternulo, la majeston de nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Fortigu la senfortiĝintajn manojn, kaj fortikigu la ŝanceliĝantajn genuojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Diru al tiuj, kiuj estas senkuraĝigitaj en la koro: Tenu vin forte, ne timu; jen estas via Dio! venos venĝo, repago de Dio; Li mem venos kaj helpos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Tiam malkovriĝos la okuloj de la blinduloj, kaj la oreloj de la surduloj malfermiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Tiam la lamulo eksaltos kiel cervo, kaj la lango de la mutulo ekkantos; ĉar en la dezerto elfendiĝos akvo kaj en la stepo riveroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'Kaj la fantoma lago fariĝos reala, kaj la tero senakva fariĝos fonto de akvo; la loĝloko de ŝakaloj fariĝos loko por kano kaj junko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Kaj estos tie irejo kaj vojo, kaj ĝi estos nomata Vojo Sankta; malpurulo ne iros sur ĝi, ĉar nur al ili ĝi apartenas; irante sur tiu vojo, eĉ malsaĝuloj ne eraros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Ne estos tie leono, kaj rabobesto ne aperos sur ĝi, ne troviĝos tie; iros nur savitoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Kaj la elaĉetitoj de la Eternulo revenos kaj iros sur Cionon kun kantado, kaj ĝojo eterna estos super ilia kapo; ĝojon kaj gajecon ili atingos, kaj forflugos afliktoj kaj ĝemado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'Tio estis en la dek-kvara jaro de la reĝo Ĥizkija, eliris Sanĥerib, reĝo de Asirio, kontraŭ ĉiujn fortikigitajn urbojn de Judujo, kaj venkoprenis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Kaj la reĝo de Asirio sendis Rabŝaken el Laĥiŝ en Jerusalemon al la reĝo Ĥizkija kun granda militistaro; kaj li stariĝis ĉe la akvotubo de la supra lageto, ĉe la vojo de la kampo de fulistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Kaj eliris al li Eljakim, filo de Ĥilkija, la palacestro, kaj Ŝebna, la skribisto, kaj Joaĥ, filo de Asaf, la kronikisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Kaj Rabŝake diris al ili: Diru al Ĥizkija: Tiele diras la granda reĝo, la reĝo de Asirio: Kio estas la fido, kiun vi fidas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Mi opinias, ke tio estas nur buŝa babilado; por milito oni bezonas konsilon kaj forton. Nun kiun vi fidas, ke vi ribelis kontraŭ mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Jen vi fidas la apogon de Egiptujo, tiu kano rompita, kiu, se iu sin apogas sur ĝi, eniras en lian manon kaj trapikas ĝin. Tia estas Faraono, reĝo de Egiptujo, por ĉiuj, kiuj fidas lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Eble vi diros al mi: La Eternulon, nian Dion, ni fidas? Sed Li estas ja Tiu, kies altaĵojn kaj altarojn Ĥizkija forigis, dirante al Judujo kaj Jerusalem: Antaŭ ĉi tiu altaro adorkliniĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Nun provu konkuri kun mia sinjoro, la reĝo de Asirio; mi donos al vi du mil ĉevalojn-ĉu vi povas trovi rajdantojn por ili?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Kiel vi povas forigi estron, unu el la plej malgrandaj servantoj de mia sinjoro, kaj fidi Egiptujon pro la ĉaroj kaj rajdistoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Cetere, ĉu sen la volo de la Eternulo mi iris kontraŭ ĉi tiun landon, por ruinigi ĝin? La Eternulo diris al mi: Iru kontraŭ ĉi tiun landon kaj ruinigu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Tiam Eljakim kaj Ŝebna kaj Joaĥ diris al Rabŝake: Volu paroli al viaj sklavoj en la lingvo Siria, ĉar ni komprenas; sed ne parolu al ni Jude antaŭ la oreloj de la popolo, kiu estas sur la murego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Sed Rabŝake diris: Ĉu al via sinjoro kaj al vi sendis min mia sinjoro, por diri tiujn vortojn? ĉu ne al la homoj, kiuj sidas sur la murego, por manĝi sian ekskrementon kaj trinki sian urinon kune kun vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Kaj Rabŝxake stariĝis, kaj ekkriis per laŭta voĉo Jude, dirante: Aŭskultu la vortojn de la granda reĝo, la reĝo de Asirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'Tiele diras la reĝo: Ĥizkija ne forlogu vin; ĉar li ne povos savi vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'Kaj Ĥizkija ne fidigu vin per la Eternulo, dirante: La Eternulo certe nin savos, ĉi tiu urbo ne estos transdonita en la manojn de la reĝo de Asirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Ne aŭskultu Ĥizkijan; ĉar tiele diras la reĝo de Asirio: Faru kun mi pacon kaj eliru al mi, kaj manĝu ĉiu el sia vinberĝardeno kaj ĉiu de sia figarbo kaj trinku ĉiu la akvon de sia puto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'ĝis mi venos kaj prenos vin en landon similan al via lando, en landon de greno kaj mosto, en landon de pano kaj vinberĝardenoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Ĥizkija ne forlogu vin per la vortoj: La Eternulo nin savos. Ĉu la dioj de la nacioj savis ĉiu sian landon el la manoj de la reĝo de Asirio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Kie estas la dioj de Ĥamat kaj Arpad? kie estas la dioj de Sefarvaim? kaj ĉu ili savis Samarion el miaj manoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Kiu el ĉiuj dioj de tiuj landoj savis sian landon el miaj manoj, ke la Eternulo savu Jerusalemon el miaj manoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Kaj ili silentis kaj nenion respondis al li; ĉar estis ordono de la reĝo: Ne respondu al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Kaj Eljakim, filo de Ĥilkija, la palacestro, kaj Ŝebna, la skribisto, kaj Joaĥ, filo de Asaf, la kronikisto, venis al Ĥizkija en disŝiritaj vestoj, kaj raportis al li la vortojn de Rabŝake.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'Kiam la reĝo Ĥizkija tion aŭdis, li disŝiris siajn vestojn kaj ĉirkaŭkovris sin per sako, kaj iris en la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'Kaj li sendis Eljakimon, la palacestron, kaj Ŝebnan, la skribiston, kaj la plejaĝulojn de la pastroj, ĉirkaŭkovritajn per sakoj, al la profeto Jesaja, filo de Amoc.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'Kaj ili diris al li: Tiele diras Ĥizkija: Ĉi tiu tago estas tago de malfeliĉo, de puno, kaj de malhonoro; ĉar infanoj atingis la aperturon de la utero, sed forestas forto por naski.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Eble aŭdos la Eternulo, via Dio, la vortojn de Rabŝake, kiun sendis la reĝo de Asirio, lia sinjoro, por blasfemi la vivantan Dion, kaj insulti per la vortoj, kiujn aŭdis la Eternulo, via Dio. Levu do preĝon por la restintoj, kiuj ankoraŭ ekzistas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Kaj la servantoj de la reĝo Ĥizkija venis al Jesaja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'Kaj Jesaja diris al ili: Tiele parolu al via sinjoro: Tiele diras la Eternulo: Ne timu la vortojn, kiujn vi aŭdis kaj per kiuj blasfemis Min la servantoj de la reĝo de Asirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Jen Mi metos en lin spiriton, ke, aŭdinte sciigon, li reiros en sian landon; kaj Mi faligos lin per glavo en lia lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Kaj Rabŝake revenis, kaj trovis la reĝon de Asirio militanta kontraŭ Libna; ĉar li aŭdis, ke li foriris de Laĥiŝ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Kaj venis sciigo pri Tirhaka, reĝo de Etiopujo, nome: Li eliris, por militi kontraŭ vi. Kiam li tion aŭdis, li sendis senditojn al Ĥizkija kun la sekvanta komisio:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'Tiele diru al Ĥizkija, reĝo de Judujo: Ne forlogu vin via Dio, kiun vi fidas, dirante: Jerusalem ne estos transdonita en la manojn de la reĝo de Asirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Vi aŭdis ja, kion faris la reĝoj de Asirio al ĉiuj landoj, ruiniginte ilin; ĉu vi do saviĝos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Ĉu ilin savis la dioj de la nacioj, kiujn ekstermis miaj patroj, la naciojn de Gozan kaj Ĥaran kaj Recef kaj la filojn de Eden en Telasar?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Kie estas la reĝo de Ĥamat kaj la reĝo de Arpad kaj la reĝo de la urbo Sefarvaim, de Hena kaj Iva?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Ĥizkija prenis la leteron el la manoj de la senditoj kaj legis ĝin, kaj li iris en la domon de la Eternulo, kaj Ĥizkija disvolvis ĝin antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Kaj Ĥizkija ekpreĝis al la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'Ho Eternulo Cebaot, Dio de Izrael, sidanta sur la keruboj! Vi estas la sola Dio super ĉiuj regnoj de la tero, Vi kreis la ĉielon kaj la teron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'klinu, ho Eternulo, Vian orelon, kaj aŭskultu; malfermu, ho Eternulo, Viajn okulojn, kaj rigardu; kaj aŭdu ĉiujn vortojn de Sanĥerib, kiujn li sendis, por insulti la Dion vivantan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Estas vero, ho Eternulo, la reĝoj de Asirio ruinigis ĉiujn regnojn kaj ilian teron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'kaj ĵetis iliajn diojn en fajron; ĉar tio estis ne dioj, sed faritaĵoj de homaj manoj, ligno kaj ŝtono, ili ekstermis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Sed nun, ho Eternulo, nia Dio, savu nin kontraŭ liaj manoj, por ke ĉiuj regnoj de la tero eksciu, ke Vi, ho Eternulo, estas sola.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Kaj Jesaja, filo de Amoc, sendis al Ĥizkija, por diri: Tiele diras la Eternulo, Dio de Izrael: Koncerne tion, kion vi preĝis al Mi pri Sanĥerib, reĝo de Asirio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'jen estas tio, kion diris pri li la Eternulo: Malestimas vin, mokas vin la virga filino de Cion, balancas post vi la kapon la filino de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Kiun vi blasfemis kaj insultis? kaj kontraŭ kiun vi laŭtigis voĉon kaj alte levis viajn okulojn? Kontraŭ la Sanktulon de Izrael!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Per viaj servantoj vi blasfemis la Sinjoron, kaj vi diris: Kun mia multo da ĉaroj mi supreniris sur la supron de montoj, sur la randon de Lebanon, kaj mi dehakis ĝiajn altajn cedrojn, ĝiajn plej bonajn cipresojn, kaj mi atingis ĝian plej altan pinton, ĝian ĝardensimilan arbaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Mi fosis kaj trinkis akvon, kaj mi sekigos per la plandoj de miaj piedoj ĉiujn riverojn de Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Ĉu vi ne aŭdis, ke Mi jam de longe tion decidis, de tempo antikva tion destinis? nun Mi tion plenumis, ke la fortikigitaj urboj fariĝis amaso da ruinŝtonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'Kaj iliaj loĝantoj senfortigitaj ektremis kaj kovriĝis per honto; ili fariĝis kiel herbo de kampo, kiel malgrava verdaĵo, kiel musko sur tegmentoj, kaj kiel sunbruligita greno antaŭ la spikiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Sed vian sidon kaj vian eliron kaj vian venon Mi scias, ankaŭ vian koleron kontraŭ Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Pro tio, ke vi koleris kontraŭ Mi kaj via aroganteco venis al Miaj oreloj, Mi metos Mian ringon en viajn nazotruojn kaj Mian buŝbridaĵon en vian buŝon, kaj Mi reirigos vin per la sama vojo, per kiu vi venis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'Kaj jen estas por vi la pruvosigno: vi manĝos en ĉi tiu jaro grenon memsemiĝintan, en la dua jaro grenon sovaĝan, sed en la tria jaro vi semos kaj rikoltos kaj plantos vinberĝardenojn kaj manĝos iliajn fruktojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Kaj la restaĵo de la domo de Jehuda denove enradikiĝos malsupre kaj donos fruktojn supre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Ĉar el Jerusalem devenos restaĵo, kaj savitaĵo de la monto Cion; la fervoro de la Eternulo Cebaot tion faros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Tial tiele diras la Eternulo pri la reĝo de Asirio: Li ne eniros en ĉi tiun urbon kaj ne ĵetos tien sagon kaj ne aliros al ĝi kun ŝildo kaj ne ŝutos kontraŭ ĝi remparon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Per la sama vojo, per kiu li venis, li reiros, kaj en ĉi tiun urbon li ne eniros, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Mi defendos ĉi tiun urbon, por savi ĝin pro Mi kaj pro Mia servanto David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Kaj eliris anĝelo de la Eternulo kaj frapis en la tendaro de la Asirianoj cent okdek kvin mil. Kiam oni leviĝis matene, oni ekvidis, ke ili ĉiuj estas kadavroj senvivaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Kaj Sanĥerib, la reĝo de Asirio, elmoviĝis kaj iris kaj rehejmiĝis kaj restis en Nineve.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'Kaj kiam li adorkliniĝis en la domo de sia dio Nisroĥ, liaj filoj Adrameleĥ kaj Ŝarecer mortigis lin per glavo, kaj mem ili forkuris en la landon Araratan. Kaj ekreĝis anstataŭ li lia filo Esar-Ĥadon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'En tiu tempo Ĥizkija morte malsaniĝis; kaj venis al li la profeto Jesaja, filo de Amoc, kaj diris al li: Tiele diras la Eternulo: Faru testamenton pri via domo, ĉar vi mortos kaj ne vivos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Tiam Ĥizkija turnis sian vizaĝon al la muro, kaj ekpreĝis al la Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'kaj diris: Mi petas, ho Eternulo, rememoru, ke mi iradis antaŭ Vi kun vero kaj koro fidela, kaj mi faradis tion, kio plaĉas al Vi. Kaj Ĥizkija laŭte ekploris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Tiam aperis la vorto de la Eternulo al Jesaja jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Iru, kaj diru al Ĥizkija: Tiele diras la Eternulo, Dio de via patro David: Mi aŭdis vian preĝon, Mi vidis viajn larmojn; jen Mi aldonos al via vivo dek kvin jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'Kaj kontraŭ la mano de la reĝo de Asirio Mi savos vin kaj ĉi tiun urbon, kaj Mi defendos ĉi tiun urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'Kaj jen estas por vi la pruvosigno de la Eternulo, ke la Eternulo plenumos tion, kion Li diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'jen la hormontran ombron, kiu malsupriĝis sur la suna hormontrilo de Aĥaz, Mi retiros malantaŭen je dek gradoj. Kaj la suno retiriĝis je dek gradoj laŭ la gradaro, laŭ kiu ĝi malsupriĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Jen estas la skribo de Ĥizkija, reĝo de Judujo, kiam li malsaniĝis kaj eliris viva el sia malsano:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, 'Mi pensis, ke en la mezo de mia vivo mi malsupreniros en la pordegon de Ŝeol, Ke mi estos senigita je la resto de miaj jaroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Mi pensis, ke mi ne plu vidos Dion, la Eternulon, sur la tero de la vivantoj, Ke mi ne plu rigardos homon inter la loĝantoj de la vantejo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Ke mia estado demoviĝas, kaj forportiĝas de mi kiel tendo de paŝtisto; Ke mi finteksis mian vivon kiel teksisto, kaj Li detranĉos min de la teksbazo; Ke antaŭ ol la tago cedos al la nokto, Vi faros al mi finon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Mi atendis ĝis mateno, ke simile al leono Li frakasos ĉiujn miajn ostojn, Ke antaŭ ol la tago cedos al la nokto, Vi faros al mi finon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Kiel hirundo plendanta mi plorpepis, mi ĝemis kiel kolombo; Miaj okuloj estis direktitaj malsupren: Ho Eternulo, mi suferas, protektu min!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Kion mi diru? Li promesis ja al mi, kaj Li faris. Nun mi pasigos ĉiujn miajn jarojn, memorante la premitecon de mia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Ho Sinjoro, per tio vivas la homoj, Kaj en ĉio ĉi tio estas la vivo de mia spirito: Vi resanigis min, kaj konservis al mi la vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Jen en bonon aliformiĝis mia sufero; Vi ame eltiris mian animon el pereo, Ĉar Vi ĵetis malantaŭ Vin ĉiujn miajn pekojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Ĉar ne Ŝeol Vin gloros, ne la morto Vin laŭdos; La irantaj en la terinternon ne esperos Vian verecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'La vivanto, nur la vivanto Vin gloros, kiel mi hodiaŭ; Patro al la filoj konigos Vian verecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'La Eternulo min helpas; Kaj miajn kantojn ni kantados Dum nia tuta vivo en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Kaj Jesaja diris: Oni alportu dispremitan figon kaj metu sur la ŝvelaĵon, kaj li estos sanigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Kaj Ĥizkija diris: Kia estas la signo, ke mi iros en la domon de la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'En tiu tempo Merodaĥ-Baladan, filo de Baladan, reĝo de Babel, sendis leteron kaj donacojn al Ĥizkija; ĉar li aŭdis, ke li estis malsana kaj resaniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Kaj Ĥizkija ĝojis pri ili, kaj montris al ili sian trezorejon, la arĝenton kaj la oron kaj la aromaĵojn kaj la karan oleon kaj sian tutan armilejon, kaj ĉion, kio troviĝis en liaj trezorejoj; estis nenio, kion Ĥizkija ne montrus al ili en sia domo kaj en sia tuta posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Kaj venis la profeto Jesaja al la reĝo Ĥizkija, kaj diris al li: Kion parolis tiuj homoj? kaj de kie ili venis al vi? Kaj Ĥizkija diris: El lando malproksima ili venis al mi, el Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Kaj li diris: Kion ili vidis en via domo? Kaj Ĥizkija respondis: Ĉion, kio estas en mia domo, ili vidis; estis nenio, kion mi ne montrus al ili en miaj trezorejoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Tiam Jesaja diris al Ĥizkija: Aŭskultu la diron de la Eternulo Cebaot:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Jen venos tagoj, kaj ĉio, kio estas en via domo kaj kion kolektis viaj patroj ĝis la nuna tago, estos forportata en Babelon; nenio restos, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'Kaj el viaj filoj, kiuj devenos de vi, kiujn vi naskigos, oni prenos; kaj ili estos korteganoj en la palaco de la reĝo de Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Kaj Ĥizkija diris al Jesaja: Bona estas la vorto de la Eternulo, kiun vi diris. Kaj li diris plue: Estu nur paco kaj vero en mia tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Konsolu, konsolu Mian popolon, diras via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Parolu al la koro de Jerusalem, kaj voku al ĝi, ke finiĝis la tempo de ĝia batalado, ke pardonita estas ĝia kulpo, ke ĝi ricevis el la mano de la Eternulo duoble pro ĉiuj siaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Sonas voĉo de krianto: Pretigu en la dezerto la vojon de la Eternulo, rektigu en la stepo irejon por nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Ĉiu valo leviĝu, kaj ĉiu monto kaj monteto malaltiĝu, kaj la malebenaĵo fariĝu ebenaĵo, kaj la montaro fariĝu valo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'Kaj aperos la majesto de la Eternulo; kaj ĉiu karno kune vidos, ke la buŝo de la Eternulo parolis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Voĉo diras: Proklamu! sed li diras: Kion mi proklamu? Ĉiu karno estas herbo, kaj ĉiu ĝia ĉarmo estas kiel kampa floreto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'Sekiĝas herbo, velkas floreto, kiam la spiro de la Eternulo blovetas sur ĝin; vere, la popolo estas herbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Sekiĝas herbo, velkas floreto; sed la vorto de nia Dio restas eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Sur altan monton supreniru, ho predikantino de Cion; laŭtigu potence vian voĉon, ho predikantino de Jerusalem, laŭtigu, ne timu; diru al la urboj de Judujo: Jen estas via Dio!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Jen la Sinjoro, la Eternulo, venas kun potenco, kaj Lia brako regas; jen Lia rekompenco estas kun Li, kaj Lia repago antaŭ Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Kiel paŝtisto Li paŝtos Sian ŝafaron, per Sia brako Li kolektos la ŝafidojn kaj portos ilin sur Sia brusto; la suĉigantinojn Li kondukos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Kiu mezuris per sia mankavo la akvon kaj difinis la ĉielon per la manlarĝo kaj metis en mezurilon la polvon de la tero kaj pesis per pesilo la montojn kaj la montetojn per pesiltaso?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Kiu gvidis la spiriton de la Eternulo, kaj kiu donis al Li sian konsilon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'De kiu Li petis konsilon, ke tiu komprenigu Lin kaj instruu Lin pri la vojo de justeco kaj instruu al Li scion kaj konigu al Li la vojon de saĝeco?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Jen la popoloj estas kiel guto el sitelo kaj kalkulataj kiel polvero sur pesiltaso; jen Li disŝutas la insulojn, kiel polveretojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Lebanon ne sufiĉus por fajro, kaj ĝia bestaro ne sufiĉus por bruloferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Ĉiuj nacioj estas antaŭ Li kiel nenio, estas rigardataj de Li kiel nulo kaj senvaloraĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Kun kiu vi komparos Dion? kaj kian similaĵon vi kontraŭstarigos al Li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Ĉu idolon, kiun fandis artisto kaj kiun oraĵisto kovras per oro kaj ornamas per arĝentaj ĉenoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'Kiu estas tro malriĉa por la oferdono, tiu elektas lignon ne putrantan, serĉas kompetentan skulptiston, por fari idolon fortikan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Ĉu vi ne scias? ĉu vi ne aŭdis? ĉu ne estis dirite al vi antaŭlonge? ĉu vi ne komprenas detempe de la fondado de la tero?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Li sidas super la rondo de la tero, kaj ĝiaj loĝantoj estas kiel lokustoj; Li etendas la ĉielon kiel maldikan teksaĵon kaj distiras ĝin kiel tendon por loĝado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'Li faras la princojn neniaĵo, la juĝistojn de la tero Li faras neekzistaĵo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'kvazaŭ ili ne estus plantitaj, kvazaŭ ili ne estus semitaj, kvazaŭ ilia trunko ne havus radikon en la tero: apenaŭ Li blovetis sur ilin, ili velkis, kaj la ventego forportas ilin kiel pajlerojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'Kaj al kiu do vi volas egaligi Min, ke Mi estu simila al li? diras la Sanktulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Levu alten viajn okulojn, kaj rigardu, kiu kreis tion? Li, kiu elkondukas iliajn taĉmentojn laŭ kalkulo, kiu ilin ĉiujn vokas laŭ la nomo; antaŭ la Plejpotenculo kaj Plejfortulo neniu kaŝiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Kial vi parolas, ho Jakob, kaj diras, ho Izrael: Mia vojo estas kaŝita antaŭ la Eternulo, kaj mia afero ne atingas Dion?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Ĉu vi ne scias, ĉu vi ne aŭdis, ke la Eternulo estas Dio eterna, la Kreinto de la finoj de la tero? Li ne laciĝas kaj ne senfortiĝas; Lia saĝeco estas neesplorebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Li donas forton al la laculo, kaj al la senfortulo Li plifortigas la povon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Knaboj senfortiĝas kaj laciĝas, junuloj ofte falas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'sed tiuj, kiuj fidas la Eternulon, ricevas novan forton, ili levas la flugilojn kiel agloj, ili kuras kaj ne laciĝas, ili iras kaj ne senfortiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Silentu antaŭ Mi, ho insuloj, kaj la popoloj refortiĝu; ili alproksimiĝu kaj parolu; ni kune iru al juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Kiu vekis el la oriento la justulon, vokis lin, ke li iru? Li transdonis al li naciojn kaj detronigis reĝojn, transdonis kiel polvon al lia glavo, kiel disflugantajn pajlerojn al lia pafarko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Li persekutas ilin, transiras en paco la vojon, sur kiu liaj piedoj ne haltas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Kiu tion faris kaj estigis? kiu vokis la generaciojn de la komenco? Mi, la Eternulo, la unua, kaj kun la lastaj Mi estas la sama.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Vidis tion la insuloj kaj ektimis; la finoj de la tero ektremis; ili alproksimiĝis kaj alvenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Ĉiu helpas sian proksimulon, kaj diras al sia frato: Estu kuraĝa!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Kaj la skulptisto kuraĝigas la fandiston, la ladfaristo la forĝiston, kaj li diras: La kuniĝo estas bona; kaj li fortikigas tion per najloj, ke ĝi ne ŝanceliĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Sed vi, ho Mia servanto Izrael, ho Jakob, kiun Mi elektis, ho idaro de Abraham, Mia amato,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'vi, kiun Mi prenis de la finoj de la tero kaj vokis de ĝiaj randoj, kaj al kiu Mi diris: Vi estas Mia servanto, Mi vin elektis kaj ne forpuŝis-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'ne timu, ĉar Mi estas kun vi; ne maltrankviliĝu, ĉar Mi estas via Dio; Mi vin fortigos, Mi vin helpos, Mi vin subtenos per Mia justa dekstra mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Jen hontiĝos kaj malhonoriĝos ĉiuj, kiuj koleras kontraŭ vi; viaj kontraŭuloj fariĝos neniaĵo kaj pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Vi serĉos ilin, sed vi ilin ne trovos, la homojn, kiuj kverelas kontraŭ vi; la homoj, kiuj batalas kontraŭ vi, fariĝos neniaĵo kaj neekzistaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Ĉar Mi, la Eternulo, via Dio, fortigas vian dekstran manon, dirante al vi: Ne timu, Mi vin helpos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Ne timu, vermo Jakob, malmultulo Izrael! Mi vin helpos, diras la Eternulo; kaj via Liberiganto estas la Sanktulo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Jen Mi faros vin draŝilo akra, nova, dentohava; vi draŝos montojn kaj disfrotos, kaj montetojn vi faros kiel grenventumaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Vi disĵetos ilin, kaj la vento ilin disportos, kaj la ventego ilin disblovos; sed vi ĝojos en la Eternulo, vi havos gloron en la Sanktulo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'La malriĉuloj kaj senhavuloj serĉas akvon, sed ĝi ne troviĝas; ilia lango sekiĝas de soifo. Mi, la Eternulo, aŭskultos ilin; Mi, la Dio de Izrael, ne forlasos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Sur nudaj montetoj Mi malfermos riverojn kaj meze de valoj fontojn, dezerton Mi faros lago da akvo kaj sensukan teron fontoj de akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'En dezerto Mi aperigos cedron, akacion, mirton, kaj olivarbon; Mi starigos en stepo cipreson, abion, kaj bukson kune;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'por ke ĉiuj vidu kaj eksciu kaj rimarku kaj komprenu, ke la mano de la Eternulo tion faris kaj la Sanktulo de Izrael tion kreis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Prezentu vian juĝaferon, diras la Eternulo; antaŭmetu viajn argumentojn, diras la Reĝo de Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Ili alvenu, kaj diru al ni, kio fariĝos; diru al ni, kion signifas tio, kio estis en la komenco, tiam ni pripensos kaj ekscios la finon; aŭ sciigu al ni tion, kio estos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Diru al ni tion, kio venos poste, por ke ni eksciu, ke vi estas dioj; ĉu vi faros bonon, ĉu malbonon, ni miros kaj vidos kune.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Sed jen vi estas neniaĵo, kaj via agado estas neniaĵo; abomenindaĵon oni elektas en vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Iun Mi vekis el nordo, kaj li venis; de la leviĝejo de la suno li proklamas Mian nomon; li paŝas sur potenculoj kiel sur koto, kaj kiel potfaristo piedpremas argilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Kiu tion diris antaŭe, por ke ni sciu? kaj antaŭlonge, por ke ni diru: Li estas prava? Sed neniu diris, kaj neniu sciigis, kaj neniu aŭdis viajn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Mi la unua diris al Cion: Jen ili estas; kaj al Jerusalem Mi donis sciiganton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Mi rigardis, kaj neniu estis; inter ili estis neniu konsilanto, ke Mi povu demandi kaj ili respondu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Jen ili ĉiuj estas vantaĵo, neniaĵo estas ilia faro, vento kaj senenhavaĵo estas iliaj fanditaj idoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Jen estas Mia servanto, kiun Mi apogas, Mia elektito, kiun favoras Mia animo. Mi metis Mian spiriton sur lin; li disportos justecon al la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Li ne krios nek bruos, kaj ne aŭdigos sur la stratoj sian voĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Kanon rompetitan li ne rompos, kaj meĉon senfajriĝantan li ne estingos. Laŭ la vero li faros juĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Li ne laciĝos nek fleksiĝos, ĝis li starigos sur la tero justecon; kaj lian instruon atendas la insuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Tiele diras Dio, la Eternulo, kiu kreis la ĉielon kaj etendis ĝin, kiu disvastigis la teron kaj ĝiajn produktojn, kiu donis animon sur ĝiaj loĝantoj, kaj spiriton al tiuj, kiuj iras sur ĝi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Mi, la Eternulo, alvokis vin por la vero, kaj Mi prenos vin je la mano kaj gardos vin, kaj faros vin interligo por la popolo, lumo por la nacioj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'por malfermi okulojn blindajn, por elkonduki el malliberejo malliberulojn, el domo ŝlosita sidantajn en mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Mi estas la Eternulo, tia estas Mia nomo; kaj Mian honoron Mi ne donos al alia, nek Mian gloron al idoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Kio antaŭlonge estis profetita, jen ĝi plenumiĝis, kaj novajn aferojn Mi anoncas; antaŭ ol ili elkreskos, Mi anoncos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Kantu al la Eternulo kanton novan, Lian gloron de la rando de la tero, vi, kiuj ŝipveturas sur la maro, kaj ĉio, kio ĝin plenigas, insuloj kaj iliaj loĝantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Laŭtigu vian voĉon, ho dezerto kaj ĝiaj urboj, la vilaĝoj, en kiuj loĝas Kedar; ĝojkriu la loĝantoj de Sela, de la supro de montoj ili voku.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Ili donu honoron al la Eternulo, kaj Lian gloron ili proklamu sur la insuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'La Eternulo eliros kiel heroo, kiel homo de milito Li vekos fervoron, Li vokos kaj aŭdigos militan krion, Li montros Sian potencon sur Siaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Longe Mi silentis, estis kvieta, kaj detenis Min; nun Mi krios kiel naskantino, Mi neniigos kaj englutos ĉion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Mi dezertigos montojn kaj montetojn, kaj ilian tutan verdaĵon Mi elsekigos; Mi faros la riverojn insuloj, kaj la lagojn Mi elsekigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'Mi kondukos la blindulojn laŭ vojo, kiun ili ne konas, laŭ irejoj por ili ne konataj Mi irigos ilin; la mallumon antaŭ ili Mi faros lumo, kaj la vojojn kurbajn rektaj. Tiajn aferojn Mi faros por ili, kaj Mi ilin ne forlasos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Retiros sin malantaŭen, kovriĝos per honto tiuj, kiuj fidas idolojn, kaj kiuj diras al fanditaĵoj: Vi estas niaj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Aŭskultu, ho surduloj; kaj vi, blinduloj, rigardu, por ke vi vidu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Sed kiu estas tiel blinda, kiel Mia servanto, kaj surda, kiel la sendato, kiun Mi sendas? kiu estas tiel blinda, kiel Mia elaĉetito, kaj blinda, kiel la servanto de la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Vi vidis multe, sed vi ne konservis; viaj oreloj estas malfermitaj, sed ne aŭdas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'La Eternulo deziris pro Sia justeco, ke Li faru la leĝon granda kaj glora.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Sed tio estas popolo prirabita kaj senhavigita; ili ĉiuj estas ligitaj en kavernoj kaj kaŝitaj en malliberejoj; ili fariĝis rabakiro, kaj neniu ilin savas, kaptitaĵo, kaj neniu diras: Redonu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Kiu el vi atentos ĉi tion, komprenos kaj aŭskultos por la tempo estonta?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Kiu fordonis Jakobon por ruinigo kaj Izraelon al la rabistoj? ĉu ne la Eternulo, kontraŭ kiu ni pekis, ne volis iri laŭ Liaj vojoj kaj ne aŭskultis Lian instruon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'Kaj Li elverŝis sur lin la ardon de Sia kolero kaj la potencon de la milito; kaj Li faris brulon ĉirkaŭe de li, sed li ne komprenis; Li ĵetis flamojn sur lin, sed li ne prenis tion al sia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Sed nun tiele diras la Eternulo, kiu vin kreis, ho Jakob, kaj kiu vin estigis, ho Izrael: Ne timu, ĉar Mi vin savos; Mi vokos vin laŭ via nomo, vi estas Mia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Kiam vi transiros akvon, Mi estos kun vi, kaj trans riverojn, ili vin ne dronigos; kiam vi iros en fajron, vi ne brulvundiĝos, kaj flamo vin ne bruligos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Ĉar Mi estas la Eternulo, via Dio, la Sanktulo de Izrael, via Savanto; Egiptujon Mi donos kiel vian elaĉeton, Etiopujon kaj Seban anstataŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Ĉar vi estas kara en Miaj okuloj, vi estis honorita kaj Mi vin amas; tial Mi fordonos aliajn homojn anstataŭ vi kaj gentojn anstataŭ via animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Ne timu, ĉar Mi estas kun vi; de la oriento Mi venigos vian idaron, kaj de la okcidento Mi vin kolektos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Mi diros al la nordo: Redonu! kaj al la sudo: Ne retenu! venigu Miajn filojn de malproksime kaj Miajn filinojn de la randoj de la tero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'ĉiun, kiu estas nomata per Mia nomo kaj kiun Mi kreis por Mia gloro, faris, kaj estigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Elirigu la popolon blindan, kiu tamen havas okulojn, kaj la surdulojn, kiuj tamen havas orelojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Ĉiuj nacioj kolektiĝu kune, kaj la popoloj kunvenu; kiu el ili tion antaŭdirus aŭ anoncus al ni antaŭlonge? ili starigu siajn atestantojn kaj pravigu sin, por ke oni aŭdu, kaj diru: Estas vero!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Vi estas Miaj atestantoj, diras la Eternulo, kaj Mia servanto, kiun Mi elektis; por ke vi sciu kaj kredu al Mi, kaj komprenu, ke tio estas Mi; antaŭ Mi estis kreita nenia Dio, kaj post Mi ne ekzistos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Mi, Mi estas la Eternulo; kaj krom Mi ekzistas nenia savanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Mi promesis kaj savis kaj anoncis; kaj ne estis inter vi iu fremda; kaj vi estas Miaj atestantoj, diras la Eternulo, kaj Mi estas Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'De la komenco de la tempo Mi estas la sama, kaj neniu povas savi kontraŭ Mia mano; kiam Mi faras, kiu tion ŝanĝos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'Tiele diras la Eternulo, via Liberiganto, la Sanktulo de Izrael: Pro vi Mi sendis en Babelon kaj pelis malsupren ĉiujn forkurantojn, kaj la ĝojadon de la Ĥaldeoj Mi aliformigis en ploradon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Mi estas la Eternulo, via Sanktulo, la Kreinto de Izrael, via Reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'Tiele diras la Eternulo, kiu faris vojon sur la maro kaj vojeton sur potenca akvo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'kiu elirigis ĉarojn kaj ĉevalojn, militistaron kaj potencon, kiuj ĉiuj kune falis kaj ne leviĝos, senfajriĝis, estingiĝis kiel meĉo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Ne rememoru tion, kio estis antaŭlonge, kaj ne meditu pri tio, kio estis en la tempo antikva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Jen Mi faras ion novan, nun ĝi elkreskas; ĉu vi tion ne komprenas? Mi faros vojon en la dezerto, riverojn en senakva lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Gloros Min la bestoj de la kampo, ŝakaloj kaj strutoj; ĉar Mi donis akvon en la dezerto, riverojn en senakva lando, por trinkigi la popolon, kiun Mi elektis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'tiun popolon, kiun Mi kreis por Mi, por ke ĝi rakontu pri Mia gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Sed ne Min vi vokis, ho Jakob, kaj ne por Mi vi laboris, ho Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Vi ne alportadis al Mi viajn ŝafidojn de brulofero kaj ne honoradis Min per viaj buĉoferoj; Mi ne servigis vin per farunoferoj kaj ne lacigis vin per olibano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Vi ne aĉetis por Mi per mono bonodoran kanon kaj ne satigis Min per la sebo de viaj buĉoferoj; vi nur laborŝarĝis Min per viaj pekoj, lacigis Min per viaj malbonagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Mi, Mi forviŝas viajn krimojn pro Mi mem, kaj viajn pekojn Mi ne rememoros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Rememorigu al Mi, kaj ni faru juĝon inter ni; rakontu vi, por ke vi vin pravigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Via prapatro pekis, kaj viaj profetoj defalis de Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'Tial Mi sensanktigis la estrojn de la sanktejo, kaj Mi elmetis Jakobon al anatemo kaj Izraelon al malhonoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Sed nun aŭskultu, ho Jakob, Mia servanto, kaj Izrael, kiun Mi elektis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'Tiele diras la Eternulo, kiun vin kreis kaj formis kaj helpas vin de post via naskiĝo: Ne timu, ho Jakob, Mia servanto, kaj vi, ho Jeŝurun, kiun Mi elektis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Ĉar Mi verŝos akvon sur la soifantaĵon kaj torentojn sur la sekan teron; Mi verŝos Mian spiriton sur vian idaron kaj Mian benon sur viajn devenontojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'por ke ili kresku inter herbo, kiel salikoj super torentoj da akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Unu diros: Mi apartenas al la Eternulo; alia nomos sin per la nomo de Jakob; alia skribe konsekros sin al la Eternulo kaj prenos al si la alnomon Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Tiele diras la Eternulo, la Reĝo de Izrael, kaj lia Liberiganto, la Eternulo Cebaot: Mi estas la unua, kaj Mi estas la lasta, kaj ne ekzistas Dio krom Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Kaj kiu estas simila al Mi? li diru kaj anoncu, kaj elmetu antaŭ Mi ĉion, kio estis de post la tempo, kiam Mi kreis la popolon eternan; ili anoncu tion, kio estos kaj kio venos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Ne timu kaj ne maltrankviliĝu; Mi aŭdigis ja al vi kaj antaŭdiris antaŭlonge; kaj vi estas Miaj atestantoj. Ĉu ekzistas Dio krom Mi? ne ekzistas Roko, Mi iun ne konas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Ĉiuj, kiuj faras idolojn, estas vantaĵo, kaj iliaj amataĵoj estas senutilaj, kaj ili mem estas atestantoj; ili ne vidas kaj ne komprenas, tial ili estos hontigataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Kiu faris dion, kaj fandis idolon, kiu nenion utilas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Ĉiuj partoprenintoj estos hontigataj, ĉar la majstroj estas ja el homoj; ili ĉiuj kolektiĝu kaj stariĝu, ili ektimos, kaj ĉiuj kune estos hontigataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Unu tranĉas la feron per ĉizilo, laboras per karboj, formas ĝin per marteloj, kaj prilaboras ĝin per la forto de sia brako; li eĉ malsatas kaj perdas la fortojn, ne trinkas akvon kaj laciĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Alia hakas lignon, mezuras ĝin per ŝnuro, faras konturojn per grifelo, rabotas per rabotilo, ĉirkaŭsignas per cirkelo, kaj faras el ĝi bildon de homo, de bela homo, por ke ĝi loĝu en la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Li hakas por si cedrojn, prenas ilekson kaj kverkon, preparas al si provizon de arbaraj arboj, plantas pinon, kiun la pluvo kreskigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Kaj tio servas al la homo kiel hejtilo; li prenas el tio kaj varmigas sin, li ankaŭ faras fajron kaj bakas panon; el tio sama li faras dion kaj adorkliniĝas antaŭ ĝi, li faras el ĝi idolon kaj adoras ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Parton el ĝi li forbruligas en fajro, super parto li manĝas viandon, rostas rostaĵon, kaj satiĝas; li ankaŭ varmigas sin, kaj diras: Ha, ha, fariĝis al mi varme, mi eksentis fajron!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Kaj ĝian restaĵon li faris dio, li faris el ĝi sian idolon; li adoras ĝin, adorkliniĝas kaj preĝas al ĝi, kaj diras: Savu min, ĉar vi estas mia dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Ili ne scias kaj ne komprenas, ĉar gluitaj estas iliaj okuloj, por ke ili ne vidu, por ke ilia koro ne komprenu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'Kaj li ne primeditas en sia koro, ne havas scion nek komprenon, por diri: Duonon de ĝi mi forbruligis en fajro, mi ankaŭ bakis sur ĝiaj karboj panon, mi rostis viandon kaj manĝis; ĉu do el la restaĵo mi faros abomenindaĵon? ĉu ŝtipon da ligno mi adoros?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Li postkuras polvon, la trompita koro lin erarigas, kaj li ne savas sian animon, kaj ne diras: Ĉu ne malveraĵon mi havas en mia dekstra mano?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Memoru tion, ho Jakob, kaj Izrael, ĉar vi estas Mia servanto; Mi kreis vin Mia servanto; vi, ho Izrael, ne estos forgesita de Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Mi forviŝis viajn kulpojn kiel nubon, kaj viajn pekojn kiel nebulon; revenu al Mi, ĉar Mi savis vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Ĝojkriu, ho ĉielo, ĉar la Eternulo tion faris; voku, profundo de la tero; sonigu kanton, ho montoj, arbaro kaj ĉiuj arboj en ĝi; ĉar la Eternulo liberigis Jakobon, kaj faris Sin glora per Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Tiele diras la Eternulo, via Liberiginto, kiu formis vin de la momento de via naskiĝo: Mi estas la Eternulo, kiu ĉion faras, kiu sola etendis la ĉielon, per Sia propra potenco disvastigis la teron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'kiu neniigas la signojn de divenistoj kaj ridindigas la sorĉistojn, repuŝas la saĝulojn malantaŭen kaj malsaĝigas ilian scion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'kiu konfirmas la vorton de Sia servanto kaj plenumas la decidojn de Siaj senditoj; kiu diras pri Jerusalem: Ĝi havos multe da loĝantoj; kaj pri la urboj de Judujo: Ili estos rekonstruitaj, kaj iliajn ruinojn Mi restarigos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'kiu diras al la maro: Estu seka, kaj Mi sekigos viajn riverojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'kiu diras pri Ciro: Li estas Mia paŝtisto, kaj li plenumos ĉiujn Miajn dezirojn, dirante al Jerusalem: Estu rekonstruata, kaj la templo estu refondata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Tiele diras la Eternulo pri Sia sanktoleito Ciro: Mi prenis lin je lia dekstra mano, por faligi antaŭ li popolojn, kaj la lumbojn de reĝoj Mi senzonigos, por malfermi antaŭ li la pordojn, kaj por ke la pordegoj ne estu ŝlositaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Mi iros antaŭ vi kaj ebenigos altaĵojn; kuprajn pordojn Mi disbatos, kaj ferajn riglilojn Mi rompos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'Kaj Mi transdonos al vi trezorojn sekretajn kaj riĉaĵojn kaŝitajn, por ke vi eksciu, ke Mi, la Eternulo, vokis vin laŭ via nomo, Mi, Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Pro Mia servanto Jakob kaj pro Mia elektito Izrael Mi vokis vin laŭ via nomo, Mi altigis vin, kvankam vi Min ne konis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Mi estas la Eternulo, kaj ne ekzistas alia; ne ekzistas Dio krom Mi; Mi zonis vin, kvankam vi Min ne konis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'por ke oni eksciu oriente kaj okcidente, ke ne ekzistas krom Mi; Mi estas la Eternulo, kaj ne ekzistas alia,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'kiu faras lumon kaj kreas mallumon, faras pacon kaj estigas malbonon; Mi, la Eternulo, faras ĉion ĉi tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Gutigu, ho ĉielo, de supre, kaj la nuboj verŝu virton; malfermiĝu la tero kaj produktu savon, kaj virto kune elkresku. Mi, la Eternulo, tion kreis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Ve al tiu, kiu malpacas kun sia Kreinto! potpeco el la potpecoj de la tero! Ĉu diras argilo al sia potfaristo: Kion vi faras? via faritaĵo estas malforta?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Ve al tiu, kiu diras al la patro: Por kio vi naskigas? kaj al la patrino: Por kio vi turmentas vin per naskado?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Tiele diras la Eternulo, la Sanktulo de Izrael kaj lia Kreinto: Pri la estonteco demandu Min; la zorgon pri Miaj filoj kaj pri la faritaĵo de Miaj manoj lasu al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Mi faris la teron kaj kreis la homon sur ĝi; Mi per Miaj manoj etendis la ĉielon kaj aranĝis ĉiujn ĝiajn apartenaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Mi starigis lin por justeco, kaj ĉiujn liajn vojojn Mi ebenigos; li rekonstruos Mian urbon kaj forliberigos Miajn ekzilitojn, ne pro elaĉeto nek pro donacoj, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Tiele diras la Eternulo: La laborakiro de Egiptujo kaj la komercaĵo de Etiopujo kaj de Seba, de tiuj altkreskaj viroj, transiros al vi kaj estos viaj; ili iros post vi, en katenoj ili preteriros, kaj ili kliniĝos antaŭ vi, kaj preĝos al vi: Nur ĉe vi estas Dio, kaj ne ekzistas alia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Vere Vi estas Dio Sin kaŝanta, Dio de Izrael, Savanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Hontigataj kaj malhonorataj ili ĉiuj estas; kune kun ili iros en honto la farantoj de idoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Sed Izrael estas savita de la Eternulo per savo eterna; vi ne estos hontigataj nek malhonorataj ĝis eterneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Ĉar tiele diras la Eternulo; la kreinto de la ĉielo, Li estas Dio; la farinto kaj estiginto de la tero, Li ĝin aranĝis; Li kreis ĝin, ne por ke ĝi estu malplena; Li faris ĝin, por ke ĝi estu loĝata: Mi estas la Eternulo, kaj ne ekzistas alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Ne sekrete Mi parolis, sur malluma loko de la tero; Mi ne diris al la idaro de Jakob: Vane vi Min serĉas. Mi estas la Eternulo, kiu parolas justaĵon kaj anoncas veraĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Kolektiĝu kaj venu, alproksimiĝu kune, ĉiuj savitoj el la nacioj. Senprudentaj estas tiuj, kiuj portas siajn lignajn idolojn, kaj preĝas al dio, kiu ne povas helpi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Diru, eĉ interproksimiĝu kaj interkonsiliĝu: kiu anoncis tion en la antikva tempo, kaj diris tion antaŭlonge? ĉu ne Mi, la Eternulo? kaj ne ekzistas alia Dio krom Mi, la Dio vera kaj la helpanto; ekzistas neniu krom Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Turnu vin al Mi, ĉiuj finoj de la tero, kaj estu savitaj; ĉar Mi estas Dio, kaj ne ekzistas alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Mi ĵuris per Mi, el Mia buŝo eliris vero, vorto ne retirota, ke antaŭ Mi kliniĝos ĉiu genuo, ĵuros ĉiu lango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'Nur la Eternulo, oni diros pri Mi, havas veron kaj potencon; al Li venos kaj hontos ĉiuj, kiuj koleris kontraŭ Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'Per la Eternulo praviĝos kaj gloriĝos la tuta idaro de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Kliniĝis Bel, falis Nebo; iliaj idoloj estas transdonitaj al bestoj kaj brutoj; tio, kion vi portadis, fariĝis ŝarĝo por lacaj bestoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Ili kliniĝis kaj falis kune, ne povis savi sian ŝarĝon, kaj mem iris en malliberecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Aŭskultu Min, domo de Jakob kaj la tuta restaĵo de la domo de Izrael, kiuj estas ŝarĝitaj sur Mi de post via naskiĝo, kiuj estas portataj de Mi de post via eliro el la ventro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Ankaŭ ĝis via maljuneco Mi estos la sama, kaj ĝis via griziĝo Mi vin portos; Mi vin kreis kaj Mi portos, Mi ŝarĝos sur Min kaj Mi savos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Al kiu vi Min egaligos kaj komparos kaj similigos Min, ke ni estu similaj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Tiuj, kiuj ŝutas oron el la saketo kaj pesas arĝenton sur pesilo, dungas oraĵiston, ke li faru el tio dion, antaŭ kiu ili kliniĝas kaj ĵetas sin teren,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'levas lin sur la ŝultron, portas kaj starigas lin sur lia loko; kaj li staras, ne moviĝas de sia loko; eĉ se oni krias al li, li ne respondas kaj neniun savas el lia malfeliĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Memoru tion kaj estu viroj, prenu tion al via koro, ho pekantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Memoru tion, kio estis en la komenco de la tempo; ĉar Mi estas Dio, kaj ne ekzistas alia; Mi estas Dio, kaj ne ekzistas simila al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'Mi anoncas antaŭe la estontaĵon, kaj antaŭlonge tion, kio ankoraŭ ne okazis; kiam Mi diras, Mia decido plenumiĝas, kaj ĉion, kion Mi deziras, Mi faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Mi vokas de oriento aglon, el lando malproksima viron de Mia destino. Kion Mi diris, tion Mi venigos; kion Mi pripensis, tion Mi plenumos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Aŭskultu Min, vi, kiuj havas malhumilan koron, kiuj estas malproksimaj de la vero:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Mi alproksimigis Mian veron, por ke ĝi ne estu malproksima, kaj Mia savo ne prokrastiĝos; kaj Mi donos al Cion savon, al Izrael Mian gloron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Iru malsupren kaj sidiĝu sur polvo, ho virgulino filino de Babel; sidiĝu sur la tero, sentronigita filino de la Ĥaldeoj; ĉar oni ne plu nomos vin delikata kaj dorlotata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Prenu manan muelilon kaj muelu farunon; forigu vian vualon, levu vian vestrandon, malkovru vian kruron, transiru riverojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Malkovriĝos via nudaĵo, kaj montriĝos via honto. Mi faros venĝon, kaj Mi neniun indulgos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Nia Liberiganto-Lia nomo estas Eternulo Cebaot, Sanktulo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Sidu silente kaj iru en mallumon, ho filino de la Ĥaldeoj, ĉar oni ne plu nomos vin estrino de regnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Kiam Mi koleris Mian popolon, malhonoris Mian heredaĵon, kaj transdonis ilin en viajn manojn, vi ne montris al ili kompaton, sur maljunulon vi metis tre peze vian jugon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'vi diris: Eterne mi estos estrino; vi ne prenis tion al via koro, ne pensis pri la sekvoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Aŭskultu do nun, ho voluptulino, kiu sidas senzorge, kiu diras en sia koro: Mi estas, kaj ne ekzistas alia krom mi; mi ne fariĝos vidvino, kaj mi ne konos perdon de infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Venos do sur vin tiuj du aferoj subite, en unu tago; seninfaneco kaj vidvineco en plena mezuro trafos vin, malgraŭ viaj multaj sorĉoj, malgraŭ la granda forto de viaj magiaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Vi sentis vin sendanĝera en via malboneco; vi diris: Neniu min vidas; via saĝeco kaj via scio estis viaj delogantoj; kaj vi diris en via koro: Mi estas, kaj ne ekzistas alia krom mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Tial venos sur vin malbono, kies komencon vi ne scios, kaj falos sur vin malfeliĉo, el kiu vi ne povos vin elaĉeti, kaj surprizos vin pereo, kiun vi ne antaŭvidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Restu do ĉe viaj magiaĵoj, kaj ĉe viaj multaj sorĉoj, super kiuj vi laboris de via juneco; eble vi povos profiti, eble vi fortiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Vi laciĝis de la multo de viaj konsiliĝoj; nun ili stariĝu, la mezurantoj de la ĉielo, la esplorantoj de la steloj, la antaŭdiristoj laŭ la luno, kaj ili savu vin kontraŭ tio, kio trafos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Jen, ili fariĝos kiel pajlo; la fajro forbruligos ilin; ili ne savos sian animon el la forto de la flamo; ne estos ia karbo, ĉe kiu sin varmigi, nek fajro, antaŭ kiu sidi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Tiaj fariĝis por vi tiuj, kun kiuj vi multe penis, kun kiuj vi interrilatis de via juneco; ĉiu forvagis siaflanken, neniu vin savos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Aŭskultu tion, ho domo de Jakob, vi, kiuj estas nomataj per la nomo de Izrael, kiuj devenis el la fonto de Jehuda, kiuj ĵuras per la nomo de la Eternulo kaj citas la Dion de Izrael, ne en vero kaj ne en justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'Laŭ la sankta urbo ili sin nomas, kaj je la Dio de Izrael ili sin apogas; Eternulo Cebaot estas Lia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'La estintajn okazintaĵojn Mi anoncis antaŭlonge, el Mia buŝo tio eliris, kaj Mi ĝin aŭdigis; Mi agis subite, kaj ĉio plenumiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Ĉar Mi sciis, ke vi estas obstina kaj via kolo estas fera tendeno kaj via frunto estas kupra,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'tial Mi anoncis al vi antaŭlonge, Mi aŭdigis al vi, antaŭ ol tio plenumiĝis, por ke vi ne diru: Mia idolo tion faris, mia statuo kaj mia fanditaĵo tion ordonis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Vi aŭdis; rigardo do ĉion; ĉu vi ne devas mem tion konfesi? Mi aŭdigis al vi nun aferojn novajn kaj kaŝitajn, kiujn vi ne sciis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Nun ili estas kreitaj, ne antaŭlonge; eĉ unu tagon antaŭe vi ne aŭdis pri tio, por ke vi ne diru: Jen, mi sciis pri ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Vi ne aŭdis, vi ne sciis, kaj via orelo antaŭe ne estis malfermita; ĉar Mi sciis, ke vi perfidos, de la momento de via naskiĝo oni ja nomas vin nefidindulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Pro Mia nomo Mi prokrastas Mian koleron, kaj pro Mia gloro Mi detenas Min, ke Mi ne ekstermu vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Jen Mi vin refandis, sed ne rezultis arĝento; Mi elprovis vin en la forno de mizero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Por Mi, por Mi Mi tion faras; ĉar kial oni blasfemu? Mian gloron Mi ne donos al iu alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Aŭskultu Min, ho Jakob kaj Mia alvokito Izrael: tio estas Mi; Mi estas la unua, kaj Mi estas la lasta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Nur Mia mano fondis la teron, kaj Mia dekstra mano etendis la ĉielon; se Mi vokos ilin, ili stariĝos kune.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Kolektiĝu vi ĉiuj kaj aŭskultu: kiu inter ili anoncis tion? tiu, kiun la Eternulo ekamis, plenumos Lian volon en Babel kaj aperigos Lian potencon super la Ĥaldeoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Mi, Mi tion diris, Mi lin alvokis, venigis, kaj sukcesigis lian vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Alproksimiĝu al Mi, aŭskultu tion; de la komenco Mi ne parolis sekrete; de la momento, kiam la afero komenciĝis, Mi tie estis. Kaj ankaŭ nun sendis min la Sinjoro, la Eternulo, kaj Lia spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'Tiele diras la Eternulo, via Liberiganto, la Sanktulo de Izrael: Mi estas la Eternulo, via Dio, kiu instruas vin por via utilo, kiu kondukas vin laŭ la vojo, kiun vi devas iri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'Ho, se vi atentus Miajn ordonojn! tiam via paco estus kiel rivero, kaj via justeco kiel la ondoj de la maro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'kaj via idaro estus kiel sablo, kaj viaj devenantoj kiel ĝiaj grajnetoj; lia nomo ne estus ekstermita nek pereigita antaŭ Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Eliru el Babel, kuru el Ĥaldeujo, anoncu kun voĉo ĝojkria, aŭdigu tion, disportu ĝin ĝis la fino de la tero, diru: La Eternulo liberigis Sian servanton Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Kaj ili ne soifis en la dezertoj, tra kiuj Li kondukis ilin; Li elfluigis por ili akvon el roko, Li disfendis rokon, kaj ekfluis akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Sed por la malpiuloj, diras la Eternulo, ne ekzistas paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Aŭskultu min, ho insuloj, kaj atentu, ho malproksimaj gentoj: la Eternulo min alvokis el la ventro, el la interno de mia patrino Li vokis mian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Kaj Li faris mian buŝon simila al akra glavo, kovris min per la ombro de Sia mano, kaj faris min polurita sago, kaŝis min en Sia sagujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'Kaj Li diris al mi: Vi estas Mia servanto, ho Izrael, per kiu Mi gloriĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Mi opiniis, ke vane mi penis, ke sencele kaj vane mi konsumis mian forton; sed vere mia rajto estas ĉe la Eternulo, kaj mia rekompenco ĉe mia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'Kaj nun diris la Eternulo, kiu el la patrina ventro kreis min Lia servanto, por ke mi revenigu al Li Jakobon kaj por ke Izrael kolektiĝu ĉe Li (ĉar mi estas honorata antaŭ la okuloj de la Eternulo, kaj mia Dio estas mia forto) -');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'Li diris: Ne sufiĉas, ke vi estas Mia servanto, por restarigi la tribojn de Jakob kaj revenigi la konservitojn de Izrael; sed Mi faros vin lumo por la nacioj, por ke Mia savo etendiĝu ĝis la fino de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Tiele diras la Eternulo, la Liberiganto de Izrael, lia Sanktulo, al la malestimata animo, al la abomenato de la popoloj, al la sklavo de la regantoj: Reĝoj ekvidos kaj leviĝos; princoj, kaj ili adorkliniĝos; pro la Eternulo, kiu estas fidinda, pro la Sanktulo de Izrael, kiu vin elektis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Tiele diras la Eternulo: En la tempo de favoro Mi aŭskultos vin, kaj en la tago de savo Mi helpos vin, kaj Mi konservos vin kaj faros vin interligo por la popoloj, por restarigi la teron, por ekposedi dezertigitajn posedaĵojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'por diri al la malliberigitoj: Eliru! al la troviĝantoj en mallumo: Montriĝu! Ĉe la vojoj ili paŝtiĝos, kaj sur ĉiuj nudaj montetoj estos ilia paŝtejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Ili ne malsatos nek soifos, ne frapos ilin siroko nek la suno; ĉar ilia Kompatanto ilin kondukos, kaj al fontoj de akvo Li ilin gvidos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Kaj Mi faros ĉiujn Miajn montojn vojo, kaj Miaj vojetoj estos ebene altigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Jen tiuj venos de malproksime, kaj aliaj de nordo kaj de okcidento, kaj aliaj el la lando Sinim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Ĝojkriu, ho ĉielo, kaj ĝoju, ho tero, sonigu kanton, ho montoj; ĉar la Eternulo konsolis Sian popolon kaj kompatis Siajn mizerulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Sed Cion diris: La Eternulo min forlasis, kaj mia Sinjoro min forgesis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Ĉu povas virino forgesi sian infaneton kaj ne kompati la idon de sia ventro? eĉ se ili forgesos, Mi vin ne forgesos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Jen sur Miaj manoj Mi vin gravuris; viaj muroj estas ĉiam antaŭ Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Rapidos viaj konstruantoj; viaj detruantoj kaj viaj ekstermantoj eliros for de vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Levu ĉirkaŭen viajn okulojn, kaj rigardu: ĉiuj kolektiĝis, venas al vi. Kiel Mi vivas, diras la Eternulo, vi ĉiujn metos sur vin kiel ornamon, kaj vi ĉirkaŭligos vin per ili kiel fianĉino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Ĉar viaj dezertigitaj kaj senhomigitaj lokoj kaj via ruinigita lando estas tro malvastaj por la loĝantoj, kaj viaj ekstermantoj estos malproksimigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Viaj malaperintaj infanoj ankoraŭ diros en viajn orelojn: Tro malvasta estas por mi la loko; cedu al mi, ke mi povu loĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Tiam vi diros en via koro: Kiu naskis al mi ĉi tiujn? mi estis ja seninfana kaj soleca, elpelita kaj forpuŝita; kiu do edukis ilin? mi restis ja sola; kie do estis ĉi tiuj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'Tiele diras la Sinjoro, la Eternulo: Jen Mi levos Mian manon al la nacioj, kaj antaŭ la gentoj Mi elmetos Mian standardon; kaj ili venigos viajn filojn en la baskoj, kaj viajn filinojn ili portos sur la ŝultroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'Kaj reĝoj estos viaj vartistoj, kaj iliaj princinoj estos viaj nutristinoj; vizaĝaltere ili kliniĝos antaŭ vi, kaj la polvon de viaj piedoj ili lekos; kaj tiam vi ekscios, ke Mi estas la Eternulo, ke Miaj fidantoj ne hontos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Ĉu de fortulo oni povas forpreni la akiritaĵon? aŭ ĉu oni povas liberigi la kaptitojn de venkinto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Sed tiele diras la Eternulo: Eĉ la kaptitoj estos forprenitaj for de la fortulo, kaj la akiritaĵo de la potenculo formalaperos; kaj kontraŭ viaj kverelantoj Mi kverelos, kaj viajn filojn Mi savos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'Kaj al viaj premantoj Mi manĝigos ilian propran karnon, kaj kiel de mosto ili ebriiĝos de sia propra sango; kaj ekscios ĉiu karno, ke Mi, la Eternulo, estas via Savanto kaj via Liberiganto, la Potenculo de Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Tiele diras la Eternulo: Kie estas la eksedziga letero de via patrino, per kiu Mi ŝin forpuŝis? aŭ al kiu el Miaj kreditoroj Mi vendis vin? Jen pro viaj pekoj vi estas venditaj, kaj pro viaj krimoj estas forpuŝita via patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Kial neniu estis, kiam Mi venis? kial neniu respondis, kiam Mi vokis? Ĉu Mia mano fariĝis tro mallonga, por liberigi? kaj ĉu ne ekzistas en Mi forto, por savi? Jen per Mia severa vorto Mi sekigas maron, Mi faras el riveroj dezerton; iliaj fiŝoj putras pro senakveco kaj mortas de soifo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Mi vestas la ĉielon per mallumo, kaj sakaĵon Mi faras ĝia kovrilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'La Sinjoro, la Eternulo, donis al mi langon instruitan, por ke mi povosciu vigligi per vorto senfortigiton; Li vekas, ĉiumatene vekas mian orelon, por ke mi aŭskultu kiel instruatoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'La Sinjoro, la Eternulo, malfermis mian orelon, kaj mi ne kontraŭstaris, mi ne turnis min malantaŭen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Mian dorson mi elmetis al la batantoj kaj miajn vangojn al la harŝirantoj; mian vizaĝon mi ne kovris kontraŭ insultoj kaj kraĉado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Sed la Sinjoro, la Eternulo, helpas al mi, tial mi ne estas hontigata; tial mi faris mian vizaĝon kiel siliko, kaj mi scias, ke mi ne estos senhonorigata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Proksima estas mia praviganto; kiu procesos kontraŭ mi? ni stariĝu kune; kiu postulas juĝon kontraŭ mi, li alproksimiĝu al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Jen la Sinjoro, la Eternulo, helpas al mi; kiu do malpravigos min? jen ili ĉiuj elfrotiĝos kiel vesto, tineoj ilin tramanĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Kiu inter vi timas la Eternulon, aŭskultas la voĉon de Lia servanto? Kvankam li iras en mallumo kaj nenio brilas al li, tamen li fidu la nomon de la Eternulo kaj apogu sin sur sia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Jen vi ĉiuj, kiuj ekbruligas fajron, ĉirkaŭas sin per flamoj, iru en la lumon de via fajro, kaj en la flamojn, kiujn vi ekbruligis. Per Mia mano tio fariĝos al vi; en doloro vi kuŝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Aŭskultu Min, vi, kiuj postkuras la veron, kiuj serĉas la Eternulon: rigardu la rokon, el kiu vi estas elhakitaj, kaj en la profundon de la kavo, el kiu vi estas elfositaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Rigardu Abrahamon, vian patron, kaj Saran, vian naskintinon; ĉar Mi alvokis lin, kiam li estis sola, kaj Mi benis lin kaj multigis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Ĉar la Eternulo konsolos Cionon, konsolos ĉiujn ĝiajn ruinojn, kaj ĝian dezerton Li faros kiel Eden, kaj ĝian stepon kiel la ĝardeno de la Eternulo; ĝojo kaj gajeco troviĝos en ĝi, dankado kaj laŭta kantado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Atentu Min, ho Mia popolo, kaj vi, Mia gento, aŭskultu Min; ĉar instruo eliros el Mi, kaj Mian leĝon Mi starigos kiel lumon por la popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Proksima estas Mia vero, eliris Mia helpo, kaj Miaj brakoj juĝos popolojn; al Mi esperas insuloj kaj atendas Mian brakon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Levu al la ĉielo viajn okulojn, kaj rigardu la teron malsupre; ĉar la ĉielo disneniiĝos kiel fumo, kaj la tero elfrotiĝos kiel vesto, kaj ĝiaj loĝantoj mortos kiel kuloj; sed Mia savo restos eterne, kaj Mia vero ne difektiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Aŭskultu Min, vi, kiuj konas la veron, popolo, havanta Mian instruon en sia koro: ne timu ofendon de homoj, kaj de iliaj insultoj ne senkuraĝiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Ĉar kiel veston tramanĝos ilin tineoj, kaj kiel lanaĵon tramanĝos ilin vermoj; sed Mia vero restos eterne, kaj Mia savo por ĉiuj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Leviĝu, leviĝu, vestu vin per forto, ho brako de la Eternulo; leviĝu, kiel en la tempo antikva, en la generacioj de antaŭlonge. Ĉu ne vi dishakis Rahabon, trapikis la drakon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Ĉu ne vi elsekigis la maron, la akvon de grandega abismo, faris la maran profundon vojo por transiro de la liberigitoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Kaj la elaĉetitoj de la Eternulo revenos kaj iros sur Cionon kun kantado, kaj ĝojo eterna estos super ilia kapo; ĝojon kaj gajecon ili atingos, kaj forflugos afliktoj kaj ĝemado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Mi, Mi mem estas via konsolanto. Kiu vi estas, ke vi timas homon morteman, kaj homidon, kiu estas egala al herbo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'kaj vi forgesis la Eternulon, vian Kreinton, kiu etendis la ĉielon kaj fondis la teron; kaj konstante, ĉiutage, vi timas la furiozon de la premanto, kiu celas ekstermi? Sed kie estas la furiozo de la premanto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Baldaŭ la kaptito estos liberigita, ke li ne mortu en la kavo kaj ne manku al li pano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Mi estas la Eternulo, via Dio, kiu kvietigas la maron, kiam bruas ĝiaj ondoj, kaj kies nomo estas Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Mi metis Miajn vortojn en vian buŝon kaj kovris vin per la ombro de Mia mano, por aranĝi la ĉielon kaj doni fundamenton al la tero, kaj por diri al Cion: Vi estas Mia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Vekiĝu, vekiĝu, leviĝu, ho Jerusalem, vi, kiu trinkis el la mano de la Eternulo la kalikon de Lia kolero; la ŝaŭmantan ebriigantan kalikon vi eltrinkis ĝis la fundo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'El ĉiuj filoj, kiujn ŝi naskis, neniu ŝin gvidis; el ĉiuj filoj, kiujn ŝi edukis, neniu tenis ŝin je la mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Tio ambaŭ vin trafis; kiu kompatis vin? ruinado kaj malfeliĉo, malsato kaj glavo; per kiu mi povus konsoli vin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Viaj filoj senfortiĝis, kuŝis ĉe la komenco de ĉiuj stratoj kiel cervo en reto, plenaj de la kolero de la Eternulo, de la indigno de via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Tial aŭskultu ĉi tion, vi, mizerulino kaj ebriulino, sed ne de vino:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'tiele diras via Sinjoro, la Eternulo, kaj via Dio, kiu defendas Sian popolon: Jen Mi prenis el via mano la ebriigan kalikon, la ŝaŭmantan kalikon de Mia kolero; vi ne plu trinkos ĝin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'kaj Mi transdonos ĝin en la manon de viaj turmentantoj, kiuj diris al via animo: Klinu vin, por ke ni transiru; kaj vi faris el via dorso kvazaŭ teron, kvazaŭ straton por pasantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Vekiĝu, vekiĝu, vestu vin per via forto, ho Cion; surmetu sur vin la vestojn de via majesto, ho Jerusalem, sankta urbo; ĉar ne plu eniros en vin necirkumcidito kaj malpurulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Forskuu de vi la polvon, leviĝu, sidiĝu, ho Jerusalem; disigu la ligilojn de via kolo, ho kaptita filino de Cion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Ĉar tiele diras la Eternulo: Senpage vi estis vendita, kaj ne per arĝento vi estos elaĉetita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Ĉar tiele diras la Sinjoro, la Eternulo: En Egiptujon iam iris Mia popolo, por loĝi tie kelktempe, kaj la Asiriano pro nenio ĝin premis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'kion do Mi nun ĉi tie devas fari, diras la Eternulo, kiam Mia popolo estas prenita pro nenio? ĝiaj regantoj triumfe krias, diras la Eternulo, kaj konstante, ĉiutage, Mia nomo estas insultata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Tial Mia popolo ekkonos Mian nomon; tial ĝi ekscios en tiu tago, ke Mi estas Tiu sama, kiu diras: Jen Mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Kiel ĉarmaj estas sur la montoj la piedoj de anoncanto, kiu proklamas pacon, anoncas bonon, sciigas pri helpo, diras al Cion: Reĝas via Dio!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Jen eksonis la voĉo de viaj gardostarantoj; ili levas la voĉon kaj kune ĝojkrias, ĉar per siaj propraj okuloj ili vidas, kiel la Eternulo revenas al Cion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Triumfu, ĝojkriu kune, ho ruinoj de Jerusalem; ĉar la Eternulo konsolis Sian popolon, liberigis Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'La Eternulo malkovris Sian sanktan brakon antaŭ la okuloj de ĉiuj nacioj; kaj ĉiuj finoj de la tero vidas la helpon de nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Foriru, foriru, eliru el tie, ne tuŝu malpuraĵon; eliru el ĝia mezo; purigu vin, ho portantoj de la vazoj de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Tamen ne rapidante vi eliros, kaj ne forkurante vi iros; ĉar iros antaŭ vi la Eternulo, kaj gardos vin malantaŭe la Dio de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Jen Mia servanto havos sukceson, li altiĝos kaj gloriĝos kaj staros tre alte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Kiel multaj estis teruritaj, rigardante vin (tiele lia aspekto estis malbeligita pli ol ĉe ĉiu alia kaj lia eksteraĵo pli ol ĉe iu ajn homo),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'tiel li saltigos pri si multe da popoloj; reĝoj fermos antaŭ li sian buŝon, ĉar ili vidos ion, kio ne estis dirita al ili, kaj ili rimarkos ion, pri kio ili ne aŭdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Kiu kredus al tio, kion ni aŭdis? kaj super kiu malkaŝiĝis la brako de la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Ĉar li elkreskis antaŭ Li kiel juna branĉo kaj kiel radiko el tero senakva; li ne havis staturon nek belecon; ni rigardis lin, sed li ne havis aspekton, per kiu li plaĉus al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Li estis malestimata kaj evitata de homoj, viro suferanta kaj malsana; kaj kiel iganta deturni de li la vizaĝon, li estis malestimata, kaj li havis por ni nenian valoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Vere, niajn malsanojn li portis sur si, kaj per niaj suferoj li sin ŝarĝis; sed ni opiniis lin plagita, frapita de Dio, kaj humiligita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'Tamen li estis vundita pro niaj pekoj, dispremita pro niaj krimoj; puno por nia bono estis sur li, kaj per lia vundo ni saniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Ni ĉiuj erarvagis kiel ŝafoj, ĉiu iris sian vojon; kaj la Eternulo ĵetis sur lin la kulpon de ni ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Li estis turmentata, tamen li humiliĝis kaj ne malfermis sian buŝon; kiel ŝafido kondukata al buĉo kaj kiel ŝafo muta antaŭ siaj tondantoj, li ne malfermis sian buŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'De malliberigo kaj de juĝo li estas prenita; kaj pri lia generacio kiu rakontos? De sur la tero de vivantoj li estas fortranĉita, pro la kulpo de mia popolo li estas frapita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'Inter malbonaguloj oni donis al li tombon, inter riĉuloj post lia morto, kvankam li ne faris maljustaĵon kaj trompo ne estis en lia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Sed la Eternulo volis tiel lin turmenti. Kiam lia animo estos preninta sur sin elaĉetan punon, li vidos idaron, li longe vivos, kaj la intenco de la Eternulo sukcesos per lia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'La laborfrukton de sia animo li vidos, kaj satiĝos. Per konigo de li Mia virtulo-servanto virtigos multajn; kaj iliajn pekojn li portos sur si.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Tial Mi donos al li multajn kiel lian parton, kaj la potenculojn li dividos kiel akiron; pro tio, ke li elmetis sian animon al la morto kaj estis alkalkulita al krimuloj, dum li portis sur si la pekon de multaj kaj petis por la krimuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Ĝoju, ho senfruktulino, kiu ne naskis; sonigu kanton kaj ĝojkriu, ho vi, kiu ne suferis doloron; ĉar la forlasitino havos pli da infanoj, ol la havanta edzon, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Vastigu la spacon de via tendo, disetendu la tapiŝojn de viaj loĝejoj, ne retenu; etendu pli longe viajn ŝnurojn, kaj viajn palisojn fortikigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Ĉar dekstren kaj maldekstren vi disvastiĝos, kaj via idaro ekposedos naciojn kaj ekloĝos en urboj dezertigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Ne timu, ĉar vi ne estos malhonorata; ne kaŝu vin honte, ĉar vi ne estos hontigata, kaj ĉar la honton de via juneco vi forgesos kaj la malhonoron de via vidvineco vi ne plu rememoros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Ĉar via Kreinto estas via edzo, Eternulo Cebaot estas Lia nomo; kaj via Liberiginto estas la Sanktulo de Izrael, kiun oni nomas Dio de la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Ĉar kiel virinon forlasitan kaj afliktitan en la spirito la Eternulo vin alvokis; kaj kiel edzinon de la juneco, kvankam forpuŝitan, diras via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Por malgranda momento Mi vin forlasis, kaj kun granda kompato Mi vin reprenos al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'En eksplodo de kolero Mi forturnis de vi Mian vizaĝon por momento, sed per eterna favorkoreco Mi vin kompatis, diras via Liberiginto, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Ĉar tio estas por Mi kiel la akvo de Noa; kiel Mi ĵuris, ke Mi ne plu venigos la akvon de Noa sur la teron, tiel Mi ĵuris, ke Mi ne koleros vin nek insultos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Ĉar montoj forŝoviĝos kaj altaĵoj ŝanceliĝos; sed Mia favorkoreco ne foriĝos de vi, kaj la interligo de Mia paco ne ŝanceliĝos, diras la Eternulo, via Kompatanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'Ho mizera, suferanta de ventego, senkonsola! jen Mi donos brilon al viaj ŝtonoj, kaj vian fundamenton Mi faros el safiroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'Kaj Mi faros viajn murdentojn el rubenoj kaj viajn pordegojn el kristaloj kaj ĉiujn viajn limojn el multekostaj ŝtonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'Kaj ĉiuj viaj infanoj estos instruitaj de la Eternulo, kaj granda estos la bonstato de viaj filoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Per vero vi fortikiĝos; estu malproksima de premiteco, ĉar vi ne bezonas timi, kaj de teruro, ĉar ĝi ne alproksimiĝos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Certe, oni sin armos kontraŭ vi, sed tio ne estos de Mi; kiu sin armos kontraŭ vi, tiu falos antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Jen Mi kreis la forĝiston, kiu blovas fajron sur karboj kaj ellaboras ilojn por siaj faroj; kaj Mi ankaŭ kreis ekstermanton por detruado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Nenia ilo, kreita kontraŭ vi, havos sukceson; kaj ĉiun langon, kiu batalos kontraŭ vi en la juĝo, vi malpravigos. Tio estas la heredaĵo de la servantoj de la Eternulo, kaj ilia praveco antaŭ Mi, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Ho vi, ĉiuj soifantoj, iru al la akvo, kaj vi, kiuj ne havas monon; iru, aĉetu, kaj manĝu; iru, aĉetu sen mono kaj sen pago vinon kaj lakton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Kial vi donas monon por tio, kio ne estas pano? kaj vian laboron por tio, kio ne satigas? aŭskultu do Min, kaj manĝu bonaĵon, kaj via animo ĝuu grasaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Klinu vian orelon, kaj venu al Mi; aŭskultu, por ke vivu via animo; kaj Mi faros kun vi interligon eternan pri la fidindaj korfavoroj, promesitaj al David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Jen Mi starigis lin kiel atestanton por la nacioj, kiel princon kaj ordonanton por la gentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Jen vi vokos popolon, kiun vi ne konas; kaj popolo, kiu vin ne konas, alkuros al vi, pro la Eternulo, via Dio, kaj pro la Sanktulo de Izrael, ĉar Li faris vin glora.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Serĉu la Eternulon, dum Li estas trovebla; voku Lin, dum Li estas proksime.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Malpiulo forlasu sian vojon, kaj krimulo siajn intencojn, kaj li returnu sin al la Eternulo, kaj ĉi Tiu lin kompatos, kaj al nia Dio, ĉar Li multe pardonas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Ĉar Miaj pensoj ne estas viaj pensoj, kaj viaj vojoj ne estas Miaj vojoj, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Kiom la ĉielo estas pli alte ol la tero, tiom Miaj vojoj estas pli alte ol viaj vojoj, kaj Miaj pensoj ol viaj pensoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Ĉar kiel la pluvo kaj la neĝo falas de la ĉielo kaj ne revenas tien, sed malsoifigas la teron kaj naskigas kaj produktigas ĝin kaj donas semon al la semanto kaj panon al la manĝanto:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'tiel estos Mia vorto, kiu eliras el Mia buŝo; ĝi ne revenos al Mi vane, sed plenumos Mian volon, kaj sukcesos en tio, por kio Mi ĝin sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Kun ĝojo vi eliros, kaj kun paco vi estos kondukataj; la montoj kaj montetoj sonigos antaŭ vi kanton, kaj ĉiuj arboj de la kampo plaŭdos per la manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Anstataŭ pikarbetaĵo elkreskos cipreso, anstataŭ urtiko elkreskos mirto; kaj tio estos gloro por la Eternulo, eterna signo, kiu ne ekstermiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Tiele diras la Eternulo: Gardu justecon kaj faru bonon; ĉar baldaŭ venos Mia savo kaj malkaŝiĝos Mia vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Feliĉa estas la homo, kiu tion faras, kaj la homido, kiu sin tenas je tio, kaj observas sabaton, por ne malsanktigi ĝin, kaj gardas sian manon, por fari nenian malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'La fremdulo, kiu aliĝis al la Eternulo, ne diru: La Eternulo elapartigos min de Sia popolo; kaj la eŭnuko ne diru: Jen mi estas arbo velkinta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Ĉar tiele diras la Eternulo pri la eŭnukoj, kiuj observas Miajn sabatojn, elektas tion, kio plaĉas al Mi, kaj tenas sin je Mia interligo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'Al ili Mi donos en Mia domo kaj inter Miaj muroj lokon kaj nomon pli bonan ol al filoj kaj filinoj; Mi donos al ili nomon eternan, kiu ne ekstermiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Kaj la fremdulojn, kiuj aliĝis al la Eternulo, por servi al Li kaj ami la nomon de la Eternulo, por estis Liaj sklavoj, ĉiujn, kiuj observas sabaton, por ne malsanktigi ĝin, kaj kiuj tenas sin je Mia interligo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'Mi venigos sur Mian sanktan monton kaj ĝojigos en Mia preĝejo; iliaj bruloferoj kaj buĉoferoj estos favore akceptataj sur Mia altaro; ĉar Mia domo estos nomata preĝejo por ĉiuj popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'La Sinjoro, la Eternulo, kiu kolektas la dispelitojn de Izrael, diras: Al liaj kolektitoj Mi kolektos ankoraŭ pli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Venu por manĝi, ho ĉiuj bestoj kampaj, ĉiuj bestoj arbaraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Liaj gardistoj ĉiuj estas blindaj, senkomprenaj; ili ĉiuj estas hundoj mutaj, kiuj ne povas boji, dormemaj, kuŝemaj, amantaj dormeti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'Tamen ili estas hundoj avidaj, kiuj ne povas satiĝi; kaj ili estas paŝtistoj, kiuj nenion komprenas; ĉiu iras sian vojon, ĉiu siaflanke serĉas sian profiton, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'Venu, mi prenos vinon, kaj ni trinku ebriigaĵon; kaj kiel estas hodiaŭ, tiel estos morgaŭ, multe kaj ankoraŭ multe pli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'La virtulo pereis, kaj neniu prenis tion al sia koro; kaj piaj homoj estas forkaptataj, kaj neniu komprenas, ke for de malbono estas forkaptita la virtulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Kiu iras ĝustan vojon, tiu venas al paco, ripozas sur sia kuŝejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Sed venu ĉi tien vi, ho filoj de sorĉistino, idoj de adultulo kaj malĉastulino!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Kiun vi mokegas? kontraŭ kiu vi malfermegas la buŝon kaj elŝovas la langon? ĉu vi ne estas infanoj de krimo, idoj de mensogo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'kiuj varmiĝas en la arbaretoj, sub ĉiu verdbranĉa arbo; kiuj buĉas la infanojn en la valoj, sub la elstarantaj rokoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Inter la glataĵoj de la valo estas via parto; ili, ili estas via loto; al ili vi verŝis verŝoferojn, alportis farunoferojn; ĉu Mi povas esti kontenta pri tio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Sur monto alta kaj levita vi starigis vian kuŝejon, vi tien supreniris, por buĉi oferojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'Kaj malantaŭ la pordo kaj la fostoj vi starigis vian simbolon; ĉar vi forturnis vin de Mi kaj supreniris, larĝigis vian kuŝejon, kaj ligis vin kun ili; vi ekamis ilian kuŝejon, elrigardis por vi oportunan lokon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Oleita vi pilgrimis al la reĝo, uzis multe da aromaĵoj, kaj vi sendis malproksimen viajn senditojn, kaj malaltiĝis ĝis Ŝeol.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Pro la multeco de viaj vojoj vi laciĝis, tamen vi ne diris: Mi perdis la esperon; vi trovis ankoraŭ vivon en via mano, kaj pro tio vi ne laciĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Sed kiu kaŭzis al vi zorgojn, kaj kiun vi timis, ke vi ekmensogis kaj Min ne memoris kaj ne prenis al via koro? ĉu pro tio, ke Mi silentas tre longe, vi Min ne timas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Se Mi montros vian pravecon kaj viajn farojn, ili ne helpos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Kiam vi krios, viaj idolamasoj vin savu; sed ilin ĉiujn disportos la vento, forpelos la blovo; kaj kiu fidas Min, tiu ekposedos la teron kaj heredos Mian sanktan monton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'Kaj Li diras: Faru vojon, faru vojon, ebenigu irejon, forigu malhelpojn de la vojo de Mia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Ĉar tiele diras la Plejalta kaj Plejsupra, kiu restas eterne kaj kies nomo estas Sanktulo: Alte kaj en sankta loko Mi loĝas, sed ankaŭ apud afliktito kaj humilulo, por revigligi la spiriton de humiluloj kaj revivigi la koron de afliktitoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Ĉar ne eterne Mi malpacas kaj ne senfine Mi koleras; alie tute senfortiĝus antaŭ Mi la spirito kaj la animoj, kiujn Mi kreis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Pro la peko de lia avideco Mi koleris kaj frapis lin, Mi deturnis Min kaj koleris; sed li iris perfide, iris laŭ la vojo de sia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Mi vidis liajn vojojn, kaj Mi lin sanigos; Mi kondukos lin kaj redonos konsolon al li kaj al liaj plorantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Mi kreos diron de la buŝo: Paco, paco al malproksimaj kaj al proksimaj, diras la Eternulo; kaj Mi sanigos lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Sed la malpiuloj estas kiel malkvieta maro, kiu ne povas trankviliĝi kaj kies akvo elĵetas ŝlimon kaj koton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Ne ekzistas paco por la malpiuloj, diras mia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Kriu per la tuta gorĝo, ne detenu vin, laŭtigu vian voĉon simile al fanfaro, kaj eldiru al Mia popolo ĝian krimon kaj al la domo de Jakob ĝiajn pekojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Min ili ĉiutage serĉas, kaj ili deziras ekkoni Miajn vojojn; kiel popolo, kiu faras bonon kaj ne forlasis la leĝon de sia Dio, ili postulas de Mi justan juĝon, deziras proksimecon de Dio:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'Kial ni fastas, kaj Vi ne vidas? turmentas nian animon, kaj Vi ne scias? Sed jen en la tago de via fastado vi plenumas viajn dezirojn, kaj ĉiujn viajn laborantojn vi premas per postuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Jen vi fastas por kverelo kaj malpaco, kaj por bati per malpia pugno; kiel nun, vi ne fastas tiel, ke en la alteco estu aŭdata via voĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Ĉu tia estas fasto, kiu plaĉas al Mi, kiam homo turmentas sian animon, klinas sian kapon kiel kanon, kaj sternas sub si sakaĵon kaj cindron? ĉu tion vi nomas fasto kaj tago plaĉanta al la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Ja nur tio estas fasto, kiu plaĉas al Mi, se vi disŝiros la ligilojn de malpieco, disbatos la katenojn de sklaveco, liberigos la prematojn, disbatos ĉian jugon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'se vi derompos vian panon por malsatulo kaj senhejmajn malriĉulojn enkondukos en vian domon; se, vidante nudulon, vi lin vestos, kaj antaŭ viaj samkarnuloj vi vin ne kaŝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Tiam via lumo ekbrilos kiel matenruĝo, kaj via saniĝo rapide progresos; via virto iros antaŭ vi; la gloro de la Eternulo gardos vin malantaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Tiam vi vokos, kaj la Eternulo respondos; vi krios, kaj Li diros: Jen Mi estas! Se vi forigos el inter vi premadon, montradon per fingro, kaj paroladon malbonan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'kaj malfermos antaŭ malsatulo vian koron, kaj satigos suferantan animon, tiam via lumo brilos en mallumo kaj via krepusko estos kiel tagmezo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'kaj la Eternulo kondukos vin ĉiam kaj satigos vian animon en tempo de senpluveco, kaj Li fortikigos viajn ostojn; kaj vi estas kiel ĝardeno akvumata, kaj kiel akva fonto, kies akvo ne mankas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'Kaj oni rekonstruos ĉe vi la antikvajn ruinojn; la fundamentojn de antaŭ multaj generacioj vi restarigos; kaj oni nomos vin riparanto de breĉoj, reboniganto de vojoj por loĝado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Se vi retenos vian piedon en sabato, por ke vi ne plenumu viajn dezirojn en Mia sankta tago; kaj vi nomos sabaton plezuro, la sanktigitan tagon de la Eternulo vi nomos honorata; kaj vi honoros ĝin per nefarado de viaj ordinaraj aferoj, per neplenumado de viaj deziroj, kaj per neparolado de vantaĵoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'tiam vi ĝuos per la Eternulo, kaj Mi sidigos vin sur la altaĵoj de la tero, kaj Mi nutros vin per la heredaĵo de via patro Jakob; ĉar tion diras la buŝo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Vidu, ne mallongiĝis la mano de la Eternulo, por ke ĝi ne povu helpi; kaj ne malakriĝis Lia orelo, por ke Li ne aŭdu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'Nur viaj krimoj estis disigilo inter vi kaj via Dio, kaj viaj pekoj kovris antaŭ vi Lian vizaĝon, por ke Li ne aŭdu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Ĉar viaj manoj estas makulitaj per sango, kaj viaj fingroj per krimo; via buŝo parolas malveron, via lango esprimas maljustaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Neniu procesas honeste, kaj neniu juĝas juste; oni fidas vantaĵon kaj parolas malveron, gravediĝas per malhonestaĵo kaj naskas krimon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Oni kovas ovojn de vipuro, kaj oni teksas araneaĵon. Kiu manĝas iom el tiuj ovoj, tiu mortas; kiam oni ilin disrompas, elaperas vipuro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Ilia teksaĵo ne taŭgos por vesto, kaj ili ne kovros sin per sia faritaĵo; iliaj faroj estas faroj pekaj, kaj agoj de rabo estas en iliaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Iliaj piedoj kuras al malbono, kaj ili rapidas, por verŝi senkulpan sangon; iliaj pensoj estas pensoj pekaj; ruinigo kaj pereigo estas sur ilia vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Vojon de paco ili ne konas, kaj sur iliaj irejoj ne troviĝas justeco; siajn vojetojn ili kurbigis al si; ĉiu, kiu iras sur ili, ne konas pacon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Tial malproksimiĝis de ni justeco, kaj vero ne atingis nin; ni atendas lumon, sed jen estas mallumo; brilon, sed ni iras en mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Ni palpas la muron kiel blinduloj, kaj ni palpas kiel senokululoj; en tagmezo ni faletas kiel en krepusko, en mallumo kiel mortintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Ni ĉiuj blekegas kiel ursoj, kaj ni ĝemas kiel kolomboj; ni atendas justecon, sed ĝi forestas; savon, sed ĝi estas malproksime de ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Ĉar multiĝis niaj krimoj antaŭ Vi, kaj niaj pekoj atestas kontraŭ ni; ĉar niaj krimoj estas kun ni, kaj niajn pekojn ni konas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Ni krimis kaj mensogis kontraŭ la Eternulo, kaj ni forturnis nin de nia Dio; ni parolis pri rabado kaj malbonagado, ni preparis kaj eligis el la koro vortojn mensogajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Kaj forturniĝis malantaŭen la justeco, kaj la virto staras malproksime; ĉar la vero faletis sur la strato, kaj la ĝusteco ne povas veni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'Kaj la vero estas forigita; kaj prirabata estas tiu, kiu detenas sin de malbono. Kaj la Eternulo vidis, kaj Li indignis, ke forestas justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Kaj Li vidis, ke ne troviĝas viro, kaj Li miris, ke ne troviĝas defendanto; kaj helpis Lin Lia brako, kaj Lia justeco Lin subtenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Kaj Li surmetis sur Sin la veron kiel kirason, kaj la kaskon de savo sur Sian kapon; kaj Li metis sur Sin veston de venĝo, kaj envolvis Sin en severecon kiel en mantelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Laŭ la faroj Li repagos: koleron al Siaj malamikoj, honton al Siaj malamantoj; al la insuloj Li repagos, kion ili meritas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'Kaj oni timos en la okcidento la nomon de la Eternulo kaj en la oriento Lian majeston; ĉar la malamiko venos kiel rivero, pelata de la spirado de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'Kaj venos Liberiganto por Cion, kaj por tiuj el Jakob, kiuj retiriĝis de malbonagoj, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'Kaj Mi faras kun ili jenan interligon, diras la Eternulo: Mia spirito, kiu estas sur vi, kaj Miaj vortoj, kiujn Mi metis en vian buŝon, ne foriĝos de via buŝo nek de la buŝo de viaj infanoj nek de la buŝo de via plua idaro, de nun ĝis eterne, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Leviĝu, lumiĝu; ĉar venas via lumo, kaj la majesto de la Eternulo ekbrilas super vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Ĉar jen mallumo kovros la teron, kaj krepusko la popolojn; sed super vi brilos la Eternulo, kaj Lia majesto aperos super vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'Kaj popoloj iros al via lumo, kaj reĝoj al la brilo de viaj radioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Levu ĉirkaŭen viajn okulojn, kaj rigardu: ĉiuj ili kolektiĝas kaj iras al vi; viaj filoj venas de malproksime, kaj viaj filinoj estas portataj sur la brako.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Tiam vi vidos kaj estos ravita, ektremos kaj vastiĝos via koro; ĉar turniĝos al vi la abundaĵo de la maro, la riĉaĵoj de la popoloj venos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Multo da kameloj kovros vin, junaj kameloj el Midjan kaj Efa; ĉiuj ili venos el Ŝeba, portos oron kaj olibanon, kaj proklamos laŭdon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Ĉiuj ŝafoj de Kedar kolektiĝos ĉe vi; la virŝafoj de Nebajot servos al vi; favore akceptotaj ili iros sur Mian altaron, kaj la domon de Mia gloro Mi majestigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Kiuj ili estas, kiuj flugas kiel nuboj, kaj kiel kolomboj al siaj kolombujoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Al Mi celas la insuloj, kaj la ŝipoj de Tarŝiŝ estas antaŭe, por venigi viajn filojn de malproksime, ilian arĝenton kaj oron kune kun ili, pro la nomo de la Eternulo, via Dio, kaj de la Sanktulo de Izrael, ĉar Li faris vin glora.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Kaj fremduloj konstruos viajn murojn, kaj iliaj reĝoj servos al vi; ĉar en Mia kolero Mi vin frapis, sed en Mia favoro Mi vin kompatas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Kaj ĉiam nefermitaj estos viaj pordegoj, nek tage nek nokte ili estos ŝlosataj; por ke oni venigu al vi la potencon de la popoloj kaj konduku iliajn reĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Ĉar popolo aŭ regno, kiu ne servos al vi, pereos, kaj tiaj popoloj estas tute ekstermotaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'La majesto de Lebanon venos al vi; cipreso, abio, kaj bukso kuniĝos, por ornami la lokon de Mia sanktejo; kaj la lokon de Miaj piedoj Mi faros honorata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Kaj humile venos al vi la filoj de viaj premantoj, kaj ĵetos sin antaŭ viajn piedojn ĉiuj, kiuj vin malestimis; kaj oni nomos vin urbo de la Eternulo, Cion de la Sanktulo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Anstataŭ tio, ke vi estis forlasita kaj malamata kaj neniu volis preterpasi vin, Mi faros vin fierindaĵo de la mondo, ĝojo de ĉiuj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Kaj vi nutros vin per la lakto de la popoloj kaj per la abundaĵo de la reĝoj; kaj vi ekscios, ke Mi, la Eternulo, estas via Savanto kaj via Liberiganto, la Potenculo de Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Anstataŭ kupro Mi alportos oron, kaj anstataŭ fero Mi alportos arĝenton, anstataŭ ligno kupron, kaj anstataŭ ŝtonoj feron; kaj Mi faros via estraro la pacon kaj viaj administrantoj la justecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Oni ne plu aŭdos pri perforto en via lando, pri malfeliĉo kaj pereigo inter viaj limoj; kaj viajn murojn vi nomos savo kaj viajn pordegojn laŭda kanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'La suno ne plu estos por vi lumo de la tago, kaj la brilo de la luno ne lumos al vi; sed la Eternulo estos por vi lumo eterna, kaj via Dio estos via gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Via suno ne plu subiros, kaj via luno ne kaŝiĝos; ĉar la Eternulo estos por vi lumo eterna, kaj la tagoj de via funebro finiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Kaj via popolo tuta estos justuloj, por eterne ili ekposedos la teron; tio estas markoto de Mia plantado, faro de Miaj manoj, per kiu Mi Min gloros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'El la plej malgranda fariĝos milo, kaj el la plej sensignifa fariĝos potenca popolo; Mi, la Eternulo, rapide faros tion en ĝia tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'La spirito de la Sinjoro, la Eternulo, estas sur mi, ĉar la Eternulo min sanktoleis, por bonanonci al mizeruloj; Li sendis min, por bandaĝi tiujn, kies koro estas vundita, por anonci liberecon al kaptitoj kaj malŝloson al malliberigitoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'por proklami favorjaron de la Eternulo kaj venĝotagon de nia Dio, por konsoli ĉiujn malĝojulojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'por fari al la afliktitoj de Cion, ke oni donu al ili ornamon anstataŭ cindro, oleon de ĝojo anstataŭ funebro, veston de gloro anstataŭ spirito afliktita, kaj ke oni nomu ilin kverkoj de justeco, plantaĵo de la Eternulo por Lia gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'Kaj ili rekonstruos la antikvajn ruinojn, restarigos la detruitaĵojn de la antaŭa tempo, kaj renovigos la ruinigitajn urbojn, dezertigitajn antaŭ multe da generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Stariĝos fremduloj kaj paŝtos viajn ŝafojn, kaj aligentuloj estos viaj plugistoj kaj vinberistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Kaj vi estos nomataj pastroj de la Eternulo, servantoj de nia Dio oni nomos vin; la riĉaĵon de popoloj vi manĝos, kaj per ilia gloro vi gloriĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Pro via honto vi ricevos duoble, pro la malhonoro ili ĝojkantos sur siaj partoj; duoblaĵon ili ekposedos en sia lando; ĝojo eterna estos ĉe ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Ĉar Mi, la Eternulo, amas justecon, malamas rabadon kaj maljustecon; kaj Mi fidele donos al ili ilian rekompencon, kaj interligon eternan Mi faros kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'Kaj ilia idaro estos fama inter la popoloj, kaj iliaj posteuloj inter la nacioj; ĉiuj, kiuj ilin vidos, konos ilin, ke ili estas semo benita de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Mi forte ĝojas pri la Eternulo, mia animo ĝojas pri mia Dio; ĉar Li vestis min per vestoj de savo, per mantelo de justeco Li min kovris, kiel fianĉon, kiu sin ornamas per belaĵo, kaj kiel fianĉinon, kiu metas sur sin siajn ornamaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Ĉar kiel la tero elirigas siajn kreskaĵojn kaj kiel ĝardeno elkreskigas siajn semojn, tiel la Sinjoro, la Eternulo, elkreskigos justecon kaj gloron antaŭ ĉiuj popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Pro Cion mi ne silentos, kaj pro Jerusalem mi ne haltos, ĝis ĝia praveco eliĝos kiel brilo kaj ĝia savo kiel brulanta torĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'Kaj la popoloj vidos vian feliĉon, kaj ĉiuj reĝoj vian honoron; kaj oni nomos vin per nomo nova, kiun eldiros la buŝo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Kaj vi estos belega krono en la mano de la Eternulo, kaj reĝa kapornamo en la manplato de via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Oni ne plu nomos vin forlasita, kaj pri via lando oni ne plu diros, ke ĝi estas dezerta; sed oni nomos vin Mia Favorata kaj vian landon Edzinigitino; ĉar la Eternulo vin favoras kaj via lando havos edzon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Kiel junulo prenas por kunvivado junulinon, tiel kunvivos kun vi viaj filoj; kaj kiel fianĉo ĝojas pri la fianĉino, tiel ĝojos pri vi via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Sur viaj muregoj, ho Jerusalem, Mi starigis gardistojn, por ke la tutan tagon kaj la tutan nokton ili ne eksilentu; vi, kiuj memorigas pri la Eternulo, ne faru al vi ripozon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'kaj al Li ne donu ripozon, ĝis Li aranĝos kaj faros Jerusalemon gloro sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'La Eternulo ĵuris per Sia dekstra mano kaj per Sia potenca brako: Mi ne plu donos vian grenon kiel manĝaĵon al viaj malamikoj, kaj fremduloj ne trinkos vian moston, por kiu vi laboris;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'sed ĝiaj rikoltantoj ĝin manĝos, kaj laŭdos la Eternulon; kaj ĝiaj kolektantoj ĝin trinkos en la korto de Mia sanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Pasu, pasu tra la pordegoj, pretigu vojon por la popolo; ebenigu, ebenigu la vojon, liberigu ĝin de ŝtonoj; levu standardon super la popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Jen la Eternulo aŭdigas ĝis la fino de la tero: Diru al la filino de Cion: Jen venas via Savanto; jen Lia rekompenco estas kun Li, kaj Lia repago antaŭ Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Kaj oni nomos ilin la sankta popolo, la liberigitoj de la Eternulo; kaj vin oni nomos urbo multevizitata kaj ne forlasata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Kiu estas tiu, kiu venas el Edom, en ruĝaj vestoj el Bocra? tiu majesta en siaj vestoj, klinanta sin sub la grandeco de sia forto? Tio estas Mi, anoncanta la veron, potenca por helpi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Kial Via drapiraĵo estas ruĝa, kaj Viaj vestoj kiel ĉe tretanto en vinpremejo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'La premilon Mi sola tretis, kaj el la popoloj neniu estis kun Mi; Mi tretis ilin en Mia kolero kaj piedpremis ilin en Mia furiozo; kaj ŝprucis ilia sango sur Mian veston, kaj Mian tutan drapiraĵon Mi malpurigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Ĉar la tago de venĝo estas en Mia koro, kaj la jaro de Miaj liberigotoj venis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Mi rigardis, sed Mi ne trovis helpanton; Mi miris, sed Mi ne trovis subtenanton; tiam helpis Min Mia brako, kaj Mia furiozo Min subtenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'Kaj Mi dispremis popolojn en Mia kolero kaj ebriigis ilin per Mia furiozo, kaj Mi elverŝis sur la teron ilian sangon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Mi proklamos la favorkorecon de la Eternulo, la laŭdon al la Eternulo, pro ĉio, kion la Eternulo faris por ni, kaj pro la multe da bono, kiun Li faris al la domo de Izrael konforme al Sia kompatemeco kaj granda favorkoreco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Kaj Li diris: Ili estas ja Mia popolo, filoj, kiuj ne perfidas; kaj Li fariĝis ilia Savanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'En ĉiuj iliaj suferoj Li ankaŭ suferis, kaj anĝelo de ĉe Li helpis ilin; en Sia amo kaj en Sia kompato Li liberigis ilin; Li prenis ilin sur Sin kaj portis ilin en ĉiuj tempoj de la antikveco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Sed ili ribelis, kaj indignigis Lian sanktan spiriton; tial Li fariĝis ilia malamiko kaj mem batalis kontraŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Kaj Lia popolo rememoris la tempon antikvan de Moseo, dirante: Kie estas Tiu, kiu elkondukis ilin el la maro kune kun la paŝtanto de Liaj ŝafoj? kie estas Tiu, kiu metis internen de ili Sian sanktan spiriton?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'Tiu, kiu gvidis per Sia majesta brako la dekstran manon de Moseo? Tiu, kiu disfendis antaŭ ili la akvon, por fari al Si nomon eternan?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'Tiu, kiu kondukis ilin tra la abismoj kiel ĉevalon tra la dezerto, kaj ili ne falpuŝiĝis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Kiel brutaro malsupreniras en la valon kaj la spirito de la Eternulo donas al ĝi ripozon, tiel Vi kondukis Vian popolon, por fari al Vi gloran nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Rigardu el la ĉielo kaj vidu el Via sankta kaj majesta loĝejo: kie estas Via fervoro kaj potenco? Via granda interno kaj Via kompato fortiriĝis de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Vi estas ja nia patro; Abraham ja ne scias pri ni, kaj Izrael nin ne rekonas; Vi, ho Eternulo, estas nia patro; nia Liberiganto-tia estas de eterne Via nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Kial, ho Eternulo, Vi permesis al ni forvagi de Viaj vojoj, obstinigis nian koron, ke ni Vin ne respektu? Returnu Vin pro Viaj servantoj, pro Viaj heredaj triboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Ne longe posedis Via sankta popolo; niaj malamikoj dispremis per la piedoj Vian sanktejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Ni fariĝis kiel tiuj, kiujn Vi neniam regis, kiuj neniam estis nomataj per Via nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'Ho, se Vi disfendus la ĉielon kaj malsuprenirus, antaŭ Vi ektremus la montoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'aperu kiel fajro, kiu bruligas lignerojn, kiel akvo, kiu bolas de fajro, por konigi Vian nomon al Viaj malamikoj; antaŭ Via vizaĝo ektremu la popoloj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Kiam Vi faris miraklojn, kiujn ni ne atendis, kiam Vi malsupreniris, antaŭ Vi ektremis la montoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Neniam oni tion aŭdis, ne eksciis per la orelo, nek okulo tion vidis, ke iu dio krom Vi tion faras por tiuj, kiuj esperas je li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Vi renkontis tiujn, kiuj ĝoje faris justaĵon kaj memoris Vin sur Viaj vojoj; kvankam Vi koleris, kiam ni pekis, tamen per ili ni ĉiam estis savataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Ni ĉiuj fariĝis kiel malpuruloj, kaj nia tuta virto estas kiel makulita vesto; ni ĉiuj velkas kiel folio, kaj niaj pekoj portas nin kiel vento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Kaj neniu vokas Vian nomon, nek vekiĝas, por forte sin teni je Vi; ĉar Vi kovris Vian vizaĝon antaŭ ni kaj lasas nin perei per niaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Sed nun, ho Eternulo, Vi estas nia Patro; ni estas la argilo, kaj Vi estas nia formanto, kaj ni ĉiuj estas la produkto de Via mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Ne koleru, ho Eternulo, tro forte, kaj ne eterne memoru la kulpon; ho, rigardu, ni ĉiuj estas Via popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Viaj sanktaj urboj fariĝis dezerto, Cion fariĝis dezerto, Jerusalem ruino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Nia sankta kaj belega domo, en kiu niaj patroj Vin laŭdadis, estas forbruligita per fajro, kaj ĉiuj niaj dezirindaĵoj fariĝis ruinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, 'Ĉu malgraŭ ĉio ĉi tio Vi retenos Vin, ho Eternulo? ĉu Vi silentos kaj tiel forte nin premos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Mi estis preta respondi al tiuj, kiuj tion ne petis; Mi estis trovebla por tiuj, kiuj Min ne serĉis; al popolo, kiu ne vokis Mian nomon, Mi diris: Jen Mi estas, jen Mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Ĉiutage Mi etendis Miajn manojn al popolo obstina, al tiuj, kiuj iras vojon malbonan, laŭ siaj intencoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'al popolo, kiu konstante indignigas Min antaŭ Mia vizaĝo; al homoj, kiuj buĉas oferojn en ĝardenoj kaj incensas sur brikoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'al homoj, kiuj sidas inter la tomboj kaj noktas en kavernoj, manĝas viandon de porko, kaj havas abomenindan supon en siaj vazoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'kiuj diras: Iru for, ne alproksimiĝu al mi, ĉar mi estas pli sankta ol vi. Tiuj estas fumo por Mia nazo, fajro brulanta la tutan tagon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Tio estas enskribita antaŭ Mi: Mi ne eksilentos, ĝis Mi repagos; kaj Mi repagos sur ilian bruston');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'viajn kulpojn kaj kune ankaŭ la kulpojn de viaj patroj, diras la Eternulo, kiuj incensis sur la montoj kaj ofendis Min sur la montetoj; kaj Mi remezuros al ili iliajn antaŭajn farojn sur ilian bruston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Tiele diras la Eternulo: Kiel se en vinberaro troviĝas mosto, oni diras: Ne difektu ĝin, ĉar en ĝi estas beno, tiel Mi agos pro Miaj servantoj, ke Mi ne pereigu ĉiujn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Kaj Mi elirigos el Jakob semon kaj el Jehuda heredanton de Miaj montoj, kaj heredos ilin Miaj elektitoj, kaj Miaj servantoj tie loĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'Kaj Ŝaron estos paŝtejo de ŝafoj, kaj la valo Aĥor kuŝejo de bovoj por Mia popolo, kiu serĉas Min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Sed vin, kiuj forlasis la Eternulon, forgesis Mian sanktan monton, aranĝas tablon por la Feliĉo, kaj faras verŝon por la Destino-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'vin Mi destinos por la glavo, kaj ĉiuj vi genuos por la buĉo, pro tio, ke Mi vokis kaj vi ne respondis, Mi parolis kaj vi ne aŭskultis, kaj vi faris malbonon antaŭ Miaj okuloj, kaj elektis tion, kio ne plaĉis al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Tial tiele diras la Sinjoro, la Eternulo: Jen Miaj servantoj manĝos, kaj vi malsatos; Miaj servantoj trinkos, kaj vi soifos; Miaj servantoj ĝojos, kaj vi hontos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Miaj servantoj kantos pro kora gajeco, kaj vi krios pro kora doloro kaj ploros pro aflikto de spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'Kaj vi donos vian nomon al Miaj elektitoj por malbeno, kaj la Sinjoro, la Eternulo, vin mortigos; sed Siajn servantojn Li nomos per alia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'Kiu sin benos sur la tero, tiu benos sin per la Dio vera; kaj kiu ĵuros sur la tero, tiu ĵuros per la Dio vera; ĉar forgesitaj estos la antaŭaj suferoj kaj forkaŝiĝos antaŭ Miaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Ĉar jen Mi kreos novan ĉielon kaj novan teron; kaj la antaŭaĵo ne estos rememorigata, kaj oni ne pensos pri ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Kaj vi nur ĝojos kaj estos gajaj ĉiam pri tio, kion Mi kreos; ĉar jen Mi kreos Jerusalemon por ĝojo kaj ĝian popolon por gajeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'Kaj Mi ĝojos pri Jerusalem, kaj Mi estos gaja pri Mia popolo; kaj oni ne plu aŭdos en ĝi voĉon de ploro, nek voĉon de plendo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Ne plu estos tie infano aŭ maljunulo, kiu ne atingus la plenecon de siaj tagoj; ĉar junulo mortos en la aĝo de cent jaroj, kaj pekulo estos malbenata per aĝo centjara.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'Ili konstruos domojn kaj loĝos en ili; ili plantos vinberĝardenojn kaj manĝos iliajn fruktojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Ili ne konstruos, ke alia loĝu; ili ne plantos, ke alia manĝu; ĉar kiel la tagoj de arbo estas la tagoj de Mia popolo, kaj Miaj elektitoj eluzos la produktojn de siaj manoj ĝis plena malnoviĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Ili ne laboros vane kaj ne naskos por pereo; ĉar ili estos semo de benitoj de la Eternulo, kaj iliaj posteuloj kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'Kaj estos tiel, ke antaŭ ol ili vokos, Mi respondos; ili estos ankoraŭ parolantaj, kaj Mi jam aŭdos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Lupo kaj ŝafido paŝtiĝos kune, leono simile al bovo manĝos pajlon, kaj manĝaĵo de serpento estos polvo. Ili ne faros malbonon nek difekton sur Mia tuta sankta monto, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Tiele diras la Eternulo: La ĉielo estas Mia trono, kaj la tero estas Mia piedbenketo; kie do estos la domo, kiun vi konstruos por Mi? kaj kie estos la loko por Mia ripozo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Ĉion tion faris ja Mia mano, kaj tiel ĉio fariĝis, diras la Eternulo. Nur tion Mi rigardas: humilulon kaj spirite-afliktiton, kiu respektegas Mian vorton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Unu buĉas bovon, alia mortigas homon; unu buĉoferas ŝafidon, alia rompas la kolon al hundo; unu alportas farunoferon, alia sangon de porko; unu incensas olibanon, alia preĝas al idolo. Sed kiel ili elektis al si siajn vojojn kaj ilia animo ĝuas ilian abomenindaĵon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'tiel ankaŭ Mi elektos por ili petolantojn kaj venigos sur ilin tion, kion ili timis; ĉar Mi vokis, kaj neniu respondis; Mi parolis, kaj ili ne aŭskultis; sed ili faris malbonon antaŭ Miaj okuloj, kaj elektis tion, kio ne plaĉis al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Aŭskultu la parolon de la Eternulo, vi, kiuj respektegas Lian parolon: Viaj fratoj, kiuj vin malamas kaj forpuŝas pro Mia nomo, diras: La Eternulo montru Sian gloron, por ke ni vidu vian ĝojon! Sed ili estos hontigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Aŭdiĝas brua voĉo el la urbo, voĉo el la templo, voĉo de la Eternulo, kiu repagas merititaĵon al Siaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Antaŭ ol ŝi eksentis dolorojn, ŝi naskis; antaŭ ol venis al ŝi la akuŝiĝaj suferoj, ŝi elfaligis filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Kiu aŭdis ion similan? kiu vidis ion similan? ĉu la tero naskas en unu tago? ĉu naskiĝas popolo per unu fojo, kiel, apenaŭ eksentinte naskajn dolorojn, tuj naskis Cion siajn filojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Ĉu Mi, malfermante la uteron, ne lasus naski? diras la Eternulo. Ĉu Mi, kiu pretigis la naskon, mem ĝin haltigus? diras via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Ĝoju kun Jerusalem kaj estu gajaj pri ĝi ĉiuj ĝiaj amantoj; forte ĝoju pri ĝi ĉiuj, kiuj ploris pri ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'Suĉu kaj satiĝu el la brusto de ĝiaj konsoloj; suĉu kaj ĝuu la abundon de ĝia gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Ĉar tiele diras la Eternulo: Jen Mi fluigos sur ĝin pacon kiel riveron, kaj la riĉaĵon de la popoloj kiel disverŝiĝintan torenton, por ke vi suĉu; sur la brakoj vi estos portataj, kaj sur la genuoj vi estos dorlotataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Kiel homon, kiun konsolas lia patrino, tiel Mi vin konsolos; kaj en Jerusalem vi estos konsolataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Kaj vi vidos, kaj ĝojos via koro, kaj viaj ostoj vigliĝos kiel freŝa verdaĵo; kaj la mano de la Eternulo fariĝos konata al Liaj servantoj, kaj Lia kolero al Liaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Ĉar jen la Eternulo venos en fajro, kaj Lia ĉaro estos kiel ventego, por elverŝi en ardo Sian koleron kaj en flama fajro Sian indignon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Ĉar per fajro kaj glavo la Eternulo faros juĝon super ĉiu karno; kaj multaj estos la frapitoj de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Tiuj, kiuj sanktigas kaj purigas sin por la ĝardenoj, starante post unu en la mezo, kiuj manĝas viandon de porko kaj abomenindaĵon kaj musojn, ĉiuj kune estos ekstermitaj, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Kaj por Mi, pro iliaj faroj kaj intencoj, venis la tempo kolekti ĉiujn popolojn kaj gentojn, por ke ili venu kaj vidu Mian gloron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'Kaj Mi faros sur ili signon, kaj la saviĝintojn el ili Mi sendos al la popoloj Tarŝiŝ, Pul, kaj Lud, al la streĉantoj de pafarkoj, al Tubal kaj Javan, sur la malproksimajn insulojn, kiuj ne aŭdis la famon pri Mi kaj ne vidis Mian gloron; kaj ili proklamos Mian gloron inter la popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'Kaj ili venigos ĉiujn viajn fratojn el inter ĉiuj popoloj kiel donacon al la Eternulo, sur ĉevaloj kaj ĉaroj, en veturiloj, kaj sur muloj kaj kameloj, sur Mian sanktan monton en Jerusalemon, diras la Eternulo, simile al tio, kiel la Izraelidoj alportadis la donacojn en la domon de la Eternulo en pura vazo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'Kaj el ili Mi prenos al Mi pastrojn kaj Levidojn, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Ĉar kiel la nova ĉielo kaj la nova tero, kiujn Mi kreos, staros antaŭ Mi, diras la Eternulo, tiel staros via idaro kaj via nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'Kaj regule en ĉiu monatkomenco kaj en ĉiu sabato venos ĉiu karno, por adorkliniĝi antaŭ Mi, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'Kaj ili eliros kaj vidos la kadavrojn de la homoj, kiuj malbonagis kontraŭ Mi; ĉar ilia vermo ne mortos kaj ilia fajro ne estingiĝos, kaj ili estos abomenindaĵo por ĉiu karno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Paroloj de Jeremia, filo de Ĥilkija, el la pastroj, kiuj estis en Anatot, en la lando de Benjamen;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'al kiu aperis la vorto de la Eternulo en la tempo de Joŝija, filo de Amon, reĝo de Judujo, en la dek-tria jaro de lia reĝado,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'kaj poste en la tempo de Jehojakim, filo de Joŝija, reĝo de Judujo, ĝis la fino de la dek-unua jaro de Cidkija, filo de Joŝija, reĝo de Judujo, ĝis la forkonduko de la Jerusalemanoj en la kvina monato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Aperis al mi la vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Antaŭ ol Mi formis vin en la utero, Mi vin konis, kaj antaŭ ol vi eliris el la ventro, Mi vin sanktigis, Mi faris vin profeto por la popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Mi diris: Ho ve, Sinjoro, ho Eternulo! mi ne povoscias paroli, ĉar mi estas juna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Sed la Eternulo diris al mi: Ne diru, ke vi estas juna; sed ĉien, kien Mi sendos vin, iru, kaj ĉion, kion Mi ordonos al vi, parolu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Ne timu ilin; ĉar Mi estas kun vi, por savi vin, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Kaj la Eternulo etendis Sian manon kaj ektuŝis mian buŝon, kaj la Eternulo diris al mi: Jen Mi enmetis Miajn vortojn en vian buŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Vidu, Mi starigas vin hodiaŭ super la popoloj kaj super la regnoj, por elŝiri, rompi, pereigi, kaj detrui, por konstrui kaj planti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Kaj aperis al mi la vorto de la Eternulo, dirante: Kion vi vidas, Jeremia? Kaj mi diris: Mi vidas bastonon maldormantan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Kaj la Eternulo diris al mi: Vi vidis bone; ĉar Mi maldormos pri Mia vorto, por plenumi ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Kaj duafoje aperis al mi la vorto de la Eternulo, dirante: Kion vi vidas? Kaj mi diris: Mi vidas flame bolantan poton, kaj ĝi rigardas de norde.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Kaj la Eternulo diris al mi: De norde venos la malfeliĉo sur ĉiujn loĝantojn de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Ĉar jen Mi alvokos ĉiujn gentojn de la nordaj regnoj, diras la Eternulo, kaj ili venos kaj starigos ĉiu sian tronon antaŭ la pordegoj de Jerusalem kaj ĉirkaŭ ĝiaj muregoj kaj antaŭ ĉiuj urboj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'Kaj Mi eldiros Mian verdikton pri ili pro ĉiuj iliaj malbonagoj, pro tio, ke ili forlasis Min kaj incensis al aliaj dioj kaj adorkliniĝis antaŭ la faritaĵo de siaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Kaj vi zonu viajn lumbojn, leviĝu, kaj diru al ili ĉion, kion Mi ordonas al vi; ne tremu antaŭ ili, por ke Mi ne tremigu vin antaŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Jen Mi faras vin hodiaŭ fortikigita urbo, fera kolono, kaj kupraj muroj en la tuta lando, kontraŭ la reĝoj de Judujo, kontraŭ ĝiaj princoj, kontraŭ ĝiaj pastroj, kaj kontraŭ la popolo de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Ili batalos kontraŭ vi, sed ne venkos vin; ĉar Mi estas kun vi, diras la Eternulo, por savi vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Kaj aperis al mi la vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Iru kaj prediku al la oreloj de Jerusalem, dirante: Tiele diras la Eternulo: Mi memoras la piecon de via juneco, la amon de via fianĉineco, kiam vi sekvis Min en la dezerto, en lando ne prisemita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Izrael tiam estis sanktaĵo de la Eternulo, Lia unua frukto; ĉiuj, kiuj manĝis ĝin, estis kondamnitaj, malbono venis sur ilin, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Aŭskultu la vorton de la Eternulo, ho domo de Jakob kaj ĉiuj familioj de la domo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Tiele diras la Eternulo: Kian maljustaĵon viaj patroj trovis en Mi, ke ili malproksimiĝis de Mi kaj sekvis vantaĵon kaj mem vantiĝis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Kaj ili ne diris: Kie estas la Eternulo, kiu elkondukis nin el la Egipta lando, kiu kondukis nin tra dezerto, tra lando de stepoj kaj kavoj, tra lando seka kaj malluma, tra lando, kiun neniu trapasis kaj kie neniu loĝis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Kaj Mi venigis vin en landon fruktodonan, por ke vi manĝu ĝiajn fruktojn kaj bonaĵojn; sed vi venis kaj malpurigis Mian landon, kaj Mian heredaĵon vi faris abomenindaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'La pastroj ne diris: Kie estas la Eternulo? la leĝokompetentuloj ne atentis Min, la paŝtistoj perfidis Min, la profetoj profetis per Baal kaj sekvis idolojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Pro tio Mi ankoraŭ procesos kun vi, diras la Eternulo, kaj kun la filoj de viaj filoj Mi procesos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Ĉar iru sur la insulojn de la Kitidoj kaj rigardu, sendu al la Kedaridoj kaj esploru bone kaj rigardu, ĉu tie estas farita io simila.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Ĉu ia popolo ŝanĝis siajn diojn, kvankam ili ne estas dioj? sed Mia popolo ŝanĝis sian gloron je idoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Miregu pri tio, ho ĉielo, sentu teruron kaj forte konsterniĝu, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Ĉar du malbonagojn faris Mia popolo: Min ili forlasis, la fonton de viva akvo, por elhaki al si putojn, truhavajn putojn, kiuj ne povas teni akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Ĉu Izrael estas sklavo, aŭ ĉu li estas infano de la domo? kial li fariĝis rabitaĵo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Kontraŭ li blekegis leonidoj, forte kriis, kaj ili faris lian landon dezerto; liaj urboj estas bruligitaj, kaj neniu loĝas en ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Eĉ la filoj de Nof kaj de Taĥpanĥes frakasis vian verton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Vi jam mem tion faris al vi, ĉar vi forlasis la Eternulon, vian Dion, en la tempo, kiam Li gvidis vin sur la vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'Kaj nun por kio vi bezonas la vojon al Egiptujo? ĉu por trinki la akvon de Nilo? Kaj por kio vi bezonas la vojon al Asirio? ĉu por trinki la akvon de Eŭfrato?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Via malboneco vin punos, kaj viaj malbonagoj faros al vi riproĉojn, por ke vi sciu kaj vidu, kiel malbone kaj maldolĉe estas, ke vi forlasis la Eternulon, vian Dion, kaj ne timas Min, diras la Sinjoro, la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Ĉar antaŭ longe vi rompis vian jugon kaj disŝiris viajn ŝnurojn, kaj vi diris: Mi ne plu malbonagos; tamen sur ĉiu alta loko kaj sub ĉiu verda arbo vi kuŝigis vin kiel malĉastistino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Mi plantis vin kiel bonegan vinberbranĉon, portontan plej ĝustajn fruktojn; kiel do vi ŝanĝiĝis ĉe Mi je vinberbranĉo sovaĝa?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Se vi eĉ lavus vin per natro kaj uzus por vi multe da sapo, via malvirto tamen restos makula antaŭ Mi, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Kiel vi povas diri: Mi ne malpurigis min, mi ne sekvis Baalojn? rigardu vian agadon en la valo, pripensu, kion vi faris, juna kamelino rapidpieda, petolanta sur sia vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'Kiu povas reteni sovaĝan azeninon, alkutimiĝintan al la dezerto, kiam ĝi sopiregas de sia volupta celado? ĉiuj, kiuj ĝin serĉas, ne bezonas laciĝi, en la sama stato ili ĝin trovos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Detenu viajn piedojn de nudeco kaj vian gorĝon de soifo. Sed vi diras: Ne, mi ne volas, ĉar mi amas fremdulojn kaj mi sekvos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Kiel ŝtelinto hontas, kiam oni lin trovas, tiel estas hontigita la domo de Izrael, ili, iliaj reĝoj, iliaj princoj, iliaj pastroj, kaj iliaj profetoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'kiuj diras al ligno: Vi estas mia patro; kaj al ŝtono: Vi min naskis. Ili turnis al Mi la nukon, ne la vizaĝon; sed en la tempo de sia malfeliĉo ili diras: Leviĝu, kaj savu nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Kie do estas viaj dioj, kiujn vi faris al vi? ili leviĝu, se ili povas vin savi en la tempo de via malfeliĉo; ĉar kiom da urboj, tiom da dioj vi havas, ho Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Kial vi volas disputi kun Mi? vi ĉiuj defalis de Mi, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'Vane Mi frapis viajn infanojn, ili ne akceptis la moralinstruon; via glavo ekstermis viajn profetojn, kiel furioza leono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'Ho generacio, atentu la vorton de la Eternulo! Ĉu Mi estis por Izrael dezerto aŭ lando malluma? Kial do Mia popolo diras: Ni mem estas sinjoroj, ni ne plu iros al Vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Ĉu virgulino forgesas sian ornamon, aŭ fianĉino sian ĉirkaŭligon? sed Mia popolo Min forgesis jam de tempo nekalkulebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Kiel vi beligas vian vojon, por serĉi amon! al agoj malbonaj vi ja alkutimiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Eĉ sur viaj baskoj oni trovas sangon de malriĉuloj, senkulpuloj; ne en foskavoj Mi tion trovis, sed sur ĉiuj tiuj lokoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'Vi diras: Mi estas senkulpa, Lia kolero deturnu sin de mi. Sed Mi postulos juĝon inter ni pro tio, ke vi diras: Mi ne pekis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Kiel malestiminda vi fariĝis, ŝanĝante vian vojon! De Egiptujo vi estos tiel same hontigita, kiel vi estas hontigita de Asirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'Ankaŭ el tie vi eliros kun la manoj sur la kapo, ĉar la Eternulo forpuŝis viajn esperojn kaj vi ne sukcesos kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Oni diras: Se viro forigas sian edzinon, kaj ŝi foriras de li kaj edziniĝas kun alia viro, ĉu li tiam povas reveni al ŝi denove? ĉu ne malpuriĝus per tio tiu lando? Kaj vi malĉastis kun multaj amantoj; tamen revenu al Mi, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Levu viajn okulojn al la altaĵoj, kaj rigardu; kie vi ne adultis? Ĉe la vojoj vi sidis por ili, kiel Arabo en la dezerto, kaj vi malpurigis la landon per via malĉastado kaj malbonagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Pro tio estas retenitaj la pluvoj, kaj la printempa pluvo ne aperis; sed vi havas frunton de malĉastistino, vi ne plu volas honti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Tamen vi kriis al Mi: Mia patro, Vi, gvidinto de mia juneco!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'ĉu Vi koleros eterne kaj konservos la koleron por ĉiam? Tiel vi parolas, kaj tamen vi faras malbonon kaj kontraŭstaras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'La Eternulo diris al mi en la tempo de la reĝo Joŝija: Ĉu vi vidis, kion faris la defalinta Izrael? ŝi iris sur ĉiun altan monton kaj sub ĉiun verdan arbon kaj tie malĉastis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'Kaj post kiam ŝi faris ĉion ĉi tion, Mi diris: Revenu al Mi; sed ŝi ne revenis. Kaj tion vidis ŝia perfidema fratino Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'Mi vidis ĉiujn adultaĵojn de la defalinta Izrael, kaj Mi forpelis ŝin kaj donis al ŝi eksedzigan leteron; tamen ne ektimis ŝia perfidema fratino Judujo, sed ŝi iris kaj ankaŭ malĉastis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Kaj de la bruo de ŝia malĉastado malpuriĝis la lando, kaj ŝi adultis kun ŝtono kaj kun ligno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'Kaj malgraŭ ĉio ŝia perfidema fratino Judujo revenis al Mi ne per sia tuta koro, sed nur hipokrite, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Kaj la Eternulo diris al mi: La defalinta Izrael estas piulino en komparo kun la perfidema Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Iru, kaj proklamu ĉi tiujn vortojn norden, kaj diru: Revenu, defalinta Izrael, diras la Eternulo; Mi ne forturnos de vi Mian vizaĝon, ĉar Mi estas kompatema, diras la Eternulo, Mi ne koleros eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Nur konfesu vian kulpon, ke vi pekis kontraŭ la Eternulo, via Dio, kaj kuradis al aliaj sub ĉiun verdan arbon, kaj Mian voĉon vi ne aŭskultis, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Revenu, defalintaj infanoj, diras la Eternulo, ĉar Mi estas via sinjoro, kaj Mi prenos vin po unu el urbo kaj po du el tribo kaj venigos vin en Cionon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'Kaj Mi donos al vi paŝtistojn laŭ Mia koro, kiuj paŝtos vin kun sciado kaj saĝeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'Kaj kiam vi kreskos kaj multiĝos en la lando en tiu tempo, diras la Eternulo, oni ne plu parolos pri la kesto de interligo de la Eternulo; ĝi ne venos en la koron, oni ne rememoros ĝin, oni ne serĉos ĝin, oni ne faros ĝin denove.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'En tiu tempo oni nomos Jerusalemon trono de la Eternulo, kaj tie kolektiĝos ĉiuj popoloj en la nomo de la Eternulo, en Jerusalem, kaj ili ne plu sekvos la logojn de sia malbona koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'En tiu tempo la domo de Jehuda iros al la domo de Izrael, kaj ili kune iros el la norda lando en la landon, kiun Mi donis kiel heredaĵon al viaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Mi diris: Kiamaniere Mi alkalkulos vin al la filoj, kaj donos al vi la ĉarman landon, la plej belan heredaĵon inter multe da popoloj? Kaj Mi diris: Vi nomos Min patro, kaj vi ne fordeturnos vin de Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Sed kiel virino, kiu perfidis sian amanton, tiel vi perfidis Min, ho domo de Izrael, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Voĉo estas aŭdata sur la altaĵoj, plenda plorado de la filoj de Izrael, ĉar ili malvirtigis sian vojon, forgesis la Eternulon, sian Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Revenu, defalintaj infanoj; Mi resanigos vian defalon. Jen ni venis al Vi, ĉar Vi estas la Eternulo, nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Vere, mensogo estis en la altaĵoj, en la multo da montoj; nur en la Eternulo, nia Dio, estas la savo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'La hontindaĵo formanĝis la penadon de niaj patroj de post nia juneco: iliajn ŝafojn, iliajn bovojn, iliajn filojn, kaj iliajn filinojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Ni kuŝu en nia abomenindaĵo, kaj nia hontindaĵo nin kovru; ĉar kontraŭ la Eternulo, nia Dio, ni pekis, ni kaj niaj patroj, de nia juneco ĝis la nuna tago, kaj ni ne aŭskultis la voĉon de la Eternulo, nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Se vi volas rekonverti vin, ho Izrael, diras la Eternulo, rekonvertu vin al Mi; kaj se vi forigos viajn abomenindaĵojn de antaŭ Mia vizaĝo, kaj ne plu vagados,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'kaj se vi en vero, bonordo, kaj pieco ĵuros: Kiel la Eternulo vivas, tiam ankaŭ la popoloj benos sin per Li kaj gloros sin per Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Ĉar tiele diras la Eternulo al la viroj de Judujo kaj al Jerusalem: Plugu al vi novan plugokampon, kaj ne semu inter dornaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Cirkumcidu vin al la Eternulo kaj forigu la prepucion de via koro, ho viroj de Judujo kaj loĝantoj de Jerusalem, por ke Mia kolero ne eliru kiel fajro kaj ne brulu pro viaj malbonagoj tiel, ke neniu ĝin estingos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Proklamu en Judujo, aŭdigu en Jerusalem, prediku kaj trumpetu en la lando; voku per plena voĉo, kaj diru: Kolektiĝu, kaj ni iru en la fortikigitajn urbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Levu standardon en Cion, kuru, ne haltu; ĉar malfeliĉon Mi venigas de nordo kaj grandan pereon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Leono leviĝas el sia densejo, kaj pereiganto de popoloj elmoviĝas kaj eliras el sia loko, por fari vian landon dezerto; viaj urboj estos detruitaj, kaj neniu loĝos en ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Pro tio zonu vin per sakaĵo, ploru kaj ĝemu, ĉar la flama kolero de la Eternulo ne foriĝas de ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'En tiu tago, diras la Eternulo, senviviĝos la koro de la reĝo kaj la koro de la princoj, konsterniĝos la pastroj, kaj la profetoj konfuziĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Kaj mi diris: Ho Sinjoro, ho Eternulo! ĉu Vi erarigis ĉi tiun popolon kaj Jerusalemon, dirinte: Vi havos pacon-kaj dume la glavo atingis jam la animon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'En tiu tempo oni diros al tiu popolo kaj al Jerusalem: Seka vento de la altaĵoj en la dezerto venas sur la vojon de la filino de Mia popolo, ne por ventumi kaj ne por purigi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'vento pli forta ol ili venos al Mi; tiam Mi diros Mian verdikton kontraŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Jen ĝi leviĝas kiel nuboj, kaj ĝiaj ĉaroj estas kiel ventegoj, ĝiaj ĉevaloj estas pli rapidaj ol agloj; ve al ni! ni estos ruinigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Lavu de la malbono vian koron, ho Jerusalem, por ke vi saviĝu; ĝis kiam loĝos en vi viaj malbonaj pensoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Venas voko el la regiono de Dan, kaj malbona sciigo de la monto de Efraim:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Sciigu al la popoloj, aŭdigu pri Jerusalem, ke sieĝontoj venas el lando malproksima kaj sonigas sian voĉon kontraŭ la urboj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Kiel kampogardistoj ili ĉirkaŭas ĝin, ĉar ĝi ribelis kontraŭ Mi, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Via konduto kaj viaj faroj kaŭzis tion al vi, tiu via malboneco, ĉar ĝi estas maldolĉa, ĉar ĝi penetris ĝis via koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'Mia internaĵo, mia internaĵo min doloras, batas mia koro, mi ne povas silenti; ĉar vi, mia animo, aŭdis sonon de korno, trumpetadon de batalo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Estas proklamata malfeliĉo post malfeliĉo, ĉar la tuta lando estas ruinigata, subite estas detruataj miaj domoj, momente miaj tendoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Kiel longe ankoraŭ mi vidos standardon, aŭdos sonadon de korno?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Ĉar Mia popolo estas freneza, Min ili ne rekonas; ili estas malsaĝaj infanoj, ili ne komprenas; saĝaj ili estas por fari malbonon, sed fari bonon ili ne povoscias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Mi rigardas la teron, kaj jen ĝi estas malplena kaj dezerta; la ĉielon, kaj jen ĝi estas senluma.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Mi rigardas la montojn-ili tremas, kaj ĉiuj montetoj ŝanceliĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Mi rigardas-troviĝas neniu homo, kaj ĉiuj birdoj de la ĉielo disflugis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Mi rigardas-la fruktoriĉa lando fariĝis dezerto, kaj ĉiuj ĝiaj urboj estas detruitaj de la Eternulo, de la flamo de Lia kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Ĉar tiele diras la Eternulo: Dezertigita estos la tuta lando, sed plenan ekstermon Mi ne faros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Pro tio la tero ploros kaj la ĉielo supre malĝojos; ĉar Mi eldiris Mian decidon, kaj Mi ne bedaŭras, kaj Mi ne reprenos ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Pro la bruo de la rajdantoj kaj pafantoj forkuras la tuta urbo; oni kuras en densajn arbarojn, grimpas sur rokojn; ĉiuj urboj malpleniĝis, kaj neniu en ili loĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'Kaj vi, dezertigita, kion vi faros? Eĉ se vi metos sur vin purpuron, se vi ornamos vin per oraj ornamoj, se vi ruĝe kolorigos vian vizaĝon, vi ornamos vin vane: viaj amantoj vin malestimos, ili volos vin mortigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Ĉar Mi aŭdas krion kiel de naskantino, ĝemegadon kiel de virino naskanta la unuan infanon, krion de la filino de Cion; ŝi ĝemas, kaj etendas siajn manojn: Ho ve al mi! ĉar mia animo pereas de la mortigantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Trairu la stratojn de Jerusalem kaj rigardu, esploru kaj serĉu sur ĝiaj palacoj, ĉu vi trovos homon, kiu agas juste, kiu serĉas la veron-tiam Mi pardonos al ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Eĉ se ili diras: Mi ĵuras per la Eternulo-ili tamen ĵuras mensoge.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Ho Eternulo, Viaj okuloj rigardas ja la fidelecon; Vi batas ilin, sed ili ne sentas doloron; Vi preskaŭ pereigas ilin, sed ili ne volas preni moralinstruon; sian vizaĝon ili faris pli malmola ol roko, ili ne volas konvertiĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Mi diris al mi: Eble ili estas malriĉuloj, malkleruloj, ili ne konas la vojon de la Eternulo, la leĝojn de sia Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'mi iros al la eminentuloj, kaj mi parolos kun ili: ili ja konas la vojon de la Eternulo, la leĝojn de sia Dio; sed ankaŭ ili ĉiuj kune rompis la jugon, disŝiris la ŝnurojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Pro tio mortigos ilin leono el la arbaro, lupo el la stepo ilin prirabos, leopardo atendos ilin apud iliaj urboj; ĉiu, kiu eliros el tie, estos disŝirata. Ĉar multaj fariĝis iliaj krimoj, fortaj fariĝis iliaj perfidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Kiel Mi tion pardonus al vi? viaj filoj Min forlasis kaj ĵuris per ne- dioj. Mi ĵurigis ilin, sed ili adultas kaj iras amase en malĉastejojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Ili fariĝis kiel voluptemaj pasiaj ĉevaloj; ĉiu blekas al la edzino de sia proksimulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Ĉu Mi povas ne puni pro tio? diras la Eternulo; kaj ĉu al tia popolo Mia animo povas ne venĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Iru sur ĝiajn muregojn kaj detruu ilin, tamen ne tute ekstermu; forigu ĝiajn branĉojn, ĉar ne por la Eternulo ili estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Ĉar forte perfidis Min la domo de Izrael kaj la domo de Jehuda, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Ili neis la ekzistadon de la Eternulo, kaj diris: Li ne ekzistas, kaj ne venos sur nin malbono, kaj glavon kaj malsaton ni ne vidos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'Kaj la profetoj estas kiel vento, ne troviĝas en ili la vorto de Dio; tiel fariĝu al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Pro tio tiele diras la Eternulo, Dio Cebaot: Pro tio, ke vi parolas tiajn vortojn, jen Mi metos Miajn vortojn en vian buŝon kiel fajron, kaj ĉi tiu popolo estos kiel ligno, kiun ĝi konsumos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Jen Mi venigos sur vin, sur la domon de Izrael, popolon de malproksime, diras la Eternulo, popolon fortan, popolon antikvan, popolon, kies lingvon vi ne scias; kaj vi ne komprenos, kion ĝi parolas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Ĝia sagujo estas kiel malfermita tombo; ĉiuj ili estas herooj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'Ĝi formanĝos vian rikolton kaj vian panon, ekstermos viajn filojn kaj viajn filinojn, formanĝos viajn ŝafojn kaj viajn bovojn, formanĝos viajn vinberojn kaj viajn figojn, detruos per glavo viajn fortikigitajn urbojn, kiujn vi fidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Sed eĉ en tiu tempo, diras la Eternulo, Mi ne pereigos vin tute.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Kaj kiam oni demandos: Pro kio la Eternulo, nia Dio, faras al ni ĉion ĉi tion? tiam diru al ili: Kiel vi forlasis Min kaj servas al fremdaj dioj en via lando, tiel vi servos al fremduloj en lando, kiu ne apartenas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Anoncu tion en la domo de Jakob kaj aŭdigu en Judujo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Aŭskultu ĉi tion, ho popolo malsaĝa kaj senkora, kiu havas okulojn, sed ne vidas, havas orelojn, sed ne aŭdas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Ĉu vi ne timas Min? diras la Eternulo; ĉu vi ne tremas antaŭ Mi, kiu faris sablon limo por la maro, aranĝo eterna, kiun ĝi ne transpaŝas? kiom ajn ĝi skuiĝas, ĝi nenion povas fari; kiom ajn bruas ĝiaj ondoj, ili ne povas ĝin transpaŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Sed ĉi tiu popolo havas koron defaleman kaj neobeeman, ili defalis kaj foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'Kaj ili ne diris en sia koro: Ni timu la Eternulon, nian Dion, kiu donas al ni pluvon frusezonan kaj malfrusezonan en ĝia tempo, kiu gardas por ni la semajnojn, destinitajn por la rikolto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Viaj malbonagoj tion forklinis, kaj viaj pekoj forigis de vi la bonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Ĉar inter Mia popolo troviĝas malvirtuloj, kiuj faras insidojn, starigas pereigajn kaptilojn, kaptas la homojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Kiel birdejo estas plena de birdoj, tiel iliaj domoj estas plenaj de trompakiraĵoj; tial ili fariĝis grandaj kaj riĉaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Ili fariĝis grasaj, ili fariĝis dikaj; ili faris malbonajn agojn; juĝon ili ne faras, juĝon pri orfo, sed ili ĝuas la vivon; justecon al malriĉuloj ili ne faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Ĉu Mi povas lasi tion sen puno? diras la Eternulo; ĉu al tia popolo Mia animo ne venĝos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Io konsterna kaj terura fariĝis en la lando:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'la profetoj profetas malveraĵon, kaj la pastroj regas per ili; kaj al mia popolo tio plaĉas. Kaj kion vi faros en la estonteco?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Kuru rapide, ho filoj de Benjamen, el Jerusalem, kaj en Tekoa sonigu la trumpeton kaj super Bet-Kerem faru signalon; ĉar de nordo aperas malbono kaj granda pereo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Al bela kaj delikata virino Mi similigis la filinon de Cion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Al ŝi venos paŝtistoj kun siaj brutaroj, ĉirkaŭ ŝi ili starigos tendojn, kaj ĉiu paŝtos sur sia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Aranĝu militon kontraŭ ŝi; leviĝu, ni iru en tagmezo. Ho ve al ni! ĉar baldaŭ vesperiĝos, etendiĝas la ombroj de vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Leviĝu, ni iru nokte, kaj ni detruu ŝiajn palacojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Ĉar tiele diras la Eternulo Cebaot: Haku ŝiajn arbojn kaj aranĝu remparon ĉirkaŭ Jerusalem; ĉi tiun urbon oni devas puni, ĝi estas tute plena de malbonagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Kiel fonto elfluigas sian akvon, tiel ĝi elfluigas el si malbonon; nur perforteco kaj rabado estas aŭdataj en ĝi, antaŭ Mi estas ĉiam turmentado kaj batado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Prudentiĝu, ho Jerusalem, por ke ne foriĝu de vi Mia animo, por ke Mi ne faru vin dezerto, lando ne loĝata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Tiele diras la Eternulo Cebaot: Oni kolektu la restaĵon de Izrael kiel restaĵon de vinberoj; eltiru kaj retiru vian manon, kiel ŝirkolektanto de vinberoj super la korboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Kun kiu Mi parolu, kiun Mi admonu, ke oni Min aŭskultu? ilia orelo ne estas cirkumcidita, kaj ili ne povas aŭdi. Jen la vorton de la Eternulo ili malŝatas; ili ne deziras ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Tial Mi pleniĝis de kolero de la Eternulo, Mi ne plu povas toleri; elverŝu ĝin sur la infanojn sur la strato kaj sur la interkonsiliĝon de la junuloj; kiel viro, tiel ankaŭ virino estos kaptita, maljunulo kaj profundaĝulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'Iliaj domoj transiros al aliuloj, ankaŭ la kampoj kaj la edzinoj; ĉar Mi etendos Mian manon sur la loĝantojn de la lando, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Ĉar ĉiuj, de la malgrandaj ĝis la grandaj, estas profitavidaj; kaj de la profetoj ĝis la pastroj ĉiuj faras malhonestaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'Kaj la vundojn de Mia popolo ili kuracas per facilanimigo, dirante, ke ĉio estas en bona stato, kvankam ne estas bona stato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Ĉu ili hontas, ke ili faras abomenindaĵon? ili tute ne hontas, ili eĉ ne povoscias ruĝiĝi; tial ili falos inter la falantoj, ili renversiĝos, kiam Mi vizitos ilin, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Tiele diras la Eternulo: Stariĝu sur la vojoj kaj rigardu, kaj demandu pri la vojoj antikvaj, kia estas la bona vojo, kaj iru laŭ ĝi kaj trovu ripozon por via animo. Sed ili diris: Ni ne iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'Kaj Mi starigis gardistojn super vi, dirante: Atentu la sonadon de la trumpeto. Sed ili diris: Ni ne atentos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Tial aŭdu, ho popoloj, kaj sciu, ho komunumoj, kio fariĝas ĉe ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Aŭskultu, ho tero! jen Mi venigas malfeliĉon sur ĉi tiun popolon, frukton de iliaj pensoj; ĉar ili ne atentis Miajn vortojn, kaj Mian instruon ili forpuŝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Por kio Mi bezonas la olibanon venantan el Ŝeba, kaj la bonodoran kanon el malproksima lando? viaj bruloferoj ne plaĉas al Mi, kaj viaj buĉoferoj ne estas agrablaj al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Tial tiele diras la Eternulo: Jen Mi metos antaŭ ĉi tiu popolo falpuŝilon, kaj sur ĝi falpuŝiĝos kune patroj kaj filoj, najbaro kaj amiko pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Tiele diras la Eternulo: Jen venos popolo el norda lando, kaj granda nacio leviĝos de la randoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Pafarkon kaj lancon ili tenas forte; kruelaj ili estas kaj senkompataj; ilia voĉo bruas kiel maro; sur ĉevaloj ili rajdas, armite por la batalo kiel unu homo, kontraŭ vin, ho filino de Cion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Kiam ni aŭdis pri ili, malleviĝis niaj manoj, teruro kaj doloro nin atakis kiel naskantinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Ne eliru sur la kampon, ne iru sur la vojon, ĉar la glavo de la malamiko vekas teruron ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'Ho filino de Mia popolo! zonu vin per sakaĵo, rulu vin en cindro, funebru kiel pro sola filo, ploru maldolĉe, ĉar subite venos sur nin la pereiganto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Kiel esploranton Mi starigis vin inter Mia popolo, fortan, ke vi ekkonu kaj esploru ilian vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Ĉiuj ili estas obstinaj defalintoj, kalumniantoj, kupro kaj fero; ĉiuj ili estas degenerintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'La blovilo bruldifektiĝis, la plumbo malaperis en la fajro; vane fandis la fandisto: la malbonuloj ne apartiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'Arĝento rifuzita oni nomos ilin, ĉar la Eternulo forrifuzis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Jen estas la vorto, kiu aperis al Jeremia de la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Stariĝu en la pordego de la domo de la Eternulo, kaj tie proklamu ĉi tiun vorton, kaj diru: Aŭskultu la vorton de la Eternulo, ĉiuj Judoj, kiuj venas en ĉi tiun pordegon, por adorkliniĝi al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Tiele diras la Eternulo Cebaot, Dio de Izrael: Plibonigu vian vojon kaj vian konduton; tiam Mi loĝigos vin sur ĉi tiu loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Ne fidu la mensogajn vortojn, kiam oni diras al vi: Ĉi tie estas la templo de la Eternulo, la templo de la Eternulo, la templo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Nur se vi plibonigos vian vojon kaj vian konduton, se vi agos juste unu rilate la alian,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'se vi ne premos fremdulon, orfon, kaj vidvinon, se vi ne verŝos senkulpan sangon sur ĉi tiu loko, kaj ne sekvos aliajn diojn por via malfeliĉo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'tiam Mi loĝigos vin sur ĉi tiu loko, en la lando, kiun Mi donis al viaj patroj, ĉiam kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Jen vi fidas la mensogajn vortojn, kiuj neniom helpas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Ŝtelante, mortigante, adultante, ĵurante mensoge, incensante al Baal, kaj sekvante aliajn diojn, kiujn vi ne konas,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'vi poste venas kaj stariĝas antaŭ Mi en ĉi tiu domo, kiu estas nomata per Mia nomo, kaj vi diras: Ni saviĝis-kvankam vi plue faras ĉiujn tiujn abomenindaĵojn!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Ĉu ĉi tiun domon, kiu estas nomata per Mia nomo, vi rigardas kiel neston de rabistoj? Mi bone vidas tion, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Iru do al Mia loko en Ŝilo, kie Mi antaŭe loĝigis Mian nomon, kaj rigardu, kion Mi faris al ĝi pro la malbonagoj de Mia popolo Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Kaj nun, ĉar vi faras ĉiujn tiujn farojn, diras la Eternulo, kaj Mi de frua mateno ĉiam parolas al vi, kaj vi ne aŭskultas, Mi vokas vin, kaj vi ne respondas:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'tial al la domo, kiu estas nomata per Mia nomo kaj kiun vi fidas, kaj al la loko, kiun Mi donis al vi kaj al viaj patroj, Mi faros tiel, kiel Mi faris al Ŝilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'Mi forpuŝos vin de antaŭ Mi, kiel Mi forpuŝis ĉiujn viajn fratojn, la tutan idaron de Efraim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Kaj vi ne preĝu por ĉi tiu popolo kaj ne direktu por ili supren krion kaj preĝon kaj ne klopodu antaŭ Mi, ĉar Mi ne aŭskultos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Ĉu vi ne vidas, kion ili faras en la urboj de Judujo kaj sur la stratoj de Jerusalem?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'La filoj kolektas la lignon, kaj la patroj ekbruligas la fajron, kaj la virinoj knedas la paston, por fari kukojn por la reĝino de la ĉielo, kaj ili faras verŝoferojn al aliaj dioj, por ĉagreni Min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Sed ĉu Min ili ĉagrenas? diras la Eternulo; ĉu ne sin mem, por hontigi sian vizaĝon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Tial tiele diras la Sinjoro, la Eternulo: Jen Mia kolero kaj indigno elverŝiĝos sur ĉi tiun lokon, sur la homojn kaj sur la brutojn kaj sur la arbojn de la kampo kaj sur la fruktojn de la tero; ĝi ekflamos kaj ne estingiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Tiele diras la Eternulo Cebaot, Dio de Izrael: Aldonu viajn bruloferojn al viaj buĉoferoj, kaj manĝu la viandon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'ĉar Mi ne parolis al viaj patroj kaj Mi ne ordonis al ili pri bruloferoj kaj buĉoferoj en la tago, kiam Mi elkondukis ilin el la lando Egipta;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'nur ĉi tion Mi ordonis al ili: Aŭskultu Mian voĉon, kaj Mi estos via Dio, kaj vi estos Mia popolo, kaj iru laŭ la tuta vojo, kiun Mi montros al vi, por ke estu al vi bone.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Sed ili ne aŭskultis kaj ne alklinis sian orelon, ili agis laŭ siaj propraj pensoj, laŭ la obstineco de sia malbona koro, kaj ili iris malantaŭen, ne antaŭen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'De post la tago, kiam viaj patroj eliris el la lando Egipta, ĝis la nuna tago Mi sendadis al vi ĉiujn Miajn servantojn, la profetojn, ĉiutage Mi sendis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'sed ili ne aŭskultis Min kaj ne alklinis sian orelon, ili obstinigis sian nukon, agis pli malbone ol iliaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Kaj kiam vi diros al ili ĉion ĉi tion, ili ne aŭskultos vin; kiam vi vokos ilin, ili ne respondos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Diru do al ili: Jen estas popolo, kiu ne aŭskultas la voĉon de la Eternulo, sia Dio, kaj ne akceptas moralinstruon; la kredo malaperis kaj estas ekstermita el ilia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Detondu viajn harojn kaj forĵetu ilin, kantu funebran kanton sur la altaĵoj; ĉar la Eternulo forrifuzis kaj forpuŝis la generacion, kiun Li koleras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Ĉar la filoj de Jehuda faras malbonon antaŭ Miaj okuloj, diras la Eternulo; siajn abomenindaĵojn ili metis en la domon, kiu estas nomata per Mia nomo, por malpurigi ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'Ili aranĝis altaĵojn de Tofet en la valo de la filo de Hinom, por bruligi siajn filojn kaj siajn filinojn en fajro, kion Mi ne ordonis kaj kio neniam estis en Miaj pensoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Pro tio jen venos tempo, diras la Eternulo, kiam oni jam nomos tion ne Tofet kaj valo de la filo de Hinom, sed valo de mortigado, kaj en Tofet oni enterigos mortintojn, ĉar mankos alia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'Kaj la kadavroj de ĉi tiu popolo estos manĝaĵo por la birdoj de la ĉielo kaj por la bestoj de la tero, kiujn neniu fortimigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'Kaj Mi ĉesigos en la urboj de Judujo kaj sur la stratoj de Jerusalem la sonojn de ĝojo kaj la sonojn de gajeco, la voĉon de fianĉo kaj la voĉon de fianĉino; ĉar la lando fariĝos dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'En tiu tempo, diras la Eternulo, oni elĵetos el iliaj tomboj la ostojn de la reĝoj de Judujo kaj la ostojn de ĝiaj princoj kaj la ostojn de la pastroj kaj la ostojn de la profetoj kaj la ostojn de la loĝantoj de Jerusalem;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'kaj oni disĵetos ilin antaŭ la suno kaj antaŭ la luno kaj antaŭ la tuta armeo de la ĉielo, kiujn ili amis, al kiuj ili servis, kiujn ili sekvis, kiujn ili serĉis, kaj al kiuj ili adorkliniĝis; oni ne kolektos ilin kaj ne enterigos ilin, sed ili estos kiel sterko sur la supraĵo de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'Kaj preferos la morton ol la vivon ĉiuj restintoj, kiuj restos el tiu malbona gento, kiuj restos en ĉiuj lokoj, sur kiujn Mi dispelis ilin, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Kaj diru al ili: Tiele diras la Eternulo: Ĉu se oni falis, oni ne leviĝas? ĉu se oni devojiĝis, oni ne volas reveni?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Kial do ĉi tiu popolo en Jerusalem defalis per defalo obstina? ili forte sin tenas je la malveraĵo kaj ne volas sin konverti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Mi atentis kaj aŭskultis, sed ili parolas nenion ĝustan; neniu pentas sian malbonecon, dirante: Kion mi faris? Ĉiu fordonis sin al sia kurado, kiel ĉevalo, kiu flugrapide kuras en la batalon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Eĉ cikonio sub la ĉielo scias sian tempon, turto, hirundo, kaj gruo observas la tempon, kiam ili devas veni; sed Mia popolo ne scias la leĝon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Kiel vi diras: Ni estas saĝuloj, kaj ni havas antaŭ ni la instruon de la Eternulo? Ĝi fariĝis ja mensogaĵo per la mensoga skribilo de la skribistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Per honto kovris sin la saĝuloj, konfuziĝis kaj implikiĝis; jen ili forrifuzis la vorton de la Eternulo, kian do saĝecon ili havas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Tial Mi fordonos iliajn edzinojn al aliuloj, iliajn kampojn al venkintoj; ĉar de malgrandulo ĝis grandulo ili ĉiuj estas profitavidaj, de profeto ĝis pastro ili ĉiuj faras malhonestaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Kaj la vundojn de la filino de Mia popolo ili kuracas per facilanimigo, dirante, ke ĉio estas en bona stato, kvankam ne estas bona stato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Ĉu ili hontas, ke ili faras abomenindaĵon? ili tute ne hontas, ili eĉ ne povoscias ruĝiĝi; tial ili falos inter la falantoj, ili renversiĝos, kiam Mi vizitos ilin, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Mi plene ŝirkolektos ilin, diras la Eternulo; ne restos beroj sur la vinberbranĉo nek figoj sur la figarbo, kaj la folioj forvelkos, kaj Mi donos al ili plenan pereon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Por kio ni sidas? kolektiĝu, kaj ni iru en la fortikigitajn urbojn, kaj ni tie pereu; ĉar la Eternulo, nia Dio, pereigas nin kaj trinkigas al ni akvon maldolĉan pro tio, ke ni pekis antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Ni esperis pacon, sed venas nenio bona; ni esperis tempon de resaniĝo, sed jen estas teruro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'El la regiono de Dan oni aŭdas spiregadon de iliaj ĉevaloj; de la blekegado de iliaj fortaj ĉevaloj tremas la tuta tero; ili iras, kaj ili formanĝos la teron, kaj tion, kio estas sur ĝi, la urbon kaj ĝiajn loĝantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Ĉar jen Mi sendos sur vin serpentojn, vipurojn, kiujn oni ne povas sorĉligi, kaj ili pikos vin, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Mia malĝojo estas super ĉiuj malĝojoj, mia koro en mi doloras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Jen mi aŭdas kriadon de la filino de mia popolo el lando malproksima: Ĉu jam ne ekzistas la Eternulo en Cion? ĉu ĝia Reĝo ne estas en ĝi? Sed kial ili kolerigis min per siaj idoloj, per fremdaj vantaĵoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'Pasis la rikolto, finiĝis la somero, sed ni ne ricevis helpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'La malfeliĉo de mia popolo min afliktas, mi malĝojas, mi sentas teruron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Ĉu ne ekzistas balzamo en Gilead? ĉu ne ekzistas tie kuracisto? kial do ne venas resaniĝo al la filino de mia popolo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Ho, se mia kapo havus sufiĉe da akvo kaj miaj okuloj estus fonto da larmoj! tage kaj nokte mi priplorus la mortigitojn el mia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Ho, se mi havus en la dezerto rifuĝejon por migrantoj! tiam mi forlasus mian popolon kaj forirus de ili, ĉar ili ĉiuj estas adultuloj, amaso da perfiduloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Per siaj langoj ili pafas mensogon kiel per pafarko, ne por vero ili fortiĝas sur la tero; ili iras de malbonago al malbonago, kaj Min ili ne konas, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Gardu vin unu kontraŭ alia, kaj fidu neniun fraton; ĉar ĉiu frato insidas, kaj ĉiu proksimulo disportas kalumniojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'Unu trompas alian, kaj veron ili ne parolas; ili lernigis sian langon paroli malveron, ili laciĝas de malbonagado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Vi loĝas meze de malhonesteco; pro malhonesteco ili ne volas koni Min, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Tial tiele diras la Eternulo Cebaot: Jen Mi fandos kaj elprovos ilin; ĉar kiel alie Mi povas agi kun la filino de Mia popolo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Ilia lango estas vundanta sago, ĝi parolas trompe; per sia buŝo ili afable salutas sian proksimulon, sed en sia koro ili faras insidon kontraŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Ĉu pro tio Mi povas ne puni ilin? diras la Eternulo; ĉu al tia popolo Mia animo ne venĝos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Pri la montoj Mi ploros, kaj pri la kabanoj en la dezerto Mi kantos funebre; ĉar ili estas tiel bruligitaj, ke jam neniu migranto en ilin eniras, kaj oni jam ne aŭdas blekadon de brutoj; de la birdoj de la ĉielo ĝis la brutoj ĉio diskuris, foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'Mi faros Jerusalemon amaso da ŝtonoj, loĝejo de ŝakaloj; kaj la urbojn de Judujo Mi dezertigos tiel, ke estos en ili neniu loĝanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Ĉu ekzistas homo saĝa, kiu komprenus tion kaj klarigus tion, kion diras al li la buŝo de la Eternulo, pro kio la lando pereis kaj estas bruldetruita kiel dezerto tiel, ke neniu iras tra ĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'Kaj la Eternulo diris: Pro tio, ke ili forlasis Mian instruon, kiun Mi donis al ili, kaj ne aŭskultis Mian voĉon kaj ne sekvis ĝin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'sed sekvis la obstinecon de sia koro kaj la Baalojn, kiel lernigis al ili iliaj patroj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'tial tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi manĝigos al tiu popolo vermuton kaj trinkigos al ili akvon maldolĉan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'kaj Mi dissemos ilin inter popoloj, kiujn ne konis ili nek iliaj patroj; kaj Mi sendos post ilin glavon, ĝis Mi tute ekstermos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Tiele diras la Eternulo Cebaot: Serĉu kaj voku ploristinojn, ke ili venu; sendu voki lertulinojn en tia afero, ke ili venu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'Ili rapidu kaj komencu funebran ploradon pri ni, por ke el niaj okuloj ekfluu larmoj kaj de niaj palpebroj ekverŝiĝu akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Voĉo de funebra plorado estos aŭdata el Cion: Kiele ni estas ruinigitaj! kiele ni estas kovritaj de honto! ĉar ni forlasis nian landon kaj estas elĵetitaj el niaj loĝejoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Aŭskultu do, ho virinoj, la vorton de la Eternulo, kaj via orelo enprenu la vorton el Lia buŝo: Lernigu al viaj filinoj funebran ploradon kaj unu al alia funebran kantadon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Ĉar la morto eniras en niajn fenestrojn kaj venas en niajn palacojn, por ekstermi infanojn de ekstere, junulojn de la stratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Diru, ke tiele diras la Eternulo: La kadavroj de homoj falos kiel sterko sur la kampojn kaj kiel garboj malantaŭ la rikoltanto, kaj neniu ilin enkolektos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Tiele diras la Eternulo: Ne fieru saĝulo pri sia saĝeco, ne fieru fortulo pri sia forteco, ne fieru riĉulo pri sia riĉeco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'sed kiu volas fieri, tiu fieru nur pri tio, ke li komprenas kaj konas Min, ke Mi estas la Eternulo, kiu faras korfavoraĵon, juĝon, kaj justaĵon sur la tero; ĉar ĉi tio plaĉas al Mi, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Jen venos tagoj, diras la Eternulo, kiam Mi punvizitos ĉiujn cirkumciditajn kaj necirkumciditajn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'Egiptujon, Judujon, Edomon, la Amonidojn, Moabon, kaj ĉiujn, kiuj tondas la harojn sur la tempioj kaj kiuj loĝas en la dezerto; ĉar ĉiuj popoloj havas necirkumciditan prepucion, sed la tuta domo de Izrael havas necirkumciditan koron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Aŭskultu la vorton, kiun diras pri vi la Eternulo, ho domo de Izrael!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Tiele diras la Eternulo: Ne lernu la konduton de la nacioj, kaj ne timu la signojn de la ĉielo, kiel la nacioj ilin timas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Ĉar la aranĝoj de la nacioj estas vantaĵo: ili dehakas arbon en la arbaro, kaj ĉarpentisto prilaboras ĝin per hakilo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'ili ornamas ĝin per arĝento kaj oro, fortikigas per najloj kaj marteloj, por ke ĝi ne disfalu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Ili estas kiel kolono ĉirkaŭforĝita; ili ne parolas, oni portas ilin, ĉar ili ne povas iri. Ne timu ilin, ĉar ili ne faras malbonon, tiel same, kiel ili ne povas fari bonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Sed simila al Vi, ho Eternulo, ekzistas neniu; granda Vi estas, kaj granda estas Via nomo en potenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Kiu povas ne timi Vin, ho Reĝo de la popoloj? al Vi tio decas, ĉar inter ĉiuj saĝuloj de la nacioj kaj en ĉiuj iliaj regnoj ekzistas neniu simila al Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'Ĉiuj ili malsaĝiĝis kaj idiotiĝis, ĉar ligno donas ja nur vantaĵan instruon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'Foliigita arĝento estas venigita el Taŝiŝ kaj oro el Ufaz, laboritaĵo de artisto kaj de la manoj de fandisto; blua kaj purpura ŝtofo estas ilia vesto, ĉio estas faritaĵo de lertuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Sed la Eternulo estas Dio vera, Li estas Dio vivanta kaj Reĝo eterna; de Lia kolero tremas la tero, kaj la nacioj ne povas elteni Lian indignon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Diru do al ili: La dioj, kiuj ne kreis la ĉielon kaj la teron, pereos de sur la tero kaj sub la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Li kreis la teron per Sia forto, aranĝis la mondon per Sia saĝo, kaj per Sia prudento etendis la ĉielon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Kiam Li eksonigas Sian voĉon, kolektiĝas multego da akvo en la ĉielo; Li levas la nubojn de la randoj de la tero, Li aperigas fulmojn inter la pluvo, kaj elirigas la venton el Siaj trezorejoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Malsaĝiĝis ĉiu homo kun sia sciado, per honto kovriĝis ĉiu fandisto kun sia statuo; ĉar lia fanditaĵo estas malveraĵo, ĝi ne havas en si spiriton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Tio estas vantaĵo, faro de eraro; kiam ili estos vizititaj, ili pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Ne simila al ili estas Tiu, kiun havas Jakob; ĉar Li estas la kreinto de ĉio, kaj Izrael estas la gento de Lia heredo; Eternulo Cebaot estas Lia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Forprenu de la tero vian komercaĵon, vi, kiu loĝas en fortikaĵo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'ĉar tiele diras la Eternulo: Jen Mi ĉi tiun fojon elĵetos la loĝantojn de la lando, kaj Mi premos ilin, ke ili sentos kaj diros:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Ho ve al mi en mia malfeliĉo! neresanigebla estas mia vundo. Kaj mi pensis, ke tio estas mia malsano, kiun mi devas elporti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Mia tendo estas ruinigita, kaj ĉiuj miaj ŝnuroj estas disŝiritaj; miaj infanoj foriris de mi kaj forestas; estas jam neniu, kiu povus starigi mian tendon kaj pendigi miajn kurtenojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Ĉar la paŝtistoj malsaĝiĝis kaj ne serĉis la Eternulon; tial ili nenion komprenas kaj ilia tuta paŝtataro estas dispelita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Jen venas laŭta krio kaj granda bruo el norda lando, por fari la urbojn de Judujo ruinoj, loĝejo de ŝakaloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Mi scias, ho Eternulo, ke la vojo de homo estas ne laŭ lia volo, ke homo iranta ne povas libere direkti siajn paŝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Punu min, ho Eternulo, sed laŭjuĝe, ne en Via kolero, por ke Vi min ne tro dispremu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Elverŝu Vian koleron sur tiujn naciojn, kiuj Vin ne konas, kaj sur la gentojn, kiuj ne vokas Vian nomon; ĉar ili formanĝis Jakobon, englutis lin, ekstermis lin, kaj dezertigis lian loĝejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Jen estas la vorto, kiu aperis al Jeremia de la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Aŭskultu la vortojn de ĉi tiu interligo, kaj raportu ilin al la Judoj kaj al la loĝantoj de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Kaj diru al ili: Tiele diras la Eternulo, Dio de Izrael: Malbenita estu la homo, kiu ne aŭskultos la vortojn de ĉi tiu interligo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'kiun Mi donis al viaj patroj, kiam Mi elkondukis ilin el la lando Egipta, el la fera forno, dirante: Obeu Mian voĉon, kaj faru ĉion, kion Mi ordonas al vi; kaj vi estos Mia popolo, kaj Mi estos via Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'por ke plenumiĝu la ĵuro, kiun Mi ĵuris al viaj patroj, ke Mi donos al ili landon, kie fluas lakto kaj mielo, kiel tio estas nun. Kaj mi respondis kaj diris: Tiel estu, ho Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Kaj la Eternulo diris al mi: Proklamu ĉiujn ĉi tiujn vortojn en la urboj de Judujo kaj sur la stratoj de Jerusalem, dirante: Aŭskultu la vortojn de ĉi tiu interligo kaj plenumu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Ĉar Mi klare avertis viajn patrojn, kiam Mi elkondukis ilin el la lando Egipta, ĝis la nuna tago, Mi konstante avertadis ilin, dirante: Aŭskultu Mian voĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Sed ili ne aŭskultis kaj ne alklinis sian orelon, ĉiu sekvis la obstinecon de sia malbona koro; kaj tial Mi venigis sur ilin ĉion, kio estas dirita en ĉi tiu interligo, kiun Mi ordonis plenumi, sed kiun ili ne plenumis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Kaj la Eternulo diris al mi: Fariĝis ribelo ĉe la Judoj kaj ĉe la loĝantoj de Jerusalem;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'ili returnis sin al la malbonagoj de siaj prapatroj, kiuj ne volis obei Miajn vortojn kaj sekvis aliajn diojn, servante al ili; la domo de Izrael kaj la domo de Jehuda rompis Mian interligon, kiun Mi faris kun iliaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Tial tiele diras la Eternulo: Jen Mi venigos sur ilin malfeliĉon, el kiu ili ne povos liberiĝi; kaj ili krios al Mi, sed Mi ne aŭskultos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Tiam la urboj de Judujo kaj la loĝantoj de Jerusalem iros kaj krios al tiuj dioj, al kiuj ili incensas, sed tiuj ne helpos ilin en la tempo de ilia malfeliĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Ĉar kiom da urboj, tiom da dioj vi havas, ho Jehuda; kaj kiom da stratoj estas en Jerusalem, tiom da hontindaj altaroj vi starigis, por incensi al Baal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Kaj vi ne preĝu por ĉi tiu popolo kaj ne direktu por ili supren peton kaj preĝon; ĉar Mi ne aŭskultos, kiam ili vokos al Mi en la tempo de sia malfeliĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Por kio, Mia kara, vi faras en Mia domo la multajn artifikojn kaj alportas la sanktan viandon, se vi fariĝas ĉiam pli malbona kaj ankoraŭ ĝojas pri tio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'La Eternulo nomis vin verda, bela, fruktoriĉa olivarbo; sed kun granda bruo ekbruligis ĝin fajro, kaj ĝiaj branĉoj difektiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'La Eternulo Cebaot, kiu plantis vin, dekretis por vi malbonon pro la malbono de la domo de Izrael kaj de la domo de Jehuda, kiun ili faris, kolerigante Min per la incensado al Baal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Vi, ho Eternulo, sciigis tion al mi, por ke mi sciu; Vi montris al mi iliajn farojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Kaj mi, kiel milda ŝafido, kondukata al la buĉo, ne sciis, ke ili havas malbonajn intencojn kontraŭ mi, dirante: Ni ekstermu la arbon kun ĝiaj fruktoj, ni elhaku ĝin el la tero de la vivo, por ke lia nomo ne plu estu rememorata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Sed Vi, ho Eternulo Cebaot, kiu juĝas juste, kiu esploras la internon kaj la koron, vidigu al mi Vian venĝon kontraŭ ili, ĉar al Vi mi transdonis mian proceson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Tial tiele diras la Eternulo pri la loĝantoj de Anatot, kiuj serĉas vian animon, kaj diras: Ne profetu al ni en la nomo de la Eternulo, por ke vi ne mortu de niaj manoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'tiele diras la Eternulo Cebaot: Jen Mi punvizitos ilin; la junuloj mortos de glavo, iliaj filoj kaj filinoj mortos de malsato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'Kaj neniu restos el ili, ĉar Mi venigos malfeliĉon sur la loĝantojn de Anatot en la jaro, kiam Mi punvizitos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Vi estos prava, ho Eternulo, kiam mi procesos kun Vi; tamen mi parolos kun Vi pri justeco: kial la vojo de malpiuloj estas sukcesa kaj ĉiuj perfiduloj vivas trankvile?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Vi plantis ilin, kaj ili ricevis fortajn radikojn, ili kreskas kaj donas fruktojn; proksima Vi estas en ilia buŝo, sed malproksima de ilia interno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Sed min, ho Eternulo, Vi konas; Vi vidis kaj esploris, kia estas mia koro koncerne Vin. Pelu ilin, kiel ŝafojn al la buĉo, kaj apartigu ilin por la tago de mortigo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Kiel longe Vi tenos la landon en malĝojo kaj la herbo sur ĉiuj kampoj velkos? Brutoj kaj birdoj pereas pro la malboneco de ĝiaj loĝantoj, kiuj diras: Li ne scias, kio estos al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Se vi kuras kun piedirantoj kaj ili vin lacigas, kiel do vi povas konkuri kun ĉevaloj? se vi esperas trovi sendanĝerecon en lando paca, kion vi faros ĉe la majesta Jordan?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Ĉar eĉ viaj fratoj kaj la domo de via patro agas perfide kontraŭ vi, krias post vi plenvoĉe. Ne fidu ilin, eĉ se ili parolos al vi bone.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Mi forlasis Mian domon, Mi foriris de Mia heredaĵo; tion, kio estis kara por Mia animo, Mi fordonis en la manojn de ĝiaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Mia heredaĵo fariĝis por Mi kiel leono en la arbaro: ĝi ekblekegis kontraŭ Mi, tial Mi ĝin ekmalamis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Mia heredaĵo fariĝis kiel diverskolora rabobirdo, kiun ĉirkaŭe atakis aliaj rabobirdoj. Venu, kolektiĝu, ĉiuj bestoj de la kampo, venu, por formanĝi ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Multo da paŝtistoj ruinigis Mian vinberĝardenon, dispremis per la piedoj Mian kampoparton, Mian plej amatan kampoparton ili faris senfrukta dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Ili faris ĝin dezerto, kaj ĝia dezerteco plendas antaŭ Mi; la tuta lando estas dezertigita, kaj neniu zorgas pri tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Sur ĉiujn altaĵojn en la dezerto venis ruinigantoj, ĉar la glavo de la Eternulo ekstermas ĉion de unu rando de la lando ĝis la alia; neniu karno estas indulgata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Ili semis tritikon, sed rikoltis dornojn; ili elspezis, sed ne profitis; viaj enspezoj estos hontindaj, pro la flama kolero de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Tiele diras la Eternulo pri ĉiuj malbonaj najbaroj, kiuj tuŝis la posedaĵon, kiun Mi heredigis al Mia popolo Izrael: Jen Mi elŝiros ilin el ilia lando, kaj la domon de Jehuda Mi eltiros el inter ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Kaj kiam Mi estos elŝirinta ilin, Mi denove kompatos ilin kaj revenigos ĉiun al lia heredaĵo kaj ĉiun en lian landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Kaj se ili lernos la agmanieron de Mia popolo, por ĵuri per Mia nomo: Kiel vivas la Eternulo, simile al tio, kiel ili lernigis al Mia popolo ĵuri per Baal, tiam ili estos konstrue aranĝitaj inter Mia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Sed se ili ne aŭskultos, tiam Mi tute elŝiros tiun popolon kaj ekstermos ĝin, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Tiele diris al mi la Eternulo: Iru, aĉetu al vi tolan zonon kaj metu ĝin sur viajn lumbojn, sed en akvon ĝin ne metu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Kaj mi aĉetis la zonon konforme al la vorto de la Eternulo kaj metis ĝin sur miajn lumbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Kaj duafoje aperis al mi la vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Prenu la zonon, kiun vi aĉetis, kiu estas sur viaj lumboj, leviĝu kaj iru al Eŭfrato, kaj kaŝu ĝin tie en fendo de roko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Kaj mi iris kaj kaŝis ĝin apud Eŭfrato, kiel la Eternulo al mi ordonis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Post longa tempo la Eternulo diris al mi: Leviĝu, iru al Eŭfrato, kaj prenu de tie la zonon, pri kiu Mi ordonis al vi, ke vi kaŝu ĝin tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Kaj mi iris al Eŭfrato, elfosis kaj prenis la zonon el la loko, kie mi ĝin kaŝis; kaj jen montriĝis, ke la zono tute putriĝis kaj jam por nenio taŭgas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Kaj aperis al mi la vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'Tiele diras la Eternulo: Tiele Mi putrigos la fieron de Jehuda kaj la grandan fieron de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Tiu malbona popolo, kiu ne volas obei Miajn vortojn, kiu sekvas la obstinecon de sia koro, kaj sekvas aliajn diojn, servante al ili kaj adorkliniĝante al ili, fariĝos kiel ĉi tiu zono, kiu jam taŭgas por nenio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Kiel zono estas alligata al la lumboj de homo, tiel Mi alligis al Mi la tutan domon de Izrael kaj la tutan domon de Jehuda, diras la Eternulo, por ke ili estu Mia popolo, Mia nomo, gloro, kaj ornamo; sed ili ne obeis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Kaj diru al ili ĉi tion: Tiele diras la Eternulo, Dio de Izrael: Ĉiu vinkruĉo estos plenigata de vino. Ili diros al vi: Ĉu ni ne scias, ke ĉiu vinkruĉo estos plenigata de vino?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'Sed vi diru al ili: Tiele diras la Eternulo: Jen Mi plenigos ĝis ebrieco ĉiujn loĝantojn de ĉi tiu lando, la reĝojn, kiuj sidas sur la trono de David, la pastrojn, la profetojn, kaj ĉiujn loĝantojn de Jerusalem;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'kaj Mi interfrapigos ilin reciproke, la patrojn kaj la filojn kune, diras la Eternulo, Mi ne kompatos, ne preterlasos, ne indulgos, ekstermante ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Aŭskultu kaj atentu; ne tenu vin alte, ĉar la Eternulo parolas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Donu honoron al la Eternulo, via Dio, antaŭ ol Li venigos mallumon, kaj antaŭ ol viaj piedoj falpuŝiĝos sur la mallumaj montoj; tiam vi atendos lumon, sed Li donos anstataŭ ĝi ombron de morto, densan nebulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Se vi ne aŭskultos, tiam mia animo kaŝe ploros pro via fiero, ĝi ploros maldolĉe, kaj el miaj okuloj fluegos larmoj, ĉar kaptita estos la paŝtataro de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Diru al la reĝo kaj al la reĝino: Sidiĝu pli malalte, ĉar la krono de via majesto defalis de via kapo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'La sudaj urboj estas fermitaj, kaj neniu ilin malfermos; la tuta Judujo estas forkondukita en kaptitecon, ĝi tuta estas forkondukita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Levu viajn okulojn, kaj rigardu tiujn, kiuj venas de nordo. Kie estas la paŝtataro, kiu estas komisiita al vi, via bela ŝafaro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Kion vi diros, kiam Li punvizitos vin? vi lernigis ja ilin esti kontraŭ vi, esti ĉefoj kaj ordonantoj. Ĉu ne atakos vin doloroj kiel naskantan virinon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Eble vi diros en via koro: Pro kio trafis min ĉi tio? Pro la multo de viaj malbonagoj estas levitaj la randoj de viaj vestoj kaj malhonoritaj viaj kalkanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Ĉu negro povas ŝanĝi sian haŭton aŭ leopardo siajn makulojn? tiel ankaŭ vi, ĉu vi povas fari bonon, alkutimiĝinte al malbono?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Tial Mi disblovos ilin kiel pajlopecetojn, kiujn dispelas la vento el la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Tio estos via sorto, via parto, destinita de Mi, diras la Eternulo, pro tio, ke vi forgesis Min kaj fidis malveraĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'Kaj Mi levos la randojn de viaj vestoj ĝis via vizaĝo, kaj montriĝos via hontindaĵo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'via adulto, via voluptegeco, viaj malĉastaj pensoj. Sur la montetoj de la kampo Mi vidis viajn abomenindaĵojn. Ve al vi, ho Jerusalem! ĉu vi ne puriĝos? kiam do fine?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Vorto de la Eternulo, kiu aperis al Jeremia koncerne la senpluvecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Judujo funebras, ĝiaj pordegoj malĝoje nigriĝis, klinite al la tero, kaj plora kriado leviĝas el Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Ĝiaj potenculoj sendas siajn subulojn, por alporti akvon; ĉi tiuj venas al la putoj, sed ne trovas akvon; ili alportas returne siajn vazojn malplenajn, ili hontas, konsterniĝas, kaj kovras sian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Ĉar la tero dezertiĝis pro tio, ke ne estis pluvo, tial konsterniĝis la terkultivistoj kaj kovris sian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Eĉ cervino, naskinta sur la kampo, forlasas sian idon, ĉar ne ekzistas verdaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'Sovaĝaj azenoj staras sur montetoj, glutas aeron kiel ŝakaloj; senbriliĝis iliaj okuloj, ĉar ne ekzistas herbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Se niaj malbonagoj akuzas nin, ho Eternulo, tiam agu pro Via nomo; ĉar granda estas nia perfido, ni pekis antaŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Ho espero de Izrael kaj lia savanto en tempo de malfeliĉo! kial Vi estas kiel fremdulo en la lando, kiel pasanto, kiu eniris nur por tradormi la nokton?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Kial Vi estas kiel homo konfuzita, kiel fortulo, kiu ne povas helpi? Vi estas ja meze de ni, ho Eternulo, kaj ni portas sur ni Vian nomon; ne forlasu nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Tiele diras la Eternulo pri ĉi tiu popolo: Ili amas vagi, ili ne retenas siajn piedojn; tial la Eternulo ne estas favora al ili, nun Li memoras iliajn malbonagojn kaj punas iliajn pekojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Kaj la Eternulo diris al mi: Ne preĝu por ĉi tiu popolo, por ĝia bono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Se ili fastos, Mi ne aŭskultos ilian preĝon, kaj se ili alportos bruloferojn kaj farunoferojn, Mi ne estos favora al ili; sed Mi ekstermos ilin per glavo, per malsato, kaj per pesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Tiam mi diris: Ho Sinjoro, ho Eternulo! jen la profetoj diras al ili: Vi ne vidos glavon, kaj malsato ne estos ĉe vi, ĉar veran pacon Mi donos al vi sur ĉi tiu loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Sed la Eternulo diris al mi: Malveraĵon profetas tiuj profetoj en Mia nomo; Mi ne sendis ilin, ne donis al ili ordonojn, kaj ne parolis al ili; ili profetas al vi viziojn mensogajn, sorĉaĵon, idolaĵon, kaj trompaĵon de sia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Tial tiele diras la Eternulo pri la profetoj: Ĉar ili profetas en Mia nomo, kvankam Mi ne sendis ilin, kaj ili diras, ke glavo kaj malsato ne estos en ĉi tiu lando-per glavo kaj malsato estos ekstermitaj tiuj profetoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'kaj la popolo, al kiu ili profetas, estos disĵetita sur la stratojn de Jerusalem per malsato kaj glavo, kaj neniu ilin enterigos-ili, iliaj edzinoj, iliaj filoj, kaj iliaj filinoj; kaj Mi elverŝos sur ilin ilian malbonecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Kaj diru al ili jenon: Miaj okuloj fluigas larmojn nokte kaj tage kaj ne ĉesas, ĉar granda malfeliĉo trafis la virgulinon, la filinon de mia popolo, frapo tre doloriga.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Kiam mi eliras sur la kampon, mi vidas homojn, mortigitajn per glavo; kiam mi eniras en la urbon, mi vidas homojn, senfortigitajn de malsato; ankaŭ la profetoj kaj pastroj formigris en landon, kiun ili ne konas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Ĉu Vi tute forpuŝis Jehudan? ĉu Via animo eksentis abomenon kontraŭ Cion? kial Vi frapis nin tiel, ke neniu povas nin resanigi? Ni esperis pacon, sed venis nenio bona; ni esperis tempon de resaniĝo, sed ni havas nur teruron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Ni konfesas, ho Eternulo, nian malpiecon kaj la malbonagojn de niaj patroj; ĉar ni pekis antaŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Pro Via nomo ne malestimegu nin, ne malaltigu la tronon de Via gloro; memoru kaj ne rompu Vian interligon kun ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Ĉu inter la idoloj de la nacioj ekzistas tiaj, kiuj povas doni pluvon? ĉu la ĉielo per si mem donas pluvegon? Vi estas ja la Eternulo, nia Dio, kaj ni esperas al Vi, ĉar Vi faras ĉion ĉi tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Kaj la Eternulo diris al mi: Eĉ se stariĝus antaŭ Mi Moseo kaj Samuel, eĉ tiam Mia animo ne estos kun tiu popolo; forpelu ilin de antaŭ Mia vizaĝo, ili foriru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Kaj se ili diros al vi: Kien ni iru? tiam diru al ili, ke tiele diras la Eternulo: Kiu estas destinita por la morto, tiu iru al la morto; kiu estas destinita por la glavo, tiu iru al la glavo; kiu estas destinita por la malsato, tiu iru al la malsato; kiu estas destinita por kaptiteco, tiu iru en kaptitecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Mi punos ilin per kvar specoj, diras la Eternulo: per glavo, por mortigi; per hundoj, por treni; per birdoj de la ĉielo kaj per bestoj de la tero, por formanĝi kaj ekstermi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'Mi faros ilin objekto de teruro por ĉiuj regnoj de la tero, pro Manase, filo de Ĥizkija, reĝo de Judujo, pro tio, kion li faris en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Ĉar kiu kompatos vin, ho Jerusalem, kaj kiu afliktiĝos pri vi? kiu sin turnos, por demandi pri via farto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Vi forlasis Min, diras la Eternulo, vi iris malantaŭen; tial Mi etendas Mian manon sur vin kaj pereigas vin; Mi laciĝis de kompatado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Mi disŝutis ilin per ŝutilo tra la pordegojn de la lando, Mi seninfanigis kaj pereigis Mian popolon; kaj tamen ili ne returnis sin de sia vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Mi faros, ke da vidvinoj ĉe ili estos pli ol da sablo ĉe la maro; en ilian ĉefurbon Mi venigos junan militiston, kiu ruinigas meze de la tago; Mi ĵetos sur ĝin subite timon kaj teruron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Naskintino de sep infanoj estas senforta, eliras ŝia animo; subiras ŝia suno, kiam estas ankoraŭ tago; ŝi estas kovrita de honto kaj de malhonoro. Kaj tiujn, kiuj restis, Mi transdonos al glavo antaŭ iliaj malamikoj, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Ho ve al vi, mia patrino, ke vi naskis min kiel homon, kontraŭ kiu ĉiu malpacas kaj kiun ĉiu atakas sur la tuta tero! Mi ne pruntedonis procentege, mi ne prenis prunte; tamen ĉiuj min malbenas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'La Eternulo diris: Mi liberigos vin por bono, Mi helpos vin en la tempo malbona kaj en la tempo de premado kontraŭ la malamiko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Ĉu oni rompas feron per fero el nordo kaj per kupro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Vian riĉaĵon kaj viajn trezorojn Mi fordonos al rabado, sen ia pago, pro ĉiuj viaj pekoj en ĉiuj viaj limoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'Kaj Mi transirigos vin al viaj malamikoj en landon, kiun vi ne konas; ĉar fajro, kiu ekflamis en Mia kolero, brulos sur vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Vi scias, ho Eternulo; rememoru min, kaj vizitu min, kaj venĝu pro mi al miaj persekutantoj; pro Via toleremeco ne pereigu min; sciu, ke pro Vi mi suferas malhonoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Kiam mi trovis Viajn vortojn, mi ilin englutis; kaj Via vorto fariĝis mia ĝojo kaj gajeco de mia koro; ĉar mi portas sur mi Vian nomon, ho Eternulo, Dio Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Mi ne sidis en interkonsiliĝo de mokantoj kaj ne ĝojis kun ili; mi sidis solece antaŭ Via mano, ĉar Vi plenigis min per indigno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Kial mia malsano estas senfina, kaj mia vundo tiel malfacila, ke ĝi ne povas resaniĝi? Vi fariĝis por mi kiel malaperanta fonto de akvo nefidebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Tial tiele diras la Eternulo: Se vi revenos, tiam Mi denove starigos vin antaŭ Mi; se el senvaloraĵo vi eltiros la valoraĵon, vi fariĝos kiel Mia buŝo; ili revenos al vi, sed vi ne revenos al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Kaj Mi starigos vin por tiu popolo kiel fortikan kupran muron; ili batalos kontraŭ vi, sed ne venkos vin; ĉar Mi estas kun vi, por vin helpi kaj savi, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'Mi savos vin el la mano de malbonuloj, kaj Mi liberigos vin el la mano de tiranoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Kaj aperis al mi la vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Ne prenu al vi edzinon, kaj ne havu filojn nek filinojn, sur ĉi tiu loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Ĉar tiele diras la Eternulo pri la filoj kaj filinoj, kiuj naskiĝas sur ĉi tiu loko, pri iliaj patrinoj, kiuj naskas ilin, kaj pri iliaj patroj, kiuj naskigas ilin en ĉi tiu lando:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'Per diversaj doloraj mortoj ili mortos; ili ne estos priplorataj nek enterigitaj, ili estos kiel sterko sur la supraĵo de la tero; de glavo kaj de malsato ili pereos, kaj iliaj kadavroj estos manĝaĵo por la birdoj de la ĉielo kaj por la bestoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Ĉar tiele diras la Eternulo: Ne eniru en la domon de plorado, ne iru funebri, kaj ne konsolu ilin; ĉar Mi forprenis de tiu popolo Mian pacon, diras la Eternulo, la favorkorecon kaj la kompaton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Mortos la granduloj kaj la malgranduloj en tiu lando; ili ne estos enterigitaj nek priplorataj; oni ne faros al si tranĉojn nek kalvaĵon pro ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Oni ne disdonos inter ili panon de funebro, por konsoli ilin pri la mortinto, kaj oni ne trinkigos al ili kalikon de konsolo pri ilia patro kaj pri ilia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Ankaŭ en la domon de festeno ne iru, por sidi kun ili, por manĝi kaj trinki.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Ĉar tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi forigos de ĉi tiu loko antaŭ viaj okuloj kaj dum via vivo la sonojn de ĝojo kaj la sonojn de gajeco, la voĉon de fianĉo kaj la voĉon de fianĉino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'Kiam vi diros al tiu popolo ĉiujn ĉi tiujn vortojn, kaj ili diros al vi: Pro kio la Eternulo eldiris pri ni tiun tutan grandan malfeliĉon? kia estas nia krimo, kaj kia estas nia peko, kiun ni pekis antaŭ la Eternulo, nia Dio? -');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'tiam diru al ili: Pro tio, ke viaj patroj forlasis Min, diras la Eternulo, kaj sekvis aliajn diojn kaj servis kaj adorkliniĝis al ili, dum Min ili forlasis kaj Mian instruon ne obeis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'kaj vi agas ankoraŭ pli malbone ol viaj patroj, kaj ĉiu el vi sekvas la obstinecon de sia malbona koro, ne aŭskultante Min;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'tial Mi elĵetos vin el ĉi tiu lando en landon, kiun ne konis vi nek viaj patroj, kaj vi servos tie al aliaj dioj tage kaj nokte, ĉar Mi ne donos al vi indulgon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Pro tio jen venos tempo, diras la Eternulo, kiam oni ne plu diros: Vivas la Eternulo, kiu elkondukis la Izraelidojn el la lando Egipta;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'sed: Vivas la Eternulo, kiu elkondukis la Izraelidojn el la lando norda, kaj el ĉiuj landoj, kien Li dispelis ilin; ĉar Mi revenigos ilin en ilian landon, kiun Mi donis al iliaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Jen Mi sendos multe da fiŝkaptistoj, diras la Eternulo, por kapti ilin; poste Mi sendos multe da ĉasistoj, por ĉasi ilin de ĉiu monto, de ĉiu monteto, kaj el la fendoj de la rokoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Ĉar Miaj okuloj vidas ĉiujn iliajn vojojn; ili ne estas kovritaj antaŭ Mi, kaj iliaj malbonagoj ne estas kaŝitaj antaŭ Miaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Antaŭ ĉio Mi duoble pagos pro iliaj malbonagoj kaj iliaj pekoj, pro tio, ke ili malpurigis Mian landon: per la kadavroj de siaj idoloj kaj per siaj abomenindaĵoj ili plenigis Mian heredaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Ho Eternulo, mia forto kaj mia fortikeco kaj mia rifuĝo en tempo de malfeliĉo! al Vi venos nacioj de la randoj de la tero, kaj diros: Nur malverajn diojn heredis niaj patroj; ili estas vantaĵo, ili taŭgas por nenio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Ĉu povas homo fari al si diojn? ili ne estas ja dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'Tial jen Mi prudentigos ilin; tiun fojon Mi sentigos al ili Mian manon kaj Mian forton; kaj ili ekscios, ke Mia nomo estas Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'La peko de Jehuda estas skribita per fera skribilo, per diamanta pinto, sur la tabelo de ilia koro kaj sur la kornoj de iliaj altaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Iliaj filoj bone memoras iliajn altarojn kaj iliajn sanktajn stangojn ĉe la verdaj arboj sur la altaj montetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Ĉu Mia monto estas sur la kampo? vian havon kaj ĉiujn viajn trezorojn Mi fordonos por disrabo, viajn altaĵojn pro la pekoj en ĉiuj viaj limoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Kaj vi estos elpuŝita el la heredaĵo, kiun Mi donis al vi, kaj Mi servigos vin al viaj malamikoj en lando, kiun vi ne konas; ĉar vi ekbruligis fajron de Mia kolero, ĝi flamos eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Tiele diras la Eternulo: Malbenita estas la homo, kiu fidas homon kaj faris karnon lia apogo kaj kies koro forturnis sin de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Li estos kiel nuda arbo en la dezerto; li ne vidos, kiam venos bono; li loĝos sur sunbruligita loko, en lando senfrukta kaj ne loĝata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Benita estas la homo, kiu fidas la Eternulon, kaj la Eternulo estos lia apogo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Li estos kiel arbo, plantita ĉe akvo kaj etendanta siajn radikojn al torento; ĝi ne timas, kiam venas varmego; ĝiaj folioj restas verdaj, kaj en tempo de sekeco ĝi ne zorgas kaj ne ĉesas doni fruktojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Malica estas ĉies koro, kaj nefidinda; kiu povas ĝin ekkoni?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Sed Mi, la Eternulo, trapenetras la koron, esploras la internon, por redoni al ĉiu laŭ lia konduto, laŭ la fruktoj de liaj agoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Perdriko kovas ovojn, kiujn ĝi ne naskis; tia estas tiu, kiu akiras riĉecon per rimedoj maljustaj: en la mezo de sia vivo li ĝin perdos, kaj en la fino li restos malsaĝulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Sed la loko de nia sanktejo estas trono de gloro, alta de tempo antikva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Ho Eternulo, espero de Izrael! ĉiuj, kiuj forlasas Vin, estos hontigitaj, la defalintoj estos skribitaj sur la tero; ĉar ili forlasis la Eternulon, la fonton de viva akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Sanigu min, ho Eternulo, kaj mi estos sanigita; savu min, kaj mi estos savita; ĉar Vi estas mia gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Jen ili diras al mi: Kie estas la vorto de la Eternulo? ĝi plenumiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Sed mi ne forklinis min de tio, esti paŝtisto laŭ Via montro; la tagon de malfeliĉo mi ne deziris, tion Vi scias; kio eliris el mia buŝo, tio estis ĝusta antaŭ Via vizaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Ne estu por mi terura, Vi, mia rifuĝejo en la tago de mizero!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Miaj persekutantoj estu hontigitaj, sed mi ne estu hontigita; ili tremu, sed mi ne tremu; venigu sur ilin tagon de mizero, kaj frapu ilin per duobla frapo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Tiele diris al mi la Eternulo: Iru kaj stariĝu en la pordego de la simpla popolo, tiu pordego, tra kiu eniras kaj eliras la reĝoj de Judujo, kaj en ĉiuj pordegoj de Jerusalem;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'kaj diru al ili: Aŭskultu la vorton de la Eternulo, ho reĝoj de Judujo, kaj ĉiuj Judoj kaj ĉiuj loĝantoj de Jerusalem, kiuj iras tra ĉi tiuj pordegoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Tiele diras la Eternulo: Gardu viajn animojn, kaj ne portu ŝarĝojn en la tago sabata, kaj ne enportu ilin tra la pordegoj de Jerusalem;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'kaj ne elportu ŝarĝon el viaj domoj en la tago sabata, kaj faru nenian laboron, sed sanktigu la tagon sabatan, kiel Mi ordonis al viaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Sed ili ne aŭskultis kaj ne alklinis sian orelon, sed obstinigis sian nukon, por ne aŭskulti kaj por ne akcepti moralinstruon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Se vi aŭskultos Min, diras la Eternulo, kaj ne portos ŝarĝon tra la pordegoj de ĉi tiu urbo en la tago sabata, sed vi sanktigos la tagon sabatan, farante en ĝi nenian laboron:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'tiam tra la pordegoj de ĉi tiu urbo irados reĝoj kaj princoj, sidantaj sur la trono de David, veturantaj sur ĉaroj kaj ĉevaloj, ili kaj iliaj princoj, la Judoj kaj la loĝantoj de Jerusalem, kaj ĉi tiu urbo estos loĝata eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'Kaj oni venados el la urboj de Judujo, el la ĉirkaŭaĵoj de Jerusalem, el la lando de Benjamen, de la ebenaĵo, de la montoj, kaj de sudo, alportante bruloferojn kaj buĉoferojn kaj farunoferojn kaj olibanon kaj dankajn donacojn en la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Sed se vi ne obeos Min, ke vi sanktigu la tagon sabatan kaj ne portu ŝarĝon, irante tra la pordegoj de Jerusalem en la tago sabata: tiam Mi ekbruligos en ĝiaj pordegoj fajron, kiu ekstermos la palacojn de Jerusalem kaj ne estingiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Jen estas la vorto, kiu aperis al Jeremia de la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Leviĝu kaj iru en la domon de la potisto, kaj tie Mi aŭdigos al vi Miajn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Kaj mi iris en la domon de la potisto, kaj jen li laboras sur la stablo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Kaj kiam difektiĝis en la mano de la potisto la vazo, kiun li estis faranta el argilo, li faris denove alian vazon, kian al li plaĉis fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Tiam aperis al mi la jena vorto de la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Ĉu Mi ne povas agi kun vi, ho domo de Izrael, kiel tiu potisto? diras la Eternulo; jen kiel la argilo en la mano de la potisto, tiel vi estas en Mia mano, ho domo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Unu momenton Mi decidas pri popolo kaj pri regno, ke Mi ĝin elŝiros, disfrapos, kaj pereigos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'sed se tiu popolo pentas sian malbonecon, pro kiu Mi decidis pri ĝi, tiam Mi ankaŭ pentas pri la malfeliĉo, kiun Mi intencis fari al ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Alian fojon Mi decidas pri popolo kaj pri regno, ke Mi ĝin fortikigos kaj enradikigos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'sed se ĝi faras malbonon antaŭ Miaj okuloj, ne aŭskultante Mian voĉon, tiam Mi pentas pri la bono, kiun Mi intencis fari al ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Kaj nun diru al la Judoj kaj al la loĝantoj de Jerusalem jene: Tiele diras la Eternulo: Jen Mi preparas por vi malbonon kaj havas intencon kontraŭ vi; revenu do ĉiu de sia malbona vojo, kaj rebonigu vian konduton kaj viajn agojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Sed ili diras: Vane, ni sekvos niajn intencojn, kaj ĉiu el ni agos laŭ la obstineco de sia malbona koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Tial tiele diras la Eternulo: Demandu inter la nacioj, ĉu iu aŭdis ion similan; multe da abomenindaĵoj faris la filino de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Ĉu la neĝo de Lebanon ĉesas liveri akvon al Miaj kampoj? ĉu ĉesigas sian iradon la malvarma akvo, fluanta de malproksime?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Sed Mia popolo forgesis Min, incensas al idoloj; per sia konduto ili senordigas la vojojn eternajn, por iri laŭ vojo ne ebenigita,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'por fari sian landon dezerto, eterna mokataĵo, tiel, ke ĉiu, kiu trapasas ĝin, miras kaj balancas la kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Kiel per orienta vento Mi disblovos ilin antaŭ la malamiko; la nukon kaj ne la vizaĝon Mi montros al ili en la tago de ilia pereo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Ili diris: Ni iru kaj interkonsiliĝu kontraŭ Jeremia; ĉar ne malaperis la leĝinstruo ĉe la pastro, nek konsilo ĉe la saĝulo, nek parolo ĉe la profeto; venu, ni batu lin per la lango, kaj ni ne atentu liajn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Atentu min, ho Eternulo, kaj aŭskultu la voĉon de miaj kontraŭuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Ĉu oni devas repagi bonon per malbono? ĉar ili fosis foson por mia animo. Memoru, kiel mi staris antaŭ Vi, por paroli bonon pri ili, por forklini de ili Vian koleron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Tial elmetu iliajn filojn al malsato kaj transdonu ilin al glavo; iliaj edzinoj fariĝu seninfanaj kaj vidvinoj, iliaj viroj estu frapitaj de morto, iliaj junuloj estu mortigitaj de glavo en milito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Kriado estu aŭdata el iliaj domoj, kiam Vi subite venigos sur ilin amasojn, pro tio, ke ili fosis foson, por kapti min, kaj reton ili metis antaŭ miajn piedojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Vi, ho Eternulo, scias ĉiujn iliajn intencojn kontraŭ mi, por mortigi min; ne pardonu ilian malbonagon, kaj ilian pekon antaŭ Vi ne elviŝu; faligu ilin antaŭ Vi; agu kontraŭ ili en la tempo de Via kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Tiele diris la Eternulo: Iru kaj aĉetu argilan kruĉon de potisto, kaj, preninte kelkajn el la plejaĝuloj de la popolo kaj el la plejaĝuloj de la pastroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'iru en la valon de la filo de Hinom, kiu estas antaŭ la Pordego de Argilaĵoj, kaj proklamu tie la vortojn, kiujn Mi diros al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'Kaj diru: Aŭskultu la vorton de la Eternulo, ho reĝoj de Judujo kaj loĝantoj de Jerusalem! tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi venigos sur ĉi tiun lokon tian malfeliĉon, ke al ĉiu, kiu aŭdos pri ĝi, eksonoros liaj oreloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Pro tio, ke ili forlasis Min, kaj malpurigis ĉi tiun lokon, kaj incensis sur ĝi al aliaj dioj, kiujn ne konis ili nek iliaj patroj nek la reĝoj de Judujo, kaj plenigis ĉi tiun lokon per sango de senkulpuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'kaj konstruis altaĵojn al Baal, por forbruligi siajn filojn kiel bruloferojn al Baal, kion Mi ne ordonis kaj ne diris, kaj kio eĉ ne venis en Mian kapon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'pro tio jen venos tempo, diras la Eternulo, kiam oni jam nomos ĉi tiun lokon ne Tofet kaj valo de la filo de Hinom, sed valo de mortigado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Kaj Mi detruos sur ĉi tiu loko la planon de Judujo kaj Jerusalem; kaj Mi faligos ilin de glavo antaŭ iliaj malamikoj, kaj de la mano de tiuj, kiuj serĉas ilian animon, kaj Mi donos iliajn kadavrojn kiel manĝaĵon al la birdoj de la ĉielo kaj al la bestoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Kaj Mi faros ĉi tiun urbon dezerto kaj mokataĵo; ĉiu, kiu preterpasos ĝin, miros kaj mokos ĉiujn ĝiajn frapojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'Kaj Mi manĝigos al ili la karnon de iliaj filoj kaj la karnon de iliaj filinoj, kaj ĉiu manĝos la karnon de sia proksimulo, dum la sieĝo, kaj en la premado, per kiu premos ilin iliaj malamikoj kaj la serĉantoj de iliaj animoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Kaj disrompu la kruĉon antaŭ la okuloj de tiuj viroj, kiuj venis kun vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'kaj diru al ili: Tiele diras la Eternulo Cebaot: Tiele Mi disrompos ĉi tiun popolon kaj ĉi tiun urbon, kiel oni disrompas vazon de potisto, ke ĝi ne povas esti tutaĵigita; kaj oni enterigos en Tofet, ĉar ne ekzistos alia loko por enterigado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Tiele Mi agos kun ĉi tiu loko, diras la Eternulo, kaj kun ĝiaj loĝantoj, kaj Mi faros ĉi tiun lokon simila al Tofet.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'Kaj la domoj de Jerusalem kaj la domoj de la reĝoj de Judujo estos malpuraj, kiel la loko Tofet, ĉiuj domoj, sur kies tegmentoj oni incensis al la tuta armeo de la ĉielo kaj verŝis verŝoferojn al aliaj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Kaj Jeremia venis de Tofet, kien sendis lin la Eternulo por profeti; kaj li stariĝis sur la korto de la domo de la Eternulo, kaj diris al la tuta popolo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, 'Tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi venigos sur ĉi tiun urbon kaj sur ĉiujn ĝiajn vilaĝojn la tutan malfeliĉon, kiun Mi eldiris pri ĝi; ĉar ili obstinigis sian nukon kaj ne aŭskultas Miajn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Kiam la pastro Paŝĥur, filo de Imer, la ĉefa oficisto en la domo de la Eternulo, aŭdis, kiel Jeremia profetis ĉion diritan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'Paŝĥur batis la profeton Jeremia, kaj metis lin en karceron, kiu estis en la supra Pordego de Benjamen ĉe la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'La sekvantan tagon Paŝĥur ellasis Jeremian el la karcero; tiam Jeremia diris al li: La Eternulo nomas vin ne Paŝĥur, sed Teruro-ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Ĉar tiele diras la Eternulo: Jen Mi faros vin teruro por vi mem kaj por ĉiuj viaj amikoj, kaj ili falos de la glavo de siaj malamikoj; viaj okuloj tion vidos; kaj la tutan Judujon Mi transdonos en la manojn de la reĝo de Babel, kiu ekzilos ilin en Babelon kaj mortigos ilin per la glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Kaj la tutan havon de ĉi tiu urbo kaj ĝian tutan laborakiron kaj ĉiujn ĝiajn valoraĵojn kaj ĉiujn trezorojn de la reĝoj de Judujo Mi transdonos en la manon de iliaj malamikoj, kiuj prirabos kaj prenos kaj forportos ilin en Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Kaj vi, Paŝĥur, kaj ĉiuj loĝantoj de via domo iros en kaptitecon, venos Babelon, kaj tie vi mortos, kaj tie vi estos enterigitaj, vi kaj ĉiuj viaj amikoj, al kiuj vi profetis malvere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Ho Eternulo, Vi fortiris min post Vi, kaj mi lasis fortiri min; Vi estas pli forta ol mi kaj venkis min; kaj mi fariĝis objekto de ĉiutaga mokado, ĉiu mokas min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Ĉar de la tempo, kiam mi ekparolis, kriis pri maljusteco, vokis pri rabado, la vorto de la Eternulo fariĝis por mi kaŭzo de honto kaj de ĉiutaga mokado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Mi diris al mi: Mi ne rememorigos pri Li, mi ne plu parolos en Lia nomo; sed tio fariĝis en mia koro kiel flamanta fajro, penetrinta en miajn ostojn, kaj mi laciĝis de retenado kaj ne plu povis elteni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Ĉar mi aŭdas la insultadon de multaj kaj minacadon ĉirkaŭe: Akuzu, ni akuzu lin! Ĉiuj, kiuj vivas pace kun mi, observas min de flanke: Eble li forlogiĝos, tiam ni venkos lin kaj venĝos al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Sed la Eternulo estas kun mi kiel potenca heroo, tial miaj persekutantoj falos kaj ne venkos; ili estos forte hontigitaj pro tio, ke ili agis tiel malprudente; la honto estos eterna, ne forgesiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Ho Eternulo Cebaot, kiu elprovas virtulon kaj vidas la internon kaj la koron! faru, ke mi vidu Vian venĝon sur ili, ĉar al Vi mi transdonis mian proceson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Kantu al la Eternulo, gloru la Eternulon; ĉar Li savas la animon de malriĉulo el la mano de malbonaguloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Malbenita estu la tago, en kiu mi naskiĝis; la tago, en kiu mia patrino min naskis, ne estu benita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Malbenita estu la homo, kiu sciigis al mia patro kaj diris: Virseksa infano estas naskita al vi, kaj per tio li faris al li grandan ĝojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Tiu homo estu kiel la urboj, kiujn la Eternulo senkompate ruinigis; li aŭdu kriadon matene kaj ploregadon tagmeze.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'Kial mi ne estis mortigita en la utero, ke mia patrino estu mia tombo kaj ŝia ventro restu graveda por ĉiam?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Kial mi eliris el la utero, por vidi malfacilan penadon kaj mizeron kaj por ke mia vivo pasu en honto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Jen estas la vorto, kiu aperis al Jeremia de la Eternulo, kiam la reĝo Cidkija sendis al li Paŝĥuron, filon de Malkija, kaj la pastron Cefanja, filo de Maaseja, por diri:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'Volu demandi pri ni la Eternulon, ĉar Nebukadnecar, reĝo de Babel, militas kontraŭ ni; eble la Eternulo faros al ni ion similan al ĉiuj Liaj mirakloj, kaj tiu foriros de ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Kaj Jeremia diris al ili: Tiele diru al Cidkija:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Tiele diras la Eternulo, Dio de Izrael: Jen Mi returnos la batalilojn, kiuj estas en viaj manoj kaj per kiuj vi batalas kontraŭ la reĝo de Babel, kaj kontraŭ la Ĥaldeoj, kiuj sieĝas vin ekstere de la murego, kaj Mi kolektos ilin meze de ĉi tiu urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'Kaj Mi batalos kontraŭ vi per mano etendita kaj per forta brako, en kolero, furiozo, kaj granda indigno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'Kaj Mi frapos la loĝantojn de ĉi tiu urbo, la homojn kaj la brutojn; de granda pesto ili mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Kaj post tio, diras la Eternulo, Cidkijan, reĝon de Judujo, kaj liajn servantojn, kaj la popolon, kaj tiujn, kiuj en ĉi tiu urbo restis de la pesto, de la glavo, kaj de la malsato, Mi transdonos en la manon de Nebukadnecar, reĝo de Babel, en la manon de iliaj malamikoj, kaj en la manon de tiuj, kiuj deziras ilian morton; kaj li mortigos ilin per glavo; li ne hezitos, ne indulgos, kaj ne kompatos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Kaj al ĉi tiu popolo diru: Tiele diras la Eternulo: Jen Mi proponas al vi vojon de vivo kaj vojon de morto:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'kiu restos en ĉi tiu urbo, tiu mortos de glavo aŭ de malsato aŭ de pesto; kaj kiu eliros kaj transdonos sin al la Ĥaldeoj, kiuj vin sieĝas, tiu restos vivanta, kaj lia animo estos lia akiro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Ĉar Mi turnis Mian vizaĝon kontraŭ ĉi tiun urbon por malbono, ne por bono, diras la Eternulo; en la manon de la reĝo de Babel ĝi estos transdonita, kaj li forbruligos ĝin per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Kaj koncerne la domon de la reĝo de Judujo aŭskultu la vorton de la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Domo de David! diras la Eternulo: Frue matene faru juĝon kaj savu prematon el la mano de premanto, por ke Mia kolero ne aperu kiel fajro kaj ĝi ne ekflamu pro viaj malbonagoj tiel, ke neniu povos ĝin estingi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Jen Mi iras kontraŭ vin, kiu staras en la valo, roko sur la ebenaĵo, diras la Eternulo, kontraŭ vin, kiuj diras: Kiu atakos nin? kaj kiu eniros en niajn loĝejojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Kaj Mi punos vin laŭ la fruktoj de viaj agoj, diras la Eternulo; kaj Mi ekbruligos fajron en ĝia arbaro, por ke ĝi ekstermu ĝian tutan ĉirkaŭaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Tiele diris la Eternulo: Iru en la domon de la reĝo de Judujo, kaj diru tie jenon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'diru: Aŭskultu la vorton de la Eternulo, ho reĝo de Judujo, kiu sidas sur la trono de David, vi, kaj viaj servantoj, kaj via popolo, kiu iras tra ĉi tiuj pordegoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Tiele diras la Eternulo: Faru juĝon kaj juston, kaj savu prematon el la mano de premanto; ne ofendu kaj ne premu fremdulon, orfon, aŭ vidvinon, kaj sangon senkulpan ne verŝu sur ĉi tiu loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Ĉar se vi plenumos ĉi tiun diron, tiam tra la pordegoj de ĉi tiu domo irados reĝoj, sidantaj sur la trono de David, veturantaj sur ĉaroj kaj sur ĉevaloj, li mem kaj liaj servantoj kaj lia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Sed se vi ne obeos tiujn vortojn, tiam-Mi ĵuras per Mi, diras la Eternulo-ĉi tiu domo fariĝos ruino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Ĉar tiele diras la Eternulo koncerne la domon de la reĝo de Judujo: Vi estas al Mi Gilead, supro de Lebanon; kaj tamen Mi faros vin dezerto, urboj ne loĝataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'Mi starigos kontraŭ vi ekstermantojn, ĉiun kun liaj bataliloj, kaj ili dehakos viajn plej bonajn cedrojn kaj ĵetos en fajron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'Kaj multe da nacioj preterpasos ĉi tiun urbon, kaj ili diros unu al la alia: Pro kio la Eternulo agis tiele kun ĉi tiu granda urbo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'Kaj oni respondos: Pro tio, ke ili forlasis la interligon de la Eternulo, ilia Dio, kaj adorkliniĝis al aliaj dioj kaj servis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Ne ploru pri mortinto kaj ne funebru pri li; sed ploru forte pri tiu, kiu foriras, ĉar li ne plu revenos kaj ne revidos la landon de sia naskiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Ĉar tiele diras la Eternulo pri Ŝalum, filo de Joŝija, reĝo de Judujo, kiu reĝis post sia patro Joŝija kaj foriris de ĉi tiu loko: Li ne plu revenos ĉi tien;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'sed sur la loko, kien oni transloĝigis lin en kaptitecon, tie li mortos, kaj ĉi tiun landon li ne plu vidos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Ve al tiu, kiu konstruas sian domon per malbonagoj kaj siajn ĉambrojn en maljusteco; kiu devigas sian proksimulon labori vane kaj ne donas al li lian prolaboran pagon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'kiu diras: Mi konstruos al mi grandan domon kaj vastajn ĉambrojn; kaj trahakas al si fenestrojn kaj kadras ilin per cedro kaj kolorigas per cinabro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Ĉu vi reĝos per tio, ke vi ĉirkaŭis vin per cedraĵo? via patro ja ankaŭ manĝis kaj trinkis, sed li agis laŭjuĝe kaj juste, kaj tiam estis al li bone.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Li juĝadis la aferojn de premito kaj malriĉulo, kaj tiam estis bone. Ĉu ne tio signifas koni Min? diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Sed viaj okuloj kaj via koro celas nur malhonestan profiton, verŝadon de senkulpa sango, faradon de rabado kaj de premado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Tial tiele diras la Eternulo pri Jehojakim, filo de Joŝija, reĝo de Judujo: Oni ne lamentos pri li: Ho ve, mia frato! ho ve, fratino! oni ne lamentos pri li: Ho ve, sinjoro! ho ve, glorulo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Per enterigo de azeno li estos enterigita: oni trenos lin kaj ĵetos malproksimen de la pordegoj de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Supreniru sur Lebanonon kaj kriu, kaj en Baŝan laŭtigu vian voĉon, kaj kriu de Abarim; ĉar disbatitaj estas ĉiuj viaj amantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Mi parolis al vi, kiam vi estis ankoraŭ en bona stato, sed vi diris: Mi ne volas aŭskulti. Tia estis via konduto detempe de via juneco, ke vi ne aŭskultis Mian voĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Ĉiujn viajn paŝtistojn forblovos la vento, kaj viaj amantoj iros en kaptitecon; tiam vin kovros honto kaj malhonoro pro ĉiuj viaj malbonagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Vi sidas sur Lebanon, vi faris al vi neston inter cedroj; kiel mizera vi estos, kiam atakos vin doloroj, kiel doloroj de naskantino!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'Kiel Mi vivas, diras la Eternulo, se Konja, filo de Jehojakim, reĝo de Judujo, eĉ estus sigelringo sur Mia dekstra mano, eĉ de tie Mi vin deŝirus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'Kaj Mi transdonos vin en la manon de tiuj, kiuj celas vian morton, kaj en la manon de tiuj, kiujn vi timegas, en la manon de Nebukadnecar, reĝo de Babel, kaj en la manon de la Ĥaldeoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Kaj Mi ĵetos vin, kaj vian patrinon, kiu naskis vin, en alian landon, kie vi ne naskiĝis; kaj tie vi mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Sed en la landon, kien ili tre dezirus reveni, tien ili ne revenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Ĉu ĉi tiu homo, Konja, estas objekto malestimata, forpuŝita? ĉu li estas vazo neamata? kial ili estas forĵetitaj, li kaj lia idaro, ĵetitaj en landon, kiun ili ne konis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'Ho tero, tero, tero! aŭskultu la vorton de la Eternulo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'Tiele diras la Eternulo: Enskribu ĉi tiun homon kiel seninfanan, kiel homon, kiu ne havos sukceson en sia vivo; ĉar neniu el lia idaro sukcesos sidi sur la trono de David aŭ regos iam en Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Ve al la paŝtistoj, kiuj pereigas kaj diskurigas la ŝafojn de Mia paŝtataro! diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Tial tiele diras la Eternulo, Dio de Izrael, pri la paŝtistoj, kiuj paŝtas Mian popolon: Vi diskurigis Miajn ŝafojn kaj dispelis ilin kaj ne observis ilin; jen Mi punos sur vi viajn malbonajn agojn, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Sed Mi kolektos la restaĵon de Miaj ŝafoj el ĉiuj landoj, kien Mi dispelis ilin, kaj Mi revenigos ilin sur ilian paŝtejon; kaj ili donos fruktojn kaj multiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'Kaj Mi starigos super ili paŝtistojn, por ke ili paŝtu ilin; kaj ili jam ne timos kaj ne tremos kaj ne estos atakataj, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Jen venos tempo, diras la Eternulo, kaj Mi aperigos de David markoton virtan, kaj ekregos reĝo, kaj li estos prudenta, kaj li farados juĝon kaj justecon sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'En lia tempo Jehuda estos savita kaj Izrael loĝos sendanĝere; kaj jen estas la nomo, per kiu oni lin nomos: La Eternulo estas nia justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Pro tio jen venos tempo, diras la Eternulo, kiam oni ne plu diros: Vivas la Eternulo, kiu elkondukis la Izraelidojn el la lando Egipta;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'sed: Vivas la Eternulo, kiu elirigis kaj venigis la idaron de la domo de Izrael el la lando norda, kaj el ĉiuj landoj, kien Mi dispelis ilin; kaj ili ekloĝos en sia lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Pri la profetoj. Disŝiriĝas en mi mia koro, ĉiuj miaj ostoj tremas; mi fariĝis kiel ebriulo, kiel homo, senfortigita de vino, antaŭ la Eternulo kaj antaŭ Liaj sanktaj vortoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Ĉar la lando estas plena de adultuloj, ĉar la lando ploras de malbeno; sekiĝis la paŝtejoj de la stepo; ilia celado estas malpia, kaj ilia forto estas en malvereco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Ĉar profeto kaj pastro hipokritas; eĉ en Mia domo Mi trovas iliajn malbonagojn, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Pro tio ilia vojo estos kiel glitigaj lokoj en mallumo: ili glitos tie kaj falos; ĉar Mi venigos sur ilin malfeliĉon en la jaro, kiam Mi punvizitos ilin, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Ĉe la profetoj de Samario Mi vidis stultecon: ili profetis en la nomo de Baal, kaj erarigis Mian popolon Izrael;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'sed ĉe la profetoj de Jerusalem Mi vidis ion teruran: ili adultas, iras vojon de mensogoj, kaj subtenas la manojn de malbonaguloj, por ke neniu el ili konvertu sin de sia malboneco; ili ĉiuj fariĝis por Mi kiel Sodom, kaj la loĝantoj de la urbo kiel Gomora.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Tial tiele diras la Eternulo Cebaot pri la profetoj: Jen Mi manĝigos al ili vermuton kaj trinkigos al ili akvon maldolĉan; ĉar de la profetoj de Jerusalem disvastiĝas malpieco en la tuta lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Tiele diras la Eternulo Cebaot: Ne aŭskultu la vortojn de la profetoj, kiuj profetas al vi; ili trompas vin; ili predikas vizion de sia koro, sed ne el la buŝo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Ili diras al Miaj malŝatantoj: La Eternulo diris, ke al vi estos paco; kaj al ĉiu, kiu sekvas la obstinecon de sia koro, ili diras: Ne trafos vin malfeliĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Sed kiu staris en la konsilo de la Eternulo, kaj vidis kaj aŭdis Lian vorton? kiu aŭdis Lian vorton kaj komprenis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Jen eliros ventego de la Eternulo en kolero, ventego turniĝanta; ĝi falos sur la kapon de la malpiuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Ne kvietiĝos la kolero de la Eternulo, ĝis Li estos farinta kaj ĝis Li estos plenuminta la intencojn de Sia koro; en la tempo estonta vi tion komprenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Mi ne sendis tiujn profetojn, sed ili mem kuris; Mi nenion diris al ili, tamen ili profetas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Se ili estus starintaj en Mia konsilo, ili aŭdigus Miajn vortojn al Mia popolo kaj deturnus ilin de ilia malbona vojo kaj de iliaj malbonaj agoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Ĉu Mi estas nur Dio de proksime? diras la Eternulo; ĉu Mi ne estas ankaŭ Dio de malproksime?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Ĉu homo povas kaŝi sin en tia sekreta loko, kie Mi lin ne vidus? diras la Eternulo; ĉu ne Mi plenigas la ĉielon kaj la teron? diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Mi aŭdas, kion diras la profetoj, kiuj en Mia nomo profetas malveraĵon; ili diras: Mi sonĝis, mi sonĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Kiel longe tio daŭros en la koro de la profetoj, kiuj profetas malveraĵon, profetas la trompaĵon de sia koro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'Ili pensas, ke ili forgesigos al Mia popolo Mian nomon per siaj sonĝoj, kiujn ili rakontas unu al la alia, tiel same, kiel iliaj patroj forgesis Mian nomon pro Baal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Profeto, kiu vidis sonĝon, rakontu sonĝon; kaj tiu, al kiu aperis Mia vorto, raportu Mian vorton vere. Kio komuna estas inter pajlo kaj greno? diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Ĉu Mia vorto ne estas kiel fajro, diras la Eternulo, kaj kiel martelo, kiu disbatas rokon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Tial jen Mi turnos Min kontraŭ la profetojn, diras la Eternulo, kiuj ŝtelas Miajn vortojn unu de la alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Jen Mi turnos Min kontraŭ la profetojn, diras la Eternulo, kiuj esprimas sian propran parolon, kaj diras: Li diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Jen Mi turnos Min kontraŭ tiujn, kiuj profetas malverajn sonĝojn, diras la Eternulo, kaj rakontas ilin kaj erarigas Mian popolon per siaj mensogaĵoj kaj per sia senprudenteco, dum Mi ne sendis ilin kaj ne donis al ili ordonojn, kaj ili ja alportas al ĉi tiu popolo nenian utilon, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Se ĉi tiu popolo aŭ profeto aŭ pastro demandos vin, dirante: Kia estas la ŝarĝo de la Eternulo? tiam diru al ili koncerne la ŝarĝon: Mi forlasos vin, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'Kaj se iu el la profetoj aŭ pastroj aŭ el la popolo diros: Ŝarĝo de la Eternulo, Mi punos tiun homon kaj lian domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Nur tiel diru ĉiu al sia proksimulo kaj ĉiu al sia frato: Kion respondis la Eternulo? aŭ: Kion diris la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'Kaj la esprimon: Ŝarĝo de la Eternulo, ne plu uzu; ĉar por ĉiu homo lia vorto fariĝos ŝarĝo, pro tio, ke vi malĝustigas la vortojn de la vivanta Dio, de la Eternulo Cebaot, nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Tiele diru al la profeto: Kion respondis al vi la Eternulo? kion diris la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Sed se vi diros: Ŝarĝo de la Eternulo, tiam tiele diras la Eternulo: Ĉar vi eldiris tiujn vortojn: Ŝarĝo de la Eternulo, dum Mi sendis, por diri al vi, ke vi ne uzu la esprimon: Ŝarĝo de la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'tial jen Mi tute forlasos kaj forpelos de antaŭ Mia vizaĝo vin, kaj la urbon, kiun Mi donis al vi kaj al viaj patroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'kaj Mi metos sur vin eternan honton kaj eternan malhonoron, kiu ne forgesiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'La Eternulo montris al mi: jen estas du korboj kun figoj, starigitaj antaŭ la templo de la Eternulo, post kiam Nebukadnecar, reĝo de Babel, forkondukis el Jerusalem Jeĥonjan, filon de Jehojakim, reĝon de Judujo, kaj la princojn de Judujo kaj la ĉarpentistojn kaj seruristojn, kaj venigis ilin en Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Unu korbo estis kun figoj tre bonaj, kiel estas la figoj plej frue maturiĝintaj; la dua korbo estis kun figoj tre malbonaj, kiujn pro ilia malboneco oni ne povas manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Kaj la Eternulo diris al mi: Kion vi vidas, Jeremia? Kaj mi respondis: Figojn; la bonaj figoj estas tre bonaj, kaj la malbonaj estas tre malbonaj, tiel, ke pro ilia malboneco oni ne povas ilin manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Tiam aperis al mi la vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'Tiele diras la Eternulo, Dio de Izrael: Simile al ĉi tiuj bonaj figoj, Mi distingos por bono la forkondukitajn Judojn, kiujn Mi forsendis de ĉi tiu loko en la landon Ĥaldean;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'kaj Mi direktos sur ilin Miajn okulojn por bono, kaj Mi revenigos ilin en ĉi tiun landon, kaj Mi aranĝos ilin, ne ruinigos, Mi plantos ilin, ne elŝiros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Kaj Mi donos al ili koron, ke ili konu Min, ke Mi estas la Eternulo; ili estos Mia popolo, kaj Mi estos ilia Dio; ĉar ili konvertiĝos al Mi per sia tuta koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Sed koncerne la malbonajn figojn, kiujn oni ne povas manĝi pro ilia malboneco, tiele diras la Eternulo: Al ili Mi similigos Cidkijan, reĝon de Judujo, kaj liajn princojn, kaj la restintajn Jerusalemanojn, kiuj restis en ĉi tiu lando kaj kiuj loĝas en la lando Egipta;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'kaj Mi donos al ili suferadon kaj mizeron en ĉiuj regnoj de la tero, Mi faros ilin objekto de honto, de ekzemplo, de moko, kaj de malbeno sur ĉiuj lokoj, kien Mi dispelos ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'kaj Mi sendos sur ilin glavon, malsaton, kaj peston, ĝis Mi ekstermos ilin el la lando, kiun Mi donis al ili kaj al iliaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Jen estas la vorto, kiu aperis al Jeremia pri la tuta Juda popolo en la kvara jaro de Jehojakim, filo de Joŝija, reĝo de Judujo, tio estas en la unua jaro de Nebukadnecar, reĝo de Babel,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'kaj kiun la profeto Jeremia proklamis al la tuta Juda popolo kaj al ĉiuj loĝantoj de Jerusalem, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'De post la dek-tria jaro de Joŝija, filo de Amon, reĝo de Judujo, ĝis la nuna tago, en la daŭro de dudek tri jaroj, aperadis al mi la vorto de la Eternulo, kaj mi paroladis al vi, konstante paroladis; sed vi ne aŭskultis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'La Eternulo sendis al vi ĉiujn Siajn servantojn, la profetojn; ĉiutage Li sendadis; sed vi ne aŭskultis, vi ne alklinis vian orelon, por aŭskulti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'Ili diris: Deturnu vin ĉiu de sia malbona vojo kaj de viaj malbonaj agoj, kaj loĝu sur la tero, kiun la Eternulo donis al vi kaj al viaj patroj de ĉiam kaj por ĉiam;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'kaj ne sekvu aliajn diojn, servante kaj adorkliniĝante al ili, kaj ne kolerigu Min per la faritaĵo de viaj manoj, por ke Mi ne faru al vi malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Sed vi ne aŭskultis Min, diras la Eternulo; vi kolerigis Min per la faritaĵo de viaj manoj por via malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Tial tiele diras la Eternulo Cebaot: Pro tio, ke vi ne aŭskultis Miajn vortojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'jen Mi sendos kaj kolektos ĉiujn nordajn gentojn, diras la Eternulo, kaj Mian servanton Nebukadnecar, reĝo de Babel, kaj Mi venigos ilin sur ĉi tiun landon kaj sur ĝiajn loĝantojn kaj sur ĉiujn naciojn ĉirkaŭe; kaj Mi elmetos ilin al ekstermo, kaj Mi faros ilin ruinoj, mokataĵo, kaj eterna dezertaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'Kaj Mi ĉesigos ĉe ili la sonojn de ĝojo kaj la sonojn de gajeco, la voĉon de fianĉo kaj la voĉon de fianĉino, la bruon de muelilo kaj la lumon de lucerno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'Kaj ĉi tiu tuta lando fariĝos ruino kaj dezerto; kaj tiuj nacioj servos al la reĝo de Babel dum sepdek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Sed kiam finiĝos la sepdek jaroj, Mi punos la reĝon de Babel kaj tiun nacion, diras la Eternulo, pro ĝiaj malbonagoj, kaj la landon Ĥaldean, kaj Mi faros ĝin eterna dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'Kaj Mi plenumos super tiu lando ĉiujn Miajn vortojn, kiujn Mi diris pri ĝi, ĉion, kio estas skribita en ĉi tiu libro, kion Jeremia profetis pri ĉiuj nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Ĉar ankaŭ ilin sklavigos potencaj nacioj kaj grandaj reĝoj, kaj Mi repagos al ili laŭ iliaj agoj kaj laŭ la faroj de iliaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Ĉar tiele diras al mi la Eternulo, Dio de Izrael: Prenu el Mia mano ĉi tiun pokalon de la vino de furiozo, kaj trinkigu el ĝi ĉiujn naciojn, al kiuj Mi sendas vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'Ili trinku, ili ŝanceliĝu kaj freneziĝu antaŭ la glavo, kiun Mi sendos sur ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Kaj mi prenis la pokalon el la mano de la Eternulo, kaj trinkigis al ĉiuj popoloj, al kiuj sendis min la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'al Jerusalem kaj al la urboj de Judujo, al iliaj reĝoj kaj al iliaj eminentuloj, por fari ilin dezertaĵo kaj ruino, mokataĵo kaj malbenataĵo, kiel tio estas nun;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'al Faraono, reĝo de Egiptujo, kaj al liaj servantoj kaj al liaj eminentuloj kaj al lia tuta popolo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'kaj al ĉiuj diversgentaj popoloj kaj al ĉiuj reĝoj de la lando Uc kaj al ĉiuj reĝoj de la lando Filiŝta kaj al Aŝkelon kaj al Gaza kaj al Ekron kaj al la restaĵo de Aŝdod;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'al Edom kaj al Moab kaj al la Amonidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'kaj al ĉiuj reĝoj de Tiro kaj al ĉiuj reĝoj de Cidon kaj al la reĝoj de la insuloj trans la maro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'al Dedan, al Tema, al Buz, kaj al ĉiuj, kiuj tondas la harojn sur la tempioj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'kaj al ĉiuj reĝoj de Arabujo, kaj al ĉiuj reĝoj de la diversgentaj popoloj, loĝantaj en la dezerto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'kaj al ĉiuj reĝoj de Zimri kaj al ĉiuj reĝoj de Elam kaj al ĉiuj reĝoj de Medujo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'kaj al ĉiuj reĝoj de la nordo, la proksimaj kaj la malproksimaj, unu kontraŭ la alia, kaj al ĉiuj regnoj de la mondo, kiuj troviĝas sur la tero; kaj la reĝo de Ŝeŝaĥ trinkos post ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'Kaj diru al ili: Tiele diras la Eternulo Cebaot, Dio de Izrael: Trinku kaj ebriiĝu, vomu kaj falu, kaj ne leviĝu antaŭ la glavo, kiun Mi sendas sur vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Kaj se ili ne volos preni la pokalon el via mano, por trinki, tiam diru al ili: Tiele diras la Eternulo Cebaot: Vi nepre devas trinki.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Ĉar jen sur la urbon, kiu portas sur si Mian nomon, Mi komencas sendi suferojn; ĉu vi do restos senpunaj? vi ne restos sen puno, ĉar Mi vokas glavon sur ĉiujn loĝantojn de la tero, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Profetu al ili ĉion ĉi tion, kaj diru al ili: La Eternulo ekbruos de alte, kaj el Sia sankta loĝejo Li aŭdigos Sian voĉon; Li forte ekbruos kontraŭ Sian restadejon; kanton de vinpremantoj Li eksonigos super ĉiuj loĝantoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'La bruo atingos ĝis la fino de la tero; ĉar la Eternulo havos juĝon kontraŭ la popoloj, Li juĝos ĉiun karnon; la malpiulojn Li transdonos al glavo, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'Tiele diras la Eternulo Cebaot: Jen plago iros de popolo al popolo, kaj granda ventego leviĝos de la randoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'Kaj la mortigitoj de la Eternulo en tiu tago estos de unu fino de la tero ĝis la alia fino de la tero; ili ne estos priplorataj, ne estos kolektataj, nek enterigataj; ili fariĝos sterko sur la supraĵo de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Ploru, ho paŝtistoj, kriu kaj rulu vin en polvo, ho regantoj de la ŝafoj; ĉar venis por vi la tempo de buĉo; Mi disĵetos vin, kaj vi disfalos, kiel multekosta vazo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'Kaj ne ekzistos forkuro por la paŝtistoj, nek forsaviĝo por la regantoj de la ŝafaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Estos aŭdata kriado de la paŝtistoj kaj plorado de la regantoj de la ŝafaro, ĉar la Eternulo faros ekstermon en ilia ŝafaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'Disfalos la pacaj loĝejoj antaŭ la flama kolero de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Li forlasis Sian laŭbon kiel leono; ilia lando fariĝis dezerto de la kolero de la atakanto kaj de Lia flama kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'En la komenco de la reĝado de Jehojakim, filo de Joŝija, reĝo de Judujo, aperis jena vorto de la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'Tiele diras la Eternulo: Stariĝu sur la korto de la domo de la Eternulo, kaj parolu pri ĉiuj urboj de Judujo, kiuj venas en la domon de la Eternulo por adorkliniĝi, ĉiujn vortojn, kiujn Mi ordonis al vi diri al ili; ne mankigu eĉ unu vorton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Eble ili aŭskultos kaj returnos sin ĉiu de sia malbona vojo; kaj tiam Mi fordecidos la malbonon, kiun Mi intencas fari al ili pro iliaj malbonaj agoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Kaj diru al ili: Tiele diras la Eternulo: Se vi ne obeos Min, por agadi laŭ Mia instruo, kiun Mi donis al vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'por obei la vortojn de Miaj servantoj, la profetoj, kiujn Mi sendas al vi, kiujn Mi konstante sendadis, sed vi ilin ne aŭskultis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'tiam Mi agos kun ĉi tiu domo kiel kun Ŝilo, kaj ĉi tiun urbon Mi faros malbeno por ĉiuj popoloj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Kaj aŭdis la pastroj kaj la profetoj kaj la tuta popolo, kiel Jeremia parolis tiujn vortojn en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'Kiam Jeremia finis la paroladon de ĉio, kion la Eternulo ordonis diri al la tuta popolo, tiam kaptis lin la pastroj kaj la profetoj kaj la tuta popolo, dirante: Vi devas morti!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Kial vi profetas en la nomo de la Eternulo, dirante: Ĉi tiu domo fariĝos kiel Ŝilo, kaj ĉi tiu urbo dezertiĝos tiel, ke estos en ĝi neniu loĝanto? Kaj la tuta popolo amasiĝis ĉirkaŭ Jeremia en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Kiam la eminentuloj de Judujo aŭdis pri tio, ili iris el la reĝa domo en la domon de la Eternulo kaj sidiĝis ĉe la enirejo de la nova pordego de la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Kaj la pastroj kaj la profetoj diris al la eminentuloj kaj al la tuta popolo jene: Al morto estas kondamninda ĉi tiu homo, ĉar li profetis kontraŭ ĉi tiu urbo, kiel vi aŭdis per viaj oreloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Tiam Jeremia diris al ĉiuj eminentuloj kaj al la tuta popolo jene: La Eternulo sendis min, por profeti kontraŭ ĉi tiu domo kaj ĉi tiu urbo ĉion, kion vi aŭdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Plibonigu do nun viajn vojojn kaj vian konduton, kaj obeu la voĉon de la Eternulo, via Dio; kaj tiam la Eternulo fordecidos la malbonon, kiun Li diris pri vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Kaj mi estas nun en viaj manoj; faru kun mi tion, kion vi trovas bona kaj justa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Sed sciu, ke se vi min mortigos, vi ŝarĝos per senkulpa sango vin kaj ĉi tiun urbon kaj ĝiajn loĝantojn; ĉar vere la Eternulo sendis min al vi, por diri en viajn orelojn ĉiujn tiujn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Tiam la eminentuloj kaj la tuta popolo diris al la pastroj kaj al la profetoj: Ĉi tiu homo ne estas kondamninda al morto, ĉar li parolis al ni en la nomo de la Eternulo, nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Kaj leviĝis kelkaj el la plejaĝuloj de la lando, kaj diris al la tuta amaso de la popolo jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'Miĥa, la Moreŝetano, profetis en la tempo de Ĥizkija, reĝo de Judujo, kaj diris al la tuta Juda popolo jene: Tiele diras la Eternulo Cebaot: Cion estos plugita kiel kampo, Jerusalem fariĝos ruinaĵo, kaj la monto de la templo fariĝos arbara altaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Ĉu mortigis lin Ĥizkija, reĝo de Judujo, kaj ĉiuj Judoj? ili timis ja la Eternulon kaj preĝis antaŭ la Eternulo, kaj la Eternulo fordecidis la malbonon, kiun Li diris pri ili. Kaj ni farus grandan malbonon kontraŭ niaj animoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Ankaŭ alia homo profetis en la nomo de la Eternulo, Urija, filo de Ŝemaja, el Kirjat-Jearim; li profetis kontraŭ ĉi tiu urbo kaj ĉi tiu lando, simile al ĉio, kion diris Jeremia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'Kaj liajn vortojn aŭdis la reĝo Jehojakim kaj ĉiuj liaj potenculoj kaj ĉiuj eminentuloj, kaj la reĝo intencis mortigi lin; sed Urija tion aŭdis, kaj ektimis, kaj forkuris kaj venis en Egiptujon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Kaj la reĝo Jehojakim sendis homojn en Egiptujon: Elnatanon, filon de Aĥbor, kune kun aliaj homoj li sendis en Egiptujon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'kaj ili elkondukis Urijan el Egiptujo kaj venigis lin al la reĝo Jehojakim; kaj ĉi tiu mortigis lin per glavo kaj ĵetis lian kadavron inter la tombojn de la simpla popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Tamen la mano de Aĥikam, filo de Ŝafan, protektis Jeremian, ne lasante transdoni lin en la manojn de la popolo, por mortigi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'En la komenco de la reĝado de Jehojakim, filo de Joŝija, reĝo de Judujo, aperis de la Eternulo jena vorto al Jeremia:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Tiele diras al mi la Eternulo: Faru al vi ligilojn kaj jugon, kaj metu tion sur vian kolon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'kaj sendu tion al la reĝo de Edom kaj al la reĝo de Moab kaj al la reĝo de la Amonidoj kaj al la reĝo de Tiro kaj al la reĝo de Cidon, per la senditoj, kiuj venis Jerusalemon al Cidkija, reĝo de Judujo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'kaj komisiu al ili, ke ili diru al siaj sinjoroj jene: Tiele diras la Eternulo Cebaot, Dio de Izrael: Tiele diru al viaj sinjoroj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Per Mia granda forto kaj per Mia etendita brako Mi kreis la teron, la homojn kaj la bestojn, kiuj estas sur la tero; kaj Mi donas tion al tiu, kiu plaĉas al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'Kaj nun Mi transdonas ĉiujn tiujn landojn en la manon de Mia servanto Nebukadnecar, reĝo de Babel, kaj eĉ la bestojn de la kampo Mi transdonas al li, por ke ili servu al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'Kaj servos al li ĉiuj popoloj, ankaŭ al lia filo kaj al la filo de lia filo, ĝis venos la tempo ankaŭ por lia lando kaj lin sklavigos potencaj popoloj kaj grandaj reĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Kaj se ia popolo kaj regno ne servos al li, al Nebukadnecar, reĝo de Babel, kaj ne metos sian kolon sub la jugon de la reĝo de Babel, Mi punos tiun popolon per glavo kaj malsato kaj pesto, diras la Eternulo, ĝis Mi ekstermos ilin per lia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Ne aŭskultu do viajn profetojn, nek viajn magiistojn, nek viajn sonĝoklarigistojn, nek viajn aŭguristojn, nek viajn sorĉistojn, kiuj diras al vi jene: Ne servu al la reĝo de Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Ĉar ili profetas al vi malveraĵon, por malproksimigi vin de via lando, por ke Mi elpelu vin kaj vi pereu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Sed tiun popolon, kiu metos sian kolon sub la jugon de la reĝo de Babel kaj servos al li, tiun Mi restigos trankvile sur ĝia tero, diras la Eternulo, por prilaboradi ĝin kaj loĝi sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Kaj al Cidkija, reĝo de Judujo, mi diris tiajn samajn vortojn, nome: Metu vian kolon sub la jugon de la reĝo de Babel, kaj servu al li kaj al lia popolo, kaj restu vivantaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Por kio vi volus morti, vi kaj via popolo, de glavo, de malsato, kaj de pesto, kiel la Eternulo decidis pri popolo, kiu ne servos al la reĝo de Babel?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Ne aŭskultu la vortojn de la profetoj, kiuj diras al vi, ke vi ne servu al la reĝo de Babel; ĉar ili profetas al vi malveraĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Ĉar Mi ne sendis ilin, diras la Eternulo, kaj ili malvere profetas en Mia nomo, por ke Mi elpelu vin, kaj por ke vi pereu, vi kaj la profetoj, kiuj profetas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Kaj al la pastroj kaj al la tuta ĉi tiu popolo mi diris jene: Tiele diras la Eternulo: Ne aŭskultu la vortojn de viaj profetoj, kiuj profetas al vi jene: Jen la vazoj de la domo de la Eternulo nun baldaŭ estos revenigitaj el Babel; ĉar malveraĵon ili profetas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Ne aŭskultu ilin; servu al la reĝo de Babel, por ke vi vivu; por kio ĉi tiu urbo fariĝu dezerto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Se ili estas profetoj kaj se ili havas la vorton de la Eternulo, ili elpetegu de la Eternulo Cebaot, ke la vazoj, kiuj restis en la domo de la Eternulo kaj en la domo de la reĝo de Judujo kaj en Jerusalem, ne transiru en Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Ĉar tiele diras la Eternulo Cebaot pri la kolonoj, pri la maro, pri la bazoj, kaj pri la ceteraj vazoj, kiuj restis en ĉi tiu urbo');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'kaj kiujn ne prenis Nebukadnecar, reĝo de Babel, kiam li forkondukis Jeĥonjan, filon de Jehojakim, reĝon de Judujo, el Jerusalem en Babelon, kaj ankaŭ ĉiujn eminentulojn de Judujo kaj Jerusalem;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'tiele diras la Eternulo Cebaot, Dio de Izrael, pri la vazoj, kiuj restis en la domo de la Eternulo kaj en la domo de la reĝo de Judujo kaj en Jerusalem:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'En Babelon ili estos forportitaj, kaj tie ili restos, ĝis la tago, kiam Mi rememoros ilin, diras la Eternulo, kaj prenigos kaj reportigos ilin sur ĉi tiun lokon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'En tiu sama jaro, en la komenco de la reĝado de Cidkija, reĝo de Judujo, en la kvara jaro, en la kvina monato, Ĥananja, filo de Azur, profeto el Gibeon, diris al mi en la domo de la Eternulo, antaŭ la okuloj de la pastroj kaj de la tuta popolo, jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'Tiele diras la Eternulo Cebaot, Dio de Izrael: Mi rompos la jugon de la reĝo de Babel;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'post du jaroj Mi revenigos sur ĉi tiun lokon ĉiujn vazojn de la domo de la Eternulo, kiujn Nebukadnecar, reĝo de Babel, prenis de ĉi tiu loko kaj forportis en Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Kaj Jeĥonjan, filon de Jehojakim, reĝon de Judujo, kaj ĉiujn forkondukitajn Judojn, kiuj venis en Babelon, Mi revenigos sur ĉi tiun lokon, diras la Eternulo; ĉar Mi rompos la jugon de la reĝo de Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Tiam la profeto Jeremia respondis al la profeto Ĥananja antaŭ la okuloj de la pastroj, kaj de la tuta popolo, kiu staris en la domo de la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'kaj la profeto Jeremia diris: Amen, tiel la Eternulo faru; la Eternulo plenumu viajn vortojn, kiujn vi profetis, kaj Li revenigu el Babel sur ĉi tiun lokon la vazojn de la domo de la Eternulo kaj ĉiujn forkondukitojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Tamen aŭskultu la vorton, kiun mi diros en viajn orelojn kaj en la orelojn de la tuta popolo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'La profetoj, kiuj de antikva tempo estis antaŭ mi kaj antaŭ vi, profetis al multaj landoj kaj al grandaj regnoj militon, malfeliĉon, aŭ peston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Se profeto antaŭdiris pacon, tiam post la plenumiĝo de la vorto de la profeto oni ekkonis lin kiel profeton, kiun vere sendis la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Kaj la profeto Ĥananja deprenis la jugon de la kolo de la profeto Jeremia kaj rompis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'Kaj Ĥananja diris antaŭ la okuloj de la tuta popolo jene: Tiele diras la Eternulo: Simile al ĉi tio Mi rompos la jugon de Nebukadnecar, reĝo de Babel, post du jaroj, deprenante ĝin de la kolo de ĉiuj popoloj. Kaj la profeto Jeremia iris sian vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Kaj aperis jena vorto de la Eternulo al Jeremia, post kiam la profeto Ĥananja forrompis la jugon de la kolo de la profeto Jeremia:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, 'Iru kaj diru al Ĥananja jene: Tiele diras la Eternulo: Jugon lignan vi rompis, sed vi faru anstataŭ ĝi jugon feran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Ĉar tiele diras la Eternulo Cebaot, Dio de Izrael: Feran jugon Mi metis sur la kolon de ĉiuj tiuj popoloj, ke ili servu al Nebukadnecar, reĝo de Babel, kaj ili servos al li; eĉ la bestojn de la kampo Mi transdonis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Tiam la profeto Jeremia diris al la profeto Ĥananja: Aŭskultu, Ĥananja; la Eternulo vin ne sendis, kaj vi kredigas al ĉi tiu popolo malveraĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Pro tio tiele diras la Eternulo: Jen Mi forigos vin de sur la tero; en ĉi tiu jaro vi mortos, ĉar vi parolis kontraŭ la volo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'Kaj la profeto Ĥananja mortis en tiu jaro, en la sepa monato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Jen estas la vortoj de la letero, kiun la profeto Jeremia sendis el Jerusalem al la plej gravaj plejaĝuloj, kiuj estis forkondukitaj, kaj al la pastroj, al la profetoj, kaj al la tuta popolo, kiujn Nebukadnecar forkondukis el Jerusalem en Babelon');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, '(post kiam la reĝo Jeĥonja, kaj la reĝino, kaj la korteganoj, la eminentuloj de Judujo kaj Jerusalem, la ĉarpentistoj kaj forĝistoj foriris el Jerusalem);');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'per Eleasa, filo de Ŝafan, kaj Gemarja, filo de Ĥilkija (kiujn Cidkija, reĝo de Judujo, sendis en Babelon, al Nebukadnecar, reĝo de Babel), li sendis jenajn vortojn:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'Tiele diras la Eternulo Cebaot, Dio de Izrael, al ĉiuj elpelitoj, kiujn Mi elpelis el Jerusalem en Babelon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Konstruu domojn kaj loĝu, plantu ĝardenojn kaj manĝu iliajn fruktojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'prenu edzinojn kaj naskigu filojn kaj filinojn, prenu edzinojn por viaj filoj kaj edzinigu viajn filinojn, por ke ili nasku filojn kaj filinojn; multiĝu tie kaj ne malmultiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Zorgu pri la bonstato de tiu urbo, kien Mi transloĝigis vin, kaj preĝu por ĝi al la Eternulo; ĉar ĉe ĝia bonstato vi ankaŭ havos bonstaton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Ĉar tiele diras la Eternulo Cebaot, Dio de Izrael: Viaj profetoj, kiuj estas inter vi, kaj viaj magiistoj ne forlogu vin; kaj ne atentu viajn sonĝojn, kiujn vi sonĝas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'ĉar malveraĵon ili profetas al vi en Mia nomo; Mi ne sendis ilin, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Ĉar tiele diras la Eternulo: Kiam en Babel pasos sepdek jaroj, Mi rememoros vin kaj plenumos super vi Mian bonan vorton, revenigante vin sur ĉi tiun lokon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Ĉar Mi scias la intencojn, kiujn Mi havas koncerne vin, diras la Eternulo, intencojn al bono kaj ne al malbono, por doni al vi estontecon kaj esperon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Vi vokos al Mi, kaj vi iros, kaj vi preĝos al Mi; kaj Mi aŭskultos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'Vi serĉos Min, kaj trovos, se vi serĉos Min per via tuta koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'Kaj Mi estos trovita de vi, diras la Eternulo, kaj Mi revenigos viajn kaptitojn, kaj Mi kolektos vin el ĉiuj popoloj kaj de ĉiuj lokoj, kien Mi forpelis vin, diras la Eternulo; kaj Mi revenigos vin sur la lokon, de kiu Mi transloĝigis vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Vane vi diras: La Eternulo starigis al ni profetojn en Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'Ĉar tiele diras la Eternulo pri la reĝo, kiu sidas sur la trono de David, kaj pri la tuta popolo, kiu loĝas en ĉi tiu urbo, pri viaj fratoj, kiuj ne iris kun vi en ekzilon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'tiele diras la Eternulo Cebaot: Jen Mi sendos sur ilin glavon kaj malsaton kaj peston, kaj Mi similigos ilin al malbonaj figoj, kiujn oni ne povas manĝi pro ilia malboneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'Mi persekutos ilin per glavo, per malsato, kaj per pesto, kaj Mi faros ilin objekto de teruro por ĉiuj regnoj de la tero, objekto de malbeno, mirego, moko, kaj malhonoro inter ĉiuj popoloj, kien Mi dispelos ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'pro tio, ke ili ne aŭskultis Miajn vortojn, diras la Eternulo; Mi sendadis al ili Miajn servantojn, la profetojn, Mi konstante sendadis, sed vi ne aŭskultis, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Kaj vi, ĉiuj forkondukitoj, kiujn Mi foririgis el Jerusalem en Babelon, aŭskultu la vorton de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'Tiele diras la Eternulo Cebaot, Dio de Izrael, pri Aĥab, filo de Kolaja, kaj pri Cidkija, filo de Maaseja, kiuj profetis al vi en Mia nomo malveraĵon: Jen Mi transdonos ilin en la manon de Nebukadnecar, reĝo de Babel, kaj li mortigos ilin antaŭ viaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'Kaj ĉe ĉiuj ekzilitoj de Judujo, kiuj estas en Babel, ilia nomo fariĝos objekto de malbeno, kaj oni dirados: La Eternulo faru al vi tion, kion, kion al Cidkija kaj Aĥab, kiujn la reĝo de Babel rostigis sur fajro-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'pro tio, ke ili faris abomenindaĵon en Izrael, adultis kun la edzinoj de siaj proksimuloj, kaj parolis en Mia nomo malveraĵon, kiun Mi ne ordonis al ili. Tion Mi scias kaj atestas, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'Kaj al Ŝemaja, la Neĥelamano, diru jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'Tiele diras la Eternulo Cebaot, Dio de Izrael: Pro tio, ke vi sendis en via nomo leterojn al la tuta popolo, kiu estas en Jerusalem, kaj al la pastro Cefanja, filo de Maaseja, kaj al ĉiuj pastroj, kun la sekvanta enhavo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'La Eternulo starigis vin pastro anstataŭ la pastro Jehojada, por ke vi estu kontrolanto en la domo de la Eternulo super ĉiu frenezulo, kiu prezentas sin kiel profeto, kaj vi metu lin en malliberejon kaj karceron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'kial do vi ne faris punparolon al Jeremia, la Anatotano, kiu prezentas sin al vi kiel profeto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Ĉar ankaŭ al ni en Babelon li sendis, por diri: La kaptiteco estos longa; konstruu domojn kaj loĝu, plantu ĝardenojn kaj manĝu iliajn fruktojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'Kaj la pastro Cefanja tralegis tiun leteron en la orelojn de la profeto Jeremia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'Tial aperis jena vorto de la Eternulo al Jeremia:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, 'Sendu al ĉiuj ekzilitoj, por diri: Tiele diras la Eternulo pri Ŝemaja, la Neĥelamano: Pro tio, ke Ŝemaja profetis al vi, kvankam Mi ne sendis lin, kaj li fidigis vin per malveraĵo-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'pro tio tiele diras la Eternulo: Jen Mi punos Ŝemajan, la Neĥelamanon, kaj lian idaron: neniu restos ĉe li meze de ĉi tiu popolo, kaj li ne vidos la bonon, kiun Mi faros al Mia popolo, diras la Eternulo; ĉar li parolis kontraŭ la volo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Jena vorto aperis de la Eternulo al Jeremia:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'Tiele diras la Eternulo, Dio de Izrael: Enskribu al vi en libron ĉiujn vortojn, kiujn Mi diris al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Ĉar jen venos tempo, diras la Eternulo, kiam Mi revenigos la kaptitojn de Mia popolo Izrael kaj Jehuda, diras la Eternulo, kaj Mi revenigos ilin en la landon, kiun Mi donis al iliaj patroj, kaj ili ĝin posedos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Kaj jen estas la vortoj, kiujn diris la Eternulo pri Izrael kaj Jehuda:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Tiele diras la Eternulo: Voĉon de tumulto kaj de teruro ni aŭdas, ne de paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Demandu kaj rigardu, ĉu viro naskas? kial do Mi vidas, ke ĉiu viro tenas siajn manojn ĉe siaj lumboj, kiel naskantino, kaj ĉies vizaĝoj verdiĝis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Ho ve, kiel granda estas tiu tago! ne ekzistas simila al ĝi; tempo de mizero ĝi estas por Jakob, sed li estos savita el ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'En tiu tempo, diras la Eternulo Cebaot, Mi forrompos lian jugon de via kolo, kaj viajn ligilojn Mi disŝiros, kaj fremduloj ne plu servigos lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'Sed ili servos al la Eternulo, sia Dio, kaj al David, sia reĝo, kiun Mi restarigos al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Kaj vi ne timu, ho Mia servanto Jakob, diras la Eternulo, kaj ne tremu, ho Izrael; ĉar jen Mi savos vin el malproksime kaj vian idaron el la lando de ilia kaptiteco, kaj Jakob revenos kaj vivos trankvile kaj pace, kaj neniu lin timigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Ĉar Mi estos kun vi, diras la Eternulo, por savi vin; ĉar Mi ekstermos ĉiujn popolojn, inter kiujn Mi disĵetis vin, sed vin Mi ne ekstermos; Mi nur punos vin modere, por ke Mi ne lasu vin tute sen puno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Ĉar tiele diras la Eternulo: Danĝera estas via vundo, kaj via ulcero estas dolorplena.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Neniu juĝos vian aferon, por sanigi vian vundon; bona kuracado ne ekzistas por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Ĉiuj viaj amikoj forgesis vin, ili vin ne serĉas; ĉar per frapo de malamiko Mi frapis vin, per kruela puno, pro viaj multaj malbonagoj, pro la forteco de viaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Kial vi krias pri via vundo, pri via danĝera malsano? Mi tion faris al vi pro viaj multaj malbonagoj, pro la forteco de viaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Tamen ĉiuj viaj manĝegantoj estos manĝegitaj; kaj ĉiuj viaj premantoj, ĉiuj, iros en kaptitecon; viaj ruinigintoj estos ruinigitaj; kaj ĉiuj viajn rabintojn Mi faros rabitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Mi donos al vi kuracon, kaj Mi resanigos vin de viaj vundoj, diras la Eternulo; ĉar ili nomis vin forpuŝitino, ho Cion, pri kiu neniu demandas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Tiele diras la Eternulo: Jen Mi revenigos el kaptiteco la tendojn de Jakob, kaj liajn loĝejojn Mi kompatos; kaj la urbo estos konstruita sur sia monteto, kaj la templo estos starigita laŭ sia ordo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'Kaj eliros el ili dankado kaj voĉo de gajuloj; Mi multigos ilin, kaj ili ne malmultiĝos; Mi donos al ili honoron, kaj ili ne malaltiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Kaj ili havos filojn kiel antaŭe, kaj ilia komunumo forte staros antaŭ Mi, kaj Mi punos ĉiujn iliajn premintojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'Kaj ilia potenculo estos el ili mem, kaj ilia reganto devenos el ilia propra mezo; Mi alproksimigos lin, kaj li aliros al Mi; ĉar kiu alia kuraĝos en sia koro alproksimiĝi al Mi? diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'Kaj vi estos Mia popolo, kaj Mi estos via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Jen eliros ventego de la Eternulo en kolero, ventego detruanta; ĝi falos sur la kapon de la malpiuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Ne kvietiĝos la flama kolero de la Eternulo, ĝis Li estos farinta kaj ĝis Li estos plenuminta la intencojn de Sia koro; en la tempo estonta vi tion komprenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'En tiu tempo, diras la Eternulo, Mi estos Dio de ĉiuj familioj de Izrael, kaj ili estos Mia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Tiele diras la Eternulo: En la dezerto trovis favoron popolo, kiu restis ne ekstermita de la glavo; Izrael iras al sia trankviliĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'De malproksime aperis al mi la Eternulo, dirante: Mi ekamis vin per amo eterna, tial Mi altiris vin favorkore.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Denove Mi aranĝos vin, kaj vi estos aranĝita, ho virgulino de Izrael; denove vi ornamos vin per viaj tamburinoj kaj eliros en dancrondojn de gajuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Denove vi plantos vinberĝardenojn sur la montoj de Samario; oni plantos kaj ricevos fruktojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Ĉar venos la tempo, kiam gardistoj sur la monto de Efraim vokos: Leviĝu, kaj ni iru sur Cionon al la Eternulo, nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Ĉar tiele diras la Eternulo: Kantu ĝojon al Jakob kaj ĝojkriu antaŭ la kapoj de la nacioj, proklamu, gloru, kaj diru: Savu, ho Eternulo, Vian popolon, la restaĵon de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Jen Mi venigos ilin el la lando norda, kaj kolektos ilin de la randoj de la tero, kune kun la blinduloj kaj lamuloj, gravedulinoj kaj naskintinoj; en granda amaso ili revenos ĉi tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Kun ploro ili venos, kun preĝoj Mi kondukos ilin; Mi irigos ilin apud torentoj da akvo, laŭ vojo ĝusta, sur kiu ili ne falpuŝiĝos; ĉar Mi fariĝis patro por Izrael, kaj Efraim estas Mia unuenaskito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Aŭskultu la vorton de la Eternulo, ho nacioj, kaj sciigu al la malproksimaj insuloj, kaj diru: La disĵetinto de Izrael kolektos lin kaj gardos lin, kiel paŝtanto sian paŝtataron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Ĉar la Eternulo elaĉetis Jakobon kaj liberigis lin el la mano de plifortulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'Kaj ili venos kaj kantos sur la altaĵo de Cion; kaj ili rapidos al la bonaĵoj de la Eternulo, al la greno, al la mosto, al la oleo, al la ŝafidoj kaj bovidoj; kaj ilia animo estos kiel akvoriĉa ĝardeno, kaj ili ne plu havos malĝojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Tiam virgulino gajos en la dancrondo, kaj kune ankaŭ junuloj kaj maljunuloj; kaj Mi ŝanĝos ilian malĝojon en ĝojon, Mi konsolos ilin kaj gajigos ilin post ilia aflikto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'Kaj la animon de la pastroj Mi satigos per grasaĵoj, kaj Mia popolo satiĝos per Miaj bonaĵoj, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Tiele diras la Eternulo: Voĉo estas aŭdata en Rama, ĝemado kaj maldolĉa plorado: Raĥel priploras siajn filojn, ne volas konsoliĝi pri siaj infanoj, ĉar ili forestas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Tiele diras la Eternulo: Detenu vian voĉon de plorado kaj viajn okulojn de larmoj; ĉar ekzistas rekompenco por via laboro, diras la Eternulo, kaj ili revenos el la lando de la malamiko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Kaj ekzistas espero por via idaro, diras la Eternulo, kaj la filoj revenos en siajn limojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'Mi aŭdis, kiel Efraim diras pentante: Vi punis min, kaj mi estas punita, kiel bovido ne dresita; konvertu min, kaj mi konvertiĝos; ĉar Vi, ho Eternulo, estas mia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Kiam mi konvertiĝis, mi pentis; kaj kiam mi estis punita, mi batis min sur la femurojn; mi hontis kaj mi ruĝiĝis, ĉar mi portas la malhonoron de mia juneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Ĉu Efraim ne estas Mia kara filo, Mia amata infano? ĉar kion ajn Mi parolis pri li, Mi tamen ankoraŭ rememoras lin; tial Mia interno afliktiĝas pri li; Mi certe korfavoros lin, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Starigu al vi gvidajn ŝtonojn, aranĝu al vi vojsignojn, atentu la vojon, laŭ kiu vi iris; revenu, virgulino de Izrael, revenu en ĉi tiujn viajn urbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Ĝis kiam vi turnados vin, ho defalinta filino? Ĉar la Eternulo kreis ion novan sur la tero: virino ĉirkaŭos viron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Tiele diras la Eternulo Cebaot, Dio de Izrael: Ankoraŭ oni parolos jenajn vortojn en la Juda lando kaj en ĝiaj urboj, kiam Mi revenigos iliajn kaptitojn: La Eternulo vin benu, ho loĝejo de justeco, sankta monto!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Kaj loĝos apud ĝi Jehuda kune kun ĉiuj siaj urboj, la terkultivistoj kaj la vagantoj kun paŝtataroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Ĉar Mi sensoifigos animon lacan, kaj ĉiun animon malĝojan Mi satigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Ĉe tio mi vekiĝis kaj ekrigardis, kaj mia sonĝo estis agrabla por mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Jen venos la tempo, diras la Eternulo, kiam Mi prisemos la domon de Izrael kaj la domon de Jehuda per semo de homo kaj semo de bruto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'Kaj tiel same, kiel Mi maldormis super ili, por elradikigi, elŝiri, detrui, pereigi, kaj malfeliĉigi, tiel Mi maldormos super ili, por konstrui kaj planti, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'En tiu tempo oni ne plu diros: La patroj manĝis nematurajn vinberojn, kaj la dentoj de la filoj agaciĝis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'sed ĉiu mortos pro sia propra kulpo, la dentoj agaciĝos ĉe tiu, kiu manĝis la nematurajn vinberojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Jen venos la tempo, diras la Eternulo, kiam Mi faros kun la domo de Izrael kaj la domo de Jehuda interligon novan:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'ne tian, kiel la interligo, kiun Mi faris kun iliaj patroj, en la tago, kiam Mi prenis ilian manon, por elkonduki ilin el la lando Egipta, la interligo, kiun ili malobeis kaj Mi devis altrudi al ili, diras la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'sed jen estas la interligo, kiun Mi faros kun la domo de Izrael post tiu tempo, diras la Eternulo: Mi metos Mian leĝon en ilian internon, kaj sur ilia koro Mi ĝin skribos, kaj Mi estos ilia Dio, kaj ili estos Mia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'Kaj ne plu instruos ĉiu sian proksimulon kaj ĉiu sian fraton, dirante: Ekkonu la Eternulon; ĉar ĉiuj Min konos, de iliaj malgranduloj ĝis iliaj granduloj, diras la Eternulo; ĉar Mi pardonos iliajn kulpojn, kaj iliajn pekojn Mi ne plu rememoros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'Tiele diras la Eternulo, kiu donas la sunon por lumo en la tago, leĝojn al la luno kaj al la steloj por lumo en la nokto; kiu kvietigas la maron, kiam bruas ĝiaj ondoj; kaj kies nomo estas Eternulo Cebaot:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Se ĉi tiuj leĝoj neniiĝos antaŭ Mi, diras la Eternulo, tiam ankaŭ la idaro de Izrael ĉesos esti eterne popolo antaŭ Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'Tiele diras la Eternulo: Se oni povos mezuri la ĉielon supre kaj esplori la fundamenton de la tero malsupre, tiam Mi forpuŝos la tutan idaron de Izrael pro ĉio, kion ili faris, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Jen venos la tempo, diras la Eternulo, kiam denove konstruiĝos la urbo al la Eternulo, de la turo Ĥananel ĝis la Pordego Angula.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'Kaj la mezura ŝnuro iros pluen ĝis la monteto Gareb kaj turniĝos al Goa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'Kaj la tuta valo de kadavroj kaj de cindro, kaj ĉiuj kampoj ĝis la torento Kidron, ĝis la angulo de la Pordego de Ĉevaloj oriente, estos sanktaj al la Eternulo, ne detruiĝos kaj ne plu ruiniĝos eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Jen estas la vorto, kiu aperis al Jeremia de la Eternulo en la deka jaro de Cidkija, reĝo de Judujo, tio estas en la dek-oka jaro de Nebukadnecar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'Tiam la militistaro de la reĝo de Babel sieĝis Jerusalemon, kaj la profeto Jeremia estis malliberigita sur la korto de la malliberejo, kiu estis apud la domo de la reĝo de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Tie malliberigis lin Cidkija, reĝo de Judujo, dirante: Kial vi profetas, parolante, ke tiele diras la Eternulo: Jen Mi transdonos ĉi tiun urbon en la manon de la reĝo de Babel, kiu ĝin venkoprenos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'kaj Cidkija, reĝo de Judujo, ne saviĝos el la manoj de la Ĥaldeoj, sed li estos transdonita en la manon de la reĝo de Babel, kies buŝo parolos kun lia buŝo kaj kies okuloj rigardos liajn okulojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'kaj en Babelon li forkondukos Cidkijan, kaj ĉi tiu restos tie, ĝis Mi vizitos lin, diras la Eternulo; se vi militos kontraŭ la Ĥaldeoj, vi ne sukcesos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Kaj Jeremia diris: Aperis al mi la vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Jen Ĥanamel, filo de via onklo Ŝalum, iras al vi, por diri: Aĉetu al vi mian kampon, kiu estas en Anatot, ĉar al vi apartenas la rajto de parenco, por aĉeti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Kaj venis al mi Ĥanamel, filo de mia onklo, konforme al la vorto de la Eternulo, sur la korton de la malliberejo, kaj li diris al mi: Aĉetu, mi petas, mian kampon, kiu estas en Anatot, en la lando de Benjamen; ĉar al vi apartenas la rajto de heredo kaj la rajto de elaĉeto; aĉetu al vi. Tiam mi komprenis, ke tio estas vorto de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'Kaj mi aĉetis de Ĥanamel, filo de mia onklo, la kampon, kiu estis en Anatot, kaj mi pesis al li la monon, dek sep siklojn da arĝento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'Kaj mi skribis dokumenton kaj sigelis; kaj mi invitis atestantojn, kaj pesis la arĝenton per pesilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Kaj mi prenis la dokumenton de aĉeto, la sigelitan laŭ juro kaj leĝo, kaj la nefermitan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'Kaj mi donis la dokumenton de aĉeto al Baruĥ, filo de Nerija, filo de Maĥseja, antaŭ la okuloj de mia kuzo Ĥanamel, kaj antaŭ la okuloj de la atestantoj, kiuj subskribis la dokumenton de aĉeto, kaj antaŭ la okuloj de ĉiuj Judoj, kiuj sidis sur la korto de la malliberejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'Kaj mi ordonis al Baruĥ antaŭ iliaj okuloj, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, 'Tiele diras la Eternulo Cebaot, Dio de Izrael: Prenu ĉi tiujn dokumentojn, ĉi tiun dokumenton de aĉeto, la sigelitan, kaj ĉi tiun nefermitan, kaj metu ilin en argilan vazon, por ke ili konserviĝu dum longa tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Ĉar tiele diras la Eternulo Cebaot, Dio de Izrael: Oni denove aĉetos domojn, kampojn, kaj vinberĝardenojn en ĉi tiu lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Kaj, transdoninte la dokumentojn de aĉeto al Baruĥ, filo de Nerija, mi ekpreĝis al la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'Ho Sinjoro, ho Eternulo! Vi kreis la ĉielon kaj la teron per Via granda forto kaj per Via etendita brako; nenia afero estas nefarebla por Vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'Vi faras favorkoraĵon al miloj, kaj pro la malbonagoj de la patroj Vi repagas al iliaj filoj post ili. Vi, Dio granda, potenca, kies nomo estas Eternulo Cebaot,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'granda en Siaj decidoj kaj potenca en Siaj agoj; Vi, kies okuloj estas malfermitaj super ĉiuj vojoj de la homidoj, por redoni al ĉiu laŭ lia konduto kaj laŭ la fruktoj de liaj agoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'Vi, kiu faris signojn kaj miraklojn en la lando Egipta ĝis la nuna tago super Izrael kaj super la aliaj homoj, kaj faris al Vi gloran nomon, kiel ĝi estas nune;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'kaj Vi elkondukis Vian popolon Izrael el la lando Egipta per signoj kaj per mirakloj, per forta mano, per etendita brako, kaj per granda teruro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'kaj Vi donis al ili ĉi tiun landon, pri kiu Vi ĵuris al iliaj patroj, ke Vi donos al ili, landon, en kiu fluas lakto kaj mielo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'kaj ili venis kaj ekposedis ĝin, tamen ili ne aŭskultis Vian voĉon kaj ne sekvis Vian instruon, ne faris ĉion, kion Vi ordonis al ili; kaj Vi venigis sur ilin ĉi tiun tutan malfeliĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Jen remparoj alproksimiĝas al la urbo, por venkopreni ĝin, kaj la urbo pro la glavo, malsato, kaj pesto estas transdonata en la manojn de la Ĥaldeoj, kiuj militas kontraŭ ĝi; kion Vi diris, tio fariĝas, kaj Vi tion vidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'Kaj Vi, Sinjoro, ho Eternulo, diris al mi: Aĉetu al vi la kampon pro mono, kaj starigu atestantojn; dume la urbo estas transdonata en la manojn de la Ĥaldeoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Tiam la vorto de la Eternulo aperis al Jeremia, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'Jen Mi, la Eternulo, estas Dio de ĉiu karno; ĉu ekzistas por Mi io nefarebla?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Tial tiele diras la Eternulo: Jen Mi transdonas ĉi tiun urbon en la manojn de la Ĥaldeoj, kaj en la manon de Nebukadnecar, reĝo de Babel, kaj li venkoprenos ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'Kaj venos la Ĥaldeoj, kiuj militas kontraŭ ĉi tiu urbo, kaj ekbruligos ĉi tiun urbon per fajro, kaj forbruligos ĝin, kaj la domojn, sur kies tegmentoj oni incensadis al Baal kaj faradis verŝoferojn al aliaj dioj, por kolerigi Min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Ĉar la Izraelidoj kaj la Judoj faradis nur malbonon antaŭ Miaj okuloj detempe de sia juneco; ĉar la Izraelidoj nur kolerigadis Min per la faroj de siaj manoj, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'Ĉar nur por Mia kolero kaj por Mia ĉagreno ekzistis ĉi tiu urbo de la tago, kiam oni konstruis ĝin, ĝis la nuna tago, tiel, ke Mi devas forpuŝi ĝin de antaŭ Mia vizaĝo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'pro ĉiuj malbonaĵoj de la Izraelidoj kaj Jehudaidoj, kiujn ili faris, por Min kolerigi, ili, iliaj reĝoj, iliaj princoj, iliaj pastroj, iliaj profetoj, la Judoj, kaj la loĝantoj de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'Ili turnis al Mi la dorson, ne la vizaĝon; Mi instruadis ilin, konstante instruadis, sed ili ne aŭskultis, ne akceptis admonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Siajn abomenindaĵojn ili metis en la domon, kiu estas nomata per Mia nomo, kaj ili malpurigis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'Kaj ili aranĝis la altaĵojn de Baal, kiuj estas en la valo de la filo de Hinom, por bruligi siajn filojn kaj filinojn al Moleĥ, kion Mi ne ordonis al ili, kaj pri kio ne venis al Mi en la kapon, ke ili faros tiun abomenindaĵon, por pekigi Judujon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Kaj tamen tiele diras la Eternulo, Dio de Izrael, pri ĉi tiu urbo, pri kiu vi diras, ke ĝi estas transdonata en la manon de la reĝo de Babel per glavo, malsato, kaj pesto:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Jen Mi kolektos ilin el ĉiuj landoj, kien Mi dispelis ilin en Mia kolero, en Mia furiozo, kaj en granda indigno; kaj Mi revenigos ilin sur ĉi tiun lokon kaj loĝigos ilin sendanĝere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'Kaj ili estos Mia popolo, kaj Mi estos ilia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'Kaj Mi donos al ili unu koron kaj unu vojon, ke ili ĉiam timu Min, por ke estu bone al ili kaj al iliaj idoj post ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'Kaj Mi faros kun ili interligon eternan, ke Mi ne dekliniĝos de ili en Mia bonfarado al ili; kaj timon je Mi Mi metos en ilian koron, ke ili ne forturniĝu de Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'Kaj Mi ĝojos pri ili, bonfarante al ili, kaj Mi plantos ilin en ĉi tiu lando fidele, per Mia tuta koro kaj per Mia tuta animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Ĉar tiele diras la Eternulo: Kiel Mi venigis sur ĉi tiun popolon tiun tutan grandan malbonon, tiel Mi venigos sur ilin la tutan bonon, kiun Mi eldiris pri ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Kaj kampoj estos aĉetataj en ĉi tiu lando, pri kiu vi diras, ke ĝi estas dezerta, ke ne troviĝas en ĝi homoj nek brutoj, ke ĝi estas transdonita en la manojn de la Ĥaldeoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Oni aĉetos kampojn per mono, oni enskribos en dokumentojn kaj sigelos, kaj starigos atestantojn, en la lando en Benjamen, en la ĉirkaŭaĵo de Jerusalem, en la urboj de Judujo, en la urboj de la montoj, en la urboj de la valoj, kaj en la urboj de la sudo; ĉar Mi revenigos ilin el la kaptiteco, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'La vorto de la Eternulo aperis al Jeremia duafoje, kiam li estis ankoraŭ tenata sur la korto de la malliberejo, nome:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'Tiele diras la Eternulo, kiu ĉion faris, la Eternulo, kiu ĉion kreis, por ĝin fortikigi, kaj kies nomo estas Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Voku al Mi, kaj Mi respondos al vi, kaj Mi sciigos al vi grandajn kaj gravajn aferojn, kiujn vi ne scias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Ĉar tiele diras la Eternulo, Dio de Izrael, pri la domoj de ĉi tiu urbo, kaj pri la domoj de la reĝoj de Judujo, kiuj estas detruitaj por remparoj kaj por glavoj');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'de tiuj, kiuj venis, por batali kontraŭ la Ĥaldeoj kaj plenigi ilin per kadavroj de homoj, kiujn Mi frapis en Mia kolero kaj en Mia indigno; ĉar Mi kaŝis Mian vizaĝon for de ĉi tiu urbo pro ĉiuj iliaj malbonagoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Jen Mi redonos al ĝi bonstaton kaj kuracon, kaj Mi resanigos ilin, kaj Mi malkovros por ili abundon da paco kaj vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Kaj Mi revenigos la kaptitojn de Jehuda kaj la kaptitojn de Izrael, kaj Mi aranĝos ilin kiel antaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'Kaj Mi purigos ilin de ĉiuj iliaj malbonagoj, per kiuj ili pekis antaŭ Mi; kaj Mi pardonos ĉiujn iliajn krimojn, per kiuj ili pekis antaŭ Mi kaj defalis de Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'Kaj tio fariĝos por Mi agrabla nomo, laŭdo kaj gloro antaŭ ĉiuj nacioj de la tero, kiuj aŭdos pri la tuta bono, kiun Mi faras al ili, kaj ili ektimos kaj ektremos pro la tuta bono kaj la tuta bonstato, kiun Mi donos al ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Tiele diras la Eternulo: Sur ĉi tiu loko-pri kiu vi diras, ke ĝi estas dezertigita tiel, ke jam ne ekzistas homoj nek brutoj en la urboj de Judujo kaj sur la stratoj de Jerusalem, kiuj fariĝis malplenaj pro foresto de homoj kaj de loĝantoj kaj de brutoj-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'ankoraŭ estos aŭdataj sonoj de ĝojo kaj sonoj de gajeco, voĉo de fianĉo kaj voĉo de fianĉino, voĉo de homoj, kiuj parolos: Laŭdu la Eternulon Cebaot, ĉar la Eternulo estas bona, ĉar eterna estas Lia favorkoreco; kaj kiuj alportados dankoferojn en la domon de la Eternulo; ĉar Mi revenigos la forkaptitojn de la lando kiel antaŭe, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Tiele diras la Eternulo Cebaot: Sur ĉi tiu loko, kiu dezertiĝis tiel, ke tie ne troviĝas homo nek bruto, kaj en ĉiuj ĝiaj urboj denove troviĝos loĝejoj de paŝtistoj, kiuj ripozigos tie siajn ŝafojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'en la urboj de la montoj, en la urboj de la valoj, en la urboj de la sudo, en la lando de Benjamen, en la ĉirkaŭaĵo de Jerusalem, kaj en la urboj de Judujo denove pasados ŝafoj sub la mano de kalkulanto, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Jen venos tempo, diras la Eternulo, kiam Mi plenumos la bonan vorton, kiun Mi diris pri la domo de Izrael kaj pri la domo de Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'En tiuj tagoj kaj en tiu tempo Mi elkreskigos al David markoton virtan, kiu faros juĝon kaj justecon sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'En tiu tempo Judujo estos savita, kaj Jerusalem ekvivos sendanĝere, kaj oni nomos ĝin jene: La Eternulo estas nia justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Ĉar tiele diras la Eternulo: Ne mankos ĉe David viro, sidanta sur la trono de la domo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'Kaj ĉe la pastroj Levidoj neniam mankos antaŭ Mi viro, alportanta bruloferon kaj fumiganta farunoferon kaj faranta buĉoferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Kaj aperis vorto de la Eternulo al Jeremia, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'Tiele diras la Eternulo: Se oni povos ĉesigi Mian interligon pri la tago kaj Mian interligon pri la nokto, kaj la tago kaj nokto ne estu en sia tempo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'tiam povos esti ĉesigita Mia interligo kun Mia servanto David, ke ne estu ĉe li filo, reĝanta sur lia trono, kaj kun la Levidoj pastroj, Miaj servistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Kiel nekalkulebla estas la armeo de la ĉielo kaj nemezurebla la sablo de la maro, tiel Mi multigos la idaron de Mia servanto David, kaj la Levidojn, kiuj faras servadon al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Kaj aperis vorto de la Eternulo al Jeremia, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, 'Ĉu vi ne vidas, kiel ĉi tiu popolo parolas kaj diras: La du gentojn, kiujn la Eternulo elektis, Li forpuŝis? Kaj ili malestimas Mian popolon, kvazaŭ ĝi jam ne estus popolo antaŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'Tiele diras la Eternulo: Se Mi ne farus interligon pri tago kaj nokto kaj Miajn leĝojn pri la ĉielo kaj la tero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'tiam Mi forpuŝus la idaron de Jakob kaj de Mia servanto David, ne prenante el lia idaro regantojn super la idaro de Abraham, Isaak, kaj Jakob; ĉar Mi revenigos iliajn forkaptitojn kaj kompatos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Jen estas la vorto, kiu aperis al Jeremia de la Eternulo, kiam Nebukadnecar, reĝo de Babel, kaj lia tuta militistaro, kaj ĉiuj regnoj de la tero, kiuj estis sub la regado de lia mano, kaj ĉiuj popoloj militis kontraŭ Jerusalem kaj kontraŭ ĉiuj ĝiaj urboj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'Tiele diras la Eternulo, Dio de Izrael: Iru kaj parolu al Cidkija, reĝo de Judujo, kaj diru al li: Tiele diras la Eternulo: Jen Mi transdonos ĉi tiun urbon en la manon de la reĝo de Babel, kaj li forbruligos ĝin per fajro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'kaj vi ne saviĝos el lia mano, sed vi estos kaptita kaj transdonita en lian manon, kaj viaj okuloj rigardos la okulojn de la reĝo de Babel, kaj lia buŝo parolos kun via buŝo, kaj vi iros en Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Tamen aŭskultu la vorton de la Eternulo, ho Cidkija, reĝo de Judujo: Tiele diras la Eternulo pri vi: Vi ne mortos de glavo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'vi mortos en paco; kaj kiel oni faris brulon al viaj patroj, la antaŭaj reĝoj, kiuj estis antaŭ vi, tiel oni faros brulon al vi, kaj oni priploros vin: Ho ve, sinjoro! Ĉar Mi parolis la vorton, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Kaj la profeto Jeremia raportis al Cidkija, reĝo de Judujo, ĉiujn tiujn vortojn en Jerusalem,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'dum la militistaro de la reĝo de Babel militis kontraŭ Jerusalem, kaj kontraŭ ĉiuj restintaj urboj de Judujo, kontraŭ Laĥiŝ kaj kontraŭ Azeka; ĉar ili restis ankoraŭ el la fortikaĵaj urboj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Jen estas la vorto, kiu aperis al Jeremia de la Eternulo, post kiam la reĝo Cidkija faris interligon kun la tuta popolo de Jerusalem, proklamante al ili liberecon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'ke ĉiu forliberigu sian sklavon kaj sian sklavinon, Hebreon kaj Hebreinon, por ke inter ili neniu el la Judoj tenu sian fraton en sklaveco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Kaj obeis ĉiuj potenculoj kaj la tuta popolo, kiuj aliĝis al la interligo, por ke ĉiu forliberigu sian sklavon kaj sian sklavinon, por ne plu teni ilin en sklaveco; ili obeis kaj forliberigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Sed poste ili denove reprenis la sklavojn kaj la sklavinojn, kiujn ili forliberigis, kaj devigis ilin fariĝi sklavoj kaj sklavinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Tiam aperis la vorto de la Eternulo al Jeremia, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'Tiele diras la Eternulo, Dio de Izrael: Mi faris interligon kun viaj patroj en la tempo, kiam Mi elkondukis ilin el la lando Egipta, el la domo de sklaveco, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'En ĉiu sepa jaro forliberigu ĉiu sian fraton Hebreon, kiu estas vendita al vi kaj servis al vi ses jarojn, kaj permesu al li foriri de vi tute libera; sed viaj patroj ne aŭskultis Min kaj ne alklinis sian orelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Nun vi pentis, kaj faris bonon antaŭ Miaj okuloj, proklamante liberecon unu por la alia, kaj vi faris interligon antaŭ Mi en la domo, kiu estas nomata per Mia nomo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'sed vi ŝanĝiĝis, kaj malsanktigis Mian nomon, kaj reprenis al vi ĉiu sian sklavon kaj sian sklavinon, kiujn vi forliberigis, ke ili estu memstaraj, kaj vi devigis ilin, ke ili estu por vi sklavoj kaj sklavinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Tial tiele diras la Eternulo: Vi ne obeis Min, ke vi proklamu liberecon ĉiu al sia frato kaj unu al la alia; jen Mi proklamas koncerne vin liberecon al la glavo, pesto, kaj malsato, kaj Mi faros vin objekto de teruro por ĉiuj regnoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'Kaj Mi transdonos la homojn, kiuj malobeis Mian interligon, kiuj ne plenumis la vortojn de la interligo, kiun ili faris antaŭ Mi, kiam ili dishakis la bovidon en du partojn kaj trairis tra la dishakitaj partoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'la eminentulojn de Judujo kaj la eminentulojn de Jerusalem, la korteganojn kaj la pastrojn, kaj la tutan popolon de la lando, kiuj trairis tra la dishakitaj partoj de la bovido;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'Mi transdonos ilin en la manojn de iliaj malamikoj, kaj en la manojn de tiuj, kiuj celas ilian morton; kaj iliaj kadavroj estos manĝaĵo por la birdoj de la ĉielo kaj por la bestoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Kaj Cidkijan, reĝon de Judujo, kaj liajn eminentulojn Mi transdonos en la manojn de iliaj malamikoj, kaj en la manojn de tiuj, kiuj celas ilian morton, kaj en la manojn de la militistaro de la reĝo de Babel, kiu foriris de vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Jen Mi faros ordonon, diras la Eternulo, kaj Mi revenigos ilin al ĉi tiu urbo, kaj ili atakos ĝin kaj venkoprenos ĝin kaj forbruligos ĝin per fajro, kaj la urbojn de Judujo Mi faros dezerto tiel, ke neniu en ĝi loĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Jen estas la vorto, kiu aperis al Jeremia de la Eternulo en la tempo de Jehojakim, filo de Joŝija, reĝo de Judujo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Iru en la domon de la Reĥabidoj, kaj parolu al ili, kaj venigu ilin en la domon de la Eternulo en unu el la ĉambroj, kaj trinkigu al ili vinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Kaj mi prenis Jaazanjan, filon de Jeremia, filo de Ĥabacinja, kaj liajn fratojn kaj ĉiujn liajn filojn kaj la tutan domon de la Reĥabidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'kaj mi venigis ilin en la domon de la Eternulo, en la ĉambron de la filoj de Ĥanan, filo de Jigdalja, homo de Dio, kiu estas apud la ĉambro de la princoj, super la ĉambro de Maaseja, filo de Ŝalum, gardisto de pordego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Kaj mi starigis antaŭ la filoj de la domo de la Reĥabidoj pokalojn plenajn de vino, kaj kalikojn, kaj mi diris al ili: Trinku vinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Sed ili diris: Ni ne trinkas vinon, ĉar nia patro Jonadab, filo de Reĥab, ordonis al ni, dirante: Ne trinku vinon, vi kaj viaj infanoj, eterne;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'kaj domon ne konstruu, kaj semon ne semu, kaj vinberĝardenon ne plantu kaj ne posedu, sed loĝu en tendoj dum via tuta vivo, por ke vi vivu longan tempon sur la tero, sur kiu vi loĝas fremdule.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Kaj ni obeis la voĉon de nia patro Jonadab, filo de Reĥab, en ĉio, kion li ordonis al ni, ne trinkante vinon dum nia tuta vivo, nek ni, nek niaj edzinoj, nek niaj filoj, nek niaj filinoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'kaj ne konstruante domojn por nia loĝado, kaj ne havante por ni vinberĝardenon, nek kampon, nek semadon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'sed ni loĝas en tendoj, kaj obeas, kaj faras ĉion tiel, kiel ordonis al ni nia patro Jonadab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Kaj kiam Nebukadnecar, reĝo de Babel, venis kontraŭ la landon, ni diris: Venu, ni iru en Jerusalemon, for de la militistaro de la Ĥaldeoj kaj de la militistaro de Sirio; kaj ni restis en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Kaj aperis vorto de la Eternulo al Jeremia, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'Tiele diras la Eternulo Cebaot, Dio de Izrael: Iru kaj diru al la Judujanoj kaj al la loĝantoj de Jerusalem: Ĉu vi ne akceptos moralinstruon, obeante Miajn vortojn? diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'Plenumataj estas la vortoj de Jonadab, filo de Reĥab, kiujn li ordonis al siaj filoj, ke ili ne trinku vinon, kaj ili ne trinkas ĝis nun, ĉar ili obeas la ordonon de sia patro; sed Mi diris al vi, konstante diradis, kaj vi ne obeis Min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'Mi sendis al vi ĉiujn Miajn servantojn, la profetojn, Mi konstante sendadis, dirante: Deturnu vin ĉiu de sia malbona vojo, plibonigu vian konduton, ne sekvu aliajn diojn, servante al ili, tiam vi restos sur la tero, kiun Mi donis al vi kaj al viaj patroj; sed vi ne alklinis vian orelon kaj ne obeis Min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'La filoj de Jonadab, filo de Reĥab, plenumis la ordonon de sia patro, kiun li donis al ili; sed ĉi tiu popolo ne obeis Min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Tial tiele diras la Eternulo, Dio Cebaot, Dio de Izrael: Jen Mi venigos sur Judujon kaj sur ĉiujn loĝantojn de Jerusalem la tutan malbonon, kiun Mi eldiris pri ili, pro tio, ke Mi parolis al ili kaj ili ne aŭskultis, Mi vokis al ili kaj ili ne respondis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Sed al la domo de la Reĥabidoj Jeremia diris: Tiele diras la Eternulo Cebaot, Dio de Izrael: Pro tio, ke vi obeis la ordonon de via patro Jonadab kaj observis ĉiujn liajn ordonojn, kaj agis konforme al ĉio, kion li rekomendis al vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'pro tio tiele diras la Eternulo Cebaot, Dio de Izrael: Neniam mankos ĉe Jonadab, filo de Reĥab, viro, staranta antaŭ Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'En la kvara jaro de Jehojakim, filo de Joŝija, reĝo de Judujo, aperis jena vorto al Jeremia de la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'Prenu al vi libron-rulaĵon, kaj skribu en ĝin ĉiujn vortojn, kiujn Mi diris al vi pri Izrael kaj pri Jehuda kaj pri ĉiuj nacioj, de la tago, en kiu Mi parolis al vi, de la tempo de Joŝija ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Eble la domo de Jehuda aŭdos pri la tuta malbono, kiun Mi intencas fari al ili, kaj ili returniĝos ĉiu de sia malbona vojo, por ke Mi pardonu ilian malbonagon kaj ilian pekon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Kaj Jeremia alvokis Baruĥon, filon de Nerija; kaj Baruĥ enskribis en libron-rulaĵon sub diktado de Jeremia ĉiujn vortojn de la Eternulo, kiujn Li diris al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Kaj Jeremia donis jenan ordonon al Baruĥ: Mi estas malliberigita, mi ne povas iri en la domon de la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'iru do vi, kaj legu laŭ la libro, kiun vi skribis sub mia diktado, la vortojn de la Eternulo en la orelojn de la popolo en la domo de la Eternulo en tago de fasto; kaj ankaŭ en la orelojn de ĉiuj Judoj, kiuj venis el siaj urboj, legu tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Eble falos ilia preĝo antaŭ la Eternulo, kaj ili returniĝos ĉiu de sia malbona vojo; ĉar granda estas la kolero kaj indigno, kiujn la Eternulo esprimis pri ĉi tiu popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Kaj Baruĥ, filo de Nerija, plenumis ĉion, kion ordonis la profeto Jeremia, kaj li voĉlegis el la libro la vortojn de la Eternulo en la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'En la kvina jaro de Jehojakim, filo de Joŝija, reĝo de Judujo, en la naŭa monato, oni proklamis faston antaŭ la Eternulo al la tuta popolo en Jerusalem, kaj al la tuta popolo, kiu venis el la urboj de Judujo en Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'Kaj Baruĥ voĉlegis el la libro la vortojn de Jeremia en la domo de la Eternulo, en la ĉambro de Gemarja, filo de la kanceliero Ŝafan, sur la supra korto, ĉe la nova pordego de la domo de la Eternulo, laŭte al la tuta popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Kaj Miĥaja, filo de Gemarja, filo de Ŝafan, aŭdis el la libro ĉiujn vortojn de la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'kaj li iris en la domon de la reĝo, en la ĉambron de la kanceliero. Kaj jen tie sidis ĉiuj eminentuloj: la kanceliero Eliŝama, Delaja, filo de Ŝemaja, Elnatan, filo de Aĥbor, Gemarja, filo de Ŝafan, Cidkija, filo de Ĥananja, kaj ĉiuj eminentuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'Kaj Miĥaja raportis al ili ĉiujn vortojn, kiujn li aŭdis, kiam Baruĥ legis el la libro en la orelojn de la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Tiam ĉiuj eminentuloj sendis al Baruĥ Jehudin, filon de Netanja, filo de Ŝelemja, filo de Kuŝi, por diri: La skribrulaĵon, el kiu vi legis en la orelojn de la popolo, prenu en vian manon, kaj venu. Kaj Baruĥ, filo de Nerija, prenis kun si la skribrulaĵon, kaj venis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'Kaj ili diris al li: Sidiĝu, kaj voĉlegu ĝin al ni. Kaj Baruĥ voĉlegis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Kiam ili aŭdis ĉiujn vortojn, ili eksentis teruron unu antaŭ la alia, kaj ili diris al Baruĥ: Ni raportos al la reĝo ĉiujn ĉi tiujn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Kaj ili demandis Baruĥon, dirante: Diru al ni, kiamaniere vi skribis ĉiujn tiujn vortojn el lia buŝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Kaj Baruĥ respondis al ili: El sia buŝo li elparolis al mi ĉiujn tiujn vortojn, kaj mi skribis en la libron per inko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Kaj la eminentuloj diris al Baruĥ: Iru kaj kaŝiĝu, vi kaj Jeremia, ke neniu sciu, kie vi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Ili venis al la reĝo en la palacon, kaj la skribrulaĵon ili restigis en la ĉambro de la kanceliero Eliŝama; kaj ili raportis al la reĝo ĉiujn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Tiam la reĝo sendis Jehudin, por preni la skribrulaĵon; kaj Jehudi prenis ĝin el la ĉambro de la kanceliero Eliŝama, kaj voĉlegis ĝin al la reĝo, kaj al ĉiuj eminentuloj, kiuj staris apud la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'La reĝo sidis en la vintra domo en la naŭa monato, kaj antaŭ li brulis fajrujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Kaj ĉiufoje, kiam Jehudi tralegis tri aŭ kvar kolumnojn, la reĝo detranĉis ilin per tranĉileto de skribisto, kaj ĵetis en la fajron, kiu estis en la fajrujo, ĝis la tuta skribrulaĵo forbrulis sur la fajro, kiu estis en la fajrujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Kaj ne timis kaj ne disŝiris siajn vestojn la reĝo, nek ĉiuj liaj servantoj, kiuj aŭdis ĉiujn tiujn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Kvankam Elnatan kaj Delaja kaj Gemarja petis la reĝon, ke li ne forbruligu la skribrulaĵon, li ne obeis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Kaj la reĝo ordonis al Jeraĥmeel, filo de la reĝo, al Seraja, filo de Azriel, kaj al Ŝelemja, filo de Abdeel, kapti la skribiston Baruĥ kaj la profeton Jeremia; sed la Eternulo ilin kaŝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Kaj aperis jena vorto de la Eternulo al Jeremia, post kiam la reĝo forbruligis la skribrulaĵon, kaj la vortojn, kiujn Baruĥ skribis sub diktado de Jeremia:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, 'Prenu al vi denove alian skribrulaĵon, kaj skribu sur ĝi ĉiujn antaŭajn vortojn, kiuj estis sur la unua skribrulaĵo, kiun forbruligis Jehojakim, reĝo de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'Kaj pri Jehojakim, reĝo de Judujo, diru: Tiele diras la Eternulo: Vi forbruligis tiun skribrulaĵon, dirante: Kial vi skribis sur ĝi, ke venos la reĝo de Babel kaj ruinigos ĉi tiun landon kaj ekstermos sur ĝi homojn kaj brutojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Tial tiele diras la Eternulo pri Jehojakim, reĝo de Judujo: Ne estos ĉi li sidanto sur la trono de David, kaj lia kadavro estos ĵetita al la varmego de la tago kaj al la malvarmo de la nokto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'kaj Mi punos lin kaj lian idaron kaj liajn servantojn, pro ilia malbonago; kaj Mi venigos sur ilin kaj sur la loĝantojn de Jerusalem kaj sur la Judujanojn la tutan malbonon, pri kiu Mi diris al ili, sed ili ne aŭskultis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Kaj Jeremia prenis alian skribrulaĵon, kaj donis ĝin al la skribisto Baruĥ, filo de Nerija; kaj tiu skribis sur ĝi sub diktado de Jeremia ĉiujn vortojn de la libro, kiun Jehojakim, reĝo de Judujo, forbruligis per fajro; kaj al ili estis aldonitaj ankoraŭ multaj similaj vortoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Kaj ekreĝis la reĝo Cidkija, filo de Joŝija, anstataŭ Konja, filo de Jehojakim, ĉar Nebukadnecar, reĝo de Babel, faris lin reĝo en la Juda lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Li kaj liaj servantoj kaj la popolo de la lando ne obeis la vortojn de la Eternulo, kiujn Li diris per la profeto Jeremia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Tamen la reĝo Cidkija sendis Jehuĥalon, filon de Ŝelemja, kaj Cefanjan, filon de la pastro Maaseja, al la profeto Jeremia, por diri: Preĝu, mi petas, por ni al la Eternulo, nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Jeremia tiam iradis libere inter la popolo, kaj oni ne metis lin en malliberejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'Dume la militistaro de Faraono eliris el Egiptujo, kaj kiam la Ĥaldeoj, kiuj sieĝis Jerusalemon, tion aŭdis, ili foriris de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Kaj aperis vorto de la Eternulo al la profeto Jeremia, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'Tiele diras la Eternulo, Dio de Izrael: Tiele diru al la reĝo de Judujo, kiu sendis vin al Mi, por demandi Min: Jen la militistaro de Faraono, kiu eliris kun helpo al vi, iros returne en sian landon Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'Kaj la Ĥaldeoj revenos kaj militos kontraŭ ĉi tiu urbo, kaj prenos ĝin kaj forbruligos ĝin per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Tiele diras la Eternulo: Ne trompu vin mem, dirante: La Ĥaldeoj foriros de ni; ĉar ili ne foriros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Ĉar se vi eĉ venkobatus la tutan militistaron de la Ĥaldeoj, kiu militas kontraŭ vi, kaj restus el ili nur kelkaj vunditoj, ĉi tiuj leviĝus ĉiu el sia tendo kaj forbruligus ĉi tiun urbon per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Kiam la militistaro de la Ĥaldeoj, timante la militistaron de Faraono, foriris de Jerusalem,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'tiam Jeremia eliris el Jerusalem, por iri en la landon de Benjamen, por ricevi sian tiean heredaĵon inter la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Sed kiam li estis ĉe la Pordego de Benjamen, tie estis la gardistestro, kies nomo estis Jirija, filo de Ŝelemja, filo de Ĥananja; li kaptis la profeton Jeremia, dirante: Vi volas transkuri al la Ĥaldeoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Jeremia diris: Tio estas malvero, mi ne volas transkuri al la Ĥaldeoj. Sed tiu ne aŭskultis lin; kaj Jirija kaptis Jeremian kaj alkondukis lin al la eminentuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'La eminentuloj ekkoleris kontraŭ Jeremia, kaj batis lin, kaj metis lin en malliberejon, en la domo de la skribisto Jonatan, ĉar tiun domon oni faris malliberejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'Post kiam Jeremia venis en la malliberejon kaj en karceron, kaj Jeremia estis sidinta tie longan tempon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'la reĝo Cidkija sendis kaj prenis lin, kaj la reĝo sekrete en sia domo demandis lin, dirante: Ĉu estas ia vorto de la Eternulo? Kaj Jeremia diris: Estas: vi estos transdonita en la manon de la reĝo de Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Kaj Jeremia diris al la reĝo Cidkija: Per kio mi pekis antaŭ vi aŭ antaŭ viaj servantoj aŭ antaŭ ĉi tiu popolo, ke vi metis min en malliberejon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Kaj kie estas viaj profetoj, kiuj profetis al vi, ke la reĝo de Babel ne venos kontraŭ vin kaj kontraŭ ĉi tiun landon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Nun aŭskultu, mia sinjoro, ho reĝo, mia petego falu antaŭ vi: ne revenigu min en la domon de la skribisto Jonatan, mi ne mortu tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Tiam la reĝo Cidkija ordonis, ke oni tenu Jeremian sur la korto de la malliberejo; kaj oni donadis al li bulon da pano ĉiutage el la strato de la bakistoj, ĝis konsumiĝis la tuta pano en la urbo. Tiamaniere Jeremia restis sur la korto de la malliberejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Ŝefatja, filo de Matan, Gedalja, filo de Paŝĥur, Juĥal, filo de Ŝelemja, kaj Paŝĥur, filo de Malkija, aŭdis la vortojn, kiujn Jeremia parolis al la tuta popolo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'Tiele diras la Eternulo: Kiu restos en ĉi tiu urbo, tiu mortos de glavo, de malsato, aŭ de pesto; sed kiu eliros al la Ĥaldeoj, tiu restos vivanta, lia animo estos lia akiro, kaj li vivos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Tiele diras la Eternulo: Ĉi tiu urbo estos transdonita en la manojn de la militistaro de la reĝo de Babel, kaj li venkoprenos ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Tiam la eminentuloj diris al la reĝo: Oni devas mortigi ĉi tiun homon, ĉar li senfortigas la manojn de la militistoj, kiuj restis en ĉi tiu urbo, kaj la manojn de la tuta popolo, parolante al ili tiajn vortojn; ĉar ĉi tiu homo deziras al ĉi tiu popolo ne pacon, sed nur malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Kaj la reĝo Cidkija diris: Jen li estas en viaj manoj, ĉar la reĝo nenion povas fari kontraŭ via volo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Tiam ili prenis Jeremian, kaj ĵetis lin en la kavon de Malkija, filo de la reĝo, kiu troviĝis sur la korto de la malliberejo, kaj oni mallevis Jeremian per ŝnuroj; en la kavo ne estis akvo, sed nur ŝlimo, kaj Jeremia eniĝis en la ŝlimon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Kaj Ebed-Meleĥ, Etiopo, eŭnuko, kiu estis en la domo de la reĝo, aŭdis, ke oni ĵetis Jeremian en la kavon; la reĝo tiam sidis ĉe la Pordejo de Benjamen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Tiam Ebed-Meleĥ eliris el la domo de la reĝo, kaj ekparolis al la reĝo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, 'Mia sinjoro, ho reĝo! malbone agis tiuj homoj, ke ili tion faris al la profeto Jeremia, ke ili ĵetis lin en la kavon: li mortos tie de malsato, ĉar jam en ekzistas pano en la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Tiam la reĝo ordonis al la Etiopo Ebed-Meleĥ, dirante: Prenu kun vi de ĉi tie tridek homojn, kaj eltiru la profeton Jeremia el la kavo, antaŭ ol li mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Kaj Ebed-Meleĥ prenis kun si la homojn kaj iris en la domon de la reĝo sub la trezorejon, kaj prenis de tie malnovajn kaj eluzitajn ĉifonojn kaj mallevis ilin per ŝnuroj al Jeremia en la kavon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'Kaj la Etiopo Ebed-Meleĥ diris al Jeremia: Metu la eluzitajn ĉifonojn sub viajn akselojn sub la ŝnurojn; kaj Jeremia tiel faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Kaj oni ektiris Jeremian per la ŝnuroj kaj eltiris lin el la kavo; kaj Jeremia restis sur la korto de la malliberejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Kaj la reĝo Cidkija sendis, kaj venigis la profeton Jeremia al si, al la tria enirejo de la domo de la Eternulo; kaj la reĝo diris al Jeremia: Mi demandos de vi ion, kaŝu antaŭ mi nenion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Kaj Jeremia diris al Cidkija: Se mi diros al vi, vi ja mortigos min; kaj se mi donos al vi konsilon, vi ja ne obeos min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Tiam la reĝo Cidkija sekrete ĵuris al Jeremia, dirante: Mi ĵuras per la Eternulo, kiu kreis al ni ĉi tiun animon, ke mi ne mortigos vin, kaj ne transdonos vin en la manojn de tiuj homoj, kiuj celas vian morton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Kaj Jeremia diris al Cidkija: Tiele diras la Eternulo, Dio Cebaot, Dio de Izrael: Se vi eliros al la eminentuloj de la reĝo de Babel, via animo restos vivanta, kaj ĉi tiu urbo ne estos forbruligita per fajro, kaj vi kaj via domo vivos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'sed se vi ne eliros al la eminentuloj de la reĝo de Babel, tiam ĉi tiu urbo estos transdonita en la manojn de la Ĥaldeoj, kaj ili forbruligos ĝin per fajro, kaj vi ne saviĝos el iliaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Kaj la reĝo Cidkija diris al Jeremia: Mi timas la Judojn, kiuj transkuris al la Ĥaldeoj, ke oni ne transdonu min en iliajn manojn, por ke ili mokturmentu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Tiam Jeremia diris: Oni ne transdonos vin; aŭskultu la voĉon de la Eternulo pri tio, kion mi diras al vi; tiam estos bone al vi, kaj via animo restos vivanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Sed se vi ne volos eliri, en tia okazo jen estas tio, kion la Eternulo vidigis al mi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Jen ĉiuj virinoj, kiuj restis en la domo de la reĝo de Judujo, estos elkondukitaj al la eminentuloj de la reĝo de Babel, kaj ili diros: Viaj konsolantoj forlogis vin kaj superfortis vin; viaj piedoj enprofundiĝis en koton, kaj tiuj foriĝis de vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Kaj ĉiujn viajn edzinojn kaj viajn filojn oni forkondukos al la Ĥaldeoj, kaj vi ne saviĝos el iliaj manoj; vi estos kaptita en la manojn de la reĝo de Babel, kaj ĉi tiu urbo estos forbruligita per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Kaj Cidkija diris al Jeremia: Neniu devas scii tiujn vortojn, alie vi mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Se la eminentuloj aŭdos, ke mi parolis kun vi, kaj ili venos al vi, kaj diros al vi: Sciigu al ni, kion vi diris al la reĝo, ne kaŝu antaŭ ni, por ke ni ne mortigu vin, kaj kion la reĝo diris al vi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'tiam respondu al ili: Mi humile petegis la reĝon, ke li ne revenigu min en la domon de Jonatan, mi ne mortu tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'Kaj venis ĉiuj eminentuloj al Jeremia kaj demandis lin, kaj li respondis al ili konforme al ĉiuj vortoj, kiujn ordonis la reĝo; kaj ili silente foriris de li, ĉar ili nenion eksciis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'Kaj Jeremia restis sur la korto de la malliberejo ĝis la tago, en kiu Jerusalem estis venkoprenita; kaj li tie estis, kiam Jerusalem estis venkoprenita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'En la naŭa jaro de Cidkija, reĝo de Judujo, en la deka monato, venis Nebukadnecar, reĝo de Babel, kun sia tuta militistaro al Jerusalem, kaj eksieĝis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'En la dek-unua jaro de Cidkija, en la kvara monato, en la naŭa tago de la monato, oni faris enrompon en la urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'Kaj eniris ĉiuj eminentuloj de la reĝo de Babel, kaj haltis ĉe la Meza Pordego: Nergal-Ŝarecer, Samgar-Nebu, Sarseĥim Rab-saris, Nergal- Ŝarecer Rab-mag, kaj ĉiuj ceteraj eminentuloj de la reĝo de Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Kiam ilin ekvidis Cidkija, reĝo de Judujo, kaj ĉiuj militistoj, ili forkuris, kaj eliris en la nokto el la urbo tra la ĝardeno de la reĝo, tra la pordego inter la du muregoj, kaj ili iris sur la vojon, kiu kondukas al la stepo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Sed la Ĥaldea militistaro postkuris ilin, kaj atingis Cidkijan sur la stepo de Jeriĥo kaj kaptis lin, kaj alkondukis lin al Nebukadnecar, reĝo de Babel, en Riblan, en la lando Ĥamat, kaj ĉi tiu eldiris verdikton kontraŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Kaj la reĝo de Babel buĉis la filojn de Cidkija en Ribla antaŭ liaj okuloj, kaj ĉiujn eminentulojn de Judujo la reĝo de Babel buĉis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Kaj la okulojn de Cidkija li blindigis, kaj li ligis lin per katenoj, por forkonduki lin en Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Kaj la domon de la reĝo kaj la domojn de la popolo la Ĥaldeoj forbruligis per fajro, kaj la muregojn de Jerusalem ili detruis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Kaj la ceteran popolon, kiu restis en la urbo, kaj la transkurintojn, kiuj transkuris al li, kaj la tutan reston de la popolo Nebuzaradan, estro de la korpogardistoj, forkondukis en Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Sed la malriĉulojn el la popolo, kiuj nenion havis, Nebuzaradan, estro de la korpogardistoj, restigis en la lando Juda kaj donis al ili tiam vinberĝardenojn kaj kampojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Sed pri Jeremia Nebukadnecar, reĝo de Babel, ordonis al Nebuzaradan, la estro de la korpogardistoj, jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Prenu lin, kaj atentu pri li, kaj faru al li nenion malbonan, sed agu kun li nur tiel, kiel li diros al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Kaj sendis Nebuzaradan, estro de la korpogardistoj, kaj Nebuŝazban Rab-saris, kaj Nergal-Ŝarecar Rab-mag, kaj ĉiuj estroj de la reĝo de Babel;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'ili sendis, kaj prenis Jeremian el la korto de la malliberejo, kaj transdonis lin al Gedalja, filo de Aĥikam, filo de Ŝafan, ke li konduku lin en sian domon; kaj li ekvivis inter la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'Kaj al Jeremia aperis jena vorto de la Eternulo, kiam li estis ankoraŭ tenata sur la korto de la malliberejo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Iru kaj diru al la Etiopo Ebed-Meleĥ jene: Tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi plenumos Miajn vortojn pri ĉi tiu urbo al malbono, ne al bono, kaj ili plenumiĝos antaŭ via vizaĝo en tiu tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Sed vin Mi savos en tiu tempo, diras la Eternulo, kaj vi ne estos transdonita en la manojn de tiuj homoj, kiujn vi timas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Ĉar Mi forsavos vin, kaj vi ne falos de glavo, kaj via animo estos via akiro; ĉar vi fidis Min, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Jen estas la vorto, kiu aperis al Jeremia de la Eternulo, post kiam Nebuzaradan, estro de la korpogardistoj, forliberigis lin el Rama, kiam li prenis lin, ligitan per ĉenoj, inter ĉiuj kaptitoj de Jerusalem kaj Judujo, forkondukataj en Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Kaj la estro de la korpogardistoj prenis Jeremian, kaj diris al li: La Eternulo, via Dio, eldiris ĉi tiun malfeliĉon kontraŭ ĉi tiu loko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'kaj la Eternulo tion venigis, kaj faris, kiel Li diris, ĉar vi pekis antaŭ la Eternulo kaj ne aŭskultis Lian voĉon; pro tio fariĝis al vi tia afero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Kaj nun jen hodiaŭ mi liberigis vin de la katenoj, kiuj estis sur viaj manoj; se plaĉas al vi iri kun mi en Babelon, iru, kaj mi zorgos pri vi; se ne plaĉas al vi iri kun mi en Babelon, ne faru tion; vidu, la tuta lando estas antaŭ vi; kien plaĉas al vi iri, tien iru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, '(Dum li ankoraŭ ne foriris,)Iru al Gedalja, filo de Aĥikam, filo de Ŝafan, kiun la reĝo de Babel starigis kiel estron super la urboj de Judujo, kaj restu kun li inter la popolo; aŭ kien plaĉas al vi iri, tien iru. Kaj la estro de la korpogardistoj donis al li manĝaĵon kaj donacon kaj forliberigis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Kaj Jeremia venis al Gedalja, filo de Aĥikam, en Micpan, kaj ekloĝis kun li inter la popolo, kiu restis en la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Kiam ĉiuj militestroj, kiuj estis sur la kampo, ili kaj iliaj homoj, aŭdis, ke la reĝo de Babel starigis Gedaljan, filon de Aĥikam, kiel estron de la lando, kaj ke li metis sub lian regadon la virojn, virinojn, infanojn, kaj malriĉulojn de la lando, kiuj ne estis transloĝigitaj en Babelon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'tiam ili venis al Gedalja en Micpan: Iŝmael, filo de Netanja, Joĥanan kaj Jonatan, filoj de Kareaĥ, Seraja, filo de Tanĥumet, la filoj de Efaj, Netofaano, kaj Jezanja, filo de Maaĥatano, ili kaj iliaj homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Kaj Gedalja, filo de Aĥikam, filo de Ŝafan, ĵuris al ili kaj al iliaj homoj, dirante: Ne timu servi al la Ĥaldeoj, restu en la lando kaj servu al la reĝo de Babel, kaj tiam estos al vi bone.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Mi restas en Micpa, por ke mi povu stariĝi antaŭ la vizaĝo de la Ĥaldeoj, kiuj venos al ni; sed vi enkolektu vinon kaj somerajn fruktojn kaj oleon kaj metu en viajn vazojn, kaj restu en viaj urboj, kiujn vi okupis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Ankaŭ ĉiuj Judoj, kiuj estis ĉe la Moabidoj, ĉe la Amonidoj, ĉe la Edomidoj, kaj en ĉiuj landoj, aŭdis, ke la reĝo de Babel restigis parton de la Judoj, kaj ke li starigis kiel reganton super ili Gedaljan, filon de Aĥikam, filo de Ŝafan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'Kaj ĉiuj tiuj Judoj revenis de ĉiuj lokoj, kien ili estis dispelitaj, kaj venis en la landon Judan al Gedalja en Micpan, kaj ili enkolektis tre multe da vino kaj da someraj fruktoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Sed Joĥanan, filo de Kareaĥ, kaj ĉiuj militestroj, kiuj estis sur la kampo, venis al Gedalja en Micpan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'Kaj ili diris al li: Ĉu vi scias, ke Baalis, reĝo de la Amonidoj, sendis Iŝmaelon, filon de Netanja, por ke li mortigu vin? Sed Gedalja, filo de Aĥikam, ne kredis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Tiam Joĥanan, filo de Kareaĥ, diris sekrete al Gedalja en Micpa jene: Permesu, ke mi iru kaj mortigu Iŝmaelon, filon de Netanja, kaj neniu tion scios; kial li vin mortigu, ke ĉiuj Judoj, kiuj kolektiĝis al vi, diskuru, kaj la restaĵo de la Judoj pereu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Sed Gedalja, filo de Aĥikam, diris al Joĥanan, filo de Kareaĥ: Ne faru tion, ĉar malveron vi parolas pri Iŝmael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'En la sepa monato Iŝmael, filo de Netanja, filo de Eliŝama, el la reĝa idaro, unu el la eminentuloj de la reĝo, kaj kun li dek viroj, venis al Gedalja, filo de Aĥikam, en Micpan, kaj ili kune tie manĝis en Micpa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Kaj leviĝis Iŝmael, filo de Netanja, kaj la dek viroj, kiuj estis kun li, kaj frapis Gedaljan, filon de Aĥikam, filo de Ŝafan, per glavo, kaj mortigis lin, kiun la reĝo de Babel starigis kiel reganton super la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Kaj ĉiujn Judojn, kiuj estis kun li, Gedalja, en Micpa, kaj la Ĥaldeojn, kiuj tie troviĝis, la militistojn, Iŝmael mortigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'En la dua tago post la mortigo de Gedalja, kiam neniu ankoraŭ sciis pri tio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'venis viroj el Ŝeĥem, el Ŝilo, kaj el Samario, okdek homoj, kun razitaj barboj kaj disŝiritaj vestoj, kun tranĉoj sur la korpo, kaj en iliaj manoj estis donacoj kaj olibano, por alporti ilin en la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Kaj Iŝmael, filo de Netanja, eliris al ili renkonte el Micpa, irante kaj plorante; kaj kiam li atingis ilin, li diris al ili: Iru al Gedalja, filo de Aĥikam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Sed kiam ili venis en la mezon de la urbo, Iŝmael, filo de Netanja, kune kun la homoj, kiuj estis kun li, buĉis ilin kaj ĵetis en kavon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Tamen troviĝis inter ili dek homoj, kiuj diris al Iŝmael: Ne mortigu nin, ĉar ni havas sur la kampo abundajn provizojn da tritiko, hordeo, oleo, kaj mielo. Kaj li haltis, kaj ne mortigis ilin kune kun iliaj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'La kavo, en kiun Iŝmael ĵetis ĉiujn kadavrojn de la homoj, kiujn li mortigis samtempe kiel Gedaljan, estis tiu, kiun faris la reĝo Asa kontraŭ Baaŝa, reĝo de Izrael; ĝin Iŝmael, filo de Netanja, plenigis per mortigitoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Kaj Iŝmael kaptis la tutan restaĵon de la popolo, kiu estis en Micpa, la reĝidinojn, kaj la tutan popolon, kiu restis en Micpa, kaj super kiu Nebuzaradan, la estro de la korpogardistoj, estrigis Gedaljan, filon de Aĥikam; ilin kaptis Iŝmael, filo de Netanja, kaj li pretiĝis, por transiri al la Amonidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Sed Joĥanan, filo de Kareaĥ, kaj ĉiuj militestroj, kiuj estis kun li, aŭdis pri la tuta malbono, kiun faris Iŝmael, filo de Netanja;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'kaj ili prenis ĉiujn virojn, kaj iris, por batali kontraŭ Iŝmael, filo de Netanja; kaj ili trovis lin ĉe la granda akvo, kiu estas en Gibeon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'Kiam la tuta popolo, kiu estis ĉe Iŝmael, ekvidis Joĥananon, filon de Kareaĥ, kaj ĉiujn militestrojn, kiuj estis kun li, ĝi ekĝojis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'Kaj la tuta popolo, kiun Iŝmael forkondukis el Micpa, deturnis sin, kaj iris al Joĥanan, filo de Kareaĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Sed Iŝmael, filo de Netanja, forkuris de Joĥanan kun ok homoj kaj iris al la Amonidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Joĥanan, filo de Kareaĥ, kaj ĉiuj militestroj, kiuj estis kun li, prenis la tutan restaĵon de la popolo, kiun li revenigis de Iŝmael, filo de Netanja, el Micpa, post kiam ĉi tiu mortigis Gedaljan, filon de Aĥikam: virojn, militistojn, virinojn, infanojn, kaj eŭnukojn, kiujn li revenigis el Gibeon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'Kaj ili iris kaj haltis ĉe la gastejo Kimham, apud Bet-Leĥem, por direkti sin al Egiptujo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'for de la Ĥaldeoj; ĉar ili timis ilin pro tio, ke Iŝmael, filo de Netanja, mortigis Gedaljan, filon de Aĥikam, kiun la reĝo de Babel estrigis super la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Kaj aliris ĉiuj militestroj, kaj Joĥanan, filo de Kareaĥ, kaj Jezanja, filo de Hoŝaja, kaj la tuta popolo, de la malgrandaj ĝis la grandaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'kaj diris al la profeto Jeremia: Ni humile petegas vin, preĝu por ni al la Eternulo, via Dio, por ĉi tiu tuta restaĵo; ĉar el multaj ni restis malmultaj, kiel viaj okuloj nin vidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'Kaj la Eternulo, via Dio, sciigu al ni la vojon, kiun ni devas iri, kaj kion ni devas fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Kaj la profeto Jeremia diris al ili: Mi aŭdis; jen mi preĝos al la Eternulo, via Dio, konforme al viaj vortoj, kaj ĉion, kion la Eternulo respondos al vi, mi raportos al vi; mi nenion kaŝos antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Kaj ili diris al Jeremia: La Eternulo estu inter ni atestanto vera kaj fidela, ke ni agos konforme al ĉio, kun kio la Eternulo, via Dio, sendos vin al ni;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'ĉu estos bone, ĉu estos malbone, ni aŭskultos la voĉon de la Eternulo, nia Dio, al kiu ni vin sendas, por ke estu al ni bone, se ni aŭskultos la voĉon de la Eternulo, nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Post dek tagoj aperis la vorto de la Eternulo al Jeremia;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'kaj li vokis Joĥananon, filon de Kareaĥ, kaj ĉiujn militestrojn, kiuj estis kun li, kaj la tutan popolon, de la malgrandaj ĝis la grandaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'kaj diris al ili: Tiele diras la Eternulo, Dio de Izrael, al kiu vi min sendis, por faligi vian petegon antaŭ Li:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Se vi restos en ĉi tiu lando, Mi vin aranĝos kaj ne ruinigos, Mi vin plantos kaj ne elradikigos; ĉar Mi pentas pri la malbono, kiun Mi faris al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Ne timu la reĝon de Babel, kiun vi nun timas; ne timu lin, diras la Eternulo, ĉar Mi estas kun vi, por helpi vin kaj por savi vin el lia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'Mi estos favorkora al vi, ke li vin kompatu kaj vin loĝigu sur via tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Sed se vi diros: Ni ne volas loĝi en ĉi tiu lando, kaj vi ne obeos la voĉon de la Eternulo, via Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'dirante: Ne, ni iros en la landon Egiptan, kie ni ne vidos militon kaj ne aŭdos sonon de trumpeto kaj ne malsatos koncerne panon, kaj tie ni restos:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'tiam aŭskultu la vorton de la Eternulo, ho restaĵo de Jehuda: tiele diras la Eternulo Cebaot, Dio de Izrael: Se vi turnos vian vizaĝon, por iri en Egiptujon, kaj vi iros, por tie ekloĝi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'tiam la glavo, kiun vi timas, atingos vin tie, en la lando Egipta, kaj la malsato, pri kiu vi zorgas, persekutos vin tie en Egiptujo, kaj tie vi mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Tiamaniere ĉiuj homoj, kiuj turnis sian vizaĝon, por iri en Egiptujon, por tie ekloĝi, mortos de glavo, de malsato, kaj de pesto, kaj neniu el ili restos, nek forsaviĝos de la malbono, kiun Mi venigos sur ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Ĉar tiele diras la Eternulo Cebaot, Dio de Izrael: Kiel elverŝiĝis Mia kolero kaj indigno sur la loĝantojn de Jerusalem, tiel Mia kolero elverŝiĝos sur vin, kiam vi venos en Egiptujon, kaj vi fariĝos objekto de ĵuro, de teruro, de malbeno, kaj de honto, kaj vi ne plu vidos ĉi tiun lokon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Pri vi, ho restaĵo de Jehuda, la Eternulo parolis: Ne iru en Egiptujon; sciu, ke Mi avertis vin hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Vi fariĝis kulpaj kontraŭ viaj propraj animoj; ĉar vi sendis min al la Eternulo, via Dio, dirante: Preĝu por ni al la Eternulo, nia Dio, kaj ĉion, kion diros la Eternulo, nia Dio, sciigu al ni, por ke ni tion faru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Kaj mi sciigis al vi hodiaŭ, sed vi ne aŭskultis la voĉon de la Eternulo, via Dio, nek ĉion, kun kio Li sendis min al vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'sciu do, ke vi mortos de glavo, de malsato, kaj de pesto, sur la loko, kien vi volas iri, por tie ekloĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Kiam Jeremia finis antaŭ la tuta popolo la raportadon pri ĉiuj vortoj de la Eternulo, ilia Dio, pri ĉiuj vortoj, kun kiuj la Eternulo, ilia Dio, sendis lin al ili,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'tiam Azarja, filo de Hoŝaja, kaj Joĥanan, filo de Kareaĥ, kaj ĉiuj malhumilaj homoj diris al Jeremia: Malveron vi parolas; la Eternulo, nia Dio, ne sendis vin, por diri: Ne iru en Egiptujon, por tie ekloĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'sed nur Baruĥ, filo de Nerija, instigas vin kontraŭ ni, por transdoni nin en la manojn de la Ĥaldeoj, por ke ili mortigu nin aŭ transloĝigu nin en Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'Tiamaniere Joĥanan, filo de Kareaĥ, kaj ĉiuj militestroj, kaj la tuta popolo, ne obeis la voĉon de la Eternulo, por resti en la lando Juda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Kaj Joĥanan, filo de Kareaĥ, kaj ĉiuj militestroj prenis la tutan restaĵon de la Judoj, kiuj revenis el ĉiuj nacioj, kien ili estis dispelitaj, por loĝi en la lando Juda:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'la virojn, la virinojn, la infanojn, la reĝidinojn, kaj ĉiujn, kiujn Nebuzaradan, estro de la korpogardistoj, restigis kun Gedalja, filo de Aĥikam, filo de Ŝafan, kaj la profeton Jeremia, kaj Baruĥon, filon de Nerija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'Kaj ili iris en la landon Egiptan, ne obeante la voĉon de la Eternulo, kaj venis ĝis Taĥpanĥes.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Kaj aperis vorto de la Eternulo al Jeremia en Taĥpanĥes, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Prenu en vian manon grandajn ŝtonojn, kaj antaŭ la okuloj de la Judaj viroj kaŝu ilin en la kalko en la brikfarejo, kiu troviĝas ĉe la enirejo de la domo de Faraono en Taĥpanĥes;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'kaj diru al ili: Tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi sendos, kaj venigos Nebukadnecaron, reĝon de Babel, Mian servanton, kaj Mi starigos lian tronon supre de ĉi tiuj ŝtonoj, kiujn Mi kaŝis, kaj li starigos sur ili sian tendon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Kaj li venos, kaj frapos la landon Egiptan: kiu estas destinita al la morto, tiu ricevos la morton; kiu estas destinita al kaptiteco, tiu iros en kaptitecon; kaj kiu estas destinita al glavo, tiun trafos glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'Kaj Mi ekbruligos fajron en la domoj de la dioj de Egiptujo, kaj ĝi bruligos ilin kaj forkaptos. Kaj li ĉirkaŭkovros sin per la havo de la lando Egipta, kiel paŝtisto kovras sin per sia vesto, kaj li eliros el tie bonstate.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Kaj li rompos la statuojn de la templo de la suno en la lando Egipta, kaj la domojn de la dioj de Egiptujo li forbruligos per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Jen estas la vorto, kiu aperis al Jeremia pri ĉiuj Judoj, kiuj loĝas en la lando Egipta, kiuj loĝas en Migdol, en Taĥpanĥes, en Nof, kaj en la lando Patros:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'Tiele diras la Eternulo Cebaot, Dio de Izrael: Vi vidis la tutan malbonon, kiun Mi venigis sur Jerusalemon kaj sur ĉiujn urbojn de Judujo; jen ili estas nun dezertaj, kaj neniu loĝas en ili,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'pro iliaj malbonagoj, kiujn ili faris, kolerigante Min, irante incensi kaj servi al aliaj dioj, kiujn ne konis ili, nek vi, nek viaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Mi sendis al vi ĉiujn Miajn servantojn, la profetojn, Mi konstante sendadis, dirante: Ne faru tiun abomenindan aferon, kiun Mi malamas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Sed ili ne obeis, kaj ne alklinis sian orelon, por deturni sin de siaj malbonagoj, por ne incensi al aliaj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Pro tio elverŝiĝis Mia indigno kaj kolero, kaj ĝi ekbrulis en la urboj de Judujo kaj sur la stratoj de Jerusalem, kaj ili ruiniĝis kaj dezertiĝis, kiel oni nun vidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Kaj nun tiele diras la Eternulo, Dio Cebaot, Dio de Izrael: Kial vi faras grandan malbonon al viaj propraj animoj, por ke ekstermiĝu ĉe vi viroj kaj virinoj, infanoj kaj suĉinfanoj en Judujo, por ke nenio restu ĉe vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'Kial vi kolerigas Min per la faroj de viaj manoj, incensante al aliaj dioj en la lando Egipta, kien vi venis, por tie loĝi, por ke vi ekstermiĝu kaj por ke vi fariĝu objekto de malbeno kaj de honto inter ĉiuj nacioj de la tero?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Ĉu vi forgesis la malbonaĵojn de viaj patroj kaj la malbonaĵojn de la reĝoj de Judujo, la malbonaĵojn de iliaj edzinoj, viajn malbonaĵojn, kaj la malbonaĵojn de viaj edzinoj, kiujn ili faris en la lando Juda kaj sur la stratoj de Jerusalem?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Ili ne humiliĝis ĝis la nuna tago, ili ne timas kaj ne agas laŭ Mia instruo kaj laŭ Miaj leĝoj, kiujn Mi donis al vi kaj al viaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Tial tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi turnos Mian vizaĝon kontraŭ vin por malfeliĉo kaj por ekstermi la tutan Judujon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Kaj Mi prenos la restaĵon de la Judoj, kiuj turnis sian vizaĝon, por iri en la landon Egiptan, por tie ekloĝi, kaj ili ĉiuj ekstermiĝos en la lando Egipta; ili falos de glavo, de malsato ili ekstermiĝos, de la malgrandaj ĝis la grandaj; de glavo kaj de malsato ili mortos, kaj ili fariĝos objekto de ĵuro, de teruro, de malbeno, kaj de honto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Kaj Mi punos tiujn, kiuj loĝas en la lando Egipta, kiel Mi punis Jerusalemon, per glavo, per malsato, kaj per pesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'Kaj neniu saviĝos nek restos el la restaĵo de la Judoj, kiuj venis en la landon Egiptan, por loĝi tie kelktempe kaj por poste reiri en la landon Judan, kien ili sopiras per sia animo reveni kaj tie loĝi; ili ne revenos, krom tiuj, kiuj forkuros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Tiam respondis al Jeremia ĉiuj viroj, kiuj sciis, ke iliaj edzinoj incensas al aliaj dioj, kaj ĉiuj virinoj, kiuj staris en granda amaso, kaj la tuta popolo, kiu loĝis en la lando Egipta, en Patros; ili diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'Tion, kion vi diris al ni en la nomo de la Eternulo, ni ne obeos al vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'sed ni faros ĉion laŭ la vortoj, kiuj eliras el nia buŝo, ni incensos al la reĝino de la ĉielo, ni verŝos al ŝi verŝoferojn, kiel faris ni kaj niaj patroj, niaj reĝoj kaj niaj eminentuloj, en la urboj de Judujo kaj sur la stratoj de Jerusalem; tiam ni havis abundan panon, kaj estis al ni bone, kaj malbonon ni ne vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Sed de tiu tempo, kiam ni ĉesis incensi al la reĝino de la ĉielo kaj verŝi al ŝi verŝoferojn, ĉio mankas al ni, kaj ni pereas de glavo kaj de malsato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'Kaj kiam ni incensas al la reĝino de la ĉielo kaj verŝas al ŝi verŝoferojn, ĉu sen la scio de niaj edzoj ni faras al ŝi kukojn kun ŝia bildo kaj verŝas al ŝi verŝoferojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Tiam Jeremia diris al la tuta popolo, pri la viroj kaj virinoj, kaj pri ĉiuj el la popolo, kiuj respondis al li:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, 'Ĝuste tiun incensadon, kiun vi faradis en la urboj de Judujo kaj sur la stratoj de Jerusalem, vi kaj viaj patroj, viaj reĝoj kaj viaj eminentuloj kaj la popolo de la lando-ĝuste tion la Eternulo ja rememoris, kaj ĝi atingis Lian koron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'Kaj la Eternulo ne plu povis toleri viajn malbonajn agojn, la abomenindaĵojn, kiujn vi faris; tial via lando fariĝis dezerto, objekto de teruro kaj de malbeno, kaj neniu loĝas en ĝi, kiel oni nun vidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Pro tio, ke vi incensadis kaj pekadis antaŭ la Eternulo kaj ne obeis la voĉon de la Eternulo kaj ne agadis laŭ Lia instruo, laŭ Liaj leĝoj kaj ordonoj-pro tio trafis vin tiu malbono, kiel vi nun vidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Kaj Jeremia diris al la tuta popolo kaj al ĉiuj virinoj: Aŭskultu la vorton de la Eternulo, ĉiuj Judoj, kiuj estas en la lando Egipta!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'Tiele diras la Eternulo Cebaot, Dio de Izrael: Vi kaj viaj edzinoj parolis per via buŝo kaj plenumis per viaj manoj tion, kion vi diris: Ni plenumos nian solenan promeson, kiun ni faris, incensi al la reĝino de la ĉielo kaj verŝi al ŝi verŝoferojn; vi efektive plenumas viajn promesojn, kaj faras, kion vi promesis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Tial aŭskultu la vorton de la Eternulo, ĉiuj Judoj, kiuj loĝas en la lando Egipta: Jen Mi ĵuris per Mia granda nomo, diras la Eternulo, ke la buŝo de neniu Judo en la tuta lando Egipta plu vokos Mian nomon, dirante: Kiel vivas la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Jen Mi viglos super ili por malbono, ne por bono; kaj ĉiuj Judoj, kiuj estas en la lando Egipta, pereos de glavo kaj de malsato, ĝis ili tute ekstermiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'Nur malgranda nombro da homoj, kiuj saviĝos de glavo, revenos el la lando Egipta en la landon Judan; kaj la tuta restaĵo de la Judoj, kiuj venis en la landon Egiptan, por tie loĝi, ekscios, kies vorto plenumiĝas, Mia aŭ ilia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'Kaj jen estas por vi la pruvosigno, diras la Eternulo, ke Mi punos vin sur ĉi tiu loko, por ke vi sciu, ke plenumiĝos Miaj vortoj sur vi por malbono:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'tiele diras la Eternulo: Jen Mi transdonos Faraonon Ĥofran, reĝon de Egiptujo, en la manojn de liaj malamikoj, kaj en la manojn de tiuj, kiuj celas lian morton, kiel Mi transdonis Cidkijan, reĝon de Judujo, en la manon de Nebukadnecar, reĝo de Babel, lia malamiko kaj celanto de lia morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Jen estas la vorto, kiun la profeto Jeremia diris al Baruĥ, filo de Nerija, kiam ĉi tiu skribis tiujn vortojn en libron sub diktado de Jeremia, en la kvara jaro de Jehojakim, filo de Joŝija, reĝo de Judujo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'Tiele diras la Eternulo, Dio de Izrael, pri vi, ho Baruĥ:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Vi diris: Ve al mi! ĉar la Eternulo aldonis malĝojon al mia suferado; mi laciĝis de mia ĝemado, kaj mi ne trovas ripozon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Tiele diru al li: Tiele diras la Eternulo: Jen tion, kion Mi konstruis, Mi detruas, kaj kion Mi plantis, tion Mi elradikigas, ĉi tiun tutan Mian landon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'kaj vi postulas por vi grandaĵon! Ne postulu; ĉar jen Mi venigos malbonon sur ĉiun karnon, diras la Eternulo, sed al vi Mi donos vian animon kiel akiron sur ĉiuj lokoj, kien vi iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Jen estas la vorto de la Eternulo, kiu aperis al la profeto Jeremia pri la nacioj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'Pri Egiptujo, pri la militistaro de Faraono Neĥo, reĝo de Egiptujo, kiu estis ĉe la rivero Eŭfrato en Karkemiŝ, kaj kiun venkobatis Nebukadnecar, reĝo de Babel, en la kvara jaro de Jehojakim, filo de Joŝija, reĝo de Judujo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Pretigu ŝildon kaj kirason, kaj iru en batalon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Jungu la ĉevalojn kaj surĉevaligu la rajdistojn, stariĝu en kaskoj, akrigu la lancojn, surmetu sur vin armaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Kial Mi vidas, ke ili ektimis kaj kuras malantaŭen? iliaj herooj estas frapitaj, kaj forkuras rapide, ne deturnante sin; teruro estas ĉirkaŭe, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Ne forkuros la rapidpiedulo, ne forsaviĝos la heroo; norde, ĉe la rivero Eŭfrato, ili falpuŝiĝos kaj falos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Kiu estas tiu, kiu leviĝas kiel Nilo kaj kies akvo ondiĝas kiel torentoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Egiptujo leviĝas kiel Nilo, kaj kiel torentoj, en kiuj ondiĝas la akvo; kaj ĝi diras: Leviĝante, mi kovros la teron, mi pereigos urbon kun ĝiaj loĝantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Leviĝu sur la ĉevalojn, kaj kuru rapide sur la ĉaroj; eliru la herooj, la Etiopoj kaj la Putidoj, tenantaj ŝildon, kaj la Ludidoj, tenantaj kaj streĉantaj pafarkon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Kaj tiu tago estos ĉe la Sinjoro, la Eternulo Cebaot, tago de venĝo, por venĝi al Liaj malamikoj; kaj la glavo manĝegos kaj satiĝos kaj ebriiĝos de ilia sango; ĉar buĉofero estos al la Sinjoro, la Eternulo Cebaot, en la lando norda, ĉe la rivero Eŭfrato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Iru en Gileadon kaj prenu balzamon, ho virga filino de Egiptujo; vane vi multigas la kuracilojn; ne ekzistas por vi resaniĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'La nacioj aŭdis vian malhonoron, kaj via plorado plenigis la teron; ĉar fortulo falpuŝiĝis kontraŭ fortulo, kaj ambaŭ kune falis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Jen estas la vorto, kiun la Eternulo diris al la profeto Jeremia pri la veno de Nebukadnecar, reĝo de Babel, por frapi la landon Egiptan:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Sciigu en Egiptujo, proklamu en Migdol, proklamu en Nof kaj en Taĥpanĥes, diru: Stariĝu kaj pretiĝu, ĉar la glavo ekstermas vian ĉirkaŭaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Kial estas forpuŝita via fortulo, ne povis stari? ĉar la Eternulo lin renversis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Li multigis la falpuŝiĝantojn; falis unu sur la alian; kaj ili diras: Leviĝu, ni reiru al nia popolo kaj al la lando de nia naskiĝo, for de la glavo de la tirano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Oni kriis tie: Faraono, reĝo de Egiptujo, estas nur bruo; li preterlasis la difinitan tempon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'Kiel Mi vivas, diras la Reĝo, kies nomo estas Eternulo Cebaot, li venos kiel Tabor inter la montoj kaj kiel Karmel ĉe la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Pretigu al vi ĉion, kio estas necesa por elmigro, ho loĝantino, filino de Egiptujo; ĉar Nof estos ruinigita kaj dezertigita, ke neniu en ĝi loĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Tre bela bovidino estas Egiptujo; sed de nordo venas jam la buĉonto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Ankaŭ ĝiaj dungitoj interne de ĝi estas kiel bone nutritaj bovidoj; sed ili ankaŭ turnis sin malantaŭen, kune forkuris, ne povis kontraŭstari; ĉar la tago de ilia malfeliĉo venis sur ilin, la tempo de ilia puno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Ĝia voĉo sonos kiel voĉo de serpento; ĉar ili iros kun militistaro, kaj kun hakiloj ili venos al ĝi, kiel lignohakistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'Ili elhakos ĝian arbaron, diras la Eternulo, kvankam ĝi estas nekalkulebla; ĉar ili estas pli multenombraj ol akridoj, kaj oni ne povas ilin kalkuli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Hontigita estas la filino de Egiptujo, transdonita en la manojn de norda popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'La Eternulo Cebaot, Dio de Izrael, diras: Jen Mi punvizitos Amonon en No, kaj Faraonon, kaj Egiptujon kaj ĝiajn diojn kaj ĝiajn reĝojn, Faraonon mem, kaj tiujn, kiuj fidas lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'Kaj Mi transdonos ilin en la manojn de tiuj, kiuj celas ilian morton, kaj en la manojn de Nebukadnecar, reĝo de Babel, kaj en la manojn de liaj servantoj; sed poste ĝi estos loĝata, kiel en la tempo antaŭa, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Sed vi ne timu, ho Mia servanto Jakob, kaj ne tremu, ho Izrael; ĉar jen Mi savos vin el malproksime kaj vian idaron el la lando de ilia kaptiteco, kaj Jakob revenos kaj vivos trankvile kaj pace, kaj neniu lin timigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Vi ne timu, ho Mia servanto Jakob, diras la Eternulo, ĉar Mi estas kun vi; ĉar Mi ekstermos ĉiujn popolojn, inter kiujn Mi dispelis vin, sed vin Mi ne ekstermos; Mi nur punos vin modere, por ke Mi ne lasu vin tute sen puno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Jen estas la vorto de la Eternulo, kiu aperis al la profeto Jeremia pri la Filiŝtoj, antaŭ ol Faraono venkobatis Gazan:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'Tiele diras la Eternulo: Jen venos akvo de norde, kaj ĝi fariĝos inundanta torento, kaj ĝi inundos la landon, kaj ĉion, kio estas en ĝi, la urbon kaj ĝiajn loĝantojn; ekkrios la homoj, kaj ekploregos ĉiuj loĝantoj de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'Pro la sonado de la hufoj de la fortaj ĉevaloj, pro la bruo de la ĉaroj, pro la bruego de la radoj la patroj ne atentos siajn infanojn, senforte malleviĝos iliaj manoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'pro la tago, kiu venos, kiam oni prirabos ĉiujn Filiŝtojn, ekstermos ĉe Tiro kaj Cidon ĉiujn restintajn helpantojn; ĉar la Eternulo ruinigos la Filiŝtojn, la restaĵon de la insulo Kaftor.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Kalveco trafos Gazan, pereos Aŝkelon kaj la restaĵo de ilia valo. Kiel longe ankoraŭ vi faros al vi tranĉojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Ho glavo de la Eternulo, kiel longe vi ne kvietiĝos? eniru en vian ingon, haltu kaj silentu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Sed kiel vi povas kvietiĝi? la Eternulo donis al ĝi ordonon kontraŭ Aŝkelon kaj kontraŭ la bordo de la maro; tien Li destinis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Pri Moab: Tiele diras la Eternulo Cebaot, Dio de Izrael: Ve al Nebo! ĉar ĝi estas ruinigita; hontigita kaj venkoprenita estas Kirjataim; hontigita kaj tremigita estas la fortikaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Jam ne ekzistas la gloro de Moab; en Ĥeŝbon oni intencas kontraŭ ĝi malbonon, dirante: Ni iru, kaj ni ekstermu ĝin, ke ĝi ne plu estu popolo. Ankaŭ vi, ho Madmen, eksilentu; vin persekutos glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Kriadon oni aŭdas de Ĥoronaim, tie estas ruinigado kaj granda malfeliĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Disbatita estas Moab; ĝiaj infanoj laŭte krias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Kiuj supreniras al Luĥit, tiuj iras kun plorado; ĉe la malsuprenirado de Ĥoronaim la malamikoj aŭdas kriadon de malfeliĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Forkuru, savu vian vivon, kaj estu kiel seknudiĝinta arbo en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Ĉar vi fidis viajn faritaĵojn kaj viajn trezorojn, vi ankaŭ estos venkoprenita; kaj Kemoŝ iros en kaptitecon kune kun siaj pastroj kaj eminentuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Venos ruiniganto en ĉiun urbon, neniu urbo saviĝos; pereos la valo kaj dezertiĝos la ebenaĵo, kiel diris la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Donu flugilojn al Moab, ĉar li devas forflugi; liaj urboj dezertiĝos tiel, ke neniu en ili loĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Malbenita estu tiu, kiu plenumas malĝuste la faron de la Eternulo, kaj malbenita estu tiu, kiu detenas sian glavon de sango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'De sia juneco Moab havis trankvilecon kaj ripozadis sur sia feĉo, li ne estis transverŝata el unu vazo en alian, kaj en kaptitecon li ne iris; tial lia gusto restis en li kaj lia odoro ne ŝanĝiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Tial jen venos tempo, diras la Eternulo, kiam Mi sendos al li verŝistojn, kaj ili verŝos lin, malplenigos liajn vazojn, kaj disrompos liajn kruĉojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'Kaj Moab estos hontigita pro Kemoŝ, kiel la domo de Izrael estis hontigita pro Bet-El, kiun ili fidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Kiel vi povas diri: Ni estas herooj kaj kapabluloj por la milito?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Ruinigita estas Moab, liaj urboj falis, kaj liaj plej bravaj junuloj iris al buĉo, diras al Reĝo, kies nomo estas Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Baldaŭ venos pereo al Moab, kaj lia malfeliĉo tre rapidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Bedaŭru lin ĉiuj liaj ĉirkaŭantoj, kaj ĉiuj, kiuj konas lian nomon, diru: Kiele disrompiĝis la forta vergo, la belega bastono!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Iru malsupren de via majesto, sidu en senakva loko, ho loĝantino, filino de Dibon; ĉar la ruiniganto de Moab elpaŝis kontraŭ vin kaj detruis viajn fortikaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Staru ĉe la vojo kaj rigardu, ho loĝantino de Aroer; demandu la forkuranton kaj la forsaviĝanton, kaj diru: Kio fariĝis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Hontigita estas Moab, ĉar li estas frapita; ploru kaj kriu, sciigu en Arnon, ke Moab estas ruinigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Juĝo venis kontraŭ la lando de la ebenaĵo, kontraŭ Ĥolon, Jahac, kaj Mefaat,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'kontraŭ Dibon, Nebo, kaj Bet-Diblataim,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'kontraŭ Kirjataim, Bet-Gamul, kaj Bet-Meon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'kontraŭ Keriot kaj Bocra, kaj kontraŭ ĉiuj urboj de la lando de Moab, la malproksimaj kaj la proksimaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'Dehakita estas la korno de Moab, kaj lia brako estas rompita, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Ebriigu lin, ĉar li leviĝis kontraŭ la Eternulo; Moab plaŭdos en sia vomaĵo, kaj li mem estos objekto de mokado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Ĉu vi ne mokis Izraelon? ĉu oni trovis lin inter ŝtelistoj, ke ĉiufoje, kiam vi parolas pri li, vi balancas la kapon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Forlasu la urbojn kaj ekloĝu sur roko, ho loĝantoj de Moab, kaj fariĝu kiel kolomboj, kiuj nestas en truoj de kavernoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Ni aŭdis pri la fiereco de Moab, granda fiereco, pri lia malmodesteco, fiereco, aroganteco, kaj pri la malhumileco de lia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Mi konas, diras la Eternulo, lian koleremecon, la nesincerecon de liaj vortoj kaj la nesincerecon de liaj agoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Tial Mi devas plori pri Moab, ĝemi pri ĉiuj Moabidoj, priplori la loĝantojn de Kir-Ĥeres.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Per pli ol la plorado de Jazer Mi ploros pri vi, ho vinberĝardeno de Sibma; viaj branĉoj etendiĝis trans la maron, atingis la maron de Jazer; rabisto atakis viajn somerajn fruktojn kaj vian rikolton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'Foriĝis ĝojo kaj gajeco de la fruktodona kampo kaj de la lando de Moab; Mi malaperigis vinon en la vinpremejoj, oni ne premos tie kun ĝojo vinon, triumfaj kantoj ne plu sonos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'Pro la kriado, kiu aŭdiĝas de Ĥeŝbon ĝis Eleale kaj ĝis Jahac, ili laŭte ekploris de Coar ĝis Ĥoronaim kaj ĝis la tria Eglat; ĉar ankaŭ la akvo de Nimrim sekmalaperis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'Mi ekstermos ĉe Moab, diras la Eternulo, ĉiun, kiu supreniras sur altaĵon kaj incensas al siaj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Tial Mia koro ĝemas pri Moab kiel fluto, kaj pri la loĝantoj de Kir- Ĥeres Mia koro ĝemas kiel fluto; ĉar la abundaĵo, kiun ili akiris, pereis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Ĉar ĉiu kapo kalviĝis, kaj ĉiu barbo estas fortondita, sur ĉiuj manoj estas tranĉoj, kaj sur la lumboj estas sakaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Sur ĉiuj tegmentoj de Moab kaj sur liaj stratoj ĉie estas plorado; ĉar Mi disrompis Moabon kiel senvaloran vazon, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Kiele disbatita li estas, kiele ili ploregas! kiele Moab turnis sian nukon, estas hontigita, kaj Moab fariĝis objekto de mokado kaj de teruro por ĉiuj siaj ĉirkaŭantoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Ĉar tiele diras la Eternulo: Jen li alflugos kiel aglo kaj etendos siajn flugilojn super Moab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Prenita estas Keriot, kaj la fortikigitaj urboj estas kaptitaj; kaj la koro de la herooj de Moab en tiu tago estos kiel la koro de virino dum la doloroj de naskado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'Kaj Moab estos ekstermita, ke li ne plu estos popolo, ĉar li leviĝis kontraŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Teruro, kavo, kaj kaptilo trafos vin, ho loĝanto de Moab, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Kiu forkuros de la teruro, tiu falos en la kavon; kaj kiu eliros el la kavo, tiu trafos en kaptilon; ĉar Mi venigos sur lin, sur Moabon, la jaron de lia puno, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'Sub la ombro de Ĥeŝbon stariĝos tiuj, kiuj forkuros de la forto; sed fajro eliros el Ĥeŝbon kaj flamo el la mezo de Siĥon, kaj ĝi manĝegos la flankon de Moab kaj la verton de la filoj malkvietaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Ve al vi, ho Moab! pereis la popolo de Kemoŝ; ĉar viaj filoj estas prenitaj en kaptitecon kaj viaj filinoj estas forkondukitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Sed en la tempo estonta Mi revenigos la kaptitojn de Moab, diras la Eternulo. Ĝis ĉi tie estas la verdikto pri Moab.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Pri la Amonidoj: Tiele diras la Eternulo: Ĉu Izrael ne havas filojn? ĉu li ne havas heredanton? kial do Malkam heredis Gadon kaj lia popolo loĝas en la urboj de ĉi tiu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Tial jen venos tempo, diras la Eternulo, kaj Mi eksonigos militan trumpetadon super Raba de la Amonidoj; kaj ĝi fariĝos amaso da ruinoj, kaj ĝiaj filinoj forbrulos en fajro, kaj Izrael ekposedos siajn posedintojn, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Ploregu, ho Ĥeŝbon, ĉar Aj estas ruinigita. Kriu, ho filinoj de Raba, zonu vin per sakaĵo, ploru kaj vagadu inter la bariloj; ĉar Malkam iras en kaptitecon kune kun siaj pastroj kaj eminentuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Kial vi fanfaronas pri viaj valoj? sangon fluigas via valo, ho filino malobeema, kiu fidas siajn trezorojn, kaj diras: Kiu povas veni al mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Jen Mi venigos sur vin timon, diras la Sinjoro, la Eternulo Cebaot, de ĉiuj viaj ĉirkaŭaĵoj; kaj vi estos dispelitaj ĉiu aparte, kaj neniu kolektos la vagantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Tamen poste Mi revenigos la forkaptitajn Amonidojn, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Pri Edom: Tiele diras la Eternulo Cebaot: Ĉu jam ne ekzistas saĝo en Teman? ĉu la filoj jam ne havas konsilon? ĉu ilia saĝeco malaperis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Forkuras, turnis sian dorson, kaj profunde sin kaŝas la loĝantoj de Dedan; ĉar malfeliĉon de Esav Mi venigis sur lin, la tempon de lia puno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Kiam venos al vi vinberkolektantoj, ili ne restigos forgesitajn berojn; se venos ŝtelistoj en la nokto, ili rabos plenan kvanton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Ĉar Mi nudigis Esavon, Mi malkaŝis liajn sekretajn rifuĝejojn, por ke li ne povu sin kaŝi; ekstermitaj estas lia idaro, liaj fratoj, kaj liaj najbaroj, kaj li jam ne ekzistas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Restigu viajn orfojn, Mi konservos ilian vivon; kaj viaj vidvinoj fidu Min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Ĉar tiele diras la Eternulo: Jen tiuj, kiuj ne meritis trinki la pokalon, tamen ĝin trinkos; ĉu vi do povas resti nepunita? vi ne restos nepunita, sed vi nepre trinkos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Ĉar Mi ĵuris per Mi, diras la Eternulo, ke Bocra fariĝos objekto de teruro, honto, ruinigo, kaj malbeno; kaj ĉiuj ĝiaj urboj fariĝos ruinoj por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Diron mi aŭdis de la Eternulo, kaj kuriero estas sendita al la nacioj: Kolektiĝu kaj iru kontraŭ ĝin, kaj leviĝu por batalo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'Ĉar jen Mi faris vin malgranda inter la nacioj, malestimata inter la homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Via malhumileco kaj la fiereco de via koro trompis vin, kiu loĝas en la fendegoj de la rokoj kaj okupas suprojn de montoj; sed se vi eĉ aranĝus vian neston tiel alte, kiel aglo, eĉ de tie Mi ĵetos vin malsupren, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'Edom fariĝos objekto de teruro; ĉiu, kiu pasos preter li, miros kaj fajfos pri ĉiuj liaj vundoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Kiel renversitaj estas Sodom kaj Gomora kaj iliaj najbarlokoj, diras la Eternulo, tiel ankaŭ tie neniu restos, neniu homido tie loĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Jen kiel leono li supreniras de la majesta Jordan kontraŭ la fortikan loĝejon; ĉar Mi rapide forpelos ilin de tie, kaj Mi estrigos tie tiun, kiu estas elektita. Ĉar kiu estas simila al Mi? kiu donos al Mi decidojn? kiu estas la paŝtisto, kiu povas kontraŭstari al Mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Tial aŭskultu la decidon de la Eternulo, kiun Li decidis pri Edom, kaj Liajn intencojn, kiujn Li havas pri la loĝantoj de Teman: la knaboj- paŝtistoj ilin fortrenos kaj detruos super ili ilian loĝejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'De la bruo de ilia falo ektremos la tero, ilian kriadon oni aŭdos ĉe la Ruĝa Maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Jen li leviĝos kiel aglo, ekflugos kaj etendos siajn flugilojn super Bocra; kaj la koro de la herooj de Edom en tiu tago estos kiel la koro de virino ĉe la naskodoloroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Pri Damasko: Hontigitaj estas Ĥamat kaj Arpad, ĉar, aŭdinte malbonan sciigon, ili senkuraĝiĝis; ĉe la maro ili tiel ektremis, ke ili ne povas trankviliĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Damasko senkuraĝiĝis, turnis sin, por forkuri; tremo atakis ĝin, doloro kaj turmentoj ĝin kaptis, kiel naskantinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Kial ne estas riparita la glora urbo, la gaja urbo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Tial ĝiaj junuloj falos sur ĝiaj stratoj, kaj ĉiuj militistoj pereos en tiu tago, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'Kaj Mi ekbruligos fajron sur la murego de Damasko, kaj ĝi ekstermos la palacojn de Ben-Hadad.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Pri Kedar, kaj pri la regnoj de Ĥacor, kiujn venkobatis Nebukadnecar, reĝo de Babel: Tiele diras la Eternulo: Leviĝu, iru kontraŭ Kedaron, kaj ruinigu la filojn de la oriento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Iliaj tendoj kaj ŝafaroj estos prenitaj; iliajn tapiŝojn kaj ĉiujn iliajn vazojn kaj iliajn kamelojn oni forprenos, kaj oni kriados al ili: Teruro ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Forkuru, foriĝu rapide, kaŝu vin profunde, ho loĝantoj de Ĥacor, diras la Eternulo; ĉar Nebukadnecar, reĝo de Babel, faras pri vi decidon kaj havas intencon kontraŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Leviĝu, iru kontraŭ popolon trankvilan, kiu sidas en sendanĝereco, diras la Eternulo; ĝi ne havas pordojn nek riglilojn, ili vivas izolite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Kaj iliaj kameloj estos forrabitaj, kaj la multo de iliaj brutoj fariĝos rabakiro; kaj Mi dispelos ilin al ĉiuj ventoj, ilin, kiuj tondas la harojn sur la tempioj, kaj de ĉiuj flankoj Mi venigos ilian malfeliĉon, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'Kaj Ĥacor fariĝos loĝejo de ŝakaloj, eterna dezerto; neniu tie restos, kaj neniu homido tie loĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Jen estas la vorto de la Eternulo, kiu aperis al la profeto Jeremia pri Elam, en la komenco de la reĝado de Cidkija, reĝo de Judujo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'Tiele diras la Eternulo Cebaot: Jen Mi rompos la pafarkon de Elam, ilian ĉefan forton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'Kaj Mi venigos sur Elamon kvar ventojn de la kvar finoj de la ĉielo, kaj Mi dispelos ilin al ĉiuj tiuj ventoj; kaj ne ekzistos popolo, al kiu ne venus la dispelitoj el Elam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'Kaj Mi senkuraĝigos Elamon antaŭ iliaj malamikoj, kaj antaŭ tiuj, kiuj celas ilian morton; kaj Mi venigos sur ilin malbonon, la flamon de Mia kolero, diras la Eternulo, kaj Mi persekutos ilin per la glavo, ĝis Mi ekstermos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'Kaj Mi starigos Mian tronon en Elam, kaj Mi pereigos tie la reĝon kaj la eminentulojn, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'Tamen en la tempo estonta Mi revenigos la forkaptitojn de Elam, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Jen estas la vorto, kiun la Eternulo diris per la profeto Jeremia pri Babel kaj pri la lando de la Ĥaldeoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Sciigu al la nacioj kaj proklamu, levu standardon, proklamu, ne kaŝu, diru: Prenita estas Babel, hontigita estas Bel, frakasita estas Merodaĥ, hontigitaj estas ĝiaj idoloj, frakasitaj estas ĝiaj statuoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Ĉar eliris kontraŭ ĝin popolo el la nordo, kiu faros ĝian landon dezerto, kaj ne plu estos loĝanto en ĝi: de homo ĝis bruto ĉio foriĝos kaj foriros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'En tiuj tagoj kaj en tiu tempo, diras la Eternulo, venos la idoj de Izrael kune kun la idoj de Jehuda; ili iros kaj ploros, kaj serĉos la Eternulon, sian Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Pri la vojo al Cion ili demandos, tien estos turnita ilia vizaĝo: Venu, ni aliĝos al la Eternulo per interligo eterna, neforgesebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Mia popolo estis kiel erarvagantaj ŝafoj: ili paŝtistoj delogis ilin, erarvagigis ilin sur la montoj; de monto sur monteton ili vagis, ili forgesis sian ŝafejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Ĉiuj, kiuj renkontis ilin, manĝis ilin; kaj iliaj malamikoj diris: Ni ne estas kulpaj, ĉar ili pekis antaŭ la Eternulo, la loĝejo de la vero, antaŭ la espero de iliaj patroj, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Kuru el Babel kaj eliru el la lando de la Ĥaldeoj, kaj estu kiel virkaproj antaŭ la ŝafoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Ĉar jen Mi vekos kaj venigos sur Babelon amason da grandaj popoloj el lando norda, kaj ili aranĝos sin kontraŭ ĝi, kaj ĝi estos venkoprenita; iliaj sagoj, kiel lerta heroo, ne revenas vane.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'Kaj Ĥaldeujo fariĝos militakiro; ĉiuj ĝiaj prirabantoj satiĝos, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Ĉar vi ĝojis, ĉar vi triumfis, ho rabintoj de Mia heredaĵo, ĉar vi saltis, kiel bovidino sur herbo, kaj blekis, kiel fortaj ĉevaloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'tre hontigita estas via patrino, mokata estas via naskintino; jen estas la estonteco de la nacioj: dezerto, neloĝata tero, kaj stepo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'De la kolero de la Eternulo ĝi fariĝos neloĝata, kaj ĝi tuta fariĝos dezerta; ĉiu, kiu iros preter Babel, miros kaj fajfos pri ĉiuj ĝiaj vundoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Pretigu vin kontraŭ Babel ĉirkaŭe, ĉiuj streĉantoj de pafarkoj, pafu sur ĝin, ne domaĝu sagojn; ĉar ĝi pekis antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Triumfe kriu kontraŭ ĝi ĉirkaŭe; malleviĝis ĝia mano, falis ĝia fundamento, detruiĝis ĝiaj muregoj; ĉar tio estas venĝo de la Eternulo; venĝu al ĝi; kiel ĝi agis, tiel agu kontraŭ ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Ekstermu el Babel semanton kaj rikoltanton en la tempo de rikoltado; de la glavo de la tirano ĉiu sin turnu al sia popolo, kaj ĉiu forkuru en sian landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Izrael estas kiel disĵetita ŝafaro; leonoj lin dispelis: la unua manĝis lin la reĝo de Asirio, kaj ĉi tiu lasta, Nebukadnecar, reĝo de Babel, rompis al li la ostojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Tial tiele diras la Eternulo Cebaot, Dio de Izrael: Jen Mi punos la reĝon de Babel kaj lian landon, kiel Mi punis la reĝon de Asirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'Kaj Mi revenigos Izraelon en lian loĝejon, kaj li paŝtiĝos sur Karmel kaj Baŝan, kaj sur la monto de Efraim kaj en Gilead lia animo satiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'En tiuj tagoj kaj en tiu tempo, diras la Eternulo, oni serĉos malbonagon de Izrael, sed ĝi ne estos, kaj pekon de Jehuda, sed ĝi ne troviĝos; ĉar Mi pardonos al tiuj, kiujn Mi restigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Iru kontraŭ la landon de la maldolĉigantoj, kontraŭ ĝin kaj kontraŭ la loĝantojn de la punejo; ruinigu kaj ekstermu ĉion post ili, diras la Eternulo, kaj faru ĉion tiel, kiel Mi ordonis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Bruo de batalo estas en la lando, kaj granda frakasado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Kiele rompita kaj frakasita estas la martelo de la tuta tero! kiele dezertiĝis Babel inter la nacioj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Mi starigis reton por vi, kaj vi estas kaptita, ho Babel, antaŭ ol vi tion rimarkis; vi estas trovita kaj kaptita, ĉar vi leviĝis kontraŭ la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'La Eternulo malfermis Sian trezorejon, kaj elprenis el tie la ilojn de Sia kolero; ĉar ion por fari havas la Sinjoro, la Eternulo Cebaot, en la lando de la Ĥaldeoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Iru kontraŭ ĝin de plej malproksime, malfermu ĝiajn grenejojn, piedpremu ĝin kiel amasaĵon, ekstermu ĝin, ke nenio de ĝi restu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Dishaku per glavo ĉiujn ĝiajn bovojn; ili estu buĉataj. Ve al ili! ĉar venis ilia tago, la tempo de ilia puno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Aŭdiĝas voĉo de forkurantoj kaj forsaviĝantoj el la lando Babela, por sciigi en Cion pri la venĝo de la Eternulo, nia Dio, pri la venĝo pro Lia templo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Alvoku multajn kontraŭ Babelon, ĉiujn, kiuj streĉas pafarkon; stariĝu tendare ĉirkaŭ ĝi, ke neniu povu forsaviĝi el ĝi; repagu al ĝi laŭ ĝiaj agoj: ĉion, kion ĝi faris, faru al ĝi; ĉar ĝi estis malhumila kontraŭ la Eternulo, kontraŭ la Sanktulo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Pro tio ĝiaj junuloj falos sur ĝiaj stratoj, kaj ĉiuj ĝiaj militistoj pereos en tiu tago, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Jen Mi estas kontraŭ vi, ho malhumilulo, diras la Sinjoro, la Eternulo Cebaot; ĉar venis via tago, la tempo de via puno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Kaj la malhumilulo falpuŝiĝos kaj falos, kaj neniu lin levos; kaj Mi ekbruligos fajron en liaj urboj, kaj ĝi ekstermos ĉiujn liajn ĉirkaŭaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'Tiele diras la Eternulo Cebaot: Turmentataj estas la idoj de Izrael kune kun la idoj de Jehuda; kaj ĉiuj iliaj kaptintoj forte ilin tenas, ne volas forliberigi ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Sed ilia Liberiganto estas forta, Eternulo Cebaot estas Lia nomo; Li defendos ilian aferon tiel, ke la tero skuiĝos kaj la loĝantoj de Babel ektremos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Glavo falu sur la Ĥaldeojn, diras la Eternulo, sur la loĝantojn de Babel, sur ĝiajn eminentulojn kaj saĝulojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'glavo sur la antaŭdiristojn, ke ili malsaĝiĝu; glavo sur ĝiajn heroojn, ke ili senkuraĝiĝu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'glavo sur ĝiajn ĉevalojn kaj sur ĝiajn ĉarojn, kaj sur ĉiujn diversgentajn loĝantojn, kiuj estas en ĝi, ke ili fariĝu kiel virinoj; glavo sur ĝiajn trezorojn, ke ili estu disrabitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Sekeco trafu ĝiajn akvojn, ke ili malaperu; ĉar tio estas lando de idoloj, kaj pri siaj monstroj ili fanfaronas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Tial tie ekloĝos stepaj bestoj kaj ŝakaloj, kaj strutoj en ĝi loĝos; ĝi neniam plu estos loĝata, kaj neniu tie havos domon en ĉiuj venontaj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Kiel Dio renversis Sodomon kaj Gomoran kaj iliajn najbarlokojn, diras la Eternulo, tiel ankaŭ tie restos neniu kaj loĝos neniu homido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Jen venas popolo el nordo, granda nacio kaj multe da reĝoj leviĝas de la randoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Pafarkon kaj lancon ili tenas forte; kruelaj ili estas kaj senkompataj; ilia voĉo bruas kiel maro; sur ĉevaloj ili rajdas, armite por la batalo kiel unu homo, kontraŭ vin, ho filino de Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Aŭdis la reĝo de Babel la sciigon pri ili, kaj senfortiĝis liaj manoj; suferego atakis lin, doloro kiel ĉe naskantino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Jen kiel leono li supreniras de la majesta Jordan kontraŭ la fortikan loĝejon; ĉar Mi rapide forpelos ilin de tie, kaj Mi estrigos tie tiun, kiu estas elektita. Ĉar kiu estas simila al Mi? kiu donos al Mi decidojn? kaj kiu estas la paŝtisto, kiu povas kontraŭstari al Mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Tial aŭskultu la decidon de la Eternulo, kiun Li decidis pri Babel, kaj Liajn intencojn, kiujn Li havas pri la lando de la Ĥaldeoj: la knaboj- paŝtistoj ilin fortrenos, kaj detruos super ili ilian loĝejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'De la famo pri la preno de Babel ektremos la tero, kaj krio estos aŭdata ĉe la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Tiele diras la Eternulo: Jen Mi vekos pereigan venton kontraŭ Babelon, kaj kontraŭ ĝiajn loĝantojn, kiuj leviĝis kontraŭ Min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'Kaj Mi sendos ventumistojn kontraŭ Babelon, kaj ili ĝin disventumos, kaj dezertigos ĝian landon; ĉar en la tago de la malfeliĉo ili estos ĉirkaŭ ĝi ĉiuflanke.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'La pafarkisto streĉu sian pafarkon, kaj sin levu en sia kiraso; ne kompatu ĝiajn junulojn, ekstermu ĝian tutan militistaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'Kaj falu mortigitoj en la lando de la Ĥaldeoj, kaj trapikitoj sur iliaj stratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Ĉar Izrael kaj Jehuda ne estas vidvigitaj de sia Dio, de la Eternulo Cebaot; ĉar ilia lando estas plena de kulpoj kontraŭ la Sanktulo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Forkuru el interne de Babel, kaj savu ĉiu sian animon, ke vi ne pereu pro ĝiaj malbonagoj; ĉar tio estas tempo de venĝo por la Eternulo, Li donas al ĝi repagon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'En la mano de la Eternulo Babel estis ora kaliko, ebriiganta la tutan teron: el ĝi trinkis vinon la nacioj, kaj tial ili freneziĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Subite falis Babel kaj frakasiĝis; ploru pri ĝi, prenu balzamon por ĝia vundo; eble ĝi saniĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, 'Ni kuracis Babelon, sed ĝi ne saniĝis; lasu ĝin, kaj ni iru ĉiu en sian landon; ĉar la juĝo kontraŭ ĝi atingis la ĉielon kaj leviĝis ĝis la nuboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'La Eternulo elaperigis nian pravecon; venu, kaj ni rakontu en Cion la faron de la Eternulo, nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Akrigu la sagojn, pretigu la ŝildojn! la Eternulo vekis la spiriton de la reĝoj de Medujo, ĉar Lia intenco estas kontraŭ Babel, por pereigi ĝin; ĉar tio estas venĝo de la Eternulo, venĝo pro Lia templo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Kontraŭ la muregojn de Babel levu standardon, plifortigu la gardistaron, starigu observistojn, pretigu embuskon; ĉar kiel la Eternulo intencis, tiel Li faris tion, kion Li diris pri la loĝantoj de Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Ho vi, kiu loĝas ĉe granda akvo kaj havas grandajn trezorojn! venis via fino, finiĝis via avideco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'La Eternulo Cebaot ĵuris per Sia animo: Mi plenigos vin de homoj kiel de skaraboj, kaj ili eksonigos kontraŭ vi triumfan kanton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Li kreis la teron per Sia forto, aranĝis la mondon per Sia saĝo, kaj per Sia prudento etendis la ĉielon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Kiam Li eksonigas Sian voĉon, kolektiĝas multego da akvo en la ĉielo; Li levas la nubojn de la randoj de la tero, Li aperigas fulmojn inter la pluvo, kaj elirigas la venton el Siaj trezorejoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Malsaĝiĝis ĉiu homo kun sia sciado, per honto kovriĝis ĉiu fandisto kun sia statuo; ĉar lia fanditaĵo estas malveraĵo, ĝi ne havas en si spiriton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Tio estas vantaĵo, faro de eraro; kiam ili estos vizititaj, ili pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Ne simila al ili estas Tiu, kiun havas Jakob; ĉar Li estas la kreinto de ĉio, kaj Izrael estas la gento de Lia heredo; Eternulo Cebaot estas Lia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Vi estis por Mi martelo, ilo de batalo, kaj per vi Mi frakasis naciojn, kaj per vi Mi ekstermis regnojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'Mi frakasis per vi ĉevalon kaj ĝian rajdanton, Mi frakasis per vi ĉaron kaj ĝian veturanton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'Mi frakasis per vi viron kaj virinon, Mi frakasis per vi maljunulon kaj junulon, Mi frakasis per vi junulon kaj junulinon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'Mi frakasis per vi paŝtiston kaj lian ŝafaron, Mi frakasis per vi terlaboriston kaj lian jungaĵon, Mi frakasis per vi komandantojn kaj estrojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'Kaj Mi repagos al Babel kaj al ĉiuj loĝantoj de Ĥaldeujo pro ilia tuta malbono, kiun ili faris en Cion antaŭ viaj okuloj, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Jen Mi iras kontraŭ vin, ho pereiga monto, pereiganto de la tuta tero, diras la Eternulo; Mi etendos Mian manon kontraŭ vin, Mi rulĵetos vin de la rokoj kaj faros vin monto de brulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'Oni ne prenos el vi angulŝtonon, nek ŝtonon por fundamento, sed vi estos eterna ruino, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Levu standardon en la lando, blovu per trumpeto inter la nacioj, armu kontraŭ ĝin popolojn, kunvoku kontraŭ ĝin la regnojn de Ararat, Mini, kaj Aŝkenaz; starigu kontraŭ ĝin militestron, alkonduku ĉevalojn kiel pikantajn skarabojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Armu kontraŭ ĝin popolojn, la reĝojn de Medujo, ĝiajn komandantojn kaj ĉiujn ĝiajn estrojn, kaj la tutan landaron, super kiu ĝi regas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'Kaj la tero skuiĝas kaj tremas, ĉar plenumiĝas super Babel la intencoj de la Eternulo, por fari la landon de Babel dezerto, en kiu neniu loĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'La herooj de Babel ĉesis batali, ili restis en la fortikaĵoj; malaperis ilia forto, ili fariĝis kiel virinoj; ĝiaj loĝejoj ekbrulis, ĝiaj rigliloj estas rompitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Kuranto kuras renkonte al kuranto, sciiganto renkonte al sciiganto, por raporti al la reĝo de Babel, ke lia urbo estas venkoprenita ĉe ĉiuj flankoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'ke la transirejoj estas okupitaj, la fortikaĵoj brulas per fajro, kaj la militistojn atakis teruro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Ĉar tiele diras la Eternulo Cebaot, Dio de Izrael: La filino de Babel estas kiel draŝejo dum la draŝado; tre baldaŭ venos la tempo de ĝia rikolto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Manĝis min, frakasis min Nebukadnecar, reĝo de Babel, li faris min malplena vazo, glutis min kiel drako, plenigis sian ventron per miaj dolĉaĵoj, kaj forpelis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'La maljusteco kontraŭ mi kaj mia karno estu nun sur Babel, diras la loĝantino de Cion; kaj mia sango sur la loĝantoj de Ĥaldeujo, diras Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Tial tiele diras la Eternulo: Jen Mi juĝos vian aferon kaj Mi faros venĝon pro vi, Mi sekigos ĝian maron kaj Mi senakvigos ĝian fonton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'Kaj Babel fariĝos amaso da ŝtonoj, loĝejo de ŝakaloj, objekto de teruro kaj mokado, kaj neniu en ĝi loĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Ili ĉiuj blekegos kiel junaj leonoj, krios kiel leonidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Dum ilia varmegiĝo Mi faros al ili festenon, kaj Mi ebriigos ilin, por ke ili fariĝu gajaj kaj ekdormu per eterna dormo kaj ne vekiĝu, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Mi kondukos ilin malsupren, kiel ŝafidojn al la buĉo, kiel ŝafojn kun kaproj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Kiele prenita estas Ŝeŝaĥ! kaj kaptita la gloro de la tuta mondo! kiele Babel fariĝis objekto de teruro inter la popoloj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Leviĝis kontraŭ Babelon la maro kaj kovris ĝin per la multego de siaj ondoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Ĝiaj urboj fariĝis dezerto, tero seka kaj senviva, tero, sur kiu neniu loĝas kaj tra kiu neniu homido trairas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Kaj Mi punos Belon en Babel, Mi eltiros el lia buŝo tion, kion li englutis, kaj ne plu kolektiĝos al li popoloj; ankaŭ la muregoj de Babel falos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Eliru el ĝia interno, Mia popolo, kaj ĉiu savu sian animon antaŭ la flama kolero de la Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'por ke via koro ne senkuraĝiĝu kaj vi ne ektimu, kiam oni aŭdos la famon en la lando; ĉar venos famo en unu jaro, kaj post ĝi venos famo en la sekvanta jaro, kaj sur la tero estos perforteco, unu reganto kontraŭ alia reganto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Tial jen venos tempo, kaj Mi vizitos la idolojn en Babel, kaj ĝia tuta lando estos hontigita, kaj ĉiuj ĝiaj mortigitoj falos meze de ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Kaj ĝojkantos pri Babel la ĉielo kaj la tero, kaj ĉio, kio estas sur ili; ĉar el la nordo venos al ĝi ruinigantoj, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Kiel Babel faligis la mortigitojn de Izrael, tiel ankaŭ en Babel falos mortigitoj el la tuta lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Vi, kiuj forsaviĝis de glavo, iru, ne haltu; en malproksimeco rememoru la Eternulon, kaj Jerusalem sin levu en via koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Ni hontis, kiam ni aŭdis la insulton; honto kovris nian vizaĝon, kiam fremduloj eniris en la sanktejon de la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Tial jen venos tempo, diras la Eternulo, kiam Mi vizitos ĝiajn idolojn, kaj en la tuta lando ĝemos morte-vunditoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Eĉ se Babel leviĝus al la ĉielo kaj se ĝi fortikigus alte sian forton, tamen al ĝi venus de Mi ruinigantoj, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Kriado estas aŭdata el Babel, kaj granda lamentado el la lando de la Ĥaldeoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'ĉar la Eternulo ruinigas Babelon kaj pereigas ĝin kun ĝia granda bruo; iliaj ondoj bruas kiel granda akvo, aŭdiĝas ilia malkvieta voĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Ĉar venos sur ĝin, sur Babelon, ruiniganto, kaj kaptitaj estos ĝiaj herooj, rompitaj estos iliaj pafarkoj; ĉar la Eternulo, Dio de repagado, nepre repagos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'Mi ebriigos ĝiajn eminentulojn, saĝulojn, komandantojn, estrojn, kaj heroojn, kaj ili ekdormos per eterna dormo kaj ne vekiĝos, diras la Reĝo, kies nomo estas Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'Tiele diras la Eternulo Cebaot: La larĝaj muregoj de Babel estos subfositaj, kaj ĝiaj altaj pordegoj estos forbruligitaj per fajro; kaj vana fariĝos la penado de la popoloj, kaj gentoj estos lacigintaj sin por fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Jen estas la vorto, kiun ordonis la profeto Jeremia al Seraja, filo de Nerija, filo de Maĥseja, kiam tiu iris kun Cidkija, reĝo de Judujo, en Babelon, en la kvara jaro de lia reĝado; Seraja estis la ripozejestro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Kaj Jeremia enskribis en unu libron la tutan malbonon, kiu venos sur Babelon, ĉiujn tiujn vortojn, skribitajn pri Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'Kaj Jeremia diris al Seraja: Kiam vi venos en Babelon, tiam rigardu kaj tralegu ĉiujn tiujn vortojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'kaj diru: Ho Eternulo! Vi diris pri ĉi tiu loko, ke Vi ekstermos ĝin tiel, ke estos en ĝi neniu loĝanto, nek homo, nek bruto, sed ĝi estos eterna dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'Kaj kiam vi finos la legadon de ĉi tiu libro, alligu al ĝi ŝtonon, kaj ĵetu ĝin en la mezon de Eŭfrato;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'kaj diru: Tiele dronos Babel, kaj ĝi ne releviĝos de la malfeliĉo, kiun Mi venigos sur ĝin, kaj ili pereos. Ĝis ĉi tie estas la vortoj de Jeremia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'La aĝon de dudek unu jaroj havis Cidkija, kiam li fariĝis reĝo, kaj dek unu jarojn li reĝis en Jerusalem. La nomo de lia patrino estis Ĥamutal, filino de Jeremia, el Libna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Li agadis malbone antaŭ la Eternulo, kiel ĉio, kion faris Jehojakim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Ĉar la kolero de la Eternulo estis kontraŭ Jerusalem kaj kontraŭ Judujo, ĝis Li forĵetis ilin de antaŭ Sia vizaĝo. Kaj Cidkija defalis de la reĝo de Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'En la naŭa jaro de lia reĝado, en la deka monato, en la deka tago de la monato, venis Nebukadnecar, reĝo de Babel, li kaj lia tuta militistaro, kontraŭ Jerusalemon, kaj eksieĝis ĝin, kaj oni konstruis ĉirkaŭ ĝi bastionojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'Kaj la urbo restis sieĝata ĝis la dek-unua jaro de la reĝo Cidkija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'En la kvara monato, en la naŭa tago de la monato, kiam la malsato tiel fortiĝis en la urbo, ke la popolo de la lando ne havis panon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'tiam oni faris enrompon en la urbon; kaj ĉiuj militistoj forkuris, kaj eliris el la urbo nokte, laŭ la vojo de la pordego inter la du muregoj apud la ĝardeno de la reĝo, kaj foriris laŭ la vojo al la stepo. Kaj la Ĥaldeoj staris ĉirkaŭ la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Kaj la militistaro de la Ĥaldeoj postkuris la reĝon kaj kuratingis Cidkijan sur la stepo de Jeriĥo, kaj lia tuta militistaro diskuris for de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'Kaj ili kaptis la reĝon kaj forkondukis lin al la reĝo de Babel, en Riblan, en la lando Ĥamat, kaj oni faris pri li juĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'Kaj la reĝo de Babel buĉis la filojn de Cidkija antaŭ liaj okuloj, kaj ankaŭ ĉiujn eminentulojn de Judujo li buĉis en Ribla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'Kaj al Cidkija li blindigis la okulojn, kaj ligis lin per kupraj katenoj; kaj la reĝo de Babel venigis lin en Babelon, kaj metis lin en malliberejon ĝis la tago de lia morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'En la kvina monato, en la deka tago de la monato, tio estas en la dek- naŭa jaro de la reĝo Nebukadnecar, reĝo de Babel, venis Nebuzaradan, estro de la korpogardistoj, kiu ĉiam estis apud la reĝo de Babel, en Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'Kaj li forbruligis la domon de la Eternulo kaj la domon de la reĝo kaj ĉiujn domojn de Jerusalem; ĉiujn grandajn domojn li forbruligis per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'Kaj ĉiujn muregojn de Jerusalem ĉirkaŭe detruis la tuta militistaro de la Ĥaldeoj, kiu estis kun la estro de la korpogardistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'La malriĉulojn el la urbo, kaj la ceteran popolon, kiu restis en la urbo, kaj la transkurintojn, kiuj transkuris al la reĝo de Babel, kaj la ceteran popolamason forkondukis Nebuzaradan, la estro de la korpogardistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Sed iom el la malriĉuloj de la lando Nebuzaradan, la estro de la korpogardistoj, restigis, ke ili estu vinberistoj kaj terkultivistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'La kuprajn kolonojn, kiuj estis en la domo de la Eternulo, kaj la bazaĵojn kaj la kupran maron, kiuj estis en la domo de la Eternulo, la Ĥaldeoj disrompis kaj forportis ilian tutan kupron en Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Kaj la potojn kaj la ŝovelilojn kaj la tranĉilojn kaj la aspergajn kalikojn kaj la kulerojn kaj ĉiujn kuprajn vazojn, kiuj estis uzataj ĉe la servado, ili forprenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'Kaj la tasojn kaj la karbujojn kaj la aspergajn kalikojn kaj la potojn kaj la lucernojn kaj la kulerojn kaj la verŝilojn, kiuj estis aŭ el oro aŭ el arĝento, prenis la estro de la korpogardistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Koncerne la du kolonojn, la unu maron, la dek du kuprajn bovojn, kiuj servis kiel subtenilo, kiujn faris la reĝo Salomono por la domo de la Eternulo: la kvanto da kupro en ĉiuj tiuj iloj estis nemezurebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'La kolonoj havis ĉiu la alton de dek ok ulnoj, kaj ĝin ĉirkaŭis ŝnuro, havanta la longon de dek du ulnoj; ĝia diko estis kvar fingroj, kaj interne ĝi estis malplena.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'Ĝi havis sur si kupran kronon, kaj la alto de unu krono estis kvin ulnoj; kaj ĉirkaŭ la krono estis kradaĵo kaj granatoj, ĉio el kupro; tiel same estis ĉe la dua kolono, ankaŭ kun granatoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'Da granatoj estis sur ĉiu flanko naŭdek ses; la nombro de la granatoj ĉirkaŭ la krono estis cent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Kaj la korpogardistestro prenis la ĉefpastron Seraja kaj la duan pastron Cefanja kaj la tri pordogardistojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'Kaj el la urbo li prenis unu korteganon, kiu estis super la militistoj, kaj sep virojn el la adjutantoj de la reĝo, kiuj troviĝis en la urbo, kaj la skribiston de la militestro, kiu enregistradis militistojn el la popolo de la lando, kaj sesdek homojn el la popolo de la lando, kiuj troviĝis en la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Ilin prenis Nebuzaradan, la estro de la korpogardistoj, kaj forkondukis al la reĝo de Babel en Riblan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'Kaj la reĝo de Babel frapis ilin kaj mortigis ilin en Ribla, en la lando Ĥamat. Tiamaniere Jehuda estis elhejmigita el sia lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Jen estas la kvanto de la popolo, kiun Nebukadnecar elhejmigis: en la sepa jaro tri mil dudek tri Judojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'en la dek-oka jaro de Nebukadnecar okcent tridek du homojn el Jerusalem;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'en la dudek-tria jaro de Nebukadnecar la korpogardistestro Nebuzaradan elhejmigis sepcent kvardek kvin homojn el la Judoj: la kvanto de ĉiuj estis kvar mil sescent homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'En la tridek-sepa jaro post la elpatrujigo de Jehojaĥin, reĝo de Judujo, en la dek-dua monato, en la dudek-kvina tago de la monato, Evil- Merodaĥ, reĝo de Babel, en la unua jaro de sia reĝado, levis la kapon de Jehojaĥin, reĝo de Judujo, kaj elirigis lin el la malliberejo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'kaj li parolis kun li afable, kaj starigis lian tronon pli alte ol la tronoj de la aliaj reĝoj, kiuj estis ĉe li en Babel;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'kaj li ŝanĝis liajn vestojn de malliberejo; kaj li manĝadis ĉiam ĉe li dum sia tuta vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Kaj liaj vivrimedoj, vivrimedoj konstantaj, estis donataj al li de la reĝo de Babel ĉiutage dum lia tuta vivo, ĝis la tago de lia morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Kiel solece sidas la urbo, kiu estis tiel multehoma! La estrino de la nacioj fariĝis kiel vidvino, La princino de landoj fariĝis tributulino!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Senĉese ŝi ploras en la nokto, kaj ŝiaj larmoj estas sur ŝiaj vangoj; Ŝi havas neniun konsolanton inter ĉiuj siaj amintoj, Ĉiuj ŝiaj amikoj ŝin perfidis, fariĝis ŝiaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Elmigris Jehuda pro mizero kaj tro malfacila laborado; Li ekloĝis inter la nacioj, sed ne trovas ripozon; Ĉiuj liaj persekutantoj atingis lin en malvastaj lokoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'La vojoj de Cion estas malĝojaj, ĉar neniu iras al festoj; Ĉiuj ĝiaj pordegoj dezertiĝis, ĝiaj pastroj ĝemas; Ĝiaj virgulinoj ploras, kaj al ĝi mem estas tre maldolĉe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Ĝiaj kontraŭuloj fariĝis ĉefoj, ĝiaj malamikoj ĝuas bonstaton; Ĉar la Eternulo ĵetis sur ĝin mizeron pro la multo de ĝiaj malbonagoj; Ĝiaj infanoj iris en kaptitecon, pelataj de la malamiko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'Foriĝis de la filino de Cion ŝia tuta beleco; Ŝiaj princoj fariĝis kiel cervoj, kiuj ne trovas paŝtejon, Kaj ili iras senforte antaŭ la pelanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'En la tagoj de sia mizero kaj suferoj Jerusalem rememoras ĉiujn ĉarmaĵojn, kiujn ŝi havis en la tempoj pasintaj; Dume nun ŝia popolo enfalis en la manon de premanto, kaj neniu ŝin helpas, La malamikoj ŝin rigardas kaj ridas pri ŝia ruiniĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Pekis, pekis Jerusalem, tial ŝi fariĝis kiel hontindulino; Ĉiuj, kiuj ŝin estimis, nun malestimas ŝin, ĉar ili vidas ŝian malhonoron; Kaj ŝi mem ĝemas kaj turnas sin malantaŭen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Ŝia malpuraĵo estas sur la rando de ŝia vesto; ŝi ne pensis pri sia estonteco; Tial ŝi terure malaltiĝis, kaj ŝi havas neniun konsolanton: Rigardu, ho Eternulo, mian mizeron, ĉar la malamiko forte fieras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'La malamiko etendis sian manon sur ĉiujn ŝiajn grandvaloraĵojn; Ŝi vidas, kiel en ŝian sanktejon eniras nacioj, Pri kiuj Vi ordonis, ke ili ne eniru en Vian komunumon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Ŝia tuta popolo ĝemas, ili serĉas panon, Ili fordonas siajn grandvaloraĵojn pro manĝaĵo, por revigligi sian animon: Rigardu, ho Eternulo, kaj vidu, kiel malestimata mi fariĝis!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Ho vi, ĉiuj, kiuj preteriras la vojon, rigardu kaj vidu, Ĉu ekzistas sufero simila al mia sufero, Kiu trafis min kaj kiun la Eternulo ĵetis sur min en la tago de Lia flama kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'De supre Li ĵetis fajron en miajn ostojn, kaj ĝi ekregis en ili; Li etendis reton antaŭ miaj piedoj, renversis min malantaŭen; Li ruinigis min, faris min dolorplena dum la tuta tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Kunplektiĝis per Lia mano la jugo de miaj pekoj; Ili kunplektiĝis, suriris sur mian kolon; Li faligis mian forton; La Sinjoro transdonis min en tiajn manojn, el kiuj mi ne povas leviĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'La Sinjoro dispremis per la piedoj ĉiujn miajn fortulojn interne de mi; Li kunvokis festan kunvenon kontraŭ min, por disbati miajn junulojn; Kiel en vinpremejo la Sinjoro piedpremis la virgulinon-filinon de Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Pro tio mi ploras kaj miaj ambaŭ okuloj abunde fluigas akvon; Ĉar malproksime de mi estas konsolanto, kiu povus revigligi mian animon; Miaj infanoj pereis, ĉar la malamiko venkis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Cion etendas siajn manojn, sed ĝi ne trovas konsolanton; La Eternulo vokis kontraŭ Jakobon liajn malamikojn de ĉiuj flankoj; Jerusalem fariĝis inter ili kiel hontindulino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Justa Li estas, la Eternulo, ĉar mi malobeis Liajn vortojn. Aŭskultu, ho ĉiuj popoloj, kaj rigardu mian suferadon: Miaj virgulinoj kaj junuloj iris en kaptitecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Mi vokis miajn amikojn, sed ili min trompis; Miaj pastroj kaj miaj plejaĝuloj estas mortantaj en la urbo, Ili serĉas por si panon, por revigligi sian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Rigardu, ho Eternulo, en kia mizero mi estas! Miaj internaĵoj ŝvelis, mia koro renversiĝis en mi, ĉar mi forte malobeis. Ekstere seninfanigis min la glavo, kaj en la domo la morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Oni aŭdas, kiel mi ĝemas, sed neniu min konsolas; Ĉiuj miaj malamikoj aŭdis pri mia malfeliĉo, kaj ekĝojis, ĉar Vi tion faris; Venigu do la tagon, kiam Vi proklamos, ke ili fariĝu kiel mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Ilia tuta malboneco venu antaŭ Vin; Kaj agu kun ili tiel, kiel Vi agis kun mi pro ĉiuj miaj pekoj; Ĉar granda estas mia ĝemado, kaj mia koro doloras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Kiele la Sinjoro en Sia kolero kovris per mallumo la filinon de Cion! De la ĉielo sur la teron Li ĵetegis la belecon de Izrael, Kaj ne rememoris Sian piedbenketon en la tago de Sia kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Senindulge ekstermis la Sinjoro ĉiujn loĝejojn de Jakob; Li detruis en Sia kolero la fortikaĵojn de la filino de Jehuda, alniveligis ilin al la tero; Li frapis la regnon kaj ĝiajn regantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'En flama kolero Li rompis ĉiujn kornojn de Izrael; Li tiris Sian dekstran manon malantaŭen, kiam venis la malamiko; Kaj Li ekbruligis en Jakob kvazaŭ flamantan fajron, kiu ekstermas ĉion ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Li streĉis Sian pafarkon kiel malamiko, direktis Sian dekstran manon kiel atakanto, Kaj mortigis ĉion, kio estis ĉarma por la okuloj; En la tendo de la filino de Cion Li elverŝis Sian koleron kiel fajron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'La Sinjoro fariĝis kiel malamiko, Li ekstermis Izraelon, ekstermis ĉiujn liajn palacojn, detruis liajn fortikaĵojn; Kaj al la filino de Jehuda Li donis multe da plorado kaj ĝemado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Kiel ĝardenon Li ruinigis lian tendon, detruis lian kunvenejon; La Eternulo forgesigis en Cion feston kaj sabaton, Kaj forpuŝis en la indigno de Sia kolero reĝon kaj pastron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'La Sinjoro forlasis Sian altaron, abomenis Sian sanktejon, Transdonis en la manojn de malamikoj la murojn de ĝiaj palacoj; Ili faris bruon en la domo de la Eternulo kiel en tago de festo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'La Eternulo decidis ekstermi la muregon de la filino de Cion; Li eltiris la mezurŝnuron, ne detenis Sian manon de ekstermado; Li funebrigis la fortikaĵon kaj muregon, ambaŭ havas nun mizeran aspekton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Enprofundiĝis en la teron ĝiaj pordegoj; Li detruis kaj rompis ĝiajn riglilojn; Ĝia reĝo kaj ĝiaj princoj estas inter la nacioj; La leĝoj jam ne ekzistas, kaj ĝiaj profetoj ne plu ricevas vizion de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Silente sidas sur la tero la plejaĝuloj de la filino de Cion; Polvon ili metis sur sian kapon, zonis sin per sakaĵo; Al la tero klinis sian kapon la virgulinoj de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Konsumiĝis de larmoj miaj okuloj, ŝvelis miaj internaĵoj, Elverŝiĝis sur la teron mia hepato, pro la pereo de la filino de mia popolo, Kiam infanoj kaj suĉinfanoj senfortiĝis de malsato sur la stratoj de la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Al siaj patrinoj ili diris: Kie estas pano kaj vino? Ili falis kiel vunditaj sur la stratoj de la urbo, Kaj eligis sian animon sur la brusto de siaj patrinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Kiun mi povas montri al vi, kun kiu mi povas kompari vin, ho filino de Jerusalem? Kiun similan mi povas montri al vi, por konsoli vin, ho virgulino-filino de Cion? Ĉar granda kiel la maro estas via malfeliĉo; kiu vin resanigos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Viaj profetoj profetis al vi malveraĵon kaj sensencaĵon, Kaj ne montris al vi viajn malbonagojn, por antaŭgardi vin kontraŭ kaptiteco; Ili predikis al vi viziojn malverajn, kiuj alportis al vi elpelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Kunfrapas pri vi siajn manojn ĉiuj preterirantoj; Ili fajfas kaj balancas la kapon pri la filino de Jerusalem, dirante: Ĉu tio estas la urbo, kiun oni nomis perfektaĵo de beleco, ĝojo de la tuta tero?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Malfermegas kontraŭ vi sian buŝon ĉiuj viaj malamikoj; Ili fajfas kaj grincigas la dentojn, dirante: Ni englutis ŝin; Ĉi tiun tagon ni atendis, ni ĝin atingis, ni ĝin vidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'La Eternulo plenumis tion, kion Li intencis; Li plenumis Sian vorton, kiun Li eldiris antaŭ longa tempo; Li detruis senindulge, Li ĝojigis pri vi la malamikon, Li altigis la kornon de viaj kontraŭuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Ilia koro krias al la Sinjoro: Ho murego de la filino de Cion, verŝu larmojn kiel torento tage kaj nokte; Ne ripozu, la pupilo de via okulo ne silentu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Leviĝu, ploregu en la nokto en la komenco de ĉiu gardoparto; Elverŝu kiel akvon vian koron antaŭ la vizaĝo de la Sinjoro; Levu al Li viajn manojn pro la animo de viaj infanoj, kiuj senfortiĝas de malsato en la komenco de ĉiuj stratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Rigardu, ho Eternulo, kaj vidu, kun kiu Vi agis tiamaniere! Ĉu ie aliloke manĝis virinoj sian frukton, siajn dorlotitajn infanojn? Ĉu ie estis mortigataj en la sanktejo de la Sinjoro pastroj kaj profetoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Surtere sur la stratoj kuŝis junuloj kaj maljunuloj; Miaj junulinoj kaj junuloj falis de glavo; Vi mortigis en la tago de Via kolero, buĉis kaj ne kompatis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Kiel por festa tago Vi kunvokis de ĉirkaŭe miajn terurajn najbarojn, Kaj en la tago de la kolero de la Eternulo neniu saviĝis, neniu restis; Tiujn, kiujn mi dorlotis kaj edukis, ĉiujn ekstermis mia malamiko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Mi estas la viro, kiu spertis suferon sub la vergo de Lia kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Min Li kondukis kaj irigis en mallumon, ne en lumon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Nur sur min Li turnas Sian manon ĉiutage denove.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Li maljunigis mian karnon kaj haŭton, rompis miajn ostojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Li konstruis ĉirkaŭ mi, ĉirkaŭis min per maldolĉaĵoj kaj malfacilaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'En mallumon Li lokis min, kiel porĉiamajn mortintojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Li ĉirkaŭbaris min, ke mi ne povu eliri; Li ligis min per pezaj ĉenoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Kvankam mi krias kaj vokas, Li kovras Siajn orelojn antaŭ mia preĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Li baris miajn vojojn per hakitaj ŝtonoj; Li kurbigis miajn vojetojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Li estas por mi kiel urso en embusko, kiel leono en kaŝita loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Li depuŝis min de miaj vojoj, kaj disŝiris min; Li faris min objekto de teruro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Li streĉis Sian pafarkon, kaj starigis min kiel celon por Siaj sagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'En miajn renojn Li pafis la filojn de Sia sagujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Mi fariĝis mokataĵo por mia tuta popolo, ilia ĉiutaga rekantaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Li satigis min per maldolĉaĵo, trinkoplenigis min per vermuto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Li disrompis miajn dentojn en malgrandajn pecojn, Li enpuŝis min en cindron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Mia animo estas forpuŝita for de paco; bonstaton mi forgesis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'Kaj mi diris: Pereis mia forto kaj mia espero al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'La memoro pri mia mizero kaj miaj suferoj estas vermuto kaj galo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Konstante rememorante tion, senfortiĝas en mi mia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Sed tion mi respondas al mia koro, kaj tial mi esperas:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Ĝi estas favorkoreco de la Eternulo, ke ni ne tute pereis; ĉar Lia kompatemeco ne finiĝis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'Sed ĉiumatene ĝi renoviĝas; granda estas Via fideleco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'Mia parto estas la Eternulo, diras mia animo; tial mi esperas al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'La Eternulo estas bona por tiuj, kiuj esperas al Li, por la animo, kiu serĉas Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Bone estas esperi pacience helpon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Bone estas al la homo, kiu portas jugon en sia juneco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Li sidas solece kaj silentas, kiam li estas ŝarĝita;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'Li metas sian buŝon en polvon, kredante, ke ekzistas espero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Li donas sian vangon al tiu, kiu lin batas; li satigas sin per malhonoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Ĉar ne por eterne forlasas la Sinjoro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'Se Li iun suferigas, Li ankaŭ kompatas pro Sia granda favorkoreco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Ĉar ne el Sia koro Li sendas mizeron kaj suferon al la homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Kiam oni premas sub siaj piedoj ĉiujn malliberulojn de la tero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'Kiam oni forklinas la rajton de homo antaŭ la vizaĝo de la Plejaltulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'Kiam oni estas maljusta kontraŭ homo en lia juĝa afero-Ĉu la Sinjoro tion ne vidas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Kiu povas per sia diro atingi, ke io fariĝu, se la Sinjoro tion ne ordonis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Ĉu ne el la buŝo de la Plejaltulo eliras la decidoj pri malbono kaj pri bono?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Kial murmuras homo vivanta? Ĉiu murmuru kontraŭ siaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Ni trarigardu kaj esploru nian konduton, kaj ni revenu al la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Ni levu nian koron kaj niajn manojn al Dio en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Ni pekis kaj malobeis, kaj Vi ne pardonis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Vi kovris Vin per kolero kaj persekutis nin; Vi mortigis, Vi ne kompatis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Vi kovris Vin per nubo, por ke ne atingu Vin la preĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Vi faris nin balaindaĵo kaj abomenindaĵo inter la popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Malfermegis kontraŭ ni sian buŝon ĉiuj niaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Teruro kaj pereo trafis nin, ruinigo kaj malfeliĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Torentojn da akvo verŝas mia okulo pri la malfeliĉo de la filino de mia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Mia okulo fluigas kaj ne ĉesas, ne ekzistas por ĝi halto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'Ĝis la Eternulo ekrigardos kaj ekvidos de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Mia okulo suferigas mian animon pri ĉiuj filinoj de mia urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Senkaŭze ĉasas min kiel birdon miaj malamikoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'Ili pereigas mian vivon en kavo, ili ĵetas sur min ŝtonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Akvo leviĝis kontraŭ mian kapon, kaj mi diris: Mi tute pereis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Mi vokis Vian nomon, ho Eternulo, el la profunda kavo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Vi aŭdis mian voĉon; ne kovru Vian orelon antaŭ mia vokado pri liberigo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Vi alproksimiĝis, kiam mi vokis al Vi; Vi diris: Ne timu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Vi, ho Sinjoro, defendis mian juĝaferon; Vi liberigis mian vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Vi vidis, ho Eternulo, la maljustaĵon, kiun mi suferas; juĝu mian aferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Vi vidis ilian tutan venĝon, ĉiujn iliajn intencojn kontraŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Vi aŭdis ilian insultadon, ho Eternulo, ĉiujn iliajn intencojn kontraŭ mi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'La parolojn de tiuj, kiuj leviĝis kontraŭ min, kaj iliajn pensojn kontraŭ mi dum la tuta tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Rigardu, kiam ili sidas kaj kiam ili leviĝas; mi ĉiam estas ilia rekantaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Redonu al ili repagon, ho Eternulo, laŭ la faroj de iliaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Donu al ili doloron en la koro, sentigu al ili Vian malbenon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Persekutu ilin en kolero, kaj ekstermu ilin el sub la ĉielo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Kiele senbriliĝis la oro, ŝanĝiĝis la bonega metalo! La ŝtonoj de la sanktejo kuŝas disĵetitaj en la komenco de ĉiuj stratoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'La karaj filoj de Cion, havantaj la valoron de plej pura oro, Kiele ili similiĝis al argilaj potoj, faritaĵo de potisto!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Eĉ ŝakaloj donas siajn mamojn kaj nutras siajn idojn; Sed la filino de mia popolo fariĝis kruela, kiel strutoj en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'La lango de suĉinfano algluiĝis al ĝia palato pro soifo; Infanoj petas panon, sed neniu donas al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Kiuj antaŭe manĝadis frandaĵojn, tiuj senfortiĝas nun pro malsato sur la stratoj; Kiuj estis edukitaj sur purpuro, tiuj ruliĝas nun sur sterko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'La pekoj de la filino de mia popolo estas pli grandaj, ol la pekoj de Sodom, Kiu estis renversita momente, kaj manoj ĝin ne turmentis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Ŝiaj princoj estis pli puraj ol neĝo, pli klaraj ol lakto; Ilia vizaĝo estis pli ruĝa ol koraloj, ili aspektis kiel safiro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Nun ilia vizaĝo estas pli nigra ol karbo; oni ne rekonas ilin sur la stratoj; Ilia haŭto alpendiĝis al iliaj ostoj, velksekiĝis kiel ligno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Pli bone estis al tiuj, kiuj mortis de glavo, ol al tiuj, kiuj mortas de malsato, Kiuj senfortiĝas kaj pereas pro manko de produktaĵoj de kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'La manoj de kompatemaj virinoj kuiris iliajn infanojn; Kaj ĉi tiuj fariĝis ilia manĝaĵo en la mizerego de la filino de mia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'La Eternulo plene elĉerpis Sian koleron, Li elverŝis la flamon de Sia indigno; Li ekbruligis en Cion fajron, kiu ekstermis ĝiajn fundamentojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Ne kredis la reĝoj de la tero, nek ĉiuj loĝantoj de la mondo, Ke malamiko kaj kontraŭulo eniros en la pordegojn de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Tio fariĝis pro la pekoj de ĝiaj profetoj, pro la malbonagoj de ĝiaj pastroj, Kiuj verŝadis en ĝi sangon de virtuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Kiel blinduloj ili vagadis sur la stratoj, Malpurigis sin per sango tiel, ke oni ne povis tuŝi iliajn vestojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, 'Oni kriis al ili: For, malpuruloj! for, for, ne altuŝiĝu! Kiam ili foriĝadis kaj vagadis, oni diradis inter la nacioj: Ili ne plu loĝos tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'La vizaĝo de la Eternulo ilin disĵetis, kaj jam ne volas rigardi ilin; Pastrojn ili ne respektis, plejaĝulojn ili ne kompatis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Ankoraŭ laciĝadis niaj okuloj, atendante senvaloran helpon; Streĉe ni atendis nacion, kiu ne povas helpi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Ili glitigis niajn paŝojn, ke ni ne povu iri sur niaj stratoj. Alproksimiĝis nia fino; pleniĝis nia tempo, ĉar venis nia fino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Pli rapidaj ol agloj de la ĉielo estis niaj persekutantoj; Sur la montoj ili postkuris nin, en la dezerto ili faris embuskojn kontraŭ ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'La spiro de nia vivo, la sanktoleito de la Eternulo, kaptiĝis en iliajn kavojn, Pri kiu ni diris: Sub lia ombro ni vivos inter la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Ĝoju kaj estu gaja, ho filino de Edom, kiu loĝas en la lando Uc; Ankaŭ al vi venos la kaliko, vi ebriiĝos kaj nudiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Finiĝis viaj malbonagoj, ho filino de Cion; Li vin ne plu forkondukigos; Sed viajn malbonagojn, ho filino de Edom, Li punos, Li malkovros viajn pekojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Rememoru, ho Eternulo, kio fariĝis al ni; Rigardu kaj vidu nian malhonoron!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Nia heredaĵo transiris al fremduloj, Niaj domoj al aligentuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Ni fariĝis orfoj senpatraj, Niaj patrinoj estas kiel vidvinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Nian akvon ni trinkas pro mono; Nian lignon ni ricevas nur pro pago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Oni pelas nin je nia kolo; Ni laciĝis, sed oni ne permesas al ni ripozi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Al Egiptujo ni etendis la manon, Al Asirio, por satiĝi per pano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Niaj patroj pekis, sed ili jam ne ekzistas; Kaj ni devas suferi pro iliaj malbonagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Sklavoj regas super ni; Kaj neniu liberigas nin el iliaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Kun danĝero por nia vivo ni akiras nian panon, Pro la glavo en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Nia haŭto varmegiĝis kiel forno, Por la kruela malsato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'La virinojn en Cion ili senhonorigis, La virgulinojn en la urboj de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'La princoj estas pendigitaj je siaj manoj; La maljunulojn oni ne respektis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'La junuloj devas porti muelŝtonojn; La knaboj falas sub la lignoŝarĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'La maljunuloj jam ne sidas ĉe la pordegoj, La junuloj jam ne kantas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Malaperis la gajeco de nia koro; Niaj dancrondoj aliformiĝis en funebron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Defalis la krono de nia kapo; Ho ve al ni, ke ni pekis!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Pro tio senfortiĝis nia koro, Pro tio senlumiĝis niaj okuloj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'Pro la monto Cion, ke ĝi fariĝis dezerta, Ke vulpoj vagas sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Sed Vi, ho Eternulo, kiu restas eterne Kaj kies trono staras de generacio al generacio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Kial Vi forgesis nin kvazaŭ por eterne, Forlasis nin por longa tempo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Reirigu nin, ho Eternulo, al Vi, ke ni revenu; Renovigu niajn tagojn kiel en la tempo antaŭa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Ĉar ĉu Vi nin tute forpuŝis? Vi tre forte ekkoleris kontraŭ ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'En la trideka jaro, en la kvina tago de la kvara monato, kiam mi estis inter la elpatrujigitoj ĉe la rivero Kebar, malfermiĝis la ĉielo, kaj mi ekvidis viziojn de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'En la kvina tago de tiu monato, tio estas, en la kvina jaro post la elpatrujigo de la reĝo Jehojaĥin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'aperis la vorto de la Eternulo al la pastro Jeĥezkel, filo de Buzi, en la lando Ĥaldea, ĉe la rivero Kebar, kaj tie aperis sur li la mano de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Kaj mi vidis, jen malkvieta vento venis el la nordo kun granda nubo kaj flamanta fajro; brilo estis ĉirkaŭe de ĝi, kaj el interne, el la mezo de la fajro, iris tre hela lumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'El la mezo vidiĝis bildo de kvar kreitaĵoj, kaj ilia aspekto estis kiel aspekto de homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'Kaj ĉiu havis kvar vizaĝojn, kaj ĉiu el ili havis kvar flugilojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Iliaj piedoj estis piedoj rektaj, kaj la plandoj de iliaj piedoj estis kiel plando de bovido kaj brilis kiel hela pura kupro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Kaj homaj manoj estis sub iliaj flugiloj ĉe iliaj kvar flankoj; ĉiuj kvar havis siajn vizaĝojn kaj siajn flugilojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Iliaj flugiloj estis kuntuŝiĝantaj unu kun la alia; irante, ili sin ne deturnadis, sed ĉiu iradis laŭ la direkto de sia vizaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'La aspekto de iliaj vizaĝoj estis kiel vizaĝo homa, kaj kiel vizaĝo leona sur la dekstra flanko de ĉiuj kvar, kiel vizaĝo bova sur la maldekstra flanko de ĉiuj kvar, kaj kiel vizaĝo agla ĉe ĉiuj kvar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Iliaj vizaĝoj kaj flugiloj supre estis disigitaj; ĉe ĉiu el ili du flugiloj tuŝis unu la alian kaj du kovris ilian korpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'Ĉiu iradis laŭ la direkto de sia vizaĝo; kien tiris ilin la spirito, tien ili iradis, ne deturnante sin dum sia irado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'La aspekto de la kreitaĵoj estis kiel aspekto de ardantaj kaj brulantaj karboj, kiel aspekto de torĉoj, irantaj inter tiuj kreitaĵoj; brilon havis la fajro, kaj el la fajro eliradis fulmoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Kaj la kreitaĵoj kuradis tien kaj reen kiel fulmoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Rigardante la kreitaĵojn, mi ekvidis, ke sur la tero apud la kreitaĵoj troviĝis po unu rado ĉe la kvar vizaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'La aspekto de la radoj kaj ilia prilaboriteco estis kiel aspekto de turkiso, ĉiuj kvar havis la saman aspekton; ilia aspekto kaj prilaboriteco estis tiel, kvazaŭ unu rado troviĝus en la alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Irante, ili sin movadis sur siaj kvar flankoj; ili ne deturnadis sin dum la irado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Iliaj radrondoj estis altaj kaj teruraj; la radrondoj de ĉiuj kvar estis plenaj de okuloj ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'Kaj kiam la kreitaĵoj iris, la radoj iradis apud ili; kaj kiam la kreitaĵoj leviĝis de la tero, leviĝadis ankaŭ la radoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Kien la spirito instigis ilin iri, tien ili iradis; kien la spirito instigis ilin iri, la radoj leviĝadis kune kun ili, ĉar la spirito de la kreitaĵoj estis en la radoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Kiam tiuj iris, ili ankaŭ iradis; kiam tiuj staris, ili ankaŭ staris; kiam tiuj leviĝis de la tero, la radoj leviĝadis apud ili, ĉar la spirito de la kreitaĵoj estis en la radoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Super la kapoj de la kreitaĵoj estis io simila al firmamento, kvazaŭ terura kristalo, etendita super iliaj kapoj supre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'Sub la firmamento estis etenditaj iliaj flugiloj, rekte unu apud la alia; la korpon de ĉiu el ili kovris du flugiloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'Mi aŭdis, kiel iliaj flugiloj dum ilia irado bruis kiel granda akvo, kiel la voĉo de la Plejpotenculo, granda bruo, kiel bruo de tendaro; kiam ili haltis, iliaj flugiloj malleviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'Kiam aŭdiĝis voĉo el super la firmamento, kiu estis super iliaj kapoj, ili haltadis kaj mallevadis siajn flugilojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'Supre de la firmamento, kiu estis super iliaj kapoj, estis io, aspektanta kiel safiro, havanta la formon de trono; kaj super la bildo de la trono estis kvazaŭ bildo de homo, sidanta sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'Kaj mi vidis kvazaŭ helegan brilon, kvazaŭ fajron interne kaj ĉirkaŭe, de la bildo de liaj lumboj supren kaj de la bildo de liaj lumboj malsupren; mi vidis aspekton de fajro kaj brilon ĉirkaŭ de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Kiel la aspekto de ĉielarko, kiu montriĝas en la nuboj en la tempo de pluvo, tia estis la aspekto de la brilo ĉirkaŭe. Tio estis la aspekto de la majesto de la Eternulo. Kiam mi tion vidis, mi ĵetis min vizaĝaltere, kaj mi aŭdis voĉon de parolanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'Kaj Li diris al mi: Ho filo de homo, stariĝu sur viaj piedoj, kaj Mi parolos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Kaj kiam Li parolis al mi, venis en min spirito kaj starigis min sur miaj piedoj; kaj mi aŭskultis Tiun, kiu parolis al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Kaj Li diris al mi: Ho filo de homo, Mi sendas vin al la Izraelidoj, al la defalintaj gentoj, kiuj defalis de Mi; ili kaj iliaj patroj perfidis Min ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'La filoj havas malmolan vizaĝon kaj obstinan koron; Mi sendas vin al ili, por ke vi diru al ili: Tiele diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'Ĉu ili aŭskultos, ĉu ili ne aŭskultos (ĉar ili estas domo malobeema), ili almenaŭ sciu, ke profeto estis inter ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Kaj vi, ho filo de homo, ne timu ilin, kaj ne timu iliajn parolojn; kvankam ili estas por vi dornoj kaj pikiloj kaj vi loĝas inter skorpioj, tamen ne timu iliajn vortojn, kaj ne sentu teruron antaŭ ilia vizaĝo, ĉar ili estas domo malobeema.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Kaj diru al ili Miajn vortojn, ĉu ili aŭskultos aŭ ĉu ili ne aŭskultos, ĉar ili estas malobeemaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Kaj vi, ho filo de homo, aŭskultu tion, kion Mi diras al vi; ne estu malobeema, kiel la malobeema domo; malfermu vian buŝon, kaj manĝu tion, kion Mi donos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Kaj mi ekvidis, jen mano estas etendita al mi, kaj en ĝi estas skribrulaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Kaj Li disvolvis ĝin antaŭ mi, kaj ĝi estis skribkovrita interne kaj ekstere, kaj sur ĝi estis skribitaj lamentoj, ĝemoj, kaj veoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Kaj Li diris al mi: Ho filo de homo, manĝu tion, kion vi trovas, manĝu ĉi tiun skribrulaĵon, kaj iru kaj parolu al la domo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Kaj mi malfermis mian buŝon, kaj Li manĝigis al mi tiun skribrulaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'Kaj Li diris al mi: Ho filo de homo, en vian ventron manĝu, kaj vian internaĵon plenigu per ĉi tiu skribrulaĵo, kiun Mi donas al vi. Kaj mi manĝis, kaj en mia buŝo ĝi estis dolĉa, kiel mielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Kaj Li diris al mi: Ho filo de homo, iru al la domo de Izrael, kaj parolu al ili per Miaj vortoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Ĉar ne al popolo kun nekomprenebla lingvo kaj malfacila parolado vi estas sendata, sed al la domo de Izrael;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'ne al multaj popoloj kun nekomprenebla lingvo kaj malfacila parolado, kies vortojn vi ne komprenas; cetere, se eĉ al ili Mi sendus vin, eĉ ili aŭskultus vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Sed la domo de Izrael ne volos aŭskulti vin, ĉar ili ne volas aŭskulti Min; ĉar la tuta domo de Izrael havas malmolan frunton kaj obstinan koron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Jen Mi faris vian vizaĝon forta kontraŭ iliaj vizaĝoj kaj vian frunton forta kontraŭ iliaj fruntoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Mi faris vian frunton kiel diamanto pli forta ol siliko; ne timu ilin, kaj ne sentu teruron antaŭ ili, ĉar ili estas domo malobeema.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Kaj Li diris al mi: Ho filo de homo, ĉiujn Miajn vortojn, kiujn Mi parolos al vi, prenu en vian koron kaj aŭskultu per viaj oreloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Kaj iru al la elpelitoj, al la filoj de via popolo, kaj parolu al ili, kaj diru al ili: Tiele diras la Sinjoro, la Eternulo-tute egale, ĉu ili aŭskultos aŭ ne aŭskultos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Kaj levis min la spirito, kaj mi ekaŭdis malantaŭ mi grandan bruon: Benita estu la majesto de la Eternulo sur sia loko!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'Kaj aŭdiĝis bruo de la flugiloj de la kreitaĵoj, kiuj kunfrapiĝadis unuj kun la aliaj, kaj bruo de la radoj apud ili, kaj bruo de granda tertremo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'Kaj la spirito levis min kaj forportis min; kaj mi iris kun afliktita kaj maltrankvila koro; kaj la mano de la Eternulo tenis min forte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'Kaj mi venis en Tel-Abibon, al la elpelitoj, kiuj loĝis ĉe la rivero Kebar; kaj mi haltis tie, kie ili loĝis, kaj mi restis tie inter ili sep tagojn malĝoje.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'Post paso de la sep tagoj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, 'Ho filo de homo! Mi starigis vin kiel observiston super la domo de Izrael; kaj kiam vi aŭdos vorton el Mia buŝo, tiam instruu ilin de Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Kiam Mi diros al la malpiulo: Vi devas morti, kaj vi ne admonos lin, kaj vi ne parolos, por averti malpiulon kontraŭ lia malbona vojo, por konservi al li la vivon-tiam li, malpiulo, mortos pro sia malpieco, sed lian sangon Mi repostulos el via mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Sed se vi avertis malpiulon, kaj li ne returnis sin de sia malpieco kaj de sia malbona vojo, tiam li mortos pro sia malpieco, kaj vi estos savinta vian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Kaj se virtulo deturnos sin de sia virteco kaj agos malbone, tiam Mi metos antaŭ lin falpuŝilon, kaj li mortos; ĉar vi lin ne avertis, li mortos pro sia peko, kaj ne estos rememorataj la bonaj agoj, kiujn li faris; sed lian sangon Mi repostulos el via mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Sed se vi avertos virtulon, ke la virtulo ne peku, kaj li ne pekos, tiam li restos vivanta pro tio, ke li akceptis averton, kaj vi estos savinta vian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'Kaj venis sur min tie la mano de la Eternulo, kaj Li diris al mi: Leviĝu, kaj iru en la valon, kaj tie Mi parolos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Kaj mi leviĝis, kaj eliris en la valon; kaj jen tie staras la majesto de la Eternulo, simile al la majesto, kiun mi vidis ĉe la rivero Kebar. Kaj mi ĵetis min vizaĝaltere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Kaj eniris en min la spirito kaj starigis min sur miaj piedoj. Kaj Li ekparolis al mi, kaj diris al mi: Iru, enŝlosu vin en via domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Kaj vidu, ho filo de homo, oni metos sur vin ŝnurojn kaj ligos vin per ili, kaj vi ne povos eliri inter ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'kaj vian langon Mi algluos al via palato, kaj vi mutiĝos kaj ne estos admonanto por ili; ĉar ili estas domo malobeema.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Sed kiam Mi ekparolos al vi, Mi malfermos vian buŝon, kaj vi diros al ili: Tiele diras la Sinjoro, la Eternulo: Kiu volas aŭskulti, tiu aŭskultu, kaj kiu ne volas, tiu rifuzu; ĉar ili estas domo malobeema.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'Kaj vi, ho filo de homo, prenu al vi brikon kaj kuŝigu ĝin antaŭ vi, kaj desegnu sur ĝi urbon, nome Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Kaj faru ĉirkaŭ ĝi sieĝon, aranĝu kontraŭ ĝi bastionon, surŝutu kontraŭ ĝi remparon, faru kontraŭ ĝi tendaron, kaj starigu ĉirkaŭ ĝi muregrompilojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Kaj prenu al vi feran paton kaj starigu ĝin kiel feran muron inter vi kaj la urbo, kaj direktu vian vizaĝon kontraŭ ĝin; ĝi estu sub sieĝo, kaj vi sieĝu ĝin. Tio estu signo por la domo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Kaj vi kuŝiĝu sur vian maldekstran flankon, kaj metu sur ĝin la malpiecon de la domo de Izrael; dum tiom da tagoj, kiom vi kuŝos sur ĝi, vi portos sur vi ilian malpiecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'La jarojn de ilia malpieco Mi kalkulos al vi kiel tagojn: dum tricent naŭdek tagoj vi portos sur vi la malpiecon de la domo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Kiam vi tion plenumos, tiam denove kuŝiĝu sur vian dekstran flankon, kaj portu sur vi la malpiecon de la domo de Jehuda dum kvardek tagoj; ĉiun tagon Mi kalkulos al vi kiel jaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Kaj kontraŭ la sieĝatan Jerusalemon direktu vian vizaĝon kaj vian etenditan brakon, kaj profetu kontraŭ ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Kaj jen Mi metos sur vin ŝnurojn, ke vi ne povu turni vin de unu flanko sur la alian, ĝis vi finos la tagojn de via sieĝado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Kaj prenu al vi tritikon kaj hordeon, fabojn kaj lentojn, milion kaj spelton, kaj ŝutu tion en unu vazon, kaj faru al vi el tio panon laŭ la nombro de la tagoj, dum kiuj vi kuŝos sur via flanko: dum tricent naŭdek tagoj manĝu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'Kaj vian manĝaĵon, kiun vi manĝos, uzu laŭpeze, po dudek sikloj ĉiutage; de tempo al tempo manĝu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Kaj akvon trinku laŭmezure, po sesono de hino trinku de tempo al tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'En formo de hordeaj platkukoj manĝu tion, kaj sur ekskrementoj de homoj baku ilin antaŭ iliaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'Kaj la Eternulo diris: Tiele la Izraelidoj manĝados sian panon malpure inter la popoloj, al kiuj Mi ilin dispelos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Kaj mi diris: Ho Sinjoro, ho Eternulo! jen mia animo ne malpuriĝis, kadavraĵon aŭ disŝiritaĵon mi ne manĝis de mia juneco ĝis nun, kaj nenia abomeninda viando eniris iam en mian buŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Kaj Li diris al mi: Jen Mi permesas al vi uzi ekskrementojn de brutoj anstataŭ ekskrementoj de homoj, kaj sur ili pretigu vian panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Kaj Li diris al mi: Ho filo de homo! jen Mi rompos la panan apogon en Jerusalem, kaj oni manĝos panon laŭpeze kaj en zorgoj, kaj akvon oni trinkos laŭmezure kaj kun afliktoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'ĉar mankos al ili pano kaj akvo, kaj ili kun teruro rigardos unu la alian, kaj ili konsumiĝos pro sia malpieco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'Kaj vi, ho filo de homo, prenu al vi glavon akran, kiel razilo de barbiroj, prenu ĝin al vi, kaj pasigu ĝin sur via kapo kaj sur via barbo, kaj prenu al vi pesilon, kaj disdividu la harojn:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'trionon forbruligu meze de la urbo, kiam finiĝos la tagoj de la sieĝado; trionon prenu, kaj dishaku ĝin per la glavo en la ĉirkaŭaĵo de la urbo; kaj trionon disblovu en la venton, kaj Mi elingigos post ili la glavon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Kaj prenu el tio malgrandan kvanton, kaj ligu ĝin en la randon de via vesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'Kaj ankoraŭ iom prenu el tio, kaj ĵetu en fajron, kaj forbruligu ilin per fajro; el tie eliros fajro sur la tutan domon de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Tiele diras la Sinjoro, la Eternulo: Jen estas Jerusalem; Mi starigis ĝin meze de la nacioj, kaj ĉirkaŭ ĝi estas diversaj landoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Sed ĝi agis kontraŭ Miaj decidoj pli malpie, ol la nacioj, kaj kontraŭ Miaj leĝoj pli malbone, ol la landoj, kiuj estas ĉirkaŭ ĝi; ĉar ili malestimis Miajn decidojn, kaj Miajn leĝojn ili ne sekvis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Tial tiele diras la Sinjoro, la Eternulo: Ĉar via amaso estas pli malbona, ol la nacioj, kiuj estas ĉirkaŭ vi, ĉar Miajn leĝojn vi ne sekvis kaj Miajn decidojn vi ne plenumis, kaj vi ne agis eĉ laŭ la justeco de la nacioj, kiuj estas ĉirkaŭ vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'tial tiele diras la Sinjoro, la Eternulo: Jen Mi ankaŭ iros kontraŭ vin, kaj Mi faros inter vi juĝon antaŭ la okuloj de la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'Kaj Mi agos kun vi tiel, kiel Mi neniam agis kaj kiel Mi neniam plu agos simile, pro ĉiuj viaj abomenindaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Tial gepatroj manĝos gefilojn inter vi, kaj gefiloj manĝos siajn gepatrojn; kaj Mi faros kontraŭ vi juĝon, kaj Mi disblovos vian tutan restaĵon al ĉiuj ventoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Tial, kiel Mi vivas, diras la Sinjoro, la Eternulo, pro tio, ke vi malpurigis Mian sanktejon per ĉiuj viaj abomenindaĵoj kaj per ĉiuj viaj fiaĵoj, Mi vin malgrandigos, kaj Mia okulo ne indulgos, kaj Mi ne kompatos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Triono el vi mortos de pesto kaj pereos de malsato meze de vi; triono falos de glavo en viaj ĉirkaŭaĵoj; kaj trionon Mi dispelos al ĉiuj ventoj, kaj Mi elingigos post ili la glavon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Mi plene agigos Mian koleron, kaj Mi ripozigos Mian indignon sur ili, kaj Mi faros al Mi kontentecon, por ke ili eksciu, ke Mi, la Eternulo, parolis en Mia fervoro, kiam Mi konsumos Mian koleron sur ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Kaj Mi vin dezertigos kaj hontigos inter la nacioj, kiuj estas ĉirkaŭ vi, antaŭ la okuloj de ĉiu pasanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'Kaj vi estos hontindaĵo kaj mokataĵo, ekzemplo kaj teruro por la nacioj, kiuj estas ĉirkaŭ vi, kiam Mi faros kontraŭ vi juĝon en kolero kaj indigno kaj kun indigna moralinstruo. Mi, la Eternulo, tion diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Kiam Mi ĵetos sur ilin Miajn kruelajn sagojn de malsato, kiuj estos pereigaj kaj kiujn Mi sendos por ekstermado, tiam Mi faros ĉe vi la malsaton ĉiam pli granda, kaj Mi rompos ĉe vi la panan apogon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Mi sendos sur vin malsaton, kaj sovaĝajn bestojn, kiuj faros vin seninfanaj; kaj pesto kaj sangoverŝado trairos vin, kaj glavon Mi venigos sur vin. Mi, la Eternulo, tion diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Ho filo de homo, direktu vian vizaĝon al la montoj de Izrael, kaj profetu pri ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'kaj diru: Ho montoj de Izrael, aŭskultu la vorton de la Sinjoro, la Eternulo: Tiele diras la Sinjoro, la Eternulo, al la montoj kaj al la montetoj, al la intermontoj kaj al la valoj: Jen Mi venigos sur vin glavon, kaj Mi detruos viajn altaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'Kaj dezertigitaj estos viaj altaroj, kaj rompitaj estos viaj sunkolonoj; kaj Mi faligos viajn mortigitojn antaŭ viaj idoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'Kaj Mi faligos la kadavrojn de la Izraelidoj antaŭ iliaj idoloj, kaj Mi disĵetos viajn ostojn ĉirkaŭ viaj altaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'En ĉiuj viaj loĝlokoj la urboj estos ruinigitaj kaj la altaĵoj estos dezertigitaj, por ke estu ruinigitaj kaj dezertigitaj viaj altaroj, por ke estu rompitaj kaj detruitaj viaj idoloj, viaj sunkolonoj estu disbatitaj, kaj viaj faritaĵoj estu ekstermitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'Kaj falos mortigitoj inter vi, kaj tiam vi ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Sed Mi restigos al vi kelkan kvanton, kiu saviĝos de la glavo inter la nacioj, kiam vi estos disĵetitaj en la landojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Kaj viaj saviĝintoj rememoros Min inter la nacioj, kien ili estos forkondukitaj, kiam Mi disbatos ilian malĉastan koron, kiu defalis de Mi, kaj iliajn okulojn, kiuj malĉastis kun siaj idoloj; kaj ili mem pentos pri la malbonagoj, kiujn ili faris per ĉiuj siaj abomenindaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'Kaj ili ekscios, ke Mi, la Eternulo, ne vane diris, ke Mi faros al ili tiun malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Tiele diras la Sinjoro, la Eternulo: Plaŭdu per viaj manoj, frapu per via piedo, kaj diru: Ve pro ĉiuj malbonaj abomenindaĵoj de la domo de Izrael, pro kiuj ili falos de glavo, de malsato, kaj de pesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Kiu estas malproksime, tiu mortos de pesto; kiu estas proksime, tiu falos de glavo; kiu restis kaj konserviĝis, tiu mortos de malsato. Tiel Mi konsumos Mian koleron sur ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'Kaj vi ekscios, ke Mi estas la Eternulo, kiam iliaj mortigitoj kuŝos inter siaj idoloj ĉirkaŭ iliaj altaroj sur ĉiu alta monteto, sur ĉiuj suproj de la montoj, sub ĉiu verda arbo, kaj sub ĉiu densfolia kverko, tie, kie ili faradis bonodorajn incensojn al ĉiuj siaj idoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Kaj Mi etendos Mian manon sur ilin, kaj en ĉiuj iliaj loĝlokoj Mi dezertigos la teron pli ol en la dezerto Dibla; kaj ili ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'Ho filo de homo, tiele diras la Sinjoro, la Eternulo, pri la tero de Izrael: Fino venis, la fino por ĉiuj kvar randoj de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Nun venos al vi la fino; kaj Mi sendos sur vin Mian koleron, kaj Mi juĝos vin laŭ via konduto, kaj Mi metos sur vin ĉiujn viajn abomenindaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Ne indulgos vin Mia okulo, kaj Mi ne kompatos; ĉar vian konduton Mi rekompencos sur vi, kaj viaj abomenindaĵoj estos meze de vi; kaj vi ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Tiele diras la Sinjoro, la Eternulo: Malbono, unu malbono nun venas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'fino venas, venas la fino, ĝi vekiĝas kontraŭ vin, jen ĝi venas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Venas matenruĝo kontraŭ vi, ho loĝanto de la lando; venas la tempo, proksima estas la tago de tumulto, kiam oni ne plu kantos sur la montoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Nun Mi baldaŭ elverŝos Mian indignon sur vin, Mi plene kontentigos Mian koleron sur vi, Mi juĝos vin laŭ via konduto, kaj Mi metos sur vin ĉiujn viajn abomenindaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Ne indulgos Mia okulo, kaj Mi ne kompatos; laŭ via konduto Mi redonos al vi, kaj viaj abomenindaĵoj estos meze de vi; kaj vi ekscios, ke Mi, la Eternulo, estas la batanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Jen estas la tago, jen ĝi venas, leviĝis la matenruĝo, la vergo elkreskis, la fiero ekfloris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'La perforteco leviĝis kiel vergo kontraŭ la malpiecon; nenio restos de ili, nek de ilia amaso, nek de ilia popola bruo, neniu ĝemos ĉe ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Venas la tempo, alproksimiĝas la tago; la aĉetanto ne ĝoju, kaj la vendanto ne malĝoju; ĉar la kolero trafis ilian tutan amason.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Ĉar la vendanto ne plu revenos al la venditaĵo, eĉ se ili ankoraŭ estus vivantaj; ĉar la vizio pri ilia tuta amaso ne retiriĝos, kaj neniu fortikigos sian vivon per sia malpieco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Eksonigu la trumpeton, kaj ĉiu armiĝu; neniu tamen iros en la militon, ĉar Mia kolero estas super ilia tuta amaso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'La glavo estas ekstere, la pesto kaj la malsato interne; kiu estas sur la kampo, tiu mortos de la glavo, kaj kiu estas en la urbo, tiun ekstermos malsato kaj pesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Kaj tiuj el ili, kiuj forsaviĝos, estos sur la montoj, kiel kolomboj el la valoj, ĉiuj ili ĝemos, ĉiu pro siaj malbonagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Ĉiuj manoj malleviĝos senforte, kaj ĉiuj genuoj moviĝos kiel akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'Ili zonos sin per sakaĵo; teruro ilin kovros; sur ĉiu vizaĝo estos honto, kaj ĉiuj kapoj estos senharaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Sian arĝenton ili ĵetos sur la stratojn, kaj ilia oro fariĝos malpuraĵo; ilia arĝento kaj ilia oro ne povos savi ilin en la tago de la kolero de la Eternulo, ne satigos ilian animon, kaj ne plenigos ilian internaĵon; ĉar tio estis instigilo por iliaj malbonagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'Sian plej belan ornamon ili faris objekto de fiereco, siajn abomenindajn statuojn kaj idolojn ili starigis en ĝi; tial Mi faros ĝin malpuraĵo por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'Kaj Mi transdonos ĝin en la manojn de fremduloj por disrabi, kaj al la malpiuloj de la tero kiel militakiron, kaj ili malsanktigos ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Mi deturnos Mian vizaĝon de ili, por ke ili malsanktigu Mian misterejon; kaj rabistoj tien venos kaj malsanktigos ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Faru ĉenon; ĉar la lando estas plena de sangaj krimoj kaj la urbo estas plena de perforteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Mi venigos la plej malbonajn el la nacioj, kaj ili ekposedos iliajn domojn; Mi neniigos la fierecon de la fortuloj, kaj iliaj sanktaĵoj estos malsanktigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Pereo venas; oni serĉos pacon, sed ne trovos ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Malfeliĉo post malfeliĉo venos, sciigo post sciigo; oni serĉos vizion ĉe profeto; malaperos la instruo ĉe la pastro, kaj konsilo ĉe la maljunuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'La reĝo malĝojos, la princo estos kovrita de teruro, kaj la manoj de la simpla popolo malkuraĝiĝos. Laŭ ilia konduto Mi agos kun ili, laŭ iliaj meritoj Mi juĝos ilin; kaj ili ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'En la sesa jaro, en la kvina tago de la sesa monato, mi sidis en mia domo, kaj la plejaĝuloj de Jehuda sidis antaŭ mi; kaj falis sur min la mano de la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'Kaj mi vidis, jen estas bildo, kiu aspektas kiel fajro; de la bildo de liaj lumboj malsupren estis fajro, kaj supre de liaj lumboj estis hela brilo, tre hela lumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Kaj li etendis la bildon de mano, kaj kaptis min je la bukloj de mia kapo; kaj la spirito ekportis min inter la tero kaj la ĉielo, kaj venigis min en Dia vizio en Jerusalemon, al la enirejo de la interna pordego, turnita al nordo, kie staris statuo de koleriga ĵaluzo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'Kaj jen tie estas la majesto de Dio de Izrael, simile al la vizio, kiun mi vidis en la valo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Kaj Li diris al mi: Ho filo de homo, levu viajn okulojn en la direkto al nordo! Kaj mi levis miajn okulojn en la direkto al nordo, kaj jen norde de la pordego de la altaro, ĉe la enirejo, staras tiu statuo de ĵaluzo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Kaj Li diris al mi: Ho filo de homo, ĉu vi vidas, kion ili faras? la grandajn abomenindaĵojn, kiujn la domo de Izrael faras ĉi tie, por malproksimigi Min de Mia sanktejo? sed vi ankoraŭ denove vidos grandajn abomenindaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Kaj Li venigis min al la enirejo de la korto, kaj mi ekvidis, ke jen estas unu truo en la muro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Kaj Li diris al mi: Ho filo de homo, trafosu la muron. Kaj mi trafosis la muron, kaj jen estas ia pordo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Kaj Li diris al mi: Eniru, kaj rigardu la malbonajn abomenindaĵojn, kiujn ili faras ĉi tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Kaj mi eniris kaj ekrigardis, kaj jen diversaj bildoj de rampaĵoj kaj abomenindaj brutoj kaj diversaj idoloj de la domo de Izrael estas skulptitaj sur la muro ĉirkaŭe, sur ĉiuj flankoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'Kaj antaŭ ili staras sepdek viroj el la plejaĝuloj de la domo de Izrael, kaj Jaazanja, filo de Ŝafan, staras meze de ili; kaj ĉiu havas en la mano sian incensilon, kaj de la incensoj leviĝas densa nubo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Kaj Li diris al mi: Ho filo de homo, ĉu vi vidas, kion la plejaĝuloj de la domo de Izrael faras en mallumo, ĉiu en sia ĉambro de pentraĵoj? Ĉar ili diras: La Eternulo ne vidas nin, la Eternulo forlasis la landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Kaj Li diris al mi: Vi denove ankoraŭ vidos grandajn abomenindaĵojn, kiujn ili faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Kaj Li venigis min al la enirejo de la norda pordego de la domo de la Eternulo, kaj jen tie sidas virinoj, kiuj ploras pri Tamuz.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'Kaj Li diris al mi: Ĉu vi vidas, ho filo de homo? vi vidos ankoraŭ pli grandajn abomenindaĵojn ol tiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Kaj Li venigis min en la internan korton de la domo de la Eternulo, kaj jen ĉe la enirejo de la templo de la Eternulo, inter la portiko kaj la altaro, staras ĉirkaŭ dudek kvin homoj, kun la dorso al la templo de la Eternulo kaj kun la vizaĝo al la oriento, kaj adorkliniĝas orienten, al la suno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Kaj Li diris al mi: Ĉu vi vidas, ho filo de homo? ĉu ne sufiĉas al la domo de Jehuda, ke ili faras la abomenindaĵojn, kiujn ili faras ĉi tie? ili ankoraŭ plenigis la landon per perforteco, kaj ripete kolerigas Min; kaj jen ili direktas la vergon al sia vizaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Tial Mi ankaŭ agos en kolero; ne indulgos Mia okulo, kaj Mi ne kompatos; eĉ se ili krios al Miaj oreloj per laŭta voĉo, Mi ne aŭskultos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Kaj Li vokis al miaj oreloj per laŭta voĉo, dirante: Alproksimiĝu la punantoj de la urbo, kaj ĉiu havu en sia mano sian pereigilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'Kaj jen ses homoj venis per la vojo de la supra pordego, kiu estas turnita norden, kaj ĉiu havis en la mano sian detruilon, kaj inter ili estis unu vestita per tolo, kaj li havis skribilon ĉe siaj lumboj. Ili venis, kaj stariĝis apud la kupra altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'Kaj la majesto de Dio de Izrael leviĝis de la kerubo, sur kiu ĝi estis, al la sojlo de la domo. Kaj Li alvokis la homon, kiu estis vestita per tolo kaj havis skribilon ĉe siaj lumboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'Kaj la Eternulo diris al li: Trairu la urbon Jerusalem, kaj marku per litero Tav la fruntojn de tiuj homoj, kiuj ĝemas kaj malĝojas pri ĉiuj abomenindaĵoj, kiuj estas farataj en la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Kaj al la aliaj Li diris tiel, ke mi povis aŭdi: Iru tra la urbo post li, kaj frapu; via okulo ne indulgu, kaj vi ne kompatu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Maljunulon, junulon, junulinon, infanojn, kaj virinojn eksterme mortigu; sed ĉiun homon, sur kiu estas la litero Tav, ne tuŝu; kaj komencu de Mia sanktejo. Kaj ili komencis de la maljunaj homoj, kiuj estis antaŭ la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Kaj Li diris al ili: Malpurigu la domon, kaj plenigu la kortojn per mortigitoj; eliru! Kaj ili eliris, kaj komencis frapadi en la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'Kiam ili finis la mortigadon kaj mi restis, tiam mi ĵetis min vizaĝaltere, ekkriis, kaj diris: Ho Sinjoro, ho Eternulo! ĉu Vi ekstermos la tutan restaĵon de Izrael, elverŝante Vian koleron sur Jerusalemon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Kaj Li diris al mi: La malpieco de la domo de Izrael kaj de Jehuda estas tre, tre granda, kaj la lando estas plena de sango, kaj la urbo estas plena de maljusteco; ĉar ili diras: La Eternulo forlasis la landon, kaj la Eternulo ne vidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Tial ankaŭ Miaflanke Mia okulo ne indulgos, kaj Mi ne kompatos; ilian agadon Mi metos sur ilian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'Kaj jen la viro, kiu estis vestita per tolo kaj havis skribilon ĉe siaj lumboj, alportis respondon, dirante: Mi faris tion, kion Vi ordonis al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Kaj mi vidis: jen sur la firmamento, kiu estis super la kapoj de la keruboj, io simila al safiro, aspektanta kiel bildo de trono, aperis super ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Kaj Li diris al la viro, vestita per tolo, jene: Eniru inter la radojn sub la kerubon, kaj prenu plenmanojn da ardantaj karboj el inter la keruboj, kaj ĵetu ilin sur la urbon. Kaj li eniris antaŭ miaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'La keruboj staris dekstre de la domo, kiam la viro eniris, kaj nubo plenigis la internan korton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Kaj leviĝis la majesto de la Eternulo de la kerubo al la enirejo de la domo, kaj la domo pleniĝis de la nubo, kaj la korto pleniĝis de brilo de la majesto de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'Kaj bruo de la flugiloj de la keruboj estis aŭdata ĝis la ekstera korto, kiel bruo de Dio, la Plejpotenculo, kiam Li parolas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'Kaj kiam Li ordonis al la viro, vestita per tolo, dirante: Prenu fajron el inter la radoj, el inter la keruboj, kaj ĉi tiu eniris kaj stariĝis apud la rado,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'tiam unu el la keruboj etendis sian manon el inter la keruboj al la fajro, kiu estis inter la keruboj, kaj prenis kaj metis sur la manplatojn de la tolvestito; kaj ĉi tiu prenis kaj eliris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'Kaj ĉe la keruboj montriĝis similaĵo de homa mano sub iliaj flugiloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Kaj mi vidis, jen estas kvar radoj apud la keruboj, po unu rado apud ĉiu kerubo, kaj la aspekto de la radoj estis kiel turkiso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Kaj laŭ aspekto la kvar radoj havis unu formon, kvazaŭ unu rado estus en la alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Irante, ili moviĝadis sur ĉiujn kvar flankojn, ili ne deturniĝadis dum la irado; al la loko, al kiu estis direktita la kapo, ili sekvadis ĝin, ili ne deturniĝadis dum la irado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'Kaj ilia tuta korpo, ilia dorso, iliaj manoj, iliaj flugiloj, kiel ankaŭ la radoj, estis ĉirkaŭe plenaj de okuloj; ĉiuj kvar havis siajn radojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'La radoj estis nomataj turnovento, kiel mi povis tion aŭdi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'Ĉiu havis kvar vizaĝojn: unu vizaĝo estis vizaĝo de kerubo, la dua vizaĝo estis vizaĝo de homo, la tria estis vizaĝo de leono, kaj la kvara estis vizaĝo de aglo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'Kaj leviĝis la keruboj. Tio estis tiu kreitaĵo, kiun mi vidis ĉe la rivero Kebar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'Kaj kiam la keruboj iris, la radoj iradis apud ili; kaj kiam la keruboj levis siajn flugilojn, por leviĝi de la tero, tiam ankaŭ la radoj ne deturniĝadis de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Kiam tiuj staris, ili ankaŭ staris, kaj kiam tiuj leviĝis, ili ankaŭ leviĝadis; ĉar la spirito de la kreitaĵoj estis en ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Kaj la majesto de la Eternulo foriĝis de la sojlo de la domo kaj stariĝis super la keruboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Kaj la keruboj levis siajn flugilojn, kaj suprenflugis de la tero antaŭ miaj okuloj, kaj la radoj kune kun ili; kaj ili stariĝis ĉe la enirejo de la orienta pordego de la domo de la Eternulo; kaj la majesto de Dio de Izrael aperis supre super ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'Tio estis la kreitaĵo, kiun mi vidis sub Dio de Izrael ĉe la rivero Kebar; kaj mi eksciis, ke tio estas keruboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Ĉiu el ili havis kvar vizaĝojn, kaj ĉiu havis kvar flugilojn, kaj similaĵo de homaj manoj estis sub iliaj flugiloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'Kaj la aspekto de iliaj vizaĝoj estis kiel tiuj vizaĝoj, kiujn mi vidis ĉe la rivero Kebar, ilia aspekto kaj ili mem. Ĉiu moviĝis laŭ la direkto de sia vizaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Kaj levis min la spirito, kaj venigis min al la orienta pordego de la domo de la Eternulo, al tiu, kiu rigardas orienten. Kaj jen ĉe la enirejo de la pordego staras dudek kvin homoj, kaj inter ili mi vidas Jaazanjan, filon de Azur, kaj Pelatjan, filon de Benaja, estrojn de la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Kaj Li diris al mi: Ho filo de homo, ĉi tiuj homoj havas malpiajn intencojn kaj donas malbonajn konsilojn en ĉi tiu urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'Ili diras: Ankoraŭ ne baldaŭ; ni konstruu domojn; ĝi estas la kaldrono, kaj ni estas la viando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Tial profetu pri ili, profetu, ho filo de homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'Kaj malleviĝis sur min la spirito de la Eternulo, kaj diris al mi: Diru: Tiele diras la Eternulo: Tiel vi parolis, ho domo de Izrael, kaj la pensojn de via koro Mi scias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Multajn vi mortigis en ĉi tiu urbo, kaj ĝiajn stratojn vi plenigis per mortigitoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Tial tiele diras la Sinjoro, la Eternulo: Viaj mortigitoj, kiujn vi faligis en ĝi, estas la viando, kaj ĝi mem estas la kaldrono; sed vi estos elkondukitaj el ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Glavon vi timas, kaj glavon Mi venigos sur vin, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'Mi elkondukos vin el ĝi kaj transdonos vin en la manojn de fremduloj, kaj Mi faros super vi juĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'De glavo vi falos; ĉe la limoj de Izrael Mi juĝos vin; kaj vi ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'La urbo ne estos por vi kaldrono, nek vi estos en ĝi kiel viando; ĉe la limoj de Izrael Mi juĝos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'Kaj vi ekscios, ke Mi estas la Eternulo, kies leĝojn vi ne sekvis kaj kies decidojn vi ne plenumis, sed vi agis laŭ la maniero de la nacioj, kiuj estas ĉirkaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'Kiam mi eldiris mian profetaĵon, Pelatja, filo de Benaja, mortis; kaj mi ĵetis min vizaĝaltere, kaj ekkriis per laŭta voĉo, kaj diris: Ho Sinjoro, ho Eternulo! Vi faras finon al la restaĵo de Izrael!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Ho filo de homo! al viaj fratoj, jes al viaj fratoj, al viaj parencoj, kaj al la tuta domo de Izrael parolas la loĝantoj de Jerusalem: Foriĝu de la Eternulo, al ni estas donita ĉi tiu lando kiel hereda posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Tial diru: Tiele diras la Sinjoro, la Eternulo: Kvankam Mi forigis ilin al la nacioj kaj disĵetis ilin en diversajn landojn, Mi tamen baldaŭ estos ilia sanktejo en la landoj, kien ili venis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Tial diru: Tiele diras la Sinjoro, la Eternulo: Mi kolektos vin el inter la nacioj, Mi kolektos vin el la landoj, kien vi estas disĵetitaj, kaj Mi donos al vi la landon de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'Kaj kiam ili venos tien, ili forigos el ĝi ĉiujn ĝiajn fiaĵojn kaj ĉiujn ĝiajn abomenindaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'Kaj Mi donos al ili unu koron, kaj novan spiriton Mi enmetos en vin, kaj Mi elprenos el ilia korpo la koron ŝtonan kaj donos al ili koron karnan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'por ke ili sekvu Miajn leĝojn kaj observu Miajn decidojn kaj plenumu ilin; kaj ili estos Mia popolo, kaj Mi estos ilia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Sed al tiuj, kiuj sin fordonas al la fiaĵoj kaj abomenindaĵoj de sia koro, Mi turnos ilian konduton kontraŭ ilian kapon, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Tiam la keruboj levis siajn flugilojn, kaj la radoj estis apud ili; kaj la majesto de Dio de Izrael estis supre super ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'Kaj la majesto de la Eternulo leviĝis el meze de la urbo, kaj haltis sur la monto, kiu estas oriente de la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'Kaj la spirito min levis, kaj venigis min en la vizio kaj en la inspiro de Dio en Ĥaldeujon, al la forkondukitoj. Kaj malaperis de mi la vizio, kiun mi vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'Kaj mi rakontis al la forkondukitoj ĉiujn vortojn de la Eternulo, kiujn Li aperigis al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Ho filo de homo! meze de domo malobeema vi loĝas; ili havas okulojn, por vidi, sed ili ne vidas; ili havas orelojn, por aŭdi, sed ili ne aŭdas; ĉar ili estas domo malobeema.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Tial, ho filo de homo, faru al vi objektojn de migrado, kaj migru tage antaŭ iliaj okuloj, formigru antaŭ iliaj okuloj el via loko en alian lokon; eble ili vidos, ke ili estas domo malobeema.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Kaj elportu viajn necesaĵojn, kaj necesaĵojn de migranto, tage antaŭ iliaj okuloj; kaj vi mem eliru antaŭ iliaj okuloj vespere, kiel eliras migrantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Antaŭ iliaj okuloj trabatu al vi aperturon en la muro kaj eliru tra ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Antaŭ iliaj okuloj metu la necesaĵojn sur la ŝultron, elportu ilin en mallumo, kovru vian vizaĝon, por ke vi ne vidu la teron; ĉar Mi faris vin antaŭsigno por la domo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'Kaj mi agis tiel, kiel estis ordonite al mi: miajn necesaĵojn mi elportis, kiel necesaĵojn de migranto, ĉe la taglumo; kaj vespere mi trabatis al mi per la mano aperturon en la muro, en mallumo mi elportis, kaj levis sur mian ŝultron antaŭ iliaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'Kaj matene aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'Ho filo de homo! ĉu la domo de Izrael, la domo malobeema, ne demandis vin, kion vi faras?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Diru al ili: Tiele diras la Sinjoro, la Eternulo: Ĉi tiu portaĵo koncernas la princon de Jerusalem, kaj la tutan domon de Izrael, kiu estas en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Diru: Mi estas via antaŭsigno: kiel mi agis, tiel oni agos kun ili: en elhejmiĝon, en kaptitecon ili iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'Kaj la princo, kiu estas inter ili, en mallumo prenos siajn aĵojn sur la ŝultron kaj eliros; oni trarompos en la muro aperturon, por elkonduki lin; li kovros sian vizaĝon, por ke li ne vidu per la okulo la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Kaj Mi sternos Mian reton kontraŭ li, kaj li estos kaptita en Mian kaptilon, kaj Mi forkondukos lin en Babelon, en la landon de la Ĥaldeoj; sed li ĝin ne vidos, kvankam tie li mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'Kaj ĉiujn liajn ĉirkaŭantojn, liajn helpantojn, kaj ĉiujn liajn taĉmentojn Mi dispelos al ĉiuj ventoj, kaj Mi elingigos post ili glavon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'Kaj ili ekscios, ke Mi estas la Eternulo, kiam Mi dispelos ilin inter la naciojn kaj disĵetos ilin en la landojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Sed malgrandan nombron el ili Mi restigos de la glavo, malsato, kaj pesto, por ke ili rakontu pri ĉiuj siaj abomenindaĵoj, inter la nacioj, al kiuj ili venos; kaj oni ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'Ho filo de homo! manĝu vian panon kun tremo, kaj trinku vian akvon kun ĉagreno kaj zorgoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'Kaj diru al la popolo de la lando: Tiele diras la Sinjoro, la Eternulo, pri la loĝantoj de Jerusalem, pri la lando de Izrael: Sian panon ili manĝos en zorgoj, kaj sian akvon ili trinkos en teruro; ĉar la lando dezertiĝos de sia abundo pro la maljustaĵoj de ĉiuj siaj loĝantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'Kaj la loĝataj urboj estos ruinigitaj, kaj la lando estos dezertigita; kaj vi ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, 'Ho filo de homo! kian proverbon vi havas en la lando de Izrael, dirantan: Pasos multe da tempo, kaj ĉiu antaŭdiro malaperos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Tial diru al ili: Tiele diras la Sinjoro, la Eternulo: Mi neniigos ĉi tiun proverbon, kaj oni ne plu uzos tian proverbon en Izrael; sed diru al ili: Proksima jam estas la tempo kaj la plenumiĝo de ĉiu antaŭdiro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Ĉar neniu profetaĵo estos plu vana, kaj neniu antaŭdiro estos dusenca en la domo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Ĉar Mi, la Eternulo, parolas; kaj vorto, kiun Mi parolas, plenumiĝos, ne plu estos prokrastata; en via tempo, ho domo malobeema, Mi parolas vorton, kaj Mi ĝin plenumos, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, 'Ho filo de homo! jen la domo de Izrael diras: La profetaĵo, kiun li profetas, venos ankoraŭ post longa tempo; pri tempoj malproksimaj li profetas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Tial diru al ili: Tiele diras la Sinjoro, la Eternulo: Neniu el Miaj vortoj plu prokrastiĝos; vorto, kiun Mi diros, plenumiĝos, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Ho filo de homo! profetu pri la profetoj de Izrael, kiuj profetas, kaj diru al tiuj, kiuj profetas laŭ sia propra bontrovo: Aŭskultu la vorton de la Eternulo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Tiele diras la Sinjoro, la Eternulo: Ve al la senprudentaj profetoj, kiuj gvidas sin per sia propra spirito kaj nenion vidis!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Kiel vulpoj kaj ruinoj estas viaj profetoj, ho Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Vi ne eliras al la breĉoj, nek baras baron ĉirkaŭ la domo de Izrael, por stari en la batalo en la tago de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Ilia vizio estas senenhava, ilia antaŭdiro estas mensogo. Ili diras: La Eternulo diris-sed la Eternulo ilin ne sendis; kaj ili asertas, ke ilia vorto plenumiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Vi vidis ja vizion senenhavan, kaj vi eldiras antaŭdiron mensogan; vi diras: Tiel parolas la Eternulo-kvankam Mi ne parolis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Tial tiele diras la Sinjoro, la Eternulo: Pro tio, ke vi predikas senbaze kaj antaŭdiras malveraĵon, jen Mi iras kontraŭ vin, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'Kaj Mia mano estos kontraŭ la profetoj, kiuj profetas senbaze kaj antaŭdiras malveraĵon; en la konsilo de Mia popolo ili ne estos, kaj en la registro de la domo de Izrael ili ne estos enskribitaj, kaj en la landon de Izrael ili ne venos; kaj vi ekscios, ke Mi estas la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Pro tio, ĝuste pro tio, ke ili erarigas Mian popolon, antaŭdirante pacon, kvankam paco ne estos, kaj kiam la popolo konstruas barilon, ili ŝmiras ĝin per maltaŭga mortero-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'diru al tiuj, kiuj ŝmiras per maltaŭga mortero, ke ĝi defalos; estos pluvego, kaj vi, ŝtonoj de grandega hajlo, falos sur ĝin, kaj forta vento ĝin krevigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'Kaj jen la muro falis; ĉu oni ne diros al vi: Kie estas la mortero, per kiu vi ŝmiris?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Tial tiele diras la Sinjoro, la Eternulo: Mi elpuŝos fortan venton en Mia indigno kaj pluvegon en Mia kolero kaj ŝtonojn de hajlo en Mia furiozo, por ĉion ekstermi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Mi detruos la muron, kiun vi ŝmiris per maltaŭga mortero, Mi disŝutos ĝin sur la teron tiel, ke nudiĝos ĝia fundamento; kaj ĝi disfalos, kaj vi pereos meze de ĝi; kaj vi ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Kaj Mi plene kontentigos Mian koleron sur la muro, kaj sur tiuj, kiuj ŝmiris ĝin per maltaŭga mortero, kaj Mi diros al vi: Jam ne ekzistas la muro, kaj jam ne ekzistas tiuj, kiuj ŝmiris ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'Tiaj estas la profetoj de Izrael, kiuj profetas pri Jerusalem, kaj predikas al ĝi vizion pri paco, kvankam paco ne estos, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'Kaj vi, ho filo de homo, direktu vian vizaĝon al la filinoj de via popolo, kiuj profetas laŭ elpenso de sia koro; kaj profetu pri ili,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'kaj diru: Tiele diras la Sinjoro, la Eternulo: Ve al tiuj, kiuj kudras kusenojn sub ĉiujn kubutojn kaj faras kaptukojn por kapoj de ĉia alteco, por kapti animojn! kaptante la animojn de Mia popolo, vi volas konservi viajn animojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Kaj vi malsanktigas Min antaŭ Mia popolo pro plenmano da hordeo kaj pro peco da pano, mortigante animojn, kiuj ne devas morti, kaj konservante la vivon al tiaj animoj, kiuj ne devas vivi, mensogante al Mia popolo, kiu volonte aŭskultas mensogon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Tial tiele diras la Sinjoro, la Eternulo: Jen Mi iros kontraŭ viajn kusenojn, per kiuj vi kaptas tie la animojn flugemajn, Mi elŝiros ilin el viaj brakoj, kaj forliberigos la animojn, kiujn vi allogas, ke ili flugu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'Kaj Mi disŝiros viajn kaptukojn, kaj savos Mian popolon el viaj manoj, kaj ili ne plu estos kaptotaĵo por viaj manoj; kaj vi ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Ĉar vi mensoge afliktas la koron de virtulo, kiun Mi ne afliktis, kaj vi fortigas la manojn de malvirtulo, por ke li ne returnu sin de sia malbona vojo, per kio li konservus sian vivon-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'tial vi ne plu havos senbazajn viziojn kaj ne faros antaŭdirojn; kaj Mi savos Mian popolon el viaj manoj; kaj vi ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Venis al mi kelkaj el la plejaĝuloj de Izrael, kaj sidiĝis antaŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Ho filo de homo! ĉi tiuj homoj levis siajn idolojn en sian koron, kaj allogilon de sia malpieco ili starigis antaŭ sia vizaĝo; ĉu Mi nun respondu al ili, kiam ili Min demandas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Tial parolu kun ili, kaj diru al ili: Tiele diras la Sinjoro, la Eternulo: Se iu el la domo de Izrael levis siajn idolojn en sian koron kaj starigis antaŭ si la allogilon de sia malpieco, kaj poste venas al la profeto, tiam Mi, la Eternulo, respondos al li tiel, kiel li meritas per sia granda idolisteco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'por ke la domo de Izrael estu kaptata konforme al sia koro, kiun ili defaligis de Mi per ĉiuj siaj idoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Tial diru al la domo de Izrael: Tiele diras la Sinjoro, la Eternulo: Pentu, kaj deturnu vin de viaj idoloj, kaj de ĉiuj viaj abomenindaĵoj deturnu vian vizaĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Ĉar se iu el la domo de Izrael, aŭ el la fremduloj, kiu loĝas ĉe Izrael, defalas de Mi, levas siajn idolojn en sian koron, starigas antaŭ sia vizaĝo la allogilon de sia malpieco, kaj poste venas al la profeto, por fari per li demandojn al Mi, tiam Mi, la Eternulo, respondos al li per Mi mem;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'Mi direktos Mian vizaĝon kontraŭ tiun homon kaj faros lin avertilo kaj ekzemplo, kaj Mi ekstermos lin el inter Mia popolo; kaj vi ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Kaj se la profeto estos delogita kaj ion parolos, tiam Mi, la Eternulo, malsaĝigis tiun profeton, kaj Mi etendos Mian manon sur lin kaj ekstermos lin el inter Mia popolo Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'Tiamaniere ili estos punitaj pro sia malpieco: la puno de la demandanto kaj la puno de la profeto estos egalaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'por ke ili ne plu forerarigu de Mi la domon de Izrael kaj ili ne plu malpurigu sin per ĉiuj siaj krimoj; sed ili estu Mia popolo kaj Mi estu ilia Dio, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Ho filo de homo! se lando pekos kontraŭ Mi, forte kulpiĝante antaŭ Mi, tiam Mi etendos Mian manon sur ĝin, kaj rompos al ĝi la panan apogon, venigos sur ĝin malsaton, kaj ekstermos en ĝi la homojn kaj brutojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'Kaj se meze de ĝi troviĝus tiaj tri homoj, kiel Noa, Daniel, kaj Ijob, ili pro sia virteco savus sian vivon, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Se Mi venigus en la landon sovaĝajn bestojn, por ĝin senhomigi, por ke ĝi fariĝu dezerta kaj neniu povu iri tra ĝi pro la bestoj-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'kiel Mi vivas, diras la Sinjoro, la Eternulo, eĉ tiuj tri homoj en ĝi ne savus la filojn nek filinojn; nur ili mem saviĝus, sed la lando fariĝus dezerta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Aŭ se Mi venigus glavon sur tiun landon, kaj dirus: Glavo, trairu la landon; kaj Mi ekstermus en ĝi homojn kaj brutojn-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'kiel Mi vivas, diras la Sinjoro, la Eternulo, eĉ tiuj tri homoj en ĝi ne savus la filojn nek filinojn; nur ili mem saviĝus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Aŭ se Mi venigus peston sur tiun landon, kaj Mi elverŝus sur ĝin Mian koleron en sango, por ekstermi en ĝi homojn kaj brutojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'kaj Noa, Daniel, kaj Ijob estus en ĝi-kiel Mi vivas, diras la Sinjoro, la Eternulo, ili ne savus filon nek filinon; nur ili pro sia virteco savus sian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Ĉar tiele diras la Sinjoro, la Eternulo: Eĉ se Mi venigus sur Jerusalemon la kvar malbonajn punojn, la glavon, malsaton, sovaĝajn bestojn, kaj peston, por ekstermi en ĝi homojn kaj brutojn-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'tamen restos en ĝi restaĵo da mortevitintaj filoj kaj filinoj, kaj jen ili eliros al vi, kaj vi vidos ilian konduton kaj iliajn agojn, kaj vi konsoliĝos pri la malbono, kiun Mi venigis sur Jerusalemon, pri ĉio, kion Mi venigis sur ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'Kaj ili vin konsolos, kiam vi vidos ilian konduton kaj iliajn agojn, kaj ekscios, ke ne vane Mi faris ĉion, kion Mi faris kontraŭ ĝi, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'Ho filo de homo! por kio taŭgas la ligno de vinberbranĉo inter ĉiuj branĉoriĉaj arboj, kiuj estas inter la arboj de arbaro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Ĉu oni prenas de ĝi pecon, por ion fari el ĝi? ĉu oni faras el ĝi almenaŭ hokon, por pendigi sur ĝi ian objekton?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Jen ĝi estas transdonata al la fajro por forbruligo; ambaŭ finojn formanĝas la fajro, forbrulas ankaŭ la mezo; ĉu ĝi taŭgas por laboro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Jen, kiam ĝi estis ankoraŭ nedifektita, oni ne povis ion fari el ĝi; des pli kiam la fajro ĝin difektis kaj bruligis, ĉu oni povas ion fari el ĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Tial tiele diras la Sinjoro, la Eternulo: Kiel la vinberarbon inter la arboj de la arbaro Mi transdonis al la fajro, ke ĝi ĝin forbruligu, tiel Mi agos kun la loĝantoj de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Mi direktos Mian vizaĝon kontraŭ ilin; el fajro ili eliris, kaj fajro ilin ekstermos; kaj vi ekscios, ke Mi estas la Eternulo, kiam Mi direktos Mian vizaĝon kontraŭ ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'Kaj Mi faros la landon dezerto pro tio, ke ili forte kulpiĝis, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Ho filo de homo, montru al Jerusalem ĝiajn abomenindaĵojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'kaj diru: Tiele diras la Sinjoro, la Eternulo, al Jerusalem: Via deveno kaj via naskiĝlando estas en la lando Kanaana; via patro estas Amorido, kaj via patrino estas Ĥetidino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'Ĉe via naskiĝo, kiam vi estis naskita, oni ne detranĉis vian umbilikon, oni ankaŭ ne lavis vin purige per akvo, ne frotis vin per salo, kaj ne vindis per vindaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Nenies okulo favoris vin, por fari al vi pro kompato unu el tiuj faroj, sed oni elĵetis vin sur la kampon pro abomeno kontraŭ vi en la tago, kiam vi estis naskita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Mi preteriris preter vi, kaj Mi vidis, ke vi baraktas en via sango, kaj Mi diris al vi en via sango: Vivu; jes, Mi diris al vi en via sango: Vivu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'Mi grandigis vin, kiel kampan kreskaĵon; vi fariĝis plena kaj granda, vi fariĝis tute bela; viaj mamoj formiĝis, viaj haroj abunde kreskis; sed vi estis nuda kaj nekovrita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Mi preteriris preter vi kaj ekvidis vin, kaj Mi vidis, ke estas via tempo, la tempo de amo; kaj Mi etendis Mian mantelon sur vin kaj kovris vian nudecon; kaj Mi ĵuris al vi, kaj Mi faris interligon kun vi, diras la Sinjoro, la Eternulo, kaj vi fariĝis Mia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Mi lavis vin per akvo. Mi forlavis de vi vian sangon, kaj Mi ŝmiris vin per oleo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'Mi vestis vin per brodita vesto, sur viajn piedojn Mi metis delikatledajn ŝuojn, Mi zonis vin per bisino, kaj Mi kovris vin per silka kovrotuko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'Mi ornamis vin per ornamaĵoj, Mi metis braceletojn sur viajn manojn, kaj kolĉenon sur vian kolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'Mi metis nazringon sur vian nazon, kaj orelringojn sur viajn orelojn, kaj belan kronon sur vian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'Vi ornamiĝis per oro kaj arĝento, viaj vestoj estis el bisino, silko, kaj broditaĵo; plej delikatan farunon, mielon, kaj oleon vi manĝis; kaj vi fariĝis tre kaj tre bela kaj atingis reĝecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Kaj disvastiĝis via renomo inter la nacioj pro via beleco, ĉar ĝi estis perfekta per la ornamaĵo, kiun Mi metis sur vin, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Sed vi fidis vian belecon, kaj vi komencis malĉasti, apogante vin sur via renomo, kaj vi malĉastis kun ĉiu pasanto, fordonante vin al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Vi prenis viajn vestojn kaj faris al vi mikskolorajn oferaltaĵojn, kaj sur ili vi malĉastis, kiel neniam estis kaj neniam estos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Vi prenis viajn ornamaĵojn el oro kaj el arĝento, kiujn Mi donis al vi, kaj vi faris al vi bildojn de virseksuloj kaj malĉastis kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'Vi prenis viajn broditajn vestojn kaj kovris per tio ilin, kaj Mian oleon kaj Mian incenson vi donis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'Mian panon, kiun Mi donis al vi, la plej delikatan farunon, oleon, kaj mielon, per kiuj Mi nutris vin, vi metis antaŭ ilin kiel agrablan odoraĵon. Jes, tiel estis, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Vi prenis viajn filojn kaj viajn filinojn, kiujn vi naskis al Mi, kaj vi buĉis ilin al ili kiel manĝaĵon. Ĉu malgranda estas via malĉasteco?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'Vi buĉis Miajn infanojn kaj pasigis ilin tra fajro por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'Kaj en ĉiuj viaj abomenindaĵoj kaj malĉastaĵoj vi ne rememoris la tagojn de via juneco, kiam vi estis nuda kaj nekovrita, baraktanta en via sango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'Kaj post ĉiuj viaj malbonagoj (ho ve, ve al vi! diras la Sinjoro, la Eternulo)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'vi konstruis al vi malĉastejon, kaj faris al vi fialtaĵojn sur ĉiu strato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'En la komenco de ĉiu vojo vi konstruis viajn fialtaĵojn, vi abomenindigis vian belecon, vi etendis viajn piedojn al ĉiu pasanto, kaj vi malĉastis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Vi malĉastis kun la filoj de Egiptujo, viaj grandkorpaj najbaroj, kaj vi multe malĉastis, kolerigante Min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Kaj jen Mi etendis Mian manon kontraŭ vin kaj malgrandigis vian destinitaĵon, kaj Mi transdonis vin al la volo de viaj malamikinoj, la filinoj de Filiŝtujo, kiuj hontis pri via malvirta konduto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Kaj vi malĉastis kun la filoj de Asirio, ne povante satiĝi; vi malĉastis kun ili, kaj tamen ne kontentiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'Vi multigis viajn malĉastaĵojn ĝis la lando de komercado, Ĥaldeujo, sed ankaŭ tio vin ne kontentigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Per kio Mi povas purigi vian koron, diras la Sinjoro, la Eternulo, se vi faras ĉion ĉi tion, farojn de plej senhonta malĉastistino?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'Kiam vi aranĝis viajn malĉastejojn ĉe la komenco de ĉiu vojo kaj faris viajn fialtaĵojn sur ĉiu strato, vi estis ne kiel malĉastistino, kiu ŝatas donacojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'sed kiel malĉastanta virino, kiu anstataŭ sia edzo akceptas fremdulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Al ĉiuj malĉastistinoj oni donas donacojn, sed vi mem donas viajn donacojn al ĉiuj viaj amantoj, kaj vi subaĉetas ilin, ke ili de ĉiuj flankoj venu malĉasti kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'Ĉe via malĉastado fariĝas kun vi la malo de tio, kion oni vidas ĉe aliaj virinoj: oni ne postkuras vin por malĉastado, sed vi mem pagas, kaj al vi oni ne donas pagon; tiamaniere vi estas la malo de aliaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Tial, ho malĉastistino, aŭskultu la vorton de la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'Tiele diras la Sinjoro, la Eternulo: Pro tio, ke vi malŝparas vian metalon kaj via nudeco estas malkovrata en via malĉastado al viaj amistoj kaj al ĉiuj viaj abomenindaj idoloj, kaj pro la sango de viaj infanoj, kiujn vi fordonas al ili-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'pro tio Mi kolektos ĉiujn viajn amistojn, kun kiuj vi ĝuis, kaj ĉiujn, kiujn vi amis, kaj ĉiujn, kiujn vi malamis, kaj Mi kolektos ilin kontraŭ vi de ĉirkaŭe, kaj Mi malkovros antaŭ ili vian nudecon, kaj ili vidos vian tutan hontindaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'Kaj Mi juĝos vin laŭ la juĝoj kontraŭ adultulinoj kaj kontraŭ sangoverŝantinoj, kaj Mi transdonos vin al sangoverŝo kruela kaj severa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'Mi transdonos vin en iliajn manojn, kaj ili detruos vian malĉastejon kaj disbatos viajn fialtaĵojn, ili deprenos de vi viajn vestojn, prenos viajn ornamaĵojn, kaj restigos vin nuda kaj nekovrita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'Kaj ili venigos kontraŭ vin homamason, kiu mortigos vin per ŝtonoj kaj dishakos per siaj glavoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'Kaj ili forbruligos viajn domojn per fajro, kaj faros al vi juĝon antaŭ la okuloj de multaj virinoj; kaj Mi ĉesigos vian malĉastadon, kaj vi ne plu donos donacojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Mi kontentigos sur vi Mian koleron, kaj Mia severeco trankviliĝos sur vi tiel, ke Mi trankviliĝos kaj ne plu koleros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Pro tio, ke vi ne rememoris la tagojn de via juneco, sed incitis Min per ĉio tio, Mi ankaŭ metos vian konduton sur vian kapon, diras la Sinjoro, la Eternulo, por ke vi ne plu faru la malĉastaĵon kun ĉiuj viaj abomenindaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Jen ĉiu proverbisto diros pri vi proverbon: Kia la patrino, tia la filino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Vi estas filino de via patrino, kiu malŝatis sian edzon kaj siajn infanojn, kaj vi estas fratino de viaj fratinoj, kiuj malŝatis siajn edzojn kaj siajn infanojn. Via patrino estas Ĥetidino, kaj via patro estas Amorido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Via pli maljuna fratino estas Samario kun siaj filinoj, kiu loĝas maldekstre de vi; kaj via pli juna fratino, kiu loĝas dekstre de vi, estas Sodom kun siaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Sed eĉ ne laŭ ilia vojo vi iris, kaj ne iliajn abomenindaĵojn vi faris; tio estis malmulta por vi, kaj vi malboniĝis pli ol ili en ĉiuj viaj agoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Kiel Mi vivas, diras la Sinjoro, la Eternulo, via fratino Sodom kaj ŝiaj filinoj ne faris tion, kion faris vi kaj viaj filinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Jen kio estis la kulpo de via fratino Sodom: malmodesteco, trosatiĝo per manĝado, kaj senzorgeco, kiun havis ŝi kaj ŝiaj filinoj; kaj la manon de malriĉulo kaj senhavulo ŝi ne subtenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'Kaj ili fieriĝis kaj faris abomenindaĵon antaŭ Mi, kaj Mi forpuŝis ilin, kiam Mi tion vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Samario ne faris eĉ duonon de viaj pekoj; vi faris pli da abomenindaĵoj, ol ili; per ĉiuj viaj abomenindaĵoj, kiujn vi faris, vi faris viajn fratinojn preskaŭ virtulinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'Tial ankaŭ vi nun portu vian malhonoron, kiun vi kondamnis en viaj fratinoj, pro viaj pekoj, per kiuj vi abomenindiĝis pli ol ili; ili estas virtulinoj en komparo kun vi; hontu kaj portu vian malhonoron, ĉar vi kvazaŭ pravigis viajn fratinojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Tamen kiam Mi revenigos iliajn forkaptitojn, la forkaptitojn de Sodom kaj de ŝiaj filinoj kaj la forkaptitojn de Samario kaj de ŝiaj filinoj, tiam Mi revenigos ankaŭ viajn forkaptitojn kune kun ili,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'por ke vi portu vian malhonoron kaj hontu pri ĉio, kion vi faris, estante konsolo por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Viaj fratinoj, Sodom kaj ŝiaj filinoj revenos al sia antaŭa stato, kaj Samario kaj ŝiaj filinoj revenos al sia antaŭa stato; ankaŭ vi kaj viaj filinoj revenos al via antaŭa stato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Ĉu via fratino Sodom ne estis objekto de rezonado en via buŝo en la tempo de via fiereco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'antaŭ ol elmontriĝis via malboneco, kiel en la tempo de la malhonoro de la filinoj de Sirio kaj ĉiuj ĝiaj ĉirkaŭaĵoj, kaj de la filinoj de Filiŝtujo, kiuj malestimis vin ĉirkaŭe?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Suferu do pro via malĉasteco kaj pro viaj abomenindaĵoj, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Ĉar tiele diras la Sinjoro, la Eternulo: Mi agos kun vi tiel, kiel vi agis, malŝatante la ĵuron kaj rompante la interligon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Tamen Mi rememoros Mian interligon kun vi en la tempo de via juneco, kaj Mi restarigos kun vi interligon eternan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Kaj vi rememoros vian konduton, kaj hontos, kiam vi akceptos al vi viajn plej maljunajn kaj plej junajn fratinojn; kaj Mi donos ilin al vi kiel filinojn, sed ne pro via interligo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'Mi restarigos Mian interligon kun vi, kaj vi ekscios, ke Mi estas la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'por ke vi memoru kaj hontu, kaj por ke vi ne plu povu malfermi vian buŝon pro honto, kiam Mi pardonos al vi ĉion, kion vi faris, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'Ho filo de homo, proponu enigmon kaj parabolon al la domo de Izrael;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'kaj diru: Tiele diras la Sinjoro, la Eternulo: Granda aglo kun grandaj flugiloj kaj grandaj korpomembroj, plene kovrita de diverskoloraj plumoj, venis sur Lebanonon kaj prenis pinton de cedro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'ĝi deŝiris ĝian supran junan branĉeton kaj alportis ĝin en la landon de komercado kaj kuŝigis ĝin en urbo de komercistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Ĝi prenis iom el la semoj de la lando, plantis ĝin sur prisemebla kampo, aranĝis ĝin apud abunda akvo, tre singarde.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'Kaj ĝi elkreskis kaj fariĝis vasta vinberkreskaĵo kun malalta trunko; ĝiaj flankobranĉoj fleksiĝis al ĝi malsupren, kaj ĝiaj radikoj estis sub ĝi; kaj ĝi fariĝis vinbertrunko kaj elkreskigis branĉojn kaj branĉetojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Kaj estis alia granda aglo kun grandaj flugiloj kaj abundaj plumoj; kaj jen tiu vinbertrunko tiris sin per siaj radikoj al ĝi kaj etendis al ĝi siajn branĉojn, por ke ĝi trinkigu ĝin, de la bedoj, kie ĝi estis plantita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'Sur bona kampo, apud abunda akvo, ĝi estis plantita, por ke ĝi elkreskigu branĉojn kaj portu fruktojn kaj estu belega vinbertrunko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Diru: Tiele diras la Sinjoro, la Eternulo: Ĉu ĝi havos sukceson? oni ja elŝiros ĝiajn radikojn, oni deŝiros ĝiajn fruktojn, kaj ĝi velkos; ĉiuj ĝiaj elkreskintaj folioj velkos, kaj oni ne bezonos grandan forton kaj multon da homoj, por deŝiri ĝin de ĝiaj radikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Kaj jen, kvankam ĝi estas plantita, ĉu ĝi havos sukceson? ĉu ĝi ne tute forvelkos, kiam la orienta vento ĝin tuŝos? ĝi forvelkos sur la bedoj, kie ĝi kreskis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'Diru do al la domo malobeema: Ĉu vi ne scias, kion tio signifas? Diru: Jen venis la reĝo de Babel en Jerusalemon, kaj prenis ĝian reĝon kaj ĝiajn eminentulojn kaj venigis ilin al si en Babelon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'kaj li prenis iun el la reĝa idaro kaj faris kun li interligon kaj prenis de li ĵuron, kaj la potenculojn de la lando li forprenis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'por ke la regno estu humila kaj ne altigu sin, kaj por ke ĝi konservu lian interligon kaj povu sin teni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Sed tiu defalis de li, kaj sendis siajn senditojn en Egiptujon, por ke oni donu al li ĉevalojn kaj multe da homoj. Ĉu li povas havi sukceson? ĉu povas saviĝi tiu, kiu tiel agas? ĉu li saviĝos, se li rompis la interligon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Kiel Mi vivas, diras la Sinjoro, la Eternulo, sur la loko de tiu reĝo, kiu faris lin reĝo kaj antaŭ kiu li malŝatis sian ĵuron kaj rompis lian interligon, ĉe li, en Babel, li mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Kaj Faraono kun granda forto kaj multenombra anaro ne helpos al li en la milito, kiam estos surŝutitaj remparoj kaj estos konstruitaj bastionoj, por ekstermi multe da homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Kaj ĉar li malŝatis la ĵuron kaj rompis la interligon, ĉar li donis sian manon kaj tamen faris ĉion ĉi tion, tial li ne saviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Tial tiele diras la Sinjoro, la Eternulo: Kiel Mi vivas, Mian ĵuron, kiun li malŝatis, kaj Mian interligon, kiun li rompis, Mi metos sur lian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Mi ĵetos sur lin Mian reton, kaj li kaptiĝos en Mian kaptilon; kaj Mi forkondukos lin en Babelon, kaj tie Mi faros sur li juĝon pro la krimo, kiun li faris kontraŭ Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'Kaj ĉiuj liaj forkurintoj el ĉiuj liaj taĉmentoj falos de glavo, kaj la restintoj estos dispelitaj al ĉiuj ventoj; kaj vi ekscios, ke Mi, la Eternulo, tion diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'Tiele diras la Sinjoro, la Eternulo: Mi mem prenos branĉon de alta cedro kaj metos ĝin; el la supraj junaj branĉetoj Mi deŝiros la plej delikatan, kaj Mi plantos ĝin sur monto alta kaj eminenta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'Sur la alta monto de Izrael Mi ĝin plantos, kaj ĝi elkreskigos branĉojn kaj donos fruktojn kaj fariĝos belega cedro; kaj loĝos sub ĝi ĉiaspecaj birdoj, ĉiaspecaj flugiluloj nestos en la ombro de ĝiaj branĉoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'Kaj ekscios ĉiuj arboj de la kampo, ke Mi, la Eternulo, malaltigas arbon altan kaj altigas arbon malaltan, ke Mi velkigas arbon sukoplenan kaj verdigas arbon velkintan; Mi, la Eternulo, tion diris, kaj Mi tion plenumos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'Kial vi uzas ĉe vi en la lando de Izrael ĉi tiun proverbon kaj diras: La patroj manĝis nematurajn vinberojn, kaj la dentoj de la filoj agaciĝis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Kiel Mi vivas, diras la Sinjoro, la Eternulo, neniu plu uzos ĉe vi tiun proverbon en Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Jen ĉiuj animoj apartenas al Mi: kiel la animo de la patro, tiel ankaŭ la animo de la filo apartenas al Mi; tiu animo, kiu pekas, ĝi mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Sed se iu estas virta kaj agas laŭleĝe kaj juste;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'ne manĝas sur la montoj kaj ne levas siajn okulojn al la idoloj de la domo de Izrael, ne malpurigas la edzinon de sia proksimulo kaj ne alproksimiĝas al virino en la tempo de ŝia monataĵo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'neniun perfortas, redonas al la ŝuldanto lian garantiaĵon, ne faras rabon, donas sian panon al malsatulo kaj nudulon kovras per vesto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'ne donas kontraŭ procentegoj kaj ne prenas troprofiton, detenas sian manon de maljustaĵo, faras inter homo kaj homo juĝon justan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'sekvas Miajn leĝojn kaj observas Miajn ordonojn, por plenumi ilin ĝuste: tiu estas virtulo, kaj li certe vivos, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'Sed se li naskigis filon, kiu estas rabisto, verŝas sangon, aŭ faras ion similan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'kaj ĉion diritan li mem ne faras, sed li manĝas sur la montoj, malpurigas la edzinon de sia proksimulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'perfortas malriĉulon kaj senhavulon, faras rabadon, ne redonas garantiaĵon, levas siajn okulojn al idoloj, faras abomenindaĵon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'donas kontraŭ procentegoj, prenas troprofiton: ĉu tia povas vivi? li ne devas vivi: ĉar li faras ĉiujn tiujn abomenindaĵojn, li devas morti; lia sango estu sur li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'Sed jen li naskigis filon, kiu vidas ĉiujn pekojn de sia patro, kiujn ĉi tiu faras, kaj li timas, kaj ne faras ion similan:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'sur la montoj li ne manĝas, siajn okulojn li ne levas al la idoloj de la domo de Izrael, la edzinon de sia proksimulo li ne malpurigas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'li neniun perfortas, garantiaĵon ne prenas, rabadon ne faras, sian panon li donas al malsatulo kaj nudulon li kovras per vesto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'de premado de malriĉulo detenas sian manon, procentegon kaj troprofiton ne prenas, plenumas Miajn ordonojn kaj sekvas Miajn leĝojn: li ne mortos pro la pekoj de sia patro, sed li nepre vivos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Kaj lia patro, ĉar li faris kruelaĵojn, prirabis fraton, kaj faris inter sia popolo tion, kio estas nebona: li mortos pro siaj malbonagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Vi diros: Kial filo ne estas punata pro la malbonagoj de la patro? La filo agis ĝuste kaj juste, observis ĉiujn Miajn leĝojn kaj plenumis ilin; tial li nepre vivos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Tiu animo, kiu pekas, ĝi mortos; filo ne suferos pro la malbonagoj de la patro, kaj patro ne suferos pro la malbonagoj de la filo; la virteco de virtulo estos sur li, kaj la malpieco de malpiulo estos sur li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Sed se malpiulo deturnas sin de ĉiuj siaj pekoj, kiujn li faris, kaj li observos ĉiujn Miajn leĝojn kaj agados ĝuste kaj juste, tiam li vivos, li ne mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Ĉiuj liaj malbonagoj, kiujn li faris, ne estos rememorataj; pro siaj bonaj agoj, kiujn li faris, li vivos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Ĉu Mi deziras la morton de malpiulo? diras la Sinjoro, la Eternulo; kiam li deturnos sin de sia konduto, li ja vivos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Kaj se virtulo deturnos sin de sia virteco kaj faros malbonagojn, agos simile al ĉiuj abomenindaĵoj, kiujn faras malpiulo: ĉu li tiam povas vivi? Ĉiuj bonaj agoj, kiujn li faris, ne estos rememorataj; pro siaj krimoj, kiujn li faris, kaj pro siaj pekoj, kiujn li faris, pro ili li mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Vi diros: Ne ĝusta estas la maniero de agado de la Sinjoro. Aŭskultu do, ho domo de Izrael: Ĉu Mia maniero de agado estas ne ĝusta? Ne, via konduto estas ne ĝusta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Kiam virtulo deturnas sin de sia virteco kaj faras malbonagojn kaj mortas pro tio, tiam li mortas pro siaj malbonagoj, kiujn li faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Kaj kiam malpiulo deturnas sin de siaj malbonagoj, kiujn li faris, kaj li agas ĝuste kaj juste, tiam li donas vivon al sia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Ĉar li rigardis, kaj retiris sin de ĉiuj siaj malbonagoj, kiujn li faris, tial li nepre vivos, li ne mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'La domo de Izrael diros: Ne ĝusta estas la agadmaniero de la Sinjoro. Ĉu Mia agadmaniero estas ne ĝusta, ho domo de Izrael? Ne, via agadmaniero estas ne ĝusta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'Tial Mi juĝos vin, ho domo de Izrael, ĉiun laŭ lia konduto, diras la Sinjoro, la Eternulo. Pentu kaj retiru vin de ĉiuj viaj krimoj, por ke la malbonagoj ne estu por vi falilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Forĵetu de vi ĉiujn viajn krimojn, per kiuj vi pekis, kaj faru al vi novan koron kaj novan spiriton. Kial vi mortu, ho domo de Izrael?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Ĉar Mi ne deziras la morton de mortanto, diras la Sinjoro, la Eternulo; konvertu vin kaj vivu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'Kaj vi eksonigu funebran kanton pri la princoj de Izrael;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'kaj diru: Kial via patrino kiel leonino kuŝis inter leonoj, inter leonidoj edukis siajn idojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'Ŝi edukis unu el siaj idoj, ĝi fariĝis leonido, kaj ĝi lernis disŝiri kaptaĵon, ĝi manĝis homojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'Kaj aŭdis pri ĝi popoloj; ĝi estas kaptita en ilian kavon, kaj ili forkondukis ĝin en ĉenoj en la landon Egiptan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Kiam ŝi vidis, ke ŝia espero malaperis, ŝi prenis alian el siaj idoj kaj faris ĝin leonido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Irante meze de leonoj, ĝi fariĝis leonido, lernis disŝiri kaptaĵon, manĝis homojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'Ĝi difektis iliajn loĝejojn, dezertigis iliajn urbojn; kaj la lando, kun ĉio, kio estis en ĝi, eksentis teruron antaŭ la voĉo de ĝia blekegado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Tiam kolektiĝis kontraŭ ĝi la popoloj el la ĉirkaŭaj landoj kaj ĵetis sur ĝin sian reton, kaj ĝi kaptiĝis en ilian kavon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'Kaj oni metis ĝin en ĉenoj en kaĝegon kaj forportis ĝin al la reĝo de Babel; kaj oni metis ĝin en fortikigitan lokon, por ke oni ne plu aŭdu ĝian voĉon sur la montoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Via patrino estis, simile al vi, kiel vinberkreskaĵo, plantita apud akvo, fruktoriĉa kaj branĉoriĉa pro la abundo de akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'Kaj elkreskis al ĝi branĉoj tiel fortikaj, ke ili taŭgis kiel sceptroj de regantoj, kaj alte leviĝis ĝia trunko inter la branĉaro; kaj ĝi estis bone videbla pro sia alteco kaj pro la multo de siaj branĉoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Sed en kolero oni ĝin elŝiris kaj ĵetis sur la teron, kaj la orienta vento elsekigis ĝiajn fruktojn; derompiĝis kaj velksekiĝis la fortikaj branĉoj, fajro ilin konsumis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'Kaj nun ĝi estas transplantita en la dezerton, en landon sekan kaj senakvan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'Kaj eliris fajro el unu el ĝiaj branĉoj kaj forkonsumis ĝiajn fruktojn; kaj jam ne restis sur ĝi fortika branĉo por sceptro de regado. Funebra kanto tio estas, kaj ĝi restos funebra kanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'En la sepa jaro, en la deka tago de la kvina monato, venis kelkaj el la plejaĝuloj de Izrael, por demandi la Eternulon, kaj ili sidiĝis antaŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'Ho filo de homo, parolu al la plejaĝuloj de Izrael, kaj diru al ili: Tiele diras la Sinjoro, la Eternulo: Ĉu por demandi Min vi venis? kiel Mi vivas, Mi ne respondos al via demando, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Se vi volas juĝi ilin, se vi volas juĝi, ho filo de homo, tiam montru al ili la abomenindaĵojn de iliaj patroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'kaj diru al ili: Tiele diras la Sinjoro, la Eternulo: En la tago, kiam Mi elektis Izraelon kaj levis Mian manon al la idaro de la domo de Jakob, kiam Mi konigis Min al ili en la lando Egipta, kaj, levante al ili Mian manon, diris: Mi estas la Eternulo, via Dio-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'en tiu tago Mi per levo de la mano promesis al ili, ke Mi elkondukos ilin el la lando Egipta en landon, kiun Mi elektis por ili, kie fluas lakto kaj mielo, kaj kiu estas la plej bela el ĉiuj landoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'Kaj Mi diris al ili: Ĉiu el vi forĵetu la fiaĵojn, kiuj estas antaŭ liaj okuloj, kaj ne malpurigu vin per la idoloj de Egiptujo: Mi, la Eternulo, estas via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Sed ili malobeis Min kaj ne volis aŭskulti Min, kaj neniu el ili forĵetis la fiaĵojn, kiuj estis antaŭ liaj okuloj, kaj la idolojn de Egiptujo ili ne forlasis. Kaj Mi intencis elverŝi sur ilin Mian koleron, kontentigi sur ili Mian indignon meze de la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Tamen pro Mia nomo, por ke ĝi ne malsanktiĝu antaŭ la okuloj de la nacioj, inter kiuj ili estis kaj antaŭ kies okuloj Mi konigis Min al ili, Mi agis tiel, ke Mi elkondukis ilin el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'Kaj Mi elkondukis ilin el la lando Egipta kaj venigis ilin en la dezerton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'Kaj Mi donis al ili Miajn leĝojn, kaj Mi konigis al ili Miajn decidojn, per kies plenumado homo vivas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Ankaŭ Miajn sabatojn Mi donis al ili, por ke ili estu signo inter Mi kaj ili, por ke ili sciu, ke Mi, la Eternulo, ilin sanktigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Sed la domo de Izrael ribelis kontraŭ Mi en la dezerto: ili ne sekvis Miajn leĝojn, kaj ili malŝatis Miajn decidojn, per kies plenumado homo vivas, kaj Miajn sabatojn ili tre malsanktigis. Kaj Mi intencis elverŝi sur ilin Mian koleron en la dezerto, por ekstermi ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Tamen Mi agis pro Mia nomo, por ke ĝi ne malsanktiĝu antaŭ la okuloj de la nacioj, antaŭ kies okuloj Mi elkondukis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Mi levis kontraŭ ilin Mian manon en la dezerto, por ne venigi ilin en la landon, kiun Mi destinis, en kiu fluas lakto kaj mielo kaj kiu estas la plej bela el ĉiuj landoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'pro tio, ke ili malŝatis Miajn decidojn, ne sekvis Miajn leĝojn, kaj malsanktigis Miajn sabatojn; ĉar ilia koro sekvis iliajn idolojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Tamen Mia okulo indulgis ilin, por ne pereigi ilin, kaj Mi ne faris al ili finon en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Kaj Mi diris al iliaj infanoj en la dezerto: Ne sekvu la leĝojn de viaj patroj, ne observu iliajn morojn, kaj ne malpurigu vin per iliaj idoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Mi, la Eternulo, estas via Dio; Miajn leĝojn sekvu, kaj Miajn decidojn observu, kaj plenumu ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'kaj tenu sankte Miajn sabatojn, por ke ili estu signo inter Mi kaj vi, por ke vi sciu, ke Mi, la Eternulo, estas via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Sed la infanoj malobeis Min: Miajn leĝojn ili ne sekvis, ili ne observis kaj ne plenumis Miajn decidojn, per kies plenumado homo vivas, malsanktigis Miajn sabatojn. Kaj Mi intencis elverŝi Mian koleron sur ilin, kontentigi Mian indignon sur ili en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Tamen Mi retiris Mian manon kaj agis pro Mia nomo, por ke ĝi ne malsanktiĝu antaŭ la okuloj de la nacioj, antaŭ kies okuloj Mi elkondukis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Sed, levinte Mian manon, Mi diris al ili en la dezerto, ke Mi disĵetos ilin inter la naciojn kaj dispelos ilin en diversajn landojn');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'pro tio, ke ili ne plenumis Miajn decidojn, malŝatis Miajn leĝojn, malsanktigis Miajn sabatojn, kaj direktis siajn okulojn al la idoloj de siaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Tial Mi donis al ili instituciojn nebonajn, kaj aranĝojn, per kiuj ili ne povas vivi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'kaj Mi permesis al ili malpurigi sin per siaj oferoj, trairigante tra fajro ĉiun unuenaskiton, por ke Mi ruinigu ilin, por ke ili eksciu, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Tial parolu al la domo de Izrael, ho filo de homo, kaj diru al ili, ke tiele diras la Sinjoro, la Eternulo: Ankoraŭ plue viaj patroj malhonoris Min per la pekoj, kiujn ili faris kontraŭ Mi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Mi venigis ilin en la landon, pri kiu Mi per levo de mano promesis, ke Mi donos ĝin al ili; sed ĉie, kie ili vidis ian altan monteton aŭ ian branĉoriĉan arbon, ili buĉis tie siajn oferojn kaj alportis tien siajn kolerigantajn donojn, metis tien siajn agrablajn odoraĵojn kaj verŝis tie siajn verŝoferojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'Kaj Mi diris al ili: Kio estas tiu altaĵo, sur kiun vi iras? Kaj oni donis al tiu loko la nomon Altaĵo ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Tial diru al la domo de Izrael: Tiele diras la Sinjoro, la Eternulo: Vi malpurigas vin konforme al la konduto de viaj patroj, kaj vi malĉaste sekvas iliajn abomenindaĵojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'alportante viajn donacojn, trairigante viajn infanojn tra fajro, vi malpurigas vin per ĉiuj viaj idoloj ĝis la nuna tempo; ĉu do Mi povas respondi al viaj demandoj, ho domo de Izrael? Kiel Mi vivas, diras la Sinjoro, la Eternulo, Mi ne respondos al viaj demandoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'Kaj kio venas en vian kapon, kiam vi diras: Ni estu kiel la nacioj, kiel la gentoj de la landoj, servante al ligno kaj al ŝtonoj-tio ne efektiviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Kiel Mi vivas, diras la Sinjoro, la Eternulo, per forta mano, per etendita brako, kaj per elverŝado de kolero Mi reĝos super vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'kaj per forta mano, per etendita brako, kaj per elverŝado de kolero, Mi elkondukos vin el inter la popoloj, kaj kolektos vin el la landoj, kien vi estas disĵetitaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'kaj Mi venigos vin en la dezerton de la popoloj, kaj tie Mi procesos kun vi vizaĝon kontraŭ vizaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Kiel Mi procesis kun viaj patroj en la dezerto de la lando Egipta, tiel Mi procesos kun vi, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'Kaj Mi pasigos vin sub vergo kaj venigos vin en la ligilojn de la interligo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'kaj Mi eligos el inter vi tiujn, kiuj ribelis kaj pekis kontraŭ Mi, el la lando de ilia loĝado Mi elirigos ilin, sed en la landon de Izrael ili ne eniros. Kaj vi ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Kaj pri vi, ho domo de Izrael, tiele diras la Sinjoro, la Eternulo: Ĉiu el vi iru kaj servu al siaj idoloj, se vi ne aŭskultas Min; sed Mian sanktan nomon ne plu malhonoru per viaj donoj kaj per viaj idoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Ĉar sur Mia sankta monto, sur la alta monto de Izrael, diras la Sinjoro, la Eternulo, tie servos al Mi la tuta domo de Izrael, ĉiuj, kiuj estos en la lando; tie Mi akceptos ilin favore, kaj tie Mi akceptos viajn oferdonojn kaj la unuaaĵojn de viaj donoj, kun ĉio, kion vi dediĉas al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Mi akceptos vin favore ĉe la agrabla odoraĵo, kiam Mi elkondukos vin el inter la popoloj, kaj kolektos vin el la landoj, kien vi estis disĵetitaj; kaj Mi sanktiĝos per vi antaŭ la okuloj de la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'Kaj vi ekscios, ke Mi estas la Eternulo, kiam Mi venigos vin en la landon de Izrael, en la landon, pri kiu Mi levis Mian manon, ke Mi donos ĝin al viaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'Kaj vi rememoros tie vian konduton kaj ĉiujn viajn agojn, per kiuj vi malpurigis vin, kaj vi sentos abomenon antaŭ vi mem kontraŭ ĉiuj malbonagoj, kiujn vi faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'Kaj vi ekscios, ke Mi estas la Eternulo, kiam Mi agos kun vi pro Mia nomo, ne konforme al via malbona konduto kaj al viaj pereigaj agoj, ho domo de Izrael, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, 'Ho filo de homo, direktu vian vizaĝon al la vojo suden, prediku al la sudo, kaj profetu pri la arbaro de la suda kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, 'Kaj diru al la suda arbaro: Aŭskultu la vorton de la Eternulo! Tiele diras la Sinjoro, la Eternulo: Jen Mi ekbruligos en vi fajron, kaj ĝi formanĝegos en vi ĉiun arbon verdan kaj ĉiun arbon velksekiĝintan; ne estingiĝos la flamanta fajro, kaj forbrulos ĉio, kio troviĝas de la sudo ĝis la nordo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, 'Kaj ĉiu karno vidos, ke Mi, la Eternulo, tion ekbruligis tiel, ke oni ne povas estingi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, 'Kaj mi diris: Ho Sinjoro, ho Eternulo! ili diras pri mi: Li parolas ja nur parabolojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, 'Ho filo de homo, turnu vian vizaĝon al Jerusalem, prediku pri la sanktaĵoj, kaj profetu pri la lando de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'Kaj diru al la lando de Izrael: Tiele diras la Eternulo: Jen Mi iras kontraŭ vin, Mi eltiros Mian glavon el ĝia ingo, kaj Mi ekstermos inter vi virtulojn kaj malpiulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Ĉar Mi ekstermos inter vi virtulojn kaj malpiulojn, tial Mia glavo eliros el sia ingo kontraŭ ĉiun karnon de la sudo ĝia la nordo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'Kaj ĉiu karno ekscios, ke Mi, la Eternulo, eltiris Mian glavon el ĝia ingo, kaj ĝi ne plu revenos tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'Kaj vi, ho filo de homo, ĝemu, kun doloro de la lumboj, kaj maldolĉe ĝemu antaŭ iliaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'Kaj kiam ili demandos vin, pro kio vi ĝemas, respondu: Pro la sciigo, kiu venis, kaj de kiu ĉiu koro disfandiĝos, ĉiuj manoj senfortiĝos, ĉiu spirito senkuraĝiĝos, kaj ĉiuj genuoj fariĝos kiel akvo; jen tio venas kaj plenumiĝos, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Ho filo de homo, profetu, kaj diru: Tiele diras la Eternulo: Proklamu: Glavo, glavo estas akrigita kaj purigita;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'ĝi estas akrigita, por buĉi; ĝi estas purigita, por brili. Ĉu oni povas ĝoji, kiam la sceptron de Mia filo malŝatas ĉia ligno?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'Li donis ĝin, por purigi, por ke oni povu preni ĝin en la manon; la glavo estas akrigita kaj purigita, por doni ĝin en la manon de mortiganto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Kriu kaj ploru, ho filo de homo, ĉar ĝi iras kontraŭ Mian popolon, kontraŭ ĉiujn eminentulojn de Izrael, kiuj estas kolektitaj kune kun Mia popolo sub la glavon. Pro tio batu viajn lumbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Ĉar estis farita provo, sed kion ĝi helpis? eĉ malŝatata la sceptro ne povas ekzisti, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Kaj vi, ho filo de homo, profetu, kaj interfrapu la manojn; ĉar la glavo duobliĝos, eĉ triobliĝos; ĝi estas glavo por mortigado, glavo de granda mortigado ĝi estas, kiu penetros al ili en la ĉambrojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Mi sendos glavon teruran, por ke la koroj ektremu, kaj por ke multaj falu ĉe ĉiuj iliaj pordegoj. Ha, kiel ĝi brilas, kiel akrigita ĝi estas por la buĉado!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Kolektiĝu dekstren, metu vin maldekstren, kien ajn via vizaĝo sin tiras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Mi plaŭdos per Miaj manoj, kaj Mi kontentigos Mian indignon; Mi, la Eternulo, tion diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'Vi, ho filo de homo, marku al vi du vojojn, per kiuj venos la glavo de la reĝo de Babel; ambaŭ devas eliri el unu lando; elektu lokon sur la ĉefa vojo, elektu urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Marku vojon, per kiu devas veni glavo en Raban de la Amonidoj, kaj en Judujon, en la fortikigitan Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Ĉar la reĝo de Babel haltis ĉe la disvojiĝo, ĉe la komenco de du vojoj; por ricevi antaŭdirojn, li ĵetas sagojn, demandas la domajn diojn, esploras hepaton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Sur la dekstra flanko la sortodemandado montras Jerusalemon, por starigi muregrompilojn, malfermi la buŝon por mortigado, sonigi militajn trumpetojn, direkti muregrompilojn kontraŭ la pordegojn, ŝuti remparon, konstrui bastionon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'Sed tio aperas al ili kiel antaŭdiro malvera, ili faras ĵurojn, kaj li rememorigas la krimojn, por ke ili estu kaptitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Tial tiele diras la Sinjoro, la Eternulo: Pro tio, ke vi rememoras viajn krimojn, elmontras viajn kulpojn en ĉiuj viaj agoj-pro tio, ke vi rememoras, vi estos kaptitaj per mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'Kaj vi, ho senhonora kaj malpia estro de Izrael, kies tago alvenis nun, kiam devas ĉesiĝi liaj krimoj-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'tiele diras la Sinjoro, la Eternulo: Deprenu la cidaron kaj demetu la kronon; ne plue estos tiel; kiu estis humila, tiu altiĝos, kaj kiu estis fiera, tiu malaltiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Mi forigos, forigos, forigos ĝin; kaj ĝi ne ekzistos, ĝis venos tiu, kiu havas rajton je ĝi, kaj al li Mi ĝin donos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Kaj vi, ho filo de homo, profetu, kaj diru: Tiele diras la Sinjoro, la Eternulo, pri la Amonidoj kaj pri ilia hontindeco, kaj diru: Glavo, glavo estas nudigita por buĉado, akrigita por ekstermado, ke ĝi brilu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'pro tio, ke oni prezentas al vi malverajn viziojn, ke oni antaŭdiras al vi mensogaĵon, por meti vin sur la kolojn de mortigotaj malpiuloj, kies tago alvenis nun, kiam devas ĉesiĝi iliaj krimoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Remetu ĝin en ĝian ingon. Sur la loko, kie vi estas kreita, en la lando de via naskiĝo, Mi juĝos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'Kaj Mi elverŝos sur vin Mian indignon, Mi blovos sur vin la fajron de Mia kolero, kaj Mi transdonos vin en la manojn de homoj furiozaj, lertaj ekstermistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Vi fariĝos manĝaĵo por la fajro; via sango elverŝiĝos en la lando; oni ne rememoros vin; ĉar Mi, la Eternulo, tion diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'Ĉu vi, ho filo de homo, volas juĝi la urbon de sango kaj montri al ĝi ĉiujn ĝiajn abomenindaĵojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'Diru, ke tiele diras la Sinjoro, la Eternulo: Ho urbo, kiu elverŝas sangon en sia mezo, por ke venu ĝia tempo, kaj kiu faras al si idolojn, por malpuriĝi!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Per la sango, kiun vi elverŝis, vi kulpiĝis, kaj per viaj idoloj, kiujn vi faris, vi malpuriĝis; vi alproksimigis vian tempon kaj alvenigis vian jaron. Pro tio Mi faros vin hontindaĵo inter la nacioj kaj mokataĵo por ĉiuj landoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Tiuj, kiuj estas proksimaj, kaj tiuj, kiuj estas malproksimaj de vi, mokos vin, kiu havos malpuran nomon kaj grandan maltrankvilecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Jen la estroj de Izrael, ĉiu el ili laŭ sia potenco, estis ĉe vi, por verŝi sangon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Patron kaj patrinon oni malŝatis ĉe vi, fremdulon oni premis inter vi, al orfo kaj vidvino oni faris maljustaĵon ĉe vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Miajn sanktaĵojn vi malestimis, kaj Miajn sabatojn vi malsanktigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Kalumniantoj estis ĉe vi, por verŝi sangon; sur la montoj oni manĝis ĉe vi, malĉastaĵojn oni faris meze de vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'Nudaĵon de patro oni malkovris ĉe vi, perfortis virinon dum ŝia monataĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Oni faris abomenindaĵon kun la edzino de sia proksimulo, oni malpurigis sian bofilinon per malĉastaĵo, oni perfortis ĉe vi sian fratinon, filinon de sia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'Subaĉeton oni prenis ĉe vi, por verŝi sangon, procentegon kaj troprofiton vi prenis, pro avideco vi premis viajn proksimulojn, kaj Min vi forgesis, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Kaj jen Mi interfrapis Miajn manojn pro via profitemeco, kiun vi montris, kaj pro la verŝado de sango, kiu estis meze de vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Ĉu via koro rezistos, kaj ĉu viaj manoj konservos sian forton, en la tempo, kiam Mi komencos Mian faradon kontraŭ vi? Mi, la Eternulo, tion diris, kaj Mi faros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Kaj Mi disĵetos vin inter la naciojn, kaj Mi dispelos vin en diversajn landojn, kaj Mi tute deprenos de vi vian malpurecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'Kaj vi humiligos vin antaŭ la okuloj de la nacioj; kaj vi ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Ho filo de homo! la domo de Izrael fariĝis por Mi kiel skorio: ili ĉiuj, kupro, stano, fero, kaj plumbo, interne de la forno fariĝis skorio de arĝento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Tial tiele diras la Sinjoro, la Eternulo: Ĉar vi ĉiuj fariĝis skorio, tial jen Mi kolektos vin en Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Kiel oni kolektas arĝenton, kupron, feron, plumbon, kaj stanon en forno, por blovi sur ilin fajron kaj fandi ilin, tiel Mi kolektos en Mia kolero kaj en Mia indigno, kuŝigos, kaj fandos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Mi kunigos vin kaj blovos sur vin la fajron de Mia kolero, kaj vi fandiĝos en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Kiel fandiĝas arĝento en la forno, tiel vi fandiĝos en ĝi; kaj vi ekscios, ke Mi, la Eternulo, elverŝis sur vin Mian koleron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Ho filo de homo, diru al ĝi: Vi estas lando ne purigata, ne pripluvata en la tago de kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'La amasiĝintaj profetoj en ĝi estas kiel blekeganta leono, kiu disŝiras kaptitaĵon; ili manĝas animojn, forprenas valoraĵojn kaj multekostaĵojn, multigas en ĝi la nombron de ĝiaj vidvinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Ĝiaj pastroj kripligas Mian instruon kaj malsanktigas Miajn sanktaĵojn; ili ne distingas inter sanktaĵo kaj nesanktaĵo, ne montras la diferencon inter malpuraĵo kaj puraĵo; kaj de Miaj sabatoj ili forturnis siajn okulojn, kaj Mi estas malsanktigata inter ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Ĝiaj potenculoj en ĝi estas kiel lupoj, kiuj disŝiras kaptitaĵon, verŝas sangon, pereigas animojn, por akiri profiton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'Ĝiaj profetoj ŝmiras ilin per maltaŭga mortero, predikas malverajn viziojn, faras al ili mensogajn antaŭdirojn, dirante, ke tiele diris la Sinjoro, la Eternulo, kvankam la Eternulo ne parolis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'La popolo de la lando faras perfortaĵojn, senĉese rabas, premas malriĉulon kaj senhavulon, perfortas la fremdulon sen ia justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'Mi serĉis inter ili homon, kiu aranĝus barilon kaj stariĝus antaŭ Mi ĉe la breĉo, por defendi la landon, ke Mi ne pereigu ĝin; sed Mi ne trovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Kaj Mi elverŝos sur ilin Mian koleron, Mi ekstermos ilin per la fajro de Mia indigno; ilian konduton Mi metos sur ilian kapon, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Ho filo de homo! estis du virinoj, filinoj de unu patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'Kaj ili malĉastis en Egiptujo, en sia juneco ili malĉastis; tie premiĝis ilia brusto, kaj tie palpiĝis iliaj virgaj mamoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Iliaj nomoj estas: la nomo de la pli aĝa, Ohola; kaj la nomo de ŝia fratino, Oholiba. Ili fariĝis Miaj edzinoj, kaj ili naskis filojn kaj filinojn. Ohola estas Samario, kaj Oholiba estas Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Ohola, estante jam Mia, malĉastis, kaj volupte amis siajn amistojn, siajn najbarojn, la Asirianojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'kiuj portas vestojn purpurajn, la estrojn kaj urboregantojn, kiuj ĉiuj estas ĉarmaj junuloj, lertaj rajdistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Kaj ŝi malĉastis kun ili, kun ĉiuj plej ĉarmaj filoj de Asirio; kaj ŝi malpurigis sin per ĉiuj idoloj de tiuj, kiujn ŝi volupte amis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Kaj ŝi ne forlasis ankaŭ sian malĉastadon kun la Egiptoj, kiuj kuŝadis kun ŝi dum ŝia juneco, palpadis ŝiajn virgajn mamojn, kaj verŝadis sur ŝin sian malĉastaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Tial Mi transdonis ŝin en la manojn de ŝiaj amistoj, en la manojn de la filoj de Asirio, al kiuj ŝi havis voluptan pasion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Ili malkovris ŝian nudaĵon, prenis ŝiajn filojn kaj ŝiajn filinojn, kaj ŝin mem ili mortigis per glavo. Kaj ŝi ricevis malhonoran nomon inter la virinoj, kiam pri ŝi estis farita juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'Tion vidis ŝia fratino Oholiba, kaj en siaj voluptaĵoj ŝi agis ankoraŭ pli malbone ol ŝi, kaj ŝia malĉastado estis ankoraŭ pli granda, ol la malĉastado de ŝia fratino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Ŝi amis volupte la filojn de Asirio, estrojn kaj urboregantojn, siajn najbarojn, kiuj portis belajn vestojn, estis lertaj rajdistoj, kaj ĉiuj estis ĉarmaj junuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'Mi vidis, ke ŝi malpuriĝis, kaj ke ambaŭ havas la saman konduton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Sed ĉi tiu malĉastis ankoraŭ pli. Kiam ŝi vidis pentritajn virojn sur la muro, bildojn de Ĥaldeoj, kolore pentritajn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'kun zonoj ĉirkaŭ siaj lumboj, kun longaj kapkovroj sur siaj kapoj, aspektantajn kiel herooj, prezentantajn la bildon de Babelanoj el Ĥaldeujo, ilia naskiĝlando,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'tiam ŝi volupte ekamis ilin, kiam ŝi vidis ilian bildon, kaj ŝi sendis al ili senditojn en Ĥaldeujon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Kaj la Babelanoj venis al ŝi, por ame kuŝi kun ŝi, kaj ili malpurigis ŝin per sia malĉastaĵo, kaj ŝi malpuriĝis per ili; kaj poste ŝia animo trosatiĝis de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Kaj kiam ŝia malĉastado kaj ŝia hontindeco fariĝis tro malkaŝa, tiam Mia animo tediĝis de ŝi, kiel Mia animo tediĝis de ŝia fratino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Sed ŝi malĉastadis ĉiam pli, rememorante la tagojn de sia juneco, kiam ŝi malĉastadis en la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'Kaj ŝi volupte ekamis pli ol iliaj kromvirinoj ilin, kies karno estas kiel karno de azenoj kaj kies elfluo estas kiel elfluo de ĉevaloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Kaj vi ripetis la malĉastadon de via juneco, kiam la Egiptoj palpadis vian bruston pro viaj junaj mamoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Tial, ho Oholiba, tiele diras la Sinjoro, la Eternulo: Jen Mi instigos kontraŭ vin viajn amistojn, de kiuj via animo tediĝis, kaj Mi venigos ilin sur vin de ĉirkaŭe:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'la Babelanojn, kaj ĉiujn Ĥaldeojn el Pekod, el Ŝoa, kaj el Koa, kune kun ĉiuj filoj de Asirio, la ĉarmajn junulojn, la estrojn kaj urboregantojn, la potenculojn kaj eminentulojn, ĉiujn lertajn rajdistojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'Kaj ili venos kontraŭ vin kun hakiloj, sur ĉevaloj kaj sur ĉaroj, kaj kun granda amaso da popolo; ili ĉirkaŭos vin de ĉiuj flankoj en kirasoj, kun ŝildoj kaj kaskoj; kaj Mi transdonos vin al ilia juĝo, kaj ili juĝos vin laŭ sia maniero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'Kaj Mi direktos kontraŭ vin Mian indignon, kaj ili agos kun vi kolere, ili detranĉos vian nazon kaj viajn orelojn, kaj via restaĵo falos de glavo; ili forprenos viajn filojn kaj viajn filinojn, kaj via restaĵo estos ekstermita per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'Ili deprenos de vi viajn vestojn kaj forprenos viajn ornamaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'Kaj Mi faros finon al via malĉastado kaj al viaj malvirtoj el la lando Egipta, kaj vi ne plu levos al ili viajn okulojn, kaj Egiptujon vi ne plu rememoros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Ĉar tiele diras la Sinjoro, la Eternulo: Jen Mi transdonos vin en la manojn de tiuj, kiujn vi ekmalamis, en la manojn de tiuj, de kiuj via animo tediĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'Kaj ili agos kun vi malame, kaj forprenos ĉion, kion vi laborakiris, kaj ili lasos vin nuda kaj senkovra; kaj malkaŝiĝos la nudeco de via malĉastado, kaj viaj malvirtoj kaj viaj malĉastaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Tio estos farita al vi pro tio, ke vi malĉastis laŭ la ekzemplo de la nacioj kaj malpurigis vin per iliaj idoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Vi iris laŭ la vojo de via fratino, tial Mi donos ŝian kalikon en vian manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Tiele diras la Sinjoro, la Eternulo: Vi trinkos la kalikon de via fratino, la profundan kaj larĝan; vi estos mokata kaj insultata pli, ol oni povas elporti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Vi fariĝos plena de ebrieco kaj malĝojo, ĉar kaliko de teruro kaj ruinigo estas la kaliko de via fratino Samario.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Kaj vi eltrinkos ĝin ĝisfunde, kaj vi ĉirkaŭlekos ĝiajn rompopecetojn, kaj vi disŝiros vian bruston; ĉar Mi tion parolis, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Tial tiele diras la Sinjoro, la Eternulo: Pro tio, ke vi forgesis Min kaj forĵetis Min malantaŭ vian dorson, tial suferu nun pro viaj malvirtoj kaj pro viaj malĉastaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'Kaj la Eternulo diris al mi: Ho filo de homo! ĉu vi volas juĝi Oholan kaj Oholiban kaj montri al ili iliajn abomenindaĵojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'Ĉar ili adultis, kaj sango estas sur iliaj manoj; ili adultis kun siaj idoloj; kaj siajn infanojn, kiujn ili naskis al Mi, ili trairigis por ili tra fajro, kiel manĝaĵon por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Ankoraŭ ĉi tion ili faris al Mi: ili malpurigis Mian sanktejon en tiu tempo, kaj malsanktigis Miajn sabatojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'kaj, buĉinte siajn infanojn por siaj idoloj, ili en la sama tago venis en Mian sanktejon, por malsanktigi ĝin; jen tiel ili agis en Mia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Ili ankaŭ sendis, por inviti homojn el malproksime, al kiuj sendito estis sendita; kaj ili venis, tiuj, por kiuj vi vin lavis, kolerigis viajn okulojn, kaj ornamis vin per ornamaĵoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'kaj sidiĝis sur luksa lito, antaŭ kiu estis aranĝita tablo, kaj sur ĝin vi metis Mian incenson kaj Mian oleon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'Kaj tie estis aŭdata ĝojkriado de homamaso, kaj al la granda amaso da homoj venis ankaŭ ebriuloj el la dezerto, kaj metis braceletojn sur iliajn manojn kaj belajn kronojn sur iliajn kapojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'Mi diris pri la maljuniĝinta en adultado: Ŝi alkutimiĝis al la malĉastado kaj ne povas ĉesi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'Oni venadis al ŝi, kiel oni venas al malĉastistino; tiel oni venadis al Ohola kaj al Oholiba, la malĉastulinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Sed la homoj virtaj juĝos ilin laŭ la juĝo kontraŭ adultulinoj kaj laŭ la juĝo kontraŭ sangoverŝantinoj; ĉar ili estas adultulinoj, kaj sango estas sur iliaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Ĉar tiele diras la Sinjoro, la Eternulo: Venigu kontraŭ ilin homamason, kaj oni elmetu ilin al ruinigo kaj rabado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'Kaj la amaso mortigu ilin per ŝtonoj kaj haku ilin per siaj glavoj; iliajn filojn kaj iliajn filinojn oni mortigu, kaj iliajn domojn oni forbruligu per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'Kaj Mi faros finon al la malĉastado en la lando, kaj tio estos averto por ĉiuj virinoj, ke ili ne agu simile al via malĉastado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'Kaj oni metos vian malĉastadon sur vin, kaj vi portos sur vi la pekojn pri viaj idoloj; kaj vi ekscios, ke Mi estas la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'Kaj aperis al mi vorto de la Eternulo en la naŭa jaro, en la deka monato, en la deka tago de la monato, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'Ho filo de homo! enskribu al vi la nomon de ĉi tiu tago, ĝuste de ĉi tiu tago; la reĝo de Babel atingis Jerusalemon ĝuste en ĉi tiu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'Kaj prezentu parabolon al la domo malobeema, kaj diru al ili: Tiele diras la Sinjoro, la Eternulo: Starigu kaldronon, starigu, kaj verŝu en ĝin akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Enkolektu en ĝin ĝiajn pecojn, ĉiujn bonajn pecojn, la lumbojn kaj ŝultrojn; per plej bonaj ostoj plenigu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Prenu plej bonan ŝafaĵon, metu suben vicon da ostoj; boligu bone, ke ankaŭ la ostoj kuiriĝu en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Tial tiele diras la Sinjoro, la Eternulo: Ve al la sangavida urbo, al la kaldrono, kies sedimento restas en ĝi kaj kies sedimento ne eliras el ĝi! pecon post peco elĵetu el ĝi, ne elektu lote.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Ĉar ĝia sango estas en ĝi; sur nudan rokon ĝi verŝis ĝin, ne verŝis ĝin sur la teron, kie polvo povus ĝin kovri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Por venigi sur ĝin Mian koleron, por fari venĝon, Mi verŝos ĝian sangon sur nudan rokon, por ke ĝi ne estu kovrita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Tial tiele diras la Sinjoro, la Eternulo: Ve al la sangavida urbo! Mi ankaŭ aranĝos grandan brulolignaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Multigu la lignon, ekbruligu la fajron, plenkuiru la viandon, bone spicu, ke eĉ la ostoj brulu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Kaj starigu la malplenan kaldronon sur ĝiaj karboj, por ke ĝi fariĝu varmega, por ke ĝia kupro brulruĝiĝu kaj ĝia malpuraĵo en ĝi fandiĝu kaj ĝia sedimento malaperu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Sed obstina estas la sedimento, ne eliras el ĝi; multe estas da sedimento, eĉ en la fajro restas ĝia sedimento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'En via malpuraĵo estas malvirtaĵo; kiel ajn Mi penis purigi vin, vi tamen ne puriĝis de via malpuraĵo; ankaŭ vi ne plu puriĝos, ĝis Mi kvietigos sur vi Mian koleron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Mi, la Eternulo, parolis, kaj tio venos, kaj Mi tion plenumos; Mi ne prokrastos, ne indulgos, ne kompatos; laŭ via konduto kaj laŭ viaj agoj Mi juĝos vin, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Ho filo de homo! jen per plago Mi forprenos de vi tion, kio estas plej kara por viaj okuloj; sed vi ne plendu, kaj ne ploru, kaj ne elfluigu larmojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Ĝemu mallaŭte; funebran ceremonion ne faru, sed vian kapornamon metu sur vin, kaj viajn ŝuojn metu sur viajn piedojn, ne kovru vian buŝon, kaj ne manĝu panon de funebrantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Mi parolis al la popolo matene, kaj vespere mortis mia edzino; kaj en la sekvanta tago mi agis tiel, kiel estis ordonite al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'Kaj la popolo diris al mi: Ĉu vi ne diros al ni, kion signifas por ni tio, kion vi faras?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Kaj mi diris al ili: Aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Diru al la domo de Izrael: Tiele diras la Sinjoro, la Eternulo: Jen Mi malsanktigos Mian sanktejon, la forton de via gloro, la ĝuon de viaj okuloj, kaj la ĉarmaĵon de via animo; kaj viaj filoj kaj viaj filinoj, kiujn vi forlasis, falos de glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'Kaj vi agos, kiel mi agis: vian buŝon vi ne kovros, kaj panon de funebrantoj vi ne manĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'Kaj via kapornamo estos sur via kapo, kaj viaj ŝuoj estos sur viaj piedoj; vi ne funebros kaj ne ploros, sed vi konsumiĝados pro viaj malbonagoj kaj ĝemados unu al alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Kaj Jeĥezkel estos por vi antaŭsigno: ĉion, kion li faris, vi ankaŭ faros; kiam tio venos, vi ekscios, ke Mi estas la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'Kaj koncerne vin, ho filo de homo: en la tago, kiam Mi forprenos de ili ilian forton, la ĝojon de ilia beleco, la ĝuon de iliaj okuloj, la ĉarmaĵon de ilia animo, iliajn filojn kaj iliajn filinojn-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'en tiu tago venos al vi forsaviĝinto, por transdoni sciigon al viaj oreloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'en tiu tago malfermiĝos via buŝo antaŭ la forsaviĝinto, kaj vi ekparolos, kaj vi ne plu silentos, kaj vi estos antaŭsigno por ili; kaj ili ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'Ho filo de homo, turnu vian vizaĝon al la Amonidoj, kaj profetu pri ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'kaj diru al la Amonidoj: Aŭskultu la vorton de la Sinjoro, la Eternulo: Tiele diras la Sinjoro, la Eternulo: Pro tio, ke vi diras pri Mia sanktejo: Ha, ha! ĝi estas malsanktigita; kaj pri la lando de Izrael: Ĝi estas dezertigita; kaj pri la domo de Jehuda: Ili estas forkondukitaj en kaptitecon-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'pro tio jen Mi transdonos vin kiel posedaĵon al la filoj de la oriento, kaj ili starigos ĉe vi siajn tendarojn kaj aranĝos ĉe vi siajn loĝejojn; ili manĝos viajn fruktojn, kaj ili trinkos vian lakton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'Kaj Mi faros el Raba stalon por kameloj, kaj el la lando de la Amonidoj ripozejon por ŝafoj; kaj vi ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Ĉar tiele diras la Sinjoro, la Eternulo: Pro tio, ke vi aplaŭdis per la manoj kaj frapis per la piedoj kaj kun plena kora malestimo ĝojis pri la lando de Izrael-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'pro tio jen Mi etendos Mian manon kontraŭ vin kaj transdonos vin al la nacioj por disrabo, kaj Mi ekstermos vin el inter la popoloj, malaperigos vin el inter la landoj, kaj pereigos vin; kaj vi ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Tiele diras la Sinjoro, la Eternulo: Pro tio, ke Moab kaj Seir diras: Jen la domo de Jehuda estas kiel ĉiuj nacioj-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'pro tio Mi malfermos la flankon de Moab en la urboj, en ĝiaj limaj urboj, la belan landon de Bet-Jeŝimot, Baal-Meon, kaj Kirjataim;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'kaj Mi donos tion kune kun la Amonidoj al la filoj de la oriento kiel posedaĵon, por ke la Amonidoj ne plu estu rememorataj inter la popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'Kaj kontraŭ Moab Mi faros juĝon; kaj ili ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Tiele diras la Sinjoro, la Eternulo: Pro tio, ke Edom faris venĝon al la domo de Jehuda kaj forte kulpiĝis per sia venĝo kontraŭ ili-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'pro tio tiele diras la Sinjoro, la Eternulo: Mi etendos Mian manon kontraŭ la landon de Edom, kaj ekstermos en ĝi la homojn kaj brutojn, kaj faros ĝin dezerto; de Teman ĝis Dedan ili falos de glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'Kaj Mi faros Mian venĝon kontraŭ Edom per la mano de Mia popolo Izrael; kaj ili agos kun la Edomidoj konforme al Mia kolero kaj indigno, por ke ĉi tiuj ekkonu Mian venĝon, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Tiele diras la Sinjoro, la Eternulo: Pro tio, ke la Filiŝtoj agis venĝe kaj faris la venĝon kun plena kora malbondeziro kaj faris ekstermon laŭ sia eterna malamo-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'pro tio tiele diras la Sinjoro, la Eternulo: Jen Mi etendos Mian manon kontraŭ la Filiŝtojn, ekstermos la Keretidojn, kaj pereigos la restintojn ĉe la bordo de la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'Kaj Mi faros kontraŭ ili grandan venĝon kun kolerega puno; kaj ili ekscios, ke Mi estas la Eternulo, kiam Mi faros Mian venĝon kontraŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'En la dek-unua jaro, en la unua tago de la monato, aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Ho filo de homo! pro tio, ke Tiro diras pri Jerusalem: Ha, ha! ĝi estas frakasita, la pordo de la popoloj, ĝi turnas sin al mi, mi pleniĝos de ĝia dezertiĝo-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'pro tio tiele diras la Sinjoro, la Eternulo: Jen Mi iras kontraŭ vin, ho Tiro, kaj Mi levos kontraŭ vin multe da nacioj, kiel maro levas siajn ondojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'Kaj ili detruos la muregojn de Tiro kaj disrompos ĝiajn turojn; kaj Mi forbalaos de ĝi ĝian polvon, kaj Mi faros ĝin nuda roko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Loko por sternado de retoj ĝi fariĝos meze de la maro, ĉar Mi tion parolis, diras la Sinjoro, la Eternulo; kaj ĝi fariĝos rabaĵo por la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'Kaj ĝiaj filinoj, kiuj estas sur la kampo, estos mortigitaj per glavo; kaj ili ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Ĉar tiele diras la Sinjoro, la Eternulo: Jen Mi venigos kontraŭ Tiron de norde Nebukadnecaron, reĝon de Babel, la reĝon de reĝoj, kun ĉevaloj, ĉaroj, kaj rajdistoj, kun homamaso kaj multe da popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Viajn filinojn sur la kampo li mortigos per glavo; li faros kontraŭ vi bastionojn, li ŝutaranĝos ĉirkaŭ vi remparojn, kaj starigos kontraŭ vi siajn ŝildojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'kaj li starigos siajn muregrompilojn kontraŭ viaj muregoj, kaj viajn turojn li detruos per siaj hakiloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Pro la multo de siaj ĉevaloj li kovros vin per polvo; de la bruo de la rajdistoj, radoj, kaj ĉaroj ektremos viaj muregoj, kiam li eniros en viajn pordegojn, kiel oni eniras en urbon trarompitan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Per la hufoj de siaj ĉevaloj li dispremos ĉiujn viajn stratojn; vian popolon li mortigos per glavo, kaj la monumentojn de via forto li ĵetos sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'Ili disrabos vian havon kaj diskaptos viajn komercaĵojn; ili detruos viajn murojn, ili disrompos viajn belajn domojn; viajn ŝtonojn, vian lignon, kaj vian teron ili ĵetos en la akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'Mi ĉesigos la laŭtan sonadon de viaj kantoj, kaj la voĉo de viaj harpoj ne plu estos aŭdata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'Mi faros vin nuda roko; vi fariĝos loko por sternado de retoj, vi ne plu estos rekonstruata; ĉar Mi, la Eternulo, tion parolis, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Tiele diras la Sinjoro, la Eternulo, pri Tiro: Vere, de la bruo de via falado, de la ĝemado de viaj vunditoj, kiam meze de vi estos farata mortigado, ektremos la insuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Kaj malsupreniros de siaj tronoj ĉiuj princoj de la maro, ili demetos de si sian purpuron kaj siajn broditajn vestojn; timo ilin atakos; ili sidiĝos sur la tero, tremos ĉiuminute, kaj eksentos teruron pro vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'Kaj ili ekkantos pri vi funebran kanton, kaj diros pri vi: Kiele vi pereis, vi, loĝata de maristoj, glora urbo, kiu estis forta sur la maro, ĝi kaj ĝiaj loĝantoj, kiuj ĵetadis timon sur ĉiujn loĝantojn de la mara regiono!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Nun ektremos la maraj regionoj en la tago de via falo, kaj la insuloj sur la maro konsterniĝos pro via finiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Ĉar tiele diras la Sinjoro, la Eternulo: Kiam Mi faros vin urbo dezerta simila al la urboj neloĝataj, kiam Mi levos sur vin la abismon kaj granda akvo vin kovros,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'tiam Mi mallevos vin al tiuj, kiuj iris en la tombon, al la popolo eterna, kaj Mi puŝos vin en la profundon subteran, en la eternan dezerton, al tiuj, kiuj iris en la tombon, por ke vi ne plu estu loĝata; tiam Mi restarigos belecon sur la tero de la vivantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Mi neniigos vin, kaj vi ne plu ekzistos; oni serĉos vin, sed ne plu trovos en eterneco, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'Vi, ho filo de homo, ekkantu funebran kanton pri Tiro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'kaj diru al Tiro, kiu sidas ĉe la enirejo de la maro kaj kiu komercas kun la popoloj sur multaj insuloj: Tiele diras la Sinjoro, la Eternulo: Ho Tiro, vi diras: Mi estas perfektaĵo de beleco!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'En la koro de la maro estas viaj limoj; viaj konstruintoj faris vin perfekte bela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'El cipresoj de Senir ili konstruis por vi ĉiujn viajn tabulojn, cedrojn de Lebanon ili prenis, por fari viajn mastojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'El kverkoj de Baŝan ili faris viajn remilojn, viajn benkojn ili faris el eburo kaj el bukso de la insuloj de la Kitidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'El delikata brodita tolo Egipta estis viaj veloj, kaj tio estis ankaŭ via standardo; blua kaj purpura ŝtofo de la insuloj de Eliŝa estis viaj kovrotukoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'La loĝantoj de Cidon kaj Arvad estis viaj remistoj; viajn proprajn kompetentulojn vi havis, ho Tiro, kaj ili estis viaj ŝipgvidistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'La plejaĝuloj de Gebal kaj ĝiaj kompetentuloj estis ĉe vi kalfatristoj; ĉiaj ŝipoj de la maro kaj iliaj ŝipistoj estis ĉe vi, por servi al via komercado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Persoj, Ludidoj, kaj Putidoj estis en via armeo, kiel viaj militistoj, pendigis ĉe vi siajn ŝildojn kaj kaskojn, kaj estis via beleco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'La filoj de Arvad kaj via militistaro staris sur viaj muregoj ĉirkaŭe kaj estis gardistoj sur viaj turoj; siajn ŝildojn ili pendigis ĉirkaŭe sur viaj muregoj, kaj ili perfektigis vian belecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Tarŝiŝ komercis kun vi per multo da diversaj valoraĵoj; arĝenton, feron, stanon, kaj plumbon ĝi alportadis al via komercejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Javan, Tubal, kaj Meŝeĥ komercis kun vi, alportante al vi kiel komercaĵojn homajn animojn kaj kuprajn vazojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'El Togarma oni alportadis al via komercejo ĉevalojn, rajdoĉevalojn, kaj mulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'La filoj de Dedan komercis kun vi; sur multaj insuloj estis viaj komercaĵoj; eburon kaj ebonon ili vendadis al vi siaflanke.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'Sirio prenadis de vi komerce la multon de viaj faritaĵoj; rubenojn, purpurajn kaj broditajn ŝtofojn, delikatan tolon, koralojn, kaj kristalojn ili alportadis al via komercejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Judujo kaj la lando de Izrael komercis kun vi; pro viaj komercaĵoj ili alportadis al vi tritikon de Minit, vakson, mielon, oleon, kaj balzamon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damasko donadis al vi komerce kontraŭ la multo de viaj faritaĵoj multe da diversaj valoraĵoj, vinon el Ĥelbon, kaj plej blankan lanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Dan, Javan, kaj Meuzal alportadis al via komercejo ŝtalaĵojn, kasion, kaj bonodoran kanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedan komercis kun vi per belaj vestoj por rajdado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Arabujo kaj ĉiuj princoj de Kedar komercis kun vi, donante al vi ŝafidojn, ŝafojn, kaj kaprojn kontraŭ viaj komercaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'La komercistoj el Ŝeba kaj Raama komercis kun vi; la plej bonajn aromaĵojn, ĉiajn multekostajn ŝtonojn, kaj oron ili alportadis al via komercejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Ĥaran, Kane, kaj Eden, la komercistoj el Ŝeba, Asirio, kaj Kilmad komercis kun vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'ili komercis kun vi per belegaj ŝtofoj, purpuraj kaj broditaj tukoj, kestoj da multekostaj ŝtofoj, ĉirkaŭligitaj per ŝnuroj kaj cedrokovritaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Ŝipoj el Tarŝiŝ estis la ĉefaj en via komercado; kaj vi fariĝis tre riĉa kaj honorata sur la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Sur grandaj akvoj kondukadis vin viaj remistoj; sed orienta vento disrompos vin meze de la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Viaj riĉaĵoj, viaj komercaĵoj, viaj foiraĵoj, viaj ŝipanoj kaj viaj ŝipestroj, viaj kalfatristoj, la kondukantoj de via komercado, ĉiuj militistoj, kiuj estas ĉe vi, kaj la tuta homamaso, kiu estas ĉe vi, falos en la mezon de la maro en la tago de via pereo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'De la laŭta kriado de viaj ŝipestroj ekskuiĝos viaj ĉirkaŭaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'Kaj de siaj ŝipoj malsupreniros ĉiuj remistoj, la ŝipanoj, ĉiuj ŝipestroj, kaj stariĝos sur la tero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'kaj ili laŭte krios pri vi, kaj ploros maldolĉe kaj metos polvon sur siajn kapojn kaj rulos sin en cindro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'kaj ili faros al si pro vi kalvaĵon, ĉirkaŭzonos sin per sakaĵo, kaj ploros pri vi kun maldolĉa koro maldolĉan ploron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'Kaj en sia ĝemado ili ekkantos pri vi funebran kanton, kaj diros: Kiu iam fariĝis tiel silenta sur la maro, kiel Tiro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Kiam viaj komercaĵoj venadis de la maroj, vi satigadis multajn popolojn; per la abundo de viaj riĉaĵoj kaj viaj komercaĵoj vi riĉigadis la reĝojn de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Sed kiam sur la maroj vi estis ĵetegata en la profundon de la akvo, falis ĉe vi via komercado kaj via tuta homomulto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Ĉiuj loĝantoj de la insuloj eksentis teruron pri vi, iliaj reĝoj ektremis, kaj konsterno estas sur ilia vizaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'La komercistoj de la aliaj popoloj ekfajfis pri vi; vi neniiĝis, kaj neniam plu ekzistos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Ho filo de homo, diru al la reganto de Tiro: Tiele diras la Sinjoro, la Eternulo: Pro tio, ke via koro fieriĝis, kaj vi diris: Mi estas dio, mi sidas sur dia trono en la mezo de la maroj; dum vi estas homo, sed ne dio, kvankam vi rigardas vian koron kiel koron de dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'kvazaŭ vi estus pli saĝa ol Daniel kaj nenio estus kaŝita antaŭ vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'kvazaŭ per via saĝeco kaj via kompetenteco vi akirus al vi la potencon kaj kolektus oron kaj arĝenton en vian trezorejon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'kvazaŭ per via granda saĝeco en via komercado vi grandigus vian riĉecon, kaj via koro fieriĝis pro via riĉeco:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'pro tio tiele diras la Sinjoro, la Eternulo: Ĉar vi rigardas vian koron kiel koron de dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'tial jen Mi venigos kontraŭ vin fremdulojn, la plej terurajn el la popoloj; kaj ili nudigos siajn glavojn kontraŭ la belaĵojn de via saĝeco kaj malaperigos vian brilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'En pereon ili puŝos vin, kaj vi mortos en la mezo de la maro per morto de buĉitoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Ĉu antaŭ via mortiganto vi diros: Mi estas dio; dum vi estas ne dio, sed homo en la mano de via mortiganto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Per morto de necirkumciditoj vi mortos de la manoj de fremduloj; ĉar Mi tion parolis, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Ho filo de homo, ekkantu funebran kanton pri la reĝo de Tiro, kaj diru al li: Tiele diras la Sinjoro, la Eternulo: Vi estas sigelo de perfekteco, plena de saĝo kaj plej alta grado de beleco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'Vi estis en Eden, la ĝardeno de Dio; ĉiaspecaj multekostaj ŝtonoj vin kovris: rubeno, topazo, diamanto, sukceno, berilo, jaspiso, safiro, smeraldo, ametisto, kaj oro estis la ornamo de viaj tamburinoj kaj flutoj; ĉio estis preta en la tago de via kreiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Vi estas kerubo, kiu sin etendas kaj protektas; kaj Mi metis vin sur la sanktan monton de Dio, kie vi iradis inter fajraj ŝtonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Vi estis perfekta en via konduto de post la tago de via kreiĝo, ĝis troviĝis en vi malbonago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Pro la grandeco de via komercado via interno pleniĝis de maljusteco, kaj vi pekis; tial Mi deĵetos vin de la monto de Dio, kaj malaperigos vin, ho kerubo protektanto, el inter la fajraj ŝtonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'De via beleco fieriĝis via koro, pro via majesteco vi perdis vian saĝon; tial Mi ĵetos vin sur la teron kaj faros vin mokataĵo antaŭ la reĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Per la multo de viaj malbonagoj kaj per via malhonesta komercado vi malhonoris vian sanktejon; kaj Mi elirigos el vi fajron, kiu ekstermos vin, kaj Mi faros vin cindro sur la tero antaŭ la okuloj de ĉiuj viaj vidantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Ĉiuj, kiuj konas vin inter la popoloj, eksentos teruron pri vi; vi neniiĝis, kaj neniam plu ekzistos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Ho filo de homo, turnu vian vizaĝon al Cidon, kaj profetu pri ĝi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'kaj diru: Tiele diras la Sinjoro, la Eternulo: Jen Mi iras kontraŭ vin, ho Cidon; kaj Mi gloriĝos inter vi, kaj oni ekscios, ke Mi estas la Eternulo, kiam Mi faros kontraŭ ĝi juĝon kaj montros sur ĝi Mian sanktecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'Mi sendos sur ĝin peston, kaj sangoverŝadon sur ĝiajn stratojn, kaj falos en ĝi mortigitoj de glavo, kiu estos direktita kontraŭ ĝin de ĉiuj flankoj; kaj oni ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'Kaj ĝi ne plu estos por la domo de Izrael pikanta dorno nek doloriganta pikilo pli ol ĉiuj malbondezirantaj najbaroj; kaj oni ekscios, ke Mi estas la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'Tiele diras la Sinjoro, la Eternulo: Kiam Mi kolektos la domon de Izrael el la popoloj, inter kiujn ĝi estis disĵetita, kaj montros sur ĝi Mian sanktecon antaŭ la okuloj de la nacioj, tiam ili loĝos sur sia tero, kiun Mi donis al Mia servanto Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'Kaj ili loĝos sur ĝi sendanĝere, kaj konstruos domojn kaj plantos vinberĝardenojn; jes, ili loĝos en sendanĝereco, kiam Mi faros juĝon kontraŭ ĉiuj iliaj malbondezirantoj ĉirkaŭ ili; kaj ili ekscios, ke Mi, la Eternulo, estas ilia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'En la deka jaro, en la deka monato, en la dek-dua tago de la monato, aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Ho filo de homo, turnu vian vizaĝon al Faraono, reĝo de Egiptujo, kaj profetu pri li kaj pri la tuta Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Parolu, kaj diru: Tiele diras la Sinjoro, la Eternulo: Jen Mi iras kontraŭ vin, ho Faraono, reĝo de Egiptujo, granda drako, kiu kuŝas meze de siaj riveroj, kaj diras: La rivero estas mia, kaj mi faris ĝin por mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Mi metos hokojn en vian buŝon, Mi alkroĉos la fiŝojn de viaj riveroj al via skvamaro, kaj Mi eltiros vin el viaj riveroj kune kun ĉiuj fiŝoj de viaj riveroj, kiuj estas alkroĉitaj al via skvamaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'Mi ĵetos vin en la dezerton, vin kaj ĉiujn fiŝojn de viaj riveroj; sur la kampon vi falos, oni vin ne levos kaj ne enkolektos; al la bestoj de la tero kaj al la birdoj de la ĉielo Mi transdonos vin kiel manĝaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'Kaj ekscios ĉiuj loĝantoj de Egiptujo, ke Mi estas la Eternulo; pro tio, ke ili estis kana apogo por la domo de Izrael:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'kiam ili kaptis vin per la mano, vi fendiĝis kaj trapikis al ili la tutan flankon; kaj kiam ili apogis sin sur vi, vi rompiĝis kaj traboris al ili la tutajn lumbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Tial tiele diras la Sinjoro, la Eternulo: Jen Mi venigos sur vin glavon kaj ekstermos ĉe vi la homojn kaj la brutojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'Kaj la lando Egipta fariĝos dezerto kaj ruinoj; kaj oni ekscios, ke Mi estas la Eternulo; pro tio, ke li diris: La rivero estas mia, kaj mi ĝin faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Tial jen Mi iras kontraŭ vin kaj kontraŭ viajn riverojn, kaj Mi faros el la lando Egipta ruinojn, absolutajn ruinojn, de Migdol ĝis Sevene, ĝis la limo de Etiopujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Ne trairos ĝin piedo de homo, nek piedo de bruto trairos ĝin, kaj ĝi ne estos loĝata dum kvardek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'Kaj Mi faros la landon Egiptan dezerto inter la aliaj dezertaj landoj, kaj ĝiaj urboj inter la aliaj ruinigitaj urboj estos dezertaj dum kvardek jaroj; kaj Mi disĵetos la Egiptojn inter la popolojn kaj dispelos ilin en diversajn landojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Ĉar tiele diras la Sinjoro, la Eternulo: Post paso de kvardek jaroj Mi kolektos la Egiptojn el inter la popoloj, kien ili estis disĵetitaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'kaj Mi revenigos la forkaptitajn Egiptojn, kaj revenigos ilin en la landon Patros, en la landon de ilia deveno, kaj ili tie estos humila regno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Ĝi estos humila inter la aliaj regnoj, kaj ĝi ne plu sin tenos alte super la nacioj; Mi faros ĝin malgranda, por ke ĝi ne regu super la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'Kaj ĝi ne plu estos por la domo de Izrael fidataĵo, rememoriganta iliajn malbonagojn, kiam ili sin turnadis al ĝi; kaj oni ekscios, ke Mi estas la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'En la dudek-sepa jaro, en la unua monato, en la unua tago de la monato, aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'Ho filo de homo! Nebukadnecar, reĝo de Babel, ŝarĝis sian militistaron per granda laboro kontraŭ Tiro, tiel, ke ĉiuj kapoj senhariĝis kaj ĉiuj ŝultroj defrotiĝis; kaj tamen nek li nek lia militistaro ricevis rekompencon antaŭ Tiro pro la laboro, kiun li faris antaŭ ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Tial tiele diras la Sinjoro, la Eternulo: Jen Mi donos al Nebukadnecar, reĝo de Babel, la landon Egiptan, por ke li forportu ĝiajn riĉaĵojn kaj faru en ĝi rabadon kaj diskapton; kaj tio estos rekompenco por lia militistaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Rekompence pro la laboro, kiun li faris, Mi donis al li la landon Egiptan; ĉar ili laboris por Mi, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'En tiu tempo Mi elkreskigos kornon al la domo de Izrael, kaj al vi Mi donos liberecon de parolado inter ili; kaj ili ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Ho filo de homo, profetu, kaj diru: Tiele diras la Sinjoro, la Eternulo: Plorkriu: Ve al la tago!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Ĉar proksima estas la tago, jes, proksima estas la tago de la Eternulo, malluma tago; venas la tempo de la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'Venos glavo sur Egiptujon, kaj tremo atakos Etiopujon, kiam mortigitoj falos en Egiptujo kaj oni forprenos ĝiajn riĉaĵojn kaj detruos ĝiajn fundamentojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'La Etiopoj, la Putidoj, kaj la Ludidoj, kaj ĉiuj diversgentaj popoloj, kaj Kub, kaj la filoj de la lando de interligo kune kun ili falos de glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'Tiele diras la Eternulo: Falos la helpantoj de Egiptujo, kaj malaltiĝos la fiereco de ĝia forto; de Migdol ĝis Sevene oni falos en ĝi de glavo, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'Kaj ĝi dezertiĝos kiel la aliaj dezertaj landoj, kaj ĝiaj urboj estos inter la aliaj ruinigitaj urboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'Kaj oni ekscios, ke Mi estas la Eternulo, kiam Mi aperigos fajron en Egiptujo kaj ĉiuj ĝiaj helpantoj estos frakasitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'En tiu tempo senditoj de Mi iros sur ŝipoj, por ektimigi Etiopujon, kiu estis ekster danĝero; kaj tremo ilin atakos, kiel en la tempo de Egiptujo; ĉar la tempo venas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Tiele diras la Sinjoro, la Eternulo: Mi neniigos la homomulton en Egiptujo per Nebukadnecar, reĝo de Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Li kune kun sia popolo, la plej terura el la nacioj, estos venigitaj, por pereigi la landon; kaj ili nudigos siajn glavojn kontraŭ Egiptujon kaj plenigos la landon per mortigitoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'Kaj la riverojn Mi faros sektero, kaj la landon Mi transdonos en la manojn de homoj malbonaj; kaj Mi ruinigos la landon, kaj ĉion, kio estas en ĝi, per la manoj de fremduloj; Mi, la Eternulo, tion parolis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Tiele diras la Sinjoro, la Eternulo: Mi ekstermos la idolojn kaj neniigos la malverajn diojn en Nof, kaj ne plu estos princo el la lando Egipta, kaj Mi venigos timon sur la landon Egiptan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'Mi ruinigos Patroson, Mi ekbruligos fajron en Coan, kaj Mi faros juĝon en No.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'Mi elverŝos Mian koleron sur la Egiptan fortikaĵon Sin, kaj Mi ekstermos la homomulton en No.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'Mi ekbruligos fajron en Egiptujo; forte ektremos Sin, No estos trarompita, kaj Nof havos ĉiutagan angoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'La junuloj de Aven kaj de Pi-Beset falos de glavo, kaj la virinoj iros en forkaptitecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'En Taĥpanĥes mallumiĝos la tago, kiam Mi rompos tie la jugon de Egiptujo, kaj malaperos en ĝi la fiereco de ĝia forto; mallumo ĝin kovros, kaj ĝiaj filinoj iros en forkaptitecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'Kaj Mi faros juĝon kontraŭ Egiptujo; kaj oni ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'En la dek-unua jaro, en la unua monato, en la sepa tago de la monato, aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'Ho filo de homo! Mi rompis la brakon de Faraono, reĝo de Egiptujo; kaj jen ĝi ne estas bandaĝita, por resaniĝi, kaj ĝi ne estas ĉirkaŭligita, ke ĝi ricevu forton, por teni glavon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Tial tiele diras la Sinjoro, la Eternulo: Jen Mi iros kontraŭ Faraonon, reĝon de Egiptujo, kaj Mi frakasos liajn brakojn, la sanan kaj la rompitan, kaj Mi elfaligos la glavon el lia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'Kaj Mi disĵetos la Egiptojn inter la naciojn, kaj Mi dispelos ilin en diversajn landojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Kaj Mi fortigos la brakojn de la reĝo de Babel kaj metos Mian glavon en lian manon; sed la brakojn de Faraono Mi frakasos, kaj ĉi tiu ĝemos antaŭ li, kiel ĝemas morte-vundito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Mi fortigos la brakojn de la reĝo de Babel, sed la brakoj de Faraono falos; kaj oni ekscios, ke Mi estas la Eternulo, kiam Mi metos Mian glavon en la manon de la reĝo de Babel kaj li eltiros ĝin kontraŭ la landon Egiptan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'Kaj Mi disĵetos la Egiptojn inter la naciojn kaj dispelos ilin en diversajn landojn; kaj ili ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'En la dek-unua jaro, en la tria monato, en la unua tago de la monato, aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Ho filo de homo, diru al Faraono, reĝo de Egiptujo, kaj al lia tuta popolo: Al kiu vi similigas vin en via grandeco?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Jen Asirio estis kiel cedro sur Lebanon, kun belaj branĉoj, kun densa foliaro, kun alta kresko, kaj ĝia supro estis inter la nuboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Akvo elkreskigis ĝin, la profundo altigis ĝin, ĉirkaŭante ĝian junan trunkon per siaj riveroj kaj sendante siajn fluojn al ĉiuj arboj de la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Tial ĝi fariĝis pli alta ol ĉiuj arboj de la kampo; ĝi ricevis multe da branĉoj, kaj ĝiaj branĉoj longiĝis, ĉar ĝi havis multe da akvo, por disetendiĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Sur ĝiaj branĉoj havis siajn nestojn ĉiaj birdoj de la ĉielo, sub ĝiaj branĉoj naskis idojn ĉiaj bestoj de la kampo, kaj sub ĝia ombro loĝis ĉiaj grandaj popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Kaj ĝi estis bela per sia grandeco kaj per la longeco de siaj branĉoj, ĉar ĝiaj radikoj troviĝis apud abunda akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'La cedroj en la ĝardeno de Dio ne estis pli altaj ol ĝi, la cipresoj ne estis egalaj al ĝiaj branĉoj, la platanoj ne povis sin kompari kun ĝiaj branĉoj; neniu arbo en la ĝardeno de Dio estis simila al ĝi per sia beleco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Mi faris ĝin bela per la multo de ĝiaj branĉoj; kaj ĉiuj Edenaj arboj, kiuj estas en la ĝardeno de Dio, enviis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Tial tiele diras la Sinjoro, la Eternulo: Pro tio, ke ĝi tro altiĝis kaj levis sian supron inter la nubojn kaj ĝia koro fieriĝis pro ĝia alteco -');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'pro tio Mi transdonos ĝin en la manon de la plej potenca el la nacioj, kiu agos kun ĝi konforme al ĝia malboneco kaj elpuŝos ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'Kaj elhakos ĝin fremduloj, la plej teruraj el la nacioj, kaj disĵetos ĝin; sur la montojn kaj sur ĉiujn valojn falos ĝiaj branĉoj, kaj ĝiaj branĉetoj rompiĝos sur ĉiuj torentoj de la lando, kaj ĉiuj popoloj de la tero foriros el sub ĝia ombro kaj forlasos ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Kaj sur ĝia renversiĝinta trunko sidos ĉiaj birdoj de la ĉielo, kaj sur ĝiaj branĉoj sidos ĉiaj bestoj de la kampo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'por ke neniu el la arboj apudakvaj fieriĝu pri sia alteco, nek levu sian supron inter la nubojn, kaj por ke neniu akvonutrata arbo leviĝu super ilin; ĉar ĉiuj ili estas destinitaj al la morto, en la profundon subteran, kune kun la homoj, kiuj iris en la tombon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Tiele diras la Sinjoro, la Eternulo: En la tago, kiam ĝi iros en Ŝeolon, Mi faros funebron, Mi fermos pro ĝi la abismon, Mi haltigos ĝiajn riverojn, ke stariĝu la grandaj akvoj, Mi mallumigos pro ĝi Lebanonon, kaj ĉiuj arboj de la kampo estos afliktitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Per la bruo de ĝia falo Mi ektremigos la naciojn, kiam Mi puŝos ĝin en Ŝeolon al tiuj, kiuj iris en la tombon; kaj konsoliĝos en la profundo subtera ĉiuj arboj de Eden, la plej elektitaj kaj plej bonaj de Lebanon, ĉiuj akvonutrataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Ĉar ankaŭ ili iros en Ŝeolon, al tiuj, kiuj estis mortigitaj de glavo, kaj ĝiaj kunuloj, kiuj sidis sub ĝia ombro inter la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Al kiu el la arboj de Eden vi estis simila per majesto kaj grandeco? tamen kune kun la arboj de Eden vi estos ĵetita en la profundon subteran; kaj vi kuŝos meze de necirkumciditoj kune kun tiuj, kiuj mortis de glavo. Tio estas dirita pri Faraono kaj pri lia tuta granda popolo, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'En la dek-dua jaro, en la dek-dua monato, en la unua tago de la monato, aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Ho filo de homo, ekkantu funebran kanton pri Faraono, reĝo de Egiptujo, kaj diru al li: Vi estas kiel leonido inter la nacioj, vi estas kiel drako en la maroj, vi saltas en viaj riveroj, vi movmalklarigas la akvon per viaj piedoj, vi malkvietigas iliajn riverojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'Tiele diras la Sinjoro, la Eternulo: Mi ĵetos sur vin Mian reton per granda amaso da popoloj, kaj ili eltiros vin per Mia reto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'Kaj Mi ĵetos vin sur la teron, sur nekovritan kampon Mi vin ĵetos, kaj Mi sidigos sur vi ĉiajn birdojn de la ĉielo, kaj Mi satigos de vi la bestojn de la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'Mi disĵetos vian karnon sur la montojn, kaj Mi plenigos la valojn per via kadavraĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'La landon de via naĝado Mi malsekigos per via sango ĝis la montoj, kaj la valoj estos plenaj de vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'Kiam vi estingiĝos, Mi kovros la ĉielon kaj senlumigos ĝiajn stelojn, la sunon Mi kovros per nubo, kaj la luno ne havos sian lumon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Ĉiujn fontojn de lumo en la ĉielo Mi senlumigos pro vi, kaj mallumon Mi metos sur vian landon, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'Mi maltrankviligos la korojn de multaj popoloj, kiam Mi venigos la scion pri via pereo inter la naciojn, en landojn, kiujn vi ne konis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'Mi teruros pro vi multajn popolojn, kaj iliaj reĝoj ektremos pro vi, kiam Mi svingos Mian glavon antaŭ iliaj vizaĝoj, kaj ĉiu el ili ĉiuminute tremos pri sia vivo en la tago de via falo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Ĉar tiele diras la Sinjoro, la Eternulo: La glavo de la reĝo de Babel venos sur vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Per la glavo de fortuloj Mi faligos vian multenombran popolon; ĉiuj ili estas la plej teruraj el la nacioj, kaj ili neniigos la belecon de Egiptujo, kaj ĝia tuta homomulto estos ekstermita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Mi pereigos ĉiujn ĝiajn brutojn apud la abundaj akvoj, kaj ilin ne plu malklarigos piedo de homo nek la hufoj de bruto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Tiam Mi ripozpurigos iliajn akvojn, kaj iliajn riverojn Mi fluigos kiel oleon, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'Kiam Mi faros la landon Egiptan dezerto, kaj la lando perdos ĉion, kion ĝi havis, kiam Mi mortigos ĉiujn, kiuj loĝas en ĝi, tiam oni ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'Tio estas funebra kanto, kiun oni kantos; la filinoj de la nacioj ĝin kantos, pri Egiptujo kaj pri ĝia tuta grandnombra popolo ili ĝin kantos, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'En la dek-dua jaro, en la dek-kvina tago de la sama monato, aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Ho filo de homo, priploru la popolon de Egiptujo, kaj puŝu ĝin kaj la filinojn de potencaj nacioj en la profundon subteran kune kun tiuj, kiuj iris en la tombon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'Ĉu vi estas pli bona ol iu? falu, kaj kuŝu kun la necirkumciditoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Inter tiuj, kiuj mortis de glavo, ili falos; al la glavo ĝi estas transdonita; oni tiros ĝin kaj ĝian tutan grandnombran popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Ekparolos al ĝi la potencaj herooj el meze de Ŝeol, kiuj kune kun ĝiaj helpantoj malsupreniris kaj ekkuŝis necirkumciditaj, mortigitaj de glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Tie estas Asirio kaj ĝia tuta homomulto; ĉirkaŭe de ĝi estas ĝiaj tomboj; ĉiuj ili estas mortigitaj, falis de glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Ĝiaj tomboj estas en la profundo de la terinterno, kaj ĝia homomulto estas ĉirkaŭ ĝia tombo; ĉiuj ili estas mortigitaj, falintaj de glavo, ili, kiuj ĵetadis ĉirkaŭ si teruron sur la tero de la vivantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Tie estas Elam kaj ĝia tuta homomulto, ĉirkaŭe estas ĝiaj tomboj; ĉiuj ili estas mortigitoj, kiuj falis de glavo kaj necirkumcidite malsupreniris en la profundon subteran, la samaj, kiuj ĵetadis ĉirkaŭ si teruron sur la tero de la vivantoj; ili portis sian honton kune kun tiuj, kiuj iris en la tombon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'Meze de mortigitoj estas donita kuŝejo al ĝi kun ĝia tuta homomulto; ĉirkaŭe estas iliaj tomboj; ĉiuj ili estas necirkumciditaj, mortigitaj de glavo; ĉar ili ĵetadis ĉirkaŭ si teruron sur la tero de la vivantoj, tial ili portis sian honton kun tiuj, kiuj iris en la tombon, kaj ili estas metitaj inter la mortigitojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Tie estas Meŝeĥ kaj Tubal kaj ilia tuta homomulto, ĉirkaŭe estas iliaj tomboj; ĉiuj ili estas necirkumciditaj, mortigitaj de glavo, ĉar ili ĵetadis ĉirkaŭ si teruron sur la tero de la vivantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'Ili ne kuŝas kun la herooj, kiuj falis de necirkumciditoj kaj iris en Ŝeolon kun siaj bataliloj kaj metis siajn glavojn sub siajn kapojn; iliaj malbonagoj restis sur iliaj ostoj, ĉar kiel fortuloj ili ĵetadis ĉirkaŭ si teruron sur la tero de la vivantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'Kaj vi ankaŭ estos frakasita meze de la necirkumciditoj, kaj kuŝos kun tiuj, kiuj estas mortigitaj de glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Tie estas Edom kun siaj reĝoj kaj kun ĉiuj siaj princoj, kiuj malgraŭ sia forteco estas ĵetitaj al tiuj, kiuj falis de glavo; ili kuŝas kun la necirkumciditoj, kaj kun tiuj, kiuj iris en la tombon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Tie estas ĉiuj princoj de la nordo, kaj ĉiuj Cidonanoj, kiuj malsupreniris kune kun la mortigitoj; ili hontas pri la teruro, kiun ĵetadis ilia forto; ili kuŝas necirkumciditaj kun tiuj, kiuj falis de glavo, kaj ili portas sian honton kun tiuj, kiuj iris en la tombon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Ilin Faraono vidos, kaj li konsoliĝos pri sia tuta popolo, mortigita de glavo, Faraono kaj lia tuta militistaro, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Ĉar Mi ĵetos Mian teruron sur la teron de la vivantoj; kaj inter la necirkumciditojn, kune kun tiuj, kiuj estas mortigitaj de glavo, estos metita Faraono kun sia tuta homomulto, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'Ho filo de homo, parolu al la filoj de via popolo, kaj diru al ili: Se Mi venigos glavon kontraŭ iun landon, kaj la popolo de la lando prenos el sia mezo unu viron kaj starigos lin ĉe si kiel observanton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'kaj se li, vidante la glavon, kiu iras kontraŭ la landon, ekblovos per trumpeto kaj avertos la popolon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'kaj se iu, aŭdinte la sonon de la trumpeto, ne akceptos la averton, kaj la glavo venos kaj prenos lin, tiam lia sango estos sur lia kapo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'li aŭdis la sonon de la trumpeto kaj tamen ne atentis la averton, tial lia sango estos sur lia kapo; sed kiu atentos la averton, tiu savos sian vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Sed se la observanto vidos la venantan glavon kaj ne blovos per trumpeto, kaj la popolo ne estos avertita, kaj la glavo venos kaj prenos la vivon de iu: tiam ĉi tiu estos prenita pro sia peko, sed lian sangon Mi repostulos el la mano de la observanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Kaj nun, ho filo de homo, Mi starigis vin kiel observanton por la domo de Izrael; kaj kiam vi aŭdos el Mia buŝo vorton, avertu ilin en Mia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Kiam Mi diros pri la malvirtulo: Malvirtulo, vi devas morti; kaj vi ne parolos, por averti la malvirtulon kontraŭ lia konduto: tiam li, la malvirtulo, mortos pro sia malvirteco, sed lian sangon Mi repostulos el via mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Sed se vi avertis la malvirtulon kontraŭ lia konduto, ke li deturnu sin de ĝi, kaj li ne deturnis sin de sia konduto: tiam li mortos pro sia malvirteco kaj vi savos vian vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Kaj vi, ho filo de homo, diru al la domo de Izrael: Vi diras: Niaj kulpoj kaj pekoj estas sur ni, kaj de ili ni konsumiĝas; kiel do ni povas vivi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Diru do al ili: Kiel Mi vivas, diras la Sinjoro, la Eternulo, Mi deziras ne la morton de malvirtulo, sed ke la malvirtulo deturnu sin de sia vojo kaj restu vivanta. Deturnu vin, deturnu vin de viaj malbonaj vojoj! kial vi mortu, ho domo de Izrael?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Kaj vi, ho filo de homo, diru al la filoj de via popolo: La virteco de virtulo ne savos lin en la tago de lia krimo, kaj malvirtulo ne falos pro sia malvirteco en la tago, kiam li deturnos sin de sia malvirteco; tiel same virtulo en la tago de sia peko ne povas resti vivanta kun ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Se Mi diros al la virtulo, ke li vivos, kaj li, fidante sian virtecon, faros krimon: tiam lia tuta virteco ne estos memorata, kaj li mortos pro sia krimo, kiun li faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Kaj se Mi diros al la malvirtulo, ke li mortos, sed li deturnos sin de sia peko kaj agados juste kaj virte;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'se la malvirtulo redonos la garantiaĵon, repagos la rabitaĵon, agados laŭ la leĝoj de la vivo, ne farante malbonagojn: tiam li restos vivanta kaj ne mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'Ĉiuj liaj pekoj, kiujn li faris, ne estos rememorataj: li agas juste kaj virte, kaj tial li restos vivanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Dume la filoj de via popolo diras: Ne ĝusta estas la vojo de la Sinjoro! Sed en efektiveco ilia vojo estas ne ĝusta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Se virtulo deturnas sin de sia virteco kaj faras malbonagojn, li mortas pro ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'kaj se malvirtulo deturnas sin de sia malvirteco kaj agas juste kaj virte, pro tio li restas vivanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Kaj vi diras: Ne ĝusta estas la vojo de la Sinjoro! Ĉiun el vi Mi juĝas konforme al lia konduto, ho domo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'En la dek-dua jaro de nia forkaptiteco, en la kvina tago de la deka monato, venis al mi forsaviĝinto el Jerusalem, kaj diris: La urbo estas disbatita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Sed la mano de la Eternulo aperis super mi en la vespero antaŭ la veno de la forsaviĝinto, kaj malfermis mian buŝon, antaŭ ol tiu venis al mi matene; kaj mia buŝo malfermiĝis, kaj mi ne plu devis silenti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Ho filo de homo! la loĝantoj de tiuj dezertaj lokoj sur la tero de Izrael parolas tiele: Abraham estis unu sola homo, kaj ricevis herede la landon; sed ni estas multo, des pli apartenas al ni la lando kiel heredaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Tial diru al ili: Tiele diras la Sinjoro, la Eternulo: Vi manĝas kun sango, kaj viajn okulojn vi levas al viaj idoloj, kaj sangon vi verŝas; kaj tamen vi volas posedi la landon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Vi apogas vin sur via glavo, vi faras abomenindaĵon, vi malpurigas unu la edzinon de la alia; kaj tamen vi volas posedi la landon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Diru al ili jenon: Tiele diras la Sinjoro, la Eternulo: Kiel Mi vivas, tiuj, kiuj troviĝas sur la ruinoj, falos de glavo; kiu estas sur la kampo, tiun Mi transdonos kiel manĝaĵon al la bestoj; kaj tiuj, kiuj estas en fortikaĵoj kaj en kavernoj, mortos de pesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Kaj Mi faros la landon absoluta dezerto, kaj malaperos ĝia fiera forto; kaj la montoj de Izrael dezertiĝos tiel, ke neniu tie pasos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'Kaj oni ekscios, ke Mi estas la Eternulo, kiam Mi plene dezertigos la landon pro ĉiuj iliaj abomenindaĵoj, kiujn ili faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'Kaj koncerne vin, ho filo de homo, la filoj de via popolo interparolas pri vi ĉe la muroj kaj ĉe la pordoj de la domoj, kaj unu al la alia parolas jene: Iru, kaj aŭskultu, kia estas la vorto, kiu eliris de la Eternulo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'Kaj ili venas al vi kiel al popola kunveno, kaj Mia popolo sidiĝas antaŭ vi, kaj aŭskultas viajn vortojn, sed ne plenumas ilin; ĉar voluptajn kantojn ili faras el tio en siaj buŝoj, kaj ilia koro celas nur profiton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'Vi estas por ili kiel volupta kanto, kiel homo kun bela voĉo kaj bone kantanta; ili aŭskultas viajn vortojn, sed ne plenumas ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Sed kiam plenumiĝos tio, kio devas plenumiĝi, tiam ili ekscios, ke profeto estis meze de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Ho filo de homo, profetu pri la paŝtistoj de Izrael, profetu, kaj diru al ili, al la paŝtistoj: Tiele diras la Sinjoro, la Eternulo: Ve al la paŝtistoj de Izrael, kiuj paŝtas sin mem! ĉu ne la ŝafojn devas paŝti la paŝtistoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'La grasaĵon vi manĝas, per la lano vi vin vestas, la grasigitan ŝafon vi buĉas; sed la ŝafojn vi ne paŝtas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'La malfortajn vi ne flegas, malsanan vi ne kuracas, vunditan vi ne bandaĝas, forerarintan vi ne revenigas, perditan vi ne serĉas; sed vi regas super ili maldelikate kaj kruele.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Kaj ili diskuris, ĉar ili ne havas paŝtiston; kaj ili fariĝis manĝaĵo por ĉiuj bestoj de la kampo, ili diskuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Erarvagas Miaj ŝafoj sur ĉiuj montoj kaj sur ĉiuj altaj montetoj, kaj sur la tutan teron diskuris Miaj ŝafoj, kaj neniu demandas pri ili, neniu ilin serĉas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Tial, ho paŝtistoj, aŭskultu la vorton de la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Kiel Mi vivas, diras la Sinjoro, la Eternulo: pro tio, ke Miaj ŝafoj fariĝis rabataĵo, kaj pro foresto de paŝtisto Miaj ŝafoj fariĝis manĝaĵo por ĉiuj bestoj de la kampo, kaj Miaj paŝistoj ne serĉis Miajn ŝafojn, kaj la paŝtistoj paŝtis sin mem, sed Miajn ŝafojn ili ne paŝtis -');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'pro tio, ho paŝtistoj, aŭskultu la vorton de la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Tiele diras la Sinjoro, la Eternulo: Jen Mi iras kontraŭ la paŝtistojn, kaj Mi elpostulos Miajn ŝafojn el iliaj manoj, kaj Mi forprenos de ili la paŝtadon de ŝafoj, kaj la paŝtistoj jam ne plu paŝtos sin mem, kaj Mi savos Miajn ŝafojn el ilia buŝo, por ke ili ne plu estu manĝaĵo por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Ĉar tiele diras la Sinjoro, la Eternulo: Jen Mi venos, kaj Mi serĉos Miajn ŝafojn kaj esploros ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Kiel paŝtisto esploras sian ŝafaron, kiam li alvenas al siaj diskurintaj ŝafoj, tiel Mi esploros Miajn ŝafojn; kaj Mi savos ilin el ĉiuj lokoj, kien ili diskuris en la tago nuba kaj malluma.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'Mi elkondukos ilin el inter la popoloj, Mi kolektos ilin el la diversaj landoj, Mi revenigos ilin sur ilian teron; kaj Mi paŝtos ilin sur la montoj de Izrael, en la valoj, kaj sur ĉiuj loĝeblaj lokoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Sur bona paŝtejo Mi ilin paŝtos, kaj sur la altaj montoj de Izrael estos ilia loĝloko; tie ili ripozos en bona restejo, kaj paŝtiĝos sur grasa paŝtejo, sur la montoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Mi paŝtos Miajn ŝafojn, kaj Mi ripozigos ilin, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'La ŝafon perdiĝintan Mi elserĉos, la forpelitan Mi revenigos, la vunditan Mi bandaĝos, la malsanan Mi fortigos; sed la grasan kaj fortan Mi ekstermos; Mi paŝtos kun justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Kaj pri vi, ho Miaj ŝafoj, tiele diras la Sinjoro, la Eternulo: Jen Mi faros juĝon inter ŝafo kaj ŝafo, al virŝafoj kaj virkaproj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Ĉu ne sufiĉas al vi, ke vi paŝtiĝas sur bona paŝtejo? la restaĵon sur via paŝtejo vi dispremas per viaj piedoj! Ĉu ne sufiĉas, ke vi trinkas puran akvon? la restaĵon vi movmalklarigas per viaj piedoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'Kaj Miaj ŝafoj devas manĝi tion, kio estas dispremita per viaj piedoj, kaj trinki tion, kio estas malklarigita per viaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Tial tiele diras al ili la Sinjoro, la Eternulo: Jen Mi venos, kaj Mi faros juĝon inter ŝafo grasa kaj ŝafo malgrasa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Ĉar vi puŝas per la flanko kaj per la ŝultro kaj frapas per viaj kornoj ĉiujn malfortajn, ĝis vi forpelas ilin eksteren,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'Mi helpos al Miaj ŝafoj, kaj ili ne plu estos prirabataj, kaj Mi faros juĝon inter ŝafo kaj ŝafo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'Kaj Mi starigos super ili unu paŝtiston, kiu paŝtos ilin, Mian servanton David; li paŝtos ilin, kaj li estos por ili paŝtisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Kaj Mi, la Eternulo, estos por ili Dio, kaj Mia servanto David estos princo inter ili; Mi, la Eternulo, tion parolis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'Kaj Mi faros kun ili interligon de paco, kaj Mi malaperigos ĉiujn sovaĝajn bestojn el la lando, por ke oni povu loĝi en la dezerto sendanĝere kaj dormi en la arbaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'Kaj Mi faros ilin kaj la ĉirkaŭaĵon de Mia monteto objekto de beno, kaj Mi sendados pluvon en ĝia tempo, tio estos pluvoj de beno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'Kaj la arbo de la kampo donados siajn fruktojn, kaj la tero donados siajn produktaĵojn, kaj ili estos sur sia tero ekster danĝero; kaj ili ekscios, ke Mi estas la Eternulo, kiam Mi rompos la stangojn de ilia jugo, kaj savos ilin el la manoj de tiuj, kiuj sklavigis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'Kaj ili ne plu estos prirabataj de la nacioj, kaj la bestoj de la tero ne manĝegos ilin; kaj ili loĝos sendanĝere, kaj neniu teruros ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'Kaj Mi aranĝos por ili gloran plantadon, kaj ili ne plu estos ekstermataj de malsato en la lando, kaj ili ne plu havos malhonoron inter la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'Kaj oni ekscios, ke Mi, la Eternulo, ilia Dio, estas kun ili, kaj ke ili, la domo de Izrael, estas Mia popolo, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Kaj vi, homoj, estas Miaj ŝafoj, la ŝafoj de Mia paŝtejo, kaj Mi estas via Dio, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Ho filo de homo, turnu vian vizaĝon al la monto Seir, kaj profetu pri ĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'kaj diru al ĝi: Tiele diras la Sinjoro, la Eternulo: Jen Mi iras kontraŭ vin, ho monto Seir, kaj Mi etendos Mian manon kontraŭ vin kaj faros vin absoluta dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Viajn urbojn Mi ruinigos, kaj vi mem dezertiĝos; kaj vi ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Ĉar vi havis eternan malamon, kaj elmetadis la Izraelidojn al glavo en la tempo de ilia malfeliĉo, kiam iliaj malbonagoj finiĝis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'tial, kiel Mi vivas, diras la Sinjoro, la Eternulo, Mi faros vin sanganta, kaj sanga venĝo vin persekutos; ĉar vi ne malamis sangon, tial sanga venĝo vin persekutos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'Kaj Mi faros la monton Seir absoluta dezerto, kaj Mi malaperigos sur ĝi ĉian pasanton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'Mi plenigos ĝiajn altaĵojn de mortigitoj: sur viaj montetoj, en viaj valoj, kaj en ĉiuj viaj terfendoj kuŝos falintoj, mortigitaj de glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Mi faros vin eterna dezerto, kaj viaj urboj ne estos loĝataj; kaj vi ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Pro tio, ke vi diris: Tiuj du popoloj kaj du landoj apartenos al mi, kaj ni ekposedos ilin, kvankam tie estas la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'tial, kiel Mi vivas, diras la Eternulo, Mi agos kun vi konforme al via kolero, kaj al via envio, kiun vi elmontris en via malamo kontraŭ ili; kaj oni ekkonos Min ĉe ili, kiam Mi juĝos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'Kaj vi ekscios, ke Mi, la Eternulo, aŭdis ĉiujn viajn insultojn, kiujn vi eldiris pri la montoj de Izrael, dirante: Ili estas dezertigitaj kaj transdonitaj al ni, por ke ni konsumu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Vi faris vin grandaj antaŭ Mi per via buŝo, kaj vi multe parolis kontraŭ Mi; Mi tion aŭdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Tiele diras la Sinjoro, la Eternulo: Kiam la tuta tero ĝojos, Mi faros vin dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Kiel vi ĝojis pri la heredaĵo de la domo de Izrael, kiam ĝi dezertiĝis, tiel Mi agos kun vi: vi fariĝos dezerto, ho monto Seir kaj la tuta Edomujo; kaj oni ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'Kaj vi, ho filo de homo, profetu pri la montoj de Izrael, kaj diru: Ho montoj de Izrael, aŭskultu la vorton de la Eternulo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'Tiele diras la Sinjoro, la Eternulo: Ĉar la malamiko diras pri vi: Ha, ha! ankaŭ la eternaj altaĵoj fariĝis niaj posedaĵoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'tial profetu, kaj diru: Tiele diras la Sinjoro, la Eternulo: Pro tio, ĝuste pro tio, ke oni dezertigis vin kaj premis vin de ĉiuj flankoj, por ke vi fariĝu heredaĵo por la aliaj nacioj, kaj oni prenis vin sur sian langon kaj la popoloj vin kalumnias,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'tial, ho montoj de Izrael, aŭskultu la vorton de la Sinjoro, la Eternulo: Tiele diras la Sinjoro, la Eternulo, al la montoj kaj al la montetoj, al la terfendoj kaj al la valoj, al la dezertigitaj ruinoj kaj al la forlasitaj urboj, kiuj fariĝis rabataĵo kaj mokataĵo por la aliaj nacioj ĉirkaŭe;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'tiele diras la Sinjoro, la Eternulo: Kredu, ke en la fajro de Mia fervoro Mi parolis pri la aliaj nacioj kaj pri la tuta Edomujo, kiuj alproprigis al si Mian landon kun tutkora ĝojo kaj kun mokado, por prirabi ĝiajn produktaĵojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'tial profetu pri la lando de Izrael, kaj diru al la montoj kaj al la montetoj, al la terfendoj kaj al la valoj: Tiele diras la Sinjoro, la Eternulo: Jen Mi parolis en Mia fervoro kaj en Mia kolero, pro tio, ke vi suferas malhonoron de la nacioj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'tial tiele diras la Sinjoro, la Eternulo: Mi ĵuras per levo de Mia mano, ke la nacioj, kiuj estas ĉirkaŭ vi, suferos malhonoron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'sed vi, montoj de Izrael, elkreskigos viajn branĉojn kaj alportados viajn fruktojn al Mia popolo Izrael; ĉar ili baldaŭ venos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Ĉar jen Mi venos al vi, Mi turnos Mian vizaĝon al vi, kaj vi estos prilaborataj kaj prisemataj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'kaj Mi aperigos sur vi multe da homoj, la tutan domon de Izrael, ilin ĉiujn; kaj la urboj fariĝos loĝataj, kaj la ruinoj estos rekonstruataj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'Mi aperigos sur vi multe da homoj kaj brutoj, kaj ili multiĝos kaj fruktoriĉiĝos; kaj Mi faros vin loĝataj, kiel en via antaŭa tempo, kaj Mi bonfarados al vi pli ol en via komenco; kaj vi ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Mi venigos sur vin homojn, Mian popolon Izrael; kaj ili posedos vin, kaj vi estos ilia heredaĵo, kaj vi ne plu seninfanigos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Tiele diras la Sinjoro, la Eternulo: Pro tio, ke oni diras al vi: Vi formanĝas homojn, kaj vi seninfanigis vian popolon-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'pro tio vi nun ne plu manĝos homojn, kaj vian popolon vi ne plu seninfanigos, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'Kaj Mi ne plu aŭdigos kontraŭ vi insultadon de la nacioj, kaj vi ne plu havos malhonoron de la flanko de popoloj, kaj vian popolon vi ne plu seninfanigos, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Ho filo de homo! la domo de Izrael, loĝante sur sia tero, malpurigis ĝin per sia konduto kaj per siaj agoj; kiel la malpuraĵo de virino dum ŝia monataĵo estis antaŭ Mi ilia konduto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Kaj Mi elverŝis sur ilin Mian koleron pro la sango, kiun ili verŝadis sur la teron, kaj pro tio, ke ili malpurigadis ĝin per siaj idoloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'kaj Mi disĵetis ilin inter la naciojn, kaj ili estis dispelitaj en la diversajn landojn; konforme al ilia konduto kaj al iliaj agoj Mi faris juĝon kontraŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'Kaj ili aliĝis al la nacioj, al kiuj ili venis, kaj malsanktigis Mian sanktan nomon tiel, ke oni diris pri ili: Ĉu tio estas la popolo de la Eternulo, kiu devis eliri el Lia lando?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Sed Mi domaĝis Mian sanktan nomon, kiun la domo de Izrael malsanktigis inter la nacioj, kien ili venis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Tial diru al la domo de Izrael: Tiele diras la Sinjoro, la Eternulo: Ne pro vi Mi agas, ho domo de Izrael, sed nur pro Mia sankta nomo, kiun vi malsanktigis inter la nacioj, kien vi venis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Kaj Mi sanktigos Mian grandan nomon, malsanktigitan ĉe la nacioj, kiun vi malsanktigis inter ili; kaj la nacioj ekscios, ke Mi estas la Eternulo, diras la Sinjoro, la Eternulo, kiam Mi montros sur vi Mian sanktecon antaŭ iliaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Mi prenos vin el inter la nacioj, Mi kolektos vin el ĉiuj landoj, kaj Mi venigos vin en vian landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'Kaj Mi aspergos vin per pura akvo, kaj vi puriĝos de ĉiuj viaj malpuraĵoj, kaj de ĉiuj viaj idoloj Mi purigos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'Kaj Mi donos al vi koron novan, kaj spiriton novan Mi metos en vin; Mi eligos el via korpo la ŝtonan koron, kaj Mi donos al vi koron karnan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Kaj Mian spiriton Mi metos en vin, kaj Mi faros, ke vi agados laŭ Miaj leĝoj, kaj Miajn ordonojn vi observados kaj plenumados.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'Kaj vi loĝos en la lando, kiun Mi donis al viaj patroj; kaj vi estos Mia popolo, kaj Mi estos via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'Kaj Mi liberigos vin de ĉiuj viaj malpuraĵoj; Mi vokos la grenon kaj multigos ĝin, kaj Mi ne venigos sur vin malsaton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'Mi multigos la fruktojn de la arboj kaj la produktaĵojn de la kampo, por ke vi ne plu havu antaŭ la nacioj honton pri malsato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Tiam vi rememoros vian malbonan konduton kaj viajn nebonajn agojn, kaj vi faros al vi mem riproĉojn pro viaj malbonagoj kaj pro viaj abomenindaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Ne pro vi Mi agas, diras la Sinjoro, la Eternulo; tion vi sciu. Hontu kaj ruĝiĝu pri via konduto, ho domo de Izrael!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'Tiele diras la Sinjoro, la Eternulo: En la tempo, kiam Mi purigos vin de ĉiuj viaj malbonagoj kaj loĝatigos la urbojn, kaj la ruinoj estos rekonstruitaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'kaj la dezertigita tero estos prilaborata anstataŭ tio, ke ĝi estis dezerto antaŭ la okuloj de ĉiu pasanto:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'tiam oni diros: Ĉi tiu dezertigita tero fariĝis kiel la ĝardeno Eden, kaj la urboj ruinigitaj, dezertigitaj, kaj detruitaj estas nun fortikigitaj kaj loĝataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'Kaj ekscios la nacioj, kiuj restos ĉirkaŭ vi, ke Mi, la Eternulo, rekonstruis la detruitaĵon, priplantis la dezertigitaĵon; Mi, la Eternulo, tion diris, kaj Mi tion plenumos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'Tiele diras la Sinjoro, la Eternulo: Ankoraŭ en tio Mi trovigos Min al la domo de Izrael, kaj faros al ili: Mi multigos ĉe ili la homojn kiel ŝafojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Kiel la sanktaj ŝafoj, kiel la ŝafoj de Jerusalem dum ĝiaj festoj, tiel la dezertigitaj urboj pleniĝos de amasoj da homoj; kaj oni ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Aperis super mi la mano de la Eternulo, kaj elirigis min en la inspiro de la Eternulo, kaj starigis min meze de ebenaĵo, kiu estis plena de ostoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'Kaj Li kondukis min ĉirkaŭe ĉirkaŭ ili; estis tre multe da ili sur la ebenaĵo, kaj ili estis tre sekaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'Kaj Li diris al mi: Ho filo de homo! ĉu reviviĝos ĉi tiuj ostoj? Mi respondis: Ho Sinjoro, ho Eternulo, nur Vi tion scias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Kaj Li diris al mi: Profetu pri ĉi tiuj ostoj, kaj diru al ili: Ho sekaj ostoj, aŭskultu la vorton de la Eternulo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Tiele diras la Sinjoro, la Eternulo, al ĉi tiuj ostoj: Jen Mi venigos en vin spiriton, kaj vi reviviĝos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'kaj Mi donos al vi tendenojn, Mi kreskigos ĉirkaŭ vi karnon, Mi kovros vin per haŭto, Mi enmetos en vin spiriton, kaj vi reviviĝos; kaj vi ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Kaj mi profetis, kiel estis ordonite al mi; kaj kiam mi eldiris mian profetaĵon, fariĝis bruo kaj tumulto, kaj la ostoj komencis alproksimiĝadi, ĉiu osto al sia osto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'Kaj mi vidis: jen sur ili estas tendenoj, kaj elkreskis karno, kaj haŭto kovris ilin supre; sed spirito en ili ne estis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Kaj Li diris al mi: Profetu al la spirito, profetu, ho filo de homo, kaj diru al la spirito: Tiele diras la Sinjoro, la Eternulo: El la kvar ventoj venu, ho spirito, kaj ekblovu sur ĉi tiujn mortigitojn, por ke ili reviviĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Kaj mi profetis, kiel Li ordonis al mi; kaj eniris en ilin spirito, kaj ili reviviĝis kaj stariĝis sur siaj piedoj, tre, tre granda armeo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Kaj Li diris al mi: Ho filo de homo! ĉi tiuj ostoj estas la tuta domo de Izrael. Jen ili diras: Sekiĝis niaj ostoj, kaj pereis nia espero, decidita estas nia sorto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Tial profetu, kaj diru al ili: Tiele diras la Sinjoro, la Eternulo: Jen Mi malfermos viajn tombojn kaj elirigos vin el viaj tomboj, ho Mia popolo, kaj Mi venigos vin en la landon de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'Kaj vi ekscios, ke Mi estas la Eternulo, kiam Mi malfermos viajn tombojn kaj elirigos vin el viaj tomboj, ho Mia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'Kaj Mi enmetos Mian spiriton en vin, kaj vi reviviĝos, kaj Mi aranĝos vin en via lando; kaj vi ekscios, ke Mi, la Eternulo, tion parolis kaj faris, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'Vi, ho filo de homo, prenu al vi lignon, kaj skribu sur ĝi: De Jehuda, kaj de la Izraelidoj, aliĝintaj al li. Poste prenu ankoraŭ unu lignon, kaj skribu sur ĝi: De Jozef, ligno de Efraim, kaj de la tuta domo de Izrael, kiu aliĝis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'Kaj aligu ilin al vi unu al la alia kiel unu lignon, ke ili fariĝu unu en via mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'Kaj kiam la filoj de via popolo demandos vin: Ĉu vi ne klarigos al ni, kion tio signifas ĉe vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'tiam diru al ili: Tiele diras la Sinjoro, la Eternulo: Jen Mi prenos la lignon de Jozef, kiu estas en la manoj de Efraim kaj de la triboj de Izrael, kiuj aliĝis al li; kaj Mi aligos ĝin kun ili al la ligno de Jehuda, kaj Mi faros ilin unu ligno, kaj ili estos unu en Mia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'Kaj la lignoj, sur kiuj vi estos skribinta, estu en via mano antaŭ iliaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'Kaj diru al ili: Tiele diras la Sinjoro, la Eternulo: Jen Mi prenos la Izraelidojn el inter la nacioj, kien ili iris, kaj Mi kolektos ilin de ĉirkaŭe kaj venigos ilin en ilian landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'Kaj Mi faros ilin unu nacio en la lando, sur la montoj de Izrael, kaj unu reĝo estos reĝo por ili ĉiuj; kaj ili ne plu estos du popoloj kaj ne plu estos dividitaj en du regnojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'Kaj ili ne plu sin malpurigos per siaj idoloj kaj per siaj abomenindaĵoj kaj per ĉiuj siaj krimoj; kaj Mi liberigos ilin el ĉiuj iliaj loĝlokoj, en kiuj ili pekis, kaj Mi purigos ilin; kaj ili estos Mia popolo, kaj Mi estos ilia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'Kaj Mia servanto David estos reĝo super ili, kaj unu paŝtisto estos por ili ĉiuj; kaj ili sekvos Miajn decidojn, kaj Miajn leĝojn ili observos kaj plenumos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'Kaj ili loĝos en la lando, kiun Mi donis al Mia servanto Jakob kaj en kiu loĝis viaj patroj; kaj ili loĝos en ĝi, ili kaj iliaj infanoj, kaj la infanoj de iliaj infanoj, eterne; kaj Mia servanto David estos por ili princo eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Kaj Mi faros kun ili interligon de paco; ĝi estos eterna interligo kun ili; Mi aranĝos kaj multigos ilin, kaj Mi starigos Mian sanktejon inter ili por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'Kaj Mi loĝos inter ili; kaj Mi estos ilia Dio, kaj ili estos Mia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'Kaj la nacioj ekscios, ke Mi, la Eternulo, sanktigas Izraelon, ĉar Mia sanktejo estos inter ili por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'Ho filo de homo, turnu vian vizaĝon al Gog, en la lando Magog, ĉefa princo de Meŝeĥ kaj Tubal, kaj profetu pri li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'kaj diru: Tiele diras la Sinjoro, la Eternulo: Jen Mi iras kontraŭ vin, ho Gog, ĉefa princo de Meŝeĥ kaj Tubal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Kaj Mi vagigos vin, Mi metos buŝbridaĵon en vian buŝon, kaj Mi elirigos vin kaj vian tutan militistaron, ĉevalojn kaj rajdistojn, ĉiujn en belegaj vestoj, grandan anaron, en kirasoj kaj kun ŝildoj, kun glavo en la mano;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Persojn, Etiopojn, kaj Putidojn, ĉiujn kun ŝildoj kaj kaskoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Gomeron kun ĉiuj ĝiaj taĉmentoj, la domon de Togarma, de la nordaj randoj, kun ĉiuj ĝiaj taĉmentoj; multaj popoloj estos kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Pretigu vin kaj aranĝu vin, vi kaj ĉiuj homamasoj, kiuj kolektiĝis al vi, kaj vi estu ilia gvidanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Post longa tempo vi estos elvokita; en la lastaj jaroj vi venos en la landon liberigitan el glavo, al la popolo, kolektita el inter multaj gentoj, sur la montojn de Izrael, kiuj ĉiam estis dezertaj, al la popolo, kiu estos elkondukita el inter la gentoj kaj nun tuta loĝas ekster danĝero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Kaj vi leviĝos, kaj venos kiel ventego; vi estos kiel nubego, kiu volas kovri la teron, vi kaj ĉiuj viaj taĉmentoj kaj la multaj popoloj kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Tiele diras la Sinjoro, la Eternulo: En tiu tempo venos en vian koron diversaj deziroj, kaj vi pripensos malbonajn intencojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'Kaj vi diros: Mi iros kontraŭ la landon nebaritan, mi iros kontraŭ la trankvilulojn, kiuj pensas, ke ili loĝas ekster danĝero, kiuj loĝas ĉiuj sen muroj kaj ne havas riglilojn nek pordojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'por ke mi faru rabadon kaj kaptu kaptaĵon, kaj metu la manon sur la denove loĝatajn ruinojn, kaj sur la popolon, kiu estas rekolektita el inter la nacioj, okupas sin per brutedukado kaj komercado, kaj loĝas sur la centro de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Ŝeba kaj Dedan, kaj la komercistoj de Tarŝiŝ, kaj ĉiuj ĝiaj potenculoj diros al vi: Ĉu ne por fari rabadon vi venis? ĉu ne por kapti kaptaĵon vi kolektis vian homomulton, por forporti arĝenton kaj oron, por preni brutojn kaj havaĵojn, por fari grandan rabadon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Tial profetu, ho filo de homo, kaj diru al Gog: Tiele diras la Sinjoro, la Eternulo: Ĉu vi ne scias pri tiu tempo, kiam Mia popolo Izrael devas loĝi sendanĝere?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'Vi venos de via loko, de la nordaj randoj, vi kaj multaj popoloj kun vi, ĉiuj rajdante sur ĉevaloj, granda homomulto kaj potenca armeo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'kaj vi iros kontraŭ Mian popolon Izrael kiel nubo, por kovri la landon. Tio okazos en la lasta tempo. Mi permesos al vi veni en Mian landon, por ke la nacioj ekkonu Min, kiam Mi montros sur vi Mian sanktecon antaŭ iliaj okuloj, ho Gog.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Tiele diras la Sinjoro, la Eternulo: Vi estas ja tiu, pri kiu Mi parolis en la antikva tempo per Miaj servantoj, la profetoj de Izrael, kiuj en tiu tempo antaŭdiris la jarojn, kiam Mi venigos vin sur ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'En tiu tempo, kiam Gog venos sur la teron de Izrael, diras la Sinjoro, la Eternulo, leviĝos Mia kolero kaj Mia indigno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'Kaj en Mia fervoro, en la fajro de Mia kolero Mi decidis, ke en tiu tempo estos granda tumulto sur la tero de Izrael;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'kaj ektremos antaŭ Mi la fiŝoj de la maro, la birdoj de la ĉielo, la bestoj de la kampo, ĉiuj rampaĵoj, kiuj rampas sur la tero, kaj ĉiuj homoj, kiuj estas sur la tero; kaj renversiĝos la montoj, falos la rokkrutaĵoj, kaj ĉiuj muroj falos sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Kaj Mi vokos kontraŭ lin glavon sur ĉiuj Miaj montoj, diras la Sinjoro, la Eternulo; ĉiu prenos glavon kontraŭ sian fraton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'Kaj Mi faros kontraŭ li juĝon per pesto kaj sangoverŝado; Mi sendos pluvegon, ŝtonan hajlon, fajron, kaj sulfuron sur lin kaj sur liajn taĉmentojn, kaj sur la multajn popolojn, kiuj estos kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'Kaj Mi montros Mian grandecon kaj sanktecon, kaj Mi konatigos Min antaŭ la okuloj de multaj popoloj; kaj ili ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'Kaj vi, ho filo de homo, profetu pri Gog, kaj diru: Tiele diras la Sinjoro, la Eternulo: Jen Mi iras kontraŭ vin, ho Gog, ĉefa princo de Meŝeĥ kaj Tubal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'Kaj Mi vagigos vin, allogos vin, levos vin de la nordaj randoj, kaj venigos vin sur la montojn de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Kaj Mi elbatos vian pafarkon el via maldekstra mano, kaj Mi elfaligos viajn sagojn el via dekstra mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Sur la montoj de Izrael vi falos, vi kaj ĉiuj viaj taĉmentoj, kaj la popoloj, kiuj estos kun vi; al ĉiaspecaj rabobirdoj kaj al la bestoj de la kampo Mi transdonos vin kiel manĝaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'Sur la kampo vi falos; ĉar Mi tion decidis, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'Kaj Mi sendos fajron sur Magogon kaj sur la eksterdanĝerajn loĝantojn de la insuloj; kaj oni ekscios, ke Mi estas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'Kaj Mian sanktan nomon Mi konatigos meze de Mia popolo Izrael, kaj Mi ne plu permesos malhonori Mian sanktan nomon; kaj la popoloj ekscios, ke Mi estas la Eternulo, la Sanktulo en Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Jen tio venos kaj plenumiĝos, diras la Sinjoro, la Eternulo; tio estos la tempo, pri kiu Mi parolis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Kaj eliros la loĝantoj de la urboj de Izrael, faros fajron, kaj bruligos la armilojn, la ŝildojn kaj kirasojn, la pafarkojn kaj sagojn, la ponardojn kaj lancojn; kaj ili bruligados per tio fajron en la daŭro de sep jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'Ili ne alportados lignon de la kampo, ne hakados el la arbaroj, sed per la armiloj ili farados fajron; ili prirabos siajn rabintojn, kaj prenos kaptaĵon de tiuj, kiuj prenis kaptaĵon de ili, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'En tiu tempo Mi donos al Gog tombolokon en Izrael, la valon, tra kiu oni iras orienten de la maro, kaj ĝi fortimigos la pasantojn, kaj tie oni enterigos Gogon kaj lian tutan homomulton, kaj oni nomos ĝin Valo de la Homomulto de Gog.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'Kaj la domo de Izrael enterigos ilin, por purigi la landon, en la daŭro de sep monatoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'Kaj la enterigadon faros la tuta popolo de la lando; kaj glora estos por ili tiu tempo, kiam Mi montros Mian majeston, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'Kaj ili destinos konstantajn homojn, kiuj irados tra la lando, kaj kune kun la trairantoj ili enterigados tiujn, kiuj restis sur la supraĵo de la tero, por purigi ĉi tiun; post paso de sep monatoj ili komencos la serĉadon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'Kaj kiam iu el la trairantoj de la lando vidos oston de homo, li starigos ĉe ĝi signon, ĝis la enterigantoj enterigos ĝin en la Valo de la Homomulto de Gog.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'Kaj eĉ la nomo de la urbo estos Homomulto. Kaj oni purigos la landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'Kaj vi, ho filo de homo, tiele diras la Sinjoro, la Eternulo: Diru al la ĉiaspecaj birdoj kaj al ĉiuj bestoj de la kampo: Kolektiĝu kaj venu, kunvenu de ĉirkaŭe al la buĉado, kiun Mi faras por vi, al la granda buĉado sur la montoj de Izrael; kaj vi manĝos karnon kaj trinkos sangon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Karnon de fortuloj vi manĝos, kaj sangon de princoj de la tero vi trinkos, kiel de virŝafoj, ŝafidoj, kaproj, kaj bovoj, ĉiuj bone grasigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'Kaj vi manĝos grasaĵon ĝissate, kaj vi trinkos sangon ĝisebrie de Mia buĉofero, kiun Mi buĉis por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'Kaj ĉe Mia tablo vi satiĝos de ĉevaloj kaj rajdantoj, de fortuloj kaj ĉiaspecaj militistoj, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'Kaj Mi montros Mian majeston inter la nacioj, kaj ĉiuj nacioj vidos Mian juĝon, kiun Mi faris, kaj Mian manon, kiun Mi metis sur ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'Kaj la domo de Izrael ekscios, ke Mi estas la Eternulo, ilia Dio, de tiu tempo kaj plue.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'Kaj la nacioj ekscios, ke la domo de Izrael estis forkondukita en kaptitecon pro siaj malbonagoj; pro tio, ke ili perfidis Min, Mi kaŝis Mian vizaĝon antaŭ ili kaj transdonis ilin en la manojn de iliaj malamikoj, kaj ili ĉiuj falis de glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Konforme al ilia malpureco kaj al iliaj krimoj Mi agis kun ili, kaj Mi kaŝis antaŭ ili Mian vizaĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Tial tiele diras la Sinjoro, la Eternulo: Nun Mi revenigos la forkaptitojn de Jakob, Mi kompatos la tutan domon de Izrael, kaj Mi fervoros pri Mia sankta nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Kaj ili konscios sian malhonoron, kaj ĉiujn siajn perfidojn, kiujn ili faris kontraŭ Mi, kiam ili sidos sendanĝere sur sia tero kaj neniu ilin timigos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'kiam Mi revenigos ilin el inter la popoloj kaj kolektos ilin el la landoj de iliaj malamikoj kaj montros sur ili Mian sanktecon antaŭ la okuloj de la multaj popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'Kaj ili ekscios, ke Mi, la Eternulo, estas ilia Dio, kiam, dispelinte ilin inter la naciojn, Mi rekolektos ilin en ilian landon kaj neniun plu restigos tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'Kaj Mi ne plu kaŝos Mian vizaĝon antaŭ ili, kiam Mi elverŝos Mian spiriton sur la domon de Izrael, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'En la dudek-kvina jaro de nia forkaptiteco, en la komenco de la jaro, en la deka tago de la monato, en la dek-kvara jaro post la disbato de la urbo, ĝuste en tiu tago aperis super mi la mano de la Eternulo kaj venigis min tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'En Dia vizio Li venigis min en la landon de Izrael, kaj starigis min sur tre alta monto, sur kiu sude estis kvazaŭ konstruaĵoj de urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'Kaj Li venigis min tien, kaj jen mi ekvidis viron, kies aspekto estis kiel aspekto de kupro; en la mano li havis fadenan ŝnureton kaj mezurstangon, kaj li staris ĉe pordego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'Kaj tiu viro ekparolis al mi: Ho filo de homo, rigardu per viaj okuloj, aŭskultu per viaj oreloj, kaj atentu per via koro ĉion, kion mi montros al vi; ĉar vi estas venigita ĉi tien, por ke mi tion montru al vi. Ĉion, kion vi vidos, raportu al la domo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'Kaj jen mi ekvidis muron ekster la domo ĉirkaŭe, kaj en la mano de la viro estis mezurstango, havanta la longon de ses ulnoj kun aldono po manlarĝo por ĉiu ulno; kaj li mezuris sur tiu konstruaĵo unu stangon laŭlarĝe kaj unu stangon laŭalte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Kaj li aliris al la pordego, kiu estis turnita orienten, kaj supreniris sur ĝia ŝtuparo; kaj li mezuris sur unu sojlo de la pordego la larĝon de unu stango kaj sur la dua sojlo la larĝon de unu stango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'Kaj en la flankaj ĉambretoj li mezuris unu stangon da longo kaj unu stangon da larĝo, kaj inter la ĉambretoj kvin ulnojn; kaj sur la sojlo de la pordego apud la portiko, kondukanta al la interna pordego, ankaŭ unu stangon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Kaj en la portiko de la interna pordego li mezuris unu stangon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'En la portiko de la pordego li mezuris ok ulnojn kaj sur ĝiaj kolonoj du ulnojn; la portiko de la pordego estis interne de la konstruaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'Da flankaj ĉambretoj ĉe la orienta pordego estis tri sur unu flanko kaj tri sur la alia flanko; ĉiuj tri havis unu mezuron, kaj ankaŭ la ambaŭflankaj kolonoj havis unu mezuron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Li mezuris la larĝon de la enirejo de la pordego, dek ulnojn; laŭlonge de la pordego li mezuris dek tri ulnojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'La spaco antaŭ la ĉambretoj estis po unu ulno sur ambaŭ flankoj, kaj la ĉambretoj havis po ses ulnoj sur ambaŭ flankoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Kaj li mezuris la pordegon de la tegmento de unu ĉambreto ĝis la tegmento de la dua ĉambreto, dudek kvin ulnojn laŭlarĝe; unu pordo estis kontraŭ la alia pordo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'Kaj en la kolonoj li kalkulis sesdek ulnojn, en la kolonoj de la korto kaj de la pordego ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'Kaj de la antaŭo de la pordego de la eniro ĝis la antaŭo de la interna portiko de la pordego estis kvindek ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Kaj kovritaj fenestroj estis en la flankaj ĉambretoj kaj en la vestibloj kun direkto internen, ĉirkaŭe de la pordego; tiel ankaŭ en la vestibloj la fenestroj estis direktitaj ĉe ĉiuj flankoj internen, kaj sur la kolonoj estis pentritaj palmoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Kaj li venigis min sur la korton eksteran; kaj tie mi ekvidis ĉambrojn kaj pavimon, faritan ĉirkaŭe ĉe la korto; tridek ĉambroj estis sur la pavimo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'La pavimo estis flanke de la pordegoj; laŭlonge de la pordegoj la pavimo estis pli malalte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Kaj li mezuris la larĝon deloke de la malsupra pordego ĝis la ekstera rando de la interna korto, cent ulnojn orienten kaj norden.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'Li mezuris ankaŭ la longon kaj la larĝon de la norden turnita pordego de la ekstera korto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'Kaj da flankaj ĉambretoj estis ambaŭflanke po tri; kaj ĝiaj kolonoj kaj portikoj havis la saman mezuron, kiel ĉe la unua pordego: kvindek ulnojn da longo kaj dudek kvin ulnojn da larĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'Ĝiaj fenestroj kaj vestibloj kaj palmornamoj havis la saman mezuron, kiel la pordego turnita orienten; per sep ŝtupoj oni leviĝadis sur ĝin; kaj antaŭ ĝi estis ĝia vestiblo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Kaj la pordegoj de la interna korto estis kontraŭ la pordegoj norda kaj orienta; kaj li mezuris de pordego ĝis pordego cent ulnojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Kaj li kondukis min suden; kaj jen estis pordego turnita suden; kaj li mezuris ĝiajn kolonojn kaj vestiblojn, kaj ilia mezuro estis la sama, kiel ĉe la aliaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'Kaj fenestrojn kaj vestiblojn ĉirkaŭe ĝi havis tiajn samajn, kiel tiuj fenestroj; la longo de la pordego estis kvindek ulnoj, kaj la larĝo dudek kvin ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'Kaj por supreniri ĝi havis sep ŝtupojn, kaj iliaj vestibloj estis antaŭ ili, kaj palmornamojn ĝiaj kolonoj havis po unu sur unu flanko kaj unu sur la alia flanko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Ankaŭ ĉe la interna korto estis pordego turnita suden; kaj li mezuris de unu pordego al la alia, turnita suden, cent ulnojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Kaj li venigis min sur la internan korton tra la suda pordego; kaj li mezuris ĉe la suda pordego la saman mezuron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'Kaj ĝiaj ĉambretoj kaj kolonoj kaj portikoj havis la saman mezuron, kiel tiuj; kaj fenestrojn ĝi kaj ĝiaj portikoj havis ĉirkaŭe; ĉio havis la longon de kvindek ulnoj kaj la larĝon de dudek kvin ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'Kaj la portikoj ĉirkaŭe havis la longon de dudek kvin ulnoj kaj la larĝon de kvin ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'Estis ankaŭ portiko al la ekstera korto, kaj palmornamoj sur la kolonoj, kaj ok ŝtupoj por leviĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Kaj li venigis min sur la internan korton al la orienta flanko; kaj li mezuris ĉe la pordego la samajn mezurojn, kiel ĉe la aliaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'Kaj ĝiaj ĉambretoj kaj kolonoj kaj portikoj havis la samajn mezurojn; kaj fenestrojn ĝi kaj ĝiaj portikoj havis ĉirkaŭe; ĉio havis la longon de kvindek ulnoj kaj la larĝon de dudek kvin ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Estis ankaŭ portiko al la ekstera korto, kaj palmornamoj sur la kolonoj ambaŭflanke, kaj ok ŝtupoj por leviĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Kaj li venigis min al la norda pordego; kaj li mezuris tie tiajn samajn mezurojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'Ĝi havis ĉambretojn, kolonojn, kaj portikojn, kaj fenestrojn ĉirkaŭe; ĉio havis la longon de kvindek ulnoj kaj la larĝon de dudek kvin ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'Kaj ĝiaj kolonoj staris en la direkto al la ekstera korto, kaj palmornamoj estis sur la kolonoj ambaŭflanke, kaj ok ŝtupoj por leviĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Estis ankaŭ ĉambro kun sia enirejo apud la kolonoj ĉe la pordegoj; tie oni lavadis la bruloferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'En la portiko de la pordego staris du tabloj sur unu flanko kaj du tabloj sur la dua flanko, por buĉi sur ili la bruloferon, pekoferon, kaj kulpoferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'Ĉe la ekstera flanko apud la enirejo de la norda pordego staris du tabloj, kaj ĉe la dua flanko, apud la portiko de la pordego, staris ankaŭ du tabloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'Kvar tabloj unuflanke kaj kvar tabloj aliaflanke staris ĉe la flankoj de la pordego: ok tabloj, sur kiuj oni buĉadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'Kaj kvar tabloj por bruloferoj estis el ĉirkaŭhakitaj ŝtonoj, kaj havis la longon de unu ulno kaj duono kaj la larĝon de unu ulno kaj duono kaj la alton de unu ulno; sur ili oni kuŝigadis la ilojn, per kiuj oni buĉadis la bruloferon kaj aliajn oferojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'Kaj listeloj, havantaj la larĝon de unu manplato, estis ĉe la muroj de la domo ĉirkaŭe; kaj sur la tablojn oni metadis la viandon de la ofero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Ekstere de la interna pordego estis ĉambroj por kantistoj, ĉe la interna korto, flanke de la norda pordego; ili estis turnitaj per sia vizaĝa flanko suden, sed unu, flanke de la orienta ĉambro, estis turnita norden.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'Kaj li diris al mi: Ĉi tiu ĉambro, kiu estas turnita suden, estas por la pastroj, kiuj plenumas la servadon en la domo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'kaj la ĉambro, kiu estas turnita per sia vizaĝa flanko norden, estas por la pastroj, kiuj plenumas la servadon ĉe la altaro: tio estas la filoj de Cadok, kiuj solaj el la idoj de Levi povas alproksimiĝi al la Eternulo, por servi al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'Kaj li mezuris la korton: ĝi havis la longon de cent ulnoj kaj la larĝon de cent ulnoj, ĝi estis kvadrata; kaj la altaro staris antaŭ la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Kaj li venigis min en la vestiblon de la domo; kaj li mezuris ĉe kolono de la portiko kvin ulnojn ĉe unu flanko kaj kvin ulnojn ĉe la dua flanko; kaj la larĝo de la pordego estis tri ulnoj ĉe unu flanko kaj tri ulnoj ĉe la dua flanko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'La longo de la portiko estis dudek ulnoj, kaj la larĝo dek unu ulnoj, kaj ĝi havis ŝtupojn por supreniri; kaj la kolonoj havis bazaĵojn, unu ĉe unu flanko kaj unu ĉe la alia flanko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Kaj li venigis min en la templon; kaj li mezuris ĉe la kolonoj ses ulnojn da larĝo ĉe unu flanko kaj ses ulnojn da larĝo ĉe la alia flanko, laŭlarĝe de la tabernaklo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'La larĝo de la pordo estis dek ulnoj, kaj la flankoj de la pordo havis la larĝon de kvin ulnoj ĉe unu flanko kaj kvin ulnoj ĉe la alia flanko; kaj li mezuris la longon de la templo, kvardek ulnojn, kaj la larĝon, dudek ulnojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Kaj li eniris internen, kaj mezuris sur la kolono de la pordo du ulnojn kaj sur la pordo mem ses ulnojn; kaj la larĝo de la pordo estis sep ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Kaj li mezuris en la longo de la templo dudek ulnojn kaj en la larĝo dudek ulnojn en la interna parto de la templo; kaj li diris al mi: Ĉi tio estas la plejsanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Kaj li mezuris la muron de la domo, kiu havis ses ulnojn da diko, kaj la larĝo de la flanka galerio ĉirkaŭe de la tuta domo estis kvar ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Kaj la flankaj galerioj, unu apud la alia, havis la longon de tridek tri futoj, kaj limiĝis per la muro, kiu estis ĉe la domo por la galerioj ĉirkaŭe, por ke ili estu kunigitaj inter si, sed ne kunigitaj kun la muro de la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'Kaj la larĝo kaj amplekso de la flankaj galerioj estis des pli grandaj ju pli alte; ĉar ankaŭ la domo estis ju pli alte des pli ampleksa ĉiuflanke, kaj supre la domo estis pli larĝa; kaj el la malsupra galerio oni povis iri en la supran tra la meza.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Kaj mi vidis ĉe la domo ĉirkaŭe altaĵon, kiu estis la fundamento por la galerioj kaj havis la larĝon de tuta stango de ses ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'La larĝo de la muro de la galerio ekstere estis kvin ulnoj, kaj libera loko kondukis al la galerioj de la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'Kaj la interspaco inter la oficaj ĉambroj, kiuj estis ĉiuflanke ĉirkaŭ la domo, estis dudek ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'Kaj estis pordoj el la galerioj al la libera loko, unu pordo turnita norden kaj unu pordo suden; la larĝo de la libera loko estis kvin ulnoj ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'La konstruaĵo, kiu estis turnita al la placo okcidenten, havis la larĝon de sepdek ulnoj; kaj la muro de la konstruaĵo havis la larĝon de kvin ulnoj ĉiuflanke, kaj ĝia longo estis naŭdek ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Kaj li mezuris la longon de la domo, cent ulnojn; kaj la placo kaj la konstruaĵo kaj ĝiaj muroj havis ankaŭ la longon de cent ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'Kaj la larĝo de la antaŭa flanko de la domo kaj la placo orienta havis ankaŭ cent ulnojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Kaj li mezuris la longon de la konstruaĵo kontraŭ la placo, kiu estis malantaŭe, kun ĝiaj flankaj partoj ambaŭflanke, cent ulnojn; ankaŭ la internan templon kaj la portikojn de la korto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'La sojloj kaj la kovritaj fenestroj kaj la galerioj ĉirkaŭe en siaj tri etaĝoj kontraŭ ĉiu sojlo estis tabulkovritaj per ligno ĉiuflanke, ankaŭ la tero ĝis la fenestroj; kaj la fenestroj estis kovritaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'De la supra parto de la pordo ĝis la internaj kaj eksteraj partoj de la domo laŭ la tuta muro ĉirkaŭe, interne kaj ekstere ĉio estis laŭmezura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'Kaj estis faritaj keruboj kaj palmornamoj; inter unu kerubo kaj la alia estis palmornamo, kaj ĉiu kerubo havis du vizaĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'Kaj homa vizaĝo estis turnita al la palmornamo de unu flanko, kaj al la palmornamo de la dua flanko estis turnita vizaĝo leonida; tiel estis farite en la tuta domo ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'De la tero ĝis la supro de la pordo estis skulptitaj la keruboj kaj la palmornamoj, ankaŭ sur la muro de la templo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'La templo havis kvarangulajn fostojn, kaj la tuta aspekto de la sanktejo estis simetria.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'La ligna altaro havis la alton de tri ulnoj kaj la longon de du ulnoj; ĝiaj anguloj kaj ĉiuj ĝiaj flankoj estis el ligno. Kaj li diris al mi: Ĉi tio estas la tablo, kiu staras antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'Kaj du pordoj estis en la templo kaj en la sanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'Ĉiu pordo havis du fermoplatojn, kiuj ambaŭ estis moveblaj; du fermoplatojn havis unu pordo, kaj du fermoplatojn havis la dua.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'Kaj sur ili, sur la pordoj de la templo, troviĝis keruboj kaj palmornamoj similaj al tiuj, kiuj estis sur la muroj; kaj antaŭ la portiko ekstere estis ligna podio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Kaj kovritaj fenestroj kaj palmornamoj estis ĉe ambaŭ flankoj de la portiko kaj flankpartoj de la domo kaj podioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Kaj li elkondukis min sur la korton eksteran, kiu estis en norda direkto; kaj li venigis min al la ofica ĉambro, kiu estis kontraŭ la placo kaj kontraŭ la konstruaĵo norde.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'Ĝia longo ĝis la norda pordo estis cent ulnoj, kaj la larĝo kvindek ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Kontraŭ la dudek ulnoj de la interna korto kaj kontraŭ la pavimo de la ekstera korto estis galerio apud galerio trietaĝe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'Kaj antaŭ la oficaj ĉambroj estis pasejo, havanta la larĝon de dek ulnoj kaj internen unu ulnon; iliaj pordoj malfermiĝadis norden.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'La supraj ĉambroj estis malpli ampleksaj, ĉar la galerioj iom deprenis de ili kompare kun la malsupraj kaj mezaj partoj de la konstruaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Ĉar ili estis trietaĝaj kaj ili ne havis kolonojn kiel la kolonoj de la kortoj, tial ili estis malgrandigitaj kompare kun la malsupraj kaj mezaj, komencante de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Kaj la muro ekster la oficaj ĉambroj, en la direkto al la ekstera korto, havis antaŭ la ĉambroj la longon de kvindek ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Ĉar la longo de la ĉambroj, turnitaj al la ekstera korto, estis kvindek ulnoj, tial la spaco antaŭ la templo estis cent ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'Kaj malsupre por tiuj ĉambroj estis enirejo de oriente, por ke oni povu veni al ili el la ekstera korto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'Laŭlarĝe de la muro de la korto en la direkto al oriento, antaŭ la placo kaj antaŭ la konstruaĵo estis ĉambroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'Kaj pasejo antaŭ ili estis tia sama, kiel antaŭ la ĉambroj, kiuj estis norde, kaj tiaj samaj estis ilia longo kaj larĝo, ĉiuj iliaj eliroj kaj ilia aranĝo kaj iliaj pordoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'Kaj simile al la pordoj de la ĉambroj turnitaj suden ankaŭ ĉe la orientaj ĉambroj estis enira pordo ĉe la komenco de la vojo, de tiu vojo, kiu iris laŭlonge de la muro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Kaj li diris al mi: La ĉambroj nordaj kaj la ĉambroj sudaj, kiuj estas antaŭ la placo, estas ĉambroj sanktaj, en kiuj la pastroj, starantaj proksime al la Eternulo, konsumas la plej sanktajn oferojn; tie ili kuŝigas la plej sanktajn oferojn kaj la farunoferon kaj pekoferon kaj kulpoferon, ĉar la loko estas sankta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Kiam la pastroj eniris ĉi tien, ili devas ne eliri el la sanktejo sur la eksteran korton, antaŭ ol ili restigis ĉi tie siajn vestojn, en kiuj ili faris la servadon, ĉar tiuj vestoj estas sanktaj; ili metu sur sin aliajn vestojn, kaj tiam ili povas iri al lokoj de la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'Kiam li finis la mezuradon de la interna domo, li elkondukis min tra la pordego, kiu estis turnita orienten, kaj mezuris la domon ĉe ĉiuj flankoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Li mezuris la orientan flankon per la mezura stango, kvincent mezurajn stangojn ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Li mezuris la nordan flankon, ankaŭ kvincent mezurajn stangojn ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'La sudan flankon li mezuris, ankaŭ kvincent mezurajn stangojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Li turnis sin al la okcidenta flanko, kaj tie ankaŭ mezuris kvincent mezurajn stangojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'De kvar flankoj li mezuris; la muro ĉirkaŭe havis kvincent stangojn da longo kaj kvincent stangojn da larĝo, por apartigi la sanktaĵon de la nesanktaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Kaj li venigis min al la pordego, al tiu pordego, kiu estas turnita orienten.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'Kaj jen la majesto de la Dio de Izrael estis venanta laŭ la orienta vojo; kaj Lia voĉo estis kiel la bruo de granda akvo; kaj la tero lumiĝis de Lia majesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'Tio estis vizio simila al tiu vizio, kiun mi vidis antaŭe, kiam mi iris, por antaŭdiri pereon al la urbo, kaj vizio simila al tiu, kiun mi vidis ĉe la rivero Kebar. Kaj mi ĵetis min vizaĝaltere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'Kaj la majesto de la Eternulo eniris en la domon tra la pordego, kiu estis turnita orienten.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Kaj levis min la spirito, kaj venigis min sur la internan korton; kaj jen la majesto de la Eternulo plenigis la domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'Kaj mi aŭdis, ke Iu parolas al mi el la domo, kaj viro staris apud mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'Kaj estis dirite al mi: Ho filo de homo! jen estas la loko de Mia trono, kaj la loko de la plandoj de Miaj piedoj, kie Mi loĝos eterne inter la Izraelidoj; kaj la domo de Izrael ne plu malpurigos Mian sanktan nomon, nek ili nek iliaj reĝoj, per sia malĉastado kaj per la kadavraĵoj de siaj reĝoj sur iliaj altaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'Ili starigis sian sojlon apud Mia sojlo kaj siajn fostojn apud Miaj fostoj, tie ke nur muro estis inter Mi kaj ili; kaj ili malpurigis Mian sanktan nomon per siaj abomenindaĵoj, kiujn ili faris; tial Mi pereigis ilin en Mia kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Sed nun ili forigos de Mi sian malĉastaĵon kaj la kadavraĵojn de siaj reĝoj, kaj Mi loĝos inter ili eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Vi, ho filo de homo, montru al la domo de Izrael ĉi tiun domon, por ke ili ekhontu pri siaj malbonagoj kaj alkonformigu sin al ĝia aranĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'Kaj se ili ekhontos pri ĉio, kion ili faris, tiam montru al ili la bildon de la domo, ĝian aranĝon, ĝiajn elirojn kaj enirojn, ĉiujn ĝiajn manierojn kaj leĝojn, ĉiujn ĝiajn morojn kaj instrukciojn, kaj priskribu ĉion antaŭ iliaj okuloj, por ke ili observu ĉiujn ĝiajn instrukciojn kaj leĝojn kaj plenumu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'Jen estas la leĝo por la domo: la tuta spaco sur la supro de la monto ĉirkaŭe estas plejsanktejo; tio estas la leĝo por la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'Kaj jen estas la mezuroj de la altaro laŭ ulnoj, kun aldono po manlarĝo por ĉiu ulno: la bazo havu unu ulnon kaj la larĝo unu ulnon, kaj la listelo ĉe ĝia rando ĉirkaŭe havu la larĝon de unu manstreĉo; kaj tia estu la dorso de la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'Kaj de la bazo sur la tero ĝis la malsupra elstaraĵo devas esti du ulnoj, kaj la larĝo estu unu ulno; kaj de la malgranda elstaraĵo ĝis la granda elstaraĵo estu kvar ulnoj, kaj la larĝo unu ulno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Kaj la altaro mem havu kvar ulnojn, kaj de la altaro leviĝu supren kvar kornoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'Kaj la altaro havu dek du ulnojn da longo kaj dek du ulnojn da larĝo, ĝi estu kvadrata sur ĉiuj siaj kvar flankoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'Kaj la elstaraĵo havu dek kvar ulnojn da longo kaj dek kvar ulnojn da larĝo sur ĉiuj siaj kvar flankoj, kaj la listelo ĉirkaŭ ĝi havu duonon de ulno, kaj ĝia bazo ĉirkaŭe havu unu ulnon; kaj ĝiaj ŝtupoj devas esti ĉe la orienta flanko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'Kaj Li diris al mi: Ho filo de homo! tiele diras la Sinjoro, la Eternulo: Tio estas la leĝoj por la altaro por tiu tago, kiam oni konstruos ĝin, por alportadi sur ĝi bruloferojn kaj aspergadi ĝin per sango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'Kaj al la pastroj Levidoj el la idaro de Cadok, kiuj alproksimiĝos al Mi, por servi al Mi, diras la Sinjoro, la Eternulo, donu bovidon kiel pekoferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'Kaj prenu iom el ĝia sango, kaj ŝprucigu sur ĝiajn kvar kornojn kaj sur la kvar angulojn de la elstaraĵo kaj sur la listelon ĉirkaŭe; kaj per tio vi ĝin purigos kaj pekliberigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Poste prenu la pekoferan bovidon, kaj forbruligu ĝin sur aparta loko de la domo ekster la sanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Kaj en la sekvanta tago alportu virkapron sendifektan kiel pekoferon; kaj oni pekliberigu la altaron tiel same, kiel oni pekliberigis per la bovido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Kiam vi finos la pekliberigon, alportu bovidon sendifektan, kaj sendifektan virŝafon el la ŝafoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'kaj alportu ilin antaŭ la Eternulon, kaj la pastroj ĵetu sur ilin salon kaj faru el ili bruloferon al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Dum sep tagoj alportu ĉiutage pekoferan kapron; kaj ili alportu po unu bovido el la bovoj kaj po unu virŝafo el la ŝafoj, sendifektajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Dum sep tagoj oni pekliberigu la altaron kaj purigu ĝin kaj konsekru ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'Kiam finiĝos tiuj tagoj, komencante de la oka tago kaj plue, la pastroj farados sur la altaro viajn bruloferojn kaj viajn pacoferojn; kaj Mi estos favora al vi, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Kaj li venigis min denove al la ekstera pordego de la sanktejo, al tiu, kiu estis turnita orienten; sed ĝi estis ŝlosita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'Kaj la Eternulo diris al mi: Ĉi tiu pordego estos ŝlosita, kaj oni ĝin ne malfermu, kaj neniu iru tra ĝi; ĉar la Eternulo, Dio de Izrael, eniris tra ĝi, tial ĝi restu ŝlosita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Nur la princo, la princo povas sidi en ĝi, por manĝi panon antaŭ la Eternulo; tra la portiko de la pordego li eniru, kaj laŭ la sama vojo li eliru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Kaj li venigis min al la domo tra la norda pordego; kaj mi ekvidis, ke jen la majesto de la Eternulo plenigis la domon de la Eternulo; kaj mi ĵetis min vizaĝaltere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'Kaj la Eternulo diris al mi: Ho filo de homo, atentu per via koro, rigardu per viaj okuloj, kaj aŭskultu per viaj oreloj ĉion, kion Mi diras al vi pri ĉiuj leĝoj de la domo de la Eternulo kaj pri ĉiuj ĝiaj instrukcioj; kaj atentu la eniron en la domon kaj ĉiujn elirojn el la sanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'Kaj diru al la malobeema domo de Izrael: Tiele diras la Sinjoro, la Eternulo: Sufiĉaj estu por vi ĉiuj viaj abomenindaĵoj, ho domo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'Vi venigis aligentulojn kun necirkumcidita koro kaj necirkumcidita karno, ke ili estu en Mia sanktejo, por malsanktigi Mian domon; vi alportadis Mian panon, grasaĵon, kaj sangon, kaj rompadis Mian interligon per ĉiuj viaj abomenindaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'Vi ne plenumadis mem Mian sanktan servadon, sed vi faris ilin plenumantoj de Mia servado en Mia sanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Tiele diras la Sinjoro, la Eternulo: Neniu aligentulo kun necirkumcidita koro kaj necirkumcidita karno eniru en Mian sanktejon, eĉ el tiuj aligentuloj, kiuj loĝas inter la Izraelidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Sed la Levidoj, kiuj malproksimiĝis de Mi, kiam la Izraelidoj erarvagis, kaj kiuj perfidis Min, por sekvi siajn idolojn, ili estu punataj pro siaj malbonagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'Ili estos en Mia sanktejo servistoj, havantaj sian oficon ĉe la pordegoj de la domo, simplaj servistoj en la domo; ili buĉados por la popolo la bruloferon kaj buĉoferon, kaj ili staros antaŭ la homoj, por servi ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Pro tio, ke ili servis ilin antaŭ iliaj idoloj kaj estis por la Izraelidoj logilo al malbonagoj, pro tio Mi levis Mian manon sur ilin, diras la Sinjoro, la Eternulo, kaj ili estu punataj pro siaj malbonagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'Ili ne alproksimiĝu al Mi, por fari pastran servadon antaŭ Mi kaj por aliri al ĉiuj Miaj sanktaĵoj, al la plejsanktejo; ili portu sur si sian malhonoron, kaj siajn abomenindaĵojn, kiujn ili faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Mi destinis por ili esti servistoj en la domo por ĉiuj laboroj en ĝi, kaj por ĉio, kio estas farata en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Sed la pastroj Levidoj, filoj de Cadok, kiuj plenumadis la servadon en Mia sanktejo en la tempo, kiam la Izraelidoj defalis de Mi, ili alproksimiĝadu al Mi, por servi al Mi; ili staru antaŭ Mi, por alporti al Mi grasaĵon kaj sangon, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Ili eniradu en Mian sanktejon, ili alproksimiĝadu al Mia tablo, por servi al Mi, kaj ili plenumadu antaŭ Mi la servan oficon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'Kiam ili eniros en la pordegon de la interna korto, ili metu sur sin tolajn vestojn; kaj lanaĵo ne devas esti sur ili, kiam ili servos en la pordego de la interna korto kaj en la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Tola kapornamo estu sur ilia kapo, kaj linaj pantalonoj sur iliaj lumboj; ili ne zonu sin en ŝvito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Kaj kiam ili devos eliri sur la eksteran korton, sur la eksteran korton al la popolo, ili demetu de si siajn vestojn, en kiuj ili servis, kaj deponu ilin en la sanktaj ĉambroj, kaj ili metu sur sin aliajn vestojn, por ke ili ne sanktigu la popolon per siaj vestoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Sian kapon ili ne razu, kaj ili ankaŭ ne lasu libere kreski siajn harojn, sed ili pritondu sian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Vinon trinku neniu el la pastroj, kiam ili devas iri en la internan korton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Vidvinon aŭ eksedzinon ili ne prenu al si kiel edzinon; sed nur virgulinon el la idaro de la domo de Izrael, aŭ vidvinon, kiu vidviniĝis de pastro, ili prenu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'Mian popolon ili devas instrui distingi inter sanktaĵo kaj nesanktaĵo, inter malpuraĵo kaj puraĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'En disputa afero ili stariĝu por juĝi, kaj ili juĝu laŭ Mia juro; Mian instruon kaj Miajn leĝojn pri ĉiuj Miaj festoj ili observu, kaj Miajn sabatojn ili tenu sankte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Al homo mortinta ili ne aliru, por ne fariĝi malpura; nur por la patro aŭ la patrino, por filo aŭ filino, por frato aŭ needzinigita fratino ili povas sin malpurigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Kaj kiam tia pastro repuriĝos, oni kalkulu al li sep tagojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'Kaj en la tago, kiam li venos en la sanktejon, en la internan korton, por servi en la sanktejo, li alportu sian pekoferon, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'Kaj ilia heredaĵo estu tio, ke Mi estas ilia heredaĵo; terposedaĵon ne donu al ili en Izrael: Mi estas ilia posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'La farunoferojn, pekoferojn, kaj kulpoferojn ili manĝu; kaj ĉio anatemita en Izrael apartenu al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'Kaj la unuaaĵo el ĉio unuenaskita, kaj ĉiaj oferdonoj el ĉiuj viaj oferdonoj apartenu al la pastroj; kaj la unuaaĵon de via pasto donu al la pastroj, por ke beno estu super via domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Ĉian kadavraĵon aŭ disŝiritaĵon el la birdoj aŭ el la brutoj la pastroj ne manĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'Kiam vi lote dividos la teron en heredaĵojn, tiam apartigu oferdonon al la Eternulo, sanktan terpecon, havantan la longon de dudek kvin mil mezurstangoj kaj la larĝon de dek mil; tiu loko estu sankta en ĉiuj siaj limoj ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'El ĝi devas esti por la sanktejo kvadrato de kvincent mezuroj ĉiuflanke, kaj kvindek ulnoj ĉirkaŭe kiel libera placo por ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Per tiu mezuro mezuru la longon de dudek kvin mil kaj la larĝon de dek mil; sur tiu loko estos la sanktejo, la plejsanktaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'La cetera parto de la sankta tero apartenu al la pastroj, kiuj servas en la sanktejo, kiuj alproksimiĝas al la Eternulo, por servi al Li; ĝi estu por ili kiel loko por domoj, kaj estu konsekrita al la sanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'Dudek kvin mil ulnoj da longo kaj dek mil ulnoj da larĝo estu por la Levidoj, kiuj servas en la domo; dudek ĉambroj estu tie ilia posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Kaj kiel posedaĵon de la urbo apartigu kvin mil da larĝo kaj dudek kvin mil da longo kontraŭ la sankta terpeco: ĝi apartenu al la tuta domo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'Kaj al la princo donu parton ambaŭflanke apud la sankta terpeco kaj apud la urba posedaĵo, sur la okcidenta flanko okcidenten kaj sur la orienta flanko orienten; ĝia longo devas esti tia sama, kiel de unu el tiuj partoj de la okcidenta limo ĝis la orienta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Tio estos lia tero, lia terposedaĵo en Izrael, por ke Miaj princoj ne plu premu Mian popolon; kaj la ceteran teron oni donu al la domo de Izrael laŭ iliaj triboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Tiele diras la Sinjoro, la Eternulo: Sufiĉe estas por vi, ho princoj de Izrael; forigu la perfortadon kaj rabadon, agu juste kaj virte, ĉesigu vian persekutadon kontraŭ Mia popolo, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Ĝusta pesilo, ĝusta ŝutmezurilo, kaj ĝusta verŝmezurilo estu ĉe vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'La efo kaj la bat�o devas havi egalan amplekson, tiel, ke la bat�o entenu dekonon de ĥomero kaj la efo ankaŭ dekonon de ĥomero: laŭ la ĥomero oni fiksu ilian amplekson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'La siklo devas enteni dudek gerojn; dudek sikloj, dudek vin sikloj, kaj dek kvin sikloj estu por vi unu min�o.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'Jen estas la oferdono, kiun vi devas alportadi: sesono de efo el ĥomero da tritiko, kaj sesono de efo el ĥomero da hordeo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'Kaj la leĝo pri la oleo estas: bat�o da oleo; bat�o estas dekono de kor�o; dek bat�oj faras ĥomeron, ĉar ĥomero entenas dek bat�ojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'Kaj unu ŝafidon oni donu el ducento da ŝafoj de paŝtejo de Izrael. Tio estos farunofero, brulofero, kaj pacofero, por pekliberigo por ili, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'La tuta popolo de la lando alportadu tian oferdonon al la princo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Kaj la princo devas zorgi pri la bruloferoj, farunofero, kaj verŝofero en la festoj, monatkomencoj, kaj sabatoj, en ĉiuj festoj de la domo de Izrael; li devas alportadi la pekoferon, la farunoferon, la bruloferon, kaj la pacoferon, por atingi pekliberigon por la domo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'Tiele diras la Sinjoro, la Eternulo: En la unua tago de la unua monato prenu sendifektan bovidon, kaj pekliberigu la sanktejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Kaj la pastro prenu iom el la sango de la pekofero, kaj ŝprucigu sur la fostojn de la domo kaj sur la kvar angulojn de la elstaraĵo de la altaro kaj sur la fostojn de la pordego de la interna korto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Tion saman faru en la sepa tago de la monato por ĉiu, kiu pekis pro eraro aŭ pro naiveco; kaj tiamaniere pekliberigu la domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'En la dek-kvara tago de la unua monato estu ĉe vi Pasko, festo septaga, en kiu oni devas manĝi macojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'Kaj la princo en tiu tago devas alporti pro si kaj pro la tuta popolo de la lando bovon kiel propekan oferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'Kaj dum la sep tagoj de la festo li alportadu bruloferon al la Eternulo, po sep bovoj kaj po sep virŝafoj sendifektaj ĉiutage dum la sep tagoj, kaj po unu virkapro kiel pekoferon ĉiutage.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Kaj da farunofero li alportos po unu efo por ĉiu bovo, kaj po unu efo por ĉiu virŝafo, kaj po unu hino da oleo por ĉiu efo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'En la dek-kvina tago de la sepa monato, en la festo, li faru tion saman dum sep tagoj: tian saman pekoferon, bruloferon, farunoferon, kaj oleon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'Tiele diras la Sinjoro, la Eternulo: La pordego de la interna korto, kiu estas turnita al oriento, estu ŝlosita dum la ses laboraj tagoj, sed en la tago sabata ĝi estu malfermita, kaj ankaŭ en la monatkomenco ĝi estu malfermita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'Kaj la princo eniros tra la portiko de la pordego el ekstere, kaj stariĝos ĉe la fosto de la pordego; kaj la pastroj faros lian bruloferon kaj lian pacoferon; kaj li adorkliniĝos sur la sojlo de la pordego kaj eliros; sed la pordego ne estos ne estos ŝlosita ĝis vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'La popolo de la lando adorkliniĝos antaŭ la Eternulo ĉe la enirejo de tiu pordego en la sabatoj kaj en la monatkomencoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'La brulofero, kiun la princo alportos al la Eternulo en sabato, estos: ses sendifektaj ŝafidoj kaj unu sendifekta virŝafo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'kaj da farunofero unu efo por la virŝafo, kaj da farunofero por la ŝafidoj tiom, kiom povas doni lia mano, kaj po unu hino da oleo por ĉiu efo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'En la tago de la monatkomenco: sendifekta bovido kaj ses ŝafidoj kaj sendifekta virŝafo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'kaj farunoferon li faru: unu efon por la bovido, kaj unu efon por la virŝafo, kaj por la ŝafidoj tiom, kiom povas doni lia mano, kaj po unu hino da oleo por ĉiu efo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'Kiam la princo venos, li devas eniri tra la portiko de la pordego, kaj laŭ la sama vojo li devas eliri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Kaj kiam la popolo de la lando venos antaŭ la Eternulon en la festoj, tiam tiuj, kiuj eniris tra la norda pordego, por adorkliniĝi, devas eliri tra la suda pordego, kaj tiuj, kiuj eniris tra la suda pordego, devas eliri tra la norda pordego; oni devas ne iri returne tra tiu pordego, tra kiu oni eniris, sed oni devas eliri tra la kontraŭa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'Kaj la princo estos inter ili: kiam ili eniros, li ankaŭ eniros, kaj kiam ili eliros, li ankaŭ eliros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'En la festoj kaj en la solenaj tagoj la farunofero devas esti unu efo por la bovido, kaj unu efo por la virŝafo, kaj por la ŝafidoj tiom, kiom povas doni lia mano, kaj po unu hino da oleo por ĉiu efo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Kiam la princo alportos al la Eternulo memvolan bruloferon aŭ memvolan pacoferon, tiam oni devas malfermi antaŭ li la pordegon, turnitan al oriento, kaj li faros sian bruloferon aŭ sian pacoferon tiel, kiel li faras ĝin en la tago sabata; poste li eliros, kaj post lia eliro oni ŝlosos la pordegon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Unujaran ŝafidon sendifektan li alportu kiel bruloferon ĉiutage al la Eternulo; ĉiumatene li alportu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'Kaj farunoferon li alportu kune kun ĝi ĉiumatene: sesonon de efo, kaj trionon de hino da oleo, por ŝprucigi sur la farunon; tio devas esti la porĉiama leĝo pri la farunofero al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Tiamaniere oni alportu ĉiumatene la ŝafidon kaj la farunoferon kaj la oleon, kiel konstantan bruloferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Tiele diras la Sinjoro, la Eternulo: Se la princo donos donacon al iu el siaj filoj, ĝi fariĝu heredaĵo por liaj filoj; tio estu ilia hereda posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Sed se li donos donacon el sia heredaĵo al unu el siaj sklavoj, ĝi apartenu al li ĝis la jaro de libereco, kaj poste ĝi revenu al la princo; nur la heredaĵo donacita al liaj filoj devas resti ĉe ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'La princo ne prenu ion el la heredaĵo de la popolanoj, elpremante ilin el ilia terposedaĵo: nur el sia terposedaĵo li povas doni heredon al siaj filoj, por ke neniu el Mia popolo estu elpuŝita el sia terposedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Kaj li venigis min tra la enirejo, kiu estis flanke de la pordego, al la sanktaj ĉambroj, kiuj apartenas al la pastroj kaj kiuj estas turnitaj norden; kaj jen mi tie vidis lokon ĉe la rando okcidente.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'Kaj li diris al mi: Ĉi tie estas la loko, kie la pastroj devas kuiri la kulpoferon kaj la pekoferon kaj kie ili devas baki la farunoferon, ne alportante tion sur la eksteran korton, por ne sanktigi la popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Kaj li elkondukis min sur la eksteran korton, kaj alkondukis min al la kvar anguloj de la korto; kaj mi vidis, ke en ĉiu angulo de la korto troviĝas ankoraŭ korto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'En la kvar anguloj de la korto troviĝis aldonaj kortetoj, havantaj la longon de kvardek ulnoj kaj la larĝon de tridek; la saman mezuron havis ĉiuj kvar kortetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'Kaj mureto estis ĉirkaŭe, ĉirkaŭ ĉiuj kvar, kaj kuirlokoj estis aranĝitaj malsupre ĉe tiuj muretoj ĉirkaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'Kaj li diris al mi: Jen estas la kuirejoj, kie la servistoj de la domo devas kuiri la oferojn de la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Kaj li revenigis min al la pordo de la domo; kaj mi ekvidis, ke jen el sub la sojlo de la domo fluas akvo orienten, ĉar la vizaĝa flanko de la domo estis turnita orienten; kaj la akvo fluis el sub la dekstra flanko de la domo al la suda flanko de la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Kaj li elkondukis min tra la norda pordego, kaj kondukis min laŭ ekstera vojo al la ekstera pordego, turnita orienten; kaj jen la akvo fluas el la dekstra flanko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Kiam la viro iris orienten, li havis en sia mano mezurŝnuron, kaj li mezuris mil ulnojn, kaj transpasigis min trans la akvon, kiu estis alta ĝis la maleoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Kaj li mezuris ankoraŭ mil ulnojn, kaj transpasigis min trans la akvon; la akvo estis alta ĝis la genuoj. Kaj li mezuris ankoraŭ mil, kaj transpasigis min trans la akvon, kiu estis alta ĝis la lumboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'Kiam li mezuris ankoraŭ mil, estis jam torento, kiun mi ne povis transiri; ĉar la akvo estis tro alta, oni devis ĝin transnaĝi, sed transiri la torenton oni ne povis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Kaj li diris al mi: Ĉu vi vidis, ho filo de homo? Kaj li kondukis min returne al la bordo de la torento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Kiam mi revenis, mi vidis, ke sur la bordo de la torento estas jam tre multe da arboj sur ambaŭ flankoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'Kaj li diris al mi: Ĉi tiu akvo, kiu eliras el la orienta regiono, iros malsupren en la stepon, kaj venos en la maron; kiam ĝi troviĝos en la maro, tiam saniĝos la akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'Kaj ĉiu vivanta estaĵo, kiu rampas tie, kie pasas la torentoj, reviviĝos, kaj estos tre multe da fiŝoj; ĉar tien venos ĉi tiu akvo, kaj ĉio saniĝos kaj reviviĝos, kien venos la torento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'Kaj staros apud ĝi fiŝkaptistoj de En-Gedi ĝis En-Eglaim, kaj ili etendos tie retojn; iliaj fiŝoj estos tiaspecaj, kiel la fiŝoj de la Granda Maro, kaj tre multe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Sed ĝiaj marĉoj kaj marĉetoj ne saniĝos, ili estos destinitaj por salo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'Kaj apud la torento sur ambaŭ bordoj kreskos ĉiaspecaj manĝaĵdonantaj arboj; ne velkos iliaj folioj, kaj ne forfiniĝos iliaj fruktoj; ĉiumonate ili donos novajn fruktojn, ĉar la akvo por ili fluas el la sanktejo; kaj iliaj fruktoj estos uzataj kiel manĝaĵo, kaj iliaj folioj kiel kuracilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'Tiele diras la Sinjoro, la Eternulo: Jen estas la limoj, laŭ kiuj vi devas dividi heredige la teron al la dek du triboj de Izrael: al Jozef duoblan parton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Kaj dividu ĝin al ĉiuj egale; ĉar per levo de la mano Mi promesis doni ĝin al viaj patroj, tial ĉi tiu tero fariĝos via hereda posedaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'Jen estas la limo de la lando: sur la norda rando, komencante de la Granda Maro, ĝi iras tra Ĥetlon en la direkto al Cedad;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'tra Ĥamat, Berota, Sibraim, kiu estas inter la limo de Damasko kaj la limo de Ĥamat, ĝis Ĥacer-Tiĥon, kiu troviĝas ĉe la limo de Ĥavran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Kaj la limo estos de la maro ĝis Ĥacar-Enan apud la limo de Damasko, kaj ĝis la norda Cafon kaj la limo de Ĥamat. Tio estas la rando norda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'Kaj la orientan randon mezuru inter Ĥavran kaj Damasko, inter Gilead kaj la lando de Izrael, laŭ Jordan, de la limo ĝis la orienta maro; tio estas la rando orienta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'La suda rando estas de Tamar ĝis la Akvo de Malpaco apud Kadeŝ, laŭ la torento ĝis la Granda Maro; tio estas la rando suda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'La okcidenta rando estas la Granda Maro, ĝis la komenco de Ĥamat; tio estas la rando okcidenta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'Kaj dividu inter vi ĉi tiun landon laŭ la triboj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'Kaj dividu ĝin lote al vi, kaj ankaŭ al la fremduloj, kiuj loĝas inter vi kaj kiuj naskis infanojn inter vi; ili devas esti por vi kiel indiĝenoj inter la Izraelidoj, kune kun vi ili devas ricevi lote heredan posedaĵon inter la triboj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'En tiu tribo, inter kiu ekloĝis la fremdulo, tie donu al li lian heredan posedaĵon, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'Jen estas la nomoj de la triboj: de la norda rando laŭ la vojo al Ĥetlon, en la direkto al Ĥamat, Ĥacar-Enan, norde de la limo de Damasko ĝis Ĥamat; ĉi tiu regiono de oriente ĝis okcidente apartenos sole al Dan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'Kaj apud la limo de Dan, de la orienta rando ĝis la okcidenta, havos sian parton Aŝer.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'Apud la limo de Aŝer, de la orienta rando ĝis la okcidenta, havos sian parton Naftali.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'Apud la limo de Naftali, de la orienta rando ĝis la okcidenta, havos sian parton Manase.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'Apud la limo de Manase, de la orienta rando ĝis la okcidenta, havos sian parton Efraim.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'Apud la limo de Efraim, de la orienta rando ĝis la okcidenta, havos sian parton Ruben.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'Apud la limo de Ruben, de la orienta rando ĝis la okcidenta, havos sian parton Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'Apud la limo de Jehuda, de la orienta rando ĝis la okcidenta, estos la konsekrita terpeco, kiun vi apartigos, kaj kiu havos la larĝon de dudek kvin mil mezurstangoj kaj la longon kiel unu el la partoj de la orienta rando ĝis la okcidenta, kaj en kies mezo estos la sanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'La apartigita terpeco, kiun vi konsekros al la Eternulo, havos la longon de dudek kvin mil kaj la larĝon de dek mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'Kaj la sankta terpeco estos por la pastroj, havante norden dudek kvin mil, kaj okcidenten la larĝon de dek mil, orienten la larĝon de dek mil, kaj suden la longon de dudek kvin mil; kaj en ĝia mezo estos la sanktejo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Ĝi estu sanktigita por la pastroj el la filoj de Cadok, kiuj plenumadis Mian servadon kaj ne defalis de Mi dum la defalo de la Izraelidoj, kiel defalis la Levidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'Kaj al ili estos apartigita parto el la konsekrita terpeco, kiel plejsanktaĵo, apud la limo de la Levidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Kaj la Levidoj havos apud la limo de la pastroj dudek kvin mil da longo kaj dek mil da larĝo; la tuta longo estos dudek kvin mil, kaj la larĝo estos dek mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'Ili nenion devas vendi el tio, nek interŝanĝi; la unuaaĵo de la lando devas ne transiri, ĉar ĝi estas konsekrita al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'La ceteraj kvin mil da larĝo kun dudek kvin mil da longo estas nekonsekrita apartenaĵo de la urbo, kiel loĝatejo kaj antaŭurbo; kaj la urbo estos en la mezo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'Jen estas ĝiaj dimensioj: la norda rando havos kvar mil kvincent, la suda rando kvar mil kvincent, la orienta rando kvar mil kvincent, kaj la okcidenta rando kvar mil kvincent.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'La antaŭurbo de la urbo havos norde ducent kvindek, kaj sude ducent kvindek, kaj oriente ducent kvindek, kaj okcidente ducent kvindek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'Koncerne la ceteran parton de la longo kontraŭ la sankta terpeco, nome dek mil oriente kaj dek mil okcidente, kiu troviĝas kontraŭ la sankta terpeco, ĝiaj produktaĵoj devas servi kiel manĝaĵo por la laboristoj de la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'En la urbo laboros laboristoj el ĉiuj triboj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'La tuta apartigita terpeco devas havi dudek kvin mil kontraŭ dudek kvin mil; kvaronon de la sankta terpeco apartigu kiel posedaĵon de la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Kio restas de la sanktigita terpeco kaj de la posedaĵo de la urbo, de la dudek kvin mil, apartigitaj oriente kaj okcidente, kontraŭ tiuj partoj, tio apartenu al la princo; kaj la sankta terpeco kaj la sankta domo estos en la mezo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'Kio troviĝas inter la apartenaĵo de la Levidoj kaj la apartenaĵo de la urbo, inter la limo de Jehuda kaj la limo de Benjamen, tio apartenu al la princo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'La ceteraj triboj de la rando orienta ĝis la rando okcidenta: Benjamen havos unu parton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'Apud la limo de Benjamen, de la orienta rando ĝis la okcidenta, havos sian parton Simeon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'Apud la limo de Simeon, de la orienta rando ĝis la okcidenta, havos sian parton Isaĥar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'Apud la limo de Isaĥar, de la orienta rando ĝis la okcidenta, havos sian parton Zebulun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Apud la limo de Zebulun, de la orienta rando ĝis la okcidenta, havos sian parton Gad.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'Apud la limo de Gad, ĉe la rando suda, estos la limo de Tamar ĝis la Akvo de Malpaco apud Kadeŝ, laŭlonge de la torento ĝis la Granda Maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'Tio estas la lando, kiun vi lote dividos kiel heredan posedaĵon al la triboj de Izrael, kaj tio estas iliaj partoj, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'Kaj jen estas la randoj de la urbo: sur la norda flanko kvar mil kvincent mezurstangoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'kaj la pordegoj de la urbo estos nomataj laŭ la nomoj de la triboj de Izrael; tri pordegoj norde: unu Pordego de Ruben, unu Pordego de Jehuda, unu Pordego de Levi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'Ankaŭ sur la orienta flanko kvar mil kvincent mezurstangoj; kaj tri pordegoj: unu Pordego de Jozef, unu Pordego de Benjamen, unu Pordego de Dan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'Ankaŭ sur la suda flanko kvar mil kvincent mezurstangoj; kaj tri pordegoj: unu Pordego de Simeon, unu Pordego de Isaĥar, unu Pordego de Zebulun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Ankaŭ sur la okcidenta flanko kvar mil kvincent; pordegojn ĝi havas tri: unu Pordego de Gad, unu Pordego de Aŝer, unu Pordego de Naftali.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'La tuta ĉirkaŭo havas dek ok mil. Kaj la nomo de la urbo de post tiu tago estos: Eternulo-Tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'En la tria jaro de la reĝado de Jehojakim, reĝo de Judujo, venis Nebukadnecar, reĝo de Babel, al Jerusalem, kaj eksieĝis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Kaj la Sinjoro transdonis en lian manon Jehojakimon, reĝon de Judujo, kaj parton de la vazoj de la domo de Dio; kaj li venigis ilin en la landon Ŝinar, en la domon de sia dio, kaj la vazojn li metis en la trezorejon de sia dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Kaj la reĝo diris al Aŝpenaz, la estro de liaj korteganoj, ke el la Izraelidoj, el la reĝa idaro kaj el la nobelaro, li venigu');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'knabojn sendifektajn, belaspektajn, komprenemajn por ĉiu saĝaĵo, klerajn, scienckomprenantajn, kaj kapablajn servi en la palaco de la reĝo, kaj ke oni lernigu al ili la skribadon kaj la lingvon Ĥaldean.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Kaj la reĝo destinis por ili por ĉiu tago manĝaĵojn de la reĝa tablo, kaj vinon el tiu, kiun li mem trinkadis, kaj li ordonis eduki ilin dum tri jaroj, post kies finiĝo ili estis komencontaj la servadon antaŭ la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'El la idoj de Jehuda estis inter ili Daniel, Ĥananja, Miŝael, kaj Azarja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'La estro de la korteganoj donis al ili aliajn nomojn; kaj li donis al Daniel la nomon Beltŝacar; al Ĥananja, Ŝadraĥ; al Miŝael, Meŝaĥ; kaj al Azarja, Abed-Nego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Daniel metis en sian koron, ke li ne malpurigos sin per la manĝaĵoj de la reĝo, nek per la vino, kiun ĉi tiu trinkas; tial li petis la korteganestron, ke al li estu permesite ne malpurigi sin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Dio donis al Daniel favoron kaj simpation ĉe la korteganestro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Kaj la korteganestro diris al Daniel: Mi timas mian sinjoron, la reĝon, kiu mem destinis por vi, kion vi devas manĝi kaj trinki; se li vidos, ke viaj vizaĝoj estas malpli grasaj, ol ĉe aliaj knaboj, viaj samaĝuloj, tiam vi farus mian kapon kulpa antaŭ la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Tiam Daniel diris al la inspektisto, al kiu la korteganestro komisiis Danielon, Ĥananjan, Miŝaelon, kaj Azarjan:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Faru, mi petas, provon kun viaj servantoj dum dek tagoj; oni donadu al ni por manĝi legomojn, kaj por trinki akvon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'poste montriĝu al vi nia aspekto, kaj la aspekto de la knaboj, kiuj manĝas la manĝaĵon de la reĝo; kaj poste agu kun viaj servantoj laŭ tio, kion vi vidos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Li obeis ilin en tio kaj faris kun ili provon dum dek tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Post paso de la dek tagoj montriĝis, ke ili estas pli bonaspektaj kaj pli bonkorpaj, ol ĉiuj knaboj, kiuj manĝis la manĝaĵon de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Tial la inspektisto forportadis ilian manĝaĵon, kaj la vinon, kiu estis destinita al ili por trinki, kaj donadis al ili legomojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Kaj al tiuj kvar knaboj Dio donis kapablojn kaj komprenemecon pri ĉiuj libroj kaj saĝaĵo, kaj Daniel estis ankaŭ kompetenta pri ĉiaj vizioj kaj sonĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Kiam pasis la tempo, kiun la reĝo difinis por ilia venigo, la korteganestro prezentis ilin al Nebukadnecar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'La reĝo parolis kun ili, kaj el ili ĉiuj troviĝis neniu egala al Daniel, Ĥananja, Miŝael, kaj Azarja. Kaj ili komencis servadi antaŭ la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'Kaj koncerne ĉiujn aferojn de saĝo kaj scio, pri kiuj la reĝo ilin demandis, li trovis ilin dekoble pli saĝaj, ol ĉiuj astrologoj kaj magiistoj, kiuj estis en lia tuta regno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Daniel estis tie ĝis la unua jaro de la reĝo Ciro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'En la dua jaro de la reĝado de Nebukadnecar aperis al Nebukadnecar sonĝoj; kaj konfuziĝis lia spirito, kaj li ne povis dormi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Kaj la reĝo ordonis alvoki la astrologojn, magiistojn, sorĉistojn, kaj Ĥaldeojn, por ke ili diru al la reĝo liajn sonĝojn. Kaj ili venis kaj stariĝis antaŭ la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Kaj la reĝo diris al ili: Mi havis sonĝon, kaj mia spirito maltrankviliĝis, dezirante scii, kio estis tiu sonĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'La Ĥaldeoj respondis al la reĝo en la lingvo Siria: Ho reĝo, vivu eterne! diru la sonĝon al viaj servantoj, kaj ni klarigos ĝian signifon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Sed la reĝo respondis kaj diris al la Ĥaldeoj: La enhavon mi forgesis. Tamen, se vi ne diros al mi la sonĝon kaj ĝian signifon, vi estos dishakitaj en pecojn kaj viaj domoj estos ruinigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Sed se vi rakontos al mi la sonĝon kaj ĝian signifon, vi ricevos de mi donacojn, rekompencon, kaj grandan honoron. Tial diru al mi la sonĝon kaj ĝian signifon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Ili denove respondis: La reĝo diru sian sonĝon al siaj servantoj, kaj ni klarigos ĝian signifon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'La reĝo diris: Mi scias bone, ke vi deziras gajni tempon, ĉar vi vidas, ke la afero malaperis el mia memoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Se vi ne diros al mi la sonĝon, tio montros, ke vi havas unu intencon: vi preparas vin, por doni al mi mensogan kaj sentaŭgan respondon, ĝis la tempo pasos. Tial rakontu al mi la sonĝon, tiam mi konvinkiĝos, ke vi povas klarigi al mi ankaŭ ĝian signifon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'La Ĥaldeoj respondis al la reĝo kaj diris: Ne ekzistas sur la tero tia homo, kiu povus plenumi la deziron de la reĝo; tial neniu reĝo, kiel ajn granda kaj potenca li estus, postulis iam similan respondon de iu astrologo, magiisto, aŭ Ĥaldeo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'la afero, kiun la reĝo postulas, estas tiel eksterordinara, ke neniu povas tion plenumi al la reĝo, krom la dioj, kiuj ne vivas inter karnuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Tiam la reĝo forte indignis kaj koleris, kaj ordonis pereigi ĉiujn saĝulojn de Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'Kiam la dekreto eliris, oni komencis la mortigadon de la saĝuloj, kaj oni volis mortigi ankaŭ Danielon kaj liajn kamaradojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Tiam Daniel faris saĝan kaj prudentan rediron al Arjoĥ, la estro de la reĝaj korpogardistoj, kiu eliris, por mortigi la saĝulojn de Babel;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'li demandis Arjoĥon, la potenculon de la reĝo, dirante: Pro kio eliris de la reĝo tia severa ordono? Tiam Arjoĥ rakontis al Daniel la tutan aferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Daniel iris kaj petis la reĝon, ke li donu al li templimon, kaj li prezentos al la reĝo la klarigon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Poste Daniel iris en sian domon, kaj rakontis la aferon al siaj kamaradoj Ĥananja, Miŝael, kaj Azarja,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'por ke ili petegu la kompateman Dion de la ĉielo malkaŝi tiun kaŝitan aferon, por ke Daniel kaj liaj kamaradoj ne pereu kun la aliaj saĝuloj de Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Kaj tiam la kaŝitaĵo malkaŝiĝis al Daniel en nokta vizio, kaj Daniel dankis pro tio Dion de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Kaj Daniel ekparolis, kaj diris: Estu benata la nomo de Dio de eterne ĝis eterne; ĉar al Li apartenas saĝo kaj forto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'Li ŝanĝas la tempojn kaj jarojn; Li faligas reĝojn kaj starigas reĝojn; Li donas saĝon al la saĝuloj kaj prudenton al la prudentuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'Li malkaŝas la profundaĵon kaj kaŝitaĵon; Li scias, kio estas en la mallumo, kaj lumo estas en Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Vin, ho Dio de miaj patroj, mi dankas kaj gloras; ĉar Vi donis al mi saĝon kaj forton, kaj malkaŝis al mi tion, pri kio ni Vin petis; ĉar Vi malkaŝis al ni la aferon de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Poste Daniel iris al Arjoĥ, al kiu la reĝo komisiis mortigi la saĝulojn de Babel; li venis, kaj diris al li tiel: Ne mortigu la saĝulojn de Babel, konduku min al la reĝo, kaj mi diros al la reĝo la klarigon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Tiam Arjoĥ tuj enkondukis Danielon al la reĝo, kaj diris al ĉi tiu tiele: Inter la transloĝigitaj filoj de Judujo mi trovis homon, kiu povas doni al la reĝo klarigon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Tiam ekparolis la reĝo, kaj diris al Daniel, kies nomo estis nun Beltŝacar: Ĉu vi povas sciigi al mi la sonĝon, kiun mi vidis, kaj ĝian signifon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Daniel respondis al la reĝo kaj diris: La kaŝitaĵon, pri kiu la reĝo demandas, ne povas malkaŝi al la reĝo la saĝuloj, nek la sorĉistoj, nek la astrologoj, nek la divenistoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'sed en la ĉielo ekzistas Dio, kiu malkaŝas kaŝitaĵon; Li malkaŝis al la reĝo Nebukadnecar tion, kio estos en tempo estonta. Via sonĝo kaj la vizioj de via kapo sur via lito estis jenaj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'vi, ho reĝo, meditis sur via lito pri tio, kio estos poste; kaj la Malkaŝanto de kaŝitaĵoj montris al vi, kio estos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Kaj al mi tiu kaŝitaĵo malkaŝiĝis ne pro tio, ke mi kvazaŭ estus pli saĝa ol ĉiuj vivantoj, sed por tio, ke la reĝo ricevu klarigon kaj ke vi eksciu la pensojn de via koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Vi, ho reĝo, havis vizion: jen staris granda statuo; grandega statuo tio estis; en eksterordinara brilo ĝi staris antaŭ vi, kaj ĝia aspekto estis terura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'La kapo de tiu statuo estis el pura oro; ĝiaj brusto kaj manoj estis el arĝento, la ventro kaj femuroj el kupro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'ĝiaj kruroj estis el fero, ĝiaj piedoj estis parte el fero, parte el argilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Vi vidis poste, ke ŝtono deŝiriĝis sen ago de ia mano, frapis la statuon, ĝiajn ferajn kaj argilajn piedojn, kaj frakasis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Tiam ĉio kune frakasiĝis: la fero, argilo, kupro, arĝento, kaj oro fariĝis kiel grenventumaĵo sur somera draŝejo, kaj la vento ilin forportis, kaj ne restis postesigno post ili; sed la ŝtono, kiu frakasis la statuon, fariĝis granda monto kaj plenigis la tutan teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'Tio estas la sonĝo. Nun ni diros al la reĝo la signifon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Vi, ho reĝo, estas reĝo super reĝoj, al kiu Dio de la ĉielo donis regnon, potencon, forton, kaj gloron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'kaj ĉie, kie ajn loĝas homoj, Li transdonis en viajn manojn la bestojn de la kampo kaj la birdojn de la ĉielo, kaj faris vin reganto super ili ĉiuj. Vi estas la ora kapo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Post vi aperos nova regno, malpli alta ol via, kaj ankoraŭ tria regno, kupra, kiu regos super la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'La kvara regno estos malmola, kiel fero; ĉar kiel fero disbatas kaj frakasas ĉion, tiel ankaŭ ĝi, simile al ĉiofrakasanta fero, disbatados kaj frakasados.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Kaj ke vi vidis la piedojn kaj la fingrojn parte el potargilo kaj parte el fero-tio estos regno de miksita konsisto, kaj ĝi enhavos parte la malmolecon de fero, ĉar vi vidis feron miksitan kun potargilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'Sed kiel la fingroj de la piedoj estis parte el fero, parte el argilo, tiel ankaŭ la regno estos parte fortika, parte rompebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Kaj ke vi vidis feron, miksitan kun potargilo, tio signifas, ke ili estos kunigitaj per forto homa, sed ne kunfandiĝos inter si, kiel fero ne kunfandiĝas kun argilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Sed en la tempo de tiuj reĝoj Dio de la ĉielo starigos regnon, kiu neniam detruiĝos, kaj ĝia reĝado ne transiros al alia popolo; ĝi frakasos kaj detruos ĉiujn regnojn, sed ĝi mem staros eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'Vi vidis, ke ŝtono sen ia mano deŝiriĝis de monto, kaj frakasis feron, kupron, argilon, arĝenton, kaj oron; la granda Dio montris al la reĝo, kio estos poste. Tia estas precize la sonĝo kaj ĝia ĝusta klarigo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Tiam la reĝo Nebukadnecar ĵetis sin vizaĝaltere kaj adorkliniĝis al Daniel kaj ordonis alporti al li donacojn kaj bonodorajn incensojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'La reĝo ekparolis al Daniel, kaj diris: Vere, via Dio estas Dio de la dioj kaj Reganto de la reĝoj, malkaŝanta kaŝitaĵojn, kaj tial vi povis malkaŝi tiun kaŝitaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Tiam la reĝo altigis Danielon, donis al li grandajn kaj riĉajn donacojn, kaj faris lin reganto super la tuta lando de Babel kaj ĉefo super ĉiuj saĝuloj de Babel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Daniel petis la reĝon, kaj ĉi tiu starigis Ŝadraĥon, Meŝaĥon, kaj Abed-Negon super la aferoj de la lando Babela; kaj Daniel mem restis ĉe la kortego de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'La reĝo Nebukadnecar faris oran statuon, kiu havis la alton de sesdek ulnoj kaj la larĝon de ses ulnoj; kaj li starigis ĝin en la valo Dura en la lando Babela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Kaj la reĝo Nebukadnecar sendis al la satrapoj, regionestroj, militestroj, ĉefaj juĝistoj, urbestroj, leĝistoj, oficistoj, kaj potenculoj de la lando, ke ili venu al la solena malkovro de la statuo, kiun starigis la reĝo Nebukadnecar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Tiam kunvenis la satrapoj, regionestroj, militestroj, ĉefaj juĝistoj, urbestroj, leĝistoj, oficistoj, kaj potenculoj de la lando, al la solena malkovro de la statuo, kiun la reĝo Nebukadnecar starigis; kaj ili stariĝis antaŭ la statuo, kiun Nebukadnecar starigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Kaj heroldo laŭte proklamis: Estas sciigate al vi, ho popoloj, gentoj, kaj lingvoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'kiam vi aŭdos la sonon de korno, fluto, harpo, sabeko, psaltero, sakfajfilo, kaj diversaj muzikaj instrumentoj, tiam faligu vin kaj adorkliniĝu al la ora statuo, kiun starigis la reĝo Nebukadnecar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Kiu ne faligos sin kaj ne adorkliniĝos, tiu tuj estos ĵetita en ardantan fornon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Tial, kiam ĉiuj popoloj ekaŭdis la sonon de korno, fluto, harpo, sabeko, psaltero, kaj diversaj muzikaj instrumentoj, ili faligis sin kaj adorkliniĝis al la ora statuo, kiun starigis la reĝo Nebukadnecar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'En tiu tempo tuj aliris kelkaj Ĥaldeoj kaj akuzis la Judojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Ili ekparolis, kaj diris al la reĝo Nebukadnecar: Ho reĝo, vivu eterne!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Vi, ho reĝo, ordonis, ke ĉiu homo, kiu aŭdos la sonon de korno, fluto, harpo, sabeko, psaltero, sakfajfilo, kaj diversaj muzikaj instrumentoj, faligu sin kaj adorkliniĝu al la ora statuo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'kaj kiu ne faligos sin kaj ne adorkliniĝos, tiu estu ĵetita en ardantan fornon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Ekzistas tamen viroj Judaj, kiujn vi starigis super la aferoj de la lando Babela, Ŝadraĥ, Meŝaĥ, kaj Abed-Nego; kaj tiuj homoj ne obeas vian ordonon, ho reĝo, ne servas al viaj dioj, kaj ne adorkliniĝas al la ora statuo, kiun vi starigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Tiam Nebukadnecar en kolero kaj furiozo ordonis venigi Ŝadraĥon, Meŝaĥon, kaj Abed-Negon; kaj oni tuj venigis tiujn virojn al la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Nebukadnecar ekparolis, kaj diris al ili: Ĉu intence vi, ho Ŝadraĥ, Meŝaĥ, kaj Abed-Nego, ne servas al miaj dioj, kaj ne adorkliniĝas al la ora statuo, kiun mi starigis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'De nun, kiam vi ekaŭdos la sonon de korno, fluto, harpo, sabeko, psaltero, sakfajfilo, kaj diversaj muzikaj instrumentoj, estu pretaj tuj faligi vin kaj adorkliniĝi al la statuo, kiun mi faris; se vi ne adorkliniĝos, tiam vi tuj estos ĵetitaj en ardantan fornon; kaj tiam kia dio savos vin el miaj manoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Ŝadraĥ, Meŝaĥ, kaj Abed-Nego respondis kaj diris al la reĝo: Ho Nebukadnecar, ne estas al ni malfacile respondi al vi pri tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Ni havas Dion, al kiu ni servas; Li povas savi nin el la ardanta forno kaj ankaŭ savi nin el via mano, ho reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Kaj se Li eĉ tion ne faros, vi tamen sciu, ho reĝo, ke al viaj dioj ni ne servos, kaj al la ora statuo, kiun vi starigis, ni ne adorkliniĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Tiam Nebukadnecar pleniĝis de furiozo, kaj la aspekto de lia vizaĝo ŝanĝiĝis pro kolero kontraŭ Ŝadraĥ, Meŝaĥ, kaj Abed-Nego; kaj li ordonis ardigi la fornon sepoble pli forte, ol oni faradis ordinare.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'Kaj al la plej fortaj militistoj el sia militistaro li ordonis ligi Ŝadraĥon, Meŝaĥon, kaj Abed-Negon, kaj ĵeti ilin en la ardantan fornon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Tiam oni ligis tiujn virojn en ilia suba kaj supra vesto, en iliaj kapkovroj kaj aliaj vestoj, kaj oni ĵetis ilin en la ardantan fornon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Kaj ĉar la ordono de la reĝo estis severa kaj la forno estis ardigita treege, tial tiujn homojn, kiuj ĵetis Ŝadraĥon, Meĥaĥon, kaj Abed-Negon, mortigis la flamo de la fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Kaj tiuj tri viroj, Ŝadraĥ, Meŝaĥ, kaj Abed-Nego, falis ligitaj en la ardantan fornon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Tiam la reĝo Nebukadnecar ekmiregis, kaj en teruro li leviĝis, ekparolis, kaj diris al siaj konsilistoj: Ĉu ne tri virojn ni ĵetis ligitajn en la fajron? Ili respondis al la reĝo: Tiel estas, ho reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Sed li parolis plue, kaj diris: Jen mi vidas kvar virojn, ne ligitajn, kiuj iras meze de la fajro kaj estas sendifektaj; kaj la kvara aspektas kvazaŭ filo de la dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Kaj Nebukadnecar aliris al la aperturo de la ardanta forno, ekparolis, kaj diris: Ho Ŝadraĥ, Meŝaĥ, kaj Abed-Nego, servantoj de Dio la Plejalta! eliru, kaj aliru. Tiam Ŝadraĥ, Meŝaĥ, kaj Abed-Nego eliris el meze de la fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Kaj la satrapoj, regionestroj, militestroj, kaj konsilistoj de la reĝo kunvenis, kaj pririgardis tiujn virojn, super kies korpoj la fajro havis nenian forton, tiel, ke eĉ haro sur ilia kapo ne bruldifektiĝis, iliaj vestoj ne ŝanĝiĝis, kaj eĉ odoron de fajro oni ne sentis sur ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Nebukadnecar ekparolis, kaj diris: Benata estu Dio de Ŝadraĥ, Meŝaĥ, kaj Abed-Nego, kiu sendis Sian anĝelon, kaj savis Siajn servantojn pro tio, ke ili fidis je Li, ne obeis la ordonon de la reĝo, kaj oferis siajn korpojn, por ne servi kaj adorkliniĝi al alia dio, krom sia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Nun mi donas ordonon: Se iu el ia popolo, gento, aŭ lingvo eldiros blasfemon kontraŭ Dio de Ŝadraĥ, Meŝaĥ, kaj Abed-Nego, tiu estos hakita en pecojn kaj lia domo estos ruinigita; ĉar ne ekzistas alia dio, kiu povus savi tiamaniere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Kaj la reĝo denove tre altigis Ŝadraĥon, Meŝaĥon, kaj Abed-Negon en la lando Babela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'La reĝo Nebukadnecar al ĉiuj popoloj, gentoj, kaj lingvoj, kiuj estas sur la tuta tero: Kresku via bonstato!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Mi trovas bona konigi la pruvosignojn kaj miraklojn, kiujn faris sur mi Dio la Plejalta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Kiel grandaj estas Liaj pruvosignoj, kaj kiel potencaj estas Liaj mirakloj! Lia reĝado estas eterna, kaj Lia regado estas en ĉiuj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Mi, Nebukadnecar, estis trankvila en mia domo kaj bonfarta en mia palaco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Sed mi vidis sonĝon, kiu teruris min, kaj la meditado sur mia lito kaj la vizioj de mia kapo min konsternis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Kaj mi donis ordonon venigi al mi ĉiujn saĝulojn de Babel, por ke ili diru al mi la signifon de la sonĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Tiam venis la astrologoj, sorĉistoj, Ĥaldeoj, kaj divenistoj; mi rakontis al ili la sonĝon, sed ili ne povis klarigi al mi ĝian signifon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Fine venis al mi Daniel, al kiu estis donita la nomo Beltŝacar, laŭ la nomo de mia dio, kaj kiu havas en si la spiriton de la sanktaj dioj; mi rakontis al li la sonĝon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Ho Beltŝacar, ĉefo de la astrologoj, pri kiu mi scias, ke en vi estas la spirito de la sanktaj dioj kaj nenia kaŝitaĵo vin embarasas: klarigu al mi la vizion de mia sonĝo kaj ĝian signifon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'La vizio de mia kapo sur mia lito estis jena: mi vidis, ke jen meze de la tero staras arbo tre alta;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'tiu arbo estas bonkreska kaj forta, kaj ĝia alto atingas la ĉielon, kaj oni ĝin vidas ĝis la randoj de la tuta tero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'ĝia foliaro estas bela, kaj multe da fruktoj estas sur ĝi, kaj sur ĝi troviĝas manĝaĵo por ĉiuj; en la ombro sub ĝi kaŝas sin bestoj de la kampo, kaj sur ĝiaj branĉoj sidas birdoj de la ĉielo, kaj ĉiu karno nutras sin de ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Kaj mi vidis en la vizioj de mia kapo sur mia lito, ke jen sankta prizorganto malsupreniris de la ĉielo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'kaj per laŭta voĉo li diris: Dehaku ĉi tiun arbon, ĉirkaŭhaku ĝiajn branĉojn, deprenu de ĝi la foliaron, kaj disĵetu ĝiajn fruktojn, por ke foriĝu la bestoj, kiuj estas sub ĝi, kaj la birdoj forflugu de ĝiaj branĉoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Sed ĝian ĉefan radikon restigu en la tero, en ĉenoj feraj kaj kupraj, meze de la herbo de la kampo; ĝin trinkigu la roso de la ĉielo, kaj kune kun la bestoj ĝi nutru sin per la herboj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'La homa koro estos prenita for de ĝi, kaj ĝi ricevos koron bestan, kaj tiel pasos super ĝi sep jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Per la ordono de la prizorgantoj tio estas decidita, kaj per la dekreto de la sanktuloj tio estas destinita, por ke la vivantoj sciu, ke la Plejaltulo regas en la regno de la homoj, kaj donas ĝin al tiu, al kiu Li volas, kaj starigas super ĝi la plej humilan el la homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Tian sonĝon vidis mi, reĝo Nebukadnecar. Kaj vi, ho Beltŝacar, diru ĝian signifon; ĉar neniu el la saĝuloj en mia regno povas klarigi ĝian signifon, sed vi povas, ĉar vi havas en vi la spiriton de la sanktaj dioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Tiam Daniel, kiu havis la nomon Beltŝacar, en la daŭro de unu horo staris konsternite, kaj liaj pensoj lin malĝojigis. La reĝo ekparolis, kaj diris: Ho Beltŝacar, ne embarasu vin la sonĝo kaj ĝia signifo. Beltŝacar respondis kaj diris: Ho mia sinjoro, por viaj malamikoj estu tiu sonĝo, kaj por viaj malamantoj estu ĝia signifo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'La arbo, kiun vi vidis, kiu elkreskis alte kaj forte, atingis per sia pinto la ĉielon, kaj estis videbla sur la tuta tero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'kaj sur kiu estis bela foliaro, multe da fruktoj kaj manĝaĵo por ĉiuj, sub kiu sidis bestoj de la kampo, kaj sur kies branĉoj sidis birdoj de la ĉielo-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'tio estas vi, ho reĝo altiĝinta; via grandeco kreskis kaj atingis ĝis la ĉielo, kaj via potenco ĝis la randoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Kaj ke la reĝo vidis sanktan prizorganton, kiu malsupreniris de la ĉielo, kaj diris: Dehaku la arbon kaj ekstermu ĝin, sed nur ĝian ĉefan radikon restigu en la tero, en ĉenoj feraj kaj kupraj, meze de la herbo de la kampo, ĝin trinkigu la roso de la ĉielo, kaj ĝi havu la sorton de la bestoj de la kampo, ĝis pasos super ĝi sep jaroj-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'jen estas la signifo de tio, ho reĝo: tio estas dekreto de la Plejaltulo, kiu trafos mian sinjoron, la reĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Vi estos elpuŝita el meze de la homoj, kaj vi vivos kun la bestoj de la kampo; per herbo oni vin nutros, kiel bovojn; roson de la ĉielo oni trinkigos al vi; kaj sep jaroj pasos super vi, ĝis vi ekscios, ke super la regno de homoj regas la Plejaltulo, kaj donas ĝin al tiu, al kiu Li volas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Kaj ke estas ordonite restigi la ĉefan radikon de la arbo-tio signifas, ke via regno estos redonita al vi, kiam vi konfesos la potencon de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'Tial, ho reĝo, volu favore akcepti mian konsilon: liberigu vin de viaj pekoj per justeco kaj de viaj malbonagoj per favorkoreco al malriĉuloj; per tio via bonstato fariĝos longedaŭra.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Ĉio ĉi tio efektiviĝis sur la reĝo Nebukadnecar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Post paso de dek du monatoj, promenante tra la reĝa palaco en Babel,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'la reĝo ekparolis, kaj diris: Ĉu tio ne estas la majesta Babel, kiun por restado de la reĝo mi aranĝis per la forto de mia potenco kaj por la gloro de mia majesto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'Kiam ĉi tiu parolo estis ankoraŭ en la buŝo de la reĝo, eksonis voĉo el la ĉielo: Al vi, ho reĝo Nebukadnecar, estas dirate: La regno estas prenata for de vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'kaj vi estas elpuŝata el meze de la homoj, kaj vi vivos kun la bestoj de la kampo; per herbo oni vin nutros, kiel bovojn; kaj sep jaroj pasos super vi, ĝis vi ekscios, ke super la regno de homoj regas la Plejaltulo, kaj donas ĝin al tiu, al kiu Li volas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'Tuj plenumiĝis tiu verdikto sur Nebukadnecar; li estis elpuŝita el meze de la homoj, li komencis manĝis herbon, kiel bovoj, lia korpo estis trinkigata de la roso de la ĉielo, tiel, ke liaj haroj kreskis kiel la plumoj de aglo kaj liaj ungoj fariĝis kiel ĉe birdo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Post paso de la difinita tempo, mi, Nebukadnecar, levis miajn okulojn al la ĉielo, kaj mia prudento revenis al mi; kaj mi benis la Plejaltulon, mi laŭdis kaj gloris Tiun, kiu vivas eterne, kies regado estas regado eterna kaj kies regno daŭras en ĉiuj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, 'Ĉiuj, kiuj vivas sur la tero, estas kalkuleblaj kiel nenio. Laŭ Sia volo Li agas, kiel kun la armeo de la ĉielo, tiel kun la vivantoj sur la tero; kaj ekzistas neniu, kiu povus kontraŭstari al Lia mano, aŭ demandi Lin: Kion Vi faras?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, 'En tiu tempo revenis al mi mia prudento, kaj mi ricevis denove mian reĝan honoron, mian majeston, kaj mian antaŭan aspekton; tiam elserĉis min miaj konsilistoj kaj miaj altranguloj, mi estis denove starigita super mia regno, kaj mia majesto fariĝis ankoraŭ pli granda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, 'Nun mi, Nebukadnecar, laŭdas, altigas, kaj gloras la Reĝon de la ĉielo, kies ĉiuj faroj estas veraj kaj kies vojoj estas ĝustaj, kaj kiu la fierulojn povas humiligi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'La reĝo Belŝacar faris grandan festenon por siaj mil eminentuloj kaj multe drinkis kun tiuj mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Fariĝinte ebria, Belŝacar ordonis alporti la orajn kaj arĝentajn vazojn, kiujn lia patro Nebukadnecar venigis el la templo de Jerusalem, por ke el ili trinku la reĝo kaj liaj eminentuloj, liaj edzinoj kaj kromvirinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Tiam oni alportis la orajn vazojn, kiuj estis prenitaj el la sanktejo de la domo de Dio en Jerusalem; kaj trinkis el ili la reĝo kaj liaj eminentuloj, liaj edzinoj kaj kromvirinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Ili trinkis vinon, kaj gloris la diojn orajn kaj arĝentajn, kuprajn, ferajn, lignajn, kaj ŝtonajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'En tiu momento aperis fingroj de homa mano kaj komencis skribi kontraŭ la kandelabro sur la kalkita muro de la reĝa salono; kaj la reĝo vidis la manon, kiu skribis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Tiam ŝanĝiĝis la vizaĝaspekto de la reĝo, liaj pensoj konfuziĝis, la ligiloj de liaj lumboj malstreĉiĝis, kaj liaj genuoj tremante kunfrapiĝadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'La reĝo laŭtege ekkriis, ke oni venigu la magiistojn, Ĥaldeojn, kaj divenistojn. La reĝo ekparolis, kaj diris al la saĝuloj de Babel: Kiu ajn tralegos ĉi tiun surskribon kaj klarigos al mi ĝian signifon, tiu ricevos purpuran veston, ora ĉeno estos sur lia kolo, kaj li estos la tria reganto en la regno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Tiam venis ĉiuj saĝuloj de la reĝo; sed ili ne povis tralegi la surskribon, nek klarigi al la reĝo ĝian signifon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'La reĝo Belŝacar forte maltrankviliĝis, kaj lia vizaĝaspekto ŝanĝiĝis, kaj antaŭ liaj eminentuloj konfuziĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Ĉe tiu okazintaĵo, kiu fariĝis al la reĝo kaj al liaj altranguloj, en la salonon de la festeno eniris la reĝino. La reĝino ekparolis, kaj diris: Ho reĝo, vivu eterne! Ne konsternu vin viaj pensoj, kaj ne ŝanĝiĝu via vizaĝaspekto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'En via regno ekzistas viro, kiu havas en si la spiriton de la sanktaj dioj; en la tempo de via patro oni trovis en li lumon, prudenton, kaj saĝon, similan al la saĝo de la dioj; kaj la reĝo Nebukadnecar, via patro, la reĝo mem, via patro, faris lin ĉefo de la astrologoj, sorĉistoj, Ĥaldeoj, kaj divenistoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'ĉar en li oni trovis altan spiriton, scion, kaj prudenton, por klarigi sonĝojn, komentarii sentencojn, kaj malkaŝi kaŝitaĵojn. Tio estas Daniel, al kiu la reĝo donis la nomon Beltŝacar. Tial oni voku Danielon, kaj li klarigos la signifon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Tiam oni alkondukis Danielon antaŭ la reĝon; kaj la reĝo ekparolis, kaj diris al Daniel: Ĉu vi estas Daniel, unu el la forkaptitaj filoj de Judujo, kiujn mia patro, la reĝo, venigis el Judujo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Mi aŭdis pri vi, ke la spirito de la dioj estas en vi, kaj ke lumo, prudento, kaj eksterordinara saĝo troviĝas en vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Nun estis alkondukitaj al mi la saĝuloj kaj magiistoj, por tralegi ĉi tiun surskribon kaj klarigi al mi ĝian signifon; sed ili ne povis klarigi al mi la sencon de ĉi tiuj vortoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Sed mi aŭdis pri vi, ke vi povoscias klarigi signifon kaj malkaŝi kaŝitaĵon. Tial, se vi povas tralegi ĉi tiun surskribon kaj klarigi al mi ĝian signifon, vi ricevos purpuran veston, ora ĉeno estos sur via kolo, kaj vi estos la tria reganto en la regno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Tiam Daniel respondis kaj diris al la reĝo: Viaj donacoj restu ĉe vi, viajn rekompencojn donu al iu alia; mi tamen tralegos al la reĝo la surskribon, kaj mi klarigos al li la signifon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Ho reĝo! Dio la Plejalta donis al via patro Nebukadnecar regnon, potencon, honoron, kaj gloron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'Pro la potenco, kiun Li donis al li, ĉiuj popoloj, gentoj, kaj lingvoj tremis kaj havis timon antaŭ li; kiun li volis, li mortigis, kaj kiun li volis, li lasis vivi; kiun li volis, li altigis, kaj kiun li volis, li malaltigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Sed kiam lia koro fieriĝis kaj lia spirito malhumiliĝis, li estis deĵetita el sia reĝa trono kaj senigita je sia gloro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'kaj li estis elpuŝita el meze de la homoj, kaj lia koro fariĝis simila al koro de besto, kaj li vivis kun sovaĝaj azenoj; li manĝis herbon, kiel la bovoj, kaj lia korpo estis trinkigata per la roso de la ĉielo; ĝis li eksciis, ke super la regno de homoj regas Dio la Plejalta, kaj donas ĝin al tiu, al kiu Li volas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Vi, lia filo, ho Belŝacar, ne humiligis vian koron, kvankam vi sciis ĉion tion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'sed vi levis vin kontraŭ la Reganton de la ĉielo, tiel, ke la vazojn el Lia domo oni alportis al vi, kaj vi kun viaj eminentuloj, kun viaj edzinoj kaj kromvirinoj, trinkis vinon el ili; kaj vi gloris la diojn arĝentajn kaj orajn, kuprajn, ferajn, lignajn, kaj ŝtonajn, kiuj ne vidas, ne aŭdas, kaj ne pensas; kaj Dion, en kies mano estas la spiro de via vivo kaj ĉiuj viaj vojoj, vi ne gloris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Pro tio estas sendita de Li la mano kaj skribita ĉi tiu surskribo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'Jen estas la surskribo, kiu estas desegnita: MENE, MENE, TEKEL, UFARSIN.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Jen estas la signifo de la vortoj: MENE: Dio kalkulis la tempon de via reĝado kaj metis al ĝi finon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'TEKEL: vi estas pesita sur pesilo kaj trovita tro malpeza;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'PERES: via regno estas dividita kaj donita al la Medoj kaj Persoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Tiam laŭ ordono de Belŝacar oni metis purpuran veston sur Danielon kaj oran ĉenon sur lian kolon, kaj oni proklamis lin la tria reganto en la regno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'En tiu sama nokto Belŝacar, reĝo de la Ĥaldeoj, estis mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, 'Dario, la Medo, ricevis la regnon, havante la aĝon de sesdek du jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Kaj Dario bonvolis starigi super sia regno cent dudek satrapojn, por administri lian tutan regnon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'kaj super ili tri ĉefajn estrojn, inter kiuj estis ankaŭ Daniel, por ke la satrapoj donadu al ili kalkulraportojn, kaj por ke la reĝo ne havu malprofiton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Sed Daniel superis la aliajn ĉefajn estrojn kaj satrapojn, ĉar li havis eksterordinaran saĝon; kaj la reĝo havis jam la intencon starigi lin super la tuta regno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Tiam la ĉefaj estroj kaj la satrapoj komencis serĉi pretekston, por akuzi Danielon koncerne la aferojn de la regno. Sed ili povis trovi nenian pretekston nek kulpon; ĉar li estis fidela, kaj nenia kulpo nek krimo estis trovebla en li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Tiam tiuj homoj diris: Ni ne povos trovi kulpon en tiu Daniel, se ni ne trovos ion kontraŭ li en la leĝoj de lia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Kaj tiuj ĉefaj estroj kaj satrapoj venis al Dario, kaj diris al li tiel: Ho reĝo Dario, vivu eterne!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Ĉiuj ĉefaj estroj de la regno, regionestroj, satrapoj, konsilistoj, kaj militestroj interkonsentis, ke oni devas elirigi reĝan dekreton kaj severe ordoni, ke ĉiun, kiu en la daŭro de tridek tagoj petos ion de ia dio aŭ homo anstataŭ de vi, ho reĝo, oni ĵetu en kavon de leonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Tial konfirmu, ho reĝo, ĉi tiun decidon, kaj subskribu la ordonon, por ke ĝi ne estu malobeata, kiel leĝo de Medujo kaj Persujo, kiun neniu povas senvalorigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'La reĝo Dario subskribis la dekreton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Kiam Daniel eksciis, ke estas subskribita tia ordono, li iris en sian domon, kaj antaŭ la fenestroj de sia ĉambro, malfermitaj en la direkto al Jerusalem, li tri fojojn ĉiutage genuis kaj preĝis al sia Dio kaj gloradis Lin, kiel li faradis antaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Tiam tiuj homoj ĉirkaŭis Danielon, kaj trovis lin preĝanta kaj petanta favorkorecon antaŭ sia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Kaj ili iris, kaj diris al la reĝo koncerne la reĝan dekreton: Ĉu vi ne ordonis per dekreto, ke ĉiun homon, kiu en la daŭro de tridek tagoj petos ion de ia dio aŭ homo krom vi, ho reĝo, oni ĵetu en kavon de leonoj? La reĝo respondis kaj diris: Jes, tio efektive estas dekretita, kiel neforigebla leĝo de Medujo kaj Persujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Tiam ili respondis kaj diris al la reĝo: Jen Daniel, kiu estas el la transloĝigitaj filoj de Judujo, ne atentas vin, ho reĝo, nek la dekreton, subskribitan de vi, sed tri fojojn ĉiutage li preĝas siajn preĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Aŭdinte tion, la reĝo forte afliktiĝis en sia animo, kaj, dezirante savi Danielon, li multe klopodis ĝis la subiro de la suno, por liberigi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Sed tiuj homoj ĉirkaŭis la reĝon, kaj diris al li: Sciu, ho reĝo, ke laŭ la leĝoj de Medujo kaj Persujo ĉiu malpermeso aŭ ordono, konfirmita de la reĝo, devas resti neŝanĝebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Tiam la reĝo ordonis, kaj oni alkondukis Danielon, kaj ĵetis lin en kavon de leonoj. Sed la reĝo diris al Daniel: Via Dio, al kiu vi senĉese servas, savu vin!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Kaj oni alportis ŝtonon kaj metis ĝin sur la aperturon de la kavo; kaj la reĝo sigelis ĝin per sia ringo kaj per la ringo de siaj altranguloj, por ke ne fariĝu ia ŝanĝo koncerne Danielon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Poste la reĝo iris en sian palacon, pasigis la nokton en fastado, eĉ ne permesis alporti al li manĝaĵon; kaj ankaŭ dormi li ne povis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Matene la reĝo leviĝis ĉe la tagiĝo kaj iris rapide al la kavo de la leonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'Kaj kiam li alvenis al la kavo, li vokis per malĝoja voĉo Danielon; kaj ekparolinte, la reĝo diris al Daniel: Ho Daniel, servanto de la vivanta Dio! ĉu via Dio, al kiu vi senĉese servas, povis savi vin de la leonoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Tiam Daniel respondis al la reĝo: Ho reĝo, vivu eterne!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Mia Dio sendis Sian anĝelon, kaj baris la buŝon de la leonoj, kaj ili faris al mi nenian difekton; ĉar mi estis trovita pura antaŭ Li; kaj ankaŭ antaŭ vi, ho reĝo, mi ne faris krimon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Tiam la reĝo tre ekĝojis pri li kaj ordonis levi Danielon el la kavo. Kaj oni eligis Danielon el la kavo, kaj nenia difekto montriĝis sur li; ĉar li kredis al sia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Kaj la reĝo ordonis alkonduki tiujn virojn, kiuj per sia akuzo volis pereigi Danielon, kaj ĵeti en la kavon de la leonoj ilin mem, kaj ankaŭ iliajn infanojn kaj iliajn edzinojn; kaj ankoraŭ antaŭ ol ili atingis la fundon de la kavo, la leonoj kaptis ilin kaj frakasis ĉiujn iliajn ostojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Post tio la reĝo Dario skribis al ĉiuj popoloj, gentoj, kaj lingvoj de la tuta tero: Kresku via bonfarto!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Mi donas ordonon, ke en ĉiu regiono de mia regno oni timu kaj respektu Dion de Daniel; ĉar Li estas Dio vivanta kaj eterne restanta, Lia regno estas nedetruebla, kaj Lia regado estas senfina.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'Li liberigas kaj savas, Li faras miraklojn kaj pruvosignojn en la ĉielo kaj sur la tero; Li savis Danielon kontraŭ leonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'Kaj Daniel havis sukceson dum la reĝado de Dario, kaj dum la reĝado de Ciro, la Perso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'En la unua jaro de Belŝacar, reĝo de Babel, Daniel havis sonĝon kaj vizion de sia kapo sur sia lito. Li enskribis tiun sonĝon, prezentinte la esencon de la afero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Daniel komencis sian rakonton, dirante: Mi vidis en mia nokta vizio, ke jen kvar ventoj de la ĉielo batalas inter si sur granda maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Kaj eliris el la maro kvar grandegaj bestoj malsimilaj unu al alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'La unua estis kiel leono, sed ĝi havis flugilojn de aglo; mi vidis, kiel fine oni deŝiris de ĝi la flugilojn, oni levis ĝin de la tero, kaj starigis sur piedoj, kiel homon, kaj homa koro estis donita al ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Jen ankaŭ dua besto, simila al urso, staris ĉe ĝia flanko, kaj tri kojnodentojn ĝi havis en sia buŝo, inter siaj dentoj. Kaj estis dirite al ĝi: Leviĝu, kaj manĝu multe da karno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Poste mi vidis ankoraŭ unu beston, similan al leopardo; sur sia dorso ĝi havis kvar flugilojn de birdo, kaj kvar kapojn havis tiu besto, kaj potenco estis donita al ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Poste mi vidis en la nokta vizio beston kvaran, teruran, monstran, kaj tre fortan; ĝi havis grandegajn ferajn dentojn; ĝi manĝegis kaj frakasis, kaj la restaĵon ĝi dispremis per la piedoj; ĝi estis malsimila al ĉiuj antaŭaj bestoj kaj havis dek kornojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Mi rigardis tiujn kornojn, kaj jen inter ili aperis alia korno, malgranda; kaj tri el la antaŭaj kornoj estis elŝiritaj antaŭ ĝi kun la radiko; kaj jen montriĝis, ke tiu korno havas okulojn, kiel okuloj de homo, kaj buŝon, kiu parolas malhumile.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Fine mi vidis, ke estas starigitaj tronoj, kaj sidiĝis la Antaŭtempulo. Lia vesto estis blanka kiel neĝo, kaj la haroj sur Lia kapo estis kiel pura lano; Lia trono estis brilantaj flamoj, ĝiaj radoj estis flamanta fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Fajra rivero elfluis kaj disverŝiĝis antaŭ Li; miloj da miloj servis al Li, kaj dekmiloj da dekmiloj staris antaŭ Li. La juĝantoj sidiĝis, kaj la libroj malfermiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Tiam mi vidis, kiel fine, pro la malhumilaj vortoj, kiujn parolis la korno, la besto estis mortigita, kaj ĝia korpo estis frakasita, kaj ĵetita en fajron, por forbruli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Ankaŭ de la aliaj bestoj oni forprenis ilian potencon, kaj daŭro de la vivo estis donita al ili nur por difinita tempo kaj ĝis difinita templimo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Poste mi vidis en la nokta vizio, ke jen en la nuboj de la ĉielo iris kvazaŭ filo de homo, venis al la Antaŭtempulo, kaj estis alkondukita al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Kaj al li estis donita potenco, gloro, kaj regno, por ke ĉiuj popoloj, gentoj, kaj lingvoj servu al li; lia regado estas regado eterna, kiu ne ĉesiĝos, kaj lia regno ne detruiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Ĉe mi, Daniel, ektremis mia spirito en mia korpo, kaj la vizio de mia kapo konsternis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Mi aliris al unu el la antaŭstarantoj kaj demandis lin pri la vera signifo de ĉio ĉi tio, kaj li komencis paroli al mi kaj klarigis al mi la sencon de la diritaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Tiuj kvar grandaj bestoj signifas, ke kvar regnoj formiĝos sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Poste prenos la regnon la sanktuloj de la Plejaltulo, kaj ili posedos la regnon eterne, en eterna eterneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Tiam mi deziris havi precizan klarigon pri la kvara besto, kiu estis malsimila al ĉiuj, kaj terura, kun feraj dentoj kaj kupraj ungegoj, manĝegis kaj frakasis kaj la restaĵon dispremis per la piedoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'kaj pri la dek kornoj, kiuj estis sur ĝia kapo, kaj pri la alia, kiu poste eliris kaj antaŭ kiu elfalis tri, pri tiu sama korno, kiu havis okulojn kaj buŝon parolantan malhumile, kaj kiu laŭ sia aspekto estis pli granda ol la aliaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Mi vidis, kiel tiu korno komencis bataladon kontraŭ la sanktuloj kaj estis jam venkanta ilin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'ĝis venis la Antaŭtempulo; tiam la juĝo estis farita por la sanktuloj de la Plejaltulo, kaj venis la tempo, kiam la regnon ekposedis la sanktuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Kaj li diris: La kvara besto estas la kvara regno, kiu estos sur la tero, malsimila al ĉiuj regnoj, kaj ĝi manĝegos la tutan teron, piedpremos kaj frakasos ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'La dek kornoj signifas, ke el tiu regno aperos dek reĝoj, kaj post ili eliros alia, malsimila al la antaŭaj, kaj faligos tri reĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Li blasfemos kontraŭ la Plejaltulo kaj frapos la sanktulojn de la Plejaltulo; li eĉ arogos al si ŝanĝi la tempojn kaj leĝojn. Ili estos transdonitaj en lian manon ĝis paso de unu tempo kaj du tempoj kaj duono de tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Poste aperos juĝo, kaj ĝi forprenos de li la potencon, por lia pereo kaj plena ekstermiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Sed la regado, potenco, kaj grandeco de la regnoj sub la tuta ĉielo estos donita al la sankta popolo de la Plejaltulo, kies regno estas regno eterna, kaj ĉiuj potenculoj servados kaj obeados al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Ĉi tie finiĝas la parolo. Mi, Daniel, estis tre konsternita de mia meditado, kaj mia vizaĝaspekto ŝanĝiĝis sur mi; sed la parolon mi konservis en mia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'En la tria jaro de reĝado de la reĝo Belŝacar aperis al mi, al Daniel, vizio, post tiu, kiu aperis al mi en la komenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Kiam mi vidis la vizion, mi estis en la kastelurbo Ŝuŝan, kiu troviĝas en la lando Elam; sed en la vizio mi vidis, ke mi estas ĉe la rivero Ulaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Mi levis miajn okulojn, kaj mi ekvidis: jen unu virŝafo staras ĉe la rivero; ĝi havas du kornojn, kaj ambaŭ kornoj estas altaj, sed unu estas pli alta ol la dua, kaj la pli alta elkreskis poste.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Mi vidis, ke tiu virŝafo kornopuŝas okcidenten, norden, kaj suden, kaj nenia besto povas kontraŭstari al ĝi, kaj neniu povas savi kontraŭ ĝia forto; kaj ĝi faras ĉion, kion ĝi volas, kaj ĝi estas granda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Dum mi atente ĝin rigardis, jen de okcidente iras virkapro sur la tutan teron, kaj ĝi ne tuŝas la teron. Tiu virkapro havis bone videblan kornon inter siaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Kaj ĝi iris al tiu kornohava virŝafo, kiun mi vidis starantan ĉe la rivero, kaj ĵetis sin sur ĝin kun furioza forto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'kaj mi vidis, ke, alproksimiĝinte al la virŝafo, ĝi furioziĝis kontraŭ ĝi, frapis la virŝafon, kaj rompis ambaŭ ĝiajn kornojn; kaj la virŝafo ne havis la forton, por kontraŭstari al ĝi, kaj ĉi tiu ĵetis ĝin sur la teron kaj disbatis ĝin per la piedoj; kaj neniu povis savi la virŝafon kontraŭ ĝia forto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Tiam la virkapro forte grandiĝis. Kiam ĝi fariĝis tre forta, rompiĝis la granda korno, kaj anstataŭ ĝi eliris kvar aliaj en la direkto al la kvar ventoj de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'El unu el ili eliris alia korno malgranda, kiu forte kreskis suden kaj orienten kaj al la plej bela lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Kaj ĝi kreskis ĝis la armeo de la ĉielo, kaj ĝi ĵetis sur la teron parton de tiu armeo kaj de la steloj, kaj dispremis ilin per la piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Kaj eĉ kontraŭ la armeestron ĝi leviĝis, forprenis de li la ĉiutagajn oferojn, kaj ruinigis lian sanktan loĝejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Forto estis donita al ĝi kontraŭ la ĉiutagaj oferoj pro peko; kaj ĝi ĵetis la veron sur la teron kaj laboris kun sukceso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Kaj mi aŭdis unu sanktulon, kiu parolis, kaj tiu sanktulo diris al iu, kiu demandis: Ĝis kiam havos forton la profetaĵo pri la ĉiutagaj oferoj kaj pri la terura peko, ke la sanktejo kaj la armeo estos piedpremataj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'Kaj li diris al mi: Ĝis pasos du mil tricent vesperoj kaj matenoj; tiam la sanktejo denove estos sanktigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Dum mi, Daniel, estis rigardanta tiun vizion kaj serĉanta ĝian signifon, jen stariĝis antaŭ mi bildo de viro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Kaj el meze de Ulaj mi aŭdis homan voĉon, kiu vokis kaj diris: Gabriel, klarigu al li la vizion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Kaj li aliris al tiu loko, kie mi staris; kaj kiam li venis, mi eksentis teruron kaj falis vizaĝaltere; kaj li diris al mi: Sciu, ho homido, ke la vizio koncernas la finon de la tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Kiam li parolis al mi, mi kuŝis senkonscie sur la tero; sed li ektuŝis min kaj starigis min sur mia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Kaj li diris: Jen mi sciigas al vi, kio estos ĉe la fino de la kolero; ĉar tio koncernas la finan tempon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'La virŝafo, kiun vi vidis kun la du kornoj, estas la reĝoj de Medujo kaj Persujo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'kaj la vila virkapro estas la reĝo de Grekujo; la granda korno inter ĝiaj okuloj estas la unua reĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'ĝi rompiĝis, kaj anstataŭ ĝi eliris kvar aliaj; kvar regnoj formiĝos el la nacio, sed ne tiel fortaj, kiel ĝi estis antaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'En la fina tempo de tiuj regnoj, kiam la perfiduloj havos sukceson, aperos reĝo malmodesta, lerta ruzulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Li fariĝos potenca, sed ne per sia forto; li faros grandan dezertigadon, li havos sukceson en siaj faroj, li pereigos fortulojn kaj la popolon de la sanktuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'Kaj pro lia saĝeco liaj ruzaĵoj sukcesos en lia mano, kaj li fieriĝos, kaj meze de paco li multajn pereigos, kaj li leviĝos kontraŭ la Princon de la princoj; sed li estos frakasita, kvankam ne per mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'La vizio pri la vespero kaj la mateno, kiu estas dirita al vi, estas vera; sed tenu la vizion sekrete, ĉar ĝi rilatas tempon malproksiman.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Kaj mi, Daniel, senfortiĝis, kaj estis malsana dum kelke da tagoj. Poste mi leviĝis kaj komencis okupadi min per la aferoj de la reĝo. Mi estis konsternita de la vizio, sed neniu tion rimarkis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'En la unua jaro de Dario, filo de Aĥaŝveroŝ, el la gento Meda, kiu fariĝis reĝo super la regno de la Ĥaldeoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'en la unua jaro de lia reĝado, mi, Daniel, rimarkis en la libroj la nombron de la jaroj, pri kiuj la Eternulo parolis al la profeto Jeremia, ke devas finiĝi sepdek jaroj de la dezerteco de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Kaj mi turnis mian vizaĝon al Dio, la Sinjoro, por preĝi kaj petegi, en fastado, sakaĵo, kaj cindro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Kaj mi preĝis al la Eternulo, mia Dio, mi faris konfeson, kaj mi diris: Mi petas Vin, ho Sinjoro, Dio granda kaj timinda, kiu konservas la interligon kaj favorkorecon al Liaj amantoj kaj al la plenumantoj de Liaj ordonoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Ni pekis, ni malbonagis, ni estis malpiaj, ni ribelis, kaj ni defalis de Viaj ordonoj kaj decidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'ni ne aŭskultis Viajn servantojn, la profetojn, kiuj parolis en Via nomo al niaj reĝoj, estroj, kaj patroj, kaj al la tuta popolo de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Vi, ho Sinjoro, estas prava, kaj ni devas honti, kiel nun, ĉiu Judo, la loĝantoj de Jerusalem kaj la tuta Izrael, la proksimaj kaj la malproksimaj, en ĉiuj landoj, kien Vi dispelis ilin pro iliaj malbonagoj, kiujn ili faris koncerne Vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Ho Sinjoro! ni hontas pro niaj reĝoj, estroj, kaj patroj, kiuj pekis antaŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Sed la Sinjoro, nia Dio, havas kompatemon kaj pardonemon, kvankam ni defalis de Li');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'kaj ne aŭskultis la voĉon de la Eternulo, nia Dio, por iradi laŭ Liaj instruoj, kiujn Li donis al ni per Siaj servantoj, la profetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'La tuta Izrael malobeis Vian instruon, kaj deturnis sin, por ne aŭskulti Vian voĉon; pro tio trafis nin la malbeno kaj la ĵuro, pri kiuj estas skribite en la instruo de Moseo, servanto de Dio; ĉar ni pekis kontraŭ Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'Kaj Li plenumis Sian vorton, kiun Li diris pri ni, kaj pri niaj juĝistoj, kiuj faradis juĝon ĉe ni, kaj Li venigis sur nin grandan malfeliĉon; sub la tuta ĉielo nenie fariĝis tio, kio fariĝis al Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Kiel estas skribite en la instruo de Moseo, tiel trafis nin tiu tuta malfeliĉo; ni tamen ne preĝis antaŭ la Eternulo, nia Dio, deturnante nin de niaj malbonagoj kaj penante kompreni Vian veron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Kaj la Eternulo viglis super la malfeliĉo kaj venigis ĝin sur nin; ĉar justa estas la Eternulo, nia Dio, en ĉiuj Siaj faroj, kiujn Li faras, sed ni ne aŭskultis Lian voĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Kaj nun, ho Sinjoro, nia Dio, kiu elkondukis Vian popolon el la lando Egipta per forta mano, kaj faris al Vi gloran nomon, kiel ĝi nun estas, ni pekis, ni estis malpiaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Ho Sinjoro, konforme al Via tuta bonfaremeco deturniĝu nun Via kolero kaj Via indigno de Via urbo Jerusalem, de Via sankta monto; ĉar pro niaj pekoj kaj pro la malbonagoj de niaj patroj Jerusalem kaj Via popolo estas hontindaĵo antaŭ ĉiuj niaj ĉirkaŭantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Kaj nun aŭskultu, ho nia Dio, la preĝon de Via servanto kaj lian petegon, kaj lumu per Via vizaĝo sur Vian dezertigitan sanktejon, pro la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Klinu, ho mia Dio, Vian orelon, kaj aŭskultu; malfermu Viajn okulojn, kaj vidu nian ruinigitecon, kaj la urbon, kiu estas nomata per Via nomo; ĉar ne pro nia praveco, sed pro Via granda kompatemeco, ni faligas antaŭ Vi nian preĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Ho Sinjoro, aŭskultu! ho Sinjoro, pardonu! ho Sinjoro, atentu kaj agu, ne prokrastu, pro Vi mem, ho mia Dio, ĉar Vian nomon portas Via urbo kaj Via popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Dum mi ankoraŭ parolis kaj preĝis kaj konfesis miajn pekojn kaj la pekojn de mia popolo Izrael kaj metis mian petegon antaŭ la Eternulon, mian Dion, pri la sankta monto de mia Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'dum mi ankoraŭ parolis preĝante, la viro Gabriel, kiun mi vidis antaŭe en la vizio, alflugis, kaj ektuŝis min ĉirkaŭ la tempo de la vespera ofero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'kaj, klarigante, li ekparolis al mi, kaj diris: Ho Daniel, nun mi eliris, por komprenigi al vi la aferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Ĉe la komenco de via preĝado eliris ordono, kaj mi venas, por sciigi ĝin, ĉxar vi estas homo agrabla al Dio; atentu la vorton, kaj komprenu la vizion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Sepdek jarsepoj estas destinitaj por via popolo kaj por via sankta urbo, por ke kovriĝu la kulpo, sigeliĝu la pekoj, kaj pardoniĝu la malbonagoj, por ke venu justeco eterna, sigeliĝu la vizio kaj profetaĵo, kaj sanktoleiĝu Plejsanktulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Sciu, kaj komprenu: de la momento, kiam eliros la ordono, ke Jerusalem estu denove konstruata, ĝis la sanktoleado de la estro pasos sep jarsepoj kaj sesdek du jarsepoj; kaj denove estos konstruitaj la stratoj kaj muroj, kvankam en tempo malfacila.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'Post la sesdek du jarsepoj la sanktoleito estos pereigita kaj jam ne ekzistos; kaj la urbon kun ĝia sanktejo pereigos popolo de estro, kiu venos, kaj ĝia fino estos kiel de inundego; kaj ĝis la fino de la milito ĝi estos tute dezertigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'En la daŭro de unu jarsepo estos konfirmita la interligo kun multaj, kaj meze de la jarsepo estos ĉesigitaj buĉoferoj kaj farunoferoj; sur la flugiloj de la sanktejo estos abomeninda dezerteco, ĝis la fina destinita pereo falos sur la ruinojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'En la tria jaro de Ciro, reĝo de Persujo, vorto estis malkaŝita al Daniel, kiu havis la nomon Beltŝacar; kaj vera estis tiu vorto kaj tre grava. Li komprenis la vorton kaj komprenis bone la vizion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'En tiu tempo mi, Daniel, funebris dum tri semajnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Bongustan manĝaĵon mi ne manĝis, viando kaj vino ne venis en mian buŝon, kaj per oleo mi min ne ŝmiris, ĝis la fino de la tri semajnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'En la dudek-kvara tago de la unua monato mi estis sur la bordo de granda rivero, nome de Ĥidekel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'Kaj levinte miajn okulojn, mi ekvidis: jen staras unu viro, vestita per tolaj vestoj, kaj liaj lumboj estas zonitaj per pura oro el Ufaz.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Lia korpo estas kiel turkiso, lia vizaĝo aspektas kiel fulmo, liaj okuloj kiel fajraj flamoj, liaj brakoj kaj kruroj kiel brilanta kupro, kaj la voĉo de lia parolado estas kiel voĉo de amaso da homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Nur mi sola, Daniel, vidis tiun vizion; la homoj, kiuj estis kun mi, ne vidis la vizion; tamen granda timo falis sur ilin, kaj ili forkuris, por sin kaŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'Mi restis sola, kaj mi rigardis tiun grandan vizion; ne restis en mi forto, mia vizaĝaspekto ŝanĝiĝis terure, kaj mi ne povis rekolekti miajn fortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Kaj mi ekaŭdis la voĉon de liaj vortoj; kaj kiam mi ekaŭdis la voĉon de liaj vortoj, mi senkonscie falis vizaĝaltere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Sed jen mano ektuŝis min kaj levis min sur miajn genuojn kaj manplatojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Kaj li diris al mi: Ho Daniel, viro agrabla al Dio! atentu la vortojn, kiujn mi diros al vi, kaj stariĝu sur via loko, ĉar mi nun estas sendita al vi. Kiam li tion parolis al mi, mi staris tremante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Li diris al mi: Ne timu, Daniel, ĉar de la unua tago, kiam vi sincere penis kompreni kaj pentofari antaŭ via Dio, viaj vortoj estis aŭditaj; kaj mi venis laŭ via peto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Sed la protektanto de la Persa regno kontraŭstaris al mi dum dudek unu tagoj, kaj, ĝis Miĥael, unu el la plej ĉefaj protektantoj, venis kun helpo al mi, mi restis tie apud la reĝoj de Persujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Nun mi venis, por informi vin, kio estos kun via popolo en la estonta tempo, ĉar la vizio koncernas tempon estontan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Dum li parolis al mi tiujn vortojn, mi almetis mian vizaĝon al la tero kaj silentis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Sed jen iu, simila al homido, ektuŝis miajn lipojn, kaj mi malfermis mian buŝon, ekparolis kaj diris al tiu, kiu staris kontraŭ mi: Ho mia sinjoro, de ĉi tiu vizio kurbiĝis mia vizaĝo, kaj mi jam ne havas fortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Kaj kiel la sklavo de mia sinjoro povas paroli kun tia mia sinjoro, se mi jam ne havas forton kaj mi jam ne havas spiron?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Tiam denove ektuŝis min tiu bildo de homo kaj refortigis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'Kaj li diris: Ne timu, ho simpatia homo, paco estu al vi, kaj estu kuraĝa. Kaj dum li parolis al mi, mi kuraĝiĝis, kaj diris: Parolu, ho mia sinjoro, ĉar vi min refortigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Tiam li diris: Ĉu vi scias, por kio mi venis al vi? nun mi iras denove, por batali kontraŭ la protektanto de Persujo; sed kiam mi foriros, venos la protektanto de Grekujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Tamen mi sciigos al vi, kio estas notita en la vera skribo; kaj estas neniu, kiu subtenus min kontraŭ tiuj, krom Miĥael, via protektanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'En la unua jaro de Dario, la Medo, mi staris, por subteni kaj fortigi min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'Kaj nun mi sciigos al vi la veron: jen ankoraŭ tri reĝoj estos en Persujo; la kvara superos ĉiujn per sia riĉeco; kaj kiam li fariĝos forta per sia riĉeco, li ekscitos ĉiujn kontraŭ la regnon Grekan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Aperos reĝo potenca, kiu regos kun granda forto, kaj faros ĉion, kion li volos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Sed dum lia starado lia regno disrompiĝos kaj dividiĝos laŭ la kvar ventoj de la ĉielo, kaj ĝi transiros ne al liaj idoj, kaj ne kun tiu potenco, kun kiu li regis; lia regno estos disŝirita kaj transiros al homoj fremdaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Fortiĝos unu el liaj princoj, la reĝo suda, kaj fariĝos pli forta ol li, kaj regos; lia potenco estos granda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Sed post kelke da jaroj ili kuniĝos inter si; kaj la filino de la suda reĝo venos al la norda reĝo, por aranĝi la aferon inter ili; sed ŝi ne retenos la forton en sia mano, kaj ankaŭ li kun sia forto ne restos; ŝi kaj ŝiaj akompanantoj kaj ŝia infano kaj ŝia kelktempa fortiganto estos transdonitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Tamen el ŝia trunko aperos branĉo, venos kun militistaro, venos al la fortikaĵo de la norda reĝo, kaj venkos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Ankaŭ iliajn diojn, kun iliaj statuoj, kaj kun iliaj grandvaloraj vazoj arĝentaj kaj oraj, li forportos en Egiptujon, kaj por kelke da jaroj li restos malproksima de la norda reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Ĉi tiu iros al la regno de la suda reĝo, sed revenos en sian landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Poste liaj filoj sin armos kaj kolektos grandan militistaron; kaj unu iros rapide, disverŝiĝos kiel inundo, kaj denove faros militon ĝis lia fortikaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Tiam la suda reĝo indignos, eliros kaj militos kontraŭ li, kontraŭ la norda reĝo, kaj starigos grandan homomulton, kaj tiu homamaso estos transdonita en lian manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'Li forkondukos tiun homamason, kaj fieriĝos lia koro; sed kvankam li venkos multajn milojn, li tamen ne fariĝos pli forta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'La norda reĝo denove starigos homomulton, pli grandan ol la antaŭa, kaj post kelka tempo li eliros kun granda militistaro kaj kun granda riĉeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'En tiu tempo multaj stariĝos kontraŭ la suda reĝo, kaj malkvietaj filoj de via popolo leviĝos, por ke plenumiĝu la profetaĵo, sed ili falos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Kaj venos la norda reĝo, ŝutaranĝos remparon, kaj venkoprenos la fortikigitan urbon; kaj la forto de la sudo ne povos kontraŭstari, kaj ĝia plej bona militistaro ne havos forton, por rezisti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'Kaj ĉiu, kiu venos al li, faros tion, kion li postulos, neniu povos kontraŭstari al li; li stariĝos en la plej bela lando, kaj pereigos ĝin per sia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Kaj li intencos veni kun la potenco de sia tuta regno kaj kun siaj bravuloj, kaj li tion faros; kaj la urbo de virinoj estos donita al li por ekstermi; kaj ĝi ne povos kontraŭstari; sed ĝi ankaŭ ne fariĝos lia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Kaj li direktos sian vizaĝon al la insuloj kaj venkoprenos multajn; sed unu princo ĉesigos lian malhonoradon, ke li ne plu malhonoru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Tiam li denove turnos sin al la fortikaĵoj de sia lando; sed li falpuŝiĝos, falos, kaj oni lin jam ne trovos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Sur lia loko stariĝos tia, kiu sendos impostiston tra la tuta glora regno; sed post kelke da tagoj li pereos, kvankam ne per kolero kaj ne per batalo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Sur lia loko stariĝos homo malestimata, sur kiun oni ne metos la reĝan ornamon; sed li venos kun trankvileco, kaj ekposedos la regnon per flataĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'Kaj la dronigantaj taĉmentegoj estos dronigitaj kaj frakasitaj de li, kaj ankaŭ la princo, kun kiu estis farita la interligo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Kaj post la interamikiĝo li faros kontraŭ li malicaĵon, iros, kaj superfortos lin per malmulte da homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'En la pacajn kaj plej bonstatajn urbojn de la lando li venos, kaj faros tion, kion ne faris liaj patroj nek liaj prapatroj; la kaptaĵon, rabaĵon, kaj havaĵon li disĵetos; kaj li direktos siajn intencojn kontraŭ la fortikigitajn urbojn, sed nur ĝis certa tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Poste li ekscitos sian forton kaj sian koron kontraŭ la reĝon sudan kun grandega militistaro, kaj la suda reĝo eliros milite kun granda kaj tre forta militistaro; sed li ne eltenos, ĉar estos faritaj atencoj kontraŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Tiuj, kiuj manĝas ĉe lia tablo, pereigos lin, kaj lia armeo disverŝiĝos, kaj falos multe da mortigitoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Ambaŭ reĝoj havos en sia koro malbonajn intencojn, kaj ĉe la sama tablo ili parolos malveraĵon; sed ili ne sukcesos, ĉar la fino estas ankoraŭ prokrastita ĝis certa tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Li iros returne al sia lando kun granda havaĵo, kaj kun intencoj kontraŭ la sankta interligo; kaj li plenumos, kaj venos en sian landon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'En difinita tempo li denove iros suden; sed la lasta fojo ne estos tia, kiel la unua.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Ĉar venos kontraŭ lin ŝipoj de la Kitidoj, kaj li perdos la kuraĝon; kaj li denove fariĝos kolera kontraŭ la sankta interligo, kaj denove agos kaj interkonsentos kun la forlasintoj de la sankta interligo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'Helpantoj estos starigitaj de li; ili malsanktigos la fortodonan sanktejon, ĉesigos la ĉiutagajn oferojn, kaj faros abomenindan ruinigon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Tiujn, kiuj malbonagas kontraŭ la interligo, li allogos per flataĵoj. Sed la homoj, kiuj konas sian Dion, fariĝos kuraĝaj kaj komencos agi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'La klerigantoj de la popolo klerigos multajn, kvankam dum kelka tempo ili falados de glavo, fajro, mallibereco, kaj prirabado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Dum sia falado ili ricevos kelkan helpon, sed multaj aliĝos al ili hipokrite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Kelkaj el la klerigantoj falos por tio, ke ili refandiĝu, puriĝu, kaj blankiĝu ĝis la fina tempo; ĉar estas ankoraŭ tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'La reĝo farados, kion li volos, kaj li fieriĝos, kaj rigardos sin kiel pli altan ol ĉiu dio, kaj pri Dio de la dioj li parolos teruraĵojn, kaj li havos sukceson, ĝis pleniĝos la kolero; ĉar kio estas decidita, tio plenumiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Kaj pri la dioj de siaj patroj li ne pensos, li ne atentos ĉarmon de virinoj, nek ian dion, sed li tenos sin pli alte ol ĉio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'Nur la dion de fortikaĵoj sur sia loko li honoros, kaj tiun dion, kiun ne konis liaj patroj, li honoros per oro, arĝento, multekostaj ŝtonoj, kaj juveloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'Kaj li konstruos por la urboj fortikaĵojn sub la nomo de fremda dio; kiu akceptos ĉi tiun, al tiu li plimultigos la honorojn kaj donos potencon super multaj kaj rekompence disdonos teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'Fine ekbatalos kontraŭ li la suda reĝo, kaj ĵetos sin sur lin la norda reĝo kun ĉaroj, rajdistoj, kaj multe da ŝipoj, atakos la regionojn, inundos, kaj trairos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Kaj li venos en la plej belan landon, kaj multaj pereos; saviĝos kontraŭ lia mano nur jenaj: Edom, Moab, kaj la ĉefaj el la Amonidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'Kaj li etendos sian manon kontraŭ diversajn landojn; ankaŭ la lando Egipta ne saviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'Kaj li fariĝos mastro super la trezoroj de oro, arĝento, kaj ĉiuj grandvaloraĵoj de Egiptujo; Luboj kaj Etiopoj sekvos liajn paŝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Sed ektimigos lin famoj de oriento kaj de nordo, kaj li eliros kun granda furiozo, por pereigi kaj ekstermi multajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'Kaj li starigos sian belegan tendon inter la maro kaj la monto de la bela sanktejo; sed li venos al sia fino, kaj neniu helpos al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'En tiu tempo leviĝos Miĥael, la granda protektanto, kiu defendas la filojn de via popolo; kaj venos tempo malfacila, kia ne ekzistis de tiu tempo, kiam aperis homoj, ĝis la nuna tempo; sed saviĝos en tiu tempo el via popolo ĉiuj, kiuj troviĝos enskribitaj en la libro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Kaj multaj el tiuj, kiuj dormas en la tero, vekiĝos, unuj por vivo eterna, aliaj por eterna malhonoro kaj honto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Kaj la klerigantoj brilos, kiel la brilo de la ĉielo; kaj la virtigantoj de multaj, kiel steloj por ĉiam kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Kaj vi, ho Daniel, kaŝu la vortojn kaj sigelu la libron ĝis la fina tempo; multaj ĝin tralegos, kaj multiĝos la scio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Tiam mi, Daniel, ekrigardis, kaj jen staras du aliaj, unu sur unu bordo de la rivero kaj la dua sur la alia bordo de la rivero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Kaj li diris al la viro en la tolaj vestoj, kiu staris super la akvo de la rivero: Kiam estos la fino de la mirindaĵoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Kaj mi aŭskultis la viron en la tolaj vestoj, kiu staris super la akvo de la rivero; li levis sian dekstran manon kaj sian maldekstran manon al la ĉielo, kaj ĵuris per Tiu, kiu vivas eterne, ke tio estos post la paso de tempo kaj tempoj kaj duono de tempo; kaj kiam finiĝos la dissemiteco de la sankta popolo, tiam plenumiĝos ĉio ĉi tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Mi aŭdis, sed mi ne komprenis; kaj mi diris: Ho mia sinjoro, kio estos post tio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Kaj li respondis: Iru, Daniel, ĉar tio estas kaŝita kaj sigelita ĝis la fina tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Multaj estos purigitaj, blankigitaj, kaj elprovitaj; la malpiuloj faros malpiaĵojn, kaj ĉiuj malpiuloj ne komprenos; sed la klerigantoj komprenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Kaj de la tempo, kiam ĉesiĝos la ĉiutagaj oferoj kaj fariĝos abomeninda ruiniĝo, pasos mil ducent naŭdek tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Feliĉa estas tiu, kiu atendas kaj atingos la tempon de mil tricent tridek kvin tagoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Kaj vi, ho Daniel, foriru ĝis la fino; kaj ripozu, kaj vi stariĝos por via sorto en la fino de la tempoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Vorto de la Eternulo, kiu aperis al Hoŝea, filo de Beeri, en la tempo de Uzija, Jotan, Aĥaz, kaj Ĥizkija, reĝoj de Judujo, kaj en la tempo de Jerobeam, filo de Joaŝ, reĝo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Kiam la Eternulo komencis paroli al Hoŝea, la Eternulo diris al Hoŝea: Iru, prenu al vi edzinon malĉastulinon kaj naskigu infanojn malĉastajn, ĉar la lando malĉastiĝis for de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Kaj li iris, kaj prenis Gomeron, filinon de Diblaim; kaj ŝi gravediĝis kaj naskis al li filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Kaj la Eternulo diris al li: Donu al li la nomon Jizreel; ĉar baldaŭ Mi punos pro la sango de Jizreel la domon de Jehu, kaj Mi metos finon al la regno de la domo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'En tiu tempo Mi rompos la pafarkon de Izrael en la valo Jizreel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Kaj ŝi denove gravediĝis kaj naskis filinon; kaj Li diris al li: Donu al ŝi la nomon Lo-Ruĥama; ĉar Mi ne plu kompatos la domon de Izrael, sed postulos de ili pagon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Tamen la domon de Jehuda Mi kompatos, kaj Mi helpos al ili per la Eternulo, ilia Dio; Mi ne helpos al ili per pafarko, glavo, kaj batalo, nek per ĉevaloj kaj rajdantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Kiam ŝi demamigis Lo-Ruĥaman, ŝi gravediĝis kaj naskis filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Kaj Li diris: Donu al li la nomon Lo-Ami; ĉar vi ne estas Mia popolo, kaj Mi ne estos por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'Tamen la nombro de la Izraelidoj estos kiel la sablo ĉe la maro, ne mezurebla kaj ne kalkulebla. Kaj sur la sama loko, kie estis dirite al ili: Vi ne estas Mia popolo, oni diros al ili: Infanoj de la vivanta Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'Kolektiĝos kune la idoj de Jehuda kaj la idoj de Izrael, kaj faros al si unu ĉefon, kaj iros el la lando; ĉar granda estos la tago de Jizreel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Nomu viajn fratojn Mia popolo, kaj viajn fratinojn Kompatataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Havu juĝon kontraŭ via patrino, havu juĝon, ĉar ŝi ne estas Mia edzino, kaj Mi ne estas ŝia edzo; ŝi forigu la malĉastecon de sia vizaĝo kaj la adultemecon de siaj mamoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'por ke Mi ne senvestigu ŝin ĝis nudeco, kaj ne prezentu ŝin tia, kia ŝi estis en la tago de sia naskiĝo, ke Mi ne faru ŝin kiel dezerto, ne faru ŝin kiel tero senakva, kaj ne mortigu ŝin per soifo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Ankaŭ ŝiajn infanojn Mi ne kompatus, ĉar ili estas infanoj de malĉasto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'ĉar ilia patrino malĉastis, ilia naskintino malhonoris sin; ĉar ŝi diris: Mi sekvos miajn amistojn, kiuj donas al mi mian panon kaj mian akvon, miajn lanaĵojn kaj miajn linaĵojn, mian oleon kaj miajn drinkaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Pro tio Mi baros vian vojon per dornoj, Mi ĉirkaŭbaros ŝin, ke ŝi ne trovos siajn vojojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Ŝi postkuros siajn amistojn, sed ŝi ne kuratingos ilin; ŝi serĉos ilin, sed ne trovos; kaj ŝi diros: Mi iros returne al mia unua edzo, ĉar pli bone estis al mi tiam, ol nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Kaj ŝi ne sciis, ke Mi estis tiu, kiu donadis al ŝi panon kaj moston kaj oleon, Mi donis al ŝi multe da arĝento kaj oro, kiun ili uzis por Baal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Tial Mi prenos returne Mian panon kaj Mian moston iliatempe, Mi forprenos Mian lanaĵon kaj Mian linaĵon, per kiu ŝi kovris sian nudecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Kaj nun Mi malkaŝos ŝian hontindaĵon antaŭ la okuloj de ŝiaj amistoj, kaj neniu savos ŝin el Mia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Mi ĉesigos ĉian ŝian gajecon, ŝiajn festojn, monatkomencojn, kaj sabatojn, kaj ĉiujn ŝiajn solenajn kunvenojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Mi dezertigos ŝiajn vinbertrunkojn kaj ŝiajn figarbojn, pri kiuj ŝi diras: Tio estas donaco, kiun donis al mi miaj amistoj; Mi faros ilin arbaro, kaj la bestoj de la kampo ilin manĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Mi punos ŝin pro la tagoj de la Baaloj, al kiuj ŝi incensis, ornaminte sin per siaj ringoj kaj siaj ĉirkaŭkoloj, kaj sekvante siajn amistojn, dum Min ŝi forgesis, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Tial jen Mi allogos ŝin, kondukos ŝin en dezerton, kaj parolos al ŝi agrablajn vortojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'kaj Mi donos al ŝi ŝiajn vinberĝardenojn el tie, kaj la valon de malĝojo Mi faros pordo de espero; kaj tie ŝi kantos, kiel en la tagoj de sia juneco kaj kiel en la tempo de sia elirado el la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'En tiu tempo, diras la Eternulo, ŝi nomos Min: Mia edzo; ŝi ne plu nomos Min: Mia mastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Mi forigos de ŝia buŝo la nomojn de la Baaloj, kaj oni ne plu rememoros ilin laŭ ilia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'Kaj Mi faros por ili en tiu tempo interligon kun la bestoj de la kampo, kun la birdoj de la ĉielo, kaj kun la rampaĵoj de la tero; pafarkon, glavon, kaj militon Mi ekstermos el la lando, kaj Mi donos al ili la eblon dormi eksterdanĝere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'Mi fianĉiĝos kun vi por ĉiam, Mi fianĉiĝos kun vi en vero kaj justo, en favorkoreco kaj kompatemeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'Mi fianĉiĝos kun vi en fideleco, kaj vi ekkonos la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'En tiu tempo Mi favoros, diras la Eternulo, Mi favoros la ĉielon, kaj ĝi favoros la teron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'kaj la tero favoros la grenon, moston, kaj oleon, kaj ĉi tiuj favoros Jizreelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Mi faros ŝin al Mi fruktoporta sur la tero, kaj Mi kompatos la nekompatitinon; kaj al tiu, kiu estis ne Mia popolo, Mi diros: Vi estas Mia popolo; kaj ĝi diros: Vi estas mia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Kaj la Eternulo diris al mi plue: Iru, kaj komencu amaĵon kun virino, kiun amas ŝia edzo, sed kiu adultas, simile al tio, kiel la Eternulo amas la Izraelidojn, sed ili turnas sin al aliaj dioj kaj amas iliajn vinberkukojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Kaj mi akiris ŝin al mi per dek kvin arĝentaj moneroj kaj ĥomero kaj duono da hordeo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'Kaj mi diris al ŝi: Longan tempon restu ĉe mi; ne malĉastu, kaj fordonu vin al neniu viro; tiel same mi agos kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Ĉar dum longa tempo la Izraelidoj restos sen reĝo, sen estro, sen oferoj, sen statuo, sen efodo, kaj sen domaj dioj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'poste la Izraelidoj returnos sin, kaj serĉos la Eternulon, sian Dion, kaj Davidon, sian reĝon, kaj ili respektegos la Eternulon kaj Lian bonon en la fina tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Aŭskultu la vorton de la Eternulo, ho Izraelidoj; ĉar la Eternulo havas juĝan disputon kun la loĝantoj de la tero; ĉar sur la tero ne ekzistas vero, nek amo, nek konado de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Malbenado kaj trompado, mortigado, ŝtelado, kaj adultado tre disvastiĝis, kaj sangoverŝo sekvas sangoverŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Pro tio ekploros la tero, kaj malfeliĉo trafos ĉiujn ĝiajn loĝantojn kaj la bestojn de la kampo kaj la birdojn de la ĉielo; eĉ la fiŝoj de la maro malaperos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Sed neniu malpacu, neniu riproĉu; via popolo estas kiel insultantoj de pastro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Vi falos meze de la tago, kaj ankaŭ la profeto falos kun vi en la nokto; kaj Mi pereigos vian patrinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Mia popolo pereos pro tio, ke ĝi ne havas scion. Ĉar vi forpuŝis la scion, tial Mi vin forpuŝos, ke vi ne plu estu Mia pastro. Ĉar vi forgesis la instruon de via Dio, tial ankaŭ Mi forgesos viajn infanojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Ju pli ili multiĝas, des pli ili pekas kontraŭ Mi; ilian honoron Mi faros senhonoreco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Per la pekoj de Mia popolo ili sin nutras, kaj al ĝia malpieco strebas ilia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Kaj fariĝos al la popolo tiel same, kiel al la pastroj: Mi punos ĝin pro ĝia konduto, kaj Mi repagos al ĝi pro ĝiaj agoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'Ili manĝos kaj ne satiĝos, ili malĉastos kaj ne disvastiĝos; ĉar ili forlasis la Eternulon kaj ne atentas Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Malĉastado, vino, kaj mosto forprenas la prudenton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Mia popolo demandas sian lignon, kaj ĝia bastono donas al ĝi respondon; ĉar la spirito de malĉasteco erarigas ilin, kaj ili malĉastas kontraŭ sia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Sur la supro de montoj ili alportas oferojn, kaj sur montetoj ili incensas sub kverko, poplo, kaj terebintarbo, ĉar bona estas ilia ombro. Tial malĉastos viaj filinoj, kaj viaj bofilinoj adultos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Ĉu Mi povas ne puni viajn filinojn, se ili malĉastas, kaj viajn bofilinojn, se ili adultas, se ili apartiĝas kune kun la malĉastistinoj kaj alportas oferojn kune kun la publikaj virinoj, kaj la malklera popolo pereas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Se malĉastas vi, ho Izrael, tiam almenaŭ Jehuda ne kulpiĝu; ne iru en Gilgalon, ne iru en Bet-Avenon, kaj ne ĵuru: Kiel vivas la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Ĉar Izrael obstinas, kiel obstina bovino; ĉu nun la Eternulo povas paŝti ilin, kiel ŝafidon sur vasta paŝtejo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Efraim aliĝis al idoloj; lasu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Abomeninda fariĝis ilia drinkado; ili fordonis sin al malĉastado kaj malhonora amo; honto al iliaj protektantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'La vento forportos ilin per siaj flugiloj, kaj ili hontos pri siaj oferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Aŭskultu tion, ho pastroj, atentu, ho domo de Izrael, kaj prenu en viajn orelojn, ho reĝa domo; ĉar vin trafos juĝo pro tio, ke vi estis kaptilo en Micpa kaj etendita reto sur Tabor.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Per premado ili profundigis la pekojn; Mi punos ĉiujn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Mi konas Efraimon, kaj Izrael ne estas kaŝita antaŭ Mi: vi nun malĉastas, ho Efraim, kaj Izrael malpuriĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Iliaj agoj ne permesas al ili reveni al ilia Dio, ĉar spirito de malĉasteco estas en ili kaj la Eternulon ili ne konas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'La malmodesteco de Izrael parolas kontraŭ li antaŭ lia vizaĝo; tial Izrael kaj Efraim falos pro siaj malbonagoj; ankaŭ Jehuda falos kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Kun siaj ŝafoj kaj bovoj ili iros serĉi la Eternulon, sed ne trovos; Li foriĝis de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Ili perfidis al la Eternulo, kaj naskis fremdajn infanojn; tial ekstermos ilin la monato kune kun ilia havaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Blovu per korno en Gibea, per trumpeto en Rama; bruu en Bet-Aven, post vi, ho Benjamen!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Efraim fariĝos dezerto en la tago de la puno; inter la triboj de Izrael Mi avertis fidele.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'La princoj de Jehuda fariĝis similaj al forŝovantoj de limo; Mi elverŝos sur ilin Mian koleron kiel akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Efraim estas premata, frapita de la juĝo; ĉar li memvole sekvis homan ordonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Mi estos por Efraim kiel tineo, kiel putro por la domo de Jehuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Efraim vidis sian malsanon, kaj Jehuda sian vundon; tiam Efraim iris al Asirio, kaj sendis al reĝo, kiu venĝus pro li; sed li ne povas sanigi vin, ne forigos de vi la vundon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Ĉar Mi estas kiel leono por Efraim, kiel leonido por la domo de Jehuda; Mi, Mi disŝiros kaj foriros; Mi forportos, kaj neniu povos savi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Mi iros returne sur Mian lokon, ĝis ili konfesos sian kulpon kaj serĉos Mian vizaĝon; kiam ili suferos, ili Min serĉos, kaj diros:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Ni iru, ni revenu al la Eternulo; ĉar Li disŝiris, sed Li ankaŭ resanigos nin, Li frapis, kaj Li ankaŭ bandaĝos niajn vundojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Li revivigos nin post du tagoj; en la tria tago Li restarigos nin, kaj ni vivos antaŭ Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Kaj ni havos scion, kaj ni penos koni la Eternulon. Li eliros, kiel bela matenruĝo; Li venos al ni, kiel pluvo, kiel printempa pluvo, kiu malsekigas la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Kion Mi faru al vi, ho Efraim? Kion Mi faru al vi, ho Jehuda? Via pieco estas kiel matena nebulo, kaj kiel roso, kiu frue malaperas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Tial Mi hakas per la profetoj, Mi mortigas ilin per la vortoj el Mia buŝo; kaj justeco koncerne vin eliros kiel lumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Ĉar Mi deziras bonfaradon, sed ne oferon, kaj konadon de Dio Mi preferas ol bruloferojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Sed ili rompis la interligon, kiel Adam, kaj ili defalis de Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Gilead estas urbo de malbonaguloj, makulita de sango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Kiel bando da embuskantoj la anaro de la pastroj pereigas tiujn, kiuj iras al Ŝeĥem; abomenindaĵon ili faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'En la domo de Izrael Mi vidas teruraĵon: tie malĉastas Efraim, malpuriĝas Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Sed ankaŭ Jehuda havos rikolton, kiam Mi revenigos la forkaptitojn de Mia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Kiam Mi komencis kuraci Izraelon, malkaŝiĝis la malbonagoj de Efraim kaj la malboneco de Samario; ĉar ili agas mensoge, ŝtelistoj eniras, kaj bandoj rabas sur la strato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'Ili ne pensis en sia koro, ke Mi memoras ĉiujn iliajn malbonagojn; nun ĉirkaŭas ilin iliaj agoj kaj staras antaŭ Mia vizaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Per sia malboneco ili gajigas la reĝon kaj per siaj trompoj la princojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Ĉiuj ili adultas, kiel forno, forte hejtita de la bakisto, kiu ĉesas hejti nur de post la knedado de sia pasto ĝis ĝia fermentiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'Hodiaŭ estas festo de nia reĝo; kaj la princoj komencas fariĝi frenezaj de la vino, kaj li etendas sian manon kun la blasfemantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Ili armas sian koron per malico, kiel fornon, kaj kvankam la bakisto dormas dum la tuta nokto, ĝi tamen matene brulas kiel flamanta fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Ĉiuj ili ardas, kiel forno, kaj formanĝas siajn juĝistojn; ĉiuj iliaj reĝoj falis, kaj neniu el ili vokas al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Efraim miksis sin kun la popoloj, Efraim fariĝis kiel platkuko, bakita sen renversado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Fremduloj konsumis liajn fortojn, kaj li ne rimarkis; eĉ grizaj haroj lin kovris, kaj li tion ne scias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'La malmodesteco de Izrael atestas kontraŭ li, sed ili ne turnas sin al la Eternulo, sia Dio, kaj ne serĉas Lin malgraŭ ĉio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Efraim fariĝis kiel naiva, senprudenta kolombo: ili vokas la Egiptojn, ili iras en Asirion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Kiam ili iros, Mi ĵetos sur ilin Mian reton; kiel birdojn de la ĉielo Mi tiros ilin malsupren; Mi ilin punos, kiel estis predikate en iliaj kunvenoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Ve al ili, ke ili foriĝis de Mi; malfeliĉaj ili estas, ke ili defalis de Mi. Mi volas savi ilin, kaj ili parolas kontraŭ Mi mensogojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'Kaj ili ne vokas al Mi en sia koro, kiam ili ĝemas sur siaj litoj; pro pano kaj mosto ili kunvenas, sed de Mi ili foriĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Mi instruis ilin, fortigis ilian brakon, kaj ili pensas malbonon pri Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Ili returnas sin, sed ne al la Plejaltulo; ili fariĝis kiel malĝusta pafarko; falos de glavo iliaj estroj pro sia kolerema lango; tio estos moko kontraŭ ili en la lando Egipta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Metu trumpeton al via buŝo! Li flugas kiel aglo al la domo de la Eternulo, pro tio, ke ili agis kontraŭ Mia interligo kaj defalis de Mia instruo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Al Mi ili vokos: Ho mia Dio, ni, Izraelidoj, ekkonis Vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Izrael forpuŝis la bonon; malamiko lin persekutos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Ili starigis reĝojn, sed ne de Mi; ili starigis princojn, sed sen Mia scio; el sia arĝento kaj oro ili faris al si idolojn, por pereigi sin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Forpuŝita estas via bovido, ho Samario; ekflamis kontraŭ ili Mia kolero; kiel longe ankoraŭ ili ne povos puriĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Ĉar ĝi estas faritaĵo de Izrael; artisto ĝin faris, kaj ĝi ne estas dio; dispecetiĝos la bovido de Samario.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Ĉar ili semas venton, ili rikoltos ventegon; grenon li ne havos; la kreskantaĵo ne donos farunon; se ĝi eĉ donos, fremduloj ĝin formanĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Izrael estas formanĝata; nun ili fariĝis inter la popoloj kiel senvalora vazo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Ĉar ili iris en Asirion, kiel sovaĝa azeno solece vaganta; la Efraimidoj donis amajn donacojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Kvankam ili donis donacojn al la nacioj, Mi nun kolektus ilin, por ke ili iom ripozu de la ŝarĝo de la reĝo de la princoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Sed multe da altaroj konstruis Efraim, por peki; ili fariĝis por li altaroj pekigaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Mi skribis por li la multon de Miaj leĝoj; sed li rigardas ilin kiel fremdaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'La oferojn, donacatajn al Mi, ili buĉas nur pro viando, por ĝin manĝi; la Eternulo ne deziras ilin; nun Li rememoros iliajn malbonagojn kaj punos iliajn pekojn; ili revenos en Egiptujon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Izrael forgesis sian Kreinton, kaj konstruas palacojn; Jehuda konstruis multe da fortikigitaj urboj; sed Mi sendos fajron sur liajn urbojn, kaj ĝi ekstermos liajn palacojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Ne ĝoju, ho Izrael, ne estu gaja, kiel la popoloj, ĉar vi malĉaste foriĝis de via Dio, vi preferas proamaĵajn donacojn ol ĉiujn grenejojn plenajn de greno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Tial draŝejo kaj vinpremejo ne nutros ilin, la mosto mankos en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Ili ne loĝos en la lando de la Eternulo; Efraim revenos en Egiptujon, kaj en Asirio ili manĝos malpuraĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Ili ne verŝoferos al la Eternulo vinon, kaj ne estos agrablaj al Li; iliaj oferoj estos kiel pano de suferantoj: ĉiuj ĝiaj manĝantoj fariĝos malpuraj; ĉar ilia pano devas esti nur por ili mem, ĝi ne devas veni en la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Kion vi faros en la tago de solena kunveno kaj en la tago de festo de la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Ĉar vidu, ili forkuras de malfeliĉo; Egiptujo ilin kolektos, Memfis ilin enterigos; sur la loko, kie troviĝis iliaj amataj arĝentaĵoj, kreskos urtiko, dornoj estos en iliaj tendoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Venis la tempo de punvizito, venis la tagoj de repago; Izrael ekscios, ĉu malsaĝa estis la profeto, ĉu freneza estis la viro inspirita, parolante pri viaj multaj malbonagoj kaj pri la granda malboneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'La gardisto de Efraim estis antaŭe kun mia Dio; nun profeto metas kaptilojn sur ĉiuj liaj vojoj, kaj malamo estas en la domo de lia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Profunde ili malboniĝis, kiel en la tagoj de Gibea; Li rememoros iliajn malbonagojn, Li punos iliajn pekojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Kiel vinberojn en la dezerto Mi trovis Izraelon; kiel unuan frukton sur la figarbo en la komenco de ĝia matureco Mi vidis viajn patrojn; sed ili iris al Baal-Peor, kaj konsekris sin al la hontindaĵo, kaj fariĝis abomeninduloj, kiel ilia amato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'La honoro de Efraim forflugos kiel birdo; ne estos nasko, nek gravedeco, nek gravediĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Kaj se ili eĉ edukus siajn infanojn, Mi tamen seninfanigos ilin, ke ili ne havu homojn; ĉar ve al ili, kiam Mi forigos Min de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Efraim, kiel Mi vidas, estas plantita sur bela loko, kiel Tiro; tamen Efraim elirigos siajn infanojn al la mortiganto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Donu al ili, ho Eternulo, tion, kion Vi promesis doni; donu al ili ventron aborteman kaj mamojn sekiĝintajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Ilia tuta malboneco estas en Gilgal; tie Mi ekmalamis ilin; pro iliaj malbonaj agoj Mi elpelos ilin el Mia domo; Mi ne plu amos ilin; ĉiuj iliaj princoj estas defalintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Efraim estas batita; ilia radiko sekiĝis; ili ne plu donos fruktojn; eĉ se ili naskos, Mi mortigos la karan frukton de ilia ventro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Mia Dio ilin forpuŝos, ĉar ili ne aŭskultis Lin; kaj ili vagados inter la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Izrael estas vasta vinberujo, portas siajn fruktojn; sed ju pli multiĝis liaj fruktoj, des pli li multigis siajn altarojn; ju pli bona estis lia lando, des pli belajn statuojn li starigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Ilia koro estas dividita, tial nun ili estas kondamnitaj; Li rompos iliajn altarojn, frakasos iliajn statuojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Nun ili diras: Ni ne havas reĝon; ĉar ni ne timas la Eternulon, kion do povas fari por ni reĝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Ili parolas vanajn vortojn, ĵuras mensoge, kiam ili faras interligon; tial juĝo super ili aperos, kiel venena herbo sur la sulkoj de la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Pri la bovidoj de Bet-Aven ektremos la loĝantoj de Samario; ĉar ĝia popolo ekploros pri ĝi, kaj la pastraĉoj, kiuj ĝojis pri ĝi, ploros pri ĝia gloro, kiu foriĝis de ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'La bovido mem estas forportita en Asirion, kiel donaco al la reĝo- venĝonto; malhonoron ricevos Efraim, kaj Izrael hontos pro sia entrepreno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Malaperos Samario kun sia reĝo, kiel ŝaŭmo sur la supraĵo de akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Detruitaj estos la altaĵoj de Aven, la peko de Izrael; kardo kaj dornoj kreskos sur iliaj altaroj; ili diros al la montoj: Kovru nin; kaj al la montetoj: Falu sur nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Pli ol en la tempo de Gibea vi pekis, ho Izrael; tiam oni leviĝis, sed nun milito en Gibea ne atingas la malbonagulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Konforme al Mia intenco Mi punos ilin, kaj kolektiĝos kontraŭ ili popoloj, kiam ili estos punataj pro siaj du krimoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Efraim estas kiel bovido dresita, amanta draŝi. Mi metos jugon sur lian belan kolon, Mi rajdos sur Efraim, Jehuda plugos, Jakob erpos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Semu al vi justecon, tiam vi rikoltos amon; plugu al vi plugotaĵon; estas tempo, por turni sin al la Eternulo, ĝis Li venos kaj verŝos sur vin justecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Vi plugas malpiaĵon, vi rikoltas malbonagojn, vi manĝas frukton de mensogo; ĉar vi fidas vian vojon, la multon de viaj herooj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Sed fariĝos tumulto en via popolo, kaj ĉiuj viaj fortikaĵoj estos detruitaj, kiel Ŝalman detruis Bet-Arbelon dum la milito; mortigita estos la patrino kune kun siaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Tion faros al vi Bet-El pro via granda malpieco. Frue pereos, pereos la reĝo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Kiam Izrael estis junulo, Mi lin ekamis, kaj el Egiptujo Mi vokis Mian filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Sed nun oni vokas ilin, kaj ili sin deturnas; al la Baaloj ili oferas, kaj al idoloj ili incensas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Mi instruis al Efraim la iradon; Mi prenis ilin je la brako, kaj ili ne rimarkis, ke Mi ilin kuracas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Per ŝnuroj de homoj Mi tiris ilin, per ligiloj de amo; Mi estis por ili kiel levanto de la jugo, kaj Mi metis antaŭ ili la manĝaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Ili ne revenos en la landon Egiptan, sed Asirio estos ilia reĝo, ĉar ili ne volis penti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'Glavo falos sur liajn urbojn kaj ekstermos liajn idojn kaj formanĝos ilin pro iliaj entreprenoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Mia popolo rigidiĝis en la defalo de Mi; kaj kvankam oni ĝin vokas al la Plejaltulo, ĝi ne levas sin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Kiel Mi agu kun vi, ho Efraim? kiel Mi protektu vin, ho Izrael? Ĉu Mi faru al vi, kiel al Adma? ĉu Mi egaligu vin al Ceboim? Renversiĝis en Mi Mia koro, varmegiĝis Mia tuta kompato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Mi ne agos laŭ Mia flama kolero, Mi ne plu ekstermos Efraimon; ĉar Mi estas Dio, ne homo, Mi estas Sanktulo inter vi; Mi ne venos en furiozo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'La Eternulon ili sekvos, kiel kriantan leonon; kiam Li krios, tiam timigite venos la filoj de okcidente.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'Timigite kiel birdo ili venos el Egiptujo, kaj kiel kolombo el la lando Asiria; kaj Mi enloĝigos ilin en iliaj domoj, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, 'Kun mensogoj ĉirkaŭis Min Efraim, kaj kun falsaĵo la domo de Izrael; sed Jehuda ankoraŭ tenis sin je Dio kaj estis fidela al la Sanktulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Efraim paŝtas venton, postkuras la orientan venton; kun ĉiu tago li faras pli da mensogaĵoj kaj da idolaĵoj; li faras interligon kun Asirio, kaj portas oleon en Egiptujon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Sed ankaŭ kun Jehuda la Eternulo havas juĝon, kaj Li punos Jakobon laŭ lia konduto, laŭ liaj agoj Li repagos al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'Ankoraŭ en la ventro li retenis sian fraton, kaj viriĝinte li luktis kun Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Li luktis kun anĝelo kaj venkis, li tamen petegis lin kun ploro; en Bet-El Li nin trovos, kaj tie Li parolos kun ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'La Eternulo estas Dio Cebaot, Eternulo estas Lia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Returnu do vin al via Dio, konservu favorkorecon kaj justecon, kaj fidu ĉiam vian Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Kanaanido havas en sia mano falsan pesilon, li amas trompi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'kaj Efraim diras: Mi riĉiĝis, mi akiris al mi havaĵon, sed en ĉiuj miaj laboroj oni ne trovos ĉe mi malbonagon, per kiu mi estus pekinta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Mi, la Eternulo, estas via Dio de post la lando Egipta; Mi ankoraŭ denove loĝigos vin en tendoj, kiel en la tagoj de festo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'Mi parolis per la profetoj, Mi donis multe da vizioj, kaj per la profetoj Mi parolis alegorie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'En Gilead estis idoloj, sed ili fariĝis senvaloraĵo; en Gilgal oni oferbuĉis bovojn, sed iliaj altaroj fariĝis kiel ŝtonamasoj sur la sulko de la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Jakob forkuris sur la kampojn de Sirio, Izrael servis por edzino, kaj por edzino li devis gardi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Kaj per profeto la Eternulo elkondukis Izraelon el Egiptujo, kaj per profeto Li gardis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Forte kolerigis Lin Efraim, tial lia sango venos sur lin, kaj lia Sinjoro redonos al li pro liaj hontindaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Kiam Efraim parolis, oni timis; li altiĝis en Izrael. Sed li fariĝis kulpa per Baal, kaj mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Nun ili ankoraŭ pli pekas; ili faris al si el sia arĝento statuojn, idolojn laŭ sia kompreno, kiuj estas ja ĉiuj faritaĵo de forĝistoj; ili parolas pri ili: Tiuj, kiuj oferbuĉas homojn, povas kisi la bovidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Pro tio ili estos kiel matena nebulo, kiel roso, kiu frue malaperas, kiel grenventumaĵo, kiun la vento forblovas de la draŝejo, kaj kiel fumo el la kamentubo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Sed Mi, la Eternulo, estas via Dio de post la lando Egipta; kaj alian Dion krom Mi vi ne devas koni, kaj ne ekzistas alia Savanto krom Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Mi konis vin en la dezerto, en la lando de sekeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Kiam ili havis paŝtejon, ili satiĝis; kaj kiam ili satiĝis, tiam fieriĝis ilia koro, kaj tial ili forgesis Min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Tial Mi estos por ili kiel leono, kiel leopardo, kiu embuskas ĉe la vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Mi atakos ilin, kiel ursino, kiu perdis la infanojn, Mi disŝiros ilian ŝlositan koron, Mi manĝegos ilin tie, kiel leono; sovaĝaj bestoj ilin disŝiros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Vi pereigis vin, ho Izrael, ĉar via savo estas nur en Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Kie estas via reĝo? li savu vin en ĉiuj viaj urboj. Kie estas viaj juĝistoj, pri kiuj vi diris: Donu al mi reĝon kaj estrojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Mi donis al vi reĝon en Mia kolero, kaj Mi forprenos lin en Mia indigno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Kunpakitaj estas la malbonagoj de Efraim, lia peko estas konservita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Doloroj de naskantino atakos lin. Li estas infano sensaĝa; alie li ne starus longe en la pozicio de naskiĝantaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'El Ŝeol Mi savos ilin, de la morto Mi liberigos ilin; kie estas via veneno, ho morto? kie estas via pereigeco, ho Ŝeol? Sed la konsolo estas ankoraŭ kaŝita antaŭ Miaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Kvankam li estas fruktoriĉa inter la fratoj, venos tamen vento orienta, vento de la Eternulo, blovanta el la dezerto, kaj tiam elsekiĝos lia fonto, dezertiĝos lia devenejo; kaj li disrabos la trezorejon de ĉiuj grandvaloraĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, 'Samario suferos, ĉar ĝi ribelis kontraŭ sia Dio. De glavo ili falos; iliaj malgrandaj infanoj estos frakasitaj, iliaj gravedulinoj estos dishakitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Revenu, ho Izrael, al la Eternulo, via Dio; ĉar vi falis pro viaj malbonagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Prenu kun vi vortojn kaj revenu al la Eternulo; diru al Li: Pardonu ĉiun pekon kaj akceptu bonon; anstataŭ bovoj ni alportos ofere niajn lipojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Asirio ne savos nin; ni ne rajdos sur ĉevaloj, ni ne plu nomos nia dio la faritaĵon de niaj manoj; nur ĉe Vi la orfo trovas kompaton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Mi sanigos ilin de la defalo, Mi volonte ilin amos, ĉar pasis Mia kolero koncerne ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Mi estos por Izrael kiel roso; li ekfloros kiel rozo, li profundigos siajn radikojn kiel Lebanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Liaj branĉoj disvastiĝos, li estos bela kiel olivarbo, li bonodoros kiel Lebanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Revenos tiuj, kiuj sidis en lia ombro; ili reviviĝos kiel greno, ili floros kiel vinberbranĉo; li estos fama, kiel la vino de Lebanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Ho Efraim, per kio interesas Min plue la idoloj? Mi aŭskultos lin kaj gvidos lin; Mi estos kiel verda cipreso; ĉe Mi oni trovos viajn fruktojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Kiu estas saĝa, tiu komprenu ĉi tion; kiu estas prudenta, tiu sciu ĉi tion; ĉar ĝustaj estas la vojoj de la Eternulo, virtuloj iras sur ili, kaj malpiuloj falas sur ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Vorto de la Eternulo, kiu aperis al Joel, filo de Petuel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Aŭskultu ĉi tion, ho maljunuloj, kaj atentu, ho ĉiuj loĝantoj de la lando! Ĉu estis ĉi tio en via tempo, aŭ en la tempo de viaj patroj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Rakontu pri tio al viaj infanoj, kaj viaj infanoj al siaj infanoj, kaj iliaj infanoj al la sekvanta generacio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Kio restis de la raŭpoj, tion manĝis la akridoj; kio restis de la akridoj, tion manĝis la skaraboj; kaj kio restis de la skaraboj, tion manĝis la vermoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Vekiĝu, ho ebriuloj, kaj ploru, ĝemu vi, ĉiuj drinkantoj, pri la suko vinbera, kiu estas prenita for de via buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Ĉar venis sur mian landon nacio forta kaj nekalkulebla; ĝiaj dentoj estas dentoj de leono, kaj makzelojn de leonino ĝi havas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Ĝi dezertigis mian vinberujon, ĉirkaŭŝiris mian figarbon, tute senŝeligis ĝin kaj forĵetis; blankiĝis ĝiaj branĉoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Ĝemu, kiel junulino, kiu metis sur sin sakaĵon pro sia fianĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'For estas la farunoferoj kaj verŝoferoj el la domo de la Eternulo; funebras la pastroj, servistoj de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Dezertigita estas la kampo, funebras la tero; ĉar ekstermita estas la greno, elsekiĝis la mosto, velkis la olivoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Konsternitaj estas la plugistoj, plorĝemas la vinberkultivistoj, pro la tritiko kaj hordeo, pro la pereo de la rikolto sur la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Elsekiĝis la vinberbranĉo, velkis la figarbo; la granatarbo, la palmo, kaj la pomarbo, ĉiuj arboj de la kampo elsekiĝis; malaperis gajeco ĉe la homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Zonu vin kaj ploru, ho pastroj; ĝemegu, ho servistoj de la altaro; iru kaj kuŝu en sakaĵoj, ho servistoj de mia Dio; ĉar malaperis el la domo de via Dio la farunoferoj kaj verŝoferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Sanktigu faston, proklamu solenan kunvenon, kunvoku la maljunulojn kaj ĉiujn loĝantojn de la lando en la domon de la Eternulo, via Dio, kaj kriu al la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Ho ve, kia tago! Ĉar proksima estas la tago de la Eternulo; kiel katastrofo ĝi venos de la Plejpotenculo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Antaŭ niaj okuloj ja malaperis la manĝaĵo, el la domo de nia Dio la ĝojo kaj gajeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Forputris la grajnoj sub siaj terbuloj, malpleniĝis la grenejoj, detruitaj estas la garbejoj, ĉar la greno difektiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Ho, kiel ĝemas la brutoj, kiel suferas la bovaroj! ĉar ili ne havas paŝtaĵon; ankaŭ la ŝafaroj turmentiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Al Vi, ho Eternulo, mi vokas; ĉar fajro ekstermis la herbejojn de la stepo, kaj flamo bruldifektis ĉiujn arbojn de la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Eĉ la bestoj de la kampo sopiras al Vi; ĉar elsekiĝis la torentoj da akvo, kaj fajro ekstermis la herbejojn de la stepo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Blovu per korno en Cion, kaj kriu alarmon sur Mia sankta monto; ektremu ĉiuj loĝantoj de la lando; ĉar venas la tago de la Eternulo, ĝi estas jam proksima;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'tago de mallumo kaj senlumeco, tago de nuboj kaj nebulo; simile al la matena ĉielruĝo disvastiĝas sur la montoj popolo grandnombra kaj forta; tia neniam ekzistis ĝis nun, kaj ankaŭ post ĝi ne plu ekzistos tia, en iu ajn generacio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Antaŭ ĝi ekstermas fajro, kaj post ĝi bruligas flamo; antaŭ ĝi la lando estas kiel la Edena ĝardeno, kaj post ĝi absoluta dezerto; kaj neniu saviĝos de ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Ili aspektas kiel ĉevaloj, ili kuras kiel rajdantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Ili saltas sur la montoj, kiel bruantaj ĉaroj, kiel krakado de fajro, kiam ĝi ekstermas pajlon, kiel popolo potenca, pretiĝinta por batalo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Popoloj tremas antaŭ ĝi, ĉiuj vizaĝoj paliĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Kiel herooj ili kuras, kiel kuraĝaj batalistoj ili grimpas sur la muregon; ĉiu iras sian vojon, ne foreraras de sia vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'Unu alian ne puŝas, ĉiu iras en sia vico; sur la glavojn ili sin ĵetas, sed restas sendifektaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Ili trakuras la urbon, kuras sur la muregoj, eniras en la domojn, grimpas tra la fenestroj, kiel ŝtelisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Antaŭ ili skuiĝas la tero, tremas la ĉielo; la suno kaj la luno senlumiĝas, kaj la steloj perdas sian brilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Kaj la Eternulo ektondras per Sia voĉo antaŭ Sia armeo; ĉar Lia militistaro estas tre granda, kaj la plenumantoj de Lia vorto estas potencaj; ĉar granda kaj tre timinda estos la tago de la Eternulo; kiu povos ĝin elteni?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Sed eĉ nun ankoraŭ la Eternulo diras: Returnu vin al Mi per via tuta koro, kun fastado, plorado, kaj ĝemegado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'disŝiru vian koron, ne viajn vestojn, kaj returnu vin al la Eternulo, via Dio; ĉar Li estas favorkora kaj kompatema, longepacienca kaj indulgema, kaj Li bedaŭras malfeliĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Kiu scias? eble Li denove bedaŭros, eble Li restigos post Si benon, farunoferojn kaj verŝoferojn al la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Blovu per korno en Cion, sanktigu faston, proklamu solenan kunvenon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Kunvenigu la popolon, sanktigu la komunumon, invitu la maljunulojn, kolektu la malgrandajn infanojn kaj suĉinfanojn; fianĉo eliru el sia ĉambro, kaj fianĉino el sub sia baldakeno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Inter la portiko kaj la altaro ploru la pastroj, servistoj de la Eternulo, kaj ili diru: Indulgu, ho Eternulo, Vian popolon, kaj ne kovru per honto Vian heredaĵon, la nacioj ne moku ilin; por kio oni diru inter la popoloj: Kie estas ilia Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Tiam la Eternulo fariĝos fervora por Sia lando kaj indulgos Sian popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'Kaj la Eternulo respondos kaj diros al Sia popolo: Jen Mi sendas al vi grenon kaj moston kaj oleon, kaj vi satiĝu per ili; kaj Mi ne plu permesos al la nacioj malhonori vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Kaj la nordulon Mi malproksimigos de vi, kaj forpelos lin en landon senakvan kaj dezertan, lian antaŭan parton al la maro orienta, kaj lian malantaŭan parton al la maro okcidenta; kaj li putros kaj malbonodoros, ĉar li faris multe da malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Ne timu, ho tero, ĝoju kaj estu gaja, ĉar la Eternulo faros ion grandan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Ne timu, ho bestoj de la kampo, ĉar verdiĝos la paŝtejoj de la stepoj; la arboj portos siajn fruktojn, la figarbo kaj vinberujo donos sian riĉaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'Kaj vi, ho infanoj de Cion, ĝoju kaj estu gajaj pri la Eternulo, via Dio; ĉar Li donos al vi instruanton pri virteco, kaj Li sendos al vi pluvon, fruan kaj malfruan, kiel antaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'La grenejoj pleniĝos de greno, kaj la premejoj superpleniĝos de mosto kaj de oleo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'Kaj Mi rekompencos vin pro tiuj jaroj, kiam ĉion formanĝis la akridoj, skaraboj, vermoj, kaj raŭpoj, Mia granda armeo, kiun Mi sendis sur vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Kaj vi povos manĝi sate, kaj vi gloros la nomon de la Eternulo, via Dio, kiu agis kun vi mirinde; kaj Mia popolo neniam plu havos malhonoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'Kaj vi ekscios, ke Mi estas meze de Izrael, ke Mi, la Eternulo, estas via Dio, kaj alia ne ekzistas; kaj Mia popolo neniam plu havos malhonoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, 'Post tio Mi elverŝos Mian spiriton sur ĉiun karnon; viaj filoj kaj viaj filinoj profetos, viaj maljunuloj havos sonĝojn, viaj junuloj havos viziojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, 'Eĉ sur la sklavojn kaj sur la sklavinojn Mi en tiu tempo elverŝos Mian spiriton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, 'Kaj Mi donos miraklajn signojn en la ĉielo kaj sur la tero: sangon, fajron, kaj kolonojn da fumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, 'La suno fariĝos malluma, kaj la luno fariĝos sanga, antaŭ ol venos la granda kaj timinda tago de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, 'Kaj ĉiu, kiu vokos la nomon de la Eternulo, saviĝos; ĉar sur la monto Cion kaj en Jerusalem estos savo, kiel diris la Eternulo, ankaŭ por la restintoj, kiujn la Eternulo alvokos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Ĉar jen en tiuj tagoj kaj en tiu tempo, kiam Mi revenigos la forkaptitojn de Judujo kaj de Jerusalem,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'Mi kolektos ĉiujn naciojn kaj venigos ilin en la valon de Jehoŝafat; kaj tie Mi faros super ili juĝon pro Mia popolo kaj Mia heredaĵo Izrael, kiun ili disĵetis inter la naciojn, dividinte Mian landon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'kaj pro tio, ke ili lotis pri Mia popolo, fordonis knabon pro manĝaĵo kaj knabinon vendis pro vino, kaj drinkis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Kaj kion vi volas de Mi, ho Tiro, Cidon, kaj ĉiuj distriktoj Filiŝtaj? ĉu vi volas repagi al Mi? kaj se vi volos repagi al Mi, Mi facile kaj baldaŭ turnos vian repagon sur vian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Mian arĝenton kaj Mian oron vi prenis, kaj Miajn plej bonajn valoraĵojn vi transportis en viajn templojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'kaj la filojn de Judujo kaj la filojn de Jerusalem vi vendis al la filoj de la Grekoj, por malproksimigi ilin de iliaj limoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'sed jen Mi vekos ilin el tiu loko, kien vi vendis ilin, kaj vian agon Mi turnos sur vian kapon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'kaj Mi vendos viajn filojn kaj viajn filinojn en la manojn de la Judoj, kaj ĉi tiuj vendos ilin al la Ŝebaanoj, al popolo malproksima; ĉar la Eternulo tion diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Proklamu tion inter la nacioj; pretiĝu al milito, veku la kuraĝulojn; ĉiuj militistoj leviĝu kaj eliru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Forĝu el viaj plugiloj glavojn, kaj el viaj rikoltiloj lancojn; la malfortulo diru: Mi estas forta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Rapidu kaj venu, ĉiuj nacioj de ĉiuj flankoj, kaj kolektiĝu; tien alkonduku, ho Eternulo, Viajn fortulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'La popoloj leviĝu kaj iru en la valon de Jehoŝafat; ĉar tie Mi sidiĝos, por juĝi ĉiujn naciojn de ĉiuj flankoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Svingu la rikoltilon, ĉar la rikoltaĵo estas matura; venu malsupren, ĉar la premejoj estas plenaj kaj la tinoj tropleniĝis; ĉar granda estas ilia malboneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Amasoj post amasoj kolektiĝas en la valo de la juĝo, ĉar alproksimiĝas la tago de la Eternulo en la valo de la juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'La suno kaj la luno senlumiĝos, kaj la steloj perdos sian brilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'Kaj la Eternulo ektondros el Cion kaj aŭdigos Sian voĉon el Jerusalem; ektremos la ĉielo kaj la tero; sed la Eternulo estos rifuĝejo por Sia popolo, kaj fortikaĵo por la idoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'Kaj vi ekscios, ke Mi, la Eternulo, estas via Dio, kiu loĝas en Cion, sur Mia sankta monto; kaj Jerusalem estos sanktejo, kaj fremduloj ne plu iros tra ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'En tiu tago la montoj elgutigos dolĉan sukon, el la montetoj fluos lakto, kaj ĉiuj torentoj de Judujo estos plenaj de akvo; kaj fonto eliros el la domo de la Eternulo kaj liveros akvon al la valo Ŝitima.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'Egiptujo fariĝos dezerto, kaj Edom fariĝos senviva dezerto, pro tio, ke ili premis la idojn de Jehuda kaj verŝis senkulpan sangon en sia lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'Sed Judujo estos loĝata eterne, kaj Jerusalem en ĉiuj generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'Kaj Mi venĝos pro ilia sango, kiu ne estis venĝita de Mi; kaj la Eternulo loĝados en Cion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Vortoj de Amos, paŝtisto el Tekoa, kiujn li laŭvizie eldiris pri Izrael en la tempo de Uzija, reĝo de Judujo, kaj en la tempo de Jerobeam, filo de Joaŝ, reĝo de Izrael, du jarojn antaŭ la tertremo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Li diris: La Eternulo ektondros el Cion kaj aŭdigos Sian voĉon el Jerusalem; kaj ekfunebros la paŝtejoj de la paŝtistoj, kaj sekiĝos la supro de Karmel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Tiele diras la Eternulo: Pro tri krimoj de Damasko kaj pro kvar Mi ne indulgos ĝin, pro tio, ke ili draŝis Gileadon per fera draŝilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Mi sendos fajron sur la domon de Ĥazael, kaj ĝi ekstermos la palacojn de Ben-Hadad.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'Mi disrompos la riglilojn de Damasko, Mi ekstermos la loĝantojn de la valo Aven kaj la tenanton de sceptro el la domo Edena, kaj la popolo Siria estos forkondukita en Kiron, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Tiele diras la Eternulo: Pro tri krimoj de Gaza kaj pro kvar Mi ne indulgos ĝin, pro tio, ke ili tute forkondukis la kaptitojn, por transdoni ilin al Edom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'Mi sendos fajron sur la muregon de Gaza, kaj ĝi ekstermos ĝiajn palacojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'Mi ekstermos la loĝantojn de Aŝdod kaj la tenanton de sceptro el Aŝkelon, Mi direktos Mian manon kontraŭ Ekronon, kaj pereos la restintoj de la Filiŝtoj, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Tiele diras la Eternulo: Pro tri krimoj de Tiro kaj pro kvar Mi ne indulgos ĝin, pro tio, ke ili transdonis en plenan malliberecon al Edom kaj ne memoris la fratan interligon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'Mi sendos fajron sur la muregon de Tiro, kaj ĝi ekstermos ĝiajn palacojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Tiele diras la Eternulo: Pro tri krimoj de Edom kaj pro kvar Mi ne indulgos lin, pro tio, ke li persekutis kun glavo sian fraton, ke li sufokis en si la kompaton, ke li senĉese furiozas en sia kolero kaj konservas sian furiozon por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'Mi sendos fajron sur Temanon, kaj ĝi ekstermos la palacojn de Bocra.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Tiele diras la Eternulo: Pro tri krimoj de la Amonidoj kaj pro kvar Mi ne indulgos ilin, pro tio, ke ili dishakis gravedulinojn en Gilead, por plivastigi siajn limojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'Mi ekbruligos fajron sur la murego de Raba, kaj ĝi ekstermos ĝiajn palacojn, kun bruo en la tago de batalo, kun ventego en la tago de malkvieteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'Kaj ilia reĝo iros en forkaptitecon, li, kaj kune ankaŭ liaj eminentuloj, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Tiele diras la Eternulo: Pro tri krimoj de Moab kaj pro kvar Mi ne indulgos lin, pro tio, ke li forbruligis la ostojn de la reĝo de Edom ĝis cindreco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'Mi sendos fajron sur Moabon, kaj ĝi ekstermos la palacojn de Keriot; kaj Moab mortos en tumulto, ĉe bruo kaj sonado de trumpeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'Mi ekstermos juĝiston el meze de li, kaj ĉiujn liajn eminentulojn Mi mortigos kune kun li, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Tiele diras la Eternulo: Pro tri krimoj de Jehuda kaj pro kvar Mi ne indulgos lin, pro tio, ke ili forpuŝis la instruon de la Eternulo, ne observis Liajn leĝojn, kaj permesis sin delogiĝi per la mensogaĵoj, kiujn sekvis iliaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'Mi sendos fajron sur Judujon, kaj ĝi ekstermos la palacojn de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Tiele diras la Eternulo: Pro tri krimoj de Izrael kaj pro kvar Mi ne indulgos lin, pro tio, ke ili vendas virtulon pro arĝento kaj malriĉulon pro paro da ŝuoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'Ili premas la kapon de senhavuloj en la polvon de la tero, ili baras la vojon de humiluloj; filo kaj patro iras al unu knabino, por malhonori Mian sanktan nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'Sur garantidonitaj vestoj ili kuŝas apud ĉiu altaro, kaj vinon de punitoj ili trinkas en la domo de sia dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Kaj Mi ekstermis antaŭ ili la Amoridon, kiu estis alta kiel cedro kaj forta kiel kverko; Mi ekstermis liajn fruktojn supre kaj liajn radikojn malsupre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Mi elkondukis vin el la lando Egipta kaj kondukis vin en la dezerto dum kvardek jaroj, por ke vi ekposedu la landon de la Amorido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'El viaj filoj Mi faris profetojn kaj el viaj junuloj konsekritojn; ĉu ne estas tiel, ho filoj de Izrael? diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Sed vi trinkigis al la konsekritoj vinon, kaj al la profetoj vi ordonis: Ne profetu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Jen Mi krakigos sub vi, kiel krakas veturilo, plenigita de garboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'Eĉ lertulo ne povos forkuri, fortulo ne povos ion fari per sia forto, kaj heroo ne povos savi sian vivon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'la arkpafistoj ne povos kontraŭstari, rapidpiedulo ne saviĝos, kaj rajdanto ne savos sian vivon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'kaj la plej kuraĝa el la herooj forkuros nuda en tiu tago, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Aŭskultu ĉi tiun vorton, kiun la Eternulo eldiris pri vi, ho Izraelidoj, pri la tuta gento, kiun Mi elkondukis el la lando Egipta:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'nur vin Mi distingis el ĉiuj gentoj de la tero, tial Mi punos vin pro ĉiuj viaj malbonagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Ĉu iras du kune, se ili ne interkonsentis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Ĉu leono krias en la arbaro, se ĝi ne havas disŝirotaĵon? ĉu leonido aŭdigas sian voĉon el sia kaverno, se ĝi nenion kaptis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Ĉu birdo falas en kaptilon sur la tero, se ne ekzistas birdokaptisto? ĉu kaptilo leviĝas de la tero, se nenio kaptiĝis per ĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Ĉu oni blovas per korno en urbo, kaj la popolo ne ektimas? ĉu okazas malfeliĉo en urbo, se tion ne faris la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'La Sinjoro, la Eternulo, faras nenion, ne malkaŝinte Sian sekreton al Siaj servantoj, la profetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Kiam leono ekkriis, kiu ne ektimos? kiam la Sinjoro, la Eternulo, parolis, kiu tiam ne profetos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Aŭdigu en la palacoj de Aŝdod kaj en la palacoj de la lando Egipta, kaj diru: Kolektiĝu sur la montoj de Samario, kaj rigardu, kia granda tumulto estas en ĝi kaj kia granda rabado estas farata meze de ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'Ili ne povoscias agi juste, diras la Eternulo; trezoroj, akiritaj per rabado kaj perfortado, estas en iliaj palacoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Tial tiele diras la Sinjoro, la Eternulo: Malamiko aperos kaj ĉirkaŭos la landon, kaj li deŝiros de vi vian forton, kaj viaj palacoj estos prirabitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Tiele diras la Eternulo: Kiel paŝtisto savas el la buŝo de leono du krurojn aŭ parton de orelo, tiel saviĝos la Izraelidoj, kiuj sidos en Samario sur la rando de lito kaj en Damasko sur kuŝejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Aŭskultu, kaj atestu kontraŭ la domo de Jakob, diras la Sinjoro, la Eternulo, Dio Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Ĉar en la tago, kiam Mi punos Izraelon pro liaj krimoj, Mi punos ankaŭ la altarojn en Bet-El, kaj dehakitaj estos la kornoj de la altaro kaj falos sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Kaj Mi frapos la vintran domon kune kun la somera domo; kaj malaperos la domoj eburaj, kaj multe da domoj malaperos, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Aŭskultu ĉi tiun vorton, vi grasaj bovinoj, kiuj estas sur la monto de Samario, kiuj turmentas senhavulojn, premas malriĉulojn, kaj kiuj diras al siaj mastroj: Venu, ni drinku.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'La Sinjoro, la Eternulo, ĵuris per Sia sankteco, ke jen venos sur vin tagoj, kiam oni forportos vin per hokoj kaj viajn idojn per fiŝhokoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Kaj tra breĉoj vi eliros, ĉiu aparte, kaj estos ĵetitaj sur Harmonon, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Iru en Bet-Elon, por peki, en Gilgalon, por multe krimi; alportu viajn oferojn ĉiumatene kaj vian dekonaĵon en ĉiu tria tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'Incensu laŭdoferon el fermentaĵo, kriu pri memvolaj oferoj, aŭdigu pri ili; ĉar tion vi amas, ho Izraelidoj, diras la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'Tial Mi donis al vi purecon de la dentoj en ĉiuj viaj urboj kaj mankon de pano en ĉiuj viaj lokoj; vi tamen ne revenis al Mi, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Mi ankaŭ rifuzis al vi la pluvon, kiam estis ankoraŭ tri monatoj antaŭ la rikolto; Mi donis pluvon super unu urbo, kaj super alia Mi ne donis pluvon; unu kampo estis pripluvata, kaj alia, ne pripluvita, elsekiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'Kaj du, tri urboj iris al unu urbo, pro trinki akvon, kaj ne povis trinki sufiĉe; vi tamen ne revenis al Mi, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Mi frapis vin per brulsekiĝo kaj velkiĝo de la greno; viajn multajn ĝardenojn, vinberĝardenojn, figarbojn, kaj olivarbojn formanĝis raŭpoj; vi tamen ne revenis al Mi, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Mi sendis sur vin peston sur la vojo al Egiptujo, Mi mortigis per glavo viajn junulojn kaj forkondukis viajn ĉevalojn, kaj Mi levis la malbonodoron de via tendaro en viajn nazotruojn; vi tamen ne revenis al Mi, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Mi faris inter vi renverson, kiel Dio renversis Sodomon kaj Gomoran, kaj vi fariĝis kiel brulanta ŝtipo, savita el brulo; vi tamen ne revenis al Mi, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Tial tiele Mi agos kun vi plue, ho Izrael; kaj ĉar Mi tiele agos kun vi, tial pretigu vin renkonte al via Dio, ho Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Ĉar Li estas Tiu, kiu faras montojn, kreas venton, diras al la homo, kion ĉi tiu intencas; Li faras la ĉielruĝon kaj la nebulon; Li iras sur la altaĵoj de la tero; Lia nomo estas Eternulo, Dio Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Aŭskultu ĉi tiun vorton, per kiu mi plorkantas pri vi, ho domo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Falis kaj ne releviĝos la virgulino de Izrael; ŝi estas ĵetita sur la teron, kaj neniu ŝin restarigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Ĉar tiele diras la Sinjoro, la Eternulo: La urbo, kiu elirigas milon, restos nur kun cento, kaj tiu, kiu elirigas centon, restos nur kun deko en la domo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Ĉar tiele diras la Eternulo al la domo de Izrael: Turnu vin al Mi, kaj tiam vi vivos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Ne turnu vin al Bet-El, ne iru en Gilgalon, ne migru al Beer-Ŝeba; ĉar Gilgal estos elpatrujigita kaj Bet-El fariĝos senvalora.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Turnu vin al la Eternulo, kaj vivu, por ke la domo de Jozef ne ekflamu kiel fajro, kiu ekstermos, kaj neniu estingos en Bet-El.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'La juĝon vi faras vermuto, kaj la veron vi ĵetas sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Li kreis la Plejadojn kaj Orionon; Li faras el la mallumo matenon, kaj el la tago Li faras malluman nokton; Li vokas la akvon de la maro kaj verŝas ĝin sur la teron; Lia nomo estas Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Li sendas malfeliĉon sur fortulon, kaj malfeliĉo trafas urbon fortikigitan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Sed ili malamas tiun, kiu admonas ilin en la pordego, kaj ili abomenas tiun, kiu parolas honestaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Tial pro tio, ke vi premas senhavulon kaj forprenas de li la panon per grandaj impostoj, vi konstruos domojn el hakitaj ŝtonoj, sed vi ne loĝos en ili; vi plantos ĉarmajn vinberĝardenojn, sed vi ne trinkos ilian vinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Ĉar Mi scias, kiel multaj estas viaj krimoj kaj kiel gravaj estas viaj pekoj: vi premas virtulon, vi prenas subaĉeton, vi forpuŝas malriĉulojn en la pordego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Tial la saĝulo silentas en ĉi tiu tempo, ĉar ĝi estas tempo malbona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Serĉu bonon, ne malbonon, por ke vi vivu; tiam la Eternulo, Dio Cebaot, estos kun vi, kiel vi diras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Malamu la malbonon, amu la bonon, kaj starigu en la pordego justecon; eble la Eternulo, Dio Cebaot, indulgos la restintojn de Jozef.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Tial tiele diras la Eternulo, Dio Cebaot, la Sinjoro: Sur ĉiuj placoj estos plorado, sur ĉiuj stratoj oni dirados: Ho ve, ho ve! kaj oni vokos la plugiston, por plori, kaj la sciantojn de funebraj kantoj, por plorkanti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'Kaj en ĉiuj vinberĝardenoj estos plorado, kiam Mi trairos meze de vi, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Ve al tiuj, kiuj deziras vidi la tagon de la Eternulo! por kio vi ĝin deziras? la tago de la Eternulo estas malluma, ne luma.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Tiel same, kiel se iu forkuras de leono kaj lin kaptas urso, aŭ li venis hejmen kaj apogis sian manon al muro kaj lin pikas serpento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Malluma estos ja la tago de la Eternulo, ne luma; malluma kaj sen ia brilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Mi malamas, Mi abomenas viajn festojn, kaj Mi ne flaras la oferojn de viaj solenaj tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Kiam vi alportas al Mi bruloferojn kaj viajn farunoferojn, Mi ne akceptas ilin, kaj viajn grasajn dankoferojn Mi ne rigardas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Forigu de Mi la bruon de viaj kantoj, la sonadon de viaj psalteroj Mi ne volas aŭskulti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Sed justeco fluu kiel akvo, kaj vero kiel potenca torento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Ĉu buĉoferojn kaj farunoferojn vi alportadis al Mi en la dezerto dum kvardek jaroj, ho domo de Izrael?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Vi portis la tabernaklon de via Moleĥ, la kolonon de via idolo, la stelon de via dio, kiun vi faris al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Tial Mi elpatrujigos vin trans Damaskon, diras la Eternulo, kies nomo estas Dio Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Ve al la senzorguloj en Cion, kaj al tiuj, kiuj fidas la monton de Samario, al la eminentuloj de la unuauloj inter la nacioj, al kiuj sin turnas la domo de Izrael!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Iru al Kalne, kaj rigardu; de tie iru en la grandan Ĥamat, poste iru al Gat de la Filiŝtoj: ĉu ili estas pli bonaj ol tiuj regnoj, ĉu iliaj limoj estas pli vastaj ol viaj limoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Tiuj, kiu pensas, ke la tago de malfeliĉo estas malproksima, kaj tenas sin proksime de la seĝo de maljusteco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'kiuj kuŝas sur eburaj litoj kaj dorlotas sin sur sia kuŝejo, manĝas la plej bonajn ŝafojn el la ŝafaro kaj bovidojn el la nutrejo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'kiuj tintas sur psalteroj, pensante, ke ili estas muzikistoj egalaj al David;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'kiuj trinkas vinon el grandaj kalikoj, ŝmiras sin per la plej bonaj oleaĵoj, kaj ne zorgas pri la mizero de Jozef:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'ili tial nun estos la unuaj, kiuj iros en forkaptitecon, kaj la ĝojkriado de la dorlotiĝantoj finiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'La Sinjoro, la Eternulo, ĵuris per Si mem, diras la Eternulo, Dio Cebaot: Mi abomenas la fierecon de Jakob, kaj liajn palacojn Mi malamas; Mi transdonos la urbon kun ĉio, kion ĝi enhavas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'Kaj se dek homoj restos en unu domo, ili ankaŭ mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'Kaj prenos ilin ilia amiko aŭ kadavrobruliganto, por elporti la ostojn el la domo, kaj li diros al tiu, kiu estas ĉe la domo: Ĉu estas ankoraŭ iu ĉe vi? Kaj ĉi tiu respondos: Neniu plu. Kaj tiu diros: Silentu, oni ne devas elparoli la nomon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Ĉar jen la Eternulo donas ordonon frapi la grandajn domojn per fendoj kaj la malgrandajn domojn per breĉoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Ĉu kuras ĉevaloj sur roko? ĉu oni povas plugi ĝin per bovoj? Vi tamen faris la juĝon veneno, kaj la frukton de la vero vi faris vermuto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'Vi ĝojas pro senvaloraĵoj; vi diras: Ĉu ne per nia forto ni akiris al ni potencon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Jen, diras la Eternulo, Dio Cebaot, Mi levos kontraŭ vin, ho domo de Izrael, nacion, kiu premos vin de Ĥamat ĝis la torento de la stepo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Tian vizion donis al mi la Sinjoro, la Eternulo: jen Li kreis akridojn en la komenco de kreskado de la postfalĉaĵo; la postfalĉaĵo aperis post la falĉado por la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'Kiam ili finis la manĝadon de la herbo sur la tero, mi diris: Ho Sinjoro, ho Eternulo, volu pardoni! Kiu restarigos Jakobon? li estas ja malgranda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Tiam la Eternulo bedaŭris tion: Tio ne estos, diris la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Tian vizion donis al mi la Sinjoro, la Eternulo: jen la Sinjoro, la Eternulo, proklamis juĝon per fajro, ke ĝi ekstermu la grandan abismon kaj ekstermu la kampojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Kaj mi diris: Ho Sinjoro, ho Eternulo, volu haltigi! Kiu restarigos Jakobon? li estas ja malgranda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'La Eternulo bedaŭris ankaŭ tion: Tio ne estos, diris la Sinjoro, la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Li donis al mi tian vizion: jen la Sinjoro staris sur murego vertikala, kaj vertikalon Li tenis en Sia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Kaj la Eternulo diris al mi: Kion vi vidas, Amos? Mi respondis: Vertikalon. Kaj la Sinjoro diris: Jen Mi metos vertikalon meze de Mia popolo Izrael; Mi ne plu indulgos ĝin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'kaj dezertiĝos la altaĵoj de Isaak, kaj la sanktejoj de Izrael estos ruinigitaj; kaj Mi levos Min kun glavo kontraŭ la domon de Jerobeam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Amacja, pastro el Bet-El, sendis al Jerobeam, reĝo de Izrael, por diri: Amos faras kontraŭ vi ribelon meze de la domo de Izrael; la lando ne povas toleri ĉiujn liajn vortojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'ĉar tiele diras Amos: Jerobeam mortos de glavo, kaj Izrael estos forkondukita el sia lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Kaj Amacja diris al Amos: Ho viziisto, iru kaj forkuru en la landon de Jehuda, tie nutru vin, kaj tie profetu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'sed en Bet-El ne plu profetu, ĉar ĝi estas sanktejo de la reĝo kaj domo de la regno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Amos respondis kaj diris al Amacja: Mi ne estas profeto, nek filo de profeto, mi estas nur paŝtisto, kaj mi kultivas sikomorojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'sed la Eternulo prenis min de la ŝafaro, kaj la Eternulo diris al mi: Iru kaj profetu al Mia popolo Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Kaj nun aŭskultu la vorton de la Eternulo: Vi diras: Ne profetu pri Izrael, kaj ne prediku pri la domo de Isaak;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'tial tiele diras la Eternulo: Via edzino malĉastos en la urbo, viaj filoj kaj viaj filinoj falos de glavo, via tero estos dividita per la ŝnuro, kaj vi mortos sur tero malpura; kaj Izrael estos forkondukita el sia lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Tian vizion donis al mi la Sinjoro, la Eternulo: mi vidis korbon kun maturaj fruktoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Kaj Li diris: Kion vi vidas, Amos? Mi respondis: Korbon kun maturaj fruktoj. Tiam la Eternulo diris al mi: Venis la fino por Mia popolo Izrael; Mi ne plu indulgos ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'La kantoj de la palaco fariĝos lamentoj en tiu tago, diras la Sinjoro, la Eternulo; estos multe da kadavroj; sur ĉiu loko oni ĵetos ilin silente.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Aŭskultu ĉi tion, vi, kiuj penas engluti la malriĉulojn kaj pereigi la humilulojn de la tero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'kaj kiuj diras: Kiam pasos la monatkomenco, ke ni povu vendadi grenon? kaj la sabato, ke ni povu malfermi la grenejon? Ni malgrandigos la mezuron, ni pligrandigos la prezon, kaj ni trompos per falsa pesilo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'ni aĉetos senhavulojn per mono kaj malriĉulon per paro da ŝuoj, kaj grenventumaĵon ni vendos kun la greno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'La Eternulo ĵuris per la gloro de Jakob: Neniam Mi forgesos ĉiujn iliajn farojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Ĉu pro tio ne ektremos la tero, ne ekploros ĉiuj ĝiaj loĝantoj? Ĝi tuta ekskuiĝos kiel lago, ĝi leviĝos kaj malleviĝos kiel la Rivero de Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'En tiu tago, diras la Sinjoro, la Eternulo, Mi subirigos la sunon en tagmezo, kaj Mi mallumigos la teron meze de luma tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Mi aliformigos viajn festojn en funebron kaj ĉiujn viajn kantojn en lamentojn; Mi metos sakaĵon sur ĉiujn lumbojn kaj kalvon sur ĉiun kapon; Mi aperigos ĉe ili funebron, kiel pri sola filo, kaj ilia fino estos tago de maldolĉeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Jen venos tagoj, diras la Sinjoro, la Eternulo, kaj Mi sendos malsaton en la landon, ne malsaton pri pano kaj ne soifon pri akvo, sed soifon por aŭskultado de la vortoj de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Kaj ili vagados de maro ĝis maro, kaj de nordo ĝis oriento ili migrados, por serĉi la vorton de la Eternulo, sed ili ne trovos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'En tiu tago senfortiĝos de soifo la belaj junulinoj kaj la junuloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'kiuj nun ĵuras per la peko de Samario, kaj diras: Kiel vivas via dio, ho Dan! kiel floras la vojo al Beer-Ŝeba! ili falos, kaj ne plu releviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Mi vidis la Eternulon, kiu staris super la altaro; kaj Li diris: Frapu la kapitelon, ke la fostoj ekskuiĝu kaj la pecoj falu sur la kapojn de ĉiuj; kaj ilian naskitaron Mi mortigos per glavo, neniu el ili forkuros, neniu el ili saviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Eĉ se ili enfosus sin en Ŝeolon, eĉ de tie Mia mano ilin prenos; eĉ se ili suprenirus en la ĉielon, Mi de tie depuŝos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'Se ili kaŝus sin sur la supro de Karmel, Mi tie elserĉos kaj prenos ilin; se ili kaŝiĝus for de Miaj okuloj sur la fundo de la maro, eĉ tie Mi ordonos al la serpento, ke ĝi piku ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'Se ili iros en forkaptitecon antaŭ siaj malamikoj, ankaŭ tie Mi ordonos al la glavo mortigi ilin. Mi direktos sur ilin Miajn okulojn por malfeliĉo, ne por bono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'La Sinjoro, la Eternulo Cebaot, ektuŝas landon, kaj ĝi tiam fandiĝas, kaj ĉiuj loĝantoj ploras; ĝi tuta ekskuiĝas kiel lago, malleviĝas kiel la Rivero de Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'Li konstruis Sian loĝejon en la ĉielo, kaj Sian firmamenton Li fundamentis sur la tero; Li vokas la akvon de la maro kaj verŝas ĝin sur la teron; Lia nomo estas Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Ĉu vi ne estas por Mi kiel la Etiopoj, ho Izraelidoj? diras la Eternulo; ĉu Mi ne elkondukis Izraelon el la lando Egipta, la Filiŝtojn el Kaftor, kaj la Sirianojn el Kir?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Jen la okuloj de la Sinjoro, la Eternulo, estas direktitaj sur la pekan regnon, kaj Mi ekstermos ĝin de sur la tero; tamen ne tute Mi ekstermos la domon de Jakob, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Jen Mi ordonos, kaj disĵetigos la domon de Izrael inter ĉiujn naciojn, kiel oni disĵetas per kribrilo, kaj eĉ unu grajno ne falos sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'De glavo mortos ĉiuj pekuloj de Mia popolo, kiuj diras: Malfeliĉo ne alproksimiĝos al ni kaj ne trafos nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'En tiu tempo Mi restarigos la falintan tabernaklon de David, Mi reŝtopos ĝiajn breĉojn, Mi restarigos la detruitaĵon, kaj Mi rekonstruos ĝin, kiel en la tempo antikva,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'por ke ili ekposedu la restaĵon de Edom kaj ankaŭ ĉiujn naciojn, inter kiuj estos proklamata Mia nomo, diras la Eternulo, kiu tion faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Jen venos tagoj, diras la Eternulo, kiam la pluganto renkontiĝos kun la rikoltanto, la vinberpremanto kun la semanto; kaj la montoj elgutigos dolĉan sukon, kaj ĉiuj montetoj fariĝos fruktoportaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Kaj Mi revenigos la forkaptitojn de Mia popolo Izrael, ili rekonstruos la ruinigitajn urbojn, enloĝiĝos, plantos vinberĝardenojn kaj trinkos ilian vinon, aranĝos ĝardenojn kaj manĝos iliajn fruktojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Kaj Mi replantos ilin sur ilia tero, kaj ili ne plu estos elŝirataj el sia tero, kiun Mi donis al ili, diras la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Vizio de Obadja. Tiele diras la Sinjoro, la Eternulo, pri Edom: Diron ni aŭdis de la Eternulo, kaj kuriero estas sendita al la nacioj: Leviĝu, ni iru milite kontraŭ lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Vidu, Mi faris vin malgranda inter la nacioj; vi estas tre malestimata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'La fiereco de via koro delogis vin; loĝante en la fendegoj de rokoj, sur via alta sidejo, vi diras en via koro: Kiu depuŝos min sur la teron?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Sed se vi eĉ leviĝus tiel alte, kiel aglo, aŭ se vi aranĝus vian neston inter la steloj, eĉ de tie Mi ĵetos vin malsupren, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Ĉu ŝtelistoj venis al vi, aŭ noktaj rabistoj? kiamaniere vi estas tiel ruinigita? ili ŝtelus nur tiom, kiom sufiĉus por ili. Se vinberkolektantoj venus al vi, ili restigus ja forgesitajn berojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Kiel forte Esav estas priserĉita kaj liaj kaŝejoj estas traesploritaj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Al la limo vin puŝis ĉiuj viaj interliganoj, trompis kaj perfortis vin viaj amikoj; la manĝantoj de via pano metis sub vin kaptilon, kiun vi eĉ ne rimarkis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'En tiu tempo, diras la Eternulo, Mi pereigos ja la saĝulojn ĉe Edom kaj la prudenton sur la monto de Esav.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'Ektimos viaj kuraĝuloj, ho Teman, por ke ĉiuj sur la monto de Esav estu ekstermitaj per mortigo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Pro tio, ke vi premis vian fraton Jakob, kovros vin honto, kaj vi estos ekstermita por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'En la tempo, kiam vi staris apude, kiam fremduloj kondukis lian militistaron en kaptitecon kaj aligentuloj eniris en liajn pordegojn kaj lotis pri Jerusalem, vi ankaŭ estis kiel unu el ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Vi devus ne rigardi la malfeliĉan tagon de via frato, la tagon de lia forpuŝiteco, kaj vi devus ne ĝoji pri la idoj de Jehuda en la tago de ilia pereo, nek fanfaroni en la tago de ilia mizero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Vi devus ne eniri en la pordegon de Mia popolo en la tago de ilia malfeliĉo, vi devus ne rigardi ilian suferadon en la tago de ilia malfeliĉo, nek tuŝi ilian havaĵon en la tago de ilia malfeliĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Vi devus ne stari ĉe la vojdisiĝo, por ekstermi iliajn forsaviĝintojn, nek transdoni iliajn restintojn en la tago de malfeliĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Ĉar proksima estas la tago de la Eternulo kontraŭ ĉiuj nacioj. Kiel vi agis, tiel oni agos kun vi; kion vi meritas, tio venos sur vian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Ĉar kiel vi trinkis sur Mia sankta monto, tiel trinkos ĉiam ĉiuj nacioj; ili trinkos, trinkos ĝisfunde, ĝis ili fariĝos kiel tute ne ekzistintaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Sed sur la monto Cion estos saviĝo, kaj ĝi estos sankta; kaj la domo de Jakob ekposedos tiujn, kiuj ilin posedis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'La domo de Jakob estos fajro, la domo de Jozef estos flamo; sed la domo de Esav estos pajlo, oni ekbruligos ĝin kaj ekstermos ĝin, kaj neniu restos el la domo de Esav; ĉar la Eternulo tion diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'Kaj la sudanoj ekposedos la monton de Esav, kaj la loĝantoj de la malaltaĵo la Filiŝtojn; ili ekposedos la kampojn de Efraim kaj la kampojn de Samario; kaj Benjamen posedos Gileadon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Kaj tiu multo da forkondukitaj Izraelidoj en la lando Kanaana ĝis Carfat kaj la forkondukitaj el Jerusalem en Sefarad ekposedos la urbojn sudajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'Kaj venos savantoj sur la monton Cion, por juĝi la monton de Esav. Kaj la regado apartenos al la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Aperis vorto de la Eternulo al Jona, filo de Amitaj, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Leviĝu, iru en la grandan urbon Nineve, kaj prediku kontraŭ ĝi; ĉar iliaj malbonagoj leviĝis antaŭ Min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Sed Jona leviĝis, por forkuri de antaŭ la Eternulo en Tarŝiŝon; li iris en Jafon, trovis ŝipon, forirontan al Tarŝiŝ, pagis pro la vojaĝo, kaj eniris en ĝin, por veturi kun ili al Tarŝiŝ, for de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Sed la Eternulo sendis grandan venton sur la maron, kaj sur la maro fariĝis granda ventego, kaj oni pensis, ke la ŝipo pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'La ŝipanoj ektimis kaj komencis voki ĉiu al sia dio; kaj la objektojn, kiuj troviĝis en la ŝipo, oni ĵetis en la maron, por malpligrandigi la pezon. Sed Jona iris malsupren, en la internon de la ŝipo, kuŝiĝis, kaj endormiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Kaj aliris al li la ŝipestro, kaj diris al li: Kial vi dormas? leviĝu, kaj voku al via Dio; eble Dio rememoros pri ni, kaj ni ne pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Kaj oni diris unu al alia: Ni lotu, por ke ni eksciu, pro kiu trafis nin ĉi tiu malfeliĉo. Ili lotis, kaj la loto trafis Jonan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Tiam ili diris al li: Vi, pro kiu nin trafis ĉi tiu malfeliĉo, diru al ni, per kio vi vin okupas? de kie vi venis? kie estas via lando? kaj el kiu popolo vi estas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Kaj li respondis al ili: Mi estas Hebreo: mi respektas la Eternulon, Dion de la ĉielo, kiu kreis la maron kaj la sekteron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Tiam tiuj homoj ektimis per granda timo, kaj diris al li: Kion vi faris? Ĉar tiuj homoj eksciis, ke li forkuris de antaŭ la Eternulo, kiel li mem diris al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Kaj ili diris al li: Kion ni faru kun vi, por ke la maro kvietiĝu por ni? ĉar la maro fariĝis ĉiam pli kaj pli malkvieta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Li respondis al ili: Prenu min, kaj ĵetu min en la maron; tiam la maro kvietiĝos por vi; ĉar mi scias, ke pro mi trafis vin ĉi tiu granda ventego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'La homoj forte ekremis, por reveni sur la sekteron; sed ili nenion povis fari, ĉar la maro fariĝadis ĉiam pli kaj pli malkvieta kontraŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Tiam ili ekvokis al la Eternulo, kaj diris: Ni petas Vin, ho Eternulo, ne do lasu nin perei pro la animo de ĉi tiu homo, kaj ne metu sur nin la sangon de senkulpulo; ĉar Vi, ho Eternulo, povas fari ĉion, kion Vi volas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Kaj ili prenis Jonan kaj ĵetis lin en la maron; tiam la maro ĉesis koleri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Tiam tiuj homoj eksentis grandan timon antaŭ la Eternulo; kaj ili buĉis oferon al la Eternulo kaj faris sanktajn promesojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, 'Kaj la Eternulo pretigis grandan fiŝon, ke ĝi englutu Jonan; kaj Jona restis en la interno de la fiŝo dum tri tagoj kaj tri noktoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Kaj Jona ekpreĝis al la Eternulo, sia Dio, el la interno de la fiŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'Kaj li diris: Kiam mi suferis, mi vokis al la Eternulo, Kaj Li respondis al mi; El la ventro de Ŝeol mi kriis, Kaj Vi aŭskultis mian voĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'Vi ĵetis min en la profundegon, en la internon de la maro, Kaj fluego min ĉirkaŭis; Ĉiuj Viaj ondegoj kaj ondoj iris super min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Kaj mi pensis: Mi estas forpuŝita de antaŭ Viaj okuloj; Tamen mi rigardos ankoraŭ Vian sanktan templon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Ĉirkaŭis min akvo ĝis la animo; Abismo min ĉirkaŭis; Junko kovris mian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Mi falis malsupren ĝis la fundamento de la montoj; La tero baris min por ĉiam per siaj rigliloj; Sed Vi, ho Eternulo, mia Dio, elirigis mian vivon el la pereo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Kiam mia animo senfortiĝis en mi, mi rememoris la Eternulon; Kaj mia preĝo alvenis al Vi en Vian sanktan templon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Tiuj, kiuj servas al vantaĵoj, Senigas sin je favorkoreco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Sed mi kun danka voĉo alportos al Vi oferon; Kion mi promesis, tion mi plenumos; Savo estas ĉe la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Kaj la Eternulo ordonis al la fiŝo, kaj ĝi elvomis Jonan sur la sekteron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Kaj duafoje aperis al Jona vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Leviĝu, iru en la grandan urbon Nineve, kaj prediku al ĝi la predikon, kiun Mi diros al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Tiam Jona leviĝis kaj iris en Nineven, konforme al la vorto de la Eternulo. Nineve estis granda urbo ĉe Dio; ĝi havis la grandecon de tri tagoj da irado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Kiam Jona komencis la trairadon de la urbo kaj trairis unu tagon, li vokis, kaj diris: Post kvardek tagoj Nineve pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'La loĝantoj de Nineve ekkredis je Dio, proklamis faston, kaj metis sur sin sakaĵon, de la grandaj ĝis la malgrandaj inter ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Kiam tion aŭdis la reĝo de Nineve, li leviĝis de sia trono, demetis de si sian reĝan veston, kovris sin per sakaĵo, kaj sidiĝis sur cindro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Kaj li ordonis proklami en Nineve en la nomo de la reĝo kaj de liaj altranguloj jenon: La homoj kaj la brutoj, la bovoj kaj la ŝafoj, gustumu nenion, ili ne paŝtiĝu kaj ne trinku akvon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'kaj la homoj kaj la brutoj kovru sin per sakaĵo, kaj voku forte al Dio, kaj ĉiu deturnu sin de sia malbona vojo kaj de la perfortaĵoj de siaj manoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'eble Dio bedaŭros, kaj forlasos Sian flaman koleron, kaj ni ne pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'Kiam Dio vidis iliajn farojn, ke ili deturnis sin de sia malbona vojo, Dio bedaŭris la malbonon, kiun Li minacis fari al ili, kaj Li tion ne faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Tio tre forte ĉagrenis Jonan, kaj li ekkoleris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Kaj li ekpreĝis al la Eternulo, kaj diris: Ho Eternulo, tion mi ja diris, kiam mi estis ankoraŭ en mia lando; kaj tial mi preferis forkuri en Tarŝiŝon, ĉar mi sciis, ke Vi estas Dio indulgema kaj kompatema, longepacienca kaj tre favorkora, kaj bedaŭras malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Nun, ho Eternulo, volu forpreni de mi mian animon; ĉar pli bone por mi estas morti, ol vivi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'La Eternulo diris: Ĉu vi havas grandan ĉagrenon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Jona eliris el la urbo, sidiĝis oriente de la urbo, faris al si tie laŭbon, kaj sidiĝis sub ĝi en la ombro, ĝis li vidos, kio estos kun la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Dume Dio, la Eternulo, pretigis hederon, kaj ĝi elkreskis super lian kapon, por ke li havu ombron super sia kapo kaj liberiĝu el sia suferado. Kaj Jona forte ekĝojis pro la hedero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Sed kiam leviĝis la matenruĝo de la sekvanta tago, Dio aperigis vermon, kiu difektis la hederon, kaj ĝi forvelkis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Kaj kiam ekbrilis la suno, Dio aperigis bruligan orientan venton, kaj la suno turmentis la kapon de Jona tiel, ke li senfortiĝis kaj petis por si morton; li diris: Pli bone por mi estas morti, ol vivi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Tiam Dio diris al Jona: Ĉu vi havas grandan ĉagrenon pro la hedero? Li respondis: Mi havas grandan ĉagrenon, eĉ ĝis deziro al morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'La Eternulo tiam diris: Vi domaĝas la hederon, pri kiu vi ne laboris kaj kiun vi ne edukis, kiu dum unu nokto elkreskis kaj dum unu nokto pereis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'kaj ĉu Mi povus ne domaĝi Nineven, la grandan urbon, en kiu troviĝas pli ol cent dudek mil homoj, ne povantaj distingi inter sia dekstra mano kaj sia maldekstra, kaj krom tio multe da brutoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Vorto de la Eternulo, kiu aperis al Miĥa, la Moreŝetano, en la tempo de Jotam, Aĥaz, kaj Ĥizkija, reĝoj de Judujo, kaj kiun li viziis pri Samario kaj Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Aŭskultu, ĉiuj popoloj, atentu, ho tero, kaj ĉio, kio estas sur ĝi! La Sinjoro, la Eternulo, estu atestanto kontraŭ vi, la Sinjoro el Sia sankta templo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Ĉar jen la Eternulo eliras el Sia loko, iras kaj paŝas sur la altaĵoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'Kaj fandiĝas la montoj sub Li, kaj la valoj disfendiĝas, kiel vakso antaŭ fajro, kiel akvo, falanta de krutaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Ĉio ĉi tio estas pro la krimo de Jakob kaj pro la pekoj de la domo de Izrael. Kiu krimigis Jakobon? ĉu ne Samario? Kiu aranĝis la altaĵojn de Judujo? ĉu ne Jerusalem?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Tial Mi faros Samarion ŝtonamaso sur la kampo, por plantado de vinberoj; Mi disĵetos ĝiajn ŝtonojn en la valon kaj nudigos ĝiajn fundamentojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Ĉiuj ĝiaj idoloj estos disbatitaj, ĉiuj ĝiaj promalĉastaj donacoj estos forbruligitaj per fajro, kaj ĉiujn ĝiajn statuojn Mi ruinigos; ĉar per promalĉastaj donacoj ĝi ilin aranĝis, kaj promalĉastaj donacoj ili fariĝos denove.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Pri tio mi ploras kaj ĝemas, iras senŝue kaj nude; mi krias plende, kiel la ŝakaloj, kaj estas malgaja, kiel la strutoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Ĉar senespera estas ĝia plago, ĝi venis ĝis Judujo, atingis ĝis la pordego de mia popolo, ĝis Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Ne diru tion en Gat, ne ploru laŭte; en Bet-Leafra rulu vin en cindro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Foriru, ho loĝantino de Ŝafir, en nudeco kaj honto; ne eliros la loĝantino de Caanan; la plorado en Bet-Ecel ne permesos al vi tie halti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Afliktiĝas pri sia bono la loĝantino de Marot; ĉar malfeliĉo venis de la Eternulo al la pordego de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Jungu al la ĉaro kurĉevalojn, ho loĝantino de Laĥiŝ; vi estas la komenco de pekoj de la filino de Cion, ĉar ĉe vi oni trovis la krimojn de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Tial vi sendos donacojn en Moreŝet-Gaton; sed la domoj de Aĥzib trompos la reĝojn de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Mi alkondukos al vi ankoraŭ la posedonton, ho loĝantino de Mareŝa; ĝis Adulam venos la gloro de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Detondu viajn harojn kaj razu vin pro viaj amataj filoj; larĝigu vian kalvon kiel aglo, ĉar ili estos forkaptitaj for de vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Ve al tiuj, kiuj meditas pri pekoj kaj intencas malbonagojn sur sia kuŝejo, por plenumi ilin matene, kiam ilia mano havas forton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Ili ekdeziras kampojn kaj rabas ilin, domojn kaj forprenas ilin; ili premas homon kaj lian domon, viron kaj lian posedaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Tial tiele diras la Eternulo: Jen Mi entreprenas kontraŭ tiu gento tian malbonon, de kiu vi ne liberigos vian kolon kaj ne iros kun levita kapo; ĉar tio estos tempo malfacila.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'En tiu tempo oni parolos pri vi parabolon, kaj oni prikantos vin per plorkanto, dirante: Ni estas tute ruinigitaj; la posedaĵo de mia popolo transiris al alia; kiamaniere povas reveni al ni niaj kampoj, se ili jam estas disdividitaj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Tial oni ne mezuros por vi per ŝnuro terpecon lote en la komunumo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, 'Ne prediku, ho predikantoj; oni ne devas prediki al tiuj, kiuj ne volas eviti malhonoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Ho, la tiel nomata domo de Jakob! ĉu malgrandiĝis la spirito de la Eternulo? ĉu tiaj estas Liaj agoj? Ĉu ne estas bonfaraj Miaj vortoj por tiu, kiu kondutas ĝuste?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Sed Mia popolo leviĝis kiel malamiko; vi rabas la supran kaj la malsupran vestojn de la trankvilaj preterirantoj, kvazaŭ ili revenus de batalo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'La virinojn de Mia popolo vi elpelas el iliaj amataj loĝejoj; de iliaj junaj infanoj vi forprenas por ĉiam Mian ornamon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Leviĝu kaj foriru, ĉar ĉi tie vi ne havos ripozon; pro sia malpureco la lando estos kruele ruinigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Se iu falsanimulo elpensus mensogon, kaj dirus: Mi predikos al vi pri vino kaj ebriigaĵo, li estus ĝusta predikanto por ĉi tiu popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Tamen Mi kolektos vin tutan, ho Jakob, Mi kolektos la restaĵon de Izrael, Mi kunigos ilin kiel ŝafojn en ŝafejo; kiel grego en gregejo ili ekbruos de multhomeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Murrompanto iros antaŭ ili; ili trarompos la baron, trapasos la pordegon, kaj eliros el ĝi; ilia reĝo iros antaŭ ili, kaj la Eternulo estos ilia antaŭgvidanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Mi diris: Aŭskultu, ho ĉefoj de Jakob kaj estroj de la domo de Izrael! Vi devas ja scii la juron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'tamen vi malamas la bonon, amas la malbonon; vi deŝiras de ili ilian haŭton kaj la karnon de iliaj ostoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'Kaj kiam ili manĝas la karnon de mia popolo, deŝiras de ili ilian haŭton, rompas kaj dispecigas iliajn ostojn kvazaŭ por poto kaj la karnon kvazaŭ por kaldrono:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'tiam ili krios al la Eternulo; sed Li ne respondos al ili, Li kaŝos antaŭ ili Sian vizaĝon en tiu tempo, ĉar ili faris siajn malbonajn agojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Tiele diras la Eternulo pri la profetoj, kiu erarigas mian popolon, kiuj mordas per siaj dentoj kaj predikas pacon, kaj kontraŭ tiu, kiu ne donas ion en ilian buŝon, ili predikas militon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Tial estos ĉe vi nokto, sed ne vizioj, mallumo, sed ne antaŭdiroj; subiros la suno super la profetoj, kaj mallumiĝos super ili la tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'Hontos tiuj viziistoj, mokindaj fariĝos la antaŭdiristoj, kaj ili ĉiuj fermos sian buŝon; ĉar ili ne havas respondon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Sed mi estas plena de forto de la spirito de la Eternulo, de praveco kaj kuraĝo, por montri al Jakob lian krimon kaj al Izrael lian pekon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Aŭskultu ĉi tion, ho ĉefoj de la domo de Jakob kaj estroj de la domo de Izrael, kiuj abomenas juron kaj kurbigas ĉion rektan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'kiuj konstruas Cionon per sango kaj Jerusalemon per maljustaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Ĝiaj ĉefoj juĝas pro subaĉeto, ĝiaj pastroj instruas pro pago, kaj ĝiaj profetoj antaŭdiras pro mono; tamen ili apogas sin sur la Eternulo, kaj diras: La Eternulo estas ja meze de ni, ne trafos nin malfeliĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Tial pro vi Cion estos plugita kiel kampo, Jerusalem fariĝos ruinaĵo, kaj la monto de la templo fariĝos arbara altaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Sed iam en la tempo estonta la monto de la domo de la Eternulo staros kiel ĉefo inter la montoj, kaj ĝi estos pli alta ol ĉiuj altaĵoj; kaj fluos al ĝi popoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'Kaj iros multaj nacioj, kaj diros: Venu, ni iru supren sur la monton de la Eternulo kaj en la domon de Dio de Jakob, por ke Li instruu nin pri Siaj vojoj kaj ke ni iru laŭ Lia irejo; ĉar el Cion eliros la instruo, kaj la vorto de la Eternulo el Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Kaj Li juĝos inter multe da popoloj, kaj Li decidos pri potencaj nacioj en landoj malproksimaj; kaj ili forĝos el siaj glavoj plugilojn kaj el siaj lancoj rikoltilojn; ne levos nacio glavon kontraŭ nacion, kaj oni ne plu lernos militon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Sed ĉiu sidos sub sia vinberujo kaj sub sia figarbo, kaj neniu timigos; ĉar la buŝo de la Eternulo Cebaot tion diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Ĉiuj popoloj iros ĉiu en la nomo de sia dio, sed ni irados en la nomo de la Eternulo, nia Dio, ĉiam kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'En tiu tago, diras la Eternulo, Mi kolektos la lamulojn, kunvenigos la dispelitojn, kaj tiujn, kiujn Mi suferigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Kaj la lamulojn Mi faros restantaro, kaj la suferintojn potenca nacio, kaj la Eternulo reĝos super ili sur la monto Cion de nun kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'Kaj vi, ho turo de la grego, fortikaĵo de la filino de Cion, al vi venos, revenos la antaŭa reĝado, la regno de la filino de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Kial vi nun ploras tiel laŭte? Ĉu vi ne havas reĝon? ĉu pereis viaj konsilistoj, ke vin atakis doloroj kiel naskantinon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Suferu, kaj havu dolorojn, ho filino de Cion, kiel naskantino; ĉar nun vi eliros el la urbo kaj loĝos sur la kampo kaj venos ĝis Babel; tie vi estos savata; tie la Eternulo liberigos vin el la mano de viaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Nun kolektiĝis kontraŭ vi multe da nacioj, kiuj diras: Ĝi malsanktiĝu, kun ĝuo ni rigardu Cionon!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Sed ili ne scias la pensojn de la Eternulo, ili ne komprenas Lian intencon, ke Li kolektis ilin kiel garbojn en la draŝejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Leviĝu kaj draŝu, ho filino de Cion, ĉar vian kornon Mi faros fera, viajn hufojn Mi faros kupraj, kaj vi dispremos multe da popoloj, vi konsekros al la Eternulo ilian akiritaĵon, kaj ilian havaĵon al la Sinjoro de la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Nun armu vin, ho batalistino! oni sieĝos nin; per vergo oni frapos la vangon de la juĝisto de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Kaj vi, ho Bet-Leĥem Efrata, kiu estas malgranda inter la milejoj de Judujo, el vi eliros al Mi tiu, kiu devas esti reganto en Izrael kaj kies deveno estas de tempo tre antikva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Li lasos ilin ĝis la tempo, kiam la naskontino estos naskinta; tiam liaj ceteraj fratoj revenos al la idoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'Li stariĝos kaj paŝtos kun la forto de la Eternulo, kun la majesto de la nomo de la Eternulo, lia Dio, kaj tiuj konvertiĝos; ĉar tiam li fariĝos granda ĝis la randoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'Kaj li estos paco. Kiam la Asiriano venos en nian landon kaj enpaŝos en niajn palacojn, ni starigos kontraŭ li sep paŝtistojn kaj ok eminentulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'Ili paŝtos la landon Asirian per glavo kaj la landon de Nimrod per iliaj lancoj; kaj li savos nin kontraŭ la Asiriano, kiam ĉi tiu venos en nian landon kaj enpaŝos en niajn limojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'Kaj la restaĵo de Jakob estos inter multe da popoloj kiel roso de la Eternulo, kiel pluvaj gutoj sur herbo; kaj li ne esperos je homo kaj ne fidos homidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Kaj la restaĵo de Jakob estos inter la nacioj, meze de multaj popoloj, kiel leono inter la bestoj de la arbaro, kiel leonido meze de ŝafaroj, kiu dispremas pasante, disŝiras, kaj neniu povas savi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Leviĝos via mano super viaj kontraŭuloj, kaj ĉiuj viaj malamikoj ekstermiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'En tiu tago, diras la Eternulo, Mi ekstermos viajn ĉevalojn ĉe vi kaj pereigos viajn ĉarojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'Mi ekstermos la urbojn de via lando kaj detruos ĉiujn viajn fortikaĵojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'Mi ekstermos ĉe vi la sorĉistojn, kaj vi ne plu havos aŭguristojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Mi ekstermos el via mezo viajn idolojn kaj viajn statuojn, kaj vi ne plu adorkliniĝos antaŭ la faritaĵo de viaj manoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'Mi elŝiros el via mezo viajn sanktajn stangojn kaj ekstermos viajn urbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, 'Kaj en kolero kaj indigno Mi faros venĝon super la nacioj, kiuj ne volos obei.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Aŭskultu, kion diras la Eternulo: Leviĝu, havu juĝan disputon kun la montoj, kaj la montetoj aŭdu vian voĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Aŭskultu, ho montoj, la juĝan disputon de la Eternulo, kaj ankaŭ vi, ho potencaj fundamentoj de la tero; ĉar la Eternulo havas juĝan disputon kun Sia popolo, kaj al Izrael Li volas doni moralinstruon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Ho Mia popolo! kion Mi faris al vi, kaj per kio Mi faris al vi maljustaĵon? respondu al Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Mi elkondukis ja vin el la lando Egipta, kaj el la domo de sklaveco Mi vin elaĉetis, kaj Mi sendis antaŭ vin Moseon, Aaronon, kaj Mirjamon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Ho Mia popolo! rememoru, kion intencis Balak, reĝo de Moab, kaj kion respondis al li Bileam, filo de Beor; de Ŝitim ĝis Gilgal, por ke vi sciu la bonfarojn de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'Kun kio mi povas stariĝi antaŭ la Eternulo, kliniĝi antaŭ Dio en la alto? ĉu mi stariĝu antaŭ Li kun bruloferoj, kun jaraĝaj bovidoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Ĉu al la Eternulo faros plezuron miloj da ŝafoj aŭ sennombraj torentoj da oleo? ĉu mi donu mian unuenaskiton pro mia krimo, la frukton de mia ventro pro la peko de mia animo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Estas dirite al vi, ho homo, kio estas bona kaj kion la Eternulo postulas de vi: nur agi juste, ami bonfarojn, kaj esti modesta antaŭ via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'La voĉo de la Eternulo vokas al la urbo, kaj saĝuloj timas Vian nomon. Humiliĝu antaŭ la puno, kaj antaŭ Tiu, kiu ĝin destinis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Ankoraŭ restas en la domo de malpiulo trezoroj de malpieco, kaj malbeninda malĝusta mezurilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Ĉu Mi povas aprobi falsan pesilon kaj trompajn pezilojn en la saketo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Ĉar la riĉuloj de la urbo estas plenaj de rabemo, kaj ĝiaj loĝantoj parolas mensogon, kaj la lingvo de ilia buŝo estas falsaĵo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'tial Mi dolorige vin frapos per dezertigo pro viaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Vi manĝos, sed ne fariĝos sata; doloron pro malsato vi havos en via interno; vi kaŝos, sed ne povos konservi; kaj kion vi konservos, tion Mi transdonos al la glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Vi semos, sed vi ne rikoltos; vi premos olivojn, sed vi ne ŝmiros vin per oleo; vi premos vinberojn, sed vi ne trinkos vinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Konserviĝis ĉe vi la moroj de Omri kaj ĉiuj faroj de la domo de Aĥab, kaj vi sekvas iliajn konsilojn, por ke Mi faru vin dezerto, viajn loĝantojn mokataĵo, kaj por ke vi portu sur vi la malhonoron de Mia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Ho ve al mi! ĉar mi fariĝis kiel kolektanto de someraj fruktoj kaj de restaĵo de vinberoj, kiu ne trovas beron manĝeblan; bonan maturan frukton deziras mia animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Malaperis piuloj en la lando, kaj ne troviĝas justulo inter la homoj; ĉiuj insidas, por verŝi sangon, unu la alian ĉasas, por pereigi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Por pravigi malbonan faron, la estro postulas donacon kaj la juĝisto pagon; la altrangulo parolas, kion li volas, kaj konfuzas la aferojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'La plej bona inter ili estas kiel dornarbetaĵo, la justulo estas kiel pikaĵa barilo. Sed venos la tago de Via esploro, de Via puno; tiam ili ne scios, kion fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Ne kredu al proksimulo, ne fidu amikon; kontraŭ tiu, kiu kuŝas ĉe via brusto, gardu la aperturon de via buŝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'ĉar filo malhonoras patron, filino batalas kontraŭ sia patrino, bofilino kontraŭ sia bopatrino; la domanoj de homo estas liaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Sed mi rigardas al la Eternulo, mi fidas la Dion de mia savo; mia Dio min aŭskultos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Ne ĝoju pri mi, mia malamikino: kvankam mi falis, mi releviĝos; kvankam mi estas en mallumo, la Eternulo estas lumo por mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'La koleron de la Eternulo mi portos, ĉar mi pekis antaŭ Li, ĝis Li esploros mian aferon kaj faros juĝon super mi; tiam Li elkondukos min en lumon, kaj mi vidos Lian bonecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Kaj tion vidos mia malamikino, kaj honto ŝin kovros pro tio, ke ŝi diris al mi: Kie estas la Eternulo, via Dio? Miaj okuloj ŝin rigardos tiam, kiam ŝi estos piedpremata, kiel koto sur la stratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'En tiu tempo, kiam viaj muroj estos rekonstruataj, en tiu tempo la leĝo disvastiĝos malproksime.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'En tiu tempo oni venos al vi el Asirio kaj el la urboj Egiptaj, de Egiptujo ĝis la Rivero, de maro ĝis maro, kaj de monto ĝis monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'La lando estos dezerta pro ĝiaj loĝantoj, pro la fruktoj de iliaj agoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Paŝtu per Via bastono Vian popolon, Vian heredan ŝafaron, kiu loĝas izolite en la arbaro, meze de Karmel; ili paŝtiĝu en Baŝan kaj Gilead, kiel en la tempo antikva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Kiel en la tempo de via eliro el la lando Egipta, Mi montros al li mirindaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'La nacioj vidos kaj hontos, malgraŭ ilia tuta potenco; ili metos la manon sur la buŝon, iliaj oreloj surdiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'Ili lekos polvon, kiel serpento; kiel la rampaĵoj sur la tero, kun tremado ili elvenos el siaj kaŝejoj; ili ektimos la Eternulon, nian Dion, ili ekrespektos Vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Kiu estas Dio simila al Vi, kiu pardonas malbonagon kaj preterlasas la kulpon de la restaĵo de Sia heredaĵo, ne konservas por ĉiam Sian koleron, ĉar Li amas bonfari?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Li denove kompatos nin, malgrandigos niajn malbonagojn, kaj ĵetos en la profundon de la maro ĉiujn niajn pekojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Vi montros fidelecon al Jakob, favorkorecon al Abraham, kiel Vi ĵuris al niaj patroj en la tempo antikva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Profetaĵo pri Nineve, libro de vizio de Naĥum, la Elkoŝano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'La Eternulo estas Dio severa kaj venĝanta; la Eternulo estas venĝanto kaj koleranto; la Eternulo venĝas al Siaj malamikoj kaj ne forgesas pri Siaj kontraŭuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'La Eternulo estas longepacienca, kaj potenca per Sia forto, kaj neniu estas senkulpa antaŭ Li; la vojo de la Eternulo estas en fulmotondro kaj ventego, kaj nubo estas la polvo sub Liaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Kiam Li ekparolas kolere al la maro, Li elsekigas ĝin, kaj ĉiujn riverojn Li senakvigas; malgajiĝas Baŝan kaj Karmel, kaj velkas ĉio, kio floras sur Lebanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'La montoj tremas antaŭ Li, la montetoj disfandiĝas; skuiĝas antaŭ Li la tero, la mondo kaj ĉiuj ĝiaj loĝantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Kiu povas kontraŭstari al Lia indigno? kaj kiu povas elteni la flamon de Lia kolero? Lia indigno disverŝiĝas kiel fajro; la rokoj disfalas antaŭ Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'La Eternulo estas bona, forta apogo en tago de malfeliĉo; kaj Li konas tiujn, kiuj fidas Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Dronigante per inundo, Li faras finon al loko, kaj Liajn malamikojn persekutas mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Kion vi pensas pri la Eternulo? Li faros la ekstermon, la malfeliĉo ne bezonas veni duafoje.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Ĉar, interplektiĝinte kiel dornoj kaj ebriaj de drinkado, ili estos ekstermitaj, kiel tute seka pajlo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'El vi eliris tiu, kiu havis malbonan intencon kontraŭ la Eternulo kaj kiu estas malica konsilanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Tiele diras la Eternulo: Kvankam ili estas unuanimaj kaj multaj, ili tamen estos dishakitaj kaj malaperos; sed vin, kiun Mi humiligis, Mi ne plu humiligos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Nun Mi rompos lian jugon, kiu estas sur vi, kaj Mi disŝiros viajn ligilojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Sed pri vi la Eternulo decidis: Ne plu restos semo portanta vian nomon; el la domo de viaj dioj Mi ekstermos la idolojn kaj statuojn; Mi signos sur via tombo, ke vi fariĝis senvalora.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'Jen sur la montoj estas la piedoj de sciiganto, kiu proklamas pacon! Festu, ho Judujo, viajn festojn, plenumu viajn sanktajn promesojn; ĉar ne plu iros tra vi la sentaŭgulo; li estas tute ekstermita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Disĵetanto iras kontraŭ vin; fortikigu viajn fortikaĵojn, gardu la vojon, armu viajn lumbojn, fortigu vin kiel eble plej potence.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Ĉar la Eternulo restarigos la majeston de Jakob, kiel ankaŭ la majeston de Izrael; ĉar la ruinigantoj ilin ruinigis kaj ekstermis iliajn vinberbranĉojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'La ŝildo de liaj herooj estas ruĝigita; liaj militistoj estas kiel en purpuro; kiel fajro brilas la ĉaroj en la tago de lia armiĝo; la lancoj ŝanceliĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Sur la stratoj rapide ruliĝas la ĉaroj, bruas sur la placoj; ili aspektas kiel torĉoj, brilas kiel fulmoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Li vokas siajn fortulojn, sed ili falpuŝiĝos dum sia irado; ili rapidas al la murego kaj preparas defendon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'La pordegoj ĉe la akvo malfermiĝos, kaj la palaco cedos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'Decidita estas ĝia kapto kaj forkonduko, kaj ĝiaj sklavinoj ĝemos kiel kolomboj kaj batos sian bruston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Nineve estas de ĉiam kiel baseno da akvo; sed nun ĝi forkuras: Haltu, haltu! sed neniu revenas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Disrabu arĝenton, disrabu oron; senfinaj estas la trezoroj, estas multege da diversaj valoraĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Prirabita kaj plene ruinigita ĝi estos; la koro svenas, la genuoj tremas; ĉies lumboj senfortiĝis, kaj ĉies vizaĝoj nigriĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Kie nun estas la loĝejo de la leonoj, kaj tiu paŝtejo de leonidoj, kie iradis leono, leonino, kaj leonidoj, kaj neniu ilin timigis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'La leono disŝiradis sufiĉon por siaj idoj, sufokadis por siaj leoninoj, plenigadis siajn kavernojn per kaptaĵo kaj siajn nestegojn per disŝiritaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Jen Mi iras kontraŭ vin, diras la Eternulo Cebaot, kaj Mi forbruligos en fumo viajn ĉarojn, kaj glavo ekstermos viajn leonidojn; Mi ĉesigos sur la tero vian disŝiradon, kaj oni ne plu aŭdos la voĉon de viaj sendatoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Ve al la urbo sangavida, kiu estas plena de trompoj kaj raboj, kaj ne volas ĉesigi la rabadon!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Oni aŭdas la sonadon de vipoj, la sonadon de bruantaj radoj; blekas ĉevalo, saltas ĉaro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'moviĝas rajdantoj, brilas glavoj, fulmas lancoj; estas multe da mortigitoj kaj amasoj da kadavroj; sennombraj estas la kadavroj, oni falpuŝiĝas sur ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Tio estas pro la granda malĉastado de la malĉastistino, kiu ĉarmas per sia beleco, estas lerta sorĉistino, kaj vendas naciojn per sia malĉastado kaj gentojn per sia sorĉado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Jen Mi iras kontraŭ vin, diras la Eternulo Cebaot, kaj Mi levos ĝis via vizaĝo la randojn de via vesto, kaj Mi montros al la nacioj vian nudecon kaj al la regnoj vian malhonoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Mi ĵetos sur vin abomenindaĵojn, Mi malhonoros vin kaj faros vin mokataĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'Ĉiu, kiu vidos vin, forkuros de vi, kaj diros: Ruinigita estas Nineve; kiu bedaŭros ĝin? kie mi povas serĉi por vi konsolantojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Ĉu vi estas pli bona ol No-Amon, kiu troviĝas inter riveroj, estas ĉirkaŭata de akvo, kaj kies forto kaj murego estis la maro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Etiopujo kaj la senfina Egiptujo estis ĝia forto, la Putidoj kaj Luboj donadis al vi helpon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'tamen ĝi ankaŭ estas elpatrujigita kaj forkaptita; eĉ ĝiaj malgrandaj infanoj estas frakasitaj en la komenco de ĉiuj stratoj; pri ĝiaj eminentuloj oni lotis, kaj ĉiujn ĝiajn altrangulojn oni katenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Tiel ankaŭ vi ebriiĝos kaj kaŝos vin kaj serĉos defendon kontraŭ la malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Ĉiuj viaj fortikaĵoj estas kiel figarboj kun maturaj fruktoj; se oni ekskuas ilin, ili falas en la buŝon de manĝonto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Jen via popolo estas ĉe vi kiel virinoj; al viaj malamikoj larĝe malfermiĝos la pordegoj de via lando; fajro ekstermos viajn riglilojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Provizu al vi akvon por la tempo de sieĝo; fortigu viajn fortikaĵojn; iru en kalkon, knedu argilon, faru fortajn brikojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Tamen tie la fajro vin konsumos, glavo vin ekstermos, formanĝos vin kiel skarabo, se vi eĉ estus grandnombra kiel skaraboj, grandnombra kiel akridoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Vi havas pli da komercistoj, ol la steloj de la ĉielo; sed ili diskuros kiel akridoj kaj forflugos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Viaj taĉmentoj estas kiel akridoj, kaj viaj taĉmentestroj estas kiel lokustoj, kiuj dum la malvarmo kaŝas sin en fendoj, kaj kiam la suno ekbrilas, ili disflugas tiel, ke oni ne scias, kie ili estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Dormas viaj paŝtistoj, ho reĝo de Asirio, kuŝas viaj fortuloj; via popolo estas disĵetita sur la montoj, kaj troviĝas neniu, kiu ĝin kolektus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Ne resaniĝas via vundo, doloriga estas via ulcero; ĉiu, kiu aŭdas la sciigon pri vi, aplaŭdas pri vi; ĉar kiun ne trafis senĉese via malboneco?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Profetaĵo, kiun laŭvizie eldiris la profeto Ĥabakuk.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Ĝis kiam, ho Eternulo, mi krios, kaj Vi ne aŭskultos, mi krios al Vi pri perfortaĵo, kaj Vi ne helpos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Kial Vi devigas min vidi maljustaĵon, rigardi mizeraĵon? Rabado kaj perfortado estas antaŭ mi, leviĝas disputoj kaj malpaco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Tial la instruo perdis sian forton, la justeco neniam venkas; ĉar la malvirtulo superfortas la virtulon, tial la rezultoj de juĝo estas malĝustaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Rigardu la naciojn, rigardu, kaj vi forte miros; ĉar en via tempo Mi faros ion, kion vi ne kredus, se oni rakontus al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Ĉar jen Mi levos la Ĥaldeojn, nacion kruelan kaj lertan, kiu trairos la tutan larĝon de la tero, por ekposedi loĝejojn, kiuj ne apartenas al ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Terura kaj timinda ĝi estas; ĝia juĝado kaj regado dependas de ĝi mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Pli rapidaj ol leopardoj estas ĝiaj ĉevaloj, kaj pli lertaj ol lupoj vespere; en grandaj amasoj venas ĝiaj rajdantoj de malproksime, flugas kiel aglo, kiu rapidas al manĝaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Ĉiuj ili venas por rabi; kiel vento orienta ili direktas sin, kien ili volas; kaj ili kolektas kaptitojn kiel sablon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Reĝojn ili mokas, regantoj estas ridataĵo por ili; ĉiun fortikaĵon ili mokas; ili ŝutas teron, kaj venkoprenas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Tiam ŝanĝiĝas ilia spirito, transiras kaj fariĝas peka, kaj ilia forto fariĝas ilia dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Sed Vi estas ja de ĉiam, ho Eternulo, mia sankta Dio! ne lasu nin morti. Vi, ho Eternulo, aperigis ilin por juĝo; Vi, ho nia Roko, destinis ilin por puni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Viaj okuloj estas tro puraj, por vidi malbonon, kaj rigardi maljustaĵon Vi ne povas; kiel do Vi rigardas malhonestulojn, kaj silentas, kiam malpiulo englutas tiun, kiu estas pli virta ol li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Kial Vi faras la homojn kiel fiŝoj en la maro, kiel rampaĵoj, kiuj ne havas reganton?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Ĉiujn ili tiras per fiŝhoko, kaptas per sia reto, amasigas per sia fiŝreto; kaj tial ili ĝojas kaj triumfas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Tial ili alportas oferojn al sia reto, incensas al sia fiŝreto; ĉar per ĉi tiuj grasiĝis ilia parto kaj boniĝis ilia manĝaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Ĉu por tio ili devas ĵetadi sian reton kaj senĉese mortigadi naciojn senindulge?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Sur mia gardista posteno mi staris; kaj, stariĝinte sur turo, mi observis, por vidi, kion Li diros al mi kaj kion mi devas respondi al la riproĉo kontraŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Kaj la Eternulo ekparolis al mi, kaj diris: Enskribu la vizion, kaj desegnu bone sur la tabeloj, por ke leganto povu facile tralegi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Ĉar la vizio koncernas tempon difinitan kaj parolas pri la fino, sed ĝi ne mensogas; se ĝi prokrastiĝus, atendu ĝin, ĉar ĝi nepre plenumiĝos, ne estos fordecidita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Vidu, kiu estas malhumila, ties animo ne estos trankvila en li; sed virtulo vivos per sia fideleco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'La vino trompas viron fieran, kaj li ne humiliĝas; li larĝigas sian animon kiel Ŝeol, kaj kiel la morto li estas nesatigebla, li kolektas al si ĉiujn naciojn kaj kaptas al si ĉiujn popolojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Sed ili ja ĉiuj parolos pri li alegorion kaj mokan enigmon, kaj diros: Ve al tiu, kiu tro multigas al si fremdaĵon sen fino kaj metas sur sin tro grandan ŝarĝon de ŝuldoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Subite ja leviĝos viaj pikontoj kaj vekiĝos viaj puŝontoj, kaj vi fariĝos ilia rabataĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Ĉar vi prirabis multe da nacioj, tial ankaŭ vin prirabos la ceteraj popoloj, pro la sango de homoj, pro la premado de la lando, de la urbo, kaj de ĉiuj ĝiaj loĝantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Ve al tiu, kiu kolektas por sia domo maljustan akiraĵon, por aranĝi alte sian neston, por defendi sin kontraŭ mano de malbonulo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Vi elpensis malhonoron por via domo, disbatante multe da popoloj kaj pekigante vian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'La ŝtonoj el la muroj krias, kaj la lignaj traboj respondas al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Ve al tiu, kiu konstruas urbon per sangoverŝado kaj pretigas fortikaĵon per maljusteco!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Tio venas ja de la Eternulo Cebaot, ke la popoloj klopodas por la fajro kaj la gentoj lacigas sin vane.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Ĉar la tero pleniĝos de konado de la gloro de la Eternulo, kiel la akvo plenigas la maron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Ve al vi, kiu drinkigas sian proksimulon, por elverŝi vian koleron, kaj ebriigas lin, por vidi lian honton!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Vi satiĝis per honto anstataŭ per honoro; drinku do ankaŭ vi, kaj kovru vin per honto; ankaŭ al vi venos la kaliko el la dekstra mano de la Eternulo, kaj neniigo de via gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Ĉar via perforteco sur Lebanon falos sur vin, kaj atakate de bestoj vi estos terurata pro la sango de homoj, pro la premado de la lando, de la urbo, kaj de ĉiuj ĝiaj loĝantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Kion helpos la skulptaĵo, kiun skulptis la artisto, la fanditaĵo kaj malvera instruanto, kvankam la majstro fidis sian propran faritaĵon, farante mutajn idolojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Ve al tiu, kiu diras al ligno: Leviĝu, kaj al muta ŝtono: Vekiĝu! Ĉu ĝi povas instrui? ĝi estas ja tegita per oro kaj arĝento, sed havas en si nenian spiriton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Sed la Eternulo estas en Sia sankta templo; la tuta tero silentu antaŭ Li!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Preĝo de la profeto Ĥabakuk laŭ maniero de psalmoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Ho Eternulo, mi aŭdis la sciigon pri Vi, kaj mi ektimis. Ho Eternulo, vivigu Vian faritaĵon en la mezo de la jaroj, Montru en la mezo de la jaroj, Ke eĉ en kolero Vi memoras pri kompato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Dio venas de Teman, La Sanktulo de la monto Paran. Sela. Lia majesto kovras la ĉielon, Kaj Lia gloro plenigas la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Lia brilo estas kiel hela lumo, Radioj iras el Lia mano, Kaj tie estas kaŝita Lia potenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Antaŭ Li iras pesto, Kaj fajro sekvas Liajn piedojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Li stariĝis, kaj ekmezuris la teron; Li ekrigardis, kaj tremigis la naciojn; Dissaltis eternaj montoj, Kliniĝis eternaj montetoj, Kiam Li ekpaŝis kiel en la tempo antikva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'En mizera stato mi vidis la tendojn de Kuŝan; Skuiĝis la tapiŝoj de la lando Midjan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Ĉu kontraŭ riveroj koleris la Eternulo? Ĉu kontraŭ la riveroj Vi ekflamiĝis, Aŭ ĉu kontraŭ la maro estis Via indigno, Ke Vi ekrajdis sur Viaj ĉevaloj, Ekveturis sur Viaj venkaj ĉaroj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Vi eltiris Vian pafarkon, Konforme al ĵura promeso, kiun Vi donis al la triboj. Sela. Per riveroj Vi dividis la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Ektremis la montoj, kiam ili Vin vidis; La fluo de la akvo pasis, La abismo ekbruis, La altaĵo levis siajn manojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'La suno kaj la luno haltis sur sia loko; Kun brilo iras Viaj sagoj, Kun fulmo Viaj lancoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'Kun kolero Vi paŝas sur la tero, Kun indigno Vi piedpremas naciojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Vi elpaŝis, por helpi al Via popolo, Por helpi al Via sanktoleito. Vi frakasas la supron de la domo de malpiulo, Nudigas la fundamenton ĝis la kolo. Sela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Vi trapikis per liaj lancoj la kapojn de liaj taĉmentestroj, Kiam ili sin ĵetis ventege, por dispeli min kun ĝojo, Kvazaŭ englutante mizerulon kaŝe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Vi paŝis kun Viaj ĉevaloj tra la maro, Tra la ŝlimo de granda akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Mi aŭdis, kaj mia interno ekskuiĝis; Pro la bruo ektremis miaj lipoj, Putro venis en miajn ostojn, kaj la loko sub mi ekŝanceliĝis; Dume mi devas esti trankvila en la tago de malfeliĉo, Kiam sur mian popolon iras ĝia atakanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Kiam la figarbo ne floros, La vinberbranĉoj ne donos fruktojn, La olivarbo rifuzos sian laboron, La plugokampoj ne donos manĝaĵon, La ŝafoj estos forkaptitaj el la ŝafejo, Kaj en la staloj ne troviĝos bovoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'Eĉ tiam mi ĝojos pri la Eternulo, Mi estos gaja pri la Dio de mia savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'La Eternulo, la Sinjoro, estas mia forto; Li faras miajn piedojn kiel ĉe cervo, Kaj venigas min sur miajn altaĵojn. Al Li, la Venkanto, iru miaj kantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Vorto de la Eternulo, kiu aperis al Cefanja, filo de Kuŝi, filo de Gedalja, filo de Amarja, filo de Ĥizkija, en la tempo de Joŝija, filo de Amon, reĝo de Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Mi forprenos ĉion de sur la tero, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Mi forprenos la homojn kaj la brutojn, Mi forprenos la birdojn de la ĉielo kaj la fiŝojn de la maro, la delogilojn kune kun la malpiuloj; Mi ekstermos la homojn de sur la tero, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Mi etendos Mian manon sur Judujon kaj sur ĉiujn loĝantojn de Jerusalem; Mi ekstermos de ĉi tiu loko la restaĵon de Baal, la nomon de la idolpastroj kaj ankaŭ de la pastroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'tiujn, kiuj sur la tegmentoj adorkliniĝas antaŭ la armeo de la ĉielo, kaj tiujn, kiuj, adorkliniĝante, ĵuras per la Eternulo kaj ĵuras ankaŭ per Malkam;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'kaj tiujn, kiuj defalis de la Eternulo, kiuj ne serĉis la Eternulon kaj ne turnis sin al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Silentu antaŭ la Sinjoro, la Eternulo, ĉar proksima estas la tago de la Eternulo; ĉar la Eternulo pretigis buĉoferon kaj destinis la invitotojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'En la tago de la buĉofero de la Eternulo Mi punos la altrangulojn kaj la reĝidojn, kaj ĉiujn, kiuj vestas sin per vestoj de aligentuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Mi punos en tiu tago ĉiujn, kiuj transsaltas la sojlon kaj plenigas la domon de sia sinjoro per perforteco kaj trompoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'En tiu tago, diras la Eternulo, estos laŭta kriado ĉe la Pordego de Fiŝoj, ĝemegado ĉe la dua kvartalo de la urbo, kaj granda plorkriado sur la montetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Ĝemegu, loĝantoj de la malalta parto de la urbo; ĉar malaperos la tuta popolo de la butikistoj, kaj ekstermitaj estos ĉiuj ŝarĝitaj per arĝento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'En tiu tempo Mi traesploros Jerusalemon kun lumiloj, kaj Mi punos tiujn, kiuj ripozas sur sia feĉo, kaj diras en sia koro: La Eternulo ne faras bonon, nek malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Ilia havaĵo fariĝos rabaĵo, kaj iliaj domoj fariĝos ruinoj; ili konstruos domojn, sed ne loĝos en ili, ili plantos vinberĝardenojn, sed ne trinkos ilian vinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Proksima estas la granda tago de la Eternulo, ĝi estas proksima kaj venos tre baldaŭ; oni aŭdas jam la tagon de la Eternulo; maldolĉe tiam plorkrios eĉ kuraĝulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Tago de kolero estos tiu tago, tago de malĝojo kaj de angoro, tago de teruro kaj de dezertigo, tago de mallumo kaj de senlumeco, tago de nuboj kaj de nebulego,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'tago de korno kaj de trumpetado kontraŭ la fortikigitaj urboj kaj kontraŭ la altaj turoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'Mi premos la homojn, kaj ili irados kiel blinduloj pro tio, ke ili pekis antaŭ la Eternulo; ilia sango estos disŝprucigita kiel polvo, kaj ilia karno kiel sterko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Nek ilia arĝento nek ilia oro povos ilin savi en la tago de la kolero de la Eternulo, sed per la fajro de Lia indigno estos forbruligita la tuta lando; ĉar rapidan ekstermon Li faros al ĉiuj loĝantoj de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Kolektiĝu kaj konsciiĝu, ho nacio ne aminda,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'antaŭ ol eliris la dekreto (la tago forflugas kiel grenventumaĵo), antaŭ ol trafis vin la flama kolero de la Eternulo, antaŭ ol venis por vi la tago de indigno de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Serĉu la Eternulon, ĉiuj humiluloj sur la tero, kiuj plenumas Liajn leĝojn; serĉu veron, serĉu humilecon, por ke vi povu esti kaŝitaj en la tago de kolero de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Ĉar Gaza estos forlasita, Aŝkelon estos dezertigita, Aŝdod estos elpelita meze de la tago, kaj Ekron estos elradikigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Ve al tiuj, kiuj loĝas en la distrikto de la maro, al la nacio de Keretidoj! la vorto de la Eternulo estas kontraŭ vi, ho Kanaan, lando Filiŝta: Mi vin pereigos tiel, ke restos neniu loĝanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'La apudmara regiono estos nur loko por loĝejoj de paŝtistoj kaj por ŝafejoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'Kaj la regiono fariĝos apartenaĵo de la restaĵo de la domo de Jehuda; tie ili paŝtos, en la domoj de Aŝkelon ili ripozos vespere, post kiam la Eternulo, ilia Dio, rememoros ilin kaj revenigos ilin el la kaptiteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Mi aŭdis la insultadon de Moab kaj la malhonoradon de la Amonidoj, kiel ili insultadis Mian popolon kaj fanfaronadis ĉe ĝiaj limoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Tial, kiel Mi vivas, diras la Eternulo Cebaot, Dio de Izrael, Moab fariĝos kiel Sodom, kaj la Amonidoj kiel Gomora, urtikejo, salfosejo, dezerto por ĉiam; la restaĵo de Mia popolo prenos ilin kiel kaptaĵon, kaj la restintoj el Mia popolo heredos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'Tio fariĝos al ili pro ilia malhumileco, pro tio, ke ili insultadis la popolon de la Eternulo Cebaot kaj tenis sin alte antaŭ ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'La Eternulo estos terura por ili; ĉar Li ekstermos ĉiujn diojn de la tero; kaj antaŭ Li adorkliniĝos, ĉiu sur sia loko, ĉiuj insuloj de la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Ankaŭ vi, ho Etiopoj, estos mortigitaj de Mia glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Li etendos Sian manon norden kaj pereigos Asirion, kaj faros Nineven ruinoj, senakva loko, kiel dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'Kaj ripozados en ĝi amasoj da ĉiuspecaj bestoj; eĉ pelikanoj kaj botaŭroj noktos en ĝiaj kapiteloj, kaj ilia voĉo estos aŭdata tra la fenestroj; la sojloj estos ruinigitaj, ĉar la cedraj tabuloj estos forŝiritaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'Tia estos la gaja urbo, kiu estis ekster danĝero, kaj kiu parolis en sia koro: Mi estas sola, kaj ne ekzistas alia krom mi. Kiel ĝi estas ruinigita, fariĝis ripozejo por bestoj! Ĉiu preteriranto fajfos pri ĝi kaj svingos la manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Ve al la abomeninda kaj malpurigita urbo-premanto!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Ĝi ne aŭskultas voĉon, ne akceptas admonon; la Eternulon ĝi ne fidas, al sia Dio ĝi sin ne turnas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Ĝiaj eminentuloj meze de ĝi estas kiel blekegantaj leonoj; ĝiaj juĝistoj estas kiel lupoj vespere; ili nenion restigas ĝis mateno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Ĝiaj profetoj estas facilanimaj kaj perfidaj; ĝiaj pastroj malsanktigas la sanktejon, kripligas la instruon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'La Eternulo estas justulo meze de ĝi, Li ne faras maljustaĵon; ĉiumatene Li montras Siajn leĝojn, ne ĉesas; sed la malpiulo ne konas honton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'Mi ekstermis naciojn; ruinigitaj estas iliaj turoj; Mi dezertigis iliajn stratojn tiel, ke neniu trairas ilin; iliaj urboj estas ruinigitaj tiel, ke tie troviĝas jam neniu homo, neniu loĝanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Mi diris al ĝi: Timu Min, akceptu admonon! Kaj ne estus ekstermita ĝia loĝejo, kiom ajn Mi punus ĝin; sed ili rapidis malbonigi ĉiujn siajn agojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Tial atendu Min, diras la Eternulo, ĝis Mi Miatempe leviĝos; ĉar Mi decidis kolekti la naciojn, kunvenigi la regnojn, por elverŝi sur ilin Mian koleron, la tutan flamon de Mia indigno; ĉar de la fajro de Mia severeco forbrulos la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Tiam Mi redonos al la popoloj lingvon puran, por ke ĉiuj vokadu la nomon de la Eternulo kaj servadu al Li unuanime.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'El trans la riveroj de Etiopujo Miaj adorantoj, Mia disĵetita popolo, alportos al Mi donacojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'En tiu tempo vi ne plu hontos pri ĉiuj viaj agoj, per kiuj vi krimis kontraŭ Mi; ĉar tiam Mi forigos el inter vi viajn fierajn fanfaronulojn, kaj vi ne plu tenos vin malhumile sur Mia sankta monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'Mi restigos en via mezo popolon humilan kaj malriĉan, kaj ili fidados la nomon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'La restintoj el Izrael ne faros maljustaĵon, ne parolos mensogon, kaj en ilia buŝo ne troviĝos lango trompa, sed ili paŝtiĝados kaj ripozados, kaj neniu ilin timigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Ĝojkriu, ho filino de Cion; triumfu, ho Izrael; ĝoju kaj estu gaja el la tuta koro, ho filino de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'La Eternulo forigis la verdikton pri vi, forpelis vian malamikon; la Reĝo de Izrael, la Eternulo, estas meze de vi, kaj vi ne plu vidos malfeliĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'En tiu tempo oni diros al Jerusalem: Ne timu! kaj al Cion: Viaj manoj ne senfortiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'La Eternulo, via Dio, estas meze de vi, forta Savanto; Li ĝojos pri vi gaje, Li pardonos al vi pro Sia amo, Li ĝoje triumfos pri vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'La sentaŭgulojn el via mezo Mi forprenos, por ke vi ne plu havu malhonoron pro ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Jen Mi faros finon en tiu tempo al ĉiuj viaj premantoj, Mi helpos la lamulojn, Mi kolektos la dispelitojn, kaj Mi faros ilin gloraj kaj honorataj en ĉiuj landoj, kie oni malestimis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'En tiu tempo Mi venigos vin, kaj en tiu tempo Mi kolektos vin; ĉar Mi faros vin gloraj kaj honorataj inter ĉiuj popoloj de la lando, kiam Mi revenigos viajn kaptitojn antaŭ viaj okuloj, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'En la dua jaro de la reĝo Dario, en la sesa monato, en la unua tago de la monato, aperis vorto de la Eternulo per la profeto Ĥagaj al Zerubabel, filo de Ŝealtiel, regionestro de Judujo, kaj al la ĉefpastro Josuo, filo de Jehocadak, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'Tiele diras la Eternulo Cebaot: Tiu popolo diras, ke ankoraŭ ne venis la tempo, por konstrui la domon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Sed aperis vorto de la Eternulo per la profeto Ĥagaj, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Ĉu por vi mem estas nun la ĝusta tempo, por sidi en viaj tabulitaj domoj, dum tiu domo estas ruinoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Nun tiele diras la Eternulo Cebaot: Pripensu bone vian staton:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'vi semas multe, sed enportas malmulte; vi manĝas, sed ne ĝissate; vi trinkas, sed ne ĝisebrie; vi vestas vin, sed ne estas al vi varme; kiu laborenspezas monon, tiu laborenspezas por truhava saketo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Tiele diras la Eternulo Cebaot: Pripensu bone vian staton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Iru sur la monton, prenu lignon, kaj konstruu la domon; Mi akceptos ĝin favore, kaj Mi montros Mian gloron, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Vi atendis multon, sed montriĝis, ke estas malmulte; kaj kion vi alportis hejmen, tion Mi disblovis. Pro kio tiel estas? diras la Eternulo Cebaot; pro tio, ke Mia domo estas dezerta, dum vi kuras ĉiu al sia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Pro tio la ĉielo ne donas al vi roson kaj la tero ne donas siajn produktaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'Kaj Mi alvokis sekecon sur la teron, sur la montojn, sur la grenon, sur la moston, sur la oleon, kaj sur ĉion, kion produktas la tero, ankaŭ sur la homon, sur la bruton, kaj sur ĉiun laboron de la manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Zerubabel, file de Ŝealtiel, kaj la ĉefpastro Josuo, filo de Jehocadak, kaj la tuta cetera popolo aŭskultis la voĉon de la Eternulo, ilia Dio, kaj la vortojn de la profeto Ĥagaj, kun kiuj lin sendis la Eternulo, ilia Dio; kaj la popolo ektimis la Eternulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Kaj Ĥagaj, la sendito de la Eternulo, diris al la popolo en la nomo de la Eternulo jene: Mi estas kun vi, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Kaj la Eternulo vigligis la spiriton de Zerubabel, filo de Ŝealtiel, regionestro de Judujo, kaj la spiriton de la ĉefpastro Josuo, filo de Jehocadak, kaj la spiriton de la tuta cetera popolo; kaj ili venis kaj komencis labori en la domo de la Eternulo Cebaot, ilia Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'en la dudek-kvara tago de la sesa monato, en la dua jaro de la reĝo Dario.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'En la sepa monato, en la dudek-unua tago de la monato, aperis vorto de la Eternulo per la profeto Ĥagaj, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Diru al Zerubabel, filo de Ŝealtiel, regionestro de Judujo, kaj al la ĉefpastro Josuo, filo de Jehocadak, kaj al la cetera popolo jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Kiu restis inter vi, kiu vidis ĉi tiun domon en ĝia antaŭa belegeco? kaj kion vi vidas en ĝi nun? ĉu ĝi ne aperas antaŭ viaj okuloj kiel nenio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Sed estu kuraĝa, ho Zerubabel, diras la Eternulo; estu kuraĝa, ho ĉefpastro Josuo, filo de Jehocadak; estu kuraĝa, ho tuta popolo de la lando, diras la Eternulo; kaj laboru, ĉar Mi estas kun vi, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'Konforme al la interligo, kiun Mi faris kun vi, kiam vi eliris el Egiptujo, Mia spirito estas inter vi; ne timu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Ĉar tiele diras la Eternulo Cebaot: Pasos malmulte da temo, kaj Mi ekmovos la ĉielon kaj la teron, la maron kaj la sekteron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'Mi skuos ĉiujn popolojn; kaj venos io ĉarma por ĉiuj nacioj, kaj Mi plenigos ĉi tiun domon per gloro, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Al Mi apartenas la arĝento kaj al Mi apartenas la oro, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'La gloro de ĉi tiu lasta domo estos pli granda, ol de la antaŭa, diras la Eternulo Cebaot; kaj sur ĉi tiu loko Mi donos pacon, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'En la dudek-kvara tago de la naŭa monato, en la dua jaro de Dario, aperis vorto de la Eternulo per la profeto Ĥagaj, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'Tiele diras la Eternulo Cebaot: Petu de la pastroj instruon, kaj diru:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Jen homo portis sanktigitan viandon en la basko de sia vesto, kaj per sia basko li ektuŝis panon aŭ ion kuiritan aŭ vinon aŭ oleon aŭ ian manĝaĵon-ĉu ĝi tiam fariĝos sankta? La pastroj respondis kaj diris: Ne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Ĥagaj plue diris: Kaj se ĉion ĉi tion ektuŝos iu, kiu malpuriĝis per mortinto-ĉu ĝi tiam malpuriĝos? La pastroj respondis kaj diris: Ĝi malpuriĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Tiam Ĥagaj diris: Tia estas ĉi tiu popolo, kaj tia estas ĉi tiu gento antaŭ Mi, diras la Eternulo, kaj tiaj estas ĉiuj faroj de iliaj manoj; kaj ĉio, kion ili tie alportas, estas malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Nun pripensu bone la tempon de ĉi tiu tago malantaŭen, antaŭ ol estis metita ŝtono sur ŝtonon en la templo de la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'kiam iu venis al garbaro, kiu devis havi dudek mezurojn, ĝi havis nur dek; kiam iu venis al la vinpremejo, por ĉerpi kvindek mezurojn, troviĝis nur dudek;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Mi frapis vin per sekiga vento, per forvelkado kaj per hajlo ĉiujn laborojn de viaj manoj, sed vi tamen ne turnis vin al Mi, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Pripensu bone la tempon de ĉi tiu tago malantaŭen, de la dudek-kvara tago de la naŭa monato, de la tago, en kiu estas fondita la templo de la Eternulo; pripensu bone:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'ĉu troviĝas semoj en la grenejo? ĝis nun la vinberbranĉo, la figarbo, la granatarbo, kaj la olivarbo ne donis fruktojn; sed de post ĉi tiu tago Mi vin benos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Kaj duafoje aperis vorto de la Eternulo al Ĥagaj en la dudek-kvara tago de la monato, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Diru al Zerubabel, regionestro de Judujo, jene: Mi ekmovos la ĉielon kaj la teron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'Mi renversos tronojn de regnoj, Mi ekstermos la forton de regnoj de la nacioj, Mi renversos ĉarojn kun iliaj veturantoj; falos la ĉevaloj, kaj iliaj rajdantoj falos unu de glavo de alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'En tiu tempo, diras la Eternulo Cebaot, Mi prenos vin, ho Zerubabel, Mia servanto, filo de Ŝealtiel, diras la Eternulo, kaj Mi konservos vin kiel sigelringon; ĉar vin Mi elektis, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'En la oka monato, en la dua jaro de Dario, aperis vorto de la Eternulo al la profeto Zeĥarja, filo de Bereĥja, filo de Ido, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'Forte koleris la Eternulo kontraŭ viaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Diru do al ili: Tiele diras la Eternulo Cebaot: Revenu al Mi, diras la Eternulo Cebaot, kaj tiam Mi returnos Min al vi, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Ne estu kiel viaj patroj, al kiuj vokadis la antaŭaj profetoj, dirante: Tiele diras la Eternulo Cebaot: Deturnu vin de viaj malbonaj vojoj kaj de viaj malbonaj agoj-sed ili ne aŭskultis kaj ne atentis Min, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Kie estas viaj patroj? kaj eĉ la profetoj, ĉu ili povas vivi eterne?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Sed Miaj vortoj kaj decidoj, pri kiuj Mi diris al Miaj servantoj, la profetoj, ĉu ili ne trafis viajn patrojn? Kaj ili pentis, kaj diris: Kiel la Eternulo Cebaot decidis agi kun ni pro niaj vojoj kaj pro niaj agoj, tiel Li agis kun ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'En la dudek-kvara tago de la dek-unua monato, tio estas de la monato Ŝebat, en la dua jaro de Dario, aperis vorto de la Eternulo al la profeto Zeĥarja, filo de Bereĥja, filo de Ido, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Mi vidis en la nokto: jen viro sidas sur ruĝa ĉevalo, kaj li troviĝas inter mirtoj en ombrita loko, kaj post li troviĝas ĉevaloj ruĝaj, brunaj, kaj blankaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Mi demandis: Kiuj ili estas, mia sinjoro? Kaj la anĝelo, kiu parolis kun mi, diris al mi: Mi montros al vi, kiuj ili estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Kaj la viro, kiu troviĝis inter la mirtoj, ekparolis kaj diris: Ili estas tiuj, kiujn la Eternulo sendis, por trairi la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Kaj ili mem ekparolis al la anĝelo de la Eternulo, kiu troviĝis inter la mirtoj, kaj diris: Ni trairis la teron, kaj ni trovis, ke la tuta tero estas trankvila kaj paca.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Tiam ekparolis la anĝelo de la Eternulo kaj diris: Ho Eternulo Cebaot, kiel longe Vi ne kompatos Jerusalemon kaj la urbojn de Judujo, kiujn Vi koleras jam dum sepdek jaroj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Kaj la Eternulo respondis al la anĝelo, kiu parolis kun mi, vortojn bonajn, vortojn konsolajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Tiam diris al mi la anĝelo, kiu parolis kun mi: Proklamu kaj diru: Tiele diras la Eternulo Cebaot: Mi ekfervoris pri Jerusalem kaj pri Cion per granda fervoro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'kaj per granda indigno Mi indignas kontraŭ la nacioj memfidaj; ĉar kiam Mi koleris malmulte, ili akcelis la malfeliĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Tial tiele diras la Eternulo: Mi returnas Min al Jerusalem kun kompato; Mia domo estos konstruita en ĝi, diras la Eternulo Cebaot, kaj ŝnuro de ĉarpentistoj estos tirata en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Ankoraŭ proklamu jenon: Tiele diras la Eternulo Cebaot: Denove pleniĝos Miaj urboj per bonaĵo, denove la Eternulo konsolos Cionon, kaj denove Li elektos Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'Mi levis miajn okulojn kaj ekvidis: jen estas kvar kornoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'Kaj mi diris al la anĝelo, kiu parolis kun mi: Kion tio signifas? Kaj li respondis al mi: Tio estas la kornoj, kiuj disĵetis Jehudan, Izraelon, kaj Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'Kaj la Eternulo montris al mi kvar majstrojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'Mi diris: Kion ili intencas fari? Li respondis jene: Tiuj kornoj disĵetis Jehudan tiel, ke neniu povis levi sian kapon; tial nun venas ĉi tiuj, por fortimigi tiujn, por dehaki la kornojn de la nacioj, kiuj levis sian kornon kontraŭ la loĝantojn de Judujo, por disĵeti ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Mi denove levis miajn okulojn, kaj mi ekvidis: jen staras viro, kiu tenas en sia mano mezurŝnuron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'Mi demandis: Kien vi iras? Kaj li respondis al mi: Mezuri Jerusalemon, por vidi, kiel larĝa kaj kiel longa ĝi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'Kaj jen la anĝelo, kiu parolis kun mi, eliris, kaj alia anĝelo iris renkonte al li,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'kaj diris al li: Kuru, kaj diru al ĉi tiu junulo: Sen murego estos Jerusalem, pro la multeco de la homoj kaj brutoj en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Sed Mi estos por ĝi fajra murego ĉirkaŭe, diras la Eternulo, kaj Mi estos glora meze de ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'He, he! kuru el la lando norda, diras la Eternulo; ĉar kiel la kvar ventojn de la ĉielo Mi dispelis vin, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'He, Cion, kiu loĝas ĉe la filino de Babel, saviĝu!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Ĉar tiele diras la Eternulo Cebaot: Post la gloriĝo Li sendos min al la nacioj, kiuj prirabis vin; ĉar kiu tuŝas vin, tiu tuŝas la pupilon de Lia okulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Kaj jen mi levos mian manon sur ilin, kaj ili fariĝos rabaĵo por tiuj, kiujn ili sklavigis; kaj tiam vi ekscios, ke la Eternulo Cebaot min sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Ĝoju kaj estu gaja, ho filino de Cion; ĉar jen Mi iras, por ekloĝi meze de vi, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'Kaj multaj popoloj aliĝos al la Eternulo en tiu tempo, kaj fariĝos Mia popolo, kaj Mi ekloĝos meze de vi; kaj vi ekscios, ke la Eternulo Cebaot sendis min al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Kaj la Eternulo posedos Judujon kiel Sian heredan parton sur la sankta tero, kaj Li denove favoros Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Ĉiu karno silentu antaŭ la Eternulo, ĉar Li leviĝis el Sia sankta loĝejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Li montris al mi la ĉefpastron Josuo, kiu staris antaŭ la anĝelo de la Eternulo, kaj Satanon, kiu staris dekstre de li, por kontraŭagi al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Kaj la Eternulo diris al Satano: La Eternulo faras al vi severan riproĉon, ho Satano, severe riproĉas vin la Eternulo, kiu favoras Jerusalemon; ĝi estas ja brulŝtipo, savita el la fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Josuo estis vestita per malpuraj vestoj, kaj staris antaŭ la anĝelo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'Ĉi tiu ekparolis kaj diris al tiuj, kiuj staris antaŭ li: Deprenu de li la malpurajn vestojn. Kaj al li mem li diris: Vidu, mi deprenis de vi vian pekon, kaj mi metos sur vin festajn vestojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Kaj li diris, ke oni metu puran kapornamon sur lian kapon; kaj oni metis la puran kapornamon sur lian kapon kaj vestis lin per novaj vestoj, en la ĉeesto de la anĝelo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Kaj la anĝelo de la Eternulo atestis al Josuo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'Tiele diras la Eternulo Cebaot: Se vi irados laŭ Miaj vojoj kaj plenumados la servadon al Mi, tiam vi regados en Mia domo kaj administrados en Miaj kortoj, kaj Mi donos al vi akompanantojn el tiuj, kiuj staras ĉi tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Aŭskultu, ho ĉefpastro Josuo, vi kaj viaj amikoj, kiuj sidas apud vi, ĉar ili komprenas misterajn signojn: jen Mi venigos Mian servanton-markoton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Ĉar vidu la ŝtonon, kiun Mi metis antaŭ Josuon: sur ĉi tiu sola ŝtono estas sep okuloj; jen Mi gravuros sur ĝi signojn, diras la Eternulo Cebaot, kaj Mi forigos la pekon de ĉi tiu lando en unu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'En tiu tempo, diras la Eternulo Cebaot, vi vokos unu alian sub vinberbranĉon kaj sub figarbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Kaj revenis la anĝelo, kiu antaŭe parolis kun mi; kaj li vekis min, kiel oni vekas iun el lia dormo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'Kaj li diris al mi: Kion vi vidas? Mi respondis: Mi vidas kandelabron tute el oro, kaj kaliketon ĝi havas sur sia supro, kaj sep lucernoj estas sur ĝi, kaj po sep tubetoj troviĝas sur la lucernoj supre de ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'Kaj du olivarboj troviĝas super ĝi: unu dekstre de la kaliketo kaj la dua maldekstre de ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Kaj mi ekparolis kaj diris al la anĝelo, kiu parolis kun mi: Kio tio estas, ho mia sinjoro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'La anĝelo, kiu parolis kun mi, respondis kaj diris: Ĉu vi ne scias, kio tio estas? Mi diris: Ne, mia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Tiam li responde diris al mi jene: Tio estas la vorto de la Eternulo al Zerubabel, kaj signifas: Ne per militistaro kaj ne per forto, sed nur per Mia spirito, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Kiu vi estas, ho granda monto? antaŭ Zerubabel vi fariĝos ebenaĵo; kaj li metos la unuan ŝtonon sub komuna vokado: Feliĉo, feliĉo al ĝi!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'La manoj de Zerubabel fondis ĉi tiun domon, kaj liaj manoj ankaŭ finos ĝin; kaj vi ekscios, ke la Eternulo Cebaot sendis min al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Ĉar kiu povas malŝati ĉi tiun tagon kiel malgrandan, kiam ĝoje rigardas la vertikalŝnuron en la mano de Zerubabel tiuj sep okuloj de la Eternulo, kiuj trapenetras per sia rigardo la tutan teron?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Tiam mi denove parolis kaj diris al li: Kion signifas tiuj du olivarboj dekstre kaj maldekstre de la kandelabro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Kaj mi parolis ankoraŭ kaj diris al li: Kion signifas la du branĉoj de olivarboj, kiuj troviĝas apud la du oraj tubetoj, tra kiuj fluas oro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Li respondis al mi kaj diris: Ĉu vi ne scias, kio tio estas? Mi diris: Ne, mia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Tiam li diris: Tio estas du oleitoj, kiuj staras apud la Reganto de la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Mi levis denove miajn okulojn, kaj mi ekvidis disvolvitan skribrulaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'Kaj li diris al mi: Kion vi vidas? Mi respondis: Mi vidas disvolvitan skribrulaĵon, kiu havas la longon de dudek ulnoj kaj la larĝon de dek ulnoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Tiam li diris al mi: Tio estas la malbeno, kiu eliras sur la supraĵon de la tuta lando; ĉar ĉiu, kiu ŝtelas, estos ekstermita, kiel estas dirite en ĝi, kaj ĉiu, kiu ĵuras mensoge, estos ekstermita, kiel estas dirite en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Mi elirigas ĝin, diras la Eternulo Cebaot, kaj ĝi eniros en la domon de ŝtelisto, kaj en la domon de tiu, kiu malvere ĵuras per Mia nomo; kaj ĝi restos en lia domo kaj ekstermos ĝin kune kun ĝia ligno kaj kun ĝiaj ŝtonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'La anĝelo, kiu parolis kun mi, elpaŝis, kaj diris al mi: Levu nun viajn okulojn, kaj rigardu, kio aperas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Mi diris: Kio tio estas? Kaj li respondis: Eliras mezurvazo; kaj li diris plue: Tio estas ilia aspekto en la tuta lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'Kaj jen leviĝis kikaro da plumbo, kaj jen ia virino sidas interne de la mezurvazo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Li diris: Tio estas la Malpieco; kaj li ĵetis ŝin sur la fundon de la mezurvazo, kaj sur la aperturon li ĵetis la plumban mason.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Mi levis miajn okulojn, kaj vidis, ke aperas du virinoj, kaj vento estas en iliaj flugiloj, kaj iliaj flugiloj estis kiel la flugiloj de cikonio; ili levis la mezurvazon inter la teron kaj la ĉielon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Mi diris al la anĝelo, kiu parolis kun mi: Kien ili forportas tiun mezurvazon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Li respondis al mi: Por konstrui por ĝi domon en la lando Ŝinar; kiam ĉio estos preta, oni starigos ĝin tie sur ĝia bazo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Mi levis denove miajn okulojn, kaj mi ekvidis: jen kvar ĉaroj eliras el inter du montoj; kaj la montoj estas kupraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'La unua ĉaro havis ĉevalojn ruĝajn, la dua ĉaro havis ĉevalojn nigrajn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'la tria ĉaro havis ĉevalojn blankajn, kaj la kvara ĉaro havis ĉevalojn makulitajn kaj brunajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Mi ekparolis kaj diris al la anĝelo, kiu parolis kun mi: Kio tio estas, mia sinjoro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'La anĝelo respondis kaj diris al mi: Tio estas la kvar spiritoj de la ĉielo, kiuj eliras post sia starado antaŭ la Reganto de la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'La ĉaro kun la nigraj ĉevaloj iris al la lando norda, la blankaj iris post ili, kaj la makulitaj iris al la lando suda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'La brunaj eliris, kaj deziris trairi la teron; kaj li diris: Iru, trairu la teron; kaj ili trairis la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Kaj li kriis al mi, kaj diris al mi jene: Vidu, tiuj, kiuj eliris al la lando norda, kontentigis Mian spiriton en la lando norda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'Kaj aperis al mi vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Prenu de la forkondukitoj, de Ĥeldaj, de Tobija, kaj de Jedaja, kaj iru en la domon de Joŝija, filo de Cefanja, iru en la sama tago, kiam ili venos el Babel;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'prenu arĝenton kaj oron, kaj faru kronojn kaj metu sur la kapon de la ĉefpastro Josuo, filo de Jehocadak,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'kaj diru al li jene: Tiele diras la Eternulo Cebaot: Jen estas viro, kies nomo estas Markoto; li kreskos el sia loko kaj konstruos la templon de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Li konstruos la templon de la Eternulo, li ricevos gloron kaj sidos kaj regos sur sia trono; li estos ankaŭ pastro sur sia trono, kaj konsiliĝo paca estos inter ambaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Kaj tiuj kronoj estos ĉe Ĥelem, Tobija, Jedaja, kaj Ĥen, filo de Cefanja, kiel memoraĵo en la templo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Kaj malproksime loĝantoj venos kaj konstruos en la templo de la Eternulo, kaj vi ekscios, ke la Eternulo Cebaot sendis min al vi; kaj tio okazos, se vi obeados la voĉon de la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'En la kvara jaro de la reĝo Dario aperis vorto de la Eternulo al Zeĥarja, en la kvara tago de la naŭa monato, tio estas de Kislev;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'kiam Bet-El sendis Ŝareceron kaj Regem-Meleĥon kun iliaj akompanantoj, por preĝi antaŭ la Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'kaj demandi la pastrojn, kiuj estis en la domo de la Eternulo Cebaot, kaj la profetojn, jene: Ĉu ni devas plori en la kvina monato, kaj fasti, kiel ni faradis jam dum multe da jaroj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Tiam aperis al mi vorto de la Eternulo Cebaot, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Diru al la tuta popolo de la lando kaj al la pastroj jene: Kiam vi fastis kaj funebris en la kvina monato kaj en la sepa dum la sepdek jaroj-ĉu por Mi vi fastis? ĉu por Mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'Kaj kiam vi manĝas kaj trinkas, ĉu ne por vi mem vi manĝas kaj trinkas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Ĉu la esenco ne estas tiuj vortoj, kiujn la Eternulo proklamis per la antaŭaj profetoj, kiam Jerusalem estis priloĝata kaj bonstata, kaj la urboj ĉirkaŭ ĝi, la suda regiono kaj la malaltaĵo, estis priloĝataj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'Kaj aperis vorto de la Eternulo al Zeĥarja, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'Tiele diras la Eternulo Cebaot: Faru juĝon justan, ĉiu estu bona kaj kompatema al sia frato;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'vidvinon, orfon, fremdulon, kaj malriĉulon ne premu, kaj ne portu en via koro malbonajn intencojn kontraŭ via frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Sed ili ne volis atenti, ili deturnis de Mi sian flankon, kaj siajn orelojn ili ŝtopis, por ne aŭdi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'Sian koron ili faris kiel diamanta ŝtono, por ne obei la instruon, kaj la vortojn, kiujn la Eternulo Cebaot sendis en Sia spirito per la antaŭaj profetoj; pro tio aperis granda kolero de la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Kaj ĉar Li vokis, kaj ili ne aŭskultis, tial ankaŭ Mi ne aŭskultis, kiam ili vokis, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'Kaj Mi disblovis ilin inter ĉiujn naciojn, kiujn ili ne konis, kaj la lando post ili dezertiĝis tiel, ke neniu en ĝi iris tien aŭ reen; tiamaniere la ĉarman landon ili faris dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Kaj aperis vorto de la Eternulo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'Tiele diras la Eternulo Cebaot: Mi ekfervoris pri Cion per granda fervoro, kaj kun granda kolero Mi ekfervoris pri ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'Tiele diras la Eternulo: Mi revenos al Cion, Mi ekloĝos meze de Jerusalem, kaj Jerusalem estos nomata urbo de la vero, kaj la monto de la Eternulo Cebaot, monto sankta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'Tiele diras la Eternulo Cebaot: Denove sidos maljunuloj kaj maljunulinoj sur la placoj de Jerusalem, ĉiu kun bastono en la mano, pro profundeco de la aĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'Kaj la stratoj de la urbo pleniĝos de infanoj kaj infaninoj, ludantaj sur ĝiaj stratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'Tiele diras la Eternulo Cebaot: Se en la okuloj de la restintoj de la popolo en ĉi tiu tempo tio ŝajnas ne ebla, ĉu tio estas ne ebla ankaŭ en Miaj okuloj? diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'Tiele diras la Eternulo Cebaot: Jen Mi savos Mian popolon el la lando orienta kaj el la lando okcidenta;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'Mi venigos ilin, kaj ili ekloĝos interne de Jerusalem; kaj ili estos Mia popolo, kaj Mi estos ilia Dio, en vero kaj justo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'Tiele diras la Eternulo Cebaot: Fortigu viajn manojn, vi, kiuj aŭdas en ĉi tiuj tagoj ĉi tiujn vortojn el la buŝo de la profetoj, en la tago, kiam estas farata fondo por la konstruado de la domo de la Eternulo Cebaot, la templo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Ĉar antaŭ ĉi tiuj tagoj ne ekzistis rekompenco por la laboro de homo, nek por la laboro de bruto; nek la eliranto nek la eniranto povis esti trankvila antaŭ la malamiko; kaj Mi permesis al ĉiuj homoj ataki unu la alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Sed nun Mi estas por la restintoj de tiu popolo ne tia, kia Mi estis antaŭe, diras la Eternulo Cebaot;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'ĉar estos semo de paco: la vinberbranĉo donos siajn fruktojn, la tero donos siajn produktaĵojn, la ĉielo donos sian roson, kaj ĉion ĉi tion Mi posedigos al la restintoj de ĉi tiu popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'Kaj kiel vi, ho domo de Jehuda kaj domo de Izrael, estis malbeno inter la nacioj, tiel Mi savos vin, kaj vi fariĝos beno; ne timu do, kaj viaj manoj fortiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Ĉar tiele diras la Eternulo Cebaot: Tiel same, kiel Mi intencis plagi vin, kiam viaj patroj Min kolerigis, diras la Eternulo Cebaot, kaj Mi ne fordecidis tion,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'tiel Mi returnis Min kaj intencas nun fari bonon al Jerusalem kaj al la domo de Jehuda: ne timu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Jen estas la aferoj, kiujn vi devas fari: parolu veron unu al la alia, veran kaj pacan juĝon faru en viaj pordegoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'ne intencu en via koro malbonon unu kontraŭ la alia, kaj ne amu mensogan ĵuron; ĉar ĉion ĉi tion Mi malamas, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'Kaj aperis al mi vorto de la Eternulo Cebaot, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'Tiele diras la Eternulo Cebaot: La fastotago de la kvara monato kaj la fastotago de la kvina kaj la fastotago de la sepa kaj la fastotago de la deka estos por la domo de Jehuda ĝojo kaj gajeco kaj agrablaj festoj; tial amu la veron kaj la pacon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'Tiele diras la Eternulo Cebaot: Venados ankoraŭ popoloj kaj loĝantoj de multaj urboj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'kaj la loĝantoj de unu urbo venos al la loĝantoj de alia urbo, kaj diros: Ni iru rapide, por preĝi antaŭ la Eternulo kaj por turni nin al la Eternulo Cebaot; mi ankaŭ iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'Kaj venos multaj popoloj kaj potencaj nacioj, por serĉi la Eternulon Cebaot en Jerusalem kaj por preĝi antaŭ la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'Tiele diras la Eternulo Cebaot: En tiu tempo forte kaptos dek homoj el ĉialingvaj nacioj la baskon de Judo, kaj diros: Ni iros kun vi, ĉar ni aŭdis, ke Dio estas kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Profeta vorto de la Eternulo pri la lando Ĥadraĥ kaj pri ĝia ripozejo Damasko (ĉar la Eternulo rigardas ĉiujn homojn, kiel ĉiujn tribojn de Izrael),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'kaj pri Ĥamat, kiu havas sian limon apud ĝi, pri Tiro kaj Cidon, kiuj pensas, ke ili estas tre saĝaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Tiro konstruis al si fortikaĵon, kaj kolektis arĝenton kiel polvon, kaj oron kiel stratan koton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'sed jen la Sinjoro faros ĝin malriĉa kaj ĵetos en la maron ĝian remparon, kaj ĝi mem estos ekstermita de fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Aŝkelon tion vidos kaj ektimos, Gaza forte ektremos, ankaŭ Ekron, ĉar ĝia fido kovriĝos per honto; pereos la reĝo de Gaza, kaj Aŝkelon ne plu estos loĝata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'En Aŝdod loĝos fremduloj, kaj Mi ekstermos la fierecon de Filiŝtujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'Mi forigos la sangon el ĝia buŝo kaj la abomenindan manĝaĵon el ĝiaj dentoj, kaj ĝi mem fariĝos apartenaĵo de nia Dio, kaj ĝi estos distrikto de Judujo, kaj Ekron fariĝos kiel la Jebusidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'Mi gardos Mian domon kontraŭ la militistoj, por ke neniu trairu tien kaj reen, kaj ne plu venos al ĝi premanto; ĉar Mi rigardas ĝin nun per Miaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Ĝoju forte, ho filino de Cion, triumfu, ho filino de Jerusalem: jen via reĝo iras al vi; justa kaj helpema li estas, humila kaj rajdanta sur azeno, sur ido de azenino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Ĉar Mi ekstermos ĉarojn ĉe Efraim kaj ĉevalojn en Jerusalem, kaj ekstermita estos milita pafarko; li proklamos pacon al la nacioj, kaj lia regado estos de maro ĝis maro, de la Rivero ĝis la finoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'Kaj pro la sango de via interligo Mi eligos viajn malliberulojn el la senakva kavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Reiru al la fortikaĵo, vi, ligitaj de espero! ĉar hodiaŭ Mi sciigas, ke Mi redonos al vi duoble.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Mi streĉos al Mi Judujon kiel pafarkon, Mi armos Efraimon, Mi levos viajn filojn, ho Cion, kontraŭ viajn filojn, ho Grekujo, kaj Mi faros vin kiel glavo de heroo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'La Eternulo aperos super ili, Lia sago elflugos kiel fulmo, la Sinjoro, la Eternulo, ekblovos per trumpeto kaj paŝos en suda ventego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'La Eternulo Cebaot defendos ilin, kaj ili ekstermos, kaj ili piedpremos la ŝtonojn de la ŝtonĵetiloj; ili trinkos, kaj bruos kvazaŭ de vino; ili pleniĝos kiel porofera kaliko, kiel la anguloj de la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'Kaj savos ilin la Eternulo, ilia Dio, en tiu tempo, kiel la ŝafojn de Sia popolo; ĉar kiel ŝtonoj de krono ili brilos sur Lia tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Ĉar kiel granda estas Lia boneco, kaj kiel granda estas Lia beleco! Pano vigligos la junulojn, kaj mosto la junulinojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Petu de la Eternulo pluvon printempan; la Eternulo faros fulmojn, kaj donos abundan pluvon por ĉiuj kreskaĵoj sur la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'La domaj dioj parolas sensencaĵon, la antaŭdiristoj havas malverajn viziojn, rakontas mensogajn sonĝojn, kaj konsolas per vantaĵo; tial ili diskuras kiel ŝafoj, suferas pro tio, ke ili ne havas paŝtiston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Kontraŭ la paŝtistoj ekflamis Mia kolero, kaj la antaŭirantajn virkaprojn Mi punos; sed la Eternulo Cebaot vizitos Sian ŝafaron, la domon de Jehuda, kaj faros ĝin kiel ornamita ĉevalo en batalo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'El ĝi eliros la angula ŝtono, el ĝi la ĉefa stango, el ĝi la batala pafarko, el ĝi eliros ĉiuj regantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'Ili estos kiel forteguloj, kiuj piedpremas en batalo kvazaŭ koton sur la strato; kaj ili batalos, ĉar la Eternulo estos kun ili, kaj ili hontigos tiujn, kiuj sidas sur ĉevaloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'Mi fortigos la domon de Jehuda, Mi savos la domon de Jozef, kaj Mi enloĝigos ilin, ĉar Mi kompatas ilin. Kaj ili estos en tia stato, kvazaŭ Mi neniam ilin forlasis; ĉar Mi, la Eternulo, estas ilia Dio, kaj Mi aŭskultos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Efraim estos kiel fortegulo; kaj ilia koro estos gaja, kiel de vino; iliaj filoj vidos kaj ĝojos; ilia koro triumfos per la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Mi fajfos al ili kaj kunvenigos ilin, ĉar Mi elaĉetis ilin; kaj ili multiĝos, kiel ili multiĝis antaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'Mi semos ilin inter la popoloj, kaj en malproksimaj landoj ili memoros Min, kaj ili vivos kun siaj infanoj kaj revenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Mi revenigos ilin el la lando Egipta, Mi kolektos ilin el Asirio, Mi revenigos ilin en la landon Gileadan kaj sur Lebanonon, kaj ne troviĝos sufiĉe da loko por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Malfeliĉo trairos la maron, batos la ondojn de la maro, kaj sekiĝos ĉiuj profundaj lokoj de Nilo; malaltiĝos la fiereco de Asirio, kaj malaperos la sceptro de Egiptujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'Mi faros ilin forteguloj per la Eternulo, kaj en Lia nomo ili irados, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Malfermu, ho Lebanon, viajn pordojn, ke la fajro ekstermu viajn cedrojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Ĝemegu, ho cipreso, ĉar falis la cedro kaj la potenculoj estas ruinigitaj. Ĝemegu, ho kverkoj de Baŝan, ĉar falis la fortika arbaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Oni aŭdas ploradon de paŝtistoj, ĉar ilia belegaĵo estas ruinigita; oni aŭdas kriadon de junaj leonoj, ĉar forigita estas la beleco de Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Tiele diras la Eternulo, mia Dio: Paŝtu la buĉotajn ŝafojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'kiujn iliaj aĉetintoj mortigas, ne farante pekon, kaj iliaj vendintoj diras: Dank� al la Eternulo, mi riĉiĝis; kaj iliaj paŝtistoj ne bedaŭras ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Pro tio Mi ne plu indulgos la loĝantojn de la tero, diras la Eternulo; jen Mi transdonos la homojn ĉiun en la manon de lia proksimulo kaj en la manon de lia reĝo, kaj ili frapados la teron, kaj Mi ne savos el ilia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Kaj mi paŝtis la ŝafojn buĉotajn, la plej malfeliĉajn el la ŝafoj. Kaj mi prenis al mi du bastonojn, la unu mi nomis Afableco kaj la duan Ligilo; kaj mi paŝtis la ŝafojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'Kaj mi forigis tri paŝtistojn en unu monato; kaj deturnis sin de ili mia animo, kiel ankaŭ ilia animo deturnis sin de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Kaj mi diris: Mi vin ne paŝtos: la mortonta mortu, la pereonta pereu, kaj la ceteraj manĝu unu la karnon de la alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Kaj mi prenis mian bastonon Afableco kaj rompis ĝin, por detrui la interligon, kiun mi faris kun ĉiuj popoloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'kaj ĝi estis detruita en tiu tago. Kaj tiam la malfeliĉaj ŝafoj, kiuj atentadis min, eksciis, ke tio estas vorto de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Kaj mi diris al ili: Se plaĉas al vi, donu al mi mian laborpagon; se ne, tiam ne faru tion. Kaj ili pesis al mi kiel mian laborpagon tridek arĝentajn monerojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Kaj la Eternulo diris al mi: Ĵetu tion en la trezorejon; bela prezo, per kiu ili taksis Min! Kaj mi prenis la tridek arĝentajn monerojn kaj ĵetis ilin en la trezorejon de la domo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Kaj mi rompis mian duan bastonon Ligilo, por detrui la fratecon inter Jehuda kaj Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'Kaj la Eternulo diris al mi: Prenu al vi ankoraŭ la ilaron de paŝtisto malsaĝa;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'ĉar jen Mi starigos sur la tero paŝtiston, kiu ne serĉos la ŝafojn perdiĝintajn, ne zorgos pri la junaj, ne kuracos la malsanajn, ne nutros la sanajn, sed manĝos la viandon de la grasaj kaj disbatos iliajn hufojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Ve al la malsaĝa paŝtisto, kiu forlasas la ŝafojn! la glavo trafos lian brakon kaj lian dekstran okulon; lia brako velksekiĝos, kaj lia dekstra okulo tute perdos sian vidadon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Profeta vorto de la Eternulo pri Izrael. Diro de la Eternulo, kiu etendis la ĉielon, fondis la teron, kaj kreis la spiriton de la homo interne de li:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Jen Mi faros Jerusalemon freneziga kaliko por ĉiuj popoloj ĉirkaŭe, kaj eĉ por Judujo, kiam Jerusalem estos sieĝata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'En tiu tempo Mi faros Jerusalemon peza ŝtono por ĉiuj popoloj: ĉiuj, kiuj ĝin levos, faros al si vundojn; kaj kolektiĝos kontraŭ ĝi ĉiuj nacioj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'En tiu tempo, diras la Eternulo, Mi frapos ĉiun ĉevalon per rabio kaj ĝian rajdanton per frenezeco; kaj sur la domon de Jehuda Mi malfermos Miajn okulojn; ĉiujn ĉevalojn de la popoloj Mi frapos per blindeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Kaj la estroj de Judujo diros en sia koro: Mia forto estas la loĝantoj de Jerusalem, dank� al la Eternulo Cebaot, ilia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'En tiu tempo Mi faros la estrojn de Judujo kiel pato kun fajro inter ligno kaj kiel brulanta torĉo inter garboj, kaj ili formanĝos dekstre kaj maldekstre ĉiujn popolojn ĉirkaŭe; kaj Jerusalem estos denove priloĝata sur sia loko, en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Kaj antaŭe la Eternulo savos la tendojn de Judujo, por ke la gloro de la domo de David kaj la gloro de la loĝantoj de Jerusalem ne estu tro alta super Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'En tiu tempo la Eternulo defendos la loĝantojn de Jerusalem, kaj la plej malforta el ili estos en tiu tempo kiel David, kaj la domo de David estos kiel Dio, kiel anĝelo de la Eternulo antaŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'En tiu tempo Mi decidos ekstermi ĉiujn naciojn, kiuj atakas Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'Sed sur la domon de David kaj sur la loĝantojn de Jerusalem Mi verŝos spiriton de amo kaj de preĝoj; kaj ili rigardos tiun, kiun ili trapikis, kaj ili ploros pri li, kiel oni ploras pri solfilo, kaj ili malĝojos pri li, kiel oni malĝojas pri unuenaskito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'En tiu tempo estos granda plorado en Jerusalem, kiel la plorado en Hadadrimon en la valo de Megidon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'Ploros la lando, ĉiu familio aparte: la familio de la domo de David aparte, kaj iliaj edzinoj aparte; la familio de la domo de Natan aparte, kaj iliaj edzinoj aparte;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'la familio de la domo de Levi aparte, kaj iliaj edzinoj aparte; la familio de la Ŝimeiidoj aparte, kaj iliaj edzinoj aparte;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'ĉiuj ceteraj familioj ĉiu familio aparte, kaj iliaj edzinoj aparte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'En tiu tempo malfermiĝos por la domo de David kaj por la loĝantoj de Jerusalem fonto, por purigi sin de pekoj kaj de malpureco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'En tiu tempo, diras la Eternulo Cebaot, Mi ekstermos de la lando la nomojn de la idoloj, kaj ili ne plu estos rememorataj; ankaŭ la profetojn kaj la malpuran spiriton Mi forigos de la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'Se iu tiam diros profetaĵon, tiam lia patro kaj lia patrino, kiuj naskis lin, diros al li: Vi ne devas vivi, ĉar vi parolis malveraĵon en la nomo de la Eternulo; kaj lia patro kaj lia patrino, kiuj naskis lin, trapikos lin, kiam li profetos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'En tiu tempo ĉiu el la profetoj hontos pri sia vizio, kiam li volos profeti, kaj oni ne metos sur sin harkovritan mantelon por trompi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'sed ĉiu diros: Mi ne estas profeto, mi estas terkultivisto, ĉar al la tero mi alkutimiĝis de mia infaneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'Se oni diros al li: Kio estas ĉi tiuj vundoj sur viaj manoj? tiam li respondos: Oni batis min en la domo de miaj amantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Ho glavo, leviĝu kontraŭ Mian paŝtiston kaj kontraŭ Mian plej proksiman amikon, diras la Eternulo Cebaot; frapu la paŝtiston, por ke diskuru la ŝafoj; kaj Mi returnos Mian manon al la malgranduloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'Kaj sur la tuta tero, diras la Eternulo, du partoj estos ekstermitaj kaj pereos, kaj la tria parto restos sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'Kaj tiun trian parton Mi trairigos tra fajro, kaj refandos, kiel oni fandas arĝenton, kaj Mi elprovos ilin, kiel oni elprovas oron. Ili vokos Mian nomon, kaj Mi aŭskultos ilin, kaj Mi diros: Tio estas Mia popolo; kaj ili diros: La Eternulo estas nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Jen de la Eternulo venos tago, kiam oni dividos vian havaĵon meze de vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Mi kolektos ĉiujn naciojn milite kontraŭ Jerusalemon, kaj la urbo estos venkoprenita, la domoj estos detruitaj, la virinoj estos senhonorigitaj, duono de la urbo iros en kaptitecon, sed la cetera popolo ne estos ekstermita el la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Sed la Eternulo eliros kaj militos kontraŭ tiuj nacioj, kiel iam Li militis en tago de batalo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'Liaj piedoj en tiu tempo stariĝos sur la Monto de Olivoj, kiu estas antaŭ Jerusalem oriente; kaj la Monto de Olivoj disfendiĝos en la mezo en du partojn, de oriento ĝis okcidento, tiel, ke fariĝos tre granda valo, unu duono de la monto forŝoviĝos norden kaj la dua duono suden.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Kaj vi kuros en la valo inter Miaj montoj, ĉar la intermonta valo atingos ĝis Acel; vi kuros, kiel vi kuris de la tertremo en la tempo de Uzija, reĝo de Judujo; tiam venos la Eternulo, mia Dio, kune kun ĉiuj sanktuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'En tiu tago ne estos lumo, sed estos malvarmo kaj densa nebulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'Kaj tio estos tago sola, konata nur de la Eternulo, nek tago nek nokto; nur vespere montriĝos lumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'En tiu tago ekfluos viviga akvo el Jerusalem, duono de ĝi al la maro orienta kaj duono al la maro okcidenta; ĝi fluados en somero kaj en vintro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'Kaj la Eternulo estos Reĝo super la tuta tero; en tiu tempo la Eternulo estos sola, kaj Lia nomo estos sola.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'La tuta lando fariĝos ebenaĵo, de Geba ĝis Rimon, sude de Jerusalem; ĉi tiu altiĝos kaj staros sur sia loko, de la Pordego de Benjamen ĝis la loko de la unua pordego, ĝis la Pordego Angula, kaj de la turo de Ĥananel ĝis la reĝaj vinpremejoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'Kaj oni loĝos en ĝi, kaj anatemo ne plu ekzistos; kaj Jerusalem estos ekster ĉia danĝero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'Kaj tia estos la plago, per kiu la Eternulo frapos ĉiujn popolojn, kiuj batalis kontraŭ Jerusalem: ilia karno putros, kiam ili staros ankoraŭ sur siaj piedoj, iliaj okuloj putros en siaj kavoj, kaj ilia lango putros en ilia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'En tiu tempo estos inter ili granda tumulto, venanta de la Eternulo, kaj ĉiu kaptos la manon de sia proksimulo, kaj leviĝos lia mano kontraŭ lian proksimulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Eĉ Judujo militos kontraŭ Jerusalem, kaj oni kolektos la havaĵon de ĉiuj nacioj ĉirkaŭe, tre multe da oro, arĝento, kaj vestoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'Tia sama plago estos sur la ĉevaloj, muloj, kameloj, azenoj, kaj sur ĉiuj brutoj, kiuj estos en tiuj tendaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'Ĉiuj restintoj el ĉiuj nacioj, kiuj venis kontraŭ Jerusalemon, venados ĉiujare, por adorkliniĝi antaŭ la Reĝo, la Eternulo Cebaot, kaj por festi la feston de laŭboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'Se iu el la gentoj de la tero ne iros en Jerusalemon, por adorkliniĝi antaŭ la Reĝo, la Eternulo Cebaot, tiam ili ne havos pluvon super si.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'Se la gento Egipta, kiu ne havas pluvon, ne iros kaj ne venos, trafos ilin la plago, per kiu la Eternulo frapos tiujn naciojn, kiuj ne venos, por festi la feston de laŭboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Tio estos puno de Egiptujo, kaj puno de ĉiuj nacioj, se ili ne iros, por festi la feston de laŭboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'En tiu tempo sur la tintiloj de la ĉevaloj estos skribite: SANKTA AL LA ETERNULO; kaj la kaldronoj en la domo de la Eternulo estos kiel la kalikoj antaŭ la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'Kaj ĉiuj kaldronoj en Jerusalem kaj en Judujo estos sanktaj al la Eternulo Cebaot; kaj ĉiuj oferontoj venos kaj prenos el ili kaj kuiros en ili; kaj ne plu estos komercisto en la domo de la Eternulo Cebaot en tiu tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Profeta vorto de la Eternulo al Izrael per Malaĥi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Mi ekamis vin, diras la Eternulo. Vi demandas: En kio Vi nin ekamis? Ĉu Esav ne estas frato de Jakob? diras la Eternulo; tamen Mi ekamis Jakobon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'kaj Esavon mi malamis, kaj Mi dezertigis liajn montojn, kaj lian posedaĵon Mi donis al la ŝakaloj de la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Se la Edomidoj diras: Ni estas ruinigitaj, sed ni revenos kaj rekonstruos la ruinojn-la Eternulo Cebaot diras tiele: Ili konstruos, kaj Mi detruos, kaj oni nomos ilin lando de malpieco, kaj popolo, kontraŭ kiu la Eternulo koleras eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Viaj okuloj tion vidos, kaj vi diros: Granda estas la Eternulo super la limoj de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Filo respektas patron, kaj sklavo sian sinjoron; sed se Mi estas patro, kie estas la respekto al Mi? kaj se Mi estas sinjoro, kie estas la timo antaŭ Mi? diras la Eternulo Cebaot al vi, ho pastroj, kiuj malhonoras Mian nomon. Kaj vi diras: Per kio ni malhonoras Vian nomon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Vi alportas sur Mian altaron panon malpuran, kaj tamen vi diras: Per kio ni malpuriĝis antaŭ Vi? Per tio, ke vi diras: La tablo de la Eternulo estas senvalora.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Kaj kiam vi alportas oferon blindan, ĉu tio ne estas malbona? aŭ kiam vi alportas laman aŭ malsanan, ĉu tio ne estas malbona? Provu alporti ĝin al via regionestro-ĉu vi tiam plaĉos al li, kaj ĉu li akceptos vin favore? diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'Preĝu de nun al Dio, ke Li indulgu nin; se tio estas farita de viaj manoj, ĉu Li povas favore akcepti vin? diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Estus bone, se iu el vi ŝlosus la pordon, por ke vi ne bruligu vane fajron sur Mia altaro. Vi ne estas agrablaj al Mi, diras la Eternulo Cebaot; kaj donacon el via mano Mi ne akceptos favore.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Ĉar de la sunleviĝejo ĝis la sunsubirejo Mia nomo estos granda inter la nacioj, kaj sur ĉiu loko oni incensos kaj alportos oferojn al Mia nomo, oferojn purajn; ĉar granda estos Mia nomo inter la nacioj, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Sed vi malhonoras ĝin per tio, ke vi diras: La tablo de la Eternulo estas malsankta, kaj la manĝaĵo sur ĝi estas senvalora.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Kaj vi diras: Tio estas nur klopodoj! Kaj vi malŝatas tion, diras la Eternulo Cebaot, kaj vi alportas tion, kio estas ŝtelita, lama, aŭ malsana, kaj vi alportas ankaŭ tiaspecan farunoferon. Ĉu Mi povas favore akcepti tion el via mano? diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Malbenata estu la hipokritulo, kiu havas en sia brutaro sendifektan virbruton, sed, farinte sanktan promeson, li alportas ofere al la Sinjoro kriplaĵon; ĉar Mi estas Reĝo granda, diras la Eternulo Cebaot, kaj Mia nomo estas timata inter la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'Kaj nun, ho pastroj, al vi estas donata jena ordono:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Se vi ne obeos, kaj se vi ne atentos, ke vi donadu honoron al Mia nomo, diras la Eternulo Cebaot, tiam Mi sendos sur vin malbenon, Mi malbenos viajn benojn; jes, Mi tion malbenos pro tio, ke vi ne donas vian atenton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Jen Mi ĵetos insulton sur la semon ĉe vi, malpuraĵon Mi ĵetos sur viajn vizaĝojn, la malpuraĵon de viaj festoferoj, kaj ĝi algluiĝos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'Kaj vi scios, ke Mi sendis al vi ĉi tiun ordonon, por konservi Mian interligon kun Levi, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Mia interligo kun li estis por vivo kaj paco, kaj Mi donis ilin al li, por ke li timu Min, kaj li timis Min kaj respektegis Mian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Instruo de la vero estis en lia buŝo, kaj maljustaĵo ne troviĝis sur liaj lipoj; en paco kaj sincereco li iradis antaŭ Mi, kaj multajn li deturnis de peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Ĉar la lipoj de pastro devas konservi scion, kaj el lia buŝo oni devas serĉi instruon; ĉar li estas sendito de la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Sed vi forkliniĝis de la vojo, vi delogis multajn de la instruo, vi detruis la interligon kun Levi, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Tial Mi ankaŭ faris vin malestimataj kaj malaltigataj antaŭ la tuta popolo, pro tio, ke vi ne observas Miajn vojojn kaj estas personfavoraj en la aferoj de la leĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Ĉu ne unu patron ni ĉiuj havas? ĉu ne unu Dio nin kreis? kial ni perfidas unu la alian, malsanktigante la interligon de niaj patroj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Perfidis Jehuda, kaj abomenaĵo estas farita en Izrael kaj en Jerusalem; ĉar Jehuda malhonoris la sanktaĵon de la Eternulo per tio, ke li ekamis kaj edzinigis al si filinon de fremda dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Al tiu, kiu tion faras, la Eternulo ekstermos el la tendoj de Jakob majstron kaj disĉiplon, kaj ankaŭ tiun, kiu alportas donon al la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'Ankaŭ tion vi faras: vi kovras la altaron de la Eternulo per larmoj, plorado, kaj ĝemado tiel, ke Li jam ne povas rigardi la donojn nek akcepti ion agrable el via mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Vi diras: Kial? Tial, ke la Eternulo estas atestanto inter vi kaj la edzino de via juneco, kontraŭ kiu vi agis perfide, kvankam ŝi estas via kamaradino kaj via leĝa edzino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Tion ne faris eĉ seninfanulo, se en li restis spirito. Kion faris la seninfanulo? li petis de Dio idaron. Estu do singardaj en via spirito, kaj neniu agu perfide kontraŭ la edzino de sia juneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Kiu elmalamis ŝin kaj forpuŝas ŝin, diras la Eternulo, Dio de Izrael, tiu makulas sian veston per perfortaĵo, diras la Eternulo Cebaot: estu do singardaj en via spirito, kaj ne agu perfide.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Vi indignigis la Eternulon per viaj vortoj. Tamen vi diras: Per kio ni indignigis Lin? Per tio, ke vi diras: Ĉiu malbonaganto estas bona antaŭ la okuloj de la Eternulo, kaj tiajn Li favoras; aŭ: Kie estas la Dio de justeco?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Jen Mi sendos Mian anĝelon, kaj li preparos antaŭ Mi la vojon; kaj subite venos en Sian templon la Sinjoro, kiun vi serĉas; kaj la anĝelo de la interligo, kiun vi deziras, jen li iras, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Sed kiu eltenos la tagon de Lia veno? kaj kiu povos stari, kiam Li aperos? Ĉar Li estas kiel la fajro de fandisto, kaj kiel la sapo de la fulistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'Li sidiĝos, por refandi kaj purigi arĝenton, kaj Li purigos la idojn de Levi kaj refandos ilin kiel oron kaj arĝenton, por ke ili alportadu al la Eternulo la donojn kun pieco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Tiam al la Eternulo estos agrablaj la oferoj de Jehuda kaj de Jerusalem, kiel en la tempo antikva kaj kiel en la jaroj antaŭaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'Kaj Mi venos al vi, por juĝi; kaj Mi estos rapida atestanto kontraŭ la sorĉistoj kaj adultuloj, kontraŭ tiuj, kiuj ĵuras mensoge, kontraŭ tiuj, kiuj estas maljustaj en la pagado al dungito, al vidvino kaj al orfo, kaj kontraŭ tiuj, kiuj forklinas la rajton de fremdulo kaj Min ne timas, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Ĉar Mi, la Eternulo, ne ŝanĝiĝas; kaj vi, ho filoj de Jakob, ne neniiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'De post la tagoj de viaj patroj vi deturnis vin de Miaj leĝoj kaj ne observas ilin; revenu al Mi, kaj tiam Mi returnos Min al vi, diras la Eternulo Cebaot. Sed vi diras: En kio ni devas reveni?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Ĉu povas homo ruzi kontraŭ Dio? tamen vi ruzas kontraŭ Mi. Vi diras: En kio ni ruzas kontraŭ Vi? En la dekonaĵo kaj la oferdonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Sub la malbeno vi ruiniĝas, sed kontraŭ Mi vi ruzas, la tuta popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Alportu la tutan dekonaĵon en la provizejon, por ke estu manĝaĵo en Mia domo, kaj elprovu Min per tio, diras la Eternulo Cebaot, ĉu Mi ne malfermos al vi la aperturon de la ĉielo kaj ĉu Mi ne verŝos sur vin benon abundan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'Tiam Mi faros por vi malpermeson al la manĝeganto, ke li ne pereigu al vi la fruktojn de la tero kaj ne senfruktigu al vi la vinberbranĉojn sur la kampo, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'Kaj ĉiuj nacioj nomos vin feliĉaj, ĉar vi estos lando ravanta, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'Arogantaj estas kontraŭ Mi viaj vortoj, diras la Eternulo. Tamen vi diras: Kion ni parolas kontraŭ Vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Vi parolas: Vane ni servas al Dio: kian profiton ni havas, se ni plenumas Liajn preskribojn kaj se ni iradas senĝoje antaŭ la Eternulo Cebaot?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Tial ni diras, ke la malbonuloj estas feliĉaj, kaj la malpiuloj estas bone aranĝitaj; ili incitas Dion, sed restas sendifektaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Sed tiuj, kiuj timas la Eternulon, diras al si reciproke: La Eternulo atentas kaj aŭdas, kaj memorlibro estas skribata antaŭ Li pri tiuj, kiuj timas la Eternulon kaj respektas Lian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'Kaj ili estos Miaj, diras la Eternulo Cebaot, en la tago, kiam Mi aranĝos Mian apartan trezoron; kaj Mi korfavoros ilin, kiel homo korfavoras sian filon, kiu servas al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Kaj vi denove vidos la diferencon inter virtulo kaj malvirtulo, inter tiu, kiu servas al Dio, kaj tiu, kiu ne servas al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'Ĉar jen venos tago, ardanta kiel forno; tiam ĉiuj malhumiluloj kaj malbonaguloj estos kiel pajlo, kaj la venonta tago bruligos ilin tiel, diras la Eternulo Cebaot, ke ĝi ne restigos al ili radikon nek branĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'Sed por vi, kiuj respektas Mian nomon, leviĝos suno de justeco, kaj sanigo estos en ĝiaj radioj, kaj vi eliros kaj saltados, kiel bone nutritaj bovidoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'Kaj vi piedpremos la malpiulojn, ĉar ili estos polvo sub la plandoj de viaj piedoj en tiu tago, kiun Mi aranĝos, diras la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'Memoru la instruon de Mia servanto Moseo, kiun Mi donis al li sur Ĥoreb por la tuta Izrael, la leĝojn kaj preskribojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Jen Mi sendos al vi la profeton Elija, antaŭ ol venos la granda kaj timinda tago de la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'kaj li returnos la koron de la patroj al la infanoj, kaj la koron de la infanoj al iliaj patroj, por ke Mi, veninte, ne frapu la teron per anatemo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'La genealogia registro de Jesuo Kristo, filo de David, filo de Abraham.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Al Abraham naskiĝis Isaak, kaj al Isaak naskiĝis Jakob, kaj al Jakob naskiĝis Jehuda kaj liaj fratoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'kaj al Jehuda naskiĝis Perec kaj Zeraĥ el Tamar, kaj al Perec naskiĝis Ĥecron, kaj al Ĥecron naskiĝis Ram,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'kaj al Ram naskiĝis Aminadab, kaj al Aminadab naskiĝis Naĥŝon, kaj al Naĥŝon naskiĝis Salma,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'kaj al Salma naskiĝis Boaz el Raĥab, kaj al Boaz naskiĝis Obed el Rut, kaj al Obed naskiĝis Jiŝaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'kaj al Jiŝaj naskiĝis David, la reĝo. Kaj al David naskiĝis Salomono el la edzino de Urija,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'kaj al Salomono naskiĝis Reĥabeam, kaj al Reĥabeam naskiĝis Abija, kaj al Abija naskiĝis Asa,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'kaj al Asa naskiĝis Jehoŝafat, kaj al Jehoŝafat naskiĝis Joram, kaj al Joram naskiĝis Uzija,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'kaj al Uzija naskiĝis Jotam, kaj al Jotam naskiĝis Aĥaz, kaj al Aĥaz naskiĝis Ĥizkija,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'kaj al Ĥizkija naskiĝis Manase, kaj al Manase naskiĝis Amon, kaj al Amon naskiĝis Joŝija,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'kaj al Joŝija naskiĝis Jeĥonja kaj liaj fratoj, je la tempo de la transloĝiĝo en Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Kaj post la transloĝiĝo en Babelon, al Jeĥonja naskiĝis Ŝealtiel, kaj al Ŝealtiel naskiĝis Zerubabel,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'kaj al Zerubabel naskiĝis Abiud, kaj al Abiud naskiĝis Eljakim, kaj al Eljakim naskiĝis Azor,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'kaj al Azor naskiĝis Cadok, kaj al Cadok naskiĝis Aĥim, kaj al Aĥim naskiĝis Eliud,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'kaj al Eliud naskiĝis Eleazar, kaj al Eleazar naskiĝis Mattan, kaj al Mattan naskiĝis Jakob,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'kaj al Jakob naskiĝis Jozef, edzo de Maria, el kiu estis naskita Jesuo, kiu estas nomata Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Tial ĉiuj generacioj de Abraham ĝis David estas dek kvar generacioj, kaj de David ĝis la transloĝiĝo en Babelon dek kvar generacioj, kaj de la transloĝiĝo en Babelon ĝis la Kristo dek kvar generacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Kaj la naskiĝo de Jesuo Kristo estis tiamaniere: kiam lia patrino Maria estis fianĉinigita al Jozef, antaŭ ol ili kunvenis, ŝi troviĝis graveda per la Sankta Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Kaj ŝia edzo Jozef, estante justulo, kaj ne volante meti ŝin al publika malhonoro, volis ŝin sekrete forsendi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Sed kiam li pripensis tion, jen anĝelo de la Eternulo aperis al li en sonĝo, dirante: Jozef, filo de David, ne timu preni al vi vian edzinon Maria; ĉar tio, kio naskiĝos de ŝi, estas per la Sankta Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Kaj ŝi naskos filon; kaj vi nomos lin JESUO; ĉar li savos sian popolon de ĝiaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Kaj ĉio tio okazis, por ke plenumiĝu tio, kion la Eternulo parolis per la profeto, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, 'Jen virgulino gravediĝos kaj naskos filon, Kaj oni donos al li la nomon Emanuel; tio estas, Dio kun ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Kaj Jozef, leviĝinte el sia dormo, faris, kiel ordonis al li la anĝelo de la Eternulo, kaj prenis al si sian edzinon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'kaj li ne ekkonis ŝin, ĝis ŝi naskis filon; kaj li donis al li la nomon JESUO.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Kaj kiam Jesuo estis naskita en Bet-Leĥem de Judujo en la tempo de la reĝo Herodo, jen saĝuloj el la oriento venis al Jerusalem, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'Kie estas tiu, kiu estas naskita Reĝo de la Judoj? ĉar ni vidis lian stelon en la oriento, kaj venis, por adorkliniĝi al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Kaj kiam la reĝo Herodo tion aŭdis, li maltrankviliĝis, kaj la tuta Jerusalem kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Kaj kunveniginte ĉiujn ĉefpastrojn kaj skribistojn de la popolo, li demandis al ili, kie la Kristo devas naskiĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Kaj ili diris al li: En Bet-Leĥem de Judujo, ĉar per la profeto estas skribite jene:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, 'Kaj vi, ho Bet-Leĥem, lando de Judujo, Neniel estas plej malgranda inter la regantoj de Judujo; Ĉar el vi venos reganto, Kiu paŝtos Mian popolon Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Tiam Herodo sekrete venigis la saĝulojn, kaj precize sciiĝis de ili pri la tempo, kiam aperis la stelo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'Kaj li sendis ilin al Bet-Leĥem, dirante: Iru kaj elserĉu zorge pri la knabeto; kaj kiam vi lin trovos, sciigu al mi, por ke mi ankaŭ venu kaj adorkliniĝu al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Kaj aŭdinte la reĝon, ili ekvojiris; kaj jen la stelo, kiun ili vidis en la oriento, antaŭiris ilin, ĝis ĝi venis kaj staris super la loko, kie estis la juna knabeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Kaj vidante la stelon, ili ĝojis kun tre granda ĝojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Kaj veninte en la domon, ili vidis la knabeton kun lia patrino Maria, kaj adorkliniĝis al li; kaj malferminte siajn trezorojn, ili faligis sin kaj prezentis al li donacojn: oron kaj olibanon kaj mirhon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Kaj avertite de Dio en sonĝo, ke ili ne iru returne al Herodo, ili foriris per alia vojo al sia lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Kaj post ilia foriro jen anĝelo de la Eternulo aperis en sonĝo al Jozef, dirante: Leviĝu, kaj prenu la knabeton kaj lian patrinon, kaj forrapidu en Egiptujon, kaj restu tie, ĝis mi parolos al vi; ĉar Herodo serĉos la knabeton, por lin pereigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Kaj li leviĝis, kaj prenis la knabeton kaj lian patrinon nokte, kaj migris en Egiptujon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'kaj restis tie ĝis la morto de Herodo; por ke plenumiĝu tio, kion la Eternulo parolis per la profeto, dirante: El Egiptujo Mi vokis Mian filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Tiam Herodo, ekvidinte, ke li estas trompita de la saĝuloj, tre koleris; kaj sendinte, li mortigis ĉiujn knabojn en Bet-Leĥem kaj en ĉiuj ĝiaj ĉirkaŭaĵoj, havantajn du jarojn aŭ malpli, laŭ la tempo, pri kiu li precize sciiĝis de la saĝuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Tiam plenumiĝis tio, kio estis dirita per la profeto Jeremia, nome:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, 'Voĉo estas aŭdita en Rama, Ĝemado kaj maldolĉa plorado, Raĥel priploras siajn infanojn, Kaj ŝi ne volas konsoliĝi, ĉar ili forestas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Sed kiam Herodo mortis, jen anĝelo de la Eternulo aperis en sonĝo al Jozef en Egiptujo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'Leviĝu, kaj prenu la knabeton kaj lian patrinon, kaj iru en la landon de Izrael; ĉar mortis tiuj, kiuj atencis la vivon de la knabeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'Kaj li leviĝis, kaj prenis la knabeton kaj lian patrinon, kaj venis en la landon de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Sed kiam li aŭdis, ke Arĥelao reĝas en Judujo anstataŭ sia patro Herodo, li timis iri tien; kaj avertite de Dio en sonĝo, li fortiris sin en la regionojn de Galileo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'kaj venis al kaj loĝis en urbo nomata Nazaret, por ke plenumiĝu tio, kio estis dirita per la profetoj, ke li estos nomata Nazaretano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'En tiuj tagoj venis Johano, la Baptisto, predikante en la dezerto de Judujo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'kaj dirante: Pentu, ĉar alproksimiĝis la regno de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Ĉar li estas tiu, pri kiu estis dirite per la profeto Jesaja: Voĉo de krianto en la dezerto: Pretigu la vojon de la Eternulo, Rektigu Liajn irejojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Kaj tiu Johano havis sian vestaĵon el kamelaj haroj, kaj ledan zonon ĉirkaŭ siaj lumboj, kaj lia nutraĵo estis akridoj kaj sovaĝa mielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Tiam eliris al li Jerusalem kaj la tuta Judujo kaj la tuta ĉirkaŭaĵo de Jordan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'kaj ili estis baptitaj de li en la rivero Jordan, konfesante siajn pekojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Kaj vidante multajn el la Fariseoj kaj Sadukeoj venantajn al lia baptado, li diris al ili: Ho vipuridoj! kiu vin avertis forkuri de la venonta kolero?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Donu do fruktojn taŭgajn por pento;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'kaj ne pensu diri en vi: Ni havas Abrahamon kiel patron; ĉar mi diras al vi, ke Dio povas el ĉi tiuj ŝtonoj starigi idojn al Abraham.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Kaj jam la hakilo kuŝas ĉe la radiko de la arboj; tial ĉiu arbo, kiu ne donas bonan frukton, estas dehakata, kaj ĵetata en fajron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Mi ja vin baptas per akvo por pento; sed tiu, kiu venas post mi, estas pli potenca ol mi; liajn ŝuojn mi ne estas inda porti; li vin baptos per la Sankta Spirito kaj per fajro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'lia ventumilo estas en lia mano, kaj li elpurigos sian draŝejon, kaj li kolektos sian tritikon en la grenejon; sed la grenventumaĵon li bruligos per fajro neestingebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Tiam venis Jesuo el Galileo al Jordan al Johano, por esti baptata de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Sed tiu lin malakceptis, dirante: Mi bezonas esti baptata de vi, kaj ĉu vi venas al mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Sed Jesuo responde diris al li: Lasu do, ĉar tiel decas al ni plenumi ĉian justecon. Tiam li lasis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Kaj Jesuo, baptite, supreniris tuj el la akvo; kaj jen la ĉielo malfermiĝis, kaj li vidis la Spiriton de Dio malsuprenirantan kiel kolombo, kaj venantan sur lin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'kaj jen voĉo el la ĉielo, dirante: Ĉi tiu estas Mia Filo, la amata, en kiu Mi havas plezuron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Tiam Jesuo estis kondukita supren de la Spirito en la dezerton, por esti tentata de la diablo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'Kaj fastinte kvardek tagojn kaj kvardek noktojn, li poste malsatis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Kaj la tentanto venis, kaj diris al li: Se vi estas Filo de Dio, ordonu, ke tiuj ŝtonoj fariĝu panoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Sed responde li diris: Estas skribite: Ne per la pano sole vivas homo, sed per ĉiu vorto, kiu eliras el la buŝo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Poste la diablo portis lin en la sanktan urbon, kaj starigis lin sur la tegmenta pinto de la templo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'kaj diris al li: Se vi estas Filo de Dio, ĵetu vin malsupren, ĉar estas skribite: Al Siaj anĝeloj Li ordonos pri vi, Kaj sur la manoj ili vin portos, Por ke vi ne falpuŝiĝu sur ŝtono per via piedo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Jesuo diris al li: Ankaŭ estas skribite: Ne provu la Eternulon, vian Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Denove la diablo portis lin al monto tre alta, kaj montris al li ĉiujn regnojn de la mondo kaj ilian gloron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'kaj diris al li: Ĉion tion mi donos al vi, se vi faligos vin kaj adorkliniĝos al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Tiam Jesuo diris al li: Foriru, Satano! ĉar estas skribite: Al la Eternulo, via Dio, vi adorkliniĝu, kaj al Li sola vi servu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Tiam la diablo forlasis lin, kaj jen anĝeloj venis kaj servadis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Kaj aŭdinte, ke Johano estas arestita, li foriris en Galileon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'kaj lasinte Nazareton, li venis al kaj loĝis en Kapernaum apudmara, en la limoj de Zebulun kaj Naftali;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'por ke plenumiĝu tio, kio estis dirita per la profeto Jesaja, nome:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, 'Lando de Zebulun kaj lando de Naftali, Laŭvoje de la maro, transe de Jordan, Galileo de la nacioj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'La popolo, sidanta en mallumo, Ekvidis grandan lumon, Kaj al homoj, sidantaj en lando de ombra morto, ekbrilis lumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'De tiam Jesuo komencis prediki, kaj diri: Pentu, ĉar la regno de la ĉielo alproksimiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Kaj piedirante apud la maro de Galileo, li vidis du fratojn, Simonon, kiu estis nomata Petro, kaj Andreon, lian fraton, ĵetantajn reton en la maron, ĉar ili estis fiŝkaptistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'Kaj li diris al ili: Venu post mi, kaj mi faros vin kaptistoj de homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Kaj ili tuj forlasis la retojn, kaj sekvis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'Kaj antaŭenirinte de tie, li vidis aliajn du fratojn, Jakobon, filon de Zebedeo, kaj Johanon, lian fraton, en la ŝipeto kun ilia patro Zebedeo, riparantajn siajn retojn; kaj li vokis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'Kaj ili tuj forlasis la ŝipeton kaj sian patron, kaj sekvis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'Kaj Jesuo trairis tra la tuta Galileo, instruante en iliaj sinagogoj, kaj predikante la evangelion de la regno, kaj kuracante ĉian malsanon kaj ĉian malfortaĵon inter la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'Kaj lia famo disvastiĝis en la tuta Sirio; kaj oni alkondukis al li ĉiujn malsanulojn, malfortigitajn de diversaj malsanoj kaj turmentoj, demonhavantojn, epilepsiulojn, kaj paralizulojn, kaj li resanigis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'Kaj grandaj homamasoj lin sekvis el Galileo kaj Dekapolis kaj Jerusalem kaj Judujo kaj el trans Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Kaj vidinte la homamasojn, li supreniris sur la monton, kaj kiam li sidiĝis, liaj disĉiploj venis al li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'kaj malferminte la buŝon, li instruis ilin, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'Feliĉaj estas la malriĉaj en spirito, ĉar ilia estas la regno de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Feliĉaj estas la plorantaj, ĉar ili konsoliĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Feliĉaj estas la humilaj, ĉar ili heredos la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Feliĉaj estas tiuj, kiuj malsatas kaj soifas justecon, ĉar ili satiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Feliĉaj estas la kompatemaj, ĉar ili ricevos kompaton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Feliĉaj estas la kore puraj, ĉar ili vidos Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Feliĉaj estas la pacigantoj, ĉar filoj de Dio ili estos nomataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Feliĉaj estas tiuj, kiuj estas persekutitaj pro justeco, ĉar ilia estas la regno de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Feliĉaj estas vi, kiam oni vin riproĉos kaj persekutos kaj false vin kalumnios pro mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Ĝoju kaj raviĝu, ĉar via rekompenco estos granda en la ĉielo; ĉar tiel oni persekutis la profetojn, kiuj estis antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Vi estas la salo de la tero; sed se la salo sengustiĝis, per kio ĝi estos salita? ĝi jam taŭgas por nenio, krom por esti elĵetita kaj piedpremita de homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Vi estas la lumo de la mondo. Urbo starigita sur monto ne povas esti kaŝita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Kiam oni bruligas lampon, oni metas ĝin ne sub grenmezurilon, sed sur la lampingon; kaj ĝi lumas sur ĉiujn, kiuj estas en la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Tiel same via lumo lumu antaŭ homoj, por ke ili vidu viajn bonajn farojn, kaj gloru vian Patron, kiu estas en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Ne pensu, ke mi venis, por detrui la leĝon aŭ la profetojn; mi venis, ne por detrui, sed por plenumi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Vere mi diras al vi: Ĝis la ĉielo kaj la tero forpasos, nek unu joto nek unu streketo forpasos de la leĝo, ĝis ĉio plenumiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Tial, kiu malobservos unu el ĉi tiuj plej malgrandaj ordonoj kaj tiel instruos homojn, tiu estos nomata la plej malgranda en la regno de la ĉielo; sed kiu faros ilin kaj instruos, tiu estos nomata granda en la regno de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Ĉar mi diras al vi, ke se via justeco ne superos la justecon de la skribistoj kaj la Fariseoj, vi tute ne eniros en la regnon de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Vi aŭdis, ke estas dirite al la antikvuloj: Ne mortigu, kaj kiu mortigos, tiu estos en danĝero de juĝado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'sed mi diras al vi, ke kiu koleras kontraŭ sia frato, tiu estos en danĝero de juĝado; kaj kiu diros al sia frato: Raka, tiu estos en danĝero de la sinedrio; kaj kiu diros: Malsaĝulo, tiu estos en danĝero de Gehena de fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Tial, se vi prezentas vian oferon ĉe la altaro, kaj tie memoras, ke via frato havas ion kontraŭ vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'lasu tie vian oferon antaŭ la altaro, kaj foriru, unue paciĝu kun via frato, kaj poste venu kaj prezentu vian oferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Konsentu rapide kun via kontraŭulo, dum vi estas kun li sur la vojo, por ke la kontraŭulo ne transdonu vin al la juĝisto, kaj la juĝisto al la subulo, kaj por ke vi ne estu ĵetita en malliberejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'Vere mi diras al vi, ke vi neniel eliros el tie, ĝis vi pagos la lastan kodranton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Vi aŭdis, ke estas dirite: Ne adultu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'sed mi diras al vi, ke ĉiu, kiu rigardas virinon, por deziri ŝin, jam adultis je ŝi en sia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Kaj se via dekstra okulo faligas vin, elŝiru kaj forĵetu ĝin; ĉar estus pli bone por vi, se unu el viaj membroj pereus, ol se via tuta korpo estus ĵetita en Gehenan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'Kaj se via dekstra mano faligas vin, detranĉu kaj forĵetu ĝin; ĉar estus pli bone por vi, se unu el viaj membroj pereus, ol se via tuta korpo irus en Gehenan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Estas ankaŭ dirite: Kiu forsendos sian edzinon, tiu donu al ŝi eksedzigan leteron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'sed mi diras al vi, ke ĉiu, kiu forsendas sian edzinon, krom pro malĉasteco, igas ŝin adulti; kaj kiu edziĝos kun forsenditino, tiu adultas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Plue, vi aŭdis, ke estas dirite al la antikvuloj: Ne rompu ĵurojn, sed plenumu viajn ĵurojn antaŭ la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'sed mi diras al vi: Tute ne ĵuru; nek per la ĉielo, ĉar ĝi estas la trono de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'nek per la tero, ĉar ĝi estas la benketo de Liaj piedoj; nek per Jerusalem, ĉar ĝi estas urbo de la granda Reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Nek ĵuru per via kapo, ĉar vi ne povas fari eĉ unu haron blanka aŭ nigra.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Sed via parolo estu: Jes, jes, ne, ne; ĉio ekster tio estas el malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Vi aŭdis, ke estas dirite: Okulon pro okulo, kaj denton pro dento;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'sed mi diras al vi: Ne rezistu al malbono; sed al tiu, kiu frapas vian dekstran vangon, turnu ankaŭ la alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'Kaj se iu deziras procesi kontraŭ vi, por forpreni vian tunikon, lasu lin preni ankaŭ vian mantelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'Kaj se iu devigas vin iri unu mejlon, iru kun li du.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Donu al tiu, kiu petas de vi; kaj ne deturnu vin de tiu, kiu deziras prunti de vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Vi aŭdis, ke estas dirite: Amu vian proksimulon, kaj malamu vian malamikon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'sed mi diras al vi: Amu viajn malamikojn, kaj preĝu por viaj persekutantoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'por ke vi estu filoj de via Patro, kiu estas en la ĉielo; ĉar Li levas Sian sunon sur la malbonulojn kaj bonulojn, kaj sendas pluvon sur la justulojn kaj la maljustulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Ĉar se vi amas tiujn, kiuj amas vin, kian rekompencon vi havas? ĉu ne tion saman faras eĉ la impostistoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'Kaj se vi salutas nur sole viajn fratojn, kion ekstran vi faras? ĉu ne tion saman faras eĉ la nacianoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Estu do perfektaj, kiel ankaŭ via ĉiela Patro estas perfekta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Gardu vin, ke vi ne faru vian justaĵon antaŭ homoj, por esti alrigardataj de ili; alie vi ne havas rekompencon ĉe via Patro, kiu estas en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Tial, kiam vi donos almozon, ne sonigu trumpeton antaŭ vi, kiel faras la hipokrituloj en la sinagogoj kaj sur la stratoj, por havi gloron ĉe homoj. Vere mi diras al vi: Ili jam ricevas sian rekompencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Sed kiam vi donas almozon, ne lasu vian maldekstran manon scii, kion faras via dekstra;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'por ke via almozo estu en sekreto; kaj via Patro, kiu vidas en sekreto, vin rekompencos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'Kaj kiam vi preĝas, ne estu kiel la hipokrituloj; ĉar ili amas preĝi, starante en la sinagogoj kaj ĉe la anguloj de la stratoj, por montri sin al homoj. Vere mi diras al vi: Ili jam ricevas sian rekompencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Sed vi, kiam vi preĝas, eniru en vian ĉambreton, kaj ŝlosinte vian pordon, preĝu al via Patro, kiu estas en sekreto; kaj via Patro, kiu vidas en sekreto, vin rekompencos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Kaj dum via preĝado ne vante ripetadu, kiel la nacianoj; ĉar ili supozas, ke ili estos aŭskultitaj pro sia multvorteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Ne estu similaj al ili; ĉar via Patro scias, kion vi bezonas, antaŭ ol vi petas de Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Vi do preĝu jene: Patro nia, kiu estas en la ĉielo, Via nomo estu sanktigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Venu Via regno, plenumiĝu Via volo, kiel en la ĉielo, tiel ankaŭ sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Nian panon ĉiutagan donu al ni hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'Kaj pardonu al ni niajn ŝuldojn, kiel ankaŭ ni pardonas al niaj ŝuldantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'Kaj ne konduku nin en tenton, sed liberigu nin de la malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Ĉar se vi pardonas al homoj iliajn kulpojn, via Patro ĉiela ankaŭ pardonos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Sed se vi ne pardonas al homoj iliajn kulpojn, via Patro ankaŭ ne pardonos viajn kulpojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Kaj kiam vi fastas, ne estu kiel la hipokrituloj, kun malĝoja mieno; ĉar ili malbeligas sian vizaĝon, por ke al homoj ili ŝajnu fasti. Vere mi diras al vi: Ili jam ricevas sian rekompencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Sed fastante, vi oleu vian kapon kaj lavu vian vizaĝon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'por ke vi ne al homoj ŝajnu fasti, sed al via Patro en sekreto; kaj via Patro, kiu vidas en sekreto, vin rekompencos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Ne provizu al vi trezorojn sur la tero, kie tineo kaj rusto konsumas, kaj kie ŝtelistoj trafosas kaj ŝtelas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'sed provizu al vi trezorojn en la ĉielo, kie nek tineo nek rusto konsumas, kaj kie ŝtelistoj nek trafosas nek ŝtelas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'ĉar kie estas via trezoro, tie estos ankaŭ via koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'La lampo de la korpo estas la okulo; se do via okulo estas sendifekta, via tuta korpo estos luma.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Sed se via okulo estas malbona, via tuta korpo estos malluma. Se do la lumo en vi estas mallumo, kiel densa estas la mallumo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Neniu povas esti sklavo por du sinjoroj; ĉar aŭ li malamos unu kaj amos la alian, aŭ li aliĝos al unu kaj malestimos la alian. Vi ne povas servi al Dio kaj al Mamono!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'Tial mi diras al vi: Ne zorgu pri via vivo, kion vi manĝu, aŭ kion vi trinku; nek pri via korpo, kion vi surmetu. Ĉu la vivo ne estas pli ol nutraĵo, kaj la korpo pli ol vestaĵo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Rigardu la birdojn de la ĉielo, ke ili ne semas, nek rikoltas, nek kolektas en grenejojn, kaj via Patro ĉiela ilin nutras. Ĉu vi ne multe pli valoras ol ili?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'Kaj kiu el vi per zorgado povas aldoni unu ulnon al sia staturo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'Kaj kial vi zorgas pri vestaĵo? Pripensu la liliojn de la kampo, kiel ili kreskas; ili ne laboras, nek ŝpinas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'tamen mi diras al vi, ke eĉ Salomono en sia tuta gloro ne estis ornamita, kiel unu el ĉi tiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Sed se Dio tiel vestas la kampan herbaĵon, kiu ekzistas hodiaŭ, kaj morgaŭ estos ĵetata en fornon, kiom pli certe Li vestos vin, ho malgrandfiduloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Tial ne zorgu, dirante: Kion ni manĝu? aŭ: Kion ni trinku? aŭ: Kion ni surmetu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Ĉar pri ĉio tio serĉas la nacianoj; ĉar via Patro ĉiela scias, ke vi bezonas ĉion tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Sed celu unue Lian regnon kaj Lian justecon, kaj ĉio tio estos aldonita al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Tial ne zorgu pri la morgaŭa tago, ĉar la morgaŭa tago zorgos pri si mem. Sufiĉa por la tago estas ĝia propra malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Ne juĝu, por ke vi ne estu juĝataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Ĉar per kia juĝo vi juĝos, per tia vi estos juĝitaj; kaj per kia mezuro vi mezuros, per tia oni mezuros al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Kaj kial vi rigardas la lignereton en la okulo de via frato, kaj ne pripensas la trabon en via okulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Kiel vi diros al via frato: Lasu min eltiri la lignereton el via okulo; kaj jen la trabo en via propra okulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Hipokritulo, eligu unue la trabon el via okulo, kaj tiam vi klare vidos, por eltiri la lignereton el la okulo de via frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Ne donu sanktaĵon al la hundoj, nek ĵetu viajn perlojn antaŭ la porkoj; por ke ili ne premu ilin sub la piedoj, nek poste, sin turninte, disŝiru vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Petu, kaj estos donite al vi; serĉu, kaj vi trovos; frapu, kaj estos malfermite al vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'ĉar ĉiu petanto ricevas, kaj la serĉanto trovas, kaj al la frapanto estos malfermite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Plue, kiu homo el vi, kies filo de li petos panon, donos al li ŝtonon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'aŭ se li petos fiŝon, donos al li serpenton?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Se do vi, estante malbonaj, scias doni bonajn donacojn al viaj filoj, kiom pli certe via Patro, kiu estas en la ĉielo, donos bonaĵojn al tiuj, kiuj petas de Li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Ĉion ajn do, kion vi deziras, ke la homoj faru al vi, vi ankaŭ faru al ili; ĉar ĉi tio estas la leĝo kaj la profetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Eniru tra la mallarĝa pordo, ĉar larĝa estas la pordego kaj vasta estas la vojo kondukanta al la pereo, kaj multaj tra ĝi eniras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Ĉar mallarĝa estas la pordo kaj malvastigita estas la vojo kondukanta al la vivo, kaj malmultaj ĝin trovas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Gardu vin kontraŭ la falsaj profetoj, kiuj venas al vi en ŝafaj feloj, sed interne estas rabemaj lupoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Per iliaj fruktoj vi konos ilin. Ĉu el dornarbetoj oni kolektas vinberojn, aŭ el kardoj figojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Tiel ĉiu bona arbo donas bonajn fruktojn, sed putra arbo donas malbonajn fruktojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Bona arbo ne povas doni malbonajn fruktojn, nek putra arbo doni bonajn fruktojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Ĉiu arbo, kiu ne donas bonan frukton, estas dehakata kaj ĵetata en fajron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Tial per iliaj fruktoj vi konos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Ne ĉiu, kiu diras al mi: Sinjoro, Sinjoro, eniros en la regnon de la ĉielo; sed tiu, kiu plenumas la volon de mia Patro, kiu estas en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Multaj diros al mi en tiu tago: Sinjoro, Sinjoro, ĉu ni ne profetis en via nomo, kaj en via nomo elpelis demonojn, kaj en via nomo faris multajn potencaĵojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'Kaj tiam mi konfesos al ili: Mi neniam konis vin; foriĝu de mi, vi farantoj de maljusteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Tial ĉiu, kiu aŭdas ĉi tiujn miajn parolojn kaj plenumas ilin, estos komparata al saĝa viro, kiu konstruis sian domon sur roko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'kaj falis pluvo, kaj venis inundoj, kaj blovis ventoj, kaj albatis tiun domon, kaj ĝi ne falis; ĉar ĝi estis fondita sur roko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'Kaj ĉiu, kiu aŭdas ĉi tiujn miajn parolojn kaj ne plenumas ilin, estos komparata al viro malsaĝa, kiu konstruis sian domon sur la sablo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'kaj falis pluvo, kaj venis inundoj, kaj blovis ventoj, kaj sin ĵetis sur tiun domon, kaj ĝi falis; kaj granda estis ĝia falo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'Kaj kiam Jesuo finis tiujn parolojn, la homamasoj miregis pri lia instruado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'ĉar li instruis ilin, kiel havanta aŭtoritaton, kaj ne kiel iliaj skribistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Kaj kiam li malsupreniris de la monto, lin sekvis grandaj homamasoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'Kaj jen venis al li leprulo kaj adorkliniĝis al li, dirante: Sinjoro, se vi volas, vi povas min purigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Kaj li etendis la manon kaj tuŝis lin, dirante: Mi volas; estu purigita. Kaj tuj lia lepro estis purigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Kaj Jesuo diris al li: Zorgu, ke vi diru al neniu. Sed iru, montru vin al la pastro, kaj oferu la donon, kiun Moseo ordonis, por atesto al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Kaj kiam li eniris en Kapernaumon, venis al li centestro, petante lin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'kaj dirante: Sinjoro, mia knabo kuŝas paralizulo en la domo, kaj terure suferas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Kaj li diris al li: Mi venos, kaj sanigos lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Kaj la centestro responde diris: Sinjoro, mi ne estas inda, ke vi venu sub mian tegmenton; sed nur parolu vorte, kaj mia knabo saniĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Ĉar mi ankaŭ estas homo sub aŭtoritato, havante soldatojn sub mi; kaj mi diras al ĉi tiu: Iru; kaj li iras; kaj al alia: Venu; kaj li venas; kaj al mia sklavo: Faru ĉi tion; kaj li ĝin faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Kaj kiam Jesuo tion aŭdis, li miris, kaj diris al la sekvantoj: Vere mi diras al vi, ke ĉe neniu en Izrael mi trovis tiom da fido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Kaj mi diras al vi, ke multaj venos el la oriento kaj la okcidento, kaj sidiĝos kun Abraham kaj Isaak kaj Jakob en la regno de la ĉielo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'sed la filoj de la regno estos elĵetitaj en la eksteran mallumon; tie estos la plorado kaj la grincado de dentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'Kaj Jesuo diris al la centestro: Iru; kiel vi kredis, tiel estu farite al vi. Kaj lia knabo saniĝis en tiu sama horo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Kaj kiam Jesuo venis en la domon de Petro, li vidis lian bopatrinon kuŝanta, malsana de febro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'Kaj li tuŝis ŝian manon, kaj la febro forlasis ŝin; kaj ŝi leviĝis kaj servis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Kaj kiam vesperiĝis, oni venigis al li multajn demonhavantojn; kaj li elpelis la spiritojn per vorto, kaj sanigis ĉiujn malsanulojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'por ke plenumiĝu tio, kio estis dirita per la profeto Jesaja, nome: Li mem prenis niajn malfortaĵojn kaj portis niajn malsanojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Kaj kiam Jesuo vidis ĉirkaŭ si grandan homamason, li ordonis transiri al la alia bordo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Kaj venis unu skribisto, kaj diris al li: Majstro, mi vin sekvos, kien ajn vi iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Kaj Jesuo diris al li: La vulpoj havas kavojn, kaj la birdoj de la ĉielo havas ripozejojn; sed la Filo de homo ne havas, kie kuŝigi sian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Kaj alia el la disĉiploj diris al li: Sinjoro, permesu al mi unue iri kaj enterigi mian patron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Sed Jesuo diris al li: Sekvu min, kaj lasu la mortintojn enterigi siajn mortintojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'Kaj kiam li eniris en ŝipeton, liaj disĉiploj lin sekvis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'Kaj jen okazis granda malsereno sur la maro, tiel ke la ŝipeto estis kovrita de la ondoj; sed li dormadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'Kaj ili venis, kaj vekis lin, dirante: Sinjoro, savu; ni pereas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'Kaj li diris al ili: Kial vi estas timemaj, ho malgrandfiduloj? Tiam li leviĝis, kaj admonis la ventojn kaj la maron; kaj fariĝis granda sereno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Kaj la homoj miregis, dirante: Kia estas ĉi tiu, ke eĉ la ventoj kaj la maro lin obeas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'Kaj kiam li venis al la alia bordo, en la landon de la Gadaranoj, lin renkontis du demonhavantoj, elvenante el inter la tomboj, tre furiozaj, tiel, ke neniu povis preterpasi per tiu vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'Kaj jen ili kriis, dirante: Kio estas inter ni kaj vi, ho Filo de Dio? ĉu vi venis ĉi tien, por turmenti nin antaŭ la tempo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Kaj malproksime de ili estis granda grego da porkoj, paŝtiĝantaj tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Kaj la demonoj petegis lin, dirante: Se vi elpelos nin, forsendu nin en la gregon da porkoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'Kaj li diris al ili: Iru. Kaj elirinte, ili foriris en la porkojn; kaj jen kuris la tuta grego malsupren de la krutaĵo en la maron, kaj pereis en la akvoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Kaj la paŝtistoj forkuris kaj iris en la urbon, kaj rakontis ĉion, kaj pri la demonhavintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'Kaj jen la tuta urbo elvenis renkonte al Jesuo; kaj vidinte lin, ili petegis, ke li transiru el iliaj limoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Kaj enirinte en ŝipeton, li transiris, kaj venis en sian propran urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'Kaj jen oni alportis al li paralizulon, kuŝantan sur lito; kaj Jesuo, vidinte ilian fidon, diris al la paralizulo: Kuraĝu, filo, viaj pekoj estas pardonitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Kaj jen iuj el la skribistoj diris en si: Ĉi tiu blasfemas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Kaj Jesuo, eksciante iliajn pensojn, diris: Kial vi pensas malbonon en viaj koroj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Ĉar kio estas pli facila, diri: Viaj pekoj estas pardonitaj; aŭ diri: Leviĝu kaj piediru?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Sed por ke vi sciu, ke la Filo de homo havas aŭtoritaton sur la tero pardoni pekojn-tiam li diris al la paralizulo: Leviĝu, prenu vian liton, kaj iru al via domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Kaj li leviĝis, kaj iris al sia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'Kaj vidinte tion, la homamasoj timis, kaj gloris Dion, kiu donis tian aŭtoritaton al homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'Kaj Jesuo, forpasante de tie, vidis viron nomatan Mateo, sidantan ĉe la impostejo; kaj li diris al li: Sekvu min. Kaj li stariĝis, kaj sekvis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Kaj dum li sidis ĉe manĝo en la domo, jen multaj impostistoj kaj pekuloj venis kaj sidiĝis tie kun Jesuo kaj liaj disĉiploj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'Kaj vidinte tion, la Fariseoj diris al liaj disĉiploj: Kial via instruisto manĝas kun impostistoj kaj pekuloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Kaj aŭdinte tion, li diris: Ne la sanuloj bezonas kuraciston, sed la malsanuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Sed iru, kaj lernu, kion signifas ĉi tio: Mi deziras bonfaradon, sed ne oferon; ĉar mi venis, por alvoki ne justulojn, sed pekulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Tiam alvenis al li la disĉiploj de Johano, dirante: Kial ni kaj la Fariseoj fastas ofte, sed viaj disĉiploj ne fastas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'Kaj Jesuo diris al ili: Ĉu la filoj de la edziĝejo povas malĝoji, dum la fianĉo estas kun ili? Sed venos tagoj, kiam la fianĉo estos prenita for de ili, kaj tiam ili fastos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Kaj neniu alkudras flikaĵon el nefulita drapo sur malnovan veston, ĉar la plenigaĵo forprenas de la vesto, kaj pli malbona ŝiraĵo fariĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Ankaŭ oni ne enverŝas novan vinon en malnovajn felsakojn; alie la felsakoj krevos, kaj la vino elfluos, kaj la felsakoj detruiĝos; sed oni enverŝas novan vinon en novajn felsakojn, kaj ambaŭ konserviĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Dum li tion parolis al ili, jen unu estro, alveninte, adorkliniĝis al li, dirante: Mia filino ĵus mortis; sed venu kaj metu vian manon sur ŝin, kaj ŝi vivos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Kaj Jesuo leviĝis, kaj sekvis lin, kaj ankaŭ liaj disĉiploj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'Kaj jen virino, kiu jam dek du jarojn havis sangofluon, venis malantaŭ lin kaj tuŝis la randon de lia mantelo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'ĉar ŝi diris en si: Se mi nur tuŝos lian mantelon, mi estos sanigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Kaj Jesuo, sin turninte kaj vidinte ŝin, diris: Kuraĝu, filino; via fido vin savis. Kaj en tiu sama horo la virino resaniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Kaj Jesuo, veninte en la domon de la estro kaj vidinte la flutistojn kaj la homamason bruantajn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'diris: Foriru; ĉar la knabineto ne mortis, sed dormas. Kaj ili mokridis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Sed kiam la homamaso estis elpelita, li eniris, kaj prenis ŝian manon; kaj la knabineto leviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'Kaj disiris tiu famo en tiun tutan regionon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'Kaj kiam Jesuo foriris de tie, du blinduloj sekvis lin, kriante kaj dirante: Kompatu nin, ho filo de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Kaj kiam li venis en la domon, la blinduloj alvenis al li, kaj Jesuo diris al ili: Ĉu vi kredas, ke mi povas fari ĉi tion? Ili diris al li: Jes, Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Tiam li tuŝis iliajn okulojn, dirante: Estu al vi laŭ via fido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'Kaj iliaj okuloj malfermiĝis. Kaj Jesuo severe ordonis al ili: Gardu vin, ke neniu tion sciu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Sed elirinte, ili disvastigis lian famon en tiu tuta regiono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Kaj dum ili eliris, jen oni alportis al li mutan demonhavanton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'Kaj kiam la demono estis elpelita, la mutulo parolis; kaj la homamasoj miris, dirante: Neniam tia afero estas vidita en Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Sed la Fariseoj diris: Per la estro de la demonoj li elpelas demonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'Kaj Jesuo trairis ĉiujn urbojn kaj vilaĝojn, instruante en iliaj sinagogoj, kaj predikante la evangelion de la regno, kaj sanigante ĉian malsanon kaj ĉian malfortaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Kaj vidante la homamasojn, li estis kortuŝita pri ili, ĉar ili estis mizerigitaj kaj disigitaj, kiel ŝafoj ne havantaj paŝtiston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Tiam li diris al siaj disĉiploj: La rikolto ja estas abunda, sed la laborantoj estas malmultaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Petu do la Sinjoron de la rikolto, ke Li sendu laborantojn en Sian rikolton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Kaj li alvokis al si la dek du disĉiplojn, kaj donis al ili aŭtoritaton super malpuraj spiritoj, por elpeli ilin, kaj por sanigi ĉian malsanon kaj ĉian malfortaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Kaj la nomoj de la dek du apostoloj estas jenaj: la unua, Simon, kiu estis nomata Petro, kaj lia frato Andreo, Jakobo, filo de Zebedeo, kaj lia frato Johano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Filipo kaj Bartolomeo, Tomaso, kaj Mateo, impostisto, Jakobo, filo de Alfeo, kaj Tadeo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Simon, la Fervorulo, kaj Judas Iskariota, kiu ankaŭ perfidis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Ĉi tiujn dek du Jesuo forsendis, kaj ordonis al ili, dirante: Ne iru sur vojon de nacianoj, kaj ne eniru en urbon de Samarianoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'sed iru prefere al la perditaj ŝafoj de la domo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Kaj dum vi iros, prediku, dirante: La regno de la ĉielo alproksimiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Malsanulojn sanigu, mortintojn levu, leprulojn purigu, demonojn elpelu: donace vi ricevis, donace donu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Ne provizu oron nek arĝenton nek kupron en viajn zonojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'nek saketon por vojaĝo, nek du tunikojn, nek ŝuojn, nek bastonon; ĉar la laboranto meritas sian nutraĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'Kaj en iu ajn urbo aŭ vilaĝo, en kiun vi eniros, demandu, kiu tie estas inda; kaj loĝu tie, ĝis vi foriros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'Kaj venante en la domon, salutu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'Kaj se la domo estas inda, via paco venu sur ĝin; sed se ĝi ne estas inda, via paco revenu al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'Kaj se iu ne akceptos vin, nek aŭskultos viajn vortojn, tiam forirante el tiu domo aŭ tiu urbo, deskuu la polvon de viaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Vere mi diras al vi: Pli elporteble estos por la lando de Sodom kaj Gomora en la tago de juĝado, ol por tiu urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Jen mi forsendas vin kiel ŝafojn meze de lupoj; estu do prudentaj kiel serpentoj, kaj simplaj kiel kolomboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Sed gardu vin kontraŭ la homoj; ĉar ili transdonos vin al sinedrioj, kaj en siaj sinagogoj ili vin skurĝos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'kaj antaŭ provincestrojn kaj reĝojn vi estos kondukitaj pro mi, por atesto al ili kaj al la nacianoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Sed kiam ili transdonos vin, ne zorgu, kiel aŭ kion vi parolos; ĉar estos donita al vi en tiu horo tio, kion vi parolos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Ĉar parolas ne vi, sed la Spirito de via Patro parolas en vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Kaj frato transdonos fraton al morto, kaj patro filon; kaj infanoj ribelos kontraŭ gepatroj kaj mortigos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'Kaj vi estos malamataj de ĉiuj pro mia nomo; sed kiu persistos ĝis la fino, tiu estos savita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Kaj kiam oni vin persekutos en unu urbo, forkuru en alian; ĉar vere mi diras al vi: Vi ne trairos la urbojn de Izrael, antaŭ ol venos la Filo de homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Disĉiplo ne estas super sia instruanto, nek sklavo super sia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Sufiĉas por la disĉiplo, ke li estu kiel lia instruanto, kaj la sklavo, kiel lia sinjoro. Se oni nomis la dommastron Baal-Zebub, kiom pli ankaŭ liajn domanojn!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Tial ne timu ilin, ĉar nenio estas kovrita, kio ne estos elmontrita, kaj nenio kaŝita, kio ne estos konigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Kion mi diras al vi en la mallumo, tion parolu en la lumo; kaj kion vi aŭdas en la orelon, tion proklamu sur la tegmentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'Kaj ne timu tiujn, kiuj mortigas la korpon, sed ne povas mortigi la animon; sed prefere timu Tiun, kiu povas pereigi kaj animon kaj korpon en Gehena.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Ĉu oni ne vendas du paserojn por asaro? tamen unu el ili ne falos teren sen via Patro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'sed eĉ la haroj de via kapo estas ĉiuj kalkulitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Tial ne timu; vi valoras pli, ol multaj paseroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Ĉiun do, kiu konfesos min antaŭ homoj, mi ankaŭ konfesos antaŭ mia Patro, kiu estas en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'Sed kiu malkonfesos min antaŭ homoj, tiun mi ankaŭ malkonfesos antaŭ mia Patro, kiu estas en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Ne supozu, ke mi venis, por enkonduki pacon sur la teron; mi venis, por enkonduki ne pacon, sed glavon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Ĉar mi venis, por kontraŭmeti viron kontraŭ lian patron, kaj filinon kontraŭ ŝian patrinon, kaj bofilinon kontraŭ ŝian bopatrinon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'kaj la domanoj de homo estos liaj malamikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Kiu amas patron aŭ patrinon pli ol min, tiu ne estas inda je mi; kaj kiu amas filon aŭ filinon pli ol min, tiu ne estas inda je mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'Kaj kiu ne prenas sian krucon kaj sekvas post mi, tiu ne estas inda je mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Kiu trovas sian vivon, tiu ĝin perdos; kaj kiu perdas sian vivon pro mi, tiu ĝin trovos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Kiu vin akceptas, tiu min akceptas; kaj kiu min akceptas, tiu akceptas Tiun, kiu min sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Kiu akceptas profeton en la nomo de profeto, tiu ricevos rekompencon de profeto; kaj kiu akceptas justulon en la nomo de justulo, tiu ricevos rekompencon de justulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'Kaj kiu trinkigos nur tason da malvarma akvo al unu el ĉi tiuj malgranduloj en la nomo de disĉiplo, vere mi diras al vi, tiu neniel perdos sian rekompencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Kaj kiam Jesuo finis siajn ordonojn al siaj dek du disĉiploj, li foriris de tie, por instrui kaj prediki en iliaj urboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Kaj kiam Johano aŭdis en la malliberejo pri la faroj de Kristo, li sendis per siaj disĉiploj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'por diri al li: Ĉu vi estas la venonto, aŭ ĉu ni atendu alian?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Kaj Jesuo responde diris al ili: Iru kaj sciigu al Johano tion, kion vi aŭdas kaj vidas:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'blinduloj ricevas vidpovon, kaj lamuloj marŝas, lepruloj estas purigitaj, kaj surduloj aŭdas, kaj mortintoj leviĝas, kaj al malriĉuloj evangelio estas predikata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'Kaj feliĉa estas ĉiu, kiu ne falpuŝiĝas pro mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Kaj kiam ili foriris, Jesuo komencis paroli al la homamasoj pri Johano: Kion vi eliris en la dezerton por rigardi? ĉu junkon skuatan de la vento?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Sed kion vi eliris por vidi? ĉu homon mole vestitan? Jen tiuj, kiuj portas molajn vestojn, troviĝas en domoj de reĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Sed kion vi eliris por vidi? ĉu profeton? Jes, mi diras al vi, kaj multe pli ol profeton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Ĉar li estas tiu, pri kiu estas skribite: Jen Mi sendos Mian anĝelon antaŭ via vizaĝo, Kaj li preparos antaŭ vi vian vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Vere mi diras al vi: Inter naskitoj de virinoj ne aperis iu pli granda ol Johano, la Baptisto; tamen tiu, kiu estas nur malgranda en la regno de la ĉielo, estas pli granda ol li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Kaj de post la tagoj de Johano, la Baptisto, ĝis nun, la regno de la ĉielo estas perfortata, kaj perfortuloj kaptas ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Ĉar ĉiuj profetoj kaj la leĝo profetis ĝis Johano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'Kaj se vi volas tion ricevi, tiu estas Elija, kiu estis venonta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Kiu havas orelon por aŭdi, tiu aŭdu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Sed al kio mi komparu ĉi tiun generacion? Ĝi similas al infanoj, kiuj sidas sur la placoj, kaj vokas al la ceteraj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'dirante: Ni flutis al vi, kaj vi ne dancis; ni lamentis, kaj vi ne ploris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Ĉar venis Johano, nek manĝante nek trinkante, kaj ili diras: Li havas demonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'La Filo de homo venis, manĝante kaj trinkante, kaj ili diras: Jen manĝegulo kaj vindrinkulo, amiko de impostistoj kaj pekuloj! Kaj la saĝeco estas pravigita de siaj faroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Tiam li komenci riproĉi la urbojn, en kiuj estis faritaj la plej multaj el liaj potencaj faroj; ĉar ili ne pentis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, 'Ve al vi, Ĥorazin! Ve al vi, Betsaida! Ĉar se en Tiro kaj Cidon estus faritaj tiuj potencaĵoj, kiuj estas faritaj en vi, antaŭ longe ili jam pentus en sakaĵo kaj cindro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Tamen mi diras al vi: Estos pli elporteble por Tiro kaj Cidon en la tago de juĝado, ol por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'Kaj vi, Kapernaum! ĉu vi estos altigita ĝis la ĉielo? vi malsupreniĝos ĝis Hades; ĉar se en Sodom estus faritaj tiuj potencaĵoj, kiuj estas faritaj en vi, ĝi restus ĝis hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Tamen mi diras al vi: Estos pli elporteble por la lando de Sodom en la tago de juĝado, ol por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'En tiu tempo Jesuo ekparolis kaj diris: Mi Vin gloras, ho Patro, Sinjoro de la ĉielo kaj la tero, ke tion Vi kaŝis for de saĝuloj kaj prudentuloj, kaj malkaŝis al infanoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'jes, Patro, ĉar tiel estis bone antaŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Ĉio estas transdonita al mi de mia Patro, kaj neniu konas la Filon krom la Patro, nek iu konas la Patron krom la Filo, kaj tiu, al kiu la Filo volas malkaŝi Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Venu al mi ĉiuj, kiuj estas laborantaj kaj ŝarĝitaj, kaj mi vin ripozigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Metu sur vin mian jugon, kaj lernu ĉe mi, ĉar mi estas milda kaj korhumila; kaj vi trovos ripozon por viaj animoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'Ĉar mia jugo estas facila, kaj mia ŝarĝo estas malpeza.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'En tiu tempo Jesuo iris en sabato tra la grenkampoj, kaj liaj disĉiploj malsatis, kaj komencis deŝiri spikojn, kaj manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Sed la Fariseoj, vidinte, diris al li: Jen viaj disĉiploj faras tion, kio ne estas permesata en sabato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Sed li diris al ili: Ĉu vi ne legis, kion faris David, kiam malsatis li kaj liaj kunuloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'ke li eniris en la domon de Dio, kaj manĝis la panojn de propono, kiujn manĝi ne estis permesate al li, nek al liaj kunuloj, sed nur al la pastroj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Kaj ĉu vi ne legis en la leĝo, kiel en sabato la pastroj en la templo profanas la sabaton kaj estas senkulpaj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Sed mi diras al vi, ke alestas ĉi tie io pli granda ol la templo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Sed se vi komprenus, kion signifas ĉi tio: Mi deziras bonfaradon, sed ne oferon; vi ne kondamnus la senkulpajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Ĉar la Filo de homo estas sinjoro de la sabato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'Kaj li foriris de tie, kaj eniris en ilian sinagogon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'kaj jen viro, havanta manon velkintan. Kaj oni demandis al li, dirante: Ĉu estas permesate sanigi en sabato? por ke ili povu lin akuzi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Kaj li diris al ili: Kiu el vi, havanta unu ŝafon, se ĝi falos en fosaĵon en sabato, ne ekprenos kaj levos ĝin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Kiom do viro superas ŝafon! Tial estas permesate bonfari en sabato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Tiam li diris al la viro: Etendu vian manon. Kaj ĉi tiu etendis ĝin, kaj ĝi tute resaniĝis kiel la alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Sed la Fariseoj eliris, kaj konsiliĝis kontraŭ li, kiamaniere lin pereigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Kaj Jesuo, eksciante, foriris de tie, kaj multaj lin sekvis; kaj li sanigis ilin ĉiujn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'kaj admonis ilin, ke ili ne konatigu lin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'por ke plenumiĝu tio, kio estis dirita per la profeto Jesaja, nome:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, 'Jen estas Mia servanto, kiun Mi elektis, Mia amata, en kiu Mia animo havas plezuron. Mi metos Mian Spiriton sur lin; Kaj li proklamos justecon al la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Li ne disputados, nek laŭte krios; Kaj oni ne aŭdos sur la stratoj lian voĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Kanon rompetitan li ne rompos, Kaj meĉon senfajriĝantan li ne estingos, Ĝis li elsendos juĝon por venko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'Kaj al lia nomo esperos la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Tiam oni kondukis al li demonhavanton, blindan kaj mutan; kaj li sanigis lin, tiel ke la mutulo parolis kaj vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'Kaj miris ĉiuj homamasoj, kaj diris: Ĉu ĉi tiu estas la filo de David?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Sed la Fariseoj, aŭdinte, diris: Ĉi tiu ne elpelas demonojn krom per Baal-Zebub, estro de la demonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Kaj sciante iliajn pensojn, li diris al ili: Ĉiu regno dividita kontraŭ si dezertiĝas, kaj ĉiu urbo aŭ domo dividita kontraŭ si ne starados;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'kaj se Satano elpelas Satanon, li estas dividita kontraŭ si; kiel do staros lia regno?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'Kaj se mi per Baal-Zebub elpelas demonojn, per kiu viaj filoj elpelas ilin? tial ili estos viaj juĝantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Sed se mi per la Spirito de Dio elpelas demonojn, tiam la regno de Dio estas veninta sur vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Kaj kiel oni povas eniri en la domon de la fortulo kaj trarabi liajn posedaĵojn, se unue li ne ligos la fortulon? kaj poste li trarabos lian domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Kiu ne estas kun mi, tiu estas kontraŭ mi; kaj kiu ne kolektas kun mi, tiu disĵetas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Tial mi diras al vi: Ĉia peko kaj ĉia blasfemo estos pardonita el homoj; sed la blasfemo kontraŭ la Spirito ne estos pardonita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'Kaj al iu, kiu parolos vorton kontraŭ la Filo de homo, tio estos pardonita; sed al iu, kiu parolos kontraŭ la Sankta Spirito, tio ne estos pardonita en ĉi tiu mondo, nek en la venonta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Aŭ faru la arbon bona kaj ĝian frukton bona, aŭ faru la arbon malbona kaj ĝian frukton malbona; ĉar la arbo estas konata per la frukto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Ho vipuridoj! kiel vi povas paroli bonaĵojn, estante malbonaj? ĉar el la abundo de la koro la buŝo parolas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'La bona homo el sia bona trezoro elmetas bonaĵojn; kaj la malbona homo el sia malbona trezoro elmetas malbonaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Kaj mi diras al vi, ke pro ĉiu senutila vorto, kiun homoj parolos, ili donos respondon en la tago de juĝado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Ĉar laŭ viaj vortoj vi estos pravigitaj, kaj laŭ viaj vortoj vi estos kondamnitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Tiam iuj el la skribistoj kaj Fariseoj respondis al li, dirante: Majstro, ni deziras vidi signon de vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'Sed li respondis kaj diris al ili: Malbona kaj adultema generacio serĉas signon; kaj neniu signo estos donita al ĝi krom la signo de la profeto Jona;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'ĉar kiel Jona estis tri tagojn kaj tri noktojn en la ventro de la marmonstro, tiel la Filo de homo estos tri tagojn kaj tri noktojn en la koro de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Viroj Nineveanoj staros en la juĝado kun ĉi tiu generacio, kaj kondamnos ĝin; ĉar ili pentis pro la predikado de Jona; kaj jen iu pli granda ol Jona estas ĉi tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'La reĝino de la sudo leviĝos en la juĝado kun ĉi tiu generacio, kaj kondamnos ĝin; ĉar ŝi venis el la finoj de la tero, por aŭskulti la saĝon de Salomono; kaj jen iu pli granda ol Salomono estas ĉi tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Sed kiam la malpura spirito eliras el homo, ĝi trairas tra senakvaj lokoj, serĉante ripozon, sed ne trovas ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Tiam ĝi diras: Mi reiros al mia domo, el kie mi eliris. Kaj alveninte, ĝi trovas ĝin vakanta, balaita, kaj ornamita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Tiam ĝi iras, kaj kunprenas al si sep aliajn spiritojn pli malbonajn ol ĝi mem, kaj ili eniras kaj loĝas tie; kaj la fina stato de tiu homo fariĝas pli malbona, ol la unua. Tiel estos ankaŭ al ĉi tiu malbona generacio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Dum li ankoraŭ parolis al la homamasoj, jen lia patrino kaj liaj fratoj staris ekstere, dezirantaj paroli kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'Kaj iu diris al li: Jen via patrino kaj viaj fratoj staras ekstere, dezirantaj paroli kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'Sed li responde diris al tiu, kiu parolis al li: Kiu estas mia patrino? kaj kiuj estas miaj fratoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'Kaj etendinte la manon al siaj disĉiploj, li diris: Jen mia patrino kaj miaj fratoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Ĉar kiu ajn faros la volon de mia Patro, kiu estas en la ĉielo, tiu estas mia frato kaj mia fratino kaj mia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'En tiu tago Jesuo eliris el la domo kaj sidiĝis apud la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'Kaj kolektiĝis al li grandaj homamasoj, tiel ke li eniris en ŝipeton, kaj sidis; kaj la tuta homamaso staris sur la marbordo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'Kaj li multe parolis al ili per paraboloj, dirante: Jen semisto eliris, por semi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'kaj dum li semis, iuj semoj falis apud la vojo, kaj la birdoj venis kaj formanĝis ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'kaj aliaj falis sur ŝtonajn lokojn, kie ili ne havis multe da tero; kaj tuj ili ekkreskis, ĉar ili ne havis profundecon de tero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'kaj kiam la suno leviĝis, ili brulsekiĝis, kaj ĉar ili ne havis radikon, ili forvelkis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Kaj aliaj falis inter dornojn, kaj la dornoj kreskis kaj sufokis ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'kaj aliaj falis sur la bonan teron, kaj donis frukton, jen centoble, jen sesdekoble, jen tridekoble.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Kiu havas orelojn, tiu aŭdu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Kaj la disĉiploj venis, kaj diris al li: Kial vi parolas al ili per paraboloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Kaj li respondis kaj diris al ili: Al vi estas donite scii la misterojn de la regno de la ĉielo, sed al ili ne estas donite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Ĉar kiu ajn havas, al tiu estos donite, kaj li havos abundon; sed kiu ajn ne havas, for de tiu estos prenita eĉ tio, kion li havas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Tial mi parolas al ili per paraboloj; ĉar vidante, ili ne rimarkas, kaj aŭdante, ili ne aŭdas nek komprenas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'Kaj por ili plenumiĝis tiu profetaĵo de Jesaja, kiu diras: Aŭdante, vi aŭdos, sed ne komprenos; Kaj vidante, vi vidos, sed ne rimarkos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Ĉar la koro de tiu popolo grasiĝis, Kaj iliaj oreloj aŭdas malklare, Kaj siajn okulojn ili fermis; Por ke ili ne vidu per siaj okuloj, Kaj ne aŭdu per siaj oreloj, Kaj ne komprenu per sia koro, Kaj ne rekonvertiĝu, Kaj ke Mi ne sanigu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Sed feliĉaj estas viaj okuloj, ĉar ili vidas; kaj viaj oreloj, ĉar ili aŭdas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Vere mi diras al vi, ke multaj profetoj kaj justuloj deziris vidi tion, kion vi vidas, sed ili ne vidis; kaj aŭdi tion, kion vi aŭdas, sed ili ne aŭdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Vi do aŭdu la parabolon de la semisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Kiam iu aŭdas la vorton de la regno kaj ne komprenas ĝin, tiam venas la malbonulo, kaj forprenas tion, kio estas semita en lia koro. Ĉi tiu estas la ricevinta semon apud la vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Kaj tiu, kiu ricevis semon sur la ŝtonaj lokoj, estas tiu, kiu aŭdas la vorton kaj tuj kun ĝojo akceptas ĝin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'sed li ne havas radikon en si, sed restas nur portempe, kaj kiam venas sufero aŭ persekuto pro la vorto, tuj li falpuŝiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'Kaj kiu ricevis semon inter la dornoj, estas tiu, kiu aŭdas la vorton; sed la zorgoj de la mondo kaj la trompo de riĉo sufokas la vorton, kaj li fariĝas senfrukta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Kaj kiu ricevis semon sur la bona tero, estas tiu, kiu aŭdas la vorton kaj komprenas ĝin; kaj tiu ja portas frukton, kaj donas, jen centoble, jen sesdekoble, jen tridekoble.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Alian parabolon li proponis al ili, dirante: La regno de la ĉielo similas al homo, kiu semis bonan semon en sia kampo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'sed dum homoj dormis, lia malamiko venis kaj semis lolon meze de la tritiko, kaj foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Kaj kiam la trunketo kreskis kaj donis frukton, tiam aperis ankaŭ la lolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Kaj la sklavoj de la dommastro venis, kaj diris al li: Sinjoro, ĉu vi ne semis bonan semon en via kampo? De kie do ĝi havas lolon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'Kaj li diris al ili: Iu malamiko faris tion. Kaj la sklavoj diris al li: Ĉu vi do volas, ke ni iru kaj kolektu ĝin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'Sed li diris: Ne; por ke, kolektante la lolon, vi ne elradikigu ankaŭ la tritikon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Lasu al ambaŭ kreski kune ĝis la rikolto; kaj en la tempo de la rikolto mi diros al la rikoltistoj: Kolektu unue la lolon, kaj ligu ĝin en faskojn, por bruligi ĝin; sed kolektu la tritikon en mian grenejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Alian parabolon li proponis al ili, dirante: La regno de la ĉielo similas al sinapa semeto, kiun viro prenis kaj semis en sia kampo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'ĝi vere estas pli malgranda ol ĉiuj semoj, sed kreskinte, ĝi estas pli granda ol la legomoj, kaj fariĝas arbo, tiel ke venas la birdoj de la ĉielo kaj loĝas en ĝiaj branĉoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Alian parabolon li parolis al ili: La regno de la ĉielo similas al fermentaĵo, kiun virino prenis kaj kaŝis en tri mezurojn da faruno, ĝis la tuto fermentis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Ĉion tion parolis Jesuo per paraboloj al la homamasoj, kaj sen parabolo li parolis nenion al ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'por ke plenumiĝu tio, kio estis dirita per la profeto, nome: Mi malfermos per sentenco mian buŝon; Mi eldiros enigmojn el tempo antikva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Tiam forsendinte la homamasojn, li venis en la domon; kaj liaj disĉiploj venis al li, dirante: Klarigu al ni la parabolon pri la lolo de la kampo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'Kaj responde li diris: Tiu, kiu semas la bonan semon, estas la Filo de homo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'kaj la kampo estas la mondo; kaj la bonaj semoj estas la filoj de la regno; kaj la lolo estas la filoj de la malbonulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'kaj la malamiko, kiu ilin semis, estas la diablo; kaj la rikolto estas la fino de la mondaĝo; kaj la rikoltistoj estas anĝeloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Kiel do la lolo estas kolektita kaj bruligita per fajro, tiel estos ĉe la fino de la mondaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'La Filo de homo elsendos siajn anĝelojn, kaj ili kolektos el lia regno ĉiun falpuŝilon, kaj ĉiujn, kiuj faras maljustecon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'kaj ĵetos ilin en la fornon de fajro; tie estos la plorado kaj la grincado de dentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Tiam la justuloj brilos kiel la suno en la regno de sia Patro. Kiu havas orelojn, tiu aŭdu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'La regno de la ĉielo similas al kaŝita en kampo trezoro, kiun viro trovis kaj kaŝis, kaj pro ĝojo li iras kaj vendas ĉion, kion li posedas, kaj aĉetas tiun kampon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Cetere, la regno de la ĉielo similas al komercisto, serĉanta belajn perlojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'kaj trovinte unu multevaloran perlon, li iris kaj vendis ĉion, kion li posedis, kaj aĉetis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Plue, la regno de la ĉielo similas al reto, kiu estis ĵetita en la maron kaj kolektis el ĉiu speco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'kaj kiun, kiam ĝi pleniĝis, oni suprentiris al la marbordo; kaj sidiĝinte, ili kolektis la bonajn en ujojn, sed la malbonajn ili ĵetis eksteren.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Tiel estos en la fino de la mondaĝo: la anĝeloj eliros, kaj apartigos la malbonulojn el inter la justuloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'kaj ĵetos ilin en la fornon de fajro; tie estos la plorado kaj la grincado de dentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Ĉu vi komprenis ĉion tion? Ili diris al li: Jes.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'Kaj li diris al ili: Tial ĉiu skribisto, disĉipligita en la regnon de la ĉielo, similas al dommastro, kiu elportas el sia trezorejo objektojn novajn kaj malnovajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'Kaj kiam Jesuo finis tiujn parabolojn, li foriris de tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'Kaj veninte en sian patrujon, li instruis ilin en ilia sinagogo, tiel ke ili miris, kaj diris: De kie ĉi tiu viro havas tian saĝecon kaj la potencaĵojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Ĉu ĉi tiu ne estas la filo de la ĉarpentisto? ĉu lia patrino ne estas nomata Maria? kaj liaj fratoj Jakobo kaj Joses kaj Simon kaj Judas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'Kaj ĉu liaj fratinoj ne estas ĉiuj ĉe ni? De kie do li ĉion tion havas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'Kaj ili ofendiĝis pro li. Sed Jesuo diris al ili: Profeto ne estas sen honoro, krom en sia patrujo kaj en sia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'Kaj pro ilia nekredemo li faris tie ne multajn potencaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'En tiu tempo la tetrarĥo Herodo aŭdis la famon pri Jesuo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'kaj diris al siaj servantoj: Tiu estas Johano, la Baptisto; li leviĝis el la mortintoj, kaj tial tiuj potencaĵoj energias en li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Ĉar Herodo jam arestis Johanon kaj ligis lin kaj metis lin en malliberejon pro Herodias, kiu estis edzino de lia frato Filipo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'Ĉar Johano diris al li: Ne decas, ke vi havu ŝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Kaj dezirante mortigi lin, li timis la popolon, ĉar oni opiniis lin profeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Sed kiam venis la naskotaga festo de Herodo, la filino de Herodias dancis en la mezo, kaj plaĉis al Herodo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'Tiam li ĵure promesis doni al ŝi ion ajn, kion ŝi petos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Kaj ŝi, instigite de sia patrino, diris: Donu al mi ĉi tie sur plado la kapon de Johano, la Baptisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Kaj la reĝo malĝojis; tamen pro siaj ĵuroj kaj pro la kunmanĝantoj li ordonis doni ĝin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'kaj sendinte, li senkapigis Johanon en la malliberejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'Kaj oni alportis lian kapon sur plado, kaj donis ĝin al la knabino, kaj ŝi alportis ĝin al sia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Kaj liaj disĉiploj venis kaj forportis la korpon kaj enterigis ĝin, kaj ili iris kaj rakontis tion al Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Kaj Jesuo, aŭdinte, foriris de tie en ŝipeto al dezerta loko aparte; kaj la homamasoj, aŭdinte, sekvis lin, piedirante el la urboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Kaj li elvenis, kaj vidis grandan homamason, kaj li kortuŝiĝis pri ili, kaj sanigis iliajn malsanulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Kaj kiam venis la vespero, liaj disĉiploj venis al li, dirante: La loko estas dezerta, kaj la horo jam pasis; forsendu la homamason, por ke ili iru en la vilaĝojn kaj aĉetu por si manĝaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Sed Jesuo diris al ili: Ili ne bezonas foriri; vi donu al ili manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'Kaj ili diris al li: Ni nenion havas ĉi tie, krom kvin panoj kaj du fiŝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'Kaj li diris: Alportu ilin ĉi tien al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'Kaj li ordonis al la homamasoj sidiĝi sur la herbo; kaj li prenis la kvin panojn kaj la du fiŝojn, kaj suprenrigardinte al la ĉielo, li benis kaj dispecigis la panojn, kaj donis al la disĉiploj, kaj la disĉiploj al la homamasoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'Kaj ĉiuj manĝis kaj satiĝis; kaj oni kolektis da postrestintaj fragmentoj dek du plenajn korbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Kaj la manĝantoj estis ĉirkaŭ kvin mil viroj, krom virinoj kaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'Kaj tuj li devigis la disĉiplojn eniri en la ŝipeton kaj iri antaŭ li al la alia bordo, ĝis li forsendos la homamason.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'Kaj forsendinte la homamason, li supreniris sur la monton sola, por preĝi; kaj kiam vesperiĝis, li estis tie sola.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Sed la ŝipeto jam estis meze de la maro, turmentata de la ondoj; ĉar la vento estis kontraŭa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Kaj en la kvara gardoparto de la nokto li venis al ili, irante sur la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'Sed la disĉiploj, vidante lin iranta sur la maro, maltrankviliĝis, dirante: Jen fantomo; kaj ili ekkriis pro timo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Sed tuj Jesuo parolis al ili, dirante: Kuraĝu; ĝi estas mi; ne timu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Kaj responde al li Petro diris: Sinjoro, se ĝi estas vi, ordonu min veni al vi sur la akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'Kaj li diris: Venu. Kaj Petro, malsuprenirinte el la ŝipeto, iris sur la akvo, por veni al Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Sed vidante la venton, li timis, kaj komencante subakviĝi, li ekkriis, dirante: Sinjoro, savu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Kaj tuj Jesuo etendis la manon kaj ektenis lin, dirante al li: Ho malgrandfidulo, kial vi dubis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'Kaj kiam ili supreniris en la ŝipeton, la vento ĉesiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Kaj tiuj, kiuj estis en la ŝipeto, adorkliniĝis al li, dirante: Vere vi estas Filo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'Kaj transirinte, ili alvenis teren ĉe Genesaret.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'Kaj kiam la viroj de tiu loko ekkonis lin, ili sendis en la tutan ĉirkaŭaĵon, kaj venigis al li ĉiujn malsanulojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'kaj ili petis lin, ke ili nur tuŝu la randon de lia mantelo; kaj ĉiuj, kiuj tuŝis, estis tute resanigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Tiam alvenis al Jesuo el Jerusalem Fariseoj kaj skribistoj, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, 'Kial viaj disĉiploj transpaŝas la tradicion de la antaŭuloj? ĉar ili ne lavas siajn manojn, kiam ili manĝas panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Kaj li responde diris al ili: Kial vi ankaŭ transpaŝas la ordonon de Dio per via tradicio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Ĉar Dio diris: Respektu vian patron kaj vian patrinon; kaj: Kiu malbenas sian patron aŭ sian patrinon, tiu nepre mortu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Sed vi diras: Se iu diros al sia patro aŭ al sia patrino: Oferdono estu tio, per kio vi povus profiti de mi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'tiu ne devas respekti sian patron aŭ sian patrinon. Kaj vi vantigis la vorton de Dio per via tradicio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Ho hipokrituloj, bone profetis Jesaja pri vi, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, 'Ĉi tiu popolo honoras Min per siaj lipoj, Sed ilia koro estas malproksime de Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'Sed vane ili Min adoras, Instruante kiel doktrinojn ordonojn de homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Kaj alvokinte al si la homamason, li diris al ili: Aŭskultu kaj komprenu:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Ne tio, kio eniras en la buŝon, profanas la homon; sed kio eliras el la buŝo, tio profanas la homon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Tiam veninte, la disĉiploj diris al li: Ĉu vi scias, ke la Fariseoj ofendiĝis, kiam ili aŭdis tiun diron?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Sed li responde diris: Ĉiu kreskaĵo, kiun mia ĉiela Patro ne plantis, estos elradikigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Lasu ilin; ili estas blindaj kondukantoj de blinduloj. Kaj se blindulo kondukos blindulon, ambaŭ falos en fosaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Kaj Petro responde diris al li: Klarigu al ni tiun parabolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Kaj li diris: Ĉu vi ankaŭ estas eĉ ankoraŭ sen kompreno?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Ĉu vi ne konscias, ke ĉio, eniranta en la buŝon, pasas en la ventron kaj estas elĵetata en apartan lokon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Sed tio, kio eliras el la buŝo, elvenas el la koro, kaj profanas la homon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Ĉar el la koro eliras malvirtaj pensoj, mortigoj, adultoj, malĉastaĵoj, ŝteloj, falsatestoj, blasfemoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'jen tio, kio profanas la homon, sed manĝi kun manoj nelavitaj ne profanas la homon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'Kaj elirinte de tie, Jesuo foriris en la regionojn apud Tiro kaj Cidon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'Kaj jen virino Kanaana, veninte el tiuj limlandoj, kriis, dirante: Ho Sinjoro, filo de David, kompatu min; mia filino estas terure turmentata de demono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Sed li ne respondis al ŝi eĉ unu vorton. Kaj alveninte, liaj disĉiploj petis lin, dirante: Forsendu ŝin, ĉar ŝi krias post ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'Kaj li responde diris: Mi ne estas sendita, krom al la perditaj ŝafoj el la domo de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Sed ŝi venis kaj adorkliniĝis al li, dirante: Sinjoro, helpu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Sed li responde diris: Ne decas preni la panon de la infanoj kaj ĵeti ĝin al la hundetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Sed ŝi diris: Jes, Sinjoro; ĉar eĉ la hundetoj manĝas el la panpecetoj, kiuj falas de la tablo de iliaj sinjoroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Tiam responde Jesuo diris al ŝi: Ho virino, granda estas via fido; estu al vi, kiel vi volas. Kaj ŝia filino estis sanigita de post tiu horo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'Kaj transirinte de tie, Jesuo venis apud la maron de Galileo; kaj suprenirinte sur la monton, li sidiĝis tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'Kaj alvenis al li grandaj homamasoj, havante kun si homojn lamajn, blindajn, mutajn, kriplajn, kun multaj aliaj, kaj metis ilin apud liajn piedojn; kaj li sanigis ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'tiel ke la homamaso miris, vidante mutulojn parolantaj, kriplulojn sanaj, kaj lamulojn piedirantaj, kaj blindulojn vidantaj; kaj ili gloris la Dion de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Kaj Jesuo, alvokinte al si siajn disĉiplojn, diris: Mi kortuŝiĝas pro la homamaso, ĉar jam tri tagojn ili restas ĉe mi, kaj nenion havas manĝi; kaj mi ne volas forsendi ilin fastantaj, por ke ili ne laciĝu sur la vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'Kaj la disĉiploj diris al li: De kie ni povas ricevi en la dezerto tiom da panoj, por satigi tiom da homoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'Kaj Jesuo diris al ili: Kiom da panoj vi havas? Kaj ili diris: Sep, kaj kelkajn malgrandajn fiŝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Kaj li ordonis al la homamaso sidiĝi sur la tero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'kaj li prenis la sep panojn kaj la fiŝojn; kaj doninte dankon, li dispecigis ilin, kaj donis al la disĉiploj, kaj la disĉiploj al la homamasoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'Kaj ĉiuj manĝis kaj satiĝis; kaj oni kolektis da postrestintaj fragmentoj sep korbegojn plenajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Kaj la manĝantoj estis kvar mil viroj, krom virinoj kaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Kaj forsendinte la homamasojn, li eniris en la ŝipeton, kaj venis en la regionojn de Magadan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Kaj alvenis la Fariseoj kaj la Sadukeoj, kaj por provi lin postulis, ke li montru al ili signon el la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Kaj responde li diris al ili: Kiam vesperiĝas, vi diras: Estos bona vetero, ĉar la ĉielo ruĝiĝas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'kaj frumatene: Estos hodiaŭ malbona vetero, ĉar la ĉielo ruĝiĝas kolere. La vizaĝon de la ĉielo vi povas juĝi, sed la signojn de la tempo vi ne povas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Generacio malbona kaj adultema serĉas signon; kaj signo ne estos donita al ĝi, krom la signo de Jona. Kaj lasinte ilin, li foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'Kaj la disĉiploj, transirinte al la alia bordo, forgesis preni panojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Sed Jesuo diris al ili: Zorgu, kaj gardu vin kontraŭ la fermentaĵo de la Fariseoj kaj Sadukeoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Kaj ili diskutis inter si, dirante: Ĉar ni ne prenis panojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Sed Jesuo, eksciante tion, diris: Kial vi diskutas inter vi, ho malgrandfiduloj, pro tio, ke vi ne prenis panojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Ĉu vi ankoraŭ ne konscias, nek memoras la kvin panojn de la kvin mil, kaj kiom da korboj vi kolektis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'Nek la sep panojn de la kvar mil, kaj kiom da korbegoj vi kolektis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Kial vi ne komprenas, ke ne pri panoj mi diris al vi: Gardu vin kontraŭ la fermentaĵo de la Fariseoj kaj Sadukeoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Tiam ili ekkomprenis, ke li admonis ilin sin gardi ne kontraŭ la fermentaĵo de panoj, sed kontraŭ la instruado de la Fariseoj kaj Sadukeoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Kaj Jesuo, veninte en la regionojn de Cezarea Filipi, demandis siajn disĉiplojn, dirante: Kiu, diras la homoj, ke mi, la Filo de homo, estas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Kaj ili diris: Laŭ iuj: Johano, la Baptisto; laŭ aliaj: Elija; kaj laŭ aliaj: Jeremia, aŭ unu el la profetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Li diris al ili: Sed vi, kiu vi diras, ke mi estas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Kaj responde Simon Petro diris: Vi estas la Kristo, la Filo de la vivanta Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Kaj Jesuo responde diris al li: Feliĉa vi estas, Simon Bar-Jona; ĉar ne karno kaj sango tion malkaŝis al vi, sed mia Patro, kiu estas en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'Kaj mi diras al vi, ke vi estas Petro, kaj sur ĉi tiu roko mi konstruos mian eklezion; kaj pordegoj de Hades ne superfortos ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'Mi donos al vi la ŝlosilojn de la regno de la ĉielo; kaj kion ajn vi ligos sur la tero, tio estos ligita en la ĉielo; kaj kion ajn vi malligos sur la tero, tio estos malligita en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Tiam li admonis la disĉiplojn, ke ili diru al neniu, ke li estas la Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'De post tiu tempo Jesuo komencis montri al siaj disĉiploj, ke li devas iri al Jerusalem, kaj multe suferi ĉe la pliaĝuloj kaj ĉefpastroj kaj skribistoj, kaj esti mortigita, kaj la trian tagon releviĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Kaj Petro prenis lin, kaj komencis admoni lin, dirante: Kompaton al vi, Sinjoro! tio ne estu al vi!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Sed turninte sin, li diris al Petro: Iru malantaŭ min, Satano; vi estas faligilo por mi, ĉar vi havas pensojn ne laŭ Dio, sed laŭ homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Tiam Jesuo diris al siaj disĉiploj: Se iu volas veni post mi, li abnegaciu sin, kaj levu sian krucon, kaj sekvu min;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'ĉar kiu volos savi sian animon, tiu ĝin perdos; kaj kiu perdos sian animon pro mi, tiu ĝin trovos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Ĉar kiel profitus homo, se li gajnus la tutan mondon kaj perdus sian animon? Aŭ kion homo donu interŝanĝe por sia animo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Ĉar la Filo de homo venos en la gloro de sia Patro kun siaj anĝeloj, kaj tiam li redonos al ĉiu laŭ liaj faroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Vere mi diras al vi: Inter la ĉi tie starantaj estas iuj, kiuj neniel gustumos morton, antaŭ ol ili vidos la Filon de homo venantan en sia regno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'Kaj post ses tagoj Jesuo prenis kun si Petron, kaj Jakobon, kaj Johanon, lian fraton, kaj kondukis ilin sur altan monton aparte;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'kaj li estis aliformita antaŭ ili, kaj lia vizaĝo lumis kiel la suno, kaj liaj vestoj fariĝis blankaj kiel la lumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'Kaj jen aperis al ili Moseo kaj Elija, parolantaj kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Kaj Petro responde diris al Jesuo: Sinjoro, estas bone por ni esti ĉi tie. Se vi volas, mi faros ĉi tie tri laŭbojn: unu por vi, kaj unu por Moseo, kaj unu por Elija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Dum li ankoraŭ parolis, jen luma nubo superombris ilin; kaj jen voĉo el la nubo, dirante: Ĉi tiu estas Mia Filo, la amata, en kiu Mi havas plezuron; aŭskultu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Kaj aŭdinte tion, la disĉiploj falis sur sian vizaĝon, kaj tre timis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Kaj Jesuo alvenis kaj ektuŝis ilin, kaj diris: Leviĝu, kaj ne timu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Kaj levinte siajn okulojn, ili vidis neniun krom Jesuo sola.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'Kaj dum ili malsupreniris de la monto, Jesuo ordonis al ili, dirante: Rakontu al neniu la vizion, ĝis la Filo de homo releviĝos el la mortintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'Kaj liaj disĉiploj demandis lin, dirante: Kial do diras la skribistoj, ke Elija devas veni antaŭe?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Kaj li responde diris: Vere Elija venas antaŭe, kaj restarigos ĉion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'sed mi diras al vi, ke Elija jam venis, kaj oni ne konis lin, sed faris al li ĉion, kion ili volis. Tiel ankaŭ la Filo de homo estas suferonta sub ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Tiam la disĉiploj komprenis, ke li parolis al ili pri Johano, la Baptisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'Kaj kiam li venis al la homamaso, venis al li viro, genuante antaŭ li, kaj dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'Sinjoro, kompatu mian filon, ĉar li frenezas kaj forte suferas; ĉar ofte li falas en la fajron kaj ofte en la akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'Kaj mi venigis lin al viaj disĉiploj, kaj ili ne povis lin sanigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Kaj Jesuo responde diris: Ho senfida kaj perversa generacio, ĝis kiam mi estos kun vi? ĝis kiam mi toleros vin? venigu lin al mi ĉi tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'Kaj Jesuo severe admonis lin; kaj la demono eliris el li, kaj la knabo resaniĝis en tiu sama horo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Tiam la disĉiploj, veninte al Jesuo aparte, diris: Pro kio ni ne povis elpeli ĝin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'Kaj li respondis al ili: Pro la malgrandeco de via fido; ĉar vere mi diras al vi: Se vi havas fidon, kiel semero de sinapo, vi diros al ĉi tiu monto: Translokiĝu tien de ĉi tie, kaj ĝi translokiĝos; kaj nenio estos neebla por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Sed ĉi tiu speco ne eliras, krom per preĝado kaj fastado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'Kaj kiam ili kolektiĝis en Galileo, Jesuo diris al ili: La Filo de homo estos transdonita en la manojn de homoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'kaj ili mortigos lin, kaj la trian tagon li leviĝos. Kaj ili tre malĝojis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Kaj kiam ili venis en Kapernaumon, venis al Petro la ricevistoj de la du draĥmoj, kaj diris: Ĉu via majstro pagas la du draĥmojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Li respondis: Jes. Kaj kiam li venis en la domon, Jesuo unue parolis al li, dirante: Kiel ŝajnas al vi, Simon? de kiuj prenas la reĝoj de la tero imposton aŭ tributon? de siaj filoj aŭ de la fremduloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Kaj kiam li diris: De la fremduloj; Jesuo diris: Sekve la filoj estas liberaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Sed, por ke ni ne ofendu ilin, iru al la maro kaj ĵetu hoketon, kaj prenu la fiŝon unue venintan, kaj malferminte ĝian buŝon, vi trovos stateron. Prenu ĝin, kaj donu al ili por mi kaj vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'En tiu horo la disĉiploj venis al Jesuo, dirante: Kiu do estas la plej granda en la regno de la ĉielo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'Kaj alvokinte al si infanon, li starigis ĝin meze de ili,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'kaj diris: Vere mi diras al vi: Se vi ne turniĝos kaj ne fariĝos kiel infanoj, vi neniel eniros en la regnon de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Kiu do humiligos sin, kiel ĉi tiu infano, tiu estas la plej granda en la regno de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'Kaj kiu akceptos unu tian infanon en mia nomo, tiu akceptas min;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'sed kiu igos fali unu el ĉi tiuj malgranduloj, kiuj kredas al mi, estus pli bone por tiu, se granda muelŝtono estus pendigita ĉirkaŭ lia kolo, kaj se li estus subakvigita en la profundon de la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Ve al la mondo pro faliloj! ĉar estas necese, ke venu faliloj, sed ve al tiu homo, per kiu la falilo venas!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Kaj se via mano aŭ via piedo faligas vin, detranĉu ĝin kaj forĵetu ĝin de vi: estas bone por vi eniri en vivon kripla aŭ lama prefere ol, havante du manojn aŭ du piedojn, esti enĵetita en la eternan fajron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'Kaj se via okulo faligas vin, elŝiru ĝin kaj forĵetu ĝin de vi; estas bone por vi eniri en vivon unuokula prefere ol, havante du okulojn, esti enĵetita en Gehenan de fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Gardu vin, ke vi ne malestimu unu el tiuj malgranduloj; ĉar mi diras al vi, ke iliaj anĝeloj en la ĉielo ĉiam rigardas la vizaĝon de mia Patro, kiu estas en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'Ĉar la Filo de homo venis, por savi tion, kio estis perdita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Kiel vi pensas? Se viro havas cent ŝafojn, kaj unu el ili erarvagis, ĉu li ne lasas la naŭdek naŭ, kaj iras al la montoj, kaj serĉas tiun, kiu erarvagis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'Kaj se okazas, ke li trovas ĝin, vere mi diras al vi, li plimulte ĝojas pri ĝi, ol pri la naŭdek naŭ, kiuj ne erarvagis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Tiel same ne estas la volo de via Patro, kiu estas en la ĉielo, ke unu el ĉi tiuj malgranduloj pereu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Kaj se via frato pekos kontraŭ vi, iru kaj montru al li la kulpon inter vi kaj li sola. Se li aŭskultos vin, vi gajnos vian fraton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Sed se li ne aŭskultos, prenu ankaŭ unu aŭ du kun vi, por ke per la buŝo de du aŭ tri atestantoj ĉiu vorto estu konfirmita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Kaj se li rifuzos aŭskulti ilin, diru la aferon al la eklezio; kaj se li ankaŭ rifuzos aŭskulti la eklezion, li estu por vi kiel fremdulo kaj impostisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Vere mi diras al vi, ke ĉio, kion vi ligos sur la tero, estos ligita en la ĉielo; kaj ĉio, kion vi malligos sur la tero, estos malligita en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Cetere mi diras al vi, ke se du el vi konsentos sur la tero pri ia pripetota afero, ĝi estos farita al ili de mia Patro, kiu estas en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Ĉar kie du aŭ tri kunvenas en mia nomo, tie mi estas meze de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Tiam Petro venis kaj diris al li: Sinjoro, kiomfoje povu peki mia frato kontraŭ mi, kaj mi pardonu lin? ĝis sep fojoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Jesuo diris al li: Mi ne diras al vi: Ĝis sep fojoj; sed: Ĝis sepdekoble sep fojoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'Tial la regno de la ĉielo similas al reĝo, kiu volis fari kalkulon kun siaj servistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'Kaj kiam li komencis la kunkalkuladon, oni alkondukis al li unu, kiu estis ŝuldanto por dek mil talantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Sed ĉar li ne havis, per kio pagi, lia sinjoro ordonis, ke estu venditaj li kaj lia edzino kaj liaj infanoj, kaj ĉio, kion li posedis, kaj ke estu pago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Tiam la servisto, falinte, kliniĝis antaŭ li, dirante: Sinjoro, paciencu pri mi, kaj mi pagos al vi ĉion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Kaj la sinjoro de tiu servisto, kortuŝite, liberigis lin kaj pardonis al li la ŝuldon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Sed elirinte, tiu servisto trovis kunserviston, kiu ŝuldis al li cent denarojn; kaj li kaptis kaj eksufokis lin, dirante: Pagu tion, kion vi ŝuldas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Kaj falinte antaŭ li, la kunservisto petegis lin, dirante: Paciencu pri mi, kaj mi pagos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'Sed li ne volis; sed foriris kaj ĵetis lin en malliberejon, ĝis li pagos tion, kio estas ŝuldata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Tiam liaj kunservistoj, vidinte tion, kio okazis, tre ĉagreniĝis; kaj veninte, rakontis al sia sinjoro ĉion, kio okazis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Tiam lia sinjoro, alvokinte lin, diris: Vi malbona servisto, mi pardonis al vi tiun tutan ŝuldon, ĉar vi petegis min;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'ĉu vi ankaŭ ne devis kompati vian kunserviston, kiel mi kompatis vin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'Kaj lia sinjoro koleris, kaj transdonis lin al la turmentistoj, ĝis li pagos ĉion al li ŝuldatan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'Tiel same mia ĉiela Patro faros al vi, se vi ne pardonas el viaj koroj, ĉiu al sia frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'Kaj kiam Jesuo finis ĉi tiujn parolojn, li foriris el Galileo, kaj venis en la limojn de Judujo trans Jordan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'kaj grandaj homamasoj lin sekvis, kaj li sanigis ilin tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Kaj venis al li Fariseoj, provante lin, kaj dirante: Ĉu estas permesate forsendi sian edzinon pro ĉia kaŭzo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'Kaj responde li diris: Ĉu vi ne legis, ke en la komenco la Kreinto faris ilin vira kaj virina,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'kaj diris: Tial viro forlasos sian patron kaj sian patrinon, kaj aliĝos al sia edzino; kaj ili estos unu karno?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'Sekve ili jam estas ne du, sed unu karno. Kion do Dio kunigis, tion homo ne disigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Ili diris al li: Kial do Moseo ordonis doni eksedzigan leteron, kaj forsendi ŝin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Li diris al ili: Moseo, pro la malmoleco de via koro, permesis al vi forsendi viajn edzinojn; sed ne estis tiel de la komenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Sed mi diras al vi: Kiu forsendos sian edzinon krom pro malĉasteco, kaj edziĝos kun alia, tiu adultas; kaj kiu edziĝas kun la forsenditino, tiu adultas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'La disĉiploj diris al li: Se tia estas la rilato de viro al virino, ne estas oportune edziĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'Sed li diris al ili: Ne ĉiuj homoj akceptas ĉi tiun diron, sed nur tiuj, al kiuj tio estas donita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'Ĉar estas eŭnukoj, kiuj estas naskitaj tiaj el la patrina ventro; kaj estas eŭnukoj, kiuj estis eŭnukigitaj de homoj; kaj estas eŭnukoj, kiuj eŭnukigis sin pro la regno de la ĉielo. Kiu povas tion akcepti, tiu akceptu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Tiam oni venigis al li infanojn, por ke li metu la manojn sur ilin kaj preĝu; kaj la disĉiploj admonis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Sed Jesuo diris: Lasu la infanojn, kaj ne malhelpu ilin, veni al mi; ĉar el tiaj estas la regno de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'Kaj metinte la manojn sur ilin, li foriris de tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'Kaj jen unu viro, veninte al li, diris: Majstro, kian bonon mi faru, por ke mi ricevu eternan vivon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Li diris al li: Kial vi min demandas pri bono? Ekzistas Unu, kiu estas bona; sed se vi deziras eniri en la vivon, observu la ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'Li diris al li: Kiujn? Kaj Jesuo diris: Ne mortigu; Ne adultu; Ne ŝtelu; Ne parolu malveran ateston;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'Respektu vian patron kaj vian patrinon; kaj: Amu vian proksimulon kiel vin mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'La junulo diris al li: Ĉion tion mi observis; kio ankoraŭ mankas al mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Jesuo diris al li: Se vi deziras esti perfekta, iru, vendu viajn posedaĵojn, kaj donu al malriĉuloj, kaj vi havos trezoron en la ĉielo; kaj venu, sekvu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Sed aŭdinte tiun diron, la junulo foriris malĝoja, ĉar li havis multajn posedaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Kaj Jesuo diris al siaj disĉiploj: Vere mi diras al vi: Malfacile riĉulo eniros en la regnon de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Kaj cetere mi diras al vi: Estas pli facile por kamelo iri tra trueton de kudrilo, ol por riĉulo eniri en la regnon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'Kiam la disĉiploj tion aŭdis, ili forte miregis, dirante: Kiu do povas esti savita?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Kaj Jesuo, rigardante ilin, diris al ili: Ĉe homoj tio estas neebla, sed ĉe Dio ĉio estas ebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Tiam Petro responde diris al li: Jen ni ĉion forlasis, kaj vin sekvis; kion do ni havos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Jesuo diris al ili: Vere mi diras al vi, ke vi, kiuj min sekvis, en la renaskado, kiam la Filo de homo sidos sur la trono de sia gloro, vi ankaŭ sidos sur dek du tronoj, juĝante la dek du tribojn de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'Kaj ĉiu, kiu forlasis domojn aŭ fratojn aŭ fratinojn aŭ patron aŭ patrinon aŭ infanojn aŭ kampojn pro mia nomo, ricevos multoble kaj heredos eternan vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Sed multaj unuaj estos lastaj, kaj lastaj estos unuaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, 'Ĉar la regno de la ĉielo similas al domomastro, kiu eliris frumatene, por dungi laboristojn por sia vinberĝardeno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Kaj kontraktinte kun la laboristoj po unu denaro por la tago, li ilin sendis en sian vinberejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'Kaj elirinte ĉirkaŭ la tria horo, li vidis aliajn starantajn senokupe sur la placo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'kaj li diris al ili: Vi ankaŭ iru en la vinberejon, kaj kiom estas justa, tiom mi donos al vi. Kaj ili iris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'Denove elirinte ĉirkaŭ la sesa horo kaj la naŭa, li agis simile.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Kaj elirinte ĉirkaŭ la dek-unua horo, li trovis aliajn starantajn; kaj li diris al ili: Kial vi staras ĉi tie senokupe la tutan tagon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Ili diris al li: Ĉar neniu nin dungis. Li diris al ili: Vi ankaŭ iru en la vinberejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Kaj kiam vesperiĝis, la sinjoro de la vinberejo diris al sia administranto: Alvoku la laboristojn, kaj donu al ili la salajron, komencante de la lastaj ĝis la unuaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'Kaj venis tiuj, kiuj estis dungitaj ĉirkaŭ la dek-unua horo, kaj ili ricevis po unu denaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Kaj kiam la unuaj venis, ili supozis, ke ili ricevos pli; kaj ili ankaŭ ricevis po unu denaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'Kaj tion ricevinte, ili murmuris kontraŭ la domomastro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'dirante: Tiuj lastaj laboris nur unu horon, kaj vi faris ilin egalaj kun ni, kiuj elportis la ŝarĝon de la tago kaj la varmegon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'Sed li responde diris al unu el ili: Amiko, mi ne faras al vi maljustaĵon; ĉu vi ne kontraktis kun mi por unu denaro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Prenu do la vian kaj foriru; mi volas doni al ĉi tiu lasta tiel same, kiel al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Ĉu ne estas permesate al mi, fari kun la mia tion, kion mi volas? aŭ ĉu via okulo estas malbona tial, ke mi estas bona?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Tiel la lastaj estos unuaj, kaj la unuaj estos lastaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'Kaj suprenirante al Jerusalem, Jesuo prenis la dek du disĉiplojn aparte, kaj sur la vojo li diris al ili:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, 'Jen ni supreniras al Jerusalem; kaj la Filo de homo estos transdonita al la ĉefpastroj kaj skribistoj; kaj ili kondamnos lin al morto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'kaj transdonos lin al la nacianoj, por moki kaj skurĝi kaj krucumi; kaj la trian tagon li releviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Tiam venis al li la patrino de la filoj de Zebedeo, kun siaj filoj, adorkliniĝante kaj farante al li peton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'Li diris al ŝi: Kion vi volas? Ŝi diris al li: Ordonu, ke ĉi tiuj miaj du filoj povu sidi, unu dekstre de vi kaj la dua maldekstre, en via regno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Sed Jesuo responde diris: Vi ne scias, kion vi petas. Ĉu vi povas trinki la kalikon, kiun mi trinkos? Ili diris al li: Ni povas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Li diris al ili: Mian kalikon vi ja trinkos; sed sidi dekstre de mi kaj maldekstre, tion doni ne apartenas al mi, sed ĝi estas por tiuj, por kiuj ĝi estas preparita de mia Patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'Kaj aŭdinte, la dek indignis kontraŭ la du fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Sed Jesuo, alvokinte ilin al si, diris: Vi scias, ke la regantoj de la nacioj kondutas kiel sinjoroj super ili, kaj iliaj granduloj ekzercas aŭtoritaton super ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Ne tiel estos inter vi; sed kiu volas esti granda inter vi, tiu estu via servanto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'kaj kiu volas esti la unua inter vi, tiu estu via servisto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'same kiel la Filo de homo venis, ne por esti servata, sed por servi, kaj por doni sian vivon kiel elaĉeton por multaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'Kaj kiam ili eliris el Jeriĥo, granda homamaso lin sekvis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'Kaj jen du blinduloj, sidantaj apud la vojo, aŭdinte, ke Jesuo preterpasas, ekkriis, dirante: Sinjoro, kompatu nin, ho filo de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Kaj la homamaso admonis ilin, ke ili silentu, sed ili plimulte kriis, dirante: Sinjoro, kompatu nin, ho filo de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'Kaj Jesuo, haltinte, alvokis ilin, kaj diris: Kion vi volas, ke mi faru al vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Ili diris al li: Sinjoro, ke niaj okuloj estu malfermitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Kaj Jesuo, kortuŝite, tuŝis iliajn okulojn; kaj tuj ili ricevis vidpovon, kaj sekvis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'Kaj kiam ili alproksimiĝis al Jerusalem, kaj venis al Betfage, al la monto Olivarba, tiam Jesuo sendis du disĉiplojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'dirante al ili: Iru en la vilaĝon, kiu estas kontraŭ vi, kaj vi tuj trovos azeninon ligitan, kaj azenidon kun ĝi. Ilin malligu kaj alkonduku al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'Kaj se iu diros ion al vi, respondu: La Sinjoro bezonas ilin; kaj tuj li sendos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Kaj ĉi tio okazis, por ke plenumiĝu tio, kio estis dirita per la profeto, nome:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, 'Diru al la filino de Cion: Jen via Reĝo iras al vi, Humila kaj rajdanta sur azeno, Kaj azenido, filo de ŝarĝobesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Kaj la disĉiploj iris, kaj faris, kiel Jesuo ordonis al ili,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'kaj alkondukis la azeninon kaj la azenidon, kaj surmetis sur ilin siajn vestojn; kaj li sidis sur tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'Kaj la pli granda parto de la homamaso sternis siajn vestojn sur la vojo; kaj aliaj detranĉis branĉojn de la arboj, kaj dismetis ilin sur la vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'Kaj la homamaso, kiu iris antaŭ li, kaj kiu sekvis lin, kriis, dirante: Hosana al la Filo de David! Estu benata tiu, kiu venas en la nomo de la Eternulo; Hosana en la supera alto!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'Kaj li eniris en Jerusalemon, kaj la tuta urbo malkvietiĝis, dirante: Kiu estas ĉi tiu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'Kaj la homamasoj diris: Ĉi tiu estas la profeto, Jesuo el Nazaret en Galileo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'Kaj Jesuo eniris en la templon de Dio, kaj elpelis ĉiujn vendantojn kaj aĉetantojn en la templo, kaj renversis la tablojn de la monŝanĝistoj, kaj la seĝojn de la vendantoj de kolomboj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'kaj li diris al ili: Estas skribite: Mia domo estas nomata domo de preĝo; sed vi faris ĝin kaverno de rabistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'Kaj blinduloj kaj lamuloj venis al li en la templo, kaj li sanigis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Sed la ĉefpastroj kaj skribistoj, vidinte la mirindaĵojn, kiujn li faris, kaj la knabojn kriantajn en la templo, kaj dirantajn: Hosana al la Filo de David, indignis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'kaj diris al li: Ĉu vi aŭdas, kion ĉi tiuj diras? Kaj Jesuo diris al ili: Jes; ĉu vi neniam legis: El la buŝo de junaj infanoj kaj suĉinfanoj Vi perfektigis laŭdon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'Kaj lasinte ilin, li eliris el la urbo al Betania, kaj tie loĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Kaj matene, dum li revenis al la urbo, li malsatis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'Kaj vidante figarbon apud la vojo, li iris al ĝi, kaj trovis sur ĝi nenion krom folioj; kaj li diris al ĝi: Ne plu estu frukto sur vi por eterne. Kaj tuj la figarbo forvelkis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'Kaj kiam la disĉiploj vidis, ili miris, dirante: Kiel rapide la figarbo forvelkis!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Kaj Jesuo responde diris al ili: Vere mi diras al vi: Se vi havos fidon kaj ne dubos, vi ne nur faros la aferon de la figarbo, sed eĉ se vi diros al ĉi tiu monto: Estu formovita kaj ĵetita en la maron; tio plenumiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'Kaj ĉion, kion vi petos per preĝado, kredante, vi ricevos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'Kaj kiam li jam venis en la templon, la ĉefpastroj kaj la pliaĝuloj de la popolo venis al li, dum li instruis, kaj ili diris: Laŭ kia aŭtoritato vi faras ĉi tion? kaj kiu donis al vi tian aŭtoritaton?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Kaj Jesuo responde diris al ili: Mi ankaŭ faros al vi unu demandon; kaj se vi tion diros al mi, mi ankaŭ diros al vi, laŭ kia aŭtoritato mi faras ĉi tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'La baptado de Johano, de kie ĝi estis? El la ĉielo, aŭ el homoj? Kaj ili diskutis inter si, dirante: Se ni diros: El la ĉielo, li diros al ni: Kial do vi ne kredis al li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Sed se ni diros: El homoj, ni timas la popolon, ĉar ĉiuj opinias Johanon profeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'Kaj ili responde diris al Jesuo: Ni ne scias. Li ankaŭ diris al ili: Kaj mi ne diras al vi, laŭ kia aŭtoritato mi faras ĉi tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Kiel ŝajnas al vi? Unu viro havis du filojn; kaj li venis al la unua, kaj diris: Filo, iru hodiaŭ kaj laboru en la vinberĝardeno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Kaj li respondis kaj diris: Mi ne volas; sed poste li pentis kaj iris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'Kaj li venis al la dua, kaj diris tion saman. Kaj li responde diris: Mi iros, sinjoro; kaj ne iris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Kiu el la du plenumis la volon de la patro? Ili diris: La unua. Jesuo diris al ili: Vere mi diras al vi, ke la impostistoj kaj malĉastistinoj iras antaŭ vi en la regnon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Ĉar Johano venis al vi en vojo de justeco, kaj vi ne kredis al li; sed la impostistoj kaj malĉastistinoj kredis al li. Kaj vi, kiam vi vidis, eĉ ne pentis poste, por kredi al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Aŭskultu alian parabolon: Estis viro dommastro, kiu plantis vinberĝardenon, kaj ĉirkaŭmetis plektobarilon, kaj fosis en ĝi vinpremejon, kaj konstruis turon, kaj luigis ĝin al kultivistoj, kaj forvojaĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'Kaj kiam alproksimiĝis la sezono de fruktoj, li sendis siajn sklavojn al la kultivistoj, por ricevi siajn fruktojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Kaj la kultivistoj, kaptinte liajn sklavojn, skurĝis unu, kaj mortigis alian, kaj ŝtonbatis alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Li sendis ankoraŭ aliajn sklavojn, pli multajn ol la unuaj; kaj ili faris al ili tiel same.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Sed poste li sendis al ili sian filon, dirante: Ili respektos mian filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Sed la kultivistoj, vidante la filon, diris inter si: Ĉi tiu estas la heredonto; venu, ni lin mortigu, kaj prenu lian heredaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'Kaj ili kaptis lin, elĵetis lin el la vinberejo, kaj mortigis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Kiam do venos la sinjoro de la vinberejo, kion li faros al tiuj kultivistoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Ili diris al li: Tiujn malbonulojn li mizere pereigos, kaj li luigos la vinberejon al aliaj kultivistoj, kiuj donos al li la fruktojn en iliaj sezonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Jesuo diris al ili: Ĉu vi neniam legis en la Skriboj: Ŝtono, kiun malŝatis la konstruantoj, Fariĝis ŝtono bazangula: De la Eternulo ĉi tio fariĝis, Kaj ĝi estas miraklo en niaj okuloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'Tial mi diras al vi: La regno de Dio estos prenita for de vi, kaj estos donita al nacio, kiu liveros ĝiajn fruktojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'Kaj kiu falas sur tiun ŝtonon, tiu rompiĝos; sed sur kiun ĝi falos, ĝi tiun polvigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'Kaj la ĉefpastroj kaj la Fariseoj, aŭdinte liajn parabolojn, komprenis, ke li parolas pri ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'Kaj celante kapti lin, ili timis la popolon, ĉar oni opiniis lin profeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'Kaj respondante, Jesuo denove parolis al ili parabole, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, 'La regno de la ĉielo similas al unu reĝo, kiu faris edziĝan feston por sia filo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'kaj sendis siajn sklavojn, por voki la invititojn al la edziĝa festo; kaj ili ne volis veni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Poste li sendis aliajn sklavojn, dirante: Diru al la invititoj: Jen mi preparis la manĝon; miaj bovoj kaj miaj grasigitaj brutoj estas buĉitaj, kaj ĉio estas preta; venu al la edziĝa festo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Sed ili malatentis, kaj foriris, unu al sia bieno, alia al sia komercado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'kaj la ceteraj, kaptinte liajn sklavojn, perfortis kaj mortigis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Kaj la reĝo koleris; kaj sendinte siajn armeojn, li pereigis tiujn mortigintojn kaj bruligis ilian urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Tiam li diris al siaj sklavoj: La edziĝa festo estas preta, sed la invititoj ne estis indaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Iru do al la disirejoj de la vojoj, kaj ĉiujn, kiujn vi trovos, invitu al la edziĝa festo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'Kaj tiuj sklavoj, elirinte sur la vojojn, kunvenigis ĉiujn, kiujn ili trovis, malbonajn kaj bonajn; kaj la edziĝa festo pleniĝis de gastoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Sed la reĝo, enveninte por rigardi la gastojn, tie vidis viron, kiu ne havis sur si edziĝofestan veston;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'kaj li diris al li: Amiko, kiel vi envenis ĉi tien, ne havante edziĝofestan veston? Kaj li silentadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Tiam la reĝo diris al siaj servantoj: Ligu lin mane kaj piede, kaj elĵetu lin en la eksteran mallumon; tie estos la plorado kaj la grincado de dentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Ĉar multaj estas vokitaj, sed malmultaj estas elektitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Tiam iris la Fariseoj, kaj konsiliĝis, kiel ili povos impliki lin per interparolado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'Kaj ili sendis al li siajn disĉiplojn kun la Herodanoj, por diri: Majstro, ni scias, ke vi estas verama, kaj instruas laŭ vero la vojon de Dio, kaj ne zorgas pri iu ajn; ĉar vi ne favoras la personon de homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Diru do al ni, kiel ŝajnas al vi? ĉu konvenas doni tributon al Cezaro, aŭ ne?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Sed Jesuo, sciante ilian ruzecon, diris: Kial vi min provas, hipokrituloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Montru al mi la tributan moneron. Kaj ili alportis al li denaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'Kaj li diris al ili: Kies estas ĉi tiu bildo kaj la surskribaĵo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'Ili diris al li: De Cezaro. Tiam li diris al ili: Redonu do al Cezaro la propraĵon de Cezaro, kaj al Dio la propraĵon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'Kaj aŭdinte, ili miris, kaj lin lasis kaj foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'En tiu sama tago alvenis al li Sadukeoj, kiuj diras, ke ne estas releviĝo; kaj ili demandis lin, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'Majstro, Moseo diris: Se iu mortas, ne havante infanojn, lia frato edziĝu kun lia edzino kaj naskigu idaron al sia frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Estis ĉe ni sep fratoj; kaj la unua edziĝis kaj mortis, kaj ne havante idaron, lasis sian edzinon al sia frato;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'tiel same ankaŭ la dua, kaj la tria, ĝis la sepa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'Kaj post ĉiuj la virino mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'En la releviĝo do, por kiu el la sep ŝi estos edzino? ĉar ĉiuj ŝin havis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Sed Jesuo responde diris: Vi eraras, ne sciante la Skribojn, nek la potencon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'Ĉar en la releviĝo oni nek edziĝas nek edziniĝas, sed estas kiel anĝeloj en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'Sed pri la releviĝo el la mortintoj, ĉu vi ne legis tion, kio estis dirita al vi de Dio, nome:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, 'Mi estas la Dio de Abraham kaj la Dio de Isaak kaj la Dio de Jakob? Dio estas Dio ne de la mortintoj, sed de la vivantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'Kaj kiam la homamaso tion aŭdis, ili miregis pro lia instruado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Sed la Fariseoj, aŭdinte, ke li silentigis la Sadukeojn, kune kolektiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'Kaj unu el ili, leĝisto, demandis lin, provante lin:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, 'Majstro, kiu estas la granda ordono en la leĝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'Kaj li diris al li: Amu la Eternulon, vian Dion, per via tuta koro kaj per via tuta animo kaj per via tuta menso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'Ĉi tiu estas la granda kaj la unua ordono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'Kaj dua estas simila al ĝi: Amu vian proksimulon kiel vin mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'De ĉi tiuj du ordonoj dependas la tuta leĝo kaj la profetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'Kaj kiam la Fariseoj jam kunvenis, Jesuo ilin demandis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, 'dirante: Kion vi pensas pri la Kristo? kies filo li estas? Ili diris al li: De David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Li diris al ili: Kial do David, en la Spirito, lin nomas Sinjoro, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, 'La Eternulo diris al mia Sinjoro: Sidu dekstre de Mi, Ĝis Mi faros viajn malamikojn benketo por viaj piedoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Se do David nomas lin Sinjoro, kiel li estas lia filo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'Kaj neniu povis respondi unu vorton al li, nek iu post tiu tago plu kuraĝis fari al li demandon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Tiam parolis Jesuo al la homamasoj kaj al siaj disĉiploj, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'La skribistoj kaj la Fariseoj sidas sur la seĝo de Moseo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'ĉion do, kion ili ordonas al vi, faru kaj observu; sed ne agu laŭ iliaj faroj, ĉar ili ordonas, sed ne faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Ili ligas pezajn ŝarĝojn malfacile porteblajn, kaj metas ilin sur la ŝultrojn de homoj; sed ili mem ne volas movi ilin per sia fingro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'Sed ĉiujn siajn agojn ili faras, por esti rigardataj de homoj; ĉar ili larĝigas siajn filakteriojn kaj grandigas la franĝojn de siaj vestoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'kaj amas la ĉeflokojn ĉe festenoj, kaj la ĉefseĝojn en la sinagogoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'kaj salutojn sur la placoj, kaj esti nomataj de homoj Rabeno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Sed vi ne estu nomataj Rabeno; ĉar unu estas via instruanto, kaj vi ĉiuj estas fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'Kaj nomu neniun sur la tero via patro; ĉar Unu, kiu estas en la ĉielo, estas via Patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Kaj ne estu nomataj edukantoj; ĉar unu, la Kristo, estas via edukanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Sed la pli granda el vi estos via servanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Kaj kiu sin plialtigos, tiu estos humiligita; kaj kiu sin humiligos, tiu estos plialtigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Sed ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi ŝlosas la regnon de la ĉielo kontraŭ la homoj; ĉar vi mem ne eniras, nek lasas al la enirantoj eniri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, 'Ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi formanĝas domojn de vidvinoj, kaj por preteksto vi longe preĝas; tial vi ricevos pli severan kondamnon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi ĉirkaŭiras maron kaj teron, por varbi unu prozeliton; kaj kiam li tia fariĝis, vi lin faras filo de Gehena, duoble kiom vi mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Ve al vi, blindaj gvidantoj! kiuj diras: Se iu ĵuras per la sanktejo, tio estas nenio; sed kiu ĵuras per la oro de la sanktejo, tiu estas ŝuldanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Vi malsaĝaj kaj blindaj! ĉar kio estas pli granda, la oro, aŭ la sanktejo, kiu sanktigas la oron?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'Kaj: Se iu ĵuras per la altaro, tio estas nenio; sed kiu ĵuras per la ofero, kuŝanta sur ĝi, tiu estas ŝuldanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Vi blinduloj! ĉar kio estas pli granda, la ofero, aŭ la altaro, kiu sanktigas la oferon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Tiu do, kiu ĵuras per la altaro, ĵuras per ĝi, kaj per ĉio, kuŝanta sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'Kaj tiu, kiu ĵuras per la sanktejo, ĵuras per ĝi, kaj per Tiu, kiu loĝas en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'Kaj tiu, kiu ĵuras per la ĉielo, ĵuras per la trono de Dio, kaj per Tiu, kiu sidas sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi pagas dekonaĵojn de mento kaj de anizo kaj de kumino, kaj forlasis la pli gravajn aferojn de la leĝo: juĝon kaj kompaton kaj fidon. Sed ĉi tiujn vi devus fari, kaj la aliajn ne preterlasi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Vi blindaj gvidantoj! kiuj elkribras la kulon kaj glutas la kamelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi purigas la eksteron de la kaliko kaj de la plado; sed interne ili estas plenaj de rabado kaj malmodereco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Vi blinda Fariseo! purigu unue la internon de la kaliko kaj de la plado, por ke ilia ekstero ankaŭ fariĝu pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi similas al tomboj blankigitaj, kiuj ekstere ŝajnas belaj, sed interne estas plenaj de ostoj de mortintoj kaj de ĉia malpureco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Tiel ankaŭ vi ekstere ŝajnas justaj antaŭ homoj, sed interne vi estas plenaj de hipokriteco kaj maljusteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Ve al vi, skribistoj kaj Fariseoj, hipokrituloj! ĉar vi konstruas la tombojn de la profetoj kaj ornamas la monumentojn de la justuloj, kaj diras:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'Se ni vivus en la tagoj de niaj patroj, ni ne partoprenus kun ili en la sango de la profetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'Tial vi atestas pri vi mem, ke vi estas filoj de tiuj, kiuj mortigis la profetojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'Vi do plenigu la mezuron de viaj patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Serpentoj, vipuridoj! kiel vi povos eviti la juĝon de Gehena?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Jen do mi sendas al vi profetojn kaj saĝulojn kaj skribistojn; iujn el ili vi mortigos kaj krucumos, kaj aliajn el ili vi skurĝos en viaj sinagogoj kaj persekutos de urbo al urbo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'por ke venu sur vin la tuta justa sango elverŝita sur la teron, de la sango de la justulo Habel ĝis la sango de Zeĥarja, filo de Bereĥja, kiun vi mortigis inter la sanktejo kaj la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'Vere mi diras al vi: Ĉio tio venos sur ĉi tiun generacion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Ho Jerusalem, Jerusalem, kiu mortigas la profetojn, kaj priĵetas per ŝtonoj tiujn, kiuj estas senditaj al ĝi! kiom ofte mi volis kolekti viajn infanojn, kiel kokino kolektas sian idaron sub la flugilojn, kaj vi ne volis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Jen via domo estas lasita al vi dezerta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'Ĉar mi diras al vi: De nun vi ne vidos min, ĝis vi diros: Estu benata tiu, kiu venas en la nomo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'Kaj Jesuo, elirinte, ekforiris de la templo; kaj liaj disĉiploj venis al li, por montri al li la konstruaĵojn de la templo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'Sed li responde diris al ili: Ĉu vi ne vidas ĉion tion? vere mi diras al vi: Ne estos lasita ĉi tie ŝtono sur ŝtono, kiu ne estos deĵetita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'Kaj dum ili sidis sur la monto Olivarba, la disĉiploj venis aparte al li, dirante: Diru al ni, kiam tio estos? Kaj kio estas la signo de via alesto kaj de la maturiĝo de la mondaĝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'Kaj Jesuo, respondante, diris al ili: Gardu vin, ke neniu vin forlogu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'Ĉar multaj venos en mia nomo, dirante: Mi estas la Kristo; kaj ili forlogos multajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Kaj vi aŭdos pri militoj kaj famoj de militoj. Zorgu, ke vi ne maltrankviliĝu; ĉar tio devas okazi; sed ankoraŭ ne estas la fino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Ĉar leviĝos nacio kontraŭ nacion, kaj regno kontraŭ regnon; kaj estos malsatoj kaj tertremoj en diversaj lokoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Sed ĉio tio estas komenco de suferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Tiam oni transdonos vin al afliktado, kaj mortigos vin; kaj vi estos malamataj de ĉiuj nacioj pro mia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'Tiam multaj ofendiĝos, kaj perfidos unu la alian, kaj malamos unu la alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'Kaj multaj falsaj profetoj leviĝos, kaj forlogos multajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'Kaj pro la multobligo de maljusteco, la amo de la plimulto malvarmiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Sed kiu persistos ĝis la fino, tiu estos savita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'Kaj ĉi tiu evangelio de la regno estos predikita tra la tuta mondo, kiel atesto al ĉiuj nacioj; kaj tiam venos la fino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Kiam do vi vidos la abomenindaĵon de dezerteco, pri kiu estas dirite de la profeto Daniel, starantan sur la sankta loko (la leganto komprenu),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'tiam tiuj, kiuj estas en Judujo, forkuru al la montoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'kiu estas sur la tegmento, tiu ne malsupreniru, por preni ion el sia domo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'kaj kiu estas sur la kampo, tiu ne revenu, por preni sian mantelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Sed ve al la gravedulinoj kaj al la suĉigantinoj en tiuj tagoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Kaj preĝu, ke via forkurado ne estu en vintro nek en sabato;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'ĉar tiam estos granda aflikto tia, kia ne estis de la komenco de la mondo ĝis nun, nek iam estos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'Kaj se tiuj tagoj ne estus mallongigitaj, neniu karno estus savita; sed pro la elektitoj tiuj tagoj estos mallongigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Tiam se iu diros al vi: Jen ĉi tie la Kristo, aŭ: Tie; ne kredu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'ĉar leviĝos falsaj kristoj kaj falsaj profetoj kaj faros grandajn signojn kaj miraklojn, tiel ke ili forlogus, se eble, eĉ la elektitojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Jen mi antaŭdiris al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Se oni do diros al vi: Jen li estas en la dezerto; ne eliru; aŭ: Jen li estas en sekretaj ĉambroj; ne kredu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Ĉar kiel la fulmo venas el la oriento kaj montriĝas ĝis la okcidento, tiel ankaŭ estos la alesto de la Filo de homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Kie ajn estos la kadavro, tien kolektiĝos la agloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'Sed tuj post la aflikto de tiuj tagoj la suno mallumiĝos, kaj la luno ne donos sian lumon, kaj la steloj falos el la ĉielo, kaj la potencoj de la ĉielo ŝanceliĝos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'kaj tiam aperos sur la ĉielo la signo de la Filo de homo, kaj tiam ploros ĉiuj gentoj de la tero, kaj oni vidos la Filon de homo, venantan en la nuboj de la ĉielo kun potenco kaj granda gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'Kaj li elsendos siajn anĝelojn kun granda sono de trumpeto, kaj ili kolektos liajn elektitojn el la kvar ventoj, el limo ĝis limo de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'De la figarbo lernu ĝian parabolon: kiam ĝia branĉo jam moliĝis kaj aperigas foliojn, tiam vi scias, ke la somero estas proksima;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'tiel same vi, kiam vi vidos ĉion tion, tiam sciu, ke li estas proksima, ĉe la pordoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Vere mi diras al vi: Ĉi tiu generacio ne forpasos, ĝis ĉio tio plenumiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'La ĉielo kaj la tero forpasos, sed miaj vortoj ne forpasos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'Sed pri tiu tago kaj la horo scias neniu, eĉ ne la anĝeloj de la ĉielo, nek la Filo, sed la Patro sola.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Sed kiel la tagoj de Noa, tiel estos la alesto de la Filo de homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Ĉar kiel dum la tagoj, kiuj estis antaŭ la diluvo, oni manĝis kaj trinkis, edziĝis kaj edziniĝis, ĝis la tago, kiam Noa eniris en la arkeon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'kaj oni ne eksciis, ĝis la diluvo venis kaj forprenis ĉiujn; tiel estos la alesto de la Filo de homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Tiam du viroj estos sur kampo: unu estos prenita, kaj la alia lasita;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'du virinoj estos muelantaj apud muelilo: unu estos prenita, kaj la alia lasita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Tial viglu; ĉar vi ne scias, en kiu tago via Sinjoro venos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Sed sciu tion, ke se la dommastro scius, en kiu gardoparto venos la ŝtelisto, li viglus kaj ne lasus sian domon trafosiĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Tial vi ankaŭ estu pretaj; ĉar en horo, kiam vi ne atendas, la Filo de homo venas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Kiu do estas la fidela kaj prudenta servisto, kiun la sinjoro starigis super siajn domanojn, por doni al ili nutraĵon ĝustatempe?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Feliĉa estas tiu servisto, kiun lia sinjoro, veninte, trovos tiel faranta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Vere mi diras al vi, ke super sian tutan havon li starigos lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Sed se tiu malbona servisto diros en sia koro: Mia sinjoro malfruas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'kaj komencos bati siajn kunservistojn, kaj manĝi kaj trinki kun la drinkuloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'la sinjoro de tiu servisto venos en tago, kiam li ne atendas, kaj en horo, kiam li ne scias,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'kaj distranĉos lin, kaj difinos lian parton kun la hipokrituloj; tie estos la plorado kaj la grincado de dentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Tiam la regno de la ĉielo estos komparata al dek virgulinoj, kiuj prenis siajn lampojn kaj eliris renkonte al la fianĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Kaj kvin el ili estis malprudentaj, kaj kvin estis prudentaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'La malprudentaj, prenante la lampojn, ne prenis oleon kun si;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'sed la prudentaj prenis oleon en la vazoj kun siaj lampoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Kaj kiam la fianĉo malfruis, ili ĉiuj malviglis kaj dormis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Sed je la noktomezo estis ekkrio: Jen la fianĉo! eliru al li renkonte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Tiam ĉiuj tiuj virgulinoj leviĝis, kaj ordigis siajn lampojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Kaj la malprudentaj diris al la prudentaj: Donu al ni el via oleo, ĉar niaj lampoj estingiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Sed la prudentaj respondis, dirante: Eble ne estos sufiĉe por ni kaj vi; iru prefere al la vendistoj, kaj aĉetu por vi mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Kaj dum ili iris, por aĉeti, alvenis la fianĉo; kaj tiuj, kiuj estis pretaj, eniris kun li al la edziĝa festo, kaj la pordo estis fermita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Poste venis ankaŭ la ceteraj virgulinoj, dirante: Sinjoro, sinjoro, malfermu al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Sed li responde diris: Vere mi diras al vi: Mi vin ne konas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Tial viglu, ĉar vi ne scias la tagon nek la horon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Ĉar tiel estas, kvazaŭ viro, forvojaĝonte, alvokis siajn servistojn, kaj komisiis al ili siajn posedaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'Kaj al unu li donis kvin talantojn, al alia du, al alia unu; al ĉiu laŭ lia kapableco; kaj li tuj forvojaĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Kaj tiu, kiu ricevis la kvin talantojn, iris kaj negocadis per ili, kaj gajnis pluajn kvin talantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'Tiel same ankaŭ tiu, kiu ricevis la du, gajnis pluajn du.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Sed tiu, kiu ricevis la unu, foriris kaj fosis en la tero, kaj kaŝis la monon de sia sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Kaj post longa tempo la sinjoro de tiuj servistoj venis, kaj faris kun ili kalkulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'Kaj tiu, kiu ricevis la kvin talantojn, venis kaj alportis pluajn kvin talantojn, dirante: Sinjoro, vi komisiis al mi kvin talantojn; jen mi gajnis pluajn kvin talantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Lia sinjoro diris al li: Bone, vi bona kaj fidela servisto; vi estis fidela pri malmultaj aferoj, mi starigos vin super multaj; envenu en la ĝojon de via sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Kaj venis ankaŭ tiu, kiu ricevis la du talantojn, kaj diris: Sinjoro, vi komisiis al mi du talantojn; jen mi gajnis pluajn du talantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Lia sinjoro diris al li: Bone, vi bona kaj fidela servisto; vi estis fidela pri malmultaj aferoj, mi starigos vin super multaj; envenu en la ĝojon de via sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Kaj venis ankaŭ tiu, kiu ricevis la unu talanton, kaj diris: Sinjoro, mi sciis, ke vi estas severa homo, rikoltanta, kie vi ne semis, kaj kolektanta, kie vi ne disŝutis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'kaj mi timis, kaj foriris, kaj kaŝis vian talanton en la tero; jen vi havas vian propraĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Sed lia sinjoro responde diris al li: Vi malbona kaj mallaborema servisto, vi sciis, ke mi rikoltas, kie mi ne semis, kaj kolektas, kie mi ne disŝutis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'pro tio vi devus doni mian monon al la bankistoj, kaj veninte, mi ricevus mian propraĵon kun procento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Forprenu de li do la talanton, kaj donu ĝin al tiu, kiu havas la dek talantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'Ĉar al ĉiu, kiu havas, estos donite, kaj li havos abundegon; sed for de tiu, kiu ne havas, eĉ tio, kion li havas, estos prenita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'Kaj elĵetu la senutilan serviston en la eksteran mallumon; tie estos la plorado kaj la grincado de dentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'Sed kiam la Filo de homo venos en sia gloro, kaj ĉiuj anĝeloj kun li, tiam li sidos sur la trono de sia gloro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'kaj antaŭ li kolektiĝos ĉiuj nacioj, kaj li apartigos ilin unu de alia, kiel paŝtisto apartigas la ŝafojn for de la kaproj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'kaj li starigos la ŝafojn dekstre de li, kaj la kaprojn maldekstre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Tiam diros la Reĝo al tiuj, kiuj staras dekstre de li: Venu, vi benataj de mia Patro, heredu la regnon preparitan por vi de post la komenco de la mondo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'ĉar mi malsatis, kaj vi donis al mi manĝi; mi soifis, kaj vi donis al mi trinki; mi estis fremda, kaj vi gastigis min;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'nuda, kaj vi vestis min; mi malsanis, kaj vi vizitis min; mi estis en malliberejo, kaj vi venis al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Tiam respondos al li la justuloj, dirante: Sinjoro, kiam ni vin vidis malsata, kaj vin satigis? aŭ soifanta, kaj trinkigis vin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'Kaj kiam ni vidis vin fremda kaj gastigis vin? aŭ nuda, kaj vin vestis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Kaj kiam ni vidis vin malsana aŭ en malliberejo, kaj venis al vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'Kaj la Reĝo respondos kaj diros al ili: Vere mi diras al vi: Kiom vi faris al unu el ĉi tiuj miaj fratoj la plej malgrandaj, tiom vi faris al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Tiam li diros al tiuj, kiuj staras maldekstre: For de mi, vi malbenitaj, en la eternan fajron, kiu estas preparita por la diablo kaj liaj anĝeloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'ĉar mi malsatis, kaj vi ne donis al mi manĝi; mi soifis, kaj vi ne donis al mi trinki;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'mi estis fremda, kaj vi ne gastigis min; nuda, kaj vi ne vestis min; malsana kaj en malliberejo, kaj vi ne vizitis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Tiam ili ankaŭ respondos, dirante: Sinjoro, kiam ni vidis vin malsata, aŭ soifanta, aŭ fremda, aŭ nuda, aŭ malsana, aŭ en malliberejo, kaj ne servis al vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Tiam li respondos al ili, dirante: Vere mi diras al vi: Kiom vi ne faris al unu el ĉi tiuj la plej malgrandaj, tiom vi ne faris al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'Kaj ĉi tiuj foriros en eternan punon, sed la justuloj en eternan vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'Kaj kiam Jesuo finis ĉiujn tiujn vortojn, li diris al siaj disĉiploj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, 'Vi scias, ke post du tagoj okazos la Pasko, kaj la Filo de homo estos transdonita, por esti krucumita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Tiam kunvenis la ĉefpastroj kaj la pliaĝuloj de la popolo, en la korto de la ĉefpastro, kies nomo estis Kajafas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'kaj ili konsiliĝis, por ke ili povu per ruzo kapti Jesuon, kaj mortigi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Sed ili diris: Ne dum la festo, por ke ne leviĝu tumulto ĉe la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Kaj kiam Jesuo estis en Betania, en la domo de Simon, leprulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'venis al li virino, havanta alabastran vazon da multekosta ŝmiraĵo, kaj ŝi verŝis ĝin sur lian kapon, dum li sidis ĉe manĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Sed kiam la disĉiploj tion vidis, ili indignis, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Por kio estas ĉi tiu malŝparo? Ĉar ĉi tiun ŝmiraĵon oni povus vendi por granda prezo, kaj doni al malriĉuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Sed Jesuo, tion sciante, diris al ili: Kial vi ĝenas la virinon? ŝi faris bonan faron al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Ĉar la malriĉulojn vi ĉiam havas kun vi, sed min vi ne ĉiam havas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Ĉar verŝante ĉi tiun ŝmiraĵon sur mian korpon, ŝi tion faris por mia entombigo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Vere mi diras al vi: Kie ajn estos predikata ĉi tiu evangelio en la tuta mondo, tio ankaŭ, kion faris ĉi tiu virino, estos priparolata, por memoraĵo de ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Tiam unu el la dek du, nomata Judas Iskariota, iris al la ĉefpastroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'kaj diris: Kion vi volas doni al mi, se mi lin transdonos al vi? Kaj ili pesis por li tridek arĝentajn monerojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'Kaj de tiam li serĉis okazon, por transdoni lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'Kaj en la unua tago de macoj la disĉiploj venis al Jesuo, dirante: Kie vi volas, ke ni pretigu por vi, por manĝi la Paskon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'Kaj li diris: Iru en la urbon al trovotulo, kaj diru al li: La Majstro diras: Mia tempo estas proksima; mi faros la Paskon ĉe vi, kun miaj disĉiploj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'Kaj la disĉiploj faris, kiel Jesuo ordonis al ili, kaj ili pretigis la Paskon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Kaj kiam vesperiĝis, li sidis ĉe manĝo kun la dek du disĉiploj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'kaj dum ili manĝis, li diris: Vere mi diras al vi, ke unu el vi perfidos min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'Kaj ili tre malĝojis, kaj ĉiu komencis diri al li: Sinjoro, ĉu eble mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'Kaj li respondis kaj diris: Tiu, kiu trempis kun mi la manon en la pladon, perfidos min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'La Filo de homo iros, kiel estas skribite pri li; sed ve al tiu viro, de kiu la Filo de homo estos perfidita! se tiu homo ne estus naskita, estus bone por li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Kaj Judas, kiu estis lin perfidonta, responde diris: Ĉu eble mi, Rabeno? Li diris al li: Vi diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'Kaj dum ili manĝis, Jesuo prenis panon, kaj beninte, dispecigis ĝin kaj donis al la disĉiploj, kaj diris: Prenu, manĝu; ĉi tio estas mia korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'Kaj li prenis kalikon, kaj doninte dankon, donis al ili, dirante: Vi ĉiuj trinku el ĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'ĉar ĉi tio estas mia sango de la interligo, kiu estas elverŝata por multaj, por la pardonado de pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Sed mi diras al vi: De nun mi ne trinkos el ĉi tiu frukto de la vinberarbo, ĝis tiu tago, kiam mi trinkos ĝin novan kun vi en la regno de mia Patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'Kaj kantinte himnon, ili foriris al la monto Olivarba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Tiam diris Jesuo al ili: Vi ĉiuj ofendiĝos pro mi dum ĉi tiu nokto; ĉar estas skribite: Mi frapos la paŝtiston, kaj la ŝafoj de la grego diskuros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Tamen, post mia releviĝo mi iros antaŭ vi en Galileon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Sed Petro responde diris al li: Eĉ se ĉiuj ofendiĝos pro vi, mi neniam ofendiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Jesuo diris al li: Vere mi diras al vi, ke en ĉi tiu nokto, antaŭ ol krios koko, vi trifoje malkonfesos min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Petro diris al li: Eĉ se mi devos morti kun vi, mi neniel vin malkonfesos. Tiel same diris ĉiuj disĉiploj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Tiam venis Jesuo kun ili al loko nomata Getsemane, kaj diris al siaj disĉiploj: Sidiĝu ĉi tie, dum mi iros tien, por preĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'Kaj li prenis kun si Petron kaj la du filojn de Zebedeo, kaj komencis malĝoji kaj maltrankviliĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Tiam li diris al ili: Tre malĝoja estas mia animo, eĉ ĝis morto; restu ĉi tie, kaj viglu kun mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'Kaj irinte iom antaŭen, li falis sur sian vizaĝon, preĝante, kaj dirante: Ho mia Patro, se povas esti, ĉi tiu kaliko pasu for de mi; tamen ne kiel mi volas, sed kiel Vi volas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Kaj li venis al la disĉiploj kaj trovis ilin dormantaj, kaj diris al Petro: Ĉu vi do ne havis forton vigli kun mi eĉ unu horon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Viglu kaj preĝu, por ke vi ne eniru en tenton; la spirito ja estas fervora, sed la karno estas malforta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Denove la duan fojon foririnte, li preĝis, dirante: Ho mia Patro, se ĉi tio ne povos forpasi, krom se mi trinkos ĝin, Via volo plenumiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'Kaj denove reveninte, li trovis ilin dormantaj, ĉar iliaj okuloj peziĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'Kaj li denove lasis ilin kaj foriris, kaj la trian fojon preĝis, denove dirante la samajn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Tiam li venis al la disĉiploj, kaj diris al ili: Dormu nun kaj ripozu: jen la horo alproksimiĝis, kaj la Filo de homo estas perfidata en la manojn de pekuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Leviĝu, ni iru; jen mia perfidanto alproksimiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'Kaj dum li ankoraŭ parolis, jen venis Judas, unu el la dek du; kaj kun li granda homamaso kun glavoj kaj bastonoj venis de la ĉefpastroj kaj pliaĝuloj de la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Kaj lia perfidanto jam aranĝis kun ili signon, dirante: Kiun mi kisos, tiu estas li; kaptu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'Kaj tuj veninte al Jesuo, li diris: Saluton, Rabeno; kaj kisis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Kaj Jesuo diris al li: Amiko, por kio vi venis? Tiam ili venis, kaj metis manojn sur Jesuon kaj arestis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'Kaj jen unu el tiuj, kiuj estis kun Jesuo, etendis sian manon kaj eltiris sian glavon, kaj frapis la sklavon de la ĉefpastro, kaj detranĉis lian orelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Tiam diris Jesuo al li: Remetu vian glavon en ĝian ingon; ĉar ĉiuj, kiuj glavon prenas, per glavo pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Ĉu vi do supozas, ke mi ne povas alvoki mian Patron, kaj Li tuj liveros al mi pli ol dek du legiojn da anĝeloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Sed kiel plenumiĝus la Skriboj, ke tiel devas okazi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'En tiu horo Jesuo diris al la homamasoj: Ĉu vi elvenis kvazaŭ kontraŭ rabiston, kun glavoj kaj bastonoj, por kapti min? Ĉiutage mi sidis en la templo, instruante, kaj vi ne arestis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Sed ĉio tio okazis, por ke plenumiĝu la Skriboj de la profetoj. Tiam ĉiuj disĉiploj forlasis lin kaj forkuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Kaj la arestintoj de Jesuo forkondukis lin al la domo de la ĉefpastro Kajafas, kie jam kolektiĝis la skribistoj kaj pliaĝuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Sed Petro malproksime sekvis lin ĝis la korto de la ĉefpastro, kaj eniris, kaj sidis kun la subuloj, por vidi la finon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Kaj la ĉefpastroj kaj la tuta sinedrio serĉis malveran ateston kontraŭ Jesuo, por ke ili povu lin mortigi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'kaj ne trovis, kvankam multaj malveraj atestantoj venis. Sed poste venis du, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'Ĉi tiu diris: Mi povas detrui la sanktejon de Dio, kaj rekonstrui ĝin en la daŭro de tri tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'Kaj la ĉefpastro stariĝis, kaj diris al li: Ĉu vi respondas nenion? kion atestas ĉi tiuj kontraŭ vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Sed Jesuo silentadis. Kaj la ĉefpastro diris al li: Mi ĵurligas vin per Dio la vivanta, ke vi diru al ni, ĉu vi estas la Kristo, la Filo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Jesuo diris al li: Vi diris; tamen mi diras al vi: Poste vi vidos la Filon de homo, sidantan ĉe la dekstra mano de la Potenco, kaj venantan sur la nuboj de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Tiam la ĉefpastro disŝiris siajn vestojn, dirante: Li blasfemis; por kio ni plu bezonas atestantojn? jen nun vi aŭdis la blasfemon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'kion vi opinias? Ili respondis kaj diris: Li estas kondamninda al morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Tiam oni kraĉis sur lian vizaĝon kaj vangofrapis lin, kaj iuj frapis lin per la manplatoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'dirante: Profetu al ni, ho Kristo, kiu vin frapis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Kaj Petro sidis ekstere sur la korto; kaj venis al li unu servantino, dirante: Vi ankaŭ estis kun Jesuo, la Galileano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Sed li malkonfesis antaŭ ili ĉiuj, dirante: Mi ne scias, kion vi diras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'Kaj post kiam li eliris en la vestiblon, alia vidis lin, kaj diris al la ĉeestantoj: Ĉi tiu estis ankaŭ kun Jesuo, la Nazaretano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'Kaj denove li malkonfesis kun ĵuro: Mi ne konas tiun homon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Kaj post iom da tempo la apudstarantoj venis, kaj diris al Petro: Vere vi ankaŭ estas el ili, ĉar via parolmaniero malkaŝas vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Tiam li komencis malbeni kaj ĵuri: Mi ne konas tiun homon. Kaj tuj koko kriis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'Kaj Petro rememoris la vorton, kiun Jesuo parolis: Antaŭ ol krios koko, vi trifoje malkonfesos min. Kaj li eliris, kaj maldolĉe ploris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'Kaj kiam venis la mateno, ĉiuj ĉefpastroj kaj pliaĝuloj de la popolo konsiliĝis kontraŭ Jesuo, por mortigi lin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'kaj ili ligis lin, kaj forkondukis lin kaj transdonis lin al Pilato, la provincestro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Tiam Judas, lia perfidinto, vidinte, ke li estas kondamnita, pentis, kaj reportis la tridek arĝentajn monerojn al la ĉefpastroj kaj la pliaĝuloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'dirante: Mi pekis, perfidante senkulpan sangon. Sed ili diris: Kiel tio koncernas nin? vi zorgu pri tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Kaj li ĵetis la arĝentajn monerojn en la sanktejon, kaj eliris; kaj foririnte, pendigis sin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Kaj la ĉefpastroj prenis la arĝentajn monerojn, kaj diris: Ne konvenas meti ilin en la trezorejon, ĉar tio estas prezo de sango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'Kaj ili konsiliĝis, kaj aĉetis per ili la kampon de la potisto, por enterigi fremdulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Tial tiu kampo estas nomata Kampo de Sango, ankoraŭ ĝis hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Tiam plenumiĝis tio, kio estis dirita per la profeto Jeremia, nome: Kaj ili prenis la tridek arĝentajn monerojn, taksoprezon de tiu, kiu estis taksita, kiujn iuj el la filoj de Izrael taksis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'kaj donis ilin por la kampo de la potisto, kiel la Eternulo difinis al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Kaj Jesuo staris antaŭ la provincestro; kaj la estro demandis lin, dirante: Ĉu vi estas la Reĝo de la Judoj? Kaj Jesuo diris al li: Vi diras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'Kaj kiam la ĉefpastroj kaj pliaĝuloj akuzis lin, li respondis nenion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Tiam Pilato diris al li: Ĉu vi ne aŭdas, kiom da aferoj oni atestas kontraŭ vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Kaj li ne respondis al li eĉ unu vorton, tiel ke la provincestro tre forte miris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Sed ĉe tiu festo la provincestro kutimis liberigi al la homamaso unu malliberulon, kiun ili deziris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Kaj oni havis tiam faman malliberulon, nomatan Barabas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Kiam do ili kolektiĝis, Pilato diris al ili: Kiun vi deziras, ke mi liberigu al vi? ĉu Barabason, aŭ Jesuon, nomatan Kristo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Ĉar li sciis, ke pro envio ili transdonis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'Kaj dum li sidis sur la tribunala seĝo, lia edzino sendis al li, por diri: Nenion havu kun tiu justulo, ĉar mi suferis multe hodiaŭ en sonĝo kaŭze de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Kaj la ĉefpastroj kaj pliaĝuloj decidigis la homamason postuli Barabason kaj pereigi Jesuon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Sed la provincestro responde diris al ili: Kiun el la du vi volas, ke mi liberigu al vi? Kaj ili diris: Barabason.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Pilato diris al ili: Kion do mi faros al Jesuo, nomata Kristo? Ĉiuj diris: Li estu krucumita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'Kaj li diris: Kial? kian malbonon li faris? Sed ili des pli ekkriis, dirante: Li estu krucumita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Tial Pilato, vidante, ke neniel prosperas al li, sed ke kontraŭe tumulto leviĝas, prenis akvon kaj lavis siajn manojn antaŭ la homamaso, dirante: Mi estas senkulpa pri la sango de tiu justulo: vi zorgu pri ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'Kaj la tuta popolo responde diris: Lia sango estu sur ni kaj sur niaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Tiam li liberigis al ili Barabason; sed skurĝinte Jesuon, li transdonis lin, por esti krucumita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Tiam la soldatoj de la provincestro, kondukinte Jesuon en la palacon, kolektis al li la tutan kohorton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'Kaj ili senvestigis lin, kaj surmetis al li skarlatan mantelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'Kaj ili plektis kronon el dornoj kaj metis ĝin sur lian kapon, kaj metis kanon en lian dekstran manon; kaj ili genuis antaŭ li, kaj mokis lin, dirante: Saluton, Reĝo de la Judoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'Kaj ili kraĉis sur lin, kaj prenis la kanon kaj frapis lian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'Kaj mokinte lin, ili demetis de li la mantelon, kaj surmetis al li liajn proprajn vestojn, kaj forkondukis lin, por krucumi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'Kaj elirinte, ili trovis viron Kirenanon, nomatan Simon; tiun ili devigis, ke li portu lian krucon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'Kaj veninte al loko nomata Golgota, tio estas, Loko de Kranio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'ili donis al li trinki vinon kun galo enmiksita; kaj li gustumis ĝin, kaj ne volis trinki.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'Kaj krucuminte lin, ili dividis inter si liajn vestojn, ĵetante lotojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'kaj ili sidiĝis, kaj gardis lin tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'Kaj ili metis super lia kapo lian akuzon, skribitan: ĈI TIU ESTAS JESUO, LA REĜO DE LA JUDOJ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Tiam kun li estis krucumitaj du rabistoj, unu dekstre kaj unu maldekstre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Kaj la preterpasantoj insultis lin, balancante la kapon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'kaj dirante: Vi, kiu detruas la sanktejon kaj rekonstruas ĝin en la daŭro de tri tagoj, savu vin. Se vi estas la Filo de Dio, deiru de la kruco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Tiel same ankaŭ la ĉefpastroj, mokante kun la skribistoj kaj la pliaĝuloj, diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, 'Aliajn li savis; sin mem li ne povas savi. Li ja estas Reĝo de Izrael, li nun deiru de la kruco, kaj ni kredos al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Li apogis sin al Dio; Tiu savu lin, se Li amas lin; ĉar li diris: Mi estas la Filo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Kaj ankaŭ la rabistoj, kiuj estis krucumitaj kun li, tiel same insultis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Kaj de post la sesa horo fariĝis mallumo sur la tuta lando ĝis la naŭa horo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'Kaj ĉirkaŭ la naŭa horo Jesuo ekkriis per laŭta voĉo, dirante: Eli, Eli, lama sabaĥtani? tio estas: Mia Dio, mia Dio, kial Vi forlasis min?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Kaj iuj el la apudstarantoj, aŭdinte tion, diris: Ĉi tiu vokas Elijan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'Kaj tuj unu el ili kuris kaj prenis spongon kaj plenigis ĝin per vinagro, kaj metinte ĝin sur kanon, donis al li trinki.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Kaj la aliaj diris: Lasu; ni vidu, ĉu venos Elija, por savi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Kaj Jesuo, denove kriinte per laŭta voĉo, ellasis for la spiriton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'Kaj jen la kurteno de la sanktejo disŝiriĝis en du pecojn de supre ĝis malsupre; kaj la tero tremis; kaj la rokoj diskrevis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'kaj la tomboj malfermiĝis, kaj multaj korpoj de dormantaj sanktuloj leviĝis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'kaj elirinte el la tomboj post lia releviĝo, ili eniris en la sanktan urbon kaj aperis al multaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Kaj la centestro, kaj tiuj, kiuj estis kun li gardantaj Jesuon, kiam ili vidis la tertremon kaj la okazantaĵojn, tre timis, dirante: Vere ĉi tiu estis Filo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Kaj tie estis multaj virinoj, rigardantaj de malproksime, kiuj sekvis Jesuon el Galileo, servante al li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'inter kiuj estis Maria Magdalena, kaj Maria, la patrino de Jakobo kaj de Joses, kaj la patrino de la filoj de Zebedeo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Kaj kiam vesperiĝis, venis riĉulo, nomata Jozef, el Arimateo, kiu mem estis disĉiplo de Jesuo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'tiu, irinte al Pilato, petis la korpon de Jesuo. Tiam Pilato ordonis doni ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'Kaj Jozef prenis la korpon, kaj envolvis ĝin en pura tolaĵo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'kaj metis ĝin en sian novan tombon, kiun li jam elhakis en la roko; kaj li alrulis grandan ŝtonon al la enirejo de la tombo, kaj foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'Kaj Maria Magdalena estis tie, kaj la alia Maria, sidantaj apud la tombo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'La sekvantan tagon, kiu estas la tago post la Preparado, la ĉefpastroj kaj la Fariseoj kolektiĝis al Pilato,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'dirante: Sinjoro, ni ekrememoras, ke tiu trompanto diris, dum li ankoraŭ vivis: Post tri tagoj mi releviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Ordonu do, ke oni gardu la tombon ĝis la tria tago, por ke liaj disĉiploj ne venu kaj ne forŝtelu lin kaj ne diru al la popolo: Li releviĝis el la mortintoj; kaj la lasta trompo estus pli malbona, ol la unua.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Pilato diris al ili: Vi havas gardistaron; iru, kaj gardu ĝin laŭ via eblo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'Tial ili foriris kaj gardis la tombon, sigelinte la ŝtonon, kune kun gardistaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'Kaj sabate malfrue, kiam eklumis por la unua tago de la semajno, venis Maria Magdalena kaj la alia Maria, por vidi la tombon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'Kaj jen okazis granda tertremo; ĉar anĝelo de la Eternulo malsupreniris el la ĉielo, kaj venis kaj derulis la ŝtonon, kaj sidiĝis sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'Lia aspekto estis kiel fulmo, kaj lia vestaĵo estis blanka, kiel neĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'kaj pro timo al li la gardistoj tremis, kaj fariĝis kiel malvivuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Kaj la anĝelo responde diris al la virinoj: Ne timu; ĉar mi scias, ke vi serĉas Jesuon, la krucumitan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Li ne estas ĉi tie; ĉar li leviĝis, kiel li diris. Venu, vidu la lokon, kie la Sinjoro kuŝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'Kaj iru rapide, kaj diru al liaj disĉiploj: Li leviĝis el la mortintoj, kaj jen li iras antaŭ vi en Galileon; tie vi vidos lin; jen mi sciigis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'Kaj ili rapide foriris de la tombo kun timo kaj granda ĝojo, kaj kuris, por sciigi al liaj disĉiploj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'Kaj jen Jesuo renkontis ilin, dirante: Saluton. Kaj alveninte, ili ekprenis liajn piedojn kaj adorkliniĝis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Tiam Jesuo diris al ili: Ne timu; iru, diru al miaj fratoj, ke ili foriru en Galileon, kaj tie ili min vidos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'Kaj dum ili iris, iuj el la gardistoj venis en la urbon, kaj rakontis al la ĉefpastroj ĉiujn okazintaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Kaj kunveninte kun la pliaĝuloj, ili konsiliĝis kune, kaj ili donis al la soldatoj multe da mono,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'dirante: Diru: Liaj disĉiploj venis nokte, kaj forŝtelis lin, dum ni dormis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'Kaj se la provincestro tion aŭdos, ni konvinkos lin, kaj liberigos vin de ĉia zorgo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Kaj ili prenis la monon, kaj faris, kiel ili estis instruitaj; kaj tiu diro disvastiĝis inter la Judoj ĝis hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Sed la dek unu disĉiploj iris en Galileon, sur la monton, kiun Jesuo jam difinis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'Kaj kiam ili vidis lin, ili adorkliniĝis al li; sed kelkaj dubis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'Kaj Jesuo venis al ili, kaj diris al ili: Estas donita al mi ĉia aŭtoritato en la ĉielo kaj sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Iru do kaj disĉipligu ĉiujn naciojn, baptante ilin en la nomon de la Patro kaj de la Filo kaj de la Sankta Spirito;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'instruante ilin observi ĉion, kion mi ordonis al vi. Kaj jen mi estas kun vi ĉiujn tagojn, ĝis la maturiĝo de la mondaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'La komenco de la evangelio de Jesuo Kristo, Filo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Kiel estas skribite en la profeto Jesaja: Jen Mi sendas Mian anĝelon antaŭ via vizaĝo, Kaj li preparos vian vojon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Voĉo de krianto en la dezerto: Pretigu la vojon de la Eternulo, Rektigu Liajn irejojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'venis Johano, kiu baptis en la dezerto kaj predikis la bapton de pento por la pardonado de pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Kaj eliris al li la tuta Juduja distrikto, kaj ĉiuj Jerusalemanoj; kaj ili estis baptitaj de li en la rivero Jordan, konfesante siajn pekojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Kaj Johano estis vestita per kamelharaĵo kaj leda zono ĉirkaŭ siaj lumboj, kaj li manĝadis akridojn kaj sovaĝan mielon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Kaj li predikis, dirante: Venas post mi tiu, kiu estas pli potenca ol mi; la rimenon de liaj ŝuoj mi ne estas inda, kliniĝinte, malligi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Mi vin baptis per akvo; sed li vin baptos per la Sankta Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'Kaj en tiuj tagoj Jesuo venis el Nazaret de Galileo, kaj estis baptita de Johano en Jordan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Kaj tuj kiam li eliris el la akvo, li vidis la ĉielon fenditan, kaj la Spiriton kiel kolombo malsuprenirantan sur lin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'kaj venis voĉo el la ĉielo: Vi estas Mia Filo, la amata, en kiu Mi havas plezuron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Kaj tuj la Spirito pelis lin for en la dezerton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'Kaj li estis en la dezerto kvardek tagojn, tentata de Satano; kaj li estis kun la sovaĝaj bestoj, kaj la anĝeloj servadis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Kaj post kiam Johano estis arestita, Jesuo iris en Galileon, predikante la evangelion de Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'kaj dirante: La tempo jam plenumiĝis, kaj la regno de Dio alproksimiĝis; pentu, kaj kredu al la evangelio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Kaj irante apud la Galilea Maro, li vidis Simonon, kaj Andreon, fraton de Simon, ĵetantajn reton en la maron; ĉar ili estis fiŝkaptistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'Kaj Jesuo diris al ili: Venu post mi, kaj mi igos vin fariĝi kaptistoj de homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'Kaj ili tuj forlasis la retojn, kaj sekvis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'Kaj irinte iom antaŭen, li vidis Jakobon, filon de Zebedeo, kaj Johanon, lian fraton, kiuj ankaŭ estis en la ŝipeto, riparante la retojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'Kaj tuj li alvokis ilin; kaj ili lasis sian patron Zebedeo en la ŝipeto kun la dungitoj, kaj foriris post li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'Kaj ili iris en Kapernaumon, kaj tuj en la sabato li eniris en la sinagogon kaj instruis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'Kaj oni miris pro lia instruado; ĉar li instruis kiel havanta aŭtoritaton, kaj ne kiel la skribistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'Kaj en ilia sinagogo estis viro kun malpura spirito; kaj li ekkriis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'dirante: Kio estas inter ni kaj vi, Jesuo Nazaretano? ĉu vi venis, por pereigi nin? mi scias, kiu vi estas: la Sanktulo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'Kaj Jesuo severe admonis lin, dirante: Silentu, kaj eliru el li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'Kaj la malpura spirito konvulsiigis lin, kaj, laŭte kriinte, eliris el li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'Kaj ĉiuj miregis tiom, ke ili diskutis inter si, dirante: Kio estas ĉi tio? jen nova instruado! kun aŭtoritato li ordonas eĉ al la malpuraj spiritoj, kaj ili obeas lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'Kaj tuj la famo pri li disvastiĝis ĉie en la tutan ĉirkaŭaĵon de Galileo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'Kaj tuj, elirinte el la sinagogo, ili eniris en la domon de Simon kaj Andreo, kun Jakobo kaj Johano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'Sed la bopatrino de Simon kuŝis malsana de febro; kaj tuj oni sciigis al li pri ŝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'kaj veninte, li prenis ŝian manon kaj levis ŝin; kaj la febro forlasis ŝin, kaj ŝi servis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Kaj vespere, kiam la suno subiris, oni venigis al li ĉiujn, kiuj estis malsanaj kaj demonhavantaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'Kaj la tuta urbo kolektiĝis ĉe la pordo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'Kaj li sanigis multajn, kiuj malsanis de diversaj malsanoj, kaj elpelis multajn demonojn; kaj li ne permesis al la demonoj paroli, ĉar ili konis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'Kaj matene, antaŭ ol la nokto pasis, li leviĝis, kaj foriris en dezertan lokon, kaj tie preĝadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Kaj Simon kaj liaj kunuloj elserĉis lin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'kaj ili trovis lin, kaj diris al li: Ĉiuj vin serĉas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Kaj li diris al ili: Ni iru aliloken en la proksimajn urbetojn, por ke mi tie ankaŭ prediku; ĉar por tio mi venis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'Kaj li iris, predikante en iliaj sinagogoj tra la tuta Galileo, kaj elpelante la demonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Kaj venis al li leprulo, alvokante lin, kaj genuinte, li diris al li: Se vi nur volas, vi povas min purigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'Kaj kortuŝite, li etendis la manon kaj tuŝis lin, kaj diris al li: Mi volas; estu purigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'Kaj tuj la lepro foriris de li, kaj li fariĝis pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'Kaj severe avertinte lin, li tuj forsendis lin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'kaj diris al li: Zorgu, ke vi diru nenion al iu; sed iru, montru vin al la pastro, kaj oferu pro via purigado tion, kion Moseo ordonis, por atesto al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Sed li eliris, kaj komencis diligente rakonti kaj disfamigi la aferon, tiel ke Jesuo jam ne povis malkaŝe eniri en urbon, sed restis ekstere en dezertaj lokoj; kaj oni venis al li el ĉie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Kaj kiam li revenis en Kapernaumon post kelke da tagoj, oni sciiĝis, ke li estas en domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'Kaj multaj kunvenis, tiel ke jam ne estis loko eĉ apud la pordo; kaj li parolis al ili la vorton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Kaj oni venis, alportante al li paralizulon, portatan de kvar homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Kaj ne povante alproksimiĝi al li pro la homamaso, ili malkovris la tegmenton, kie li estis; kaj trafosinte ĝin, ili mallevis la liton, sur kiu kuŝis la paralizulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Kaj Jesuo, vidante ilian fidon, diris al la paralizulo: Filo, viaj pekoj estas pardonitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Sed estis iuj el la skribistoj tie, sidantaj kaj diskutantaj en siaj koroj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Kial tiu tiel parolas? li blasfemas: kiu povas pardoni pekojn, krom Dio sola?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Kaj Jesuo, tuj eksciante en sia spirito, ke tiel ili diskutas en si, diris al ili: Kial vi tion diskutas en viaj koroj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Kio estas pli facila: diri al la paralizulo: Viaj pekoj estas pardonitaj; aŭ diri: Leviĝu, prenu vian liton, kaj piediru?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Sed por ke vi sciu, ke la Filo de homo havas aŭtoritaton sur la tero pardoni pekojn-li diris al la paralizulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'Mi diras al vi: Leviĝu, prenu vian liton, kaj iru al via domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Kaj li leviĝis, kaj tuj prenis la liton, kaj eliris antaŭ ĉiuj, tiel ke ĉiuj miregis, kaj gloris Dion, dirante: Neniam ni vidis ion tian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Kaj denove li eliris al la marbordo, kaj la tuta homamaso venis al li, kaj li instruis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Kaj preterpasante, li vidis Levin, filon de Alfeo, sidantan ĉe la impostejo, kaj li diris al li: Sekvu min. Kaj li stariĝis, kaj sekvis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'Kaj li sidis ĉe manĝo en lia domo, kaj multaj impostistoj kaj pekuloj kunsidis kun Jesuo kaj liaj disĉiploj; ĉar ili estis multaj, kaj ili sekvis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Kaj la skribistoj kaj la Fariseoj, vidante, ke li manĝas kun la pekuloj kaj la impostistoj, diris al liaj disĉiploj: Li manĝas kaj trinkas kun impostistoj kaj pekuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Kaj aŭdinte tion, Jesuo diris al ili: Ne la sanuloj bezonas kuraciston, sed la malsanuloj: mi venis, por alvoki ne justulojn, sed pekulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Kaj la disĉiploj de Johano kaj la Fariseoj estis fastantaj, kaj oni venis, kaj diris al li: Kial fastas la disĉiploj de Johano kaj de la Fariseoj, sed viaj ne fastas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Kaj Jesuo diris al ili: Ĉu la filoj de la edziĝejo povas fasti, dum la fianĉo estas kun ili? Tiel longe, kiel ili havas kun si la fianĉon, ili ne povas fasti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Sed venos tagoj, kiam la fianĉo estos prenita for de ili, kaj tiam ili fastos en tiuj tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Neniu alkudras flikaĵon el nefulita drapo sur malnovan veston; alie la nova plenigaĵo ion forprenas de la malnova ŝtofo, kaj pli malbona ŝiraĵo fariĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'Kaj neniu enverŝas novan vinon en malnovajn felsakojn; alie la vino krevigos la felsakojn, kaj la vino elfluos kaj la felsakoj detruiĝos; sed oni enverŝas novan vinon en novajn felsakojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'Kaj en sabato li iris tra la grenkampoj, kaj liaj disĉiploj komencis dum la vojiro deŝiri la spikojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Kaj la Fariseoj diris al li: Jen kial ili en la sabato faras tion, kio ne estas permesata?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Kaj li diris al ili: Ĉu vi neniam legis, kion faris David, kiam li havis bezonon kaj malsatis, li kaj liaj kunuloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'Ke li eniris en la domon de Dio, kiam Ebjatar estis ĉefpastro, kaj manĝis la panojn de propono, kiujn manĝi ne estas permesate krom al la pastroj, kaj donis ankaŭ al siaj kunuloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'Kaj li diris al ili: La sabato estiĝis por la homo, kaj ne la homo por la sabato;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'tial la Filo de homo estas sinjoro eĉ de la sabato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Kaj denove li eniris en la sinagogon, kaj tie estis viro, havanta manon velkintan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'Kaj oni observis lin, ĉu en la sabato li lin sanigos, por ke ili povu lin akuzi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Kaj li diris al la viro, kiu havis la velkintan manon: Stariĝu en la mezo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Kaj li diris al ili: Ĉu estas permesate bonfari en sabato, aŭ malbonfari? savi vivon, aŭ mortigi? Sed ili silentis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Kaj kiam kun kolero li ĉirkaŭrigardis ilin, ĉagrenite pro la obstiniĝo de ilia koro, li diris al la viro: Etendu vian manon. Kaj li etendis ĝin, kaj lia mano resaniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Kaj la Fariseoj eliris, kaj tuj konsiliĝis kun la Herodanoj kontraŭ li, kiamaniere lin pereigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Kaj Jesuo kun siaj disĉiploj foriris ĝis la maro; kaj granda homamaso el Galileo sekvis lin. Kaj el Judujo');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'kaj el Jerusalem kaj el Edom kaj el Transjordano kaj el ĉirkaŭ Tiro kaj Cidon, grandnombra homamaso, aŭdinte ĉion, kion li faris, venis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Kaj li diris al siaj disĉiploj, ke malgranda ŝipeto estu je lia dispono, pro la homamaso, por ke oni ne premu lin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'ĉar multajn li jam sanigis, tiel ke ĉiuj, kiuj havis malsanojn, premadis sur lin, por tuŝi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'Kaj malpuraj spiritoj, tuj kiam ili vidis lin, falis antaŭ li, kaj kriis, dirante: Vi estas la Filo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Kaj li severe admonis ilin, ke ili ne konatigu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Kaj li supreniris sur la monton, kaj alvokis tiujn, kiujn li mem volis; kaj ili venis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'Kaj li elektis dek du, kiujn ankaŭ li nomis apostoloj, por ke ili estu kun li, kaj por ke li dissendu ilin por prediki,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'kaj por havi aŭtoritaton elpeli demonojn:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'kaj Simonon li alnomis Petro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'kaj Jakobon, filon de Zebedeo, kaj Johanon, fraton de Jakobo, kaj tiujn li alnomis Boanerges, tio estas, Filoj de tondro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'kaj Andreon kaj Filipon kaj Bartolomeon kaj Mateon kaj Tomason, kaj Jakobon, filon de Alfeo, kaj Tadeon, kaj Simonon, la Fervorulon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'kaj Judason Iskariotan, kiu ankaŭ perfidis lin. Kaj li venis en domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Kaj denove la homamaso kunvenis tiel, ke ili ne povis eĉ manĝi panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'Kaj liaj amikoj, aŭdinte tion, eliris, por kapti lin, ĉar ili diris: Li frenezas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'Kaj la skribistoj, kiuj alvenis el Jerusalem, diris: Li havas Baal- Zebubon; per la estro de la demonoj li elpelas la demonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'Kaj li alvokis ilin, kaj parolis al ili parabole: Kiel povas Satano elpeli Satanon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'Kaj se regno estas dividita kontraŭ si, tiu regno ne povas stari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'Kaj se domo estas dividita kontraŭ si, tiu domo ne povas stari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'Kaj se Satano ribelis kontraŭ si kaj estas dividita, li ne povas stari, sed havas finon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Sed neniu povas eniri en la domon de la fortulo kaj trarabi liajn posedaĵojn, se unue li ne ligos la fortulon, kaj poste li trarabos lian domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'Vere mi diras al vi: Ĉiuj iliaj pekoj estos pardonitaj al la filoj de homoj, kaj iliaj blasfemoj, per kiuj ajn ili blasfemos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'sed iu, kiu blasfemos kontraŭ la Sankta Spirito, eterne ne havos pardonon, sed estas kulpa pri eterna peko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'ĉar oni diris: Li havas malpuran spiriton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Kaj jen alvenis lia patrino kaj liaj fratoj, kaj starante ekstere, ili sendis al li, vokante lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'Kaj homamaso sidis ĉirkaŭ li; kaj oni diris al li: Jen via patrino kaj viaj fratoj ekstere vin serĉas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Kaj li respondis al ili, dirante: Kiuj estas mia patrino kaj miaj fratoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'Kaj ĉirkaŭrigardante tiujn, kiuj ronde ĉirkaŭ li sidis, li diris: Jen mia patrino kaj miaj fratoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Ĉar kiu ajn faros la volon de Dio, tiu estas mia frato kaj mia fratino kaj mia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'Kaj denove li komencis instrui apud la maro. Kaj kolektiĝis al li tre granda homamaso tiel, ke li eniris en ŝipeton, kaj sidis sur la maro; kaj la tuta homamaso estis sur la tero apud la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'Kaj li multe instruis ilin per paraboloj, kaj diris al ili en sia instruado:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, 'Aŭskultu: jen semisto eliris, por semi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'kaj dum li semis, iuj semoj falis apud la vojo, kaj la birdoj venis kaj formanĝis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Kaj aliaj falis sur ŝtonan lokon, kie ili ne havis multe da tero; kaj tuj ili ekkreskis, ĉar ili ne havis profundecon de tero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'kaj kiam la suno leviĝis, ili brulsekiĝis, kaj ĉar ili ne havis radikon, ili forvelkis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Kaj aliaj falis inter dornojn, kaj la dornoj kreskis kaj sufokis ilin, kaj ili ne donis frukton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Kaj aliaj falis en la bonan teron, kaj donis frukton, kreskante kaj multobliĝante, kaj produktis tridekoble kaj sesdekoble kaj centoble.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'Kaj li diris: Kiu havas orelojn por aŭdi, tiu aŭdu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Kaj kiam li estis sola, tiuj, kiuj alestis kune kun la dek du, demandis lin pri la paraboloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'Kaj li diris al ili: Al vi estas donite scii la misteron de la regno de Dio; sed al tiuj, kiuj estas ekstere, ĉio estas farata per paraboloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'por ke, vidante, ili vidu, sed ne rimarku; kaj aŭdante, ili aŭdu, sed ne komprenu; por ke neniam ili konvertiĝu kaj pardoniĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Kaj li diris al ili: Ĉu vi ne scias ĉi tiun parabolon? kiel do vi povos kompreni ĉiujn parabolojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'La semisto semas la vorton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Jen do tiuj, kiuj estas apud la vojo, kie estas semata la vorto; kaj kiam ili aŭdis, tuj venas Satano, kaj forprenas la vorton, en ili semitan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'Kaj tiel same jen la semitaj ĉe la ŝtonaj lokoj: ili aŭdas la vorton, kaj tuj kun ĝojo akceptas ĝin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'kaj ili ne havas en si radikon, sed restas nur portempe; kiam do venas sufero aŭ persekuto pro la vorto, tuj ili falpuŝiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'Kaj jen la semitaj ĉe la dornoj: tiuj, kiuj aŭdis la vorton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'sed la zorgoj de la mondo kaj la trompo de riĉo kaj la deziroj al aliaj aferoj, enirante, sufokas la vorton, kaj ĝi fariĝas senfrukta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'Kaj jen la semitaj ĉe la bona tero: tiuj, kiuj aŭdas la vorton kaj akceptas ĝin, kaj donas frukton, jen tridekoble, kaj jen sesdekoble, kaj jen centoble.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'Kaj li diris al ili: Ĉu lampo enportiĝas, por esti metita sub grenmezurilon aŭ sub liton, kaj ne por stari sur la lampingo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Ĉar nenio estas kaŝita krom por tio, ke ĝi estu malkaŝita; nek io estas sekreta krom por tio, ke ĝi estu aperigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Se iu havas orelojn por aŭdi, tiu aŭdu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'Kaj li diris al ili: Atentu, kion vi aŭdas; per kia mezuro vi mezuras, laŭ tiu sama oni mezuros al vi, kaj eĉ faros al vi aldonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Ĉar al tiu, kiu havas, estos donite; sed for de tiu, kiu ne havas, estos prenita eĉ tio, kion li havas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'Kaj li diris: Tia estas la regno de Dio, kvazaŭ homo ĵetus semojn sur la teron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'kaj dormus kaj leviĝus nokte kaj tage, kaj la semoj burĝonus kaj kreskus, li ne scias kiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'Aŭtomate la tero donas frukton, unue folion, poste spikon, poste plenan grenon en spiko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'Sed kiam la frukto estas preta, li tuj svingas la rikoltilon, ĉar venis la rikolto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'Kaj li diris: Al kio ni komparu la regnon de Dio? aŭ per kia parabolo ni montru ĝin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Al sinapa semeto, kiu, kiam ĝi estas semita sur la teron, estas pli malgranda ol ĉiuj aliaj semoj, kiuj estas sur la tero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'tamen semite, kreskas kaj fariĝas pli granda ol ĉiuj legomoj, kaj elmetas grandajn branĉojn, tiel ke sub ĝia ombro povas ekloĝi la birdoj de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'Kaj per multaj tiaj paraboloj li parolis al ili la vorton laŭ tio, kiel ili povis aŭskulti;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'kaj sen parabolo li ne parolis al ili; sed private li klarigis ĉion al siaj disĉiploj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Kaj en tiu tago, kiam vesperiĝis, li diris al ili: Ni transiru al la alia bordo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'Kaj forsendinte la homamason, ili kondukis lin kun si, kiel li estis en la ŝipeto. Kaj aliaj ŝipetoj akompanis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Kaj okazis granda ventego, kaj ondoj batis en la ŝipeton, tiel ke la ŝipeto estis jam pleniĝanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'Kaj li estis dormanta en la posta parto sur la kuseno; kaj ili vekis lin, kaj diris al li: Majstro, ĉu vi ne zorgas pri tio, ke ni pereas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'Kaj vekite, li admonis la venton, kaj diris al la maro: Silentu, kvietiĝu. Kaj la vento ĉesiĝis, kaj fariĝis granda sereno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'Kaj li diris al ili: Kial vi estas timemaj? ĉu vi ankoraŭ ne havas fidon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'Kaj ili timis treege, kaj diris unu al alia: Kiu do estas ĉi tiu? ĉar eĉ la vento kaj la maro obeas al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'Kaj ili venis trans la maron en la landon de la Gerasenoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'Kaj kiam li elvenis el la ŝipeto, tuj lin renkontis el la tomboj viro, havanta malpuran spiriton,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'kiu havis loĝejon en la tomboj, kaj jam neniu povis ligi lin eĉ per kateno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'ĉar li ofte estis ĉirkaŭligita per katenoj kaj ĉenoj, kaj la ĉenoj estis disŝiritaj de li kaj la katenoj frakasitaj; kaj neniu kapablis malsovaĝigi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'Kaj ĉiam, nokte kaj tage, inter la tomboj kaj sur la montoj, li kriadis kaj sin tranĉis per ŝtonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Kaj, vidinte Jesuon el malproksime, li kuris kaj adorkliniĝis al li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'kaj kriante per laŭta voĉo, li diris: Kio estas inter mi kaj vi, ho Jesuo, Filo de Dio Plejalta? Mi vin ĵurpetas per Dio, ke vi ne turmentu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Ĉar li diris al li: Eliru, ho malpura spirito, el la viro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'Kaj li demandis lin: Kia estas via nomo? Kaj li respondis, dirante: Mia nomo estas Legio, ĉar ni estas multaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'Kaj li multe petegis, ke li ne forsendu ilin el la lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Kaj estis tie sur la monto granda grego da porkoj paŝtiĝantaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'Kaj ili petegis lin, dirante: Sendu nin en la porkojn, por ke ni eniru en ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'Kaj li permesis tion al ili. Kaj elirinte, la malpuraj spiritoj eniris en la porkojn; kaj la grego kuris rapide malsupren de la krutaĵo en la maron, ĉirkaŭ du miloj, kaj sufokiĝis en la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Kaj iliaj paŝtistoj forkuris, kaj rakontis la aferon en la urbo kaj en la kamparo. Kaj oni venis, por vidi, kio okazis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'Kaj ili venis al Jesuo, kaj vidis la demonhavinton, kiu havis la legion, sidanta, vestita kaj en sana prudento; kaj ili timis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Kaj la vidintoj rakontis al ili, kiamaniere tio okazis al la demonhavinto, kaj pri la porkoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Kaj ili komencis petegi lin, ke li foriru el iliaj limoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Kaj kiam li eniris en la ŝipeton, la demonhavinto petegis lin, ke li povu esti kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Kaj li ne permesis al li, sed diris al li: Iru al via domo, al la viaj, kaj rakontu al ili ĉion, kion faris la Eternulo por vi, kaj kiel Li kompatis vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Kaj li foriris, kaj komencis famigi en Dekapolis ĉion, kion faris Jesuo por li; kaj ĉiuj miregis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Kaj kiam Jesuo retransiris en la ŝipeto al la alia bordo, granda homamaso kolektiĝis al li; kaj li estis apud la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'Kaj venis unu el la sinagogestroj, nomata Jairo, kaj ekvidinte lin, falis antaŭ liaj piedoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'kaj insiste lin petegis, dirante: Mia filineto estas en lasta ekstremo; venu do kaj metu viajn manojn sur ŝin, por ke ŝi saviĝu kaj vivu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Kaj li iris kun li, kaj granda homamaso sekvis lin kaj premis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'Kaj virino, kiu jam dek du jarojn havis sangofluon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'kaj multe suferis pro multaj kuracistoj, kaj elspezis sian tutan havon, kaj estis neniel helpita, sed kontraŭe eĉ pli malsaniĝis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'aŭdinte pri Jesuo, venis en la homamaso malantaŭ lin, kaj tuŝis lian mantelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'Ĉar ŝi diris: Se mi nur tuŝos lian mantelon, mi estos sanigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'Kaj tuj la fonto de ŝia sango sekiĝis, kaj ŝi korpe sentis, ke ŝi resaniĝis el sia malsano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'Kaj Jesuo, tuj sentante en si, ke la potenco eliris, turnis sin en la homamaso, kaj diris: Kiu tuŝis mian veston?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'Kaj liaj disĉiploj diris al li: Vi vidas la homamason, premantan vin, kaj ĉu vi diras: Kiu min tuŝis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'Kaj li ĉirkaŭrigardis, por vidi tiun, kiu tion faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Sed la virino, timigita kaj tremanta, sciante, kio fariĝis al ŝi, venis kaj falis antaŭ li, kaj diris al li la tutan veron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'Kaj li diris al ŝi: Filino, via fido vin savis; iru en paco, kaj estu sana el via malsano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Dum li ankoraŭ parolis, oni venis el la domo de la sinagogestro, dirante: Via filino mortis; kial vi ankoraŭ ĝenas la instruiston?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Sed Jesuo, ne atentante la parolon diritan, diris al la sinagogestro: Ne timu, nur kredu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'Kaj li ne permesis al iu sekvi kun li, krom Petro kaj Jakobo, kaj Johano, frato de Jakobo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'Kaj ili venis al la domo de la sinagogestro, kaj li vidis tumulton, kaj homojn plorantajn kaj funebre ĝemantajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'Kaj enirinte, li diris al ili: Kial vi tumultas kaj ploras? la infanino ne mortis, sed dormas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'Kaj ili mokridis lin. Tamen, foriginte ĉiujn, li kondukis la patron de la infanino kaj la patrinon, kaj tiujn, kiuj estis kun li, kaj eniris tien, kie estis la infanino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'Kaj preninte la manon de la infanino, li diris al ŝi: Talita kumi; tio estas: Knabineto, mi diras al vi: Leviĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'Kaj tuj leviĝis la knabineto kaj piediris; ĉar ŝi estis dekdujara. Kaj ili miris kun granda mirego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'Kaj li severe admonis ilin, ke neniu sciiĝu pri tio; kaj li ordonis doni al ŝi manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Kaj li eliris de tie, kaj venis en sian patrujon; kaj liaj disĉiploj lin sekvis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Kaj kiam venis la sabato, li komencis instrui en la sinagogo; kaj multaj, lin aŭdante, miris, dirante: De kie tiu viro havas tion? kaj: Kia estas la saĝeco donita al li? kaj kiaj estas tiaj potencaĵoj farataj per liaj manoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Ĉu ĉi tiu ne estas la ĉarpentisto, filo de Maria, kaj frato de Jakobo kaj Joses kaj Judas kaj Simon? kaj ĉu liaj fratinoj ne estas ĉi tie ĉe ni? Kaj ili ofendiĝis pro li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Kaj Jesuo diris al ili: Profeto ne estas sen honoro, krom en sia patrujo kaj inter siaj parencoj kaj en sia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Kaj li povis tie fari nenian potencaĵon, krom tio, ke li metis la manojn sur kelkajn senfortulojn kaj ilin resanigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'Kaj li miris pro ilia nekredemo. Kaj li rondevizitis la vilaĝojn, instruante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Kaj li alvokis al si la dek du, kaj komencis forsendi ilin duope; kaj li donis al ili aŭtoritaton super malpuraj spiritoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'kaj li ordonis, ke ili portu nenion por la vojo krom nur bastono-nek panon, nek saketon, nek monon en sia zono;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'sed ili iru piedvestitaj per sandaloj, kaj ne surmetu du tunikojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'Kaj li diris al ili: Kie ajn vi eniros en domon, tie loĝu, ĝis vi foriros el tiu loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'Kaj se ie ajn oni vin ne akceptos, nek vin aŭskultos, tiam el tie forirante, deskuu la polvon, kiu estas sub viaj piedoj, por atesto al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Kaj foririnte, ili predikis, ke oni pentu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'Kaj ili elpeladis multajn demonojn, kaj ŝmiradis per oleo multajn malsanulojn kaj ilin sanigadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'Kaj la reĝo Herodo aŭdis pri tio, ĉar lia nomo jam konatiĝis; kaj li diris: Johano, la Baptisto, leviĝis el la mortintoj, kaj tial tiuj potencaĵoj energias en li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Sed aliaj diris: Tiu estas Elija. Kaj aliaj diris: Tiu estas profeto, kvazaŭ unu el la profetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Sed, tion aŭdinte, Herodo diris: Johano, kiun mi senkapigis, leviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Ĉar Herodo mem jam sendis, kaj arestis Johanon, kaj ligis lin en malliberejo pro Herodias, kiu estis edzino de lia frato Filipo, ĉar li estis edziĝinta kun ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Ĉar Johano diris al Herodo: Ne decas, ke vi havu la edzinon de via frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Kaj Herodias klopodis kontraŭ li, kaj deziris mortigi lin, kaj ne povis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'ĉar Herodo timis Johanon, sciante, ke li estas viro justa kaj sankta, kaj nepre gardis lin. Kaj aŭskultante lin, li embarasiĝis, kaj aŭskultis lin volonte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Kaj kiam venis oportuna tago, kiam Herodo pro sia naskotago faris vespermanĝon al siaj nobeloj kaj milestroj kaj ĉefoj de Galileo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'eniris la filino de Herodias mem kaj dancis, kaj ŝi plaĉis al Herodo kaj al liaj kunmanĝantoj; kaj la reĝo diris al la knabino: Petu de mi, kion ajn vi volas, kaj mi tion donos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'Kaj li ĵuris al ŝi: Kion ajn vi petos de mi, mi tion donos al vi, ĝis duono de mia regno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Kaj elirinte, ŝi diris al sia patrino: Kion mi petu? Kaj tiu diris: La kapon de Johano, la Baptisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'Kaj ŝi tuj eniris rapide al la reĝo, kaj petis, dirante: Mi deziras, ke vi tuj donu al mi sur plado la kapon de Johano, la Baptisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'Kaj la reĝo fariĝis tre malĝoja; tamen pro siaj ĵuroj kaj pro la kunmanĝantoj li ne volis rifuzi al ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'Kaj tuj la reĝo elsendis soldaton el sia gardistaro, kaj ordonis alporti lian kapon; kaj elirinte, tiu senkapigis lin en la malliberejo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'kaj alportis lian kapon sur plado, kaj donis ĝin al la knabino; kaj la knabino donis ĝin al sia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Kaj kiam liaj disĉiploj aŭdis, ili venis kaj forportis lian korpon, kaj metis ĝin en tombon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'Kaj la apostoloj kolektiĝis al Jesuo, kaj rakontis al li ĉion, kion ili faris kaj instruis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'Kaj li diris al ili: Venu mem aparte en dezertan lokon, kaj iom ripozu. Ĉar estis multaj venantaj kaj irantaj, kaj ili ne havis oportunon eĉ por manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'Kaj ili foriris en la ŝipeto al dezerta loko aparte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'Kaj oni vidis ilin forirantajn, kaj multaj rekonis ilin, kaj piede oni kuris tien el ĉiuj urboj kaj antaŭvenis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Kaj li elvenis, kaj vidis grandan homamason, kaj li kortuŝiĝis pri ili, ĉar ili estis kiel ŝafoj ne havantaj paŝtiston; kaj li komencis instrui al ili multon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'Kaj kiam la horo jam estis malfrua, liaj disĉiploj venis al li, kaj diris: La loko estas dezerta, kaj la horo estas jam malfrua;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'forsendu ilin, por ke ili iru en la ĉirkaŭajn kampojn kaj vilaĝojn kaj aĉetu por si manĝaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'Sed li responde diris al ili: Vi donu al ili manĝi. Kaj ili diris al li: Ĉu ni iru kaj aĉetu panojn por ducent denaroj, kaj donu al ili manĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'Kaj li diris al ili: Kiom da panoj vi havas? iru, por vidi. Kaj sciiĝinte, ili diris: Kvin, kaj du fiŝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'Kaj li ordonis al ili, ke ĉiuj sidiĝu laŭgrupe sur la verda herbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'Kaj ili sidiĝis en aroj, centope kaj kvindekope.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Kaj li prenis la kvin panojn kaj la du fiŝojn, kaj suprenrigardinte al la ĉielo, li benis kaj dispecigis la panojn, kaj donis al la disĉiploj, por meti antaŭ ilin; kaj li dividis la du fiŝojn inter ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'Kaj ĉiuj manĝis kaj satiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'Kaj oni kolektis da fragmentoj dek du korbojn, kaj ankaŭ el la fiŝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'Kaj tiuj, kiuj manĝis la panojn, estis kvin mil viroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'Kaj tuj li devigis siajn disĉiplojn eniri en la ŝipeton kaj iri antaŭ li al la alia bordo, al Betsaida, dum li forsendos la homamason.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'Kaj adiaŭinte ilin, li foriris sur la monton, por preĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'Kaj kiam vesperiĝis, la ŝipeto estis meze de la maro, kaj li sola sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'Kaj vidante ilin laborantaj en malfacila remado, ĉar la vento estis kontraŭa al ili, ĉirkaŭ la kvara gardoparto de la nokto li venis al ili, irante sur la maro, kaj li volis preterpasi ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'sed ili, vidante lin iranta sur la maro, supozis, ke ĝi estas fantomo, kaj ili ekkriis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'ĉar ĉiuj vidis lin kaj maltrankviliĝis. Sed li tuj parolis kun ili, kaj diris al ili: Kuraĝu; ĝi estas mi; ne timu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'Kaj li supreniris al ili en la ŝipeton, kaj la vento ĉesiĝis; kaj ili sentis grandan miregon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'ĉar ili ne komprenis pri la panoj, ĉar ilia koro estis sensenta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'Kaj transirinte, ili alvenis teren ĉe Genesaret, kaj alligis la ŝipeton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'Kaj kiam ili estis elŝipiĝintaj, tuj oni rekonis lin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'kaj kuris tra tiu tuta regiono, kaj komencis ĉirkaŭporti la malsanulojn sur iliaj litoj tien, kie ili aŭdis, ke li estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'Kaj kien ajn li eniris, en vilaĝojn aŭ en urbojn aŭ sur la kamparon, ili demetis la malsanulojn sur la placoj, kaj petegis lin, ke ili tuŝu nur la randon de lia vesto; kaj ĉiuj, kiuj tuŝis, resaniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Kaj kolektiĝis al li la Fariseoj kaj iuj el la skribistoj, kiuj venis el Jerusalem,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'kaj jam vidis, ke kelkaj el liaj disĉiploj manĝas panon kun manoj profanaj, tio estas nelavitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'Kaj la Fariseoj kaj ĉiuj Judoj, se ili ne lavis zorge la manojn, ne manĝas, tenante la tradicion de la antaŭuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'kaj veninte el komercejo, ili ne manĝas, ne sin lavinte; kaj estas multaj aliaj aferoj, kiujn ili ricevis por observi, trempon de pokaloj kaj mezurpotoj kaj kupraj vazoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Kaj lin demandis la Fariseoj kaj la skribistoj: Kial ne faras viaj disĉiploj laŭ la tradicio de la antaŭuloj, sed manĝas panon kun manoj profanaj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Kaj li diris al ili: Bone profetis Jesaja pri vi hipokrituloj, kiel estas skribite: Ĉi tiu popolo honoras Min per siaj lipoj, Sed ilia koro estas malproksime de Mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'Sed vane ili Min adoras, Instruante kiel doktrinojn ordonojn de homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Ĉar, forlasinte la ordonon de Dio, vi tenas la tradicion de homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Kaj li diris al ili: Efektive vi forrifuzas la ordonon de Dio, por observi vian tradicion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Ĉar Moseo diris: Respektu vian patron kaj vian patrinon; kaj: Kiu malbenas sian patron aŭ sian patrinon, tiu nepre mortu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Sed vi diras: Se iu diros al sia patro aŭ sia patrino: Korban, tio estas Oferdono, estu tio, per kio vi povus profiti de mi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'vi jam ne permesas al li fari ion por sia patro aŭ sia patrino;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'vantigante la vorton de Dio per via tradicio, kiun vi transdonis; kaj multajn tiajn aferojn vi faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'Kaj denove alvokinte la homamason, li diris al ili: Ĉiuj min aŭskultu kaj komprenu:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'ekzistas nenio, kio, enirante en homon de ekstere, povas lin profani; sed kio eliras el homo, tio profanas la homon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Kiu havas orelojn por aŭdi, tiu aŭdu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Kaj kiam li eniris en domon for de la homamaso, liaj disĉiploj demandis lin pri la parabolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Kaj li diris al ili: Ĉu vi ankaŭ estas tiel sen kompreno? Ĉu vi ne konscias, ke ĉio, eniranta de ekstere en homon, ne povas profani lin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'ĉar ĝi eniras ne en lian koron, sed en la ventron, kaj eliras en apartan lokon? Tion li diris, indigante ĉiajn manĝaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Kaj li diris: Kio elvenas el homo, tio profanas la homon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Ĉar de interne, el la koro de homoj, eliras malvirtaj pensoj, malĉastaĵoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'ŝteloj, mortigoj, adultoj, avideco, malindaĵoj, ruzeco, voluptoj, malica okulo, blasfemo, aroganteco, malsaĝeco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'ĉiuj tiuj malbonoj elvenas de interne kaj profanas la homon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Kaj irinte de tie, li venis en la limojn de Tiro kaj Cidon. Kaj enirinte en domon, li volis, ke neniu sciu; sed li ne povis esti kaŝita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Sed aŭdinte pri li, iu virino, kies filineto havis malpuran spiriton, venis kaj falis antaŭ liaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'Kaj la virino estis Grekino, rase Sirofenika. Kaj ŝi petis lin, ke li elpelu la demonon el ŝia filino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Kaj li diris al ŝi: Lasu unue satigi la infanojn, ĉar ne decas preni la panon de la infanoj kaj ĵeti ĝin al la hundetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Sed ŝi respondis kaj diris al li: Jes, Sinjoro; ĉar eĉ la hundetoj sub la tablo manĝas el la panpecetoj de la infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Kaj li diris al ŝi: Pro ĉi tiu vorto iru vian vojon; la demono eliris el via filino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'Kaj kiam ŝi iris en sian domon, ŝi trovis la infaninon kuŝigita sur la lito, kaj la demonon foririnta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Kaj denove foririnte el la limoj de Tiro, li venis tra Cidon al la Galilea Maro, tra la mezo de la limoj de Dekapolis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'Kaj oni kondukis al li viron surdan kaj apenaŭ parolkapablan, kaj petis lin, ke li metu sian manon sur lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'Kaj kondukinte lin el la homamaso en apartan lokon, li metis siajn fingrojn en liajn orelojn, kaj kraĉinte, li tuŝis lian langon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'kaj suprenrigardinte al la ĉielo, li ĝemis, kaj diris al li: Efata, tio estas: Malfermiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'Kaj liaj oreloj malfermiĝis, kaj la ligilo de lia lango malstreĉiĝis, kaj li parolis klare.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Kaj li admonis ilin, ke oni diru tion al neniu; sed ju pli li malpermesis, des pli multe ili ĉie sciigis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'Kaj supermezure ili miregis, dirante: Li faris ĉion bone; li igas la surdulojn aŭdi, kaj la mutulojn paroli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'En tiuj tagoj, kiam denove estis granda homamaso, kaj ili nenion havis manĝi, li alvokis al si siajn disĉiplojn, kaj diris al ili:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'Mi kortuŝiĝas pro la homamaso, ĉar jam tri tagojn ili restas ĉe mi kaj nenion havas manĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'kaj se mi forsendos ilin fastantaj al iliaj domoj, ili laciĝos sur la vojo; kaj iuj el ili venis de malproksime.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Kaj liaj disĉiploj respondis al li: De kie oni povos satigi ĉi tiujn homojn per panoj ĉi tie en dezerto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'Kaj li demandis ilin: Kiom da panoj vi havas? Kaj ili diris: Sep.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Kaj li ordonis al la homamaso sidiĝi sur la tero; kaj li prenis la sep panojn, kaj doninte dankon, li dispecigis ilin, kaj donis al la disĉiploj por disdoni; kaj ili disdonis al la homamaso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Kaj ili havis kelkajn malgrandajn fiŝojn; kaj beninte ilin, li ordonis disdoni ilin ankaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Kaj ili manĝis kaj satiĝis; kaj oni kolektis da postrestintaj fragmentoj sep korbegojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Kaj ili estis proksimume kvar mil, kaj li forsendis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'Kaj tuj enirinte en la ŝipeton kun siaj disĉiploj, li iris al la regiono Dalmanuta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Kaj alvenis la Fariseoj, kaj komencis diskuti kun li, serĉante ĉe li signon el la ĉielo, por provi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Kaj forte ĝeminte en sia spirito, li diris: Kial ĉi tiu generacio serĉas signon? vere, mi diras al vi: Nenia signo estos donita al ĉi tiu generacio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'Kaj forlasinte ilin, li denove enŝipiĝis kaj transiris al la alia bordo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Kaj ili forgesis preni panojn; kaj nur unu panon ili havis kun si en la ŝipeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Kaj li admonis ilin, dirante: Zorgu, gardu vin kontraŭ la fermentaĵo de la Fariseoj kaj la fermentaĵo de Herodo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'Kaj ili diskutis unu kun la alia, dirante: Ĉar ni ne havas panojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Kaj Jesuo, eksciante tion, diris al ili: Kial vi diskutas pro tio, ke vi ne havas panon? ĉu vi ankoraŭ ne konscias nek komprenas? ĉu via koro estas obstinigita?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Okulojn havante, ĉu vi ne vidas? kaj orelojn havante, ĉu vi ne aŭdas? kaj ĉu vi ne memoras?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Kiam mi dispecigis la kvin panojn por la kvin mil, kiom da korboj da fragmentoj vi kolektis? Ili respondis al li: Dek du.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, 'Kaj kiam la sep por la kvar mil, kiom da korbegoj da fragmentoj vi kolektis? Kaj ili respondis al li: Sep.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'Kaj li diris al ili: Ĉu vi ankoraŭ ne komprenas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Kaj ili alvenis al Betsaida. Kaj oni alkondukis al li blindulon, kaj petegis, ke li tuŝu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Kaj preninte la manon de la blindulo, li elkondukis lin ekster la vilaĝon; kaj kraĉinte sur liajn okulojn, kaj surmetinte la manojn sur lin, li demandis lin: Ĉu vi vidas ion?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'Kaj li ekrigardis, kaj diris: Mi vidas homojn, ĉar mi vidas kvazaŭ arbojn irantajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Tiam denove li metis la manojn sur liajn okulojn; kaj li fikse rigardis, kaj resaniĝis, kaj vidis ĉion klare.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'Kaj li forsendis lin al lia domo, dirante: Nepre ne eniru en la vilaĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Kaj eliris Jesuo kaj liaj disĉiploj en la vilaĝojn de Cezarea Filipi; kaj sur la vojo li demandis siajn disĉiplojn, dirante al ili: Kiu, diras la homoj, ke mi estas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Kaj ili respondis al li: Johano, la Baptisto; laŭ aliaj: Elija; kaj laŭ aliaj: Unu el la profetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'Kaj li demandis ilin: Sed vi-kiu vi diras, ke mi estas? Petro responde diris al li: Vi estas la Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'Kaj li admonis ilin, ke ili diru al neniu pri li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'Kaj li komencis instrui al ili, ke la Filo de homo devas multe suferi, kaj esti rifuzita de la pliaĝuloj kaj la ĉefpastroj kaj la skribistoj, kaj esti mortigita, kaj post tri tagoj releviĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'Kaj li parolis tiun diron malkaŝe. Kaj Petro prenis lin, kaj komencis admoni lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Sed turninte sin kaj rigardante la disĉiplojn, li admonis Petron, dirante: Iru malantaŭ min, Satano, ĉar vi havas pensojn ne laŭ Dio, sed laŭ homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'Kaj alvokinte al si la homamason kun siaj disĉiploj, li diris al ili: Se iu volas veni post mi, li abnegaciu sin, kaj levu sian krucon, kaj sekvu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Ĉar kiu volos savi sian animon, tiu ĝin perdos; kaj kiu perdos sian animon pro mi kaj pro la evangelio, tiu ĝin savos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Ĉar kiel profitus homo, se li gajnus la tutan mondon kaj perdus sian animon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Ĉar kion homo donu interŝanĝe por sia animo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Ĉar kiu hontos pri mi kaj miaj paroloj antaŭ ĉi tiu adultema kaj peka generacio, pri tiu ankaŭ hontos la Filo de homo, kiam li venos en la gloro de sia Patro kun la sanktaj anĝeloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'Kaj li diris al ili: Vere mi diras al vi: Inter la ĉi tie starantaj estas iuj, kiuj neniel gustumos morton, antaŭ ol ili vidos la regnon de Dio venintan en potenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'Kaj post ses tagoj Jesuo prenis kun si Petron kaj Jakobon kaj Johanon, kaj kondukis ilin solajn sur altan monton aparte; kaj li estis aliformita antaŭ ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'kaj liaj vestoj fariĝis brilantaj, treege blankaj, kiel fulisto sur la tero ne povas blankigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'Kaj aperis al ili Elija kun Moseo, kaj ili interparoladis kun Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Kaj Petro responde diris al Jesuo: Rabeno, estas bone por ni esti ĉi tie; kaj ni faru tri laŭbojn: unu por vi, kaj unu por Moseo, kaj unu por Elija.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Ĉar li ne sciis, kion respondi, ĉar ili tre timiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'Kaj nubo superombris ilin; kaj elvenis voĉo el la nubo: Ĉi tiu estas Mia Filo, la amata; aŭskultu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'Kaj subite, ĉirkaŭrigardinte, ili jam vidis neniun krom Jesuo sola.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Kaj dum ili malsupreniris de la monto, li admonis ilin, ke al neniu ili rakontu tion, kion ili vidis, ĝis la Filo de homo releviĝos el la mortintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'Kaj ili konservis la diron, demandante inter si, kion signifas la releviĝo el la mortintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'Kaj ili demandis lin, dirante: Kial diras la skribistoj, ke Elija devas veni antaŭe?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Kaj li diris al ili: Vere Elija venas antaŭe, kaj restarigas ĉion; kaj kiel estas skribite pri la Filo de homo, ke li devas multe suferi kaj esti malestimata?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Sed mi diras al vi, ke Elija jam venis, kaj oni faris al li ĉion, kion ili volis, kiel estas skribite pri li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Kaj veninte al la disĉiploj, ili vidis grandan homamason ĉirkaŭ ili, kaj skribistojn diskutantajn kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'Kaj tuj la homamaso, vidante lin, forte miris, kaj alkuris, kaj salutis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'Kaj li demandis ilin: Pri kio vi diskutas kun ili?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'Kaj unu el la amaso respondis al li: Majstro, mi venigis al vi mian filon, kiu havas mutan spiriton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'kaj kie ajn ĝi kaptas lin, ĝi ŝiras lin, kaj li ŝaŭmas kaj grincigas la dentojn kaj kadukiĝas; kaj mi parolis al viaj disĉiploj, ke ili elpelu ĝin; kaj ili ne povis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Kaj li respondis al ili, dirante: Ho senfida generacio, ĝis kiam mi estos kun vi? ĝis kiam mi toleros vin? venigu lin al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'Kaj ili venigis lin al li; kaj vidinte lin, tuj la spirito konvulsiigis lin, kaj li falis teren kaj ruliĝis ŝaŭmanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'Kaj li demandis la patron: De kiom da tempo okazadas ĉi tio al li? Kaj li diris: De infaneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'Kaj ofte ĝi ĵetis lin en fajron kaj en akvon, por pereigi lin; sed se vi povas fari ion, kompatu al ni kaj helpu nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Kaj Jesuo diris al li: Kiel, se vi povas! Ĉio estas ebla por kredanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'Tuj ekkriante, la patro de la infano diris: Mi kredas; helpu mian nekredemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Kaj kiam Jesuo vidis, ke homamaso alkuras, li severe admonis la malpuran spiriton, dirante al ĝi: Vi muta kaj surda spirito, mi ordonas al vi: Eliru el li, kaj ne plu eniru en lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Kaj ekkriinte, kaj multe konvulsiiginte lin, ĝi eliris; kaj li fariĝis kvazaŭ mortinto, tiel ke la plimulto diris: Li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Sed Jesuo, preninte lin je la mano, levis lin; kaj li stariĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'Kaj kiam li eniris en la domon, liaj disĉiploj aparte demandis lin: Kial ni ne povis elpeli ĝin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'Kaj li diris al ili: Ĉi tiu speco neniel povas eliri, krom per preĝado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'Kaj foririnte, ili trapasis tra Galileo; kaj li deziris, ke neniu tion eksciu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Ĉar li instruadis siajn disĉiplojn, kaj diris al ili: La Filo de homo estas transdonita en la manojn de homoj, kaj ili mortigos lin; kaj, mortigite, li leviĝos post tri tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Sed ili ne komprenis la diron, kaj timis demandi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'Kaj ili venis al Kapernaum, kaj kiam li estis en la domo, li demandis ilin: Pri kio vi diskutis sur la vojo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Sed ili silentis; ĉar ili diskutis inter si sur la vojo pri tio, kiu estas la plej granda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'Kaj sidiĝinte, li alvokis la dek du, kaj diris al ili: Se iu volas esti unua, li estos lasta el ĉiuj, kaj servanto de ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'Kaj preninte infanon, li starigis ĝin meze de ili; kaj ĉirkaŭbrakinte ĝin, li diris al ili:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, 'Kiu akceptos unu el tiaj infanoj en mia nomo, tiu akceptas min; kaj kiu akceptas min, tiu akceptas ne min, sed Tiun, kiu sendis min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Johano diris al li: Majstro, ni vidis iun elpelantan demonojn en via nomo; kaj ni malpermesis lin, ĉar li ne sekvas nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Sed Jesuo diris: Ne malpermesu lin; ĉar neniu, kiu faros miraklon en mia nomo, povos facile paroli malbone pri mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Ĉar tiu, kiu ne estas kontraŭ ni, estas por ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Ĉar kiu donos al vi trinki tason da akvo, pro tio, ke vi apartenas al Kristo, vere mi diras al vi, tiu neniel perdos sian rekompencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'Kaj kiu igos fali unu el ĉi tiuj malgranduloj, kiuj kredas al mi, estus pli bone por tiu, se granda muelŝtono estus pendigita ĉirkaŭ lia kolo, kaj se li estus ĵetita en la maron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'Kaj se via mano faligas vin, detranĉu ĝin: estas bone por vi eniri en vivon kripla prefere ol, havante du manojn, eniri en Gehenan, en la neestingeblan fajron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'kie ilia vermo ne pereas kaj la fajro ne estingiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'Kaj se via piedo faligas vin, detranĉu ĝin: estas bone por vi eniri en vivon lama prefere ol, havante du piedojn, esti ĵetita en Gehenan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'kie ilia vermo ne pereas kaj la fajro ne estingiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'Kaj se via okulo faligas vin, elŝiru ĝin: estas bone por vi eniri en la regnon de Dio kun unu okulo prefere ol, havante du okulojn, esti ĵetita en Gehenan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'kie ilia vermo ne pereas kaj la fajro ne estingiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Ĉar ĉiu estos salita per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'Salo estas bona; sed se la salo fariĝis nesala, kiel vi rebonigos ĝin? Havu salon en vi, kaj paciĝu unu kun alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Kaj li foriris de tie, kaj venis en la limojn de Judujo kaj trans Jordanon; kaj homamasoj kunvenis denove al li, kaj laŭ sia kutimo li instruis ilin denove.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Kaj Fariseoj venis, kaj demandis lin, por provi lin: Ĉu estas permesate al viro forsendi sian edzinon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Kaj li responde diris al ili: Kion Moseo ordonis al vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Kaj ili diris: Moseo permesis skribi eksedzigan leteron, kaj forsendi ŝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Sed Jesuo diris al ili: Pro la malmoleco de via koro li skribis por vi ĉi tiun ordonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Sed de la komenco de la kreo: Li faris ilin vira kaj virina.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'Tial viro forlasos sian patron kaj sian patrinon, kaj aliĝos al sia edzino,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'kaj ili estos unu karno; sekve ili jam estas ne du, sed unu karno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Kion do Dio kunigis, tion homo ne disigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'Kaj en la domo la disĉiploj denove demandis lin pri la afero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'Kaj li diris al ili: Kiu forsendos sian edzinon kaj edziĝos kun alia, tiu adultas kontraŭ ŝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'kaj se ŝi mem forsendos sian edzon kaj edziniĝos kun alia, ŝi adultas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'Kaj oni venigis al li infanojn, por ke li tuŝu ilin; kaj la disĉiploj admonis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Sed Jesuo, vidinte tion, indignis, kaj diris al ili: Lasu la infanojn veni al mi; ne malhelpu ilin, ĉar el tiaj estas la regno de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Vere mi diras al vi: Kiu ne akceptos la regnon de Dio kiel infano, tiu neniel eniros en ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'Kaj li prenis ilin en siaj brakoj, kaj benis ilin, metinte la manojn sur ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'Kaj dum li foriris sur la vojo, unu homo kuris al li kaj genuis antaŭ li, kaj demandis lin: Bona Majstro, kion mi faru, por ke mi heredu eternan vivon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Kaj Jesuo diris al li: Kial vi nomas min bona? neniu estas bona krom Unu, nome Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Vi scias la ordonojn: Ne mortigu; Ne adultu; Ne ŝtelu; Ne parolu malveran ateston; Ne rabu; Respektu vian patron kaj vian patrinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'Kaj li responde diris al li: Majstro, ĉion tion mi observis detempe de mia juneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Kaj Jesuo, rigardante lin, amis lin, kaj diris al li: Unu mankon vi havas; iru, kaj vendu ĉion, kion vi havas, kaj donu al malriĉuloj, kaj vi havos trezoron en la ĉielo; kaj venu, sekvu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Sed li malgajiĝis ĉe tiu vorto, kaj foriris malĝoja; ĉar li havis multajn posedaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Kaj Jesuo ĉirkaŭrigardis, kaj diris al siaj disĉiploj: Kiel malfacile tiuj, kiuj havas riĉon, eniros en la regnon de Dio!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Kaj la disĉiploj miris pro liaj vortoj. Sed Jesuo, respondante denove, diris al ili: Infanoj, kiel malfacile estas por tiuj, kiuj fidas al la riĉo, eniri en la regnon de Dio!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Estas pli facile por kamelo iri tra trueton de kudrilo, ol por riĉulo eniri en la regnon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'Kaj ili forte miregis, dirante al li: Kiu do povas esti savita?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Rigardante ilin, Jesuo diris: Ĉe homoj tio estas neebla, sed ne ĉe Dio; ĉar ĉio estas ebla ĉe Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Petro ekparolis al li: Jen ni ĉion forlasis kaj vin sekvis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Jesuo diris: Vere mi diras al vi: Ekzistas neniu, kiu forlasis domon aŭ fratojn aŭ fratinojn aŭ patrinon aŭ patron aŭ infanojn aŭ kampojn pro mi kaj pro la evangelio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'kaj kiu ne ricevos centoble en ĉi tiu tempo, domojn kaj fratojn kaj fratinojn kaj patrinojn kaj infanojn kaj kampojn, kun persekutado; kaj en la venonta mondo eternan vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Sed multaj unuaj estos lastaj, kaj lastaj estos unuaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'Kaj ili estis sur la vojo suprenirantaj al Jerusalem, kaj Jesuo iris antaŭ ili; kaj ili miregis, kaj la sekvantoj timis. Kaj li prenis al si denove la dek du, kaj ekparolis pri tio, kio okazos al li, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, 'Jen ni supreniras al Jerusalem; kaj la Filo de homo estos transdonita al la ĉefpastroj kaj la skribistoj; kaj ili kondamnos lin al morto kaj transdonos lin al la nacianoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'kaj ili lin mokos kaj sur lin kraĉos kaj lin skurĝos kaj lin mortigos; kaj post tri tagoj li releviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Kaj alproksimiĝis al li Jakobo kaj Johano, filoj de Zebedeo, dirante al li: Majstro, ni deziras, ke, kion ajn ni petos de vi, vi tion faru por ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'Kaj li diris al ili: Kion vi volas, ke mi faru por vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'Kaj ili diris al li: Permesu, ke ni povu sidi, unu dekstre de vi kaj la dua maldekstre, en via gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Sed Jesuo diris al ili: Vi ne scias, kion vi petas. Ĉu vi povas trinki la kalikon, kiun mi trinkas? aŭ esti baptitaj per la bapto, per kiu mi estas baptata?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'Kaj ili diris al li: Ni povas. Kaj Jesuo diris al ili: La kalikon, kiun mi trinkas, vi trinkos, kaj per la bapto, per kiu mi estas baptata, vi estos baptitaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'sed sidi dekstre de mi aŭ maldekstre, tion doni ne apartenas al mi; sed ĝi estas por tiuj, por kiuj ĝi estas preparita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'Kaj aŭdinte, la dek ekindignis kontraŭ Jakobo kaj Johano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Kaj Jesuo, alvokinte ilin al si, diris al ili: Vi scias, ke tiuj, kiuj pretendas regi la nacianojn, kondutas kiel sinjoroj super ili, kaj iliaj granduloj ekzercas aŭtoritaton super ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Sed ne tiel estos inter vi; sed kiu volas esti granda inter vi, tiu estu via servanto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'kaj kiu volas esti la unua inter vi, tiu estu sklavo de ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Ĉar la Filo de homo venis, ne por esti servata, sed por servi, kaj por doni sian vivon kiel elaĉeton por multaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'Kaj ili venis al Jeriĥo; kaj kiam li foriris el Jeriĥo kun siaj disĉiploj kaj granda homamaso, la filo de Timeo, Bartimeo, blinda almozulo, sidis apud la vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'Kaj aŭdinte, ke ĉeestas Jesuo, la Nazaretano, li ekkriis, kaj diris: Jesuo, filo de David, kompatu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'Kaj multaj admonis lin, ke li silentu; sed li des pli forte kriis: Ho Filo de David, kompatu min!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Kaj Jesuo haltis, kaj diris: Alvoku lin. Kaj oni alvokis la blindulon, dirante al li: Kuraĝu; leviĝu, li vin alvokas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'Kaj li forĵetis sian veston, kaj eksaltis kaj venis al Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'Kaj Jesuo responde al li diris: Kion vi volas, ke mi faru al vi? Kaj la blindulo diris al li: Rabeno mia, ke mi ricevu vidpovon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'Kaj Jesuo diris al li: Iru; via fido vin savis. Kaj tuj li ricevis vidpovon, kaj sekvis lin sur la vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'Kaj kiam ili alproksimiĝis al Jerusalem, al Betfage kaj Betania, apud la monto Olivarba, li sendis du el siaj disĉiploj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'kaj diris al ili: Iru en la vilaĝon, kiu estas kontraŭ vi, kaj enirinte ĝin, vi tuj trovos azenidon alligitan, sur kiu ankoraŭ neniu iam sidis; malligu kaj alkonduku ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'Kaj se iu diros al vi: Kial vi faras tion? respondu: La Sinjoro bezonas ĝin; kaj tuj li sendos ĝin ĉi tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Kaj ili iris, kaj trovis azenidon alligitan apud pordo ekstere sur la strato; kaj ili malligis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Kaj iuj apudstarantoj diris al ili: Kion vi faras, malligante la azenidon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Sed ili respondis al ili, kiel Jesuo diris; kaj ili lasis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Kaj ili alkondukis la azenidon al Jesuo, kaj metis sur ĝin siajn vestojn; kaj li sidis sur ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Kaj multaj sternis siajn vestojn sur la vojo, kaj aliaj sternis foliarojn, tranĉinte ilin el la kampoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'Kaj kriis la antaŭirantoj kaj la sekvantoj: Hosana! Estu benata tiu, kiu venas en la nomo de la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Estu benata la venanta regno de nia patro David; Hosana en la supera alto!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'Kaj li eniris en Jerusalemon, en la templon; kaj kiam li ĉirkaŭrigardis ĉion, kaj la horo jam vesperiĝis, li foriris al Betania kun la dek du.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'Kaj la morgaŭan tagon, post ilia eliro el Betania, li malsatis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'Kaj vidinte el malproksime figarbon havantan foliojn, li aliris, por trovi, se eble, ion sur ĝi; kaj veninte al ĝi, li trovis nenion krom folioj, ĉar la tempo de figoj ankoraŭ ne venis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Kaj responde li diris al ĝi: Neniu por ĉiam manĝu frukton el vi. Kaj aŭdis la disĉiploj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'Kaj ili venis en Jerusalemon; kaj enirinte en la templon, li komencis elpeli la vendantojn kaj la aĉetantojn en la templo, kaj renversis la tablojn de la monŝanĝistoj kaj la seĝojn de la vendantoj de kolomboj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'kaj ne permesis, ke oni portu ian vazon tra la templo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'Kaj li instruis, kaj diris al ili: Ĉu ne estas skribite: Mia domo estos nomata domo de preĝo por ĉiuj popoloj? Sed vi faris ĝin kaverno de rabistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Kaj la ĉefpastroj kaj la skribistoj aŭdis tion, kaj serĉis, kiamaniere pereigi lin; ĉar ili timis lin, ĉar la tuta homamaso miregis pro lia instruado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'Kaj kiam vesperiĝis, li eliris el la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'Kaj matene, preterpasante, ili vidis la figarbon forvelkinta de la radikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Kaj rememorinte, Petro diris al li: Rabeno, jen forvelkis la figarbo, kiun vi malbenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Kaj responde Jesuo diris al ili: Havu fidon al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Vere mi diras al vi: Se iu diros al ĉi tiu monto: Estu formovita kaj ĵetita en la maron, kaj ne dubos en sia koro, sed kredos, ke okazos tio, kion li diras, tiu ĝin havos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'Pro tio mi diras al vi: Kion ajn vi petos, preĝante, kredu, ke vi tion jam ricevis, kaj vi ĝin havos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'Kaj kiam vi staras preĝante, pardonu, se vi havas ion kontraŭ iu; por ke ankaŭ via Patro, kiu estas en la ĉielo, pardonu al vi viajn erarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Sed se vi ne pardonos, ankaŭ via Patro, kiu estas en la ĉielo, ne pardonos viajn erarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'Kaj ili denove venis al Jerusalem; kaj dum li ĉirkaŭiris en la templo, la ĉefpastroj kaj la skribistoj kaj la pliaĝuloj venis al li,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'kaj diris al li: Laŭ kia aŭtoritato vi faras ĉi tion? aŭ kiu donis al vi tian aŭtoritaton, ke vi faru ĉi tion?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Sed Jesuo diris al ili: Mi faros al vi unu demandon, kaj respondu al mi, kaj mi diros al vi, laŭ kia aŭtoritato mi faras ĉi tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'La baptado de Johano, ĉu ĝi estis el la ĉielo, aŭ el homoj? respondu al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'Kaj ili diskutis inter si, dirante: Se ni diros: El la ĉielo, li diros: Kial do vi ne kredis al li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Sed se ni diros: El homoj-ili timis la popolon, ĉar ĉiuj opiniis, ke Johano efektive estis profeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'Kaj responde ili diris al Jesuo: Ni ne scias. Kaj Jesuo diris al ili: Kaj mi ne diras al vi, laŭ kia aŭtoritato mi faras ĉi tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Kaj li komencis paroli al ili per paraboloj. Vinberĝardenon plantis unu viro, kaj ĉirkaŭmetis plektobarilon, kaj fosis vinpremejon, kaj konstruis turon, kaj luigis ĝin al kultivistoj, kaj forvojaĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'Kaj li sendis sklavon en la ĝusta tempo al la kultivistoj, por ricevi de la kultivistoj el la fruktoj de la vinberejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Kaj ili kaptis lin kaj skurĝis lin, kaj forsendis lin senhava.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'Kaj poste li sendis al ili duan sklavon; kaj ili lin kapvundis kaj malhonoris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'Kaj li sendis alian, kaj ili mortigis lin; kaj multajn aliajn; skurĝante unujn, kaj mortigante aliajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Li havis ankoraŭ unu amatan filon: li sendis lin ankaŭ la lastan al ili, dirante: Ili respektos mian filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Sed tiuj kultivistoj diris inter si: Ĉi tiu estas la heredonto; venu, ni mortigu lin, kaj la heredaĵo estos nia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'Kaj ili kaptis kaj mortigis lin, kaj elĵetis lin ekster la vinberejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Kion do faros la sinjoro de la vinberejo? li venos kaj pereigos la kultivistojn, kaj donos la vinberejon al aliaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Ĉu vi ne legis tiun skribon: Ŝtono, kiun malŝatis la konstruantoj, Fariĝis ŝtono bazangula;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'De la Eternulo ĉi tio fariĝis, Kaj ĝi estas miraklo en niaj okuloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Kaj ili celis kapti lin, sed ili timis la homamason; ĉar ili eksciis, ke li parolis la parabolon kontraŭ ili; kaj forlasinte lin, ili foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Kaj ili sendis al li iujn el la Fariseoj kaj el la Herodanoj, por impliki lin per interparolado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Kaj veninte, ili diris al li: Majstro, ni scias, ke vi estas verama kaj ne zorgas pri iu ajn; ĉar vi ne favoras la personon de homoj, sed instruas laŭ vero la vojon de Dio. Ĉu konvenas doni tributon al Cezaro, aŭ ne?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Ĉu ni donu, aŭ ne donu? Sed li, sciante ilian hipokritecon, diris al ili: Kial vi provas min? alportu al mi denaron, ke mi ĝin vidu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Kaj ili ĝin alportis. Kaj li diris al ili: Kies estas ĉi tiu bildo kaj la surskribaĵo? Kaj ili diris al li: De Cezaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Kaj Jesuo respondis al ili: Redonu al Cezaro la propraĵon de Cezaro, kaj al Dio la propraĵon de Dio. Kaj ili miregis pro li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Kaj venis al li Sadukeoj, kiuj diras, ke ne estas releviĝo; kaj ili demandis lin, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, 'Majstro, Moseo skribis por ni: Se ies frato mortos kaj postlasos edzinon kaj ne lasos infanon, la frato de la mortinto prenu lian edzinon kaj naskigu idaron al sia frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Estis sep fratoj; kaj la unua prenis edzinon, kaj mortinte, ne lasis idaron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'kaj la dua prenis ŝin, kaj mortis, ne lasinte idaron; kaj la tria same;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'kaj la sep ne lasis idaron. Laste post ĉiuj la virino ankaŭ mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'En la releviĝo, por kiu el ili ŝi estos edzino? ĉar ĉiuj sep havis ŝin kiel edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Kaj Jesuo diris al ili: Ĉu vi ne eraras pro tio, ke vi ne scias la Skribojn, nek la potencon de Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Ĉar kiam oni leviĝos el la mortintoj, oni nek edziĝas nek edziniĝas, sed estas kiel anĝeloj en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'Sed pri la mortintoj, ke ili releviĝas, ĉu vi ne legis en la libro de Moseo ĉe la arbetaĵo, kiel Dio parolis al li, dirante: Mi estas la Dio de Abraham kaj la Dio de Isaak kaj la Dio de Jakob?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Li estas Dio ne de la mortintoj, sed de la vivantoj: vi multe eraras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Kaj unu el la skribistoj alvenis kaj aŭskultis la diskutadon, kaj rimarkis, ke li lerte respondas al ili; kaj tiu demandis lin: Kiu ordono estas la unua el ĉiuj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Kaj Jesuo respondis: La unua estas: Aŭskultu, ho Izrael! la Eternulo, nia Dio, la Eternulo estas unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'kaj amu la Eternulon, vian Dion, per via tuta koro kaj per via tuta animo kaj per via tuta menso kaj per via tuta forto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'Kaj jen estas la dua: Amu vian proksimulon kiel vin mem. Pli granda ol ĉi tiuj ne estas alia ordono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'Kaj respondis al li la skribisto: Bone, Majstro, laŭ vero vi respondis, ke Li estas unu, kaj ne ekzistas alia krom Li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'kaj ami Lin per la tuta koro kaj per la tuta intelekto kaj per la tuta forto, kaj ami sian proksimulon kiel sin mem-tio multe pli valoras, ol ĉiuj bruloferoj kaj pekoferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Kaj Jesuo, vidante, ke li respondis prudente, diris al li: Vi ne estas malproksime de la regno de Dio. Kaj neniu plu kuraĝis fari al li demandon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'Kaj responde Jesuo diris, instruante en la templo: Kial diras la skribistoj, ke la Kristo estas Filo de David?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'David mem diris per la Sankta Spirito: La Eternulo diris al mia Sinjoro: Sidu dekstre de Mi, Ĝis Mi faros viajn malamikojn benketo por viaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'David mem nomas lin Sinjoro; kaj kiel do li estas lia filo? Kaj la granda homamaso aŭskultis lin plezure.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'Kaj en sia instruado li diris: Gardu vin kontraŭ la skribistoj, kiuj amas promenadi en roboj kaj salutojn sur la placoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'kaj ĉefseĝojn en la sinagogoj, kaj ĉeflokojn ĉe festenoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'kaj kiuj formanĝas la domojn de vidvinoj, kaj por preteksto ili longe preĝas; ili ricevos pli severan kondamnon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'Kaj sidante kontraŭ la monkesto, li rimarkis, kiel la homoj enĵetas monerojn en la monkeston; kaj multaj riĉuloj enĵetis multon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'Kaj venis unu malriĉa vidvino, kaj enĵetis du leptojn, kiuj faras kodranton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Kaj alvokinte al si siajn disĉiplojn, li diris al ili: Vere mi diras al vi, ke tiu malriĉa vidvino enĵetis pli ol ĉiuj ĵetantoj en la monkeston;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'ĉar ili ĉiuj enĵetis el sia abundo, sed ŝi el sia senhaveco ĵetis ĉion, kion ŝi havis, sian tutan vivrimedon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Kaj dum li eliris el la templo, unu el liaj disĉiploj diris al li: Majstro, jen kiaj ŝtonoj kaj kiaj konstruaĵoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Kaj Jesuo diris al li: Ĉu vi vidas ĉi tiujn grandajn konstruaĵojn? ne estos lasita ĉi tie ŝtono sur ŝtono, kiu ne estos deĵetita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Kaj dum li sidis sur la monto Olivarba rekte kontraŭ la templo, Petro kaj Jakobo kaj Johano kaj Andreo demandis lin aparte:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, 'Diru al ni, kiam tio estos? kaj kio estas la signo, kiam ĉio tio devos plenumiĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Kaj Jesuo ekparolis, kaj diris al ili: Gardu vin, ke neniu vin forlogu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Multaj venos en mia nomo, dirante: Mi estas; kaj ili forlogos multajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Kaj kiam vi aŭdos pri militoj kaj famoj de militoj, ne maltrankviliĝu; tio devas okazi; sed ankoraŭ ne estas la fino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Ĉar leviĝos nacio kontraŭ nacio, kaj regno kontraŭ regno; estos tertremoj en diversaj lokoj, kaj estos malsatoj; tio estas komenco de suferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Sed gardu vin; ĉar oni transdonos vin al sinedrioj, kaj en sinagogoj vi estos skurĝitaj; kaj vi staros antaŭ provincestroj kaj reĝoj pro mi, por atesto al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Kaj la evangelio devas antaŭe esti predikita al ĉiuj nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Kaj kiam oni forkondukos kaj transdonos vin, ne antaŭzorgu, kion vi parolos; sed kio ajn estos donita al vi en tiu horo, tion parolu; ĉar la parolanto estas ne vi, sed la Sankta Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Kaj frato transdonos fraton al morto, kaj patro filon; kaj leviĝos gefiloj kontraŭ gepatroj kaj mortigos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'Kaj vi estos malamataj de ĉiuj pro mia nomo; sed kiu persistos ĝis la fino, tiu estos savita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Sed kiam vi vidos la abomenindaĵon de dezerteco starantan tie, kie ne decas (la leganto komprenu), tiam kiuj estas en Judujo, tiuj forkuru al la montoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'kaj kiu estas sur la tegmento, tiu ne malsupreniru, nek eniru, por preni ion el sia domo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'kaj kiu estas sur la kampo, tiu ne revenu, por preni sian mantelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Sed ve al la gravedulinoj kaj al la suĉigantinoj en tiuj tagoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Kaj preĝu, ke tio ne okazu en vintro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Ĉar tiuj tagoj estos tagoj de aflikto tia, kia ne estis de la komenco de la kreo, kiun Dio kreis, ĝis nun, kaj neniam estos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'Kaj se la Eternulo ne malplilongigus la tagojn, neniu karno estus savita; sed pro la elektitoj, kiujn Li elektis, Li malplilongigis la tagojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'Kaj tiam se iu diros al vi: Jen ĉi tie la Kristo, aŭ, Jen tie; ne kredu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'ĉar leviĝos falsaj kristoj kaj falsaj profetoj, kaj faros signojn kaj miraklojn, por erarigi, se eble, la elektitojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Sed gardu vin; jen mi ĉion antaŭdiris al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'Sed en tiuj tagoj, post tiu aflikto, la suno mallumiĝos kaj la luno ne donos sian lumon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'kaj la steloj falados el la ĉielo, kaj la potencoj, kiuj estas en la ĉieloj, ŝanceliĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'Kaj tiam oni vidos la Filon de homo, venantan en nuboj kun granda potenco kaj gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'Kaj tiam li elsendos la anĝelojn kaj kolektos siajn elektitojn el la kvar ventoj, de la limo de la tero ĝis la limo de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'De la figarbo lernu ĝian parabolon: kiam ĝia branĉo jam moliĝas kaj aperigas foliojn, vi scias, ke la somero estas proksima;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'tiel same vi, kiam vi vidos, ke tio okazas, tiam sciu, ke li estas proksima, ĉe la pordoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Vere mi diras al vi: Ĉi tiu generacio ne forpasos, antaŭ ol ĉio tio fariĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'La ĉielo kaj la tero forpasos, sed miaj vortoj ne forpasos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Sed pri tiu tago kaj la horo scias neniu, eĉ ne la anĝeloj en la ĉielo, nek la Filo, sed nur la Patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Gardu vin, viglu kaj preĝu; ĉar vi ne scias, kiam estos la ĝusta tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'Kiel homo forvojaĝinta, kiu lasis sian domon kaj donis aŭtoritaton al siaj sklavoj, al ĉiu lian propran laboron, kaj ordonis al la pordisto, ke li viglu:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'vi do viglu; ĉar vi ne scias, kiam venos la domomastro, ĉu vespere, ĉu noktomeze, ĉu ĉe la kokokrio, ĉu frumatene;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'por ke li ne venu subite kaj ne trovu vin dormantaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'Kaj kion mi diras al vi, tion mi diras al ĉiuj: Viglu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Kaj post du tagoj estis la Pasko kaj la festo de macoj; kaj la ĉefpastroj kaj skribistoj serĉis, kiamaniere ili povu per ruzo lin kapti kaj mortigi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'ĉar ili diris: Ne dum la festo, por ke ne estu tumulto de la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Kaj dum li estis en Betania, en la domo de Simon, la leprulo, kiam li sidis ĉe manĝo, venis virino, havanta alabastran vazon da pura narda ŝmiraĵo, tre multekosta; kaj rompinte la vazon, ŝi surverŝis lian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Kaj iuj indignis inter si, dirante: Por kio fariĝis ĉi tiu malŝparo de la ŝmiraĵo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Ĉar ĉi tiun ŝmiraĵon oni povus vendi por pli ol tricent denaroj, kaj doni al malriĉuloj. Kaj ili murmuris kontraŭ ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Kaj Jesuo diris: Lasu ŝin; kial vi ĝenas ŝin? ŝi faris bonan faron al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Ĉar la malriĉulojn vi ĉiam havas kun vi, kaj kiam ajn vi volas, vi povas bonfari al ili; sed min vi ne ĉiam havas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Kion ŝi povis, tion ŝi faris; ŝi antaŭfaris la ŝmiron de mia korpo por la entombigo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Vere mi diras al vi: Kie ajn estos predikata la evangelio en la tuta mondo, tio ankaŭ, kion ŝi faris, estos priparolata, por memoraĵo de ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Kaj Judas Iskariota, kiu estis unu el la dek du, foriris al la ĉefpastroj, por transdoni lin al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Kaj aŭdinte, ili ĝojis, kaj promesis doni al li monon. Kaj li serĉis, kiamaniere oportune transdoni lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Kaj en la unua tago de la macoj, kiam oni buĉis la Paskon, liaj disĉiploj diris al li: Kien vi volas, ke ni iru, kaj pretigu, por ke vi manĝu la Paskon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Kaj li sendis du el siaj disĉiploj, kaj diris al ili: Iru en la urbon, kaj vin renkontos viro, portanta kruĉon da akvo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'lin sekvu, kaj kien li eniros, tie diru al la domomastro: La Majstro diras: Kie estas mia gastoĉambro, en kiu mi manĝos la Paskon kun miaj disĉiploj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'Kaj li mem montros al vi grandan supran ĉambron, prete aranĝitan; kaj tie vi pretigu por ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Kaj foriris la disĉiploj kaj iris en la urbon, kaj trovis tiel, kiel li diris al ili; kaj ili pretigis la Paskon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Kaj kiam vesperiĝis, li venis kun la dek du.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'Kaj dum ili sidis kaj manĝis, Jesuo diris: Vere mi diras al vi, ke unu el vi perfidos min, unu, kiu manĝas kun mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Kaj ili komencis malĝoji, kaj diri al li unu post la alia: Ĉu eble mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Sed li diris al ili: Unu el la dek du, kiu trempas kun mi en la pladon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'La Filo de homo iros, kiel estas skribite pri li; sed ve al tiu viro, de kiu la Filo de homo estos perfidita! Se tiu homo ne estus naskita, estus bone por li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'Kaj dum ili manĝis, li prenis panon, kaj, beninte, dispecigis ĝin kaj donis al ili, kaj diris: Prenu; ĉi tio estas mia korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'Kaj li prenis kalikon, kaj, doninte dankon, li donis al ili; kaj ĉiuj trinkis el ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'Kaj li diris al ili: Ĉi tio estas mia sango de la interligo, kiu estas elverŝata por multaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Vere mi diras al vi: Mi ne plu trinkos el la frukto de la vinberarbo, ĝis tiu tago, kiam mi trinkos ĝin novan en la regno de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'Kaj kantinte himnon, ili foriris al la monto Olivarba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Kaj Jesuo diris al ili: Vi ĉiuj ofendiĝos; ĉar estas skribite: Mi frapos la paŝtiston, kaj la ŝafoj diskuros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Tamen post mia releviĝo, mi iros antaŭ vi en Galileon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Sed Petro diris al li: Eĉ se ĉiuj ofendiĝos, tamen ne mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'Kaj Jesuo diris al li: Vere mi diras al vi, ke hodiaŭ en ĉi tiu nokto, antaŭ ol dufoje krios koko, vi trifoje malkonfesos min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Sed tre insiste li diris: Eĉ se mi devos morti kun vi, mi neniel vin malkonfesos. Kaj tiel same diris ili ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'Kaj ili venis al loko, kies nomo estas Getsemane; kaj li diris al siaj disĉiploj: Sidu ĉi tie, dum mi preĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'Kaj li prenis kun si Petron kaj Jakobon kaj Johanon, kaj komencis tre konsterniĝi kaj maltrankviliĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'Kaj li diris al ili: Tre malĝoja estas mia animo, eĉ ĝis morto; restu ĉi tie, kaj viglu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'Kaj irinte iom antaŭen, li falis sur la teron, kaj preĝis, ke, se povas esti, la horo pasu for de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'Kaj li diris: Aba, Patro, ĉio estas ebla ĉe Vi: forportu de mi ĉi tiun kalikon; tamen estu ne tio, kion mi volas, sed kion Vi volas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Kaj li venis, kaj trovis ilin dormantaj, kaj diris al Petro: Simon, ĉu vi dormas? ĉu vi ne havis forton vigli eĉ unu horon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Viglu kaj preĝu, por ke vi ne eniru en tenton; la spirito ja estas fervora, sed la karno estas malforta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'Kaj denove foririnte, li preĝis, dirante la samajn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'Kaj denove reveninte, li trovis ilin dormantaj, ĉar iliaj okuloj peziĝis; kaj ili ne sciis, kion respondi al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'Kaj li venis la trian fojon, kaj diris al ili: Dormu nun kaj ripozu; sufiĉas; venis la horo; jen la Filo de homo estas perfidata en la manojn de pekuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Leviĝu, ni iru; jen mia perfidanto alproksimiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'Kaj tuj, dum li ankoraŭ parolis, venis Judas, unu el la dek du; kaj kun li homamaso kun glavoj kaj bastonoj venis de la ĉefpastroj kaj la skribistoj kaj la pliaĝuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'Kaj lia perfidanto jam antaŭe aranĝis kun ili signon, dirante: Kiun mi kisos, tiu estas li; kaptu kaj forkonduku lin garde.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'Kaj veninte, li tuj iris al li, kaj diris: Rabeno; kaj kisis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Kaj ili metis la manojn sur lin kaj arestis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Sed unu el tiuj, kiuj staris apude, eltiris la glavon kaj frapis la sklavon de la ĉefpastro, kaj detranĉis al li la orelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Kaj Jesuo responde diris al ili: Ĉu vi elvenis, kvazaŭ kontraŭ rabiston, kun glavoj kaj bastonoj, por kapti min?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Ĉiutage mi estis inter vi en la templo, instruante, kaj vi ne arestis min; tamen, ke plenumiĝu la Skriboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'Kaj ĉiuj forlasis lin kaj forkuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Kaj sekvis lin unu junulo, vestita per tolaĵo ĉirkaŭ la nuda korpo; kaj oni kaptis lin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'sed lasinte la tolaĵon, li forkuris nuda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'Kaj oni forkondukis Jesuon al la ĉefpastro; kaj kunvenis ĉe li ĉiuj ĉefpastroj kaj pliaĝuloj kaj skribistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Kaj Petro malproksime sekvis lin ĝis interne de la korto de la ĉefpastro; kaj sidis kun la subuloj kaj sin varmigis apud la fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Sed la ĉefpastroj kaj la tuta sinedrio serĉis ateston kontraŭ Jesuo, por lin mortigi, kaj ne trovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Ĉar multaj malvere atestis kontraŭ li, kaj iliaj atestoj ne akordiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Kaj elpaŝis iuj, kaj malvere atestis kontraŭ li, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, 'Ni aŭdis lin diri: Mi detruos ĉi tiun sanktejon manfaritan, kaj en la daŭro de tri tagoj mi konstruos alian ne manfaritan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Kaj eĉ tiel ilia atesto ne akordiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Kaj la ĉefpastro stariĝis en la mezo, kaj demandis Jesuon, dirante: Ĉu vi respondas nenion? kion atestas ĉi tiuj kontraŭ vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Sed li silentadis kaj respondis nenion. Denove la ĉefpastro demandis lin, kaj diris al li: Ĉu vi estas la Kristo, la Filo de la Benato?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'Kaj Jesuo diris: Mi estas; kaj vi vidos la Filon de homo, sidantan dekstre de la Potenco kaj venantan kun la nuboj de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Kaj la ĉefpastro disŝiris siajn vestojn, kaj diris: Pro kio ni plu bezonas atestantojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Vi aŭdis la blasfemon: kion vi opinias? Kaj ili ĉiuj juĝis lin kondamninda al morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'Kaj iuj komencis kraĉi sur lin, kaj ĉirkaŭkovri lian vizaĝon, kaj vangofrapi lin, kaj diri al li: Profetu; kaj la subuloj frapis lin per la manplatoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'Kaj dum Petro estis malsupre sur la korto, venis unu el la servantinoj de la ĉefpastro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'kaj vidante Petron sin varmigantan, ŝi rigardis lin, kaj diris: Vi ankaŭ estis kun la Nazaretano, kun tiu Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Sed li malkonfesis, dirante: Mi ne scias, nek komprenas, kion vi diras; kaj li iris en la vestiblon; kaj koko kriis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'Kaj lin vidinte, la servantino denove komencis diri al la apudstarantoj: Tiu estas el ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'Kaj li denove malkonfesis. Kaj post iom da tempo la apudstarantoj denove diris al Petro: Vere vi estas el ili, ĉar vi estas ja Galileano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Kaj li komencis malbeni kaj ĵuri: Mi ne konas tiun homon, pri kiu vi parolas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'Kaj tuj la duan fojon koko kriis. Kaj Petro ekrememoris la vorton, kiun Jesuo diris al li: Antaŭ ol dufoje krios koko, vi trifoje malkonfesos min. Kaj pripensinte, li ekploris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'Tuj matene la ĉefpastroj, farinte interkonsilon kun la pliaĝuloj kaj skribistoj kaj la tuta sinedrio, ligis Jesuon kaj forkondukis lin kaj transdonis lin al Pilato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'Kaj Pilato demandis lin: Ĉu vi estas la Reĝo de la Judoj? Kaj responde li diris al li: Vi diras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Kaj la ĉefpastroj multe lin akuzis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Kaj Pilato denove lin demandis: Ĉu vi respondas nenion? vidu, pri kiom da aferoj oni vin akuzas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Sed Jesuo ankoraŭ nenion respondis, tiel ke Pilato miris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Ĉe tiu festo li kutimis liberigi al ili unu malliberulon, iun ajn, kiun ili pripetis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Kaj estis unu, nomata Barabas, katenita kun la ribelintoj, kiuj en la ribelo faris mortigon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'Kaj suprenveninte, la homamaso komencis peti lin pri tio, kion li kutimis fari por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Kaj Pilato respondis al ili, dirante: Ĉu vi volas, ke mi liberigu al vi la Reĝon de la Judoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Ĉar li eksciis, ke pro envio la ĉefpastroj transdonis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Sed la ĉefpastroj instigis la homamason, ke prefere li liberigu al ili Barabason.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Kaj Pilato, denove respondante, diris al ili: Kion do mi faru al tiu, kiun vi nomas Reĝo de la Judoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Kaj ili denove ekkriis: Krucumu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Kaj Pilato diris al ili: Kial? kian malbonon li faris? Sed ili des pli ekkriis: Krucumu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Kaj Pilato, volante kontentigi la homamason, liberigis al ili Barabason, kaj, skurĝinte Jesuon, transdonis lin, por esti krucumita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Kaj la soldatoj forkondukis lin en la korton, kiu estas la Pretorio, kaj kunvokis la tutan kohorton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'Kaj ili vestis lin per purpuro, kaj plektinte dornan kronon, surmetis ĝin al li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'kaj ili komencis aklami lin: Saluton, Reĝo de la Judoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'Kaj ili frapis lian kapon per kano, kaj kraĉis sur lin, kaj ekgenuinte, kliniĝis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'Kaj mokinte lin, ili demetis de li la purpuran veston, kaj surmetis liajn proprajn vestojn. Kaj ili elkondukis lin, por krucumi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'Kaj ili devigis al servado unu preterpasanton, venantan de la kamparo, Simonon, Kirenanon, patron de Aleksandro kaj Rufo, ke li portu lian krucon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'Kaj ili kondukis lin al la loko Golgota, tio estas, Loko de Kranio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'Kaj ili donis al li vinon kun mirho enmiksita, sed li ne akceptis ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'Kaj ili krucumis lin kaj dividis inter si liajn vestojn, ĵetante lotojn sur ili, kion ĉiu el ili ricevu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'Kaj estis la tria horo, kaj ili krucumis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'Kaj la surskribo de lia akuzo estis surskribita: LA REĜO DE LA JUDOJ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'Kaj kun li ili krucumis du rabistojn, unu dekstre kaj unu maldekstre de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'Kaj plenumiĝis la Skribo, kiu diras: Kaj li estis alkalkulita al krimuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'Kaj la preterpasantoj insultis lin, balancante la kapon, kaj dirante: Ha, ha! vi, kiu detruas la sanktejon kaj konstruas ĝin en la daŭro de tri tagoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'savu vin, deirante de la kruco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Tiel same ankaŭ la ĉefpastroj, mokante inter si kun la skribistoj, diris: Aliajn li savis; sin mem li ne povas savi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'La Kristo, la Reĝo de Izrael, deiru ja nun de la kruco, por ke ni vidu kaj kredu. Kaj tiuj, kiuj estis krucumitaj kun li, insultis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'Kaj kiam venis la sesa horo, fariĝis mallumo sur la tuta lando ĝis la naŭa horo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'Kaj je la naŭa horo Jesuo kriis per laŭta voĉo: Eloi, Eloi, lama sabaĥtani; tio estas: Mia Dio, mia Dio, kial Vi forlasis min?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'Kaj iuj el la apudstarantoj, aŭdinte, diris: Jen li vokas Elijan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Kaj unu kuris, kaj plenigis spongon per vinagro, kaj metinte ĝin sur kanon, donis al li trinki, dirante: Lasu; ni vidu, ĉu venos Elija, por depreni lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Sed Jesuo, eliginte laŭtan krion, ellasis for la spiriton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'Kaj la kurteno de la sanktejo disŝiriĝis en du pecojn de supre ĝis malsupre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Kaj kiam la centestro, kiu apudstaris kontraŭ li, vidis, ke li tiamaniere ellasis for la spiriton, li diris: Vere ĉi tiu viro estis Filo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Estis ankaŭ virinoj, rigardantaj de malproksime, inter kiuj estis Maria Magdalena, kaj Maria, la patrino de Jakobo la malgranda kaj de Joses, kaj Salome;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'kiuj sekvis lin, kiam li estis en Galileo, kaj servadis al li; kaj multaj aliaj virinoj, kiuj suprenvenis kun li en Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'Kaj kiam jam vesperiĝis, pro tio, ke estas la Preparado, tio estas, la tago antaŭ sabato,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'venis Jozef el Arimateo, honorinda konsilanto, kiu mem atendadis la regnon de Dio; kaj li kuraĝe eniris al Pilato, kaj petis la korpon de Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Kaj Pilato miris, ĉu li jam mortis; kaj alvokinte la centestron, li demandis lin, ĉu li de longe estas mortinta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'Kaj sciiĝinte de la centestro, li donis al Jozef la korpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'Kaj li aĉetis tolaĵon, kaj deprenis lin kaj envolvis lin en la tolaĵo, kaj metis lin en tombon, kiu estis elhakita el ŝtonego; kaj li alrulis ŝtonon al la enirejo de la tombo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Kaj Maria Magdalena, kaj Maria, la patrino de Joses, vidis, kien oni metis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Kaj kiam la sabato jam pasis, Maria Magdalena, kaj Maria, la patrino de Jakobo, kaj Salome aĉetis aromaĵojn, por ke ili iru kaj ŝmiru lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'Kaj tre frue en la unua tago de la semajno ili venis al la tombo, kiam la suno ĵus leviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'Kaj ili diris inter si: Kiu derulos por ni la ŝtonon de la enirejo de la tombo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'kaj suprenrigardante, ili vidis, ke la ŝtono estas derulita; ĉar ĝi estis tre granda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Kaj enirinte en la tombon, ili vidis junulon sidantan ĉe la dekstra flanko, vestitan per blanka robo; kaj ili miregis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Sed li diris al ili: Ne miregu; vi serĉas Jesuon, la Nazaretanon, la krucumitan: li leviĝis; li ne estas ĉi tie; jen la loko, kien oni metis lin!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Sed iru, diru al liaj disĉiploj kaj al Petro: Li iras antaŭ vi en Galileon; tie vi vidos lin, kiel li diris al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'Kaj elirinte, ili forkuris de la tombo, ĉar tremado kaj konfuziĝo posedis ilin; kaj ili diris nenion al iu, ĉar ili timis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Sed leviĝinte frue en la unua tago de la semajno, li aperis unue al Maria Magdalena, el kiu li elpelis sep demonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Ŝi iris, kaj sciigis ĝin al la homoj, kiuj estis kun li, dum ili malĝojis kaj ploris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Kaj aŭdinte, ke li vivas kaj estas vidita de ŝi, ili ne kredis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Kaj post tio li aperis sub alia formo al du el ili, dum ili piediris en la kamparon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Kaj foririnte, ili sciigis al la aliaj, kaj ankaŭ ili ne kredis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Poste li aperis al la dek unu, dum ili sidis ĉe manĝo, kaj riproĉis ilian nekredemon kaj korobstinon, ĉar ili ne kredis tiujn, kiuj vidis lin leviĝintan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'Kaj li diris al ili: Iru en la tutan mondon, kaj prediku la evangelion al ĉiu kreitaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Kiu kredos kaj estos baptita, tiu estos savita; sed kiu ne kredos, tiu estos kondamnita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Kaj jenaj signoj sekvos la kredantojn: en mia nomo ili elpelos demonojn; ili parolos per lingvoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'ili prenos en manojn serpentojn, kaj se ili trinkos ion mortigan, ĝi neniel difektos ilin; sur malsanulojn ili metos la manojn, kaj ili saniĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Tiam la Sinjoro Jesuo, post kiam li parolis al ili, estis ricevita supren en la ĉielon, kaj sidiĝis dekstre de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Kaj elirinte, ili predikis ĉie, kaj la Sinjoro laboris kun ili kaj fortikigis la vorton per la signoj, kiuj sekvis. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Ĉar multaj jam entreprenis aranĝi historion pri la faktoj, kiuj estas konstatitaj inter ni,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'kiel ilin transdonis al ni tiuj, kiuj de la komenco vidis mem kaj estis administrantoj de la vorto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'ŝajnis bone ankaŭ al mi, esplorinta ĉion atente de la komenco, skribi en ordo al vi, plej eminenta Teofilo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'por ke vi povu scii la certecon pri la aferoj, pri kiuj vi estas instruita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'En la tagoj de Herodo, reĝo de Judujo, estis pastro nomata Zeĥarja, el la deĵora grupo de Abija; kaj li havis edzinon el la filinoj de Aaron, kaj ŝia nomo estis Elizabeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Kaj ambaŭ estis justaj antaŭ Dio, irantaj laŭ ĉiuj ordonoj kaj instruoj de la Eternulo sen riproĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Kaj ili ne havis infanon, ĉar Elizabeto estis senfrukta, kaj ili ambaŭ estis en profunda aĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Kaj dum li plenumis sian pastradon antaŭ Dio en la vico de sia grupo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'laŭ la kutimo de la pastra ofico estis lia loto eniri en la sanktejon de la Eternulo kaj incensadi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'Kaj la tuta amaso de la popolo preĝis ekstere dum la horo de la incensado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Kaj aperis antaŭ li anĝelo de la Eternulo, staranta dekstre de la altaro de incensado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Kaj Zeĥarja maltrankviliĝis, kiam li vidis lin, kaj sur lin falis timo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Sed la anĝelo diris al li: Ne timu, Zeĥarja; ĉar via preĝo estas aŭdita, kaj via edzino Elizabeto naskos al vi filon, kaj vi donos al li la nomon Johano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Kaj vi havos ĝojon kaj feliĉon, kaj multaj ĝojos pro lia naskiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Ĉar li estos granda antaŭ la Sinjoro, kaj li ne trinkos vinon nek ebriigaĵon; kaj li estos plena de la Sankta Spirito jam de la ventro de sia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'Kaj multajn el la filoj de Izrael li turnos al la Eternulo, ilia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'Kaj li iros antaŭ Lia vizaĝo en la spirito kaj potenco de Elija, por turni la korojn de la patroj al la infanoj kaj la malobeemajn al la saĝeco de la justuloj, por pretigi por la Sinjoro popolon preparitan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Kaj Zeĥarja diris al la anĝelo: Per kio mi scios tion? ĉar mi estas maljunulo, kaj mia edzino havas profundan aĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'Kaj la anĝelo responde diris al li: Mi estas Gabriel, kiu staras antaŭ Dio; kaj mi estas sendita, por paroli al vi kaj fari al vi tiun bonan sciigon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'Kaj jen vi silentos kaj estos ne kapabla paroli, ĝis la tago, kiam tio okazos, ĉar vi ne kredis miajn vortojn, kiuj plenumiĝos siatempe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'Kaj la popolo atendis Zeĥarjan, kaj miris pro lia restado en la sanktejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Kaj kiam li elvenis, li ne povis paroli al ili; kaj ili eksciis, ke li vidis vizion en la sanktejo; kaj li faradis signojn al ili, kaj restis muta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'Kaj kiam finiĝis la tagoj de lia pastrado, li foriris en sian domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'Kaj post tiuj tagoj lia edzino Elizabeto gravediĝis, kaj kaŝis sin kvin monatojn, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, 'Tiamaniere agis la Eternulo rilate al mi en la tagoj, kiam Li favore rigardis min, por forpreni mian riproĉon inter homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'Kaj en la sesa monato la anĝelo Gabriel estis sendita de Dio en urbon de Galileo, nomatan Nazaret,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'al virgulino fianĉinigita kun viro, kies nomo estis Jozef, el la domo de David; kaj la nomo de la virgulino estis Maria.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'Kaj li venis al ŝi, kaj diris: Saluton al vi la grace favorita, la Eternulo estas kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Sed ŝi tre maltrankviliĝis ĉe tiu diro, kaj konsideris, kia povas esti tiu saluto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'Kaj la anĝelo diris al ŝi: Ne timu, Maria; ĉar vi trovis gracon antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'Kaj jen vi gravediĝos en via ventro kaj naskos filon, kaj vi nomos lin JESUO.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Li estos granda, kaj estos nomata Filo de la Plejaltulo; kaj Dio, la Eternulo, donos al li la tronon de lia patro David;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'kaj li reĝos super la domo de Jakob eterne, kaj lia regno ne havos finon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Kaj Maria diris al la anĝelo: Kiel estos tio, ĉar mi ne konas viron?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'Kaj la anĝelo responde diris al ŝi: La Sankta Spirito venos sur vin, kaj la potenco de la Plejaltulo superombros vin; pro kio ankaŭ la naskotaĵo estos nomata sankta, la Filo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'Kaj jen via parencino Elizabeto ankaŭ gravediĝis je filo en sia maljuneco, kaj la nuna monato estas la sesa por ŝi, kiun oni nomis senfrukta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'Ĉar ĉe Dio nenio estas neebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Kaj Maria diris: Jen la sklavino de la Eternulo; estu al mi laŭ via diro. Kaj la anĝelo foriris de ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'Kaj en tiuj tagoj Maria leviĝis kaj senprokraste vojaĝis en la montan regionon, en urbon de Judujo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'kaj enirinte en la domon de Zeĥarja, ŝi salutis Elizabeton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'Kaj kiam Elizabeto aŭdis la saluton de Maria, la infaneto eksaltis en ŝia ventro; kaj Elizabeto pleniĝis de la Sankta Spirito,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'kaj ŝi levis sian voĉon per laŭta krio, kaj diris: Benata vi estas inter virinoj, kaj benata estas la frukto de via ventro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'Kaj pro kio okazas al mi ĉi tio, ke la patrino de mia Sinjoro venas al mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Ĉar jen kiam la voĉo de via saluto venis en miajn orelojn, la infaneto ĝoje eksaltis en mia ventro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'Kaj feliĉa estas ŝi, kiu kredis, ĉar plenumiĝos tio, kio estas dirita al ŝi de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Kaj Maria diris: Mia animo altigas la Eternulon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'Kaj mia spirito ĝojis en Dio, mia Savanto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'Ĉar Li rigardis la humilecon de Sia sklavino; Ĉar jen de nun ĉiuj generacioj nomos min feliĉa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'Ĉar la Potenculo faris al mi grandaĵojn, Kaj sankta estas Lia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'Kaj Lia boneco estas por ĉiuj generacioj Al tiuj, kiuj Lin timas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Li montris forton per Sia brako, Li dispelis fierulojn en la penso de ilia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Li malaltigis potenculojn de iliaj tronoj, Kaj Li altigis humilulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Malsatulojn Li plenigis per bonaĵo, Kaj riĉulojn Li forsendis malplenaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Li helpis Sian servanton Izrael, Memorante Sian korfavoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'Kiel Li parolis al niaj patroj, Al Abraham kaj al lia idaro eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Kaj Maria loĝis ĉi ŝi tri monatojn, kaj reiris al sia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Kaj venis por Elizabeto la tempo, en kiu ŝi devis naski; kaj ŝi naskis filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'Kaj ŝiaj najbaroj kaj ŝiaj parencoj aŭdis, ke la Eternulo pligrandigis Sian bonecon al ŝi; kaj ili ĝojis kun ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'Kaj en la oka tago oni venis, por cirkumcidi la infaneton; kaj ili eknomis lin Zeĥarja, laŭ la nomo de lia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'Kaj lia patrino responde diris: Tute ne; sed li estos nomata Johano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'Kaj ili diris al ŝi: El via parencaro estas neniu, kiu estas nomata per tiu nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'Kaj ili faris signojn al lia patro pri tio, kiel li volas, ke li estu nomata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'Kaj li petis tabuleton, kaj skribis jene: Lia nomo estas Johano. Kaj ĉiuj miris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'Kaj tuj lia buŝo malfermiĝis, kaj lia lango liberiĝis; kaj li parolis, glorante Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'Kaj timo venis sur ĉiujn, kiuj loĝis ĉirkaŭ ili, kaj tra la tuta monta regiono de Judujo disvastiĝis rakonto pri ĉio tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'Kaj ĉiuj aŭdantoj konservis tion en sia koro, dirante: Kia do estos ĉi tiu knabeto? Ĉar la mano de la Eternulo estis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'Kaj lia patro Zeĥarja pleniĝis de la Sankta Spirito, kaj profetis, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, 'Benata estu la Eternulo, la Dio de Izrael, Ĉar Li vizitis Sian popolon kaj faris por ili elaĉeton,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'Kaj levis kornon de savo por ni En la domo de Sia servanto David,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'Kiel Li parolis per la buŝo de Siaj sanktaj profetoj, de post la komenco de la mondo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'Savadon el niaj malamikoj kaj el la mano de ĉiuj niaj malamantoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'Por montri Sian bonecon ĉe niaj patroj, Kaj por memori Sian sanktan interligon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'La ĵuron, kiun Li ĵuris al nia patro Abraham;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'Ke Li donos al ni, ke, liberigite el la mano de niaj malamikoj, Ni servu Lin sentime,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'En sankteco kaj justeco antaŭ Li ĉiujn niajn tagojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'Kaj vi, infano, estos nomata profeto de la Plejaltulo, Ĉar vi iros antaŭ la vizaĝo de la Sinjoro, por pretigi liajn vojojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'Por doni al lia popolo scion de savo En la pardonado de iliaj pekoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'Pro la kompata koro de nia Dio, Per kiu nin vizitis la sunleviĝo de supre,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'Por lumi sur tiujn, kiuj sidas en mallumo kaj en la ombro de morto, Por gvidi niajn piedojn en la vojojn de paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'Kaj kreskis la infano kaj fortiĝis en spirito, kaj estis en la dezertoj ĝis la tago de sia ekmontriĝo al Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'Kaj en tiuj tagoj eliris dekreto de Cezaro Aŭgusto, ke la tuta mondo estu registrita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Ĉi tiu estis la unua registrado, farita, kiam Kirenio estis reganto de Sirio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Kaj ĉiuj iris, por esti registritaj, ĉiu al sia urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Kaj Jozef ankaŭ supreniris el Galileo, el la urbo Nazaret, en Judujon, al la urbo de David, kiu estas nomata Bet-Leĥem, ĉar li estis el la domo kaj familio de David,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'por esti registrita kun sia fianĉino Maria, kiu estis graveda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Kaj dum ili estis tie, venis la tagoj por ŝia akuŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'Kaj ŝi naskis sian unuan filon, kaj ŝi ĉirkaŭvindis lin kaj kuŝigis lin en staltrogon, ĉar ne estis loko por ili en la gastejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'Kaj en tiu sama regiono estis paŝtistoj, kiuj kamploĝis kaj nokte gardis sian gregon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'Kaj anĝelo de la Eternulo alstaris apud ili, kaj la gloro de la Eternulo brilis ĉirkaŭ ili, kaj ili timis per granda timo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Kaj la anĝelo diris al ili: Ne timu; ĉar jen mi venigas al vi bonan sciigon de granda ĝojo, kiu estos al la tuta popolo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'ĉar hodiaŭ estas naskita por vi, en la urbo de David, Savanto, kiu estas Kristo, la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'Kaj jen la signo por vi: vi trovos infaneton, ĉirkaŭvinditan kaj kuŝantan en staltrogo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'Kaj subite estis kun la anĝelo amaso de la ĉiela armeo, laŭdante Dion, kaj dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Gloro al Dio en la supera alto, Kaj sur la tero paco, inter homoj Difavoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'Kaj kiam la anĝeloj foriris de ili en la ĉielon, la paŝtistoj diris unu al alia: Ni jam iru ĝis Bet-Leĥem, kaj vidu ĉi tiun okazintaĵon, kiun la Eternulo sciigis al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Kaj rapidante, ili iris, kaj trovis Marian kaj Jozefon, kaj la infaneton kuŝantan en la staltrogo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Kaj tion vidinte, ili sciigis pri la diro, kiu estis parolita al ili pri ĉi tiu infano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'Kaj ĉiuj aŭdintoj miris pri tio, kion rakontis al ili la paŝtistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Sed Maria konservis ĉiujn tiujn dirojn kaj pripensis ilin en sia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Kaj la paŝtistoj revenis, glorante kaj laŭdante Dion pri ĉio, kion ili aŭdis kaj vidis, kiel estis parolite al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'Kaj kiam jam pasis ok tagoj por cirkumcidi lin, oni donis al li la nomon JESUO, kiel li estis nomita de la anĝelo, antaŭ ol li estis en la ventro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'Kaj kiam finiĝis la tagoj de ilia purigado laŭ la leĝo de Moseo, ili alportis lin al Jerusalem, por prezenti lin al la Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, 'kiel estas skribite en la leĝo de la Eternulo: Ĉiu virseksulo, kiu malfermas la uteron, estu dediĉita al la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'kaj por alporti oferon laŭ tio, kio estas dirita en la leĝo de la Eternulo: Paron da turtoj, aŭ du kolombidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'Kaj jen en Jerusalem estis viro, kies nomo estis Simeon, kaj ĉi tiu estis justa kaj pia, atendanta la konsoladon de Izrael; kaj la Sankta Spirito estis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'Kaj estis montrite al li de la Sankta Spirito, ke li ne mortos, ĝis li vidos la Kriston de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'Kaj li venis per la Spirito en la templon; kaj kiam la gepatroj enportis la infanon Jesuo, por fari pri li laŭ la kutimo de la leĝo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'tiam li ricevis lin en siajn brakojn, kaj benis Dion, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, 'Nun, ho Eternulo, Vi ellasas Vian servanton, Laŭ Via vorto, en paco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'Ĉar miaj okuloj vidis Vian savon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'Kiun Vi preparis antaŭ la vizaĝo de ĉiuj popoloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'Lumon por malkaŝo al la gentoj, Kaj gloron de Via popolo Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'Kaj lia patro kaj lia patrino miris pri tio, kio estis parolita pri li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'kaj Simeon ilin benis, kaj diris al Maria, lia patrino: Jen ĉi tiu estas metita por la falo kaj leviĝo de multaj en Izrael, kaj por signo kontraŭparolata;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, 'kaj ankaŭ vian animon glavo trapasos; por ke la pensoj de multaj koroj malkaŝiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'Kaj estis unu profetino, Anna, filino de Fanuel, el la tribo de Aŝer (ŝi estis grandaĝa, loĝinte sep jarojn kun sia edzo de post sia virgeco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'kaj estinte vidvino okdek kvar jarojn), kiu neniam foriris el la templo, adorante per fastoj kaj preĝoj nokte kaj tage.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'Kaj alveninte ĝuste en tiu horo, ŝi dankis Dion, kaj parolis pri li al ĉiuj, kiuj atendadis la elaĉeton de Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'Kaj kiam ili jam faris ĉion, konforme al la leĝo de la Eternulo, ili revenis en Galileon, al sia urbo Nazaret.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'Kaj la infano kreskadis kaj fortiĝis, pleniĝante de saĝeco; kaj la graco de Dio estis sur li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'Kaj liaj gepatroj iris ĉiujare al Jerusalem ĉe la Paska festo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'Kaj kiam li estis dekdujara, ili supreniris laŭ la kutimo de la festo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'kaj kiam ili jam pasigis la tagojn, ĉe ilia returniĝo la knabo Jesuo restis en Jerusalem, kaj liaj gepatroj tion ne sciis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'sed supozante, ke li estas en la karavano, ili iris tagan vojaĝon, kaj serĉis lin inter siaj parencoj kaj konatoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'kaj ne trovinte lin, ili reiris al Jerusalem, serĉante lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'Kaj post tri tagoj ili trovis lin en la templo, kie li sidis meze de la instruistoj, aŭskultante ilin kaj metante al ili demandojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'kaj ĉiuj, kiuj aŭdis lin, miregis pro lia kompreno kaj liaj respondoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'Kaj ili miris, vidante lin, kaj lia patrino diris al li: Filo, kial vi tiel agis kontraŭ ni? jen via patro kaj mi serĉis vin kun malĝojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'Kaj li diris al ili: Kial vi serĉis min? ĉu vi ne sciis, ke mi devas esti en la domo de mia Patro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Kaj ili ne komprenis la diron, kiun li parolis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'Kaj li malsupreniris kun ili, kaj venis en Nazareton, kaj li estis obeema al ili; kaj lia patrino konservis ĉiujn tiujn dirojn en sia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'Kaj Jesuo progresis en saĝeco kaj staturo, kaj en graco ĉe Dio kaj homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'En la dek-kvina jaro de la regado de Tiberio Cezaro, kiam Pontio Pilato estis provincestro de Judujo, kaj Herodo estis tetrarĥo de Galileo, kaj lia frato Filipo tetrarĥo de la regiono Iturea kaj Traĥonitis, kaj Lisanio tetrarĥo de Abilene,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'dum la ĉefpastreco de Anas kaj Kajafas, venis la vorto de Dio al Johano, filo de Zeĥarja, en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'Kaj li venis en la tutan regionon ĉirkaŭ Jordan, predikante la bapton de pento por la pardonado de pekoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'kiel estas skribite en la libro de la vortoj de la profeto Jesaja: Voĉo de krianto en la dezerto: Pretigu la vojon de la Eternulo, Rektigu Liajn irejojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Ĉiu valo leviĝos, Kaj ĉiu monto kaj monteto malaltiĝos, Kaj la malebenaĵo fariĝos ebenaĵo, Kaj la malglataj vojoj glatiĝos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'Kaj ĉiu karno vidos la savon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Li do diris al la homamasoj, kiuj eliris, por esti baptitaj de li: Ho vipuridoj! kiu vin avertis forkuri de la venonta kolero?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Donu do fruktojn taŭgajn por pento. Kaj ne komencu diri en vi: Ni havas Abrahamon kiel patron; ĉar mi diras al vi, ke Dio povas el ĉi tiuj ŝtonoj starigi idojn al Abraham.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Kaj la hakilo jam kuŝas ĉe la radiko de la arboj; tial ĉiu arbo, kiu ne donas bonan frukton, estas dehakata, kaj ĵetata en fajron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'Kaj la homamasoj lin demandis, dirante: Kion do ni faru?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Kaj responde li diris al ili: Kiu havas du tunikojn, tiu donu al la nehavanto; kaj kiu havas manĝaĵon, tiu faru tiel same.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Venis ankaŭ impostistoj, por esti baptitaj, kaj ili diris al li: Majstro, kion ni faru?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'Kaj li diris al ili: Ne postulu pli multe, ol estas ordonite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Kaj ankaŭ soldatoj lin demandis, dirante: Kaj kion ni faru? Kaj li diris al ili: Ne perfortu iun, nek maljuste ion postulu, kaj estu kontentaj je via salajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'Kaj kiam la popolo atendis, kaj ĉiuj diskutis en siaj koroj pri Johano, ĉu eble li estas la Kristo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Johano respondis al ĉiuj, dirante: Mi ja vin baptas per akvo, sed venas tiu, kiu estas pli potenca ol mi; la rimenon de liaj ŝuoj mi ne estas inda malligi; li vin baptos per la Sankta Spirito kaj per fajro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'lia ventumilo estas en lia mano, por ke li elpurigu sian draŝejon, kaj kolektu la tritikon en sian grenejon; sed la grenventumaĵon li bruligos per fajro neestingebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Kaj per multaj aliaj konsiloj li evangeliis al la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Sed Herodo, la tetrarĥo, riproĉite de li pri Herodias, la edzino de lia frato, kaj pri ĉiuj malbonaĵoj, kiujn Herodo faris,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'aldonis al ĉio ankaŭ ĉi tion, ke li enŝlosis Johanon en malliberejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Kaj kiam la tuta popolo estis baptata, Jesuo ankaŭ estis baptita, kaj dum li preĝis, la ĉielo malfermiĝis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'kaj la Sankta Spirito malsupreniris sur lin en korpa aspekto kiel kolombo; kaj venis voĉo el la ĉielo: Vi estas Mia Filo, la amata; en vi Mi havas plezuron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'Kaj Jesuo mem, komencante, havis ĉirkaŭ tridek jarojn, estante filo (kiel oni supozis) de Jozef, de Eli,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'de Mattat, de Levi, de Melĥi, de Janaj, de Jozef,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'de Matatias, de Amos, de Naĥum, de Esli, de Nagaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'de Maat, de Matatias, de Semein, de Jozef, de Joda,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'de Joĥanan, de Resa, de Zerubabel, de Ŝealtiel, de Neri,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'de Melĥi, de Adi, de Kosam, de Elmodam, de Er,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'de Jesu, de Eliezer, de Jorim, de Mattat, de Levi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'de Simeon, de Jehuda, de Jozef, de Jonam, de Eljakim,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'de Melea, de Mena, de Matata, de Natan, de David,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'de Jiŝaj, de Obed, de Boaz, de Salma, de Naĥŝon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'de Aminadab, de Ram, de Ĥecron, de Perec, de Jehuda,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'de Jakob, de Isaak, de Abraham, de Teraĥ, de Naĥor,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'de Serug, de Reu, de Peleg, de Eber, de Ŝelaĥ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'de Kenan, de Arpaĥŝad, de Ŝem, de Noa, de Lemeĥ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'de Metuŝelaĥ, de Ĥanoĥ, de Jared, de Mahalalel, de Kenan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'de Enoŝ, de Set, de Adam, de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Kaj Jesuo, plena de la Sankta Spirito, revenis de Jordan, kaj estis kondukata de la Spirito en la dezerton');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'dum kvardek tagoj, tentate de la diablo. Kaj li manĝis nenion en tiuj tagoj; kaj kiam ili finiĝis, li malsatis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'Kaj la diablo diris al li: Se vi estas Filo de Dio, ordonu al ĉi tiu ŝtono, ke ĝi fariĝu pano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Kaj Jesuo respondis al li: Estas skribite: Ne per la pano sole vivos homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'Kaj kondukinte lin supren, li montris al li ĉiujn regnojn de la mondo en momento da tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'Kaj la diablo diris al li: Mi donos al vi la tutan ĉi tiun potencon kaj ilian gloron; ĉar ĝi estas transdonita al mi, kaj al kiu ajn mi volas, al tiu mi ĝin donas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Se do vi adorkliniĝos antaŭ mi, ĉio estos via.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'Kaj responde Jesuo diris al li: Estas skribite: Al la Eternulo, via Dio, adorkliniĝu, kaj al Li sola servu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Kaj li kondukis lin al Jerusalem, kaj starigis lin sur la tegmenta pinto de la templo, kaj diris al li: Se vi estas Filo de Dio, ĵetu vin de ĉi tie malsupren;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'ĉar estas skribite: Al siaj anĝeloj Li ordonos pri vi, ke ili vin gardu,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'kaj: Sur la manoj ili vin portos, Por ke vi ne falpuŝiĝu sur ŝtono per via piedo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Kaj responde Jesuo diris al li: Estas dirite: Ne provu la Eternulon, vian Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'Kaj fininte la tutan tentadon, la diablo foriris de li ĝis estonta tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Kaj revenis Jesuo en la potenco de la Spirito en Galileon; kaj eliris famo pri li tra la tuta ĉirkaŭaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'Kaj li instruadis en iliaj sinagogoj, glorate de ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'Kaj li venis al Nazaret, kie li estis edukita; kaj laŭ sia kutimo li eniris en la sinagogon en la sabata tago, kaj stariĝis, por legi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'Kaj estis donita al li libro de la profeto Jesaja. Kaj, malferminte la libron, li trovis la lokon, kie estis skribite:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, 'La spirito de la Eternulo estas sur mi, Ĉar Li min sanktoleis, por bonanonci al malriĉuloj; Li sendis min, por anonci liberecon al kaptitoj Kaj vidpovon al blinduloj, Por meti la vunditojn en liberecon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'Por proklami favorjaron de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'Kaj kunvolvinte la libron, kaj redoninte ĝin al la subulo, li sidiĝis; kaj la okuloj de ĉiuj en la sinagogo atente lin rigardis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'Kaj li ekparolis al ili: Hodiaŭ tiu skribo plenumiĝas en viaj oreloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'Kaj ĉiuj atestis pri li, kaj miris pro la vortoj de graco, kiuj eliris el lia buŝo; kaj ili diris: Ĉu ĉi tiu ne estas la filo de Jozef?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'Kaj li diris al ili: Sendube vi diros al mi la jenan sentencon: Kuracisto, sanigu vin mem; kiajn aferojn, pri kiuj ni aŭdis, en Kapernaum faritajn, tiajn faru ĉi tie en via patrujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'Kaj li diris: Vere mi diras al vi: Neniu profeto estas akceptata en sia patrujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Kun vereco mi diras al vi: Estis multaj vidvinoj en Izrael en la tagoj de Elija, kiam estis ŝlosita la ĉielo tri jarojn kaj ses monatojn, kiam okazis granda malsato sur la tuta lando;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'kaj al neniu el ili Elija estis sendita, krom al Carfat en la lando Cidon, al virino vidvino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'Kaj estis multaj lepruloj en Izrael en la tagoj de la profeto Eliŝa; sed neniu el ili estis purigita, krom Naaman, la Siriano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'Kaj ĉiuj en la sinagogo pleniĝis de kolero, aŭdante tion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'kaj leviĝinte, ili elĵetis lin ekster la urbon, kaj kondukis lin ĝis la krutaĵo de la monteto, sur kiu ilia urbo estis konstruita, por ĵeti lin malsupren.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Sed li foriris, trapasinte tra ilia mezo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'Kaj li malsupreniris al Kapernaum, urbo Galilea. Kaj li instruis ilin en la sabato;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'kaj oni miris pro lia instruado, ĉar kun aŭtoritato estis lia vorto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'Kaj en la sinagogo estis viro, havanta spiriton de malpura demono; kaj li kriegis per laŭta voĉo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, 'dirante: Ha! kio estas inter ni kaj vi, Jesuo Nazaretano? Ĉu vi venis, por pereigi nin? Mi scias, kiu vi estas, la Sanktulo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'Kaj Jesuo severe admonis lin, dirante: Silentu, kaj eliru el li. Kaj ĵetinte lin en la mezon, la demono eliris el li, neniel difektinte lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'Kaj falis miro sur ĉiujn, kaj ili kunparoladis inter si, dirante: Kia vorto estas ĉi tio? ĉar kun aŭtoritato kaj potenco li ordonas al la malpuraj spiritoj, kaj ili eliras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'Kaj famo pri li eliris al ĉiu loko de la tuta ĉirkaŭaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Kaj leviĝinte el la sinagogo, li eniris en la domon de Simon. Kaj la bopatrino de Simon estis tenata de granda febro, kaj ili petis lin pri ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Kaj starante super ŝi, li admonis la febron; kaj ĝi forlasis ŝin, kaj ŝi tuj leviĝis kaj servis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Kaj ĉe la subiro de la suno ĉiuj, kiuj havis malsanulojn kun diversaj malsanoj, venigis ilin al li; kaj li metis sur ĉiun el ili la manojn, kaj sanigis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Eliris ankaŭ demonoj el multaj, kriegante, kaj dirante: Vi estas la Filo de Dio. Kaj severe admonante, li ne permesis al ili paroli, ĉar ili sciis, ke li estas la Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'Kaj kiam tagiĝis, li eliris, kaj venis en dezertan lokon; kaj la homamasoj lin serĉis, kaj venis al li, kaj lin detenis, ke li ne foriru de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Sed li diris al ili: Ankaŭ al la ceteraj urboj mi devas prediki la evangelion de la regno de Dio; ĉar por tio mi estas sendita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'Kaj li predikis en la sinagogoj de Galileo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Kaj dum la homamaso ĉirkaŭpremis lin kaj aŭskultis la vorton de Dio, li staris apud la lago Genesaret;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'kaj li vidis du ŝipetojn starantajn apud la lago, sed la fiŝkaptistoj ĵus eliris el ili, kaj lavis la retojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'Kaj li eniris en unu el la ŝipetoj, kiu apartenis al Simon, kaj petis, ke li forŝovu iom for de la bordo. Kaj li sidiĝis, kaj instruis la homamason el la ŝipeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Kaj kiam li ĉesis paroli, li diris al Simon: Forŝovu ĝis la profundo, kaj mallevu la retojn por akirado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'Kaj responde Simon diris: Estro, ni jam laboris la tutan nokton kaj kaptis nenion; tamen laŭ via diro mi mallevos la retojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'Kaj tion farinte, ili enfermis grandan amason da fiŝoj, kaj iliaj retoj ekrompiĝis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'kaj ili geste signis al siaj kompanianoj en la alia ŝipeto, ke ili venu kaj helpu ilin. Kaj ili venis, kaj plenigis ambaŭ ŝipetojn, ĝis ekprofundiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Sed Simon Petro, tion vidinte, falis teren antaŭ la genuoj de Jesuo, dirante: Foriru de mi, ho Sinjoro, ĉar mi estas pekulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Ĉar pro la preno de fiŝoj, kiun ili akiris, miro kaptis lin, kaj ĉiujn, kiuj estis kun li,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'kaj tiel same Jakobon kaj Johanon, filojn de Zebedeo, kiuj estis kompanianoj de Simon. Kaj Jesuo diris al Simon: Ne timu; de nun vi estos kaptisto de homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'Kaj kiam ili surbordigis siajn ŝipetojn, ili forlasis ĉion, kaj sekvis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'Kaj dum li estis en unu el la urboj, jen viro plena de lepro; kaj vidante Jesuon, li falis sur la vizaĝon kaj petegis lin, dirante: Sinjoro, se vi volas, vi povas min purigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Kaj li etendis la manon kaj tuŝis lin, dirante: Mi volas; estu purigita. Kaj tuj la lepro foriris de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'Kaj li ordonis al li, ke li diru al neniu: Sed foririnte, montru vin al la pastro kaj tiele oferu pro via purigado, kiel ordonis Moseo, por atesto al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Sed la famo pri li des pli multe disvastiĝis; kaj grandaj homamasoj kunvenis, por aŭskulti kaj por esti sanigitaj je siaj malsanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'Sed li fortiris sin en la dezertojn, kaj preĝadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'Kaj en unu el tiuj tagoj li estis instruanta; kaj ĉeestis Fariseoj kaj leĝinstruistoj, sidantaj, kiuj alvenis el ĉiu vilaĝo de Galileo kaj el Judujo kaj el Jerusalem; kaj la potenco de la Eternulo alestis, por sanigi ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'Kaj jen viroj alportis sur lito viron, kiu estis paralizita; kaj ili penis enporti lin kaj meti lin antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Kaj ne trovinte, kiamaniere ili povas enporti lin, pro la homamaso, ili supreniris sur la tegmenton, kaj mallevis lin tra la tegoloj, kun la liteto, en la mezon antaŭ Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Kaj vidante ilian fidon, li diris: Ho viro, viaj pekoj estas al vi pardonitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Kaj la skribistoj kaj Fariseoj komencis diskuti inter si, dirante: Kiu estas ĉi tiu, kiu parolas blasfemojn? kiu povas pardoni pekojn krom Dio sola?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Sed Jesuo, eksciante iliajn pensojn, responde diris al ili: Kial vi diskutas en viaj koroj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Kio estas pli facila, diri: Viaj pekoj estas al vi pardonitaj, aŭ diri: Leviĝu kaj piediru?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Sed por ke vi sciu, ke la Filo de homo havas aŭtoritaton sur la tero pardoni pekojn-li diris al la paralizulo: Mi diras al vi: Leviĝu, kaj prenu vian liteton, kaj iru al via domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'Kaj tuj li leviĝis antaŭ ili, kaj prenis tion, sur kio li kuŝis, kaj iris al sia domo, glorante Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'Kaj mirego kaptis ĉiujn, kaj li gloris Dion; kaj ili pleniĝis de timo, dirante: Ni vidis mirindaĵojn hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Kaj post tio li eliris, kaj vidis impostiston, nomatan Levi, sidantan ĉe la impostejo, kaj diris al li: Sekvu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'Kaj li forlasis ĉion, kaj leviĝis, kaj sekvis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'Kaj Levi faris grandan festenon por li en sia domo, kaj estis granda amaso da impostistoj kaj aliaj, kiuj sidis ĉe manĝo kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'Kaj la Fariseoj kaj iliaj skribistoj murmuris kontraŭ liaj disĉiploj, dirante: Kial vi manĝas kaj trinkas kun impostistoj kaj pekuloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'Kaj Jesuo responde diris al ili: Ne la sanuloj bezonas kuraciston, sed la malsanuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Mi venis, por alvoki ne justulojn, sed pekulojn al pento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'Kaj ili diris al li: La disĉiploj de Johano ofte fastas kaj faras preĝojn, kaj tiel same ankaŭ la disĉiploj de la Fariseoj; sed la viaj manĝas kaj trinkas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Kaj Jesuo diris al ili: Ĉu vi povas igi la filojn de la edziĝejo fasti, dum la fianĉo estas kun ili?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Sed venos tagoj; kaj kiam la fianĉo estos prenita for de ili, tiam ili fastos en tiuj tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Kaj li ankaŭ parolis al ili parabolon: Neniu ŝiras pecon el nova vesto kaj alkudras ĝin sur malnovan veston; ĉar alie li ŝirus la novan, kaj ankaŭ la flikaĵo el la nova ne harmonius kun la malnova.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'Kaj neniu enverŝas novan vinon en malnovajn felsakojn; ĉar alie la nova vino krevigus la felsakojn, kaj ĝi mem elfluus, kaj la felsakoj detruiĝus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'Sed novan vinon oni devas enverŝi en novajn felsakojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'Kaj neniu, trinkinte malnovan vinon, deziras novan; ĉar li diras: La malnova estas preferinda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'Kaj en sabato li iris tra la grenkampoj, kaj liaj disĉiploj deŝiris la spikojn, kaj manĝis, frotante ilin en la manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Sed iuj el la Fariseoj diris: Kial vi faras tion, kion fari en sabato ne estas permesate?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'Kaj Jesuo, respondante al ili, diris: Ĉu vi eĉ ne legis, kion faris David, kiam malsatis li kaj liaj kunuloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'ke li eniris en la domon de Dio, kaj prenis kaj manĝis kaj donis ankaŭ al siaj kunuloj la panojn de propono, kiujn manĝi ne estas permesate, krom nur al la pastroj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'Kaj li diris al ili: La Filo de homo estas sinjoro de la sabato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'Kaj en alia sabato li eniris en la sinagogon kaj instruadis; kaj tie estis viro, kies dekstra mano estis velkinta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'Kaj la skribistoj kaj Fariseoj observis lin atente, ĉu li sanigos en la sabato, por ke ili trovu, kiel lin akuzi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Sed li sciis iliajn pensojn, kaj li diris al la viro, kiu havis la manon velkintan: Leviĝu, kaj stariĝu en la mezo. Kaj li leviĝis kaj stariĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Kaj Jesuo diris al ili: Mi vin demandas: ĉu estas permesate bonfari en sabato, aŭ malbonfari? Savi vivon, al ĝin pereigi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'Kaj ĉirkaŭrigardinte ĉiujn, li diris al li: Etendu vian manon. Kaj li tion faris, kaj lia mano resaniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Sed ili pleniĝis de frenezo, kaj interparoladis inter si, kion ili faru al Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'Kaj en tiuj tagoj li foriris sur la monton, por preĝi; kaj li pasigis la tutan nokton en preĝado al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'Kaj kiam tagiĝis, li alvokis siajn disĉiplojn, kaj elektis el ili dek du, kiujn li ankaŭ nomis apostoloj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Simonon, kiun li ankaŭ nomis Petro, kaj Andreon, lian fraton, kaj Jakobon kaj Johanon kaj Filipon kaj Bartolomeon');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'kaj Mateon kaj Tomason, kaj Jakobon, filon de Alfeo, kaj Simonon, nomatan Fervorulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'kaj Judason de Jakobo, kaj Judason Iskariotan, kiu fariĝis perfidulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'Kaj li malsupreniris kun ili, kaj staris sur ebena loko, kaj granda amaso de liaj disĉiploj, kaj granda nombro de la popolo el la tuta Judujo kaj Jerusalem, kaj el la marbordo de Tiro kaj Cidon, kiuj alvenis, por aŭskulti lin kaj saniĝi je siaj malsanoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'kaj tiuj, kiuj estis turmentataj de malpuraj spiritoj, estis sanigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'Kaj la tuta homamaso volis tuŝi lin, ĉar potenco eliris el li kaj sanigis ĉiujn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'Kaj li levis siajn okulojn al siaj disĉiploj, kaj diris: Feliĉaj estas vi malriĉuloj, ĉar via estas la regno de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Feliĉaj estas vi, kiuj nun malsatas, ĉar vi satiĝos. Feliĉaj estas vi, kiuj nun ploras, ĉar vi ridos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Feliĉaj vi estas, kiam oni vin malamos kaj vin izolos kaj vin riproĉos, kaj elĵetos vian nomon kial malbonan, pro la Filo de homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Ĝoju en tiu tago, kaj pro ĝojo saltu, ĉar jen via rekompenco estas granda en la ĉielo; ĉar tiel same faris iliaj patroj kontraŭ la profetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Sed ve al vi riĉuloj! ĉar vi jam ricevis vian konsolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Ve al vi satigitaj! ĉar vi malsatos. Ve al vi, kiuj nun ridas! ĉar vi malĝojos kaj ploros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Ve, kiam ĉiuj homoj parolos bone pri vi! ĉar tiel same faris iliaj patroj al la falsaj profetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Sed mi diras al vi, kiuj aŭdas: Amu viajn malamikojn, faru bonon al viaj malamantoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'benu tiujn, kiuj vin malbenas; preĝu por tiuj, kiuj kun insulto vin atakas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'Al tiu, kiu frapas vin sur la vango, prezentu ankaŭ la alian; kaj de tiu, kiu prenas vian mantelon, ne detenu vian tunikon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Donu al ĉiu, kiu petas de vi; kaj de tiu, kiu forprenas viajn posedaĵojn, ne repostulu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'Kaj kiel vi volas, ke la homoj faru al vi, faru ankaŭ al ili tiel same.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Kaj se vi amas tiujn, kiuj amas vin, kian dankon vi havas? ĉar eĉ la pekuloj amas tiujn, kiuj ilin amas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'Kaj se vi bonfaras al viaj bonfarantoj, kian dankon vi havas? ĉar eĉ la pekuloj tiel same faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'Kaj se vi pruntas al tiuj, de kiuj vi esperas ricevi, kian dankon vi havas? eĉ pekuloj pruntas al pekuloj, por egale rericevi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Sed amu viajn malamikojn, kaj bonfaru, kaj pruntedonu, pri neniu perdante esperon; kaj via rekompenco estos granda, kaj vi estos filoj de la Plejalta; ĉar Li estas bona al la nedankemuloj kaj malbonuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Estu kompatemaj, kiel via Patro estas kompatema.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Kaj ne juĝu, kaj vi ne estos juĝitaj; kaj ne kondamnu, kaj vi ne estos kondamnitaj; liberigu, kaj vi estos liberigitaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'donu, kaj estos donite al vi; bonan mezuron, premitan, kunskuitan, superfluantan, oni donos en vian sinon. Ĉar per kia mezuro vi mezuras, per tia oni remezuros al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Kaj li parolis ankaŭ al ili parabolon: Ĉu blindulo povas gvidi blindulon? ĉu ne falos ambaŭ en fosaĵon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Disĉiplo ne estas super sia instruisto; sed perfektigite, ĉiu estos kiel lia instruisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Kaj kial vi rigardas la lignereton, kiu estas en la okulo de via frato, kaj ne pripensas la trabon, kiu estas en via propra okulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Kiel vi povas diri al via frato: Frato, lasu min eltiri la lignereton, kiu estas en via okulo; dum vi ne pripensas la trabon en via propra okulo? Hipokritulo! eltiru unue la trabon el via okulo, kaj tiam vi klare vidos, por eltiri la lignereton, kiu estas en la okulo de via frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Ĉar ne ekzistas bona arbo, kiu donas putran frukton; nek putra arbo, kiu donas bonan frukton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'Ĉar ĉiu arbo estas konata per sia propra frukto. Ĉar el dornarbetoj oni ne kolektas figojn, nek el rubusujo oni rikoltas vinberojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'Bona homo el la bona trezorejo de sia koro liveras bonon, kaj malbona homo el la malbona trezorejo liveras malbonon; ĉar el la abundo de la koro parolas lia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'Kaj kial vi min vokas: Sinjoro, Sinjoro; kaj ne faras tion, kion mi diras?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Pri ĉiu, kiu venas al mi, kaj aŭdas miajn parolojn, kaj plenumas ilin, mi montros al vi, al kiu li similas:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'li similas al viro, kiu, konstruante domon, fosis kaj profunde kavigis, kaj metis fundamenton sur la roko; kaj kiam okazis inundo, la rivero sin ĵetis kontraŭ tiun domon, kaj ne povis ĝin ŝanceli; ĉar ĝi estis bone konstruita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Sed tiu, kiu aŭdas kaj ne plenumas, similas al viro, kiu konstruis sur la tero sen fundamento domon; kontraŭ kiun la rivero sin ĵetis, kaj ĝi tuj enfalis, kaj la ruino de tiu domo estis granda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Fininte ĉiujn siajn dirojn en la oreloj de la popolo, li eniris en Kapernaumon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Kaj sklavo de unu centestro, kiu estis kara por li, estis malsana kaj preskaŭ mortanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Kaj aŭdinte pri Jesuo, tiu sendis al li pliaĝulojn de la Judoj, por peti, ke li venu, por savi lian sklavon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Kaj veninte al Jesuo, ili insiste petegis, dirante: Li estas inda, ke vi faru al li tiun komplezon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'ĉar li amas nian nacion, kaj li mem konstruigis por ni la sinagogon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Kaj Jesuo ekiris kun ili. Kaj kiam li estis ne malproksime de la domo, la centestro sendis al li amikojn, por diri al li: Sinjoro, ne ĝenu vin; ĉar mi ne estas inda, ke vi venu sub mian tegmenton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'pro tio mi ne opiniis min inda veni al vi. Sed vorton parolu, kaj mia knabo saniĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Ĉar mi ankaŭ estas homo metita sub aŭtoritato, havante sub mi soldatojn; kaj mi diras al ĉi tiu: Iru; kaj li iras; kaj al alia: Venu; kaj li venas; kaj al mia sklavo: Faru ĉi tion; kaj li ĝin faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Kaj kiam Jesuo tion aŭdis, li miris pri li, kaj sin turninte, diris al la homamaso, lin sekvanta: Mi diras al vi: Eĉ en Izrael mi ne trovis tiom da fido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'Kaj la senditoj, reveninte al la domo, trovis la sklavon sana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'Kaj post nelonge li iris al urbo nomata Nain, kaj akompanis lin liaj disĉiploj kaj granda homamaso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Kaj kiam li alproksimiĝis al la pordego de la urbo, jen oni elportis mortinton, la solan filon de lia patrino, kaj ŝi estis vidvino; kaj granda homamaso el la urbo estis kun ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Kaj kiam la Sinjoro ŝin vidis, li kortuŝiĝis pri ŝi, kaj diris al ŝi: Ne ploru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'Kaj li alproksimiĝis, kaj tuŝis la portilon, kaj la portantoj haltis. Kaj li diris: Junulo, mi diras al vi: Leviĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'Kaj la mortinto side leviĝis kaj komencis paroli. Kaj li donis lin al lia patrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Kaj timo kaptis ĉiujn; kaj ili gloris Dion, dirante: Granda profeto leviĝis inter ni; kaj: Dio vizitis Sian popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'Kaj ĉi tiu famo pri li eliris tra la tuta Judujo, kaj tra la tuta ĉirkaŭaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'Kaj la disĉiploj de Johano sciigis lin pri ĉio tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'Kaj Johano, alvokinte al si du el siaj disĉiploj, sendis ilin al la Sinjoro, por diri: Ĉu vi estas la venonto, aŭ ĉu ni atendu alian?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Kaj kiam la viroj alvenis al li, ili diris: Johano, la Baptisto, sendis nin al vi, por diri: Ĉu vi estas la venonto, aŭ ĉu ni atendu alian?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'En tiu horo li sanigis multajn je malsanoj kaj pestoj kaj malbonaj spiritoj; kaj al multaj blinduloj li redonis vidpovon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'Kaj li respondis kaj diris al ili: Iru kaj sciigu Johanon pri tio, kion vi vidis kaj aŭdis: blinduloj vidas, lamuloj marŝas, lepruloj estas purigitaj, kaj surduloj aŭdas, mortintoj leviĝas, al malriĉuloj evangelio estas predikata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'Kaj feliĉa estas ĉiu, kiu ne falpuŝiĝas pro mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'Kaj kiam la senditoj de Johano foriris, li komencis paroli al la homamasoj pri Johano: Kion vi eliris en la dezerton, por rigardi? ĉu junkon skuatan de la vento?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Sed kion vi eliris, por vidi? ĉu homon per mola vestaro vestitan? Jen tiuj, kiuj portas luksan vestaron kaj delikate vivadas, troviĝas en domoj de reĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Sed kion vi eliris, por vidi? ĉu profeton? Jes, mi diras al vi, kaj multe pli ol profeton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'Ĉar li estas tiu, pri kiu estas skribite: Jen Mi sendos Mian anĝelon antaŭ via vizaĝo, Kaj li preparos antaŭ vi vian vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Mi diras al vi: Inter naskitoj de virinoj estas neniu pli granda ol Johano; tamen tiu, kiu estas nur malgranda en la regno de Dio, estas pli granda ol li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'Kaj la tuta popolo kaj la impostistoj, aŭdinte, pravigis Dion, ĉar ili ricevis la bapton de Johano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'Sed la Fariseoj kaj la leĝistoj rifuzis por si la intencon de Dio, ĉar ili ne estis baptitaj de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'Al kio do mi komparos la homojn de ĉi tiu generacio? kaj al kio ili similas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Ili similas al infanoj, kiuj sidas sur la placo kaj vokas unu al alia, dirante: Ni flutis al vi, kaj vi ne dancis; ni lamentis, kaj vi ne ploris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Ĉar Johano, la Baptisto, venis, nek manĝante panon nek trinkante vinon; kaj vi diras: Li havas demonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'La Filo de homo venis, manĝante kaj trinkante; kaj vi diras: Jen manĝegulo kaj vindrinkulo, amiko de impostistoj kaj pekuloj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Kaj la saĝeco estas pravigita de ĉiuj siaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Kaj unu el la Fariseoj petis lin, ke li manĝu kun li. Kaj li eniris en la domon de la Fariseo, kaj sidiĝis ĉe manĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'Kaj jen estis en la urbo virino pekulino; kaj kiam ŝi eksciis, ke Jesuo sidas ĉe manĝo en la domo de la Fariseo, ŝi alportis alabastran vazon da ŝmiraĵo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'kaj starante malantaŭe ĉe liaj piedoj, plorante, ŝi komencis priverŝi liajn piedojn per siaj larmoj, kaj viŝis ilin per la haroj de sia kapo, kaj kisadis liajn piedojn, kaj ŝmiris ilin per la ŝmiraĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Kaj kiam la Fariseo, kiu lin invitis, tion vidis, li parolis en si, dirante: Ĉi tiu, se li estus profeto, ja scius, kiu kaj kia virino lin tuŝas, ke ŝi estas pekulino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'Kaj responde Jesuo diris al li: Simon, mi havas ion diri al vi. Kaj li diris: Majstro, parolu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, 'Unu pruntedoninto havis du ŝuldantojn; unu ŝuldis kvincent denarojn, kaj la alia kvindek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'Kiam ili havis nenion, per kio pagi, li pardonis al ambaŭ la ŝuldon. Kiu el ili do lin pli amos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Simon responde diris: Tiu, mi supozas, al kiu li pardonis la pli grandan ŝuldon. Kaj li diris al li: Vi prave juĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'Kaj sin turnante al la virino, li diris al Simon: Ĉu vi vidas ĉi tiun virinon? Mi eniris en vian domon, vi ne donis al mi akvon por la piedoj; sed ŝi priverŝis miajn piedojn per siaj larmoj kaj viŝis ilin per siaj haroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Vi ne donis al mi kison; sed ŝi, de la tempo, kiam mi eniris, ne ĉesis kisadi miajn piedojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Vi ne ŝmiris mian kapon per oleo; sed ŝi ŝmiris miajn piedojn per ŝmiraĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Pro tio mi diras al vi: Ŝiaj pekoj, kiuj estas multaj, estas pardonitaj; ĉar ŝi multe amis; sed al kiu malmulto estas pardonita, tiu malmulte amas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Kaj li diris al ŝi: Viaj pekoj estas pardonitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'Kaj tiuj, kiuj sidis ĉe manĝo kun li, komencis diri inter si: Kiu estas ĉi tiu, kiu eĉ pardonas pekojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'Kaj li diris al la virino: Via fido vin savis; iru en pacon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'Kaj post ne longe li vojiradis tra urboj kaj vilaĝoj, predikante kaj alportante la evangelion de la regno de Dio, kaj kun li la dek du,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'kaj iuj virinoj, kiuj estis resanigitaj je malbonaj spiritoj kaj malsanoj: Maria, kiu estis nomata Magdalena, el kiu eliris sep demonoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'kaj Joana, edzino de Ĥuzas, la ĉambelano de Herodo, kaj Susana, kaj multaj aliaj, kiuj faris al ili helpan servadon per sia havo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Kaj kiam granda homamaso kolektiĝis, kaj homoj el ĉiu urbo venis al li, li diris per parabolo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, 'La semisto eliris, por semi sian semon; kaj dum li semis, iuj semoj falis apud la vojo kaj estis piedpremitaj, kaj la birdoj de la ĉielo formanĝis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'Kaj aliaj falis sur ŝtonan lokon, kaj kreskinte, velkis, ĉar ili ne havis malsekaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Kaj aliaj falis meze inter dornojn; kaj la dornoj kunkreskis, kaj sufokis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'Kaj aliaj falis en la bonan teron, kaj kreskinte, produktis frukton centoble. Dirinte tion, li kriis: Kiu havas orelojn por aŭdi, tiu aŭdu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'Kaj liaj disĉiploj demandis al li, kia estas ĉi tiu parabolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'Kaj li diris: Al vi estas donite scii la misterojn de la regno de Dio; sed al la aliaj per paraboloj, por ke, vidante, ili ne rimarku, kaj aŭdante, ili ne komprenu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'La parabolo estas jena: La semo estas la vorto de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'Kaj la falintaj apud la vojo estas tiuj, kiuj aŭdis; tiam venas la diablo, kaj forprenas la vorton el ilia koro, por ke ili ne kredu kaj ne estu savitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'Kaj la falintaj sur la ŝtonan lokon estas tiuj, kiuj, aŭdinte, kun ĝojo akceptas la vorton; sed ili ne havas radikon, kaj kredas nur portempe, kaj en tempo de tento ili defalas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'Kaj tio, kio falis inter dornojn, estas tiuj, kiuj aŭdis, kaj dum sia irado sufokiĝas per zorgoj kaj riĉo kaj plezuroj de la vivo, kaj ne perfektigas frukton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Kaj tio, kio falis en la bonan teron, estas tiuj, kiuj en bela kaj bona koro, aŭdinte la vorton, konservas ĝin, kaj kun pacienco donas frukton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'Kaj ekbruliginte lampon, oni ne kovras ĝin per vazo, aŭ forŝovas ĝin sub liton; sed metas ĝin sur lampingon, por ke la enirantoj povu vidi la lumon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Ĉar estas kaŝita nenio, kio ne malkaŝiĝos; kaj ne estas io sekreta, kio ne koniĝos kaj klare elmontriĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Atentu do, kiamaniere vi aŭdas; ĉar kiu ajn havas, al tiu estos donite; kaj kiu ajn ne havas, de tiu estos forprenita eĉ tio, kion li ŝajne havas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Kaj alvenis al li lia patrino kaj liaj fratoj, kaj ili ne povis lin atingi pro la homamaso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'Kaj oni sciigis lin: Via patrino kaj viaj fratoj staras ekstere, kaj deziras vin vidi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'Sed respondante, li diris al ili: Mia patrino kaj miaj fratoj estas tiuj, kiuj aŭdas la vorton de Dio, kaj ĝin plenumas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Kaj en unu el tiuj tagoj eniris en ŝipeton li kaj liaj disĉiploj; kaj li diris al ili: Ni transiru al la alia bordo de la lago; kaj ili surmariĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'Sed dum ili veturis, li endormiĝis; kaj falis ventego sur la lagon; kaj ili tute pleniĝis de akvo, kaj estis en danĝero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'Kaj ili venis al li, kaj vekis lin, dirante: Estro, estro, ni pereas. Kaj li leviĝis, kaj admonis la venton kaj la furiozon de la akvo; kaj ili ĉesiĝis, kaj fariĝis sereno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Kaj li diris al ili: Kie estas via fido? Kaj ili timis kaj miris, dirante unu al la alia: Kiu do estas ĉi tiu? ĉar li ordonas eĉ al la ventoj kaj al la akvo, kaj ili obeas al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'Kaj ili ŝipveturis al la lando de la Gerasenoj, kiu estas kontraŭ Galileo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'Kaj kiam li surbordiĝis, renkontis lin el la urbo viro, havanta demonojn; kaj jam de longe li ne portis vestojn, kaj loĝis ne en domo, sed en la tomboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Kaj vidinte Jesuon, li ekkriis kaj falis antaŭ li, kaj laŭtvoĉe diris: Kio estas inter mi kaj vi, ho Jesuo, Filo de Dio Plejalta? mi petas vin, ne turmento min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Ĉar li ordonis al la malpura spirito eliri el la homo. Ĉar ĝi ofte kaptis lin, kaj li estis sub gardantaro, kaj ligita per ĉenoj kaj katenoj; kaj disrompinte la ligilojn, li estis peladata de la demono en la dezertojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'Kaj Jesuo demandis lin: Kia estas via nomo? Kaj li diris: Legio; ĉar multaj demonoj eniris en lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'Kaj ili petegis lin, ke li ne ordonu al ili foriri en la abismon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Kaj estis tie granda grego da porkoj, paŝtiĝantaj sur la monto; kaj ili petegis lin, ke li permesu al ili eniri en la porkojn. Kaj li tion permesis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'Kaj elirinte el la viro, la demonoj eniris en la porkojn; kaj la grego kuris de la krutaĵo en la lagon, kaj sufokiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'Kaj kiam iliaj paŝtistoj vidis la okazintaĵon, ili forkuris, kaj rakontis ĝin en la urbo kaj en la kamparo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'Kaj oni eliris por vidi, kio okazis; kaj ili venis al Jesuo, kaj trovis la viron, el kiu eliris la demonoj, sidanta, vestita kaj en sana prudento, ĉe la piedoj de Jesuo, kaj ili timis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Kaj la vidintoj rakontis al ili, kiamaniere la demonhavinto saniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'Kaj la tuta homamaso, el la ĉirkaŭaĵo de la Gerasenoj, petis lin foriri de ili; ĉar ili estis tenataj de granda timo; kaj li eniris en ŝipeton kaj returne veturis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Sed la viro, el kiu eliris la demonoj, petis lin, ke li povu esti kun li; sed li forsendis lin, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, 'Reiru al via domo, kaj rakontu ĉion, kion Dio faris por vi. Kaj li foriris, famigante tra la tuta urbo ĉion, kion Jesuo faris por li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'Kaj kiam Jesuo revenis, la homamaso bonvenigis lin, ĉar ĉiuj atendis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'Kaj jen venis viro, nomata Jairos, kaj li estis sinagogestro; kaj li sin ĵetis antaŭ la piedojn de Jesuo, kaj petegis lin, ke li venu en lian domon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'ĉar li havis unu solan filinon, proksimume dekdujaran, kaj ŝi estis mortanta. Kaj dum li iris, la homamaso ĉirkaŭpremis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'Kaj virino, kiu jam dek du jarojn havis sangofluon, kaj elspezis sian tutan havon por kuracistoj, kaj ne povis esti resanigita de iu,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'venis malantaŭ lin, kaj tuŝis la randon de lia vestaĵo; kaj tuj ŝia sangofluo ĉesiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'Kaj Jesuo diris: Kiu min tuŝis? Kaj kiam ĉiuj neis, Petro diris: Estro, la homamaso ĉirkaŭas kaj premas vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Sed Jesuo diris: Iu min tuŝis; ĉar mi sentis, ke de mi eliris potenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'Kaj kiam la virino ekvidis, ke ŝi ne estas kaŝita, ŝi venis tremanta, kaj, sin ĵetante antaŭ lin, sciigis antaŭ la tuta popolo, pro kia motivo ŝi tuŝis lin, kaj kiel ŝi estas tuj sanigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'Kaj li diris al ŝi: Filino, via fido vin savis; iru en pacon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Dum li ankoraŭ parolis, jen iu venis de la domo de la sinagogestro, dirante: Via filino jam mortis; ne ĝenu la instruiston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Sed Jesuo, aŭdinte tion, respondis al li: Ne timu; nur kredu, kaj ŝi estos savita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Kaj kiam li venis al la domo, li permesis al neniu eniri kun li, krom Petro kaj Johano kaj Jakobo kaj la patro kaj la patrino de la knabino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Kaj ĉiuj ploris kaj ĝemis pro ŝi; sed li diris: Ne ploru; ĉar ŝi ne mortis, sed dormas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'Kaj ili mokridis lin, sciante, ke ŝi mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'Sed li, preninte ŝian manon, vokis ŝin, dirante: Knabino, leviĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'Kaj ŝia spirito revenis, kaj ŝi tuj stariĝis; kaj li ordonis, ke oni donu al ŝi manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'Kaj ŝiaj gepatroj estis mirigitaj; sed li ordonis, ke ili diru al neniu tion, kio estis farita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Kaj li kunvokis la dek du, kaj donis al ili potencon kaj aŭtoritaton super ĉiuj demonoj, kaj por forigi malsanojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'Kaj li forsendis ilin, por prediki la regnon de Dio, kaj por sanigi la malsanulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'Kaj li diris al ili: Portu nenion por la vojo-nek bastonon, nek saketon, nek panon, nek monon; kaj ne havu du tunikojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'Kaj en kiun ajn domon vi eniros, tie loĝu, kaj el tie ekvojaĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Kaj se ie oni vin ne akceptos, tiam, forirante el tiu urbo, deskuu la polvon de viaj piedoj, por atesto kontraŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'Kaj ili, foririnte, trairis la vilaĝojn, ĉie predikante la evangelion kaj sanigante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Kaj la tetrarĥo Herodo aŭdis pri ĉio, kio fariĝis; kaj li embarasiĝis, ĉar iuj diris, ke Johano leviĝis el la mortintoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'kaj aliaj, ke Elija aperis; kaj aliaj, ke unu el la antikvaj profetoj releviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'Kaj Herodo diris: Johanon mi senkapigis, sed kiu estas ĉi tiu, pri kiu mi aŭdas tiajn aferojn? Kaj li deziris vidi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Kaj la apostoloj, reveninte, rakontis al li ĉion, kion ili faris. Kaj li kondukis ilin, kaj foriris aparte al urbo, nomata Betsaida.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Sed la homamaso, eksciinte tion, sekvis lin; kaj li akceptis ilin, kaj parolis al ili pri la regno de Dio, kaj tiujn, kiuj bezonis kuracon, li resanigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'Kaj ekvesperiĝis; kaj la dek du, alveninte, diris al li: Forsendu la homamason, por ke ili iru en la ĉirkaŭajn vilaĝojn kaj kampojn, por trovi ripozejojn kaj nutraĵon; ĉar ĉi tie ni estas en dezerta loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Sed li diris al ili: Vi donu al ili manĝi. Kaj ili diris: Ni havas ne pli ol kvin panojn kaj du fiŝojn, se ni ne irus kaj aĉetus manĝaĵon por ĉi tiu tuta homomulto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'Ĉar ĉeestis proksimume kvin mil viroj. Kaj li diris al siaj disĉiploj: Sidigu ilin en aroj, po proksimume kvindek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'Kaj tion ili faris, kaj sidigis ĉiujn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Kaj li prenis la kvin panojn kaj la du fiŝojn, kaj suprenrigardinte al la ĉielo, li ilin benis kaj dispecigis, kaj donis al la disĉiploj, por meti antaŭ la homamason.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'Kaj ili manĝis, kaj ĉiuj satiĝis; kaj oni kolektis da postrestintaj fragmentoj dek du korbojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'Kaj dum li preĝis en soleco, la disĉiploj estis kun li; kaj li demandis ilin, dirante: Kiu, diras la popolo, ke mi estas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'Kaj ili responde diris: Laŭ iuj Johano, la Baptisto; sed laŭ aliaj: Elija; kaj laŭ aliaj, ke unu el la antikvaj profetoj releviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'Sed li diris al ili: Sed vi-kiu vi diras, ke mi estas? Kaj Petro responde diris: La Kristo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Sed li per severa ordono admonis, ke ili diru ĉi tion al neniu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'dirante: La Filo de homo devas multe suferi, kaj esti rifuzita de la pliaĝuloj kaj ĉefpastroj kaj skribistoj, kaj esti mortigita, kaj la trian tagon releviĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Kaj li diris al ĉiuj: Se iu volas veni post mi, li abnegaciu sin, kaj levu sian krucon ĉiutage, kaj sekvu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Ĉar kiu volos savi sian animon, tiu ĝin perdos; sed kiu perdos sian animon pro mi, tiu ĝin savos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Ĉar kiel profitus homo, se li gajnus la tutan mondon kaj sin perdus aŭ pereigus?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Ĉar kiu hontos pri mi kaj pri miaj paroloj, pri tiu hontos la Filo de homo, kiam li venos en sia gloro, kaj la gloro de la Patro kaj de la sanktaj anĝeloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Sed mi diras al vi certe: Inter la ĉi tie starantaj estas iuj, kiuj neniel gustumos morton, antaŭ ol ili vidos la regnon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'Kaj pasis post tiuj diroj ĉirkaŭ ok tagoj, kaj li prenis kun si Petron kaj Johanon kaj Jakobon, kaj supreniris sur la monton, por preĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'Kaj dum li preĝis, la aspekto de lia vizaĝo aliiĝis, kaj lia vestaro fariĝis blanka kaj fulme brilanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'Kaj jen interparolis kun li du viroj, kiuj estis Moseo kaj Elija,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'kiuj montriĝis en gloro, kaj parolis pri lia foriro, kiun li estis plenumonta en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Sed Petro, kaj tiuj, kiuj estis kun li, estis subpremataj de dormo; sed vekiĝinte, ili vidis lian gloron, kaj la du virojn, kiuj staris kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'Kaj dum ili foriris de li, Petro diris al Jesuo: Estro, estas bone por ni esti ĉi tie; kaj ni faru tri laŭbojn: unu por vi, kaj unu por Moseo, kaj unu por Elija; li ne sciis, kion li diras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Kaj dum li tion diris, nubo venis kaj superombris ilin; kaj ili timis, kiam ili eniris en la nubon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'Kaj el la nubo venis voĉo, diranta: Ĉi tiu estas Mia Filo, Mia elektito; lin aŭskultu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'Kaj dum la voĉo ankoraŭ sonis, Jesuo troviĝis sola. Kaj ili silentis, kaj al neniu en tiuj tagoj rakontis ion, kion ili vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'Kaj la sekvantan tagon, post kiam ili malsupreniris de la monto, granda homamaso renkontis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'Kaj jen unu viro el la homamaso ekkriis, dirante: Majstro, mi petegas vin rigardi mian filon, ĉar li estas mia sola infano;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'kaj jen spirito kaptas lin, kaj subite li ekkrias, kaj ĝi konvulsiigas lin kun buŝa ŝaŭmo, kaj malfacile lasas lin, kontuzinte lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'Kaj mi petis viajn disĉiplojn, ke ili elpelu ĝin; sed ili ne povis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Kaj Jesuo respondis kaj diris: Ho senfida kaj perversa generacio, ĝis kiam mi estos kun vi kaj vin toleros? venigu ĉi tien vian filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'Kaj dum li venis, la demono lin ĵetis sur la teron kaj lin konvulsiigis. Sed Jesuo severe admonis la malpuran spiriton, kaj sanigis la knabon kaj redonis lin al la patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'Kaj ĉiuj miregis pro la majesto de Dio. Sed dum ĉiuj miris pri ĉio, kion li faris, li diris al siaj disĉiploj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, 'Penetrigu ĉi tiujn vortojn en viajn orelojn: ĉar la Filo de homo estos transdonita en la manojn de homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Sed ili ne komprenis tiun diron, kaj ĝi estis kaŝita for de ili, por ke ili ne sciu ĝian signifon; kaj ili timis demandi al li pri tiu diro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Kaj komenciĝis diskutado inter ili pri tio, kiu el ili estos la plej granda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Sed Jesuo, vidinte la diskutadon de iliaj koroj, prenis infanon, kaj starigis lin apud si,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'kaj diris al ili: Kiu akceptos ĉi tiun infanon en mia nomo, tiu min akceptas; kaj kiu min akceptos, tiu akceptas Tiun, kiu min sendis; ĉar kiu estas plej malgranda inter vi ĉiuj, tiu estas granda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'Kaj Johano respondis kaj diris: Estro, ni vidis iun elpelantan demonojn en via nomo; kaj ni malpermesis lin, ĉar li ne sekvas kun ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'Sed Jesuo diris al li: Ne malpermesu; ĉar tiu, kiu ne estas kontraŭ vi, estas por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'Kaj kiam la tagoj maturiĝis por lia suprenakcepto, li firmigis sian vizaĝon, por iri al Jerusalem,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'kaj sendis senditojn antaŭ sia vizaĝo; kaj ili iris, kaj eniris en vilaĝon de la Samarianoj, por pretigi por li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'Kaj tiuj lin ne akceptis, ĉar lia vizaĝo estis direktata al Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Kaj liaj disĉiploj Jakobo kaj Johano, tion vidinte, diris: Sinjoro, ĉu vi volas, ke ni ordonu fajron malsuprenveni el la ĉielo kaj ekstermi ilin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Sed li sin turnis kaj admonis ilin; kaj li diris: Vi mem ne scias, laŭ kia spirito vi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Ĉar la Filo de homo venis, ne por pereigi animojn de homoj, sed por savi. Kaj ili iris en alian vilaĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Kaj dum ili vojaĝis, sur la vojo iu diris al li: Mi vin sekvos, kien ajn vi iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'Kaj Jesuo diris al li: La vulpoj havas kavojn, kaj la birdoj de la ĉielo havas ripozejojn; sed la Filo de homo ne havas, kie kuŝigi sian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'Kaj li diris al alia: Sekvu min. Sed li diris: Sinjoro, permesu al mi unue iri kaj enterigi mian patron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Sed li diris al li: Lasu la mortintojn enterigi siajn mortintojn; sed vi iru kaj proklamu la regnon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Kaj ankoraŭ alia diris: Mi vin sekvos, Sinjoro; sed unue permesu al mi adiaŭi tiujn, kiuj estas en mia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Sed Jesuo diris al li: Neniu, metinte sian manon al la plugilo kaj rigardante malantaŭen, taŭgas por la regno de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Kaj post tio la Sinjoro elektis sepdek aliajn, kaj ilin forsendis duope antaŭ sia vizaĝo en ĉiun urbon kaj ĉiun lokon, kien li mem estis venonta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'Kaj li diris al ili: La rikolto estas granda, sed la laborantoj estas malmultaj; petu do la Estron de la rikolto, ke Li sendu laborantojn en Sian rikolton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Iru; jen mi sendas vin kiel ŝafidojn meze de lupoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Ne portu monujon, nek saketon, nek ŝuojn; kaj salutu neniun sur la vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'Kaj en kiun ajn domon vi eniros, unue diru: Paco al ĉi tiu domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'Kaj se tie estos filo de paco, via paco restos sur li; sed se ne, ĝi revenos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'Kaj en tiu sama domo restu, manĝante kaj trinkante tion, kion ili havas; ĉar la laboranto meritas sian salajron. Ne transiru de domo en domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'Kaj en kiun ajn urbon vi eniros, kaj oni vin akceptos, manĝu tion, kion oni metos antaŭ vin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'kaj sanigu la tieajn malsanulojn, kaj diru al ili: La regno de Dio alproksimiĝis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Sed en kiun ajn urbon vi eniros, kaj oni ne akceptos vin, eliru sur ĝiajn stratojn, kaj diru:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, 'Eĉ la polvon de via urbo, kiu sin tenas al niaj piedoj, ni deviŝas kontraŭ vin; tamen sciu, ke la regno de Dio alproksimiĝis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Mi diras al vi: Estos pli elporteble en tiu tago por Sodom, ol por tiu urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Ve al vi, Ĥorazin! ve al vi, Betsaida! ĉar se en Tiro kaj Cidon estus faritaj tiuj potencaj faroj, kiuj fariĝis en vi, ili jam antaŭ longe pentus, sidante en sakaĵo kaj cindro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Tamen estos pli elporteble por Tiro kaj Cidon en la juĝado, ol por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'Kaj vi, Kapernaum, ĉu vi estos altigita ĝis la ĉielo? vi ja malsupreniros ĝis Hades.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Kiu vin aŭskultas, tiu min aŭskultas; kiu vin malŝatas, tiu min malŝatas; kaj kiu min malŝatas, tiu malŝatas Tiun, kiu min sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Kaj la sepdek revenis kun ĝojo, dirante: Sinjoro, eĉ la demonoj submetiĝas al ni per via nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Kaj li diris al ili: Mi vidis Satanon falanta de la ĉielo, kiel fulmo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Jen mi donis al vi aŭtoritaton piedpaŝi sur serpentoj kaj skorpioj, kaj sur la tuta potenco de la malamiko; kaj nenio iel vin difektos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Tamen ne ĝoju pri tio, ke la spiritoj submetiĝis al vi; sed ĝoju, ke viaj nomoj estas skribitaj en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'En tiu sama horo li ĝojis en la Sankta Spirito, kaj diris: Mi Vin gloras, ho Patro, Estro de la ĉielo kaj la tero, ke Vi kaŝis ĉi tion for de saĝuloj kaj prudentuloj, kaj malkaŝis al infanetoj; jes, Patro, ĉar al Vi tio bone plaĉis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Ĉio estas transdonita al mi de mia Patro; kaj neniu scias, kiu estas la Filo, krom la Patro; nek kiu estas la Patro, krom la Filo, kaj tiu, al kiu la Filo volas malkaŝi Lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'Kaj sin turninte al la disĉiploj, li flanke diris: Feliĉaj estas la okuloj, kiuj vidas tion, kion vi vidas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'ĉar mi diras al vi, ke multaj profetoj kaj reĝoj deziris vidi tion, kion vi vidas, kaj ili ne vidis; kaj aŭdi tion, kion vi aŭdas, kaj ili ne aŭdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'Kaj jen unu leĝisto stariĝis, kaj tentis lin, dirante: Majstro, kion mi faru, por heredi eternan vivon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'Kaj li diris al li: Kio estas skribita en la leĝo? kiel vi legas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'Kaj li responde diris: Amu la Eternulon, vian Dion, per via tuta koro kaj per via tuta animo kaj per via tuta forto kaj per via tuta menso, kaj vian proksimulon kiel vin mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Kaj li diris al li: Vi prave respondis; tion faru, kaj vi vivos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Sed li, dezirante pravigi sin, diris al Jesuo: Kaj kiu estas mia proksimulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Jesuo respondis kaj diris: Unu homo malsupreniris de Jerusalem al Jeriĥo; kaj li falis en la manojn de rabistoj, kiuj lin senvestigis kaj batis, kaj foriris, lasante lin duone senviva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'Kaj laŭ okazo unu pastro malsupreniris la saman vojon; kaj lin vidinte, li preterpasis aliflanke.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'Kaj tiel same unu Levido, veninte al la loko kaj lin vidinte, preterpasis aliflanke.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Sed unu Samariano, vojaĝante, alvenis tien, kie li estis, kaj lin ekvidinte, li kortuŝiĝis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'kaj alproksimiĝis, kaj bandaĝis liajn vundojn, kaj surverŝis oleon kaj vinon; kaj li metis lin sur sian beston, kaj kondukis lin al gastejo, kaj zorgis pri li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Kaj la morgaŭan tagon li elprenis du denarojn kaj donis ilin al la gastejestro, kaj diris: Zorgu pri li, kaj kion pli vi elspezos, mi tion repagos al vi, kiam mi revenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Kiu el tiuj tri, laŭ via opinio, sin montris proksimulo de tiu, kiu falis en la manojn de la rabistoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'Kaj li diris: Tiu, kiu faris al li kompaton. Kaj Jesuo diris al li: Iru vi, kaj faru tion saman.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'Kaj dum ili vojaĝis, li eniris en unu vilaĝon; kaj virino, nomata Marta, akceptis lin en sian domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'Kaj ŝi havis fratinon, nomatan Maria, kaj ĉi tiu sidis apud la piedoj de la Sinjoro, kaj aŭskultis lian parolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Sed Marta estis distrata pro multo da servado; kaj ŝi alproksimiĝis, kaj diris: Sinjoro, ĉu vi ne zorgas pri tio, ke mia fratino lasis al mi servi sola? diru do al ŝi, ke ŝi min helpu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'Sed la Sinjoro respondis kaj diris al ŝi: Marta, Marta, vi zorgas kaj klopodadas pri multaj aferoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'sed unu afero estas necesa; kaj Maria elektis la bonan parton, kiu ne estos prenita for de ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'Kaj li preĝis en iu loko; kaj kiam li ĉesis preĝi, unu el liaj disĉiploj diris al li: Sinjoro, instruu nin preĝi, kiel ankaŭ Johano instruis siajn disĉiplojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Kaj li diris al ili: Kiam vi preĝas, diru: Patro, Estu sanktigita Via nomo. Venu Via regno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Donu al ni tagon post tago nian ĉiutagan panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'Kaj pardonu al ni niajn pekojn, ĉar ni ankaŭ pardonas al ĉiu, kiu ŝuldas al ni. Kaj ne konduku nin en tenton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Kaj li diris al ili: Kiu el vi havos amikon, kaj iros al li noktomeze, kaj diros al li: Amiko, pruntu al mi tri panojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'ĉar amiko mia venis al mi post vojaĝo, kaj mi ne havas, kion meti antaŭ lin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'kaj tiu de interne respondos kaj diros: Ne ĝenu min; la pordo estas jam fermita, kaj miaj infanoj kun mi estas en lito; mi ne povas min levi kaj doni al vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Mi diras al vi: Kvankam li ne volos pro sia amikeco al li leviĝi kaj doni al li, tamen, pro ĉi ties persisteco li leviĝos kaj donos al li tiom, kiom li bezonas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'Kaj mi diras al vi: Petu, kaj al vi estos donite; serĉu, kaj vi trovos; frapu, kaj al vi estos malfermite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Ĉar ĉiu petanto ricevas; kaj la serĉanto trovas; kaj al la frapanto estos malfermite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Kaj de kiu el vi, kiu estas patro, filo petos panon, kaj li donos al li ŝtonon? aŭ se li petas fiŝon, ĉu li anstataŭ fiŝo donos al li serpenton?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Aŭ se li petos ovon, ĉu li donos al li skorpion?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Se vi do, estante malbonaj, scias doni bonajn donacojn al viaj infanoj, des pli via Patro ĉiela donos la Sanktan Spiriton al tiuj, kiuj petos al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'Kaj li estis elpelanta demonon, kiu estis muta. Kaj kiam la demono eliris, la mutulo parolis; kaj la homamaso miregis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Sed iuj el ili diris: Per Baal-Zebub, la estro de la demonoj, li elpelas demonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Kaj aliaj, tentante lin, postulis de li signon el la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Sed li, sciante iliajn pensojn, diris al ili: Ĉiu regno, dividita kontraŭ si, dezertiĝas; kaj domo, dividita kontraŭ domo, falas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'Kaj se ankaŭ Satano dividiĝas kontraŭ si, kiel staros lia regno? ĉar vi diras, ke per Baal-Zebub mi elpelas demonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'Kaj se per Baal-Zebub mi elpelas demonojn, per kiu viaj filoj ilin elpelas? tial ili estos viaj juĝantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Sed se per la fingro de Dio mi elpelas demonojn, tiam la regno de Dio jam venis sur vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Kiam fortulo plene armita gardas sian palacon, en paco estas liaj posedaĵoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'sed kiam venas iu pli forta ol li kaj venkos lin, li forprenas lian plenarmilaron, al kiu li fidis, kaj disdonas lian havon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Kiu ne estas kun mi, tiu estas kontraŭ mi; kaj kiu ne kolektas kun mi, tiu disĵetas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Kiam la malpura spirito eliris el homo, ĝi trairas tra senakvaj lokoj, serĉante ripozon; kaj ne trovante ĝin, diras: Mi reiros al mia domo, el kie mi eliris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'Kaj alveninte, ĝi trovas ĝin balaita kaj ornamita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Tiam ĝi iras kaj alprenas al si sep aliajn spiritojn pli malbonajn ol ĝi mem, kaj ili, enirinte, loĝas tie; kaj la fina stato de tiu homo fariĝas pli malbona, ol la unua.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'Kaj dum li ĉi tion parolis, unu virino el la homamaso levis sian voĉon, kaj diris al li: Feliĉaj estas la ventro, kiu naskis vin, kaj la mamoj, kiujn vi suĉis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'Sed li diris: Sed pli ĝuste, feliĉaj estas tiuj, kiuj aŭdas la vorton de Dio kaj observas ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'Kaj kiam la homamaso kolektiĝis al li, li ekparolis, dirante: Ĉi tiu generacio estas malbona generacio; ĝi serĉas signon, kaj signo ne estos donita al ĝi, krom la signo de Jona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Ĉar kiel Jona estis signo por la Nineveanoj, tiel ankaŭ estos la Filo de homo por ĉi tiu generacio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'La reĝino de la sudo leviĝos en la juĝado kun la viroj de ĉi tiu generacio, kaj ilin kondamnos; ĉar ŝi venis el la finoj de la tero, por aŭskulti la saĝon de Salomono; kaj jen iu pli granda ol Salomono estas ĉi tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Viroj Nineveanoj staros en la juĝado kun ĉi tiu generacio, kaj ĝin kondamnos; ĉar ili pentis pro la predikado de Jona; kaj jen iu pli granda ol Jona estas ĉi tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Kiam oni ekbruligis lampon, oni metas ĝin ne en kaŝejon, nek sub grenmezurilon, sed sur la lampingon, por ke la enirantoj povu vidi la lumon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'La lampo de via korpo estas via okulo; kiam via okulo estas sendifekta, via tuta korpo estas luma; sed kiam ĝi estas malbona, via korpo ankaŭ estas malluma.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Tial viglu, ke la lumo, kiu estas en vi, ne estu mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Tial, se via tuta korpo estas luma, havante nenian malluman parton, ĝi estos tute lumplena, kiel kiam la lampo lumas al vi per sia brilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Kaj dum li parolis, unu Fariseo invitis lin matenmanĝi kun li; kaj li eniris kaj sidiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'Kaj la Fariseo, ekvidinte, miris, ke li ne lavis sin antaŭ la matenmanĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Kaj la Sinjoro diris al li: Vi Fariseoj purigas la eksteron de kaliko kaj plado, sed via interno estas plena de rabado kaj malvirto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Malsaĝuloj! ĉu Tiu, kiu faris la eksteron, ne faris ankaŭ la internon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Tamen, uzu por almozo la internaĵojn, kaj jen ĉio estas al vi pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Sed ve al vi, Fariseoj! ĉar vi pagas dekonaĵojn de mento kaj ruto kaj ĉiu vegetaĵo, kaj preterlasas juĝon kaj amon al Dio; ĉi tion vi devus fari, kaj tion ne preterlasi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Ve al vi, Fariseoj! ĉar vi amas la ĉefseĝojn en la sinagogoj, kaj la salutojn sur la placoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Ve al vi! ĉar vi similas tombojn ne vidatajn; kaj la homoj, kiuj iras super ili, ne scias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'Kaj unu el la leĝistoj responde diris al li: Majstro, dirante ĉi tion, vi ankaŭ nin riproĉas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'Kaj li diris: Ve ankaŭ al vi, leĝistoj! ĉar vi ŝarĝas homojn per ŝarĝoj malfacile porteblaj, kaj vi mem ne tuŝas eĉ per unu el viaj fingroj la ŝarĝojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Ve al vi! ĉar vi konstruas la tombojn de la profetoj, kiujn viaj patroj mortigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Tial vi estas atestantoj, kaj konsentas al la faroj de viaj patroj; ĉar ili mortigis ilin, kaj vi konstruas la tombojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Tial ankaŭ diris la saĝo de Dio: Mi sendos al ili profetojn kaj apostolojn, kaj iujn el tiuj ili mortigos kaj persekutos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'por ke la sango de ĉiuj profetoj, kiu estis elverŝita de post la komenco de la mondo, estu postulita el ĉi tiu generacio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'de la sango de Habel ĝis la sango de Zeĥarja, kiu pereis inter la altaro kaj la sankta domo; jes, mi diras al vi: Ĝi estos postulita el ĉi tiu generacio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Ve al vi, leĝistoj! ĉar vi forprenis la ŝlosilon de la scio; vi mem ne eniris, kaj vi malhelpis la enirantajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'Kaj kiam li eliris el tie, la skribistoj kaj la Fariseoj atakis lin insiste, kaj instigis lin paroli pri multaj aferoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'insidante kontraŭ li, por kapti ion el lia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Dume, kiam la miriadoj de la homamaso kunkolektiĝis tiel, ke ili piedpremis unu la alian, li ekparolis al siaj disĉiploj, dirante unue: Gardu vin kontraŭ la fermentaĵo de la Fariseoj, kiu estas hipokriteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Sed estas nenio kovrita, kio ne estos elmontrita; kaj nenio kaŝita, kio ne estos sciata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'Tial, kion vi diris en la mallumo, tio estos aŭdita en la lumo; kaj kion vi parolis en orelon en internaj ĉambroj, tio estos proklamita sur la tegmentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Kaj mi diras al vi, miaj amikoj: Ne timu tiujn, kiuj mortigas la korpon, kaj poste ne povas fari ion plu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Sed mi montros al vi, kiun vi devas timi: Timu Tiun, kiu, mortiginte, plue havas aŭtoritaton enĵeti en Gehenan; jes, mi diras al vi: Tiun timu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Ĉu oni ne vendas kvin paserojn por du asaroj? kaj eĉ unu el ili ne estas forgesita antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'Sed eĉ la haroj de via kapo estas ĉiuj kalkulitaj. Ne timu; vi pli valoras ol multaj paseroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Kaj mi diras al vi: Ĉiun, kiu konfesos min antaŭ la homoj, la Filo de homo ankaŭ konfesos antaŭ la anĝeloj de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'sed kiu malkonfesos min antaŭ la homoj, tiu estos malkonfesita antaŭ la anĝeloj de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'Kaj por ĉiu, kiu parolos vorton kontraŭ la Filo de homo, estos pardono; sed por tiu, kiu blasfemas kontraŭ la Sankta Spirito, ne estos pardono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Kaj kiam oni kondukos vin antaŭ la sinagogojn kaj regantojn kaj aŭtoritatulojn, ne zorgu, kiel aŭ kion respondi, aŭ kion diri;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'ĉar la Sankta Spirito instruos al vi en tiu horo mem tion, kion vi devas diri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Kaj unu el la homamaso diris al li: Majstro, diru al mia frato, ke li dividu kun mi la heredaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Sed li diris al li: Ho viro, kiu starigis min super vi kiel juĝanton aŭ dividanton?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'Kaj li diris al ili: Zorgu, kaj gardu vin kontraŭ ĉia avideco, ĉar la vivo de homo ne konsistas en la abundeco de liaj posedaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Kaj li parolis al ili parabolon, dirante: La bieno de unu riĉulo donis abunde;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'kaj li konsideris, dirante: Kion mi faru, ĉar mi ne havas lokon, kie mi povas amasigi miajn fruktojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Kaj li diris: Jen kion mi faros: mi disbatos miajn grenejojn kaj konstruos pli grandajn, kaj tie mi amasigos mian grenon kaj miajn posedaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'Kaj mi diros al mia animo: Animo, vi havas multajn posedaĵojn, provizitajn por multaj jaroj; ripozu, manĝu, trinku, estu gaja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Sed Dio diris al li: Ho senprudentulo! ĉi tiun nokton oni postulas de vi vian animon; kies estos tio, kion vi preparis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Tia estas tiu, kiu kolektas por si trezoron, kaj ne estas riĉa rilate Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Kaj li diris al siaj disĉiploj: Tial mi diras al vi: Ne zorgu pri via vivo, kion vi manĝu; nek pri via korpo, kion vi surmetu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'Ĉar la vivo estas pli ol nutraĵo, kaj la korpo pli ol vestaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Pripensu la korvojn, ke ili ne semas, nek rikoltas, kaj ne havas provizejon nek grenejon; kaj Dio nutras ilin; kiom pli vi valoras, ol la birdoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'Kaj kiu el vi per zorgado povas aldoni unu ulnon al sia staturo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Se do vi ne povas fari eĉ la plej malgrandan aferon, kial vi zorgas pri la ceteraj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Pripensu la liliojn, kiel ili kreskas; ili ne laboras, nek ŝpinas; tamen mi diras al vi: Eĉ Salomono en sia tuta gloro ne estis ornamita tiel, kiel unu el ĉi tiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'Sed se Dio tiel vestas la kampan herbaĵon, kiu hodiaŭ ekzistas, kaj morgaŭ estos ĵetata en fornon, kiom pli certe Li vestos vin, ho malgrandfiduloj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'Kaj ne serĉu, kion vi manĝos, kaj kion vi trinkos, kaj ne estu dubemaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'Ĉar pri ĉio tio serĉas la nacioj de la mondo; sed via Patro scias, ke vi tion bezonas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Sed celu Lian regnon, kaj ĉio tio estos aldonita al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Ne timu, malgranda grego; ĉar bone plaĉis al la Patro doni al vi la regnon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Vendu viajn posedaĵojn, kaj donu almozon; faru por vi monujojn, kiuj ne fariĝos malnovaj, trezoron ne mankontan en la ĉielo, kie ŝtelisto ne alproksimiĝas kaj tineo ne detruas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Ĉar kie estas via trezoro, tie estos ankaŭ via koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Viaj lumboj estu zonitaj, kaj viaj lampoj estu brulantaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'kaj vi mem estu similaj al viroj, kiuj atendas sian sinjoron, kiam li revenos de la edziĝa festo; por ke ili tuj malfermu al li, kiam li venos kaj frapos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Feliĉaj estas tiuj servistoj, kiujn la sinjoro, kiam li venos, trovos viglaj; vere mi diras al vi, ke li sin zonos, kaj sidigos ilin por manĝi, kaj mem venos kaj servos al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'Kaj se li alvenos nokte dum la dua gardoparto, aŭ dum la tria gardoparto, kaj tiel ilin trovos, feliĉaj estas tiuj servistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Sed sciu, ke se la domomastro scius, je kioma horo la ŝtelisto venos, li maldormus kaj ne lasus sian domon trafosiĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Vi ankaŭ estu pretaj, ĉar en tiu horo, kiun vi ne pripensas, la Filo de homo venos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Kaj Petro diris: Sinjoro, ĉu vi parolas ĉi tiun parabolon por ni, aŭ ankaŭ por ĉiuj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'Kaj la Sinjoro diris: Kiu do estas la fidela kaj saĝa administranto, kiun lia sinjoro starigos super sia servantaro, por doni al ili ĝustatempe ilian porcion da nutraĵo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Feliĉa estas tiu servisto, kiun lia sinjoro, veninte, trovos aganta tiel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'Vere mi diras al vi, ke li starigos lin super ĉio, kion li havas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Sed se tiu servisto diros en sia koro: Mia sinjoro prokrastas sian alvenon; kaj komencos bati la knabojn kaj la knabinojn, kaj manĝos kaj trinkos kaj ebriiĝos,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'la sinjoro de tiu servisto alvenos en tago, kiam li ne atendas, kaj en horo, pri kiu li ne scias; kaj tranĉe skurĝos lin, kaj difinos por li parton kun la senfiduloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Kaj tiu servisto, kiu sciis la volon de sia sinjoro, kaj nenion pretigis, nek faris laŭ lia volo, suferos multajn batojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'sed tiu, kiu ne sciis, kaj laŭ siaj agoj meritis batojn, suferos malmultajn batojn. Kaj al kiu multo estas donita, el tiu estos multo postulata; kaj al kiu oni multon komisiis, el tiu oni des pli multon postulos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Mi alvenis, por ĵeti fajron sur la teron; kaj kion mi volas, se jam ĝi ekbrulis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Sed mi havas bapton, per kiu esti baptita; kaj kiel mi premiĝas, ĝis ĝi estos plenumita!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Ĉu vi supozas, ke mi alvenis, por doni pacon sur la tero? Mi diras al vi: Ne; sed pli vere disigon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'ĉar de nun estos kvin el unu domo disigitaj, tri kontraŭ du, kaj du kontraŭ tri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'Estos disigitaj patro kontraŭ filo, kaj filo kontraŭ patro; patrino kontraŭ filino, kaj filino kontraŭ patrino; bopatrino kontraŭ bofilino, kaj bofilino kontraŭ bopatrino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Kaj li diris al la homamasoj: Kiam vi vidas nubon leviĝantan en la okcidento, vi tuj diras: Venos pluveto; kaj tiel fariĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'Kaj kiam blovas la suda vento, vi diras: Estos varmego; kaj tiel fariĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Ho hipokrituloj! vi scias esplori la aspekton de la tero kaj de la ĉielo; sed kial vi ne scias esplori ĉi tiun tempon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Kaj kial eĉ per vi mem vi ne juĝas, kio estas justa?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Ĉar dum vi iradas kun via kontraŭulo al la reganto, survoje klopodu liberiĝi de li; por ne lasi, ke li trenu vin al la juĝisto, kaj la juĝisto vin transdonu al la oficisto de la tribunalo, kaj la oficisto vin ĵetu en malliberejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Mi diras al vi: Vi neniel el tie eliros, ĝis vi pagos la lastan lepton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'Kaj ĉeestis en tiu sama tempo iuj, kiuj rakontis al li pri tiuj Galileanoj, kies sangon Pilato miksis kun iliaj oferaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'Kaj responde li diris al ili: Ĉu vi pensas, ke tiuj Galileanoj estis pekuloj pli ol ĉiuj Galileanoj, pro tio, ke ili tion suferis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Mi diras al vi: Neniel; sed se vi ne pentos, vi ĉiuj tiel same pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Aŭ pri tiuj dek ok, sur kiujn falis la turo en Ŝiloaĥ kaj ilin mortigis, ĉu vi pensas, ke ili estis pekuloj pli ol ĉiuj homoj, kiuj loĝis en Jerusalem?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Neniel, mi diras al vi; sed se vi ne pentos, vi ĉiuj ankaŭ pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Kaj li parolis la jenan parabolon: Unu viro havis figarbon, plantitan en lia vinberĝardeno, kaj li venis, serĉante frukton sur ĝi, kaj ne trovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Kaj li diris al la vinberisto: Jen tri jarojn mi venas, serĉante frukton sur ĉi tiu figarbo, kaj mi ne trovas; elhaku ĝin; kial ĝi senutiligas ankaŭ la teron?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Sed li responde diris: Sinjoro, lasu ĝin resti ankaŭ ĉi tiun jaron, ĝis mi fosos ĉirkaŭ ĝi kaj metos sterkon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'kaj se ĝi poste donos frukton, bone; sed se ne, vi elhakos ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Kaj li instruadis en unu el la sinagogoj en la sabato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'Kaj jen virino, kiu dum dek ok jaroj havis spiriton de malforteco; kaj ŝi estis kunkurbita kaj neniel povis leviĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Kaj vidinte ŝin, Jesuo vokis ŝin, kaj diris: Virino, vi estas liberigita el via malforteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'Kaj li metis sur ŝin la manojn, kaj ŝi tuj rektiĝis kaj gloris Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Kaj la sinagogestro, indignante, ke Jesuo resanigis en la sabato, respondis kaj diris al la homamaso: Ekzistas ses tagoj, en kiuj oni devas labori; en ili do venu, por esti resanigitaj, kaj ne en la sabata tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Sed la Sinjoro respondis al li kaj diris: Ho hipokrituloj! ĉu ne ĉiu el vi en la sabato malligas sian bovon aŭ sian azenon el la stalo, kaj forkondukas ĝin, por trinkigi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Kaj ĉu ne devis ĉi tiu virino, estante filino de Abraham, ligite de Satano jen dek ok jarojn, esti malligita el ĉi tiu kateno en la sabata tago?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'Kaj kiam li tion diris, ĉiuj liaj kontraŭuloj hontiĝis; kaj la tuta homamaso ĝojis pro ĉiuj gloraj agoj, faritaj de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Kaj li diris: Al kio similas la regno de Dio? kaj al kio mi ĝin komparu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Ĝi estas simila al sinapa semeto, kiun viro prenis kaj ĵetis en sian ĝardenon; kaj ĝi kreskis kaj fariĝis arbo; kaj la birdoj de la ĉielo loĝis en ĝiaj branĉoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'Poste li diris: Al kio mi komparu la regnon de Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Ĝi estas simila al fermentaĵo, kiun virino prenis kaj kaŝis en tri mezuroj da faruno, ĝis la tuto fermentis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'Kaj li iris tra urboj kaj vilaĝoj, instruante kaj irante ĉiam pluen al Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Kaj iu diris al li: Sinjoro, ĉu malmultaj estas la savataj? Kaj li diris al ili:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, 'Strebu eniri tra la mallarĝa pordo; ĉar multaj, mi diras al vi, deziros eniri kaj ne povos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Kiam la domomastro leviĝos kaj ŝlosos la pordon, kaj vi komencos stari ekstere kaj frapi sur la pordon, dirante: Sinjoro, malfermu al ni; kaj li respondos kaj diros al vi: Mi ne scias, de kie vi estas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'tiam vi ekparolos: Ni manĝis kaj trinkis antaŭ vi, kaj sur niaj stratoj vi instruadis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'kaj li parolos, kaj diros al vi: Mi ne scias, de kie vi estas; foriru de mi, ĉiuj farantoj de maljusteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Tie estos la plorado kaj la grincado de dentoj, kiam vi vidos Abrahamon kaj Isaakon kaj Jakobon kaj ĉiujn profetojn en la regno de Dio, kaj vin mem forpelitaj eksteren.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'Kaj oni venos el oriento kaj el okcidento, kaj el nordo kaj el sudo, kaj sidiĝos en la regno de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'Kaj jen estas lastaj, kiuj estos unuaj; kaj estas unuaj, kiuj estos lastaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'En tiu sama horo alvenis iuj Fariseoj, kaj diris al li: Eliru kaj foriru de ĉi tie, ĉar Herodo volas mortigi vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'Kaj li diris al ili: Iru, kaj diru al tiu vulpo: Jen mi elpelas demonojn kaj faras sanigojn hodiaŭ kaj morgaŭ, kaj la trian tagon mi estos perfektigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Sed mi devas iradi hodiaŭ kaj morgaŭ kaj postmorgaŭ, ĉar ne povas esti, ke profeto pereos ekster Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Ho Jerusalem, Jerusalem, kiu pereigas la profetojn kaj ŝtonmortigas tiujn, kiuj estas senditaj al ĝi! kiom ofte mi deziris kolekti viajn infanojn, kiel kokino kolektas sian idaron sub la flugilojn, kaj vi ne volis!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Jen via domo estas lasita al vi dezerta; kaj mi diras al vi: Vi min ne vidos, ĝis vi diros: Estu benata tiu, kiu venas en la nomo de la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'Kaj kiam li eniris en sabato en la domon de unu reganto de la Fariseoj, por manĝi panon, ili lin observis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'Kaj jen antaŭ li estis unu hidropsulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'Kaj respondante, Jesuo parolis al la leĝistoj kaj la Fariseoj, kaj diris: Ĉu estas permesate sanigi en sabato, aŭ ne?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Sed ili silentis. Kaj li prenis lin kaj sanigis lin, kaj forliberigis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'Kaj li diris al ili: Kiu el vi havos azenon aŭ bovon, falintan en puton, kaj ne tuj eltiros ĝin en sabata tago?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'Kaj ili ne povis respondi al tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Kaj li parolis parabolon al la invititoj, vidinte, kiel ili elektas la ĉefajn sidlokojn; li diris al ili:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, 'Kiam vi estas invitita de iu al edziĝa festo, ne sidiĝu en la ĉefa loko, por ke ne okazu, ke iu, pli honorinda ol vi, estas de li invitita;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'kaj tiu, kiu invitis vin kaj lin, venos, kaj diros al vi: Cedu lokon al ĉi tiu; kaj tiam vi komencos kun honto preni la lastan lokon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Sed kiam vi estas invitita, iru kaj sidiĝu en la lasta loko; kaj tiel, kiam venos tiu, kiu vin invitis, li diros al vi: Amiko, iru pli alten; tiam vi havos honoron antaŭ ĉiuj, kiuj sidas kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Ĉar ĉiu, kiu sin altigas, estos humiligita, kaj kiu sin humiligas, tiu estos altigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Kaj li diris al tiu, kiu lin invitis: Kiam vi faras tagmanĝon aŭ vespermanĝon, ne voku viajn amikojn, nek viajn fratojn, nek viajn parencojn, nek viajn riĉajn najbarojn, por ke ne okazu, ke ili ankaŭ invitos vin, kaj vi ricevos rekompencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Sed kiam vi faras festenon, invitu malriĉulojn, kriplulojn, lamulojn, blindulojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'kaj vi estos feliĉa, ĉar ili ne povas rekompenci vin, sed vi rekompenciĝos en la releviĝo de la justuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Kaj aŭdinte tion, unu el la kunsidantoj diris al li: Feliĉa estas tiu, kiu manĝos panon en la regno de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Sed li diris al li: Unu viro faris grandan vespermanĝon, kaj invitis multajn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'kaj en la horo de la festeno li elsendis sian serviston, por diri al la invititoj: Venu, ĉar ĉio estas jam preta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'Kaj ĉiuj tiel same komencis peti pri indulgo. La unua diris al li: Mi aĉetis kampon, kaj mi nepre devas eliri, por ĝin vidi; mi petas, kalkulu al mi indulgon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'Alia diris: Mi aĉetis kvin jugojn da bovoj, kaj mi iras, por ilin provi; mi petas, kalkulu al mi indulgon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'Kaj alia diris: Mi edziĝis kun edzino, kaj tial mi ne povas veni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'Kaj la servisto revenis, kaj rakontis tion al sia mastro. Tiam ekkoleris la mastro, kaj diris al sia servisto: Eliru rapide sur la stratojn kaj irejojn de la urbo, kaj alkonduku ĉi tien la malriĉulojn kaj kriplulojn kaj blindulojn kaj lamulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'Kaj la servisto diris: Sinjoro, estas farita tio, kion vi ordonis, kaj ankoraŭ estas loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'Kaj la sinjoro diris al la servisto: Eliru sur la vojojn kaj kamplimojn, kaj devigu ilin enveni, por ke mia domo pleniĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Ĉar mi diras al vi, ke neniu el tiuj viroj invititaj gustumos mian vespermanĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Kaj grandaj homamasoj iris kun li, kaj li sin turnis, kaj diris al ili:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, 'Se iu venas al mi, kaj ne malamas sian patron kaj sian patrinon kaj sian edzinon kaj siajn infanojn kaj fratojn kaj fratinojn, kaj eĉ ankaŭ sian vivon, li ne povas esti mia disĉiplo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'Kiu ne portas sian krucon kaj ne sekvas min, tiu ne povas esti mia disĉiplo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Ĉar kiu el vi, dezirante konstrui turon, unue ne sidiĝas, por kalkuli la koston, ĉu li havas sufiĉe, por fini ĝin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'Por ke, kiam li metis la fundamenton kaj ne povas ĝin fini, ĉiuj vidantoj ne komencu moki lin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'dirante: Ĉi tiu homo komencis konstrui, sed ne povis fini.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Kaj kiu reĝo, ekirante, por renkonti en batalo alian reĝon, unue ne sidiĝos, por konsiliĝi, ĉu li povas kun dek mil renkonti tiun, kiu venas kontraŭ li kun dudek mil?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Aŭ alie, dum la alia estas tre malproksime, li alsendas ambasadorojn kaj demandas pri paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Kiu do el vi ne forlasas ĉiujn siajn posedaĵojn, tiu ne povas esti mia disĉiplo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Salo do estas bona, sed se eĉ la salo sengustiĝis, per kio ĝi estos spicata?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Ĝi taŭgas nek por la tero nek por sterkejo; oni ĝin forĵetas. Kiu havas orelojn por aŭdi, tiu aŭdu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Kaj ĉiuj impostistoj kaj pekuloj alproksimiĝis al li, por aŭskulti lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'Kaj murmuris la Fariseoj kaj la skribistoj, dirante: Ĉi tiu akceptas pekulojn kaj manĝas kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Kaj li parolis al ili la jenan parabolon, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, 'Kiu el vi, havante cent ŝafojn kaj perdinte unu el ili, ne forlasas la naŭdek naŭ sur la stepo, kaj iras, por serĉi tiun, kiun li perdis, ĝis li ĝin trovos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'Kaj trovinte, li ĝin metas sur siajn ŝultrojn, ĝojante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'Kaj reveninte domen, li kunvokas siajn amikojn kaj siajn najbarojn, dirante al ili: Ĝoju kun mi, ĉar mi trovis mian ŝafon, la perditan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Mi diras al vi, ke tiel same estos ĝojo en la ĉielo pro unu pekulo, kiu pentas, pli ol pro naŭdek naŭ justuloj, kiuj ne bezonas penton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Kiu virino, havante dek draĥmojn, se ŝi perdis unu draĥmon, ne ekbruligas lampon kaj balaas la domon kaj serĉas diligente, ĝis ŝi ĝin trovos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'Kaj trovinte, ŝi kunvokas siajn amikinojn kaj siajn najbarinojn, dirante: Ĝoju kun mi, ĉar mi trovis la draĥmon, kiun mi perdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Tiel same, mi diras al vi, estas ĝojo antaŭ la anĝeloj de Dio pro unu pekulo, kiu pentas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Kaj li diris: Unu viro havis du filojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'kaj la pli juna diris al sia patro: Patro, donu al mi la heredotan parton de la havo. Kaj li dividis inter ili siajn vivrimedojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Kaj post ne multaj tagoj la pli juna, kolektinte ĉion, forvojaĝis al malproksima lando; kaj tie li disperdis sian havon per diboĉa vivado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'Kaj kiam li jam elspezis ĉion, forta malsato okazis en tiu lando, kaj li komencis havi mankon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'Kaj li iris, kaj aliĝis al unu el la loĝantoj de tiu lando; kaj ĉi tiu lin sendis sur siajn kampojn, por paŝti porkojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'Kaj li deziris plenigi sian ventron per la karoboj, kiujn la porkoj manĝis; kaj neniu donis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Sed reveninte al si, li diris: Kiom da dungitoj de mia patro havas panon abunde, sed mi ĉi tie pereas de malsato!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Mi leviĝos, kaj iros al mia patro, kaj mi diros al li: Patro, mi pekis kontraŭ la ĉielo kaj antaŭ vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'mi jam ne meritas esti nomata via filo; faru min kiel unu el viaj dungitoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'Kaj li leviĝis, kaj iris al sia patro. Sed kiam li estis ankoraŭ malproksime, lia patro lin vidis kaj kortuŝiĝis, kaj kurinte, falis sur lian kolon kaj lin kisadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'Kaj la filo diris al li: Patro, mi pekis kontraŭ la ĉielo kaj antaŭ vi, kaj mi jam ne meritas esti nomata via filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Kaj diris la patro al siaj servistoj: Alportu rapide la ĉefan robon, kaj lin vestu, kaj metu ringon sur lian manon kaj ŝuojn sur liajn piedojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'kaj alportu la grasigitan bovidon kaj buĉu ĝin, kaj ni manĝu kaj estu gajaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'ĉar ĉi tiu mia filo estis mortinta, kaj denove vivas; li estis perdita, kaj estas trovita. Kaj ili komencis esti gajaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Sed la pli maljuna filo estis sur la kampo; kaj kiam li venis kaj alproksimiĝis al la domo, li aŭdis muzikon kaj dancadon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'Kaj li alvokis unu el la knaboj, kaj demandis lin, kio estas tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'Kaj li diris al li: Via frato venis, kaj via patro buĉis la grasigitan bovidon, ĉar li ricevis lin sana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Sed li koleris, kaj ne volis eniri; kaj lia patro elvenis, kaj lin petegis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'Sed li responde diris al sia patro: Jen tiom da jaroj mi servas al vi, kaj neniam mi malobeis vian ordonon, tamen vi neniam donis al mi kapridon, por ke mi estu gaja kun miaj amikoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'sed kiam venis ĉi tiu via filo, kiu formanĝis vian havon kun malĉastistinoj, vi buĉis por li la grasigitan bovidon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'Kaj li diris al li: Filo, vi estas ĉiam kun mi, kaj ĉio mia estas via.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Sed konvenis esti gajaj kaj ĝoji; ĉar ĉi tiu via frato estis mortinta, kaj denove vivas; li estis perdita, kaj estas trovita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Kaj li diris ankaŭ al siaj disĉiploj: Estis unu riĉa homo, kiu havis administranton; kaj ĉi tiu estis denuncita al li, ke li disperdas lian havon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Kaj li alvokis lin, kaj diris al li: Kio estas tio, kion mi aŭdas pri vi? donu al mi konton de via administrado, ĉar vi ne plu povas administradi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'Tiam la administranto diris en si: Kion mi faru? ĉar mia sinjoro deprenas de mi la administradon; fosi mi ne povas, kaj mi hontas peti almozon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Mi decidis, kion mi faros, por ke oni akceptu min en siajn domojn, kiam mi estos eksigita el la administra ofico.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'Kaj alvokinte al si ĉiun el la ŝuldantoj de sia sinjoro, li diris al la unua: Kiom vi ŝuldas al mia sinjoro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'Kaj li diris: Cent bat�ojn da oleo. Kaj li diris al li: Prenu vian kalkulon, kaj tuj sidiĝu kaj skribu kvindek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Tiam li diris al alia: Kaj kiom vi ŝuldas? Kaj li diris: Cent kor�ojn da tritiko. Li diris al li: Prenu vian kalkulon, kaj skribu okdek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'Kaj tiu sinjoro laŭdis la maljustan administranton, ĉar li prudente agis; ĉar la filoj de ĉi tiu mondo estas en sia generacio pli prudentaj, ol la filoj de la lumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'Kaj mi diras al vi: Faru al vi amikojn per la mamono de maljusteco, por ke, kiam ĝi mankos, oni akceptu vin en eternajn loĝejojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Kiu estas fidela en la plej malgranda afero, tiu estas fidela ankaŭ en multo; kaj kiu estas maljusta en la plej malgranda, tiu estas ankaŭ maljusta en multo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Se do vi ne estis fidelaj en la maljusta mamono, kiu konfidos al vi la veran riĉon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'Kaj se vi ne estis fidelaj en tio, kio apartenas al alia homo, kiu donos al vi tion, kio estas via propra?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Nenia servanto povas servi al du sinjoroj; ĉar aŭ li malamos unu kaj amos la alian, aŭ li aliĝos al unu kaj malestimos la alian. Vi ne povas servi al Dio kaj al Mamono!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Kaj la Fariseoj ankaŭ, kiuj estis monavidaj, aŭdis ĉion tion, kaj ili lin mokis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'Kaj li diris al ili: Vi estas tiuj, kiuj ŝajnigas sin justaj antaŭ homoj, sed Dio scias viajn korojn; ĉar kio estas altigita inter homoj, tio estas abomenaĵo antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'La leĝo kaj la profetoj estis ĝis Johano; de post tiu tempo la evangelio de la regno de Dio estas predikata, kaj ĉiu al ĝi sin perforte aligas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Sed estas pli facile por la ĉielo kaj la tero forpasi, ol por unu punkteto de la leĝo fali.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Ĉiu, kiu forsendas sian edzinon kaj edziĝas kun alia, adultas; kaj kiu edziĝas kun tiu, forsendita de sia edzo, tiu adultas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Estis unu riĉulo, kiu estis vestita per purpuro kaj bisino, kaj festis lukse ĉiutage;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'kaj apud lia pordego estis kuŝigita almozulo, nomata Lazaro, kiu havis ulcerojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'kaj deziris esti nutrata per la panpecetoj, kiuj falis de la tablo de la riĉulo; kaj eĉ venis la hundoj kaj lekis liajn ulcerojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Kaj la almozulo mortis, kaj li estis forportita de la anĝeloj sur la sinon de Abraham; la riĉulo ankaŭ mortis, kaj estis enterigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'Kaj en Hades li levis siajn okulojn, estante en turmentoj, kaj vidis Abrahamon malproksime kaj Lazaron sur lia sino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'Kaj li ekkriis, kaj diris: Patro Abraham, kompatu min, kaj sendu Lazaron, por ke li trempu en akvon la pinton de sia fingro, por malvarmigi mian langon; ĉar mi tre suferas en ĉi tiu flamo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Sed Abraham diris: Filo, memoru, ke dum via vivo vi ricevis viajn bonaĵojn, kaj Lazaro tiel same malbonaĵojn; sed nun li ricevas konsolon, kaj vi suferas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'Kaj krom ĉio tio staras granda abismo inter ni kaj vi, tiel ke tiuj, kiuj volus iri de ĉi tie al vi, ne povas, kaj oni ne povas transiri de tie al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'Kaj li diris: Tial mi petas, patro, ke vi sendu lin al la domo de mia patro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'ĉar mi havas kvin fratojn, por ke li atestu al ili, por ke ili ne venu ankaŭ en ĉi tiun lokon de turmento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Sed Abraham diris: Ili havas Moseon kaj la profetojn; ili aŭskultu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'Sed li diris: Ne, patro Abraham; sed se unu venos al ili el la mortintoj, ili pentos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Kaj li diris al li: Se ili ne aŭskultas Moseon kaj la profetojn, ili ne kredos, eĉ se iu leviĝus el la mortintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Kaj li diris al siaj disĉiploj: Ne povas esti, ke faliloj ne venos, sed ve al tiu, per kiu ili venos!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Pli bone estus por tiu, se muelŝtono estus pendigita ĉirkaŭ lia kolo, kaj se li estus ĵetita en la maron, ol se li metus falilon por unu el ĉi tiuj malgranduloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Gardu vin; se via frato pekos, admonu lin; kaj se li pentos, pardonu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'Kaj se li pekos kontraŭ vi sep fojojn en la tago, kaj sep fojojn turniĝos al vi, dirante: Mi pentas; vi lin pardonu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'Kaj la apostoloj diris al la Sinjoro: Aldonu al ni fidon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'Kaj la Sinjoro diris: Se vi havus fidon kiel semeron de sinapo, vi dirus al ĉi tiu morusarbo: Estu elradikigita, kaj estu plantita en la maron; kaj ĝi obeus al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Sed kiu el vi, havante serviston plugantan aŭ paŝtantan, diros al li, kiam li envenis de la kampo: Tuj venu, kaj sidiĝu, por manĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Ĉu li ne diros al li prefere: Preparu ion, por ke mi verspermanĝu, kaj zonu vin, kaj servu al mi, dum mi manĝos kaj trinkos; kaj poste vi manĝos kaj trinkos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Ĉu li dankas la serviston, ĉar li faris tion, kio estis ordonita?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Tiel ankaŭ vi, kiam vi faris ĉion, kio estas ordonita al vi, diru: Ni estas senutilaj servistoj; ni faris tion, kion fari estis nia devo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'Kaj dum ili vojiris al Jerusalem, li trapasis tra la mezo de Samario kaj de Galileo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'Kaj kiam ili eniris en unu vilaĝon, renkontis lin dek lepruloj, kiuj staris malproksime;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'kaj ili levis sian voĉon, dirante: Jesuo, estro, kompatu nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'Kaj vidinte ilin, li diris al ili: Iru, kaj montru vin al la pastroj. Kaj dum ili iris, ili fariĝis puraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Kaj unu el ili, vidinte, ke li resaniĝis, revenis, glorante Dion per laŭta voĉo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'kaj falis sur sian vizaĝon ĉe liaj piedoj kaj dankis lin; kaj li estis Samariano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Kaj Jesuo responde diris: Ĉu ne la dek estis purigitaj? sed kie estas la naŭ?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Ĉu ne troviĝis revenantoj, por doni gloron al Dio, krom ĉi tiu fremdulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'Kaj li diris al li: Leviĝu kaj iru; via fido vin savis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Kaj kiam la Fariseoj demandis al li, kiam venos la regno de Dio, li respondis al ili, dirante: La regno de Dio ne venas kun observado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'kaj oni ne diros: Jen ĉi tie, aŭ: Jen tie! ĉar jen la regno de Dio estas inter vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'Kaj li diris al la disĉiploj: Venos tagoj, kiam vi deziros vidi unu el la tagoj de la Filo de homo, kaj vi ne vidos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'Kaj ili diros al vi: Jen tie! Jen ĉi tie! Ne foriru, nek sekvu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'ĉar kiel la fulmo, kiam ĝi fulmas el unu subĉiela flanko, lumas ĝis alia subĉiela flanko, tiel estos la Filo de homo en sia tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Sed unue li devas multon suferi, kaj esti malŝatata de ĉi tiu generacio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'Kaj kiel estis en la tagoj de Noa, tiel estos en la tagoj de la Filo de homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'Oni manĝis, trinkis, edziĝis, edziniĝis, ĝis la tago, kiam Noa eniris en la arkeon, kaj venis la diluvo kaj pereigis ĉiujn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Ankaŭ tiel same, kiel estis en la tagoj de Lot; oni manĝis, trinkis, aĉetis, vendis, plantis, konstruis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'sed en la tago, kiam Lot eliris el Sodom, fajro kaj sulfuro falis el la ĉielo kaj pereigis ĉiujn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'tiel same estos en tiu tago, kiam la Filo de homo malkaŝiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'Kiu estos sur la tegmento en tiu tago, kun liaj havaĵoj en la domo, tiu ne malsupreniru, por ilin forporti; kaj kiu estas sur la kampo, tiu ankaŭ ne revenu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Memoru la edzinon de Lot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Kiu penos gajni sian animon, tiu ĝin perdos; sed kiu ĝin perdos, tiu savos ĝin viva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Mi diras al vi: En tiu nokto estos du viroj sur unu lito; unu estos prenita, kaj la alia lasita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Du virinoj estos muelantaj kune; unu estos prenita, kaj la alia lasita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, 'Du viroj estos sur kampo; unu estos prenita, kaj la alia lasita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'Kaj ili responde diris al li: Kie, Sinjoro? Kaj li diris al ili: Kie estas la kadavro, tien ankaŭ kolektiĝos la agloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Kaj li parolis al ili parabolon pri tio, ke oni devas ĉiam preĝi kaj ne laciĝi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'dirante: En unu urbo estis juĝisto, kiu ne timis Dion, nek respektis homon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'kaj estis vidvino en tiu urbo, kaj ŝi venadis al li, dirante: Faru por mi justecon kontraŭ mia kontraŭulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'Kaj li ne volis dum kelka tempo, sed poste li diris en si: Kvankam mi ne timas Dion, nek respektas homon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'tamen, ĉar ĉi tiu vidvino min ĝenas, mi faros por ŝi justecon, por ke ŝi ne malfortigu min per sia ĉiama venado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Kaj la Sinjoro diris: Aŭskultu, kion diras la maljusta juĝisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'Kaj ĉu Dio ne faros justecon por Siaj elektitoj, kiuj tage kaj nokte krias al Li, kvankam Li longe pri ili paciencas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Mi diras al vi: Rapide Li faros por ili justecon. Tamen kiam venos la Filo de homo, ĉu li trovos fidon sur la tero?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Kaj li parolis la jenan parabolon, ankaŭ por iuj, kiuj fidis al si, ke ili estas justuloj, kaj malestimis la ceterajn:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, 'Du homoj supreniris en la templon, por preĝi; unu estis Fariseo, kaj la alia estis impostisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'La Fariseo, starante, preĝis kun si jene: Ho Dio, mi Vin dankas, ke mi ne estas kiel la ceteraj homoj, rabemaj, maljustaj, adultemaj, nek eĉ kiel ĉi tiu impostisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Mi fastas dufoje en semajno; mi donas dekonaĵojn el ĉio, kion mi akiras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Sed la impostisto, starante malproksime, ne volis eĉ levi la okulojn al la ĉielo, sed batadis sian bruston, dirante: Ho Dio, estu favora al mi pekulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Mi diras al vi: Ĉi tiu malsupreniris al sia domo, pravigita pli ol tiu; ĉar ĉiu, kiu sin altigas, estos humiligita; sed kiu sin humiligas, tiu estos altigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Kaj oni venigis al li ankaŭ siajn infanetojn, por ke li tuŝu ilin; kaj la disĉiploj, vidinte, admonis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Sed Jesuo alvokis ilin al si, dirante: Lasu la infanojn veni al mi, kaj ne malhelpu ilin; ĉar el tiaj estas la regno de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Vere mi diras al vi: Kiu ne akceptos la regnon de Dio kiel infano, tiu neniel eniros en ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'Kaj unu reganto demandis al li, dirante: Bona Majstro, kion mi faru, por heredi eternan vivon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'Kaj Jesuo diris al li: Kial vi nomas min bona? neniu estas bona krom Unu, nome Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Vi scias la ordonojn: Ne adultu; Ne mortigu; Ne ŝtelu; Ne parolu malveran ateston; Respektu vian patron kaj vian patrinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'Kaj li diris: Ĉion tion mi observis detempe de mia juneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Kaj Jesuo, aŭdinte, diris al li: Ankoraŭ unu mankon vi havas: vendu ĉion, kion vi posedas, kaj disdonu al malriĉuloj, kaj vi havos trezoron en la ĉielo; kaj venu, sekvu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Sed aŭdinte tion, li fariĝis tre malĝoja; ĉar li estis tre riĉa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Kaj Jesuo, lin rigardante, diris: Kiel malfacile tiuj, kiuj havas riĉon, eniros en la regnon de Dio!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Ĉar estas pli facile por kamelo iri tra trueton de kudrilo, ol por riĉulo eniri en la regnon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Kaj tiuj, kiuj tion aŭdis, diris: Kiu do povos esti savita?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'Sed li diris: Kio estas neebla ĉe homoj, tio estas ebla ĉe Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'Kaj Petro diris: Jen ni forlasis niajn propraĵojn, kaj sekvis vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'Kaj li diris al ili: Vere mi diras al vi: Estas neniu, kiu forlasis domon aŭ edzinon aŭ fratojn aŭ gepatrojn aŭ infanojn pro la regno de Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'kaj kiu ne ricevos multoble en ĉi tiu tempo, kaj en la venonta mondo vivon eternan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Kaj preninte al si la dek du, li diris al ili: Jen ni supreniras al Jerusalem; kaj ĉio skribita per la profetoj estos plenumita al la Filo de homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Ĉar li estos transdonita al la nacianoj, kaj mokita kaj perfortita kaj surkraĉita;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'kaj ili skurĝos kaj mortigos lin; kaj la trian tagon li releviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Kaj ili komprenis nenion el tio, kaj ĉi tiu parolo estis kaŝita for de ili, kaj ili ne sciis la dirojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'Kaj kiam li alproksimiĝis al Jeriĥo, unu blindulo sidis apud la vojo, petante almozojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'kaj aŭdinte homamason preterirantan, li demandis, kio estas tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'Kaj oni diris al li, ke Jesuo, la Nazaretano, preteriras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'Kaj li kriis, dirante: Jesuo, filo de David, kompatu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Kaj la antaŭirantoj admonis lin, ke li silentu; sed li des pli forte kriis: Ho filo de David, kompatu min!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Kaj Jesuo haltis, kaj ordonis alkonduki lin; kaj kiam li alproksimiĝis, li lin demandis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'Kion vi volas, ke mi faru al vi? Kaj li diris: Sinjoro, ke mi ricevu vidpovon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'Kaj Jesuo diris al li: Ricevu vidpovon; via fido vin savis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'Kaj li tuj ricevis vidpovon, kaj sekvis lin, glorante Dion; kaj la tuta popolo, vidinte tion, donis laŭdon al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'Kaj li eniris en Jeriĥon kaj ĝin trapasis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'Kaj jen viro, nomata Zakĥeo; kaj li estis ĉefimpostisto, kaj li estis riĉa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'Kaj li penis vidi Jesuon, kia homo li estas; kaj li ne povis pro la homamaso, ĉar li estis malgranda je staturo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'Kaj antaŭkurinte antaŭen, li supreniris sur sikomorarbon, por lin vidi; ĉar li estis preterpasonta tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'Kaj kiam Jesuo venis al la loko, li suprenrigardis, kaj diris al li: Zakĥeo, rapide malsupreniru, ĉar hodiaŭ mi devas loĝi en via domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'Kaj li rapide malsupreniris, kaj akceptis lin ĝoje.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'Kaj vidinte, ĉiuj murmuris, dirante: Ĉe pekulo li eniris, por gasti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Kaj Zakĥeo, starante, diris al la Sinjoro: Jen duonon de miaj posedaĵoj, Sinjoro, mi donacas al la malriĉuloj; kaj se el iu mi maljuste eldevigis ion, mi redonas kvaroblon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Kaj Jesuo diris al li: Hodiaŭ venis savo al ĉi tiu domo, ĉar li ankaŭ estas filo de Abraham.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'Ĉar la Filo de homo venis, por serĉi kaj savi la perditaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'Kaj kiam oni aŭdis tion, li parolis ankoraŭ parabolon, ĉar li estis proksime al Jerusalem, kaj oni supozis, ke la regno de Dio tuj aperos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Li do diris: Unu nobelo forvojaĝis en malproksiman landon, por ricevi al si regnon, kaj reveni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'Kaj vokinte al si dek siajn servistojn, li donis al ili dek min�ojn, kaj diris al ili: Negocadu, ĝis mi revenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Sed liaj regnanoj lin malamis, kaj sendis delegitaron post li, dirante: Ni ne volas, ke tiu viro reĝu super ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'Kaj kiam li revenis, ricevinte la regnon, li ordonis voki al li tiujn servistojn, al kiuj li donis la monon, por ke li sciiĝu, kiom ili gajnis per negocado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Kaj venis la unua, kaj diris: Sinjoro, via min�o produktis dek min�ojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'Kaj li diris al li: Bonege, bona servisto; ĉar vi estis fidela en tre malgranda afero, havu aŭtoritaton super dek urboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'Kaj venis la dua, kaj diris: Sinjoro, via min�o faris kvin min�ojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'Li diris ankaŭ al tiu: Vi ankaŭ estu super kvin urboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'Kaj alia venis, kaj diris: Sinjoro, jen via min�o, kiun mi konservis, flankemetitan en viŝtuko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'ĉar mi vin timis, ĉar vi estas homo severa; vi prenas tion, kion vi ne demetis, kaj rikoltas tion, kion vi ne semis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Li diris al li: El via propra buŝo mi vin juĝos, vi malbona servisto. Vi sciis, ke mi estas homo severa, kiu prenas tion, kion mi ne demetis, kaj rikoltas tion, kion mi ne semis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'kial do vi ne donis mian monon en bankon, por ke, reveninte, mi postulu ĝin kun procento?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'Kaj li diris al la apudstarantoj: Forprenu de li la min�on, kaj donu ĝin al tiu, kiu havas la dek min�ojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, '(Kaj ili diris al li: Sinjoro, li havas dek min�ojn.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, 'Mi diras al vi, ke al ĉiu, kiu havas, estos donite; kaj for de tiu, kiu ne havas, estos prenita eĉ tio, kion li havas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Cetere tiujn miajn malamikojn, kiuj ne volis, ke mi reĝu super ili, konduku ĉi tien, kaj mortigu ilin antaŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'Kaj tion dirinte, li ekiris antaŭe, suprenirante al Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'Kaj kiam li alproksimiĝis al Betfage kaj Betania, apud la monto nomata Olivarba, li sendis du el siaj disĉiploj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'dirante: Iru en la kontraŭan vilaĝon, en kiu, enirante, vi trovos azenidon ligitan, sur kiu neniu iam ankoraŭ sidis; ĝin malligu kaj alkonduku.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'Kaj se iu demandos al vi: Kial vi ĝin malligas? parolu jene: La Sinjoro ĝin bezonas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Kaj la senditoj foriris, kaj trovis, ĝuste kiel li diris al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'Kaj dum ili malligis la azenidon, ĝiaj posedantoj diris al ili: Kial vi malligas la azenidon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'Kaj ili diris: La Sinjoro ĝin bezonas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'Kaj ili alkondukis ĝin al Jesuo; kaj ĵetinte siajn vestojn sur la azenidon, ili sidigis Jesuon sur ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'Kaj dum li iris, ili sternis siajn vestojn sur la vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'Kaj kiam li jam alproksimiĝis, malsuprenironte la deklivon de la monto Olivarba, la tuta amaso de la disĉiploj komencis ĝoji kaj laŭdi Dion per laŭta voĉo pro ĉiuj potencaĵoj, kiujn ili vidis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'dirante: Estu benata la Reĝo, kiu venas en la nomo de la Eternulo; paco en la ĉielo kaj gloro en la supera alto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Kaj iuj Fariseoj el la homamaso diris al li: Majstro, admonu viajn disĉiplojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'Kaj responde li diris: Mi diras al vi, ke se ĉi tiuj silentos, la ŝtonoj ekkrios.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'Kaj kiam li alproksimiĝis, li rigardis la urbon, kaj ploris pro ĝi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'dirante: Ho, se vi mem scius en ĉi tiu tago la aferojn apartenantajn al paco! sed nun ili estas kaŝitaj for de viaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Ĉar venos sur vin tagoj, kiam viaj malamikoj ĉirkaŭbaros vin per palisaro, kaj ronde ĉirkaŭos vin, kaj ĉiuflanke premos vin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'kaj detruos ĝis la tero vin, kaj viajn infanojn en vi, kaj ne lasos en vi ŝtonon sur ŝtono, pro tio, ke vi ne sciis la tempon de via vizitado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'Kaj enirinte en la templon, li komencis elpeli la vendantojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'dirante al ili: Estas skribite: Mia domo estos domo de preĝo; sed vi faris ĝin kaverno de rabistoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'Kaj li instruis tagon post tago en la templo. Sed la ĉefpastroj kaj la skribistoj kaj la ĉefoj de la popolo penadis lin pereigi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'kaj ne trovis, kion fari, ĉar la tuta popolo tre atente aŭskultis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'Kaj en unu el la tagoj, dum li instruis la popolon en la templo kaj predikis la evangelion, la ĉefpastroj kaj la skribistoj venis kun la pliaĝuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'kaj ili ekparolis, dirante al li: Diru al ni: Laŭ kia aŭtoritato vi ĉi tion faras? aŭ kiu estas tiu, kiu donis al vi tian aŭtoritaton?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'Kaj responde li diris al ili: Mi ankaŭ faros al vi demandon, kaj diru al mi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'La baptado de Johano, ĉu ĝi estis el la ĉielo, aŭ el homoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'Kaj ili diskutis inter si, dirante: Se ni diros: El la ĉielo; li diros: Kial vi ne kredis al li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Sed se ni diros: El homoj; la tuta popolo ŝtonmortigos nin, ĉar ili estas konvinkitaj, ke Johano estis profeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'Kaj ili respondis, ke ili ne scias, de kie ĝi estis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'Kaj Jesuo diris al ili: Kaj mi ne diras al vi, laŭ kia aŭtoritato mi faras ĉi tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'Kaj li komencis paroli al la popolo la jenan parabolon: Unu viro plantis vinberĝardenon, kaj luigis ĝin al kultivistoj, kaj forvojaĝis por longa tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'Kaj en la ĝusta tempo li sendis sklavon al la kultivistoj, por ke ili donu al li el la frukto de la vinberejo; sed la kultivistoj skurĝis lin, kaj forsendis lin senhava.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'Kaj li sendis ankoraŭ alian sklavon, kaj lin ankaŭ ili skurĝis kaj malhonoris, kaj forsendis lin senhava.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'Kaj li sendis ankoraŭ trian, kaj lin ankaŭ ili vundis kaj elĵetis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Kaj la sinjoro de la vinberejo diris: Kion mi faru? Mi sendos mian amatan filon; eble lin ili respektos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Sed kiam la kultivistoj lin vidis, ili diskutis unu kun alia, dirante: Ĉi tiu estas la heredonto; ni lin mortigu, por ke la heredaĵo fariĝu nia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'Kaj ili elĵetis lin el la vinberejo kaj lin mortigis. Kion do faros al ili la sinjoro de la vinberejo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Li venos kaj pereigos ĉi tiujn kultivistojn, kaj donos la vinberejon al aliaj. Kaj aŭdinte tion, ili diris: Ne tiel estu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Sed li, rigardante ilin, diris: Kio do estas la jena skribitaĵo: Ŝtono, kiun malŝatis la konstruantoj, Fariĝis ŝtono bazangula?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Ĉiu, kiu falas sur tiun ŝtonon, rompiĝos; sed sur kiun ĝi falos, tiun ĝi polvigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'Kaj la skribistoj kaj ĉefpastroj celis meti manojn sur lin en tiu sama horo, kaj ili timis la popolon; ĉar ili eksciis, ke kontraŭ ili li parolis ĉi tiun parabolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'Kaj ili observis lin, kaj elsendis spionojn, kiuj ŝajnigis sin justaj, por ke ili ekkaptu lian parolon, celante transdoni lin al la potenco kaj aŭtoritato de la provincestro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'Kaj ili demandis lin, dirante: Majstro, ni scias, ke vi prave parolas kaj instruas, kaj ne akceptas ies personon, sed instruas laŭ vero la vojon de Dio:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Ĉu konvenas al ni doni tributon al Cezaro, aŭ ne?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Sed sciante ilian ruzecon, li diris al ili:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, 'Montru al mi denaron. Kies bildon kaj surskribaĵon ĝi portas? Kaj ili respondis: De Cezaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'Kaj li diris al ili: Tial redonu al Cezaro la propraĵon de Cezaro, kaj al Dio la propraĵon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'Kaj ili ne povis ekkapti la diron antaŭ la popolo; kaj ili miris pro lia respondo, kaj silentis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Kaj venis iuj el la Sadukeoj, kiuj diras, ke ne estas releviĝo; kaj ili demandis lin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'dirante: Majstro, Moseo skribis por ni, ke, se ies frato mortos, havante edzinon, kaj li estas seninfana, lia frato prenu la edzinon kaj naskigu idaron al sia frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Estis do sep fratoj; kaj la unua edziĝis, kaj mortis seninfana;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'ankaŭ la dua;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'kaj la tria ŝin prenis; kaj tiel same ankaŭ la sep ne lasis infanojn, kaj mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Laste mortis ankaŭ la virino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'En la releviĝo do por kiu el ili ŝi estos edzino? ĉar la sep havis ŝin kiel edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'Kaj Jesuo diris al ili: La filoj de ĉi tiu mondo edziĝas kaj estas edzigataj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'sed kiuj estas juĝitaj indaj atingi tiun mondon kaj la releviĝon el la mortintoj, tiuj nek edziĝas nek edziniĝas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'ĉar ili ne plu povas morti; ĉar ili estas egalaj kun la anĝeloj, kaj estas filoj de Dio, estante filoj de la releviĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'Sed ke la mortintoj leviĝas, Moseo mem montris en la arbetaĵo, kiam li nomis la Eternulon la Dio de Abraham kaj la Dio de Isaak kaj la Dio de Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Li estas Dio ne de mortintoj, sed de la vivantoj, ĉar ĉiuj vivas al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Kaj iuj el la skribistoj responde diris: Majstro, vi bone diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'Kaj ili ne plu kuraĝis fari al li demandon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Kaj li diris al ili: Kiel oni diras, ke la Kristo estas filo de David?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'Ĉar David mem diras en la Psalmaro: La Eternulo diris al mia Sinjoro: Sidu dekstre de Mi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'Ĝis Mi faros viajn malamikojn benketo por viaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'Tial David nomas lin Sinjoro, kaj kiamaniere li estas lia filo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'Kaj dum la tuta popolo aŭskultis, li diris al siaj disĉiploj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, 'Gardu vin kontraŭ la skribistoj, kiuj amas promenadi en roboj kaj amas salutojn sur la placoj, kaj ĉefseĝojn en la sinagogoj, kaj ĉeflokojn ĉe festenoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'kaj kiuj formanĝas domojn de vidvinoj, kaj por preteksto longe preĝas. Ĉi tiuj ricevos pli severan kondamnon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'Kaj ekrigardante, li vidis riĉulojn enĵetantajn siajn donacojn en la monkeston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Kaj li vidis unu malriĉan vidvinon enĵetantan tien du leptojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'Kaj li diris: Vere mi diras al vi: Ĉi tiu malriĉa vidvino enĵetis pli multe ol ĉiuj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'ĉar ĉiuj tiuj el sia abundo enĵetis en la donacaron; sed ŝi el sia malmultego enĵetis la tutan vivrimedon, kiun ŝi havis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'Kaj kiam iuj parolis pri la templo, ke ĝi estas ornamita per belaj ŝtonoj kaj oferdonoj, li diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, 'Rilate al tio, kion vi vidas, venos tagoj, en kiuj ne estos lasita ĉi tie ŝtono sur ŝtono, kiu ne estos deĵetita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'Kaj ili demandis lin, dirante: Majstro, kiam do tio estos? kaj kio estos la signo, kiam tio estos proksima?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'Kaj li diris: Gardu vin, ke vi ne estu erarigitaj; ĉar multaj venos en mia nomo, dirante: Mi estas; kaj: La tempo proksimiĝis; ne sekvu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Kaj kiam vi aŭdos pri militoj kaj tumultoj, ne teruriĝu; ĉar tio devas okazi unue, sed ne tuj estos la fino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Tiam li diris al ili: Leviĝos nacio kontraŭ nacio, kaj regno kontraŭ regno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'kaj estos grandaj tertremoj, kaj en diversaj lokoj malsatoj kaj pestoj; kaj estos teruraĵoj kaj grandaj signoj el la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Sed antaŭ ĉio tio oni metos sur vin siajn manojn kaj persekutos vin, transdonante vin al la sinagogoj kaj malliberejoj, kaj kondukante vin antaŭ reĝojn kaj provincestrojn pro mia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'Tio fariĝos por vi atesto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Decidu tial en viaj koroj, ne prizorgi antaŭe pri pleda respondo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'ĉar mi donos al vi buŝon kaj saĝon, kiun ĉiuj viaj atakantoj ne povos rezisti nek kontraŭdiri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'Sed vi estos transdonitaj eĉ de gepatroj kaj fratoj kaj parencoj kaj amikoj; kaj iujn el vi oni mortigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'Kaj vi estos malamataj de ĉiuj pro mia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Kaj eĉ unu haro de via kapo ne pereos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'Per via pacienco vi akiros viajn animojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'Sed kiam vi vidos Jerusalemon ĉirkaŭitan de armeoj, tiam sciu, ke ĝia ruiniĝo alproksimiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Tiam, kiuj estas en Judujo, tiuj forkuru al la montoj; kaj kiuj estas en ĝia mezo, tiuj elmigru; kaj kiuj estas sur la kamparo, tiuj ne eniru tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Ĉar tiuj estas tagoj de punado, por ke plenumiĝu ĉio, kio estas skribita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Ve al la gravedulinoj kaj al la suĉigantinoj en tiuj tagoj! ĉar estos granda manko sur la tero, kaj kolero kontraŭ ĉi tiu popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'Kaj ili falos per tranĉrando de glavo, kaj forkaptiĝos en ĉiujn naciojn; kaj Jerusalem estos piedpremata de la nacianoj, ĝis plenumiĝos la tempoj de la nacianoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'Kaj estos signoj en la suno kaj la luno kaj la steloj, kaj sur la tero mizero de nacioj, konsternitaj de la muĝado de la maro kaj la ondegoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'homoj malfortiĝos de timo kaj de atendado de tio, kio venos sur la mondon; ĉar la potencoj de la ĉielo ŝanceliĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'Kaj tiam oni vidos la Filon de homo, venantan en nubo kun potenco kaj granda gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Sed kiam tio komencos okazi, rigardu supren kaj levu viajn kapojn, ĉar via elaĉeto alproksimiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'Kaj li parolis al ili parabolon: Rigardu la figarbon kaj ĉiujn arbojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'kiam ili ekkreskigas foliojn, vi ekvidas, kaj el vi mem scias, ke la somero jam estas proksima.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'Tiel same vi, kiam vi vidos, ke tio okazas, tiam sciu, ke la regno de Dio estas proksima.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Vere mi diras al vi: Ĉi tiu generacio ne forpasos, ĝis ĉio plenumiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'La ĉielo kaj la tero forpasos, sed miaj vortoj ne forpasos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'Sed gardu vin, por ke viaj koroj ne estu ŝarĝitaj de trosatiĝo kaj ebrieco kaj zorgoj pri vivrimedoj, kaj por ke tiu tago ne venu al vi subite;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'ĉar kiel kaptilo ĝi venos sur ĉiujn, kiuj loĝas sur la supraĵo de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Sed viglu en ĉiu tempo, preĝante, ke prosperu al vi saviĝi de ĉio, kio okazos, kaj stari antaŭ la Filo de homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'Kaj dum la tagoj li instruis en la templo, kaj ĉiunokte li eliris, kaj loĝis sur la monto nomata Olivarba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'Kaj la tuta popolo venis al li frumatene en la templo, por aŭskulti lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Jam alproksimiĝis la festo de macoj, kiu estas nomata la Pasko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'Kaj la ĉefpastroj kaj la skribistoj serĉis, kiamaniere ili povu mortigi lin, ĉar ili timis la popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Kaj Satano eniris en Judason, nomatan Iskariota, kiu estis el la nombro de la dek du.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'Kaj li foriris kaj interparolis kun la ĉefpastroj kaj kapitanoj, kiamaniere transdoni lin al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'Kaj ili ĝojis, kaj konsentis doni al li monon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'Kaj li promesis, kaj serĉis okazon transdoni lin al ili, for de la homamaso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Kaj venis la tago de macoj, kiam oni devis buĉi la Paskon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'Kaj li sendis Petron kaj Johanon, dirante: Iru kaj pretigu por ni la Paskon, por ke ni ĝin manĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'Kaj ili diris al li: Kie vi volas, ke ni pretigu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'Kaj li diris al ili: Jen kiam vi estos enirintaj en la urbon, vin renkontos viro, portanta kruĉon da akvo; lin sekvu en la domon, en kiun li eniros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'Kaj vi diros al la domomastro: La Majstro diras: Kie estas la gastoĉambro, en kiu mi manĝos la Paskon kun miaj disĉiploj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'Kaj li montros al vi grandan supran ĉambron aranĝitan; tie pretigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'Kaj ili iris kaj trovis tiel, kiel li diris al ili; kaj ili pretigis la Paskon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'Kaj kiam alvenis la horo, li sidiĝis, kaj la apostoloj kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'Kaj li diris al ili: Kun deziro mi deziris manĝi ĉi tiun Paskon kun vi, antaŭ ol mi suferos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'ĉar mi diras al vi: Mi ne manĝos ĝin, antaŭ ol ĝi plenumiĝos en la regno de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'Kaj ricevinte kalikon, kaj doninte dankon, li diris: Ĉi tion prenu kaj dividu inter vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'ĉar mi diras al vi: De nun mi ne trinkos el la frukto de la vinberarbo, ĝis venos la regno de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'Kaj li prenis panon, kaj doninte dankon, li ĝin dispecigis kaj donis al ili, dirante: Ĉi tio estas mia korpo, kiu estas donita por vi; ĉi tion faru por memorigo pri mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'Sammaniere ankaŭ la kalikon post la vespermanĝo, dirante: Ĉi tiu kaliko estas la nova interligo en mia sango, kiu estas elverŝata por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Sed jen la mano de tiu, kiu min perfidas, estas apud mi sur la tablo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'Ĉar la Filo de homo ja iros, laŭ la antaŭdecido; sed ve al tiu viro, de kiu li estos perfidata!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'Kaj ili komencis diskuti inter si: kiu el ili faros tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Kaj fariĝis ankaŭ inter ili disputo: kiun el ili oni opinias la plej granda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'Kaj li diris al ili: La reĝoj de la nacianoj faras sin sinjoroj super ili; kaj tiujn, kiuj potencas inter ili, oni nomas Bonfarantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Sed vi ne estu tiaj; sed kiu estas la pli granda el vi, tiu fariĝu kiel la pli juna; kaj tiu, kiu estas ĉefa, kiel la servanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Ĉar kiu estas la pli granda, la sidanto ĉe manĝo, aŭ la servanto? ĉu ne la sidanto ĉe manĝo? sed mi estas meze de vi kiel la servanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'Sed vi estas tiuj, kiuj restadis apud mi en miaj tentoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'kaj mi difinas por vi regnon, kiel mia Patro difinis por mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'por ke vi manĝu kaj trinku ĉe mia tablo en mia regno, kaj sidu sur tronoj, juĝante la dek du tribojn de Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'Simon, Simon, jen Satano postulis vin ĉiujn, por kribri kiel tritikon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'sed mi preĝis por vi, ke via fido ne ŝanceliĝu; kaj vi, kiam vi konvertiĝos, firmigu viajn fratojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'Kaj li diris al li: Sinjoro, vin mi estas preta akompani eĉ al malliberejo kaj al morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'Kaj li diris: Mi diras al vi, Petro, koko ne krios hodiaŭ, antaŭ ol vi trifoje malkonfesos, ke vi min konas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'Kaj li diris al ili: Kiam mi vin elsendis sen monujo kaj sako kaj ŝuoj, ĉu io mankis al vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Kaj ili diris: Nenio. Kaj li diris al ili: Sed nun kiu havas monujon, tiu prenu ĝin, kaj ankaŭ sakon; kaj kiu ne havas, tiu vendu sian mantelon kaj aĉetu glavon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Ĉar mi diras al vi, ke tio, kio estas skribita, devas plenumiĝi pri mi: Kaj li estis alkalkulita al krimuloj; ĉar tio, kio rilatas al mi, havas sian finon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Kaj ili diris: Sinjoro, jen estas du glavoj; kaj li diris al ili: Sufiĉas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'Kaj elirinte, li iris laŭ sia kutimo al la monto Olivarba, kaj la disĉiploj lin sekvis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'Kaj veninte al la loko, li diris al ili: Preĝu, ke vi ne eniru en tenton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'Kaj li iris for de ili proksimume ŝtonĵeton, kaj li genuis, kaj preĝis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'dirante: Patro, se Vi volas, formetu de mi ĉi tiun kalikon; tamen plenumiĝu ne mia volo, sed Via.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'Kaj aperis antaŭ li anĝelo el la ĉielo, fortigante lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'Kaj estante en agonio, li preĝis pli fervore, kaj lia ŝvito fariĝis kiel gutoj da sango, defalantaj sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'Kaj leviĝinte post la preĝo, li venis al la disĉiploj kaj trovis ilin dormantaj de malĝojo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'kaj diris al ili: Kial vi dormas? leviĝu kaj preĝu, ke vi ne eniru en tenton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Dum li ankoraŭ parolis, jen homamaso; kaj tiu, kiu estis nomata Judas, unu el la dek du, iris antaŭ ili, kaj alproksimiĝis al Jesuo, por kisi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Sed Jesuo diris al li: Judas, ĉu vi perfidas per kiso la Filon de homo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Kaj kiam tiuj, kiuj ĉirkaŭis lin, vidis, kio sekvos, ili diris: Sinjoro, ĉu ni frapu per glavo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'Kaj unu el ili frapis la sklavon de la ĉefpastro, kaj detranĉis lian dekstran orelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Sed Jesuo responde diris: Permesu tiom. Kaj li tuŝis lian orelon kaj sanigis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'Kaj Jesuo diris al la ĉefpastroj kaj kapitanoj de la templo kaj pliaĝuloj, kiuj venis kontraŭ lin: Ĉu vi elvenis kun glavoj kaj bastonoj, kvazaŭ kontraŭ rabiston?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Kiam mi estis ĉiutage inter vi en la templo, vi ne etendis kontraŭ min viajn manojn; sed ĉi tiu estas via horo, kaj la potenco de mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'Kaj ili kaptis lin, kaj forkondukinte, venigis lin en la domon de la ĉefpastro. Sed Petro sekvis malproksime.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'Kaj kiam oni ekbruligis fajron meze de la korto kaj sidis kune, Petro sidiĝis meze de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'Kaj unu servantino, vidante lin sidantan en la fajrolumo, kaj fikse rigardinte lin, diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'Ĉi tiu ankaŭ estis kun li. Sed li malkonfesis, dirante: Virino, mi lin ne konas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'Kaj post iom da tempo alia vidis lin, kaj diris: Vi ankaŭ estas el ili. Sed Petro diris: Viro, mi ne estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'Kaj post la daŭro de unu horo proksimume, alia asertis persiste, dirante: Vere, ĉi tiu ankaŭ estis kun li, ĉar li estas Galileano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'Sed Petro diris: Viro, mi ne scias, kion vi diras. Kaj tuj, dum li ankoraŭ parolis, la koko kriis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'Kaj la Sinjoro sin turnis, kaj alrigardis Petron. Kaj Petro ekmemoris la vorton de la Sinjoro, ke li diris al li: Antaŭ ol koko krios hodiaŭ, vi trifoje min malkonfesos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'Kaj li eliris, kaj maldolĉe ploris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Kaj tiuj, kiuj gardis Jesuon, lin mokis kaj batis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'Kaj ili ĉirkaŭkovris lin, kaj demandis lin, dirante: Profetu, kiu vin frapis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'Kaj per multaj aliaj insultoj ili parolis kontraŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'Kaj tuj kiam tagiĝis la pliaĝularo de la popolo kunvenis, kaj ĉefpastroj kaj skribistoj, kaj ili forkondukis lin antaŭ sian sinedrion, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'Se vi estas la Kristo, diru al ni. Sed li diris al ili: Se mi diros al vi, vi ne kredos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'kaj se mi demandos, vi ne respondos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Tamen, de nun la Filo de homo sidos dekstre de la Potenco de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Kaj ili ĉiuj demandis: Ĉu vi do estas la Filo de Dio? Kaj li respondis: Vi diras, ke mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'Kaj ili diris: Pro kio ni bezonas pluan atestadon? ĉar ni mem aŭdis el lia propra buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'Kaj la tuta ĉeestantaro leviĝis, kaj kondukis lin antaŭ Pilaton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'Kaj ili komencis akuzi lin, dirante: Ni trovis ĉi tiun viron erariganta nian nacion, kaj malpermesanta pagi tributon al Cezaro, kaj diranta, ke li mem estas Kristo, reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Kaj Pilato demandis lin, dirante: Ĉu vi estas la Reĝo de la Judoj? Kaj li responde al li diris: Vi diras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Kaj Pilato diris al la ĉefpastroj kaj homamasoj: Mi trovas nenian kulpon en ĉi tiu viro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Sed ili insistis, dirante: Li malkvietigas la popolon, instruante tra la tuta Judujo, kaj komencante de Galileo, eĉ ĝis ĉi tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Sed kiam Pilato tion aŭdis, li demandis, ĉu la viro estas Galileano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'Kaj kiam li sciiĝis, ke li estas el sub la aŭtoritato de Herodo, li sendis lin al Herodo, kiu ankaŭ ĉeestis en Jerusalem en tiuj tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Sed Herodo, vidinte Jesuon, treege ĝojis; ĉar de longe li deziris vidi lin, ĉar li jam aŭdis pri li, kaj li esperis vidi ian signon, faritan de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'Kaj li demandis lin per multaj vortoj, sed li respondis al li nenion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'Kaj la ĉefpastroj kaj la skribistoj staris, forte lin akuzante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'Kaj Herodo kaj liaj soldatoj malhonoris lin kaj mokis lin, kaj vestinte lin per brilaj vestoj, li resendis lin al Pilato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'Kaj Herodo kaj Pilato fariĝis amikoj unu kun la alia en tiu sama tago; ĉar antaŭe ili havis inter si malamon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'Kaj Pilato, kunvokinte la ĉefpastrojn kaj la regantojn kaj la popolon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'diris al ili: Vi alkondukis antaŭ min ĉi tiun viron, kiel erarigantan la popolon; kaj jen ekzameninte lin antaŭ vi, mi trovis nenian kulpon en ĉi tiu viro rilate tion, pri kio vi lin akuzas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'nek Herodo ankaŭ, ĉar li resendis lin al ni; kaj jen nenio inda je morto estas farita de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Tial mi lin skurĝos kaj liberigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, 'Ĉar li devis liberigi unu al ili dum la festo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Sed amase ili kriis, dirante: Forigu lin, kaj liberigu al ni Barabason;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'kiu pro ribelado farita en la urbo, kaj pro mortigo, estis ĵetita en malliberejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Kaj Pilato, volante liberigi Jesuon, denove parolis al ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'sed ili laŭte kriis, dirante: Krucumu, krucumu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'Kaj la trian fojon li diris al ili: Kial? kian malbonon faris ĉi tiu? mi trovis en li nenion indan je morto; mi do lin skurĝos kaj liberigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Sed ili insistis per grandaj krioj, postulante krucumi lin. Kaj iliaj krioj superfortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'Kaj Pilato donis juĝon, ke plenumiĝu ilia postulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'Kaj li liberigis tiun, kiu pro ribelado kaj mortigo estis ĵetita en malliberejon, kaj kiun ili postulis; sed Jesuon li transdonis al ilia volo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'Kaj kiam ili forkondukis lin, ili kaptis Simonon, Kirenanon, venantan de la kamparo, kaj metis sur lin la krucon, por porti ĝin post Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'Kaj sekvis lin granda amaso de la popolo, kaj de virinoj, kiuj ĝemis kaj lamentis pro li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Sed Jesuo, turninte sin al ili, diris: Filinoj de Jerusalem, ne ploru pro mi, sed ploru pro vi kaj pro viaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'Ĉar jen venas tagoj, kiam oni diros: Feliĉaj estas la senfruktaj, kaj la ventroj ne naskintaj, kaj la mamoj ne nutrintaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Tiam oni komencos diri al la montoj: Falu sur nin; kaj al la montetoj: Kovru nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Ĉar se oni tiel agas en la suka ligno, kiel oni agos en la seka?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Kaj estis kondukataj kun li ankaŭ aliaj du, krimuloj, por esti mortigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'Kaj kiam ili alvenis al la loko nomata Kranio, tie ili krucumis lin, kaj la krimulojn, unu dekstre kaj unu maldekstre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Kaj Jesuo diris: Patro, pardonu ilin; ĉar ili ne scias, kion ili faras. Kaj dividante inter si liajn vestojn, ili ĵetis lotojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'Kaj la popolo staris, rigardanta. Kaj la regantoj ankaŭ mokis lin, dirante: Aliajn li savis: li savu sin mem, se ĉi tiu estas la Kristo de Dio, la elektito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Kaj ŝercis pri li ankaŭ la soldatoj, venante al li kaj proponante al li vinagron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'kaj dirante: Se vi estas la Reĝo de la Judoj, savu vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Kaj estis ankaŭ surskribo super li: ĈI TIU ESTAS LA REĜO DE LA JUDOJ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'Kaj unu el la pendigitaj krimuloj insultis lin, dirante: Ĉu vi ne estas la Kristo? savu vin kaj nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Sed la alia responde admonis lin, dirante: Ĉu vi eĉ ne timas Dion? ĉar vi estas en la sama kondamno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'Kaj ni ja juste, ĉar ni ricevas rekompencon, merititan pro niaj faroj; sed ĉi tiu faris nenion malbonan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'Kaj li diris: Jesuo, memoru min, kiam vi venos en vian regnon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'Kaj li diris al li: Vere mi diras al vi: Hodiaŭ vi estos kun mi en Paradizo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'Kaj jam estis ĉirkaŭ la sesa horo, kaj fariĝis mallumo sur la tuta lando ĝis la naŭa, ĉar la sunlumo mankis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'kaj la kurteno de la sanktejo disŝiriĝis en la mezo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'Kaj kriinte per laŭta voĉo, Jesuo diris: Patro, en Viajn manojn mi transdonas mian spiriton; kaj tion dirinte, li ellasis for la spiriton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Kaj kiam la centestro vidis la okazantaĵon, li gloris Dion, dirante: Ĉi tiu estis ja justulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'Kaj ĉiuj homamasoj, kiuj kunvenis al ĉi tiu spektaklo, kiam ili vidis la okazintaĵojn, reiris, frapante al si la bruston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Kaj ĉiuj liaj konantoj, kaj la virinoj, kiuj sekvis lin el Galileo, staris malproksime, vidante tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'Kaj jen viro nomata Jozef, kiu estis konsilanto, viro bona kaj justa');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, '(li ne konsentis al ilia intenco kaj faro), el Arimateo, urbo de la Judoj, kiu atendis la regnon de Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'irinte al Pilato, petis la korpon de Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'Kaj li deprenis ĝin kaj envolvis ĝin en tolaĵo, kaj metis lin en tombo, elhakita el ŝtono, kie neniu antaŭe kuŝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'Kaj estis la tago de la Preparado, kaj la sabato eklumis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Kaj la virinoj, kiuj venis kun li el Galileo, sekvis, kaj vidis la tombon, kaj kiamaniere la korpo estis metita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'Kaj ili reiris, kaj preparis aromaĵojn kaj ŝmiraĵojn. Kaj sabate ili ripozis laŭ la ordono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'Kaj la unuan tagon de la semajno, ĉe frua tagiĝo, ili venis al la tombo, alportante la aromaĵojn, kiujn ili preparis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'Kaj ili trovis la ŝtonon derulita for de la tombo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'Kaj enirinte, ili ne trovis la korpon de la Sinjoro Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'Kaj dum ili embarasiĝis pri tio, jen apud ili staris du viroj en brilaj vestoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'kaj dum ili timis kaj kliniĝis vizaĝaltere, tiuj demandis ilin: Kial vi serĉas la vivanton inter la mortintoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Li ne estas ĉi tie, sed leviĝis; memoru, kiamaniere li parolis al vi, kiam li estis ankoraŭ en Galileo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'dirante, ke la Filo de homo devas esti transdonita en la manojn de pekuloj kaj esti krucumita, kaj la trian tagon releviĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'Kaj ili rememoris liajn vortojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'kaj reveninte de la tombo, ili rakontis ĉion tion al la dek unu kaj al ĉiuj ceteraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'Kaj ili estis Maria Magdalena, kaj Joana, kaj Maria, la patrino de Jakobo; kaj la ceteraj virinoj kun ili rakontis tion al la apostoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'Kaj tiuj vortoj ŝajnis al ili kiel babilado, kaj ili ne kredis al la virinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Sed Petro leviĝis kaj kuris al la tombo, kaj kliniĝinte, vidis la tolaĵojn solajn, kaj li foriris, mirante en si pri tio, kio okazis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'Kaj jen du el ili iris en tiu sama tago al vilaĝo nomata Emaus, kiu estas malproksime de Jerusalem sesdek stadiojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'Kaj ili interparolis inter si pri ĉio tio, kio okazis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'Kaj dum ili interparolis kaj diskutis inter si, Jesuo mem alproksimiĝis kaj iris kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Sed iliaj okuloj estis malhelpataj tiel, ke ili lin ne rekonis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'Kaj li diris al ili: Kiaj vortoj estas tiuj, kiujn vi interŝanĝas, dum vi iras? Kaj ili haltis, kun malgaja mieno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'Kaj unu el ili, nomata Kleopas, responde diris al li: Ĉu nur vi sola loĝas en Jerusalem, kaj ne scias tion, kio tie okazis en ĉi tiuj tagoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'Kaj li diris al ili: Kion? Kaj ili diris al li: Pri Jesuo, la Nazaretano, kiu estis profeto potenca age kaj parole antaŭ Dio kaj la tuta popolo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'kaj kiel la ĉefpastroj kaj niaj regantoj transdonis lin por kondamno al morto, kaj lin krucumis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'Sed ni esperis, ke li estas tiu, kiu elaĉetos Izraelon. Kaj plie, krom ĉio tio, hodiaŭ estas jam la tria tago, de kiam tio okazis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Ankaŭ mirigis nin iuj virinoj el inter ni, kiuj estis frumatene apud la tombo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'kaj ne trovinte lian korpon, revenis, dirante, ke ili ankaŭ vidis vizion de anĝeloj, kiuj diris, ke li vivas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'Kaj iuj el nia kunularo iris al la tombo, kaj trovis tiel, kiel diris la virinoj; sed lin ili ne vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'Kaj li diris al ili: Ho malsaĝuloj kaj kore malviglaj por kredi ĉion, kion la profetoj antaŭparolis!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Ĉu la Kristo ne devis suferi ĉion tion, kaj eniri en sian gloron?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'Kaj komencante de Moseo kaj de ĉiuj profetoj, li klarigis al ili el ĉiuj Skriboj la dirojn pri li mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'Kaj ili alproksimiĝis al la vilaĝo, kien ili iris, kaj li ŝajnigis al ili, kvazaŭ li pluen iros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'Kaj ili retenis lin, dirante: Restu ĉe ni, ĉar estas preskaŭ vespere, kaj la tago jam malkreskas. Kaj li eniris, por resti ĉe ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'Kaj dum li sidis kun ili ĉe manĝo, li prenis panon, kaj ĝin benis kaj dispecigis kaj donis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'Kaj iliaj okuloj malfermiĝis, kaj ili rekonis lin, kaj li fariĝis nevidebla por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'Kaj ili diris unu al alia: Ĉu nia koro ne brulis en ni, dum li parolis kun ni sur la vojo, dum li klarigis al ni la Skribojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'Kaj leviĝinte en tiu sama horo, ili reiris al Jerusalem, kaj trovis la dek unu kunvenintaj, kun siaj kunuloj, kaj dirantaj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'La Sinjoro vere leviĝis, kaj aperis al Simon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'Kaj ili rakontis tion, kio okazis sur la vojo, kaj kiamaniere li rekoniĝis al ili en la dispecigo de pano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'Kaj dum ili priparolis tion, li mem staris meze de ili, kaj diris al ili: Paco al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Sed terurite kaj timigite, ili supozis, ke ili vidas spiriton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'Kaj li diris al ili: Kial vi maltrankviliĝas? kaj kial diskutoj leviĝas en viaj koroj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Vidu miajn manojn kaj miajn piedojn, ke ĝi estas mi mem; palpu min kaj vidu; ĉar spirito ne havas karnon kaj ostojn, kiel vi vidas min havanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'Kaj tion dirinte, li montris al ili siajn manojn kaj siajn piedojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Kaj dum ili ankoraŭ ne kredis pro ĝojo, kaj miris, li demandis ilin: Ĉu vi havas ian manĝaĵon ĉi tie?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Kaj ili donis al li pecon de rostita fiŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'Kaj li prenis, kaj manĝis antaŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'Kaj li diris al ili: Jen estas miaj vortoj, kiujn mi parolis al vi, kiam mi ankoraŭ estis ĉe vi, ke devas plenumiĝi ĉio, kio estas skribita pri mi en la leĝo de Moseo kaj en la profetoj kaj en la psalmoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Tiam li malfermis ilian menson, por ke ili komprenu la Skribojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'kaj li diris al ili: Tiel estas skribite, ke la Kristo devas suferi, kaj leviĝi el la mortintoj la trian tagon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'kaj ke pento kaj pardonado de pekoj estu predikataj en lia nomo al ĉiuj nacioj, komencante ĉe Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'Vi estas atestantoj pri tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'Kaj jen mi elsendos sur vin la promeson de mia Patro; sed restu en la urbo, ĝis vi vestiĝos per potenco de supre.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'Kaj li elkondukis ilin ĝis apud Betania, kaj, levinte siajn manojn, li benis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'Kaj dum li benis ilin, li foriĝis de ili kaj estis suprenportita en la ĉielon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'Kaj adorkliniĝinte al li, ili revenis al Jerusalem kun granda ĝojo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'kaj estis konstante en la templo, glorante Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'En la komenco estis la Vorto, kaj la Vorto estis kun Dio, kaj la Vorto estis Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Tiu estis en la komenco kun Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Ĉio estiĝis per li; kaj aparte de li estiĝis nenio, kio estiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'En li estis la vivo, kaj la vivo estis la lumo de la homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'Kaj la lumo brilas en la mallumo, kaj la mallumo ĝin ne venkis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'De Dio estis sendita viro, kies nomo estis Johano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Tiu venis kiel atestanto, por atesti pri la lumo, por ke ĉiuj per li kredu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Li ne estis la lumo, sed li venis, por atesti pri la lumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Tio estis la vera lumo, kiu lumas al ĉiu homo, venanta en la mondon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Tiu estis en la mondo, kaj la mondo per li estiĝis, kaj la mondo lin ne konis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Li venis al siaj propraĵoj, kaj liaj propruloj lin ne akceptis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Sed al ĉiuj, kiuj lin akceptis, li donis la rajton fariĝi filoj de Dio, al la kredantoj al lia nomo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'kiuj naskiĝis nek el sango, nek el volo de karno, nek el volo de homo, sed el Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Kaj la Vorto fariĝis karno kaj loĝis inter ni, kaj ni vidis lian gloron, gloron kvazaŭ de la solenaskita de la Patro, plena de graco kaj vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Johano atestis pri li, kaj kriis, dirante: Ĉi tiu estas li, pri kiu mi diris: Kiu venas post mi, tiu estas metita super mi, ĉar li ekzistis pli frue ol mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'Ĉar el lia pleneco ni ĉiuj ricevis, kaj gracon post graco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Ĉar la leĝo estis donita per Moseo; la graco kaj la vero estiĝis per Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Neniu iam vidis Dion; la solenaskita Filo, kiu estas en la sino de la Patro, Lin deklaris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'Kaj jen estas la atesto de Johano, kiam la Judoj sendis al li pastrojn kaj Levidojn el Jerusalem, por demandi lin: Kiu vi estas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'Kaj li konfesis kaj ne kaŝis; kaj li konfesis: Mi ne estas la Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'Kaj ili demandis lin: Kio do? Ĉu vi estas Elija? Kaj li diris: Mi ne estas. Ĉu vi estas la profeto? Kaj li respondis: Ne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Ili do diris al li: Kiu vi estas? por ke ni donu respondon al niaj sendintoj. Kion vi diras pri vi mem?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Li diris: Mi estas voĉo de krianto en la dezerto: Rektigu la vojon de la Eternulo, kiel diris la profeto Jesaja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'Kaj tiuj estis senditaj de la Fariseoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'Kaj ili demandis lin, kaj diris al li: Kial do vi baptas, se vi ne estas la Kristo, nek Elija, nek la profeto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Johano respondis al ili, dirante: Mi baptas per akvo; meze de vi staras tiu, kiun vi ne konas,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'kiu venas post mi; la rimenon de lia ŝuo mi ne estas inda malligi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Tio okazis en Betania transe de Jordan, kie Johano baptadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'La sekvantan tagon li vidis Jesuon venanta al li, kaj diris: Jen la Ŝafido de Dio, kiu forportas la pekon de la mondo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'Li estas tiu, pri kiu mi diris: Post mi venas viro, kiu estas metita super mi, ĉar li ekzistis pli frue ol mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'Kaj mi lin ne konis; sed por ke li estu montrita al Izrael, tial mi venis, baptante per akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'Kaj Johano atestis, dirante: Mi vidis la Spiriton malsupreniranta de la ĉielo kiel kolombo, kaj ĝi restis sur li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'Kaj mi lin ne konis; sed kiu sendis min por bapti per akvo, Tiu diris al mi: Sur kiun vi vidos la Spiriton malsupreniranta kaj restanta sur li, tiu estas la baptanto per la Sankta Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'Kaj mi vidis, kaj atestis, ke ĉi tiu estas la Filo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Denove la sekvantan tagon staris Johano, kaj du el liaj disĉiploj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'kaj rigardante Jesuon promenantan, li diris: Jen la Ŝafido de Dio!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'Kaj la du disĉiploj aŭdis lin paroli, kaj sekvis Jesuon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Kaj Jesuo sin turnis, kaj vidis ilin sekvantajn, kaj diris al ili: Kion vi serĉas? Kaj ili diris al li: Rabeno (tio estas, Majstro), kie vi loĝas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Li diris al ili: Venu, kaj vi vidos. Ili do venis, kaj vidis, kie li loĝas, kaj ili restis ĉe li tiun tagon; estis ĉirkaŭ la deka horo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'Unu el la du, kiuj aŭdis Johanon kaj lin sekvis, estis Andreo, la frato de Simon Petro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Tiu unue trovis sian propran fraton Simon, kaj diris al li: Ni trovis la Mesion (tio estas, Kriston).');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'Li kondukis lin al Jesuo. Jesuo lin rigardis, kaj diris: Vi estas Simon, filo de Jona; vi estos nomata Kefas (tio estas, Petro).');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'La sekvantan tagon li volis foriri en Galileon, kaj trovis Filipon; kaj Jesuo diris al li: Sekvu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'Filipo estis el Betsaida, la urbo de Andreo kaj Petro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Filipo trovis Natanaelon, kaj diris al li: Ni trovis tiun, pri kiu skribis Moseo en la leĝo, kaj la profetoj, Jesuon el Nazaret, filon de Jozef.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Kaj Natanael diris al li: Ĉu io bona povas esti el Nazaret? Filipo diris al li: Venu kaj vidu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Jesuo vidis Natanaelon venanta al li, kaj diris pri li: Jen vera Izraelido, en kiu ne estas ruzeco!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Natanael diris al li: Per kio vi min konas? Jesuo respondis kaj diris al li: Antaŭ ol Filipo vin vokis, kiam vi estis sub la figarbo, mi vin vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Natanael respondis kaj diris al li: Rabeno, vi estas la Filo de Dio; vi estas Reĝo de Izrael!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Jesuo respondis kaj diris al li: Ĉu vi kredas pro tio, ke mi diris al vi: Mi vin vidis sub la figarbo? vi vidos pli grandajn aferojn ol ĉi tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'Kaj li diris al li: Vere, vere, mi diras al vi, vi vidos la ĉielon malfermita kaj la anĝelojn de Dio suprenirantaj kaj malsuprenirantaj sur la Filon de homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'La trian tagon okazis edziĝo en Kana Galilea, kaj la patrino de Jesuo ĉeestis tie;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'ankaŭ Jesuo kaj liaj disĉiploj estis invititaj al la edziĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Kaj kiam mankis vino, la patrino de Jesuo diris al li: Ili ne havas vinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Kaj Jesuo diris al ŝi: Kio estas inter mi kaj vi, virino? mia horo ankoraŭ ne venis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Lia patrino diris al la servantoj: Kion ajn li diros al vi, tion faru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Kaj estis tie ses akvokuvoj ŝtonaj, metitaj laŭ la purigo de la Judoj, enhavantaj po du ĝis tri metretoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Jesuo diris al ili: Plenigu la akvokuvojn per akvo. Kaj oni plenigis ilin ĝis la rando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Kaj li diris al ili: Ĉerpu nun, kaj alportu al la festenestro. Kaj oni alportis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Kiam la festenestro gustumis la akvon, nun fariĝintan vino, kaj ne sciis, de kie ĝi estas (sciis tamen la servantoj, kiuj ĉerpis la akvon), la festenestro alvokis la fianĉon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'kaj diris al li: Ĉiu homo prezentas unue la bonan vinon, kaj kiam oni jam drinkis, tiam la malpli bonan; sed vi rezervis la bonan vinon ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Ĉi tiun komencon de signoj Jesuo faris en Kana Galilea, kaj elmontris sian gloron, kaj liaj disĉiploj kredis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Post tio li malsupreniris al Kapernaum, kaj kun li lia patrino kaj liaj fratoj kaj liaj disĉiploj; kaj tie ili restis ne multajn tagojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Kaj la Pasko de la Judoj alproksimiĝis, kaj Jesuo supreniris al Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'Kaj li trovis en la templo vendistojn de bovoj kaj ŝafoj kaj kolomboj, kaj la monŝanĝistojn sidantajn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'kaj farinte skurĝon el ŝnuretoj, li elpelis ĉiujn el la templo, ŝafojn kaj bovojn; kaj elŝutis la monerojn de la monŝanĝistoj kaj renversis la tablojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'kaj al la vendistoj de la kolomboj li diris: Forportu tion de ĉi tie; ne faru la domon de mia Patro domo de komerco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'La disĉiploj rememoris, ke estis skribite: Fervoro pri Via domo min konsumis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'La Judoj do respondis kaj diris al li: Kian signon vi montras al ni, ĉar vi faras tion?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Respondis Jesuo kaj diris al ili: Detruu ĉi tiun sanktejon, kaj mi levos ĝin en la daŭro de tri tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'La Judoj diris: Kvardek ses jarojn ĉi tiu sanktejo estis konstruata; ĉu vi levos ĝin en la daŭro de tri tagoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Sed li parolis pri la sanktejo de sia korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Kiam do li leviĝis el la mortintoj, la disĉiploj rememoris, ke li diris tion; kaj ili kredis la Skribon, kaj la vorton, kiun Jesuo diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Kaj kiam li estis en Jerusalem ĉe la Pasko, dum la festo, multaj fidis al lia nomo, vidante la signojn, kiujn li faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Sed Jesuo ne konfidis sin al ili, ĉar li konis ĉiujn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'kaj ne bezonis, ke iu atestu pri la homo, ĉar li mem sciis, kio estas en la homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Estis viro el la Fariseoj, nomata Nikodemo, ĉefo inter la Judoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'tiu venis al li nokte, kaj diris al li: Rabeno, ni scias, ke vi estas instruisto, veninta de Dio; ĉar neniu povas fari tiujn signojn, kiujn vi faras, se Dio ne estas kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Jesuo respondis kaj diris al li: Vere, vere, mi diras al vi: Se homo ne estas denove naskita, li ne povas vidi la regnon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Nikodemo diris al li: Kiel povas homo naskiĝi, kiam li estas maljuna? ĉu li povas eniri denove en la ventron de sia patrino kaj naskiĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Jesuo respondis: Vere, vere, mi diras al vi: Se homo ne estas naskita el akvo kaj la Spirito, li ne povas eniri en la regnon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Tio, kio naskiĝas el la karno, estas karno; kaj tio, kio naskiĝas de la Spirito, estas spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Ne miru, ke mi diris al vi: Vi devas esti denove naskitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'La vento blovas, kie ĝi volas, kaj ĝian voĉon vi aŭdas, sed vi ne scias, de kie ĝi venas kaj kien ĝi iras; tia estas ĉiu, kiu estas naskita de la Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Nikodemo respondis kaj diris al li: Kiel povas tio fariĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Jesuo respondis kaj diris al li: Vi estas la instruisto de Izrael, kaj ĉu vi ne scias tion?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Vere, vere, mi diras al vi: Kion ni scias, tion ni parolas, kaj kion ni vidis, tion ni atestas; kaj vi homoj ne akceptas nian ateston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Se mi aferojn surterajn diris al vi, kaj vi ne kredas, kiel vi kredos, se mi diros enĉielajn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Kaj neniu supreniris en la ĉielon, krom tiu, kiu malsupreniris de la ĉielo, la Filo de homo, kiu estas en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Kaj kiel Moseo levis la serpenton en la dezerto, tiel devas la Filo de homo esti levita;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'por ke ĉiu, fidanta al li, havu eternan vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Ĉar Dio tiel amis la mondon, ke Li donis Sian solenaskitan Filon, por ke ĉiu, kiu fidas al li, ne pereu, sed havu eternan vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Ĉar Dio sendis Sian Filon en la mondon, ne por juĝi la mondon, sed por ke la mondo per li estu savita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Kiu fidas al li, tiu ne estas juĝata; sed la nekredanto jam estas juĝita, ĉar li ne fidas al la nomo de la solenaskita Filo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Kaj jen estas la juĝo: ke la lumo venis en la mondon, kaj la homoj amis la mallumon pli ol la lumon, ĉar iliaj faroj estis malbonaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Ĉar ĉiu, kiu faradas malbonon, malamas la lumon, kaj ne venas al la lumo, por ke liaj faroj ne estu malaprobitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Sed tiu, kiu faras la veron, venas al la lumo, por ke liaj faroj estu montrataj, ke ili estas faritaj en Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Post tio venis Jesuo kun siaj disĉiploj en la landon Judujo, kaj restis tie kun ili kaj baptadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Johano ankaŭ baptadis en Enon, proksime de Salim, ĉar estis tie multe da akvoj; kaj oni alvenis kaj estis baptitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Ĉar Johano ankoraŭ ne estis ĵetita en malliberejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Fariĝis do diskutado inter la disĉiploj de Johano kaj iu Judo pri la puriĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'Kaj ili venis al Johano, kaj diris al li: Rabeno, tiu, kiu estis kun vi transe de Jordan, kaj pri kiu vi atestis, jen tiu sama baptas, kaj ĉiuj venas al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Johano respondis kaj diris: Homo ne povas ion ricevi, se ĝi ne estas donita al li el la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Vi mem atestas pri mi, ke mi diris: Mi ne estas la Kristo, sed mi estas sendita antaŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Kiu havas la fianĉinon, tiu estas la fianĉo; sed la amiko de la fianĉo, kiu staras kaj lin aŭdas, tre ĝojas pro la voĉo de la fianĉo; ĉi tiu mia ĝojo do plenumiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'Li devas altiĝi, sed mi devas malaltiĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Kiu de supre venas, tiu estas super ĉiuj; kiu estas el la tero, tiu el la tero estas, kaj el la tero parolas; kiu venas de la ĉielo, tiu estas super ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'Kion li vidis kaj aŭdis, tion li atestas; kaj neniu akceptas lian ateston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Kiu akceptis lian ateston, tiu jam sigelis, ke Dio estas vera.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Ĉar tiu, kiun Dio sendis, parolas la vortojn de Dio; ĉar ne laŭmezure Li donas la Spiriton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'La Patro amas la Filon, kaj donis ĉion en lian manon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Kiu fidas al la Filo, tiu havas eternan vivon; sed kiu ne obeas al la Filo, tiu ne vidos vivon, sed la kolero de Dio sur li restas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Kiam do la Sinjoro sciis, ke la Fariseoj aŭdis, ke Jesuo faras kaj baptas pli multe da disĉiploj, ol Johano');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(kvankam baptadis ne Jesuo mem, sed liaj disĉiploj),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'li foriris el Judujo kaj reiris al Galileo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Kaj li devis trairi tra Samario.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Li alvenis do al unu urbo Samaria, nomata Siĥar, apud la terpeco, kiun Jakob donis al sia filo Jozef;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'kaj la fonto de Jakob estis tie. Jesuo do, lacigita de sia vojirado, sidiĝis tiamaniere apud la fonto. Estis ĉirkaŭ la sesa horo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Venis virino Samaria, por ĉerpi akvon; Jesuo diris al ŝi: Donu al mi trinki.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'Ĉar liaj disĉiploj jam foriris en la urbon, por aĉeti nutraĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'La Samarianino do diris al li: Kiel vi, estante Judo, petas trinki de mi, kiu estas Samarianino? (Ĉar la Judoj ne interrilatas kun la Samarianoj.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Jesuo respondis kaj diris al ŝi: Se vi scius la donacon de Dio, kaj kiu estas tiu, kiu diras al vi: Donu al mi trinki, vi petus lin, kaj li donus al vi vivan akvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'La virino diris al li: Sinjoro, vi nenian ĉerpilon havas, kaj la puto estas profunda; de kie do vi havas tiun vivan akvon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Ĉu vi estas pli granda ol nia patro Jakob, kiu donis al ni la puton, kaj trinkis mem el ĝi, kiel ankaŭ liaj filoj kaj liaj brutoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Jesuo respondis kaj diris al ŝi: Ĉiu, kiu trinkas el ĉi tiu akvo, denove soifos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'sed kiu trinkos el la akvo, kiun mi donos al li, tiu neniam soifos; sed la akvo, kiun mi donos al li, fariĝos en li fonto de akvo, ŝprucanta supren por eterna vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'La virino diris al li: Sinjoro, donu al mi ĉi tiun akvon, por ke mi ne plu soifu, kaj ne devu traveni ĉi tien, por ĉerpi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Jesuo diris al ŝi: Foriru, voku vian edzon, kaj revenu ĉi tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'La virino respondis kaj diris al li: Mi ne havas edzon. Jesuo diris al ŝi: Vi prave diris: Mi ne havas edzon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'ĉar vi havis kvin edzojn; kaj tiu, kiun vi nun havas, ne estas via edzo; ĉi tion vi diris vere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'La virino diris al li: Sinjoro, mi ekvidas, ke vi estas profeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Niaj patroj adoradis sur ĉi tiu monto; kaj vi diras, ke en Jerusalem estas la loko, kie oni devas adori.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Jesuo diris al ŝi: Kredu al mi, virino; venas la horo, kiam nek sur ĉi tiu monto, nek en Jerusalem, vi adoros la Patron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Vi adoras tion, kion vi ne konas; ni adoras tion, kion ni konas; ĉar el la Judoj estas la savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Sed venas la horo, kaj jam estas, kiam la veraj adorantoj adoros la Patron laŭ spirito kaj vero; ĉar la Patro serĉas tiajn por esti Liaj adorantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Dio estas Spirito: kaj Liaj adorantoj devas adori Lin laŭ spirito kaj vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'La virino diris al li: Mi scias, ke venas la Mesio (kiu estas nomata Kristo); kiam tiu alestos, li anoncos al ni ĉion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Jesuo diris al ŝi: Tiu estas mi, kiu parolas kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'Kaj ĉe tio venis liaj disĉiploj, kaj ili miris, ke li parolas kun virino; tamen neniu diris: Kion vi volas? aŭ: Kial vi parolas kun ŝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'La virino do lasis sian akvokruĉon, kaj foriris en la urbon, kaj diris al la homoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, 'Venu, vidu homon, kiu rakontis al mi ĉion, kion mi faris; ĉu eble ĉi tiu estas la Kristo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Ili eliris el la urbo, kaj venis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Dume la disĉiploj petis lin, dirante: Rabeno, manĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Sed li diris al ili: Por manĝi mi havas nutraĵon, pri kiu vi ne scias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'La disĉiploj do diris inter si: Ĉu iu alportis al li ion por manĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Jesuo diris al ili: Mia nutraĵo estas plenumi la volon de Tiu, kiu min sendis, kaj fini Lian laboron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Ĉu vi ne diras: Estas ankoraŭ kvar monatoj, kaj venas la rikolto? jen mi diras al vi: Levu viajn okulojn kaj rigardu la kampojn, ke ili jam estas blankaj por la rikolto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'La rikoltanto ricevas salajron, kaj kolektas frukton por eterna vivo, por ke ĝoju kune la semanto kaj la rikoltanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Ĉar en ĉi tio estas vera la proverbo: Unu semas, alia rikoltas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Mi vin sendis, por rikolti tion, kion vi ne prilaboris; aliaj laboris, kaj vi eniris en ilian laboron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Kaj el tiu urbo multaj el la Samarianoj kredis al li pro la diro de la virino, kiu atestis: Li rakontis al mi ĉion, kion mi faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Kiam do la Samarianoj venis al li, ili petis, ke li restu ĉe ili; kaj li restis tie du tagojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'Kaj multe pli multaj kredis pro lia vorto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'kaj diris al la virino: Jam ne pro via diro ni kredas, ĉar ni mem aŭdis lin; kaj ni scias, ke ĉi tiu estas vere la Savanto de la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Kaj post la du tagoj li foriris de tie en Galileon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'Ĉar Jesuo mem atestis, ke profeto ne havas honoron en sia propra lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Kiam do li venis en Galileon, la Galileanoj akceptis lin, ĉar ili jam vidis ĉion, kion li faris en Jerusalem dum la festo; ĉar ili ankaŭ iris al la festo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Li revenis en Kanan Galilean, kie li faris la akvon vino. Kaj estis unu kortegano, kies filo estis malsana en Kapernaum.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Kiam li aŭdis, ke Jesuo alvenis el Judujo en Galileon, li iris al li, kaj petis lin malsupreniri kaj resanigi lian filon; ĉar li preskaŭ mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Jesuo do diris al li: Se vi ne vidas signojn kaj mirindaĵojn, vi tute ne kredos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'La kortegano diris al li: Sinjoro, malsupreniru, antaŭ ol mia fileto mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Jesuo diris al li: Foriru, via filo vivas. La viro kredis la vorton, kiun Jesuo parolis al li, kaj li foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Dum li ankoraŭ malsupreniris, liaj sklavoj lin renkontis, dirante: Via filo vivas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Li demandis al ili pri la horo, kiam li ekresaniĝis. Ili respondis al li: Hieraŭ je la sepa horo la febro lin forlasis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Tial la patro sciis, ke tio estis en tiu sama horo, en kiu Jesuo diris al li: Via filo vivas; kaj kredis li mem kaj lia tuta domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Ĉi tiun jam la duan signon faris Jesuo, veninte el Judujo en Galileon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Post tio estis festo de la Judoj, kaj Jesuo supreniris al Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'En Jerusalem apud la Pordego de Ŝafoj estas lageto, nomata en la Hebrea lingvo Betesda, havanta kvin portikojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'En tiuj kuŝis amaso da malsanuloj, blinduloj, lamuloj, velkintoj, kiuj atendis la ekmovon de la akvo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'ĉar anĝelo de la Eternulo malsupreniris iafoje en la lageton kaj movis la akvon; kiu ajn do unua post la movado de la akvo enpaŝis, tiu resaniĝis, tute egale, de kia malsano li suferis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Kaj tie estis unu viro, kiu estis tridek ok jarojn en sia malforteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Kiam Jesuo vidis lin kuŝantan, kaj sciis, ke li jam de longe malsanas, li diris al li: Ĉu vi volas fariĝi sana?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'La malsanulo respondis: Sinjoro, mi ne havas iun por enĵeti min en la lageton, kiam la akvo moviĝis; sed dum mi venas, alia paŝas malsupren antaŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Jesuo diris al li: Leviĝu, prenu vian liton, kaj iru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Kaj la viro tuj fariĝis sana, kaj prenis sian liton, kaj iris. Kaj estis la sabato en tiu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'La Judoj do diris al la resanigito: Estas la sabato, kaj al vi ne konvenas porti vian liton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Li respondis: Tiu, kiu min sanigis, diris al mi: Prenu vian liton, kaj iru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Ili demandis lin: Kiu estas tiu homo, kiu diris al vi: Prenu kaj iru?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Sed la resanigito ne sciis, kiu tiu estas; ĉar Jesuo jam formoviĝis pro la tiea homamaso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Poste Jesuo trovis lin en la templo, kaj diris al li: Jen vi fariĝis sana; ne plu peku, por ke io pli malbona ne okazu al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'La viro foriris, kaj diris al la Judoj, ke Jesuo estas tiu, kiu lin sanigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'Kaj la Judoj persekutis Jesuon pro tio, ke li tion faris en sabato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Sed Jesuo respondis al ili: Mia Patro ĝis nun laboras, kaj mi laboras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Pro tio do la Judoj des pli celis mortigi lin, pro tio, ke li ne nur malobservis la sabaton, sed ankaŭ diris, ke Dio estas lia propra Patro, kaj pretendis esti egala al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Jesuo do respondis kaj diris al ili: Vere, vere, mi diras al vi: La Filo ne povas per si mem fari ion, krom tio, kion li vidas la Patron faranta; ĉar kion ajn Li faras, tion la Filo tiel same ankaŭ faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Ĉar la Patro amas la Filon, kaj montras al li ĉion, kion Li mem faras; kaj Li montros al li farojn pli grandajn ol ĉi tio, por ke vi miru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Ĉar kiel la Patro levas la mortintojn kaj ilin vivigas, tiel ankaŭ la Filo vivigas tiujn, kiujn li volas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Ĉar la Patro juĝas neniun, sed Li donis ĉian juĝon al la Filo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'por ke ĉiuj honoru la Filon tiel same, kiel ili honoras la Patron. Kiu ne honoras la Filon, tiu ne honoras la Patron, kiu lin sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Vere, vere, mi diras al vi: Kiu aŭskultas mian vorton, kaj kredas al Tiu, kiu min sendis, tiu havas eternan vivon kaj ne venas en juĝon, sed jam pasis de morto en vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Vere, vere, mi diras al vi: Venas horo kaj jam estas, kiam la mortintoj aŭdos la voĉon de la Filo de Dio; kaj la aŭdintoj vivos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Ĉar kiel la Patro havas en Si mem vivon, tiel Li donis al la Filo ankaŭ, ke ĉi tiu havu en si mem vivon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'kaj Li donis al li la rajton fari juĝon, ĉar li estas la Filo de homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Ne miru pro tio; ĉar venas horo, en kiu ĉiuj, kiuj estas en la tomboj, aŭdos lian voĉon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'kaj eliros; la farintoj de bono, al releviĝo por vivo; sed la farintoj de malbono, al releviĝo por juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Mi ne povas per mi mem fari ion; kiel mi aŭdas, tiel mi juĝas; kaj mia juĝo estas justa, ĉar mi celas ne mian propran volon, sed la volon de Tiu, kiu min sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Se mi atestus pri mi mem, mia atesto ne estus vera.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Estas alia, kiu atestas pri mi; kaj mi scias, ke vera estas la atesto, kiun li atestas pri mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Vi sendis al Johano, kaj li atestis pri la vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Sed la atesto, kiun mi ricevas, ne estas el homo, tamen mi tion diras, por ke vi estu savitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Li estis la lampo, kiu brulas kaj lumas; kaj vi volis ĝoji kelkan tempon en lia lumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Sed la atesto, kiun mi havas, estas pli granda ol la atesto de Johano; ĉar la laboroj, kiujn la Patro donis al mi por fini, tiuj samaj laboroj, kiujn mi faras, atestas pri mi, ke la Patro min sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'Kaj la Patro, kiu min sendis, atestis pri mi. Vi nek aŭdis iam Lian voĉon, nek vidis Lian formon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'Kaj vi ne havas Lian vorton restantan en vi, ĉar vi ne kredas al tiu, kiun Li sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Vi esploras la Skribojn, ĉar vi opinias, ke en ili vi havas eternan vivon; kaj ili estas tio, kio atestas pri mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'kaj vi ne volas veni al mi, por havi vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'De homoj mi ne prenas gloron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'Sed mi vin scias, ke vi ne havas en vi la amon al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Mi venis en la nomo de mia Patro, kaj vi min ne akceptas; se alia venos en sia propra nomo, vi lin akceptos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Kiel povas kredi vi, kiuj prenas gloron unu de alia, kaj la gloron, kiu venas de la sola Dio, vi ne serĉas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Ne pensu, ke mi akuzos vin antaŭ la Patro; ekzistas unu, kiu akuzas vin, Moseo, al kiu vi esperas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Ĉar se vi kredus al Moseo, vi ankaŭ kredus al mi, ĉar li skribis pri mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Sed se vi ne kredas liajn skribojn, kiel vi kredos miajn vortojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Poste Jesuo foriris trans la maron de Galileo, tio estas de Tiberias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'Kaj granda homamaso lin sekvis, ĉar ili vidis la signojn, kiujn li faris por la malsanuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Kaj Jesuo supreniris sur la monton, kaj tie li sidis kun siaj disĉiploj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Kaj la Pasko, la festo de la Judoj, estis proksima.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Jesuo do, levinte siajn okulojn, kaj ekvidinte, ke granda homamaso venas al li, diris al Filipo: De kie ni aĉetu panojn, por ke ĉi tiuj manĝu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Tion li diris, por provi lin; ĉar li mem sciis, kion li faros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Filipo respondis al li: Panoj por ducent denaroj ne sufiĉus por ili, por ke ĉiu iometon ricevu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Unu el liaj disĉiploj, Andreo, frato de Simon Petro, diris al li:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Ĉi tie estas knabo, kiu havas kvin hordeajn panojn kaj du malgrandajn fiŝojn; sed kio estas tio por tiom da homoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Jesuo diris: Sidigu la homojn. Kaj estis tie multe da herbo. La viroj do sidiĝis, nombre ĉirkaŭ kvin mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Kaj Jesuo prenis la panojn, kaj doninte dankon, disdonis al la sidiĝintoj; kaj tiel same el la fiŝoj tiom, kiom oni deziris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Kaj kiam ili satiĝis, li diris al siaj disĉiploj: Kolektu la postrestantajn fragmentojn, por ke nenio perdiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Ili do kolektis ilin, kaj plenigis dek du korbojn per la fragmentoj de la kvin hordeaj panoj, kiuj postrestis al la manĝintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Kiam do la homoj vidis la signon, kiun Jesuo faris, ili diris: Ĉi tiu estas vere la profeto, kiu devis veni en la mondon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Tial Jesuo, eksciante, ke oni celas veni kaj kapti lin, por fari lin reĝo, denove fortiris sin sola al la monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Kaj kiam vesperiĝis, liaj disĉiploj malsupreniris al la maro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'kaj enŝipiĝinte, ili veturis trans la maron al Kapernaum. Kaj jam estis mallume, kaj Jesuo ankoraŭ ne venis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'Kaj la maro malsereniĝis de forta vento, kiu blovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Kiam do ili remis proksimume dudek kvin ĝis tridek stadiojn, ili ekvidis Jesuon iranta sur la akvo, kaj proksimiĝanta al la ŝipo; kaj ili timis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Sed li diris al ili: Ĝi estas mi; ne timu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Tiam ili volonte ricevis lin en la ŝipon, kaj tuj la ŝipo albordiĝis tien, kien ili veturis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'La sekvantan tagon, kiam la homamaso, kiu restis trans la maro, vidis, ke nenia ŝipeto estas tie krom unu, kaj ke Jesuo ne eniris kun la disĉiploj en la ŝipon, sed la disĉiploj solaj veturis');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, '(venis tamen ŝipetoj el Tiberias proksime al la loko, kie oni manĝis la panon, post kiam la Sinjoro donis dankon) -');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'kiam do la homamaso vidis, ke Jesuo ne estas tie, nek liaj disĉiploj, ili ankaŭ eniris la ŝipetojn kaj veturis al Kapernaum, serĉante Jesuon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'Kaj trovinte lin trans la maro, ili diris al li: Rabeno, kiam vi venis ĉi tien?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Jesuo respondis al ili kaj diris: Vere, vere, mi diras al vi: Vi min serĉas, ne ĉar vi vidis signojn, sed ĉar vi manĝis el la panoj kaj satiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Laboru ne por la pereema nutraĵo, sed por la nutraĵo, kiu restas ĝis eterna vivo, kiun la Filo de homo donos al vi; ĉar lin Dio, la Patro, sigelis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Ili do diris al li: Kiel ni agu, por ke ni faru la farojn de Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Jesuo respondis kaj diris al ili: Jen la faro de Dio: kredi al tiu, kiun Li sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Ili do diris al li: Kian signon vi montras, por ke ni vidu kaj kredu al vi? kion vi faras?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Niaj patroj manĝis la manaon en la dezerto, kiel estas skribite: Li donis al ili ĉielan panon por manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Jesuo do diris al ili: Vere, vere, mi diras al vi: Ne Moseo donis al vi tiun ĉielan panon; sed mia Patro donas al vi la veran ĉielan panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Ĉar la pano de Dio estas tiu, kiu malsupreniras de la ĉielo kaj donas vivon al la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Ili do diris al li: Sinjoro, ĉiam donu al ni tiun panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Jesuo diris al ili: Mi estas la pano de vivo; kiu venas al mi, tiu neniam malsatos, kaj kiu kredas al mi, tiu neniam soifos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Sed mi diris al vi, ke vi min vidis, kaj tamen vi ne kredas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Ĉio, kion la Patro donas al mi, venos al mi; kaj tiun, kiu venas al mi, mi ja ne elĵetos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Ĉar mi malsupreniris de la ĉielo, por plenumi ne mian volon, sed la volon de Tiu, kiu min sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'Kaj estas la volo de Tiu, kiu min sendis, ke el ĉio, kion Li donis al mi, mi ne perdu ion, sed relevu ĝin en la lasta tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'Ĉar estas la volo de mia Patro, ke ĉiu, kiu vidas la Filon kaj kredas al li, havu eternan vivon; kaj mi levos tiun en la lasta tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'La Judoj do murmuris pri li, ĉar li diris: Mi estas la pano, kiu malsupreniris de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'Kaj ili diris: Ĉu ĉi tiu ne estas Jesuo, filo de Jozef, kies patron kaj patrinon ni konas? kiel do li diras: Mi malsupreniris de la ĉielo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Jesuo respondis kaj diris al ili: Ne murmuru inter vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Neniu povas veni al mi, se la Patro, kiu min sendis, ne tiros lin; kaj mi levos tiun en la lasta tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Estas skribite en la profetoj: Kaj ĉiuj estos instruitaj de Dio. Ĉiu do, kiu aŭdis de la Patro kaj lernis, venas al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Neniu vidis la Patron, krom tiu, kiu estas de Dio; li vidis la Patron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Vere, vere, mi diras al vi: Kiu kredas, tiu havas vivon eternan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Mi estas la pano de vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Viaj patroj manĝis la manaon en la dezerto, kaj mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'Jen la pano, kiu malsupreniris de la ĉielo, por ke oni manĝu el ĝi kaj ne mortu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Mi estas la viva pano, kiu malsupreniris de la ĉielo; se iu manĝos el ĉi tiu pano, tiu vivos eterne; kaj la pano, kiun mi donos, estas mia karno, por la vivo de la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'La Judoj do disputis inter si, dirante: Kiel ĉi tiu povas doni al ni sian karnon por manĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Jesuo do diris al ili: Vere, vere, mi diras al vi: Se vi ne manĝas la karnon de la Filo de homo kaj ne trinkas lian sangon, vi ne havas en vi vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Kiu manĝas mian karnon kaj trinkas mian sangon, tiu havas eternan vivon; kaj mi levos tiun en la lasta tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Ĉar mia karno estas vera manĝaĵo, kaj mia sango estas vera trinkaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Kiu manĝas mian karnon kaj trinkas mian sangon, tiu restas en mi, kaj mi en li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Kiel la vivanta Patro min sendis, kaj mi vivas pro la Patro, tiel, kiu min manĝas, tiu vivos pro mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'Jen la pano, kiu malsupreniris de la ĉielo; ne kiel la patroj manĝis, kaj mortis; kiu manĝas ĉi tiun panon, tiu vivos eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Tion li diris en la sinagogo, instruante en Kapernaum.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Multaj do el liaj disĉiploj, aŭdinte tion, diris: Malfacila estas tiu parolo; kiu povas lin aŭskulti?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Sed Jesuo, sciante en si mem, ke liaj disĉiploj pri tio murmuris, diris al ili: Ĉu tio faligas vin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Kio do, se vi vidos la Filon de homo supreniranta tien, kie li antaŭe estis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'La spirito estas la viviganto; la karno nenion utilas; la vortoj, kiujn mi diris al vi, estas spirito kaj estas vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'Sed estas iuj el vi, kiuj ne kredas. Ĉar Jesuo sciis de la komenco, kiuj estas la nekredantoj, kaj kiu lin perfidos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'Kaj li diris: Tial mi diris al vi, ke neniu povas veni al mi, se tio ne estas donita al li de mia Patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Ĉe tio multaj el liaj disĉiploj iris returne kaj lin ne plu akompanis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Jesuo do diris al la dek du: Ĉu vi ankaŭ volas foriri?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Simon Petro respondis al li: Sinjoro, al kiu ni iru? vi havas la vortojn de eterna vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'Kaj ni ekkredis kaj scias, ke vi estas la Sanktulo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Respondis al ili Jesuo: Ĉu mi ne elektis vin la dek du, kaj unu el vi estas diablo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'Li parolis pri Judas Iskariota, filo de Simon; ĉar tiu, unu el la dek du, estis perfidonta lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Kaj post tio Jesuo iradis en Galileo; ĉar li ne volis iradi en Judujo, ĉar la Judoj celis mortigi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'La festo de la Judoj, nomata la festo de laŭboj, proksimiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Liaj fratoj do diris al li: Transiru de ĉi tie, kaj iru en Judujon, por ke viaj disĉiploj ankaŭ vidu viajn farojn, kiujn vi faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Ĉar neniu faras ion sekrete, kaj celas mem esti publike konata. Se vi faras tiajn farojn, montru vin al la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Ĉar liaj fratoj mem ne kredis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Jesuo do diris al ili: Mia tempo ankoraŭ ne venis; sed via tempo ĉiam estas preta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'La mondo ne povas vin malami; sed min ĝi malamas, ĉar mi atestas pri ĝi, ke ĝiaj faroj estas malbonaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Supreniru vi al la festo; mi ankoraŭ ne supreniras al la festo, ĉar mia tempo ankoraŭ ne maturiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Dirinte tion al ili, li restis ankoraŭ en Galileo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Sed kiam liaj fratoj supreniris al la festo, tiam li ankaŭ supreniris, ne malkaŝe, sed kvazaŭ sekrete.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'La Judoj do serĉis lin ĉe la festo, kaj diris: Kie li estas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Kaj fariĝis multe da murmurado inter la homamasoj pri li. Unuj diris: Li estas bonulo; aliaj diris: Ne, sed li erarigas la amason.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Tamen neniu parolis malkaŝe pri li, pro timo antaŭ la Judoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Sed ĉirkaŭ la mezo de la festo, Jesuo supreniris en la templon kaj instruis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Kaj la Judoj miris, dirante: Kiel ĉi tiu scias skribojn, neniam lerninte?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Jesuo respondis al ili kaj diris: Mia instruado estas ne mia, sed Ties, kiu min sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Se iu volas plenumi Lian volon, tiu scios pri la instruado, ĉu ĝi estas de Dio, aŭ ĉu mi parolas nur el mi mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Kiu parolas el si mem, tiu celas sian propran gloron; sed kiu celas la gloron de Tiu, kiu lin sendis, tiu estas verema, kaj maljusteco ne estas en li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Ĉu Moseo ne donis al vi la leĝon? kaj neniu el vi observas la leĝon. Kial vi celas mortigi min?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'La homamaso respondis: Vi havas demonon; kiu celas mortigi vin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Jesuo respondis kaj diris al ili: Mi faris unu faron, kaj vi ĉiuj miras pro tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Moseo donis al vi cirkumcidon (tamen ĝi estas ne de Moseo, sed de la patroj); kaj vi en la sabato cirkumcidas viron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Se viro estas cirkumcidata en la sabato, por ke oni ne malobeu al la Mosea leĝo, ĉu vi koleras kontraŭ mi pro tio, ke mi tute sanigis viron en sabato?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Ne juĝu laŭ ŝajno, sed juĝu justan juĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Tiam kelkaj el la Jerusalemanoj diris: Ĉu li ne estas tiu, kiun oni celas mortigi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'Kaj jen li parolas maltime, kaj ili diras al li nenion. Ĉu eble la estraro certe scias, ke ĉi tiu estas la Kristo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Tamen ni scias, de kie ĉi tiu estas; sed kiam la Kristo venos, neniu scios, de kie li estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Jesuo do, instruante en la templo, ekkriis kaj diris: Vi jam min konas, kaj vi ankaŭ scias, de kie mi estas; kaj mi ne venis de mi mem; sed Tiu, kiu min sendis, estas vera, sed Lin vi ne konas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Mi Lin konas, ĉar mi estas de Li; kaj Li min sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Oni do celis kapti lin; sed neniu metis sur lin sian manon, ĉar lia horo ankoraŭ ne venis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Kaj multaj el la homamaso kredis al li, kaj diris: Kiam la Kristo venos, ĉu li faros pli multe da signoj, ol ĉi tiu faris?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'La Fariseoj aŭdis la amason murmuranta tion pri li, kaj la ĉefpastroj kaj la Fariseoj sendis oficistojn, por kapti lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Jesuo do diris al ili: Ankoraŭ iom da tempo mi estas kun vi, kaj mi foriras al Tiu, kiu min sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Vi min serĉos kaj ne trovos; kaj kie mi estas, vi ne povas tien veni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Tial la Judoj inter si diris: Kien ĉi tiu iros, ke ni lin ne trovos? ĉu li iros al la disĵetitoj inter la Grekoj kaj instruos la Grekojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Kia diro estas tio, kion li diris: Vi min serĉos kaj ne trovos, kaj: Kie mi estas, vi ne povas tien veni?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'En la lasta tago, la granda tago de la festo, Jesuo staris kaj kriis, dirante: Se iu soifas, tiu venu al mi kaj trinku.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Kiu kredas al mi, kiel la Skribo diris, el ties ventro fluos riveroj da viva akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'Sed tion li diris pri la Spirito, kiun estis ricevontaj tiuj, kiuj kredis al li; ĉar la Spirito ankoraŭ ne estis donita, ĉar Jesuo ankoraŭ ne estis glorita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Iuj do el la homamaso, aŭdinte tiujn vortojn, diris: Vere ĉi tiu estas la Profeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'Aliaj diris: Ĉi tiu estas la Kristo. Sed kelkaj diris: Tamen ĉu el Galileo la Kristo venas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'Ĉu la Skribo ne diris, ke la Kristo venas el la idaro de David kaj el la vilaĝo Bet-Leĥem, kie David estis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Tiel fariĝis pro li malkonsento inter la homamaso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'Kaj iuj el ili volis kapti lin, sed neniu metis sur lin la manojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Tiam la oficistoj revenis al la ĉefpastroj kaj Fariseoj, kaj ĉi tiuj diris al ili: Kial vi lin ne alkondukis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Respondis la oficistoj: Ankoraŭ neniam tiel parolis homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'La Fariseoj do respondis al ili: Ĉu vi ankaŭ estas erarigitaj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Ĉu kredis al li iu el la regantoj, aŭ el la Fariseoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Sed tiu homamaso, kiu ne scias la leĝon, estas malbenita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Tiam Nikodemo (tiu, kiu venis nokte al Jesuo, estante unu el ili) diris al ili:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, 'Ĉu nia leĝo juĝas iun, se antaŭe oni ne aŭskultis lin, kaj ne sciiĝis, kion li faras?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Ili respondis kaj diris al li: Ĉu vi ankaŭ estas el Galileo? Esploru, kaj vidu, ke neniam el Galileo venas profeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'Kaj ĉiu iris al sia domo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'sed Jesuo iris al la monto Olivarba.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Kaj li revenis frumatene en la templon, kaj la tuta popolo venis al li; kaj li sidiĝis, kaj instruadis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Kaj la skribistoj kaj Fariseoj alkondukis virinon, kaptitan en adulto; kaj stariginte ŝin en la mezo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'ili diris al li: Majstro, ĉi tiu virino estas kaptita adultante, en la faro mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'En la leĝo Moseo ordonis al ni tiajn ŝtonmortigi; sed kion vi diras?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Kaj tion ili diris, provante lin, por povi lin akuzi pri io. Sed Jesuo sin klinis, kaj per fingro skribis sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Kiam ili ankoraŭ demandis lin, li leviĝis, kaj diris al ili: Kiu el vi estas senpeka, tiu unua ĵetu sur ŝin ŝtonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Kaj denove li sin klinis kaj skribis sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Sed aŭdinte tion, ili eliris unu post alia, komencante de la plej maljunaj kaj ĝis la lastaj; kaj restis Jesuo sola, kaj la virino staranta en la mezo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Kaj Jesuo leviĝis, kaj diris al ŝi: Virino, kie ili estas? ĉu neniu vin kondamnis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Kaj ŝi diris: Neniu, Sinjoro. Jesuo diris al ŝi: Ankaŭ mi vin ne kondamnas; iru, kaj de nun ne plu peku.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Jesuo denove parolis al ili, dirante: Mi estas la lumo de la mondo; kiu min sekvas, tiu ne iros en mallumo, sed havos la lumon de la vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'La Fariseoj do diris al li: Vi atestas pri vi mem; via atesto ne estas vera.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Jesuo respondis kaj diris al ili: Kvankam mi atestas pri mi mem, tamen mia atesto estas vera; ĉar mi scias, de kie mi venis, kaj kien mi iras; sed vi ne scias, de kie mi venis, nek kien mi iras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Vi juĝas laŭ la karno; mi juĝas neniun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'Tamen, eĉ se mi juĝas, mia juĝo estas vera; ĉar mi ne estas sola, sed mi kaj la Patro, kiu min sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'Estas ja skribite en via leĝo, ke la atesto de du homoj estas vera.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Mi estas atestanto pri mi mem, kaj la Patro, kiu min sendis, atestas pri mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Ili do diris al li: Kie estas via Patro? Respondis Jesuo: Vi konas nek min, nek mian Patron; se vi konus min, vi konus ankaŭ mian Patron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Tiujn vortojn Jesuo parolis en la trezorejo, dum li instruis en la templo; kaj neniu arestis lin, ĉar lia horo ankoraŭ ne venis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Jesuo do denove diris al ili: Mi foriras, kaj vi serĉos min, kaj vi mortos en via peko; kien mi iras, tien vi ne povas veni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'La Judoj do diris: Ĉu li sin mortigos? ĉar li diras: Kien mi iras, tien vi ne povas veni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'Kaj li diris al ili: Vi estas de malsupre, mi estas de supre; vi estas de ĉi tiu mondo, mi ne estas de ĉi tiu mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Mi tial diris al vi, ke vi mortos en viaj pekoj; ĉar se vi ne kredos, ke mi estas, vi mortos en viaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Ili do diris al li: Kiu vi estas? Jesuo diris al ili: Laŭ tio, kion mi diradis al vi de la komenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Mi havas multon por diri kaj juĝi pri vi; sed Tiu, kiu min sendis, estas vera; kaj tion, kion mi aŭdis de Li, mi parolas al la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Ili ne komprenis, ke li parolas al ili pri la Patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Jesuo do diris: Kiam vi levos la Filon de homo, tiam vi scios, ke mi estas, kaj ke mi ne faras ion per mi mem; sed kiel la Patro instruis min, tion mi parolas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'Kaj Tiu, kiu min sendis, estas kun mi; Li ne lasis min sola; ĉar mi ĉiam faras tion, kio plaĉas al Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Dum li parolis tion, multaj kredis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Jesuo do diris al la Judoj, kiuj kredis al li: Se vi restos en mia vorto, vi estas vere miaj disĉiploj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'kaj vi scios la veron, kaj la vero vin liberigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Ili respondis al li: Ni estas idaro de Abraham, kaj ankoraŭ al neniu ni estis sklavoj; kial vi diras: Vi estos liberigitaj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Jesuo respondis al ili: Vere, vere, mi diras al vi: Ĉiu, kiu faras pekon, estas sklavo de peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'Kaj la sklavo ne ĉiam restas en la domo, sed la filo ĉiam restas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Se do la Filo vin liberigos, vi estos efektive liberaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Mi scias, ke vi estas idaro de Abraham; sed vi celas mortigi min, ĉar mia vorto ne progresas en vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Mi parolas tion, kion mi vidis ĉe mia Patro; kaj vi ankaŭ faras tion, kion vi vidis ĉe via patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Ili respondis kaj diris al li: Nia patro estas Abraham. Jesuo diris al ili: Se vi estus Abrahamidoj, vi farus la farojn de Abraham.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'Sed nun vi celas mortigi min, homon, kiu parolis al vi la veron, kiun mi aŭdis de Dio; tion Abraham ne faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Vi faras la farojn de via patro. Tiam ili diris al li: Ni ne naskiĝis per malĉasteco; unu Patron ni havas, Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Jesuo diris al ili: Se Dio estus via Patro, vi min amus; ĉar de Dio mi elvenis, kaj estas veninta; ĉar mi ne venis de mi mem, sed Li min sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Kial vi ne komprenas mian parolon? Tial, ke vi ne povas aŭdi mian vorton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Vi estas de patro, la diablo, kaj vi volas fari la dezirojn de via patro. Li estis hommortiganto de la komenco, kaj ne staras en la vero, ĉar vero ne estas en li. Kiam li parolas mensogon, li parolas sian propraĵon, ĉar li estas mensoganto, kaj la patro de ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Sed tial, ke mi parolas la veron, vi ne kredas al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Kiu el vi pruvas kontraŭ mi pekon? Se mi diras la veron, kial vi ne kredas al mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Kiu estas de Dio, tiu aŭskultas la vortojn de Dio; vi ne aŭskultas, ĉar vi ne estas el Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'La Judoj respondis kaj diris al li: Ĉu ne prave ni diras, ke vi estas Samariano kaj havas demonon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Jesuo respondis: Mi ne havas demonon; sed mi honoras mian Patron, kaj vi min malhonoras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Sed mi ne serĉas mian gloron: estas Unu, kiu serĉas kaj juĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Vere, vere, mi diras al vi: Se iu observos mian vorton, tiu la morton neniam vidos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'La Judoj diris al li: Nun ni scias, ke vi havas demonon. Mortis Abraham, kaj la profetoj; kaj vi diras: Se iu observos mian vorton, tiu la morton neniam gustumos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Ĉu vi estas pli granda ol nia patro Abraham, kiu mortis? kaj la profetoj mortis; kiu vi pretendas esti?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Jesuo respondis: Se mi gloros min mem, mia gloro estas nenio; Tiu, kiu min gloras, estas mia Patro, pri kiu vi diras, ke Li estas via Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'kaj vi Lin ne konis, sed mi Lin konas; kaj se mi diros, ke mi Lin ne konas, mi estos, kiel vi, mensoganto; sed mi Lin konas, kaj observas Lian vorton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Via patro Abraham ĝojegis vidi mian tagon, kaj li vidis kaj estis ravita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Tiam la Judoj diris al li: Vi ankoraŭ ne estas kvindekjara, kaj ĉu vi vidis Abrahamon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Jesuo diris al ili: Vere, vere, mi diras al vi: Antaŭ ol naskiĝis Abraham, mi ekzistas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Tiam ili prenis ŝtonojn, por ĵeti sur lin; sed Jesuo sin kaŝis, kaj eliris el la templo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Kaj preterirante, li vidis viron blindan de post la naskiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'Kaj liaj disĉiploj demandis lin, dirante: Rabeno, kiu do pekis, ĉi tiu viro, aŭ liaj gepatroj, ke li naskiĝis blinda?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Jesuo respondis: Nek ĉi tiu viro pekis, nek liaj gepatroj; sed por ke la faroj de Dio aperu en li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Dum estas tago, mi devas prilabori la farojn de Tiu, kiu min sendis; venas la nokto, kiam neniu povas labori.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Dum mi estas en la mondo, mi estas la lumo de la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Dirinte tion, li kraĉis sur la teron, kaj faris el la kraĉaĵo koton, kaj ŝmiris per la koto la okulojn de la blindulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'kaj diris al li: Iru, lavu vin en la lageto de Ŝiloaĥ (tio estas, Sendito). Li do foriris, kaj sin lavis, kaj revenis vidanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'La najbaroj do, kaj tiuj, kiuj antaŭe vidis lin, ke li estas almozulo, diris: Ĉu ĉi tiu ne estas tiu, kiu sidis kaj petis almozojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Unuj diris: Li estas; aliaj diris: Ne, sed li estas simila al tiu. Li diris: Tiu mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Ili do diris al li: Kiamaniere viaj okuloj malfermiĝis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Li respondis kaj diris: La homo, nomata Jesuo, faris koton kaj ŝmiris miajn okulojn, kaj diris al mi: Iru al Ŝiloaĥ, kaj vin lavu; kaj mi iris, kaj lavis min, kaj mi ricevis vidpovon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Tiam ili diris al li: Kie li estas? Li diris: Mi ne scias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Ili kondukis al la Fariseoj la iam blindan viron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Sed estis sabato la tago, en kiu Jesuo faris la koton kaj malfermis liajn okulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'La Fariseoj do denove demandis lin, kiamaniere li ricevis vidpovon. Kaj li diris al ili: Li metis koton sur miajn okulojn, kaj mi lavis min, kaj mi vidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Unuj do el la Fariseoj diris: Ĉi tiu homo ne estas de Dio, ĉar li ne observas la sabaton. Aliaj diris: Kiel povas homo pekulo fari tiajn signojn? Kaj malkonsento estis inter ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Denove ili diris al la blindulo: Kion vi diras pri li rilate tion, ke li malfermis viajn okulojn? Li diris: Li estas profeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'La Judoj ne kredis pri li, ke li estis antaŭe blinda, kaj ke li ricevis vidpovon, ĝis ili alvokis la gepatrojn de tiu, kiu ricevis vidpovon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'kaj demandis ilin, dirante: Ĉu ĉi tiu estas via filo, kiu, vi diras, naskiĝis blinda? kiel do li nun vidas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Liaj gepatroj respondis kaj diris: Ni scias, ke ĉi tiu estas nia filo, kaj ke li naskiĝis blinda;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'sed kial li nun vidas, ni ne scias; kaj kiu malfermis liajn okulojn, ni ne scias; demandu lin, li havas plenaĝon; li pri si mem parolos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Tion diris la gepatroj, ĉar ili timis la Judojn; ĉar la Judoj jam interkonsentis, ke se iu konfesos, ke li estas la Kristo, tiu estu forigita el la sinagogo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Tial la gepatroj diris: Li havas plenaĝon, demandu lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Ili do denove alvokis la viron, kiu estis blinda, kaj diris al li: Donu gloron al Dio; ni certe scias, ke tiu homo estas pekulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'Li do respondis: Ĉu li estas pekulo, mi ne scias; unu aferon mi scias, ke mi estis blinda kaj nun vidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Tiam ili diris al li denove: Kion li faris al vi? kiamaniere li malfermis viajn okulojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Li respondis al ili: Mi ĵus diris al vi, kaj vi ne atentis; kial vi volas denove ĝin aŭdi? ĉu vi ankaŭ volas fariĝi liaj disĉiploj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Tiam ili insultis lin, kaj diris: Vi estas lia disĉiplo, sed ni estas disĉiploj de Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Ni scias, ke Dio parolis al Moseo; sed pri ĉi tiu, ni ne scias, de kie li estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'La viro respondis kaj diris al ili: Jen la mirindaĵo, ke vi ne scias, de kie li estas, kaj tamen li malfermis miajn okulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Ni scias, ke Dio ne atentas pekulojn; sed se iu estas adoranto de Dio kaj plenumas Lian volon, tiun Li atentas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'De la komenco de la mondo oni neniam aŭdis, ke iu malfermis la okulojn de homo, kiu naskiĝis blinda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Se ĉi tiu homo ne estus de Dio, li nenion povus fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Ili respondis kaj diris al li: Vi tute naskiĝis en pekoj, kaj ĉu vi nin instruas? Kaj ili forpelis lin eksteren.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Jesuo aŭdis, ke ili forpelis lin; kaj trovinte lin, li diris al li: Ĉu vi kredas al la Filo de Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Li respondis kaj diris: Kiu li estas, Sinjoro, por ke mi kredu al li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Jesuo diris al li: Vi lin vidis; kaj li estas tiu, kiu parolas kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'Kaj li diris: Sinjoro, mi kredas. Kaj li adorkliniĝis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'Kaj Jesuo diris: Por juĝo mi venis en ĉi tiun mondon, por ke la nevidantoj vidu, kaj ke la vidantoj fariĝu blindaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'Kaj tion aŭdis tiuj el la Fariseoj, kiuj estis kun li; kaj ili diris al li: Ĉu ni ankaŭ estas blindaj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Jesuo diris al ili: Se vi estus blindaj, vi ne havus pekon; sed nun vi diras: Ni vidas; via peko do restas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'Vere, vere, mi diras al vi: Kiu eniras en la ŝafejon ne tra la pordo, sed aliloke suprengrimpas, tiu estas ŝtelisto kaj rabisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Sed kiu eniras tra la pordo, tiu estas la paŝtisto de la ŝafoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Al tiu la pordisto malfermas; kaj la ŝafoj aŭskultas lian voĉon, kaj li alvokas laŭ nomoj siajn proprajn ŝafojn, kaj elkondukas ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'Kaj kiam li kondukis eksteren siajn ŝafojn, li iras antaŭ ili, kaj la ŝafoj lin sekvas, ĉar ili konas lian voĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Kaj fremdulon ili ne sekvos, sed forkuros de li, ĉar ili ne konas la voĉon de fremduloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Tiun alegorion Jesuo diris al ili; sed ili ne komprenis, kiajn aferojn li parolas al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Jesuo do diris denove al ili: Vere, vere, mi diras al vi: Mi estas la pordo de la ŝafoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Ĉiuj, kiuj venis pli frue ol mi, estas ŝtelistoj kaj rabistoj; sed la ŝafoj ne aŭskultis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Mi estas la pordo; se iu tra mi eniras, tiu estos savita; kaj li eniros kaj eliros, kaj trovos paŝtaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'La ŝtelisto ne venas, krom por ŝteli kaj buĉi kaj pereigi; mi venis, por ke ili havu vivon, kaj havu ĝin abunde.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Mi estas la bona paŝtisto; la bona paŝtisto demetas sian vivon por la ŝafoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'La dungito, kaj tiu, kiu ne estas paŝtisto, kies propraĵo la ŝafoj ne estas, ekvidas la lupon venanta kaj lasas la ŝafojn kaj forkuras; kaj la lupo ilin kaptas kaj dispelas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'li forkuras tial, ke li estas dungito kaj ne zorgas pri la ŝafoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Mi estas la bona paŝtisto, kaj mi konas la miajn, kaj la miaj min konas');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'tiel same, kiel la Patro min konas, kaj mi konas la Patron; kaj mi demetas mian vivon por la ŝafoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Kaj aliajn ŝafojn mi havas, kiuj ne estas de ĉi tiu gregejo; ilin ankaŭ mi devas alkonduki, kaj ili aŭskultos mian voĉon; kaj estos unu grego, unu paŝtisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Pro tio la Patro min amas, ke mi demetas mian vivon, por ke mi ĝin reprenu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Neniu ĝin forprenas de mi, sed mi ĝin demetas memvole. Mi havas la rajton ĝin demeti, kaj mi havas la rajton ĝin repreni. Ĉi tiun ordonon mi ricevis de mia Patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Denove fariĝis malkonsento inter la Judoj pro tiuj diroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Kaj multaj el ili diris: Li havas demonon kaj estas freneza; kial vi lin aŭskultas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Aliaj diris: Tiuj ne estas diroj de demonhavanto. Ĉu demono povas malfermi la okulojn de blinduloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Okazis la festo de inaŭguro en Jerusalem, kaj estis vintro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'kaj Jesuo promenis en la templo, en la portiko de Salomono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'La Judoj do ĉirkaŭis lin, kaj diris al li: Ĝis kiam vi tenas en dubo nian animon? Se vi estas la Kristo, diru al ni malkaŝe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Jesuo respondis al ili: Mi diris al vi, kaj vi ne kredas; la faroj, kiujn mi faras en la nomo de mia Patro, atestas pri mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Sed vi ne kredas, ĉar vi ne estas el miaj ŝafoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Miaj ŝafoj aŭskultas mian voĉon, kaj mi ilin konas, kaj ili min sekvas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'kaj mi donas al ili eternan vivon; kaj ili neniam pereos, kaj neniu ilin forkaptos el mia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Mia Patro, kiu donis ilin al mi, superas ĉion; kaj neniu povas ion forkapti el la mano de mia Patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Mi kaj la Patro estas unu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Tiam la Judoj denove prenis ŝtonojn, por ŝtonmortigi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Jesuo respondis al ili: Multajn bonajn farojn mi montris al vi de mia Patro; pro kiu el ili vi volas ŝtonmortigi min?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'La Judoj respondis: Ne pro bona faro ni volas ŝtonmortigi vin, sed pro blasfemo, kaj ĉar vi, estante homo, pretendas esti Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Jesuo respondis: Ĉu ne estas skribite en via leĝo: Mi diris: Vi estas dioj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Se li nomis dioj tiujn, al kiuj venis la vorto de Dio (kaj la Skribo ne povas esti nuligita),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'ĉu vi diras pri tiu, kiun la Patro konsekris kaj sendis en la mondon: Vi blasfemas; ĉar mi diris: Mi estas Filo de Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Se mi ne faras la farojn de mia Patro, ne kredu al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'Sed se mi faras ilin, kvankam vi ne kredas al mi, kredu la farojn, por ke vi sciu kaj komprenu, ke la Patro estas en mi, kaj mi en la Patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Ili denove celis kapti lin, sed li iris for de ilia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'Li foriris denove trans Jordanon tien, kie Johano unue baptis, kaj tie li restadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'Kaj multaj venis al li, kaj diris: Johano ja ne faris signon; sed ĉio, kion Johano diris pri ĉi tiu, estis vera.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'Kaj tie multaj kredis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Kaj estis unu malsanulo, nomata Lazaro, el Betania, la vilaĝo de Maria kaj ŝia fratino Marta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'Tiu Maria, kies frato Lazaro estis malsana, estis tiu sama, kiu ŝmiris la Sinjoron per ŝmiraĵo kaj viŝis liajn piedojn per siaj haroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'La fratinoj do sendis al li, dirante: Sinjoro, jen tiu, kiun vi amas, estas malsana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Sed Jesuo, aŭdinte tion, diris: Ĉi tiu malsano estas ne por la morto, sed por la gloro de Dio, por ke la Filo de Dio estu per ĝi glorata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Kaj Jesuo amis Martan kaj ŝian fratinon kaj Lazaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Kaj kiam li sciiĝis, ke tiu estas malsana, li restis ankoraŭ du tagojn en la loko, kie li estis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Poste li diris al la disĉiploj: Ni iru returne en Judujon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'La disĉiploj diris al li: Rabeno, la Judoj ĵus celis ŝtonmortigi vin; kaj ĉu vi denove iras tien?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Jesuo respondis: Ĉu ne estas dek du horoj en la tago? Se iu iras dum la tago, li ne faletas, ĉar li vidas la lumon de ĉi tiu mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'Sed se iu iras dum la nokto, li faletas, ĉar en li ne estas la lumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Tion li parolis, kaj poste li diris al ili: Nia amiko Lazaro endormiĝis, sed mi iras, por veki lin el lia dormo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'La disĉiploj do diris: Sinjoro, se li endormiĝis, li resaniĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Jesuo parolis pri lia morto; sed ili supozis, ke li parolas pri ripozo en dormo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Tiam Jesuo diris al ili klare: Lazaro jam mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'Kaj pro vi mi ĝojas, ke mi ne ĉeestis tie, por ke vi kredu; tamen ni iru al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Tiam Tomaso, nomata Didimo, diris al siaj kundisĉiploj: Ni ankaŭ iru, por ke ni mortu kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Kiam Jesuo alvenis, li trovis lin jam kvar tagojn entombigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Kaj Betania estis proksime de Jerusalem, en la distanco de ĉirkaŭ dek kvin stadioj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'kaj multaj el la Judoj jam venis al Marta kaj Maria, por konsoli ilin pri ilia frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Marta do, kiam ŝi eksciis, ke Jesuo alproksimiĝas, iris al li renkonte; sed Maria ankoraŭ sidis en la domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Tiam diris Marta al Jesuo: Sinjoro, se vi estus ĉi tie, mia frato ne estus mortinta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'Sed eĉ nun mi scias, ke kion ajn vi petos de Dio, tion Dio donos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Jesuo diris al ŝi: Via frato releviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Marta diris al li: Mi scias, ke li releviĝos ĉe la releviĝo en la lasta tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Jesuo diris al ŝi: Mi estas la releviĝo kaj la vivo; kiu kredas al mi, eĉ se li estos mortinta, tiu vivos,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'kaj ĉiu, kiu vivas kaj kredas al mi, por ĉiam ne mortos. Ĉu vi tion kredas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Ŝi diris al li: Jes, Sinjoro, mi jam kredas, ke vi estas la Kristo, la Filo de Dio, la venanta en la mondon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'Kaj dirinte tion, ŝi foriris, kaj vokis sekrete sian fratinon Maria, dirante: La Majstro ĉeestas, kaj vokas vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Kaj ŝi, aŭdinte tion, leviĝis rapide kaj iris al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, '(Sed Jesuo ankoraŭ ne eniris en la vilaĝon, sed estis en la loko, kie Marta lin renkontis.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'La Judoj do, kiuj estis kun ŝi en la domo kaj konsolis ŝin, vidinte, ke Maria leviĝis subite kaj eliris, sekvis ŝin, dirante: Ŝi iras al la tombo, por plori tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Kiam Maria alvenis al la loko, kie Jesuo estis, kaj lin vidis, ŝi falis antaŭ liaj piedoj, dirante: Sinjoro, se vi estus ĉi tie, mia frato ne estus mortinta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Kiam do Jesuo vidis ŝin ploranta kaj la Judojn ankaŭ, kiuj venis kun ŝi, plorantaj, li ĝemis en la spirito kaj maltrankviliĝis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'kaj diris: Kie vi lin kuŝigis? Ili diris al li: Sinjoro, venu kaj vidu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Jesuo larmis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'La Judoj do diris: Jen kiel li lin amis!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Sed kelkaj el ili diris: Ĉu ĉi tiu, kiu malfermis la okulojn de la blindulo, ne povus kaŭzi ankaŭ, ke ĉi tiu homo ne mortu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Tiam Jesuo, denove ĝemante en si, venis al la tombo. Ĝi estis kaverno, kaj sur ĝi kuŝis ŝtono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Jesuo diris: Forprenu la ŝtonon. Marta, la fratino de la mortinto, diris al li: Sinjoro, li jam malbonodoras, ĉar li estis tie kvar tagojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Jesuo diris al ŝi: Ĉu mi ne diris al vi, ke se vi kredos, vi vidos la gloron de Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Oni do forprenis la ŝtonon. Kaj Jesuo levis siajn okulojn, kaj diris: Patro, mi dankas Vin, ke Vi min aŭskultis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Kaj mi sciis, ke Vi ĉiam aŭskultas min; sed pro la ĉirkaŭstaranta homamaso mi tion diris, por ke ili kredu, ke Vi min sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'Kaj dirinte tion, li kriis per laŭta voĉo: Lazaro, elvenu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'Kaj la mortinto elvenis, kun la manoj kaj piedoj ligitaj per tombotukoj; kaj lia vizaĝo estis ĉirkaŭligita per viŝtuko. Jesuo diris al ili: Malligu lin, kaj lasu lin iri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Tiam multaj el la Judoj, kiuj venis al Maria, kaj vidis, kion li faris, kredis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'Sed kelkaj el ili foriris al la Fariseoj, kaj rakontis al ili tion, kion Jesuo faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Tial la ĉefpastroj kaj la Fariseoj kunvenigis sinedrion, kaj diris: Kion ni faras? ĉar ĉi tiu homo faras multajn signojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'se ni lasos lin tiel, ĉiuj kredos al li, kaj la Romanoj venos kaj forigos nian lokon kaj nian nacion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'Sed unu el ili, Kajafas, ĉefpastro en tiu sama jaro, diris al ili: Vi scias nenion,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'nek konsideras, ke bone estas por vi, ke unu homo mortu por la popolo, kaj ke la tuta nacio ne pereu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Sed li diris tion ne de si mem; sed estante ĉefpastro en tiu jaro, li profetis, ke Jesuo mortos por la nacio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'kaj ne nur por la nacio, sed ankaŭ por ke li kunvenigu en unu la ĉie disĵetitajn filojn de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'De post tiu tago do ili konsiliĝis, por lin mortigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'Tial Jesuo ne plu iris publike inter la Judoj, sed foriris de tie en la kamparon apud la dezerto, en urbon nomatan Efraim; kaj tie li restadis kun la disĉiploj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'Kaj la Pasko de la Judoj proksimiĝis, kaj multaj supreniris el la kamparo al Jerusalem antaŭ la Pasko, por sin sanktigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Ili do serĉis Jesuon, kaj parolis inter si, starante en la templo: Kion vi pensas? Ĉu ke li ne venos al la festo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Kaj la ĉefpastroj kaj la Fariseoj jam antaŭe ordonis, ke se iu scias, kie li estas, tiu montru tion, por ke oni lin kaptu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Jesuo do ses tagojn antaŭ la Pasko venis al Betania, kie estis Lazaro, kiun Jesuo relevis el inter la mortintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Oni do pretigis por li tie vespermanĝon, kaj Marta servadis; sed Lazaro estis unu el tiuj, kiuj sidis kun li ĉe manĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Tiam Maria prenis funton da pura narda ŝmiraĵo tre multekosta, ŝmiris la piedojn de Jesuo, kaj viŝis liajn piedojn per siaj haroj; kaj la domo pleniĝis de la odoro de la ŝmiraĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Sed diris Judas Iskariota, unu el liaj disĉiploj, kiu estis lin perfidonta:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'Kial oni ne vendis ĉi tiun ŝmiraĵon por tricent denaroj kaj donis al malriĉuloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Tion li diris, ne ĉar li zorgis pri la malriĉuloj; sed ĉar li estis ŝtelisto, kaj havis la monujon kaj forprenadis tion, kion oni metis en ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Sed Jesuo diris: Lasu ŝin konservi ĝin por la tago de mia entombigo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Ĉar la malriĉulojn vi ĉiam havas kun vi, sed min vi ne ĉiam havas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'La amaso de la Judoj do sciiĝis, ke li estas tie; kaj ili venis ne nur pro Jesuo, sed ankaŭ por vidi Lazaron, kiun li levis el la mortintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Sed la ĉefpastroj konsiliĝis, ke ili mortigu ankaŭ Lazaron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'ĉar pro li multaj Judoj foriris, kaj kredis al Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'En la sekvanta tago granda homamaso, veninte al la festo, kaj sciiĝinte, ke Jesuo venas al Jerusalem,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'prenis branĉojn de la palmoj, kaj iris al li renkonte, kaj kriis: Hosana! Estu benata la Reĝo de Izrael, kiu venas en la nomo de la Eternulo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'Kaj Jesuo, trovinte junan azenon, sidis sur ĝi, kiel estas skribite:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, 'Ne timu, filino de Cion: jen via Reĝo venas, sidanta sur ido de azeno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Tion la disĉiploj unue ne komprenis; sed post la gloriĝo de Jesuo ili rememoris, ke tio estis skribita pri li kaj ke oni faris al li tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'La homamaso do, kiu ĉeestis kun li, kiam li elvokis Lazaron el la tombo, kaj levis lin el la mortintoj, atestis pri li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Pro tio ankaŭ la homamaso iris al li renkonte, ĉar ili sciiĝis, ke li faris tiun signon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'La Fariseoj do diris inter si: Vidu, kiel nenio prosperis al vi; jen la mondo eliris post li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Kaj inter tiuj, kiuj alvojaĝis por adorkliniĝi ĉe la festo, estis iuj Grekoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'tiuj do venis al Filipo, kiu estis el Betsaida Galilea, kaj petis lin, dirante: Sinjoro, ni volas vidi Jesuon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Filipo venis kaj sciigis Andreon; kaj poste Andreo kaj Filipo venis kaj sciigis Jesuon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'Sed Jesuo respondis al ili, dirante: Venis la horo, por ke la Filo de homo estu glorata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Vere, vere, mi diras al vi: Se la tritika grenero ne falas en la teron kaj ne mortas, ĝi restas sola; sed se ĝi mortas, ĝi donas multe da frukto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Kiu amas sian vivon, tiu ĝin perdas; kaj kiu malamas sian vivon en ĉi tiu mondo, tiu ĝin konservos ĝis eterna vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Se iu min servas, tiu sekvu min; kaj kie mi estas, tie ankaŭ estos mia servanto; se iu min servas, tiun la Patro honoros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Nun maltrankviliĝas mia animo; kaj kion mi diru? Patro, savu min el ĉi tiu horo. Sed por tio mi venis ĝis ĉi tiu horo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Patro, gloru Vian nomon. Tiam voĉo venis el la ĉielo: Mi jam gloris ĝin kaj denove gloros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'Do la apudstaranta homamaso, aŭdinte, diris, ke tondris; aliaj diris: Anĝelo parolis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Jesuo respondis kaj diris: Ne por mi venis tiu voĉo, sed por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Nun estas la juĝo de ĉi tiu mondo; nun la estro de ĉi tiu mondo estos elpelita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'Kaj mi, se mi estos suprenlevita de sur la tero, altiros al mi ĉiujn homojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'Tion li diris, per aludo montrante, per kia morto li mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'La homamaso respondis al li: Ni aŭdis el la leĝo, ke la Kristo restados por ĉiam; kaj kiel vi diras: La Filo de homo devas esti suprenlevita? Kiu estas ĉi tiu Filo de homo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Jesuo do diris al ili: Ankoraŭ mallongan tempon estas la lumo kun vi. Iradu, dum vi havas la lumon, por ke la mallumo ne venu sur vin; ĉar tiu, kiu iradas en mallumo, ne scias, kien li iras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Dum vi havas lumon, kredu al la lumo, por ke vi fariĝu filoj de lumo. Tion parolis Jesuo, kaj li foriris, kaj sin kaŝis for de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'Sed kvankam li jam faris tiom da signoj antaŭ ili, tamen ili ne kredis al li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'por ke plenumiĝu la vorto de la profeto Jesaja, kiun li parolis: Ho Eternulo, kiu kredis nian raporton? Kaj super kiu malkaŝiĝis la brako de la Eternulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Pro tio ili ne povis kredi, ĉar Jesaja diris plue:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, 'Li blindigis iliajn okulojn kaj sensentigis ilian koron, Por ke ili ne vidu per siaj okuloj, kaj ke ili ne komprenu per sia koro, Kaj ke ili ne konvertiĝu, Kaj ke Mi ilin ne sanigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'Tion diris Jesaja, ĉar li vidis lian gloron kaj parolis pri li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Tamen eĉ el la regantoj multaj kredis al li; sed pro la Fariseoj ili ne konfesis lin, por ke ili ne estu elpelitaj el la sinagogo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'ĉar ili ŝatis la laŭdon de homoj pli, ol la gloron de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Kaj Jesuo kriis kaj diris: Kiu kredas al mi, tiu kredas ne al mi, sed al Tiu, kiu min sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'Kaj kiu vidas min, tiu vidas ankaŭ Tiun, kiu min sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Mi venis lumo en la mondon, por ke ĉiu, kiu kredas al mi, ne restadu en mallumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'Kaj se iu aŭdas miajn dirojn kaj ne plenumas ilin, mi lin ne juĝas; ĉar mi venis, ne por juĝi la mondon, sed por savi la mondon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Tiu, kiu forrifuzas min kaj ne akceptas miajn dirojn, havas juĝonton; la vorto, kiun mi parolis, juĝos lin en la lasta tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Ĉar mi ne parolis de mi mem; sed la Patro, kiu sendis min, mem ordonis al mi, kion mi parolu, kaj kion mi diru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'Kaj mi scias, ke Lia ordono estas eterna vivo; kion do mi parolas, ĝuste kiel la Patro diris al mi, tiel mi parolas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Kaj antaŭ la Paska festo Jesuo, sciante, ke lia horo venis, por ke li transiru el ĉi tiu mondo al la Patro, aminte siajn proprulojn, kiuj estis en la mondo, amis ilin ĝis la fino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'Kaj dum la vespermanĝo, kiam la diablo jam metis en la koron de Judas Iskariota, filo de Simon, la intencon perfidi lin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Jesuo, sciante, ke la Patro donis ĉion en liajn manojn, kaj ke li venis de Dio kaj iras al Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'leviĝis de la vespermanĝo kaj demetis siajn vestojn; kaj li prenis viŝtukon, kaj sin zonis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Poste li verŝis akvon en la pelvon, kaj komencis lavi la piedojn de la disĉiploj kaj viŝi ilin per la tuko, per kiu li estis zonita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Tiam li venis al Simon Petro. Ĉi tiu diris al li: Sinjoro, ĉu vi lavas al mi la piedojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Jesuo respondis kaj diris al li: Kion mi faras, vi nun ne scias, sed poste vi komprenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Petro diris al li: Vi ja neniam lavos miajn piedojn. Respondis al li Jesuo: Se mi ne lavas vin, vi ne partoprenas kun mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Simon Petro diris al li: Sinjoro, ne nur miajn piedojn, sed ankaŭ la manojn kaj la kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Jesuo diris al li: Kiu sin jam banis, tiu bezonas nur, ke oni lavu la piedojn, kaj li estas tuta pura; kaj vi estas puraj, tamen ne ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Ĉar li konis tiun, kiu perfidos lin; tial li diris: Vi ne ĉiuj estas puraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Kiam do li jam lavis iliajn piedojn kaj surmetis siajn vestojn kaj denove sidiĝis, li diris al ili: Ĉu vi scias, kion mi faris al vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Vi nomas min Majstro kaj Sinjoro; kaj prave vi diras, ĉar tia mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Se do mi, la Sinjoro kaj la Majstro, lavis viajn piedojn, vi ankaŭ devas inter vi lavi la piedojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Ĉar mi donis al vi ekzemplon, por ke vi ankaŭ faru tion, kion mi faris al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Vere, vere, mi diras al vi: Sklavo ne estas pli granda ol lia sinjoro; nek estas la sendito pli granda ol la sendinto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Se ĉi tion vi scias, vi estas feliĉaj, se tion vi faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Ne pri vi ĉiuj mi parolas; mi scias, kiujn mi elektis; sed por ke plenumiĝu la Skribo: Tiu, kiu manĝas mian panon, levis kontraŭ min la piedon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'De nun mi parolas al vi pri tio, antaŭ ol ĝi okazos, por ke, kiam ĝi okazos, vi kredu, ke mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Vere, vere, mi diras al vi: Kiu akceptas tiun, kiun mi sendas, tiu akceptas min; kaj kiu min akceptas, tiu akceptas Tiun, kiu min sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Dirinte tion, Jesuo maltrankviliĝis en spirito, kaj ateste parolis, dirante: Vere, vere, mi diras al vi, ke unu el vi min perfidos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Tiam la disĉiploj rigardis unu la alian, dubante pri kiu li parolas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Estis apud la sino de Jesuo unu el liaj disĉiploj, kiun Jesuo amis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Simon Petro do faris signon al li, ke li demandu, pri kiu li parolas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'Tiu do, kliniĝante al la brusto de Jesuo, diris al li: Sinjoro, kiu ĝi estas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Jesuo respondis: Ĝi estas tiu, por kiu mi trempos la pecon kaj donos al li. Kaj trempinte la pecon, li donis ĝin al Judas Iskariota, filo de Simon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'Kaj post la peco, tiam Satano eniris en lin. Jesuo do diris al li: Kion vi faras, tion faru senprokraste.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Sed neniu el la kunmanĝantoj sciis, kial li diris al li tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'Iuj pensis, ĉar Judas havis la monujon, ke Jesuo diris al li: Aĉetu tion, kion ni bezonas por la festo; aŭ ke li donu ion al la malriĉuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Li do, ricevinte la pecon, tuj eliris; kaj estis nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Kiam li eliris, Jesuo diris: Nun la Filo de homo estas glorata, kaj Dio estas glorata en li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'kaj Dio gloros lin en Si mem, kaj tuj Li gloros lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Infanoj, ankoraŭ mallongan tempon mi estas kun vi. Vi min serĉos; kaj kiel mi diris al la Judoj: Kien mi iras, tien vi ne povas veni, tiel ankaŭ al vi mi nun diras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Novan ordonon mi donas al vi, ke vi amu unu alian; kiel mi amis vin, tiel vi ankaŭ amu unu alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'Per tio ĉiuj homoj scios, ke vi estas miaj disĉiploj, se vi havos amon unu al alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Simon Petro diris al li: Sinjoro, kien vi iras? Jesuo respondis: Kien mi iras, vi ne povas min sekvi nun, sed poste vi min sekvos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Petro diris al li: Sinjoro, kial mi ne povas vin sekvi nun? mi demetos por vi mian vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Jesuo respondis al li: Ĉu vi demetos por mi vian vivon? Vere, vere, mi diras al vi: La koko ne krios, antaŭ ol vi min malkonfesos tri fojojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Ne maltrankviliĝu via koro; vi kredas al Dio, kredu ankaŭ al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Ĉe la domo de mia Patro estas multe da loĝejoj; se ne tiel estus, mi dirus al vi; mi iras, por pretigi por vi lokon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Kaj se mi iros kaj pretigos por vi lokon, mi revenos kaj ricevos vin al mi mem, por ke vi ankaŭ estu tie, kie mi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'Kaj kien mi iras, vi scias, kaj vi konas la vojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Tomaso diris al li: Sinjoro, ni ne scias, kien vi iras; kiel ni konas la vojon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Jesuo diris al li: Mi estas la vojo kaj la vero kaj la vivo; neniu venas al la Patro krom per mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Se vi min konus, vi konus ankaŭ mian Patron; kaj de nun vi konas Lin kaj Lin vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Filipo diris al li: Sinjoro, montru al ni la Patron, kaj por ni tio sufiĉos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Jesuo diris al li: Ĉu mi estas kun vi tiel longan tempon, kaj vi min ne konas, Filipo? tiu, kiu vidis min, vidis ankaŭ la Patron; kiel vi diras: Montru al ni la Patron?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Ĉu vi ne kredas, ke mi estas en la Patro kaj la Patro en mi? la vortojn, kiujn mi parolas al vi, mi parolas ne de mi mem; sed la Patro, restanta en mi, faras Siajn farojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Kredu al mi, ke mi estas en la Patro, kaj la Patro en mi; aŭ almenaŭ kredu al mi pro la faroj mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Vere, vere, mi diras al vi: Kiu kredas al mi, tiu ankaŭ faros la farojn, kiujn mi faras; kaj li faros pli grandajn ol tiuj, ĉar mi iras al la Patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'Kaj kion ajn vi petos en mia nomo, tion mi faros, por ke la Patro estu glorata en la Filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Se vi petos ion de mi en mia nomo, tion mi faros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Se vi min amas, vi observos miajn ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'Kaj mi petos la Patron, kaj Li donos al vi alian Parakleton, por ke li restadu kun vi por ĉiam;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'tiu estas la Spirito de la vero, kiun la mondo ne povas akcepti, ĉar ĝi lin ne vidas nek konas; vi lin konas, ĉar li restadas kun vi kaj estos en vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Mi ne lasos vin orfaj; mi venas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Ankoraŭ iom da tempo, kaj la mondo ne plu vidos min, sed vi vidos min; ĉar mi vivas, tial vi ankaŭ vivos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'En tiu tago vi scios, ke mi estas en mia Patro, kaj vi en mi, kaj mi en vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Kiu havas miajn ordonojn kaj observas ilin, tiu estas, kiu min amas; kaj kiu min amas, tiu estos amata de mia Patro, kaj mi amos lin, kaj elmontros min al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Judas (ne la Iskariota) diris al li: Sinjoro, kio okazis, ke vi elmontros vin al ni, kaj ne al la mondo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Jesuo respondis kaj diris al li: Se iu min amas, tiu observos mian vorton; kaj mia Patro lin amos; kaj ni venos al li kaj faros loĝon kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Kiu min ne amas, tiu ne observas miajn vortojn; kaj la vorto, kiun vi aŭdas, estas ne mia, sed de la Patro, kiu min sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Tion mi parolis al vi, dum mi ĉe vi restas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Sed la Parakleto, la Sankta Spirito, kiun la Patro sendos en mia nomo, instruos vin pri ĉio, kaj vin rememorigos pri ĉio, kion mi diris al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Pacon mi lasas al vi; mian pacon mi donas al vi; ne kiel la mondo donas, mi donas al vi. Ne maltrankviliĝu via koro, nek senkuraĝiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Vi aŭdis, ke mi diris al vi: Mi foriras, kaj mi revenas al vi. Se vi min amus, vi ĝojus pro tio, ke mi iras al la Patro, ĉar la Patro estas pli granda ol mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Kaj nun mi diris al vi, antaŭ ol ĝi okazos, por ke vi kredu, kiam ĝi okazos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'De nun mi jam ne multe parolos kun vi; ĉar la estro de la mondo venas; kaj li havas nenion en mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'sed por ke la mondo sciu, ke mi amas la Patron, kaj kiel la Patro ordonis al mi, tiel mi faras. Leviĝu; ni foriru de ĉi tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Mi estas la vera vinberarbo, kaj mia Patro estas la kultivisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Ĉiun nefruktodonan branĉon en mi Li forprenas; kaj ĉiun fruktodonan branĉon Li purigas, por ke ĝi donu pli da frukto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Jam vi estas puraj pro la vorto, kiun mi parolis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Restadu en mi, kaj mi en vi. Kiel la branĉo ne povas de si mem doni frukton, se ĝi ne restas en la vinberarbo, tiel ankaŭ vi ne povas, se vi ne restas en mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Mi estas la vinberarbo; vi estas la branĉoj; kiu restadas en mi, kaj mi en li, tiu donas multe da frukto; ĉar sen mi vi nenion povas fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Se iu ne restas en mi, tiu estas elĵetita, kiel la branĉo, kaj sekiĝas; kaj oni ilin kolektas kaj ĵetas en fajron, kaj ili brulas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Se vi restadas en mi, kaj miaj vortoj restadas en vi, petu kion ajn vi volos, kaj tio estos farita por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'En tio mia Patro estas glorata, ke vi donas multe da frukto; kaj vi estos miaj disĉiploj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Kiel la Patro min amis, tiel mi ankaŭ vin amis; restadu en mia amo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Se vi observos miajn ordonojn, vi restados en mia amo tiel same, kiel mi observis la ordonojn de mia Patro kaj restadas en Lia amo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Tion mi parolis al vi, por ke mia ĝojo en vi restadu, kaj via ĝojo estu plena.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Jen estas mia ordono: ke vi amu unu alian tiel same, kiel mi vin amis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Neniu havas amon pli grandan ol tio, ke iu demetus sian vivon por siaj amikoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Vi estas miaj amikoj, se vi faras tion, kion mi al vi ordonas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Mi jam ne nomas vin sklavoj, ĉar la sklavo ne scias, kion lia sinjoro faras; sed mi nomis vin amikoj, ĉar ĉion, kion mi aŭdis de mia Patro, mi sciigis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Vi ne elektis min, sed mi elektis vin, kaj starigis vin, por ke vi iru kaj donu frukton, kaj ke via frukto daŭru; por ke la Patro donu al vi ĉion ajn, kion vi petos de Li en mia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Tion mi ordonas al vi, por ke vi amu unu la alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Se la mondo malamas vin, vi scias, ke ĝi malamis min pli frue, ol vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Se vi estus el la mondo, la mondo amus siajn proprajn; sed ĉar vi ne estas el la mondo, kaj mi elektis vin for de la mondo, tial la mondo vin malamas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Memoru la vorton, kiun mi diris al vi: Sklavo ne estas pli granda ol lia sinjoro. Se ili min persekutis, vin ankaŭ ili persekutos; se ili observis mian vorton, ankaŭ vian ili observos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Sed ĉion ĉi tion ili faros al vi pro mia nomo, ĉar ili ne konas Tiun, kiu min sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Se mi ne estus veninta kaj parolinta al ili, ili ne havus pekon; sed nun ili ne havas pretekston por sia peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Tiu, kiu min malamas, malamas ankaŭ mian Patron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Se mi ne estus farinta inter ili farojn, kiajn neniu alia faris, ili ne havus pekon; sed nun ili vidis kaj malamis min kaj ankaŭ mian Patron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Sed tio okazas, por ke plenumiĝu la vorto skribita en ilia leĝo: Ili malamis min senkaŭze.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Sed kiam venos la Parakleto, kiun mi sendos de la Patro al vi, la Spirito de la vero, kiu devenas de la Patro, tiu pri mi atestos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'kaj vi ankaŭ atestas, ĉar vi estis kun mi de la komenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'Tion mi parolis al vi, por ke vi ne falpuŝiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Ili forpelos vin el la sinagogoj; eĉ venas la horo, kiam iu, kiu mortigos vin, opinios, ke li faras servon al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'Kaj tion ili faros pro tio, ke ili ne konis la Patron, nek min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Sed tion mi parolis al vi, por ke vi rememoru, kiam ĝia tempo venos, ke mi ĝin antaŭdiris al vi. Sed en la komenco mi ne diris al vi tion, ĉar mi estis kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Sed nun mi foriras al Tiu, kiu min sendis; kaj neniu el vi demandas min: Kien vi iras?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Sed ĉar mi tiel parolis al vi, malĝojo plenigis vian koron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Tamen mi diras al vi la veron: Estas bone por vi, ke mi foriros; ĉar se mi ne foriros, la Parakleto ne venos al vi; sed se mi foriros, mi sendos lin al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'Kaj kiam li alvenos, li pruvos la mondon kulpa rilate pekon kaj justecon kaj juĝon:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'rilate pekon, ĉar ili ne kredas al mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'rilate justecon, ĉar mi foriras al la Patro, kaj vi jam ne rigardas min;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'rilate juĝon, ĉar la estro de ĉi tiu mondo estas juĝita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Mi havas ankoraŭ multon por diri al vi, sed vi ne povas ĝin nun elporti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Tamen kiam venos li, la Spirito de la vero, li gvidos vin en ĉian veron; ĉar li parolos ne de si mem; sed kion ajn li aŭdos, tion li parolos; kaj li anoncos al vi venontajn aferojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Li gloros min, ĉar li ricevos el miaj kaj anoncos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Ĉio ajn, kion la Patro havas, estas mia; tial mi diris, ke li ricevos el miaj kaj anoncos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Mallongan tempon, kaj vi jam ne rigardas min; kaj denove mallongan tempon, kaj vi min vidos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Iuj do el liaj disĉiploj diris al aliaj: Kio estas ĉi tio, kion li diras al ni: Mallongan tempon, kaj vi ne rigardas min; kaj denove mallongan tempon, kaj vi min vidos; kaj: Ĉar mi foriras al la Patro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Ili do diris: Kio estas ĉi tio, kion li diras: Mallongan tempon? Ni ne komprenas lian diron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Jesuo ekvidis, ke ili deziras demandi lin, kaj li diris al ili: Ĉu vi serĉas inter vi klarigon pri tio, kion mi diris: Mallongan tempon, kaj vi ne rigardas min; kaj denove mallongan tempon, kaj vi min vidos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Vere, vere, mi diras al vi, ke vi ploros kaj lamentos, sed la mondo ĝojos; vi estos malĝojaj, sed via malĝojo fariĝos ĝojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Virino, kiam ŝi akuŝas, havas malĝojon, ĉar ŝia horo venis; sed kiam ŝi naskis la infaneton, ŝi jam ne memoras sian doloregon, pro ĝojo, ĉar homo naskiĝis en la mondon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Vi do ankaŭ havas nun malĝojon; sed mi revidos vin, kaj via koro ĝojos, kaj neniu forprenos de vi vian ĝojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'Kaj en tiu tago vi demandos min pri nenio. Vere, vere, mi diras al vi, se vi petos ion de la Patro, Li donos ĝin al vi en mia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Ĝis nun vi petis nenion en mia nomo; petu, kaj vi ricevos, por ke via ĝojo estu plena.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Ĉi tion mi parolis al vi alegorie; sed venas la horo, kiam mi jam ne parolos al vi alegorie, sed anoncos al vi malkaŝe pri la Patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'En tiu tago vi petos en mia nomo; kaj mi ne diras, ke mi petos de la Patro pro vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'ĉar la Patro mem vin amas tial, ke vi min amis, kaj kredis, ke mi elvenis de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Mi elvenis de la Patro, kaj alvenis en la mondon; denove mi lasas la mondon, kaj iras al la Patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Liaj disĉiploj diris: Jen nun vi parolas malkaŝe, kaj nenian alegorion diras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Nun ni scias, ke vi ĉion scias, kaj ne bezonas, ke iu demandu vin; pro tio ni kredas, ke vi elvenis de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Jesuo respondis al ili: Ĉu vi nun kredas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Jen venas la horo, kaj eĉ jam venis, kiam vi disiĝos, ĉiu al sia loko, kaj vi lasos min sola; kaj tamen mi ne estas sola, ĉar la Patro estas kun mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Tion mi parolis al vi, por ke en mi vi havu pacon. En la mondo vi havos suferadon; sed kuraĝu; mi venkis la mondon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Tion Jesuo parolis; kaj levinte la okulojn al la ĉielo, li diris: Patro, la horo venis; gloru Vian Filon, por ke la Filo Vin gloru;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'kiel Vi donis al li aŭtoritaton super ĉiu karno, por ke li donu eternan vivon al ĉiuj tiuj, kiujn Vi donis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Kaj jen estas la eterna vivo, ke ili konu Vin, la sole veran Dion, kaj tiun, kiun Vi sendis, Jesuon Kriston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Mi gloris Vin sur la tero, plenuminte la faron, kiun Vi donis al mi por fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'Kaj nun, ho Patro, gloru min kun Vi, per la gloro, kiun mi havis kun Vi, antaŭ ol la mondo ekzistis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Mi elmontris Vian nomon al la homoj, kiujn Vi donis al mi el la mondo; Viaj ili estis, kaj al mi Vi ilin donis; kaj ili konservis Vian vorton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Nun ili scias, ke ĉio ajn, kion Vi donis al mi, estas de Vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'ĉar mi donis al ili la vortojn, kiujn Vi donis al mi; kaj ili akceptis ilin, kaj scias vere, ke mi elvenis de Vi; kaj ili kredas, ke Vi min sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Mi preĝas por ili; mi preĝas ne por la mondo, sed por tiuj, kiujn Vi donis al mi, ĉar ili estas Viaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'kaj ĉio mia estas Via, kaj Via estas mia; kaj mi estas glorita per ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'Mi jam ne estas en la mondo, kaj ĉi tiuj estas en la mondo, kaj mi venas al Vi. Patro Sankta, gardu en Via nomo tiujn, kiujn Vi donis al mi, por ke ili estu unu tiel same, kiel ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Dum mi estis kun ili, mi konservis en Via nomo tiujn, kiujn Vi donis al mi; kaj mi gardis ilin, kaj neniu el ili pereis, krom la filo de perdiĝo, por ke plenumiĝu la Skribo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Sed nun mi venas al Vi; kaj tion mi parolas en la mondo, por ke ili havu mian ĝojon ĝis pleneco en si mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Mi donis al ili Vian vorton; kaj la mondo malamis ilin, ĉar ili ne estas el la mondo, kiel mi ne estas el la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Mi petas, ne ke Vi forigu ilin el la mondo, sed ke Vi gardu ilin kontraŭ la malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Ili ne estas el la mondo, kiel mi ne estas el la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Konsekru ilin en la vero; Via vorto estas vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Kiel Vi min sendis en la mondon, tiel ankaŭ mi ilin sendis en la mondon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'Kaj por ili mi konsekras min, por ke ili mem ankaŭ estu konsekritaj en la vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Kaj mi preĝas ne nur por ili, sed ankaŭ por tiuj, kiuj kredos al mi pro ilia vorto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'por ke ili ĉiuj estu unu; kiel Vi, Patro, estas en mi, kaj mi en Vi, tiel ili ankaŭ estu en ni; por ke la mondo kredu, ke Vi min sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'Kaj la gloron, kiun Vi donis al mi, mi donis al ili; por ke ili estu unu tiel same, kiel ni estas unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'mi en ili, kaj Vi en mi, por ke ili perfektiĝu en unu; por ke la mondo sciu, ke Vi min sendis, kaj ke Vi ilin amis, kiel Vi min amis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Patro, pri tiuj, kiujn Vi donis al mi, mi volas, ke ili ankaŭ estu kun mi tie, kie mi estas; por ke ili vidu mian gloron, kiun Vi donis al mi; ĉar Vi amis min antaŭ la fondo de la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Ho Patro justa, la mondo Vin ne konis, tamen mi Vin konis; kaj ĉi tiuj scias, ke Vi min sendis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'kaj al ili Vian nomon mi konigis kaj ankoraŭ konigos, por ke la amo, per kiu Vi amis min, estu en ili, kaj mi en ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Parolinte tiujn vortojn, Jesuo foriris kun siaj disĉiploj trans la torenton Kidron, kie estis ĝardeno, en kiun li eniris kune kun siaj disĉiploj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Kaj Judas, lia perfidanto, konis la lokon; ĉar Jesuo ofte venis tien kun siaj disĉiploj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Judas do, ricevinte la kohorton kaj oficistojn, senditajn de la ĉefpastroj kaj Fariseoj, venis tien kun lanternoj kaj torĉoj kaj bataliloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Jesuo do, sciante ĉion, kio venos al li, paŝis antaŭen, kaj diris al ili: Kiun vi serĉas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Ili respondis al li: Jesuon Nazaretan. Jesuo respondis: Mi estas tiu. Kaj Judas, lia perfidanto, staris kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Kiam do li diris al ili: Mi estas tiu, ili malantaŭen ekpaŝis kaj falis sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Tiam denove li demandis ilin: Kiun vi serĉas? Ili diris: Jesuon Nazaretan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Jesuo respondis: Mi ĵus diris al vi, ke mi estas tiu; se do vi min serĉas, lasu ĉi tiujn foriri;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'por ke plenumiĝu la vorto, kiun li diris: El tiuj, kiujn Vi donis al mi, mi perdis neniun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Simon Petro do, havante glavon, eltiris ĝin, kaj frapis sklavon de la ĉefpastro kaj detranĉis lian dekstran orelon. La nomo de la sklavo estis Malĥo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Jesuo do diris al Petro: Metu la glavon en ĝian ingon; la kalikon, kiun la Patro donis al mi, ĉu mi ne trinkos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'La kohorto kaj la milestro kaj la oficistoj de la Judoj kaptis do Jesuon kaj ligis lin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'kaj kondukis lin unue al Anas; ĉar ĉi tiu estis bopatro de Kajafas, kiu estis ĉefpastro en tiu jaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Kajafas estis tiu, kiu donis konsilon al la Judoj, ke estos bone, ke unu homo mortu por la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Kaj Simon Petro sekvis Jesuon, kaj ankaŭ alia disĉiplo. Ĉi tiu disĉiplo estis konata de la ĉefpastro, kaj eniris kun Jesuo en la korton de la ĉefpastro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'sed Petro staris ekstere apud la pordo. Kaj la alia disĉiplo, kiu estis konata de la ĉefpastro, eliris kaj parolis kun la pordistino, kaj enirigis Petron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'La sklavino pordistino diris al Petro: Ĉu vi ne estas ankaŭ el la disĉiploj de tiu homo? Li diris: Mi ne estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'La sklavoj kaj la oficistoj, farinte karban fajron (ĉar estis malvarme), staris kaj sin varmigis; Petro ankaŭ estis kun ili, starante kaj sin varmigante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'La ĉefpastro demandis Jesuon pri liaj disĉiploj kaj pri lia instruado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jesuo respondis al li: Mi parolis malkaŝe al la mondo; mi ĉiam instruis en la sinagogoj kaj en la templo, kie ĉiuj Judoj kunvenas; kaj sekrete mi nenion parolis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Kial vi min demandas? demandu tiujn, kiuj aŭdis, kion mi parolis al ili; ili ja scias, kion mi diris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Kaj kiam li parolis tion, unu el la apude starantaj oficistoj per la manplato frapis Jesuon, dirante: Ĉu tiel vi respondas al la ĉefpastro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Respondis Jesuo al li: Se mi malbone parolis, atestu pri la malbono; sed se bone, kial vi min frapas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Anas sendis lin ligitan al la ĉefpastro Kajafas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Simon Petro staris kaj sin varmigis. Oni do diris al li: Ĉu vi estas unu el liaj disĉiploj? Li neis, dirante: Mi ne estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Unu el la sklavoj de la ĉefpastro, estante parenco de tiu, kies orelon Petro detranĉis, diris: Ĉu mi ne vidis vin kun li en la ĝardeno?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Petro do denove neis; kaj tuj la koko ekkriis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Kaj oni kondukis Jesuon de Kajafas en la palacon; estis frumatene; kaj ili ne eniris en la palacon, por ke ili ne malpuriĝu, sed povu manĝi la Paskon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Pilato do eliris al ili, kaj diris: Kian akuzon vi prezentas kontraŭ ĉi tiu viro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Ili respondis kaj diris al li: Se li ne estus malbonfaranto, ni ne transdonus lin al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Pilato do diris al ili: Vi mem prenu lin, kaj juĝu lin laŭ via leĝo. La Judoj diris al li: Ne estas permesate al ni mortigi homon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'por ke plenumiĝu la vorto de Jesuo, kiun li parolis, montrante, per kia morto li mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Pilato do reeniris en la palacon, kaj alvokis Jesuon, kaj diris al li: Ĉu vi estas la Reĝo de la Judoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Jesuo respondis: Ĉu vi tion diras de vi mem, aŭ ĉu aliaj diris ĝin al vi pri mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Pilato respondis: Ĉu mi estas Judo? Via propra nacio kaj la ĉefpastroj transdonis vin al mi; kion vi faris?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Jesuo respondis: Mia regno ne estas el ĉi tiu mondo; se mia regno estus el ĉi tiu mondo, miaj servantoj bataladus, por ke mi ne transdoniĝu al la Judoj; sed nun mia regno ne estas el ĉi tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Pilato demandis lin: Ĉu vi do estas reĝo? Jesuo respondis: Vi diras, ke mi estas reĝo. Por tio mi naskiĝis kaj venis en la mondon, ke mi atestu pri la vero. Ĉiu, kiu estas el la vero, aŭskultas mian voĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Pilato diris al li: Kio estas la vero? Kaj dirinte tion, li eliris denove al la Judoj, kaj diris al ili: Mi trovas en li nenian kulpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'Sed estas ĉe vi kutime, ke mi liberigu al vi unu dum la Pasko: ĉu vi do volas, ke mi liberigu al vi la Reĝon de la Judoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Kaj ili kriis denove, dirante: Ne ĉi tiun, sed Barabason. Barabas estis rabisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Tiam do Pilato prenis Jesuon kaj lin skurĝigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Kaj la soldatoj plektis kronon el dornoj kaj metis ĝin sur lian kapon, kaj vestis lin per purpura mantelo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'kaj venis al li, kaj diris: Saluton, Reĝo de la Judoj! kaj ili frapis lin per la manplatoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Pilato do denove eliris, kaj diris al ili: Jen mi elkondukas lin al vi, por ke vi sciu, ke mi trovas en li nenian kulpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Jesuo do eliris, portante la dornan kronon kaj la purpuran mantelon. Pilato diris al ili: Jen la homo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Kiam do la ĉefpastroj kaj oficistoj lin vidis, ili kriis: Krucumu, krucumu lin. Pilato diris al ili: Mem prenu lin kaj krucumu lin, ĉar mi trovas en li nenian kulpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'La Judoj respondis al li: Ni havas leĝon, kaj laŭ tiu leĝo li devas morti tial, ke li pretendis esti Filo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Kiam do Pilato aŭdis tiun diron, li des pli timis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'kaj reenirinte en la palacon, li diris al Jesuo: De kie vi estas? Sed Jesuo nenion respondis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Tiam diris Pilato al li: Ĉu vi ne parolas al mi? ĉu vi ne scias, ke mi havas povon krucumi vin, kaj povon liberigi vin?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Jesuo respondis: Vi havus nenian povon kontraŭ mi, se ĝi ne estus donita al vi de supre; tial tiu, kiu transdonis min al vi, havas la pli grandan pekon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Ĉe tio Pilato penis liberigi lin; sed la Judoj kriis, dirante: Se vi liberigos tiun, vi ne estas amiko de Cezaro; ĉiu, kiu pretendas esti reĝo, parolas kontraŭ Cezaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Kiam do Pilato aŭdis tiun vorton, li elkondukis Jesuon, kaj sidiĝis sur tribunala seĝo en loko nomata La Pavimo, sed en la Hebrea lingvo Gabata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Estis la Preparado de la Pasko, ĉirkaŭ la sesa horo. Kaj li diris al la Judoj: Jen via Reĝo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Ili kriegis: Forigu, forigu, krucumu lin. Pilato diris al ili: Ĉu mi krucumu vian Reĝon? La ĉefpastroj respondis: Ni ne havas reĝon krom Cezaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Tiam do li transdonis lin al ili, por esti krucumita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'Kaj ili prenis Jesuon; kaj li eliris, portante sian krucon, al la loko nomata Loko de Kranio, kiu estas en la Hebrea lingvo Golgota;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'tie ili krucumis lin, kaj kun li du aliajn, ĉiuflanke po unu, kaj Jesuon meze.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Kaj Pilato ankaŭ skribis titolon, kaj surmetis ĝin sur la krucon. Kaj estis skribite: JESUO NAZARETA, LA REĜO DE LA JUDOJ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Tiun titolon multaj el la Judoj legis; ĉar la loko, kie Jesuo estis krucumita, estis proksime de la urbo; kaj ĝi estis skribita Hebree kaj Latine kaj Greke.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Tiam la ĉefpastroj de la Judoj diris al Pilato: Ne skribu: La Reĝo de la Judoj; sed, ke li diris: Mi estas Reĝo de la Judoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Respondis Pilato: Kion mi skribis, tion mi skribis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Kaj la soldatoj, kiam ili krucumis Jesuon, prenis liajn vestojn, kaj dividis ilin en kvar partojn, po unu parto por ĉiu soldato; kaj la tunikon; sed la tuniko estis senkudra, desupre teksita tra la tuto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Ili do diris unu al alia: Ni ne disŝiru ĝin, sed lotu pri ĝi, kies ĝi estos; por ke plenumiĝu la Skribo, kiu diras: Ili dividis miajn vestojn inter si, Pri mia tuniko ili lotis. Tion la soldatoj faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'Sed apud la kruco de Jesuo staris lia patrino, kaj la fratino de lia patrino, Maria, la edzino de Klopas, kaj Maria Magdalena.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Jesuo, rigardante sian patrinon, kaj la apudstarantan disĉiplon, kiun li amis, diris al sia patrino: Virino, jen via filo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Tiam li diris al la disĉiplo: Jen via patrino! Kaj de post tiu horo la disĉiplo akceptis ŝin en sian domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Jesuo, sciante, ke ĉio jam finiĝis, por ke plenumiĝu la Skribo, diris: Mi soifas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Kuŝis tie vazo plena de vinagro; oni do metis spongon, plenigitan per la vinagro, sur hisopon, kaj levis ĝin al lia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Kiam do Jesuo ricevis la vinagron, li diris: Estas finite; kaj, klininte sian kapon, li ellasis for la spiriton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'La Judoj, ĉar estis la Preparado, por ke la korpoj ne restadu sur la krucoj dum la sabato (ĉar la tago de tiu sabato estis granda tago), petis Pilaton, ke oni rompu iliajn krurojn, kaj forportu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Tiam la soldatoj venis, kaj rompis la krurojn de la unua kaj de la alia krucumita kun li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'sed kiam ili venis al Jesuo, kaj vidis, ke li jam mortis, ili ne rompis liajn krurojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'tamen unu el la soldatoj per lanco pikis lian flankon, kaj tuj elvenis sango kaj akvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'Kaj la vidinto atestis, kaj vera estas lia atesto; kaj li scias, ke li diras la veron, ke vi ankaŭ kredu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Ĉar tio okazis, por ke plenumiĝu la Skribo: Osto en li ne estos rompita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'Kaj ankoraŭ alia Skribo diras: Ili rigardos tiun, kiun ili trapikis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Post tio, Jozef el Arimateo, kiu estis disĉiplo de Jesuo, sed sekrete pro timo antaŭ la Judoj, petis Pilaton, ke li povu forpreni la korpon de Jesuo; kaj Pilato permesis. Li do venis kaj forprenis lian korpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Venis ankaŭ Nikodemo (tiu, kiu unue venis al Jesuo nokte), portanta miksaĵon de mirho kaj aloo, ĉirkaŭ cent funtoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Ili do prenis la korpon de Jesuo, kaj ĉirkaŭvindis ĝin per tolaĵoj kun aromaĵoj, laŭ la kutimo de la Judoj por entombigo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'Kaj estis ĝardeno en la loko, kie li estis krucumita, kaj en la ĝardeno nova tombo, en kiun ankoraŭ neniu estis metita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Tien do, pro la Preparado de la Judoj (ĉar la tombo estis proksima) ili enmetis Jesuon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'La unuan tagon de la semajno Maria Magdalena venis frue, dum estis ankoraŭ mallume, al la tombo, kaj vidis la ŝtonon prenita for de la tombo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Ŝi do kuris kaj venis al Simon Petro kaj al tiu alia disĉiplo, kiun Jesuo amis, kaj ŝi diris al ili: Oni forprenis el la tombo la Sinjoron, kaj ni ne scias, kien oni lin metis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Eliris do Petro kaj la alia disĉiplo, kaj iris al la tombo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Kaj ambaŭ ekkuris kune; kaj la alia disĉiplo kuris antaŭen pli rapide ol Petro, kaj unua alvenis al la tombo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'kaj kliniĝinte, li enrigardis, kaj vidis la tolaĵojn kuŝantajn; tamen li ne eniris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Kaj poste venis Simon Petro, sekvante lin, kaj eniris en la tombon; kaj li vidis la tolaĵojn kuŝantajn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'kaj la viŝtukon, kiu estis sur lia kapo, ne kuŝantan kun la tolaĵoj, sed kunvolvitan en aparta loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Tiam eniris do la alia disĉiplo, kiu unua alvenis al la tombo, kaj li vidis kaj kredis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Ĉar ili ankoraŭ ne komprenis la Skribon, ke li devas releviĝi el la mortintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Kaj la disĉiploj iris returne hejmen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Sed Maria staris ekstere apud la tombo, plorante; kaj dum ŝi ploris, ŝi kliniĝis, kaj enrigardis en la tombon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'kaj ŝi vidis du anĝelojn en blankaj vestoj, sidantajn, unu ĉe la kaploko kaj unu ĉe la piedloko, kie la korpo de Jesuo antaŭe kuŝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'Kaj ili diris al ŝi: Virino, kial vi ploras? Ŝi respondis: Ĉar oni forprenis mian Sinjoron, kaj mi ne scias, kien oni lin metis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'Dirinte tion, ŝi sin turnis malantaŭen, kaj vidis Jesuon staranta, kaj ne sciis, ke ĝi estas Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Jesuo diris al ŝi: Virino, kial vi ploras? kiun vi serĉas? Ŝi, supozante, ke li estas la ĝardenisto, diris al li: Sinjoro, se vi forportis lin, sciigu min, kien vi metis lin, kaj mi lin forprenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Jesuo diris al ŝi: Maria. Ŝi sin turnis, kaj diris al li Hebrelingve: Raboni; tio estas Majstro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Jesuo diris al ŝi: Ne tuŝu min; ĉar mi ankoraŭ ne supreniris al la Patro; sed iru al miaj fratoj, kaj diru al ili: Mi supreniras al mia Patro kaj via Patro, kaj al mia Dio kaj via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Maria Magdalena venis al la disĉiploj, sciigante: Mi vidis la Sinjoron; kaj ke li tion diris al ŝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Kiam do estis vespero en tiu sama tago, la unua de la semajno, kaj kiam estis fermitaj la pordoj, kie la disĉiploj estis, pro timo antaŭ la Judoj, Jesuo venis kaj staris meze de ili, kaj diris al ili: Paco al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'Kaj dirinte tion, li montris al ili siajn manojn kaj sian flankon. La disĉiploj do ĝojis, vidante la Sinjoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Jesuo denove diris al ili: Paco al vi; kiel la Patro sendis min, tiel ankaŭ mi vin sendas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'Kaj dirinte tion, li elspiris sur ilin, kaj diris: Ricevu la Sanktan Spiriton:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'kies pekojn vi pardonos, al tiuj ili estas pardonitaj; kies vi retenos, ili estas retenitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Sed Tomaso, unu el la dek du, nomata Didimo, ne ĉeestis kun ili, kiam Jesuo venis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'La aliaj disĉiploj do diris al li: Ni vidis la Sinjoron. Sed li diris al ili: Se mi ne vidos en liaj manoj la truon de la najloj, kaj se mi ne metos mian fingron en la lokon de la najloj, kaj ne metos mian manon en lian flankon, mi tute ne kredos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'Kaj post ok tagoj la disĉiploj denove estis interne, kaj Tomaso kun ili. Kaj Jesuo venis, kiam la pordoj estis fermitaj, kaj staris en la mezo, kaj diris: Paco al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Tiam li diris al Tomaso: Etendu ĉi tien vian fingron kaj vidu miajn manojn; kaj etendu vian manon kaj enmetu ĝin en mian flankon; kaj ne estu nekredema, sed estu kredanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Tomaso respondis al li kaj diris: Mia Sinjoro kaj mia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Jesuo diris al li: Ĉar vi vidis min, vi kredas; feliĉaj estas tiuj, kiuj ne vidis, kaj tamen kredas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Jesuo faris antaŭ la disĉiploj multajn aliajn signojn, kiuj ne estas skribitaj en ĉi tiu libro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'sed ĉi tiuj estas skribitaj, por ke vi kredu, ke Jesuo estas la Kristo, la Filo de Dio, kaj ke kredante, vi havu vivon en lia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Post tio Jesuo denove sin montris al la disĉiploj apud la maro de Tiberias; kaj li montris sin jene.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Estis kune Simon Petro, kaj Tomaso, nomata Didimo, kaj Natanael el Kana Galilea, kaj la filoj de Zebedeo, kaj aliaj du el liaj disĉiploj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Simon Petro diris al ili: Mi iras, por fiŝkapti. Ili diris al li: Ni ankaŭ iras kun vi. Ili do eliris, kaj iris sur la ŝipon; kaj tiun nokton ili nenion kaptis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Sed ĉe la tagiĝo Jesuo staris sur la marbordo; tamen la disĉiploj ne sciis, ke ĝi estas Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Tiam Jesuo diris al ili: Infanoj, ĉu vi havas ian manĝaĵon? Ili respondis al li: Ne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'Kaj li diris al ili: Ĵetu la reton ĉe la dekstra flanko de la ŝipo, kaj vi trovos. Ili do ĝin elĵetis; kaj pro la multeco de la fiŝoj ili ne plu povis ĝin treni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Tiu disĉiplo, kiun Jesuo amis, diris al Petro: Ĝi estas la Sinjoro. Kiam do Simon Petro aŭdis, ke ĝi estas la Sinjoro, li alzonis al si sian kitelon (ĉar li estis nuda) kaj ĵetis sin en la maron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Sed la aliaj disĉiploj venis en la ŝipeto (ĉar ili estis ne malproksime de la tero, sed nur ĉirkaŭ ducent ulnoj), trenante la reton plenan de fiŝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Kaj kiam ili eliris sur la teron, ili vidis fajron karban aranĝitan tie, kaj fiŝon kuŝantan sur ĝi, kaj panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Jesuo diris al ili: Alportu el la fiŝoj, kiujn vi ĵus kaptis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Simon Petro iris sur la ŝipon, kaj tiris la reton al la tero, plenan de grandaj fiŝoj, cent kvindek tri; kaj kvankam estis tiel multaj, tamen la reto ne disŝiriĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Jesuo diris al ili: Venu, matenmanĝu. Kaj neniu el la disĉiploj kuraĝis lin demandi: Kiu vi estas? sciante, ke ĝi estas la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Jesuo venis kaj prenis la panon kaj donis al ili, kaj tiel same la fiŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'Tiu estas jam la tria fojo, kiam aperis Jesuo al siaj disĉiploj, post sia releviĝo el la mortintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Post la matenmanĝo Jesuo diris al Simon Petro: Simon, filo de Jona, ĉu vi amas min pli, ol tiuj? Li diris al li: Jes, Sinjoro; vi scias, ke mi vin amas. Li diris al li: Paŝtu miajn ŝafidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Li diris al li ankoraŭ la duan fojon: Simon, filo de Jona, ĉu vi min amas? Li diris al li: Jes, Sinjoro; vi scias, ke mi vin amas. Li diris al li: Zorgu pri miaj ŝafoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Li diris al li la trian fojon: Simon, filo de Jona, ĉu vi min amas? Petro ĉagreniĝis, ke li diris al li la trian fojon: Ĉu vi min amas? kaj respondis al li: Sinjoro, vi scias ĉion; vi scias, ke mi vin amas. Jesuo diris al li: Paŝtu miajn ŝafojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Vere, vere, mi diras al vi: Kiam vi estis juna, vi zonis vin, kaj iris, kien vi volis; sed kiam vi maljuniĝos, vi etendos viajn manojn, kaj alia vin zonos, kaj portos vin, kien vi ne volos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Tion li diris, montrante per aludo, per kia morto li gloros Dion. Kaj dirinte tion, li diris al li: Sekvu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Petro, sin turninte, vidis malantaŭe la disĉiplon, kiun Jesuo amis (kiu ankaŭ klinis sin al lia brusto dum la vespermanĝo, kun la diro: Sinjoro, kiu estas la perfidanta vin?).');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Petro do, vidinte lin, diris al Jesuo: Sinjoro, kaj kion pri ĉi tiu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Jesuo diris al li: Se mi volas, ke li restu, ĝis mi venos, kio estas al vi? vi sekvu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Tial inter la fratoj disiris la famo, ke tiu disĉiplo ne mortos; tamen Jesuo ne diris al li, ke li ne mortos, sed: Se mi volas, ke li restu, ĝis mi venos, kio estas al vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'Tiu estas la disĉiplo, kiu atestas pri tio kaj skribis tion: kaj ni scias, ke lia atesto estas vera.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Estas ankaŭ multaj aliaj faroj, kiujn Jesuo faris; kaj mi supozas, ke se ĉiu el ili estus skribita detale, la tuta mondo ne havus lokon por la skribotaj libroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'La unuan historion mi faris, ho Teofilo, pri ĉio, kion Jesuo komencis fari kaj instrui,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'ĝis la tago, kiam li estis akceptita supren, doninte ordonon per la Sankta Spirito al la apostoloj, kiujn li elektis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'al kiuj ankaŭ post sia suferado li montris sin vivanta per multaj pruvoj, dum kvardek tagoj aperante al ili kaj parolante pri la aferoj de la regno de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'kaj kunestante, li admonis ilin ne foriri el Jerusalem, sed atendi tiun promeson de la Patro, pri kiu (li diris) vi aŭdis de mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'ĉar kiel Johano baptis per akvo, vi baptiĝos per la Sankta Spirito post ne multe da tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Ili do, kunveninte, demandis lin, dirante: Sinjoro, ĉu en ĉi tiu tempo vi restarigas la regadon al Izrael?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Kaj li diris al ili: Ne apartenas al vi scii tempojn aŭ epokojn, kiujn la Patro rezervis en Sia aŭtoritato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'Sed vi ricevos povon, kiam la Sankta Spirito venos sur vin; kaj vi estos miaj atestantoj en Jerusalem kaj en la tuta Judujo kaj Samario kaj ĝis la plej malproksima parto de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Kaj tion dirinte, li suprenleviĝis, ankoraŭ dum ili rigardis, kaj nubo ricevis lin for de iliaj okuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Kaj dum ili fikse rigardis al la ĉielo, kiam li foriris, jen staris apud ili du viroj blanke vestitaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'kiuj ankaŭ diris: Viroj Galileanoj, kial vi staras rigardantaj al la ĉielo? ĉi tiu Jesuo, kiu estas prenita supren for de vi en la ĉielon, tiel same revenos, kiel vi vidis lin iranta en la ĉielon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Tiam ili iris returne al Jerusalem de la monteto nomata Olivarba, kiu estas proksime de Jerusalem, en la distanco de sabata vojaĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Kaj kiam ili envenis, ili supreniris en la supran ĉambron, kie loĝis Petro kaj Johano kaj Jakobo kaj Andreo, Filipo kaj Tomaso, Bartolomeo kaj Mateo, Jakobo, filo de Alfeo, kaj Simon, la Fervorulo, kaj Judas, filo de Jakobo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Ĉiuj ĉi tiuj unuanime persistis en preĝado kaj petado, kun la virinoj, kaj Maria, la patrino de Jesuo, kaj kun liaj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'Kaj en tiuj tagoj Petro, stariĝinte meze de la fratoj, diris (kaj multego da personoj estis kune, ĉirkaŭ cent dudek):');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'Fratoj, estis necese, ke plenumiĝu tiu Skribo, kiun la Sankta Spirito antaŭparolis per la buŝo de David pri Judas, kiu fariĝis gvidanto al tiuj, kiuj kaptis Jesuon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Ĉar li estis kalkulita inter ni kaj ricevis sian parton en ĉi tiu servado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, '(Tiu ja akiris kampon per la rekompenco de sia maljusteco, kaj falinte kapantaŭe, li diskrevis meze, kaj ĉiuj liaj internaĵoj elŝutiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'Kaj tio fariĝis sciata al ĉiuj loĝantoj en Jerusalem, tiel ke en ilia dialekto tiu kampo estas nomita Akeldama, tio estas, Kampo de Sango.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Ĉar estas skribite en la Psalmaro: Lia loĝejo dezertiĝu, Kaj en ĝi ne ekzistu loĝanto; kaj: Lian oficon ricevu alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'El tiuj viroj do, kiuj nin akompanis dum la tuta tempo, en kiu la Sinjoro Jesuo eniris kaj eliris inter ni,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'komencante de la bapto de Johano ĝis la tago, kiam li estis akceptita supren for de ni, unu devas esti atestanto kun ni pri lia releviĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'Kaj ili starigis du: Jozefon, nomatan Barsabas, kies alnomo estis Justo, kaj Mattiason.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'Kaj preĝante, ili diris: Vi, ho Sinjoro, kiu konas la korojn de ĉiuj, elmontru, kiun el ĉi tiuj du Vi elektis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'por ricevi la parton en ĉi tiu servado kaj apostoleco, de kiu Judas forfalis, por iri al sia propra loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'Kaj ili lotis pri tio, kaj la loto falis por Mattias; kaj li estis alkalkulita al la dek unu apostoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Kaj kiam venis la Pentekosta tago, ili ĉiuj estis unuanime en unu loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Kaj subite venis el la ĉielo sono kvazaŭ blovego de forta vento, kaj ĝi plenigis la tutan domon, kie ili sidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'Kaj al ili aperis disirantaj langoj kvazaŭ el fajro, kaj sidiĝis sur ĉiun el ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'Kaj ĉiuj pleniĝis de la Sankta Spirito, kaj komencis paroli aliajn lingvojn, kiel la Spirito donis al ili parolpovon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Kaj en Jerusalem tiam loĝis piaj Judoj el ĉiu nacio sub la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Kaj kiam aŭdiĝis tiu sono, la homamaso kunvenis kaj miregis, ĉar ĉiu aparte aŭdis ilin paroli per lia propra dialekto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Kaj ĉiuj konfuziĝis kaj miris, dirante unu al alia: Rigardu! ĉu ne estas Galileanoj ĉiuj tiuj parolantoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Kiel do ni aŭdas ĉiu en sia dialekto, en kiu ni naskiĝis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Partoj kaj Medoj kaj Elamanoj, kaj loĝantoj en Mezopotamio, Judujo, Kapadokio, Ponto kaj Azio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'Frigio kaj Pamfilio, Egiptujo kaj la partoj de Libio apud Kireno, kaj pasloĝantaj Romanoj, Judoj kaj prozelitoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Kretanoj kaj Araboj-ni aŭdas ilin paroli en niaj lingvoj la mirindaĵojn de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Kaj ĉiuj konfuziĝis kaj embarasiĝis, dirante unu al alia: Kion ĉi tio signifas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Sed aliaj moke diris: Ili estas plenaj de mosto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Sed Petro, stariĝinte kun la dek unu, levis sian voĉon kaj parolis al ili, dirante: Ho Judoj kaj ĉiuj loĝantaj en Jerusalem, ĉi tio estu al vi sciata, kaj aŭskultu miajn vortojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Ĉar ĉi tiuj ne estas ebriaj, kiel vi supozas, ĉar estas la tria horo de la tago;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'sed jen tio, kio estis dirita per la profeto Joel:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, 'Kaj en la lasta tempo, diras Dio, Mi elverŝos Mian spiriton sur ĉiun karnon; Kaj viaj filoj kaj viaj filinoj profetos, Kaj viaj junuloj havos viziojn, Kaj viaj maljunuloj havos sonĝojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'Kaj eĉ sur Miajn sklavojn kaj Miajn sklavinojn en tiu tempo Mi elverŝos Mian spiriton, Kaj ili profetos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'Kaj Mi donos miraklojn en la ĉielo supre, Kaj signojn sur la tero malsupre: Sangon, fajron, kaj vaporon de fumo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'La suno fariĝos malluma, Kaj la luno fariĝos sanga, Antaŭ ol venos la granda kaj majesta tago de la Eternulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'Kaj ĉiu, kiu vokos la nomon de la Eternulo, saviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Izraelidoj, aŭskultu la jenajn vortojn: Jesuon, la Nazaretanon, viron de Dio, elmontritan al vi per potencaĵoj kaj mirakloj kaj signoj, kiujn Dio faris per li meze de vi, kiel vi mem scias,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'lin, laŭ la difinita intenco kaj antaŭscio de Dio transdonitan, vi per la manoj de senleĝuloj krucumis kaj mortigis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'lin Dio levis, malliginte la suferojn de morto, ĉar estis neeble, ke li estu tenata de ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Ĉar David diris pri li: Ĉiam mi vidis la Eternulon antaŭ mi, Ĉar Li estas ĉe mia dekstra mano, por ke mi ne falu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Tial ĝojis mia koro, raviĝis mia lango, Eĉ mia karno ripozas en espero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'Ĉar Vi ne lasos mian animon al Ŝeol, Vi ne permesos, ke Via sanktulo forputru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Vi konigis al mi la vojojn de la vivo, Vi plenigos min per ĝojo antaŭ Vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Fratoj, mi povas libere paroli al vi pri la patriarko David, ke li mortis kaj estis enterigita, kaj lia tombo estas ĉe ni ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Estante do profeto, kaj sciante, ke Dio ĵuris al li per ĵuro, sidigi sur lia trono iun el la frukto de liaj lumboj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'li, antaŭvidante, parolis pri la relevo de la Kristo, ke li ne estos lasita al Ŝeol, kaj lia karno ne forputros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Ĉi tiun Jesuon relevis Dio, pri kio ni ĉiuj estas atestantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Levite do ĝis dekstre de Dio, kaj ricevinte de la Patro la promeson de la Sankta Spirito, li elverŝis tion, kion vi vidas kaj aŭdas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Ĉar David ne supreniris en la ĉielojn; sed li mem diris: La Eternulo diris al mia Sinjoro: Sidu dekstre de Mi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'Ĝis Mi faros viajn malamikojn benketo por viaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Kun certeco do sciu la tuta domo de Izrael, ke tiun Jesuon, kiun vi krucumis, Dio faris Sinjoro kaj Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'Kaj aŭdinte tion, ili estis pikitaj en la koro, kaj diris al Petro kaj la aliaj apostoloj: Kion ni faru, fratoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Kaj Petro diris al ili: Ekpentu, kaj baptiĝu ĉiu el vi en la nomo de Jesuo Kristo por forigo de pekoj, kaj vi ricevos la donacon de la Sankta Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Ĉar la promeso estas por vi kaj por viaj infanoj, kaj por ĉiuj ĝis malproksime, kiujn alvokos la Eternulo, nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'Kaj per multaj aliaj paroloj li atestis kaj alvokis ilin, dirante: Savu vin el ĉi tiu perversa generacio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Tiuj do, kiuj akceptis lian parolon, baptiĝis, kaj en tiu tago aldoniĝis ĉirkaŭ tri mil animoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'Kaj ili persistis en la instruo de la apostoloj kaj en la kunuleco, en la dispecigo de pano kaj en preĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'Kaj ĉiu animo havis timon, kaj multaj mirakloj kaj signoj fariĝis per la apostoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'Kaj ĉiuj kredantoj estis kune, kaj havis ĉion komuna;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'kaj ili vendis siajn havojn kaj posedaĵojn, kaj dividis ilin al ĉiuj laŭ ĉies aparta bezono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'Kaj ĉiutage, vizitadante unuanime la templon, kaj dispecigante panon dome, ili prenis sian nutraĵon kun ĝojo kaj unueco de koro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'laŭdante Dion kaj havante favoron ĉe la tuta popolo. Kaj la Sinjoro aldonis ĉiutage al la eklezio la savatojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Kaj Petro kaj Johano estis suprenirantaj en la templon je la horo de preĝado, la naŭa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Kaj unu viro, lama de la patrina ventro, estis portata; oni lin metis ĉiutage apud tiu pordego de la templo, kiu estas nomata La Bela, por ke li petu pri almozoj la enirantojn en la templon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'tiu, vidante Petron kaj Johanon enirontajn en la templon, petis almozon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Kaj Petro, fikse rigardante lin, kun Johano, diris: Rigardu nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Kaj li atentis ilin, atendante ricevi ion de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Kaj Petro diris: Nek arĝentaĵon nek oraĵon mi havas, sed kion mi havas, tion mi donas al vi. En la nomo de Jesuo Kristo, la Nazaretano, piediru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'Kaj li prenis lin per la dekstra mano kaj lin levis; kaj tuj liaj plandoj kaj liaj maleolostoj fortiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'Kaj li suprensalte stariĝis, kaj piediris; kaj li eniris kun ili en la templon, piedirante kaj saltante, kaj laŭdante Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Kaj la tuta popolo vidis lin piedirantan kaj laŭdantan Dion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'kaj ili rekonis lin, ke li estas tiu, kiu sidis por almozo apud la Bela Pordego de la templo, kaj ili pleniĝis de mirego kaj konfuziĝo pri tio, kio okazis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Kaj dum li tenis Petron kaj Johanon, la tuta popolo kunkuris al ili en la portiko nomata Salomona, miregante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Kaj Petro, vidante tion, respondis al la popolo: Izraelidoj, kial vi miras pri ĉi tio? kaj kial vi fikse rigardas nin, kvazaŭ per propra potenco aŭ pieco ni igis lin piediri?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'La Dio de Abraham kaj de Isaak kaj de Jakob, la Dio de niaj patroj, gloris Sian Servanton Jesuo, kiun vi transdonis, kaj malkonfesis antaŭ la vizaĝo de Pilato, kiam ĉi tiu decidis liberigi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Sed vi malkonfesis la Sanktulon kaj Justulon, kaj petis, ke mortiginto estu donita al vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'kaj mortigis la Estron de la vivo, kiun Dio relevis el la mortintoj, pri kio ni estas atestantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'Kaj lia nomo, per fido en lia nomo, fortigis ĉi tiun, kiun vi vidas kaj konas; kaj la fido, kiu estas per li, donis al li ĉi tiun plensanecon antaŭ vi ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Kaj nun, fratoj, mi scias, ke vi agis de nescio, kiel ankaŭ viaj regantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Sed tiel Dio plenumis tion, kion Li antaŭanoncis per la buŝo de ĉiuj profetoj, ke Lia Kristo suferos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'Pentu do, kaj konvertiĝu, por ke viaj pekoj estu forviŝitaj, por ke venu tempoj de refreŝiĝo de la vizaĝo de la Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'kaj por ke Li sendu la por vi difinitan Kriston, Jesuon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'kiun la ĉielo devas ricevi ĝis la tempoj de restarigo de ĉio, pri kiuj parolis Dio per la buŝo de Siaj sanktaj profetoj jam de antikva tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Ĉar Moseo diris: Profeton el viaj fratoj, similan al mi, starigos por vi la Eternulo, via Dio; lin aŭskultu pri ĉio ajn, kion li al vi parolos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'Kaj ĉiu animo, kiu ne aŭskultos tiun profeton, ekstermiĝos el la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Kaj ĉiuj profetoj de post Samuel kaj liaj posteuloj, kiuj parolis, antaŭanoncis ankaŭ tiujn tagojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Vi estas la filoj de la profetoj, kaj de la interligo, kiun Dio faris kun viaj patroj, dirante al Abraham: Kaj beniĝos per via idaro ĉiuj gentoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Al vi unue Dio, relevinte Sian Servanton, sendis lin, por vin beni, deturnante ĉiun el vi for de liaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Kaj dum ili parolis al la popolo, venis sur ilin la ĉefpastroj, la kapitano de la templo, kaj la Sadukeoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'ĉagrenate, ke ili instruas la popolon kaj proklamas per Jesuo la releviĝon el la mortintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'Kaj ili metis sur ilin la manojn, kaj metis ilin en gardejon ĝis la sekvanta tago; ĉar estis jam vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Tamen multaj el tiuj, kiuj aŭdis la vorton, kredis; kaj la nombro de la viroj estis proksimume kvin mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Kaj en la sekvanta tago kunvenis en Jerusalem la regantoj kaj pliaĝuloj kaj skribistoj');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'kaj Anas, la ĉefpastro, kaj Kajafas kaj Johano kaj Aleksandro, kaj ĉiuj, kiuj estis de la ĉefpastra parencaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'Kaj stariginte ilin en la mezo, tiuj demandis: Per kia potenco aŭ per kia nomo vi faris tion?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Tiam Petro, plenigite de la Sankta Spirito, diris al ili: Regantoj de la popolo kaj pliaĝuloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'se ni hodiaŭ estas eldemandataj pri la bonfaro al la senfortulo, per kio li resaniĝis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'estu sciate al vi ĉiuj kaj al la tuta popolo Izraela, ke en la nomo de Jesuo Kristo, la Nazaretano, kiun vi krucumis, kiun Dio levis el la mortintoj, ĉi tiu staras sana antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Tiu estas la ŝtono, kiun vi konstruantoj malŝatis, kaj kiu fariĝis ŝtono bazangula.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'Kaj en neniu alia estas savo; ĉar ne estas sub la ĉielo alia nomo, donita inter homoj, per kiu ni devas esti savitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Sed kiam ili rimarkis la kuraĝon de Petro kaj Johano, kaj komprenis, ke ili estas malkleruloj kaj nesciuloj, ili miris, kaj rekonis ilin, ke ili estis kun Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Kaj vidante la resanigiton starantan apud tiuj, ili ne havis, kion kontraŭdiri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Sed ordoninte ilin foriri el la sinedrio, ili interkonsiliĝis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'dirante: Kion ni devas fari al ĉi tiuj homoj? ĉar estas videble por ĉiuj loĝantoj en Jerusalem, ke rimarkinda signo fariĝis per ili, kaj nei ĝin ni ne povas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Sed por ke ĝi ne plu disvastiĝu inter la popolo, ni minacu ilin, ke ili de nun ne parolu al iu ajn en ĉi tiu nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'Kaj ili vokis ilin, kaj ordonis al ili tute ne paroli nek instrui en la nomo de Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Sed Petro kaj Johano responde diris al ili: Ĉu estas juste antaŭ Dio aŭskulti vin prefere ol Dion, vi juĝu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'ĉar ni ne povas ne paroli pri tio, kion ni vidis kaj aŭdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Kaj ili, denove minacinte, liberigis ilin, trovinte nenion, pro kio ili povus ilin puni, pro la popolo; ĉar ĉiuj gloris Dion pro la faritaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Ĉar estis pli ol kvardekjara la viro, sur kiu fariĝis ĉi tiu signo resaniga.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Kaj liberigite, ili venis al siaj kunuloj kaj rakontis ĉion, kion la ĉefpastroj kaj pliaĝuloj diris al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Kaj aŭdinte, ili levis la voĉon al Dio unuanime, kaj diris: Ho Plejpotenculo, kiu faris la ĉielon kaj la teron kaj la maron, kaj ĉion, kio estas en ili,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'kaj kiu per la Sankta Spirito, per la buŝo de nia patro David, Via servanto, diris: Kial tumultas popoloj, Kaj gentoj pripensas vanaĵon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Leviĝis la reĝoj de la tero, Kaj la regantoj kolektiĝis kune, Kontraŭ la Eternulo kaj kontraŭ Lia Sanktoleito;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'ĉar vere en ĉi tiu urbo kolektiĝis kontraŭ Via sankta Servanto Jesuo, kiun Vi sanktoleis, kune Herodo kaj Pontio Pilato kun la gentoj kaj la popoloj de Izrael,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'por fari ĉion, kion Via mano kaj Via intenco antaŭdifinis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'Kaj nun, ho Eternulo, rigardu iliajn minacojn; kaj donu al Viaj sklavoj paroli Vian vorton kun plena kuraĝo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'dum Vi etendos Vian manon por sanigado, kaj signoj kaj mirakloj fariĝos per la nomo de Via sankta Servanto Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'Kaj post ilia preĝado skuiĝis la loko, en kiu ili kolektiĝis; kaj ili ĉiuj pleniĝis de la Sankta Spirito, kaj parolis kuraĝe la vorton de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Kaj la anaro de la kredantoj estis unukora kaj unuanima, kaj neniu diris, ke io el lia havaĵo estas propra al li; sed ĉe ili ĉio estis komuna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'Kaj kun granda potenco la apostoloj atestis pri la releviĝo de la Sinjoro Jesuo; kaj granda graco estis sur ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Inter ili neniu havis mankon, ĉar ĉiuj posedantoj de bienoj aŭ domoj vendis ilin, kaj alportis la prezon de la venditaĵoj');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'kaj metis ĝin antaŭ la piedoj de la apostoloj; kaj estis disdonate al ĉiu laŭ ĉies aparta bezono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'Kaj Jozef, kiu de la apostoloj estis alnomita Barnabas (tio estas, Filo de Konsolo), Levido, Kiprano laŭ sia naskiĝo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'posedante kampon, vendis ĝin, kaj alportis la prezon kaj metis ĝin antaŭ la piedoj de la apostoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Sed unu viro, nomata Ananias, kun sia edzino Sapfira vendis posedaĵon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'kaj retenis iom el la prezo, kun la konsento de sia edzino, kaj iun parton alportis kaj metis antaŭ la piedoj de la apostoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Sed Petro diris: Ananias, kial Satano plenigis vian koron tiel, ke vi mensogas al la Sankta Spirito kaj retenas iom el la prezo de la bieno?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Dum ĝi restis, ĉu ĝi ne estis via? kaj post la vendo, ĉu ĝi ne estis en via rajto? Kial do ĉi tiun faron vi celis en via koro? vi mensogis ne al homoj, sed al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Kaj aŭdante ĉi tiujn vortojn, Ananias falis kaj senspiriĝis; kaj granda timo venis sur ĉiujn aŭdantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Kaj la junuloj leviĝis, kaj lin ĉirkaŭvindis, kaj forportis kaj enterigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Kaj post paso de ĉirkaŭ tri horoj eniris lia edzino, ne sciante, kio okazis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Kaj Petro ŝin demandis: Diru al mi, ĉu por tiom vi vendis la bienon? Kaj ŝi respondis: Jes, por tiom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Kaj Petro respondis al ŝi: Kial estis interkonsento inter vi, por inciti la Spiriton de la Eternulo? jen la piedoj de tiuj, kiuj enterigis vian edzon, estas apud la pordo, kaj ili vin forportos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'Kaj ŝi tuj falis apud liaj piedoj kaj senspiriĝis; kaj la junuloj eniris, kaj trovis ŝin mortinta, kaj ŝin forportis kaj enterigis apud ŝia edzo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'Kaj granda timo venis sur la tutan eklezion kaj sur ĉiujn aŭdantajn pri tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Kaj per la manoj de la apostoloj estis faritaj multaj signoj kaj mirindaĵoj meze de la popolo; kaj ili ĉiuj estis unuanime en la portiko Salomona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Sed el la ceteraj neniu kuraĝis aliĝi al ili; tamen la popolo gloris ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'kaj kredantoj pligrandnombre aldoniĝis al la Sinjoro, amasoj da viroj kaj virinoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'tiel, ke oni elportis la malsanulojn sur la stratojn kaj kuŝigis ilin sur litoj kaj kanapoj, por ke ĉe la preterpaso de Petro, almenaŭ lia ombro ombru iun el ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Kunvenis ankaŭ en Jerusalemon la amaso el la ĉirkaŭaj urboj, portante malsanulojn kaj la turmentatajn de malpuraj spiritoj, kaj ĉiuj estis sanigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Sed stariĝis la ĉefpastro, kaj ĉiuj, kiuj estis kun li (tio estas la sekto de la Sadukeoj), kaj ili pleniĝis de ĵaluzo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'kaj ĵetis manojn sur la apostolojn, kaj metis ilin en la publikan gardejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Sed anĝelo de la Eternulo nokte malfermis la pordojn de la karcero, kaj elkondukis ilin, kaj diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, 'Iru, kaj staru kaj parolu en la templo al la popolo ĉiujn vortojn pri ĉi tiu Vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'Kaj tion aŭdinte, ili eniris ĉe la tagiĝo en la templon kaj ekinstruis. Sed venis la ĉefpastro, kaj tiuj, kiuj estis kun li, kaj kunvokis la sinedrion kaj la tutan senaton de la Izraelidoj, kaj sendis al la malliberejo, por ilin venigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Sed la oficistoj venis, kaj ne trovis ilin en la karcero, kaj ili revenis kaj rakontis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'dirante: Ni ja trovis la malliberejon ŝlosita tute fortike, kaj la gardistojn starantaj antaŭ la pordoj; sed malferminte, ni trovis interne neniun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'Kiam do la kapitano de la templo kaj la ĉefpastroj aŭdis ĉi tiujn vortojn, ili embarasiĝis pri ili, kio fariĝos el tiu afero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'Tiam iu venis, kaj sciigis al ili: Jen la viroj, kiujn vi metis en la karceron, estas en la templo, kaj staras kaj instruas la popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Tiam foriris la kapitano kun la oficistoj, kaj alkondukis ilin sen perforto; ĉar ili timis la popolon, por ke ili ne estu priĵetitaj per ŝtonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'Kaj oni alkondukis ilin kaj starigis ilin antaŭ la sinedrio. Kaj la ĉefpastro ilin demandis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'dirante: Ni severe ordonis al vi, ke vi ne instruu en ĉi tiu nomo; kaj jen vi plenigis Jerusalemon per via instruado, kaj intencas survenigi sur nin la sangon de tiu homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Tiam Petro kaj la apostoloj responde diris: Oni devas obei Dion prefere ol homojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'La Dio de niaj patroj levis Jesuon, kiun vi pereigis, pendigante lin sur lignaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'Lin altigis Dio per Sia dekstra mano, por esti Estro kaj Savanto, por doni al Izrael penton kaj pardonadon de pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'Kaj ni estas atestantoj de ĉi tiuj vortoj, kiel ankaŭ estas la Sankta Spirito, kiun Dio donis al tiuj, kiuj Lin obeas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'Kaj ili, aŭdinte tion, estis pikitaj en la koro, kaj ili konsiliĝis, por pereigi ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Sed unu Fariseo, nomata Gamaliel, leĝinstruisto honorata ĉe la tuta popolo, ekstaris en la sinedrio, kaj ordonis, ke oni eksteren forigu la homojn por kelka tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'Kaj li diris al ili: Izraelidoj, estu singardaj rilate al ĉi tiuj homoj pri tio, kion vi celas fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Ĉar antaŭ ĉi tiuj tagoj leviĝis Teŭdas, dirante, ke li estas ia persono; kaj al li aliĝis nombro da viroj, ĉirkaŭ kvarcent; kaj li pereis; kaj ĉiuj, kiuj lin obeis, dispeliĝis kaj nuliĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Post tiu leviĝis Judas, Galileano, en la tagoj de la registrado, kaj fortiris post si homojn; li ankaŭ pereis, kaj ĉiuj, kiuj lin obeis, dispeliĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'Kaj nun mi diras al vi: Detenu vin de ĉi tiuj homoj, kaj lasu ilin; ĉar, se ĉi tiu intenco aŭ ĉi tiu laboro estas de homoj, ĝi renversiĝos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'sed se ĝi estas de Dio, vi ilin ne povos renversi; aŭ eble iel vi troviĝos batalantaj kontraŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'Kaj ili konsentis kun li; kaj alvokinte la apostolojn kaj batinte ilin, ili ordonis, ke ili ne parolu en la nomo de Jesuo, kaj liberigis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'Sed ili foriris de antaŭ la sinedrio, ĝojante, ke ili estis juĝitaj indaj suferi malhonoron pro la Nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'Kaj ĉiutage en la templo kaj dome ili ne ĉesis instrui kaj prediki Jesuon, la Kriston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'Kaj en tiuj tagoj, kiam la nombro de la disĉiploj multiĝis, fariĝis murmurado de la Grekaj Judoj kontraŭ la Hebreaj pro tio, ke iliaj vidvinoj estas preterlasataj en la ĉiutaga servado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Kaj la dek du, alvokinte la amason de la disĉiploj, diris: Ne estas dezirinde, ke ni forlasu la vorton de Dio, por servi ĉe tabloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Tial elserĉu, fratoj, el inter vi sep homojn, bone atestatajn, plenajn de la Spirito kaj de saĝo, kiujn ni difinos por tiu afero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'Sed ni persistos en preĝado kaj la servado de la Vorto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'Kaj tiu diro plaĉis al la tuta amaso; kaj ili elektis Stefanon, viron plenan de fido kaj de la Sankta Spirito, kaj Filipon kaj Proĥoron kaj Nikanoron kaj Timonon kaj Parmenason, kaj Nikolaon, prozeliton el Antioĥia;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'tiujn ili starigis antaŭ la apostoloj; kaj ĉi tiuj, preĝinte, metis sur ilin la manojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'Kaj la vorto de Dio kreskis, kaj la nombro de la disĉiploj multiĝis treege en Jerusalem, kaj granda aro el la pastroj obeis al la fido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Kaj Stefano, plena de graco kaj potenco, faris grandajn mirindaĵojn kaj signojn inter la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Sed stariĝis iuj el la sinagogo nomata la Sinagogo de la Liberigitoj, kaj el la Kirenanoj kaj el la Aleksandrianoj kaj el la homoj el Kilikio kaj Azio; kaj ili diskutis kun Stefano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Kaj ili ne povis rezisti al la saĝeco kaj la Spirito, per kiu li parolis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Tiam ili subinstigis virojn, kiuj diris: Ni aŭdis lin paroli blasfemajn vortojn kontraŭ Moseo kaj kontraŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'Kaj ili incitis la popolon kaj la pliaĝulojn kaj la skribistojn, kaj venis sur lin kaj kaptis lin, kaj kondukis lin al la sinedrio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'kaj starigis mensogajn atestantojn, kiuj diris: Ĉi tiu homo ne ĉesas paroli vortojn kontraŭ ĉi tiu sankta loko kaj la leĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'ĉar ni aŭdis lin diri, ke ĉi tiu Jesuo, la Nazaretano, detruos ĉi tiun lokon, kaj ŝanĝos la kutimojn, kiujn Moseo transdonis al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Kaj ĉiuj, kiuj sidis en la sinedrio, fikse rigardante lin, vidis lian vizaĝon kvazaŭ vizaĝon de anĝelo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Tiam diris la ĉefpastro: Ĉu ĉi tiuj aferoj estas tiel?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'Kaj tiu diris: Fratoj kaj patroj, aŭskultu. La Dio de gloro aperis al nia patro Abraham, kiam li estis en Mezopotamio, antaŭ ol li loĝis en Ĥaran,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'kaj diris al li: Iru el via lando kaj de via parencaro, kaj venu en tiun landon, kiun Mi montros al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Tiam li iris el la lando de la Ĥaldeoj, kaj loĝis en Ĥaran; kaj el tie, post la morto de lia patro, Li transloĝigis lin en ĉi tiun landon, kie vi nun loĝas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'kaj Li donis al li nenian heredaĵon en ĝi, eĉ ne piedspacon, sed Li promesis doni ĝin al li por posedaĵo kaj al lia idaro post li, kiam li ankoraŭ ne havis infanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Kaj Dio parolis jene: ke lia idaro loĝos en fremda lando, kaj ke oni sklavigos kaj turmentos ilin dum kvarcent jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Kaj la popolon, ĉe kiu ili estos sklavoj, Mi juĝos, diris Dio; kaj poste ili eliros kaj faros servon al Mi sur ĉi tiu loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'Kaj Li donis al li la interligon de cirkumcido; kaj tiel Abraham naskigis Isaakon kaj cirkumcidis lin en la oka tago, kaj Isaak naskigis Jakobon, kaj Jakob la dek du patriarkojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'Kaj la patriarkoj, enviante Jozefon, lin vendis en Egiptujon; kaj Dio estis kun li,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'kaj liberigis lin el ĉiuj liaj suferoj, kaj donis al li favoron kaj saĝecon antaŭ Faraono, reĝo de Egiptujo; kaj ĉi tiu estrigis lin super Egiptujo kaj super lia tuta domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Kaj venis malsato sur la tutan landon Egiptujon kaj Kanaanon, kaj granda sufero; kaj niaj patroj ne trovis nutraĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Sed kiam Jakob aŭdis, ke estas greno en Egiptujo, li sendis unue niajn patrojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'Kaj la duan fojon Jozef rekonatiĝis al siaj fratoj, kaj la gento de Jozef estis montrita al Faraono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Kaj Jozef sendis, kaj alvokis sian patron Jakob, kaj la tutan parencaron, sepdek kvin animojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'Kaj Jakob venis en Egiptujon, kaj mortis li mem kaj niaj patroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'kaj ili estis transportitaj al Ŝeĥem kaj metitaj en la tombon, kiun Abraham aĉetis por prezo arĝenta de la filoj de Ĥamor en Ŝeĥem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Sed kiam alproksimiĝis la tempo de la promeso, kiun Dio ĵuris al Abraham, la popolo diskreskis kaj multiĝis en Egiptujo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'ĝis aperis alia reĝo, kiu ne konis Jozefon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Tiu agis ruze kontraŭ nia gento, kaj premis niajn patrojn tiel, ke ili elĵetis siajn infanojn, por ke ili ne vivadu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'En tiu tempo Moseo naskiĝis, kaj estis eksterordinare bela; kaj li estis nutrata tri monatojn en la domo de sia patro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'kaj kiam oni lin elĵetis, prenis lin la filino de Faraono kaj lin nutris kiel sian filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'Kaj Moseo estis instruita en la tuta saĝeco de la Egiptoj, kaj estis potenca per siaj vortoj kaj agoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Sed kiam li jam havis la aĝon de kvardek jaroj, venis en lian koron la penso viziti siajn fratojn, la Izraelidojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'Kaj vidinte unu el ili suferi maljustecon, li defendis kaj venĝis la premiton, batante la Egipton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'kaj li supozis, ke liaj fratoj komprenos, ke Dio per lia mano donas al ili savon, sed ili ne komprenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Kaj en la sekvanta tago li aperis al ili, dum ili malpacis, kaj li deziris repacigi ilin, dirante: Ho viroj, vi estas fratoj; kial vi malbonfaras unu al alia?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Sed la ofendanto de sia proksimulo forpuŝis lin, dirante: Kiu faris vin estro kaj juĝanto super ni?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Ĉu vi celas mortigi min, kiel vi mortigis la Egipton hieraŭ?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'Kaj ĉe tiu parolo Moseo forkuris kaj ekloĝis en la lando Midjana, kie li naskigis du filojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'Kaj post paso de kvardek jaroj anĝelo aperis al li en la dezerto apud monto Sinaj, en flama fajro en arbetaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Kaj kiam Moseo ĝin vidis, li miris pri la fenomeno; kaj kiam li alproksimiĝis, por rigardi, venis al li voĉo de la Eternulo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, 'Mi estas la Dio de viaj patroj, la Dio de Abraham, kaj de Isaak, kaj de Jakob. Kaj Moseo tremis, kaj ne kuraĝis rigardi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Kaj la Eternulo diris al li: Deprenu la ŝuojn de viaj piedoj; ĉar la loko, sur kiu vi staras, estas tero sankta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Mi rigardis, kaj vidis la mizeron de Mia popolo, kiu estas en Egiptujo, kaj Mi aŭdis ĝian ĝemadon, kaj Mi malsupreniris, por savi ĝin; venu do, kaj Mi vin sendos en Egiptujon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Tiun Moseon, kiun ili malakceptis, dirante: Kiu faris vin estro kaj juĝanto? tiun Dio sendis, por esti estro kaj savanto, per la mano de la anĝelo, kiu aperis al li en la arbetaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'Tiu elkondukis ilin, farinte mirindaĵojn kaj signojn en Egiptujo, kaj en la Ruĝa Maro, kaj en la dezerto dum kvardek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'Ĝi estis tiu Moseo, kiu diris al la Izraelidoj: Profeton el viaj fratoj, similan al mi, starigos por vi la Eternulo, via Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'Li estis tiu, kiu estis en la komunumo en la dezerto kun la anĝelo, kiu parolis kun li sur la monto Sinaj, kaj estis kun niaj patroj; kaj ricevis vivajn orakolojn, por doni al ni;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'al tiu niaj patroj ne volis esti obeemaj, sed forpuŝis lin, kaj returniĝis en sia koro al Egiptujo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'dirante al Aaron: Faru al ni diojn, kiuj irus antaŭ ni; ĉar pri tiu Moseo, kiu elkondukis nin el la lando Egipta, ni ne scias, kio okazis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'Kaj ili faris bovidon en tiuj tagoj, kaj alportis oferon al la idolo, kaj ĝojis pri la faritaĵo de siaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'Tiam Dio turniĝis, kaj lasis ilin servi al la armeo de la ĉielo, kiel estas skribite en la libro de la profetoj: Ĉu vi alportis al Mi buĉitajn bestojn kaj oferojn Dum kvardek jaroj en la dezerto, ho domo de Izrael?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'Kaj vi portis la tabernaklon de Moleĥ Kaj la stelon de la dio Refan, La figuraĵojn, kiujn vi faris, por adorkliniĝi al ili; Kaj Mi elpatrujigos vin preter Babelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Kun niaj patroj en la dezerto estis la tabernaklo de atesto, kiel ordonis Tiu, kiu parolis al Moseo, ke li konstruu ĝin laŭ la modelo, kiun li vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'Ĝin ankaŭ niaj patroj siavice enportis kun Josuo, kiam ili eniris en la posedaĵon de la nacioj, kiujn Dio forpuŝis antaŭ niaj patroj, ĝis la tagoj de David;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'kiu trovis favoron antaŭ Dio, kaj petis trovi loĝejon por la Dio de Jakob.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'Sed Salomono konstruis por Li domon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Tamen la Plejaltulo ne loĝas en manfaritaj temploj, kiel diris la profeto:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, 'La ĉielo estas Mia trono, Kaj la tero estas Mia piedbenketo; Kian domon vi konstruos por Mi? diras la Eternulo; Kaj kia estas la loko por Mia ripozo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Ĉu ne faris Mia mano ĉion tion?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Vi malmolnukaj, vi necirkumciditaj je koro kaj oreloj, vi ĉiam rezistas al la Sankta Spirito; kiel viaj patroj, tiel ankaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Kiun el la profetoj viaj patroj ne persekutis? kaj ili mortigis tiujn, kiuj antaŭmontris pri la alveno de la Justulo, de kiu vi nun fariĝis la perfidintoj kaj mortigintoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'vi, kiuj ricevis la leĝon, kiel anoncitan per anĝeloj, sed ĝin ne observis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Kaj aŭdante tion, ili koleriĝis en la koro, kaj grincigis kontraŭ li siajn dentojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'Sed li, plena de la Sankta Spirito, rigardis fikse al la ĉielo, kaj vidis la gloron de Dio, kaj Jesuon starantan dekstre de Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'kaj diris: Jen mi vidas la ĉielon malfermitan kaj la Filon de homo starantan dekstre de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'Sed ili ekkriis per laŭta voĉo, kaj fermis siajn orelojn, kaj kuregis sur lin unuanime,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'kaj elpelis lin el la urbo, kaj ĵetis sur lin ŝtonojn; kaj la atestantoj demetis siajn vestojn apud la piedoj de junulo, nomata Saŭlo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'Kaj ili ŝtonmortigis Stefanon, vokantan kaj dirantan: Jesuo, Sinjoro, akceptu mian spiriton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'Kaj li genuiĝis, kaj kriis per laŭta voĉo: Sinjoro, ne metu sur ilin ĉi tiun pekon. Kaj tion dirinte, li endormiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Kaj Saŭlo konsentis al lia mortigo. Kaj en tiu tago komenciĝis granda persekutado kontraŭ la eklezio, kiu estis en Jerusalem; kaj ĉiuj estis dispelitaj tra la regionoj de Judujo kaj Samario, kun escepto de la apostolaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Kaj piuloj enterigis Stefanon, kaj faris pri li grandan funebron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Sed Saŭlo atakis la eklezion, enirante en ĉiun domon, kaj li trenis virojn kaj virinojn, kaj transdonis ilin en malliberejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Sed la dispelitoj trairis, predikante la vorton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Kaj Filipo, malsuprenirinte en la urbon Samario, proklamis al ili la Kriston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'Kaj la homamaso unuanime atentis la parolojn de Filipo, kiam ili lin aŭdis kaj vidis la signojn, kiujn li faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Ĉar el multaj el ili, kiuj havis malpurajn spiritojn, ĉi tiuj elvenis, kriante per laŭta voĉo; kaj multaj paralizuloj kaj lamuloj resaniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'Kaj estis granda ĝojo en tiu urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Sed unu viro, nome Simon, jam antaŭe faradis magion en la urbo kaj sorĉadis la popolon de Samario, dirante, ke li estas iu granda;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'al li atentadis ili ĉiuj, de la malgrandaj ĝis la grandaj, dirante: Ĉi tiu homo estas la granda potenco de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Kaj ili atentadis lin, ĉar li jam de longe sorĉis ilin per magiaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Sed kiam ili kredis al Filipo, predikanta la evangelion pri la regno de Dio kaj la nomo de Jesuo Kristo, ili baptiĝis, viroj kaj virinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Kaj Simon mem ankaŭ kredis; kaj kiam li baptiĝis, li forte aliĝis al Filipo, kaj vidante signojn kaj grandajn miraklojn farataj, li konfuziĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Kaj la apostoloj en Jerusalem, aŭdinte, ke Samario akceptis la vorton de Dio, sendis al ili Petron kaj Johanon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'kiuj, alveninte, preĝis por ili, ke ili ricevu la Sanktan Spiriton,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'ĉar ankoraŭ sur neniun el ili li falis; ili nur baptiĝis en la nomon de la Sinjoro Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Tiam ili metis la manojn sur ilin, kaj ili ricevis la Sanktan Spiriton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'Kaj kiam Simon vidis, ke la Sankta Spirito estis donata per la surmetado de la manoj de la apostoloj, li proponis al ili monon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'kaj diris: Donu ankaŭ al mi ĉi tiun rajton, por ke ĉiu ajn, sur kiun mi metos la manojn, ricevu la Sanktan Spiriton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Sed Petro diris al li: Via arĝentaĵo iru kun vi en pereon, ĉar vi pensis ricevi per mono la donacon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Vi havas nek parton nek loton en tiu afero, ĉar via koro ne estas rekta antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Pentu do pri tiu via malboneco, kaj preĝu al la Eternulo, se eble la penso de via koro estu pardonita al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Ĉar mi vidas, ke vi estas en la galo de maldolĉeco kaj en la kateno de maljusteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Kaj Simon responde diris: Preĝu vi al la Eternulo por mi, ke trafu min neniom el tio, pri kio vi parolis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Ili do, atestinte kaj parolinte la vorton de la Sinjoro, revenis al Jerusalem, kaj predikis la evangelion al multaj vilaĝoj de la Samarianoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Sed anĝelo de la Eternulo parolis al Filipo, dirante: Leviĝu, kaj iru suden ĝis la vojo, kiu kondukas de Jerusalem al Gaza; tio estas dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'Kaj li leviĝis, kaj ekiris; kaj jen viro, Etiopo, eŭnuko, potenculo sub Kandake, reĝino de la Etiopoj, kaj kiu estis super ŝia tuta trezoro, jam venis al Jerusalem, por adorkliniĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'tiu vojaĝis returne, kaj, sidante en sia ĉaro, legis la profeton Jesaja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'Kaj la Spirito diris al Filipo: Aliru, kaj aliĝu al tiu ĉaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'Kaj Filipo alkuris, kaj aŭdis lin legi la profeton Jesaja, kaj diris: Ĉu vi komprenas tion, kion vi legas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'Kaj tiu diris: Kiel mi povas, se neniu min gvidas? Kaj li petis Filipon, ke li supreniru kaj sidiĝu kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'La peco de la Skribo, kiun li legis, estis jena: Li estis kondukata kiel ŝafo al la buĉo; Kaj kiel ŝafido muta antaŭ sia tondanto, Li ne malfermis sian buŝon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'En lia humiliĝo lia juĝo estis deprenita; Pri lia generacio kiu rakontos? Ĉar lia vivo estas prenita for de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'Kaj la eŭnuko responde al Filipo diris: Mi petas vin, pri kiu parolis la profeto ĉi tion? ĉu pri si, aŭ pri iu alia?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Kaj Filipo malfermis sian buŝon, kaj komencante de tiu Skribo, predikis al li Jesuon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'Kaj dum ili iris sur la vojo, ili alvenis al iu akvo; kaj la eŭnuko diris: Jen estas akvo; kio malhelpas min baptiĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, 'Kaj Filipo diris: Se vi kredas per via tuta koro, tio estas permesata. Kaj li respondis: Mi kredas, ke Jesuo Kristo estas la Filo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'Kaj li ordonis, ke la ĉaro haltu, kaj ili ambaŭ malsupreniris en la akvon, Filipo kaj la eŭnuko; kaj li baptis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'Kaj kiam ili supreniris el la akvo, la Spirito de la Eternulo forkaptis Filipon; kaj la eŭnuko ne plu lin vidis, kaj li iris sian vojon, ĝojante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Sed Filipo troviĝis en Aŝdod; kaj trapasante, li predikis la evangelion en ĉiuj urboj, ĝis li alvenis en Cezarean.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Kaj Saŭlo, ankoraŭ spirante minacojn kaj mortigon kontraŭ la disĉiploj de la Sinjoro, iris al la ĉefpastro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'kaj petis de li leterojn al la sinagogoj en Damasko, por ke, se li eble trovos homojn, aliĝintajn al la Vojo, ĉu virojn aŭ virinojn, li alkonduku ilin katenitajn al Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'Kaj dum li vojaĝis, li alproksimiĝis al Damasko; kaj subite ekbrilegis ĉirkaŭ li lumo el la ĉielo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'kaj li falis sur la teron, kaj aŭdis voĉon dirantan al li: Saŭlo, Saŭlo, kial vi min persekutas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Kaj li diris: Kiu vi estas, ho Sinjoro? Kaj tiu diris: Mi estas Jesuo, kiun vi persekutas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'sed leviĝu, kaj eniru en la urbon, kaj estos dirite al vi, kion vi devas fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Kaj liaj kunvojaĝantoj staris mutaj, aŭdante la voĉon, sed vidante neniun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Kaj Saŭlo leviĝis de la tero; kaj kiam liaj okuloj malfermiĝis, li vidis nenion; kaj ili kondukis lin je la mano, kaj venigis lin en Damaskon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'Kaj li estis sen vidpovo tri tagojn; kaj ne manĝis, nek trinkis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Kaj en Damasko estis unu disĉiplo nomata Ananias; kaj la Sinjoro diris al li en vizio: Ananias. Kaj li respondis: Jen mi, Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'Kaj la Sinjoro diris al li: Leviĝu, kaj iru sur la straton, kiun oni nomas Rekta, kaj serĉu en la domo de Judas viron, nomatan Saŭlo, el Tarso; ĉar jen li preĝas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'kaj li vidis viron, nomatan Ananias, enirantan kaj metantan sur lin la manojn, por ke li ricevu vidpovon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Sed Ananias respondis: Sinjoro, mi aŭdis de multaj pri ĉi tiu viro, kiom da malbono li faris kontraŭ viaj sanktuloj en Jerusalem;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'kaj ĉi tie li havas de la ĉefpastroj aŭtoritaton kateni ĉiujn, kiuj vokas vian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Sed la Sinjoro diris al li: Ekiru, ĉar li estas elektita ilo por mi, por porti mian nomon antaŭ la nacianoj kaj la reĝoj kaj la Izraelidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'ĉar mi montros al li, kiom li devas suferi pro mia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Kaj Ananias ekiris, kaj eniris en la domon, kaj metinte sur lin la manojn, diris: Frato Saŭlo, min sendis la Sinjoro Jesuo, kiu aperis al vi en la vojo, laŭ kiu vi venis, por ke vi ricevu vidpovon kaj pleniĝu de la Sankta Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'Kaj tuj falis de liaj okuloj kvazaŭ skvamoj; kaj li tuj ricevis vidpovon, kaj leviĝis kaj baptiĝis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'kaj preninte nutraĵon, li refortiĝis. Kaj dum kelke da tagoj li restis kun la disĉiploj en Damasko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'Kaj en la sinagogoj li tuj proklamis Jesuon, ke li estas la Filo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'Kaj miregis ĉiuj, kiuj lin aŭdis, kaj ili diris: Ĉu li ne estas tiu, kiu en Jerusalem pereigis tiujn, kiuj vokis ĉi tiun nomon? kaj li venis ĉi tien por tio, ke li konduku ilin katenitajn antaŭ la ĉefpastrojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Sed Saŭlo des pli fortiĝis, kaj li konfuzis la Judojn loĝantajn en Damasko, pruvante, ke tiu estas la Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'Kaj post la paso de multaj tagoj, la Judoj kune konsiliĝis, por lin mortigi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'sed ilia konspiro sciiĝis al Saŭlo. Kaj ili observadis la pordegojn tage kaj nokte, por lin mortigi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'sed liaj disĉiploj prenis lin nokte, kaj mallevis lin tra la urba muro, malsupren lasante lin en korbego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'Kaj kiam li venis en Jerusalemon, li provis aliĝi al la disĉiploj; kaj ĉiuj lin timis, ne kredante, ke li estas disĉiplo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Sed Barnabas prenis lin, kaj kondukis lin al la apostoloj, kaj rakontis al ili, kiel li sur la vojo vidis la Sinjoron, kiu ankaŭ parolis al li, kaj kiel en Damasko li sentime parolis en la nomo de Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'Kaj li estis kun ili, enirante kaj elirante en Jerusalem,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'kaj sentime predikante en la nomo de la Sinjoro; kaj li parolis kaj disputadis kontraŭ la Grekaj Judoj; sed ili entreprenis mortigi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Kaj la fratoj, eksciinte tion, kondukis lin al Cezarea, kaj forsendis lin al Tarso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'Kaj la eklezio tra la tuta Judujo kaj Galileo kaj Samario havis pacon kaj ricevis edifon; kaj iradante en la timo de la Sinjoro kaj en la konsolo de la Sankta Spirito, ĝi kreskis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'Kaj dum Petro trairis ĉiujn regionojn, li ankaŭ malsupreniris al la sanktuloj loĝantaj en Lida.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'Kaj tie li trovis unu viron, nomatan Eneas, kiu kuŝadis en sia lito jam ok jarojn; ĉar li estis paralizulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'Kaj Petro diris al li: Eneas, Jesuo Kristo vin sanigas; leviĝu, kaj ordigu vian liton. Kaj li tuj leviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'Kaj ĉiuj loĝantoj en Lida kaj en Ŝaron lin vidis, kaj turniĝis al la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'Kaj estis en Jafo unu disĉiplino, nomata Tabita, kiu laŭ traduko estas nomata Dorkas; ŝi estis plena de bonfaroj kaj almozoj, kiujn ŝi faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'Kaj en tiu tempo ŝi malsaniĝis, kaj mortis; kaj ili ŝin lavis kaj metis en supran ĉambron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'Kaj ĉar Lida estis proksime de Jafo, la disĉiploj, aŭdinte, ke Petro estas tie, sendis al li du virojn, por petegi lin: Ne prokrastu veni al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Kaj Petro leviĝis kaj iris kun ili. Kaj kiam li alvenis, ili lin kondukis en la supran ĉambron; kaj alestis apud li ĉiuj vidvinoj, plorante kaj montrante tunikojn kaj vestojn, kiujn Dorkas faris, kiam ŝi estis ankoraŭ kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Sed Petro, formetinte ĉiujn, genuiĝis kaj preĝis, kaj, turninte sin al la korpo, li diris: Tabita, leviĝu. Kaj ŝi malfermis siajn okulojn, kaj, vidinte Petron, ŝi side leviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'Kaj li donis al ŝi la manon kaj starigis ŝin, kaj, vokinte la sanktulojn kaj vidvinojn, li prezentis ŝin vivanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'Kaj tio fariĝis sciata tra la tuta Jafo, kaj multaj kredis al la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'Kaj dum multe da tagoj li loĝis en Jafo ĉe unu Simon, tanisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'En Cezarea estis unu viro, nomata Kornelio, centestro de la kohorto nomata la Itala,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'viro pia, kiu timis Dion kune kun sia tuta familio, kaj donis multajn almozojn al la popolo, kaj preĝis al Dio konstante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Tiu vidis klare en vizio, ĉirkaŭ la naŭa horo de la tago, anĝelon de Dio, alvenantan al li, kaj dirantan al li: Kornelio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'Kaj ĉi tiu, fikse rigardante lin kaj timante, diris: Kio estas, Sinjoro? Kaj li diris al li: Viaj preĝoj kaj viaj almozoj supreniris kiel memoraĵo antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Kaj nun sendu virojn al Jafo, kaj venigu Simonon, kiu estas alnomata Petro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'li gastas ĉe unu Simon, tanisto, kies domo estas apud la marbordo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Kaj kiam foriris la anĝelo, kiu parolis al li, li alvokis du el siaj domservantoj, kaj pian soldaton el tiuj, kiuj ĉiam deĵoris apud li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'kaj klariginte ĉion al ili, li sendis ilin al Jafo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Kaj en la sekvanta tago, kiam ili vojaĝis kaj alproksimiĝis al la urbo, Petro supreniris sur la tegmenton, por preĝi, ĉirkaŭ la sesa horo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'kaj li fariĝis malsata, kaj deziris manĝi; sed dum oni pretigis, falis sur lin ekstazo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'kaj li vidis la ĉielon malfermitan, kaj ian ujon malsuprenirantan, kvazaŭ grandan tukon, mallevatan per la kvar anguloj sur la teron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'kaj en ĝi troviĝis ĉiaj kvarpiedaj bestoj kaj rampaĵoj de la tero kaj birdoj de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'Kaj venis voĉo al li: Leviĝu, Petro; buĉu kaj manĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Sed Petro diris: Ho ne, Sinjoro, ĉar mi neniam manĝis ion profanan aŭ malpuran.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Kaj voĉo venis al li denove duan fojon: Kion Dio purigis, tion vi ne nomu profana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'Kaj tio estis farita trifoje; kaj la ujo estis tuj prenita for en la ĉielon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Kaj dum Petro spirite embarasiĝis, kia povas esti la vizio, kiun li vidis, jen la viroj senditaj de Kornelio, eldemandinte pri la domo de Simon, staris antaŭ la pordo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'kaj vokis kaj demandis, ĉu Simon, kiu estas alnomata Petro, tie gastas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Kaj dum Petro pripensis pri la vizio, la Spirito diris al li: Jen tri viroj vin serĉas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Sed leviĝu, kaj malsupreniru, kaj vojaĝu kun ili, tute ne hezitante; ĉar mi ilin sendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Kaj Petro malsupreniris al la viroj, kaj diris: Jen mi estas tiu, kiun vi serĉas; kia estas la kaŭzo, pro kiu vi venis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Kaj ili diris: Kornelio, centestro, viro justa kaj timanta Dion, kaj bone atestata de la tuta nacio de la Judoj, estas avertita de sankta anĝelo, ke li venigu vin al sia domo kaj aŭdu parolojn de vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Tial li envokis kaj gastigis ilin. Kaj en la sekvanta tago li leviĝis, kaj foriris kun ili, kaj iuj fratoj el Jafo lin akompanis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'Kaj la morgaŭan tagon ili eniris en Cezarean. Kaj Kornelio atendis ilin, kunvokinte siajn parencojn kaj intimajn amikojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'Kaj kiam Petro estis eniranta, Kornelio lin renkontis, kaj, falinte antaŭ liaj piedoj, adorkliniĝis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Sed Petro lin levis, dirante: Stariĝu; mi mem ankaŭ estas homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'Kaj interparolante kun li, li eniris, kaj trovis multajn kunvenintajn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'kaj li diris al ili: Vi mem scias, kiel kontraŭleĝe estas por Judo kamaradiĝi aŭ aliri al alinaciano; sed Dio min admonis, ke mi ne nomu ian homon profana aŭ malpura;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'tial, kiam mi estis vokita, mi alvenis sen kontraŭdiro. Mi do demandas, por kio vi min venigis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'Kaj Kornelio diris: Antaŭ kvar tagoj ĝis ĉi tiu horo, mi preĝis la naŭahoran preĝon en mia domo; kaj jen antaŭ mi staris viro hele vestita,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'kaj diris: Kornelio, via preĝo estas aŭdita, kaj viaj almozoj estas memoritaj antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Sendu do al Jafo, kaj invitu al vi Simonon, kiu estas alnomata Petro; li gastas en la domo de Simon, tanisto, apud la marbordo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Tial mi tuj sendis al vi; kaj vi bone faris, ke vi venis. Nun do ni ĉiuj alestas ĉi tie antaŭ Dio, por aŭdi ĉion, kio estas ordonita al vi de la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Kaj Petro malfermis sian buŝon, kaj diris: Vere mi ekkomprenas, ke Dio ne privilegias personojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'sed en ĉiu nacio tiu, kiu timas Lin kaj agas juste, estas akceptata de Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'Vi konas tiun vorton, kiun Li sendis al la Izraelidoj, predikante la evangelion de paco per Jesuo Kristo (li estas Sinjoro de ĉiuj);');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'vi konas tiun diron, kiu estas disvastigita tra la tuta Judujo, komencante de Galileo, post la bapto, kiun predikis Johano-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'Jesuon, la Nazaretanon, kiun Dio sanktoleis per la Sankta Spirito kaj potenco; li ĉirkaŭiris, bonfarante kaj sanigante ĉiujn premegatajn de la diablo, ĉar Dio estis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'Kaj ni estas atestantoj pri ĉio, kion li faris en la lando de la Judoj kaj en Jerusalem; lin oni mortigis, pendigante lin sur lignaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Lin Dio levis en la tria tago, kaj donis, ke li estu videbla,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'ne al la tuta popolo, sed al atestantoj, kiuj estis elektitaj antaŭe de Dio, al ni, kiuj manĝis kaj trinkis kun li post lia releviĝo el la mortintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'Kaj li ordonis al ni prediki al la popolo, kaj atesti, ke li estas la difinito de Dio, por esti la juĝisto de la vivantoj kaj de la mortintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Pri li ĉiuj profetoj atestas, ke per lia nomo ĉiu kredanta al li ricevos pardonadon de pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'Dum Petro parolis tiujn vortojn, la Sankta Spirito falis sur ĉiujn, kiuj aŭdis la diron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'Kaj ĉiuj el la cirkumcido kredantoj, kiuj venis kun Petro, miregis pri tio, ke ankaŭ sur la nacianojn estis surverŝata la donaco de la Sankta Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'Ĉar ili aŭdis ilin paroli per lingvoj kaj glori Dion. Tiam respondis Petro:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, 'Ĉu iu povas malpermesi la akvon, ke ne baptiĝu ĉi tiuj, kiuj ricevis la Sanktan Spiriton tiel same, kiel ni?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'Kaj li ordonis, ke ili baptiĝu en la nomo de Jesuo Kristo. Tiam ili petis, ke li restu ankoraŭ kelkajn tagojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Kaj la apostoloj kaj la fratoj, kiuj estis en Judujo, aŭdis, ke la nacianoj ankaŭ ricevis la vorton de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'Kaj kiam Petro venis al Jerusalem, tiuj, kiuj estis el la cirkumcido, disputis kun li,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'dirante: Vi eniris al viroj ne cirkumciditaj, kaj manĝis kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Sed Petro klarigis la aferon al ili orde, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, 'Dum mi preĝis en la urbo Jafo, en ekstazo mi vidis vizion, ujon malsuprenirantan, kvazaŭ grandan tukon, mallevatan el la ĉielo per la kvar anguloj; kaj ĝi venis ĝis mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'kun fiksa rigardo mi ĝin observis, kaj vidis kvarpiedajn bestojn de la tero kaj sovaĝajn bestojn kaj rampaĵojn kaj birdojn de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'Kaj mi aŭdis voĉon dirantan al mi: Leviĝu, Petro; buĉu kaj manĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Sed mi diris: Ho ne, Sinjoro, ĉar nenio profana aŭ malpura eniris iam en mian buŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Sed voĉo respondis al mi la duan fojon el la ĉielo: Kion Dio purigis, tion vi ne nomu profana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'Ĉi tio fariĝis trifoje, kaj ĉio estis retirata en la ĉielon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'Kaj jen antaŭ la domo, en kiu mi estis, tuj staris tri viroj senditaj el Cezarea al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'Kaj la Spirito ordonis, ke mi iru kun ili, tute ne hezitante. Kaj ĉi tiuj ses fratoj min akompanis, kaj ni eniris en la domon de la viro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'kaj li diris al ni, ke li vidis en sia domo la anĝelon starantan, kaj dirantan: Sendu al Jafo, kaj venigu Simonon, kies alnomo estas Petro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'kiu parolos al vi vortojn, per kiuj vi kaj via tuta familio saviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Kaj dum mi komencis paroli, la Sankta Spirito malsupreniris sur ilin tiel same, kiel sur nin en la komenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Kaj mi rememoris la vorton de la Sinjoro, ke li diris: Johano ja baptis per akvo; sed vi baptiĝos per la Sankta Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Se do al ili Dio donis la saman donacon, kiel al ni, kiam ni ekkredis al la Sinjoro Jesuo Kristo, kia homo mi estis, ke mi povus kontraŭstari al Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Kiam ili tion aŭdis, ili silentiĝis, kaj gloris Dion, dirante: Ankaŭ do al la nacianoj Dio donacis penton por vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Tiuj do, kiuj dispeliĝis pro la suferado, kiu okazis pro Stefano, vojaĝis ĝis Fenikio kaj Kipro kaj Antioĥia, priparolante la vorton al neniu krom nur Judoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Sed iuj el ili, viroj el Kipro kaj Kireno, veninte en Antioĥian, parolis al la Grekoj ankaŭ, predikante la Sinjoron Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'Kaj la mano de la Sinjoro estis kun ili; kaj granda nombro kredis kaj turniĝis al la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'Kaj la raporto pri tio estis aŭdita de la eklezio, kiu estis en Jerusalem; kaj ili forsendis Barnabason ĝis Antioĥia;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'li, veninte, kaj vidante la gracon de Dio, ĝojis; kaj li admonis ilin ĉiujn, ke kun korfirmeco ili restu fidelaj al la Sinjoro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'ĉar li estis bona viro, kaj plena de la Sankta Spirito kaj de fido; kaj multo da homoj aldoniĝis al la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Kaj li iris al Tarso, por serĉi Saŭlon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'kaj trovinte, li kondukis lin al Antioĥia. Kaj dum tuta jaro ili kunvenadis kun la eklezio, kaj instruis grandan aron da homoj; kaj en Antioĥia la disĉiploj unue nomiĝis Kristanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'Kaj en tiuj tagoj profetoj el Jerusalem vojaĝis al Antioĥia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'Kaj stariĝis unu el ili, nomata Agabo, kaj deklaris per la Spirito, ke estos granda malsato tra la tuta mondo; kaj tio okazis en la tagoj de Klaŭdio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Kaj la disĉiploj decidis, ke ĉiu laŭ sia bonstato sendu helpon al la fratoj, kiuj loĝis en Judujo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'tion ankaŭ ili faris, sendante al la presbiteroj per la manoj de Barnabas kaj Saŭlo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'Kaj ĉirkaŭ tiu tempo la reĝo Herodo etendis siajn manojn, por premi iujn el la eklezianoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'Kaj li mortigis per glavo Jakobon, la fraton de Johano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'Kaj vidinte, ke tio plaĉas al la Judoj, li plue aldonis la areston de Petro. Kaj tiam estis la tagoj de macoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'Kaj kaptinte lin, li metis lin en malliberejon, transdonante lin al kvar kvaroj da soldatoj, por gardi lin, intencante elkonduki lin post la Pasko al la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Tial Petro estis gardata en la malliberejo; sed preĝo por li estis fervore farata de la eklezio al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'Kaj kiam Herodo intencis elkonduki lin, en tiu sama nokto Petro dormis inter du soldatoj, ligite per du katenoj; kaj gardistoj antaŭ la pordoj gardis la malliberejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'Kaj jen apudstaris anĝelo de la Eternulo, kaj lumo ekbrilis en la ĉambro; kaj li frapis la flankon de Petro, kaj vekis lin, dirante: Leviĝu rapide. Kaj liaj katenoj defalis de liaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'Kaj la anĝelo diris al li: Zonu vin, kaj alligu viajn sandalojn. Kaj li faris tion. Kaj li diris al li: Ĵetu ĉirkaŭ vin vian mantelon kaj sekvu min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'Kaj li eliris, kaj sekvis; kaj li ne sciis, ke reala estas tio, kion faris la anĝelo, sed li pensis, ke li vidas vizion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Kaj trapasinte la unuan postenon kaj la duan, ili venis al la fera pordego, kiu kondukas en la urbon; kaj ĝi malfermiĝis al ili propramove; kaj ili eliris, kaj pasis laŭlonge de unu strato; kaj la anĝelo tuj foriris de li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Kaj Petro, rekonsciiĝinte, diris: Nun mi certe scias, ke la Eternulo elsendis Sian anĝelon kaj liberigis min el la mano de Herodo kaj el la tuta atendado de la popolo Juda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Kaj pripensinte, li venis al la domo de Maria, la patrino de Johano, alnomata Marko, kie estis multaj kunvenintaj kaj preĝantaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'Kaj kiam li frapis ĉe la pordo de la pordego, venis knabino nomata Roda, por aŭskulti,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'kaj rekonante la voĉon de Petro, ŝi pro ĝojo ne malfermis la pordegon, sed enkuris, kaj diris, ke Petro staras antaŭ la pordego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Kaj oni diris al ŝi: Vi frenezas. Sed ŝi persiste certigis, ke tiel estas. Kaj ili diris: Ĝi estas lia anĝelo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Sed Petro daŭrigis la frapadon; kaj ili, malferminte, vidis lin, kaj miregis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Sed li gestis per la mano, ke ili silentu, kaj rakontis al ili, kiamaniere la Eternulo elkondukis lin el la malliberejo. Kaj li diris: Sciigu pri tio Jakobon kaj la fratojn. Kaj li foriris, kaj iris al alia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Kaj kiam tagiĝis, fariĝis inter la soldatoj ne malgranda ekscitiĝo, kio fariĝis kun Petro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Kaj Herodo, serĉinte kaj ne trovinte lin, ekzamenis la gardistojn, kaj ordonis forkonduki ilin al morto. Kaj li vojaĝis el Judujo al Cezarea, kaj tie restis iom da tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Kaj li estis tre kolera kontraŭ la homoj de Tiro kaj Cidon; kaj ili venis unuanime al li, kaj, akirinte la favoron de Blasto, la reĝa ĉambelano, petis pacon, ĉar ilia lando estis nutrata de la lando de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'Kaj en difinita tago Herodo, vestita en reĝaj vestoj, sidis sur tribunala seĝo kaj deklamis al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'Kaj la popolo kriis: Ĝi estas voĉo de dio, kaj ne de homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'Kaj anĝelo de la Eternulo tuj frapis lin, pro tio, ke li ne donis al Dio la gloron; kaj manĝate de vermoj, li senspiriĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'Sed la vorto de Dio kreskis kaj pligrandiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Kaj Barnabas kaj Saŭlo revenis de Jerusalem, plenuminte sian servadon, kondukante kun si Johanon, kiu estis alnomata Marko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'Kaj en Antioĥia, en la tiea eklezio, estis profetoj kaj instruistoj, Barnabas, kaj Simeon, nomata Niger, kaj Lucio, la Kirenano, kaj Manaen, kunvartito de la tetrarĥo Herodo, kaj Saŭlo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Kaj dum ili faris servon al la Sinjoro kaj fastis, la Sankta Spirito diris: Apartigu al mi Barnabason kaj Saŭlon por tiu laboro, al kiu mi ilin vokis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Tiam, fastinte kaj preĝinte kaj metinte sur ilin la manojn, ili forsendis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Kaj ĉi tiuj, forkondukite de la Sankta Spirito, malsupreniris al Seleŭkia; kaj de tie ili ŝipiris al Kipro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'Kaj estante en Salamis, ili proklamis la vorton de Dio en la sinagogoj de la Judoj; kaj ili havis Johanon kiel helpanton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'Kaj trairinte la tutan insulon ĝis Pafos, ili trovis unu magiiston, Judan falsan profeton, kies nomo estis Bar-Jesuo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'kiu estis kun la prokonsulo Sergio Paŭlo, prudenta viro. Ĉi tiu venigis al si Barnabason kaj Saŭlon, kaj deziris aŭdi la vorton de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Sed kontraŭstaris al ili Elimas, la magiisto (ĉar tion signifas lia nomo), penante deturni la prokonsulon for de la fido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Sed Saŭlo, kiu estas Paŭlo, plenigite de la Sankta Spirito kaj fikse rigardante lin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'diris: Ho vi, plena de ĉia trompo kaj ruzemeco, filo de diablo, malamiko de ĉia justeco, ĉu vi ne ĉesos defleksi la rektajn vojojn de la Sinjoro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'Kaj nun jen la mano de la Sinjoro estas sur vi, kaj vi estos blinda, ne vidante la sunon dum kelka tempo. Kaj tuj falis sur lin nebulo kaj mallumo, kaj ĉirkaŭvagante, li serĉis mankondukantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Tiam la prokonsulo, vidinte la okazintaĵon, kredis, mirigite de la instruado de la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'Sed Paŭlo kaj liaj akompanantoj ekŝipiris de Pafos kaj venis al Perga en Pamfilio; kaj Johano forlasis ilin kaj reiris al Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Sed ili, trapasante de Perga venis al Antioĥia en Pisidio; kaj en la sabato ili eniris en la sinagogon, kaj sidiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Kaj post la legado de la leĝo kaj la profetoj, la sinagogestroj sendis al ili, dirante: Fratoj, se estas ĉe vi vorto de admono por la popolo, parolu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Kaj Paŭlo, stariĝinte kaj gestinte per la mano, diris: Izraelidoj, kaj vi, kiuj timas Dion, aŭskultu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'La Dio de ĉi tiu popolo Izrael elektis niajn patrojn, kaj altigis la popolon dum la loĝado en Egiptujo, kaj per alta brako elkondukis ilin el tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'Kaj en la daŭro de ĉirkaŭ kvardek jaroj Li toleris ilian konduton en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'Kaj eksterminte sep naciojn en la lando Kanaana, Li donis al ili ilian landon kiel heredon por ĉirkaŭ kvarcent kvindek jaroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'kaj post tio Li donis juĝistojn ĝis la profeto Samuel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Kaj poste ili petis reĝon; kaj Dio donis al ili Saulon, filon de Kiŝ, viron el la tribo de Benjamen, por kvardek jaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'Kaj formetinte lin, Li levis al ili Davidon kiel reĝon, pri kiu Li parolis, atestante: Mi trovis Davidon, filon de Jiŝaj, viron laŭ Mia koro; li plenumos Mian tutan volon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'El lia idaro Dio laŭ promeso venigis al Izrael Savanton, Jesuon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'kiam Johano jam predikis antaŭ lia alveno la bapton de pento al la tuta popolo Izrael.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'Kaj dum Johano plenumis sian kuradon, li diris: Kiu vi supozas, ke mi estas? mi ne estas tiu. Sed jen venas post mi unu, al kiu mi ne estas inda malligi la sandalojn de la piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Fratoj, idoj el la raso de Abraham, kaj tiuj inter vi, kiuj timas Dion, al ni estas sendita la vorto de ĉi tiu savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Ĉar la loĝantoj en Jerusalem kaj iliaj regantoj ne konis lin; kaj kondamnante lin, ili plenumis la voĉojn de la profetoj ĉiusabate legatajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'Kaj trovinte en li nenian kaŭzon de morto, ili tamen petis Pilaton mortigi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'Kaj plenuminte ĉion, kio estis skribita pri li, ili forprenis lin de la lignaĵo kaj metis lin en tombon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'Sed Dio levis lin el la mortintoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'kaj li estis vidata multajn tagojn de tiuj, kiuj venis kun li el Galileo en Jerusalemon, kaj ili nun estas liaj atestantoj ĉe la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'Kaj ni alportas al vi bonan sciigon pri la promeso farita al la patroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'ke Dio plenumis tion al ni, la filoj, relevinte Jesuon, kiel ankaŭ estas skribite en la dua psalmo: Vi estas Mia Filo, hodiaŭ Mi vin naskis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'Kaj pri tio, ke Li relevis lin el la mortintoj, jam ne venontan en forputron, Li parolis jene: Mi donos al vi la fidindajn favorkoraĵojn de David.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'Ĉar li ankaŭ diris en alia psalmo: Vi ne permesos, ke Via sanktulo forputru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'Ĉar David, servinte en sia generacio al la intenco de Dio, ekdormis, kaj alkolektiĝis al siaj patroj kaj vidis forputron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'sed tiu, kiun Dio relevis, ne vidis forputron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Estu do sciate al vi, fratoj, ke per ĉi tiu estas proklamata al vi pardonado de pekoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'kaj ĉiu kredanto al li estas pravigita pri ĉio, pri kio vi ne povis esti pravigitaj per la leĝo de Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Gardu vin do, ke ne venu sur vin tio, kio estas dirita en la profetoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, 'Rigardu, vi malestimantoj, kaj miru, kaj malaperu, Ĉar en via tempo Mi faras ion, Kion vi ne kredus, se oni rakontus al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'Kaj dum ili eliris el la sinagogo, oni petegis, ke ĉi tiuj vortoj estu parolataj al ili la venontan sabaton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'Kaj kiam la sinagogo disiĝis, multaj el la Judoj kaj el la piaj prozelitoj sekvis Paŭlon kaj Barnabason, kiuj, alparolante ilin, urĝe admonis ilin persisti en la graco de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'En la sekvanta sabato preskaŭ la tuta urbo kolektiĝis, por aŭdi la vorton de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Kaj la Judoj, vidante la homamasojn, pleniĝis de ĵaluzo, kaj kontraŭdiris la dirojn de Paŭlo, kaj blasfemis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Kaj Paŭlo kaj Barnabas, parolante kuraĝe, diris: Estis necese paroli al vi unue la vorton de Dio. Sed ĉar vi forpuŝis ĝin kaj ne juĝas vin indaj je la eterna vivo, jen ni turnas nin al la nacianoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Ĉar tiel ordonis al ni la Sinjoro: Mi vin metis kiel lumon por la nacioj, Por ke vi estu por savo ĝis la plej malproksima parto de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'Kaj aŭdinte tion, la nacianoj ĝojis, kaj gloris la vorton de Dio; kaj el ili kredis ĉiuj, kiuj estis difinitaj por eterna vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'Kaj la vorto de la Sinjoro estis disportata tra la tuta regiono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Sed la Judoj incitis la piajn virinojn bonfamajn kaj la ĉefojn de la urbo, kaj instigis persekutadon kontraŭ Paŭlo kaj Barnabas, kaj forpelis ilin el siaj limoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'Sed ili forskuis la polvon de siaj piedoj kontraŭ ili, kaj iris al Ikonio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'Kaj la disĉiploj pleniĝis de ĝojo kaj de la Sankta Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'Kaj en Ikonio ili ambaŭ eniris en la sinagogon de la Judoj, kaj tiel parolis, ke granda amaso da Judoj kaj Grekoj kredis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Sed la nekredantaj Judoj ekscitis kaj malbonigis la animojn de la nacianoj kontraŭ la fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Tial ili restis longan tempon tie, sentime parolante en la Sinjoro, kiu atestadis pri la vorto de Sia graco, lasante, ke signoj kaj mirakloj fariĝu per iliaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'Sed la loĝantaro de la urbo dividiĝis; unuj estis kun la Judoj, kaj aliaj kun la apostoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Kaj kiam fariĝis atenco de la nacianoj kaj ankaŭ de la Judoj kun iliaj regantoj, por ataki kaj ŝtonmortigi ilin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'sciiĝinte pri ĝi, ili forsavis sin en la urbojn de Likaonio-Listran kaj Derben kaj la ĉirkaŭaĵon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'kaj tie ili proklamis la evangelion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'Kaj en Listra sidadis unu viro senforta en la piedoj, kiu estis lama de la patrina ventro, kaj neniam piediris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Li aŭdis Paŭlon paroli; kaj ĉi tiu, fikse rigardante lin, kaj vidante, ke ili havas fidon por esti sanigita,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'diris per laŭta voĉo: Stariĝu rekte sur viaj piedoj. Kaj li salte leviĝis kaj piediris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Kaj la homamaso, vidinte tion, kion Paŭlo faris, levis sian voĉon, kaj diris en la Likaonia lingvo: La dioj en homa formo malsupreniris al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'Kaj Barnabason ili nomis Zeŭs, kaj Paŭlon Hermes, ĉar ĉi tiu estis la ĉefa parolanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Kaj la pastro de la Zeŭs, kiu estis antaŭ la urbo, alkondukis bovojn kaj girlandojn al la pordegoj, kaj volis oferi kun la homamasoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Sed la apostoloj Paŭlo kaj Barnabas, aŭdinte, disŝiris siajn vestojn, kaj antaŭensaltis en la amason, kriante,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'kaj dirante: Ho viroj, kial vi tion faras? Ni ankaŭ estas homoj, samsentaj kiel vi, kaj ni alportas al vi evangelion, por turni vin de ĉi tiuj vantaĵoj al la vivanta Dio, kiu faris la ĉielon kaj la teron kaj la maron kaj ĉion en ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'kaj kiu en la pasintaj generacioj permesis, ke ĉiuj nacioj iru siajn proprajn vojojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Tamen Li ne lasis Sin sen atesto, ĉar Li bonfaris, donante al vi pluvojn el la ĉielo kaj fruktoportajn sezonojn, plenigante viajn korojn per nutraĵo kaj feliĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'Kaj tiel dirante, ili apenaŭ retenis la amasojn de oferado al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Sed alvenis Judoj el Antioĥia kaj Ikonio, kaj, instiginte la amason, ili priĵetis Paŭlon per ŝtonoj, kaj trenis lin ekster la urbon, pensante, ke li mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Sed kiam la disĉiploj staris ĉirkaŭ li, li leviĝis, kaj eniris en la urbon; kaj en la sekvanta tago li eliris kun Barnabas al Derbe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'Kaj proklaminte la evangelion al tiu urbo, kaj varbinte multajn disĉiplojn, ili revenis al Listra kaj Ikonio kaj Antioĥia,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'firmigante la animojn de la disĉiploj, kaj admonante, ke ili restu en la fido, kaj ke tra multaj suferoj ni devas eniri en la regnon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'Kaj elektinte presbiterojn por ili en ĉiu eklezio, kaj preĝinte kun fastado, ili rekomendis ilin al la Sinjoro, al kiu ili ekkredis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'Kaj trairinte Pisidion, ili venis en Pamfilion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'Kaj parolinte la vorton en Perga, ili malsupreniris al Atalia;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'kaj de tie ili ŝipiris al Antioĥia, de kie ili estis konfiditaj al la graco de Dio por la laboro, kiun ili plenumis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'Kaj kiam ili alvenis, ili kunvenigis la eklezion, kaj rakontis ĉion, kion Dio per ili faris, kaj ke Li malfermis al la nacianoj pordon de fido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'Kaj ili restis kelkan tempon kun la disĉiploj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Kaj iuj homoj vojaĝis tien el Judujo, kaj instruis la fratojn: Se vi ne cirkumcidiĝos laŭ la moro de Moseo, vi ne povas saviĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Kaj kiam Paŭlo kaj Barnabas havis ne malgrandan malkonsenton kaj diskutadon kontraŭ ili, oni aranĝis, ke Paŭlo kaj Barnabas kaj aliaj tieuloj iru Jerusalemon al la apostoloj kaj presbiteroj pri tiu demando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Ili do, forkondukite de la eklezio, trairis Fenikion kaj Samarion, anoncante la konvertadon de la nacianoj, kaj faris grandan ĝojon al ĉiuj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'Kaj alveninte en Jerusalemon, ili estis akceptitaj de la eklezio kaj apostoloj kaj presbiteroj, kaj raportis ĉion, kion Dio faris per ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Sed leviĝis iuj kredantoj el la sekto de la Fariseoj, dirante: Estas necese cirkumcidi ilin, kaj ordoni, ke ili observu la leĝon de Moseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Kaj kunvenis la apostoloj kaj presbiteroj, por esplori tiun aferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'Kaj post multe da diskutado, Petro stariĝis, kaj diris al ili: Fratoj, vi scias, ke jam antaŭ longe Dio elektis min el inter vi, por ke per mia buŝo la nacianoj aŭdu la vorton de la evangelio kaj kredu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'Kaj Dio, kiu konas la korojn, atestis al ili, donante al ili la Sanktan Spiriton tiel same, kiel al ni;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'kaj Li faris nenian diferencon inter ni kaj ili, per la fido puriginte iliajn korojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Nun do kial vi incitas Dion, dezirante meti sur la kolon de la disĉiploj jugon, kiun povis porti nek niaj patroj, nek ni?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Sed ni kredas pri nia savo per la graco de la Sinjoro Jesuo tiel same, kiel ankaŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Kaj silentis la tuta amaso; kaj ili aŭskultis, dum Paŭlo kaj Barnabas rakontis, kiom da signoj kaj mirakloj Dio faris ĉe la nacianoj per ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'Kaj kiam ili ĉesis paroli, Jakobo respondis, dirante: Fratoj, aŭskultu min;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Simeon rakontis, kiel unue Dio vizitis nacianojn, por elekti el ili popolon por Sia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'Kaj al tio konsentas la vortoj de la profetoj, kiel estas skribite:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, 'Post tio Mi revenos, Kaj Mi restarigos la falintan tabernaklon de David, Mi restarigos la detruitaĵojn, Kaj Mi rekonstruos ĝin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'Por ke strebu al la Eternulo la ceteraj homoj Kaj ĉiuj nacioj, inter kiuj estas proklamata Mia nomo, Diras la Eternulo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'Kiu tion faras jam de la tempo antikva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Tial mi decidas, ke ni ne ĝenu tiujn el la nacianoj, kiuj turniĝas al Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'sed ni admonu ilin, ke ili detenu sin de malpuriĝoj ĉe idoloj kaj de malĉasteco kaj de sufokitaĵoj kaj de sango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Ĉar de post antikvaj generacioj Moseo havas en ĉiuj urboj tiujn, kiuj lin predikas, legate en la sinagogoj ĉiusabate.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Tiam al la apostoloj kaj presbiteroj kun la tuta eklezio ŝajnis bone elekti virojn el inter si kaj sendi ilin al Antioĥia kun Paŭlo kaj Barnabas: nome Judas, alnomata Barsabas, kaj Silas, viroj konataj inter la fratoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'kaj ili sendis per ili la jenan leteron: La apostoloj kaj presbiteroj, al la fratoj, kiuj estas el la nacianoj en Antioĥia kaj Sirio kaj Kilikio, kun saluto:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Ĉar ni aŭdis, ke iuj el ni ĝenis vin per vortoj maltrankviligaj por viaj animoj, al kiuj ni ne ordonis tion,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'ŝajnis bone al ni unuanime, ke ni elektu virojn kaj sendu ilin al vi kun niaj amataj Barnabas kaj Paŭlo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'homoj, kiuj riskis siajn vivojn pro la nomo de nia Sinjoro Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Ni do sendis Judason kaj Silason, kiuj ankaŭ mem buŝe diros tion saman.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Ĉar al la Sankta Spirito kaj al ni ŝajnis bone meti sur vin nenian alian ŝarĝon, krom la jenaj necesaj aferoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'ke oni sin detenu de idoloferitaĵoj kaj de sango kaj de sufokitaĵoj kaj de malĉasteco; se vi vin gardos kontraŭ tio, vi bone agos. Adiaŭ!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Ili do, forsendite, iris al Antioĥia; kaj kunveniginte la amason, ili transdonis la leteron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'Kaj leginte ĝin, ili ĝojis pro la konsolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'Kaj Judas kaj Silas, kiuj estis ankaŭ mem profetoj, konsolis la fratojn per multe da parolo kaj firmigis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'Kaj pasiginte kelkan tempon, ili kun paco foriris de la fratoj al siaj forsendintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, '(Tamen plaĉis al Silas tie restadi.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Sed Paŭlo kaj Barnabas restis en Antioĥia, instruante kaj predikante, kun multaj aliaj, la vorton de la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Kaj post kelke da tagoj Paŭlo diris al Barnabas: Ni reiru, kaj vizitu niajn fratojn en ĉiu urbo, kie ni proklamis la vorton de la Sinjoro, kaj vidu, kiel ili fartas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Kaj Barnabas konsilis kunpreni Johanon, alnomatan Marko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Sed Paŭlo ne aprobis kunpreni tiun, kiu sin fortiris de ili en Pamfilio, kaj ne kuniris en la laboron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'Kaj fariĝis disputo, tiel ke ili disiĝis unu de la alia; kaj Barnabas, kunprenante Markon, ŝipiris al Kipro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'sed Paŭlo, elektinte Silason, foriris, konfidite de la fratoj al la graco de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'Kaj li iris tra Sirio kaj Kilikio, firmigante la ekleziojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Kaj li venis al Derbe kaj Listra; kaj jen tie estis unu disĉiplo, nomata Timoteo, filo de kredanta Judino kaj de Greka patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'Tiu estis bone atestata de la fratoj en Listra kaj Ikonio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Tiun Paŭlo deziris, ke li foriru kun li, kaj li prenis kaj cirkumcidis lin pro la Judoj, kiuj estis en tiuj regionoj; ĉar ĉiuj sciis, ke lia patro estas Greko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'Kaj dum ili trapasis la urbojn, ili transdonis al ili por observado la dekretojn, deciditajn de la apostoloj kaj presbiteroj en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'Tiel la eklezioj firmiĝis en la fido, kaj kreskis laŭnombre ĉiutage.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'Kaj ili trairis la Frigian kaj Galatujan regionon, malpermesite de la Sankta Spirito priparoli la vorton en Azio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'kaj veninte apud Misia, ili klopodis eniri en Bitinion, kaj la Spirito de Jesuo tion ne permesis al ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'kaj pasinte preter Misia, ili malsupreniris al Troas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'Kaj vizio aperis al Paŭlo dum la nokto: viro Makedona staris, kaj petegis lin, dirante: Transpasu al Makedonujo, kaj nin helpu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Kaj post kiam li vidis la vizion, ni tuj penis foriri en Makedonujon, konkludinte, ke Dio vokis nin, por prediki al ili la evangelion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Tial, ekŝipirinte de Troas, ni rekte veturis al Samotrake, kaj la sekvantan tagon al Neapolis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'kaj de tie al Filipi, kiu estas kolonio, ĉefurbo de la Makedonuja provinco; kaj en tiu urbo ni restis dum kelke da tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'Kaj en la sabato ni eliris ekster la pordegon apud rivero, kie, ni supozis, estis kunvenejo por preĝado; kaj ni sidiĝis, kaj parolis al la virinoj kunvenintaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'Kaj unu virino, nomata Lidia, vendistino de purpuro, el la urbo Tiatira, adorantino de Dio, nin aŭdis; ŝian koron la Sinjoro malfermis, por atenti la parolojn de Paŭlo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'Kaj kiam ŝi estis baptita, kun sia familio, ŝi nin petegis, dirante: Se vi juĝas min fidela al la Sinjoro, venu, kaj loĝu en mia domo. Kaj ŝi devigis nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'Kaj kiam ni iris al la kunvenejo por preĝado, renkontis nin unu knabino, kiu havis orakolan spiriton kaj kiu per aŭgurado alportadis al siaj mastroj multan gajnon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Ŝi sekvis Paŭlon kaj nin, kaj kriadis, dirante: Tiuj homoj estas servistoj de Dio la Plejalta, kiuj proklamas al vi vojon de savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'Kaj tion ŝi faris dum multe da tagoj. Sed Paŭlo, ĉagrenite, turnis sin, kaj diris al la spirito: Mi ordonas al vi en la nomo de Jesuo Kristo, ke vi eliru el ŝi. Kaj ĝi eliris en tiu sama horo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Sed ŝiaj mastroj, vidinte, ke eliris la espero de ilia gajno, kaptis Paŭlon kaj Silason, kaj trenis ilin en la placon al la regantoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'kaj kondukinte ilin al la urbestroj, diris: Ĉi tiuj homoj treege maltrankviligas nian urbon, estante Judoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'kaj ili proklamas morojn, kiujn ne decas akcepti nek fari por ni, kiuj estas Romanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'Kaj la popolo amase sin kolektis kontraŭ ili; kaj la urbestroj, forŝirinte de ili la vestojn, ordonis, ke oni vergobatu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'Kaj metinte sur ilin multajn batojn, ili ĵetis ilin en malliberejon, ordonante al la estro de la malliberejo, ke li forte gardu ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'kaj li, ricevinte tiun ordonon, ĵetis ilin en la internan karceron kaj fiksis iliajn piedojn en la trabon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Sed ĉirkaŭ la noktomezo Paŭlo kaj Silas preĝis kaj himnis al Dio, kaj la katenitoj aŭskultis ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'kaj subite fariĝis granda tertremo, tiel ke la fundamentoj de la malliberejo skuiĝis; kaj tuj ĉiuj pordoj malfermiĝis, kaj ĉies katenoj falis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'Kaj la malliberejestro, vekiĝinte, kaj vidante la pordojn de la karcero malfermitaj, eltiris sian glavon kaj volis mortigi sin, supozante, ke la malliberuloj forkuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Sed Paŭlo vokis per laŭta voĉo, dirante: Nenian malbonon faru al vi, ĉar ni ĉiuj estas ĉi tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Kaj veniginte lumilon, li ensaltis, kaj, tremante de timo, kliniĝis antaŭ Paŭlo kaj Silas,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'kaj kondukis ilin eksteren, kaj diris: Sinjoroj, kion mi devas fari, por esti savita?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'Kaj ili diris: Kredu al la Sinjoro Jesuo, kaj vi estos savita, vi kaj via familio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'Kaj ili parolis la vorton de la Sinjoro al li kaj al ĉiuj en lia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'Kaj li kondukis ilin en tiu sama nokta horo kaj lavis al ili la batovundojn; kaj baptiĝis senprokraste li kaj ĉiuj liaj domanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'Kaj li kondukis ilin en sian domon, kaj aranĝis por ili manĝotablon, kaj tre ĝojis kun sia tuta domanaro, ekkredinte al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'Sed kiam tagiĝis, la urbestroj sendis la liktorojn, por diri: Forliberigu tiujn homojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'Kaj la malliberejestro raportis la vortojn al Paŭlo: La urbestroj ĵus sendis, por ke vi forliberiĝu; tial nun elvenu kaj foriru pace.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Sed Paŭlo diris al ili: Ili publike vergobatis nin ne kondamnitajn, kvankam ni estas Romanoj, kaj nin ĵetis en malliberejon; kaj ĉu ili nun elĵetas nin kaŝe? tute ne; ili mem venu kaj forkonduku nin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Kaj la liktoroj raportis tiujn vortojn al la urbestroj; kaj ĉi tiuj timis, aŭdante, ke ili estas Romanoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'kaj ili venis kaj petegis ilin, kaj, elkondukinte ilin, petis, ke ili foriru de la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'Kaj ili eliris el la malliberejo, kaj eniris en la domon de Lidia; kaj vidinte kaj konsolinte la fratojn, ili foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Kaj vojaĝinte tra Amfipolis kaj Apolonia, ili alvenis en Tesalonikon, kie estis sinagogo de la Judoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'kaj laŭ sia kutimo Paŭlo eniris al ili, kaj dum tri sabatoj li rezonadis kun ili el la Skriboj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'klarigante kaj montrante, ke la Kristo devis suferi kaj releviĝi el la mortintoj, kaj dirante: Ĉi tiu Jesuo, kiun mi predikas al vi, estas la Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'Kaj unuj el ili estis konvinkitaj, kaj kunsortiĝis kun Paŭlo kaj Silas; kaj el la piaj Grekoj granda amaso, kaj el la ĉefaj virinoj ne malmultaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Sed la Judoj, enviante, varbis kelkajn malnoblulojn el la popolaĉo, kaj, kolektinte homamason, entumultigis la urbon; kaj atakinte la domon de Jason, ili klopodis elkonduki ilin al la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Sed ne trovinte ilin, ili trenis Jasonon kaj kelkajn fratojn antaŭ la urbestrojn, kriante: Tiuj samaj, kiuj renversis la tutan mondon, alestas ankaŭ ĉi tie;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'ilin Jason akceptis; kaj ili ĉiuj agas kontraŭ la dekretoj de Cezaro, dirante, ke estas alia reĝo, Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'Kaj ili maltrankviligis la homamason kaj la urbestrojn, kiuj tion aŭdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Kaj ĉi tiuj, ricevinte garantiaĵon de Jason kaj la aliaj, liberigis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Kaj la fratoj tuj forsendis Paŭlon kaj Silason nokte al Berea; kaj alveninte tien, ili iris en la sinagogon de la Judoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Kaj ĉi tiuj estis pli noblaj ol la Tesalonikanoj, ĉar ili akceptis la vorton kun plena fervoro, kaj ĉiutage esploris la Skribojn, por konstati, ĉu tiuj aferoj estas veraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Tial multaj el ili kredis, kaj ne malmultaj el la Grekaj virinoj honorindaj kaj el la viroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Sed kiam la Judoj en Tesaloniko sciiĝis, ke ankaŭ en Berea la vorto de Dio estas proklamita de Paŭlo, ili venis ankaŭ tien, maltrankviligante kaj ekscitante la homamason.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Kaj tiam la fratoj tuj forsendis Paŭlon, por ke li iru ĝis la marbordo; sed Silas kaj Timoteo restis ankoraŭ tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Kaj la gvidantoj de Paŭlo kondukis lin ĝis Ateno, kaj ricevinte komision al Silas kaj Timoteo, ke ili venu al li kiel eble plej rapide, ili foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Kaj dum Paŭlo atendis ilin en Ateno, lia spirito ĉagreniĝis en li, kiam li vidis la urbon idolplena.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Tial li rezonadis en la sinagogoj kun la Judoj kaj la diotimantoj, kaj sur la placo ĉiutage kun la renkontitoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Kaj iuj el la Epikuranaj kaj Stoikaj filozofoj lin renkontis. Kaj unuj diris: Kion volus diri ĉi tiu vortŝutanto? aliaj diris: Li ŝajnas esti proklamanto de fremdaj diaĵoj; ĉar li predikis Jesuon kaj la releviĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'Kaj ili prenis lin, kaj kondukis lin al la Areopago, dirante: Ĉu ni povas scii, kio estas tiu nova instruo, priparolata de vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Ĉar fremdaĵojn vi portas al niaj oreloj; ni do volas scii, kion signifas tiuj aferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, '(Ĉiuj Atenanoj kaj la tie loĝantaj fremduloj pasigadis la tempon ĉe nenio alia, krom diri aŭ aŭdi ion plej novan.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Kaj Paŭlo staris meze de la Areopago, kaj diris: Atenanoj, mi rimarkas, ke vi estas ĉiurilate tro servemaj al diaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Ĉar preterpasante kaj rigardante viajn adorataĵojn, mi trovis ankaŭ altaron, sur kiu estis skribite: AL DIO NEKONATA. Kiun do vi nekonante adoras, Tiun mi predikas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'La Dio, kiu faris la mondon kaj ĉion, kio estas en ĝi, estante per Si mem Sinjoro de la ĉielo kaj la tero, ne loĝas en manfaritaj temploj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'kaj ne estas servata de homaj manoj, kvazaŭ Li ion bezonus, ĉar Li mem donas al ĉiuj vivon kaj spiron kaj ĉion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'kaj el unu origino Li faris ĉiujn naciojn de la homoj, por loĝi sur la tuta supraĵo de la tero, difininte ordigitajn epokojn kaj la limojn de iliaj loĝejoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'por ke ili serĉu Dion, se eble ili povus ĉirkaŭpalpi kaj trovi Lin, kvankam Li ne estas malproksime de ĉiu el ni;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'ĉar en Li ni vivas kaj moviĝas kaj ekzistas, kiel ankaŭ iuj viaj poetoj diris: Ĉar ni estas ankaŭ Lia idaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Tial ni, estante idaro de Dio, devas ne opinii la Diecon simila al oro aŭ arĝento aŭ ŝtono, gravuraĵo de homa arto kaj imagado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Kaj la tempojn de nesciado preterrigardis Dio, sed nun Li proklamas al ĉiuj homoj, ke ili pentu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'tial Li difinis tagon, en kiu Li juĝos la mondon en justeco per tiu viro, kiun Li elektis, doninte garantion pri tio al ĉiuj homoj per tio, ke Li relevis lin el la mortintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Kaj aŭdinte pri releviĝo de la mortintoj, unuj mokis; sed aliaj diris: Ni aŭskultos vin denove pri tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'Kaj tiel Paŭlo eliris el inter ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Sed iuj viroj aliĝis al li kaj kredis, inter kiuj estis Dionisio, Areopagano, kaj virino, nomata Damaris, kaj aliaj kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Post tio li foriris el Ateno kaj alvenis en Korinton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'Kaj li trovis Judon, nomatan Akvila, Pontanon laŭ gento, antaŭ ne longe venintan el Italujo, kaj Priskilan, lian edzinon, ĉar Klaŭdio jam ordonis, ke ĉiuj Judoj foriru el Romo; kaj li iris al ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'kaj, ĉar li estis sammetiisto, li loĝis ĉe ili, kaj ili laboris, ĉar ili estis laŭ metio tendofaristoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Kaj li diskutadis en la sinagogo ĉiusabate, kaj penis konvinki Judojn kaj Grekojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'Kiam do Silas kaj Timoteo alvenis el Makedonujo, Paŭlo estis premata per la predikado, atestante al la Judoj, ke Jesuo estas la Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Sed kiam ili kontraŭstaris kaj blasfemis, li elskuis siajn vestojn, kaj diris al ili: Via sango estu sur viaj kapoj; mi estas pura; de nun mi iros al la nacianoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'Kaj foririnte de tie, li iris en la domon de homo nomata Tito Justo, kiu adoris Dion, kaj kies domo estis tuj apud la sinagogo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Kaj Krispo, la sinagogestro, kredis al la Sinjoro kune kun ĉiuj siaj domanoj; kaj multaj Korintanoj, aŭdinte, kredis kaj baptiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Kaj la Sinjoro diris per vizio nokte al Paŭlo: Ne timu, sed parolu, kaj ne silentu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'ĉar mi estas kun vi, kaj neniu vin atakos, por fari al vi malbonon; ĉar mi havas multe da homoj en ĉi tiu urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'Kaj li loĝis tie jaron kaj ses monatojn, instruante inter ili la vorton de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Sed kiam Galiono estis prokonsulo de la Aĥaja lando, la Judoj leviĝis unuanime kontraŭ Paŭlo, kaj kondukis lin al la tribunala seĝo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'dirante: Kontraŭ la leĝo ĉi tiu instigas homojn adori Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Sed kiam Paŭlo estis malfermonta la buŝon, Galiono diris al la Judoj: Se vere tio estus ia maljustaĵo aŭ malbonega kanajlaĵo, ho Judoj, estus racie, ke mi vin toleru;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'sed se prezentiĝas demandoj pri vortoj kaj nomoj kaj via propra leĝo, vi mem ĝin atentu; pri tiaj aferoj mi ne volas esti juĝanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'Kaj li forpelis ilin de la tribunala seĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Kaj ili ĉiuj ekkaptis Sosteneson, la sinagogestron, kaj batis lin antaŭ la tribunala seĝo. Kaj Galiono atentis nenion el tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Kaj Paŭlo, restinte post tio ankoraŭ dum multe da tagoj, adiaŭis la fratojn, kaj de tie ŝipiris al Sirio, kaj kun li Priskila kaj Akvila; sed li razis sian kapon en Kenkrea, ĉar li faris sanktan promeson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Kaj ili alvenis en Efeson, kaj li lasis ilin tie; sed li mem eniris en la sinagogon, kaj diskutis kun la Judoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'Kaj kiam ili petis lin restadi pli longe, li ne konsentis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'sed adiaŭinte ilin, kaj dirinte: Mi denove revenos al vi, se plaĉos al Dio-li ekŝipiris el Efeso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'Kaj elŝipiĝinte en Cezarea, li supreniris kaj salutis la eklezion, kaj poste vojaĝis al Antioĥia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'Kaj pasiginte iom da tempo tie, li foriris, kaj trapasis laŭvice la Galatujan kaj Frigian regionon, fortikigante ĉiujn disĉiplojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Kaj unu Judo, nomata Apolos, Aleksandriano laŭ gento, viro klera, venis al Efeso; kaj li estis potenca en la Skriboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Ĉi tiu jam estis instruita pri la vojo de la Sinjoro; kaj estante fervora en spirito, li paroladis kaj instruadis precize pri Jesuo, konante nur la bapton de Johano;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'kaj li komencis paroli sentime en la sinagogo. Sed Akvila kaj Priskila, aŭdinte lin, alprenis lin al si, kaj klarigis al li pli precize la vojon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'Kaj kiam li volis transiri en la Aĥajan landon, la fratoj kuraĝigis lin, kaj skribis al la disĉiploj, ke ili akceptu lin; kaj alveninte, li multe helpis tiujn, kiuj kredis per graco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'ĉar konvinke li refutis la Judojn publike, pruvante per la Skriboj, ke Jesuo estas la Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Kaj dum Apolos estis en Korinto, Paŭlo, trapasinte la supran regionon, venis al Efeso, kaj trovinte iujn disĉiplojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'li diris al ili: Ĉu vi ricevis la Sanktan Spiriton, kiam vi ekkredis? Kaj ili diris al li: Ni ankoraŭ eĉ ne aŭdis, ĉu estas Sankta Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Kaj li diris al ili: En kion do vi baptiĝis? Kaj ili diris: En la bapton de Johano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Kaj Paŭlo diris: Johano baptis per la bapto de pento, dirante al la popolo, ke ili kredu al tiu, kiu venos post li, tio estas al Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Kaj tion aŭdinte, ili baptiĝis en la nomon de la Sinjoro Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'Kaj kiam Paŭlo metis siajn manojn sur ilin, la Sankta Spirito venis sur ilin; kaj ili ekparolis per lingvoj kaj ekprofetis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Kaj ili ĉiuj estis ĉirkaŭ dek du viroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Kaj li eniris en la sinagogon, kaj parolis sentime en la daŭro de tri monatoj, diskutante kaj rezonante rilate la regnon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Sed kiam kelkaj obstiniĝis kaj malobeis, kalumniante la Vojon antaŭ la homamaso, li foriris de ili, kaj forigis la disĉiplojn, kaj diskutis ĉiutage en la lernejo de Tiranos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'Kaj tio daŭris dum du jaroj; tiel ke ĉiuj loĝantoj en Azio, Judoj kaj Grekoj, aŭdis la vorton de la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'Kaj Dio faris per la manoj de Paŭlo eksterordinarajn miraklojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'tiel ke al la malsanuloj oni alportis de lia korpo viŝtukojn aŭ vestotukojn, kaj la malsanoj forlasis ilin, kaj la malbonaj spiritoj eliris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Sed ankaŭ kelkaj el la vagemaj Judoj, ekzorcistoj, entreprenis nomi super tiuj, kiuj havis la malbonajn spiritojn, la nomon de la Sinjoro Jesuo, dirante: Mi ekzorcas vin per Jesuo, kiun Paŭlo predikas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'Kaj sep filoj de unu Judo, Skeva, ĉefpastro, tion faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Kaj la malbona spirito responde diris al ili: Jesuon mi konas, kaj Paŭlon mi konas; sed kiuj estas vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'Kaj la viro, en kiu estis la malbona spirito, sin ĵetis sur ilin, kaj venkis kaj superfortis ilin, tiel ke ili forkuris el tiu domo nudaj kaj vunditaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'Kaj tio sciiĝis al ĉiuj, kiuj loĝis en Efeso, Judoj kaj Grekoj; kaj timo falis sur ilin ĉiujn, kaj la nomo de la Sinjoro Jesuo grandiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'Multaj ankaŭ el la kredantoj venis, kaj konfesis, montrante siajn agojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Kaj ne malmultaj el tiuj, kiuj praktikis magiajn artojn, alportis amase siajn librojn, kaj bruligis ilin antaŭ la okuloj de ĉiuj; kaj oni kalkulis ilian valoron, kaj trovis ĝin kvindek miloj da moneroj arĝentaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Tiel forte kreskis la vorto de la Sinjoro kaj sukcesis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'Kaj kiam tio finiĝis, Paŭlo intencis en la spirito, trapasinte Makedonujon kaj la Aĥajan landon, vojaĝi al Jerusalem, kaj li diris: Post kiam mi iros tien, mi devos ankaŭ vidi Romon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Kaj sendinte en Makedonujon du el siaj helpservantoj, Timoteon kaj Eraston, li mem restis iom da tempo en Azio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Kaj ĉirkaŭ tiu tempo leviĝis ne malgranda ekscitiĝo pri la Vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Ĉar unu viro, nomata Demetrio, arĝentaĵisto, kiu faradis arĝentajn templetojn de Artemis, liveris al la metiistoj multe da okupo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'kaj li kunvenigis ilin, kune kun la samokupaj laboristoj, kaj diris: Ho viroj, vi scias, ke per ĉi tiu metio ni havas bonajn enspezojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'Kaj vi vidas kaj aŭdas, ke ne sole en Efeso, sed ankaŭ tra preskaŭ la tuta Azio, ĉi tiu Paŭlo jam influis kaj forturnis multe da homoj, dirante, ke tio, kio estas manfarita, estas ne-dioj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'kaj estas danĝero, ne sole ke ĉi tiu nia metio estos malestimata, sed ankaŭ ke la templo de la granda diino Artemis estos malŝatata; kaj eble estos senigita je sia majesto tiu, kiun la tuta Azio kaj la tuta mondo adoras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'Aŭdinte tion, ili pleniĝis de kolero, kaj ekkriis, dirante: Granda estas Artemis de la Efesanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'Kaj la urbo pleniĝis de tumulto; kaj oni kure kolektiĝis unuanime en la teatron, ekkaptinte Gajon kaj Aristarĥon, Makedonojn, kunvojaĝantojn de Paŭlo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Kaj kiam Paŭlo volis eniri antaŭ la popolon, la disĉiploj tion ne permesis al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'Kaj ankaŭ kelkaj el la ĉefoj de Azio, kiuj estis liaj amikoj, sendis al li, kaj petegis lin ne riski sin en la teatron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Kriadis ili do diverse ion kaj alion, ĉar la kunveno estis konfuzita; kaj la plimulto ne sciis, kial ili kunvenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'Kaj el la homamaso ili elpaŝigis Aleksandron, kiun la Judoj puŝis antaŭen. Kaj Aleksandro gestis per la mano, kaj ekprovis pledi antaŭ la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Sed sciiĝinte, ke li estas Judo, ĉiuj unuvoĉe en la daŭro de ĉirkaŭ du horoj kriadis: Granda estas Artemis de la Efesanoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Kaj kiam la urboskribisto kvietigis la amason, li diris: Ho Efesanoj, ĉu do ekzistas homo nescianta, ke la urbo de la Efesanoj estas templogardanto de Artemis la granda kaj de la elĉiela falintaĵo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Ĉar tio do ne estas kontraŭdirebla, vi devas esti trankvilaj, kaj fari nenion senpripense.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'Ĉar vi alkondukis ĉi tiujn virojn, kiuj estas nek templorabistoj nek blasfemantoj de nia diino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Se do Demetrio kaj la kun li metiistoj havas plendaferon kontraŭ iu, la juĝejoj estas je ilia dispono, kaj ekzistas prokonsuloj; ili procesu unu kontraŭ alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Sed se vi faras esploron pri io alia, tio decidiĝos en la laŭleĝa kunveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Ĉar estas danĝero, ke oni akuzos nin pri tumulto rilate la hodiaŭan aferon, pro manko de motivo; kaj rilate ĝin, ni ne povos pravigi ĉi tiun homamasiĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, 'Kaj tion dirinte, li dissendis la kunvenintojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Kaj kiam la tumulto ĉesiĝis, Paŭlo, veniginte al si kaj admoninte la disĉiplojn, adiaŭis ilin, kaj foriris, por iri en Makedonujon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Kaj trairinte tiujn regionojn, kaj per multaj paroloj kuraĝiginte la tieulojn, li venis en Grekujon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'Kaj pasiginte tie tri monatojn, post konspiro farita de la Judoj kontraŭ li, kiam li volis ŝipiri al Sirio, li decidis reveni tra Makedonujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Kaj ĝis Azio akompanis lin Sopater el Berea, la filo de Pirho; kaj el la Tesalonikanoj, Aristarĥo kaj Sekundo; kaj Gajo el Derbe, kaj Timoteo; kaj Tiĥiko kaj Trofimo, Azianoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Sed ĉi tiuj, antaŭirinte, atendis nin en Troas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'Kaj ni ŝipiris de Filipi post la tagoj de macoj, kaj alvenis al ili en Troas post kvin tagoj, kaj tie ni restis sep tagojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'Kaj en la unua tago de la semajno, kiam ni kunvenis, por dispecigi panon, Paŭlo paroladis al ili, intencante foriri en la sekvanta tago; kaj li daŭrigis sian paroladon ĝis noktomezo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'Kaj estis multaj lumiloj en la supra ĉambro, kie ni kunvenis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Kaj sur la fenestro sidis junulo, nomata Eŭtiĥo, premegata de profunda dormo; kaj dum Paŭlo ankoraŭ longe paroladis, tiu, venkite de la dormo, falis malsupren de la tria etaĝo, kaj estis levita malviva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Kaj Paŭlo malsupreniris, kaj falis sur lin, kaj ĉirkaŭpreninte lin, diris: Ne maltrankviliĝu; ĉar lia vivo estas en li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Kaj suprenirinte, kaj dispeciginte la panon, kaj manĝinte, kaj parolinte kun ili longe, ĝis la tagiĝo, fine li foriris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'Kaj ili alkondukis la knabon vivantan, kaj multe konsoliĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'Sed ni, irinte pli frue al la ŝipo, ekveturis al Asos, por tie enŝipigi Paŭlon; ĉar tiel li aranĝis, intencante mem piediri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'Kaj kiam li renkontis nin en Asos, ni enŝipigis lin, kaj venis al Mitilene.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'Kaj de tie ŝipirinte, ni alvenis la sekvantan tagon kontraŭ Ĥios; kaj la duan tagon ni atingis Samoson; kaj la trian tagon ni alvenis en Mileton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Ĉar Paŭlo decidis preterveturi Efeson, por ne perdi tempon en Azio; ĉar li rapidis, por esti en Jerusalem, se li nur povos, en la Pentekosta tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Kaj de Mileto li sendis al Efeso, kaj alvokis al si la presbiterojn de la eklezio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'Kaj kiam ili alvenis, li diris al ili: Vi mem scias de post la tago, kiam mi unue enpaŝis en Azion, kiamaniere mi kondutis inter vi dum la tuta tempo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'servante la Sinjoron kun ĉia humileco, kaj ĉe larmoj kaj ĉe tentoj, kiuj okazis al mi per la konspiroj de la Judoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'kaj ke mi ne hezitis deklari al vi ĉion utilan, instruante vin publike, kaj de domo al domo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'ateston farante al Judoj kaj Grekoj pri pento antaŭ Dio kaj pri fido al nia Sinjoro Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'Kaj nun jen, enkatenite en spirito, mi iras al Jerusalem, ne sciante, kio okazos al mi tie,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'krom tio, ke la Sankta Spirito atestas al mi en ĉiu urbo, dirante, ke katenoj kaj afliktoj min atendas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Sed mi taksas je nenio mian vivon kiel al mi mem karan, se nur mi povos plenumi mian kuradon, kaj la komision, kiun mi ricevis de la Sinjoro Jesuo, atesti la evangelion de la graco de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'Kaj nun jen mi scias, ke vi ĉiuj, inter kiuj mi iradis, predikante la regnon, ne plu vidos mian vizaĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Tial mi atestas al vi hodiaŭ, ke mi estas pura pri la sango de ĉiuj homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'Ĉar mi ne hezitis anonci al vi la tutan intencon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Gardu vin kaj la tutan gregon, en kiu la Sankta Spirito faris vin episkopoj, por nutri la eklezion de Dio, kiun li aĉetis per sia propra sango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Mi scias, ke post mia foriro eniros inter vi kruelaj lupoj, ne lasante la gregon sendifekta;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'kaj eĉ el inter vi mem leviĝos viroj perverse parolantaj, por forlogi post si la disĉiplojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Tial gardu vin, memorante, ke dum tri jaroj mi ne ĉesis admoni ĉiun nokte kaj tage kun larmoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'Kaj nun mi vin rekomendas al Dio kaj al la vorto de Lia graco, kiu povas vin edifi kaj doni al vi la heredon inter ĉiuj sanktigitoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Mi ne deziras ies arĝenton, nek oron, nek vestaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Vi mem scias, ke ĉi tiuj manoj servadis al miaj bezonoj kaj al miaj kunuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'En ĉio mi montris al vi, ke tiel laborante, vi devas helpi la malfortulojn, kaj memori la vortojn de la Sinjoro Jesuo, kiujn li mem diris: Pli feliĉe estas doni, ol ricevi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'Kaj tiel dirinte, li genuiĝis, kaj preĝis kun ili ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'Kaj ĉiuj ploregis, kaj falis sur la kolon de Paŭlo kaj lin kisis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'malĝojante precipe pro la vorto, kiun li diris, ke ili ne plu vidos lian vizaĝon. Kaj ili akompanis lin ĝis la ŝipo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Kaj kiam ni, apartiĝinte de ili, ekŝipiris, ni rekte veturis al Kos, kaj en la sekvanta tago al Rodo, kaj de tie al Patara;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'kaj trovinte ŝipon transirontan al Fenikio, ni enŝipiĝis kaj ekveturis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'Kaj ekvidinte Kipron kaj lasinte ĝin maldekstre, ni veturis al Sirio, kaj elŝipiĝis en Tiro; ĉar tie la ŝipo devis senŝarĝiĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'Kaj trovinte la disĉiplojn, ni restis tie sep tagojn; kaj tiuj diris al Paŭlo per la Spirito, ke li ne aliru Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Kaj pasiginte la tagojn, ni eliris kaj ekvojaĝis; kaj ili ĉiuj kune kun edzinoj kaj infanoj akompanis nin ĝis ekster la urbo; kaj genuiĝinte sur la marbordo, ni preĝis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'kaj adiaŭinte unuj aliajn, ni enŝipiĝis, kaj ili returne iris hejmen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Kaj fininte la marvojaĝon de Tiro, ni alvenis ĉe Ptolemais; kaj ni salutis la fratojn, kaj restis kun ili unu tagon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'Kaj en la sekvanta tago ni foriris, kaj alvenis en Cezarean; kaj enirinte en la domon de la evangeliisto Filipo, kiu estis unu el la sepo, ni restis ĉe li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'Ĉi tiu havis kvar filinojn virgulinojn, kiuj profetadis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Kaj dum ni restis tie ankoraŭ dum kelke da tagoj, unu profeto, nomata Agabo, alvojaĝis el Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'Kaj veninte al ni, li prenis la zonon de Paŭlo, kaj ligis siajn piedojn kaj manojn, kaj diris: Tiele diras la Sankta Spirito: Tiamaniere la Judoj en Jerusalem ligos la viron, kies estas ĉi tiu zono, kaj ili transdonos lin en la manojn de la nacianoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'Kaj aŭdinte tion, ni kaj la tieuloj petis lin, ke li ne aliru Jerusalemon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Sed Paŭlo respondis: Kion vi faras, plorante kaj dispremante mian koron? ĉar mi estas preta ne nur esti ligita, sed ankaŭ morti en Jerusalem pro la nomo de la Sinjoro Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'Kaj kiam li ne konsentis, ni silentis, dirante: Plenumiĝu la volo de la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Kaj post tiuj tagoj ni pretigis niajn pakaĵojn, kaj supreniris al Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'Kaj iris ankaŭ kun ni kelkaj el la disĉiploj el Cezarea, kunkondukante Mnasonon, Kipranon, unuatempan disĉiplon, ĉe kiu ni devis loĝadi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'Kaj kiam ni alvenis en Jerusalemon, la fratoj nin ĝoje akceptis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'Kaj la sekvantan tagon Paŭlo akompanis nin al Jakobo, kaj ĉiuj presbiteroj ĉeestis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Kaj salutinte ilin, li rakontis detale ĉion, kion Dio faris inter la nacianoj per lia servado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Kaj tion aŭdinte, ili gloris Dion; kaj ili diris al li: Vi vidas, frato, kiom da miloj da kredantoj estas el inter la Judoj, kaj ili ĉiuj estas fervoruloj por la leĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'kaj oni raportis al ili pri vi, ke vi instruas ĉiujn Judojn, kiuj estas inter la nacianoj, forlasi Moseon, dirante, ke ili ne cirkumcidu la infanojn, nek sekvu la kutimojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Kio do estas? nepre ili aŭdos, ke vi venis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Faru do tion, kion ni diras al vi: Ni havas kvar virojn, kiuj faris sanktan promeson;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'prenu ĉi tiujn, sanktigu vin kun ili, kaj pagu iliajn elspezojn, por ke ili razu sian kapon; kaj ĉiuj scios, ke nenia vero estas en tio, kion oni raportis pri vi, sed ke vi mem ankaŭ iradas orde, observante la leĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Sed koncerne la nacianojn, kiuj ekkredis, ni jam skribis, decidante, ke ili gardu sin kontraŭ idoloferitaĵoj kaj sango kaj sufokitaĵo kaj malĉasteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Tiam Paŭlo alprenis al si la virojn, kaj, sanktiginte sin kun ili, en la sekvanta tago li eniris en la templon, kaj deklaris la plenumon de la tagoj de la purigado, ĝis la oferaĵo estos alportita por ĉiu el ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Kaj kiam la sep tagoj preskaŭ finiĝis, la Judoj el Azio, vidinte lin en la templo, incitis la tutan homamason, kaj lin kaptis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'ekkriante: Izraelidoj, helpu: Jen estas la viro, kiu ĉie instruadas ĉiujn kontraŭ la popolo kaj la leĝo kaj ĉi tiu loko, kaj ankaŭ li kondukis Grekojn en la templon kaj profanis ĉi tiun sanktan lokon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'Ĉar ili antaŭe vidis kun li en la urbo la Efesanon Trofimo; kaj ili supozis, ke Paŭlo kondukis lin en la templon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'Kaj la tuta urbo ekscitiĝis, kaj la popolo kunkuris; kaj preninte Paŭlon, oni trenis lin ekster la templon; kaj tuj la pordoj estis ŝlositaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'Kaj dum ili penis lin mortigi, famo venis al la ĉefkapitano de la kohorto, ke la tuta Jerusalem tumultas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'Kaj li tuj kunvokis soldatojn kaj centestrojn, kaj kuris malsupren sur ilin; kaj ĉi tiuj, vidinte la ĉefkapitanon kaj soldatojn, ĉesis bati Paŭlon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Tiam la ĉefkapitano alproksimiĝis, kaj arestis lin, kaj ordonis, ke oni ligu lin per du katenoj, kaj demandis, kiu li estas, kaj kion li faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'Kaj la amaso kriadis diverse ion kaj alion; kaj, ne povante konstati la ĝuston pro la tumulto, li ordonis, ke oni konduku lin en la fortikaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'Kaj kiam li venis sur la ŝtuparon, li estis portata de la soldatoj pro la perforto de la amaso;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'ĉar la multego de la popolo sekvis, kriante: Forigu lin!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'Kaj Paŭlo, jam enkondukota en la fortikaĵon, diris al la ĉefkapitano: Ĉu estas permesate al mi diri ion al vi? Kaj li diris: Ĉu vi scias la Grekan lingvon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'Ĉu vi ne estas la Egipto, kiu antaŭ kelka tempo ekmovis ribele kaj elkondukis en la dezerton la kvar mil virojn de la Sikarioj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'Sed Paŭlo diris: Mi estas Judo el Tarso en Kilikio, burĝo de urbo ne malnobla; kaj mi petas vin, permesu al mi paroli al la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'Kaj kiam li tion permesis, Paŭlo, starante sur la ŝtuparo, gestis per la mano al la popolo; kaj kiam fariĝis granda silento, li parolis al ili en la Hebrea lingvo, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, 'Fratoj kaj patroj, aŭskultu la pledon, kiun mi faras nun antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Kaj kiam ili aŭdis, ke li parolas al ili en la Hebrea lingvo, ili des pli silentiĝis; kaj li diris:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, 'Mi estas Judo, naskita en Tarso en Kilikio, sed edukita en ĉi tiu urbo ĉe la piedoj de Gamaliel, kaj instruita laŭ la preciza maniero de nia prapatra leĝo, kaj mi estis fervora pro Dio, kiel vi ĉiuj estas hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'Kaj mi persekutis ĉi tiun Vojon ĝis la morto, katenante kaj en karcerojn transdonante virojn kaj virinojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'Kiel ankaŭ atestas pri mi la ĉefpastro kaj la tuta pliaĝularo, de kiuj mi ankaŭ ricevis leterojn por la fratoj, kaj iris al Damasko, por konduki tiujn, kiuj tie estis, katenitajn al Jerusalem, por puniĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Kaj dum mi vojaĝis kaj alproksimiĝis al Damasko, ĉirkaŭ tagmezo subite ekbrilis el la ĉielo granda lumo ĉirkaŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'Kaj mi falis sur la teron, kaj aŭdis voĉon dirantan al mi: Saŭlo, Saŭlo, kial vi min persekutas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Kaj mi respondis: Kiu vi estas, Sinjoro? Kaj li diris al mi: Mi estas Jesuo, la Nazaretano, kiun vi persekutas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'Kaj tiuj, kiuj estis kun mi, vidis ja la lumon, sed ne aŭdis la voĉon de tiu, kiu parolis al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'Kaj mi diris: Kion mi faru, Sinjoro? Kaj la Sinjoro diris al mi: Leviĝu, kaj iru al Damasko; kaj tie vi ricevos informon pri ĉio, kio estas difinita, ke vi ĝin faru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Kaj, ĉar mi ne povis vidi pro la gloro de tiu lumo, mi eniris en Damaskon mane kondukata de tiuj, kiuj estis kun mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Kaj unu Ananias, piulo laŭ la leĝo, bone atestata de ĉiuj Judoj tie loĝantaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'venis al mi, kaj apudstarante, diris al mi: Frato Saŭlo, ricevu vian vidpovon. Kaj en tiu sama horo mi ekvidis, kaj lin rigardis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'Kaj li diris: La Dio de niaj patroj difinis vin, por ke vi sciu Lian vojon kaj vidu la Justulon kaj aŭdu voĉon el lia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'Ĉar vi estos lia atestanto antaŭ ĉiuj homoj pri ĉio, kion vi vidis kaj aŭdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'Kaj nun kial vi prokrastas? leviĝu, kaj baptiĝu, kaj forlavu viajn pekojn, vokante lian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'Kaj reveninte al Jerusalem kaj preĝante en la templo, mi estis en ekstazo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'kaj mi vidis lin dirantan al mi: Rapidu, kaj eliru tuj el Jerusalem, ĉar ili ne akceptos vian ateston pri mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'Kaj mi diris: Sinjoro, ili mem scias, ke mi malliberigis kaj batis en ĉiuj sinagogoj tiujn, kiuj kredas al vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'kaj kiam estis verŝata la sango de via martiro Stefano, mi ankaŭ staris apude kaj konsentis, kaj gardis la vestojn de tiuj, kiuj lin mortigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'Kaj li diris al mi: Foriru; ĉar mi vin sendos malproksimen al la nacianoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'Ili aŭskultis lin ĝis tiu vorto, sed tiam ili levis sian voĉon, dirante: Forigu tian homon de sur la tero; ĉar ne decas, ke li vivu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Kaj dum ili kriis kaj forĵetis siajn vestojn kaj ĵetis polvon en la aeron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'la ĉefkapitano ordonis konduki lin en la fortikaĵon, kaj diris, ke oni ekzamenu lin per skurĝado, por ke li sciiĝu, kial oni tiel forte kriis kontraŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'Kaj kiam ili ligis lin per rimenoj, Paŭlo diris al la apudstaranta centestro: Ĉu estas laŭleĝe por vi skurĝi Romanon ne kondamnitan?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Kaj kiam la centestro tion aŭdis, li iris al la ĉefkapitano kaj raportis, dirante: Kion vi celas fari? ĉar ĉi tiu viro estas Romano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Kaj la ĉefkapitano venis, kaj diris al li: Diru al mi, ĉu vi estas Romano? Kaj li diris: Jes.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'Kaj la ĉefkapitano respondis: Per granda sumo mi akiris tiun civitanecon. Kaj Paŭlo respondis: Sed mi naskiĝis tia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Tiuj do, kiuj devis ekzameni lin, tuj foriris de li; kaj la ĉefkapitano ankaŭ timis, konstatinte, ke tiu estas Romano, kaj ke li lin ligis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'Sed en la sekvanta tago, ĉar li volis certiĝi, pri kio la Judoj lin akuzis, li malligis al li la katenojn, kaj ordonis, ke la ĉefpastroj kaj la tuta sinedrio kunvenu; kaj li kondukis Paŭlon malsupren, kaj starigis lin antaŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Kaj Paŭlo, fikse rigardante la sinedrion, diris: Fratoj, mi vivadis antaŭ Dio laŭ tute bona konscienco ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Kaj la ĉefpastro Ananias ordonis al la apudstarantoj frapi lian buŝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Tiam diris Paŭlo al li: Dio vin frapos, vi kalkeblanka muro; ĉu vi sidas, por juĝi min laŭ la leĝo, kaj kontraŭ la leĝo ordonas, ke oni min frapu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Kaj la apudstarantoj diris: Ĉu vi insultas la ĉefpastron de Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Kaj Paŭlo diris: Mi ne sciis, fratoj, ke li estas ĉefpastro; ĉar estas skribite: Estron de via popolo ne insultu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Sed kiam Paŭlo eksciis, ke unu parto konsistas el Sadukeoj, kaj la alia el Fariseoj, li ekkriis en la sinedrio: Fratoj, mi estas Fariseo, filo de Fariseo; pri la espero kaj la releviĝo de la mortintoj mi estas juĝata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Kaj kiam li tion diris, malpaco okazis inter la Fariseoj kaj la Sadukeoj, kaj la ĉeestantaro dividiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Ĉar la Sadukeoj diras, ke ne estas releviĝo, nek anĝelo, nek spirito; sed la Fariseoj konfesas ambaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'Kaj fariĝis bruego; kaj kelkaj skribistoj el la partio de la Fariseoj stariĝis, kaj forte insistis, dirante: Ni trovas nenian malbonon en ĉi tiu viro; kaj kio, se parolis al li spirito aŭ anĝelo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'Kaj kiam fariĝis granda malpaco, la ĉefkapitano, timante, ke Paŭlo estos disŝirita de ili, ordonis al la soldataro malsupreniri kaj forkapti lin perforte el la mezo de ili, kaj konduki lin en la fortikaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'Kaj la sekvantan nokton la Sinjoro staris apud li, kaj diris: Kuraĝu; ĉar kiel vi jam atestis pri mi en Jerusalem, tiel vi devas atesti ankaŭ en Romo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Kaj je la tagiĝo la Judoj konspiris, kaj per solena ĵuro sin ligis, dirante, ke ili nek manĝos nek trinkos, ĝis ili mortigos Paŭlon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Kaj pli ol kvardek estis la tiel kunĵurintaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Kaj ili venis al la ĉefpastroj kaj la pliaĝuloj, kaj diris: Ni per solena ĵuro ligis nin gustumi nenion, ĝis ni mortigos Paŭlon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Nun do vi kune kun la sinedrio instigu la ĉefkapitanon, ke li konduku lin al vi, kvazaŭ vi volus juĝi pri la afero pli precize; kaj ni, antaŭ ol li alproksimiĝos, estos pretaj pereigi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Sed la filo de la fratino de Paŭlo, enveninte, aŭdis pri la embusko, kaj li iris en la fortikaĵon, kaj pri tio sciigis Paŭlon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Kaj Paŭlo alvokis unu el la centestroj, kaj diris: Konduku ĉi tiun junulon al la ĉefkapitano, ĉar li havas ion por diri al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'Li do prenis lin kaj kondukis lin al la ĉefkapitano, kaj diris: La katenito Paŭlo min alvokis, kaj petis, ke mi konduku al vi ĉi tiun junulon, kiu havas ion por diri al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Kaj la ĉefkapitano prenis lian manon, kaj, flankenirante, demandis lin aparte: Kio estas tio, kion vi havas por diri al mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'Kaj li diris: La Judoj interkonsentis peti, ke vi konduku Paŭlon malsupren morgaŭ en la sinedrion, kvazaŭ ili intencus fari pri li esploron iom pli precizan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Sed ne konsentu al ili, ĉar embuskas kontraŭ li pli ol kvardek el ili, kiuj per solena ĵuro sin ligis nek manĝi nek trinki, ĝis ili lin pereigos; kaj nun ili estas pretaj, kaj atendas de vi la promeson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Tiam la ĉefkapitano forsendis la junulon, ordonante al li: Eldiru al neniu, ke vi sciigis min pri ĉi tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'Kaj alvokinte du el la centestroj, li diris: Pretigu ducent soldatojn, por ke ili iru ĝis Cezarea, kun sepdek rajdistoj kaj ducent lancistoj, je la tria horo nokte;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'kaj provizu bestojn, por sidigi Paŭlon kaj konduki lin sendanĝere al Felikso, la provincestro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'Kaj li skribis leteron laŭ jena formo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, 'Klaŭdio Lisias al lia ekscelenco Felikso, la provincestro, saluton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Ĉi tiu viro estis kaptita de la Judoj, kaj ili volis mortigi lin; sed mi alvenis kun la soldataro kaj forsavis lin, sciiĝinte, ke li estas Romano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'Kaj dezirante scii la kaŭzon, pro kio ili lin akuzas, mi lin enkondukis en ilian sinedrion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'kaj mi trovis lin akuzata pri demandoj rilatantaj al ilia leĝo, sed havanta nenian akuzon meritantan morton aŭ katenojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'Kaj ĉar oni montris al mi, ke estos konspiro kontraŭ la viro, mi tuj sendis lin al vi, ordonante ankaŭ, ke liaj akuzantoj atestu kontraŭ li antaŭ vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Tial la soldatoj, kiel estis ordonite al ili, prenis Paŭlon kaj kondukis lin nokte al Antipatris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'Kaj en la sekvanta tago ili lasis la rajdistojn iri kun li, kaj ili ekiris returne al la fortikaĵo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'sed tiuj, enirinte en Cezarean kaj transdoninte la leteron al la provincestro, enkondukis ankaŭ Paŭlon antaŭ lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'Kaj kiam li ĝin legis, li demandis, el kiu provinco li venas; kaj kiam li sciiĝis, ke li estas el Kilikio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'li diris: Mi aŭskultos vian proceson, kiam viaj akuzantoj ankaŭ ĉeestos; kaj li ordonis, ke oni gardu lin en la palaco de Herodo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Kaj post kvin tagoj la ĉefpastro Ananias malsupreniris tien kun kelkaj pliaĝuloj, kaj unu advokato, nomata Tertulo; kaj ili faris denuncon antaŭ la provincestro kontraŭ Paŭlo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'Kaj kiam ĉi tiu estas vokita, Tertulo komencis akuzi lin, dirante: Ĉar ni ĝuadas grandan trankvilecon per vi, kaj malbonaĵoj estas ĝustigitaj por ĉi tiu nacio per via antaŭzorgeco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'ni akceptas tion, ĉiel kaj ĉie, plej nobla Felikso, kun plena dankemeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Sed (por ke mi vin ne tro tedu) mi vin petegas aŭskulti nin mallonge, laŭ via bonkoreco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Ĉar ni trovis ĉi tiun viron pestulo, kaj incitanta al ribelado inter ĉiuj Judoj tra la tuta mondo, kaj ĉefo de la Nazaretana sekto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'li provis ankaŭ profani la templon; kaj ni arestis lin kaj volis juĝi lin laŭ nia leĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'Sed la ĉefkapitano Lisias venis, kaj per granda perforto forprenis lin el niaj manoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'kaj ordonis al liaj akuzantoj veni antaŭ vin; kaj nun, ekzamenante lin, vi mem povos certiĝi pri ĉio, pro kio ni lin akuzas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Kaj la Judoj ankaŭ konsentis, dirante, ke ĉi tio estas vera.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Tiam Paŭlo, kiam la provincestro signis, ke li parolu, respondis: Sciante, ke jam de multaj jaroj vi estas juĝisto por ĉi tiu nacio, mi des pli volonte min defendas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'ĉar vi povas certiĝi, ke pasis ne pli ol dek du tagoj, de kiam mi supreniris al Jerusalem, por adorkliniĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'kaj ili ne trovis min disputanta kun iu aŭ incitanta la popolon en la templo, nek en la sinagogoj, nek en la urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'Kaj ili ne povas pruvi la aferojn, pri kiuj ili nun akuzas min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Sed mi konfesas al vi jenon: ke laŭ tiu Vojo, kiun ili nomas sekto, mi adoras la Dion de miaj patroj, kredante ĉion, kio estas laŭ la leĝo, kaj ĉion skribitan en la profetoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'kaj mi havas tiun esperon al Dio, kiun ili mem ankaŭ akceptas, ke estos iam releviĝo de la justuloj kaj de la maljustuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'En ĉi tio ankaŭ mi min ekzercadas, havi ĉiam konsciencon neriproĉeblan antaŭ Dio kaj homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Kaj post multe da jaroj mi alvenis, por alporti al mia nacio almozojn kaj oferojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'ĉe tiaj okupoj ili trovis min sanktigitan en la templo, ne kun homamaso, nek kun tumulto; sed ĉeestis iuj Judoj el Azio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'kiuj devus esti ĉi tie antaŭ vi kaj fari akuzon, se ili havus ion kontraŭ mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Alie ĉi tiuj mem diru, kian malbonfaron ili trovis en mi, kiam mi staris antaŭ la sinedrio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'krom eble pri unu vorto, kiun mi jene kriis, starante inter ili: Pri la releviĝo de la mortintoj mi estas juĝata de vi hodiaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Sed Felikso, konante iom precize la Vojon, prokrastis rilate ilin, kaj diris: Kiam alvenos la ĉefkapitano Lisias, tiam mi decidos vian aferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'Kaj li ordonis al la centestro gardi Paŭlon kun malsevereco, kaj ne malpermesi al iu ajn el liaj amikoj lin viziti kaj helpi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'Kaj post kelke da tagoj, Felikso venis kun sia edzino Drusila, kiu estis Judino, kaj li venigis al si Paŭlon kaj aŭskultis lin pri la fido al Kristo Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'Kaj dum Paŭlo rezonis pri justeco, sinregado, kaj la juĝo estonta, Felikso timiĝis, kaj respondis: La nunan fojon foriru; kiam mi havos oportunan tempon, mi alvokos vin al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Li ankaŭ esperis, ke mono estos donita de Paŭlo al li, por ke li lin liberigu; tial li des pli ofte venigis Paŭlon kaj interparoladis kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Sed post du jaroj Felikso estis anstataŭita de Porcio Festo; kaj Felikso, dezirante akiri favoron ĉe la Judoj, lasis Paŭlon ligita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Festo do, veninte en la provincon, post tri tagoj supreniris de Cezarea al Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Kaj la ĉefpastro kaj la ĉefoj de la Judoj faris denuncon al li kontraŭ Paŭlo, kaj lin instigis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'petante de li favoron kontraŭ Paŭlo, ke li venigu lin al Jerusalem; ĉar ili aranĝis embuskon, por mortigi lin sur la vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Tamen Festo respondis, ke Paŭlo estas gardata en Cezarea, kaj ke li mem baldaŭ iros tien.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'Tial, li diris, la eminentuloj el vi tien iru kun mi, kaj se estas io krima en la viro, ili lin akuzu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'Kaj restinte inter ili ne pli ol ok aŭ dek tagojn, li iris al Cezarea; kaj en la sekvanta tago li sidiĝis sur la tribunala seĝo, kaj ordonis, ke oni alkonduku Paŭlon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Kaj kiam li alestis, la Judoj, kiuj malsupreniris de Jerusalem, staris ĉirkaŭe, akuzante lin pri multaj kaj gravaj kulpoj, kiujn ili ne povis pruvi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'tiam Paŭlo responde pledis: Nek kontraŭ la leĝo de la Judoj, nek kontraŭ la templo, nek kontraŭ Cezaro mi iamaniere ofendis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Sed Festo, dezirante akiri favoron ĉe la Judoj, respondis al Paŭlo, dirante: Ĉu vi volas supreniri al Jerusalem, kaj tie esti juĝata antaŭ mi pri ĉi tiuj aferoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Sed Paŭlo diris: Mi staras antaŭ la tribunalo de Cezaro, kie mi devas esti juĝata; kontraŭ la Judoj mi faris nenian malbonon, kiel ankaŭ vi tre bone scias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Se do mi estas krimulo, kaj faris ion meritantan morton, mi ne rifuzas morti; sed se estas vera nenio el tiuj aferoj, pri kiuj ili min akuzas, neniu povas cedi min al ili. Mi apelacias al Cezaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Tiam Festo, kunparolinte kun la konsilantaro, respondis: Vi apelaciis al Cezaro; al Cezaro vi devos iri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Kaj post paso de kelke da tagoj, la reĝo Agripo kaj Bernike venis al Cezarea kaj salutis Feston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Kaj dum ili restis tie multajn tagojn, Festo montris al la reĝo la aferon de Paŭlo, dirante: Felikso lasis katenita unu viron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'pri kiu, kiam mi estis en Jerusalem, la ĉefpastro kaj pliaĝuloj de la Judoj sciigis min, postulante juĝon kontraŭ li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Al ili mi respondis, ke ĉe la Romanoj ne estas moro transdoni iun al morto, antaŭ ol la akuzito havos la akuzantojn vizaĝon kontraŭ vizaĝo, kaj ricevos permeson defendi sin pri la akuzo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Kiam do ili kunvenis ĉi tien, mi faris nenian prokraston, sed en la sekvanta tago mi sidiĝis sur la tribunala seĝo kaj ordonis alkonduki la viron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'La akuzantoj, stariĝinte, prezentis pri li nenian kulpigon tian, kian mi atendis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'sed havis kelkajn demandojn kontraŭ li pri sia propra religio, kaj pri unu Jesuo, kiu mortis, kaj pri kiu Paŭlo asertis, ke li vivas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Kaj mi, en embaraso, kiel fari ekzamenon pri tio, demandis, ĉu li volas iri al Jerusalem kaj tie esti juĝata koncerne tiun aferon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Sed kiam Paŭlo apelaciis, ke li estu rezervata por la decido de lia Imperiestra Moŝto, mi ordonis gardi lin, ĝis mi povos lin sendi al Cezaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Kaj Agripo diris al Festo: Volonte ankaŭ mi aŭskultus tiun viron. Morgaŭ, li diris, vi lin aŭskultos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Tial en la sekvanta tago, kiam venis Agripo kaj Bernike kun grandioza parado, kaj ili eniris en la aŭditorion kun la ĉefkapitanoj kaj la eminentuloj el la urbo, Festo ordonis, kaj oni enkondukis Paŭlon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'Kaj Festo diris: Reĝo Agripo, kaj ĉiuj viroj, kiuj ĉeestas kun ni, vi vidas ĉi tiun, pri kiu la tuta amaso de la Judoj instigis min en Jerusalem kaj ankaŭ ĉi tie, kriante, ke ne decas, ke li vivu plu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Sed mi trovis, ke li ne faris ion meritantan morton; kaj ĉar li mem apelaciis al lia Imperiestra Moŝto, mi decidis sendi lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'Sed pri li mi havas nenion precizan por skribi al mia sinjoro. Tial mi elkondukis lin antaŭ vin ĉiujn, kaj precipe antaŭ vin, reĝo Agripo, por ke post ekzameno mi havu ion por skribi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'Ĉar ŝajnas al mi senracie, sendi arestiton, kaj ne klarigi la akuzojn kontraŭ li metitajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Kaj Agripo diris al Paŭlo: Estas permesate al vi paroli por vi mem. Tiam Paŭlo, etendinte sian manon, responde pledis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, 'Mi min trovas feliĉa, reĝo Agripo, ke mi respondos antaŭ vi hodiaŭ rilate ĉion, pri kio mi estas akuzita de la Judoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'precipe ĉar vi estas klera pri ĉiuj moroj kaj demandoj, kiuj ekzistas ĉe la Judoj; tial mi petegas vin aŭskulti min pacience.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Mian vivmanieron de post mia juneco, kiu estis de la komenco en mia nacio, en Jerusalem, ĉiuj Judoj scias,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'konante min jam longe, kaj sciante (se ili volus atesti), ke laŭ la plej severa sekto de nia religio mi vivis Fariseo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'Kaj nun mi staras ĉi tie juĝota pro la espero de la promeso farita de Dio al niaj patroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'al kiu promeso niaj dek du triboj, fervore servante Dion nokte kaj tage, esperas atingi. Kaj pri tiu espero mi estas akuzita de la Judoj, ho reĝo!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Kial oni ĉe vi opinias nekredinde, ke Dio levos la mortintojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Mi mem ja pensis en mi, ke mi devas fari multajn agojn kontraŭ la nomo de Jesuo, la Nazaretano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'Kaj tion mi ankaŭ faris en Jerusalem; kaj multajn el la sanktuloj en karcerojn mi enŝlosis, ricevinte de la ĉefpastroj la aŭtoritaton, kaj ĉe ilia mortigado mi ilin per voĉdono kondamnis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'Kaj punante ilin tre ofte en ĉiuj sinagogoj, mi penis devigi ilin blasfemi; kaj forte furiozante kontraŭ ili, mi persekutis ilin eĉ ĝis fremdaj urboj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'Por tiaj celoj vojaĝante al Damasko kun aŭtoritato kaj komisio de la ĉefpastroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'mi vidis tagmeze, ho reĝo, sur la vojo lumon el la ĉielo, superantan la helecon de la suno, brilantan ĉirkaŭ mi kaj miaj kunvojaĝantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'Kaj kiam ni ĉiuj falis sur la teron, mi aŭdis voĉon, dirantan al mi en la Hebrea lingvo: Saŭlo, Saŭlo, kial vi min persekutas? estas malfacile por vi piedbati kontraŭ la pikiloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'Kaj mi diris: Kiu vi estas, Sinjoro? Kaj la Sinjoro diris: Mi estas Jesuo, kiun vi persekutas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Sed leviĝu, kaj stariĝu sur viaj piedoj; ĉar por tio mi aperis al vi, por difini vin kiel servanton al mi kaj atestanton pri la cirkonstancoj, en kiuj vi jam vidis min, kaj ankaŭ en kiuj mi poste aperos al vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'liberigante vin de la popolo kaj de la nacianoj, al kiuj mi vin sendas,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'por malfermi iliajn okulojn, ke ili sin turnu de mallumo al lumo, kaj de la aŭtoritato de Satano al Dio, por ke ili ricevu pardonon de pekoj, kaj heredaĵon inter tiuj, kiuj sanktiĝis per fido al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Tial, ho reĝo Agripo, mi ne iĝis malobeema al la ĉiela vizio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'sed proklamis unue al la Damaskanoj, kaj en Jerusalem, kaj tra la tuta regiono de Judujo, kaj ankaŭ al la nacianoj, ke ili pentu kaj sin turnu al Dio, farante farojn indajn je pento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'Pro ĉi tio la Judoj kaptis min en la templo kaj celis mortigi min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Ricevinte do la helpon, kiu estas de Dio, mi staras ĝis la nuna tago, atestante al malgranduloj kaj granduloj, dirante nenion krom tio, kion la profetoj kaj Moseo anoncis kiel venontan:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'ke la Kristo devas suferi, kaj ke li unua per la revivigado de mortintoj proklamos lumon al la popolo kaj al la nacianoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'Kaj dum li tiel pledis, Festo diris per laŭta voĉo: Paŭlo, vi frenezas; multe da studado vin frenezigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Sed Paŭlo diris: Mi ne frenezas, plej nobla Festo, sed mi malkaŝe parolas vortojn de vero kaj prudento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Ĉar tiujn aferojn tre bone scias la reĝo, al kiu mi parolas maltime; ĉar mi konvinkiĝis, ke nenio el ĉi tio estas kaŝita for de li, ĉar ĉi tio ne estas farita en angulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Reĝo Agripo, ĉu vi kredas la profetojn? mi ja scias, ke vi kredas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Kaj Agripo diris al Paŭlo: En mallonga tempo vi konvinkos min fariĝi Kristano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'Kaj Paŭlo diris: Mi volus preĝi al Dio, ke, ĉu en mallonga aŭ en longa, ne nur vi, sed ankaŭ ĉiuj, kiuj aŭskultas min hodiaŭ, fariĝu tiaj, kia mi estas, krom ĉi tiuj katenoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'Kaj stariĝis la reĝo kaj la provincestro kaj Bernike kaj la kunsidantoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'kaj apartiĝinte, ili parolis inter si, dirante: Tiu viro faris nenion meritantan morton aŭ katenojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Kaj Agripo diris al Festo: Tiu viro povus esti tuj liberigita, se li ne apelacius al Cezaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'Kaj kiam estis decidite, ke ni ŝipiru al Italujo, oni transdonis Paŭlon kaj kelkajn aliajn malliberulojn al centestro, nomata Julio, el la Aŭgusta kohorto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Kaj enirinte en ŝipon el Adramitio, veturontan al la lokoj ĉe la marbordo de Azio, ni ekveturis sur la maron, havante kun ni Aristarĥon, Makedonon el Tesaloniko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'Kaj la sekvantan tagon ni vizitis Cidonon; kaj Julio kondutis afable rilate Paŭlon, kaj permesis al li iri al siaj amikoj kaj refreŝiĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'Kaj irinte de tie sur la maron, ni preterveturis sub la ŝirmo de Kipro, ĉar la ventoj estis kontraŭaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'Kaj transveturinte la maron apud Kilikio kaj Pamfilio, ni alvenis al Mira en Likio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'Kaj la centestro, trovinte tie ŝipon Aleksandrian veturontan al Italujo, enirigis nin en ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'Kaj veturante malrapide dum multe da tagoj kaj venkinte kun malfacileco proksime al Knido (ĉar la vento ne permesis al ni atingi ĝin), ni veturis sub la ŝirmo de Kreto, apud Salmone;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'kaj kun malfacileco veturinte preter la marbordo, ni alvenis al loko, nomata Belaj Havenoj, proksime de kiu estas la urbo Lasaja.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Kaj kiam pasis multe da tempo, kaj la vojaĝo jam fariĝis danĝera, ĉar jam pasis la Fasto, Paŭlo avertis ilin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'dirante al ili: Ho viroj, mi ekvidas, ke la vojaĝo estos kun difekto kaj multa perdo, ne nur de la ŝarĝo kaj de la ŝipo, sed ankaŭ de niaj vivoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Sed la centestro atentis pli la konsilon de la direktilisto kaj la posedanto de la ŝipo, ol la parolon de Paŭlo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'Kaj ĉar la haveno ne estis sufiĉe vasta, por tie travintri, la plimulto konsilis ŝipiri de tie, se eble ili povos atingi Fenikson, havenon de Kreto, kiu rigardas en la direkto al la nordokcidenta kaj la sudokcidenta ventoj, por tie travintri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'Kaj kiam la suda vento blovis malpli forte, ili supozis, ke ili atingis sian celon, kaj levinte la ankrojn, ili preterveturis Kreton tre proksime.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Sed post mallonga tempo atakis nin el ĝi uragana vento, kiu estas nomata Eŭrakilo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'kaj kiam la ŝipo estis kaptita kaj ne povis kontraŭstari al la vento, ni cedis kaj estis pelataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Kaj kurinte sub la ŝirma flanko de insuleto, nomata Kaŭda, ni kun granda klopodo apenaŭ povis savi la boaton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'kaj suprenlevinte ĝin, oni uzis helpilojn, por subzoni la ŝipon; kaj timante, ke ni estos ĵetataj sur la Sirtison, oni mallevis la ilaron kaj tiel estis pelataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'Kaj kiam ni estis treege premataj de la ventego, la sekvantan tagon ili komencis elĵetadon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'kaj la trian tagon oni elĵetis per siaj propraj manoj la ekipaĵon de la ŝipo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Kaj kiam dum multe da tagoj nek suno nek steloj ekbrilis sur nin, kaj uragano nemalgranda ĉirkaŭis nin, fine ĉia espero pri nia savo estis forprenita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Kaj kiam ili jam de longe nenion manĝis, Paŭlo, stariĝinte meze de ili, diris: Ho viroj, vi devis aŭskulti min, kaj ne ŝipiri el Kreto, kaj ne suferi ĉi tiun difekton kaj perdon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Kaj nun mi admonas vin esti kuraĝaj; ĉar estos neniu perdo de vivo inter vi, sed nur de la ŝipo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Ĉar en tiu nokto staris apud mi anĝelo de la Dio, kies mi estas kaj al kiu mi servas,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'dirante: Paŭlo, ne timu; vi devas stari antaŭ Cezaro; kaj jen Dio donacis al vi ĉiujn, kiuj marveturas kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Tial, viroj, kuraĝu; ĉar mi kredas al Dio, ke la afero estos tiel, kiel estas dirite al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Tamen ni devas esti ĵetitaj sur ian insulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'Sed kiam venis la dek-kvara nokto, kaj ni estis ĉirkaŭpelataj en la Adria maro, la maristoj eksentis ĉirkaŭ noktomezo, ke ili alproksimiĝas al ia lando;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'kaj sondinte, ili trovis dudek klaftojn; kaj post mallonga interspaco ili ree sondis, kaj trovis dek kvin klaftojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'Kaj timante, ke ni falos sur malmolajn lokojn, ili ĵetis kvar ankrojn el la ŝiplmalantaŭo, kaj preĝis, ke tagiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'Kaj kiam la maristoj serĉis rimedon forkuri el la ŝipo, kaj jam mallevis la boaton en la maron sub preteksto, ke ili demetos ankrojn el la antaŭo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'Paŭlo diris al la centestro kaj la soldatoj: Se ĉi tiuj ne restos en la ŝipo, vi ne povas saviĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Tiam la soldatoj detranĉis la ŝnurojn de la boato, kaj lasis ĝin defali.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'Sed ĝis venis la tagiĝo, Paŭlo petis ĉiujn, ke ili prenu iom da nutraĵo, kaj li diris: La nuna tago estas la dek-kvara, en kiu vi daŭre atendas kaj fastadas, preninte nenion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Tial mi petas vin preni nutraĵon, ĉar ĉi tio koncernas vian savon; ĉar eĉ unu haro ne pereos el la kapo al vi ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'Kaj dirinte tion kaj preninte panon, li donis dankon al Dio antaŭ ĉiuj; kaj dispeciginte ĝin, li komencis manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Tiam ili ĉiuj kuraĝiĝis, kaj ankaŭ mem prenis nutraĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'Kaj ni ĉiuj en la ŝipo estis ducent sepdek ses animoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'Kaj manĝinte ĝissate, ili malpezigis la ŝipon, elĵetante la tritikon en la maron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'Kaj kiam plene tagiĝis, ili ne rekonis la landon; sed ili ekvidis unu golfeton kun sablaĵo, kaj ili konsiliĝis inter si, ĉu ili povos surpeli sur ĝin la ŝipon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'Kaj forlasinte la ankrojn, ili lasis ilin en la maro, kaj samtempe malligis la ŝnurojn de la direktiloj; kaj suprenlevinte la antaŭvelon kontraŭ la vento, ili sin direktis al la sablaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Sed trafinte lokon, kie du marmovoj sin renkontas, ili surterigis la ŝipon; kaj la antaŭo fiksiĝis kaj restis nemovebla, sed la malantaŭo rompiĝis de la forto de la ondoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'Kaj fariĝis intenco ĉe la soldatoj mortigi la malliberulojn, por ke neniu el ili elnaĝu kaj forkuru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Sed la centestro, dezirante savi Paŭlon, malhelpis ilin de tiu decido, kaj ordonis, ke tiuj, kiuj povas naĝi, forĵetu sin unuaj kaj iru al la tero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'kaj ke la ceteraj sin savu, jen sur tabuloj, jen sur diversaj objektoj el la ŝipo. Kaj tiamaniere ĉiuj saviĝis sur la teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'Kaj kiam ni saviĝis, tiam ni sciiĝis, ke la insulo estas nomata Melita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'Kaj la barbaroj montris al ni neordinaran bonecon; ĉar ili ekbruligis fajron kaj akceptis nin ĉiujn pro la tiama pluvo kaj pro la malvarmeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'Sed kiam Paŭlo kolektis faskon da vergoj kaj metis ĝin sur la fajron, vipuro, elveninte de la varmo, alkroĉiĝis al lia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Kaj kiam la barbaroj vidis la beston pendantan de lia mano, ili diris unu al alia: Sendube ĉi tiu viro estas mortiginto, al kiu, kvankam li saviĝis de la maro, tamen Justeco ne permesas vivi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Sed li forskuis la beston en la fajron, kaj ne suferis malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'Sed ili atendis, ke li ŝvelos aŭ falos subite mortinta; sed longe atendinte, kaj vidinte, ke nenia malbono okazas al li, ili ŝanĝis sian opinion, kaj diris, ke li estas dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'Proksime de tiu loko estis bieno, apartenanta al la estro de la insulo; lia nomo estis Publio; li akceptis nin kaj amike gastigis nin tri tagojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'Kaj la patro de Publio kuŝis malsana de febro kaj disenterio; al li Paŭlo eniris, kaj preĝis, kaj, metinte la manojn sur lin, sanigis lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Kaj post tiu faro, ankaŭ ceteraj insulanoj, kiuj havis malsanojn, venis kaj estis sanigitaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'ĉi tiuj ankaŭ honoris nin per multaj honoroj; kaj kiam ni ekveturis, ili surŝipigis ĉion, kion ni bezonis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'Kaj post tri monatoj ni ekveturis en ŝipo Aleksandria, kiu travintris ĉe la insulo; kaj ĝia insigno estis la Ĝemeloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'Kaj albordiĝinte ĉe Sirakuso, ni restis tie tri tagojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'Kaj de tie ni ĉirkaŭiris kaj alvenis en Region; kaj post unu tago ekblovis suda vento, kaj la duan tagon ni venis al Puteoli,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'kie ni trovis fratojn kaj estis petataj resti ĉe ili sep tagojn, kaj tiel poste ni vojaĝis al Romo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Kaj de tie la fratoj, aŭdinte pri ni, venis al ni renkonte ĝis la Vendejo de Apio kaj la Tri Gastejoj; kaj vidante ilin, Paŭlo dankis Dion, kaj kuraĝiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Kaj kiam ni eniris en Romon, al Paŭlo estis permesate loĝi sola kun la soldato, kiu lin gardis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Kaj post tri tagoj, li kunvokis tiujn, kiuj estis eminentuloj inter la Judoj; kaj kiam ili kunvenis, li diris al ili: Fratoj, kvankam mi faris nenion kontraŭ la popolo nek kontraŭ la moroj de niaj patroj, tamen mi estis transdonita kiel malliberulo el Jerusalem en la manojn de la Romanoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'kiuj, ekzameninte min, volis liberigi min, ĉar en mi estis nenio meritanta morton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Sed kiam la Judoj kontraŭparolis, tiam mi estis devigata apelacii al Cezaro; ne kvazaŭ mi havis ion, pri kio akuzi mian nacion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'Pro tio do mi petis vin viziti min kaj kunparoli, ĉar pro la espero de Izrael mi portas ĉi tiun katenon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Kaj ili diris al li: Ni ne ricevis el Judujo leterojn pri vi, kaj neniu el la fratoj, alveninte, raportis aŭ parolis pri vi ion malbonan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Sed ni deziras aŭdi de vi, kion vi opinias; ĉar pri tiu sekto ni scias, ke ĉie oni kontraŭparolas al ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'Kaj difininte tagon por li, ili grandnombre venis al li en lian loĝejon; kaj li faris al ili klarigon, atestante la regnon de Dio, kaj penante konvinki ilin pri Jesuo, el la leĝo de Moseo kaj el la profetoj, de mateno ĝis vespero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'Kaj unuj kredis la parolitaĵojn, kaj aliaj ne kredis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'Kaj ne konsentante inter si, ili foriris, post kiam Paŭlo parolis unu vorton: Bone parolis la Sankta Spirito per la profeto Jesaja al viaj patroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'dirante: Iru al tiu popolo, kaj diru: Aŭdante, vi aŭdos, sed ne komprenos; Kaj vidante, vi vidos, sed ne rimarkos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'Ĉar la koro de tiu popolo grasiĝis, Kaj iliaj oreloj aŭdas malklare, Kaj siajn okulojn ili fermis, Por ke ili ne vidu per siaj okuloj, Kaj por ke ili ne aŭdu per siaj oreloj, Kaj por ke ili ne komprenu per sia koro, Kaj por ke ili ne konvertiĝu, Kaj por ke Mi ne sanigu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'Certiĝu do al vi, ke ĉi tiu savado de Dio estas sendata al la nacianoj, kaj ili aŭskultos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, 'Kaj kiam li diris tion, la Judoj foriris, havante inter si multe da disputado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'Kaj li loĝadis tutajn du jarojn en sia propra loĝejo, kaj li akceptis ĉiujn, kiuj eniris al li,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'predikante la regnon de Dio, kaj instruante la aferojn pri la Sinjoro Jesuo Kristo kun plena maltimo, malhelpate de neniu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Paŭlo, servisto de Jesuo Kristo, apostolo vokita, apartigita al la evangelio de Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'kiun Li promesis antaŭe per Siaj profetoj en la sanktaj skriboj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'pri Sia Filo, kiu naskiĝis el la idaro de David laŭ la karno,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'la difinita Filo de Dio en potenco laŭ la Spirito de sankteco per la releviĝo de la mortintoj-Jesuo Kristo, nia Sinjoro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'per kiu ni ricevis gracon kaj apostolecon por obeemo de fido ĉe ĉiuj nacioj pro lia nomo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'inter kiuj estas ankaŭ vi, vokitaj de Jesuo Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'al ĉiuj, kiuj estas en Romo, amataj de Dio, vokitaj sanktuloj: Graco al vi kaj paco de Dio, nia Patro, kaj de la Sinjoro Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Unue mi dankas al mia Dio per Jesuo Kristo por vi ĉiuj, ke via fido estas proklamata tra la tuta mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Ĉar mia atestanto estas Dio, kiun mi servas en mia spirito en la evangelio de Lia Filo, ke mi senĉese memorigas pri vi en miaj preĝoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'ĉiam petante, ke iel al mi jam fine prosperos veni al vi per la volo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Ĉar mi sopiras vin vidi, por ke mi transdonu al vi ian spiritan donacon, por ke vi estu firmigitaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'tio estas, por ke estu inter ni reciproka kuraĝigo, per la komuna fido, egale via kaj mia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Kaj mi ne volas, ke vi nesciu, fratoj, ke ofte mi celis veni al vi (sed mi estas malhelpita ĝis nun), por ke mi havu iom da frukto ĉe vi, kiel ankaŭ ĉe la aliaj nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Mi estas ŝuldanto al Grekoj kaj al Barbaroj, al saĝuloj kaj al senprudentuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Tial laŭ mia eblo mi estas fervora prediki la evangelion ankaŭ al vi, kiuj estas en Romo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Ĉar mi ne hontas pri la evangelio; ĉar ĝi estas la potenco de Dio al savo por ĉiu, kiu kredas, al la Judoj unue, kaj ankaŭ al la Grekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Ĉar la justeco de Dio malkaŝiĝas en ĝi de fido al fido, kiel estas skribite: La virtulo vivos per sia fideleco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Ĉar la kolero de Dio malkaŝiĝas el la ĉielo kontraŭ ĉia malpieco kaj maljusteco de homoj, kiuj tenas la veron en maljusteco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'ĉar la scio pri Dio estas elmontrita ĉe ili, ĉar Dio elmontris ĝin al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Ĉar Liaj nevideblaj ecoj de post la kreado de la mondo fariĝas videblaj, sentate per Liaj faritaĵoj, nome, Lia eterna potenco kaj dieco; tial al ili mankas defenda pledo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'ĉar konante Dion, ili ne gloris Lin kiel Dion, nek estis dankemaj, sed vaniĝis per diskutadoj, kaj ilia sensaĝa koro mallumiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Pretendante esti saĝaj, ili malsaĝiĝis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'kaj ŝanĝis la gloron de la senmorta Dio en bildon de morta homo kaj de birdoj kaj kvarpiedaj bestoj kaj rampaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Tial Dio fordonis ilin al la voluptoj de iliaj koroj, al malpureco, por ke iliaj korpoj malhonoriĝu inter ili mem;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'kiuj ŝanĝis la veron de Dio en mensogon, kaj adoris kaj servis la kreitaĵojn prefere ol la Kreinton, kiu estas eterne benata. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Tial Dio fordonis ilin al malhonoraj pasioj; ĉar iliaj virinoj ŝanĝis la naturan uzadon en kontraŭnaturan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'kaj tiel same ankaŭ la viroj, forlasante la naturan uzadon de la virino, brulis en sia volupto unu al alia, kaj viroj kun viroj faris hontindaĵon kaj ricevis en si mem la taŭgan rekompencon de sia malvirto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'Kaj ĉar ili malŝatis teni Dion en sia konado, Dio fordonis ilin al malaprobinda menso, por ke ili faru nedecaĵojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'plenigite de ĉia maljusteco, malvirteco, avideco, malboneco; plenaj de envio, mortigo, malpaco, ruzo, malico; flustrantaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'kalumniantaj, Dimalamantaj, insultantaj, arogantaj, fanfaronemaj, elpensantaj malbonaĵojn, malobeemaj al gepatroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'senprudentaj, nefidindaj, neparencamaj, senkompataj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'kiuj, sciante pri la juĝo de Dio, ke la farantoj de tiaj agoj meritas morton, ne nur mem faras ilin, sed ankaŭ konsentas al la farantoj de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Sekve, vi estas nedefendebla, ho ĉiu homo juĝanta; ĉar dum vi juĝas alian, vi kondamnas vin mem, ĉar vi, la juĝanto, faradas la samajn agojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Kaj ni scias, ke la juĝo de Dio estas laŭ vero kontraŭ tiuj, kiuj faradas tiajn agojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Kaj ĉu vi kalkulas, ho homo, kiu juĝas la farantojn de tiaj agoj kaj faras la samajn, ke vi evitos la juĝon de Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Aŭ ĉu vi malestimas la riĉecon de Lia boneco kaj toleremeco kaj pacienco, ne sciante, ke la boneco de Dio alkondukas vin al pento?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'sed laŭ via obstineco kaj senpenta koro vi amasigas por vi koleron en la tago de kolero kaj malkaŝigo de la justa juĝo de Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'kiu redonos al ĉiu homo laŭ liaj faroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'al tiuj, kiuj per pacienco en bonfarado celas al gloro kaj honoro kaj senmorteco, eternan vivon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'sed al tiuj, kiuj estas malpacemaj kaj ne obeas al la vero, sed obeas al maljusteco, koleron kaj indignon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'aflikton kaj maltrankvilon, sur ĉiun animon de homo, kiu faras malbonon, de Judo unue kaj de Greko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'sed gloron kaj honoron kaj pacon al ĉiu, kiu faras bonon, al Judo unue kaj al Greko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'ĉar ne estas personfavorado ĉe Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Ĉar ĉiu, kiu pekis sen leĝo, ankaŭ pereos sen leĝo; kaj ĉiu, kiu pekis sub leĝo, estos juĝata per leĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'ĉar ne la aŭskultantoj de leĝo estos justaj antaŭ Dio, sed la plenumantoj de leĝo estos pravigitaj');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, '(ĉar kiam la nacianoj, kiuj ne havas la leĝon, faras nature la aferojn de la leĝo, ĉi tiuj, ne havante leĝon, estas leĝo por si mem;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'kiuj elmontras la faradon de la leĝo skribita en iliaj koroj, kiam ilia konscienco kunatestas, kaj iliaj rezonadoj inter si akuzas aŭ defendas ilin.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'en la tago, kiam Dio juĝos la sekretojn de homoj, laŭ mia evangelio, per Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Sed se vi estas nomata Judo, kaj apogas vin sur la leĝon, kaj fieras pri Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'kaj konas Lian volon, kaj aprobas la aprobindaĵojn, kaj estas instruita el la leĝo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'kaj estas konvinkita, ke vi mem estas gvidanto por la blinduloj, lumo por tiuj, kiuj estas en mallumo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'edukanto por la senprudentuloj, instruanto por infanoj, havante en la leĝo la formon de la scio kaj la vero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'vi, kiu instruas alian, ĉu vi ne instruas vin mem? vi, kiu predikas: Ne ŝtelu; ĉu vi ŝtelas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'vi, kiu diras: Ne adultu; ĉu vi adultas? vi, kiu abomenas idolojn, ĉu vi prirabas templojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'vi, kiu fieras pri la leĝo, ĉu vi malhonoras Dion per via transpaŝo de la leĝo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Ĉar pro vi, la nomo de Dio estas blasfemata inter la nacianoj, kiel estas skribite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Ĉar cirkumcido vere utilas, se vi estas faranto de la leĝo; sed se vi estas pekanto kontraŭ la leĝo, via cirkumcido fariĝas necirkumcido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Se do necirkumcidulo plenumas la ordonojn de la leĝo, ĉu lia necirkumcido ne kalkuliĝos kiel cirkumcido?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'kaj ĉu la laŭnatura necirkumcidulo, se li plenumas la leĝon, ne juĝos vin, kiu kun la skribo kaj cirkumcido transpaŝas la leĝon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Ĉar Judo estas ne tiu, kiu estas ekstere tia, kaj cirkumcido estas ne tio, kio estas tia ekstere en la karno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'sed Judo estas tiu, kiu estas interne tia, kaj cirkumcido estas en la koro, laŭ la spirito, ne laŭ la litero, kies laŭdo estas ne de homoj, sed de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Kia do estas la supereco de la Judoj? aŭ kia estas la utilo de cirkumcido?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Multa en ĉiu rilato: unue, ke al ili estis konfiditaj la orakoloj de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Ĉu do estas grave, se kelkaj ne fidis? ĉu ilia senfideco vantigos la fidelecon de Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Nepre ne! Dio montriĝu vera, sed ĉiu homo mensoganto, kiel estas skribite: Ke Vi estu justa en Via vorto Kaj pura en Via juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Sed se nia maljusteco rekomendas la justecon de Dio, kion ni diros? Ĉu maljusta estas Dio, kiu alportas koleron? (Mi parolas kiel homo.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Nepre ne! ĉar kiel Dio juĝus la mondon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Ĉar se la vero de Dio per mia mensogo abundis al Lia gloro, kial mi estas ankoraŭ juĝata, kiel pekinto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'kaj kial ne (kiel ni estas kalumniataj, kaj kelkaj asertas, ke ni diras): Ni faru malbonon, por ke venu bono? ilia kondamno estas justa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Kio do? ĉu ni nin senkulpigas? Tute ne: ĉar ni jam akuzis egale Judojn kaj Grekojn, ke ĉiuj estas sub peko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'kiel estas skribite: Ne ekzistas justulo, ne eĉ unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'Ne ekzistas prudentulo, Ne ekzistas iu, kiu serĉas Dion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Ĉiuj devojiĝis, ĉiuj senutiliĝis; Ekzistas neniu, kiu faras bonon, ne eĉ unu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Malfermita tombo estas ilia gorĝo; Per sia lango ili hipokritis; Veneno de vipuro estas sub iliaj lipoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'Ilia buŝo estas plena de malbenado kaj malico;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Iliaj piedoj rapidas, por verŝi sangon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'Ruinigo kaj pereigo estas sur iliaj vojoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'Kaj vojon de paco ili ne konas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'Antaŭ iliaj okuloj ne ekzistas timo antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Sed ni scias, ke ĉion ajn, kion la leĝo diras, ĝi parolas al tiuj, kiuj estas sub la leĝo; ke ĉiu buŝo fermiĝu, kaj ke la tuta mondo submetiĝu sub la juĝon de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'ĉar per la faroj de la leĝo neniu karno praviĝos antaŭ Li; ĉar per la leĝo venas konscio pri peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Sed nun, ekster la leĝo, justeco de Dio montriĝis, atestata per la leĝo kaj la profetoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'nome, la justeco de Dio, per fido al Jesuo Kristo, por ĉiuj kredantoj, ĉar ne ekzistas diferencigo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'ĉar ĉiuj pekis kaj maltrafis la gloron de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'pravigite donace de Lia graco, per la elaĉeto, kiu estas en Kristo Jesuo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'kiun Dio antaŭdifinis kiel repacigilon per fido en lia sango, por la elmontrado de Sia justeco per la pardono de la pekoj, antaŭe faritaj laŭ la toleremeco de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'por la elmontrado de Lia justeco en la nuna tempo, kaj ke Li estas mem justa, kaj estas la praviganto de tiu, kiu havas fidon en Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Kie do estas la fanfaronado? Ĝi estas esceptita. Per kia leĝo? de faroj? Ne; sed per la leĝo de fido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Ni do konkludas, ke homo praviĝas per fido, ekster la faroj de la leĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Ĉu Dio estas nur Dio de la Judoj? ĉu ne ankaŭ de la nacianoj? Jes, ankaŭ de la nacianoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'ĉar Dio estas unu, kaj Li pravigos la cirkumcidularon pro fido kaj la necirkumcidularon per fido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Ĉu ni do per fido vantigas la leĝon? Nepre ne! sed ni firmigas la leĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Kion do, ni diros, trovis Abraham, nia praavo laŭ la karno?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Ĉar se Abraham praviĝis per faroj, li havas ion, pri kio fieri, sed ne antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Ĉar kion diras la Skribo? Kaj Abraham kredis al Dio, kaj tio estis kalkulita al li kiel virto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Al tiu, kiu laboras, la salajro estas kalkulata ne kiel favoro, sed kiel ŝuldo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Sed al tiu, kiu ne laboras, sed kredas al Tiu, kiu pravigas la malpiulon, lia fido estas kalkulata kiel virto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Kiel David ankaŭ pridiras la feliĉon de la homo, al kiu Dio kalkulas virton ekster faroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'dirante: Feliĉaj estas tiuj, kies krimoj estas pardonitaj, Kies pekoj estas kovritaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Feliĉa estas la homo, al kiu la Eternulo ne kalkulas lian kulpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Ĉu do ĉi tiu feliĉo apartenas al la cirkumcidularo, aŭ al la necirkumcidularo ankaŭ? Ĉar ni diras, ke al Abraham la fido estis kalkulita kiel virto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Kiel do ĝi estis kalkulita? kiam li estis en cirkumcido, aŭ en necirkumcido? Ne en cirkumcido, sed en necirkumcido;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'kaj li ricevis la signon de cirkumcido, kiel sigelon de la virto de la fido, kiu ekzistis en lia necirkumcido; por ke li estu la patro de ĉiuj, kiuj ankoraŭ en necirkumcido kredas, por ke virto estu kalkulata al ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'kaj la patro de cirkumcido al tiuj, kiuj ne nur estas anoj de la cirkumcido, sed kiuj ankaŭ sekvas la paŝojn de tiu fido, kiun nia patro Abraham havis dum sia necirkumcido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Ĉar ne per la leĝo fariĝis la promeso al Abraham aŭ al lia idaro, ke li estos heredanto de la mondo, sed per la virto el fido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Ĉar se tiuj, kiuj estas laŭ la leĝo, estas heredantoj, la fido nuliĝis, kaj la promeso vantiĝis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'ĉar la leĝo elfaras koleron; sed kie ne ekzistas leĝo, tie ankaŭ ne ekzistas transpaŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Ĝi do estas el fido por tio, ke ĝi estu laŭ graco; por ke la promeso estu firma al la tuta idaro, ne nur al tiu, kiu estas el la leĝo, sed ankaŭ al tiu, kiu estas el la fido de Abraham, kiu estas la patro de ni ĉiuj');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, '(kiel estas skribite: Mi faris vin patro de multe da popoloj) antaŭ Tiu, al kiu li kredis, nome Dio, kiu vivigas la mortintojn, kaj vokas la neekzistantaĵojn, kvazaŭ ili ekzistus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Li ekster espero kredis en espero, por ke li fariĝu patro de multe da popoloj, laŭ la diritaĵo: Tiel estos via idaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'Kaj ne senfortigite en fido, li pripensis sian propran korpon jam pereintan (estante preskaŭ centjara), kaj la senvivecon de la utero de Sara;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'tamen pri la promeso de Dio li ne ŝanceliĝis en nekredemo, sed fortiĝis per fido, donante la gloron al Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'kaj plene certigite, ke tion, kion Li promesis, Li povas ankaŭ fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Tial ĝi estis kalkulita al li kiel virto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Kaj ne por li sola estis skribite, ke ĝi estis kalkulita al li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'sed ankaŭ por ni, al kiuj ĝi estos kalkulata, kaj kiuj kredas al Tiu, kiu levis el la mortintoj Jesuon, nian Sinjoron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'kiu estis transdonita pro niaj pekoj kaj estis relevita por nia pravigo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Tial ni, pravigite per fido, havu pacon kun Dio per nia Sinjoro Jesuo Kristo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'per kiu ankaŭ ni ricevis enkondukon per fido en ĉi tiun gracon, en kiu ni staras; kaj ni ĝoju pro espero de la gloro de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Kaj krome ni ĝoju ankaŭ pro la afliktoj, sciante, ke aflikto faras paciencon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'kaj pacienco provitecon, kaj proviteco esperon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'kaj la espero ne hontigas, ĉar la amo de Dio estas verŝita en niajn korojn per la Sankta Spirito, donita al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Ĉar kiam ni ankoraŭ estis senfortaj, tiam Kristo ĝustatempe mortis pro malpiuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Ĉar apenaŭ pro justulo iu mortus; ĉar pro bonulo eble iu kuraĝus morti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Sed Dio rekomendas al ni Sian amon en tio, ke dum ni ankoraŭ estis pekuloj, Kristo mortis por ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Des plimulte do ni, jam pravigite per lia sango, estos per li savitaj el la kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Ĉar se ni, estante malamikoj, estas repacigitaj kun Dio per la morto de Lia Filo, des plimulte, repacigite, ni estos savitaj per lia vivo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'kaj krom tio ni fieras ankaŭ en Dio pro nia Sinjoro Jesuo Kristo, per kiu ni jam ricevis la repacigon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'Pro tio, kiel per unu homo peko eniris en la mondon, kaj morto per peko, kaj tiel morto atingis ĉiujn homojn pro tio, ke ĉiuj pekis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'ĉar ĝis la leĝo peko estis en la mondo, sed peko ne estas alkalkulata, kiam ne ekzistas leĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Sed morto reĝis de post Adam ĝis Moseo, eĉ super tiuj, kiuj ne pekis simile al la transpaŝo de Adam, kiu estis la tipo de la venonto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Sed ne kia la eraro, tia estas la donaco. Ĉar se per la eraro de unu mortis la multaj, des plimulte abundis al la multaj la graco de Dio kaj la donaco per la graco de la unu homo Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'Kaj la donaco ne estis laŭ la unu pekinta; ĉar la juĝo venis el unu ĝis kondamno, sed la donaco venis el multaj eraroj ĝis pravigo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Ĉar se, per la eraro de la unu, morto reĝis per unu, des plimulte reĝos en vivo per la unu Jesuo Kristo tiuj, kiuj ricevis abundon de la graco kaj de la donaco de justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Tial, kiel per unu eraro venis juĝo al ĉiuj homoj ĝis kondamno, tiel same per unu justaĵo venis la donaco al ĉiuj homoj ĝis la pravigo de vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Ĉar kiel per la malobeo de unu la multaj fariĝis pekuloj, tiel per la obeo de unu la multaj fariĝos justaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Kaj la leĝo eniris, por ke la eraro plimultiĝu; sed kie peko plimultiĝis, graco multe pli superabundis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'por ke tiel same, kiel la peko reĝis en morto, la graco reĝu per justeco ĝis eterna vivo per Jesuo Kristo, nia Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Kion do ni diru? Ĉu ni restu en peko, por ke graco abundu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Nepre ne! Ĉu ni, kiuj mortis al peko, ankoraŭ vivus en ĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Ĉu vi ne scias, ke ni ĉiuj, kiuj baptiĝis al Jesuo Kristo, baptiĝis al lia morto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Ni do estas entombigitaj kun li per bapto al morto, por ke, kiel Kristo estas levita el la mortintoj per la gloro de la Patro, tiel same ni ankaŭ iradu en noveco de vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Ĉar se ni jam kuniĝis al la simileco de lia morto, ni tiel same kuniĝos al la simileco de lia releviĝo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'sciante, ke nia malnova homo estas kun li krucumita, por ke la korpo de peko estu neniigita, por ke ni jam ne estu sklavoj al peko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'ĉar tiu, kiu mortis, estas pravigita pri peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Sed se ni mortis kun Kristo, ni kredas, ke ni ankaŭ vivos kun li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'sciante, ke Kristo, levite el la mortintoj, ne plu mortas; la morto ne plu lin regas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Ĉar mortante, li mortis al peko unufoje por ĉiam; sed vivante, li vivas al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Tial ankaŭ vi vin kalkulu mortintoj al peko, sed vivantoj al Dio en Kristo Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Tial peko ne reĝu en via morta korpo tiel, ke vi obeu al ĝiaj deziroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'ankaŭ ne prezentu viajn membrojn iloj de maljusteco al peko, sed prezentu vin al Dio vivantoj el la mortintoj, kaj viajn membrojn iloj de justeco por Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Ĉar peko ne regos vin, ĉar vi estas ne sub la leĝo, sed sub graco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Kio do? ĉu ni peku, pro tio, ke ni estas ne sub leĝo, sed sub graco? Nepre ne!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Ĉu vi ne scias, ke kiam vi vin prezentas, kiel sklavoj al iu por obeado, vi estas sklavoj de tiu, al kiu vi obeas, ĉu de peko por morto, aŭ de obeemeco por justeco?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Sed danko estu al Dio, ke kvankam vi estis la sklavoj de peko, vi tamen fariĝis kore obeemaj al tiu tipo de instruado, al kiu vi estas kondukitaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'kaj liberigite el peko, vi sklaviĝis al justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Mi parolas home pro la malforteco de via karno; ĉar kiel vi prezentis viajn membrojn sklavoj al malpureco kaj al maljusteco ĝis maljusteco, tiel nun prezentu viajn membrojn sklavoj al justeco ĝis sanktigo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Ĉar kiam vi estis sklavoj de peko, vi estis liberaj de justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Kian frukton do vi havis tiam el tio, pri kio vi nun hontas? ĉar la fino de tio estas morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Sed nun, liberigite el peko, kaj sklaviĝinte al Dio, vi havas vian frukton ĝis sanktiĝo, kaj por fino eternan vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Ĉar la salajro de peko estas morto; sed la donaco de Dio estas eterna vivo en Kristo Jesuo, nia Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Aŭ ĉu vi ne scias, fratoj (ĉar mi parolas al konantoj de la leĝo), ke la leĝo regas la homon tiel longe, kiel li vivas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Ĉar la edzinigita virino estas leĝe alligita al sia edzo dum lia vivo; sed se la edzo mortas, ŝi liberiĝas el la leĝo de la edzo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Se do, dum la edzo vivas, ŝi kuniĝas kun alia viro, ŝi estos nomata adultulino; sed se la edzo mortis, ŝi estas libera de la leĝo, kaj ne estas adultulino, kvankam kuniĝinte kun alia viro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Tiel, miaj fratoj, vi same mortis al la leĝo per la korpo de Kristo, por kuniĝi kun alia, nome kun tiu, kiu leviĝis el la mortintoj, por ke ni donu frukton al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Ĉar dum ni estis en karno, la laŭpekaj pasioj, kiuj estis per la leĝo, energiis en niaj membroj, por doni frukton al morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Sed ni jam liberiĝis el la leĝo, mortinte rilate tion, en kio ni estis tenataj, por ke ni servu en noveco de spirito, kaj ne en malnoveco de litero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Kion do ni diru? Ĉu la leĝo estas peko? Nepre ne! Tamen mi ne konus pekon, krom per la leĝo; ĉar mi ne konus deziron, se la leĝo ne dirus: Ne deziru;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'sed la peko, trovante pretekston, estigis en mi per la ordono ĉian deziremon, ĉar ekster leĝo la peko estas senviva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Kaj iam mi vivadis ekster la leĝo; sed kiam la ordono venis, la peko viviĝis, kaj mi mortis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'kaj tiun ordonon, kiu estas por vivo, mi trovis por morto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'ĉar la peko, trovinte pretekston, per la ordono min trompis, kaj per ĝi min mortigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'Tiel la leĝo estas sankta, kaj la ordono estas sankta kaj justa kaj bona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Ĉu do tio, kio estas bona, fariĝis morto por mi? Nepre ne! Sed la peko, por ke ĝi montriĝu peko, estigante morton en mi per la bono-por ke per la ordono la peko fariĝu treege peka.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Ĉar ni scias, ke la leĝo estas spirita; sed mi estas karna, vendite sub pekon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Ĉar mi ne havas certecon pri tio, kion mi faradas; ĉar mi ne agas laŭ tio, kion mi volas; sed kion mi malamas, tion mi faras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Sed se mi faras tion, kion mi ne volas fari, mi konsentas al la leĝo, ke ĝi estas bona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'La faranto do estas jam ne mi, sed la peko, loĝanta en mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Ĉar mi scias, ke en mi (tio estas, en mia karno) bono ne loĝas; ĉar ĉe mi estas la volo, sed ne la elfaro de la bono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Ĉar la bonon, kiun mi volas fari, mi ne faras; sed la malbonon, kiun mi ne volas fari, mi faradas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Sed se mi faras tion, kion mi ne volas fari, faras ĝin jam ne mi, sed la peko, loĝanta en mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Mi do trovas leĝon, ke kiam mi volas fari bonon, la malbono estas ĉe mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Ĉar mi ĝojas en la leĝo de Dio laŭ la interna homo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'sed mi vidas alian leĝon en miaj membroj, militantan kontraŭ la leĝo de mia menso, kaj forkaptantan min sub la leĝon de la peko, kiu estas en miaj membroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Ho ve, mi malfeliĉulo! kiu min liberigos el la korpo de ĉi tiu morto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Danko estu al Dio, per Jesuo Kristo, nia Sinjoro. Per la menso do mi mem servas al la leĝo de Dio, sed per la karno al la leĝo de peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Ekzistas do jam nenia kondamno kontraŭ tiuj, kiuj estas en Kristo Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Ĉar la leĝo de la Spirito de vivo en Kristo Jesuo liberigis min de la leĝo de peko kaj morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Ĉar kiam la leĝo troviĝis nekapabla pro tio, ke ĝi estis malforta pro la karno, Dio, sendante Sian propran Filon en simileco de peka karno kaj pro peko, kondamnis la pekadon en la karno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'por ke la postulo de la leĝo plenumiĝu en ni, kiuj iradas ne laŭ la karno, sed laŭ la spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Ĉar kiuj estas laŭ la karno, tiuj sin interesas pri la aferoj de la karno; sed kiuj estas laŭ la spirito, pri la aferoj de la spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Ĉar la intereso de la karno estas morto, sed la intereso de la spirito estas vivo kaj paco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'ĉar la intereso de la karno estas malamikeco kontraŭ Dio, ĉar ĝi ne obeas al la leĝo de Dio, kaj ĝi ja ne povas obei;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'kaj tiuj, kiuj estas en la karno, ne povas plaĉi al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Sed vi estas ne en la karno, sed en la spirito, se vere la Spirito de Dio loĝas en vi. Sed se iu ne havas la Spiriton de Kristo, tiu ne estas lia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'Kaj se Kristo estas en vi, la korpo malvivas pro peko, sed la spirito estas vivo pro justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'Kaj se la Spirito de Tiu, kiu levis Jesuon el la mortintoj, loĝas en vi, tiam la Levinto de Kristo Jesuo el la mortintoj vivigos eĉ viajn mortajn korpojn per Sia Spirito, loĝanta en vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'Tial do, fratoj, ni estas ŝuldantoj, ne al la karno, por vivi laŭ la karno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'ĉar se vi vivas laŭ la karno, vi mortos; sed se per la spirito vi malvivigas la farojn de la korpo, vi vivos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Ĉar ĉiuj, kiuj estas kondukataj de la Spirito de Dio, estas filoj de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Ĉar vi ne ricevis la spiriton de sklaveco denove al timo; sed vi ricevis la spiriton de adopto, per kiu ni krias: Aba, Patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'La Spirito mem kunatestas kun nia spirito, ke ni estas idoj de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'kaj se idoj, tial heredantoj, heredantoj de Dio, kunheredantoj kun Kristo, se vere ni suferas kun li, por ke ni estu glorataj kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Ĉar mi kalkulas, ke la suferoj de la nuna tempo ne indas komparon kun la gloro, kiu estas malkaŝota al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Ĉar la fervora sopiro de la kreitaro atendas la malkaŝon de la filoj de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'Ĉar la kreitaro subiĝis sub la vanecon, ne volonte, sed, pro la subiganto, kun espero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'ke la kreitaro mem ankaŭ liberiĝos el la sklaveco de pereo en la liberecon de la gloro de la idoj de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Ĉar ni scias, ke la tuta kreitaro kune ĝemas kaj naskodoloras ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'Kaj krom tio, ni mem, kiuj havas la unuaaĵon de la Spirito, ĝemas en ni, atendante nian adopton, nome la elaĉeton de nia korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Ĉar per espero ni estas savitaj; sed la espero, kiu estas vidata, ne estas espero; ĉar kiu esperas al tio, kion li vidas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Sed, se ni esperas al tio, kion ni ne vidas, tiam ni ĝin atendas pacience.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'Kaj tiel same la Spirito ankaŭ helpas nian malfortecon; ĉar ni ne scias, kiel preĝi dece, sed la Spirito mem propetadas por ni per ĝemoj neeldireblaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'kaj Tiu, kiu esploras la korojn, scias, kio estas la penso de la Spirito, ĉar li propetadas por la sanktuloj laŭ la volo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'Kaj ni scias, ke por tiuj, kiuj amas Dion, por tiuj, kiuj estas vokitaj laŭ Lia intenco, ĉio kunlaboras al bono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Ĉar kiujn Li antaŭkonis, tiujn Li antaŭdifinis kiel konformajn al la bildo de Lia Filo, por ke ĉi tiu estu la unuenaskita inter multaj fratoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'kaj kiujn Li antaŭdifinis, tiujn Li ankaŭ vokis; kaj kiujn Li vokis, tiujn Li ankaŭ justigis; kaj kiujn Li justigis, tiujn Li ankaŭ gloris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Kion do ni diru pri ĉi tio? Se Dio estas por ni, kiu estas kontraŭ ni?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Ĉu Tiu, kiu ne indulgis Sian propran Filon, sed fordonis lin por ni ĉiuj, ne donos al ni libere ĉion kun li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Kiu akuzos la elektitojn de Dio? Dio estas la justiganto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'kiu estas la kondamnanto? Kristo estas tiu, kiu mortis, sed leviĝis el la mortintoj, kiu estas dekstre de Dio, kaj ankaŭ propetadas por ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Kiu apartigos nin de la amo de Kristo? ĉu aflikto, aŭ turmento, aŭ persekutado, aŭ malsato, aŭ nudeco, aŭ danĝero, aŭ glavo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'Kiel estas skribite: Pro Vi ni estas mortigataj ĉiutage; Oni rigardas nin kiel ŝafojn por buĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Sed en ĉio tio ni supervenkas per tiu, kiu nin amis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Ĉar mi konvinkiĝis, ke nek morto, nek vivo, nek anĝeloj, nek aŭtoritatoj, nek estantaĵoj, nek estontaĵoj, nek potencoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'nek alteco, nek profundeco, nek iu alia kreitaĵo povos apartigi nin de la amo de Dio, kiu estas en Kristo Jesuo, nia Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Mi diras la veron en Kristo, mi ne mensogas, kaj mia konscienco atestas kun mi per la Sankta Spirito,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'ke mi havas grandan malĝojon kaj senĉesan doloron en la koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'Ĉar mi volus, ke mi estu anatemita for de Kristo por miaj fratoj, miaj parencoj laŭ la karno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'kiuj estas Izraelidoj, kies estas la adopto kaj la gloro kaj la interligoj kaj la leĝdono kaj la Diservo kaj la promesoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'kies estas la patroj, kaj el kiuj laŭ la karno estas Kristo, kiu estas super ĉiuj, Dio benata eterne. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Sed la afero ne estas, kvazaŭ la vorto de Dio estus neniiĝinta. Ĉar ne ĉiuj estas Izrael, kiuj estas el Izrael;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'nek, ĉar ili estas idoj de Abraham, ĉiuj estas filoj, sed: Per Isaak oni nomos vian idaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'Tio estas, ne la filoj de la karno estas la filoj de Dio, sed la filoj de la promeso estas rigardataj kiel idaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Ĉar jen estas la vorto de promeso: En la sama jartempo Mi venos, kaj estos filo ĉe Sara.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'Kaj plue, kiam Rebeka ankaŭ gravediĝis per unu, nia patro Isaak');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, '(ĉar la infanoj ankoraŭ ne naskiĝis, nek faris ion bonan aŭ malbonan, por ke la intenco de Dio restu laŭ elekto, ne pro faroj, sed pro la alvokanto),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'estis dirite al ŝi: La pli granda servos la malpli grandan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'Kiel estas skribite: Mi ekamis Jakobon, sed Esavon Mi malamis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Kion do ni diru? Ĉu estas maljusteco ĉe Dio? Nepre ne!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Ĉar Li diris al Moseo: Mi favorkoros tiun, kiun Mi favorkoros, kaj Mi kompatos tiun, kiun Mi kompatos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'Tial do tio apartenas ne al tiu, kiu volas, nek al tiu, kiu kuras, sed al Dio, kiu kompatas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Ĉar la Skribo diras al Faraono: Nur por tio Mi vin konservis, ke Mi montru sur vi Mian forton, kaj por ke oni rakontu pri Mia nomo sur la tuta tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'Tial Li favorkoras ĉiun, kiun Li volas; kaj ĉiun, kiun Li volas, Li obstinigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Vi do diras al mi: Kial Li ankoraŭ riproĉas? Ĉar kiu rezistas al Lia volo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'Sed antaŭ tio, ho viro, kiu vi estas, ke vi respondas kontraŭ Dio? Ĉu faritaĵo diros al sia farinto: Kial vi faris min tiel?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Aŭ ĉu la potfaristo ne havas rajton super la argilo, el la sama maso fari jen vazon por honoro, kaj jen vazon por malhonoro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Kiel do, se Dio, volante elmontri Sian koleron kaj konatigi Sian potencon, toleris kun plena pacienco vazojn de kolero, taŭgajn por pereo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'kaj por ke Li konatigu la riĉon de Sia gloro sur vazojn de favoro, kiujn Li antaŭe pretigis por gloro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'nome nin, kiujn Li ankaŭ vokis, ne nur el la Judoj, sed ankaŭ el la nacianoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'Kiel Li diras ankaŭ en Hoŝea: La popolon ne Mian Mi nomos Mia popolo, Kaj la neamatinon amatino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'Kaj sur la sama loko, kie estis al ili dirite: Vi ne estas Mia popolo, Tie oni nomos ilin infanoj de la vivanta Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Kaj Jesaja krias pri Izrael: Se la nombro de la filoj de Izrael eĉ estos kiel la apudmara sablo, la restintoj saviĝos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'ĉar la Sinjoro efektivigos Sian vorton en la mondo, akcelante kaj tranĉe mallongigante ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'Kiel Jesaja diris antaŭe: Se la Eternulo Cebaot ne lasus al ni restaĵon, Ni fariĝus kiel Sodom, ni similiĝus al Gomora.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Kion do ni diru? Ke la nacianoj, kiuj ne sekvis justecon, atingis justecon, la justecon, kiu estas el fido;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'sed ke Izrael, sekvante la leĝon de justeco, ne atingis tiun leĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Kial? Ĉar ili sekvis ĝin ne per fido, sed kvazaŭ per faroj. Ili falpuŝiĝis ĉe la ŝtono de falpuŝiĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'kiel estas skribite: Jen Mi kuŝigas en Cion ŝtonon de falpuŝiĝo kaj rokon de alfrapiĝo; Kaj tiu, kiu fidos al li, ne estos hontigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Fratoj, la deziro de mia koro kaj mia preĝo al Dio pri ili estas por ilia savado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Ĉar mi atestas pri ili, ke ili havas fervoron al Dio, sed ne laŭ scio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Ĉar nesciante la justecon de Dio, kaj penante starigi sian propran justecon, ili ne subiĝis al la justeco de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Ĉar Kristo estas la fino de la leĝo por justeco por ĉiu, kiu kredas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Ĉar Moseo skribis, ke tiu, kiu plenumas la justecon de la leĝo, vivos per ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Sed la justeco, kiu estas el fido, diras jene: Ne diru en via koro: Kiu suprenirus en la ĉielon? (tio estas, por malsuprenigi Kriston),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'nek: Kiu malsuprenirus en la abismon? (tio estas, por suprenkonduki Kriston el la mortintoj).');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Sed kion ĝi diras? La afero estas proksime de vi, en via buŝo kaj en via koro; tio estas, la vorto de fido, kiun ni predikas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'ĉar se vi per via buŝo konfesas Jesuon Sinjoro, kaj kredas en via koro, ke Dio lin levis el la mortintoj, vi saviĝos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'ĉar per la koro la homo kredas ĝis justeco, kaj per la buŝo konfesas ĝis savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Ĉar la Skribo diras: Ĉiu, kiu fidas al li, ne estos hontigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Ĉar estas nenia diferencigo inter Judo kaj Greko, ĉar unu sama estas Sinjoro de ĉiuj, kaj estas riĉa por ĉiuj, kiuj lin vokas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'ĉar: Ĉiu, kiu vokos la nomon de la Eternulo, saviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Kiel do ili vokos Tiun, al kiu ili ne kredis? kaj kiel ili kredos al Tiu, pri kiu ili ne aŭdis? kaj kiel ili aŭdos sen predikanto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'kaj kiel oni predikos, se ili ne estos senditaj? kiel estas skribite: Kiel ĉarmaj estas la piedoj de la anoncantoj de la evangelio de bono!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Sed ne ĉiuj aŭskultis la evangelion. Ĉar Jesuo diris: Ho Eternulo! kiu kredus al tio, kion ni aŭdis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'La fido venas do per aŭdado, kaj aŭdado per la vorto de Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Sed mi diras: Ĉu ili ne aŭdis? Certe: Tra la tuta mondo iris ilia sono, Kaj ĝis la finoj de la tero iris iliaj vortoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Sed mi diras: Ĉu Izrael ne sciis? Unue Moseo diris: Mi incitos vin per ne-popolo, Per popolo malnobla Mi vin kolerigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'Kaj Jesaja estis tre kuraĝa, kaj diris: Mi estas trovebla por tiuj, kiuj Min ne serĉis; Mi montris Min al tiuj, kiuj pri Mi ne demandis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Sed pri Izrael li diris: Ĉiutage Mi etendis Miajn manojn al popolo malobeema kaj obstina.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Mi do diras: Ĉu Dio forpuŝis Sian popolon? Nepre ne! Ĉar ankaŭ mi estas Izraelido, el la idoj de Abraham, el la tribo de Benjamen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Dio ne forpuŝis Sian popolon, kiun Li antaŭkonis. Aŭ ĉu vi ne scias, kion la Skribo diras pri Elija? kiel li pledis ĉe Dio kontraŭ Izrael:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, 'Ho Eternulo, oni mortigis Viajn profetojn, detruis Viajn altarojn; kaj mi sola restis, kaj oni serĉas mian animon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Sed kion diras al li la orakolo de Dio? Mi restigis por Mi sep mil virojn, kies genuoj ne fleksiĝis antaŭ Baal.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Tiel same do estas ankaŭ nuntempe restaĵo laŭ la elektado de graco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Sed se per graco, ne plu el faroj; alie graco jam ne estus graco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Kion do? Kion Izrael serĉadas, tion li ne atingis, sed la elektitaro atingis ĝin, kaj la restaĵo estis obstinigita;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'kiel estas skribite: Dio donis al ili spiriton de profunda dormo, okulojn, por ke ili ne vidu, kaj orelojn, por ke ili ne aŭdu, ĝis la nuna tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'Kaj David diris: Ilia tablo fariĝu por ili reto kaj kaptilo Kaj falpuŝilo kaj repago;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'Mallumiĝu iliaj okuloj, ke ili ne vidu; Kaj iliajn lumbojn malfortigu por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Mi do diras: Ĉu ili falpuŝiĝis, por ke ili falu? Nepre ne! sed per ilia eraro venis savo al la nacianoj, por ĵaluzigi ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Se do ilia eraro riĉigis la mondon, kaj ilia perdo estas la gajno de la nacianoj, kiom pli ilia pleneco?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Sed mi parolas al vi, nacianoj. Laŭ tio, kiom mi estas apostolo al nacianoj, mi gloras mian servadon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'se nur mi iel povos ĵaluzigi tiujn, kiuj estas mia karno, kaj savi kelkajn el ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Ĉar se la forĵetado de ili estas la repacigo de la mondo, kio estos la akcepto de ili, se ne vivo el la mortintoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Kaj se la unuaaĵo estas sankta, la maso ankaŭ estas sankta; kaj se la radiko estas sankta, la branĉoj ankaŭ estas sanktaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Sed se kelkaj el la branĉoj derompiĝis, kaj vi, estante sovaĝa olivarbo, engreftiĝis inter ili kaj fariĝis partoprenanto en la radiko kaj graso de la olivarbo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'ne fieru super la branĉoj; sed se vi fieras, ne vi portas la radikon, sed la radiko portas vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Vi do diros: Branĉoj estis derompitaj, por ke mi estu engreftita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Bone; pro nekredemeco ili estis derompitaj, kaj vi staras per via fido. Ne tenu vin alte, sed timu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'ĉar se Dio ne indulgis la naturajn branĉojn, Li ankaŭ vin ne indulgos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Vidu do la bonecon kaj severecon de Dio: al la falintoj severecon, sed al vi bonecon, se vi restados en Lia boneco; alie vi ankaŭ detranĉiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Kaj ili ankaŭ, se ili ne restados en sia nekredemeco, engreftiĝos; ĉar Dio povas reengrefti ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Ĉar se vi eltranĉiĝis el tio, kio estas nature sovaĝa olivarbo, kaj kontraŭnature engreftiĝis en bonan olivarbon, kiom pli ĉi tiuj, kiuj estas la naturaj branĉoj, engreftiĝos en sian propran olivarbon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Ĉar mi ne volas, fratoj, ke vi ne sciu ĉi tiun misteron, por ke vi ne opiniu vin saĝaj, ke laŭparta obstiniĝo okazis al Izrael, ĝis la pleneco de la nacianoj envenos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'kaj tiamaniere la tuta Izrael saviĝos, kiel estas skribite: El Cion venos la Liberiganto; Li deturnos de Jakob malpiecon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'Kaj ĉi tio estos Mia interligo kun ili, Kiam Mi forigos iliajn pekojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Rilate al la evangelio, ili estas malamikoj pro vi; sed rilate al la elekto, ili estas amataj pro la patroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Ĉar la donacoj kaj la vokado de Dio estas nerevokeblaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Ĉar kiel vi iam estis malobeemaj al Dio, sed jam ricevis kompaton per ilia malobeo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'tiel same ankaŭ ĉi tiuj jam malobeis, por ke, per la kompato montrita al vi, ili ankaŭ nun ricevu kompaton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Ĉar Dio kunŝlosis ĉiujn en malobeo, por ke Li kompatu ĉiujn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'Ho, profundo de riĉeco kaj saĝeco kaj scio de Dio! kiel neesploreblaj estas Liaj juĝoj, kaj nesekveblaj Liaj vojoj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Ĉar kiu sciis la spiriton de la Eternulo? aŭ kiu estis Lia konsilanto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'aŭ kiu antaŭe al Li donis ion, poste redonotan al li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Ĉar el Li kaj per Li kaj al Li estas ĉio. Al Li estu la gloro por ĉiam. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Mi do vin petas, fratoj, pro la kompatoj de Dio, ke vi prezentu viajn korpojn kiel vivantan oferon, sanktan, plaĉantan al Dio, kio estas via racia servo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'Kaj ne konformiĝu al ĉi tiu mondo; sed aliformiĝu per renovigado de via menso, por ke vi provu, kio estas la bona kaj aprobinda kaj perfekta volo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Ĉar mi diras al ĉiu el vi, per la graco al mi donita, ke li ne tro estimu sin, sed estimu sin kun modereco, laŭ mezuro de la fido, kiun Dio disdonis al ĉiu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Ĉar kiel ni havas multajn membrojn en unu korpo, kaj ne ĉiuj membroj havas la saman funkcion,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'tiel same ni multaj estas unu korpo en Kristo, kaj ĉiuj aparte membroj unu de alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Sed havante donacojn diversajn laŭ la graco donita al ni, ĉu profetadon, ni profetu laŭ la mezuro de nia fido;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'aŭ servadon, ni laboru en nia servado; aŭ instruanto, en sia instruado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'aŭ admonanto, en sia admonado; la disdonanto agu malavare, la administranto kun diligenteco, la kompatanto kun ĝojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Via amo estu sen hipokriteco. Abomenu tion, kio estas malbona; algluiĝu al la bona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'En fratamo estu kore unuigitaj unu al alia, honore preferantaj unu la alian;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'en diligenteco ne malviglaj, en spirito fervoraj, servantaj la Sinjoron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'en espero ĝojaj, en aflikto paciencaj, en preĝado persistaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'kotizantaj por la bezonoj de la sanktuloj, sekvantaj gastamecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Benu tiujn, kiuj vin persekutas; benu, kaj ne malbenu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Ĝoju kun ĝojantoj, ploru kun plorantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Estu simpatiaj unu al alia. Ne pripensadu altajn aferojn, sed klinadu vin al humilaj aferoj. Ne opiniu vin saĝaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Redonu al neniu malbonon pro malbono. Celu aprobindaĵojn antaŭ ĉiuj homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'Se estos eble, restu pacaj viaparte kun ĉiuj homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Ne venĝu vin, amataj, sed cedu lokon al kolero; ĉar estas skribite: Ĉe Mi estas venĝo, Mi repagos, diras la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'Sed se via malamiko malsatas, donu al li manĝi; se li soifas, donu al li trinki; ĉar tion farante, fajrajn karbojn vi kolektos sur lia kapo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Ne venkiĝu de malbono, sed venku malbonon per bono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Ĉiu animo submetiĝu al la superaj aŭtoritatoj, ĉar ne ekzistas aŭtoritato, krom de Dio; kaj tiuj, kiuj ekzistas, estas starigitaj de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'Tiu do, kiu kontraŭstaras al aŭtoritato, rezistas al la ordono de Dio; kaj tiuj, kiuj rezistas, ricevos juĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Ĉar regantoj estas teruraĵo ne al la bona agado, sed al la malbona. Ĉu vi volas ne timi aŭtoritatulon? faru bonon, kaj vi havos de li laŭdon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'ĉar li estas servanto de Dio al vi por bono. Sed timu, se vi faras malbonon; ĉar ne vane li portas la glavon, ĉar li estas servanto de Dio, venĝanto por kolero kontraŭ tiu, kiu faras malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'Sekve estas necese submetiĝi, ne nur pro la kolero, sed ankaŭ pro konscienco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Ĉar pro tio vi ankaŭ pagas tributon, ĉar ili estas servantoj de Dio, klopodantaj por ĉi tio mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Redonu ŝuldon al ĉiuj: tributon, al kiu tributo estas ŝuldata; imposton, al kiu imposto; timon, al kiu timo; honoron, al kiu honoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Al neniu ŝuldu ion, krom la reciproka amo; ĉar amante sian proksimulon, oni plenumis la ceteran leĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Ĉar tio: Ne adultu, Ne mortigu, Ne ŝtelu, Ne deziru, kaj ĉiu alia ordono, estas resumitaj en la jena parolo: Amu vian proksimulon kiel vin mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'Amo ne faras malbonon al proksimulo; amo do estas la plenumado de la leĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'Kaj tion faru, sciante la ĝustan tempon, ke nun estas la horo por leviĝo el dormo; ĉar nun nia savo estas pli proksima, ol kiam ni ekkredis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'La nokto jam finiĝas, kaj la tago alproksimiĝas; ni demetu do la farojn de mallumo kaj surmetu la armilojn de lumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Ni iradu dece, kiel en la tago, ne en diboĉado kaj drinkado, nek en volupto kaj senbrideco, nek en malpaco kaj ĵaluzo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'Sed surmetu la Sinjoron Jesuo Kristo, kaj ne sekvu la intencojn de la karno al voluptoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Sed akceptu malfortulon en fido, tamen ne por dubaj disputadoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Unu homo kredas, ke li povas ĉion manĝi; sed alia, estante malforta, manĝas legomojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Kiu manĝas, tiu ne malestimu tiun, kiu ne manĝas; kaj kiu ne manĝas, tiu ne juĝu tiun, kiu manĝas; ĉar Dio lin akceptis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Kiu estas vi, ke vi juĝas la servanton de alia? antaŭ sia propra sinjoro li staras aŭ falas. Li ja estos starigita, ĉar la Sinjoro povas lin starigi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Unu juĝas unu tagon pli alte ol alian, alia egale juĝas ĉiun tagon. Ĉiu homo konvinkiĝu en sia menso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Kiu observas la tagon, tiu observas ĝin al la Sinjoro; kaj la manĝanto manĝas al la Sinjoro, ĉar li dankas Dion; kaj la nemanĝanto nemanĝas al la Sinjoro, kaj li dankas Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Ĉar neniu el ni vivas al si mem, kaj neniu mortas al si mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Ĉar se ni vivas, ni vivas al la Sinjoro, kaj se ni mortas, ni mortas al la Sinjoro; ĉu ni vivas do, aŭ mortas, al la Sinjoro ni apartenas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Ĉar por tio Kristo mortis kaj viviĝis, por esti Sinjoro de la mortintoj kaj de la vivantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Sed vi, kial vi juĝas vian fraton? kaj vi, kial vi malestimas vian fraton? ĉar ni ĉiuj staros antaŭ la tribunala seĝo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Ĉar estas skribite: Kiel Mi vivas, diras la Eternulo, antaŭ Mi kliniĝos ĉiu genuo, Kaj ĉiu lango gloros Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'Tial do ĉiu el ni respondos al Dio pri si mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Tial ni ne plu juĝu unu alian; sed prefere ni juĝu, ke neniu metu en la vojo de sia frato faligilon aŭ ian ofendilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Mi scias, kaj konvinkiĝis en la Sinjoro Jesuo, ke nenio estas malpura per si; sed por tiu, kiu opinias ion malpura, ĝi estas malpura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Ĉar se pro manĝaĵo via frato ĉagreniĝas, vi jam ne iradas en amo. Ne pereigu per via manĝaĵo tiun, por kiu Kristo mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Via bono do ne estu kalumniita;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'ĉar la regno de Dio estas ne manĝado kaj trinkado, sed justeco kaj paco kaj ĝojo en la Sankta Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Ĉar tiu, kiu en tio servas Kriston, plaĉas al Dio, kaj estas aprobata de homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Ni do celu tion, kio apartenas al paco kaj al reciproka edifo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Ne detruu pro manĝaĵo la faron de Dio. Ĉio estas ja pura; sed estas malbone por tiu, kiu manĝas kun ofendo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Estas bone ne manĝi viandon, nek trinki vinon, nek fari ion, per kio via frato ofendiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Tiun fidon, kiun vi havas, havu por vi mem antaŭ Dio. Feliĉa estas tiu, kiu ne juĝas sin mem per tio, kion li aprobas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Sed tiu, kiu estas sendecida, estas kondamnita, se li manĝas; ĉar li manĝas ne el fido, kaj ĉio, kio ne estas el fido, estas peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Ni, kiuj estas fortaj, devas porti la malfortaĵojn de la nefortaj, kaj ne plaĉi al ni mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Ĉiu el ni plaĉu al sia proksimulo per tia bono, kia taŭgas, por edifi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Ĉar Kristo ankaŭ ne plaĉis al si mem, sed, kiel estas skribite: La insultoj de Viaj insultantoj falis sur min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Ĉar ĉio, kio estas antaŭe skribita, estas skribita por nia instruado, por ke per pacienco kaj per konsolo de la Skriboj ni havu esperon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'Kaj la Dio de pacienco kaj konsolo donu al vi, ke vi simpatiu unu kun alia laŭ Kristo Jesuo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'por ke vi unuanime per unu voĉo gloru la Dion kaj Patron de nia Sinjoro Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Tial akceptu unu la alian, kiel ankaŭ Kristo akceptis vin, al la gloro de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Ĉar mi diras, ke Kristo fariĝis servanto al la cirkumcidularo pro la vereco de Dio, por konfirmi la promesojn al la patroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'kaj ke la nacianoj pro lia kompato gloru Dion, kiel estas skribite: Tial mi gloros Vin inter la popoloj, Kaj pri Via nomo mi kantos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'Kaj ankaŭ oni diras: Ĝoju, ho gentoj, kun Lia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'Kaj ankaŭ: Gloru la Eternulon ĉiuj popoloj, Kaj laŭdu Lin ĉiuj gentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'Kaj ankaŭ Jesaja diras: Estos radiko de Jiŝaj, Kaj la stariĝanto por regi la naciojn. Al li celados la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Kaj la Dio de espero plenigu vin per ĉia ĝojo kaj paco en kredado, por ke vi abunde havu esperon, laŭ la potenco de la Sankta Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Kaj, ho miaj fratoj, mi mem konvinkiĝis pri vi, ke vi mem estas plenaj de boneco, plenigitaj per ĉia sciado, kaj kapablaj admoni unu la alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Tamen mi iom pli kuraĝe skribas al vi, kvazaŭ rememorigante vin per la graco, donita al mi de Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'ke mi estu servanto de Kristo Jesuo al la nacianoj, solenanta la evangelion de Dio, por ke la oferado de la nacianoj fariĝu akceptebla, sanktigite de la Sankta Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Mi povas do fieri en Kristo Jesuo pri tio, kio rilatas al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Ĉar mi ne kuraĝos priparoli ion, krom tio, kion Kristo faris per mi, por obeigi la nacianojn, vorte kaj fare,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'en la potenco de signoj kaj mirindaĵoj, en la potenco de la Sankta Spirito; tiel, ke de Jerusalem kaj ĉirkaŭe ĝis Iliriko mi plene predikis la evangelion de Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'jenon ambiciante: tiel prediki la evangelion, ne tie, kie Kristo jam estis priparolita, ke mi ne konstruu sur la fundamento de alia;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'sed kiel estas skribite: Vidos tiuj, al kiuj ne estis dirite pri li, Kaj komprenos tiuj, kiuj ne aŭdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Pro tio ankaŭ mi ofte estis malhelpita veni al vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'sed jam ne havante lokon en ĉi tiuj regionoj, kaj dum multe da jaroj sopirante veni al vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'kiam mi veturos al Hispanujo, mi venos al vi (ĉar mi esperas vin viziti travojaĝante, kaj esti helpata de vi sur la vojo, se antaŭe mi estos sufiĉe gastinta ĉe vi);');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'sed nun mi veturas al Jerusalem, farante servon al la sanktuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Ĉar Makedonujo kaj la Aĥaja lando volonte decidis fari monoferon por la neriĉaj sanktuloj en Jerusalem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Volonte ili decidis, estante iliaj ŝuldantoj. Ĉar se la nacianoj partoprenas en iliaj spiritaj aferoj, tiuj siavice devas servi al ili ankaŭ en materiaj aferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Tial, plenuminte ĉi tion, kaj sigelinte por ili ĉi tiun frukton, mi ekiros Hispanujon, kaj vizitos vin survoje.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'Kaj mi scias, ke venante al vi, mi venos en la pleneco de la beno de Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Sed mi petas vin, fratoj, pro nia Sinjoro Jesuo Kristo kaj pro la amo de la Spirito, ke vi kunluktu kun mi en viaj preĝoj al Dio pro mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'ke mi liberiĝu de la malobeemuloj en Judujo, kaj ke mia servo al Jerusalem estu akceptebla al la sanktuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'por ke mi venu ĝoje al vi per la volo de Dio kaj trovu ripozon ĉe vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Kaj la Dio de paco estu kun vi ĉiuj. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Mi rekomendas al vi nian fratinon Febe, kiu estas diakonino de la eklezio en Kenkrea;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'por ke vi akceptu ŝin en la Sinjoro, kiel konvenas al sanktuloj, kaj ke vi helpu ŝin, en ĉiuj aferoj, pri kiuj ŝi bezonos vin; ĉar ŝi ankaŭ estis helpantino de multaj, kaj de mi mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Salutu Priskilan kaj Akvilan, miajn kunlaborantojn en Kristo Jesuo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'kiuj pro mia vivo riskis siajn kolojn; ilin dankas ne nur mi, sed ankaŭ ĉiuj eklezioj de la nacianoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'kaj salutu la eklezion en ilia domo. Salutu mian amatan Epajneton, kiu estas la unuaaĵo de Azio por Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Salutu Marian, kiu multe laboris por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Salutu Andronikon kaj Junion, miajn parencojn kaj miajn kunkaptitojn, kiuj estas konataj inter la apostoloj, kaj ankaŭ estis en Kristo antaŭ ol mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Salutu Ampliason, mian amaton en la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Salutu Urbanon, nian kunlaboranton por Kristo, kaj mian amatan Staĥison.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Salutu Apeleson, la aprobitan en Kristo. Salutu tiujn, kiuj estas ĉe Aristobulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Salutu mian parencon Herodion. Salutu tiujn ĉe Narkiso, kiuj estas en la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Salutu Trifajnan kaj Trifosan, kiuj laboras en la Sinjoro. Salutu Persison, la virinon amatan, kiu multe laboris en la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Salutu Rufon, elektitan de la Sinjoro, kaj lian kaj mian patrinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Salutu Asinkriton, Flegonon, Hermeson, Patrobason, Hermason, kaj la fratojn ĉe ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Salutu Filologon kaj Julian, Nereon kaj lian fratinon, kaj Olimpason, kaj ĉiujn sanktulojn kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Salutu unu la alian per sankta kiso. Ĉiuj eklezioj de Kristo vin salutas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Nun mi vin petas, fratoj, observi tiujn, kiuj kaŭzas la malkonsentojn kaj ofendojn kontraŭ la instruado, kiun vi lernis; kaj forturni vin de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Ĉar tiaj homoj servas ne al nia Sinjoro Kristo, sed al sia ventro; kaj per siaj belaj kaj flataj vortoj ili trompas la korojn de la naivuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Ĉar via obeemeco estas sciigita al ĉiuj homoj. Tial mi ĝojas pro vi; sed mi deziras, ke vi estu saĝaj rilate la bonon kaj malkleraj rilate la malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'Kaj la Dio de paco baldaŭ subpremos Satanon sub viaj piedoj. La graco de nia Sinjoro Jesuo Kristo estu kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Salutas vin Timoteo, mia kunlaboranto, kaj Lucio kaj Jason kaj Sosipatro, miaj parencoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Mi, Tertio, kiu skribis ĉi tiun epistolon, salutas vin en la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Vin salutas Gajo, la gastiganto de mi kaj de la tuta eklezio. Vin salutas Erasto, la ekonomo de la urbo, kaj Kvarto, la frato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'La graco de nia Sinjoro Jesuo Kristo estu kun vi ĉiuj. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'Al Tiu, kiu povas fortikigi vin, laŭ mia evangelio kaj la predikado de Jesuo Kristo, laŭ la malkaŝo de la mistero, silentigita tra eternaj tempoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'sed nun elmontrita, kaj per la profetaj skriboj laŭ la ordono de la eterna Dio sciigita al ĉiuj nacioj por obeado de fido;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'al la sola saĝa Dio, per Jesuo Kristo estu la gloro por ĉiam kaj eterne. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Paŭlo, vokita por esti apostolo de Jesuo Kristo per la volo de Dio, kaj Sostenes, nia frato,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'al tiu eklezio de Dio, kiu estas en Korinto, al tiuj, kiuj estas sanktigitaj en Kristo Jesuo, vokitaj por esti sanktuloj, kune kun ĉiuj, kiuj en ĉiu loko vokas la nomon de nia Sinjoro Jesuo Kristo, ilia Sinjoro kaj nia:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Graco estu al vi kaj paco de Dio, nia Patro, kaj de la Sinjoro Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Mi ĉiam dankas mian Dion pri vi, pro la graco de Dio al vi donita en Kristo Jesuo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'ke en ĉio vi riĉiĝis en li, en ĉia parolo kaj ĉia scio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'kiel ankaŭ la atesto de Kristo konfirmiĝis en vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'tiel, ke vi malatingas nenian donacon; atendante la malkaŝon de nia Sinjoro Jesuo Kristo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'kiu ankaŭ konfirmos vin ĝis la fino, por ke vi estu neriproĉeblaj en la tago de nia Sinjoro Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Fidela estas Dio, per kiu vi estas alvokitaj en la kunulecon de Lia Filo Jesuo Kristo, nia Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Mi petegas vin, fratoj, per la nomo de nia Sinjoro Jesuo Kristo, ke vi ĉiuj parolu tion saman, kaj ke estu neniaj skismoj inter vi; sed ke vi estu perfekte kunigitaj en la sama spirito kaj en la sama juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Ĉar pri vi, miaj fratoj, estas sciigite al mi de la domanoj de Ĥloe, ke ekzistas inter vi malpacoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Kaj la jenon mi volas diri, ke ĉiu el vi diras: Mi estas de Paŭlo; kaj mi de Apolos; kaj mi de Kefas; kaj mi de Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Ĉu Kristo estas dividita? ĉu Paŭlo krucumiĝis por vi? aŭ ĉu vi baptiĝis en la nomon de Paŭlo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Mi dankas Dion, ke mi baptis neniun el vi krom Krispo kaj Gajo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'por ke neniu diru, ke vi baptiĝis en mian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Kaj mi baptis ankaŭ la familion de Stefanas; krom tio mi ne scias, ĉu mi baptis iun alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Ĉar Kristo sendis min, ne por bapti, sed por prediki la evangelion; ne en saĝeco de vortoj, por ke la kruco de Kristo ne vantiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Ĉar la priparolo de la kruco estas por la pereantoj malsaĝeco; sed por ni, la savatoj, ĝi estas la potenco de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Ĉar estas skribite: Mi pereigos la saĝecon de la saĝuloj, Kaj la kompetentecon de la kompetentuloj Mi malaperigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Kie estas la saĝulo? kie estas la skribisto? kie estas la diskutisto de ĉi tiu tempaĝo? ĉu Dio ne malsaĝigis la saĝecon de la mondo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Ĉar pro tio, ke en la saĝeco de Dio la mondo per sia saĝeco ne konis Dion, bonvolis Dio per la malsaĝeco de la prediko savi la kredantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Ĉar Judoj postulas signojn, kaj Grekoj serĉas saĝecon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'sed ni predikas Kriston krucumitan, por Judoj falilon, kaj por Grekoj malsaĝon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'sed por la vokitoj mem, ĉu Judoj aŭ Grekoj, Kriston la potencon de Dio, kaj la saĝecon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Ĉar la malsaĝeco de Dio estas pli saĝa ol homoj; kaj la malforteco de Dio estas pli forta ol homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Ĉar rigardu vian vokon, fratoj, ke ne multaj saĝuloj laŭ la karno, ne multaj potenculoj, ne multaj nobeloj, estas vokataj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'sed Dio elektis la malsaĝajn objektojn de la mondo, por hontigi la saĝulojn; kaj Dio elektis la malfortajn objektojn de la mondo, por hontigi la fortajn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'kaj la malnoblajn objektojn de la mondo, kaj la malestimatajn Dio elektis, kaj eĉ la nerealajn, por neniigi la realajn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'por ke neniu karno fieru antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Sed el Li vi estas en Kristo Jesuo, kiu fariĝis al ni saĝeco el Dio, kaj justeco kaj sanktigo, kaj elaĉeto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'por ke, kiel estas skribite: Kiu fieras, tiu fieru en la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Kaj mi, fratoj, venante al vi, venis ne kun supereco de parolo aŭ de saĝeco, proklamante al vi la misteron de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Ĉar mi decidis scii ĉe vi nenion, krom Jesuo Kristo kaj tiu krucumita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'Kaj mi estis ĉe vi en malforteco kaj en timo kaj en multa tremado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'Kaj mia parolo kaj mia prediko estis ne en allogaj paroloj de saĝeco, sed en elmontro de la Spirito kaj potenco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'por ke via fido estu ne laŭ la saĝeco de homoj, sed laŭ la potenco de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Tamen ni parolas saĝecon inter plenaĝuloj, sed saĝecon ne de ĉi tiu mondo, nek de la regantoj de ĉi tiu mondo, kiuj neniiĝas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'sed ni parolas la saĝecon de Dio en mistero, la saĝecon kaŝitan, kiun Dio antaŭdestinis antaŭ la mondaĝoj por nia glorado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'kaj kiun scias neniu el la regantoj de ĉi tiu mondo; ĉar se ili ĝin scius, ili ne krucumus la Sinjoron de gloro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'sed kiel estas skribite: Tion, kion okulo ne vidis kaj orelo ne aŭdis, Kaj kio en la koron de homo ne eniris, Dio preparis por tiuj, kiuj Lin amas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Sed al ni Dio malkaŝis ilin per la Spirito; ĉar la Spirito esploras ĉion, eĉ la profundaĵojn de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Ĉar kiu inter homoj scias la aferojn de iu homo, krom la spirito de la homo, kiu estas en li? tiel same la aferojn de Dio scias neniu, krom la Spirito de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Sed ni ricevis ne la spiriton de la mondo, sed la spiriton, kiu estas de Dio; por ke ni sciu tion, al ni donacitan de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'Pri kio ankaŭ ni parolas per vortoj, ne kiujn instruas homa saĝeco, sed kiujn instruas la Spirito; komparante spiritajn kun spiritaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Sed la natura homo ne akceptas la aferojn de la Spirito de Dio; ĉar ili estas por li malsaĝeco; kaj li ne povas ilin scii, pro tio, ke ili estas juĝataj spirite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Sed la spirita homo juĝas ĉion, kaj li mem estas juĝata de neniu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Ĉar kiu sciis la menson de la Eternulo, ke li instruu Lin? Sed ni havas la menson de Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Kaj mi, fratoj, ne povis paroli al vi kiel al spirituloj, sed kiel al karnuloj, kiel al infanetoj en Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Mi nutris vin per lakto, ne per manĝaĵoj; ĉar vi ankoraŭ tion ne kapablis; kaj eĉ nun vi ne kapablas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'ĉar vi estas ankoraŭ karnaj; ĉar dum ekzistas inter vi ĵaluzo kaj malpaco, ĉu vi ne estas karnaj kaj iradas laŭ la maniero de homoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Ĉar kiam unu diras: Mi estas de Paŭlo; kaj alia: Mi estas de Apolos; ĉu vi ne estas homoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Kio do estas Apolos? kaj kio estas Paŭlo? Servantoj, per kiuj vi ekkredis; kaj ĉiu, kiel la Sinjoro al li donis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Mi plantis, Apolos akvumis; sed Dio kreskigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'Tial nek la plantanto estas io, nek la akvumanto; sed Dio, la kreskiganto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Sed la plantanto kaj la akvumanto estas unu; sed ĉiu ricevos sian propran rekompencon laŭ sia laboro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Ĉar ni estas kunlaborantoj kun Dio: vi estas la kultivotaĵo de Dio, la konstruotaĵo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Laŭ la graco de Dio al mi donita, kiel saĝa majstromasonisto mi metis fundamenton; kaj aliaj surkonstruas. Sed ĉiu zorgu, kiel li surkonstruas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Ĉar neniu povas meti alian fundamenton krom tiu, kiu estas metita, tio estas Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Sed se iu konstruas sur la fundamento oron, arĝenton, multekostajn ŝtonojn, lignon, fojnon, pajlon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'ĉies laboraĵo evidentiĝos; ĉar la tago ĝin montros, pro tio, ke ĝi estas malkaŝita en fajro; kaj la fajro mem provos ĉies laboraĵon, kia ĝi estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Se restos ies laboraĵo, kiun li surkonstruis, li ricevos rekompencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'Se ies laboraĵo forbrulos, li suferos perdon; sed li mem saviĝos; tamen kiel tra fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Ĉu vi ne scias, ke vi estas templo de Dio kaj ke en vi loĝas la Spirito de Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Se iu detruas la templon de Dio, tiun detruos Dio; ĉar la templo de Dio estas sankta, kaj vi estas tio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Neniu sin trompu. Se iu el vi opinias sin saĝa en ĉi tiu mondo, li fariĝu malsaĝulo, por ke li saĝiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Ĉar la saĝeco de ĉi tiu mondo estas malsaĝeco ĉe Dio. Ĉar estas skribite: Li kaptas la saĝulojn per ilia ruzaĵo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'kaj ankaŭ: La Eternulo scias la pensojn de saĝuloj, ke ili estas vantaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Tial neniu fanfaronu pri homoj. Ĉar ĉio apartenas al vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'ĉu Paŭlo, aŭ Apolos, aŭ Kefas, aŭ la mondo, aŭ la vivo, aŭ la morto, aŭ estantaĵoj aŭ estontaĵoj: ĉio apartenas al vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'kaj vi al Kristo, kaj Kristo al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Tiel oni rigardu nin, kiel servantojn de Kristo kaj administrantojn de la misteroj de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'Cetere, ĉi tie estas postulate ĉe administrantoj, ke oni troviĝu fidela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Sed ĉe mi estas tre malgrava afero esti juĝata de vi, aŭ per homa juĝo: mi ja ne juĝas min mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'Ĉar mi scias nenion kontraŭ mi; tamen mi ne estas pro tio pravigita; sed tiu, kiu juĝas min, estas la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Tial juĝu nenion antaŭ la tempo, ĝis venos la Sinjoro, kiu enlumigos la kaŝitaĵojn de la mallumo kaj klarigos la intencojn de la koroj; kaj tiam ĉiu ricevos de Dio sian propran laŭdon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Tion do, fratoj, mi alifigure rilatigis al mi kaj Apolos pro vi; por ke vi en ni lernu ne preterpasi la skribitaĵojn; por ke neniu el vi bloveŝvelu por unu kontraŭ la alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Ĉar kiu vin diferencigas? kaj kion vi havas, kion vi ne ricevis? sed se vi ĝin ricevis, kial vi fanfaronas, kvazaŭ vi ĝin ne ricevus?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Jam vi estas plenigitaj, jam vi riĉiĝis, vi reĝis sen ni; kaj mi ja volus, ke vi efektive reĝu, por ke ni ankaŭ reĝu kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Ĉar ŝajnas al mi, ke Dio elmetis nin, la apostolojn, la plej lastajn, kiel mortkondamnitajn; ĉar ni fariĝis spektaklo al la mondo kaj al anĝeloj kaj al homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Ni estas malsaĝuloj pro Kristo, sed vi estas saĝaj en Kristo; ni estas malfortaj, sed vi estas fortaj; vi estas gloraj, sed ni estas senhonoraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Eĉ ĝis la nuna horo ni malsatas kaj soifas, kaj ni estas nudaj, kaj ni estas batataj kaj senhejmaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'kaj ni penadas, laborante per niaj propraj manoj; insultate, ni benas; persekutate, ni eltenas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'kalumniate, ni petegas; ni fariĝas kiel la balaaĵo de la mondo, la forĵetaĵo de ĉio, eĉ ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Ne por hontigi vin mi tion skribas, sed, kiel miajn amatajn filojn, por admoni vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Ĉar kvankam vi eĉ havus dek mil pedagogojn en Kristo, tamen vi havas ne multajn patrojn; ĉar en Kristo Jesuo mi naskigis vin per la evangelio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Mi do petegas vin, estu imitantoj de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'Pro tio mi sendis al vi Timoteon, kiu estas mia amata kaj fidela filo en la Sinjoro, kaj kiu vin memorigos pri miaj vojoj en Kristo, ĝuste kiel mi instruas ĉie en ĉiu eklezio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Kelkaj bloveŝvelas, kvazaŭ mi ne venus al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Sed mi venos al vi baldaŭ, se la Sinjoro tion volos; kaj mi ekscios, ne la parolon de la bloveŝvelintoj, sed la potencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Ĉar la regno de Dio estas ne en parolo, sed en potenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Kion vi volas? ĉu kun vergo mi venu al vi, aŭ en amo kaj en spirito de humileco?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Efektive oni raportas, ke estas ĉe vi malĉasteco, kaj tia malĉasteco, kia ne ekzistas eĉ inter la nacianoj, ke iu havas la edzinon de sia patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'Kaj vi bloveŝvelis, kaj ne prefere ploregis, por ke tiu, kiu faris tion, foriĝu el inter vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Ĉar mi vere, korpe forestante, sed spirite ĉeestante, jam juĝis, kvazaŭ ĉeestante, tiun, kiu tiel faris tion,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'en la nomo de nia Sinjoro Jesuo Kristo, en kunveno de vi kaj de mia spirito kun la potenco de nia Sinjoro Jesuo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'transdoni tian homon al Satano por la detruo de la karno, por ke la spirito saviĝu en la tago de la Sinjoro Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Ne bona estas via fanfaronado. Ĉu vi ne scias, ke malmulto da fermentaĵo fermentigas la tutan mason?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Forpurigu la malnovan fermentaĵon, por ke vi estu nova maso, kiel vi estas nefermentintaj. Ĉar por ni ankaŭ Pasko estas oferita, nome Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'tial ni festu, ne per malnova fermentaĵo, nek per fermentaĵo de malico kaj malboneco, sed per la senfermenta pano de sincereco kaj vereco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'En mia epistolo mi skribis al vi, ke vi ne intermiksu vin kun malĉastuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'ne tute kun la malĉastuloj de ĉi tiu mondo, aŭ kun la aviduloj kaj rabemuloj, aŭ kun idolanoj; ĉar tiuokaze estus necese, ke vi eliru el la mondo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'sed nun mi skribas al vi, ke vi ne intermiksu vin, se iu, nomata frato, eble estas malĉastulo, aŭ avidulo, aŭ idolano, aŭ insultanto, aŭ drinkulo, aŭ rabemulo; kun tia homo eĉ ne kunmanĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Ĉar kiel koncernas min juĝi la eksterulojn? Ĉu vi ne juĝas la internulojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'dum la eksterulojn juĝas Dio? Forigu el inter vi la malvirtulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Ĉu iu el vi, havante aferon kontraŭ sia proksimulo, kuraĝas procesi antaŭ la malpiuloj, kaj ne antaŭ la sanktuloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Aŭ ĉu vi ne scias, ke la sanktuloj juĝos la mondon? kaj se la mondon vi juĝos, ĉu vi ne estas indaj juĝi la plej malgrandajn aferojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Ĉu vi ne scias, ke ni juĝos anĝelojn? kiom pli do aferojn de la nuna vivo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Se do vi devas starigi tribunalon pri la aferoj de la nuna vivo, ĉu vi faras juĝantoj tiujn, kiuj estas negravaj en la eklezio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Mi diras tion, por vin hontigi. Ĉu efektive ne ekzistas ĉe vi eĉ unu saĝulo, kiu povus decidi inter siaj fratoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'sed frato procesas kontraŭ frato, kaj eĉ antaŭ nekredantoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Certe jam estas ĉe vi granda domaĝo, ke vi faras procesojn unu kontraŭ alia. Kial vi ne prefere suferas maljustecon? kial vi ne prefere suferas rabadon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Tamen eĉ vi mem faras maljustecon kaj rabadon, kaj eĉ kontraŭ la fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Aŭ ĉu vi ne scias, ke la maljustuloj ne heredos la regnon de Dio? Ne trompiĝu: nek malĉastuloj, nek idolanoj, nek adultuloj, nek molmoruloj, nek viruzaĉantoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'nek ŝtelistoj, nek aviduloj, nek drinkuloj, nek insultantoj, nek rabemuloj, heredos la regnon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Kaj tiaj estis kelkaj el vi; sed vi laviĝis, sed vi sanktiĝis, sed vi justiĝis en la nomo de la Sinjoro Jesuo Kristo kaj en la Spirito de nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Ĉio estas por mi permesata, sed ne ĉio estas oportuna. Ĉio estas por mi permesata; sed mi ne volas sub io submetiĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Manĝaĵoj por la ventro, kaj la ventro por manĝaĵoj; sed Dio neniigos kune ĝin kaj ilin. Sed la korpo estas ne por malĉasteco, sed por la Sinjoro; kaj la Sinjoro por la korpo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'kaj Dio levis la Sinjoron, kaj levos ankaŭ nin per Sia potenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Ĉu vi ne scias, ke viaj korpoj estas membroj de Kristo? ĉu mi do prenos la membrojn de Kristo, kaj faros ilin membroj de malĉastistino? Nepre ne!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Aŭ ĉu vi ne scias, ke tiu, kiu kuniĝas kun malĉastistino, estas kun ŝi unu korpo? ĉar: Ili, Li diris, estos unu karno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Sed tiu, kiu kuniĝas kun la Sinjoro, estas kun li unu spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Forkuru de malĉasteco. Ĉiu peko, kiun homo faras, estas ekster la korpo; sed tiu, kiu malĉastas, pekas kontraŭ sia propra korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Aŭ ĉu vi ne scias, ke via korpo estas templo de la Sankta Spirito, kiu estas en vi kaj kiun vi havas de Dio? kaj vi ne apartenas al vi mem,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'ĉar vi estas aĉetitaj per prezo; gloru do Dion en via korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Nun rilate al la aferoj, pri kiuj vi skribis: Estas bone por viro, ne tuŝi virinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Sed pro malĉastaĵoj ĉiu viro havu propran edzinon, kaj ĉiu virino havu propran edzon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'La edzo donu al la edzino ŝian rajtaĵon; tiel same ankaŭ la edzino al la edzo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Ne la edzino, sed la edzo rajtas pri ŝia korpo; tiel same ankaŭ ne la edzo, sed la edzino rajtas pri lia korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Ne senigu unu la alian, krom eble kun konsento por kelka tempo, por ke vi dediĉu vin al preĝado, kaj kuniĝu denove, por ke Satano vin ne tentu pro manko de sinregado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Sed tion mi diras kiel permeson, ne kiel ordonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Sed mi volus, ke ĉiuj homoj estu kiel mi mem. Tamen ĉiu havas sian propran donacon de Dio, unu tiel, alia alie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Sed mi diras al senedzinuloj kaj al vidvinoj: Estas bone por ili resti kiel mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Sed se ili ne povas sin deteni, ili edziĝu; ĉar estas pli bone edziĝi, ol bruladi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Sed al geedzoj mi ordonas (tamen ne mi, sed la Sinjoro): Ke edzino ne foriĝu de sia edzo');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, '(tamen, se ŝi foriĝas, ŝi restu senedza, aŭ denove konsentiĝu kun sia edzo); kaj ke la edzo ne forsendu sian edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Sed al la ceteraj diras mi, ne la Sinjoro: Se iu frato havas nekredantan edzinon, kaj ŝi konsentas loĝadi kun li, li ne forigu ŝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'Kaj se virino havas nekredantan edzon, kaj li konsentas loĝadi kun ŝi, ŝi ne forlasu sian edzon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Ĉar la nekredanta edzo estas sanktigita per la edzino, kaj la nekredanta edzino estas sanktigita per la frato; alie viaj infanoj estus profanaj, sed nun ili estas sanktaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Tamen se la nekredanto volas foriri, li foriru: la frato aŭ la fratino en tiaj okazoj ne estas sklavigita; sed Dio vokis nin en paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Ĉar kiel vi scias, ho edzino, ĉu vi savos vian edzon? aŭ kiel vi scias, ho edzo, ĉu vi savos vian edzinon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Sed kiel la Sinjoro disdonis al ĉiu, kiel Dio ĉiun vokis, tiel li iru. Kaj tiel mi ordonas en ĉiuj eklezioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Ĉu iu estas vokita, cirkumcidite? li ne fariĝu necirkumcidita. Ĉu iu estas vokita, necirkumcidite? li ne cirkumcidiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Cirkumcido estas nenio, kaj necirkumcido estas nenio; sed la plenumado de la ordonoj de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Ĉiu restadu en tiu voksorto, en kiu li estas vokita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Ĉu vi estas vokita, estante sklavo? ne ĉagreniĝu pro tio; sed se vi povas liberiĝi, tion uzu prefere.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Ĉar kiu estas vokita en la Sinjoro, estante sklavo, tiu estas liberulo de la Sinjoro; tiel same tiu, kiu estas vokita, estante libera, estas sklavo de Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Vi estas aĉetitaj per prezo; ne fariĝu sklavoj de homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Fratoj, ĉiu, kie li estas vokita, tie restadu kun Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Sed rilate al virgulinoj, mi ne havas ordonon de la Sinjoro; sed mi donas mian opinion, kiel ricevinta de la Sinjoro indulgon, por esti fidela.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Mi opinias do, ke la jeno estas bona pro la nuna neceseco, nome, ke estas bone por viro samstate resti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Ĉu vi estas ligita kun edzino? ne serĉu malligon. Ĉu vi estas malligita je edzino? ne serĉu edzinon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Sed se vi edziĝas, vi ne pekas; kaj se virgulino edziniĝas, ŝi ne pekas. Sed tiaj personoj havos maltrankvilon en la karno; kaj mi volas indulgi vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Sed la jenon mi diras, fratoj: La tempo estas mallongigita, por ke de nun tiuj, kiuj havas edzinojn, estu kvazaŭ ili ne havus;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'kaj la plorantoj, kvazaŭ ne plorantaj; kaj la ĝojantoj, kvazaŭ ne ĝojantaj; kaj la aĉetantoj, kvazaŭ ne posedantaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'kaj tiuj, kiuj uzas la mondon, kvazaŭ ne trouzantaj ĝin; ĉar la formo de ĉi tiu mondo forpasas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Sed mi volas, ke vi estu sen zorgoj. La needziĝinto prizorgas la aferojn de la Sinjoro, kiamaniere li povos plaĉi al la Sinjoro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'sed la edziĝinto prizorgas la aferojn de la mondo, kiamaniere li povos plaĉi al sia edzino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'Kaj estas diferenco ankaŭ inter edzino kaj virgulino. La needziniĝinto prizorgas la aferojn de la Sinjoro, por ke ŝi estu sankta korpe kaj spirite; sed la edziniĝinto prizorgas la aferojn de la mondo, kiamaniere ŝi povos plaĉi al sia edzo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Kaj tion mi diras por via propra utilo; ne por ĵeti kaptilon sur vin, sed pro konveneco, kaj por ke vi atentu la Sinjoron nedistrite.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Sed se iu opinias, ke li kondutas nedece kontraŭ sia virgulino, se ŝi preteriras sian aĝfloradon, kaj se tio estas necesa, li faru tion, kion li volas; li ne pekas; ili geedziĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Sed tiu, kiu staras firma en sia koro, havante nenian neceson, sed regas sian propran volon, kaj decidis en sia koro gardi sian virgulinon, faras bone.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Tiel tiu, kiu lasas sian virgulinon edziniĝi, faras bone; kaj tiu, kiu ne lasas ŝin edziniĝi, faros pli bone.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Edzino estas ligita tiel longe, kiel vivas ŝia edzo; sed se la edzo mortis, ŝi estas libera edziniĝi kun iu, kun kiu ŝi volas; nur en la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Sed laŭ mia opinio ŝi estas pli feliĉa, se ŝi restas samstate; kaj mi opinias, ke mi ankaŭ havas la Spiriton de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Nun rilate al oferitaĵoj al idoloj: Ni scias, ke ni ĉiuj havas scion. La scio bloveŝveligas, sed la amo edifas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Se iu opinias, ke li scias ion, tiu ankoraŭ ne tiel scias, kiel li devus scii;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'sed se iu amas Dion, tiu estas konata de Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'Rilate do la manĝadon de la idoloferitaĵoj, ni scias, ke idolo estas neniaĵo en la mondo, kaj ke ne ekzistas Dio krom unu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Ĉar kvankam estas tiel nomataj dioj, ĉu en la ĉielo aŭ sur la tero, kiel estas dioj multenombraj, kaj sinjoroj multenombraj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'tamen por ni estas unu Dio, la Patro, el kiu estas ĉio, kaj ni por Li; kaj unu Sinjoro, Jesuo Kristo, per kiu estas ĉio, kaj ni per li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Tamen ne ĉe ĉiuj estas tiu scio; sed iuj, pro sia ĝisnuna kutimiĝo al la idolo, manĝas la manĝaĵon kiel oferitaĵon al idolo; kaj ilia konscienco, estante malforta, malpuriĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Sed manĝaĵo ne rekomendos nin al Dio; ĉar ni havas nek mankon, se ni ne manĝas, nek profiton, se ni manĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Sed gardu vin, por ke ĉi tiu via libereco ne fariĝu faligilo por la malfortuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Ĉar se iu vidas vin, kiu havas scion, sidantan ĉe manĝo en idolejo, ĉu lia konscienco, se li estas malforta, ne kuraĝiĝos manĝi idoloferitaĵojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'Pro via scio do pereas la malfortulo, la frato, pro kiu Kristo mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Kaj tiamaniere, pekante kontraŭ la frataro, kaj vundante ilian konsciencon malfortan, vi pekas kontraŭ Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Tial se manĝaĵo maledifas mian fraton, mi neniam plu manĝos karnon, por ke mi ne maledifu mian fraton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Ĉu mi ne estas libera? ĉu mi ne estas apostolo? ĉu mi ne vidis nian Sinjoron Jesuo? ĉu vi ne estas mia laboraĵo en la Sinjoro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Se ĉe aliaj mi ne estas apostolo, tamen almenaŭ mi estas ĉe vi; ĉar la sigelo de mia apostoleco vi estas en la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Mia respondo al tiuj, kiuj min ekzamenas, estas jena:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Ĉu ni ne rajtas manĝi kaj trinki?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Ĉu ni ne rajtas ĉirkaŭkonduki edzinon, kiu estas kredantino, kiel ankaŭ la ceteraj apostoloj kaj la fratoj de la Sinjoro kaj Kefas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Aŭ mi sola kaj Barnabas, ĉu ni ne rajtas ĉesi labori?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Kiu soldato iam deĵoras je sia propra elspezo? kiu plantas vinberĝardenon, kaj ne manĝas ĝian frukton? aŭ kiu paŝtas ŝafaron, kaj ne manĝas el la lakto de la ŝafaro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Ĉu mi parolas tion kiel homo? ĉu ne diras la leĝo tion saman?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Ĉar estas skribite en la leĝo de Moseo: Ne fermu la buŝon al bovo draŝanta. Ĉu pri la bovoj Dio zorgas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'aŭ ĉu Li diras tion tute pro ni? Jes, pro ni ĝi estas skribita; ĉar pluganto devas plugi kun espero, kaj draŝanto devas draŝi kun espero al partopreno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Se ni semis al vi spiritajn aferojn, ĉu estas io grava, se ni rikoltos viajn karnajn aferojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Se aliaj partoprenas ĉi tiun rajton super vi, ĉu ne ni ankoraŭ pli multe? Tamen ni ne uzis ĉi tiun rajton; sed ni eltenas ĉion, por ke ni neniel malhelpu la evangelion de Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Ĉu vi ne scias, ke tiuj, kiuj sin okupas pri sanktaj aferoj, manĝas el la templaj manĝaĵoj, kaj tiuj, kiuj deĵoras ĉe la altaro, partoprenas kune kun la altaro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Tial same la Sinjoro ordonis, ke la proklamantoj de la evangelio vivadu per la evangelio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Sed mi uzis nenion el tiuj rajtoj; kaj mi skribas ĉi tion, ne por ke tio estu farita ĉe mi; ĉar estus pli bone por mi morti, ol se iu vantigus mian fieraĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Ĉar se mi predikas la evangelion, mi havas nenion, pri kio fieri; ĉar neceseco kuŝas sur mi; ĉar ve al mi, se mi ne predikus la evangelion!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Ĉar se mi tion faras propravole, mi havas rekompencon; sed se ne propravole, kiel administranto mi estas komisiita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Kio do estas mia rekompenco? Ke kiam mi predikas la evangelion, mi faru la evangelion senpaga, por ke mi ne plene uzu mian rajton en la evangelio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Ĉar estante libera de ĉiuj, mi min sklavigis sub ĉiujn, por ke mi gajnu des pli multajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'Kaj al la Judoj mi fariĝis kiel Judo, por ke mi gajnu Judojn; al tiuj, kiuj estas sub la leĝo, kiel sub la leĝo, ne estante mem sub la leĝo, por ke mi gajnu tiujn, kiuj estas sub la leĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'al tiuj, kiuj estas sen leĝo, kiel sen leĝo, ne estante sen leĝo rilate Dion, sed sub leĝo rilate Kriston, por ke mi gajnu tiujn, kiuj estas sen leĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Al la malfortuloj mi fariĝis malforta, por ke mi gajnu la malfortulojn; mi fariĝis ĉio al ĉiuj, por ke mi nepre savu kelkajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Kaj mi faras ĉion pro la evangelio, por ke mi ĝin partoprenu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Ĉu vi ne scias, ke ĉiuj kurantoj en la areno kuras, sed nur unu ricevas la premion? Tiel same kuru, por ke vi atingu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Kaj ĉiu konkuranto sin regas en ĉio. Ili faras tion, por ricevi pereontan kronon; sed ni, nepereontan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Mi do tiel kuras, kiel ne sendecide; tiel mi boksas, kiel ne batante la aeron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'sed mi kontuzas mian korpon, kaj ĝin subpremas; por ke mi, predikinte al aliaj, nepre ne estu mem forrifuzata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Ĉar mi ne volas, fratoj, ke vi ne sciu, ke niaj prapatroj estis ĉiuj sub la nubo, kaj ĉiuj trairis la maron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'kaj ĉiuj baptiĝis en Moseon en la nubo kaj en la maro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'kaj ĉiuj manĝis la saman spiritan manĝaĵon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'kaj ĉiuj trinkis la saman spiritan trinkaĵon; ĉar ili trinkis el spirita roko, kiu ilin sekvis; kaj la roko estis Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Tamen la plejmulto el ili ne plaĉis al Dio; ili ja disĵetiĝis en la dezerto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Sed tio okazis kiel ekzemploj por ni, por ke ni ne deziregu malbonaĵojn, kiel ili ankaŭ deziregis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Kaj vi ne estu idolanoj, kiel estis kelkaj el ili; kiel estas skribite: La popolo sidiĝis, por manĝi kaj trinki, kaj ili leviĝis, por ludi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Kaj ni ne malĉastadu, kiel kelkaj el ili faris, kaj falis en unu tago dudek tri mil.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Kaj ni ne incitu la Eternulon, kiel kelkaj el ili incitis, kaj pereis per serpentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Kaj vi ne murmuru, kiel kelkaj el ili murmuris, kaj pereis per la ekstermanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Tio okazis al ili kiel ekzemploj, kaj ĝi estas skribita kiel admono por ni, sur kiujn venis la finoj de la mondaĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Tiu do, kiu opinias, ke li staras, sin gardu, por ke li ne falu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Nenia tento vin prenis, krom laŭ homa forto; sed fidela estas Dio, kiu ne lasos vin esti tentataj super via forto; sed kune kun la tento ankaŭ faros la forkurejon, por ke vi povu ĝin elporti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Tial, miaj amataj, forsavu vin de idolservado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Mi parolas kiel al saĝuloj; vi juĝu tion, kion mi diras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Ĉu ne estas la kaliko de beno, kiun ni benas, partopreno en la sango de Kristo? Ĉu ne estas la pano, kiun ni dispecigas, partopreno en la korpo de Kristo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'pro tio, ke ni, kiuj estas multaj, estas unu pano, unu korpo; ĉar ni ĉiuj prenas parton el la unu pano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Rigardu Izraelon laŭ la karno: ĉu ne estas tiuj, kiuj manĝas la oferojn, partoprenantoj en la altaro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Kion do mi diras? ke idoloferitaĵo estas io, aŭ ke idolo estas io?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Sed mi diras, ke tion, kion oferas la nacianoj, ili oferas al demonoj, kaj ne al Dio; kaj mi ne volas, ke vi partoprenu kun demonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Vi ne povas trinki la kalikon de la Sinjoro kaj la kalikon de demonoj; vi ne povas partopreni ĉe la tablo de la Sinjoro kaj ĉe la tablo de demonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Aŭ ĉu ni ĵaluzigas la Sinjoron? ĉu ni estas pli fortaj ol li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Ĉio estas permesata; sed ne ĉio estas oportuna. Ĉio estas permesata; sed ne ĉio edifas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Neniu celu sian bonon, sed ĉiu la bonon de sia proksimulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Kion oni vendas en la buĉejo, ĉion manĝu, demandante nenion pro konscienco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'ĉar al la Eternulo apartenas la tero, kaj ĉio, kio ĝin plenigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Se iu el la nekredantoj invitas vin al festeno, kaj vi volas iri, kion oni metas antaŭ vi, ĉion manĝu, demandante nenion pro konscienco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Sed se iu diras al vi: Ĉi tio estas oferitaĵo-ne manĝu, pro la montrinto, kaj pro konscienco:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'konscienco, mi diras, ne via propra, sed de la alia; ĉar kial mia libereco estus juĝata per alia konscienco?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Se mi danke partoprenas, kial mi estus mallaŭdata pri tio, pro kio mi donas dankon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Ĉu do vi manĝas, aŭ trinkas, aŭ kion ajn vi faras, faru ĉion por la gloro de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Ne metu faligilon, ĉu por Judoj, aŭ por Grekoj, aŭ por la eklezio de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'tiel same, kiel mi ankaŭ plaĉas al ĉiuj en ĉio, celante ne mian propran utilon, sed la utilon de la multaj, por ke ili saviĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Vi estu imitantoj de mi, kiel mi ankaŭ estas imitanto de Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Mi laŭdas vin, ke vi min memoras en ĉio, kaj ke vi firme tenas la tradiciojn, ĝuste kiel mi transdonis ilin al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Sed mi volas sciigi vin, ke la kapo de ĉiu viro estas Kristo; kaj la kapo de virino estas viro; kaj la kapo de Kristo estas Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Ĉiu viro, preĝanta aŭ profetanta kun kapo kovrita, malhonoras sian kapon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Sed ĉiu virino, preĝanta aŭ profetanta kun kapo senvuala, malhonoras sian kapon; ĉar tio estas tia sama, kvazaŭ ŝi estus razita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Ĉar se virino ne estas vualita, ŝi ankaŭ tondiĝu; sed se estas hontinde por virino esti kun haroj tonditaj aŭ razitaj, ŝi estu vualita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Ĉar viro devas ne havi la kapon vualita, pro tio, ke li estas la bildo kaj gloro de Dio; sed virino estas la gloro de viro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Ĉar viro ne estas el virino, sed virino el viro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'ĉar ankaŭ viro ne estas kreita por virino, sed virino por viro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'pro tio virino devas havi sur la kapo signon de aŭtoritato, pro la anĝeloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Tamen ne ekzistas virino sen viro, nek viro sen virino, en la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Ĉar kiel virino estas el viro, tiel same ankaŭ estas viro per virino; sed ĉio estas el Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Juĝu en vi mem: ĉu decas, ke virino preĝu al Dio nevualite?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'Ĉu eĉ la naturo mem ne instruas vin, ke se viro havas longajn harojn, tio estas por li malhonoro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'Sed se virino havas longajn harojn, tio estas por ŝi gloro; ĉar ŝiaj haroj estas donitaj al ŝi kiel kovraĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Sed se iu ŝajnas esti disputema, ni ne havas tian kutimon, nek la eklezioj de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Sed ordonante al vi jene, mi ne laŭdas vin, ke vi kunvenas ne por pliboniĝo, sed por malpliboniĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Ĉar unue mi aŭdas, ke kiam vi kunvenas en la eklezio, ekzistas inter vi skismoj; kaj mi parte kredas tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Ĉar necese estas, ke ankaŭ herezoj estu inter vi, por ke la aprobitoj evidentiĝu inter vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Kiam do vi kunvenas, estas neeble manĝi la Sinjoran vespermanĝon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'ĉar en via manĝado ĉiu antaŭ alia prenas sian propran vespermanĝon; kaj unu malsatas, kaj alia drinkas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Kio? ĉu vi ne havas domojn, en kiuj vi povas manĝi kaj trinki? aŭ ĉu vi malestimas la eklezion de Dio, kaj hontigas la nehavantojn? Kion mi diros? ĉu mi vin laŭdos en tio? Mi ja vin ne laŭdas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Ĉar mi ricevis de la Sinjoro tion, kion mi ankaŭ transdonis al vi, ke la Sinjoro Jesuo en la nokto, en kiu li estis perfidata, prenis panon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'kaj doninte dankon, li dispecigis ĝin, kaj diris: Ĉio tio estas mia korpo, kiu estas por vi; ĉi tion faru por memorigo pri mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Tiel same ankaŭ la kalikon post la vespermanĝo, dirante: Ĉi tiu kaliko estas la nova interligo en mia sango; ĉi tion faru ĉiufoje, kiam vi trinkos, por memorigo pri mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Ĉar ĉiufoje, kiam vi manĝos ĉi tiun panon kaj trinkos la kalikon, vi proklamos la morton de la Sinjoro, ĝis li venos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'Tial ĉiu, kiu neinde manĝos la panon aŭ trinkos la kalikon de la Sinjoro, kulpiĝos pri la korpo kaj la sango de la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Sed oni sin provu, kaj tiele manĝu el la pano kaj trinku el la kaliko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'Ĉar la manĝanto kaj trinkanto manĝas kaj trinkas juĝon al si mem, se li ne pripensas la korpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Pro tio multaj inter vi estas malfortaj kaj malsanaj, kaj ne malmultaj dormas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Sed se ni pripensus nin mem, ni ne estus juĝitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Sed kiam ni estas juĝataj, ni estas punataj de la Sinjoro, por ke ni ne estu kondamnitaj kune kun la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Tial, miaj fratoj, kiam vi kunvenas por manĝi, atendu unu la alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Se iu malsatas, li manĝu hejme, por ke via kunvenado ne enkonduku juĝon. Kaj la ceteron mi ordigos, kiam mi venos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'Rilate spiritajn donacojn, fratoj, mi ne volas, ke vi estu nesciantaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Vi scias, ke kiam vi estis nacianoj, vi estis forkondukataj al tiuj mutaj idoloj, kiel ajn oni vin kondukis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Tial mi sciigas vin, ke neniu parolanta en la Spirito de Dio diras: Jesuo estas anatemita; kaj neniu povas diri: Jesuo estas Sinjoro, krom per la Sankta Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Ekzistas diverseco de donacoj, sed la sama Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'Kaj ekzistas diverseco de servoj, kaj la sama Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'Kaj ekzistas diverseco de energioj, sed la sama Dio, kiu energias ĉion en ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Sed al ĉiu estas donita la elmontro de la Spirito por utilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Ĉar al unu estas donita per la Spirito la vorto de saĝeco; kaj al alia, la vorto de scio, laŭ la sama Spirito;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'al alia, fido, en la sama Spirito; al alia, donacoj de resanigoj, en la unu Spirito;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'kaj al alia, energioj por mirakloj; kaj al alia, profetpovo; kaj al alia, distingoj de spiritoj; al alia, diversaj lingvoj; kaj al alia, interpreto de lingvoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'sed ĉion tion energias la unu sama Spirito, dividante al ĉiu aparte, kiel al li plaĉas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Ĉar kiel la korpo estas unu, kaj havas multajn membrojn, kaj ĉiuj membroj de la korpo, estante multaj, estas unu korpo; tiel same ankaŭ estas Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Ĉar en unu Spirito ni ĉiuj baptiĝis en unu korpon, ĉu Judoj aŭ Grekoj, ĉu sklavoj aŭ liberaj; kaj ĉiuj estas trinkigitaj el unu Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Ĉar la korpo estas ne unu membro, sed multaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Se la piedo diros: Pro tio, ke mi ne estas la mano, mi ne apartenas al la korpo-ne sekvas de tio, ke ĝi ne apartenas al la korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'Kaj se la orelo diros: Pro tio, ke mi ne estas la okulo, mi ne apartenas al la korpo-ne sekvas de tio, ke ĝi ne apartenas al la korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Se la tuta korpo estus okulo, kie estus la aŭdado? Se la tuta estus aŭdado, kie estus la flarado?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Sed Dio jam metis la membrojn al la korpo, ĉiun, kiel al Li plaĉis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'Kaj se ĉiuj estus unu membro, kie estus la korpo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Nun do ekzistas multaj membroj, sed unu korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Kaj la okulo ne povas diri al la mano: Mi vin ne bezonas; nek same la kapo al la piedoj: Mi vin ne bezonas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Sed multe plie la ŝajne malfortaj membroj de la korpo estas necesaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'kaj al tiuj partoj de la korpo, kiujn ni opinias malpli honorindaj, ni donas pli abundan honoron; kaj niaj negraciaj partoj havas pli abundan gracion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'sed niaj graciaj partoj ne havas bezonon; tamen Dio kunakordigis la korpon, doninte pli abundan honoron al la parto, kiu havas mankon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'por ke ne estu skismo en la korpo; sed ke la membroj prizorgu egale unu la alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'Kaj se unu membro suferas, ĉiuj membroj kune suferas; aŭ se unu membro honoriĝas, ĉiuj membroj kunĝojas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Vi do estas la korpo de Kristo, kaj membroj en ĝi, ĉiu laŭ sia parto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'Kaj Dio metis iujn en la eklezio, unue apostolojn, due profetojn, trie instruantojn, poste miraklojn, poste donacojn de kuracado, helpojn, direktojn, diversajn lingvojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Ĉu ĉiuj estas apostoloj? ĉu ĉiuj profetoj? ĉu ĉiuj instruantoj? ĉu ĉiuj mirakluloj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'ĉu ĉiuj havas kuracan povon? ĉu ĉiuj parolas per lingvoj? ĉu ĉiuj interpretas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Sed vi deziru forte la pligrandajn donacojn. Kaj ankoraŭ pli preferindan vojon mi montras al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Se mi parolus la lingvojn de homoj kaj anĝeloj, sed ne havus amon, mi fariĝus sonanta kupro aŭ tintanta cimbalo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'Kaj se mi posedus la profetpovon, kaj komprenus ĉiujn misterojn kaj ĉian scion; kaj se mi havus ĉian fidon, tiel ke mi povus formovi montojn, sed ne havus amon, mi estus nenio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'Kaj se mi disdonus mian tutan havon por nutri la malsatulojn, kaj se mi lasus mian korpon por forbrulo, sed ne havus amon, per tio mi neniom profitus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'Amo longe suferas, kaj bonfaras; amo ne envias; amo ne fanfaronas, ne ŝveligas sin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'ne kondutas nedece, ne celas por si mem, ne koleriĝas, ne pripensas malbonon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'ne ĝojas pri maljusteco, sed kunĝojas kun vereco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'ĉion toleras, ĉion kredas, ĉion esperas, ĉion eltenas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'Amo neniam pereas; sed, ĉu estas profetadoj, ili neniiĝos; ĉu lingvoj, ili ĉesiĝos; ĉu estas scio, ĝi neniiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Ĉar ni scias laŭparte, kaj ni profetadas laŭparte;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'sed kiam venos perfektaĵo, tiam neniiĝos tio, kio estas laŭparta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Kiam mi estis infano, kiel infano mi parolis, kiel infano mi sentis, kiel infano mi pensis; nun fariĝinte plenaĝulo, mi jam forigis la infanaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Ĉar nun ni vidas per spegulo, malhele; sed tiam okulon ĉe okulo; nun mi konas laŭparte; sed tiam mi konos tiel same, kiel ankaŭ mi estas konita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Restas do nun fido, espero, amo, tiuj tri; kaj la plej granda el ili estas amo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Sekvu amon; tamen deziregu spiritajn donacojn, sed prefere, ke vi profetadu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Ĉar tiu, kiu per lingvo parolas, ne al homoj parolas, sed al Dio; ĉar neniu komprenas, sed en la spirito li parolas misterojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Sed la profetanto parolas al homoj edifon kaj konsilon kaj konsolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Tiu, kiu per lingvo parolas, edifas sin mem; sed la profetanto edifas la eklezion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Mi volas, ke vi ĉiuj parolu per lingvoj, sed prefere, ke vi profetadu; kaj pli granda estas la profetanto, ol la per lingvoj parolanta, krom se li ankaŭ interpretas, por ke la eklezio ricevu edifon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Sed nun, fratoj, se mi venus al vi, parolante per lingvoj, kiel mi vin helpus, se mi ne parolus al vi, aŭ en formo de malkaŝado, aŭ de sciado, aŭ de profetado, aŭ de instruado?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Eĉ la senvivaĵoj, kiuj produktas sonon, ĉu fluto, ĉu harpo, se ili ne donas diferencon en la sonoj, kiel oni scios, kio estas flutata aŭ harpata?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Ĉar se la trumpeto donos necertan voĉon, kiu pretiĝos por batalo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Tiel ankaŭ vi, se vi per la lango ne donas parolon facile kompreneblan, kiel oni scios, kio estas parolata? ĉar en la aeron vi parolus.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Eble estas tiom da specoj de voĉoj en la mondo, kaj nenia estas sensignifa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Se do mi ne scios la signifon de la voĉo, mi estos, rilate la parolanton, barbaro, kaj la parolanto estos por mi barbaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Tiel same ankaŭ vi, dum vi fervore deziras spiritajn donacojn, klopodu, ke vi havu abunde por la edifo de la eklezio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'Tial kiu parolas per lingvo, tiu preĝu, ke li interpretu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Ĉar se mi preĝas per lingvo, mia spirito preĝas, sed mia intelekto estas senfrukta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Kio do estas? Mi preĝos spirite, kaj mi preĝos ankaŭ intelekte; mi kantos spirite, kaj mi kantos ankaŭ intelekte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Alie, se vi benas spirite, kiamaniere tiu, kiu okupas la lokon de la malklerulo, diros Amen ĉe via dankesprimo? ĉar li ne scias, kion vi diras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Ĉar vi ja bone dankesprimas, sed la alia ne estas edifata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Mi dankas Dion, mi parolas per lingvoj pli ol vi ĉiuj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'tamen en la eklezio mi preferus paroli kvin vortojn per mia intelekto, por ke mi instruu ankaŭ aliajn, ol dek mil vortojn per lingvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Fratoj, ne estu infanoj en viaj mensoj; tamen en malico estu infanetoj, sed en la mensoj estu plenaĝuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'En la leĝo estas skribite: Per balbutantaj lipoj kaj per lingvo fremda Mi parolos al ĉi tiu popolo; kaj tamen tiel ili ne volos aŭskulti Min, diras la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Tial la lingvoj estas kiel signo, ne al la kredantoj, sed al la nekredantoj; sed la profetpovo estas kiel signo, ne al la nekredantoj, sed al la kredantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Se do la tuta eklezio kunvenos, kaj ĉiuj parolos per lingvoj, kaj tien envenos nekleruloj aŭ nekredantoj, ĉu ili ne diros, ke vi frenezas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Sed se ĉiuj profetos, kaj envenos nekredanto aŭ neklerulo, li estos konvinkata de ĉiuj, li estos juĝata de ĉiuj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'la sekretoj de lia koro estos elmontrataj; kaj sekve li falos sur sian vizaĝon kaj adoros Dion, deklarante, ke Dio ja estas ĉe vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Kio do estas, fratoj? Kiam vi kunvenas, ĉiu havas psalmon, havas instruon, havas malkaŝaĵon, havas lingvon, havas interpretaĵon. Ĉio fariĝu por edifo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Se oni parolas per lingvo, tio estu duope, aŭ triope je plejmulto, kaj laŭvice; kaj unu interpretu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'sed se ne ĉeestas interpretanto, oni silentu en la eklezio; kaj li parolu al si kaj al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Kaj la profetoj parolu duope aŭ triope, kaj la aliaj interdiferencigu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'Sed se al alia apudsidanta io malkaŝiĝos, la unua silentu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Ĉar vi ĉiuj povas profeti unuope laŭvice, por ke ĉiuj lernu, kaj ĉiuj ricevu konsilon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'kaj la spiritoj de la profetoj estas submetataj al la profetoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'ĉar Dio estas Dio ne de konfuzo, sed de paco; kiel en ĉiuj eklezioj de la sanktuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'La virinoj silentadu en la eklezioj; ĉar ne estas permesate al ili paroli, sed ili submetiĝu, kiel ankaŭ diras la leĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'Kaj se ili volas lerni ion, ili demandu al siaj edzoj hejme; ĉar estas honte por virino paroli en la eklezio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Kio? ĉu el vi la vorto de Dio eliris? ĉu ĝi venis al vi solaj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Se iu ŝajnas al si esti profeto aŭ laŭspirita, li sciiĝu pri tio, kion mi skribas al vi, ke ĝi estas la ordono de la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Sed se iu ne scias, li ne sciu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Tial, fratoj, deziregu profeti, kaj ne malpermesu paroli per lingvoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Sed ĉio fariĝu konvene kaj laŭorde.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Kaj mi sciigas vin, fratoj, pri la evangelio, kiun mi predikis al vi, kiun ankaŭ vi ricevis, en kiu ankaŭ vi staras,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'per kiu vi saviĝis; se vi en memoro tenas, per kiuj vortoj mi ĝin predikis al vi, krom se vi kredis vane.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Ĉar mi transdonis al vi komence tion, kion mi ankaŭ ricevis, ke Kristo mortis pro niaj pekoj laŭ la Skriboj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'kaj ke li estis entombigita; kaj ke li releviĝis la trian tagon laŭ la Skriboj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'kaj ke li aperis al Kefas; poste al la dek du;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'poste li aperis al pli ol kvincent fratoj samtempe, el kiuj la plimulto restas ĝis nun, sed kelkaj jam ekdormis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'poste li aperis al Jakobo; poste al ĉiuj apostoloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'kaj fine li aperis al mi ankaŭ, kiel al infano ekstertempe naskita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Ĉar mi estas la plej malgranda el la apostoloj, kaj ne meritas esti nomata apostolo pro tio, ke mi persekutis la eklezion de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Sed per la graco de Dio mi estas tio, kio mi estas; kaj Lia graco donacita al mi montriĝis ne vana; sed mi laboregis pli abunde ol la ceteraj; tamen ne mi, sed la graco de Dio, kiu estis kun mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Ĉu do mi, ĉu ili, tiel ni predikas, kaj tiel vi kredis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Nu, se Kristo estas predikata, ke li releviĝis el la mortintoj, kiel do diras kelkaj el vi, ke ne ekzistas releviĝo de mortintoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Sed se ne ekzistas releviĝo de mortintoj, ankaŭ Kristo ne releviĝis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'kaj se Kristo ne releviĝis, vana ja estas nia predikado, vana ankaŭ estas via fido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'Jes, kaj ni montriĝas kiel falsaj atestantoj de Dio; tial ke ni atestis pri Dio, ke Li relevis Kriston; kiun Li ne relevis, se la mortintoj ja ne releviĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Ĉar se la mortintoj ne releviĝas, ankaŭ Kristo ne releviĝis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'kaj se Kristo ne releviĝis, via fido estas vana; vi estas ankoraŭ en viaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'Tiuokaze ankaŭ pereis la ekdormintoj en Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Se nur en ĉi tiu vivo ni esperis en Kristo, ni estas el ĉiuj homoj la plej mizeraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Sed nun Kristo releviĝis el la mortintoj, la unuaaĵo de la dormantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'Ĉar tial, ke per homo venis la morto, per homo ankaŭ venis la releviĝo de la mortintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Ĉar kiel en Adam ĉiuj mortas, tiel same ankaŭ en Kristo ĉiuj estos vivigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'Sed ĉiu en sia propra vico: Kristo la unuaaĵo, poste tiuj, kiuj apartenas al Kristo, ĉe lia alveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'Poste venos la fino, kiam li transdonos la reĝecon al Dio, al la Patro; kiam li estos neniiginta ĉian regadon kaj ĉian aŭtoritaton kaj potencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Ĉar li devas reĝadi, ĝis li metos ĉiujn malamikojn sub siajn piedojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'La lasta neniigota malamiko estas la morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Ĉar: Ĉion Li metis sub liajn piedojn. Sed kiam estas dirate: Ĉio estas submetita, estas evidente, ke esceptita estas Tiu, kiu submetis ĉion al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'Kaj kiam ĉio estos submetita al li, tiam la Filo ankaŭ mem estos submetita al Tiu, kiu submetis ĉion al li, por ke Dio estu ĉio en ĉio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Alie kion faros tiuj, kiuj baptiĝas pro la mortintoj? Se la mortintoj tute ne releviĝas, kial do ili baptiĝas pro ili?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'kial ni ankaŭ endanĝeriĝas ĉiun horon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Mi asertas per la singratulado pro vi, fratoj, kiun mi havas en Kristo Jesuo, nia Sinjoro, mi mortas ĉiutage.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Se laŭ homa maniero mi batalis kontraŭ bestoj en Efeso, kiel mi per tio profitas? Se la mortintoj ne releviĝas, ni manĝu kaj trinku, ĉar morgaŭ ni mortos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Ne trompiĝu; Malbonaj kuniĝoj malbonigas bonajn morojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Malebriiĝu en justeco, kaj ne peku; ĉar kelkaj havas nenian scion pri Dio; mi tion diras, por hontigi vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Sed iu diros: Kiel la mortintoj releviĝas? kaj kun kia korpo ili venas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Ho malsaĝulo! tio, kion vi mem semas, ne viviĝas, se ĝi ne mortos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'kaj tio, kion vi semas, estas ne la estonta korpo, sed nuda grenero, eble de tritiko, aŭ de alia speco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'sed Dio donas al ĝi korpon, kiel Li volis, kaj al ĉiu semo ĝian propran korpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Ne ĉiu karno estas unu sama karno; sed ekzistas unu karno de homoj, kaj alia de bestoj, kaj alia karno de birdoj, kaj alia de fiŝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'Ekzistas ankaŭ korpoj ĉielaj kaj korpoj teraj; sed la gloro de la ĉielaj estas unu, kaj la gloro de la teraj estas alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'Ekzistas unu gloro de la suno, kaj alia gloro de la luno, kaj alia gloro de la steloj; ĉar unu stelo diferencas de alia stelo rilate al gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Tia sama ankaŭ estas la releviĝo de la mortintoj. Ĝi estas semata en putreco, ĝi releviĝas en senputreco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'ĝi estas semata en malhonoro, ĝi releviĝas en gloro; ĝi estas semata en malforteco, ĝi releviĝas en potenco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'ĝi estas semata laŭanima korpo, ĝi releviĝas laŭspirita korpo. Se ekzistas laŭanima korpo, ekzistas ankaŭ laŭspirita korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'Tiele ankaŭ estas skribite: La unua homo Adam fariĝis viva animo. La lasta Adam fariĝis viviganta spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Tamen unua estas ne tio, kio estas laŭspirita, sed tio, kio estas laŭanima; poste tio, kio estas laŭspirita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'La unua homo estas el la tero, elpolva; la dua homo estas el la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Kia estas la elpolvulo, tiaj estas ankaŭ la elpolvuloj; kaj kia estas la elĉielulo, tiaj estas ankaŭ la elĉieluloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'Kaj kiel ni portis la figuron de la elpolvulo, tiel same ni portos la figuron de la elĉielulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Kaj la jenon mi diras, fratoj, ke karno kaj sango ne povas heredi la regnon de Dio; kaj putreco ne heredas senputrecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Jen mi sciigas al vi misteron: Ni ne ĉiuj dormos, sed ni ĉiuj ŝanĝiĝos,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'en momento, en okula ekmovo, ĉe la lasta trumpetsono: ĉar la trumpeto sonos, kaj la mortintoj releviĝos senputraj, kaj ni ŝanĝiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Ĉar estas necese, ke ĉi tiu putrema surmetu senputrecon, kaj ke ĉi tiu mortema surmetu senmortecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'Sed kiam ĉi tiu putrema surmetos senputrecon, kaj ĉi tiu mortema surmetos senmortecon, tiam plenumiĝos la skribita diro: La morto forglutiĝis en venko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, 'Ho morto, kie estas via venko? Ho morto, kie estas via pikilo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'La pikilo de la morto estas la peko; kaj la forto de la peko estas la leĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'sed danko estu al Dio, kiu donas al ni la venkon per nia Sinjoro Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Tial, miaj amataj fratoj, estu firmaj, nemoveblaj, ĉiam abundaj en la laboro de la Sinjoro, sciante, ke via penado ne estas vanta en la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'Nun rilate al la monkolekto pro la sanktuloj, kiel mi ordonis al la eklezioj de Galatujo, tiel ankaŭ vi faru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'La unuan tagon de la semajno, ĉiu el vi provizu ĉe si laŭ tio, kion li prospere akiris, por ke ne estu kolektoj tiam, kiam mi venos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'Kaj kiam mi alvenos, kiujn vi per leteroj aprobos, tiujn mi sendos, por alporti vian donacon al Jerusalem;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'kaj se konvenos, ke mi ankaŭ tien vojaĝu, ili vojaĝos kun mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Sed mi venos al vi, kiam mi estos trapasinta Makedonujon; ĉar Makedonujon mi ja trapasos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'sed ĉe vi eble mi restos, aŭ eĉ travintros, por ke vi antaŭen irigu min, kien mi veturos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Ĉar mi ne volas vidi vin nun dumvojaĝe; ĉar mi esperas resti kelkan tempon ĉe vi, se la Sinjoro permesos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Sed mi restos en Efeso ĝis Pentekosto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'ĉar pordo granda kaj efika malfermiĝis al mi, kaj estas multaj kontraŭstarantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Se Timoteo venos, zorgu, ke li estu ĉe vi sentime; ĉar li faras la laboron de la Sinjoro, kiel mi ankaŭ;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'neniu do lin malestimu. Sed antaŭen irigu lin en paco, por ke li venu al mi; ĉar mi atendas lin kun la fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'Sed rilate al la frato Apolos, mi multe petegis lin veni al vi kun la fratoj; sed tute mankis volo veni nun; sed li venos, kiam li havos oportunan tempon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Viglu, staru firme en la fido, viriĝu, fortiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Ĉio via estu farata en amo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Mi petegas vin, fratoj (vi konas la domon de Stefanas, ke ĝi estas la unuaaĵo de la Aĥaja lando, kaj ke ili sin dediĉis al la servo de la sanktuloj),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'ke vi ankaŭ submetiĝu al tiaj, kaj al ĉiu kunhelpanto kaj kunlaboranto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'Kaj mi ĝojas pro la alveno de Stefanas kaj Fortunato kaj Aĥaiko, tial, ke vian mankaĵon ili plenigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'Ĉar ili refreŝigis mian spiriton kaj vian; rekonu do tiajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'La eklezioj de Azio vin salutas. Akvila kaj Priskila vin salutas multe en la Sinjoro, kune kun la eklezio en ilia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Ĉiuj fratoj vin salutas. Salutu unu la alian per sankta kiso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'La saluto de mi, Paŭlo, per mia propra mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Se iu ne amas la Sinjoron Jesuo Kristo, li estu anatemita. Maran-ata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'La graco de la Sinjoro Jesuo Kristo estu kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Mia amo estu kun vi ĉiuj en Kristo Jesuo. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Paŭlo, apostolo de Kristo Jesuo per la volo de Dio, kaj la frato Timoteo, al la eklezio de Dio, kiu estas en Korinto, kune kun ĉiuj sanktuloj, kiuj estas en la tuta Aĥaja lando:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Graco al vi kaj paco de Dio, nia Patro, kaj de la Sinjoro Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Benata estu la Dio kaj Patro de nia Sinjoro Jesuo Kristo, la Patro de kompatoj kaj Dio de ĉia konsolo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'kiu konsoladas nin en nia tuta aflikto, por ke ni povu konsoli tiujn, kiuj iel afliktiĝas, per la konsolo, per kiu ni mem estas konsolataj de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Ĉar kiel la suferoj de Kristo abundas ĉe ni, tiel same abundas ankaŭ per Kristo nia konsolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Sed se ni afliktiĝas, tio estas por via konsolo kaj saviĝo; aŭ se ni konsoliĝas, tio estas por via konsolo, kiu energias, per la pacienca elportado de la samaj suferoj, kiujn ni ankaŭ suferadas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'kaj nia espero pri vi estas firma, ĉar ni scias, ke kiel vi estas partoprenantoj en la suferoj, tiel ankaŭ vi estas partoprenantoj en la konsolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Ĉar ni ne volas, ke vi nesciu, fratoj, pri la aflikto, kiu okazis al ni en Azio, ke ni ekstreme super la forto estis depremitaj, tiel, ke ni forte malesperis, eĉ pri la vivo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'ni ja ricevis la aljuĝon al morto en ni mem, por ke ni fidu ne nin mem, sed Dion, kiu levas la mortintojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'kaj kiu nin forsavis el tia granda morto kaj forsavos; al kiu ni esperis, ke Li ankoraŭ plu nin forsavos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'dum vi ankaŭ nin kunhelpas per via petegado, por ke, pro la donaco donita al ni per multaj personoj, danko estu donata de multaj pro ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Ĉar jen estas nia singratulado, nome la atesto de nia konscienco, ke en sankteco kaj sincereco antaŭ Dio, ne laŭ homa saĝeco, sed laŭ la graco de Dio, ni kondutadis en la mondo, kaj precipe ĉe vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Ĉar ni skribas al vi nenion alian krom tio, kion vi legas kaj prikonsentas, kaj mi esperas, ke vi prikonsentos ĝis la fino;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'kiel ankaŭ vi ja parte prikonsentis pri ni, ke ni estas via singratulado, tiel same, kiel vi ankaŭ estas la nia en la tago de nia Sinjoro Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Kaj en ĉi tiu fidado mi intencis veni unue al vi, por ke vi havu duoblan gracon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'kaj vizitinte vin survoje, trairi en Makedonujon, kaj denove el Makedonujo veni al vi, kaj de vi esti antaŭen irigita al Judujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Kiam mi do tiel intencis, ĉu mi elmontris kapricemon? aŭ kion mi celas, ĉu mi tion celas laŭkarne, tiel ke estu ĉe mi la Jes, Jes, kaj la Ne, Ne?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Sed, kiel Dio estas fidela, nia parolo al vi ne estas Jes kaj Ne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Ĉar la Filo de Dio, Jesuo Kristo, kiu de ni estas predikita inter vi, de mi kaj Silvano kaj Timoteo, ne estis Jes kaj Ne, sed en li la Jes estiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Ĉar kiel ajn multaj estas la promesoj de Dio, en li estas la Jes; tial ankaŭ per li estas la Amen, por la gloro al Dio per ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Kaj tiu, kiu fortikigas nin kune kun vi en Kristo kaj sanktoleis nin, estas Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'kiu ankaŭ nin sigelis kaj donis al ni la antaŭgarantiaĵon de la Spirito en niaj koroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Sed mi vokas Dion kiel atestanton sur mian animon, ke por indulgi vin mi ankoraŭ ne venis al Korinto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Ne kvazaŭ ni estrus super via fido, sed ni estas kunhelpantoj de via ĝojo; ĉar per via fido vi staras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Sed mi decidis por mi mem, ke mi ne venos al vi denove en malĝojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Ĉar se mi vin malĝojigas, kiu do min ĝojigas, krom tiu, kiu estas malĝojigata de mi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'Kaj mi skribis tion saman, por ke, veninte, mi ne havu malĝojon de tiuj, pri kiuj mi devus ĝoji, fidante pri vi ĉiuj, ke mia ĝojo estas la ĝojo de vi ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Ĉar el multe da aflikto kaj kora dolorego mi skribis al vi kun multaj larmoj, ne por ke vi malĝoju, sed ke vi sciu la amon, kiun mi havas al vi abunde.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Sed se iu kaŭzis malĝojon, li kaŭzis malĝojon ne al mi, sed parte (por ne tro forte vin premi) al vi ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Sufiĉa al tia homo estas tiu puno, farita de la plimulto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'pro tio, kontraŭe, vi devus lin pardoni kaj konsoli, por ke tia homo neniel forglutiĝu per sia troa malĝojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Tial mi petegas vin, ke vi konfirmu al li vian amon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Ĝuste por tio mi ja skribis, ke mi vin provu, ĉu vi en ĉio estas obeemaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Sed al kiu vi pardonas ion, mi ankaŭ; ĉar kion mi ankaŭ pardonis, se mi ion pardonis, mi tion faris pro vi antaŭ Kristo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'por ke Satano ne gajnu profiton kontraŭ ni: ĉar ni ne estas sen scio pri liaj ruzoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Kiam mi venis al Troas, por disvastigi tie la evangelion de Kristo, kaj kiam en la Sinjoro malfermiĝis al mi pordo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'mi ne ricevis ripozon por mia spirito, ĉar mi ne trovis mian fraton Tito; sed mi adiaŭis ilin kaj foriris al Makedonujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Sed danko estu al Dio, kiu ĉiam kondukadas nin triumfe en Kristo kaj montras ĉie per ni la bonodoron de Sia koniĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Ĉar ni estas al Dio dolĉa odoro de Kristo, en la savatoj, kaj en la pereantoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'al ĉi tiuj, odoro de morto al morto; al tiuj, odoro de vivo al vivo. Kaj kiu estas taŭga por ĉi tio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Ĉar ni ne similas al multaj, kiuj faras la vorton de Dio komercaĵo; sed kun sincereco, kaj kiel per Dio, antaŭ Dio ni parolas en Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Ĉu ni denove komencas nin mem rekomendi? aŭ ĉu ni bezonas, kiel iuj, leterojn rekomendajn al vi, aŭ de vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Vi mem estas nia letero, skribita sur nia koro, kaj konata kaj legata de ĉiuj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'ĉar vi montriĝis, ke vi estas letero de Kristo liverita per ni, skribita ne per inko, sed per la Spirito de la vivanta Dio; ne sur ŝtonaj tabeloj, sed sur la karnaj tabeloj de la koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Kaj tian fidon ni havas per Kristo al Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'ne kvazaŭ ni taŭgas ion fari per ni mem, sed nia taŭgeco estas el Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'kiu ankaŭ taŭgigis nin kiel administrantojn de nova interligo, ne laŭ litero, sed laŭ spirito; ĉar la litero mortigas, sed la spirito vivigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Sed se la administrado mortiga, esprimita per literoj kaj enĉizita sur ŝtonoj, estiĝis en gloro, tiel, ke la Izraelidoj ne povis fikse rigardi la vizaĝon de Moseo pro lia vizaĝa brileco, jam tamen malpliiĝanta,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'kiel do la administrado spirita ne estos pli multe en gloro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Ĉar se la administrado de kondamno estas gloro, multe pli abunde la administrado de justeco superas en gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Ĉar vere tio, kio havis gloron, ne estis glorigita en ĉi tiu rilato, pro la superabunda gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Ĉar se tio, kio forpasas, havis gloron, ankoraŭ pli multe tio, kio restadas, estas en gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Havante do tian esperon, ni uzas grandan liberecon de parolo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'kaj ne kiel Moseo, kiu metis vualon sur sian vizaĝon, por ke la Izraelidoj ne fikse rigardu ĝis finiĝo de tio, kio estis forpasanta;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'sed iliaj animoj sensentiĝis; ĉar eĉ ĝis hodiaŭ, ĉe la legado de la malnova testamento, nelevita restadas tiu sama vualo, kiu estas forigita en Kristo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'sed ĝis hodiaŭ, kiam ajn oni legas Moseon, vualo kuŝas sur ilia koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Sed kiam ajn oni turnas sin al la Sinjoro, la vualo estas forprenata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'La Sinjoro estas la Spirito; kaj kie estas la Spirito de la Sinjoro, tie estas libereco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Sed ni ĉiuj, per nevualita vizaĝo spegulante la gloron de la Sinjoro, transformiĝas en la saman bildon, de gloro al gloro, kiel el la Sinjoro la Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Pro tio, ke ni havas ĉi tiun administradon, kiel ni ricevis kompaton, ni ne senkuraĝiĝas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'sed ni formetis la kaŝitajn aferojn de honto, ne irante kun ruzeco kaj ne falsante la vorton de Dio, sed per elmontro de la vero rekomendante nin al ĉies konscienco antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Sed se nia evangelio eble estas vualita, ĝi estas vualita rilate al tiuj, kiuj pereas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'en kiuj la dio de ĉi tiu mondo blindigis la animojn de la nekredantoj, por ke la lumo de la evangelio de la gloro de Kristo, kiu estas la bildo de Dio, ne brilu sur ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Ĉar ni predikadas ne nin mem, sed Kriston Jesuon kiel Sinjoron, kaj nin mem kiel viajn servistojn pro Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Ĉar Dio, kiu diris: El mallumo lumo brilos, Tiu brilis en niaj koroj, por doni lumon de la scio de la gloro de Dio en la vizaĝo de Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Sed ni havas ĉi tiun trezoron en argilaj vazoj, por ke la treega grandeco de la potenco estu de Dio, kaj ne de ni mem;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'ni estas premegataj ĉe ĉiu flanko, tamen ne enanguligitaj; embarasataj, sed ne konsternataj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'persekutataj, sed ne forlasataj; faligataj, sed ne detruataj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'ĉiam portante en la korpo la mortiĝon de Jesuo, por ke la vivo ankaŭ de Jesuo elmontriĝu en nia korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Ĉar ni, la vivantoj, ĉiam estas submetataj al morto pro Jesuo, por ke la vivo ankaŭ de Jesuo elmontriĝu en nia morta karno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'La morto do energias en ni, sed la vivo en vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Sed havante la saman spiriton de fido laŭ la skribo: Mi kredis, kaj tial mi parolis; ni ankaŭ kredas, kaj tial ankaŭ ni parolas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'sciante, ke Tiu, kiu levis la Sinjoron Jesuo, levos nin ankaŭ kun Jesuo kaj prezentos nin kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Ĉar ĉio estas pro vi, por ke la graco, multobligita per multaj, abundigu la dankon al la gloro de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Pro tio ni ne senkuraĝiĝas; sed kvankam nia ekstera homo kadukiĝas, tamen nia interna homo renoviĝas tagon post tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Ĉar nia malpeza kaj momenta sufero elfaras por ni, pli kaj pli ekster mezuro, eternan pezon da gloro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'dum ni rigardas ne la vidataĵojn, sed la nevidataĵojn; ĉar la vidataĵoj estas tempaj, sed la nevidataĵoj estas eternaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Ĉar ni scias, ke se la surtera loĝejo de nia tabernaklo dissolviĝos, ni havas de Dio konstruaĵon, domon ne manfaritan, eternan en la ĉieloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Ĉar vere en ĉi tiu ni ĝemas, sopirante al la survestado per nia loĝejo, kiu devenas de la ĉielo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'se almenaŭ, vestite, ni ne troviĝos nudaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Ĉar ni, kiuj estas en ĉi tiu tabernaklo, ĝemas ŝarĝite, ne pro tio, ke ni deziras senvestiĝi, sed ĉar ni deziras survestiĝi, por ke la mortaĵo estu elsorbita de la vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Kaj Tiu, kiu nin elfaris por ĉi tiu celo, estas Dio, kiu donis al ni la antaŭgarantiaĵon de la Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Ni do ĉiam ĝoje kuraĝas, kaj ni scias, ke dum ni ĉeestas en la korpo, ni forestas de la Sinjoro');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, '(ĉar ni iradas fide, ne vide);');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'ni ĝoje kuraĝas, kaj ni plivolas foresti de la korpo kaj ĉeesti kun la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Tial ankaŭ ni ambicias, ĉu ĉeestante aŭ forestante, esti akceptindaj ĉe li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Ĉar ni ĉiuj devos elmontriĝi antaŭ la tribunala seĝo de Kristo, por ke ĉiu ricevu tion, kion li faris en la korpo, laŭ siaj faritaĵoj, ĉu bonaj aŭ malbonaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Sciante do la timon al la Sinjoro, ni celas konvinki homojn, sed ni ja elmontriĝas al Dio; kaj ni esperas, ke ni elmontriĝas ankaŭ al viaj konsciencoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Ni ne denove nin rekomendas al vi, sed donas al vi kaŭzon fieriĝi pri ni, por ke vi havu ion respondi al tiuj, kiuj fieriĝas ŝajne kaj ne kore.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Ĉar ĉu ni estis frenezaj, tio estis pro Dio, aŭ ĉu ni estas seriozaj, tio estas pro vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Ĉar la amo de Kristo nin devigas; ĉar ni juĝas jene, ke ĉar unu mortis pro ĉiuj, tial ĉiuj mortis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'kaj li mortis pro ĉiuj, por ke la vivantoj jam vivu ne por si mem, sed por tiu, kiu pro ili mortis kaj releviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Tial ni de nun konas neniun laŭkarne; eĉ kvankam ni konis Kriston laŭkarne, tamen ni ne plu lin tiel konas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Tial se iu homo estas en Kristo, estas jam nova kreitaĵo; la malnovaĵoj forpasis, jen ili jam estiĝis novaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'Sed ĉio estas de Dio, kiu repacigis nin al Si mem per Kristo kaj donis al ni la administradon de la repacigo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'nome, ke Dio estis en Kristo, repacigante la mondon al Si, ne alkalkulante al ili la kulpojn, kaj komisiis al ni la vorton repacigan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Ni do estas ambasadoroj pro Kristo, kvazaŭ Dio per ni petadus; ni vin petegas pro Kristo, repaciĝu al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Tiun, kiu ne konis pekon, Li faris peko pro ni; por ke ni fariĝu justeco de Dio en li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Kaj kunlaborante kun li, ni petegas ankaŭ, ke vi ne vane akceptu la gracon de Dio');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, '(ĉar Li diris: En tempo de favoro Mi aŭskultis vin, Kaj en tago de savo Mi helpis vin; jen nun la tempo de favoro; jen nun la tago de savo);');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'ni donu en nenio okazon por maledifo, por ke oni ne kulpigu nian administradon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'sed en ĉio ni aprobigu nin, kiel servantoj de Dio, en multa pacienco, en suferoj, en afliktoj, en malfacilaĵoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'en batovundoj, en malliberigoj, en tumultoj, en laboroj, en maldormoj, en malsatoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'en ĉasteco, en sciado, en pacienco, en afableco, en Spirito Sankta, en amo senhipokrita,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'en la vorto de vero, en la potenco de Dio; per la armaĵo de justeco dekstre kaj maldekstre,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'per gloro kaj malgloro, per malbonfamo kaj bonfamo; kiel trompantoj, tamen veraj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'kiel nekonataj, tamen bone konataj; kiel mortantaj, kaj jen ni vivas; kiel pune korektataj, tamen ne mortigataj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'kiel dolorplenaj, tamen ĉiam ĝojantaj; kiel malriĉaj, tamen multajn riĉigantaj; kiel nenion havantaj, tamen posedantaj ĉion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Nia buŝo estas malfermita al vi, ho Korintanoj, nia koro estas plivastigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'Vi ne estas malvastigitaj en ni, sed vi estas malvastigitaj en viaj propraj internaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'Pro rekompenco samspeca do (mi parolas kiel al infanoj) vi ankaŭ estu plivastigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Ne estiĝu kunjuguloj maltaŭge kun nekredantoj; ĉar kian partoprenon havas justeco kun maljusteco? aŭ kian komunaĵon havas lumo kun mallumo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Kaj kian akordon havas Kristo kun Belial? aŭ kian kunecon havas kredanto kun nekredanto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'Kaj kian konsenton havas templo de Dio kun idoloj? ĉar ni estas templo de Dio vivanta; kiel diris Dio: Mi loĝos inter ili, kaj Mi iros inter ili; kaj Mi estos ilia Dio, kaj ili estos Mia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'Tial Eliru el inter ili, kaj estu apartaj, diras la Eternulo, Kaj ne tuŝu malpuraĵon; Kaj Mi vin akceptos,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'Kaj Mi estos por vi Patro, Kaj vi estos Miaj filoj kaj filinoj, diras la Eternulo Plejpotenca.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Havante do ĉi tiujn promesojn, amataj, ni purigu nin de ĉia malpureco karna kaj spirita, perfektigante sanktecon en la timo al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Malfermu al ni viajn korojn; ni kontraŭ neniu maljuste agis, ni ruinigis neniun, al neniu ni friponis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Ne por vin kondamni mi tion diras; ĉar mi antaŭe diris, ke vi estas en niaj koroj, por kune vivi kaj kune morti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Granda estas mia parola libereco al vi, granda estas mia fiereco pri vi: mi estas plena de konsolo, al mi superabundas la ĝojo meze de nia tuta aflikto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Ĉar eĉ kiam ni jam alvenis en Makedonujon, nia karno tute ne faciliĝis, sed ni ĉiel depremiĝis; ekstere estis bataloj, interne timoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Tamen Dio, kiu konsolas la humilulojn, konsolis nin per la alveno de Tito;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'kaj ne nur per lia alveno, sed ankaŭ per la konsolo, per kiu li konsoliĝis pri vi, dum li pridiris al ni vian sopiron, vian doloron, vian fervoron pro mi; tiel, ke mi ankoraŭ pli ĝojis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Ĉar kvankam mi vin malĝojigis per mia epistolo, mi ne bedaŭras pri tio, kvankam mi ja bedaŭris; ĉar mi vidas, ke tiu epistolo vin malĝojigis, sed nur mallonge.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Mi nun ĝojas, ne pro tio, ke vi malĝojis, sed pro tio, ke vi malĝojis ĝis pento; ĉar vi laŭ Dio malĝojis, por ke vi havu nenian malutilon per ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Ĉar la malĝojo laŭ Dio elfaras penton ĝis savo, ne bedaŭrindan; sed la malĝojo de la mondo elfaras morton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Ĉar jen kian zorgemon tiu sama malĝojo laŭ Dio elfaris en vi, plue kian senkulpigon, plue kian indignon, plue kian timon, plue kian sopiron, plue kian fervoron, plue kian venĝon! En ĉio vi elmontris vin puraj pri la afero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Tial kvankam mi skribis al vi, tamen tio estis ne pro tiu, kiu faris la malbonon, nek pro tiu, kiu suferis la malbonon, sed por ke via zorgemo por ni elmontriĝu al vi mem antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Tial ni konsoliĝis; kaj en nia konsolo ni ĝojis des pli multege pro la ĝojo de Tito, ĉar lia animo estas refreŝigita de vi ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Ĉar se en io mi fanfaronis al li pro vi, mi ne hontis; sed kiel ni ĉion parolis vereme al vi, tiel same ankaŭ nia fanfaronado, kiun mi faris antaŭ Tito, montriĝis vera.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'Kaj lia interna amo pli abundas al vi, dum li memoras la obeadon de vi ĉiuj, kiel kun timo kaj tremo vi lin akceptis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Mi ĝojas, ke en ĉio mi povas fidi al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Cetere, fratoj, ni sciigas al vi la gracon de Dio, kiu estas donacita en la eklezioj Makedonaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'nome, en grava provo per suferado, la abundo de ilia ĝojo kaj ilia profunda malriĉeco abundis al la riĉo de ilia malavareco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Ĉar mi konstatas, ke laŭ sia povo-jes, kaj super sia povo-ili donis memvole,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'petegante nin per multe da petado fari tiun komplezon kaj la komunan helpservadon al la sanktuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'kaj ne kiel ni esperis, sed unue ili sin dediĉis al la Sinjoro, kaj al ni per la volo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'Tiel, ke ni instigis Titon, ke kiel li antaŭe komencis, tiel same li perfektigu en vi ĉi tiun pluan gracon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Sed kiel al vi ĉio abundas: fido kaj parolo kaj scio kaj fervoro kaj via amo al ni, tiel abundu al vi ankaŭ ĉi tiu graco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Mi parolas ne ordonante, sed provante per la fervoro de aliaj la sincerecon de via amo ankaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Ĉar vi scias la gracon de nia Sinjoro Jesuo Kristo, ke kvankam li estis riĉa, tamen pro vi li fariĝis malriĉa, por ke vi per lia malriĉeco fariĝu riĉaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'Kaj en tio mi donas mian opinion; ĉar ĉi tio utilas por vi, kiuj unuaj komencis, antaŭ unu jaro, ne nur fari, sed ankaŭ voli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Sed nun kompletigu la faradon ankaŭ; tiel ke, kiel estis la volonteco voli, tiel ankaŭ estu la plenumo el via havo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Ĉar kie ekzistas la volonteco, ĝi estos akceptita laŭ la havo, ne laŭ la nehavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Ĉar mi diras tion, ne por ke aliaj estu faciligataj kaj vi premataj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'sed laŭ egaleco: via abundo nuntempe fariĝu por ilia manko, por ke ilia abundo fariĝu por via manko, por ke estu egaleco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'kiel estas skribite: Tiu, kiu kolektis pli, ne havis superflue, kaj tiu, kiu kolektis malpli, ne havis mankon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Sed danko estu al Dio, kiu metas en la koron de Tito la saman zorgon pri vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'Ĉar li ja akceptis la instigon; sed estante mem tre fervora, li ekiris al vi memvole.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Kaj ni sendis kune kun li la fraton, kies laŭdo en la evangelio disvastiĝas tra ĉiuj eklezioj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'kaj krom tio, li ankaŭ estis elektita de la eklezioj, por vojaĝadi kune kun ni rilate al ĉi tiu graco, kiun ni administradas al la gloro de la Sinjoro, kaj por elmontri nian volontecon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'evitante tion, ke iu riproĉus nin rilate al ĉi tiu monhelpo, kiun ni administras;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'ĉar ni celas aferojn konvenajn ne nur antaŭ la Sinjoro, sed ankaŭ antaŭ homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'Kaj ni sendis kune kun ili nian fraton, kiun ni ofte pruvis fervora en multaj aferoj, sed nun multe pli fervora pro la granda fido, kiun li havas al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Se iu demandas pri Tito, li estas mia kunulo kaj mia kunlaboranto rilate al vi; se pri niaj fratoj, ili estas apostoloj de eklezioj, la gloro de Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Vi do elmontru al ili antaŭ la eklezioj la pruvon de via amo kaj de nia fanfaronado pro vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Ĉar pri la servado al la sanktuloj estas por mi superflue skribi al vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'ĉar mi scias vian volontecon, pri kiu mi fanfaronas pro vi al la Makedonoj, ke la Aĥaja lando jam antaŭ unu jaro pretiĝis; kaj via fervoro instigis la plimulton el ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Sed mi sendis la fratojn, por ke nia fanfaronado pro vi ne fariĝu vanta rilate al ĉi tio, sed, kiel mi diris, por ke vi estu pretaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'por ke, se venus kune kun mi iuj el Makedonujo kaj trovus vin ne pretaj, ni (por ne diri, vi) ne hontu pro ĉi tiu fido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Mi do opiniis necesa, peti la fratojn, ke ili antaŭe iru al vi, kaj antaŭe pretigu vian de longe promesitan helpmonon, por ke tio estu preta, kiel volonte donita, kaj ne kiel eldevigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Sed jen: Tiu, kiu semas ŝpare, ankaŭ rikoltos ŝpare; kaj tiu, kiu semas malavare, ankaŭ rikoltos malavare.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Ĉiu faru laŭ tio, kion li intencas en la koro, ne domaĝante, nek pro neceseco; ĉar Dio amas donacanton ĝojan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Kaj Dio povas abundigi ĉe vi ĉian gracon, por ke vi, havante ĉiam en ĉio ĉian sufiĉecon, abunde rilatu al ĉia bona faro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'kiel estas skribite: Li ŝutis kaj donis al la malriĉuloj; Lia justeco restas eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Kaj Tiu, kiu donas semon al la semanto kaj panon por nutraĵo, donos kaj multobligos vian semotan semon, kaj plimultigos la fruktojn de via justeco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'dum vi pliriĉiĝos en ĉio al ĉia malavareco, kiu efikas per ni dankdonadon al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Ĉar la administrado de ĉi tiu servado ne nur kompletigas la mezuron de la bezonoj de la sanktuloj, sed ankaŭ abundas per multaj dankoj al Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'ĉar provinte vin per ĉi tiu administrado, ili gloras Dion pro la obeo de via konfeso al la evangelio de Kristo, kaj pro la malavareco de via donaco al ili kaj al ĉiuj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'dum ili mem ankaŭ, per petado por vi, tre sopiras al vi pro la grandega graco de Dio en vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Danko estu al Dio pro Lia neesprimebla donaco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Mi mem, Paŭlo, petegas vin pro la mildeco kaj dolĉanimeco de Kristo, mi, kiu en via ĉeesto estas humila inter vi, sed, forestante, tre kuraĝas rilate al vi:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'mi mem petegas vin, ke ĉeestante, mi ne kuraĝu per la insisteco, per kiu mi bontrovas kuraĝi kontraŭ iuj, kiuj rigardas nin kiel laŭkarne iradantajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Ĉar kvankam ni iradas en karno, tamen ni ne militadas laŭ karno');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, '(ĉar la iloj de nia militado estas ne laŭkarnaj, sed potencaj antaŭ Dio por la deĵetado de fortikaĵoj);');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'deĵetante diskutojn, kaj ĉian altaĵon levatan kontraŭ la scio konforma al Dio, kaj ekkaptante ĉiun penson al la obeo al Kristo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'kaj starante pretaj puni ĉian malobeon, tuj kiam via obeo plenumiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Vi rigardas la aferojn antaŭ via vizaĝo. Se iu fidas en si mem, ke li apartenas al Kristo, li denove pripensu en si mem, ke kiel li apartenas al Kristo, tiel same ankaŭ ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Ĉar eĉ se mi fierus iom supermezure pri nia aŭtoritato (kiun donis la Sinjoro, por vin edifi, kaj ne por vin deĵeti), mi ne hontus;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'por ke ne ŝajnu, kvazaŭ mi volus timigi vin per miaj leteroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Ĉar, oni diras, liaj leteroj estas gravaj kaj fortaj; sed lia korpa aspekto estas malforta, kaj lia parolo malŝatinda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Tiu homo konsideru, ke kiaj, forestante, ni estas per leteroj, tiaj, ĉeestante, ni estas ankaŭ per agado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Ĉar ni ne kuraĝas nin interkalkuli aŭ kompari kun iuj el la sin rekomendantaj; ĉar ili estas neprudentaj, mezurante sin laŭ si mem kaj komparante sin al si mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Sed ni fieros ne pretermezure, sed laŭ la amplekso de la mezurilo, kiun Dio destinis al ni, por mezuri, por atingi eĉ ĝis vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Ĉar ni ne tro etendas nin, kvazaŭ ni ne atingus ĝis vi; ĉar ni jam venis ĝis vi en la evangelio de Kristo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'ne fierante pretermezure, nome en laboroj malpropraj, sed esperante, ke dum kreskos via fido, ni kreskos en vi laŭ nia mezurilo ĝis plua abundo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'por prediki la evangelion ĝis la regionoj preter vi, kaj ne fieri pri malpropra mezurilo rilate al aferoj jam faritaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Sed kiu fieras, tiu fieru en la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Ĉar ne tiu, kiu sin mem rekomendas, estas akceptata, sed tiu, kiun rekomendas la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Mi volas, ke vi pacience toleru min pro iom da malsaĝeco; sed efektive vi ja pacience min toleras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Ĉar mi ĵaluzas pri vi per Dia ĵaluzo, ĉar mi fianĉigis vin al unu edzo, por ke mi prezentu vin kiel ĉastan virgulinon al Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Sed mi timas, ke kiel trompis Evan la serpento per sia ruzeco, viaj animoj iel dekliniĝos for de la simpleco kaj la ĉasteco, kiu estas en Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Ĉar se iu vizitanto predikas alian Kriston, kiun ni ne predikis, aŭ se vi ricevas malsaman spiriton, kiun vi ne ricevis, aŭ malsaman evangelion, kiun vi ne akceptis, facilanime vi lin toleras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Ĉar mi opinias, ke mi neniel malsuperas la plej eminentajn apostolojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Kaj kvankam mi estas neklera laŭ parolo, mi tamen ne tia estas laŭ scio; sed en ĉio ni malkaŝe agis ĉe vi inter ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Aŭ ĉu mi pekis, humiligante min, por ke vi estu altigitaj, en tio, ke mi senpage predikis al vi la evangelion de Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Mi senigis aliajn ekleziojn, ricevante de ili pagon, por servi al vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'kaj kiam mi ĉeestis ĉe vi kaj havis mankon, mi ne estis ŝarĝo sur iu; ĉar la fratoj, veninte el Makedonujo, plenigis la mezuron de mia bezono; kaj en ĉio mi tenis min ne ŝarĝa rilate vin, kaj ankoraŭ tenos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Jen estas la vero de Kristo en mi, ke ĉi tiu fanfarono ne estos barita kontraŭ mi en la regionoj Aĥajaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Kial? ĉu tial, ke mi vin ne amas? Dio scias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Sed kiel mi faras, tiel mi ankaŭ faros, por forigi la pretekston al tiuj, kiuj deziras pretekston, por ke, en kio ili fieras, ili troviĝu samaj, kiel ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Ĉar tiaj homoj estas falsaj apostoloj, trompemaj laboristoj, sin aliformante kvazaŭ apostolojn de Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'Kaj nenia miro; ĉar Satano mem sin aliformas kvazaŭ anĝelon de lumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Estas do nenio granda, se liaj servantoj ankaŭ sin aliformas kvazaŭ servantojn de justeco; ilia finiĝo estos laŭ iliaj faroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Denove mi diras: Neniu opiniu min malsaĝa; sed se vi ja tiel opinias min, tamen min akceptu kiel malsaĝan, por ke mi ankaŭ iom fanfaronu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'Tion, kion mi diras, mi diras ne laŭ la Sinjoro, sed kvazaŭ malsaĝe, en ĉi tiu insistado pri fierado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Ĉar multaj fanfaronas laŭ la karno, do mi ankaŭ fanfaronos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Ĉar vi afable toleras malsaĝulojn, estante mem saĝaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Ĉar vi toleras homon, se li vin sklavigas, se li vin formanĝas, se li vin kaptas, se li sin altigas, se li batas al vi la vizaĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Mi parolas kvazaŭ per sinmallaŭdo, kvazaŭ ni estus malfortiĝintaj. Tamen pri kio iu kuraĝas, pri tio (mi parolas en malsaĝeco) mi ankaŭ kuraĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Ĉu ili estas Hebreoj? mi ankaŭ. Ĉu ili estas Izraelidoj? mi ankaŭ. Ĉu ili estas el la idaro de Abraham? mi ankaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Ĉu ili estas servantoj al Kristo? (mi parolas kiel frenezulo) mi plie; en laboroj pli abunde, en malliberejoj pli abunde, en batoj supermezure, en mortiĝoj ofte.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'De la Judoj kvinfoje mi ricevis batojn po kvardek sen unu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'Trifoje mi estas batita per vergoj, unufoje mi estas priĵetita per ŝtonoj, trifoje mi suferis ŝippereon, nokton kaj tagon mi pasis en la profunda maro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'en oftaj vojaĝoj, en danĝeroj de riveroj, danĝeroj de rabistoj, danĝeroj de Judoj, danĝeroj de la nacianoj, danĝeroj en urbo, danĝeroj en dezerto, danĝeroj en la maro, danĝeroj inter falsaj fratoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'en laboro kaj sufero, en oftaj sendormiĝoj, en malsato kaj soifo, en oftaj fastoj, en malvarmo kaj senvesteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'Krom tiuj aferoj eksteraj estas tio, kio min premas ĉiutage, nome la zorgado pri ĉiuj eklezioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Kiu estas malforta, kaj mi ne estas malforta? kiu estas faligata, kaj mi ne indignas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'Se mi nepre devas fanfaroni, mi fanfaronos pri tio, kio rilatas al mia malforteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'La Dio kaj Patro de la Sinjoro Jesuo, Tiu, kiu ĉiam estas benata, scias, ke mi ne mensogas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'En Damasko, la urbestro sub la reĝo Aretas starigis gardistaron en la urbo de la Damaskanoj, por min kapti;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'kaj tra fenestro oni min delasis laŭflanke de la muro en korbo, kaj mi eliĝis de liaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Mi nepre devas fanfaroni, kvankam tio ne konvenas; sed mi venos al vizioj kaj malkaŝoj de la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Mi konas viron en Kristo, antaŭ dek kvar jaroj (ĉu en la korpo, mi ne scias, ĉu ekster la korpo, mi ne scias; Dio scias) eklevitan ĝis en la trian ĉielon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'kaj mi scias pri la tiela viro (ĉu en la korpo, aŭ ekster la korpo, mi ne scias; Dio scias),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'ke li estis eklevita en Paradizon, kaj aŭdis nedireblajn vortojn, kiujn ne estas permesate al homo paroli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Pro tia homo mi fieros; sed pro mi mem mi ne fieros, krom rilate al miaj malfortaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Ĉar se mi deziros fieri, mi ne estos malsaĝa; ĉar mi diros la veron; sed mi min detenas, por ke neniu min opiniu supera ol tia, kia li vidas min, aŭ aŭdas ĉe mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'Kaj pro la treega grandeco de la malkaŝoj-por ke mi ne tro altiĝu, estis donita al mi dornego por la karno, sendito de Satano, por min kontuzi, por ke mi ne tro altiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Pri tio mi petegis trifoje la Sinjoron, ke ĝi foriru de mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'Kaj li diris al mi: Mia graco sufiĉas por vi, ĉar mia potenco perfektiĝas en malforteco. Plej ĝoje do mi plivole fieros pri miaj malfortaĵoj, por ke la potenco de Kristo kovru min.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Mi do plezuron havas en malfortaĵoj, en atencoj, en bezonegoj, en persekutoj, en suferoj, pro Kristo; ĉar kiam mi estas malforta, tiam mi estas forta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Mi malsaĝiĝis: vi min devigis; ĉar mi devus estis laŭdata de vi; ĉar en nenio mi malsuperis la plej eminentajn apostolojn, kvankam mi estas nenio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Vere la signoj de apostolo estis elfaritaj inter vi en ĉia pacienco, per signoj kaj mirindaĵoj kaj potencaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Ĉar en kio vi fariĝis malsuperaj kompare al la aliaj eklezioj, krom en tio, ke mi mem ne ŝarĝiĝis al vi? pardonu al mi ĉi tiun maljustaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Jen la trian fojon mi min tenas preta veni al vi; kaj mi ne fariĝos ŝarĝo por vi, ĉar mi celas ne viajn, sed vin; ĉar devus provizi ne la idoj por la gepatroj, sed la gepatroj por la idoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Kaj plej ĝoje mi elspezos kaj elspeziĝos por viaj animoj. Se mi vin amas pli abunde, ĉu mi estas des malpli amata?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Tio estu, tamen mi ne estis ŝarĝo por vi; sed estante ruzema, mi vin kaptis per logo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Ĉu mi superruzis vin per iu el tiuj, kiujn mi sendis al vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Mi instigis al Tito, kaj kune kun li mi sendis la fraton. Ĉu Tito vin superruzis? ĉu ni ne iradis laŭ la sama Spirito? ĉu ni ne iradis en la samaj piedosignoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Vi ankoraŭ nun ĉiam pensas, ke ni nin senkulpigas antaŭ vi. Antaŭ Dio, ni parolas en Kristo. Sed ĉio, amataj miaj, estas por via edifo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Ĉar mi timas, ke veninte, mi iel ne trovos vin tiaj, kiajn mi volas; kaj ke mi mem estos trovata tia, kian vi ne volas; ke iel estos malpaco, ĵaluzo, koleroj, partioj, kalumnioj, murmurado, ŝveliĝoj, tumultoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'ke kiam mi revenos, mia Dio min humiligos antaŭ vi, kaj mi malĝojos pro multaj, kiuj jam antaŭe pekis kaj ne pentis pri la malpureco kaj adulto kaj volupto, kiujn ili faris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Jen la trian fojon mi venas al vi. Laŭ la diro de du atestantoj aŭ tri ĉiu vorto estu konfirmita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Mi antaŭdiris, kaj mi nun antaŭdiras, kiel ĉeestante la duan fojon, tiel nun forestante, al la jam pekintaj kaj al ĉiuj ceteraj, ke se mi revenos, mi ne indulgos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'ĉar vi serĉas pruvon de tio, ke parolas en mi Kristo, kiu rilate al vi ne estas malforta, sed energias en vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'ĉar li estis krucumita pro malforto, tamen li vivas per la potenco de Dio. Ĉar ni ankaŭ estas malfortaj kune kun li, sed ni vivos kune kun li per la potenco de Dio rilate al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Provu vin mem, ĉu vi estas en la fido; ekzamenu vin mem. Aŭ ĉu vi ne scias pri vi mem, ke Jesuo Kristo estas en vi? se ja vi ne estas malaprobindaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Sed mi esperas, ke vi sciiĝos, ke ni ne estas malaprobindaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Ni preĝas al Dio, ke vi faru nenian malbonon; ne por tio, ke ni montriĝu aprobataj, sed por ke vi faradu tion, kio estas honorinda, eĉ kvankam ni estus malaprobindaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Ĉar ni ne povas fari ion kontraŭ la vero, sed nur por la vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Ĉar ni ĝojas, kiam ni estas malfortaj kaj vi estas fortaj; ankaŭ ni preĝas por via perfektiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Pro tio mi skribas ĉi tion, forestante, por ke, ĉeestante, mi ne agu severe laŭ la aŭtoritato, kiun la Sinjoro donis al mi por edifado kaj ne por deĵetado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Fine, fratoj, adiaŭ. Perfektiĝu, konsoliĝu, estu unuanimaj, vivu pace; kaj la Dio de amo kaj paco estos ĉe vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Salutu unu la alian per sankta kiso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Ĉiuj sanktuloj vin salutas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, 'La graco de la Sinjoro Jesuo Kristo kaj la amo de Dio kaj la kuneco de la Sankta Spirito estu kun vi ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Paŭlo, apostolo (ne de homoj, nek per homo, sed per Jesuo Kristo, kaj Dio, la Patro, kiu levis lin el la mortintoj),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'kaj ĉiuj fratoj, kiuj estas kun mi, al la eklezioj de Galatujo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Graco al vi kaj paco de Dio, la Patro, kaj de nia Sinjoro Jesuo Kristo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'kiu sin donis pro niaj pekoj, por liberigi nin el la nuna malbona mondo, laŭ la volo de nia Dio kaj Patro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'al kiu estu la gloro por ĉiam kaj eterne. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Mi miras, ke tiel rapide vi foriĝas for de Tiu, kiu vokis vin en la gracon de Kristo, al malsama evangelio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'kiu ja ne estas alia, sed troviĝas iuj, kiuj vin maltrankviligas kaj deziras renversi la evangelion de Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Tamen se eĉ ni, aŭ anĝelo el la ĉielo, al vi instruus ian evangelion krom tiu, kiun ni jam al vi instruis, tiu estu anatemita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Kiel ni antaŭe diris, tiel nun mi denove diras: Se iu al vi instruas ian evangelion krom tiu, kiun vi ricevis, tiu estu anatemita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Ĉar ĉu mi nun influas homojn, aŭ Dion? aŭ ĉu mi celas plaĉi al homoj? se mi ankoraŭ nun plaĉus al homoj, mi ne estus servisto de Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Ĉar mi sciigas vin, fratoj, rilate al la evangelio predikita de mi, ke ĝi ne estas laŭ homo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Ĉar mi ne ricevis ĝin de homo, kaj ĝi ne estas instruita al mi krom per malkaŝo de Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Ĉar vi iam aŭdis pri mia estinta vivmaniero en Judismo, ke mi forte persekutis la eklezion de Dio kaj ĝin atakis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'kaj mi plimulte progresis en Judismo, ol multaj miaj samaĝuloj en mia nacio, estante multe pli fervoranima pri la tradicioj de miaj prapatroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Sed kiam bonvole plaĉis al Dio, kiu el la ventro de mia patrino apartigis min kaj per Sia graco min vokis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'por malkaŝi en mi Sian Filon, por ke mi prediku lin inter la nacianoj: mi ne konsiliĝis kun karno kaj sango,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'kaj mi ne supreniris al Jerusalem, al la antaŭ mi apostoloj, sed mi tuj foriris en Arabujon, kaj poste mi revenis al Damasko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Tiam, post tri jaroj, mi supreniris al Jerusalem, por viziti Kefason, kaj mi restis kun li dek kvin tagojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Sed neniun alian el la apostoloj mi vidis, krom Jakobo, la frato de la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Pri tio, kion mi skribas al vi, jen, antaŭ Dio, mi ne mensogas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Poste mi venis en la regionojn de Sirio kaj Kilikio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Kaj mi ankoraŭ estis vizaĝe nekonata de la eklezioj de Judujo, kiuj estis en Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'sed ili nur aŭdis la jenon: Kiu nin iam persekutis, tiu nun predikas la fidon, kiun iam li atakis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'kaj ili gloris Dion en mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Tiam, post intertempo de dek kvar jaroj, mi denove supreniris al Jerusalem kun Barnabas, kunkondukante ankaŭ Titon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Kaj mi supreniris laŭ Dia malkaŝo; kaj mi prezentis al ili la evangelion, kiun mi predikas inter la nacianoj, sed aparte al la eminentuloj, por ke mi ne estu vane kuranta, aŭ kurinta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Sed eĉ Titon, kiu estis kun mi, estante Greko, oni ne devigis cirkumcidiĝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'sed tio estis pro la kaŝe enportitaj fratoj, kiuj ruze envenis, por spioni nian liberecon en Kristo Jesuo, por ke ili nin sklavigu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'al kiuj ni ne submetiĝis cedeme, eĉ por unu horo; por ke la vero de la evangelio restadu kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Sed el tiuj, kiuj ŝajne iom valoris (kiaj ajn ili estis, tio por mi ne estas grava: ĉe Dio ne estas personfavorado) -tiuj valoruloj nenion aldonis al mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'sed kontraŭe, kiam ili vidis, ke je la evangelio de la necirkumcido mi estas komisiita tiel same, kiel Petro je la evangelio de la cirkumcido');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '(ĉar Tiu, kiu forte energiis en Petro por la apostoleco de la cirkumcido, ankaŭ energiis en mi por la nacianoj),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'Jakobo kaj Kefas kaj Johano, kiuj ŝajne estis kolonoj, rimarkinte la gracon donitan al mi, donis al mi kaj al Barnabas la dekstrajn manojn de kunuleco, por ke ni iru al la nacianoj, kaj ili al la cirkumcidularo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'kondiĉe nur, ke ni memoru la malriĉulojn, kion ja mi klopodis jam fari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Sed kiam venis Kefas al Antioĥia, mi lin rezistis vizaĝon kontraŭ vizaĝo, ĉar li estis mallaŭdinda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Ĉar antaŭ ol iuj alvenis de Jakobo, li kunmanĝis kun la nacianoj; sed kiam ili alvenis, li sin fortiris kaj apartigis, timante tiujn, kiuj estis el la cirkumcido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'Kaj la aliaj Judoj kune hipokritis, tiel ke eĉ Barnabas mem fortiriĝis per ilia hipokriteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Kaj kiam mi vidis, ke ili ne prave kondutas laŭ la vero de la evangelio, mi diris al Kefas antaŭ ĉiuj: Se vi, estante Judo, naciane vivas, kaj ne kiel Judoj, kial vi devigas la nacianojn agi laŭ Judismo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Ni, nature Judoj, kaj ne pekuloj el la nacianoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'sciante, ke praviĝas homo ne per faroj de la leĝo, sed nur per fido al Jesuo Kristo, ni mem en Kristo Jesuo kredis, por ke ni praviĝu per fido al Kristo, kaj ne per faroj de la leĝo; tial, ke per faroj de la leĝo neniu karno praviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Sed se, dezirante praviĝi en Kristo, ni mem montriĝis pekuloj, ĉu Kristo estas servanto de peko? Nepre ne!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Ĉar se mi rekonstruas tion, kion mi detruis, mi montras min pekulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Ĉar per la leĝo mi al la leĝo mortis, por ke mi al Dio vivu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Kun Kristo mi krucumiĝis, tamen mi vivas; jam ne mi mem, sed Kristo vivas en mi; kaj tiun vivon, kiun mi vivas en karno, mi vivas en fido al la Filo de Dio, kiu min amis kaj sin donis pro mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Mi ne vanigas la gracon de Dio; ĉar se per la leĝo venas justeco, Kristo ja vane mortis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'Ho malsaĝaj Galatoj, kiu vin ensorĉis? vin, antaŭ kies okuloj Kristo Jesuo estis publike prezentita krucumita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Nur la jenon mi deziras sciiĝi de vi: Ĉu per faroj de la leĝo vi ricevis la Spiriton, aŭ per la aŭdado de fido?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Ĉu vi tiel malsaĝaj estas? komencinte en Spirito, ĉu vi en karno nun perfektiĝas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Ĉu vi vane tiom suferis? se ja tio estas vana.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Ĉu do Tiu, kiu donas al vi la Spiriton kaj faras ĉe vi miraklojn, tion faras per faroj de la leĝo, aŭ per la aŭdado de fido?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Tiel same, kiel Abraham kredis al Dio, kaj tio estis kalkulita al li kiel virto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Sciu do, ke tiuj, kiuj rilatas al fido, estas filoj de Abraham.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'Antaŭvidante do, ke per fido Dio pravigos la nacianojn, la Skribo antaŭpredikis la evangelion al Abraham, dirante: Beniĝos per vi ĉiuj gentoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Tial do tiuj, kiuj rilatas al fido, beniĝas kun la fidela Abraham.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Ĉar ĉiuj, kiuj rilatas al faroj de la leĝo, estas sub malbeno; ĉar estas skribite: Malbenita estas ĉiu, kiu ne persistos en ĉio, kio estas skribita en la libro de la leĝo, por plenumi ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Sed ke neniu praviĝas antaŭ Dio per la leĝo, estas evidente; ĉar: La virtulo vivos per fido;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'kaj la leĝo ne rilatas al fido; sed: Kiu plenumas ilin, tiu vivos en ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Kristo elaĉetis nin el la malbeno de la leĝo, fariĝinte malbeno pro ni; ĉar estas skribite: Malbenita estas ĉiu, kiu pendas sur lignaĵo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'por ke venu sur la nacianojn la beno de Abraham en Kristo Jesuo; por ke per fido ni ricevu la promeson de la Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Fratoj, mi parolas laŭ homo: Konfirmitan interligon, eĉ nur homan, neniu nuligas nek prialdonas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Sed al Abraham kaj al lia semo la promesoj estis parolitaj. Li ne diras: Kaj al semoj, kvazaŭ pri multaj; sed kvazaŭ unu: Kaj al via semo, kiu estas Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Sed jen kion mi diras: Interligon, antaŭe konfirmitan de Dio, la leĝo, kiu venis kvarcent tridek jarojn poste, ne nuligas, tiel ke ĝi malefektivigus la promeson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Ĉar se la heredaĵo estas de la leĝo, ĝi jam ne estas de promeso; sed Dio ĝin donis al Abraham per promeso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Kio do estas la leĝo? Ĝi estis aldonita kaŭze de eraroj, ĝis venos la idaro, al kiu la promeso estas donita; ordigite per anĝeloj en la mano de interulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Interulo ne estas de unu, sed Dio estas unu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Ĉu do la leĝo kontraŭstaras al la promesoj de Dio? Nepre ne! ĉar se estus donita leĝo, kiu povus vivigi, efektive justeco estus per la leĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Tamen la Skribo kune enŝlosis ĉion sub peko, por ke la promeso per fido al Kristo Jesuo estu donata al ĉiuj, kiuj fidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Sed antaŭ ol fido venis, ni estis gardataj sub la leĝo, enŝlositaj por la fido malkaŝota.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'Tial la leĝo fariĝis nia pedagogo, kondukanta al Kristo, por ke ni praviĝu per fido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Sed nun, post kiam la fido alvenis, ni jam ne estas sub pedagogo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Ĉar vi ĉiuj per la fido estas filoj de Dio en Kristo Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Ĉar ĉiuj el vi, kiuj al Kristo baptiĝis, surmetis al si Kriston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Ne estas ja Judo nek Greko, ne estas sklavo nek liberulo, ne estas ja vira kaj virina; ĉar vi ĉiuj estas unu en Kristo Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'Se do vi apartenas al Kristo, vere vi estas la idaro de Abraham, kaj heredantoj laŭ la promeso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Kaj mi sciigas vin, ke tiel longe, kiel la heredanto estas infano, li neniel malsimilas sklavon, kvankam li estas estro de ĉio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'sed li estas sub guvernantoj kaj administrantoj, ĝis la templimo difinita de la patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Tiel ankaŭ ni, dum ni estis infanoj, estis en sklaveco sub la elementoj de la mondo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'sed kiam venis la pleneco de la tempo, Dio elsendis Sian Filon, el virino naskitan, sub leĝo naskitan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'por reaĉeti tiujn, kiuj estas sub la leĝo, por ke ni ricevu la filadopton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'Kaj ĉar vi estas filoj, Dio elsendis la Spiriton de Sia Filo en niajn korojn, kriantan, Aba, Patro!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'Tiel ke ĉiu el vi estas jam ne sklavo, sed filo; kaj se filo, ankaŭ heredanto per Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Tamen, tiam ne konante Dion, vi estis en sklaveco al tiuj, kiuj nature ne estas dioj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'sed jam nun konante Dion, aŭ pli ĝuste, de Dio konate, kial vi returniĝas al la malfortaj kaj mizeraj elementoj, al kiuj vi deziras denove sklaviĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Vi observas tagojn kaj monatojn kaj tempojn kaj jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Mi timas pri vi, ke eble mi vane laboris ĉe vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Mi petegas vin, fratoj, estu kiel mi, ĉar mi ankaŭ estas kiel vi. Vi neniel al mi malbonfaris;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'sed vi scias, ke pro malforteco de la karno mi la unuan fojon predikis al vi la evangelion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'kaj vian elprovon en mia karno vi ne malestimis nek abomenis, sed kvazaŭ anĝelon de Dio vi akceptis min, kvazaŭ Kriston Jesuon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Kie do estas via singratulado? mi atestas al vi, ke se estus eble, vi estus elŝirintaj viajn okulojn kaj donintaj ilin al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Ĉu mi do per verdirado fariĝis al vi malamiko?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Ili fervore serĉas vin, ne bone; ili eĉ volas elŝlosi vin, por ke vi serĉu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Sed estas bone esti fervore serĉata ĉiam en bona afero, kaj ne nur tiam, kiam mi estas ĉe vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Miaj infanetoj, pro kiuj mi denove suferas naskodoloron, ĝis Kristo formiĝos en vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'mi tute deziris esti ĉe vi nun, kaj ŝanĝi mian voĉon; ĉar vere mi dubas pri vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Diru al mi, vi, kiuj volas esti sub la leĝo, ĉu vi ne aŭskultas la leĝon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Ĉar estas skribite, ke Abraham havis du filojn, unu el la sklavino kaj unu el la liberulino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Tamen tiu el la sklavino naskiĝis laŭ la karno, sed ĉi tiu el la liberulino naskiĝis per promeso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Ĉi tio enhavas alegorion; ĉar la du virinoj estas du interligoj, unu el la monto Sinaj, por sklaveco naskante, kiu estas Hagar.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Ĉar tiu Hagar estas la monto Sinaj en Arabujo, kaj prezentas la nunan Jerusalemon, ĉar ŝi estas sklavigita kune kun siaj infanoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Sed la supera Jerusalem estas libera, kiu estas patrino nia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Estas ja skribite: Ĝoju, ho senfruktulino, kiu ne naskis, Sonigu kanton kaj ĝojkriu, ho vi, kiu ne suferas naskodoloron; Ĉar la forlasitino havos pli da infanoj, ol la havanta edzon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Sed ni, fratoj, estas filoj de promeso tiel same, kiel Isaak.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Sed kiel tiam la laŭ karno naskita persekutis la laŭspiritulon, tiel estas ankaŭ nuntempe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Sed kion diras la Skribo? Forpelu la sklavinon kaj ŝian filon; ĉar la filo de la sklavino ne heredos kun la filo de la liberulino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'Tial, fratoj, ni estas filoj ne de sklavino, sed de la liberulino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Por libereco Kristo nin liberigis; tial staru fortike, kaj ne reimplikiĝu en jugon de sklaveco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Jen mi, Paŭlo, diras al vi, ke, se vi cirkumcidiĝos, Kristo al vi tute ne utilos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'Mi denove atestas al ĉiu homo cirkumcidata, ke li estas ŝuldanto, por plenumi la tutan leĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Vi, kiuj volas vin pravigi per la leĝo, apartiĝis for de Kristo; vi forfalis de graco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Ĉar ni en la Spirito atendas la esperon de justeco per la fido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Ĉar en Kristo Jesuo nek cirkumcido nek necirkumcido valoras ion, sed nur fido, energianta per amo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Vi bone kuradis; kiu vin malhelpis, ke vi ne obeu la veron?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Ĉi tiu influo ne venas de tiu, kiu vin vokas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Malmulto da fermentaĵo fermentigas la tutan mason.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Mi fidas pri vi en la Sinjoro, ke vi ne alie sentados; sed tiu, kiu malkvietigas vin, elportos sian propran juĝon, kiu ajn li estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Sed mi, fratoj, se mi ankoraŭ predikas cirkumcidon, kial mi estas ankoraŭ persekutata? tiuokaze la falpuŝilo de la kruco estas formovita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Mi volus, ke tiuj, kiuj vin maltrankviligas, sin fortranĉu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Ĉar vi, fratoj, estas vokitaj al libereco; tamen ne uzu vian liberecon kiel pretekston por la karno, sed per amo servu unu la alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Ĉar la tuta leĝo estas plenumata en unu diro, jene: Amu vian proksimulon kiel vin mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Sed se vi mordas kaj manĝegas unu la alian, gardu vin, ke vi ne estu detruitaj unu de la alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Sed mi diras: Iradu laŭ la Spirito, kaj la deziregon de la karno vi ne plenumos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Ĉar la karno deziregas kontraŭ la Spirito, kaj la Spirito kontraŭ la karno; ĉar ĉi ĉiuj interbatalas reciproke, por ke vi ne faru tion, kion vi volas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Sed se vi estas kondukataj de la Sinjoro, vi jam ne estas sub la leĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'Evidentaj estas la faroj de la karno, kiuj estas malĉasteco, malpureco, voluptemo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'idolkulto, sorĉado, malamikeco, malpaco, ĵaluzoj, koleregoj, partiemeco, skismoj, herezoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'envioj, ebrieco, diboĉado, kaj aliaj similaj; pri kiuj mi avertas vin, kiel mi jam antaŭe admonis vin, ke tiuj, kiuj tion faradas, ne heredos la regnon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Sed la frukto de la Spirito estas amo, ĝojo, paco, pacienco, komplezo, bonkoreco, fideleco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'mildeco, sinregado; kontraŭ tiaj ne ekzistas leĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Kaj tiuj, kiuj apartenas al Kristo Jesuo, jam krucumis la karnon kun ĝiaj pasioj kaj voluptoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Se ni vivas per la Spirito, en la Spirito ni ankaŭ iradu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Ni ne fariĝu fanfaronemaj, incitante kaj enviante unu la alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Fratoj, eĉ se homo estos trovita en ia kulpo, vi, kiuj estas spiritaj, restarigu tiun per spirito de mildeco; rigardante vin, ĉiu sin mem, por ke vi ne estu tentataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Reciproke subtenadu viajn ŝarĝojn, kaj tiamaniere plenumu la leĝon de Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Ĉar, se iu, estante nenio, sin estimas, kvazaŭ li estas io, li sin trompas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Sed ĉiu kontrolu sian propran faradon, kaj tiam li havos singratuladon pri si mem, kaj ne pri sia proksimulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'Ĉar ĉiu devas subteni sian propran portaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'Tiu, kiu estas instruata en la parolo de Dio, partoprenu kun tiu, kiu lin instruas, en ĉiuj bonaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Ne trompiĝu; Dio ne estas mokata; ĉar ĉion, kion oni semas, tion ankaŭ li rikoltos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Ĉar kiu semas por sia karno, el la karno tiu rikoltos putradon; sed kiu semas por la Spirito, el la Spirito tiu rikoltos eternan vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'Kaj ni ne laciĝu en bonfarado; ĉar ĝustatempe ni rikoltos, se ni ne senfortiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Tial laŭ nia oportuna tempo ni bonfaradu al ĉiuj, precipe al tiuj, kiuj apartenas al la familio de la fido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Vidu, per kiaj grandaj literoj mi skribis al vi propramane.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Kiuj deziras sin paradi per la karno, tiuj devigas vin cirkumcidiĝi; sole por ke ili ne estu persekutataj pro la kruco de Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Ĉar eĉ tiuj mem, kiuj cirkumcidiĝas, ne observas la leĝon; sed ili deziras, ke vi cirkumcidiĝu, por ke ili fanfaronu pri via karno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Sed por mi ne estu fanfarono krom pri la kruco de nia Sinjoro Jesuo Kristo, per kiu la mondo estas krucumita al mi, kaj mi al la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Ĉar nek cirkumcido nek necirkumcido estas io, sed nova kreitaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'Kaj kiuj irados laŭ tiu regulo, paco kaj kompato estu sur ili ĉiuj, kaj sur la Izrael de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'De nun neniu min ĝenu, ĉar mi portas en mia korpo la signojn de Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'La graco de nia Sinjoro Jesuo Kristo estu kun via spirito, fratoj. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Paŭlo, apostolo de Jesuo Kristo per la volo de Dio, al la sanktuloj, kiuj estas en Efeso, kaj al la fideluloj en Kristo Jesuo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Graco estu al vi kaj paco de Dio, nia Patro, kaj de la Sinjoro Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Benata estu la Dio kaj Patro de nia Sinjoro Jesuo Kristo, kiu benis nin per ĉia beno spirita en la ĉielejoj en Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'kiel Li elektis nin en li antaŭ la fondo de la mondo, por ke ni estu sanktaj kaj senmakulaj antaŭ Li en amo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'antaŭdestininte nin por filadopto per Jesuo Kristo al Si mem, laŭ la aprobo de Sia volo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'al la laŭdo de la gloro de Lia graco, per kiu Li favoris nin en la Amata;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'en kiu ni havas la elaĉeton per lia sango, la pardonon de niaj pekoj, laŭ la riĉo de lia graco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'kiun li abundigis al ni en ĉia saĝeco kaj prudento,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'sciiginte al ni la misteron de Lia volo, laŭ Lia bonvolo, kiun Li antaŭdecidis en li,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'por dispono en la pleneco de la tempo, por sumigi en Kristo ĉion, kio estas en la ĉieloj kaj sur la tero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'en li, en kiu ni fariĝis heredaĵo, destinite laŭ la antaŭdecido de Tiu, kiu ĉion faras laŭ la intenco de Sia volo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'por ke ni estu por la laŭdo de Lia gloro, ni, kiuj antaŭe esperis en Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'en kiu vi ankaŭ esperas, aŭdinte la vorton de la vero, la evangelion de via savo; al kiu ankaŭ kredinte, vi estas sigelitaj per la Sankta Spirito de promeso,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'kiu estas antaŭgarantiaĵo de nia heredaĵo, por la elaĉeto de la posedaĵo, por laŭdo de Lia gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Pro tio mi ankaŭ, aŭdinte pri via fido al la Sinjoro Jesuo, kaj via amo al ĉiuj sanktuloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'ne ĉesas danki pro vi, vin nomante en miaj preĝoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'por ke la Dio de nia Sinjoro Jesuo Kristo, la Patro de gloro, donu al vi spiriton de saĝeco kaj malkaŝo en la konado de Li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'dum la okuloj de via koro estas lumigataj, por ke vi sciu, kia estas la espero de Lia voko, kaj kia la riĉeco de la gloro de Lia heredaĵo en la sanktuloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'kaj kia la supermezura grandeco de Lia potenco al ni, kiuj kredas, laŭ la energio de la efikeco de Lia forto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'kiun Li faris en Kristo, relevante lin el la mortintoj, kaj sidigante lin dekstre de Li en la ĉieloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'multe super ĉiu reganto kaj aŭtoritato kaj potenco kaj regeco, kaj ĉiu nomo nomata, ne nur en ĉi tiu mondo, sed ankaŭ en la estonta;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'kaj ĉion Li metis sub liajn piedojn, kaj donis lin kiel kapon super ĉio por la eklezio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'kiu estas lia korpo, la pleneco de Tiu, kiu plenigas ĉion en ĉio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Kaj vin li vivigis, kiam vi estis malvivaj per eraroj kaj pekoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'en kiuj vi iam iradis laŭ la vojo de ĉi tiu mondo, laŭ la estro de la potenco de la aero, de la spirito, kiu nun energias en la filoj de malobeo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'inter kiuj ni ĉiuj iam ankaŭ vivis, plenumante la dezirojn de nia karno, farante la volojn de la karno kaj de la menso, kaj ni estis laŭ naturo infanoj de kolerego, kiel ankaŭ la aliaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Sed Dio, estante riĉa en kompateco, pro Sia granda amo, per kiu Li amis nin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'eĉ kiam ni estis malvivaj en niaj eraroj, nin vivigis en Kristo (per graco vi saviĝis),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'kaj nin levis, kaj nin kunsidigis en la ĉielejoj en Kristo Jesuo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'por montri en la mondaĝoj estontaj la superabundan riĉecon de Sia graco en korfavoro al ni en Kristo Jesuo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'ĉar per graco vi saviĝis per fido; ne per vi mem: ĝi estas dono de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'ne el faroj, por ke neniu fanfaronu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Ĉar ni estas Lia faritaĵo, kreitaj en Kristo Jesuo por bonaj faroj, kiujn antaŭaranĝis Dio, por ke ni iradu en ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Kaj pro tio rememoru, ke iam vi, nacianoj laŭ la karno, nomataj la Necirkumcido ĉe la tiel nomata Cirkumcido, mane farita sur la karno-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'ke vi estis tiam sen Kristo, fremdigitaj for de la komunumo de Izrael, kaj eksteruloj de la interligoj de la promeso, esperon ne havantaj kaj sen Dio en la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Sed nun en Kristo Jesuo vi, iam malproksimaj, proksimiĝis en la sango de Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Ĉar nia paco estas li, kiu unuigis ambaŭ kaj rompis la intermuron de disigo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'en sia karno neniiginte la malamon, la leĝon de ordonoj en dekretoj; por krei en si el la du unu novan homon, tiel farante pacon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'kaj por kunakordigi ambaŭ en unu korpo al Dio per la kruco, mortiginte per tio la malamon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'kaj li venis kaj predikis pacon al vi malproksimaj kaj al la proksimaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'ĉar per li ni ambaŭ havas en unu Spirito alkondukon al la Patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Sekve vi jam estas ne fremduloj kaj pasloĝantoj, sed samregnanoj kun la sanktuloj, kaj el la domanaro de Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'konstruitaj sur la fundamento de la apostoloj kaj profetoj, kies bazangula ŝtono estas Kristo Jesuo mem;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'en kiu ĉiu aparta konstruaĵo, bone kunigita, kreske fariĝas sankta templo en Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'en kiu vi ankaŭ estas kunkonstruitaj por sanktejo de Dio en la Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Pro tio mi, Paŭlo, malliberulo de Kristo Jesuo por vi nacianoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'se vi aŭdis pri la dispono de tiu graco de Dio, kiu estas donita al mi por vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'ke per malkaŝo la mistero estas sciigita al mi, kiel mi jam antaŭe mallonge skribis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'per kio vi povas rimarki, dum vi legas, mian komprenon en la mistero de Kristo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'kiu en aliaj generacioj ne estis sciigita al la homidoj, kiel ĝi nun malkaŝiĝis al liaj sanktaj apostoloj kaj profetoj en la Spirito,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'ke la nacianoj estas kunheredantoj, kaj samkorpanoj, kaj partoprenantoj en la promeso en Kristo Jesuo per la evangelio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'al kiu mi fariĝis servanto laŭ la dono de la graco de Dio, donita al mi laŭ la energio de Lia potenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Al mi, kiu estas malpli ol la malplej granda el ĉiuj sanktuloj, ĉi tiu graco estas donita, por ke mi prediku inter la nacioj la neesploreblan riĉon de Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'kaj por ke mi klarigu al ĉiuj, kia estas la dispono de la mistero kaŝita tra ĉiuj mondaĝoj en Dio, kiu kreis ĉion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'por ke nun konatiĝu al la regantoj kaj aŭtoritatoj en la ĉielejoj, per la eklezio, la multobla saĝeco de Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'laŭ la eterna decido, kiun Li faris en Kristo Jesuo, nia Sinjoro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'en kiu ni havas kuraĝon kaj alkondukon en fidado per nia fido al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Pro tio mi petas, ke vi ne senfortiĝu pro miaj suferoj por vi, kiuj estas via gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Pro tio mi fleksas miajn genuojn antaŭ la Patro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'el kiu ĉiu familio, en la ĉielo kaj sur la tero, estas nomata,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'por ke Li donu al vi, laŭ la riĉo de Sia gloro, ke vi estu potence fortigitaj en la interna homo, per Lia Spirito;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'por ke Kristo loĝu per fido en viaj koroj; tiel, ke vi, enradikigite kaj bazite en amo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'kapabliĝu kun ĉiuj sanktuloj kompreni, kio estas la larĝeco kaj longeco kaj alteco kaj profundeco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'kaj scii la amon de Kristo, kiu superas scion, por ke vi pleniĝu eĉ ĝis la pleneco de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Nun al Tiu, kiu povas tre abunde fari, super ĉio, kion ni povas peti aŭ pensi, laŭ la potenco, kiu energias en ni,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'estu gloro en la eklezio kaj en Kristo Jesuo ĝis ĉiuj generacioj por ĉiam kaj eterne. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Mi do, malliberulo pro la Sinjoro, petegas vin, ke vi iradu inde je la voko, en kiu vi estas vokitaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'kun ĉia humileco kaj mildeco, kun toleremeco, paciencante unu al alia en amo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'penante konservi la unuecon de la Spirito en la ligilo de paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Estas unu korpo, kaj unu Spirito, kiel ankaŭ vi estas vokitaj en unu espero de via voko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'unu Sinjoro, unu fido, unu bapto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'unu Dio kaj Patro de ĉiuj, kiu estas super ĉiuj, kaj tra ĉiuj, kaj en ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Sed al ĉiu el ni la graco estas donita, laŭ la mezuro de la dono de Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Tial li diras: Kiam li supreniris alten, li alkondukis kaptitojn, Kaj donis donacojn al homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, '(Ĉi tio do: Li supreniris-kio ĝi estas krom tio, ke li ankaŭ antaŭe malsupreniris ĝis la profundaĵoj de la tero?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'La malsuprenirinto-tiu sama estis la suprenirinto alte super ĉiuj ĉieloj, por plenigi ĉion.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'Kaj unujn li donis por esti apostoloj; aliajn, profetoj; aliajn, evangeliistoj; kaj aliajn, paŝtistoj kaj instruistoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'por perfektigo de la sanktuloj, por la laboro de pastrado, por la konstruo de la korpo de Kristo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'ĝis ni ĉiuj atingos la unuecon de la fido kaj de la scio de la Filo de Dio, ĝis la homo perfekta, ĝis la mezuro de la matureco de la pleneco de Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'por ke ni jam ne estu infanoj, onde ĵetataj kaj ĉirkaŭpelataj de ĉiu vento de doktrino, per ĵonglado de homoj, per ruzo laŭ artifiko de trompo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'sed parolante la veron en amo, ni ĉiel kreskadu en tiun, kiu estas la kapo, Kristo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'el kiu la tuta korpo, kunigita kaj kunfortikigita tra ĉiu artiko de la livera sistemo, per energio, laŭ la mezuro de ĉiu parto, faras kreskadon de la korpo, por la sinedifado en amo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'La jenon do mi diras, kaj protestas en la Sinjoro, ke vi ne plu iru tiel, kiel iras ankaŭ la nacianoj en la vanteco de siaj mensoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'mallumigitaj en intelekto, fremdigitaj for de la vivo de Dio, pro la nescio, kiu estas en ili, pro la malmoleco de ilia koro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'kiuj, sensentiĝinte, fordonis sin al malĉasteco por la praktikado de ĉia malpureco kun avideco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Sed vi ne tiel lernis Kriston;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'se almenaŭ vi lin aŭdis, kaj en li estis instruitaj, kiel en Jesuo estas vero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'por ke vi formetu, rilate al antaŭa konduto, la malnovan homon, pereeman laŭ trompaj deziroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'kaj renoviĝu rilate al la spirito de via menso,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'kaj surmetu la novan homon, kreitan laŭ Dio en justeco kaj vera sankteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Pro tio, formetante malveron, ĉiu parolu veron kun sia proksimulo, ĉar ni estas membroj unu de alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Koleru kaj ne peku, la suno ne subiru sur via kolero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'ankaŭ ne donu lokon al la diablo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Ŝtelinto ne plu ŝtelu, sed prefere li laboru, farante bonon per siaj manoj, por ke li havu ion por doni al bezonanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'El via buŝo eliru neniu putra vorto, sed nur tio, kio estas bona, por konvena edifado, por ke ĝi donu gracon al la aŭdantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'Kaj ne ĉagrenu la Sanktan Spiriton de Dio, en kiu vi estis sigelitaj al la tago de elaĉeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Ĉia akreco kaj indigno kaj kolero kaj voĉbruado kaj kalumnio estu formetitaj el inter vi, kune kun ĉia malico;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'kaj estu bonfaraj unu al alia, bonkoraj, pardonantaj unu al alia, kiel ankaŭ Dio en Kristo pardonis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Estu do imitantoj de Dio, kiel infanoj amataj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'kaj iradu en amo, kiel Kristo nin amis kaj sin donis pro ni, donaĵon kaj oferaĵon al Dio por agrabla odoraĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Sed malĉasteco kaj ĉia malpureco kaj avideco ne eĉ estu nomataj inter vi, kiel decas por sanktuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'nek ia hontindaĵo, nek sensenca parolado, nek tro libera babilado, kiuj ne konvenas; sed prefere dankesprimo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Ĉar vi ja scias, ke ĉiu malĉastulo kaj malpurulo kaj avidulo, kiu estas idolano, havas nenian heredon en la regno de Kristo kaj Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Neniu vin trompu per vantaj vortoj; ĉar pro tiuj aferoj venas sur la infanojn de malobeo la kolero de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Ne estu do partoprenantoj kun ili;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'ĉar iam vi estis mallumo, sed jam vi estas lumo en la Sinjoro; iru kiel infanoj de lumo');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, '(ĉar la frukto de la lumo estas en ĉia boneco kaj justeco kaj vero),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'provante, kio bone plaĉas al la Sinjoro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'kaj ne partoprenu kun la senfruktaj faroj de mallumo, sed prefere refutu ilin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'ĉar estas hontinde eĉ paroli pri tio, kion ili faras sekrete.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Sed ĉio, kio estas refutata, estas elmontrata per la lumo, ĉar ĉio elmontrata estas lumo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Tial estas dirite: Vekiĝu, dormanto, kaj releviĝu el la mortintoj, kaj Kristo al vi lumos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Zorgu do, ke vi atente iradu, ne kiel malsaĝaj, sed kiel saĝaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'elaĉetante la tempon, ĉar malbonaj estas la tagoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Ne estu do senprudentaj, sed komprenu, kio estas la volo de la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'Kaj ne ebriiĝu per vino, en kio estas diboĉo, sed pleniĝu per la Spirito;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'parolante unu al alia per psalmoj kaj himnoj kaj kantoj spiritaj, kantante kaj psalmante en viaj koroj al la Sinjoro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'dankante Dion, la Patron, ĉiam pro ĉio en la nomo de nia Sinjoro Jesuo Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'submetiĝante unu al alia en la timo al Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Edzinoj, submetiĝu al viaj edzoj tiel same, kiel al la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Ĉar edzo estas kapo de edzino, kiel ankaŭ Kristo estas kapo de la eklezio; kaj li estas la savanto de la korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Sed kiel la eklezio sin submetas al Kristo, tiel ankaŭ edzinoj al edzoj en ĉio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Edzoj, amu viajn edzinojn, kiel Kristo amis la eklezion kaj pro ĝi sin donis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'por ke li sanktigu ĝin per akvolavo, kun la vorto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'por ke li starigu ĝin antaŭ si glora eklezio, ne havanta makulon, nek malglataĵon, nek ion tian, sed por ke ĝi estu sankta kaj sendifekta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Tiel same devas edzoj ami siajn edzinojn kiel siajn proprajn korpojn. Kiu amas sian edzinon, tiu amas sin mem;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'ĉar oni neniam malamas sian propran karnon, sed nutras kaj prizorgas ĝin, kiel ankaŭ la Sinjoro la eklezion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'ĉar ni estas membroj de lia korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'Tial viro forlasos sian patron kaj sian patrinon, kaj aliĝos al sia edzino, kaj ili du estos unu karno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Ĉi tiu mistero estas granda, sed mi parolas pri Kristo kaj la eklezio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Tamen ankaŭ ĉiu el vi individue amu sian edzinon, kiel sin mem; kaj la edzino timu sian edzon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Infanoj, obeu al viaj gepatroj en la Sinjoro, ĉar tio decas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'Respektu vian patron kaj vian patrinon (ĝi estas la unua ordono kun promeso),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'por ke estu al vi bone kaj por ke longe daŭru via vivo sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'Kaj patroj, ne kolerigu viajn infanojn; sed nutradu ilin en la disciplino kaj admono de la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Sklavoj, obeu al tiuj, kiuj laŭ la karno estas viaj sinjoroj, kun timo kaj tremo, en simpleco de via koro, kiel al Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'ne laŭ okulservo, kiel homplaĉantoj, sed kiel sklavoj de Kristo, plenumante el la koro la volon de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'kun bonvoleco servante, kiel al la Sinjoro, kaj ne al homoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'sciante, ke, kian ajn bonon faras ĉiu, ĉu sklavo aŭ liberulo, tion saman li ricevos de la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Kaj sinjoroj, agu tiel same al ili, forlasante minacon; sciante, ke via kaj ilia Sinjoro estas en la ĉielo, kaj ne ekzistas ĉe li personfavorado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Cetere, fortiĝu en la Sinjoro kaj en la forteco de lia potenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Surmetu la tutan armilaron de Dio, por ke vi povu kontraŭstari al la artifikoj de la diablo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Ĉar nia luktado estas ne kontraŭ sango kaj karno, sed kontraŭ regantoj, kontraŭ aŭtoritatoj, kontraŭ mondpotenculoj de la nuna mallumo, kontraŭ la spiritaroj de malbono en la ĉielejoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Tial prenu al vi la tutan armilaron de Dio, por ke vi povu rezisti en la malbona tago, kaj, farinte ĉion, stari.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Staru do, ĉirkaŭzoninte la lumbojn per vero, kaj surmetinte la kirason de justeco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'kaj enŝuiginte la piedojn per la pretiĝo de la evangelio de paco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'super ĉio tenante la ŝildon de fido, per kiu vi povos estingi ĉiujn fajrajn sagojn de la malbonulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'Kaj ricevu la kaskon de savo, kaj la glavon de la Spirito, kiu estas la vorto de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'per ĉia preĝado kaj petegado en ĉiu tempo preĝante en la Spirito, kaj viglante por tio en ĉia persisteco kaj petego por ĉiuj sanktuloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'kaj por mi, ke al mi estu donita parolpovo kun malfermo de mia buŝo, por ke mi sciigu kuraĝe la misteron de la evangelio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'pro kiu mi estas ambasadoro en kateno, por ke mi parolu kuraĝe en ĝi, kiel mi devus paroli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Plue, por ke vi sciiĝu pri miaj aferoj, kiel mi statas, raportos ĉion al vi Tiĥiko, la amata frato kaj fidela diakono en la Sinjoro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'kiun mi sendis al vi ĝuste por tio, ke vi sciiĝu pri nia stato kaj por ke li konsolu viajn korojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Paco estu al la fratoj, kaj amo kun fido de Dio, la Patro, kaj de la Sinjoro Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Graco estu kun ĉiuj, kiuj sendekliniĝe amas nian Sinjoron Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Paŭlo kaj Timoteo, servistoj de Jesuo Kristo, al ĉiuj sanktuloj en Kristo Jesuo, kiuj estas en Filipi, kun la episkopoj kaj diakonoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Graco al vi kaj paco estu de Dio, nia Patro, kaj de la Sinjoro Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Mi dankas mian Dion ĉe ĉiu rememoro pri vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'ĉiam en ĉiu mia preĝo por vi ĉiuj farante la peton kun ĝojo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'pro via partopreno en la evangelio de post la unua tago ĝis nun;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'pri tio mem fidante, ke Tiu, kiu komencis bonan faron ĉe vi, ĝin perfektigados ĝis la tago de Jesuo Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'kaj ja decas, ke mi tion sentu pri vi ĉiuj, ĉar vi havas min en via koro, kaj vi ĉiuj estas kun mi partoprenantoj en la graco, kiel en miaj katenoj, tiel ankaŭ en la defendo kaj fortigado de la evangelio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Ĉar Dio estas mia atestanto, kiel fervore mi sopiras al vi ĉiuj laŭ la koramo de Kristo Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'Kaj mi preĝas, ke via amo abundu ankoraŭ plie kaj plie, en scio kaj ĉia saĝo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'por ke vi aprobu la plej bonajn aferojn kaj estu sinceraj kaj senofendaj ĝis la tago de Kristo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'plenigite de la fruktoj de justeco, kiuj estas per Jesuo Kristo, al la gloro kaj laŭdo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Sed, fratoj, mi volas certigi vin, ke miaj aferoj plie efektiviĝis por la progresado de la evangelio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'tiel, ke miaj katenoj estas evidentigitaj en Kristo tra la tuta Pretorio kaj ĉie aliloke;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'kaj la plimulto el la fratoj en la Sinjoro, pro miaj katenoj fariĝinte sentimaj, supermezure kuraĝas persiste elparoladi la vorton de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Unuj ja proklamas Kriston eĉ envie kaj malpace, sed aliaj bonvole;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'ĉi tiuj kun amo, sciante, ke mi estas metita, por defendi la evangelion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'sed tiuj kun partieco predikas Kriston, ne sincere, supozante, ke ili aldonos doloron al miaj katenoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Kio do? nur tio, ke ĉiamaniere, ĉu pretekste aŭ vere, oni predikas Kriston: kaj pro tio mi ĝojas kaj ankoraŭ plu ĝojos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Ĉar mi scias, ke ĉi tio efikos al mia savo, per viaj preĝoj kaj la provizado de la Spirito de Jesuo Kristo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'laŭ mia fervora atendado kaj espero, ke mi pri nenio hontiĝos, sed ke per ĉia liberparolo, kiel ĉiam, tiel ankaŭ nun, Kristo estos glorata en mia korpo, ĉu per vivo aŭ per morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Ĉar ĉe mi la vivado estas Kristo, kaj morti estas gajno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Sed se mi vivados korpe, tio signifas pluan frukton de laboro; kaj mi ne scias, kion elekti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Ĉar ambaŭflanke mi estas embarasata, havante deziron foriri kaj esti kun Kristo, kio estas multe pli bona;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'tamen mia restado en la karno estas pli bezona por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'Kaj tiel fidante, mi scias, ke mi restos kaj apudrestados kun vi ĉiuj, por via progreso kaj ĝojo de fido;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'por ke mi pli abunde en Kristo Jesuo gratulu min pri vi, per mia denova ĉeestado kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Sed via vivmaniero nur estu inda je la evangelio de Kristo, por ke, ĉu mi alvenos kaj vin vidos, aŭ forestos, mi aŭdu pri viaj aferoj, ke vi fortike staras unuspirite, kunbatalantaj unuanime por la fido de la evangelio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'kaj neniel timigitaj de la kontraŭuloj: kio estas al ili certa signo de pereo, sed al vi certa signo (nepre de Dio) pri via saviĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'ĉar estas al vi permesite pro Kristo, ne sole kredi al li, sed ankaŭ suferi pro li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'havantaj la saman bataladon, kiun vi vidis ĉe mi, kaj pri kiu vi nun aŭdas, ke ĉe mi ĝi ankoraŭ ekzistas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Se do en Kristo ekzistas ia konsolo, ia simpatio de amo, ia kunuleco de la Spirito, ia korfavoro kaj kompato,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'plenigu mian ĝojon, ke vi tiel same sentu, havante la saman amon, estante unuanimaj, sampensaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'nenion farante malpace aŭ arogante, sed kun humileco rigardante unu la alian kiel pli indan, ol li mem;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'ne atentu ĉiu siajn proprajn aferojn, sed ĉiu ankaŭ la aferojn de aliaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Tiu sama spirito estu en vi, kiu estis ankaŭ en Kristo Jesuo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'kiu, estante en la formo de Dio, ne rigardis kiel ŝatindaĵon la egalecon kun Dio');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'sed sin malplenigis, alprenante la formon de sklavo, fariĝante laŭ la bildo de homoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'kaj troviĝinte laŭfigure kiel homo, li sin humiligis kaj fariĝis obeema ĝis morto, eĉ ĝis la morto per kruco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Pro tio do Dio tre alte superigis lin, kaj donis al li nomon, kiu estas super ĉia nomo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'por ke en la nomo de Jesuo kliniĝu ĉiu genuo, de enĉieluloj kaj surteruloj kaj subteruloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'kaj ĉiu lango konfesu, ke Jesuo Kristo estas Sinjoro, al la gloro de Dio, la Patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Tial, miaj amatoj, kiel vi ĉiam obeis, ne nur dum mia ĉeestado ĉe vi, sed nun eĉ pli multe dum mia forestado, ellaboru kun timo kaj tremo vian propran savon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'ĉar Dio estas Tiu, kiu elfaras en vi la volon kaj la energion laŭ Sia bonvolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Ĉion faru sen murmuroj kaj disputoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'por ke vi estu senkulpaj kaj simplaj, filoj de Dio, neriproĉindaj, meze de perversa kaj malhonesta generacio, inter kiuj vi brilas kiel lumiloj en la mondo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'forte tenante la vorton de la vivo; por ke estu por mi io, pri kio mi povos min gratuli en la tago de Kristo, ke mi ne vane kuris kaj laboris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Cetere, eĉ se mi estas elverŝata sur la oferon kaj servon de via fido, mi ĝojas kaj kunĝojas kun vi ĉiuj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'kaj tiel same vi ankaŭ ĝoju kaj kunĝoju kun mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Sed mi esperas en la Sinjoro Jesuo baldaŭ sendi al vi Timoteon, por ke mi ankaŭ refreŝiĝu, kiam mi certiĝos pri via stato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Ĉar mi havas neniun samsentan, kiu sincere zorgos pri via stato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'Ĉar ĉiu celas siajn aferojn, ne la aferojn de Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Sed vi ja konas lian provadon, ke kiel filo servas al sia patro, tiel li servis kun mi por la evangelio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Lin do mi esperas tuj sendi, kiam mi certiĝos, kio al mi okazos,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'sed mi fidas al la Sinjoro, ke mi mem ankaŭ venos baldaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Tamen ŝajnis al mi necese sendi al vi Epafroditon, mian fraton kaj kunlaboranton kaj kunbatalanton, vian senditon kaj helpanton por mia bezono;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'ĉar li sopiris al vi ĉiuj, kaj forte maltrankviliĝis pro tio, ke vi jam sciiĝis pri lia malsano;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'ĉar efektive li malsanis, preskaŭ ĝis morto; sed Dio kompatis lin, kaj ne sole lin, sed ankaŭ min, por ke mi ne havu malĝojon super malĝojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Mi do sendis lin des pli diligente, por ke, revidante lin, vi ĝoju, kaj ke mi estu sen malĝojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Akceptu lin do en la Sinjoro kun plena ĝojo, kaj tiajn homojn honoru;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'ĉar pro la laboro por Kristo li alproksimiĝis al morto, riskante sian vivon, por kompletigi tion, kio mankis ĉe via servado al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Fine, fratoj, ĝoju en la Sinjoro. Tute ne ĝenas min al vi skribi ripete, kaj por vi tio estas sendanĝeriga.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Gardu vin kontraŭ la hundoj, gardu vin kontraŭ la malbonaguloj, gardu vin kontraŭ la karntranĉuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'ĉar ni estas la cirkumciduloj, kiuj per la Spirito de Dio adoras, kaj nin gratulas pri Kristo Jesuo, kaj ne havas fidon al la karno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'kvankam mi mem povas havi fidon al la karno; se iu alia pretendas fidi la karnon, mi ja pli efektive;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'cirkumcidita la okan tagon, el la raso Izraela, el la tribo de Benjamen, Hebreo el Hebreoj; rilate la leĝon, Fariseo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'rilate fervoron, persekutanto de la eklezio; rilate la justecon, kiu fariĝas per la leĝo, senkulpa.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Sed kio estis al mi gajno, tion mi rigardis kiel malgajnon pro Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Kaj efektive mi rigardas ĉion kiel malgajnon pro la supereco de la scio de Kristo Jesuo, mia Sinjoro, pro kiu mi suferis malgajnon de ĉio, kaj rigardas ĉion kiel rubon, por ke mi gajnu Kriston,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'kaj estu trovata en li, ne havante mian justecon, kiu devenas de la leĝo, sed la justecon, kiu estas per la fido al Kristo, la justecon, kiu devenas de Dio sur fidon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'por ke mi sciu lin kaj la potencon de lia releviĝo kaj la kunulecon en liaj suferoj, konformiĝinte al lia morto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'se mi povos iel atingi la releviĝon el la mortintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Ne kvazaŭ mi jam trafis, aŭ jam perfektiĝis; sed mi min pelas antaŭen, se mi nur povos ekteni tion, pro kio mi estas tenata de Kristo Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Miaj fratoj, mi ne rigardas min kiel jam ektenantan; sed nur jene: forgesante tion, kio estas malantaŭe, kaj strebante al tio, kio estas antaŭe,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'mi min pelas al la celo, por akiri la premion de la supera voko de Dio en Kristo Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Ĉiuj el ni do, kiuj estas perfektaj, tiel pensu; kaj se pri io vi pensas alie, tion ankaŭ Dio malkaŝos al vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'sed ĉiaokaze, laŭ tio, kiom ni jam atingis, ni iradu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Fratoj, estu kunimitantoj de mi; kaj observu tiujn, kiuj tiel iradas, kiel vi havas nin kiel ekzemplon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Ĉar iradas multaj, pri kiuj mi ofte diris al vi, kaj nun eĉ plorante diras, ke ili estas malamikoj de la kruco de Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'ilia fino estas pereo, ilia dio estas la ventro, kaj ilia gloro estas en ilia honto, ili atentas surteraĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Ĉar nia burĝrajto estas en la ĉielo, de kie ankaŭ ni atendas Savonton, la Sinjoron Jesuo Kristo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'kiu denove elformos la korpon de nia humiliĝo, por ke ĝi konformiĝu al la korpo de lia gloro, laŭ la energio, per kiu li eĉ povas ĉion al si submeti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Tial, miaj fratoj amataj kaj alsopirataj, mia ĝojo kaj mia krono, tiel staru fortike en la Sinjoro, miaj amataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Mi admonas Eŭodian, kaj mi admonas Sintiĥen, ke ili estu unuanimaj en la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Kaj mi petegas vin ankaŭ, sincera kunjugulo, helpu tiujn virinojn, ĉar ili kunlaboris kun mi en la evangelio, kune kun Klemento kaj miaj ceteraj kunlaborantoj, kies nomoj estas en la libro de vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Ĝoju en la Sinjoro ĉiam; denove mi diros: Ĝoju.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Via mildeco estu konata al ĉiuj. La Sinjoro estas proksima.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Pri nenio trozorgu; sed pri ĉio, per preĝo kaj peto kun dankesprimo, viaj deziroj sciiĝu al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'Kaj la paco de Dio, kiu superas ĉian intelekton, gardos viajn korojn kaj pensojn en Kristo Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Fine, fratoj, kio ajn estas vera, kio ajn honesta, kio ajn justa, kio ajn ĉasta, kio ajn ŝatinda, kio ajn bonfama; se estas ia virto, se estas ia laŭdo, tion pripensu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Kion vi lernis kaj ricevis kaj aŭdis kaj vidis en mi, tion faru; kaj la Dio de paco estos kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Sed mi forte ĝojas en la Sinjoro, ke vi jam nun revivigis vian zorgon pri mi; vi ja estis zorgemaj, sed mankis al vi oportuna tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Tamen mi ne parolas rilate bezonon; ĉar mi lernis, en kia ajn stato mi estas, en tio esti kontenta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Mi scias humiliĝi, kaj mi scias ankaŭ esti en abundeco; ĉie kaj ĉiel mi lernis la sekreton pleniĝi kaj malsati, havi abundon kaj havi mankon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Mi ĉion povas fari en tiu, kiu min fortikigas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Tamen vi bone agis, partoprenante kun mi en mia suferado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Kaj vi mem, Filipianoj, ankaŭ scias, ke en la komenco de la evangelio, kiam mi foriris el Makedonujo, neniu eklezio komunikiĝis kun mi rilate donadon kaj ricevadon, krom vi solaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'ĉar eĉ en Tesaloniko vi pli ol unufoje sendis ion por mia bezono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Mi ne deziras la donacon; sed mi deziras la frukton, kiu plimultiĝos por via profito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Sed mi havas ĉion, kaj estas en abundeco; mi jam pleniĝis, ricevinte per Epafrodito vian senditaĵon, agrablan odoraĵon, oferon akceptindan, kiu plaĉas al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Kaj mia Dio satigos ĉian vian bezonon, laŭ Sia riĉo en gloro en Kristo Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Nun al nia Dio kaj Patro estu gloro por ĉiam kaj eterne. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Salutu ĉiun sanktulon en Kristo Jesuo. La fratoj, kiuj estas kun mi, vin salutas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Ĉiuj sanktuloj vin salutas, precipe tiuj, kiuj estas el la domanaro de Cezaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'La graco de la Sinjoro Jesuo Kristo estu kun via spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Paŭlo, apostolo de Kristo Jesuo per la volo de Dio, kaj Timoteo, nia frato,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'al la sanktuloj kaj fidelaj fratoj en Kristo, kiuj estas en Kolose: Graco al vi kaj paco estu de Dio, nia Patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Ni dankas Dion, la Patron de nia Sinjoro Jesuo Kristo, ĉiam preĝante por vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'aŭdinte pri via fido en Kristo Jesuo kaj pri via amo al ĉiuj sanktuloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'pro la espero konservita por vi en la ĉielo, pri kiu vi jam antaŭe aŭdis en la vorto de la vero de la evangelio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'kiu venis ĝis vi, kiel ankaŭ en la tuta mondo ĝi estas fruktodona kaj kreskanta, kiel ankaŭ en vi de post tiu tago, en kiu vi aŭdis kaj eksciis la gracon de Dio laŭ la vero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'kiel vi lernis de Epafras, nia amata kunservanto, kiu estas fidela diakono de Kristo pro ni,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'kaj kiu ankaŭ sciigis nin pri via amo en la Spirito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Tial ni ankaŭ, de post la tago, en kiu ni tion aŭdis, ne ĉesas preĝi kaj peti por vi, ke vi pleniĝu per la scio de Lia volo en ĉia spirita saĝo kaj prudento,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'por ke vi iradu inde je la Sinjoro, al ĉia plaĉado, en ĉia bona farado fruktodonaj kaj kreskantaj en la scio de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'fortigitaj per ĉia forto laŭ la potenco de Lia gloro, por ĉia pacienco kaj toleremeco kun ĝojo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'dankante la Patron, kiu taŭgigis nin por partopreno en la heredaĵo de la sanktuloj en lumo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'kaj liberigis nin el la potenco de mallumo, kaj transportis nin en la regnon de la Filo de Sia amo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'en kiu ni havas la elaĉeton, la pardonon de pekoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'li estas bildo de la nevidebla Dio, la unuenaskito inter la tuta kreitaro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'ĉar en li kreiĝis ĉio en la ĉielo kaj sur la tero, ĉio videbla kaj nevidebla, ĉu tronoj, ĉu regecoj, ĉu estrecoj, ĉu aŭtoritatoj; ĉio kreiĝis per li, kaj por li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'kaj li estas antaŭ ĉio, kaj en li ĉio ekzistas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'Kaj li estas la kapo de la korpo, la eklezio; kaj li estas la komenco, la unuenaskita el la mortintoj, por ke li fariĝu superulo en ĉio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Ĉar la Patro bonvolis, ke en li la tuta pleneco loĝu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'kaj per li kunakordigi ĉion al Si mem, pacon farinte per la sango de lia kruco; per li ĉion, ĉu sur la tero, ĉu en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Kaj vin, iam fremdigitajn, kaj mense malamikojn en malbonaj faroj, li tamen jam kunakordigis');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'en la korpo de sia karno, per morto, por starigi vin sanktaj kaj senmakulaj kaj neriproĉeblaj antaŭ li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'se efektive vi restas en la fido, fonditaj kaj fiksitaj kaj firmaj en la espero de la evangelio, kiun vi aŭdis, kiu estas predikita tra la tuta kreitaro sub la ĉielo, kaj kies diakono mi, Paŭlo, fariĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Nun mi ĝojas pri miaj suferoj pro vi, kaj plenigas la mankon de la afliktoj de Kristo en mia karno pro lia korpo, kiu estas la eklezio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'kies diakono mi fariĝis laŭ la aranĝo de Dio, donita al mi pro vi, por plenumi la vorton de Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'la misteron, kiu estas kaŝita for de la mondaĝoj kaj de la generacioj, sed nun klarigita al liaj sanktuloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'al kiuj Dio volis sciigi, kia estis la riĉeco de la gloro de ĉi tiu mistero inter la nacianoj; kiu estas Kristo en vi, la espero de gloro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'kaj kiun ni anoncas, admonante ĉiun homon kaj instruante ĉiun homon en ĉia saĝo, por ke ni starigu ĉiun homon perfekta en Kristo Jesuo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'por tiu celo mi ankaŭ laboras, klopodante laŭ lia energio, kiu energias en mi kun potenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Mi volas do, ke vi sciu, kiel grandan klopodon mi havas pro vi, kaj pro tiuj en Laodikea, kaj pro ĉiuj, kiuj ne vidis mian vizaĝon en la karno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'por ke iliaj koroj konsoliĝu, dum ili kunkroĉiĝas en amo, kaj al ĉia riĉeco de la plena certiĝo de kompreno, por ke ili sciu la misteron de Dio, Kriston,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'en kiu estas kaŝitaj ĉiuj trezoroj de saĝeco kaj de scio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Tion mi diras, por ke neniu vin trompu per parola allogeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Ĉar kvankam mi laŭ karno forestas, tamen laŭ spirito mi estas kun vi, ĝojante kaj vidante vian ordon kaj la firmecon de via fido al Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Kiel do vi ricevis Kriston Jesuon, la Sinjoron, tiel vi iradu en li,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'enradikigite kaj konstruite en li, kaj firmigite en la fido, kiel vi estas instruitaj, kun abundo da dankesprimo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Gardu vin, ke neniu prirabu vin per filozofio kaj vanta trompo, laŭ la tradicio de homoj, laŭ la elementoj de la mondo, kaj ne laŭ Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'ĉar en li korpe loĝas la tuta pleneco de la Dieco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'kaj vi estas plenigitaj en li, kiu estas la kapo de ĉia estreco kaj aŭtoritato;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'en kiu ankaŭ vi cirkumcidiĝis per cirkumcido ne manfarita, en la demeto de la korpo de la karno, en la cirkumcido de Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'enterigite kun li en bapto, en kiu ankaŭ vi estas kunlevitaj per la fido al la energio de Dio, kiu lin levis el la mortintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'Kaj vin, kiuj estis malvivaj per viaj eraroj kaj la necirkumcido de via karno, Li vivigis kun li, pardoninte al ni ĉiujn erarojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'elviŝinte la dekreton kontraŭ ni en ordonoj skribitan, kiu estis al ni malfavora, kaj li forprenis ĝin el la mezo, najlinte ĝin al la kruco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'kaj foriginte de si la estrecojn kaj la aŭtoritatojn, parade malkaŝis ilin, triumfante super ili en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Neniu do vin juĝu pri manĝaĵo, aŭ trinkaĵo, aŭ rilate al festo, aŭ novmonato, aŭ sabato;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'kiuj estas ombro de la estontaĵoj, sed la korpo apartenas al Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Neniu forrabu de vi vian premion per memvola humileco kaj kulto de la anĝeloj, entrudante sin en tion, kion li ne vidis, vante blovoŝvelinte per sia karna menso,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'kaj ne tenante sin al la Kapo, el kiu la tuta korpo, per la artikoj kaj ligiloj provizita kaj kunigita, kreskas laŭ la kreskigo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Se vi mortis kun Kristo for de la elementoj de la mondo, kial, kiel vivantaj en la mondo, vi submetiĝas al dekretoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, 'Ne tuŝu, ne gustumu, ne palpu,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'pri ĉio, kio pereas per la uzado, laŭ la ordonoj kaj doktrinoj de homoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'Ĉio tio havas ŝajnon de saĝeco en volokulto kaj humileco kaj severeco rilate al la korpo, sed ne en ia valoro por plensatigo de la karno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Se do vi estas levitaj kun Kristo, serĉu tion, kio estas supre, kie Kristo sidas dekstre de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Atentu tion, kio estas supre, ne surteraĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Ĉar vi mortis, kaj via vivo kaŝiĝis kun Kristo en Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Kiam aperos Kristo, nia vivo, tiam vi ankaŭ kun li aperos en gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Malvivigu do viajn membrojn, kiuj estas sur la tero: malĉastecon, malpurecon, volupton, malbonan deziron, kaj avidecon, kiu estas idolkulto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'pro kio venas la kolero de Dio sur la filojn de malobeo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'en kiuj vi ankaŭ iam iradis, kiam vi vivis en ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Sed nun formetu ankaŭ la jenajn: koleron, pasian indignon, malicon, kalumnion, hontindan parolon el via buŝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'ne mensogu unu al alia, ĉar vi jam formetis la malnovan homon kun liaj agoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'kaj surmetis la novan homon, kiu estas renovigata al scio laŭ la bildo de Tiu, kiu lin kreis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'kie ne povas esti Greko kaj Judo, cirkumcido kaj necirkumcido, barbaro, Skito, sklavo, liberulo, sed Kristo estas ĉio kaj en ĉio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Surmetu do, kiel elektitoj de Dio, sanktaj kaj amataj, koron de kompato, bonkorecon, humilecon, mildecon, toleremecon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'reciproke paciencante kaj pardonante, se iu havas plendon kontraŭ iu; kiel la Sinjoro pardonis vin, tiel vi ankaŭ faru;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'kaj super ĉion tion surmetu amon, kiu estas ligilo de perfekteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Kaj la paco de Kristo prezidu en viaj koroj, al kiu ankaŭ vi estas vokitaj en unu korpo, kaj estu dankemaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'La vorto de Kristo loĝu en vi riĉe, en ĉia saĝeco; kaj instruu kaj admonu unu la alian per psalmoj kaj himnoj kaj spiritaj kantoj, kantante kun graco en viaj koroj al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'Kaj kion ajn vi faras per vorto aŭ ago, faru ĉion en la nomo de la Sinjoro Jesuo, dankante Dion, la Patron, per li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Edzinoj, submetiĝu al viaj edzoj, kiel decas en la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Edzoj, amu viajn edzinojn, kaj ne maldolĉiĝu kontraŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Infanoj, obeu viajn gepatrojn en ĉio, ĉar tio plaĉas al la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Patroj, ne kolerigu viajn infanojn, por ke ili ne senkuraĝiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Sklavoj, obeu en ĉio al la sinjoroj laŭ la karno, ne per okulservo, kiel homplaĉantoj, sed en simpleco de koro, timante la Sinjoron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'kaj kion ajn vi faras, laboru plenanime, kiel por la Sinjoro, kaj ne por homoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'sciante, ke de la Sinjoro vi ricevos la rekompencon de la heredaĵo; ĉar vi servas la Sinjoron Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Sed ĉiu maljuste faranta ricevos returne laŭ sia maljustaĵo, kaj ne ekzistas personfavorado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Sinjoroj, donu al viaj sklavoj justaĵon kaj egalaĵon, sciante, ke vi ankaŭ havas Sinjoron en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'En preĝado persistu, viglante en ĝi kun danko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'preĝante samtempe ankaŭ pro ni, por ke Dio malfermu al ni pordon por la vorto, por paroli la misteron de Kristo, pro kiu mi estas ankaŭ enkatenita;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'por ke mi klarigu ĝin, kiel mi devus paroli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Iradu en saĝeco rilate al la eksteruloj, elaĉetante la tempon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Via parolo estu ĉiam kun graco, spicita per salo, por ke vi sciu, kiel vi devus respondi al ĉiu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Pri ĉiuj miaj aferoj sciigos vin Tiĥiko, la amata frato kaj fidela diakono kaj kunservanto en la Sinjoro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'kiun mi sendis al vi ĝuste por tio, ke vi sciiĝu pri nia farto, kaj ke li konsolu viajn korojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'kune kun Onesimo, la fidela kaj amata frato, kiu estas el vi. Ili sciigos vin pri ĉiuj ĉi tieaj aferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Salutas vin Aristarĥo, mia kunmalliberulo, kaj Marko, kuzo de Barnabas (pri kiu vi ricevis ordonojn: se li venos al vi, akceptu lin),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'kaj Jesu, nomata Justo, kiuj estas el la cirkumcido; tiuj solaj estas miaj kunlaborantoj por la regno de Dio, kiuj estis al mi konsolilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Salutas vin Epafras, kiu estas el vi, servisto de Kristo Jesuo, ĉiam klopodeganta pro vi en siaj preĝoj, por ke vi staru perfektaj kaj konvinkitaj en la tuta volo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Ĉar mi atestas pri li, ke li havas multan fervoron pro vi, kaj pro tiuj, kiuj estas en Laodikea, kaj en Hierapolis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Salutas vin Luko, la amata kuracisto, kaj Demas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Salutu la fratojn en Laodikea, kaj Nimfason, kaj la eklezion en ilia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'Kaj kiam la epistolo estos legita ĉe vi, faru, ke ĝi estu legata ankaŭ en la eklezio en Laodikea; kaj ke vi ankaŭ legu la epistolon el Laodikea.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'Kaj diru al Arĥipo: Zorgu pri la diakoneco, kiun vi ricevis en la Sinjoro, por ke vi plenumu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'La saluto per la propra mano de mi, Paŭlo. Memoru miajn katenojn. Graco estu kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Paŭlo kaj Silvano kaj Timoteo al la eklezio de la Tesalonikanoj en Dio, la Patro, kaj la Sinjoro Jesuo Kristo: Graco al vi kaj paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Ni ĉiam dankas Dion pri vi ĉiuj, memorigante pri vi en niaj preĝoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'memorante senĉese vian laboron de fido kaj penadon de amo kaj paciencon de espero al nia Sinjoro Jesuo Kristo, antaŭ nia Dio kaj Patro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'sciante, fratoj, amataj de Dio, vian elekton,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'ĉar nia evangelio venis al vi ne nur parole, sed ankaŭ kun potenco kaj kun la Sankta Spirito kaj plena certigo; vi scias, kiaj homoj ni ĉe vi montriĝis pro vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'Kaj vi fariĝis imitantoj de ni kaj de la Sinjoro, ricevinte la vorton en multe da aflikto, kun ĝojo de la Sankta Spirito;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'tiel, ke vi fariĝis modelo por ĉiuj kredantoj en Makedonujo kaj en la Aĥaja lando.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Ĉar de vi la vorto de la Sinjoro estas diseĥita ne nur en Makedonujo kaj la Aĥaja lando, sed en ĉiu loko via fido al Dio disvastiĝis, tiel, ke ni ne bezonas diri ion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Ĉar ili mem pri ni rakontas, kian alvenon ni havis ĉe vi; kaj kiel vi vin turnis al Dio for de idoloj, por servi vivantan kaj veran Dion,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'kaj atendi Lian Filon el la ĉielo, la Filon, kiun Li levis el la mortintoj, Jesuon, kiu nin savas de la estonta kolerego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Ĉar vi mem scias, fratoj, ke nia alveno al vi ne montriĝis senfrukta;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'sed suferinte kaj insultite en Filipi, kiel vi scias, ni kuraĝiĝis en nia Dio prediki al vi la evangelion de Dio meze de granda konflikto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Ĉar nia instruado ne devenis de eraro, nek de malpureco, kaj ĝi ne estas kun ruzo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'sed kiel Dio nin aprobis, por konfidi al ni la evangelion, tiel ni parolas, por plaĉi ne al homoj, sed al Dio, kiu esploras niajn korojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Ĉar, kiel vi scias, ni neniam troviĝis kun vortoj flataj, nek kun avideca preteksto (Dio estas atestanto),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'nek celante homan gloron ĉe vi aŭ ĉe iu alia, kvankam ni povis esti al vi ŝarĝaj, kiel apostoloj de Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'Sed ni estis mildaj inter vi, kiel vartistino, fleganta siajn proprajn infanojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'tiel same ni, sentante por vi koran inklinon, volonte tiam dividus kun vi, ne nur la evangelion de Dio, sed ankaŭ niajn proprajn animojn, ĉar vi fariĝis por ni tre karaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Ĉar vi memoras, fratoj, nian penadon kaj laboregon: nokte kaj tage laborante, por ke ni ne fariĝu ŝarĝo por iu el vi, ni predikadis al vi la evangelion de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Vi estas atestantoj, kaj Dio ankaŭ, kiel sankte kaj juste kaj senkulpe ni kondutis ĉe vi kredantoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'kiel vi scias, ke por ĉiu el vi ni estis kiel patro ĉe siaj infanoj, vin admonante kaj kuraĝigante, kaj petegante,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'ke vi iradu inde je Dio, kiu vin vokas en Sian regnon kaj gloron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Pro ĉi tio ankaŭ ni senĉese dankas Dion, ke ricevinte per nia parolo la vorton de Dio, vi akceptis ne la homan vorton, sed, kiel ĝi vere estas, la Dian vorton, kiu ankaŭ energias en vi, kiuj kredas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Ĉar vi, fratoj, fariĝis imitantoj de la eklezioj de Dio en Kristo Jesuo, kiuj estas en Judujo; ĉar tiajn samajn suferojn vi ankaŭ spertis ĉe viaj samlandanoj, kiajn tiuj ĉe la Judoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'kiuj mortigis la Sinjoron Jesuo kaj la profetojn, kaj nin elpelis, kaj ne plaĉas al Dio, kaj estas kontraŭuloj al ĉiuj homoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'ili malhelpis al ni prediki al la nacianoj, por ke ili saviĝu, por kompletigi ĉiam la sumon de siaj pekoj; kaj sur ilin venis la kolero ĝis ekstrema mezuro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Sed, fratoj, ni, senigite je vi dum kelka tempo, persone, ne kore, des pli fervore klopodis vidi vian vizaĝon kun multa sopiro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'ĉar ni deziris veni al vi; mi, Paŭlo, tion deziris pli ol unufoje; sed malhelpis nin Satano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Ĉar kio estas nia espero, aŭ ĝojo, aŭ krono de singratulado? Ĉu ĝi ja ne estas vi, antaŭ nia Sinjoro Jesuo Kristo ĉe lia alveno?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Ĉar vi estas nia gloro kaj nia ĝojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Kiam do ni jam ne povis resti trankvilaj, ni decidis esti lasitaj solaj en Ateno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'kaj ni sendis Timoteon, nian fraton kaj servanton de Dio en la evangelio de Kristo, por firmigi vin kaj konsoli vin pri via fido,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'por ke neniu estu ŝancelita de tiuj afliktoj; ĉar vi mem scias, ke ili apartenas al nia sorto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Ĉar kiam ni estis ĉe vi, ni antaŭdiris al vi, ke ni nepre suferos; kaj tio efektive okazis, kiel vi ja scias.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Pro tio mi ankaŭ, kiam mi jam ne povis resti trankvila, sendis, por ke mi certiĝu pri via fido, pro timo, ke eble la tentanto vin tentis kaj ke nia laboro fariĝos senutila.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Sed kiam Timoteo, ĵus veninte al ni de vi, donis al ni bonajn sciigojn pri via fido kaj via amo, kaj ke vi ĉiam memoras nin bonkore, sopirante vidi nin, kiel ni ankaŭ vin,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'pro tio ni konsoliĝis, fratoj, pri vi, en ĉia nia malĝojo kaj aflikto, per via fido;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'ĉar nun ni vivas, se vi staras firme en la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Ĉar kian dankon ni povas repagi al Dio pri vi, pro la tuta ĝojo, per kiu ni ĝojas pro vi antaŭ Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'nokte kaj tage preĝante fervore, ke ni povu vidi vian vizaĝon kaj perfektigi la mankojn de via fido?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Nia Dio kaj Patro mem kaj nia Sinjoro Jesuo direktu nian vojon al vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'kaj la Sinjoro pligrandigu kaj abundigu ĉe vi la amon de unu al la alia kaj al ĉiuj, kiel ni amas vin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'por ke li faru viajn korojn senkulpaj kaj sanktaj antaŭ nia Dio kaj Patro, ĉe la alveno de nia Sinjoro Jesuo kun ĉiuj liaj sanktuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Fine do, fratoj, ni petegas kaj admonas vin en la Sinjoro Jesuo, ke kiamaniere vi lernis de ni, kiel vi devus iradi kaj plaĉi al Dio (kaj vi ja tiel iradas), tiamaniere vi pli kaj pli abunde agu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Ĉar vi scias, kian admonon ni donis al vi en la Sinjoro Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Ĉar jen estas la volo de Dio, via sanktiĝo, ke vi vin detenu de malĉasteco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'ke ĉiu el vi sciu preni al si sian propran aĵon en sankteco kaj honoro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'ne en la pasio de volupto, kiel la nacianoj, kiuj ne konas Dion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'ke neniu peku kaj trompu sian fraton en ĉi tio; ĉar la Eternulo estas venĝanto en ĉio tio, kiel ankaŭ ni antaŭavertis vin kaj atestis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Ĉar Dio nin vokis ne por malpureco, sed por sanktiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Tiu do, kiu malakceptas, malakceptas ne homon, sed Dion, kiu donas al vi Sian Sanktan Spiriton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Sed pri amo al la frataro, vi ne bezonas, ke oni skribu al vi, ĉar vi mem estas instruitaj de Dio ami unu la alian;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'ĉar vi ja tion faras al ĉiuj fratoj, kiuj estas en la tuta Makedonujo. Sed ni admonas vin, fratoj, ke vi amu pli kaj pli abunde,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'kaj ke vi celu esti kvietaj, kaj fari viajn proprajn aferojn, kaj labori per viaj manoj, ĝuste kiel ni al vi ordonis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'por ke vi iradu konvene antaŭ tiuj, kiuj estas ekstere, kaj por ke nenio al vi manku.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Sed ni ne volas, fratoj, ke vi ne sciu pri tiuj, kiuj endormiĝis; por ke vi ne malĝoju, kiel la ceteraj, kiuj havas nenian esperon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Ĉar se ni kredas, ke Jesuo mortis kaj releviĝis, tiel ankaŭ tiujn, kiuj endormiĝis en Jesuo, Dio venigos kun li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Ĉar ni diras al vi per la vorto de la Sinjoro, ke ni, kiuj estos vivaj, restantaj ĝis la alveno de la Sinjoro, tute ne havos lokon antaŭ la endormiĝintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Ĉar la Sinjoro mem malsupreniros de la ĉielo, kun signalkrio, kun la voĉo de la ĉefanĝelo, kaj kun la trumpeto de Dio; kaj la mortintoj en Kristo leviĝos la unuaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'poste ni, kiuj vivas, ankoraŭ restantaj, estos kune kun ili suprenkaptitaj en la nubojn, por renkonti la Sinjoron en la aero; kaj tiel ni estos por ĉiam kun la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'Tial per tiuj vortoj konsolu unu la alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Sed pri la tempoj kaj okazoj, fratoj, vi ne bezonas, ke oni skribu al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'Ĉar vi mem tute bone scias, ke la tago de la Sinjoro venas, kiel ŝtelisto en la nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Dum oni diras: Paco kaj sendanĝereco, tiam subita detruo venas sur ilin, kiel naskodoloro al gravedulino, kaj ili tute ne forsaviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Sed vi, fratoj, ne estas en mallumo tiel, ke tiu tago vin trafus kiel ŝtelisto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'ĉar vi ĉiuj estas filoj de lumo kaj filoj de la tago; ni ne estas el la nokto, nek el mallumo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'tial ni ne dormu, kiel la ceteraj, sed ni viglu kaj estu sobraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Ĉar kiuj dormas, tiuj dormas en la nokto; kaj kiuj ebriiĝas, tiuj ebriiĝas en la nokto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Sed ĉar ni estas el la tago, ni estu sobraj, surmetante la kirason de fido kaj amo, kaj, kiel kaskon, la esperon de savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Ĉar Dio nin destinis ne al kolero, sed al la ricevo de savado per nia Sinjoro Jesuo Kristo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'kiu mortis por ni, por ke ni vivu kune kun li, ĉu ni maldormos aŭ dormos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Tial admonu vin reciproke kaj edifu unu la alian, kiel ankaŭ vi jam faradas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Sed ni petegas vin, fratoj, koni tiujn, kiuj laboras ĉe vi kaj estras ĉe vi en la Sinjoro kaj vin admonas,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'kaj estimi ilin treege kun amo pro ilia laboro. Estu pacemaj unu kun la alia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Kaj ni petas vin, fratoj, admonu la senordulojn, kuraĝigu la nebravulojn, subtenu la malfortulojn, estu paciencaj kontraŭ ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Zorgu, ke neniu redonu al iu malbonon por malbono; sed ĉiam sekvu tion, kio estas bona, unu por alia kaj por ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Ĝoju ĉiam;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'preĝu senĉese;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'pri ĉio donu dankon; ĉar tia estas la volo de Dio en Kristo Jesuo pri vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Ne estingu la Spiriton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'ne malestimu profetaĵojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'elprovu ĉion; tenu firme tion, kio estas bona;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'detenu vin de ĉia formo de malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'Kaj la Dio de paco vin sanktigu tute; kaj via spirito kaj animo kaj korpo estu plene konservitaj sen kulpo, ĉe la alveno de nia Sinjoro Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Fidela estas Tiu, kiu vin vokas, kiu ankaŭ faros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Fratoj, preĝu por ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Salutu ĉiujn fratojn per sankta kiso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Mi solene petegas vin per la Sinjoro, ke oni legu ĉi tiun epistolon antaŭ la tuta frataro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'La graco de nia Sinjoro Jesuo Kristo estu kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Paŭlo kaj Silvano kaj Timoteo al la eklezio de la Tesalonikanoj en Dio, nia Patro, kaj la Sinjoro Jesuo Kristo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Graco al vi kaj paco de Dio, la Patro, kaj de la Sinjoro Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Ni devas ĉiam danki Dion pro vi, fratoj, kiel estas ja dece, pro tio, ke via fido kreskas treege, kaj abundas via reciproka amo de ĉiu al ĉiu,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'tiel, ke ni mem fanfaronas pri vi en la eklezioj de Dio, pro via pacienco kaj fido sub ĉiuj viaj persekutoj kaj afliktoj, kiujn vi elportadas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'tio estas evidenta signo de la justa juĝo de Dio; por ke vi montriĝu indaj je la regno de Dio, por kiu vi ankaŭ suferas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'ĉar estas justaĵo ĉe Dio redoni afliktojn al tiuj, kiuj vin afliktas,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'kaj al vi, la afliktataj, ripozon kun ni, ĉe la malkaŝiĝo de la Sinjoro Jesuo el la ĉielo kun la anĝeloj de lia potenco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'en flamanta fajro, por venigi venĝon sur tiujn, kiuj ne konas Dion kaj ne obeas al la evangelio de nia Sinjoro Jesuo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'kiuj suferos punadon, eternan detruon de antaŭ la vizaĝo de la Sinjoro kaj de la gloro de lia potenco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'kiam li venos por esti glorata en siaj sanktuloj, kaj esti admirata ĉe ĉiuj, kiuj ekkredis (ĉar nia atestado ĉe vi estis kredata) en tiu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Por tiu celo ni ankaŭ konstante preĝas por vi, ke nia Dio vin trovu indaj je la voko, kaj kun potenco plenumu ĉiun bonvolon de boneco kaj ĉiun laboron de fido;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'por ke la nomo de nia Sinjoro Jesuo estu glorata en vi, kaj vi en li, laŭ la graco de nia Dio kaj la Sinjoro Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Nun ni petegas vin, fratoj, koncerne la alvenon de nia Sinjoro Jesuo Kristo kaj nian alkolektiĝon al li,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'ke vi ne fariĝu facile skueblaj mense, kaj ne konsterniĝu, ĉu per spirito, aŭ per parolo, aŭ per letero ŝajne de ni, kvazaŭ la tago de la Sinjoro jam apudestus;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'neniu vin trompu iamaniere; ĉar nepre antaŭe okazos la apostateco, kaj la homo de peko malkaŝiĝos, la filo de pereo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'kiu kontraŭmetas sin kaj levas sin super ĉion, kion oni nomas Dio aŭ adoras; tiel, ke li sidas en la templo de Dio, elmontrante sin, kvazaŭ li estas Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Ĉu vi ne memoras, ke mi diris tion al vi, dum mi estis kun vi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Kaj nun vi scias, kio malhelpas, por ke li malkaŝiĝu siatempe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Ĉar la mistero de maljusteco jam energias; sed restas ankoraŭ la malhelpanto, ĝis li estos formovita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'Kaj tiam malkaŝiĝos la maljustulo, kiun la Sinjoro Jesuo detruos per la spiro de sia buŝo kaj neniigos per la apero de sia alveno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'tiun, kies alveno estas pro la energio de Satano kun ĉia potenco kaj kun signoj kaj mensogaj mirindaĵoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'kaj kun ĉia trompo de maljusteco por la pereantoj, pro tio, ke ili ne ricevis la amon al la vero por esti savitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'Kaj pro tio Dio sendas al ili energion de eraro, tiel, ke ili kredos mensogon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'por ke estu juĝataj ĉiuj, kiuj ne kredis la veron, sed trovis plezuron en maljusteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Sed ni devas ĉiam danki Dion pro vi, fratoj, amataj de la Sinjoro, pro tio, ke Dio vin elektis de la komenco al savo en la sanktigo de la Spirito kaj kredo al la vero;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'al kiu Li vin vokis per nia evangelio, por la akiro de la gloro de nia Sinjoro Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Tial, fratoj, staru firme, kaj tenu la tradiciojn, kiujn vi lernis ĉu per parolo, aŭ per ia letero nia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Nia Sinjoro Jesuo Kristo mem, kaj Dio, nia Patro, kiu nin amis kaj al ni donis eternan konsolon kaj bonan esperon per graco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'konsolu viajn korojn kaj fortigu ilin por ĉia bona faro kaj vorto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Fine, fratoj, preĝu por ni, ke la vorto de la Sinjoro disvastiĝu kaj estu glorata, kiel ankaŭ ĉe vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'kaj ke ni forsaviĝu de senprudentaj kaj malbonaj homoj; ĉar ne ĉe ĉiuj estas la fido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Sed fidela estas la Sinjoro, kiu vin fortikigos kaj vin defendos kontraŭ la malbonulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Sed ni fidas la Sinjoron rilate vin, ke vi faras kaj faros tion, kion ni ordonas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Kaj la Sinjoro direktu viajn korojn en la amon al Dio kaj en la paciencon de Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Ni ordonas al vi, fratoj, en la nomo de la Sinjoro Jesuo Kristo, ke vi vin apartigu for de ĉiu frato, kiu iradas senorde kaj ne laŭ la tradicio, kiun oni ricevis de ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Ĉar vi mem scias, kiel vi devas nin imiti; ĉar ni ne kondutis senorde inter vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'nek manĝis panon donace de iu, sed per laboro kaj penado, nokte kaj tage laborante, por ke ni ne fariĝu ŝarĝo por iu el vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'ne kvazaŭ ni ne havus tian rajton, sed por estigi nin ekzemplo antaŭ vi, ke vi nin imitu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Ĉar eĉ kiam ni estis ĉe vi, la jenon ni ordonis al vi: Se iu ne volas labori, tiu ankaŭ ne manĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Ĉar ni aŭdas, ke inter vi iradas senorde kelkaj, kiuj tute ne laboras, sed en ĉies aferojn sin enŝovas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Tiajn ni ordonas kaj admonas pro la Sinjoro Jesuo Kristo, ke kviete ili laboru kaj manĝu sian propran panon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Sed vi, fratoj, ne laciĝu en bonfarado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Sed se iu ne obeos al la parolo de ĉi tiu nia epistolo, rimarku tiun, kaj ne estu por li kamaradoj, por ke li hontiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'Tamen ne rigardu lin kiel malamikon, sed admonu lin kiel fraton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'La Sinjoro de paco mem donu al vi pacon ĉiutempe kaj ĉiumaniere. La Sinjoro estu kun vi ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'La saluto de mi, Paŭlo, per mia propra mano, kiu estas la signo en ĉiu epistolo; tiel mi skribas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'La graco de nia Sinjoro Jesuo Kristo estu kun vi ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Paŭlo, apostolo de Kristo Jesuo, laŭ la ordono de Dio, nia Savanto, kaj Kristo Jesuo, nia espero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'al Timoteo, mia vera filo en fido: Graco, kompato, kaj paco de Dio, la Patro, kaj de Kristo Jesuo, nia Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Kiel mi, ekironte en Makedonujon, petis vin resti en Efeso, por ke vi admonu kelkajn homojn, ke ili ne instruu alian doktrinon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'nek atentu fabelojn kaj senfinajn genealogiojn, kiuj naskas diskutojn, pli ol tiun administradon de Dio, kiu estas laŭ la fido-tiel faru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Sed la celo de la admono estas amo el pura koro kaj bona konscienco kaj sincera fido;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'kion maltrafinte, kelkaj homoj sin deturnis al vanta babilado,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'dezirante esti instruistoj de la leĝo, kvankam ili ne komprenas tion, kion ili diras, nek tion, pri kio ili faras aserton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Sed ni scias, ke la leĝo estas bona, se oni ĝin laŭleĝe uzas,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'sciante, ke la leĝo ekzistas ne por justulo, sed por homoj senleĝaj kaj malobeemaj, malpiaj kaj pekemaj, malsanktaj kaj profanaj, por patromortigantoj kaj patrinomortigantoj, hommortigantoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'malĉastuloj kaj viruzaĉantoj, homŝtelistoj, mensogantoj, falseĵurantoj, kaj ĉio ajn alia kontraŭa al la sana doktrino;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'laŭ la konfidita al mi evangelio de la gloro de la benata Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Mi dankas Kriston Jesuon, nian Sinjoron, kiu min kapabligas, tial, ke li trovis min fidela, destinante min al sia servado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'kvankam mi antaŭe estis blasfemanto kaj persekutanto kaj insultanto; tamen mi ricevis kompaton, ĉar mi tion faris nesciante kaj nekredante;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'kaj la graco de nia Sinjoro abunde sufiĉegis kun fido kaj amo, kiuj estas en Kristo Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Fidinda estas la diro, kaj inda je plena akcepto, ke Kristo Jesuo envenis en la mondon, por savi pekantojn, el kiuj mi estas la ĉefa;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'tamen pro tiu kaŭzo mi ricevis kompaton, por ke en mi, kiel la ĉefa, Jesuo Kristo elmontru sian tutan paciencegon, kiel ekzemplo por tiuj, kiuj poste kredos al li por eterna vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Nun al la Reĝo eterna, senmorta, nevidebla, la sola Dio, estu honoro kaj gloro por ĉiam kaj eterne. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Ĉi tiun zorgadon mi komisias al vi, mia filo Timoteo, laŭ la profetaĵoj, kiuj antaŭiris sur vin, ke per ili vi militadu la bonan militon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'tenante la fidon kaj bonan konsciencon, kiun forpuŝinte de si, kelkaj homoj ŝippereis rilate la fidon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'el kiuj estas Himeneo kaj Aleksandro, kiujn mi transdonis al Satano, por ke ili lernu ne blasfemi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Mi konsilas do, antaŭ ĉio, fari petegojn, preĝojn, propetadojn, dankojn por ĉiuj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'por reĝoj kaj ĉiuj eminentuloj, por ke ni vivadu trankvile kaj kviete en plena pieco kaj seriozeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Tio estas bona kaj akceptebla antaŭ Dio, nia Savanto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'kiu volas, ke ĉiuj homoj estu savitaj kaj venu al la scio de la vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Ĉar ekzistas unu Dio, kaj unu interulo inter Dio kaj homoj, homo, Kristo Jesuo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'kiu sin donis kiel elaĉetaĵon por ĉiuj, ateston elmontrotan en konvenaj tempoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'por kio mi estas nomita predikisto kaj apostolo (mi diras la veron, mi ne mensogas), instruisto por la nacianoj en fido kaj vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Mi deziras do, ke la viroj preĝu en ĉiu loko, levante sanktajn manojn, sen kolero kaj disputado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Tiel same, ke virinoj sin vestu per decaj vestoj, kun modesteco kaj sobreco; ne kun harplektaĵoj, aŭ oro, aŭ perloj, aŭ multekostaj vestoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'sed (kio konvenas al virinoj konfesantaj la piecon) per bonfaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Virino lernu en kvieteco kun ĉia submetiĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Sed mi ne permesas al virino instruadi, nek regi super viro, sed esti en kvieteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Ĉar Adam kreiĝis la unua, poste Eva;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'kaj Adam ne trompiĝis; sed la virino, trompite, falis en pekon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'sed ŝi saviĝos per la naskado, se ili daŭras en fido kaj amo kaj sanktiĝo kun sobreco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Fidinda estas la diro: Se iu celas episkopecon, tiu deziras bonan laboron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Episkopo do devas esti neriproĉebla, edzo de unu edzino, sobra, moderema, ordema, gastama, instruema,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'ne vindrinkema, ne batema; sed mildanima, ne disputema, ne monamanto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'reganta bone sian propran domanaron, tenante siajn gefilojn sub regado kun ĉia seriozeco');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, '(sed se iu ne scias regi sian propran domon, kiel li zorgos pri la eklezio de Dio?);');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'ne novico, por ke li ne ŝvelu per fiereco kaj ne falu en la kondamnon de la diablo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Krom tio li devas havi bonan ateston de la eksteruloj, por ke li ne falu en riproĉon kaj kaptilon de la diablo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Tiel same diakonoj devas esti seriozaj, ne duflanke parolantaj, ne tro amantaj vinon, ne avidantaj malhonoran gajnon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'tenantaj la misteron de la fido en pura konscienco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'Kaj tiuj ankaŭ estu unue provitaj; poste ili servu kiel diakonoj, se ili estos neriproĉeblaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Virinoj ankaŭ devas esti seriozaj, ne kalumniantoj, sobraj, fidelaj pri ĉio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'La diakonoj estu edzoj de po unu edzino, regantaj bone siajn gefilojn kaj siajn proprajn domojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Ĉar tiuj, kiuj bone servadis kiel diakonoj, akiras al si bonan gradon kaj grandan kuraĝon en la fido, kiu estas en Kristo Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Ĉi tion mi skribas al vi, esperante veni al vi baldaŭ,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'sed se mi prokrastos, por ke vi komprenu, kiel oni devas konduti en la domo de Dio, kiu estas la eklezio de la vivanta Dio, la kolono kaj bazo de la vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Kaj laŭ konsento, granda estas la mistero de pieco: Tiu, kiu elmontriĝis en la karno, praviĝis en la spirito, estis vidita de anĝeloj, pripredikita ĉe la nacioj, prikredita en la mondo, prenita supren en gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Sed la Spirito klare diras, ke en la venontaj tempoj kelkaj defalos de la fido, atentante delogantajn spiritojn kaj doktrinojn de demonoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'per la hipokriteco de trompantoj, kiuj havas la konsciencon kaŭterizitan kvazaŭ per brule varmega fero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'admonante ne edziĝi, kaj deteni sin de manĝaĵoj, kiujn Dio kreis por ke ili estu danke ricevitaj de tiuj, kiuj kredas kaj scias la veron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Ĉar ĉiu kreitaĵo de Dio estas bona, kaj nenio devas esti forĵetita, se oni ĝin ricevas kun dankesprimo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'ĉar ĝi estas sanktigita per la parolo de Dio kaj per preĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Se vi memorigos la fratojn pri tio, vi estos bona servanto de Kristo Jesuo, nutrita per la vortoj de la fido kaj de la bona doktrino, kiun vi jam sekvis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'sed forrifuzu profanajn kaj avinajn fabelojn. Kaj ekzercu vin al pieco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'ĉar korpa ekzercado malmulte utilas; sed pieco utilas al ĉio, havante promeson pri la nuna vivo kaj pri la estonta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Fidinda estas la diro, kaj inda je plena akcepto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Ĉar por tio ni laboras kaj batalas, ĉar ni apogas nian esperon sur la vivantan Dion, kiu estas la Savanto de ĉiuj homoj, precipe de la kredantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Tion ordonu kaj instruu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Neniu malestimu vian junecon, sed vi estu ekzemplo al la kredantoj, per parolo, per konduto, per amo, per fido, per ĉasteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Ĝis mi venos, atentu legadon, konsilon, instruadon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Ne malŝatu la donacon, kiu estas en vi, donita al vi per profetado, kun la surmetado de la manoj de la presbiteraro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Estu diligenta pri tiuj aferoj; dediĉu vin al ili, por ke via progreso evidentiĝu al ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Zorgu pri vi mem kaj pri via instruo. Persistu en tio; ĉar, tion farante, vi savos vin mem, kaj tiujn, kiuj vin aŭskultas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Ne riproĉu maljunulon, sed konsilu lin, kiel patron; la pli junajn virojn, kiel fratojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'la maljunulinojn, kiel patrinojn; la pli junajn virinojn, kiel fratinojn, kun ĉia ĉasteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Respektu tiujn vidvinojn, kiuj estas efektive vidvinoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Sed se iu vidvino havas filojn aŭ nepojn, ĉi tiuj lernu unue montri piecon ĉe sia propra familio kaj rekompenci siajn gepatrojn; ĉar tio estas akceptebla antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Tiu, kiu estas efektiva vidvino kaj izolitino, apogas sian esperon sur Dion, kaj persistas en petegoj kaj preĝoj nokte kaj tage.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Sed la voluptamanta, ankoraŭ vivante, malvivas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Tion ankaŭ ordonu, por ke ili estu sen riproĉo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Sed se iu ne zorgas pri siaj propraj, kaj precipe pri siaj familianoj, tiu malkonfesis la fidon, kaj estas pli malbona ol nekredanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Estu registrata kiel vidvino tiu, kiu havas ne malpli ol sesdek jarojn, estis edzino de unu viro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'estas bone atestata pri bonfarado, edukis infanojn, gastigis fremdulojn, lavis la piedojn de la sanktuloj, helpis la suferantojn, kaj sekvis ĉian bonfaradon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Sed la pli junajn vidvinojn malakceptu; ĉar post kiam ili ekfariĝos luksemaj kontraŭ Kristo, ili deziras edziniĝi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'meritante kondamnon, ĉar ili vantigis sian unuan fidon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Krom tio ili lernas esti senutilaj, rondirante de domo al domo; kaj ne sole senutilaj, sed ankaŭ babilemaj kaj sintrudemaj, parolante nekonvenaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Mi volas do, ke la pli junaj edziniĝu, nasku infanojn, mastrumadu, ne donu al la malamiko pretekston por kalumnio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'ĉar kelkaj jam turniĝis flanken post Satano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Se iu kredantino havas vidvinojn, ŝi helpu ilin, kaj la eklezio ne estu ŝarĝata; por ke ĝi helpu la efektivajn vidvinojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'La presbiteroj, kiuj regas bone, estu rigardataj kiel indaj je duobla honoro, precipe tiuj, kiuj laboras super la vorto kaj instruado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Ĉar la Skribo diras: Ne fermu la buŝon al bovo draŝanta. Kaj: La laboristo meritas sian salajron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Kontraŭ presbitero ne akceptu denuncon krom ĉe du aŭ tri atestantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'La pekintojn riproĉu antaŭ la okuloj de ĉiuj, por ke la ceteraj ankaŭ timu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Mi admonas vin antaŭ Dio kaj Kristo Jesuo kaj la elektitaj anĝeloj, ke vi zorgu pri tiuj aferoj sen antaŭjuĝo, farante nenion pro partieco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Sur neniun surmetu la manojn tro rapidece, kaj ne estu partoprenanto en la pekoj de aliaj; konservu vin ĉasta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Ne plu estu akvotrinkanto, sed uzu iom da vino pro la stomako kaj viaj oftaj malfortoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'La pekoj de unuj estas evidentaj, antaŭirantaj al la juĝo; kaj aliajn homojn ili sekvas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Tiel same ankaŭ ekzistas bonaj faroj, kiuj estas evidentaj, kaj la alispecaj ne povas esti kaŝitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Ĉiuj subjugaj sklavoj rigardu siajn estrojn kiel indajn je ĉia honoro, por ke la nomo de Dio kaj la doktrino ne estu blasfemataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Kaj tiuj, kiuj havas kredantajn estrojn, ne malestimu ilin tial, ke ili estas fratoj, sed servu al ili tiom pli, ĉar tiuj, kiuj partoprenas en la Didonaco, estas fidelaj kaj amataj. Tion instruu kaj konsilu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Se iu instruas malsame kaj ne konsentas al sanaj vortoj, la vortoj de nia Sinjoro Jesuo Kristo, kaj al la laŭpieca doktrino,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'tiu estas fanfaronema, nenion sciante, sed malsana je demandoj kaj privortaj diskutoj, de kiuj naskiĝas envio, malpaco, mallaŭdoj, malbonaj suspektoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'disputadoj de homoj mense perversigitaj kaj senigitaj je la vero, supozantaj, ke la pieco estas gajnilo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Sed la pieco kun kontenteco estas granda gajnilo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'ĉar ni nenion enportis en la mondon, kaj ni ne povas ion forporti;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'sed havante manĝaĵojn kaj vestojn, ni estos per tio kontentaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Tamen tiuj, kiuj volas riĉiĝi, falas en tenton kaj kaptilon kaj multajn malsaĝajn kaj malutilajn dezirojn tiajn, kiaj dronigas la homojn en detruo kaj pereo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Ĉar la amo al mono estas radiko de ĉia malbono; celante al tio, kelkaj forvagis de la fido kaj sin trapikis per multaj malĝojoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Sed vi, ho homo de Dio, forsaviĝu de tiaj aferoj, kaj sekvu justecon, piecon, fidon, amon, paciencon, mildecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Batalu la bonan batalon de la fido, kaj ektenu la eternan vivon, al kiu vi estas vokita kaj konfesis la bonan konfeson antaŭ multaj atestantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Mi vin admonas antaŭ Dio, kiu ĉion vivigadas, kaj antaŭ Kristo Jesuo, kiu antaŭ Pontio Pilato atestis la bonan konfeson,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'ke vi plenumu la ordonon sen makulo, sen riproĉo, ĝis la apero de nia Sinjoro Jesuo Kristo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'kiun aperon en Siaj propraj tempoj montros Tiu, kiu estas la benata kaj sola Potenculo, la Reĝo de reĝoj kaj Sinjoro de sinjoroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'kiu sola havas senmortecon, loĝante en lumo neatingebla, kaj kiun neniu vidis nek povas vidi, al kiu estu honoro kaj potenco eterna. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Admonu tiujn, kiuj estas riĉaj en la nuna mondo, ke ili ne estu arogantaj, kaj ke ili apogu sian esperon ne sur la malcertecon de la riĉo, sed sur Dion, kiu donas al ni riĉe ĉion por ĝuado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'ke ili bone agadu, ke ili estu riĉaj je bonaj faroj, ke ili estu pretaj disdoni, simpatiemaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'provizante por si bonan fundamenton kontraŭ la venonta tempo, por ke ili ektenu la efektivan vivon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'Ho Timoteo, gardu tion, kio estas komisiita al vi, deturnante vin for de la babiladoj kaj kontraŭparoloj de la falsenomata scio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'kiun konfesante, kelkaj maltrafis rilate la fidon. Graco estu kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Paŭlo, apostolo de Kristo Jesuo, per la volo de Dio, laŭ la promeso de vivo, kiu estas en Kristo Jesuo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'al Timoteo, mia amata filo: Graco, kompato, kaj paco de Dio, la Patro, kaj de Kristo Jesuo, nia Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Mi dankas Dion, kiun mi adoras de post miaj praavoj kun pura konscienco, ke konstantan memoron mi havas pri vi en miaj preĝoj, nokte kaj tage');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'sopirante vidi vin, memorante viajn larmojn, por ke mi pleniĝu de ĝojo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'ricevinte rememoron pri la sincera fido, kiu estas en vi, kaj kiu loĝis unue en via avino Lois kaj en via patrino Eŭnike, kaj, mi konvinkiĝis, en vi ankaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Pro tio mi memorigas vin, ke vi reekbruligu la donacon de Dio, kiu estas en vi per la surmetado de miaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Ĉar Dio donis al ni spiriton ne de malkuraĝeco, sed de potenco kaj amo kaj sinregado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Ne hontu do pri la atesto de nia Sinjoro, nek pri mi, lia malliberulo; sed kunelportu suferojn kun la evangelio laŭ la potenco de Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'kiu nin savis kaj vokis per sankta voko, ne laŭ niaj faroj, sed laŭ Sia propra antaŭintenco kaj laŭ la graco donita al ni en Kristo Jesuo antaŭ tempoj eternaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'sed nun malkaŝita per la apero de nia Savanto Jesuo Kristo, kiu neniigis la morton kaj enlumigis la vivon kaj la senmortecon per la evangelio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'al kiu mi estas nomita predikisto kaj apostolo kaj instruisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'Pro tio mi ankaŭ suferas tiel; tamen mi ne hontas; ĉar mi konas tiun, al kiu mi kredis, kaj mi konvinkiĝis, ke li havas la povon gardi mian konfiditaĵon ĝis tiu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Konservu la modelon de sanaj vortoj, kiujn vi aŭdis de mi, en fido kaj amo, kiuj estas en Kristo Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'La bonan konfiditaĵon gardu per la Sankta Spirito, kiu loĝas en ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Vi scias, ke forturniĝis de mi ĉiuj en Azio, el kiuj estas Figelo kaj Hermogenes.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'La Sinjoro donu kompaton al la domo de Onesiforo; ĉar li ofte min refreŝigis, kaj li ne hontis pri mia kateno,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'sed kiam li estis en Romo, li elserĉis min tre diligente kaj min trovis');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, '(la Sinjoro donu al li, ke li trovu kompaton ĉe la Sinjoro en tiu tago), kaj vi scias tre bone, kiom da servoj li faris en Efeso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Vi do, mia filo, fortikiĝu en la graco, kiu estas en Kristo Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'Kaj kion vi de mi aŭdis inter multaj atestantoj, tion transdonu al fidelaj homoj, kompetentaj instrui ankaŭ aliajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Vi do elportu suferojn, kiel bona militisto de Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Neniu militanto sin implikas en la aferojn de ĉi tiu vivo; por ke li plaĉu al sia varbinto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'Kaj se iu konkuras kiel atleto, li ne estas kronata, se li ne laŭregule konkuris.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'La laboranta terkultivisto devas la unua partopreni en la fruktoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Konsideru tion, kion mi diras; ĉar la Sinjoro donos al vi komprenon pri ĉio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Memoru Jesuon Kriston, levitan el la mortintoj, el la idaro de David, laŭ mia evangelio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'en ĝi mi elportas suferadon ĝis ligiloj, kiel krimulo, sed la vorto de Dio ne estas ligita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Tial mi suferas ĉion pro la elektitoj, por ke ili ankaŭ atingu la en Kristo Jesuo savon kun gloro eterna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Fidinda estas la diro: Ĉar se ni mortis kun li, ni ankaŭ vivos kun li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'se ni suferas, ni ankaŭ reĝos kun li; se ni malkonfesos lin, li ankaŭ nin malkonfesos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'se ni malfidas, li restas fidela; ĉar li ne povas malkonfesi sin mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Memorigu ilin pri tio, admonante ilin antaŭ la Sinjoro, ke ili ne vortobatalu, kio estas neniel utila, kun risko de ŝancelo por la aŭdantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Klopodu prezenti vin ĉe Dio kiel aprobita, laboranto senriproĉa, ĝuste pritaksante la vorton de la vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Sed evitu profanajn babiladojn; ĉar ili iros antaŭen al pli multe da malpieco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'kaj ilia parolo dismordos kiel gangreno; el kiuj estas Himeneo kaj Fileto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'kiuj pri la vero eraris, dirante, ke la releviĝo estas jam pasinta; kaj ili renversas la fidon de kelkaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Tamen la firma fundamento de Dio staras, havante la jenan sigelon: La Sinjoro konas tiujn, kiuj estas liaj, kaj: Foriru de maljusteco ĉiu, kiu nomas la nomon de la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'Sed en granda domo estas vazoj ne nur oraj kaj arĝentaj, sed ankaŭ lignaj kaj argilaj, kaj unuj por honoro kaj aliaj por malhonoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Se do iu purigos sin de ĉi tiuj, li estos vazo por honoro, sanktigita, taŭga por la mastro, pretigita por ĉiu bona laboro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Sed forkuru de junulaj voluptoj, kaj sekvu justecon, fidon, amon, pacon, kune kun tiuj, kiuj vokas la Sinjoron el pura koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Sed malsaĝajn kaj neklerajn demandojn evitu, sciante, ke ili naskas malpacojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Kaj la servisto de la Sinjoro devas ne malpaci, sed esti afabla al ĉiuj, instruema, tolerema,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'en humileco instruante tiujn, kiuj kontraŭstaras; eble Dio donos al ili penton, por ke ili venu al scio de la vero,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'kaj por ke ili sobraj eliĝu el la kaptilo de la diablo, kaptite de li, por plenumi lian volon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Sed sciu, ke en la lastaj tagoj venos danĝeraj tempoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Ĉar homoj estos sinamantaj, monamantaj, fanfaronemaj, arogantaj, insultemaj, malobeemaj al gepatroj, sendankaj, nesanktaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'neparencamaj, nepacigeblaj, kalumniemaj, nesinregantaj, malmildaj, ne bonamantaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'perfidemaj, pasiemaj, ventoplenaj, plezuron amantaj pli ol Dion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'havante ŝajnon de pieco, sed neinte ĝian potencon; de ĉi tiuj ankaŭ vin forturnu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Ĉar el ĉi tiuj estas tiuj, kiuj rampas en domojn, kaj forkaptas malsaĝajn virinojn, ŝarĝitajn de pekoj, forkondukatajn per diversaj voluptoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'ĉiam lernantajn, kaj neniam kapablajn veni al la scio de la vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Kaj kiel Janes kaj Jambres kontraŭstaris al Moseo, tiel same ĉi tiuj ankaŭ kontraŭstaras al la vero, homoj kun malnobligita spirito, por la fido senvaloraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Sed ili ne plu iros antaŭen; ĉar ilia malsaĝeco evidentiĝos al ĉiuj, kiel ankaŭ fariĝis ĉe tiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Sed vi sekvis mian instruon, konduton, celon, fidon, toleremecon, amon, paciencon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'persekutojn, suferojn, kiaj okazis al mi en Antioĥia, en Ikonio, en Listra; kiajn persekutojn mi suferis; kaj el ĉio tio la Sinjoro min savis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Jes, kaj ĉiuj, kiuj volas vivi pie en Kristo Jesuo, estos persekutataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Sed malbonaj homoj kaj ruzuloj ĉiam iros antaŭen al pli granda malbono, trompantaj kaj trompataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Sed restu vi en tio, kion vi lernis kaj pri kio vi certiĝis, sciante, de kiu vi ĝin lernis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'kaj ke jam de frua infaneco vi konas la sanktajn skribojn, kiuj povas fari vin saĝa por savo per la fido, kiu estas en Kristo Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Ĉiu skribaĵo inspirita de Dio estas ankaŭ utila por instruo, por admono, por korekto, por disciplino en justeco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'por ke la homo de Dio estu perfekta, plene provizita por ĉiu bona laboro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Mi ordonas al vi antaŭ Dio, kaj antaŭ Kristo Jesuo, kiu juĝos la vivantojn kaj la mortintojn, kaj pro lia apero kaj lia regno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'prediku la vorton; insistu ĝustatempe, malĝustatempe; konvinku, admonu, konsilu, en ĉia pacienco kaj instruado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Ĉar venos tempo, kiam oni ne toleros la sanan instruon; sed havante jukantajn orelojn, amasigos al si instruantojn, laŭ siaj deziroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'kaj ili deturnos de la vero sian orelon, kaj turnos sin flanken al fabeloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Sed vi estu sobra en ĉio, elportu suferojn, faru la laboron de evangeliisto, plenumu vian servadon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Ĉar mi jam estas elverŝata kvazaŭ verŝofero, kaj venis la horo de mia foriro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Mi batalis la bonan batalon, mi finis la kuradon, mi gardis la fidon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'de nun estas konservita por mi la krono de justeco, kiun la Sinjoro, la justa juĝisto, donos al mi en tiu tago; kaj ne nur al mi, sed ankaŭ al ĉiuj, kiuj amis lian aperon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Klopodu veni baldaŭ al mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'ĉar Demas min forlasis, amante la nunan mondon, kaj iris al Tesaloniko; Kreskens al Galatujo, Tito al Dalmatujo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Nur Luko estas kun mi. Prenu Markon kaj alkonduku lin kun vi, ĉar li utilas al mi por la servado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Sed Tiĥikon mi sendis al Efeso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'La mantelon, kiun mi lasis en Troas ĉe Karpo, alportu, kiam vi venos, kaj la librojn, precipe la pergamenojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Aleksandro, la kupristo, faris al mi multe da malbono; la Sinjoro redonos al li laŭ liaj faroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'kontraŭ li vi ankaŭ vin gardu, ĉar li multege kontraŭstaris al niaj vortoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Ĉe mia unua pledo, neniu staris kun mi, sed ĉiuj min forlasis; tio ne estu kalkulita kontraŭ ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Sed la Sinjoro staris apud mi, kaj min fortigis, por ke per mi la anonco estu plene publikigita, kaj ke ĉiuj nacianoj aŭdu; kaj mi forsaviĝis el la buŝo de la leono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'La Sinjoro min savos de ĉiu malbona faro, kaj min savkondukos en sian ĉielan regnon; al li la gloro por ĉiam kaj eterne. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Salutu Priskilan kaj Akvilan kaj la domon de Onesiforo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Erasto restis en Korinto; sed Trofimon mi lasis malsanan en Mileto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Klopodu veni antaŭ la vintro. Salutas vin Eŭbulo kaj Pudens kaj Lino kaj Klaŭdia kaj ĉiuj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'La Sinjoro estu kun via spirito. Graco estu kun vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Paŭlo, servisto de Dio kaj apostolo de Jesuo Kristo, laŭ la fido de la elektitoj de Dio, kaj laŭ la scio de la vero, kiu estas laŭ pieco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'kun espero al eterna vivo, kiun la senmensoga Dio promesis antaŭ la tempoj eternaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'sed ĝustatempe Li elmontris Sian vorton en la anonco, kiu estas al mi konfidita konforme al la ordono de Dio, nia Savanto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'al Tito, mia vera filo laŭ komuna fido: Graco kaj paco de Dio, la Patro, kaj de Kristo Jesuo, nia Savanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Pro tio mi lasis vin en Kreto, ke vi aranĝu la aferojn mankohavajn kaj starigu presbiterojn en ĉiu urbo, kiel mi ordonis al vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'se iu troviĝas neriproĉebla, edzo de unu edzino, kies infanoj estas kredantoj, kaj ne estas akuzitaj pri diboĉo, nek ribelemaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Ĉar episkopo devas esti sen riproĉo, kiel administranto de Dio; ne obstina, ne kolerema, ne drinkema, ne malpacema, ne avidanta malhonoran gajnon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'sed gastama, bonamanta, sobra, justa, sankta, sinreganta,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'tenanta la fidelan vorton, kiu estas laŭ la instruado, por ke li povu admoni pri la sana doktrino kaj ankaŭ refuti la kontraŭdirantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Ĉar ekzistas multaj homoj ribelemaj, vantaj parolantoj kaj trompistoj, precipe tiuj el la cirkumcido,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'kies buŝoj devas esti fermitaj; homoj, kiuj renversas tutajn domojn, instruantaj nekonvenaĵojn por malhonora gajno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'Unu el ili, profeto samnacia, diris: La Kretanoj ĉiam estas mensogantoj, malbonaj bestoj, mallaboremaj manĝeguloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Tiu atesto estas vera. Tial akre riproĉu ilin, por ke ili estu sanaj en la fido,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'ne atentante Judajn fabelojn, kaj ordonojn de tiuj homoj, kiuj deturnas sin de la vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Ĉe la puraj, ĉio estas pura; sed ĉe la malpuraj kaj nekredantaj, nenio estas pura; sed ilia menso kaj ilia konscienco estas malpurigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Ili pretendas koni Dion; sed per siaj agoj ili malkonfesas Lin, estante abomenaj kaj malobeemaj kaj por ĉiu bona faro senvaloraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Sed parolu vi tion, kio konvenas al la sana doktrino:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'ke la maljunuloj estu sobraj, seriozmienaj, prudentaj, sanaj en la fido, en amo en pacienco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'ke la maljunulinoj tiel same estu je sintenado respektemaj, ne kalumniantoj, nek sklavigitaj de troa vino, sed instruantaj la bonon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'por ke ili eduku la junulinojn ami siajn edzojn, ami siajn infanojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'esti prudentaj, ĉastaj, hejme laborantaj, bonfaremaj, submetiĝemaj al siaj propraj edzoj, por ke la vorto de Dio ne estu blasfemita;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'konsilu tiel same la junulojn, ke ili estu prudentaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'pri ĉio montrante vin ekzemplo de bonaj faroj, en via instruado montrante sincerecon, seriozecon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'paroladon sanan, nekondamneblan; por ke la kontraŭulo hontu, havante nenion malbonan diri kontraŭ ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Admonu sklavojn, ke ili estu submetiĝemaj al siaj propraj sinjoroj kaj plaĉantaj al ili en ĉio; ne kontraŭdiremaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'ne ŝtelantaj, sed montrantaj ĉian bonan fidelecon; por ke ili ornamu en ĉio la doktrinon de Dio, nia Savanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Ĉar jam aperis la graco de Dio, portante savon al ĉiuj homoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'instruante nin, ke foriginte malpiecon kaj laŭmondajn dezirojn, ni vivadu sobre, juste, kaj pie en la nuna mondo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'atendantaj la feliĉan esperon kaj la malkaŝon de la gloro de nia granda Dio kaj Savanto, Jesuo Kristo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'kiu donis sin por ni, por elaĉeti nin el ĉia maljusteco kaj por purigi al si popolon propran, fervoran pri bonaj faroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Tion parolu, kaj konsilu kaj riproĉu kun ĉia aŭtoritato. Neniu vin malestimu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Memorigu ilin, ke ili submetiĝu al regantoj kaj estroj, ke ili estu obeemaj, pretaj por ĉiu bona laboro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'ke ili ne parolu malbonon pri iu ajn, estu ne malpacemaj, sed dolĉanimaj, montrantaj ĉian mildecon al ĉiuj homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Ĉar ni ankaŭ estis iam malsaĝaj, malobeemaj, trompitaj, servantaj al diversaj pasioj kaj voluptoj, vivantaj en malico kaj envio, malamindaj, kaj malamantaj unu la alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Sed kiam aperis la boneco de Dio, nia Savanto, kaj Lia amo al homoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'ne per laboroj faritaj en justeco, kiujn ni mem farus, sed laŭ Sia kompato Li savis nin, per la lavado de renasko, kaj per la renovigo de la Sankta Spirito,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'kiun Li riĉe surverŝis sur nin per Jesuo Kristo, nia Savanto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'por ke ni, justigite per Lia graco, fariĝu heredantoj laŭ la espero de eterna vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Fidinda estas la diro, kaj mi volas, ke pri tio vi atestadu kun certeco, por ke tiuj, kiuj ekkredis al Dio, zorgu pri bonaj faroj. Tiuj aferoj estas bonaj kaj utilaj al la homoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'sed evitu malsaĝajn demandojn kaj genealogiojn kaj diskutojn kaj prileĝajn disputojn, ĉar ili montriĝas senutilaj kaj vanaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Se iu estas herezulo ankoraŭ post unua admono kaj dua, evitu tiun,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'sciante, ke tia homo perversiĝis kaj pekas, estante memkondamnita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Kiam mi sendos al vi Artemason aŭ Tiĥikon, rapidu veni al mi al Nikopolis; ĉar mi decidis travintri tie.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Antaŭen irigu Zenason, la leĝiston, kaj Apoloson sur ilia vojaĝo kiel eble plej rapide, por ke nenio manku al ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Kaj niaj amikoj ankaŭ lernu daŭrigi bonajn laborojn, por necesaj bezonoj, por ke ili ne estu senfruktaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Ĉiuj, kiuj estas ĉe mi, vin salutas. Salutu vi tiujn, kiuj amas nin en la fido. Graco estu kun vi ĉiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Paŭlo, malliberulo por Kristo Jesuo, kaj Timoteo, la frato, al Filemon, nia amato kaj kunlaboranto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'kaj al Apfia, la fratino, kaj al Arĥipo, nia kunbatalanto, kaj al la eklezio en via domo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Graco al vi kaj paco de Dio, nia Patro, kaj de la Sinjoro Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Mi ĉiam dankas mian Dion, memorigante pri vi en miaj preĝoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'aŭdinte pri via amo kaj pri la fido, kiun vi havas al la Sinjoro Jesuo kaj al ĉiuj sanktuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'por ke la partoprenado en via fido fariĝu energia per la sciigo de ĉiu bonaĵo, kiu estas en vi, por Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Ĉar mi tre ĝojis kaj havis multon da konsolo pro via amo, ĉar la koroj de la sanktuloj refreŝiĝis per vi, frato mia.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Kvankam do mi havas plenan kuraĝon en Kristo, por ordoni al vi tion, kio estas konvena,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'tamen pro la amo mi preferas petegi tia, kia mi estas, Paŭlo, maljunulo kaj nun ankaŭ malliberulo pro Kristo Jesuo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'mi petegas vin koncerne mian filon, kiun mi naskis en miaj katenoj; tio estis Onesimo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'kiu estis iam senutila por vi, sed nun estas utila por vi kaj por mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'mi ĵus resendis al vi lin mem, alivorte, mian propran koron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'lin mi volonte ja tenus apud mi, por ke anstataŭ vi li estu al mi helpanto en la ligiloj de la evangelio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'sed mi nenion volis fari sen via konsento; por ke via boneco estu ne kvazaŭ deviga, sed laŭvola.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Ĉar eble li pro tio estas apartigita for de vi por kelka tempo, por ke vi havu lin por ĉiam;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'jam ne kiel sklavon, sed kiel pli bonan ol sklavo, kiel fraton amatan, precipe por mi, sed des pli por vi, kaj en la karno kaj en la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Se vi do rigardas min kiel kunulon, akceptu lin tiel same, kiel min mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Se tamen li faris ian malhonestaĵon, aŭ ŝuldas ion al vi, tion enkalkulu en mian konton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'mi, Paŭlo, skribas per mia propra mano, mi ĝin repagos; mi tamen ne diras al vi, ke vi viaparte ŝuldas al mi eĉ vin mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Jes, frato mia, lasu min havi plezuron de vi en la Sinjoro; refreŝigu mian koron en Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Fidante pri via obeo, mi skribas al vi, sciante, ke vi faros eĉ pli multe, ol kiom mi diras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Sed krom tio pretigu por mi gastoĉambron; ĉar mi esperas, ke mi, laŭ viaj preĝoj, estos donita al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Salutas vin Epafras, mia kunmalliberulo en Kristo Jesuo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Marko, Aristarĥo, Demas, Luko, miaj kunlaborantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'La graco de nia Sinjoro Jesuo Kristo estu kun via spirito. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Dio, kiu multafoje kaj multamaniere parolis en la tempo antikva al niaj patroj en la profetoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'en tiuj lastaj tagoj parolis al ni en Filo, kiun Li nomis heredanto de ĉio, per kiu ankaŭ Li faris la mondaĝojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'kiu, estante la elbrilo de Lia gloro kaj plena bildo de Lia substanco, kaj subtenante ĉion per la vorto de sia potenco, kaj farinte la elpurigon de niaj pekoj, sidiĝis dekstre de la Majesto en altaĵoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'fariĝinte tiom pli granda ol la anĝeloj, kiom pli bonegan nomon ol ili li heredis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Ĉar al kiu el la anĝeloj Li iam diris: Vi estas Mia Filo, Hodiaŭ Mi vin naskis? kaj denove: Mi estos al li Patro, Kaj li estos al Mi Filo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Kaj ankoraŭ, kiam Li enkondukas la unuenaskiton en la mondon, Li diras: Kaj kliniĝu antaŭ li ĉiuj anĝeloj de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Kaj pri la anĝeloj Li diras: Kiu faras la ventojn Liaj senditoj, Flamantan fajron Liaj servantoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'sed pri la Filo: Via trono estas Dia trono por ĉiam kaj eterne; La sceptro de via regno estas sceptro de justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Vi amas virton kaj malamas malvirton; Tial Dio, via Dio, oleis vin per oleo de ĝojo pli ol viajn kamaradojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'Kaj: En antikveco Vi, ho Eternulo, fondis la teron, Kaj la ĉielo estas la faro de Viaj manoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Ili pereos, sed Vi restos; Kaj ĉiuj ili eluziĝos kiel vesto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'Kiel veston Vi ilin ŝanĝos, kaj ili ŝanĝiĝos. Sed Vi restas la sama, Kaj Viaj jaroj ne finiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Sed al kiu el la anĝeloj Li iam diris: Sidu dekstre de Mi, Ĝis Mi faros viajn malamikojn benketo por viaj piedoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Ĉu ne estas ili ĉiuj spiritoj servantaj, elsendataj, por servi al tiuj, kiuj estas heredontoj de la savo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Pro tio ni devas pli diligente atenti la aŭditaĵojn, por ke ni de ili ne forflosu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Ĉar se la vorto parolata per anĝeloj montriĝis konstanta, kaj ĉiu dekliniĝo kaj malobeo ricevis justan rekompencon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'kiamaniere ni forsaviĝos, malŝatinte tian gravan savon? kiu, unue ekanoncite per la Sinjoro, estas konfirmita al ni de la aŭdintoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'dum Dio ankaŭ kunatestis per signoj kaj mirindaĵoj kaj diversaj potencaĵoj kaj disdonoj de la Sankta Spirito, laŭ Sia volo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Ĉar ne al anĝeloj Li submetis la estontan mondon, pri kiu ni paroladas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Sed iu atestis ie, dirante: Kio estas homo, ke Vi lin memoras? Kio estas homido, ke Vi pensas pri li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Vi malaltigis lin malmulte antaŭ la anĝeloj, Per honoro kaj beleco Vi lin kronis. Vi faris lin reganto super la faritaĵoj de Viaj manoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Ĉion Vi metis sub liajn piedojn. Ĉar, metante ĉion sub lin, Li nenion lasis ne submetita. Sed nun ni ankoraŭ ne vidas ĉion submetita sub lin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Sed la malmulte sub la anĝeloj malaltigitan Jesuon ni vidas, pro la sufero de morto, kronita per honoro kaj beleco, por ke per la favoro de Dio li gustumu morton por ĉiu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Ĉar konvenis al Li, por kiu ĉio estas, kaj de kiu ĉio estas, alkondukanta multajn filojn al gloro, perfektigi per suferado la estron de ilia savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Ĉar la sanktiganto kaj la sanktigatoj estas ĉiuj el unu; pro tiu kaŭzo li ne hontas nomi ilin fratoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'dirante: Mi predikos Vian nomon al miaj fratoj, En la mezo de popola kunveno mi Vin gloros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'Kaj ankaŭ: Mi fidos Lin. Kaj ankaŭ: Jen mi kaj la infanoj, kiujn Dio donis al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Ĉar do la infanoj partoprenas en sango kaj karno, li ankaŭ mem egale partoprenis en ili, por ke per morto li neniigu tiun, kiu havis la potencon de morto, tio estas la diablo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'kaj liberigu tiujn, kiuj per timo de morto dum la tuta vivo estis subigitaj al sklaveco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Ĉar vere li ektenas ne anĝelojn, sed la idaron de Abraham li ektenas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Tial li devis en ĉio similiĝi al siaj fratoj, por ke li fariĝu kompatema kaj fidela ĉefpastro en la aferoj de Dio, por fari repacigon por la pekoj de la popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Ĉar per tio, ke li mem, tentate, suferis, li povas helpi la tentatojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Tial, fratoj sanktaj, partoprenantaj en ĉiela voko, pripensu la Apostolon kaj Ĉefpastron de nia konfeso, Jesuon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'kiu estis fidela al Tiu, kiu nomis lin kiel ankaŭ Moseo en Lia domo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Ĉar ĉi tiu estas rigardita kiel inda je tiom pli granda gloro ol Moseo, kiom pli grandan honoron, ol la domo, havas ĝia stariginto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Ĉar ĉiu domo estas starigita de iu; sed la stariginto de ĉio estas Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Kaj Moseo ja estis fidela en Lia tuta domo, kiel servanto, por atestaĵo pri tio, kio estis parolota;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'sed Kristo, kiel filo super Lia domo; kies domo ni estas, se ni tenos nian kuraĝon kaj la ĝojadon de nia espero firmaj ĝis la fino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Tial, kiel diras la Sankta Spirito: Hodiaŭ, se vi aŭskultas Lian voĉon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'Ne obstinigu vian koron, kiel en la indignigo, Kiel en la tago de la tento en la dezerto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'Kiam viaj patroj Min incitis, Esploris kaj vidis Miajn farojn kvardek jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Pro tio Mi indignis kontraŭ tiu generacio, Kaj Mi diris: Ili ĉiam estas kun koro malĝusta, Kaj ili ne volas koni Miajn vojojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Tial Mi ĵuris en Mia kolero, Ke ili ne venos en Mian ripozejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Gardu vin, fratoj, ke ne estu en iu el vi koro malbona de nekredemo, en defalo de la vivanta Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'sed konsilu unu la alian ĉiutage, dum estas nomate hodiaŭ, por ke neniu el vi estu obstinigita per la trompeco de peko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'ĉar ni fariĝis partoprenantoj en Kristo, se la komencon de nia certiĝo ni tenos firma ĝis la fino;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'dum estas dirite: Hodiaŭ, se vi aŭskultas Lian voĉon, Ne obstinigu vian koron, kiel en la indignigo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Ĉar kiuj, aŭskultinte, indignigis? ĉu ne ĉiuj elirintoj el Egiptujo per Moseo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Kaj kontraŭ kiuj Li indignis kvardek jarojn? ĉu ne kontraŭ la pekintoj, kies korpoj falis en la dezerto?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Kaj al kiuj Li ĵuris, ke ili ne venos en Lian ripozejon, krom al la neobeantoj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Kaj ni vidas, ke ili pro nekredemo ne povis enveni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Ni do timu, ke, kiam al ni restas promeso veni en Lian ripozejon, iu el vi eble ŝajne malatingos ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Ĉar al ni ankaŭ estas evangelio anoncita tiel same, kiel al ili; sed al ili la aŭdita parolo ne utilis, ne miksite kun fido ĉe la aŭdantoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Ĉar ni ekkredintoj venas en la ripozejon, kiel Li diris: Tial Mi ĵuris en Mia kolero, Ke ili ne venos en Mian ripozejon; kvankam la faritaĵoj estis finitaj jam de post la fondo de la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Ĉar Li diris ie pri la sepa tago jene: Kaj Dio ripozis en la sepa tago de Sia tuta laboro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'kaj ankaŭ jene: Ili ne venos en Mian ripozejon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Ĉar restas do por iuj veni en ĝin, kaj tiuj, al kiuj la evangelio unue estis predikita, ne envenis pro malobeo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'denove Li difinis iun tagon, dirante en David: Hodiaŭ, post tiom da tempo; kiel estas dirite: Hodiaŭ, se vi aŭskultas Lian voĉon, Ne obstinigu vian koron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Ĉar se Josuo al ili estus doninta ripozon, Li ne parolus poste pri alia tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Tial restas sabata ripozo por la popolo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Ĉar tiu, kiu venis en sian ripozejon, ankaŭ mem ripozas de siaj faroj, kiel Dio de Siaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Ni klopodu do veni en tiun ripozejon, por ke neniu falu laŭ la sama ekzemplo de malobeo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Ĉar la vorto de Dio estas viva kaj energia, kaj pli akra ol ĉia glavo dutranĉa, kaj penetranta ĝis divido de la animo kaj spirito, kaj de artikoj kaj medolo, kaj kritikanta la pensojn kaj celojn de la koro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Kaj ne ekzistas kreitaĵo kaŝita antaŭ Lia vidado; sed ĉio estas nuda kaj evidenta al la okuloj de Tiu, al kiu nia afero rilatas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Havante do ĉefpastron grandan, trapasintan la ĉielon, Jesuon, la Filon de Dio, ni tenu firme nian konfeson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Ĉar ni havas ĉefpastron ne tian, kiu ne povus simpatii kun niaj malfortaĵoj, sed tentitan en ĉio tiel same, tamen sen peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Ni do alvenu kun kuraĝo al la trono de graco, por ke ni ricevu kompaton kaj trovu gracon por ĝustatempa helpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Ĉar ĉiu ĉefpastro, prenata el inter homoj, pro homoj estas difinita por aferoj rilatantaj al Dio, por ke li oferu kaj donacojn kaj oferojn pro pekoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'povante indulgi tiujn, kiuj estas malkleraj kaj erarantaj, tial, ke li mem estas ĉirkaŭata de malforteco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'kaj pro tio li devas, kiel por la popolo, tiel ankaŭ por si mem, oferi pro pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'Kaj neniu alprenas al si tiun honoron krom la vokato de Dio, tiel same, kiel Aaron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Tiel ankaŭ Kristo sin mem ne honoris, por fariĝi ĉefpastro, sed lin honoris Tiu, kiu diris al li: Vi estas Mia Filo, Hodiaŭ Mi vin naskis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'kiel ankaŭ aliloke Li diris: Vi estas pastro por ĉiam, Laŭ la maniero de Melkicedek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'En siaj karnaj tagoj, preĝojn kaj petegojn oferinte, kun forta kriado kaj larmoj, al Tiu, kiu povis lin savi el morto, kaj aŭdite pro sia pia timo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'tiu, kvankam li estis Filo, tamen lernis obeon per tio, kion li suferis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'kaj perfektigite, li fariĝis la fonto de eterna savo al ĉiuj al li obeantaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'nomite de Dio ĉefpastro laŭ la maniero de Melkicedek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Pri tiu ni havas dirotaĵojn multajn, kaj malfacile klarigeblajn tial, ke vi surdiĝis en aŭdado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Ĉar kvankam vi jam devus esti instruistoj, vi ankoraŭ bezonas, ke oni instruu al vi, kiaj estas la komencaj elementoj de la orakoloj de Dio, kaj vi fariĝis bezonantoj de lakto kaj ne de solida nutraĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Ĉar ĉiu, kiu nutriĝas per lakto, estas nesperta rilate la vorton de justeco; ĉar li estas infaneto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Sed solida nutraĵo estas por la plenaĝuloj, kiuj per uzado havas la sentojn ekzercitaj, por distingi inter bono kaj malbono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Tial, ĉesigante la diskutadon pri la elementoj de Kristo, ni iru antaŭen al perfektiĝo, ne metante denove fundamenton de pento el malvivaj faroj kaj de fido al Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'de la dogmaro pri baptoj, surmetado de manoj, de revivigo de mortintoj, de eterna juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Kaj tion ni faros, se Dio permesos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Ĉar ĉe tiuj, kiuj unufoje estas allumitaj kaj gustumis la ĉielan donon kaj fariĝis partoprenantoj en la Sankta Spirito,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'kaj gustumis la bonan vorton de Dio kaj la potencojn de la estonta mondo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'kaj defalis, ne estas eble renovigi ilin ankoraŭ al pento, dum ili rekrucumas al si la Filon de Dio kaj elmetas lin al publika malhonoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Ĉar la tero, kiu entrinkis la pluvon, sur ĝin ofte venantan, kaj produktas kreskaĵojn, taŭgajn por tiuj, pro kiuj ĝi ankaŭ estas kultivata, ricevas benon de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'sed se ĝi donas dornojn kaj kardojn, ĝi estas malaprobata kaj proksima al malbeno; ĝia fino estas en brulado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Sed ni certigas al ni aferojn pli bonajn pri vi, amatoj, kaj aferojn, kiuj akompanas savon, kvankam ni tiel parolas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'ĉar Dio ne estas maljusta, por forgesi vian laboron kaj la amon, kiun vi montris al Lia nomo, servinte al la sanktuloj kaj ankoraŭ servante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Sed ni deziras, ke ĉiu el vi montru tian saman diligentecon por la plenumo de la espero ĝis la fino;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'por ke vi fariĝu ne maldiligentaj, sed imitantoj de tiuj, kiuj per fido kaj pacienco heredas la promesojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Ĉar kiam Dio promesis al Abraham, Li ĵuris per Si mem (ĉar Li ne povis ĵuri per iu pli granda),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'dirante: Certe benante Mi benos vin, kaj multigante Mi multigos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Kaj tiel, atendinte kun pacienco, li atingis la promeson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Ĉar homoj ĵuras per la pli granda, kaj ĉe ili la ĵuro por certigo estas fino de ĉia disputado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Kaj Dio, volante montri pli abunde al la heredantoj de la promeso la neŝanĝeblecon de Sia intenco, intermetis ĵuron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'por ke per du neŝanĝeblaj aferoj, en kiuj ne eble estas por Dio mensogi, fortan konsolon havu ni, kiuj rifuĝis, por akiri la esperon antaŭ ni metitan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'kiun ni havas kiel ankron de la animo, firman kaj konstantan, enirantan internen de la kurteno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'kien eniris Jesuo, la antaŭulo por ni, fariĝinte ĉefpastro por ĉiam laŭ la maniero de Melkicedek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Ĉar tiu Melkicedek, reĝo de Salem, pastro de Dio la Plejalta, kiu renkontis Abrahamon revenantan de la mortigado de la reĝoj, kaj lin benis,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'kaj al kiu ankaŭ Abraham donis dekonon el ĉio (unue laŭ interpreto reĝo de justeco, kaj poste reĝo de Salem, tio estas reĝo de paco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'senpatra, senpatrina, sengenealogia, havanta nek komencon de tagoj, nek finon de vivo, sed similigita al la Filo de Dio), restas pastro por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Nun pripensu, kiel granda estis ĉi tiu, al kiu la patriarko Abraham donis dekonon el la akiraĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Kaj efektive el la filoj de Levi tiuj, kiuj ricevas la pastran oficon, havas ordonon imposti laŭleĝe podekone la popolon, tio estas, siajn fratojn, kvankam elirintajn el la lumboj de Abraham;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'sed tiu, kies genealogio ne estas el ili, ricevis de Abraham dekonaĵon, kaj benis tiun, kiu havis la promesojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Sed ekster ĉia kontraŭparolo, la malpli granda ricevas benon de la pli granda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'Kaj ĉi tie homoj, kiuj mortas, ricevas dekonaĵojn, sed tie unu, pri kiu estas atestate, ke li vivas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'Kaj, por tiel diri, per Abraham ankaŭ Levi, la ricevanto de dekonaĵoj, donis dekonaĵon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'ĉar li estis ankoraŭ en la lumboj de la patro, kiam Melkicedek lin renkontis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Tial, se ekzistis perfekteco per la Levida pastreco (ĉar sub ĝi la popolo ricevis la leĝon), kia plua bezono estis, ke leviĝu alia pastro laŭ la maniero de Melkicedek, kaj ne estu nomata laŭ la maniero de Aaron?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Ĉar kiam la pastraro ŝanĝiĝas, necese ankaŭ fariĝas ŝanĝo de leĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Ĉar tiu, pri kiu tio estas dirita, estas ano de alia tribo, el kiu neniu servis ĉe la altaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Ĉar evidente estas, ke nia Sinjoro devenis de Jehuda, pri kiu tribo Moseo diris nenion rilate pastrecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Kaj tio eĉ pli evidenta estas, se laŭ simileco de Melkicedek leviĝas pastro alia,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'kiu estas farita ne laŭ la leĝo de ordono karna, sed laŭ la potenco de vivo nedetruebla;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'ĉar li havas la ateston: Vi estas pastro por ĉiam Laŭ la maniero de Melkicedek.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Ĉar okazas vere nuligado de antaŭiranta ordono, pro ĝia malforteco kaj senutileco');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, '(ĉar la leĝo nenion perfektigis); kaj okazas la enkonduko de pli bona espero, per kiu ni alproksimiĝas al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'Kaj pro tio, ke ne mankas ĵurado');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, '(ĉar ili sen ĵurado estas faritaj pastroj, sed ĉi tiu kun ĵuro laŭ Tiu, kiu diris pri li: La Eternulo ĵuris, kaj ne pentos: Vi estas pastro por ĉiam);');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'Jesuo fariĝis garantiulo de des pli bona interligo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Kaj ili ja fariĝis pastroj multenombraj, ĉar pro morto estas malpermesate al ili daŭri;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'sed ĉi tiu, pro sia eterna daŭrado, havas sian pastrecon neŝanĝebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Tial ankaŭ li povas savi ĝis la ekstremaĵo tiujn, kiuj alproksimiĝas per li al Dio, ĉar li ĉiam vivas, por propeti pro ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Ĉar por ni konvenis tia ĉefpastro, sankta, senpeka, senmakula, apartigita for de pekuloj, kaj farita pli alta ol la ĉielo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'li ne havas ĉiutagan necesecon, kiel tiuj ĉefpastroj, oferi oferojn, unue pro la propraj pekoj, poste pro la pekoj de la popolo; ĉar tion li faris unufoje por ĉiam, oferante sin mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Ĉar la leĝo starigas kiel ĉefpastrojn homojn, kiuj havas malfortecon; sed la vorto de la ĵuro, kiu estas post la leĝo, nomas Filon, perfektigitan por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Jen do la resumo rilate la diritaĵojn: Ni havas tian ĉefpastron, kiu sidiĝis dekstre de la trono de la Majesto en la ĉielo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'servanto de la sanktejo, kaj de la vera tabernaklo, kiun starigis ne homo, sed la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Ĉar ĉiu ĉefpastro estas enoficigita por oferi donacojn kaj oferojn; kaj tial estas necese, ke ankaŭ ĉi tiu havu ion por oferi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Sed se li estus sur la tero, li tute ne estus pastro, tial, ke jam ekzistas oferantoj de donacoj laŭ la leĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'kiuj servas al la ekzemplo kaj ombro de ĉielaj aferoj, kiel Moseo estis admonita, faronte la tabernaklon; ĉar: Zorgu, Li diris, ke vi faru ĉion laŭ la modelo, kiu estis montrita al vi sur la monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Sed nun li ricevis servadon des pli bonan, ju pli bona estas la interligo, kies interulo li fariĝis kaj kiu sur pli bonaj promesoj estas dekretita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Ĉar se tiu unua interligo estus sendifekta, tiam ne estus serĉita loko por dua.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Ĉar riproĉante ilin, Li diris: Jen venos la tempo, diras la Eternulo, Kiam Mi faros kun la domo de Izrael kaj la domo de Jehuda interligon novan:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'Ne tian, kiel la interligo, kiun Mi faris kun iliaj patroj En la tago, kiam Mi prenis ilian manon, por elkonduki ilin el la lando Egipta, Ĉar ili ne restis en Mia interligo, Kaj Mi malatentis ilin, diris la Eternulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Sed jen estas la interligo, kiun Mi faros kun la domo de Izrael Post tiu tempo, diras la Eternulo: Mi metos Miajn leĝojn en ilian internon, Kaj sur ilia koro Mi ilin skribos, Kaj Mi estos ilia Dio, Kaj ili estos Mia popolo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'Kaj ne plu instruos ĉiu sian proksimulon, Kaj ĉiu sian fraton, dirante: Ekkonu la Eternulon; Ĉar ĉiuj Min konos, De iliaj malgranduloj ĝis iliaj granduloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Ĉar Mi pardonos iliajn kulpojn, Kaj iliajn pekojn kaj malbonaĵojn Mi ne plu rememoros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'Dirante: Novan interligon-Li malnovigis la unuan. Kaj tio, kio kadukiĝas kaj malnoviĝas estas proksima al malapero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Sed eĉ la unua interligo havis ordonojn pri Diservado, kaj sanktejon mondan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Ĉar tabernaklo estis pretigita: la unua, en kiu estis la kandelabro kaj la tablo kaj la panoj de propono; ĝi estas nomata la Sanktejo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'kaj post la dua kurteno, la tabernaklo nomata la Plejsanktejo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'havanta la oran incensilon, kaj la keston de interligo, tegitan entute per oro, en kiu estis vazo ora (enhavanta la manaon) kaj la ekflorinta bastono de Aaron kaj la tabeloj de la interligo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'kaj super tio kerubojn de gloro superombrantajn la fermoplaton, pri kiuj ni nun ne povas detale paroli.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Kiam do ĉi tio estis tiel aranĝita, en la unuan tabernaklon eniras ĉiam la pastroj, farante la Diservojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'sed en la duan, unufoje en la jaro eniras la ĉefpastro sola, ne sen sango, kiun li oferas pro si kaj pro la eraroj de la popolo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'per tio la Sankta Spirito montras, ke la vojo en la sanktejon ankoraŭ ne estas elmontrita, dum la unua tabernaklo ankoraŭ staras;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'kio estas parabolo por la nuna tempo; laŭ kio estas oferataj donacoj kaj oferoj, kiuj ne povas laŭ la konscienco perfektigi la adoranton,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'nur altrudate (kun manĝaĵoj kaj trinkaĵoj kaj diversaj lavadoj kaj karnaj purigadoj) ĝis tempo de reformo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Sed Kristo, aperinte kiel ĉefpastro de la estontaj bonoj, per la pli granda kaj pli perfekta tabernaklo, ne manfarita, tio estas ne el ĉi tiu kreo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'nek per la sango de kaproj kaj bovidoj, sed per sia propra sango, eniris unufoje por ĉiam en la sanktejon, atinginte eternan elaĉeton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Ĉar se la sango de kaproj kaj bovoj, kaj la cindro de bovidino, ŝprucigite sur malpurulojn, sanktigas ĝis la purigado de la karno:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'kiom pli la sango de Kristo, kiu per la eterna Spirito sin oferis senmakula al Dio, purigos vian konsciencon el malvivaj faroj, por servi al la vivanta Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Kaj pro tio li estas interulo de nova testamento, por ke (post kiam morto okazis por la elaĉeto de tiuj pekoj, kiuj estis sub la unua testamento) la vokitoj ricevu la promeson de la eterna heredaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Ĉar kiam estas testamento, nepre devas esti la morto de la testamentinto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Ĉar testamento efektiviĝas rilate mortinton, ĉar ĝi neniam efikas, dum vivas la testamentinto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Tial ankaŭ la unua testamento ne sen sango dediĉiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Ĉar Moseo, parolinte ĉiun ordonon laŭ la leĝo al la tuta popolo, prenis la sangon de bovidoj kaj kaproj, kun akvo kaj lano skarlata kaj hisopo, kaj aspergis la libron mem kaj la tutan popolon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'dirante: Jen estas la sango de la interligo, kiun Dio ordonis al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Plue li aspergis per la sango la tabernaklon kaj ĉiujn vazojn de la Diservo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'Kaj laŭ la leĝo, preskaŭ ĉio puriĝas per sango; kaj sen sangoverŝado ne fariĝas absolvo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Necese do estis, ke la ekzemploj de la enĉielaj aferoj estu purigitaj per ĉi tiuj, sed la enĉielaj aferoj mem per pli bonaj oferoj, ol ĉi tiuj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Ĉar eniris Kristo ne en sanktejon manfaritan, ekzemplon de la vera; sed en la ĉielon mem, por aperi antaŭ la vizaĝo de Dio por ni;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'nek estas necese, ke li oferu sin ofte, kiel la ĉefpastro eniras en la sanktejon jaron post jaro, kun sango ne propra;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'alie li devus ofte suferi de post la fondo de la mondo; sed nun unufoje en la fino de la mondaĝoj li aperis, por forigi la pekon per la ofero de si mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Kaj kiel estas dekretite por homoj unufoje morti, kaj post tio juĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'tiel ankaŭ Kristo, oferite unufoje, por porti la pekojn de multaj, aperos duan fojon, aparte de peko, al tiuj, kiuj lin atendas, por savo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Ĉar la leĝo, havante ombron de estontaj bonaĵoj, ne la bildon mem de la aferoj, neniam povas, per tiuj samaj oferoj, kiujn oni oferadas senĉese jaron post jaro, perfektigi la tien venantajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Ĉar alie ĉu ili ne ĉesus esti oferataj? tial, ke la adorantoj, unufoje purigite, jam ne havus konsciencon pri pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Sed en tiuj oferoj estas ĉiujara rememorigo pri pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Ĉar ne eble estas, ke la sango de bovoj kaj kaproj forprenus pekojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Tial, venante en la mondon, li diris: Oferojn kaj donacojn Vi ne deziras, Sed korpon Vi preparis por mi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Bruloferojn kaj pekoferojn Vi ne ŝatis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Tiam mi diris: Jen mi venis (En la rulaĵo de la libro estas skribite pri mi), Por plenumi Vian volon, ho Dio!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Antaŭe dirinte: Oferojn kaj donacojn kaj bruloferojn kaj pekoferojn Vi nek deziris nek ŝatis (kiuj estas oferataj laŭ la leĝo),');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'tiam li diris: Jen mi venis, por plenumi Vian volon. Li forprenas la unuan, por ke li starigu la duan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'Laŭ tiu volo ni estas sanktigitaj per la ofero de la korpo de Jesuo Kristo unufoje por ĉiam.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'Kaj ĉiu pastro staradas ĉiutage, servante kaj oferante ofte la samajn oferojn, kiuj neniam povas forpreni pekojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'sed li, oferinte unu oferon por pekoj por ĉiam, sidiĝis dekstre de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'de nun atendante, ĝis liaj malamikoj fariĝos benketo por liaj piedoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Ĉar per unu ofero li perfektigis ĝis eterneco la sanktigatojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Kaj la Sankta Spirito ankaŭ atestas al ni; ĉar, dirinte:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, 'Jen estas la interligo, kiun Mi faros kun ili Post tiu tempo, diras la Eternulo: Mi metos Miajn leĝojn en ilian internon, Kaj sur ilia koro Mi ilin skribos; li ankaŭ diras:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'Kaj iliajn pekojn kaj malbonaĵojn Mi ne plu rememoros.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Sed kie estas absolvo de ĉi tiuj, ne plu estas oferado pro peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Havante do, fratoj, kuraĝon eniri en la plejsanktejon per la sango de Jesuo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'per la vojo nova kaj vivanta, kiun li dediĉis por ni, tra la kurteno, tio estas, lia karno,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'kaj havante grandan pastron super la domo de Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'ni alproksimiĝu kun sincera koro, en pleneco de fido, kun niaj koroj aspergitaj for de malbona konscienco, kaj kun la korpoj lavitaj per akvo pura;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'ni tenu firme la konfeson de nia espero sendekliniĝe; ĉar la promesinto estas fidela;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'kaj ni pripensu unu la alian, por instigi al amo kaj bonaj faroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'ne forlasante nian kunvenadon, kiel estas la kutimo de iuj; sed konsilante unu la alian, kaj des pli forte, ju pli vi vidas la tagon alproksimiĝanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Ĉar se, ricevinte la scion de la vero, ni pekos memvole, jam ne restas ofero pro pekoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'sed ia timoplena atendo de juĝo, kaj de fajra kolero, kiu ekstermos la kontraŭulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Tiu, kiu malŝatis la leĝon de Moseo, sen kompato mortas ĉe du aŭ tri atestantoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'kiom pli severan punon, vi opinias, ke meritos tiu, kiu piedpremis la Filon de Dio kaj rigardas kiel ne sanktan la sangon de la interligo, per kiu li estis sanktigita, kaj kiu spitis la Spiriton de graco?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Ĉar ni konas Tiun, kiu diris: Ĉe Mi estas venĝo, Mi repagos. Kaj ankaŭ: La Eternulo juĝos Sian popolon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Terure estas fali en la manojn de la vivanta Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Sed memoru la antaŭajn tagojn, en kiuj vi, jam allumite, elportis grandan konflikton de suferoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'unuflanke, kiam vi fariĝis spektaklo per riproĉoj kaj doloroj, kaj aliflanke, kiam vi partoprenis kun tiuj, kiuj tian sperton havis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Ĉar vi kompatis tiujn, kiuj estis en katenoj, kaj ĝoje akceptis la rabadon de via posedaĵo, sciante, ke vi mem havas pli bonan kaj restantan posedaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Tial ne forĵetu vian kuraĝon, kiu havas rekompencon grandan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Ĉar vi havas bezonon de pacienco, por ke, plenuminte la volon de Dio, vi ricevu la promeson.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Ĉar ankoraŭ iomete da tempo, La venonto venos, kaj ne malfruos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Sed virtulo vivos per sia fideleco; Kaj se li sin tiros malantaŭen, mia spirito ne ĝojos en li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Sed ni ne estas el la malantaŭen tiriĝantaj en pereon, sed el la kredantaj por la gajnado de la animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Kaj la fido estas realigo de esperataĵoj, provado de aferoj ne vidataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Ĉar per tio la antikvuloj ricevis bonan ateston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Per la fido ni komprenas, ke la mondaĝoj estas kreitaj per vorto de Dio, tiel ke tio, kio estas vidata, ne estas farita el aperantaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Per la fido Habel oferis al Dio pli bonan oferon ol Kain, per kio li ricevis ateston, ke li estas justa, ĉar Dio atestis pri liaj donacoj; kaj per ĝi li, mortinte, ankoraŭ parolas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Per la fido Ĥanoĥ estis transportita, por ne vidi morton; kaj li ne estis trovata, ĉar Dio lin transportis; ĉar antaŭ lia transporto estis atestite pri li, ke li plaĉis al Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'kaj sen fido neeble estas plaĉi al Li; ĉar necese estas, ke tiu, kiu alvenas al Dio, kredu, ke Li ekzistas, kaj ke Li fariĝas rekompencanto al tiuj, kiuj Lin diligente serĉas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Per la fido Noa, avertite pri la ankoraŭ ne viditaj aferoj, kun pia timo konstruis arkeon por la savado de sia domo; per kio li kondamnis la mondon, kaj fariĝis heredanto de la justeco laŭ fido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Per la fido Abraham, vokite, obeis eliri en lokon, kiun li estis ricevonta kiel heredaĵon; kaj li eliris, ne sciante, kien li iras.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Per la fido li fariĝis pasloĝanto en la lando de la promeso, kiel lando fremda, loĝante en tendoj kun Isaak kaj Jakob, kunheredantoj de la sama promeso;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'ĉar li serĉis la urbon havantan la fundamentojn, kies arĥitekturisto kaj konstruanto estas Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Per la fido ankaŭ Sara mem ricevis kapablon gravediĝi, eĉ post la ordinara aĝo, ĉar ŝi kredis la Promesinton fidela;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'sekve ankaŭ el unu, kaj tiu kvazaŭ malviva, leviĝis tiel multaj, kiel la steloj de la ĉielo laŭnombre, kaj kiel la sablo, kiu estas sur la bordo de la maro, nekalkulebla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Ĉiuj tiuj mortis en fido, ne ricevinte la promesojn, sed vidinte kaj salutinte ilin de malproksime, kaj konfesinte, ke ili estas fremduloj kaj migrantoj sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Ĉar tiuj, kiuj parolas tiamaniere, konstatas, ke patrolandon ili serĉas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'Kaj se ili tenadus en memoro tiun landon, el kiu ili eliris, ili havus ian okazon por reiri.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'Sed nun pli bonan landon ili celas, tio estas, ĉielan; tial Dio ne hontas pri ili, esti nomata ilia Dio; ĉar Li por ili pretigis urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Per la fido Abraham, provate, oferis Isaakon; tiu, kiu akceptis la promesojn, ekoferis ja sian solenaskiton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'nome tiu, al kiu estis dirite: Per Isaak oni nomos vian idaron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'pensante, ke Dio povas relevi lin eĉ el la mortintoj; el kie ankaŭ li en similaĵo lin retrovis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Per la fido Isaak benis Jakobon kaj Esavon pri estontaj aferoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Per la fido Jakob, mortante, benis ĉiun el la filoj de Jozef, kaj adorkliniĝis sur la supro de sia bastono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Per la fido Jozef, ĉe la fino de sia vivo, aludis la foriron de la Izraelidoj, kaj pri siaj ostoj ordonis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Per la fido Moseo, naskiĝinte, estis kaŝata tri monatojn de la gepatroj, ĉar ili vidis la infaneton belega, kaj ne timis la dekreton de la reĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Per la fido Moseo, plenkreskinte, rifuzis esti nomata filo de filino de Faraono,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'plivole elektante kunsuferi kun la popolo de Dio, ol havi la kelktempan ĝuadon de peko,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'taksante la riproĉon de Kristo pligranda riĉeco ol la trezoroj Egiptaj, ĉar li rigardis al la estonta rekompenco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Per la fido li forlasis Egiptujon, ne timante la koleregon de la reĝo; ĉar li persistis, kiel vidante Tiun, kiu ne estas videbla.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Per la fido li observis la Paskon kaj la sangaspergon, por ke la ekstermanto de la unuenaskitoj ne tuŝu ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Per la fido li trapasis la Ruĝan Maron kvazaŭ sekteron, kion fari penante, la Egiptoj dronis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Per la fido la muroj de Jeriĥo falis, ĉirkaŭirite sep tagojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Per la fido la malĉastistino Raĥab ne pereis kun la nekredantoj, akceptinte la spionojn kun paco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'Kaj kion mi diru plu? ĉar mankus al mi tempo por rakonti pri Gideon kaj Barak kaj Ŝimŝon kaj Jiftaĥ kaj David kaj Samuel kaj la profetoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'kiuj pere de fido venkis regnojn, plenumis justecon, atingis promesojn, fermis la buŝojn de leonoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'estingis la forton de fajro, forsaviĝis de la tranĉrando de glavo, el malforteco refortiĝis, fariĝis potencaj en militado, forkurigis armeojn de fremduloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Virinoj rericevis siajn mortintojn per revivigo; kaj aliaj suferis turmentadon, ne akceptante liberigon, por atingi pli bonan releviĝon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'kaj aliaj elproviĝis per mokado kaj skurĝado kaj ankaŭ de katenoj kaj malliberiĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'ili estis ŝtonmortigataj, dissegataj, tentataj; per glavo ili estis mortigitaj; ili ĉirkaŭvagis en ŝafaj kaj kapraj feloj, senigite, subpremate, dolorigate');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, '(je kiuj la mondo ne estis inda); ili vagadis en dezertoj, sur montoj, en kavernoj kaj kaŝejoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'Kaj ĉiuj tiuj, ricevinte bonan ateston per sia fido, ne ricevis la promeson,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'ĉar Dio antaŭvidis por ni ion pli bonan, por ke ili sen ni ne estu perfektigataj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Tial ankaŭ ni, havante ĉirkaŭ ni tian nubegon da atestantoj, formetu ĉion pezan kaj la pekon embarasantan, kaj persiste kuru la kuradon antaŭ ni metitan,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'direktante la rigardon al la aŭtoro kaj perfektiganto de la fido, Jesuo, kiu, pro la ĝojo antaŭ li metita, suferis la krucon, malestimante honton, kaj sidiĝis dekstre de la trono de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Ĉar pripensu tiun, kiu suferis tian kontraŭdiradon de pekuloj kontraŭ li, por ke vi ne laciĝu kaj ne malfortiĝu en viaj spiritoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Vi ankoraŭ ne kontraŭstaris ĝis sango, batalante kontraŭ peko;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'kaj vi forgesis la admonon, kiu rezonas kun vi, kiel kun filoj: Mia filo, ne malŝatu la punon de la Eternulo, Nek svenu, riproĉate de Li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'Ĉar kiun la Eternulo amas, tiun Li punkorektas, Kaj Li skurĝas ĉiun filon, kiun Li akceptas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Se vi suferas punon, kiel al filoj Dio rilatiĝas al vi; ĉar kia filo estas, kiun la patro ne punas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Sed se vi estas sen puno, en kiu ĉiuj fariĝas partoprenantoj, tiuokaze vi estas bastardoj, kaj ne filoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Cetere ni havis patrojn de nia karno, kiuj nin punis, kaj ni respektis ilin; ĉu ni ne multe pli submetiĝu al la Patro de la spiritoj, kaj vivu?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Ĉar ili ja dum kelke da tagoj laŭ sia volo punis; sed Li, por utilo, por ke ni partoprenu en Lia sankteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Ĉiu puno portempe ŝajnas esti ne ĝoja, sed malĝoja; sed poste ĝi donas la pacplenan frukton de justeco al tiuj, kiuj per ĝi estas ekzercitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Tial levu la manojn pendantajn kaj la senfortajn genuojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'kaj faru rektajn vojetojn por viaj piedoj, por ke tio, kio estas lama, ne deturniĝu, sed prefere resaniĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Serĉu pacon kun ĉiuj, kaj la sanktigon, sen kiu neniu vidos la Sinjoron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'rigardante zorge, por ke neniu maltrafu la gracon de Dio, por ke nenia radiko de maldolĉeco, altkreskante, vin ĝenu, kaj por ke per tio multaj ne malpuriĝu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'por ke ne estu iu malĉastulo aŭ malpiulo, kiel Esav, kiu por unu manĝo vendis sian unuenaskitecon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Ĉar vi scias, ke eĉ kiam li poste deziris heredi la benon, li estis rifuzita; ĉar por pentado li trovis nenian lokon, kvankam kun larmoj li ĝin serĉis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Ĉar vi ne alvenis al monto tuŝebla kaj brulanta per fajro, kaj al nigreco kaj mallumo kaj ventego,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'kaj sono de trumpeto kaj voĉo de paroloj, kies aŭdantoj petegis, ke plua vorto ne estu parolata al ili,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'ĉar ili ne povis elporti la ordonon: Se eĉ bruto tuŝos la monton, ĝi estu ŝtonmortigita;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'kaj tiel terura estis la aperaĵo, ke Moseo diris: Mi timegas kaj tremas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'sed vi alvenis al la monto Cion kaj al la urbo de vivanta Dio, la ĉiela Jerusalem, kaj al miriadoj da anĝeloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'al la ĝenerala kunveno kaj eklezio de la unuenaskitoj, en la ĉielo enskribitaj, kaj al Dio, la Juĝisto de ĉiuj, kaj al la spiritoj de justuloj perfektigitaj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'kaj al Jesuo, la interulo de nova interligo, kaj al la sango de aspergo, kiu parolas pli bonajn aferojn ol la sango de Habel.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Gardu vin, ke vi ne forrifuzu la parolanton. Ĉar se ne forsaviĝis tiuj, kiuj forrifuzis la admonanton sur la tero, des malpli ni, deturnante nin de la parolanto el la ĉielo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'kies voĉo tiam skuis la teron; sed nun Li promesis, dirante: Ankoraŭ unufoje Mi ekmovos ne sole la teron, sed ankaŭ la ĉielon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Kaj tiu diro: Ankoraŭ unufoje-montras la translokigon de la skuitaĵoj, kiel de faritaĵoj, por ke la neskueblaj restu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Tial, ricevante regnon neskueblan, ni havu dankemecon, per kiu ni adoru Dion akcepteble kun respektego kaj pia timo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'ĉar nia Dio estas fajro konsumanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'La fratamo daŭradu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Ne forgesu gastamon al nekonatoj; ĉar per tio iuj gastigis anĝelojn, ne sciante.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Memoru la katenitojn, kvazaŭ vi ankaŭ estus katenitaj, kaj la suferantojn, ĉar vi ankaŭ estas en la korpo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Estu honorata la edzeco ĉe ĉiuj, kaj la lito estu senmakula; ĉar malĉastulojn kaj adultulojn Dio juĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Estu via karaktero sen monamo; estu kontentaj je tio, kion vi havas; ĉar Li mem diris: Mi ne foriros de vi kaj ne forlasos vin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'Tial ni kuraĝas diri: La Eternulo estas mia helpanto, mi ne timos; Kion faros al mi homo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Memoru viajn regintojn, kiuj parolis al vi la vorton de Dio; kaj ilian fidon imitu, pripensante la finon de ilia vivmaniero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jesuo Kristo estas la sama hieraŭ, hodiaŭ, kaj ĝis eterneco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Ne forportiĝu per dogmaroj diversaj kaj fremdaj; ĉar estas bone, ke la koro estu plifortigata per graco, ne per manĝaĵoj, per kiuj ne profitis la okupiĝantaj pri ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Ni havas altaron, el kiu la servantoj de la tabernaklo havas nenian rajton manĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Ĉar la korpoj de tiuj bestoj, kies sango estas en la sanktejon enportata de la ĉefpastro pro peko, estas bruligataj ekster la tendaro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Tial Jesuo ankaŭ, por ke li sanktigu la popolon per sia propra sango, ekster la pordego suferis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Tial ni eliru al li ekster la tendaro, portante lian riproĉon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Ĉar ĉi tie ni ne havas restantan urbon, sed estontan ni serĉas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Per li do ni oferu al Dio ĉiam oferon de laŭdo, tio estas, la frukton de niaj lipoj konfesantaj al lia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Sed ne forgesu la bonfaradon kaj kunulecon; ĉar tiaj oferoj plaĉas al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Obeu al tiuj, kiuj vin regas, kaj submetiĝu; ĉar ili viglas pro viaj animoj, kvazaŭ liveronte raporton; por ke kun ĝojo ili faru tion, kaj ne ĝemante, ĉar ĉi tio estus senprofita por vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Preĝu por ni; ĉar ni fidas, ke ni havas bonan konsciencon, dezirante en ĉio honeste vivi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Sed des pli urĝe mi petegas vin fari tion, por ke mi tiom pli frue estu redonata al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Nun la Dio de paco, kiu relevis el la mortintoj la grandan paŝtiston de la ŝafoj, nian Sinjoron Jesuo, per la sango de la eterna interligo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'perfektigu vin en ĉia bona laboro, por plenumi Lian volon, farante en vi tion, kio plaĉas al Li, per Jesuo Kristo, al kiu estu la gloro por ĉiam kaj eterne. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Kaj mi petegas vin, fratoj, toleru la vorton de konsilo, ĉar mi skribis al vi per malmulte da vortoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Sciu, ke estas liberigita nia frato Timoteo, kun kiu, se li venos baldaŭ, mi vin vidos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Salutu ĉiujn, kiuj vin regas, kaj ĉiujn sanktulojn. Tiuj, kiuj estas el Italujo, vin salutas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Graco estu kun vi ĉiuj. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jakobo, servisto de Dio kaj de la Sinjoro Jesuo Kristo, al la dek du triboj, kiuj estas dispelitaj: Saluton!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Rigardu ĉion kiel ĝojigan, miaj fratoj, kiam vi falas en diversajn tentojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'sciante, ke la provado de via fido faras paciencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Kaj la pacienco havu sian perfektan faradon, por ke vi estu perfektaj kaj kompletaj, ne havante mankon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Sed se al iu el vi mankas saĝeco, li petu Dion, kiu donacas al ĉiuj malavare kaj ne riproĉas, kaj ĝi estos al li donata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Sed li petu en fido, neniel dubante; ĉar la dubanto similas ondon de la maro, ventopelatan kaj skuatan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Ĉar tiu homo ne pensu, ke li ricevos ion de la Sinjoro-');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'duoblanima homo, ŝanceliĝa en ĉiuj siaj vojoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Sed la malaltranga frato ĝoju pri sia alteco;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'kaj la riĉulo pri sia humiliĝo; ĉar kiel floro de herbo li forpasos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Ĉar la suno leviĝas kun la brulvento kaj sekigas la herbon, kaj ĝia floro falas, kaj la gracio de ĝia formo pereas; tiel ankaŭ la riĉulo velkos en siaj vojoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Feliĉa estas la homo, kiu elportas tenton; ĉar kiam li estos elprovita, li ricevos la kronon de vivo, kiun la Sinjoro promesis al tiuj, kiuj lin amas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Neniu diru, kiam li estas tentata: Mi estas tentata de Dio; ĉar Dio ne estas tentebla de malbono, kaj Li mem tentas neniun;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'sed ĉiu estas tentata, kiam li estas fortirata de sia dezirado, kaj delogata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Tiam la dezirado, gravediĝinte, naskas pekon; kaj la peko, maturiĝinte, naskas morton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Ne trompiĝu, miaj amataj fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Ĉiu bona donaĵo kaj ĉiu perfekta donaco estas de supre, malsuprenvenante de la Patro de lumoj, ĉe kiu ne povas ekzisti ŝanĝo, nek ombro de sinturnado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Laŭ Sia propra volo Li naskis nin per la vorto de la vero, por ke ni estu kvazaŭ unuaaĵo de Liaj kreitaĵoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Tion vi scias, miaj amataj fratoj. Sed ĉiu rapidu aŭdi, malrapidu paroli, malrapidu koleri;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'ĉar la kolero de homo ne efektivigas la justecon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Tial, formetinte ĉian malpurecon kaj superfluon de malico, akceptu kun humileco la enplantitan vorton, kiu povas savi viajn animojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Sed estu plenumantoj de la vorto, kaj ne nur aŭskultantoj, trompantaj vin mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Ĉar se iu estas aŭskultanto de la vorto, kaj ne plenumanto, li similas iun, kiu rigardas sian naturan vizaĝon en spegulo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'ĉar li sin rigardas kaj foriras, kaj tuj forgesas, kia li estis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Sed tiu, kiu fikse rigardas en la perfektan leĝon, la leĝon de libereco, kaj tiel restas, ne estante aŭskultanto, kiu forgesas, sed plenumanto, kiu energias, tiu estos benata en sia faro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Se iu ŝajnas al si religia, ne bridante sian langon, sed trompante sian koron, ties religio estas vanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Religio pura kaj senmakula antaŭ nia Dio kaj Patro estas jena: viziti orfojn kaj vidvinojn en ilia mizero, kaj sin gardi sen malpuriĝo de la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Miaj fratoj, ne kun personfavorado tenu la fidon de nia Sinjoro Jesuo Kristo, la glora Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Ĉar se en vian sinagogon envenas viro kun oraj ringoj, en bela vestaro, kaj envenas ankaŭ malriĉulo en malpura vestaro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'kaj vi respektas la bele vestitan homon, kaj diras: Sidiĝu ĉi tie en bona loko; kaj diras al la malriĉulo: Staru tie, aŭ sidiĝu sube apud mia piedbenketo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'ĉu vi ne diferencigas en vi mem, kaj fariĝas juĝistoj malbone pensantaj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Aŭskultu, miaj amataj fratoj; ĉu Dio ne elektis la malriĉulojn laŭ la mondo, por esti riĉaj rilate al fido, kaj heredantoj de la regno, kiun Li promesis al tiuj, kiuj Lin amas?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Sed vi malhonoradis la malriĉulon. Ĉu ne subpremas vin la riĉuloj, kaj mem trenas vin antaŭ la tribunalojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Ĉu ili ne blasfemas la honorindan nomon, sur vin metitan?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Tamen, se vi plenumas la reĝan leĝon laŭ la Skribo: Amu vian proksimulon kiel vin mem-vi faras bone;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'sed se vi favoras personojn, vi faras pekon, kulpigitaj de la leĝo, kiel malobeintoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Ĉar ĉiu, kiu observas la tutan leĝaron, sed falpuŝiĝas pri unu punkto, fariĝis kulpa pri ĉio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Ĉar Tiu, kiu diris: Ne adultu-diris ankaŭ: Ne mortigu. Se do vi ne adultas, sed mortigas, vi fariĝis malobeinto kontraŭ la leĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Tiel parolu, kaj tiel agu, kiel juĝotoj laŭ leĝo de libereco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Ĉar al tiu, kiu ne kompatis, la juĝo estos senkompata; la kompato sin altigas super la juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Kia estas la profito, miaj fratoj, se iu diras, ke li havas fidon, sed ne havas farojn? ĉu tiu fido povas lin savi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Se frato aŭ fratino estas nuda kaj sen ĉiutaga manĝo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'kaj iu el vi diras al ili: Iru en paco, estu varmaj kaj sataj; tamen vi ne donas al ili tion, kion la korpo bezonas, kia estas la profito?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Tiel same fido, ne havante farojn, estas en si mem malviva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Kaj cetere iu diros: Vi havas fidon, kaj mi havas farojn; montru al mi vian fidon aparte de faroj, kaj mi per miaj faroj montros al vi la fidon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Vi ja kredas, ke Dio estas unu; vi faras bone; la demonoj ankaŭ kredas kaj tremas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Se ĉu vi volas scii, ho vantulo, ke la fido sen faroj estas senfrukta?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Ĉu nia patro Abraham ne praviĝis per faroj, oferinte sian filon Isaak sur la altaro?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Vi vidas, ke la fido kunagis kun liaj faroj, kaj per faroj la fido perfektiĝis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'kaj plenumiĝis la Skribo, kiu diras: Kaj Abraham kredis al Dio, kaj tio estis kalkulita al li kiel virto; kaj li estis nomita: amiko de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Vi vidas, ke homo praviĝas per faroj, kaj ne sole per fido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Tiel same, ĉu ankaŭ la malĉastistino Raĥab ne praviĝis per faroj, kiam ŝi akceptis la senditojn kaj forsendis ilin per alia vojo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Ĉar kiel la korpo aparte de la spirito estas malviva, tiel ankaŭ fido aparte de faroj estas malviva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Ne estu multaj instruistoj, miaj fratoj, sciante, ke ni ricevos pli severan juĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Ĉar multokaze ni ĉiuj falpuŝiĝas. Se iu ne falpuŝiĝas parole, tiu estas perfekta homo, kapabla bridi ankaŭ la tutan korpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Se ni al la ĉevaloj enmetas la bridojn en la buŝojn, por ke ili obeu al ni, ni ankaŭ ĉirkaŭturnas ilian tutan korpon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Jen ankaŭ la ŝipoj, kiuj, kvankam ili estas tiel grandaj kaj estas kurepelataj de fortaj ventoj, tamen per tre malgranda direktilo turniĝadas, kien ajn la volo de la direktilisto decidas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Tiel ankaŭ la lango estas malgranda membro, kaj fanfaronas grandaĵojn. Jen, kiel grandan arbaron ekbruligas fajrero!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'Kaj la lango estas fajro; mondo da maljusteco inter niaj membroj estas la lango, kiu malpurigas la tutan korpon kaj ekbruligas la radon de la naturo kaj estas ekbruligita de Gehena.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Ĉar ĉiun specon de bestoj kaj birdoj, de rampaĵoj kaj enmaraĵoj la homa raso al si subigas kaj subigis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'sed la langon neniu povas subigi; ĝi estas malkvieta malbono, plena de mortiga veneno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Per ĝi ni benas la Sinjoron kaj Patron; kaj per ĝi ni malbenas homojn, faritajn laŭ la bildo de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'el la sama buŝo eliras beno kaj malbeno. Miaj fratoj, tio devus ne tiel esti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Ĉu la fonto elŝprucigas el la sama aperturo dolĉan akvon kaj maldolĉan?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'ĉu figarbo, miaj fratoj, povas doni olivojn, aŭ vinberarbo figojn? kaj sala akvo ne donas dolĉaĵon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Kiu inter vi estas saĝa kaj prudenta? tiu elmontru per honesta vivado siajn farojn en mildeco de saĝeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Sed se vi havas akran ĵaluzon kaj malpacon en via koro, ne fieru, kaj ne mensogu kontraŭ la vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Ĉi tiu saĝeco ne devenas de supre, sed estas monda, laŭsenta, demona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Ĉar kie estas ĵaluzo kaj malpaco, tie estas konfuzo kaj ĉia malnobla ago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Sed la saĝeco, kiu estas de supre, estas unue ĉasta, poste pacema, milda, cedema, plena de kompatemo kaj bonaj fruktoj, sen partieco, sen hipokriteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Kaj la frukto de justeco estas semata en paco por tiuj, kiuj faras pacon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'De kie militoj kaj de kie bataloj inter vi? ĉu ne de viaj voluptoj, militantaj en viaj membroj?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Vi deziras, kaj ne havas; vi mortigas kaj konkuras, kaj ne povas akiri; vi batalas kaj militas; vi ne havas, ĉar vi ne petas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Vi petas kaj ne ricevas, tial, ke vi petas malprave, por ke vi elspezu por viaj voluptoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Vi adultulinoj, ĉu vi ne scias, ke la amikeco al la mondo estas malamikeco al Dio? Ĉiu do, kiu volas esti amiko de la mondo, fariĝas malamiko de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Aŭ ĉu vi opinias, ke la Skribo vane parolas? Ĉu la spirito, kiun Li loĝigis en ni, deziregas envieme?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Sed Li donas pli grandan gracon. Tial estas dirite: Dio kontraŭstaras al la fieruloj, sed al la humiluloj Li donas gracon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Submetiĝu do al Dio; sed rezistu la diablon, kaj li forkuros de vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Alproksimiĝu al Dio, kaj Li alproksimiĝos al vi. Purigu la manojn, vi pekuloj, kaj ĉastigu la korojn, vi duoblanimuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Mizeru kaj malĝoju kaj ploru; via ridado turniĝu en ploron, kaj via ĝojo en malĝojon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Humiliĝu antaŭ la Sinjoro, kaj Li vin altigos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Ne kalumniu unu la alian, fratoj. Kiu kalumnias fraton aŭ juĝas sian fraton, tiu kalumnias la leĝon kaj juĝas la leĝon; sed se vi juĝas la leĝon, vi jam estas ne plenumanto de la leĝo, sed juĝanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Unu estas la leĝdonisto kaj juĝisto, Tiu, kiu povas savi aŭ pereigi; kiu vi estas, juĝanta vian proksimulon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Atentu nun vi, kiuj diras: Hodiaŭ aŭ morgaŭ ni iros al tiu urbo kaj restos tie unu jaron kaj negocados kaj profitos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'kvankam vi ne scias, kio morgaŭ okazos. Kio estas via vivo? Vi ja estas vaporo, kiu mallongan tempon montriĝas kaj poste malaperas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Anstataŭ diri: Se la Sinjoro volos, ni vivados kaj faros ĉi tion aŭ tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Sed nun vi fieras pri viaj memfidaĵoj; ĉiu tia singratulado estas malbona.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Kiu do scias bonfari, kaj ne bonfaras, ĉe tiu estas peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Atentu nun, riĉuloj; ploregu kaj kriegu pro la mizeroj sur vin alvenontaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Via riĉo putriĝis, kaj viaj vestoj konsumiĝas de tineoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Via oro kaj via arĝento rustiĝis; kaj ilia rusto atestos kontraŭ vi, kaj konsumos vian karnon, kiel fajro. En la lastaj tagoj vi kolektadis trezoron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Jen krias la de vi trompe retenata salajro de la laboristoj, kiuj falĉis viajn kampojn; kaj la krioj de la rikoltintoj venis en la orelojn de la Eternulo Cebaot.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Vi luksadis sur la tero, kaj diboĉadis; vi nutradis viajn korojn en tago de buĉado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Vi kondamnis, vi mortigis la justulon; li ne kontraŭstaras al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Paciencu do, fratoj, ĝis la alveno de la Sinjoro. Jen la terkultivisto atendas la multevaloran frukton de la tero, paciencante pri ĝi, ĝis ĝi ricevos la fruan kaj la malfruan pluvon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Vi ankaŭ paciencu; fortikigu viajn korojn; ĉar la alveno de la Sinjoro alproksimiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Ne murmuru, fratoj, unu kontraŭ la alia, por ke vi ne estu juĝataj; jen la juĝisto staras antaŭ la pordoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Prenu, fratoj, kiel ekzemplon de suferado kaj pacienco, la profetojn, kiuj parolis en la nomo de la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Jen ni nomas feliĉaj tiujn, kiuj elportis suferon; vi aŭdis pri la pacienco de Ijob, kaj vidis la finan agadon de la Sinjoro, ke la Sinjoro estas kompatema kaj indulgema.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Sed antaŭ ĉio, miaj fratoj, ne ĵuru, nek per la ĉielo, nek per la tero, nek per ia alia ĵuro; sed via jes estu jes, kaj via ne estu ne; por ke vi ne falu sub juĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Ĉu iu el vi suferas? li preĝu. Ĉu iu estas gaja? li psalme kantu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Ĉu iu el vi malsanas? li venigu la presbiterojn de la eklezio; kaj ili preĝu super li, ŝmirinte lin per oleo en la nomo de la Sinjoro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'kaj la preĝo de fido savos la malsanulon, kaj la Sinjoro relevos lin; kaj se li faris pekojn, tio estos pardonita al li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Konfesu do viajn pekojn unu al la alia, kaj preĝu unu por la alia, por ke vi resaniĝu. Petego de justulo multe efikas per sia energio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Elija estis homo samnatura, kiel ni, kaj li preĝis fervore, ke ne pluvu; kaj ne pluvis sur la teron dum tri jaroj kaj ses monatoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'Kaj denove li preĝis; kaj la ĉielo donis pluvon, kaj la tero ekproduktis sian frukton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Miaj fratoj, se iu el vi forvagos de la vero, kaj iu lin returnos,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'oni sciu, ke tiu, kiu returnas pekulon de la elvoja forvago, savos animon el morto kaj kovros amason da pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Petro, apostolo de Jesuo Kristo, al la elektitoj, kiuj estas el la dispelitaro, pasloĝantaj en Ponto, Galatujo, Kapadokio, Azio, kaj Bitinio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'laŭ la antaŭscio de Dio, la Patro, en sanktigo de la Spirito, por obeo kaj aspergo de la sango de Jesuo Kristo: Graco al vi kaj paco pligrandiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Benata estu la Dio kaj Patro de nia Sinjoro Jesuo Kristo, kiu laŭ Sia granda kompato nin renaskis en esperon vivan per la releviĝo de Jesuo Kristo el la mortintoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'en heredaĵon ne pereontan, ne makulotan, ne velkontan, rezervitan en la ĉielo por vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'kiuj estas gardataj de la potenco de Dio per fido al savo preta malkaŝiĝi en la lasta tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'En tio vi ĝojegas, kvankam por kelka tempo, se estas necese, malĝojigite en diversaj tentoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'por ke la provado de via fido, pli multevalora ol oro, kiu pereas, kvankam per fajro provite, troviĝu efika por laŭdo kaj gloro kaj honoro en la malkaŝo de Jesuo Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'kiun, ne vidinte, vi amas; kiun kvankam nun vi ne vidas, tamen, al li kredante, vi ĝojegas per ĝojo nedirebla kaj gloroplena;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'ricevante la celon de via fido, savon de animoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Koncerne tiun savon esploris kaj serĉis la profetoj, kiuj profetis pri la graco venonta al vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'serĉante, kiun kaj kian tempon montris la enestanta en ili Spirito de Kristo, kiu atestis antaŭe la suferojn por Kristo kaj la sekvontajn glorojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Kaj al ili malkaŝiĝis, ke ne al si mem, sed al vi, ili liveris tion, kio nun estas proklamita al vi de tiuj, kiuj predikis al vi la evangelion per la Spirito Sankta, elsendita el la ĉielo; en kiujn aferojn anĝeloj deziras enrigardi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Tial, ĉirkaŭzoninte la lumbojn de via menso, estu sobraj kaj esperadu perfekte la gracon alportotan al vi en la malkaŝo de Jesuo Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'kiel infanoj de obeo, ne formiĝante laŭ la voluptoj, kiujn vi antaŭe havis en via nescio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'sed kiel via Vokinto estas sankta, tiel vi ankaŭ fariĝu sanktaj en ĉia konduto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'pro tio, ke estas skribite: Vi estu sanktaj, ĉar Mi estas sankta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Kaj se vi vokas la Patron, kiu sen personfavorado juĝas laŭ la faro de ĉiu, vi pasigu en timo la tempon de via ĉi tiea loĝado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'sciante, ke ne per pereemaj objektoj, oro aŭ arĝento, vi elaĉetiĝis el via vanta vivmaniero, kiun vi ricevis de viaj patroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'sed per multekosta sango, kiel de ŝafido senmakula kaj sendifekta, la sango de Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'kiu estis antaŭdifinita antaŭ la fondo de la mondo, sed elmontrita en la fino de la tempoj pro vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'kiuj per li fidas Dion, kiu relevis lin el la mortintoj kaj donis al li gloron; por ke via fido kaj espero estu al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Ĉastiginte viajn animojn, en la obeo al la vero, por sincera amo al la frataro, amu unu la alian el la koro fervore;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'renaskite, ne el pereema semo, sed el nepereema, per la vorto de Dio, vivanta kaj restanta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Ĉar: Ĉiu karno estas herbo, Kaj ĉiu ĝia ĉarmo estas kiel kampa floreto. Sekiĝas herbo, velkas floreto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'Sed la vorto de la Eternulo restas eterne. Kaj ĉi tiu estas la parolo, kiu estas predikita al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Formetinte do ĉian malbonon kaj ĉian trompon kaj hipokritecon kaj enviojn kaj ĉiajn kalumniojn,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'kiel ĵusnaskitaj suĉinfanoj, sopiru al la spirita lakto pura, por ke vi per tio kresku en savon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'se vi gustumis, ke la Sinjoro estas bona;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'al kiu alvenante, kvazaŭ al ŝtono vivanta, de homoj rifuzita, sed ĉe Dio elektita, honorinda,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'vi ankaŭ, kiel ŝtonoj vivantaj, konstruiĝas domo spirita, sankta pastraro, por oferi spiritajn oferojn, akcepteblajn de Dio per Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Ĉar estas enhavate en skribo: Jen Mi kuŝigas en Cion bazangulan ŝtonon, elektitan, valoregan; Kaj kiu lin fidas, tiu ne estos hontigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Por vi do, la fidantoj, estas la valoregeco; sed por nefidantoj: Ŝtono, kiun malŝatis la konstruantoj, Fariĝis ŝtono bazangula;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'kaj: Ŝtono de falpuŝiĝo kaj roko de alfrapiĝo; ili falpuŝiĝas pro la vorto, malobeante, por kio ankaŭ ili estas difinitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Sed vi estas raso elektita, pastraro reĝa, nacio sankta, popolo Diposedata, por ke vi proklamu la gloron de Tiu, kiu vokis vin el mallumo en Sian lumon mirindan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'kiuj iam estis ne-popolo, sed nun estas popolo de Dio; antaŭe nekompatitoj, sed nun kompatitoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Amataj, mi petegas vin kiel fremdulojn kaj migrantojn, detenu vin de karnaj voluptoj, kiuj militadas kontraŭ la animo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'kondutante dece ĉe la nacianoj, por ke, kvankam ili kalumnias vin kiel malbonagulojn, tamen, vidante viajn bonfarojn, ili gloru Dion en la tago de vizitado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Submetu vin al ĉiu homa institucio pro la Sinjoro; ĉu al la reĝo, la superreganto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'ĉu al regantoj, kiel liaj senditoj por venĝo al malbonaguloj kaj por laŭdo al bonaguloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Ĉar la volo de Dio estas, ke bonfarante, vi silentigu la nesciadon de homoj malsaĝaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'kiel liberaj, kaj ne farantaj el via libereco kovrilon de malico, sed kiel servistoj de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Ĉiujn honoru. La frataron amu. Dion timu. La reĝon honoru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Servantoj, submetu vin al viaj sinjoroj kun ĉia timo; ne sole al la bonaj kaj malseveraj, sed ankaŭ al la malbonhumoraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Ĉar tio estas laŭdinda, se pro konscienco al Dio oni elportas malĝojon, suferante maljuste.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Ĉar kia honoro estas, se, pekante kaj sekve batate, vi tion pacience elportas? sed se, bonfarante kaj sekve suferante, vi tion pacience elportas, tio estas laŭdinda antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Ĉar al ĉi tio vi estas vokitaj; pro tio, ke Kristo ankaŭ suferis pro vi, postlasante por vi ekzemplon, por ke vi sekvu liajn postesignojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'pekon li ne faris, kaj trompo ne troviĝis en lia buŝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'insultate, li ne insultis responde; suferante, li ne minacis, sed submetis sin al la juste juĝanta;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'li mem portis niajn pekojn en sia korpo sur la lignaĵo, por ke ni, malvivigite koncerne pekojn, vivu por justeco; per lia vundo vi resaniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Ĉar vi estis kiel ŝafoj erarvagantaj; sed nun vi returne venis al la Paŝtisto kaj Episkopo de viaj animoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Tiel same, edzinoj, submetu vin al viaj propraj edzoj; por ke, eĉ se iuj ne obeas al la vorto, ili sen la vorto estu gajnitaj per la konduto de siaj edzinoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'rigardante vian konduton kun timo ĉastan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Via ornamo estu ne la ekstera ornamo de harplektado kaj orportado, aŭ la surmetado de vestoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'sed la kaŝita homo de la koro en la nedifektebla vesto de spirito milda kaj trankvila, kiu estas multevalora antaŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Ĉar tiel same ankaŭ, en la tempo antikva, la sanktaj virinoj, kiuj esperis al Dio, ornamis sin, submetante sin al siaj propraj edzoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'kiel Sara obeis al Abraham, nomante lin sinjoro; kies infanoj vi fariĝis, bonfarante, kaj ne ektimigate per ia teruro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Tiel same, edzoj, kunvivadu kun viaj edzinoj laŭscie, donante honoron al la virino kiel al la plimalforta ilo, kaj estante ankaŭ kun ili kunheredantoj de la graco de vivo, por ke viaj preĝoj ne malhelpiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Fine, estu ĉiuj samideaj, simpatiaj, fratamemaj, kompatemaj, humilanimaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'ne repagantaj malbonon kontraŭ malbono, nek insulton kontraŭ insulto, sed kontraŭe benadantaj; ĉar al tio vi estas vokitaj, por ke vi heredu benon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Ĉar: Kiu volas ami vivon kaj vidi bonajn tagojn, Tiu gardu sian langon kontraŭ malbono, Kaj sian buŝon kontraŭ mensoga parolo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Li dekliniĝu de malbono kaj faru bonon, Li serĉu pacon, kaj ĉasu ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Ĉar la okuloj de la Eternulo estas turnitaj al la piuloj, Kaj Liaj oreloj al iliaj krioj; Sed la vizaĝo de la Eternulo estas kontraŭ tiuj, kiuj faras malbonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Kaj kiu faros al vi malbonon, se vi fariĝos fervoraj en la bono?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Sed se vi eĉ suferus pro justeco, feliĉegaj vi estus; kaj ilian timon ne timu, nek maltrankviliĝu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'sed la Sinjoron Kriston sanktigu en viaj koroj; estu ĉiam pretaj doni defendan respondon al ĉiu, kiu vin demandas pri la motivo de la espero en vi, sed kun humileco kaj timo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'havantaj bonan konsciencon; por ke, dum vi estas malestimataj, hontu tiuj, kiuj kalumnias vian bonan konduton en Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Ĉar pli bone estus, se tiel volus Dio, suferi pro bonfarado, ol pro malbonfarado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Ĉar Kristo ankaŭ unufoje suferis pro pekoj, justulo pro maljustuloj, por ke li nin konduku al Dio; mortigite en la karno, sed vivigite en la spirito;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'en kiu ankaŭ li iris kaj predikis al la enkarceraj spiritoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'kiuj iam malobeis, kiam la longedaŭra pacienco de Dio atendis en la tagoj de Noa dum la pretigado de la arkeo, en kiu malmultaj, tio estas ok personoj, elsaviĝis tra akvo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'kiu ankaŭ vin nun savas en antitipo, la bapto, ne la formetado de la karna malpuraĵo, sed la demando de bona konscienco al Dio per la releviĝo de Jesuo Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'kiu estas dekstre de Dio, irinte en la ĉielon; al li anĝeloj kaj aŭtoritatoj kaj potencoj estas submetitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Ĉar Kristo do suferis en la karno, vi ankaŭ armu vin per la sama intenco; ĉar la suferinto en la karno apartiĝis de pekoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'por ke vi travivu la reston de la enkarna tempo jam ne laŭ la voluptoj de homoj, sed laŭ la volo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Ĉar la tempo pasinta sufiĉas, por elfari la deziron de la nacianoj kaj iradi en diboĉoj, voluptoj, vindrinkado, brufestenoj, ebrieco, kaj abomenaj idolkultoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'en kio ili miras, ke vi ne kuras kune kun ili en la saman superfluon de diboĉado, kaj ili kalumnias vin;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'ili prirespondos al Tiu, kiu estas preta juĝi la vivantojn kaj la mortintojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Ĉar por tio ankaŭ la evangelio estas anoncita al la mortintoj, por ke ili estu korpe juĝitaj laŭ homoj, sed spirite vivu laŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Sed la fino de ĉio alproksimiĝas; prudentiĝu do, kaj sobriĝu por preĝoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'antaŭ ĉio havante fervoran amon unu al alia; ĉar amo kovras amason da pekoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'estu gastamaj unu al alia sen murmurado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'laŭmezure, kiel ĉiu ricevis donacon, tiel ĝin administrante inter vi, kiel bonaj administrantoj de la diversaspeca graco de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'se iu parolas, li parolu kvazaŭ orakolojn de Dio; se iu administras, li administru kvazaŭ el la forto, kiun Dio provizas; por ke en ĉio Dio estu glorata per Jesuo Kristo, kies estas la gloro kaj la potenco por ĉiam kaj eterne. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Amataj, ne surpriziĝu pri la fajrego ĉe vi okazanta por provi vin, kvazaŭ io stranga okazus ĉe vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'sed laŭ tio, ke vi partoprenas en la suferoj de Kristo, ĝoju; por ke ankaŭ en la elmontro de lia gloro vi ĝoju ravege.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Se vi estas riproĉataj pro la nomo de Kristo, feliĉegaj vi estas; ĉar la Spirito de gloro kaj la Spirito de Dio restas sur vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Nur neniu el vi suferu kiel mortiginto, aŭ ŝtelisto, aŭ malbonfarinto, aŭ kiel sintrudanto en malpropraj aferoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'sed se iu suferas kiel Kristano, li ne hontu; sed li gloru Dion en tiu nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Ĉar jam venis la tempo por la komenco de la juĝo ĉe la domo de Dio; kaj se ĝi komenciĝas ĉe ni, kia estos la sorto de tiuj, kiuj ne obeas al la evangelio de Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'Kaj se justulo apenaŭ saviĝas, kie aperos malpiulo kaj pekulo?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Tial ankaŭ tiuj, kiuj suferas laŭ la volo de Dio, alkonfidu siajn animojn en bonfarado al fidela Kreinto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'La presbiterojn do inter vi mi admonas, estante kunpresbitero kaj atestanto de la suferoj de Kristo kaj partoprenanto en la malkaŝota gloro:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Paŝtu la gregon de Dio ĉe vi, direktante ĝin, ne devige, sed volonte, laŭ Dio; ne pro avideco, sed bonvole;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'ne kvazaŭ sinjorante super la heredo, sed fariĝante ekzemploj al la grego.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'Kaj kiam elmontriĝos la Ĉefpaŝtisto, vi ricevos la nevelkontan kronon de gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Tiel same, vi plijunuloj, submetu vin al la pliaĝuloj. Tial ankaŭ vi ĉiuj submetu vin unu al la alia, kaj zonu vin per humileco; ĉar Dio kontraŭstaras al la fieruloj, sed al la humiluloj donas gracon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Humiligu vin do sub la potencan manon de Dio, por ke Li altigu vin ĝustatempe;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'surĵetante sur Lin ĉian vian zorgon, ĉar Li zorgas pri vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Estu sobraj, vigladu; via kontraŭulo, la diablo, kiel leono blekeganta ĉirkaŭiras, serĉante, kiun li povos forgluti;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'lin rezistu, konstantaj en la fido, sciante, ke la samaj suferoj plenumiĝas en via frataro en la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Kaj la Dio de ĉia graco, kiu vin alvokis al Sia eterna gloro en Kristo, mem perfektigos, firmigos, plifortigos vin ne longe suferintajn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Al Li estu la potenco por ĉiam kaj eterne. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Per Silvano, la fidela frato, kiel mi opinias, al vi mi skribis mallonge, konsilante kaj atestante, ke ĉi tio estas la vera graco de Dio; en ĝi firme staru.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Vin salutas la en Babel kunelektitino, kaj Marko, mia filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Salutu unu la alian per ama kiso. Paco al vi ĉiuj, kiuj estas en Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Simon Petro, servisto kaj apostolo de Jesuo Kristo, al tiuj, kiuj ricevis egale altvaloran fidon, kiel ni, en la justeco de nia Dio kaj Savanto Jesuo Kristo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Graco al vi kaj paco pligrandiĝu en sciado pri Dio, kaj pri Jesuo, nia Sinjoro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'pro tio, ke lia Dia povo donacis al ni ĉion rilatantan al vivo kaj pieco, per la scio de tiu, kiu nin vokis per sia propra gloro kaj virto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'per kiuj li donacis al ni la promesojn karegajn kaj tre grandajn; por ke per ili vi fariĝu partoprenantoj en Dia naturo, forsaviĝinte el la putreco, kiu estas en la mondo per voluptemo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Kaj pro tiu sama kaŭzo viaflanke aplikante ĉian diligentecon, en via fido aldonu virton; kaj en virto scion;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'kaj en scio sinregadon; kaj en sinregado paciencon; kaj en pacienco piecon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'kaj en pieco fratamikecon, kaj en fratamikeco amon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Ĉar tiuj ecoj, se ĉe vi ili troviĝas kaj abundas, faras vin nek mallaboremaj nek senfruktaj en la scio de nia Sinjoro Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Ĉar tiu, al kiu mankas tiuj ecoj, estas blinda, miopa, forgesinte la forpurigon el siaj antaŭaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Sekve, fratoj, pli diligente klopodu, por certigi vian vokon kaj elekton; ĉar farante tion, vi neniam falpuŝiĝos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'ĉar tiel al vi estos riĉe provizita la eniro en la eternan regnon de nia Sinjoro kaj Savanto Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Pro tio mi ĉiam estos preta rememorigi vin pri tiuj aferoj, kvankam vi ilin scias kaj estas fortigitaj en la ĉeestanta vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Kaj mi opinias konvena, dum mi estas en ĉi tiu tabernaklo, vigligi vin per rememorigo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'sciante, ke baldaŭ estos la demeto de mia tabernaklo, ĝuste kiel nia Sinjoro Jesuo Kristo montris al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Kaj mi diligente penos, ke post mia foriro vi povu konstante rememori tion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Ĉar ne sekvinte fabelojn sofismajn, ni konigis al vi la potencon kaj alvenon de nia Sinjoro Jesuo Kristo, sed vidinte per propraj okuloj lian majeston.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Ĉar li ricevis de Dio, la Patro, honoron kaj gloron, kiam al li tia voĉo estis alportita el la brilega gloro: Ĉi tiu estas Mia Filo, la amata, en kiu Mi havas plezuron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'kaj tiun voĉon, alportitan el la ĉielo, ni mem aŭdis, kunestante kun li sur la sankta monto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Kaj ni havas la profetan vorton konfirmitan; kiun atentante, vi bone faras, kvazaŭ lampon lumantan en malhela loko, ĝis ektagiĝos kaj la matenstelo ekleviĝos en viaj koroj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'antaŭ ĉio sciante, ke neniu profetaĵo de la Skribo enhavas en si sian propran klarigon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Ĉar neniam profetaĵo estas alportita per homa volo; sed homoj, movataj de la Sankta Spirito, parolis laŭ Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Sed ankaŭ falsaj profetoj troviĝis inter la popolo tiel same, kiel inter vi estos falsaj instruistoj, kiuj sekrete enkondukos herezojn pereigajn, eĉ malkonfesante la Sinjoron, kiu ilin elaĉetis, kaj venigante sur sin rapidan pereon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Kaj ilian senbridecon sekvos multaj, per kiuj la vojo de la vero estos kalumniata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'Kaj en avideco per trompaj paroloj ili vin komercos; ilia kondamno nun de post tre longe ne malfruas, kaj ilia pereo ne dormas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Ĉar se Dio ne indulgis anĝelojn pekintajn, sed, eninferiginte ilin en kavernojn de mallumo, transdonis ilin rezervatajn por la juĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'kaj ne indulgis la mondon antikvan, sed gardis Noan kun sep aliaj, predikanton de justeco, kiam Li sendis diluvon sur la mondon de malpiuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'kaj, cindriginte la urbojn Sodom kaj Gomora, kondamnis ilin per katastrofo, farinte ilin ekzemplo al estontaj malpiuloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'kaj savis justan Loton, ĉagrenegatan de la senbrida konduto de la malvirtuloj');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, '(ĉar tiu justulo, loĝante inter ili, en vidado kaj aŭdado, turmentis sian justan animon, tagon post tago, pro iliaj malvirtaj faroj):');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'la Sinjoro do scias savi el tento la piulojn, kaj teni sub puno la maljustulojn ĝis la tago de juĝo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'sed precipe tiujn, kiuj iras laŭ la karno en volupto de malpuraĵo, kaj malestimas regadon. Arogantaj, obstinaj, ili ne timas insulti aŭtoritatojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'sed kontraŭe, anĝeloj, superante laŭ forto kaj potenco, ne faras insultan akuzon kontraŭ ili antaŭ la Sinjoro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Sed tiuj, kiel bestoj senprudentaj, naskitaj laŭ naturo por kaptado kaj pereo, blasfemante en aferoj, kiujn ili ne scias, en sia putreco pereos,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'en malbono ricevante pagon por malbono; homoj, kiuj opinias entagan diboĉon plezuro kaj estas makuloj kaj hontindaĵoj, diboĉante en sia uzado de la agapoj, dum ili kunfestenas kun vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'havante okulojn plenajn de adulto kaj ne reteneblajn de pekado; forlogante malfirmajn animojn; havante koron lertan por avideco; estante filoj de malbeno;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'forlasinte la rektan vojon kaj erarvaginte, sekvinte la vojon de Bileam, filo de Beor, kiu amis la rekompencon de malbonfarado;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'sed li estis riproĉita pro sia malobeo; muta azeno, parolante per homa voĉo, haltigis la frenezecon de la profeto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Ili estas putoj senakvaj, kaj nebuletoj pelataj de ventego; por ili la nigreco de mallumo estas rezervita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Ĉar, elparolante fanfaronaĵojn de vanteco, ili forlogas en la karnovolupton per senbrideco tiujn, kiuj ĵus forsaviĝis de tiuj, kiuj vivadas en eraro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'anoncante al ili liberecon, ili mem estas sklavoj de putreco; ĉar al kiu iu submetiĝas, al tiu ankaŭ li sklaviĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Ĉar se, forsaviĝinte el la malpuraĵoj de la mondo per la scio de la Sinjoro kaj Savanto Jesuo Kristo, ili estos denove tien implikitaj kaj venkitaj, ilia lasta stato fariĝos pli malbona, ol la unua.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Ĉar estus por ili pli bone ne ekkoni la vojon de justeco, ol, ekkoninte ĝin, returni sin for de la sankta ordono al ili transdonita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Al ili okazis laŭ la vera proverbo: Hundo reveninta al sia vomitaĵo, kaj porkino lavita al ruliĝado en koto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Jam ĉi tiun duan epistolon, amataj, mi skribas al vi; en ambaŭ mi instigas vian sinceran menson per rememorigo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'por ke vi memoru la antaŭdirojn de la sanktaj profetoj, kaj la ordonon de la Sinjoro kaj Savanto per viaj apostoloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'unue sciante, ke en la lastaj tagoj mokemuloj venos kun mokado, irante laŭ siaj propraj voluptoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'kaj dirante: Kie estas la anonco de lia alveno? ĉar de kiam la patroj endormiĝis, ĉio restas kiel de post la komenco de la kreo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Ĉar ili volonte forgesas, ke ĉielo ekzistis de antikve, kaj tero kunmetita el akvo kaj meze de akvo, laŭ la vorto de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'per kio la tiama mondo, diluvite, pereis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'sed la nuna ĉielo kaj la tero per la sama vorto estas destinitaj por fajro, rezervate ĝis la tago de juĝo kaj pereo de malpiuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Sed ne forgesu ĉi tiun unu aferon, amataj, ke ĉe la Sinjoro unu tago estas kiel mil jaroj, kaj mil jaroj kiel unu tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'La Sinjoro ne malrapidas pri la promeso, kiel iuj malrapidecon kalkulas; sed paciencas al vi, volante, ne ke iuj pereu, sed ke ĉiuj venu al pento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Sed la tago de la Sinjoro venos, kvazaŭ ŝtelisto; en tiu tago la ĉielo forpasos kun muĝa bruego, kaj la elementoj brulante solviĝos, kaj la tero kaj la faritaĵoj en ĝi forbrulos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Ĉar tiamaniere ĉio tio solviĝos, kiaj homoj vi do devus esti en sankta konduto kaj pieco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'atendante kaj akcelante la alvenon de la tago de Dio, pro kio la ĉielo flamanta solviĝos, kaj la elementoj per fajra brulado fluidiĝos?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Sed laŭ Lia promeso ni atendas novan ĉielon kaj novan teron, en kiuj loĝas justeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Tial, amataj, tion atendante, klopodu troviĝi en paco, senmakulaj kaj neriproĉindaj antaŭ Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'Kaj rigardu la paciencon de nia Sinjoro kiel savon; kiel ankaŭ nia amata frato Paŭlo, laŭ la saĝeco donita al li, jam skribis al vi,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'kiel ankaŭ en ĉiuj siaj epistoloj, parolante en ili pri ĉi tio; en kiuj estas iuj aferoj malfacile kompreneblaj, kiujn la malkleruloj kaj malkonstantuloj tordas, kiel ankaŭ la ceterajn skribaĵojn, al sia propra pereo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Vi do, amataj, ĉi tion antaŭsciante, gardu vin, por ke vi ne forlogiĝu per la eraro de la pekuloj, kaj ne defalu de via propra konstanteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Sed kresku en graco kaj scio de nia Sinjoro kaj Savanto Jesuo Kristo. Al li estu la gloro nun kaj ĝis la tago de eterneco. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Tion, kio estis de la komenco, kion ni aŭdis, kion ni vidis per niaj propraj okuloj, kion ni rigardis kaj niaj manoj palpis, koncerne la Vorton de vivo');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, '(kaj la vivo elmontriĝis, kaj ni vidis kaj atestas kaj anoncas al vi la vivon, la eternan vivon, kiu estis ĉe la Patro kaj montriĝis al ni);');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'kion ni vidis kaj aŭdis, tion ni anoncas al vi, por ke vi ankaŭ havu kunulecon kun ni; kaj nia kunuleco estas kun la Patro kaj kun Lia Filo Jesuo Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'kaj ĉi tion ni skribas, por ke nia ĝojo kompletiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Kaj jen estas la anonco, kiun ni aŭdis de Li kaj anoncas al vi, ke Dio estas lumo, kaj da mallumo estas en Li neniom.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Se ni diras, ke ni havas kunulecon kun Li, kaj iradas en la mallumo, ni mensogas, kaj ne faras la veron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'sed se ni iradas en la lumo, kiel Li estas en la lumo, ni havas kunulecon unu kun la alia, kaj la sango de Jesuo, Lia Filo, nin purigas de ĉia peko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Se ni diras, ke pekon ni ne havas, ni nin trompas, kaj la vero ne estas en ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Se ni konfesas niajn pekojn, Li estas fidela kaj justa por pardoni al ni niajn pekojn kaj nin purigi de ĉia maljusteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Se ni diras, ke ni ne pekis, ni faras Lin mensoginto, kaj Lia vorto ne estas en ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Infanetoj miaj, ĉi tion mi skribas al vi, por ke vi ne peku. Kaj se iu pekas, ni havas Advokaton ĉe la Patro, Jesuon Kriston, la justan;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'kaj li estas repacigo pro niaj pekoj, kaj ne sole pro niaj, sed ankaŭ pro la tuta mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Kaj per ĉi tio ni scias, ke ni konas lin: se ni observas liajn ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Kiu diras: Mi lin konas, kaj ne observas liajn ordonojn, tiu estas mensoganto, kaj la vero ne estas en li;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'sed en ĉiu ajn, kiu observas lian vorton, vere perfektiĝis la amo al Dio. Per ĉi tio ni scias, ke ni estas en li:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'kiu diras, ke li restas en li, tiu mem devus tiel iradi, kiel li iradis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Amataj, al vi mi skribas ne ordonon novan, sed malnovan ordonon, kiun vi havis de la komenco; la malnova ordono estas la vorto, kiun vi aŭdis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Ankaŭ mi skribas al vi novan ordonon, kiu estas vera en li kaj en vi; ĉar la mallumo forpasas, kaj la vera lumo jam brilas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Kiu diras, ke li estas en la lumo, kaj malamas sian fraton, tiu estas en la mallumo ankoraŭ ĝis nun.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Kiu amas sian fraton, tiu restas en la lumo, kaj en li ne estas faligaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Sed kiu malamas sian fraton, tiu estas en la mallumo, kaj iras en la mallumo, kaj ne scias, kien li iras, ĉar la mallumo blindigis al li la okulojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Mi skribas al vi, infanetoj, ĉar la pekoj al vi estas pardonitaj pro lia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Mi skribas al vi, patroj, ĉar vi konas tiun, kiu estas de la komenco. Mi skribas al vi, junuloj, ĉar vi venkis la malbonulon. Mi skribis al vi, infanoj, ĉar vi konas la Patron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Mi skribis al vi, patroj, ĉar vi konas tiun, kiu estas de la komenco. Mi skribis al vi, junuloj, ĉar vi estas fortaj, kaj la vorto de Dio restas en vi, kaj vi venkis la malbonulon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Ne amu la mondon, nek la mondaĵojn. Se iu amas la mondon, la amo al la Patro ne estas en li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Ĉar ĉio, kio estas en la mondo, la dezirego de la karno kaj la dezirego de la okuloj kaj la fiereco de vivo, estas ne de la Patro, sed de la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Kaj forpasas la mondo kaj ĝia dezirego; sed la plenumanto de la volo de Dio restas por eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Infanoj, jam estas la lasta horo; kaj kiel vi aŭdis, ke antikristo venas, jam leviĝis multe da antikristoj; per tio ni scias, ke estas la lasta horo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'De ni ili eliris, sed ili ne estis el ni; ĉar se ili el ni estus, ili restus ĉe ni; sed ili eliris, por ke ili elmontriĝu, ke ili ĉiuj ne estas el ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Kaj vi havas sanktoleadon de la Sanktulo, kaj vi scias ĉion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Mi skribis al vi ne pro tio, ke vi ne scias la veron, sed pro tio, ke vi ĝin scias, kaj pro tio, ke nenia mensogo estas el la vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Kiu estas la mensogisto, krom tiu, kiu malkonfesas, ke Jesuo estas la Kristo? Tiu estas la antikristo, kiu malkonfesas la Patron kaj la Filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Ĉiu, kiu malkonfesas la Filon, ne havas la Patron; tiu, kiu konfesas la Filon, havas ankaŭ la Patron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Vi do lasu resti en vi tion, kion vi aŭdis de la komenco. Se tio, kion vi aŭdis de la komenco, restos en vi, vi ankaŭ restos en la Filo kaj en la Patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'Kaj jen estas la promeso, kiun li promesis al ni: la vivo eterna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Ĉi tion mi skribis al vi pri tiuj, kiuj vin forlogas de la vojo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Pri vi, la sanktoleado, kiun vi ricevis de li, restas en vi, kaj vi ne havas bezonon, ke iu vin instruu; sed kiel lia sanktoleado vin instruas pri ĉio kaj estas vera kaj ne estas mensogo, kaj kiel ĝi vin instruis, vi restas en li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Kaj nun, infanetoj, restu en li; por ke, se li elmontriĝos, ni havu kuraĝon, kaj ne hontu antaŭ li ĉe lia alveno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Se vi scias, ke li estas justa, vi scias, ke ankaŭ ĉiu, kiu faras justecon, el li naskiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Rigardu, kian amon la Patro donis al ni, ke ni estas nomataj infanoj de Dio; kaj tiaj ni estas. Pro tio la mondo nin ne konas, ĉar ĝi Lin ne konis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Amataj, nun ni estas infanoj de Dio, kaj ankoraŭ ne elmontriĝis, kio ni estos. Ni scias, ke se li elmontriĝos, ni estos similaj al li; ĉar ni vidos lin, kiel li estas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'Kaj ĉiu, kiu havas ĉi tiun esperon rilate lin, sin sanktigas tiel same, kiel li estas sankta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Ĉiu, kiu faras pekon, faras ion kontraŭ la leĝo; kaj peko estas kontraŭleĝeco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Kaj vi scias, ke li elmontriĝis, por forigi pekojn; kaj peko ne estas en li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Ĉiu, kiu restas en li, ne pekas; ĉiu pekanto lin ne vidis, nek lin konas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Infanetoj, neniu vin forlogu; kiu faras justecon, tiu estas justa tiel same, kiel li estas justa;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'kiu faras pekon, tiu estas el la diablo; ĉar la diablo pekas de la komenco. Por tio la Filo de Dio elmontriĝis, por ke li detruu la farojn de la diablo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Ĉiu, kiu naskiĝis de Dio, ne faras pekon, ĉar lia semo restas en li; kaj li ne povas peki, ĉar li naskiĝis de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Jen kiel evidentiĝas la infanoj de Dio, kaj la infanoj de la diablo: ĉiu, kiu ne faras justecon, ne estas de Dio, nek tiu, kiu ne amas sian fraton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Ĉar jen estas la anonco, kiun vi aŭdis de la komenco: ke ni amu unu la alian;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'ne kiel Kain estis de la malbonulo kaj mortigis sian fraton. Kaj pro kio li lin mortigis? Ĉar liaj faroj estis malbonaj, kaj la faroj de lia frato estis justaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Ne miru, fratoj, se la mondo vin malamas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Ni scias, ke ni jam pasis el morto en vivon, ĉar ni amas la fratojn. Kiu ne amas, tiu restas en morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Ĉiu, kiu malamas sian fraton, estas hommortiganto; kaj vi scias, ke ĉiu hommortiganto ne havas vivon eternan, restantan en li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Per ĉi tio ni konas amon: ĉar li demetis sian vivon pro ni; kaj ni devus demeti nian vivon pro la fratoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Sed se iu havas mondan posedaĵon kaj vidas sian fraton havantan bezonon kaj fermas sian kompaton kontraŭ li, kiel la amo de Dio restas en li?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Infanetoj, ni amu, ne laŭ vorto nek laŭ lango, sed laŭ faro kaj vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Per tio ni scios, ke ni estas el la vero, kaj ni certigos nian koron antaŭ Li');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'en ĉio ajn, pri kio nia koro nin kondamnas; ĉar Dio estas pli granda ol nia koro, kaj scias ĉion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Amataj, se nia koro ne kondamnas nin, ni havas kuraĝon antaŭ Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'kaj ĉion ajn, kion ni petas, ni ricevas de Li, ĉar ni observas Liajn ordonojn, kaj faras tion, kio plaĉas antaŭ Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'Kaj jen estas Lia ordono, ke ni kredu al la nomo de Lia Filo, Jesuo Kristo, kaj amu unu la alian tiel same, kiel Li al ni donis ordonon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Kaj kiu observas Liajn ordonojn, tiu en Li restas, kaj Li en tiu. Kaj per tio ni scias, ke Li restas en ni: per la Spirito, kiun Li donis al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Amataj, kredu ne al ĉiu spirito, sed provu la spiritojn, ĉu ili estas el Dio; ĉar multaj falsaj profetoj eliris en la mondon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Jen kiel vi ekkonas la Spiriton de Dio: ĉiu spirito, kiu konfesas, ke Jesuo Kristo venis en la karno, estas el Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'kaj ĉiu spirito, kiu ne konfesas Jesuon, ne estas el Dio; kaj ĉi tiu estas la spirito de antikristo, pri kiu vi aŭdis, ke ĝi venas; kaj nun ĝi jam estas en la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Infanetoj, vi estas el Dio, kaj ilin venkis; ĉar pli granda estas Tiu, kiu estas en vi, ol tiu, kiu estas en la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Ili estas el la mondo; pro tio ili parolas laŭ la mondo, kaj la mondo ilin aŭskultas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Ni estas el Dio; kiu konas Dion, tiu nin aŭskultas; kiu ne estas el Dio, tiu nin ne aŭskultas. Jen kiel ni ekkonas la spiriton de vero, kaj la spiriton de eraro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Amataj, ni amu unu la alian; ĉar la amo estas el Dio; kaj ĉiu, kiu amas, naskiĝas el Dio kaj Dion konas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Kiu ne amas, tiu ne konas Dion, ĉar Dio estas amo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Jen kiel la amo de Dio elmontriĝis en ni: ke Dio sendis en la mondon Sian Filon solenaskitan, por ke ni vivu per li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Jen estas la amo, ne ke ni amis Dion, sed ke Li amis nin, kaj sendis Sian Filon kiel repacigon pro niaj pekoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Amataj, se Dio tiel amis nin, ni ankaŭ devus ami unu la alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Dion neniu iam vidis; se ni reciproke nin amas, Dio restas en ni, kaj Lia amo perfektiĝis en ni;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'jen kiel ni scias, ke ni restas en Li, kaj Li en ni: ĉar el Sia Spirito Li donis al ni.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Kaj ni vidis kaj atestas, ke la Patro sendis la Filon por esti la Savonto de la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'En ĉiu ajn, kiu konfesas, ke Jesuo estas la Filo de Dio, Dio restas, kaj li en Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Kaj ni konas kaj kredis la amon, kiun Dio havas al ni. Dio estas amo; kaj kiu restas en amo, tiu restas en Dio, kaj Dio restas en li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'Jen kiel amo perfektiĝis ĉe ni: ke ni havu kuraĝon en la tago de juĝo; ĉar ĝuste kia li estas, tiaj ankaŭ ni estas en ĉi tiu mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Timo ne ekzistas en amo; sed perfekta amo elĵetas timon, ĉar timo havas turmentegon; kaj timanto ne perfektiĝas en amo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Ni amas, ĉar Li unue nin amis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Se iu diras: Mi amas Dion, kaj malamas sian fraton-tiu estas mensoganto; ĉar kiu ne amas sian fraton, kiun li vidis, tiu ne povas ami Dion, kiun li ne vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Kaj la jenan ordonon ni havas de Li: ke kiu amas Dion, tiu amu ankaŭ sian fraton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Ĉiu, kiu kredas, ke Jesuo estas la Kristo, naskiĝis el Dio; kaj ĉiu, kiu amas la Naskinton, amas ankaŭ la naskiton el Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Per tio ni ekscias, ke ni amas la infanojn de Dio, kiam ni amas Dion kaj plenumas Liajn ordonojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Ĉar jen estas la amo al Dio: ke ni observas Liajn ordonojn; kaj Liaj ordonoj ne estas pezaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Ĉar ĉio, kio el Dio naskiĝis, venkas la mondon; kaj jen estas la venko venkinta la mondon: nia fido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Kaj kiu estas la venkanto de la mondo, krom tiu, kiu kredas, ke Jesuo estas la Filo de Dio?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Ĉi tiu estas la veninto per akvo kaj sango, Jesuo Kristo; ne sole en la akvo, sed en la akvo kaj en la sango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Kaj la Spirito estas la atestanto, ĉar la Spirito estas la vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'Ĉar tri estas la atestantoj: la Spirito, kaj la akvo, kaj la sango; kaj la tri en unu konsentas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Se ni akceptas la ateston de homoj, pli granda estas la atesto de Dio; ĉar jen estas la atesto de Dio: ke Li atestis pri Sia Filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Kiu kredas al la Filo de Dio, tiu havas en si la ateston; kiu ne kredas al Dio, tiu faris Lin mensoginto, pro tio, ke li ne kredis la ateston, kiun Dio atestis pri Sia Filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Kaj jen estas la atesto: ke Dio donis al ni la vivon eternan; kaj tiu vivo estas en Lia Filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Kiu havas la Filon, tiu havas la vivon; kiu ne havas la Filon de Dio, tiu la vivon ne havas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Ĉi tion mi skribis al vi, por ke vi sciu, ke vi havas vivon eternan; al vi, kiuj kredas al la nomo de la Filo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'Kaj jen estas la kuraĝo, kiun ni havas antaŭ Li: ke se ni ion petas laŭ lia volo, Li nin aŭskultas;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'kaj se ni scias, ke kion ajn ni petas, Li nin aŭskultas, ni scias, ke ni havas la petojn, kiujn ni petis de Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Se iu vidas sian fraton pekantan pekon ne al morto, tiu petos, kaj Li donos al li vivon, por la pekantoj ne al morto. Ekzistas peko al morto; ne pri tio mi diras, ke li petegu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Ĉia nejusteco estas peko; kaj ekzistas peko ne al morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Ni scias, ke ĉiu naskito el Dio ne pekas; sed la naskito el Dio sin gardas, kaj la malbonulo lin ne tuŝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Ni scias, ke ni el Dio estas, kaj la tuta mondo kuŝas en la malbonulo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Kaj ni scias, ke la Filo de Dio venis kaj al ni donis komprenon, por ke ni ekkonu la Verulon; kaj ni estas en la Verulo, en Lia Filo, Jesuo Kristo. Tiu estas la vera Dio, kaj la vivo eterna.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Infanetoj, gardu vin kontraŭ idoloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'La presbitero al la elektita sinjorino kaj ŝiaj infanoj, kiujn mi amas en la vero; kaj ne mi sola, sed ankaŭ ĉiuj, kiuj konas la veron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'pro la vero restanta en ni, kaj ĝi estos ĉe ni por ĉiam:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Graco, kompato, paco, estos ĉe ni, de Dio, la Patro, kaj de Jesuo Kristo, la Filo de la Patro, en vero kaj amo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Mi treege ĝojas, ke mi trovis iujn el viaj infanoj iradantajn en la vero tiel same, kiel ni ricevis ordonon de la Patro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'Kaj nun mi vin petegas, sinjorino, skribante ne kvazaŭ novan ordonon al vi, sed tiun, kiun ni havis de la komenco, ke ni amu unu la alian.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'Kaj jen estas la amo: ke ni iradu laŭ Liaj ordonoj. Tio estas la ordono, tiu sama, kiun vi aŭdis de la komenco, ke vi iradu en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Ĉar multaj delogantoj eliris en la mondon, kiuj ne konfesas Jesuon Kriston venantan en karno. Tio estas la deloganto kaj la antikristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Gardu vin, ke vi ne perdu viajn elfaritaĵojn, sed ke vi ricevu plenan rekompencon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Ĉiu, kiu iras antaŭen kaj ne restas en la instruado de Kristo, ne havas Dion; kiu restas en la instruado, tiu havas kaj la Patron kaj la Filon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Se iu al vi venas kaj ne kunportas ĉi tiun instruadon, ne ricevu lin en la domon, kaj al li ne donu salutan vorton;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'ĉar kiu al li salute parolas, tiu partoprenas en liaj malbonfaroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Havante multon por skribi al vi, mi ne volis skribi per papero kaj inko; sed mi esperas veni al vi kaj paroli vizaĝon kontraŭ vizaĝo, por ke via ĝojo estu plena.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Salutas vin la infanoj de via fratino, la elektita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'La presbitero al Gajo, la amata, kiun mi amas en la vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Amato, mi preĝas, ke al vi prosperu ĉio, kaj vi bonsanu tiel same, kiel prosperas al via animo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Ĉar mi treege ĝojis, kiam fratoj venis kaj atestis pri via vereco, kiel vi iradas en la vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Pli grandan ĝojon mi ne havas, ol aŭdi pri miaj infanoj iradantaj en la vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Amato, vi faras fidele rilate al ĉiuj viaj klopodoj por la fratoj kaj tiuj fremduloj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'kiuj atestis vian amon antaŭ la eklezio; kaj vi faros bone, tiujn antaŭenigante dece je Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'ĉar pro la Nomo ili eliris, akceptante nenion de la nacianoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Ni devas do akcepti tiajn, por ke ni estu kunlaborantoj kun la vero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Mi skribis iom al la eklezio; sed Diotrefes, kiu amas la estrecon inter ili, nin ne akceptas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Tial, se mi venos, mi rememorigos al li la farojn, kiujn li faras, per malbonaj paroloj babilante kontraŭ ni; kaj ne kontenta je tio, li mem ne akceptas la fratojn, nek tion permesas al tiuj, kiuj volas, kaj ilin el la eklezio elpelas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Amato, imitu ne la malbonon, sed la bonon. Bonfaranto estas el Dio; malbonfaranto ne vidis Dion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Pri Demetrio estas atestite de ĉiuj, kaj de la vero mem; kaj ni ja atestas; kaj vi scias, ke nia atesto estas vera.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Mi havis multon por skribi al vi; sed mi ne volas skribi al vi per inko kaj kano;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'sed mi esperas vidi vin baldaŭ, kaj ni parolos vizaĝon kontraŭ vizaĝo. Paco al vi. Salutas vin la amikoj. Salutu laŭ nomo la amikojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Judas, servisto de Jesuo Kristo kaj frato de Jakobo, al la alvokitoj, amataj en Dio, la Patro, kaj konservitaj por Jesuo Kristo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Kompato al vi kaj paco kaj amo pligrandiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Amataj, kiam mi faris ĉian diligentecon, por skribi al vi pri nia komuna savo, mi deviĝis skribi al vi, por kuraĝigi vin batali por la kredo, jam per unu fojo transdonita al la sanktuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Ĉar enŝteliĝis iuj homoj, jam antaŭ longe destinitaj por ĉi tiu kondamno, malpiuloj, ŝanĝante la gracon de nia Dio en diboĉecon, kaj malkonfesante la solan Estron kaj nian Sinjoron Jesuo Kristo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Mi do volas rememorigi vin, kvankam vi jam per unu fojo sciiĝis pri ĉio, ke la Sinjoro, savinte popolon el la Egipta lando, poste pereigis la nekredantojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'Kaj anĝelojn, kiuj ne konservis sian regadon, sed forlasis sian propran loĝejon, Li rezervis sub mallumo en katenoj ĉiamaj ĝis la juĝo en la granda tago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Kiel ankaŭ Sodom kaj Gomora kaj la ĉirkaŭaj urboj tiel same, kiel ĉi tiuj, malĉastiĝinte kaj foririnte post fremdan karnon, estas elmontritaj kiel ekzemplo, suferante la punon de eterna fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Tamen tiel same ankaŭ ĉi tiuj en siaj sonĝadoj malpurigas la karnon, malestimas aŭtoritaton, kaj insultas honorojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Sed Miĥael, la ĉefanĝelo, kiam en kontraŭstaro al la diablo li disputis pri la korpo de Moseo, ne kuraĝis lin akuzi insulte, sed diris: La Sinjoro vin riproĉu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Sed tiuj insultas ja ĉion, kion ili ne scias; sed kion ili per naturo komprenas, kiel la bestoj senprudentaj, en tio ili malvirtiĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Ve al ili! ĉar ili iris sur la vojo de Kain, kaj forĵetis sin en la eraron de Bileam por dungopago, kaj pereis en la kontraŭdirado de Koraĥ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Ili estas la subakvaj rokoj en viaj agapoj, kun vi kunfestenante, sentime sin paŝtante; nuboj senakvaj, per vento disportataj; aŭtunaj arboj senfruktaj, dufoje mortintaj, elradikigitaj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'sovaĝaj marondoj, elŝaŭmantaj siajn hontindaĵojn; steloj vagantaj, por kiuj la nigreco de mallumo por eterne estas rezervata.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Kaj al ili ankaŭ Ĥanoĥ, la sepa post Adam, profetis, dirante: Jen la Sinjoro venis kun Siaj sanktaj miriadoj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'por fari juĝon kontraŭ ĉiuj, kaj por kondamni ĉiujn malpiulojn pri ĉiuj malpiaĵoj, kiujn ili malpie faris, kaj pri ĉiuj obstinaj paroloj, kiujn malpiaj pekuloj parolis kontraŭ Li.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Ili estas murmuremuloj, plendemuloj, irantaj laŭ siaj voluptoj (dum ilia buŝo parolas fanfaronaĵojn) kaj favorantaj personojn pro profito.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Sed vi, amataj, memoru la dirojn antaŭe parolitajn de la apostoloj de nia Sinjoro Jesuo Kristo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'nome, ke ili diris al vi: En la lasta tempo estos mokemuloj, irantaj laŭ siaj propraj voluptoj malpiaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Tiuj estas la apartigantoj, laŭsentaj, ne havantaj la Spiriton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Sed vi, amataj, konstruante vin sur via plej sankta fido, preĝante en la Sankta Spirito,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'konservu vin en la amo al Dio, atendante la kompaton de nia Sinjoro Jesuo Kristo por eterna vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'Kaj unujn, kiuj ŝanceliĝas, indulgu;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'kaj unujn savu, eltirante ilin el la fajro; kaj aliajn kompatu kun timo; malamante eĉ la veston makulitan de la karno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Kaj al Tiu, kiu povas vin gardi senfalaj, kaj starigi vin senriproĉaj antaŭ Sia gloro en granda ĝojo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'al la sola Dio, nia Savanto, per Jesuo Kristo, nia Sinjoro, estu gloro, majesto, potenco, kaj aŭtoritato, antaŭ ĉiu mondaĝo, kaj nun, kaj ĝis la eterneco. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Apokalipso de Jesuo Kristo, kiun Dio donis al li, por montri al siaj servistoj tion, kio devas baldaŭ okazi; kaj Li sendis kaj montris ĝin per Sia anĝelo al Sia servisto Johano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'kiu atestis la vorton de Dio kaj la ateston de Jesuo Kristo, pri ĉio, kion li vidis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Feliĉaj estas la leganto kaj la aŭskultantoj de la vortoj de la profetaĵo kaj la observantoj de la skribitaĵoj en ĝi; ĉar la tempo estas proksima.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Johano al la sep eklezioj en Azio: Graco al vi kaj paco de Tiu, kiu estas kaj estis kaj venos; kaj de la sep spiritoj antaŭ Lia trono;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'kaj de Jesuo Kristo, la fidela atestanto, la unuenaskita el la mortintoj, kaj la reganto de la reĝoj de la tero. Al tiu, kiu nin amas, kaj nin malligis de niaj pekoj per sia sango,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'kaj faris nin regno, pastroj al lia Dio kaj Patro; al li la gloro kaj la potenco por ĉiam kaj eterne. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Jen li venas kun la nuboj; kaj lin vidos ĉiu okulo, kaj tiuj, kiuj lin trapikis; kaj ĉiuj gentoj de la tero ploros pro li. Vere, Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Mi estas la Alfa kaj la Omega, diras la Sinjoro, la Dio, kiu estas kaj estis kaj venos, la Plejpotenca.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Mi, Johano, via frato kaj partoprenanto kun vi en la aflikto kaj regno kaj pacienco de Jesuo, estis sur la insulo nomata Patmos pro la vorto de Dio kaj la atesto de Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Mi min trovis en la Spirito en la tago de la Sinjoro, kaj mi aŭdis malantaŭ mi grandan voĉon kvazaŭ de trumpeto,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'dirantan: Kion vi vidas, tion skribu en libron kaj sendu al la sep eklezioj: al Efeso kaj al Smirna kaj al Pergamo kaj al Tiatira kaj al Sardes kaj al Filadelfia kaj al Laodikea.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Kaj mi min turnis, por vidi la voĉon, kiu parolis kun mi. Kaj turniĝinte, mi vidis sep orajn lampingojn;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'kaj meze de la sep lampingoj iun similan al la Filo de homo, vestitan ĝispiede, kaj zonitan ĉirkaŭ la brusto per ora zono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Kaj lia kapo kaj liaj haroj estis blankaj kiel blanka lano, kiel neĝo; kaj liaj okuloj estis kiel fajra flamo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'kaj liaj piedoj estis kiel brilanta latuno, kvazaŭ rafinita en forno; kaj lia voĉo estis kiel voĉo de multaj akvoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'Kaj li havis en sia dekstra mano sep stelojn; kaj el lia buŝo eliris akra dutranĉa glavo; kaj lia aspekto estis kiel brilas la suno en sia forteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Kaj kiam mi vidis lin, mi falis ĉe liaj piedoj kvazaŭ senviva. Kaj li metis sian dekstran manon sur min, dirante: Ne timu; mi estas la unua kaj la lasta,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'kaj la vivanta; kaj mi fariĝis mortinta, kaj jen, mi estas vivanta por ĉiam kaj eterne, kaj mi havas la ŝlosilojn de la morto kaj de Hades.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Skribu do tion, kion vi vidis, kaj kio estas, kaj kio okazos poste;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'la misteron de la sep steloj, kiujn vi vidis en mia dekstra mano, kaj la sep orajn lampingojn. La sep steloj estas la anĝeloj de la sep eklezioj; kaj la sep lampingoj estas la sep eklezioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Al la anĝelo de la eklezio en Efeso skribu: Tiele diras la tenanto de la sep steloj en sia dekstra mano, la iranto meze de la sep oraj lampingoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Mi scias viajn farojn, kaj vian laboron kaj vian paciencon, kaj ke vi ne povas toleri la malbonulojn, kaj ke vi provis tiujn, kiuj nomas sin apostoloj kaj ne estas tiaj, kaj trovis ilin malveraj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'kaj vi havas paciencon kaj toleris pro mia nomo kaj ne laciĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Sed mi havas kontraŭ vi, ke vi forlasis vian unuan amon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Memoru do, de kie vi falis, kaj pentu, kaj faru la unuajn farojn; alie mi venos al vi, kaj formovos vian lampingon el ĝia loko, se vi ne pentos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Sed ĉi tion vi havas, ke vi malamas la farojn de la Nikolaitoj, kiujn mi ankaŭ malamas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj. Al la venkanto mi donos manĝi el la arbo de vivo, kiu estas en la Paradizo de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Kaj al la anĝelo de la eklezio en Smirna skribu: Tiele diras la unua kaj la lasta, kiu fariĝis senviva kaj vivis:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Mi scias vian aflikton kaj vian malriĉecon (vi tamen estas riĉa), kaj la blasfemon de tiuj, kiuj nomas sin Judoj, kaj estas ne tiaj, sed sinagogo de Satano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Ne timu tion, kion vi suferos; jen la diablo ĵetos iujn el vi en malliberejon, por ke vi estu elprovataj; kaj vi havos aflikton dek tagojn. Estu fidela ĝis morto, kaj mi donos al vi la kronon de vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj. La venkanto tute ne difektiĝos de la dua morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'Kaj al la anĝelo de la eklezio en Pergamo skribu: Tiele diras la portanto de la akra dutranĉa glavo:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Mi scias, kie vi loĝas: tie, kie estas la trono de Satano; kaj vi tenas firme mian nomon, kaj ne malkonfesis mian fidon, eĉ en la tagoj de Antipas, mia fidela atestinto, kiu estis mortigita inter vi, kie loĝas Satano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Sed mi havas kelkon kontraŭ vi: ke vi havas tie sekvantojn de la instruo de Bileam, kiu instruis al Balak ĵeti falilon antaŭ la Izraelidojn, por ke ili manĝu idoloferitaĵojn kaj malĉastu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Kaj vi ankaŭ havas sekvantojn de la instruo de la Nikolaitoj tiel same.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Pentu do; alie mi rapide venos al vi, kaj militos kontraŭ ili per la glavo de mia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj. Al la venkanto mi donos el la kaŝita manao, kaj mi donos al li blankan ŝtoneton, kaj sur la ŝtoneto novan nomon skribitan, kiun konas neniu krom la ricevanto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Kaj al la anĝelo de la eklezio en Tiatira skribu: Tiele diras la Filo de Dio, kiu havas okulojn kiel fajra flamo, kaj liaj piedoj estas kiel brilanta latuno:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Mi scias viajn farojn, kaj viajn amon kaj fidon kaj servadon kaj paciencon, kaj pri viaj faroj, ke la lastaj estas pli multaj ol la unuaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Sed mi havas kontraŭ vi, ke vi toleras la virinon Izebel, kiu nomas sin profetino; kaj ŝi instruas kaj delogas miajn servistojn malĉasti kaj manĝi idoloferitaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Kaj mi donis al ŝi tempon, por ke ŝi pentu; kaj ŝi ne volas penti pri sia malĉasteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Jen mi ĵetos ŝin en liton, kaj la kun ŝi adultantojn en grandan aflikton, se ili ne pentos pri ŝiaj faroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'Kaj mi pereigos ŝiajn idojn per morto; kaj ĉiuj eklezioj scios, ke mi estas tiu, kiu esploras internaĵojn kaj korojn; kaj mi donos al ĉiu el vi laŭ viaj faroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Sed al vi mi diras, al la ceteraj en Tiatira, al ĉiuj, kiuj ne havas ĉi tiun instruon, kaj kiuj ne konas la profundaĵojn de Satano, kiel oni diras: Mi ne ĵetos sur vin alian ŝarĝon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Tamen tion, kion vi havas, tenu, ĝis mi venos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'Kaj al la venkanto kaj la observanto de miaj faroj ĝis la fino mi donos aŭtoritaton super la nacioj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'kaj li regos ilin per fera sceptro, kiel la potaj vazoj estas dispecigataj; kiel mi ankaŭ ricevis de mia Patro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'kaj mi donos al li la matenan stelon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Kaj al la anĝelo de la eklezio en Sardes skribu: Tiele diras tiu, kiu havas la sep Spiritojn de Dio, kaj la sep stelojn: Mi scias viajn farojn, ke vi estas nomata viva, kaj estas malviva.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Fariĝu vigla, kaj firmigu la restaĵojn, kiuj estis preskaŭ mortantaj; ĉar mi ne trovis viajn farojn plenumitaj antaŭ mia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Memoru do, kiel vi ricevis kaj aŭdis; kaj observu, kaj pentu. Se do vi ne viglos, mi venos, kvazaŭ ŝtelisto, kaj vi ne scios, je kiu horo mi venos al vi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Sed vi havas en Sardes kelkajn nomojn, kiuj ne makulis siajn vestojn; kaj ili promenos kun mi en blankaĵoj; ĉar ili estas indaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'La venkanto estos tiel vestita per blankaj vestoj; kaj mi ja ne elstrekos lian nomon el la libro de vivo, kaj mi konfesos lian nomon antaŭ mia Patro kaj antaŭ Liaj anĝeloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'Kaj al la anĝelo de la eklezio en Filadelfia skribu: Tiele diras la sanktulo, la verulo, kiu havas la ŝlosilon de David, tiu, kiu malfermas, kaj neniu fermas; kiu fermas, kaj neniu malfermas:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Mi scias viajn farojn (jen mi donis antaŭ vi pordon malfermitan, kiun neniu povas fermi), ke vi havas kelkan potencon, kaj observis mian vorton, kaj ne malkonfesis mian nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Jen mi donas el la sinagogo de Satano, kiuj sin nomas Judoj, kaj estas ne tiaj, sed mensogas; jen mi igos ilin veni kaj adorkliniĝi antaŭ viaj piedoj, kaj scii, ke mi vin amis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Ĉar vi observis la vorton de mia pacienco, mi ankaŭ vin konservos el tiu horo de provo, kiu venos sur la tutan mondon, por provi la loĝantojn sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Mi venos rapide; tenadu tion, kion vi havas, por ke neniu forprenu vian kronon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'La venkanton mi faros kolono en la templo de mia Dio, kaj li ne plu eliros el ĝi; kaj mi skribos sur li la nomon de mia Dio, kaj la nomon de la urbo de mia Dio, la nova Jerusalem, kiu venas malsupren de mia Dio el la ĉielo, kaj mian novan nomon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Kaj al la anĝelo de la eklezio en Laodikea skribu: Tiele diras la Amen, la atestanto fidela kaj vera, la komenco de la kreo de Dio:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Mi scias viajn farojn, ke vi estas nek malvarma, nek varmega; mi volus, ke vi estu aŭ malvarma aŭ varmega.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Tial, ĉar vi estas varmeta, kaj nek malvarma nek varmega, mi elsputos vin el mia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Ĉar vi diras: Mi estas riĉa kaj akiris riĉon, kaj nenion mi bezonas; kaj vi ne scias, ke vi estas la mizera kaj kompatinda kaj malriĉa kaj blinda kaj nuda;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'mi konsilas al vi aĉeti de mi oron rafinitan per fajro, por ke vi riĉiĝu; kaj blankajn vestojn, por ke vi vin vestu, kaj por ke ne aperu la honto de via nudeco; kaj kolirion, por ŝmiri viajn okulojn, por ke vi vidu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Ĉiujn, kiujn mi amas, mi riproĉas kaj punas; estu do fervora, kaj pentu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Jen mi staras ĉe la pordo kaj frapas; se iu aŭdas mian voĉon kaj malfermas la pordon, mi eniros al li kaj manĝos kun li, kaj li kun mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Al la venkanto mi donos sidiĝi kun mi sur mia trono, kiel mi ankaŭ venkis kaj sidiĝis kun mia Patro sur Lia trono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Kiu havas orelon, tiu aŭskultu, kion la Spirito diras al la eklezioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Post tio mi rigardis, kaj jen pordo malfermita en la ĉielo, kaj la unua voĉo, kiun mi aŭdis, estis voĉo kvazaŭ de trumpeto parolanta kun mi, dirante: Suprenvenu ĉi tien, kaj mi montros al vi tion, kio devas okazi poste.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Tuj mi min trovis en la Spirito; kaj jen trono stariĝis en la ĉielo, kaj sur la trono unu sidanta;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'kaj la Sidanto estis en aspekto simila al ŝtono jaspisa kaj sardia; kaj jen ĉielarko ĉirkaŭ la trono, aspekte simila al smeraldo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Kaj ĉirkaŭ la trono estis dudek kvar tronoj; kaj sur la tronoj mi vidis dudek kvar presbiterojn sidantajn, vestitajn per blankaj vestoj; kaj sur iliaj kapoj orajn kronojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Kaj el la trono eliris fulmoj kaj voĉoj kaj tondroj. Kaj antaŭ la trono brulis sep fajraj torĉoj, kiuj estas la sep Spiritoj de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'kaj antaŭ la trono kvazaŭ vitra maro, simila al kristalo; kaj meze apud la trono kaj ronde ĉirkaŭ la trono kvar kreitaĵoj, plenaj de okuloj antaŭe kaj malantaŭe.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Kaj la unua kreitaĵo similis leonon, kaj la dua kreitaĵo similis bovidon, kaj la tria kreitaĵo havis vizaĝon kvazaŭ homan, kaj la kvara kreitaĵo similis aglon flugantan.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Kaj la kvar kreitaĵoj, havantaj po ses flugiloj, estas ĉirkaŭe kaj interne plenaj de okuloj; kaj paŭzon ili ne havas tage kaj nokte, dirante: Sankta, sankta, sankta, estas Dio, la Sinjoro, la Plejpotenca, la estanta kaj estinta kaj venonta.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Kaj kiam la kreitaĵoj donos gloron kaj honoron kaj dankon al la Sidanto sur la trono, al la Vivanto por ĉiam kaj eterne,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'la dudek kvar presbiteroj falos antaŭ la Sidanto sur la trono, kaj ili adorkliniĝos al la Vivanto por ĉiam kaj eterne, kaj ĵetos siajn kronojn antaŭ la trono, dirante:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Inda Vi estas, ho nia Sinjoro kaj nia Dio, ricevi la gloron kaj la honoron kaj la potencon; ĉar Vi kreis ĉion, kaj pro Via volo ĉio ekzistis kaj kreiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Kaj mi vidis en la dekstra mano de la Sidanto sur la trono libron, skribitan interne kaj malantaŭe, sigelitan per sep sigeloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'Kaj mi vidis fortan anĝelon, proklamantan per granda voĉo: Kiu estas inda malfermi la libron kaj rompi ĝiajn sigelojn?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Kaj neniu en la ĉielo, nek sur la tero, nek sub la tero, povis malfermi la libron, aŭ rigardi ĝin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Kaj mi multe ploris, ĉar troviĝis neniu inda malfermi la libron, aŭ ĝin rigardi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'kaj unu el la presbiteroj diris al mi: Ne ploru; jen la leono el la tribo de Jehuda, la Markoto de David, venkis, por malfermi la libron kaj ĝiajn sep sigelojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Kaj mi vidis meze inter la trono kaj la kvar kreitaĵoj, kaj meze de la presbiteroj, Ŝafidon starantan, kvazaŭ oferbuĉitan, havantan sep kornojn kaj sep okulojn, kiuj estas la sep Spiritoj de Dio, senditaj sur la tutan teron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Kaj li venis, kaj prenis ĝin el la dekstra mano de la Sidanto sur la trono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'Kaj kiam li prenis la libron, la kvar kreitaĵoj kaj la dudek kvar presbiteroj falis antaŭ la Ŝafido, havantaj ĉiu harpon, kaj orajn pelvojn plenajn de incenso, kiuj estas la preĝoj de la sanktuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'Kaj ili kantis novan kanton, dirante: Vi estas inda preni la libron kaj malfermi ĝiajn sigelojn; ĉar vi estis mortigita, kaj vi elaĉetis al Dio per via sango homojn el ĉiu tribo kaj lingvo kaj popolo kaj nacio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'kaj faris ilin al nia Dio regno kaj pastroj; kaj ili reĝas sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Kaj mi rigardis, kaj mi aŭdis voĉon de multaj anĝeloj, ronde ĉirkaŭ la trono kaj la kreitaĵoj kaj la presbiteroj; kaj ilia nombro estis miriadoj da miriadoj kaj miloj da miloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'dirantaj per granda voĉo: Inda estas la Ŝafido, la mortigita, ricevi la potencon kaj riĉon kaj saĝecon kaj forton kaj honoron kaj gloron kaj laŭdon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'Kaj ĉiun kreitaĵon, kiu estis en la ĉielo kaj sur la tero kaj sub la tero kaj sur la maro, kaj ĉion en ili, mi aŭdis dirantajn: Al la Sidanto sur la trono, kaj al la Ŝafido, estu la laŭdo kaj la honoro kaj la gloro kaj la potenco por ĉiam kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Kaj la kvar kreitaĵoj diris: Amen. Kaj la presbiteroj falis kaj adorkliniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'Kaj mi rigardis, kiam la Ŝafido malfermis unu el la sep sigeloj, kaj mi aŭdis unu el la kvar kreitaĵoj dirantan kvazaŭ per voĉo de tondro: Venu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'Kaj mi rigardis, kaj jen blanka ĉevalo, kaj la sidanta sur ĝi havis pafarkon; kaj estis donita al li krono; kaj li eliris venkanta, kaj por venki.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'Kaj kiam li malfermis la duan sigelon, mi aŭdis la duan kreitaĵon dirantan: Venu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'Kaj eliris alia ĉevalo, flamkolora; kaj al la sidanta sur ĝi estis donite forpreni pacon de la tero, kaj ke oni mortigu unu la alian; kaj al li estis donita granda glavo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'Kaj kiam li malfermis la trian sigelon, mi aŭdis la trian kreitaĵon dirantan: Venu. Kaj mi rigardis, kaj jen nigra ĉevalo; kaj la sidanta sur ĝi havis en la mano pesilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'Kaj mi aŭdis kvazaŭ voĉon, meze de la kvar kreitaĵoj, dirantan: Mezuro da tritiko por denaro, kaj tri mezuroj da hordeo por denaro; kaj la oleon kaj la vinon ne difektu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'Kaj kiam li malfermis la kvaran sigelon, mi aŭdis la voĉon de la kvara kreitaĵo dirantan: Venu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'Kaj mi rigardis, kaj jen pala ĉevalo; kaj la nomo de la sidanta sur ĝi estis Morto; kaj Hades sekvis kun li. Kaj estis donita al ili aŭtoritato super kvarono de la tero, por mortigi per glavo kaj per malsato kaj per morto kaj per la sovaĝaj bestoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Kaj kiam li malfermis la kvinan sigelon, mi vidis sub la altaro la animojn de la mortigitaj pro la vorto de Dio kaj pro la atesto, kiun ili havadis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'kaj ili kriis per granda voĉo, dirante: Ĝis kiam, ho Estro, la sankta kaj vera, Vi ne juĝas kaj ne venĝas nian sangon al la loĝantoj sur la tero?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Kaj estis donita al ĉiu el ili blanka robo; kaj estis dirite al ili, ke ili atendu ankoraŭ kelkan tempon, ĝis ankaŭ iliaj kunservistoj kaj iliaj fratoj, mortigotaj kiel ili mem, plensumiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Kaj mi rigardis, kiam li malfermis la sesan sigelon, kaj fariĝis granda tertremo; kaj la suno fariĝis nigra kiel sakaĵo el haroj, kaj la tuta luno fariĝis kiel sango;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'kaj la steloj de la ĉielo falis sur la teron, kiel figarbo, skuate de forta vento, ĵetas siajn nematurajn figojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'Kaj la ĉielo formoviĝis, kvazaŭ kunvolvata libro; kaj ĉiu monto kaj ĉiu insulo formoviĝis de sia loko.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Kaj la reĝoj de la tero kaj la granduloj kaj la milestroj kaj la riĉuloj kaj la fortuloj kaj ĉiu sklavo kaj ĉiu liberulo sin kaŝis en la kavernoj kaj inter la rokoj de la montoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'kaj ili diris al la montoj kaj al la rokoj: Falu sur nin, kaj nin kaŝu for de la vizaĝo de la Sidanto sur la trono, kaj for de la kolero de la Ŝafido;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'ĉar venis la granda tago de ilia kolero; kaj kiu povas stari?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Post tio mi vidis kvar anĝelojn starantajn sur la kvar anguloj de la tero, retenantajn la kvar ventojn de la tero, por ke ne blovu vento sur la teron, nek sur la maron, nek sur ian arbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'Kaj mi vidis alian anĝelon suprenirantan de la sunleviĝo, havantan sigelilon de la vivanta Dio; kaj li ekkriis per granda voĉo al la kvar anĝeloj, al kiuj estis donite difekti la teron kaj la maron,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'dirante: Ne difektu la teron, nek la maron, nek la arbojn, antaŭ ol ni sigelos sur iliaj fruntoj la servistojn de nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'Kaj mi aŭdis la nombron de la sigelitoj, cent kvardek kvar miloj, sigelitaj el ĉiuj triboj de la Izraelidoj:');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'El la tribo de Jehuda estis sigelitaj dek du miloj; El la tribo de Ruben, dek du miloj; El la tribo de Gad, dek du miloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'El la tribo de Aŝer, dek du miloj; El la tribo de Naftali, dek du miloj; El la tribo de Manase, dek du miloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'El la tribo de Simeon, dek du miloj; El la tribo de Levi, dek du miloj; El la tribo de Isaĥar, dek du miloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'El la tribo de Zebulun, dek du miloj; El la tribo de Jozef, dek du miloj; El la tribo de Benjamen estis sigelitaj dek du miloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Post tio mi rigardis, kaj jen granda homamaso, kiun neniu povis kalkuli, el ĉiu nacio, kaj el ĉiuj triboj kaj popoloj kaj lingvoj, starantaj antaŭ la trono kaj antaŭ la Ŝafido, vestitaj per blankaj roboj, kaj kun palmoj en iliaj manoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'kaj ili kriis per granda voĉo, dirante: Savo al nia Dio, la sidanta sur la trono, kaj al la Ŝafido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'Kaj ĉiuj anĝeloj staris ĉirkaŭ la trono kaj la presbiteroj kaj la kvar kreitaĵoj; kaj ili falis sur sian vizaĝon antaŭ la trono, kaj adorkliniĝis al Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'dirante: Amen; La laŭdo kaj la gloro kaj la saĝeco kaj la danko kaj la honoro kaj la potenco kaj la forto estu al nia Dio por ĉiam kaj eterne. Amen.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'Kaj respondis unu el la presbiteroj, dirante al mi: Kiuj estas ĉi tiuj per blankaj roboj vestitaj, kaj de kie ili venis?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'Kaj mi diris al li: Mia sinjoro, vi scias. Kaj li diris al mi: Ĉi tiuj estas la venantoj el la granda afliktado, kaj ili lavis siajn robojn, kaj blankigis ilin en la sango de la Ŝafido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'Tial ili estas antaŭ la trono de Dio; kaj ili servas al Li tage kaj nokte en Lia templo; kaj la Sidanto sur la trono etendos super ili Sian tabernaklon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Ili ne plu malsatos, nek plu soifos; ne frapos ilin la suno nek ia varmego;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'ĉar la Ŝafido, kiu estas meze de la trono, paŝtos ilin kaj kondukos ilin al akvofontoj de vivo; kaj Dio forviŝos de iliaj okuloj ĉiun larmon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'Kaj kiam li malfermis la sepan sigelon, fariĝis silento en la ĉielo por ĉirkaŭ duono de horo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'Kaj mi vidis la sep anĝelojn, kiuj staras antaŭ Dio; kaj estis donitaj al ili sep trumpetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'Kaj alia anĝelo venis, kaj staris apud la altaro, havante incensilon oran; kaj estis donita al li multe da incenso, por ke li aldonu ĝin al la preĝoj de ĉiuj sanktuloj sur la altaro ora, kiu estis antaŭ la trono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'Kaj la fumo de la incenso, kun la preĝoj de la sanktuloj, leviĝis antaŭ Dio el la mano de la anĝelo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'Kaj la anĝelo prenis la incensilon, kaj li plenigis ĝin per la fajro de la altaro, kaj ĵetis ĝin sur la teron; kaj fariĝis tondroj kaj voĉoj kaj fulmoj kaj tertremo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'Kaj la sep anĝeloj, havantaj la sep trumpetojn, sin pretigis, por trumpeti.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'Kaj la unua trumpetis, kaj fariĝis hajlo kaj fajro, miksitaj kun sango, kaj ili estis ĵetitaj sur la teron; kaj triono de la tero forbrulis, kaj triono de la arboj forbrulis, kaj la tuta verda herbo forbrulis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'Kaj la dua anĝelo trumpetis, kaj kvazaŭ granda monto, per fajro brulanta, estis ĵetita en la maron; kaj triono de la maro fariĝis sango;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'kaj mortis triono de la kreitaĵoj en la maro, kiuj havis vivon; kaj triono de la ŝipoj pereis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'Kaj la tria anĝelo trumpetis, kaj falis el la ĉielo granda stelo, brulanta kiel torĉo, kaj ĝi falis sur trionon de la riveroj kaj sur la fontojn de la akvoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'kaj la nomo de la stelo estas Absinto; kaj triono de la akvoj fariĝis absintaĵo; kaj multe da homoj mortis de la akvoj, ĉar ili maldolĉiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'Kaj la kvara anĝelo trumpetis, kaj estis frapita triono de la suno kaj triono de la luno kaj triono de la steloj, por ke mallumiĝu triono de ili, kaj ke ne lumu dum triono de la tago, kaj por la nokto tiel same.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'Kaj mi rigardis, kaj mi aŭdis unu aglon, flugantan en meza ĉielo, dirantan per granda voĉo: Ve! ve! ve al la loĝantoj sur la tero, pro la ceteraj voĉoj trumpetaj de la tri anĝeloj ankoraŭ trumpetontaj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'Kaj la kvina anĝelo trumpetis, kaj mi vidis stelon el la ĉielo falintan sur la teron; kaj al li estis donita la ŝlosilo de la puto de la abismo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'Kaj li malfermis la puton de la abismo; kaj el la puto leviĝadis fumo, kiel fumo el granda forno; kaj mallumiĝis la suno kaj la aero pro la fumo de la puto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'Kaj el la fumo eliris akridoj sur la teron; kaj al ili estis donita povo, kiel havas povon la skorpioj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'Kaj estis ordonite al ili, ke ili ne difektu la herbon de la tero, nek ian verdaĵon, nek ian arbon, sed nur tiujn homojn, kiuj ne havas sur la frunto la sigelon de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'Kaj al ili estis komisiite, ke ili ne mortigu ilin, sed ke ili estu turmentataj kvin monatojn; kaj ilia turmento estis kiel turmento de skorpio, kiam ĝi pikvundas homon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'Kaj en tiuj tagoj la homoj serĉos morton, kaj ĝin tute ne trovos; kaj ili deziregos morti, kaj morto forflugos de ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'Kaj la formoj de la akridoj similis ĉevalojn, pretigitajn por milito; kaj sur iliaj kapoj estis kvazaŭ kronoj similaj al oro, kaj iliaj vizaĝoj estis kiel vizaĝoj de homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'Kaj ili havis harojn kiel haroj de virinoj, kaj iliaj dentoj estis kiel de leonoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'Kaj ili havis kirasojn, kiel kirasoj el fero; kaj la sono de iliaj flugiloj estis kiel la sono de ĉaroj, de multe da ĉevaloj kurantaj en militon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'Kaj ili havis vostojn similajn al vostoj de skorpioj, kaj pikilojn; kaj en iliaj vostoj estas ilia kapablo difekti la homojn kvin monatojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'Ili havis super si reĝon, la anĝelon de la abismo; lia nomo estas en la Hebrea lingvo Abadon, kaj en la Greka lingvo li havas la nomon Apolion.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'La unua Veo jam pasis; jen post tio venas ankoraŭ du Veoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'Kaj la sesa anĝelo trumpetis, kaj mi aŭdis voĉon el la kornoj de la ora altaro, kiu staras antaŭ Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'dirantan al la sesa anĝelo, kiu havis la trumpeton: Malligu la kvar anĝelojn, ligitajn apud la granda rivero Eŭfrato.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'Kaj malligiĝis la kvar anĝeloj, pretigitaj por la horo kaj tago kaj monato kaj jaro, por ke ili mortigu trionon de la homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'Kaj la nombro de la armeoj de la kavalerio estis ducent milionoj; mi aŭdis ilian nombron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'Kaj tiel mi vidis la ĉevalojn en la vizio, kaj la sidantajn sur ili, havantajn kirasojn kiel el fajro kaj el jacinto kaj el sulfuro; kaj la kapoj de la ĉevaloj estis kiel kapoj de leonoj, kaj el iliaj buŝoj eliris fajro kaj fumo kaj sulfuro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'Per tiuj tri plagoj triono de la homoj estis mortigita, per la fajro kaj la fumo kaj la sulfuro elirantaj el iliaj buŝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'Ĉar la kapablo de la ĉevaloj estas en iliaj buŝoj kaj en iliaj vostoj; ĉar iliaj vostoj similas serpentojn kaj havas kapojn; kaj per ĉi tiuj ili vundas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'Kaj la ceteraj homoj, kiuj ne estis mortigitaj per tiuj plagoj, ne pentis pri la faroj de siaj manoj, por ne adorkliniĝi al demonoj, kaj al la idoloj oraj kaj arĝentaj kaj kupraj kaj ŝtonaj kaj lignaj, kiuj povas nek vidi, nek aŭdi, nek marŝi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'kaj ili ne pentis pri siaj mortigoj, nek pri siaj sorĉoj, nek pri sia malĉastado, nek pri siaj ŝteloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'Kaj mi vidis alian fortan anĝelon, malsuprenirantan el la ĉielo, vestitan per nubo; kaj la ĉielarko estis super lia kapo, kaj lia vizaĝo estis kiel la suno, kaj liaj piedoj kiel kolonoj el fajro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'kaj li havis en la mano libreton malfermitan; kaj li metis la dekstran piedon sur la maron, kaj la maldekstran sur la teron;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'kaj li ekkriis per granda voĉo, kiel leono blekas; kaj kiam li kriis, la sep tondroj parolis per siaj voĉoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'Kaj kiam la sep tondroj parolis, mi volis skribi; kaj mi aŭdis voĉon el la ĉielo, dirantan: Sigelu tion, kion parolis la sep tondroj, kaj ĝin ne skribu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'Kaj la anĝelo, kiun mi vidis staranta sur la maro kaj sur la tero, levis sian dekstran manon al la ĉielo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'kaj ĵuris per la Vivanto por ĉiam kaj eterne, kiu kreis la ĉielon kaj tion, kio estas en ĝi, kaj la teron kaj tion, kio estas en ĝi, kaj la maron kaj tion, kio estas en ĝi, ke tempo ne plu ekzistos;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'sed en la tagoj de la voĉo de la sepa anĝelo, kiam li tuj trumpetos, tiam finiĝos la mistero de Dio, kiel Li evangeliis al Siaj servistoj, la profetoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'Kaj la voĉo, kiun mi aŭdis el la ĉielo, parolis al mi denove, dirante: Iru, prenu la libreton malfermitan en la mano de la anĝelo, staranta sur la maro kaj sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'Kaj mi iris al la anĝelo, kaj diris al li: Donu al mi la libreton. Kaj li diris al mi: Prenu ĝin, kaj formanĝu ĝin; kaj ĝi maldolĉigos al vi la ventron, sed en via buŝo ĝi estos dolĉa kiel mielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'Kaj mi prenis la libreton el la mano de la anĝelo, kaj formanĝis ĝin; kaj en mia buŝo ĝi estis dolĉa kiel mielo, kaj kiam mi ĝin manĝis, mia ventro maldolĉiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'Kaj ili diris al mi: Vi devas denove profeti ĉe multaj popoloj kaj nacioj kaj lingvoj kaj reĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'Kaj estis donita al mi kano, simila al bastono; kaj iu diris: Leviĝu, kaj mezuru la templon de Dio, kaj la altaron, kaj la adorantojn en ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Kaj la korton ekster la templo preterlasu, kaj ne mezuru ĝin, ĉar ĝi estas donita al la nacioj; kaj la sanktan urbon ili piedpremos kvardek du monatojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'Kaj mi donos komision al miaj du atestantoj, kaj ili profetos mil ducent sesdek tagojn, vestite per sakaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Ili estas la du olivarboj kaj la du lampingoj, starantaj antaŭ la Sinjoro de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'Kaj se iu volas difekti ilin, fajro elvenas el ilia buŝo kaj formanĝas iliajn malamikojn; kaj se iu volas difekti ilin, tiamaniere li devas esti mortigita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Ili havas la povon fermi la ĉielon, por ke ne pluvu dum la tagoj de ilia profetado; kaj ili havas povon super la akvoj, por ŝanĝi ilin en sangon, kaj frapi la teron per ĉia plago ĉiufoje, kiam ili volos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'Kaj kiam ili finos sian ateston, la besto, kiu suprenvenas el la abismo, faros militon kontraŭ ili kaj venkos ilin kaj mortigos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'Kaj iliaj kadavroj kuŝas sur la strato de la granda urbo, kiu nomiĝas laŭspirite Sodom kaj Egiptujo, kie ankaŭ ilia Sinjoro estis krucumita.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'Kaj el la popoloj kaj triboj kaj lingvoj kaj nacioj oni rigardas iliajn kadavrojn dum tri tagoj kaj duono, kaj ne lasas meti iliajn kadavrojn en tombon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'Kaj la loĝantoj sur la tero ĝojas pri ili, kaj gajiĝas; kaj ili sendos donacojn unu al la alia; ĉar tiuj du profetoj turmentadis la loĝantojn sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'Kaj post la tri tagoj kaj duono la spirito de vivo el Dio eniris en ilin, kaj ili stariĝis sur siaj piedoj; kaj granda timo falis sur tiujn, kiuj ilin rigardis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'Kaj ili aŭdis grandan voĉon el la ĉielo, dirantan al ili: Suprenvenu ĉi tien. Kaj ili supreniris en la ĉielon en la nubo; kaj iliaj malamikoj rigardis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'Kaj en tiu horo fariĝis granda tertremo, kaj dekono de la urbo falis; kaj en la tertremo mortis sep mil homoj; kaj la ceteraj pleniĝis de timo, kaj donis laŭdon al la Dio de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'La dua Veo jam pasis; jen la tria Veo rapide venas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'Kaj la sepa anĝelo trumpetis; kaj fariĝis grandaj voĉoj en la ĉielo, dirante: La regno de la mondo fariĝis regno de nia Sinjoro kaj de Lia Kristo; kaj li reĝos por ĉiam kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'Kaj la dudek kvar presbiteroj, kiuj antaŭ Dio sidas sur siaj tronoj, falis sur la vizaĝon kaj adorkliniĝis al Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'dirante: Ni dankas Vin, ho Dio, la Sinjoro, la Plejpotenca, kiu estas kaj estis; ĉar Vi alprenis Vian grandan potencon kaj reĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'Kaj la nacioj furiozis, kaj venis Via kolero, kaj la tempo de la mortintoj, por esti juĝataj, kaj la tempo doni la rekompencon al Viaj servistoj, la profetoj, kaj al la sanktuloj, kaj al la timantoj de Via nomo, malgrandaj kaj grandaj, kaj pereigi la detruantojn de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'Kaj malfermiĝis la enĉiela templo de Dio, kaj vidiĝis en Lia templo la kesto de Lia interligo; kaj fariĝis fulmoj kaj voĉoj kaj tondroj kaj tertremo kaj granda hajlo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'Kaj granda signo vidiĝis en la ĉielo: virino vestita per la suno, kaj la luno sub ŝiaj piedoj, kaj sur ŝia kapo krono el dek du steloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'kaj estante graveda, ŝi ekkriis, naskodolorigate kaj suferante por naski.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'Kaj vidiĝis alia signo en la ĉielo; kaj jen granda ruĝa drako, havanta sep kapojn kaj dek kornojn, kaj sur siaj kapoj sep diademojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'Kaj ĝia vosto trenis trionon de la steloj de la ĉielo, kaj ĵetis ilin sur la teron; kaj la drako staris antaŭ la virino naskonta, por ke, kiam ŝi estos naskinta, ĝi formanĝu ŝian infanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'Kaj ŝi naskis filon, viran infanon, kiu regos ĉiujn naciojn per fera sceptro; kaj ŝia infano estis forkaptita supren al Dio kaj al Lia trono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'Kaj la virino forkuris en la dezerton, kie ŝi havis lokon pretigitan de Dio, por ke tie oni nutru ŝin mil ducent sesdek tagojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'Kaj fariĝis milito en la ĉielo: Miĥael kaj liaj anĝeloj ekmilitis kontraŭ la drako; kaj militis la drako kaj ĝiaj anĝeloj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'kaj ne prosperis al ili, kaj ne plu troviĝis ilia loko en la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'Kaj ĵetiĝis malsupren la granda drako, la antikva serpento, nomata Diablo kaj Satano, la trompanto de la tuta mondo; ĝi ĵetiĝis sur la teron, kaj ĝiaj anĝeloj ĵetiĝis kun ĝi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'Kaj mi aŭdis grandan voĉon en la ĉielo, dirantan: Nun fariĝis la savo kaj la potenco kaj la reĝeco de nia Dio, kaj la aŭtoritato de Lia Kristo; ĉar ĵetiĝis malsupren la akuzanto de niaj fratoj, kiu tage kaj nokte akuzas ilin antaŭ nia Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'Kaj ili venkis ĝin pro la sango de la Ŝafido, kaj pro la vorto de sia atesto; kaj ili ne amis sian vivon ĝis morto mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'Pro tio ĝoju, ho ĉieloj, kaj vi, kiuj en ili loĝas. Ve al la tero kaj al la maro! ĉar la diablo malsupreniris en vin, havante grandan koleron, sciante, ke li havas nur mallongan tempon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'Kaj kiam la drako vidis, ke ĝi estas ĵetita sur la teron, ĝi persekutis la virinon, kiu naskis la viran infanon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'Kaj al la virino estis donitaj la du flugiloj de la granda aglo, por ke ŝi flugu en la dezerton, sur sian lokon, kie ŝi estas nutrata tempon kaj tempojn kaj duontempon, for de la vizaĝo de la serpento.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'Kaj la serpento elĵetis el sia buŝo, post la virinon, akvon kvazaŭ riveron, por ke ĝi igu ŝin forportiĝi de la fluo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'Kaj la tero helpis la virinon, kaj la tero malfermis sian buŝon, kaj englutis la riveron, kiun la drako elĵetis el sia buŝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'Kaj la drako furiozis kontraŭ la virino, kaj foriris, por fari militon kontraŭ la restintojn de ŝia idaro, kiuj observas la ordonojn de Dio kaj havas la ateston de Jesuo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'kaj ĝi staris sur la sablo de la maro. Kaj mi vidis beston suprenirantan el la maro, havantan dek kornojn kaj sep kapojn, kaj sur siaj kornoj dek diademojn, kaj sur siaj kapoj nomojn de blasfemo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'Kaj la besto, kiun mi vidis, estis simila al leopardo, kaj ĝiaj piedoj estis kiel de urso, kaj ĝia buŝo kiel buŝo de leono; kaj la drako donis al ĝi sian potencon kaj sian tronon kaj grandan aŭtoritaton.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'Kaj mi vidis unu el ĝiaj kapoj kvazaŭ morte vunditan; kaj la morta vundo saniĝis; kaj la tuta tero miris post la besto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'kaj ili adorkliniĝis al la drako, ĉar ĝi donis sian aŭtoritaton al la besto; kaj ili adorkliniĝis al la besto, dirante: Kiu estas simila al la besto? kaj kiu povas militi kontraŭ ĝi?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'kaj estis donita al ĝi buŝo, parolanta grandaĵojn kaj blasfemaĵojn; kaj estis donita al ĝi aŭtoritato agadi dum kvardek du monatoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'Kaj ĝi malfermis la buŝon por blasfemoj kontraŭ Dio, por blasfemi Lian nomon kaj Lian tabernaklon kaj la loĝantojn de la ĉielo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Kaj estis donite al ĝi fari militon kontraŭ la sanktuloj, kaj venki ilin; kaj estis donita al ĝi aŭtoritato sur ĉiu tribo kaj popolo kaj lingvo kaj nacio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'Kaj adorkliniĝos al ĝi ĉiuj loĝantoj de la tero, kies nomo ne estas skribita en la libro de vivo, libro de la Ŝafido oferita jam de la fondo de la mondo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Se iu havas orelon, tiu aŭskultu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Se iu malliberigas, en malliberecon li iras; se iu per la glavo mortigos, li devas per la glavo esti mortigita. Ĉi tie estas la pacienco kaj la fido de la sanktuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Kaj mi vidis alian beston suprenirantan el la tero; kaj ĝi havis du kornojn, simile al ŝafido, kaj ĝi parolis kiel drako.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'Kaj ĝi ekzercas la tutan aŭtoritaton de la unua besto antaŭ ĝi. Kaj ĝi devigas la teron kaj la loĝantojn sur ĝi adorkliniĝi al la unua besto, kies morta vundo saniĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'Kaj ĝi faras grandajn signojn, devigante eĉ fajron malsupreniri el la ĉielo sur la teron antaŭ la homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'Kaj ĝi trompas la loĝantojn de la tero per la signoj, kiujn estis donite al ĝi fari antaŭ la besto; dirante al la loĝantoj sur la tero, ke ili faru bildon al la besto, kiu havis la glavovundon kaj vivis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'Kaj estis donite, ke ĝi donu spiron al la bildo de la besto, por ke eĉ parolu la bildo de la besto, kaj faru, ke ĉiuj, kiuj ne volas adorkliniĝi al la bildo de la besto, estu mortigitaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'Kaj ĝi devigas ĉiujn, la malgrandajn kaj la grandajn, la riĉajn kaj la malriĉajn, la liberajn kaj la sklavajn, ricevi markon sur la dekstra mano aŭ sur la frunto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'por ke neniu povu aĉeti aŭ vendi, krom tiuj, kiuj havas la markon, la nomon de la besto, aŭ la numeron de ĝia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Ĉi tie estas saĝeco. Kiu havas prudenton, tiu kalkulu la numeron de la besto; ĉar ĝi estas la numero de homo; kaj ĝia numero estas sescent sesdek ses.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'Kaj mi rigardis, kaj jen la Ŝafido staranta sur la monto Cion, kaj kun li cent kvardek kvar miloj, havantaj lian nomon, kaj la nomon de lia Patro, skribitajn sur ilia frunto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'Kaj mi aŭdis voĉon el la ĉielo, kiel voĉon de multaj akvoj, kaj kiel voĉon de granda tondro; kaj la voĉo, kiun mi aŭdis, estis kiel de harpistoj, harpantaj per siaj harpoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'kaj ili kantas kvazaŭ novan kanton antaŭ la trono kaj antaŭ la kvar kreitaĵoj kaj la presbiteroj; kaj neniu povis lerni la kanton krom la cent kvardek kvar miloj, la elaĉetitoj el la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Ili estas tiuj, kiuj ne malpuriĝis kun virinoj; ĉar ili estas virguloj. Ili estas la sekvantoj de la Ŝafido, kien ajn li iras. Ili estas elaĉetitaj el inter la homoj, la unuaaĵo al Dio kaj al la Ŝafido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'Kaj en ilia buŝo ne troviĝis mensogo; ili estas senkulpaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'Kaj mi vidis alian anĝelon, flugantan en meza ĉielo, havantan eternan evangelion, por evangelii la loĝantojn de la tero kaj ĉiun nacion kaj tribon kaj lingvon kaj popolon,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'kaj dirantan per granda voĉo: Timu Dion, kaj donu al Li gloron, ĉar venis la horo de Lia juĝo; kaj adorkliniĝu al la Kreinto de la ĉielo kaj la tero kaj la maro kaj la fontoj akvaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'Kaj alia anĝelo, dua, sekvis, dirante: Falis, falis Babel la granda, kiu trinkigis ĉiujn naciojn el la vino de la kolero de ŝia malĉastaĵo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'Kaj alia anĝelo, tria, sekvis ilin, dirante per granda voĉo: Se iu adorkliniĝas al la besto kaj al ĝia bildo, kaj ricevas markon sur sia frunto aŭ sur sia mano,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'tiu ankaŭ trinkos el la vino de la kolero de Dio, kiu estas pretigita nemiksite en la pokalo de Lia kolero, kaj li turmentiĝos en fajro kaj sulfuro antaŭ la sanktaj anĝeloj kaj antaŭ la Ŝafido;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'kaj la fumo de ilia turmento leviĝas por ĉiam kaj eterne; kaj ne havas paŭzon tage kaj nokte tiuj, kiuj adorkliniĝas al la besto kaj al ĝia bildo, kaj ĉiu, kiu ricevas la markon de ĝia nomo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Ĉi tie estas la pacienco de la sanktuloj, kiuj observas la ordonojn de Dio kaj la fidon de Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'Kaj mi aŭdis voĉon el la ĉielo, dirantan: Skribu: Feliĉaj estas la mortintoj, kiuj de nun mortas en la Sinjoro; vere, diras la Spirito, por ke ili ripozu de siaj laboroj; ĉar iliaj faroj sekvas kun ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'Kaj mi rigardis, kaj jen blanka nubo, kaj sur la nubo sidanto, simila al la Filo de homo, havanta sur sia kapo oran kronon, kaj en sia mano akran rikoltilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'Kaj alia anĝelo eliris el la templo, kriante per granda voĉo al la sidanta sur la nubo: Sendu vian rikoltilon, kaj rikoltu; ĉar venis la horo por rikolti, ĉar la rikolto de la tero tromaturiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'Kaj la sidanta sur la nubo ĵetis sian rikoltilon sur la teron; kaj la tero rikoltiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'Kaj alia anĝelo eliris el la enĉiela templo, ankaŭ havante akran rikoltilon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'Kaj alia anĝelo eliris el la altaro, havante aŭtoritaton super la fajro; kaj li kriis per granda voĉo al la portanto de la akra rikoltilo, dirante: Sendu vian akran rikoltilon, kaj detranĉu la vinberarojn de la vinberarbo de la tero; ĉar tute maturiĝis ĝiaj vinberoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'Kaj la anĝelo ĵetis sian rikoltilon en la teron kaj detranĉis la vinberarbon de la tero kaj ĵetis ĝin en la grandan vinpremilon de la kolero de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'Kaj la vinpremilo estis tretita ekster la urbo, kaj eliris sango el la vinpremilo, ĝis la bridoj de la ĉevaloj, en la spaco de mil sescent stadioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Kaj mi vidis alian signon en la ĉielo, grandan kaj mirindan: sep anĝelojn havantajn sep plagojn, la finajn, ĉar en ili finiĝis la kolero de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'Kaj mi vidis kvazaŭ vitran maron, miksitan kun fajro; kaj tiujn, kiuj venkis la beston kaj ĝian bildon kaj la numeron de ĝia nomo; kaj ili staris sur la vitra maro, havante harpojn de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'Kaj ili kantis la kanton de Moseo, la servanto de Dio, kaj la kanton de la Ŝafido, dirante: Grandaj kaj mirindaj estas Viaj faroj, ho Dio, la Sinjoro, la Plejpotenca; justaj kaj veraj estas Viaj vojoj, ho Reĝo de la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Kiu ne timos, ho Sinjoro, kaj ne gloros Vian nomon? ĉar Vi sola estas sankta; ĉar ĉiuj nacioj venos kaj adorkliniĝos al Vi; ĉar Viaj justaĵoj elmontriĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'Kaj post tio mi rigardis, kaj malfermiĝis la templo de la tabernaklo de la atesto en la ĉielo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'kaj elvenis el la templo la sep anĝeloj, havante la sep plagojn, vestite per linaĵo pura kaj luma, kaj zonite ĉirkaŭ la brusto per ora zono.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'Kaj unu el la kvar kreitaĵoj donis al la sep anĝeloj sep orajn pelvojn, plenajn de la kolero de Dio, la vivanta por ĉiam kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'Kaj la templo pleniĝis de fumo el la gloro de Dio kaj el Lia potenco; kaj neniu povis eniri en la templon, ĝis finiĝos la sep plagoj de la sep anĝeloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'Kaj mi aŭdis grandan voĉon el la templo, dirantan al la sep anĝeloj: Iru, kaj elverŝu sur la teron la sep pelvojn de la kolero de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'Kaj la unua foriris, kaj elverŝis sian pelvon sur la teron; kaj fariĝis malbona kaj dolora ulcero sur la homoj, kiuj havis la markon de la besto kaj kiuj adorkliniĝis al ĝia bildo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'Kaj la dua elverŝis sian pelvon en la maron; kaj fariĝis sango, kiel de mortinto; kaj mortis ĉiu vivanta estaĵo en la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'Kaj la tria elverŝis sian pelvon en la riverojn kaj en la fontojn de akvoj; kaj fariĝis sango.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'Kaj mi aŭdis la anĝelon de la akvoj dirantan: Justa estas Vi, la estanta kaj estinta, la Sanktulo, ĉar Vi tiele juĝis;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'ĉar ili elverŝis la sangon de sanktuloj kaj profetoj, kaj sangon Vi donis al ili trinki; ili tion meritas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'Kaj mi aŭdis la altaron dirantan: Vere, ho Dio, la Sinjoro, la Plejpotenca, veraj kaj justaj estas Viaj juĝoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'Kaj la kvara elverŝis sian pelvon sur la sunon; kaj estis donite al ĝi brulvundi homojn per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'Kaj la homoj brulvundiĝis per granda varmego, kaj ili blasfemis la nomon de Dio, kiu havas aŭtoritaton sur tiuj plagoj; kaj ili ne pentis, por doni al Li gloron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'Kaj la kvina elverŝis sian pelvon sur la tronon de la besto; kaj ĝia regno mallumiĝis; kaj ili mordis sian langon pro dolorego,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'kaj ili blasfemis la Dion de la ĉielo pro siaj doloroj kaj siaj ulceroj; kaj ili ne pentis pri siaj faroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'Kaj la sesa elverŝis sian pelvon sur la grandan riveron, la riveron Eŭfrato; kaj ĝia akvo forsekiĝis, por ke pretiĝu la vojo de la reĝoj, kiuj venas el la sunleviĝejo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'Kaj mi vidis tri malpurajn spiritojn, kvazaŭ ranojn, elirantaj el la buŝo de la drako, kaj el la buŝo de la besto, kaj el la buŝo de la falsa profeto;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'ĉar ili estas spiritoj de demonoj, farantaj signojn; ili foriras al la reĝoj de la tuta mondo, por kolekti ilin por la milito de la granda tago de Dio, la Plejpotenca.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, '(Jen mi venas kvazaŭ ŝtelisto. Feliĉa estas tiu, kiu viglas kaj konservas siajn vestojn, por ke li ne iru nuda, kaj oni ne vidu lian honton.)');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'Kaj oni kolektis ilin en lokon, nomatan en la Hebrea lingvo Har- Magedon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'Kaj la sepa anĝelo elverŝis sian pelvon sur la aeron; kaj eliris granda voĉo el la templo, for de la trono, dirante: Fariĝis!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'kaj okazis fulmoj kaj voĉoj kaj tondroj; kaj okazis granda tertremo tia, kia ne okazis de kiam homoj estiĝis sur la tero, tiela tertremo, tiel granda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'Kaj la granda urbo disiĝis en tri partojn, kaj la urboj de la nacioj falis; kaj Babel la granda estis memorata antaŭ Dio, por doni al ĝi la pokalon de la vino de la furiozeco de Lia kolero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'Kaj ĉiu insulo forflugis, kaj la montoj ne troviĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'Kaj granda hajlo, peza kvazaŭ po talanto, falis el la ĉielo sur la homojn; kaj la homoj blasfemis Dion pro la plago de la hajlo; ĉar ĝia plago estas treege granda.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'Kaj unu el la sep anĝeloj, havantaj la sep pelvojn, venis kaj parolis kun mi, dirante: Venu ĉi tien, mi montros al vi la juĝon de la granda malĉastistino, kiu sidas sur multaj akvoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'kun kiu la reĝoj de la tero malĉastis, kaj la loĝantoj sur la tero ebriiĝis per la vino de ŝia malĉasteco.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'Kaj li forportis min en la Spirito en dezerton; kaj mi vidis virinon, sidantan sur skarlata besto, plena de nomoj de blasfemo, havanta sep kapojn kaj dek kornojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'Kaj la virino estis vestita per purpuro kaj skarlato, kaj ornamita per oro kaj altvaloraj ŝtonoj kaj perloj, kaj havis en sia mano oran pokalon, plenan de abomenindaĵoj kaj la malpuraĵoj de ŝia malĉasteco,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'kaj sur sia frunto nomon skribitan: MISTERO, BABEL LA GRANDA, LA PATRINO DE LA MALĈASTISTINOJ KAJ DE LA ABOMENINDAĴOJ DE LA TERO.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'Kaj mi vidis la virinon ebria de la sango de la sanktuloj, kaj de la sango de la martiroj de Jesuo. Kaj vidinte ŝin, mi miris per granda miro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'Kaj la anĝelo diris al mi: Kial vi miris? mi diros al vi la misteron de la virino, kaj de la besto, kiu portas ŝin kaj kiu havas la sep kapojn kaj la dek kornojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'La besto, kiun vi vidis, ekzistis, sed ne ekzistas, kaj venos supren el la abismo kaj iros en pereon. Kaj la loĝantoj sur la tero, kies nomoj ne estas skribitaj en la libro de vivo jam de la fondo de la mondo, miros, kiam ili vidos la beston, ke ĝi ekzistis kaj ne ekzistas, sed venos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Ĉi tie estas la signifo, kiu havas saĝecon: la sep kapoj estas sep montoj, sur kiuj sidas la virino;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'kaj ili estas sep reĝoj; la kvin jam falis, la unu estas, la alia ankoraŭ ne venis; kaj kiam li venos, li devos resti kelkan tempon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'Kaj la besto, kiu ekzistis kaj ne ekzistas, estas ankaŭ oka, kaj estas el la sep; kaj ĝi iras en pereon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'Kaj la dek kornoj, kiujn vi vidis, estas dek reĝoj, kiuj ankoraŭ ne ricevis regnon; sed ili ricevas aŭtoritaton kiel reĝoj, kun la besto, por unu horo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Tiuj havas unu intencon, kaj ili donas sian potencon kaj aŭtoritaton al la besto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Tiuj militos kontraŭ la Ŝafido, kaj la Ŝafido venkos ilin, ĉar li estas Sinjoro de sinjoroj, kaj Reĝo de reĝoj; kaj venkos tiuj, kiuj estas kun li, vokitaj kaj elektitaj kaj fidelaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'Kaj li diris al mi: La akvoj, kiujn vi vidis, kie sidas la malĉastistino, estas popoloj kaj homamasoj kaj nacioj kaj lingvoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'Kaj la dek kornoj, kiujn vi vidis, kaj la besto, malamos la malĉastistinon, kaj faros ŝin izolita kaj nuda, kaj manĝos ŝian karnon, kaj forbruligos ŝin per fajro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Ĉar Dio enmetis en ilian koron efektivigi Lian intencon, kaj efektivigi unu intencon, kaj doni sian regnon al la besto, ĝis la vortoj de Dio plenumiĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'Kaj la virino, kiun vi vidis, estas la granda urbo, kiu havas reĝecon super la reĝoj de la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Post tio mi vidis alian anĝelon, malsuprenirantan el la ĉielo, havantan grandan aŭtoritaton; kaj la tero lumiĝis per lia gloro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'Kaj li forte kriis per granda voĉo, dirante: Falis, falis Babel la granda, kaj fariĝis loĝejo de demonoj, kaj malliberejo de ĉia malpura spirito, kaj malliberejo de ĉia malpura kaj malaminda birdo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'Ĉar per la vino de la kolero de ŝia malĉasteco falis ĉiuj nacioj; kaj la reĝoj de la tero malĉastis kun ŝi, kaj la komercistoj de la tero riĉiĝis per la potenco de ŝia lukso.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'Kaj mi aŭdis alian voĉon el la ĉielo, dirantan: Elvenu el ŝi, ho Mia popolo, por ke vi ne partoprenu en ŝiaj pekoj, kaj por ke vi ne ricevu el ŝiaj plagoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'ĉar ŝiaj pekoj amasiĝis ĝis la ĉielo, kaj Dio memoris ŝiajn maljustaĵojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Redonu al ŝi, ĝuste kiel ŝi donis, kaj duobligu duoble laŭ ŝiaj faroj; en la pokalo, kiun ŝi miksis, miksu al ŝi duoblon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'Kiom ŝi gloris sin kaj voluptis, tiom donu al ŝi da turmento kaj funebro; ĉar ŝi diras en sia koro: Mi sidas reĝino, kaj mi ne estas vidvino, kaj mi tute ne vidos funebron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'Tial en unu tago venos ŝiaj plagoj, morto kaj funebro kaj malsatego; kaj ŝi forbrulos per fajro; ĉar forta estas Dio, la Sinjoro, kiu ŝin juĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'Kaj la reĝoj de la tero, kiuj malĉastis kun ŝi kaj voluptis, ploros kaj ĝemos pri ŝi, kiam ili rigardos la fumon de ŝia brulado,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'starante malproksime pro timo de ŝia turmento, dirante: Ve! ve, la granda urbo, Babel, la forta urbo! ĉar en unu horo venis via juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'Kaj la komercistoj de la tero ploras kaj lamentas pri ŝi, ĉar jam neniu aĉetas ilian komercaĵon;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'komercaĵon el oro kaj arĝento kaj altvaloraj ŝtonoj kaj perloj kaj bisino kaj purpuro kaj silko kaj skarlato, kaj ĉia parfuma ligno kaj ĉia vazo ebura kaj ĉia vazo el plej altvalora ligno kaj el kupro kaj fero kaj marmoro,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'kaj cinamo kaj amomo kaj incenso kaj ŝmiraĵo kaj olibano kaj vino kaj oleo kaj faruno kaj tritiko kaj brutoj kaj ŝafoj, kaj el ĉevaloj kaj ĉaroj, kaj korpoj kaj animoj de homoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'Kaj la fruktaro de la deziroj de via animo malaperis for de vi, kaj ĉio bongusta kaj brila pereis for de vi, kaj oni ne plu trovos ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'La negocintoj de tiuj komercaĵoj, kiuj riĉiĝis per ŝi, malproksime staros pro la timo de ŝia turmento, plorante kaj lamentante,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'kaj dirante: Ve! ve, la granda urbo, la vestita per bisino kaj purpuro kaj skarlato, kaj ornamita per oro kaj altvaloraj ŝtonoj kaj perloj!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'ĉar en unu horo pereis tiom da riĉeco. Kaj ĉiu ŝipestro, kaj ĉiu ien ŝipe veturanta, kaj maristoj, kaj ĉiuj, kiuj sur la maro laboris, staris malproksime,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'kaj kriis, vidante la fumon de ŝia brulego, dirante: Kio similas la grandan urbon?');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'Kaj ili ĵetis polvon sur siajn kapojn, kaj kriis, plorante kaj lamentante, kaj dirante: Ve! ve, la granda urbo! en kiu riĉiĝis ĉiuj, kiuj havis siajn ŝipojn sur la maro per ŝia luksego! ĉar en unu horo ŝi dezertiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Ĝojegu super ŝi, ho ĉielo, kaj la sanktuloj, kaj la apostoloj, kaj la profetoj; ĉar Dio decidis pri ŝi laŭ via juĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'Kaj forta anĝelo prenis ŝtonon, kvazaŭ grandan muelŝtonon, kaj ĵetis ĝin en la maron, dirante: Tiel per puŝego deĵetiĝos Babel, la granda urbo, kaj jam ne plu troviĝos.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'Kaj voĉo de harpistoj kaj muzikistoj kaj flutistoj kaj trumpetistoj jam ne plu aŭdiĝos en vi; kaj ĉia metiisto de ĉia metio jam ne plu troviĝos en vi; kaj sono de muelŝtono jam ne plu aŭdiĝos en vi;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'kaj lumo de lampo jam ne plu brilos en vi; kaj voĉo de fianĉo kaj fianĉino jam ne plu aŭdiĝos en vi; ĉar viaj komercistoj estis la granduloj de la tero; ĉar per via sorĉado ĉiuj nacioj trompiĝis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'Kaj en ŝi troviĝis la sango de profetoj kaj sanktuloj, kaj de ĉiuj mortigitoj sur la tero.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Post tio mi aŭdis kvazaŭ grandan voĉon de granda homamaso en la ĉielo, dirantan: Haleluja! La savo kaj la gloro kaj la potenco apartenas al nia Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'ĉar veraj kaj justaj estas Liaj juĝoj; ĉar Li juĝis la grandan malĉastistinon, kiu infektis la teron per sia malĉasteco, kaj Li venĝis la sangon de Siaj servistoj el ŝia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'Kaj duan fojon ili diris: Haleluja! Kaj ŝia fumo leviĝas por ĉiam kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'Kaj la dudek kvar presbiteroj kaj la kvar kreitaĵoj falis kaj adorkliniĝis al Dio, la sidanta sur la trono, dirante: Amen, Haleluja!');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'Kaj el la trono eliris voĉo, dirante: Laŭdu nian Dion, ĉiuj Liaj servistoj, vi, kiuj timas Lin, la malgrandaj kaj la grandaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'Kaj mi aŭdis kvazaŭ voĉon de granda homamaso kaj kvazaŭ voĉon de multaj akvoj kaj kvazaŭ voĉon de fortaj tondroj, dirantajn: Haleluja! ĉar la Sinjoro, nia Dio, la Plejpotenca, reĝas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Ni ĝoju kaj triumfu, kaj donu al Li la gloron; ĉar venis la edziĝo de la Ŝafido, kaj lia edzino sin pretigis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'Kaj estis donite al ŝi, ke ŝi sin vestu per bisino luma kaj pura; ĉar la bisino estas la justaĵoj de la sanktuloj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'Kaj li diris al mi: Skribu: Feliĉaj estas la invititaj al la edziĝa festeno de la Ŝafido. Kaj li diris al mi: Tio estas la veraj vortoj de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'Kaj mi falis antaŭ liaj piedoj, por adorkliniĝi al li. Kaj li diris al mi: Gardu vin, ke vi tion ne faru; mi estas kunservisto kun vi kaj kun viaj fratoj, kiuj konservas la ateston de Jesuo; adorkliniĝu al Dio; ĉar la atesto de Jesuo estas la spirito de profetado.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'Kaj mi vidis la ĉielon malfermitan; kaj jen blanka ĉevalo, kaj la sidanta sur ĝi, nomata Fidela kaj Vera; en justeco li juĝas kaj militas.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Kaj liaj okuloj estas fajra flamo, kaj sur lia kapo estas multaj diademoj; kaj li havas nomon skribitan, kiun konas neniu krom li mem.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'Kaj li estas vestita per vesto, trempita en sangon; kaj lia nomo estas: La Vorto de Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'Kaj la armeoj en la ĉielo sekvis lin sur blankaj ĉevaloj, vestite per bisino blanka kaj pura.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'Kaj el lia buŝo eliras akra glavo, por ke li per ĝi frapu la naciojn; kaj li regos ilin per fera sceptro; kaj li tretas la vinpremilon de la furiozeco de la kolero de Dio, la Plejpotenca.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'Kaj li havas sur la vesto kaj sur la femuro nomon skribitan: REĜO DE REĜOJ KAJ SINJORO DE SINJOROJ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'Kaj mi vidis unu anĝelon, starantan en la suno; kaj li ekkriis per granda voĉo, dirante al ĉiuj birdoj, kiuj flugas en meza ĉielo: Venu, kolektiĝu al la granda festeno de Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'por ke vi manĝu karnon de reĝoj kaj karnon de milestroj kaj karnon de fortuloj kaj karnon de ĉevaloj kaj de iliaj rajdantoj, kaj karnon de ĉiuj homoj, liberaj kaj sklavaj, grandaj kaj malgrandaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'Kaj mi vidis la beston, kaj la reĝojn de la tero kaj iliajn armeojn, kunigitajn, por fari militon kontraŭ la sidanta sur la ĉevalo kaj kontraŭ lia armeo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'Kaj la besto estis kaptita, kaj kun ĝi la falsa profeto, kiu faris antaŭ ĝi la signojn, per kiuj li trompis tiujn, kiuj ricevis la markon de la besto kaj adorkliniĝis al ĝia bildo; ili ambaŭ estis ĵetitaj vivaj en la lagon fajran, brulantan per sulfuro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'kaj la ceteraj estis mortigitaj per la glavo de la sidanta sur la ĉevalo, la glavo, kiu eliris el lia buŝo; kaj ĉiuj birdoj satiĝis per ilia karno.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'Kaj mi vidis anĝelon malsuprenirantan el la ĉielo, havantan la ŝlosilon de la abismo kaj grandan katenon en sia mano.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'Kaj li ekkaptis la drakon, la antikvan serpenton, kiu estas la Diablo kaj Satano, kaj enkatenis lin por mil jaroj,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'kaj ĵetis lin en la abismon kaj fermis ĝin kaj sigelis ĝin super li, por ke li ne plu trompu la naciojn, ĝis finiĝos la mil jaroj; post tio li devos esti malligita por kelka tempo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'Kaj mi vidis tronojn, kaj oni sidis sur ili, kaj juĝo estis donita al ili; kaj mi vidis la animojn de la senkapigitaj pro la atesto de Jesuo kaj pro la vorto de Dio, kaj tiujn, kiuj ne adorkliniĝis al la besto, nek al ĝia bildo, kaj ne ricevis la markon sur sia frunto kaj sur sia mano; kaj ili vivis, kaj ili reĝis kun Kristo mil jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'La ceteraj mortintoj ne vivis, ĝis finiĝos la mil jaroj. Tio estas la unua releviĝo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Feliĉa kaj sankta estas la partoprenanto en la unua releviĝo; super tiuj la dua morto havas nenian aŭtoritaton; sed ili estos pastroj de Dio kaj de Kristo, kaj reĝos kun li mil jarojn.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'Kaj kiam finiĝos la mil jaroj, Satano estos ellasita el sia malliberejo,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'kaj eliros, por trompi la naciojn en la kvar anguloj de la tero, Gog kaj Magog, por kolekti ilin por la milito; ilia nombro estas kiel la sablo de la maro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'Kaj ili supreniris laŭlarĝe de la tero kaj ĉirkaŭis la tendaron de la sanktuloj kaj la amatan urbon; kaj fajro malsupreniris el la ĉielo, kaj ekstermis ilin.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'Kaj la diablo, kiu trompis ilin, estis ĵetita en la lagon fajran kaj sulfuran, kie troviĝas la besto kaj la falsa profeto; kaj ili estos turmentataj tage kaj nokte por ĉiam kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'Kaj mi vidis grandan blankan tronon, kaj la Sidanton sur ĝi, antaŭ kies vizaĝo forflugis la tero kaj la ĉielo; kaj ne troviĝis loko por ili.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'Kaj mi vidis la mortintojn, grandajn kaj malgrandajn, starantajn antaŭ la trono; kaj libroj estis malfermitaj; kaj estis malfermita alia libro, kiu estas la libro de vivo; kaj la mortintoj estis juĝataj el la skribitaĵoj en la libroj, laŭ siaj faroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'Kaj la maro liveris la mortintojn, kiuj estis en ĝi; kaj la morto kaj Hades liveris la mortintojn, kiuj estis en ili; kaj ĉiu estis juĝata laŭ siaj faroj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'Kaj la morto kaj Hades estis ĵetitaj en la fajran lagon. Tio estas la dua morto-la fajra lago.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'Kaj se iu ne troviĝis skribita en la libro de vivo, tiu estis ĵetita en la fajran lagon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Kaj mi vidis novan ĉielon kaj novan teron; ĉar la unua ĉielo kaj la unua tero forpasis; kaj la maro jam ne ekzistis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'Kaj mi vidis la sanktan urbon, novan Jerusalemon, malsuprenirantan el la ĉielo for de Dio, pretigitan kiel fianĉino, ornamita por sia edzo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'Kaj mi aŭdis grandan voĉon el la trono, dirantan: Jen la tabernaklo de Dio estas kun la homoj, kaj Li loĝos kun ili, kaj ili estos Liaj popoloj, kaj Dio mem estos kun ili kaj estos ilia Dio;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'kaj Li forviŝos ĉiun larmon el iliaj okuloj; kaj la morto jam ne ekzistos; ne plu ekzistos funebro, nek plorado, nek doloro; la unuaj aferoj forpasis.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'Kaj diris la Sidanto sur la trono: Vidu, Mi faras ĉion nova. Kaj Li diris: Skribu, ĉar tiuj vortoj estas fidelaj kaj veraj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'Kaj Li diris al mi: Ĉio fariĝis. Mi estas la Alfa kaj la Omega, la komenco kaj la fino. Mi donos donace al la soifanto el la fonto de la akvo de vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'La venkanto heredos ĉion; kaj Mi estos por li Dio, kaj li estos por Mi filo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Sed por la timemaj kaj nekredemaj kaj abomenindaj kaj mortigistoj kaj malĉastuloj kaj sorĉistoj kaj idolanoj kaj ĉiuj mensoguloj, ilia lotaĵo estos en la lago, brulanta per fajro kaj sulfuro; tio estas la dua morto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'Kaj venis unu el la sep anĝeloj, havantaj la sep pelvojn, plenajn de la sep finaj plagoj; kaj li parolis kun mi, dirante: Venu ĉi tien, mi montros al vi la fianĉinon, la edzinon de la Ŝafido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'Kaj li forportis min en la Spirito sur monton, grandan kaj altan, kaj li montris al mi la sanktan urbon Jerusalem, malsuprenirantan el la ĉielo for de Dio,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'havantan la gloron de Dio; ĝia lumo estis simila al ŝtono plej altvalora, kvazaŭ jaspiso kristaleca;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'kun muro granda kaj alta, kun dek du pordegoj, kaj apud la pordegoj dek du anĝeloj; kaj nomoj surskribitaj, kiuj estas la nomoj de la dek du triboj de la Izraelidoj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'oriente estis tri pordegoj, kaj norde tri pordegoj, kaj sude tri pordegoj, kaj okcidente tri pordegoj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'Kaj la muro de la urbo havis dek du fundamentojn, kaj sur ili dek du nomojn de la dek du apostoloj de la Ŝafido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'Kaj mia kunparolanto havis mezurilon, oran vergon, por mezuri la urbon kaj ĝiajn pordegojn kaj ĝian muron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'Kaj la urbo staras kvadrate, kaj ĝia longo estas tiom, kiom la larĝo; kaj li mezuris la urbon per la vergo, dek du mil stadiojn; ĝia longo kaj ĝia larĝo kaj ĝia alto estas egalaj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'Kaj li mezuris ĝian muron, cent kvardek kvar ulnojn, laŭ mezuro de homo, tio estas, de anĝelo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'Kaj la strukturo de ĝia muro estis jaspiso; kaj la urbo estis pura oro, simila al pura vitro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'La fundamentoj de la muro de la urbo estis ornamitaj per altvaloraj ŝtonoj ĉiuspecaj. La unua fundamento estis jaspiso; la dua, safiro; la tria, kalcedonio; la kvara, smeraldo;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'la kvina, sardonikso; la sesa, sardio; la sepa, krizolito; la oka, berilo; la naŭa, topazo; la deka, krizopraso; la dek-unua, jacinto; la dek- dua, ametisto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'Kaj la dek du pordegoj estis dek du perloj, ĉiu el la pordegoj estis el unu perlo; kaj la strato de la urbo estis pura oro, kvazaŭ travidebla vitro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Kaj templon en ĝi mi ne vidis; ĉar Dio, la Sinjoro, la Plejpotenca, kaj la Ŝafido estas ĝia templo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'Kaj la urbo ne bezonas la sunon, nek la lunon, por brili al ĝi; ĉar la gloro de Dio lumis al ĝi, kaj ĝia lampo estas la Ŝafido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'Kaj la nacioj promenos per ĝia lumo; kaj la reĝoj de la tero alportas en ĝin sian gloron.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'Kaj ĝiaj pordegoj tute ne estos fermitaj tage (ĉar nokto ne ekzistos tie);');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'kaj ili alportos en ĝin la gloron kaj la honoron de la nacioj;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'kaj tute ne eniros en ĝin io malpura, nek faranto de abomenindaĵo kaj mensogo; sed nur la skribitaj en la libro de vivo de la Ŝafido.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'Kaj li montris al mi riveron de akvo de vivo, helan kiel kristalo, elirantan el la trono de Dio kaj de la Ŝafido,');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'meze de ĝia strato. Kaj ĉe ĉiu flanko de la rivero estis arbo de vivo, portanta dek du fruktojn, liveranta sian frukton ĉiumonate; kaj la folioj de la arbo estis por la resanigo de la nacioj.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'Kaj ne plu ekzistos malbeno; kaj en ĝi estos la trono de Dio kaj de la Ŝafido; kaj Liaj servistoj Lin adoros;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'kaj ili vidos Lian vizaĝon; kaj Lia nomo estos sur ilia frunto.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'Kaj nokto ne plu ekzistos; kaj ili ne bezonas lumon de lampo, nek lumon de suno; ĉar Dio, la Sinjoro, lumos al ili; kaj ili reĝos por ĉiam kaj eterne.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'Kaj li diris al mi: Tiuj vortoj estas fidelaj kaj veraj; kaj la Sinjoro, la Dio de la spiritoj de la profetoj, sendis Sian anĝelon, por montri al Siaj servistoj tion, kio devas okazi baldaŭ.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'Kaj jen mi rapide venos. Feliĉa estas tiu, kiu observas la vortojn de la profetaĵo de ĉi tiu libro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'Kaj mi, Johano, estis la aŭdanto kaj la vidanto de ĉi tio. Kaj kiam mi aŭdis kaj vidis, mi falis, por adorkliniĝi antaŭ la piedoj de la anĝelo, kiu montris tion al mi.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Kaj li diris al mi: Gardu vin, ke vi tion ne faru; mi estas kunservisto kun vi kaj kun viaj fratoj, la profetoj, kaj kun la observantoj de la vortoj de ĉi tiu libro; adorkliniĝu al Dio.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Kaj li diris al mi: Ne sigelu la vortojn de la profetaĵo de ĉi tiu libro; ĉar la tempo estas proksima.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'La maljustulo ankoraŭ estu maljusta; kaj la malpurulo ankoraŭ estu malpura; kaj la justulo ankoraŭ faru juston; kaj la sanktulo ankoraŭ sanktiĝu.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'Jen mi rapide venos; kaj mia rekompenco estas kun mi, por repagi al ĉiu laŭ lia faro.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Mi estas la Alfa kaj la Omega, la unua kaj la lasta, la komenco kaj la fino.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Feliĉaj estas tiuj, kiuj lavas siajn robojn, por ke ili havu rajton sur la arbo de vivo, kaj ke ili eniru tra la pordegoj en la urbon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Ekstere estas la hundoj kaj la sorĉistoj kaj la malĉastuloj kaj la mortigistoj kaj la idolanoj, kaj ĉiu, kiu amas kaj faras mensogon.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Mi, Jesuo, sendis mian anĝelon, por atesti al vi ĉi tion por la eklezioj. Mi estas la markoto kaj ido de David, la hela, la matena stelo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'Kaj la Spirito kaj la fianĉino diras: Venu. Kaj la aŭdanto diru: Venu. Kaj la soifanto venu; kiu volas, tiu prenu donace la akvon de vivo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Mi atestas al ĉiu, kiu aŭdas la vortojn de la profetaĵo de ĉi tiu libro: Se iu aldonos al ili, Dio aldonos al li la plagojn, skribitajn en ĉi tiu libro;');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'kaj se iu forprenos el la vortoj de la libro de ĉi tiu profetaĵo, skribitaj en ĉi tiu libro, Dio forprenos lian lotaĵon el la arbo de vivo kaj el la sankta urbo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'La atestanto de tio diras: Vere, mi rapide venos. Amen; venu, Sinjoro Jesuo.');
INSERT INTO `Esperanto_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'La graco de la Sinjoro Jesuo estu kun ĉiuj sanktuloj. Amen.');
